          GUID = "190FBDDA",
          NextDialogue = 10011002,
          SpeakNpcId = 100003,
          Subtitle = "More Filthoids are coming...",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBDDA"
        },
        [10011002] = {
          ContentES = "{nickname}, no te alejes de mí. Si es necesario, usaremos nuestras señales secretas.",
          DialogueId = 10011002,
          GUID = "190FBE04",
          NextDialogue = 10011003,
          SpeakNpcId = 100003,
          Subtitle = "Stay close, . If necessary, give out the secret signals.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE04"
        },
        [10011003] = {
          ContentES = "¿Lo recuerdas, verdad? Los inventamos antes para no alertar a los Filthoids en la montaña.",
          DialogueId = 10011003,
          GUID = "190FBE05",
          NextDialogue = 10011004,
          SpeakNpcId = 100003,
          Subtitle = "We made them up earlier so as not to alert the Filthoids up the mountain, remember?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE05"
        },
        [10011004] = {
          ContentES = "Por supuesto.",
          DialogueId = 10011004,
          ExStoryInfo = "Player",
          GUID = "190FBE06",
          NextDialogue = 10011005,
          SpeakNpcId = 100001,
          Subtitle = "Yes.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE06"
        },
        [10011005] = {
          ContentES = "Bien, una comprobación rápida: ¿Dos golpecitos en el hombro derecho significan...?",
          DialogueId = 10011005,
          GUID = "190FBE07",
          NextDialogue = 10011006,
          SpeakNpcId = 100003,
          Subtitle = "Alright, a quick check — Two pats on the right shoulder means...?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE07"
        },
        [10011006] = {
          ContentES = "“Cuidado con tu espalda.”",
          DialogueId = 10011006,
          ExStoryInfo = "Player",
          GUID = "190FBE08",
          NextDialogue = 10011007,
          SpeakNpcId = 100001,
          Subtitle = "\"Watch your back.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE08"
        },
        [10011007] = {
          ContentES = "¿Y dos golpecitos en el pecho?",
          DialogueId = 10011007,
          GUID = "190FBE09",
          NextDialogue = 10011008,
          SpeakNpcId = 100003,
          Subtitle = "And two taps on the chest?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE09"
        },
        [10011008] = {
          ContentES = "“Acércate.”",
          DialogueId = 10011008,
          ExStoryInfo = "Player",
          GUID = "190FBEA0",
          NextDialogue = 10011009,
          SpeakNpcId = 100001,
          Subtitle = "\"Come closer.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA0"
        },
        [10011009] = {
          ContentES = "¿Y un ligero roce en la nariz?",
          DialogueId = 10011009,
          GUID = "190FBEA1",
          NextDialogue = 10011010,
          SpeakNpcId = 100003,
          Subtitle = "And scraping on the nose?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA1"
        },
        [10011010] = {
          ContentES = "“Todo está bien ahora.”",
          DialogueId = 10011010,
          ExStoryInfo = "Player",
          GUID = "190FBEA2",
          NextDialogue = 10011011,
          SpeakNpcId = 100001,
          Subtitle = "\"Everything's okay now.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA2"
        },
        [10011011] = {
          ContentES = "Perfecto. El último, ¿tres parpadeos rápidos?",
          DialogueId = 10011011,
          GUID = "190FBEA3",
          NextDialogue = 10011012,
          SpeakNpcId = 100003,
          Subtitle = "Good. And the last one — three quick blinks?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA3"
        },
        [10011012] = {
          ContentES = "...Lo olvidé.",
          DialogueId = 10011012,
          ExStoryInfo = "Player",
          GUID = "190FBEA4",
          NextDialogue = 10011013,
          SpeakNpcId = 100001,
          Subtitle = "...I forgot it.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA4"
        },
        [10011013] = {
          ContentES = "Recuerda, tres parpadeos rápidos significa—",
          DialogueId = 10011013,
          GUID = "190FBEA5",
          NextDialogue = 10011014,
          SpeakNpcId = 100003,
          Subtitle = "Remember, three quick blinks means—",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA5"
        },
        [10011014] = {
          ContentES = "...No me interesa esa señal, y de todas formas no la recordaré.",
          DialogueId = 10011014,
          ExStoryInfo = "Player",
          GUID = "190FBEA6",
          NextDialogue = 10011015,
          SpeakNpcId = 100001,
          Subtitle = "...I'm not interested in that signal, and I won't remember it anyway.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA6"
        },
        [10011015] = {
          ContentES = "...",
          DialogueId = 10011015,
          GUID = "190FBEA7",
          SpeakNpcId = 100003,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA7"
        },
        [10011101] = {
          ContentES = "¿Es... un templo?",
          DialogueId = 10011101,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190FCE42",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001
          },
          SpeakNpcId = 100001,
          Subtitle = "Is this place... a temple?",
          VoiceName = "voice/$Locale$/story/1001/100111/190FCE42"
        },
        [10011102] = {
          ContentES = "... Sí.",
          DialogueId = 10011102,
          DisableMouth = 1,
          Duration = 0.5,
          GUID = "190FCE6C",
          SpeakNpcId = 100003,
          Subtitle = "...Yes.",
          VoiceName = "voice/$Locale$/story/1001/100111/190FCE6C"
        },
        [10011103] = {
          ContentES = "En el pasado, alguien dejó aquí este barco capaz de volar.",
          DialogueId = 10011103,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190FCE96",
          SpeakNpcId = 100003,
          Subtitle = "Someone once left that flying ship here.",
