        },
        [10011104] = {
          ContentES = "Y también... una “llave”.",
          DialogueId = 10011104,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "190FCEC0",
          SpeakNpcId = 100003,
          Subtitle = "And... a \"key.\"",
          VoiceName = "voice/$Locale$/story/1001/100111/190FCEC0"
        },
        [10011201] = {
          ContentES = "Escucha, clava la espada que llevas, aquí.",
          DefaultLookAt = "KeepState",
          DialogueId = 10011201,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190FDEAA",
          LookAt = {
            [1] = "100003:n(100001)"
          },
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001
          },
          SpeakNpcId = 100003,
          Subtitle = "Listen, thrust your sword right in there.",
