            [1] = "100001:n(100003)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Like this?",
          VoiceName = "voice/$Locale$/story/1001/100112/190FDED4"
        },
        [10011301] = {
          ContentES = "¿La llave... es esta espada?",
          DialogueId = 10011301,
          ExStoryInfo = "Player",
          GUID = "190FEF12",
          NextDialogue = 10011302,
          SpeakNpcId = 100001,
          Subtitle = "So the key is... this sword?",
          VoiceName = "voice/$Locale$/story/1001/100113/190FEF12"
        },
        [10011302] = {
          ContentES = "Sí. Tu espada nunca estuvo destinada a hacer daño.",
          DialogueId = 10011302,
          GUID = "190FEF13",
          SpeakNpcId = 100003,
          Subtitle = "Yes. Your sword was never meant to hurt.",
          VoiceName = "voice/$Locale$/story/1001/100113/190FEF13"
        },
        [10011401] = {
          ContentES = "Vamos hacia la cima de la montaña. Solía haber un dirigible allí. Si aún está, tal vez podamos salir.",
          DialogueId = 10011401,
          Duration = 4.5,
          GUID = "190FFFA4",
          SpeakNpcId = 100003,
          Subtitle = "Let's head towards the top of the mountain. There used to be an airship there. If it's still around, we might be able to make it out.",
          VoiceName = "voice/$Locale$/story/1001/100114/190FFFA4"
        },
        [10011501] = {
          Content = "那就是……你说的飞艇？",
          DialogueId = 10011501,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19100FE2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100115/19100FE2"
        },
        [10011502] = {
          Content = "还有人在那里……我们得救了吗？",
          DialogueId = 10011502,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "1910100C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100115/1910100C"
        },
        [10011601] = {
          ContentES = "Llevamos años buscando... La comandante debería abandonar esta maldita caza, ¿no?",
          DialogueId = 10011601,
          Duration = 3.5,
          GUID = "1910204A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "We've been searching for years. When will the Chief give up this pointless hunt?",
          VoiceName = "voice/$Locale$/story/1001/100116/1910204A"
        },
        [10011602] = {
          ContentES = "¿Quién está ahí?",
          DialogueId = 10011602,
          Duration = 1.5,
          GUID = "19102074",
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "Who's there?!",
          VoiceName = "voice/$Locale$/story/1001/100116/19102074"
        },
        [10011603] = {
          ContentES = "¡Dejen sus armas!",
          DialogueId = 10011603,
          Duration = 0.9,
          GUID = "19102075",
          SpeakNpcName = "UI_Npc_Name_Man_3",
          Subtitle = "Lay down your arms—",
