          SpeakNpcId = 100005,
          Subtitle = "Is this your idea of \"accurate intel,\" Randy? You gave me your word.",
          VoiceName = "voice/$Locale$/story/1001/100117/191030B2"
        },
        [10011702] = {
          Camera = "112.41748,326.53125,131.15976,0.001058,1.609964,-59.853107,35.0,100000.0,true,DoNotOverride,2.8",
          ContentES = "Los soldados hicieron lo mejor que pudieron. Los Filthoids que pululan en la isla, eso no se podía prever. Pero encontramos algo valioso en esta isla hoy...",
          DialogueId = 10011702,
          DisableMouth = 1,
          Duration = 7.6,
          GUID = "191030DC",
          SpeakNpcId = 100006,
          Subtitle = "The soldiers did their best with the Filthoids. These are indeed unforeseen circumstances.\nBut we did find something valuable on this island today—",
          VoiceName = "voice/$Locale$/story/1001/100117/191030DC"
        },
        [10011703] = {
          ContentES = "Herramientas alquímicas que ha usado y un dirigible con un número de serie de la Legión.",
          DialogueId = 10011703,
          DisableMouth = 1,
          Duration = 5.4,
          GUID = "19103106",
          SpeakNpcId = 100006,
          Subtitle = "Alchemical tools she has used and an airship with a Legion serial number on it.",
          VoiceName = "voice/$Locale$/story/1001/100117/19103106"
        },
        [10011704] = {
          Camera = "126.422852,269.644531,140.342804,0.001063,-0.790492,125.942245,35.0,100000.0,true,DoNotOverride,2.8",
          ContentES = "Te das cuenta de que estamos buscando el “N.º 0”, no esta chatarra inútil, ¿verdad?",
          DialogueId = 10011704,
          DisableMouth = 1,
          Duration = 3,
          GUID = "19103130",
          SpeakNpcId = 100005,
          Subtitle = "You realise we're looking for \"No. 0,\" not this useless junk, right?",
          VoiceName = "voice/$Locale$/story/1001/100117/19103130"
        },
        [10011705] = {
          ContentES = "Hemos estado buscando durante más de una década... Pero nuestra unidad marítima interceptó varios de los barcos de los aldeanos. Podrían ser capaces de encontrar algo...",
          DialogueId = 10011705,
          DisableMouth = 1,
          Duration = 9.5,
          GUID = "1910315A",
          SpeakNpcId = 100006,
          Subtitle = "We've been searching for over a decade... But our maritime unit intercepted several of the villagers' vessels.\nThey might be able to dig up some—",
          VoiceName = "voice/$Locale$/story/1001/100117/1910315A"
        },
        [10011706] = {
          ContentES = "¿Fueron disparos?",
          DialogueId = 10011706,
          DisableMouth = 1,
          Duration = 1,
          GUID = "191031AE",
          SpeakNpcId = 100006,
          Subtitle = "Were those gunshots?",
