        },
        [10012002] = {
          ContentES = "¡Berry!",
          DialogueId = 10012002,
          DisableMouth = 1,
          Duration = 1,
          ExStoryInfo = "Player",
          GUID = "191061EB",
          SpeakNpcId = 100001,
          Subtitle = "Berry!",
          VoiceName = "voice/$Locale$/story/1001/100120/191061EB"
        },
        [10012003] = {
          ContentES = "Ríndete, N.º 0 Incluso la espada más dura tiene su punto de quiebre.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012003,
          DisableMouth = 1,
          Duration = 4.5,
          GUID = "19106214",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Give it up, No. 0. Even the toughest blade has its breaking point.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106214"
        },
        [10012004] = {
          ContentES = "Vuelve conmigo, y vivirás... al igual que {性别:este niño|esta niña} al que tanto quieres proteger.",
          DialogueId = 10012004,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19106218",
          SpeakNpcId = 100005,
          Subtitle = "Come back with me, and you'll live — so will this kid you care so much about.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106218"
        },
        [10012005] = {
          ContentES = "Si no, {性别:él|ella} morirá...",
          DialogueId = 10012005,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106219",
          SpeakNpcId = 100005,
          Subtitle = "Otherwise, {性别:he|she} will—",
          VoiceName = "voice/$Locale$/story/1001/100120/19106219"
        },
        [10012006] = {
          ContentES = "... Prométemelo.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012006,
          DisableMouth = 1,
          Duration = 1.7,
          GUID = "1910623E",
          SpeakNpcId = 100003,
          Subtitle = "...Give me your word.",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623E"
        },
        [10012007] = {
          ContentES = "¿Hmm?",
          DialogueId = 10012007,
          DisableMouth = 1,
          Duration = 1,
          GUID = "1910623F",
          SpeakNpcId = 100005,
          Subtitle = "Hmm?",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623F"
        },
        [10012008] = {
          ContentES = "Voy contigo, pero tienes que prometer que {性别:lo|la} dejarás ir.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012008,
          DisableMouth = 1,
          Duration = 4,
          GUID = "19106268",
          LookAt = {
            [1] = "100007:n(100005)"
          },
          SpeakNpcId = 100003,
          Subtitle = "I'll go back with you, but you have to promise to let {性别:him|her} go.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106268"
        },
        [10012009] = {
          ContentES = "¡Promételo! ¡Si no, traerás nuestros dos cadáveres!",
          DefaultLookAt = "KeepState",
          DialogueId = 10012009,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106292",
          SpeakNpcId = 100003,
          Subtitle = "Give me your word! Or, you can take two corpses back!",
          VoiceName = "voice/$Locale$/story/1001/100120/19106292"
        },
        [10012010] = {
          ContentES = "Te equivocas. Esto no es una negociación, es una orden.",
          DefaultLookAt = "Self",
          DialogueId = 10012010,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "190F7C64",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Perhaps I wasn't clear — This is not a negotiation, it's an order.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7C64"
        },
        [10012011] = {
          ContentES = "... Berry.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012011,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "191062E6",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Berry.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E6"
        },
        [10012012] = {
          ContentES = "... ¿¡Tú...!?",
          DialogueId = 10012012,
          DisableMouth = 1,
          Duration = 1,
          GUID = "191062E7",
          SpeakNpcId = 100003,
          Subtitle = "...?! You...!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E7"
        },
        [10012013] = {
          ContentES = "Sal de aquí, y vive.",
          DialogueId = 10012013,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "191062E8",
          SpeakNpcId = 100001,
          Subtitle = "Get out of here, and live.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E8"
        },
        [10012014] = {
          ContentES = "¡¡No!!",
          DialogueId = 10012014,
          DisableMouth = 1,
          Duration = 1.5,
          GUID = "191062E9",
          SpeakNpcId = 100003,
          Subtitle = "No—!!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E9"
        },
        [10012015] = {
          ContentES = "Pequeña pregunta, {nickname}. “El signo de tres parpadeos rápidos” significa...",
          DialogueId = 10012015,
          Duration = 5,
          GUID = "191062F0",
          SpeakNpcId = 100003,
          Subtitle = "Quick question, . The \"three quick blinks\" means—",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F0"
        },
        [10012016] = {
          ContentES = "¡Lo recuerdo, Berry! Tres parpadeos rápidos significa...",
          DialogueId = 10012016,
          Duration = 6,
          ExStoryInfo = "Player",
          GUID = "191062F1",
          SpeakNpcId = 100001,
          Subtitle = "I've got this, Berry. Three quick blinks means...",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F1"
        },
        [10012017] = {
          ContentES = "“Aunque estés {性别:solo|sola}, debes ser valiente y seguir viviendo.”",
          DialogueId = 10012017,
          DialoguePanelType = "None",
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "191062F2",
          SpeakNpcId = 100001,
          Subtitle = "\"Even if left all alone, you should be brave and live on.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F2"
        },
        [10012018] = {
          ContentES = "“Hasta el día en que nos volvamos a encontrar.”",
          DialogueId = 10012018,
          DialoguePanelType = "None",
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "191062F3",
          SpeakNpcId = 100001,
          Subtitle = "\"Until the day we meet again.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F3"
        },
        [10012101] = {
          ContentES = "Eso es...",
          DialogueId = 10012101,
          Duration = 1.5,
          GUID = "19107252",
          NextDialogue = 10012102,
          SpeakNpcId = 100005,
          Subtitle = "That is...",
          VoiceName = "voice/$Locale$/story/1001/100121/19107252"
        },
        [10012102] = {
          ContentES = "El N.º 0 no se supone que libere todos sus poderes aún. ¿Por qué...",
          DialogueId = 10012102,
          Duration = 2.5,
          GUID = "1910727C",
          NextDialogue = 10012103,
          SpeakNpcId = 100005,
          Subtitle = "No. 0 is not supposed to release all her powers yet. Why...",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727C"
        },
        [10012103] = {
          ContentES = "No, ese no es su poder, es Resonancia.",
          DialogueId = 10012103,
          Duration = 3,
          GUID = "1910727D",
          NextDialogue = 10012104,
          SpeakNpcId = 100005,
          Subtitle = "No, that's not her power, it's Resonance.",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727D"
        },
        [10012104] = {
          ContentES = "...{性别:Este chico|Esta chica} a quien ella protege... ¿sería el nuevo recipiente del poder de la Resonancia?",
          DialogueId = 10012104,
          Duration = 2.5,
          GUID = "191072A6",
          NextDialogue = 10012110,
          SpeakNpcId = 100005,
          Subtitle = "...That brat she's trying to protect... That's the new receptacle for the Power of Resonance?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072A6"
        },
        [10012105] = {
          ContentES = "...La reaparición simultánea del poder de la “Resonancia” y del “N.º 0”... ¿qué significa eso?",
          DialogueId = 10012105,
          Duration = 3,
          GUID = "191072D0",
          SpeakNpcId = 100005,
          Subtitle = "The reappearance of the \"Power of Resonance\" and \"No. 0\" together... What could this possibly mean...?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D0"
        },
        [10012110] = {
          ContentES = "Pensándolo bien, la apariencia de {性别:este chico|esta chica} hace un momento era...",
          DialogueId = 10012110,
          GUID = "191072D1",
          NextDialogue = 10012105,
          SpeakNpcId = 100005,
          Subtitle = "Come to think of it,  {性别:his|her} face was...",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D1"
        },
        [10012201] = {
          ContentES = "¡Corre!",
          DialogueId = 10012201,
          Duration = 2,
          GUID = "191082BA",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          ContentES = "¡No me escaparás!",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934C"
        },
        [10012303] = {
          Content = "那就好，不要勉强自己。",
          DialogueId = 10012303,
          Duration = 2,
          GUID = "1910934D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934D"
        },
        [10012401] = {
          ContentES = "Parece que alguien solía vivir aquí.",
          DialogueId = 10012401,
          ExStoryInfo = "Player",
          GUID = "1910A38A",
          NextDialogue = 10012402,
          SpeakNpcId = 100001,
          Subtitle = "It seems someone used to live here.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A38A"
        },
        [10012402] = {
          ContentES = "¿Esta era tu casa, verdad, Berry?",
          DialogueId = 10012402,
          ExStoryInfo = "Player",
          GUID = "1910A3B4",
          NextDialogue = 10012403,
          SpeakNpcId = 100001,
          Subtitle = "This was your home, am I right, Berry?",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3B4"
        },
        [10012403] = {
          ContentES = "...Yo...",
          DialogueId = 10012403,
          GUID = "1910A3DE",
          NextDialogue = 10012404,
          SpeakNpcId = 100003,
          Subtitle = "...I...",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3DE"
        },
        [10012404] = {
          ContentES = "...Sí. Pero no solo yo. Aquí, era nuestra casa.",
          DialogueId = 10012404,
          GUID = "1910A408",
          NextDialogue = 10012405,
          SpeakNpcId = 100003,
          Subtitle = "...Yes, and no. It was OUR home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A408"
        },
        [10012405] = {
          ContentES = "¿“Nuestra” casa? Sin embargo, no recuerdo nada.",
          DialogueId = 10012405,
          ExStoryInfo = "Player",
          GUID = "1910A432",
          NextDialogue = 10012406,
          SpeakNpcId = 100001,
          Subtitle = "Our home? But I don't remember a thing.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A432"
        },
        [10012406] = {
          ContentES = "...No importa. Tal vez sea mejor así. Cuando salgamos de aquí, construiremos un nuevo hogar.",
          DialogueId = 10012406,
          GUID = "1910A433",
          SpeakNpcId = 100003,
          Subtitle = "...It's okay. Maybe it's all for the best. After we make it out, we'll build a new home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A433"
        },
        [10012501] = {
          Content = "任务失败，请重新开始。",
          DialogueId = 10012501,
