          Duration = 10,
          ExStoryInfo = "Player",
          GUID = "1910B3F3",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again"
        },
        [10012601] = {
          Content = "净界岛上的小村，我和贝蕾妮卡一起长大的地方。",
          DialogueId = 10012601,
          Duration = 2.5,
          GUID = "1910C45A",
          NextDialogue = 10012602,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C45A"
        },
        [10012602] = {
          Content = "这些叫做秽兽的怪物究竟从何而来，我们也无从得知；",
          DefaultLookAt = "KeepState",
          DialogueId = 10012602,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C484",
          LookAt = {
            [1] = "100001:n(100003)"
          },
          NextDialogue = 10012603,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C484"
        },
        [10012603] = {
          Content = "只知道，昔日宁和的村庄，一夜之间变成了这副模样。",
          DialogueId = 10012603,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C4AE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C4AE"
        },
        [10012701] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentES = "Has vuelto, {nickname}... Mi otra mitad, mi reflejo y mi eco.",
          DialogueId = 10012701,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D4EC",
          NextDialogue = 10012702,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You're back, ... My other half, my reflection, and my echo.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D4EC"
        },
        [10012702] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentES = "Oíste mi voz y recuperaste el poder que te pertenece. La “Resonancia.”",
          DialogueId = 10012702,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D516",
          NextDialogue = 10012703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You heard my voice and retrieved the power that belongs to you. The \"Resonance.\"",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D516"
        },
        [10012703] = {
          Camera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          ContentES = "Este poder no cambió nada. Caí al mar y nunca despertaré de nuevo. Todo ha terminado.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012703,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D540",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012704,
          SpeakNpcId = 100001,
          Subtitle = "This power didn't change anything. I fell into the sea and I'll never wake up again. It's all over.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D540"
        },
        [10012704] = {
          Camera = "699.554688,-957.21875,341.90564,0.000407,-14.001368,121.374519,35.0,100000.0,false,Manual,22.0",
          ContentES = "No, lo veo ... tu futuro, nuestro futuro... no termina aquí.",
          DialogueId = 10012704,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "249.050781,-1061.171875,341.90564,0.00044,-16.201441,91.573235,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D56A",
          NextDialogue = 10012705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "No, I can see it — your future, our future... it doesn't end here.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56A"
        },
        [10012705] = {
          ContentES = "Alguien te sacará de las aguas oscuras y te llevará a una extensión helada, donde el destino te impondrá la verdadera prueba.",
          DialogueId = 10012705,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D56B",
          NextDialogue = 10012706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Someone will pluck you from the briny waters and lead you to a frozen wilderness, where destiny will pose the ultimate test.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56B"
        },
        [10012706] = {
          Camera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          ContentES = "¿Estás diciendo... que todavía estoy {性别:vivo|viva}?",
          DefaultLookAt = "KeepState",
          DialogueId = 10012706,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D594",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012712,
          SpeakNpcId = 100001,
          Subtitle = "Are you saying... I'm still alive?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D594"
        },
        [10012707] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentES = "...Ha llegado el momento. Déjame ofrecerte mi último regalo.",
          DialogueId = 10012707,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D595",
          NextDialogue = 10012708,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "...The time has come. Let me offer you one last gift.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D595"
        },
        [10012708] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentES = "Dame la mano, {nickname}.",
          DialogueId = 10012708,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D599",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Here, .",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D599"
        },
        [10012709] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentES = "Estas arenas son nuestros recuerdos compartidos, que unen el pasado, el presente y el futuro.",
          DialogueId = 10012709,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59A",
          NextDialogue = 10012710,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "These sands are our shared memories, bridging the past, present, and future."
        },
        [10012710] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentES = "Dentro de estas arenas fluidas de memoria, encontrarás la fuerza para tu viaje.",
          DialogueId = 10012710,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59B",
          NextDialogue = 10012711,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Within these flowing sands of memory, you shall find strength for your journey.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D59B"
        },
        [10012711] = {
          Content = "愿他们成为你此行的助力。",
          DialogueId = 10012711,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59C",
          NextDialogue = 10012712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "May they be your strength on your journey.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D59C"
        },
        [10012712] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentES = "Es hora de partir.",
          DialogueId = 10012712,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D596",
          NextDialogue = 10012713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "It's time to set off.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D596"
        },
        [10012713] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentES = "... {nickname}. La vida es un viaje solitario en la oscuridad infinita de la noche. El río se desborda de lágrimas, y las zarzas que bordean sus orillas son su testimonio.",
          DialogueId = 10012713,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D597",
          NextDialogue = 10012714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = ".... Life is like a lonely cruise through the boundless darkness of the night. The river weeps, overflowing its banks, while the thorny thickets on either side stand as a testament to its sorrow.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D597"
        },
        [10012714] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentES = "Velaré por ti... el alma de la otra orilla, para ver hasta dónde llegarás.",
          DialogueId = 10012714,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D598",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "I'll keep watching over you, The One Across the Shore... to see where you're going.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D598"
        },
        [10012801] = {
          ContentES = "Esta es mi primera visita en la Región de Cocytus. Aparentemente, la bienvenida aquí es... particular.",
          DialogueId = 10012801,
          Duration = 8.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E52A",
          RelatedWikiId = {
            [1] = 408002
          },
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in the Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E52A"
        },
        [10012802] = {
          ContentES = "No quiero molestarte, solo quiero... hacer un pequeño “trato.”",
          DialogueId = 10012802,
          Duration = 6.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E57E",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small \"bargain.\"",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E57E"
        },
        [10012803] = {
          ContentES = "Te pagaré lo que quieras, y todo lo que tienes que hacer, bueno, será pan comido.",
          DialogueId = 10012803,
          Duration = 6.5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E5A8",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E5A8"
        },
        [10017801] = {
          Content = "......",
          DialogueId = 10017801,
          Duration = 1,
          GUID = "1914197A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001,
            [5] = 403001
          },
          VoiceName = "voice/$Locale$/story/1002/100178/1914197A"
        },
        [10017901] = {
          ContentES = "El dirigible está en la cima. Descansamos un momento, luego continuamos.",
          DialogueId = 10017901,
          DisableMouth = 1,
          Duration = 5,
          GUID = "191429E2",
          SpeakNpcId = 100003,
          Subtitle = "The ship is at the mountaintop. After a short break, we'll push on.",
          VoiceName = "voice/$Locale$/story/1001/100179/191429E2"
        },
        [10017902] = {
          ContentES = "...Ya... tendremos que decir adiós a la Isla del Purgatorio.",
          DialogueId = 10017902,
          DisableMouth = 1,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19142A0C",
          SpeakNpcId = 100001,
          Subtitle = "...Can't believe we'll be saying goodbye to Purgatorio Island soon.",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0C"
        },
        [10017903] = {
          ContentES = "...Criaturas, simplemente no pueden dejarnos en paz, ¿verdad?",
          DialogueId = 10017903,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19142A0D",
          SpeakNpcId = 100003,
          Subtitle = "...You creatures just can't give us a break, can you?",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0D"
        },
        [10018001] = {
          Content = "走。",
          DialogueId = 10018001,
          Duration = 2,
          GUID = "19143A4A",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100180/19143A4A"
        },
        [10018101] = {
          DialogueId = 10018101,
          Duration = 1,
          GUID = "19144AB2",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100181/19144AB2"
        },
        [10018201] = {
          Content = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
          DialogueId = 10018201,
          DialoguePanelType = "None",
          Duration = 13,
          ExStoryInfo = "Player",
          GUID = "19145B1A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B1A"
        },
        [10018202] = {
          Content = "第一次，我感受到了，我是如此真实地活着。",
          DialogueId = 10018202,
          DialoguePanelType = "None",
          Duration = 7,
          ExStoryInfo = "Player",
          GUID = "19145B44",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B44"
        },
        [10018301] = {
          Content = "下坠。我本应朝着漆黑的深渊下坠。",
          DialogueId = 10018301,
          Duration = 2.5,
          GUID = "19146B82",
          NextDialogue = 10018302,
          VoiceName = "voice/$Locale$/story/1001/100183/19146B82"
        },
        [10018302] = {
          Content = "但，我却感觉自己在晨雾的怀抱里飘浮。",
          DialogueId = 10018302,
          Duration = 2.5,
          GUID = "19146BAC",
          NextDialogue = 10018303,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BAC"
        },
        [10018303] = {
          Content = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
          DialogueId = 10018303,
          Duration = 4,
          GUID = "19146BD6",
          NextDialogue = 10018304,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BD6"
        },
        [10018304] = {
          Content = "而是一种，奇特的触感……亲切，甚至令人怀念。",
          DialogueId = 10018304,
          Duration = 3,
          GUID = "19146C00",
          VoiceName = "voice/$Locale$/story/1001/100183/19146C00"
        },
        [10018401] = {
          ContentES = "Pero hasta ahora, no ha habido respuesta. Solo arena movediza interminable cubriendo mi visión, y...",
          DialogueId = 10018401,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "19147BEA",
          NextDialogue = 10018402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "But up until now, there has been no answer. Only endless flowing quicksand covering my vision, and...",
          VoiceName = "voice/$Locale$/story/1001/100184/19147BEA"
        },
        [10018402] = {
          ContentES = "{性别:ella|él}.",
          DialogueId = 10018402,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "19147C14",
