        },
        [10019001] = {
          ContentES = "El pueblo está sumido en un silencio mortal. Me temo que probablemente...",
          DialogueId = 10019001,
          Duration = 1.8,
          GUID = "1914DE5A",
          NextDialogue = 10019002,
          SpeakNpcId = 100003,
          Subtitle = "The village is in dead silence. I'm afraid they've probably...",
