        },
        [10019002] = {
          ContentES = "¡¡...!!",
          DialogueId = 10019002,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1914DE84",
          NextDialogue = 10019003,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE84"
        },
        [10019003] = {
          ContentES = "... Quiero decir, probablemente se hayan escapado en barco.",
          DialogueId = 10019003,
          Duration = 2.5,
          GUID = "1914DEAE",
          NextDialogue = 10019004,
          SpeakNpcId = 100003,
          Subtitle = "...I mean, they've probably scarpered off by boat.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAE"
        },
        [10019004] = {
          ContentES = "Tenemos que regresar rápidamente a recoger las armas, luego ir al muelle. Aún es peligroso aquí.",
          DialogueId = 10019004,
          Duration = 2.5,
          GUID = "1914DEAF",
          NextDialogue = 10019005,
          SpeakNpcId = 100003,
          Subtitle = "We should hurry home and get the weapons, and then get to the wharf. It's still dangerous here.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAF"
        },
        [10019005] = {
          ContentES = "Estamos completamente desarmados... Tenemos que evitar a esos Filthoids tanto como sea posible.",
          DialogueId = 10019005,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "1914DEB1",
          NextDialogue = 10019006,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(We're unarmed right now. We have to avoid those Filthoids as much as possible.)",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB1"
        },
        [10019006] = {
          ContentES = "Un poco más... la casa está justo adelante.",
          DialogueId = 10019006,
          Duration = 2.5,
          GUID = "1914DEB2",
          SpeakNpcId = 100003,
          Subtitle = "Almost there. It's up ahead.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB2"
        },
        [10019007] = {
