        },
        [10019301] = {
          ContentES = "¿Cuántos de ellos hay...?",
          DialogueId = 10019301,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19150F92",
          NextDialogue = 10019302,
          SpeakNpcId = 100001,
          Subtitle = "How many of them are there...",
          VoiceName = "voice/$Locale$/story/1001/100193/19150F92"
        },
        [10019302] = {
          ContentES = "Subamos a la cima para deshacernos de ellos.",
          DialogueId = 10019302,
          Duration = 4,
          GUID = "19150FBC",
          SpeakNpcId = 100003,
          Subtitle = "Let's get to the top to shake them off.",
          VoiceName = "voice/$Locale$/story/1001/100193/19150FBC"
        },
        [10019401] = {
          Content = "这是我第一次来科赛托斯省。看来，这里的待客之道颇为独特啊。",
          DialogueId = 10019401,
          Duration = 8,
          ExStoryInfo = "EXPlayer",
          GUID = "19151FFA",
          RelatedWikiId = {
            [1] = 408002
          },
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1001/100194/19151FFA"
        },
        [10019402] = {
          Content = "我没有任何恶意，只是想同你做一笔……小小的交易。",
          DialogueId = 10019402,
          Duration = 5.3,
          ExStoryInfo = "EXPlayer",
          GUID = "19152024",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small \"bargain.\"",
          VoiceName = "voice/$Locale$/story/1001/100194/19152024"
        },
        [10019403] = {
          Content = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
          DialogueId = 10019403,
          Duration = 6.9,
          ExStoryInfo = "EXPlayer",
          GUID = "1915204E",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1001/100194/1915204E"
        },
        [10019501] = {
          Content = "？？？：不杀了{性别：他|她}吗？",
          DialogueId = 10019501,
          Duration = 2.5,
          GUID = "19153057.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153057"
        },
        [10019502] = {
          Content = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
          DialogueId = 10019502,
          Duration = 9,
          GUID = "19153058.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153058"
        },
        [10019503] = {
          Content = "？？？：我会处理。但，现在还不是时候。",
          DialogueId = 10019503,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153059.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153059"
        },
        [10019504] = {
          Content = "？？？：收到。将如实提交您的答复。",
          DialogueId = 10019504,
          Duration = 5,
          GUID = "19153060.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153060"
        },
        [10019505] = {
          Content = "？？？：……听着，{NickName}。",
          DialogueId = 10019505,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "19153061.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153061"
        },
        [10019506] = {
          Content = "？？？：“生命是航行在无尽长夜里的孤船。”",
          DialogueId = 10019506,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153062.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153062"
        },
        [10019507] = {
          Content = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
          DialogueId = 10019507,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1915308C",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915308C"
        },
        [10019508] = {
          Content = "？？？：“我会一直注视着……”",
          DialogueId = 10019508,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "191530B6",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530B6"
        },
        [10019509] = {
          Content = "？？？：“来自彼岸之人，你将驶向何方。”",
          DialogueId = 10019509,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "191530E0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530E0"
        },
        [10019510] = {
          Content = "（是谁……）",
          DialogueId = 10019510,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1915310A",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915310A"
        },
        [10025701] = {
          ContentES = "Esta fuga... comenzó con ese sueño extraño. He sido {性别:atormentado|atormentada} por sueños similares toda mi vida.",
          DialogueId = 10025701,
          Duration = 3,
          GUID = "19192992",
          NextDialogue = 10025702,
          Subtitle = [[
This escape was heralded by that odd dream.
I've been plagued by similar ones all my life.]],
          VoiceName = "voice/$Locale$/story/1002/100257/19192992"
        },
        [10025702] = {
          ContentES = "Pero no es el momento de perderse en el pasado. Hay algo más urgente, ahora...",
          DialogueId = 10025702,
          Duration = 3,
          GUID = "191929BC",
          NextDialogue = 10025703,
          Subtitle = "But now's not the time for reflection...\nThere's something more pressing at the moment—",
          VoiceName = "voice/$Locale$/story/1002/100257/191929BC"
        },
        [10025703] = {
          ContentES = "Berry y yo debemos huir de la Isla del Purgatorio, aunque fue aquí donde crecimos juntos.",
          DialogueId = 10025703,
          Duration = 4,
          GUID = "191929E6",
          Subtitle = [[
Berry and I must flee from this isle known as "Purgatorio Island,"
where we spent our childhoods together.]],
          VoiceName = "voice/$Locale$/story/1002/100257/191929E6"
        },
        [10025704] = {
          ContentES = "Porque nuestra vida tranquila ya ha sido desgarrada, destrozada por las garras impías de los Filthoids...",
          DialogueId = 10025704,
          Duration = 3,
          GUID = "19192A10",
          Subtitle = "For the peace we once knew has been torn asunder by the vile claws of Filthoids...",
          VoiceName = "voice/$Locale$/story/1002/100257/19192A10"
        },
        [10025801] = {
          ContentES = "¿Están muertos esos Filthoids...?",
          DialogueId = 10025801,
          ExStoryInfo = "Player",
          GUID = "191939FA",
          NextDialogue = 10025802,
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/191939FA"
        },
        [10025802] = {
          ContentES = "Alguien ya los ha enfrentado... justo antes de nuestra llegada.",
          DialogueId = 10025802,
          GUID = "19193A24",
          NextDialogue = 10025803,
          SpeakNpcId = 100003,
          Subtitle = "It seems someone had a fight with them just before we arrived.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A24"
        },
        [10025803] = {
          ContentES = "¿Sería un aldeano el que encontró refugio aquí...? No. Esa puerta, la abrimos {性别:nosotros|nosotras}.",
          DialogueId = 10025803,
          ExStoryInfo = "Player",
          GUID = "19193A4E",
          NextDialogue = 10025804,
          SpeakNpcId = 100001,
          Subtitle = "Could it be one of the villagers... No, we were the first to open that door.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A4E"
        },
        [10025804] = {
          ContentES = "De todos modos, gracias a esa persona, no tenemos que enfrentarnos a estos Filthoids {性别:nosotros mismos|nosotras mismas}.",
          DialogueId = 10025804,
          ExStoryInfo = "Player",
          GUID = "19193A78",
          NextDialogue = 10025805,
          SpeakNpcId = 100001,
          Subtitle = "Anyway, thanks to that person, we don't have to deal with these Filthoids ourselves.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A78"
        },
        [10025805] = {
          ContentES = "Quienquiera que sea, no debemos subestimarlo. Mantengámonos alerta.",
          DialogueId = 10025805,
          GUID = "19193AA2",
          SpeakNpcId = 100003,
          Subtitle = "Whoever it was, they're not to be underestimated. We must be vigilant.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA2"
        },
        [10025806] = {
          Content = "这些秽兽……断气了？",
          DialogueId = 10025806,
          ExStoryInfo = "Player",
          GUID = "19193AA3",
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA3"
        },
        [10027501] = {
          Content = "在不远处……",
          DialogueId = 10027501,
          Duration = 2,
          GUID = "191A50E2",
          Subtitle = "A short distance away...",
          VoiceName = "voice/$Locale$/story/1001/100275/191A50E2"
        },
        [10029301] = {
          ContentES = "En mis sueños que se repiten en espiral, me he hecho esa pregunta incontables veces.",
          DialogueId = 10029301,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "1914AD4C",
          NextDialogue = 10018401,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "In my dreams that unfold like a double helix, I've asked myself that question countless times.",
          VoiceName = "voice/$Locale$/story/1002/100293/1914AD4C"
        },
        [10029309] = {
          Content = "恭喜你起名完成啦！！！！！",
          DialogueId = 10029309,
          Duration = 3,
          GUID = "1914AD4D",
          VoiceName = "voice/$Locale$/story/1002/100293/"
        },
        [10029401] = {
