        [10030416] = {
          Camera = "17.873657,-44.469727,169.63678,-0.00131,-21.59972,96.626923,35.000008,39.151329,false,DoNotOverride,22",
          Content = "那晚泪湖边上的事，我听说了，我知道你多半不想见她。",
          DialogueId = 10030416,
          GUID = "191C2F20",
          NextDialogue = 10030417,
          SpeakNpcId = 200003,
          Subtitle = "I heard about what happened at Lamenting Lake that day. I know you probably don't want to see her.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F20"
        },
        [10030417] = {
          Camera = "406.211243,-635.881592,325.041443,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
          Content = "但你是那夜<H>袭击事件</>中唯一活下来的，我想她不会轻易放弃。",
          DialogueId = 10030417,
          FinalCamera = "391.624817,-609.80957,316.13501,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
          GUID = "191C2F4A",
          NextDialogue = 10030418,
          SpeakNpcId = 200003,
          Subtitle = "But you were the sole survivor of the murder case that night. I doubt she'll give up easily.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F4A"
        },
        [10030418] = {
          Camera = "13.79155,51.50293,147.848907,0.000202,-3.803739,102.358437,35.000019,112.939484,false,Manual,22.0",
          Content = "唯一活下来的？",
          DialogueId = 10030418,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "191C2F74",
          NextDialogue = 10030419,
          SpeakNpcId = 100001,
          Subtitle = "The sole survivor?",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F74"
        },
        [10030419] = {
          Camera = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
          Content = "时间差不多了。",
          DialogueId = 10030419,
          GUID = "191C2F9E",
          NextDialogue = 10030422,
          SpeakNpcId = 200003,
          Subtitle = "I should be going.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F9E"
        },
        [10030420] = {
          Camera = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
          DialogueId = 10030420,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "80.489944,-105.125,178.525864,0.000199,-12.403227,110.153175,35.000015,290.266602,false,Manual,22.0",
          GUID = "191C2FC9",
          Scripts = "MoveTo{ActorId{200003},TargetPoint{\"kami_01_leave\"},MoveSpeed{90},Visibility{\"Show\"}}",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 3
        },
        [10030421] = {
          Content = "慰问品七七八八地堆放着，似乎是这几天很多人陆续送来的。\n仔细一看，里面有不知名的野花，虽然冷掉但依旧闻起来美味的肉汤，带划痕但精美的八音盒，画着小鸟的一罐棉花糖……\n除了这些以外，还有一份没有署名，系着歪扭蝴蝶结的朴素礼盒，打开以后发现里面是一瓶帝国最顶尖的止痛剂。这份关怀的心虽是好的，但送给一名昏迷人士止痛剂，实在是没什么意义了。",
          DialogueId = 10030421,
          GUID = "191C2FF2",
          Subtitle = [[
The care packages are scattered across the room. They seem to have been brought in by various individuals over the past few days.
On closer inspection, the packages reveal an assortment of thoughtful items: a bouquet of wildflowers, a bowl of now-cold but still aromatic meat soup, a scratched yet beautifully crafted music box, and a tin of cotton candy with a drawing of a little bird on its surface...
Among these items lies a plain gift box tied with a clumsily made ribbon bow, missing a name tag. Inside is a bottle of the Empire's finest painkiller. While the gesture is undoubtedly kind, gifting a painkiller to someone in a coma feels, perhaps, a little misplaced.]],
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FF2"
        },
        [10030422] = {
          Camera = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
          Content = "还想知道什么，就去水仙平原问你的朋友吧。这几天他们也很挂念你。",
          DialogueId = 10030422,
          GUID = "191C2FC8",
          NextDialogue = 10030420,
          SpeakNpcId = 200003,
          Subtitle = "If you want answers, go to The Asphodel and ask your friends. They've been worried about you these past few days.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FC8"
        },
        [10030501] = {
          Content = "（咦，冰湖城多了好多气球……最近是什么节日吗？）",
          DialogueId = 10030501,
          DisableMouth = 1,
          GUID = "191C3D12",
          NextDialogue = 10030502,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Huh, there are so many balloons around Icelake... Is it some kind of festival?)",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D12"
        },
        [10030502] = {
          Content = "（但这么热闹的装饰，也盖不住空气里的冷清……）",
          DialogueId = 10030502,
          DisableMouth = 1,
          GUID = "191C3D3C",
          NextDialogue = 10030503,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(But even with all these festive decorations, the lingering chill in the air is still pretty obvious...)",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D3C"
        },
        [10030503] = {
          Content = "（去找奥特赛德和白了解下昏迷这几天的情况吧。）",
          DialogueId = 10030503,
          DisableMouth = 1,
          GUID = "191C3D66",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I should go check in with Snow and Outsider to find out what's happened while I was unconscious.)",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D66"
        },
        [10030504] = {
          Content = "13个人，13个人！一夜之间！",
          DialogueId = 10030504,
          Duration = 5,
          GUID = "191C3D90",
          SpeakNpcId = 700036,
          Subtitle = "13 people... 13 people! All gone in a single night!",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D90"
        },
        [10030505] = {
          Content = "躲在家里也不安全，我们到底该怎么办……",
          DialogueId = 10030505,
          Duration = 7,
          GUID = "191C3DBA",
          SpeakNpcId = 700038,
          Subtitle = "Even staying home isn't safe anymore. What are we supposed to do?",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3DBA"
        },
        [10030506] = {
          Content = "唉，一把老骨头了，总不能为这事搬家吧……",
          DialogueId = 10030506,
          Duration = 7,
          GUID = "191C3DE4",
          SpeakNpcId = 700246,
          Subtitle = "*sigh* ...These old bones couldn't possibly move because of something like this...",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3DE4"
        },
        [10030507] = {
          Content = "演员在八音盒内旋转，我们在冰湖城中徘徊！转折将要发生，雾海欢迎来客！",
          DialogueId = 10030507,
          Duration = 12,
          GUID = "191C3E0E",
          SpeakNpcId = 700015,
          Subtitle = "The performers spin inside the music box, while we wander through the maze of Icelake! The fateful twist is near, and the Misty Sea welcomes its new visitors!",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E0E"
        },
        [10030508] = {
          Content = "别，别过来，不要杀我……卫戍部队，卫戍部队在哪里？！",
          DialogueId = 10030508,
          Duration = 9,
          GUID = "191C3E38",
          SpeakNpcId = 700035,
          Subtitle = "S—Stay back! Don't kill me... Escort... Where's the Escort!?",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E38"
        },
        [10030509] = {
          Content = "怪物，绝对是怪物干的……",
          DialogueId = 10030509,
          Duration = 4,
          GUID = "191C3E62",
          SpeakNpcId = 700034,
          Subtitle = "It was definitely a monster... nothing else could've done this...",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E62"
        },
        [10030510] = {
          Content = "冰湖城外城近日发生多起恶性伤人事件，手段极其残忍，现场极为混乱，请广大市民减少深夜外出，锁好门窗。\n持有武器许可证的市民如果遭遇行凶者，不要试图反击（这很危险！！！），优先保全自身性命。\n如有凶手线索，请立即联系卫戍部队，黎瑟·费西尔。\n皇帝会庇护他忠诚的子民度过难关，荣耀尽归吾皇。",
          DialogueId = 10030510,
          GUID = "191C3E8C",
          Subtitle = "Multiple brutal assaults have recently occurred in the outer city. The attacks were exceptionally violent, leaving behind chaotic scenes. Citizens are strongly urged to stay indoors at night and keep their doors and windows securely locked.\nFor citizens holding a weapons permit: If you encounter the perpetrator, do not attempt to retaliate — it's extremely dangerous! Please prioritise your safety above all else.\nIf you have any information regarding the perpetrator, please contact the Escort immediately, attention: Rhythm Fischer.\nThe Emperor shall protect his loyal subjects through these trying times. All glory to our Emperor.",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E8C"
        },
        [10030601] = {
          Content = "挥手打个招呼。",
          DialogueId = 10030601,
          GUID = "191C4D7A",
          NextDialogue = 10030603,
          Subtitle = "Wave hello."
        },
        [10030602] = {
          Content = "吹个口哨。",
          DialogueId = 10030602,
          GUID = "191C4DA4",
          NextDialogue = 10030603,
          Subtitle = "Whistle to grab their attention."
        },
        [10030603] = {
          Camera = "78.226898,5.710938,147.152344,0.000109,-17.401026,138.984924,35.000011,249.345123,false,Manual,3.0",
          Content = "呜呜呜……是你，{nickname}，真的是你！！",
          DialogueId = 10030603,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "191C4DCE",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200021:n(100001)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10030604,
          SpeakNpcId = 200002,
          Subtitle = "Waaaah! ! It really is you!!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4DCE"
        },
        [10030604] = {
          Camera = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862011,35.282173,313.231873,false,Manual,6.0",
          Content = "哦？该说不说，碰上<H>卡戎狩猎</>还能活着，你命真是比坚壳果还硬啊。我还以为我们这个“夜航者小队”还没起航就要搁浅了呢。",
          DialogueId = 10030604,
          GUID = "191C4DF8",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10030605,
          SpeakNpcId = 200021,
          Subtitle = "Huh, surviving the Charon Hunt? I've got to say, you're tougher than an Ironshell Nut. Honestly, I thought the ship of our Noctoyagers would sink before it even left the dock.",
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "200002:Explain02_End"
          },
          TurnTo = {
            [1] = "100304:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4DF8"
        },
        [10030605] = {
          Camera = "0.396332,244.167969,21.378906,0.000094,25.396158,-121.224731,35.000011,411.428223,false,Manual,22.0",
          Content = "呸呸呸，明明这几天急得又是满城找医生，又是低三下四求卡米拉帮忙照顾{性别：他|她}的就是你，现在人家醒了，怎么又开始胡言乱语！",
          DialogueId = 10030605,
          GUID = "191C4E22",
          LookAt = {
            [1] = "200002:n(200021)",
            [2] = "100001:n(200021)",
            [3] = "200021:n(200002)"
          },
          NextDialogue = 10030606,
          SpeakNpcId = 200002,
          Subtitle = "Pfft! Says the guy who's been running all over town looking for doctors and grovelling to Camilla to take care of {性别:him|her} these past few days! Now that {性别:he|she} is all better, you're talking hot air again.",
          TalkActionId = {
            [1] = "200002:Angry01_Start",
            [2] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4E22"
        },
        [10030606] = {
          Camera = "23.498505,-207.322266,260.337891,0.00005,-27.40271,113.967453,35.000011,411.428162,false,Manual,3.0",
          Content = "我没——小矮子我警告你少添油加醋啊，不然——",
          DialogueId = 10030606,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "191C4E4C",
          NextDialogue = 10030607,
          SpeakNpcId = 200021,
          Subtitle = "I did not—! I'm warning you, Button Mushroom, quit twisting my words, or else—",
          TalkActionId = {
            [1] = "200021:Confident_Start",
            [2] = "200002:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4E4C"
        },
        [10030607] = {
          Camera = "-405.321106,133.943359,83.382812,0.000094,-6.002507,-9.651911,35.0,681.079041,false,Manual,3.0",
          Content = "（嗯……看起来这两个人都还挺精神的。）",
          DialogueId = 10030607,
          DisableMouth = 1,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "-405.321106,133.943359,83.382812,0.000094,-1.002378,-9.652462,35.000008,520.892517,false,Manual,6.0",
          GUID = "191C4E76",
          NextDialogue = 10030608,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... Looks like these two are doing just fine.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100306/191C4E76"
        },
        [10030608] = {
          Camera = "135.663208,-35.232422,147.521484,0.000062,-15.799928,131.261826,35.000023,295.694153,false,Manual,6.0",
          Content = "小仆从你感觉怎么样？嗯……胳膊腿都在，角的颜色很棒，脸色有点差。",
          DialogueId = 10030608,
          GUID = "191C4EA0",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200021:n(100001)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10030609,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, how are you feeling? Hmm... Arms and legs are all in place, and the colour of your horn looks great, though your face is a bit pale.",
          TalkActionId = {
            [1] = "200002:Bai_Think2Confident"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4EA0"
        },
        [10030609] = {
          Content = "很好，我就知道“不死的白色骑士，重生的夜航之星，被赐福的恶魔伯爵”不会随便抛下魔王大人不管的！",
          DialogueId = 10030609,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "191C4ECA",
          NextDialogue = 10030610,
          SpeakNpcId = 200002,
          Subtitle = "Good! I knew the \"Immortal White Knight, the Reborn Star of the Noctoyagers, the Blessed Demon Earl\" wouldn't leave their Demon King behind!",
          VoiceName = "voice/$Locale$/story/1003/100306/191C4ECA"
        },
        [10030610] = {
          Content = "你坐在这里不要动，我去给你拿点水果补补身子！",
          DialogueId = 10030610,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "191C4EF4",
          NextDialogue = 10030631,
          SpeakNpcId = 200002,
          Subtitle = "Stay right here — I'll go grab some nutritious fruit for you!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4EF4"
        },
        [10030611] = {
          Camera = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
          Content = "（怎么称呼变长以后，爵位反而更低了！等等……不能被白奇怪的称呼拐走话题。）",
          DialogueId = 10030611,
          DisableMouth = 1,
          GUID = "191C4F1E",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10030612,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Why is my title getting longer, but the rank keeps dropping? Wait... I can't let Snow's silly titles distract me.)",
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F1E"
        },
        [10030612] = {
          Camera = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
          Content = "刚才你们在说什么……<H>卡戎狩猎</>？那是什么？",
          DialogueId = 10030612,
          GUID = "191C4F48",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10030613,
          SpeakNpcId = 100001,
          Subtitle = "What were you talking about earlier? Charon Hunt? What's that?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F48"
        },
        [10030613] = {
          Camera = "190.638672,10.195312,120.152344,0.000129,5.198969,171.649796,35.282173,291.788361,false,Manual,6.0",
          Content = "是桩你逃不开的大麻烦。",
          DialogueId = 10030613,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191C4F72",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10030614,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"bai_02_walkin\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200021,
          Subtitle = "It's a trouble you can't run away from.",
          TalkActionId = {
            [1] = "200021:Explain01_Start",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F72"
        },
        [10030614] = {
          Camera = "1141.481445,-277.025391,7.660156,0.000071,7.39676,-70.647835,35.000023,392.616089,false,Manual,6.0",
          Content = "请问，{nickname}醒了吗？",
          DialogueId = 10030614,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "191C4F9C",
          NextDialogue = 10030615,
          RelatedWikiId = {
            [1] = 201011
          },
          Scripts = [[
PARA{
MoveTo{ActorId{200002},TargetPoint{"bai_02_set"},MoveSpeed{90},Visibility{"Show"}},
CameraMoveTo{_delay{1.5},TargetPosition{"1180.628296,-769.296875,95.171875,0.000036,-15.803131,78.751717,35.000023,411.821381,false,Manual,6.0"},duration{0}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Excuse me, is  awake?",
          TurnTo = {
            [1] = "100304:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F9C"
        },
        [10030615] = {
          Content = "呜哇！",
          DialogueId = 10030615,
          FacialId = {
            [1] = "200002:Shock02"
          },
          GUID = "191C4FC6",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10030616,
          SpeakNpcId = 200002,
          Subtitle = "Eek!",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4FC6"
        },
        [10030616] = {
          Camera = "1297.798462,-671.682617,65.072266,0.000065,-0.601719,155.368057,35.000008,116.489357,false,Manual,3.0",
          Content = "喏，来了来了。麻烦一蹬腿不动弹了——麻烦死喽。",
          DialogueId = 10030616,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "1297.798462,-671.682617,65.072266,0.000066,-0.601685,155.368103,35.000008,2653.720459,false,Manual,3.0",
          GUID = "191C4FF0",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10030617,
          SpeakNpcId = 200021,
          Subtitle = "Speak of the devil. Here comes your trouble — a big one, with a name.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100001:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4FF0"
        },
        [10030617] = {
          Camera = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
          Content = "……黎瑟·费西尔？",
          DialogueId = 10030617,
          GUID = "191C501A",
          NextDialogue = 10030618,
          SpeakNpcId = 100001,
          Subtitle = "...Rhythm Fischer?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200002:Shock_End",
            [3] = "200021:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C501A"
        },
        [10030618] = {
          Content = "对，又来了。她基本每天这个点都要来问一次。",
          DialogueId = 10030618,
          GUID = "191C5044",
          NextDialogue = 10030619,
          SpeakNpcId = 200021,
          Subtitle = "Yup. She's been stopping by every day around this time to ask about your situation.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C5044"
        },
        [10030619] = {
          Content = "……既然你说了“又”，那就说明这几天已经应付过她很多次了。交给你了，奥特赛德，加油，你可以的。",
          DialogueId = 10030619,
          GUID = "191C506E",
          LookAt = {
            [1] = "200021:n(100001)",
