          GUID = "191C50C2",
          NextDialogue = 10030622,
          SpeakNpcId = 200021,
          Subtitle = "Charon Hunt is a string of serial murders in the outer city. As the sole survivor, there's no way the Legion won't want some information from you. It's only a matter of time.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C50C2"
        },
        [10030622] = {
          Content = "我看这位黎瑟女士还挺好说话的，这在军团可不多见。要是换个凶神恶煞的来，还不如她呢。",
          DialogueId = 10030622,
          GUID = "191C50EC",
          NextOptions = {
            [1] = 10030623,
            [2] = 10030624
          },
          SpeakNpcId = 200021,
          Subtitle = "Honestly, she seems pretty reasonable for a legion officer. If it were someone more heavy-handed, you'd be wishing it was her instead.",
          VoiceName = "voice/$Locale$/story/1003/100306/191C50EC"
        },
        [10030623] = {
          Content = "…………",
          DialogueId = 10030623,
          GUID = "191C5116",
