          DetectiveQuestionId = 1001,
          DialogueId = 10031002,
          GUID = "191C8F44",
          ImprPlusId = 1007,
          NextDialogue = 10031004,
          Subtitle = "Yes, I remember it."
        },
        [10031003] = {
          Content = "要是你走在路上被人敲一闷棍也不可能忘吧。",
