          DialogueId = 10031006,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-408.319336,125.966064,245.506836,0.000153,-15.000843,-32.580688,35.0,941.904541,false,DoNotOverride,22",
          GUID = "191C8FEC",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 10031007,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "As for the exact time... I was preoccupied, so it's a bit of a blur.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C8FEC"
        },
        [10031007] = {
