          Content = "没事，是我想一个人走走。",
          DetectiveQuestionId = 1001,
          DialogueId = 10031008,
          FinalCamera = "122.243164,140.819336,51.0,0.000055,8.797734,-107.575684,35.0,941.904541,false,DoNotOverride,1.903106",
          GUID = "191C9040",
          LookAt = {
