          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "191C906A",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          NextDialogue = 10031010,
          SpeakNpcId = 100001,
          Subtitle = "(Wait... I remember when I reached this street, the wind had just stopped, and the moon came out. Judging by the moon's position, it must've been... between 4 and 5 a.m.)",
          TalkActionId = {
            [1] = "100001:Explain02_End"
