        [10032301] = {
          Camera = "27.207031,22.800903,135.363281,7.222204,-1.399963,-168.822205,30.000002,334.113678,false,DoNotOverride,2.014144",
          Content = "你的喉咙太紧张了，放松，将口腔打开，用气来托住你的声音，发声位置要靠后，想象将你的声音集中在后脑勺上的一点。",
          DialogueId = 10032301,
