          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow— Meowww!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96C0"
        },
        [10032609] = {
