          SpeakNpcId = 100304,
          Subtitle = "No. Filthoids are unintelligent and typically rampage openly through the streets. The fact that this creature hides during the day shows a level of strategic awareness — it's avoiding detection.",
          TalkActionId = {
            [1] = "100304:Think_Start",
            [2] = [[

100314:Talk01_End]],
            [3] = [[

100001:Think_End]]
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAB42"
        },
        [10032734] = {
          Camera = "26.018082,1022.058594,419.480957,0.00025,-9.196863,101.955841,25.000006,100000.0,false,Manual,22.0",
          Content = "我当时吓破了胆，光顾着把手里的东西一股脑丢过去，防身的鱼叉啊，月髓液啊……唉，辛辛苦苦搞来的月髓液全都砸它身上了，一分钱也没捞到。",
          DialogueId = 10032734,
          FinalCamera = "24.513016,1021.863281,422.244141,0.000247,-9.196863,99.756096,27.0,100000.0,false,Manual,22.0",
          GUID = "191DAB6C",
          NextDialogue = 10032735,
          Scripts = [[
SEQ{
PlayAnimation{_delay{10},ActorId{100314},AnimationId{"Talk02_End"},Duration{2}},
PlayAnimation{ActorId{100314},AnimationId{"Sigh_Start"},Duration{2}},
PlayAnimation{_delay{4},ActorId{100314},AnimationId{"Sigh_End"},Duration{2}},
}]],
          SpeakNpcId = 100314,
          Subtitle = "I was so terrified that I threw everything I had at it — my harpoon, the Phoxichor, everything! All the stuff I risked my neck for, gone just like that!",
          TalkActionId = {
            [1] = "100314:Talk02_Start",
            [2] = [[

100304:Think_End]]
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAB6C"
        },
        [10032735] = {
          Camera = "90.650497,1262.787109,464.490234,0.000251,-20.997215,-118.24427,25.0,100000.0,false,Manual,22.0",
          Content = "难怪它身上会沾着这么多月髓液。然后呢，它怎样了？",
          DialogueId = 10032735,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "90.650497,1262.787109,456.999512,0.000264,-18.797083,-118.044243,25.0,100000.0,false,Manual,22.0",
          GUID = "191DAB96",
          NextDialogue = 10032736,
          SpeakNpcId = 100304,
          Subtitle = "That would explain why the creature was heavily stained with Phoxichor. What happened after that?",
          TalkActionId = {
            [1] = "100304:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5.5,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAB96"
        },
        [10032736] = {
          Camera = "384.150787,1358.378906,320.59082,0.000264,2.402717,-144.638229,25.0,100000.0,false,Manual,22.0",
          Content = "我哪知道，我回过神来吓得连裤子都湿了，拔腿就跑，根本不敢回头看……",
          DialogueId = 10032736,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "391.812073,1347.450195,320.59082,0.000264,2.402717,-145.238098,25.0,100000.0,false,Manual,22.0",
          GUID = "191DABC0",
          NextDialogue = 10032737,
          SpeakNpcId = 100314,
          Subtitle = "How should I know!? I was so scared I even wet myself! I just ran for my life and didn't dare look back...",
          TalkActionId = {
            [1] = "100314:Disagree"
          },
          ToFinalCameraBlendTime = 10.5,
          VoiceName = "voice/$Locale$/story/1003/100327/191DABC0"
        },
        [10032737] = {
          Camera = "10.431229,1056.774414,422.860352,0.000264,-14.396945,91.352699,25.000002,100000.0,false,Manual,22.0",
          Content = "唉，我全都、全都告诉你们了！各位长官，你们要说话算话，你们要救救我！我和那怪物打过照面，一直躲在这里也是怕它找上门来……",
          DialogueId = 10032737,
          FinalCamera = "10.431229,1056.774414,422.860352,0.000264,-14.396945,91.352699,25.000002,100000.0,false,Manual,22.0",
          GUID = "191DABEA",
          LookAt = {
            [1] = "100314:n(100314)"
          },
          NextDialogue = 10032738,
          SpeakNpcId = 100314,
          Subtitle = "I've told you everything! Please, officers, you promised to protect me! That monster... I saw it up close! If I hadn't been hiding all this time, it probably would've found me already...",
          TalkActionId = {
            [1] = "100314:Sigh_Start"
          },
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1003/100327/191DABEA"
        },
        [10032738] = {
          Camera = "118.877075,858.798828,345.73584,0.000268,5.002854,122.155495,25.000002,327.751526,false,Manual,8.0",
          Content = "长官你看这个情报，和我那月、月髓液的事……",
          DialogueId = 10032738,
          FinalCamera = "116.053726,857.193359,345.73584,0.000266,4.60285,125.156082,25.000002,327.751526,false,Manual,8.0",
          GUID = "191DAC14",
          NextDialogue = 10032739,
          Scripts = "PlayAnimation{_delay{2},ActorId{100314},AnimationId{\"Explain01_Start\"},Duration{2}}",
          SpeakNpcId = 100314,
          Subtitle = "Look, I've told you all I know. What do you say...? Please, about the Phoxichor case. If I get charged...",
          TalkActionId = {
            [1] = "100314:Sigh_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAC14"
        },
        [10032739] = {
          Camera = "12.610016,1093.600586,371.847168,0.000261,4.202765,-97.048279,25.000002,100000.0,false,Manual,22.0",
          Content = "我会如实汇报。你盗窃的罪行确凿——不过，根据《海伯利亚刑事法典》，因为你提供了怪物藏身处这一关键线索，量刑上会酌情减免。",
          DialogueId = 10032739,
          FinalCamera = "12.383255,1091.765625,369.847656,0.000261,5.202746,-97.248253,25.000002,100000.0,false,Manual,22.0",
          GUID = "191DAC3E",
          NextDialogue = 10032740,
          Scripts = [[
PARA{
PlayAnimation{ActorId{100304},AnimationId{"AgreeHead"},Duration{2}},
PlayAnimation{_delay{4.5},ActorId{100304},AnimationId{"Talk03ToTalkL_Start"},Duration{2}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "I'll report your information as it is. Your theft of Imperial property is undeniable, but since you've provided critical intel, your sentence will be reduced in accordance with the Hyperborean Criminal Code.",
          TalkActionId = {
            [1] = "100314:Explain01_End"
          },
          ToFinalCameraBlendTime = 13.5,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAC3E"
        },
        [10032740] = {
          Camera = "88.094833,1061.608398,409.404785,0.000228,-5.796761,132.950623,25.000006,100000.0,false,Manual,22.0",
          Content = "唉……好吧……",
          DialogueId = 10032740,
          FinalCamera = "90.046204,1059.512695,409.694336,0.000228,-5.796761,132.950623,25.000006,100000.0,false,Manual,22.0",
          GUID = "191DAC68",
          NextDialogue = 10032741,
          Scripts = "PlayAnimation{_delay{2},ActorId{100314},AnimationId{\"Agree\"},Duration{2}}",
          SpeakNpcId = 100314,
          Subtitle = "*sigh* Fine...",
          TalkActionId = {
            [1] = "100304:Talk03ToTalkL_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAC68"
        },
        [10032741] = {
          Camera = "417.617523,1340.390625,517.765137,0.000245,-18.19628,-145.447281,25.0,100000.0,false,Manual,22.0",
          Content = "走吧，我们去治安署吧，那里暂时是安全的。",
          DialogueId = 10032741,
          FinalCamera = "423.821808,1344.560547,557.297852,0.000245,-21.596436,-146.647812,25.0,100000.0,false,Manual,22.0",
          GUID = "191DAC92",
          SpeakNpcId = 100304,
          Subtitle = "Let's move. We'll take you to the Security Bureau — it's the safest place for you right now.",
          TalkActionId = {
            [1] = "100304:AgreeHead",
            [2] = [[

100304:Talk03_End]]
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100327/191DAC92"
        },
        [10032801] = {
          Camera = "224.584015,-265.474854,117.003174,0.000127,4.601635,112.406464,45.0,100000.0,false,DoNotOverride,22.0",
          Content = "凶手的样貌，藏身处都知道了，你接下来准备怎么做？",
          DialogueId = 10032801,
          FacialId = {
            [1] = "100001:Confident01",
            [2] = "200021:Confident01"
          },
          FinalCamera = "234.472229,-261.296478,117.003174,0.00013,4.601635,115.207146,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB66A",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)"
          },
          NextDialogue = 10032802,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011
          },
          SpeakNpcId = 200021,
          Subtitle = "Now we know what the perp looks like and where it's hiding. What's the plan, Officer Fischer?",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB66A"
        },
        [10032802] = {
          Camera = "96.836044,171.306366,168.76709,0.000148,-7.817568,-88.797409,45.000011,100000.0,false,DoNotOverride,22.0",
          Content = "我会去下水道找凶手。",
          DialogueId = 10032802,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "191DB694",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10032803,
          SpeakNpcId = 100304,
          Subtitle = "I'll go into the sewers to find the suspect myself.",
          TalkActionId = {
            [1] = "100304:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100328/191DB694"
        },
        [10032803] = {
          Camera = "167.984818,-205.774139,131.468262,0.000253,-0.015108,101.613518,40.000011,267.396179,false,Manual,4.73068",
          Content = "上级说过，必须找到凶手“确切的藏身地”。冰湖城下水道四通八达，我想，如果只是笼统的“下水道”这条线索，他们还是不会给我支援的。",
          DialogueId = 10032803,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "171.199982,-205.113373,131.468262,0.000253,-0.015108,102.613853,40.000011,267.396179,false,Manual,4.73068",
          GUID = "191DB6BE",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10032804,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"393.642365,431.494934,343.199219,0.000233,-24.415255,-120.785851,40.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"393.642365,431.494934,343.199219,0.000232,-22.415157,-120.785835,40.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{7},ActorId{100304},AnimationId{\"Talk03_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "My superiors have made it clear — they need the suspect's exact hideout. But the Icelake sewer system is a labyrinth. If I just tell them the suspect is hiding somewhere in the sewers, they still won't grant me backup.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB6BE"
        },
        [10032804] = {
          Camera = "176.219116,20.281265,129.256104,0.000271,0.98438,-104.177605,40.0,100000.0,false,DoNotOverride,22.0",
          Content = "但是，如果我能找到那只怪物，甚至亲自与它交手……卫戍部队就再也没有理由按兵不动了。",
          DialogueId = 10032804,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "191DB6E8",
          NextDialogue = 10032805,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"192.452271,-160.383804,109.512207,0.000415,7.582159,110.635193,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"200.166122,-157.445602,109.512207,0.000415,7.582159,112.435341,35.0,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "But if I locate the monster myself — or better yet, confront it — the Escort won't have any excuses left.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100328/191DB6E8"
        },
        [10032805] = {
          Camera = "144.717804,3.13652,134.062988,0.000183,0.20246,-92.804955,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "“大人们不愿播种与耕耘，只期盼在冬天过后直接收获丰厚的果实。”",
          DialogueId = 10032805,
          FinalCamera = "145.932831,27.938095,133.975342,0.000188,0.20246,-92.805283,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB712",
          NextDialogue = 10032806,
          SpeakNpcId = 100304,
          Subtitle = "\"The grown-ups refuse to sow or plough, yet they expect a bountiful harvest come winter's end.\"",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB712"
        },
        [10032806] = {
          Camera = "176.682602,-234.133072,121.445068,0.000451,-0.819302,97.851067,40.0,294.572479,false,Manual,2.460059",
          Content = "什么？",
          DialogueId = 10032806,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "176.682602,-234.133072,121.445068,0.000451,-0.019288,97.851067,40.0,294.572479,false,Manual,2.460059",
          GUID = "191DB73C",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10032807,
          SpeakNpcId = 100001,
          Subtitle = "What was that?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB73C"
        },
        [10032807] = {
          Camera = "189.593658,127.976791,140.150879,0.000493,-4.018521,-107.357994,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "啊，我只是下意识……这是歌剧《雪国的孩子》里的一段……",
          DialogueId = 10032807,
          FacialId = {
            [1] = "100304:Doubt01",
            [2] = "100001:Confident01"
          },
          FinalCamera = "192.263779,127.142166,140.150879,0.000493,-4.018514,-108.557556,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB766",
          NextOptions = {
            [1] = 10032808,
            [2] = 10032811
          },
          RelatedWikiId = {
            [1] = 404002
          },
          Scripts = "PARA{PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain01_End\"},Duration{2}},SEQ{CameraMoveTo{_delay{5},TargetPosition{\"182.977341,-66.020782,115.567139,0.00049,8.781335,104.043732,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"186.8992,-65.072113,115.567139,0.000491,8.781335,105.843719,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}}}",
          SpeakNpcId = 100304,
          Subtitle = "Ah, that just slipped out... It's a line from the opera Children From the Snowfield...",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB766"
        },
        [10032808] = {
          Content = "原来你也早就对卫戍部队的作风不满了。",
          DialogueId = 10032808,
          GUID = "191DB790",
          NextDialogue = 10032809,
          Subtitle = "So you're not a fan of the way the Escort works, too."
        },
        [10032809] = {
          Camera = "151.968018,0.902451,133.101074,0.000211,0.200609,-95.606949,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "不是的，我没有质疑卫戍部队的意思……咳、咳！",
          DialogueId = 10032809,
          FacialId = {
            [1] = "100304:Unacceptable01"
          },
          FinalCamera = "153.395508,15.445602,133.05127,0.000211,0.200609,-95.606949,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB7BA",
          NextDialogue = 10032810,
          SpeakNpcId = 100304,
          Subtitle = "No, no— I wasn't questioning how the Escort operates... ahem!",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB7BA"
        },
        [10032810] = {
          Camera = "188.496887,-182.958466,131.04541,0.000186,4.800099,122.799866,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "不用解释了，长官，你的想法都写在脸上了。放心吧，我们不会乱嚼舌根的。",
          DialogueId = 10032810,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "193.293198,-190.400955,130.301514,0.000186,4.800099,122.799866,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB7E4",
          NextDialogue = 10032813,
          SpeakNpcId = 200021,
          Subtitle = "No need to explain, Officer Fischer. We get it. It's written all over your face. Don't worry, we won't say a word.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB7E4"
        },
        [10032811] = {
          Content = "歌剧？黎瑟长官还有这么高雅的爱好。",
          DialogueId = 10032811,
          GUID = "191DB80E",
          NextDialogue = 10032812,
          Subtitle = "An opera fan, Officer Fischer? That's quite sophisticated."
        },
        [10032812] = {
          Camera = "151.968018,0.902451,133.101074,0.000211,0.200609,-95.606949,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "算不上我的爱好，只是家人很喜欢而已。",
          DialogueId = 10032812,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "153.395508,15.445602,133.05127,0.000211,0.200609,-95.606949,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB838",
          NextDialogue = 10032813,
          SpeakNpcId = 100304,
          Subtitle = "Can't say I'm a fan. It's just something a close family member of mine enjoyed.",
          TalkActionId = {
            [1] = "100304:DisagreeHead",
            [2] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB838"
        },
        [10032813] = {
          Camera = "311.277649,-363.356415,74.417236,0.000184,5.399715,117.80748,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "不闲聊了，我该走了。",
          DialogueId = 10032813,
          FinalCamera = "317.189819,-360.27356,74.417236,0.000185,5.399715,118.407417,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB862",
          NextDialogue = 10032814,
          SpeakNpcId = 100304,
          Subtitle = "Anyway, enough small talk. I need to get moving.",
          TalkActionId = {
            [1] = "100304:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB862"
        },
        [10032814] = {
          Camera = "370.595215,492.630737,342.745361,0.000198,-23.599121,-113.79567,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "请允许我再次向你们致谢——感谢你们为卫戍部队、为冰湖城做出的一切。",
          DialogueId = 10032814,
          FinalCamera = "370.595215,492.630737,342.745361,0.000199,-22.199057,-113.795647,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB88C",
          NextDialogue = 10032815,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"209.970795,-128.235275,133.67627,0.000174,3.600794,174.404312,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"209.420944,-133.846909,133.67627,0.000174,3.600794,174.404312,35.0,100000.0,false,DoNotOverride,22.0\"},duration{3.5}}}",
          SpeakNpcId = 100304,
          Subtitle = "Allow me to thank you again — for everything you've done for the Escort and Icelake.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB88C"
        },
        [10032815] = {
          Camera = "209.420944,-133.846909,133.67627,0.000174,3.600794,174.404312,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "不过，很抱歉，还有最后两件事想要麻烦你们……",
          DialogueId = 10032815,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          GUID = "191DB8B6",
          NextDialogue = 10032816,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"253.807343,102.368408,169.783203,0.000607,-10.818787,-117.140869,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"259.912048,99.335846,169.783203,0.000607,-10.818787,-119.340866,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "But before I go... I have two final requests to make of you.",
          TalkActionId = {
            [1] = "100304:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100328/191DB8B6"
        },
        [10032816] = {
          Camera = "181.440201,117.865677,139.834473,0.000585,-1.818729,-106.351646,40.0,100000.0,false,DoNotOverride,22.0",
          Content = "这是我升准尉时得到的奖章，上面刻着我的名字。",
          DialogueId = 10032816,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "184.079407,117.058807,139.834473,0.000585,-1.818729,-107.151398,40.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB8E0",
          NextDialogue = 10032817,
          SpeakNpcId = 100304,
          Subtitle = "This is the medal I received when I was promoted to Warrant Officer. My name is engraved on it.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB8E0"
        },
        [10032817] = {
          Camera = "363.140869,-823.144897,336.696289,0.00064,-16.018269,108.05632,40.0,974.299927,false,Manual,1.2",
          Content = "第一件事是，如果我回不来，就请你们去卫戍部队下属治安署，找达米安署长，把我的……死讯告诉他，请他继续调查“卡戎狩猎”，千万不要中止。",
          DialogueId = 10032817,
          FinalCamera = "367.579041,-821.69812,336.696289,0.00064,-16.018269,108.05632,40.0,974.299927,false,Manual,1.2",
          GUID = "191DB90A",
          NextDialogue = 10032818,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"180.454208,-130.658432,129.400146,-0.001007,6.202877,169.209763,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"180.046188,-132.799576,129.400146,-0.001007,6.202877,169.209763,35.0,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "If I don't make it back, please go to the Security Bureau under the Escort and inform Chief Damian about what happened to me. Tell him the investigation into the \"Charon Hunt\" must continue, no matter what.",
          TalkActionId = {
            [1] = "100304:Explain01_End",
            [2] = "100001:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB90A"
        },
        [10032818] = {
          Camera = "190.108154,132.64003,140.636475,0.000663,-2.617219,-105.706673,45.000011,283.341888,false,Manual,4.333576",
          Content = "第二件事是，请署长帮我把这枚奖章转交给驻扎在内城的第六军团，交给一个叫布鲁斯·费西尔的年轻人。",
          DialogueId = 10032818,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "194.02652,131.538162,140.636475,0.000662,-2.617219,-107.106346,45.000011,283.341888,false,Manual,4.333576",
          GUID = "191DB934",
          NextDialogue = 10032819,
          SpeakNpcId = 100304,
          Subtitle = "And second, please have Chief Damian deliver this medal to the 6th Legion in the inner city. It's for a young man named Blues Fischer.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB934"
        },
        [10032819] = {
          Camera = "144.682556,-23.990265,132.799316,0.00741,1.181288,-93.427711,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "告诉他，不用再等姐姐了，以后的日子请他一个人坚强地走下去。",
          DialogueId = 10032819,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "146.193344,1.224564,132.279541,0.00741,1.181288,-93.429176,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB95E",
          NextDialogue = 10032820,
          SpeakNpcId = 100304,
          Subtitle = "Let him know he doesn't have to wait for his sister anymore. Tell him to stay strong and move on with his life.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:ConfidentLR_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB95E"
        },
        [10032820] = {
          Camera = "72.367409,-120.216789,137.059326,0.007411,1.581291,-2.808713,35.0,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInQuad",
          Content = "抱歉我漏了，还有第三件事是……",
          DialogueId = 10032820,
          FinalCamera = "72.092346,-125.821777,137.059326,0.007411,1.581291,-2.808713,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB988",
          NextDialogue = 10032821,
          SpeakNpcId = 100304,
          Subtitle = "Oh, and there's one more thing—",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB988"
        },
        [10032821] = {
          Camera = "113.508186,-60.045151,119.098877,0.007421,5.980657,72.403885,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "行了，没有第三件了。不，前两件也没有。",
          DialogueId = 10032821,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "113.508186,-60.045151,119.098877,0.007421,8.58065,72.804283,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB9B2",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 10032822,
          SpeakNpcId = 100001,
          Subtitle = "That's enough. There's no \"one more thing.\" In fact, we can't do the first two for you either.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB9B2"
        },
        [10032822] = {
          Camera = "120.826347,-1.616959,114.983398,0.007418,8.980496,-81.996254,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "啊……",
          DialogueId = 10032822,
          FacialId = {
            [1] = "100304:Shock01"
          },
          FinalCamera = "118.27652,16.516449,112.0896,0.007418,8.980496,-81.996254,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DB9DC",
          NextDialogue = 10032823,
          SpeakNpcId = 100304,
          Subtitle = "Ah...",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DB9DC"
        },
        [10032823] = {
          Camera = "312.308807,-216.968994,83.050049,0.007329,7.778444,126.202782,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "因为夜航者小队会和你一起去，不会让你一个人逞英雄立功的。对吧，队长？",
          DialogueId = 10032823,
          FacialId = {
            [1] = "200021:Happy01"
          },
          FinalCamera = "312.308807,-216.968994,83.050049,0.007329,5.97843,125.203247,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DBA06",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "200021:n(100001)"
          },
          NextOptions = {
            [1] = 10032824,
            [2] = 10032825
          },
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"18.183481,-25.84479,181.624756,0.007328,-16.821007,41.593891,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"20.124172,-27.936852,181.624756,0.007327,-16.821007,43.193699,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Because the Noctoyagers are going with you. No way we'd let you play the hero alone and hog all the glory. Right, Captain?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DBA06"
        },
        [10032824] = {
          Content = "嗯，就是这样。",
          DialogueId = 10032824,
          GUID = "191DBA30",
          NextDialogue = 10032826,
          Subtitle = "That's right."
        },
        [10032825] = {
          Content = "那怪物打人疼死了，我得亲自报仇才行。",
          DialogueId = 10032825,
          GUID = "191DBA5A",
          NextDialogue = 10032826,
          Subtitle = "That monster's punches hurt like hell. I need to settle the score with it myself."
        },
        [10032826] = {
          Camera = "73.926605,-238.322037,143.751465,0.00736,-3.820944,66.994003,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "天快黑了，黎瑟长官，你也不想磨磨蹭蹭的，害得今天晚上又有无辜的人被袭击吧？",
          DialogueId = 10032826,
          FinalCamera = "65.447815,-234.789932,143.750977,0.007359,-3.820944,63.794052,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DBA84",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10032827,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200002:n(100304)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "It's getting dark, Officer Fischer. You don't want to drag this out and risk another victim tonight, do you?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DBA84"
        },
        [10032827] = {
          Camera = "92.946442,268.478546,205.385986,0.007381,-16.020536,-85.002853,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "……我明白你们的意思了。那我们……出发吧。",
          DialogueId = 10032827,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "100.467682,269.136414,205.385742,0.007382,-16.020521,-86.802406,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191DBAAE",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)"
          },
          NextDialogue = 10032828,
          Scripts = "PARA{PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"AgreeHead\"},Duration{2}},PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "...I see. Let's go, then.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DBAAE"
        },
        [10032828] = {
          Camera = "112.471596,-154.705948,142.71875,0.007393,-21.019278,64.592957,35.000008,210.83786,false,Manual,6.454089",
          Content = "那个，那个……你们两个就没人好奇黎瑟长官的第三件事到底是什么吗？",
          DialogueId = 10032828,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "112.471596,-154.705948,142.71875,0.007391,-17.819143,64.792992,35.000008,210.83786,false,Manual,6.454089",
          GUID = "191DBAD8",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10032829,
          SpeakNpcId = 200002,
          Subtitle = "Wait, wait! Aren't you guys the least bit curious about what Officer Fischer's third request was?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DBAD8"
        },
        [10032829] = {
          Camera = "181.988678,85.651779,83.525391,0.007393,10.776809,-102.371201,30.0,210.83786,false,Manual,6.454089",
          Content = "哦，我原本是打算把秘密基地的钥匙给你们。我所有积蓄都放在那儿，如果我回不来，你们就可以自己拿报酬。",
          DialogueId = 10032829,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "181.988678,85.651779,88.937988,0.007396,10.776809,-102.371193,30.0,210.83786,false,Manual,6.454089",
          GUID = "191DBB02",
          LookAt = {
            [1] = "100304:n(200002)"
          },
          NextDialogue = 10032830,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"218.8479,-220.312103,76.052246,0.007326,9.376709,110.837814,30.0,210.83786,false,Manual,6.454089\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"223.453308,-218.817688,76.05249,0.007326,9.376709,113.638161,30.0,210.83786,false,Manual,6.454089\"},duration{5}}},PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"ExplainTwo_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "Oh, I was going to give you the key to my secret base. All my savings are there. If I didn't make it back, you could go there yourselves and collect your payment.",
          TalkActionId = {
            [1] = "100304:ExplainTwo_Start",
            [2] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DBB02"
        },
        [10032830] = {
          Camera = "148.493927,27.434708,144.814453,0.00731,-6.81881,-93.240387,30.0,100000.0,false,DoNotOverride,22.0",
          Content = "不过既然{nickname}那样说了，我相信以我们第一次见面时你们的实力……我们一定能平安回来的。",
          DialogueId = 10032830,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "149.026001,36.830658,145.938721,0.00731,-6.418793,-93.240837,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191DBB2C",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-764.08551,466.744812,142.1875,0.007305,-1.81905,-29.224564,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-775.528442,446.289978,142.189941,0.007305,-1.81905,-27.42462,35.0,100000.0,false,DoNotOverride,22.0\"},duration{10}}}",
          SpeakNpcId = 100304,
          Subtitle = "But since  insists, and after seeing what you're all capable of the first time we met... I trust we'll make it back together.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100328/191DBB2C"
        },
        [10032901] = {
          Content = "走这边。",
          DialogueId = 10032901,
          GUID = "191DC6D2",
          NextDialogue = 10032902,
          SpeakNpcId = 100304,
          Subtitle = "This way.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6D2"
        },
        [10032902] = {
          Content = "黎瑟长官对这里似乎很熟悉？",
          DialogueId = 10032902,
          GUID = "191DC6FC",
          NextDialogue = 10032903,
          SpeakNpcId = 100001,
          Subtitle = "Officer Fischer, you seem pretty familiar with this place.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6FC"
        },
        [10032903] = {
          Content = "这些年帝国很注重各城镇地下设施的建设，卫戍部队也要出力维护。",
          DialogueId = 10032903,
          GUID = "191DC726",
          NextDialogue = 10032904,
          SpeakNpcId = 100304,
          Subtitle = "In recent years, the Empire has heavily invested in underground infrastructure across its cities, with the escorts assisting in its maintenance.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC726"
        },
        [10032904] = {
          Content = "刚加入卫戍部队时，我每天都被安排打扫这里。",
          DialogueId = 10032904,
          GUID = "191DC750",
          NextDialogue = 10032905,
          SpeakNpcId = 100304,
          Subtitle = "When I first joined the Escort, I was assigned to clean this place every single day.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC750"
        },
        [10032905] = {
          Content = "天天清理下水道……卡戎就算加入军团也还是会被欺负吗？",
          DialogueId = 10032905,
          GUID = "191DC77A",
          NextDialogue = 10032906,
          SpeakNpcId = 100001,
          Subtitle = "Cleaning sewers every day... Does being a Charon mean you get pushed around no matter where you are, even in the Legion?",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC77A"
        },
        [10032906] = {
          Content = "偏见是根深蒂固的，但在军团至少我们还可以靠功绩来赢得尊重。",
          DialogueId = 10032906,
          GUID = "191DC7A4",
          NextDialogue = 10032907,
          SpeakNpcId = 100304,
          Subtitle = "Prejudice runs deep. But in the Legion, we at least have a chance to prove ourselves through merits and exploits.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7A4"
        },
        [10032907] = {
          Content = "这也是身为“恶魔的孩子”，偿还自己罪业的方式之一。",
          DialogueId = 10032907,
          GUID = "191DC7CE",
          NextDialogue = 10032908,
          SpeakNpcId = 100304,
          Subtitle = "It's also one way for us, as \"demon's children,\" to atone for our sins.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7CE"
        },
        [10032908] = {
          Content = "等等……你们有没有听到什么声音？",
          DialogueId = 10032908,
          GUID = "191DC7F8",
          SpeakNpcId = 200021,
          Subtitle = "Wait... Do you hear that?",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7F8"
        },
        [10032909] = {
          Content = "救，救救我……我……不想死……",
          DialogueId = 10032909,
          GUID = "191DC822",
          NextDialogue = 10032910,
          SpeakNpcId = 100321,
          Subtitle = "H—Help me... Please... I don't want to die...",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC822"
        },
        [10032910] = {
          Content = "……呼救声！我马上过来！",
          DialogueId = 10032910,
          GUID = "191DC84C",
          NextDialogue = 10032911,
          SpeakNpcId = 100304,
          Subtitle = "...That's a cry for help! I'll be right over!",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC84C"
        },
        [10032911] = {
          Content = "喂，你都不确认一下是不是陷阱吗……啧，我们也快跟上去吧。",
          DialogueId = 10032911,
          GUID = "191DC876",
          SpeakNpcId = 200021,
          Subtitle = "Whoa—! Slow down — what if it's a trap? Ugh, fine. Let's keep up with her before she does something reckless.",
          VoiceName = "voice/$Locale$/story/1003/100329/191DC876"
        },
        [10033001] = {
          Camera = "624.507812,337.115234,453.645508,0.000164,-26.398672,-154.983353,25.0,100000.0,false,Manual,22.0",
          Content = "这是什么情况？",
          DialogueId = 10033001,
          FinalCamera = "623.152344,340.018555,453.645508,0.000164,-26.39868,-154.983414,25.0,100000.0,false,Manual,22.0",
          GUID = "191DD73A",
          LookAt = {
            [1] = "200021:n(100321)",
            [2] = [[

200002:n(100321)]],
            [3] = [[

100304:n(100321)]],
            [4] = [[

100321:n(100304)]]
          },
          NextDialogue = 10033002,
          SpeakNpcId = 100001,
          Subtitle = "What's going on here?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100330/191DD73A"
        },
        [10033002] = {
          Camera = "-4.990234,-83.879883,129.222412,0.000075,-0.599486,141.201096,35.000008,100000.0,false,Manual,22.0",
          Content = "他和同伴被一只怪物逼进了下水道，他以为自己肯定活不成了，但那只怪物突然停止了追击。",
          DialogueId = 10033002,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-3.224609,-81.675781,129.222412,0.000074,-0.599486,141.601227,35.000008,100000.0,false,Manual,22.0",
          GUID = "191DD764",
          LookAt = {
            [1] = "100001:n(100304)"
          },
