          Subtitle = "Yes. They're the Noctoyagers, an excellent Phoxhunter team. Without their help, I wouldn't have made it this far.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0998"
        },
        [10033309] = {
          Content = "哇，好多人帮忙呀！哼哼，对付打伤{nickname}的坏家伙，必须出重拳！",
          DialogueId = 10033309,
          GUID = "191E09C2",
          NextDialogue = 10033310,
          SpeakNpcId = 200002,
          Subtitle = "Wow, look at all this backup! Hmm-hmm~ Time to show that monster what happens when you mess with !",
          VoiceName = "voice/$Locale$/story/1003/100333/191E09C2"
        },
        [10033310] = {
          Content = "要准备迎战了。",
          DialogueId = 10033310,
          GUID = "191E09EC",
          SpeakNpcId = 100001,
          Subtitle = "Stay alert. There's a big fight coming up ahead.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E09EC"
        },
        [10033311] = {
          Content = "吼……！",
          DialogueId = 10033311,
          GUID = "191E0A16",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "—ROAR!!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A16"
        },
        [10033312] = {
          Content = "目标并非秽兽，采取牵制战术！",
          DialogueId = 10033312,
          GUID = "191E0A40",
          NextDialogue = 10033313,
          SpeakNpcId = 100304,
          Subtitle = "The target is not a Filthoid. Use containment tactics to subdue him!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A40"
        },
        [10033313] = {
          Content = "活捉目标，还受害者一个交代！",
          DialogueId = 10033313,
          GUID = "191E0A6A",
          NextDialogue = 10033314,
          SpeakNpcId = 100304,
          Subtitle = "We need him alive. The victims deserve answers.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A6A"
        },
        [10033314] = {
          Content = "收到！",
          DialogueId = 10033314,
          GUID = "191E0A94",
          SpeakNpcId = 100344,
          Subtitle = "Copy that!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A94"
        },
        [10033315] = {
          Content = "粉……碎……",
          DialogueId = 10033315,
          GUID = "191E0ABE",
          NextDialogue = 10033316,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "CRRRRUSH...",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0ABE"
        },
        [10033316] = {
          Content = "呃啊……好大的力气……",
          DialogueId = 10033316,
          GUID = "191E0AE8",
          NextDialogue = 10033317,
          SpeakNpcId = 100345,
          Subtitle = "Argh... It's too strong...",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0AE8"
        },
        [10033317] = {
          Content = "小心！",
          DialogueId = 10033317,
          GUID = "191E0B12",
          NextDialogue = 10033318,
          SpeakNpcId = 100304,
          Subtitle = "Watch out!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B12"
        },
        [10033318] = {
          Content = "可恶……腾不出手！",
          DialogueId = 10033318,
          GUID = "191E0B3C",
          SpeakNpcId = 100304,
          Subtitle = "Darn it... I'm tied up!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B3C"
        },
        [10033319] = {
          Content = "消……除……",
          DialogueId = 10033319,
          GUID = "191E0B66",
          NextDialogue = 10033320,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "DESTRRRROY...",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B66"
        },
        [10033320] = {
          Content = "我来掩护伤员后撤，大家不要慌张。",
          DialogueId = 10033320,
          GUID = "191E0B90",
          NextDialogue = 10033321,
          SpeakNpcId = 100001,
          Subtitle = "I'll cover the retreat of the wounded. Stay focused — don't lose your nerve!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B90"
        },
        [10033321] = {
          Content = "拜托了。",
          DialogueId = 10033321,
          GUID = "191E0BBA",
          NextDialogue = 10033322,
          SpeakNpcId = 100304,
          Subtitle = "Be careful.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BBA"
        },
        [10033322] = {
          Content = "咳……谢谢。",
          DialogueId = 10033322,
          GUID = "191E0BE4",
          SpeakNpcId = 100344,
          Subtitle = "*coughs* ...Thank you.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BE4"
        },
        [10033323] = {
          Content = "奥特赛德，左边有破绽。",
          DialogueId = 10033323,
          GUID = "191E0C0E",
          NextDialogue = 10033324,
          SpeakNpcId = 100001,
          Subtitle = "Outsider, there's an opening on its left!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C0E"
        },
        [10033324] = {
          Content = "交给我。",
          DialogueId = 10033324,
          GUID = "191E0C38",
          SpeakNpcId = 200021,
          Subtitle = "I'm on it.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C38"
        },
        [10033325] = {
          Content = "牵制住了。黎瑟！",
          DialogueId = 10033325,
          GUID = "191E0C62",
          SpeakNpcId = 200021,
          Subtitle = "We've got it pinned! Rhythm, now!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C62"
        },
        [10033401] = {
          Content = "快……撤……",
          DialogueId = 10033401,
          GUID = "191E18DA",
          SpeakNpcId = 100311,
          Subtitle = "Re...Retreat...",
          VoiceName = "voice/$Locale$/story/1003/100334/191E18DA"
        },
        [10033402] = {
          Content = "……怪物……不止一只……有同伙！",
          DialogueId = 10033402,
          GUID = "191E1904",
          SpeakNpcId = 100311,
          Subtitle = "There's... more than... one monster...!",
          VoiceName = "voice/$Locale$/story/1003/100334/191E1904"
        },
        [10033403] = {
          Content = "拦住它们两个……",
          DialogueId = 10033403,
          GUID = "191E192E",
          SpeakNpcId = 100311,
          Subtitle = "Stop them...",
          VoiceName = "voice/$Locale$/story/1003/100334/191E192E"
        },
        [10033404] = {
          Content = "……不行……防线被突破了……",
          DialogueId = 10033404,
          GUID = "191E1958",
          SpeakNpcId = 100311,
          Subtitle = "We can't... they've broken through...",
          VoiceName = "voice/$Locale$/story/1003/100334/191E1958"
        },
        [10033405] = {
          Content = "营救伤员，快，先去营救伤员！",
          DialogueId = 10033405,
          GUID = "191E1982",
          SpeakNpcId = 100311,
          Subtitle = "Evacuate the wounded! Hurry! Get them out first!",
          VoiceName = "voice/$Locale$/story/1003/100334/191E1982"
        },
        [10033501] = {
