          GUID = "191E2BB8",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 10033517,
          SpeakNpcId = 200021,
          Subtitle = "Alright, since our work here's done, how about we head home and rest up?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2BB8"
        },
        [10033517] = {
          Camera = "-140.902344,-181.350952,57.819458,0.000238,9.192799,159.999252,35.000011,100000.0,false,DoNotOverride,22.0",
          Content = "唔……刚才黎瑟长官好像伤得很重诶，咱们还是先去看看她吧！",
          DialogueId = 10033517,
          FacialId = {
            [1] = "200002:Sad03"
          },
          FinalCamera = "-132.044922,-150.669006,57.819458,0.00024,9.592809,170.198151,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2BE2",
          NextDialogue = 10033518,
          Scripts = "PlayFacial{_delay{3},ActorId{200002},FacialId{\"None\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Mmm... but Officer Fischer looked really bad back there! Shouldn't we check on her first?",
          TalkActionId = {
            [1] = "200002:Bai_Think2Confident",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2BE2"
        },
        [10033518] = {
          Camera = "-69.097656,-83.115845,148.539307,0.000209,1.550528,163.935776,35.000015,100000.0,false,DoNotOverride,22.0",
          Content = "她多半被送去内城的军团医院去了。内城那地方你又不是不知道，咱们几个进不去的。",
          DialogueId = 10033518,
          FinalCamera = "-30.691406,-94.174072,147.457397,0.000209,1.550528,163.935776,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2C0C",
          LookAt = {
            [1] = "200021:n(100311)"
          },
          NextDialogue = 10033519,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"588.361328,-259.9021,29.950439,0.000221,6.195254,167.58075,35.000019,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"579.164062,-298.835632,29.950439,0.000221,5.995246,163.979752,35.000019,100000.0,false,Manual,22.0\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "She's probably been taken to the Legion Hospital in the inner city. You know how that place is — there's no way they'll just let us waltz in.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2C0C"
        },
        [10033519] = {
          Camera = "-144.302734,-80.81012,63.27771,0.000198,7.796223,-165.788574,35.000011,100000.0,false,Manual,22.0",
          Content = "先试试嘛！刚刚我们也帮了这么大的忙，说不定那些士兵会带我们去呢！",
          DialogueId = 10033519,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "-121.376953,-75.004456,60.040405,0.0002,7.796223,-165.787888,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E2C36",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 10033520,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-424.035156,-125.463745,95.406128,-0.001007,1.595539,15.6097,35.000019,505.590393,false,Manual,11.621747\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-427.814453,-110.609375,95.406128,-0.001007,1.595539,12.010799,35.000019,505.590393,false,Manual,11.621747\"},duration{5}}},PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}}}",
          SpeakNpcId = 200002,
          Subtitle = "Come on, let's at least try! We helped out a ton just now! Maybe the soldiers will help get us in.",
          TalkActionId = {
            [1] = "200002:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2C36"
        },
        [10033520] = {
          Camera = "-2.652344,-20.905457,137.411133,-0.001007,6.791995,19.24058,35.000023,505.590393,false,DoNotOverride,11.621747",
          Content = "问问看吧。毕竟……",
          DialogueId = 10033520,
          FinalCamera = "-3.791016,-17.602783,137.411133,-0.001007,6.791995,19.24058,35.000023,505.590393,false,DoNotOverride,11.621747",
          GUID = "191E2C60",
          NextOptions = {
            [1] = 10033521,
            [2] = 10033523
          },
          SpeakNpcId = 100001,
          Subtitle = "Let's give it a try. After all...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2C60"
        },
        [10033521] = {
          Content = "她答应我们的报酬还没给。",
          DialogueId = 10033521,
          GUID = "191E2C8A",
          ImprPlusId = 1006,
          NextDialogue = 10033522,
          Subtitle = "She hasn't fulfilled her promise yet."
        },
        [10033522] = {
          Camera = "-225.560547,-129.777405,118.852295,0.000196,-27.401426,176.001938,35.000011,3519.813721,false,DoNotOverride,1.257729",
          Content = "对哦……我们一开始找她，是为了让她帮你打探家人的消息！差点就忘了！",
          DialogueId = 10033522,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "-209.878906,-130.874634,127.011353,0.000196,-27.401426,176.001938,35.000011,3519.813721,false,DoNotOverride,1.257729",
          GUID = "191E2CB4",
          NextDialogue = 10033525,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"112.146484,-9.554932,152.045166,0.000209,-9.000365,-178.801422,35.000011,3519.813721,false,DoNotOverride,1.257729\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"112.146484,-9.554932,152.045166,0.000209,-12.200309,-171.200958,35.000011,3519.813721,false,DoNotOverride,1.257729\"},duration{8}}}",
          SpeakNpcId = 200002,
          Subtitle = "Oh, right! We went to her in the first place — so she could dig up info about your family. Almost forget about that part!",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2CB4"
        },
        [10033523] = {
          Content = "刚才，是她救了我。",
          DialogueId = 10033523,
          GUID = "191E2CDE",
          ImprPlusId = 1009,
          NextDialogue = 10033524,
          Subtitle = "She just saved my life."
        },
        [10033524] = {
          Content = "没关系的，保护市民是我的责任……你们没事……就好。",
          DialogueId = 10033524,
          GUID = "191E2D08",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10033524.T_Story_Recall_10033524'",
          NextDialogue = 10033525,
          SpeakNpcId = 100304,
          Subtitle = "It's alright... Protecting civilians is my duty... as long as... you're all safe...",
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D08"
        },
        [10033525] = {
          Camera = "2442.072266,-1239.279053,1486.851685,0.000195,-26.801941,154.004623,55.0,3519.813721,false,Manual,1.257729",
          Content = "好吧，好吧，听你们的。那现在就走？",
          DialogueId = 10033525,
          FinalCamera = "2433.271484,-1257.322388,1486.851562,0.000196,-27.001888,153.805222,55.0,3519.813721,false,Manual,1.257729",
          GUID = "191E2D32",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextOptions = {
            [1] = 10033526,
            [2] = 10033527
          },
          SpeakNpcId = 200021,
          Subtitle = "Alright, alright. Whatever you say. So, should we go now?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D32",
          bForbidSkipOptions = true
        },
        [10033526] = {
          Content = "嗯，走吧。先离开下水道。",
          DialogueId = 10033526,
          GUID = "191E2D33",
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Yeah, let's leave the sewers first."
        },
        [10033527] = {
          Content = "再等等吧。",
          DialogueId = 10033527,
          GUID = "191E2D34",
          NextDialogue = 10033528,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Just a second."
        },
        [10033528] = {
          Content = "行啊，那等你准备好了我们再出去。",
          DialogueId = 10033528,
          GUID = "191E2D35",
          SpeakNpcId = 200021,
          Subtitle = "Sure, whenever you're ready.",
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D35"
        },
        [10033601] = {
          Content = "咦？不是说有人在这儿接我们嘛，他们人呢？",
          DialogueId = 10033601,
          GUID = "191E39AA",
          NextDialogue = 10033602,
          SpeakNpcId = 200002,
          Subtitle = "Hmm? Weren't there supposed to be soldiers meeting us here? Where are they?",
          VoiceName = "voice/$Locale$/story/1003/100336/191E39AA"
        },
        [10033602] = {
          Content = "看这里，墙上有一大片密集的弹孔。",
          DialogueId = 10033602,
          GUID = "191E39D4",
          NextDialogue = 10033603,
          SpeakNpcId = 100001,
          Subtitle = "Look — there's a cluster of bullet holes on the wall.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E39D4"
        },
        [10033603] = {
          Content = "啧……接我们的人跟凶手撞上了？这下麻烦了啊。",
          DialogueId = 10033603,
          GUID = "191E39FE",
          NextDialogue = 10033604,
          SpeakNpcId = 200021,
          Subtitle = "Ugh... Looks like the team sent to meet us ran into the perp. This isn't good.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E39FE"
        },
        [10033604] = {
          Content = "……从弹孔的分布来看，凶手应该是往这边去了。我们也顺路去看看吧。",
          DialogueId = 10033604,
          GUID = "191E3A28",
          SpeakNpcId = 100001,
          Subtitle = "Look at the pattern of the bullet holes... The perpetrator probably went this way. Let's go.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A28"
        },
        [10033605] = {
          Content = "真是这边吗？附近什么也没有呀……",
          DialogueId = 10033605,
          GUID = "191E3A52",
          NextDialogue = 10033606,
          SpeakNpcId = 200002,
          Subtitle = "Are we sure it's this way? There's nothing here...",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A52"
        },
        [10033606] = {
          Content = "你们有没有感觉，这里的风力比其他地方强？",
          DialogueId = 10033606,
          GUID = "191E3A7C",
          NextDialogue = 10033607,
          SpeakNpcId = 100001,
          Subtitle = "Do you feel that? The wind here is stronger than in the other areas.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A7C"
        },
        [10033607] = {
          Content = "我上去看看。",
          DialogueId = 10033607,
          GUID = "191E3AA6",
          NextDialogue = 10033608,
          SpeakNpcId = 200021,
          Subtitle = "Let me get up there and have a look.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AA6"
        },
        [10033608] = {
          Content = "哈，你的感觉还挺敏锐，上面这个管道不久前才被人破坏过。",
          DialogueId = 10033608,
          GUID = "191E3AD0",
          NextDialogue = 10033609,
          SpeakNpcId = 200021,
          Subtitle = "Ha, you're pretty sharp. The pipe up here looks like it was damaged recently.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AD0"
        },
        [10033609] = {
          Content = "从管道延伸的方向来看，凶手会从前面的出口附近出来。",
          DialogueId = 10033609,
          GUID = "191E3AFA",
          NextDialogue = 10033610,
          SpeakNpcId = 200021,
          Subtitle = "Judging by the direction it leads, the perp might be heading out the next exit.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AFA"
        },
        [10033610] = {
          Content = "好，大家小心些。",
          DialogueId = 10033610,
          GUID = "191E3B24",
          SpeakNpcId = 100001,
          Subtitle = "Okay, let's keep moving and stay alert.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B24"
        },
        [10033611] = {
          Content = "咦？不是说有人在这儿接我们吗，他们人呢？",
          DialogueId = 10033611,
          GUID = "191E3B25",
          NextDialogue = 10033612,
          SpeakNpcId = 200002,
          Subtitle = "Hmm? Weren't there supposed to be soldiers meeting us here? Where are they?",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B25"
        },
        [10033612] = {
          Content = "不太对。",
          DialogueId = 10033612,
          GUID = "191E3B4E",
          NextDialogue = 10033613,
          SpeakNpcId = 200021,
          Subtitle = "Hold up... something feels off.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B4E"
        },
        [10033613] = {
          Content = "除了<H>风声</>以外什么都没有……过于安静了。",
          DialogueId = 10033613,
          GUID = "191E3B78",
          SpeakNpcId = 100001,
          Subtitle = "It's too quiet... except for the wind.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B78"
        },
        [10033701] = {
