        [10033710] = {
          Camera = "-122.579224,1156.571289,134.322327,0.000475,-0.79474,-80.193794,35.0,100000.0,false,Manual,22.0",
          Content = "算了，这已经不是委托分内的事了。小矮子先和{nickname}一起去看黎瑟。我去跟卫戍部队的人说一下这里的情况，完事就去找你们。",
          DialogueId = 10033710,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-122.579224,1156.571289,108.431885,0.000475,-0.79474,-80.193794,35.0,100000.0,false,Manual,22.0",
          GUID = "191E4B8C",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 10033711,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}},",
          SpeakNpcId = 200021,
          Subtitle = "Maybe. Either way, this is beyond what we signed up for. Button Mushroom, you go with  to check on Rhythm. I'll update the Escort on this and catch up with you later.",
          TalkActionId = {
