        },
        [10033802] = {
          Content = "小仆从小仆从，走这边。",
          DialogueId = 10033802,
          GUID = "191E5AA4",
          SpeakNpcId = 200002,
          Subtitle = "This way, Little Minion!",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5AA4"
        },
        [10033803] = {
          Content = "前方是内城，卡戎之民没有特殊许可禁止通行！",
          DialogueId = 10033803,
          GUID = "191E5ACE",
          NextDialogue = 10033804,
          SpeakNpcId = 100325,
          Subtitle = "Halt! This is the inner city. No Charons allowed in without special clearance!",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5ACE"
        },
        [10033804] = {
          Content = "哦哦，是你们啊。别那么凶，{性别：他们|她们}刚刚给卫戍部队帮了大忙。",
          DialogueId = 10033804,
          GUID = "191E5AF8",
          NextDialogue = 10033805,
          SpeakNpcId = 100325,
          Subtitle = "Oh, it's you guys. Ease up — they just did the Escort a huge favour.",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5AF8"
        },
        [10033805] = {
          Content = "你们来内城做什么？",
          DialogueId = 10033805,
          GUID = "191E5B22",
          NextDialogue = 10033806,
          SpeakNpcId = 100325,
          Subtitle = "What brings you to the inner city?",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B22"
        },
        [10033806] = {
          Content = "我们想看看黎瑟长官的状况。",
          DialogueId = 10033806,
          GUID = "191E5B4C",
          NextDialogue = 10033807,
          SpeakNpcId = 100001,
          Subtitle = "We want to check on Officer Fischer and see if she's okay.",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B4C"
        },
        [10033807] = {
          Content = "听说救回来一条命，还昏迷着。真要看她的话，我带你们进去吧。低调点，跟着我。",
          DialogueId = 10033807,
          GUID = "191E5B76",
          SpeakNpcId = 100325,
          Subtitle = "I heard she made it through, though she's still unconscious in the hospital. I can take you there. Just lay low and follow me.",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B76"
        },
        [10033901] = {
          Camera = "24.498535,102.712585,126.646484,0.000073,-6.999646,-158.394653,35.000008,100000.0,false,Manual,22.0",
          Content = "（空气中弥漫的消毒水让鼻腔感到些许的刺激，落针可闻的房间中回荡着黎瑟平缓的呼吸。）",
          DialogueId = 10033901,
          FacialId = {
            [1] = "100360:Close"
          },
          FinalCamera = "27.636719,94.549805,126.646484,0.000073,-6.799651,-160.394623,35.000008,100000.0,false,Manual,22.0",
          GUID = "191E6AE2",
          NextDialogue = 10033902,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011
          },
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-69.343262,549.935181,167.714844,0.000155,-3.198639,-29.731237,35.000015,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-39.04248,602.994751,167.714844,0.000155,-3.398593,-32.931664,35.000015,100000.0,false,Manual,22.0\"},duration{4}}}",
          Subtitle = "(The faint sting of disinfectant fills the air. In the stillness of the room, Rhythm's steady breathing is the only sound.)",
          TalkActionId = {
            [1] = "100360:Lise_Lieidle"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6AE2"
        },
        [10033902] = {
          Camera = "165.0,2.0,359.658203,-179.994263,-87.068275,81.286964,35.000019,100000.0,false,Manual,22.0",
          Content = "（她的面色平静。如果不是骇人的伤口，甚至会让人误以为她只是陷入了一场宁静的梦——毕竟，她还是一个如此年轻的女孩子，本应是在可以做梦的年纪。）",
          DialogueId = 10033902,
          FinalCamera = "165.0,2.0,318.0,-165.594345,-87.068413,81.287193,35.000019,100000.0,false,Manual,22.0",
          GUID = "191E6B0C",
          NextDialogue = 10033903,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"236.759277,8.561646,82.060547,-0.001007,3.71761,179.18042,35.000019,68.10289,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"236.621582,-1.383545,82.060547,-0.001007,3.71761,179.18042,35.000019,68.10289,false,Manual,22.0\"},duration{8}}}",
          Subtitle = "(She looks peaceful. Were it not for the horrific wounds, one might mistake her for a girl lost in a tranquil dream — after all, she is so young, still at an age for dreams.)",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B0C"
        },
        [10033903] = {
          Camera = "440.781738,-108.77594,198.904297,0.000069,-9.407048,145.046661,35.000019,581.174438,false,Manual,1.203584",
          Content = "看来一时半会儿是醒不了了。",
          DialogueId = 10033903,
          FacialId = {
            [1] = "100001:Confident01",
            [2] = "200021:Think01"
          },
          FinalCamera = "437.213867,-113.824066,198.904297,0.000069,-9.407048,144.44664,35.000019,581.174438,false,Manual,1.203584",
          GUID = "191E6B36",
          NextDialogue = 10033904,
          Scripts = "MoveTo{ActorId{200021},TargetPoint{\"Point01\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Doesn't look like she's doing too well.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B36"
        },
        [10033904] = {
          Camera = "15.115234,180.011108,131.390625,0.000063,-23.806725,38.66003,35.000019,100000.0,false,DoNotOverride,22.0",
          Content = "呀！你走路怎么没声音的。",
          DialogueId = 10033904,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-118.733887,89.56427,200.0,0.000064,-24.006701,40.061115,35.000019,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6B60",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10033905,
          SpeakNpcId = 200002,
          Subtitle = "Eek! How come you walk like a cat? Not a single sound at all...",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.25,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B60"
        },
        [10033905] = {
          Camera = "33.217773,125.854919,134.521484,0.000093,2.393059,111.061989,35.000015,100000.0,false,DoNotOverride,22.0",
          Content = "你来了，跟那群内城士兵说清楚情况了？",
          DialogueId = 10033905,
          FinalCamera = "17.6875,121.21051,134.521484,0.000088,1.993083,104.461479,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6B8A",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "200002:n(200002)",
            [3] = "200021:n(200021)"
          },
          NextDialogue = 10033906,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"142.0,-84.0,101.0,0.000097,5.591923,124.053864,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"133.336426,-89.81842,101.0,0.000097,5.591923,121.254005,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "There you are, Outsider. Did you manage to report the situation about the poison to the inner city soldiers?",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B8A"
        },
        [10033906] = {
          Camera = "-21.286133,28.451904,241.835938,0.000052,-28.808077,103.452721,35.000015,100000.0,false,DoNotOverride,22.0",
          Content = "嗯，费半天劲可算是解释清楚了，她这咋样了？",
          DialogueId = 10033906,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "-21.286133,28.451904,241.835938,0.000062,-28.408081,97.652969,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6BB4",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10033907,
          Scripts = "PARA{LookAt{_delay{4},LookAtDescription{\"200021:n(200021)\"}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-280.063477,458.90332,239.466797,0.000107,-17.405077,-43.745438,35.000023,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-280.063477,458.90332,239.466797,0.000104,-15.204923,-43.745186,35.000023,100000.0,false,DoNotOverride,22.0\"},duration{5}}}}",
          SpeakNpcId = 200021,
          Subtitle = "Yeah, took a while, but they finally got it. How's she holding up?",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6BB4"
        },
        [10033907] = {
          Camera = "-81.523438,283.592834,150.683594,0.00011,-8.204743,-37.341213,35.000023,332.760406,false,Manual,4.091501",
          Content = "说是已经脱离了危险，但……现在看起来丝毫没有要醒来的迹象。",
          DialogueId = 10033907,
          FinalCamera = "-84.269043,279.994141,150.683594,0.000113,-8.204743,-35.341167,35.000023,332.760406,false,Manual,4.091501",
          GUID = "191E6BDE",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200021:n(100360)"
          },
          NextDialogue = 10033908,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"211.149902,-1.937378,87.357422,0.000139,7.79136,141.059586,35.000019,350.177124,false,Manual,2.141533\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"208.573242,-5.074341,87.357422,0.000137,7.79136,140.259949,35.000019,350.177124,false,Manual,2.141533\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "They said she's stable, but... it doesn't look like she'll wake up anytime soon.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6BDE"
        },
        [10033908] = {
          Camera = "106.286621,81.659973,136.853516,0.000117,2.589987,156.447357,35.000023,100000.0,false,DoNotOverride,22.0",
          Content = "会醒的。",
          DialogueId = 10033908,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "106.286621,81.659973,136.853516,0.000117,4.390008,156.447113,35.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6C08",
          NextDialogue = 10033909,
          SpeakNpcId = 200021,
          Subtitle = "She will.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C08"
        },
        [10033909] = {
          Camera = "35.591309,171.008667,116.136719,0.000114,-15.807728,48.257145,35.000011,100000.0,false,DoNotOverride,22.0",
          Content = "咦——你居然懂医术！",
          DialogueId = 10033909,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "17.802734,151.073669,123.701172,0.000114,-15.807707,48.257084,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6C32",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10033910,
          SpeakNpcId = 200002,
          Subtitle = "Why? Don't tell me you are also a medicine expert!",
          TalkActionId = {
            [1] = "200002:Bai_Talk03Quick"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C32"
        },
        [10033910] = {
          Camera = "461.0,-36.0,227.0,0.000208,-7.596256,153.67186,40.000011,699.855347,false,Manual,1.599285",
          Content = "我不太懂医术，但我懂一点人心。",
          DialogueId = 10033910,
          FinalCamera = "461.0,-36.0,234.0,0.000208,-7.596256,153.67186,40.000011,699.855347,false,Manual,1.599285",
          GUID = "191E6C5C",
          LookAt = {
            [1] = "200002:n(100360)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10033911,
          Scripts = "PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Not at all. It's just that I read people.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C5C"
        },
        [10033911] = {
          Camera = "22.721191,147.070129,213.337891,14.478269,-31.792528,169.829453,40.000027,699.855347,false,DoNotOverride,1.599285",
          Content = "看她的双手，那是常年高强度工作的人才会有的老茧。她是个认真的好士兵。",
          DialogueId = 10033911,
          FinalCamera = "22.27002,142.886963,212.416016,14.479208,-31.792534,167.828476,40.000027,699.855347,false,DoNotOverride,1.599285",
          GUID = "191E6C86",
          NextDialogue = 10033912,
          SpeakNpcId = 200021,
          Subtitle = "Look at her hands — calloused, roughened. Those come from years of hard work. She's indeed a dedicated soldier.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C86"
        },
        [10033912] = {
          Camera = "-147.882324,242.155945,207.876953,0.000033,-21.398981,-37.788219,35.0,699.855347,false,DoNotOverride,1.599285",
          Content = "而且她还是个固执的笨家伙。那双充满干劲的眼睛是我最烦的，因为这种人不知道放弃和变通，非得把自己搞得头破血流才知道疼。",
          DialogueId = 10033912,
          FinalCamera = "-147.882324,242.155945,207.876953,0.000033,-18.398855,-37.787617,35.0,699.855347,false,DoNotOverride,1.599285",
          GUID = "191E6CB0",
          NextDialogue = 10033913,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"91.999512,-31.641846,83.878906,0.000177,0.801796,22.820667,35.0,699.855347,false,DoNotOverride,1.599285\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"89.305664,-25.238281,83.878906,0.000177,0.801796,22.820667,35.0,699.855347,false,DoNotOverride,1.599285\"},duration{8}}}",
          SpeakNpcId = 200021,
          Subtitle = "And those eyes of hers — always so stubborn and full of determination. People like that never know when to stop or take an easier way out. They always have to push until they hurt themselves badly.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6CB0"
        },
        [10033913] = {
          Camera = "134.203613,109.259399,124.238281,-0.000946,6.40391,164.582108,35.000011,699.855347,false,DoNotOverride,1.599285",
          Content = "正因如此，在解决“卡戎狩猎”之前，她是不会就此一睡不醒的。而我们现在要做的，就是好好休息，慢慢等她醒。",
          DialogueId = 10033913,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "135.833008,115.049255,124.238281,-0.000946,6.40391,166.781784,35.000011,699.855347,false,DoNotOverride,1.599285",
          GUID = "191E6CDA",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"624.469238,-61.893066,498.599609,-0.000946,-36.395668,162.188492,35.000011,699.855347,false,DoNotOverride,1.599285\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"624.469238,-61.893066,498.599609,-0.000946,-30.996033,156.988922,35.000008,699.855347,false,DoNotOverride,1.599285\"},duration{12}}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"ConfidentLR_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "So she's not going to stay down for long. She'll drag herself back into the fight before the \"Charon Hunt\" case is resolved. For now, all we have to do is have a good rest and wait for her to wake up.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6CDA"
        },
        [10033914] = {
          Camera = "29.499023,114.307373,105.529053,0.000116,2.145451,-109.253723,35.000011,173.868729,false,Manual,7.109471",
          Content = "姐姐……姐姐！",
          DialogueId = 10033914,
          FacialId = {
            [1] = "100357:None"
          },
          FinalCamera = "32.957031,113.430908,105.529053,0.000117,2.145451,-112.853188,35.000011,173.868729,false,Manual,7.109471",
          GUID = "191E6D04",
          NextDialogue = 10033915,
          Scripts = [[
PARA{
SetLocation{ActorId{100357},TargetPoint{"cp2fixsimple25-26Point01"},Visibility{"Show"}},
PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Streak_01.MI_PP_Streak_01'"}}
}]],
          SpeakNpcId = 100357,
          Subtitle = "Rhythm... Rhythm!",
          TalkActionId = {
            [1] = "100359:Sigh_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D04"
        },
        [10033915] = {
          Camera = "-5.026367,70.663574,102.933838,0.000149,13.144316,90.151543,35.000019,17.340178,false,Manual,12.691343",
          Content = "布鲁斯……？别喊了，我再眯一会儿……",
          DialogueId = 10033915,
          FacialId = {
            [1] = "100359:Sad01"
          },
          FinalCamera = "-6.173828,70.660889,102.933838,0.000148,13.144316,89.751526,35.000019,17.340178,false,Manual,12.691343",
          GUID = "191E6D2E",
          NextDialogue = 10033916,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"138.259766,246.894287,49.095703,0.000111,7.945723,-128.444931,35.000015,329.660828,false,Manual,2.012213\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"138.259766,246.894287,49.095703,0.000112,12.545684,-128.244171,35.000015,207.928787,false,Manual,2.012213\"},duration{5}}},PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Sigh_End\"},Duration{2}}}",
          SpeakNpcId = 100359,
          Subtitle = "Blues...? Keep it down... I'm so sleepy...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D2E"
        },
        [10033916] = {
          Camera = "526.81543,176.885864,156.60498,0.000122,-6.853343,-167.440613,35.000008,563.148376,false,Manual,1.225325",
          Content = "真是的，姐姐又在白天睡大觉——明天就要考试了！你还记得刚才我讲到哪儿了吗？",
          DialogueId = 10033916,
          FinalCamera = "530.197266,161.683472,156.60498,0.000122,-6.85333,-167.240479,35.000008,563.148376,false,Manual,1.225325",
          GUID = "191E6D58",
          NextDialogue = 10033917,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"26.428711,93.085571,95.163818,0.000168,4.34385,-109.880463,35.000015,126.514526,false,Manual,7.109471\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"26.289062,92.703491,95.163818,0.000167,7.343805,-110.680161,35.000015,126.514526,false,Manual,7.109471\"},duration{5}}}",
          SpeakNpcId = 100357,
          Subtitle = "Seriously, you're napping in the middle of the day again? The test's tomorrow! Do you even remember where I left off?",
          TalkActionId = {
            [1] = "100357:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D58"
        },
        [10033917] = {
          Camera = "46.933594,-142.992432,70.192139,0.000176,5.9446,109.526016,35.000011,306.744568,false,Manual,7.109471",
          Content = "好像是……卡戎之民的……“罪业”？那、那是什么来着……",
          DialogueId = 10033917,
          FacialId = {
            [1] = "100359:Think01"
          },
          FinalCamera = "46.933594,-142.992432,79.62915,0.000177,5.9446,109.526001,35.000011,306.744568,false,Manual,7.109471",
          GUID = "191E6D82",
          NextDialogue = 10033918,
          Scripts = "PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100359,
          Subtitle = "Uh... something about the Charons'... \"sins\"? Yes, what was that again?",
          TalkActionId = {
            [1] = "100359:Explain02_Start",
            [2] = "100357:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D82"
        },
        [10033918] = {
          Camera = "8.995117,69.829834,100.221191,0.000187,6.743834,-101.07547,35.000015,106.301834,false,Manual,7.109471",
          Content = "唉，一看姐姐你上课就又偷懒了。",
          DialogueId = 10033918,
          FacialId = {
            [1] = "100357:Smile01"
          },
          FinalCamera = "18.592773,67.906982,100.221191,0.000188,6.743834,-106.47596,35.000015,106.301834,false,Manual,7.109471",
          GUID = "191E6DAC",
          NextDialogue = 10033919,
          SpeakNpcId = 100357,
          Subtitle = "Ugh, figures you've been slacking off in class again.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6DAC"
        },
        [10033919] = {
          Camera = "22.104492,41.488037,139.45166,10.816259,-23.854141,115.722862,35.000023,106.301834,false,DoNotOverride,7.109471",
          Content = "嘿嘿……晚上工作太困了……这不是还有布鲁斯你给我补课嘛。",
          DialogueId = 10033919,
          FacialId = {
            [1] = "100359:Ahaha01"
          },
          FinalCamera = "14.884766,37.489014,138.013672,10.817234,-22.054098,108.921974,35.000023,106.301834,false,DoNotOverride,7.109471",
          GUID = "191E6DD6",
          NextDialogue = 10033920,
          SpeakNpcId = 100359,
          Subtitle = "Hehe... working at night always leaves me too sleepy for school the next day... But hey, that's what I've got you for — my personal tutor!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6DD6"
        },
        [10033920] = {
          Camera = "105.572266,235.572021,152.555908,-0.000184,-12.201387,-122.479736,35.000015,106.301834,false,DoNotOverride,7.109471",
          Content = "唉，工作的话我也在一起做呀。我们总共就没两年书可读，你还不好好听讲……回到卡戎的“罪业”上来，那还得从<H>“泪湖之夜”</>说起……",
          DialogueId = 10033920,
          FinalCamera = "119.550781,226.407837,152.555908,-0.000183,-12.201387,-127.679604,35.000015,106.301834,false,DoNotOverride,7.109471",
          GUID = "191E6E00",
          NextDialogue = 10033921,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"57.916016,117.509399,78.924561,-0.000183,9.39821,-114.472267,35.000019,106.301834,false,DoNotOverride,7.109471\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"62.908203,115.10022,78.924561,-0.000182,9.398203,-117.471146,35.000019,106.301834,false,DoNotOverride,7.109471\"},duration{10}}},PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 100357,
          Subtitle = "*sigh* I had to work too, but you don't see me nodding off in class. We only get a few years of schooling... How can you just waste them like that? Anyway — the Charons' \"sins.\" It all started from the \"Night of Lamenting Lake.\"",
          TalkActionId = {
            [1] = "100357:Angry01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E00"
        },
        [10033921] = {
          Camera = "21.583984,37.977295,146.400635,-0.000183,-24.001146,-114.668968,35.000015,106.301834,false,DoNotOverride,7.109471",
          Content = "一千年前，就在我们的冰湖城，长着犄角的“恶魔”们——卡戎之民，假装和索拉之民一起在泪湖畔举行庆典，却在庆典那夜干了很坏很坏的事！在场的索拉人几乎都被杀掉了……",
          DialogueId = 10033921,
          FacialId = {
            [1] = "100357:Sad01"
          },
          FinalCamera = "21.583984,37.977295,146.400635,-0.000187,-19.60116,-115.469559,35.000015,106.301834,false,DoNotOverride,7.109471",
          GUID = "191E6E2A",
          NextDialogue = 10038401,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"208.77832,286.108398,72.5625,-0.000182,9.583554,-134.240799,35.000023,106.301834,false,DoNotOverride,7.109471\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"208.77832,286.108398,72.5625,-0.000183,3.783597,-132.241501,35.000023,106.301834,false,DoNotOverride,7.109471\"},duration{10}}}",
          SpeakNpcId = 100357,
          Subtitle = "A thousand years ago, right here in Icelake, the horned \"demons\" — the Charons — pretended to join the Solarians for a lakeside festival. But that very night, they did something terrible... Nearly every Solarian there was slaughtered.",
          TalkActionId = {
            [1] = "100359:Explain02_End",
            [2] = "100357:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2A"
        },
        [10033922] = {
          Camera = "23.90625,145.747559,110.425293,-0.000397,-0.998471,-109.465141,35.000019,183.023834,false,Manual,5.506591",
          Content = "但因为“泪湖之夜”的过错，卡戎的后代必须用自己的人生，去偿还祖先犯下的罪。",
          DialogueId = 10033922,
          FacialId = {
            [1] = "100357:None"
          },
          FinalCamera = "28.929688,143.939087,110.425293,-0.000397,-0.998471,-111.464867,35.000019,183.023834,false,Manual,5.506591",
          GUID = "191E6E54",
          NextDialogue = 10033923,
          SpeakNpcId = 100357,
          Subtitle = "That's why... for the crime of the \"Night of Lamenting Lake\", every Charon born since must carry the burden of that sin for the rest of their lives.",
          TalkActionId = {
            [1] = "100357:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E54"
        },
        [10033923] = {
          Camera = "104.679688,-172.143555,57.492432,-0.000398,7.801148,118.534103,35.000015,301.429138,false,Manual,2.621887",
          Content = "可是可是，都过去这么久了……我们还是要花上一辈子去赎罪吗？",
          DialogueId = 10033923,
          FacialId = {
            [1] = "100359:Sad01"
          },
          FinalCamera = "104.679688,-172.143555,57.492432,-0.000396,11.201155,119.733948,35.000015,301.429138,false,Manual,2.621887",
          GUID = "191E6E7E",
          NextDialogue = 10033924,
          SpeakNpcId = 100359,
          Subtitle = "But... it's been so long. Do we really have to spend our whole lives paying for something we didn't do?",
          TalkActionId = {
            [1] = "100357:Talk02_End",
            [2] = "100359:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E7E"
        },
        [10033924] = {
          Camera = "12.585938,79.568848,100.525391,-0.000396,5.199898,-102.469757,35.000015,117.480644,false,Manual,2.621887",
          Content = "没错，我们只能偿还……但要是能加入军团，成为海伯利亚忠诚的战士，甚至当上<H>桂冠卡戎</>，我们的生活或许……会变得不一样吧。",
          DialogueId = 10033924,
          FacialId = {
            [1] = "100357:Smile01"
          },
          FinalCamera = "19.641602,78.040527,100.525391,-0.000396,5.199898,-105.269951,35.000015,117.480644,false,Manual,2.621887",
          GUID = "191E6EA8",
          NextDialogue = 10033925,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"1843.746094,1290.007935,347.944092,-0.000397,-5.799684,-147.667007,55.0,2176.124023,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"1859.686523,1264.762573,347.944092,-0.000396,-5.799684,-148.066879,55.0,2176.124023,false,Manual,1.2\"},duration{10}}}",
          SpeakNpcId = 100357,
          Subtitle = "Yes. Repayment is all we can do... But if we join the Legion, become loyal soldiers of Hyperborea, or even earn the title of Laurelled Charon... Maybe things could change for us then.",
          TalkActionId = {
            [1] = "100359:Think_End",
            [2] = "100357:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6EA8"
        },
        [10033925] = {
          Camera = "42.208008,-128.189453,108.011963,-0.000397,-1.200132,110.128555,35.000015,246.756485,false,Manual,2.621887",
          Content = "布鲁斯一定可以的！",
          DialogueId = 10033925,
          FacialId = {
            [1] = "100359:Smile01"
          },
          FinalCamera = "54.620117,-123.871338,108.011963,-0.000397,-1.200132,115.327736,35.000015,246.756485,false,Manual,2.621887",
          GUID = "191E6ED2",
          NextDialogue = 10033926,
          SpeakNpcId = 100359,
          Subtitle = "You'll make it, Blues! I believe in you!",
          TalkActionId = {
            [1] = "100359:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6ED2"
        },
        [10033926] = {
          Camera = "476.704102,389.137207,151.945068,-0.000397,-7.999592,-144.868225,35.000015,663.789307,false,Manual,2.430077",
          Content = "有姐姐这句话，第六军团的考核感觉也没那么难了呢。",
          DialogueId = 10033926,
          FinalCamera = "488.553711,372.130981,151.945068,-0.000396,-7.999592,-147.467621,35.000015,663.789307,false,Manual,2.430077",
          GUID = "191E6EFC",
          NextDialogue = 10033927,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"75.076172,205.711304,152.616455,-0.000396,-13.799529,-118.663506,35.000015,265.940674,false,Manual,2.430077\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"85.417969,200.057251,152.616455,-0.000397,-13.799529,-123.663765,35.000015,265.940674,false,Manual,2.430077\"},duration{5}}}",
          SpeakNpcId = 100357,
          Subtitle = "Haha, with your faith in me, the 6th Legion's entrance tests don't seem so daunting anymore.",
          TalkActionId = {
            [1] = "100357:Think_End",
            [2] = "100359:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6EFC"
        },
        [10033927] = {
          Camera = "-9.589844,56.781738,104.453369,-0.000398,6.400085,-90.263626,35.000015,87.994987,false,Manual,4.21821",
          Content = "那么，今天的费西尔家庭小课堂就在我动听的口琴声中下课吧……咦，我的口琴呢？",
          DialogueId = 10033927,
          FacialId = {
            [1] = "100357:Ahaha01"
          },
          GUID = "191E6F26",
          NextDialogue = 10033928,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{100357},AnimationId{"BulusiY_Story_Find02_Start"},Duration{2}},
CameraMoveTo{_delay{4},TargetPosition{"-77.882812,47.860352,154.744873,-0.000397,-34.599674,-51.263714,35.000019,87.994987,false,Manual,4.21821"},duration{0}}
}]],
          SpeakNpcId = 100357,
          Subtitle = "Well, let's wrap up today's Fischers Tutorial with a beautiful tune from my harmonica... Wait, where is it?",
          VoiceName = "voice/$Locale$/story/1003/100339/191E6F26"
        },
        [10033928] = {
          Camera = "-64.916992,-23.831787,104.750732,-0.000397,2.599297,64.942268,35.000015,143.102722,false,Manual,4.21821",
          Content = "早就说了，给口琴加一条皮绳或者链子什么的……算了，你肯定又要说太贵了不划算，之后我做一条送给你好啦。",
          DialogueId = 10033928,
          FacialId = {
            [1] = "100359:Smile01"
          },
          GUID = "191E6F50",
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-577.176758,-950.747559,611.587524,-0.000397,-25.999912,59.331665,35.000015,1582.272949,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-715.947266,-855.034424,611.588623,-0.000397,-25.799891,50.531769,35.000015,1582.272949,false,Manual,22.0\"},duration{10}}},PlayAnimation{_delay{4},ActorId{100359},AnimationId{\"Explain02_End\"},Duration{2}},PlayAnimation{_delay{8},ActorId{100359},AnimationId{\"Talk01_Start\"},Duration{2}}}",
          SpeakNpcId = 100359,
          Subtitle = "I told you to tie a strap or chain to it ages ago... But no, it was \"too expensive\" and \"not worth it.\" ...Fine, I'll make one for you.",
          TalkActionId = {
            [1] = "100359:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100339/191E6F50"
        },
        [10033929] = {
          Camera = "-404.671875,994.436401,134.542236,0.000085,-1.772489,-64.911392,35.000011,1107.309814,false,Manual,1.349087",
          Content = "工厂那边怎么说？",
          DialogueId = 10033929,
          FacialId = {
