        [10033964] = {
          Camera = "131.790039,122.645935,122.564453,0.000205,6.79308,168.303848,35.000015,364.535095,false,DoNotOverride,1.2",
          Content = "别动别动别动，你不会又想自己跑一趟那个下水道吧？你们军团的人在那搜着呢，你还病着，别去添乱了。",
          DialogueId = 10033964,
          FinalCamera = "133.391602,129.9245,122.564453,0.000205,6.79308,170.903305,35.000015,364.535095,false,DoNotOverride,1.2",
          GUID = "191E7538",
          NextDialogue = 10033965,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"282.059082,49.649109,102.980469,0.000203,6.593188,170.706314,35.000011,364.535095,false,Manual,3.069153\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"282.754395,53.502625,102.980469,0.000204,6.593188,172.306107,35.000011,364.535095,false,Manual,3.069153a\"},duration{6}}},PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Whoa, easy! Don't tell me you're thinking about diving back into that sewer. Your squad's already on it, and you're supposed to be resting. You're not going to help anyone in your condition.",
