          Scripts = "PlayAnimation{_delay{4},ActorId{100001},AnimationId{\"Talk03_End\"},Duration{1}}",
          SpeakNpcId = 100360,
          Subtitle = "I'm in no condition to do much for you right now, but I can at least write a few letters to ask for help on your behalf.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7634"
        },
        [10033971] = {
          Content = "他们可靠吗？",
          DialogueId = 10033971,
          GUID = "191E765E",
          ImprPlusId = 1006,
          NextDialogue = 10033972,
          Subtitle = "Can I trust them?"
        },
        [10033972] = {
          Camera = "326.638672,-43.474365,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          Content = "嗯，虽然数量很少，但愿意帮助卡戎之民的人，还是存在的。",
          DialogueId = 10033972,
          FinalCamera = "322.354492,-50.202484,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E7688",
          NextDialogue = 10033975,
          SpeakNpcId = 100360,
          Subtitle = "Yes. Though few in number, there are still some who are willing to lend a hand to the Charons.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7688"
        },
        [10033973] = {
          Content = "……你现在这样子还在想着帮我？",
          DialogueId = 10033973,
          GUID = "191E76B2",
          ImprPlusId = 1009,
          NextDialogue = 10033974,
          Subtitle = "...Even in a hospital bed, you're still thinking about helping me?"
        },
        [10033974] = {
          Camera = "326.638672,-43.474365,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          Content = "这是我的职责。而我自己也希望你能和家人团聚。",
          DialogueId = 10033974,
          FinalCamera = "322.354492,-50.202484,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E76DC",
          NextDialogue = 10033975,
          SpeakNpcId = 100360,
          Subtitle = "I made a promise. Besides, I truly hope you'll reunite with your family.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_End",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E76DC"
        },
        [10033975] = {
          Camera = "301.869629,98.541199,115.601562,0.000116,3.196139,162.306015,40.000011,367.813141,false,Manual,1.2",
          Content = "那我们就收下这份好意吧。",
          DialogueId = 10033975,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "304.80127,107.63208,115.601562,0.000116,3.196132,163.505875,40.000011,367.813141,false,Manual,1.2",
          GUID = "191E7706",
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-321.128418,431.440491,273.042969,0.000077,-18.603077,-39.290245,40.0,364.535095,false,DoNotOverride,3.069153\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-354.362305,458.634705,287.5,0.000077,-18.603077,-39.290245,40.0,364.535095,false,DoNotOverride,3.069153\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "Alright, we shall gladly accept your help, then.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7706"
        },
        [10034001] = {
          Content = "军人的秘密基地啊，会是什么样子呢，感觉很刺激！",
          DialogueId = 10034001,
          GUID = "191E7B4A",
          NextDialogue = 10034002,
          SpeakNpcId = 200002,
          Subtitle = "A soldier's secret base? I bet it's packed with cool stuff! This is so exciting!",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B4A"
        },
        [10034002] = {
          Content = "钥匙上写的地方，好像是公路那个中转站附近啊。",
          DialogueId = 10034002,
          GUID = "191E7B74",
          NextDialogue = 10034003,
          SpeakNpcId = 200021,
          Subtitle = "The address points to somewhere near the roadside freight station.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B74"
        },
        [10034003] = {
          Content = "居然把秘密基地建在这种地方吗……",
          DialogueId = 10034003,
          GUID = "191E7B9E",
          NextDialogue = 10034004,
          SpeakNpcId = 100001,
          Subtitle = "She actually built her secret base in a place like that?",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B9E"
        },
        [10034004] = {
          Content = "大家都会钻到在一些常人无法理解的地方给自己找个独处的避风港……",
          DialogueId = 10034004,
          GUID = "191E7BC8",
          NextDialogue = 10034005,
          SpeakNpcId = 200021,
          Subtitle = "People tend to pick the oddest spots for their hideaways...",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BC8"
        },
        [10034005] = {
          Content = "有人是车里，有人是管道，所以把那种地方当做秘密基地很正常吧。",
          DialogueId = 10034005,
          GUID = "191E7BF2",
          NextDialogue = 10034006,
          SpeakNpcId = 200021,
          Subtitle = "Some use cars, some find old pipes... A roadside freight station? Seems pretty normal to me.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BF2"
        },
        [10034006] = {
          Content = "呃……很正常吧，不会只有我小时候喜欢到处乱钻吧？",
          DialogueId = 10034006,
          GUID = "191E7C1C",
          SpeakNpcId = 200021,
          Subtitle = "Uh... please tell me I'm not the only one who used to crawl into random places as a kid.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C1C"
        },
        [10034007] = {
          Content = "就是这里？",
          DialogueId = 10034007,
          GUID = "191E7C46",
          NextDialogue = 10034008,
          SpeakNpcId = 100001,
          Subtitle = "Is this it?",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C46"
        },
        [10034008] = {
          Content = "入口应该就在这附近，找找看吧。",
          DialogueId = 10034008,
          GUID = "191E7C70",
          SpeakNpcId = 200021,
          Subtitle = "The entrance should be near. Let's look around.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C70"
        },
        [10034101] = {
          Camera = "-1302.09375,188.645508,676.1875,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          Content = "哦？看来是拿废弃检修间改的啊。",
          DialogueId = 10034101,
          FinalCamera = "-1145.925781,162.691406,610.441406,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BB2",
          NextDialogue = 10034102,
          SpeakNpcId = 200021,
          Subtitle = "Hmm, looks like this place used to be an old maintenance room.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToExplainR_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BB2"
        },
        [10034102] = {
          Camera = "330.632812,-30.893555,59.353516,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          Content = "这不就跟白乱糟糟的房间，不是，魔王的豪华寝室差不多嘛！",
          DialogueId = 10034102,
          FacialId = {
            [1] = "200002:Doubt01",
            [2] = "200021:Angry01",
            [3] = "100001:Doubt01"
          },
          FinalCamera = "330.792969,-23.540039,59.5625,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BDC",
          NextDialogue = 10034103,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, this place is kind of like my messy... I mean, the Demon King's grand chamber!",
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "200021:ConfidentLRToExplainR_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BDC"
        },
        [10034103] = {
          Camera = "-157.855469,20.635742,139.306641,1.753745,-2.15362,-32.439327,35.000015,199.365784,false,DoNotOverride,8.0",
          Content = "分头找找看吧，银色的印章。",
          DialogueId = 10034103,
          FinalCamera = "-148.238281,18.021484,147.634766,1.753745,-4.553892,-31.638124,35.000011,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8C06",
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"cp2fixsimple30Point01\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's split up and look for the silver seal.",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C06"
        },
        [10034104] = {
          Content = "皇帝尾戒勋章，完全由纯金打造，只会颁发给为帝国做出卓越贡献的军人。\n\n科赛托斯行省冰湖城第六军团下属卫戍部队，<H>黎瑟·费西尔</>。\n在连年、数次<H>清缴秽兽作战</>中，决策果断，作战英勇，收尾迅速。\n在维护地区治安的过程中起到了无可比拟的关键作用。\n现经军团评估，以吾皇尤里乌斯之名，授予黎瑟·费西尔帝皇尾戒勋章及准尉军衔，望广大军人以其为榜样，奋发上进，共同成长。\n荣耀尽归吾皇。",
          DialogueId = 10034104,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000047;content:READ_TEXT_2000047}",
          GUID = "191E8C30",
          Subtitle = [[
Recipient: Rhythm Fischer, serving in the Icelake Escort under the 6th Legion in the Cocytus Region.
For demonstrating decisive leadership, exemplary bravery, and exceptional efficiency in multiple Filthoid-clearing operations over the years.
For playing an irreplaceable role in maintaining public order and ensuring the safety of the region.
Upon the assessment of the Legion, and by the decree of His Majesty Julius, Rhythm Fischer is hereby awarded the Emperor's signet ring and the rank of Warrant Officer. Let her serve as an inspiration to all soldiers, urging them to strive ever higher for the Empire's glory.
All glory to our Emperor.]],
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C30"
        },
        [10034105] = {
          Content = "石灰墙的一角用小刀刻满了密密麻麻的字，有的歪歪扭扭，似是孩童的字迹；有些已经成熟，像是成年人所写。这些字都是同一句话：\n“我不会再看着任何人被秽兽杀死。”",
          DialogueId = 10034105,
          GUID = "191E8C5A",
          Subtitle = "One corner of the limewashed wall is covered in countless etched words. Some are crooked and childlike, while others are firm and deliberate, clearly written by an adult hand. All of them repeat the same sentence: \"I'll never let anyone die to Filthoids again.\"",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C5A"
        },
        [10034106] = {
          Content = "压在一堆杂物下的老旧报纸，记录着很久以前的悲惨事故。\n\n<H>秽蚀者异常凶险，不要被表象欺骗！</>\n9月24日，本市发生一起极为恶劣的“秽蚀”事件，经第六军团卫戍部队调查后，得出以下结论：\n冰湖城市民费西尔夫妇于9月13日在泪湖畔公路边上偶遇一名叫做罗比·布朗的青年。因其身受重伤，费西尔夫妇将其带回家中照料。\n然而，罗比·布朗是一名秽蚀者，他躲过了帝国对潜在秽蚀者的例行盘查并潜逃至城外，且在接受费西尔夫妇帮助时，刻意掩盖了自己的秽蚀痕迹。十日后，悲剧发生：布朗蜕变成为秽兽，杀死了包括费西尔夫妇在内数十名居住在冰湖城南区的市民。第六军团下属冰湖城卫戍部队紧急出动才平息此次骚乱。\n骚乱共造成18人死亡，其中包含3名索拉之民；另有34人受伤。在此提醒各位市民谨记，不要轻易收留身份不明的卡戎之民，一旦发现秽蚀者，立即上报治安署。它们永远只是人类的敌人，无一例外。如有刻意包庇秽蚀者、隐瞒不报者，一律按照《海伯利亚刑事法典》第54条规定，处以死刑。",
          DialogueId = 10034106,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000048;content:READ_TEXT_2000048}",
          GUID = "191E8C84",
          Subtitle = "Deteriorators Are Exceptionally Dangerous — Do Not Be Fooled by Their Appearance!\nOn September 24th, an egregious case of Deterioration occurred in Icelake, with devastating consequences. Following an comprehensive investigation by the 6th Legion's Escort Unit, the details of the tragedy have now been confirmed:\nOn September 13th, local residents Mr and Mrs Fischer encountered a gravely injured young man, Robie Brown, collapsed by the roadside near Lamenting Lake. Acting out of compassion, they brought him into their home and cared for him.\nHowever, Robie Brown was a Deteriorator — one who had evaded the Empire's routine screenings and fled to the outskirts of the city. While receiving aid from the Fischers, Brown deliberately concealed his condition. Ten days later, he succumbed to the transformation, becoming a Filthoid. The resulting massacre in Icelake's southern district claimed the lives of dozens, including Mr and Mrs Fischer. The 6th Legion's Escort responded swiftly and succeeded in subduing the threat — but not before the damage was done.\n\nThe incident resulted in 18 deaths (including 3 Solarian citizens) and 34 injuries. Citizens are reminded: under no circumstances should you provide shelter to unidentified Charon individuals. If you suspect someone of being a Deteriorator, report them to the Security Bureau immediately. Deteriorators are — and will remain — humanity's enemies. No exceptions. Harbouring Deteriorators or concealing their condition is a capital offence under Article 54 of the Hyperborean Criminal Code, punishable by death.",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C84"
        },
        [10034107] = {
          Camera = "-106.066406,611.137695,77.603516,0.000153,5.204611,-92.19577,35.000008,100000.0,false,Manual,22.0",
          Content = "来看看这个。",
          DialogueId = 10034107,
          FinalCamera = "-106.066406,611.137695,77.603516,0.000154,8.004599,-92.39566,35.000008,100000.0,false,Manual,22.0",
          GUID = "191E8CAE",
          LookAt = {
            [1] = "100001:p(Point04)",
            [2] = "200021:p(Point04)"
          },
          NextDialogue = 10034108,
          Scripts = "PARA{MoveTo{ActorId{100001},TargetPoint{\"Point03\"},MoveSpeed{80},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point02\"},Visibility{\"Hide\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "Take a look at this.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8CAE"
        },
        [10034108] = {
          Camera = "-113.304688,236.751953,107.111328,0.000155,-26.791348,130.790771,30.0,100000.0,false,DoNotOverride,22.0",
          Content = "为什么废弃检修间会有这么多矿灯跟矿镐？",
          DialogueId = 10034108,
          FinalCamera = "-113.304688,236.751953,107.111328,0.000152,-33.191277,130.190399,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191E8CD8",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10034109,
          SpeakNpcId = 100001,
          Subtitle = "Why are there so many mining lamps and pickaxes in an abandoned maintenance room?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8CD8"
        },
        [10034109] = {
          Camera = "99.867188,416.986328,118.638672,0.000182,3.20773,-139.803497,35.000011,100000.0,false,Manual,22.0",
          Content = "格雷姆矿坑的月石快没的时候，矿工们担心未来，从矿坑顺了些东西转卖。",
          DialogueId = 10034109,
          FinalCamera = "107.375,408.098633,118.638672,0.000182,3.607713,-142.203781,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E8D02",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034110,
          SpeakNpcId = 200021,
          Subtitle = "Back when the Glevum Pit was running dry, miners started swiping gear to sell elsewhere, out of fear of losing their livelihood.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D02"
        },
        [10034110] = {
          Camera = "-27.976562,359.482422,156.25,0.00017,-1.390585,-141.406723,30.0,100000.0,false,DoNotOverride,22.0",
          Content = "这里应该就是那群矿工藏东西的地方，后来被黎瑟发现，当成了一个隐秘的仓库。不过我要你看的不是这些。",
          DialogueId = 10034110,
          FinalCamera = "-16.988281,344.918945,156.25,0.000169,-1.590608,-147.206284,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191E8D2C",
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.000061,-16.397821,77.969307,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.00006,-14.397696,77.768784,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{5}}},LookAt{_delay{5},LookAtDescription{\"200021:p(Point04)\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "This place must've been one of their stashes. Rhythm probably stumbled upon it later and turned it into a secret base. But that's not what I wanted to show you.",
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D2C"
        },
        [10034111] = {
          Content = "系着歪扭蝴蝶结的朴素礼盒，礼盒边是一瓶帝国最顶尖的止痛剂，和一封不知是什么原因没被塞入礼盒的纸条，上面写着“希望你能早日康复”。",
          DialogueId = 10034111,
          GUID = "191E8D56",
          Subtitle = "A plain gift box with a clumsily made ribbon bow, accompanied by a bottle of the Empire's finest painkiller. Next to it is an unsent note that reads: \"Get well soon.\"",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D56"
        },
        [10034201] = {
          Camera = "219.984375,651.333008,126.039062,0.000189,-0.595449,-128.390549,35.000008,527.224426,false,Manual,2.038203",
          Content = "我还好奇是哪个傻瓜在你昏迷的时候送止痛剂呢，看到这个，确实是黎瑟这种傻傻的家伙能干出来的。",
          DialogueId = 10034201,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "226.792969,645.869141,126.039062,0.000189,-0.795451,-129.390228,35.000008,527.224426,false,Manual,2.038203",
          GUID = "191E9C1A",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034202,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          Scripts = "PARA{SetLocation{ActorId{100001},TargetPoint{\"Point03\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point02\"},Visibility{\"Hide\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "I was wondering who the genius was that sent painkillers to someone in a coma. Now it makes sense — that's so Rhythm.",
          TalkActionId = {
            [1] = "200021:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C1A"
        },
        [10034202] = {
          Camera = "6.648438,363.008789,131.244141,0.000182,3.603758,-146.77739,35.000008,527.224426,false,DoNotOverride,2.038203",
          Content = "好了，我这边就找到这些，你呢，找到印章了吗？",
          DialogueId = 10034202,
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "13.488281,352.691406,131.244141,0.000182,3.603758,-149.576935,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C44",
          NextDialogue = 10034203,
          SpeakNpcId = 200021,
          Subtitle = "Anyway, this is all I've found so far. What about you? Found the seal yet?",
          TalkActionId = {
            [1] = "200021:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200021:p(-20)"
          },
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C44"
        },
        [10034203] = {
          Camera = "-275.664062,320.675781,156.072266,0.000189,-3.796267,-32.382538,35.000008,527.224426,false,DoNotOverride,2.038203",
          Content = "还没。但我知道了另一件事……",
          DialogueId = 10034203,
          FinalCamera = "-271.5625,327.202148,156.072266,0.000189,-3.796267,-35.982929,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C6E",
          NextDialogue = 10034204,
          SpeakNpcId = 100001,
          Subtitle = "Not yet. But I've learned something else...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C6E"
        },
        [10034204] = {
          Camera = "-106.195312,289.816406,169.058594,0.000185,-23.795893,-51.580635,35.000008,527.224426,false,DoNotOverride,2.038203",
          Content = "黎瑟还小的时候……她父母被秽蚀者变成的秽兽害死了，那只秽兽还杀掉了很多人。",
          DialogueId = 10034204,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-101.417969,293.541992,169.058594,0.000177,-23.795885,-56.380722,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C98",
          NextDialogue = 10034205,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-91.234375,264.868164,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-100.582031,264.547852,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "When Rhythm was young... her parents were killed by a Filthoid. That same Filthoid took the lives of so many others.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C98"
        },
        [10034205] = {
          Content = "秽兽异常凶险，虽然它现在停止了攻击，但很可能只是暂时休眠。你们尽快去城内避难，这里交给卫戍部队应付。",
          DialogueId = 10034205,
          GUID = "191E9CC2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10031809.T_Story_Recall_10031809'",
          NextDialogue = 10034206,
          SpeakNpcId = 100304,
          Subtitle = "The Filthoid is highly dangerous. Although it's ceased attacking, it may only be in temporary dormancy. Return to the city immediately — the Escort will take it from here.",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CC2"
        },
        [10034206] = {
          Content = "……保护市民……是我的责任，你们没事……就好。",
          DialogueId = 10034206,
          GUID = "191E9CEC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10034206.T_Story_Recall_10034206'",
          NextDialogue = 10034207,
          SpeakNpcId = 100304,
          Subtitle = "...Protecting civilians is my duty... as long as... you're all safe...",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CEC"
        },
        [10034207] = {
          Camera = "-83.59375,619.290039,74.404297,0.000918,8.607185,-95.991829,35.000008,527.224426,false,DoNotOverride,2.038203",
          Content = "她不想再看到任何人死在秽兽手上，也许正因为如此她才会加入卫戍部队吧。",
          DialogueId = 10034207,
          FinalCamera = "-65.59375,616.701172,74.404297,0.000924,8.607192,-98.191681,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9D16",
          NextDialogue = 10034208,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"315.195312,664.356445,432.208984,0.000911,-28.393204,-137.977951,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"326.253906,652.047852,432.208984,0.000918,-28.993189,-141.378052,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Maybe that's why she joined the Escort — to make sure no one else has to suffer like her parents did.",
