          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "36.460938,163.713867,131.796875,0.000142,3.79891,-110.804428,35.000011,624.438599,false,DoNotOverride,2.005455",
          GUID = "191EA088",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"660.796875,-135.25,43.917969,0.000042,3.629316,166.558029,35.000011,624.438538,false,Manual,2.005455\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"658.265625,-146.15625,43.917969,0.000042,3.629323,165.557648,35.000011,624.438538,false,Manual,2.005455\"},duration{5}}},PlayAnimation{_delay{4},ActorId{200002},AnimationId{\"Alright_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Of course not. Knowing Button Mushroom's little goldfish brain, she'll forget all about it in five minutes. Let's go.",
          TalkActionId = {
            [1] = "200002:Alright_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191EA088"
        },
        [10034229] = {
