          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"566.523438,-273.269531,298.757812,0.000069,-18.199966,156.589584,35.000008,624.438599,false,DoNotOverride,2.005455\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"562.40625,-282.818359,298.757812,0.000073,-18.799973,154.590057,35.000008,624.438599,false,DoNotOverride,2.005455\"},duration{6}}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{2}}",
