        [10034302] = {
          Camera = "274.097168,73.586609,115.533203,0.000013,5.602387,-157.948822,35.000008,257.794312,false,Manual,8.0",
          Content = "对！我们抓紧时间直奔主题吧。",
          DialogueId = 10034302,
          FinalCamera = "272.314453,77.91095,115.533203,0.000014,5.602394,-155.949081,35.000008,257.794312,false,Manual,8.0",
