          NextDialogue = 10034303,
          Scripts = "PlayAnimation{ActorId{100361},AnimationId{\"AgreeHead\"},Duration{1}},",
          SpeakNpcId = 100361,
          Subtitle = "Yes! Alright, let's get straight to it.",
