        [10034320] = {
          Camera = "-96.10498,201.29425,7.722656,0.000082,19.400864,-41.310314,47.0,313.029602,false,Manual,3.0",
          Content = "我明白你的不平。但是我已经满足了，布鲁斯能实现他的梦想，更是我们小时候根本不敢相信的。",
          DialogueId = 10034320,
          FacialId = {
            [1] = "100001:None",
            [2] = [[

200021:None]]
          },
          FinalCamera = "-87.334961,189.71106,12.724609,0.000082,19.400829,-41.110359,47.0,313.029602,false,Manual,3.0",
          GUID = "191EAFA0",
          NextDialogue = 10034321,
          SpeakNpcId = 100361,
          Subtitle = "I understand your indignation. But I'm content with it. Blues achieving his dream is something we never thought possible when we were kids.",
          TalkActionId = {
            [1] = "100361:AgreeHead",
            [2] = [[

100001:Angry01_End]]
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAFA0"
        },
        [10034321] = {
          Camera = "436.986328,-25.022644,237.849609,0.000091,-22.597795,-179.913559,40.000011,313.029602,false,Manual,1.2",
          Content = "我和布鲁斯是怀着双重罪孽长大的，身为卡戎之民的罪，以及……父亲和母亲的罪。",
          DialogueId = 10034321,
          FinalCamera = "436.890137,-3.298767,237.849609,0.000091,-22.597795,-179.113525,40.000011,313.029602,false,Manual,1.2",
          GUID = "191EAFCA",
          LookAt = {
            [1] = "100001:n(100361)",
            [2] = [[

100361:n(100361)]]
          },
          NextDialogue = 10034322,
          SpeakNpcId = 100361,
          Subtitle = "Blues and I grew up under the weight of a double burden: the guilt of our Charon bloodline, and... the sins of our parents.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAFCA"
        },
        [10034322] = {
          Camera = "62.244629,67.1026,108.648438,0.0002,9.797967,-38.907223,30.0,107.425705,false,Manual,1.2",
          Content = "在我小时候，我的父母不慎收留了一名伪装成普通人的秽蚀者……后来的事你们大概可以猜到了。那名秽蚀者变成秽兽，袭击了整片街区，很多人丧生。",
          DialogueId = 10034322,
          FacialId = {
            [1] = "100361:Disappoint01"
          },
          FinalCamera = "62.244629,67.1026,108.648438,0.000201,9.997955,-39.907112,31.0,106.964676,false,Manual,1.2",
          GUID = "191EAFF4",
          NextDialogue = 10034323,
          SpeakNpcId = 100361,
          Subtitle = "When I was a child, my parents unknowingly sheltered someone who was secretly a Deteriorator... You can probably guess what happened next — that Deteriorator turned into a Filthoid and wreaked havoc, killing many of our neighbourhood.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAFF4"
        },
        [10034323] = {
          Camera = "-130.825195,82.583252,114.78125,0.000176,1.399355,-16.117037,37.000015,311.120117,false,Manual,1.2",
          Content = "按照海伯利亚的律法，收留秽蚀者的市民与秽蚀者同罪。",
          DialogueId = 10034323,
          FinalCamera = "-127.814941,91.322998,114.78125,0.000176,1.799379,-19.516514,37.000015,311.120117,false,Manual,1.2",
          GUID = "191EB01E",
          NextDialogue = 10034324,
          SpeakNpcId = 100361,
          Subtitle = "Under Hyperborean laws, harbouring a Deteriorator is as much a crime as being one.",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1003/100343/191EB01E"
        },
        [10034324] = {
          Camera = "468.034668,-74.813324,244.382812,0.000137,-20.387451,167.442261,60.000004,311.120117,false,Manual,3.0",
          Content = "但即使是作为罪犯的后裔，帝国并没有降罪于年幼的我和布鲁斯，甚至允许我们为军团效命。",
          DialogueId = 10034324,
          FacialId = {
            [1] = "100361:Smile01"
          },
          FinalCamera = "467.346191,-77.886597,244.382812,0.000137,-20.387451,167.242218,60.000004,311.120117,false,Manual,3.0",
          GUID = "191EB048",
          LookAt = {
            [1] = "100361:n(100361)"
          },
          NextDialogue = 10034325,
          SpeakNpcId = 100361,
          Subtitle = "But even as the children of criminals, the Empire didn't punish Blues and me. They even allowed us to serve in the Legion.",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1003/100343/191EB048"
        },
        [10034325] = {
          Camera = "206.080566,19.950012,117.921875,0.000168,5.479744,-174.439545,20.000008,208.56778,false,Manual,3.0",
          Content = "也许卡戎之民的日子是艰苦一些……但，我们还是可以用自己的双手，让每天的生活比昨天更好一些的，不是吗？",
          DialogueId = 10034325,
          FinalCamera = "205.896973,21.842163,117.921875,0.000168,5.679732,-176.039429,20.000008,208.56778,false,Manual,3.0",
          GUID = "191EB072",
          LookAt = {
