          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBD3E"
        },
        [10034404] = {
          Camera = "173.846405,157.876358,270.469482,0.000002,-28.998379,-132.680298,20.0,1171.522461,false,Manual,22.0",
          Content = "等整理完报告，我便与你们会合。",
