          FinalCamera = "412.643616,25.277588,132.101562,0.0002,4.006999,-150.270157,45.000023,100000.0,false,Manual,22.0",
          GUID = "191ED0EE",
          NextDialogue = 10034524,
          SpeakNpcId = 100310,
          Subtitle = "Save it. Who faces the penalty is for the military court to decide. If Major Lynn hasn't ordered your arrest, then just focus on doing your job.",
