          },
          NextDialogue = 10034531,
          SpeakNpcId = 200021,
          Subtitle = "Oh yeah? You mean like setting off that ammo box you were supposed to carry, or breaking the sluice gate while patching up the pipes?",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "200002:Angry01_End"
