          },
          NextDialogue = 10034533,
          SpeakNpcId = 100001,
          Subtitle = "Speaking of Rhythm — where is she? She's usually waiting for us at the parking lot by now.",
          TalkActionId = {
            [1] = "200002:ScratchHead_End",
            [2] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED268"
        },
        [10034533] = {
          Content = "确实，那家伙连每天等我们的位置和姿势都不带变的。",
          DialogueId = 10034533,
          GUID = "191ED292",
          LookAt = {
