          },
          NextDialogue = 10034537,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-132.125977,37.652344,136.237793,0.000147,-3.197143,9.206694,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-127.595703,16.415039,136.237793,0.000146,-3.197109,18.007582,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk03_End\"},Duration{2}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"ConfidentLR_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "No, this is a supply list I put together. Ever since the 13th Legion took over the case, it's been harder for citizens to get around, especially in Mist Aken, where food supplies were already scarce. I thought I could at least help by delivering some essentials.",
          TalkActionId = {
            [1] = "100304:Talk03_Start",
            [2] = "200021:ConfidentLRToExplainR_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED310"
        },
        [10034537] = {
          Camera = "64.092773,19.856934,138.348145,0.000255,-4.402309,155.469559,30.000002,198.150391,false,Manual,2.669626",
          Content = "你还真是半点都闲不下来啊——好了停，我知道你又要“职责所在”了。",
          DialogueId = 10034537,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "59.726562,11.441406,138.348145,0.000256,-4.202267,153.069778,30.000002,198.150391,false,Manual,2.669626",
          GUID = "191ED33A",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = "200021:n(100304)"
          },
          NextOptions = {
            [1] = 10034538,
            [2] = 10034541
          },
          SpeakNpcId = 200021,
          Subtitle = "Wow, you sure don't know how to take it easy, do you? I know, I know, save the \"It's my duty\" speech this time.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED33A"
        },
        [10034538] = {
          Content = "我们也来帮忙吧。",
          DialogueId = 10034538,
          GUID = "191ED364",
          ImprPlusId = 1007,
          NextDialogue = 10034539,
          Subtitle = "Let us help you."
        },
        [10034539] = {
          Camera = "-145.116211,-92.38623,122.953613,0.000255,0.797418,50.270557,35.000008,198.150391,false,DoNotOverride,2.669626",
          Content = "谢……啊，不是，麻烦大家了。",
          DialogueId = 10034539,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "-141.902344,-95.058105,122.953613,0.000255,0.997412,51.070686,35.000008,198.150391,false,DoNotOverride,2.669626",
          GUID = "191ED38E",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10034540,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "You don't have to... I mean, thank you.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED38E"
        },
        [10034540] = {
          Camera = "275.59668,-135.068359,262.251953,0.000129,-23.202957,151.422806,35.000015,100000.0,false,DoNotOverride,22.0",
          Content = "这才对嘛，这么久了还说谢，就太见外了。",
          DialogueId = 10034540,
          FacialId = {
            [1] = "200021:Ahaha01",
            [2] = "100304:Sad01"
          },
          FinalCamera = "241.146484,-116.370117,245.611328,0.000129,-23.002949,151.8228,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191ED3B8",
          NextDialogue = 10034545,
          SpeakNpcId = 200021,
          Subtitle = "That's more like it. After all, we've been through a lot together.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED3B8"
        },
        [10034541] = {
          Content = "我也缺，能帮我搞点月石吗？",
          DialogueId = 10034541,
          GUID = "191ED3E2",
          ImprPlusId = 1010,
          NextDialogue = 10034542,
          Subtitle = "I'm running low on supplies too. Can you get me some Phoxenes?"
        },
        [10034542] = {
          Camera = "-145.116211,-92.38623,122.953613,0.000255,0.797418,50.270557,35.000008,198.150391,false,DoNotOverride,2.669626",
          Content = "如果对你来说是必需品的话。",
          DialogueId = 10034542,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-141.902344,-95.058105,122.953613,0.000255,0.997412,51.070686,35.000008,198.150391,false,DoNotOverride,2.669626",
          GUID = "191ED40C",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10034543,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "If it's really something you need, I'll see what I can do.",
          TalkActionId = {
            [1] = "100304:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED40C"
        },
        [10034543] = {
          Camera = "47.226562,105.367188,139.936523,0.000253,-8.199676,-117.541321,35.000011,100000.0,false,DoNotOverride,22.0",
          Content = "别当真别当真，小仆从就是随口一说啦，我们还是看看你还缺什么东西吧。",
          DialogueId = 10034543,
          FinalCamera = "47.226562,105.367188,139.936523,0.000257,-12.799651,-114.540627,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191ED436",
          LookAt = {
            [1] = "100304:n(200002)"
          },
          NextDialogue = 10034544,
          SpeakNpcId = 200002,
          Subtitle = "Don't mind my Little Minion, {性别:he|she} was just kidding around. Let's see what else is still on your list.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED436"
        },
        [10034544] = {
          Camera = "20.209961,-161.042969,88.688477,0.000263,5.556803,128.063461,35.000015,291.948975,false,Manual,4.0",
          Content = "你就只是单纯想继续跑去玩吧！",
          DialogueId = 10034544,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "23.350586,-158.584473,88.688477,0.000264,5.556803,129.063293,35.000015,291.948975,false,Manual,4.0",
          GUID = "191ED460",
          LookAt = {
