            [2] = "100304:n(100304)",
            [3] = "100001:n(100001)"
          },
          NextDialogue = 10034545,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200002:n(200021)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "You're just looking for an excuse to goof around more, aren't you?",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 4,
