        },
        [10034545] = {
          Camera = "58.495117,-31.134766,130.94043,0.000255,1.197216,122.468346,35.0,198.150391,false,DoNotOverride,2.669626",
          Content = "我看看……嗯，物资清单上还有最后一项，送到雾区的鱼。",
          DialogueId = 10034545,
          FacialId = {
            [1] = "200021:Confident01",
            [2] = "100304:Unhappy01"
          },
          FinalCamera = "62.019531,-28.944824,130.94043,0.000255,0.997201,121.468498,35.0,198.150391,false,DoNotOverride,2.669626",
          GUID = "191ED48A",
          LookAt = {
            [1] = "200002:n(200002)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10034546,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-155.210938,-117.219727,121.275391,0.000203,-0.800443,54.851498,35.000015,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-150.672852,-120.304688,121.275391,0.000203,-0.800443,53.851078,35.000015,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Explain01_Start\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "Let me see... Looks like the last thing we need to deliver is fish for Mist Aken.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED48A"
        },
        [10034546] = {
          Camera = "-12.336914,-66.583008,102.745605,0.000291,-9.999444,-97.554825,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "哇，是钓鱼诶——我也要钓我也要钓！",
          DialogueId = 10034546,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "5.630859,58.565918,130.43457,0.000288,-14.59942,-97.35498,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191ED4B4",
          LookAt = {
            [1] = "100304:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200021:n(200002)"
          },
          Scripts = "SEQ{CameraMoveTo{_delay{1.5},TargetPosition{\"33.922852,-373.008789,157.193848,0.000295,-13.007589,102.518494,25.0,198.150391,false,DoNotOverride,2.669626\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"28.636719,-349.197754,151.557129,0.000295,-13.007589,102.518494,25.0,198.150391,false,DoNotOverride,2.669626\"},duration{8}}}",
          SpeakNpcId = 200002,
          Subtitle = "Whoa, fishing? Count me in, count me in!",
          TalkActionId = {
            [1] = "100304:Explain01_End",
            [2] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED4B4"
        },
        [10034601] = {
          Content = "呵呵……",
          DialogueId = 10034601,
          GUID = "191EDDBA",
          NextDialogue = 10034602,
          SpeakNpcId = 100304,
          Subtitle = "Hehe...",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDBA"
        },
        [10034602] = {
          Content = "你笑什么？",
          DialogueId = 10034602,
          GUID = "191EDDE4",
          NextDialogue = 10034603,
          SpeakNpcId = 200021,
          Subtitle = "What's so funny?",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDE4"
        },
        [10034603] = {
          Content = "我想起上次这样在湖边钓鱼，还是三年前和布鲁斯一起。",
          DialogueId = 10034603,
          GUID = "191EDE0E",
          NextDialogue = 10034604,
          SpeakNpcId = 100304,
          Subtitle = "I was just remembering the last time I fished here. It was three years ago, with Blues.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE0E"
        },
        [10034604] = {
          Content = "那家伙虽然聪明，但太好动了，根本坐不住。所以他钓一整天，篓子都是空的。",
          DialogueId = 10034604,
          GUID = "191EDE38",
          NextDialogue = 10034605,
          SpeakNpcId = 100304,
          Subtitle = "That kid's smart, but he's always been boisterous. He fished all day and ended up with an empty basket.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE38"
        },
        [10034605] = {
          Content = "……不知道他现在在内城过得怎么样了，有没有学会钓鱼。",
          DialogueId = 10034605,
          GUID = "191EDE62",
          NextDialogue = 10034606,
          SpeakNpcId = 100304,
          Subtitle = "...I wonder how he's doing in the inner city now. Maybe he's finally learned how to fish.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE62"
        },
        [10034606] = {
          Content = "哼哼，你们这些凡人啊，总被这些乱七八糟的感情羁绊，不像本魔王大人。",
          DialogueId = 10034606,
          GUID = "191EDE8C",
          NextDialogue = 10034607,
          SpeakNpcId = 200002,
          Subtitle = "Heh, you mortals are always held back by your worldly attachments. You should learn from me, the cool, detached Demon King!",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE8C"
        },
        [10034607] = {
          Content = "没事的小矮子，我们也是你的家人。只要你开心，让我管你叫奶奶都行。",
          DialogueId = 10034607,
          GUID = "191EDEB6",
          NextDialogue = 10034608,
          SpeakNpcId = 200021,
          Subtitle = "It's okay, Button Mushroom, we're all your family. If it makes you happy, I'll even call you Granny.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEB6"
        },
        [10034608] = {
          Content = "你，你怎么突然这么好……",
          DialogueId = 10034608,
          GUID = "191EDEE0",
          NextDialogue = 10034609,
          SpeakNpcId = 200002,
          Subtitle = "Aww, why are you being so nice to me all of a sudden...?",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEE0"
        },
        [10034609] = {
          Content = "奶奶，我饿，给点零用钱。",
          DialogueId = 10034609,
          GUID = "191EDF0A",
          NextDialogue = 10034610,
          SpeakNpcId = 200021,
          Subtitle = "Granny, I'm starving. Got a little pocket money for your poor, hungry grandkid?",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF0A"
        },
        [10034610] = {
          Content = "可恶！",
          DialogueId = 10034610,
          GUID = "191EDF34",
          SpeakNpcId = 200002,
          Subtitle = "Hmph! I knew it!",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF34"
        },
        [10034611] = {
          Content = "这样就齐了，把物资送到雾区吧。",
          DialogueId = 10034611,
          GUID = "191EDF5E",
          SpeakNpcId = 100304,
          Subtitle = "That should do it. Let's deliver these supplies to Mist Aken.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF5E"
        },
        [10034612] = {
          Content = "宵禁期间禁止通行，请各位市民配合！",
          DialogueId = 10034612,
          GUID = "191EDF60",
          Subtitle = "Access is prohibited during curfew. Thank you for your cooperation.",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF60"
        },
        [10034613] = {
          Content = "（<H>地面都被士兵封锁了</>……或许可以试试别的路——比如<H>楼顶</>？）",
          DialogueId = 10034613,
          GUID = "191EDF61",
          SpeakNpcId = 100001,
          Subtitle = "(The ground is blockaded by soldiers... Maybe try another way — what about the rooftops?)",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF61"
        },
        [10034701] = {
