          SpeakNpcId = 100001,
          Subtitle = "Right. But this isn't quite what I expected. It even feels... kind of like a cosy little home.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFFB0"
        },
        [10034809] = {
          Camera = "-851.0,-3564.0,2678.0,0.000575,-32.462578,76.610298,40.0,100000.0,false,DoNotOverride,22.0",
          Content = "小时候贝蕾也会学着其他人把一些五颜六色的布条挂在房间里，这样屋子就没有那么冷清了。",
          DialogueId = 10034809,
          FinalCamera = "-851.0,-3564.0,2706.0,0.000575,-32.462578,76.610298,40.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191EFFDA",
          LookAt = {
            [1] = "100001:p(fix31_4)",
            [2] = "100304:n(100001)"
          },
          NextDialogue = 10034810,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-506.869629,-167.307617,243.748657,-0.001007,-11.265167,46.788433,30.000008,800.491821,false,Manual,1.261124\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-493.358398,-179.537109,243.748657,-0.001007,-11.865192,48.388107,30.000008,800.491821,false,Manual,1.261124\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "When we were kids, Berry would hang colourful strips of cloth all around our home. She said it'd make the place feel warmer, and less lonely.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFFDA"
        },
        [10034810] = {
          Camera = "18.089355,286.953125,108.440918,-0.00174,-21.568111,-73.964584,30.000008,100000.0,false,DoNotOverride,22.0",
          Content = "仔细一瞧，他们摆得还挺威严的！难道他们才是真正的下水道公爵？",
          DialogueId = 10034810,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "22.338867,288.074219,108.440918,-0.00174,-21.568111,-76.764099,30.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191F0004",
          NextDialogue = 10034811,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-1.92041,529.060547,193.301636,-0.001741,-23.567587,-85.957458,30.000013,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-14.425781,525.737305,192.27063,-0.00174,-23.367571,-80.557098,30.000013,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 200002,
          Subtitle = "Upon a closer look, they've set this place up pretty majestically! Maybe they're the real Dukes of the Sewers!",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100001:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1003/100348/191F0004"
        },
        [10034811] = {
          Camera = "-33.097656,174.466797,70.899658,-0.00174,12.431073,39.826427,35.000011,233.370453,false,Manual,4.128408",
          Content = "下水道公爵是……什么？",
          DialogueId = 10034811,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-35.933594,177.720703,70.899658,-0.001739,12.43106,37.626053,35.000011,233.370453,false,Manual,4.128408",
          GUID = "191F002E",
          LookAt = {
            [1] = "100304:n(200002)",
            [2] = "200002:n(100304)"
          },
          NextDialogue = 10034812,
          SpeakNpcId = 100304,
          Subtitle = "Dukes of the Sewers...? What's that?",
          TalkActionId = {
            [1] = "100304:Think_Start",
            [2] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191F002E"
        },
        [10034812] = {
          Camera = "79.039062,291.808594,109.609131,-0.00177,8.627402,141.371552,35.000019,427.577942,false,DoNotOverride,3.623266",
          Content = "咳，这不重要。这里布置得有些奇怪，我们先各处检查看看有没有什么异常吧。",
          DialogueId = 10034812,
          FinalCamera = "75.835938,287.754883,109.609131,-0.001769,8.627402,138.971634,35.000019,427.577942,false,DoNotOverride,3.623266",
          GUID = "191F0058",
          LookAt = {
            [1] = "100304:n(100001)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10034813,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"167.153809,290.429688,133.526123,-0.00177,-4.771181,148.190033,30.000002,228.299911,false,Manual,2.297225\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"164.938477,286.738281,133.526123,-0.00177,-4.771181,145.189713,30.000002,228.299911,false,Manual,2.297225\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Ahem... Let's not get hung up on that. The setup here's a bit strange — let's split up and check for anything off.",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191F0058"
        },
        [10034813] = {
          Camera = "1.158203,334.078125,122.950684,-0.00177,4.227047,-0.062805,35.000023,427.577942,false,DoNotOverride,3.623266",
          Content = "好的。",
          DialogueId = 10034813,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "191F0082",
          SpeakNpcId = 100304,
          Subtitle = "Okay.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100348/191F0082"
        },
        [10034814] = {
          Content = "与剧院帷幕材质十分接近的布料，虽然老旧但十分整洁，显然被什么人认真打理过。\n仔细观察和触摸会发现，和袭击现场发现的帷幕是同一块布料。",
          DialogueId = 10034814,
          GUID = "191F00AC",
          Subtitle = "A piece of fabric resembling theatre curtain material. Though old and worn, it is impeccably clean — clearly maintained with care.\nA closer look confirms it matches the fabric found at the crime scene.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00AC"
        },
        [10034815] = {
          Content = "假人模型虽然很旧，但造型和姿势明显经过了精心设计，看起来端庄而优雅，如同在舞台上纵情表演的演员。",
          DialogueId = 10034815,
          GUID = "191F00D6",
          Subtitle = "Though worn with age, the mannequin has clearly been posed and styled with care, exuding a graceful elegance, — like a performer lost in the moment on stage.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00D6"
        },
        [10034816] = {
          Content = "四周遍布着巨大的爪痕，密集而凌乱，似是在极度的痛苦和疯狂中留下的。",
          DialogueId = 10034816,
          GUID = "191F0100",
          Subtitle = "Huge claw marks slash across the walls — dense, erratic, as if left in a frenzy of agony and madness.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0100"
        },
        [10034817] = {
          Camera = "-470.862305,336.71875,225.989624,0.000123,-12.395741,-25.18132,31.654133,100000.0,false,Manual,22.0",
          Content = "我彻查了下方区域，没有异常，你们有什么发现吗？",
          DialogueId = 10034817,
          FinalCamera = "-470.862305,336.71875,205.012207,0.000122,-11.195704,-25.18092,31.654133,100000.0,false,Manual,22.0",
          GUID = "191F012A",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034818,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200021:n(100001)"}},
LookAt{LookAtDescription{"200021:n(100304)"}},
LookAt{LookAtDescription{"200021:n(100001)"}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "I've checked the lower area — no signs of anything unusual. What about your side?",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1003/100348/191F012A"
        },
        [10034818] = {
          Camera = "-87.959473,-40.362305,149.193604,0.000196,-4.19418,55.214046,40.0,237.274918,false,Manual,3.0",
          Content = "我发现了，头顶这些布条的材质和袭击现场的帷幕是一样的。不过我们现在已经找到了这里，看来没什么意义了。",
          DialogueId = 10034818,
          FinalCamera = "-89.506348,-39.294922,149.193604,0.000197,-3.594148,55.013935,40.0,237.274918,false,Manual,3.0",
          GUID = "191F0154",
          NextDialogue = 10034819,
          Scripts = [[
