}]],
          SpeakNpcId = 100001,
          Subtitle = "I found something. This fabric matches the piece of curtain cloth from the crime scene. But now that we've already found this spot, it doesn't seem to matter much anymore.",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100348/191F0154"
        },
        [10034819] = {
          Camera = "-32.84668,164.612305,158.262451,0.000111,-9.194923,-83.765297,35.0,136.70015,false,Manual,3.0",
          Content = "帷幕……帷幕吗……",
          DialogueId = 10034819,
          FacialId = {
