            [3] = [[

200021:n(100304)]]
          },
          NextDialogue = 10034821,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100304},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{ActorId{100304},AnimationId{"ConfidentLR_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{100304},AnimationId{"ConfidentLRToTalk01_Start"},Duration{1}},

}]],
          SpeakNpcId = 100304,
          Subtitle = "Wait... I remember something! That mannequin's pose and look — I've seen it before on an opera poster Blues once sketched.",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200002:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100348/191F01A8"
        },
        [10034821] = {
          Camera = "-30.813477,46.808594,125.878662,0.000131,5.604402,63.830662,36.000004,16827.542969,false,Manual,22.0",
          Content = "嗯……这么说来，这整个房间都布置得像个舞台一样。凶手难道是一名<H>歌剧爱好者</>？",
          DialogueId = 10034821,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "-18.894043,45.036133,126.219971,0.000127,5.80439,68.630951,36.000004,16827.542969,false,Manual,22.0",
          GUID = "191F01D2",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = [[

200021:n(100001)]]
          },
          NextDialogue = 10034822,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... now that you mention it, the whole room's staged like a theatre. Could the perpetrator be... an opera enthusiast?",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100348/191F01D2"
        },
        [10034822] = {
          Camera = "-2.286133,328.46582,139.172852,0.000183,-0.195316,-81.557655,32.000004,16827.542969,false,Manual,22.0",
          Content = "……不过既然军团已经找到了凶手，这条线索已经意义不大了。",
          DialogueId = 10034822,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-5.772461,327.951172,139.172852,0.000183,-0.195316,-81.957558,32.000004,16827.542969,false,Manual,22.0",
          GUID = "191F01FC",
          NextDialogue = 10034823,
          SpeakNpcId = 100001,
          Subtitle = "...Then again, since the Legion has already tracked down the perp, this clue probably doesn't matter much either.",
          TalkActionId = {
            [1] = "100304:Confident_End",
            [2] = [[

100001:ScratchHead_End]],
            [3] = [[

200021:ConfidentLR_Start]]
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100348/191F01FC"
        },
        [10034823] = {
          Camera = "-460.376465,319.509766,156.266602,0.000142,-6.195459,-23.380085,31.654133,100000.0,false,Manual,22.0",
          Content = "的确。总不能跟凶手来段对唱，人家一看我们志同道合，就乖乖认罪吧。",
          DialogueId = 10034823,
          FinalCamera = "-460.07373,319.378906,144.872803,0.000142,-5.395446,-23.57946,31.654133,100000.0,false,Manual,22.0",
          GUID = "191F0226",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = [[

100001:n(200021)]]
          },
          NextDialogue = 10034824,
          SpeakNpcId = 200021,
          Subtitle = "Right. Not like we can belt out a duet and hope they turn themselves in out of mutual admiration.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToSighR_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1003/100348/191F0226"
        },
        [10034824] = {
          Camera = "-9.942383,21.341797,132.388428,0.000254,0.805327,76.790901,33.0,16827.542969,false,Manual,22.0",
          Content = "来听听克莱夫有什么新指示吧。",
          DialogueId = 10034824,
          FinalCamera = "-9.302246,24.06543,132.428711,0.000254,0.805327,76.790901,33.0,16827.542969,false,Manual,22.0",
          GUID = "191F0250",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Let's report back to Clive and see if he has any new instructions.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToSighR_End",
            [2] = [[

100001:Talk02_Start]],
            [3] = [[

100304:AgreeHead]]
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100348/191F0250"
        },
        [10034825] = {
          Content = "小仆从，这里有个奇奇怪怪的机关诶！",
          DialogueId = 10034825,
          GUID = "191F0101",
          NextDialogue = 10034826,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, Little Minion — look! There's a weird-looking switch here!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0101"
        },
        [10034826] = {
          Content = "小矮子先别碰，当心有诈！……嗯，还好，只是普通的升降机。",
          DialogueId = 10034826,
          GUID = "191F0102",
          SpeakNpcId = 200021,
          Subtitle = "No, Button Mushroom — don't touch that! Could be a trap... Huh. Looks like it's just a regular lift.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0102"
        },
        [10034827] = {
          Content = "出现了新的路诶！简直像变魔术一样！",
          DialogueId = 10034827,
          GUID = "191F0103",
          SpeakNpcId = 200002,
          Subtitle = "Whoa! A new path just opened up — like magic!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0103"
        },
        [10034828] = {
          Content = "嘁，什么都没有嘛，我还以为会突然蹦出来啥。",
          DialogueId = 10034828,
          GUID = "191F0104",
          NextDialogue = 10034829,
          SpeakNpcId = 200021,
          Subtitle = "Tch. Nothing at all... I was half expecting something to jump out.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0104"
        },
        [10034829] = {
          Content = "呸呸呸，不许乌鸦嘴！",
          DialogueId = 10034829,
          GUID = "191F0105",
          NextDialogue = 10034830,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Watch your mouth — you'll jinx it!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0105"
        },
        [10034830] = {
          Content = "继续向上吧。",
          DialogueId = 10034830,
          GUID = "191F0106",
          NextDialogue = 10034832,
          SpeakNpcId = 100001,
          Subtitle = "Let's just keep moving.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0106"
        },
        [10034831] = {
          Content = "嚯，一下就亮起来了。边边角角都看得一清二楚。",
          DialogueId = 10034831,
          GUID = "191F0107",
          SpeakNpcId = 200021,
          Subtitle = "Whoa — the whole place just lit up. You can see every corner now.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0107"
        },
        [10034832] = {
          Content = "不得不说，这地方布置得还挺有艺术感的，简直像个缩小版的剧院舞台。",
          DialogueId = 10034832,
          GUID = "191F0108",
          SpeakNpcId = 200021,
          Subtitle = "Gotta say, this place's got style. Feels like a mini theatre stage.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0108"
        },
        [10034833] = {
          Content = "看样子这里没有什么陷阱。回去报告黎瑟长官吧。",
          DialogueId = 10034833,
          GUID = "191F0109",
          SpeakNpcId = 100001,
          Subtitle = "Looks clear for now. Let's report back to Officer Fischer.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0109"
        },
        [10034901] = {
