        [10035225] = {
          Camera = "-359.866394,-8.274414,54.811768,0.000218,9.979808,3.766006,35.0,426.298615,false,Manual,22.0",
          Content = "是的，我想要的不过是一份安心而已。所以我做不到……我做不到自己在壁炉边烤火，却眼睁睁地看着其他人冻死在大雪里。",
          DialogueId = 10035225,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "-348.656433,-7.537384,56.790039,0.000218,9.979808,3.766125,35.0,426.298615,false,Manual,22.0",
          GUID = "191F441A",
          NextDialogue = 10035226,
          Scripts = [[
PARA{
