LookAt{_delay{4.5},LookAtDescription{"100304:n(100001)"}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "Yes, I joined the Legion only for peace of mind. But that's exactly why I can't sit back, warming my hands by a fire, while others freeze to death out there in the cold.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100352/191F441A"
        },
        [10035226] = {
          Camera = "-767.976807,-468.421631,1021.622314,0.000127,-46.820312,30.559282,35.0,1471.360107,false,Manual,22.0",
          Content = "你还记得我说过一件事吗？我的父母是被秽兽杀害的，因为他们收留了一名伪装成常人的秽蚀者……",
          DialogueId = 10035226,
          FinalCamera = "-783.698853,-437.067078,1022.494141,0.000135,-46.820293,30.359089,35.0,1471.360107,false,Manual,22.0",
          GUID = "191F4444",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10035227,
          Scripts = [[
PARA{
PlayAnimation{ActorId{100304},AnimationId{"Talk02_End"},Duration{1}},
MoveTo{ActorId{200002},TargetPoint{"TargetPoint_cp2fixsimple47_xiaobaiHide"},MoveSpeed{60},Visibility{"Show"}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Do you remember what I told you about my parents? They were killed by a Filthoid because they took in a Deteriorator who hid his symptoms.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4444"
        },
        [10035227] = {
          Camera = "-31.82811,20.605799,47.986328,-10.012484,51.563259,6.457195,18.0,105.517471,false,Manual,3.0",
          Content = "但……没有人知道……真正的罪人，是我。那个晚上，是我央求妈妈，“那个大哥哥好像快不行了，我们帮帮他好不好。”",
          DialogueId = 10035227,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-6.432026,22.505722,89.076172,-10.01455,51.962456,0.059592,16.0,57.592651,false,Manual,3.0",
          GUID = "191F446E",
          NextDialogue = 10035228,
          Scripts = [[
PARA{
SetLocation{ActorId{100001},TargetPoint{"TargetPoint_cp2fixsimple47_nvzhuHide"},Visibility{"Hide"}},
LookAt{LookAtDescription{"100304:p(TargetPoint_cp2fixsimple47_liseWatch1)"}},
PlayAnimation{ActorId{100304},AnimationId{"Sigh_Start"},Duration{5}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "But... no one knows the truth. The one really to blame... was me. That night, it was I who begged my mother to help that man, because he looked like he was dying, and I felt sorry for him.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1003/100352/191F446E"
        },
        [10035228] = {
          Camera = "-57.968437,116.424126,97.0979,0.000168,14.376346,-55.626965,25.000002,114.971954,false,Manual,8.0",
          Content = "秽兽袭来的时候，他们把我藏在了壁橱里。妈妈和我说的最后一句话是，“不是你的错，不要责怪自己，也不要告诉其他人。照顾好布鲁斯，好好活着。”",
          DialogueId = 10035228,
          FacialId = {
            [1] = "100304:Iyada01",
            [2] = [[

200021:Sad01]]
          },
          FinalCamera = "-69.577477,107.578148,97.0979,0.000171,14.376346,-49.227505,25.000002,114.971954,false,Manual,8.0",
          GUID = "191F4498",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          NextDialogue = 10035229,
          Scripts = [[
SEQ{
PlayAnimation{_delay{9},ActorId{100304},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{100304},AnimationId{"ConfidentRToExplain_Start"},Duration{1}}

}]],
          SpeakNpcId = 100304,
          Subtitle = "When the Filthoid came, my parents hid me in the closet. My mother's last words to me were, \"It's not your fault. Don't beat yourself up for it — and don't tell anyone. Take care of Blues and yourself.\"",
          TalkActionId = {
            [1] = "100304:Sigh_End"
          },
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4498"
        },
        [10035229] = {
          Camera = "-234.232544,-55.80162,49.559814,0.000288,15.979787,17.355488,45.0,312.70285,false,Manual,3.0",
          Content = "我的妈妈……她不恨我，一直到秽兽的爪子刺穿她的身体，她都没有指责过我半句。可是我多希望、多希望她能打我，骂我……而不是原谅我。",
          DialogueId = 10035229,
          FacialId = {
            [1] = "100304:Sad02"
          },
          FinalCamera = "-223.185394,-52.350403,52.874756,0.000288,15.979787,17.355488,45.0,312.70285,false,Manual,3.0",
          GUID = "191F44C2",
          NextDialogue = 10035230,
          Scripts = [[
PARA{
SetLocation{ActorId{100001},TargetPoint{"TargetPoint_cp2fixsimple47_nvzhuHide"},Visibility{"Show"}},
PlayAnimation{_delay{3},ActorId{100304},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{14.5},ActorId{100304},AnimationId{"Explain01L_Start"},Duration{1}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "My mother didn't hate me. Even as the Filthoid's claws pierced her, she never once blamed me. But I wish she had. I wish she'd hit me, yelled at me — anything but forgive me.",
          TalkActionId = {
            [1] = "100304:Explain01_Start",
            [2] = [[

100001:Talk03_End]]
          },
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1003/100352/191F44C2"
        },
        [10035230] = {
          Camera = "-384.197845,-334.033997,297.927734,0.000337,-22.820459,39.757423,20.0,628.755066,false,Manual,3.0",
          Content = "但我无法原谅自己。妈妈的遗言就像梦魇，这些年我从未真正安心过，哪怕是一个晚上。如果不是布鲁斯一直安慰我，或许……我已经疯掉了。",
          DialogueId = 10035230,
          FinalCamera = "-375.433136,-326.792511,311.782715,0.000337,-23.620474,39.557415,20.0,628.755066,false,Manual,3.0",
          GUID = "191F44EC",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = [[

200021:n(100304)]]
          },
          NextDialogue = 10035231,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{100304},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{6},ActorId{100304},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{10},ActorId{100304},AnimationId{"Sigh_Start"},Duration{1}},
PlayAnimation{_delay{6},ActorId{100001},AnimationId{"Explain02_Start"},Duration{1}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "But I can't forgive myself. Her last words haunt me like a nightmare. I haven't known peace of mind, not even for a single night. If it weren't for Blues comforting me, I... I might've gone mad.",
          TalkActionId = {
            [1] = "100304:Explain01L_End"
          },
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1003/100352/191F44EC"
        },
        [10035231] = {
          Camera = "36.986095,-18.870388,128.928223,-8.004199,3.379967,115.186882,25.0,96.903938,false,Manual,5.0",
          Content = "这一次也是一样。如果“卡戎狩猎”就这样过去，我永远无法原谅自己。",
          DialogueId = 10035231,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "38.870972,-17.965782,128.635742,-8.004287,3.379967,115.187103,25.0,96.903938,false,Manual,5.0",
          GUID = "191F4516",
          NextDialogue = 10035232,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100304},AnimationId{"Sigh_End"},Duration{1}},
PlayAnimation{_delay{3},ActorId{100304},AnimationId{"Explain02_Start"},Duration{1}},
}
]],
          SpeakNpcId = 100304,
          Subtitle = "It's the same this time. If I just sit by and let the \"Charon Hunt\" case end like this, I'll never forgive myself.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4516"
        },
        [10035232] = {
          Camera = "-514.289307,44.722595,247.631836,0.000043,-15.820329,-3.607711,35.0,612.436279,false,Manual,22.0",
          Content = "抱歉，拉着你们絮叨了这么多陈年旧事……该继续行动了！趁着天色还不晚。",
          DialogueId = 10035232,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "-511.032501,44.516754,237.636963,0.000039,-14.420188,-4.007435,35.0,612.436279,false,Manual,22.0",
          GUID = "191F4540",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextOptions = {
            [1] = 10035233,
            [2] = 10035234
          },
          SpeakNpcId = 100304,
          Subtitle = "Sorry for unloading all these old memories on you... I should get going while there's still daylight.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = [[

200021:Talk03_Start]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4540"
        },
        [10035233] = {
          Content = "一起去吧。我不会让你再留下遗憾。",
          DialogueId = 10035233,
          GUID = "191F456A",
          ImprPlusId = 1009,
          NextDialogue = 10035235,
          Subtitle = "We'll go with you. I want to help you fix your regrets."
        },
        [10035234] = {
          Content = "只有我们几个人行动吗？",
          DialogueId = 10035234,
          GUID = "191F4594",
          ImprPlusId = 1006,
          NextDialogue = 10035235,
          Subtitle = "Just you and us?"
        },
        [10035235] = {
          Camera = "-152.189682,50.255051,133.710449,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0",
          Content = "这是我自己的选择，而且我已经没有其他可以调动的下属了。所以各位不必陪我继续涉险。",
          DialogueId = 10035235,
          FacialId = {
            [1] = "100001:None",
            [2] = [[

200021:None]]
          },
          FinalCamera = "-144.869965,49.820297,133.784424,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0",
          GUID = "191F45BE",
          NextDialogue = 10035236,
          SpeakNpcId = 100304,
          Subtitle = "This is my own choice, and I have no other subordinates to call upon. You don't have to risk yourselves to help me.",
          TalkActionId = {
            [1] = "100304:Talk01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100352/191F45BE"
        },
        [10035236] = {
          Camera = "-66.625938,-133.03833,203.941406,0.00007,-24.019957,54.40028,20.0,136.574539,false,Manual,5.0",
          Content = "说什么呢，都到这份上了，还想抛下我们自个儿揽功？总是为他人送去炭火的人，我们也必然不会让她冻死在雪里。",
          DialogueId = 10035236,
          FinalCamera = "-66.625938,-133.03833,199.980713,0.000071,-23.21991,54.600311,20.0,136.574539,false,Manual,5.0",
          GUID = "191F45E8",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10035237,
          SpeakNpcId = 200021,
          Subtitle = "What are you saying? We've come this far, and now you want to go solo and hog all the credit? Like we'd leave a good person who brings warmth to others freeze out in the snow.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start",
            [2] = [[

100304:Talk01_End]]
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1003/100352/191F45E8"
        },
        [10035237] = {
          Camera = "18.257643,30.248974,152.72583,0.0002,3.779478,-84.856224,30.000002,95.997826,false,Manual,10.0",
          Content = "更何况，要是你也冻死了，我那个凶神恶煞的妹妹可不会放过我。",
          DialogueId = 10035237,
          FinalCamera = "18.257643,30.248974,152.72583,0.0002,3.779478,-84.856224,30.000002,95.997826,false,Manual,10.0",
          GUID = "191F4612",
          NextDialogue = 10035238,
          SpeakNpcId = 200021,
          Subtitle = "And besides, if you freeze to death, that terrifying little sister of mine will make sure I pay for it.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToTalkR_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4612"
        },
        [10035238] = {
          Camera = "-99.90155,10.630356,127.286377,0.00003,16.37895,-31.00835,35.0,159.336838,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          Content = "我都听到了！我要告诉菲娜去！",
          DialogueId = 10035238,
          FacialId = {
