          ToFinalCameraBlendTime = 3
        },
        [10035401] = {
          Content = "……凶手果然还活着！",
          DialogueId = 10035401,
          GUID = "191F60FA",
          NextDialogue = 10035402,
          SpeakNpcId = 100304,
          Subtitle = "I knew the perpetrator is still alive!",
          VoiceName = "voice/$Locale$/story/1003/100354/191F60FA"
        },
        [10035402] = {
          Content = "好家伙，自己找上门来了……",
          DialogueId = 10035402,
          GUID = "191F6124",
          NextDialogue = 10035403,
          SpeakNpcId = 200021,
          Subtitle = "Huh, came straight to us this time.",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6124"
        },
        [10035403] = {
          Content = "“凶手”……",
          DialogueId = 10035403,
          GUID = "191F614E",
          NextDialogue = 10035404,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "\"Perpetrator\"...?",
          VoiceName = "voice/$Locale$/story/1003/100354/191F614E"
        },
        [10035404] = {
          Content = "看来，直到最后，他们也，没告诉你，真相。果然十三军团，也是，一丘之貉。",
          DialogueId = 10035404,
          GUID = "191F6178",
          NextDialogue = 10035405,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Hmph. Even now, they haven't... told you... the truth. Dirty liars. Even the 13th Legion... is no exception.",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6178"
        },
        [10035405] = {
          Content = "真相？你在说什么……",
          DialogueId = 10035405,
          GUID = "191F61A2",
          NextDialogue = 10035406,
          SpeakNpcId = 100304,
          Subtitle = "The truth? What do you mean...?",
          VoiceName = "voice/$Locale$/story/1003/100354/191F61A2"
        },
        [10035406] = {
          Content = "这怪物在拖延时间，先制服它！",
          DialogueId = 10035406,
          GUID = "191F61CC",
          SpeakNpcId = 200021,
          Subtitle = "It's stalling — Take it down first!",
          VoiceName = "voice/$Locale$/story/1003/100354/191F61CC"
        },
        [10035407] = {
          Camera = "-315.066406,-84.020996,106.125488,0.000016,9.398941,7.940432,30.0,100000.0,false,Manual,7.44259",
          Content = "别来无恙，姐姐。",
          DialogueId = 10035407,
          FinalCamera = "-309.679688,-83.179199,106.931641,0.000015,8.998944,8.140003,30.0,100000.0,false,Manual,7.44259",
          GUID = "191F61F6",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)",
            [5] = "100327:n(100304)"
          },
          NextDialogue = 10035408,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "It's been so long, Sister.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F61F6"
        },
        [10035408] = {
          Camera = "1161.523438,-515.213623,358.976562,-10.001677,-11.199829,154.540695,35.0,100000.0,false,Manual,14.096215",
          Content = "…………？！",
          DialogueId = 10035408,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "1029.605469,-452.223145,330.28418,-10.001463,-11.199829,155.340485,35.0,100000.0,false,Manual,14.096215",
          GUID = "191F6220",
          LookAt = {
            [1] = "100304:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "200021:n(100304)"
          },
          NextDialogue = 10035409,
          SpeakNpcId = 100304,
          Subtitle = "...!?",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6220"
        },
        [10035409] = {
          Camera = "-162.207031,-39.662109,88.29541,0.00001,15.77163,15.197428,30.0,100000.0,false,Manual,13.369958",
          Content = "算了……我现在应该，称呼你，黎瑟长官。你，冷静点，了吗。",
          DialogueId = 10035409,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "-154.007812,-60.436035,88.29541,0.000008,16.371765,18.595819,30.0,100000.0,false,Manual,13.369958",
          GUID = "191F624A",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "200002:n(100327)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10035410,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{\"outside1\"},Visibility{\"Show\"}}",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Or should I say... Officer Fischer. Have you... calmed down... now?",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F624A"
        },
        [10035410] = {
          Camera = "-154.007812,-60.436035,88.29541,0.000008,16.371765,18.595819,30.0,100000.0,false,Manual,13.369958",
          Content = "……你到底是谁？！",
          DialogueId = 10035410,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191F6274",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035411,
          SpeakNpcId = 100304,
          Subtitle = "...Who are you!? Answer me!",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F6274"
        },
        [10035411] = {
          Camera = "-29.5625,-71.805176,165.97998,0.0,7.367677,18.358356,50.0,100000.0,false,Manual,22.0",
          Content = "布鲁斯·费西尔。你的，弟弟。那把口琴的，主人。",
          DialogueId = 10035411,
          FinalCamera = "-29.5625,-71.805176,165.97998,0.0,11.16768,18.558241,50.0,100000.0,false,Manual,22.0",
          GUID = "191F629E",
          NextDialogue = 10035412,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Blues Fischer. Your younger brother. The owner of that harmonica.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100354/191F629E"
        },
        [10035412] = {
          Camera = "749.542969,-320.927246,358.976562,0.000014,-16.229792,146.761581,50.0,100000.0,false,Manual,22.0",
          Content = "布鲁斯？你为什么打扮成这样……你的嗓子怎么了……？",
          DialogueId = 10035412,
          FacialId = {
            [1] = "100304:Shock02"
          },
          FinalCamera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.0",
          GUID = "191F62C8",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035413,
          SpeakNpcId = 100304,
          Subtitle = "Blues? Why are you dressed like that...? What happened to your voice...?",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100354/191F62C8"
        },
        [10035413] = {
          Camera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.0",
          Content = "你不是一直在内城服役吗？为什么……你会……",
          DialogueId = 10035413,
          GUID = "191F62F2",
          NextDialogue = 10035414,
          SpeakNpcId = 100304,
          Subtitle = "I thought you were training in the inner city... Why... why are you...?",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F62F2"
        },
        [10035414] = {
          Camera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.00",
          Content = "呵……",
          DialogueId = 10035414,
          GUID = "191F631C",
          NextDialogue = 10035415,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "Heh...",
          VoiceName = "voice/$Locale$/story/1003/100354/191F631C"
        },
        [10035415] = {
          Camera = "221.476562,-7.47168,109.081543,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0",
          Content = "不对，你在说谎。我的弟弟布鲁斯热诚又善良，他视他人的痛苦为自己的痛苦，视所有同胞为手足！他不可能犯下<H>卡戎狩猎</>这种暴行！",
          DialogueId = 10035415,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "196.777344,-3.805176,112.84082,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0",
          GUID = "191F6346",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10035425,
          SpeakNpcId = 100304,
          Subtitle = "No... you're lying. My Blues has a heart of gold. He shares other people's suffering as if it were his own and treats every Charon like family! He'd never have committed atrocities like the Charon Hunt!",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6346"
        },
        [10035416] = {
          Camera = "196.777344,-3.805176,112.84082,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0",
          Content = "这是，小时候……我给布鲁斯做的链子……",
          DialogueId = 10035416,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter02_HarmonicaChain.T_Guide_Chapter02_HarmonicaChain'}",
          GUID = "191F6370",
          NextDialogue = 10035417,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/chainpocket\"},PlayAs2D{true}}",
          SpeakNpcId = 100304,
          Subtitle = "This... this is the chain I made for Blues when we were kids...",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6370"
        },
        [10035417] = {
          Camera = "-29.5625,-71.805176,165.97998,0.0,11.16768,18.558241,50.0,100000.0,false,Manual,22.0",
          Content = "还给你吧。军团，背叛了我。再也，用不到它了。",
          DialogueId = 10035417,
          GUID = "191F639A",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035418,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "Take it back. The Legion betrayed me. I don't need it anymore.",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F639A"
        },
        [10035418] = {
          Camera = "119.15625,42.66748,164.325195,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0",
          Content = "黎瑟，先别激动。我们之前领教过它的狡猾，它很可能是在借你弟弟的名头，实际别有所图。",
          DialogueId = 10035418,
          FinalCamera = "156.070312,53.80127,172.121582,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F63C4",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10035419,
          SpeakNpcId = 100001,
          Subtitle = "Rhythm, don't jump to conclusions. You've seen how cunning this monster is. He could just be disguising himself as your brother to manipulate you.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F63C4"
        },
        [10035419] = {
          Camera = "-331.53125,-373.69873,96.422363,10.800302,6.167674,40.957329,35.0,100000.0,false,Manual,22.0",
          Content = "……我多希望你说的是真的。但它的每一个动作，我都太熟悉了……",
          DialogueId = 10035419,
          FinalCamera = "-289.46875,-337.193848,102.441895,7.200046,6.167674,40.957287,35.0,100000.0,false,Manual,22.0",
          GUID = "191F63EE",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035420,
          SpeakNpcId = 100304,
          Subtitle = "...I wish that were true. But his every move... I know them too well...",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F63EE"
        },
        [10035420] = {
          Camera = "40.863281,-1146.140381,-4.161133,0.000027,7.377881,83.959587,50.0,100000.0,false,Manual,22.0",
          Content = "尤其是那个伸手在背后找东西的样子，和小时候的布鲁斯一模一样。",
          DialogueId = 10035420,
          FacialId = {
            [1] = "100304:Sad01"
          },
          GUID = "191F6418",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035421,
          SpeakNpcId = 100304,
          Subtitle = "Especially the way he reached behind himself to search for something... it's exactly how Blues used to look for his harmonica.",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6418"
        },
        [10035421] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117",
          Content = "……这么说来，它在见到黎瑟后，的确<H>一直在留手，没有伤害我们</>。",
          DialogueId = 10035421,
          GUID = "191F6442",
          LookAt = {
            [1] = "100001:n(100327)"
          },
          NextDialogue = 10035422,
          SpeakNpcId = 100001,
          Subtitle = "...Now that you mention it, since he saw Rhythm, he's been holding back to avoid hurting us.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F6442"
        },
        [10035422] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117",
          Content = "你还有意识，而且<H>你身上那些好像并不是铠甲</>……更像是……身体的一部分。你经历了什么？“军团背叛了你”是什么意思？",
          DialogueId = 10035422,
          GUID = "191F646C",
          NextDialogue = 10035423,
          SpeakNpcId = 100001,
          Subtitle = "So, you're still sentient. And... those mechanical pieces encasing you don't look like armour. They're more like... part of your body. What happened to you? What do you mean by \"the Legion betrayed you\"?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F646C"
        },
        [10035423] = {
          Camera = "-1343.695312,-699.813721,314.711426,10.834046,-7.832737,28.140293,50.0,100000.0,false,Manual,22.0",
          Content = "……你的，直觉，很敏锐。但这在帝国，不一定是，好事……",
          DialogueId = 10035423,
          FinalCamera = "-1351.945312,-685.367432,310.913574,10.833482,-7.832731,28.140591,50.0,100000.0,false,Manual,22.0",
          GUID = "191F6496",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10035424,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...Your instincts... are sharp. But in the Empire... that's not always... a good thing.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6496"
        },
        [10035424] = {
          Camera = "-1351.945312,-685.367432,310.913574,10.833482,-7.832731,28.140591,50.0,100000.0,false,Manual,22.0",
          Content = "……黎瑟，我的姐姐……让我来告诉你吧，“桂冠卡戎”的，真相……",
          DialogueId = 10035424,
          GUID = "191F64C0",
          LookAt = {
            [1] = "100327:n(100304)"
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Rhythm... my sister. Let me tell you... the cruel truth behind... the title of \"Laurelled Charon.\"",
          VoiceName = "voice/$Locale$/story/1003/100354/191F64C0"
        },
        [10035425] = {
          Camera = "53.945312,-48.872559,263.330078,0.000002,-24.832872,18.36636,28.000006,100000.0,false,Manual,22.0",
          DialogueId = 10035425,
          DialoguePanelType = "None",
          Duration = 7,
          GUID = "191F6347",
          NextDialogue = 10035416,
          Scripts = "PlayAnimation{_delay{0},ActorId{100327},AnimationId{\"Tuosi02_Story_Find02_Start\"},Duration{5}}"
        },
        [10035501] = {
          Content = "“桂冠卡戎”——我曾视它为一颗最璀璨的金刚石。\n它在梦想的尽头熠熠生辉，如冰湖城最高处，那盏不灭的明灯。",
          DialogueId = 10035501,
          Duration = 4,
          GUID = "191F7162",
          NextDialogue = 10035502,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The \"Laurelled Charon\" — once, I believed it to be a diamond of the utmost brilliance.\nIt gleamed at the horizon of my dreams, like the eternal light atop Icelake's highest peak.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7162"
        },
        [10035502] = {
          Content = "后来我才知道，那并非坚硬的金刚石。\n它是玻璃——折射着虚幻的光，美丽，夺目，\n但一颗卵石，一块泥砖，便将它轻易打碎。",
          DialogueId = 10035502,
          Duration = 4,
          GUID = "191F718C",
          NextDialogue = 10035503,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But later, I realised it wasn't a diamond at all.\nIt was glass — reflecting an illusory light. Beautiful, dazzling, but so fragile it could be shattered by a single pebble or a chunk of clay.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F718C"
        },
        [10035503] = {
          Content = "通过第六军团考核的卡戎之民，与任人宰割的困兽没有任何区别。\n倒不如说我们宁愿成为一头无知麻木的野兽——\n这样我们便不会为破灭的梦而痛苦，不会因无法完成的约定而恸哭。",
          DialogueId = 10035503,
          Duration = 4,
          GUID = "191F71B6",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "A Charon who passes the 6th Legion's tests is nothing more than a caged beast awaiting slaughter.\nIn truth, we would rather become numb, unthinking beasts —\nFor then we wouldn't endure the agony of shattered dreams or weep over unfulfilled promises.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71B6"
        },
        [10035504] = {
          Content = "（好刺眼的灯光……这是哪里？我记得通过考核后，被派到第六军团炼金院工作，然后……）",
          DialogueId = 10035504,
          GUID = "191F71E0",
          RelatedWikiId = {
            [1] = 407003,
            [2] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(Ah, this glare... Where am I? I remember passing the tests, being assigned to the 6th Legion's alchemy academy, and then...)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71E0"
        },
        [10035505] = {
          Content = "老师，改造体的意识好像提前苏醒了。它看起来很痛苦，我再取一点麻醉剂。",
          DialogueId = 10035505,
          GUID = "191F720A",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = [[
Professor, the test subject's consciousness seems to have awakened earlier than scheduled.
It seems to be in great pain. Should I administer another dose of anaesthetic?]],
          VoiceName = "voice/$Locale$/story/1003/100355/191F720A"
        },
        [10035506] = {
          Content = "无妨，醒了就醒了吧。做好准备，2分钟后开始采集它的抗性数据。",
          DialogueId = 10035506,
          GUID = "191F7234",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "No need. Let it stay awake. Begin resistance data extraction in two minutes.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7234"
        },
        [10035507] = {
          DialogueId = 10035507,
          GUID = "191F725E",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F725E"
        },
        [10035508] = {
          Content = "老师，数据出来了。它在这批改造体中的抗性表现优异，电流未能直接击穿您移植进去的第二心脏，火焰损伤了它的人造皮肤，导致它的体温远高于正常值。",
          DialogueId = 10035508,
          GUID = "191F7288",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = [[
Professor, the data is in. This one shows exceptional resistance among this batch of augmented subjects. 
The current test failed to breach the secondary heart you implanted, while fire has damaged its synthetic skin,
causing its body temperature to spike far beyond normal limits.]],
          VoiceName = "voice/$Locale$/story/1003/100355/191F7288"
        },
        [10035509] = {
          Content = "数据记录完毕。我先带它回去休息吧，它的体力恐怕撑不住了。",
          DialogueId = 10035509,
          GUID = "191F72B2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Data collection complete. It's on the verge of collapse — shall I take it back to rest?",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72B2"
        },
        [10035510] = {
          Content = "不要对这些恶魔报以无谓的怜悯。注射镇定剂，固定好四肢，接下来要进行强化实验了。",
          DialogueId = 10035510,
          GUID = "191F72DC",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = [[
Do not waste your compassion on these demons.
Administer the sedative, secure its limbs, and prepare for the next enhancement experiment.]],
          VoiceName = "voice/$Locale$/story/1003/100355/191F72DC"
        },
        [10035511] = {
          Content = "（痛……好痛啊……你们到底对我做了什么，全身每一处毛孔都在哀嚎着疼痛，你们听不到吗！）",
          DialogueId = 10035511,
          GUID = "191F7306",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(It hurts... It hurts so much... What have you done to me!? Every inch of my body is screaming in agony — can't you hear!?)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7306"
        },
        [10035512] = {
          Content = "多么丰富的表情。怎么？想要吠叫什么？可惜没机会了。",
          DialogueId = 10035512,
          GUID = "191F7330",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Such vivid expressions. What, are you trying to bark something at me? Too bad, you won't get the chance.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7330"
        },
        [10035513] = {
          Content = "镇定剂注射完毕。老师，我还是觉得——",
          DialogueId = 10035513,
          GUID = "191F735A",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Sedative administered, Professor. But I still think we should—",
          VoiceName = "voice/$Locale$/story/1003/100355/191F735A"
        },
        [10035514] = {
          Content = "听我吩咐。从它最敏感的尖角开始取样，这样我们才能得到更精确的数据。",
          DialogueId = 10035514,
          GUID = "191F7384",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Just follow my instructions. Begin with the horns — they are its most sensitive parts. This way, we'll get the most precise data.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7384"
        },
        [10035515] = {
          Content = "……是，老师……",
          DialogueId = 10035515,
          GUID = "191F73AE",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "...Understood, Professor...",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73AE"
        },
        [10035516] = {
          Content = "（好痛……好痛……这就是身为“恶魔的孩子”，必须经受的惩罚吗……）",
          DialogueId = 10035516,
          GUID = "191F73D8",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(It hurts... so much... Is this the punishment for being a \"Demon's Child\"?)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73D8"
        },
        [10035517] = {
          Content = "（但无论是怎样的罪孽，这样的痛苦……也早该还清了吧……！）",
          DialogueId = 10035517,
          GUID = "191F7402",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(But no matter the sins we bear, shouldn't such suffering and agony... have repaid it all by now!?)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7402"
        },
        [10035518] = {
          Content = "我们不知道这样的日子过去了多久，只知道自己的身体正一步步变成可怖的怪物。心也变得越发冰冷，碎裂在泪湖的冷风之中。",
          DialogueId = 10035518,
          GUID = "191F742C",
          NextDialogue = 10035519,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I don't know how long those days dragged on, only that my body was slowly twisted into the shape of a grotesque monster. My heart grew colder with each passing moment, shattered into shards by the frigid winds of Lamenting Lake.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F742C"
        },
        [10035519] = {
          Content = "生而为人的旧日记忆渐行渐远。最终，连名字都被遗忘。",
          DialogueId = 10035519,
          GUID = "191F7456",
          NextDialogue = 10035520,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The old memories as a human slipped further and further away, until even my name was lost, swallowed by the abyss.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7456"
        },
        [10035520] = {
          Content = "布鲁斯·费西尔死了。取而代之的是<W>47号</>——这个新的“称呼”。",
          DialogueId = 10035520,
          GUID = "191F7480",
          NextDialogue = 10035521,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Blues Fischer is dead. In his place remains a hollow shell, his name erased — now known only as Subject 47.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7480"
        },
        [10035521] = {
          Content = "可即使如此，我们的肉体依旧在苟延残喘地挣扎着。",
          DialogueId = 10035521,
          GUID = "191F74AA",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "And yet, this wretched body still clung desperately to the instinct to survive.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F74AA"
        },
        [10035522] = {
          Camera = "-4.90918,-156.237305,105.101868,-0.000091,10.758511,116.110672,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "报告老师，排异反应终止了，各项指标趋于平稳。就是β型抑制剂好像使用太多了，精神状态不稳定。",
          DialogueId = 10035522,
          FinalCamera = "-9.579102,-158.523438,105.101868,-0.000092,10.758511,114.710289,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "191F74D4",
          NextDialogue = 10035523,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000069,7.559721,84.699837,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000061,11.159675,84.499451,35.0,100000.0,false,DoNotOverride,2.8\"},duration{5}}}",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Professor, the subject's rejection response has ceased, and all vital signs are stabilising. However, it seems we've overused the β-type suppressant — the subject's mental state is unstable.",
          TalkActionId = {
            [1] = "100337:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74D4"
        },
        [10035523] = {
          Camera = "-179.390625,29.248047,164.763611,0.000084,-5.841492,-25.696522,35.0,251.812622,false,Manual,2.797869",
          Content = "精神不过是生命代谢的废料，改造体能回答“是”就足够了。带它去试验场。",
          DialogueId = 10035523,
          FinalCamera = "-182.842773,22.280273,164.763611,0.000086,-5.841492,-21.695681,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F74FE",
          NextDialogue = 10035524,
          SpeakNpcId = 100337,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "The mind is nothing more than a byproduct of biological processes. All we need is obedience — as long as the subject can respond with a \"yes.\" Take it to the testing ground.",
          TalkActionId = {
            [1] = "100337:Explain01_End",
            [2] = "100336:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74FE"
        },
        [10035524] = {
          Camera = "20.333008,-203.238281,111.764038,0.00009,4.758661,116.695335,35.0,251.812622,false,Manual,2.797869",
          Content = "是，老师。",
          DialogueId = 10035524,
          FinalCamera = "20.333008,-203.238281,111.764038,0.000089,7.758616,116.69487,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F7528",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Yes, Professor.",
          TalkActionId = {
            [1] = "100337:Agree",
            [2] = "100336:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F7528"
        },
        [10035601] = {
          Content = "有抑制剂在，<H>连违背我们的命令都做不到</>，简直像是牲畜一样。",
          DialogueId = 10035601,
          GUID = "191F81CA",
          NextDialogue = 10035602,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "With those suppressants, it couldn't defy our orders even if it tried. Like pathetic, mindless beasts.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81CA"
        },
        [10035602] = {
          Content = "凶恶野蛮，缺乏理性且毫无美感。不过，这才是卡戎之民原初的模样。",
          DialogueId = 10035602,
          GUID = "191F81F4",
          NextDialogue = 10035603,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Savage, brutish, devoid of intelligence or elegance. Hmph, but this is the true form of a Charon.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81F4"
        },
        [10035603] = {
          Content = "喂，离它远点，说不定身上有什么不干净的呢。",
          DialogueId = 10035603,
          GUID = "191F821E",
          NextDialogue = 10035604,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Hey, stay away from it. Who knows what kind of filth it's carrying?",
          VoiceName = "voice/$Locale$/story/1003/100356/191F821E"
        },
        [10035604] = {
          Content = "等会儿好好记下它的战斗数据，不达标或者有可疑举动就处理掉。",
          DialogueId = 10035604,
          GUID = "191F8248",
          NextDialogue = 10035605,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Make sure to record its combat data thoroughly. If it fails to meet the standards or shows any suspicious behaviour, dispose of it immediately.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8248"
        },
        [10035605] = {
          Content = "这样真的可以吗？会不会太残忍了？",
          DialogueId = 10035605,
          GUID = "191F8272",
          NextDialogue = 10035606,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Are you sure we can do that? This feels excessively cruel, doesn't it?",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8272"
        },
        [10035606] = {
          Content = "不，应该说正是吾皇的仁慈和炼金技术的伟大，才能赐予这样的垃圾献身于炼金院的价值。",
          DialogueId = 10035606,
          GUID = "191F829C",
          NextDialogue = 10035607,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Cruel? You've got it all wrong. It is by His Majesty's benevolence and the magnificence of alchemical technology that this trash has been given the honour of serving the academy's great cause.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F829C"
        },
        [10035607] = {
          Content = "不要想着逃跑，电网与机炮可不像我们这般仁慈。也不要想着自毁，我们还有不少药品可以延续你那一文不值的生命。",
          DialogueId = 10035607,
          GUID = "191F82C6",
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Don't even think about running. The electrified grids and gun turrets are far less forgiving than we are. And forget self-destruction — we have plenty of drugs to prolong your worthless existence.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C6"
        },
        [10035608] = {
          Content = "测试开始，投放改造体。",
          DialogueId = 10035608,
          GUID = "191F82F0",
          NextDialogue = 10035609,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test begins. Release the subject.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82F0"
        },
        [10035609] = {
          Content = "47号，消灭一切阻拦者。",
          DialogueId = 10035609,
          GUID = "191F831A",
          NextDialogue = 10035610,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Subject 47, eliminate all obstacles.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F831A"
        },
        [10035610] = {
          Content = "是。",
          DialogueId = 10035610,
          GUID = "191F8344",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Yes.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8344"
        },
        [10035611] = {
          Content = "那边还有敌人，不要停下来哦。",
          DialogueId = 10035611,
          GUID = "191F836E",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "There are still enemies over there. Don't stop now.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F836E"
        },
        [10035612] = {
          Content = "数据落后预期了，去把那边的敌人也清理掉，快。",
          DialogueId = 10035612,
          GUID = "191F8398",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "The numbers are underwhelming. Go and clear out the enemies over there. Now.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8398"
        },
        [10035613] = {
          Content = "加油！加油！",
          DialogueId = 10035613,
          GUID = "191F83C2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Keep it up! Keep it up!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83C2"
        },
        [10035614] = {
          Content = "受伤了？这么脆弱吗？",
          DialogueId = 10035614,
          GUID = "191F83EC",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Injured already? Useless worm.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83EC"
        },
        [10035615] = {
          Content = "去那边哦~",
          DialogueId = 10035615,
          GUID = "191F8416",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Go that way! Hurry up~!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8416"
        },
        [10035616] = {
          Content = "那边的敌人还有口气，这种敌人都处理不好吗？",
          DialogueId = 10035616,
          GUID = "191F8440",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "That one over there is still breathing. Can't you even handle that? Finish it!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8440"
        },
        [10035617] = {
          Content = "测试通过，带回收容处。我们准备迎接下一批改造体了。",
          DialogueId = 10035617,
          GUID = "191F846A",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test complete. Return it to the cell. Prepare for the next batch of subjects.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F846A"
        },
        [10035618] = {
          Content = "数据什么时候出来？等不及了。",
          DialogueId = 10035618,
          GUID = "191F82C7",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "When's the data coming in? I'm running out of patience.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C7"
        },
        [10035619] = {
          Content = "希望这只能成功吧。",
          DialogueId = 10035619,
          GUID = "191F82C8",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Let's hope it works this time.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C8"
        },
        [10035620] = {
          Content = "三天后开始第五次强化。",
