        [10035704] = {
          Camera = "316.166016,-370.8125,168.484741,0.000076,8.598402,-44.815922,20.000011,335.406189,false,DoNotOverride,1.2",
          Content = "不想说话没事。你随便出一下声，让我知道你也活着就好。",
          DialogueId = 10035704,
          FinalCamera = "290.038086,-344.858398,162.916687,0.000075,8.598402,-44.815895,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F92B0",
          NextDialogue = 10035705,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Not in the mood to talk? That's fine. Just make a sound so I know you're alive.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F92B0"
        },
        [10035705] = {
          Camera = "-180.529297,-310.954102,177.634216,0.000067,1.398201,38.782471,20.000011,335.406189,false,DoNotOverride,1.2",
          Content = "……47号。",
          DialogueId = 10035705,
          FinalCamera = "-190.380859,-298.686523,177.634216,0.000067,1.1982,38.781147,20.000011,335.406189,false,DoNotOverride,1.2",
