        },
        [10036003] = {
          Camera = "463.391602,-580.462891,220.541992,0.000188,-7.202789,119.394897,20.0,678.51178,false,Manual,3.0",
          Content = "喂……",
          DialogueId = 10036003,
          FinalCamera = "463.229492,-580.175781,220.541992,0.000189,-7.202789,118.994843,20.0,70.352333,false,Manual,3.0",
          GUID = "191FC3BE",
          NextDialogue = 10036004,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Hey...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC3BE"
        },
        [10036004] = {
          Camera = "-43.522461,-123.954102,225.915833,0.000146,-7.596761,-21.001686,20.000008,100000.0,false,Manual,22.0",
          Content = "……",
          DialogueId = 10036004,
          GUID = "191FC3E8",
          NextDialogue = 10036005,
          Scripts = "PlayAnimation{_delay{2},ActorId{100331},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC3E8"
        },
        [10036005] = {
          Camera = "58.138672,-330.501953,109.144714,0.000134,8.597835,-22.997952,35.0,291.655762,false,Manual,2.8",
          Content = "嘿……这个，拿去……应该能缓解一下我们白天受的伤。",
          DialogueId = 10036005,
          FinalCamera = "58.137695,-330.5,140.144714,0.000134,8.597835,-22.997952,35.0,291.655762,false,Manual,2.8",
          GUID = "191FC412",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10036006,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Hey... here, take this... it should help ease the injuries from earlier.",
          TalkActionId = {
            [1] = "100331:Give"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100328:n(100331)"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC412"
        },
        [10036006] = {
          Camera = "463.391602,-580.462891,220.541992,0.000188,-7.202789,119.394897,20.0,678.51178,false,Manual,3.0",
          Content = "……所以你白天任务完成那么慢，还挨了打，就是为了这几瓶药？",
          DialogueId = 10036006,
          GUID = "191FC43C",
          NextDialogue = 10036007,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...So that's why you dragged your tasks out today? Even took a good thrashing, just to get your hands on these phials of medicine?",
          TalkActionId = {
            [1] = "100328:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC43C"
        },
        [10036007] = {
          Content = "被你发现了呀……",
          DialogueId = 10036007,
          GUID = "191FC466",
          NextDialogue = 10036008,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Caught me, huh...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC466"
        },
        [10036008] = {
          Camera = "185.640625,-233.083984,160.088501,0.000144,8.996766,-43.391754,35.0,526.580566,false,Manual,2.8",
          Content = "可别放弃活下去的念头。我说过，要带你活着逃出去。",
          DialogueId = 10036008,
          GUID = "191FC490",
          LookAt = {
            [1] = "100328:n(100328)"
          },
          NextDialogue = 10036009,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Don't you dare give up. I told you — I'm getting us both out of here alive.",
          TalkActionId = {
            [1] = "100331:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC490"
        },
        [10036009] = {
          Camera = "-267.09668,-233.355469,217.466675,-0.000031,-3.001649,50.570717,25.0,335.406189,false,DoNotOverride,1.2",
          Content = "为什么想活着？我们都这样了，出去了又能有什么好事？",
          DialogueId = 10036009,
          GUID = "191FC4BA",
          NextDialogue = 10036010,
          Scripts = "MoveTo{ActorId{100328},TargetPoint{\"tuosi01_walk3\"},MoveSpeed{200},Visibility{\"Show\"}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Why bother? Even if we managed to escape, what kind of life awaits us now that we've become like this?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC4BA"
        },
        [10036010] = {
          Camera = "160.84668,-584.186523,204.747314,-0.00003,-2.401276,24.76207,25.000002,335.406189,false,DoNotOverride,1.2",
          Content = "但死掉就永远不会发生好事，我不甘心。",
          DialogueId = 10036010,
          GUID = "191FC4E4",
          NextDialogue = 10036011,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "But once you're dead, nothing good can ever happen to you again. I won't go down without a fight.",
          TalkActionId = {
            [1] = "100331:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC4E4"
        },
        [10036011] = {
          Camera = "307.469727,-340.191406,161.595886,0.000178,13.19656,-47.393784,35.000011,241.246582,false,Manual,2.799999",
          Content = "我们都还有梦想没实现吧。",
          DialogueId = 10036011,
          GUID = "191FC50E",
          NextDialogue = 10036012,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "We both have dreams we've yet to fulfil, haven't we?",
          TalkActionId = {
            [1] = "100331:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC50E"
        },
        [10036012] = {
          Camera = "498.730469,-495.881836,208.647461,0.00018,-0.003142,142.201035,50.0,241.246582,false,Manual,22.0",
          Content = "不重要了，反正都这样了。",
          DialogueId = 10036012,
          FinalCamera = "447.958984,-456.501953,208.644409,0.00018,-0.003142,142.201035,50.0,241.246582,false,Manual,22.0",
          GUID = "191FC538",
          NextDialogue = 10036013,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Doesn't matter anymore. Look at us now.",
          TalkActionId = {
            [1] = "100328:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC538"
        },
        [10036013] = {
          Camera = "-223.761719,17.283203,231.583618,0.000198,-9.803254,-22.194181,20.0,241.246582,false,Manual,22.0",
          Content = "讲讲。反复说起，能提醒我们还是个人。",
          DialogueId = 10036013,
          GUID = "191FC562",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10036014,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Tell me about them. Talking about your dreams reminds you that you're still human.",
          TalkActionId = {
            [1] = "100331:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC562"
        },
        [10036014] = {
          Camera = "-217.935547,-11.030273,239.382629,0.000152,-16.403408,10.210232,35.000008,241.246582,false,Manual,22.0",
          Content = "…………",
          DialogueId = 10036014,
          GUID = "191FC58C",
          LookAt = {
            [1] = "100328:n(100328)"
          },
          NextDialogue = 10036015,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC58C"
        },
        [10036015] = {
          Content = "……演员……",
          DialogueId = 10036015,
          GUID = "191FC5B6",
          NextDialogue = 10036016,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...A performer...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC5B6"
        },
        [10036016] = {
          Camera = "475.610352,-611.675781,221.689697,0.000148,-7.606269,121.213806,20.0,1261.194092,false,Manual,22.0",
          Content = "什么？",
          DialogueId = 10036016,
          GUID = "191FC5E0",
          NextDialogue = 10036017,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Huh?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC5E0"
        },
        [10036017] = {
          Camera = "475.610352,-611.675781,221.689697,0.000148,-7.606269,121.213806,20.0,1261.194092,false,Manual,22.0",
          Content = "我曾经的梦想是做个演员。",
          DialogueId = 10036017,
          GUID = "191FC60A",
          NextDialogue = 10036018,
          Scripts = [[
PARA{
MoveTo{ActorId{100328},TargetPoint{"tuosi01_walk4"},MoveSpeed{120},Visibility{"Show"}},
CameraMoveTo{_delay{1},TargetPosition{"-347.200195,-320.677734,160.137878,0.000141,6.99427,50.212906,35.000008,1261.194092,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I used to dream of becoming a performer.",
          TalkActionId = {
            [1] = "100328:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC60A"
        },
        [10036018] = {
          Camera = "-165.179688,-114.144531,207.396362,0.000156,-2.605772,-133.186981,25.0,1261.194092,false,Manual,22.0",
          Content = "参加第六军团的考核，也是为了有朝一日成为“桂冠卡戎”。只要过上更好的生活，就有机会登上更广大的舞台……",
          DialogueId = 10036018,
          FinalCamera = "-187.849609,-138.015625,206.04657,0.000155,-1.805758,-134.186615,25.0,1261.194092,false,Manual,22.0",
          GUID = "191FC634",
          NextDialogue = 10036019,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Participating in the 6th Legion's tests was meant to be my first step toward becoming a Laurelled Charon. I thought if I could build a better life, I might one day stand on a grander stage...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC634"
        },
        [10036019] = {
          Camera = "483.212891,-613.606445,221.566162,0.000146,-6.40518,124.602669,25.0,189.198608,false,Manual,22.0",
          Content = "再也不会只能对着舞台上的演员发呆，对着满屋的录音带沉默，只因为卡戎之民没有资格参加演出，因为头上那根角会污了观众的眼。",
          DialogueId = 10036019,
          GUID = "191FC65E",
          NextDialogue = 10036020,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I wouldn't have to hide in the shadows anymore, watching others bask in the spotlight, or surround myself with tapes of songs I couldn't even play — all because, as a Charon, my horn was deemed \"sickening\" to the audience.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC65E"
        },
        [10036020] = {
          Camera = "223.780273,-418.617188,192.429321,0.000123,5.795101,-18.393356,35.0,189.198654,false,Manual,2.8",
          Content = "哈，哈哈。",
          DialogueId = 10036020,
          GUID = "191FC688",
          NextDialogue = 10036021,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Ha, hahaha.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC688"
        },
        [10036021] = {
          Content = "很可笑吧。",
          DialogueId = 10036021,
          GUID = "191FC6B2",
          NextDialogue = 10036022,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I know — it's a ridiculous dream.",
          TalkActionId = {
            [1] = "100328:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC6B2"
        },
        [10036022] = {
          Content = "我是觉得很搭。",
          DialogueId = 10036022,
          GUID = "191FC6DC",
          NextDialogue = 10036023,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "No, I just thought of us.",
          TalkActionId = {
            [1] = "100331:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC6DC"
        },
        [10036023] = {
          Camera = "-277.438477,12.542969,206.000488,0.000168,-2.405633,-27.593695,35.000008,989.247986,false,Manual,2.8",
          Content = "我也喜欢歌剧，难怪会和你一见如故。等我们逃出去，我们就搭个舞台，叫来亲朋好友，看我们表演。",
          DialogueId = 10036023,
          GUID = "191FC706",
          NextDialogue = 10036024,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I love opera too. No wonder we hit it off. After we get out, we'll set up a stage of our own, invite everyone we know, and put on a wonderful show for them.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC706"
        },
        [10036024] = {
          Camera = "199.172852,-433.332031,223.718994,0.000192,-3.005399,132.20047,35.000008,938.13208,false,Manual,2.8",
          Content = "…………",
          DialogueId = 10036024,
          FinalCamera = "215.05957,-418.922852,223.388977,0.000192,-3.005399,132.20047,35.000008,938.13208,false,Manual,2.8",
          GUID = "191FC730",
          NextDialogue = 10036025,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC730"
        },
        [10036025] = {
          Camera = "198.80957,-348.649414,122.465942,0.000148,16.993544,-28.586533,35.0,302.68161,false,Manual,2.8",
          Content = "不说话我就当你答应了，答应的诺言就得遵守。",
          DialogueId = 10036025,
          GUID = "191FC75A",
          NextDialogue = 10036026,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I'll take that as a yes. And a promise is a promise — I'll hold you to it.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC75A"
        },
        [10036026] = {
          Content = "我有预感，离开的机会就要到了。",
          DialogueId = 10036026,
          GUID = "191FC784",
          LookAt = {
            [1] = "100331:n(100328)"
          },
          NextDialogue = 10036027,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I've got a feeling... our chance to escape is coming.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC784"
        },
        [10036027] = {
          Camera = "-336.173828,-305.694336,191.327087,0.000173,2.392745,50.61248,35.000008,302.68161,false,Manual,2.8",
          Content = "错觉罢了。",
          DialogueId = 10036027,
          FinalCamera = "-312.927734,-277.383789,192.857788,0.000173,2.392745,50.612766,35.000011,302.68161,false,Manual,2.8",
          GUID = "191FC7AE",
          NextDialogue = 10036028,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "It might be just a delusion.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC7AE"
        },
        [10036028] = {
          Camera = "198.80957,-348.649414,122.465942,0.000148,16.993544,-28.586533,35.0,302.68161,false,Manual,2.8",
          Content = "这可不是错觉，你没感觉这些年下来，<H>抑制剂对我们的效果减弱了</>吗？",
          DialogueId = 10036028,
          GUID = "191FC7D8",
          NextDialogue = 10036029,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "It's not. Haven't you noticed? The suppressants have been growing less effective on us over the years.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC7D8"
        },
        [10036029] = {
          Content = "这就是我们还是人的证明，连身体都在提醒我们，该反抗了！",
          DialogueId = 10036029,
          GUID = "191FC802",
          NextDialogue = 10036030,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "That's proof we're still human — even our bodies are telling us it's time to fight for ourselves!",
          TalkActionId = {
            [1] = "100331:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC802"
        },
        [10036030] = {
          Camera = "-64.507812,-225.208984,216.510254,0.000098,-1.602383,103.814949,20.0,302.68161,false,Manual,2.8",
          Content = "说难听点，就是这具该死的怪物的身体变异得太成功了。",
          DialogueId = 10036030,
          FinalCamera = "-64.507812,-225.208984,216.510254,0.000069,-43.801937,102.617737,20.0,302.68161,false,Manual,2.8",
          GUID = "191FC82C",
          NextDialogue = 10036031,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Or maybe it's just this cursed, monstrous body mutating for its own survival.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC82C"
        },
        [10036031] = {
          Camera = "201.640625,-253.776367,315.783325,0.000122,-19.205063,-42.193974,35.0,302.68161,false,Manual,2.8",
          Content = "哈哈，炼金术师还没注意到这种变异，结果来说是好的嘛！我想想，我们得约个行动暗号……",
          DialogueId = 10036031,
          FinalCamera = "221.570312,-272.848633,306.172791,0.000119,-19.20507,-43.193863,35.0,302.68161,false,Manual,2.8",
          GUID = "191FC856",
          NextDialogue = 10036032,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Haha, but the alchemists haven't even noticed it yet. Their negligence is our chance. Let me think... we should come up with a secret signal for when the time comes.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC856"
        },
        [10036032] = {
          Camera = "-268.056641,6.759766,219.209229,0.000128,-4.005373,-26.392078,35.000008,1151.087158,false,Manual,2.8",
          Content = "…………",
          DialogueId = 10036032,
          FinalCamera = "-268.056641,6.759766,219.209229,0.000128,-4.005373,-26.392078,35.000008,166.311462,false,Manual,2.8",
          GUID = "191FC880",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC880"
        },
        [10036033] = {
          Content = "喂，你猜会是几号？",
          DialogueId = 10036033,
          GUID = "191FC881",
          Subtitle = "Hey, which one do you think it's gonna be this time?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC881"
        },
        [10036034] = {
          Content = "还真不好猜，数据实在是太接近了。",
          DialogueId = 10036034,
          GUID = "191FC882",
          Subtitle = "Hard to say — their metrics are almost identical.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC882"
        },
        [10036035] = {
          Content = "我把今天的工作都推掉了，可别让我失望啊。",
          DialogueId = 10036035,
          GUID = "191FC883",
          Subtitle = "Cleared my whole schedule for this. They'd better not disappoint.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC883"
        },
        [10036036] = {
          Content = "嘿嘿嘿嘿嘻嘻嘻嘻……我真是兴奋到不行了。",
          DialogueId = 10036036,
          GUID = "191FC884",
          Subtitle = "Heeheeheehee... ahahaha... I'm so excited I can barely breathe...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC884"
        },
        [10036101] = {
          Content = "最终测验开始，来比一比谁才是最成功的改造体吧！",
          DialogueId = 10036101,
          Duration = 7,
          GUID = "191FD3D2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "The final test begins! Let's find out which one of you is the ultimate augmented subject!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD3D2"
        },
        [10036102] = {
          Content = "怎么会……是我们俩的交战？！",
          DialogueId = 10036102,
          Duration = 5,
          GUID = "191FD3FC",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What!? They're making us fight each other!?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD3FC"
        },
        [10036103] = {
          Content = "看来我们终究是别无选择啊……",
          DialogueId = 10036103,
          Duration = 4.5,
          GUID = "191FD426",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "We really don't have a choice, do we?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD426"
        },
        [10036104] = {
          Content = "那就只好，<H>动手吧！</>",
          DialogueId = 10036104,
          Duration = 3.5,
          GUID = "191FD450",
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Guess not. Bring it on, then!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD450"
        },
        [10036105] = {
          Content = "…………？！",
          DialogueId = 10036105,
          Duration = 1.2,
          GUID = "191FD47A",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD47A"
        },
        [10036106] = {
          Content = "记得你要登台演出，别失约。",
          DialogueId = 10036106,
          GUID = "191FD4A4",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Remember, you've got a stage waiting for you.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4A4"
        },
        [10036107] = {
          Content = "做不到的许诺，没有意义。",
          DialogueId = 10036107,
          GUID = "191FD4CE",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What's the point of making promises you can't keep?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4CE"
        },
        [10036108] = {
          Content = "会有意义的。",
          DialogueId = 10036108,
          GUID = "191FD4F8",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Because someday, they might just be fulfilled.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4F8"
        },
        [10036109] = {
          Content = "36号！！你做什么！请求支援，改造体狂暴反应，请求支援！",
          DialogueId = 10036109,
          GUID = "191FD522",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "36!! What the hell are you doing!? Subject exhibiting extreme instability! Requesting backup!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD522"
        },
        [10036110] = {
          Content = "什么……你可没说过是用这种方式逃出去！",
          DialogueId = 10036110,
          GUID = "191FD54C",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What...!? You never said anything about making it out like this!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD54C"
        },
        [10036111] = {
          Content = "咳……我……绝不食言……",
          DialogueId = 10036111,
          GUID = "191FD576",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "*coughs* I... never go back on my word...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD576"
        },
        [10036112] = {
          Content = "……开了！",
          DialogueId = 10036112,
          GUID = "191FD5A0",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...It's open!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5A0"
        },
        [10036113] = {
          Content = "抱、抱歉老师……我没想到改造体居然能突破抑制剂的控制……",
          DialogueId = 10036113,
          GUID = "191FD5CA",
          NextDialogue = 10036114,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "P—Professor... I'm sorry! I didn't expect the subjects to resist the suppressant's effect...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5CA"
        },
        [10036114] = {
          Content = "这是所有改造体身上都未曾有过的<H>异变</>，也许这就是我们最成功的杰作！",
          DialogueId = 10036114,
          GUID = "191FD5F4",
          NextDialogue = 10036115,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "This kind of mutation is unprecedented in any of our test subjects. Fascinating... Perhaps they're our greatest masterpiece yet!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5F4"
        },
        [10036115] = {
          Content = "封锁消息！使用最新的γ型抑制剂！务必活捉改造体！",
          DialogueId = 10036115,
          GUID = "191FD61E",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Lock down all information! Deploy the latest γ-type suppressant — bring the subject in alive, no matter the cost!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD61E"
        },
        [10036116] = {
          Content = "咳、咳……我做到了吗……",
          DialogueId = 10036116,
          GUID = "191FD648",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036117,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "*coughs* Did I make it...?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD648"
        },
        [10036117] = {
          Content = "做到了，你做到了！",
          DialogueId = 10036117,
          GUID = "191FD672",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036118,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Yes! You made it!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD672"
        },
        [10036118] = {
          Content = "那就，好……",
          DialogueId = 10036118,
          GUID = "191FD69C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036119,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Great...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD69C"
        },
        [10036119] = {
          Content = "逃？这世上除了战场与实验室，哪里有你们怪物的容身之所！",
          DialogueId = 10036119,
          GUID = "191FD6C6",
          NextDialogue = 10036120,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Where do you think you can run off to? Monsters like you have no place in this world — your only purpose is to serve on the battlefield or in a lab!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD6C6"
        },
        [10036120] = {
          Content = "…………",
          DialogueId = 10036120,
          GUID = "191FD6F0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036121,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD6F0"
        },
        [10036121] = {
          Content = "我们不是怪物。我们是，人……！",
          DialogueId = 10036121,
          GUID = "191FD71A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "We're not monsters... We're human!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD71A"
        },
        [10036122] = {
          Content = "这边！",
          DialogueId = 10036122,
          GUID = "191FD744",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036123,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "This way!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD744"
        },
        [10036123] = {
          Content = "这是……风吗？自由的……咳、咳……",
          DialogueId = 10036123,
          GUID = "191FD76E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Is this... wind? The air of freedom... *coughs*",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD76E"
        },
        [10036124] = {
          Content = "这里有水声，一定能通向外面。",
          DialogueId = 10036124,
          GUID = "191FD798",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036125,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I hear water. There must be an outlet leading outside.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD798"
        },
        [10036125] = {
          Content = "真是，太好了，咳……",
          DialogueId = 10036125,
          GUID = "191FD7C2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Thank god... *coughs*",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD7C2"
        },
        [10036126] = {
          Camera = "1359.609375,981.171387,600.210815,0.000034,-15.799866,-145.19664,35.0,100000.0,false,Manual,22.0",
          Content = "我们出来了！",
          DialogueId = 10036126,
          GUID = "191FD7EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036126.T_Story_Recall_10036126'",
          NextDialogue = 10036127,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "We made it out!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD7EC"
        },
        [10036127] = {
          Content = "这是炼金院的下水道……应该会有通到外面的排水口。",
          DialogueId = 10036127,
          GUID = "191FD816",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036127.T_Story_Recall_10036127'",
          NextDialogue = 10036128,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "This is the academy's drainage tunnels... There must be an outlet leading outside.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD816"
        },
        [10036128] = {
          Content = "太好了……我们……自由了……",
          DialogueId = 10036128,
          GUID = "191FD840",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036128.T_Story_Recall_10036128'",
          NextDialogue = 10036129,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Can't believe we actually made it... We're... finally free...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD840"
        },
        [10036129] = {
          Content = "——呃！",
          DialogueId = 10036129,
          GUID = "191FD86A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036129.T_Story_Recall_10036129'",
          NextDialogue = 10036130,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Ugh...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD86A"
        },
        [10036130] = {
          Content = "你的伤……接下来交给我。",
          DialogueId = 10036130,
          GUID = "191FD894",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036130.T_Story_Recall_10036130'",
          NextDialogue = 10036131,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "You're hurt... I'll take care of everything from here.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD894"
        },
        [10036131] = {
          Content = "首先，要找个地方藏身……",
          DialogueId = 10036131,
          GUID = "191FD8BE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036131.T_Story_Recall_10036131'",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "First, we need to find a place to hide...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD8BE"
        },
        [10036201] = {
          Camera = "-112.558594,-18.889648,137.671387,0.000057,0.198957,165.584488,35.0,100000.0,false,Manual,22.0",
          Content = "原来下水道那个奇怪的舞台，就是你们一点点搭起来的啊。",
          DialogueId = 10036201,
          FinalCamera = "-112.96875,-20.488281,147.573242,0.000057,0.198957,165.584488,35.0,100000.0,false,Manual,22.0",
          GUID = "191FE43A",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)",
            [5] = "100327:n(100304)"
          },
          NextDialogue = 10036202,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SpeakNpcId = 200021,
          Subtitle = "So you were the ones who built that strange stage in the sewers?",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE43A"
        },
        [10036202] = {
          Camera = "602.476562,-249.944336,360.538574,0.000065,-25.800716,151.990204,20.0,100000.0,false,Manual,22.0",
          Content = "怎会……为什么……布鲁斯……你……",
          DialogueId = 10036202,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE464",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "200021:n(100304)"
          },
          NextDialogue = 10036203,
          Scripts = "MoveTo{ActorId{100304},MoveSpeed{120},TargetPoint{\"lise_56_walk\"}}",
          SpeakNpcId = 100304,
          Subtitle = "How... why... how could this happen to you... Blues...",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE464"
        },
        [10036203] = {
          Camera = "255.566406,-24.741699,131.422363,0.000058,0.598905,163.386917,35.0,100000.0,false,Manual,22.0",
          Content = "……还痛吗？",
          DialogueId = 10036203,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "223.371094,-15.542969,131.395508,0.000058,1.398898,162.986725,35.0,100000.0,false,Manual,22.0",
          GUID = "191FE48E",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10036204,
          SpeakNpcId = 100304,
          Subtitle = "...Does it still hurt?",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE48E"
        },
        [10036204] = {
          Camera = "-10.363281,-8.108887,102.920898,0.000115,20.997046,15.209096,25.000006,495.125,false,Manual,2.799999",
          Content = "我……还好。",
          DialogueId = 10036204,
          GUID = "191FE4B8",
          NextDialogue = 10036205,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...I'm fine.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE4B8"
        },
        [10036205] = {
          Camera = "90.679688,-10.201172,155.186035,0.000029,19.198732,13.00046,25.000006,233.5448,false,Manual,2.8",
          Content = "只可惜，命运只是，短暂地，垂怜了我们一下。逃出炼金院，不是，新生活的开始，而是，结束……",
          DialogueId = 10036205,
          GUID = "191FE4E2",
          NextDialogue = 10036206,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But fate only gave us a fleeting moment of mercy — escaping the academy wasn't the start of a new life... but the beginning of the end.",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE4E2"
        },
        [10036206] = {
          Content = "……逃跑时，炼金术师，新型抑制剂……毁掉了，我的，喉咙，更摧毁了……心智……",
          DialogueId = 10036206,
          GUID = "191FE50C",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036207,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "During our escape... the alchemists... their new suppressant ruined my voice... and messed up our minds...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE50C"
        },
        [10036207] = {
          Content = "我们时常，发疯，失控……而我的朋友，<H>36号</>，已经先我一步……",
          DialogueId = 10036207,
          GUID = "191FE536",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036208,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "We couldn't control ourselves... we'd go berserk from time to time... And my friend... 36... has already left this world before me.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE536"
        },
        [10036208] = {
          Camera = "-178.277344,-33.839355,138.938477,0.00009,5.597422,154.782913,50.0,239.778275,false,Manual,22.0",
          Content = "啧，早就知道炼金院那群炼金术师不是人，没想到这么不是人。居然和第六军团勾结，把魔法资质好的卡戎之民骗去做实验……",
          DialogueId = 10036208,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191FE560",
          NextDialogue = 10036209,
          SpeakNpcId = 200021,
          Subtitle = "Ugh, I always knew those alchemists were wicked scum, but this... this is cruelty on an entirely different level. And to think they had the gall to go in cahoots with the 6th Legion, luring Charons with strong magical aptitude just to turn them into test subjects...",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE560"
        },
        [10036209] = {
          Camera = "201.75,1.508789,159.896973,-6.000039,-11.003229,172.177917,25.000006,100000.0,false,Manual,22.0",
          Content = "姐姐，你听好。",
          DialogueId = 10036209,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE58A",
          NextDialogue = 10036210,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Listen, Sister.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE58A"
        },
        [10036210] = {
          Camera = "55.476562,-24.161621,154.890137,-6.00001,14.795302,12.594482,25.000002,100000.0,false,Manual,22.0",
          Content = "第六军团，用桂冠卡戎，欺骗我们。",
          DialogueId = 10036210,
          FinalCamera = "55.476562,-24.161621,154.890137,-6.000008,17.595236,12.594818,25.000002,100000.0,false,Manual,22.0",
          GUID = "191FE5B4",
          NextDialogue = 10036211,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The 6th Legion... they use the title of \"Laurelled Charon\"... as a lure to deceive us.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE5B4"
        },
        [10036211] = {
          Camera = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
          Content = "离开，军团。",
          DialogueId = 10036211,
          GUID = "191FE5DE",
          NextDialogue = 10036212,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "LEAVE... the Legion.",
          TalkActionId = {
            [1] = "100327:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE5DE"
        },
        [10036212] = {
          Camera = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
          Content = "找个，安稳的地方，好好——",
          DialogueId = 10036212,
          GUID = "191FE608",
          NextDialogue = 10036213,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Find a quiet, safe place... and take care of yourse—",
          TalkActionId = {
            [1] = "100327:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE608"
        },
        [10036213] = {
          Camera = "227.824219,31.842285,181.181152,0.000023,-16.404352,178.979095,45.0,100000.0,false,DoNotOverride,22",
          Content = "那你呢，你要怎么办？！",
          DialogueId = 10036213,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE632",
          NextDialogue = 10036214,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"189.578125,-871.764404,19.383301,-0.0,6.995186,93.378288,25.0,100000.0,false,DoNotOverride,22\"},duration{0}}",
          SpeakNpcId = 100304,
          Subtitle = "What about you!?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE632"
        },
        [10036214] = {
          Camera = "86.808594,-88.199707,320.100586,0.000018,-29.605869,33.985477,25.0,100000.0,false,Manual,22.0",
          Content = "我……",
          DialogueId = 10036214,
          FinalCamera = "4.820312,-143.472656,376.284668,0.000023,-32.005917,34.185921,25.0,100000.0,false,Manual,22.0",
          GUID = "191FE65C",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE65C"
        },
        [10036215] = {
          Content = "五天前，下水道出口",
          DialogueId = 10036215,
          GUID = "191FE686",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          Subtitle = "Five Days Ago, Sewer Exit",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE686"
        },
        [10036216] = {
          Content = "我还，以为，你会一直昏到，世界末日。",
          DialogueId = 10036216,
          GUID = "191FE6B0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036217,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SnapShot = "MEMORY",
          Subtitle = "I thought... you were going to... stay unconscious... until the end of the world.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE6B0"
        },
        [10036217] = {
          Content = "都怪我。如果我能早点赶来，你就不会被他们……",
          DialogueId = 10036217,
          GUID = "191FE6DA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036218,
          SnapShot = "MEMORY",
          Subtitle = "It's all my fault. If I'd got here sooner, you wouldn't have been...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE6DA"
        },
        [10036218] = {
          Content = "没机会，的。我能清醒的时间，在缩短。",
          DialogueId = 10036218,
          GUID = "191FE704",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036219,
          SnapShot = "MEMORY",
          Subtitle = "We wouldn't. We wouldn't have stood a chance. My moments of clarity... are slipping away.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE704"
        },
        [10036219] = {
          Content = "也可能是，如你所说，我的心，真的变成了……怪物。",
          DialogueId = 10036219,
          GUID = "191FE72E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036220,
          SnapShot = "MEMORY",
          Subtitle = "Or perhaps, like you said... my heart has already turned into... that of a monster.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE72E"
        },
        [10036220] = {
          Content = "你是怪物的话，那我又是什么呢？",
          DialogueId = 10036220,
          GUID = "191FE758",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036221,
          SnapShot = "MEMORY",
          Subtitle = "If you're a monster... then what does that make me?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE758"
        },
        [10036221] = {
          Content = "我们追逐的，那盏灯，原来这么耀眼，高不可及啊。",
          DialogueId = 10036221,
          GUID = "191FE782",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036222,
          SnapShot = "MEMORY",
          Subtitle = "We chased so hard to catch the light, the dazzling light... only to find it's so... unreachable in the end.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE782"
        },
        [10036222] = {
          Content = "高不可及的东西，让它坠落到地面来不就好了吗？",
          DialogueId = 10036222,
          GUID = "191FE7AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036223,
          Scripts = [[
SEQ
{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt03/0080_story_the_abandoned_theme"},RelatedRegionId{101103}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "If something is unreachable, why not pull it down to the ground?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE7AC"
        },
        [10036223] = {
          Content = "当心，<H>他身上有毒</>……你是谁！",
          DialogueId = 10036223,
          GUID = "191FE7D6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036224,
          SnapShot = "MEMORY",
          Subtitle = "Stay back — his body is toxic... Who are you?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE7D6"
        },
        [10036224] = {
          Content = "我有很多个名字，也有很多种身份，但这些说到底只是一个代号。而代号不管怎么变，我们这被神抛弃的本质都不会更改。",
          DialogueId = 10036224,
          GUID = "191FE800",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036225,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "I have many names, many faces. But in the end, they're all just labels. No matter how those labels shift or change, one truth remains — we have been forsaken by the gods.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE800"
        },
        [10036225] = {
          Content = "说到这里，聪明的你们应该知道我是谁了吧。",
          DialogueId = 10036225,
          GUID = "191FE82A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036226,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Now, someone as sharp as you should already know who I am.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE82A"
        },
        [10036226] = {
          Content = "我是来向你们发出一个邀请，加入我们，将那高不可及的索拉之民拖到地上，感受卡戎的怒火。",
          DialogueId = 10036226,
          GUID = "191FE854",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036227,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "I'm here to extend an invitation. Join us. Drag the untouchable Solas down to the ground, and let them feel the wrath of Charons.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE854"
        },
        [10036227] = {
          Content = "别急着拒绝。好好想想帝国对你们的所作所为吧！他们用美好的谎言欺骗你们，用残忍的刑罚折磨你们，用无尽的绝望笼罩你们。",
          DialogueId = 10036227,
          GUID = "191FE87E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036228,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Don't rush to reject me. Reflect on what the Empire has done to you. They lured you in with sweet lies, broke you with merciless torture, and buried you under an ocean of despair.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE87E"
        },
        [10036228] = {
          Content = "在这条路的尽头等你们的是什么？当上“桂冠卡戎”，过上更好的生活，实现更远的梦想？",
          DialogueId = 10036228,
          GUID = "191FE8A8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036229,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "And what lies at the end of this path? Becoming a Laurelled Charon? A better life? Greater dreams fulfilled?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8A8"
        },
        [10036229] = {
          Content = "不！是被索拉人敲骨吸髓，被同胞中的叛徒追捕，最后死在哪个不知名的角落。",
          DialogueId = 10036229,
          GUID = "191FE8D2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036230,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Absolutely not! What awaits is a slow death — your bones picked clean by the Sola elites, hunted by traitors among our own kind, until you're discarded like trash in some forgotten corner.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8D2"
        },
        [10036230] = {
          Content = "他们用一个简单的承诺，驱使如你，如我，如所有渴望出人头地的卡戎，一头扎进深渊。",
          DialogueId = 10036230,
          GUID = "191FE8FC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036231,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "With a single empty promise, they lure aspiring Charons like you and me straight into the abyss.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8FC"
        },
        [10036231] = {
          Content = "只要第六军团和炼金院的谎言不被戳破，就不断会有冰湖城的卡戎之民沿着军团这条路走下去，一个又一个，踏上和你们一样的悲剧。",
          DialogueId = 10036231,
          GUID = "191FE926",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036232,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "As long as the 6th Legion and the Alchemy Academy's web of lies remains intact, Charons of Icelake will continue walking this path to ruin, marching straight into the same tragedy as you... again and again.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE926"
        },
        [10036232] = {
          Content = "…………！",
          DialogueId = 10036232,
          GUID = "191FE950",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036233,
          SnapShot = "MEMORY",
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE950"
        },
        [10036233] = {
          Content = "我们被帝国夺走了过去，苟活在当下。未来我们也要这样毫无作为，让那群畜生碾碎我们所珍视的一切吗？",
          DialogueId = 10036233,
          GUID = "191FE97A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036234,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "The Empire stripped us of what we once had and left us trapped in this miserable present. Are we really going to let them crush everything we hold dear without putting up a fight?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE97A"
        },
        [10036234] = {
          Content = "看啊，看看现在的你我。帝国贪求我们的力量，为我们套上镣铐，把我们变成野兽，沦为真正的恶魔。",
          DialogueId = 10036234,
          GUID = "191FE9A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036235,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Look at us. The Empire coveted our strength, shackled us like animals, and twisted us into grotesque monsters — into real demons.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9A4"
        },
        [10036235] = {
          Content = "如今我们好不容易挣脱了枷锁，那不正是用帝国给予我们的这副獠牙，狠狠咬向他们咽喉的时刻吗！",
          DialogueId = 10036235,
          GUID = "191FE9CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036236,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "But now, we've broken free of those chains. Isn't it time to turn their own weapons against them? Time we made them pay?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9CE"
        },
        [10036236] = {
          Content = "让他们记住我们的存在，感受我们的痛苦，再也不敢觊觎我们珍视的东西！让他们用鲜血去忏悔，去铭记我们的存在，让整个帝国呼唤我们的名字！",
          DialogueId = 10036236,
          GUID = "191FE9F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036237,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Let them tremble at the mere thought of us. Let them feel the pain we've endured. Make them never dare to covet what we hold dear again! Let them repent with their blood and remember us for eternity. Let the entire Empire scream our names in terror!",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9F8"
        },
        [10036237] = {
          Content = "<W>神弃者同盟</>……",
          DialogueId = 10036237,
          GUID = "191FEA22",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036238,
          RelatedWikiId = {
            [1] = 101004
          },
          SnapShot = "MEMORY",
          Subtitle = "The Forsakens...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA22"
        },
        [10036238] = {
          Content = "你们可以把它理解成报复，但我更希望你们把它理解成保护，这是只有我们“恶魔”才能做到的责任——清理内城的“垃圾”，还你们的家人一个干净的未来。",
          DialogueId = 10036238,
          GUID = "191FEA4C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "You may call it vengeance, but I call it protection. We \"demons\" bear a duty to protect our kind. We'll rid the inner city of its \"filth\" and give your loved ones the cleaner, brighter future they deserve.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA4C"
        },
        [10036239] = {
          Camera = "145.113281,-134.397461,226.663574,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
          Content = "（神弃者同盟……）",
          DialogueId = 10036239,
          DisableMouth = 1,
          FinalCamera = "149.515625,-128.306641,226.455078,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
          GUID = "191FEA76",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)"
          },
          NextDialogue = 10036240,
          Scripts = [[
PARA{
SetRotation{SetRotationDescription{"100327:p(180)"}} ,
SetLocation{ActorId{200021},TargetPoint{"aoge_57"},Visibility{"Show"}}
}]],
          SnapShot = "HEART",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(The Forsakens...)",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA76"
        },
        [10036240] = {
          Camera = "419.355469,-129.479492,225.521484,-0.000548,-20.001587,145.330276,25.0,389.646332,false,Manual,2.8",
          Content = "我还有，未竟之事。",
          DialogueId = 10036240,
          FacialId = {
            [1] = "100304:Unacceptable01"
          },
          FinalCamera = "413.167969,-138.438477,274.373047,-0.000549,-20.001587,145.330292,25.0,389.646332,false,Manual,2.8",
          GUID = "191FEAA0",
          NextDialogue = 10036241,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I still have... unfinished business.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FEAA0"
        },
        [10036241] = {
          Content = "布鲁斯！",
          DialogueId = 10036241,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FEACA",
          NextDialogue = 10036242,
          Scripts = "MoveTo{ActorId{100327},TargetPoint{\"tuosi02_57_walk01\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100304,
          Subtitle = "Blues!",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FEACA"
        },
        [10036242] = {
          Camera = "1270.355469,72.632324,16.277832,-0.000549,15.796513,-175.065521,35.000011,100000.0,false,Manual,22.0",
          Content = "不要跟来。",
          DialogueId = 10036242,
          FinalCamera = "1270.355469,72.632324,16.277832,-0.000549,3.996487,-174.865509,35.000011,100000.0,false,Manual,22.0",
          GUID = "191FEAF4",
          Scripts = "MoveTo{ActorId{100327},TargetPoint{\"tuosi02_57_walk02\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Do not follow.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100362/191FEAF4"
        },
        [10036301] = {
          Content = "哇，看他看他，好酷的行头。",
          DialogueId = 10036301,
          Duration = 5,
          GUID = "191FF4A2",
          SpeakNpcId = 100366,
          Subtitle = "Whoa, check him out! That gear's absolutely wild.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4A2"
        },
        [10036302] = {
          Content = "这盔甲，这头套！哪里定做的，我也想要！",
          DialogueId = 10036302,
          Duration = 7,
          GUID = "191FF4CC",
          SpeakNpcId = 100368,
          Subtitle = "Seriously, where'd he get that? I've got to get one of those too!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4CC"
        },
        [10036303] = {
          Content = "哈哈哈哈你看那边，还有人装扮成神弃者和秽兽呢，不要命啦。",
          DialogueId = 10036303,
          Duration = 10,
          GUID = "191FF4F6",
          SpeakNpcId = 100367,
          Subtitle = "Hahaha, look at those guys over there — dressed as the Forsakens and Filthoids! They're insane!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4F6"
        },
        [10036304] = {
          Content = "怕什么，在这里我们没有身份，没有名字，没有种族！只有狂欢，彻夜狂欢！",
          DialogueId = 10036304,
          Duration = 12,
          GUID = "191FF520",
          SpeakNpcId = 100369,
          Subtitle = "Who cares? Here, we have no identities, no names, no races! Only masks, music, and revelry!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF520"
        },
        [10036305] = {
          Content = "（盖雷亚剧院，我回来了。）",
          DialogueId = 10036305,
          DisableMouth = 1,
          GUID = "191FF54A",
          NextDialogue = 10036306,
          SnapShot = "HEART",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(Galea Theatre. I'm back.)",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF54A"
        },
        [10036306] = {
          Content = "（只可惜是在这愚蠢的狂欢日……这群疯狂的家伙对这儿是一种玷污。）",
          DialogueId = 10036306,
          DisableMouth = 1,
          GUID = "191FF574",
          NextDialogue = 10036307,
          SnapShot = "HEART",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(Shame it's during this ridiculous celebration... Such cacophony of lunacy defiles the sanctity of this place.)",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF574"
        },
        [10036307] = {
          Content = "（……现在不是思考这个的时候。去和同盟的那家伙碰面吧。）",
          DialogueId = 10036307,
          DisableMouth = 1,
          GUID = "191FF59E",
          SnapShot = "HEART",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(...Focus. Now isn't the time for sentimentality. I need to meet with the Forsakens' contact.)",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF59E"
        },
        [10036308] = {
          Camera = "64.748032,73.186905,141.25,0.000034,-0.801086,-95.817291,35.000008,100000.0,false,Manual,22.0",
          Content = "居然叫我来这种地方，你还有这般雅兴。",
          DialogueId = 10036308,
          FinalCamera = "59.996071,26.498751,140.589844,0.000034,-0.801086,-95.817314,35.000008,100000.0,false,Manual,22.0",
          GUID = "191FF5C8",
          NextDialogue = 10036309,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101901}}",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Can't believe you chose to meet in a place like this. Never took you for someone who enjoys such frivolities.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF5C8"
        },
        [10036309] = {
          Camera = "47.290932,-282.748688,98.773438,0.000223,12.987468,99.416245,20.0,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我不是说过如无必要减少碰面吗？现在十三军团也撤走了，我们得尽快完成此前的约定才是。",
          DialogueId = 10036309,
          FinalCamera = "153.951035,-298.556122,92.078125,-2.0,9.185791,119.818588,20.0,100000.0,false,Manual,22.0",
          GUID = "191FF5F2",
          NextDialogue = 10036310,
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "And didn't I tell you to minimise contact unless absolutely necessary? The 13th Legion is gone. We've got to finish our deal ASAP.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF5F2"
        },
        [10036310] = {
          Camera = "48.10738,-52.516705,168.945312,0.00015,15.595841,97.983627,35.000008,100000.0,false,Manual,22.0",
          Content = "没错，可以完成，约定了。",
          DialogueId = 10036310,
          GUID = "191FF61C",
          NextDialogue = 10036311,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Yes. It can be... finished now. As we... agreed.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF61C"
        },
        [10036311] = {
          Camera = "59.996071,26.498751,140.589844,0.000034,-0.801086,-95.817314,35.000008,100000.0,false,Manual,22.0",
          Content = "…………？！",
          DialogueId = 10036311,
          GUID = "191FF646",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF646"
        },
        [10036312] = {
          Content = "你……怎么……唔……呃——！",
          DialogueId = 10036312,
          GUID = "191FF670",
          NextDialogue = 10036313,
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "What are you... why... Urgh... Agh!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF670"
        },
        [10036313] = {
          Content = "协助你，借此引来，十三军团，目的，达到。",
          DialogueId = 10036313,
          GUID = "191FF69A",
          NextDialogue = 10036314,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I only... cooperated with you... to draw out... the 13th Legion. Now... it's done.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF69A"
        },
        [10036314] = {
          Content = "但十三军团，拒绝，揭露真相。",
          DialogueId = 10036314,
          GUID = "191FF6C4",
          NextDialogue = 10036315,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But the 13th Legion... refused to expose the truth.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF6C4"
        },
        [10036315] = {
          Content = "那么你，就没有，利用价值。",
          DialogueId = 10036315,
          GUID = "191FF6EE",
          NextDialogue = 10036316,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "So now, you've outlived... your usefulness.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF6EE"
        },
        [10036316] = {
          Content = "神弃者，也是，祸患。",
          DialogueId = 10036316,
          GUID = "191FF718",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The Forsakens... are just another... plague to cleanse.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF718"
        },
        [10036317] = {
          Content = "酷啊！这次的演出比往年还逼真！",
          DialogueId = 10036317,
          GUID = "191FF742",
          NextDialogue = 10036318,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Awesome! This year's show is on a whole new level — it looks so real!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF742"
        },
        [10036318] = {
          Content = "喂，怎么还有人装扮成军团士兵的模样啊？看手里那家伙，跟真的一样啊！",
          DialogueId = 10036318,
          GUID = "191FF76C",
          NextDialogue = 10036319,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Check that out! Someone's really gone all in with that soldier costume. That gear... it looks legit!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF76C"
        },
        [10036319] = {
          Content = "他们是在演什么战争戏吗？打起来，打起来！",
          DialogueId = 10036319,
          GUID = "191FF796",
          NextDialogue = 10036320,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Is this a war-themed play or what? Come on, let's see some action already!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF796"
        },
        [10036320] = {
          Content = "…………",
          DialogueId = 10036320,
          GUID = "191FF7C0",
          NextDialogue = 10036321,
          SpeakNpcId = 100310,
          SpeakNpcName = "Cp2CharacterName25",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF7C0"
        },
        [10036321] = {
          Content = "我*，这枪声，演得太真了吧！",
          DialogueId = 10036321,
          GUID = "191FF7EA",
          NextDialogue = 10036322,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Holy s***! Did you hear that? Man, the sound effects are spot on!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF7EA"
        },
        [10036322] = {
          Content = "哥们，好样的！再来一个！",
          DialogueId = 10036322,
          GUID = "191FF814",
          NextDialogue = 10036323,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Bravo! Let's hear it again!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF814"
        },
        [10036323] = {
          Content = "唉……",
          DialogueId = 10036323,
          GUID = "191FF83E",
          NextDialogue = 10036324,
          SpeakNpcId = 100310,
          SpeakNpcName = "Cp2CharacterName25",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF83E"
        },
        [10036324] = {
          Content = "第十三军团执行公务，枪弹无眼，再不滚就死！",
          DialogueId = 10036324,
          GUID = "191FF868",
          NextDialogue = 10036325,
          SpeakNpcId = 100310,
          SpeakNpcName = "Cp2CharacterName25",
          Subtitle = "The 13th Legion is on official business. Live ammunition. Move it, or you'll die.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF868"
        },
        [10036325] = {
          Content = "等、等下……是真家伙？！",
          DialogueId = 10036325,
          GUID = "191FF892",
          NextDialogue = 10036326,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Wait — what? Are those real guns?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF892"
        },
        [10036326] = {
          Content = "是军团，真的军团！！",
          DialogueId = 10036326,
          GUID = "191FF8BC",
          NextDialogue = 10036327,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "It's the Legion... it's actually the Legion!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF8BC"
        },
        [10036327] = {
          Content = "阿诺德、托马斯、疏散群众！",
          DialogueId = 10036327,
          GUID = "191FF8E6",
          NextDialogue = 10036328,
          SpeakNpcId = 100310,
          SpeakNpcName = "Cp2CharacterName25",
          Subtitle = "Arnold, Thomas, evacuate the civilians!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF8E6"
        },
        [10036328] = {
          Content = "其他人，继续压制。",
          DialogueId = 10036328,
          GUID = "191FF910",
          SpeakNpcId = 100310,
          SpeakNpcName = "Cp2CharacterName25",
          Subtitle = "The rest of you, hold suppression!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF910"
        },
        [10036329] = {
          Camera = "121.195312,-974.079346,173.230469,-15.056557,1.40581,111.026299,20.0,348.470978,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "狂欢现场发现目标。初步判定为神弃者同盟“渡鸦”。在场的市民已经驱离，抓捕行动进展顺利。",
          DialogueId = 10036329,
          FinalCamera = "160.929688,-958.805359,173.886719,-15.056557,1.40581,111.026299,20.0,100000.0,false,Manual,2.8",
          GUID = "191FF93A",
          NextDialogue = 10036330,
          RelatedWikiId = {
            [1] = 101004
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4},TargetPosition{"113.824219,12.355896,129.007812,-15.085212,8.603217,125.227028,20.0,100000.0,false,Manual,22.0"},duration{0}},   
CameraMoveTo{_delay{0},TargetPosition{"111.667969,10.832886,137.609375,-15.085212,8.603217,125.227028,20.0,100000.0,false,Manual,22.0"},duration{4}}
}]],
          SpeakNpcId = 100310,
          Subtitle = "Target confirmed at the masquerade. Preliminary assessment identifies the target as \"The Raven\" from the Forsakens. Civilians have been cleared. Apprehension proceeding as planned.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF93A"
        },
        [10036330] = {
          Camera = "83.970703,135.913513,189.65625,-15.112432,-9.397861,141.623428,15.0,175.398438,false,Manual,2.8",
          Content = "……好……其他人也……向盖雷亚剧院集合……",
          DialogueId = 10036330,
          GUID = "191FF964",
          NextDialogue = 10036331,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 200022,
          Subtitle = "Well done... regroup... all units... to Galea Theatre...",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF964"
        },
        [10036331] = {
          Camera = "303.613281,-279.919189,8.132812,0.000071,9.59102,112.143921,25.0,668.989929,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "队长，我们还在尽力抢救，但这同盟的家伙快不行了！二号目标怎么办？",
          DialogueId = 10036331,
          FinalCamera = "269.648438,-293.739441,8.132812,0.000071,9.59102,112.143982,25.0,668.989929,false,Manual,3.0",
          GUID = "191FF98E",
          LookAt = {
            [1] = "100340:n(100310)",
            [2] = "100310:n(100340)"
          },
          NextDialogue = 10036332,
          Scripts = "SetLocation{ActorId{100342},TargetPoint{\"Point2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 100340,
          Subtitle = "Captain, we're doing everything we can to stabilise the targets, but this Forsakens bastard isn't going to make it! What about Target No. 2?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF98E"
        },
        [10036332] = {
          Camera = "4.361328,31.762268,100.789062,0.000065,25.399736,88.416191,35.000011,169.259979,false,Manual,2.8",
          Content = "直接击毙。",
          DialogueId = 10036332,
          FinalCamera = "4.966797,64.343872,117.113281,0.00006,27.199732,89.016098,35.000011,169.259979,false,Manual,2.8",
          GUID = "191FF9B8",
          LookAt = {
            [1] = "100310:n(100310)"
          },
          SpeakNpcId = 100310,
          Subtitle = "Terminate on sight.",
          TalkActionId = {
            [1] = "100310:Angry01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF9B8"
        },
        [10036333] = {DialogueId = 10036333, GUID = "191FF719"},
        [10036334] = {
          Content = "帅家伙，等会要跟我跳支舞吗？",
          DialogueId = 10036334,
          Duration = 5,
          GUID = "191FF521",
          Subtitle = "Hey, handsome — care for a dance later?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF521"
        },
        [10036335] = {
          Content = "嘿，我这枪看着很真吧，还能打出软弹呢，厉不厉害！",
          DialogueId = 10036335,
          Duration = 8,
          GUID = "191FF522",
          Subtitle = "Check out my gun — looks like the real deal, right? It even fires foam rounds — how cool is that?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF522"
        },
        [10036336] = {
          Content = "我，我没醉！你们看，我，我还能在地上滚个舞步呢。",
          DialogueId = 10036336,
          Duration = 8,
          GUID = "191FF523",
          Subtitle = "Who says I'm drunk? Watch this — I can still pull off a proper spin on the floor!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF523"
        },
        [10036337] = {
          Content = "今年怎么没人打扮成水蠊了啊，我还蛮期待的。",
          DialogueId = 10036337,
          Duration = 7,
          GUID = "191FF524",
          Subtitle = "Wait, no one came dressed as an Aquaroach this year? Aww, I was sort of looking forward to that.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF524"
        },
        [10036338] = {
          Content = "嗷嗷嗷嗷，我是秽兽，嗷嗷嗷嗷，咬你。",
          DialogueId = 10036338,
          Duration = 6,
          GUID = "191FF525",
          Subtitle = "Raargh! I'm a Filthoid! Raaaargh! I'll chomp your toes!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF525"
        },
        [10036339] = {
          Content = "别踩我，我在扮演尸体。",
          DialogueId = 10036339,
          Duration = 4,
          GUID = "191FF526",
          Subtitle = "Mind your step — I'm playing the corpse.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF526"
        },
        [10036340] = {
          Content = "这位舞伴是我先邀请的，你什么意思，想打架是吧？",
          DialogueId = 10036340,
          Duration = 8,
          GUID = "191FF527",
          Subtitle = "Hey! I asked her first! What, looking for a scrap?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF527"
        },
        [10036341] = {
          Content = "剧院禁止斗殴，就算是银烛狂欢期间也不行！",
          DialogueId = 10036341,
          Duration = 7,
          GUID = "191FF528",
          Subtitle = "No fighting in the theatre! Carnival or not — the rules still stand!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF528"
        },
        [10036342] = {
          Content = "好强壮的身材！能让我摸摸你的腹肌吗？",
          DialogueId = 10036342,
          Duration = 6,
          GUID = "191FF529",
          Subtitle = "Whoa, you're ripped! Mind if I cop a feel?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF529"
        },
        [10036343] = {
          Content = "刚才的演出太精彩了，有人能帮我把这封信递给优雅的主演小姐吗？",
          DialogueId = 10036343,
          Duration = 10,
          GUID = "191FF52A",
          Subtitle = "That show was brilliant... Could someone pass this letter to the lovely lead for me?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52A"
        },
        [10036344] = {
          Content = "跳得好！",
          DialogueId = 10036344,
          Duration = 2,
          GUID = "191FF52B",
          Subtitle = "That was a great dance!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52B"
        },
        [10036345] = {
          Content = "我这个秽兽气球怎么样，很逼真吧。",
          DialogueId = 10036345,
          Duration = 6,
          GUID = "191FF52C",
          Subtitle = "How is my Filthoid balloon? Life-like, isn't it?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52C"
        },
        [10036346] = {
          Content = "这才几点啊，起来继续！今晚统统都别想睡，哈哈哈哈哈哈！",
          DialogueId = 10036346,
          Duration = 9,
          GUID = "191FF52D",
          Subtitle = "The night is still young! Come on, get up and dance through the night! Hahahahahaha!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52D"
        },
        [10036401] = {
          Content = "什么人！",
          DialogueId = 10036401,
          GUID = "1920050A",
          SpeakNpcId = 100310,
          Subtitle = "Who is it!?",
          VoiceName = "voice/$Locale$/story/1003/100364/1920050A"
        },
        [10036402] = {
          Content = "上。",
          DialogueId = 10036402,
          GUID = "19200534",
          SpeakNpcId = 100310,
          Subtitle = "Get him!"
        },
        [10036501] = {
          Camera = "239.951172,-477.602203,105.097656,0.000085,9.599236,-122.180763,15.000005,100000.0,false,Manual,22.0",
          Content = "各位，请先住手！我们可以谈谈！",
          DialogueId = 10036501,
          FacialId = {
            [1] = "100001:Shock02",
            [2] = "200021:Angry01"
          },
          FinalCamera = "239.951172,-477.602203,105.097656,0.00009,9.599236,-130.180237,15.000005,100000.0,false,Manual,22.0",
          GUID = "19201572",
          NextDialogue = 10036502,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},TargetPoint{"nvzhu_arrival"},MoveSpeed{80},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"1514.865234,-857.240051,886.300781,-15.021118,-27.993761,156.82373,20.0,100000.0,false,Manual,1.2"},duration{0}},   
CameraMoveTo{_delay{0},TargetPosition{"1524.769531,-861.478943,892.085938,-15.021085,-28.193769,156.82373,20.0,100000.0,false,Manual,1.2"},duration{5}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Everyone, lower your weapons! Let's talk this through!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201572"
        },
        [10036502] = {
          Camera = "69.597656,314.252319,160.503906,0.000118,-1.602963,-101.987617,25.0,100000.0,false,Manual,22.0",
          Content = "克莱夫长官，不要开枪！这件事还有隐情！",
          DialogueId = 10036502,
          FacialId = {
            [1] = "100304:Shock02"
          },
          FinalCamera = "63.892578,287.364624,159.746094,0.000118,-1.602963,-101.987617,25.0,100000.0,false,Manual,22.0",
          GUID = "1920159C",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)",
            [4] = "100327:n(100304)"
          },
          NextDialogue = 10036503,
          SpeakNpcId = 100304,
          Subtitle = "Officer Clive, hold your fire! It's not what it seems!",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "100304:Lise_Story_Protect_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/1920159C"
        },
        [10036503] = {
          Camera = "106.291016,-60.851074,45.765625,14.408816,17.79439,114.413322,25.0,100000.0,false,Manual,22.0",
          Content = "费西尔准尉、狩月人？你们这是在——包庇那怪物、“卡戎狩猎”的凶手？！",
          DialogueId = 10036503,
          FinalCamera = "106.291016,-60.851048,45.765625,14.408128,21.19454,114.414146,25.0,100000.0,false,Manual,22.0",
          GUID = "192015C6",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036504,
          SpeakNpcId = 100310,
          Subtitle = "Warrant Officer Fischer and the Phoxhunters? Are you... shielding that monster — the \"Charon Hunt\" perpetrator?",
          TalkActionId = {
            [1] = "100310:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/192015C6"
        },
        [10036504] = {
          Camera = "352.181641,-1420.943481,295.125,10.817314,-10.006131,108.659332,25.0,100000.0,false,Manual,22.0",
          Content = "你们也和先前那群人一样，被愚蠢的狂欢冲烂了脑子？",
          DialogueId = 10036504,
          FinalCamera = "315.181641,-1309.563599,274.621094,10.818109,-9.806095,108.059586,25.0,100000.0,false,Manual,22.0",
          GUID = "192015F0",
          NextDialogue = 10036505,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 100310,
          Subtitle = "Have you lost your minds like the idiots prancing around at the carnival?",
          TalkActionId = {
            [1] = "100304:Lise_Story_Protect_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/192015F0"
        },
        [10036505] = {
          Camera = "67.845703,-302.296021,112.21875,0.00005,11.194864,-117.729912,35.0,100000.0,false,Manual,22.0",
          Content = "……凶手的身份和动机还未确认，直接击毙无法向冰湖城的受害者交代！",
          DialogueId = 10036505,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "87.982422,-255.8255,86.699219,0.000067,11.194679,-117.325897,35.000008,100000.0,false,Manual,22.0",
          GUID = "1920161A",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)",
            [4] = "100327:n(100304)"
          },
          NextDialogue = 10036506,
          SpeakNpcId = 100304,
          Subtitle = "...The killer's identity and motive remain unconfirmed. Executing him now will not serve justice for the victims of Icelake!",
          TalkActionId = {
            [1] = "100304:Lise_Story_Denny_Start"
          },
          ToFinalCameraBlendTime = 0.6,
          VoiceName = "voice/$Locale$/story/1003/100365/1920161A"
        },
        [10036506] = {
          Camera = "58.804688,311.518188,10.246094,0.000066,8.195646,-99.136841,25.0,100000.0,false,Manual,22.0",
          Content = "击毙就是最好的交代，你不是应该出现在这个舞台上的演员。守好规矩，退后！",
          DialogueId = 10036506,
          FinalCamera = "54.523438,283.006348,14.398438,0.000068,8.195646,-98.136887,20.0,100000.0,false,Manual,22.0",
          GUID = "19201644",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036507,
          SpeakNpcId = 100310,
          Subtitle = "Justice? Justice is putting a bullet in its skull. You're out of line here, Fischer. Stand down.",
          TalkActionId = {
            [1] = "100304:Lise_Story_Denny_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201644"
        },
        [10036507] = {
          Camera = "67.845703,-302.296021,112.21875,0.00005,11.194864,-117.729912,35.0,100000.0,false,Manual,22.0",
          Content = "…………",
          DialogueId = 10036507,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          GUID = "1920166E",
          LookAt = {
            [1] = "100304:p(lise_ditou)"
          },
          NextDialogue = 10036508,
          SpeakNpcId = 100304,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100365/1920166E"
        },
        [10036508] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          Content = "你还记得你加入军团那天，在三头狼旗下发过的誓言吗？“将此生奉献给皇帝陛下，成为海伯利亚的忠诚战士，至死方休。”",
          DialogueId = 10036508,
          FinalCamera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          GUID = "19201698",
          LookAt = {
            [1] = "100304:n(100310)"
          },
          NextDialogue = 10036509,
          SpeakNpcId = 100310,
          Subtitle = "Do you remember the oath you swore under the banner of the Three Wolves? \"To dedicate my life to His Majesty, to become a loyal soldier of Hyperborea, and to serve until death.\"",
          TalkActionId = {
            [1] = "100310:Angry01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201698"
        },
        [10036509] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          Content = "琳恩长官说过，你虽是卡戎之民，却是难得的人才。她本打算在案子结束后提携你去皇都。",
          DialogueId = 10036509,
          GUID = "192016C2",
          NextDialogue = 10036510,
          SpeakNpcId = 100310,
          Subtitle = "Major Lynn spoke highly of you — she considered you a very promising soldier, despite your Charon bloodline. She was even planning to recommend you for promotion to the capital once this case was resolved.",
          VoiceName = "voice/$Locale$/story/1003/100365/192016C2"
        },
        [10036510] = {
          Camera = "53.857422,378.744141,188.148438,0.000066,-9.20508,-99.947792,20.0,100000.0,false,Manual,22.0",
          Content = "十三军团一向惜才，我再给你最后一次证明自己是海伯利亚忠诚战士的机会。给我让开。",
          DialogueId = 10036510,
          FinalCamera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          GUID = "192016EC",
          NextDialogue = 10036511,
          SpeakNpcId = 100310,
          Subtitle = "The 13th Legion values its ace soldiers. I'm giving you one last chance to prove your loyalty to Hyperborea. Step aside.",
          TalkActionId = {
            [1] = "100310:Angry01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/192016EC"
        },
        [10036511] = {
          Camera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          Content = "……不。",
          DialogueId = 10036511,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          GUID = "19201716",
          LookAt = {
            [1] = "100304:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)"
          },
          NextDialogue = 10036512,
          SpeakNpcId = 100304,
          Subtitle = "...No.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201716"
        },
        [10036512] = {
          Camera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          Content = "你敢违抗军令？！",
          DialogueId = 10036512,
          GUID = "19201740",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036513,
          SpeakNpcId = 100310,
          Subtitle = "You dare defy a direct order!?",
          TalkActionId = {
            [1] = "100310:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201740"
        },
        [10036513] = {
          Camera = "144.183594,-290.747986,325.367188,14.401219,-44.003242,-130.524872,35.0,100000.0,false,Manual,22.0",
          Content = "我从小到大一直脑子笨，想不通很多事情。究竟怎么做才能称得上“海伯利亚的忠诚战士”，其实我到现在也没能想太明白。",
          DialogueId = 10036513,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "126.980469,-310.735382,299.902344,14.401626,-44.003242,-130.724792,35.0,100000.0,false,Manual,22.0",
          GUID = "1920176A",
          LookAt = {
            [1] = "100304:p(lise_ditou)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)",
            [4] = "100327:n(100304)"
          },
          NextDialogue = 10036514,
          SpeakNpcId = 100304,
          Subtitle = "I've always been a slow thinker — never good at understanding complicated ideas. Even now, I still don't know what it means to be a \"loyal soldier of Hyperborea.\"",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/1920176A"
        },
        [10036514] = {
          Camera = "126.980469,-310.735382,299.902344,14.401626,-44.003242,-130.724792,35.0,100000.0,false,Manual,22.0",
          Content = "但我只知道一件事——如果忠于海伯利亚、忠于皇帝陛下，要以践踏这座我生长的城市、践踏帮助过我的人、践踏与我相依为命的骨肉至亲为代价……",
          DialogueId = 10036514,
          FacialId = {
            [1] = "100304:Angry01"
          },
          GUID = "19201794",
          NextDialogue = 10036515,
          SpeakNpcId = 100304,
          Subtitle = "But there's one thing I know for sure: if loyalty to Hyperborea, to His Majesty, means trampling the place where I was born and raised, betraying those who've helped me, and turning my back on my loved ones...",
          VoiceName = "voice/$Locale$/story/1003/100365/19201794"
        },
        [10036515] = {
          Camera = "46.298828,-302.022705,104.398438,0.000043,12.393856,-107.324394,35.000008,100000.0,false,Manual,4.0",
          Content = "从此刻起，黎瑟·费西尔将不再是海伯利亚忠诚的战士！",
          DialogueId = 10036515,
          FacialId = {
            [1] = "100304:Grief"
          },
          FinalCamera = "78.177734,-200.148499,80.761719,0.000044,11.993859,-107.12439,35.000008,100000.0,false,Manual,22.0",
          GUID = "192017BE",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036516,
          SpeakNpcId = 100304,
          Subtitle = "Then from this very moment on, Rhythm Fischer is no longer a loyal soldier of Hyperborea!",
          TalkActionId = {
            [1] = "100304:Lise_Story_Aim_Start"
          },
          ToFinalCameraBlendTime = 0.6,
          VoiceName = "voice/$Locale$/story/1003/100365/192017BE"
        },
        [10036516] = {
          Camera = "438.205078,-272.948975,145.40625,0.000054,0.193151,156.073257,50.0,100000.0,false,Manual,22.0",
          Content = "违抗军纪，阻碍其他军团执行任务，依照帝国军律，同样就地击毙。",
          DialogueId = 10036516,
          FinalCamera = "532.177734,-60.53857,145.40625,0.000054,0.193151,155.673569,50.0,100000.0,false,Manual,22.0",
          GUID = "192017E8",
          NextDialogue = 10036517,
          Scripts = [[
SEQ{
