          VoiceName = "voice/$Locale$/story/1003/100365/19201BD8"
        },
        [10036541] = {
          Camera = "163.320312,-784.116699,255.972656,0.000098,-19.430269,172.310211,35.000015,474.33847,false,Manual,4.0",
          Content = "逃跑，是，没有尽头的。",
          DialogueId = 10036541,
          FinalCamera = "163.320312,-784.116699,255.972656,0.000105,-19.63027,174.310043,35.000015,157.028549,false,Manual,4.0",
          GUID = "19201C02",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036542,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "There's no end... to running.",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1003/100365/19201C02"
        },
        [10036542] = {
          Camera = "125.720703,-677.143311,182.6875,0.000139,-19.423855,39.110752,30.000008,100000.0,false,Manual,22.0",
          Content = "那就一直逃下去。只要人活着，就一定能找到出路。",
          DialogueId = 10036542,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "19201C2C",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)",
            [4] = "100327:n(100327)"
          },
          NextDialogue = 10036587,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Then keep running. As long as you're alive, there's always a way.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201C2C"
        },
        [10036543] = {
          Camera = "21.552734,-1753.842163,6.808594,0.000086,-2.626064,89.10537,35.000015,100000.0,false,Manual,22.0",
          Content = "走，吧，你是个，好人。和他，一样。",
          DialogueId = 10036543,
          FinalCamera = "21.552734,-1753.842163,6.808594,0.000088,7.573928,88.905312,35.000015,100000.0,false,Manual,22.0",
          GUID = "19201C56",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036544,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Leave. You're a good person. Just like him.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201C56"
        },
        [10036544] = {
          Camera = "419.052734,-634.423706,131.730469,0.00007,1.174369,175.702454,35.000011,100000.0,false,Manual,22.0",
          Content = "<H>他</>？",
          DialogueId = 10036544,
          GUID = "19201C80",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036545,
          SpeakNpcId = 100001,
          Subtitle = "Him?",
          TalkActionId = {
            [1] = "100001:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201C80"
        },
        [10036545] = {
          Camera = "419.052734,-634.423706,131.730469,0.00007,1.174369,175.702454,35.000011,100000.0,false,Manual,22.0",
          Content = "答应吧。布鲁斯已经做好了抉择。",
          DialogueId = 10036545,
          GUID = "19201CAA",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "200021:n(100001)"
          },
          NextDialogue = 10036546,
          SpeakNpcId = 200021,
          Subtitle = "Let's accept his request, Captain. Blues has already made his choice.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201CAA"
        },
        [10036546] = {
          Camera = "88.587891,-658.653198,139.449219,0.000054,0.981286,25.660429,35.0,100000.0,false,DoNotOverride,22",
          Content = "…………",
          DialogueId = 10036546,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19201CD4",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10036547,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201CD4"
        },
        [10036547] = {
          Camera = "121.087891,-627.140564,90.980469,0.000064,36.379902,-115.518616,35.000015,238.912354,false,Manual,2.8",
          Content = "“无言的白雪啊……苍穹的女儿……为那无名的孩子……献上祈祷吧……”",
          DialogueId = 10036547,
          FinalCamera = "112.048828,-646.135132,106.285156,0.000063,35.7798,-115.31826,35.000015,238.912354,false,Manual,2.8",
          GUID = "19201CFE",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100304)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036548,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "\"The silent silent snow, child of the sky... May the nameless child... be bathed in pure light...\"",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201CFE"
        },
        [10036548] = {
          Camera = "58.166016,-773.346558,173.808594,0.000121,-10.21771,38.108284,35.000015,238.912354,false,Manual,6.0",
          Content = "但是……",
          DialogueId = 10036548,
          GUID = "19201D28",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10036549,
          SpeakNpcId = 100001,
          Subtitle = "But...",
          VoiceName = "voice/$Locale$/story/1003/100365/19201D28"
        },
        [10036549] = {
          Camera = "58.166016,-773.346558,173.808594,0.000121,-10.21771,38.108284,35.000015,238.912354,false,Manual,6.0",
          Content = "“他已深眠于……冻土之下……”",
          DialogueId = 10036549,
          GUID = "19201D52",
          LookAt = {
            [1] = "100001:n(100327)"
          },
          NextDialogue = 10036582,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "\"The crystal heart will... keep shining through...\"",
          VoiceName = "voice/$Locale$/story/1003/100365/19201D52"
        },
        [10036550] = {
          Camera = "437.072266,-484.677155,91.523438,-6.000038,7.375101,-149.496567,22.0,100000.0,false,Manual,22.0",
          Content = "……我们接受你的委托，但，有一个前提。",
          DialogueId = 10036550,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "412.84375,-498.953125,95.148438,-6.000038,7.375101,-149.496567,22.0,100000.0,false,Manual,22.0",
          GUID = "19201D7C",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036551,
          SpeakNpcId = 100001,
          Subtitle = "...We accept your request, but on one condition.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201D7C"
        },
        [10036551] = {
          Camera = "231.177734,-578.526001,131.269531,-6.00004,16.766598,-130.071335,35.000008,315.044647,false,Manual,4.0",
          Content = "无名的朋友，<H>真正的47号</>，与布鲁斯·费西尔一起逃出炼金院的<H>同伴</>……",
          DialogueId = 10036551,
          GUID = "19201DA6",
          NextDialogue = 10036552,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0081_scene_alchemyacademy\"},RelatedRegionId{101901}}",
          SpeakNpcId = 100001,
          Subtitle = "My nameless friend... the true Subject 47, the companion who escaped the academy alongside Blues Fischer...",
          VoiceName = "voice/$Locale$/story/1003/100365/19201DA6"
        },
        [10036552] = {
          Camera = "-19.820312,-800.355225,266.109375,-6.000041,-22.222614,37.869591,80.000008,336.546021,false,Manual,8.0",
          Content = "<H>告诉我，你真实的名字。请用那个名字委托我。</>",
          DialogueId = 10036552,
          GUID = "19201DD0",
          NextDialogue = 10036553,
          SpeakNpcId = 100001,
          Subtitle = "Tell me your real name. Make this request in your true name.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201DD0"
        },
        [10036553] = {
          Camera = "258.386719,-506.575806,104.496094,0.000145,16.772669,-121.30761,35.000011,327.03125,false,Manual,2.799999",
          Content = "……呵……",
          DialogueId = 10036553,
          GUID = "19201DFA",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036554,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "...Heh...",
          VoiceName = "voice/$Locale$/story/1003/100365/19201DFA"
        },
        [10036554] = {
          Camera = "258.386719,-506.575806,104.496094,0.000145,16.772669,-121.30761,35.000011,327.03125,false,Manual,2.799999",
          Content = "……什么时候，猜到的？",
          DialogueId = 10036554,
          GUID = "19201E24",
          NextDialogue = 10036555,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "How long... have you known?",
          VoiceName = "voice/$Locale$/story/1003/100365/19201E24"
        },
        [10036555] = {
          Camera = "258.386719,-506.575806,104.496094,0.000145,16.772669,-121.30761,35.000011,327.03125,false,Manual,2.799999",
          Content = "你刚才唱那首歌的时候……或者更早。",
          DialogueId = 10036555,
          GUID = "19201E4E",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036556,
          SpeakNpcId = 100001,
          Subtitle = "When you sang that song... or maybe even earlier.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201E4E"
        },
        [10036556] = {
          Camera = "67.970703,-683.014221,202.332031,0.000099,-17.213497,28.039291,35.0,100000.0,false,Manual,22.0",
          Content = "“……无言的白雪啊，苍穹的女儿……为那无名的孩子献上祝福……他和雪花跳起轻快的舞……”",
          DialogueId = 10036556,
          FinalCamera = "67.970703,-683.014221,202.332031,0.000094,-19.413378,27.838545,35.000008,100000.0,false,Manual,22.0",
          GUID = "19201E78",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036556.T_Story_Recall_10036556'",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036557,
          SnapShot = "MEMORY",
          SpeakNpcId = 100304,
          Subtitle = "\"The silent silent snow, child of the sky... May the nameless child be bathed in good time... Dancing with snowflakes, so light, so great...\"",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100365/19201E78"
        },
        [10036557] = {
          Camera = "129.630859,-634.838989,126.636719,0.000079,7.986567,19.837446,35.000011,100000.0,false,DoNotOverride,22",
          Content = "黎瑟说过，布鲁斯不喜欢那首歌的歌词，所以自作主张把词改掉了，改成了一个幸福的结局。而你唱的“深眠于冻土之下”，应该是原本的悲伤结局吧。",
          DialogueId = 10036557,
          GUID = "19201EA2",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036558,
          SpeakNpcId = 100001,
          Subtitle = "Rhythm told us Blues didn't like the original lyrics. He rewrote them to give the song a happy ending. But what you sang is different — that's the original, sorrowful version, isn't it?",
          VoiceName = "voice/$Locale$/story/1003/100365/19201EA2"
        },
        [10036558] = {
          Camera = "-53.980469,-733.359253,143.015625,0.000226,5.980021,155.884628,35.000011,160.454437,false,Manual,4.0",
          Content = "…………！！",
          DialogueId = 10036558,
          FacialId = {
            [1] = "200021:Shock01"
          },
          GUID = "19201ECC",
          LookAt = {
            [1] = "200021:n(100327)"
          },
          NextDialogue = 10036559,
          SpeakNpcId = 200021,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1003/100365/19201ECC"
        },
        [10036559] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "如果你不是布鲁斯，熟知炼金院那些往事的……就只能是故事里的另一个改造体。",
          DialogueId = 10036559,
          GUID = "19201EF6",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036560,
          SpeakNpcId = 100001,
          Subtitle = "You're not Blues, yet you know everything about what happened in the academy... Then you must be the other protagonist of the story.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201EF6"
        },
        [10036560] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "此前我也一直想不通，我们大家看到的凶手明明丧失了理智，但你为什么如此冷静？冷静到可以清晰地和我们讲述那么多往事？",
          DialogueId = 10036560,
          GUID = "19201F20",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036560.T_Story_Recall_10036560'",
          NextDialogue = 10036561,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "It didn't make sense to me before. The culprit everyone described was a rabid beast. But you're nothing like that. You were calm enough to recount your past with such precision and clarity.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201F20"
        },
        [10036561] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "会不会，你并不是那个犯下“卡戎狩猎”的家伙，只是在扮演它？……不过，这些都是猜的。但你的反应证明……我猜中了。",
          DialogueId = 10036561,
          GUID = "19201F4A",
          NextDialogue = 10036562,
          SpeakNpcId = 100001,
          Subtitle = "So, could it be... you're not the one who committed the \"Charon Hunt\"? Perhaps you've just been playing that role? It was just a guess, but... your reaction tells me I'm right.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201F4A"
        },
        [10036562] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "你擅长表演，可以模仿布鲁斯的一举一动。你精湛的演技甚至骗过了黎瑟，布鲁斯唯一的亲人。",
          DialogueId = 10036562,
          GUID = "19201F74",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036562.T_Story_Recall_10036562'",
          NextDialogue = 10036563,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "You're such a talented performer. You managed to mimic Blues's every gesture so perfectly that even Rhythm bought it.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201F74"
        },
        [10036563] = {
          Camera = "166.142578,-735.137329,169.679688,0.000134,24.978464,-163.348846,35.000008,100000.0,false,Manual,22.0",
          Content = "你喉咙上那道<H>新伤</>，也是故意的吧……你割破喉咙，毁掉了自己的嗓音，是因为你知道，那个声音是无法完全模仿的……",
          DialogueId = 10036563,
          FinalCamera = "142.306641,-742.268066,181.257812,0.000135,24.978464,-163.348846,35.000008,100000.0,false,Manual,22.0",
          GUID = "19201F9E",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036564,
          SpeakNpcId = 100001,
          Subtitle = "That fresh wound on your throat... it wasn't an accident, was it? You deliberately sliced your throat because you knew... Blues's voice was the one thing you couldn't perfectly replicate.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/19201F9E"
        },
        [10036564] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "但是为什么，你要做到这种地步？为什么非得伪装布鲁斯不可？为了担下罪责，帮你的朋友逃脱吗？还是……",
          DialogueId = 10036564,
          GUID = "19201FC8",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036565,
          SpeakNpcId = 100001,
          Subtitle = "But why? Why go to such lengths? Why pretend to be Blues? Was it to bear his guilt for him, to help your friend escape? Or...",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201FC8"
        },
        [10036565] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "……难道是因为……！",
          DialogueId = 10036565,
          GUID = "19201FF2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036565.T_Story_Recall_10036565'",
          LookAt = {
            [1] = "200021:n(100327)"
          },
          NextDialogue = 10036566,
          SpeakNpcId = 100001,
          Subtitle = "Could it be...!?",
          VoiceName = "voice/$Locale$/story/1003/100365/19201FF2"
        },
        [10036566] = {
          Camera = "98.539062,-775.041443,241.195312,0.0001,-18.813387,168.048386,35.000019,383.519501,false,Manual,6.0",
          Content = "真正的布鲁斯，他……还活着吗？",
          DialogueId = 10036566,
          GUID = "1920201C",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "100327:n(200021)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036567,
          SpeakNpcId = 200021,
          Subtitle = "The real Blues... is he still alive?",
          VoiceName = "voice/$Locale$/story/1003/100365/1920201C"
        },
        [10036567] = {
          Camera = "228.755859,-562.123291,362.398438,0.000009,-34.213959,-130.736176,35.0,100000.0,false,Manual,22.0",
          Content = "连这个都，猜中了啊……",
          DialogueId = 10036567,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "228.755859,-562.123291,362.398438,0.0,-31.414701,-131.336136,35.0,100000.0,false,Manual,22.0",
          GUID = "19202046",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036568,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "You even... figured that out...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19202046"
        },
        [10036568] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          Content = "是的，布鲁斯已经不在了。但他不想，他的姐姐知道，是谁杀了自己……",
          DialogueId = 10036568,
          GUID = "19202070",
          LookAt = {
            [1] = "100327:n(100001)",
            [2] = "100001:n(100327)"
          },
          NextDialogue = 10036569,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "Blues is gone. But he didn't want his sister to ever know who it was... that killed him.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19202070"
        },
        [10036569] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          Content = "你，很聪明。如果那时，我们，也和你一样……算了，哪有如果。",
          DialogueId = 10036569,
          GUID = "1920209A",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 100365691,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "You're sharp. If only... we'd been... as perceptive back then... Doesn't matter now. Regrets won't... change the past.",
          VoiceName = "voice/$Locale$/story/1003/100365/1920209A"
        },
        [10036570] = {
          Content = "我，骗了你们。那个故事里，我交换了，两个人的名字。是……布鲁斯，救了我。他再次告诉我，生而为人，是怎样的感觉。",
          DialogueId = 10036570,
          GUID = "192020C4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036570.T_Story_Recall_10036570'",
          NextDialogue = 10036571,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "I... lied to you. In the story, I swapped our names. It was the other way around — Blues was the one... who saved me. He reminded me what it felt like... to be human.",
          VoiceName = "voice/$Locale$/story/1003/100365/192020C4"
        },
        [10036571] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          Content = "但我早已，被掠夺，为人的资格。名字，只是，死去的泡影……你便叫我<H>幻景</>吧。",
          DialogueId = 10036571,
          GUID = "192020EE",
          NextDialogue = 10036572,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "But I lost the right... to call myself human long ago. What's the point... of a name for a ghost of the past...? If a name is required, just call me Phantasio.",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192020EE"
        },
        [10036572] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          Content = "狩月人，我委托你，带上黎瑟，离开这里，保护好她。",
          DialogueId = 10036572,
          GUID = "19202118",
          NextDialogue = 10036573,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"-82.046875,-610.927673,194.027344,0.000118,-26.818573,-136.336395,35.000011,436.775146,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Phoxhunters, here's my commission: Take Rhythm, leave this place, and keep her safe.",
          VoiceName = "voice/$Locale$/story/1003/100365/19202118"
        },
        [10036573] = {
          Camera = "-56.003906,-789.403503,240.355469,0.000146,-20.62079,26.854027,35.000011,427.825653,false,Manual,4.0",
          Content = "并且，永远永远，不要对她，提起，我这个人。",
          DialogueId = 10036573,
          GUID = "19202142",
          NextDialogue = 10036574,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "And... never ever... tell her about me.",
          VoiceName = "voice/$Locale$/story/1003/100365/19202142"
        },
        [10036574] = {
          Camera = "305.888672,-395.790466,84.648438,3.600263,12.786038,-118.316017,35.000008,100000.0,false,Manual,22.0",
          Content = "……我，{nickname}，接受你的委托。我保证一定做到。还有……",
          DialogueId = 10036574,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "1920216C",
          NextDialogue = 10036575,
          SpeakNpcId = 100001,
          Subtitle = "...I, , accept your commission. I swear I'll see it through. And...",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/1920216C"
        },
        [10036575] = {
          Camera = "53.519531,-654.918152,148.410156,3.600489,-3.414336,17.482788,35.0,100000.0,false,Manual,22.0",
          Content = "幻景，你是最优秀的演员。",
          DialogueId = 10036575,
          FinalCamera = "83.15625,-645.581787,146.570312,3.600519,-3.414295,17.483107,35.000008,43231.078125,false,DoNotOverride,22",
          GUID = "19202196",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10036576,
          SpeakNpcId = 100001,
          Subtitle = "Phantasio... you are the best performer I've ever seen.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/19202196"
        },
        [10036576] = {
          Camera = "165.486328,-539.479675,106.078125,3.601561,21.381168,-118.114235,35.000011,100000.0,false,Manual,22.0",
          Content = "谢、谢。",
          DialogueId = 10036576,
          GUID = "192021C0",
          NextDialogue = 10036577,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Thank... you.",
          TalkActionId = {
            [1] = "100327:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192021C0"
        },
        [10036577] = {
          Camera = "451.453125,-616.61145,77.289062,-6.000039,10.974379,-171.489777,25.000006,100000.0,false,Manual,22.0",
          Content = "有机会的话，我也想听你讲你的故事，<H>你自己的故事</>。所以，保重。",
          DialogueId = 10036577,
          GUID = "192021EA",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10036578,
          SpeakNpcId = 100001,
          Subtitle = "One day, if fate allows, I'd like to hear your story. The story of your own life. Until then... take care.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192021EA"
        },
        [10036578] = {
