        },
        [10036588] = {
          Camera = "176.990234,-643.489014,165.234375,0.000066,-17.804827,38.764221,25.0,6522.728027,false,Manual,22.0",
          DialogueId = 10036588,
          DialoguePanelType = "None",
          Duration = 2,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "19201D54",
          NextDialogue = 10036550,
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [10036590] = {
          Content = "背叛军团的只有我一人，狩月人小队是无端卷进来的，还请长官不要为难他们。",
          DialogueId = 10036590,
          GUID = "19201AB3",
          NextDialogue = 10036534,
          SpeakNpcId = 100304,
          Subtitle = "I'm the one who betrayed the Legion. The Phoxhunters were merely caught up in it — they're innocent. Please, sir... don't punish them for my mistake.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201AB3"
        },
        [10036601] = {
          Camera = "-468.048828,-114.833618,288.109375,0.000034,-35.421776,40.107498,11.88,100000.0,false,Manual,22.0",
          Content = "这样就，没人知道，你们来过。",
          DialogueId = 10036601,
          Duration = 5,
          FinalCamera = "-455.794922,-104.521362,276.699219,0.00003,-35.421753,40.107464,11.88,100000.0,false,Manual,22.0",
          GUID = "192025DA",
          LookAt = {
            [1] = "100327:n(100341)"
          },
          NextDialogue = 10036602,
          Scripts = [[
PARA{
SetLocation{ActorId{100327},TargetPoint{"tuosi02_62"},Visibility{"Show"}},
SetRotation{SetRotationDescription{"100350:p(150)"}},
SetRotation{SetRotationDescription{"100351:p(120)"}},
SetRotation{SetRotationDescription{"100353:p(110)"}},
SetRotation{SetRotationDescription{"100352:p(100)"}},
SetRotation{SetRotationDescription{"100340:p(60)"}},
SetRotation{SetRotationDescription{"100341:p(30)"}},
SetRotation{SetRotationDescription{"100342:p(-30)"}},
SetRotation{SetRotationDescription{"100343:p(-60)"}},
SetRotation{SetRotationDescription{"100348:p(-90)"}},
SetRotation{SetRotationDescription{"100349:p(-100)"}},
SetRotation{SetRotationDescription{"100347:p(-120)"}},
SetRotation{SetRotationDescription{"100346:p(-150)"}},
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "This way, no one will ever know you were here... and attacked the Legion.",
          TalkActionId = {
            [1] = "100310:Onground02",
            [2] = "100340:Onground02",
            [3] = "100341:Onground02",
            [4] = "100342:Onground02",
            [5] = "100343:Onground02",
            [6] = "100350:Onground02",
            [7] = "100351:Onground02",
            [8] = "100352:Onground02",
            [9] = "100353:Onground02",
            [10] = "100346:Onground02",
            [11] = "100347:Onground02",
            [12] = "100348:Onground02",
            [13] = "100349:Onground02"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100366/192025DA"
        },
        [10036602] = {
          Content = "这个秘密，由我……带进坟墓。",
          DialogueId = 10036602,
          GUID = "19202604",
          NextDialogue = 10036603,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I'm taking this secret... to the grave.",
          VoiceName = "voice/$Locale$/story/1003/100366/19202604"
        },
        [10036603] = {
          Camera = "-508.236328,-141.803528,-26.71875,-0.001345,50.110828,41.260582,15.0,100000.0,false,Manual,22.0",
          Content = "布鲁斯，我完成约定了。",
          DialogueId = 10036603,
          FinalCamera = "-508.236328,-141.803528,-26.71875,-0.001344,55.910446,50.060265,15.0,100000.0,false,Manual,22.0",
          GUID = "1920262E",
          LookAt = {
            [1] = "100327:p(tuosi02_62_lookat)"
          },
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Blues... I've fulfilled my promise.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100327:p(70)"
          },
          VoiceName = "voice/$Locale$/story/1003/100366/1920262E"
        },
        [10036604] = {
          Content = "（士兵的手腕有一道细细的伤痕，稍加辨认便能看出是被利剑所伤。但<H>这个舞台最终留下的，应该只有军团与“怪物”战斗的痕迹才对。</>）",
          DialogueId = 10036604,
          GUID = "1920226A",
          NextOptions = {
            [1] = 10036605
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(A faint cut crosses the soldier's wrist — fine, clean, unmistakably made by a blade. But in this version of the story, only the legionaries and the \"monster\" should've left their marks.)"
        },
        [10036605] = {
          Content = "（毁掉剑痕。）",
          DialogueId = 10036605,
          GUID = "1920226B",
          NextDialogue = 10036606,
          Subtitle = "(Erase the blade cut)"
        },
        [10036606] = {
          Content = "（那道剑伤足够细，所以伤口的形状可以轻易被破坏掉。朱红的露滴滚落，<H>就像从来没有一位使剑的狩月人来过这里一样。</>）",
          DialogueId = 10036606,
          GUID = "1920226C",
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(The cut is fine enough that a simple smear disrupts the shape. Crimson beads well up and roll down — as if no sword-wielding Phoxhunter had ever set foot here.)"
        },
        [10036607] = {
          Content = "（士兵的身上有大面积焦痂，稍加辨认便能看出遭受过电击。但<H>这个舞台最终留下的，应该只有军团与“怪物”战斗的痕迹才对。</>）",
          DialogueId = 10036607,
          GUID = "1920226D",
          NextOptions = {
            [1] = 10036608
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(The soldier's body is marred with scorched welts — telltale signs of electrical burns. But in this version of the story, only the legionaries and the \"monster\" should've left their marks.)"
        },
        [10036608] = {
          Content = "（扯过电缆。）",
          DialogueId = 10036608,
          GUID = "1920226E",
          NextDialogue = 10036609,
          Subtitle = "(Pull the cable)"
        },
        [10036609] = {
          Content = "（落地灯碎裂，垂落的电缆被拦腰扯断。电火花跳起快活的小步舞曲，<H>就像从来没有一位能操纵电流的军官来过这里一样。</>啊，可惜了，那真的是一盏很漂亮的落地灯。）",
          DialogueId = 10036609,
          GUID = "1920226F",
          NextDialogue = 10036610,
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(The floor lamp shatters. A loose cable swings down, severed clean through. Sparks rise in a cheerful little dance — as if no lightning-wielding officer had ever set foot here. A pity, though... it was such a lovely lamp.)"
        },
        [10036610] = {
          Content = "（现在，布景已经完成了：十三军团一路追查到盖雷亚剧院，<H>先头小队虽然疏散了群众，却不幸命丧“怪物”之手。</>随后赶来的大部队则成功击毙“怪物”，为卡戎狩猎一案画上了休止符——这才是卡戎狩猎最恰如其分的谢幕。）",
          DialogueId = 10036610,
          GUID = "19202270",
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(And now, the stage is set: the 13th Legion pursued the creature to the Galea Theatre. The advance team evacuated the civilians — but fell to the \"monster.\" The main force arrived soon after, struck it down, and brought the Charon Hunt to its proper close. A fitting curtain call... as if the tale had always been written this way."
        },
        [10036701] = {
          Content = "神弃者同盟的人走了，布鲁斯，你的伤怎么样……布鲁斯，布鲁斯！",
          DialogueId = 10036701,
          GUID = "19203642",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036702,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "The Forsakens guy is gone now... How are you feeling? Blues? Blues!",
          VoiceName = "voice/$Locale$/story/1003/100367/19203642"
        },
        [10036702] = {
          Content = "这具躯体，也不是，钢筋铁骨……这帝国炼金院，技术，也不怎么样。",
          DialogueId = 10036702,
          GUID = "1920366C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Turns out this body... isn't exactly indestructible after all... So much for the Empire's so-called... alchemical genius.",
          VoiceName = "voice/$Locale$/story/1003/100367/1920366C"
        },
        [10036703] = {
          Content = "姐姐的……枪法还挺准，比以前厉害……多了。看来，她已经可以，保护好，自己……咳！",
          DialogueId = 10036703,
          GUID = "19203696",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036704,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "My sister's aim... has gotten a lot better... Looks like she's capable... of protecting herself now... *coughs*",
          VoiceName = "voice/$Locale$/story/1003/100367/19203696"
        },
        [10036704] = {
          Content = "现在是说这种话的时候吗！",
          DialogueId = 10036704,
          GUID = "192036C0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Is that what's important right now!?",
          VoiceName = "voice/$Locale$/story/1003/100367/192036C0"
        },
        [10036705] = {
          Content = "哈，哈。",
          DialogueId = 10036705,
          GUID = "192036EA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Huff... huff...",
          VoiceName = "voice/$Locale$/story/1003/100367/192036EA"
        },
        [10036706] = {
          Content = "撑住，我带你去找医生！只要用武力逼迫他们，就算是我们这样的怪物……",
          DialogueId = 10036706,
          GUID = "19203714",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036707,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Hang in there! I'll take you to a doctor! As long as we use force to coerce them, even monsters like us can—",
          VoiceName = "voice/$Locale$/story/1003/100367/19203714"
        },
        [10036707] = {
          Content = "……没必要，了。",
          DialogueId = 10036707,
          GUID = "1920373E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036708,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "No need for... that.",
          VoiceName = "voice/$Locale$/story/1003/100367/1920373E"
        },
        [10036708] = {
          Content = "你一直，不肯告诉我……但我能猜到，身上，洗不掉的血……是……哪来的……",
          DialogueId = 10036708,
          GUID = "19203768",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036709,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "You refused... to tell me... about all the bloodstains on me... that won't wash off... but I've figured it out...",
          VoiceName = "voice/$Locale$/story/1003/100367/19203768"
        },
        [10036709] = {
          Content = "这样，死掉，对大家，很好……",
          DialogueId = 10036709,
          GUID = "19203792",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036710,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "It's a good thing... to let me die here... at least it'll bring peace... to everyone...",
          VoiceName = "voice/$Locale$/story/1003/100367/19203792"
        },
        [10036710] = {
          Content = "混蛋，别大家大家的，你自己呢？你忘了自己怎么说的？等逃出来，我们会搭起舞台，我会教你表演，让所有亲朋好友来看我们的演出！",
          DialogueId = 10036710,
          GUID = "192037BC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036711,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Peace to everyone? What about you!? You idiot! You said after we got out, we'd set up a stage of our own! I'd teach you how to perform, and we'd invite everyone we know to watch our show!",
          VoiceName = "voice/$Locale$/story/1003/100367/192037BC"
        },
        [10036711] = {
          Content = "抱歉……要食言了……",
          DialogueId = 10036711,
          GUID = "192037E6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Sorry... looks like... I won't be able to keep that promise...",
          VoiceName = "voice/$Locale$/story/1003/100367/192037E6"
        },
        [10036712] = {
          Content = "不……对了，姐姐、你的姐姐！你说过最想念的就是姐姐，你还没和她相认啊！",
          DialogueId = 10036712,
          GUID = "19203810",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "No... Oh! What about your sister!? You said she's the one you missed the most! You haven't even reunited with her yet!",
          VoiceName = "voice/$Locale$/story/1003/100367/19203810"
        },
        [10036713] = {
          Content = "……我是个，懦夫……嘴上说着，想要与亲人团聚的，漂亮话。可，真的见到她，除了……落荒而逃……什么都，做不了……",
          DialogueId = 10036713,
          GUID = "1920383A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...I'm a coward... I said I wanted to see her again... but when I finally did... I ran like a coward. There was nothing... I could do...",
          VoiceName = "voice/$Locale$/story/1003/100367/1920383A"
        },
        [10036714] = {
          Content = "我、我有个……请求。",
          DialogueId = 10036714,
          GUID = "19203864",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036715,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I... I have one last request.",
          VoiceName = "voice/$Locale$/story/1003/100367/19203864"
        },
        [10036715] = {
          Content = "这条链子是……信物。找到姐姐，告诉她……第六军团……真相……不要，她……也被骗……",
          DialogueId = 10036715,
          GUID = "1920388E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036716,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "This chain... it's a keepsake. Find my sister. Tell her the truth... about the 6th Legion... Don't let her fall into their trap... like I did...",
          VoiceName = "voice/$Locale$/story/1003/100367/1920388E"
        },
        [10036716] = {
          Content = "还有，<H>绝对，别让她，知道……我死在，她手上。</>她会，受不住……",
          DialogueId = 10036716,
          GUID = "192038B8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036717,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "And... don't ever let her know... that I died... by her hand. She wouldn't... be able to bear it...",
          VoiceName = "voice/$Locale$/story/1003/100367/192038B8"
        },
        [10036717] = {
          Content = "拜托……你了。",
          DialogueId = 10036717,
          GUID = "192038E2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036718,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Please... Promise me...",
          VoiceName = "voice/$Locale$/story/1003/100367/192038E2"
        },
        [10036718] = {
          Content = "布鲁斯……！！",
          DialogueId = 10036718,
          GUID = "1920390C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036719,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Blues...!!",
          VoiceName = "voice/$Locale$/story/1003/100367/1920390C"
        },
        [10036719] = {
          Content = "我答应你。",
          DialogueId = 10036719,
          GUID = "19203936",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036720,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I promise.",
          VoiceName = "voice/$Locale$/story/1003/100367/19203936"
        },
        [10036720] = {
          Content = "但是……用什么办法才能隐瞒你的死因，又让她相信第六军团的真相……",
          DialogueId = 10036720,
          GUID = "19203960",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036721,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "But... how do I tell her the truth without letting her know you're gone...?",
          VoiceName = "voice/$Locale$/story/1003/100367/19203960"
        },
        [10036721] = {
          Content = "……我知道了。",
          DialogueId = 10036721,
          GUID = "1920398A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036722,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "...I get it.",
          VoiceName = "voice/$Locale$/story/1003/100367/1920398A"
        },
        [10036722] = {
          Content = "<H>只要让她以为“布鲁斯”还活着，让“布鲁斯”告诉她一切</>……只要这样……",
          DialogueId = 10036722,
          GUID = "192039B4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I just need to make her believe Blues is still alive... Let \"Blues\" tell her everything. So...",
          VoiceName = "voice/$Locale$/story/1003/100367/192039B4"
        },
        [10036801] = {
          Camera = "-120.507812,969.508057,189.074219,0.000029,7.583572,-89.405365,40.000011,1878.839111,false,Manual,22.0",
          Content = "布鲁斯，我，做到了。谎言，揭穿了。",
          DialogueId = 10036801,
          FinalCamera = "-119.283203,850.649658,204.894531,0.000029,7.583572,-89.405365,40.000011,1878.839111,false,Manual,22.0",
          GUID = "192046AA",
          NextDialogue = 10036802,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"-273.832031,-672.285706,334.296875,1.000035,27.383572,47.593906,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-265.71875,-677.161194,334.46875,1.000014,27.183973,47.994926,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{6}}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Blues... I did it. The 6th Legion's lies... are finally exposed.",
          TalkActionId = {
            [1] = "100351:Onground02",
            [2] = "100348:Onground02",
            [3] = "100348:Onground02",
            [4] = "100349:Onground02",
            [5] = "100350:Onground02"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100327:p(160)"
          },
          VoiceName = "voice/$Locale$/story/1003/100368/192046AA"
        },
        [10036802] = {
          Camera = "-466.845703,-310.563477,241.335938,-0.000153,18.977612,-31.780825,30.000002,444.161255,false,Manual,1.2",
          Content = "黎瑟不会知道，你真正的死因。",
          DialogueId = 10036802,
          FinalCamera = "-466.845703,-310.563477,241.335938,-0.000153,22.377522,-31.181177,30.000002,444.161255,false,Manual,1.2",
          GUID = "192046D4",
          NextDialogue = 10036803,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Rhythm... she'll never know the truth about your death.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100368/192046D4"
        },
        [10036803] = {
          Camera = "-406.080078,352.169067,162.449219,0.003067,16.17347,-77.143387,35.000008,100000.0,false,DoNotOverride,22.0",
          Content = "……",
          DialogueId = 10036803,
          FinalCamera = "-369.617188,360.290283,162.449219,0.003071,16.173443,-78.742867,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "192046FE",
          NextDialogue = 10036804,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-217.296875,-769.525635,326.394531,0.000022,23.965097,73.870346,25.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-200.169922,-773.712402,326.394531,0.000025,23.965036,80.669273,25.0,100000.0,false,DoNotOverride,22.0\"},duration{6}}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "...",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100368/192046FE"
        },
        [10036804] = {
          Camera = "-707.240234,463.596924,56.441406,0.000062,10.230789,-5.153081,40.000027,100000.0,false,DoNotOverride,22.0",
          Content = "我们，头一次的，合作表演，还，不错吧。",
          DialogueId = 10036804,
          FinalCamera = "-707.240234,463.596924,56.441406,0.000061,10.030787,23.246756,40.000027,100000.0,false,DoNotOverride,22.0",
          GUID = "19204728",
          NextDialogue = 10036805,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{1},TargetPosition{\"-155.210938,420.388672,141.570312,0.000106,14.365984,-85.363564,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-199.027344,1123.37085,-9.492188,3.599992,13.965052,-86.362556,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0.7}}},PARA{MoveTo{ActorId{100356},TargetPoint{\"cp2fixsimple63Point01\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100340},TargetPoint{\"cp2fixsimple63Point02\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100341},TargetPoint{\"cp2fixsimple63Point03\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100342},TargetPoint{\"cp2fixsimple63Point04\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100346},TargetPoint{\"cp2fixsimple63Point06\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100347},TargetPoint{\"cp2fixsimple63Point07\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100343},TargetPoint{\"cp2fixsimple63Point05\"},MoveSpeed{250},Visibility{\"Show\"}}}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "That was... our first performance together. Not bad, wouldn't you say?",
          TalkActionId = {
            [1] = "100356:Confident_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1003/100368/19204728"
        },
        [10036805] = {
          Camera = "-420.388672,-1342.850464,761.507812,-3.600986,-22.405731,78.146645,40.000034,2402.064941,false,Manual,1.614437",
          Content = "你们……终于来了。",
          DialogueId = 10036805,
          FinalCamera = "-380.070312,-1351.987915,759.113281,-3.600983,-22.405724,79.34613,40.000034,2402.064941,false,Manual,1.614437",
          GUID = "19204752",
          NextDialogue = 10036806,
          Scripts = "PlayAnimation{_delay{4},ActorId{100327},AnimationId{\"Talk01_Start\"},Duration{2}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "You finally... came.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100327:n(100356)"
          },
          VoiceName = "voice/$Locale$/story/1003/100368/19204752"
        },
        [10036806] = {
          Camera = "-2647.710938,-2161.527832,644.511719,0.001361,-86.042442,-139.842682,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "你们，为了抓，这家伙，才把我放走……聪明，真聪明。",
          DialogueId = 10036806,
          FinalCamera = "-2658.802734,-2162.93457,557.863281,0.001951,-85.029205,-110.631744,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1920477C",
          LookAt = {
            [1] = "100356:n(100356)"
          },
          NextDialogue = 10036807,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-197.001953,-177.368408,271.332031,0.000062,25.596645,-80.446327,40.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-167.640625,-169.903809,271.332031,0.000068,26.396597,-85.246094,40.0,100000.0,false,DoNotOverride,22.0\"},duration{6}}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "You purposely... let me loose... so that you could... catch this guy. That's quite brilliant.",
          TalkActionId = {
            [1] = "100327:Talk01_End",
            [2] = "100327:Talk01_End",
            [3] = "100330:Die"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100368/1920477C"
        },
        [10036807] = {
          Camera = "-204.759766,622.954346,74.933594,0.000039,14.192156,-80.992317,40.000027,2402.064941,false,DoNotOverride,1.614437",
          Content = "这么聪明，一定，拿到了，我留的线索……但是，为什么，不说出来？",
          DialogueId = 10036807,
          FinalCamera = "-204.759766,619.0,92.800781,0.000041,13.792146,-81.600647,40.000027,2402.064941,false,DoNotOverride,1.614437",
          GUID = "192047A6",
          NextDialogue = 10036808,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-159.652344,-253.256104,344.800781,0.000028,20.190475,-86.998611,40.000031,2402.064941,false,DoNotOverride,1.614437\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-159.652344,-253.256104,357.800781,0.000028,20.190475,-86.998611,40.000031,2402.064941,false,DoNotOverride,1.614437\"},duration{8}}}",
          SpeakNpcId = 100328,
