        [10036903] = {
          Camera = "186.626953,551.218262,-297.511719,0.000243,5.806268,-32.186558,60.0,119.689644,false,Manual,8.0",
          Content = "“无论如何都想要达成的目标。我们常常把它叫做‘梦想’。”",
