        [10100211] = {
          Camera = "321.105469,367.106934,155.726562,0.001201,-4.999698,-131.971817,50.0,560.205811,false,Manual,3.0",
          ContentES = "Entonces conoces... a una mujer que se llama Sibylle. Algunos la llaman “Comandante”. Debe de estar en este país... Tengo que encontrarla.",
          DialogueId = 10100211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1948E9B4",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 10100212,
          SpeakNpcId = 100001,
          Subtitle = "Do you know this woman called Sibylle? Others refer to her as the \"Chief,\" and she's supposed to be in this country... I need to find her.",
          TalkActionId = {
            [1] = "200002:Talk03_End",
            [2] = [[

100001:Talk02_Start]]
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E9B4"
        },
        [10100212] = {
          Camera = "109.613281,-278.998535,123.344238,0.001196,-0.900663,111.229919,35.0,350.570953,false,Manual,3.0",
          ContentES = "Sibylle es un nombre común. Pero a la que llaman “Comandante” solo hay una. ¿De verdad quieres encontrarla? ¿Qué te ha congelado el cerebro? Pensé que los Charons eran resistentes al frío.",
          DialogueId = 10100212,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "1948E9DE",
          NextDialogue = 10100213,
          RelatedWikiId = {
            [1] = 303003
          },
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{200003},AnimationId{"Talk03_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200003},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Sibylle is a common name, but there's only one that's linked with the title \"Chief.\" You want to find her? How did you lose your mind to the blizzard? I thought Charons are supposed to be resistant to cold temperatures.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E9DE"
        },
