          ContentES = "Hablo en serio. Puede que se haya llevado... algo que para mí es más importante que nada, así que debo encontrarla y aclararlo todo.",
          DialogueId = 10100213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01",
            [2] = "200003:None",
            [3] = "200002:None"
          },
          GUID = "1948EA08",
