          Camera = "67.046875,-72.922852,121.009277,0.001219,8.898916,104.827866,36.0,149.916138,false,Manual,2.8",
          ContentES = "Espionaje, asesinato, rebelión... Con solo lo que acabas de decir, los soldados del Imperio tendrían tres buenas razones para detenerte. Si realmente quieres conocer a la Comandante, evita lanzarte de cabeza.",
          DialogueId = 10100214,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "61.769531,-52.95752,124.242676,0.001221,8.898916,104.827972,36.0,132.852249,false,Manual,2.8",
          GUID = "1948EA32",
          NextDialogue = 10100215,
          Scripts = [[
SEQ{
