          VoiceName = "voice/$Locale$/story/1002/101008/19494CA2"
        },
        [10100814] = {
          ContentES = "Alguien te sacará de las aguas oscuras y te llevará a una vasta extensión helada, donde el destino te impondrá la verdadera prueba.",
          DialogueId = 10100814,
          ExStoryInfo = "EXPlayer",
          GUID = "19494CA3",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10100814.T_Story_Recall_10100814'",
          NextDialogue = 10100815,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Someone will pluck you from the briny waters and lead you to a frozen wilderness, where destiny will pose the ultimate test.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56B"
        },
        [10100815] = {
          Camera = "46.295898,-14.689941,134.97168,0.001182,0.698551,169.273804,35.000008,134.419968,false,Manual,4.0",
          ContentES = "(...¿Es la persona de mis sueños quien envió a alguien para salvarme? ¿Pero por qué traerme aquí?)",
          DialogueId = 10100815,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
