PlayAnimation{_delay{4.5},ActorId{100001},AnimationId{"Think_End"},Duration{1}}
}]],
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So, what I'm facing isn't just Sibylle but the Empire behind her. Do I stand a chance? Not for now, at least... I need a plan B.)",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494E46"
        },
        [10100824] = {
          Camera = "-312.145508,-248.166504,147.804199,0.00115,-6.100185,35.0606,35.000008,524.896545,false,Manual,4.0",
          ContentES = "Vamos a dejarlo por hoy. He estado fuera tanto tiempo que el Asfódelo ya debe estar bastante desordenado.",
          DialogueId = 10100824,
          FacialId = {
            [1] = "200003:Uninterested01"
