        [10100830] = {
          Camera = "549.845703,44.259766,152.453613,0.00125,-3.698793,-176.199417,50.0,661.213013,false,Manual,8.0",
          ContentES = "Aparte de ese lugar tan maldito que hasta los soldados evitan registrarlo, ¿quién aceptaría acoger a {性别:un|una} Charon sin permiso de viaje?",
          DialogueId = 10100830,
          GUID = "19494F6C",
          NextDialogue = 10100831,
          SpeakNpcId = 200003,
          Subtitle = "Where else would take in a Charon without a travel permit but a place that is so creepy even the soldiers didn't want to search?",
          TalkActionId = {
