          VoiceName = "voice/$Locale$/story/1002/101008/19494F96"
        },
        [10100832] = {
          Camera = "-216.379883,-128.320312,189.390137,0.00122,-17.30224,36.452347,50.0,370.186615,false,Manual,4.0",
          ContentES = "Umm... ¡Está bien! Viéndote tan {性别:solo y perdido|sola y perdida}, te llevaré a la Casa de Hypnos para ver qué pasa.",
          DialogueId = 10100832,
          FacialId = {
