}]],
          SpeakNpcId = 200002,
          Subtitle = "Umm... Alright! Seeing you so lonely and lost, I'll take you to this Hypnos' House to see what's what!",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101008/19494FC0"
        },
        [10100901] = {
          ContentES = "Esa “mansión embrujada” de la que hablas, ¿qué es exactamente?",
          DialogueId = 10100901,
          ExStoryInfo = "Player",
          GUID = "19495B12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100902,
          SpeakNpcId = 100001,
          Subtitle = "What exactly did you mean by \"haunted house\"?",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B12"
        },
        [10100902] = {
          ContentES = "Es lo que dicen los clientes del Asfódelo. Siempre hay alguien que se queja—",
          DialogueId = 10100902,
          GUID = "19495B3C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100903,
          SpeakNpcId = 200002,
          Subtitle = "I heard about it from the guests at The Asphodel. There's always someone complaining—",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B3C"
        },
        [10100903] = {
          ContentES = "Es una posada inmensa, pero las puertas permanecen cerradas día y noche, y siempre rechazan a los viajeros de paso.",
          DialogueId = 10100903,
          GUID = "19495B66",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100904,
          SpeakNpcId = 200002,
          Subtitle = "Like, even though it's such a big inn, the doors are always shut tight every day, turning away any travellers from outside the town...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B66"
        },
        [10100904] = {
          ContentES = "O cómo los huéspedes parecen nunca salir, y a veces, hay un olor raro que flota desde el interior de la casa...",
          DialogueId = 10100904,
          GUID = "19495B90",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100905,
          SpeakNpcId = 200002,
          Subtitle = "Or how the lodgers seem to never ever leave, and sometimes, there's this really weird smell drifting from the inside of the house...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B90"
        },
        [10100905] = {
          ContentES = "O incluso, la cara del posadero es más fría que las aguas del Lago Lamentoso, ¡parece que tiene una tienda de ataúdes en lugar de una posada!",
          DialogueId = 10100905,
          GUID = "19495BBA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100906,
          SpeakNpcId = 200002,
          Subtitle = "And how the innkeeper's face is colder than the waters of Lamenting Lake... It's as if he's not running an inn, but a coffin shop!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495BBA"
        },
        [10100906] = {
          ContentES = "No parece tan terrible. Pensé que estaba llena de Filthoids y Sibylles.",
          DialogueId = 10100906,
          ExStoryInfo = "Player",
          GUID = "19495BE4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10100907,
          SpeakNpcId = 100001,
          Subtitle = "It doesn't sound too bad. I thought it was crammed with Filthoids and Sibylles.",
          VoiceName = "voice/$Locale$/story/1002/101009/19495BE4"
        },
        [10100907] = {
          ContentES = "Pero, como no reciben a los forasteros, me temo que no podré...",
          DialogueId = 10100907,
          ExStoryInfo = "Player",
          GUID = "19495C0E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100908,
          SpeakNpcId = 100001,
          Subtitle = "But, if they don't welcome outsiders, I doubt if I can...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C0E"
        },
        [10100908] = {
          ContentES = "Bueno, parece que la señora Camilla Scarlet tiene cierta reputación aquí. Tal vez pueda aprovecharme de eso...",
          DialogueId = 10100908,
          ExStoryInfo = "Player",
          GUID = "19495C38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100909,
          SpeakNpcId = 100001,
          Subtitle = "Still, it seems Ms Camilla Scarlet holds some sway here. Hmm... perhaps I could leverage her influence a little bit.",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C38"
        },
        [10100909] = {
          ContentES = "¡No es necesario! Puedes usar el nombre de Nieve. ¡Desde ahora, estás bajo mi protección, mi {性别:pequeño secuaz|pequeña secuaz}!",
          DialogueId = 10100909,
          GUID = "19495C62",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100910,
          SpeakNpcId = 200002,
          Subtitle = "Nah, you can use Snow's name. From now on, you're under my wing, my little minion!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C62"
        },
        [10100910] = {
          ContentES = "Gracias, pero... ¿qué es {性别:un|una} “secuaz”?",
          DialogueId = 10100910,
          ExStoryInfo = "Player",
          GUID = "19495C8C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100911,
          SpeakNpcId = 100001,
          Subtitle = "Thank you, but what's a \"minion\"?",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C8C"
        },
        [10100911] = {
          ContentES = "¡Es como llaman en los cuentos al lacayo favorito del poderoso Rey Demonio!",
          DialogueId = 10100911,
          GUID = "19495CB6",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10100912,
          SpeakNpcId = 200002,
          Subtitle = "It's what they call someone in those stories who's the favourite lackey of the awesome Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495CB6"
        },
        [10100912] = {
          ContentES = "Hay tantos Luno en el mundo... ¿Por qué crees que solo Nieve heredó esos magníficos cuernos? ¡Eso es prueba de que estoy destinada a convertirme en la Reina Demonio!",
          DialogueId = 10100912,
          GUID = "19495CE0",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100913,
          SpeakNpcId = 200002,
          Subtitle = "Among all the Luno in the world, why else would little ol' Snow have these nifty horns, if not to be a Demon King one day? It's totally my destiny!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495CE0"
        },
        [10100913] = {
          ContentES = "Y además, esas misteriosas voces me guiaron hasta ti. ¡Así que eres, sin duda, {性别:el secuaz|la secuaz} que el destino me envió!",
          DialogueId = 10100913,
          ExStoryInfo = "Player",
          GUID = "19495D0A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100914,
          SpeakNpcId = 200002,
          Subtitle = "And it was those mysterious voices that brought me to you, so you must be the minion sent by destiny!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D0A"
        },
        [10100914] = {
          ContentES = "Aaaasí que ya he decidido: ¡con toda mi gran sabiduría, te guiaré por el buen camino!",
          DialogueId = 10100914,
          GUID = "19495D34",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10100915,
          SpeakNpcId = 200002,
          Subtitle = "Soooo~ I've made up my mind— with all my wisdom, I'm gonna guide you down the right path!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D34"
        },
        [10100915] = {
          ContentES = "...",
          DialogueId = 10100915,
          ExStoryInfo = "Player",
          GUID = "19495D5E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
