        [10100916] = {
          ContentES = "“<H>Los Lunarianos</> suelen llevarse bien con los humanos”… Así que los libros no mentían.",
          DialogueId = 10100916,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "19495D88",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100917,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(\"The Lunarians are generally friendly towards humans\"... The books weren't lying.)",
          VoiceName = "voice/$Locale$/story/1002/101009/19495D88"
        },
        [10100917] = {
          ContentES = "¡La posada está justo al norte! ¡Veeen, síiiguee-me!",
          DialogueId = 10100917,
          GUID = "19495DB2",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10100918,
          SpeakNpcId = 200002,
          Subtitle = "The inn's just up north! C'mon, fol—low—me!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495DB2"
        },
        [10100918] = {
          ContentES = "(…Es solo que esta parece ser un poquito demasiado amistosa.)",
          DialogueId = 10100918,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "19495DDC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "HEART",
