          Scripts = "SitOrStand{ActorId{100001},State{\"Sit\"}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So much has happened... Weird dreams, that mysterious man in a white cloak, Sibylle, and \"No. 0\"... They all seem to be connected somehow, but I can't figure it out.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DE52"
        },
        [10101702] = {
          Camera = "32.615486,-85.951172,141.394852,0.001194,-10.600405,119.473099,50.000011,174.121933,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "(Lo único seguro es que he perdido a Berry…)",
