          CameraBlendCurve = "easeInQuad",
          ContentES = "(Por suerte, Sibylle parece <H>necesitar</> a Berry por una razón que desconozco. No debería hacerle daño.)",
          DialogueId = 10101704,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "-50.302734,-52.980469,119.29213,0.001284,-6.599526,87.2173,35.000011,101.591904,false,Manual,6.0",
          GUID = "1949DED0",
          NextDialogue = 10101705,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The silver lining is, it seemed that Sibylle needed Berry for some reason, so she probably wouldn't harm her.)",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DED0"
        },
        [10101705] = {
