          CameraBlendCurve = "easeInOutQuad",
          ContentES = "En fin… Debo encontrar la manera de ganar algo de dinero en Lago Helado, conseguir un permiso de viaje y solo después planear mi próximo paso.",
          DialogueId = 10101705,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "-112.579315,-197.591553,124.529968,0.001198,-6.0,70.830925,35.0,247.426239,false,Manual,2.5",
          GUID = "1949DEFA",
          NextDialogue = 10101801,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Anyway, I need to scrape together some money in Icelake, get a travel permit, and then plan for my next move.)",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DEFA"
        },
