        [10101807] = {
          Camera = "155.289749,17.776367,63.671951,0.001254,10.000004,108.81134,35.000011,302.230957,false,Manual,6.0",
          ContentES = "No es nada. Tenía demasiada hambre y me mordí la lengua sin querer. Me duele, así que…",
          DialogueId = 10101807,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200006:Unhappy01"
          },
          GUID = "1949EFB6",
          NextDialogue = 10101808,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just so hungry that I accidentally bit my tongue. It hurts, so...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949EFB6"
        },
        [10101808] = {
          Camera = "292.073364,582.838379,135.940063,0.00127,-2.89807,-120.987396,50.000011,514.955017,false,Manual,4.0",
          ContentES = "Entonces come el pan y acompáñalo con un poco de leche caliente, eso te hará sentir mejor, ¡pero ten cuidado, no te vuelvas a morder la lengua!",
          DialogueId = 10101808,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1949EFE0",
          NextDialogue = 10101809,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 200006,
          Subtitle = "Then you better eat some bread and wash it down with warm milk, that'll make you feel better — be careful, don't bite your tongue again.",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "200006:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949EFE0"
        },
        [10101809] = {
          Camera = "145.36499,-36.702637,169.322754,0.001274,-7.59989,106.215103,50.000011,344.345856,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "…Gracias, Psyche.",
