        [10102501] = {
          Camera = "-237.39502,-776.429688,380.287109,0.000219,-20.598696,70.000015,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y además, me sorprendió por la espalda y me robó el dinero que acababa de ganar. ¡Ese sinvergüenza ni siquiera deja en paz a los recolectores! ¡Esas monedas eran para mantener a varias familias de los barrios pobres!",
          DialogueId = 10102501,
          FacialId = {
            [1] = "200011:Angry01"
          },
          FinalCamera = "-264.857361,-766.555664,380.287109,0.000222,-20.598696,70.000008,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "194A6192",
          NextDialogue = 10102502,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{200011},AnimationId{"Angry01_Start"},Duration{2}}
}]],
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "...And then, out of nowhere, he ambushed me and pinched the cash I'd just gotten. That rotter, doesn't even spare us scavengers! That money was for several families' upkeep in the slums!",
          TalkActionId = {
            [1] = "200011:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101025/194A6192"
        },
        [10102502] = {
          Camera = "78.0,-7.4375,131.521484,0.000191,-2.398646,-161.013702,35.000008,175.980392,false,Manual,4.0",
          ContentES = "Sin ese saco de monedas, jóvenes y ancianos tendrán que apretarse aún más el cinturón el mes que viene. Ugh… No sé a dónde escapó ese ladrón... Necesito a alguien que me ayude a atraparlo.",
          DialogueId = 10102502,
          FacialId = {
            [1] = "200011:Sad01"
          },
          GUID = "194A61BC",
          LookAt = {
            [1] = "200003:n(200011)"
          },
          NextDialogue = 10102503,
          Scripts = "PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Sigh_Start\"},Duration{2}}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Without that bag of coins, all the young and old will have to tighten their belts even more next month. Ugh... I have no idea where the thief has run off to, I need someone to help me nab him.",
          TalkActionId = {
            [1] = "200011:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A61BC"
        },
        [10102503] = {
          Camera = "-197.983643,-228.263672,131.707031,0.000195,0.20134,50.188034,50.0,454.857483,false,Manual,5.0",
          ContentES = "¿No sería esto tarea de la Oficina de Seguridad?",
          DialogueId = 10102503,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "194A61E6",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextDialogue = 10102504,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"SpecialUnInterested_Start"},Duration{2}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Shouldn't this be something for the Security Bureau to handle?",
          VoiceName = "voice/$Locale$/story/1002/101025/194A61E6"
        },
        [10102504] = {
          Camera = "281.375,129.460938,170.882812,0.000218,-5.998777,-154.617096,62.0,422.431763,false,Manual,5.0",
          ContentES = "Bah, para cuando la Oficina de Seguridad se ocupe de nosotros los Charons, ¡el hielo del Lago Lamentoso ya se habrá derretido!",
          DialogueId = 10102504,
          FacialId = {
            [1] = "200011:Unacceptable01"
          },
          GUID = "194A6210",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102505,
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Well, by the time the Security Bureau bothers with us Charons, the ice in Lamenting Lake would've melted away!",
          TalkActionId = {
            [1] = "200011:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A6210"
        },
        [10102505] = {
          Camera = "-298.685974,-953.163086,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
          ContentES = "Por favor, señora Camilla, la más amable y hermosa de Lago Helado, ¿podría pedir a algunos Phoxcazadores que nos echen una mano… solo un favorcito? ¡Por favor!",
          DialogueId = 10102505,
          FacialId = {
            [1] = "200011:Unacceptable01"
          },
          FinalCamera = "-302.263062,-951.791992,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
          GUID = "194A623A",
          NextDialogue = 10102506,
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Please, Ms Camilla, the kindest and most beautiful lady in Icelake, could you maybe ask some of the Phoxhunters here to lend a hand... Just one tiny favour! Pretty please!",
          TalkActionId = {
            [1] = "200011:Explain02_Start",
            [2] = "200003:SpecialUnInterested_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101025/194A623A"
        },
        [10102506] = {
          Camera = "10.047852,-140.40625,117.429688,0.000236,8.800841,67.194237,56.354355,240.957672,false,Manual,6.0",
          ContentES = "Córtala. Ya sabes que aquí nada se pide sin pagar un precio.",
          DialogueId = 10102506,
          GUID = "194A6264",
          NextDialogue = 10102507,
          SpeakNpcId = 200003,
          Subtitle = "Save it. You should know that nothing asked for here comes without a price.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A6264"
        },
        [10102507] = {
          Camera = "81.471924,-18.664062,159.626953,0.000213,-10.598773,-163.809616,48.734837,175.980392,false,Manual,4.0",
          ContentES = "Entonces... ¿podría al menos... proponer algún arreglo... o aceptar algún otro trueque? Espera, ¿cómo era eso...",
          DialogueId = 10102507,
          GUID = "194A628E",
          NextDialogue = 10102508,
          Scripts = [[
