          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Well then, can you maybe... give me a discount... or I could offer you something else! How does it go again—",
          TalkActionId = {
            [1] = "200011:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A628E"
        },
        [10102508] = {
          Camera = "-200.542847,-222.323242,136.585938,0.000182,1.001258,46.588379,70.000015,435.191498,false,Manual,6.0",
          ContentES = "“¡La información es oro!” Sí, eso es, yo me encargo de todas los basureros de Lago Helado, así que si doy con información interesante, usted será la primera en saberlo.",
          DialogueId = 10102508,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "194A62B8",
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{200011},AnimationId{"Give"},Duration{2}},
LookAt{_delay{7},LookAtDescription{"200003:p(P10102508Kami)"}}
}]],
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "\"Information is as good as gold\", right? I deal with all the rubbish bins in Icelake, so how about this — if I stumble upon any useful info, you'll be the first to know.",
          TalkActionId = {
            [1] = "200011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A62B8"
        },
