            [1] = 101026091,
            [2] = 101026092
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Confident_End"},Duration{2}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_Start"},Duration{2.5}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Let's get one thing straight — this isn't child's play, nor an easy gig. It's TRUE that in this place, no one would probe into your past or background, but the rewards always come with risks.",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101026/194A734A"
        },
        [10102610] = {
          Camera = "-294.801819,-157.509766,135.695312,0.001227,1.1999,33.90601,60.000004,460.630157,false,Manual,12.0",
          ContentES = "No pareces muy fuerte, aunque tu valentía es admirable.",
          DialogueId = 10102610,
          FacialId = {
            [1] = "200006:None",
            [2] = "200011:None"
          },
          GUID = "194A7374",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102611,
          SpeakNpcId = 200003,
          Subtitle = "You don't look tough, though your courage is admirable.",
          TalkActionId = {
            [1] = "200003:Talk03_Start",
            [2] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A7374"
        },
        [10102611] = {
          Camera = "-43.718262,-1261.714844,610.828125,0.001481,-22.297657,82.031219,25.0,166.832703,false,DoNotOverride,22.0",
          ContentES = "De hecho, eres más fuerte que un simple Charon, te vi pelear. Pero para convertirte en {性别:Phoxcazador|Phoxcazadora}, solo la fuerza no basta... tienes que demostrar que puedes manejar todo tipo de imprevistos y clientes.",
          DialogueId = 10102611,
          FinalCamera = "-98.231934,-1254.261719,610.828125,0.001477,-22.297657,82.031197,25.0,166.832703,false,DoNotOverride,22.0",
          GUID = "194A739E",
          NextDialogue = 10102612,
          Scripts = "SetLocation{ActorId{200011},TargetPoint{\"P10102601Maer\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200003,
          Subtitle = "You're indeed stronger than the average Charon — I've seen you in a fight. But brute strength isn't enough to qualify you to be a Phoxhunter. You need to prove that you're capable of dealing with all possible contingencies and a very mixed group of clients.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101026/194A739E"
        },
        [10102612] = {
          Camera = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
          ContentES = "Y justamente, se ha presentado una oportunidad para demostrarlo.",
          DialogueId = 10102612,
          GUID = "194A73C8",
          LookAt = {
            [1] = "200003:n(200011)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 10102613,
          SpeakNpcId = 200003,
          Subtitle = "It just so happens that a chance for that came in just now.",
          VoiceName = "voice/$Locale$/story/1002/101026/194A73C8"
        },
        [10102613] = {
          ContentES = "Ah... ¡sí, sí!",
          DialogueId = 10102613,
          FacialId = {
            [1] = "200011:Happy01"
          },
          GUID = "194A73F2",
          NextDialogue = 10102614,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.2},ActorId{200011},AnimationId{"AgreeHead"},Duration{0.1}},
TurnTo{_delay{2.2},TurnToDescription{"200011:n(100001)"}},
LookAt{_delay{1.5},LookAtDescription{"200003:n(100001)"}},
LookAt{_delay{2},LookAtDescription{"100001:n(200011)"}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Oh... right!",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A73F2"
        },
        [10102614] = {
          Camera = "73.365112,16.138672,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
          ContentES = "Nieve oyó que alguien le robó el dinero a esta señorita.",
          DialogueId = 10102614,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "72.002441,21.418945,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
          GUID = "194A741C",
          LookAt = {
            [1] = "200006:n(200011)",
            [2] = "200003:n(100001)",
            [3] = "100001:n(200011)",
            [4] = "200002:n(200011)"
          },
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"P10102601Bai3\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Snow heard that someone swiped this lady's money.",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101026/194A741C"
        },
        [10102701] = {
          ContentES = "Parece realmente preocupada… puedo ayudar para que lo encontremos más rápido.",
          DialogueId = 10102701,
          GUID = "194A8262",
          NextDialogue = 10102702,
          SpeakNpcId = 200006,
          Subtitle = "She seems quite distressed; I can lend a hand too so we can get it back sooner.",
          VoiceName = "voice/$Locale$/story/1002/101027/194A8262"
        },
        [10102702] = {
          ContentES = "No, esto es una simple prueba para {性别:un futuro Phoxcazador|una futura Phoxcazadora}. Si no tienes lo necesario, convertirte en {性别:Phoxcazador|Phoxcazadora} te mataría.",
          DialogueId = 10102702,
          GUID = "194A828C",
          NextDialogue = 10102703,
          SpeakNpcId = 200003,
          Subtitle = "No, this is a simple test just for a prospective Phoxhunter. If you don't have the chops for it, becoming a Phoxhunter would kill you.",
          TurnTo = {
            [1] = "2000061:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101027/194A828C"
        },
        [10102703] = {
          ContentES = "Está bien...",
          DialogueId = 10102703,
          GUID = "194A82B6",
          SpeakNpcId = 200006,
          Subtitle = "Okay...",
          VoiceName = "voice/$Locale$/story/1002/101027/194A82B6"
        },
        [10102801] = {
          ContentES = "¿De verdad me ayudarías? ¡Vaya... gracias!",
          DialogueId = 10102801,
          GUID = "194A92CA",
          NextDialogue = 10102802,
          SpeakNpcId = 2000111,
          Subtitle = "You'd really help me out? Aww... thank you!",
          TurnTo = {
            [1] = "2000111:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101028/194A92CA"
        },
        [10102802] = {
          ContentES = "El ladrón se fue hacia el oeste. Pero ya sabes, Lago Helado es un verdadero laberinto, ¿quién sabe dónde puede esconderse? ¡Primero busquemos pistas!",
          DialogueId = 10102802,
          GUID = "194A92F4",
          SpeakNpcId = 2000111,
          Subtitle = "That scoundrel headed west. But you know, Icelake is a maze of streets, so I can't be sure where he might have gone. Let's look for some clues first!",
          VoiceName = "voice/$Locale$/story/1002/101028/194A92F4"
        },
        [10103001] = {
          ContentES = "Vaya, ¡es inmenso y espacioso aquí abajo! Y mucho más cálido que en la superficie... casi como un pequeño reino secreto.",
          DialogueId = 10103001,
          GUID = "194A92F5",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10103002,
          SpeakNpcId = 200011,
          Subtitle = "It's surprisingly roomy down here! And much warmer than above ground — like a secret little kingdom.",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F5"
        },
        [10103002] = {
          ContentES = "Ahuyentar a las bestias, quitar el hedor, montar una tienda... ¡podríamos vivir aquí perfectamente!",
          DialogueId = 10103002,
          GUID = "194A92F6",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103003,
          SpeakNpcId = 200011,
          Subtitle = "Chase away those critters and get rid of the smell, then you could pitch a tent and practically live here!",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F6"
        },
        [10103003] = {
          ContentES = "¡Exacto! Y mira, {nickname}, vivir aquí es gratis, ¡no hay que pagar alquiler!",
          DialogueId = 10103003,
          ExStoryInfo = "Player",
          GUID = "194A92F7",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10103004,
          SpeakNpcId = 200002,
          Subtitle = "Right! Whoo, , you should live here — it's rent-free!",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F7"
        },
        [10103004] = {
          ContentES = "Vamos, los echamos fuera, tomamos su territorio, ¡y me proclamo Reina Demonio! A ti te nombraré...",
          DialogueId = 10103004,
          ExStoryInfo = "Player",
          GUID = "194AB3EE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10103005,
          SpeakNpcId = 200002,
          Subtitle = "Let's turf these critters out, seize their land, and I'll crown myself the Demon King! I'd appoint you as...",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB3EE"
        },
        [10103005] = {
          ContentES = "{性别:¡El Valiente Guerrero Cíclope, Señor de Lago Helado, y primer Duque de las Alcantarillas!|¡La Valiente Guerrera Cíclope, Señora de Lago Helado, y primera Duque de las Alcantarillas!}",
          DialogueId = 10103005,
          GUID = "194AB418",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103006,
          SpeakNpcId = 200002,
          Subtitle = "\"The Valiant Cyclopean Warrior, the Cold Lord of Icelake, the Inaugural Duke of the Sewers\"!",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB418"
        },
        [10103006] = {
          ContentES = "(Es un título un poco largo... habría que acortarlo...)",
          DialogueId = 10103006,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB419",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103007,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That title's a bit of a mouthful and could use a polish...)",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB419"
        },
        [10103007] = {
          ContentES = "(Espera, ¿por qué estoy pensando en serio en esto?)",
          DialogueId = 10103007,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB46C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hold on — why am I even considering this?)",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB46C"
        },
