        [10103203] = {
          Camera = "-72.597656,23.658203,28.410049,-5.000005,4.600173,-116.69577,20.0,110.566429,false,Manual,3.0",
          ContentES = "¡Alto, parad! ¡Toma, recupera el dinero! Llevo días sin comer... me he rendido, fue mi culpa, fue mi culpa.",
          DialogueId = 10103203,
          FacialId = {
            [1] = "200053:CM_Sad01"
          },
          GUID = "194AD496",
          LookAt = {
