PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"}},
LookAt{_delay{7},LookAtDescription{"200053:p(101032Haer3)"}}
}]],
          SpeakNpcId = 200053,
          Subtitle = "Alright, alright, here's your money bag! I haven't had a decent meal in days, so I got desperate... I'm sorry!",
          VoiceName = "voice/$Locale$/story/1002/101032/194AD496"
        },
        [10103204] = {
          Camera = "-94.212891,40.829102,88.263504,0.000059,6.830749,-10.009793,37.719067,200.074844,false,Manual,5.0",
          ContentES = "¿Ah, estás muriéndote de hambre? Pues adivina qué: ¡todos en los barrios bajos lo están! ¡Y no parecías tan apenado cuando me arrebataste la bolsa!",
          DialogueId = 10103204,
          FacialId = {
            [1] = "200011:Angry01",
            [2] = "200002:None"
          },
          FinalCamera = "-35.111328,30.1875,96.309219,0.000059,7.630748,-10.209655,37.719067,200.074844,false,Manual,5.0",
          GUID = "194AD497",
          LookAt = {
            [1] = "200053:n(200053)"
          },
          NextDialogue = 10103205,
          Scripts = [[
SEQ{
MoveTo{ActorId{200011},TargetPoint{"101032Maer1"},MoveSpeed{75},Visibility{"Show"}},
PlayAnimation{_delay{0.2},ActorId{200011},AnimationId{"Angry01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Oh, you're starving? Guess what, so is everyone in the slums! And you didn't seem so sorry when you snatched the money bag from me!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101032/194AD497"
        },
        [10103205] = {
          ContentES = "Mmm... ¿qué tal esto?: me diste unos puñetazos, así que ahora te daré unos golpes con mi pala. Luego quedamos a mano y te largas.",
          DialogueId = 10103205,
          FacialId = {
            [1] = "200011:Unhappy02"
          },
          GUID = "194AD498",
          NextDialogue = 10103206,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{200011},AnimationId{"Angry01_End"},Duration{1}},
PlayAnimation{_delay{2},ActorId{200011},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{200011},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Mm... How about this: You threw a few punches at me, so now I'm gonna hit you with my shovel a few times! Then we call it even, and you can leave.",
          TalkActionId = {
