        [10104018] = {
          Camera = "586.407837,263.538086,166.693359,0.001254,-5.098381,-163.341629,60.0,424.533936,false,Manual,3.8",
          ContentES = "Tú misma me dijiste, si ni siquiera puedo manejar esto, ¿cómo encontraré... mi tesoro perdido?",
