        [10104019] = {
          Camera = "-127.626587,-169.432617,135.080078,0.001295,0.699917,38.798576,70.000015,100000.0,false,DoNotOverride,2.8",
          ContentES = "El Asfódelo no interviene en la elección de encargo de los clientes o los Phoxcazadores. Si estás {性别:decidido|decidida}, no te detendré.",
          DialogueId = 10104019,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "194B5A9E",
          LookAt = {
            [1] = "200065:n(200003)"
          },
          NextDialogue = 10104022,
          Scripts = [[
