        },
        [10104602] = {
          Camera = "-4.705078,-275.623535,148.607422,0.000054,-3.999943,59.446644,35.000008,204.586716,false,Manual,7.37621",
          ContentES = "Gracias, nos has ayudado muchísimo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104602,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "194BBA44",
