          Scripts = "PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Thank you, you've been a tremendous help.",
          TalkActionId = {
