CameraMoveTo{TargetPosition{"25.423828,-300.893066,153.260254,0.000032,-17.799767,100.245705,35.000008,204.586716,false,Manual,7.37621"},Blend{"easeInOutQuad"},duration{8}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "But you two should head back now. I can take it from here on my own.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA6E"
        },
        [10104604] = {
          ContentES = "...Eh... ¡de ninguna manera!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104604,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "194BBA98",
          NextDialogue = 10104605,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"SpecialConfident_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "...Umm... no way!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA98"
        },
        [10104605] = {
          ContentES = "Esta Reina Demonio no puede largarse de la batalla y dejar que su {性别:pequeño secuaz|pequeña secuaz} piense menos de ella. ¡Psyche, también debes venir con nosotras!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104605,
          FacialId = {
