          SpeakNpcId = 200002,
          Subtitle = "This Demon King can't just scarper from the battle and let the little minion think less of her. Psyche, you should also come with us!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBAC2"
        },
        [10104606] = {
          Camera = "-28.857422,-67.701172,111.056641,0.000052,9.799764,-64.964821,40.000031,141.186768,false,Manual,8.987392",
          CameraBlendCurve = "easeInQuad",
          ContentES = "¿Yo...?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104606,
          FacialId = {
