          },
          FinalCamera = "1278.716797,2242.87793,1126.149414,0.000085,-21.600649,-103.932632,25.0,168.419693,false,DoNotOverride,5.0",
          GUID = "194BBB16",
          NextDialogue = 10104608,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.5},TargetPosition{"-44.302734,13.918945,72.365723,0.000042,12.799815,-75.562065,40.000027,260.261597,false,Manual,8.987392"},duration{0}},
CameraMoveTo{TargetPosition{"-31.933594,-11.705078,78.753418,0.000044,13.599787,-73.361298,40.000031,260.261597,false,Manual,8.987392"},duration{15}}
