            [1] = "200006:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBC12"
        },
        [10104614] = {
          Camera = "-3371.945312,1771.284668,1105.757324,0.000082,-14.000022,-33.965176,56.0,2477.148193,false,DoNotOverride,8.987392",
          ContentES = "…Muy bien entonces. Tengan cuidado, las dos.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104614,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "194BBC3C",
          LookAt = {
            [1] = "100001:n(200006)"
          },
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.9},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...Alright then. Be careful, both of you.",
          TalkActionId = {
            [1] = "200006:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBC3C"
        },
        [10104701] = {
          ContentES = "¿Está cerrada? ¡Mira cómo la derrumbo!",
          DialogueId = 10104701,
          Duration = 3,
          GUID = "194BCA82",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104702,
          SpeakNpcId = 200002,
          Subtitle = "It's locked? Watch me bash it open!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCA82"
        },
        [10104702] = {
          Content = "（头槌砸门声）",
          DialogueId = 10104702,
          DisableMouth = 1,
          Duration = 2,
          GUID = "194BCA83",
          NextDialogue = 10104703,
          Subtitle = "*Sound of headbutting the door*",
          VoiceName = "sfx/common/story/01/tietougong"
        },
        [10104703] = {
          ContentES = "…¡Ay!",
          DialogueId = 10104703,
          Duration = 2,
          GUID = "194BCAD6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104704,
          SpeakNpcId = 200002,
          Subtitle = "...Ouchie!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCAD6"
        },
        [10104704] = {
          ContentES = "Una puerta de este grosor probablemente resista la fuerza bruta.",
          DialogueId = 10104704,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCB00",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104705,
          SpeakNpcId = 100001,
          Subtitle = "A door this thick is probably impervious to brute force.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB00"
        },
        [10104705] = {
          ContentES = "Entonces busquemos alrededor a ver si hay otra entrada.",
          DialogueId = 10104705,
          Duration = 3,
          GUID = "194BCB2A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104706,
          SpeakNpcId = 200006,
          Subtitle = "Then let's look around to see if there's another way in.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB2A"
        },
        [10104706] = {
          ContentES = "Nieve, ¿te duele la cabeza? Déjame ayudarte—",
          DialogueId = 10104706,
          Duration = 3,
          GUID = "194BCB54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104707,
          SpeakNpcId = 200006,
          Subtitle = "Snow, does your head hurt? Let me help you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB54"
        },
        [10104707] = {
          ContentES = "…Listo, un pequeño soplo para aliviar el dolor.",
          DialogueId = 10104707,
          Duration = 3,
          GUID = "194BCB7E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104708,
          SpeakNpcId = 200006,
          Subtitle = "...There, a little puff to ease the pain.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB7E"
        },
        [10104708] = {
          ContentES = "Oooh... eres tan amable. Cuando esta Reina Demonio conquiste este lugar, te nombraré—",
          DialogueId = 10104708,
          Duration = 3,
          GUID = "194BCBA8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104709,
          SpeakNpcId = 200002,
          Subtitle = "Awww... you're so nice. When this Demon King conquers this place, I'll appoint you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBA8"
        },
        [10104709] = {
          ContentES = "“La gentil maga de capa verde, sabia maestra del Phoxene, primera Gran Duquesa de la Mina de Glevum”",
          DialogueId = 10104709,
          Duration = 3,
          GUID = "194BCBD2",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104710,
          SpeakNpcId = 200002,
          Subtitle = "\"The Gentle Green-Cloaked Mage, the Wise Master of Phoxene, the Inaugural Grand Duke of Glevum Pit\"!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBD2"
        },
        [10104710] = {
          ContentES = "(Yo era Duque de las Alcantarillas... ¿Es un Gran Duque un rango superior al de Duque?)",
          DialogueId = 10104710,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCBFC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104711,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I was the Duke of the Sewers... Is a grand duke a higher rank than a duke?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBFC"
        },
        [10104711] = {
          ContentES = "(¿Por qué Psyche tiene un título más alto que el mío? Espera, ¿por qué estoy pensando tan seriamente en esto otra vez?)",
          DialogueId = 10104711,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCC26",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(How come Psyche gets a higher title than me? Hold on, why am I seriously mulling this over again?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCC26"
        },
        [10104801] = {
          ContentES = "“Guiado por Nieve la Reina Demonio, {性别:el pequeño secuaz|la pequeña secuaz} que acaba de llegar desde lejos a Lago Helado se ha convertido en {性别:un brillante Phoxcazador|una brillante Phoxcazadora} en solo un día.”",
          DialogueId = 10104801,
          GUID = "194BDAEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104802,
          SpeakNpcId = 200002,
          Subtitle = "\"Guided by Snow the Demon King, the little minion who just arrived in Icelake from afar has become a brilliant Phoxhunter in a mere day.\"",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDAEA"
        },
        [10104802] = {
          ContentES = "¡Una nueva página en la leyenda de esta Reina Demonio!",
          DialogueId = 10104802,
          GUID = "194BDB14",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104803,
          SpeakNpcId = 200002,
          Subtitle = "A new chapter in the legend of this Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB14"
        },
        [10104803] = {
          ContentES = "“{性别:Phoxcazador|Phoxcazadora}” es un nombre genial... ¿De verdad cazan algo llamado Phox?",
          DialogueId = 10104803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDB3E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104804,
          SpeakNpcId = 100001,
          Subtitle = "\"Phoxhunter\" is a cool name... Do they all hunt something called Phox?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB3E"
        },
        [10104804] = {
          ContentES = "¡No! Los Phoxcazadores hoy en día son en realidad cazadores de recompensas. En el pasado, tenía algo que ver con el Phoxene.",
          DialogueId = 10104804,
          GUID = "194BDB68",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104805,
          SpeakNpcId = 200002,
          Subtitle = "Nah! Phoxhunters nowadays are actually bounty hunters. It has something to do with Phoxene a long time ago.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB68"
        },
        [10104805] = {
          ContentES = "Es cierto, escuché que solía referirse a una profesión que nació aquí mismo en Lago Helado.",
          DialogueId = 10104805,
          GUID = "194BDB92",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104806,
          SpeakNpcId = 200006,
          Subtitle = "Right, I heard it used to refer to a profession that originated right here in Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB92"
        },
        [10104806] = {
          ContentES = "Aparentemente, es porque en las Montañas Vidofnir, las vetas del Árbol Celestial estaban llenas de Phoxene que se podía vender a buen precio...",
          DialogueId = 10104806,
          GUID = "194BDBBC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104807,
          SpeakNpcId = 200006,
          Subtitle = "It seemed to all start with the rich Heaventree veins in the Vidofnir Mountains, and the Phoxene on them could be sold for a good price...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBBC"
        },
        [10104807] = {
          ContentES = "¡Exacto! Hace mucho tiempo, muchas personas se arriesgaban a ir en encargos solo por el Phoxene.",
          DialogueId = 10104807,
          GUID = "194BDBE6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104808,
          SpeakNpcId = 200002,
          Subtitle = "Exactly! So, a long, long time ago, many people braved the risks of collecting Phoxene for money.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBE6"
        },
        [10104808] = {
          ContentES = "Pero luego, los grandes comerciantes y el Imperio tomaron el control de las minas, y la gente común ya casi no tenía acceso al Phoxene...",
          DialogueId = 10104808,
          GUID = "194BDC10",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104815,
          SpeakNpcId = 200006,
          Subtitle = "But then the big merchants and the Empire took over the mines around here, and ordinary folk hardly had a chance with Phoxene anymore...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC10"
        },
        [10104809] = {
          ContentES = "Mientras que los Phoxcazadores, que vivían de los encargos, siguieron como profesión. Solo que los tipos de encargos cambiaron mucho desde entonces.",
          DialogueId = 10104809,
          GUID = "194BDC3A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104810,
          SpeakNpcId = 200002,
          Subtitle = "While Phoxhunters, who lived off commissions, remained as a profession. It's just that the types of commissions changed a lot since then.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC3A"
        },
        [10104810] = {
          ContentES = "Hay grandes, como proteger la ciudad de las garras de los Filthoids, y pequeñas, como recuperar pan recién horneado de la boca de un perro...",
          DialogueId = 10104810,
          GUID = "194BDC64",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104811,
          SpeakNpcId = 200002,
          Subtitle = "There are big ones like protecting the city from the claws of Filthoids, and little ones like getting freshly baked bread back from a dog's mouth...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC64"
        },
        [10104811] = {
          ContentES = "¿Pelear con perros por pan?",
          DialogueId = 10104811,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDC8E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104812,
          SpeakNpcId = 100001,
          Subtitle = "Fighting dogs for bread?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC8E"
        },
        [10104812] = {
          ContentES = "Y algunos encargos aún más aterradores, como asegurarse de que alguien que no te gusta nunca más aparezca...",
          DialogueId = 10104812,
          GUID = "194BDCB8",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104813,
          SpeakNpcId = 200002,
          Subtitle = "And some even more terrifying commissions like making sure a certain someone you don't like never shows up again...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCB8"
        },
        [10104813] = {
          ContentES = "Pero para cuando vayas al Asfódelo, ¿no habrá ya sido devorado el pan por el perro?",
          DialogueId = 10104813,
          GUID = "194BDCE2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104814,
          SpeakNpcId = 200006,
          Subtitle = "But by the time you make a trip down to The Asphodel, wouldn't the bread have been gobbled up by the dog already?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCE2"
        },
        [10104814] = {
          ContentES = "¡Dejen de contar historias de perros!",
          DialogueId = 10104814,
          GUID = "194BDD0C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "You're both missing the point here!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDD0C"
        },
        [10104815] = {
          ContentES = "Luego, las vetas se agotaron poco a poco, como aquí en la Mina de Glevum...",
          DialogueId = 10104815,
          GUID = "194BDC11",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104816,
          SpeakNpcId = 200006,
          Subtitle = "After that, the local veins gradually ran dry, including this Glevum Pit...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC11"
        },
        [10104816] = {
          ContentES = "¡Sí, qué lástima! De lo contrario, mi {性别:pequeño secuaz|pequeña secuaz} habría hecho una fortuna con el Phoxene.",
          DialogueId = 10104816,
          GUID = "194BDC12",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104809,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, what a pity! Otherwise my little minion could have made a fortune selling Phoxene.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC12"
        },
        [10104901] = {
          ContentES = "¿Todo bien?",
          DialogueId = 10104901,
          ExStoryInfo = "Player",
          GUID = "194BEB52",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104902,
          SpeakNpcId = 100001,
          Subtitle = "Everything alright?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB52"
        },
        [10104902] = {
          ContentES = "¡...!",
          DialogueId = 10104902,
          GUID = "194BEB7C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104903,
          SpeakNpcId = 200006,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB7C"
        },
        [10104903] = {
          ContentES = "No veía nada hace un momento y al final lo asusté... ¡Perdón!",
          DialogueId = 10104903,
          GUID = "194BEBA6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104904,
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10104904] = {
          ContentES = "¿Te sientes mejor ahora?",
          DialogueId = 10104904,
          ExStoryInfo = "Player",
          GUID = "194BEBD0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104905,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling better now?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBD0"
        },
        [10104905] = {
          ContentES = "Sí, creo que ahora estoy bien.",
          DialogueId = 10104905,
          GUID = "194BEBFA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10104906,
          SpeakNpcId = 200006,
          Subtitle = "Yeah, I think I'm fine now.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBFA"
        },
        [10104906] = {
          ContentES = "Bien. Si puedes luchar, entonces enfrentémonos a esa bestia {性别:juntos|juntas}.",
          DialogueId = 10104906,
          ExStoryInfo = "Player",
          GUID = "194BEC24",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104907,
          SpeakNpcId = 100001,
          Subtitle = "Great. If you're in the condition to fight, let's take on this monster together.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC24"
        },
        [10104907] = {
          ContentES = "¡Claro! Haré todo lo posible para apoyarte.",
          DialogueId = 10104907,
          GUID = "194BEC4E",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Sure! I'll do my best to support you.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC4E"
        },
        [10105001] = {
          ContentES = "Dicen que incluso las bestias más feroces pueden ser derribadas si se les apunta a sus <H>puntos débiles</>...",
          DialogueId = 10105001,
          GUID = "194BFBB9",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105002,
          SpeakNpcId = 200006,
          Subtitle = "They say even the fiercest beasts can be brought down by targeting their weaknesses...",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBB9"
        },
        [10105002] = {
          ContentES = "¡Debe ser lo mismo con este Filthoid! Mantengámonos calmados y busquemos su punto débil.",
          DialogueId = 10105002,
          GUID = "194BFBBA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It must be the same with this Filthoid! Let's take a breath and find its weakness.",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBBA"
        },
        [10105101] = {
          ContentES = "Se está volviendo más lento. {nickname}, ¡<H>las partes que parecen sus hombros</> son sus puntos débiles!",
          DialogueId = 10105101,
          ExStoryInfo = "Player",
          GUID = "194C0C4C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It's slowing down. Looks like those shoulder-looking parts are its weakness!",
          VoiceName = "voice/$Locale$/story/1002/101051/194C0C4C"
        },
        [10105201] = {
          ContentES = "¡Se ha detenido! ¡Ahora es nuestra oportunidad!",
          DialogueId = 10105201,
          GUID = "194C1C8A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105202,
          SpeakNpcId = 200006,
          Subtitle = "It's stopped — now's our chance!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1C8A"
        },
        [10105202] = {
          ContentES = "¡Perfecto...!",
          DialogueId = 10105202,
          GUID = "194C1CB4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Great...!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1CB4"
        },
        [10105301] = {
          ContentES = "Cristal estelar... ¡Miren su belleza! No es de extrañar que todos quieran un pedazo de él.",
          DialogueId = 10105301,
          GUID = "194C2CF2",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "Crystallo of Stella... Look at its beauty! No wonder everyone wants a piece of it.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2CF2"
        },
        [10105302] = {
          ContentES = "Qué alboroto acabo de escuchar. ¿Entonces fueron ustedes los que derrotaron a esa cosa gigante? Impresionante.",
          DialogueId = 10105302,
          GUID = "194C2D1C",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "What a commotion I just heard. So it was you guys that took out that giant thing? Impressive.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2D1C"
        },
        [10105401] = {
          Camera = "-29.328125,-255.251953,164.21875,0.001081,-14.107393,94.226692,50.000008,544.145996,false,Manual,5.0",
          ContentES = "¡¿Outsider!? ¿Cómo es que el Cristal estelar está en tus manos? Fue mi {性别:pequeño secuaz|pequeña secuaz} quien lo tuvo primero—",
          DialogueId = 10105401,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "200002:Angry01"
          },
          FinalCamera = "-3.181641,-258.998047,197.030273,0.001091,-23.507626,104.626007,50.000008,311.108795,false,Manual,5.0",
          GUID = "194C3D5A",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "200006:n(200021)",
            [3] = "200061:n(200021)",
            [4] = "200002:n(200021)"
          },
          NextDialogue = 10105402,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201007,
            [4] = 201005,
            [5] = 301004,
            [6] = 406001,
            [7] = 303004,
            [8] = 201009
          },
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0033_story_humour"}},
SEQ{
MoveTo{ActorId{200002},MoveSpeed{201},TargetPoint{"P101054_BaiMove1"}},
PlayAnimation{ActorId{200002},AnimationId{"Angry01_Start"},Duration{1}}
},
PARA{
MoveTo{ActorId{200021},MoveSpeed{30},TargetPoint{"P101054_AoteMove1"}},
LookAt{_delay{2.5},LookAtDescription{"200021:n(200002)"}}
},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Outsider!? How come the Crystallo is in your hands? It was my little minion who first—",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3D5A"
        },
        [10105402] = {
          Camera = "-72.519531,598.007812,133.294922,0.001335,-3.398285,-86.062561,30.0,755.136902,false,Manual,8.0",
          ContentES = "Estaba justo ahí, sin ningún nombre sobre él, ¿verdad? Vamos, en nuestro trabajo no hay eso de “el que llega primero, sirve primero”.",
          DialogueId = 10105402,
          FacialId = {
