          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Después del Despertar, algunos Charons se vuelven mucho más fuertes, como tú, y pueden usar una magia especial. ¡Se les llama “Daimons”!",
          DialogueId = 10105438,
          ExStoryInfo = "Player",
          FinalCamera = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,37.0,124.912491,false,Manual,8.0",
          GUID = "194C429A",
          NextDialogue = 10105439,
          RelatedWikiId = {
