]],
          SpeakNpcId = 200021,
          Subtitle = "I'll be back a bit late, might miss The Asphodel's closing time. Come and find me at my place — it's among those shabby houses south of the city, the one with a little bird drawn on the door.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43EA"
        },
        [10105447] = {
          Camera = "-9.882812,4.484375,146.6875,0.000026,1.206198,-92.395676,50.0,241.293564,false,Manual,4.0",
          ContentES = "Y ven {性别:solo|sola}, no traigas a nadie que no sea necesario.",
          DialogueId = 10105447,
          FinalCamera = "-9.882812,4.484375,146.6875,0.000026,1.406199,-92.39563,52.0,241.293564,false,Manual,4.0",
          GUID = "194C4414",
          LookAt = {
            [1] = "200021:n(200006)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}},\n",
          SpeakNpcId = 200021,
          Subtitle = "And come alone — don't bring anyone unrelated.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4414"
        },
        [10105501] = {
          ContentES = "¡Parece que hay un camino por allá! Vamos, este lugar me da escalofríos...",
          DialogueId = 10105501,
          GUID = "194C4DC1",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105502,
          SpeakNpcId = 200002,
          Subtitle = "Looks like there's a path over there! Let's get out of here — this place gives me the creeps...",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC1"
        },
        [10105502] = {
          ContentES = "...Espera, cuando dijo “nadie que no sea necesario”, no se refería a mí, ¿verdad?",
          DialogueId = 10105502,
          GUID = "194C4DC2",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Wait, when he said \"anyone unrelated,\" he wasn't talking about me, was he?",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC2"
        },
        [10105601] = {
          ContentES = "Este camino se siente diferente al que pasamos antes, casi como si alguien lo hubiera excavado a mano.",
          DialogueId = 10105601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5E2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105602,
          SpeakNpcId = 100001,
          Subtitle = "This trail feels different from the one we passed through earlier, almost as if it's been hand-dug by someone.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E2A"
        },
        [10105602] = {
          ContentES = "¡Es verdad! Incluso hay varios picos tirados por ahí... ¡Parece que unos aventureros ya pasaron por aquí!",
          DialogueId = 10105602,
          Duration = 3,
          GUID = "194C5E54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105603,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, there are even pickaxes lying around here... Looks like other adventurers have been here before us!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E54"
        },
        [10105603] = {
          ContentES = "Eh, Psyche, ¿por qué estás tan pálida? No has dicho nada desde hace rato.",
          DialogueId = 10105603,
          Duration = 3,
          GUID = "194C5E7E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105604,
          SpeakNpcId = 200002,
          Subtitle = "You okay, Psyche? You look pale, and you've been awfully quiet for a while.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E7E"
        },
        [10105604] = {
          ContentES = "¿Eh, yo? ¿De verdad?",
          DialogueId = 10105604,
          Duration = 3,
          GUID = "194C5EA8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10105605,
          SpeakNpcId = 200006,
          Subtitle = "Ah, h-have I?",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EA8"
        },
        [10105605] = {
          ContentES = "Supongo que todavía estoy afectada por ese monstruo. Sigo preguntándome si alguna vez pudo haber sido...",
          DialogueId = 10105605,
          Duration = 3,
          GUID = "194C5ED2",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105606,
          SpeakNpcId = 200006,
          Subtitle = "Guess I still reelling from that monster. I keep wondering if it could have once been...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5ED2"
        },
        [10105606] = {
          ContentES = "¡Tranquila! ¡Estamos aquí contigo!",
          DialogueId = 10105606,
          Duration = 3,
          GUID = "194C5EFC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105607,
          SpeakNpcId = 200002,
          Subtitle = "Relax! We're right here with you!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EFC"
        },
        [10105607] = {
          ContentES = "Ese tipo dijo que mi {性别:pequeño secuaz|pequeña secuaz} es {性别:un|una} “Daimon” fuerte, ¿verdad? Así que, aunque vinieran diez Filthoids más, no serían rivales para {性别:él|ella}.",
          DialogueId = 10105607,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F26",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105608,
          SpeakNpcId = 200002,
          Subtitle = "That Outsider said that my little minion is a strong \"Daimon,\" right? So even if ten more Filthoids came at us, they'd be no match for {性别:him|her}.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F26"
        },
        [10105608] = {
          ContentES = "Ya basta... estoy al límite, y Psyche solo estaba fingiendo confianza.",
          DialogueId = 10105608,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F50",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105609,
          SpeakNpcId = 100001,
          Subtitle = "Cut it out. I'm nearly spent, and Psyche was just bluffing.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F50"
        },
        [10105609] = {
          ContentES = "Lo importante es que ustedes estén bien. Tal vez no debería haberos metido en todo esto...",
          DialogueId = 10105609,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F7A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105610,
          SpeakNpcId = 100001,
          Subtitle = "I'm just relieved you're both safe... Maybe I shouldn't have involved you two in such a dangerous event.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F7A"
        },
        [10105610] = {
          ContentES = "¡No, para nada! Estoy muy feliz de haber participado en una aventura así.",
          DialogueId = 10105610,
          Duration = 3,
          GUID = "194C5FA4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105611,
          SpeakNpcId = 200006,
          Subtitle = "No, not at all! I'm really happy that I took part in such an adventure.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FA4"
        },
        [10105611] = {
          ContentES = "Jamás imaginé salir de mi ciudad con {性别:amigos|amigas}, explorar lo desconocido, meterme en líos y enfrentar {性别:juntos|juntas} a enemigos aterradores.",
          DialogueId = 10105611,
          Duration = 3,
          GUID = "194C5FCE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105612,
          SpeakNpcId = 200006,
          Subtitle = "I never thought I'd get out of town with friends, explore unknown places, get in trouble, and fight evil enemies together.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FCE"
        },
        [10105612] = {
          ContentES = "…Ahora que lo pienso, todavía me siento un poco mareada, como si hubiera estado soñando despierta.",
          DialogueId = 10105612,
          Duration = 3,
          GUID = "194C5FF8",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105613,
          SpeakNpcId = 200006,
          Subtitle = "Now that I think about it, it all feels so unreal, like living a daydream.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FF8"
        },
        [10105613] = {
          ContentES = "¿Ves? ¡Psyche también está de acuerdo conmigo!",
          DialogueId = 10105613,
          Duration = 3,
          GUID = "194C6022",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10105614,
          SpeakNpcId = 200002,
          Subtitle = "See? Psyche agrees with me!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C6022"
        },
        [10105614] = {
          ContentES = "...",
          DialogueId = 10105614,
          Duration = 3,
          GUID = "194C604C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C604C"
        },
