        },
        [10105814] = {
          Camera = "-248.442383,-210.168945,153.489746,0.000127,-3.200374,44.998043,35.000008,345.865082,false,Manual,5.41403",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Ella no es su hija. Y aunque lo fuera, no tienen por qué negarle tan poca libertad. ¿Sabes lo feliz que estuvo durante nuestro pequeño viaje?",
