        [10106202] = {
          Camera = "-6.599731,-145.632812,140.769531,0.000156,-3.591819,17.001183,30.0,555.360596,false,DoNotOverride,4.01182",
          ContentES = "... ¿{性别:Señor|Señora}, está bien?",
          DialogueId = 10106202,
          ExStoryInfo = "Player",
          FinalCamera = "-14.872528,-148.162109,141.300781,0.000156,-3.591819,17.001348,30.000002,555.360596,false,DoNotOverride,4.01182",
          GUID = "194CC0C4",
          LookAt = {
            [1] = "100001:n(200020)"
          },
          NextDialogue = 10106203,
          SpeakNpcId = 200020,
          Subtitle = "What's wrong, {性别:sir|miss}?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC0C4"
        },
        [10106203] = {
          Camera = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
          ContentES = "Nada. Es solo que, el pastel está bastante dulce, lo que me recuerda a... mi familia. Ella solía sazonar la comida con mucha azúcar.",
          DialogueId = 10106203,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "273.907379,326.357422,122.730469,0.000156,-0.389526,-86.226807,50.000008,393.914001,false,Manual,3.873447",
          GUID = "194CC0EE",
          NextDialogue = 10106204,
          Scripts = [[
SEQ{
LookAt{_delay{2.5},LookAtDescription{"100001:n(200020)"}},
PlayFacial{ActorId{100001},FacialId{"Sad01"}},
LookAt{_delay{3.5},LookAtDescription{"100001:p(P101060Cake)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Nothing. It's just that, the cake is quite sweet, which reminds me of... my family. She used to season food with lots of sugar.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC0EE"
        },
        [10106204] = {
          ContentES = "En la isla en la que crecimos había mucha pesca y sal, pero el azúcar era un lujo. Así que, cuando éramos {性别:pequeños|pequeñas}, nunca lo probamos.",
          DialogueId = 10106204,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CC118",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106204.T_Story_Recall_10106204'",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10106205,
          SpeakNpcId = 100001,
          Subtitle = "The island we grew up on had plenty of fish and salt, but sugar was a rarity. So, when we were little, we never really got to have any.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC118"
        },
        [10106205] = {
          Camera = "225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876",
          ContentES = "Ella es solo unos años mayor que yo, pero desde pequeña empezó a trabajar como ayudante para el pescador vecino.",
          DialogueId = 10106205,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194CC142",
          NextDialogue = 10106206,
          Scripts = [[
PARA{
LookAt{_delay{1.5},LookAtDescription{"100001:p(P101062)"}},
SEQ{
CameraMoveTo{_delay{0.8},TargetPosition{"225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876"},duration{0}},
CameraMoveTo{TargetPosition{"225.539108,-21.537109,190.847656,0.000213,-25.98712,-68.410812,50.0,111.523781,false,Manual,7.19876"},duration{8}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "She's only a few years older than me, but from a young age, she began working as a helper for the neighbouring fisherman.",
          VoiceName = "voice/$Locale$/story/1002/101062/194CC142"
        },
        [10106206] = {
          Camera = "-36.164703,179.021484,97.113281,0.000154,3.212634,-35.412941,35.000008,159.590256,false,DoNotOverride,19.0",
          ContentES = "Una vez, ese pescador consiguió algunos suministros del Imperio, incluidos dos tarros de azúcar, y ella intercambió la mitad de su salario mensual por un pequeño tarro.",
          DialogueId = 10106206,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-41.269623,171.851562,97.113281,0.000154,3.212634,-35.412941,35.000008,159.590256,false,DoNotOverride,19.0",
          GUID = "194CC16C",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10106207,
          Scripts = [[
PARA{
LookAt{_delay{0.1},LookAtDescription{"100001:n(200021)"}},
LookAt{_delay{1.1},LookAtDescription{"100001:n(200020)"}},
PlayAnimation{_delay{5.1},ActorId{100001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{5.5},ActorId{200021},AnimationId{"Confident_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "One time, that fisherman somehow got his hands on some imperial supplies, including two jars of sugar, and she traded half a month's wages for one small jar.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC16C"
        },
        [10106207] = {
          Camera = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
          ContentES = "Fue la primera vez que consiguió azúcar, y no sabía cómo usarlo. Solo sabía que era algo valioso y delicioso, así que lo vertió todo en una sopa de pescado.",
          DialogueId = 10106207,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "284.692383,307.464844,132.414062,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447",
          GUID = "194CC196",
          LookAt = {
            [1] = "100001:n(200020)"
          },
          NextDialogue = 10106208,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.1},ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{5.1},ActorId{100001},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{9.1},ActorId{100001},AnimationId{"ScratchHead_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "It was the first time she got hold of any sugar, and she didn't know how to use it. Simply knowing that it was something valuable and delicious, she poured it all into the fish stew.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC196"
        },
        [10106208] = {
          Camera = "382.73764,-248.964844,152.820312,0.0,0.0,-179.999969,40.0,393.914001,false,Manual,3.873447",
          ContentES = "Cuando crecimos y empezamos a ganar más, el azúcar ya no era un lujo. Pero cada vez que cocinaba, todavía ponía mucho azúcar por costumbre.",
          DialogueId = 10106208,
          ExStoryInfo = "Player",
          FinalCamera = "328.098663,-248.964844,152.820312,0.0,0.0,-179.999969,40.0,393.914001,false,Manual,3.873447",
          GUID = "194CC1C0",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10106209,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"100001:n(100001)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "By the time we grew up and started earning more, sugar wasn't such a luxury anymore. But whenever she cooked, she'd still add a lot of sugar out of habit.",
          TalkActionId = {
            [1] = "200021:Confident_End",
            [2] = "100001:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC1C0"
        },
        [10106209] = {
          Camera = "96.518188,-136.830078,134.59375,0.000123,1.799413,15.609182,35.000008,213.622009,false,Manual,7.38829",
          ContentES = "Dios mío, eso suena horrible... Casi puedo oler ese olor a pescado, dulce y nauseabundo. Ella te debe una disculpa, o al menos, una disculpa al azúcar y al pescado.",
          DialogueId = 10106209,
          FacialId = {
            [1] = "100001:None",
            [2] = "200021:Shock02"
          },
          GUID = "194CC1EA",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106210,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{200021},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{3.1},ActorId{200021},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Goodness, that sounds horrible... I can almost smell that fishy, sickly-sweet odour. She owes you an apology, or at the very least, she owes the sugar and the fish an apology.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC1EA"
        },
        [10106210] = {
          Camera = "96.518188,-136.830078,134.59375,0.000123,1.799413,15.609182,35.000008,213.622009,false,Manual,7.38829",
          ContentES = "No, Outsider, no has entendido la historia.",
          DialogueId = 10106210,
          FacialId = {
            [1] = "200021:None",
            [2] = "200020:Confident01"
          },
          FinalCamera = "90.803986,-143.320312,134.382812,0.000123,0.599335,20.609505,35.000008,213.622009,false,Manual,7.38829",
          GUID = "194CC214",
          LookAt = {
            [1] = "200020:n(200021)"
          },
          NextDialogue = 10106211,
          Scripts = "LookAt{_delay{0.5},LookAtDescription{\"200021:n(200020)\"}}",
          SpeakNpcId = 200020,
          Subtitle = "No, Outsider, you're missing the point of the story.",
          TalkActionId = {
            [1] = "200020:DisagreeHead",
            [2] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC214"
        },
        [10106211] = {
          Camera = "247.410675,-57.9375,168.519531,0.000134,-20.200529,35.800228,50.000008,111.523781,false,Manual,7.19876",
          ContentES = "Aquella muchacha que siempre ponía demasiado azúcar... también era una maga. Porque, a los ojos de {nickname}, todo lo que venía de ella... era precioso. Incluso los platos tan dulces que eran imposibles de comer.",
          DialogueId = 10106211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200020:Happy02"
          },
          GUID = "194CC23E",
          LookAt = {
            [1] = "200020:n(100001)",
            [2] = "100001:n(200020)"
          },
          NextDialogue = 10106212,
          Scripts = [[
PARA{
CameraMoveTo{_delay{10},TargetPosition{"225.539108,-21.537109,188.570312,0.000213,-25.98712,-68.410789,50.0,111.523781,false,Manual,7.19876"},duration{0}},
PlayFacial{_delay{10},ActorId{100001},FacialId{"Ahaha02"}}
}]],
          SpeakNpcId = 200020,
          Subtitle = "I believe that lady who always used a lot of sugar was also a great magician. So in 's eyes, everything related to her was wonderful, even the unbearably sweet meals.",
          TalkActionId = {
            [1] = "200020:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC23E"
        },
        [10106212] = {
          Camera = "90.803986,-143.320312,134.382812,0.000123,0.599335,20.609505,35.000008,213.622009,false,Manual,7.38829",
          ContentES = "Está bien... Fina tiene razón. Pero entonces, ¿dónde está ella ahora? Tal vez puedas llevarle un poco de pastel, para que sepa cómo saben los dulces normales.",
          DialogueId = 10106212,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194CC268",
          NextDialogue = 10106213,
          Scripts = [[
PARA{
LookAt{_delay{2.5},LookAtDescription{"200021:n(100001)"}},
LookAt{_delay{3.5},LookAtDescription{"200020:n(100001)"}},
LookAt{_delay{3.5},LookAtDescription{"100001:n(200021)"}}
}
]],
          SpeakNpcId = 200021,
          Subtitle = "Okay, whatever Fina says. So where is that girl now? Perhaps you can bring her some cake, let her know what normal sweets taste like.",
          TalkActionId = {
            [1] = "200020:Explain02_End",
            [2] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC268"
        },
        [10106213] = {
          Camera = "325.076691,-13.257812,187.945312,0.000222,-23.38699,-116.208672,50.0,136.090439,false,Manual,7.19876",
          ContentES = "... Nos separamos. Ayer... o tal vez mucho antes. Ya no lo recuerdo.",
          DialogueId = 10106213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200020:Shock02"
          },
          FinalCamera = "332.233704,1.279297,194.9375,0.000222,-23.38699,-116.208672,50.0,136.090439,false,Manual,7.19876",
          GUID = "194CC292",
          LookAt = {
            [1] = "200020:n(100001)",
            [2] = "200021:n(100001)"
          },
          NextDialogue = 10106214,
          Scripts = [[
PARA{
SEQ{
LookAt{_delay{2.5},LookAtDescription{"100001:n(100001)"},Duration{2}},
PlayAnimation{_delay{2.5},ActorId{100001},AnimationId{"DisagreeHead"},Duration{0.1}}
},
CameraMoveTo{_delay{9},TargetPosition{"247.410675,-57.9375,168.519531,0.000134,-20.200529,35.800228,50.000008,111.523781,false,Manual,7.19876"},duration{0}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "We got separated and lost each other yesterday... or maybe longer ago. I'm not sure.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC292"
        },
        [10106214] = {
          Camera = "-172.923157,500.876953,222.921875,0.000144,-7.79205,-46.00008,30.0,555.360596,false,Manual,2.016998",
          ContentES = "...",
          DialogueId = 10106214,
          Duration = 2,
          FacialId = {
