          },
          FinalCamera = "-181.140259,509.382812,224.539062,0.000144,-7.79205,-46.00008,30.0,555.360596,false,Manual,2.016998",
          GUID = "194CC2BC",
          NextDialogue = 10106215,
          SpeakNpcId = 200021,
          Subtitle = "...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC2BC"
        },
        [10106215] = {
          Camera = "284.721039,-61.648438,146.964844,0.00016,-12.991326,53.627674,45.0,103.803047,false,Manual,22.0",
          ContentES = "¡Entonces tienes que encontrarla! Porque la familia es como las flores y los árboles, la nieve y el viento: pase lo que pase, deben permanecer juntos. ¡Tienes que encontrarla!",
          DialogueId = 10106215,
          FacialId = {
            [1] = "200020:Disappoint01"
          },
          GUID = "194CC2E6",
          LookAt = {
            [1] = "100001:n(200020)"
          },
          NextDialogue = 10106216,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4},TargetPosition{"25.241394,353.103516,128.082031,0.000249,-0.186608,-55.60635,50.0,304.058929,false,DoNotOverride,7.19876"},duration{0}},
CameraMoveTo{TargetPosition{"197.603165,430.265625,128.082031,0.000251,-1.186663,-77.204803,50.000008,304.058929,false,DoNotOverride,7.19876"},duration{15}}
}]],
          SpeakNpcId = 200020,
          Subtitle = "Then you must find her...! Because family's like flowers and trees, snow and wind — they should be together no matter what. You have to find her.",
          TalkActionId = {
            [1] = "200020:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC2E6"
        },
        [10106216] = {
          Camera = "248.2005,27.082031,94.667969,0.000281,16.61274,-81.408127,50.0,156.400558,false,Manual,7.19876",
          ContentES = "Sí. La encontraré. Lo juro.",
          DialogueId = 10106216,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194CC310",
          NextDialogue = 10106217,
          SpeakNpcId = 100001,
          Subtitle = "Yes, I will. I WILL find her.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC310"
        },
        [10106217] = {
          ContentES = "Entonces, Outsider... necesito dinero. Una parte para alojarme y reunir información, y otra guardada por si tengo que salir de inmediato a buscar a mi familia.",
          DialogueId = 10106217,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CC33A",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106218,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100001:n(200021)"}},
TurnTo{TurnToDescription{"100001:n(200021)"}},
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "So, Outsider, I need money — for accommodation, information gathering, and some extra set aside in case I need to set off right away to find my family.",
          TalkActionId = {
            [1] = "200020:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC33A"
        },
        [10106218] = {
          Camera = "228.775543,-141.707031,208.621094,0.000132,-21.591455,46.226685,45.0,103.803047,false,DoNotOverride,22.0",
          ContentES = "... Fina, es hora de que descanses. {nickname} y yo tenemos que hablar de asuntos más serios, cosas de los Phoxcazadores.",
          DialogueId = 10106218,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CC364",
          LookAt = {
            [1] = "200021:n(200020)",
            [2] = "100001:n(200020)"
          },
          NextDialogue = 10106219,
          Scripts = [[
PARA{
LookAt{_delay{2.5},LookAtDescription{"200021:n(200020)"}},
LookAt{_delay{3},LookAtDescription{"200020:n(200021)"}}
}
]],
          SpeakNpcId = 200021,
          Subtitle = "...Time for bed, Fina. I have other matters to discuss with  — Phoxhunter stuff.",
          VoiceName = "voice/$Locale$/story/1002/101062/194CC364"
        },
        [10106219] = {
          Camera = "133.667862,436.431641,156.152344,0.000004,-4.200197,-71.19426,40.0,311.105316,false,DoNotOverride,1.670611",
          ContentES = "Está bien... Buenas noches a los dos.",
          DialogueId = 10106219,
          FacialId = {
            [1] = "200020:Happy02"
          },
          FinalCamera = "128.757187,450.847656,157.261719,0.000005,-4.200197,-71.194244,40.000011,311.105316,false,DoNotOverride,1.670611",
          GUID = "194CC38E",
          LookAt = {
            [1] = "200021:n(200020)",
            [2] = "200020:n(200021)"
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200020:n(100001)\"}}",
          SpeakNpcId = 200020,
          Subtitle = "Okay, goodnight then. Goodnight to you both.",
          TalkActionId = {
            [1] = "200020:AgreeHead"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC38E"
        },
        [10106301] = {
          Camera = "-6.289551,163.633789,182.636719,0.000162,-9.200067,-82.733803,30.0,315.887299,false,Manual,2.2",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "Pasemos a cosas serias. Hablo de lo que ocurrió hoy, en la Mina",
          DialogueId = 10106301,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "1.409424,177.989258,186.113281,0.000151,-7.200044,-80.799271,30.0,115.9599,false,Manual,2.4",
          GUID = "194CD102",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106302,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 201009,
            [3] = 201010,
            [4] = 301004,
            [5] = 201007,
            [6] = 405002
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0020_story_sanatorium\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Time to get down to business — I mean, about what happened at the pit today.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD102"
        },
        [10106302] = {
          Camera = "-134.704102,-202.952148,138.852539,0.000154,3.5,48.999954,35.0,313.251678,false,Manual,4.143779",
          ContentES = "Perdón por haber tomado tu Cristal estelar, tuve que hacerlo para que pudiéramos hablar a solas aquí.",
          DialogueId = 10106302,
          FacialId = {
            [1] = "200021:Confident01",
            [2] = "100001:Think01"
          },
          GUID = "194CD103",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextOptions = {
            [1] = 101063031,
            [2] = 101063032
          },
          Scripts = [[
PARA{
TurnTo{_delay{1},TurnToDescription{"200021:p(180)"}},
PlayAnimation{_delay{2},ActorId{200021},AnimationId{"DisagreeHead"},Duration{2}},
CameraMoveTo{_delay{8},TargetPosition{"-38.290527,76.382812,152.887695,0.00016,-1.800294,-79.190605,35.0,168.06105,false,Manual,3.5"},duration{0}},
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Sorry that I took your Crystallo — I had to do that so we could talk in private here.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD103"
        },
        [10106304] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
          ContentES = "No, está bien. Ese pequeño champiñón está lleno de vanidad, pero sabe lo que es importante. Lo que me preocupa es la chica de verde.",
          DialogueId = 10106304,
          FacialId = {
            [1] = "200021:Smile01",
            [2] = "100001:None"
          },
          GUID = "194CD104",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10106306,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{5},ActorId{200021},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Nah, she's fine. That little button mushroom's full of hot air, but she understands what's important. It's that girl in green I have reservations about.",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD104"
        },
        [10106305] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
          ContentES = "Si hablas de la chica de verde, entonces sí.",
          DialogueId = 10106305,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = "100001:None"
          },
          GUID = "194CD105",
          NextDialogue = 10106306,
          SpeakNpcId = 200021,
          Subtitle = "If you're talking about the girl in green, yes.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD105"
        },
        [10106306] = {
          ContentES = "La he visto entrar y salir de la Casa de Hypnos. No sé si es solo una huésped común o algún tipo de asistente de Henrik Ethelred.",
          DialogueId = 10106306,
          GUID = "194CD106",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106306.T_Story_Recall_10106306'",
          NextDialogue = 10106307,
          SpeakNpcId = 200021,
          Subtitle = "I've seen her going in and out of Hypnos' House. I don't know if she's just a regular lodger or some kind of assistant to Henrik Ethelred.",
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD106"
        },
        [10106307] = {
          Camera = "-134.704102,-202.952148,138.852539,0.000154,3.5,48.999954,35.0,313.47171,false,Manual,2.264544",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Voy a ser claro, no confío en Henrik Ethelred. Sospecho que está metido en asuntos turbios.",
          DialogueId = 10106307,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "-108.404053,-223.467773,138.852539,0.000162,3.899915,58.900612,35.000011,319.900421,false,Manual,2.264544",
          GUID = "194CD12C",
          NextDialogue = 10106308,
          SpeakNpcId = 200021,
          Subtitle = "I'll cut to the chase: I don't trust Henrik Ethelred — I suspect he's up to something shady.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD12C"
        },
        [10106308] = {
          Camera = "15.576416,24.124023,175.081543,-0.0,-10.199944,-103.000977,35.000008,120.127426,false,Manual,3.0",
          ContentES = "¿Asuntos... turbios... como qué?",
          DialogueId = 10106308,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "194CD12D",
          NextDialogue = 10106309,
          SpeakNpcId = 100001,
          Subtitle = "Something shady... like what?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD12D"
        },
        [10106309] = {
          Camera = "-129.019531,-207.28418,135.132324,0.000153,4.599757,50.60236,35.0,316.170074,false,Manual,2.264544",
          ContentES = "¿Sabes algo sobre el Cristal estelar, lo que él busca? Son piedras hermosas que eran populares por su aspecto, pero eso no es toda la historia. En algunos países, se usan para... propósitos medicinales.",
          DialogueId = 10106309,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "194CD1AA",
          NextDialogue = 10106310,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Explain01_Start"},Duration{2}},
PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{200021},AnimationId{"Talk03_Start"},Duration{1}}
},
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"-22.538086,-15.713867,168.216797,0.000161,1.399533,51.603157,35.000008,99.769196,false,Manual,2.264544"},duration{0}},
CameraMoveTo{TargetPosition{"-15.511475,-6.851562,168.493164,0.000161,1.399533,51.603806,35.000008,84.787651,false,Manual,2.264544"},duration{5}}
}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Do you know anything about the Crystallo of Stella — the stuff he's after? They're beautiful rocks that were popular for their looks, but that's not the whole story. In some countries, they're used for... medicinal purposes.",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1AA"
        },
        [10106310] = {
          Camera = "-801.484619,-220.195312,860.855957,0.000049,-21.199219,35.871891,30.000008,2029.508545,false,Manual,1.2",
          ContentES = "Hubo un caso grave de negligencia médica relacionado con el Cristal estelar en la provincia de Flagson. La mitad de la ciudad se sumió en el caos. Fue en ese momento cuando el comercio del Cristal estelar fue prohibido.",
          DialogueId = 10106310,
          FinalCamera = "-801.484619,-220.195312,902.421387,0.000049,-21.199219,35.871891,30.000008,2029.508545,false,Manual,1.2",
          GUID = "194CD1D4",
          NextOptions = {
            [1] = 10106311
          },
          RelatedWikiId = {
            [1] = 408005,
            [2] = 301004
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Talk03_End"},Duration{2}},
PlayAnimation{_delay{2},ActorId{200021},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "There was once a serious case of medical negligence involving Crystallo of Stella in Flagson Province, throwing half the city into chaos. That's when they slapped a ban on Crystallo trading.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1D4"
        },
        [10106311] = {
          ContentES = "Así que él infringe la prohibición. Había oído hablar de eso.",
          DialogueId = 10106311,
          GUID = "10106311.0",
          NextDialogue = 10106312,
          Subtitle = "He's violating the ban. I've heard about it."
        },
        [10106312] = {
          Camera = "0.102539,187.96582,195.69873,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2",
          ContentES = "Eso no es todo. ¿Cuántas personas en las calles de Lago Helado realmente pueden decir que tienen las manos limpias? Lo que realmente me preocupa son los rumores sobre la Casa de Hypnos.",
          DialogueId = 10106312,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "-0.895264,195.582031,197.388184,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2",
          GUID = "194CD1FE",
          NextDialogue = 10106313,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "That's not the half of it. How many folks on the streets of Icelake can truly claim clean hands? What really gets me are the rumours about the Hypnos' House.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1FE"
        },
        [10106313] = {
          Camera = "-2526.490234,772.758789,582.1875,0.000011,-9.199978,-15.202279,45.000023,2420.254639,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "La gente del vecindario dice que Henrik y sus huéspedes son una especie rara. Se mantienen alejados de los demás, y aunque lo llaman una posada, es Henrik quien <H>elige</> quién se queda.",
          DialogueId = 10106313,
          FinalCamera = "-2536.047363,737.591797,582.1875,0.000011,-9.199978,-15.202335,45.000023,2420.254639,false,Manual,1.2",
          GUID = "194CD228",
          NextDialogue = 10106314,
          SpeakNpcId = 200021,
          Subtitle = "People in the neighbourhood say that Henrik and his lodgers are a weird bunch. They keep to themselves, and though they call it an inn, Henrik's the one picking who stays.",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD228"
        },
        [10106314] = {
          Camera = "-118.642822,-24.229492,136.930176,0.000165,10.799492,27.794773,35.0,170.938126,false,Manual,1.623207",
          ContentES = "Algunos han echado un vistazo por dentro — los huéspedes son todos jóvenes menores de veinte años. Más extraño aún, los ves entrar, pero nunca salir. Nadie sabe qué les sucede.",
          DialogueId = 10106314,
          FinalCamera = "-87.214844,-7.525391,144.353027,0.000166,11.999521,27.99498,35.0,150.986908,false,Manual,1.623207",
          GUID = "194CD252",
          NextDialogue = 10106315,
          Scripts = [[
SEQ{
PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{_delay{2.5},ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{200021},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Some have peeked inside — the lodgers there are all young people under twenty. Stranger still, you see them go in but never out. No one knows where those young lodgers end up.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD252"
        },
        [10106315] = {
          Camera = "1.409424,177.989258,193.487305,0.000134,-12.400058,-82.534454,30.000002,263.612305,false,Manual,2.2",
          ContentES = "Yo también escuché rumores de “mansión embrujada”... pero dicho así, suena aún más...",
          DialogueId = 10106315,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194CD27C",
          NextDialogue = 10106316,
          SpeakNpcId = 100001,
          Subtitle = "Yes, I've heard some \"haunted house\" rumours as well, makes you wonder... But speaking of which—",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD27C"
        },
        [10106316] = {
          ContentES = "Por cierto, ¿por qué te interesa todo esto?",
          DialogueId = 10106316,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CD27D",
          NextDialogue = 10106317,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "How did you get onto this?",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD27D"
        },
        [10106317] = {
          Camera = "-118.512451,-182.769531,140.193848,0.000153,4.599757,50.000011,35.0,272.898132,false,Manual,2.264544",
          ContentES = "Hay un chico Phoxcazador con el que solía trabajar, llamado Hunt. Desapareció hace un mes, la última en verlo fue esa chica recicladora, justo fuera de la Casa de Hypnos.",
          DialogueId = 10106317,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD2A6",
          NextDialogue = 10106318,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"-637.433105,247.024414,212.966797,0.000224,14.600731,161.606003,15.000005,272.898132,false,DoNotOverride,2.264544"},duration{0}},
CameraMoveTo{TargetPosition{"-637.433105,247.024414,91.351562,0.000223,6.600879,161.406097,15.000005,272.898132,false,DoNotOverride,2.264544"},duration{12}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "There's this Phoxhunter boy I used to work with, named Hunt. He went missing a month ago, last seen by that scrap-picker girl — right outside the Hypnos' House.",
          TalkActionId = {
            [1] = "200021:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD2A6"
        },
        [10106318] = {
          Camera = "-599.96167,1241.567383,973.956787,0.000164,-31.200064,-54.605648,35.0,179.039703,false,DoNotOverride,7.148376",
          ContentES = "Hace unos días fui a enfrentarlo a Henrik. Incluso con mi daga bajo su garganta, se negó a decir dónde estaba Hunt.",
          DialogueId = 10106318,
          FacialId = {
            [1] = "200021:Sad01"
          },
          FinalCamera = "-650.708252,1312.987305,1027.01709,0.000164,-31.200064,-54.605648,35.000008,179.039703,false,DoNotOverride,7.148376",
          GUID = "194CD2D0",
          NextDialogue = 10106319,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"Sigh_End"},Duration{1}},
PlayAnimation{ActorId{200021},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{2.5},ActorId{200021},AnimationId{"Talk03_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"Angry01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Couple of days ago, I went over there and ended up in a blazing row with Henrik. Even with a dagger to his throat, he kept quiet about Hunt.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD2D0"
        },
        [10106319] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376",
          ContentES = "Se limitó a burlarse: “Tú sabes mejor que yo lo que le pasa a un Charon que se mete con un Sola. Sé que tienes una hermana. Será mejor que te mantengas al margen por su bien.”",
          DialogueId = 10106319,
          FinalCamera = "-57.103516,-124.65625,146.576172,0.000175,5.599648,57.998432,35.0,179.039703,false,Manual,7.148376",
          GUID = "194CD2FA",
          NextDialogue = 10106320,
          Scripts = [[
PARA{
PlayFacial{_delay{8.01},ActorId{100001},FacialId{"Sad01"}},
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Angry01_End"},Duration{1}},
PlayAnimation{ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}}
},
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"33.62793,178.25293,208.352539,0.000216,-11.998771,-94.401909,55.000008,276.918182,false,Manual,7.148376"},duration{0}},
CameraMoveTo{TargetPosition{"31.643555,152.46875,202.856445,0.000216,-11.998771,-94.401909,55.000008,246.001785,false,Manual,7.148376"},duration{8}}
}
}]],
          SpeakNpcId = 200021,
          Subtitle = "He just stood there, sneering, \"You know quite well what would happen to a Charon harming a Sola. I know you have a sister. Better stay out of it for her sake.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD2FA"
        },
        [10106320] = {
          Camera = "3519.108887,1585.492188,-165.398438,0.0,0.0,-94.298676,15.0,506.047913,false,DoNotOverride,1.2",
          ContentES = "¡Maldita sea! De verdad quiero tirarlo al Lago Lamentoso, que sirviera de festín a los peces. En fin, debo averiguar qué le pasó a Hunt y qué trama realmente Henrik.",
          DialogueId = 10106320,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "194CD324",
          NextOptions = {
            [1] = 10106321
          },
          SpeakNpcId = 200021,
          Subtitle = "D**n it! I really want to throw him into the Lamenting Lake. Anyway, I must find out what happened to Hunt, and what Henrik is really up to.",
          TalkActionId = {
            [1] = "200021:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD324"
        },
        [10106321] = {
          ContentES = "Te importas mucho por tu amigo.",
          DialogueId = 10106321,
          GUID = "10106321.0",
          NextDialogue = 10106322,
          Subtitle = "You really care about your friend."
        },
        [10106322] = {
          Camera = "-113.647461,-178.358398,144.197266,0.000174,3.999752,51.800861,35.0,272.898132,false,Manual,3.476349",
          ContentES = "...No es solo por Hunt. Hago esto sobre todo por Fina. No quiero ver a nadie a quien aprecie viviendo con miedo.",
          DialogueId = 10106322,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD3A0",
          NextDialogue = 10106323,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "...It's not just for Hunt. I do this mostly for Fina. I don't want to see anyone I care about living in fear anymore.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3A0"
        },
        [10106323] = {
          Camera = "31.643555,152.46875,202.856445,0.000216,-11.998804,-94.401909,55.0,248.159653,false,Manual,7.148376",
          ContentES = "Lo entiendo... Yo también estoy {性别:preocupado|preocupada} por alguien: la chica de verde de la que hablaste, Psyche.",
          DialogueId = 10106323,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194CD3A1",
          NextDialogue = 10106346,
          SpeakNpcId = 100001,
          Subtitle = "In that case, I'm worried about someone too... I mean Psyche, the girl in green you mentioned.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3A1"
        },
        [10106325] = {
          Camera = "-72.05835,-160.591797,149.589355,0.000178,4.599668,58.198891,45.0,272.898132,false,Manual,5.157309",
          ContentES = "Perfecto. Parece que tenemos un objetivo común.",
          DialogueId = 10106325,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CD3CC",
          NextDialogue = 10106326,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "Good, we have a common cause then.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3CC"
        },
        [10106326] = {
          ContentES = "Inicialmente pensaba sacar el Cristal estelar de la Mina, y luego usarlo como excusa para disculparme con Henrik y echar un vistazo dentro de la posada.",
          DialogueId = 10106326,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD3F6",
          NextDialogue = 10106327,
          Scripts = "PlayAnimation{ActorId{200021},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "I was gonna get the Crystallo from the pit, then use it as an excuse to apologise to Henrik and take a look inside the inn.",
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3F6"
        },
        [10106327] = {
          Camera = "-1467.822266,2680.921875,479.816895,0.000082,-22.999664,-48.185631,35.0,565.117065,false,Manual,2.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Pensé que nadie aceptaría el encargo, así que me fui a buscar un pastel primero, no esperaba que ustedes, {性别:los novatos|las novatas}, me dieran la sorpresa. ¿Qué tal si hacemos un trato?",
          DialogueId = 10106327,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "-1442.544678,2703.53418,479.816895,0.000082,-22.999664,-48.186123,35.0,565.117065,false,Manual,2.0",
          GUID = "194CD420",
          NextDialogue = 10106328,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{200021},AnimationId{"Sigh_Start"},Duration{1}},
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{"Sigh_End"},Duration{1}},
PlayAnimation{_delay{0.5},ActorId{200021},AnimationId{"Explain01_Start"},Duration{0}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "I thought no one would take the job, so I went off to sort out a cake first — didn't expect you newbies to throw a curveball. How about we strike a deal?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD420"
        },
        [10106328] = {
          Camera = "15.664551,9.075195,174.650879,0.000171,-3.399993,66.602043,25.000002,54.401806,false,Manual,3.0",
          ContentES = "Puedo conseguirte algo que de verdad necesitas—",
          DialogueId = 10106328,
          FacialId = {
            [1] = "200021:Smile01"
          },
          GUID = "194CD44A",
          NextDialogue = 10106329,
          SpeakNpcId = 200021,
          Subtitle = "I can get you something that you really need—",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD44A"
        },
        [10106329] = {
          Camera = "123.56665,72.790039,133.77002,0.000115,0.599902,-138.799866,30.0,88.840363,false,Manual,2.0",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "Una “identidad”: un permiso que te permite moverte libremente por Hyperborea, salvo la ciudad interior detrás de las torres de vigilancia, reservada para los de alto rango.",
          DialogueId = 10106329,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "127.988281,67.745117,133.77002,0.00011,0.599889,-138.799866,30.0,218.134293,false,Manual,2.0",
          GUID = "194CD474",
          NextDialogue = 10106330,
          SpeakNpcId = 200021,
          Subtitle = "An \"identity\" — a pass that allows you to move freely in Hyperborea, except for the inner city behind the watchtowers, which is reserved for the high and mighty.",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD474"
        },
        [10106330] = {
          Camera = "52.672607,-14.748047,167.826172,0.000079,-9.000058,-136.99884,30.000008,96.40477,false,Manual,1.828295",
          ContentES = "Muchos ofrecerían dinero, pero pocos arriesgarían la vida para conseguirte esto.",
          DialogueId = 10106330,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "194CD49E",
          NextOptions = {
            [1] = 10106331,
            [2] = 10106334
          },
          SpeakNpcId = 200021,
          Subtitle = "Many are willing to offer you money, but few would risk their lives to get you this.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD49E"
        },
        [10106331] = {
          ContentES = "¿Cómo supiste que lo necesitaba...?",
          DialogueId = 10106331,
          GUID = "10106331.0",
          NextDialogue = 10106332,
          Subtitle = "How did you know I needed that...?"
        },
        [10106332] = {
          Camera = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303",
          ContentES = "Solo lo supuse. ¿Así que realmente no tienes permiso de viaje? Menos mal que te encontraste conmigo. Si no, en Hyperborea lo tendrías complicado... a menos que te escondieras en un rincón oscuro todo el día.",
          DialogueId = 10106332,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194CD4C8",
          NextDialogue = 10106333,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"AgreeHead"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Just a guess. So, you really don't have a travel permit, huh? Lucky you ran into me. Without one, you'd be in a world of trouble in Hyperborea, unless you choose to hide in a shadowy corner all day.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD4C8"
        },
        [10106333] = {
          Camera = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
          ContentES = "(...Está intentando sacarme información.)",
          DialogueId = 10106333,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194CD4F2",
          NextOptions = {
            [1] = 10106337,
            [2] = 10106338
          },
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...He's fishing for information.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD4F2"
        },
        [10106334] = {
          ContentES = "Un permiso de viaje, entonces. ¿Y tú, cómo consigues uno?",
          DialogueId = 10106334,
          GUID = "10106334",
          NextDialogue = 10106335,
          Subtitle = "You're talking about a travel permit, right? How can you get one?"
        },
        [10106335] = {
          Camera = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303",
          ContentES = "¿Cómo lo consigues? ¿Te llevas bien con los guardias de Lago Helado?",
          DialogueId = 10106335,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194CD51C",
          NextDialogue = 10106336,
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "How can you get one? Are you buddies with the guards in Icelake?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD51C"
        },
        [10106336] = {
          ContentES = "No se puede decir que lo sea, pero nosotros, los Phoxcazadores, tenemos nuestras maneras.",
          DialogueId = 10106336,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CD546",
          NextOptions = {
            [1] = 10106337,
            [2] = 10106338
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Can't say I am, but we Phoxhunters have our ways.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD546"
        },
        [10106337] = {
          ContentES = "Ah, ya. Estás hablando de conseguir uno falso, ¿verdad?",
          DialogueId = 10106337,
          GUID = "10106337",
          NextDialogue = 10106339,
          Subtitle = "Ah, got it. You're talking about getting a fake one, aren't you?"
        },
        [10106338] = {
          ContentES = "Entonces puedo buscar a otra persona que me lo haga.",
          DialogueId = 10106338,
          GUID = "10106338",
          NextDialogue = 10106339,
          Subtitle = "Then I can also find someone else to make one for me."
        },
        [10106339] = {
          Camera = "123.935547,5.261719,672.55127,0.001522,-78.772713,-167.208313,25.0,326.395905,false,DoNotOverride,2.217901",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Hay cosas en esta ciudad que el dinero no compra, sobre todo las que te pueden meter en problemas. Lo que necesitas es el “hilo invisible” de las conexiones entre la gente.",
          DialogueId = 10106339,
          FacialId = {
            [1] = "200021:None",
            [2] = "100001:None"
          },
          FinalCamera = "140.303955,8.964844,757.100586,0.001522,-78.772713,-167.208313,25.0,326.395905,false,DoNotOverride,2.217901",
          GUID = "194CD570",
          NextDialogue = 10106340,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"-39.0,7.46582,5875.651855,0.000019,-90.0,0.000027,20.0,326.395905,false,DoNotOverride,2.217901"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"-39.0,7.46582,6107.878906,0.000248,-90.0,-0.000109,20.0,326.395905,false,DoNotOverride,2.217901"},blend{"easeOutQuad"},duration{4}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "There are things in this city that money can't buy, especially those that could land you in hot water. What you need is the \"invisible thread\" of connections between people.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD570"
        },
        [10106340] = {
          Camera = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
          ContentES = "(Sin un permiso de viaje, efectivamente es difícil moverse por Hyperborea.)",
          DialogueId = 10106340,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194CD59A",
          NextDialogue = 10106341,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Without a travel permit, it's indeed difficult to get around in Hyperborea.)",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59A"
        },
        [10106341] = {
          Camera = "45.434082,-29.058594,162.999512,0.000143,-4.198688,-134.496765,35.000008,88.220627,false,Manual,3.628265",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "¿Qué quieres a cambio de este trato? ¿Que te regale el Cristal estelar?",
          DialogueId = 10106341,
          ExStoryInfo = "Player",
          FinalCamera = "66.709229,-7.40918,165.228027,0.000144,-5.398807,-135.095779,35.000008,114.245468,false,Manual,3.628265",
          GUID = "194CD59B",
          NextDialogue = 10106342,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "So, what's the catch? Give you the Crystallo?",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59B"
        },
        [10106342] = {
          Camera = "16.160889,-237.400391,148.03125,0.000132,1.599944,92.399918,35.0,306.557922,false,Manual,2.071165",
          ContentES = "No. El Cristal es tuyo, siempre puedes cambiarlo por monedas con Henrik. Lo único que te pido es que encuentres la manera de entrar y que investigues la Casa de Hypnos.",
          DialogueId = 10106342,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CD59C",
          NextDialogue = 10106343,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Explain01_End"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "No, you can have it, and you can trade it with Henrik for silver coins if you want. All I need from you is: find a way to get in there and investigate the Hypnos' House.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59C"
        },
        [10106343] = {
          Camera = "70.744141,-0.792969,168.705566,0.000141,-7.000274,-136.200241,35.0,121.432114,false,Manual,2.071165",
          ContentES = "No eres de aquí, así que quizá él no desconfíe tanto de ti. Tienes más posibilidades de descubrir algo.",
          DialogueId = 10106343,
          FinalCamera = "65.674561,-5.65332,167.844727,0.000145,-7.000274,-136.200256,35.000008,121.432114,false,Manual,2.071165",
          GUID = "194CD59D",
          NextDialogue = 10106344,
          SpeakNpcId = 200021,
          Subtitle = "You're not one of the locals, so he might not be on his guard as much. You have a bigger chance to actually find something.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59D"
        },
        [10106344] = {
          ContentES = "Me parece sencillo. Cambiar un poco de espionaje por un permiso de viaje... trato hecho.",
          DialogueId = 10106344,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194CD59E",
          NextDialogue = 10106345,
          SpeakNpcId = 100001,
          Subtitle = "Trade a little snooping for a travel permit? I think I can handle that.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59E"
        },
        [10106345] = {
          Camera = "766.177124,137.326172,160.495605,0.000145,-2.799988,-174.8013,30.0,821.970154,false,Manual,1.2",
          ContentES = "Suena fácil, pero ten cuidado. Ven aquí mañana a las 12:00 con todo lo que hayas averiguado.",
          DialogueId = 10106345,
          FinalCamera = "843.248169,144.335938,164.278809,0.000145,-2.799988,-174.8013,30.0,821.970154,false,Manual,1.2",
          GUID = "194CD59F",
          Scripts = [[
PARA{
PlayAnimation{ActorId{200021},AnimationId{"AgreeHead"},Duration{2}},
PlayAnimation{_delay{4},ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}}}]],
          SpeakNpcId = 200021,
          Subtitle = "It sounds easy, but you should be careful. Meet me here at 12:00 tomorrow with anything you've found.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD59F"
        },
        [10106346] = {
          ContentES = "Si algo sale mal o la gente empieza a hacer preguntas… ya sabes lo que eso podría traer.",
          DialogueId = 10106346,
          GUID = "194CD3A3",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106346.T_Story_Recall_10106346'",
          NextDialogue = 10130001,
          SnapShot = "MEMORY",
          SpeakNpcId = 200005,
          Subtitle = "If anything happens that messes things up, or if people start asking questions... you know what's at stake.",
          VoiceName = "voice/$Locale$/story/1002/101058/194C8021"
        },
        [10106401] = {
          ContentES = "Más te vale descansar. Estaré aquí mañana a las 12:00 esperándote.",
          DialogueId = 10106401,
          GUID = "194CE16A",
          SpeakNpcId = 200021,
          Subtitle = "Better go get some rest. I'll be here at 12:00 tomorrow waiting for you.",
          VoiceName = "voice/$Locale$/story/1002/101064/194CE16A"
        },
        [10106501] = {
          Camera = "1342.068604,-1311.530273,220.426514,-0.001037,-2.0155,135.017212,35.000008,130.587296,false,DoNotOverride,1.200001",
          ContentES = "Berry... tantas cosas han pasado hoy.",
          DialogueId = 10106501,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "1296.370605,-1357.253906,220.427002,-0.001037,-2.0155,135.017212,35.000008,130.587296,false,DoNotOverride,1.200001",
          GUID = "194CF1D2",
          NextDialogue = 10106502,
          Scripts = [[
