        [10107013] = {
          Camera = "-32.240234,44.838135,145.527344,0.000015,2.000453,6.202501,35.0,93.94474,false,Manual,8.483248",
          ContentES = "(…Entonces, todos los huéspedes de la Casa de Hypnos padecen <H>algún tipo de enfermedad</>.)",
