          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194D4650",
          NextDialogue = 10107032,
          Scripts = "PlayAnimation{_delay{5},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Henrik is almost always here... which means this place is under his watch most of the time.)",
          TalkActionId = {
