        [10107106] = {
          Camera = "70.351562,-398.249817,694.277344,0.0,-0.800252,89.591064,25.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "… Limpiar. Quitar el polvo de todo. Cada día, cada estante, cada puerta. Todo debe estar impecable.",
          DialogueId = 10107106,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "71.666016,-197.30661,698.957031,0.0,-0.800252,89.591064,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194D5514",
          NextOptions = {
            [1] = 101071061,
            [2] = 101071062
          },
          SpeakNpcId = 200019,
          Subtitle = "Cleaning, dusting... Every day, every shelf, every door... Everything gets wiped down.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 9.5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D5514"
        },
        [10107107] = {
          Camera = "385.044922,13.178589,149.109375,0.000046,-3.499994,174.201569,45.0,406.956116,false,Manual,8.0",
          ContentES = "No lo entiendes. Es un “hábito”... Llenar la vida con actividades regulares, eso es un hábito.",
          DialogueId = 10107107,
          GUID = "194D553E",
          NextDialogue = 10107108,
          Scripts = "PlayAnimation{_delay{2},ActorId{200019},AnimationId{\"Explain01_Start\"},Duration{1}}",
          SpeakNpcId = 200019,
          Subtitle = "You don't get it. It's a \"habit\"... Filling life with regular tasks, that's what \"habit\" is.",
          TalkActionId = {
            [1] = "200019:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101071/194D553E"
        },
        [10107108] = {
          Camera = "-1277.564453,-593.944031,1182.701172,0.000064,-13.100098,20.401525,20.0,406.956116,false,Manual,8.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Como yo, que limpio todo esto cada día, o Psyche, que riega sus flores dos veces al día. Los hábitos llenan el vacío interior.",
          DialogueId = 10107108,
          FinalCamera = "-1291.347656,-556.815186,1182.701172,0.000064,-13.100098,20.401525,20.0,406.956116,false,Manual,8.0",
          GUID = "194D5568",
          NextOptions = {
            [1] = 101071081
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4.1},TargetPosition{"1046.738281,2345.742188,621.460938,0.0,0.0,89.999992,20.0,406.956116,false,Manual,8.0"},duration{0}},
CameraMoveTo{TargetPosition{"1046.738281,2380.742188,621.460938,0.0,0.0,89.999977,20.0,406.956116,false,Manual,8.0"},blend{"easeOutQuad"},duration{4}}
}]],
          SpeakNpcId = 200019,
          Subtitle = "Like how I clean here daily, or how Psyche waters her flowers twice a day. Habit fills the void inside.",
