        [10107502] = {
          Camera = "57.314453,33.117188,140.556641,0.000272,6.196354,-164.921524,35.000008,171.280121,false,Manual,8.0",
          ContentES = "Ya lo analicé. El Cristal estelar es auténtico, y su pureza coincide exactamente con la muestra que tenía antes. Buen trabajo.",
          DialogueId = 10107502,
          FinalCamera = "56.800781,35.038147,140.556641,0.000271,6.196354,-164.921188,35.000008,171.280121,false,Manual,8.0",
          GUID = "194D960C",
          NextDialogue = 10107503,
          SpeakNpcId = 200005,
          Subtitle = "I've checked it. The Crystallo is authentic, and its purity matches the small sample I had before. Good job.",
          TalkActionId = {
            [1] = "200005:Agree"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101075/194D960C"
        },
        [10107503] = {
          Camera = "218.541016,141.863037,85.324219,0.000294,10.795749,-150.511902,50.0,344.417786,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "Toma, aquí tienes. Tres mil monedas de plata y este recibo firmado. Llévaselo a la señorita Camilla y ella te entregará la garantía de mil monedas de plata.",
          DialogueId = 10107503,
          FinalCamera = "218.541016,141.863037,80.855469,0.000294,10.795749,-150.511902,50.0,344.417786,false,Manual,8.0",
          GUID = "194D9636",
          NextDialogue = 10107504,
          SpeakNpcId = 200005,
          Subtitle = "Here you go. Three thousand silver coins, and this signed receipt. Bring it to Ms Camilla, and she'll give you the guarantee of a thousand silver coins.",
          TalkActionId = {
            [1] = "200005:Give"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101075/194D9636"
        },
        [10107504] = {
          Camera = "45.244141,659.856079,249.224609,0.000292,-12.404326,-96.514885,35.0,335.254211,false,DoNotOverride,3.0",
          ContentES = "En cuanto a esto… un collar. Su valor supera con creces las mil monedas de plata. Puedes venderlo o empeñarlo.",
          DialogueId = 10107504,
          FinalCamera = "46.09375,666.646851,200.429688,0.000299,-8.604187,-97.515053,35.000008,335.254211,false,DoNotOverride,3.0",
          GUID = "194D9660",
          NextDialogue = 10107505,
          SpeakNpcId = 200005,
          Subtitle = "And this... necklace. It's worth far more than a thousand silver coins. You're free to sell it or pawn it.",
          TalkActionId = {
            [1] = "200005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101075/194D9660"
        },
        [10107505] = {
          Camera = "-205.306641,49.686646,199.617188,0.000314,-16.803425,-19.901423,40.000011,263.10965,false,Manual,5.0",
