        },
        [10108313] = {
          Camera = "196.914062,-106.330078,121.105469,0.000192,1.199682,145.998581,50.0,303.34079,false,Manual,8.0",
          ContentES = "Metal de chatarra que conseguí de la pequeña recicladora. Es resistente, no puedes romperlo tan fácil. Le puse un altavoz para atraerlos.",
          DialogueId = 10108313,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "202.421875,-97.979248,121.105469,0.000192,1.199654,147.997437,50.0,303.34079,false,Manual,8.0",
          GUID = "19516E96",
          NextDialogue = 10108314,
          SpeakNpcId = 200021,
          Subtitle = "A piece of scrap metal I picked up from the scavenger girl. It's tougher than it looks, and those Filthoids can't easily smash it. I've stuck a loudspeaker inside to lure them.",
          TalkActionId = {
            [1] = "200021:Give",
            [2] = "100001:Shock_End"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101135/19516E96"
        },
        [10108314] = {
