          Content = "…………",
          DialogueId = 10108322,
          GUID = "194E1B98",
          NextDialogue = 10108323,
          SpeakNpcId = 200021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B98"
        },
        [10108323] = {
          Camera = "-122.808594,351.115967,244.380371,0.000146,-18.200684,-67.394974,50.0,100000.0,false,Disable,2.8",
          Content = "听过一些坊间传闻而已，海伯利亚十几年前就出过一个拥有“和鸣之力”的家伙。你的力量……虽然细微，但和传说中的和鸣之力很像。",
          DialogueId = 10108323,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "-115.972656,311.899902,232.541016,0.000153,-18.400692,-66.794907,50.0,100000.0,false,Disable,2.8",
          GUID = "194E1B99",
          NextDialogue = 10108324,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200021,
          Subtitle = "It's mostly tavern talk, really. They say that years ago, there was this fellow in Hyperborea who had it. Your power, though much weaker, is very similar to that legendary power of Resonance.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B99"
        },
        [10108324] = {
          Camera = "47.087891,110.528076,141.211914,0.000135,-7.000274,-84.190117,50.0,100000.0,false,Disable,2.8",
          Content = "你说……和鸣之力是一种“引导”的力量？",
          DialogueId = 10108324,
          ExStoryInfo = "Player",
          GUID = "194E1B9A",
          NextDialogue = 10108325,
          SpeakNpcId = 100001,
          Subtitle = "So you're saying... Resonance is a sort of power that can \"guide\" people's actions?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9A"
        },
        [10108325] = {
          Camera = "144.796875,-61.763916,100.844727,0.000195,12.0,147.402008,35.0,282.419678,false,Manual,15.0",
          Content = "嗯，“引导”——或者极端一点说，“操控”。",
          DialogueId = 10108325,
          FinalCamera = "140.300781,-68.811523,100.844727,0.000195,12.0,147.402008,35.0,282.419678,false,Manual,15.0",
          GUID = "194E1B9B",
          NextDialogue = 10108326,
          SpeakNpcId = 200021,
          Subtitle = "Yes, or to put it more bluntly — it can \"control\" people.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9B"
        },
        [10108326] = {
          Camera = "95.589844,65.102783,147.506836,0.000202,2.999286,175.006119,35.0,138.980881,false,Manual,5.0",
          Content = "你没意识到吗？你的魔法会影响身边的“骸”，增幅他们的力量——甚至，极端情况下，让他们按照你的意志行动。",
          DialogueId = 10108326,
          Duration = 1.5,
          GUID = "194E1B9C",
          NextDialogue = 10108327,
          SpeakNpcId = 200021,
          Subtitle = "Haven't you noticed? Your magic can affect the Daimons around you, enhancing their powers — sometimes even manipulating them to act on your whims.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9C"
        },
        [10108327] = {
          Camera = "191.621094,-89.93457,109.277344,0.000199,6.198478,148.808563,35.0,401.024139,false,Manual,11.157635",
          Content = "当然，你如今的力量很微弱，还远远到不了那种程度。",
          DialogueId = 10108327,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "194E1B9D",
          NextDialogue = 10108328,
          SpeakNpcId = 200021,
          Subtitle = "Of course, you're not there yet. Your power's still waking up.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9D"
        },
        [10108328] = {
          Camera = "32.6875,29.662109,128.611328,0.000209,-4.201447,-62.396164,25.0,65.99147,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          Content = "（……操控？该不会是那个时候，和贝蕾——）",
          DialogueId = 10108328,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "18.273438,57.231689,130.894531,0.000209,-4.201447,-62.396164,35.0,130.879471,false,Manual,5.0",
          GUID = "194E1B9E",
          NextOptions = {
            [1] = 10108329,
            [2] = 10108332
          },
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Control other people? Could it have been from that time with Berry...)",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9E"
        },
        [10108329] = {
          Content = "引导和操控他人……听起来很危险。 ",
          DialogueId = 10108329,
          GUID = "10108329",
          ImprPlusId = 1007,
          NextDialogue = 10108330,
          Subtitle = "Guiding and controlling others… that sounds dangerous."
        },
        [10108330] = {
          Camera = "162.910156,-71.224854,104.924805,0.000222,9.998556,149.005325,35.0,100.0,false,Manual,11.0",
          Content = "嗯。所以我说尽量少在人前显露，以免惹上不必要的麻烦。",
          DialogueId = 10108330,
          GUID = "194E1B9F",
          NextDialogue = 10108331,
          SpeakNpcId = 200021,
          Subtitle = "You bet it is. That's why I'd advise keeping it under wraps in public to avoid any trouble.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9F"
        },
        [10108331] = {
          Camera = "528.824219,335.385986,-75.997559,0.000308,13.795157,-147.790375,35.0,264.565613,false,Manual,5.0",
          Content = "毕竟……上个拥有这种力量的家伙，可是把整个帝国搅得血雨腥风的，下场也凄惨得很，被吊死在迪斯玛尼亚的广场上。",
          DialogueId = 10108331,
          FinalCamera = "528.824219,335.385986,-26.985352,0.000309,9.999997,-147.789948,35.0,264.565613,false,Manual,5.0",
          GUID = "194E1C13",
          NextOptions = {
            [1] = 10108335
          },
          SpeakNpcId = 200021,
          Subtitle = "I mean... the last person with that power, turned the whole empire upside down, and ended up with a noose around their neck in Dismania's square.",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C13"
        },
        [10108332] = {
          Content = "引导和操控他人……听起来很好玩。 ",
          DialogueId = 10108332,
          GUID = "10108332",
          ImprPlusId = 1010,
          NextDialogue = 10108333,
          Subtitle = "Guiding and controlling others… that sounds fun."
        },
        [10108333] = {
          Camera = "191.621094,-89.93457,109.277344,0.000199,6.198478,148.808563,35.0,401.024139,false,Manual,11.157635",
          Content = "唉，你这外乡人是真的觉得自己命很大啊。",
          DialogueId = 10108333,
          ExStoryInfo = "Player",
          GUID = "194E1C14",
          NextDialogue = 10108334,
          SpeakNpcId = 200021,
          Subtitle = "You don't know what you're talking about.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C14"
        },
        [10108334] = {
          Camera = "471.207031,400.690186,-72.977539,0.000308,13.795151,-140.000015,35.0,625.0,false,Manual,5.0",
          Content = "上个拥有这种力量的家伙，可是把整个帝国搅得血雨腥风的，下场也凄惨得很。你也不想被吊死在迪斯玛尼亚的广场上吧？",
          DialogueId = 10108334,
          FinalCamera = "528.824219,335.385986,-75.997559,0.000308,13.795157,-147.790375,35.0,264.565613,false,Manual,5.0",
          GUID = "194E1C15",
          NextOptions = {
            [1] = 10108335
          },
          SpeakNpcId = 200021,
          Subtitle = "I mean... the last person with that power, turned the whole empire upside down and ended up with a noose around their neck in Dismania's square. You wouldn't want that, would you?",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C15"
        },
        [10108335] = {
          Content = "好吧，谢谢你的忠告。我会谨慎使用和鸣之力。",
          DialogueId = 10108335,
          GUID = "10108335",
          NextDialogue = 10108336,
          Subtitle = "Hmm, I see... thanks for the warning. I'll be careful with my power."
        },
        [10108336] = {
          Camera = "662.0625,-196.700195,127.136719,0.000301,-2.808314,161.416794,35.0,1282.889648,false,Manual,11.157635",
          Content = "好了，太阳也快下山了。回去吧，待会儿还有场“硬仗”要打。",
          DialogueId = 10108336,
          FinalCamera = "734.255859,-220.97583,130.874023,0.000301,-2.808314,161.416794,35.0,1282.889648,false,Manual,11.157635",
          GUID = "194E1C16",
          SpeakNpcId = 200021,
          Subtitle = "Well, the sun's setting. Time to head back — we've got a tough fight lined up tonight.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C16"
        },
        [10108337] = {
          Camera = "-158.597656,636.088623,270.316406,0.000033,-15.400197,-73.59948,50.0,340.220642,false,DoNotOverride,2.0",
          ContentES = "Nada mal, mejoras en combate mucho más rápido de lo que pensaba. A este paso, pronto serás {性别:un Phoxcazador autónomo|una Phoxcazadora autónoma}. Ah, los jóvenes de hoy sí que tienen talento.",
          DialogueId = 10108337,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-173.53125,686.955078,284.919434,0.000033,-15.40019,-73.599449,50.0,340.220642,false,DoNotOverride,2.0",
          GUID = "194E1C17",
          NextDialogue = 10108338,
          Scripts = "PlayAnimation{_delay{6.2},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}\n",
          SpeakNpcId = 200021,
          Subtitle = "Not bad. Your combat skill has gotten sharper than I thought. So quickly you've become a fully-fledged Phoxhunter. Hmm, the young nowadays do have talent.",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C17"
        },
        [10108338] = {
          Camera = "-5360.410156,-7622.796875,10140.634766,0.000062,-10.601491,16.198198,15.000005,340.220642,false,DoNotOverride,2.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Vamos, el sol ya se pone. Regresemos a Lago Helado para reunirnos con el Pequeño champiñón. Ojalá todo le haya ido bien.",
          DialogueId = 10108338,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "-5071.761719,-7538.956055,10084.37793,0.000067,-10.601498,16.198914,15.000005,340.220642,false,DoNotOverride,2.0",
          GUID = "194E1C18",
          SpeakNpcId = 200021,
          Subtitle = "The sun's going down. Let's go, it's time to meet Button Mushroom. I wonder if everyting on her side went smoothly.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C18"
        },
        [10108401] = {
          Content = "说起来，你的父母是什么人？",
          DialogueId = 10108401,
          Duration = 4,
          GUID = "194E298A",
          NextDialogue = 10108402,
          SpeakNpcId = 200021,
          Subtitle = "I've been meaning to ask, what do your parents do?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E298A"
        },
        [10108402] = {
          Content = "怎么突然问这个？",
          DialogueId = 10108402,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E29B4",
          NextDialogue = 10108403,
          SpeakNpcId = 100001,
          Subtitle = "Why do you ask?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E29B4"
        },
        [10108403] = {
          Content = "当然是因为和鸣之力很特别啊。卡戎之民的魔法，大多与血脉有关。没准你就大有来头。",
          DialogueId = 10108403,
          Duration = 4,
          GUID = "194E29DE",
          NextDialogue = 10108404,
          SpeakNpcId = 200021,
          Subtitle = "Because the power of Resonance is quite special, isn't it? The magical abilities among Charons often relate to their bloodline. Who knows, you might be from some prestigious background.",
          VoiceName = "voice/$Locale$/story/1002/101084/194E29DE"
        },
        [10108404] = {
          Content = "其实我也不知道……我从记事起就和贝蕾相依为命。其他的，就不太清楚了。",
          DialogueId = 10108404,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A08",
          NextDialogue = 10108405,
          SpeakNpcId = 100001,
          Subtitle = "Truth is, I don't know... It's always been just Berry and me since my earliest memories. I don't remember any other family members.",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A08"
        },
        [10108405] = {
          Content = "这样啊……",
          DialogueId = 10108405,
          Duration = 4,
          GUID = "194E2A32",
          NextDialogue = 10108406,
          SpeakNpcId = 200021,
          Subtitle = "Ah, I see...",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A32"
        },
        [10108406] = {
          Content = "哎，我说，那如果以后你发现自己其实是什么亲王啊公爵啊流落在外的私生子，可别把我这个贫贱之交忘了哦。",
          DialogueId = 10108406,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A5C",
          NextDialogue = 10108407,
          SpeakNpcId = 200021,
          Subtitle = "Hey, if you ever find out you're actually some {性别:prince|princess} or duke's secret love child, don't forget about this poor old friend of yours, alright?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A5C"
        },
        [10108407] = {
          Content = "哈，最好真的像你说的那样。",
          DialogueId = 10108407,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A86",
          SpeakNpcId = 100001,
          Subtitle = "Hah, that would be nice, wouldn't it?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A86"
        },
        [10108501] = {
          Camera = "-42.287598,160.495117,57.3396,0.000126,10.999991,-81.999931,30.0,334.989777,false,Manual,1.27223",
          ContentES = "¡Por fin!",
          DialogueId = 10108501,
          FacialId = {
            [1] = "200064:Happy01"
          },
          FinalCamera = "13.111328,278.30957,57.3396,0.000129,10.799983,-83.399635,30.0,351.555328,false,Manual,1.27223",
          GUID = "194E39F2",
