        [10108705] = {
          ContentES = "(Una caja finamente tallada, pesada de sostener. Pero, como dijo Nieve, está vacía.)",
          DialogueId = 10108705,
          DisableMouth = 1,
          GUID = "194E5B40",
          IsBlack = 1,
          NextDialogue = 10108706,
          Scripts = [[
