          Subtitle = "(It's an intricately carved box, feeling surprisingly heavy in your hands. But as Snow said, it's empty inside.)",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B40"
        },
        [10108706] = {
          ContentES = "(¡No, no está completamente vacía! Queda una sustancia…<H>un polvo viscoso</> parecido a la sal. La mayor parte se disolvió en el agua, pero un poco permanece en el fondo.)",
          DialogueId = 10108706,
          DisableMouth = 1,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194E5B6A",
          IsBlack = 1,
          LookAt = {
            [1] = "200002:p(P10108701)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10108707,
          Subtitle = "(Not completely empty, though! There's some sort of residue. Seems to be some slimy powder resembling salt. Most of it has dissolved into the water, but a small amount remains at the bottom of the box.)",
          TurnTo = {
            [1] = "100001:p(22)"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B6A"
        },
        [10108707] = {
