          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C24"
        },
        [10109003] = {
          Camera = "143.380615,51.583008,147.531738,0.000069,-1.199982,-144.201019,40.0,274.454834,false,Manual,5.0",
          ContentES = "Mmh… Henrik volvió en el peor momento. Si hubiera tenido solo unos minutos más… Es mi culpa, por perder tanto tiempo con esta chimenea. ¡Maldita sea! Sabía que no era de fiar.",
          DialogueId = 10109003,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "132.862061,65.048828,147.531738,0.00007,-1.199941,-138.801163,40.0,274.454834,false,Manual,5.0",
          GUID = "194E8C4E",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10109004,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{"DisagreeHead"},Duration{0.1}},
PlayAnimation{_delay{6},ActorId{200021},AnimationId{"Angry01_Start"},Duration{0.1}}
}
]],
          SpeakNpcId = 200021,
          Subtitle = "Ugh, Henrik came back at a bad time. If I had just a few more minutes... It's my fault — I wasted too much time with that chimney. D**n it! I knew he was up to no good.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 12.5,
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C4E"
