            [1] = "200021:None"
          },
          FinalCamera = "46.280029,5.457031,149.058594,0.000183,0.999714,-140.175919,48.0,163.680023,false,Manual,8.0",
          GUID = "194E8D20",
          NextDialogue = 10109010,
          SpeakNpcId = 200021,
          Subtitle = "\"Just stand there, helplessly watching her leave.\" Right?",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D20"
        },
        [10109010] = {
          Camera = "-218.000488,-102.597656,160.563965,0.000186,-4.601375,10.503407,45.0,275.06012,false,Manual,8.0",
          ContentES = "…¿Cómo lo sabes…?",
          DialogueId = 10109010,
          ExStoryInfo = "Player",
