  {
    MinKey = 10109802,
    MaxKey = 10111801,
    Loader = function()
      return {
        [10109802] = {
          ContentES = "A pesar de jugar al escondite con los Filthoids de vez en cuando, siempre esperaba con ansias venir aquí.",
          DialogueId = 10109802,
          GUID = "194F0F64",
          NextDialogue = 10109803,
          SpeakNpcId = 200006,
          Subtitle = "Despite the occasional hide-and-seek with the Filthoids, I always looked forward to coming here.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F64"
        },
        [10109803] = {
          ContentES = "Porque me encantaban los trozos de hielo flotante y las montañas de aquí, y aún más, me encantaba ver los trenes rugir al pasar.",
          DialogueId = 10109803,
          GUID = "194F0F8E",
          NextDialogue = 10109804,
          SpeakNpcId = 200006,
          Subtitle = "Because I loved the floating ice and mountains here, and more so, I loved watching the trains roar by.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F8E"
        },
        [10109804] = {
          ContentES = "¿Te gustan los trenes?",
          DialogueId = 10109804,
          ExStoryInfo = "Player",
          GUID = "194F0FB8",
          NextDialogue = 10109805,
          SpeakNpcId = 100001,
          Subtitle = "You like trains?",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0FB8"
        },
        [10109805] = {
          ContentES = "Sí. Lo que más me fascina es su destino... el “Sur”.",
          DialogueId = 10109805,
          GUID = "194F0FE2",
          NextDialogue = 10109806,
          SpeakNpcId = 200006,
          Subtitle = "Yeah. I'm fascinated by their destination... the \"South.\"",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0FE2"
        },
        [10109806] = {
          ContentES = "En los libros dicen que allí, nada se parece a Lago Helado.",
          DialogueId = 10109806,
          GUID = "194F100C",
          NextDialogue = 10109807,
          SpeakNpcId = 200006,
          Subtitle = "I've read that it's nothing like Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F100C"
        },
        [10109807] = {
          ContentES = "El sol es más cálido allí, y se pueden ver las estaciones cambiar.",
          DialogueId = 10109807,
          GUID = "194F1036",
          NextDialogue = 10109808,
          SpeakNpcId = 200006,
          Subtitle = "The sun's warmer there, and you get to see seasons change.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1036"
        },
        [10109808] = {
          ContentES = "Cuando llega la primavera, el hielo y la nieve desaparecen, y las flores brotan por todas partes, incluso en las llanuras salvajes.",
          DialogueId = 10109808,
          GUID = "194F1060",
          NextDialogue = 10109809,
          SpeakNpcId = 200006,
          Subtitle = "When spring comes, the ice and snow melt away, and there are flowers everywhere, even in the wilds.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1060"
        },
        [10109809] = {
          ContentES = "Siempre soñé que, si pudiera subir a un tren, algún día llegaría hasta allí.",
          DialogueId = 10109809,
          GUID = "194F108A",
          NextDialogue = 10109810,
          SpeakNpcId = 200006,
          Subtitle = "I always dreamed that if I could catch a train, I could actually get there.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F108A"
        },
        [10109810] = {
          ContentES = "Pero papá me dijo que era un deseo demasiado ambicioso.",
          DialogueId = 10109810,
          GUID = "194F10B4",
          NextDialogue = 10109811,
          SpeakNpcId = 200006,
          Subtitle = "But Dad told me, it was not a dream we could afford.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F10B4"
        },
        [10109811] = {
          ContentES = "¿Porque… sois Charons?",
          DialogueId = 10109811,
          ExStoryInfo = "Player",
          GUID = "194F10DE",
          NextDialogue = 10109812,
          SpeakNpcId = 100001,
          Subtitle = "Because... you're Charons?",
          VoiceName = "voice/$Locale$/story/1002/101098/194F10DE"
        },
        [10109812] = {
          ContentES = "Sí. Y además, mamá y papá eran simples jardineros. Éramos pobres y no teníamos medios para subir a ese tren.",
          DialogueId = 10109812,
          GUID = "194F1108",
          SpeakNpcId = 200006,
          Subtitle = "Yes. And also because Mum and Dad are just ordinary gardeners. We were poor and didn't have the means to board that train.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1108"
        },
        [10109901] = {
          Camera = "43.035156,-369.824219,5.117188,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
          ContentES = "Así que, el día que llamaste a la puerta de la Casa de Hypnos, me sentí emocionada... Nunca había conocido a nadie que viniera de fuera de Lago Helado.",
          DialogueId = 10109901,
          FacialId = {
            [1] = "200027:Smile02"
          },
          FinalCamera = "50.992188,-403.761719,-0.895508,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0",
          GUID = "194F1FA2",
          LookAt = {
            [1] = "100001:n(200027)",
            [2] = "200027:n(100001)"
          },
          NextDialogue = 10109902,
          RelatedWikiId = {
