          SpeakNpcId = 200027,
          Subtitle = "So, the day you showed up at the door of the Hypnos' House, I was thrilled... I'd never met anyone outside Icelake.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101099/194F1FA2"
        },
        [10109902] = {
          Camera = "-194.089844,43.5625,83.087891,0.000346,-1.60116,21.496424,40.0,226.073593,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Desde entonces, en secreto me pregunto: ¿cómo es tu tierra natal? ¿Has visto el océano con tus propios ojos? ¿Es realmente tan inmenso como cien lagos juntos?",
          DialogueId = 10109902,
          FinalCamera = "-148.476562,62.945312,79.891602,0.000346,-0.001072,17.102312,40.000011,162.126846,false,Manual,4.0",
          GUID = "194F1FCC",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 10109903,
          Scripts = [[

