        [10110203] = {
          ContentES = "Bien... si es su palabra, confío en usted. Pero sobre todo, ¡{性别:vigílenlo|vigílenla}bien! Nada de problemas en la ciudad, o la Comandante nos caerá encima a los dos.",
          DialogueId = 10110203,
          ExStoryInfo = "Player",
          GUID = "194F512E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110203.T_Story_Recall_10110203'",
          NextDialogue = 10110204,
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = "Alright, I trust you, Ms Camilla. But remember, keep a close eye on this kid and don't let {性别:him|her} stir up any trouble in town. If the Chief finds out about this, we'll both be in for it.",
          VoiceName = "voice/$Locale$/story/1002/101006/19492C50"
        },
        [10110204] = {
          Camera = "47.769531,188.458008,134.702148,0.000103,0.398248,-107.229118,35.0,362.075562,false,Manual,3.0",
          ContentES = "¡Mierda! No esperaba encontrarme contigo... Escucha, {性别:hermanito|hermanita}, por favor, no se lo digas a nadie, ¿vale?",
          DialogueId = 10110204,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5158",
          NextDialogue = 10110205,
          Scripts = [[
PARA{
PlayAnimation{_delay{1},ActorId{200004},AnimationId{"Disagree"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200004},AnimationId{"Talk01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "D**n ! Didn't expect to run into you... Do me a favour, {性别:mate|miss}, keep this between us, will you?",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5158"
        },
        [10110205] = {
          Camera = "64.769531,6.819336,122.332031,0.000111,7.997714,119.570648,35.0,362.075562,false,DoNotOverride,22",
          CameraBlendCurve = "easeInQuad",
          ContentES = "¿Quién es este...?",
          DialogueId = 10110205,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock02"
          },
          FinalCamera = "49.960938,32.921875,126.546875,0.000111,8.397717,119.570648,35.0,362.075562,false,DoNotOverride,22",
          GUID = "194F5182",
          LookAt = {
            [1] = "100001:p(P101102Bag)"
          },
          NextDialogue = 10110206,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"-23.076172,112.924805,193.445312,0.000089,-33.602196,-42.428871,35.0,362.075562,false,Manual,22.0"},duration{0}},
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0051_story_danger"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Who is this...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5182"
        },
        [10110206] = {
          Camera = "74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8",
          ContentES = "¡Alto, parad! ¡Toma, recupera el dinero! Llevo días sin comer... me he rendido, fue mi culpa, fue mi culpa.",
          DialogueId = 10110206,
          GUID = "194F51AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110206.T_Story_Recall_10110206'",
          NextDialogue = 10110207,
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Alright, alright, here's your money bag! I haven't had a decent meal in days, so I got desperate... I'm sorry!",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD496"
        },
        [10110207] = {
          Camera = "49.960938,32.921875,126.546875,0.000111,8.397717,119.570648,35.0,362.075562,false,Manual,22.0",
          ContentES = "¿Lo ejecutaste? No creo que se lo mereciera...",
          DialogueId = 10110207,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "194F51D6",
          LookAt = {
            [1] = "100001:n(200004)"
          },
          NextDialogue = 10110208,
          Scripts = "CameraMoveTo{_delay{1.5},TargetPosition{\"53.412109,-207.308594,178.919922,0.000045,-11.599839,106.600044,35.000008,338.707367,false,Manual,4.0\"},duration{0}},",
          SpeakNpcId = 100001,
          Subtitle = "...You executed him!? I don't think he deserves this...",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F51D6"
        },
        [10110208] = {
          Camera = "2442.902344,1375.00293,-15.568359,0.000018,1.799891,-157.005646,50.0,546.458801,false,Manual,1.2",
          ContentES = "¡Shh! Te dije que no fui yo. Solo estaba llevando su cuerpo en secreto.",
          DialogueId = 10110208,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "2446.085938,1367.493164,-15.568359,0.000015,1.799891,-157.005661,50.0,2902.307617,false,Manual,4.0",
          GUID = "194F5200",
          NextDialogue = 10110209,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Keep it down! I told you it wasn't me. I was just trying to sneak the body out.",
          TalkActionId = {
            [1] = "200004:Talk01_Start",
            [2] = "100001:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5200"
        },
        [10110209] = {
          ContentES = "Me llamo Kevin. Ya nos hemos cruzado antes... pertenezco a la Escolta del Suburbio del Lago Helado. Y él es Hal... un antiguo vecino, nos conocemos desde que éramos niños.",
          DialogueId = 10110209,
          GUID = "194F522A",
          NextDialogue = 10110210,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "My name's Kevin. We've met before — I'm in the outskirts escort... And this poor soul here is Hal, my old neighbour. We've known each other since we were kids.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F522A"
        },
        [10110210] = {
          Camera = "155.150391,89.697266,40.088867,0.000099,0.594261,-127.181572,25.0,379.426514,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Perdió a su madre siendo joven y desde entonces se ha metido en peleas sin parar. Mi familia no me permite tratar con los Charons, pero como era un amigo de la infancia, a veces le echaba una mano...",
          DialogueId = 10110210,
          FinalCamera = "155.150391,89.697266,40.088867,0.000105,18.793825,-127.379799,25.0,379.426514,false,Manual,22.0",
          GUID = "194F5254",
          NextDialogue = 10110211,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.2},TargetPosition{"108.958984,10.623047,103.797852,0.000077,19.595867,-129.596573,35.000008,184.886414,false,Manual,22.0"},duration{0}},
PlayAnimation{_delay{2},ActorId{200004},AnimationId{"Talk01_Start"},Duration{2}},
SEQ{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
LookAt{_delay{2},LookAtDescription{"200004:n(100001)"}}
}
}]],
          SpeakNpcId = 200004,
          Subtitle = "He lost his mother at an early age and had been getting into countless brawls ever since. My family doesn't allow me to interact with Charons, but he was an old friend from when I was a kid, so I'd sometimes help him out...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5254"
        },
        [10110211] = {
          Camera = "189.996094,-133.302734,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Luego un día vino a verme con aspecto sospechoso. Pensé que tenía más deudas o que su padre borracho le había pegado. Pero no... me dijo que mostraba signos de <W>Deterioro</>...",
          DialogueId = 10110211,
          FinalCamera = "190.324219,-114.291016,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463",
          GUID = "194F527E",
          LookAt = {
            [1] = "200004:n(100001)"
          },
          NextDialogue = 10110212,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"204.705078,100.296875,134.578125,0.0,0.0,-179.999954,35.0,180.0,false,Manual,4.146463"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"204.707031,113.621094,134.578125,0.0,-0.200008,-179.399948,35.0,180.0,false,Manual,4.146463"},blend{"easeOutQuad"},duration{4}},
SEQ{
PlayAnimation{_delay{0.1},ActorId{200004},AnimationId{"Talk01_End"},Duration{1}}
}
}]],
          SpeakNpcId = 200004,
          Subtitle = "One day, he came to me, acting all weird. I thought he'd racked up debts again, or that he came to moan about being hit again by his drunkard dad. But to my surprise, he said he was showing signs of Deterioration...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F527E"
        },
        [10110212] = {
          Camera = "32.447266,-94.166016,150.726562,0.000106,-6.001796,98.975403,35.000011,165.117889,false,Manual,4.0",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "¿Deterioro? ¿Qué es exactamente?",
          DialogueId = 10110212,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "27.117188,-60.277344,147.863281,0.000109,-4.801753,98.975227,35.000008,165.117889,false,Manual,4.0",
          GUID = "194F52A8",
          NextDialogue = 10110213,
          SpeakNpcId = 100001,
          Subtitle = "What exactly is \"Deterioration\"?",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F52A8"
        },
        [10110213] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
          ContentES = "¿Qué? ¿Tú, siendo Charon y no sabes lo que es Deterioro? ¿Estás seguro de venir del Imperio?",
          DialogueId = 10110213,
          GUID = "194F52D2",
          NextOptions = {
            [1] = 10110214,
            [2] = 10110216
          },
          SpeakNpcId = 200004,
          Subtitle = "As a Charon, you don't know about Deterioration? Are you really a native?",
          TalkActionId = {
            [1] = "200004:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52D2"
        },
        [10110214] = {
          ContentES = "Vengo de un pueblo remoto, no tengo mucha información...",
          DialogueId = 10110214,
          GUID = "10110214",
          ImprPlusId = 1007,
          NextDialogue = 10110215,
          Subtitle = "I'm from a backwater village, we're rather uninformed..."
        },
        [10110215] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
          ContentES = "Ah sí, Camilla lo había mencionado, eso lo explica.",
          DialogueId = 10110215,
          GUID = "194F52FC",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          Subtitle = "Ah right, Camilla did mention something about that. Makes sense then.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52FC"
        },
        [10110216] = {
          ContentES = "Haces demasiadas preguntas. Cállate o contaré lo que acabo de ver a...",
          DialogueId = 10110216,
          GUID = "10110216",
          ImprPlusId = 1010,
          NextDialogue = 10110217,
          Subtitle = "You ask too many questions. Shut it or I'll share what I just saw with..."
        },
        [10110217] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0",
          ContentES = "¡Ah! No, ya no haré más preguntas, por favor, no se lo digas a nadie.",
          DialogueId = 10110217,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5326",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          Subtitle = "Alright, alright! I won't ask any more questions! Please don't tell anyone!",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5326"
        },
        [10110218] = {
          Camera = "774.716797,904.916992,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8",
          ContentES = "El <W>Deterioro</>, es una enfermedad propia de los Charons. Cuando te afecta, es incurable.",
          DialogueId = 10110218,
          FinalCamera = "819.070312,866.855469,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8",
          GUID = "194F5350",
          NextDialogue = 10110219,
          SpeakNpcId = 200004,
          Subtitle = "So Deterioration is a peculiar disease that only Charons might suffer from. Once you've got it, there's no cure.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5350"
        },
        [10110219] = {
          Camera = "59.294922,60.157227,158.963867,0.000116,1.398187,-107.029724,35.0,201.991119,false,Manual,6.0",
          ContentES = "Ustedes suelen despertar algún tipo de poder alrededor de la adolescencia, pero no todos tienen esa suerte.",
          DialogueId = 10110219,
          FinalCamera = "54.453125,61.650391,158.963867,0.000116,1.398222,-105.829933,35.0,197.159012,false,Manual,6.0",
          GUID = "194F537A",
          NextDialogue = 10110220,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"14.539062,-57.106445,149.019531,0.000111,-4.801684,98.370796,35.0,159.591751,false,Manual,6.0"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"24.572266,-55.670898,149.019531,0.000112,-5.201646,97.571365,35.000008,165.538956,false,Manual,6.0"},duration{4}}
}]],
          SpeakNpcId = 200004,
          Subtitle = "You folks usually awaken some kind of power around your teens, but not everyone's that lucky.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F537A"
        },
        [10110220] = {
          ContentES = "Siempre hay algunos pobres desdichados que, de alguna forma, fallan su despertar y se convierten en <W>Filthoid</>. Pero mucho más fuertes que los Filthoids comunes, toda una escolta ni siquiera podría derrotar a uno.",
          DialogueId = 10110220,
          GUID = "194F53A4",
          NextDialogue = 10110221,
          RelatedWikiId = {
            [1] = 303003
          },
          SpeakNpcId = 200004,
          Subtitle = "There are always a few poor wretches who somehow get it wrong and turn into Filthoids — but way stronger than the regular Filthoids out there; a whole escort might not even be able to take one down.",
          VoiceName = "voice/$Locale$/story/1002/101102/194F53A4"
        },
        [10110221] = {
          Camera = "582.199219,778.926758,7556.786133,0.000033,22.586451,-62.627708,15.000007,179.344406,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Si aparece un Deteriorador en la ciudad... todo el vecindario está condenado.",
          DialogueId = 10110221,
          FinalCamera = "731.279297,485.125,7697.886719,0.000031,23.186407,-63.027958,15.000007,179.344406,false,DoNotOverride,22.0",
          GUID = "194F53CE",
          NextDialogue = 10110222,
          SpeakNpcId = 200004,
          Subtitle = "If a Deteriorator appears in the city... the entire neighbourhood is doomed.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F53CE"
        },
        [10110222] = {
          Camera = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0",
          ContentES = "Por eso tantos Solarianos odian a los Charons. Dicen que es la sangre impura lo que atrae la desgracia... ¿Y los Deterioradores? Son vistos como lo peor de lo peor entre todos los Charons.",
          DialogueId = 10110222,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F53F8",
          NextDialogue = 10110223,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "Now you get why most Solas hate Charons, right? They say it's the evil magic running through their veins that brings all this disaster. And the Deteriorators? They're seen as the worst of the worst among all Charons.",
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F53F8"
        },
        [10110223] = {
          Camera = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0",
          ContentES = "Honestamente, no creo completamente en eso. Pero... ¿por qué tuvo que sucederle a Hal?",
          DialogueId = 10110223,
          GUID = "194F5422",
          NextDialogue = 10110224,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
PlayAnimation{ActorId{200004},AnimationId{"Disagree"},Duration{2}},
LookAt{_delay{2},LookAtDescription{"200004:n(100001)"}}
}]],
          SpeakNpcId = 200004,
          Subtitle = "Honestly, I'm not entirely sold on this, but... How come such a rare thing had to happen to Hal?",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5422"
        },
        [10110224] = {
          Camera = "59.203125,-199.486328,172.362305,0.000048,-11.20041,106.99884,35.000008,100000.0,false,Disable,4.0",
          ContentES = "Hace dos semanas, vino a verme, desesperado. Pero no pude esconderlo. Proteger a un Deteriorador es un crimen tan grave como albergar a un miembro de los Abandonados, un solo error y estás acabado. Lo único que pude hacer fue darle algo de comer y decirle que se arreglara.",
          DialogueId = 10110224,
          GUID = "194F544C",
          NextDialogue = 10110225,
          Scripts = "CameraMoveTo{_delay{11},TargetPosition{\"74.595703,85.75,141.061523,0.000111,4.598363,-113.225594,35.0,100000.0,false,Disable,2.8\"},duration{0}}",
          SpeakNpcId = 200004,
          Subtitle = "About two weeks ago, he came to me all in a flap, but what could I do? Harbouring a Deteriorator is as serious a crime as sheltering a member of the Forsakens — one slip and you're done for. All I could do was give him some food and tell him to sort himself out.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F544C"
        },
        [10110225] = {
          Camera = "81.287109,-34.47168,231.873047,0.000089,-31.399204,-132.789673,35.000008,100000.0,false,Disable,4.0",
          ContentES = "Más tarde supe que lo atraparon robando, y cuando descubrieron que era un Deteriorador, lo llevaron directo a la Oficina de Seguridad.",
          DialogueId = 10110225,
          GUID = "194F5476",
          NextOptions = {
            [1] = 10110226
          },
          SpeakNpcId = 200004,
          Subtitle = "Later I heard he got nabbed for stealing, and when they found out he was a Deteriorator, they took him straight to the Security Bureau.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5476"
        },
        [10110226] = {
          ContentES = "¿Y qué le hacen en la Oficina de Seguridad?",
          DialogueId = 10110226,
          GUID = "194F5477",
          NextDialogue = 10110227,
          Subtitle = "What would happen to him at the Security Bureau?"
        },
        [10110227] = {
          Camera = "777.373047,-100.292969,25.057617,0.000009,4.599859,172.998215,40.000011,332.596619,false,Manual,22.0",
          ContentES = "Ya te dije que no hay cura para los Deterioradores. ¿Qué crees que le harán? Lo transfieren a la Escolta y luego... bueno, ya sabes.",
          DialogueId = 10110227,
          GUID = "194F54A0",
          NextDialogue = 10110228,
          SpeakNpcId = 200004,
          Subtitle = "Like I said, there's no cure for Deteriorators. What else could happen? They get handed over to the Escort, and then... well, you know.",
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54A0"
        },
        [10110228] = {
          Camera = "-30.980469,-249.970703,249.849609,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
          ContentES = "En cierto modo, se lo buscó... Pero fue mi amigo durante años. No pude soportar la idea de dejarlo en una morgue helada. Así que lo saqué... en secreto. Mi intención era enterrarlo junto al Lago Lamentoso, donde descansa su madre.",
          DialogueId = 10110228,
          FinalCamera = "-23.003906,-235.451172,235.890625,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
          GUID = "194F54CA",
          NextDialogue = 10110229,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
SetLocation{ActorId{100001},TargetPoint{"P101102Nvzhu2"},Visibility{"Show"}}
}]],
          SpeakNpcId = 200004,
          Subtitle = "He pretty much had it coming... But still, we were friends for a few years. I couldn't bear the thought of him lying in a cold morgue, so I sneaked him out... I was gonna bury him by Lamenting Lake, right next to his mother.",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "200004:p(-110)"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54CA"
        },
        [10110229] = {
          Camera = "49.005859,-190.758789,170.493164,0.000064,-9.500171,103.609756,40.000023,322.94809,false,Manual,3.0",
          ContentES = "Espera. Quiero saber... Entre los primeros signos de Deterioro y su manifestación total... ¿qué síntomas aparecen?",
          DialogueId = 10110229,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194F54F4",
          NextDialogue = 10110230,
          Scripts = [[
PARA{
LookAt{_delay{1},LookAtDescription{"200004:n(100001)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Hold on, I'm curious — what symptoms would appear between the onset of Deterioration and its full development?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54F4"
        },
        [10110230] = {
          Camera = "29.394531,154.411133,135.935547,0.000082,4.298655,-102.209503,40.000011,300.548492,false,Manual,4.0",
          ContentES = "No lo sé. Pero he oído que algunos se vuelven increíblemente violentos, y otros, los más desafortunados, empiezan a perder los sentidos poco a poco... como quedarse ciegos o sordos, algo así.",
          DialogueId = 10110230,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F551E",
          NextDialogue = 10110231,
          RelatedWikiId = {
            [1] = 303006
          },
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200004:n(100001)"}},
PlayAnimation{_delay{1.5},ActorId{200004},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{5},ActorId{200004},AnimationId{"Think_End"},Duration{1}},
}]],
          SpeakNpcId = 200004,
          Subtitle = "I wouldn't know. But I've heard that some would turn extremely violent, and some poor souls would gradually lose their senses, like going blind or deaf or something, perhaps.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F551E"
        },
        [10110231] = {
          ContentES = "Eso son solo rumores. Si de verdad te interesa, mejor pregúntale a un médico. Pero tú ya superaste el despertar. Entonces, ¿por qué te preocuparía eso?",
          DialogueId = 10110231,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F5548",
          NextDialogue = 10110232,
          Scripts = "PlayAnimation{_delay{3},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{2}}\n",
          SpeakNpcId = 200004,
          Subtitle = "This is all just hearsay though. If you're curious about it, better ask a doctor. But it seems to me you've awakened already successfully, why do you care?",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5548"
        },
        [10110232] = {
          Camera = "71.007812,-49.522461,222.453125,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "...",
          DialogueId = 10110232,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          FinalCamera = "60.40625,-24.273438,208.739258,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
          GUID = "194F5572",
          NextDialogue = 10110233,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5572"
        },
        [10110233] = {
          ContentES = "Ah… Me mareé un poco y no vi el escalón. Gracias.",
          DialogueId = 10110233,
          GUID = "194F559C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110233.T_Story_Recall_10110233'",
          NextDialogue = 10110234,
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "Uh! I got a little dizzy and didn't see the step, thank you.",
          VoiceName = "voice/$Locale$/story/1002/101013/19499D06"
        },
        [10110234] = {
          ContentES = "No veía nada hace un momento y al final lo asusté... ¡Perdón!",
          DialogueId = 10110234,
          GUID = "10110234.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110234.T_Story_Recall_10110234'",
          NextDialogue = 10110235,
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10110235] = {
          ContentES = "Psyche... Tus ojos... ¿Desde cuándo no ves bien?",
          DialogueId = 10110235,
          ExStoryInfo = "Player",
          GUID = "10110235.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110235.T_Story_Recall_10110235'",
          NextDialogue = 10110236,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "Psyche... when did your eyesight start to fade?",
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE42"
        },
        [10110236] = {
          ContentES = "¿Desde cuándo...?",
          DialogueId = 10110236,
          GUID = "10110236.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110236.T_Story_Recall_10110236'",
          NextDialogue = 10110237,
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "When was it...",
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE6C"
        },
        [10110237] = {
          Camera = "19.232422,44.570312,117.50293,0.000166,18.198389,104.808296,35.000008,162.592728,false,Manual,22.0",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "(...¿Podría la pérdida de la vista de Psyche ser un síntoma del Deterioro... Podría ser que todos los “huéspedes” de la Casa de Hypnos sean Deterioradores?)",
          DialogueId = 10110237,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "29.253906,6.640625,104.633789,0.000168,17.198368,104.608376,35.000008,162.592728,false,Manual,22.0",
          GUID = "194F5644",
          NextDialogue = 10110238,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Could Psyche's sight loss be a symptom of Deterioration... Could all the \"lodgers\" at the Hypnos' House be Deteriorators?)",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5644"
        },
        [10110238] = {
          Camera = "37.144531,202.914062,126.870117,0.000128,3.900086,-105.196716,40.0,278.887787,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "Señor, quiero informarme sobre alguien, y espero que me respondas con sinceridad. ¿Ves esta cámara? Si te niegas, podría entregarla a la Oficina de Seguridad, seguro que querrán verla.",
          DialogueId = 10110238,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "50.792969,198.213867,126.870117,0.000126,3.900086,-107.797836,40.0,278.887787,false,Manual,3.0",
          GUID = "194F566E",
          NextDialogue = 10110239,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"72.476562,-210.320312,168.837891,0.000193,-9.201282,108.579414,35.000008,371.235565,false,Manual,3.0"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"59.669922,-214.0625,168.837891,0.000192,-9.801321,105.5793,35.000008,371.235565,false,Manual,3.0"},blend{"easeOutQuad"},duration{4}},
PlayAnimation{_delay{4.2},ActorId{100001},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Sir, I'd like to inquire about someone, and I hope you'll be frank and supportive. See this camera? If you refuse, I might just hand it over to the Security Bureau — they'd surely be interested.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F566E"
        },
        [10110239] = {
          Camera = "62.695312,-35.460938,197.44043,0.000168,-15.401721,-165.42247,35.000008,239.561539,false,Manual,22.0",
          ContentES = "Por favor, compórtate... Si quieres sonsacar secretos militares, no necesitas acosar a un simple soldado como yo, solo estoy haciendo guardia.",
          DialogueId = 10110239,
          FacialId = {
            [1] = "200004:Sad01"
          },
          FinalCamera = "78.841797,-97.880859,197.44043,0.000168,-18.601685,-166.822098,35.000011,239.561539,false,Manual,22.0",
          GUID = "194F5698",
          NextDialogue = 10110240,
          SpeakNpcId = 200004,
          Subtitle = "Come on! Cut me some slack... If you're digging for some military secrets, you don't need to corner a mere foot soldier like me — I'm basically just a gatekeeper!",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5698"
        },
        [10110240] = {
          Camera = "24.123047,-69.332031,126.121094,0.000172,2.398667,98.17495,35.000011,177.910553,false,Manual,4.0",
          ContentES = "¿Sabes algo de Henrik Ethelred, el dueño de la Casa de Hypnos al norte de la ciudad? Cualquier cosa sobre él, quiero oírlo todo.",
          DialogueId = 10110240,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F56C2",
          NextDialogue = 10110241,
          SpeakNpcId = 100001,
          Subtitle = "Do you know anything about Henrik Ethelred, the owner of the Hypnos' House in the north of the city? I mean ANYTHING about him, I'd like to hear it all.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F56C2"
        },
        [10110241] = {
          Camera = "121.794922,416.958008,140.132812,0.000136,-2.801443,-106.219742,35.000008,100000.0,false,Disable,2.8",
          ContentES = "Henrik Ethelred... ¿no es solo un posadero? Ah, mi superior sí tiene algo de trato con él. Tiene cierto historial, pero en los últimos años ha sido un ciudadano respetuoso de la ley.",
          DialogueId = 10110241,
          FacialId = {
            [1] = "200004:None"
          },
          FinalCamera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          GUID = "194F56EC",
          NextDialogue = 10110242,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{2}}\n",
          SpeakNpcId = 200004,
          Subtitle = "Henrik Ethelred... isn't he just an inn owner? Oh, my superior does have some connection with him. He's got a bit of a history, but has been a law-abiding citizen these past years.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F56EC"
        },
        [10110242] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          ContentES = "Uf, ese hombre tiene bastante mal genio, no es raro que haya echado a patadas a viajeros. Pero así es él, incluso en su época en su oficio original no era simpático, al menos entonces tenía a su familia que lo moderaba.",
          DialogueId = 10110242,
          GUID = "194F5716",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "Oh, that man's got quite the temper, not a rare occasion he's shut the door on travellers. But that's just how he is — even back in his proper job days, he wasn't a nice guy either, though at least back then he had his family to keep him in check.",
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5716"
        },
        [10110243] = {
          ContentES = "Háblame con más detalle de su “historial”.",
          DialogueId = 10110243,
          GUID = "10110243",
          NextDialogue = 10110246,
          Subtitle = "Please elaborate on his \"history.\""
        },
        [10110244] = {
          ContentES = "Háblame con más detalle de su “oficio original”.",
          DialogueId = 10110244,
          GUID = "10110244.0",
          NextDialogue = 10110251,
          Subtitle = "Please elaborate on his \"proper job.\""
        },
        [10110245] = {
          ContentES = "Háblame con más detalle de su “familia”.",
          DialogueId = 10110245,
          GUID = "10110245.0",
          NextDialogue = 10110254,
          Subtitle = "Please elaborate on his \"family.\""
        },
        [10110246] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          ContentES = "A ver… ¿Cuándo fue eso… catorce, quince años? Henrik Ethelred cometió un asesinato en , en <H>Río Escarlata</> la provincia de Flagson.",
          DialogueId = 10110246,
          GUID = "194F5740",
          NextDialogue = 10110247,
          RelatedWikiId = {
            [1] = 408006
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          Subtitle = "Well, it was... what, some fourteen, fifteen years ago? Henrik Ethelred committed a murder up in Scarletriver, Flagson.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5740"
        },
        [10110247] = {
          Camera = "48.828125,-238.466797,197.088867,0.000132,-14.601796,105.386505,35.000008,394.862823,false,Manual,4.0",
          ContentES = "La víctima era una Charon, y ya mostraba signos de <W>Deterioradora</>, como te dije. No lo consideraron un crimen grave, así que solo cumplió unos meses de prisión antes de ser liberado.",
          DialogueId = 10110247,
          GUID = "194F576A",
          NextDialogue = 10110248,
          SpeakNpcId = 200004,
          Subtitle = "The victim was a Charon, one with signs of Deterioration — like I just said. Not a major crime though, so he only served a few months before getting released.",
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F576A"
        },
        [10110248] = {
          Camera = "11.783203,35.181641,158.039062,0.000169,-12.8009,95.373573,35.000008,83.272263,false,Manual,5.0",
          ContentES = "¿Por qué lo hizo?",
          DialogueId = 10110248,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "194F5794",
          NextDialogue = 10110249,
          SpeakNpcId = 100001,
          Subtitle = "Why would he do that?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5794"
        },
        [10110249] = {
          Camera = "781.091797,122.442383,14.25293,0.00013,1.998233,-169.017654,25.0,182.242599,false,Manual,22",
          ContentES = "…Ni idea. Pero bueno, es humano sentir miedo, incluso odiar a los Deterioradores, ¿no?",
          DialogueId = 10110249,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "781.091797,122.442383,33.219727,0.00013,0.0,-169.01709,25.0,182.242599,false,Manual,22",
          GUID = "194F57BE",
          NextDialogue = 10110250,
          SpeakNpcId = 200004,
          Subtitle = "...I don't know. But everyone would fear and despise a Deteriorator, I guess.",
          TalkActionId = {
            [1] = "200004:Disagree",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F57BE"
        },
        [10110250] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
          ContentES = "Eso es lo que me contó mi superior. Además, fue hace mucho y no ocurrió aquí. Así que si me equivoco en algún detalle, no me culpes, ¿sí?",
          DialogueId = 10110250,
          GUID = "194F57E8",
          NextDialogue = 10110261,
          Scripts = "PlayAnimation{_delay{4},ActorId{200004},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "I just heard this from my superior. It's been a long time and it didn't happen locally, so don't hold it against me if I've got some details wrong!",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F57E8"
        },
        [10110251] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
          ContentES = "Los mayores de Lago Helado saben que Henrik fue, en su día, un <H>médico</> muy prestigioso. Un verdadero profesional con talento, incluso los nobles de la ciudad interior acudían a él.",
          DialogueId = 10110251,
          GUID = "194F5812",
          NextDialogue = 10110252,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          Subtitle = "The older folks in Icelake all know that Henrik was once a renowned doctor. Quite the skilled medic, he was, even the nobles from the inner city would go to him.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5812"
        },
        [10110252] = {
          Camera = "327.693359,662.063477,356.859375,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
          ContentES = "Pero pasó algo, y cerró su consulta en el punto más alto de su fama. Dos años después la reabrió… pero como una “posada”.",
          DialogueId = 10110252,
          FinalCamera = "350.828125,717.59375,368.043945,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
          GUID = "194F583C",
          NextDialogue = 10110253,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "But then something happened, and he shut down his clinic at the height of his fame, only to reopen it as an inn a couple of years later.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F583C"
        },
        [10110253] = {
          Camera = "62.0,13.855469,151.842773,0.000098,1.998315,-117.01268,35.000008,143.588394,false,Manual,5.149117",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Ahora que lo pienso… fue más o menos por la época en que tuvo aquel lío en Río Escarlata…",
          DialogueId = 10110253,
          FinalCamera = "100.847656,-14.870117,151.862305,0.000107,6.598201,-135.012131,35.000011,143.588394,false,Manual,5.149117",
          GUID = "194F5866",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "Oh, come to think of it, that was right around the time he got in trouble in Scarletriver...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5866"
        },
        [10110254] = {
          Camera = "37.912109,160.816406,132.972656,0.000113,2.998043,-103.822327,35.000008,305.385315,false,Manual,2.8",
          ContentES = "Tenía una esposa y una hija. Una familia corriente, nada especial. Pero su esposa murió bastante temprano, y él crió a su hija solo.",
          DialogueId = 10110254,
          GUID = "194F5890",
          NextDialogue = 10110255,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          Subtitle = "He had a wife and a daughter, they were just an ordinary family of three. But then his wife passed away quite early, and he raised his daughter on his own.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5890"
        },
        [10110255] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
          ContentES = "En cuanto a su hija... ¿cómo se llamaba? ¿Heidi? ¿Hayley? Ya no me acuerdo. En fin, se fue con él de viaje a Río Escarlata, pero nunca regresó con él.",
          DialogueId = 10110255,
          GUID = "194F58BA",
          NextDialogue = 10110256,
          RelatedWikiId = {
            [1] = 201006
          },
          SpeakNpcId = 200004,
          Subtitle = "As for his daughter... what's her name? Heidi? Hayley? I don't quite remember — anyway, she went on a trip to Scarletriver with Henrik but never returned with him.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F58BA"
        },
        [10110256] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
          ContentES = "Nunca habla de su hija. Una vez, mi superior le preguntó por ella mientras bebían, y Henrik rompió su copa y se marchó furioso.",
          DialogueId = 10110256,
          GUID = "194F58E4",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "He never talks about his daughter. One year, my superior asked about her over drinks, and Henrik just smashed his glass and stormed off.",
          VoiceName = "voice/$Locale$/story/1002/101102/194F58E4"
        },
        [10110257] = {
          Camera = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
          ContentES = "Te juro que ya te he contado todo lo que sé. ¿Podrías dejarme en paz ahora? Devuélveme el carrete, al menos... Maldición, con lo amable que pareces, ¿cómo puedes ser tan {性别:astuto|astuta}?",
          DialogueId = 10110257,
          GUID = "194F590E",
          NextOptions = {
            [1] = 10110258,
            [2] = 10110259
          },
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200004:n(100001)"}},
PlayAnimation{ActorId{200004},AnimationId{"Talk01_Start"},Duration{2}},
}]],
          SpeakNpcId = 200004,
          Subtitle = "I swear, I've told you everything I know. Can you please let me off now? Just give me the film — damn it, you look nice, how could you be so cunning!",
          VoiceName = "voice/$Locale$/story/1002/101102/194F590E"
        },
        [10110258] = {
          ContentES = "Perdona por antes. En realidad estaba bromeando. No te he sacado ninguna foto de verdad...",
          DialogueId = 10110258,
          GUID = "10110258",
          ImprPlusId = 1009,
          NextDialogue = 10110260,
          Subtitle = "Sorry for earlier. Actually, I was just joking, I didn't really take your picture..."
        },
        [10110259] = {
          ContentES = "Me quedaré con el carrete por ahora. Quizás te lo devuelva la próxima vez que venga a por más información, señor.",
          DialogueId = 10110259,
          GUID = "10110259",
          ImprPlusId = 1006,
          NextDialogue = 10110260,
          Subtitle = "I'll hold onto the film for now. Maybe I'll give it to you next time I come for more info, sir."
        },
        [10110260] = {
          Camera = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
          ContentES = "Hasta la próxima, señor.",
          DialogueId = 10110260,
          ExStoryInfo = "Player",
          GUID = "194F5938",
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.2},TargetPosition{"201.574219,-68.02832,168.996094,0.000123,-2.201465,-165.821976,35.000008,243.340027,false,Manual,4.0"},duration{0}},
SEQ{
LookAt{LookAtDescription{"100001:n(100001)"}},
TurnTo{TurnToDescription{"100001:p(180)"}},   
MoveTo{ActorId{100001},TargetPoint{"P101102Nvzhu3"},MoveSpeed{80},Visibility{"Show"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Well, take care, sir.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5938"
        },
        [10110261] = {
          DialogueId = 10110261,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 10110257,
          GUID = "194F5717",
          NextOptions = {
            [1] = 10110243,
            [2] = 10110244,
            [3] = 10110245
          }
        },
        [10110301] = {
          ContentES = "¿Eh? ¿Te vas así, sin más? ¡Oye, ¿a dónde vas?!",
          DialogueId = 10110301,
          GUID = "194F6142",
          NextDialogue = 10110302,
          SpeakNpcId = 200004,
          Subtitle = "Hey! You're just gonna leave like that? Where are you going?! Oi!",
          VoiceName = "voice/$Locale$/story/1002/101103/194F6142"
        },
        [10110302] = {
          ContentES = "Me prometiste no contarlo a nadie, ¿verdad? Más te vale cumplir tu palabra...",
          DialogueId = 10110302,
          GUID = "194F616C",
          SpeakNpcId = 200004,
          Subtitle = "You promised not to tell anyone, didn't you? You have to stick to your word...",
          VoiceName = "voice/$Locale$/story/1002/101103/194F616C"
        },
        [10110401] = {
          ContentES = "¡Y... Y... ¡Aún sigues aquí!? ¡Me has dado un susto de muerte!",
          DialogueId = 10110401,
          GUID = "194F71AA",
          SpeakNpcId = 200004,
          Subtitle = "Y...Y...You're still here?! Scared me half to death.",
          VoiceName = "voice/$Locale$/story/1002/101104/194F71AA"
        },
        [10110501] = {
          Camera = "668.771606,50.456543,139.82666,0.000123,-1.999995,86.357468,45.0,207.220764,false,Manual,2.5",
          ContentES = "Todo está listo.",
          DialogueId = 10110501,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194F8212",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10110502,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 201007,
            [3] = 405002,
            [4] = 303006
          },
          Scripts = [[
