},
LookAt{_delay{1},LookAtDescription{"100001:n(200021)"}},
CameraMoveTo{_delay{1.6},TargetPosition{"614.092041,-84.750488,127.766602,0.000123,-3.400054,86.35746,35.0,365.6586,false,Manual,2.5"},duration{0}},
CameraMoveTo{_delay{1.7},TargetPosition{"614.092041,-84.750488,156.081787,0.000124,-6.0,86.35746,35.0,364.392914,false,Manual,3.227706"},blend{"easeOutQuad"},duration{3}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "It is all set.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F8212"
        },
        [10110502] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
          ContentES = "Ya arreglé las cosas con un amigo de la ciudad interior, esta noche hará pasar su carruaje por aquí. En cuanto Psyche aparezca, la sacaremos de la ciudad y la ocultaremos por un tiempo. Henrik no se atrevería a asaltar el carruaje de un noble.",
          DialogueId = 10110502,
          GUID = "194F823C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10110503,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Confident_End"},Duration{2}},
PlayAnimation{ActorId{200021},AnimationId{"Talk02_Start"},Duration{2}},
PlayAnimation{ActorId{200021},AnimationId{"Talk02_End"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "I've squared things with a friend from the inner city, he will send his coach around here tonight. Once Psyche shows up, we'll take her out of town and lay low for a while. Henrik wouldn't dare rob a noble's coach.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F823C"
        },
        [10110503] = {
          ContentES = "Después de eso... tendremos que improvisar sobre la marcha.",
          DialogueId = 10110503,
          GUID = "194F8266",
          NextDialogue = 10110504,
          SpeakNpcId = 200021,
          Subtitle = "After that... we'll have to play it by ear.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8266"
        },
        [10110504] = {
          Camera = "597.891357,-27.287598,177.053955,0.000212,-9.60052,80.358948,40.0,340.8461,false,Manual,5.0",
          ContentES = "Realmente tienes una red amplia, ¿no?",
          DialogueId = 10110504,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194F8290",
          NextDialogue = 10110505,
          SpeakNpcId = 100001,
          Subtitle = "You really have a wide network, don't you?",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8290"
        },
        [10110505] = {
          Camera = "722.716003,214.500488,130.546387,0.000153,5.999351,-137.03714,30.0,171.684738,false,Manual,6.0",
          ContentES = "¡Ja! Hay que aprovechar toda la porquería que he vivido estos últimos años. Pero... ¿estás {性别:seguro|segura} de que ella vendrá?",
          DialogueId = 10110505,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194F82BA",
          NextDialogue = 10110506,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Explain01_Start"},Duration{4}},
PlayAnimation{ActorId{200021},AnimationId{"Explain01_End"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Ha, got to make the most of all the cr*p I've been through these years. But are you sure she'll come?",
          VoiceName = "voice/$Locale$/story/1002/101105/194F82BA"
        },
        [10110506] = {
          Camera = "636.023804,126.125488,194.547607,0.000064,-21.999287,69.385223,35.000008,165.235214,false,Manual,22.0",
          ContentES = "... No lo sé. Si no viene, pasaremos al plan B.",
          DialogueId = 10110506,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:None",
            [2] = "100001:None"
          },
          GUID = "194F82E4",
          NextDialogue = 10110507,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...I'm not sure. Anyway, if she doesn't show up, we'll go with plan B.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F82E4"
        },
        [10110507] = {
          Camera = "752.663208,304.167969,134.771973,0.000159,0.799091,-134.831451,30.000008,255.753464,false,Manual,3.0",
          ContentES = "¿Entramos a la Casa de Hypnos y confrontamos a Henrik? Ja, suena como la historia de un héroe de alguna novela barata.",
          DialogueId = 10110507,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194F830E",
          NextDialogue = 10110508,
          SpeakNpcId = 200021,
          Subtitle = "We break into the Hypnos' House and confront Henrik — ha, sounds like the story of a hero from some pulp novel.",
          TalkActionId = {
            [1] = "200021:Angry01_Start",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F830E"
        },
        [10110508] = {
          ContentES = "Pero no te hagas ilusiones. Incluso si logramos salvar a Psyche hoy, ella... no durará mucho. ¿Recuerdas lo que vimos en la Mina? Ese es su destino inevitable.",
          DialogueId = 10110508,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F8338",
          NextDialogue = 10110509,
          SpeakNpcId = 200021,
          Subtitle = "But don't get your hopes up. Even if we manage to save Psyche today, she... won't last much longer. Remember the thing we saw in the pit? That's her inevitable fate.",
          TalkActionId = {
            [1] = "200021:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8338"
        },
        [10110509] = {
          Camera = "597.891357,-27.287598,177.053955,0.000213,-9.60052,80.35907,40.0,340.8461,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "... Lo veremos, paso a paso.",
          DialogueId = 10110509,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200021:None"
          },
          FinalCamera = "595.481689,-41.476074,179.486816,0.000213,-9.60052,80.359016,40.0,340.8461,false,Manual,5.0",
          GUID = "194F8362",
          NextDialogue = 10110510,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...One thing at a time.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F8362"
        },
        [10110510] = {
          Camera = "752.663208,304.167969,134.771973,0.000159,0.799091,-134.831451,30.000008,255.753464,false,Manual,3.0",
          ContentES = "... De acuerdo. Por cierto, los Deterioradores no se supone que sean el trabajo de la Escolta? ¿Qué le habrá pasado a Henrik para llegar hasta aquí?",
          DialogueId = 10110510,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F838C",
          NextDialogue = 10110511,
          SpeakNpcId = 200021,
          Subtitle = "...Right. Speaking of which, aren't the Deteriorators usually handled by the Escort? What on earth has Henrik gone through to end up doing things like this...",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F838C"
        },
        [10110511] = {
          Camera = "594.983521,34.920898,147.270508,0.000067,-8.200632,79.375977,30.000008,567.112122,false,Manual,3.0",
          ContentES = "Creo... que ya entiendo por qué.",
          DialogueId = 10110511,
          ExStoryInfo = "Player",
          FinalCamera = "617.869507,29.944824,148.867676,0.000067,-6.800539,83.778389,30.000008,242.72731,false,Manual,3.0",
          GUID = "194F838D",
          NextOptions = {
            [1] = 10110512
          },
          SpeakNpcId = 100001,
          Subtitle = "I might have figured out why.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F838D"
        },
        [10110512] = {
          ContentES = "(Revelar la información obtenida de Kevin.)",
          DialogueId = 10110512,
          GUID = "10110512.0",
          NextDialogue = 10110513,
          Subtitle = "(Reveal the intel gathered from Kevin.)"
        },
        [10110513] = {
          Camera = "960.668701,-341.848633,606.558594,0.000024,-38.601192,121.190224,30.000002,362.012939,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "... Henrik era médico, pero cerró su consulta sin explicación. Tenía una hija, desaparecida en Río Escarlata. Y en la misma ciudad, mató a una Deterioradora...",
          DialogueId = 10110513,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "896.82605,-237.447266,505.624023,0.000011,-40.001194,121.590363,30.000002,362.012939,false,Manual,22.0",
          GUID = "194F83B6",
          NextDialogue = 10110514,
          SpeakNpcId = 200021,
          Subtitle = "...Henrik used to be a doctor, but he shut down his practice for some reason; he had a daughter, but she went missing in Scarletriver and Henrik murdered a Deteriorator in Scarletriver...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101105/194F83B6"
        },
        [10110514] = {
          Camera = "673.087097,200.460449,158.318604,0.00003,-18.200924,80.989754,30.000013,71.430817,false,Manual,22.0",
          ContentES = "Exacto. Y sobre todo, estos tres eventos ocurrieron en el mismo año. No puede ser una coincidencia.",
          DialogueId = 10110514,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F83E0",
          NextDialogue = 10110515,
          SpeakNpcId = 100001,
          Subtitle = "Right. More importantly, these three events happened in the same year, so they must be connected.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F83E0"
        },
        [10110515] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
          ContentES = "Si los huéspedes de la Casa de Hypnos son realmente todos Deterioradores... Sí, ya veo a dónde quieres llegar.",
          DialogueId = 10110515,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "194F840A",
          NextDialogue = 10110516,
          SpeakNpcId = 200021,
          Subtitle = "And the lodgers at the Hypnos' House are likely all Deteriorators... Hmm, I see what you're getting at.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F840A"
        },
        [10110516] = {
          Camera = "684.15155,260.363281,147.201416,0.000142,-1.401261,-120.639412,30.000002,200.0,false,Manual,3.0",
          ContentES = "La hija de Henrik probablemente fue asesinada en Río Escarlata, posiblemente por un Deteriorador, lo que desató el profundo odio de Henrik hacia ellos, un odio que no ha desaparecido ni después de tantos años...",
          DialogueId = 10110516,
          GUID = "194F8434",
          NextDialogue = 10110517,
          SpeakNpcId = 200021,
          Subtitle = "Henrik's daughter was likely killed in Scarletriver, possibly by a Deteriorator, sparking Henrik's deep-seated hatred towards them, which hasn't faded even after so many years...",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8434"
        },
        [10110517] = {
          ContentES = "Así que, de alguna manera, logró controlar a algunos Deterioradores y administrar su propia forma de justicia... esa es tu conclusión, ¿verdad?",
          DialogueId = 10110517,
          GUID = "194F845E",
          NextDialogue = 10110518,
          SpeakNpcId = 200021,
          Subtitle = "So, he somehow managed to control some of the Deteriorators and administer his own brand of justice — that's your conclusion, right?",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F845E"
        },
        [10110518] = {
          Camera = "649.498047,158.819336,162.394043,0.000159,-15.000577,73.956459,30.000002,106.04982,false,Manual,2.113648",
          ContentES = "...Sí. Pero sea cual sea su motivo, sea cual sea el destino final de los Deterioradores... Debemos—",
          DialogueId = 10110518,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "194F8488",
          NextDialogue = 10110519,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_End"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Angry01_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...Yes. But regardless of what he's gone through, or what the Deteriorators would eventually become, we must—",
          VoiceName = "voice/$Locale$/story/1002/101105/194F8488"
        },
        [10110519] = {
          Camera = "964.300659,-14.221191,117.446289,0.000137,-2.199826,147.753998,20.0,107.293198,false,Manual,15.0",
