}]],
          SpeakNpcId = 200045,
          Subtitle = "Are you... off to find Psyche?",
          VoiceName = "voice/$Locale$/story/1002/101109/194FC3B2"
        },
        [10110902] = {
          Camera = "-231.873047,-73.172028,160.285156,0.000103,-6.596924,20.794041,40.000011,446.663574,false,Manual,5.5",
          ContentES = "Por favor, lleva esto contigo.",
          DialogueId = 10110902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_1.T_Guide_Chapter01_Flower_1'}",
          GUID = "194FC3DC",
          NextDialogue = 10110903,
          SpeakNpcId = 200045,
          Subtitle = "Please take this with you.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC3DC"
        },
        [10110903] = {
          Camera = "64.572266,91.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          ContentES = "Psyche nos regalaba flores con frecuencia. Aunque algunos ya apenas podemos olerlas o distinguirlas, ella seguía haciéndolo, diciendo que las flores traen buena suerte.",
          DialogueId = 10110903,
          FinalCamera = "64.572266,141.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          GUID = "194FC406",
          LookAt = {
            [1] = "200045:p(P10106801)"
          },
          NextDialogue = 10110904,
          SpeakNpcId = 200045,
          Subtitle = "Psyche often gave us flowers. Even though some of us can barely smell or see them clearly anymore, she kept doing it, saying flowers bring good luck.",
          TalkActionId = {
            [1] = "200045:Talk02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC406"
        },
        [10110904] = {
          Camera = "-64.513672,-54.797607,154.447266,0.000147,-5.19662,21.383118,35.000008,170.88736,false,Manual,3.0",
          ContentES = "…Pero cuando quise devolverle su amabilidad, ya era demasiado tarde.",
          DialogueId = 10110904,
          GUID = "194FC430",
          NextDialogue = 10110905,
          SpeakNpcId = 200045,
          Subtitle = "...But by the time I wanted to return her kindness, it was already too late.",
          TalkActionId = {
            [1] = "200045:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC430"
        },
        [10110905] = {
          Camera = "-230.103516,-78.412262,153.914062,0.000093,-5.797054,21.191561,35.000008,351.556366,false,Manual,4.0",
          ContentES = "Por favor, llévale esta flor. Es su favorita.",
          DialogueId = 10110905,
          GUID = "194FC45A",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110906,
          SpeakNpcId = 200045,
