        },
        [10111004] = {
          ContentES = "¡Argh—!!",
          DialogueId = 10111004,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "194FD498",
          SpeakNpcId = 100001,
          Subtitle = "Argh—!!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD498"
        },
        [10111005] = {
          ContentES = "El viento está demasiado fuerte... no puedo acercarme...",
          DialogueId = 10111005,
          ExStoryInfo = "Player",
          GUID = "194FD499",
          SpeakNpcId = 100001,
          Subtitle = "The wind's too strong, can't get any closer...!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD499"
        },
        [10111006] = {
          ContentES = "¡Vuelve, es demasiado peligroso! ¡Maldita sea... si esto sigue así, todos vamos a morir!",
          DialogueId = 10111006,
          Duration = 4.5,
          GUID = "194FD500",
          SpeakNpcId = 200021,
          Subtitle = "It's dangerous! Stay back here! Damn it, we're all doomed if this keeps up...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD500"
        },
        [10111007] = {
          ContentES = "Ha perdido la razón. ¡Prepárense para el combate!",
          DialogueId = 10111007,
          Duration = 2.5,
          GUID = "194FD516",
          SpeakNpcId = 200021,
          Subtitle = "She's lost her mind... Be ready to fight!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD516"
        },
        [10111101] = {
          ContentES = "Psyche, ¿me oyes?",
          DialogueId = 10111101,
          ExStoryInfo = "Player",
          GUID = "194FE482",
          NextDialogue = 10111102,
          SpeakNpcId = 100001,
          Subtitle = "Psyche, can you hear me?",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE482"
        },
        [10111102] = {
          ContentES = "Respóndeme...",
          DialogueId = 10111102,
          ExStoryInfo = "Player",
          GUID = "194FE4AC",
          NextDialogue = 10111103,
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4AC"
        },
        [10111103] = {
          ContentES = "Tú misma lo dijiste, hay tanto que quieres hacer...",
          DialogueId = 10111103,
          ExStoryInfo = "Player",
          GUID = "194FE4D6",
          NextDialogue = 10111104,
          SpeakNpcId = 100001,
          Subtitle = "You said it yourself, there's so much you want to do...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4D6"
        },
        [10111104] = {
          ContentES = "Dejarás Lago Helado, para descubrir otros lugares nuevos...",
          DialogueId = 10111104,
          ExStoryInfo = "Player",
          GUID = "194FE500",
          NextDialogue = 10111105,
          SpeakNpcId = 100001,
          Subtitle = "You'll leave Icelake for those unseen places—",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE500"
        },
        [10111105] = {
          ContentES = "...Irás a una pequeña isla, donde podrás construir una casa junto al mar...",
          DialogueId = 10111105,
          ExStoryInfo = "Player",
          GUID = "194FE52A",
          NextDialogue = 10111106,
          SpeakNpcId = 100001,
          Subtitle = "...You'll go to a small island, where you can build a house by the sea...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE52A"
        },
        [10111106] = {
          ContentES = "... y plantar flores blancas a su alrededor...",
          DialogueId = 10111106,
          ExStoryInfo = "Player",
          GUID = "194FE554",
          NextDialogue = 10111107,
          SpeakNpcId = 100001,
          Subtitle = "...and grow white flowers around it...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE554"
        },
        [10111107] = {
          ContentES = "... Y bajo un sombrero ancho, hablarás con tus amigos sobre la nieve de Lago Helado...",
          DialogueId = 10111107,
          ExStoryInfo = "Player",
          GUID = "194FE57E",
          NextDialogue = 10111108,
          SpeakNpcId = 100001,
          Subtitle = "...Talk about the snow in Icelake with your friends, while shading yourself with a wide-brimmed sunhat...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE57E"
        },
        [10111108] = {
          ContentES = "Respóndeme, Psyche...",
          DialogueId = 10111108,
          ExStoryInfo = "Player",
          GUID = "194FE5A8",
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE5A8"
        },
        [10111201] = {
          ContentES = "Psyche, estoy aquí para llevarte a casa.",
          DialogueId = 10111201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194FF4EA",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/101127/1950EB02"
        },
        [10111301] = {
          ContentES = "¿Es esto... mi casa?",
          DialogueId = 10111301,
          GUID = "191B889A",
          SpeakNpcId = 200006,
          Subtitle = "Is this... my home?",
          VoiceName = "voice/$Locale$/story/1002/101113/191B889A"
        },
        [10111401] = {
          ContentES = "Cariño, mira... Psyche nos sonríe.",
          DialogueId = 10111401,
          GUID = "191B88C4",
          NextDialogue = 10111402,
          SpeakNpcId = 200039,
          Subtitle = "Honey, look, Psyche is smiling at us.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88C4"
        },
        [10111402] = {
          ContentES = "...Me pregunto si el nacimiento de esta niña en este mundo fue una bendición o una maldición.",
          DialogueId = 10111402,
          GUID = "191B88EE",
          NextDialogue = 10111403,
          SpeakNpcId = 200038,
          Subtitle = "...I wonder whether this child's birth in this world was a blessing or a curse.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88EE"
        },
        [10111403] = {
          ContentES = "..Sí, no nacimos bajo bendiciones.",
          DialogueId = 10111403,
          GUID = "191B8918",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...Yes, we weren't born with blessings.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B8918"
        },
        [10111501] = {
          ContentES = "¡Mamá! Le prometí a Psyche que hoy la invitaría a jugar con mis bloques...",
          DialogueId = 10111501,
          GUID = "191BB9D2",
          NextDialogue = 10111502,
          SpeakNpcId = 200040,
          Subtitle = "Mum! I promised Psyche I'd bring her home today to play with blocks...",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9D2"
        },
        [10111502] = {
          ContentES = "¿Quién te dijo que jugaras con ella? Te he repetido mil veces que evites a esa gente impura. ¿Quieres morir, alcanzado por la magia negra?",
          DialogueId = 10111502,
          GUID = "191BB9FC",
          NextDialogue = 10111503,
          SpeakNpcId = 200041,
          Subtitle = "Who says you can play with her? How many times have I told you to stay away from these unclean people? Do you want to get killed by dark magic?",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9FC"
        },
        [10111503] = {
          ContentES = "Mira esto... estos bloques están todos sucios. ¡Tíralos ahora mismo!",
          DialogueId = 10111503,
          GUID = "191BBA26",
          SpeakNpcId = 200041,
          Subtitle = "Ugh, now these blocks are all dirty. Throw them away now!",
          VoiceName = "voice/$Locale$/story/1002/101115/191BBA26"
        },
        [10111601] = {
          ContentES = "Aquel día... llena de injusticia e incomprensión, me lavé toda la noche... hasta que mi piel empezó a sangrar.",
          DialogueId = 10111601,
          GUID = "191BBA50",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "That day, feeling wronged and confused, I bathed all night until my skin bled.",
          VoiceName = "voice/$Locale$/story/1002/101116/191BBA50"
        },
        [10111701] = {
          ContentES = "¡No, señor, está equivocado! ¡Mi hija es una buena chica, nunca habría robado el collar de un cliente, mucho menos esconderlo en una maceta!",
          DialogueId = 10111701,
          GUID = "191BCA3A",
          NextDialogue = 10111702,
          SpeakNpcId = 200039,
          Subtitle = "Please, sir, you've got it all wrong. My daughter is a good girl — she knows better than to steal a necklace and hide it in a flowerpot!",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA3A"
        },
        [10111702] = {
          ContentES = "¡Basta! ¿Hay algún niño de Charon que tenga las manos limpias?",
          DialogueId = 10111702,
          GUID = "191BCA64",
          NextDialogue = 10111703,
          SpeakNpcId = 200043,
          Subtitle = "Save it. Is there even one Charon kid who isn't light-fingered?",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA64"
        },
        [10111703] = {
          ContentES = "Bien, si es tan inocente, que lo demuestre: que rompa todos los maceteros aquí. Así se aclararán las cosas.",
          DialogueId = 10111703,
          GUID = "191BCA8E",
          NextDialogue = 10111704,
          SpeakNpcId = 200044,
          Subtitle = "Alright, if she's so innocent, she can prove it: just smash all the flowerpots here. That'll clear things up.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA8E"
        },
        [10111704] = {
          ContentES = "...Todo es porque somos los “Hijos del Demonio.”",
          DialogueId = 10111704,
          GUID = "191BDAA2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's all because, we are \"demon's children.\"",
          VoiceName = "voice/$Locale$/story/1002/101117/191BDAA2"
        },
        [10111801] = {
          ContentES = "Aaah... ¿por qué...?",
          DialogueId = 10111801,
          GUID = "191BDACC",
          NextDialogue = 10111802,
          SpeakNpcId = 200039,
          Subtitle = "Aargh... why...",
          VoiceName = "voice/$Locale$/story/1002/101118/191BDACC"
        }
      }
    end
  },
  {
