}]],
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "What are you thinking? What are you furious about? — Ah, I see. You crave to vanquish me. You still harbor the naive thought that by eliminating me, your life will return to those amusingly peaceful and tranquil days.",
          TalkActionId = {
            [1] = "200052:Talk01_Start",
            [2] = "200006:Sigh_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E7"
        },
        [10112105] = {
          Camera = "-804.349976,160.710938,171.24585,0.000067,-3.400027,138.804932,40.0,569.174194,false,Manual,7.455382",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Te equivocas. El Deterioro es irreversible. <W>Cuando yo muera, tú desaparecerás conmigo.</>",
          DialogueId = 10112105,
          FacialId = {
            [1] = "200006:Sad01"
          },
          FinalCamera = "-805.726074,158.953125,171.24585,0.000065,-2.80005,141.806,40.0,194.718216,false,Manual,7.455382",
          GUID = "195088E8",
          NextDialogue = 10112106,
          Scripts = [[
