PlayAnimation{_delay{3},ActorId{200052},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "Well, you're wrong. Deterioration is irreversible. Once I die, you'll vanish along with me!",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E8"
        },
        [10112106] = {
          Camera = "-1489.189087,539.398438,161.23291,0.000026,0.999865,-3.197937,80.0,363.719818,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Ríndete a mí… entrégate a los <W>instintos</> de este cuerpo. Conviértete en la bestia… y nada de esta absurda realidad podrá volver a herirte.",
          DialogueId = 10112106,
          FinalCamera = "-1433.880493,544.535156,162.192383,0.000026,1.599849,-1.997895,80.0,388.982208,false,Manual,4.0",
          GUID = "195088E9",
          LookAt = {
            [1] = "200052:n(200006)",
            [2] = "200006:n(200052)"
          },
          NextDialogue = 10112107,
          Scripts = [[
PARA{
SetLocation{_delay{0.1},ActorId{200052},TargetPoint{"101121Point5"},Visibility{"Show"}},
SetRotation{SetRotationDescription{"200052:p(-180)"}},
SEQ{
PlayAnimation{_delay{2},ActorId{200006},AnimationId{"Explain02_Start"},Duration{1}},
