}
}]],
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "Just embrace me, and yield to the primal urges of this flesh. Be a beast... none of this absurdity can hurt you anymore...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E9"
        },
        [10112107] = {
