          CameraBlendCurve = "easeInOutQuad",
          ContentES = "“Hija del demonio.”",
          DialogueId = 10112107,
          FacialId = {
            [1] = "200006:Sad02"
          },
          FinalCamera = "-1874.200439,1531.488281,1721.400635,0.000162,-50.799793,-52.39386,85.0,978.607666,false,Manual,22.0",
