        },
        [10112201] = {
          ContentES = "Conviértete en la bestia... hija del demonio...",
          DialogueId = 10112201,
          GUID = "195098FA",
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "Just be a beast... you demon's child...",
