        },
        [10112301] = {
          ContentES = "... Se acabó.",
          DialogueId = 10112301,
          Duration = 2.2,
          GUID = "1950A962",
          SpeakNpcId = 200006,
          Subtitle = "Right... My time... ",
          VoiceName = "voice/$Locale$/story/1002/101123/1950A962"
        },
        [10112302] = {
          ContentES = "... Mi tiempo ha terminado...",
          DialogueId = 10112302,
          Duration = 2,
          GUID = "1950A98C",
          SpeakNpcId = 200006,
          Subtitle = "Has already... come to an end.",
