        },
        [10112304] = {
          ContentES = "Levántate...",
          DialogueId = 10112304,
          Duration = 1.1,
          ExStoryInfo = "Player",
          GUID = "1950A9E0",
          SpeakNpcId = 100001,
          Subtitle = "Stand up...",
          VoiceName = "voice/$Locale$/story/1002/101123/1950A9E0"
        },
        [10112305] = {
          ContentES = "¡No te rindas ante este mundo frío y sin alma!",
          DialogueId = 10112305,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1950AA0A",
          SpeakNpcId = 100001,
          Subtitle = "Don't yield to this cold, unfeeling world!",
