          GUID = "1950AA34",
          SpeakNpcId = 200006,
          Subtitle = "I...",
          VoiceName = "voice/$Locale$/story/1002/101123/1950AA34"
        },
        [10112401] = {
          Content = "赛琪，不要放弃。",
          DialogueId = 10112401,
          ExStoryInfo = "Player",
          GUID = "1950B9CA",
          NextDialogue = 10112402,
          SpeakNpcId = 100001,
          Subtitle = "Psyche, don't lose hope.",
