        },
        [10112402] = {
          Content = "是你……({nickname}……）",
          DialogueId = 10112402,
          ExStoryInfo = "Player",
          GUID = "1950B9F4",
          NextDialogue = 10112403,
          SpeakNpcId = 200006,
          Subtitle = "It's you...",
