        [10113210] = {
          Camera = "2709.152344,918.375,-499.61203,-0.0,14.99999,-161.997604,25.0,100000.0,false,Manual,22.0",
          ContentES = "Nacemos para desaparecer, nos encontramos solo para separarnos. Lo único eterno en este mundo... es el olvido.",
