        [10113301] = {
          ContentES = "En este sueño que se derrumba, esa voz resuena una vez más a través del viento.",
          DialogueId = 10113301,
          Duration = 3.5,
          GUID = "19514D72",
          NextDialogue = 10113302,
          Subtitle = "Once again, in the collapsing dream, that voice whispered through the wind.",
