          CameraBlendCurve = "easeInQuad",
          ContentES = "Bueno, {性别:los Phoxcazadores|las Phoxcazadoras} siempre lidiamos con imprevistos. {性别:Tranquilo|Tranquila}, yo te cubro.",
          DialogueId = 10113505,
          FinalCamera = "1020.636719,17.000244,70.82959,0.0,0.0,-179.999985,25.0,674.169678,false,Manual,2.0",
