          SpeakNpcName = "UI_Npc_Name_Boy_3",
          Subtitle = "Over here! Mr Henrik's in his office!",
          VoiceName = "voice/$Locale$/story/1002/101147/19523322"
        },
        [10114801] = {
          Content = "先抓紧离开这儿吧。",
          DialogueId = 10114801,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952438A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Let's get out of here.",
          VoiceName = "voice/$Locale$/story/1002/101148/1952438A"
        },
        [10114901] = {
          Content = "请一定要找到她，拜托了……",
          DialogueId = 10114901,
          GUID = "195253F2",
          SpeakNpcId = 200045,
          Subtitle = "Please find her... I'm begging you...",
          VoiceName = "voice/$Locale$/story/1002/101149/195253F2"
        },
        [10115001] = {
          Content = "……赛琪杀了恩里克……为什么……会这样……",
          DialogueId = 10115001,
          GUID = "1952645A",
          NextDialogue = 10115002,
          SpeakNpcId = 700049,
          Subtitle = "Psyche killed Henrik... Why... How did this happen...?",
          VoiceName = "voice/$Locale$/story/1002/101150/1952645A"
        },
        [10115002] = {
          Content = "赛琪永远都在笑着……恩里克先生虽然话不多，但总是像父亲一样照料我们……他们明明都是那么好的人啊……",
          DialogueId = 10115002,
          GUID = "19526484",
          SpeakNpcId = 700049,
          Subtitle = "Psyche was so sweet, always smiling... And even though Mr Henrik didn't talk much, he cared for us like a father... They were such good people...",
          VoiceName = "voice/$Locale$/story/1002/101150/19526484"
        },
        [10115101] = {
          Content = "恩里克先生一直都太累了。或许对他来说，这样的结局……也不错。",
          DialogueId = 10115101,
          GUID = "195274C2",
          SpeakNpcId = 200019,
          Subtitle = "Mr Henrik must've been exhausted... Maybe this is somewhat a merciful release.",
          VoiceName = "voice/$Locale$/story/1002/101151/195274C2"
        },
        [10115201] = {
          Content = "白，还记得赛琪是往哪个方向跑的吗？",
          DialogueId = 10115201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952852A",
          NextDialogue = 10115202,
          SpeakNpcId = 100001,
          Subtitle = "Snow, do you remember which way Psyche went?",
          VoiceName = "voice/$Locale$/story/1002/101152/1952852A"
        },
        [10115202] = {
          Content = "当然记得，我的记忆不会出错！她是往城门的方向跑的！",
          DialogueId = 10115202,
          Duration = 4,
          GUID = "19528554",
          NextDialogue = 10115203,
          SpeakNpcId = 200002,
          Subtitle = "Of course, I have a good memory! She ran towards the city gate!",
          VoiceName = "voice/$Locale$/story/1002/101152/19528554"
        },
        [10115203] = {
          Content = "……她出城了？",
          DialogueId = 10115203,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952857E",
          NextDialogue = 10115204,
          SpeakNpcId = 100001,
          Subtitle = "...She left the city?",
          VoiceName = "voice/$Locale$/story/1002/101152/1952857E"
        },
        [10115204] = {
          Content = "好，我们也跟上，去城外。",
          DialogueId = 10115204,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "195285A8",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's head out and catch up to her.",
          VoiceName = "voice/$Locale$/story/1002/101152/195285A8"
        },
        [10115301] = {
          ContentES = "¡Qué viento! ¡Aaah, voy a salir volando!",
          DialogueId = 10115301,
          Duration = 4,
          GUID = "19529592",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10115302,
          SpeakNpcId = 200002,
          Subtitle = "This wind is so strong! Whoa, I feel like it's going to blow me away—",
          VoiceName = "voice/$Locale$/story/1002/101153/19529592"
        },
        [10115302] = {
          ContentES = "¡Tengan cuidado, ustedes dos!",
          DialogueId = 10115302,
          Duration = 4,
          GUID = "195295BC",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Be careful, you two!",
          VoiceName = "voice/$Locale$/story/1002/101153/195295BC"
        },
        [10115401] = {
          ContentES = "Es el camino más rápido. Crucemos por el hielo flotante.",
          DialogueId = 10115401,
          Duration = 4,
          GUID = "1952A5FA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10115402,
          SpeakNpcId = 200021,
          Subtitle = "This is the quickest way. Let's cross the floating ice.",
          VoiceName = "voice/$Locale$/story/1002/101154/1952A5FA"
        },
        [10115402] = {
          ContentES = "Cuidado, el agua está bastante profunda aquí.",
          DialogueId = 10115402,
          Duration = 4,
          GUID = "1952A624",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10115403,
          SpeakNpcId = 200021,
          Subtitle = "Watch your step — the water's quite deep here.",
          VoiceName = "voice/$Locale$/story/1002/101154/1952A624"
        },
        [10115403] = {
          ContentES = "...Psyche, espérame.",
          DialogueId = 10115403,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952A64E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "...Hang in there, Psyche. I'm coming.",
          VoiceName = "voice/$Locale$/story/1002/101154/1952A64E"
        },
        [10115501] = {
          ContentES = "Al mismo tiempo, en la capital imperial, Dismania.",
          DialogueId = 10115501,
          Duration = 4,
          GUID = "1952B662",
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "Meanwhile, in Dismania, the Imperial Capital...",
          VoiceName = "voice/$Locale$/story/1002/101155/1952B662"
        },
        [10115601] = {
          Content = "突然，恩里克出现了",
          DialogueId = 10115601,
          GUID = "1952C6CA",
          VoiceName = "voice/$Locale$/story/1002/101156/1952C6CA"
        },
        [10115701] = {
          Content = "一个熟悉的少女叫住了一行人",
          DialogueId = 10115701,
          GUID = "1952D732",
          VoiceName = "voice/$Locale$/story/1002/101157/1952D732"
        },
        [10115801] = {
          ContentES = "(Ya informé a Outsider y a Nieve de todo lo ocurrido hoy.)",
          DialogueId = 10115801,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1952E79A",
          IsBlack = 1,
          NextDialogue = 10115802,
          SpeakNpcId = 100001,
          Subtitle = "(I've filled in Outsider and Snow on everything that happened today.)",
          VoiceName = "voice/$Locale$/story/1002/101158/1952E79A"
        },
        [10115802] = {
          ContentES = "(Ahora solo queda llegar al punto de encuentro... y esperar.)",
          DialogueId = 10115802,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1952E7C4",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "(Now, all that's left to do is get to the meeting spot... and wait.)",
          VoiceName = "voice/$Locale$/story/1002/101158/1952E7C4"
        },
        [10116701] = {
          Camera = "1254.770752,-2759.531738,887.252197,0.000057,-11.799739,115.599007,35.0,100000.0,false,Disable,2.8",
          DialogueId = 10116701,
          Duration = 4,
          GUID = "19537B42",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/metaldooropen\"},PlayAs2D{true}}",
          VoiceName = "voice/$Locale$/story/1002/101167/19537B42"
        },
        [10116801] = {
          Content = "我们开始狩猎吧！",
          DialogueId = 10116801,
          GUID = "19538BAA",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101168/19538BAA"
        },
        [10116901] = {
          ContentES = "Esas cosas en el suelo... deben ser las trampas de Outsider.",
          DialogueId = 10116901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19539C12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10116902,
          SpeakNpcId = 100001,
          Subtitle = "These things on the ground... must be Outsider's traps.",
          VoiceName = "voice/$Locale$/story/1002/101169/19539C12"
        },
        [10116902] = {
          ContentES = "…Nada mal. No pensaba que Outsider tuviera ese tipo de talento.",
          DialogueId = 10116902,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19539C3C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "...This is really something. I didn't know Outsider had such a knack for this.",
          VoiceName = "voice/$Locale$/story/1002/101169/19539C3C"
        },
        [10117001] = {
          ContentES = "¿Qué está pasando aquí?",
          DialogueId = 10117001,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1953AC7A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117002,
          SpeakNpcId = 100001,
          Subtitle = "What's going on here?",
          VoiceName = "voice/$Locale$/story/1002/101170/1953AC7A"
        },
        [10117002] = {
          ContentES = "Ah, pues… hice un poco de ruido mientras ajustaba esa cosa y estos monstruítos han venido a buscarme…",
          DialogueId = 10117002,
          Duration = 6,
          GUID = "1953ACA4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10117003,
          SpeakNpcId = 200021,
          Subtitle = "Ah, well, I made a bit of noise while tweaking that thing and these little critters just came at me...",
          VoiceName = "voice/$Locale$/story/1002/101170/1953ACA4"
        },
        [10117003] = {
          ContentES = "¡Vamos, {性别:amigo|amiga}, échame una mano!",
          DialogueId = 10117003,
          Duration = 4,
          GUID = "1953ACCE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10117004,
          SpeakNpcId = 200021,
          Subtitle = "Come on, my friend, help me out here!",
          VoiceName = "voice/$Locale$/story/1002/101170/1953ACCE"
        },
        [10117004] = {
          ContentES = "¡Te lo mereces! …Venga.",
          DialogueId = 10117004,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1953ACF8",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Serves you right! ...Fine.",
          VoiceName = "voice/$Locale$/story/1002/101170/1953ACF8"
        },
        [10117101] = {
          ContentES = "¡Empecemos a buscar hacia el oeste!",
          DialogueId = 10117101,
          Duration = 3,
          GUID = "1953BCE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10117102,
          SpeakNpcId = 200011,
          Subtitle = "Let's start by searching to the west.",
          VoiceName = "voice/$Locale$/story/1002/101171/1953BCE2"
        },
        [10117102] = {
          ContentES = "El ladrón tiene el cabello negro y llevaba... ¿una camiseta azul? Creo.",
          DialogueId = 10117102,
          Duration = 3,
          GUID = "1953BD0C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "The thief had dark hair, and was wearing... a blue top, I think.",
          VoiceName = "voice/$Locale$/story/1002/101171/1953BD0C"
        },
        [10117201] = {
          ContentES = "¡Oh... es... ¡ ¡Es el señor Badi de los barrios bajos! Tal vez vio algo.",
          DialogueId = 10117201,
          Duration = 3,
          GUID = "1953CD4A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "Oh look! It's Mr Badi from the slums! Maybe he saw something.",
          VoiceName = "voice/$Locale$/story/1002/101172/1953CD4A"
        },
        [10117301] = {
