        [10117302] = {
          Camera = "-192.958298,199.304382,104.51123,0.000078,1.000431,-68.603432,43.300995,474.195221,false,Manual,2.6",
          ContentES = "¡Oh, es nuestra pequeña Princesa del Basurero! ¿Cómo va la cosecha de hoy? Veo que tienes dos ayudantes para apoyarte.",
          DialogueId = 10117302,
          ExStoryInfo = "Player",
