          },
          NextDialogue = 10117303,
          Scripts = [[
PARA{
LookAt{_delay{3},LookAtDescription{"200054:n(100001)"}}
}]],
          SpeakNpcId = 200054,
          Subtitle = "Oh, it's our little Princess Rubbish Bin! How's today's haul? I see you've got two little sidekicks to help you.",
          VoiceName = "voice/$Locale$/story/1002/101173/1953DDB2"
        },
        [10117303] = {
          Camera = "99.868393,-250.259125,175.274902,0.000025,-25.999838,135.993896,35.0,246.462189,false,Manual,2.6",
          ContentES = "¡No soy una ayudante! ¡Soy la Reina Demonio!",
          DialogueId = 10117303,
