            [1] = "200002:Confident_Start",
            [2] = "200011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101173/1953DE30"
        },
        [10117306] = {
          Camera = "114.257248,-212.611359,148.254395,0.000174,-12.397339,160.570602,24.0,208.790619,false,Manual,2.5",
          ContentES = "Jajaja... dejemos eso de lado por ahora. Señor Badi, ¿no ha visto pasar por aquí a un Charon de cabello negro y camiseta azul?",
          DialogueId = 10117306,
          FacialId = {
            [1] = "200011:Ahaha02"
          },
          GUID = "1953DE5A",
          LookAt = {
            [1] = "200054:n(200011)",
            [2] = "100001:n(200054)"
          },
          NextDialogue = 10117307,
          Scripts = [[
SEQ{
LookAt{_delay{1},LookAtDescription{"200011:n(200054)"}},
PlayAnimation{_delay{1},ActorId{200011},AnimationId{"Explain01_Start"},Duration{2}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Hahaha... let's not get hung up on titles for now... Mr Badi, did you happen to see a Charon man in a blue shirt with dark hair just now?",
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = "200011:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101173/1953DE5A"
        },
        [10117307] = {
          ContentES = "Sí, un joven acaba de pasar. Todo torpe, sin mirar por dónde caminaba, ¡fue directo al basurero en <H>Zona Nebulosa</>! Espera... ¿no estará robándote tu sustento?",
          DialogueId = 10117307,
          GUID = "1953DE84",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10117307.T_Story_Recall_10117307'",
          NextDialogue = 10117308,
          SpeakNpcId = 200054,
          Subtitle = "I think so... A young man just came barreling down the street — clumsy kid, wasn't even watching where he was going, headed straight for the rubbish bin in the Mist Aken! Wait, was he trying to poach on your turf?",
          VoiceName = "voice/$Locale$/story/1002/101173/1953DE84"
        },
        [10117308] = {
          ContentES = "¡Eh... más o menos! ¡Gracias, lo persigo!",
          DialogueId = 10117308,
          FacialId = {
            [1] = "200011:Happy01"
          },
          GUID = "1953DEAE",
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{200011},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{ActorId{200011},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Um, in a way! Thanks, I'm going after him.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101173/1953DEAE"
        },
        [10117401] = {
          ContentES = "El basurero en Zona Nebulosa...",
          DialogueId = 10117401,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1953EE1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117402,
          SpeakNpcId = 100001,
          Subtitle = "...The rubbish bin in the Mist Aken."
        },
        [10117402] = {
          ContentES = "¡Se refería al gran basurero nº 3! ¡Sígueme!",
          DialogueId = 10117402,
          Duration = 3,
          GUID = "1953EE44",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "He meant Big Bin No. 3! Now come with me!",
          VoiceName = "voice/$Locale$/story/1002/101174/1953EE44"
        },
        [10117501] = {
          ContentES = "¡A por ellas! Como dice el viejo refrán: “¡Ataca mientras el basurero aún está caliente!”",
          DialogueId = 10117501,
          GUID = "1953FE82",
          SpeakNpcId = 200054,
          Subtitle = "Go get 'em! As the old saying goes, \"Strike while the rubbish is hot!\"",
          VoiceName = "voice/$Locale$/story/1002/101175/1953FE82"
        },
        [10117601] = {
          ContentES = "No hay nadie por aquí.",
          DialogueId = 10117601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19540EEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10117602,
          SpeakNpcId = 100001,
          Subtitle = "It's quiet around here.",
          VoiceName = "voice/$Locale$/story/1002/101176/19540EEA"
        },
        [10117602] = {
          ContentES = "... ¡No hay problema! ¡Mi olfato de detective me dice que hay una pista por aquí!",
          DialogueId = 10117602,
          Duration = 3,
          GUID = "19540F14",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "...No worries! My detective instincts are telling me there's a clue nearby!",
          VoiceName = "voice/$Locale$/story/1002/101176/19540F14"
        }
      }
    end
