          Scripts = "PlayAnimation{_delay{1.5},ActorId{200011},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Check this out — two layers of crates against the wall. The bottom one is skewed, and there are messy footprints all over it — busted!",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/story/1002/101177/19541F52"
        },
        [10117702] = {
          ContentES = "Ejem, según el testimonio de Margie, la testigo, ella acababa de poner estas cajas horizontales esta mañana mientras hacía sus “compras” en el gran basurero nº 3.",
          DialogueId = 10117702,
          GUID = "19541F7C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10117702.T_Story_Recall_10117702'",
          NextDialogue = 10117703,
          SpeakNpcId = 200011,
          Subtitle = "Ahem, according to the statement of Margie the Witness, she just straightened these crates when she did her \"shopping\" at Big Bin No. 3 this morning.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101177/19541F7C"
        },
        [10117703] = {
          Camera = "83.220734,36.439808,97.523438,0.000132,10.199651,-171.604935,35.0,144.288223,false,Manual,2.5",
          ContentES = "Así que, según la deducción de Margie, la Detective Taciturna, ¡el ladrón apiló estas cajas rápidamente para trepar la pared! ¡Seguro que está en el techo!",
          DialogueId = 10117703,
          FinalCamera = "48.795158,31.354404,106.438965,0.000132,10.199651,-171.604935,35.0,107.665878,false,Manual,2.5",
          GUID = "19541FA6",
          NextDialogue = 10117704,
          Scripts = [[
SEQ{
PlayAnimation{_delay{3},ActorId{200011},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{ActorId{200011},AnimationId{"Talk03_Start"},Duration{1}},
PlayFacial{_delay{6},ActorId{200011},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Thus, Margie the Reticent Detective deduces — that desperate thief must have stacked these crates to climb the wall! He's likely hiding on the rooftop right now!",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101177/19541FA6"
        },
        [10117704] = {
          Camera = "-2114.584229,613.182617,98.33252,0.000144,1.892338,-19.423639,35.000008,732.249939,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "¡Oh! ¡Tiene sentido! ¡Vamos a ver allá arriba!",
          DialogueId = 10117704,
          FinalCamera = "-2097.467041,661.715881,98.33252,0.000144,1.892338,-19.423639,35.000008,732.249939,false,DoNotOverride,1.2",
          GUID = "19541FD0",
          SpeakNpcId = 200002,
          Subtitle = "Huh! Smart thinking! Let's get up there and check it out.",
          TalkActionId = {
            [1] = "200011:Talk03_End",
            [2] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101177/19541FD0"
        },
        [10117801] = {
          ContentES = "Entonces, “la Detective Taciturna”, ¿ese es tu título, Margie? No está mal... pero es un poco corto, le falta impacto.",
          DialogueId = 10117801,
          Duration = 3,
          GUID = "19542FBA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10117802,
          SpeakNpcId = 200002,
          Subtitle = "So \"Reticent Detective\"... that's your title, Margie? Sounds cool... A bit short though — could use more punch!",
          VoiceName = "voice/$Locale$/story/1002/101178/19542FBA"
        },
        [10117802] = {
          ContentES = "¡No es mala idea! Entonces, ¿Reina Demonio, tienes alguna idea?",
          DialogueId = 10117802,
          Duration = 3,
          GUID = "19542FE4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117803,
          SpeakNpcId = 200011,
          Subtitle = "Makes sense! Any suggestions, Demon King?",
          VoiceName = "voice/$Locale$/story/1002/101178/19542FE4"
        },
        [10117803] = {
          ContentES = "El viejo de hace un rato te llamó “Princesa del Basurero”... No está mal como título, ¿verdad?",
          DialogueId = 10117803,
          Duration = 3,
          GUID = "1954300E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10117804,
          SpeakNpcId = 200002,
          Subtitle = "That old man back there called you \"Princess Rubbish Bin\"... That's a good one!",
          VoiceName = "voice/$Locale$/story/1002/101178/1954300E"
        },
        [10117804] = {
          ContentES = "“¡Princesa del Basurero ☆ La Detective Taciturna”, ¡suena genial, ¿verdad?!",
          DialogueId = 10117804,
          Duration = 3,
          GUID = "19543038",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10117805,
          SpeakNpcId = 200002,
          Subtitle = "\"Reticent Detective ☆ Princess Rubbish Bin\", has a nice ring to it, doesn't it?",
          VoiceName = "voice/$Locale$/story/1002/101178/19543038"
        },
        [10117805] = {
          ContentES = "¡Argh—! ¡No, no, para! ¡No repitas ese apodo, es demasiado embarazoso!",
          DialogueId = 10117805,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19543062",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "Argh—! Noooo way! Can we please drop that nickname? It's embarrassing!",
          VoiceName = "voice/$Locale$/story/1002/101178/19543062"
        },
        [10117901] = {
          Camera = "441.521088,-620.674683,187.3125,0.000037,-5.799861,111.19696,25.0,850.802856,false,Manual,1.2",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "¿Qué? ¿Hay algo en el basurero?",
          DialogueId = 10117901,
          FinalCamera = "441.521088,-620.674683,164.277588,0.000037,-5.799861,111.19696,25.0,850.802856,false,Manual,1.2",
          GUID = "19544022",
          NextDialogue = 10117902,
          SpeakNpcId = 200011,
          Subtitle = "What, something in the bin?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101179/19544022"
        },
        [10117902] = {
          Camera = "25.164871,87.383209,131.531006,0.000057,-2.19986,-60.40377,25.0,225.91423,false,Manual,1.6",
          ContentES = "Solo quería revisar si no se estaba escondiendo...",
          DialogueId = 10117902,
          ExStoryInfo = "Player",
          GUID = "1954404C",
          LookAt = {
            [1] = "200011:n(100001)",
            [2] = "100001:n(200011)"
          },
          NextDialogue = 10117903,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"P101179Bai1\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Just making sure he wasn't hiding in—",
          VoiceName = "voice/$Locale$/story/1002/101179/1954404C"
        },
        [10117903] = {
          Camera = "14.791107,54.489399,135.432129,0.000058,-2.399801,-63.204136,35.0,189.973221,false,Manual,4.0",
          ContentES = "¡Guau! ¿Es... media botella de vino y un broche antiguo?! ¡Dios mío, eres {性别:el elegido por los dioses del basurero|la elegida por los dioses del basurero} ?!",
          DialogueId = 10117903,
          FacialId = {
            [1] = "200011:Shock01"
          },
          GUID = "19544076",
          LookAt = {
            [1] = "200011:n(200011)"
          },
          NextDialogue = 10117904,
          SpeakNpcId = 200011,
          Subtitle = "Whoooa! Is that... half a bottle of wine and an antique pin!? Wow, aren't you the chosen one blessed by the gods of rubbish bins!?",
          TalkActionId = {
            [1] = "200011:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101179/19544076"
        },
        [10117904] = {
          Camera = "282.696777,274.406219,171.463379,0.000081,-11.800018,-126.601822,20.0,385.634796,false,Manual,1.2",
          ContentES = "Vaya... justo en el peor momento... ¡Espérame!",
          DialogueId = 10117904,
          FacialId = {
            [1] = "100001:Shock01",
            [2] = "200002:Shock01"
          },
          GUID = "195440A0",
          LookAt = {
            [1] = "200002:n(200011)"
          },
          NextDialogue = 10117905,
          Scripts = [[
