          SpeakNpcId = 200011,
          Subtitle = "But this really isn't the best time… just a sec!",
          TalkActionId = {
            [1] = "200011:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101179/195440A0"
        },
        [10117905] = {
          Content = "（玛尔洁从废品堆里扯出两张旧报纸，把刚找到的宝贝小心翼翼地包了起来，放在角落里。）",
          DialogueId = 10117905,
          DisableMouth = 1,
