        [10121101] = {
          Content = "呜呜……呜呜……屁股好痛……不对，膝盖好痛……还是不对！",
          DialogueId = 10121101,
          FacialId = {
            [1] = "200072:Pain01"
          },
          GUID = "19564D22",
          IsBlack = 1,
          NextDialogue = 10121102,
          SpeakNpcId = 200072,
          Subtitle = "Oww... ugh... my butt... no, my knee... wait— No, that's not it either!",
          VoiceName = "voice/$Locale$/story/1002/101211/19564D22"
        },
        [10121102] = {
          Camera = "215.147461,-124.439484,88.77356,0.000102,-11.131883,155.416855,25.0,166.341507,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          Content = "垃圾桶公主你是头先着地的，不应该是脑袋痛吗？",
          DialogueId = 10121102,
          FinalCamera = "203.625488,-119.167603,86.280273,0.000111,-11.131883,155.417694,25.0,430.764191,false,Manual,1.2",
          GUID = "19564D4C",
          LookAt = {
            [1] = "100001:n(200072)",
            [2] = "200002:n(200072)"
          },
          NextDialogue = 10121103,
          Scripts = "CameraMoveTo{_delay{3.1},TargetPosition{\"-181.294434,28.538513,15.04187,0.000143,6.267272,-19.577271,15.0,430.764191,false,Manual,1.2\"},duration{0}}",
          SpeakNpcId = 200002,
          Subtitle = "Princess Rubbish Bin, didn't you land headfirst? I mean, shouldn't your head hurt the most?",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101211/19564D4C"
        },
        [10121103] = {
          Camera = "1531.37793,165.136719,63.804932,0.0,2.99999,-172.401581,30.0,430.764191,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInQuad",
          Content = "啊，是，是吗？哈哈，都差不多，无所谓啦。不要紧，不要紧的……",
          DialogueId = 10121103,
          FacialId = {
            [1] = "200072:Ahaha02"
          },
          FinalCamera = "1531.37793,165.136719,162.799927,-0.0,-2.99999,-172.401581,30.0,430.764191,false,DoNotOverride,1.2",
          GUID = "19564D76",
          NextDialogue = 10121104,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.1},TargetPosition{"265.185059,-156.299149,104.532104,0.0,2.99999,154.600281,30.0,430.764191,false,Manual,1.2"},duration{0}},
SetRotation{SetRotationDescription{"200072:p(74)"}}
}]],
          SpeakNpcId = 200072,
          Subtitle = "Huh? Oh, did I? Haha... Doesn't matter. It's fine, I'm fine, everything's fine...",
          TalkActionId = {
            [1] = "200072:Sigh_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101211/19564D76"
        },
        [10121104] = {
          Camera = "-162.604004,212.414276,115.010376,0.000191,-0.932922,-57.578205,30.0,314.045288,false,Manual,2.390965",
          Content = "瞧你，都开始前言不搭后语了。小仆从，我们先陪垃圾桶公主休息一会儿吧。",
          DialogueId = 10121104,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "19564DA0",
          NextDialogue = 10121105,
          Scripts = [[
PARA{
LookAt{_delay{3},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{4},ActorId{200002},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Look at you — you're spewing nonsense... Little Minion, let's take a break with our Princess Rubbish Bin for a moment.",
          VoiceName = "voice/$Locale$/story/1002/101211/19564DA0"
        },
        [10121105] = {
          Camera = "-6.003906,-21.502472,126.862305,0.000198,0.0,3.000017,15.0,103.310425,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你们先歇着，我去前面看看。",
          DialogueId = 10121105,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-6.003906,-21.502472,126.862305,0.000198,2.99999,8.000016,15.0,277.764099,false,Manual,1.2",
          GUID = "19564DCA",
          NextDialogue = 10121106,
          SpeakNpcId = 100001,
          Subtitle = "You two catch your breath here. I'll check things out up ahead.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101211/19564DCA"
        },
        [10121106] = {
          Camera = "1091.49707,610.666626,381.11792,0.000245,-14.133245,-148.57019,15.0,30.486124,false,Manual,2.46058",
          Content = "你要小心……卑鄙的狗东西会用陷阱……",
          DialogueId = 10121106,
          FacialId = {
            [1] = "200072:Unhappy02"
          },
          FinalCamera = "1111.879395,577.317749,381.11792,0.000243,-14.133259,-148.570206,15.0,288.134674,false,Manual,1.2",
          GUID = "19564DF4",
          NextDialogue = 10121107,
          SpeakNpcId = 200072,
          Subtitle = "Be careful... that slippery thief might've rigged this place with traps...",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101211/19564DF4"
        },
        [10121107] = {
          Camera = "85.51416,-96.30043,125.066162,0.000233,-0.732729,147.629822,35.0,198.376389,false,Manual,1.2",
          Content = "原来是脑袋先着地吗……还好有这顶万能的锅子。",
          DialogueId = 10121107,
          FacialId = {
            [1] = "200072:Ahaha02"
          },
          GUID = "19564E1E",
          SpeakNpcId = 200072,
          Subtitle = "Ugh... so I did land on my head... Well, guess my trusty pot helmet saved me.",
          TalkActionId = {
            [1] = "200072:SpecialHoldHelmet_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101211/19564E1E"
        },
        [10121201] = {
          Content = "这些湿漉漉的脚印，看尺寸，应该就是那个贼留下的吧。",
          DialogueId = 10121201,
          GUID = "19565D8A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10121202,
          SpeakNpcId = 100001,
          Subtitle = "(Wet footprints... Judging by the size, they must belong to that thief.)",
          VoiceName = "voice/$Locale$/story/1002/101212/19565D8A"
        },
        [10121202] = {
          Content = "唔，这些秽兽是被刚刚的爆炸声引来的吗？",
          DialogueId = 10121202,
          GUID = "19565D8B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... did the explosion just now draw in these Filthoids?)",
          VoiceName = "voice/$Locale$/story/1002/101212/19565D8B"
        },
        [10121301] = {
          Content = "总觉得这块木板怪怪的，也许不要踩为好。",
          DialogueId = 10121301,
          GUID = "19566DF2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(That board looks... off. Probably best not to step on it.)",
          VoiceName = "voice/$Locale$/story/1002/101213/19566DF2"
        },
        [10121302] = {
          Content = "是爆炸声！小仆从，你也中陷阱了吗？！",
          DialogueId = 10121302,
          GUID = "19566DF3",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10121303,
          SpeakNpcId = 200002,
          Subtitle = "Whoa! Was that an explosion!? Little Minion, are you alright!?",
          VoiceName = "voice/$Locale$/story/1002/101213/19566DF3"
        },
        [10121303] = {
          Content = "没事！咳，我只是想试试这块木板牢不牢固。",
          DialogueId = 10121303,
          GUID = "19566DF4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = " I'm fine!  Ahem... I just wanted to, uh, check if this board was safe to step on.",
          VoiceName = "voice/$Locale$/story/1002/101213/19566DF4"
        },
        [10121401] = {
          Camera = "178.257812,-350.6875,109.97998,0.000151,-7.200406,133.796951,12.0,269.704346,false,DoNotOverride,10.0",
          Content = "又是你们？！逼老子动真格的？",
          DialogueId = 10121401,
          GUID = "19567E5A",
          SpeakNpcId = 200053,
          Subtitle = "You again!? Alright, you asked for this—",
          VoiceName = "voice/$Locale$/story/1002/101214/19567E5A"
        },
        [10121501] = {
          Content = "咳、咳……！呛死我了……",
          DialogueId = 10121501,
          GUID = "19568EC2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10121502,
          SpeakNpcId = 100001,
          Subtitle = "*cough* *cough*...! This is really choking...",
          VoiceName = "voice/$Locale$/story/1002/101215/19568EC2"
        },
        [10121502] = {
          Content = "（这家伙是个移动杂货铺吗，身上什么都有。该不会把冰湖城偷了个遍吧？）",
          DialogueId = 10121502,
          DisableMouth = 1,
          GUID = "19568EEC",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(What is this guy — a walking convenience store? Where did he get all these gadgets...? Did he loot half of Icelake?)",
          VoiceName = "voice/$Locale$/story/1002/101215/19568EEC"
        },
        [10121601] = {
