        [10121603] = {
          Camera = "-1174.581055,810.613037,73.110962,0.0,0.0,-36.004082,40.0,851.326477,false,Manual,1.2",
          Content = "玛尔洁？你的屁股、膝盖和脑袋还痛吗？",
          DialogueId = 10121603,
          FinalCamera = "-1188.942383,790.815674,73.110962,0.0,0.0,-36.004082,40.0,851.326477,false,Manual,1.2",
          GUID = "19569F7E",
          NextDialogue = 10121604,
          SpeakNpcId = 100001,
          Subtitle = "Margie, how're your hips, knees, and head? Are you okay?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101216/19569F7E"
        },
        [10121604] = {
          Camera = "95.899414,-112.459473,140.34082,0.000024,-9.200435,147.595261,35.0,212.336533,false,Manual,4.0",
          Content = "没事啦没事啦，我可是有这顶万用无敌的多功能锅子——咳，头盔护体呢。我们走！",
          DialogueId = 10121604,
          GUID = "19569FA8",
          NextDialogue = 10121605,
          Scripts = "PlayAnimation{_delay{5},ActorId{200011},AnimationId{\"SpecialHoldHelmet_End\"},Duration{0}}",
          SpeakNpcId = 200011,
          Subtitle = "Yeah, I'm all good! I've got my ultra-durable, all-purpose, life-saving pot helmet protecting me! Let's move!",
          TalkActionId = {
            [1] = "200011:SpecialHoldHelmet_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101216/19569FA8"
        },
        [10121605] = {
          Camera = "-1100.842773,2782.422852,166.54071,0.000083,-2.001068,-70.194328,50.0,1557.85144,false,Manual,1.2",
          Content = "我想想……嗯，《下水道维修手册》还写过，下水道的每扇门都配有备用钥匙，平时就放在门附近。我们可以在周围找找。",
          DialogueId = 10121605,
          FinalCamera = "-1100.842773,2782.422852,251.706909,0.000086,-4.000004,-70.194374,50.0,1557.85144,false,Manual,1.2",
          GUID = "19569FD2",
          SpeakNpcId = 200011,
          Subtitle = "Hmm... The Sewer Maintenance Manual also mentioned that there's a spare key near every hatch down here. Let's look around.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101216/19569FD2"
        },
        [10121701] = {
          Content = "小仆从小仆从，你竖起耳朵仔细听，这里的水流好像有回声耶！",
          DialogueId = 10121701,
          GUID = "1956AF92",
          NextDialogue = 10121702,
          SpeakNpcId = 200002,
          Subtitle = "Pssst, Little Minion! Listen up — doesn't the water sound kind of weird?",
          TurnTo = {
            [1] = "200002:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101217/1956AF92"
        },
        [10121702] = {
          Content = "好像有一点……",
          DialogueId = 10121702,
          GUID = "1956AFBC",
          NextDialogue = 10121703,
          SpeakNpcId = 100001,
          Subtitle = "Now that you mention it...",
          VoiceName = "voice/$Locale$/story/1002/101217/1956AFBC"
        },
        [10121703] = {
          Content = "你说，水流后面会不会还有个小房间呢？你要不要去看看？",
          DialogueId = 10121703,
          GUID = "1956AFE6",
          NextDialogue = 10121704,
          SpeakNpcId = 200002,
          Subtitle = "Do you think there's a secret space behind it? Want to go check it out?",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101217/1956AFE6"
        },
        [10121704] = {
          Content = "你怎么不自己去？",
          DialogueId = 10121704,
          GUID = "1956B010",
          NextDialogue = 10121705,
          SpeakNpcId = 100001,
          Subtitle = "Go, Snow, I have faith in you.",
          VoiceName = "voice/$Locale$/story/1002/101217/1956B010"
        },
        [10121705] = {
          Content = "这么惊险刺激的冒险机会，当然要留给勇敢的小仆从你啦，嘿嘿……",
          DialogueId = 10121705,
          GUID = "1956B03A",
          SpeakNpcId = 200002,
          Subtitle = "Uh-uh. It's such a thrilling adventure. I should leave it to you, my fearless, trusty Little Minion, hehe...",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101217/1956B03A"
        },
        [10121801] = {
          Content = "我们头顶的那根水管上放了一个木箱子，备用钥匙会不会就在那里呀？可是，要怎么爬上去呢……",
          DialogueId = 10121801,
          GUID = "1956BFFA",
          SpeakNpcId = 200011,
          Subtitle = "See that crate on the pipe up there? Bet the spare key's in there... but, how are we supposed to reach it?",
          TalkActionId = {
            [1] = "200011:Think_Start"
          },
          TurnTo = {
            [1] = "200011:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101218/1956BFFA"
        },
        [10121901] = {
          Content = "（备用钥匙应该就是这一把了。回去开门试试看吧。）",
          DialogueId = 10121901,
          DisableMouth = 1,
          GUID = "1956D062",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(This should be the spare key. Let's test it out.)",
          VoiceName = "voice/$Locale$/story/1002/101219/1956D062"
        },
        [10122001] = {
          Content = "他或许被这些秽兽袭击了……我们也不能大意。",
          DialogueId = 10122001,
          GUID = "1956E0CA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "He probably ran into some Filthoids... We better stay sharp.",
          VoiceName = "voice/$Locale$/story/1002/101220/1956E0CA"
        },
        [10122101] = {
          ContentES = "{nickname}, ¡cuidado con los Filthoids! ¡Yo lo sujeto!",
          DialogueId = 10122101,
          GUID = "1956F132",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = ", watch out for those Filthoids! I'll hold him down!",
          VoiceName = "voice/$Locale$/story/1002/101221/1956F132"
        },
        [10122201] = {
          Content = "那块亮亮的石头是……？好像还有一本书诶！",
          DialogueId = 10122201,
          GUID = "1957019A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Ooooh! Look at that shiny rock! Ah — there's a book too!",
          VoiceName = "voice/$Locale$/story/1002/101222/1957019A"
        },
        [10122300] = {
          DialogueId = 10122300,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_101223;content:Reading_Content_101223}",
          GUID = "19571201",
          NextDialogue = 10122301
        },
        [10122301] = {
          Camera = "213.39209,214.109375,166.472168,0.00012,-5.40091,-127.799797,25.000002,464.479523,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeOutQuad",
          Content = "看来是前面的狩月人留下的。",
          DialogueId = 10122301,
          FinalCamera = "229.281494,234.594238,168.922363,0.00012,-5.40091,-127.799797,25.000002,464.479523,false,DoNotOverride,2.8",
          GUID = "19571202",
          NextDialogue = 10122302,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"100001:p(Plamp01)"}},
LookAt{LookAtDescription{"200002:p(Plamp01)"}},
LookAt{LookAtDescription{"200006:p(Plamp01)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Guess one of the Phoxhunters left these behind.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200006:AgreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101223/19571202"
        },
        [10122302] = {
          Camera = "1613.404053,381.626953,486.294678,0.000123,-12.201046,-168.596786,35.0,464.479523,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "原来这里探险的狩月人是用<H>引路灯</>和<H>指示牌</>为后面的人指引安全的道路吗……",
          DialogueId = 10122302,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "1761.427734,411.505371,518.932861,0.000123,-12.201046,-168.596741,35.000008,464.479523,false,DoNotOverride,2.8",
          GUID = "1957122C",
          NextDialogue = 10122303,
          SpeakNpcId = 200006,
          Subtitle = "So this Phoxhunter used lamps and signposts to mark a safe path for those who come after them...?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101223/1957122C"
        },
        [10122303] = {
          Camera = "23.476318,138.433594,140.942383,0.000156,-2.000911,-106.794113,35.0,275.996185,false,Manual,2.8",
          Content = "有余力的话，我们也帮忙维护一下这些引路灯吧！",
          DialogueId = 10122303,
          FacialId = {
            [1] = "200006:Smile02"
          },
          FinalCamera = "32.779297,169.258789,142.067383,0.000156,-2.000911,-106.794113,35.000008,275.996185,false,DoNotOverride,2.8",
          GUID = "19571256",
          SpeakNpcId = 200006,
          Subtitle = "That's so kind. If we have the time, let's help maintain these lamps too!",
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101223/19571256"
        },
        [10122401] = {
          Content = "灯又亮起来了耶~",
          DialogueId = 10122401,
          GUID = "1957226A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Yay, the lamp's glowing again~!",
          VoiceName = "voice/$Locale$/story/1002/101224/1957226A"
        },
        [10122402] = {
          Content = "嗯，这样大家应该就不会走错路了吧。",
          DialogueId = 10122402,
          GUID = "19572294",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "This should make it easier for people to find their way.",
          VoiceName = "voice/$Locale$/story/1002/101224/19572294"
        },
        [10122501] = {
          Content = "这样一来就全部搞定啦，干得漂亮！",
          DialogueId = 10122501,
          GUID = "195732D2",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Aaaand... all done! Nice work!",
          VoiceName = "voice/$Locale$/story/1002/101225/195732D2"
        },
        [10122601] = {
          Content = "它好像很喜欢你呢，{nickname}。",
          DialogueId = 10122601,
          GUID = "1957433A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10122602,
          SpeakNpcId = 200006,
          Subtitle = "It seems to really like you, .",
          VoiceName = "voice/$Locale$/story/1002/101226/1957433A"
        },
        [10122602] = {
          Content = "好可爱，让我也摸一摸！",
          DialogueId = 10122602,
          GUID = "19574364",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Aww, it's so cute! I want to pet it too!",
          VoiceName = "voice/$Locale$/story/1002/101226/19574364"
        },
        [10122701] = {
          Content = "“前有掠夺了很多财宝的秽兽千万不要靠近啊”——告示牌写好啦！",
          DialogueId = 10122701,
          GUID = "195753A2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10122702,
          SpeakNpcId = 200002,
          Subtitle = "\"Warning! Super scary treasure-hoarding Filthoids ahead! Do not approach!\" Pretty convincing, huh?",
          VoiceName = "voice/$Locale$/story/1002/101227/195753A2"
        },
        [10122702] = {
          ContentES = "...¿Estamos seguros de que un letrero como este no solo hará que la gente se sienta más curiosa?",
          DialogueId = 10122702,
          GUID = "195753CC",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...Are we sure a sign like this won't just make people more curious?",
          VoiceName = "voice/$Locale$/story/1002/101227/195753CC"
        },
        [10122801] = {
          Content = "嗯？那些黄色的“刺”亮晶晶的，难道是……",
          DialogueId = 10122801,
          GUID = "1957640A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10122802,
          SpeakNpcId = 100001,
          Subtitle = "Those glowing yellow spikes... Could they be—",
          VoiceName = "voice/$Locale$/story/1002/101228/1957640A"
        },
        [10122802] = {
          Content = "不是哦，恩里克叔叔说，群星绮晶是星星形状的<H>紫色</>晶体……",
          DialogueId = 10122802,
          GUID = "19576434",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Probably not. Mr Henrik once said Crystallo of Stella is purple and shaped like stars.",
          VoiceName = "voice/$Locale$/story/1002/101228/19576434"
        },
        [10122901] = {
          Content = "小心！！",
          DialogueId = 10122901,
          GUID = "19577472",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10122902,
          SpeakNpcId = 200006,
          Subtitle = "Watch out!!",
          VoiceName = "voice/$Locale$/story/1002/101229/19577472"
        },
        [10122902] = {
          Content = "呼，还好没事……咦，前面有路了！",
          DialogueId = 10122902,
          GUID = "1957749C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Phew... that was close. Wait... the path ahead is clear now!",
          VoiceName = "voice/$Locale$/story/1002/101229/1957749C"
        },
        [10123001] = {
          ContentES = "Por cierto, esas lámparas de guía en el camino, ¿fuiste tú quien las encendió? Gracias, en nombre de todos los Phoxcazadores que pasarán detrás de nosotros.",
          DialogueId = 10123001,
          GUID = "195784DA",
          NextDialogue = 10123002,
          Subtitle = "Those lamps along the path... that was you, wasn't it? Thoughtful of you — the other Phoxhunters will appreciate it.",
          VoiceName = "voice/$Locale$/story/1002/101230/195784DA"
        },
        [10123002] = {
          ContentES = "Tómalo como un regalo de agradecimiento.",
          DialogueId = 10123002,
          GUID = "19578504",
          Subtitle = "Here — call it a thank-you gift.",
          VoiceName = "voice/$Locale$/story/1002/101230/19578504"
        },
        [10123101] = {
          ContentES = "¡{性别:Pequeño secuaz|Pequeña secuaz}, date prisa!",
          DialogueId = 10123101,
          GUID = "19579542",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10123102,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, hurry up!",
          VoiceName = "voice/$Locale$/story/1002/101231/19579542"
        },
        [10123102] = {
          ContentES = "Shhh… con calma. Si nos nota, esto va a acabar mal.",
          DialogueId = 10123102,
          GUID = "1957956C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Shhh— Keep it down, or he will notice us.",
          VoiceName = "voice/$Locale$/story/1002/101231/1957956C"
        },
        [10123201] = {
          ContentES = "Uf… ¿qué le pasa? ¿Por qué tarda tanto?",
          DialogueId = 10123201,
          GUID = "1957A5AA",
          Subtitle = "Ugh... What's taking him so long?",
          VoiceName = "voice/$Locale$/story/1002/101232/1957A5AA"
        },
        [10123301] = {
          ContentES = "Espera… ¡estamos demasiado cerca!",
          DialogueId = 10123301,
          GUID = "1957B612",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Wait—! We're way too close!",
          VoiceName = "voice/$Locale$/story/1002/101233/1957B612"
        },
        [10123401] = {
          ContentES = "¿Otra vez ustedes? ¿Me están siguiendo a escondidas…? ¿Qué quieren?",
          DialogueId = 10123401,
          GUID = "1957C67A",
          IsBlack = 1,
          NextDialogue = 10123402,
          SpeakNpcId = 200005,
          Subtitle = "You again? Are you stalking me? What do you want?",
          VoiceName = "voice/$Locale$/story/1002/101234/1957C67A"
        },
        [10123402] = {
          ContentES = "¡No, no, no! ¡Solo volvíamos a la taberna! ¡Pura coincidencia!",
          DialogueId = 10123402,
          GUID = "1957C6A4",
          IsBlack = 1,
          SpeakNpcId = 200002,
          Subtitle = "No, no! We were just, uh, heading back to the tavern! Total coincidence!",
          VoiceName = "voice/$Locale$/story/1002/101234/1957C6A4"
        },
        [10123403] = {
          ContentES = "Oh no... ¡Henrik nos ha visto!",
          DialogueId = 10123403,
          GUID = "10123403.0",
          IsBlack = 1,
          Subtitle = "Oh no... Henrik's spotted us!"
        },
        [10123404] = {
          Content = "恩里克消失在了视线外……似乎是跟丢了。",
          DialogueId = 10123404,
          GUID = "1957C6A5",
          Subtitle = "Henrik has vanished... Looks like the trail has gone cold."
        },
        [10123405] = {
          Content = "恩里克走进了一间花店，你们决定在一旁的咖啡厅稍作等待。",
          DialogueId = 10123405,
          GUID = "1957C6A6",
          Subtitle = "Henrik stepped into a flower shop, and you decided to wait at a nearby café."
        },
        [10123501] = {
          ContentES = "Muy bien, niños~ Despacito, en fila…",
          DialogueId = 10123501,
          GUID = "1957D6E2",
          NextDialogue = 10123502,
          Subtitle = "Alright, kids~ Nice and slow, single file—",
          VoiceName = "voice/$Locale$/story/1002/101235/1957D6E2"
        },
        [10123502] = {
          ContentES = "Despacito, suave… así vamos bien...",
          DialogueId = 10123502,
          GUID = "1957D70C",
          Subtitle = "Nice and slow, here we go~",
          VoiceName = "voice/$Locale$/story/1002/101235/1957D70C"
        },
        [10123601] = {
          ContentES = "(Henrik se ha detenido… tenemos que escondernos en algún lado.)",
          DialogueId = 10123601,
          DisableMouth = 1,
          GUID = "1957E74A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(He stopped... We need to find a place to hide.)",
          VoiceName = "voice/$Locale$/story/1002/101236/1957E74A"
        },
        [10123602] = {
          ContentES = "¿¡Esto está roto otra vez!?",
          DialogueId = 10123602,
          GUID = "1957E774",
          Subtitle = "Darn it... This thing's busted again!?",
          VoiceName = "voice/$Locale$/story/1002/101236/1957E774"
        },
        [10123701] = {
          ContentES = "¡Tengo una idea! ¡Nos escondemos dentro de esa cosa enorme y lo seguimos sin hacer ruido!",
          DialogueId = 10123701,
          GUID = "1957F7B2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10123702,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, I've got an idea! We hide inside this big guy and follow him without making a sound!",
          VoiceName = "voice/$Locale$/story/1002/101237/1957F7B2"
        },
        [10123702] = {
          ContentES = "¿Y cómo piensas entrar sin que los soldados te vean?",
          DialogueId = 10123702,
          GUID = "1957F7DC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10123703,
          SpeakNpcId = 100001,
          Subtitle = "...Then tell me how you're planning to sneak inside without the soldiers noticing?",
          VoiceName = "voice/$Locale$/story/1002/101237/1957F7DC"
        },
        [10123703] = {
          ContentES = "Eh… bueno… hmm… ¡Ah, Henrik se va! ¡Rápido, rápido!",
          DialogueId = 10123703,
          GUID = "1957F806",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10123501,
          SpeakNpcId = 200002,
          Subtitle = "Uh... well... um... Oh — look, Henrik's leaving! Let's go!",
          VoiceName = "voice/$Locale$/story/1002/101237/1957F806"
        },
        [10123801] = {
          Content = "那家店……“牵念之花”，看名字好像是间花店。",
          DialogueId = 10123801,
          GUID = "1958081A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10123802,
          SpeakNpcId = 100001,
          Subtitle = "Flowers of Solicitude...? Looks like it's a flower shop.",
          VoiceName = "voice/$Locale$/story/1002/101238/1958081A"
        },
        [10123802] = {
          Content = "他去买花了吗……诶？！难道他是要去约会？",
          DialogueId = 10123802,
          GUID = "19580844",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "He went in there to buy flowers...? Wait—! Is he going on a date!?",
          VoiceName = "voice/$Locale$/story/1002/101238/19580844"
        },
        [10123901] = {
          Content = "喂，你们两个。",
          DialogueId = 10123901,
          GUID = "19581882",
          NextDialogue = 10123902,
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          Subtitle = "Hey, you two.",
          VoiceName = "voice/$Locale$/story/1002/101239/19581882"
        },
        [10123902] = {
          Content = "对，就是你们两个。你们俩，鬼鬼祟祟在人家屋顶坐着干什么？",
          DialogueId = 10123902,
          GUID = "195818AC",
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          Subtitle = "Yes, I'm talking to you. What exactly are you doing sneaking around on the roof?",
          VoiceName = "voice/$Locale$/story/1002/101239/195818AC"
        },
        [10123903] = {
          Camera = "-192.838379,86.913574,147.084473,0.000721,-6.203888,-37.222317,35.0,325.416962,false,Manual,1.997252",
          Content = "哪有，我们明明是光明正大坐着看风景！你看今天晚上的太阳多好啊。",
          DialogueId = 10123903,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          GUID = "195818D6",
          NextDialogue = 10123904,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{200002},AnimationId{"Confident_End"},Duration{1}},
PlayAnimation{_delay{5},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
CameraMoveTo{_delay{5.5},TargetPosition{"923.483887,-2454.475342,127.318726,0.000752,4.994986,122.379768,30.0,662.570679,false,Manual,1.997252"},duration{0}},
CameraMoveTo{_delay{5.6},TargetPosition{"884.15332,-2479.414307,127.318726,0.000752,4.994986,122.379768,30.0,662.570679,false,Manual,1.997252"},duration{4}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Sneaking around? Nah-uh! We're just admiring the lovely view! Look at that gorgeous sunlight—",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101239/195818D6"
        },
        [10123904] = {
          Camera = "56.511719,-167.835693,119.327148,0.000756,2.594707,118.379005,35.0,218.031204,false,Manual,3.0",
          Content = "什么太阳月亮的，我要修屋顶，麻烦让一让。",
          DialogueId = 10123904,
          GUID = "19581900",
          NextDialogue = 10123905,
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          Subtitle = "...It's nighttime. And I need to fix this roof. Move.",
          TalkActionId = {
            [1] = "200019:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101239/19581900"
        },
        [10123905] = {
          Camera = "-161.023438,20.044434,118.390259,0.000759,-2.805302,-37.617157,35.0,267.49585,false,Manual,3.0",
          Content = "走吧。",
          DialogueId = 10123905,
          GUID = "1958192A",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Let's leave.",
          VoiceName = "voice/$Locale$/story/1002/101239/1958192A"
        },
        [10123906] = {
          Content = "呜呜，我们好像跟丢了……",
          DialogueId = 10123906,
          GUID = "19581954",
          NextDialogue = 10123907,
          SpeakNpcId = 200002,
          Subtitle = "Aw... We totally lost him...",
          VoiceName = "voice/$Locale$/story/1002/101239/19581954"
        },
        [10123907] = {
          Content = "去问问花店的店主碰碰运气吧。",
          DialogueId = 10123907,
          GUID = "19581955",
          SpeakNpcId = 100001,
          Subtitle = "Let's check with the florist. Maybe they saw something.",
          VoiceName = "voice/$Locale$/story/1002/101239/19581955"
        },
        [10124000] = {
          ContentES = "Diez minutos después.",
          DialogueId = 10124000,
          GUID = "10124000.0",
          IsBlack = 1,
          Subtitle = "Ten minutes later."
        },
        [10124001] = {
          ContentES = "¡Hola! Encontramos esta moneda de plata, creemos que ese señor la dejó caer. Queríamos devolvérsela…",
          DialogueId = 10124001,
          GUID = "195828EA",
          NextDialogue = 10124002,
          SpeakNpcId = 200002,
          Subtitle = "Hello! We found this silver coin — pretty sure that man just dropped it! We wanted to return it to him...",
          VoiceName = "voice/$Locale$/story/1002/101240/195828EA"
        },
        [10124002] = {
          ContentES = "¿Está llorando? ¿Él le dijo algo malo?",
          DialogueId = 10124002,
          GUID = "19582914",
          NextDialogue = 10124003,
          SpeakNpcId = 200002,
          Subtitle = "Wait— Are you crying? Did that guy say something mean to you?",
          VoiceName = "voice/$Locale$/story/1002/101240/19582914"
        },
        [10124003] = {
          ContentES = "Oh… no, solo es polen de Rocío púrpura en mis ojos. Gracias por preguntar.",
          DialogueId = 10124003,
          GUID = "1958293E",
          NextDialogue = 10124004,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "Ah... no, it's just some Dewiolet pollen in my eyes. Thank you for asking.",
          VoiceName = "voice/$Locale$/story/1002/101240/1958293E"
        },
        [10124004] = {
          ContentES = "Si hablan del hombre de blanco… probablemente esté junto al estanque, al noreste.",
          DialogueId = 10124004,
          GUID = "19582968",
          NextDialogue = 10124005,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "If you mean the gentleman in white... I believe he's by the pond, northeast of here.",
          VoiceName = "voice/$Locale$/story/1002/101240/19582968"
        },
        [10124005] = {
          ContentES = "Entendido, gracias.",
          DialogueId = 10124005,
          GUID = "19582992",
          NextDialogue = 10124006,
          SpeakNpcId = 100001,
          Subtitle = "Got it. Thank you.",
          VoiceName = "voice/$Locale$/story/1002/101240/19582992"
        },
        [10124006] = {
          ContentES = "Espere… usted…",
          DialogueId = 10124006,
          GUID = "195829BC",
          NextDialogue = 10124007,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "Wait, you...",
          VoiceName = "voice/$Locale$/story/1002/101240/195829BC"
        },
        [10124007] = {
          ContentES = "¿Sí? ¿Habla conmigo?",
          DialogueId = 10124007,
          GUID = "195829E6",
          NextDialogue = 10124008,
          SpeakNpcId = 100001,
          Subtitle = "Hm? Are you talking to me?",
          VoiceName = "voice/$Locale$/story/1002/101240/195829E6"
        },
        [10124008] = {
          ContentES = "…No, quizá me equivoqué de persona. Perdón… Tomen esto.",
          DialogueId = 10124008,
          GUID = "19582A10",
          NextDialogue = 10124101,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "...No, I might have mistaken you for someone else. Sorry... Here, please take this.",
          VoiceName = "voice/$Locale$/story/1002/101240/19582A10"
        },
        [10124101] = {
          ContentES = "¿Me lo da… gratis?",
          DialogueId = 10124101,
          GUID = "19583952",
          NextDialogue = 10124102,
          SpeakNpcId = 100001,
          Subtitle = "You are giving me this... for free?",
          VoiceName = "voice/$Locale$/story/1002/101241/19583952"
        },
        [10124102] = {
          ContentES = "Sí. Sus ojos brillan como rubíes, combinan perfectamente con esta flor… Que tenga un día maravilloso.",
          DialogueId = 10124102,
          GUID = "1958397C",
          NextDialogue = 10124103,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "That's right. Your eyes sparkle like rubies, perfectly matching this flower... I hope you have a lovely day.",
          VoiceName = "voice/$Locale$/story/1002/101241/1958397C"
        },
        [10124103] = {
          ContentES = "Gracias. Entonces… la aceptaré con gusto.",
          DialogueId = 10124103,
          GUID = "195839A6",
          NextDialogue = 10124104,
          SpeakNpcId = 100001,
          Subtitle = "Thank you. Then... I'll gladly accept it.",
          VoiceName = "voice/$Locale$/story/1002/101241/195839A6"
        },
        [10124104] = {
          ContentES = "¿Un regalo de una desconocida? ¡Mi {性别:pequeño secuaz es realmente encantador|pequeña secuaz es realmente encantadora}!",
          DialogueId = 10124104,
          GUID = "195839D0",
          SpeakNpcId = 200002,
          Subtitle = "Whoa, a gift from a stranger? My Little Minion is way too charming!",
          VoiceName = "voice/$Locale$/story/1002/101241/195839D0"
        },
        [10124201] = {
          ContentES = "Debe de ser este estanque… Sí, ahí está.",
          DialogueId = 10124201,
          GUID = "195849BA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "This should be the place... Yep, there he is!",
          VoiceName = "voice/$Locale$/story/1002/101242/195849BA"
        },
        [10124301] = {
          ContentES = "¡Ese tiene que ser su horrible secreto! Pero… esa agua está helada. Incluso para un Charon, lanzarse ahí podría ser mala idea.",
          DialogueId = 10124301,
          GUID = "19585A22",
          NextDialogue = 10124302,
          Subtitle = "This has gotta be his horrible secret! But... that water's freezing. Even for a Charon, jumping in could be a bad idea.",
          VoiceName = "voice/$Locale$/story/1002/101243/19585A22"
        },
        [10124302] = {
          ContentES = "¡Parece que la todopoderosa Lunaria tendrá que intervenir! Está bien, yo me encargo por ti— Espera, {性别:pequeño secuaz|pequeña secuaz} , ¿qué estás haciendo...?",
          DialogueId = 10124302,
          GUID = "19585A4C",
          NextDialogue = 10124303,
          Subtitle = "Looks like the all-powerful Lunarian has to step in! Alright, I'll take this one for you— Wait, Little Minion, what are you doing...?",
          VoiceName = "voice/$Locale$/story/1002/101243/19585A4C"
        },
        [10124303] = {
          ContentES = "Solo tengo que ajustar un poco la caña de pescar… ahí está. Perfecto.",
          DialogueId = 10124303,
          GUID = "19585A76",
          NextDialogue = 10124304,
          Subtitle = "Just need to tweak the fishing rod a little... There. All set.",
          VoiceName = "voice/$Locale$/story/1002/101243/19585A76"
        },
        [10124304] = {
          ContentES = "Déjame a mí. Si está en el agua, ya sea un tesoro o un tiburón, lo sacaré igual.",
          DialogueId = 10124304,
          GUID = "19585AA0",
          Subtitle = "I got this. If it's in the water, whether it's treasure or a shark, I'll reel it in.",
          VoiceName = "voice/$Locale$/story/1002/101243/19585AA0"
        },
        [10124401] = {
          ContentES = "No puede ser… ¡{性别:pequeño secuaz|pequeña secuaz}, ¿en serio eres el Dios Elysium de la Pesca!?",
          DialogueId = 10124401,
          GUID = "19586A8A",
          NextDialogue = 10124402,
          Subtitle = "No way... Little Minion, are you actually the Elysian God of Fishing!?",
          VoiceName = "voice/$Locale$/story/1002/101244/19586A8A"
        },
        [10124402] = {
          ContentES = "Un pequeño montón de piedras. Un ramo de flores blancas reposa junto a él, como un recuerdo silencioso.",
          DialogueId = 10124402,
          GUID = "19586AB4",
          NextDialogue = 10124403,
          Subtitle = "A small cairn, carefully stacked. A bouquet of white flowers rests beside it, as if left in quiet remembrance.",
          VoiceName = "voice/$Locale$/story/1002/101244/19586AB4"
        },
        [10124403] = {
          ContentES = "¡Mira! ¡Ese ramo de flores se parece al que Henrik compró en la floristería!",
          DialogueId = 10124403,
          GUID = "19586ADE",
          Subtitle = "Ooh! Look! Doesn't this bouquet look just like the one Henrik bought at the flower shop?",
          VoiceName = "voice/$Locale$/story/1002/101244/19586ADE"
        },
        [10124500] = {
