}]],
          SpeakNpcId = 200006,
          Subtitle = "Huh? I think it's an interesting activity, but my family never fished, so I'm not that good at it...",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101248/1958AC54"
        },
        [10124803] = {
