            [2] = "200006:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101248/1958AC7E"
        },
        [10124804] = {
          Camera = "717.636719,237.269531,92.487305,0.000039,0.000007,-165.6008,40.0,199.075928,false,Manual,4.533308",
          ContentES = "De acuerdo... entonces, es una promesa.",
          DialogueId = 10124804,
          FinalCamera = "718.5625,233.65625,92.487305,0.000039,0.000007,-165.6008,40.0,583.132141,false,Manual,3.808652",
          GUID = "1958ACA8",
          SpeakNpcId = 200006,
          Subtitle = "Sounds fun... I'd love to try.",
          TalkActionId = {
            [1] = "200006:AgreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101248/1958ACA8"
        },
        [10124901] = {
          ContentES = "Cuando era pequeña, creía que si corría lo suficiente, podría salir de Lago Helado.",
          DialogueId = 10124901,
          GUID = "1958BC92",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10124902,
          SpeakNpcId = 200006,
          Subtitle = "When I was little, I thought if I just kept running, I'd leave Icelake behind.",
          VoiceName = "voice/$Locale$/story/1002/101249/1958BC92"
        },
        [10124902] = {
          ContentES = "Pero cuanto más corría, más me encontraba frente al mismo lago... como detrás de una montaña, siempre hay otra montaña.",
          DialogueId = 10124902,
          GUID = "1958BCBC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "But no matter how far I ran, the lake never ended, and the mountains always led to more mountains.",
          VoiceName = "voice/$Locale$/story/1002/101249/1958BCBC"
        },
        [10125001] = {
          Camera = "187.345703,453.548828,53.723633,0.0,0.0,-113.610939,25.0,3663.129883,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Esta flor me suena...",
          DialogueId = 10125001,
          FinalCamera = "183.400391,455.277344,53.723633,0.0,0.0,-113.610863,25.0,425.805145,false,Manual,2.325369",
          GUID = "1958CCFA",
          LookAt = {
            [1] = "100001:p(P101250Flower)",
            [2] = "200006:p(P101250Flower)"
          },
          NextDialogue = 10125002,
          SpeakNpcId = 100001,
          Subtitle = "This flower looks familiar.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CCFA"
        },
        [10125002] = {
          Camera = "-5.208984,20.542969,81.288086,0.000032,-7.199948,52.000679,30.0,79.292412,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentES = "¿De verdad? Déjame tocarla... Sí, es un lirio estelar helado. Los pétalos son más pequeños y su aroma es más suave... pero es la misma especie que la de mi habitación.",
          DialogueId = 10125002,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "3.671875,19.353516,80.720703,0.000016,-7.199975,54.899391,30.0,182.280197,false,Manual,4.0",
          GUID = "1958CD24",
          NextDialogue = 10125003,
          Scripts = [[
PARA{
MoveTo{ActorId{200006},MoveSpeed{120},TargetPoint{"P101250Saiqi"}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "Really? Let me feel it... Ah, it's a Starfrost. Though the petals are smaller and the scent fainter, it's the same kind as the pot of flowers in my room.",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CD24"
        },
        [10125003] = {
