          Subtitle = "Would you like to pick it as a keepsake?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CD4E"
        },
        [10125004] = {
