          CameraBlendCurve = "easeInOutQuad",
          ContentES = "No me gusta esta ciudad. Odio el olor constante de sangre en el aire, sus murallas altas como montañas, las pesadas botas de los guardias... y los sollozos que resuenan en cada esquina.",
          DialogueId = 10125104,
          FacialId = {
            [1] = "200027:None"
          },
          FinalCamera = "-3675.546875,-915.507812,781.563477,0.000088,25.896593,-29.799929,15.0,937.541016,false,DoNotOverride,1.2",
          GUID = "1958DDE0",
          LookAt = {
            [1] = "200027:n(200027)"
          },
          NextDialogue = 10125105,
          SpeakNpcId = 200027,
          Subtitle = "I don't like this city. I hate the ever-present smell of blood in the air, the towering walls, the guards' heavy boots... and the endless whimpers that fill every alleyway.",
          ToFinalCameraBlendTime = 14,
          TurnTo = {
            [1] = "200027:p(-120)"
          },
          VoiceName = "voice/$Locale$/story/1002/101251/1958DDE0"
        },
        [10125105] = {
          Camera = "93.558594,213.8125,52.767578,0.00006,13.824869,-124.447884,50.0,134.6604,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "... Pero también es el lugar donde crecí. Mi <H>único y verdadero hogar</>.",
          DialogueId = 10125105,
          FinalCamera = "89.410156,207.765625,54.574219,0.000061,13.824869,-124.447868,50.0,126.754227,false,Manual,5.0",
          GUID = "1958DE0A",
          NextDialogue = 10125106,
          SpeakNpcId = 200027,
          Subtitle = "...But it's still where I grew up. My one and only home.",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101251/1958DE0A"
        },
        [10125106] = {
