        [10125201] = {
          ContentES = "(Ese tipo de allí me resulta familiar... ¿lo he conocido antes?)",
          DialogueId = 10125201,
          DisableMouth = 1,
          GUID = "1958EDCA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(That guy over there looks familiar... Have I met him before?)",
          VoiceName = "voice/$Locale$/story/1002/101252/1958EDCA"
        },
        [10125301] = {
          ContentES = "¡Voy a disparar de verdad! ¡No estoy bromeando!",
          DialogueId = 10125301,
          GUID = "1958FE32",
          Subtitle = "I swear, I'll do it! I'm not bluffing!!",
          VoiceName = "voice/$Locale$/story/1002/101253/1958FE32"
        },
        [10125401] = {
          ContentES = "¡Aaah! ¡Rápido, corran! ¡El hielo va a romperse!",
          DialogueId = 10125401,
          GUID = "19590E9A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Whoa! Get off it now! The ice is cracking!",
          VoiceName = "voice/$Locale$/story/1002/101254/19590E9A"
        },
        [10125501] = {
          ContentES = "El hielo es demasiado frágil. Deberíamos llegar primero a una plataforma más estable.",
          DialogueId = 10125501,
          GUID = "19591F02",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200021,
          Subtitle = "The ice won't hold. Maybe we should move to a more stable platform first.",
          VoiceName = "voice/$Locale$/story/1002/101255/19591F02"
        },
        [10125601] = {
          ContentES = "(Este debe ser el último tramo...)",
          DialogueId = 10125601,
          DisableMouth = 1,
          GUID = "19592F6A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10125602,
          SpeakNpcId = 100001,
          Subtitle = "(This should be the final stretch...)",
          VoiceName = "voice/$Locale$/story/1002/101256/19592F6A"
        },
        [10125602] = {
          ContentES = "(Psyche, espérame... te llevaré a casa.)",
          DialogueId = 10125602,
          DisableMouth = 1,
          GUID = "19592F94",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(Psyche, wait for me... I'm bringing you home.)",
          VoiceName = "voice/$Locale$/story/1002/101256/19592F94"
        },
        [10125701] = {
          ContentES = "{nickname}, ¿dónde estás?",
          DialogueId = 10125701,
          GUID = "19593FD2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = ", where are you?",
          VoiceName = "voice/$Locale$/story/1002/101257/19593FD2"
        },
        [10125702] = {
          ContentES = "¿Ya te alejaste? Te esperaré aquí...",
          DialogueId = 10125702,
          GUID = "19593FFC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Have you wandered off? I'll wait for you here...",
          VoiceName = "voice/$Locale$/story/1002/101257/19593FFC"
        },
        [10125801] = {
          ContentES = "Ve a descansar un poco. Sé que no podrás dormir, pero al menos un respiro te hará bien.",
          DialogueId = 10125801,
          GUID = "1959503A",
          NextDialogue = 10125802,
          SpeakNpcId = 200021,
          Subtitle = "Go back and catch some Z's. I know you probably won't be able to fall asleep, but at least it helps refresh you.",
          VoiceName = "voice/$Locale$/story/1002/101258/1959503A"
        },
        [10125802] = {
          ContentES = "No, gracias. Quiero caminar {性别:solo|sola} un rato.",
          DialogueId = 10125802,
          GUID = "19595064",
          NextDialogue = 10125803,
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but I want to take a walk by myself for a while.",
          VoiceName = "voice/$Locale$/story/1002/101258/19595064"
        },
        [10125803] = {
          ContentES = "...Está bien. Las noches en Lago Helado son largas. Ten cuidado ahí fuera.",
          DialogueId = 10125803,
          GUID = "1959508E",
          SpeakNpcId = 200021,
          Subtitle = "...Okay. The nights in Icelake are long. Be careful when you're out there.",
          VoiceName = "voice/$Locale$/story/1002/101258/1959508E"
        },
        [10125901] = {
          Camera = "454.923828,1684.220703,-255.024414,8.000015,2.99999,-111.999702,35.0,320.217255,false,Manual,4.0",
