CameraMoveTo{_delay{2.7},TargetPosition{"148.105469,442.427734,103.007812,0.000107,4.432396,-103.688713,60.000019,501.192657,false,Manual,4.0"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Greetings, child. I roam as the Ferrywoman of the Misty Sea — or, if you prefer a more personal touch, you may call me Lady Nifle.",
          ToFinalCameraBlendTime = 2.5,
          TurnTo = {
            [1] = "200076:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596120"
        },
        [10125905] = {
          Camera = "-119.442383,-114.433594,183.290039,0.000117,-11.966764,48.943577,50.000011,448.770081,false,Manual,3.0",
          ContentES = "He escuchado los susurros de un alma errante en este lugar. He venido a guiarla hacia el Mar Nebuloso.",
          DialogueId = 10125905,
          FacialId = {
            [1] = "200076:Sad01"
          },
          GUID = "1959614A",
          NextDialogue = 10125906,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Having journeyed here, I've heard the whispers of a wandering soul in this place; thus I've come to guide \"her\" back to the Misty Sea.",
          TalkActionId = {
            [1] = "200076:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/1959614A"
        },
        [10125906] = {
          ContentES = "¿Un alma errante?",
          DialogueId = 10125906,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "19596174",
          NextDialogue = 10125907,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "A wandering soul?",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596174"
        },
        [10125907] = {
          Camera = "-323.897461,340.539062,65.77832,0.000179,-4.999999,-18.701145,50.0,464.774139,false,Manual,3.5",
          ContentES = "Sí. {性别:hijo mío|hija mía}, ¿tú también llevas en tus pensamientos un alma que se ha ido?",
          DialogueId = 10125907,
          FacialId = {
            [1] = "200076:None"
          },
          GUID = "1959619E",
          NextDialogue = 10125908,
          Scripts = [[
