CameraMoveTo{_delay{2},TargetPosition{"-323.897461,340.539062,116.364258,0.000179,-0.999987,-18.701147,50.0,464.774139,false,Manual,3.5"},blend{"easeInQuad"},duration{3}}
}]],
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Yes. Child, do you, too, hold a departed soul in your thoughts?",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/1959619E"
        },
        [10125908] = {
          Camera = "81.331055,16.730469,172.487305,0.000212,-16.199337,69.699547,40.0,256.526001,false,Manual,3.0",
          ContentES = "¿Cómo lo sabes?",
          DialogueId = 10125908,
