        [10129701] = {
          Camera = "98.882812,336.099609,13.861816,0.00006,13.998199,-124.392242,15.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10129701,
          FinalCamera = "176.5,102.359375,-7.201416,0.000064,19.197878,-143.98999,15.0,100000.0,false,Disable,2.8",
          GUID = "195BD012",
          ToFinalCameraBlendTime = 3
        },
        [10129801] = {
          ContentES = "¡El ladrón está justo delante! Oh no... ¡está peleando con los Filthoids!",
          DialogueId = 10129801,
          GUID = "195BD013",
          NextDialogue = 10129802,
          SpeakNpcId = 200011,
          Subtitle = "The thief's up ahead! Oh no... he's in a fight with Filthoids!",
          VoiceName = "voice/$Locale$/story/1002/101298/195BD013"
        },
        [10129802] = {
          ContentES = "Ahuyentemos a los Filthoids y atrapémoslo.",
          DialogueId = 10129802,
          GUID = "195BD014",
          SpeakNpcId = 100001,
          Subtitle = "Let's drive away the Filthoids and get him.",
          VoiceName = "voice/$Locale$/story/1002/101298/195BD014"
        },
        [10129901] = {
          ContentES = "Dicen que se puede escuchar sollozos cada noche, y de vez en cuando, un olor extraño sale de las ventanas.",
          DialogueId = 10129901,
          GUID = "195BD015",
          Subtitle = "They say you can hear sobbing every night — and now and then, there's this strange smell drifting from the windows.",
          VoiceName = "voice/$Locale$/story/1002/101299/195BD015"
        },
        [10130001] = {
          ContentES = "Lo que sea que esté haciendo Henrik, eso no es asunto mío. Pero si realmente está metido en algo... temo por la seguridad de Psyche.",
          DialogueId = 10130001,
          GUID = "195BD016",
          NextDialogue = 10106325,
          SpeakNpcId = 100001,
          Subtitle = "Whatever's going on with Henrik — that's not my business. But if he's really up to something... I'm worried Psyche might get hurt.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101300/195BD016"
        },
        [10130101] = {
          Camera = "17.943359,4617.524414,902.814453,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0",
          ContentES = "Si {性别:lo|la} encontramos... al anfitrión de la Resonancia, ¿qué piensan hacer con {性别:él|ella}?",
          DialogueId = 10130101,
          Duration = 8,
          FinalCamera = "37.016602,4939.133301,642.138672,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0",
          GUID = "195BD017",
          NextDialogue = 10130102,
          SpeakNpcId = 100006,
          Subtitle = "If we do find {性别:him|her}... the host of Resonance — what's the plan, Chief?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD017"
        },
        [10130102] = {
          ContentES = "Un poder de Resonancia plenamente despierto puede influir sobre todos los Daimons... pero ese poder depende completamente de la voluntad de su anfitrión.",
          DialogueId = 10130102,
          Duration = 8,
          GUID = "195BD018",
          NextDialogue = 10130103,
          SpeakNpcId = 100006,
          Subtitle = "A fully awakened Resonance can exert control over any Daimon. But that power hinges entirely on the host's will.",
          VoiceName = "voice/$Locale$/story/1002/101301/195BD018"
        },
        [10130103] = {
          Camera = "-1576.924561,1990.549316,316.099609,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2",
          ContentES = "Es decir: si {性别:él|ella} no coopera, {性别:capturarlo|capturarla} no le servirá al Imperio. Peor aún podría convertirse en una amenaza. Igual que la vez anterio...",
          DialogueId = 10130103,
          Duration = 8,
          FinalCamera = "-1587.533691,2001.532227,318.089844,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2",
          GUID = "195BD019",
          NextDialogue = 10130104,
          SpeakNpcId = 100006,
          Subtitle = "Which means: if {性别:he|she} won't cooperate, then capturing {性别:him|her} does the Empire no good. Worse — it could become a threat. Just like last—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD019"
        },
        [10130104] = {
          Camera = "-40.981445,48.569336,104.802734,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0",
          ContentES = "Entonces {性别:lo|la} eliminamos. Como antaño. De cualquier modo, ese poder nunca debe caer fuera de las manos del Imperio, y mucho menos en las de Elysium. Bien, ¿y la otra mala noticia?",
          DialogueId = 10130104,
          Duration = 10,
          FinalCamera = "-42.826172,89.025879,102.189453,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0",
          GUID = "195BD020",
          NextDialogue = 10108013,
          SpeakNpcId = 100005,
          Subtitle = "Then we do what we did before. Wipe it out. That power cannot fall outside Imperial hands — least of all into Elysium's. Now, the other bad news?",
          TalkActionId = {
            [1] = "100005:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD020"
        },
        [10130201] = {
          ContentES = "“Flores de solicitud”… Una florería. ¿Eh? ¿Va a una cita?",
          DialogueId = 10130201,
          GUID = "195BD021",
          NextDialogue = 10130202,
          SpeakNpcId = 200002,
          Subtitle = "\"Flowers of Solicitude\"... It's a flower shop! Wait... is he going on a date!?",
          VoiceName = "voice/$Locale$/story/1002/101302/195BD021"
        },
        [10130202] = {
          ContentES = "¡Nos sentamos enfrente y esperamos a que salga!",
          DialogueId = 10130202,
          GUID = "195BD022",
          SpeakNpcId = 200002,
          Subtitle = "Let's grab a seat across the street and wait for him to come out!",
          VoiceName = "voice/$Locale$/story/1002/101302/195BD022"
        },
        [10130301] = {
          Camera = "216.478516,-137.633301,117.546875,0.000164,-6.198915,127.211983,35.0,407.218628,false,DoNotOverride,4.0",
          ContentES = "¡Ahí está!",
          DialogueId = 10130301,
          GUID = "195BD023",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:p(LC_EnterFlow)"
          },
          NextDialogue = 10130302,
          Scripts = "MoveTo{ActorId{200002},MoveSpeed{220},TargetPoint{\"P1190930Bai1\"}}",
          SpeakNpcId = 200002,
          Subtitle = "There he is!",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD023"
        },
        [10130302] = {
          Camera = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0",
          ContentES = "¿Puedo invitarles algo de beber?",
          DialogueId = 10130302,
          GUID = "195BD024",
          NextDialogue = 10130303,
          Scripts = "MoveTo{ActorId{200097},MoveSpeed{80},TargetPoint{\"P1190930Boy1\"}}",
          SpeakNpcId = 200097,
          Subtitle = "Can I get you two something to drink?",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD024"
        },
        [10130303] = {
          Camera = "105.118164,-51.828613,93.718262,0.0,-2.999962,129.999985,30.0,118.813644,false,Manual,4.0",
          ContentES = "¡Oh, no, gracias! Solo vamos a sentarnos un rato y disfrutar del paisaje. Mira qué bonito está el atardecer, jeje…",
          DialogueId = 10130303,
          GUID = "195BD025",
          NextDialogue = 10130304,
          SpeakNpcId = 200002,
          Subtitle = "Oh, we're good! Just, uh... hanging out and enjoying the view! Isn't the sunlight lovely tonight? Heehee...",
          TalkActionId = {
            [1] = "200002:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101303/195BD025"
        },
        [10130304] = {
          Camera = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0",
          ContentES = "¡Pues nada combina mejor con un paisaje bonito que una buena bebida! Tenemos todo tipo de cafés, jugo de Baya Boreal de Lago Helado… ¡Oh! ¿Qué tal nuestra nueva especialidad? Una sopa cremosa de arenque marinado.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10130304,
          GUID = "195BD026",
          NextDialogue = 10130305,
          SpeakNpcId = 200097,
          Subtitle = "Well, nothing pairs with a good view like a good drink! We've got all kinds of coffee, Icelake's own Borealberry Juice... Oh! And how about our newest special — rich, creamy Pickled Herring Soup?",
          TalkActionId = {
            [1] = "200097:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101303/195BD026"
        },
        [10130305] = {
          Camera = "126.273438,-640.34082,115.856201,0.000007,0.0,89.999985,20.0,118.813644,false,Manual,4.0",
          ContentES = "No, gracias, tenemos que hac—… Espera, ¿dónde está Henrik?",
          DialogueId = 10130305,
          GUID = "195BD027",
          NextDialogue = 10130306,
          SpeakNpcId = 100001,
          Subtitle = "No thanks, we've got someth— ...Wait, where's Henrik?",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD027"
        },
        [10130306] = {
          Camera = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,169.724716,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Uy… creo que lo perdimos…",
          DialogueId = 10130306,
          FinalCamera = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,680.897827,false,Manual,1.2",
          GUID = "195BD028",
          LookAt = {
            [1] = "200002:p(LC_EnterFlow)",
            [2] = "100001:p(LC_EnterFlow)"
          },
          NextDialogue = 10130307,
          SpeakNpcId = 200002,
          Subtitle = "Aww, I think we lost him...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD028"
        },
        [10130307] = {
          Camera = "-31.876953,-170.957031,169.342773,0.0,-14.000125,51.202343,30.0,155.608383,false,Manual,3.0",
          ContentES = "…Vamos a preguntarle a la florista, a ver si tenemos suerte.",
          DialogueId = 10130307,
          GUID = "195BD029",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Let's ask the florist and try our luck.",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD029"
        },
        [10130401] = {
          Camera = "-137.371094,-123.811035,229.291016,0.000012,-12.600093,90.599869,16.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "(El horno es enorme. El fuego hace tiempo que se apagó, pero las cenizas en su interior sugieren un uso reciente.)",
          DialogueId = 10130401,
          DisableMouth = 1,
          FinalCamera = "-132.40625,-283.590576,87.898438,0.000034,13.599972,91.399513,16.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "195BD030",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10130402,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"200021:p(-180)\"}}",
