        },
        [10130602] = {
          ContentES = "…Algo no va bien. Pero al menos, los rehenes están ilesos.",
          DialogueId = 10130602,
          GUID = "195BD036",
          NextDialogue = 10130603,
          SpeakNpcId = 100304,
          SpeakNpcName = "UI_Npc_Name_FemaleOfficer",
          Subtitle = "...Something's off. But the hostages are safe, at least.",
          VoiceName = "voice/$Locale$/story/1002/101306/195BD036"
        },
        [10130603] = {
          Camera = "82.416016,128.960938,14.348633,-3.000001,-0.400782,-132.985641,30.000002,214.526855,false,Manual,3.0",
