        [11011111] = {
          Camera = "-3.65625,147.421875,116.083008,0.000099,3.800829,-101.856186,35.000008,156.802643,false,Manual,22.0",
          Content = "{nickname2}，你来报告。",
          DialogueId = 11011111,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90AE66",
          LookAt = {
            [1] = "110010:n(110022)",
            [2] = "110005:n(110022)"
          },
          NextDialogue = 11011112,
          SpeakNpcId = 110010,
          Subtitle = ". You, do the report please.",
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AE66"
        },
        [11011112] = {
          Camera = "150.466797,-241.613281,146.286743,0.000109,-4.599121,138.34343,35.0,720.519287,false,Manual,22.0",
          Content = "是。“狮鹫”分队原本按照计划，与您所在的“雪狼”分队分两路向龙莎要塞发起攻势——这是您知道的。但在潜入要塞后，我们遭遇了伏击。",
          DialogueId = 11011112,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "156.564453,-234.769531,146.286743,0.000109,-4.599121,138.34343,35.0,720.519287,false,Manual,22.0",
          GUID = "1B90AE90",
          LookAt = {
            [1] = "110022:n(110010)"
          },
          NextDialogue = 11011113,
          RelatedWikiId = {
            [1] = 408007
          },
          Scripts = [[
SEQ{PlayAnimation{ActorId{110022},AnimationId{"Explain02_Start"},Duration{2}},PlayAnimation{_delay{6},ActorId{110022},AnimationId{"Explain02_End"},Duration{2}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Yes, sir. As planned, the Griffins and the Snow Wolves were expected to launch a two-way assault on Lonza Fortress. However, the Griffins were ambushed shortly after we began our infiltration.",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AE90"
        },
        [11011113] = {
          Camera = "350.375,-614.980469,260.890625,0.000052,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
          Content = "各区域间的通道被封锁，我方小部分队员失联，其余则伤亡惨重。向外的通讯也被切断了——我们被困在了这里。",
          DialogueId = 11011113,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90AEBA",
          NextDialogue = 11011114,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{110022},AnimationId{"Talk02_Start"},Duration{2}},
PlayAnimation{_delay{0.5},ActorId{110022},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "The passageways between the zones were blocked. We lost contact with some of our men, and the rest have suffered heavy casualties. Our commlinks have been severed, too — we're essentially trapped here.",
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AEBA"
        },
        [11011114] = {
          Camera = "54.410156,219.574219,135.06189,0.000141,-1.200686,-103.445839,35.0,209.628448,false,Manual,22.0",
