        [11011402] = {
          Camera = "-842.123413,3605.324219,1760.076172,0.000862,-24.398064,-64.820572,22.0,100000.0,false,Manual,22.0",
          Content = "维克在下面，他想关停月髓舱，却被锁在了一扇门后面……这里的操作台被重新加密过了，我再想想办法……",
          DialogueId = 11011402,
          Duration = 3,
          FinalCamera = "-885.907959,3584.742188,1760.07666,0.000862,-24.398064,-64.820572,22.0,100000.0,false,Manual,22.0",
          GUID = "1B90D2D3",
          LookAt = {
            [1] = "110010:p(0801)",
            [2] = "110022:p(0801)",
            [3] = "110020:n(110020)"
          },
          NextDialogue = 11011403,
          SpeakNpcId = 110020,
          Subtitle = "Vic is down there. He was trying to shut down the Phoxichor tank, but he got locked behind a door... They've re-encrypted the control panel... I gotta figure out something else...",
          TalkActionId = {
