          ExStoryInfo = "EXPlayer",
          GUID = "1B90E196",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E196"
        },
        [11011424] = {
          Content = "我会逐个解锁防护屏障，等信号亮起，你就把月髓舱打碎！",
          DialogueId = 11011424,
          Duration = 3,
          GUID = "1B90E1C0",
          NextDialogue = 11011425,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "I'll disable the protective barriers one by one. When the signal light's on, smash the Phoxichor tank as fast as you can!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C0"
        },
        [11011425] = {
          Content = "有些月髓舱可能会配备自毁装置，如果听到倒计时响起，就终止行动，马上离开。",
          DialogueId = 11011425,
          Duration = 3,
          GUID = "1B90E1C1",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Some Phoxichor tanks may be equipped with self-destruct devices; if you hear a timer, evacuate immediately.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C1"
        },
        [11011426] = {
          Content = "就是现在，打碎它！",
          DialogueId = 11011426,
          Duration = 3,
          GUID = "1B90E1C2",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Now! Smash it!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C2"
        },
        [11011427] = {
          Content = "干得不错，我们还有两个要处理。",
          DialogueId = 11011427,
          Duration = 3,
          GUID = "1B90E1C3",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Excellent work. We got two more tanks to go.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C3"
        },
        [11011428] = {
          Content = "2号月髓舱的屏障解锁了，上吧！",
          DialogueId = 11011428,
          Duration = 3,
          GUID = "1B90E1C4",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "The 2nd one has been disabled. Now!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C4"
        },
        [11011429] = {
