          DialogueId = 11011429,
          Duration = 3,
          GUID = "1B90E1C5",
          NextDialogue = 11011430,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Whew... One more left. You okay down there?",
