          GUID = "1B90FF1E",
          NextDialogue = 11011604,
          SpeakNpcId = 110014,
          Subtitle = "...Captain! Thank god... you're here...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110116/1B90FF1E"
        },
        [11011604] = {
          Camera = "165.308624,228.661102,73.447205,-3.000001,-1.398563,-129.98381,45.0,249.404388,false,Manual,3.274907",
          Content = "快……轨道那儿……大家……被秽兽困住……快……去救……",
          DialogueId = 11011604,
          FinalCamera = "169.953156,224.755829,73.765076,-3.000001,-1.398563,-129.98381,45.0,249.404388,false,Manual,3.274907",
          GUID = "1B90FF48",
          NextDialogue = 11011605,
          SpeakNpcId = 110014,
          Subtitle = "Quick... the rail tracks... Everyone is trapped by the Filthoids there... Go save them...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110116/1B90FF48"
        },
        [11011605] = {
          Camera = "-124.238274,75.074234,102.226013,0.000037,-16.999535,-4.998422,35.0,221.302353,false,Manual,6.725677",
          Content = "你也要……小心……",
          DialogueId = 11011605,
          FinalCamera = "-123.417953,84.58596,102.226013,0.000037,-16.999535,-4.998422,35.0,221.302353,false,Manual,6.725677",
          GUID = "1B90FF72",
          NextDialogue = 11011606,
          SpeakNpcId = 110014,
          Subtitle = "And... be careful out there, Captain...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110116/1B90FF72"
        },
        [11011606] = {
          Camera = "33.023453,153.275375,92.632935,0.000094,-21.598936,-67.604774,35.0,90.417793,false,Manual,9.830451",
          Content = "……妈妈，秽兽在吃我的腿……好疼……",
          DialogueId = 11011606,
          FinalCamera = "36.375031,145.073242,89.119995,0.000094,-21.598936,-67.604774,35.0,90.417793,false,Manual,9.830451",
          GUID = "1B90FF9C",
          NextDialogue = 11011607,
          SpeakNpcId = 110014,
          Subtitle = "...Ma... the Filthoids are feasting on my leg... It hurts so much...",
