        },
        [11012446] = {
          Camera = "43.091187,-31.208008,198.673462,-0.002777,-40.807617,-92.394653,15.610328,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "快猜呀——猜呀猜呀！当然，就算猜出来，我也不会告诉你的！",
          DialogueId = 11012446,
          Duration = 3,
          FacialId = {
            [1] = "110009:Happy01"
          },
          FinalCamera = "43.091187,-31.208008,183.398743,-0.002777,-37.80748,-91.594666,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B91896C",
          LookAt = {
            [1] = "110022:n(110009)",
            [2] = "110009:n(110022)"
          },
          NextDialogue = 11012447,
          Scripts = "PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}",
          SpeakNpcId = 110009,
          Subtitle = "Go on, make your guess — any guess would do, because I won't tell you the truth anyway!",
          TalkActionId = {
            [1] = "110009:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91896C"
        },
        [11012447] = {
