          CameraBlendCurve = "easeInOutQuad",
          Content = "<W>不要再犹豫了！快用你的剑！它在呼唤着你，它在等待着血肉赐予的甜蜜与欢愉！</>",
          DialogueId = 11012447,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "17.73999,15.974609,99.406067,-0.002779,-48.007011,-78.395638,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B918996",
          NextDialogue = 11012448,
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},
PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Do not hesitate! Use your sword! It's calling to you! It thirsts for the sweet joy that can only be sated by flesh and blood.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918996"
        },
        [11012448] = {
          Camera = "23.116943,-23.245117,106.667053,-0.002777,1.793143,-80.992851,15.610328,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "<W>快啊！让那个疯女人闭嘴！</>",
          DialogueId = 11012448,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
