PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Quick! Silence this mad lass for good!",
          TalkActionId = {
            [1] = "110009:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9189C0",
          bForbidSkipOptions = true
        },
        [11012449] = {
          Content = "（努力维持理智。）",
          DialogueId = 11012449,
          GUID = "1B9189EA",
          NextDialogue = 11012451,
