          SpeakNpcId = 110010,
          Subtitle = "...Well, since we have , maybe {性别2:he|she} does have what it takes to lead us to victory.",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B708"
        },
        [11012725] = {
          Camera = "431.175476,-72.250488,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          Content = "嗯。准备好，我们就出发吧。",
