          FinalCamera = "423.409973,-86.030762,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          GUID = "1B91B732",
          NextDialogue = 11012726,
          SpeakNpcId = 110022,
