          FinalCamera = "-36.485291,407.628601,173.946289,0.000029,-9.399583,-88.996254,40.000011,313.388489,false,Manual,5.0",
          GUID = "1B91C428",
          NextDialogue = 11012805,
          SpeakNpcId = 110022,
          Subtitle = "Lost something important?",
