          },
          NextDialogue = 11013613,
          RelatedWikiId = {
            [1] = 201017
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{7},TargetPosition{"-742.495117,843.439453,633.784912,0.00004,-27.596544,-31.344604,30.0,271.651154,false,DoNotOverride,20.0"},duration{0}},CameraMoveTo{TargetPosition{"-832.090454,898.013672,688.620361,0.00004,-27.596523,-31.344666,30.0,271.651154,false,DoNotOverride,20.0"},duration{8}}
}]],
          SpeakNpcId = 110011,
          Subtitle = "When His Majesty was first crowned, Duke Servius was our Imperial Regent. But the Regency strayed from established Hyperborean traditions and grafted too many useless scions onto the great Imperial oak.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110010:n(110011)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B9248B8"
        },
        [11013613] = {
          Camera = "195.79921,146.666016,102.814026,-0.001556,-1.197421,101.018288,35.000011,216.948959,false,Manual,8.0",
          Content = "他们竟然搞出什么“桂冠卡戎”称号，允许你们进入枢密院和军团，甚至担任要职——这太荒谬了。",
          DialogueId = 11013613,
          Duration = 3,
          FacialId = {
            [1] = "110011:Unhappy01"
          },
          FinalCamera = "194.398621,153.863281,102.660858,-0.001556,-1.197421,101.018288,35.000011,216.948959,false,Manual,8.0",
          GUID = "1B9248E2",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013614,
          RelatedWikiId = {
            [1] = 101008
          },
          Scripts = "LookAt{_delay{6.5},LookAtDescription{\"110011:n(110011)\"}}",
          SpeakNpcId = 110011,
          Subtitle = "Those fools let so-called Laurelled Charons into the Military Council and the Legion — even handed high office to some of you. It's absurd.",
          TalkActionId = {
            [1] = "110011:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9248E2"
        },
        [11013614] = {
          Camera = "-129.604523,471.810547,-28.501526,0.000752,21.988857,-30.575706,23.640343,100000.0,false,DoNotOverride,2.654159",
          Content = "尽管如今陛下已经迷途知返，但这些糜烂的枝叶依旧存在。而我要做的，则是帮陛下一把，将这些糜烂彻底剪除。",
          DialogueId = 11013614,
          Duration = 3,
          FinalCamera = "-40.557144,495.207031,55.238251,-10.00088,13.201608,-42.578636,30.0,229.467407,false,DoNotOverride,22.0",
          GUID = "1B92490C",
          NextDialogue = 11013615,
          Scripts = [[
PARA{
PlayAnimation{_delay{12},ActorId{110011},AnimationId{"Angry02_Start"},Duration{10}},
PlayAnimation{_delay{16},ActorId{110011},AnimationId{"Angry02_End"},Duration{0}},
CameraMoveTo{_delay{10},TargetPosition{"46.070709,353.451172,80.537964,0.000758,-1.611453,15.627573,23.640345,100000.0,false,DoNotOverride,2.65416"},duration{0}}
}
]],
          SpeakNpcId = 110011,
          Subtitle = "Though His Majesty is now aware of these mistakes, they continue to plague us. I'm merely helping him prune the oak.",
          ToFinalCameraBlendTime = 12,
          TurnTo = {
            [1] = "110011:p(45)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B92490C"
        },
        [11013615] = {
          Camera = "52.397644,381.144531,96.864655,0.0,-0.198417,-44.378803,30.000019,229.46875,false,Manual,22.0",
          Content = "……闹了半天，你是看不惯我是个卡戎之民啊。",
          DialogueId = 11013615,
          Duration = 3,
          FinalCamera = "60.468475,373.251953,96.8255,0.0,-0.198417,-44.378376,30.000019,229.46875,false,Manual,22.0",
          GUID = "1B924936",
          NextDialogue = 11013616,
          SpeakNpcId = 110010,
          Subtitle = "...So you went through all the trouble, just because you don't like Charons?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924936"
        },
        [11013616] = {
          Camera = "-819.513733,862.818359,733.592957,0.000003,-32.798332,-28.176556,30.0,229.467407,false,DoNotOverride,22.0",
          Content = "那你早说，用不着上来就做这么绝吧？只要你放我从这里活着出去，我就想个办法早日退休，再也不挡你的路。",
          DialogueId = 11013616,
          Duration = 3,
          FacialId = {
            [1] = "110011:None"
          },
          FinalCamera = "-931.609741,922.859375,815.540222,0.000003,-32.798332,-28.176556,30.0,229.467407,false,DoNotOverride,22.0",
          GUID = "1B924960",
          NextDialogue = 11013617,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110010},AnimationId{"Talk01_End"},Duration{0}},
PlayAnimation{_delay{4},ActorId{110011},AnimationId{"Talk03_Start"},Duration{10}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You should've told me earlier. There's no need for such an elaborate ruse. Just let me off this time, and I'll retire early and stay out of your way forever.",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924960"
        },
        [11013617] = {
          Camera = "153.246658,302.361328,94.305695,-10.00189,5.400207,-63.975967,28.0,100000.0,false,DoNotOverride,22.0",
          Content = "如果你想要我为你效忠，也可以。只要把这次泄露作战情报的责任都推到{性别2：他|她}身上就行了。你我不但能全身而退，还能得一份揪出间谍的功劳。并且……",
          DialogueId = 11013617,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "157.790649,293.052734,95.28479,-10.00189,5.400207,-63.975967,28.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B92498A",
          NextDialogue = 11013618,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"549.498535,2849.632812,-810.490845,5.001147,-28.793985,-88.214127,50.0,100000.0,false,DoNotOverride,22.0"},duration{0}},CameraMoveTo{TargetPosition{"552.933838,2849.892578,-810.754639,5.001147,-28.793985,-88.214127,50.0,100000.0,false,DoNotOverride,22.0"},duration{10}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "If you need my loyalty, I can do that too. We can blame {性别2:him|her} for leaking our battle plans. Both of us walk away clean. Hell, we might even get a reward for uncovering a spy. And...",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92498A"
        },
        [11013618] = {
          Camera = "-13.393326,461.294922,163.357544,-0.000366,-19.199892,-42.771851,21.125469,100000.0,false,Manual,22.0",
          Content = "并且，你会多一条听话的狗。",
          DialogueId = 11013618,
          Duration = 3,
          FinalCamera = "-13.393326,461.294922,154.910889,-0.000366,-19.199892,-42.771851,21.125469,100000.0,false,Manual,22.0",
          GUID = "1B92498B",
          NextDialogue = 11013619,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110011},AnimationId{"Talk03_End"},Duration{0}},
PARA{LookAt{LookAtDescription{"110011:n(110010)"}},
TurnTo{TurnToDescription{"110011:n(110010)"}}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You'll gain an old dog obedient enough to follow your orders.",
          TalkActionId = {
            [1] = "110010:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92498B"
        },
        [11013619] = {
          Camera = "168.977859,253.941406,61.364716,-8.000504,16.603903,108.03064,21.125483,146.883423,false,Manual,5.0",
          Content = "哈，想不到你也挺下三滥的。不过，你也就只能想到这一步了。阿瓦尔，你以为你活着的那点用处，能比得上死了的你吗？",
          DialogueId = 11013619,
          Duration = 3,
          FacialId = {
            [1] = "110011:Smile01",
            [2] = "110010:Think01"
          },
          FinalCamera = "168.977859,253.941406,58.862396,-8.000504,16.603903,108.03064,21.125483,146.883423,false,Manual,5.0",
          GUID = "1B9249B4",
          NextDialogue = 11013620,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{10},TargetPosition{"118.145653,292.558594,103.879425,-3.0,-0.795013,-46.971291,30.000008,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"124.55114,285.693359,103.749207,-3.0,-0.795013,-46.971291,30.000008,100000.0,false,DoNotOverride,22.0"},duration{5}}
}
	]],
          SpeakNpcId = 110011,
          Subtitle = "Hah, how quaint, Avar — didn't expect you to stoop this low too. But you don't know the half of it, Avar. You're worth far more to us dead than alive.",
          TalkActionId = {
            [1] = "110011:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9249B4"
        },
        [11013620] = {
          Camera = "156.654633,254.740234,116.599792,-8.003376,-6.396171,107.63237,35.0,146.883423,false,DoNotOverride,5.0",
          Content = "动动你的脑子吧！如果全帝国都知道一个卡戎军官背弃军团，投靠神弃者同盟，害得一批帝国最年轻勇敢的精锐殒命——会发生什么？",
          DialogueId = 11013620,
          Duration = 3,
          FacialId = {
            [1] = "110010:None"
          },
          FinalCamera = "148.843872,279.322266,115.388702,-8.003376,-6.396171,107.63237,35.0,146.883423,false,DoNotOverride,5.0",
          GUID = "1B9249DE",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013621,
          Scripts = [[
SEQ{
PlayAnimation{_delay{3},ActorId{110011},AnimationId{"Sigh_Start"},Duration{10}},
PlayAnimation{ActorId{110011},AnimationId{"Sigh_End"},Duration{3}}
}
]],
          SpeakNpcId = 110011,
          Subtitle = "Use your head! Imagine the uproar if it came out that a high-ranking Charon officer defected and joined The Forsakens, resulting in the deaths of many of our best young soldiers.",
          TalkActionId = {
            [1] = "110011:Talk02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9249DE"
        },
        [11013621] = {
          Camera = "169.007309,92.732422,41.227081,-10.000513,6.204441,84.826546,21.125471,100000.0,false,DoNotOverride,22.0",
          Content = "高层里的桂冠卡戎本就饱受争议，届时他们还能留在现在的位子上？比如我们那位敬爱的长官——你知道有多少双眼睛在盯着她，等着看她如何跌得粉身碎骨吗？",
          DialogueId = 11013621,
          Duration = 3,
          FinalCamera = "139.76091,94.824219,46.366302,-10.000513,6.204441,84.826546,21.125471,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924A08",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013622,
          Scripts = [[
SEQ{
PlayAnimation{_delay{5},ActorId{110011},AnimationId{"Talk03_End"},Duration{5}},
PlayAnimation{ActorId{110011},AnimationId{"Talk02_Start"},Duration{0}}
}
]],
          SpeakNpcId = 110011,
          Subtitle = "Laurelled Charons in high office are already a thorn in plenty of sides. A scandal like this? It'll drag their names straight through the mud. Take our beloved superior — do you have any idea how many people wish to watch her crash and burn?",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A08"
        },
        [11013622] = {
          Camera = "9.816498,408.683594,91.287811,-0.001526,-0.599793,-38.348438,35.0,100000.0,false,Manual,22.0",
          Content = "西比尔？你想把她赶下去……你的目标是“军团长”？",
          DialogueId = 11013622,
          Duration = 3,
          FinalCamera = "11.8965,401.550781,91.224274,-0.001526,-0.599793,-38.34877,35.0,100000.0,false,Manual,22.0",
          GUID = "1B924A32",
          NextDialogue = 11013623,
          SpeakNpcId = 110010,
          Subtitle = "You mean Sibylle? You wish her gone... You're after her position and power?",
          TalkActionId = {
            [1] = "110011:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A32"
        },
        [11013623] = {
          Camera = "54.786392,-620.46875,9.960114,0.000071,7.403973,84.185303,22.000011,100000.0,false,DoNotOverride,22.0",
          Content = "也许吧，也许还有更多。不过，对你来说，都不重要了。",
          DialogueId = 11013623,
          Duration = 3,
          FinalCamera = "27.690643,-617.716797,9.960114,0.000071,7.403973,84.185303,22.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924A5C",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013624,
          Scripts = [[
PARA{
MoveTo{_delay{5},ActorId{110011},TargetPoint{"EX01_FixSimple_19point02"},MoveSpeed{65},Visibility{"Show"}},
CameraMoveTo{_delay{6},TargetPosition{"110.352188,24.90625,106.656708,0.000074,-3.195859,90.185249,40.000023,100000.0,false,DoNotOverride,22.0"},duration{0}}
}]],
          SpeakNpcId = 110011,
          Subtitle = "Perhaps. Maybe I want more. But that's no longer your concern.",
          TalkActionId = {
            [1] = "110011:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A5C"
        },
        [11013624] = {
          Camera = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
          Content = "等一下！",
          DialogueId = 11013624,
          Duration = 3,
          GUID = "1B924A86",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013625,
          SpeakNpcId = 110010,
          Subtitle = "Wait!",
          TurnTo = {
            [1] = "110010:n(110011)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A86"
        },
        [11013625] = {
          Camera = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
          Content = "我们来谈谈另一件事吧……<H>“零号”</>。",
          DialogueId = 11013625,
          Duration = 3,
          FacialId = {
            [1] = "110011:None"
          },
          GUID = "1B924AB0",
          NextDialogue = 11013626,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"175.50206,126.912109,133.876068,-0.001556,-18.199461,67.248505,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "We should talk about one more thing... About No. 0.",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924AB0"
        },
        [11013626] = {
          Camera = "151.601776,151.322266,102.676727,-0.001556,-4.801548,-108.713249,23.660721,100000.0,false,Manual,22.0",
          Content = "……嗯？",
          DialogueId = 11013626,
          Duration = 3,
          GUID = "1B924ADA",
          NextDialogue = 11013627,
          Scripts = "TurnTo{_delay{2},TurnToDescription{\"110011:p(180)\"}}",
          SpeakNpcId = 110011,
          Subtitle = "...Oh?",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924ADA"
        },
        [11013627] = {
          Camera = "63.279358,-238.914062,88.206848,-0.002014,-2.614016,77.062973,23.660721,100000.0,false,DoNotOverride,22.0",
          Content = "她是十三军团最宝贝的兵刃。如今西比尔虽然得到了她，但想要完成<H>“第二新枝”计划</>，还少了最关键的<H>“触媒”</>……",
          DialogueId = 11013627,
          Duration = 3,
          FinalCamera = "-60.852264,-120.474609,97.3927,-0.002014,-5.013919,43.262783,23.660721,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924B04",
          NextDialogue = 11013628,
          RelatedWikiId = {
            [1] = 403003
          },
          SpeakNpcId = 110010,
          Subtitle = "She is the most precious weapon of the 13th Legion. Sibylle controls her now, but to complete the Second Scion Program, she still needs the crucial \"Catalyst\"...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B04"
        },
        [11013628] = {
          Camera = "155.250778,120.773438,83.251434,10.002668,12.003586,50.623306,21.125479,95.12989,false,Manual,2.8",
          Content = "西比尔命你在弗莱格桑省搜寻“触媒”，但好像过程不怎么顺利啊。",
          DialogueId = 11013628,
          Duration = 3,
          FinalCamera = "159.07251,125.427734,84.532227,10.002668,12.003586,50.623306,21.125483,89.517586,false,Manual,2.8",
          GUID = "1B924B2E",
          NextDialogue = 11013629,
          SpeakNpcId = 110010,
          Subtitle = "Sibylle has ordered you to find the Catalyst in Flagson. But your search doesn't seem to be enjoying much success.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B2E"
        },
        [11013629] = {
          Camera = "99.726173,78.669922,83.391571,-10.008635,12.003312,-82.168861,21.125483,99.930809,false,Manual,2.8",
          Content = "你想说什么？别绕弯子。",
          DialogueId = 11013629,
          Duration = 3,
          FinalCamera = "100.516411,72.925781,84.624756,-10.008635,12.003312,-82.168861,21.125483,99.930809,false,Manual,2.8",
          GUID = "1B924B58",
          NextDialogue = 11013630,
          SpeakNpcId = 110011,
          Subtitle = "Get to the point, Avar.",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B58"
        },
        [11013630] = {
          Camera = "-540.700623,825.572266,22.562286,-5.000006,2.003171,-46.767361,40.000023,271.651154,false,DoNotOverride,10.0",
          Content = "富尔维斯，成为军团长的道路不止一条。就算你真靠演这一出赶走西比尔，你能保证陛下就一定会任命你接替她吗？",
          DialogueId = 11013630,
          Duration = 3,
          FinalCamera = "-522.103577,843.160156,24.800446,-5.000006,2.003171,-46.767361,40.000023,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924B82",
          NextDialogue = 11013631,
          Scripts = "PlayAnimation{_delay{6},ActorId{110010},AnimationId{\"Talk01_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "There are many paths to power, Fulvis. Even if this charade pushes Sibylle off her seat, how can you be sure the Emperor will let you take her place?",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924B82"
        },
        [11013631] = {
          Camera = "188.38916,374.509766,107.291229,-10.011471,-3.196467,-95.968758,40.000011,271.651154,false,DoNotOverride,13.0",
          Content = "真正能推你到那个位子的，是一份无可替代的“功劳”。",
          DialogueId = 11013631,
          Duration = 3,
          FinalCamera = "186.448547,355.947266,106.248871,-10.011503,-3.196467,-95.968758,40.000011,271.651154,false,DoNotOverride,13.0",
          GUID = "1B924BAC",
          NextDialogue = 11013632,
          SpeakNpcId = 110010,
          Subtitle = "You need some kind of unparalleled credit to propel you to the Legion's head.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924BAC"
        },
        [11013632] = {
          Camera = "96.940521,78.816406,89.251038,-10.007017,12.402838,-85.163452,40.000023,271.651154,false,DoNotOverride,10.0",
          Content = "继续。",
          DialogueId = 11013632,
          Duration = 3,
          GUID = "1B924BD6",
          NextDialogue = 11013633,
          SpeakNpcId = 110011,
          Subtitle = "I'm listening.",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924BD6"
        },
        [11013633] = {
          Camera = "-2118.515137,-306.582031,571.609009,0.00001,-10.997062,16.436613,40.0,271.651154,false,DoNotOverride,10.0",
          Content = "“第二新枝”计划对帝国来说太重要了，胜过一百个龙莎要塞。如果你找到“触媒”，完成计划的最后一块拼图，那时整个皇都都会高呼你的名字——安东尼·富尔维斯。",
          DialogueId = 11013633,
          Duration = 3,
          FinalCamera = "-2147.418945,-208.613281,571.609009,0.00001,-10.997062,16.436708,40.0,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924C00",
          NextDialogue = 11013634,
          SpeakNpcId = 110010,
          Subtitle = "The Second Scion Program is too important to the Empire. It's worth far more than a hundred Lonza Fortresses combined. If you find the \"Catalyst,\" which is the final piece of the puzzle, the entire capital will chant your name — Antonius Fulvis.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C00"
        },
        [11013634] = {
          Camera = "206.033554,354.041016,73.645569,0.000024,1.20283,-101.165855,40.0,271.651154,false,DoNotOverride,10.0",
          Content = "这对你来说正是无可替代的功劳。而我之前碰巧在机缘巧合之下，知道了它的下落。现在，我愿意将这份功劳让给你。",
          DialogueId = 11013634,
          Duration = 3,
          FinalCamera = "201.324173,330.189453,74.156342,0.000024,1.20283,-101.165855,40.0,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924C2A",
          NextDialogue = 11013635,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8},TargetPosition{"-29.667725,-114.439453,111.371826,0.000021,-2.396822,48.637676,60.0,271.651154,false,DoNotOverride,10.0"},duration{0}},CameraMoveTo{TargetPosition{"-10.139755,-92.255859,109.041138,0.000021,-2.396822,48.637676,60.0,271.651154,false,DoNotOverride,10.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "It's the unparalleled credit you need. And I, by circumstance and chance, happen to know of its whereabouts. I am willing to concede this to you.",
          TalkActionId = {
            [1] = "110011:Talk03_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C2A"
        },
        [11013635] = {
          Camera = "85.258636,144.519531,44.719849,0.000028,19.801844,-82.964874,40.000027,271.651154,false,DoNotOverride,10.0",
          Content = "这倒是有点意思。",
          DialogueId = 11013635,
          Duration = 3,
          FinalCamera = "86.617958,133.511719,48.716034,0.000028,19.801844,-82.964874,40.000027,271.651154,false,DoNotOverride,10.0",
          GUID = "1B924C54",
          NextDialogue = 11013636,
          SpeakNpcId = 110011,
          Subtitle = "Now we're talking.",
          TalkActionId = {
            [1] = "110011:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C54"
        },
        [11013636] = {
          Camera = "99.722374,88.037109,96.940674,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0",
          Content = "这便是我的“交易”。我需要你的承诺——放我和外面那些先遣小队的士兵一条生路。",
          DialogueId = 11013636,
          Duration = 3,
          GUID = "1B924C7E",
          NextDialogue = 11013637,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8},TargetPosition{"150.76915,147.746094,105.232941,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0"},duration{0}},CameraMoveTo{TargetPosition{"157.346924,153.925781,105.611877,0.000021,2.40286,43.238102,40.0,271.651154,false,DoNotOverride,10.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "That would be my end of the deal. All I ask in return is your word — let me and my people walk out alive.",
          TalkActionId = {
            [1] = "110011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924C7E"
        },
        [11013637] = {
          Camera = "116.448387,93.667969,95.850342,0.000025,5.602879,-99.561935,40.0,271.651154,false,DoNotOverride,10.0",
          Content = "真是大家的好长官！好吧，就在此地、此刻，告诉我“触媒”的下落，别耍任何花招，你没有谈判的条件。",
          DialogueId = 11013637,
          Duration = 3,
          GUID = "1B924CA8",
          NextDialogue = 11013638,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"-608.948547,3198.607422,754.886475,0.000048,-12.996736,-70.159851,40.0,271.651154,false,DoNotOverride,10.0"},duration{0}},CameraMoveTo{TargetPosition{"-547.46936,3220.791016,754.886475,0.000048,-12.996736,-70.159851,40.0,271.651154,false,DoNotOverride,10.0"},duration{8}}
}]],
          SpeakNpcId = 110011,
          Subtitle = "What a noble commander. Alright, tell me where the \"Catalyst\" is — right here, right now. No stalling, no tricks. You don't have leverage.",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B924CA8"
        },
        [11013638] = {
          Camera = "56.335129,-55.574219,108.552826,0.000057,-1.196704,55.040733,60.0,271.651154,false,Manual,20.0",
          Content = "好吧。它就在……",
          DialogueId = 11013638,
          Duration = 3,
          FinalCamera = "61.549301,-48.115234,108.362793,0.000057,-1.196704,55.040733,60.0,271.651154,false,Manual,20.0",
          GUID = "1B924CD2",
          NextDialogue = 11013639,
          SpeakNpcId = 110010,
          Subtitle = "Fine. It's at...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924CD2"
        },
        [11013639] = {
          Camera = "116.628403,103.859375,152.601593,0.000028,-21.397213,-99.75634,60.000019,271.651154,false,DoNotOverride,20.0",
          Content = "嗯，我知道了。接下来，只要……",
          DialogueId = 11013639,
          Duration = 3,
          FinalCamera = "114.449196,91.181641,147.562653,0.000028,-21.397213,-99.75634,60.000019,271.651154,false,DoNotOverride,20.0",
          GUID = "1B924CFC",
          SpeakNpcId = 110011,
          Subtitle = "Oh, thanks. As for now, I just need one last thing...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924CFC"
        },
        [11013640] = {
          DialogueId = 11013640,
          DialoguePanelType = "None",
          Duration = 6,
          GUID = "1B924811",
          IsBlack = 1,
          NextDialogue = 11013609
        },
        [11013701] = {
          Content = "阿瓦尔，别太信任一个实用主义者。",
          DialogueId = 11013701,
          Duration = 3,
          GUID = "1B925752",
          SpeakNpcId = 110011,
          Subtitle = "Remember, Avar, never trust a pragmatist.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B925752"
        },
        [11013702] = {
          Content = "法露茜，你留下，处理干净。",
          DialogueId = 11013702,
          Duration = 3,
          GUID = "1B92577C",
          IsBlack = 1,
          NextDialogue = 11013703,
          SpeakNpcId = 110011,
          Subtitle = "Stay behind, Falsi. Clean up this mess.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B92577C"
        },
        [11013703] = {
