          DialogueId = 11013703,
          Duration = 3,
          GUID = "1B9257A6",
          IsBlack = 1,
          NextDialogue = 11019301,
          SpeakNpcId = 110012,
          Subtitle = "Yes, sir.",
          VoiceName = "voice/$Locale$/story/1002/110137/1B9257A6"
        },
        [11013705] = {
