        },
        [11015907] = {
          Content = "我将凶手带到审判长大人面前……恳求审判长大人给予公正的判决……",
          DialogueId = 11015907,
          Duration = 3,
          GUID = "1B93C13E",
          NextDialogue = 11015908,
          SpeakNpcId = 110005,
          SpeakNpcName = "UI_Npc_DreamDafu",
          Subtitle = "I've brought the murderer to you, ma'am... I humbly request you to deliver a fair and just verdict...",
          TalkActionId = {
            [1] = "110005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C13E"
        },
        [11015908] = {
          Content = "……你不是达芙涅。",
          DialogueId = 11015908,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93C168",
          SpeakNpcId = 110022,
          Subtitle = "...You're not Daphne.",
          TalkActionId = {
            [1] = "0:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110159/1B93C168"
        },
        [11016001] = {
          Camera = "657.027344,-647.62207,449.714844,0.000194,-31.196772,156.787415,25.0,100000.0,false,DoNotOverride,22.0",
          Content = "如审判长大人所见，我是龙莎要塞中央控制室的控制台……",
          DialogueId = 11016001,
          Duration = 3,
          GUID = "1B93D0AA",
          NextDialogue = 11019317,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "As you can see, ma'am, I am the control panel in the central control room of Lonza Fortress...",
          VoiceName = "voice/$Locale$/story/1002/110160/1B93D0AA"
        },
        [11016005] = {
          Content = "海伯利亚军团箴言第十八条：过于顺利的战况之后，很可能就是敌人的埋伏……",
          DialogueId = 11016005,
          Duration = 3,
          GUID = "1B93D152",
          NextDialogue = 11016006,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Motto 18 of the Hyperborean Legion: An unexpectedly easy victory often leads to an impending ambush...",
          VoiceName = "voice/$Locale$/story/1002/110160/1B93D152"
        },
        [11016006] = {
          Content = "……为什么你在梦里也要复读那些箴言啊！",
          DialogueId = 11016006,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93D17C",
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SpeakNpcId = 110022,
          Subtitle = "...I can't believe you have to recite those mottos even in my dreams.",
          VoiceName = "voice/$Locale$/story/1002/110160/1B93D17C"
        },
        [11016101] = {
          Camera = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
          Content = "所有审判，皆为正义。",
          DialogueId = 11016101,
          Duration = 3,
          GUID = "1B93E112",
          NextDialogue = 11016102,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          Subtitle = "All verdicts are in the name of justice.",
          TalkActionId = {
            [1] = "110032:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110161/1B93E112"
        },
        [11016102] = {
          Camera = "-11.319336,897.331055,144.578125,0.000127,5.398841,86.191856,17.134987,100000.0,false,Manual,22.0",
          Content = "你须如实回答所有问题，不得有半分虚假、矫饰或隐瞒。",
          DialogueId = 11016102,
          Duration = 3,
          GUID = "1B93E13C",
          NextDialogue = 11019017,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          Subtitle = "All questions must be answered absent falsehood. I tolerate no fabrication, alteration, or concealment of the truth.",
          VoiceName = "voice/$Locale$/story/1002/110161/1B93E13C"
        },
        [11016201] = {
          Camera = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
          Content = "龙莎要塞一役中，先遣队伍全军覆没，是否与你有关？",
          DialogueId = 11016201,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B93F17A",
          NextDialogue = 11016202,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "The vanguard squads were obliterated in the battle of Lonza Fortress. Were you the architect of their doom?",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F17A"
        },
        [11016202] = {
          Camera = "-11.319336,897.331055,144.578125,0.000127,5.398841,86.191856,17.134987,100000.0,false,Manual,22.0",
          Content = "好好感受吧！因为某些人的背叛，他们不得不这样死去！",
          DialogueId = 11016202,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B93F1A4",
          NextDialogue = 11016203,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Feel their agony! Betrayal led them to untimely deaths.",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F1A4"
        },
        [11016203] = {
          Camera = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
          Content = "若你背弃了同胞的正义，就被秽兽的利爪撕碎！",
          DialogueId = 11016203,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B93F1CE",
          NextDialogue = 11016204,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Should you betray the justice of your comrades, these Filthoids' claws shall tear you to pieces!",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F1CE"
        },
        [11016204] = {
          Camera = "13.287109,114.423828,114.03125,-0.000825,14.198904,-86.82589,17.134987,100000.0,false,Manual,22.0",
          Content = "（他们就是被这些怪物……富尔维斯……甚至用这样的怪物来对付自己的同胞……！）",
          DialogueId = 11016204,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93F1F8",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(They were killed by these monsters... Fulvis... He actually unleashed these monsters upon his own comrades...!)",
          VoiceName = "voice/$Locale$/story/1002/110162/1B93F1F8"
        },
        [11016301] = {
          Content = "最后一个问题，阿瓦尔·赫德兰的死亡，是否是你所为？",
          DialogueId = 11016301,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B9401E2",
          NextDialogue = 11016302,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "One last question. Are you the cause of Avar Hrodland's demise?",
          VoiceName = "voice/$Locale$/story/1002/110163/1B9401E2"
        },
        [11016302] = {
          Content = "即使他背叛了帝国，他也一直信任你。他葬身火海中的时候，你在做什么？",
          DialogueId = 11016302,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B94020C",
          NextDialogue = 11016305,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Despite his faults, he trusted you. Where were you when he was consumed by flames?",
          VoiceName = "voice/$Locale$/story/1002/110163/1B94020C"
        },
        [11016303] = {
          Content = "（是的……他<H>的的确确</>那样信任我……）",
          DialogueId = 11016303,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B940236",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Yes... He truly trusted me...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B940236"
        },
        [11016304] = {
          Content = "（在完成复仇之前，我必须活下去……不能让这个女人杀了我……）",
          DialogueId = 11016304,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B940260",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(I must survive... to avenge him... I cannot let this woman kill me...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B940260"
        },
        [11016305] = {
          Content = "若你背弃了同伴的正义，就被这狱火灼烧殆尽！",
          DialogueId = 11016305,
          DisableMouth = 1,
          Duration = 3,
          GUID = "1B94028A",
          NextDialogue = 11019052,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Should you betray the loyalty of friendship, these infernal flames shall burn you to ashes!",
          VoiceName = "voice/$Locale$/story/1002/110163/1B94028A"
        },
        [11016306] = {
          Content = "（正义……正义……她一直在追求的，正是“正义”……）",
          DialogueId = 11016306,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9402B4",
          NextDialogue = 11016307,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Justice... justice... That's what she keeps talking about...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B9402B4"
        },
        [11016307] = {
          Content = "（是时候……把<H>那件事</>告诉她了……）",
          DialogueId = 11016307,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9402DE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Time to reveal the truth of that day...)",
          VoiceName = "voice/$Locale$/story/1002/110163/1B9402DE"
        },
        [11016401] = {
          Content = "典狱长大人，为了你心中的正义——",
          DialogueId = 11016401,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94124A",
          NextDialogue = 11016402,
          SpeakNpcId = 110022,
          Subtitle = "Ma'am, to satisfy the justice you seek—",
          VoiceName = "voice/$Locale$/story/1002/110164/1B94124A"
        },
        [11016402] = {
          Content = "让我来告诉你真相吧。那天在中央控制室，全部的“真相”。",
          DialogueId = 11016402,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B941274",
          SpeakNpcId = 110022,
          Subtitle = "Allow me to tell you the truth... of what unfolded in the central control room that day.",
          VoiceName = "voice/$Locale$/story/1002/110164/1B941274"
        },
        [11016501] = {
          Camera = "-12.243164,-221.074219,149.612579,0.001641,-5.409393,88.605331,35.932411,100000.0,false,Manual,22.0",
          Content = "…………！！",
          DialogueId = 11016501,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Close"
          },
          FinalCamera = "-14.769531,-324.904297,159.446762,0.001641,-5.209378,88.605347,35.932411,257.489166,false,Manual,22.0",
          GUID = "1B9422B2",
          LookAt = {
            [1] = "110039:n(110022)"
          },
          NextDialogue = 11016502,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"},RelatedRegionId{102104}},
PlayFacial{_delay{0.5},ActorId{110022},FacialId{"Pain01"}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "...!!",
          TalkActionId = {
            [1] = "110022:Weita_Story_Awake_Start",
            [2] = "110039:Sit_Idle_Loop"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110165/1B9422B2"
        },
        [11016502] = {
          Camera = "43.549805,139.308594,128.25798,0.001613,-1.609104,-101.194138,36.903526,100000.0,false,Manual,22.0",
          Content = "……怎么突然醒了？我正问到最关键的部分！",
          DialogueId = 11016502,
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "52.8125,137.478516,128.257767,0.001613,-1.209135,-100.994232,36.903526,100000.0,false,Manual,22.0",
          GUID = "1B9422DC",
          LookAt = {
            [1] = "110022:n(110039)"
          },
          NextDialogue = 11016503,
          SpeakNpcId = 110039,
          Subtitle = "...Why did you wake up? My questioning had just reached a pivotal point!",
          TalkActionId = {
            [1] = "110022:Weita_Story_Awake_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B9422DC"
        },
        [11016503] = {
          Camera = "67.43457,-649.426758,129.53125,0.001605,-4.809197,104.412491,36.90353,100000.0,false,Manual,22.0",
          Content = "没关系，典狱长大人。我还记得我在梦中对你说了什么。",
          DialogueId = 11016503,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942306",
          NextDialogue = 11016504,
          Scripts = "SitOrStand{ActorId{110022},State{\"Sit\"}}",
          SpeakNpcId = 110022,
          Subtitle = "It's alright, ma'am. I remember what I told you in my dreams. But this is classified, I request a private conversation with you.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942306"
        },
        [11016504] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,105.270081,false,Manual,22.0",
          Content = "我会将那天的真相原原本本地告诉你，也希望你听过之后，能凭借你心中的那份“正义”做出选择。",
          DialogueId = 11016504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942330",
          NextDialogue = 11016505,
          SpeakNpcId = 110022,
          Subtitle = "I'll tell you exactly what happened that day. Once you've heard the truth, I hope the justice within your heart will guide your decision.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942330"
        },
        [11016505] = {
          Camera = "32.214844,139.163086,128.258286,0.001612,-2.00912,-97.193909,36.903526,100000.0,false,Manual,22.0",
          Content = "你说吧。",
          DialogueId = 11016505,
          GUID = "1B94235A",
          NextDialogue = 11016506,
          SpeakNpcId = 110039,
          Subtitle = "Go ahead.",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110165/1B94235A"
        },
        [11016506] = {
          Camera = "-1.37793,-810.395508,591.001038,0.001542,-46.808487,89.804596,16.538609,100000.0,false,Manual,22.0",
          Content = "那天……",
          DialogueId = 11016506,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-0.708984,-729.607422,508.35968,0.001516,-44.60828,88.804398,16.538609,100000.0,false,Manual,22.0",
          GUID = "1B942384",
          NextDialogue = 11016601,
          SpeakNpcId = 110022,
          Subtitle = "On that day...",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B942384"
        },
        [11016601] = {
          Content = "让我们好好谈一谈吧。",
          DialogueId = 11016601,
          GUID = "1B94331A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016601.T_Story_Recall_11016601‘",
          NextDialogue = 11016602,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"},RelatedRegionId{102104}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We need to have a SERIOUS discussion about this.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94331A"
        },
        [11016602] = {
          Content = "我长话短说。我们没有多少时间了，如果接下来还是联络不上外面，我就用这把枪向你射击，而你要做的是——装死。",
          DialogueId = 11016602,
          GUID = "1B943344",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016603,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll keep it short — we're out of time. If we still can't reach the outside... I shoot you with this gun. And you play dead.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943344"
        },
        [11016603] = {
          Content = "为了把戏做足，我会打得更真一点。虽然不是要害，但可能会很疼。你一定要忍住，别出声。",
          DialogueId = 11016603,
          GUID = "1B94336E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016604,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To make it convincing enough, the shot will have to hit. It will miss your vitals but will really hurt. You must endure the pain silently.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94336E"
        },
        [11016604] = {
          Content = "您要做什么？",
          DialogueId = 11016604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943398",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016604.T_Story_Recall_11016604'",
          NextDialogue = 11016605,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "What are you going to do?",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943398"
        },
        [11016605] = {
          Content = "我们被困在这道门里，和外面的通讯全被切断了。富尔维斯就在路上……算算时间，这会儿他应该已经把持了整座要塞。",
          DialogueId = 11016605,
          GUID = "1B9433C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016606,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We're trapped in here, completely cut off. Fulvis is already on the move... by now, he's probably seized the whole fortress.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433C2"
        },
        [11016606] = {
          Content = "死人才不会辩解，富尔维斯一定会要我的命。你和我一起行动，又目睹了他构陷的经过，他想必也不会让你活着回去。",
          DialogueId = 11016606,
          GUID = "1B9433EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016607,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Only the dead stay silent forever. He'll kill me — no doubt. And you... you're in this too. You've seen the fake evidence. He won't let you walk away either.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433EC"
        },
        [11016607] = {
          Content = "…………！！",
          DialogueId = 11016607,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943416",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016607.T_Story_Recall_11016607'",
          NextDialogue = 11016608,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943416"
        },
        [11016608] = {
          Content = "没关系，有我呢。",
          DialogueId = 11016608,
          GUID = "1B943440",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016609,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "It's okay, I got you.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943440"
        },
        [11016609] = {
          Content = "……如果我“杀了你”，假借内讧向他投诚，他就有可能放松警惕，放过你……这是能让你活下去的唯一方式了。",
          DialogueId = 11016609,
          GUID = "1B94346A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016610,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...If I \"kill\" you and feign allegiance to him... he might lower his guard. You'll slip under the radar — it's your only shot.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94346A"
        },
        [11016610] = {
          Content = "不……老师，等他们打开门，我们就一起杀出去！",
          DialogueId = 11016610,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943494",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016610.T_Story_Recall_11016610'",
          NextDialogue = 11016622,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "No... Sir Avar — once that door opens, we're going out together!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943494"
        },
        [11016612] = {
          Content = "等会儿我会试着先和富尔维斯谈判。当然，多半是谈不拢的，所以别抱希望。我去和他谈判，只是为了一个重要的东西——",
          DialogueId = 11016612,
          GUID = "1B9434E8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016613,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll try to negotiate with Fulvis, though I believe it's going to fail in the end, so don't get your hopes up. The negotiation is for a more important purpose—",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9434E8"
        },
        [11016613] = {
          Content = "“证据”。",
          DialogueId = 11016613,
          Duration = 3,
          GUID = "1B943512",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016613.T_Story_Recall_11016613'",
          NextDialogue = 11016614,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To collect evidence.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943512"
        },
        [11016614] = {
          Content = "这是录音设备，你贴身带着。它会成为你日后扳倒富尔维斯的铁证。",
          DialogueId = 11016614,
          GUID = "1B94353C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016615,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Take this recording device. It'll provide the evidence needed to expose and destroy Fulvis.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94353C"
        },
        [11016615] = {
          Content = "决不能让士兵们冤屈的哭号，永远在龙莎要塞上空徘徊。",
          DialogueId = 11016615,
          GUID = "1B943566",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016616,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We can't let the cries of the wronged echo over Lonza Fortress forever.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD42"
        }
      }
    end
  },
  {
    MinKey = 11016616,
