        [11016805] = {
          Content = "……怎么直接当面说出来了……",
          DialogueId = 11016805,
          GUID = "1B945492",
          LookAt = {
            [1] = "110040:n(110041)"
          },
          NextDialogue = 11016806,
          SpeakNpcId = 110041,
          Subtitle = "...You weren't supposed to know that part...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945492"
        },
        [11016806] = {
          Content = "那、那个，我也不知道为什么，从今天下午开始，审问官突然变温和了许多，甚至还主动问我有什么特别想实现的心愿。",
          DialogueId = 11016806,
          GUID = "1B9454BC",
          LookAt = {
            [1] = "110041:n(110040)"
          },
          NextDialogue = 11016807,
          SpeakNpcId = 110041,
          Subtitle = "Well, I don't know what happened, but the interrogator seemed much more accommodating this afternoon. He even asked if I wanted anything.",
          TalkActionId = {
            [1] = "110041:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9454BC"
        },
        [11016807] = {
          Content = "但我的供词一直都是那些……是您说了什么，打动了典狱长吗？",
          DialogueId = 11016807,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B9454E6",
          NextDialogue = 11016808,
          Scripts = "CameraMoveTo{_delay{4},TargetPosition{\"97.759766,656.613281,129.179688,0.000218,-0.592225,-99.797882,40.0,150.488785,false,DoNotOverride,22.0\"},duration{0}}",
          SpeakNpcId = 110041,
          Subtitle = "My testimony hasn't changed... Did you say something that swayed the Warden?",
          VoiceName = "voice/$Locale$/story/1002/110168/1B9454E6"
        },
        [11016808] = {
          Camera = "208.457031,192.4375,122.078125,0.00018,1.007186,-146.99411,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "……还是说——难道，这是死刑之前最后的怜悯？！",
          DialogueId = 11016808,
          FacialId = {
            [1] = "110041:Iyada01"
          },
          FinalCamera = "175.138672,170.794922,122.734375,0.00018,1.007186,-146.99411,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B945510",
          NextOptions = {
            [1] = 11016809,
            [2] = 11016815
          },
          SpeakNpcId = 110041,
          Subtitle = "...Or is this some sort of final kindness before our execution!?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945510"
        },
        [11016809] = {
          Content = "没错，我认罪了，我们就要被处决了。",
          DialogueId = 11016809,
          GUID = "1B94553A",
          ImprPlusId = 1010,
          NextDialogue = 11016810,
          Subtitle = "You're right. I pleaded guilty. We'll be executed soon."
        },
        [11016810] = {
          Camera = "63.871094,234.428711,141.222656,0.000184,-7.192995,-92.993393,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "……是吗……我明白了。这也是没办法的事，毕竟他们的拷问真的很疼。",
          DialogueId = 11016810,
          GUID = "1B945564",
          NextDialogue = 11016811,
          SpeakNpcId = 110041,
          Subtitle = "...Really...? I see. I suppose you had no other choice. No one can withstand such intense interrogation.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945564"
        },
        [11016811] = {
          Camera = "143.042969,124.328125,135.328125,0.000179,-4.592988,-161.391342,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "没关系的，您已经保护我够久了。所以，没关系的。",
          DialogueId = 11016811,
          FacialId = {
            [1] = "110041:Pain01"
          },
          GUID = "1B94558E",
          LookAt = {
            [1] = "110041:n(110040)",
            [2] = "110040:n(110041)"
          },
          NextDialogue = 11016812,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110041},AnimationId{"Sit_Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "It's alright. You've done so much to protect me already...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94558E"
        },
        [11016812] = {
          Camera = "69.114258,343.46875,128.84375,0.000188,-1.793054,97.209267,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "不要真信，我开个玩笑……",
          DialogueId = 11016812,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110041:Sad01",
            [2] = "110040:Sad01"
          },
          GUID = "1B9455B8",
          NextDialogue = 11016813,
          SpeakNpcId = 110040,
          Subtitle = "It's not true. I was just messing with you...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9455B8"
        },
        [11016813] = {
          Camera = "79.359375,250.193359,124.222656,0.000161,0.407284,-99.607933,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "你这个人真是的——吓死我了……你、你要给我道歉的……",
          DialogueId = 11016813,
          FacialId = {
            [1] = "110040:Unhappy01"
          },
          FinalCamera = "73.981445,218.426758,124.433594,0.000161,0.407284,-99.607933,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B9455E2",
          NextDialogue = 11016814,
          Scripts = [[
PARA{
CameraMoveTo{_delay{0.3},TargetPosition{"72.458008,209.397461,124.488281,0.000158,0.407284,-99.607986,35.0,150.488785,false,DoNotOverride,22.0"},duration{3}},
SEQ{
PlayAnimation{_delay{4},ActorId{110041},AnimationId{"Sit_Talk03_End"},Duration{1}}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Wha... You really scared me... Y—You owe me an apology...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110168/1B9455E2"
        },
        [11016814] = {
          Camera = "85.217773,355.307617,126.359375,0.000139,-0.195576,100.594894,35.0,298.040161,false,Manual,15.739686",
          Content = "如果海尔法的调查顺利，我想过不了多久我们就能出去了。到时候，请你看场歌剧作为赔礼吧。",
          DialogueId = 11016814,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:None"
          },
          GUID = "1B94560C",
          NextDialogue = 11016820,
          Scripts = "PlayAnimation{_delay{6},ActorId{110040},AnimationId{\"Sit_Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 110040,
          Subtitle = "If Warden Hellfire's investigation goes well, we'll be free soon. I'll make it up to you by taking you to the opera house.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94560C"
        },
        [11016815] = {
          Content = "典狱长相信了我的证词，她去调查法露茜了。",
          DialogueId = 11016815,
          GUID = "1B945636",
          ImprPlusId = 1009,
          NextDialogue = 11016816,
          Subtitle = "The Warden believed what I said and went to investigating Falsi."
        },
        [11016816] = {
          Camera = "77.791992,275.038086,116.648438,0.000166,0.404306,-96.204185,35.0,298.040161,false,Manual,15.739686",
          Content = "太好了。",
          DialogueId = 11016816,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B945660",
          NextDialogue = 11016817,
          SpeakNpcId = 110041,
          Subtitle = "Oh, that's great.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945660"
        },
        [11016817] = {
          Camera = "140.551758,369.635742,116.640625,0.000213,2.207462,117.81002,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "……你身上又多了好多伤，很痛吧……我、我去求他们把医药箱还给我……",
          DialogueId = 11016817,
          GUID = "1B94568A",
          NextDialogue = 11016818,
          SpeakNpcId = 110041,
          Subtitle = "...You've got a lot more injuries. They must hurt... I... I'll beg them to give me back my first-aid kit...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94568A"
        },
        [11016818] = {
          Content = "我还好，你先给自己治疗一下吧……",
          DialogueId = 11016818,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:Smile02"
          },
          GUID = "1B9456B4",
          NextDialogue = 11016819,
          SpeakNpcId = 110040,
          Subtitle = "I'm fine. You should take care of your own injuries though...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9456B4"
        },
        [11016819] = {
          Camera = "70.556641,275.821289,116.648438,0.000166,0.404306,-96.204208,35.0,298.040161,false,Manual,15.739686",
          Content = "……如果海尔法典狱长的调查顺利，我想过不了多久我们就能出去了。",
          DialogueId = 11016819,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B9456DE",
          NextDialogue = 11016820,
          SpeakNpcId = 110040,
          Subtitle = "...If Warden Hellfire's investigation goes well, we'll be free soon.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B9456DE"
        },
        [11016820] = {
          Camera = "70.556641,275.821289,116.648438,0.000166,0.404306,-96.204208,35.0,298.040161,false,Manual,15.739686",
          Content = "嗯……",
          DialogueId = 11016820,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B945708",
          NextDialogue = 11016821,
          SpeakNpcId = 110041,
          Subtitle = "I hope so...",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B945708"
        },
        [11016821] = {
          Camera = "575.697266,-116.007812,144.9375,0.000189,-2.195585,142.396973,35.0,298.040161,false,Manual,15.739686",
          Content = "……还有一件事。抱歉，虽然可能会让您想起不快的回忆，但我很怕以后再也没有机会问了。",
          DialogueId = 11016821,
          FacialId = {
            [1] = "110041:Sad01"
          },
          FinalCamera = "656.711914,-178.397461,148.828125,0.000189,-2.195585,142.396973,35.0,298.040161,false,Manual,15.739686",
          GUID = "1B945732",
          NextDialogue = 11016822,
          Scripts = [[
PARA{
CameraMoveTo{_delay{6},TargetPosition{"130.480469,196.420898,116.089844,0.000191,3.395519,-130.203705,35.000011,150.488785,false,Manual,22.0"},duration{0}},
PlayAnimation{ActorId{110041},AnimationId{"Sit_Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "...And one more thing. I'm sorry, this might bring back painful memories, but I must ask while I can.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945732"
        },
        [11016822] = {
          Camera = "319.923828,100.185547,570.714844,0.000388,-57.783604,139.785599,14.723656,298.040161,false,Manual,16.645706",
          Content = "上次在要塞里，情况危急，您没有告诉我父亲的事。现在我已经整理好了心情，可以请您讲给我听吗？父亲他最后……有没有留下什么？",
          DialogueId = 11016822,
          FacialId = {
            [1] = "110040:None"
          },
          FinalCamera = "388.981445,216.772461,570.714844,0.00043,-57.782646,164.184372,14.723656,298.040161,false,Manual,16.645706",
          GUID = "1B94575C",
          NextDialogue = 11016823,
          SpeakNpcId = 110041,
          Subtitle = "Back at the fortress, the situation was so desperate that you didn't have time to tell me about my father's death. But I've sorted out my mood. Can you tell me about it now? Did my father... leave anything behind?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110168/1B94575C"
        },
        [11016823] = {
          Camera = "155.694336,479.422852,136.015625,0.000339,-1.994654,152.595154,35.000008,116.258575,false,Manual,9.707766",
          Content = "…………",
          DialogueId = 11016823,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B945786",
          NextDialogue = 11016824,
          SpeakNpcId = 110040,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945786"
        },
        [11016824] = {
          Camera = "153.564453,378.640625,135.929688,0.000189,-3.592713,124.006393,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "他留下了这个。这张照片被他藏在贴身口袋里，最靠近心脏的位置。",
          DialogueId = 11016824,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9457B0",
          SpeakNpcId = 110040,
          Subtitle = "Sir Avar kept this with him at all times, in the pocket closest to his heart.",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_Start",
            [2] = "110041:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9457B0"
        },
        [11016825] = {
          Camera = "159.3125,228.97168,103.3125,0.000155,7.203923,-128.800171,35.000008,150.488785,false,Manual,22.0",
          Content = "还有一句话，是他最后对我说的——",
          DialogueId = 11016825,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110041:Sad01"
          },
          GUID = "1B9457DA",
          NextDialogue = 11016826,
          Scripts = "PlayAnimation{ActorId{110041},AnimationId{\"Sit_Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 110040,
          Subtitle = "He wanted you to have this message—",
          TalkActionId = {
            [1] = "110041:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9457DA"
        },
        [11016826] = {
          Camera = "92.726562,649.960938,135.03125,0.000137,-2.595936,-96.005997,35.000008,524.177307,false,Manual,22.0",
          Content = "“有机会的话，请你找到达芙涅。如果她还活着，带她一起……逃出去。等安全了，告诉她——”",
          DialogueId = 11016826,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "88.107422,606.015625,133.039062,0.000137,-2.595936,-96.005997,35.000008,524.177307,false,Manual,22.0",
          GUID = "1B945804",
          NextDialogue = 11016827,
          Scripts = "SetLocation{ActorId{110021},TargetPoint{\"fix27jt\"},Visibility{\"Show\"}},",
          SpeakNpcId = 110040,
          SpeakNpcName = "UI_Npc_AwaAndMe",
          Subtitle = "\"Find Daphne if possible. If she's alive, get her out of here... Once you're both safe, tell her—\"",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945804"
        },
        [11016827] = {
          Camera = "244.314453,274.294922,106.882812,0.000178,2.404472,-134.798203,35.000008,298.040161,false,Manual,15.739686",
          Content = "“对不起，我的女儿。其实我一直等着，你再叫我一声‘爸爸’，像小时候一样。”",
          DialogueId = 11016827,
          FacialId = {
            [1] = "110041:Sad01"
          },
          FinalCamera = "195.5,309.150391,106.882812,0.000179,2.804441,-121.197876,35.000008,298.040161,false,Manual,15.739686",
          GUID = "1B94582E",
          NextDialogue = 11016828,
          Scripts = [[
SEQ{
PlayAnimation{_delay{6},ActorId{110041},AnimationId{"Sit_Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "\"I'm sorry, my baby girl. I've always wanted to hear you call me Dad again, just like when you were little.\"",
          TalkActionId = {
            [1] = "110040:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110168/1B94582E"
        },
        [11016828] = {
          Camera = "112.149414,184.543945,122.972656,0.000185,1.604336,-122.205658,44.331512,115.939659,false,Manual,15.739686",
          Content = "……他……怎么还留着这张呢……",
          DialogueId = 11016828,
          FacialId = {
            [1] = "110041:Sad02"
          },
          GUID = "1B945858",
          NextDialogue = 11016829,
          SpeakNpcId = 110041,
          Subtitle = "...He... kept this photo all along...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945858"
        },
        [11016829] = {
          Camera = "350.745117,705.481445,547.363281,0.000123,-42.805061,-126.604477,20.017895,150.488785,false,Manual,22.0",
          Content = "明明……我都已经长这么大了……",
          DialogueId = 11016829,
          GUID = "1B945882",
          NextDialogue = 11016830,
          SpeakNpcId = 110041,
          Subtitle = "So long that... I'm not the little girl in the photo anymore...",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945882"
        },
        [11016830] = {
          Camera = "-163.704102,790.329102,151.175781,0.000172,-2.604426,-61.00597,35.0,150.488785,false,DoNotOverride,22.0",
          Content = "好了，达芙涅小姐，你们通过了典狱长的又一次考验，可以请你先离开了。",
          DialogueId = 11016830,
          GUID = "1B9458AC",
          LookAt = {
            [1] = "110040:n(110021)",
            [2] = "110041:n(110021)"
          },
          NextDialogue = 11016831,
          SpeakNpcId = 110021,
          Subtitle = "Alright. Both of you have again passed the Warden's test. Miss Daphne, you may leave now.",
          TalkActionId = {
            [1] = "110021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9458AC"
        },
        [11016831] = {
          Content = "你在偷听？",
          DialogueId = 11016831,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9458D6",
          NextDialogue = 11016832,
          SpeakNpcId = 110040,
          Subtitle = "Were you eavesdropping on us?",
          TalkActionId = {
            [1] = "110021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9458D6"
        },
        [11016832] = {
          Camera = "622.149414,9.680664,136.84375,0.000179,1.395483,-140.405182,35.000008,150.488785,false,Manual,22.0",
          Content = "是典狱长的命令。把你们单独关在一起，监听你们到底在谈些什么。",
          DialogueId = 11016832,
          GUID = "1B945900",
          LookAt = {
            [1] = "110041:p(fix27floor2)"
          },
          NextDialogue = 11016833,
          SpeakNpcId = 110021,
          Subtitle = "Per the Warden's orders. I was to confine you both here and monitor your interactions.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945900"
        },
        [11016833] = {
          Camera = "148.842773,223.691406,110.460938,0.000203,3.804395,-124.205971,35.000015,150.488785,false,Manual,22.0",
          Content = "“如果是犯人的话，现在很可能在串通口供”……我明白了，谢谢海尔法大人给我们这个自证的机会。",
          DialogueId = 11016833,
          FacialId = {
            [1] = "110041:None"
          },
          GUID = "1B94592A",
          LookAt = {
            [1] = "110040:n(110041)"
          },
          NextDialogue = 11016834,
          Scripts = [[
PARA{
LookAt{_delay{6},LookAtDescription{"110041:n(110040)"}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Right, if we were guilty, we'd make use of every opportunity to collude in our testimonies... I understand. Thank you for giving us a chance to prove our innocence.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B94592A"
        },
        [11016834] = {
          Content = "也许……我们很快就能走出这里了。",
          DialogueId = 11016834,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B945954",
          SpeakNpcId = 110041,
          Subtitle = "Perhaps... we'll leave this place soon.",
          VoiceName = "voice/$Locale$/story/1002/110168/1B945954"
        },
        [11016901] = {
          Camera = "-10.047852,143.882812,126.195312,0.000104,2.803007,-30.809227,35.000015,276.520508,false,Manual,22.0",
          Content = "你们走不出这里了。",
          DialogueId = 11016901,
          GUID = "1B946452",
          NextDialogue = 11016902,
          Scripts = [[
