          VoiceName = "voice/$Locale$/story/1002/110169/1B9464A6"
        },
        [11016904] = {
          Camera = "-189.967773,373.448242,157.484375,0.000144,1.603148,-97.005592,40.0,193.921936,false,Manual,22.0",
          Content = "典狱长大人，这不对——这不符合审判的流程！",
          DialogueId = 11016904,
          Duration = 2,
          FacialId = {
            [1] = "110041:Angry01"
          },
          GUID = "1B9464D0",
          NextDialogue = 11016905,
          Scripts = [[
SEQ{
SetLocation{ActorId{110041},TargetPoint{"fx28_dafuStand"},Visibility{"Show"}},
PlayAnimation{ActorId{110041},AnimationId{"Sit_Idle_End"},Duration{2}},
TurnTo{TurnToDescription{"110041:n(110032)"}},
PlayAnimation{ActorId{110041},AnimationId{"Angry01_Start"},Duration{2}},
CameraMoveTo{TargetPosition{"246.750977,635.553711,145.472656,0.000125,-0.197017,-132.803497,35.000008,662.207397,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Ma'am, this is not right — it goes against the standard procedures of interrogation.",
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464D0"
        },
        [11016905] = {
          Camera = "-650.21875,847.072266,405.632812,0.000051,-26.194887,-39.601955,26.0,530.095764,false,DoNotOverride,22.0",
          Content = "看看这份文件吧，最后这串签名。连最高法务大臣都签了，西比尔也拦不下。你们真是卷进了了不得的事。",
          DialogueId = 11016905,
          FacialId = {
            [1] = "110041:Unacceptable01"
          },
          FinalCamera = "-650.21875,847.072266,405.632812,0.000047,-22.794765,-43.20211,26.0,530.095764,false,DoNotOverride,22.0",
          GUID = "1B9464FA",
          NextDialogue = 11016906,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110032},AnimationId{"Explain01_End"},Duration{2}},
PlayAnimation{_delay{4},ActorId{110032},AnimationId{"DisagreeHead"},Duration{2}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "Take a look at the writ and the signatures at the bottom. Even the Supreme Minister of Justice has signed it. Not even Chief Sibylle can stop it. Your case has grown beyond anyone's control.",
          TalkActionId = {
            [1] = "110041:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464FA"
        },
        [11016906] = {
          Camera = "-89.286133,352.804688,215.699219,0.000116,-15.397158,119.181168,35.000011,262.747772,false,Manual,22.0",
          Content = "法露茜呢？只要能找到法露茜，找到那支录音设备，真相就……！",
          DialogueId = 11016906,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:Angry01"
          },
          GUID = "1B946524",
          NextDialogue = 11016907,
          Scripts = [[
SEQ{
SetLocation{ActorId{110040},TargetPoint{"fx28_nanzhuStand"},Visibility{"Show"}},
PlayAnimation{ActorId{110040},AnimationId{"Sit_Idle_End"},Duration{2}},
PlayAnimation{ActorId{110040},AnimationId{"Explain01_Start"},Duration{2}}
}]],
          SpeakNpcId = 110040,
          Subtitle = "What about Falsi? As long as we find Falsi and the recording device, we can prove that...",
          VoiceName = "voice/$Locale$/story/1002/110169/1B946524"
        },
        [11016907] = {
          Camera = "-119.676758,376.845703,212.484375,0.000182,-19.996178,5.170751,35.000015,530.095764,false,Manual,22.0",
          Content = "她失踪了。",
          DialogueId = 11016907,
          FacialId = {
            [1] = "110032:None"
          },
          GUID = "1B94654E",
          LookAt = {
            [1] = "110032:n(110040)"
          },
          NextDialogue = 11016908,
          SpeakNpcId = 110032,
          Subtitle = "She's missing.",
          TalkActionId = {
            [1] = "110040:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B94654E"
        },
        [11016908] = {
          Content = "在龙莎一役的一场爆炸中，她不慎跌落到要塞外。士兵们在河岸发现了她染血的配枪。虽然军团仍在搜寻她的下落，但依照目前推测，她很可能已经死亡。",
          DialogueId = 11016908,
          GUID = "1B946578",
          NextDialogue = 11016909,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110032},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{_delay{2},ActorId{110032},AnimationId{"Talk01_End"},Duration{2}},
CameraMoveTo{_delay{1},TargetPosition{"-537.025391,515.268555,271.632812,0.000282,-18.459036,-12.635934,15.000007,100000.0,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"-564.171875,461.899414,229.765625,0.000282,-18.459036,-12.635994,15.000007,100000.0,false,Manual,22.0"},duration{15}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "An explosion occurred during the battle. Falsi was last seen outside the fortress. Her bloodstained pistol was found along the riverbank. Although the Legion continues to search, it is likely that she is deceased.",
          VoiceName = "voice/$Locale$/story/1002/110169/1B946578"
        },
        [11016909] = {
          Camera = "-167.293945,332.791992,154.449219,0.000129,2.60293,-109.422783,35.000011,159.827057,false,Manual,22.0",
          Content = "……典狱长大人，您真的相信这种巧合吗？",
          DialogueId = 11016909,
          GUID = "1B9465A2",
          LookAt = {
            [1] = "110032:n(110041)"
          },
          NextDialogue = 11016910,
          SpeakNpcId = 110041,
          Subtitle = "...Ma'am, do you really believe in such a coincidence?",
          TalkActionId = {
            [1] = "110041:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9465A2"
        },
        [11016910] = {
          Camera = "-82.495117,382.399414,154.101562,0.000099,-3.197143,-0.828277,35.000008,169.37561,false,Manual,22.0",
          Content = "…………",
          DialogueId = 11016910,
          Duration = 2,
          GUID = "1B9465CC",
          NextDialogue = 11017001,
          SpeakNpcId = 110032,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110041:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9465CC"
        },
        [11017001] = {
          Content = "维吉尔亲王殿下！这是审讯犯人的肮脏地方，请您留步！",
          DialogueId = 11017001,
          GUID = "1B9474BA",
          Scripts = "LookAt{_delay{0.6},LookAtDescription{\"110032:p(28Point3)\"}}",
          SnapShot = "OUTDOOR",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Your Royal Highness Prince Vergilius! This place isn't fitting for someone of your stature. Please don't proceed any further!",
          VoiceName = "voice/$Locale$/story/1002/110170/1B9474BA"
        },
        [11017003] = {
          Content = "凑齐这么多签名，可真不容易。",
          DialogueId = 11017003,
          Duration = 3,
          GUID = "1B94750E",
          SpeakNpcId = 110018,
          Subtitle = "Gathering so many signatures must have been quite the feat.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94750E"
        },
        [11017004] = {
          Content = "可惜这么多签名，应该都没我这个管用吧？",
          DialogueId = 11017004,
          Duration = 4,
          GUID = "1B947538",
          SpeakNpcId = 110018,
          Subtitle = "Yet, these signatures might weigh less than the one in my hand, I suppose?",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947538"
        },
        [11017005] = {
          Content = "…………",
          DialogueId = 11017005,
          Duration = 3,
          GUID = "1B947562",
          SpeakNpcId = 110032,
          Subtitle = "Your Highness.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947562"
        },
        [11017006] = {
          Content = "维吉尔殿下，皇室也打算干预龙莎间谍案的审判吗？",
          DialogueId = 11017006,
          Duration = 4,
          GUID = "1B94758C",
          SpeakNpcId = 110032,
          Subtitle = "Does the royal family intend to intervene in this military case?",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94758C"
        },
        [11017007] = {
          Content = "典狱长女士，您将陛下亲自签发特赦令一事称作“干预”？皇家军事监狱已经不再隶属“皇家”了吗？",
          DialogueId = 11017007,
          Duration = 10,
          GUID = "1B9475B6",
          SpeakNpcId = 110018,
          Subtitle = [[
Intervene? I must ask, do you view His Majesty's decree of pardon as an "intervention"?
Is the Royal Military Prison no longer under the crown's jurisdiction?]],
          VoiceName = "voice/$Locale$/story/1002/110170/1B9475B6"
        },
        [11017008] = {
          Content = "…………",
          DialogueId = 11017008,
          Duration = 3,
          GUID = "1B9475E0",
          SpeakNpcId = 110018,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110170/1B9475E0"
        },
        [11017009] = {
          Content = "我要和{nickname2}谈谈，无关人等出去。",
          DialogueId = 11017009,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94760A",
          SpeakNpcId = 110018,
          Subtitle = "I need to speak with  alone. Everyone else may leave.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94760A"
        },
        [11017010] = {
          Content = "……总算走了。",
          DialogueId = 11017010,
          Duration = 3,
          GUID = "1B947634",
          SpeakNpcId = 110018,
          Subtitle = "...Phew, they're finally gone.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947634"
        },
        [11017101] = {
          Camera = "266.088867,42.083984,149.292969,0.000127,-0.000061,19.197737,45.000023,400.044037,false,DoNotOverride,22.0",
          Content = "还好、还好。要是再来晚一点，恐怕和你这次会面就是在墓园了。",
          DialogueId = 11017101,
          FinalCamera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0",
          GUID = "1B948522",
          LookAt = {
            [1] = "110018:n(110018)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017102,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019,
            [6] = 201020
          },
          Scripts = [[
SEQ{PlayAnimation{ActorId{110018},AnimationId{"DisagreeHead"},Duration{3}},
TurnTo{_delay{0.5},TurnToDescription{"110018:n(110022)"}},
LookAt{LookAtDescription{"110018:n(110022)"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Thank goodness. One moment later and I might have to talk to your headstone instead.",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948522"
        },
        [11017102] = {
          Camera = "38.443359,-115.731445,90.113281,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0",
          Content = "我说朋友，你这次是真的闯了大祸了。你知道见皇兄一面有多难，而我又极少染指政客们的事。不过你还算走运，今早皇兄为别的事情召见我，我才求来这一纸特赦令。",
          DialogueId = 11017102,
          FinalCamera = "33.347656,-115.939453,81.179688,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0",
          GUID = "1B94854C",
          LookAt = {
            [1] = "110018:n(110022)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017103,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{110018},AnimationId{"Talk02_End"},Duration{5}},
SEQ{
CameraMoveTo{_delay{7.5},TargetPosition{"509.366211,-103.800781,280.621094,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"499.982422,-111.956055,283.566406,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928"},duration{15}}
}
}]],
          SpeakNpcId = 110018,
          Subtitle = "By all that is holy, my friend, you've really landed yourself in some serious trouble. You know how hard it is to meet my brother, and how rarely I get involved with politicians. But fortune favours you today — I was summoned for a different matter and seized the opportunity to secure your pardon.",
          TalkActionId = {
            [1] = "110018:Talk02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94854C"
        },
        [11017103] = {
          Content = "不过总算，又可以呼吸自由的空气了——想去哪儿？美术馆、歌剧院？凯旋大街的酒馆？还是随便在絮语河岸吹吹风？",
          DialogueId = 11017103,
          Duration = 2,
          GUID = "1B948576",
          NextDialogue = 11017104,
          RelatedWikiId = {
            [1] = 408008,
            [2] = 408009
          },
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{110018},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Talk01_End"},Duration{0}},
PlayAnimation{ActorId{110018},AnimationId{"Talk02_Start"},Duration{5}},
PlayAnimation{ActorId{110018},AnimationId{"Talk02_End"},Duration{5}}
},
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"329.342773,-782.536133,108.894531,0.000158,2.99986,91.395897,28.0,400.044037,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"329.342773,-782.536133,84.554688,0.000158,2.99986,91.395897,28.0,400.044037,false,DoNotOverride,22.0"},duration{40}}
}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Things have finally blown over. You're free at last. Where do you want to go, the art gallery, the opera house, or just a simple stroll along Whisper River for fresh air?",
          VoiceName = "voice/$Locale$/story/1002/110171/1B948576"
        },
        [11017104] = {
          Camera = "541.608398,60.505859,169.71875,0.000138,-8.399841,172.791351,35.0,282.239868,false,Manual,5.900274",
          Content = "……谢谢……不过，先不用了。",
          DialogueId = 11017104,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9485A0",
          NextDialogue = 11017105,
          SpeakNpcId = 110022,
          Subtitle = "...Thanks, but no thanks.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485A0"
        },
        [11017105] = {
          Camera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0",
          Content = "……你……脸色好差。看来他们没少折磨你。等下随我去我的居所吧，我安排我的医生为你诊治。",
          DialogueId = 11017105,
          Duration = 1,
          GUID = "1B9485CA",
          NextDialogue = 11017106,
          Scripts = [[
SEQ{PlayAnimation{_delay{1.5},ActorId{110018},AnimationId{"Explain02_Start"},Duration{2}},
PlayAnimation{_delay{1},ActorId{110018},AnimationId{"Explain02_End"},Duration{2}},
PlayAnimation{_delay{2},ActorId{110018},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "...You... look pale. They did go rough on you. Why don't you come to my place? My personal physicians will tend to your wounds.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485CA"
        },
        [11017106] = {
          Content = "千年后的今天，海伯利亚的监狱居然还在用原始野蛮、毫无人道主义可言的刑罚……那些谄媚的作家笔下“最伟大、最繁荣的时代”，简直就是最拙劣的喜剧。",
          DialogueId = 11017106,
          GUID = "1B9485F4",
          NextDialogue = 11017107,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"640.131836,164.128906,414.648438,0.0001,-25.800047,-120.799606,20.0,400.044037,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"691.962891,133.231445,414.648438,0.0001,-25.800047,-120.799606,20.0,400.044037,false,DoNotOverride,22.0"},duration{20}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "A millennium has passed, and still, the prisons of Hyperborea cling to such crude, barbaric, and wholly inhumane forms of torture... Those sycophantic chroniclers call this \"the greatest and most prosperous of times” — what a most exquisite farce.",
          TalkActionId = {
            [1] = "110018:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485F4"
        },
        [11017107] = {
          Camera = "358.598633,12.164062,188.667969,0.000165,-23.000387,156.785355,28.000008,310.596832,false,DoNotOverride,7.801928",
          Content = "先别说这个了……达芙涅呢？",
          DialogueId = 11017107,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "360.378906,16.311523,188.667969,0.000165,-23.000387,156.785355,28.000008,310.596832,false,DoNotOverride,7.801928",
          GUID = "1B94861E",
          NextDialogue = 11017108,
          SpeakNpcId = 110022,
          Subtitle = "Let's not dwell on that... How's Daphne?",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94861E"
        },
        [11017108] = {
          Camera = "169.751953,12.941406,146.257812,0.000181,-0.200685,23.989719,45.0,254.013382,false,Manual,7.801928",
          Content = "放心。我听闻你一直在护着她，这份特赦令自然也会庇护她。",
          DialogueId = 11017108,
          FinalCamera = "159.480469,8.374023,146.257812,0.000181,-0.200685,23.989157,45.0,254.013382,false,Manual,7.801928",
          GUID = "1B948648",
          NextDialogue = 11017112,
          SpeakNpcId = 110018,
          Subtitle = "I heard about your efforts to ensure her safety. Fear not, the pardon includes her as well.",
          TalkActionId = {
            [1] = "110018:AgreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948648"
        },
        [11017109] = {
          Camera = "626.061523,-377.210938,104.453125,0.000161,-1.200583,124.384415,28.000006,310.596832,false,DoNotOverride,7.801928",
          Content = "那就好……抱歉，现在的我，暂时还没法报答你。",
          DialogueId = 11017109,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "640.552734,-398.384766,104.984375,0.000161,-1.200583,124.384415,28.000006,310.596832,false,DoNotOverride,7.801928",
          GUID = "1B948672",
          NextDialogue = 11017110,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110022},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{1},ActorId{110022},AnimationId{"Explain02_Start"},Duration{5}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Thank you, and... sorry, I don't have anything to repay your kindness at the moment.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948672"
        },
        [11017110] = {
          Camera = "-224.194336,-243.641602,117.367188,0.000243,-0.000792,28.586721,45.000011,741.075867,false,Manual,7.801928",
          Content = "报答——嗯……那来给我当半年保镖如何？",
          DialogueId = 11017110,
          FacialId = {
            [1] = "110018:Smile01"
          },
          FinalCamera = "-230.798828,-231.524414,117.367188,0.000243,-0.000792,28.586721,45.000023,717.293152,false,Manual,6.911264",
          GUID = "1B94869C",
          NextDialogue = 11017111,
          Scripts = [[

PlayAnimation{_delay{2},ActorId{110018},AnimationId{"Talk03_Start"},Duration{2}}]],
          SpeakNpcId = 110018,
          Subtitle = "Repay me? Hmm... How about serving as my bodyguard for six months?",
          TalkActionId = {
            [1] = "110022:Explain02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94869C"
        },
        [11017111] = {
          Camera = "499.02832,79.253906,163.570312,0.000184,-5.80075,178.390396,45.0,254.013382,false,Manual,7.801928",
          Content = "保镖？",
          DialogueId = 11017111,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "498.866211,73.417969,163.570312,0.000184,-5.80075,178.390396,45.0,254.013382,false,Manual,7.801928",
          GUID = "1B9486C6",
          NextDialogue = 11019105,
          SpeakNpcId = 110022,
          Subtitle = "Bodyguard?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9486C6"
        },
        [11017112] = {
          Camera = "34.15918,-378.791016,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          Content = "还有一件事……",
          DialogueId = 11017112,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "56.49707,-391.176758,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          GUID = "1B94871B",
          NextDialogue = 11017114,
          SpeakNpcId = 110022,
          Subtitle = "One more thing...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871B"
        },
        [11017113] = {
          Camera = "3.826172,76.46582,165.292969,0.000128,-0.600066,-114.184586,31.194523,100000.0,false,DoNotOverride,22.0",
          Content = "你短期可能回不了军团了。你的嫌疑并未真的洗清，现在回军团只怕身份会尴尬。",
          DialogueId = 11017113,
          Duration = 3,
          GUID = "1B94871A",
          NextDialogue = 11019115,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Think_End"},Duration{3}},
PlayFacial{ActorId{110022},FacialId{"Think01"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "And staying away from the Legion might be wise for now. The stigma of a criminal charge lingers. Going back to the Legion at this point could be awkward.",
          TalkActionId = {
            [1] = "110018:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871A"
        },
        [11017114] = {
          Content = "富尔维斯的副官法露茜。我认为她的失踪没那么简单——她是这个案子真相的关键。如果可以，我想拜托你帮忙调查她的下落，无论生死。",
          DialogueId = 11017114,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94871C",
          NextDialogue = 11017115,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"346.420898,18.442383,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"348.020508,22.321289,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{8}}
},
SEQ{
PlayAnimation{ActorId{110022},AnimationId{"Talk02_End"},Duration{2}},
PlayAnimation{ActorId{110022},AnimationId{"Think_Start"},Duration{5}},
PlayAnimation{ActorId{110022},AnimationId{"Think_End"},Duration{2}}
}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Fulvis's adjutant, Falsi — I don't think her disappearance was what it seemed. She holds the key to the truth behind all this. If it's not too much to ask... could I trouble you to look into her whereabouts? Dead or alive — I need to know.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871C"
        },
        [11017115] = {
          Camera = "315.612305,27.775391,111.347656,0.000177,18.198792,35.193779,45.000011,254.013382,false,DoNotOverride,7.801928",
          Content = "富尔维斯失踪的副官……？好，我记下了。",
          DialogueId = 11017115,
          GUID = "1B94871D",
          NextDialogue = 11017109,
          SpeakNpcId = 110018,
          Subtitle = "Fulvis's missing adjutant... I see. I'll look into it.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871D"
        },
        [11017116] = {
          Camera = "211.03125,373.930664,131.835938,0.000081,2.000002,-130.801483,31.194527,100000.0,false,Manual,22.0",
          Content = "嗯。想想那份文件上的一串签名吧——迪斯玛尼亚不知道有多少人在看不见的暗角窥视着你。你的武器可以杀死秽兽，却挡不住来自背后的子弹。",
          DialogueId = 11017116,
          Duration = 3,
          FinalCamera = "215.617188,369.973633,131.835938,0.000081,1.999995,-130.801483,31.194527,100000.0,false,Manual,22.0",
          GUID = "1B948798",
          NextDialogue = 11017117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"118.792969,12.256836,231.714844,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"130.400391,15.670898,236.511719,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Yes. Just think of those signatures — how many people are watching you in Dismania. Your prowess may deter approaching Filthoids, but not hidden assassins.",
          TalkActionId = {
            [1] = "110022:Talk01_End",
            [2] = "110018:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948798"
        },
        [11017117] = {
          Camera = "-38.605469,-123.583984,167.742188,0.000094,-5.999843,78.991455,31.194527,446.287842,false,Manual,11.834087",
          Content = "我知道你在担心什么。西比尔·梅森和达芙涅有些故交，且在这起事件中，她明显更相信你们无辜，所以她至少会保证达芙涅的安全。",
          DialogueId = 11017117,
          Duration = 3,
          FinalCamera = "-45.6875,-122.178711,167.742188,0.000092,-6.199858,78.391617,31.194527,446.287842,false,Manual,11.834087",
          GUID = "1B9487C2",
          NextDialogue = 11019119,
          SpeakNpcId = 110018,
          Subtitle = "I know what you're worried about. Sibylle Mason is an old friend of Daphne. She is obviously inclined to your innocence, so she will at least ensure Daphne's safety.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9487C2"
        },
        [11017119] = {
          Camera = "653.830078,-1243.886719,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
          Content = "……哈，你知道我最厌恶那些老家伙的繁文缛节。不过，你总算有心情开玩笑了，这很好。",
          DialogueId = 11017119,
          Duration = 3,
          FacialId = {
            [1] = "110018:Smile01"
          },
          FinalCamera = "619.453125,-1255.985352,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
          GUID = "1B948816",
          NextDialogue = 11019121,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Explain02_End\"},Duration{3}}",
          SpeakNpcId = 110018,
          Subtitle = "...Come on, you know there's nothing I hate more than these pointless customs and etiquette. But you're in the mood for jokes now, which is a good sign.",
          TalkActionId = {
            [1] = "110018:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948816"
        },
        [11017201] = {
          Content = "{nickname2}，你就什么都不问？",
          DialogueId = 11017201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C0",
          NextDialogue = 11017202,
          SpeakNpcId = 110010,
          Subtitle = ", so you're not going to ask me anything?",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C0"
        },
        [11017202] = {
          Content = "您刚说过，军人要无条件服从命令。",
          DialogueId = 11017202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C1",
          NextDialogue = 11017203,
          SpeakNpcId = 110022,
          Subtitle = "You just said soldiers must obey.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C1"
        },
        [11017203] = {
          Content = "都这个份上了，你怎么还是老样子，像块木雕似的。",
          DialogueId = 11017203,
          Duration = 3,
          GUID = "1B9488C2",
          NextDialogue = 11017204,
          SpeakNpcId = 110010,
          Subtitle = "Given what we've been through, are you really going to be as rigid as a piece of wood?",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C2"
        },
        [11017204] = {
          Content = "老师，您还说过，作战时必须集中注意力。",
          DialogueId = 11017204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C3",
          NextDialogue = 11017205,
          SpeakNpcId = 110022,
          Subtitle = "You also said that one must fully concentrate when engaging in combat.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C3"
        },
        [11017205] = {
          Content = "现在情况并不安全，分心批评我，会增加您的伤亡概率。",
          DialogueId = 11017205,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C4",
          NextDialogue = 11017206,
          SpeakNpcId = 110022,
          Subtitle = "The current circumstances are perilous; being sidetracked by criticism might lead to casualties.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C4"
        },
        [11017206] = {
          Content = "你这小鬼！",
          DialogueId = 11017206,
          Duration = 3,
          GUID = "1B9488C5",
          SpeakNpcId = 110010,
          Subtitle = "You sharp-tongued brat!",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C5"
        },
        [11017301] = {
          Content = "“狮鹫”该不会就剩你一个了？其他人什么情况？",
          DialogueId = 11017301,
          Duration = 3,
          GUID = "1B909E29",
          NextDialogue = 11017302,
          SpeakNpcId = 110010,
          Subtitle = "Don't tell me you're the only Griffin left alive. Where are the rest of your squad?",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E29"
        },
        [11017302] = {
          Content = "他们在前面，大多伤得不轻。跟我来。",
          DialogueId = 11017302,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B909E30",
          NextDialogue = 11011013,
          SpeakNpcId = 110022,
          Subtitle = "They're right ahead. Most of them are heavily injured. Please follow me.",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E30"
        },
        [11017401] = {
          DialogueId = 11017401,
          Duration = 2,
          GUID = "1B94B65A",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B65A"
        },
        [11017402] = {
          Content = "达芙涅对伤员们进行了治疗",
          DialogueId = 11017402,
          Duration = 2,
          GUID = "1B94B684",
          Subtitle = "Daphne treated the wounded.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B684"
        },
        [11017403] = {
          Content = "带着卡嘉一行人离开了此处……",
          DialogueId = 11017403,
          Duration = 2,
          GUID = "1B94B6AE",
          Subtitle = "You take Katya and the guys and leave this place...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6AE"
        },
        [11017404] = {
          Content = "这是……继电器，总之先关闭一个",
          DialogueId = 11017404,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B6D8",
          SpeakNpcId = 110022,
          Subtitle = "This is... a relay. Anyway, just turn off one first.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6D8"
        },
        [11017405] = {
          DialogueId = 11017405,
          Duration = 2,
          GUID = "1B94B702",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B702"
        },
        [11017406] = {
          Content = "不要动！",
          DialogueId = 11017406,
          Duration = 2,
          GUID = "1B909E34",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "Freeze!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E34"
        },
        [11017407] = {
          Content = "水位降不下去！",
          DialogueId = 11017407,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B756",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 11017408,
          SpeakNpcId = 110022,
          Subtitle = "The water won't go down!",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B756"
        },
        [11017408] = {
          Content = "从边上绕过去吧。",
          DialogueId = 11017408,
          Duration = 2,
          GUID = "1B94B780",
          SpeakNpcId = 110005,
          Subtitle = "Let's get through from the side.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B780"
        },
        [11017409] = {
          DialogueId = 11017409,
          Duration = 2,
          GUID = "1B94B7AA",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7AA"
        },
        [11017410] = {
          Camera = "402.354004,84.89209,149.571686,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
          Content = "权限确认，请通行。",
          DialogueId = 11017410,
          Duration = 3,
          FinalCamera = "353.715454,60.211914,153.577911,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
          GUID = "1B94B7D4",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Access granted. Please proceed.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7D4"
        },
        [11017411] = {
          Content = "好，月髓连接上了【废弃】",
          DialogueId = 11017411,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B94B7FE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7FE"
        },
        [11017412] = {
          Content = "咦，被挡住了，看起来要绕一下路呢……",
          DialogueId = 11017412,
          Duration = 5,
          GUID = "1B94B828",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Eh? It's blocked. Seems like we need to take a detour...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B828"
        },
        [11017413] = {
          Content = "开关还打不开，先启动相连的髓动轮吧。",
          DialogueId = 11017413,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B852",
          SpeakNpcId = 110022,
          Subtitle = "The switch doesn't work, maybe I should activate the connected Phoxynamo Wheel first.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B852"
        },
        [11017414] = {
          Content = "（……要抓紧时间打开开关。）",
          DialogueId = 11017414,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B87C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...Gotta turn it on quickly.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B87C"
        },
        [11017415] = {
          Content = "炮台的能源已经全部连通，回来汇合吧。【废弃】",
          DialogueId = 11017415,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 5,
          GUID = "1B94B8A6",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8A6"
        },
        [11017416] = {
          Content = "准备好了，就激活髓动轮出发吧。",
          DialogueId = 11017416,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94B8D0",
          SpeakNpcId = 110010,
          Subtitle = "Go activate the Phoxynamo Wheels once you're ready.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8D0"
        },
        [11017417] = {
          Content = "（顺着这些线缆找到髓动轮吧。）",
          DialogueId = 11017417,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B8FA",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(These cables should lead me to the Phoxynamo Wheels.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8FA"
        },
        [11017418] = {
          Content = "好厉害……",
          DialogueId = 11017418,
          GUID = "1B94B924",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "That's amazing...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B924"
        },
        [11017419] = {
          Content = "（找到了……启动它吧。）",
          DialogueId = 11017419,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B94E",
          SpeakNpcId = 110022,
          Subtitle = "(Found it. Gotta activate it now.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B94E"
        },
        [11017420] = {
          Content = "他们管这里叫“模拟战场”，说什么……“这次的主题是冰湖城防卫战”。",
          DialogueId = 11017420,
          GUID = "1B94B978",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017421,
          SpeakNpcId = 110034,
          Subtitle = "They refer to this place as a \"Simulated Battlefield,\" saying that... \"The theme this time is the Defence of Icelake City.\"",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B978"
        },
        [11017421] = {
          Content = "听说那个冰湖城，到处都是冰天雪地的。我还没见过雪呢……真想去看看！",
          DialogueId = 11017421,
          GUID = "1B94B9A2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017422,
          SpeakNpcId = 110034,
          Subtitle = "I heard that this Icelake City is covered in snow, something that I've never seen in my entire life... How I wish I could go there and see it myself!",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9A2"
        },
        [11017422] = {
          Content = "……我是说，如果，我能活着回家。",
          DialogueId = 11017422,
          GUID = "1B94B9CC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "...I mean, if, by any chance, I could make it out alive.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9CC"
        },
        [11017423] = {
          Content = "好了。",
          DialogueId = 11017423,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B9F6",
          SpeakNpcId = 110022,
          Subtitle = "(Done.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9F6"
        },
        [11017501] = {
          Content = "动力室是整座要塞的“心脏”，维持要塞运转的能源都来自里面那台月髓舱。",
          DialogueId = 11017501,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C6C2",
          NextDialogue = 11017502,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "The engine room is the \"heart\" of the entire fortress, and all the power that keeps the fortress running comes from the Phoxichor tank in there.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C6C2"
        },
        [11017502] = {
          Content = "但直接攻击月髓舱会引起爆炸，你得先去关掉四周的<H>髓动轮</>。",
          DialogueId = 11017502,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C6EC",
          SpeakNpcId = 110010,
          Subtitle = "But a direct attack would only lead to explosion, so you need to shut down the Phoxynamo Wheels around it first.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C6EC"
        },
        [11017503] = {
          Camera = "804.818848,157.511719,744.295471,0.000002,-8.800173,-4.800692,23.868748,100000.0,false,Manual,22.0",
          Content = "那些髓动轮，蓝色的，你应该能认得出来吧？你现在要做的是把它们变成黄色。",
          DialogueId = 11017503,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C716",
          NextDialogue = 11017504,
          SpeakNpcId = 110010,
          Subtitle = "You should be able to recognise those wheels, aka the blue ones, right? What you need to do is turn them yellow.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C716"
        },
        [11017504] = {
          Content = "老师，我早毕业了，不用这样一步一步指导的。",
          DialogueId = 11017504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C740",
          NextDialogue = 11017505,
          SpeakNpcId = 110022,
          Subtitle = "I graduated a long time ago, Sir. You don't have to lead me through all the basic steps.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C740"
        },
        [11017505] = {
          Content = "那你见机行事吧，必要时我再联络你。",
          DialogueId = 11017505,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C76A",
          SpeakNpcId = 110010,
          Subtitle = "...Alright kid, play it by ear then. I'll contact you if necessary.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C76A"
        },
        [11017506] = {
          Content = "（顺着地上这些线缆，应该能顺利找到那些髓动轮。但愿它们不要藏得太刁钻。）",
          DialogueId = 11017506,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C794",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Following the cables on the ground may help me get to the Phoxynamo Wheels. I hope they're not too tricky to be found.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C794"
        },
        [11017507] = {
          Content = "（先处理这台吧。）",
          DialogueId = 11017507,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C7BE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(I'll shut down this one first.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C7BE"
        },
        [11017508] = {
          Content = "（好，关停了。）",
          DialogueId = 11017508,
          DisableMouth = 1,
