          DialogueId = 11019031,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C1C6",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(No — this isn't me.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C1C6"
        },
        [11019032] = {
          Content = "（是的，我必须走出这里，把真相……）",
          DialogueId = 11019032,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C1F0",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Yes... I have to keep going. The truth must come to light...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C1F0"
        },
        [11019033] = {
          Content = "（你不是我。你只是一个愚蠢的赝品。）",
          DialogueId = 11019033,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C21A",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(You're not me. You're just a cheap imitation.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C21A"
        },
        [11019034] = {
          Content = "消失吧。",
          DialogueId = 11019034,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C244",
          SpeakNpcId = 110022,
          Subtitle = "Get lost.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C244"
        },
        [11019035] = {
          Content = "（前面好像走不通了……要回头吗？）",
          DialogueId = 11019035,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C26E",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(The path ahead's blocked... Should I turn back?)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C26E"
        },
        [11019036] = {
          Content = "坚称无罪之人，你会因愤怒动摇吗？",
          DialogueId = 11019036,
          GUID = "1B95C298",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "You who claim innocence — will your resolve falter in anger?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C298"
        },
        [11019037] = {
          Content = "善后得怎么样了？",
          DialogueId = 11019037,
          GUID = "1B95C2C2",
          NextDialogue = 11019038,
          SpeakNpcId = 110011,
          Subtitle = "How's the cleanup?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C2C2"
        },
        [11019038] = {
          Content = "干干净净，如您所见。",
          DialogueId = 11019038,
          GUID = "1B95C2EC",
          SpeakNpcId = 110012,
          Subtitle = "Flawless. As you can see.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C2EC"
        },
        [11019039] = {
          Content = "（是他们两个……！）",
          DialogueId = 11019039,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C316",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(It's them... Fulvis and Falsi!)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C316"
        },
        [11019040] = {
          Content = "坚称无罪之人，你会因悲哀动摇吗？",
          DialogueId = 11019040,
          GUID = "1B95C340",
          SpeakNpcId = 110032,
          Subtitle = "You who claim innocence — will your resolve waver in sorrow?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C340"
        },
        [11019041] = {
          Content = "{nickname2}，我的学生……",
          DialogueId = 11019041,
          GUID = "1B95C36A",
          NextDialogue = 11019042,
          SpeakNpcId = 110010,
