        },
        [11019416] = {
          ContentES = "(No queda rastro de vida entre los soldados.)",
          DialogueId = 11019416,
          GUID = "1B9600C7",
          Subtitle = "(No trace of life remains among the soldiers.)"
        },
        [11019417] = {
          ContentES = "(Los cadáveres de Filthoids cercanos cuentan la historia: fueron estas bestias las que los acabaron. Y aun en la muerte, los soldados no se rindieron en silencio: sus últimos disparos dejaron heridas mortales en los Filthoids que los mataron.)",
          DialogueId = 11019417,
          GUID = "1B9600C8",
          Subtitle = "(The Filthoid corpses nearby tell the tale: it was these beasts that ended them. And yet, even in death, the soldiers did not go quietly — their final rounds left lethal wounds in the Filthoids that claimed them.)"
        },
        [11019418] = {
          DialogueId = 11019418,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_JailInves02;content:READ_TEXT_JailInves02}",
          GUID = "1B9600C9"
        },
        [11019419] = {
          DialogueId = 11019419,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_JailInves01;content:READ_TEXT_JailInves01}",
          GUID = "1B9600CA"
        },
        [11019420] = {
          Content = "你向典狱长承认了罪行，等待你的将是更为严酷的裁决。",
          DialogueId = 11019420,
          Duration = 4,
          GUID = "1B9600CB",
          NextDialogue = 11019421,
          Subtitle = "You have made the confession of guilt, and a far sterner retribution now lies in wait."
        },
        [11019421] = {
          Content = "你听见她的嗤笑——她曾认为你坚强无匹，但如今看来，你和她审判过的其他囚犯也并无分别。",
          DialogueId = 11019421,
          Duration = 4,
          GUID = "1B9600CC",
          NextDialogue = 11019422,
          Subtitle = "You hear her scornful laugh — she once believed you were unbreakable, but now sees you as no different from the other prisoners she has judged."
        },
        [11019422] = {
          Content = "你意识到自己正在坠入漆黑的深渊——你开始思索，如果当时你的意志能够更坚定一些，结局会不会有所不同？",
          DialogueId = 11019422,
          Duration = 4,
          GUID = "1B9600CD",
          Subtitle = "You find yourself plunging into an abyss of darkness — and you begin to wonder, if only your resolve had been firmer, would things have ended differently?"
        },
