          GUID = "1E0B01FC",
          NextDialogue = 12000903,
          SpeakNpcId = 200002,
          Subtitle = "Here you go! These are our tickets.",
          TalkActionId = {
            [1] = "200002:Give",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 3,
