          ContentES = "¿Y desde cuándo los malditos Charons se creen bienvenidos aquí? ¡Fuera! Antes de que ensucien nuestras alfombras.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000903,
          FinalCamera = "805.789062,-1312.524902,156.980469,0.000031,8.400169,167.798874,30.000002,500.702026,false,Manual,10.0",
          GUID = "1E0B0226",
          NextOptions = {
            [1] = 12000904,
            [2] = 12000905
          },
          Scripts = "PlayAnimation{_delay{1},ActorId{200002},AnimationId{\"Shock_Start\"},Duration{1}}",
          SpeakNpcId = 220010,
          Subtitle = "And where does a filthy Charon like you think you're going? Get out of here before you stain our carpets.",
          TalkActionId = {
            [1] = "220010:Angry01_Start",
            [2] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B0226"
        },
        [12000904] = {
          ContentES = "Su reglamento dice claramente: la entrada se realiza con la presentación de boletos. No he leído nada sobre la exclusión de ciertos grupos.",
          DialogueId = 12000904,
          GUID = "1E0B0250",
          ImprPlusId = 1008,
          NextDialogue = 12000906,
          Subtitle = "Your own rules state admission is ticket-based. I don't see anything about excluding specific groups. "
        },
        [12000905] = {
          ContentES = "¿Qué es esta actitud? Voy a informar a su superior.",
          DialogueId = 12000905,
          GUID = "1E0B027A",
          ImprPlusId = 1010,
          NextDialogue = 12000906,
          Subtitle = "What kind of attitude is that? I'm reporting you to your manager!"
        },
        [12000906] = {
