          },
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B02CE"
        },
        [12001101] = {
          ContentES = "El controlador ajusta lentamente su monóculo, inspeccionando los dos entradas desde todos los ángulos.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001101,
          Duration = 3,
          GUID = "1E0B22A2",
          Subtitle = "The ticket collector donned his monocle with deliberate slowness, scrutinising the two flimsy tickets in his hand from every angle.",
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B22A2"
        },
        [12001102] = {
          Camera = "472.220703,-1396.854004,227.90625,0.00006,5.200376,142.810028,35.000015,240.0,false,Manual,10.0",
          ContentES = "¡Ajá, lo sabía!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001102,
          FacialId = {
