CameraMoveTo{TargetPosition{"337.462891,-1316.896973,210.441406,-5.000038,12.401437,-50.368782,45.000011,391.082153,false,DoNotOverride,7.0"},duration{8}}
},
PlayAnimation{_delay{8.01},ActorId{210004},AnimationId{"Zhiliu_Story_Special02_Start"},Duration{4}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Alright, calm yourselves. You've done your part. Now, here's what you should do: lead the way and show us inside.",
          TalkActionId = {
            [1] = "210004:Confident_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4444"
        },
        [12001307] = {
          Camera = "408.238281,-1356.822754,294.8125,0.000137,-17.000668,150.418488,35.000008,240.0,false,DoNotOverride,10.0",
          ContentES = "...Sí, dama.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001307,
          GUID = "1E0B446E",
          NextDialogue = 12001308,
          SpeakNpcId = 220010,
          Subtitle = "...Yes, ma'am.",
          TalkActionId = {
            [1] = "210004:Zhiliu_Story_Special02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B446E"
        },
        [12001308] = {
          Camera = "299.849609,-1221.519043,191.652344,0.000176,8.199498,-63.981323,35.0,240.0,false,Manual,10.0",
          ContentES = "Un último consejo. En mi país, hay un viejo dicho: “En boca cerrada no entran moscas.”",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001308,
          GUID = "1E0B4498",
          NextDialogue = 12001309,
          Scripts = "TurnTo{TurnToDescription{\"210004:p(160)\"}}",
          SpeakNpcId = 210004,
          Subtitle = "One last piece of advice for you. In my homeland, there's an old saying: \"Thoughtless lips invite trouble.\"",
          TurnTo = {
            [1] = "210004:p(160)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4498"
        },
        [12001309] = {
          Camera = "416.728516,-1396.350098,247.863281,28.798187,5.598638,-58.176476,35.000008,240.0,false,DoNotOverride,10.0",
          ContentES = "Entonces cuida bien tu lengua... si no, nadie puede predecir qué infortunio te aguardará.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001309,
          GUID = "1E0B44C2",
          Scripts = [[
PARA{
