}]],
          SpeakNpcId = 210004,
          Subtitle = "Watch your words. You never know what misfortune they might bring upon you.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B44C2"
        },
        [12001310] = {
          Camera = "31.415039,981.577148,873.933594,0.000125,-35.994133,-75.767517,25.0,30.607483,false,DoNotOverride,4.569996",
          ContentES = "Dama, gracias por habernos ayudado hace un momento.",
          DialogueId = 12001310,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-24.272461,967.451172,851.3125,0.000125,-35.994137,-75.768639,25.0,30.607483,false,DoNotOverride,4.569996",
          GUID = "1E0B44EC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12001311,
          SpeakNpcId = 100001,
          Subtitle = "Thank you for stepping in to help us earlier, ma'am.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B44EC"
        },
        [12001311] = {
          Camera = "-76.600586,-142.378418,145.878906,0.000066,2.400094,55.591667,35.000011,210.0,false,Manual,10.0",
          ContentES = "Jeje… No hace falta ser tan formal. Simplemente llámame Zhiliu.",
          DialogueId = 12001311,
          FacialId = {
            [1] = "210004:Smile01"
          },
          FinalCamera = "-73.668945,-138.096191,146.089844,0.000078,2.400094,55.59174,35.000008,210.0,false,Manual,10.0",
          GUID = "1E0B4516",
          NextDialogue = 12001312,
          Scripts = "PlayAnimation{_delay{3.3},ActorId{210004},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "Hehe... No need to be so formal. Just call me by my name.",
          TalkActionId = {
            [1] = "210004:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4516"
        },
        [12001312] = {
          Camera = "30.446289,185.356934,190.074219,0.000055,-11.799342,-98.808578,35.000008,267.576447,false,DoNotOverride,4.724111",
          ContentES = "Entonces… ¿Dama Zhiliu…?",
          DialogueId = 12001312,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E0B4540",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001313,
          SpeakNpcId = 100001,
          Subtitle = "...Lady Zhiliu, then?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4540"
        },
        [12001313] = {
          Camera = "-64.051758,0.427246,155.0625,0.000095,4.200347,23.600756,35.000008,201.567627,false,DoNotOverride,10.0",
          ContentES = "Eso no suena mucho mejor. “Dama”, otra vez un tratamiento del Imperio, ¿no es así? Nunca me ha gustado.",
          DialogueId = 12001313,
          GUID = "1E0B456A",
          NextDialogue = 12001314,
          Scripts = "PlayAnimation{_delay{3},ActorId{210004},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "...That's not much of an improvement. \"Lady\" is more of an Empire term, isn't it? I've never really grown used to it.",
          TalkActionId = {
            [1] = "210004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B456A"
        },
        [12001314] = {
          ContentES = "He estado viajando como comerciante durante años, y tengo algunos negocios. Si insistes en ponerme un título, “propietaria” sería más apropiado.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001314,
          GUID = "1E0B4594",
          NextDialogue = 12001315,
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"24.381836,149.445801,168.28125,0.000089,-6.799255,-100.405937,35.000008,201.567627,false,Manual,10.0"},duration{0}},
LookAt{_delay{6.1},LookAtDescription{"200002:n(210004)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "I've spent years travelling these lands as a merchant, overseeing a few shops of my own. If you feel you must use a title, perhaps \"proprietress\" would be more fitting.",
          TalkActionId = {
            [1] = "210004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4594"
        },
        [12001315] = {
          Camera = "-228.251953,-342.149658,218.3125,0.000205,-10.998899,54.599339,35.0,210.445709,false,DoNotOverride,10.0",
          ContentES = "Entonces... ¿Propietaria Zhiliu, esperaba a alguien? No vamos a molestarlo, ¿verdad?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001315,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B45BE",
          NextDialogue = 12001316,
          Scripts = [[
PARA{
LookAt{_delay{5.1},LookAtDescription{"100001:n(200002)"}},
LookAt{_delay{6.1},LookAtDescription{"200002:n(210004)"}},
PlayAnimation{_delay{5},ActorId{100001},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Alright then... Proprietress Zhiliu, were you expecting someone? I hope we're not intruding.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B45BE"
        },
        [12001316] = {
          Camera = "22.512695,93.567383,162.910156,0.000092,-4.399099,-96.009109,35.000008,201.567627,false,Manual,10.0",
          ContentES = "Ah, ¿eso es lo que te preocupaba? Qué adorable considerado de tu parte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001316,
          GUID = "1E0B45E8",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(210004)"
          },
          NextDialogue = 12001317,
          SpeakNpcId = 210004,
          Subtitle = "That's what you've been worrying about? How adorably considerate of you.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B45E8"
        },
        [12001317] = {
          Camera = "-95.72168,25.02832,164.125,0.000175,-0.798128,7.808278,43.803249,210.445709,false,DoNotOverride,10.0",
          ContentES = "Está bien. No creo que esa persona venga.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001317,
          FinalCamera = "-108.598633,23.216797,163.859375,0.000175,1.201922,8.00806,43.803249,210.445709,false,DoNotOverride,10.0",
          GUID = "1E0B4612",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001318,
          Scripts = [[
PARA{
TurnTo{_delay{3},TurnToDescription{"210004:p(130)"}},
LookAt{_delay{3},LookAtDescription{"210004:n(210004)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "It's okay. I don't think that person will be coming.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200002:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4612"
        },
        [12001318] = {
          Camera = "-724.288086,-392.508057,357.445312,0.000203,-15.398278,26.595276,30.000002,210.445709,false,DoNotOverride,10.0",
          ContentES = "Un espectáculo en solitario puede parecer muy aburrido. Con ustedes dos, este palco ya se ha llenado de calor y vida. En realidad, soy yo quien les debe agradecer.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001318,
          FinalCamera = "-722.753906,-375.015869,367.042969,0.000203,-15.398278,26.595276,30.0,210.445709,false,DoNotOverride,10.0",
          GUID = "1E0B463C",
          NextDialogue = 12001319,
          Scripts = [[
PARA{
LookAt{_delay{9},LookAtDescription{"210004:n(100001)"}},
PlayAnimation{_delay{7},ActorId{210004},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Watching a show on one's own can feel a bit lonely. Having you two here has brightened this suite considerably. If anything, I should be the one thanking you.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B463C"
        },
        [12001319] = {
          Camera = "-39.875977,-172.393066,112.152344,0.000143,-4.597844,106.196785,30.000008,106.771988,false,Manual,10.0",
          ContentES = "{性别:Pequeño secuaz|Pequeña secuaz}, ¿puedes creer que alguien dejaría plantada a una dama tan rica, generosa y hermosa? ¡Qué tonto!",
          DialogueId = 12001319,
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "1E0B4666",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001320,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Confident_Start"},Duration{1}},
TurnTo{_delay{0.1},TurnToDescription{"100001:n(200002)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, can you believe someone would stand up such a rich, generous, and gorgeous lady? What a fool!",
          TalkActionId = {
            [1] = "210004:Talk02_End"
          },
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4666"
        },
        [12001320] = {
          Camera = "-157.03418,-238.744385,135.445312,0.000194,-1.198671,55.205051,29.855673,334.603516,false,DoNotOverride,10.0",
          ContentES = "En mi país, los encuentros entre las personas se llaman destino. Esos momentos son raros y valiosos, y cuando se presentan, conviene apreciarlos. ¿Qué opinas?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001320,
          FinalCamera = "2.482422,-380.777344,275.316406,0.000165,-21.198877,95.206535,29.855673,334.603516,false,DoNotOverride,10.0",
          GUID = "1E0B4690",
          LookAt = {
            [1] = "200002:n(210004)",
            [2] = "100001:n(210004)",
            [3] = "210004:n(210004)"
          },
          NextOptions = {
            [1] = 120013201,
            [2] = 120013202
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{9},ActorId{210004},AnimationId{"Zhiliu_Story_Special02_Start"},Duration{1}},
LookAt{_delay{6},LookAtDescription{"210004:n(100001)"}},
TurnTo{_delay{6.5},TurnToDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "In my homeland, we refer to the chance encounters between people as \"fate.\" Such moments are rare and precious. When it happens, we believe it's worth cherishing — wouldn't you agree?",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "100001:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4690"
        },
        [12001321] = {
          Camera = "130.839844,-87.01416,151.46875,0.00015,-13.198083,176.609421,43.803253,210.445709,false,Manual,10.0",
          ContentES = "¡Nieve está completamente de acuerdo con la gran hermana Zhiliu! ¡Entonces, Nieve y {nickname} se quedarán con gusto, muchas gracias!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001321,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E0B46BA",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12001322,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200002:n(210004)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Snow thinks this nice, pretty lady is absolutely right! So, Snow and  will stay! Thank you for having us~",
          TalkActionId = {
            [1] = "200002:Talk03_Start",
            [2] = "210004:Zhiliu_Story_Special02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B46BA"
        },
        [12001322] = {
          Camera = "-29.191406,-99.70166,165.839844,0.000196,-0.599062,67.805344,43.803253,150.779633,false,DoNotOverride,10.0",
