        [12001324] = {
          Camera = "4572.582031,245.40918,-1846.019531,0.000001,19.997604,-90.387962,20.000008,878.773254,false,Manual,1.2",
          ContentES = "Damas y caballeros, el espectáculo está a punto de comenzar. A los que lleguen tarde, por favor tomen asiento rápidamente.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001324,
          FinalCamera = "4562.724609,-667.667236,-1513.722656,0.000001,19.997604,-90.387962,20.000008,878.773254,false,Manual,1.2",
          GUID = "1E0B4738",
          NextDialogue = 12001325,
          Subtitle = "Ladies and gentlemen, the performance is about to begin. Kindly take your seats at your earliest convenience.",
          TalkActionId = {
            [1] = "220041:Sit_Idle_Start",
            [2] = "220042:Sit_Talk03_Loop"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4738"
        },
        [12001325] = {
          ContentES = "¡Y ahora, disfruten del magnífico espectáculo presentado por la compañía de ópera de Galea!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001325,
          GUID = "1E0B4762",
          NextDialogue = 12001326,
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "Up next, we are delighted to present a magnificent performance by the Galea Opera Troupe.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4762"
        },
        [12001326] = {
          Camera = "-213.078125,597.674805,707.015625,0.000202,-11.600912,-178.603836,40.000023,1102.562866,false,Manual,1.2",
          ContentES = "Hace mucho tiempo... en un castillo de hielo, en el corazón de un país nevado... Un hada de escarcha despertó con la risa de dos niños.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001326,
          FinalCamera = "-211.563477,535.948242,707.015625,0.000202,-11.600912,-178.603836,40.000023,1102.562866,false,Manual,1.2",
          GUID = "1E0B478C",
          NextDialogue = 12001327,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0069_boss_devil_linen\"}}",
          Subtitle = "Once upon a time, in a frosted castle in the Snowfield, a slumbering frost fairy was awakened by the laughter of two children...",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B478C"
        },
        [12001327] = {
          Camera = "7325.71875,5494.020508,541.855469,0.000293,22.789042,-159.560425,20.0,500.0,false,Manual,10.0",
          ContentES = "La frágil hada voló hacia las criaturas monstruosas...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001327,
          FinalCamera = "7183.162109,5440.892578,605.769531,0.000291,26.788889,-155.961044,20.0,500.0,false,Manual,10.0",
          GUID = "1E0B47B6",
          NextDialogue = 12001328,
          Subtitle = "The tiny fairy flew towards the monstrous creature...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B47B6"
        },
        [12001328] = {
          ContentES = "Pero sus garras rompieron sin esfuerzo sus frágiles miembros.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001328,
          FacialId = {
            [1] = "220041:Sad03"
          },
          GUID = "1E0B47E0",
          LookAt = {
            [1] = "220041:n(220041)",
            [2] = "220042:n(220042)"
          },
          NextDialogue = 12001329,
          Subtitle = "...only for its delicate limbs to snap beneath its might.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B47E0"
        },
        [12001329] = {
          Camera = "32.304688,240.658203,114.476562,0.000086,-2.603053,-135.186905,30.000002,132.470917,false,Manual,6.527582",
          ContentES = "Sin embargo, por primera vez... su corazón latió. Latió... ¡y gritó su propio destino!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001329,
          Duration = 5,
          FinalCamera = "41.55957,229.902832,114.476562,0.000085,-3.003077,-141.986862,30.000002,132.470917,false,Manual,6.527582",
          GUID = "1E0B480A",
          NextDialogue = 12001370,
          Subtitle = "The fairy's frozen heart pulsed for the first time — beating, screaming its own destiny—",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B480A"
        },
        [12001330] = {
          Camera = "52.354492,214.417969,109.269531,0.0,-0.001434,-142.205307,45.0,101.750626,false,Manual,5.456383",
