          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4834"
        },
        [12001331] = {
          ContentES = "Parece que estás un poco afectada...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001331,
          GUID = "1E0B485E",
          NextDialogue = 12001332,
          SpeakNpcId = 100001,
          Subtitle = "You seem a little upset.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B485E"
        },
        [12001332] = {
          ContentES = "Algo en la historia me tocó, eso es todo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001332,
          FacialId = {
            [1] = "220041:Close"
          },
          GUID = "1E0B4888",
          NextDialogue = 12001334,
          SpeakNpcId = 220041,
          Subtitle = "Something in the story struck a chord with me, that's all.",
          TalkActionId = {
            [1] = "220041:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4888"
        },
        [12001333] = {
          ContentES = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001333,
          DisableMouth = 1,
          FinalCamera = "617.853516,615.266602,211.964844,0.00002,-9.801267,-144.203323,50.0,799.630554,false,Manual,1.2",
          GUID = "1E0B48B2",
          NextDialogue = 12001334,
          SpeakNpcId = 220041,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B48B2"
        },
        [12001334] = {
          Camera = "617.853516,615.266602,211.964844,0.00002,-9.801267,-144.203323,50.0,799.630554,false,Manual,1.2",
          ContentES = "No importa el lugar y la época, la misma historia se repite. Los héroes intercambian su vida y su sacrificio por algo más grande, más noble.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001334,
          FacialId = {
            [1] = "220041:Zhiliu_SpecialSad"
          },
          FinalCamera = "728.994141,695.423828,235.628906,0.00002,-9.801267,-144.203323,50.0,930.356812,false,Manual,1.2",
          GUID = "1E0B48DC",
          LookAt = {
            [1] = "200002:n(220041)"
          },
          NextDialogue = 12001335,
