]],
          SpeakNpcId = 220041,
          Subtitle = "Across every time and place, the same stories are told — tales of those who sacrifice their lives for something greater.",
          TalkActionId = {
            [1] = "220041:Sit_Talk02_Start"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(220041)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B48DC"
        },
        [12001335] = {
          Camera = "-46.225586,57.569824,112.15625,0.00005,-1.201355,80.793785,45.000023,91.94062,false,Manual,4.511572",
          ContentES = "Pero… ¿realmente valen ese precio las cosas por las que uno cambia su vida?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001335,
          FinalCamera = "-42.095703,57.018555,112.15625,0.00005,-1.201355,82.394051,45.000023,140.453064,false,Manual,4.511572",
