]],
          SpeakNpcId = 220041,
          Subtitle = "But... are the things they die for truly worth the price?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4906"
        },
        [12001336] = {
          Camera = "617.853516,615.266602,211.964844,0.00002,-9.801267,-144.203323,50.0,799.630554,false,Manual,1.2",
          ContentES = "Jeje... mírame, poniéndome sentimental de repente.",
