        [12001346] = {
          ContentES = "La audiencia se dispersa poco a poco, dejando el teatro que antes estaba lleno, vacío. Permanecen en un tenso silencio, frente al hombre que tienen delante.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001346,
          Duration = 2,
          GUID = "1E0B4AD4",
          NextDialogue = 12001347,
          SpeakNpcId = 100001,
          Subtitle = "The audience gradually disperses, leaving the once-bustling theatre empty. You stand in tense silence, facing the man before you.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4AD4"
        },
        [12001347] = {
          ContentES = "El sonido de pasos agudos y deliberados resuena por todo el teatro vacío.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001347,
          Duration = 2,
          GUID = "1E0B4AFE",
          SpeakNpcId = 100001,
          Subtitle = "The sound of sharp, deliberate footsteps echoes through the hall.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4AFE"
        },
        [12001348] = {
