          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B28"
        },
        [12001349] = {
          Camera = "-61.787109,560.610352,42.621094,0.000029,-2.997223,-101.179504,25.0,332.928833,false,Manual,3.5",
          ContentES = "Je... ¿una pequeña advertencia, eh? Basta de excusas. Entonces, muéstrame la mercancía.",
          DialogueId = 12001349,
          FacialId = {
            [1] = "220014:Unhappy01",
            [2] = "100001:Unhappy01",
            [3] = "200002:Angry01"
          },
          GUID = "1E0B4B52",
          LookAt = {
            [1] = "220017:n(220014)",
            [2] = "220045:n(220014)"
          },
          NextDialogue = 12001350,
          SpeakNpcId = 220014,
          Subtitle = "Heh, a little power play, was it? Enough with the excuses. Show me the goods.",
          TalkActionId = {
            [1] = "220014:Talk03_Start",
            [2] = "220018:Talk01_End"
          },
          TurnTo = {
            [1] = "220017:n(220014)",
            [2] = "220045:n(220014)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B52"
        },
        [12001350] = {
          Camera = "144.626953,288.033691,17.613281,0.000053,6.199516,141.999878,35.000008,313.697113,false,Manual,3.5",
          ContentES = "El Phoxichor que pediste... lo he traído.",
          DialogueId = 12001350,
          FacialId = {
            [1] = "220018:CM_Idle"
          },
          GUID = "1E0B4B7C",
          NextDialogue = 12001351,
          SpeakNpcId = 220018,
          Subtitle = "The Phoxichor you asked for — I have it.",
          TalkActionId = {
            [1] = "220018:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B7C"
        },
        [12001351] = {
          Camera = "-38.164062,434.716309,-32.25,0.0,4.803002,-86.580322,40.000011,316.356659,false,DoNotOverride,10.0",
          ContentES = "Espera, conozco a ese tipo... Camilla me habló de él. Es un conocido traficante de armas del mercado negro aquí. Lo que vende siempre es de mala calidad, ¡y siempre está tramando para estafar a la gente!",
          DialogueId = 12001351,
          FacialId = {
            [1] = "220014:None"
          },
          GUID = "1E0B4BA6",
          NextDialogue = 12001352,
          Scripts = [[
SEQ{
LookAt{_delay{4},LookAtDescription{"200002:n(220014)"}},
LookAt{_delay{3.5},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{1},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
LookAt{_delay{0.1},LookAtDescription{"200002:n(220018)"}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wait, I know that guy... Camilla told me all about him. He's a notorious underground arms dealer around here. The stuff he peddles is always subpar, and he's always scheming to rip people off!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BA6"
        },
        [12001352] = {
          Camera = "63.847656,460.318359,7.578125,0.000011,9.802803,-126.5784,40.000011,240.677155,false,Manual,4.0",
          ContentES = "Déjenme aclarar un punto. No quiero cualquier Phoxichor que se encuentre en la calle. Quiero el más puro, no menos del 95 % de pureza. ¿Está claro?",
          DialogueId = 12001352,
          GUID = "1E0B4BD0",
          NextDialogue = 12001353,
          SpeakNpcId = 220014,
          Subtitle = "Allow me to confirm one last time. I am not seeking just any common Phoxichor that can be procured from a street vendor. My requirement is for the highest grade, with a purity of no less than 95%. Is that understood?",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkR_Start",
            [2] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BD0"
        },
        [12001353] = {
          Camera = "-44.837891,371.257324,-0.773438,0.000035,26.402218,125.022018,25.0,158.270889,false,Manual,10.0",
          ContentES = "Puede verificarlo usted misma... pero aquí, la regla es clara: pago primero, inspección después. Así que pague, dama, y después podrá examinar su mercancía.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001353,
          GUID = "1E0B4BFA",
          NextOptions = {
            [1] = 12001354,
            [2] = 12001355,
            [3] = 12001356
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"637.140625,977.703125,1000.703125,-1.999998,-48.797268,-147.182938,35.000008,158.270889,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"661.132812,993.179199,1033.300781,-1.999999,-48.79726,-147.18251,35.000008,158.270889,false,Manual,10.0"},duration{8}}
}]],
          SpeakNpcId = 220018,
          Subtitle = "You're free to inspect it yourself. But let me make one thing clear — our policy is payment first. Pay up, ma'am, and then it's all yours to examine.",
          TalkActionId = {
            [1] = "220018:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BFA"
        },
        [12001354] = {
          ContentES = "¿Y si no está a la altura? ¿Ofrecen servicio postventa?",
          DialogueId = 12001354,
          GUID = "1E0B4C24",
          ImprPlusId = 1008,
          NextDialogue = 12001357,
          Subtitle = "But what if it's not good enough? Do you offer after-sale service?"
        },
        [12001355] = {
          ContentES = "Eso va en contra de las reglas comerciales más básicas...",
          DialogueId = 12001355,
          GUID = "1E0B4C4E",
          ImprPlusId = 1007,
          NextDialogue = 12001357,
          Subtitle = "That goes against the most basic rules of fair trade."
        },
        [12001356] = {
          ContentES = "¿Nos toma por idiotas?",
          DialogueId = 12001356,
          GUID = "1E0B4C78",
          ImprPlusId = 1010,
          NextDialogue = 12001357,
          Subtitle = "How gullible do you think we are?"
        },
        [12001357] = {
          Camera = "-75.988281,358.869629,53.726562,0.000057,3.402465,-176.978516,25.000006,158.270889,false,Manual,10.0",
          ContentES = "¡Jefe! Estamos en ventaja… ¿por qué seguir jugando a esto? ¡La golpeamos y tomamos el dinero de inmediato!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001357,
          FinalCamera = "-75.574219,350.87207,53.726562,0.000057,3.402465,-176.978516,25.000006,158.270889,false,Manual,10.0",
          GUID = "1E0B4CA2",
          LookAt = {
            [1] = "220017:n(220018)",
            [2] = "220018:n(220017)"
          },
          NextDialogue = 12001358,
          Scripts = "PlayAnimation{_delay{3},ActorId{220017},AnimationId{\"Angry01_Start\"},Duration{1}}",
          SpeakNpcId = 220017,
          Subtitle = "Boss, why bother with this act? We've got the numbers — let's just beat her up and take the money!",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkR_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "220017:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CA2"
        },
        [12001358] = {
          ContentES = "Suspiro, ¿alguna vez se ha preguntado por qué vengo sola, sabiendo perfectamente que era una trampa?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001358,
          FacialId = {
            [1] = "220014:Unhappy01"
          },
          GUID = "1E0B4CCC",
          LookAt = {
            [1] = "220017:n(220014)",
            [2] = "220014:n(220014)"
          },
          NextDialogue = 12001359,
          Scripts = [[
PARA{
TurnTo{_delay{3},TurnToDescription{"220014:p(-90)"}},
PlayAnimation{_delay{7},ActorId{220014},AnimationId{"Zhiliu_Story_Special01_Start"},Duration{1}},
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"417.058594,-480.313965,322.75,0.000088,-18.600859,121.800911,35.0,300.0,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"442.078125,-520.646973,338.714844,0.000088,-18.600859,121.800911,35.0,300.0,false,DoNotOverride,10.0"},duration{8}}
}}]],
          SpeakNpcId = 220014,
          Subtitle = "Have you paused to wonder why I would come here alone, fully aware this was a setup?",
          TalkActionId = {
            [1] = "220017:Angry01_End",
            [2] = "220014:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CCC"
        },
        [12001359] = {
          Camera = "-113.576172,153.044434,12.664062,-2.999998,19.998232,75.598701,45.0,118.744087,false,Manual,5.0",
          ContentES = "Hay dos posibilidades. O soy una ingenua que pensaba que la transacción saldría bien... o estoy completamente segura de que, no importa cuántos hombres hayas traído, saldré de aquí ilesa.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001359,
          FinalCamera = "-111.560547,160.901367,15.617188,-3.0,19.998232,75.598267,45.0,118.744087,false,Manual,5.0",
          GUID = "1E0B4CF6",
          LookAt = {
            [1] = "100001:n(220014)"
          },
          NextDialogue = 12001360,
          Scripts = [[
PARA{
LookAt{_delay{8},LookAtDescription{"220014:n(220018)"}},
TurnTo{_delay{8},TurnToDescription{"220014:n(220018))"}},
PlayAnimation{_delay{5},ActorId{220014},AnimationId{"Zhiliu_Story_Special01_End"},Duration{1}},
SEQ{
CameraMoveTo{_delay{7.8},TargetPosition{"-96.761719,405.072266,41.273438,0.000106,6.599212,-80.597214,35.000008,134.024002,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-99.173828,419.692871,39.5625,0.000106,6.599212,-80.597214,35.000008,134.024002,false,Manual,10.0"},duration{6}}
},
PlayFacial{_delay{7.8},ActorId {220014}, FacialId {"Smile01"}}
}]],
          SpeakNpcId = 220014,
          Subtitle = "There are two possibilities. Either I'm hopelessly naive, trusting that this exchange will proceed peacefully... or I'm entirely certain that no matter how many men you've brought, I'll leave here unscathed.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CF6"
        },
        [12001360] = {
          ContentES = "Ahora, ¿Cuál crees que es la correcta?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001360,
          GUID = "1E0B4D20",
          LookAt = {
            [1] = "220014:n(220018)"
          },
          NextDialogue = 12001361,
          SpeakNpcId = 220014,
          Subtitle = "Now, which do you think it is?",
          TalkActionId = {
            [1] = "220014:Confident_Start"
          },
          TurnTo = {
            [1] = "220014:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4D20"
        },
        [12001361] = {
          Camera = "131.576172,289.608887,84.367188,0.000099,-6.600128,133.393799,35.0,300.0,false,DoNotOverride,10.0",
          ContentES = "¿Q-Qué hacemos, jefe? Ella parece... segura de sí misma...",
          DialogueId = 12001361,
          GUID = "1E0B4D4A",
          NextDialogue = 12001362,
          SpeakNpcId = 220045,
          Subtitle = "Wh—What do we do, boss? It sounds like she's got everything under control...",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4D4A"
        },
        [12001362] = {
          ContentES = "... ¡Está faroleando! ¡A por ella!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001362,
          GUID = "1E0B4D74",
          LookAt = {
            [1] = "220017:n(220014)"
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"37.453125,910.947266,426.960938,0.000127,-36.200096,-101.606094,25.0,300.0,false,DoNotOverride,10.0"},duration{0}},
