}]],
          SpeakNpcId = 220018,
          Subtitle = "...She's bluffing! Let's get her!",
          TalkActionId = {
            [1] = "220018:Angry01_Start"
          },
          TurnTo = {
            [1] = "220017:n(220014)"
          },
