          SpeakNpcId = 220017,
          Subtitle = "Stop! Ma'am, please!",
          TalkActionId = {
            [1] = "220017:Shock_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "220045:n(220017)"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6442"
        },
        [12001502] = {
          Camera = "127.935547,523.036133,-20.207031,0.000092,7.799284,-141.520447,15.726627,200.0,false,Manual,10.0",
          ContentES = "Solo intentábamos ganarnos la vida... Así que, considere este Phoxichor como un pequeño obsequio. Una persona tan generosa y comprensiva como usted no nos lo reprochará, ¿verdad?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001502,
          FinalCamera = "134.429688,514.882812,-20.207031,0.000092,7.799284,-141.520447,15.726627,200.0,false,Manual,10.0",
          GUID = "1E0B646C",
          LookAt = {
            [1] = "220018:n(220014)",
            [2] = "220045:n(220014)"
          },
          NextDialogue = 12001503,
          SpeakNpcId = 220018,
          Subtitle = "We're just trying to make ends meet, ma'am... How about this: consider the Phoxichor a little gift from us. Someone as understanding and big-hearted as you wouldn't hold this against a few small-timers like us, right?",
          TalkActionId = {
            [1] = "220045:Shock_Start",
            [2] = "220018:Sigh_Start"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100001:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B646C"
        },
        [12001503] = {
          Camera = "14.5,387.598633,14.96875,0.000098,13.598428,-129.716461,35.0,150.928452,false,Manual,10.0",
          ContentES = "Oh, entonces, ¿su regla del “pago por adelantado” ha desaparecido de repente?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001503,
          FacialId = {
            [1] = "220014:Smile01"
          },
          FinalCamera = "17.179688,385.376953,14.96875,0.000097,13.598428,-129.7164,35.0,150.928452,false,Manual,10.0",
          GUID = "1E0B6496",
          NextDialogue = 12001504,
          SpeakNpcId = 220014,
          Subtitle = "Oh, so your \"payment first\" rule has suddenly vanished, has it?",
          TalkActionId = {
            [1] = "220014:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6496"
        },
        [12001504] = {
          Camera = "-115.498047,99.109863,52.492188,0.000096,-6.601213,84.599968,15.726624,200.0,false,Manual,10.0",
          ContentES = "No importa... continuar esta conversación sería una pérdida de tiempo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001504,
          FacialId = {
            [1] = "220014:None"
          },
          FinalCamera = "-115.046875,103.809082,51.945312,0.000086,-6.601213,84.599968,15.726624,200.0,false,Manual,10.0",
          GUID = "1E0B64C0",
          NextDialogue = 12001505,
          SpeakNpcId = 220014,
          Subtitle = "Never mind. Continuing this conversation any longer would be a waste of my time.",
          TalkActionId = {
            [1] = "220014:Talk03_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B64C0"
        },
        [12001505] = {
          Camera = "-42.099609,587.145996,76.535156,0.000088,-8.999682,-104.72139,25.0,200.0,false,Manual,5.0",
          ContentES = "{nickname}, pásame el recipiente. Tengo que preparar mis herramientas para la inspección.",
          DialogueId = 12001505,
          FacialId = {
            [1] = "220014:Smile01"
          },
          FinalCamera = "-44.277344,578.862305,75.191406,0.000088,-8.999682,-104.721428,25.0,200.0,false,Manual,5.0",
          GUID = "1E0B64EA",
          LookAt = {
            [1] = "220014:n(100001)"
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 220014,
          Subtitle = ", would you pass me the container? I need to ready my tools for inspection.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "220014:p(90)"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B64EA"
        },
        [12001506] = {
          Camera = "-123.306641,51.673828,57.578125,0.000084,-6.004364,82.614265,50.096283,616.28064,false,Manual,10.0",
          ContentES = "(Zhiliu saca un pequeño objeto finamente trabajado y lo enciende. Recuerdas haber leído su descripción en un libro... ¿Tal vez un incensario finamente cincelado?)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001506,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_IncenseBurner01.T_Guide_Chapter_IncenseBurner01'}",
          Duration = 5,
          FinalCamera = "-120.710938,71.675781,55.433594,0.000084,-6.004364,82.614265,50.096283,616.28064,false,Manual,10.0",
          GUID = "1E0B6514",
          LookAt = {
            [1] = "100001:n(220014)",
            [2] = "200002:n(220014)"
          },
          NextDialogue = 12001507,
          Scripts = [[
PARA{
SetLocation{ActorId{220017},TargetPoint{"TargetPointbaobiao2"},Visibility{"Show"}},
SetLocation{ActorId{220045},TargetPoint{"TargetPointbaobiao3"},Visibility{"Show"}},
SetLocation{ActorId{220018},TargetPoint{"TargetPointheishang"},Visibility{"Show"}}
}]],
          Subtitle = "(Zhiliu retrieves a small, intricate object and lights it. Its design jogs your memory — you recall reading about it in a book. Could it be a carved incense burner?)",
          TalkActionId = {
            [1] = "220014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6514"
        },
        [12001507] = {
          Camera = "-37.900391,41.320801,125.242188,0.00003,17.980465,116.970291,22.896927,616.28064,false,Manual,10.0",
          ContentES = "(El humo se eleva, fino y perfectamente recto, antes de disiparse en el aire.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001507,
          Duration = 5,
          FinalCamera = "-37.900391,41.320801,125.242188,0.000031,26.780283,116.768852,22.896927,616.28064,false,Manual,10.0",
          GUID = "1E0B653E",
          NextDialogue = 12001508,
          Subtitle = "(Slender trails of smoke curl upwards, perfectly straight, before fading into nothingness.)",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B653E"
        },
        [12001508] = {
          Camera = "-1.962891,363.010254,80.773438,0.000094,-10.804443,-134.590561,35.000011,200.0,false,DoNotOverride,10.0",
          ContentES = "Este incienso es una rara especialidad de Huaxu. Reacciona fuertemente con una sustancia presente en el Phoxichor puro. Incluso un contacto mínimo altera el trayecto del humo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001508,
          GUID = "1E0B6568",
          NextDialogue = 12001509,
          SpeakNpcId = 220014,
          Subtitle = "This incense is a rare speciality of Huaxu. It resonates powerfully with a particular substance found in pure Phoxichor. Even the slightest contact will cause the smoke to change its pattern.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6568"
        },
        [12001509] = {
          Camera = "26.769531,320.916504,68.851562,0.000117,-2.605321,-158.169327,58.891438,116.774818,false,Manual,10.0",
          ContentES = "... A juzgar por el humo, el Phoxichor que ha traído es incluso peor que la calidad más baja.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001509,
          FacialId = {
            [1] = "220014:None"
          },
