          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B68DA"
        },
        [12001530] = {
          Camera = "-7.876221,306.707031,115.128906,0.000392,-12.597136,-157.65332,19.845514,128.396683,false,Manual,10.0",
          ContentES = "¿Así que este es tu “cliente importante”, eh? Hm-hmm, bueno, ustedes dos sigan charlando. ¡La muy madura y muy confiable Nieve se va a divertir por allá!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001530,
          GUID = "1E0B6904",
          LookAt = {
            [1] = "200002:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 12001531,
          SpeakNpcId = 200002,
          Subtitle = "So this is your \"important client,\" huh? Hm-hmm, well, you two chat away. The ever-mature and oh-so-reliable Snow is off to have some fun on her own!",
          TalkActionId = {
            [1] = "200002:Confident_End",
            [2] = "210004:Talk01_End"
