          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6958"
        },
        [12001533] = {
          ContentES = "El presagio decía: “Aliméntate de prudencia en el peligro, y la fortuna te seguirá. Es favorable cruzar el gran río.” Insinuaba pruebas que se enfrentarían, pero prometía un resultado afortunado.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001533,
          GUID = "1E0B6982",
          NextDialogue = 12001534,
          Scripts = [[
PARA{
PlayAnimation{_delay{8},ActorId{210004},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{8},ActorId{210004},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "The Symbol said \"Nourishment — Through peril comes fortune. Favourable it is to cross the great river.\" It hinted at trials to be faced, yet promised a fortuitous outcome.",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6982"
        },
        [12001534] = {
