          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8566"
        },
        [12001704] = {
          Camera = "-209.10791,563.994629,166.718994,0.000088,-16.400301,-72.382965,35.000008,319.844727,false,DoNotOverride,10.0",
          ContentES = "¿Estabas intentando escabullirte a escondidas, ¿verdad? ¡Nada escapa a los ojos agudos de la Reina Demonio!",
          DialogueId = 12001704,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-220.403809,560.411621,166.718994,0.000088,-16.400301,-72.382965,35.000008,318.951508,false,DoNotOverride,10.0",
          GUID = "1E0B8590",
          NextDialogue = 12001705,
          SpeakNpcId = 200002,
          Subtitle = "You were trying to sneak off, weren't you? Nothing escapes the sharp eyes of this Demon King!",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8590"
        },
        [12001705] = {
          ContentES = "Mírate, has estado ausente todo el día, y apenas has tocado tu cena. Lo vi venir de inmediato...",
          DialogueId = 12001705,
          GUID = "1E0B85BA",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001706,
          Scripts = [[
SEQ{
MoveTo{ActorId{200002},MoveSpeed{45},TargetPoint{"12000303Xiaobai"}},
PlayAnimation{_delay{3.5},ActorId{200002},AnimationId{"Confident_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Look at you — you've been out of it all day, and you barely even touched your dinner. I saw right through it—",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B85BA"
        },
        [12001706] = {
          Camera = "-182.647461,379.094727,120.482178,0.000029,-26.199799,-40.567471,23.066504,99.404587,false,Manual,10.0",
          ContentES = "¿Intentando dejarme atrás y aventurarte por tu cuenta? ¡Ni hablar!",
          DialogueId = 12001706,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          GUID = "1E0B85E4",
          NextDialogue = 12001707,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Trying to ditch me and go adventuring all by yourself? Not a chance!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B85E4"
        },
        [12001707] = {
          Camera = "-26.722656,319.375977,59.239258,0.000077,19.398317,164.820892,35.000011,187.953278,false,Manual,10.0",
          ContentES = "…No es que no quiera llevarte conmigo. Es solo que… esta vez podría enfrentarme a los soldados de Hyperborea y meterme en un buen lío. No quiero arrastrarte a mis problemas.",
          DialogueId = 12001707,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "1E0B860E",
          NextDialogue = 12001708,
          SpeakNpcId = 100001,
          Subtitle = "...It's not that I don't want to bring you. It's just... this time, I might have to deal with the Hyperborean soldiers and land myself in trouble. I don't want to drag you into my mess.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B860E"
        },
        [12001708] = {
          Camera = "-182.111328,611.16748,189.450439,0.000017,-21.399889,-85.183884,35.000011,306.042999,false,Manual,10.0",
          ContentES = "Eh... ¿cuántas veces ya hemos causado líos con los soldados de Hyperborea, eh?",
          DialogueId = 12001708,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "1E0B8638",
          NextDialogue = 12001709,
          SpeakNpcId = 200002,
          Subtitle = "Uh, haven't we already messed with the Hyperborean soldiers like a hundred times before?",
          TalkActionId = {
            [1] = "200002:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8638"
        },
        [12001709] = {
          Camera = "-103.983398,353.585449,106.5271,0.000045,18.199305,158.02092,35.000015,95.311615,false,Manual,10.0",
          ContentES = "Sí... tienes razón.",
          DialogueId = 12001709,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "1E0B8662",
          NextDialogue = 12001710,
          SpeakNpcId = 100001,
          Subtitle = "...Can't argue with that.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8662"
        },
        [12001710] = {
          Camera = "-179.918945,441.123047,116.523438,0.000046,-14.999873,-65.990524,35.000019,142.117508,false,Manual,10.0",
          ContentES = "De todos modos, ¡estás bajo mi protección, {性别:Pequeño secuaz|Pequeña secuaz}! ¡Tus líos son, sin duda, mis líos también!",
          DialogueId = 12001710,
          GUID = "1E0B868C",
          NextOptions = {
            [1] = 120017101,
            [2] = 120017111
          },
          SpeakNpcId = 200002,
          Subtitle = "Anyway! You're under my wing, Little Minion. Your mess is surely my mess!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B868C"
        },
        [12001711] = {
          ContentES = "¡Hmpf! ¡Por supuesto! ¿Quién lo dudaría?",
          DialogueId = 12001711,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1E0B86B6",
          NextDialogue = 12001714,
          SpeakNpcId = 200002,
          Subtitle = "Hm-hmm~ Of course! That goes without saying!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B86B6"
        },
        [12001712] = {
          ContentES = "¡N—N—No, para nada! ¡Era solo para probar tus habilidades, no lo malinterpretes!",
          DialogueId = 12001712,
          FacialId = {
            [1] = "200002:Guilty"
          },
          GUID = "1E0B86E0",
          NextDialogue = 12001713,
          SpeakNpcId = 200002,
          Subtitle = "T—That's not true... I was just testing your strength! Don't get the wrong idea!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B86E0"
        },
        [12001713] = {
          ContentES = "Además, aunque no esté en la primera línea, ¡mis tácticas de combate de nivel genial seguro que han sido de gran ayuda!",
          DialogueId = 12001713,
          GUID = "1E0B870A",
          NextDialogue = 12001714,
          Scripts = "PlayFacial{_delay{2.5},ActorId{200002},FacialId{\"Happy02\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Besides, even if I'm not on the front lines, my genius-level combat tactics must have been a huge help!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B870A"
        },
        [12001714] = {
          Camera = "-193.492676,858.771973,219.772217,0.000168,-15.999936,-85.57428,34.755398,150.385727,false,DoNotOverride,10.0",
          ContentES = "¡En cualquier caso, tus aventuras no estarían completas sin la gran Reina Demonio a tu lado!",
          DialogueId = 12001714,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "1E0B8734",
          NextDialogue = 12001715,
          SpeakNpcId = 200002,
          Subtitle = "In any case — your adventures wouldn't be complete without the great Demon King at your side!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8734"
        },
        [12001715] = {
