        [12001718] = {
          Camera = "-142.703125,609.208008,187.844482,0.000028,-19.60034,-93.377975,35.000011,303.12915,false,Manual,10.0",
          ContentES = "¡¡Lo tengo absolutamente y a la perfección!! Soy genial corriendo… digo, ¡haciendo una retirada táctica!",
          DialogueId = 12001718,
          FacialId = {
            [1] = "200002:Happy02"
