        },
        [12001729] = {
          Camera = "65.932007,301.697998,280.254395,0.000109,-22.599722,-120.592827,35.000008,273.028198,false,DoNotOverride,10.0",
          ContentES = "¡Entonces! ¡El destino oficial de nuestra aventura es esa cabina roja! ¡Sea ella o no, pronto lo sabremos!",
