          DialogueId = 12001732,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "1E0B8A28",
          NextDialogue = 12001733,
          SpeakNpcId = 200002,
          Subtitle = "Excuse me, miss, could I borrow a coin?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8A28"
        },
        [12001733] = {
          Camera = "-215.51416,41.373215,141.798096,0.00017,-14.398919,-73.593544,54.999653,201.282196,false,Manual,10.0",
          ContentES = "Quería comprarme una buena leche con miel bien calentita, pero me caí... y mi moneda rodó en las alcantarillas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001733,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "1E0B8A52",
          NextDialogue = 12001734,
          SpeakNpcId = 200002,
          Subtitle = "I was really hoping for a nice warm cup of honey milk, but I tripped on the way out... and my coin rolled right into the sewer.",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8A52"
        },
        [12001734] = {
          Camera = "-49.303223,-343.204956,74.226807,0.000171,8.000842,110.802505,54.999653,503.135712,false,Manual,10.0",
          ContentES = "¡Vete de aquí, Lunaria!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001734,
          GUID = "1E0B8A7C",
          NextDialogue = 12001735,
          SpeakNpcId = 220022,
          Subtitle = "Shoo, go away, Lunarian.",
          TalkActionId = {
            [1] = "220022:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8A7C"
        },
        [12001735] = {
          ContentES = "¡Estoy en misión, no me molestes!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001735,
          GUID = "1E0B8AA6",
          NextDialogue = 12001736,
          SpeakNpcId = 220022,
          Subtitle = "I'm on duty. Out of my way!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8AA6"
        },
        [12001736] = {
          Camera = "-175.340332,270.149841,203.560059,0.000172,-16.199083,-91.996391,54.999645,437.747101,false,Manual,10.0",
          ContentES = "... ¡Hmpf.! ¡Egoísta! Bueno, no importa, ¡iré a buscar mi moneda en otro lado!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001736,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E0B8AD0",
          SpeakNpcId = 200002,
          Subtitle = "...Hmph. Penny-pincher. Fine — I'll just go find a coin somewhere else!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8AD0"
        },
        [12001737] = {
          Camera = "-73.276855,44.644669,120.320557,0.000097,2.710902,148.667847,35.0,143.995453,false,Manual,10.0",
          ContentES = "Ingrid, informa tu estado.",
