        [12001750] = {
          Camera = "-1022.552795,-126.818176,848.524902,0.000189,-8.400995,-9.012328,25.000002,226.894241,false,DoNotOverride,10.0",
          ContentES = "(A lo lejos, el martilleo de las botas se mezcla con los gritos agudos de un comandante dando órdenes.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001750,
          Duration = 5,
