          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8D70"
        },
        [12001753] = {
          Camera = "175.711914,-2.875854,107.7854,0.00008,8.799318,-81.197479,35.000008,124.760086,false,Manual,10.0",
