            [1] = 405008
          },
          SpeakNpcId = 210031,
          Subtitle = "Miss Zhiliu! You've returned from your trip. So this Loongscion is your guest?",
          TalkActionId = {
            [1] = "210004:ConfidentRToTalk_End"
          },
