        },
        [12010118] = {
          Camera = "-148.47049,-63.694336,115.687988,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
          Content = "瞧{性别：他|她}的角，小巧、坚硬又有光泽，一看便有成龙之相。真是优秀的后生，让人看着就心生欢喜。",
          DialogueId = 12010118,
          FinalCamera = "-145.448669,-59.758316,115.963867,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
          GUID = "1E10E9FC",
          NextDialogue = 12010119,
          SpeakNpcId = 210031,
          Subtitle = "Look at {性别:his|her} horn — small, firm, and gleaming. Surely destined for greatness. Makes you smile just looking at this kid.",
          TalkActionId = {
            [1] = "210004:ConfidentR_End"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E9FC"
        },
        [12010119] = {
          Camera = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,50.0,147.841843,false,DoNotOverride,8.0",
          Content = "有龙氏……止流掌柜，你们是在说我吗？",
          DialogueId = 12010119,
          FacialId = {
            [1] = "100001:Curious"
          },
          FinalCamera = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,53.0,147.841843,false,DoNotOverride,8.0",
          GUID = "1E10EA26",
          NextDialogue = 12010120,
          SpeakNpcId = 100001,
          Subtitle = "Loongscion...? Proprietress Zhiliu, were you talking about me?",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EA26"
        },
        [12010120] = {
          Camera = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
          Content = "忘了告诉你，有龙氏是华胥文化中对于卡戎的称呼。不同于海伯利亚的歧视与打压，在这里，卡戎被视为护佑国家的祥瑞种族。",
          DialogueId = 12010120,
          GUID = "1E10EA50",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)"
          },
          NextDialogue = 12010121,
          SpeakNpcId = 210004,
          Subtitle = "Ah, I neglected to explain — in Huaxu, that is what we call the Charons. Unlike in Hyperborea, where they are shunned and oppressed, here they are regarded as a blessed lineage — guardians of our land.",
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "210004:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EA50"
        },
        [12010121] = {
          Content = "当初我遇见你时，看见年幼的有龙氏被旁人刁难，忍不住照拂了一下。",
          DialogueId = 12010121,
          FacialId = {
            [1] = "210004:Smile02"
          },
          GUID = "1E10EA7A",
          NextDialogue = 12010122,
          SpeakNpcId = 210004,
          Subtitle = "When I first encountered you, I could not abide the sight of a young Loongscion being treated so unfairly... so I intervened.",
          TalkActionId = {
            [1] = "210004:Explain01L_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EA7A"
        },
        [12010122] = {
          Camera = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,35.0,176.801208,false,DoNotOverride,8.0",
          Content = "这样说来……止流掌柜也是卡戎——啊，有龙氏。我那时就好奇过您的身份，您看起来地位并不普通。",
          DialogueId = 12010122,
          FinalCamera = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,38.0,176.801208,false,DoNotOverride,8.0",
          GUID = "1E10EAA4",
          NextDialogue = 12010123,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... speaking of which, you're a Charon too — I mean, a Loongscion. I've been curious since we first met — you're clearly not an ordinary person.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EAA4"
        },
        [12010123] = {
          Camera = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
          Content = "呵呵……{性别：小弟弟|小妹妹}，你觉得止流大当家是什么身份？",
          DialogueId = 12010123,
          GUID = "1E10EACE",
          LookAt = {
            [1] = "210031:n(100001)",
            [2] = [[

210004:n(210031)]],
            [3] = [[

100001:n(210031)]]
          },
          NextOptions = {
            [1] = 120101231,
            [2] = 120101232
          },
          SpeakNpcId = 210031,
          Subtitle = "Hehe... {性别:young man|young lass}, do you have any idea who Miss Zhiliu really is?",
          TalkActionId = {
            [1] = "210031:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EACE"
        },
        [12010124] = {
          Camera = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
          Content = "她可是年纪尚轻时，就获得了天命青睐，当上了<H>龙渊上卿</>。如今她司掌天禄司，就是说呀，咱们华胥所有贸易、财政、收税都归她管。",
          DialogueId = 12010124,
          FacialId = {
            [1] = "210004:Smile01"
          },
          FinalCamera = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
          GUID = "1E10EAF8",
          NextDialogue = 12010125,
          RelatedWikiId = {
            [1] = 407005
          },
          SpeakNpcId = 210031,
          Subtitle = "She was favoured by the Mandate of Heaven at a young age, rising to become the High Chancellor of Loongyuan. All trade, finance, and taxation in Huaxu fall under her authority.",
          TalkActionId = {
            [1] = "210004:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EAF8"
        },
        [12010125] = {
          Content = "只是，止流大当家为人平易近人，平日里不准我们称呼她的官职，只愿我们以大当家的头衔相称。在这里做生意的人，多多少少都承过她的人情。",
          DialogueId = 12010125,
          GUID = "1E10EB22",
          NextDialogue = 12010126,
          SpeakNpcId = 210031,
          Subtitle = "But Miss Zhiliu prefers to keep things low-key. She won't let us call her by her official title — she insists we just call her \"Miss.\" Everyone in the trade here owes her a debt of gratitude, one way or another.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EB22"
        },
        [12010126] = {
          Content = "……只是没有刻意提起的必要罢了。毕竟，以势压人，不如以理服人来得妥当。",
          DialogueId = 12010126,
          GUID = "1E10EB4C",
          NextDialogue = 12010127,
          SpeakNpcId = 210004,
          Subtitle = "...There is no need to make a fuss. After all, reason persuades with greater grace than rank ever could.",
          TalkActionId = {
            [1] = "210004:DisagreeHead",
            [2] = "210031:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EB4C"
        },
        [12010127] = {
          Camera = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,35.0,165.19751,false,DoNotOverride,8.0",
          Content = "商人这个身份，进可织星揽月，退可通权达变。比起一官半职来，倒是更符合我的喜好。",
          DialogueId = 12010127,
          FinalCamera = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,38.0,165.19751,false,DoNotOverride,8.0",
          GUID = "1E10EB76",
          NextDialogue = 12010128,
          SpeakNpcId = 210004,
          Subtitle = "Besides, the calling of a merchant suits me best — one hand reaching for the stars, the other quietly pulling the strings from behind the scenes.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EB76"
        },
        [12010128] = {
          Camera = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "来，{性别：小弟弟|小妹妹}。止流大当家难得带贵客来。这件香囊你就作为见面礼收下吧。",
          DialogueId = 12010128,
          FinalCamera = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E10EBA0",
          NextOptions = {
            [1] = 120101281,
            [2] = 120101282
          },
          SpeakNpcId = 210031,
          Subtitle = "Here you are, {性别:young man|young lass}. Since you're Miss Zhiliu's guest, take this sachet as a welcome gift.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_End",
            [2] = "210031:Give"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EBA0"
        },
        [12010129] = {
          Content = "<H>香</>在华胥可是有着大作用。定气凝神，防身护体，个中妙用，你很快就能体悟到了。",
          DialogueId = 12010129,
          FacialId = {
            [1] = "210031:Cin_Happy01"
          },
          GUID = "1E10EBCA",
          RelatedWikiId = {
            [1] = 403005
          },
          SpeakNpcId = 210031,
          Subtitle = "In Huaxu, scent — be it incense, flowers, or herbs — carries profound meaning. It soothes the mind, wards off harm, and protects the body. You'll come to understand its wonders soon enough.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EBCA"
        },
        [12010130] = {
          Content = "烤鱿鱼还是香喷喷的小银鱼干，唔，好难选哦……",
          DialogueId = 12010130,
          Duration = 3,
          GUID = "1E10EBF4",
          NextDialogue = 12010131,
          SpeakNpcId = 200002,
          Subtitle = "Grilled squid or crispy silver fish...? Aww, I can't decide!",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EBF4"
        },
        [12010131] = {
          Content = "老板，一样来一份好了！多来点酱汁！",
          DialogueId = 12010131,
          GUID = "1E10EC1E",
          SpeakNpcId = 200002,
          Subtitle = "Okay — I'll have both! Extra sauce, please!",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EC1E"
        },
        [12010132] = {
          Content = "咦，白跑到哪里去了……",
          DialogueId = 12010132,
          GUID = "1E10EC48",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Huh? Where did Snow run off to...",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10EC48"
        },
        [12010201] = {
          Camera = "26.601562,-263.371094,126.632324,0.0,-8.000487,77.603035,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "所以说，梦想是很重要的——比如白的梦想，就是成为世界第一的大魔王！",
          DialogueId = 12010201,
          GUID = "1E10F79A",
          NextDialogue = 12010202,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011
          },
          SpeakNpcId = 200002,
          Subtitle = "And that's why it's so important to have a dream — for example, my dream is to become the world's greatest Demon King!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F79A"
        },
        [12010202] = {
          Content = "哇，说的太好了！",
          DialogueId = 12010202,
          GUID = "1E10F7C4",
          NextDialogue = 12010203,
          SpeakNpcId = 210003,
          Subtitle = "Wow! You're incredible!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F7C4"
        },
        [12010203] = {
          Content = "你看，华胥的这片码头有这么大对吧。今后本魔王大人的宫殿要比它大十倍！",
          DialogueId = 12010203,
          GUID = "1E10F7EE",
          NextDialogue = 12010204,
          SpeakNpcId = 200002,
          Subtitle = "Look at this dock — huge, isn't it? Well, one day, my royal palace will be ten times bigger!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F7EE"
        },
        [12010204] = {
          Content = "等梦想实现后，白每天就能睡到下午三点，然后从长一百米的大床上醒来，享用搜罗了全世界所有小蛋糕的豪华下午茶！",
          DialogueId = 12010204,
          GUID = "1E10F818",
          NextDialogue = 12010205,
          SpeakNpcId = 200002,
          Subtitle = "When my dream comes true, I'll sleep in every day till three in the afternoon, wake up on a hundred-metre-long bed, and have an afternoon tea stacked with cupcakes of every flavour from across the world!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F818"
        },
        [12010205] = {
          Content = "那……我要成为青史留名的织星客，在人类的史书上，写下皎皎一族的名字！",
          DialogueId = 12010205,
          GUID = "1E10F842",
          NextDialogue = 12010206,
          SpeakNpcId = 210003,
          Subtitle = "Then... I'll become the most legendary Starweaver ever! And I'll make sure the name of the Lunarians is written into human history!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F842"
        },
        [12010206] = {
          Content = "到时候，从现在这里到遥远的对岸，整个码头都要铺满我的货物。每个集装箱上都要画一个硕大的皎皎涂鸦！",
          DialogueId = 12010206,
          GUID = "1E10F86C",
          NextDialogue = 12010207,
          SpeakNpcId = 210003,
          Subtitle = "From this dock to the farthest shore, I'll cover the whole place with cargo ships brimming with my merchandise! And every last container will be emblazoned with a huge Luno logo!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F86C"
        },
        [12010207] = {
          Content = "很好，就要这个气势！大声喊出来，皎皎之民征服世界——",
          DialogueId = 12010207,
          GUID = "1E10F896",
          NextDialogue = 12010208,
          SpeakNpcId = 200002,
          Subtitle = "That's the spirit! Say it louder! The Lunarian shall conquer the world—!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F896"
        },
        [12010208] = {
          Content = "呜呜……早上起床时，我向白龙神君祈愿，希望今天可以撞见好运。",
          DialogueId = 12010208,
          GUID = "1E10F8C0",
          NextDialogue = 12010209,
          RelatedWikiId = {
            [1] = 303008
          },
          SpeakNpcId = 210003,
          Subtitle = "... This morning, I made a wish to Lord Argent, just hoping for a bit of luck today.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F8C0"
        },
        [12010209] = {
          Content = "本来只是指望来码头进货时，可以从那些抠门织星客手中再抢下几个单子。没想到，有生之年，竟然能让我看到活的有角皎皎……",
          DialogueId = 12010209,
          GUID = "1E10F8EA",
          NextDialogue = 12010210,
          SpeakNpcId = 210003,
          Subtitle = "I was only hoping to snag a few extra deals at the docks from those stingy Starweavers. But I never imagined I'd meet a real, living Luno with horns...",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F8EA"
        },
        [12010210] = {
          Camera = "345.640625,-174.457031,104.969238,0.000003,-0.600497,140.202652,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "看来白龙神君大人终于回应我的诚心了……那个，尊贵的魔王殿下，可以让我再摸一下你的角吗？",
          DialogueId = 12010210,
          GUID = "1E10F914",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextOptions = {
            [1] = 120102101,
            [2] = 120102102
          },
          SpeakNpcId = 210003,
          Subtitle = "It seems Lord Argent finally heard my heartfelt prayer... Um, Your Majesty the Demon King, may I touch your horns again?",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F914"
        },
        [12010211] = {
          Content = "小仆从，你怎么来了……你、你都听见了？",
          DialogueId = 12010211,
          GUID = "1E10F93E",
          NextOptions = {
            [1] = 120102111,
            [2] = 120102112
          },
          SpeakNpcId = 200002,
          Subtitle = "Little Minion! How long have you been standing there...? Y—You heard everything!?",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F93E"
        },
        [12010212] = {
          Content = "咳咳……这就是本魔王麾下的得力大将，{nickname}。",
          DialogueId = 12010212,
          GUID = "1E10F968",
          NextDialogue = 12010213,
          SpeakNpcId = 200002,
          Subtitle = "Ahem... Well, allow me to introduce my most trusted chief lieutenant — !",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F968"
        },
        [12010213] = {
          Content = "哇——不愧是魔王大人，竟然能吸引一位有龙氏前来效忠。幸会，我是即将成为华胥第一织星客的锦鲤皎皎！",
          DialogueId = 12010213,
          GUID = "1E10F992",
          NextDialogue = 12010214,
          RelatedWikiId = {
            [1] = 203002
          },
          SpeakNpcId = 210003,
          Subtitle = "Woooow! You're amazing, Demon King — even a Loongscion has pledged loyalty to you! It's such an honour to meet you! I'm Lunocarp — soon to be the number-one Starweaver in all of Huaxu!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F992"
        },
        [12010214] = {
          Camera = "422.453125,1255.105469,437.982422,0.00003,-8.400634,-104.197899,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "白，止流掌柜还在等着我们呢。玩够了就赶紧回去吧。",
          DialogueId = 12010214,
          GUID = "1E10F9BC",
          SpeakNpcId = 100001,
          Subtitle = "Snow, Proprietress Zhiliu is still waiting for us. If you're done here, let's head back.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F9BC"
        },
        [12010215] = {
          Camera = "-387.542969,474.4375,151.621582,0.000187,-2.20303,-35.42408,35.0,100000.0,false,Manual,12.0",
          Content = "止流掌柜——我把白找回来了。",
          DialogueId = 12010215,
          GUID = "1E10F9E6",
          NextDialogue = 12010216,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 203001
          },
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu — I've brought Snow back.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10F9E6"
        },
        [12010216] = {
          Content = "……一群**养的！没完没了！",
          DialogueId = 12010216,
          GUID = "1E10FA10",
          NextDialogue = 12010217,
          SpeakNpcId = 210002,
          Subtitle = "...You ***! I can't take this anymore!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FA10"
        },
        [12010217] = {
          Camera = "192.5,215.453125,162.744141,0.000181,-5.402953,-76.421349,35.0,100000.0,false,Manual,12.0",
          Content = "……小心！！！",
          DialogueId = 12010217,
          GUID = "1E10FA3A",
          NextDialogue = 12010218,
          SpeakNpcId = 100001,
          Subtitle = "...Watch out!!!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FA3A"
        },
        [12010218] = {
          Camera = "999.449219,-469.097656,578.913574,0.000173,-25.402763,150.978256,35.0,100000.0,false,Manual,12.0",
          Content = "喂，你就是这里的舵手吧？赶紧驾船带老子离开这个鬼地方，越快越好！",
          DialogueId = 12010218,
          GUID = "1E10FA64",
          NextDialogue = 12010219,
          SpeakNpcId = 210002,
          Subtitle = "Oi! You're the helmsman, yeah? Move this boat — now! I don't care where, just get me out of this damned place!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FA64"
        },
        [12010219] = {
          Content = "胆敢轻举妄动，或者做什么手脚，老子一刀嘎了你。",
          DialogueId = 12010219,
          GUID = "1E10FA8E",
          NextDialogue = 12010220,
          SpeakNpcId = 210002,
          Subtitle = "Try anything funny, and I'll gut you right here!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FA8E"
        },
        [12010220] = {
          Content = "放开他！",
          DialogueId = 12010220,
          GUID = "1E10FAB8",
          NextDialogue = 12010221,
          SpeakNpcId = 100001,
          Subtitle = "Let go of him!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FAB8"
        },
        [12010221] = {
          Camera = "-863.470703,299.425781,276.108887,0.000178,-7.60267,-14.021979,35.0,100000.0,false,Manual,12.0",
          Content = "冷静点，{nickname}，不用出手。",
          DialogueId = 12010221,
          GUID = "1E10FAE2",
          NextDialogue = 12010222,
          SpeakNpcId = 210004,
          Subtitle = "Steady, . There's no need for intervention.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FAE2"
        },
        [12010222] = {
          Content = "可是刀都架在船夫的脖子上了！明明是这么紧急的情况，你们怎么还能这么淡定！",
          DialogueId = 12010222,
          GUID = "1E10FB0C",
          NextDialogue = 12010223,
          SpeakNpcId = 200002,
          Subtitle = "But — he's got a knife to the boatman's throat! How can you be so calm?",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FB0C"
        },
        [12010223] = {
          Content = "这位劫匪大约是外来者，尚未熟悉这里的规矩。",
          DialogueId = 12010223,
          GUID = "1E10FB36",
          NextDialogue = 12010224,
          SpeakNpcId = 210004,
          Subtitle = "This man is likely a foreigner — still unfamiliar with how things are done here.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FB36"
        },
        [12010224] = {
          Content = "记得我先前所说吗？华胥是<H>止戈之乡</>。也好，让你们有机会亲眼见证——",
          DialogueId = 12010224,
          GUID = "1E10FB60",
          SpeakNpcId = 210004,
          Subtitle = "Remember what I told you? Huaxu is a realm of peace. And now, you shall see for yourselves—",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FB60"
        },
        [12010225] = {
          Content = "嗷呜——",
          DialogueId = 12010225,
          GUID = "1E10FB8A",
          Subtitle = "Awoo—!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FB8A"
        },
        [12010226] = {
          Content = "又是这些东西，怎么阴魂不散的！",
          DialogueId = 12010226,
          GUID = "1E10FBB4",
          Subtitle = "Not these beasts again! Why do they keep—",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FBB4"
        },
        [12010227] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那、那是什么……？",
          DialogueId = 12010227,
          GUID = "1E10FBDE",
          NextDialogue = 12010228,
          SpeakNpcId = 100001,
          Subtitle = "Wh—What was that...!?",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FBDE"
        },
        [12010228] = {
          Content = "小仆从，看到了吗！那个家伙只用了一招就让坏人消失了诶。",
          DialogueId = 12010228,
          GUID = "1E10FC08",
          NextDialogue = 12010229,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, did you see that? That creature took out the baddie in just one move!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FC08"
        },
        [12010229] = {
          Content = "<H>大风有隧，有空大谷。有兽狴犴，乘风而行。香尘扰扰，缘有罪因。</>这是华胥子民从牙牙学语时便能念诵的歌谣。",
          DialogueId = 12010229,
          GUID = "1E10FC32",
          NextDialogue = 12010230,
          SpeakNpcId = 210004,
          Subtitle = "Through cavernous vales, gales carve their path. Upon the blustery winds, Bi'an nears and prowls. Fragrant motes arise, born of transgression and sins. Such is a rhyme taught to every child of Huaxu from the cradle.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FC32"
        },
        [12010230] = {
          Content = "歌谣中的“狴犴”，便是你们所见之物——华胥的守护者。",
          DialogueId = 12010230,
          GUID = "1E10FC5C",
          NextDialogue = 12010231,
          RelatedWikiId = {
            [1] = 303009
          },
          SpeakNpcId = 210004,
          Subtitle = "The \"Bi'an\" mentioned in that rhyme is the very creature you just saw — They are the guardians of Huaxu.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FC5C"
        },
        [12010231] = {
          Content = "华胥全境被一种无声无形、但又恒常流转之法则，<H>大风九章</>所统御。任何人只要踏入了华胥的界域，就会进入大风九章的保护范围内。",
          DialogueId = 12010231,
          GUID = "1E10FC86",
          NextDialogue = 12010232,
          RelatedWikiId = {
            [1] = 304003
          },
          SpeakNpcId = 210004,
          Subtitle = "All of Huaxu is protected by an unseen, ever-present law known as the Nine Chapters of Dafeng. The moment someone steps into Huaxu, they fall under its domain.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FC86"
        },
        [12010232] = {
          Content = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
          DialogueId = 12010232,
          GUID = "1E10FCB0",
          NextDialogue = 12010233,
          SpeakNpcId = 210004,
          Subtitle = "And should anyone break that law... a Bi'an emerges, borne on blustery winds, to deliver judgement.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FCB0"
        },
        [12010233] = {
          Content = "原来，这就是这里完全杜绝犯罪的理由……",
          DialogueId = 12010233,
          GUID = "1E10FCDA",
          NextDialogue = 12010234,
          SpeakNpcId = 200002,
          Subtitle = "So that's why there's no crime in Huaxu at all...",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FCDA"
        },
        [12010234] = {
          Content = "只是不知何故，出现了不懂规矩的外来者。看来，这一趟办事归来，倒是有些“惊喜”等着我呢。",
          DialogueId = 12010234,
          GUID = "1E10FD04",
          NextDialogue = 12010235,
          SpeakNpcId = 210004,
          Subtitle = "Though it seems that a few ignorant souls managed to slip in while I was away... it appears that some \"surprises\" have been left in my absence.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FD04"
        },
        [12010235] = {
          Content = "大当家——不好意思，属下来迟了——",
          DialogueId = 12010235,
          GUID = "1E10FD2E",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Miss Zhiliu—! My apologies for arriving late!",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FD2E"
        },
        [12010301] = {
          Camera = "-156.389893,790.13324,235.143555,0.00015,-10.001431,-71.777824,50.0,856.361206,false,DoNotOverride,2.8",
          Content = "幸好歹人已经被截获了……他竟然跑到这里来，惊扰到了您。",
          DialogueId = 12010301,
          FacialId = {
            [1] = "210032:Cin_Sad01"
          },
          FinalCamera = "-137.076416,731.468506,224.247559,0.00015,-10.001431,-71.777466,50.0,856.361206,false,DoNotOverride,2.8",
          GUID = "1E110802",
          LookAt = {
            [1] = "100001:n(210032)",
            [2] = "210004:n(210032)",
            [3] = "210003:n(210032)"
          },
          NextDialogue = 12010302,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 203001,
            [4] = 303009,
            [5] = 304003
          },
          SpeakNpcId = 210032,
          Subtitle = "Thankfully, the criminal's already been dealt with... I can't believe he made it this far and even disturbed you.",
          TalkActionId = {
            [1] = "210032:Explain02_Start",
            [2] = "210004:ConfidentR_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120103/1E110802"
        },
        [12010302] = {
          Camera = "-53.126144,-142.106125,132.289062,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
          Content = "杜立，不用急。调顺了气息再说话。",
          DialogueId = 12010302,
          FacialId = {
            [1] = "210004:Unhappy01"
          },
          FinalCamera = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
          GUID = "1E11082C",
          NextDialogue = 12010303,
          SpeakNpcId = 210004,
          Subtitle = "Easy, Du Li. Catch your breath before you speak.",
          TalkActionId = {
            [1] = "210032:Explain02_End",
            [2] = "210004:ConfidentRToExplain_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120103/1E11082C"
        },
        [12010303] = {
          Content = "你迟来的理由，和这个歹徒有关吗？",
          DialogueId = 12010303,
          GUID = "1E110856",
          NextDialogue = 12010304,
          SpeakNpcId = 210004,
          Subtitle = "Your late arrival... Was it because of this man?",
          VoiceName = "voice/$Locale$/story/1201/120103/1E110856"
        },
        [12010304] = {
          Camera = "80.523117,233.023392,157.48584,0.000134,-5.002382,-84.793343,35.0,422.948425,false,DoNotOverride,2.8",
          Content = "……确是如此。",
          DialogueId = 12010304,
          FinalCamera = "83.662094,198.468262,154.45166,0.000134,-5.002382,-84.793343,35.0,422.948425,false,DoNotOverride,2.8",
          GUID = "1E110880",
          LookAt = {
            [1] = "210032:n(210004)"
          },
          NextDialogue = 12010305,
          SpeakNpcId = 210032,
          Subtitle = "...That's right.",
          TalkActionId = {
            [1] = "210004:ConfidentRToExplain_End",
            [2] = "210032:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120103/1E110880"
        },
        [12010305] = {
          Content = "最近<W>烛阴之灾</>势头愈烈。部分织星客对禁行令不满，绕开我们百年春，私自从外界雇了护卫，欲与险境一搏。",
          DialogueId = 12010305,
          GUID = "1E1108AA",
          NextDialogue = 12010306,
          RelatedWikiId = {
            [1] = 304004
          },
          SpeakNpcId = 210032,
          Subtitle = "The Scourge of Zhuyin has been escalating recently. Some Starweavers, unwilling to abide by the lockdown, bypassed EverSpring and hired outside escorts to brave the danger on their own.",
          TalkActionId = {
            [1] = "210032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E1108AA"
        },
        [12010306] = {
          Content = "结果找来了个品行不端的，就有了现在这个结果。",
          DialogueId = 12010306,
          GUID = "1E1108D4",
          NextDialogue = 12010307,
          SpeakNpcId = 210032,
          Subtitle = "But they didn't bother to check the character of those they hired — and so, we ended up with this situation.",
          VoiceName = "voice/$Locale$/story/1201/120103/1E1108D4"
        },
        [12010307] = {
          Camera = "-24.557076,-109.239418,131.683594,0.000153,-0.802465,48.999199,50.0,257.290894,false,DoNotOverride,2.8",
          Content = "我赶来前，商人们还在为这事争执不休，吵得百年春前那叫一个沸反盈天。恐怕还需要您赶紧出面，从中调解一下。",
          DialogueId = 12010307,
          GUID = "1E1108FE",
          NextDialogue = 12010308,
          SpeakNpcId = 210032,
          Subtitle = "Before I left, the merchants were still in a heated argument, shouting up a storm outside EverSpring. I'm afraid you'll be needed to calm them down, Miss Zhiliu.",
          VoiceName = "voice/$Locale$/story/1201/120103/1E1108FE"
        },
        [12010308] = {
          Content = "嗯，大致情况我了解了。",
          DialogueId = 12010308,
          FacialId = {
            [1] = "210004:None"
          },
          GUID = "1E110928",
          NextDialogue = 12010309,
          SpeakNpcId = 210004,
          Subtitle = "I see.",
          TalkActionId = {
            [1] = "210032:Explain02_End",
            [2] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110928"
        },
        [12010309] = {
          Camera = "-158.883514,-85.465759,136.083008,0.000155,-2.202388,31.597618,50.0,257.290894,false,DoNotOverride,2.8",
          Content = "抱歉，{nickname}……总有这些事务缠身。看来能陪伴你的时间已经结束了。",
          DialogueId = 12010309,
          FacialId = {
            [1] = "210004:Smile01"
          },
          FinalCamera = "-143.195038,-56.148727,137.883789,0.000157,-2.602418,27.796841,50.0,257.290894,false,DoNotOverride,2.8",
          GUID = "1E110952",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)",
            [4] = "210003:n(210004)",
            [5] = "210032:n(100001)"
          },
          NextOptions = {
            [1] = 120103091,
            [2] = 120103092
          },
          SpeakNpcId = 210004,
          Subtitle = "My apologies, ... There's always something demanding my attention. It seems our time together must end here.",
          TalkActionId = {
            [1] = "210004:ConfidentR_End"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "210032:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110952"
        },
        [12010310] = {
          Content = "只是，有一件要紧的事尚未交代你们。",
          DialogueId = 12010310,
          FacialId = {
            [1] = "210004:Nervous"
          },
          GUID = "1E11097C",
          NextDialogue = 12010311,
          SpeakNpcId = 210004,
          Subtitle = "There is, however, one last thing I must mention.",
          TalkActionId = {
            [1] = "210004：Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E11097C"
        },
        [12010311] = {
          Camera = "-570.646729,-313.165039,402.481445,0.000143,-22.602468,31.792645,46.756084,257.290894,false,DoNotOverride,2.8",
          Content = "初入华胥者，必须了解<H>九诫</>的内容。若是不慎触犯了大风九章的诫律，或许就落得像刚刚歹人那般的下场。",
          DialogueId = 12010311,
          FinalCamera = "-606.82959,-335.576965,420.213379,0.000143,-22.602468,31.792645,46.756084,257.290894,false,DoNotOverride,2.8",
          GUID = "1E1109A6",
          NextDialogue = 12010312,
          SpeakNpcId = 210004,
          Subtitle = "Anyone new to Huaxu must learn the Nine Admonitions. If you ever break the rules of the Nine Chapters of Dafeng, you may very well meet the same fate as that criminal just now.",
          TalkActionId = {
            [1] = "210004:Talk03ToThink_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120103/1E1109A6"
        },
        [12010312] = {
          Camera = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
          Content = "放心，止流掌柜！我会带他们去看诫碑的，就包在本皎皎身上吧！",
          DialogueId = 12010312,
          FacialId = {
            [1] = "210003:Confident01"
          },
          GUID = "1E1109D0",
          LookAt = {
            [1] = "210004:n(210003)",
            [2] = "100001:n(210003)",
            [3] = "210032:n(210003)",
            [4] = "200002:n(210003)"
          },
          NextDialogue = 12010313,
          SpeakNpcId = 210003,
          Subtitle = "Don't worry, Miss Zhiliu! I'll take them to see the Admonition Stele myself! You can count on me!",
          TalkActionId = {
            [1] = "210004:Think_End",
            [2] = "210003:Excited02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E1109D0"
        },
        [12010313] = {
          Camera = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
          Content = "咦……你们两位已经认识了？",
          DialogueId = 12010313,
          FacialId = {
            [1] = "210004:Doubt01"
          },
          GUID = "1E1109FA",
          LookAt = {
            [1] = "200002:n(210004)"
          },
          NextDialogue = 12010314,
          SpeakNpcId = 210004,
          Subtitle = "Oh...? So the two of you have already met?",
          TalkActionId = {
            [1] = "210004:Explain02_Start",
            [2] = "210003:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E1109FA"
        },
        [12010314] = {
          Camera = "202.094421,-70.305641,138.647461,0.000175,-12.601808,127.792175,50.000008,318.602966,false,DoNotOverride,2.8",
          Content = "这就是光之魔王大人走到哪里散发到哪里的人格魅力！",
          DialogueId = 12010314,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "202.094421,-70.305641,138.647461,0.000182,-12.401793,125.792969,50.000011,318.602966,false,DoNotOverride,2.8",
          GUID = "1E110A24",
          LookAt = {
            [1] = "200002:n(210004)"
          },
          NextDialogue = 12010315,
          SpeakNpcId = 200002,
          Subtitle = "That's just the radiant charisma of this Demon King of Light — people are just drawn to me wherever I go!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120103/1E110A24"
        },
        [12010315] = {
          Content = "这位冰湖城来的魔王大人和本皎皎可是拜把子的交情！我会担起东道主的责任，好好带领他们，让他们宾至如归的！",
          DialogueId = 12010315,
          GUID = "1E110A4E",
          NextDialogue = 12010316,
          SpeakNpcId = 210003,
          Subtitle = "This Demon King from Icelake and I are sworn Lunos! I'll play host and give them a proper tour — make sure they feel right at home!",
          TalkActionId = {
            [1] = "210003:SpecialHappy_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110A4E"
        },
        [12010316] = {
          Camera = "-525.948059,104.858734,227.421875,0.000185,-12.003141,1.202763,50.0,572.522461,false,DoNotOverride,2.8",
          Content = "嗯，你对这片地界熟悉，交给你我却是放心。那你们随后到<H>百年春</>来找我就行。",
          DialogueId = 12010316,
          FacialId = {
            [1] = "210004:Smile01"
          },
          GUID = "1E110A78",
          NextDialogue = 12010317,
          SpeakNpcId = 210004,
          Subtitle = "Good. You're familiar with the area — I trust you with this. Once you're done, come see me at EverSpring.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110A78"
        },
        [12010317] = {
          Camera = "-197.656311,99.099442,143.551758,0.000188,-4.202909,-1.79672,50.000008,572.522461,false,DoNotOverride,2.8",
          Content = "{nickname}，路上注意安全。逛得尽兴了再来即可。先前提到的委托，等你来了，我再把细节交代与你。",
          DialogueId = 12010317,
          FacialId = {
            [1] = "210004:Smile01"
          },
          GUID = "1E110AA2",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "210032:n(100001)",
            [4] = "200002:n(210004)"
          },
          NextDialogue = 12010318,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{210004},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Take care on your way, . Explore at your leisure — there's no rush. When you're ready, come to me, and I shall explain the details of the commission mentioned before.",
          VoiceName = "voice/$Locale$/story/1201/120103/1E110AA2"
        },
        [12010318] = {
          Camera = "221.316528,188.197891,147.143066,0.000172,-5.802731,-150.999084,50.000011,338.357025,false,DoNotOverride,2.8",
          Content = "我明白了。止流掌柜，您快去忙吧！",
          DialogueId = 12010318,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "1E110ACC",
          SpeakNpcId = 100001,
          Subtitle = "Understood, Proprietress Zhiliu. We'll talk later!",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120103/1E110ACC"
        },
        [12010401] = {
          Camera = "1510.199219,3684.390625,1778.458984,0.000038,-13.800717,-84.392624,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "这就是你们说的诫碑了吧，让我瞧瞧——",
          DialogueId = 12010401,
          GUID = "1E11186A",
          NextDialogue = 12010402,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 203002,
            [5] = 405009
          },
          SpeakNpcId = 200002,
          Subtitle = "So this is the stele you were talking about, huh? Lemme take a closer look...",
          VoiceName = "voice/$Locale$/story/1201/120104/1E11186A"
        },
        [12010402] = {
          Camera = "696.953125,-317.017578,277.799805,0.000066,-12.201128,149.811142,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "怎、怎么办，白完全看不懂……",
          DialogueId = 12010402,
          GUID = "1E111894",
          NextDialogue = 12010403,
          SpeakNpcId = 200002,
          Subtitle = "Oh no... I don't understand a single word...",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111894"
        },
        [12010403] = {
          Camera = "-185.355469,366.291016,89.310547,0.00007,1.398802,-55.587837,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "我来给你们翻译——锦鲤皎皎的大风九章小课堂开始！为了在华胥玩得开心，大家一定要认真听哦！",
          DialogueId = 12010403,
          GUID = "1E1118BE",
          NextDialogue = 12010404,
          SpeakNpcId = 210003,
          Subtitle = "Oh, don't worry! I'll give you a crash course in the Nine Chapters! If you want to enjoy your time in Huaxu, you'd better pay attention!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E1118BE"
        },
        [12010404] = {
          Content = "最上面这行是<H>戕身害命，不可为也</>。任何伤害别人的行为在华胥都是绝对禁止的！",
          DialogueId = 12010404,
          GUID = "1E1118E8",
          NextDialogue = 12010405,
          SpeakNpcId = 210003,
          Subtitle = "The top line reads: \"To wound or kill — this must not be done.\" Any act of violence or injury is strictly forbidden in Huaxu!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E1118E8"
        },
        [12010405] = {
          Content = "这条的惩罚最为严重，一定一定要小心哦。不然就会像刚刚看到的坏强盗一样，被一下子定在原地，化作晶尘。",
          DialogueId = 12010405,
          GUID = "1E111912",
          NextDialogue = 12010406,
          SpeakNpcId = 210003,
          Subtitle = "This one carries the harshest punishment, so watch yourself! Otherwise, you'll be frozen in place — just like that wicked bandit — and shattered into dust.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111912"
        },
        [12010406] = {
          Content = "哇，这么吓人……",
          DialogueId = 12010406,
          GUID = "1E11193C",
          NextDialogue = 12010407,
          SpeakNpcId = 200002,
          Subtitle = "That's... kinda terrifying.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E11193C"
        },
        [12010407] = {
          Content = "放心，只有坏人才需要害怕啦，好人才不用担心呢！",
          DialogueId = 12010407,
          GUID = "1E111966",
          NextDialogue = 12010408,
          SpeakNpcId = 210003,
          Subtitle = "Relax! Good folk have nothing to fear — only the wicked need worry.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111966"
        },
        [12010408] = {
          Content = "多亏了大风九章，现在的华胥压根就不会有什么战争呀犯罪呀，大家都和睦融融的。我听说外面的世界可不是这样。",
          DialogueId = 12010408,
          GUID = "1E111990",
          NextDialogue = 12010409,
          SpeakNpcId = 210003,
          Subtitle = "Thanks to the Nine Chapters of Dafeng, there's no war or crime here at all. Everyone just lives in peace and harmony. I hear that out in the wider world, it's nothing like this at all.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111990"
        },
        [12010409] = {
          Content = "这倒是。要是在冰湖城，有人犯了事，就只能指望治安署那些趾高气昂的士兵。",
          DialogueId = 12010409,
          GUID = "1E1119BA",
          NextDialogue = 12010410,
          SpeakNpcId = 200002,
          Subtitle = "That's true. Back in Icelake, if someone commits a crime, all we can do is wait around for those stuck-up Security Bureau soldiers to show up.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E1119BA"
        },
        [12010410] = {
          Content = "而且他们很少管卡戎和穷人的事，最后还是得靠我们自己去抓犯人。前几天好不容易遇到一个靠谱的大姐姐，最后还跑掉不干了……",
          DialogueId = 12010410,
          GUID = "1E1119E4",
          NextDialogue = 12010411,
          SpeakNpcId = 200002,
          Subtitle = "But they don't really care about Charons or the poor. Most of the time, we've got to handle things ourselves. A few days ago, we finally met a young officer who actually cared and tried to help, but she quit to seek for a more meaningful life...",
          VoiceName = "voice/$Locale$/story/1201/120104/1E1119E4"
        },
        [12010411] = {
          Content = "华胥这些长得像冰原狼一样的，叫毕、毕什么的威风猛兽，可比冰湖城的治安署靠谱多啦！",
          DialogueId = 12010411,
          GUID = "1E111A0E",
          NextDialogue = 12010412,
          SpeakNpcId = 200002,
          Subtitle = "Compared to our city guards, the Bi... something — I mean those fierce-looking beasties that kinda look like snow wolves — they're way more reliable!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A0E"
        },
        [12010412] = {
          Content = "是狴犴，不要再记错它们的名字了！",
          DialogueId = 12010412,
          GUID = "1E111A38",
          NextOptions = {
            [1] = 120104121,
            [2] = 120104122
          },
          SpeakNpcId = 210003,
          Subtitle = "They're called Bi'an! At least try to remember their name!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A38"
        },
        [12010413] = {
          Content = "当然，狴犴可是天命的使者！",
          DialogueId = 12010413,
          GUID = "1E111A62",
          NextDialogue = 12010415,
          SpeakNpcId = 210003,
          Subtitle = "Uh-huh, they're emissaries of the Mandate of Heaven!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A62"
        },
        [12010414] = {
          Content = "这可不行！狴犴可是天命的使者。",
          DialogueId = 12010414,
          GUID = "1E111A8C",
          NextDialogue = 12010415,
          SpeakNpcId = 210003,
          Subtitle = "No way! They're emissaries of the Mandate of Heaven!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111A8C"
        },
        [12010415] = {
          Content = "这就要说到，为什么有龙氏是大家都很敬仰的存在啦。",
          DialogueId = 12010415,
          GUID = "1E111AB6",
          NextDialogue = 12010416,
          SpeakNpcId = 210003,
          Subtitle = "Anyway, that's exactly why Loongscions are held in such deep respect here in Huaxu.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111AB6"
        },
        [12010416] = {
          Content = "别卖关子啦，快说快说——",
          DialogueId = 12010416,
          GUID = "1E111AE0",
          NextDialogue = 12010417,
          SpeakNpcId = 200002,
          Subtitle = "Don't keep us in suspense — tell us, tell us!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111AE0"
        },
        [12010417] = {
          Content = "一部分有龙氏到了成年左右的时间，会感应天命，被大风九章蒙召，化为狴犴。",
          DialogueId = 12010417,
          GUID = "1E111B0A",
          NextDialogue = 12010418,
          RelatedWikiId = {
            [1] = 303009
          },
          SpeakNpcId = 210003,
          Subtitle = "So, when some Loongscions come of age, they resonate with the Mandate of Heaven. Called by the Nine Chapters of Dafeng, they awaken as Bi'an.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B0A"
        },
        [12010418] = {
          Content = "（嗯？卡戎……<H>成年左右</>？）",
          DialogueId = 12010418,
          DisableMouth = 1,
          GUID = "1E111B34",
          NextDialogue = 12010419,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Huh? Charons who... come of age?)",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B34"
        },
        [12010419] = {
          Content = "再附赠一个知识点，其实狴犴只是大风九章最普通的执法者。",
          DialogueId = 12010419,
          GUID = "1E111B5E",
          NextDialogue = 12010420,
          SpeakNpcId = 210003,
          Subtitle = "Bonus fact — Bi'an are actually the most basic kind of enforcers of the Nine Chapters.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B5E"
        },
        [12010420] = {
          Content = "有一些更厉害的有龙氏，能够直接以人身进入大风九章，作为<H>应天尉</>活动着，代天命威慑躲在暗中的坏人，让他们不敢造次！",
          DialogueId = 12010420,
          GUID = "1E111B88",
          NextDialogue = 12010421,
          RelatedWikiId = {
            [1] = 405010
          },
          SpeakNpcId = 210003,
          Subtitle = "Some truly exceptional Loongscions can even enter the Nine Chapters in their human form, serving as Magistrates of Yingtian. By the name of the Mandate of Heaven, they strike fear into any evildoers lurking in the shadows and keep them in check!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111B88"
        },
        [12010421] = {
          Content = "对于那种非常棘手的坏人，应天尉就会出动，将他们缉拿，威风凛凛！",
          DialogueId = 12010421,
          GUID = "1E111BB2",
          NextDialogue = 12010422,
          SpeakNpcId = 210003,
          Subtitle = "And if someone is evil enough to ignore even that... the Magistrates of Yingtian will show up with style and overwhelming presence, taking the bad guys down!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111BB2"
        },
        [12010422] = {
          Content = "不过……当然还是希望你们永远不要遇到应天尉！",
          DialogueId = 12010422,
          GUID = "1E111BDC",
          NextDialogue = 12010423,
          SpeakNpcId = 210003,
          Subtitle = "Buuut... let's hope you never have to meet one in person!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111BDC"
        },
        [12010423] = {
          Content = "好啦，对于第一条诫律的解说到此为止！接下来——",
          DialogueId = 12010423,
          GUID = "1E111C06",
          NextDialogue = 12010424,
          SpeakNpcId = 210003,
          Subtitle = "Alright, that wraps up the first Admonition! Now, onto the next—",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C06"
        },
        [12010424] = {
          Content = "眩晕屏幕特效",
          DialogueId = 12010424,
          GUID = "1E111C30",
          NextDialogue = 12010425,
          Subtitle = "The screen shimmers and distorts, a dizzying haze taking over the player's vision",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C30"
        },
        [12010425] = {
          Content = "…………？",
          DialogueId = 12010425,
          GUID = "1E111C5A",
          NextDialogue = 12010426,
          SpeakNpcId = 100001,
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C5A"
        },
        [12010426] = {
          Content = "（总觉得……那块诫碑，像是在<H>呼唤</>我一样……）",
          DialogueId = 12010426,
          DisableMouth = 1,
          GUID = "1E111C84",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That stele... it almost feels like it's... calling to me...)",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111C84"
        },
        [12010427] = {
          Content = "你触摸了诫碑，忽然你的脑内传来了一阵眩晕。",
          DialogueId = 12010427,
          GUID = "1E111CAE",
          Subtitle = "You reach out and touch the stele. Instantly, your mind reels — a voice echoes within your thoughts.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111CAE"
        },
        [12010428] = {
          DialogueId = 12010428,
          GUID = "1E111CD8",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111CD8"
        },
        [12010429] = {
          Camera = "265.414062,55.289062,169.237793,0.000002,-24.800047,-172.198669,11.88,100000.0,false,Manual,2.8",
          Content = "接下来，我要来讲第二条啦！大风九章的第二条即是——",
          DialogueId = 12010429,
          GUID = "1E111D02",
          NextOptions = {
            [1] = 120104291,
            [2] = 120104292
          },
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 405009,
            [5] = 203002
          },
          SpeakNpcId = 210003,
          Subtitle = "Now, onto the next Admonition of the Nine Chapters of Dafeng—",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111D02"
        },
        [12010432] = {
          Content = "完全正确！",
          DialogueId = 12010432,
          GUID = "1E111D80",
          NextDialogue = 12010433,
          SpeakNpcId = 210003,
          Subtitle = "That's exactly right!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111D80"
        },
        [12010433] = {
          Content = "小仆从，你什么时候偷偷学会了华胥文字？白都不知道！",
          DialogueId = 12010433,
          GUID = "1E111DAA",
          NextDialogue = 12010434,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, when did you learn to read Huaxu script!? Even I didn't know you could do that!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111DAA"
        },
        [12010434] = {
          Content = "不，我不认识这些文字……",
          DialogueId = 12010434,
          GUID = "1E111DD4",
          NextDialogue = 12010435,
          SpeakNpcId = 100001,
          Subtitle = "I... don't actually know how to read it.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111DD4"
        },
        [12010435] = {
          Content = "刚刚我靠近诫碑时，脑海里突然冒出来了一个声音，告诉了我这些内容。你知道这是什么情况吗？",
          DialogueId = 12010435,
          GUID = "1E111DFE",
          NextDialogue = 12010436,
          SpeakNpcId = 100001,
          Subtitle = "Just now, when I approached the stele, a voice suddenly spoke in my mind... It told me what the text meant. Do you have any idea what that might be about?",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111DFE"
        },
        [12010436] = {
          Content = "从来没有听说过这种事情……不对，等等！",
          DialogueId = 12010436,
          GUID = "1E111E28",
          NextDialogue = 12010437,
          SpeakNpcId = 210003,
          Subtitle = "I've never heard of anything like that before... Wait a minute!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111E28"
        },
        [12010437] = {
          Content = "有过这样的传说，大风九章的奠基者，也是悬衡派的创始人<H>飏</>，在史书中留下了“天人相感，阴阳相和”的评价。",
          DialogueId = 12010437,
          GUID = "1E111E52",
          NextDialogue = 12010438,
          RelatedWikiId = {
            [1] = 203003
          },
          SpeakNpcId = 210003,
          Subtitle = "There's an old legend that Yang, the founder of the Xuanheng Sect and one of the architects of the Nine Chapters, once wrote these words in the annals of Huaxu history: \"Heaven and man, in perfect accord; yin and yang, in seamless harmony.\"",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111E52"
        },
        [12010438] = {
          Content = "据说，她能够与上天，与世间万物相感应，挟飞仙以遨游！好像和你的情况有点相似。",
          DialogueId = 12010438,
          GUID = "1E111E7C",
          NextDialogue = 12010439,
          SpeakNpcId = 210003,
          Subtitle = "They say she could commune with Heaven and the myriad spirits of the world, even travel among the stars on the wings of the immortals! The way you resonated with the stele sounds a lot like that.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111E7C"
        },
        [12010439] = {
          Content = "正是这位先辈，最后带着很多德高望重的祖先一起，祭献了身躯，化为大风九章流转不息的根基。",
          DialogueId = 12010439,
          GUID = "1E111EA6",
          NextDialogue = 12010440,
          SpeakNpcId = 210003,
          Subtitle = "In the end, Master Yang and many virtuous elders gave up their mortal forms to become the foundation of the Nine Chapters, ensuring it would endure for all time.",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111EA6"
        },
        [12010440] = {
          Content = "白突然有了一个想法！莫非，小仆从就是这位前辈的不知道第几十代曾曾曾曾孙？",
          DialogueId = 12010440,
          GUID = "1E111ED0",
          NextOptions = {
            [1] = 120104401,
            [2] = 120104402
          },
          SpeakNpcId = 200002,
          Subtitle = "I just had a crazy idea! What if... my Little Minion here is actually, like, the umpteenth-generation descendant of that legendary founder!?",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111ED0"
        },
        [12010441] = {
          Content = "诶，是吗？但是{性别：他|她}看着也不像华胥人呢……",
          DialogueId = 12010441,
          GUID = "1E111EFA",
          NextDialogue = 12010443,
          SpeakNpcId = 210003,
          Subtitle = "Uh... really? But {性别:he|she} doesn't look like someone of Huaxu origin...",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111EFA"
        },
        [12010442] = {
          Content = "总而言之，大风九章的内容就是以上这些啦。止流大当家交代我的任务完成了，接下来，我带你们去百年春吧！",
          DialogueId = 12010442,
          GUID = "1E111F24",
          SpeakNpcId = 210003,
          Subtitle = "Anyway! That wraps up the Nine Chapters — mission complete! Now let me take you to EverSpring!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F24"
        },
        [12010443] = {
          Content = "一段时间后……",
          DialogueId = 12010443,
          GUID = "1E111EFB",
          NextDialogue = 12010442,
          Subtitle = "After a while…"
        },
        [12010451] = {
          Content = "跟我来！诫碑在这个方向哦！",
          DialogueId = 12010451,
          Duration = 4,
          GUID = "1E111F26",
          NextDialogue = 12010452,
          SpeakNpcId = 210003,
          Subtitle = "Come on, the Stele's this way!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F26"
        },
        [12010452] = {
          Content = "锦鲤皎皎，他们刚刚提到的烛什么阴之灾……是什么呀？",
          DialogueId = 12010452,
          Duration = 4,
          GUID = "1E111F27",
          NextDialogue = 12010453,
          SpeakNpcId = 200002,
          Subtitle = "Lunocarp, what's that \"Zhu-something\" they were talking about?",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F27"
        },
        [12010453] = {
          Content = "唔，简而言之，就是一个害得大家没法好好做生意的很坏很坏的灾害。",
          DialogueId = 12010453,
          Duration = 4,
          GUID = "1E111F28",
          NextDialogue = 12010454,
          SpeakNpcId = 210003,
          Subtitle = "Hmm, simply put, it's a really, really bad thing that's stopping everyone from doing business properly!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F28"
        },
        [12010454] = {
          Content = "不过你们放心，止流大当家已经在着手解决了！只要大当家一出手，事情都会咻的一下好起来的！",
          DialogueId = 12010454,
          Duration = 4,
          GUID = "1E111F29",
          SpeakNpcId = 210003,
          Subtitle = "But don't worry! Miss Zhiliu is already on it! Whenever she takes charge, things get better, whoosh, just like that!",
          VoiceName = "voice/$Locale$/story/1201/120104/1E111F29"
        },
        [12010500] = {
          Content = "一直听你们说百年春，那里到底是什么样的地方哇？",
          DialogueId = 12010500,
          Duration = 2,
          GUID = "1E1128A8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 12010501,
          SpeakNpcId = 200002,
          Subtitle = "You all keep talking about EverSpring — what's it like?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E1128A8"
        },
        [12010501] = {
          Content = "那可是织星客在烟津渡的最大据点，囊括了来自五湖四海的商品，可气派啦。",
          DialogueId = 12010501,
          Duration = 2,
          GUID = "1E1128D2",
          NextDialogue = 12010502,
          SpeakNpcId = 210003,
          Subtitle = "It's the biggest commercial hub for Starweavers in all of Mistwharf! You can find goods from every corner of the continent there — it's really impressive!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E1128D2"
        },
        [12010502] = {
          Content = "说起来，开旅游团好像也是一门不错的生意经……没错没错，赶紧记在小本本上。",
          DialogueId = 12010502,
          Duration = 2,
          GUID = "1E1128FC",
          SpeakNpcId = 210003,
          Subtitle = "Speaking of which... offering guided tours for foreign visitors sounds like a great business idea... Uh-huh — gotta write that down now!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E1128FC"
        },
        [12010503] = {
          Content = "吼————",
          DialogueId = 12010503,
          Duration = 2,
          GUID = "1E112926",
          NextDialogue = 12010504,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Rrrrroaaaarrrrr—!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112926"
        },
        [12010504] = {
          Content = "（刚刚那是……？）",
          DialogueId = 12010504,
          Duration = 2,
          GUID = "1E112950",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12010505,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(What was that...?)",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112950"
        },
        [12010505] = {
          Content = "糟糕——是玄色狴犴！",
          DialogueId = 12010505,
          Duration = 2,
          GUID = "1E11297A",
          NextDialogue = 12010506,
          SpeakNpcId = 210003,
          Subtitle = "Uh-oh... that was a Sable Bi'an!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E11297A"
        },
        [12010506] = {
          Content = "那是什么？！——诶，人呢？",
          DialogueId = 12010506,
          Duration = 4,
          GUID = "1E1129A4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "A what!? Wait — where did she go!?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E1129A4"
        },
        [12010507] = {
          Content = "咤——走、赶紧走开 ——",
          DialogueId = 12010507,
          Duration = 3,
          GUID = "1E1129CE",
          SpeakNpcId = 210033,
          Subtitle = "Argh—! Run... Run for your lives!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E1129CE"
        },
        [12010508] = {
          Camera = "-2086.416992,-1506.259277,1044.228516,0.000102,-15.798794,37.99028,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "上天庇佑，白龙神君庇佑！你们还好吗？",
          DialogueId = 12010508,
          FinalCamera = "-2543.464355,680.419128,896.21582,0.000097,-15.59871,-11.41056,28.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1129F8",
          LookAt = {
            [1] = "210033:n(100001)"
          },
          NextDialogue = 12010509,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 303008,
            [5] = 303009
          },
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "Heaven and Lord Argent bless us... Are you all alright?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120105/1E1129F8"
        },
        [12010509] = {
          Content = "你还好吗？你的声音都在颤抖……明明自己也怕得要死，怎么还来凑热闹呀！",
          DialogueId = 12010509,
          GUID = "1E112A22",
          NextDialogue = 12010510,
          SpeakNpcId = 200002,
          Subtitle = "Are you okay? Your voice is still shaking... You were clearly pretty scared yourself, and you still came to help us...",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112A22"
        },
        [12010510] = {
          Camera = "-309.597839,264.643616,19.609375,0.000098,-13.798676,-30.610697,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "我并无大碍，只是被那骇人的双目瞪上一眼，腿有点麻，缓缓就好了。但你们看起来是刚来此地的外乡人，不能将你们置之不理。",
          DialogueId = 12010510,
          GUID = "1E112A4C",
          NextOptions = {
            [1] = 120105101,
            [2] = 120105102
          },
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "I'm fine. That beast's terrifying glare shook me a bit. I'll feel better after a short rest. But you seemed new to this place... I couldn't just stand by and leave you in danger.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112A4C"
        },
        [12010511] = {
          Content = "其实你再晚来两步，小仆从唰唰两下就能解决啦，{性别：他|她}很厉害的！",
          DialogueId = 12010511,
          GUID = "1E112A76",
          NextDialogue = 12010512,
          SpeakNpcId = 200002,
          Subtitle = "If you hadn't shown up, my little minion would've taken it down with a few clean strikes~ {性别:He|She}'s super strong!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112A76"
        },
        [12010512] = {
          Content = "这样吗，那太好了……",
          DialogueId = 12010512,
          GUID = "1E112AA0",
          NextDialogue = 12010513,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "I see... I'm glad to hear it.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112AA0"
        },
        [12010513] = {
          Content = "但是，刚刚那是怎么回事？白没认错吧，华胥的执法者怎么突然冒出来攻击我们？！",
          DialogueId = 12010513,
          GUID = "1E112ACA",
          NextDialogue = 12010514,
          SpeakNpcId = 200002,
          Subtitle = "But seriously, what was that!? I wasn't seeing things, was I? Why would one of Huaxu's guardian beasts suddenly attack us!?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112ACA"
        },
        [12010514] = {
          Content = "事先说明，白可没有做什么违法乱纪的坏事——虽然现在说这个好像也已经晚了……",
          DialogueId = 12010514,
          GUID = "1E112AF4",
          NextDialogue = 12010515,
          SpeakNpcId = 200002,
          Subtitle = "For the record — I didn't do anything illegal, okay? Though... I guess at this point it'd be pointless to clarify...",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112AF4"
        },
        [12010515] = {
          Content = "怎、怎么办，小仆从，我们是不是得赶紧潜逃？你的水性怎么样？",
          DialogueId = 12010515,
          GUID = "1E112B1E",
          NextDialogue = 12010516,
          SpeakNpcId = 200002,
          Subtitle = "Wh—What now, Little Minion? Should we run for it? You... you can swim, right?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B1E"
        },
        [12010516] = {
          Content = "噗嗤……烟津渡周围的水域如此广阔，光靠游，一天一夜也游不出几里。",
          DialogueId = 12010516,
          GUID = "1E112B48",
          NextDialogue = 12010517,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "The waters around Mistwharf stretch far and wide. You wouldn't get very far by swimming.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B48"
        },
        [12010517] = {
          Content = "你们不必惊慌。玄色狴犴与狴犴仅仅是外形近似，但它们并非华胥的执法者，而是<H>烛阴之灾</>影响下紊乱失序的产物。",
          DialogueId = 12010517,
          GUID = "1E112B72",
          NextDialogue = 12010518,
          RelatedWikiId = {
            [1] = 303010
          },
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "There's no need to panic. That sable Bi'an may look like the argent ones, but it's not an enforcer of Huaxu. They're aberrations, born from the Scourge of Zhuyin.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B72"
        },
        [12010518] = {
          Content = "这些玄色狴犴神志浑浊暴虐，不受大风九章的控制。攻击它们不会招致责罚。\n",
          DialogueId = 12010518,
          GUID = "1E112B9C",
          NextDialogue = 12010519,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "Mindless and violent, they exist outside the reach of the Nine Chapters of Dafeng. Attacking them doesn't break any law.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112B9C"
        },
        [12010519] = {
          Content = "只是最近这玄色狴犴袭人事件，是愈来愈频发了。我刚刚续上的香，这就又用完了……",
          DialogueId = 12010519,
          GUID = "1E112BC6",
          NextDialogue = 12010520,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "But lately... these attacks have been happening more and more often. The incense I just replaced has already burned down again...",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112BC6"
        },
        [12010520] = {
          Content = "玉笙姐姐！",
          DialogueId = 12010520,
          GUID = "1E112BF0",
          NextDialogue = 12010521,
          SpeakNpcId = 210003,
          Subtitle = "Yusheng!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112BF0"
        },
        [12010521] = {
          Content = "锦鲤皎皎，你怎在此处？",
          DialogueId = 12010521,
          GUID = "1E112C1A",
          NextDialogue = 12010522,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "Lunocarp? What are you doing here?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C1A"
        },
        [12010522] = {
          Content = "这两位是止流大当家从异国带来的贵客，我正在招待他们呢！只是途中发生了一些……咳咳、小变故。",
          DialogueId = 12010522,
          GUID = "1E112C44",
          NextDialogue = 12010523,
          SpeakNpcId = 210003,
          Subtitle = "These two are honoured guests brought here by Miss Zhiliu from a faraway land! I was just showing them around... though we did run into a liiittle situation, hehe...",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C44"
        },
        [12010523] = {
          Content = "玉笙姐姐，你要去百年春前续香吗？我们一起同行吧！",
          DialogueId = 12010523,
          GUID = "1E112C6E",
          NextDialogue = 12010524,
          SpeakNpcId = 210003,
          Subtitle = "Are you heading to EverSpring to replenish your incense? Let's go together!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C6E"
        },
        [12010524] = {
          Content = "<H>香</>？",
          DialogueId = 12010524,
          GUID = "1E112C98",
          NextDialogue = 12010525,
          SpeakNpcId = 100001,
          Subtitle = "Incense?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112C98"
        },
        [12010525] = {
          Content = "说起来，刚刚战斗时，好像有一阵异香飘过，然后仿佛有某种力量，帮我抵挡了对面的攻击……这就是你们说的香吗？",
          DialogueId = 12010525,
          GUID = "1E112CC2",
          NextDialogue = 12010526,
          SpeakNpcId = 100001,
          Subtitle = "Now that you mention it... During the fight just now, I thought I caught a strange, pleasant scent — and then... it felt like something blocked the enemy's attack. Was that the incense you're talking about?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112CC2"
        },
        [12010526] = {
          Content = "确是如此。",
          DialogueId = 12010526,
          GUID = "1E112CEC",
          NextDialogue = 12010527,
          SpeakNpcId = 210033,
          SpeakNpcName = "UI_Npc_CMName_LuGuoXingShang",
          Subtitle = "Yes, that was it.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112CEC"
        },
        [12010527] = {
          Content = "哎呀，原来你们还不知道<H>香</>的妙用，是我这个东道主失职了！",
          DialogueId = 12010527,
          GUID = "1E112D16",
          NextDialogue = 12010528,
          SpeakNpcId = 210003,
          Subtitle = "Ah, so you don't know about the power of incense yet!? My bad for not showing you sooner!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D16"
        },
        [12010528] = {
          Content = "在华胥，香可不仅仅是装饰。它维持着大风九章的运转，也能让我们得到上天的庇佑。",
          DialogueId = 12010528,
          GUID = "1E112D40",
          NextDialogue = 12010529,
          SpeakNpcId = 210003,
          Subtitle = "In Huaxu, incense isn't merely ceremonial — it sustains the Nine Chapters of Dafeng and grants us heavenly protection and blessings.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D40"
        },
        [12010529] = {
          Content = "刚刚，我见你们受袭心急，便将身上佩戴的香囊扔了出去，希望能对你们有所裨益。",
          DialogueId = 12010529,
          GUID = "1E112D6A",
          NextDialogue = 12010530,
          SpeakNpcId = 210033,
          Subtitle = "That's right. So when I saw you under attack, I tossed the sachet I was carrying, hoping it might shield you from harm, even just a little.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D6A"
        },
        [12010530] = {
          Content = "它虽然无法杀伤玄色狴犴，但足以帮我们抵挡一阵子。只是，香的作用发挥之后，必须到白龙祠堂去重新获取赐福。",
          DialogueId = 12010530,
          GUID = "1E112D94",
          NextDialogue = 12010531,
          RelatedWikiId = {
            [1] = 403005
          },
          SpeakNpcId = 210033,
          Subtitle = "Though it can't kill a Sable Bi'an, it can protect us for a time. But once its power fades, we'll have to return to the Argent Loong Temple to receive the blessing anew.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112D94"
        },
        [12010531] = {
          Content = "懂了懂了——也就是去白龙祠堂祈福，我们就不用那么害怕坏狴犴了，对吧！",
          DialogueId = 12010531,
          GUID = "1E112DBE",
          NextDialogue = 12010532,
          RelatedWikiId = {
            [1] = 405011
          },
          SpeakNpcId = 200002,
          Subtitle = "Got it! So as long as we pray at the temple, those mean Bi'an won't be a problem, right?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112DBE"
        },
        [12010532] = {
          Content = "当然，白龙祠堂前的香火可旺盛啦。走吧，带你们一起去见识见识！",
          DialogueId = 12010532,
          GUID = "1E112DE8",
          SpeakNpcId = 210003,
          Subtitle = "Uh-huh! The Argent Loong Temple is always bustling with people coming to renew their incense. Come on, I'll take you there — you've got to see it!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112DE8"
        },
        [12010533] = {
          Content = "喂喂，刚刚打起来之后，你怎么一溜烟地就跑不见了。",
          DialogueId = 12010533,
          GUID = "1E112E12",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12010534,
          SpeakNpcId = 200002,
          Subtitle = "Ahem, so when that beast came at us, how come you vanished so fast?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E12"
        },
        [12010534] = {
          Content = "毕竟我手无缚鸡之力……帮不上什么忙嘛。但是我有在一旁为你们摇旗呐喊哦！",
          DialogueId = 12010534,
          GUID = "1E112E3C",
          NextDialogue = 12010535,
          SpeakNpcId = 210003,
          Subtitle = "Well... I can't be of help in a fight... But I was cheering you on from the sidelines with all my heart! That's serious moral support!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E3C"
        },
        [12010535] = {
          Content = "这样说起来，第一次遇到白的时候，好像也发生过类似的事情呢。",
          DialogueId = 12010535,
          GUID = "1E112E66",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12010536,
          SpeakNpcId = 100001,
          Subtitle = "Speaking of which... Snow did something like that too the first time we met. Didn't you, Snow?",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E66"
        },
        [12010536] = {
          Content = "噗嗤，原来白魔王大人也这么不拘小节。",
          DialogueId = 12010536,
          GUID = "1E112E90",
          NextDialogue = 12010537,
          SpeakNpcId = 210003,
          Subtitle = "Haha, so even the great Demon King has a knack for that.",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112E90"
        },
        [12010537] = {
          Content = "小、小仆从，你不要搞错了，那明明是在考验你的实力……",
          DialogueId = 12010537,
          GUID = "1E112EBA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "L—Little Minion! You've got it all wrong! I was obviously just testing your strength...!",
          VoiceName = "voice/$Locale$/story/1201/120105/1E112EBA"
        },
        [12010601] = {
          Camera = "362.59375,523.266724,128.501953,0.000092,0.196914,-127.178719,35.000011,100000.0,false,Manual,2.8",
          Content = "前面就是啦，位于巨木之根，烟津渡区域规模最大的商会——百年春！",
          DialogueId = 12010601,
          Duration = 4,
          GUID = "1E11393A",
          NextDialogue = 12010602,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 303008
          },
          SpeakNpcId = 210003,
          Subtitle = "There it is — right beneath the roots of the great tree. The largest trading guild in all of Mistwharf — EverSpring!",
          VoiceName = "voice/$Locale$/story/1201/120106/1E11393A"
        },
        [12010602] = {
          Content = "愿此香华云，直达太皓处，恳求大慈悲，施与众生乐。",
          DialogueId = 12010602,
          GUID = "1E113964",
          NextDialogue = 12010603,
          SpeakNpcName = "UI_CMName_Name_DevoutPilgrims",
          Subtitle = "May this incense rise in fragrant clouds to the halls of Heaven. With humble prayer, we seek mercy — to grant peace and joy to all beings.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113964"
        },
        [12010603] = {
          Content = "这么多人在祈愿……白龙神君回应得过来吗？",
          DialogueId = 12010603,
          GUID = "1E11398E",
          NextDialogue = 12010604,
          SpeakNpcId = 200002,
          Subtitle = "So many people making prayers... Can Lord Argent really hear them all?",
          VoiceName = "voice/$Locale$/story/1201/120106/1E11398E"
        },
        [12010604] = {
          Content = "呵呵，<H>奉香</>可不能视为众人向白龙神君进行索取的仪式。",
          DialogueId = 12010604,
          GUID = "1E1139B8",
          NextDialogue = 12010605,
          SpeakNpcId = 210033,
          Subtitle = "Hehe... You mustn't think of incense offerings as a way to demand things from Lord Argent.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E1139B8"
        },
        [12010605] = {
          Content = "先前说过，大风九章需要以“香”为介质去维持运转。",
          DialogueId = 12010605,
          GUID = "1E1139E2",
          NextDialogue = 12010606,
          RelatedWikiId = {
            [1] = 403005
          },
          SpeakNpcId = 210033,
          Subtitle = "As I mentioned before, the Nine Chapters of Dafeng rely on incense as a medium to stay effective.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E1139E2"
        },
        [12010606] = {
          Content = "人们向上天奉香维持着大风九章，大风九章的意志则化形为白龙神君。人们尊奉神君的意志，祂又通过香庇佑人们。",
          DialogueId = 12010606,
          GUID = "1E113A0C",
          NextDialogue = 12010607,
          SpeakNpcId = 210033,
          Subtitle = "People offer incense to the heavens to sustain the Nine Chapters — and in turn, the Nine Chapters manifested Lord Argent, who upholds their will and grants protection through incense.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A0C"
        },
        [12010607] = {
          Content = "愿望要靠勤耕不辍去一步步实现，白龙神君只是见证这一过程，千年皆是如此。",
          DialogueId = 12010607,
          GUID = "1E113A36",
          NextDialogue = 12010608,
          SpeakNpcId = 210033,
          Subtitle = "Wishes come true only through tireless effort, one step at a time. Lord Argent simply bears witness to that journey, as it has for centuries.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A36"
        },
        [12010608] = {
          Content = "不过，偶尔也会出现几位福星，能够得到白龙神君的青睐，获得意想不到的好处呢。",
          DialogueId = 12010608,
          GUID = "1E113A60",
          NextDialogue = 12010609,
          SpeakNpcId = 210033,
          Subtitle = "Though... on rare occasions, a few blessed souls do catch Lord Argent's eye and are granted unexpected fortune.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A60"
        },
        [12010609] = {
          Content = "哎？白有点好奇。来都来了，白也想体验一下！",
          DialogueId = 12010609,
          GUID = "1E113A8A",
          NextDialogue = 12010610,
          SpeakNpcId = 200002,
          Subtitle = "Huh? Now I'm curious. Since we're here already, I wanna give it a try too!",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113A8A"
        },
        [12010610] = {
          Content = "那，你去找香案边上的那位！他是<H>悬衡派</>的香官，负责主持祠堂的秩序。",
          DialogueId = 12010610,
          GUID = "1E113AB4",
          NextDialogue = 12010611,
          RelatedWikiId = {
            [1] = 407006
          },
          SpeakNpcId = 210003,
          Subtitle = "Sure thing. Just head over to the table by the incense altar. That man over there is an incense warden from the Xuanheng Sect — he's in charge of keeping the shrine in order.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113AB4"
        },
        [12010611] = {
          Content = "悬衡派……你好像说过，是那位“天人相感”的大风九章奠基者开创的门派？",
          DialogueId = 12010611,
          GUID = "1E113ADE",
          NextDialogue = 12010612,
          SpeakNpcId = 100001,
          Subtitle = "The Xuanheng Sect? That name rings a bell... They were founded by the same person who could commune with Heaven — the founder of the Nine Chapters, right?",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113ADE"
        },
        [12010612] = {
          Content = "没错！看来{nickname}有认真听课，我很欣慰哦。",
          DialogueId = 12010612,
          GUID = "1E113B08",
          NextDialogue = 12010613,
          SpeakNpcId = 210003,
          Subtitle = "That's right! Looks like  was paying attention during my crash course — gold star for you!",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B08"
        },
        [12010613] = {
          Content = "在上古时期，悬衡派最先发现了香的神奇功效，并作为独门秘方一直传承了下来。",
          DialogueId = 12010613,
          GUID = "1E113B32",
          NextDialogue = 12010614,
          SpeakNpcId = 210003,
          Subtitle = "Back in ancient times, the Xuanheng Sect were the first to uncover the divine power of incense — and they've guarded that secret ever since.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B32"
        },
        [12010614] = {
          Content = "直至今日，悬衡派也一直负责着华胥境内的奉香事宜。一路上看到的香炉都是他们的手笔。",
          DialogueId = 12010614,
          GUID = "1E113B5C",
          NextDialogue = 12010615,
          SpeakNpcId = 210003,
          Subtitle = "Even today, they're in charge of everything related to incense in Huaxu. Every censer you've seen along the way? All made by their hand.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B5C"
        },
        [12010615] = {
          Content = "每人每天能找悬衡派的官员无偿领取三支香。你们也去试试看吧！",
          DialogueId = 12010615,
          GUID = "1E113B86",
          SpeakNpcId = 210003,
          Subtitle = "And everyone can receive three sticks of incense per day for free from their incense wardens. Why not go try it for yourselves?",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113B86"
        },
        [12010616] = {
          Content = "愿你善根常驻。",
          DialogueId = 12010616,
          GUID = "1E113BB0",
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210034},AnimationId{"Pray_Start"},Duration{1.83}},
PlayAnimation{ActorId{210034},AnimationId{"Pray_Loop"},Duration{1}},
PlayAnimation{ActorId{210034},AnimationId{"Pray_End"},Duration{1.87}}
}]],
          SpeakNpcId = 210034,
          Subtitle = "May your virtue endure for all time.",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113BB0"
        },
        [12010617] = {
          Content = "来，最后一段路啦！",
          DialogueId = 12010617,
          Duration = 2,
          GUID = "1E113BDA",
          SpeakNpcId = 210003,
          Subtitle = "Almost there!",
          VoiceName = "voice/$Locale$/story/1201/120106/1E113BDA"
        },
        [12010701] = {
          Camera = "520.380859,617.213379,-28.979492,0.000073,13.797665,-129.582932,35.000008,100000.0,false,Manual,2.8",
          Content = "前面就是百年春的办事处！止流大当家现在估计就在上面等着你们呢。我就带路到这里了，你们自己上去吧。",
          DialogueId = 12010701,
          GUID = "1E1149A2",
          NextDialogue = 12010702,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 406004
          },
          SpeakNpcId = 210003,
          Subtitle = "That's EverSpring's guild hall just up ahead! Miss Zhiliu is probably waiting for you upstairs. Alright, my job here is done — you can head up on your own!",
          VoiceName = "voice/$Locale$/story/1201/120107/1E1149A2"
        },
        [12010702] = {
          Camera = "325.501953,283.450684,112.541016,0.000078,0.797322,-149.78244,35.000008,100000.0,false,Manual,2.8",
          Content = "我的铺位在这里，有空要来找我玩哦。如果想买什么，给你们打九九九八折！",
          DialogueId = 12010702,
          GUID = "1E1149CC",
          NextDialogue = 12010703,
          SpeakNpcId = 210003,
          Subtitle = "My stall's right here — drop by if you've got time! I'll even give you a special 0.02% discount on anything you buy!",
          VoiceName = "voice/$Locale$/story/1201/120107/1E1149CC"
        },
        [12010703] = {
          Content = "等等——多少？我没听错吧？怎么这么小气！",
          DialogueId = 12010703,
          GUID = "1E1149F6",
          NextDialogue = 12010704,
          SpeakNpcId = 200002,
          Subtitle = "Wait... what!? 0.02%!? You're such a cheapskate!",
          VoiceName = "voice/$Locale$/story/1201/120107/1E1149F6"
        },
        [12010704] = {
          Content = "毕竟约定过了，要成为华胥第一的织星客嘛！",
          DialogueId = 12010704,
          GUID = "1E114A20",
          NextDialogue = 12010705,
          SpeakNpcId = 210003,
          Subtitle = "Well, I'm striving to become Huaxu's number-one Starweaver!",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A20"
        },
        [12010705] = {
          Content = "锦鲤皎皎没有角，已经输在起跑线上了。如果不加倍地投机取巧，锱铢必较，勤能补拙，是达不到这个目标的！",
          DialogueId = 12010705,
          GUID = "1E114A4A",
          NextDialogue = 12010706,
          SpeakNpcId = 210003,
          Subtitle = "I don't have horns like you, so I'm already starting behind the line. If I don't double down on seizing every chance and being meticulous, sheer hard work won't get me there!",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A4A"
        },
        [12010706] = {
          Content = "原、原来是这样吗……",
          DialogueId = 12010706,
          GUID = "1E114A74",
          NextDialogue = 12010707,
          SpeakNpcId = 200002,
          Subtitle = "Huh? I—I see...",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A74"
        },
        [12010707] = {
          Content = "让你到处带坏别的皎皎，这下知道错了吧。",
          DialogueId = 12010707,
          GUID = "1E114A9E",
          NextDialogue = 12010708,
          SpeakNpcId = 100001,
          Subtitle = "See? That's what happens when you go around horn-chatting with other Lunos.",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114A9E"
        },
        [12010708] = {
          Content = "咳咳……小仆从，我们赶紧走吧，别让金主大人久等了！",
          DialogueId = 12010708,
          GUID = "1E114AC8",
          SpeakNpcId = 200002,
          Subtitle = "A—Anyway! Let's go, Little Minion — we don't want to keep our big benefactor waiting!",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114AC8"
        },
        [12010709] = {
          Camera = "-10.451172,-172.71875,172.462891,0.000043,-13.01181,100.396614,24.0,100000.0,false,Manual,22.0",
          Content = "……适才情绪激动，如今冷静下来仔细想想，确是我做得不妥了。",
          DialogueId = 12010709,
          FacialId = {
            [1] = "210006:CM_Sad01"
          },
          GUID = "1E114AF2",
          LookAt = {
            [1] = "210005:n(210006)",
            [2] = "210033:n(210006)"
          },
          NextDialogue = 12010710,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 406004
          },
          SpeakNpcId = 210005,
          Subtitle = "...I lost my voice earlier. Now that I've calmed down and thought it over, I realise I was in the wrong.",
          TalkActionId = {
            [1] = "210006:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114AF2"
        },
        [12010710] = {
          Content = "实在是我病急乱投医，昏了头才会从外面雇来个底细不清的人，还想凭一己之力闯一闯，将货物运到对面去。",
          DialogueId = 12010710,
          GUID = "1E114B1C",
          NextDialogue = 12010711,
          SpeakNpcId = 210005,
          Subtitle = "I shouldn't have acted out of desperation and hired some shady outsider to transport my goods on my own.",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B1C"
        },
        [12010711] = {
          Camera = "-23.115234,32.113281,166.745117,0.000075,-7.412141,88.993202,35.0,100000.0,false,Manual,22.0",
          Content = "结果那武人是个花架子，非但应付不来玄色狴犴，还是个心术不正、鸡鸣狗盗之徒，平白惹出这么多事端。我在这里给乡亲父老们赔礼了！",
          DialogueId = 12010711,
          GUID = "1E114B46",
          LookAt = {
            [1] = "210006:n(210005)"
          },
          NextDialogue = 12010712,
          SpeakNpcId = 210005,
          Subtitle = "Who would've thought that man was all talk and no substance — not only useless against a Sable Bi'an, but also a despicable thug who stirred up more trouble than I could imagine... To all my fellow traders — I owe you a deep apology.",
          TalkActionId = {
            [1] = "210006:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B46"
        },
        [12010712] = {
          Camera = "142.71875,232.458008,189.438477,0.000114,-18.212145,-157.608566,24.0,100000.0,false,Manual,22.0",
          Content = "您也不必如此自责。大家这些天心急如焚，百年春都看在眼里。",
          DialogueId = 12010712,
          GUID = "1E114B70",
          LookAt = {
            [1] = "210005:n(210033)",
            [2] = "210006:n(210033)"
          },
          NextDialogue = 12010713,
          SpeakNpcId = 210022,
          Subtitle = "You don't need to be so hard on yourself. These past few days, everyone's been anxious — EverSpring understands this well.",
          TalkActionId = {
            [1] = "210033:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B70"
        },
        [12010713] = {
          Content = "目前我们也在积极寻找对策，早日化解当下的危机，让大家的生意可以重回正轨。",
          DialogueId = 12010713,
          GUID = "1E114B9A",
          NextDialogue = 12010714,
          SpeakNpcId = 210022,
          Subtitle = "We're already working on solutions. The sooner we weather this crisis, the sooner trade and commerce will return to normal.",
          TalkActionId = {
            [1] = "210033:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114B9A"
        },
        [12010714] = {
          Camera = "-47.478516,-40.796875,121.547852,0.000145,2.387158,110.985695,35.0,100000.0,false,Manual,22.0",
          Content = "只是，这禁行令还要延续多久呢？我们织星客等得起，货可等不起啊……",
          DialogueId = 12010714,
          FacialId = {
            [1] = "210005:Unacceptable01"
          },
          GUID = "1E114BC4",
          LookAt = {
            [1] = "210006:n(210005)",
            [2] = "210033:n(210005)"
          },
          NextDialogue = 12010715,
          RelatedWikiId = {
            [1] = 407007
          },
          SpeakNpcId = 210006,
          Subtitle = "But how long is this lockdown going to last? We Starweavers can wait, but our goods sure can't...",
          TalkActionId = {
            [1] = "210005:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114BC4"
        },
        [12010715] = {
          Content = "这个时节的药草，要趁刚摘下来，还沾着露水的新鲜劲，才能卖出个好价钱。放在篮子里，那是日日都在贬值啊。",
          DialogueId = 12010715,
          FacialId = {
            [1] = "210005:CM_Idle"
          },
          GUID = "1E114BEE",
          NextDialogue = 12010716,
          SpeakNpcId = 210006,
          Subtitle = "Fresh herbs only sell for a good price when they're still dewy from the picking — they lose value by the day just sitting around.",
          VoiceName = "voice/$Locale$/story/1201/120107/1E114BEE"
        },
        [12010716] = {
          Camera = "-53.175781,137.40918,147.086914,0.000151,-8.01328,-123.215157,35.0,100000.0,false,Manual,22.0",
          Content = "这……烛阴之灾肆虐。它何时能偃旗息鼓，恐怕没人能给出承诺。",
          DialogueId = 12010716,
          FacialId = {
            [1] = "210033:CM_Sad01"
          },
          GUID = "1E114C18",
          NextDialogue = 12010717,
          SpeakNpcId = 210022,
          Subtitle = "That's... hard to say. With the Scourge of Zhuyin still raging... no one can promise when it'll end.",
          TalkActionId = {
            [1] = "210005:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114C18"
        },
        [12010717] = {
          Camera = "257.292969,-47.435547,8.095703,0.000389,-3.810276,90.187614,35.0,100000.0,false,Manual,22.0",
          Content = "——放心，最多三日，必有解法。",
          DialogueId = 12010717,
          FacialId = {
            [1] = "210033:CM_Idle",
            [2] = "210005:CM_Idle",
            [3] = "210006:CM_Idle"
          },
          FinalCamera = "257.292969,-47.435547,8.095703,0.000394,-5.410247,120.785744,35.0,100000.0,false,Manual,22.0",
          GUID = "1E114C42",
          LookAt = {
            [1] = "210005:n(210004)",
            [2] = "210033:n(210004)",
            [3] = "210006:n(210004)",
            [4] = "210004:n(210005)"
          },
          NextDialogue = 12010718,
          Scripts = [[
PARA{
MoveTo{ActorId{210004},MoveSpeed{90},TargetPoint{"zhiliu_walkin_14"}},
SetRotation{SetRotationDescription{"210005:n(210004)"}},
SetRotation{SetRotationDescription{"210006:n(210004)"}},
SetRotation{SetRotationDescription{"210033:n(210004)"}},
SEQ{
CameraMoveTo{_delay{1},TargetPosition{"-335.083984,163.441406,56.609375,0.000274,-3.011751,-7.796738,24.0,100000.0,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"-335.083984,163.441406,56.609375,0.000274,8.988139,-7.595475,24.0,100000.0,false,Manual,22.0"},duration{1.5}},
}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Three days — no more. There shall be a solution.",
          ToFinalCameraBlendTime = 1.5,
          VoiceName = "voice/$Locale$/story/1201/120107/1E114C42"
        },
        [12010718] = {
          Camera = "-335.083984,163.441406,56.609375,0.000274,8.988139,-7.595475,24.0,100000.0,false,Manual,22.0",
          Content = "止流大当家，您回来了！",
          DialogueId = 12010718,
          GUID = "1E114C6C",
          LookAt = {
            [1] = "210004:n(210033)"
          },
          NextDialogue = 12010719,
          SpeakNpcId = 210022,
          Subtitle = "Miss Zhiliu — you've returned!",
          TalkActionId = {
            [1] = "210033:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114C6C"
        },
        [12010719] = {
          Content = "听您刚刚话中的意思……您找到办法了？",
          DialogueId = 12010719,
          GUID = "1E114C96",
          LookAt = {
            [1] = "210004:n(210006)"
          },
          NextDialogue = 12010720,
          SpeakNpcId = 210006,
          Subtitle = "You mean... you've found a solution?",
          TalkActionId = {
            [1] = "210006:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114C96"
        },
        [12010720] = {
          Content = "嗯，我这趟出门，正是为此。目前算是有些眉目了。",
          DialogueId = 12010720,
          GUID = "1E114CC0",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010721,
          SpeakNpcId = 210004,
          Subtitle = "That was the purpose of my trip. And yes, I've found a lead.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114CC0"
        },
        [12010721] = {
          Camera = "-77.384766,173.716797,147.136719,0.000315,-7.212358,-15.157565,24.0,175.226349,false,Manual,3.0",
          Content = "你们也不必心焦。对于那些有时效性的货物，百年春愿意出市价八折收购。无论货物多少，照单全收。",
          DialogueId = 12010721,
          GUID = "1E114CEA",
          NextDialogue = 12010722,
          SpeakNpcId = 210004,
          Subtitle = "Rest assured. For goods with expiration concerns, EverSpring will purchase them at eighty percent of market price. We'll take it all, no matter how much.",
          TalkActionId = {
            [1] = "210004:Think_Start",
            [2] = "210033:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114CEA"
        },
        [12010722] = {
          Content = "考虑到途中的运输损耗、以及分销的资金回转周期，这应当是个相当公道的价格。",
          DialogueId = 12010722,
          GUID = "1E114D14",
          LookAt = {
            [1] = "210004:n(210005)"
          },
          NextDialogue = 12010723,
          SpeakNpcId = 210004,
          Subtitle = "Considering transport losses and turnaround costs, I believe this is a fair offer.",
          TalkActionId = {
            [1] = "210004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114D14"
        },
        [12010723] = {
          Camera = "108.34375,-30.554688,146.777344,0.000405,-14.413454,127.619759,14.0,175.226349,false,Manual,22.0",
          Content = "烛阴之灾的影响结束后，如果你们有意，可以用同样的价格购回。",
          DialogueId = 12010723,
          GUID = "1E114D3E",
          NextDialogue = 12010724,
          SpeakNpcId = 210004,
          Subtitle = "Once the Scourge has passed, if you wish, you may buy them back at the same price.",
          TalkActionId = {
            [1] = "210004:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114D3E"
        },
        [12010724] = {
          Camera = "-25.605469,65.655273,156.426758,0.000454,-11.014889,15.216454,35.000008,175.226349,false,Manual,22.0",
          Content = "倘若有人还想雇佣护卫，自行闯荡，百年春不会拦着。",
          DialogueId = 12010724,
          GUID = "1E114D68",
          NextDialogue = 12010725,
          SpeakNpcId = 210004,
          Subtitle = "Of course, if anyone still wishes to hire their own escort and test their luck, EverSpring will not stand in your way.",
          TalkActionId = {
            [1] = "210006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114D68"
        },
        [12010725] = {
          Camera = "62.994141,74.545898,142.055664,0.00016,-16.819853,47.249294,24.0,59.213684,false,Manual,22.0",
          Content = "若是雇来了些下三滥的货色，触犯了诫律，不用百年春禁止，狴犴自会出手。到时候万一人财两空，可别怪我没把话说在前头。",
          DialogueId = 12010725,
          GUID = "1E114D92",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010726,
          SpeakNpcId = 210004,
          Subtitle = "But should you bring in a disreputable lot who violate the Admonitions of the Nine Chapters... EverSpring may not intervene — but the Bi'an certainly will. And if it all ends in ruin — lives and fortunes both lost — do not say I did not forewarn you.",
          TalkActionId = {
            [1] = "210004:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114D92"
        },
        [12010726] = {
          Camera = "101.078125,42.186523,136.551758,0.000141,-1.41695,124.660164,24.0,59.21368,false,Manual,22.0",
          Content = "不敢不敢，已经吃到教训了……",
          DialogueId = 12010726,
          FacialId = {
            [1] = "210005:CM_Shock01"
          },
          GUID = "1E114DBC",
          LookAt = {
            [1] = "210004:n(210005)"
          },
          NextDialogue = 12010727,
          SpeakNpcId = 210005,
          Subtitle = "We won't, Miss Zhiliu! We've learned our lesson...",
          TalkActionId = {
            [1] = "210005:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114DBC"
        },
        [12010727] = {
          Content = "听了您这番话，我们便安心了。这种时候，还得是止流大当家，给大伙儿一颗定心丸啊。",
          DialogueId = 12010727,
          FacialId = {
            [1] = "210006:CM_Smile01"
          },
          GUID = "1E114DE6",
          NextDialogue = 12010728,
          SpeakNpcId = 210006,
          Subtitle = "Your words put our minds at ease, Miss Zhiliu. In times like these, it really takes someone like you to calm the waters.",
          TalkActionId = {
            [1] = "210006:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114DE6"
        }
      }
    end
  },
  {
    MinKey = 12010728,
    MaxKey = 12012604,
    Loader = function()
      return {
        [12010728] = {
          Camera = "-335.083984,163.441406,56.609375,0.000274,8.988139,-7.595475,24.0,100000.0,false,Manual,22.0",
          Content = "你们近日担惊受怕，都辛苦了。若无其他要事，先回去休整一下，静候佳音吧。",
          DialogueId = 12010728,
          GUID = "1E114E10",
          SpeakNpcId = 210004,
          Subtitle = "You have all borne enough these past days. If there is nothing more urgent, take some time to rest — and await good news.",
          TalkActionId = {
            [1] = "210004:Talk03_End",
            [2] = "210006:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120107/1E114E10"
        },
        [12010801] = {
          Camera = "304.855316,544.535767,34.631836,0.000097,7.994593,-130.562805,50.0,100000.0,false,Manual,22",
          Content = "你们来了？玩得怎么样？",
          DialogueId = 12010801,
          FinalCamera = "279.991364,515.381226,40.009766,0.000097,7.994593,-129.962708,50.0,100000.0,false,Manual,22",
          GUID = "1E115A0A",
          LookAt = {
            [1] = "100001:n(210004)",
            [2] = "200002:n(210004)"
          },
          NextDialogue = 12010802,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 406004
          },
          SpeakNpcId = 210004,
          Subtitle = "You have come. So — how was your little tour?",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "210004:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A0A"
        },
        [12010802] = {
          Camera = "-683.570435,-204.253418,151.115234,0.000145,-5.40716,26.220837,35.000008,811.822876,false,Manual,6.0",
          Content = "嗯，大家都很热情好客。华胥的风光和人们，都和冰湖城大不一样……",
          DialogueId = 12010802,
          GUID = "1E115A34",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010803,
          SpeakNpcId = 100001,
          Subtitle = "Everyone we met was so nice and welcoming. The sights and people of Huaxu... they're really nothing like Icelake.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A34"
        },
        [12010803] = {
          Content = "刚刚这里发生的事情我们都看到了！不愧是止流姐姐，三下五除二就把那些人摆平了！",
          DialogueId = 12010803,
          GUID = "1E115A5E",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010804,
          SpeakNpcId = 200002,
          Subtitle = "We also saw what happened down here — you calmed all those Starweavers and handled the whole situation with just a few words! You're amazing!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A5E"
        },
        [12010804] = {
          Camera = "-186.132004,148.349823,117.378906,0.000099,12.793374,-73.770279,35.0,167.978699,false,Manual,6.0",
          Content = "呵呵，做生意就是琢磨如何和人打交道。这种小场面，我早就习以为常了。反倒是在冰湖城和你们结交，更为难得。",
          DialogueId = 12010804,
          GUID = "1E115A88",
          NextDialogue = 12010805,
          Scripts = [[
SEQ{
PlayFacial{ActorId{210004},FacialId{"Ahaha01"}},
PlayFacial{_delay{2},ActorId{210004},FacialId{"None"}},
LookAt{LookAtDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Hehe. Business is all about knowing how to deal with people — that's nothing new to me. What's rare... is meeting someone like you.",
          TalkActionId = {
            [1] = "210004:Confident_Start",
            [2] = "200002:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A88"
        },
        [12010805] = {
          Content = "好啦，该切入正题了。我这次雇佣你们，是为了解决<H>烛阴之灾</>而做准备。至于这烛阴之灾是何物……",
          DialogueId = 12010805,
          GUID = "1E115AB2",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010806,
          Scripts = "PlayAnimation{_delay{2},ActorId{210004},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "Now then — let's get to the point. The reason I hired you is to help us prepare for dealing with the Scourge of Zhuyin. As for what that truly is...",
          TalkActionId = {
            [1] = "210004:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115AB2"
        },
        [12010806] = {
          Camera = "-220.036377,-24.106567,165.826172,0.000193,-11.806978,37.620747,25.0,356.590881,false,Manual,6.0",
          Content = "我们已经有所了解啦！",
          DialogueId = 12010806,
          GUID = "1E115ADC",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010807,
          SpeakNpcId = 200002,
          Subtitle = "Oh! We already got a bit of a crash course on that!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115ADC"
        },
        [12010807] = {
          Content = "哦？说来听听。",
          DialogueId = 12010807,
          GUID = "1E115B06",
          NextDialogue = 12010808,
          SpeakNpcId = 210004,
          Subtitle = "Hm? Let's hear it.",
          TalkActionId = {
            [1] = "210004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B06"
        },
        [12010808] = {
          Camera = "-156.516678,87.370865,141.241211,0.000193,-1.207092,50.224213,35.000008,157.917465,false,Manual,6.0",
          Content = "过来的路上，我们遭遇了玄色狴犴的袭击。幸好有位过路的行商相助，我们击退了它，没有受伤。",
          DialogueId = 12010808,
          GUID = "1E115B30",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010809,
          Scripts = [[
SEQ{
PlayFacial{ActorId{100001},FacialId{"Sad01"}},
PlayFacial{_delay{3},ActorId{100001},FacialId{"None"}},
LookAt{LookAtDescription{"100001:n(210004)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "On our way here, we were attacked by a Sable Bi'an. Fortunately, a passing trader helped us out, and we managed to drive it off without getting hurt.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B30"
        },
        [12010809] = {
          Camera = "-77.715431,89.802849,133.813477,0.000236,-18.807245,30.218388,35.000008,141.948105,false,Manual,6.0",
          Content = "行商姐姐告诉我们，就是这个什么烛阴之灾，会诞生很多像玄色狴犴一样的坏东西，然后它们四处咬人，让大家的日子很难过！",
          DialogueId = 12010809,
          FacialId = {
            [1] = "200002:Think02"
          },
          GUID = "1E115B5A",
          NextDialogue = 12010810,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "She told us the Scourge of Zhuyin creates all kinds of nasty beasts like that Sable Bi'an — and they go around biting people and making life miserable!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B5A"
        },
        [12010810] = {
          Camera = "-172.129272,202.076614,182.18457,0.000255,-10.007812,-82.578522,35.0,230.644745,false,Manual,6.0",
          Content = "不错。玄色狴犴出现之前，你们可曾看到或听到什么异象？",
          DialogueId = 12010810,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E115B84",
          NextDialogue = 12010811,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{210004},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "That's about right. Tell me — before the Sable Bi'an emerged, did either of you notice anything out of place?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B84"
        },
        [12010811] = {
          Camera = "-115.231911,95.112503,138.404297,0.000265,2.191896,62.419701,35.000008,144.229248,false,Manual,6.0",
          Content = "好像……从虚空中传来过某种异兽吼叫的声音。",
          DialogueId = 12010811,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E115BAE",
          NextDialogue = 12010812,
          SpeakNpcId = 100001,
          Subtitle = "I think... there was a roar. It came from the void — sounded like some kind of beast.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115BAE"
        },
        [12010812] = {
          Camera = "-62.248718,279.597717,140.96582,0.000271,0.991805,-101.18074,35.0,357.667114,false,Manual,6.0",
          Content = "是了。那便是数载前被封印的恶蛟，如今正在复苏中的<H>烛阴</>发出的嘶吼。",
          DialogueId = 12010812,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E115BD8",
          NextDialogue = 12010813,
          RelatedWikiId = {
            [1] = 303011
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{210004},AnimationId{"Talk02_End"},Duration{1}},
}]],
          SpeakNpcId = 210004,
          Subtitle = "Yes... That roar came from Zhuyin, the ancient evil jiaolong once sealed away. It is now stirring from its slumber.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115BD8"
        },
        [12010813] = {
          Content = "烛阴是华胥远古传说中，与白龙神君相敌对的恶神。它失智、狂乱的力量泄露而出，使恶兽横行。部分区域受其影响，也变得草木不生。",
          DialogueId = 12010813,
          FacialId = {
            [1] = "210004:Angry01"
          },
          GUID = "1E115C02",
          NextDialogue = 12010814,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"Talk03_Start"},Duration{1}},
LookAt{LookAtDescription{"210004:n(200002)"}},
LookAt{_delay{3},LookAtDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "According to Huaxu's oldest myths, Zhuyin is the evil foe of Lord Argent. Its mindless, frenzied power seeps into the realm, unleashing vicious beasts wherever it touches. In those tainted places, even plants refuse to grow.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C02"
        },
        [12010814] = {
          Content = "百年之前，在烟津渡区域，烛阴之灾初显端倪。时人只能仓皇应对，损失惨重，集结了众多人力物力才将其降服。",
          DialogueId = 12010814,
          FacialId = {
            [1] = "210004:Think01"
          },
          GUID = "1E115C2C",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010815,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"210004:n(100001)\"}}",
          SpeakNpcId = 210004,
          Subtitle = "About a hundred years ago, the Scourge of Zhuyin was first witnessed at Mistwharf. Back then, the unprepared people of Huaxu only barely managed to contain it — at great cost and heavy loss.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C2C"
        },
        [12010815] = {
          Content = "如今，烛阴再度从封印中复苏。这次，我打算未雨绸缪，早做准备，避免重蹈上次的覆辙。",
          DialogueId = 12010815,
          FacialId = {
            [1] = "210004:Think01"
          },
          GUID = "1E115C56",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010816,
          SpeakNpcId = 210004,
          Subtitle = "Now, Zhuyin is awakening once more. This time, I intend to stay ahead of the disaster, lest we be caught off guard again.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C56"
        },
        [12010816] = {
          Camera = "-186.98848,-7.478424,161.543945,0.000262,-16.208401,29.619329,35.0,357.667114,false,Manual,6.0",
          Content = "哇，对手真的是一条龙耶，魔王大人已经热血沸腾起来了！那需要我和小仆从做什么呢？",
          DialogueId = 12010816,
          FacialId = {
            [1] = "210004:None"
          },
          GUID = "1E115C80",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010817,
          SpeakNpcId = 200002,
          Subtitle = "Wow... fighting against a real loong! The Demon King is fired up already! So — what do you need us to do?",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C80"
        },
        [12010817] = {
          Camera = "-159.628098,156.141693,211.294922,0.000275,-23.008387,-83.780457,35.000008,179.894089,false,Manual,6.0",
          Content = "华胥禁武。纵是走南闯北的织星客，也少有人精通防身的一招半式。",
          DialogueId = 12010817,
          GUID = "1E115CAA",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010818,
          SpeakNpcId = 210004,
          Subtitle = "Combats are forbidden in Huaxu. Even the most well-travelled Starweavers know little of how to defend themselves.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_End",
            [2] = "200002:Excited01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115CAA"
        },
        [12010818] = {
          Content = "所以，这次我要委托你们的，便是孤身深入已彻底浊化的尘漠石海，将其中的<W>三片烛阴鳞</>取来，好为重新封印这个孽兽做准备。",
          DialogueId = 12010818,
          GUID = "1E115CD4",
          NextDialogue = 12010819,
          RelatedWikiId = {
            [1] = 301007
          },
          SpeakNpcId = 210004,
          Subtitle = "That is why I am entrusting you with this commission: you shall go alone into the tainted wastes of the Gritblight Expanse, and secure for me three Zhuyin Scales — for they are essential to the sealing ritual.",
          TalkActionId = {
            [1] = "210004:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115CD4"
        },
        [12010819] = {
          Camera = "-199.111633,-43.304016,157.180664,0.000239,-5.408567,52.814674,35.000008,332.602295,false,Manual,6.0",
          Content = "止流掌柜，可以问您一个问题吗？",
          DialogueId = 12010819,
          GUID = "1E115CFE",
          NextDialogue = 12010820,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, may I ask you something?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115CFE"
        },
        [12010820] = {
          Content = "这么重要的任务，您为何放心交给我一个名不经传的外来者去完成？",
          DialogueId = 12010820,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E115D28",
          NextDialogue = 12010821,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk02_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "This commission... it sounds incredibly important. Why entrust it to an outsider like me?",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115D28"
        },
        [12010821] = {
          Camera = "-105.761864,145.154953,174.711914,0.00001,-19.008606,49.811211,35.0,101.71228,false,Manual,6.0",
          Content = "我只是一个涉世未深的狩月人。比我身手更好的想必还有很多。",
          DialogueId = 12010821,
          GUID = "1E115D52",
          NextDialogue = 12010822,
          SpeakNpcId = 100001,
          Subtitle = "I'm just a green Phoxhunter — I'm sure there are many far more skilled than I am.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115D52"
        },
        [12010822] = {
          Content = "那时候在剧院，当我触碰香炉时，烟迹像是被吸引了一样，朝我倾斜……您委托我，和这件事有关系吗？",
          DialogueId = 12010822,
          GUID = "1E115D7C",
          NextDialogue = 12010823,
          SpeakNpcId = 100001,
          Subtitle = "Back at the theatre, when I touched that censer, the smoke shifted towards me... as if it was drawn in. Does that have something to do with why you chose me?",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115D7C"
        },
        [12010823] = {
          Camera = "-22.771553,316.24408,146.336914,0.000276,0.989838,-110.393227,120.000038,348.983032,false,Manual,6.0",
          Content = "……你却是敏锐。",
          DialogueId = 12010823,
          FacialId = {
            [1] = "210004:Zhiliu_SpecialDoubt"
          },
          FinalCamera = "-31.808182,319.469513,146.336914,0.000276,1.189867,-108.592857,120.000038,348.983032,false,Manual,6.0",
          GUID = "1E115DA6",
          NextDialogue = 12010824,
          SpeakNpcId = 210004,
          Subtitle = "...You're indeed perceptive.",
          TalkActionId = {
            [1] = "210004:Talk03ToThink_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120108/1E115DA6"
        },
        [12010824] = {
          Content = "相信有人告诫过你了吧，你的能力很特殊，也很珍贵。而珍贵之物往往会引来觊觎。稍有不慎，就会为持有者招致灾难。",
          DialogueId = 12010824,
          GUID = "1E115DD0",
          NextDialogue = 12010825,
          SpeakNpcId = 210004,
          Subtitle = "I'm sure someone has already warned you — your ability is rare... and precious. And precious things are always coveted. Handle them carelessly, and they only invite disaster.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115DD0"
        },
        [12010825] = {
          Camera = "-135.171982,109.97921,130.675781,0.000303,10.789028,-97.396179,25.000002,108.903717,false,Manual,6.0",
          Content = "烛阴鳞并非常规手段可以采摘。需要一种高浓度活性物质与之共鸣，软化其束缚。",
          DialogueId = 12010825,
          GUID = "1E115DFA",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010826,
          SpeakNpcId = 210004,
          Subtitle = "The Zhuyin Scales cannot be harvested through normal means. They require resonance with a highly concentrated active substance — only then can their bonds be softened for extraction.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115DFA"
        },
        [12010826] = {
          Content = "我此次前往冰湖城，本是为了试试帝国炼金院的高纯度月髓液是否可以生效，却无意间发现了你的存在——弥足珍贵的“和鸣者”。",
          DialogueId = 12010826,
          GUID = "1E115E24",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010827,
          SpeakNpcId = 210004,
          Subtitle = "Originally, I travelled to Icelake to see if the Imperial Alchemy Academy's high-purity Phoxichor might suffice. But by sheer chance, I met you — someone who possesses the priceless power of Resonance.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115E24"
        },
        [12010827] = {
          Camera = "-63.153351,333.275513,163.25,0.000279,-12.610932,-89.191231,18.000004,386.075989,false,Manual,6.0",
          Content = "我需要借助你的能力去软化烛阴鳞。当然，你随时拥有拒绝的权利。一切还是以你的安危为最优先。",
          DialogueId = 12010827,
          GUID = "1E115E4E",
          NextDialogue = 12010828,
          RelatedWikiId = {
            [1] = 203001
          },
          SpeakNpcId = 210004,
          Subtitle = "I need your ability to soften the Zhuyin Scales. Of course, the choice is yours. You may refuse — I would never force you to risk your safety.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115E4E"
        },
        [12010828] = {
          Camera = "-101.410286,105.261276,144.950195,0.000291,0.388911,66.010345,35.000008,115.940376,false,Manual,6.0",
          Content = "不。止流掌柜，感谢您的答案。这个任务，我接下了。",
          DialogueId = 12010828,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E115E78",
          NextDialogue = 12010829,
          SpeakNpcId = 100001,
          Subtitle = "Thank you for telling me all this, Proprietress Zhiliu. I take this commission.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115E78"
        },
        [12010829] = {
          Camera = "-135.763824,120.127022,133.164062,0.000261,7.987448,-98.385017,35.000011,132.596771,false,Manual,6.0",
          Content = "……你有没有想过，我对你伸出援手，或许也是看到了你的价值，从而别有用心？",
          DialogueId = 12010829,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E115EA2",
          NextDialogue = 12010830,
          SpeakNpcId = 210004,
          Subtitle = "...Have you ever considered that the reason I helped you back then might not have been out of kindness, but because I saw your worth... and had my own ulterior motive?",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "210004:Talk03ToTalkR_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115EA2"
        },
        [12010830] = {
          Camera = "-233.40567,-36.296333,167.799805,0.000267,-10.612488,39.615959,25.0,351.067688,false,Manual,6.0",
          Content = "我想过，但这改变不了您帮助过我的事实。况且，我也有自己的私心。",
          DialogueId = 12010830,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "1E115ECC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12010831,
          SpeakNpcId = 100001,
          Subtitle = "Actually, I have. But that doesn't change the fact that you did help me. And I have my own selfish reasons, too.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "210004:Talk03ToTalkR_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115ECC"
        },
        [12010831] = {
          Camera = "-143.548096,187.029388,180.547852,0.000277,-26.612356,2.415056,25.0,173.153748,false,Manual,6.0",
          Content = "我在寻找自己的家人，但我一个人的力量过于渺小。为了达到这个目的，我会抓住一切可以凭借的外力。",
          DialogueId = 12010831,
          GUID = "1E115EF6",
          NextDialogue = 12010832,
          Scripts = "PlayFacial{_delay{1.5},ActorId{200002},FacialId{\"Sad03\"}}",
          SpeakNpcId = 100001,
          Subtitle = "I'm searching for my family. But I'm powerless to do it alone. To reach that goal, I'll cling to any strength I can find.",
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115EF6"
        },
        [12010832] = {
          Content = "如果帮助您可以换取未来某些时刻的援手，我想这是一笔相当划算的交易。",
          DialogueId = 12010832,
          GUID = "1E115F20",
          NextDialogue = 12010833,
          SpeakNpcId = 100001,
          Subtitle = "If helping you means I can count on your help someday... I'd say that's a trade well worth making.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F20"
        },
        [12010833] = {
          Camera = "-51.572311,328.859131,154.874023,0.000277,-4.212703,-99.382347,35.000011,410.635406,false,Manual,6.0",
          Content = "更何况，您当初帮我解围之时，我对您而言只是一个随处可见的路人。您帮了我，我也想为您做点什么。",
          DialogueId = 12010833,
          GUID = "1E115F4A",
          NextDialogue = 12010834,
          SpeakNpcId = 100001,
          Subtitle = "Besides, when we first met at the theatre, you didn't know I had this power. I was just a stranger to you. You didn't have to help me — and yet you did. Now... I want to return that favour.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F4A"
        },
        [12010834] = {
          Camera = "-127.131332,108.307777,133.397461,0.000372,7.585963,-100.998802,25.000006,108.903717,false,Manual,6.0",
          Content = "呵呵……话都被你说尽了，我却没什么可说的了。看来假以时日，你也会成为一个优秀的“商人”。",
          DialogueId = 12010834,
          FacialId = {
            [1] = "210004:Smile03"
          },
          GUID = "1E115F74",
          NextDialogue = 12010835,
          Scripts = "PlayFacial{_delay{3},ActorId{210004},FacialId{\"Smile01\"}}",
          SpeakNpcId = 210004,
          Subtitle = "Hehe... You've covered every perspective. I've nothing to add. Given time, you might just make an excellent \"merchant\" yourself.",
          TalkActionId = {
            [1] = "210004:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F74"
        },
        [12010835] = {
          Content = "在你出发前，那边桌子上有给你准备的盘缠。随意花，不够了再来向我要。",
          DialogueId = 12010835,
          FacialId = {
            [1] = "210004:None"
          },
          GUID = "1E115F9E",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(100001)"
          },
          SpeakNpcId = 210004,
          Subtitle = "Before you leave — there's a pouch on the table. It's for your travelling expenses. Spend it as you see fit. If you run short, feel free to come back for more.",
          TalkActionId = {
            [1] = "210004:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F9E"
        },
        [12010901] = {
          Camera = "276.747314,112.712646,37.357422,0.00115,11.20263,-175.58313,25.0,199.450333,false,Manual,4.0",
          Content = "让白掂量掂量……哇，沉甸甸的钱包，这么多！止流老板太大气了！",
          DialogueId = 12010901,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_FullMoneyBag.T_Guide_Chapter_FullMoneyBag'}",
          GUID = "1E116A72",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(200002)"
          },
          NextDialogue = 12010902,
          Scripts = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Please01_Loop\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Lemme see... Whoa, this pouch is heavy! Miss Zhiliu, you're really generous!",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116A72"
        },
        [12010902] = {
          Camera = "276.747314,112.712646,37.357422,0.00115,11.20263,-175.58313,25.0,199.450333,false,Manual,4.0",
          Content = "只是些小钱罢了。你们放心支配，不必拘谨。",
          DialogueId = 12010902,
          FinalCamera = "276.747314,112.712646,37.357422,0.001156,11.002628,-173.182861,25.0,410.377594,false,Manual,4.0",
          GUID = "1E116A9C",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010903,
          SpeakNpcId = 210004,
          Subtitle = "Just a bit of pocket money. Feel free to use it however you see fit.",
          TalkActionId = {
            [1] = "210004:Explain01_Start"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1201/120109/1E116A9C"
        },
        [12010903] = {
          Camera = "117.907089,99.72242,100.063477,0.001367,9.598478,-161.603653,50.000008,218.943039,false,Manual,4.0",
          Content = "采摘烛阴鳞需要用到<W>某种特制的工具</>，我先前托一些……道上的朋友准备了。",
          DialogueId = 12010903,
          GUID = "1E116AC6",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010904,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1.5},ActorId{210004},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{3.5},ActorId{210004},AnimationId{"Talk03_Start"},Duration{1}},
}]],
          SpeakNpcId = 210004,
          Subtitle = "You'll also need a special tool to collect the Zhuyin Scales. I arranged it through some... connections.",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116AC6"
        },
        [12010904] = {
          Camera = "-91.798035,-58.921486,145.460938,0.001206,-6.398227,74.011063,35.0,283.8638,false,Manual,4.0",
          Content = "但由于玄色狴犴肆虐，通讯断绝，至今还未送来。可能需要你亲自去取。",
          DialogueId = 12010904,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E116AC7",
          NextOptions = {
            [1] = 120109041,
            [2] = 120109042
          },
          SpeakNpcId = 210004,
          Subtitle = "But with the Sable Bi'an rampaging, our usual lines of communication were cut off. It still hasn't been delivered. You'll likely have to go and fetch it yourself.",
          TalkActionId = {
            [1] = "200002:Please01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116AC7"
        },
        [12010905] = {
          Camera = "109.405472,216.004333,142.260742,0.001217,-4.798187,-140.989746,35.0,308.470398,false,Manual,4.0",
          Content = "做生意，难免遇到些棘手的事宜，需要交由他人处理。",
          DialogueId = 12010905,
          GUID = "1E116B1A",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010906,
          SpeakNpcId = 210004,
          Subtitle = "In business, there are always... delicate matters best handled by certain \"professionals.\"",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B1A"
        },
        [12010906] = {
          Content = "在华胥，那些见不得光……游走于法理边缘的生意，多在沉船林立的西岸黑市中达成交易。你去那里，找一位叫做虬先生的人，他会交代你后续的步骤。",
          DialogueId = 12010906,
          GUID = "1E116B44",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010907,
          RelatedWikiId = {
            [1] = 408012
          },
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{210004},AnimationId{"DisagreeHead"},Duration{1}},
LookAt{_delay{6},LookAtDescription{"210004:n(100001)"}},
}]],
          SpeakNpcId = 210004,
          Subtitle = "Here in Huaxu, the sorts of dealings that prefer to stay in the shadows usually happen at the black market among the shipwrecks on the western shore. Go there and find a man named Mr Qiu. He'll give you your next steps.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B44"
        },
        [12010907] = {
          Camera = "-96.494217,-40.735981,142.348633,0.00132,-4.398792,71.811882,35.000008,236.057159,false,Manual,4.0",
          Content = "你是生面孔，难以取信于他们。",
          DialogueId = 12010907,
          GUID = "1E116B6E",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010908,
          SpeakNpcId = 210004,
          Subtitle = "But you are new faces. They won't trust you right away.",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B6E"
        },
        [12010908] = {
          Camera = "109.405472,216.004333,142.260742,0.001217,-4.798187,-140.989746,35.0,308.470398,false,Manual,4.0",
          Content = "按照规矩，初次造访黑市的人，要从沿海洞窟行出，腰上佩饰特定的挂坠。他们见着这“暗号”对上了，就会知道你是自己人。",
          DialogueId = 12010908,
          GUID = "1E116B98",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010909,
          SpeakNpcId = 210004,
          Subtitle = "By custom, first-time visitors to the black market have to come through the coastal cavern, wearing a special pendant at their waist. If the signal matches, they'll know you're one of ours.",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B98"
        },
        [12010909] = {
          Camera = "-19.247467,268.217834,206.660156,0.001299,-34.998592,-66.185158,35.0,247.601944,false,Manual,4.0",
          Content = "嗯嗯，白和小仆从要扮演危险角色……这感觉对味了！",
          DialogueId = 12010909,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E116BC2",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12010910,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{200002},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Talk01_Start"},Duration{2}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Alright! So my Little Minion and I get to play the badasses this time? That sounds like a job for us!",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116BC2"
        },
        [12010910] = {
          Camera = "57.356339,167.022995,108.945312,0.001361,7.798546,-135.000778,50.000008,218.943039,false,Manual,4.0",
          Content = "你们从百年春的正门出去，往右手边就能遥看到沿海洞窟的入口。这也是通往黑市的捷径。",
          DialogueId = 12010910,
          GUID = "1E116BEC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010911,
          SpeakNpcId = 210004,
          Subtitle = "Exit through EverSpring's main gate and look to the right. In the distance, you'll see the entrance to the coastal cavern — that's a shortcut to the black market.",
          TalkActionId = {
            [1] = "210004:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116BEC"
        },
        [12010911] = {
          Content = "想必不用我再叮嘱什么了……{nickname}，我等着你平安归来。",
          DialogueId = 12010911,
          GUID = "1E116C16",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          Scripts = "LookAt{_delay{4},LookAtDescription{\"210004:n(100001)\"}}",
          SpeakNpcId = 210004,
          Subtitle = "I trust I don't need to say more... I'll be waiting for your safe return, .",
          TalkActionId = {
            [1] = "210004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116C16"
        },
        [12011001] = {
          Content = "沿海洞窟……看来就是前面那里了。",
          DialogueId = 12011001,
          Duration = 2,
          GUID = "1E117ADA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12011002,
          SpeakNpcId = 100001,
          Subtitle = "A coastal cave... looks like that's the place.",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117ADA"
        },
        [12011002] = {
          Content = "白还记得和小仆从第一次探险，也是下洞窟，仿佛就像昨天刚刚发生一样！",
          DialogueId = 12011002,
          Duration = 4,
          GUID = "1E117B04",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12011003,
          SpeakNpcId = 200002,
          Subtitle = "Do you remember our first adventure together, Little Minion? We went down into a cave that time too — it feels like it was just yesterday!",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B04"
        },
        [12011003] = {
          Content = "谁想到转眼间，我们就来到这么远的地方，肩负这么激动人心的大使命——",
          DialogueId = 12011003,
          Duration = 4,
          GUID = "1E117B2E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12011004,
          SpeakNpcId = 200002,
          Subtitle = "And now look at us — all the way out here, so far from home, on some epic, destiny-shaping quest!",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B2E"
        },
        [12011004] = {
          Content = "……嗯。那次遇到了奥特赛德，敲了他一顿竹杠。赛琪……也还在。",
          DialogueId = 12011004,
          Duration = 3,
          GUID = "1E117B58",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12011005,
          SpeakNpcId = 100001,
          Subtitle = "...Yeah. That time we ran into Outsider and kind of... shook him down. And Psyche... was still with us back then.",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B58"
        },
        [12011005] = {
          Content = "白、白说错话了……",
          DialogueId = 12011005,
          Duration = 2,
          GUID = "1E117B82",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 12011006,
          SpeakNpcId = 200002,
          Subtitle = "I—I'm sorry... I didn't mean to upset you...",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B82"
        },
        [12011006] = {
          Content = "没关系。等我们回去，再到泪湖边去，把华胥的见闻说给她听吧。",
          DialogueId = 12011006,
          Duration = 5,
          GUID = "1E117BAC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "It's alright. Once we're back, let's visit Lamenting Lake and tell her everything we've seen in Huaxu.",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117BAC"
        },
        [12011101] = {
          Content = "喂——喂——有人吗？",
          DialogueId = 12011101,
          Duration = 2,
          GUID = "1E118B42",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12011102,
          SpeakNpcId = 200002,
          Subtitle = "Hellooo—! Anyone here?",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118B42"
        },
        [12011102] = {
          Content = "看，小仆从！这里黑布隆冬的，说话还会有回音耶。你会怕黑吗？",
          DialogueId = 12011102,
          Duration = 3,
          GUID = "1E118B6C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12011103,
          SpeakNpcId = 200002,
          Subtitle = "Whoa, it's so pitch black in here! And even our voices echo. Are you scared of the dark, Little Minion?",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118B6C"
        },
        [12011103] = {
          Content = "不怕。但是我们说话声音最好压低些，当心引来什么奇怪的东西。",
          DialogueId = 12011103,
          Duration = 3,
          GUID = "1E118B96",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Not really. But we'd better keep our voices down — no telling what we might attract.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118B96"
        },
        [12011104] = {
          Content = "……哇啊！！",
          DialogueId = 12011104,
          Duration = 2,
          GUID = "1E118BC0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Waaaah!!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118BC0"
        },
        [12011201] = {
          Content = "呸、呸！好的不灵坏的灵，小仆从简直是乌鸦嘴——",
          DialogueId = 12011201,
          Duration = 2,
          GUID = "1E119BAA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12011202,
          SpeakNpcId = 200002,
          Subtitle = "Ugh! Way to go, Little Minion! Thanks for jinxing us and drawing that thing here!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E119BAA"
        },
        [12011202] = {
          Content = "又是玄色狴犴，它们的数量怎么越来越多了！",
          DialogueId = 12011202,
          Duration = 2,
          GUID = "1E119BD4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Another Sable Bi'an... Where do they keep coming from!?",
          VoiceName = "voice/$Locale$/story/1201/120112/1E119BD4"
        },
        [12011301] = {
          Content = "留神——",
          DialogueId = 12011301,
          Duration = 3,
          GUID = "1E11AC12",
          Subtitle = "Watch out—",
          VoiceName = "voice/$Locale$/story/1201/120113/1E11AC12"
        },
        [12011401] = {
          Camera = "189.114975,196.35614,114.457275,0.000174,-10.806698,-159.432999,25.000006,417.040405,false,Manual,22.0",
          Content = "刚刚真是多谢你了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011401,
          FinalCamera = "189.114975,196.35614,114.457275,0.000178,-3.606934,-159.432861,25.000006,417.040405,false,Manual,22.0",
          GUID = "1E11BC7A",
          LookAt = {
            [1] = "210007:n(100001)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011402,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003
          },
          SpeakNpcId = 100001,
          Subtitle = "You saved us — thank you.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BC7A"
        },
        [12011402] = {
          Camera = "-28.935848,42.242939,103.689453,0.000091,5.793749,-179.624237,35.000011,179.031601,false,Manual,6.0",
          Content = "不用，本是职责所在。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011402,
          GUID = "1E11BCA4",
          NextDialogue = 12011403,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "It's okay. I am merely fulfilling my duty.",
          TalkActionId = {
            [1] = "210007:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BCA4"
        },
        [12011403] = {
          Camera = "-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0",
          Content = "……职责所在？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011403,
          FacialId = {
            [1] = "200002:Think02"
          },
          GUID = "1E11BCCE",
          LookAt = {
            [1] = "210007:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011404,
          SpeakNpcId = 200002,
          Subtitle = "...Your duty?",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BCCE"
        },
        [12011404] = {
          Camera = "-65.706345,52.841057,121.108398,0.000078,-25.203888,24.986763,30.000002,118.231079,false,Manual,6.0",
          Content = "唔，是卡戎，还很能打……你该不会是锦鲤皎皎提到的<H>应天尉</>吧？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011404,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E11BCF8",
          LookAt = {
            [1] = "100001:n(210007)"
          },
          NextDialogue = 12011405,
          RelatedWikiId = {
            [1] = 405010
          },
          SpeakNpcId = 200002,
          Subtitle = "Hmm, you're a Charon — and you fight really well... Wait, are you one of those Magistrates of Yingtian that Lunocarp mentioned?",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BCF8"
        },
        [12011405] = {
          Camera = "-17.535795,38.415855,82.101318,0.00012,12.593161,179.576218,35.000011,179.03125,false,Manual,6.0",
          Content = "……我奉命来此肃清玄色狴犴。如今众敌环伺，职责未尽，恕我无暇闲聊。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011405,
          GUID = "1E11BD22",
          NextDialogue = 12011406,
          Scripts = "PlayAnimation{_delay{3},ActorId{210007},AnimationId{\"DisagreeHead\"},Duration{1}},",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...I was assigned to purge the Sable Bi'an here. With danger still looming, my duty remains. I have no time for idle chatter.",
          TalkActionId = {
            [1] = "210007:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BD22"
        },
        [12011406] = {
          Camera = "-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0",
          Content = "奉谁的命？我们等会儿出去好好谢谢人家！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011406,
          GUID = "1E11BD4C",
          NextDialogue = 12011407,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Please01_Start\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Assigned by who? We'll go thank them properly once we're out of here!",
          TalkActionId = {
            [1] = "200002:Excited01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BD4C"
        },
        [12011407] = {
          Camera = "87.904099,67.988495,63.705566,0.000245,7.791149,173.780365,25.000006,308.831635,false,Manual,6.0",
          Content = "大风九章，天命。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011407,
          GUID = "1E11BD76",
          NextDialogue = 12011408,
          Scripts = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Please01_End\"},Duration{1}},",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The Nine Chapters of Dafeng. The Mandate of Heaven.",
          TalkActionId = {
            [1] = "210007:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BD76"
        },
        [12011408] = {
          Content = "对哦，好像确实有这么一回事……那白和小仆从回头要狠狠地奉几根香！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011408,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1E11BDA0",
          NextDialogue = 12011409,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0"},duration{0}},  
PlayAnimation{_delay{2},ActorId{200002},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{_delay{0},ActorId{200002},AnimationId{"Excited02_Start"},Duration{1}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Oh, right — yeah, that's a thing... then we're definitely offering up a lot more incense once we're out!",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BDA0"
        },
        [12011409] = {
          Camera = "-51.653706,32.12328,121.247803,0.000206,-23.807735,39.170685,25.000006,119.064056,false,Manual,6.0",
          Content = "说起来，刚刚续上的香，和玄色狴犴刚打一个照面就用完了。还真是不经用……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011409,
          FacialId = {
            [1] = "200002:Sad03"
          },
          GUID = "1E11BDCA",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 12011410,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"DisagreeHead\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Speaking of which — the incense we just replaced ran out the second we faced that beast. Total rip-off if you ask me...",
          TalkActionId = {
            [1] = "200002:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BDCA"
        },
        [12011410] = {
          Camera = "-65.107132,57.948006,89.911133,0.000238,13.191348,-170.82811,25.000006,142.201553,false,Manual,6.0",
          Content = "若香已散尽，以我一人之力，恐难护得二位周全。二位若无要事，还请速速离去，寻一安稳之所。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011410,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E11BDF4",
          LookAt = {
            [1] = "210007:n(210007)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011411,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0"},duration{0}},
PlayAnimation{_delay{2},ActorId{210007},AnimationId{"DisagreeHead"},Duration{2}}
}]],
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "If your incense has burned out, I may not be able to keep you both safe on my own. If you have no urgent business here, I suggest you leave for safer ground.",
          TalkActionId = {
            [1] = "210007:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BDF4"
        },
        [12011411] = {
          Camera = "-35.692829,-53.15213,91.663574,0.000249,5.190643,81.783882,35.000011,238.308868,false,Manual,6.0",
          Content = "谢谢，不过我们有一点自保能力，不用担心。我们需要去洞窟对面办一件事，希望不会给你添麻烦。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011411,
          GUID = "1E11BE1E",
          LookAt = {
            [1] = "210007:n(100001)"
          },
          NextDialogue = 12011412,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Explain01L_Start\"},Duration{1}},",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but we can protect ourselves. We have something to take care of on the far side of this cave — that's why we came in. I hope we haven't been a bother.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE1E"
        },
        [12011412] = {
          Camera = "77.085526,178.859253,127.048584,0.000261,-3.609953,-158.824905,35.000011,303.13736,false,Manual,6.0",
          Content = "洞窟对面？据我所知，那里除岸滩搁浅的沉船残阙外，别无旁物。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011412,
          FacialId = {
            [1] = "210007:Think01"
          },
          GUID = "1E11BE48",
          NextDialogue = 12011413,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The far side? As far as I know, there's nothing there but some beached wreckage.",
          TalkActionId = {
            [1] = "210007:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE48"
        },
        [12011413] = {
          Camera = "77.085526,178.859253,127.048584,0.000261,-3.609953,-158.824905,35.000011,303.13736,false,Manual,6.0",
          Content = "没错，就是那处沉船黑市！白和小仆从要去那里谈一桩大生意！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011413,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E11BE72",
          NextDialogue = 12011414,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"-228.367401,-38.505424,133.859619,0.00008,-16.40362,35.188114,30.0,306.177948,false,Manual,6.0\"},duration{0}},",
          SpeakNpcId = 200002,
          Subtitle = "Exactly! We're going to the black market among the shipwrecks! We have a big business deal to settle there!",
          TalkActionId = {
            [1] = "210007:Think_End",
            [2] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE72"
        },
        [12011414] = {
          Camera = "15.423389,62.95097,58.172363,0.000279,14.786286,-172.234375,35.000011,215.125885,false,Manual,6.0",
          Content = "黑市、谈生意？两位若非要与鸡鸣狗盗之辈为伍，我也无话可说。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011414,
          FacialId = {
            [1] = "210007:Angry01"
          },
          GUID = "1E11BE9C",
          LookAt = {
            [1] = "210007:n(210007)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011415,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The black market... for business? If you insist on mingling with swindlers and scoundrels, I have nothing more to say.",
          TalkActionId = {
            [1] = "210007:Talk03_Start",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE9C"
        },
        [12011415] = {
          Camera = "-20.366999,-42.464127,13.334961,0.000288,25.588646,77.37146,35.000011,257.516388,false,Manual,14.0",
          Content = "怎、怎么办，小仆从？！我们好像被他误解了……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011415,
          FacialId = {
            [1] = "200002:Shock02"
          },
          GUID = "1E11BEC6",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12011416,
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh... what do we do, Little Minion? He totally misunderstood us...",
          TalkActionId = {
            [1] = "200002:Shock03_Start",
            [2] = "100001:Explain01L_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BEC6"
        },
        [12011416] = {
          Content = "事情不是你想的那样。我们受止流掌柜雇佣，为了解决玄色狴犴肆虐的问题，需要去黑市取一样工具。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011416,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E11BEF0",
          LookAt = {
            [1] = "210007:n(100001)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011417,
          Scripts = "CameraMoveTo{_delay{1},TargetPosition{\"65.418396,174.380295,125.57373,0.000325,-3.813841,-158.644958,35.000011,319.544312,false,Manual,6.0\"},duration{0}},",
          SpeakNpcId = 100001,
          Subtitle = "It's not what you think. We're here on an assignment from Proprietress Zhiliu — to help deal with the Sable Bi'an outbreak. There's a tool we need to retrieve from the black market.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BEF0"
        },
        [12011417] = {
          Camera = "-74.738007,65.379562,128.82251,0.000274,-25.813593,17.363806,35.000011,115.267303,false,Manual,6.0",
          Content = "就是，才不是去做什么偷鸡摸狗的事情呢！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011417,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E11BF1A",
          NextDialogue = 12011418,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Exactly! We're not doing anything shady, thank you very much!",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF1A"
        },
        [12011418] = {
          Camera = "-35.568024,20.937334,182.430664,0.000227,-24.613787,173.365738,35.000011,196.696289,false,Manual,6.0",
          Content = "……抱歉。是我武断了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011418,
          FacialId = {
            [1] = "210007:Sad01"
          },
          GUID = "1E11BF44",
          LookAt = {
            [1] = "210007:n(210007)"
          },
          NextDialogue = 12011419,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...My apologies. It was hasty of me to pass judgement.",
          TalkActionId = {
            [1] = "210007:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF44"
        },
        [12011419] = {
          Content = "话虽如此，黑市之人鱼龙混杂，你们需当心甄别，莫被欺瞒利用了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011419,
          FacialId = {
            [1] = "210007:None"
          },
          GUID = "1E11BF6E",
          NextDialogue = 12011420,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "Still, that place harbours all manner of folk. Beware of deceit and manipulation.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF6E"
        },
        [12011420] = {
          Camera = "189.114975,196.35614,114.457275,0.000178,-3.606934,-159.432861,25.000006,417.040405,false,Manual,22.0",
          Content = "此地不安全，让我护送你们过去吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011420,
          GUID = "1E11BF98",
          Scripts = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Explain02_End\"},Duration{1}},",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "This cavern is not safe. Allow me to escort you across.",
          TalkActionId = {
            [1] = "210007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF98"
        },
        [12011501] = {
          Content = "应天尉就是华胥的卫戍部队吧！你们有工资拿吗，待遇怎么样呀？",
          DialogueId = 12011501,
          Duration = 3,
          GUID = "1E11CCE2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12011502,
          SpeakNpcId = 200002,
          Subtitle = "So, Magistrates of Yingtian are kind of like the Escort of Huaxu, right? Do you guys get paid? Any special perks?",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CCE2"
        },
        [12011502] = {
          Content = "……",
          DialogueId = 12011502,
          Duration = 1,
          GUID = "1E11CD0C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12011503,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD0C"
        },
        [12011503] = {
          Content = "好啦好啦。白知道了，白不问这些了。",
          DialogueId = 12011503,
          Duration = 2,
          GUID = "1E11CD36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12011504,
          SpeakNpcId = 200002,
          Subtitle = "Alright, alright, I get it. I won't pry.",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD36"
        },
        [12011504] = {
          Content = "我为应天尉，只愿济苍生，安黎元，并非为那些身外俗物。",
          DialogueId = 12011504,
          Duration = 2,
          GUID = "1E11CD60",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 12011505,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "As a Magistrate of Yingtian, I serve only to safeguard the people and bring peace to the land. I did not assume this role for worldly gain.",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD60"
        },
        [12011505] = {
          Content = "……小仆从你听，就是不发工资的意思咯？比帝国还抠门！",
          DialogueId = 12011505,
          Duration = 2,
          GUID = "1E11CD8A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Hear that, Little Minion? That means they don't get paid. Guess the higher-ups here are even more tight-fisted than those of the Empire, huh?",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD8A"
        },
        [12011601] = {
          Content = "前方恐有玄色狴犴蛰伏，由我开路。请两位紧随我身后。",
          DialogueId = 12011601,
          Duration = 3,
          GUID = "1E11DD4A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "There may be more Sable Bi'an lurking ahead. I'll take the lead. Please stay close behind me.",
          VoiceName = "voice/$Locale$/story/1201/120116/1E11DD4A"
        },
        [12011701] = {
          Camera = "185.545456,-74.591217,6.828125,0.000015,14.198753,155.402176,14.0,100000.0,false,DoNotOverride,22.0",
          Content = "出口在前方。我便护送两位到这里为止。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011701,
          FinalCamera = "170.985962,-103.135139,6.828125,0.000016,13.998766,151.002472,14.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1E11EDB2",
          NextDialogue = 12011709,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"210007:p(RegionPoint_Cav_Door01)"}},
PARA{
LookAt{LookAtDescription{"100001:p(RegionPoint_Cav_Door01)"}},   
LookAt{LookAtDescription{"200002:p(RegionPoint_Cav_Door01)"}},
LookAt{LookAtDescription{"210007:n(210007)"}}
}
}]],
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The exit lies just ahead. This is where I leave you.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EDB2"
        },
        [12011702] = {
          Camera = "29.643166,-184.535736,100.408203,0.000144,-18.606226,57.386753,25.000006,79.312019,false,Manual,6.0",
          Content = "那家伙，虽然说话冷冰冰的，但是心地还不错嘛。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011702,
          FinalCamera = "29.643166,-184.535736,100.408203,0.000124,7.393843,72.986702,25.000006,257.354767,false,Manual,6.0",
          GUID = "1E11EDDC",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12011703,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},MoveSpeed{120},TargetPoint{"nvzhu_18_leave"}},
MoveTo{ActorId{200002},MoveSpeed{120},TargetPoint{"baitx_18_leave"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "That guy seems kinda aloof... but deep down, he's a good person.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EDDC"
        },
        [12011703] = {
          Camera = "-14.599092,40.482475,216.085449,0.000144,-39.405331,-15.000833,25.000002,208.178604,false,Manual,6.0",
          Content = "不知道仅凭他一个人，能否对付聚集在这山洞中的玄色狴犴。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011703,
          GUID = "1E11EE06",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12011704,
          SpeakNpcId = 100001,
          Subtitle = "Can he really hold off all those Sable Bi'an in the cave on his own...?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EE06"
        },
        [12011704] = {
          Camera = "-14.599092,40.482475,216.085449,0.000144,-39.405331,-15.000833,25.000002,208.178604,false,Manual,6.0",
          Content = "嗷呜——！！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011704,
          Duration = 3.5,
          FacialId = {
            [1] = "200002:Shock02",
            [2] = "100001:Shock01"
          },
          GUID = "1E11EE30",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 12011705,
          Scripts = [[
PARA{
PlayNormalSound{EventPath{"event:/sfx/common/story/east/bian_roar"},PlayAs2D{true}},
CameraShake {FileName {"FixSimple_CameraShake_Normal"} },
CameraMoveTo{_delay{1.5},TargetPosition{"-14.599092,40.482475,216.085449,0.000151,-1.605333,67.199013,25.000002,208.178604,false,Manual,6.0"},duration{1}},
CameraMoveTo{_delay{3},TargetPosition{"308.512939,1111.500488,43.151855,0.000154,6.394587,67.395256,25.000002,208.178604,false,Manual,6.0"},duration{0}},
CameraMoveTo{_delay{3.1},TargetPosition{"330.403259,1164.431274,49.572266,0.000154,6.394587,67.595253,25.000002,208.178604,false,Manual,6.0"},duration{1}},
