          SpeakNpcId = 100001,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Rrrrrrraaaahhh—!!",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EE30"
        },
        [12011705] = {
          Camera = "79.016762,83.664368,179.60791,0.000035,-33.004574,-79.798035,25.000006,153.629883,false,Manual,6.0",
          Content = "喂，小仆从！后面那么大的动静，是怎么回事！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011705,
          GUID = "1E11EE5A",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12011706,
          SpeakNpcId = 200002,
          Subtitle = "Whoa! What was that!? Did you hear it? I think it came from behind us...",
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EE5A"
        },
        [12011706] = {
          Camera = "79.016762,83.664368,179.60791,0.000035,-33.004574,-79.798035,25.000006,153.629883,false,Manual,6.0",
          Content = "听起来，好像是狴犴齐聚的{性别：吼叫|吼声}，数目应该不少。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011706,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "72.705215,125.454636,204.440918,0.000042,-35.404316,-85.197647,25.000006,110.730377,false,Manual,6.0",
          GUID = "1E11EE84",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 12011707,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like a huge pack of Bi'an all howling at once.",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EE84"
        },
        [12011707] = {
          Content = "那、那个，小仆从，我觉得……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011707,
          FacialId = {
            [1] = "200002:Sad03"
          },
          GUID = "1E11EEAE",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(200002)"
          },
          NextDialogue = 12011708,
          Scripts = "CameraMoveTo{_delay{2.3},TargetPosition{\"214.498825,49.772301,145.079102,0.000132,-19.205076,-144.198425,35.000011,147.209549,false,Manual,6.0\"},duration{0}}",
          SpeakNpcId = 200002,
          Subtitle = "Then... do you think maybe we should...?",
          TalkActionId = {
            [1] = "200002:Shy02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EEAE"
        },
        [12011708] = {
          Camera = "1156.068359,2425.400635,987.58252,18.003975,-51.011806,-165.660461,12.0,115.784668,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我明白。黑市晚些去也来得及，先去看看那位应天尉的情况吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011708,
          FinalCamera = "1192.273926,2435.125977,1034.175293,18.004698,-51.211037,-164.861404,12.0,115.784668,false,DoNotOverride,22.0",
          GUID = "1E11EED8",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Yeah. The black market can wait. Let's go check on that Magistrate of Yingtian.",
          TalkActionId = {
            [1] = "200002:Shy02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EED8"
        },
        [12011709] = {
          DialogueId = 12011709,
          DialoguePanelType = "None",
          Duration = 3,
          GUID = "1E11EDB3",
          LookAt = {
            [1] = "210007:n(210007)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"-576.062866,240.156998,135.246094,0.000101,-7.401425,-32.185738,25.000002,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{_delay{2.1},TargetPosition{"-576.062866,240.156998,135.246094,0.000103,-6.401335,-16.985285,25.000006,100000.0,false,DoNotOverride,22.0"},duration{4}},
SEQ{
LookAt{LookAtDescription{"210007:n(210007)"}},
MoveTo{ActorId{210007},MoveSpeed{120},TargetPoint{"yuming_18_leave"}},
}
}]]
        },
        [12011801] = {
          Content = "怎么……是你们？此处危险——",
          DialogueId = 12011801,
          Duration = 3,
          GUID = "1E11FE1A",
          Subtitle = "What are you doing here...? It's dangerous—",
          VoiceName = "voice/$Locale$/story/1201/120118/1E11FE1A"
        },
        [12011802] = {
          Content = "我来帮你！",
          DialogueId = 12011802,
          Duration = 2,
          GUID = "1E11FE44",
          Subtitle = "We're here to help you!",
          VoiceName = "voice/$Locale$/story/1201/120118/1E11FE44"
        },
        [12011901] = {
          Content = "你们是化外无关人士，不应卷入这场恶战。这里由我一人应对就好。",
          DialogueId = 12011901,
          Duration = 3,
          GUID = "1E120E82",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 12011902,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "This fight doesn't concern you outsiders. Just leave. I'll deal with them myself.",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120E82"
        },
        [12011902] = {
          Content = "敌人面前不能闲聊，你说过的。",
          DialogueId = 12011902,
          Duration = 2,
          GUID = "1E120EAC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 12011903,
          SpeakNpcId = 100001,
          Subtitle = "No time for idle chatter with danger still looming — your words.",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120EAC"
        },
        [12011903] = {
          Content = "就是就是。都负伤了还嘴硬，你就乖乖接受我们的帮助吧！",
          DialogueId = 12011903,
          Duration = 3,
          GUID = "1E120ED6",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12011904,
          SpeakNpcId = 200002,
          Subtitle = "Exactly! And look at you — you're hurt so bad already. Stop playing the hero and let us help!",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120ED6"
        },
        [12011904] = {
          Content = "……我明白了。",
          DialogueId = 12011904,
          Duration = 2,
          GUID = "1E120F00",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...Alright.",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120F00"
        },
        [12012001] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "这些孽畜，总算是尽数清缴了。多谢两位施以援手。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012001,
          GUID = "1E121EEA",
          NextDialogue = 12012002,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003
          },
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "These vile beasts... finally cleansed. Thank you both for your aid.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121EEA"
        },
        [12012002] = {
          Content = "抱歉，先前失了礼数，尚未互通姓名。在下煜明，请问你们是？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012002,
          GUID = "1E121F14",
          NextDialogue = 12012003,
          RelatedWikiId = {
            [1] = 203004
          },
          SpeakNpcId = 210007,
          Subtitle = "Forgive my earlier rudeness. We never properly exchanged names. I am Yuming. May I ask who you are?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121F14"
        },
        [12012003] = {
          Content = "我是外乡来的狩月人{nickname}。这位是……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012003,
          GUID = "1E121F3E",
          NextOptions = {
            [1] = 120120031,
            [2] = 120120032
          },
          SpeakNpcId = 100001,
          Subtitle = "I'm a Phoxhunter from a foreign land, . And this is...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121F3E"
        },
        [12012005] = {
          Content = "哼哼，没错！纯白的救赎☆光之魔王大人正是我！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012005,
          GUID = "1E121F92",
          NextDialogue = 12012009,
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh, uh-huh! And you can call me — the Pure-White Redeemer ☆ Demon King of Light!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121F92"
        },
        [12012007] = {
          Content = "异国文化，果真高深莫测……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012007,
          GUID = "1E121FE6",
          NextDialogue = 12012008,
          SpeakNpcId = 210007,
          Subtitle = "The culture of foreign lands is... truly mystifying.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121FE6"
        },
        [12012008] = {
          Content = "从、从别人的嘴里说出来，怎么有一种莫名的羞耻感……叫我白就好了！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012008,
          GUID = "1E122010",
          NextDialogue = 12012009,
          SpeakNpcId = 200002,
          Subtitle = "H—How come it sounds so much more embarrassing when someone else says it out loud...? Ugh, forget it — just call me Snow!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122010"
        },
        [12012009] = {
          Content = "刚刚还在说“无暇闲聊”，怎么这会儿就有空啦？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012009,
          GUID = "1E12203A",
          NextDialogue = 12012010,
          SpeakNpcId = 200002,
          Subtitle = "And what happened to \"No time for idle chatter,\" huh?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12203A"
        },
        [12012010] = {
          Content = "先前我灭敌心切，待人接物有所轻慢，想来惭愧，还望阁下海涵。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012010,
          GUID = "1E122064",
          NextDialogue = 12012011,
          SpeakNpcId = 210007,
          Subtitle = "I was focused on eliminating the enemy and neglected proper manners. I ask your forgiveness.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122064"
        },
        [12012011] = {
          Content = "好吧。白就大人有大量，原谅你啦！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012011,
          GUID = "1E12208E",
          NextDialogue = 12012012,
          SpeakNpcId = 200002,
          Subtitle = "Alright then. I have a big heart — so you're forgiven!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12208E"
        },
        [12012012] = {
          Content = "你还好吗？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012012,
          GUID = "1E1220B8",
          NextDialogue = 12012013,
          SpeakNpcId = 100001,
          Subtitle = "You okay?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1220B8"
        },
        [12012013] = {
          Content = "……无妨。只是刚才应对的狴犴众多，难免左支右绌，受了些皮外伤。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012013,
          GUID = "1E1220E2",
          NextDialogue = 12012014,
          SpeakNpcId = 210007,
          Subtitle = "...It's okay. I fought off too many Bi'an earlier and ended up a bit off balance — just some surface wounds.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1220E2"
        },
        [12012014] = {
          Content = "这看起来可不只是一点点皮外伤啊喂！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012014,
          GUID = "1E12210C",
          NextDialogue = 12012015,
          SpeakNpcId = 200002,
          Subtitle = "That doesn't look like \"just some surface wounds\" to me!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12210C"
        },
        [12012015] = {
          Content = "给你。这是我为了应对突发情况，从冰湖城带上的绷带和治疗药水。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012015,
          GUID = "1E122136",
          NextDialogue = 12012016,
          SpeakNpcId = 100001,
          Subtitle = "Here — take this. I brought some bandages and healing potions from Icelake, just in case.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122136"
        },
        [12012016] = {
          Content = "多谢好意，给两位添忧了……这些伤势只需静坐休息，一晌之后就能痊愈。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012016,
          GUID = "1E122160",
          NextDialogue = 12012017,
          SpeakNpcId = 210007,
          Subtitle = "Thank you for your kindness. I didn't mean to worry you... Truly, all I need is to sit and rest awhile. These injuries will mend soon enough.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122160"
        },
        [12012017] = {
          Content = "你确定吗？看起来已经伤到了筋骨，要不去找个医生看看？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012017,
          GUID = "1E12218A",
          NextDialogue = 12012018,
          SpeakNpcId = 100001,
          Subtitle = "You sure? That looks pretty bad... Maybe we should have a doctor take a look?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12218A"
        },
        [12012018] = {
          Content = "应天尉既与大风九章立了契，力量来源自与常人不同。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012018,
          GUID = "1E1221B4",
          NextDialogue = 12012019,
          SpeakNpcId = 210007,
          Subtitle = "As a Magistrate of Yingtian, my strength does not come solely from flesh and bone — it draws upon the Nine Chapters of Dafeng.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1221B4"
        },
        [12012019] = {
          Content = "只要脊骨未损，再重的伤势，也能通过汲取大风九章传来的能量而缓慢修复，不过是多忍受些痛楚煎熬罢了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012019,
          GUID = "1E1221DE",
          NextDialogue = 12012020,
          RelatedWikiId = {
            [1] = 405010
          },
          SpeakNpcId = 210007,
          Subtitle = "So long as my spine remains unbroken, even the gravest wounds can mend with the Nine Chapters' energy. It's slow and painful, but certain.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1221DE"
        },
        [12012020] = {
          Content = "听起来很厉害的样子……这不就是小说里的“不败金身”嘛！白都有点心动了！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012020,
          GUID = "1E122208",
          NextDialogue = 12012021,
          SpeakNpcId = 200002,
          Subtitle = "Whoa, that's amazing... like something out of a story — the \"unbreakable body\"! Now I'm a little jealous!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122208"
        },
        [12012021] = {
          Content = "那只是好的一面。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012021,
          GUID = "1E122232",
          NextDialogue = 12012022,
          SpeakNpcId = 210007,
          Subtitle = "That's merely the bright side.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122232"
        },
        [12012022] = {
          Content = "还有坏的一面？",
          DialogueId = 12012022,
          GUID = "1E12225C",
          NextDialogue = 12012023,
          SpeakNpcId = 200002,
          Subtitle = "Oh? So there's a downside?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12225C"
        },
        [12012023] = {
          Content = "…………",
          DialogueId = 12012023,
          GUID = "1E122286",
          NextDialogue = 12012024,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122286"
        },
        [12012024] = {
          Content = "无事，一时失言。",
          DialogueId = 12012024,
          GUID = "1E1222B0",
          NextDialogue = 12012025,
          SpeakNpcId = 210007,
          Subtitle = "It's nothing. I spoke out of turn.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1222B0"
        },
        [12012025] = {
          Content = "我曾是一介罪人，回首往去，纵是披坚执锐，却未能护下任何性命。为大风九章奔走，于我而言，是一件将功折罪的幸事。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012025,
          GUID = "1E1222DA",
          NextDialogue = 12012026,
          SpeakNpcId = 210007,
          Subtitle = "I was once a condemned soul. Looking back... though clad in armour and armed with blade, I failed to save a single life. To serve the Nine Chapters now... it is my chance to atone.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1222DA"
        },
        [12012026] = {
          Content = "多谢二位关怀。我在此疗伤，恕无法远送。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012026,
          GUID = "1E122304",
          NextDialogue = 12012027,
          SpeakNpcId = 210007,
          Subtitle = "Thank you both once again. I must remain here to recover — forgive me that I cannot see you off properly.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122304"
        },
        [12012027] = {
          Content = "二位身手了得，但烛阴之祸凶险，还望多多留意。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012027,
          GUID = "1E12232E",
          NextDialogue = 12012028,
          SpeakNpcId = 210007,
          Subtitle = "You both fight well. But the threat of Zhuyin is not to be underestimated. Take care.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12232E"
        },
        [12012028] = {
          Content = "放心，我们会的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012028,
          GUID = "1E122358",
          NextDialogue = 12012029,
          SpeakNpcId = 100001,
          Subtitle = "We will. Don't worry.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122358"
        },
        [12012029] = {
          Content = "如此，便好……",
          DialogueId = 12012029,
          GUID = "1E122382",
          NextDialogue = 12012030,
          SpeakNpcId = 210007,
          Subtitle = "Such a relief... to hear that...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122382"
        },
        [12012030] = {
          Content = "…………",
          DialogueId = 12012030,
          GUID = "1E1223AC",
          NextDialogue = 12012031,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1223AC"
        },
        [12012031] = {
          Content = "……睡、睡着了？",
          DialogueId = 12012031,
          GUID = "1E1223D6",
          NextDialogue = 12012032,
          SpeakNpcId = 200002,
          Subtitle = "...Did he... fall asleep?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1223D6"
        },
        [12012032] = {
          Content = "大概是太累了吧。我刚才转了一圈，这里的玄色狴犴都被我们清理干净了，应该暂时安全。我们找点什么把他藏起来吧。",
          DialogueId = 12012032,
          GUID = "1E122400",
          SpeakNpcId = 100001,
          Subtitle = "Probably just exhausted. I did a quick sweep — there aren't any more Sable Bi'an around, so it should be safe for now. Let's find something to cover him up.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122400"
        },
        [12012033] = {
          Camera = "-211.635849,61.618118,96.055908,0.000228,-13.199524,1.187723,50.000008,78.880096,false,Manual,6.0",
          Content = "就这样，大功告成！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012033,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-209.995361,89.062073,96.055908,0.000229,-12.999502,-3.412318,50.000008,384.850891,false,Manual,6.0",
          GUID = "1E12242A",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:p(baitx_20_lookat)"
          },
          NextDialogue = 12012034,
          Scripts = "SetLocation{ActorId{210007},TargetPoint{\"baitx_20_lookat\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 200002,
          Subtitle = "There we go — mission accomplished!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120120/1E12242A"
        },
        [12012034] = {
