}]],
          SpeakNpcId = 200002,
          Subtitle = "Didn't they say if you wear the pendant and make it through the cave, you're in? It was crawling with Sable Bi'an in there — we nearly got eaten! A little welcome would be nice, you know?",
          TalkActionId = {
            [1] = "200002:Talk02_Start",
            [2] = "100001:TilteHead_Start"
          },
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1201/120121/1E122FD0"
        },
        [12012105] = {
          Camera = "224.868164,494.087891,93.266602,3.600096,0.399839,-123.796814,35.000011,542.746643,false,Manual,2.8",
          Content = "理是这个理。恕我眼拙，您二位的挂坠在哪儿……？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012105,
          FacialId = {
            [1] = "210008:Cin_Idle"
