            [2] = "210059:n(200002)"
          },
          NextDialogue = 12012106,
          SpeakNpcId = 210008,
          Subtitle = "Fair enough... but forgive my old eyes — where exactly is this pendant of yours?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120121/1E122FFA"
        },
        [12012106] = {
