          },
          NextDialogue = 12012108,
          SpeakNpcId = 100001,
          Subtitle = "Maybe we lost it when we were fighting the Bi'an with Yuming earlier...",
          VoiceName = "voice/$Locale$/story/1201/120121/1E12304E"
