            [5] = "210059:n(100001)"
          },
          NextDialogue = 12012109,
          SpeakNpcId = 210008,
          Subtitle = "Yuming? Wait — Yuming the Huaxu Talon!? Now there's a name I know!",
          TalkActionId = {
