            [2] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120121/1E123078"
        },
        [12012109] = {
          Content = "哎哟喂，是我有眼不识泰山了。不知两位是哪路人马，有这兴致过来。莫非是——钓鱼执法？！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012109,
          FacialId = {
            [1] = "210008:Cin_Happy01"
          },
          GUID = "1E1230A2",
          LookAt = {
            [1] = "210058:n(100001)",
            [2] = "210059:n(100001)"
          },
          NextDialogue = 12012110,
          Scripts = [[
PARA{
PlayAnimation{_delay{6},ActorId{210008},AnimationId{"Explain02_End"},Duration{1}},
PlayFacial{_delay{6},ActorId{210008},FacialId{"Cin_Idle"}},
CameraMoveTo{_delay{9},TargetPosition{"151.875,84.750977,99.082031,0.000186,11.998456,-153.202118,40.000023,187.179169,false,Manual,3.746801"},duration{0}}
}]],
          SpeakNpcId = 210008,
          Subtitle = "Well damn, looks like I didn't know who I was talking to! So, tell me — who're you working with, showing up like this? Or... is this a sting? You lot setting us up?",
          VoiceName = "voice/$Locale$/story/1201/120121/1E1230A2"
        },
        [12012110] = {
          Content = "我们这里都是小本生意，没什么值得您惦记的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012110,
          FacialId = {
            [1] = "210008:Cin_Angry01"
          },
          GUID = "1E1230CC",
          NextDialogue = 12012111,
          SpeakNpcId = 210008,
          Subtitle = "Look, we're just two-bit traders here — nothing worth your trouble.",
          TalkActionId = {
            [1] = "210008:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120121/1E1230CC"
        },
        [12012111] = {
          Camera = "30.108398,-132.445312,151.695312,0.000212,-8.401153,95.996559,40.000023,452.333679,false,Manual,3.746801",
          Content = "您误会了。我们是百年春止流掌柜的朋友，受托来这里办事。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012111,
          GUID = "1E1230F6",
          LookAt = {
            [1] = "100001:n(210008)",
            [2] = "200002:n(210008)",
            [3] = "210008:n(100001)"
          },
          NextDialogue = 12012112,
          SpeakNpcId = 100001,
          Subtitle = "You're mistaken. We're friends of Proprietress Zhiliu from EverSpring — she sent us to retrieve something.",
          TalkActionId = {
            [1] = "210008:Talk01_End",
            [2] = "100001:Deny01"
          },
          VoiceName = "voice/$Locale$/story/1201/120121/1E1230F6"
        },
        [12012112] = {
          Camera = "594.422852,573.201172,288.23291,0.000224,-13.401206,-141.804123,35.0,452.333679,false,DoNotOverride,3.746801",
          Content = "您认识止流止掌柜，我还认识这朗朗青天白龙神君呢！仅凭一张嘴说的，谁不会？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012112,
          FinalCamera = "628.412109,530.005859,288.23291,0.000224,-13.401206,-141.804123,35.0,452.333679,false,DoNotOverride,3.746801",
          GUID = "1E123120",
          LookAt = {
            [1] = "210058:n(100001)",
            [2] = "210059:n(100001)"
          },
          NextDialogue = 12012113,
          SpeakNpcId = 210008,
          Subtitle = "You know Miss Zhiliu? Sure, and I'm best buds with Lord Argent! Anyone can flap their gums — doesn't make it true.",
          TalkActionId = {
            [1] = "210008:Confident_New_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120121/1E123120"
        },
        [12012113] = {
          Content = "不用再多废话了。兄弟们，风紧，扯乎——",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012113,
          GUID = "1E12314A",
          LookAt = {
            [1] = "210008:n(210008)",
            [2] = "210058:n(210008)",
            [3] = "210059:n(210008)"
          },
          NextDialogue = 12012114,
          Scripts = [[
PARA{
SEQ{
TurnTo{_delay{2},TurnToDescription{"210008:p(-180)"}},
MoveTo{ActorId{210008},TargetPoint{"MeichantA_Move2"},MoveSpeed{80},Visibility{"Show"}}
},
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"-0.021484,-371.760742,174.602051,0.000229,-7.000998,86.995377,35.000011,452.333679,false,DoNotOverride,3.746801"},duration{0}},
CameraMoveTo{TargetPosition{"3.455078,-305.514648,166.45459,0.000229,-7.000998,86.995377,35.000011,452.333679,false,DoNotOverride,3.746801"},duration{4}}
}
}]],
          SpeakNpcId = 210008,
          Subtitle = "Enough chatter. Boys — it's getting hot, time to scoot!",
          TalkActionId = {
            [1] = "210008:Confident_New_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120121/1E12314A"
        },
        [12012114] = {
          Camera = "-144.614258,249.075195,179.435547,0.000213,-26.201075,8.196909,40.000011,243.196228,false,Manual,3.746801",
          Content = "怎、怎么办，小仆从？感觉今天做什么都不顺利，这就是华胥俗称的“点背”嘛！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012114,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-145.767578,257.100586,179.435547,0.000213,-26.201069,8.196872,40.000011,243.196228,false,Manual,3.746801",
          GUID = "1E123174",
          NextDialogue = 12012115,
          Scripts = [[
PARA{
SetLocation{ActorId{210008},TargetPoint{"MeichantA_Move2"},Visibility{"Hide"}},
SetLocation{ActorId{210058},TargetPoint{"Xiaodi1_Move"},Visibility{"Hide"}},
SetLocation{ActorId{210059},TargetPoint{"Xiaodi2_Move"},Visibility{"Hide"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wh—What now, Little Minion? Nothing's going right today... This must be what they call \"when even your shadow trips over you\" in Huaxu!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120121/1E123174"
        },
        [12012115] = {
          Camera = "622.662109,-1112.847656,421.122559,0.000177,-10.60076,113.988228,40.0,243.196228,false,DoNotOverride,3.746801",
          Content = "只能在这附近转转，看看有没有机会见到那位虬先生了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012115,
          FinalCamera = "841.544922,-1591.740234,696.769043,0.000171,-15.400682,114.189644,40.0,243.196228,false,DoNotOverride,3.746801",
          GUID = "1E12319E",
          SpeakNpcId = 100001,
          Subtitle = "We'll just have to hang around here a bit. Maybe we'll still get a chance to see Mr Qiu.",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1201/120121/1E12319E"
        },
        [12012201] = {
          Content = "你——简直欺人太甚！！",
          DialogueId = 12012201,
          Duration = 2,
          GUID = "1E123FBA",
          NextDialogue = 12012202,
          SpeakNpcId = 210011,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "You—! This is outrageous!",
          VoiceName = "voice/$Locale$/story/1201/120122/1E123FBA"
        },
        [12012202] = {
          Content = "小仆从，对面好像起了什么争执！我们赶紧过去看看热闹！",
          DialogueId = 12012202,
          Duration = 3,
          GUID = "1E123FE4",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, sounds like something's going on over there! Let's go take a look!",
          VoiceName = "voice/$Locale$/story/1201/120122/1E123FE4"
        },
        [12012301] = {
          Camera = "353.783203,574.717773,227.101074,0.000003,-5.60001,-117.193687,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "今日在这里，我横竖也要讨个说法——",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012301,
          GUID = "1E125022",
          NextDialogue = 12012302,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          SpeakNpcId = 210011,
          Subtitle = "I'm not leaving until I get justice!",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125022"
        },
        [12012302] = {
          Content = "你诓骗家父签下了假契书，害得佘家家财尽散。母亲受此打击也一病不起，郁郁而终。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012302,
          GUID = "1E12504C",
          NextDialogue = 12012303,
          SpeakNpcId = 210011,
          Subtitle = "You tricked my father into signing a false contract and ruined our family's fortune. My mother was so heartbroken she fell ill and died in despair.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12504C"
        },
        [12012303] = {
          Content = "贪了人钱财性命，自己却脱身事外……这黑市还有没有王法存在？！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012303,
          GUID = "1E125076",
          NextDialogue = 12012304,
          SpeakNpcId = 210011,
          Subtitle = "You took our money — and our lives — and just walked away like nothing happened. Does the black market have no law at all!?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125076"
        },
        [12012304] = {
          Content = "您说笑呢——大风九章，不就是这华胥的王法？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012304,
          GUID = "1E1250A0",
          NextDialogue = 12012305,
          SpeakNpcId = 210009,
          Subtitle = "Now that's a funny thing to say — isn't the Nine Chapters of Dafeng the law of all places in Huaxu?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1250A0"
        },
        [12012305] = {
          Content = "那狴犴，应天尉，都双目如炬地盯着咱呢。咱要是敢作奸犯科，早就被狴犴给逮了去了。还能站在这里说话？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012305,
          GUID = "1E1250CA",
          NextDialogue = 12012306,
          SpeakNpcId = 210009,
          Subtitle = "We've got the Bi'an and the Magistrates of Yingtian watching us like hawks. If we were really breaking the law, they'd have dragged us away long ago. You think I'd still be standing here defending myself?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1250CA"
        },
        [12012306] = {
          Content = "诫条刻在那儿呢：毁约背盟，不可为也。咱只是照章办事，遵纪守法的小百姓一个呀。你血口喷人，咱心善，姑且不追究了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012306,
          GUID = "1E1250F4",
          NextDialogue = 12012307,
          SpeakNpcId = 210009,
          Subtitle = "The Admonitions are carved in stone: To break faith or betray a vow — this must not be done. I'm just a humble, law-abiding trader. You're spouting lies — but I'm a kind soul, so I'll let it slide.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1250F4"
        },
        [12012307] = {
          Content = "你……你怎么恶人先告状！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012307,
          GUID = "1E12511E",
          NextDialogue = 12012308,
          SpeakNpcId = 210011,
          Subtitle = "You... You're the one who did wrong, and now you're pointing fingers!?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12511E"
        },
        [12012308] = {
          Content = "要是正常的生意盈亏，我们便也认下了。但你事后拿出的那份契书，分明是在诓骗、敲诈！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012308,
          GUID = "1E125148",
          NextDialogue = 12012309,
          SpeakNpcId = 210011,
          Subtitle = "If it had just been an honest loss, we would have let it go. But that contract you whipped out afterwards — it was nothing but lies and extortion!",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125148"
        },
        [12012309] = {
          Content = "哎呀，令尊签字画押时……莫非不识字？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012309,
          GUID = "1E125172",
          NextDialogue = 12012310,
          SpeakNpcId = 210009,
          Subtitle = "Oh dear, are you saying your father signed something he couldn't even read?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125172"
        },
        [12012310] = {
          Content = "（群众哄笑声。）",
          DialogueId = 12012310,
          GUID = "1E12519C",
          NextDialogue = 12012311,
          Subtitle = "(Laughs and jeers)",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12519C"
        },
        [12012311] = {
          Content = "别强词夺理了！你看父亲年老眼花，故意把利息的“三倍”写成“三十倍”，还把“十”写得像芝麻一样小——",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012311,
          GUID = "1E1251C6",
          NextDialogue = 12012312,
          SpeakNpcId = 210011,
          Subtitle = "Don't play dumb! You made the \"30-fold\" interest look like \"3-fold\" — and that zero you wrote was tiny as a sesame seed!",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1251C6"
        },
        [12012312] = {
          Content = "天地良心，你敢对白龙神君发誓，你不是故意诓骗家父吗？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012312,
          GUID = "1E1251F0",
          NextDialogue = 12012313,
          SpeakNpcId = 210011,
          Subtitle = "Heaven and earth as our witness — swear by Lord Argent that you didn't trick my father!",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1251F0"
        },
        [12012313] = {
          Content = "小姑娘，这我可就要给你上一课了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012313,
          GUID = "1E12521A",
          NextDialogue = 12012314,
          SpeakNpcId = 210009,
          Subtitle = "Let me give you a little lesson, young lass.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12521A"
        },
        [12012314] = {
          Content = "这普天之下，率土之滨，凡是可为的，皆属大风九章默许的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012314,
          GUID = "1E125244",
          NextDialogue = 12012315,
          SpeakNpcId = 210009,
          Subtitle = "In all the lands beneath the heavens — anything the Nine Chapters doesn't forbid is fair play.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125244"
        },
        [12012315] = {
          Content = "大风九章只管咱们是否守契，又不管这契文怎么写。莫说这“十”字是大是小，就算我给它上面画根麻花，我照样好端端地站在这儿。你又能拿我如何？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012315,
          GUID = "1E12526E",
          NextDialogue = 12012316,
          SpeakNpcId = 210009,
          Subtitle = "They don't care how the contract is written — only that it's honoured. I could make that zero so small you'd need a magnifying glass, and it'd still hold up. And there's nothing you can do to change that.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12526E"
        },
        [12012316] = {
          Content = "你……！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012316,
          GUID = "1E125298",
          NextDialogue = 12012317,
          SpeakNpcId = 210011,
          Subtitle = "You...!",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125298"
        },
        [12012317] = {
          Content = "今天我就站在这里不走了。我要让每个路过的客人都知道你的所作所为！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012317,
          GUID = "1E1252C2",
          NextDialogue = 12012318,
          SpeakNpcId = 210011,
          Subtitle = "Then I'm not leaving. I'll tell everyone who passes by just what a swindler you really are!",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1252C2"
        },
        [12012318] = {
          Content = "（议论纷纷的嘈杂音。）",
          DialogueId = 12012318,
          GUID = "1E1252EC",
          NextDialogue = 12012319,
          Subtitle = "(The crowd breaks into murmurs and whispers.)",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1252EC"
        },
        [12012319] = {
          Content = "好了好了。大伙儿都围在这里，照这样下去，这生意没法做啦。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012319,
          GUID = "1E125316",
          NextDialogue = 12012320,
          SpeakNpcId = 210009,
          Subtitle = "Alright, alright. All you gawkers crowding around — how's a man supposed to keep his business going with this racket?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125316"
        },
        [12012320] = {
          Content = "听好了，咱也不是什么恶贯满盈的主。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012320,
          GUID = "1E125340",
          NextDialogue = 12012321,
          SpeakNpcId = 210009,
          Subtitle = "Listen, I'm no villain twirling his moustache.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125340"
        },
        [12012321] = {
          Content = "本来这生意，就该买定离手，风险自负。今儿个我欣赏你这小姑娘的骨气，就破例给你一个翻盘的机会。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012321,
          GUID = "1E12536A",
          NextDialogue = 12012322,
          SpeakNpcId = 210009,
          Subtitle = "Every deal comes with risk — win or lose, you take your chances. But I'll admit, you've got guts, young lass. I'll give you one shot to turn things around.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12536A"
        },
        [12012322] = {
          Content = "……你说。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012322,
          GUID = "1E125394",
          NextDialogue = 12012323,
          SpeakNpcId = 210011,
          Subtitle = "...I'm listening.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125394"
        },
        [12012323] = {
          Content = "看到我手下这弱不禁风的小兄弟了吗？按照我们黑市的规矩，你若是能在单挑中赢了他，我便把令尊的欠款连本带息地如数奉还。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012323,
          GUID = "1E1253BE",
          NextDialogue = 12012324,
          SpeakNpcId = 210009,
          Subtitle = "See that scrawny runt over there? In our line, the rules are simple — beat him in a fair duel, and I'll wipe your father's debt clean, interest and all.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1253BE"
        },
        [12012324] = {
          Content = "单挑？可是华胥禁武，又怎会允许私下械斗……？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012324,
          GUID = "1E1253E8",
          NextDialogue = 12012325,
          SpeakNpcId = 210011,
          Subtitle = "A duel? But Huaxu bans fighting. How can you fight without alerting the Bi'an...?",
          VoiceName = "voice/$Locale$/story/1201/120123/1E1253E8"
        },
        [12012325] = {
          Content = "瞧您说的。这只是点到为止的切磋，双方只用招式，不伤皮肉，怎会惊动狴犴和应天尉呢。有大风九章护着，您也不用怕自己的性命出什么差池。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012325,
          GUID = "1E125412",
          NextDialogue = 12012326,
          SpeakNpcId = 210009,
          Subtitle = "Relax. This'll just be a friendly sparring — no blood spilled, no broken bones. Nothing that'll wake the Bi'an or stir up the Magistrates of Yingtian. With the Nine Chapters watching over you, there's no need to fear for your life.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125412"
        },
        [12012326] = {
          Content = "您若是担心咱使什么手段，可以当场起草一份契书，条款都由您亲自书写，总能放心了吧。要是这点胆量都没有，那还请您不要打扰此地生意了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012326,
          GUID = "1E12543C",
          NextDialogue = 12012327,
          SpeakNpcId = 210009,
          Subtitle = "If you don't trust me, you're welcome to write out the duel's terms yourself. Draft a contract, clause by clause, in your own hand. If that's still too scary for you... then stop wasting my time.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E12543C"
        },
        [12012327] = {
          Content = "……好，我答应！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012327,
          GUID = "1E125466",
          SpeakNpcId = 210011,
          Subtitle = "...Fine. Let's do this.",
          VoiceName = "voice/$Locale$/story/1201/120123/1E125466"
        },
        [12012401] = {
          Content = "他答应得这么爽快……怕是有诈。",
          DialogueId = 12012401,
          Duration = 2,
          GUID = "1E12608A",
          NextDialogue = 12012402,
          SpeakNpcId = 100001,
          Subtitle = "That deal seems too good to be true. Something's fishy.",
          VoiceName = "voice/$Locale$/story/1201/120124/1E12608A"
        },
        [12012402] = {
          Content = "呜哇，围观的人越来越多了……可恶，踮起脚都看不到。",
          DialogueId = 12012402,
          Duration = 3,
          GUID = "1E1260B4",
          NextDialogue = 12012403,
          SpeakNpcId = 200002,
          Subtitle = "Ugh — more people are gathering! I can't see a thing from back here!",
          VoiceName = "voice/$Locale$/story/1201/120124/1E1260B4"
        },
        [12012403] = {
          Content = "小仆从，我们挤到前排去吧。",
          DialogueId = 12012403,
          Duration = 2,
          GUID = "1E1260DE",
          SpeakNpcId = 200002,
          Subtitle = "C'mon, Little Minion, let's squeeze up to the front!",
          VoiceName = "voice/$Locale$/story/1201/120124/1E1260DE"
        },
        [12012501] = {
          Camera = "353.783203,574.717773,227.101074,0.000003,-5.60001,-117.193687,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "随着双方揖礼，比试正式开始。",
          DialogueId = 12012501,
          GUID = "1E1270F2",
          NextDialogue = 12012511,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          Subtitle = "With a formal bow from both sides, the duel begins.",
          VoiceName = "voice/$Locale$/story/1201/120125/1E1270F2"
        },
        [12012502] = {
          Content = "小仆从，我看不太明白。但好像……那个姑娘占了上风？那她是不是有翻盘的机会了！",
          DialogueId = 12012502,
          GUID = "1E12711C",
          NextDialogue = 12012503,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, I don't really get how these fights work, but... it looks like she's got the upper hand! Does that mean she might really have a chance to clear her father's debt?",
          VoiceName = "voice/$Locale$/story/1201/120125/1E12711C"
        },
        [12012503] = {
          Content = "总感觉黑市的人在隐藏自己的实力……",
          DialogueId = 12012503,
          GUID = "1E127146",
          NextDialogue = 12012504,
          SpeakNpcId = 100001,
          Subtitle = "I've got a feeling... the black market guy is holding back.",
          VoiceName = "voice/$Locale$/story/1201/120125/1E127146"
        },
        [12012504] = {
          Content = "不好。那个人，在故意往她刀口上撞——！",
          DialogueId = 12012504,
          GUID = "1E127170",
          NextDialogue = 12012512,
          SpeakNpcId = 100001,
          Subtitle = "No — he's throwing himself at the tip of her blade on purpose!",
          VoiceName = "voice/$Locale$/story/1201/120125/1E127170"
        },
        [12012505] = {
          Content = "他、他为什么要干这种事情？！",
          DialogueId = 12012505,
          GUID = "1E12719A",
          NextDialogue = 12012510,
          SpeakNpcId = 200002,
          Subtitle = "Wh—Why would he do something like that!?",
          VoiceName = "voice/$Locale$/story/1201/120125/1E12719A"
        },
        [12012506] = {
          Content = "原来如此……这样大风九章会判定那女孩伤了人，狴犴会惩罚她！",
          DialogueId = 12012506,
          GUID = "1E1271C4",
          NextDialogue = 12012507,
          SpeakNpcId = 100001,
          Subtitle = "I see... He's trying to make the Nine Chapters see her as the aggressor — so the Bi'an will punish her!",
          VoiceName = "voice/$Locale$/story/1201/120125/1E1271C4"
        },
        [12012507] = {
          Content = "糟糕，她控制不住自己的力道了。必须在事态发酵之前分开他们！",
          DialogueId = 12012507,
          GUID = "1E1271EE",
          NextDialogue = 12012508,
          SpeakNpcId = 100001,
          Subtitle = "Oh no... she can't hold back — she's about to really hurt him! I need to stop them before things get out of hand!",
          VoiceName = "voice/$Locale$/story/1201/120125/1E1271EE"
        },
        [12012508] = {
          Content = "嗷呜——",
          DialogueId = 12012508,
          GUID = "1E127218",
          Subtitle = "Awoo—!",
          VoiceName = "voice/$Locale$/story/1201/120125/1E127218"
        },
        [12012509] = {
          Content = "由于你的及时救援，黑市商人只“蹭”到了肋下的一处伤口。\n狴犴击伤年轻姑娘以示惩戒，随后在凛风中隐去。",
          DialogueId = 12012509,
          Duration = 4,
          GUID = "1E127242",
          Subtitle = [[
Thanks to your quick intervention, the merchant only took a grazing cut to the ribs.
The Bi'an dealt the young lady a warning blow before vanishing back into the wind.]],
          VoiceName = "voice/$Locale$/story/1201/120125/1E127242"
        },
        [12012510] = {
          Content = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
          DialogueId = 12012510,
          GUID = "1E12726C",
          NextDialogue = 12012506,
          Subtitle = "And should anyone break that law... a Bi'an emerges, borne on blustery winds, to deliver judgement.",
          VoiceName = "voice/$Locale$/story/1201/120102/1E10FCB0"
        },
        [12012511] = {
          DialogueId = 12012511,
          GUID = "1E127172",
          NextDialogue = 12012502,
          VoiceName = "voice/$Locale$/story/1201/120125/1E127172"
        },
        [12012512] = {
          DialogueId = 12012512,
          GUID = "1E127171",
          NextDialogue = 12012505,
          VoiceName = "voice/$Locale$/story/1201/120125/1E127171"
        },
        [12012601] = {
          Camera = "-806.824219,-1533.11377,53.525879,0.000038,-4.799833,23.397711,35.0,385.121887,true,Manual,2.8",
          Content = "你怎么样了？",
          DialogueId = 12012601,
          FacialId = {
            [1] = "200002:Sad03",
            [2] = "210089:CM_Sad01",
            [3] = "100001:Sad01"
          },
          GUID = "1E12815A",
          LookAt = {
            [1] = "200002:n(210089)",
            [2] = "100001:n(210089)"
          },
          NextDialogue = 12012602,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          SpeakNpcId = 100001,
          Subtitle = "Are you alright?",
          TalkActionId = {
            [1] = "100001:SquatTalk_Start",
            [2] = "200002:Please01_Start"
          },
          TurnTo = {
            [1] = "210009:n(210089)"
          },
          VoiceName = "voice/$Locale$/story/1201/120126/1E12815A"
        },
        [12012602] = {
          Content = "多亏了恩人出手相助……好歹，保全了性命……",
          DialogueId = 12012602,
          GUID = "1E128184",
          NextDialogue = 12012603,
          SpeakNpcId = 210089,
          Subtitle = "Thank you... If you hadn't stepped in, I'd be dead by now...",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128184"
        },
        [12012603] = {
          Content = "大风九章……难道是只惩戒好人，却教有心人肆意妄为，逍遥法外的吗？",
          DialogueId = 12012603,
          GUID = "1E1281AE",
          NextDialogue = 12012604,
          SpeakNpcId = 210089,
          Subtitle = "So this is the Nine Chapters... Is this what justice looks like — punishing the good and honest while letting the wicked walk away free?",
          TalkActionId = {
            [1] = "100001:SquatTalk_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120126/1E1281AE"
        },
        [12012604] = {
          Camera = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,60.0,685.305847,true,Manual,2.8",
          Content = "可惜可惜，差点解决一桩麻烦……你又是哪根葱，跳出来扰咱的好事——",
          DialogueId = 12012604,
          FacialId = {
            [1] = "210009:CM_Angry01",
            [2] = "100001:Angry01"
          },
          FinalCamera = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,65.0,685.305847,true,Manual,2.8",
          GUID = "1E1281D8",
          LookAt = {
            [1] = "210009:n(100001)"
          },
          NextOptions = {
            [1] = 120126041,
            [2] = 120126042
          },
          SpeakNpcId = 210009,
          Subtitle = "Damn it... what a shame — I was this close to cleaning up a little mess. And who the hell are you, sticking your nose in and messing with my business?",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100001:n(210009)"
          },
          VoiceName = "voice/$Locale$/story/1201/120126/1E1281D8"
        }
      }
    end
  },
  {
    MinKey = 12012607,
    MaxKey = 12013902,
    Loader = function()
      return {
        [12012607] = {
          Camera = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,65.0,685.305847,true,Manual,2.8",
          Content = "带了帮手是吧。今天不管多少人来，我都叫他吃不了兜着走！",
          DialogueId = 12012607,
          GUID = "1E128256",
          SpeakNpcId = 210009,
          Subtitle = "So you brought backup, huh? I don't care how many you've got — nobody messes with my business and walks away unscathed!",
          TalkActionId = {
            [1] = "100001:Angry01_Start",
            [2] = "210009:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120126/1E128256"
        },
        [12012608] = {
          Content = "你控制力道，将对方制服，却没有留下伤口。",
          DialogueId = 12012608,
          GUID = "1E128280",
          Subtitle = "You held back just enough to subdue him without drawing blood.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128280"
        },
        [12012609] = {
          Camera = "944.539062,-331.335449,256.336914,0.000019,-7.799679,166.403183,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "够了——不可怠慢贵客！",
          DialogueId = 12012609,
          GUID = "1E1282AA",
          NextDialogue = 12012610,
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Enough — mind your manners in front of our guest!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1282AA"
        },
        [12012610] = {
          Content = "是我们没有及时察觉您的到来，让您看了这场闹剧……我家主人<H>虬先生</>有请您移步沉船内部的会客厅，进行商谈。",
          DialogueId = 12012610,
          GUID = "1E1282D4",
          NextDialogue = 12012611,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210010,
          Subtitle = "We failed to notice your arrival and let this little farce unfold before you — our apologies. My master, Mr Qiu, invites you aboard the wreck to his parlour for a private discussion.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1282D4"
        },
        [12012611] = {
          Content = "我怎么知道，这不是为了调开我而使的伎俩？",
          DialogueId = 12012611,
          GUID = "1E1282FE",
          NextDialogue = 12012612,
          SpeakNpcId = 100001,
          Subtitle = "How do I know this isn't just an excuse to trick me into leaving?",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1282FE"
        },
        [12012612] = {
          Content = "您且安心。您的朋友就是我们的朋友。万一朋友在我们的地盘上出了事，我们也不好向止流掌柜交代。",
          DialogueId = 12012612,
          GUID = "1E128328",
          NextDialogue = 12012613,
          SpeakNpcId = 210010,
          Subtitle = "Rest assured — your friends are our friends. If anything were to happen to her on our turf, we'd have to answer to Proprietress Zhiliu as well.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128328"
        },
        [12012613] = {
          Content = "是，是，都是朋友！原来是误会一场啊！",
          DialogueId = 12012613,
          GUID = "1E128352",
          NextDialogue = 12012614,
          SpeakNpcId = 210009,
          Subtitle = "Y—Yes, of course! All friends here! Just a little misunderstanding, that's all!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128352"
        },
        [12012614] = {
          Content = "咱今儿就把珍藏的药材都拿出来，给小友赔罪。一定给她的伤口包扎仔细了，让她宾至如归呀。",
          DialogueId = 12012614,
          GUID = "1E12837C",
          NextDialogue = 12012615,
          SpeakNpcId = 210009,
          Subtitle = "We'll bring out our best medicine for the young lady — patch her up real good, make sure she's feeling right at home!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E12837C"
        },
        [12012615] = {
          Content = "这样处理，您满意吗？",
          DialogueId = 12012615,
          GUID = "1E1283A6",
          NextDialogue = 12012616,
          SpeakNpcId = 210010,
          Subtitle = "Does this arrangement meet your satisfaction?",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1283A6"
        },
        [12012616] = {
          Content = "这家伙变脸这么快，真是气人！",
          DialogueId = 12012616,
          GUID = "1E1283D0",
          NextDialogue = 12012617,
          SpeakNpcId = 200002,
          Subtitle = "How can someone put on a new face that fast? Ugh — makes me sick!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1283D0"
        },
        [12012617] = {
          Content = "你们……",
          DialogueId = 12012617,
          GUID = "1E1283FA",
          NextDialogue = 12012618,
          SpeakNpcId = 100001,
          Subtitle = "You...",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1283FA"
        },
        [12012618] = {
          Content = "算了。带路吧，我之后再来看她。",
          DialogueId = 12012618,
          GUID = "1E128424",
          SpeakNpcId = 100001,
          Subtitle = "Fine. Lead the way. I'll come check on her later.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128424"
        },
        [12012701] = {
          Camera = "69.70105,1077.539062,187.139709,0.0,-5.999931,-101.595413,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "有朋自远方来，幸甚至哉。",
          DialogueId = 12012701,
          GUID = "1E1291C2",
          NextDialogue = 12012702,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012,
            [4] = 203005
          },
          SpeakNpcId = 210012,
          Subtitle = "What a joy it is to welcome friends from afar.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1291C2"
        },
        [12012702] = {
          Content = "你们黑市人，平时就是这样行事吗？",
          DialogueId = 12012702,
          GUID = "1E1291EC",
          NextDialogue = 12012703,
          SpeakNpcId = 100001,
          Subtitle = "Is this how you people do business in the black market?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1291EC"
        },
        [12012703] = {
          Content = "小友恰好撞见了比较极端的个例，但我并不打算否认这种生存之道。",
          DialogueId = 12012703,
          GUID = "1E129216",
          NextDialogue = 12012704,
          SpeakNpcId = 210012,
          Subtitle = "You simply stumbled upon an extreme case. But I won't deny — it's one of many ways to survive.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129216"
        },
        [12012704] = {
          Content = "竟然承认了……无耻！",
          DialogueId = 12012704,
          GUID = "1E129240",
          NextDialogue = 12012705,
          SpeakNpcId = 200002,
          Subtitle = "Wow, you're really just admitting it like it's nothing? That's... shameless!",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129240"
        },
        [12012705] = {
          Content = "哈哈……要说到礼义廉耻，我倒是有一个问题想要请教。",
          DialogueId = 12012705,
          GUID = "1E12926A",
          NextDialogue = 12012706,
          SpeakNpcId = 210012,
          Subtitle = "Haha... speaking of shame, let me pose a question of my own.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12926A"
        },
        [12012706] = {
          Content = "昔日华胥一隅，有群羊，又有一猛虎。猛虎捕食群羊，羔羊为虎所食，不得安生。",
          DialogueId = 12012706,
          GUID = "1E129294",
          NextDialogue = 12012707,
          SpeakNpcId = 210012,
          Subtitle = "Once, in a quiet corner of Huaxu, there was a flock of sheep — and a single tiger. The tiger hunted the sheep at his leisure, and the sheep cowered in constant fear.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129294"
        },
        [12012707] = {
          Content = "此时一侠义之士路过，羔羊便向那侠士哭求，请他垂怜庇护，令羊群免受求生之苦。",
          DialogueId = 12012707,
          GUID = "1E1292BE",
          NextDialogue = 12012708,
          SpeakNpcId = 210012,
          Subtitle = "One day, a wandering hero passed by. The sheep wept and begged him to shield them from the beast.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1292BE"
        },
        [12012708] = {
          Content = "侠士可怜羔羊羸弱，便回应羊群祈愿，尽逐当地猛兽。又去了羔羊顶角，使它们不至于误伤同类。侠义之士离去后，羊群睦然而居，繁衍壮大。",
          DialogueId = 12012708,
          GUID = "1E1292E8",
          NextDialogue = 12012709,
          SpeakNpcId = 210012,
          Subtitle = "Moved by their plight, the hero drove off every predator that threatened the sheep. He also dulled their horns, so they wouldn't wound each other by mistake. With the danger gone, the flock lived in harmony and flourished.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1292E8"
        },
        [12012709] = {
          Content = "然，多年后一日，羊群中再次闯入一只新的猛虎。羊群折了角，逃跑的功夫又日久生疏，最后全数夭于虎口。",
          DialogueId = 12012709,
          GUID = "1E129312",
          NextDialogue = 12012710,
          SpeakNpcId = 210012,
          Subtitle = "But years later, a new tiger came among them... Their horns were dulled, and the instinct to flee long forgotten — until at last, every one of them perished in the tiger's maw.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129312"
        },
        [12012710] = {
          Content = "这个故事里，你们认为何者犯了<H>最大的错误</>呢？",
          DialogueId = 12012710,
          GUID = "1E12933C",
          NextOptions = {
            [1] = 120127101,
            [2] = 120127102,
            [3] = 120127103,
            [4] = 120127104
          },
          SpeakNpcId = 210012,
          Subtitle = "So... tell me — who in this story do you believe made the gravest mistake?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12933C"
        },
        [12012711] = {
          Content = "虎以羊为食，此乃天性使然。",
          DialogueId = 12012711,
          GUID = "1E129366",
          NextDialogue = 12012713,
          SpeakNpcId = 210012,
          Subtitle = "Tigers prey on sheep — that's simply nature's way.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129366"
        },
        [12012712] = {
          Content = "哈哈……所见略同。",
          DialogueId = 12012712,
          GUID = "1E129390",
          NextDialogue = 12012713,
          SpeakNpcId = 210012,
          Subtitle = "Heh... it seems we see eye to eye.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129390"
        },
        [12012713] = {
          Content = "故事里的羔羊就能全然置身事外吗？在天敌面前全无自保之力，只能垂首乞怜，寄希望于他人援手。",
          DialogueId = 12012713,
          GUID = "1E1293BA",
          NextDialogue = 12012716,
          SpeakNpcId = 210012,
          Subtitle = "The sheep, were they truly blameless? Faced with a natural predator, they had no means to protect themselves — only pitiful bleats and blind hope that someone else would save them.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1293BA"
        },
        [12012714] = {
          Content = "你想说什么？",
          DialogueId = 12012714,
          GUID = "1E1293E4",
          NextDialogue = 12012715,
          SpeakNpcId = 100001,
          Subtitle = "What are you trying to say?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1293E4"
        },
        [12012715] = {
          Content = "既然小友心中尚无定数，那虬某就给一个答案吧：犯下最大错误的既非猛虎，也非侠士，而是看似最无辜的羊群。",
          DialogueId = 12012715,
          GUID = "1E12940E",
          NextDialogue = 12012716,
          SpeakNpcId = 210012,
          Subtitle = "If you haven't found your own answer, allow me to offer mine. The gravest mistake wasn't the tiger's, nor the hero's — but the sheep's, the ones who seemed the most innocent.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12940E"
        },
        [12012716] = {
          Content = "正是它们放弃自保，向侠士摇尾乞怜，才招致了最终的灭亡。",
          DialogueId = 12012716,
          GUID = "1E129438",
          NextDialogue = 12012717,
          SpeakNpcId = 210012,
          Subtitle = "They gave up every means of defence, wagged their tails, and begged for rescue — thus sealing their fate.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129438"
        },
        [12012717] = {
          Content = "物竞天择，适者生存，自然界本是如此。为什么人类却满口仁义道德，以弱者自居，以顺服为荣呢？",
          DialogueId = 12012717,
          GUID = "1E129462",
          NextDialogue = 12012718,
          SpeakNpcId = 210012,
          Subtitle = "Survival of the fittest — that is the law of nature. So why do humans take no shame in weakness and elevate submission as if it were some noble virtue?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129462"
        },
        [12012718] = {
          Content = "在我看来，道德不过是弱者的遮羞布。逐利才是人之本性。",
          DialogueId = 12012718,
          GUID = "1E12948C",
          NextDialogue = 12012719,
          SpeakNpcId = 210012,
          Subtitle = "To me, morality is nothing more than a fig leaf for the powerless. The pursuit of profit — that is our true nature.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12948C"
        },
        [12012719] = {
          Content = "但凡有人类这种生物的地方，便伴随着支配与臣服。若有人自愿拔去爪牙，抛下剑盾，把力量交给虚无缥缈的“规则”，那也怪不得我们这样的人存在了。",
          DialogueId = 12012719,
          GUID = "1E1294B6",
          NextDialogue = 12012720,
          SpeakNpcId = 210012,
          Subtitle = "Wherever humans exist, so too does domination and submission. If someone willingly pulls out their claws, casts aside their shield and blade, and puts all their faith in some vague idea called \"rules\"... Then people like me are merely the consequence.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1294B6"
        },
        [12012720] = {
          Content = "……听你的意思，你追求的是一个人人都可以不受约束，肆意欺凌他人的世界。",
          DialogueId = 12012720,
          GUID = "1E1294E0",
          NextDialogue = 12012721,
          SpeakNpcId = 100001,
          Subtitle = "...So you're saying your ideal world is one where everyone's free to hurt each other with no limits at all?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1294E0"
        },
        [12012721] = {
          Content = "但我不喜欢。我不想被人拿剑指着，也对拿剑指着别人没兴趣。",
          DialogueId = 12012721,
          GUID = "1E12950A",
          NextDialogue = 12012722,
          SpeakNpcId = 100001,
          Subtitle = "Well, I don't want to live under someone else's blade — and I've got no interest in holding one over anyone else either.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12950A"
        },
        [12012722] = {
          Content = "哈哈！小友心思纯粹，倒是衬得吾辈蝇营狗苟了。",
          DialogueId = 12012722,
          GUID = "1E129534",
          NextDialogue = 12012723,
          SpeakNpcId = 210012,
          Subtitle = "Heh... such a pure heart, my young friend. It does make my petty dealings seem all the more sordid by comparison.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129534"
        },
        [12012723] = {
          Content = "闲聊到此为止吧。这就是止流掌柜托付我打造的工具，你拿好了。",
          DialogueId = 12012723,
          GUID = "1E12955E",
          NextDialogue = 12012724,
          SpeakNpcId = 210012,
          Subtitle = "Alright, enough philosophy. This is the tool Proprietress Zhiliu commissioned — take it.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12955E"
        },
        [12012724] = {
          Content = "让白看看，怪模怪样的……方盒子？",
          DialogueId = 12012724,
          GUID = "1E129588",
          NextDialogue = 12012725,
          SpeakNpcId = 200002,
          Subtitle = "Let me see... it's a weird-looking... square box, isn't it?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129588"
        },
        [12012725] = {
          Content = "它以失传的机枢派技艺锻造而成，光是凑齐所需材料便费了不少功夫。",
          DialogueId = 12012725,
          GUID = "1E1295B2",
          NextDialogue = 12012726,
          SpeakNpcId = 210012,
          Subtitle = "It was forged using the long-lost techniques of the Jishu Sect. Just gathering the materials took no small effort.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1295B2"
        },
        [12012726] = {
          Content = "至于其中妙用……去请教它的锻造者吧。公尚师傅想必已迫不及待地要显摆自己的手艺了，他就在尘漠石海的入口处等着你们。",
          DialogueId = 12012726,
          GUID = "1E1295DC",
          NextDialogue = 12012727,
          SpeakNpcId = 210012,
          Subtitle = "As for how it works... ask its creator. Master Gongshang is likely itching to show it off. You'll find him waiting at the entrance to the Gritblight Expanse.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1295DC"
        },
        [12012727] = {
          Content = "没什么别的事，我告辞了。",
          DialogueId = 12012727,
          GUID = "1E129606",
          NextDialogue = 12012728,
          SpeakNpcId = 100001,
          Subtitle = "If that's all, then I'll take my leave.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129606"
        },
        [12012728] = {
          Content = "小友留步片刻。",
          DialogueId = 12012728,
          GUID = "1E129630",
          NextDialogue = 12012729,
          SpeakNpcId = 210012,
          Subtitle = "Hold on, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129630"
        },
        [12012729] = {
          Content = "顺手带上这支竹笛吧。狴犴造成的伤口并非普通人能承受，这支竹笛或许能发挥意想不到的功用。",
          DialogueId = 12012729,
          GUID = "1E12965A",
          NextDialogue = 12012730,
          SpeakNpcId = 210012,
          Subtitle = "Take this bamboo flute with you. Wounds left by the Bi'an are not something ordinary folk can easily endure. This flute may prove unexpectedly useful.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12965A"
        },
        [12012730] = {
          Content = "就当做是……我对你的“投资”好了。",
          DialogueId = 12012730,
          GUID = "1E129684",
          SpeakNpcId = 210012,
          Subtitle = "Think of it as... my little investment in you.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129684"
        },
        [12012801] = {
          Content = "这个叫做虬先生的家伙总是皮笑肉不笑的，真不想和他打交道……",
          DialogueId = 12012801,
          Duration = 2,
          GUID = "1E12A22A",
          NextDialogue = 12012802,
          SpeakNpcId = 200002,
          Subtitle = "That Mr Qiu guy always smiles like he doesn't mean it. I really don't want to deal with him...",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A22A"
        },
        [12012802] = {
          Content = "这就怕了？",
          DialogueId = 12012802,
          Duration = 2,
          GUID = "1E12A254",
          NextDialogue = 12012803,
          SpeakNpcId = 100001,
          Subtitle = "You're scared of him already?",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A254"
        },
        [12012803] = {
          Content = "你、你说什么呢！光之魔王大人顶天立地，怎么会有害怕的东西！",
          DialogueId = 12012803,
          Duration = 3,
          GUID = "1E12A27E",
          NextDialogue = 12012804,
          SpeakNpcId = 200002,
          Subtitle = "N—No way! The Demon King of Light fears nothing! I stand tall — no fear in sight!",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A27E"
        },
        [12012804] = {
          Content = "好啦好啦，不拿你开玩笑了。",
          DialogueId = 12012804,
          Duration = 2,
          GUID = "1E12A2A8",
          NextDialogue = 12012805,
          SpeakNpcId = 100001,
          Subtitle = "Hehe. I was just teasing you.",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2A8"
        },
        [12012805] = {
          Content = "他们在照顾那个女孩。还好，他们还算信守承诺。",
          DialogueId = 12012805,
          Duration = 2,
          GUID = "1E12A2D2",
          NextDialogue = 12012806,
          SpeakNpcId = 100001,
          Subtitle = "They're tending to her... At least they kept their promise.",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2D2"
        },
        [12012806] = {
          Content = "诶，但是她的状态看起来不太好……我们也去看看吧！",
          DialogueId = 12012806,
          Duration = 2,
          GUID = "1E12A2FC",
          SpeakNpcId = 200002,
          Subtitle = "But she looks awful... C'mon, let's check on her!",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2FC"
        },
        [12012901] = {
          Content = "没想到她身子骨这么弱……挨了狴犴一下便长卧不起了。",
          DialogueId = 12012901,
          GUID = "1E12B292",
          NextDialogue = 12012902,
          SpeakNpcId = 210008,
          Subtitle = "Didn't expect her to be this frail... One strike from the Bi'an, and she's been bedridden ever since.",
          VoiceName = "voice/$Locale$/story/1201/120129/1E12B292"
        },
        [12012902] = {
          Content = "这下就算是神仙妙手来了，也无力回天了吧。",
          DialogueId = 12012902,
          GUID = "1E12B2BC",
          SpeakNpcId = 210009,
          Subtitle = "At this rate, not even a miracle could save her.",
          VoiceName = "voice/$Locale$/story/1201/120129/1E12B2BC"
        },
        [12013001] = {
          Content = "什么人，走路不看路的吗？",
          DialogueId = 12013001,
          Duration = 2,
          GUID = "1E12C2FA",
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          SpeakNpcId = 210008,
          Subtitle = "Hey—! Watch where you're going!",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C2FA"
        },
        [12013002] = {
          Content = "我说，这里可是黑市的地盘……嘁，真是怪人。",
          DialogueId = 12013002,
          Duration = 2,
          GUID = "1E12C324",
          SpeakNpcId = 210009,
          Subtitle = "You do realise this is black market territory...? Tch. What a weirdo.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C324"
        },
        [12013003] = {
          Content = "……你受伤了。痛吗？",
          DialogueId = 12013003,
          Duration = 2,
          GUID = "1E12C34E",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "...You are injured. Does it hurt?",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C34E"
        },
        [12013004] = {
          Content = "不要紧，忍耐片刻就好。",
          DialogueId = 12013004,
          Duration = 2,
          GUID = "1E12C378",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "Be at ease — bear with it but a moment.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C378"
        },
        [12013005] = {
          Content = "你看似多有劳累。",
          DialogueId = 12013005,
          Duration = 2,
          GUID = "1E12C3A2",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "You look weary.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C3A2"
        },
        [12013006] = {
          Content = "我会为你调理，以免积劳成疾。",
          DialogueId = 12013006,
          Duration = 2,
          GUID = "1E12C3CC",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "Let me ease your fatigue — before it takes deeper root.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C3CC"
        },
        [12013101] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "如此，你的疲累应该已无大碍。",
          DialogueId = 12013101,
          GUID = "1E12D362",
          NextDialogue = 12013102,
          SpeakNpcId = 210013,
          Subtitle = "It is done. You'll get well soon.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D362"
        },
        [12013102] = {
          Content = "这位受伤的姑娘，是你们的朋友吗？",
          DialogueId = 12013102,
          GUID = "1E12D38C",
          NextDialogue = 12013103,
          SpeakNpcId = 210013,
          Subtitle = "Is this young lady a friend of yours?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D38C"
        },
        [12013103] = {
          Content = "……抱歉，我还未介绍名姓。我是<H>祝由</>扶疏，以家族世代传承的<H>枯荣之法</>，为恶疾缠身之人祛痛排浊。",
          DialogueId = 12013103,
          GUID = "1E12D3B6",
          NextDialogue = 12013104,
          RelatedWikiId = {
            [1] = 405012,
            [2] = 203006
          },
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I have yet to introduce myself. I'm Fushu, a healer who uses Zhuyou therapy. I practise the Art of Ephemerality passed down through my line — to cleanse affliction and expel foulness that clings to the suffering.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D3B6"
        },
        [12013104] = {
          Content = "你的意思是……你是一位医生？",
          DialogueId = 12013104,
          GUID = "1E12D3E0",
          NextDialogue = 12013105,
          SpeakNpcId = 100001,
          Subtitle = "So... you're a doctor?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D3E0"
        },
        [12013105] = {
          Content = "在华胥，枯荣之法与医药之学并非同一原理。但如果医师这一称呼会让你觉得方便，倒也无妨——或者简单一点，唤我“扶疏”便可。",
          DialogueId = 12013105,
          GUID = "1E12D40A",
          NextDialogue = 12013106,
          RelatedWikiId = {
            [1] = 304005
          },
          SpeakNpcId = 210013,
          Subtitle = "In Huaxu, the Art of Ephemerality and the practice of medicine do not share the same roots. Yet if calling me a doctor brings you ease, I shall not object. Or if you prefer, simply call me Fushu.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D40A"
        },
        [12013106] = {
          Content = "二位认识这位姑娘吗？",
          DialogueId = 12013106,
          GUID = "1E12D434",
          NextOptions = {
            [1] = 120131061,
            [2] = 120131062
          },
          SpeakNpcId = 210013,
          Subtitle = "Do you know this young lady?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D434"
        },
        [12013107] = {
          Content = "我无法根治她的病痛。可否了解她的伤因何而起？",
          DialogueId = 12013107,
          GUID = "1E12D45E",
          NextDialogue = 12013108,
          SpeakNpcId = 210013,
          Subtitle = "I cannot cleanse this affliction entirely. May I inquire... how did she come by these wounds?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D45E"
        },
        [12013108] = {
          Content = "她的伤口是狴犴造成的，但她不是什么坏人。",
          DialogueId = 12013108,
          GUID = "1E12D488",
          NextDialogue = 12013109,
          SpeakNpcId = 100001,
          Subtitle = "Her wounds were caused by a Bi'an. But she's not a criminal.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D488"
        },
        [12013109] = {
          Content = "她是被黑市的坏家伙陷害，才被大风九章惩罚的！你不要放弃她……",
          DialogueId = 12013109,
          GUID = "1E12D4B2",
          NextDialogue = 12013110,
          SpeakNpcId = 200002,
          Subtitle = "She was framed by some bad guys in the black market! That's why the Nine Chapters punished her! Please... don't give up on her.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D4B2"
        },
        [12013110] = {
          Content = "我明白了。枯荣之术同样源于大风九章，因此我的力量无法治愈狴犴的伤。我会将她带回照料，寻找有无他法。",
          DialogueId = 12013110,
          GUID = "1E12D4DC",
          NextDialogue = 12013111,
          SpeakNpcId = 210013,
          Subtitle = "I see. The Art of Ephemerality is drawn from the same source as the Nine Chapters, and thus cannot mend wounds wrought by a Bi'an. I shall take her with me and seek out other remedies.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D4DC"
        },
        [12013111] = {
          Content = "你……",
          DialogueId = 12013111,
          GUID = "1E12D506",
          NextDialogue = 12013112,
          SpeakNpcId = 210013,
          Subtitle = "You...",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D506"
        },
        [12013112] = {
          Content = "诶，扶疏姐姐为什么老盯着小仆从看呀，难道小仆从还有什么没治好的伤？",
          DialogueId = 12013112,
          GUID = "1E12D530",
          NextDialogue = 12013113,
          SpeakNpcId = 200002,
          Subtitle = "Huh? Why are you staring at my Little Minion like that, Miss Fushu? Wait... don't tell me my Little Minion's still got some hidden injury that needs treatment!",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D530"
        },
        [12013113] = {
          Content = "抱歉，我并非有意。你身体并无大碍。只是，你携带的那支竹笛似是故人之物，对我意义重大。",
          DialogueId = 12013113,
          GUID = "1E12D55A",
          NextDialogue = 12013114,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive my staring. It was unseemly of me. Your form is sound. Rather... it was that bamboo flute of yours. It resembles a relic once held by one dear to me.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D55A"
        },
        [12013114] = {
          Content = "谅我冒昧，可否将这支竹笛转让与我？我会尽力给出相应的报酬。",
          DialogueId = 12013114,
          GUID = "1E12D584",
          NextOptions = {
            [1] = 120131141,
            [2] = 120131142,
            [3] = 120131143
          },
          SpeakNpcId = 210013,
          Subtitle = "If I might be so bold — would you part with it? I would repay you, by whatever means I may.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D584"
        },
        [12013115] = {
          Content = "枯荣之术不图回报。这是家训，扶疏不敢违背。",
          DialogueId = 12013115,
          GUID = "1E12D5AE",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "The Art of Ephemerality is not to be bartered for gain. Such is the teaching of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D5AE"
        },
        [12013116] = {
          Content = "不能平白受人恩惠。这是家训，扶疏不敢违背。",
          DialogueId = 12013116,
          GUID = "1E12D5D8",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D5D8"
        },
        [12013117] = {
          Content = "理应如此。",
          DialogueId = 12013117,
          GUID = "1E12D602",
          NextDialogue = 12013118,
          SpeakNpcId = 210013,
          Subtitle = "You speak with reason.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D602"
        },
        [12013118] = {
          Content = "不能平白受人恩惠。这是家训，扶疏不敢违背。",
          DialogueId = 12013118,
          GUID = "1E12D62C",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D62C"
        },
        [12013119] = {
          Content = "只是我现在身无长物，就当我赊了这笔账吧。作为回报，日后你若有需要我的事，凡力所能及，扶疏在所不辞。",
          DialogueId = 12013119,
          GUID = "1E12D656",
          NextDialogue = 12013120,
          SpeakNpcId = 210013,
          Subtitle = "But I have nothing of worth on my person now. Thus let me offer this instead: should you ever call upon me, if it lies within my power — I shall not refuse.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D656"
        },
        [12013120] = {
          Content = "它对我们只是一支普通的竹笛，远不如对你而言的价值。来，给你。",
          DialogueId = 12013120,
          GUID = "1E12D680",
          NextDialogue = 12013121,
          SpeakNpcId = 100001,
          Subtitle = "To us, it's just a flute. But to you, it clearly means much more. Here — take it.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D680"
        },
        [12013121] = {
          Content = "多谢。还请二位告知名姓吧，扶疏定不相忘。",
          DialogueId = 12013121,
          GUID = "1E12D6AA",
          NextOptions = {
            [1] = 120131211,
            [2] = 120131212
          },
          SpeakNpcId = 210013,
          Subtitle = "Much obliged. Might I know your names? I shall keep them close to heart.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6AA"
        },
        [12013122] = {
          Content = "嗯，我读过些风物志，“公爵”应是海伯利亚帝国的贵族。只是这“下水道”……",
          DialogueId = 12013122,
          GUID = "1E12D6D4",
          NextDialogue = 12013123,
          SpeakNpcId = 210013,
          Subtitle = "Hmm... I have read some travel accounts from abroad. \"Duke\" appears to be a noble title in the Hyperborean Empire. As for the \"Sewers\"...",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6D4"
        },
        [12013123] = {
          Content = "无事，兴许是我的认知已经跟不上如今的时代了。",
          DialogueId = 12013123,
          GUID = "1E12D6FE",
          NextDialogue = 12013124,
          SpeakNpcId = 210013,
          Subtitle = "Never mind. Perhaps it is simply that I am out of touch with the times.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6FE"
        },
        [12013124] = {
          Content = "开个玩笑……我是{nickname}。这位皎皎叫白。",
          DialogueId = 12013124,
          GUID = "1E12D728",
          NextDialogue = 12013125,
          SpeakNpcId = 100001,
          Subtitle = "Just kidding. I'm  and this little Luno is Snow.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D728"
        },
        [12013125] = {
          Content = "好的，{nickname}，白。",
          DialogueId = 12013125,
          GUID = "1E12D752",
          NextDialogue = 12013126,
          SpeakNpcId = 210013,
          Subtitle = "Understood. It's nice to meet you, , and Snow.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D752"
        },
        [12013126] = {
          Content = "那我便不耽误二位的行程了，回见。",
          DialogueId = 12013126,
          GUID = "1E12D77C",
          SpeakNpcId = 210013,
          Subtitle = "Then I shall delay you no longer. See you.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D77C"
        },
        [12013127] = {
          Content = "咳、咳……！",
          DialogueId = 12013127,
          Duration = 4,
          GUID = "1E12D7A6",
          Subtitle = "*cough* *cough*",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D7A6"
        },
        [12013201] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你……扶疏姐姐，你怎么了？！",
          DialogueId = 12013201,
          GUID = "1E12E3CA",
          NextDialogue = 12013202,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012,
            [4] = 405012,
            [5] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "Hey—! What's wrong, Miss Fushu!?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E3CA"
        },
        [12013202] = {
          Content = "……无妨。",
          DialogueId = 12013202,
          GUID = "1E12E3F4",
          NextDialogue = 12013203,
          SpeakNpcId = 210013,
          Subtitle = "...It's nothing.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E3F4"
        },
        [12013203] = {
          Content = "以自身气血化如甘霖，引渡患者体内病秽伤痛凝成的浊气，则为<H>枯荣</>。",
          DialogueId = 12013203,
          GUID = "1E12E41E",
          NextDialogue = 12013204,
          RelatedWikiId = {
            [1] = 304005
          },
          SpeakNpcId = 210013,
          Subtitle = "To perform the Art of Ephemerality is to draw upon one's own essence, pulling forth the miasma of pain and corruption from another's body.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E41E"
        },
        [12013204] = {
          Content = "自烛阴之灾以来，伤者众多，我连日使用枯荣之法，气血周转不济，从而失态了，请二位勿要介怀。",
          DialogueId = 12013204,
          GUID = "1E12E448",
          NextDialogue = 12013205,
          SpeakNpcId = 210013,
          Subtitle = "Since the resurgence of the Scourge of Zhuyin, those in need have only grown more numerous. I have used this technique each day; the strain has left my energy unbalanced — hence this brief faltering. Please... be not alarmed.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E448"
        },
        [12013205] = {
          Content = "自身气血……小仆从，这又是什么意思？",
          DialogueId = 12013205,
          GUID = "1E12E472",
          NextDialogue = 12013206,
          SpeakNpcId = 200002,
          Subtitle = "One's own essence? What does that mean, Little Minion?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E472"
        },
        [12013206] = {
          Content = "扶疏，你的意思是……枯荣之法就是以命换命？",
          DialogueId = 12013206,
          GUID = "1E12E49C",
          NextDialogue = 12013207,
          SpeakNpcId = 100001,
          Subtitle = "Fushu... Are you saying that this technique trades your life for theirs?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E49C"
        },
        [12013207] = {
          Content = "你的家人……不会很担心吗？",
          DialogueId = 12013207,
          GUID = "1E12E4C6",
          NextDialogue = 12013208,
          SpeakNpcId = 100001,
          Subtitle = "What about your family? Aren't they worried about you?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E4C6"
        },
        [12013208] = {
          Content = "……",
          DialogueId = 12013208,
          GUID = "1E12E4F0",
          NextDialogue = 12013209,
          SpeakNpcId = 210013,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E4F0"
        },
        [12013209] = {
          Content = "家中传下了排浊化清的秘法，只要休憩片刻就好。",
          DialogueId = 12013209,
          GUID = "1E12E51A",
          NextDialogue = 12013210,
          SpeakNpcId = 210013,
          Subtitle = "My family passed down a secret method of purification and renewal. A brief rest, and I shall be restored.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E51A"
        },
        [12013210] = {
          Content = "哎呀气死我了，那个叫煜明的家伙也是，华胥的卡戎怎么都不把自己的身体当一回事……简直是一个模子刻出来的！",
          DialogueId = 12013210,
          GUID = "1E12E544",
          NextDialogue = 12013211,
          SpeakNpcId = 200002,
          Subtitle = "Ugh! This is so frustrating! She's just like that Yuming guy — why do all the Charons of Huaxu act like their own health doesn't matter!?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E544"
        },
        [12013211] = {
          Content = "枯荣流转，月盈而亏。祛除病痛，自然也要付出等量的代价。",
          DialogueId = 12013211,
          GUID = "1E12E56E",
          NextDialogue = 12013212,
          SpeakNpcId = 210013,
          Subtitle = "Life waxes and wanes, like the moon in its cycle. To remove another's suffering is to take it into oneself. Such is the price.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E56E"
        },
        [12013212] = {
          Content = "…………",
          DialogueId = 12013212,
          GUID = "1E12E598",
          NextDialogue = 12013213,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E598"
        },
        [12013213] = {
          Content = "我要即刻出发寻找治愈这姑娘的法子，先失陪了。你们且去忙碌，若你们想看望她，可往北部杏林中的枯荣阁寻我。",
          DialogueId = 12013213,
          GUID = "1E12E5C2",
          RelatedWikiId = {
            [1] = 405013
          },
          SpeakNpcId = 210013,
          Subtitle = "I must depart at once to seek a remedy for this young lady. Forgive my abrupt leave-taking. Pray, continue on your path — and should you wish to see her again, you will find me at the Hall of Ephemerality, in the northern apricot grove.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E5C2"
        },
        [12013301] = {
          Content = "虽然她说休息一会儿就好，但刚才她都吐血了……真的不要紧吗？",
          DialogueId = 12013301,
          GUID = "1E12F432",
          NextDialogue = 12013302,
          SpeakNpcId = 200002,
          Subtitle = "She said she just needed rest, but she coughed up blood... Is she really going to be okay?",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F432"
        },
        [12013302] = {
          Content = "如果说枯荣之术就是消耗自己的生命救人，那她这样也有一部分是因为我……",
          DialogueId = 12013302,
          GUID = "1E12F45C",
          NextDialogue = 12013303,
          SpeakNpcId = 100001,
          Subtitle = "If the Art of Ephemerality really draws on one's life to save another... then I'm partially responsible for what she's going through.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F45C"
        },
        [12013303] = {
          Content = "等我们完成止流的差事，就去看看扶疏和那个女孩的情况吧。",
          DialogueId = 12013303,
          GUID = "1E12F486",
          NextDialogue = 12013304,
          SpeakNpcId = 100001,
          Subtitle = "Let's finish Proprietress Zhiliu's commission first. Then we'll check in on Fushu and the young lady.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F486"
        },
        [12013304] = {
          Content = "说起来，小仆从用一支笛子换取了顶级医生的诺言！这就是那个虬先生的意图吗？",
          DialogueId = 12013304,
          GUID = "1E12F4B0",
          NextDialogue = 12013305,
          SpeakNpcId = 200002,
          Subtitle = "We've got a top-tier healer on our side — and all it took was a bamboo flute! Was that Mr Qiu's plan from the start?",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F4B0"
        },
        [12013305] = {
          Content = "天上不会掉面包。他给我们的好处，以后肯定也会从我们这里讨回来。",
          DialogueId = 12013305,
          GUID = "1E12F4DA",
          NextDialogue = 12013306,
          SpeakNpcId = 100001,
          Subtitle = "Nothing comes without a price. Whatever he gave us, he'll collect on it later — with interest.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F4DA"
        },
        [12013306] = {
          Content = "虬先生……我们还是对他警惕些吧。",
          DialogueId = 12013306,
          GUID = "1E12F504",
          SpeakNpcId = 100001,
          Subtitle = "We'd better stay wary of Mr Qiu.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F504"
        },
        [12013401] = {
          Camera = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "你们两位脚程实在是太慢了——怎么才来？我一直搁这儿盯着，瞪得我眼睛都酸了。",
          DialogueId = 12013401,
          FinalCamera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          GUID = "1E13049A",
          LookAt = {
            [1] = "100001:n(210014)",
            [2] = "200002:n(210014)"
          },
          NextDialogue = 12013402,
          SpeakNpcId = 210014,
          Subtitle = "Ah, you two sure took your time — I've been standing here so long, my eyes nearly grew weary from watching.",
          TalkActionId = {
            [1] = "210014:Disagree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E13049A"
        },
        [12013402] = {
          Camera = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
          Content = "不好意思，刚刚被一些事情耽搁了。您就是公尚先生吧？",
          DialogueId = 12013402,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "1E1304C4",
          NextDialogue = 12013403,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, something came up along the way. You must be Master Gongshang.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1304C4"
        },
        [12013403] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "哎呀，怎么这么见外呢，还叫什么先生？来，快叫声师父！",
          DialogueId = 12013403,
          FacialId = {
            [1] = "210014:CM_Happy01"
          },
          GUID = "1E1304EE",
          NextDialogue = 12013404,
          SpeakNpcId = 210014,
          Subtitle = "Aww, \"Master Gongshang\"? Why so formal? Come on — call me Shifu!",
          TalkActionId = {
            [1] = "210014:Explain01_Start",
            [2] = "100001:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1304EE"
        },
        [12013404] = {
          Content = "咦——你们怎么两手空空，没带拜师礼吗？",
          DialogueId = 12013404,
          FacialId = {
            [1] = "210014:CM_Idle",
            [2] = "100001:None"
          },
          GUID = "1E130518",
          NextDialogue = 12013405,
          SpeakNpcId = 210014,
          Subtitle = "Wait a second... how come you arrived empty-handed? Where's the proper token of respect one should present when acknowledging their Shifu?",
          TalkActionId = {
            [1] = "210014:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130518"
        },
        [12013405] = {
          Camera = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
          Content = "……小仆从，搞技术的人，都是这么热情好客的吗？",
          DialogueId = 12013405,
          FacialId = {
            [1] = "200002:Guilty"
          },
          GUID = "1E130542",
          NextDialogue = 12013406,
          SpeakNpcId = 200002,
          Subtitle = "...Little Minion, are all these tinkerer-types always this... over-the-top?",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130542"
        },
        [12013406] = {
          Content = "那个，您是不是搞错了什么……我们是来请教这柄武器怎么使用，但好像不是来拜师的……",
          DialogueId = 12013406,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "1E13056C",
          LookAt = {
            [1] = "100001:n(210014)",
            [2] = "200002:n(210014)"
          },
          NextDialogue = 12013407,
          SpeakNpcId = 100001,
          Subtitle = "Um, I think you might be mistaken... We're just here to learn how to use the weapon you made, not to become your apprentices...",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13056C"
        },
        [12013407] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "竟然如此——",
          DialogueId = 12013407,
          FacialId = {
            [1] = "100001:None",
            [2] = "200002:None",
            [3] = "210014:CM_Sad01"
          },
          GUID = "1E130596",
          NextDialogue = 12013408,
          SpeakNpcId = 210014,
          Subtitle = "What!? Unbelievable—!",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "210014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130596"
        },
        [12013408] = {
          Camera = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
          Content = "哇啊！他好像一下子蔫了——我们是不是说了什么很打击人的话？",
          DialogueId = 12013408,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E1305C0",
          NextDialogue = 12013409,
          SpeakNpcId = 200002,
          Subtitle = "Whoa! He totally deflated all of a sudden — did we say something wrong?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1305C0"
        },
        [12013409] = {
          Content = "……您、您好？",
          DialogueId = 12013409,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E1305EA",
          NextDialogue = 12013410,
          SpeakNpcId = 100001,
          Subtitle = "Uh... are you alright, sir?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1305EA"
        },
        [12013410] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "罢了。怪我病急乱投医，一听到有人愿意继承我机枢派的衣钵，便喜不自胜，情难自禁。",
          DialogueId = 12013410,
          GUID = "1E130614",
          NextDialogue = 12013411,
          SpeakNpcId = 210014,
          Subtitle = "Forget it. I got ahead of myself... When I heard there were two youngsters who would carry on the Jishu Sect's legacy, I was overjoyed and lost ahold of myself.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130614"
        },
        [12013411] = {
          Content = "也怪我机枢派如今式微了，换以前风光的时候，弟子排着队来拜师，那是挑花了眼也挑不过来！",
          DialogueId = 12013411,
          GUID = "1E13063E",
          NextDialogue = 12013412,
          SpeakNpcId = 210014,
          Subtitle = "Our sect has seen better days, you know. Back in our prime, young hopefuls would line up in droves, begging to be my apprentices — so many I could hardly keep track!",
          TalkActionId = {
            [1] = "210014:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13063E"
        },
        [12013412] = {
          Camera = "-123.167976,-244.147675,155.87207,0.000059,-18.800013,73.197205,35.0,557.472534,false,DoNotOverride,2.8",
          Content = "再仔细看看两位，也是一副四体不勤、天资不足的模样。对于需要精密操作、聪慧头脑、过人毅力等等集大成于一体的机括术来说，还是远远不够啊。",
          DialogueId = 12013412,
          FacialId = {
            [1] = "100001:Unhappy01",
            [2] = "200002:Unhappy01"
          },
          FinalCamera = "-115.39222,-218.401855,146.717773,0.00006,-18.800013,73.197128,35.0,557.472534,false,DoNotOverride,2.8",
          GUID = "1E130668",
          LookAt = {
            [1] = "210014:n(100001)"
          },
          NextDialogue = 12013413,
          SpeakNpcId = 210014,
          Subtitle = "But now that I get a better look at you two... clumsy limbs, average smarts... Not exactly cut out for the mechanical brilliance and steady hand our sect demands.",
          TalkActionId = {
            [1] = "210014:Disagree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130668"
        },
        [12013413] = {
          Camera = "-139.459106,-137.644135,66.660156,0.00006,-13.600217,47.404423,35.000011,237.675415,false,DoNotOverride,2.8",
          Content = "……你，你别把我们看扁了！我们今天偏要——",
          DialogueId = 12013413,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E130692",
          NextDialogue = 12013414,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Don't go thinking we're no good! Just watch — we'll show you!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130692"
        },
        [12013414] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "哦？你难道是想证明，自己其实很有悟性？",
          DialogueId = 12013414,
          FacialId = {
            [1] = "210014：CM_Shock01"
          },
          GUID = "1E1306BC",
          LookAt = {
            [1] = "210014:n(200002)"
          },
          NextDialogue = 12013415,
          SpeakNpcId = 210014,
          Subtitle = "Show me what? That you actually have talent?",
          TalkActionId = {
            [1] = "210014:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1306BC"
        },
        [12013415] = {
          Content = "启动这牵机方枢吧。让我看看两位的资质，能否达到我们机枢派的标准。",
          DialogueId = 12013415,
          FacialId = {
            [1] = "210014：CM_Idle"
          },
          GUID = "1E1306E6",
          LookAt = {
            [1] = "210014:n(100001)"
          },
          SpeakNpcId = 210014,
          Subtitle = "Very well — activate the Mechanical Nexus. Let's see if you're truly Jishu Sect material.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1306E6"
        },
        [12013416] = {
          Camera = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "看见这些太虚符文了吗？",
          DialogueId = 12013416,
          FinalCamera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          GUID = "1E130710",
          LookAt = {
            [1] = "100001:n(210014)",
            [2] = "210014:n(100001)",
            [3] = "200002:n(210014)"
          },
          NextDialogue = 12013417,
          SpeakNpcId = 210014,
          Subtitle = "See those Taixu runes?",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130710"
        },
        [12013417] = {
          Camera = "-139.459106,-137.644135,66.660156,0.00006,-13.600217,47.404423,35.000011,237.675415,false,DoNotOverride,2.8",
          Content = "好难懂的名字……",
          DialogueId = 12013417,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E13073A",
          NextDialogue = 12013418,
          SpeakNpcId = 200002,
          Subtitle = "Oof... just hearing the name makes my head spin...",
          TalkActionId = {
            [1] = "210014:Explain01_End",
            [2] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13073A"
        },
        [12013418] = {
          Camera = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          Content = "唉，孺子不可教也——太虚，无形无色，却又四处充盈。这是鸿蒙之初的常态。",
          DialogueId = 12013418,
          FacialId = {
            [1] = "210014:CM_Sad01"
          },
          FinalCamera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          GUID = "1E130764",
          NextDialogue = 12013419,
          SpeakNpcId = 210014,
          Subtitle = "Such a slow-witted child. \"Taixu\" means that which is formless and without colour, yet it pervades all that exists. It is the primal Chaos, the breath of creation at the dawn of the world.",
          TalkActionId = {
            [1] = "210014:Disagree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130764"
        },
        [12013419] = {
          Camera = "-1551.53418,-586.06665,694.782227,0.000069,-29.399681,18.407328,35.000011,555.878662,false,DoNotOverride,2.8",
          Content = "太虚被香所激化，乘风鼓动，便能成为大风九章运转的介质；静而不发，便能凝为浮盈空中的太虚符文。",
          DialogueId = 12013419,
          FacialId = {
            [1] = "210014:CM_Idle"
          },
          FinalCamera = "-1628.330078,-611.611572,740.382324,0.000072,-29.399687,18.407286,35.000011,555.878662,false,DoNotOverride,2.8",
          GUID = "1E13078E",
          NextDialogue = 12013420,
          SpeakNpcId = 210014,
          Subtitle = "When stirred by incense, the Taixu rides upon the wind and becomes the medium through which the Nine Chapters of Dafeng weave their power. When left undisturbed, it condenses into the Taixu runes drifting in the air.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120134/1E13078E"
        },
        [12013420] = {
          Content = "但如今在这朔方之地，烛阴蒙尘，固而下之，太虚便凝成裹挟一切有形形体的尘漠。",
          DialogueId = 12013420,
          GUID = "1E1307B8",
          NextDialogue = 12013421,
          SpeakNpcId = 210014,
          Subtitle = "But here in this land, shrouded by the Scourge of Zhuyin, the Taixu has sunk downwards and congealed into the Gritblight, swallowing all that bears shape and form.",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1307B8"
        },
        [12013421] = {
          Content = "而我这牵机方枢，其开天辟地之功效，便能吸收太虚，使异状归于常态。",
          DialogueId = 12013421,
          GUID = "1E1307E2",
          SpeakNpcId = 210014,
          Subtitle = "This remarkable contraption I forged can be used to draw upon the Taixu and restore balance to the world.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1307E2"
        },
        [12013422] = {
          Content = "算你勉强过关。下一关考验，你能应付吗？",
          DialogueId = 12013422,
          GUID = "1E13080C",
          SpeakNpcId = 210014,
          Subtitle = "Hmm... not bad. Now, let's see if you can handle the next trial.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E13080C"
        },
        [12013423] = {
          Camera = "628.248047,360.278137,60.518555,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          Content = "一套下来行云流水，动作竟如此利索！我却是没什么能再传授与你了。",
          DialogueId = 12013423,
          FacialId = {
            [1] = "210014:CM_Shock01"
          },
          FinalCamera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "1E130836",
          NextDialogue = 12013424,
          SpeakNpcId = 210014,
          Subtitle = "Steady hands, precise movements... You picked it up quicker than I'd expected. Truly, I have nothing more to teach you.",
          TalkActionId = {
            [1] = "210014:Shock_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130836"
        },
        [12013424] = {
          Camera = "-127.312958,25.078018,85.87793,0.000067,-13.821461,9.846305,35.000008,100000.0,false,DoNotOverride,2.8",
          Content = "哎？那是不是意味着小仆从学成出师了？",
          DialogueId = 12013424,
          FacialId = {
            [1] = "210014:CM_Idle",
            [2] = "200002:Happy01"
          },
          GUID = "1E130860",
          NextDialogue = 12013425,
          SpeakNpcId = 200002,
          Subtitle = "Whoa~ Does that mean my Little Minion has mastered it?",
          TalkActionId = {
            [1] = "210014:Shock_End",
            [2] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130860"
        },
        [12013425] = {
          Camera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          Content = "出师……也罢。当今世道，还有人愿意以我机枢派的名号为荣，不乏是一桩幸事。",
          DialogueId = 12013425,
          GUID = "1E13088A",
          NextDialogue = 12013426,
          SpeakNpcId = 210014,
          Subtitle = "Heh... so be it. In these times, to see anyone still willing to master something made by the Jishu Sect... that alone is enough to ease this old heart.",
          TalkActionId = {
            [1] = "210014:Sigh_Start",
            [2] = "200002:Excited01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13088A"
        },
        [12013426] = {
          Camera = "-183.790024,-222.993271,212.301758,0.000059,-21.221882,58.649464,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "两位，我便授予你们<H>机枢派荣誉学徒</>的头衔。望你们博学笃志，切问近思。不要辜负我们机枢派上下求索、高天揽月之志。",
          DialogueId = 12013426,
          FacialId = {
            [1] = "100001:Smile01",
            [2] = "200002:Smile01"
          },
          GUID = "1E1308B4",
          NextDialogue = 12013427,
          SpeakNpcId = 210014,
          Subtitle = "Very well — I hereby grant you both the title of Honorary Learner of the Jishu Sect. Study with focus. Ask your questions boldly. And never forget — our craft has ever sought to touch the stars above.",
          TalkActionId = {
            [1] = "210014:Explain01_Start",
            [2] = "100001:Shy02_Start",
            [3] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1308B4"
        },
        [12013427] = {
          Camera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          Content = "高处便是烛阴鳞所在之地。以我先前教你的法子，将附着于烛阴鳞之上的尘漠尽数吸收，便可进行采摘。",
          DialogueId = 12013427,
          GUID = "1E1308DE",
          NextDialogue = 12013428,
          SpeakNpcId = 210014,
          Subtitle = "See that path winding up ahead? That is where the Zhuyin Scales grow. Use the method I have shown you — draw out the Gritblight clinging to them, and you shall be able to harvest the scales.",
          TalkActionId = {
            [1] = "210014:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1308DE"
        },
        [12013428] = {
          Content = "我一把老身子骨了，不便与你们同行。你们且去吧。",
          DialogueId = 12013428,
          FacialId = {
            [1] = "210014:CM_Sad01"
          },
          GUID = "1E130908",
          SpeakNpcId = 210014,
          Subtitle = "As for me... I am far too old to be clambering about like in my younger days. Go on — I leave this to you.",
          TalkActionId = {
            [1] = "210014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130908"
        },
        [12013429] = {
          Content = "小仆从，你看！那边有一个奇怪的东西，散发出邪恶的气息！",
          DialogueId = 12013429,
          GUID = "1E130932",
          NextDialogue = 12013430,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, look! There's something weird over there... it's giving off some really wicked energy!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130932"
        },
        [12013430] = {
          Content = "以白魔王大人的洞见……那一定就是他们说的那个什么烛阴鳞了！",
          DialogueId = 12013430,
          GUID = "1E13095C",
          NextDialogue = 12013431,
          SpeakNpcId = 200002,
          Subtitle = "It must be the Zhuyin Scale they mentioned! Trust the Demon King's judgement!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E13095C"
        },
        [12013431] = {
          Content = "快用公尚师傅教我们的方法试试吧！",
          DialogueId = 12013431,
          GUID = "1E130986",
          SpeakNpcId = 200002,
          Subtitle = "Quick — let's try that method Master Gongshang taught us!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130986"
        },
        [12013432] = {
          Content = "魂兮游离，循时索归：山之阴，海之涯……",
          DialogueId = 12013432,
          GUID = "1E1309B0",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "The soul drifts untethered, returning with the turning of time: To the mountain's shadow... to the ocean's edge...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1309B0"
        },
        [12013433] = {
          Content = "谁？什么声音？",
          DialogueId = 12013433,
          GUID = "1E1309DA",
          NextDialogue = 12013434,
          SpeakNpcId = 100001,
          Subtitle = "Who's there!?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1309DA"
        },
        [12013434] = {
          Content = "小仆从，别发呆了，打起精神来！",
          DialogueId = 12013434,
          GUID = "1E130A04",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion! Focus!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A04"
        },
        [12013435] = {
          Content = "（白听不到刚才的声音……难道说，又是与诫碑那时相同的情况？）",
          DialogueId = 12013435,
          GUID = "1E130A2E",
          NextDialogue = 120134351,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Snow didn't seem to hear it... Was it like what happened at the stele...?)",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A2E"
        },
        [12013436] = {
          Content = "魂兮游离，循时索归：盈亏月下，若木长青……",
          DialogueId = 12013436,
          GUID = "1E130A58",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "The soul drifts untethered, returning with the turning of time: Beneath the waxing moon, by the evergreen wood...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A58"
        },
        [12013437] = {
          Content = "好啦，还差最后一片烛阴鳞就可以收工啦！",
          DialogueId = 12013437,
          GUID = "1E130A82",
          SpeakNpcId = 200002,
          Subtitle = "Alright! Just one more scale, and we're done here!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A82"
        },
        [12013438] = {
          Content = "比星斗兮天阙，纳阴灵兮坟茔。孰离合兮可为，蹇谁留兮他乡？",
          DialogueId = 12013438,
          GUID = "1E130AAC",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = [[
Loftier than the stars towers the celestial gate. Restless souls drift towards graves' eternal shade. Who might decree the weaving of fates, of sunderings and partings?
Who roves forlorn, tarrying in lands beyond all chartings?]],
          VoiceName = "voice/$Locale$/story/1201/120134/1E130AAC"
        },
        [12013439] = {
          Camera = "234.427734,226.169922,38.391602,0.000054,8.448527,-130.795746,11.88,100000.0,false,Manual,2.8",
          Content = "小仆从，你怎么自顾自地往这个方向走了？这里空荡荡的，什么都没有的样子……",
          DialogueId = 12013439,
          GUID = "1E130AD6",
          NextDialogue = 12013457,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, why are you going this way? There's nothing here...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130AD6"
        },
        [12013440] = {
          Content = "……小仆从，我相信你。这么难懂的语句，绝对不是随随便便就能想出来的。",
          DialogueId = 12013440,
          GUID = "1E130B00",
          NextDialogue = 12013441,
          SpeakNpcId = 200002,
          Subtitle = "...Little Minion, I believe you. There's no way you could've made up something that cryptic.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B00"
        },
        [12013441] = {
          Content = "但是，这个家伙选择和我们说话算是白费力气了，压根一个字都听不懂嘛。",
          DialogueId = 12013441,
          GUID = "1E130B2A",
          NextDialogue = 12013442,
          SpeakNpcId = 200002,
          Subtitle = "But why would they bother speaking to us if we can't make heads or tails of it?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B2A"
        },
        [12013442] = {
          Content = "——喂，想和我们说话的家伙，无论你是谁，希望你可以说得再直白一点！",
          DialogueId = 12013442,
          GUID = "1E130B54",
          NextDialogue = 12013443,
          SpeakNpcId = 200002,
          Subtitle = "—Hey! Whoever you are up there! If you're gonna talk to us, at least say it in words we can actually understand!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B54"
        },
        [12013443] = {
          Camera = "1502.039062,552.960938,672.550781,0.000055,22.248343,-38.19368,11.88,100000.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 12013443,
          FinalCamera = "1502.039062,552.960938,672.550781,0.000055,22.248343,-38.19368,11.88,100000.0,false,Manual,2.8",
          GUID = "1E130B7E",
          SpeakNpcId = 100001,
          Subtitle = "...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B7E"
        },
        [12013444] = {
          DialogueId = 12013444,
          GUID = "1E130BA8",
          NextDialogue = 12013445,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130BA8"
        },
        [12013445] = {
          Content = "群玄啸鸣，灾愆降世……",
          DialogueId = 12013445,
          GUID = "1E130BD2",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "The beasts howl in chorus. Calamity descends upon the mortal realm...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130BD2"
        },
        [12013446] = {
          Camera = "234.427734,226.169922,38.391602,0.000054,8.448527,-130.795746,11.88,100000.0,false,Manual,2.8",
          Content = "……！！",
          DialogueId = 12013446,
          GUID = "1E130BFC",
          NextDialogue = 12013447,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130BFC"
        },
        [12013447] = {
          Content = "哇——我只是随便喊喊，没想到真的奏效了，不愧是本魔王大人！",
          DialogueId = 12013447,
          GUID = "1E130C26",
          NextDialogue = 12013448,
          SpeakNpcId = 200002,
          Subtitle = "Whoa—! No way! I was just messing around, but it actually worked? Ha! That's the power of the Demon King!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130C26"
        },
        [12013448] = {
          Content = "小仆从，所以那个声音对你说了什么？",
          DialogueId = 12013448,
          GUID = "1E130C50",
          NextDialogue = 12013449,
          SpeakNpcId = 200002,
          Subtitle = "So? What did that voice say this time?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130C50"
        },
        [12013449] = {
          Content = "我不太确定……但是我好像看见了……很多玄色狴犴，在围攻……百年春。而且，我有一种预感，这是即将发生的事情……<W>是预言</>！",
          DialogueId = 12013449,
          GUID = "1E130C7A",
          NextDialogue = 12013450,
          SpeakNpcId = 100001,
          Subtitle = "I... I'm not entirely sure, but I saw... countless Sable Bi'an... swarming EverSpring. And I've got a feeling... it wasn't just some dream. It felt like a prophecy — something that could happen at any moment!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130C7A"
        },
        [12013450] = {
          Content = "哎？！",
          DialogueId = 12013450,
          GUID = "1E130CA4",
          NextDialogue = 12013451,
          SpeakNpcId = 200002,
          Subtitle = "What!?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CA4"
        },
        [12013451] = {
          Content = "白，情况紧急，我们先赶回百年春看看吧。希望我的预感不要应验……",
          DialogueId = 12013451,
          GUID = "1E130CCE",
          SpeakNpcId = 100001,
          Subtitle = "Snow, we need to get back to EverSpring now. Let's just hope I'm wrong... and this never comes to pass.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CCE"
        },
        [12013452] = {
          Camera = "244.181824,388.453522,209.890625,0.000027,-17.815693,-123.119537,35.0,647.922363,false,DoNotOverride,22.0",
          Content = "看见眼前这些尘漠了吗？这便是尘漠石海变成现今样貌的罪魁祸首。",
          DialogueId = 12013452,
          FacialId = {
            [1] = "210014:CM_Sad01"
          },
          FinalCamera = "146.362381,214.138016,192.261719,0.000026,-18.815668,-124.320526,35.0,647.922363,false,DoNotOverride,22.0",
          GUID = "1E130CCF",
          NextDialogue = 12013453,
          SpeakNpcId = 210014,
          Subtitle = "See the Gritblight before us? This is what transformed the place into its current state.",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CCF"
        },
        [12013453] = {
          Content = "试试用牵机方枢吸收尘漠吧。",
          DialogueId = 12013453,
          GUID = "1E130CD0",
          SpeakNpcId = 210014,
          Subtitle = "Give it a try, use the Mechanical Nexus to draw in the Gritblight.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD0"
        },
        [12013454] = {
          Camera = "628.248047,360.278137,60.518555,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          Content = "悟性不错，孺子可教也!",
          DialogueId = 12013454,
          FacialId = {
            [1] = "210014:CM_Smile01"
          },
          FinalCamera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "1E130CD1",
          NextDialogue = 12013455,
          SpeakNpcId = 210014,
          Subtitle = "Ah, that was quick! You show great promise.",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD1"
        },
        [12013455] = {
          Camera = "37.220299,11.483425,-280.212891,0.000085,30.816399,-128.115143,23.740538,100000.0,false,DoNotOverride,2.8",
          Content = "既然如此，不如再来试试我这匠心打造的独家机枢机关吧！这其中的诀窍你能掌握吗？",
          DialogueId = 12013455,
          FinalCamera = "-140.37941,-214.903625,-200.674316,0.000085,30.816399,-128.115158,23.740538,100000.0,false,DoNotOverride,2.8",
          GUID = "1E130CD2",
          NextDialogue = 12013456,
          SpeakNpcId = 210014,
          Subtitle = "Then perhaps you might try this unique device, a product of my personal craft. Do you have the wit to master its trick?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD2"
        },
        [12013456] = {
          Content = "若能顺利解开这道机关，其中的宝箱便作为见面礼赠予你二人了。",
          DialogueId = 12013456,
          GUID = "1E130CD3",
          SpeakNpcId = 210014,
          Subtitle = "If you can successfully solve this puzzle, the treasure inside shall be my gift to you both.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD3"
        },
        [12013457] = {
          Content = "（白听不到刚才的声音……难道说，又是与诫碑那时相同的情况？）",
          DialogueId = 12013457,
          DisableMouth = 1,
          GUID = "1E130AD7",
          NextOptions = {
            [1] = 120134391
          },
          SpeakNpcId = 100001,
          Subtitle = "(Snow didn't seem to hear it... Was it like what happened at the stele...?)",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A2E"
        },
        [12013501] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "您二位终于出来了——奉我们家老板的命令，冯某已在此恭候多时了。",
          DialogueId = 12013501,
          FacialId = {
            [1] = "210010:Cin_Happy01",
            [2] = "100001:Unhappy01",
            [3] = "200002:Unhappy02"
          },
          GUID = "1E131502",
          LookAt = {
            [1] = "100001:n(210010)",
            [2] = "200002:n(210010)"
          },
          NextOptions = {
            [1] = 120135011,
            [2] = 120135012
          },
          SpeakNpcId = 210010,
          Subtitle = "Ah! There you are. I've been waiting here on behalf of my boss.",
          TalkActionId = {
            [1] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131502"
        },
        [12013504] = {
          Content = "哎，哎——贵客您别走啊！",
          DialogueId = 12013504,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E131580",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12013505,
          SpeakNpcId = 210010,
          Subtitle = "Hey! Please — don't go! At least hear me out!",
          TurnTo = {
            [1] = "100001:p(120)"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131580"
        },
        [12013505] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "找我什么事？",
          DialogueId = 12013505,
          GUID = "1E1315AA",
          LookAt = {
            [1] = "200002:n(210010)"
          },
          NextDialogue = 12013506,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100001:n(210010)"}},
PlayAnimation{ActorId{100001},AnimationId{"ConfidentLR_Start"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "What do you want?",
          TalkActionId = {
            [1] = "210010:Explain02_End"
          },
          TurnTo = {
            [1] = "100001:n(210010)"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1315AA"
        },
        [12013506] = {
          Content = "白和小仆从的时间可是很宝贵的！只能给你一分钟……不对，三十秒的时间！",
          DialogueId = 12013506,
          GUID = "1E1315D4",
          NextDialogue = 12013507,
          SpeakNpcId = 200002,
          Subtitle = "Our time's precious, you know! You've got one minute... no, thirty seconds! Make it count!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1315D4"
        },
        [12013507] = {
          Content = "我们家老板看中了{nickname}的身手，想邀请二位共襄义举，参加一场围猎行动。",
          DialogueId = 12013507,
          GUID = "1E1315FE",
          NextDialogue = 120135070,
          SpeakNpcId = 210010,
          Subtitle = "My boss was deeply impressed by your prowess, . He wishes to invite you both to join him on a hunting expedition.",
          TalkActionId = {
            [1] = "210010:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1315FE"
        },
        [12013509] = {
          Content = "我们很熟吗？",
          DialogueId = 12013509,
          GUID = "1E131652",
          NextDialogue = 12013510,
          SpeakNpcId = 100001,
          Subtitle = "Do we even know each other?",
          TalkActionId = {
            [1] = "100001:ConfidentLRToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131652"
        },
        [12013510] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "您这话说的，这不是不打不相识吗？在冯某看来，已经和两位一见如故，简直是多年故交了！",
          DialogueId = 12013510,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E13167C",
          LookAt = {
            [1] = "210010:n(100001)"
          },
          NextDialogue = 12013511,
          SpeakNpcId = 210010,
          Subtitle = "Oh, come now! As the saying goes, \"A good brawl makes for fast friends.\" In my eyes, we're practically old acquaintances already.",
          TalkActionId = {
            [1] = "100001:ConfidentLRToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13167C"
        },
        [12013511] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "……",
          DialogueId = 12013511,
          GUID = "1E1316A6",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12013512,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "210010:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1316A6"
        },
        [12013512] = {
          Content = "……",
          DialogueId = 12013512,
          GUID = "1E1316D0",
          NextDialogue = 12013513,
          SpeakNpcId = 200002,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120135/1E1316D0"
        },
        [12013513] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "好了好了。俗话说得好，无恒久之友，亦无恒久之敌。这天下熙熙，皆为利来利往。只有利益永流转呀——",
          DialogueId = 12013513,
          GUID = "1E1316FA",
          LookAt = {
            [1] = "100001:n(210010)",
            [2] = "200002:n(210010)"
          },
          NextDialogue = 12013514,
          SpeakNpcId = 210010,
          Subtitle = "Alright, alright. Let me put it this way: \"There are no eternal friends, nor lasting foes — only the bond built on shared interests endures.\" That's the way of this world.",
          TalkActionId = {
            [1] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1316FA"
        },
        [12013514] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "听你话里的意思，你能拿出让我心动的报酬？",
          DialogueId = 12013514,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "210010:Cin_Smile01"
          },
          GUID = "1E131724",
          NextDialogue = 12013515,
          SpeakNpcId = 100001,
          Subtitle = "So... you're saying there's something in it for me?",
          TalkActionId = {
            [1] = "100001:ConfidentLRToTalk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131724"
        },
        [12013515] = {
          Camera = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
          Content = "钱自不用说。我们家老板一向出手慷慨。",
          DialogueId = 12013515,
          FacialId = {
            [1] = "200002:Curious"
          },
          GUID = "1E13174E",
          NextDialogue = 12013516,
          SpeakNpcId = 210010,
          Subtitle = "Of course. Money, for starters — our boss is nothing if not generous.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13174E"
        },
        [12013516] = {
          Content = "还有一项报酬，想必是合您心意的……",
          DialogueId = 12013516,
          GUID = "1E131778",
          NextDialogue = 12013517,
          SpeakNpcId = 210010,
          Subtitle = "But there's another reward... one that might pique your interest even more.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E131778"
        },
        [12013517] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "说来听听。",
          DialogueId = 12013517,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "200002:Smile01"
          },
          GUID = "1E1317A2",
          NextDialogue = 12013518,
          SpeakNpcId = 100001,
          Subtitle = "Let's hear it then.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1317A2"
        },
        [12013518] = {
          Content = "您或许不知，我们家老板的生意足迹遍布世界各地，与海伯利亚帝国也有盘根错节的联系……您可曾听说过格林威治考古协会？",
          DialogueId = 12013518,
          GUID = "1E1317CC",
          NextDialogue = 12013519,
          RelatedWikiId = {
            [1] = 406005
          },
          SpeakNpcId = 210010,
          Subtitle = "You may not know this, but our boss's dealings stretch far and wide — all the way to the Hyperborean Empire. Ever heard of the Greenwich Archaeological Society?",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1317CC"
        },
        [12013519] = {
          Camera = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
          Content = "哇，我听卡米拉讲过！那是一个号称要让古迹重见天日的组织，很有名的！",
          DialogueId = 12013519,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E1317F6",
          NextDialogue = 12013520,
          SpeakNpcId = 200002,
          Subtitle = "Oh! Camilla told me about them! They're famous for bringing ancient relics back to the light!",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1317F6"
        },
        [12013520] = {
          Camera = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
          Content = "呵呵，我家老板就是它背后的投资人之一。",
          DialogueId = 12013520,
          FacialId = {
            [1] = "210010:Cin_Happy01"
          },
          GUID = "1E131820",
          NextDialogue = 12013521,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210010,
          Subtitle = "Hehe... Well, our boss is one of their key backers.",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131820"
        },
        [12013521] = {
          Camera = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
          Content = "哎？！传闻中从不露面的格林威治考古协会幕后金主……竟然就藏在华胥！",
          DialogueId = 12013521,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,60,374.245361,false,DoNotOverride,2.8",
          GUID = "1E13184A",
          NextDialogue = 12013522,
          SpeakNpcId = 200002,
          Subtitle = "Wait — you're saying the mysterious backer of the Greenwich Archaeological Society is right here in Huaxu!?",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120135/1E13184A"
        },
        [12013522] = {
          Camera = "49.970024,127.262115,278.185547,0.000111,-6.199612,60.402637,35.0,190.711807,false,DoNotOverride,2.8",
          Content = "{nickname}，您在找某位失散的朋友，对吧？",
          DialogueId = 12013522,
          GUID = "1E131874",
          NextDialogue = 12013523,
          SpeakNpcId = 210010,
          Subtitle = ", you're searching for someone dear to you, aren't you?",
          TalkActionId = {
            [1] = "200002:Excited01_End",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131874"
        },
        [12013523] = {
          Camera = "34.974609,-135.861816,425.904297,0.000123,-26.199484,77.799515,35.0,491.753998,false,DoNotOverride,2.8",
          Content = "……你怎么知道的？",
          DialogueId = 12013523,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "1E13189E",
          NextDialogue = 12013524,
          SpeakNpcId = 100001,
          Subtitle = "...How do you know about that?",
          TalkActionId = {
            [1] = "100001:Shock04_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13189E"
        },
        [12013524] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "我如何知道这件事不要紧。要紧的是，考古协会提供的情报和人脉，在日后某一天说不定就能成为您达成心愿的助力。",
          DialogueId = 12013524,
          GUID = "1E1318C8",
          NextDialogue = 120135070,
          SpeakNpcId = 210010,
          Subtitle = "That's not important. What matters is — the connections and information the Society holds might one day prove invaluable to your search.",
          TalkActionId = {
            [1] = "100001:Shock04_End",
            [2] = "210010:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1318C8"
        },
        [12013526] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "人们总是对我们黑市中人有些偏见，冯某十分理解。",
          DialogueId = 12013526,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "210010:CM_Idle"
          },
          GUID = "1E13191C",
          NextDialogue = 12013528,
          SpeakNpcId = 210010,
          Subtitle = "I understand your misgivings. We black market folk have quite the reputation, I know.",
          TalkActionId = {
            [1] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13191C"
        },
        [12013528] = {
          Content = "但就算是我们，也会有一颗保卫家园的拳拳之心，偶尔想做些为民除害的好事！",
          DialogueId = 12013528,
          GUID = "1E131970",
          NextDialogue = 12013529,
          SpeakNpcId = 210010,
          Subtitle = "But even in our line of work, there are times when one must stand up for one's homeland... to rid it of certain threats.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E131970"
        },
        [12013529] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "……听起来更可疑了。",
          DialogueId = 12013529,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "200002:Doubt01"
          },
          GUID = "1E13199A",
          NextDialogue = 12013530,
          SpeakNpcId = 100001,
          Subtitle = "...You only made it sound even fishier.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13199A"
        },
        [12013530] = {
          Camera = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
          Content = "况且，这行动是止流掌柜嘱托给我们老板的，也是化解烛阴之灾布局的一子呢。",
          DialogueId = 12013530,
          GUID = "1E1319C4",
          NextDialogue = 12013531,
          SpeakNpcId = 210010,
          Subtitle = "Well, full disclosure: this request came directly from Proprietress Zhiliu herself. This hunt is but one part of her plan to resolve the Scourge of Zhuyin. My boss is simply fulfilling her commission.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E1319C4"
        },
        [12013531] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "……止流的委托？好吧。“猎物”是什么？",
          DialogueId = 12013531,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E1319EE",
          NextDialogue = 12013532,
          SpeakNpcId = 100001,
          Subtitle = "...Zhiliu's request? Fine. I'll bite. So what exactly are we hunting?",
          VoiceName = "voice/$Locale$/story/1201/120135/1E1319EE"
        },
        [12013532] = {
          Content = "这个冯某暂时无法透露，您可以视为玄色狴犴的同类。",
          DialogueId = 12013532,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E131A18",
          NextDialogue = 12013533,
          SpeakNpcId = 210010,
          Subtitle = "I'm afraid I can't say just yet. Let's just say it shares kinship with the Sable Bi'an.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E131A18"
        },
        [12013533] = {
          Content = "等您看到了再决定也不迟。毕竟，您随时有退出的权利。",
          DialogueId = 12013533,
          GUID = "1E131A42",
          NextDialogue = 120135070,
          SpeakNpcId = 210010,
          Subtitle = "When you see it with your own eyes, you can decide then. There's no obligation — you're free to walk away at any time.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131A42"
        },
        [12013534] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          Content = "……我先跟你们去看看吧。",
          DialogueId = 12013534,
          GUID = "1E131A6C",
          NextDialogue = 12013535,
          SpeakNpcId = 100001,
          Subtitle = "...Alright. I'll come along and see for myself.",
          TalkActionId = {
            [1] = "100001:Talk01_Start",
            [2] = "210010:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131A6C"
        },
        [12013535] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          Content = "这就好，不枉冯某费这一番口舌！",
          DialogueId = 12013535,
          FacialId = {
            [1] = "210010:Cin_Happy01"
          },
          GUID = "1E131A96",
          NextDialogue = 12013536,
          SpeakNpcId = 210010,
          Subtitle = "Excellent! I knew you were someone of keen vision.",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131A96"
        },
        [12013536] = {
          Content = "待您有空时，去沉船内找我们老板就好。等您来了，万事俱备，我们再开始！",
          DialogueId = 12013536,
          GUID = "1E131AC0",
          NextDialogue = 12013537,
          SpeakNpcId = 210010,
          Subtitle = "When you're ready, come to the shipwreck. The boss awaits — and once you arrive, we shall lead you to the hunting ground.",
          TalkActionId = {
            [1] = "210010:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131AC0"
        },
        [12013537] = {
          Content = "那冯某就先告退啦。",
          DialogueId = 12013537,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E131AEA",
          SpeakNpcId = 210010,
          Subtitle = "Now then, I'll take my leave.",
          TalkActionId = {
            [1] = "210010:Salute_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131AEA"
        },
        [12013601] = {
