          Content = "……抱歉，引起你的伤心事了。",
          DialogueId = 12014015,
          FinalCamera = "-169.812134,-160.684509,126.569336,0.000095,7.202011,90.234421,45.000023,134.189529,false,Manual,10.0",
          GUID = "1E136956",
          NextDialogue = 12014016,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I didn't mean to stir old grief.",
          TalkActionId = {
            [1] = "210013:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136956"
        },
        [12014016] = {
          Content = "我明白了，我会郑重考虑你的这番话。",
          DialogueId = 12014016,
          FacialId = {
            [1] = "210013:SpecialSmile"
          },
          GUID = "1E136980",
          NextDialogue = 12014017,
          SpeakNpcId = 210013,
          Subtitle = "I understand. I'll take your words to heart.",
          TalkActionId = {
            [1] = "210013:AgreeHead",
            [2] = "200002:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136980"
        },
        [12014017] = {
          Camera = "-333.198242,-92.549561,186.976562,0.000109,-17.397945,13.034511,40.000011,340.723328,false,Manual,8.0",
          Content = "这样才对嘛！小仆从，没想到你的口才这么好，不愧是本魔王最得力的跟班！",
          DialogueId = 12014017,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "-335.535034,-82.232544,186.976562,0.000107,-17.197903,11.034736,40.000011,340.337952,false,Manual,8.0",
          GUID = "1E1369AA",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 12014018,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200002:n(210013)"}},
LookAt{_delay{1.1},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{4.1},ActorId{200002},AnimationId{"Excited03_End"},Duration{1}},
PlayAnimation{_delay{7},ActorId{200002},AnimationId{"Excited02_Start"},Duration{1}},
PlayFacial{_delay{7.5},ActorId{200002},FacialId{"Happy02"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Now that's more like it! Didn't know you had the gift of gab, Little Minion — no wonder you're my number-one sidekick!",
          TalkActionId = {
            [1] = "200002:Excited03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E1369AA"
        },
        [12014018] = {
          Camera = "-530.71698,-475.512299,272.475586,0.000107,-15.798446,48.637161,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "……",
          DialogueId = 12014018,
          FacialId = {
            [1] = "210013:Sad03",
            [2] = "210056:Cin_Pain01"
          },
          FinalCamera = "-530.71698,-475.512299,272.475586,0.000108,-19.598326,51.03717,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1369D4",
          LookAt = {
            [1] = "200002:p(BP_FixSimple_37_fushu02)",
            [2] = "210013:n(210013)",
            [3] = "100001:n(210013)"
          },
          NextDialogue = 12014019,
          Scripts = "LookAt{_delay{1.1},LookAtDescription{\"100001:p(BP_FixSimple_37_fushu02)\"}}",
          SpeakNpcId = 210056,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200002:Excited02_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "210013:n(210056)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E1369D4"
        },
        [12014019] = {
          Content = "她要醒了吗？！",
          DialogueId = 12014019,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E1369FE",
          NextDialogue = 12014020,
          SpeakNpcId = 200002,
          Subtitle = "Is she waking up?",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E1369FE"
        },
        [12014020] = {
          Camera = "-304.054077,-171.641968,145.578125,5.001599,-42.596004,111.247818,40.0,126.781067,false,Manual,6.839206",
          Content = "阿娘，是你回来了吗……女儿好冷……",
          DialogueId = 12014020,
          FinalCamera = "-308.513123,-160.168503,134.261719,5.001599,-42.596004,111.247818,40.0,111.219002,false,Manual,6.839206",
          GUID = "1E136A28",
          NextDialogue = 12014021,
          SpeakNpcId = 210056,
          Subtitle = "Mama... is that you? I'm so cold...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A28"
        },
        [12014021] = {
          Camera = "-66.014252,-35.105202,167.732422,5.00001,-18.596672,-167.155045,30.0,268.570251,false,Manual,6.839206",
          Content = "……看来，只是梦中呓语。",
          DialogueId = 12014021,
          FinalCamera = "-63.524422,-45.636681,166.837891,5.000161,-18.996737,-171.154877,30.0,268.570251,false,Manual,6.839206",
          GUID = "1E136A52",
          NextDialogue = 12014022,
          SpeakNpcId = 210013,
          Subtitle = "...Just a dream, it seems.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A52"
        },
        [12014022] = {
          Content = "她的伤势现在怎么样了？",
          DialogueId = 12014022,
          GUID = "1E136A7C",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014023,
          SpeakNpcId = 100001,
          Subtitle = "How is she doing?",
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A7C"
        },
        [12014023] = {
          Camera = "-72.462227,-96.764427,124.28125,0.000125,9.403216,154.049149,35.000008,137.232391,false,Manual,6.0",
          Content = "暂时稳定下来了。但狴犴的力量还在持续侵蚀她的筋脉，她一时半会恐怕无法醒转。",
          DialogueId = 12014023,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "-74.948547,-101.871399,124.28125,0.000135,9.403216,152.449646,35.000011,127.589622,false,Manual,6.0",
          GUID = "1E136AA6",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12014024,
          SpeakNpcId = 210013,
          Subtitle = "She's stable for now. But the Bi'an's power still gnaws at her meridians. I fear it will be some time before she wakes.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AA6"
        },
        [12014024] = {
          Content = "我在家姐的笔记中查阅到了一种名为“忘忧草”的草药。它生长于此界和彼界交汇之地，药性柔和，与狴犴的刚烈相克。",
          DialogueId = 12014024,
          GUID = "1E136AD0",
          NextDialogue = 12014025,
          RelatedWikiId = {
            [1] = 301009
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3.5},TargetPosition{"-1772.944702,-1120.462158,-1462.329102,0.000139,3.182055,123.224609,25.0,3248.383545,false,Manual,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-1772.944702,-1120.462158,-1462.329102,0.000142,-9.617889,115.826202,25.0,570.544434,false,Manual,2.8"},duration{20}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "In my sister's pharmic notes, there was mention of a herb called Wangyou. It grows at the liminal crossing of this world and the next — its gentle essence said to be the perfect foil for the Bi'an's brutal energy.",
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AD0"
        },
        [12014025] = {
          Content = "以忘忧草入药，或许能调和她体内的暴虐之力，让她的病情好转。",
          DialogueId = 12014025,
          GUID = "1E136AFA",
          LookAt = {
            [1] = "210013:n(210056)"
          },
          NextDialogue = 12014026,
          SpeakNpcId = 210013,
          Subtitle = "If we use this herb in her treatment, it may soothe the violent currents within her and steady her condition.",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AFA"
        },
        [12014026] = {
          Camera = "-511.522827,-152.21167,61.43457,0.000145,8.602684,16.252649,35.000008,335.979614,false,Manual,8.60223",
          Content = "家姐研习的药石之理与我的枯荣之术虽同为治病救人之法，但原理终是不同的。我对药理只是略略懂得一些，但如今已经是唯一的法子了。",
          DialogueId = 12014026,
          FinalCamera = "-513.789429,-144.432739,61.43457,0.000145,8.602684,16.252649,35.000008,335.979614,false,Manual,8.60223",
          GUID = "1E136B24",
          LookAt = {
            [1] = "200002:n(210056)"
          },
          NextDialogue = 12014027,
          Scripts = "LookAt{_delay{11.8},LookAtDescription{\"210013:n(100001)\"}}",
          SpeakNpcId = 210013,
          Subtitle = "While my sister devoted her life to the study of herbs and medicines, I was raised in the Art of Ephemerality. Our ways share a purpose, but the paths diverge. I know little of her methods... but for now, this is the only path left to try.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B24"
        },
        [12014027] = {
          Camera = "-226.133133,-85.315811,163.748047,0.000056,-21.196583,11.054746,40.0,85.401657,false,Manual,10.0",
          Content = "那还等什么，我们赶紧走吧！",
          DialogueId = 12014027,
          FinalCamera = "-226.133133,-85.315811,163.748047,0.000056,-21.196583,11.054746,40.0,230.872345,false,Manual,10.0",
          GUID = "1E136B4E",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12014028,
          Scripts = "LookAt{_delay{1.8},LookAtDescription{\"100001:n(200002)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Then what are we waiting for? Let's go find it!",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "100001:Think_Start",
            [3] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B4E"
        },
        [12014028] = {
          Camera = "166.755264,-67.873413,51.71582,0.000071,12.00366,172.654205,40.0,353.210052,false,Manual,6.0",
          Content = "你们来得恰巧，我正准备醒来后就出门采药。若是来得晚一些，便只能错过了。",
          DialogueId = 12014028,
          FacialId = {
            [1] = "200002:Nervous",
            [2] = "210013:Smile01"
          },
          FinalCamera = "165.051727,-80.381683,51.71582,0.000071,11.803659,170.854324,40.0,352.896423,false,Manual,6.0",
          GUID = "1E136B78",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 12014029,
          Scripts = "PlayAnimation{_delay{3.01},ActorId{210013},AnimationId{\"Baiheng_Story_Special02_Start\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "You arrived at just the right moment. I was about to set out to find it myself. Had you come any later... you might have missed me altogether.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "210013:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B78"
        },
        [12014029] = {
          Camera = "-121.7556,4.822418,91.928711,0.000113,-4.796657,-10.953535,35.0,104.130783,false,Manual,8.0",
          Content = "……话说回来，那个什么什么此界彼界的玄乎地方，是哪儿来着？",
          DialogueId = 12014029,
          GUID = "1E136BA2",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014030,
          SpeakNpcId = 200002,
          Subtitle = "So — where's that place again? The one that's supposed to be between two worlds or something?",
          TalkActionId = {
            [1] = "200002:Shy03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BA2"
        },
        [12014030] = {
          Camera = "719.884644,1403.09314,144.785156,0.000114,-2.598074,-112.95311,35.000011,1652.77417,false,Manual,2.8",
          Content = "这个地方名为“虞泉”。且不论你们初来乍到，就连土生土长的华胥人，终其一生也未必去过此处呢。",
          DialogueId = 12014030,
          FinalCamera = "784.508057,1375.722168,144.785156,0.000115,-2.598074,-112.953705,35.000011,755.125061,false,Manual,2.8",
          GUID = "1E136BCC",
          NextDialogue = 12014031,
          RelatedWikiId = {
            [1] = 408013
          },
          Scripts = [[
PARA{
LookAt{LookAtDescription{"210013:n(200002)"}},
LookAt{_delay{4.1},LookAtDescription{"210013:n(100001)"}},
}]],
          SpeakNpcId = 210013,
          Subtitle = "It's called the Spring of Yu. Even those born and raised in Huaxu may never see it for themselves — let alone newcomers like you.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BCC"
        },
        [12014031] = {
          Camera = "59.27887,-13.943413,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          Content = "它由华胥独特的水土蕴养出。以无处不在的香料做引，有些人临终时的执念会化为一种叫做“无由生”的特殊生灵。",
          DialogueId = 12014031,
          FinalCamera = "60.464428,-21.080315,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          GUID = "1E136BF6",
          NextDialogue = 12014032,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          Subtitle = "It is nurtured by Huaxu's unique soil and water. When mortals perish with lingering attachments in their hearts, the ever-present perfume acts as a conduit. Those yearnings give birth to spirits known as Wishen.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BF6"
        },
        [12014032] = {
          Camera = "-147.81781,5.32869,142.967773,0.000243,-4.796145,-93.967758,35.000011,86.214539,false,Manual,7.41853",
          Content = "虞泉即为无由生的栖居之地。只有心思澄澈的儿童，或是受到它们邀请的人类，能够踏入虞泉的界域。",
          DialogueId = 12014032,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-147.885712,4.413391,142.889648,0.000242,-4.796145,-93.967621,35.000008,80.332993,false,Manual,7.41853",
          GUID = "1E136C20",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014033,
          SpeakNpcId = 210013,
          Subtitle = "The Spring of Yu is their resting ground. Only children with a pure heart — or those they choose to invite — may step into its realm.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C20"
        },
        [12014033] = {
          Camera = "-294.044525,50.440552,165.479492,0.000202,-16.597221,-20.770725,40.0,289.488281,false,Manual,6.491352",
          Content = "听起来很神奇的样子……！那我和小仆从可以去这个地方吗？",
          DialogueId = 12014033,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-294.044525,50.440552,165.479492,0.000197,-17.597284,-17.170553,40.0,289.488281,false,Manual,6.491352",
          GUID = "1E136C4A",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "200002:n(210013)"
          },
          NextDialogue = 12014034,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.1},ActorId{200002},AnimationId{"SpecialHappy_Start"},Duration{1}},
PlayFacial{_delay{2.5},ActorId{100001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wow... that sounds so mysterious! So... can my Little Minion and I get in there?",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "100001:p(-75)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C4A"
        },
        [12014034] = {
          Camera = "139.226379,128.650238,49.652344,0.000156,11.202827,-146.769257,40.0,369.932373,false,Manual,6.0",
          Content = "自然可以。跟紧了，我为你们引路。",
          DialogueId = 12014034,
          GUID = "1E136C74",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          Scripts = [[
SEQ{
LookAt{_delay{0.5},LookAtDescription{"210013:n(100001)"}},
PlayAnimation{_delay{1.1},ActorId{210013},AnimationId{"Baiheng_Story_Special01_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Of course. Stay close. I shall lead the way.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_End",
            [2] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C74"
        },
        [12014201] = {
          Content = "……未想到此处也被这些尘漠影响了。",
          DialogueId = 12014201,
          Duration = 3,
          GUID = "1E1387DA",
          NextDialogue = 12014202,
          SpeakNpcId = 210013,
          Subtitle = "...I hadn't foreseen that the Gritblight would touch even this sanctuary.",
          VoiceName = "voice/$Locale$/story/1201/120142/1E1387DA"
        },
        [12014202] = {
          Content = "放心，我有办法解决。",
          DialogueId = 12014202,
          Duration = 2,
          GUID = "1E138804",
          NextDialogue = 12014203,
          SpeakNpcId = 100001,
          Subtitle = "Don't worry. I've got this.",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138804"
        },
        [12014203] = {
          Content = "哼哼，毕竟现在白和小仆从可是出师的机枢派荣誉学徒！你就看好了！",
          DialogueId = 12014203,
          Duration = 2,
          GUID = "1E13882E",
          NextDialogue = 12014204,
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh! After all, the great Demon King and her Little Minion are now proud honorary learners of the Jishu Sect! Just watch us!",
          VoiceName = "voice/$Locale$/story/1201/120142/1E13882E"
        },
        [12014204] = {
          Content = "机枢派……？这个门派式微已久，你们怎与他们产生了交集？",
          DialogueId = 12014204,
          Duration = 2,
          GUID = "1E138858",
          NextDialogue = 12014205,
          SpeakNpcId = 210013,
          Subtitle = "The Jishu Sect...? That name has all but faded from memory. How did you come to be involved with them?",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138858"
        },
        [12014205] = {
          Content = "哼哼，这就是小说里常说的奇遇！",
          DialogueId = 12014205,
          Duration = 3,
          GUID = "1E138882",
          SpeakNpcId = 200002,
          Subtitle = "Heh! Just like one of those wild tales you hear in old legends — pure luck, I'd say!",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138882"
        },
        [12014301] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊，是白色妖怪！",
          DialogueId = 12014301,
          GUID = "1E139842",
          NextDialogue = 12014302,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! White monsters!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139842"
        },
        [12014302] = {
          Content = "呜、呜哇——谁在说话？幽灵？！救命啊，小仆从！",
          DialogueId = 12014302,
          GUID = "1E13986C",
          NextDialogue = 12014303,
          SpeakNpcId = 200002,
          Subtitle = "Eek! Wh—Who's talking!? A ghost!? Little Minion, help!!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E13986C"
        },
        [12014303] = {
          Content = "无需惊慌，小白。这就是我先前所说的<H>无由生</>。只是未受它们邀请的人看不到它们的身形。",
          DialogueId = 12014303,
          GUID = "1E139896",
          NextDialogue = 12014304,
          SpeakNpcId = 210013,
          Subtitle = "Calm yourself, Snow. This is a Wishen I spoke of. Those who have not been invited cannot see their form.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139896"
        },
        [12014304] = {
          Content = "畏生，这二位是我的朋友。我们有事拜访长老，可以请你现身，为{性别：他|她}们指明前路吗？",
          DialogueId = 12014304,
          GUID = "1E1398C0",
          NextDialogue = 12014305,
          SpeakNpcId = 210013,
          Subtitle = "Wei Shen, these two are my friends. We seek an audience with Elder Wishen. Could you reveal yourself and show them the way?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1398C0"
        },
        [12014305] = {
          Content = "扶疏的朋友？那也是畏生的朋友！",
          DialogueId = 12014305,
          GUID = "1E1398EA",
          NextDialogue = 12014306,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "Sure! Friends of Fushu are friends of mine!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1398EA"
        },
        [12014306] = {
          Content = "哇……这就是无由生吗？小家伙长得圆溜溜的，还挺可爱的！",
          DialogueId = 12014306,
          GUID = "1E139914",
          NextDialogue = 12014307,
          SpeakNpcId = 200002,
          Subtitle = "Whoa... so this is a Wishen? It's all round and puffy — kinda cute, actually!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139914"
        },
        [12014307] = {
          Content = "你怎不在祠台，跑到外面来了？",
          DialogueId = 12014307,
          GUID = "1E13993E",
          NextDialogue = 12014308,
          SpeakNpcId = 210013,
          Subtitle = "Why aren't you at the altar? What are you doing out here?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E13993E"
        },
        [12014308] = {
          Content = "灰茫茫的尘漠从地里生出来……灰茫茫的尘漠畔住了畏生的脚！畏生走不动，也跑不动……",
          DialogueId = 12014308,
          GUID = "1E139968",
          NextDialogue = 12014309,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "The Gritblight... it rose up from the ground... now my feet are stuck. I can't walk or run at all...",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139968"
        },
        [12014309] = {
          Content = "没能在天黑之前回家，阿娘要记挂了……",
          DialogueId = 12014309,
          GUID = "1E139992",
          NextDialogue = 12014310,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "I didn't make it home before dark... and Mama must be so worried...",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139992"
        },
        [12014310] = {
          Content = "放心吧，我们带你回家。包在白身上！",
          DialogueId = 12014310,
          GUID = "1E1399BC",
          NextDialogue = 12014311,
          SpeakNpcId = 200002,
          Subtitle = "Don't worry! We'll get you home safe and sound!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1399BC"
        },
        [12014311] = {
          Content = "家……畏生的家丢了！哪里都找不见阿娘，畏生没有地方可以去！",
          DialogueId = 12014311,
          GUID = "1E1399E6",
          NextDialogue = 12014312,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "Home... I've lost it. I looked everywhere, but I can't find Mama... I don't have anywhere to go anymore!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1399E6"
        },
        [12014312] = {
          Content = "呜哇，它怎么一下子激动了起来？",
          DialogueId = 12014312,
          GUID = "1E139A10",
          NextDialogue = 12014313,
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh... why did it get so upset all of a sudden?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A10"
        },
        [12014313] = {
          Content = "小白，让我来吧。",
          DialogueId = 12014313,
          GUID = "1E139A3A",
          NextDialogue = 12014314,
          SpeakNpcId = 210013,
          Subtitle = "Snow, let me handle this.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A3A"
        },
        [12014314] = {
          Content = "在外面待了这么久，你一定已经疲惫不堪了吧。我们先回祠台歇脚，可好？",
          DialogueId = 12014314,
          GUID = "1E139A64",
          NextDialogue = 12014315,
          SpeakNpcId = 210013,
          Subtitle = "You've lingered here far too long — you must be weary. Let us return to the altar, so you may find a moment of rest.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A64"
        },
        [12014315] = {
          Content = "……嗯！",
          DialogueId = 12014315,
          GUID = "1E139A8E",
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "...Okay!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A8E"
        },
        [12014316] = {
          Content = "姐姐带畏生回家！",
          DialogueId = 12014316,
          GUID = "1E139A8F",
          Subtitle = "Wei Shen is going home!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A8F"
        },
        [12014401] = {
          Camera = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "——谢谢你们！",
          DialogueId = 12014401,
          FinalCamera = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E13A8AA",
          NextDialogue = 12014402,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "—Thank you!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8AA"
        },
        [12014402] = {
          Camera = "154.71994,121.273628,111.300293,0.000013,4.39925,164.604019,35.000008,170.252457,false,Manual,3.826119",
          CameraBlendCurve = "easeInOutQuad",
          Content = "无由生是由执念构成的生灵。",
          DialogueId = 12014402,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "148.449249,101.440178,111.300293,0.000014,4.799225,156.803726,35.000011,170.252457,false,Manual,3.826119",
          GUID = "1E13A8D4",
          LookAt = {
            [1] = "210013:n(100001)",
            [2] = "200002:n(210013)",
            [3] = "100001:n(210013)"
          },
          NextDialogue = 12014403,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          Subtitle = "The Wishens are spirits woven from unfulfilled longings.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8D4"
        },
        [12014403] = {
          Content = "这只小无由生，大约是生前偷偷跑出家门玩耍，却不慎失足坠亡。从那之后，“回家”成为了它的执念。",
          DialogueId = 12014403,
          Duration = 1,
          GUID = "1E13A8FE",
          NextDialogue = 12014404,
          SpeakNpcId = 210013,
          Subtitle = "This little one was likely a child who slipped away to play... and met a sudden end. Ever since, \"going home\" has lingered as its last, unfulfilled wish.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8FE"
        },
        [12014404] = {
          Camera = "69.47644,193.072845,103.465088,0.000062,22.596144,-171.999283,45.000023,78.807327,false,Manual,7.461847",
          CameraBlendCurve = "easeInOutQuad",
          Content = "可惜它年纪尚幼，不记得家的方位。光阴荏苒，它的亲人大约也……无处可寻了。",
          DialogueId = 12014404,
          Duration = 1,
          FinalCamera = "66.714828,163.37291,100.481201,0.000061,24.395912,161.600143,45.000027,78.807327,false,Manual,7.461847",
          GUID = "1E13A928",
          LookAt = {
            [1] = "210013:p(BP_FixSimple_39_fushu)"
          },
          NextDialogue = 12014405,
          SpeakNpcId = 210013,
          Subtitle = "Sadly, it was far too young to remember where home lay. And now... so many seasons have passed, its family... is likely long gone.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A928"
        },
        [12014405] = {
          Camera = "95.111908,170.19989,184.635742,0.000034,-28.601601,178.796585,35.000011,248.150375,false,Manual,10.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "哇……无由生真的是幽灵！不过，好像没有故事书里写的那么可怕！还有点可怜……",
          DialogueId = 12014405,
          FacialId = {
            [1] = "200002:Curious"
          },
          FinalCamera = "94.933746,161.763794,184.635742,0.000033,-28.801596,176.59642,35.000011,248.150375,false,Manual,10.0",
          GUID = "1E13A952",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          NextDialogue = 12014406,
          Scripts = "PlayFacial{_delay{4.5},ActorId{200002},FacialId{\"Sad01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "So Wishens really are ghosts... but not the scary kind from old stories. If anything... they're a little bit sad.",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A952"
        },
        [12014406] = {
          Camera = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "此处本还有两只无由生，恐怕也被尘漠波及了。去寻觅它们的踪迹吧。",
          DialogueId = 12014406,
          FinalCamera = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E13A97C",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          Scripts = "PlayAnimation{_delay{4.5},ActorId{210013},AnimationId{\"Explain01_Start\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "There should be two more nearby. I fear the Gritblight has found them too. Come — let us search for their traces.",
          TalkActionId = {
            [1] = "200002:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A97C"
        },
        [12014501] = {
          Content = "“一二三，木头人……”",
          DialogueId = 12014501,
          Duration = 2,
          GUID = "1E13B912",
          NextDialogue = 12014502,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouShengSY",
          Subtitle = "\"One, two, three... Red Light!\"",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B912"
        },
        [12014502] = {
          Content = "山洞中应是有一只小无由生。但是落石堵住了通路……",
          DialogueId = 12014502,
          Duration = 3,
          GUID = "1E13B93C",
          NextDialogue = 12014503,
          SpeakNpcId = 210013,
          Subtitle = "There lies a little Wishen within the cave, yet the way has been sealed by fallen rocks...",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B93C"
        },
        [12014503] = {
          Content = "了解！拆迁作业小队上线喽——",
          DialogueId = 12014503,
          Duration = 2,
          GUID = "1E13B966",
          SpeakNpcId = 200002,
          Subtitle = "Got it! Time for the Demon King's demolition crew to work their magic!",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B966"
        },
        [12014601] = {
          Content = "“我们都是木头人，不许说话不许动……”",
          DialogueId = 12014601,
          Duration = 3,
          GUID = "1E13C97A",
          NextDialogue = 12014602,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "\"We're all statues... no talking, no moving...\"",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C97A"
        },
        [12014602] = {
          Content = "它在哪里呢？",
          DialogueId = 12014602,
          Duration = 1,
          GUID = "1E13C9A4",
          NextDialogue = 12014605,
          SpeakNpcId = 200002,
          Subtitle = "Where could it be?",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9A4"
        },
        [12014603] = {
          Content = "或许是这里的气味让它感到陌生，所以不愿意显现身形。",
          DialogueId = 12014603,
          Duration = 3,
          GUID = "1E13C9CE",
          SpeakNpcId = 210013,
          Subtitle = "Maybe the unfamiliar scents here make it wary, so it hides away.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9CE"
        },
        [12014604] = {
          Content = "点燃香炉试试吧，熟悉的香味能够给它带来安心感。",
          DialogueId = 12014604,
          Duration = 2,
          GUID = "1E13C9F8",
          SpeakNpcId = 210013,
          Subtitle = "Let's light the incense. The familiar fragrance may soothe it...",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9F8"
        },
        [12014605] = {
          Content = "……这里的花苞受尘漠侵蚀，散发出一股异样的香气。我想，它恐怕是因此不愿意显现身形。",
          DialogueId = 12014605,
          GUID = "1E13C9F9",
          NextDialogue = 12014606,
          SpeakNpcId = 210013,
          Subtitle = "These buds have been tainted, giving off unfamiliar scents. That might be why it refuses to show itself.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9F9"
        },
        [12014606] = {
          Content = "清除这些花苞试试看吧。",
          DialogueId = 12014606,
          GUID = "1E13CA11",
          SpeakNpcId = 210013,
          Subtitle = "Let's clear out these buds.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13CA11"
        },
        [12014701] = {
          Content = "被你找到啦！",
          DialogueId = 12014701,
          Duration = 2,
          GUID = "1E13D9E2",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "You found me!",
          VoiceName = "voice/$Locale$/story/1201/120147/1E13D9E2"
        },
        [12014801] = {
          Content = "“……我、我是木头人！你看不到我，也不能打我！”",
          DialogueId = 12014801,
          Duration = 3,
          GUID = "1E13EA4A",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "\"I—I'm a statue! You can't see me, and you can't hit me either!\"",
          VoiceName = "voice/$Locale$/story/1201/120148/1E13EA4A"
        },
        [12014802] = {
          Content = "祠台就在前面，我认得路了……谢谢你们！",
          DialogueId = 12014802,
          GUID = "1E13EA4B",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "I know the way... the altar is up ahead, thank you!",
          VoiceName = "voice/$Locale$/story/1201/120148/1E13EA4B"
        },
        [12014901] = {
          Content = "那个石碑上好像写着什么字！",
          DialogueId = 12014901,
          Duration = 2,
          GUID = "1E13FAB2",
          SpeakNpcId = 200002,
          Subtitle = "Hey! There's something written on that stone tablet!",
          VoiceName = "voice/$Locale$/story/1201/120149/1E13FAB2"
        },
        [12014902] = {
          Content = "<H>高高在上</>俯众生，<H>渐渐低下</>归于尘。无声无息随风去，谁能知晓它踪迹？",
          DialogueId = 12014902,
          GUID = "1E13FADC",
          Subtitle = "Lofty above, watching all below. Drifting down, returning to soil. Silent and unseen, swept away on the wind... Tell me — can you find its trail?",
          VoiceName = "voice/$Locale$/story/1201/120149/1E13FADC"
        },
        [12015001] = {
          Content = "别玩了，快跟着我们回去啦！",
          DialogueId = 12015001,
          Duration = 2,
          GUID = "1E140B1A",
          NextDialogue = 12015002,
          SpeakNpcId = 200002,
          Subtitle = "Come on, playtime's over! Let's go back!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B1A"
        },
        [12015002] = {
          Content = "不行，还没有玩够！谜底，必须先解开谜底才可以！",
          DialogueId = 12015002,
          Duration = 3,
          GUID = "1E140B44",
          NextDialogue = 12015003,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Uh-uh! Not until you solve my riddle!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B44"
        },
        [12015003] = {
          Content = "真是头疼……这是什么意思呢，{nickname}？",
          DialogueId = 12015003,
          Duration = 2,
          GUID = "1E140B6E",
          NextDialogue = 12015004,
          SpeakNpcId = 200002,
          Subtitle = "Ugh, this is giving me a headache... , any idea?",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B6E"
        },
        [12015004] = {
          Content = "“高高在上，渐渐低下”……我想，或许这些花苞需要用自上而下的顺序击打才可以？",
          DialogueId = 12015004,
          GUID = "1E140B6F",
          NextDialogue = 12015005,
          SpeakNpcId = 210013,
          Subtitle = "\"Lofty above, drifting down\"... I suppose, maybe we need to hit the buds from top to bottom?",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B6F"
        },
        [12015005] = {
          Content = "有道理哦，小仆从，我们赶紧试试！",
          DialogueId = 12015005,
          GUID = "1E140B71",
          SpeakNpcId = 200002,
          Subtitle = "Ooh, that makes sense! Let's try it, Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B71"
        },
        [12015101] = {
          Camera = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
          Content = "怎么样，你们现在有答案了吗？",
          DialogueId = 12015101,
          FinalCamera = "427.964111,58.333099,126.54541,0.0,0.0,178.205566,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E141B82",
          LookAt = {
            [1] = "100001:n(210013)",
            [2] = "100001:n(210039)"
          },
          NextDialogue = 12015102,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Do you have the answer for me now?",
          TalkActionId = {
            [1] = "210039:Wuyou_Born"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120151/1E141B82"
        },
        [12015102] = {
          Camera = "-296.378662,-545.068665,191.578613,0.000033,-5.400473,67.00705,40.000023,644.465149,false,Manual,8.26397",
          Content = "俯瞰众生，却又渺无形踪，归于尘土……你想说的或许是云朵吧。",
          DialogueId = 12015102,
          FinalCamera = "-331.210388,-529.07074,191.578613,0.000035,-5.400439,63.406521,40.000023,644.465149,false,Manual,8.26397",
          GUID = "1E141BAC",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015103,
          Scripts = "LookAt{_delay{3.1},LookAtDescription{\"210013:n(210039)\"}}",
          SpeakNpcId = 210013,
          Subtitle = "Gazing down from above, yet returning to the soil without a trace... I would say you speak of the clouds.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "210013:Shy03_Start",
            [3] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120151/1E141BAC"
        },
        [12015103] = {
          Camera = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
          Content = "嘻嘻，姐姐真聪明！我尽兴啦，我们回去吧！",
          DialogueId = 12015103,
          FinalCamera = "427.964111,58.333099,126.54541,0.0,0.0,178.205566,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E141BD6",
          LookAt = {
            [1] = "100001:n(210039)"
          },
          Scripts = "PlayAnimation{_delay{4.1},ActorId{210039},AnimationId{\"Wuyou_Disappear\"},Duration{1}}",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Heehee! You're really smart, Miss Fushu! That was fun — okay, let's head back!",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "210039:Wuyou_Agree",
            [3] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120151/1E141BD6"
        },
        [12015201] = {
          Camera = "920.312744,232.194031,104.525879,0.000081,-0.59857,-171.306732,30.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "终于找齐了三个小无由生……真是把魔王大人累得够呛！",
          DialogueId = 12015201,
          FacialId = {
            [1] = "200002:Syouganai01"
          },
          FinalCamera = "935.710205,90.954773,104.525879,0.000081,-0.59857,-176.506149,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E142BEA",
          NextDialogue = 12015202,
          Scripts = "PlayAnimation{_delay{3.01},ActorId{200002},AnimationId{\"BaiTX_Story_Tired_End\"},Duration{1}},\n",
          SpeakNpcId = 200002,
          Subtitle = "Finally found all three of the little Wishens... This Demon King's worn out!",
          TalkActionId = {
            [1] = "200002:BaiTX_Story_Tired_Loop"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120152/1E142BEA"
        },
        [12015202] = {
          Camera = "38.708542,27.845192,156.223022,0.000037,4.201495,162.893906,30.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "听好了，从现在起，你们都乖乖待在这里，不许说话，也不许乱跑！",
          DialogueId = 12015202,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "99.139954,-31.090532,153.350342,0.000036,2.801416,161.096512,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E142C14",
          LookAt = {
            [1] = "200002:n(210038)"
          },
          NextDialogue = 12015203,
          SpeakNpcId = 200002,
          Subtitle = "Listen up, you three! From now on — no more chattering or sneaking off! Stay right here, got it?",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120152/1E142C14"
        },
        [12015203] = {
          Content = "好啦，小白，莫再逗弄它们了。小心它们生气，不愿为你叩响通往虞泉的门扉。",
          DialogueId = 12015203,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E142C3E",
          LookAt = {
            [1] = "200002:n(210013)"
          },
          NextDialogue = 12015204,
          SpeakNpcId = 210013,
          Subtitle = "Do not tease them further, Snow. If you upset them, they may refuse to open the gate to the Spring of Yu for you.",
          TalkActionId = {
            [1] = "200002:Confident_End",
            [2] = "210013:Explain01_Start",
            [3] = "100001:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120152/1E142C3E"
        },
        [12015204] = {
          Camera = "133.228226,-647.736572,205.264771,0.000173,-8.198883,105.089806,30.000002,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你的意思是……我们还没有抵达真正的虞泉？",
          DialogueId = 12015204,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "155.219604,-729.304077,217.437256,0.000173,-8.198883,105.089806,30.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1E142C68",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Wait, what!? You mean... we're not there yet?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:Shy03_Start",
            [3] = "210013:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120152/1E142C68"
        },
        [12015301] = {
          Content = "哇……！",
          DialogueId = 12015301,
          GUID = "1E143C52",
          SpeakNpcId = 200002,
          Subtitle = "Whoa...!",
          VoiceName = "voice/$Locale$/story/1201/120153/1E143C52"
        },
        [12015401] = {
          Content = "呜，姐姐……姐姐不见了……",
          DialogueId = 12015401,
          GUID = "1E144CBA",
          SnapShot = "WUYOU",
          SpeakNpcId = 210019,
          Subtitle = "*sobbing*... Big sis... where are you...?",
          VoiceName = "voice/$Locale$/story/1201/120154/1E144CBA"
        },
        [12015402] = {
          Content = "在你们面前，一个异样又光怪陆离的，属于无由生那一边的世界，徐徐展开……",
          DialogueId = 12015402,
          GUID = "1E144CBB",
          Subtitle = "Before you unfolds a realm both strange and wondrous — a world that belongs to Wishen, veiled yet vast."
        },
        [12015501] = {
          Camera = "362.349304,617.265076,20.103271,0.000049,3.644691,-117.98333,30.0,50.546654,false,Manual,13.930334",
          CameraBlendCurve = "easeInOutQuad",
          Content = "果然，只要还能晒太阳的日子足够久，便能好事常在，笑口常开。",
          DialogueId = 12015501,
          FinalCamera = "379.79364,607.996277,20.103271,0.000049,3.644691,-117.983383,30.000002,548.337769,false,Manual,13.930334",
          GUID = "1E145D22",
          LookAt = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          NextDialogue = 12015502,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Ah... so long as we can keep basking in the sun, the days will stay warm, and our smiles will never fade.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145D22"
        },
        [12015502] = {
          Camera = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我这把老骨头还能见到故知，值了。祝由大人，还有两位化外之客。幸会！",
          DialogueId = 12015502,
          FinalCamera = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E145D4C",
          NextDialogue = 12015503,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "To behold an old friend once more — such fortune in this lifetime. Lady Zhuyou. Travellers from beyond. Welcome.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145D4C"
        },
        [12015503] = {
          Camera = "-357.707886,104.663635,262.303223,0.000057,-18.755178,-8.789527,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "您太客气了，扶疏当不起这个尊称。",
          DialogueId = 12015503,
          FinalCamera = "-357.707886,104.663635,262.303223,0.000051,-20.955013,-7.790245,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E145D76",
          NextDialogue = 12015504,
          SpeakNpcId = 210013,
          Subtitle = "You honour me too greatly, Elder — I am unworthy of such a title.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special01_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145D76"
        },
        [12015504] = {
          Content = "呵呵……百年之前的疫疠，在下受过祝由大人的恩惠，没齿难忘。几位有什么需要尽管开口。",
          DialogueId = 12015504,
          FacialId = {
            [1] = "200002:Nervous"
          },
          GUID = "1E145DA0",
          NextDialogue = 12015505,
          RelatedWikiId = {
            [1] = 401004
          },
          Scripts = [[
SEQ{
LookAt{_delay{6.1},LookAtDescription{"200002:n(210013)"}},
LookAt{_delay{2.1},LookAtDescription{"200002:n(210040)"}},
PlayAnimation{delay{1.5},ActorId{200002},AnimationId{"Think_End"},Duration{1}}
}]],
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Hehe... A century ago, in the days of pestilence, it was your healing hands that spared my life. That kindness has never faded from my heart, Lady Zhuyou. Pray, tell me what you would ask of me.",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "210013:Baiheng_Story_Special01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145DA0"
        },
        [12015505] = {
          Camera = "115.516785,197.20285,91.707275,0.000133,-32.198425,-53.396206,30.0,140.374573,false,Manual,8.366085",
          CameraBlendCurve = "easeInOutQuad",
          Content = "等等，小仆从，你不觉得他们的交谈有哪里不对劲吗？！",
          DialogueId = 12015505,
          FinalCamera = "105.107033,219.02327,94.781616,0.000144,-27.398195,-54.795994,30.0,166.458572,false,Manual,11.745219",
          GUID = "1E145DCA",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          NextOptions = {
            [1] = 120155051,
            [2] = 120155052
          },
          SpeakNpcId = 200002,
          Subtitle = "Wait a second, Little Minion... did you hear what he said? Notice anything weird!?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145DCA"
        },
        [12015507] = {
          Content = "你没有听明白吗小仆从！按他话里的意思，扶疏至少活了一百年那么久！",
          DialogueId = 12015507,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E145E1E",
          NextDialogue = 12015509,
          SpeakNpcId = 200002,
          Subtitle = "Didn't you catch that!? He said Fushu's been around for over a hundred years!",
          VoiceName = "voice/$Locale$/story/1201/120155/1E145E1E"
        },
        [12015509] = {
          Camera = "105.107033,219.02327,94.781616,0.000144,-27.398195,-54.795994,30.0,166.458572,false,Manual,11.745219",
          CameraBlendCurve = "easeInOutQuad",
          Content = "压根就看不出来！原来华胥的医术已经进化到长生不老的水平了吗？！",
          DialogueId = 12015509,
          FinalCamera = "131.587952,179.929916,89.484497,0.000167,-4.597933,-58.195728,30.0,166.458572,false,Manual,11.745219",
          GUID = "1E145E72",
          LookAt = {
            [1] = "200002:n(210013)",
            [2] = "100001:n(210013)"
          },
          NextDialogue = 12015510,
          Scripts = [[
SEQ{
LookAt{delay{2.5},LookAtDescription{"210013:n(100001)"}},
TurnTo{TurnToDescription{"210013:n(100001)"}},
PlayAnimation{delay{2.5},ActorId{210013},AnimationId{"Explain02_Start"},Duration{1}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "She doesn't look it at all! Don't tell me Huaxu medicine's already reached the level of immortality!",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145E72"
        },
        [12015510] = {
          Content = "……并非你们所想的那样。",
          DialogueId = 12015510,
          GUID = "1E145E9C",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015511,
          Scripts = "PlayAnimation{delay{2.5},ActorId{210013},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "...It is not as you might think.",
          TalkActionId = {
            [1] = "210013:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145E9C"
        },
        [12015511] = {
          Content = "长生无得者，举世如蜉蝣。我只是比别人多掌握了枯荣之术，但并未逃出生老病死的自然规律。",
          DialogueId = 12015511,
          GUID = "1E145EC6",
          NextDialogue = 12015512,
          Scripts = [[
SEQ{
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{"Talk01_Start"},Duration{3}},
PlayAnimation{ActorId{210013},AnimationId{"Talk01_End"},Duration{5}},
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{"DisagreeHead"},Duration{3}},
LookAt{LookAtDescription{"210013:p(BP_FixSimple_42_fushu01)"}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Immortality is but an illusion — across this world, life flits by like the mayfly's shadow. Though I have mastered the Art of Ephemerality, I too remain bound to the cycle of birth, aging, and death.",
          VoiceName = "voice/$Locale$/story/1201/120155/1E145EC6"
        },
        [12015512] = {
          Camera = "113.025772,32.107635,18.959473,0.000157,29.397686,10.806211,30.000008,12977.529297,false,Manual,12.571992",
          CameraBlendCurve = "easeInOutQuad",
          Content = "百年前的大疫中，我奔走救治时不慎……染上恶疾。家姐通过某种方式将我的躯体冻结，从而暂缓了疾病进程。",
          DialogueId = 12015512,
          Duration = 2,
          FinalCamera = "177.948578,52.488884,107.528198,0.000187,49.996937,27.204828,30.000013,12977.529297,false,Manual,12.571992",
          GUID = "1E145EF0",
          NextDialogue = 12015513,
          SpeakNpcId = 210013,
          Subtitle = "During the great plague a hundred years past, I... fell ill while tending to the sick. My sister, using a secret art, placed me in stasis to halt the disease's advance.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145EF0"
        },
        [12015513] = {
          Camera = "117.45327,198.753036,53.425415,0.000171,6.802288,-52.19939,30.000008,184.001556,false,Manual,14.564116",
          CameraBlendCurve = "easeInOutQuad",
          Content = "直至不久之前，家姐传人将我从沉眠中唤醒，并用最新研制出的药物将我体内的疾病祛除，我才重新行走于世间。",
          DialogueId = 12015513,
          FinalCamera = "99.263199,221.05603,50.602173,0.000163,5.602271,-50.799461,30.000008,246.6875,false,Manual,14.564116",
          GUID = "1E145F1A",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015514,
          SpeakNpcId = 210013,
          Subtitle = "It was only recently that her disciples woke me, armed with a new remedy to purge the illness at last. And thus, I returned to the world once more.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100001:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F1A"
        },
        [12015514] = {
          Camera = "193.710571,70.915855,75.647705,0.000229,-10.198722,104.400436,30.000023,100.823143,false,Manual,12.571992",
          CameraBlendCurve = "easeInOutQuad",
          Content = "难怪你的家干干净净，看起来像从未住过人一样……",
          DialogueId = 12015514,
          FacialId = {
            [1] = "100001:Shy"
          },
          FinalCamera = "191.586731,79.1856,74.111816,0.000238,-10.198688,104.400826,30.000023,79.899963,false,Manual,12.571992",
          GUID = "1E145F44",
          NextDialogue = 12015515,
          SpeakNpcId = 100001,
          Subtitle = "That explains why your home felt so neat... as if no one's ever lived there.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F44"
        },
        [12015515] = {
          Content = "一百年过去了，那你的姐姐……她还活着吗？",
          DialogueId = 12015515,
          FacialId = {
            [1] = "100001:Sad03"
          },
          GUID = "1E145F6E",
          LookAt = {
            [1] = "210013:n(210013)"
          },
          NextDialogue = 12015516,
          SpeakNpcId = 100001,
          Subtitle = "After all these years, your sister... is she still alive?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F6E"
        },
        [12015516] = {
          Camera = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          CameraBlendCurve = "easeInOutQuad",
          Content = "醒来后，我经过多方打听，得知家姐已于数年前溘然长逝。",
          DialogueId = 12015516,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "137.903931,114.5532,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          GUID = "1E145F98",
          NextDialogue = 12015517,
          SpeakNpcId = 210013,
          Subtitle = "After I awoke, I searched far and wide... only to learn she had already passed on, some years ago.",
          TalkActionId = {
            [1] = "210013:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F98"
        },
        [12015517] = {
          Camera = "528.575195,399.370605,61.019653,0.000049,2.244195,-139.985504,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "这也没什么大不了的啦。人皆有一死，如同草木枯荣，云起云落。你们生者无需为此感到伤神。",
          DialogueId = 12015517,
          FinalCamera = "555.92688,361.963898,61.019653,0.000049,2.644185,-144.785583,30.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1E145FC2",
          LookAt = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          NextDialogue = 12015518,
          Scripts = "TurnTo{delay{3},TurnToDescription{\"210013:n(210040)\"}}",
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Death comes to all — like the withering of leaves, like clouds that rise and drift away. You who still draw breath — there is no need to burden your hearts with it.",
          TalkActionId = {
            [1] = "210013:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(210040)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145FC2"
        },
        [12015518] = {
          Camera = "41.130356,69.325104,81.061401,0.000038,-30.356098,-0.185585,30.000002,100000.0,false,DoNotOverride,2.8",
          Content = "对哦，差点忘了……无由生也是死者耶。",
          DialogueId = 12015518,
          FacialId = {
            [1] = "200002:Nervous"
          },
          GUID = "1E145FEC",
          NextDialogue = 12015519,
          SpeakNpcId = 200002,
          Subtitle = "Right... Wishens are the dead, too.",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145FEC"
        },
        [12015519] = {
          Camera = "41.130356,69.325104,81.061401,0.000038,-30.356098,-0.185532,30.000002,148.839142,false,Manual,5.737342",
          CameraBlendCurve = "easeInOutQuad",
          Content = "嗯。家姐生前得偿所愿，她所醉心的草药学说也发扬光大，学徒众多，成为华胥的一门显学……所以无需为她感到遗憾。",
          DialogueId = 12015519,
          FacialId = {
            [1] = "210013:None"
          },
          FinalCamera = "41.130405,69.32515,81.061401,0.000048,-0.555725,-10.785604,30.000008,173.391495,false,Manual,4.750704",
          GUID = "1E146016",
          LookAt = {
            [1] = "100001:n(210013)"
