PlayAnimation{ActorId{210013},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Indeed. In life, my sister fulfilled her aspirations. Her devotion to the study of herbs took root and flourished — now a cherished tradition of Huaxu. There's no need to grieve for her.",
          TalkActionId = {
            [1] = "200002:Shock03_End",
            [2] = "210013:Shy02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146016"
        },
        [12015520] = {
          Camera = "177.72258,-25.978163,61.251343,0.000003,-3.754999,86.220833,35.0,175.973785,false,Manual,4.137168",
          CameraBlendCurve = "easeInOutQuad",
          Content = "但是，你认识的人都已经从这个世界消失了……",
          DialogueId = 12015520,
          FinalCamera = "181.986115,-26.260483,61.251343,0.000003,-3.754999,86.220833,35.0,175.973785,false,Manual,4.137168",
          GUID = "1E146040",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015521,
          SpeakNpcId = 100001,
          Subtitle = "But... all those you once knew are gone. You're the only one left in this world.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "210013:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E146040"
        },
        [12015521] = {
          Content = "只剩下你独自一人活在这个世界上，会感到孤单吗？",
          DialogueId = 12015521,
          GUID = "1E14606A",
          LookAt = {
            [1] = "200002:n(210013)"
          },
          NextDialogue = 12015522,
          SpeakNpcId = 100001,
          Subtitle = "Don't you feel lonely?",
          TalkActionId = {
