          SpeakNpcId = 210013,
          Subtitle = "I see. Thank you for sharing your knowledge.",
          TalkActionId = {
            [1] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146190"
        },
        [12015529] = {
