          Content = "哈哈，快上路吧。生者的时间可是很宝贵的。",
          DialogueId = 12015534,
          FinalCamera = "146.449402,146.941391,76.819092,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
          GUID = "1E14628C",
          NextDialogue = 12015535,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Thank you. Then be on your way. The living mustn't squander their fleeting hours.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120155/1E14628C"
        },
        [12015535] = {
          Camera = "1428.752563,1073.151489,38.327271,0.000178,-0.197604,-141.396988,30.000002,1974.44458,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "待你们百年之后，再回来这里畅谈也不迟。老骨头我有耐心，等得起呐。",
          DialogueId = 12015535,
          FinalCamera = "1560.888916,1093.783447,38.735229,0.000178,-0.197604,-144.99707,30.000002,1974.44458,false,Manual,1.2",
          GUID = "1E1462B6",
          NextDialogue = 12015536,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "When your time in the mortal world is done, you can always return — I will be waiting still for a proper catch-up.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1462B6"
        },
        [12015536] = {
          Camera = "203.142548,172.754639,84.036987,0.000236,-41.194706,-124.995682,30.000013,127.563431,false,Manual,8.594169",
          CameraBlendCurve = "easeInOutQuad",
          Content = "……明明知道他说的没错，但是莫名有一种背后发寒的感觉怎么回事！",
