          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Save me... save me...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148EAE"
        },
        [12015804] = {
          Content = "是有什么人在说话，那个人好像在向路过的人求助。",
          DialogueId = 12015804,
          GUID = "1E148ED8",
          NextDialogue = 12015805,
          SpeakNpcId = 100001,
          Subtitle = "There is a voice — someone calling for help.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148ED8"
        },
        [12015805] = {
          Content = "那人在喊……“舅舅”？她也是在找自己的亲人吗？",
          DialogueId = 12015805,
          GUID = "1E148F02",
          NextDialogue = 12015806,
          SpeakNpcId = 200002,
          Subtitle = "Did she say... \"Baby\"? ...Is she calling out for someone she loves?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F02"
        },
        [12015806] = {
          Content = "不能消失……我还有……",
          DialogueId = 12015806,
          GUID = "1E148F2C",
          NextDialogue = 12015807,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Can't disappear... I still have to...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F2C"
        },
        [12015807] = {
          Content = "在……之前……请让我……",
          DialogueId = 12015807,
          GUID = "1E148F56",
          NextDialogue = 12015808,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Before it's too late... let me...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F56"
        },
        [12015808] = {
          Content = "对吧对吧，白没有听错！就是说嘛，本魔王的听力，连水仙平原最细微角落的悄悄话都能听得一清二楚！",
          DialogueId = 12015808,
          GUID = "1E148F80",
          NextDialogue = 12015809,
          SpeakNpcId = 200002,
          Subtitle = "See? I knew I wasn't hearing things! Ha — never doubt this Demon King's ears. Sharp enough to catch whispers in every corner of The Asphodel!",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F80"
        },
        [12015809] = {
          Content = "明白了，下次有什么不能带你商量的事，一定让你走远点。",
          DialogueId = 12015809,
          GUID = "1E148FAA",
          NextDialogue = 12015810,
          SpeakNpcId = 100001,
          Subtitle = "Duly noted. Next time I've got a secret to keep, I'll make sure you're nowhere nearby.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FAA"
        },
        [12015810] = {
          Content = "喂，太过分了！！",
          DialogueId = 12015810,
          GUID = "1E148FD4",
          NextDialogue = 12015811,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Not cool, Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FD4"
        },
        [12015811] = {
          Content = "……话说回来，这个声音的主人在哪里，我们又该怎么找到它呢？",
          DialogueId = 12015811,
          GUID = "1E148FFE",
          SpeakNpcId = 200002,
          Subtitle = "Still... where's that voice coming from? And how do we even start looking for them?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FFE"
        },
        [12015901] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "小仆从，刚刚什么动静？",
          DialogueId = 12015901,
          GUID = "1E149EC2",
          NextDialogue = 12015902,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, what was that noise?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149EC2"
        },
        [12015902] = {
          Content = "小仆从，小仆从？……{nickname}？！",
          DialogueId = 12015902,
          GUID = "1E149EEC",
          NextDialogue = 12015903,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion...? Little Minion!  — what's wrong!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149EEC"
        },
        [12015903] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你、你怎么不说话呀……",
          DialogueId = 12015903,
          GUID = "1E149F16",
          NextDialogue = 12015904,
          SpeakNpcId = 200002,
          Subtitle = "Say something...!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F16"
        },
        [12015904] = {
          Content = "怎么办！扶疏，扶疏，大事不好啦——",
          DialogueId = 12015904,
          GUID = "1E149F40",
          NextDialogue = 12015905,
          SpeakNpcId = 200002,
          Subtitle = "Oh no... oh no — Fushu! Fushu, something's really wrong—!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F40"
        },
        [12015905] = {
          Content = "发生了什么？",
          DialogueId = 12015905,
          GUID = "1E149F6A",
          NextDialogue = 12015906,
          SpeakNpcId = 210013,
          Subtitle = "What happened?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F6A"
        },
        [12015906] = {
          Content = "呜哇……刚刚有什么人在看不见的地方说话，我和小仆从准备去找找看，可是刚刚突然有一道光闪过，“滋溜”一声，小仆从就变成了这个呆呆的样子！",
          DialogueId = 12015906,
          GUID = "1E149F94",
          NextDialogue = 12015907,
          SpeakNpcId = 200002,
          Subtitle = "Waaah... There was a voice, coming from somewhere we couldn't see, so we went to look... and then all of a sudden — there was this flash and a fwoosh, and my Little Minion just... froze up!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F94"
        },
        [12015907] = {
          Content = "怎么喊都不答应……就像是灵魂被抽走了一样！",
          DialogueId = 12015907,
          GUID = "1E149FBE",
          NextDialogue = 12015908,
          SpeakNpcId = 200002,
          Subtitle = "I called {性别:his|her} name many times, but {性别:he|she} just stood there like a statue — like {性别:his|her} soul's been snatched away!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149FBE"
        },
        [12015908] = {
          Content = "小白，你先镇定下来，焦急于情势无补。安心，有我在。",
          DialogueId = 12015908,
          GUID = "1E149FE8",
          NextDialogue = 12015910,
          SpeakNpcId = 210013,
          Subtitle = "Take a breath, Snow. Panic will only cloud your thoughts. Don't worry, I'm here with you.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149FE8"
        },
        [12015910] = {
          Content = "你是说……你最后一次看到正常的{nickname}，是在这里吗？",
          DialogueId = 12015910,
          GUID = "1E14A03C",
          NextDialogue = 12015912,
          SpeakNpcId = 210013,
          Subtitle = "So... the last place you saw  before {性别:he|she} froze — was right here?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A03C"
        },
        [12015912] = {
          Content = "这是什么？{nickname}该不会有危险吧？！",
          DialogueId = 12015912,
          GUID = "1E14A090",
          NextDialogue = 12015913,
          SpeakNpcId = 200002,
          Subtitle = "What is that!? Is  going to be okay!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A090"
        },
        [12015913] = {
          Content = "如果我没有猜错，{性别：他|她}的精神被<H>往隙</>吞噬了。",
          DialogueId = 12015913,
          GUID = "1E14A0BA",
          NextDialogue = 12015914,
          RelatedWikiId = {
            [1] = 304008
          },
          SpeakNpcId = 210013,
          Subtitle = "If I'm not mistaken, {性别:his|her} spirit has been swallowed by a place known as the Oblivion Rift.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A0BA"
        },
        [12015914] = {
          Content = "往隙……那是什么？听你的语气好像很不妙！",
          DialogueId = 12015914,
          GUID = "1E14A0E4",
          NextDialogue = 12015915,
          SpeakNpcId = 200002,
          Subtitle = "The Oblivion Rift...? That sounds awful! What is it?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A0E4"
        },
        [12015915] = {
          Content = "倘若虞泉是由人的执念交织形成的彼界……那么虞泉受烛阴之灾影响，便生出往隙——令一切忘却消弭的无光之地。",
          DialogueId = 12015915,
          GUID = "1E14A10E",
          NextDialogue = 12015916,
          SpeakNpcId = 210013,
          Subtitle = "The Spring of Yu is a realm woven from human yearning, and the Oblivion Rift is its shadow — born of Zhuyin's corruption. It is a lightless void where all memory is consumed and undone.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A10E"
        },
        [12015916] = {
          Content = "失足坠入的行者，若是没有在往隙生成后的一个时辰内及时返回，其魂魄就会永久迷失在其中，不得归途。",
          DialogueId = 12015916,
          GUID = "1E14A138",
          NextDialogue = 12015917,
          SpeakNpcId = 210013,
          Subtitle = "Anyone who falls in must find their way out within one hour of the Rift's birth. If they do not... their soul will be lost forever, with no path home.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A138"
        },
        [12015917] = {
          Content = "那……",
          DialogueId = 12015917,
          GUID = "1E14A162",
          NextDialogue = 12015918,
          SpeakNpcId = 200002,
          Subtitle = "Then what do we do...!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A162"
        },
        [12015918] = {
          Content = "不用心慌，我现在去带{性别：他|她}回来。你在原地等着我们。",
          DialogueId = 12015918,
          GUID = "1E14A18C",
          NextDialogue = 12015919,
          SpeakNpcId = 210013,
          Subtitle = "Don't be afraid. I will go in and bring {性别:him|her} back. Stay here and wait for us.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A18C"
        },
        [12015919] = {
          Content = "……白也要跟着一起去！",
          DialogueId = 12015919,
          GUID = "1E14A1B6",
          NextDialogue = 12015920,
          SpeakNpcId = 200002,
          Subtitle = "...I'm coming with you!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A1B6"
        },
        [12015920] = {
          Content = "不行，往隙凶险异常。若是连你也陷于其中，事态只会更加失控。",
          DialogueId = 12015920,
          GUID = "1E14A1E0",
          NextDialogue = 12015921,
          SpeakNpcId = 210013,
          Subtitle = "No, it's far too perilous. If you were to be lost as well... it would only make things worse.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A1E0"
        },
        [12015921] = {
          Content = "但、但是，白只能在这里干等着，什么事情都做不了，也不知道里面是什么情况，小仆从到底怎么样了……",
          DialogueId = 12015921,
          GUID = "1E14A20A",
          NextDialogue = 12015922,
          SpeakNpcId = 200002,
          Subtitle = "But... but I don't want to just wait here doing nothing! Not knowing what's happening in there... or if my Little Minion is safe...",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A20A"
        },
        [12015922] = {
          Content = "呜，这种感觉……太难受了……",
          DialogueId = 12015922,
          GUID = "1E14A234",
          NextDialogue = 12015923,
          SpeakNpcId = 200002,
          Subtitle = "I can't take it... Waaaah!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A234"
        },
        [12015923] = {
          Content = "小白，来，手给我。",
          DialogueId = 12015923,
          GUID = "1E14A25E",
          NextDialogue = 12015924,
          SpeakNpcId = 210013,
          Subtitle = "Snow, come here. Give me your hand.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A25E"
        },
        [12015924] = {
          Content = "这……这是……",
          DialogueId = 12015924,
          GUID = "1E14A288",
          NextDialogue = 12015925,
          SpeakNpcId = 200002,
          Subtitle = "Huh? What is this?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A288"
        },
        [12015925] = {
          Content = "家姐说过，药苦的话，吃枚蜜饯就会甜起来。我想，心里苦也是一样的。",
          DialogueId = 12015925,
          GUID = "1E14A2B2",
          NextDialogue = 12015926,
          SpeakNpcId = 210013,
          Subtitle = "My sister once said, \"When potion is bitter, chase it with something sweet.\" I believe hearts work the same way.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A2B2"
        },
        [12015926] = {
          Content = "别哭了，好吗？我一定会平安带着{性别：他|她}归来的，这是约定。",
          DialogueId = 12015926,
          GUID = "1E14A2DC",
          NextDialogue = 12015927,
          SpeakNpcId = 210013,
          Subtitle = "So no more tears, alright? I'll bring {性别:him|her} back safe and sound. I promise.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A2DC"
        },
        [12015927] = {
          Content = "那……你赶紧去吧！我帮你们盯着这个什么缝隙，让它不要一下子关上！",
          DialogueId = 12015927,
          GUID = "1E14A306",
          NextDialogue = 12015928,
          SpeakNpcId = 200002,
          Subtitle = "Then... then go already! I'll keep an eye on this creepy rift — no way I'm letting it shut!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A306"
        },
        [12015928] = {
          Content = "整天说自己是什么魔王大人，结果连我的小仆从都护不住……",
          DialogueId = 12015928,
          GUID = "1E14A330",
          NextDialogue = 12015929,
          SpeakNpcId = 200002,
          Subtitle = "I go around telling everyone I'm the Demon King... and I can't even protect my own Little Minion...",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A330"
        },
        [12015929] = {
          Content = "坏东西，白看住你了，不许消失！",
          DialogueId = 12015929,
          GUID = "1E14A35A",
          NextDialogue = 12015930,
          SpeakNpcId = 200002,
          Subtitle = "You evil rift thing — don't you dare close up! I'm watching you!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A35A"
        },
        [12015930] = {
          Content = "笨蛋仆从，你一定要好好地回来哦！不然罚你给卡米拉打一年……不对，十年，一百年工！",
          DialogueId = 12015930,
          GUID = "1E14A384",
          SpeakNpcId = 200002,
          Subtitle = "And you — stupid Little Minion — you'd better come back in one piece! Or else I'll have you waiting tables for Camilla for a year — no, ten — no, a hundred years!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A384"
        },
        [12016001] = {
          Content = "（这里是……哪里……）",
          DialogueId = 12016001,
          Duration = 2,
          GUID = "1E14AF2A",
          NextDialogue = 12016002,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Where... am I?)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF2A"
        },
        [12016002] = {
          Content = "（谁也不在，什么声音都没有，安静到只能听见自己的心跳声……）",
          DialogueId = 12016002,
          Duration = 3,
          GUID = "1E14AF54",
          NextDialogue = 12016003,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(No one's here. Not a sound. It's so still I can hear my own heartbeat...)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF54"
        },
        [12016003] = {
          Content = "（就像是……回到了白沙倾泻而下的原点，如同一切从未发生。）",
          DialogueId = 12016003,
          Duration = 3,
          GUID = "1E14AF7E",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(It's as if... I'm back where it all began. Where the white sand flows from the sky. As though nothing ever happened.)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF7E"
        },
        [12016101] = {
          Content = "{nickname}，听得到我的声音吗？",
          DialogueId = 12016101,
          Duration = 3,
          GUID = "1E14BF92",
          NextDialogue = 12016102,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Can you hear me, ?",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BF92"
        },
        [12016102] = {
          Content = "扶疏？是你吗，你在哪里？！",
          DialogueId = 12016102,
          Duration = 2,
          GUID = "1E14BFBC",
          NextDialogue = 12016103,
          SpeakNpcId = 100001,
          Subtitle = "Fushu? Is that you? Where are you!?",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BFBC"
        },
        [12016103] = {
          Content = "我所处的位置和你有一段间隔。但这里是特殊的场域，人与人的思绪在此处得以相通。因而我能够看到你，把声音传达过去。",
          DialogueId = 12016103,
          Duration = 5,
          GUID = "1E14BFE6",
          NextDialogue = 12016104,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "There lies a distance between us in the mortal realm. Yet this place is not bound by such constraints. Here, thoughts connect — I can see you, and my voice may find you.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BFE6"
        },
        [12016104] = {
          Content = "不用担忧，已经没事了。接下来我会引导你离开这里，回到安全的地方。",
          DialogueId = 12016104,
          Duration = 4,
          GUID = "1E14C010",
          NextDialogue = 12016105,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do not fear. You are safe here. I shall guide you back to where you belong.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C010"
        },
        [12016105] = {
          Content = "……嗯，我明白了！",
          DialogueId = 12016105,
          Duration = 2,
          GUID = "1E14C03A",
          SpeakNpcId = 100001,
          Subtitle = "...Okay. I understand.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C03A"
        },
        [12016201] = {
          Content = "看到那些灯花了吗？生者会将祈愿寄托于河灯之上，放入幽深的河水中，期望它们将思念载往亡者之域。",
          DialogueId = 12016201,
          Duration = 4,
          GUID = "1E14CFFA",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do you see those lantern blossoms? The living send forth their prayers upon them, setting them adrift in deep, silent waters — hoping they might reach those who have departed.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14CFFA"
        },
        [12016202] = {
          Content = "烛火的照耀可以护佑你，不受往隙的侵蚀。",
          DialogueId = 12016202,
          Duration = 3,
          GUID = "1E14D024",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Their gentle light shall shield you from the oblivion's creeping grasp.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D024"
        },
        [12016251] = {
          Content = "扶疏，我应该怎么离开这里？",
          DialogueId = 12016251,
          Duration = 3,
          GUID = "1E14D026",
          NextDialogue = 12016303,
          SpeakNpcId = 100001,
          Subtitle = "How am I supposed to leave here, Fushu?",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D026"
        },
        [12016301] = {
          Content = "小心身旁的河水。那是忘川，沾染到它会使人的存在逐渐淡薄，失去生之欲望。",
          DialogueId = 12016301,
          Duration = 3,
          GUID = "1E14E062",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Beware the river that lies close at hand. That is Lethe — the River of Forgetting. Should its waters touch you, your sense of self will begin to fade, and your will to live shall wane.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E062"
        },
        [12016302] = {
          Content = "……可是周围都是河水，没有路了。该怎么办？",
          DialogueId = 12016302,
          Duration = 3,
          GUID = "1E14E08C",
          SpeakNpcId = 100001,
          Subtitle = "...But there's water everywhere. There's no path forward. What do I do?",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E08C"
        },
        [12016303] = {
          Content = "{nickname}，你有无论如何都要完成的心愿吗？",
          DialogueId = 12016303,
          Duration = 3,
          GUID = "1E14E0B6",
          NextDialogue = 12016401,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = ", do you bear a wish that you must see fulfilled, no matter the cost?",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E0B6"
        },
        [12016304] = {
          Content = "那就是你与此世的牵绊。对着前方的占风铎，默念你的心愿。",
          DialogueId = 12016304,
          Duration = 3,
          GUID = "1E14E0E0",
          NextDialogue = 12016305,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "That wish is your tether to this world. Face the Aeolian Chime that stands before you, and let that wish take shape upon your mind.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E0E0"
        },
        [12016305] = {
          Content = "它会唤来风，将你的执念送往更高更远处，助你重返生者之界。",
          DialogueId = 12016305,
          Duration = 3,
          GUID = "1E14E10A",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "It shall call to the wind — carrying your wish to the heights, and guiding you back to the land of the living.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E10A"
        },
        [12016401] = {
          Content = "（……无论如何都要去完成的事情。）",
          DialogueId = 12016401,
          Duration = 2,
          GUID = "1E14F0CA",
          NextDialogue = 12016402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Something I must do no matter the cost...)",
          VoiceName = "voice/$Locale$/story/1201/120164/1E14F0CA"
        },
        [12016402] = {
          Content = "（贝蕾还在等着我……我要救出她，所以不能在这里止步！）",
          DialogueId = 12016402,
          Duration = 3,
          GUID = "1E14F0F4",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Berry is still waiting for me... I have to bring her back. I can't stop here!)",
          VoiceName = "voice/$Locale$/story/1201/120164/1E14F0F4"
        },
        [12016501] = {
          Content = "……！灯亮起来了，好美。",
          DialogueId = 12016501,
          Duration = 2,
          GUID = "1E150132",
          NextDialogue = 12016502,
          SpeakNpcId = 100001,
          Subtitle = "...! The lanterns lit up. How beautiful.",
          VoiceName = "voice/$Locale$/story/1201/120165/1E150132"
        },
        [12016502] = {
          Content = "那些祈天灯的火焰，应当可以点燃灯花，帮你开辟新的道路。",
          DialogueId = 12016502,
          Duration = 3,
          GUID = "1E15015C",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The flames of the sky lanterns shall awaken the blossoms ahead, lighting the path for your return.",
          VoiceName = "voice/$Locale$/story/1201/120165/1E15015C"
        },
        [12016601] = {
          Content = "{nickname}，是你吗？",
          DialogueId = 12016601,
          Duration = 2,
          GUID = "1E15119A",
          NextDialogue = 12016602,
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = ", is that you?",
          TalkActionId = {
            [1] = "210024:Explain01_Start"
          },
          TurnTo = {
            [1] = "210024:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E15119A"
        },
        [12016602] = {
          Content = "……贝蕾！",
          DialogueId = 12016602,
          Duration = 2,
          GUID = "1E1511C4",
          NextDialogue = 12016603,
          SpeakNpcId = 100001,
          Subtitle = "...Berry!",
          TalkActionId = {
            [1] = "210024:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E1511C4"
        },
        [12016603] = {
          Content = "我们一定能够再次相逢的。在那之前，照顾好自己，不要受伤。",
          DialogueId = 12016603,
          Duration = 3,
          GUID = "1E1511EE",
          NextDialogue = 12016604,
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = "We'll definitely meet again. Until then, take good care of yourself and stay safe.",
          TalkActionId = {
            [1] = "210024:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E1511EE"
        },
        [12016604] = {
          Content = "现在往前走吧，不要停下脚步。我会一直守望你的背影。",
          DialogueId = 12016604,
          Duration = 3,
          GUID = "1E151218",
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = "Keep going forward now. I'll always be watching over you.",
          TalkActionId = {
            [1] = "210024:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E151218"
        },
        [12016701] = {
          Content = "她就是你曾提及的“家人”吧。",
          DialogueId = 12016701,
          Duration = 2,
          GUID = "1E152202",
          NextDialogue = 12016702,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "She is the family you have sought so long to find, right?",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152202"
        },
        [12016702] = {
          Content = "话虽扫兴……此处的她只是心愿和思念凝成的实体，并非真人。",
          DialogueId = 12016702,
          Duration = 3,
          GUID = "1E15222C",
          NextDialogue = 12016703,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Yet I must tell you this — what you beheld was but a wisp of longing, not her true form.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E15222C"
        },
        [12016703] = {
          Content = "我明白的。",
          DialogueId = 12016703,
          Duration = 2,
          GUID = "1E152256",
          NextDialogue = 12016704,
          SpeakNpcId = 100001,
          Subtitle = "I understand.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152256"
        },
        [12016704] = {
          Content = "就算如此，能在这里看到她，相信她还在世界上某个地方等我……我会安心许多。",
          DialogueId = 12016704,
          Duration = 4,
          GUID = "1E152280",
          SpeakNpcId = 100001,
          Subtitle = "But even so... to see her here, to believe she is waiting for me somewhere in this world... it brings me solace. It gives me strength.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152280"
        },
        [12016801] = {
          Content = "又是新的占风铎。{nickname}，你知道该怎么做。",
          DialogueId = 12016801,
          Duration = 3,
          GUID = "1E15326A",
          NextDialogue = 12016802,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Another Aeolian Chime. You know what must be done, .",
          VoiceName = "voice/$Locale$/story/1201/120168/1E15326A"
        },
        [12016802] = {
          Content = "（我要平安回到冰湖城……大家还在等着我，我不能就此停下脚步！）",
          DialogueId = 12016802,
          Duration = 3,
          GUID = "1E153294",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I must make it back to Icelake safely. Everyone's still waiting for me. I can't stop now!)",
          VoiceName = "voice/$Locale$/story/1201/120168/1E153294"
        }
      }
    end
  },
  {
    MinKey = 12016901,
