    Loader = function()
      return {
        [12016901] = {
          Content = "好久不见，{nickname}。",
          DialogueId = 12016901,
          Duration = 2,
          GUID = "1E1542D2",
          NextDialogue = 12016902,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
