          TalkActionId = {
            [1] = "210024:Explain02_Start"
          },
          TurnTo = {
            [1] = "210025:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E1542D2"
        },
        [12016902] = {
          Content = "你是不是去了什么地方……一个我从未听过的、陌生又新鲜的地方？",
          DialogueId = 12016902,
          Duration = 3,
          GUID = "1E1542FC",
          NextDialogue = 12016903,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "Have you gone somewhere new and different? A place that I've never heard of?",
          TalkActionId = {
            [1] = "210024:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E1542FC"
        },
        [12016903] = {
          Content = "如果可以的话，等你什么时候回来冰湖城，可以讲给我听听吗？",
          DialogueId = 12016903,
          Duration = 3,
          GUID = "1E154326",
          NextDialogue = 12016904,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "Could you tell me about it when you come back to Icelake?",
          TalkActionId = {
            [1] = "210024:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E154326"
        },
        [12016904] = {
          Content = "虽然这个愿望有点奢侈……可以的话，请不要忘记我。",
          DialogueId = 12016904,
          GUID = "1E154350",
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "I know it's kind of way too much to ask, but... please don't forget about me.",
          VoiceName = "voice/$Locale$/story/1201/120169/1E154350"
        },
        [12017001] = {
          Content = "小仆从，快跟上来，怎么这么慢！魔王大人还要带你一起去征服世界呢！",
          DialogueId = 12017001,
          Duration = 4,
          GUID = "1E15533A",
          NextDialogue = 12017002,
