          DialogueId = 12019312,
          GUID = "1E16CE60",
          NextDialogue = 12019313,
          SpeakNpcId = 100001,
          Subtitle = "We didn't see anyone like that on the way here.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CE60"
        },
        [12019313] = {
