          GUID = "1E172F02",
          NextDialogue = 12019902,
          RelatedWikiId = {
            [1] = 203005,
            [2] = 203004
          },
          SpeakNpcId = 210012,
          Subtitle = "This little game of cat and mouse... it ends here. Wouldn't you agree, dear Magistrate of Yingtian?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F02"
        },
        [12019902] = {
          Content = "……",
          DialogueId = 12019902,
          GUID = "1E172F2C",
          NextDialogue = 12019903,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F2C"
        },
        [12019903] = {
