          DialogueId = 12023801,
          Duration = 4,
          GUID = "1E19AEDA"
        },
        [12023802] = {
          Content = "【战斗】+【机关】限时战斗后采集黑龙鳞",
          DialogueId = 12023802,
          Duration = 4,
          GUID = "1E19AF04"
        },
        [12023803] = {
          Content = "【机关】清除尘漠",
          DialogueId = 12023803,
          Duration = 4,
          GUID = "1E19AF2E"
        },
        [12023804] = {
          Content = "【机关】调香玩法",
          DialogueId = 12023804,
          Duration = 4,
          GUID = "1E19AF58"
        },
        [12023805] = {
          Content = "【机关】清除障碍",
          DialogueId = 12023805,
          Duration = 4,
          GUID = "1E19AF82"
        },
        [12023806] = {
          Content = "【幻境】女主进入扶疏幻境",
          DialogueId = 12023806,
          Duration = 4,
          GUID = "1E19AFAC"
        },
        [12023807] = {
          Content = "【幻境】进入古战场幻境",
          DialogueId = 12023807,
          Duration = 4,
          GUID = "1E19AFD6"
        },
        [12023808] = {
          Content = "【机关】采集忘忧草",
          DialogueId = 12023808,
          Duration = 4,
          GUID = "1E19B000"
        },
        [12023809] = {
          Content = "【战斗】烛阴BOSS战",
          DialogueId = 12023809,
          Duration = 4,
          GUID = "1E19B02A"
        },
        [12023810] = {
          Content = "【机关】采集黑龙鳞",
          DialogueId = 12023810,
          Duration = 4,
          GUID = "1E19B054"
        },
        [12023811] = {
          Content = "【系统（战斗轮盘）-引导需求】\n1.UI：引导打开军械库轮盘装备<牵机公枢>\n2.UI：引导打开探索背包启用<牵机关公枢>",
          DialogueId = 12023811,
          Duration = 4,
          GUID = "1E19B07E"
        },
        [12023812] = {
          Content = "【玩法（吸收晶垢-引导需求】\n1.图文:使用机关对着晶垢吸，去除晶垢",
          DialogueId = 12023812,
          Duration = 4,
          GUID = "1E19B0A8"
        },
        [12023850] = {
          Content = "烟津掠影蔽香尘",
          DialogueId = 12023850,
          GUID = "1E19B0A1",
          Subtitle = "Mistwharf – Veiled in Fragrant Haze"
        },
        [12023851] = {
          Content = "终",
          DialogueId = 12023851,
          GUID = "1E19B0A2",
          Subtitle = "The End"
        },
        [12023852] = {
          Content = "未完待续",
          DialogueId = 12023852,
          GUID = "1E19B0A3",
          Subtitle = "To be continued"
        },
        [12025001] = {
          Content = "又一船货物到了！兄弟们，清点好名单再搬运，切莫急躁，心急吃不到热豆腐哟。",
          DialogueId = 12025001,
          GUID = "1E1A73BA",
          SpeakNpcId = 210112,
          Subtitle = "Another boatload just came in, lads! Make sure the list is right before you start hauling. Don't rush it — or you'll just mess it up."
        },
        [12025101] = {
          Content = "针头线脑，香脂香囊，走过路过不要错过——",
          DialogueId = 12025101,
          GUID = "1E1A8422",
          SpeakNpcId = 210113,
          Subtitle = "Needles, thread, balsams and sachets — does anything catch your eye?"
        },
        [12025201] = {
          Content = "哟，{性别：小弟弟|小妹妹}，你来啦。看中了什么随便挑，你是止流大当家的客人，那便也是我的客人。",
          DialogueId = 12025201,
          GUID = "1E1A948A",
          NextOptions = {
            [1] = 12025203,
            [2] = 12025212
          },
          SpeakNpcId = 210113,
          Subtitle = "Ah, there you are, {性别:young man|young lass}! See something you fancy? Take whatever you like — Miss Zhiliu's guest is my guest too."
        },
        [12025203] = {
          Content = "你在码头卖这些，生意好吗？",
          DialogueId = 12025203,
          GUID = "1E1A94DE",
          NextDialogue = 12025204,
          Subtitle = "Is business good down by the docks, selling all this?"
        },
        [12025204] = {
          Content = "哈哈，做生意，无非是一个找到客户需求，满足客户需求的过程。这便是织星客上路的第一门诀窍。",
          DialogueId = 12025204,
          GUID = "1E1A9508",
          NextDialogue = 12025205,
          SpeakNpcId = 210113,
          Subtitle = "Haha, business is just knowing what folks need and getting it to 'em. That's the first trick any Starweaver learns."
        },
        [12025205] = {
          Content = "织星客远航出海，在船上常常一待就要带上个把月。",
          DialogueId = 12025205,
          GUID = "1E1A9532",
          NextDialogue = 12025206,
          SpeakNpcId = 210113,
          Subtitle = "Once a Starweaver heads out, they're stuck on the ship for a month or so at a time."
        },
        [12025206] = {
          Content = "总有些冒失鬼，临到出航前才发现这没带那没带。我这些生活杂货呀，就起到一个江湖救急的作用——当然，价格那也是绝对实惠，童叟无欺！",
          DialogueId = 12025206,
          GUID = "1E1A955C",
          NextDialogue = 12025207,
          SpeakNpcId = 210113,
          Subtitle = "There's always some scatterbrain who realises, right before they push off, that they've forgotten this or that. That's when my bits and bobs come in handy — and the prices are fair, mind you!"
        },
        [12025207] = {
          Content = "离开华胥的游客，在等渡船的过程中，也往往要带上几样特色纪念品。销量这不就来了？",
          DialogueId = 12025207,
          GUID = "1E1A9586",
          NextDialogue = 12025208,
          SpeakNpcId = 210113,
          Subtitle = "And travellers waiting for the ferry out of Huaxu usually grab a few souvenirs too. That gives the sales a bit of a boost."
        },
        [12025208] = {
          Content = "更何况，本小店还有一个赚钱的独家诀窍——",
          DialogueId = 12025208,
          GUID = "1E1A95B0",
          NextOptions = {
            [1] = 12025209
          },
          SpeakNpcId = 210113,
          Subtitle = "Plus, I've got a neat little money-making trick of my own..."
        },
        [12025209] = {
          Content = "什么诀窍？",
          DialogueId = 12025209,
          GUID = "1E1A95DA",
          NextDialogue = 12025210,
          Subtitle = "What is it?"
        },
        [12025210] = {
          Content = "{性别：小弟弟|小妹妹}，刚刚我送你的香囊，可不是什么普通物什，而是获得悬衡派授权的独家限量版香囊。",
          DialogueId = 12025210,
          GUID = "1E1A9604",
          NextDialogue = 12025211,
          SpeakNpcId = 210113,
          Subtitle = "That sachet I gave you isn't just some common item you can find on just any stall — it's a limited edition, officially licensed by the Xuanheng Sect."
        },
        [12025211] = {
          Content = "类似的香囊在华胥各地只有几家能贩售，款式还各有不同，香囊爱好者自然是趋之若鹜。我这摊子在烟津渡到此必游的清单里，也是榜上有名呢！",
          DialogueId = 12025211,
          GUID = "1E1A962E",
          SpeakNpcId = 210113,
          Subtitle = "Only a handful of places in Huaxu can sell these, each with its own design. Sachet lovers come running. My stall's even on the must-visit lists in Mistwharf."
        },
        [12025212] = {
          Content = "你也承过止流掌柜的人情吗？",
          DialogueId = 12025212,
          GUID = "1E1A9658",
          NextDialogue = 12025213,
          Subtitle = "So Proprietress Zhiliu once helped you out too?"
        },
        [12025213] = {
          Content = "当年我押上全部身家的一船货物不小心遇到海难，全翻了。我这半辈子的积蓄一夜之间打了水漂。",
          DialogueId = 12025213,
          GUID = "1E1A9682",
          NextDialogue = 12025214,
          SpeakNpcId = 210113,
          Subtitle = "Years back, I'd put my whole life's savings into one shipload of goods — and wouldn't you know it, we ran into a storm and everything went under. Half a life's savings, gone in a single night."
        },
        [12025214] = {
          Content = "我去百年春延期借款时偶遇了止流大当家。她听了我的遭遇后，把我的借款一笔勾销了，还额外给我了笔启动资金。",
          DialogueId = 12025214,
          GUID = "1E1A96AC",
          NextDialogue = 12025215,
          SpeakNpcId = 210113,
          Subtitle = "I went to EverSpring to ask for more time on my loan, and happened to run into Proprietress Zhiliu. She heard my story, cleared the debt on the spot, and even gave me some seed money to start over."
        },
        [12025215] = {
          Content = "对她而言，这可能只是一点不值一提的小恩惠，却是实实在在地改变了我的人生。",
          DialogueId = 12025215,
          GUID = "1E1A96D6",
          NextDialogue = 12025216,
          SpeakNpcId = 210113,
          Subtitle = "To her, it was probably nothing much. To me, it changed my whole life."
        },
        [12025216] = {
          Content = "后来那笔钱我早就还上了，但止流大当家的人情我可是一直记在心里。{性别：小弟弟|小妹妹}，要是你以后有什么忙需要我帮，直接开口，千万不用客气哈。",
          DialogueId = 12025216,
          GUID = "1E1A9700",
          SpeakNpcId = 210113,
          Subtitle = "I paid that back ages ago, but I've kept her kindness in mind ever since. So, {性别:young man|young lass} — if you ever need a hand, just say the word."
        },
        [12025301] = {
          Content = "是你啊。怎么样，对百年春这边还算熟悉起来了吗？",
          DialogueId = 12025301,
          GUID = "1E1AA4F2",
          NextDialogue = 12025302,
          SpeakNpcId = 210114,
          Subtitle = "Ah, it's you. How are you finding EverSpring? Starting to get the feel of the place?"
        },
        [12025302] = {
          Content = "若是有什么人生地不熟的不便之处，来找我，我会尽力帮你解决。",
          DialogueId = 12025302,
          GUID = "1E1AA51C",
          SpeakNpcId = 210114,
          Subtitle = "If anything feels difficult while you're settling in, just come to me. I'll help however I can."
        },
        [12025401] = {
          Content = "{nickname}，还有什么问题想问我吗？尽管开口，我会逐一解答。",
          DialogueId = 12025401,
          GUID = "1E1AB55A",
          NextDialogue = 12025425,
          SpeakNpcId = 210115,
          Subtitle = ", is there anything else you wish to ask? I will answer whatever I can."
        },
        [12025402] = {
          Content = "你好像是个大人物。",
          DialogueId = 12025402,
          GUID = "1E1AB584",
          NextDialogue = 12025403,
          Subtitle = "You seem like a pretty important person."
        },
        [12025403] = {
          Content = "呵呵，都是些身外之名罢了。我已经过了为一些浮名薄利而沾沾自喜的年龄。",
          DialogueId = 12025403,
          GUID = "1E1AB5AE",
          NextDialogue = 12025404,
          SpeakNpcId = 210115,
          Subtitle = "Those are merely titles the world happens to bestow. I have long outgrown any inclination to take pride in fleeting fame or trivial gain."
        },
        [12025404] = {
          Content = "止流掌柜，我可以冒昧问一句，你今年多大了吗？",
          DialogueId = 12025404,
          GUID = "1E1AB5D8",
          NextDialogue = 12025405,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu... if you don't mind me asking, how old are you?"
        },
        [12025405] = {
          Content = "嗯，这可是个危险的问题……卡米拉没有教过你这个道理吗？还是让我们之间保留一些神秘感吧。",
          DialogueId = 12025405,
          GUID = "1E1AB602",
          NextDialogue = 12025425,
          SpeakNpcId = 210115,
          Subtitle = "That is a rather dangerous question... I had thought Camilla would have instructed you better. Let us preserve a little mystery between us."
        },
        [12025406] = {
          Content = "百年春是个什么样的商会？",
          DialogueId = 12025406,
          GUID = "1E1AB62C",
          NextDialogue = 12025407,
          Subtitle = "So, what kind of guild is EverSpring?"
        },
        [12025407] = {
          Content = "它的历史与织星客一般悠久，可以上溯到华胥立国之初。",
          DialogueId = 12025407,
          GUID = "1E1AB656",
          NextDialogue = 12025408,
          SpeakNpcId = 210115,
          Subtitle = "Its history parallels that of the Starweavers, reaching all the way back to Huaxu's founding."
        }
      }
    end
  },
  {
