        [12025419] = {
          Content = "为什么一定要从沿海洞穴过去，不能从大路走吗？",
          DialogueId = 12025419,
          GUID = "1E1AB84E",
          NextDialogue = 12025420,
          SpeakNpcId = 100001,
          Subtitle = "Why the coastal cave? Can't I just take the main road?"
