        [12030452] = {
          Camera = "204.449219,394.667969,139.548828,0.000097,-5.599737,-123.286819,35.000015,355.657684,false,Manual,22.0",
          ContentES = "No, está ayudando a su madre en el mercado. Hoy solo seremos tres para jugar.",
          DialogueId = 12030452,
          FinalCamera = "190.858887,374.125977,137.133789,0.000097,-5.599737,-123.486916,35.000015,355.657684,false,Manual,22.0",
          GUID = "1E1DF208",
          NextDialogue = 12030453,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211010},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{ActorId{211010},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 211010,
          Subtitle = "Nope. He said he's helping his mum at the stall. So it's just the three of us today.",
          TalkActionId = {
            [1] = "211010:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211001:p(-60)"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DF208"
        },
        [12030453] = {
          ContentES = "¿Qué? ¡Tres es un rollo! Necesitamos a alguien más… A ver…",
          DialogueId = 12030453,
          GUID = "1E1DF232",
          NextDialogue = 12030454,
          SpeakNpcId = 211011,
          Subtitle = "Aww, only three? That's no fun! We need one more player... Let's see—",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DF232"
        },
        [12030454] = {
          Camera = "-50.73291,28.598633,98.257812,0.00012,-2.799366,-114.086708,35.000015,355.657684,false,Manual,22.0",
          ContentES = "¡Ah! ¡Mirad! ¡Es la hermana vampira de Outsider!",
          DialogueId = 12030454,
          GUID = "1E1DF25C",
          NextDialogue = 12030455,
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{211011},AnimationId{"Shock_Start"},Duration{1}},
CameraMoveTo{_delay{3},TargetPosition{"-44.11377,-451.568359,90.689453,0.000174,-0.999236,100.920631,35.0,186.932434,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 211011,
          Subtitle = "Hey! Look! It's Outsider's vampire sister!!!",
          TurnTo = {
            [1] = "211011:p(60)",
            [2] = "211010:p(60)",
            [3] = "211013:p(-60)"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DF25C"
        },
        [12030455] = {
          Camera = "-315.119629,1243.041016,116.180664,0.000182,-2.999286,98.121964,35.0,186.932434,false,Manual,2.8",
          ContentES = "¿Eh…?",
          DialogueId = 12030455,
          GUID = "1E1DF286",
          Scripts = "PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"TilteHead_Start\"},Duration{1}}",
          SpeakNpcId = 211001,
          Subtitle = "Huh...?",
          TurnTo = {
            [1] = "211001:p(60)"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DF286"
        },
        [12030501] = {
          Camera = "590.681396,410.486328,425.555664,0.000122,-21.799442,-144.886139,35.000011,1094.441895,false,Manual,15.0",
          ContentES = "¿Qué es una “hermana vampira”?",
          DialogueId = 12030501,
          FacialId = {
            [1] = "211001:Think01"
          },
          FinalCamera = "511.094238,354.519531,386.642578,0.000122,-21.799442,-144.886139,35.000011,1094.441895,false,Manual,15.0",
          GUID = "1E1DFA12",
          NextDialogue = 12030502,
          SpeakNpcId = 211010,
          Subtitle = "What's a \"vampire sister\"?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFA12"
        },
        [12030502] = {
          ContentES = "Pues su hermana. Yo nunca la he visto fuera. Los vampiros no se atreven a salir de día, ¿no?",
          DialogueId = 12030502,
          GUID = "1E1DFA3C",
          NextDialogue = 12030503,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"211011:n(211010)"}},
PlayAnimation{ActorId{211011},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 211011,
          Subtitle = "Just Outsider's sister, duh! I've never seen her come out of the house during the day. Only vampires do that, right?",
          TalkActionId = {
            [1] = "211011:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFA3C"
        },
        [12030503] = {
          ContentES = "¿En serio? ¿Una vampira de verdad? ¿Crees que podría ayudarnos a contar nuestras piedrecitas? Juro que siempre desaparecen…",
          DialogueId = 12030503,
          GUID = "1E1DFA66",
          NextDialogue = 12030504,
          Scripts = "PlayAnimation{ActorId{211011},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 211010,
          Subtitle = "Really? A real vampire? Think she can help count our pebbles? I swear they keep disappearing...",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFA66"
        },
        [12030504] = {
          Camera = "-350.497559,574.898438,120.862305,0.000087,-5.199591,-70.882019,35.000015,1094.441895,false,Manual,15.0",
          ContentES = "P-Pero… dijiste que nunca salía. Y ahora está justo ahí…",
          DialogueId = 12030504,
          FinalCamera = "-328.568359,511.637695,114.770508,0.000087,-5.199591,-70.882019,35.000015,1094.441895,false,Manual,15.0",
          GUID = "1E1DFA90",
          NextDialogue = 12030505,
          Scripts = "LookAt{LookAtDescription{\"211011:n(211011)\"}}",
          SpeakNpcId = 211013,
          Subtitle = "B—But... you said she never comes out. And now she's right there...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFA90"
        },
        [12030505] = {
          ContentES = "¡A lo mejor se ha vuelto súper fuerte y el sol ya no le da miedo!",
          DialogueId = 12030505,
          GUID = "1E1DFABA",
          NextDialogue = 12030506,
          Scripts = "MoveTo{ActorId{211001},TargetPoint{\"FIX01\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 211011,
          Subtitle = "Well... maybe she levelled up! She's not scared of the sun anymore!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFABA"
        },
        [12030506] = {
          Camera = "484.082031,395.953125,143.116699,0.000113,-5.199065,-139.488251,35.000008,1094.441895,false,Manual,15.0",
          ContentES = "Uuuh… eso da todavía más miedo…",
          DialogueId = 12030506,
          GUID = "1E1DFAE4",
          NextDialogue = 12030507,
          SpeakNpcId = 211013,
          Subtitle = "Whoaa... that's even scarier...!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFAE4"
        },
        [12030507] = {
          Camera = "-316.86377,-742.658203,241.222656,0.000068,-13.399403,70.110031,35.000011,1094.441895,false,Manual,15.0",
          ContentES = "Eh… ¿hola…?",
          DialogueId = 12030507,
          FinalCamera = "-393.217285,-712.53125,241.222656,0.000066,-13.599384,64.110405,35.000011,1094.441895,false,Manual,15.0",
          GUID = "1E1DFB0E",
          NextDialogue = 12030508,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"211013:n(211001)"}},
LookAt{LookAtDescription{"211011:n(211001)"}},
LookAt{LookAtDescription{"211010:n(211001)"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Um... hi.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211001:p(-40)",
            [2] = "211013:p(-100)",
            [3] = "211010:p(21)",
            [4] = "211011:p(40)"
          },
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFB0E"
        },
        [12030508] = {
          ContentES = "¡Aaaah! ¡No me muerdas! ¡Soooocorro!",
          DialogueId = 12030508,
          GUID = "1E1DFB38",
          NextDialogue = 12030509,
          SpeakNpcId = 211013,
          Subtitle = "Waaah! Don't bite me—! Heeelp!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFB38"
        },
        [12030509] = {
          Camera = "-122.321777,-416.608398,114.792969,0.00019,-3.398401,86.115959,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "No, no, te has equivocado. Me llamo Fina. Soy una humana normal, igual que vosotros.",
          DialogueId = 12030509,
          FinalCamera = "-119.817871,-379.738281,112.728027,0.000189,-3.198393,86.115959,24.419483,1094.441895,false,Manual,15.0",
          GUID = "1E1DFB62",
          NextDialogue = 12030510,
          Scripts = "PlayAnimation{ActorId{211001},AnimationId{\"Explain02_Start\"}}",
          SpeakNpcId = 211001,
          Subtitle = "No no, you've got it wrong. My name's Fina. I'm just a regular human, like you.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFB62"
        },
        [12030510] = {
          ContentES = "¿Entonces no eres una vampira…? ¿Y quién va a ayudarme con mis piedrecitas…?",
          DialogueId = 12030510,
          GUID = "1E1DFB8C",
          NextDialogue = 12030511,
          Scripts = "PlayAnimation{ActorId{211001},AnimationId{\"Explain02_End\"}}",
          SpeakNpcId = 211010,
          Subtitle = "So you're not a vampire...? Then who's gonna help with my pebbles...",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFB8C"
        },
        [12030511] = {
          Camera = "-172.100098,448.194336,142.628418,0.000192,-6.198451,-81.282036,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "Yo prefiero que se los lleven los gatos antes que una vampira…",
          DialogueId = 12030511,
          FinalCamera = "-167.022461,415.089844,138.991211,0.000192,-6.198451,-81.282036,24.419483,1094.441895,false,Manual,15.0",
          GUID = "1E1DFBB6",
          NextDialogue = 12030512,
          SpeakNpcId = 211013,
          Subtitle = "I'd rather the kitten stole them all than let a vampire count 'em...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFBB6"
        },
        [12030512] = {
          Camera = "-21.348633,155.701172,136.172852,0.000172,-8.198392,-103.282524,24.419487,1094.441895,false,Manual,15.0",
          ContentES = "Pero… si no eres una vampira, ¿por qué nunca sales?",
          DialogueId = 12030512,
          FinalCamera = "-23.747559,145.540039,134.669922,0.000172,-8.198392,-103.282524,24.419487,1094.441895,false,Manual,15.0",
          GUID = "1E1DFBE0",
          NextDialogue = 12030513,
          SpeakNpcId = 211011,
          Subtitle = "Then how come you never come outside, if you're not a vampire?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFBE0"
        },
        [12030513] = {
          Camera = "-48.152832,-55.458984,119.407227,0.000111,0.201088,78.511482,24.419483,118.311295,false,Manual,2.8",
          ContentES = "Porque me pongo enferma con frecuencia. Mi cuerpo es frágil, así que suelo quedarme en casa.",
          DialogueId = 12030513,
          GUID = "1E1DFC0A",
          NextDialogue = 12030514,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211001:n(211011)"}},
PlayFacial{ActorId{211001},FacialId{"Sad02"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I get sick a lot. So I usually stay home and rest.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFC0A"
        },
        [12030514] = {
          ContentES = "¿Qué? ¡Eso es muy triste! Estar enfermo debe de ser horrible…",
          DialogueId = 12030514,
          GUID = "1E1DFC34",
          NextDialogue = 12030515,
          Scripts = "PlayFacial{ActorId{211001},FacialId{\"None\"}},",
          SpeakNpcId = 211011,
          Subtitle = "...That sucks. Being sick is the worst!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFC34"
        },
        [12030515] = {
          Camera = "-59.737305,82.518555,113.938965,0.000173,-7.798696,-146.279343,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "Mi mamá dice que, si uno es débil, tiene que hacer ejercicio.",
          DialogueId = 12030515,
          GUID = "1E1DFC5E",
          NextDialogue = 12030516,
          SpeakNpcId = 211010,
          Subtitle = "My mum says if your body's weak, you've gotta exercise more.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFC5E"
        },
        [12030516] = {
          Camera = "-59.737305,82.518555,113.938965,0.000173,-7.798696,-146.279343,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "¡Exacto! Fina, si corres cien vueltas a la plaza cada mañana, ¡enseguida estarás en plena forma!",
          DialogueId = 12030516,
          FinalCamera = "-59.737305,82.518555,113.938965,0.000178,-6.998655,-109.679207,24.419483,1094.441895,false,Manual,15.0",
          GUID = "1E1DFC88",
          NextDialogue = 12030517,
          SpeakNpcId = 211011,
          Subtitle = "Exactly! Fina, you just need to run a hundred laps round the square every morning! You'll be super strong in no time!",
          TalkActionId = {
            [1] = "211011:Agree"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFC88"
        },
        [12030517] = {
          Camera = "-139.903809,-349.098633,119.885742,0.000172,-4.79846,81.120529,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "Ah… jeje… gracias por el consejo. Pero no se me da muy bien correr. Solo caminar un poco por aquí ya es mucho para mí.",
          DialogueId = 12030517,
          GUID = "1E1DFCB2",
          NextDialogue = 12030518,
          Scripts = [[
SEQ{
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{ActorId{211001},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Ah... hehe, thanks for the advice. But I'm not much of a runner. Just walking around here is already a lot for me.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFCB2"
        },
        [12030518] = {
          Camera = "-123.172852,164.339844,119.664062,0.000143,-2.398284,-53.487343,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "Entonces… Fina, ¿quieres jugar con nosotros? Jugar también es hacer ejercicio, ¿no?",
          DialogueId = 12030518,
          GUID = "1E1DFCDC",
          NextDialogue = 12030519,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211001:n(211013)"}},
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 211013,
          Subtitle = "Then... Fina, wanna play with us? Playing counts as exercise too... right?",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFCDC"
        },
        [12030519] = {
          Camera = "-259.01123,416.636719,141.748047,0.000137,-6.398309,-67.487495,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "¡Ohhh, tienes razón! ¡Y además nos falta uno! Fina, ¡ven a jugar al Glotón con nosotros!",
          DialogueId = 12030519,
          FinalCamera = "-272.342285,448.800781,145.652344,0.000137,-6.398309,-67.487495,24.419483,1094.441895,false,Manual,15.0",
          GUID = "1E1DFD06",
          NextDialogue = 12030520,
          SpeakNpcId = 211011,
          Subtitle = "Ohhh, good point! And we're one short anyway! Fina, come and play Greedy Gobbler with us!",
          TalkActionId = {
            [1] = "211001:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD06"
        },
        [12030520] = {
          Camera = "-45.714355,-177.095703,117.589355,0.000137,-0.198854,82.011528,35.000019,218.878983,false,Manual,2.8",
          ContentES = "¡Vale! Pero… ¿qué es el “Glotón”?",
          DialogueId = 12030520,
          FinalCamera = "-43.980469,-164.746094,117.545898,0.000137,-0.198854,82.011528,35.000019,218.878983,false,Manual,2.8",
          GUID = "1E1DFD30",
          NextDialogue = 12030521,
          Scripts = [[
SEQ{
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I'd love to! But... what's Greedy Gobbler? I don't think I've heard of that one...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD30"
        },
        [12030521] = {
          Camera = "-253.641113,416.605469,138.781738,0.000156,-6.998512,-71.883408,24.419483,1094.441895,false,Manual,15.0",
          ContentES = "¡Es muy fácil! Un jugador es el Glotón, y los demás son patatas asadas. El Glotón cierra los ojos y cuenta mientras las patatas se esconden.",
          DialogueId = 12030521,
          FinalCamera = "-240.412598,376.173828,133.561035,0.000156,-6.998512,-71.883408,24.419483,1094.441895,false,Manual,15.0",
          GUID = "1E1DFD5A",
          NextDialogue = 12030522,
          SpeakNpcId = 211011,
          Subtitle = "It's super easy — I'll teach you! One person plays the Greedy Gobbler, and the rest of us are roasted potatoes. When the game starts, the Gobbler closes their eyes, and the potatoes sneak off to hide!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD5A"
        },
        [12030522] = {
          ContentES = "Cuando termina de contar hasta sesenta, abre los ojos y sale a la caza. Si atrapa a una — ¡ñam! — ¡se la come!",
          DialogueId = 12030522,
          GUID = "1E1DFD84",
          NextDialogue = 12030523,
          SpeakNpcId = 211011,
          Subtitle = "Once the Gobbler finishes counting to sixty, they open their eyes and go hunting! If they find a potato — chomp! — they gobble it up!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFD84"
        },
        [12030523] = {
          ContentES = "Si se come todas las patatas en tres minutos, gana. Si no, se desmaya de hambre y ¡las patatas ganan la partida!",
          DialogueId = 12030523,
          GUID = "1E1DFDAE",
          NextDialogue = 12030524,
          SpeakNpcId = 211011,
          Subtitle = "If the Gobbler eats all the potatoes in three minutes, they win. But if even one potato's left, the Gobbler faints from hunger — and the potatoes win!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFDAE"
        },
        [12030524] = {
          Camera = "-58.322266,-105.651367,119.556152,0.000138,0.401116,79.010231,35.000019,178.36145,false,Manual,2.8",
          ContentES = "Pero… las patatas no tienen piernas. ¿Por qué iban a correr y esconderse?",
          DialogueId = 12030524,
          FinalCamera = "-56.606445,-96.818359,119.618652,0.000138,0.401116,79.010231,35.000019,159.390686,false,Manual,2.8",
          GUID = "1E1DFDD8",
          NextDialogue = 12030525,
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"Think01"}},
PlayAnimation{ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_CuteHairAction_Loop"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "But... potatoes don't have legs. Why would they run and hide?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFDD8"
        },
        [12030525] = {
          Camera = "-157.704102,-477.165039,108.151855,0.000125,-0.99884,82.013466,35.000015,251.595764,false,Manual,22.0",
          ContentES = "Tiene razón. Las patatas que hace mi mamá se quedan en el plato. Totalmente quietas.",
          DialogueId = 12030525,
          GUID = "1E1DFE02",
          NextDialogue = 12030526,
          SpeakNpcId = 211010,
          Subtitle = "She's got a point. The potatoes my mum makes just sit on a plate. Totally still.",
          TalkActionId = {
            [1] = "211010:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE02"
        },
        [12030526] = {
          ContentES = "Eh… ¡ese no es el punto!",
          DialogueId = 12030526,
          GUID = "1E1DFE2C",
          NextDialogue = 12030527,
          SpeakNpcId = 211011,
          Subtitle = "Uh... that's not the point!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE2C"
        },
        [12030527] = {
          Camera = "-27.393555,-102.768555,119.618652,0.000139,-0.198916,89.009705,35.000019,159.390686,false,Manual,2.8",
          ContentES = "Espera… ¡ya entendí! ¡Son patatas mágicas… bendecidas por un buen mago!",
          DialogueId = 12030527,
          FinalCamera = "-26.844238,-70.899414,119.508301,0.000139,-0.198916,89.009674,35.000019,129.833313,false,Manual,2.8",
          GUID = "1E1DFE56",
          NextDialogue = 12030528,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"211001:n(211011)"}},
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Oh, I get it! They must be magic roasted potatoes, blessed by a kind-hearted magician!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE56"
        },
        [12030528] = {
          ContentES = "¡Ohhh! ¡Entonces yo quiero ser la patata mágica más fuerte!",
          DialogueId = 12030528,
          GUID = "1E1DFE80",
          NextDialogue = 12030529,
          SpeakNpcId = 211010,
          Subtitle = "Ooooh! Then I wanna be the strongest magic roasted potato!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFE80"
        },
        [12030529] = {
          ContentES = "Patatas mágicas… deben de estar riquísimas…",
          DialogueId = 12030529,
          GUID = "1E1DFEAA",
          NextDialogue = 12030530,
          SpeakNpcId = 211013,
          Subtitle = "Magic roasted potato... sounds tasty...",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFEAA"
        },
        [12030530] = {
          Camera = "-224.390625,-505.521484,146.001465,0.000133,-7.598578,76.013123,35.000019,329.374176,false,Manual,22.0",
          ContentES = "¡Perfecto! Entonces nosotros seremos las patatas, y Fina, tú serás el Glotón. ¿Vale?",
          DialogueId = 12030530,
          FinalCamera = "-229.759766,-527.399414,148.927734,0.000134,-7.398529,76.212738,35.000019,329.374176,false,Manual,22.0",
          GUID = "1E1DFED4",
          NextDialogue = 12030531,
          SpeakNpcId = 211011,
          Subtitle = "Then we'll all be roasted potatoes and Fina can be the Gobbler! Is that okay, Fina?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFED4"
        },
        [12030531] = {
          Camera = "-94.611328,-127.818359,128.793945,0.000135,-2.398503,70.012207,35.000019,329.374176,false,Manual,22.0",
          ContentES = "¡Sí! Entonces cierro los ojos… y empiezo a contar… Uno… dos… tres…",
          DialogueId = 12030531,
          FinalCamera = "-89.286133,-113.015625,128.135254,0.000136,-2.398503,70.212196,35.000019,329.374176,false,Manual,22.0",
          GUID = "1E1DFEFE",
          Scripts = "PlayFacial{_delay{2},ActorId{211001},FacialId{\"Confident02\"}}",
          SpeakNpcId = 211001,
          Subtitle = "Okay — then eyes closed and counting starts~ One... two... three...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFEFE"
        },
        [12030532] = {
          Content = "转场，小孩们消失，出现三个调查点（没有先后顺序）",
          DialogueId = 12030532,
          GUID = "1E1DFF28",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DFF28"
        },
        [12030601] = {
          ContentES = "Hmm… ¿dónde se esconden estas patatas asadas…?",
          DialogueId = 12030601,
