          SpeakNpcId = 211001,
          Subtitle = "But in stories, heroes never give up. No matter how tough it gets — they always keep going, with help from their friends!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E3BB2"
        },
        [12030902] = {
          Camera = "21.739258,184.106445,139.543457,0.000111,-7.199613,-110.180969,35.000011,113.605156,false,DoNotOverride,6.0",
          ContentES = "¡Claro! Amigos… ¡Puedo pedir ayuda a mis amigos mágicos! El Gran Mago tiene el mejor olfato del mundo… ¡Él podrá encontrar estas patatas asadas!",
