        [12031308] = {
          Camera = "53.371582,-201.73291,119.283203,0.000088,-2.599857,109.347733,35.000011,198.553635,false,DoNotOverride,4.5",
          ContentES = "“¡Oh! ¡Pero si es el Pequeño Ruiseñor! ¡Bienvenido, bienvenido!” ¡Y las puertas del Reino de la Basura se abrieron de par en par ante ella!",
          DialogueId = 12031308,
          GUID = "1E1E7E78",
          NextDialogue = 12031309,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"Explain01_Start"}},
PlayAnimation{_delay{3},ActorId{211003},AnimationId{"Explain01_End"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "\"Oh-ho! It's the little nightingale! Welcome!\" And with a mighty creak, the gates of the Rubbish Kingdom swung open!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7E78"
        },
        [12031309] = {
          Camera = "-122.83252,43.303711,127.951172,0.000087,-7.399813,-27.451759,35.000011,198.553635,false,DoNotOverride,4.5",
          ContentES = "Y allí estaba la Princesa Dedos Mágicos, una noble gobernante que convierte los desperdicios más aburridos en tesoros deslumbrantes…",
          DialogueId = 12031309,
          FinalCamera = "-208.64209,87.388184,140.554932,0.000097,-7.999845,-27.251091,35.000011,307.262146,false,DoNotOverride,4.5",
          GUID = "1E1E7EA2",
          NextDialogue = 12031310,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Feina_Story_Wish_Start"}},
PlayFacial{_delay{3},ActorId{211003},FacialId{"Smile01"}},
PlayFacial{_delay{6},ActorId{211003},FacialId{"Shock01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "And there stood the Princess of Magic Fingers — a noble ruler said to turn the dullest scraps into dazzling treasure...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7EA2"
        },
        [12031310] = {
          Camera = "14.431152,-138.814453,120.02417,0.000095,-3.39987,115.548187,35.000011,307.262146,false,DoNotOverride,4.5",
          ContentES = "Ejem… Pequeña Fina, perdón pero… ¿no podrías darme otro papel? “Princesa” es un poco embarazosa…",
          DialogueId = 12031310,
          GUID = "1E1E7ECC",
          NextDialogue = 12031311,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{211003},AnimationId{"ScratchHead_Start"}},
PlayFacial{_delay{0},ActorId{211003},FacialId{"Ahaha02"}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Feina_Story_CuteHairAction_End"}},
PlayFacial{_delay{5},ActorId{211003},FacialId{"Sad02"}},
PlayAnimation{_delay{6},ActorId{211003},AnimationId{"ScratchHead_End"}},
PlayAnimation{_delay{7},ActorId{211003},AnimationId{"DisagreeHead"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "Ahem! Fina — sorry to cut in, but... could we pick a different title for my character? \"Princess\" is a bit... embarrassing.",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7ECC"
        },
        [12031311] = {
          Camera = "-149.603516,63.429688,133.592773,0.000105,-7.599821,-31.252092,35.000011,307.262146,false,DoNotOverride,4.5",
          ContentES = "¿Ah? Entonces, ¿qué título quieres, Señorita Margie?",
          DialogueId = 12031311,
          GUID = "1E1E7EF6",
          NextDialogue = 12031312,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211001},FacialId{"Shock01"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Smile01"}},
PlayFacial{_delay{0},ActorId{211003},FacialId{"Smile01"}}}]],
          SpeakNpcId = 211001,
          Subtitle = "Then what title would you prefer, Miss Margie?",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7EF6"
        },
        [12031312] = {
          Camera = "5.123535,-124.944336,98.38916,0.000106,5.400091,110.747116,35.000011,307.262146,false,DoNotOverride,4.5",
          ContentES = "Llámame… la “Detective Taciturna”!",
          DialogueId = 12031312,
          GUID = "1E1E7F20",
          NextDialogue = 12031313,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211003},FacialId{"Confident02"}},
PlayAnimation{_delay{0},ActorId{211003},AnimationId{"ConfidentLR_Start"}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Explain02_End"}},
PlayFacial{_delay{3},ActorId{211003},FacialId{"Happy02"}},
}]],
          SpeakNpcId = 211003,
          Subtitle = "I'd like to be... the Reticent Detective!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F20"
        },
        [12031313] = {
          Camera = "-128.556641,-42.028809,97.801025,0.000109,4.600009,-10.652984,35.000015,307.262146,false,DoNotOverride,4.5",
          ContentES = "¡De acuerdo! Y así, el Pequeño Ruiseñor conoció a la brillante Detective Taciturna: “¡Hola, Detective! Fina quiere ser tu amiga. ¿Podemos jugar juntas?”",
          DialogueId = 12031313,
          GUID = "1E1E7F4A",
          NextDialogue = 12031314,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211001},FacialId{"Happy01"}},
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"ConfidentR_End"}},
SEQ{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"AgreeHead"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Feina_Story_Wish_Start"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Alright then! And so, the little nightingale met the keen-eyed, ever-wise Reticent Detective. \"Good day, Detective! I'd love to be your friend — may I join your quest?\"",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F4A"
        },
        [12031314] = {
          Camera = "11.094727,-128.317383,143.341797,0.000121,-10.000031,112.346825,35.000011,293.683075,false,DoNotOverride,4.5",
          ContentES = "“¡Por supuesto!” respondió la detective, dando golpecitos a el casco de olla sobre su cabeza. “¡A partir de hoy, serás… mi Pequeña Ayudante!”",
          DialogueId = 12031314,
          GUID = "1E1E7F74",
          NextDialogue = 12031315,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211003},FacialId{"Happy02"}},
SEQ{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"AgreeHead"}},
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"SpecialHoldHelmet_Start"}},
PlayAnimation{_delay{3},ActorId{211003},AnimationId{"SpecialHoldHelmet_End"}},
PlayFacial{_delay{0},ActorId{211003},FacialId{"Confident02"}}
}
}]],
          SpeakNpcId = 211003,
          Subtitle = "\"But of course!\" said the Reticent Detective, tapping the pot helmet on her head. \"From this day forward, you shall be... my Little Sidekick!\"",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F74"
        },
        [12031315] = {
          Camera = "-38.45166,0.020508,114.371826,0.000105,-0.600066,-45.252876,35.000011,120.0,false,DoNotOverride,4.5",
          ContentES = "“¿Pequeña Ayudante”…? ¿Es mi nuevo rol?",
          DialogueId = 12031315,
          GUID = "1E1E7F9E",
          NextDialogue = 12031316,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211001},FacialId{"Shock01"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Happy02"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "\"Little Sidekick\"? Is that my new character?",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7F9E"
        },
        [12031316] = {
          Camera = "33.406738,-173.764648,123.195068,0.000108,-4.399994,102.947136,35.000011,120.0,false,DoNotOverride,4.5",
          ContentES = "¡Exactamente! Todos los grandes detectives tienen un súper ayudante a su lado.",
          DialogueId = 12031316,
          GUID = "1E1E7FC8",
          NextDialogue = 12031317,
          Scripts = [[
PARA{
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"ConfidentLR_Start"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Feina_Story_Wish_End"}},
PlayFacial{_delay{0},ActorId{211001},FacialId{"Smile02"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "It's your official title! Every great detective needs a brilliant sidekick.",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7FC8"
        },
        [12031317] = {
          Camera = "-124.683594,50.607422,131.177734,0.000107,-7.000397,-33.257271,35.000015,231.188461,false,DoNotOverride,4.5",
          ContentES = "Entonces… ¿qué debe hacer una Pequeña Ayudante?",
          DialogueId = 12031317,
          GUID = "1E1E7FF2",
          NextDialogue = 12031318,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211001},FacialId{"Happy01"}},
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"Agree"}},
PlayFacial{_delay{0},ActorId{211001},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Okay... so what does a Little Sidekick actually do?",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7FF2"
        },
        [12031318] = {
          Camera = "13.251953,-312.11084,97.703125,0.000099,0.99994,93.545998,35.000011,231.188461,false,DoNotOverride,4.5",
          ContentES = "Para que lo sepas, ¡estoy llevando a cabo una investigación enorme! Una banda de malvados secuestradores de niños ha vuelto a aparecer… Están tramando algo malo en Lago Helado, ¡pero nadie se ha dado cuenta!",
          DialogueId = 12031318,
          FinalCamera = "6.855957,-246.094727,98.700195,0.0001,1.599931,96.14592,35.000011,231.188461,false,DoNotOverride,4.5",
          GUID = "1E1E801C",
          NextDialogue = 12031319,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"ConfidentLRToExplainL_Start"}},
PlayAnimation{_delay{3},ActorId{211003},AnimationId{"ConfidentLRToExplainL_End"}},
PlayAnimation{_delay{2},ActorId{211003},AnimationId{"ConfidentLR_End"}}
},
PlayFacial{_delay{4},ActorId{211003},FacialId{"Confident01"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "Truth is, I'm on a case. A big one. A gang of no-good, child-snatching bandits is back in town — and they're planning something awful, right here in Icelake. But no one else has noticed.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E801C"
        },
        [12031319] = {
          Camera = "7.620117,-146.29248,102.274414,0.000101,2.99988,109.746193,35.000011,231.188461,false,DoNotOverride,4.5",
          ContentES = "Mira: en el basurero grande n.º 3, ¡encontré esta prueba! ¡Esta marca es exactamente la misma que la del crimen de hace un año!",
          DialogueId = 12031319,
          GUID = "1E1E8046",
          NextDialogue = 12031320,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{_delay{0},ActorId{211003},AnimationId{"Give"}},
PlayAnimation{_delay{3},ActorId{211003},AnimationId{"Talk02_Start"}},
PlayAnimation{_delay{6},ActorId{211003},AnimationId{"Talk02_End"}},
},
PlayFacial{_delay{3},ActorId{211003},FacialId{"Think01"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "Look — I found this scrap in Big Bin No. 3. See this mark? It's exactly like the one from the crime scene a year ago.",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8046"
        },
        [12031320] = {
          ContentES = "Pero la Oficina de Seguridad dijo que esto no contaba como prueba… Así que yo, la Detective Taciturna, decidí encontrarlos, frustrar su complot y proteger a todos los niños de Lago Helado.",
          DialogueId = 12031320,
          GUID = "1E1E8070",
          NextDialogue = 12031321,
          Scripts = [[
SEQ{
PlayFacial{_delay{0},ActorId{211003},FacialId{"Unhappy02"}},
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"DisagreeHead"}},
PlayAnimation{_delay{1},ActorId{211003},AnimationId{"Angry02_Start"}},
PlayFacial{_delay{0},ActorId{211003},FacialId{"Confident02"}},
PlayAnimation{_delay{5},ActorId{211003},AnimationId{"Angry02_End"}},
PlayAnimation{_delay{0},ActorId{211003},AnimationId{"Confident_Start"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "But the Security Bureau didn't think it counts as evidence... So now it's up to me — the Reticent Detective — to track them down, stop their wicked plot, and keep the children of Icelake safe!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8070"
        },
        [12031321] = {
          Camera = "0.609863,-390.711426,114.49585,0.000112,-0.000246,91.142174,35.000015,440.047546,false,DoNotOverride,4.5",
          ContentES = "¡Pequeña Ayudante, vamos a trabajar juntas! Ya he revisado los basureros del 1 al 5. Ahora voy al n.º 6… ¡lo que significa que el n.º 7 es tu misión!",
          DialogueId = 12031321,
          FinalCamera = "-2.351074,-242.245605,114.412109,0.000112,-0.200261,91.142151,35.000015,440.047546,false,DoNotOverride,4.5",
          GUID = "1E1E809A",
          NextDialogue = 12031322,
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{211003},FacialId{"Smile02"}},
LookAt{_delay{5},LookAtDescription{"211003:p(feinafx12_lookat01)"}},
PlayFacial{_delay{5},ActorId{211003},FacialId{"Smile01"}},
LookAt{_delay{6},LookAtDescription{"211001:p(feinafx12_lookat01)"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "Little Sidekick, let's solve the case together! I've already checked Bins No. 1 through to 5. I'm heading to Bin No. 6 next... which means Bin No. 7 is your mission!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E809A"
        },
        [12031322] = {
          Camera = "-166.953125,48.82959,124.791748,0.000113,-4.000059,-23.054798,35.000011,231.188461,false,DoNotOverride,4.5",
          ContentES = "¡Sí, señorita! Pequeña Ayudante Fina, ¡en la misión!",
          DialogueId = 12031322,
          GUID = "1E1E80C4",
          Scripts = [[
SEQ{
PARA{
LookAt{_delay{0},LookAtDescription{"211001:n(211003)"}},
LookAt{_delay{1},LookAtDescription{"211003:n(211001)"}}
},
PARA{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"AgreeHead"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Explain02_Start"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Yes, ma'am! Little Sidekick Fina — on the case!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E80C4"
        },
        [12031323] = {
          Content = "调查垃圾桶1（小垃圾桶）\n（这里如果想细节一些的话可以给地图上所有垃圾桶编个号，用于设计与玛尔洁相关的内容。不方便的话确保大小和文案描述一致就行了）",
          DialogueId = 12031323,
          GUID = "1E1E80EE",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E80EE"
        },
        [12031350] = {
          Content = "湛蓝的天空【补充需求】",
          DialogueId = 12031350,
          GUID = "1E1E80EF",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E80EF"
        },
        [12031401] = {
          Camera = "-222.93663,-4.119965,77.036377,0.000147,5.602271,18.947176,35.000008,242.208893,false,DoNotOverride,2.8",
          ContentES = "¡Puaj… sólo basura…! Pero no, ¡no debo tener miedo! Soy la valiente Pequeña Ayudante de la gran Detective Taciturna. ¡Debo ser fuerte y cumplir mi misión!",
          DialogueId = 12031401,
          GUID = "1E1E8DBA",
          NextDialogue = 12031402,
          Scripts = [[
SEQ{
PARA{
LookAt{_delay{0},LookAtDescription{"211001:p(QuestPoint_Feina02fx13)"}},
PlayFacial{_delay{0},ActorId{211001},FacialId{"Shock02"}}
},
PARA{
CameraMoveTo{_delay{4.01},TargetPosition{"-128.022781,66.455872,85.407471,0.000122,13.602055,-6.65639,35.000008,184.110672,false,DoNotOverride,2.8"},duration{0}},
PlayFacial{_delay{4},ActorId{211001},FacialId{"Confident01"}},
PlayAnimation{_delay{4},ActorId{211001},AnimationId{"Feina_Story_Wish_Start"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Eww... it's all rubbish... ...Uh-uh! I can't give up now! I'm the brave Little Sidekick of the great Reticent Detective — and I've got a mission to finish!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8DBA"
        },
        [12031402] = {
          ContentES = "Veamos… ¡mira, un pedazo de papel! ¿Quizá sea una pista?",
          DialogueId = 12031402,
          GUID = "1E1E8DE4",
          NextDialogue = 12031403,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Give"}},
PlayAnimation{_delay{2},ActorId{211001},AnimationId{"Think_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Let's see... here's a scrap of paper. Maybe there's a clue?",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8DE4"
        },
        [12031403] = {
          ContentES = "“Todo lo que necesitas es la oportunidad adecuada, y podrías ser el próximo gran jefe…” ¿Eh? ¿Qué es esto…? En fin, no creo que los grandes jefes secuestren niños.",
          DialogueId = 12031403,
          GUID = "1E1E8E0E",
          NextDialogue = 12031404,
          Scripts = [[
PARA{
SEQ{
PlayFacial{_delay{2},ActorId{211001},FacialId{"Shock01"}},
PlayFacial{_delay{2},ActorId{211001},FacialId{"Disappoint01"}},
PlayFacial{_delay{2},ActorId{211001},FacialId{"Happy01"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Shock01"}},
},
PlayAnimation{_delay{5},ActorId{211001},AnimationId{"Think_End"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "\"All you need is the right opportunity, and you could be the next bigshot...\" Huh? What's this...? Anyway, I don't think bigshots go around stealing children.",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E0E"
        },
        [12031404] = {
          ContentES = "Y este dice…",
          DialogueId = 12031404,
          GUID = "1E1E8E38",
          NextDialogue = 12031405,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Give"}},
PlayFacial{_delay{0},ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "And this one says...",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E38"
        },
        [12031405] = {
          Camera = "-156.79039,1.709183,91.499512,0.000147,7.401883,17.145016,35.000011,278.655243,false,DoNotOverride,2.8",
          ContentES = "“Todos los ciudadanos de Lago Helado conocen el meteórico ascenso y la repentina caída de la familia Glenville…” ¿Eh!?",
          DialogueId = 12031405,
          FinalCamera = "-108.686592,16.733475,98.225098,0.000142,7.601891,17.344889,35.000011,130.0,false,DoNotOverride,2.8",
          GUID = "1E1E8E62",
          NextDialogue = 12031406,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Think_Start"}},
PlayFacial{_delay{5.01},ActorId{211001},FacialId{"Shock02"}},
CameraMoveTo{_delay{5.01},TargetPosition{"-96.672791,18.322319,115.384521,0.000154,1.601871,16.545654,35.000011,109.004112,false,DoNotOverride,2.8"},duration{0}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "\"Every citizen of Icelake is familiar with the meteoric rise and sudden downfall of the Glenville family...\" Huh!?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E62"
        },
        [12031406] = {
          ContentES = "…Uf, nada sobre mamá o sobre mí. “Secretos del pasado”… ¿qué significará eso? Bueno… seguro que no tiene nada que ver con el caso de la Detective Taciturna. Mejor fingir que no vi nada.",
          DialogueId = 12031406,
          GUID = "1E1E8E8C",
          Scripts = [[
SEQ{
PARA{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"DisagreeHead"}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Syouganai01"}}
},
PARA{
PlayAnimation{_delay{3},ActorId{211001},AnimationId{"Explain02_Start"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Disappoint01"}},
PlayAnimation{_delay{6},ActorId{211001},AnimationId{"Explain02_End"}},
PlayFacial{_delay{5},ActorId{211001},FacialId{"Smile01"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Phew... no mention of Mum or me. What does \"hidden history\" mean, anyway...? Mmm... doesn't seem related to the case. I'll just pretend I didn't see that.",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8E8C"
        },
        [12031407] = {
          ContentES = "Fina sigue revisando los papeles, pero no encuentra nada útil.",
          DialogueId = 12031407,
          GUID = "1E1E8EB6",
          Subtitle = "Fina keeps rummaging through the bin for clues, but turns up nothing useful...",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8EB6"
        },
        [12031408] = {
          ContentES = "Regreso con Margie",
          DialogueId = 12031408,
          GUID = "1E1E8EE0",
          Subtitle = "Reports to Margie",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8EE0"
        },
        [12031501] = {
          Camera = "82.075974,-10.556297,110.049805,0.000183,0.601678,154.418808,35.000011,112.418152,false,DoNotOverride,12.0",
          ContentES = "¡Ahí estás de nuevo, Pequeña Ayudante! Mira, ¡yo encontré un nuevo pedazo de periódico con una marca! Y hay un anuncio para una obra de teatro… ¡Quizá los bandoleros apuntan al teatro!",
          DialogueId = 12031501,
