          FinalCamera = "207.430786,-37.371925,141.150879,0.000088,-4.199924,169.11882,35.000011,350.246948,false,Manual,2.8",
          GUID = "1E1EF372",
          NextDialogue = 12032022,
          SpeakNpcId = 211012,
          Subtitle = "Excuse me!? Who are you calling little? Ugh, whatever. Just answer me — can you do magic?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF372"
        },
        [12032022] = {
          Camera = "-149.126572,195.659912,131.557373,0.0001,-1.999934,-51.077328,35.000008,335.198914,false,Manual,2.8",
          ContentES = "Eh… un poco, sí.",
          DialogueId = 12032022,
          FinalCamera = "-140.549088,185.037964,131.080566,0.0001,-1.999934,-51.077328,35.000011,335.198914,false,Manual,2.8",
          GUID = "1E1EF39C",
          NextDialogue = 12032023,
