        [12032023] = {
          Camera = "112.474983,29.235161,104.275879,0.00011,2.399992,175.923996,35.000011,175.784409,false,Manual,2.8",
          ContentES = "¡Perfecto! Eh… ejem… Muy bien. Escúchame atentamente, Charon: necesito que me ayudes con algo. No es nada complicado, solo tendrás que hacer exactamente lo que te diga con tu magia.",
          DialogueId = 12032023,
          FinalCamera = "92.418343,30.663937,105.118408,0.00011,2.399992,175.924088,35.000011,175.784409,false,Manual,2.8",
          GUID = "1E1EF3C6",
          NextDialogue = 12032024,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "That's so great! Ahem... I mean, okay. Listen up, Charon — I need your help with something. It's simple. Just follow my instructions and use your magic.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF3C6"
        },
        [12032024] = {
          Camera = "215.516998,-32.253654,134.083496,0.00012,-1.199907,171.523682,35.000011,270.662476,false,Manual,2.8",
          ContentES = "Y como recompensa… toma, mira. Con esto deberías poder comer durante todo un año, ¿no?",
          DialogueId = 12032024,
          FinalCamera = "215.516998,-32.253654,134.083496,0.00012,-1.199907,171.523682,35.000011,270.662476,false,Manual,2.8",
          GUID = "1E1EF3F0",
          NextDialogue = 12032025,
          SpeakNpcId = 211012,
          Subtitle = "And your payment... Look — I can give you this much! Bet that's enough to keep you fed for a whole year, huh?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF3F0"
        },
        [12032025] = {
          Camera = "-62.110943,89.735397,140.243164,0.000095,-4.800018,-40.882198,35.000011,172.116272,false,Manual,8.0",
