          SpeakNpcId = 211012,
          Subtitle = "What? Not enough? Fine, I'll throw in more. Just—",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF444"
        },
        [12032027] = {
          Camera = "238.118057,-42.286388,133.163086,0.000128,-0.999817,168.524857,35.000008,348.288422,false,Manual,2.8",
          ContentES = "Oye, jovencita. ¿Tu profesora nunca te enseñó a pedir las cosas con educación?",
          DialogueId = 12032027,
          FinalCamera = "137.708801,24.175247,113.700439,0.000129,0.600141,-157.080948,35.000008,593.061584,false,Manual,2.8",
          GUID = "1E1EF46E",
          NextDialogue = 12032028,
          Scripts = "LookAt{LookAtDescription{\"100001:n(211012)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Hey there, missy. Didn't anyone ever teach you how to ask nicely when you want a favour?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF46E"
        },
        [12032028] = {
          Camera = "285.149689,84.910515,130.34668,0.000105,-1.19988,-161.280563,35.000011,438.518188,false,Manual,8.0",
          ContentES = "¡Uaaah! Pero… ¿y tú quién eres?",
          DialogueId = 12032028,
          FinalCamera = "270.333191,79.889786,130.019287,0.000105,-1.19988,-161.280563,35.000011,438.518188,false,Manual,8.0",
          GUID = "1E1EF498",
          NextDialogue = 12032029,
          SpeakNpcId = 211012,
          Subtitle = "Whoa—! Wh—Who are you!?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211001:p(40)",
            [2] = "211012:p(-110)"
          },
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF498"
        },
        [12032029] = {
          Camera = "-136.98381,-96.949409,138.581787,0.00012,-0.998656,-161.679504,28.0,218.307404,false,Manual,8.0",
          ContentES = "Soy su {性别:amigo|amiga}. Y, de paso, {性别:Phoxcazador|Phoxcazadora}.",
