          DialogueId = 12032804,
          GUID = "1E1F73E8",
          NextDialogue = 12032805,
          SpeakNpcId = 100001,
          Subtitle = "\"Ruse\"...? Don't you mean \"plan\"?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F73E8"
        },
        [12032805] = {
          ContentES = "Bah… es lo mismo, ¿no? Solo recuerden la idea. ¡Vamos, voy a buscar a mi amigo!",
