          Camera = "-103.942352,216.216797,150.742188,0.000137,-14.478873,152.218048,28.000006,103.690712,false,Manual,2.8",
          ContentES = "Pero… había prometido ayudar, y al final me escapé… ¿Qué voy a hacer?",
          DialogueId = 12033009,
          GUID = "1E1F95B4",
          NextDialogue = 12033010,
          SpeakNpcId = 211001,
          Subtitle = "But... I ran away. I promised to help Cassandra — and I just ran. What should I do...?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F95B4"
        },
        [12033010] = {
          Camera = "-84.477493,229.648438,149.128906,0.000138,-4.679171,-33.583679,55.000008,174.406815,false,Manual,2.8",
          ContentES = "No te preocupes. Déjamelo a mí. Soy {性别:un Phoxcazador|una Phoxcazadora}, cumplir un encargo hasta el final es mi especialidad.",
          DialogueId = 12033010,
          FinalCamera = "-73.702179,222.496094,148.070312,0.000138,-4.679171,-33.583744,55.000008,158.766953,false,Manual,2.8",
          GUID = "1E1F95DE",
          NextDialogue = 12033011,
          Scripts = [[
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Don't worry. Leave this one to me. I'm a Phoxhunter — finishing tough jobs is what I do best.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F95DE"
        },
        [12033011] = {
          Camera = "108.718094,134.107422,142.527344,0.000134,-3.278443,166.01561,28.000006,316.033936,false,Manual,2.8",
          ContentES = "De acuerdo… Pero, por favor… discúlpate con la señorita Cassandra por mí…",
          DialogueId = 12033011,
          GUID = "1E1F9608",
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Stop"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0051_story_danger"}},
LookAt{LookAtDescription{"211001:n(100001)"}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Talk02_End"},Duration{1}}
}
]],
          SpeakNpcId = 211001,
          Subtitle = "Okay...! But could you maybe say sorry to Miss Cassandra for me—?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F9608"
        },
        [12033012] = {
          Content = "敲门声",
          DialogueId = 12033012,
          GUID = "1E1F9609"
        },
        [12033101] = {
          Camera = "321.198364,-231.621094,114.386719,0.000126,2.827363,109.062408,35.000008,180.208557,false,DoNotOverride,6.0",
          ContentES = "¿Eh? ¿Quién será?",
          DialogueId = 12033101,
          GUID = "1E1FA4CC",
          NextDialogue = 12033102,
          Scripts = [[
PARA{
