        },
        [12033501] = {
          ContentES = "Buscar al azar no servirá de nada… Cassandra, ¿tienes idea de a dónde podría haber ido Savio? ¿O por qué habría salido de la ciudad?",
          DialogueId = 12033501,
          GUID = "1E1FE642",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033502,
          SpeakNpcId = 100001,
          Subtitle = "Searching blindly won't help... Cassandra, can you think of anywhere Savio might go? Why would he even leave the city?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE642"
        },
        [12033502] = {
          ContentES = "Hmm… Tal vez salió a buscar mariposas. El otro día, en clase, el maestro dijo que había algunas cerca del Lago Lamentoso. No dejaba de hacer preguntas sobre eso…",
          DialogueId = 12033502,
          GUID = "1E1FE66C",
          NextDialogue = 12033503,
          SpeakNpcId = 211012,
          Subtitle = "Umm... maybe he went to look for butterflies. A few days ago in class, the teacher said they live near Lamenting Lake. He wouldn't stop asking about it...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE66C"
        },
        [12033503] = {
          ContentES = "Está realmente obsesionado con las mariposas… ¿Es por algún cuento?",
          DialogueId = 12033503,
          GUID = "1E1FE696",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033504,
          SpeakNpcId = 100001,
          Subtitle = "Why's he so obsessed with butterflies? Is there a fairy tale behind it or something?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE696"
        },
        [12033504] = {
          ContentES = "Es por algo que pasó cuando era pequeño. Me contó la historia muchas veces… Un día, su mamá y su papá desaparecieron. Estaba asustado y lloraba mucho.",
          DialogueId = 12033504,
          GUID = "1E1FE6C0",
          NextDialogue = 12033505,
          SpeakNpcId = 211012,
          Subtitle = "It's because of something that happened when he was little. He told me the story a bunch of times... One day, his mum and dad disappeared. He was scared and cried a lot.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6C0"
        },
        [12033505] = {
          ContentES = "Y entonces aparecieron unas Hadas Mariposa. Jugaron con él, lo acompañaron… hasta que sus padres finalmente regresaron.",
          DialogueId = 12033505,
          GUID = "1E1FE6EA",
          NextDialogue = 12033506,
          SpeakNpcId = 211012,
          Subtitle = "Then the Butterfly Fairies came. They played with him, kept him company until his parents came home.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6EA"
        },
        [12033506] = {
          ContentES = "Creo… tal vez él cree que si las encuentra de nuevo, traerán de vuelta a sus padres…",
          DialogueId = 12033506,
          GUID = "1E1FE714",
          NextDialogue = 12033507,
          SpeakNpcId = 211012,
          Subtitle = "I think... maybe he believes if he finds them again, they'll bring his parents back...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE714"
        },
        [12033507] = {
          ContentES = "...",
          DialogueId = 12033507,
          GUID = "1E1FE73E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 211001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE73E"
        },
        [12033508] = {
          ContentES = "Al llegar a un lugar de interés",
          DialogueId = 12033508,
          GUID = "1E1FE768",
          Subtitle = "Arriving at a point of interest",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE768"
