          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF6AA"
        },
        [12033602] = {
          ContentES = "Parece… ¿una moneda de plata?",
          DialogueId = 12033602,
          GUID = "1E1FF6D4",
          NextDialogue = 12033603,
          SpeakNpcId = 100001,
          Subtitle = "Looks like... a silver coin?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF6D4"
        },
        [12033603] = {
          Camera = "234.363953,-50.952301,24.949219,0.000154,-4.399441,4.909956,35.000015,244.392456,false,Manual,10.0",
          ContentES = "No, solo es cartón pintado para parecer una moneda de plata… ¡Savio la hizo con sus propias manos para nuestro juego!",
          DialogueId = 12033603,
          FinalCamera = "253.116959,-20.29356,23.308594,0.000155,-4.399441,4.909863,35.000015,244.392456,false,Manual,10.0",
          GUID = "1E1FF6FE",
          NextDialogue = 12033604,
          SpeakNpcId = 211012,
          Subtitle = "No... just cardboard painted silver. This was a prop Savio made for our game.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF6FE"
        },
        [12033604] = {
          Camera = "620.08136,271.415924,29.961914,0.000183,-8.999266,-35.888649,35.000023,354.210571,false,Manual,10.0",
          ContentES = "Le importaba tanto… Nunca la habría dejado caer. Eso significa que… algo le debió haber pasado… *snif*…",
          DialogueId = 12033604,
          FinalCamera = "640.950745,256.320587,25.977539,0.000182,-8.799243,-35.888645,35.000023,354.210571,false,Manual,10.0",
          GUID = "1E1FF728",
          NextDialogue = 12033605,
          Scripts = [[
