}]],
          SpeakNpcId = 211012,
          Subtitle = "He's always careful — he'd never just leave this behind... Does this mean... something's happened to him...? *sniffles*",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211012:p(-60)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF728"
        },
        [12033605] = {
          Camera = "751.478516,230.02742,-0.833008,0.000126,1.799482,-67.086746,28.0,267.67627,false,Manual,2.8",
          ContentES = "¡Ah! ¡Recuerdo! La Detective Taciturna dijo que los bandidos que perseguía… ¡secuestraban niños!",
          DialogueId = 12033605,
          FinalCamera = "753.482544,225.280487,-0.672852,0.000128,1.799482,-67.086746,28.0,267.67627,false,Manual,2.8",
          GUID = "1E1FF752",
          NextDialogue = 12033606,
          Scripts = [[

