}
]],
          SpeakNpcId = 211001,
          Subtitle = "Ah—! I almost forgot! The Reticent Detective said the bandits we were tracking... they kidnap children!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211001:p(-60)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF752"
