PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Yes! It was a map... The Detective said it might show where the bandits are hiding — near Lamenting Lake!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF7D0"
        },
        [12033609] = {
          Camera = "855.435364,-250.186905,69.771484,0.000161,-14.201199,100.104431,28.000006,294.264496,false,Manual,22.0",
          ContentES = "¡Entonces vamos rápido!",
          DialogueId = 12033609,
