}]],
          SpeakNpcId = 211012,
          Subtitle = "Then what are we waiting for!? Let's go!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211012:p(-60)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF7FA"
        },
        [12033610] = {
          ContentES = "No. No sabemos cuántos son. Es demasiado peligroso ir todos juntos. Cassandra, ¿recuerdas el camino de regreso? Debes ir a avisar a la Oficina de Seguridad.",
          DialogueId = 12033610,
          GUID = "1E1FF824",
          NextDialogue = 12033611,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"100001:n(211012)"}},
LookAt{LookAtDescription{"211012:n(100001)"}},
PlayAnimation{ActorId{211012},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{100001},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"None"}},
}]],
          SpeakNpcId = 100001,
          Subtitle = "No — not all together. We don't know how many of them there are. It'd be too dangerous to charge in as a group. Cassandra, do you remember the way back? I need you to return to the city and alert the Security Bureau.",
          TurnTo = {
            [1] = "100001:p(50)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF824"
        },
        [12033611] = {
          ContentES = "Yo… sí, lo recuerdo. Pero—",
          DialogueId = 12033611,
          GUID = "1E1FF84E",
          NextDialogue = 12033612,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(100001)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "I remember, but...",
          TurnTo = {
            [1] = "211012:p(-100)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF84E"
        },
        [12033612] = {
          Camera = "827.256714,-86.128052,9.842773,0.000209,-5.60068,86.898766,35.000015,244.391815,false,Manual,2.8",
          ContentES = "En el camino, ya eliminé a los Filthoids. No reaparecerán de inmediato. Si sigues la misma ruta, no habrá peligro.",
          DialogueId = 12033612,
          FinalCamera = "828.428833,-64.501137,7.720703,0.000209,-5.60068,86.898766,35.000015,244.391815,false,Manual,2.8",
          GUID = "1E1FF878",
          NextDialogue = 12033613,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk03ToTalkL_Start\"},Duration{1}},",
          SpeakNpcId = 100001,
          Subtitle = "I already cleared out the Filthoids nearby on our way here. They won't be back for a while — stick to the path we took and you'll be safe.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF878"
        },
        [12033613] = {
          Camera = "850.43689,38.731472,4.530273,0.000259,-5.104651,104.108681,35.0,122.143867,false,Manual,2.8",
          ContentES = "Cassandra, solo tú puedes hacerlo. Eres la única Sola aquí. Si les informas del asunto, lo tomarán en serio.",
          DialogueId = 12033613,
          FinalCamera = "847.987793,48.463066,3.634766,0.000259,-5.104651,104.108681,35.0,122.143867,false,Manual,2.8",
          GUID = "1E1FF8A2",
          NextDialogue = 12033614,
          Scripts = [[
