LookAt{LookAtDescription{"100001:n(211012)"}},
LookAt{LookAtDescription{"211012:n(211012)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Cassandra, you're the only one who can do this. You're the only Solarian here — they won't listen unless it's coming from you.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF8A2"
        },
        [12033614] = {
          Camera = "750.329895,219.011108,0.647461,0.000261,-1.104694,-54.491871,35.000011,122.143867,false,Manual,22.0",
          ContentES = "…De acuerdo. Lo haré. ¡Espérenme, volveré con ayuda!",
          DialogueId = 12033614,
          GUID = "1E1FF8CC",
          NextDialogue = 12033615,
          Scripts = [[
