          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF920"
        },
        [12033617] = {
          ContentES = "En la guarida de los bandidos. Desde lejos, ven a Savio rodeado por seis o siete bandidos.",
          DialogueId = 12033617,
          GUID = "1E1FF94A",
          Subtitle = "At the bandit hideout — they spy six or seven bandits surrounding Savio from a distance",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF94A"
        },
        [12033701] = {
          Camera = "173.460236,214.176193,147.875977,0.000091,-9.0007,-142.292953,35.000008,267.529114,false,DoNotOverride,2.8",
          ContentES = "Ahí está…",
          DialogueId = 12033701,
          GUID = "1E200712",
          NextDialogue = 12033702,
          SpeakNpcId = 100001,
          Subtitle = "There he is...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E200712"
        },
        [12033702] = {
          Camera = "-2079.935303,-417.626953,280.476562,0.000107,-19.000505,-77.490654,35.000011,899.788879,false,DoNotOverride,2.8",
          ContentES = "No son tantos. Pero con el rehén, las cosas se complican. Hay que encontrar una forma de distraerlos…",
          DialogueId = 12033702,
          GUID = "1E20073C",
          NextDialogue = 12033703,
          SpeakNpcId = 100001,
          Subtitle = "Not too many of them. But with the boy as their hostage, we'll need a way to draw them off.",
