          Scripts = "PlayAnimation{_delay{1.5},ActorId{211037},AnimationId{\"Angry01_Start\"}}",
          SpeakNpcId = 211037,
          Subtitle = "You idiot. Those are Geniemons.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20080E"
        },
        [12033708] = {
          Camera = "-2936.262695,253.024292,-96.198242,0.000075,-4.800557,-24.382278,35.000008,267.529114,false,DoNotOverride,2.8",
          ContentES = "¿Ah, sí? Nunca había visto unos así…",
