          GUID = "1E20191E",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20191E"
        },
        [12033812] = {
          ContentES = "¿Hermana mayor… Serafina?",
          DialogueId = 12033812,
          GUID = "1E201948",
          SpeakNpcId = 211015,
          Subtitle = "...Serafina...?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E201948"
        },
        [12033813] = {
          Content = "闪回塞维欧小时候的记忆，第一视角看着飞舞的蝴蝶，背景里有菲娜模糊的身影\n回到现实",
          DialogueId = 12033813,
          GUID = "1E201972",
          VoiceName = "voice/$Locale$/story/1201/120114/1E201972"
        },
        [12033814] = {
          ContentES = "¡Venid, amigos! ¡Juntos protegeremos a todos!",
          DialogueId = 12033814,
          GUID = "1E20199C",
          SpeakNpcId = 211001,
          Subtitle = "O friends, come and protect everyone!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20199C"
        },
        [12033815] = {
