          DialogueId = 12033816,
          GUID = "1E2019F0",
          Subtitle = "Combat begins: Fina is playable; the protagonist joins as a Combat Partner.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2019F0"
        },
        [12033850] = {
          ContentES = "Fina… ¿dominas una magia tan poderosa?",
          DialogueId = 12033850,
          GUID = "1E201F84",
          NextDialogue = 12033851,
          SpeakNpcId = 100001,
          Subtitle = "Fina, I didn't know you could use such powerful magic!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E201F84"
        },
        [12033851] = {
          ContentES = "¡No soy yo… son mis amigos los que vienen a ayudarme!",
          DialogueId = 12033851,
          GUID = "1E201FAE",
          NextDialogue = 12033852,
          SpeakNpcId = 211001,
          Subtitle = "My fairy-tale friends came to help!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E201FAE"
        },
        [12033852] = {
          ContentES = "Increíble… entonces contaré contigo para cubrir mis espaldas.",
          DialogueId = 12033852,
          GUID = "1E201FD8",
          NextDialogue = 12033853,
          SpeakNpcId = 100001,
          Subtitle = "That's amazing. Well then, I'm counting on you to watch my back.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E201FD8"
        },
        [12033853] = {
          ContentES = "¡De acuerdo!",
