        [12033905] = {
          Camera = "77.939064,65.692757,77.285156,0.000161,6.997931,155.598511,25.0,86.749496,false,Manual,4.0",
          ContentES = "T-Tú… eres realmente mi hermana mayor Serafina, ¿verdad? Aunque tu cabello se haya vuelto azul… ¡te reconozco!",
          DialogueId = 12033905,
          GUID = "1E20288A",
