        [12033906] = {
          Camera = "-26.948053,81.611237,83.803711,0.000156,-0.802212,7.594927,25.0,190.125488,false,Manual,4.0",
          ContentES = "Yo…",
          DialogueId = 12033906,
          GUID = "1E2028B4",
          NextDialogue = 12033907,
          Scripts = [[
