        },
        [12034102] = {
          Camera = "986.973083,1585.42395,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
          CameraBlendCurve = "easeOutQuad",
          ContentES = "Hmm… ¿Eh? ¿Estos bandidos ya han sido neutralizados?",
          DialogueId = 12034102,
          FinalCamera = "977.238586,1591.515625,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
          GUID = "1E2048DC",
          NextDialogue = 12034103,
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          Subtitle = "Wait... these bandits are already down?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2048DC"
        },
        [12034103] = {
          Camera = "483.208221,510.672333,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "Sí. Somos {性别:Phoxcazadores|Phoxcazadoras}, contratados por la señorita Cassandra. Ya los hemos derrotado.",
          DialogueId = 12034103,
          FinalCamera = "486.036987,505.621124,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
          GUID = "1E204906",
          NextDialogue = 12034104,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},TargetPoint{"Feina_FixSimple38_nvzhuMove1"},MoveSpeed{40},Visibility{"Show"}},
PlayAnimation{ActorId{100001},AnimationId{"Explain01L_Start"},Duration{1}}

}]],
          SpeakNpcId = 100001,
          Subtitle = "Yes. We're Phoxhunters, hired by Miss Cassandra. We took them down.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120114/1E204906"
        },
        [12034104] = {
          Camera = "229.517212,445.407562,72.137695,-0.0,16.841286,-9.204861,50.0,173.055267,false,Manual,8.0",
          ContentES = "¿De verdad…?",
          DialogueId = 12034104,
          GUID = "1E204930",
          NextDialogue = 12034105,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Explain01L_End\"},Duration{1}}",
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          Subtitle = "Is that so?",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120114/1E204930"
        },
        [12034105] = {
          Camera = "-876.449036,601.317261,201.322266,0.000065,-11.157715,-19.005154,30.0,173.055267,false,DoNotOverride,8.0",
          ContentES = "¡Exacto! ¡Fui yo quien los contrató! ¡No son malas personas!",
          DialogueId = 12034105,
          FinalCamera = "-876.449036,601.317261,217.300781,0.000066,-10.35766,-19.005308,30.0,173.055267,false,DoNotOverride,8.0",
          GUID = "1E20495A",
          NextDialogue = 12034106,
          SpeakNpcId = 211012,
          Subtitle = "That's right! I hired them — they're not bad guys!",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "211012:p(-180)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E20495A"
        },
        [12034106] = {
          Camera = "-261.812439,310.25946,99.939453,0.000086,-2.357686,-2.005544,35.0,688.037964,false,Manual,4.0",
          ContentES = "…Muy bien. Nos llevaremos a estos bandidos.",
          DialogueId = 12034106,
          FinalCamera = "-261.654846,314.867767,99.939453,0.000086,-2.357686,-1.605461,35.0,688.037964,false,Manual,4.0",
          GUID = "1E204984",
          NextDialogue = 12034107,
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          Subtitle = "...Alright then. We'll take them from here.",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E204984"
        },
        [12034107] = {
          Camera = "199.814636,389.031067,112.981445,0.000071,1.842389,7.599753,50.0,198.341919,false,Manual,5.0",
          ContentES = "Hmpf… esa maldita recicladora Charon, que no paraba de venir a darnos la lata con historias de bandidos en el Lago Lamentoso… Pensábamos que estaba desvariando, pero al final tenía razón.",
          DialogueId = 12034107,
          FinalCamera = "199.727524,389.644745,112.981445,0.000072,2.04239,8.399999,55.0,198.341919,false,Manual,5.0",
          GUID = "1E2049AE",
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          Subtitle = "That filthy Charon scavenger wouldn't stop pestering us about bandits near the lake. Thought she was full of it — but turns out that lass was right...",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2049AE"
        },
        [12034108] = {
          ContentES = "Los soldados se alejan llevándose a los bandidos.\nCassandra y Savio se apartan para hablar en privado.",
          DialogueId = 12034108,
          GUID = "1E2049D8",
          Subtitle = [[
Soldiers depart with the captured bandits
Cassandra and Savio move aside for a private chat]],
          VoiceName = "voice/$Locale$/story/1201/120114/1E2049D8"
        },
        [12034201] = {
          Camera = "87.895348,214.805466,327.84668,0.000057,-19.94603,160.421906,50.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Cassandra… ¿fuiste tú quien los envió a buscarme?",
          DialogueId = 12034201,
          FinalCamera = "82.289337,199.953339,327.84668,0.000058,-19.546021,158.621765,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E20591A",
          LookAt = {
            [1] = "100001:n(211012)",
            [2] = [[

211001:n(211012)]]
          },
          NextDialogue = 12034202,
          SpeakNpcId = 211015,
          Subtitle = "Cassandra... did you send them to find me?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20591A"
        },
        [12034202] = {
          Camera = "-942.397278,-54.10989,181.074219,0.000047,-11.546441,59.81805,50.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Claro! ¿Quién más iba a hacerlo? ¿Por qué saliste de la ciudad? ¡Me diste un susto tremendo!",
          DialogueId = 12034202,
          FinalCamera = "-947.833069,-50.950378,181.074219,0.000047,-11.546441,59.81805,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E205944",
          NextDialogue = 12034203,
          SpeakNpcId = 211012,
          Subtitle = "Of course I did! Who else would've? Why'd you run off like that? You scared me half to death!",
          TalkActionId = {
            [1] = "211012:Confident_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205944"
        },
        [12034203] = {
          Camera = "-317.916473,488.004974,97.504883,0.000046,-2.946106,-178.584473,50.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Yo… pensaba que ya no querías jugar conmigo. Y si nadie quería verme… entonces pensé que ya no hacía falta volver a la escuela.",
          DialogueId = 12034203,
          FinalCamera = "-317.916473,488.004974,90.661133,0.000046,-3.146053,-178.384689,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E20596E",
          NextDialogue = 12034204,
          SpeakNpcId = 211015,
          Subtitle = "I... I thought maybe you didn't want to play with me anymore. That no one did... So maybe I shouldn't go back to school.",
          TalkActionId = {
            [1] = "211012:Confident_End",
            [2] = [[

211015:Sigh_Start]]
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20596E"
        },
        [12034204] = {
          Camera = "-896.072571,82.03035,63.115234,0.00007,-0.346345,57.812359,50.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Qué tonterías dices! ¡Somos amigos! Si vuelves a compararme con esos mocosos insoportables, de verdad me voy a enfadar — espera… ¡¿estás herido?!",
          DialogueId = 12034204,
          FinalCamera = "-890.340332,78.4217,63.115234,0.00007,-0.346345,57.811806,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E205998",
          NextDialogue = 12034205,
          Scripts = "PlayAnimation{_delay{11},ActorId{211012},AnimationId{\"Angry01_End\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Don't be ridiculous — we're friends! If you start lumping me in with those bullies, I'll get mad— Wait a sec... Are you hurt!?",
          TalkActionId = {
            [1] = "211015:Sigh_End",
            [2] = [[

211012:Angry01_Start]]
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205998"
        },
        [12034205] = {
          Camera = "-405.626709,506.263672,87.52832,0.000071,-1.545767,-172.392715,50.0,285.715515,false,Manual,8.0",
          ContentES = "No es nada, solo unos rasguños. Gracias, Cassandra.",
          DialogueId = 12034205,
          GUID = "1E2059C2",
          NextDialogue = 12034206,
          SpeakNpcId = 211015,
          Subtitle = "I'm okay. Just a few scrapes. Thank you, Cassandra.",
          TalkActionId = {
            [1] = "211015:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E2059C2"
        },
        [12034206] = {
          Camera = "151.844269,80.657501,37.138672,0.000095,1.654081,151.40625,50.0,940.830017,false,Manual,8.0",
          ContentES = "Gracias a ti estoy a salvo… y por fin he encontrado a la Hada Mariposa.",
          DialogueId = 12034206,
          FinalCamera = "149.475693,76.349304,37.138672,0.000096,1.654081,150.606277,50.0,940.830017,false,Manual,8.0",
          GUID = "1E2059EC",
          NextDialogue = 12034207,
          SpeakNpcId = 211015,
          Subtitle = "Thanks to you, I'm safe... and I finally found the Butterfly Fairy!",
          TalkActionId = {
            [1] = "211015:Explain02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2059EC"
        },
        [12034207] = {
          Camera = "-899.9151,108.874062,146.229492,0.000112,-9.546234,55.209587,50.0,552.772644,false,DoNotOverride,8.0",
          ContentES = "¡¿De verdad?! ¡Genial! ¡Tendrás que contármelo todo con detalle en la escuela!",
          DialogueId = 12034207,
          FinalCamera = "-899.9151,108.874062,133.772461,0.000113,-8.146189,54.209774,50.0,552.772644,false,DoNotOverride,8.0",
          GUID = "1E205A16",
          NextDialogue = 12034208,
          SpeakNpcId = 211012,
          Subtitle = "That's amazing! You've got to tell me everything when we're back at school.",
          TalkActionId = {
            [1] = "211015:Explain02_End",
            [2] = [[

211012:Agree]]
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205A16"
        },
        [12034208] = {
          ContentES = "¡Sí!",
          DialogueId = 12034208,
          GUID = "1E205A40",
          NextDialogue = 12034209,
          SpeakNpcId = 211015,
          Subtitle = "I will!",
          TalkActionId = {
            [1] = "211015:Agree"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E205A40"
        },
        [12034209] = {
          Camera = "-690.500427,676.570496,85.366211,0.000123,0.853248,-66.382408,40.0,552.772644,false,DoNotOverride,8.0",
          ContentES = "Fina, {性别:Señor|Señorita} {nickname}, ¡gracias por salvar a mi amigo!",
          DialogueId = 12034209,
          FinalCamera = "-706.813965,669.448181,85.366211,0.000124,1.053249,-65.382294,40.0,552.772644,false,DoNotOverride,8.0",
