          FinalCamera = "-38.820705,417.20697,108.579102,0.000143,2.494098,-93.341576,50.000008,327.060272,false,Manual,8.0",
          GUID = "1E207A3E",
          NextDialogue = 12034404,
          SpeakNpcId = 100001,
