          GUID = "1E207A68",
          Scripts = "PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{\"AgreeHead\"}}",
          SpeakNpcId = 211001,
          Subtitle = "...Okay! I'll remember that!",
          TalkActionId = {
