          SpeakNpcId = 211001,
          Subtitle = "Savio? Why did you come alone? Where's Cassandra?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E208A7C"
        },
        [12034503] = {
          ContentES = "Cassandra salió a hacer unas compras. Así que pensé en traerte mi regalo de agradecimiento antes de tiempo.",
