          SpeakNpcId = 211001,
          Subtitle = "Mr White Bird...!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E209ABA"
        },
        [12034602] = {
          Camera = "211.434235,245.470703,131.753906,0.000086,-6.587157,-77.601845,35.000008,263.858795,false,DoNotOverride,2.8",
          ContentES = "Sabía que era tu juguete favorito. Así que, cuando te fuiste, lo guardé bien a salvo en mi armario, esperando tu regreso… Ahora que tienes una casa nueva, debería estar contigo.",
          DialogueId = 12034602,
          GUID = "1E209AE4",
          NextDialogue = 12034603,
          SpeakNpcId = 211015,
          Subtitle = "I remembered how much you loved him. After you left, I kept him safe in my closet, waiting for you to come back. Now that you've got a new home, I think he should be with you.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E209AE4"
        },
        [12034603] = {
          Camera = "194.921234,126.091797,122.953125,0.000114,-5.587006,11.20279,35.000011,63.917503,false,DoNotOverride,2.8",
          ContentES = "Oh… ¡gracias, Savio!",
          DialogueId = 12034603,
          GUID = "1E209B0E",
          NextDialogue = 12034604,
          Scripts = [[
PARA{
PlayFacial{_delay{0.1},ActorId{211001},FacialId{"Shock01"}},
PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{"Explain02_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Aww... Thank you, Savio!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E209B0E"
        },
        [12034604] = {
          ContentES = "Hermana mayor Fina… recuerdo que, en nuestra antigua casa, no parecías muy feliz. ¿Y aquí? ¿En tu nueva casa… eres feliz?",
          DialogueId = 12034604,
          GUID = "1E209B38",
          NextDialogue = 12034605,
          Scripts = "PlayAnimation{_delay{4.5},ActorId{211001},AnimationId{\"Explain02_End\"}}",
          SpeakNpcId = 211015,
          Subtitle = "Fina... I remember now — you never really looked happy at our old place. Are you happy here?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E209B38"
        },
        [12034605] = {
          ContentES = "Sí. Me gusta mucho esta casa.",
          DialogueId = 12034605,
          GUID = "1E209B62",
          NextDialogue = 12034606,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3},TargetPosition{"246.114395,70.744141,133.878906,0.000121,-6.187345,78.602493,35.000011,66.890312,false,DoNotOverride,3.5"},duration{0}},
PlayFacial{_delay{0.1},ActorId{211001},FacialId{"Sad01"}},
PlayFacial{_delay{3.1},ActorId{211001},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I am. I really like my new home.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E209B62"
        },
        [12034606] = {
          Camera = "237.078812,200.228516,122.355469,0.000136,-2.587098,-83.194069,35.000011,72.722557,false,DoNotOverride,3.5",
          ContentES = "¡Qué bien! ¿Puedo venir a verte de vez en cuando? ¿Y volver a jugar contigo?",
          DialogueId = 12034606,
          FinalCamera = "237.078812,200.228516,122.355469,0.000136,-2.587098,-83.194069,35.000011,204.719406,false,DoNotOverride,3.5",
          GUID = "1E209B8C",
          NextDialogue = 12034607,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"Explain02_Start\"}}",
          SpeakNpcId = 211015,
          Subtitle = "That's great! Can I come visit you sometimes? Maybe we could play together again?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E209B8C"
        },
        [12034607] = {
          Camera = "161.765778,-79.779297,98.703125,0.00015,6.012875,54.207573,35.000015,262.416931,false,DoNotOverride,3.5",
          ContentES = "¡Claro que sí! Somos amigos, ¿no?",
          DialogueId = 12034607,
          FinalCamera = "143.822983,-105.402344,95.390625,0.00015,6.012875,55.007545,35.000015,262.416931,false,DoNotOverride,3.5",
          GUID = "1E209BB6",
          NextDialogue = 12034608,
          Scripts = [[
