          SpeakNpcId = 211001,
          Subtitle = "Of course you can — we're friends, aren't we?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E209BB6"
        },
        [12034608] = {
