        [12034705] = {
          Camera = "-133.212585,185.379044,127.350098,0.000116,-4.629789,-85.284157,35.0,173.365967,false,Manual,2.799999",
          ContentES = "{性别:Señor|Señorita} Unicornio... ¿recuerdas la historia del Pequeño Ruiseñor?",
          DialogueId = 12034705,
          FinalCamera = "-131.751953,167.669998,125.972656,0.000117,-4.42978,-85.28421,35.0,152.132278,false,Manual,2.799999",
