          SpeakNpcId = 211001,
          Subtitle = "\"The little nightingale left her nest and flew into the unknown... On her journey, she met the clever Reticent Detective, cheerful Magic Roasted Potatoes, and many, many new friends...\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CBF2"
        },
        [12034902] = {
          Camera = "65.885368,364.457031,142.957031,0.000107,-13.200897,166.389648,35.0,111.809486,false,DoNotOverride,12.0",
          ContentES = "“El Ruiseñor ya no temía a los malos hechiceros, ni a las bestias salvajes que lo perseguían.”",
          DialogueId = 12034902,
          GUID = "1E20CC1C",
          NextDialogue = 12034903,
          Scripts = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}",
          SpeakNpcId = 211001,
          Subtitle = "\"She was no longer afraid of bad sorcerers, or the beasts that once chased her...\"",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CC1C"
        },
        [12034903] = {
          Camera = "-31.965088,301.212891,134.277344,0.000101,-7.000998,109.790298,35.0,90.981918,false,DoNotOverride,12.0",
          ContentES = "“Porque ahora sabía que, aunque el mundo exterior pudiera ser oscuro y aterrador… mientras tomara la mano de sus amigos, siempre encontraría el camino hacia un sueño de mil colores.”",
          DialogueId = 12034903,
          FinalCamera = "-35.076675,309.947266,133.269531,0.000102,-5.800961,109.79023,35.0,70.654915,false,DoNotOverride,12.0",
          GUID = "1E20CC46",
