          VoiceName = "voice/$Locale$/story/2001/200005/3211B5AC"
        },
        [20000511] = {
          ContentES = "En verdad, al verlos pasar en este instante, mis viejos instintos se despertaron...",
          DialogueId = 20000511,
          Duration = 2,
          FacialId = {
