        },
        [20000512] = {
          Camera = "-448.745361,204.227051,210.797119,0.000268,-16.801117,-22.812357,80.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí... Eso es. ¡El olor de un <H>arma legendaria</>! Dime, {性别:chico|chica}, ¿esconderías un arma extraordinaria?",
