          ContentES = "(Ella observa la espada con gran atención, como si tratara de descifrar los secretos en el patrón del acero.)",
          DialogueId = 20000515,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 3,
          FinalCamera = "-1148.861572,-2949.662109,210.885498,0.000319,-1.000759,64.376427,27.995377,100000.0,false,DoNotOverride,2.8",
