        [20000602] = {
          Camera = "-160.725159,-13.358643,119.220985,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          ContentES = "Por cierto, me encontré en el camino con otras personas que se parecen a ti y a Nieve. ¿También son <H>Lunarianos</>?",
          DialogueId = 20000602,
          Duration = 2,
          ExStoryInfo = "Player",
