          GUID = "3211C614",
          NextDialogue = 20000611,
          Scripts = "CameraMoveTo{_delay{3.1},TargetPosition{\"-29.559052,-9.855469,93.745667,0.000395,-1.597868,52.748596,30.0,80.996147,false,Manual,3.33564\"},duration{0}}",
          SpeakNpcId = 200002,
          Subtitle = "As you can see, I have demonic appendages on my head. No other Lunos have these!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C614"
        },
        [20000611] = {
          Camera = "121.44281,0.996094,87.475624,0.000284,-1.203274,162.815094,40.0,255.986099,false,Manual,4.671523",
          ContentES = "Es cierto... En toda mi vida, nunca he visto a un Luno con cuernos. Tu apariencia se parece más a la de los <H>Charons</>.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000611,
          Duration = 3,
          FinalCamera = "120.606506,-1.710693,87.475624,0.000284,-1.203274,162.815094,40.0,255.986099,false,Manual,4.671523",
          GUID = "3211C63E",
          NextDialogue = 20000612,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Indeed. In all my years, I've never seen a Luno with horns like those. You look just like those human Charons.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C63E"
        },
        [20000612] = {
          Camera = "-400.428558,-346.687256,65.11969,0.000289,0.592908,43.232693,30.0,150.0,false,Disable,2.8",
          ContentES = "¡Por eso Nieve es Luno, la Reina Demonio, única en su especie! ¡Puede que incluso haya nacido para guiar a mi pueblo y conquistar el mundo!",
          DialogueId = 20000612,
          Duration = 3,
          FinalCamera = "-400.428558,-346.687256,74.75869,0.000289,0.592908,43.232693,30.0,150.0,false,Disable,2.8",
          GUID = "3211C668",
          NextDialogue = 20000613,
          SpeakNpcId = 200002,
          Subtitle = "Sooooo, I'm Luno the Demon King, different and unique! Perhaps I was meant to lead the Lunos and dominate the world!",
          TalkActionId = {
            [1] = "200002:Bai_Talk03Quick"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C668"
        },
        [20000613] = {
          Camera = "73.592575,17.665527,68.467941,0.000294,7.195904,171.812531,50.0,197.801682,false,Manual,3.959335",
          ContentES = "Oh... qué gran ambición.",
