        [20000812] = {
          Camera = "115.332031,-16.99292,124.335938,0.000007,-2.000057,168.607559,40.0,215.523529,false,Manual,4.566695",
          ContentES = "Me encantaría, pero el Sr. Henrik me ha prohibido salir... ¡Ah! Pero ya que estás aquí...",
          DialogueId = 20000812,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211E738",
          NextDialogue = 20000814,
          SpeakNpcId = 200027,
          Subtitle = "I'd love to, but Mr Henrik told me to stay inside, so... Oh! Now that you're here...",
          TalkActionId = {
