        [20000815] = {
          Camera = "102.873047,-21.080566,123.726562,0.000007,-2.000057,160.8069,30.0,215.523529,false,Manual,3.285402",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "La planta en maceta aquí... ¿Puedes describirme cómo están floreciendo las flores?",
          DialogueId = 20000815,
          Duration = 3,
          FinalCamera = "111.162109,-2.550049,123.972656,0.000007,-2.000057,179.005371,30.0,215.523529,false,Manual,3.285402",
          GUID = "3211E7B6",
          LookAt = {
