        },
        [20002801] = {
          ContentES = "Tranquilo, ya sabemos hacia dónde fue Psyche. Solo tenemos que seguir su rastro.",
          DialogueId = 20002801,
          Duration = 3,
          GUID = "32132D8A",
          NextDialogue = 20002802,
          SpeakNpcId = 200021,
          Subtitle = "It's okay, we already know where Psyche has gone. All we have to do is follow her trail.",
          VoiceName = "voice/$Locale$/story/2001/200028/32132D8A"
        },
        [20002802] = {
          ContentES = "¡Exacto! ¡Mientras la encontremos, habrá una manera de salvarla!",
