CameraMoveTo{_delay{4.1},TargetPosition{"-183.685608,-544.995117,154.855408,0.000067,-7.500005,105.000092,35.0,481.79422,false,Manual,2.023338"},duration{2.5}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "No time to breathe! Listen, someone spotted a GIGANTIC pig outside Icelake! And it's taller than you, with a head the size of a van. And if it stomps its hoof — Bam! The city walls will come down!",
          ToFinalCameraBlendTime = 3,
