          CameraBlendCurve = "easeInOutQuad",
          Content = "当然不止这点，我可是见过大风大浪的魔王大人。",
          DialogueId = 20004806,
          FinalCamera = "-660.245789,32.00293,112.909363,0.000096,-2.999962,-41.401596,25.0,824.858765,false,Manual,1.2",
          GUID = "3214767C",
          NextDialogue = 20004807,
          Scripts = [[
