PlayFacial{_delay{3.6},ActorId{200002},FacialId{"Beg"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Anyway, I'm really curious! Come on, let's go check it out! You weren't doing anything important, right?",
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200048/321476A6"
        },
        [20004901] = {
          Content = "怎么怎么，现在有空了吗？和我一起出城去看看传闻中的巨猪的真实面目！",
          DialogueId = 20004901,
          GUID = "32148612",
