          VoiceName = "voice/$Locale$/story/2001/200049/32148612"
        },
        [20005001] = {
          Camera = "1059.539062,-1035.320312,97.993164,0.000246,4.999999,145.950104,15.0,100.0,false,DoNotOverride,1.2",
          Content = "到了到了，“泪湖南岸，大坡边上”，我听到的传闻里说那只巨大的猪就在这附近出没。",
          DialogueId = 20005001,
          FinalCamera = "952.429688,-962.9375,109.304688,0.000246,4.999999,145.950104,15.0,100.0,false,DoNotOverride,1.2",
