          SpeakNpcId = 200002,
          Subtitle = "Wait, wait! Look over there! See those two? They've been standing there. Maybe they're waiting for the giant pig too! Let's go ask them!",
          TalkActionId = {
            [1] = "700262:Confident_Start"
          },
