          TurnTo = {
            [1] = "700262:p(180)"
          },
          VoiceName = "voice/$Locale$/story/2001/200052/3214B870"
        },
        [20005209] = {
          Content = "只见这两个人正对的方向出现了几只小动物，摇头晃脑，走来走去。",
          DialogueId = 20005209,
          GUID = "3214B89A",
          Subtitle = "(A few small creatures wobble into view, their tiny heads bobbing as they sniff around.)"
        },
        [20005210] = {
          Content = "而在领头人的一声令下之后，一道埋在雪地中的陷阱出现，把这些小动物尽数困住。",
          DialogueId = 20005210,
          GUID = "3214B8C4",
          NextDialogue = 20005211,
          Subtitle = "(At the duo's leader's command, with a yank of the rope, a hidden trap springs up from the snow — SNAP! — catching them all in one swift motion.)",
          VoiceName = "voice/$Locale$/story/2001/200052/3214B8C4"
        },
