MoveTo{_click{false},ActorId{100001},TargetPoint{"P200054Nvzhu1"},MoveSpeed{60},Visibility{"Show"}},
CameraMoveTo{_delay{2},TargetPosition{"-61.707031,-103.257812,77.106445,0.000102,2.99999,-133.600082,25.0,100000.0,false,Disable,2.8"},duration{0}},
PlayAnimation{_delay{2},ActorId{200002},AnimationId{"SpecialLook01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Oof, they ran so fast and disappeared in a flash! Should we chase them?",
          ToFinalCameraBlendTime = 1.9,
          VoiceName = "voice/$Locale$/story/2001/200054/3214D81A"
        },
        [20005402] = {
          Camera = "-61.707031,-103.257812,77.106445,0.000102,2.99999,-133.600082,25.0,100000.0,false,Disable,2.8",
          Content = "他们跑得轻车熟路，对附近很熟悉，应该是追不上了。并且，可别忘了，我们来这里一开始可是为了找这位。",
          DialogueId = 20005402,
          GUID = "3214D844",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 20005403,
          Scripts = [[
PARA{
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{4},ActorId{100001},AnimationId{"Talk02_End"},Duration{1}},
LookAt{_delay{5.5},LookAtDescription{"100001:n(200086)"}},
TurnTo{_delay{1.5},TurnToDescription{"200002:p(170)"}},
CameraMoveTo{_delay{5},TargetPosition{"-421.136719,-279.882812,106.238281,0.000129,14.999996,-11.802038,35.0,103.616989,false,Manual,6.0"},duration{0}},
CameraMoveTo{_delay{5.1},TargetPosition{"-420.335938,-276.035156,102.800781,0.000129,16.499994,-11.802037,35.0,358.017792,false,Manual,4.0"},duration{1.5}},
}]],
          SpeakNpcId = 100001,
          Subtitle = "They bolted like they knew every shortcut in this place. There's no way we're catching up. Besides, let's not forget why we're here.",
          TalkActionId = {
            [1] = "100001:DisagreeHead",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D844"
        },
        [20005403] = {
          Camera = "-109.613281,47.609375,431.320312,0.000135,0.0,-24.999014,15.0,358.017792,false,Manual,4.0",
          Content = "这就是你说的个子比我还高，脑袋比货车还大的巨猪？并没有那么大嘛，你被人骗啦。",
          DialogueId = 20005403,
          FinalCamera = "-18.707031,5.234375,431.320312,0.000135,0.0,-24.998245,15.0,358.017792,false,Manual,4.0",
          GUID = "3214D86E",
          LookAt = {
            [1] = "100001:n(200086)"
          },
          NextDialogue = 20005404,
          SpeakNpcId = 100001,
          Subtitle = "So... this is the giant pig that's \"taller than me\" and has \"a head the size of a van\"? You were taken in by exaggerated words, Snow.",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200002:p(120)"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D86E"
        },
        [20005404] = {
          Camera = "14.03125,-207.300781,100.790039,0.000013,-4.999999,-169.397446,25.000002,151.720291,false,Manual,4.0",
          Content = "唔……就……就算是它没我一开始说得那么大，这个大小，也很不一般了！并且你还记得吧，它刚刚还说话了，这也很值得调查！",
          DialogueId = 20005404,
          GUID = "3214D898",
          NextDialogue = 20005405,
          Scripts = "PlayFacial{_delay{1},ActorId{200002},FacialId{\"Guilty\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Well... okay, maybe it's not exactly as big as I said, but it's still pretty big! And don't forget — it TALKS! That's got to be worth looking into!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D898"
        },
        [20005405] = {
          Camera = "580.927734,-268.628906,505.952148,0.000135,0.0,-30.00001,35.0,118.427582,false,Manual,4.0",
          Content = "哼哼……",
          DialogueId = 20005405,
          GUID = "3214D8C2",
          NextDialogue = 20005406,
          Scripts = "PlayFacial{_delay{1},ActorId{200002},FacialId{\"None\"}}",
          SpeakNpcId = 200076,
          Subtitle = "Oink, oink...",
          VoiceName = "voice/$Locale$/story/2001/200054/3214D8C2"
        },
        [20005406] = {
          Camera = "-180.726562,-325.203125,184.911133,0.000013,-24.999987,177.401825,25.000002,151.701447,false,Manual,1.2",
          Content = "我怎么感觉它并不会说话的样子……",
          DialogueId = 20005406,
          GUID = "3214D8EC",
          NextDialogue = 20005407,
          Scripts = [[
PARA{
SetLocation{ActorId{200074},TargetPoint{"P200054Songlu2"},Visibility{"Show"}},
PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Yeah, except it doesn't seem like it actually talks...",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D8EC"
        },
        [20005407] = {
          Camera = "47.464844,349.339844,141.420898,0.000069,-6.0,-113.994278,45.0,633.380676,false,Manual,1.2",
          Content = "刚刚那是我在叫你们啦。",
          DialogueId = 20005407,
          GUID = "3214D916",
          LookAt = {
            [1] = "100001:n(200074)",
            [2] = "200002:n(200074)"
          },
          NextDialogue = 20005408,
          Scripts = [[
PARA{
MoveTo{ActorId{200074},TargetPoint{"P200054Songlu1"},MoveSpeed{30},Visibility{"Show"}},
TurnTo{_delay{1.5},TurnToDescription{"200002:p(90)"}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Think_End"},Duration{1}},
CameraMoveTo{_delay{2},TargetPosition{"47.464844,349.339844,137.703125,0.000065,-6.0,-113.994667,45.0,173.701065,false,Manual,3.7059"},duration{2}}
}]],
          SpeakNpcId = 200074,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "That was me!",
          VoiceName = "voice/$Locale$/story/2001/200054/3214D916"
        },
        [20005408] = {
          Camera = "-472.675781,-861.3125,125.09082,-3.000003,-4.399693,67.000412,50.0,1228.478149,false,DoNotOverride,1.847697",
          Content = "你们好，我是松露，从很远很远的地方过来，这是我的好朋友和可靠的伙伴榛子，谢谢你们一起救下了魔灵，赶跑了那些魔灵猎人！",
          DialogueId = 20005408,
          FinalCamera = "-458.234375,-820.003906,125.068359,-3.000002,-4.399693,67.001587,50.0,1228.478149,false,DoNotOverride,1.847697",
          GUID = "3214D940",
          NextDialogue = 20005409,
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"-138.240234,216.488281,55.927734,-3.000001,21.599953,-21.991064,30.0,1228.478149,false,DoNotOverride,1.847697"},duration{0}},
LookAt{_delay{5.5},LookAtDescription{"200074:n(200086)"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "Hello, I'm Truffle. I came from really far away. And this big sweetheart here is Filbert — my best friend and most trusted partner. Thank you for helping us save the Geniemons and drive away those Geniemon hunters!",
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100001:p(40)"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D940"
        },
        [20005409] = {
          Camera = "54.744141,331.777344,101.875977,0.00008,-2.599884,-115.999306,50.0,544.522034,false,Manual,3.944573",
          Content = "魔灵……猎人？",
          DialogueId = 20005409,
          GUID = "3214D96A",
          LookAt = {
            [1] = "200074:n(200002)"
          },
          NextDialogue = 20005410,
          SpeakNpcId = 200002,
          Subtitle = "Geniemon hunters...?",
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D96A"
        },
        [20005410] = {
          Camera = "-147.755859,-456.667969,107.429688,0.000102,-2.99999,82.205582,75.0,568.453857,false,Manual,8.0",
          Content = "是的，就是刚刚那几个家伙，他们自称魔灵猎人，听起来很帅气的名字，但是却一直在干坏事，把附近的魔灵都抓光了。",
          DialogueId = 20005410,
          GUID = "3214D994",
          Scripts = [[
PARA{
PlayFacial{_delay{0},ActorId{200074},FacialId{"Smile01"}},
PlayAnimation{_delay{3},ActorId{200074},AnimationId{"Explain01_End"},Duration{1}},
PlayFacial{_delay{3.5},ActorId{200074},FacialId{"Unhappy01"}},
PlayAnimation{_delay{3.5},ActorId{200074},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{200074},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "Yep, those guys back there — they go by the name \"Geniemon Hunters,\" which sounds not cool at all, because they've been running around catching every Geniemon they can find.",
          TalkActionId = {
            [1] = "200074:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D994"
        },
        [20005411] = {
          Camera = "315.054688,334.335938,83.208008,0.0,0.0,90.402756,20.0,568.453857,false,Manual,8.0",
          Content = "你们知道魔灵吧，就是它们——虽然看起来样子各不相同，但其实都是魔灵哦，是同一种类。",
          DialogueId = 20005411,
          GUID = "3214D9BE",
          NextOptions = {
            [1] = 200054111,
            [2] = 200054112,
            [3] = 200054113
          },
          SpeakNpcId = 200074,
          Subtitle = "Do you know about Geniemons? They're the ones — Though coming in all sorts of different species, they're all actually Geniemons.",
          TalkActionId = {
            [1] = "200074:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D9BE"
        },
        [20005412] = {
          Camera = "-391.167969,-541.515625,145.899414,0.000118,-5.000033,67.00695,75.000015,933.852966,false,Manual,6.0",
          Content = "是的是的，{性别：大哥哥|大姐姐}好厉害，一下子就明白了！",
          DialogueId = 20005412,
          FacialId = {
            [1] = "200074:Smile01"
          },
          GUID = "3214D9E8",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          SpeakNpcId = 200074,
          Subtitle = "Exactly! You figured that out so fast! You must be really smart!",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Agree"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214D9E8"
        },
        [20005413] = {
          Camera = "-391.167969,-541.515625,145.899414,0.000118,-5.000033,67.00695,75.000015,933.852966,false,Manual,6.0",
          Content = "差不多哦，{性别：大哥哥|大姐姐}是不是很会打架呀，一下子就想到用武器来打比方。",
          DialogueId = 20005413,
          FacialId = {
            [1] = "200074:Smile01"
          },
          GUID = "3214DA12",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          SpeakNpcId = 200074,
          Subtitle = "Yeah, kind of like that. You must be really good at fighting to think of a weapon analogy first.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Agree"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DA12"
        },
        [20005414] = {
          Camera = "-391.167969,-541.515625,145.899414,0.000118,-5.000033,67.00695,75.000015,933.852966,false,Manual,6.0",
          Content = "我想……这么说好像稍微不太对哦……但也说不出哪里不对。",
          DialogueId = 20005414,
          FacialId = {
            [1] = "200074:Shock01"
          },
          GUID = "3214DA3C",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          SpeakNpcId = 200074,
          Subtitle = "Uhhh... I think I get what you mean, but something about it feels off...",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Disagree"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DA3C"
        },
        [20005415] = {
          Camera = "80.589844,-155.308594,94.0,0.000131,0.0,102.199539,75.000015,401.161041,false,Manual,8.0",
          Content = "我是在书上看到，它们会利用月石的力量，为了适应不同环境，变成不同的样子。一般人以为这是魔法，害怕它们，就管他们叫做魔灵。",
          DialogueId = 20005415,
          FacialId = {
            [1] = "200074:Smile02"
          },
          GUID = "3214DA66",
          LookAt = {
            [1] = "200074:n(200074)"
          },
          NextDialogue = 20005416,
          SpeakNpcId = 200074,
          Subtitle = "Anyway, I read about it in a book that Geniemons tap into the power of Phoxene and become various forms to adapt to different environments.",
          TalkActionId = {
            [1] = "200074:Talk02_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DA66"
        },
        [20005416] = {
          Camera = "-645.410156,-1090.890625,111.710938,-3.000002,-0.99994,63.507641,119.393356,1504.755737,false,Manual,4.0",
          Content = "比如说，如果太靠近火焰，它们就会变成暖烘烘的“打火鸡”。如果在黑暗里待太久，它就会为了把自己藏起来，变成黑黢黢的“紫纱黑云”。",
          DialogueId = 20005416,
          GUID = "3214DA90",
          NextDialogue = 20005417,
          SpeakNpcId = 200074,
          Subtitle = "Like, if they hang around fire too close, they turn into toasty, fluffy \"Zippyro\"; while staying in the dark long enough, they go all shadowy and become \"Equinex\" to blend in. Most people don't understand how it works, so they think it's evil magic and get scared of them.",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DA90"
        },
        [20005417] = {
          Camera = "354.083984,589.65625,83.839844,0.0,-0.199981,-128.49614,75.0,989.938049,false,Manual,2.0",
          Content = "但正因为它们能使用月石的力量，所以好像就被一群人盯上了，似乎是打定主意，捕捉魔灵，但，我也不知道他们要干什么……",
          DialogueId = 20005417,
          GUID = "3214DABA",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20005418,
          SpeakNpcId = 200074,
          Subtitle = "But because they can use the power of Phoxene, they've attracted the attention of a group intent on capturing them. I don't know what they're up to, but I know it's nothing good...",
          VoiceName = "voice/$Locale$/story/2001/200054/3214DABA"
        },
        [20005418] = {
          Camera = "-113.519531,44.703125,93.811523,0.0,0.0,59.999958,35.0,175.921082,false,Manual,4.0",
          Content = "所以这几天我就一直守在附近，想让他们吃一点苦头。",
          DialogueId = 20005418,
          GUID = "3214DAE4",
          NextDialogue = 20005419,
          Scripts = [[
PARA{
PlayFacial{_delay{1},ActorId{200074},FacialId{"Satisfy01"}},
PlayFacial{_delay{3},ActorId{200074},FacialId{"Unhappy01"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "So I've been hanging around for the past few days, waiting to make them regret their actions.",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DAE4"
        },
        [20005419] = {
          Camera = "-87.744141,-68.613281,88.349609,0.00001,0.0,-107.199997,35.0,144.68222,false,Manual,3.0",
          Content = "明白了，他们追捕魔灵，你追捕他们，所以你就是魔灵猎人猎人！",
          DialogueId = 20005419,
          GUID = "3214DB0E",
          Scripts = [[
PARA{
PlayFacial{_delay{1},ActorId{200002},FacialId{"Smile01"}},
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"SpecialHappy_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Ohhh, I get it! They hunt Geniemons, and you hunt them! That makes you a \"Geniemon Hunter Hunter\"!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DB0E"
        },
        [20005420] = {
          Camera = "357.566406,-1286.941406,396.457031,-0.0,-12.999988,115.193344,30.0,144.68222,false,DoNotOverride,3.0",
          Content = "魔灵猎人猎人……有点绕口呢，不过倒也没错，这些魔灵猎人现在一看到我就跑，嘿嘿。",
          DialogueId = 20005420,
          FinalCamera = "342.291016,-1254.515625,388.173828,-0.0,-12.999988,115.193344,30.0,144.68222,false,DoNotOverride,3.0",
          GUID = "3214DB38",
          SpeakNpcId = 200074,
          Subtitle = "Geniemon Hunter Hunter...? That's a bit of a mouthful... but I guess it fits! Hehe, those guys run off the second they see me!",
          TalkActionId = {
            [1] = "200002:SpecialHappy_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200054/3214DB38"
        },
        [20005421] = {
          Camera = "506.339844,527.21875,80.919922,0.000151,-1.799714,-157.500092,38.000011,604.231934,false,Manual,3.0",
          Content = "接下来你们要是再遇到这些坏家伙，记得通知我哦，你们也都快回家吧，可不要再被那些魔灵猎人抓到了哦。",
          DialogueId = 20005421,
          FinalCamera = "506.339844,527.21875,80.919922,0.000151,-1.799714,-157.500092,38.000011,200.0,false,Manual,3.0",
          GUID = "3214DB62",
          NextDialogue = 20005422,
          Scripts = "PlayFacial{_delay{1},ActorId{200074},FacialId{\"Smile01\"}}",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let me know if you run into those bad guys again. And little ones, now go home and stay safe. Don't let those mean hunters catch you again.",
          TalkActionId = {
            [1] = "200074:Confident_End"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "200074:p(160)"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DB62"
        },
        [20005422] = {
          Camera = "524.273438,916.308594,79.697266,0.0,0.0,-121.202858,45.0,776.260559,false,Manual,1.2",
          Content = "咦？这只魔灵在这里一动不动的，难道是受伤了？唔……我总是在野外跑来跑去，也没法好好照顾它……{性别：大哥哥|大姐姐}，能拜托你吗？",
          DialogueId = 20005422,
          FinalCamera = "535.150391,910.476562,79.697266,0.0,0.0,-118.202629,45.000011,325.557251,false,Manual,1.5",
          GUID = "3214DB8C",
          NextDialogue = 20005423,
          SpeakNpcId = 200074,
          Subtitle = "Hmm? Why's this one still sitting here? Is it injured? Hmm... I'm always out in the wild, and I'm afraid I won't be able to take good care of it... {性别:Sir|Miss}, could you help me out?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200054/3214DB8C"
        },
        [20005423] = {
          Camera = "-44.972656,-76.457031,81.133789,2.000004,2.99999,-132.004791,35.000008,161.618286,false,Manual,4.88291",
          Content = "来，给你这个，妙罐罐！所有魔灵都喜欢的东西，只要一罐，唔，运气不好的话要许多罐，总之，有它，魔灵就会跟着你走啦。",
          DialogueId = 20005423,
          GUID = "3214DBB6",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          Scripts = "PlayAnimation{_delay{1},ActorId{200002},AnimationId{\"SpecialHappy_Start\"},Duration{1}}",
          SpeakNpcId = 200074,
          Subtitle = "Here, take the Yum Treat! Geniemons love it. If you're lucky, open one and they'll follow you right away! If not, just give them a few more.",
          VoiceName = "voice/$Locale$/story/2001/200054/3214DBB6"
        },
        [20005424] = {
          Content = "抓获魔灵的图文引导，抓到魔灵后继续对话",
          DialogueId = 20005424,
          GUID = "3214DBE0",
          SpeakNpcId = 100001,
          Subtitle = "Illustrated tutorial for capturing a Geniemon. Dialog continues after successfully capturing one.",
          VoiceName = "voice/$Locale$/story/2001/200054/3214DBE0"
        },
        [20005425] = {
          Camera = "215.005859,-152.28125,81.717773,-3.000002,2.99999,129.999985,12.0,100.0,false,Manual,1.2",
          Content = "哒哒……？",
          DialogueId = 20005425,
          GUID = "3214DC0A",
          LookAt = {
            [1] = "100001:p(P20005425)",
            [2] = "200002:p(P20005425)",
            [3] = "200074:p(P20005425)"
          },
          NextDialogue = 20005426,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/vo_death\"},PlayAs2D{true}}",
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Da da...?"
        },
        [20005426] = {
          Camera = "164.03125,-96.539062,96.114258,0.0,-4.999971,102.000153,25.0,262.308319,false,Manual,1.2",
          Content = "没错，就是这样，{性别：大哥哥|大姐姐}真厉害！好像这只小家伙也很喜欢你哦，你看，立刻就精神了好多！",
          DialogueId = 20005426,
          GUID = "3214DC34",
          NextDialogue = 20005427,
          SpeakNpcId = 200074,
          Subtitle = "Yes, that's how it works! You're amazing, {性别:Sir|Miss}! Look at that — the little guy perked right up! I think it really likes you!",
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DC34"
        },
        [20005427] = {
          Camera = "71.892578,97.613281,114.50293,0.000002,0.0,-97.799088,20.0,136.313141,false,Manual,1.2",
          Content = "哒哒！哒哒哒！",
          DialogueId = 20005427,
          GUID = "3214DC35",
          NextDialogue = 20005428,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/vo_happy\"},PlayAs2D{true}}",
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Da da! Da da da!",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Explain02_End"
          }
        },
        [20005428] = {
          Content = "你在吵闹什么呀，小东西？",
          DialogueId = 20005428,
          GUID = "3214DC6E",
          NextDialogue = 20005429,
          Scripts = [[
PARA{
PlayFacial{_delay{1},ActorId{200002},FacialId{"Smile02"}},
PlayFacial{_delay{1},ActorId{100001},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "What is it, chirpy?",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DC6E"
        },
        [20005429] = {
          Camera = "191.291016,-210.316406,94.194336,-5.000004,0.0,116.999962,20.0,174.74379,false,Manual,1.4",
          Content = "它在和{nickname}说话呢。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20005429,
          GUID = "3214DC7E",
          NextDialogue = 20005430,
          SpeakNpcId = 200074,
          Subtitle = "Uh, it's talking to {性别:him|her}.",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End",
            [2] = "100001:Think_End",
            [3] = "200074:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DC7E"
        },
        [20005430] = {
          Camera = "326.640625,181.09375,97.236328,-5.000004,-1.599883,-150.400177,30.0,310.625153,false,Manual,1.2",
          Content = "这只魔灵说，它莫名觉得你身上有种亲切的感觉，它想和你一起走！你来保护它，它也能在关键时刻派上用场！",
          DialogueId = 20005430,
          GUID = "3214DC8E",
          NextDialogue = 20005431,
          SpeakNpcId = 200074,
          Subtitle = "This little one says you feel familiar, like someone it can trust, and it wants to go with you! You take care of it, and it could come through for you in a pinch!",
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start",
            [2] = "200074:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DC8E"
        },
        [20005431] = {
          Camera = "150.748047,-72.34375,114.495117,-0.0,-2.19986,143.799622,35.0,121.204643,false,Manual,3.0",
          Content = "哒哒哒哒！",
          DialogueId = 20005431,
          GUID = "3214DC8F",
          NextOptions = {
            [1] = 200054311,
            [2] = 200054312
          },
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/vo_hello\"},PlayAs2D{true}}",
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Da da da da!"
        },
        [20005432] = {
          Camera = "150.748047,-72.34375,114.495117,-0.0,-2.19986,143.799622,35.0,121.204643,false,Manual,3.0",
          Content = "哒哒——！",
          DialogueId = 20005432,
          GUID = "3214DC90",
          NextDialogue = 20005434,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/vo_happy\"},PlayAs2D{true}}",
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Da da— !",
          TalkActionId = {
            [1] = "200074:Explain01_End"
          }
        },
        [20005433] = {
          Camera = "177.701172,-34.273438,38.09375,0.000007,9.399986,107.997223,12.0,262.308319,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "对哦！虽然个头要大得多的多得多，但榛子其实也是魔灵呢。",
          DialogueId = 20005433,
          FinalCamera = "169.722656,-9.726562,42.367188,0.000007,9.399979,107.997246,14.0,262.308319,false,Manual,1.2",
          GUID = "3214DD5A",
          NextDialogue = 20005434,
          SpeakNpcId = 200074,
          Subtitle = "Yep! Actually, even though Filbert's way bigger, she's a Geniemon too.",
          TalkActionId = {
            [1] = "200074:Explain01_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200054/3214DD5A"
        },
        [20005434] = {
          Camera = "1157.898438,189.347656,179.595703,0.000041,-4.999971,177.499969,30.0,303.151581,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "接下来你们要是遇到落单的魔灵，也可以试着用罐罐喂它们，让它们远离魔灵猎人。",
          DialogueId = 20005434,
          FinalCamera = "1157.992188,177.085938,179.595703,0.000041,-4.999999,-179.604523,30.0,2103.335693,false,Manual,1.2",
          GUID = "3214DD84",
          NextDialogue = 20005435,
          SpeakNpcId = 200074,
          Subtitle = "So if you ever run into a lost Geniemon, try treating it to a Yum Treat to get it to follow you. That way, it won't end up in the hands of those bad Geniemon hunters.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200054/3214DD84"
        },
        [20005435] = {
          Camera = "408.402344,589.582031,258.791992,0.00006,-13.999961,-123.402359,50.0,854.679932,false,DoNotOverride,1.2",
          Content = "好！既然魔灵猎人猎人这么说了，我一定会督促{性别：他|她}，获得好多仆从的仆从！",
          DialogueId = 20005435,
          GUID = "3214DDAE",
          Scripts = [[
PARA{
PlayFacial{_delay{1},ActorId{200002},FacialId{"Smile01"}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Alright! If the Geniemon Hunter Hunter says so, I'll make sure Little Minion collects tons of {性别:his|her} own little minions!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200054/3214DDAE"
        },
        [20005501] = {
          Content = "{性别：大哥哥|大姐姐}你放心回冰湖城，有榛子陪着我，不会有什么事的哦。",
          DialogueId = 20005501,
          GUID = "3214E882",
          NextOptions = {
            [1] = 200055011,
            [2] = 200055012,
            [3] = 200055013
          },
          SpeakNpcId = 200074,
          Subtitle = "Feel free to go back to Icelake, {性别:Sir|Miss}. With Filbert here with me, I'll be just fine.",
          VoiceName = "voice/$Locale$/story/2001/200055/3214E882"
        },
        [20005502] = {
          Content = "嘿嘿，每一个人都这么说，不过你可不要害怕哦，榛子很温柔的，还能找到很多吃的，可能干啦。",
          DialogueId = 20005502,
          GUID = "3214E8AC",
          NextDialogue = 20005503,
          SpeakNpcId = 200074,
          Subtitle = "Hehe, we get that a lot. Don't let her size fool you, she's actually really gentle and sweet. Oh, and she's amazing at sniffing out food!",
          VoiceName = "voice/$Locale$/story/2001/200055/3214E8AC"
        },
        [20005503] = {
          Content = "可惜这附近太冷啦，应该长不了红蕈，否则我可以现场表演怎么和榛子一起，花半天就能找到小山那样多的红蕈。",
          DialogueId = 20005503,
          GUID = "3214E8D6",
          SpeakNpcId = 200074,
          Subtitle = "Too bad it's too cold around here for mushrooms to grow, or I'd totally show you how we can find an entire hill of Russulas in just half a day!",
          VoiceName = "voice/$Locale$/story/2001/200055/3214E8D6"
        },
        [20005504] = {
          Content = "我没有亲人哦，和他们分开的时候年纪太小了，不记得他们。现在唯一称得上亲人的就是榛子，榛子应该不担心我！",
          DialogueId = 20005504,
          GUID = "3214E900",
          NextDialogue = 20005505,
          SpeakNpcId = 200074,
          Subtitle = "I don't have any family. I was too young when we got separated, so I don't remember them. But I've got Filbert now, and she's the best family I could ask for! She always looks out for me, so I think she's not worried!",
          VoiceName = "voice/$Locale$/story/2001/200055/3214E900"
        },
        [20005505] = {
          Content = "哼哼！",
          DialogueId = 20005505,
          GUID = "3214E92A",
          SpeakNpcId = 200086,
          SpeakNpcName = "UI_Npc_Name_Zhengzi",
          Subtitle = "Oink, oink!",
          VoiceName = "voice/$Locale$/story/2001/200055/3214E92A"
        },
        [20005601] = {
          Camera = "206.224243,153.768555,150.494141,0.000043,0.799603,31.806444,35.0,197.205399,false,Manual,1.2",
          Content = "最近有好几位狩月人说在城外目击了一个小女孩与一只非常巨大的猪。我记得你们前一阵子好像也提到过什么巨猪，你们应该清楚是怎么一回事吧？",
          DialogueId = 20005601,
          FinalCamera = "269.964478,192.320312,152.126953,0.000045,1.799543,31.007589,35.000008,157,false,Manual,3.0",
          GUID = "3214F8EA",
          LookAt = {
            [1] = "700248:n(100001)"
          },
          NextDialogue = 20005602,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{13.1},TargetPosition{"458.206421,413.079102,178.546875,0.000085,-8.594481,-123.578712,35.000015,145.801529,false,Manual,3.5"},duration{0}},
CameraMoveTo{_delay{0.1},TargetPosition{"458.206421,413.079102,178.546875,0.000085,-8.594481,-123.578712,35.000015,423.338654,false,Manual,3.5"},duration{1}}
},
SEQ{
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Talk03_Start"}},
PlayAnimation{_delay{11.5},ActorId{700248},AnimationId{"Talk03ToTalkL_Start"}}
}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Lately, quite a few Phoxhunters have reported spotting a little girl wandering outside the city with an unusually large pig. If I remember correctly, didn't you mention something about a giant pig not too long ago? You wouldn't happen to know anything about it, would you?",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/2001/200056/3214F8EA"
        },
        [20005602] = {
          Camera = "291.128906,217.024414,140.351562,0.000078,-1.794851,-139.190552,35.000011,183.651901,false,Manual,5.0",
          Content = "是的，小女孩的名字是松露，巨猪是她的好朋友，叫做榛子。",
          DialogueId = 20005602,
          FinalCamera = "254.625366,186.235352,140.017578,0.000078,1.805246,-140.590668,35.000011,121.069733,false,Manual,5.0",
          GUID = "3214F914",
          NextDialogue = 20005603,
          Scripts = [[
PARA{
PlayFacial{_delay{0.5},ActorId{100001},FacialId{"Smile01"}},
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Talk02_Start"}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Talk03ToTalkL_End"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Yeah, her name is Truffle. And the \"giant pig\" is her best friend, Filbert.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200056/3214F914"
        },
        [20005603] = {
          Camera = "238.730103,360.248047,118.785156,0.000084,4.004109,-28.378315,35.000015,173.137497,false,Manual,3.0",
          Content = "松露与榛子……嗯，我知道了。我听说她最近一段时间都在追捕一群捕猎魔灵的人，还自称什么魔灵猎人猎人。",
          DialogueId = 20005603,
          FinalCamera = "238.730103,360.248047,118.785156,0.000089,9.403872,-31.579136,35.000015,173.137497,false,Manual,3.0",
          GUID = "3214F93E",
          NextDialogue = 20005604,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{4.1},TargetPosition{"245.294434,217.859375,129.169922,0.000062,8.205167,19.019411,35.000011,148.031906,false,Manual,3.0"},duration{0}},
CameraMoveTo{_delay{0.1},TargetPosition{"258.998169,222.688477,131.525391,0.000061,10.405068,19.019463,35.000011,148.031906,false,Manual,3.0"},duration{10}}
},
PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{"Talk02_End"}},
SEQ{
PARA{
PlayFacial{_delay{0.5},ActorId{700248},FacialId{"Smile01"}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Talk03ToThink_Start"}}
},
PlayAnimation{_delay{3.5},ActorId{700248},AnimationId{"Talk03ToThink_End"}}
}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Truffle and Filbert... Mmm, I see. I've heard she's been going after a group of Geniemon poachers. Calls herself something like... \"Geniemon Hunter Hunter\" or something along those lines.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200056/3214F93E"
        },
        [20005604] = {
          Camera = "229.978394,212.079102,125.222656,0.000063,-12.394109,-163.980286,35.000015,125.363708,false,Manual,16.0",
          Content = "是我给她起的名字哦！认识她之后，我和小仆从找到了许多魔灵伙伴呢。但这已经过去很久了，她怎么还没有回家？小仆从，我们再去城外去看看吧？",
          DialogueId = 20005604,
          FinalCamera = "248.590088,221.823242,130.414062,0.000062,-14.394124,-163.781052,35.000015,125.363708,false,Manual,16.0",
          GUID = "3214F968",
          LookAt = {
            [1] = "200002:n(700248)"
          },
          NextOptions = {
            [1] = 200056041,
            [2] = 200056042
          },
          Scripts = [[
PARA{
PlayFacial{_delay{0.5},ActorId{200002},FacialId{"Confident02"}},
PlayFacial{_delay{3.5},ActorId{200002},FacialId{"Smile01"}},
SEQ{
PlayAnimation{_delay{2},ActorId{200002},AnimationId{"Think_Start"}},
PlayAnimation{_delay{4},ActorId{200002},AnimationId{"Think_End"}},
PlayAnimation{_delay{2},ActorId{200002},AnimationId{"Confident_Start"}}
}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Yep, I gave her that name. Since meeting her, my Little Minion and I have made so many Geniemon friends! But it's been a little while... how come she's still out there? Little Minion, let's go check on her!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200056/3214F968"
        },
        [20005701] = {
          Camera = "410.972656,198.460693,114.729004,-0.000031,-1.800322,-174.782776,35.0,508.027344,false,Manual,12.0",
          Content = "松露，松露！",
          DialogueId = 20005701,
          GUID = "32150952",
          NextDialogue = 20005702,
          Scripts = "PARA{TurnTo{_delay{0.1},TurnToDescription{\"200074:p(180)\"}}}",
          SpeakNpcId = 200002,
          Subtitle = "Truffle— Truffle!",
          VoiceName = "voice/$Locale$/story/2001/200057/32150952"
        },
        [20005702] = {
          Camera = "508.414062,197.715576,181.711426,-0.000031,-9.197778,-175.56842,35.0,508.027344,false,Manual,12.0",
          Content = "呀，白，还有{性别：大哥哥|大姐姐}，你们好呀，好久不见！",
          DialogueId = 20005702,
          FinalCamera = "453.972656,194.084961,173.135742,-0.00003,-8.797789,-176.168381,35.0,508.027344,false,Manual,12.0",
          GUID = "3215097C",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20005703,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.01},TargetPosition{"91.301758,135.04248,143.762451,-0.00003,-7.397702,178.63237,35.0,164.878052,false,Manual,12.0"},duration{0}},
PARA{
PlayFacial{_delay{2.1},ActorId{200074},FacialId{"Smile01"}},
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{"Explain02_Start"},Duration{1}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "Oh! Hi, Snow! And you, {性别:Sir|Miss}! Long time no see!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200057/3215097C"
        },
        [20005703] = {
          Camera = "-112.980469,86.168457,117.201904,-0.00003,-4.197971,33.230522,35.000008,346.856049,false,Manual,4.5",
          Content = "是有一段时间没见啦！所以我们以为你早就回家啦，但是听说你还在冰湖城外，所以来看一看是怎么回事。",
          DialogueId = 20005703,
          FinalCamera = "-109.616211,88.798828,117.168213,-0.000031,-4.597933,31.231554,35.000008,346.856049,false,Manual,4.5",
          GUID = "321509A6",
          NextDialogue = 20005704,
          Scripts = [[
SEQ{
PARA{
PlayFacial{_delay{0.5},ActorId{200002},FacialId{"Smile02"}},
PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{"Confident_Start"}}
},
PARA{
PlayFacial{_delay{5.5},ActorId{200002},FacialId{"Smile01"}},
PlayAnimation{_delay{5.1},ActorId{200002},AnimationId{"Confident_End"}}
}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Yeah, it's been a while! We thought you'd be back home already, but then we heard you were still hanging around outside Icelake, so we came to see you.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/321509A6"
        },
        [20005704] = {
          Camera = "174.674805,96.316162,127.840088,-0.00003,-1.797822,171.026505,35.000008,262.313629,false,Manual,12.0",
          Content = "唔，原来是这样，谢谢你们关心我！其实呢我是发现，那些魔灵猎人的老巢应该就在冰湖城里，所以想要进城。",
          DialogueId = 20005704,
          FinalCamera = "130.125,103.350098,126.549561,-0.000031,-1.397791,171.026459,35.000008,262.313629,false,Manual,12.0",
          GUID = "321509D0",
          NextDialogue = 20005705,
          Scripts = [[
SEQ{
PARA{
PlayFacial{_delay{0.5},ActorId{200074},FacialId{"Shock01"}}
},
PARA{
PlayFacial{_delay{3.5},ActorId{200074},FacialId{"Smile01"}},
PlayAnimation{_delay{3.5},ActorId{200074},AnimationId{"Explain02_End"}}
},
PARA{
PlayFacial{_delay{7.5},ActorId{200074},FacialId{"Doubt01"}},
PlayAnimation{_delay{7.1},ActorId{200074},AnimationId{"Think_Start"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "Aww, thank you for worrying about me! Actually, I found out that the Geniemon hunters' hideout is probably in Icelake, so I was trying to get in.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/321509D0"
        },
        [20005705] = {
          Camera = "64.671875,111.317383,101.9104,-0.000031,9.201856,170.022354,35.000008,161.309708,false,Manual,12.0",
          Content = "可是城门口的看守一直凶巴巴的，不让我进去，我一靠近，他们就会像受了惊吓的小狗一样大叫什么“通行证——”之类的话。",
          DialogueId = 20005705,
          FinalCamera = "55.654297,112.968506,103.494141,-0.00003,9.801861,169.622452,35.000008,161.309708,false,Manual,12.0",
          GUID = "321509FA",
          NextDialogue = 20005706,
          Scripts = [[
SEQ{
PARA{
PlayFacial{_delay{0.5},ActorId{200074},FacialId{"Sad01"}}
},
PARA{
PlayFacial{_delay{4.5},ActorId{200074},FacialId{"Unhappy01"}},
PlayAnimation{_delay{4.5},ActorId{200074},AnimationId{"Think_End"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "But the guards at the city gate are so mean. The moment I get close, they freak out and start yipping \"travel permit\" like startled puppies.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/321509FA"
        },
        [20005706] = {
          Camera = "281.921875,86.812988,145.170654,-0.000031,-7.19766,167.213409,35.000008,329.815155,false,Manual,3.5",
          Content = "所以，我就只能在城外守着他们了，可是我也没法在这里待太久……",
          DialogueId = 20005706,
          FinalCamera = "281.921875,86.812988,145.170654,-0.00003,-8.197729,169.612885,35.000008,329.815155,false,Manual,3.5",
          GUID = "32150A24",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20005707,
          Scripts = [[
SEQ{
PARA{
PlayFacial{_delay{0.5},ActorId{200074},FacialId{"Smile01"}},
PlayAnimation{_delay{1.5},ActorId{200074},AnimationId{"Talk02_Start"}}
},
PARA{
PlayFacial{_delay{3.5},ActorId{200074},FacialId{"Sad01"}},
PlayAnimation{_delay{3.5},ActorId{200074},AnimationId{"Talk02_End"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "So I've just been hanging around here, keeping watch on those bad guys. But I can't stay here forever...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200057/32150A24"
        },
        [20005707] = {
          Camera = "-135.630859,76.342285,123.094727,-0.000031,-5.734251,33.558426,35.000008,340.999542,false,Manual,3.0",
          Content = "听起来，不让他们彻底改正的话，他们就一定还会在你离开之后继续干坏事。",
          DialogueId = 20005707,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-116.200195,88.540527,120.838623,-0.000031,-5.53427,31.959337,35.000008,340.999542,false,Manual,3.0",
          GUID = "32150A4E",
          NextDialogue = 20005708,
          SpeakNpcId = 200002,
          Subtitle = "Sounds like if they don't learn their lesson completely, they'll surely go back to their old tricks once you leave.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150A4E"
        },
        [20005708] = {
          Camera = "-8.198242,133.239258,135.716309,-0.000031,-0.597799,-2.184601,35.000008,217.195679,false,Manual,12.0",
          Content = "我倒是有一个主意，能把你带进城里，只是需要你稍微表演一下……",
          DialogueId = 20005708,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "28.713867,131.945801,136.378662,-0.000031,2.20221,-2.184601,35.000008,207.195679,false,Manual,12.0",
          GUID = "32150A78",
          NextDialogue = 20005709,
          SpeakNpcId = 100001,
          Subtitle = "I've got an idea to get you into the city, but it'll require a little bit of acting on your part...",
          TalkActionId = {
            [1] = "100001:Explain01_Start",
            [2] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150A78"
        },
        [20005709] = {
          Camera = "193.325195,45.578125,159.322266,-0.000033,-17.397202,90.218147,35.000011,226.37767,false,Manual,12.0",
          Content = "喔，真不愧是{nickname}，这么快就有主意了。快讲讲，什么法子？",
          DialogueId = 20005709,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "193.325195,45.578125,159.322266,-0.000032,-17.597197,86.818207,35.000011,226.37767,false,Manual,12.0",
          GUID = "32150AA2",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Ooooh! That was fast, ! What is it?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200074:Explain01_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200002:p(45)"
          },
          VoiceName = "voice/$Locale$/story/2001/200057/32150AA2"
        },
        [20005710] = {
          Content = "如何将松露带进冰湖城，这个问题可谓非常简单，分三步：第一步，打开水仙平原的大门。第二步，向卡米拉求助。",
          DialogueId = 20005710,
          GUID = "32150ACC",
          Subtitle = [[
How to get Truffle into Icelake? Simple. Just three steps.
Step 1: Go to The Asphodel.
Step 2: Seek help from Camilla.]],
          VoiceName = "voice/$Locale$/story/2001/200057/32150ACC"
        },
        [20005711] = {
          Camera = "186.849121,350.689453,139.634766,0.000105,-3.997586,-21.968235,35.0,214.900024,false,Manual,2.5",
          Content = "你是说，让我带着非常显眼的一人一猪，没有通行证，进入冰湖城，教训捕捉魔灵的坏人？",
          DialogueId = 20005711,
          FinalCamera = "211.255615,398.773438,139.634766,0.000105,-1.797426,-36.767586,35.0,214.900024,false,Manual,2.5",
          GUID = "32150AF6",
          NextDialogue = 20005712,
          Scripts = [[
PARA{
CameraMoveTo{_delay{7.01},TargetPosition{"315.877808,219.341797,163.929688,0.000117,-1.797535,31.633312,35.0,88.606956,false,Manual,3.0"},duration{0}},
SEQ{
PlayFacial{_delay{0.5},ActorId{700248},FacialId{"Uninterested01"}},
PlayAnimation{ActorId{700248},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{ActorId{700248},AnimationId{"Talk03ToTalkL_Start"},Duration{1}}
}
}]],
          SpeakNpcId = 700248,
          Subtitle = "So, you want me to get a highly conspicuous little girl and an even more conspicuous oversized pig, who doesn't have a travel permit, into Icelake, so you can go after some Geniemon poachers?",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200057/32150AF6"
        },
        [20005712] = {
          Camera = "420.913696,326.766602,167.314453,0.000115,-8.594393,-131.77652,35.0,432.314148,false,Manual,12.0",
          Content = "是的……卡米拉女士，我相信你的实力，这对你来说应该轻而易举才是。",
          DialogueId = 20005712,
          FinalCamera = "406.812988,310.303711,164.074219,0.000119,-7.994415,-131.776855,35.0,432.314148,false,Manual,12.0",
          GUID = "32150B20",
          NextDialogue = 20005713,
          Scripts = [[
PARA{
CameraMoveTo{_delay{7.01},TargetPosition{"315.877808,219.341797,163.929688,0.000117,-1.797535,31.633312,35.0,88.606956,false,Manual,3.0"},duration{0}},
PlayFacial{_delay{7.1},ActorId{700248},FacialId{"Smile01"}},
PlayAnimation{_delay{7.1},ActorId{700248},AnimationId{"Talk03ToTalkL_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Yes... I believe in you, Ms Camilla. This should be easy for someone of your calibre.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200057/32150B20"
        },
        [20005713] = {
          Camera = "105.950684,106.310547,143.28125,0.000089,-0.195924,25.407034,35.0,296.233398,false,Manual,3.5",
          Content = "我是一个生意人，不是慈善家，按理来说我不应该答应你的这个荒诞请求。但你提到她自称松露，而猪的名字是榛子，又来自很远的地方。",
          DialogueId = 20005713,
          FinalCamera = "126.168945,116.245117,143.28125,0.000089,0.004084,25.406322,35.0,296.233398,false,Manual,3.5",
          GUID = "32150B4A",
          NextDialogue = 20005714,
          Scripts = [[
PARA{
CameraMoveTo{_delay{10.01},TargetPosition{"329.772583,250.364258,155.642578,0.0001,5.403574,13.413886,35.0,65.400925,false,Manual,3.5"},duration{0}},
SEQ{
PlayAnimation{ActorId{700248},AnimationId{"Talk03ToTalkL_Start"}},
PlayAnimation{_delay{2},ActorId{700248},AnimationId{"Talk03ToTalkL_End"}}
},
PlayAnimation{_delay{10.1},ActorId{700248},AnimationId{"Talk03ToThink_Start"},Duration{1}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "I run a business, not a charity. Technically, I shouldn't agree to your absurd request. That said, you mentioned her name is Truffle, her friend is called Filbert, and they came from a faraway place...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150B4A"
        },
        [20005714] = {
          Camera = "162.299316,114.061523,175.494141,0.000119,-6.196505,33.218781,35.0,247.15065,false,Manual,3.5",
          Content = "这和我所知的某些信息完全一致。那么，卖她一个人情也无妨，只是进城之后的安危，我可管不了。",
          DialogueId = 20005714,
          FinalCamera = "31.679077,26.966797,192.6875,0.000139,-8.796512,33.820679,35.0,386.063599,false,Manual,12.0",
          GUID = "32150B74",
          Scripts = [[
PARA{
CameraMoveTo{_delay{10.01},TargetPosition{"223.292969,158.923828,146.234375,0.000157,-1.396685,-143.179001,35.0,73.960266,false,Manual,12.0"},duration{0}},
CameraMoveTo{_delay{12.1},TargetPosition{"332.739868,241.896484,171.638672,0.000163,-6.796741,21.82086,35.0,73.960266,false,Manual,12.0"},duration{0}},
PlayFacial{_delay{10.1},ActorId{100001},FacialId{"Smile02"}},
PlayFacial{_delay{12.1},ActorId{700248},FacialId{"Smile02"}},
SEQ{
PlayAnimation{_delay{1.1},ActorId{700248},AnimationId{"Talk03ToThink_End"}},
PlayAnimation{_delay{4.1},ActorId{700248},AnimationId{"Talk03_End"}},
PlayAnimation{_delay{4.1},ActorId{700248},AnimationId{"Confident_Start"}}
}
}]],
          SpeakNpcId = 700248,
          Subtitle = "That reminds me of something I've heard before. I suppose I could do her a favour, but once she's in the city, I can't vouch for her safety.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150B74"
        },
        [20005715] = {
          Content = "于是，将松露带进冰湖城的第三步是：关上水仙平原的大门。",
          DialogueId = 20005715,
          Duration = 5,
          GUID = "32150B9E",
          Subtitle = "And so, Step 3 of getting Truffle into Icelake: Leave The Asphodel.",
          VoiceName = "voice/$Locale$/story/2001/200057/32150B9E"
        },
        [20005716] = {
          Camera = "582.584167,303.073242,220.535156,-0.000763,-20.994682,-174.971664,35.000011,349.15741,false,Manual,12.0",
          Content = "谢谢你，卡米拉女士。我刚刚有点紧张，把你交待的维瓦尔酒庄说成了瓦瓦瓦酒庄，呜……",
          DialogueId = 20005716,
          FinalCamera = "583.070496,298.848633,220.535156,-0.000763,-21.19463,-178.171448,35.000011,349.15741,false,Manual,12.0",
          GUID = "32150BC8",
          LookAt = {
            [1] = "200074:n(700248)"
          },
          NextDialogue = 20005717,
          Scripts = [[
PARA{
PARA{
CameraMoveTo{_delay{10.01},TargetPosition{"357.877014,290.280273,133.265625,-0.000763,-8.436526,153.589661,35.000011,149.736649,false,Manual,12.0"},duration{0}},
CameraMoveTo{_delay{10.2},TargetPosition{"336.220581,301.040039,129.683594,-0.000763,-8.436526,153.589767,35.000011,116.715118,false,Manual,4.8"},duration{3}}
},
SEQ{
PlayAnimation{_delay{0.1},ActorId{200074},AnimationId{"Explain02_Start"}},
PARA{
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{"Explain02_End"}},
PlayFacial{_delay{4.1},ActorId{200074},FacialId{"Sad01"}}
},
PARA{
