        },
        [20006512] = {
          Camera = "13.498047,83.051758,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
          Content = "我……我乃魔灵猎人猎人，粮秣专员松露！以及粮秣特别专员，榛子！",
          DialogueId = 20006512,
          FinalCamera = "2.105469,81.813477,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
          GUID = "32158E60",
          NextDialogue = 20006513,
          Scripts = [[
PARA{
CameraMoveTo{_delay{6.01},TargetPosition{"150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0"},duration{0}},
SEQ{
PlayFacial{_delay{3.5},ActorId{200074},FacialId{"Confident01"}},
PlayAnimation{_delay{3.1},ActorId{200074},AnimationId{"Confident_Start"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "I... I am the Geniemon Hunter Hunter, Commissary Truffle! And Filbert, the Special Commissary!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E60"
        },
        [20006513] = {
          Camera = "150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0",
          Content = "哼哼！",
          DialogueId = 20006513,
          FinalCamera = "134.871094,118.75,17.023186,0.000235,24.799322,157.617859,35.0,628.586243,false,Manual,12.0",
          GUID = "32158E8A",
          NextDialogue = 200065130,
          SpeakNpcId = 200086,
          Subtitle = "Oink, oink!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E8A"
        },
        [20006514] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,16.0",
          Content = "懂了，你们是盖雷亚剧院的演员。",
          DialogueId = 20006514,
          GUID = "32158EB4",
          NextDialogue = 20006515,
          SpeakNpcId = 200075,
          Subtitle = "Oh, I get it. You're performers from the Galea Theatre.",
          TalkActionId = {
            [1] = "200075:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158EB4"
        },
        [20006515] = {
          Camera = "-26.337891,71.758789,115.010025,0.000102,5.001563,-179.000427,35.000019,100.535843,false,Manual,8.0",
          Content = "不……不是的！请你们放了这些魔灵！否则，我会让榛子撞飞你们！",
          DialogueId = 20006515,
          GUID = "32158EDE",
          Scripts = [[
SEQ{
PlayFacial{_delay{0.1},ActorId{200074},FacialId{"Unacceptable01"}},
PlayFacial{_delay{0.6},ActorId{200074},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "That's not it...! Let the Geniemons go, or Filbert will knock you flying!",
          TalkActionId = {
            [1] = "200074:Confident_End",
            [2] = "200074:Disagree"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158EDE"
        },
        [20006516] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
          Content = "刚刚在城外不就是你和这个什么光之魔头坏了我们的好事吗？",
          DialogueId = 20006516,
          GUID = "32158F08",
          NextDialogue = 20006517,
          SpeakNpcId = 200075,
          Subtitle = "Wasn't it you and that Demon King of something or other who ruined our hunt outside the city?",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158F08"
        },
        [20006517] = {
          Camera = "-27.242188,73.443359,154.929871,0.00007,-15.000351,-177.200226,35.000015,130.614029,false,Manual,8.0",
          Content = "是光之魔王大人，不好好记住别人的名字是很没有礼貌的行为，会被榛子撞飞的！",
          DialogueId = 20006517,
          FacialId = {
            [1] = "200074:Confident02"
          },
          GUID = "32158F32",
          LookAt = {
            [1] = "200074:n(200075)"
          },
          SpeakNpcId = 200074,
          Subtitle = "It's the Demon King of Light! It's very rude to get someone's name wrong! You'll get rammed by Filbert for that!",
          VoiceName = "voice/$Locale$/story/2001/200065/32158F32"
        },
        [20006518] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
          Content = "白日做——梦！",
          DialogueId = 20006518,
          GUID = "32158F5C",
          NextDialogue = 20006519,
          SpeakNpcId = 200075,
          Subtitle = "In — your— dreams!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158F5C"
        },
        [20006519] = {
          Camera = "9.128906,71.000977,164.786407,0.000102,-18.198389,-178.600586,35.000008,450.0,false,Manual,6.0",
          Content = "如果是这样的话，那……榛子，撞飞他们！",
          DialogueId = 20006519,
          FinalCamera = "-9.466797,68.333008,115.745117,0.000102,3.801383,-177.600464,35.000011,131.004227,false,Manual,6.0",
          GUID = "32158F86",
          LookAt = {
            [1] = "200074:n(200075)"
          },
          Scripts = [[
SEQ{
PlayFacial{_delay{0.1},ActorId{200074},FacialId{"Confident02"}},
PlayFacial{_delay{1.6},ActorId{200074},FacialId{"Doubt01"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "If that's how you want it... Filbert, charge!",
          TalkActionId = {
            [1] = "200074:Confident_End",
            [2] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200065/32158F86"
        },
        [20006601] = {
          Content = "打就打，还怕你们几个半大孩子和一头畜生不成？",
          DialogueId = 20006601,
          GUID = "32159CFA",
          NextDialogue = 20006602,
          SpeakNpcId = 200087,
          Subtitle = "Pfft, what's the holdup? You think I'd be scared of a few kids and their walking pile of bacon?",
          VoiceName = "voice/$Locale$/story/2001/200066/32159CFA"
        },
        [20006602] = {
          Content = "不可以这么骂榛子！向榛子道歉！",
          DialogueId = 20006602,
          GUID = "32159D24",
          NextDialogue = 20006603,
          SpeakNpcId = 200074,
          Subtitle = "You take that back! Apologize to Filbert now!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D24"
        },
        [20006603] = {
          Content = "能打赢再说！",
          DialogueId = 20006603,
          GUID = "32159D4E",
          SpeakNpcId = 200087,
          Subtitle = "Oh yeah? Make me!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D4E"
        },
        [20006604] = {
          Content = "咿咿呀——",
          DialogueId = 20006604,
          GUID = "32159D78",
          NextDialogue = 20006605,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D78"
        },
        [20006605] = {
          Content = "不好了老大，这个魔灵把其他魔灵都放出来了！",
          DialogueId = 20006605,
          GUID = "32159DA2",
          NextDialogue = 20006606,
          SpeakNpcId = 200075,
          Subtitle = "B—Boss! That Geniemon — it released all the other ones!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DA2"
        },
        [20006606] = {
          Content = "啾——",
          DialogueId = 20006606,
          GUID = "32159DCC",
          NextDialogue = 20006607,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Chirp—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DCC"
        },
        [20006607] = {
          Content = "咩——",
          DialogueId = 20006607,
          GUID = "32159DF6",
          NextDialogue = 20006608,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Baa—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DF6"
        },
        [20006608] = {
          Content = "叮咚——",
          DialogueId = 20006608,
          GUID = "32159E20",
          NextDialogue = 20006609,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ding-dong—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E20"
        },
        [20006609] = {
          Content = "啊呀，好烫好烫——好麻——冷冷冷——",
          DialogueId = 20006609,
          GUID = "32159E4A",
          NextDialogue = 20006610,
          SpeakNpcId = 200087,
          Subtitle = "Aghhh—! Too hot— Too tingly— No, too cold—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E4A"
        },
        [20006610] = {
          Content = "我错了！我错了！",
          DialogueId = 20006610,
          GUID = "32159E74",
          SpeakNpcId = 200087,
          Subtitle = "I'm sorry! I SURRENDER! PLEASE!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E74"
        },
        [20006701] = {
          Camera = "-939.216797,26.854492,320.087097,0.0,-13.407927,0.807412,35.000008,450.0,false,Manual,6.0",
          Content = "{nickname}大人，魔灵猎人猎人大人，还有光之魔王大人，我错了，我们错了。这些魔灵我们都不要了，饶了我们。",
          DialogueId = 20006701,
          GUID = "3215AD62",
          NextDialogue = 20006702,
          SpeakNpcId = 200087,
          Subtitle = "Lord , Great Geniemon Hunter Hunter, and mighty Demon King of Light — have mercy! We're sorry! We'll leave the Geniemons alone!",
          TalkActionId = {
            [1] = "200075:Avoid",
            [2] = "200087:Avoid"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215AD62"
        },
        [20006702] = {
          Content = "诶？不用这么害怕，只要你们保证以后不再乱捉魔灵，我和榛子就不会把你们怎么样的。",
          DialogueId = 20006702,
          GUID = "3215AD8C",
          NextDialogue = 20006703,
          SpeakNpcId = 200074,
          Subtitle = "Well, no need to be so terrified. As long as you promise you'll never lay a hand on Geniemons again, Filbert and I won't hurt you.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AD8C"
        },
        [20006703] = {
          Content = "一定，一定。",
          DialogueId = 20006703,
          GUID = "3215ADB6",
          NextDialogue = 20006704,
          SpeakNpcId = 200075,
          Subtitle = "I promise... I swear...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215ADB6"
        },
        [20006704] = {
          Content = "我也一定不捉魔灵了！也监督老大，要是老大又开始抓魔灵，我第一个告诉你们！",
          DialogueId = 20006704,
          GUID = "3215ADE0",
          NextDialogue = 20006705,
          SpeakNpcId = 200087,
          Subtitle = "Same here! And I'll keep an eye on Boss — if he so much as thinks about catching another Geniemon, I'll turn him in myself!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215ADE0"
        },
        [20006705] = {
          Content = "好，那么你们也需要向它们道歉。",
          DialogueId = 20006705,
          GUID = "3215AE0A",
          NextDialogue = 20006706,
          SpeakNpcId = 200074,
          Subtitle = "Alright, then. But you also owe them an apology.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE0A"
        },
        [20006706] = {
          Content = "非常抱歉！是我利欲熏心，本来想要研究魔灵，却怎么都写不出论文，所以动起了歪心思……你们来捕猎我吧，让我这个魔灵猎人体验魔灵猎人……",
          DialogueId = 20006706,
          GUID = "3215AE34",
          NextDialogue = 20006708,
          SpeakNpcId = 200075,
          Subtitle = "I—I'm truly sorry! I let greed get the best of me. I wanted to study Geniemons, but I couldn't even write a proper research paper, that's why I turned to this... Go ahead. Take your revenge — hunt me like how I did to you...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE34"
        },
        [20006707] = {
          Content = "我实在是不聪明，居然质疑潘神大人的智力，潘神大人比我还要聪明……比老大还要聪明！今天开始我称呼你为老大……",
          DialogueId = 20006707,
          GUID = "3215AE5E",
          SpeakNpcId = 200087,
          Subtitle = "I was such a fool to question Lord Paniemon's intelligence — Lord Paniemon is smarter than me... smarter than my boss even! From today onward, I pledge my loyalty to you, Lord Paniemon!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE5E"
        },
        [20006708] = {
          Content = "咿咿。",
          DialogueId = 20006708,
          GUID = "3215AE88",
          NextDialogue = 20006709,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE88"
        },
        [20006709] = {
          Camera = "35.800781,50.916992,117.894058,0.000003,-4.407924,143.206772,35.000011,450.0,false,Manual,6.0",
          Content = "唔，看你们这么诚恳，姑且相信你们吧。那么，接下来，{nickname}，小白，我们得想办法安置这些魔灵。",
          DialogueId = 20006709,
          FinalCamera = "140.537109,-26.151367,129.112198,0.000003,-5.407959,144.206726,35.000011,450.0,false,Manual,6.0",
          GUID = "3215AEB2",
          NextDialogue = 20006710,
          SpeakNpcId = 200074,
          Subtitle = "Well, you do seem genuinely sorry. We'll believe you for now. Alright, {性别:Sir|Miss}, Snow, what should we do with the Geniemons?",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AEB2"
        },
        [20006710] = {
          Camera = "-101.119141,154.260742,108.99675,0.000025,3.592208,132.807907,35.000015,110.824821,false,Manual,6.0",
          Content = "这么多魔灵，应该没法带出冰湖城，直接放生的话，它们也会因为附近没有月石这样的能量来源陷入困境……",
          DialogueId = 20006710,
          FacialId = {
            [1] = "200074:Unhappy01"
          },
          GUID = "3215AEDC",
          NextDialogue = 20006711,
          SpeakNpcId = 200074,
          Subtitle = "There are so many of them, it'd be impossible to sneak them out of Icelake. But we can't just release them here — there's no steady source of Phoxene energy for them to survive...",
          TalkActionId = {
            [1] = "200074:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215AEDC"
        },
        [20006711] = {
          Camera = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192425,35.000015,161.420593,false,Manual,6.0",
          Content = "怎么会这样……也就是说尽管我们救了它们，但还是不能确保它们一定都能活下来是吗？",
          DialogueId = 20006711,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          FinalCamera = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192459,35.000011,450.0,false,Manual,6.0",
          GUID = "3215AF06",
          NextDialogue = 20006712,
          SpeakNpcId = 200002,
          Subtitle = "How can this be...? Are you saying, that even though we saved them from the poachers, we still can't make sure they all survive?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF06"
        },
        [20006712] = {
          Camera = "-64.103516,31.655273,119.67865,0.000029,-4.808036,119.607536,35.000011,450.0,false,Manual,6.0",
          Content = "是的，除非有足够多的月石……可是这么多的魔灵，除非冰湖城每户人家都拿出一块月石来……可是一般人都很害怕魔灵的，肯定不愿意这么做……",
          DialogueId = 20006712,
          FinalCamera = "14.46875,-50.96875,106.754761,0.000019,-3.007906,-59.192356,35.000015,134.451996,false,Manual,6.0",
          GUID = "3215AF30",
          NextDialogue = 20006713,
          SpeakNpcId = 200074,
          Subtitle = "That's right. Unless we can get enough Phoxene for all of them... That would require every household in Icelake to chip in at least one piece. But most people are afraid of Geniemons. There's no way they'd agree to help...",
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF30"
        },
        [20006713] = {
          Camera = "-108.800781,-45.291992,165.959991,0.000029,-12.807772,59.206985,35.000008,450.0,false,Manual,6.0",
          Content = "哼哼……",
          DialogueId = 20006713,
          GUID = "3215AF5A",
          NextDialogue = 20006714,
          SpeakNpcId = 200086,
          Subtitle = "Oink, oink...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF5A"
        },
        [20006714] = {
          Camera = "-112.921875,-23.537109,160.274353,0.000064,1.1921,-114.590996,35.000011,159.3237,false,Manual,6.0",
          Content = "嗯……得想想办法……",
          DialogueId = 20006714,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-122.841797,-45.224609,160.77063,0.000065,2.392089,-114.590553,35.000011,142.061966,false,Manual,6.0",
          GUID = "3215AF84",
          NextDialogue = 20006715,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... We need a plan...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF84"
        },
        [20006715] = {
          Camera = "-20.984375,-89.079102,120.151733,0.000088,-7.208342,-37.78812,35.000015,123.723419,false,Manual,6.0",
          Content = "虽然我还没有亲眼见到，但是一想到这件事可能是真的，就觉得非常可怕！",
          DialogueId = 20006715,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-40.863281,-87.678711,84.628616,0.000085,7.591741,-32.988117,35.000015,161.950012,false,Manual,6.0",
          GUID = "3215AFAE",
          NextDialogue = 20006716,
          SpeakNpcId = 200002,
          Subtitle = "I haven't seen it yet, but just thinking about it — ooh, I'm getting goosebumps already!",
          TalkActionId = {
            [1] = "200002:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AFAE"
        },
        [20006716] = {
          Camera = "-92.931641,513.984375,128.895233,0.000055,-1.407743,-97.792145,35.000008,450.0,false,Manual,6.0",
          Content = "松露，在你的家乡，大家会害怕榛子吗？",
          DialogueId = 20006716,
          GUID = "3215AFD8",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006717,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.1},ActorId{100001},AnimationId{"Think_End"}},
PARA{
PlayFacial{_delay{0.5},ActorId{100001},FacialId{"Confident01"}},
PlayAnimation{_delay{2.1},ActorId{100001},AnimationId{"Talk02_Start"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Truffle, back in your hometown, are people scared of Filbert?",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AFD8"
        },
        [20006717] = {
          Camera = "-130.119141,-252.262695,186.619904,0.00007,-10.007689,106.210793,35.000011,450.0,false,Manual,6.0",
          Content = "嗯？实话说，一开始大家没看过这么大的猪，都会有点害怕的。但是一旦知道榛子能够和我一起找到很多食物，非常能干，就不害怕了。",
          DialogueId = 20006717,
          FacialId = {
            [1] = "200074:Smile01"
          },
          GUID = "3215B002",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20006718,
          SpeakNpcId = 200074,
          Subtitle = "Well, at first, yeah. No one had ever seen a pig this big before, so they were a little scared. But once they saw how she helped me find food, how smart and hardworking she is — they weren't scared anymore.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200074:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B002"
        },
        [20006718] = {
          Camera = "-143.039062,97.484375,110.879364,0.000087,0.791714,106.205078,35.000015,140.05127,false,Manual,6.0",
          Content = "是的，觉得害怕是因为不够了解，如果让大家了解魔灵的能力，获得魔灵的帮助，就一定不会害怕了。",
          DialogueId = 20006718,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-146.861328,105.399414,111.090088,0.000087,1.391712,107.405457,35.000015,140.05127,false,Manual,6.0",
          GUID = "3215B02C",
          NextDialogue = 20006719,
          SpeakNpcId = 100001,
          Subtitle = "Right. Fear comes from not knowing. But if people see what Geniemons are capable of — how they can help — then maybe that fear will disappear.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B02C"
        },
        [20006719] = {
          Content = "松露，白，我们一起把这些魔灵带到水仙平原去。",
          DialogueId = 20006719,
          GUID = "3215B056",
          SpeakNpcId = 100001,
          Subtitle = "Truffle, Snow — let's take them to The Asphodel.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B056"
        },
        [20006720] = {
          Camera = "390.472656,-23.833008,76.522202,0.000054,0.592102,149.805954,35.000011,450.0,false,Manual,6.0",
          Content = "好的，榛子坐下，我们把魔灵放到你的背上，一口气都带出去。",
          DialogueId = 20006720,
          FinalCamera = "290.703125,34.223633,80.627289,0.000054,2.592091,149.805908,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B080",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          NextDialogue = 20006721,
          SpeakNpcId = 200074,
          Subtitle = "Alright! Filbert, sit down — let's load them onto your back and take them all in one trip!",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B080"
        },
        [20006721] = {
          Content = "嗯？又要找卡米拉吗？她呀，肯定又要嘴上说着不愿意，然后和你一起想办法了。",
          DialogueId = 20006721,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "3215B0AA",
          NextDialogue = 20006722,
          SpeakNpcId = 200002,
          Subtitle = "Huh? We're going to Camilla again? She's totally going to wear a big frown and act like she doesn't want to get involved... then come up with a perfect idea to help us.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0AA"
        },
        [20006722] = {
          Content = "我也来帮忙！",
          DialogueId = 20006722,
          GUID = "3215B0D4",
          NextDialogue = 20006723,
          SpeakNpcId = 200087,
          Subtitle = "I'll help too!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0D4"
        },
        [20006723] = {
          Content = "还有我，还有我。",
          DialogueId = 20006723,
          GUID = "3215B0FE",
          NextDialogue = 20006724,
          SpeakNpcId = 200075,
          Subtitle = "Me too!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0FE"
        },
        [20006724] = {
          Camera = "25.234375,43.664062,76.073486,0.000057,-10.207888,-1.19403,35.000011,450.0,false,Manual,6.0",
          Content = "咿咿。",
          DialogueId = 20006724,
          FinalCamera = "-37.855469,44.204102,84.949371,0.000057,-8.007871,-0.194,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B128",
          NextDialogue = 20006725,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B128"
        },
        [20006725] = {
          Camera = "447.40625,104.102539,80.368851,0.000072,-1.207823,-159.593887,35.000011,450.0,false,Manual,6.0",
          Content = "嗯？你不一起跟着来吗？",
          DialogueId = 20006725,
          FinalCamera = "483.496094,102.482422,81.651184,0.000072,-3.00781,-160.39386,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B152",
          LookAt = {
            [1] = "100001:n(700251)"
          },
          NextDialogue = 20006726,
          SpeakNpcId = 100001,
          Subtitle = "Huh? You're not coming with us?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B152"
        },
        [20006726] = {
          Camera = "45.181641,44.441406,28.436035,0.000076,6.992051,-0.794525,35.000011,450.0,false,Manual,6.0",
          Content = "魔灵潘神一般都会和人尽可能保持距离，看起来刚刚它只是想靠你们把其他魔灵救出来。",
          DialogueId = 20006726,
          FinalCamera = "-94.589844,48.933594,37.514648,0.000076,0.791967,-1.194519,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B17C",
          NextDialogue = 20006727,
          SpeakNpcId = 200075,
          Subtitle = "Paniemon usually keeps its distance from people. It probably just showed up to get you to help free the other Geniemons.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B17C"
        },
        [20006727] = {
          Camera = "-76.480469,-72.768555,129.284988,0.000097,13.191738,-135.390411,35.000015,137.250519,false,Manual,6.0",
          Content = "好，那你也要小心。",
          DialogueId = 20006727,
          FinalCamera = "-99.601562,-95.574219,136.62146,0.000099,15.191671,-135.990753,35.000015,105.456551,false,Manual,6.0",
          GUID = "3215B1A6",
          NextDialogue = 20006728,
          SpeakNpcId = 100001,
          Subtitle = "I see. Alright, take care, Paniemon.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1A6"
        },
        [20006728] = {
          Camera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          Content = "咿咿咿。",
          DialogueId = 20006728,
          FinalCamera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B1D0",
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yiiiip~",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1D0"
        },
        [20006801] = {
          Content = "最终，这些魔灵被一起带到了水仙平原，吓跑了一屋子的客人，并成功让卡米拉眉头紧锁，开始思考当初是不是不应该带{nickname}进城。",
          DialogueId = 20006801,
          Duration = 5,
          GUID = "3215BDCA",
          Subtitle = [[
And so, the Geniemons were successfully brought to The Asphodel.
The moment they arrived, the tavern customers scrambled for the exits, knocking over chairs in their haste.
Camilla did frown, pinching the bridge of her nose as she reconsidered whether bringing  into the city had been a terrible mistake.]],
          VoiceName = "voice/$Locale$/story/2001/200068/3215BDCA"
        },
        [20006901] = {
          Content = "又过了一段时间，卡米拉的眉头终于缓缓舒展开来……",
          DialogueId = 20006901,
          Duration = 3,
          GUID = "3215CE32",
          Subtitle = "But as the days passed, Camilla's frown began to ease...",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE32"
        },
        [20006902] = {
          Camera = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
          Content = "哟，卡米拉，给我来一杯“打火鸡特调”，这么冷的天来上一口，再合适不过了。",
          DialogueId = 20006902,
          GUID = "3215CE5C",
          LookAt = {
            [1] = "700253:n(700248)",
            [2] = "700254:n(700253)"
          },
          NextDialogue = 20006903,
          Scripts = [[
PARA{
PlayFacial{_delay{3.5},ActorId{700248},FacialId{"Confident01"}},
PlayAnimation{_delay{3.1},ActorId{700248},AnimationId{"Talk03_Start"}}
}]],
          SpeakNpcId = 700253,
          Subtitle = "Camilla, I'll have a Zippyro Special. Nothing beats a drink warmed by real flames on a freezing day like this.",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE5C"
        },
        [20006903] = {
          Content = "一开始我觉得这小东西很邪门，没想到喷出的火焰拿来温酒，绝了！",
          DialogueId = 20006903,
          GUID = "3215CE86",
          LookAt = {
            [1] = "700253:n(700253)"
          },
          NextDialogue = 20006904,
          SpeakNpcId = 700253,
          Subtitle = "Gotta admit, when I first saw this little thing, I thought it was evil with that weird flame. But turns out that flame's perfect for heating a nice drink. Hah — who'd have thought!",
          TalkActionId = {
            [1] = "700253:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE86"
        },
        [20006904] = {
          Camera = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
          Content = "可悲啊，威尔斯先生，可叹啊，威尔斯先生。",
          DialogueId = 20006904,
          GUID = "3215CEB0",
          NextDialogue = 20006905,
          SpeakNpcId = 700254,
          Subtitle = "Oh, the folly, Wells! The wretched, wretched folly!",
          TalkActionId = {
            [1] = "700254:Sigh_Start",
            [2] = "700253:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEB0"
        },
        [20006905] = {
          Camera = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
          Content = "你只知道打火鸡的火焰可以让酒水温热，暖及肚肠，却不知道它真正的价值，在于划破黑暗，在黑夜中为我点亮书本，带来灵感！",
          DialogueId = 20006905,
          GUID = "3215CEDA",
          NextDialogue = 20006906,
          SpeakNpcId = 700254,
          Subtitle = "You see only the fleeting comfort of a warm drink! But Zippyro's flame — it doesn't merely warm the body! It carves through the abyss! It ignites the eternal night! It is the fire of my muse!",
          TalkActionId = {
            [1] = "700254:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEDA"
        },
        [20006906] = {
          Camera = "-89.716675,175.708008,152.642578,-0.000763,-3.992218,-88.380859,35.000008,369.08606,false,Manual,12.0",
          Content = "打，火，鸡。多么美妙的三个字，我的写作生命之光，我的创作欲念之火！我的罪恶，我的灵魂！",
          DialogueId = 20006906,
          GUID = "3215CF04",
          SpeakNpcId = 700254,
          Subtitle = "Zippyro! Three syllables of pure poetry! The spark of my words, the pyre of my soul, my sin, and my salvation!",
          TalkActionId = {
            [1] = "700254:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CF04"
        },
        [20007001] = {
          Camera = "410.60437,303.494141,154.748047,0.000089,0.396813,37.710804,35.0,369.08606,false,Manual,12.0",
          Content = "有人用雨衣水滴浇花，有人用好梦先生助眠……就连我的生意，也离不开一只打火鸡。",
          DialogueId = 20007001,
          FinalCamera = "262.071167,223.890625,147.691406,0.000094,-1.403686,36.110554,35.000011,369.08606,false,Manual,12.0",
          GUID = "3215DE9A",
          NextDialogue = 20007002,
          Scripts = [[
PARA{
SEQ{
TurnTo{_delay{2},TurnToDescription{"700248:p(180)"}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Confident_Start"},Duration{1}}
},
PlayFacial{_delay{0.5},ActorId{700248},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Some people use Dripplet to water their plants. Others rely on Mr Goodnight for sleep. And now, even my business depends on a Zippyro.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DE9A"
        },
        [20007002] = {
          Content = "现在根本不会有人想要从魔灵身上提炼月石，反而会为了和魔灵更加亲近，专门买月石去喂养它们，挺有趣的。",
          DialogueId = 20007002,
          GUID = "3215DEC4",
          LookAt = {
            [1] = "100001:n(200074)",
            [2] = "200002:n(200074)"
          },
          NextDialogue = 20007003,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Confident_End"},Duration{1}},
PARA{
PlayAnimation{_delay{1.5},ActorId{700248},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{_delay{7.5},ActorId{700248},FacialId{"Smile02"}}
},
PlayFacial{_delay{1.0},ActorId{700248},FacialId{"None"}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Funny how things turn around. Not long ago, people were all about extracting Phoxene from Geniemons — now they're buying it just to keep them around.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEC4"
        },
        [20007003] = {
          Camera = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
          Content = "这也是看到松露和榛子才想到的。既然榛子能和人类友好相处，那么魔灵也能。",
          DialogueId = 20007003,
          GUID = "3215DEEE",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007004,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "That all thanks to Truffle and Filbert. If Filbert can live peacefully with humans, then so can Geniemons.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEEE"
        },
        [20007004] = {
          Camera = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,169.08606,false,Manual,12.0",
          Content = "而如果魔灵都能和人类友好相处，那么卡戎和索拉之民，迟早有一天也会相处融洽的。",
          DialogueId = 20007004,
          GUID = "3215DF18",
          NextDialogue = 20007005,
          Scripts = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
          SpeakNpcId = 100001,
          Subtitle = "And if Geniemons and humans can get along, maybe one day Charons and Solarians will too.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF18"
        },
        [20007005] = {
          Camera = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
          Content = "哈哈，我都不好说你是天真，还是看得足够远，让我好好期待那一天的到来吧。但在那之前，该送别那一位小朋友了。",
          DialogueId = 20007005,
          FinalCamera = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DF42",
          NextDialogue = 20007006,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_Start"},Duration{2}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_End"},Duration{1}}}]],
          SpeakNpcId = 700248,
          Subtitle = "Haha, I can't decide if you're just naive or a true visionary. Either way, I'll be looking forward to that day. But for now... it's time to say goodbye to a certain little traveller.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF42"
        },
        [20007006] = {
          Camera = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
          Content = "呜呜呜，松露，你就不能留在冰湖城吗？光之魔王大人好不容易找到一个伙伴愿意和我一起大声念出自己的称号！",
          DialogueId = 20007006,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "3215DF6C",
          NextDialogue = 20007007,
          SpeakNpcId = 200002,
          Subtitle = "Boohoo... Truffle, can't you just stay? As the Demon King of Light, I finally found someone who would chant the title I gave them aloud with me, and now you're leaving so soon... Waaah!",
          TurnTo = {
            [1] = "200074:p(30)"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF6C"
        },
        [20007007] = {
          Content = "别哭呀小白，我已经出门很久啦，该回去了。再说了，那几个魔灵猎人都改行变成魔灵学者了，你可以让他们和你一起念称号呀。",
          DialogueId = 20007007,
          GUID = "3215DF96",
          NextDialogue = 20007008,
          SpeakNpcId = 200074,
          Subtitle = "Aww, don't cry, Snow. I've been away for so long — it's time for me to go home. Besides, those ex-poachers are now Geniemon researchers. You can always ask them to chant with you.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF96"
        },
        [20007008] = {
          Camera = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
          Content = "不，他们说话没有你说话好听，也不能和你一样让榛子背着我兜风。{nickname}你也别傻站着，留一留松露呀。",
          DialogueId = 20007008,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "3215DFC0",
          NextOptions = {
            [1] = 200070081
          },
          SpeakNpcId = 200002,
          Subtitle = "Nah-uh, it's not the same. They're not as sweet as you... And they definitely can't carry me on Filbert for a ride! , don't just stand there — help me convince Truffle to stay!",
          TalkActionId = {
            [1] = "700248:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFC0"
        },
        [20007009] = {
          Camera = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
          Content = "嘿嘿，以后我也会时不时来玩的。{性别：大哥哥|大姐姐}，悄悄告诉你哦，我要回去的那个很远很远的地方，其实是艾利西安传颂会。",
          DialogueId = 20007009,
          FacialId = {
            [1] = "200002:CM_Idle"
          },
          FinalCamera = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DFEA",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007010,
          SpeakNpcId = 200074,
          Subtitle = "Hehe, I'll be back to visit, I promise. And let me secretly tell you something— the faraway place I'm returning to is actually the Elysian Church.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFEA"
        },
        [20007010] = {
          Camera = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
          Content = "我收集食物时，偶尔会和榛子一起越过那些没有人看守的高山，到海伯利亚来。一开始我还有点害怕，因为传颂会和帝国一直在打仗嘛。",
          DialogueId = 20007010,
          GUID = "3215E014",
          NextDialogue = 20007011,
          SpeakNpcId = 200074,
          Subtitle = "When Filbert and I forage for food, we sometimes cross the unguarded mountain border to reach Hyperborea. At first, I was a little scared — after all, the Church and the Empire have always been at war...",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E014"
        },
        [20007011] = {
          Content = "但是遇到了{性别：大哥哥|大姐姐}后，我就不害怕了。",
          DialogueId = 20007011,
          GUID = "3215E03E",
          NextDialogue = 20007012,
          SpeakNpcId = 200074,
          Subtitle = "But after meeting you, I'm not scared anymore.",
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E03E"
        },
        [20007012] = {
          Content = "{性别：大哥哥|大姐姐}能够想出办法让魔灵和人类相处，那么就一定能让卡戎和索拉不再互相讨厌，帝国和传颂会也能不再打仗。",
          DialogueId = 20007012,
          GUID = "3215E068",
          NextDialogue = 20007013,
          SpeakNpcId = 200074,
          Subtitle = "Because if you can find a way for Geniemons and humans to become friends, then I believe one day, you'll also figure out how to make Charons and Solas friends — and maybe even the Empire and the Church too!",
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E068"
        },
        [20007013] = {
          Content = "这样一来，大家就都不会饿肚子了！",
          DialogueId = 20007013,
          GUID = "3215E092",
          NextDialogue = 20007014,
          SpeakNpcId = 200074,
          Subtitle = "And once the war stops, there will be no more hunger!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E092"
        },
        [20007014] = {
          Content = "到那时候，也请你和小白，还有卡米拉女士，一起到南方。吃粉嘟嘟的红蕈、吹烫烫的海风、看这里看不到的星星，和我在这里一样开心！等着你哦！",
          DialogueId = 20007014,
          GUID = "3215E0BC",
          NextDialogue = 20007015,
          SpeakNpcId = 200074,
          Subtitle = "When that day comes, please come and visit me in the South with Snow and Ms Camilla. I'll treat you to our pink-red mushroom called Russula, and we'll go to the beach and feel the warmth of the sea breeze, and look up at stars you can't see from here. You'll have a great time, just like I did here!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0BC"
        },
        [20007015] = {
          Content = "嗯，我会尽量做到。",
          DialogueId = 20007015,
          GUID = "3215E0E6",
          NextDialogue = 20007016,
          SpeakNpcId = 100001,
          Subtitle = "That sounds wonderful. I'll try my best to make that happen.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0E6"
        },
        [20007016] = {
          Content = "拉钩为定。",
          DialogueId = 20007016,
          GUID = "3215E110",
          NextOptions = {
            [1] = 200070161
          },
          SpeakNpcId = 200074,
          Subtitle = "Pinky swear~",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E110"
        },
        [20007017] = {
          Content = "也要和榛子拉钩。",
          DialogueId = 20007017,
          GUID = "3215E13A",
          NextDialogue = 20007018,
          SpeakNpcId = 200074,
          Subtitle = "And Filbert too!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E13A"
        },
        [20007018] = {
          Content = "榛子的蹄子太粗，拉不了勾啦。",
          DialogueId = 20007018,
          GUID = "3215E164",
          NextDialogue = 20007019,
          SpeakNpcId = 100001,
          Subtitle = "Uh, her hooves seem a little too big for a pinky swear.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E164"
        },
        [20007019] = {
          Content = "那握住它的蹄子就行。来，我们一起：拉钩上吊，一百年不许变！",
          DialogueId = 20007019,
          GUID = "3215E18E",
          NextDialogue = 20007020,
          SpeakNpcId = 200074,
          Subtitle = "Then just hold onto her hoof — it still counts! Okay, together — cross my heart, hope to die, stick a needle in my eye!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E18E"
        },
        [20007020] = {
          Content = "哼唧！",
          DialogueId = 20007020,
          GUID = "3215E1B8",
          SpeakNpcId = 200086,
          Subtitle = "Oink!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E1B8"
        },
        [20007101] = {
          Content = "我乃——冰湖城第一魔灵学者！有什么魔灵疑问，都可以问我——啊，是你啊……有……有什么事吗？",
          DialogueId = 20007101,
          GUID = "3215EF02",
          NextOptions = {
            [1] = 200071011,
            [2] = 200071012,
            [3] = 200071013
          },
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "I am Icelake's foremost Geniemon scholar! If you have any questions about them, feel free to— Oh, it's you. Uh, is—is there anything I can help you with?",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF02"
        },
        [20007102] = {
          Content = "你是说那个很聪明的魔灵吗？",
          DialogueId = 20007102,
          GUID = "3215EF2C",
          NextDialogue = 20007103,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "You mean that incredibly intelligent Geniemon?",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF2C"
        },
        [20007103] = {
          Content = "关于它的记录非常少，我也只见过那一次，听说只有受到它们的认可，才能找到他们。",
          DialogueId = 20007103,
          GUID = "3215EF56",
          NextDialogue = 20007104,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "There's very little documented about it. I've only ever seen it once myself. They say it doesn't reveal itself to just anyone. Only those it deems worthy ever get to meet it.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF56"
        },
        [20007104] = {
          Content = "不过，你应该可以顺着它们留下来的痕迹找到藏身的地方。",
          DialogueId = 20007104,
          GUID = "3215EF80",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "But you might be able to track it down by following the traces it leaves behind.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF80"
        },
        [20007105] = {
          Content = "比做魔灵猎人要好多了，每天都有许多人来问我魔灵问题，好像我真的是什么大学者一样。",
          DialogueId = 20007105,
          GUID = "3215EFAA",
          NextDialogue = 20007106,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "Much better than being a Geniemon hunter, that's for sure. People actually come to me for advice now. I almost feel like a real academic.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFAA"
        },
        [20007106] = {
          Content = "多谢你和松露手下留情，多谢多谢。",
          DialogueId = 20007106,
          GUID = "3215EFD4",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "Speaking of which, I really appreciate that you and Truffle went easy on me back then.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFD4"
        },
        [20007107] = {
          Content = "若干道深深的刻痕，似是某种尖锐物体留下的痕迹。",
          DialogueId = 20007107,
          GUID = "3215EFD5",
          Subtitle = "Several deep gouges, as if left by some jagged object."
        },
        [20007108] = {
          Content = "写着“禁区危险，严禁通行”的告示。贴了厚厚一叠，似乎是当老告示变旧了就会贴一张新告示上去。最新的一张告示落款是新历1004年，也就是二十年前——格雷姆矿场应当就是在那时彻底废弃的。",
          DialogueId = 20007108,
          GUID = "3215EFD6",
          Subtitle = "A sign reading \"Danger: No Entry\" was piled up with multiple layers, as if a new one was posted each time the old one faded. The latest was dated 1004  — twenty years ago — suggesting Glevum Pit was abandoned around that time."
        },
        [21000101] = {
          Content = "背白白进场台词（测试用）",
          DialogueId = 21000101,
          GUID = "34925112",
          TalkActionId = {
            [1] = "900005:Beibao_Start"
          }
        },
        [21000102] = {
          Content = "背白白退场台词（测试用）",
          DialogueId = 21000102,
          GUID = "3492513C",
          TalkActionId = {
            [1] = "900005:Beibao_Finish"
          }
        },
        [50000101] = {
          ContentES = "¡Eh, te hablo a ti! ¿Tienes el permiso de viaje contigo?",
          DialogueId = 50000101,
          Duration = 3,
          GUID = "7D2B8592",
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?",
          VoiceName = "voice/$Locale$/env/700002/7D2B8592"
        },
        [50000201] = {
          ContentES = "¿{性别:Un Phoxcazador|Una Phoxcazadora}? Nunca habría creído que uno de ellos llegaría a este lugar... Tú también debes tener lo necesario para convertirte en {性别:un héroe|una heroína}.",
          DialogueId = 50000201,
          Duration = 4,
          GUID = "7D2B95FA",
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          VoiceName = "voice/$Locale$/env/700003/7D2B95FA"
        },
        [50000301] = {
          ContentES = "¡Todo esto es culpa de Grandet! ¿Qué se supone que debo hacer ahora...? ¿Eh? ¿Qué miras? ¡No tengo ningún encargo para ti hoy!",
          DialogueId = 50000301,
          Duration = 3,
          GUID = "7D2BA662",
          SpeakNpcId = 700004,
          Subtitle = "D*mn it, it's all Grandet's fault! What am I supposed to do now... Hm? What are you looking at? I've got no work for you today!",
          VoiceName = "voice/$Locale$/env/700004/7D2BA662"
        },
        [50000401] = {
          ContentES = "Soy... ¿Annie?",
          DialogueId = 50000401,
          Duration = 3,
          GUID = "7D2BB6CA",
          SpeakNpcId = 700032,
          Subtitle = "My name is... Annie?",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700032/7D2BB6CA"
        },
        [50000501] = {
          ContentES = "Tan pronto como me recupere, tomaré el camino para una nueva aventura.",
          DialogueId = 50000501,
          Duration = 3,
          GUID = "7D2BC732",
          SpeakNpcId = 700005,
          Subtitle = "As soon as I'm back in form, I'm off on another adventure.",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BC732"
        },
        [50000601] = {
          ContentES = "¿Qué podría ofrecerle a mamá...? Seguramente me habrá extrañado muchísimo.",
          DialogueId = 50000601,
          Duration = 3,
          GUID = "7D2BD79A",
          SpeakNpcId = 700005,
          Subtitle = "What gift should I get for mother... She must've missed me terribly.",
          TalkActionId = {
            [1] = "700005:Think_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BD79A"
        },
        [50000701] = {
          ContentES = "¡Annie... Annie!",
          DialogueId = 50000701,
          Duration = 3,
          GUID = "7D2BE802",
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          VoiceName = "voice/$Locale$/env/700006/7D2BE802"
        },
        [50000801] = {
          ContentES = "Las flores están hermosas hoy... Debería guardar algunas para esa niña.",
          DialogueId = 50000801,
          Duration = 3,
          GUID = "7D2BF86A",
          SpeakNpcId = 700007,
          Subtitle = "The flowers today are quite lovely. I should save a few for that kid.",
          TalkActionId = {
            [1] = "700007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700007/7D2BF86A"
        },
        [50000901] = {
          ContentES = "Hola. Esta flor combina perfectamente con tu atuendo... Si ella estuviera aquí, habría dicho lo mismo.",
          DialogueId = 50000901,
          Duration = 5,
          GUID = "7D2C08D2",
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here.",
          VoiceName = "voice/$Locale$/env/700007/7D2C08D2"
        },
        [50001001] = {
          ContentES = "Con tu porte, sería una lástima no llevar mis creaciones.",
          DialogueId = 50001001,
          Duration = 3,
          GUID = "7D2C193A",
          SpeakNpcId = 700008,
          Subtitle = "Hello, gorgeous! I bet you'd be a vision in our apparel.",
          VoiceName = "voice/$Locale$/env/700008/7D2C193A"
        },
        [50001101] = {
          ContentES = "¡Los mejores frutos de nuestra tierra! ¡En ningún otro lugar encontrarás un saber hacer tan refinado!",
          DialogueId = 50001101,
          Duration = 3,
          GUID = "7D2C29A2",
          SpeakNpcId = 700009,
          Subtitle = "Try these fine fruits from our orchard — grown with unmatched cultivation techniques!",
          TalkActionId = {
            [1] = "700009:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700009/7D2C29A2"
        },
        [50001201] = {
          ContentES = "Ah... O-Oh, yo... eh...",
          DialogueId = 50001201,
          Duration = 2,
          GUID = "7D2C3A0A",
          SpeakNpcId = 700010,
          Subtitle = "Ah... whoa, I... um...",
          VoiceName = "voice/$Locale$/env/700010/7D2C3A0A"
        },
        [50001301] = {
          ContentES = "Hmm... He decidido, tú serás el sujeto de experiencia n° 1.",
          DialogueId = 50001301,
          Duration = 3,
          GUID = "7D2C4A72",
          SpeakNpcId = 700011,
          Subtitle = "Hmm... I've made up my mind — hello, Test subject No. 1!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C4A72"
        },
        [50001401] = {
          ContentES = "{nickname}, Me alegra verte. Yo sigo aprendiendo muchas cosas nuevas todos los días. Entonces... seguimos progresando juntos, ¿vale?",
          DialogueId = 50001401,
          Duration = 4,
          GUID = "7D2C5ADA",
          SpeakNpcId = 700011,
          Subtitle = ", lovely to see you again! I'm trying my best to learn new things every day, let's keep at it!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C5ADA"
        },
        [50001501] = {
          ContentES = "Tú... Charon... uno de los míos...",
          DialogueId = 50001501,
          Duration = 6,
          GUID = "7D2C6B42",
          SpeakNpcId = 700012,
          Subtitle = "You... Charon... You're one of us...",
          VoiceName = "voice/$Locale$/env/700012/7D2C6B42"
        },
        [50001601] = {
          ContentES = "He visto cosas que preferiríamos mantener en la sombra... Y los “demonios” no siempre son quienes creemos.\n...A veces, entre los Solarianos y los Charons, ya no sé cuáles son los verdaderos demonios.",
          DialogueId = 50001601,
          Duration = 4,
          GUID = "7D2C7BAA",
          SpeakNpcId = 700013,
          Subtitle = [[
I've witnessed deeds that daylight never sees, and not all are the work of "demons".
...Sometimes, between Solas and Charons, I can't tell which is the true demon.]],
          VoiceName = "voice/$Locale$/env/700013/7D2C7BAA"
        },
        [50001701] = {
          ContentES = "¡Pff! ¡Maldita idiota! ¡Veamos cuánto tiempo más puedes seguir con esta farsa!",
          DialogueId = 50001701,
          Duration = 4,
          GUID = "7D2C8C12",
          SpeakNpcId = 700014,
          Subtitle = "Pah! Stupid hag! Let's see how long you can keep this charade up!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/env/700014/7D2C8C12"
        },
        [50001801] = {
          ContentES = "¡Por todos los Cielos! ¿Cómo un ser tan dulce como yo pudo caer víctima de un espectro ladrón de inspiración?! ¡Una injusticia tal haría llorar hasta a los cielos!",
          DialogueId = 50001801,
          Duration = 4,
          GUID = "7D2C9C7A",
          SpeakNpcId = 700015,
          Subtitle = "Good grief! Who'd have thought a gentle soul like myself would be beset by an inspiration-stealing spectre?! Such wretchedness would surely draw heaven's own tears!",
          VoiceName = "voice/$Locale$/env/700015/7D2C9C7A"
        },
        [50001901] = {
          ContentES = "¡Qué pérdida de tiempo! Organizar eventos tan vacíos... ¡Sería mejor tener medio día de descanso!",
          DialogueId = 50001901,
          Duration = 3,
          GUID = "7D2CACE2",
          SpeakNpcId = 700016,
          Subtitle = "What a drag! Who arranged these pointless events? I'd rather have half a day off!",
          VoiceName = "voice/$Locale$/env/700016/7D2CACE2"
        },
        [50002001] = {
          ContentES = "“Bajo la lluvia, las flores de mamá se marchitaron... Entonces el cielo sembró pequeñas flores en los charcos, para disculparse con ella.”",
          DialogueId = 50002001,
          Duration = 3,
          GUID = "7D2CBD4A",
          NextDialogue = 50002002,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          VoiceName = "voice/$Locale$/env/700017/7D2CBD4A"
        },
        [50002002] = {
          ContentES = "¿Sabéis? Este pequeño poema se titula Disculpas, y fue escrito por uno de mis alumnos... tiene solo seis años.",
          DialogueId = 50002002,
          Duration = 3,
          GUID = "7D2CBD74",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700017/7D2CBD74"
        },
        [50002101] = {
          ContentES = "Las piedras arrojadas contra las leyes de la naturaleza siempre terminan cayendo sobre quien las lanza.",
          DialogueId = 50002101,
          Duration = 3,
          GUID = "7D2CCDB2",
          SpeakNpcId = 700018,
          Subtitle = "The rocks cast against the laws of nature will inevitably fall back on one's own head.",
          TalkActionId = {
            [1] = "700018:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/env/700018/7D2CCDB2"
        },
        [50002201] = {
          ContentES = "¿Dónde habrá podido desaparecer...?",
          DialogueId = 50002201,
          Duration = 3,
          GUID = "7D2CDE1A",
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700019/7D2CDE1A"
        },
        [50002301] = {
          ContentES = "Espero que la crema de champiñones preparada esta noche caliente un poco el corazón de la señora.",
          DialogueId = 50002301,
          Duration = 4,
          GUID = "7D2CEE82",
          SpeakNpcId = 700020,
          Subtitle = "I hope tonight's creamy mushroom soup will bring some comfort to her ladyship.",
          TalkActionId = {
            [1] = "700020:Agree"
          },
          VoiceName = "voice/$Locale$/env/700020/7D2CEE82"
        },
        [50002401] = {
          ContentES = "Pobre mujer... Ha perdido completamente la cabeza.",
          DialogueId = 50002401,
          Duration = 3,
          GUID = "7D2CFEEA",
          NextDialogue = 50002402,
          SpeakNpcId = 700023,
          Subtitle = "Poor thing, having lost her mind like that.",
          VoiceName = "voice/$Locale$/env/700023/7D2CFEEA"
        },
        [50002402] = {
          ContentES = "No es de extrañar que su hija al final se haya ido.",
          DialogueId = 50002402,
          Duration = 3,
          GUID = "7D2CFF14",
          SpeakNpcId = 700024,
          Subtitle = "No wonder her daughter had left.",
          VoiceName = "voice/$Locale$/env/700024/7D2CFF14"
        },
        [50002501] = {
          ContentES = "Todas los basureros de la ciudad están bajo mi custodia. Y créeme, ¡se encuentra de todo! Botas de ante usadas apenas dos veces, lirios todavía frescos... e incluso los fragmentos de sueños rotos de alguien.",
          DialogueId = 50002501,
          Duration = 3,
          GUID = "7D2D0F52",
          SpeakNpcId = 700115,
          Subtitle = "I oversee all the rubbish bins around the city, and oh, the treasures to be found in each of them! Nearly new deerskin boots, still-fresh lilies, and the fragments of someone's shattered dreams...",
          TalkActionId = {
            [1] = "700115:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700022/7D2D0F52"
        },
        [50002601] = {
          ContentES = "El tren para la próxima estación va a salir. ¡Boletos a la venta aquí! ¿Qué? ¿No tienes dinero? ¡Entonces deja de soñar y lárgate de aquí!",
          DialogueId = 50002601,
          Duration = 5,
          GUID = "7D2D0F53",
          SpeakNpcId = 700021,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700021:Confident_Start"
          }
        },
        [50002701] = {
          ContentES = "La tubería n° 13 está en reparación. Maldita sea... hay demasiadas ratas ahí dentro.",
          DialogueId = 50002701,
          Duration = 4,
          GUID = "7D2D3022",
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700069/7D2D3022"
        },
        [50002801] = {
          ContentES = "¡Lárgate, maldito Charon!",
          DialogueId = 50002801,
          DialoguePanelType = "{type:Bubble;style:ExcitedBubble}",
          Duration = 3,
          GUID = "7D2D408A",
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!",
          VoiceName = "voice/$Locale$/env/700068/7D2D408A"
        },
        [50002901] = {
          ContentES = "Uf... ¿por qué no se quita esta mancha de sangre?",
          DialogueId = 50002901,
          Duration = 3,
          GUID = "7D2D50F2",
          SpeakNpcId = 700067,
          Subtitle = "Ugh... these bloodstains just won't come off!",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700067/7D2D50F2"
        },
        [50003001] = {
          Content = "凶猛的狼咆哮着 撕咬着狡猾的狗",
          DialogueId = 50003001,
          Duration = 3,
          GUID = "7D2D615A",
          NextDialogue = 50003002,
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D615A"
        },
        [50003002] = {
          Content = "狡猾的狗呜咽着 啃食着腐朽的肉",
          DialogueId = 50003002,
          Duration = 3,
          GUID = "7D2D6184",
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D6184"
        },
        [50003101] = {
          Content = "您也喜欢这些百合吗？",
          DialogueId = 50003101,
          Duration = 3,
          GUID = "7D2D71C2",
          SpeakNpcId = 700072,
          TalkActionId = {
            [1] = "700072:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700072/7D2D71C2"
        },
        [50003201] = {
          ContentES = "♪ “Monstruos más allá de las murallas se alimentan de nuestra carne; los de adentro nos esquilan. Mientras los sabuesos festejan con pan blanco fino; nosotros, humildes ovejas, nos contentamos con masticar hierba...”",
          DialogueId = 50003201,
          Duration = 3,
          GUID = "7D2D822A",
          NextDialogue = 50003202,
          SpeakNpcId = 700073,
          Subtitle = "♪ \"Monsters beyond the walls feast on our flesh; the ones within shear our fleece. While the hounds dine on fine white loaves; we lowly sheep are content with chewing grass...\"",
          TalkActionId = {
            [1] = "700073:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700073/7D2D822A"
        },
        [50003202] = {
          ContentES = "¡Dios mío! ¿Dónde aprendiste esta canción...? ¡Un día nos hará ejecutar a los dos!",
          DialogueId = 50003202,
          Duration = 3,
          GUID = "7D2D8254",
          NextDialogue = 50003203,
          SpeakNpcId = 700074,
          Subtitle = "Whoa, whoa! Where did you learn that ditty... you're going to get us both killed one of these days!",
          TalkActionId = {
            [1] = "700074:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D8254"
        },
        [50003203] = {
          ContentES = "¡Oh! {性别:Estimado cliente|Estimada cliente}, ¿desea comprar algo? ¡Todo aquí está hecho a mano por mí, calidad impecable garantizada!",
          DialogueId = 50003203,
          Duration = 3,
          GUID = "7D2D827E",
          SpeakNpcId = 700074,
          Subtitle = "Ah, welcome! What can I get you, dear customer? Each piece here is crafted by my own hands, top-notch quality guaranteed!",
          TalkActionId = {
            [1] = "700074:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D827E"
        },
        [50003301] = {
          Content = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
          DialogueId = 50003301,
          Duration = 3,
          GUID = "7D2D9292",
          SpeakNpcId = 700075,
          TalkActionId = {
            [1] = "700075:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/env/700075/7D2D9292"
        },
        [50003401] = {
          Content = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
          DialogueId = 50003401,
          Duration = 3,
          GUID = "7D2DA2FA",
          SpeakNpcId = 700076,
          TalkActionId = {
            [1] = "700076:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700076/7D2DA2FA"
        },
        [50003501] = {
          Content = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
          DialogueId = 50003501,
          Duration = 3,
          GUID = "7D2DB362",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2DB362"
        },
        [50003601] = {
          Content = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
          DialogueId = 50003601,
          Duration = 3,
          GUID = "7D2DC3CA",
          NextDialogue = 50003602,
          SpeakNpcId = 700078,
          TalkActionId = {
            [1] = "700078:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700078/7D2DC3CA"
        },
        [50003602] = {
          Content = "子爵大人要最好的皮料！要从最健壮的头狼身上剥下的顶级货！懂了吗蠢蛋！你的这些残次品只配给乞丐穿！",
          DialogueId = 50003602,
          Duration = 3,
          GUID = "7D2DC3F4",
          SpeakNpcId = 700079,
          TalkActionId = {
            [1] = "700079:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700079/7D2DC3F4"
        },
        [50003701] = {
          ContentES = "¡Palomitas! ¡Cigarrillos! ¡Bebidas alcohólicas! ¿Ha perdido algo? ¡Yo no vi nada! ¡Lo juro!",
          DialogueId = 50003701,
          Duration = 4,
          GUID = "7D2DD432",
          SpeakNpcId = 700080,
          Subtitle = "Popcorn! Cigs! Booze! Lost something, you say? Didn't see it! I swear!",
          VoiceName = "voice/$Locale$/env/700080/7D2DD432"
        },
        [50003801] = {
          ContentES = "Si cada Charon pudiera vivir tanto como yo... no estaría tan sola.",
          DialogueId = 50003801,
          Duration = 7,
          GUID = "7D2DE49A",
          SpeakNpcId = 700081,
          Subtitle = "If every Charon could live as long as I have, I wouldn't feel so alone.",
          VoiceName = "voice/$Locale$/env/700081/7D2DE49A"
        },
        [50003901] = {
          ContentES = "No se fíen de mi brazo roto, aún puedo transportar mercancías. ¿Qué necesitan?",
          DialogueId = 50003901,
          Duration = 3,
          GUID = "7D2DF502",
          SpeakNpcId = 700082,
          Subtitle = "Welcome! And don't worry about my broken arm — I can still get you anything you need. So, what will it be?",
          TalkActionId = {
            [1] = "700082:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700082/7D2DF502"
        },
        [50004001] = {
          ContentES = "... (Lunoeggy escribe rápidamente “Hola” en su pequeña pizarra.)",
          DialogueId = 50004001,
          Duration = 3,
          GUID = "7D2E056A",
          SpeakNpcId = 900008,
          Subtitle = "... (Lunoeggy quickly scribbles \"Hello\" on the board.)",
          VoiceName = "voice/$Locale$/env/900008/7D2E056A"
        },
        [50004101] = {
          ContentES = "He aceptado un nuevo encargo recientemente. Como siempre: 80 para ti, 20 para mí. Partimos en cuanto termine esta botella, ¿te parece?",
          DialogueId = 50004101,
          Duration = 3,
          GUID = "7D2E15D2",
          SpeakNpcId = 200015,
          Subtitle = "I've yet again been commissioned recently. Let's go with the usual 80-20 split and head out after I finish this bottle. What do you say?",
          TalkActionId = {
            [1] = "200015:Agree"
          },
          VoiceName = "voice/$Locale$/env/200015/7D2E15D2"
        },
        [50004201] = {
          ContentES = "¿Ganas de una copa?",
          DialogueId = 50004201,
          Duration = 3,
          GUID = "7D2E263A",
          SpeakNpcId = 200003,
          Subtitle = "Care for a drink?",
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_01"
        },
        [50004301] = {
          ContentES = "♪ “Ruiseñor de alas rotas, no llores más…”",
          DialogueId = 50004301,
          Duration = 3,
          GUID = "7D2E36A2",
          NextDialogue = 50004302,
          SpeakNpcId = 700142,
          Subtitle = "♪ \"Nightingale, broken wings, you can weep you can sleep...\"",
          TalkActionId = {
            [1] = "700142:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36A2"
        },
        [50004302] = {
          ContentES = "♪ “Querido pequeño ruiseñor, no te duermas para siempre…”",
          DialogueId = 50004302,
          Duration = 3,
          GUID = "7D2E36CC",
          SpeakNpcId = 700142,
          Subtitle = "♪ \"Nightingale, rise above, you will free you will see...\"",
          TalkActionId = {
            [1] = "700142:Explain02_End"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36CC"
        },
        [50004401] = {
          ContentES = "Vete... vete ya... si no vas a comprar Phoxene, no te quedes aquí... y no atraigas a esos malditos soldados hacia mí...",
          DialogueId = 50004401,
          Duration = 4,
          GUID = "7D2E470A",
          SpeakNpcId = 700113,
          Subtitle = "S-Scoot if you ain't buying any Phoxene... Lest your presence draws the soldiers' attention to us...",
          TalkActionId = {
            [1] = "700113:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700113/7D2E470A"
        },
        [50004501] = {
          ContentES = "¡Baila! ¡Vamos, baila! ¡La vida no tiene sentido, así que tira todas tus preocupaciones al basurero y baila conmigo hasta el amanecer!",
          DialogueId = 50004501,
          Duration = 3,
          GUID = "7D2E5772",
          SpeakNpcId = 700129,
          Subtitle = "Dance! Find your own groove! What's the meaning of life, you ask? Into the bin with all the stress and the fuss, and let's dance the night away!",
          VoiceName = "voice/$Locale$/env/700129/7D2E5772"
        },
        [50004601] = {
          ContentES = "Señor... La asignación imperial de este mes... Ah, aún no ha sido aprobada... *tos* *tos*... No importa, voy a adelantar el dinero de mi bolsillo... Perdón por las molestias...",
          DialogueId = 50004601,
          Duration = 4,
          GUID = "7D2E67DA",
          SpeakNpcId = 700070,
          Subtitle = "Sir, about this month's Imperial pension... Oh, you haven't received approval for that yet? *cough* *cough*... It's okay, I'll put my own money down first... Sorry to trouble you...",
          TalkActionId = {
            [1] = "700070:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700070/7D2E67DA"
        },
        [50004701] = {
          ContentES = "¡Valora la información, nunca te pierdas la emoción!",
          DialogueId = 50004701,
          Duration = 3,
          GUID = "7D2E7842",
          SpeakNpcId = 700048,
          Subtitle = "Treasure the intel, never miss the thrill!",
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E7842"
        },
        [50004801] = {
          ContentES = "¡La asociación de pescadores está reclutando! ¡Ven a lanzar el anzuelo con nosotros!",
          DialogueId = 50004801,
          Duration = 3,
          GUID = "7D2E88AA",
          SpeakNpcId = 700048,
          Subtitle = "Come join the Fishermen's Mutual Aid Society, let's hook the fun!",
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E88AA"
        },
        [50004901] = {
          ContentES = "¡Mientras esté bien desinfectado, será un platillo sabroso!",
          DialogueId = 50004901,
          Duration = 3,
          GUID = "7D2E9912",
          SpeakNpcId = 700116,
          Subtitle = "Properly disinfected, it can become a delicious dish!",
          TalkActionId = {
            [1] = "700116:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700116/7D2E9912"
        },
        [50005001] = {
          ContentES = "Pff. Una cara nueva.",
          DialogueId = 50005001,
          Duration = 3,
          GUID = "7D2EA97A",
          SpeakNpcId = 700096,
          Subtitle = "Ugh, new face.",
          TalkActionId = {
            [1] = "700096:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EA97A"
        },
        [50005101] = {
          ContentES = "¿Qué quieres?",
          DialogueId = 50005101,
          Duration = 3,
          GUID = "7D2EB9E2",
          SpeakNpcId = 700096,
          Subtitle = "What do you want?",
          TalkActionId = {
            [1] = "700096:Agree"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EB9E2"
        },
        [50005201] = {
          ContentES = "Ser fiel a sus deseos... fiel a sus deseos... fiel a sus deseos... Pero, ¿qué significa exactamente ser fiel a sus deseos...?",
          DialogueId = 50005201,
          Duration = 4,
          GUID = "7D2ECA4A",
          SpeakNpcId = 700077,
          Subtitle = "Stay true to yourself. stay true to yourself... Ugh, what am I supposed to do to stay true to myself... ",
          TalkActionId = {
            [1] = "700077:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2ECA4A"
        },
        [50005301] = {
          Content = "开往下一站的列车即将出发，如有购票需求请您在此处办理——什么？没钱？那就一边儿去！",
          DialogueId = 50005301,
          Duration = 4,
          GUID = "7D2D1FBA",
          SpeakNpcId = 700147,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700147:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700021/7D2D1FBA"
        },
        [50005401] = {
          ContentES = "¡Jajaja! ¡Corre más rápido que un ratón, vaya!",
          DialogueId = 50005401,
          Duration = 3,
          GUID = "7D2EEB1A",
          SpeakNpcId = 700089,
          Subtitle = "Hahaha, she's running so fast, faster than a mouse!"
        },
        [50005501] = {
          ContentES = "¡Eh, maldito Charon, ¿qué esperas? ¡Ve a alcanzar a tu pequeño mocoso!",
          DialogueId = 50005501,
          Duration = 3,
          GUID = "7D2EFB82",
          SpeakNpcId = 700088,
          Subtitle = "Stinky Charon, what are you waiting for? Go after your little brat!",
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [50005601] = {
          ContentES = "Tal vez necesitaríamos una pizarra un poco más grande, ¿no...?",
          DialogueId = 50005601,
          Duration = 3,
          GUID = "7D2F0BEA",
          SpeakNpcId = 700143,
          Subtitle = "Should we get a bigger board..."
        },
        [50100101] = {
          Content = "针头线脑，香脂香囊，走过路过不要错过——",
          DialogueId = 50100101,
          GUID = "7D6B9BD2",
          Subtitle = "Needles, thread, balsams and sachets — does anything catch your eye?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6B9BD2"
        },
        [50100201] = {
          Content = "来看看华胥特色纪念品喽，给亲朋好友带一份吧！",
          DialogueId = 50100201,
          GUID = "7D6BAC3A",
          Subtitle = "Come, have a look! Fine souvenirs of Huaxu — take one home for your dear ones!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BAC3A"
        },
        [50100301] = {
          Content = "海的那边……是什么样子呢？",
          DialogueId = 50100301,
          GUID = "7D6BBCA2",
          Subtitle = "I wonder... what the world beyond the sea is like.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBCA2"
        },
        [50100311] = {
          Content = "工头昨天心情好，给我们都发了赏钱！",
          DialogueId = 50100311,
          GUID = "7D6BBE46",
          Subtitle = "The foreman was in a good mood yesterday — he even slipped us a little bonus.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE46"
        },
        [50100312] = {
          Content = "那有什么！出船之前，老板来请吃了茶呢！",
          DialogueId = 50100312,
          GUID = "7D6BBE70",
          Subtitle = "Ha! That's nothing — the boss treated us to tea before we set off.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE70"
        },
        [50100401] = {
          Content = "腰酸背痛啊，抽空得找人好好按按……",
          DialogueId = 50100401,
          GUID = "7D6BCD0A",
          Subtitle = "Ugh, my back's killing me. Gotta get someone to work the knots out one of these days...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BCD0A"
        },
        [50100501] = {
          Content = "这箱货物贵重，先包上一层软垫再搬吧。",
          DialogueId = 50100501,
          GUID = "7D6BDD72",
          Subtitle = "Careful with that crate — it's pricey. Wrap it in something soft before we move it.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BDD72"
        },
        [50100601] = {
          Content = "这些木簪花钿，好看是好看，可我不会用呢。",
          DialogueId = 50100601,
          GUID = "7D6BEDDA",
          Subtitle = "These embossed hairpins are gorgeous... but I've no idea how to wear them right.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BEDDA"
        },
        [50100701] = {
          Content = "香料丝绸茶叶油膏器皿……种类也太多了！",
          DialogueId = 50100701,
          GUID = "7D6BFE42",
          Subtitle = "Incense, silks, teas, oils, salves, fine wares... where do I even start?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BFE42"
        },
        [50100801] = {
          Content = "沉月香卖完了？怎么可能，昨天才进的货！",
          DialogueId = 50100801,
          GUID = "7D6C0EAA",
          Subtitle = "Out of Lunarose already? That can't be right — it just came in yesterday!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C0EAA"
        },
        [50100901] = {
          Content = "点数清，码数齐，今日开市不慌矣~",
          DialogueId = 50100901,
          GUID = "7D6C1F12",
          Subtitle = "All tallied, all tidy — looks like a smooth start today~",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C1F12"
        },
        [50101001] = {
          Content = "不愧是织星客的故乡，华胥果真名不虚传。",
          DialogueId = 50101001,
          GUID = "7D6C2F7A",
          Subtitle = "So this is where the Starweavers hail from... Huaxu really does live up to its name.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C2F7A"
        },
        [50101101] = {
          Content = "山清水秀，在此品一盏香茗，妙趣横生呐~",
          DialogueId = 50101101,
          GUID = "7D6C3FE2",
          Subtitle = "Such a fine view... a cup of fragrant tea here would be pure delight.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C3FE2"
        },
        [50101201] = {
          Content = "说好打赌输了就欠我三根糖葫芦，你不许耍赖。",
          DialogueId = 50101201,
          GUID = "7D6C504A",
          Subtitle = "A bet's a bet! You lost, so you owe me three tanghulu skewers. No backsies!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C504A"
        },
        [50101202] = {
          Content = "放心，明日阿娘给了零花钱就来请你！",
          DialogueId = 50101202,
          GUID = "7D6C5074",
          Subtitle = "All right, all right — I'll get them for you when I've got my spending money tomorrow!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C5074"
        },
        [50101203] = {
          Content = "浮星埠是一年比一年热闹了啊……",
          DialogueId = 50101203,
          GUID = "7D6C509E",
          Subtitle = "Starwharf grows busier by the year.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C509E"
        },
        [50101301] = {
          Content = "诶呀！撞得我发髻都散啦！",
          DialogueId = 50101301,
          GUID = "7D6C60B2",
          Subtitle = "Oof! You knocked my hair loose!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C60B2"
        },
        [50101401] = {
          Content = "嘿！小友走路别分心，撞到人可不好！",
          DialogueId = 50101401,
          GUID = "7D6C711A",
          Subtitle = "Watch where you're going, young friend — don't go barging into people like that.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C711A"
        },
        [50101501] = {
          Content = "绸缎齐整，杂粮归铺，心才安……",
          DialogueId = 50101501,
          GUID = "7D6C8182",
          Subtitle = "Silks in place, grain stacked neatly — only then can a man rest easy.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C8182"
        },
        [50101601] = {
          Content = "祖传山参，百年阿胶，价优物美待君选！",
          DialogueId = 50101601,
          GUID = "7D6C91EA",
          Subtitle = "Finest ginseng and aged donkey-hide gelatin — fair prices! Come have a look!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C91EA"
        },
        [50101701] = {
          Content = "好东西不贱卖哈，总有眼尖识货人！",
          DialogueId = 50101701,
          GUID = "7D6CA252",
          Subtitle = "Quality doesn't come cheap — those with taste know it's worth the coin.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CA252"
        },
        [50101801] = {
          Content = "瓷器娇贵，客人轻拿轻放~",
          DialogueId = 50101801,
          GUID = "7D6CB2BA",
          Subtitle = "Careful now — fine porcelain. Easy does it, dear customer.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CB2BA"
        },
        [50101901] = {
          Content = "再便宜点，我直接拿了。",
          DialogueId = 50101901,
          GUID = "7D6CC322",
          Subtitle = "Knock a little off and I'll take it right now.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CC322"
        },
        [50102001] = {
          Content = "瓶子看着精致……没什么瑕疵吧？",
          DialogueId = 50102001,
          GUID = "7D6CD38A",
          Subtitle = "Lovely vase... no cracks or chips, right?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CD38A"
        },
        [50102101] = {
          Content = "称点桂花糕，我带回去给娘子吃~",
          DialogueId = 50102101,
          GUID = "7D6CE3F2",
          Subtitle = "A few osmanthus cakes, please. They're my wife's favorite.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CE3F2"
        },
        [50102201] = {
          Content = "这匹布料柔软顺滑，做成里衣定是舒适。",
          DialogueId = 50102201,
          GUID = "7D6CF45A",
          Subtitle = "This fabric's soft and smooth — it'll make a fine lining, that's for sure.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CF45A"
        },
        [50102301] = {
          Content = "神君鉴上，我雪霁立誓一生不负初晴，如……",
          DialogueId = 50102301,
          GUID = "7D6D04C2",
          Subtitle = "By Lord Argent as my witness, I, Xueji, swear never to fail Chuqing, or I'll—",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D04C2"
        },
        [50102401] = {
          Content = "嘘！后面的话不许你说！我都明白……",
          DialogueId = 50102401,
          GUID = "7D6D152A",
          Subtitle = "Uh-uh! Don't say it! I know...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D152A"
        },
        [50102501] = {
          Content = "白龙神君保佑此次出航平安无虞！",
          DialogueId = 50102501,
          GUID = "7D6D2592",
          Subtitle = "May Lord Argent grant this voyage fair winds and safe seas!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D2592"
        },
        [50102601] = {
          Content = "小女愿家中长辈身体康健，福寿绵长。",
          DialogueId = 50102601,
          GUID = "7D6D35FA",
          Subtitle = "May Lord Argent bless my family with good health and long, peaceful years.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D35FA"
        },
        [50102701] = {
          Content = "明先生最近可是在哪发了大财？",
          DialogueId = 50102701,
          GUID = "7D6D4662",
          Subtitle = "It's been a while, Ming. Been turning a decent profit lately?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D4662"
        },
        [50102702] = {
          Content = "侥幸而已！还是江先生的生意更稳当。",
          DialogueId = 50102702,
          GUID = "7D6D468C",
          Subtitle = "Ha! Pure luck, that's all. Your business runs steadier than mine any day.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D468C"
        },
        [50102801] = {
          Content = "下次出航得往赫墨北边再走一走……",
          DialogueId = 50102801,
          GUID = "7D6D56CA",
          Subtitle = "Next trip, I'll head a bit farther north of Khemet — see what's there.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D56CA"
        },
        [50102901] = {
          Content = "明明已经让了极大的利，为何销量还是……",
          DialogueId = 50102901,
          GUID = "7D6D6732",
          Subtitle = "I've slashed prices to the bone — why aren't sales picking up...?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D6732"
        },
        [50103001] = {
          Content = "我才加入织星客，凡事劳请前辈多指点！",
          DialogueId = 50103001,
          GUID = "7D6D779A",
          Subtitle = "I'm new to the Starweavers — I'll be relying on your guidance.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D779A"
        },
        [50103002] = {
          Content = "客气了，若有问题便尽管问吧。",
          DialogueId = 50103002,
          GUID = "7D6D77C4",
          Subtitle = "You're too kind. Feel free to ask anything.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77C4"
        },
        [50103003] = {
          Content = "您说我是要继续追资还是见好就收呢？",
          DialogueId = 50103003,
          GUID = "7D6D77EE",
          Subtitle = "What do you think, then — double down, or cut my losses while I still can?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77EE"
        },
        [50103101] = {
          Content = "新来的哥儿，皮子肥不肥？",
          DialogueId = 50103101,
          GUID = "7D6D8802",
          Subtitle = "New face, eh? Do you think he's got any silver?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D8802"
        },
        [50103201] = {
          Content = "穷地方来的，没挂多少老居米子。",
          DialogueId = 50103201,
          GUID = "7D6D986A",
          Subtitle = "From a poor patch, him. Don't think he can rub two coins together.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D986A"
        },
        [50103301] = {
          Content = "客人来看看？爬山头来的正经古董。",
          DialogueId = 50103301,
          GUID = "7D6DA8D2",
          Subtitle = "Have a look, friend — authentic antiques, fresh off the dig.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DA8D2"
        },
        [50103401] = {
          Content = "以前都只做洋庄，好不容易才运回国的！",
          DialogueId = 50103401,
          GUID = "7D6DB93A",
          Subtitle = "These pieces once went straight to foreign buyers. Took work and coin to bring them back!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DB93A"
        },
        [50103501] = {
          Content = "风里有太皓的意志，只需静下心感受……",
          DialogueId = 50103501,
          GUID = "7D6DC9A2",
          Subtitle = "The wind carries Taihao's will. Be still, and you'll feel it.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DC9A2"
        },
        [50103601] = {
          Content = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
          DialogueId = 50103601,
          GUID = "7D6DDA0A",
          SpeakNpcId = 701039,
          Subtitle = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DDA0A"
        }
      }
    end
  },
  {
    MinKey = 50103701,
    MaxKey = 50107215,
    Loader = function()
      return {
        [50103701] = {
          Content = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
          DialogueId = 50103701,
          GUID = "7D6DEA72",
          SpeakNpcId = 701040,
          Subtitle = "Souvenirs for travellers! First time to Huaxu? Don't pass me by — sachets, folding fans, curios, trinkets, all the little treasures you could want!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DEA72"
        },
        [50103801] = {
          Content = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
          DialogueId = 50103801,
          GUID = "7D6DFADA",
          SpeakNpcId = 701041,
          Subtitle = "Folks, lend me your ears for a moment — let me tell you the thousand-year tale of our very own Starwharf! Just as trade should be fair and square, so too should our past — plain and open for all to see.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DFADA"
        },
        [50103901] = {
          Content = "您可听好了，这大风九章的第一章就是：戕身害命，不可为也。",
          DialogueId = 50103901,
          GUID = "7D6E0B42",
          SpeakNpcId = 701044,
          Subtitle = "Listen well. The first of the Nine Chapters says: \"To wound or kill — this must not be done.\"",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E0B42"
        },
        [50104001] = {
          Content = "怎么样才能长出角呢，我揪……我揪……嗷！好痛……",
          DialogueId = 50104001,
          GUID = "7D6E1BAA",
          SpeakNpcId = 701045,
          Subtitle = "How do I make my horns grow? Maybe if I give them a little tug... ow! That hurts!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E1BAA"
        },
        [50104101] = {
          Content = "没想到成为织星客还有如此多的便利！百年春真是家大业大啊。",
          DialogueId = 50104101,
          GUID = "7D6E2C12",
          SpeakNpcId = 701046,
          Subtitle = "I never realized being a Starweaver came with so many perks. EverSpring truly is remarkable.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E2C12"
        },
        [50104201] = {
          Content = "盖个会客厅怎么样？要不再加个小厨房？",
          DialogueId = 50104201,
          GUID = "7D6E3C7A",
          SpeakNpcId = 701048,
          Subtitle = "How about adding a reception hall? Or perhaps a small kitchen?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E3C7A"
        },
        [50104301] = {
          Content = "爬到月亮上？咱们爬得上去吗？",
          DialogueId = 50104301,
          GUID = "7D6E4CE2",
          SpeakNpcId = 701050,
          Subtitle = "Climb all the way to the moon? There's no way we can do that!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E4CE2"
        },
        [50104401] = {
          Content = "嚯，这块千星板的年岁可真够久了！",
          DialogueId = 50104401,
          GUID = "7D6E5D4A",
          SpeakNpcId = 701051,
          Subtitle = "Ah... this Stellapass — now that's a piece of history!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E5D4A"
        },
        [50104501] = {
          Content = "不以利丰为荣，以义为荣；不以豪奢为高，以德为高……",
          DialogueId = 50104501,
          GUID = "7D6E6DB2",
          SpeakNpcId = 701052,
          Subtitle = "Count not profit but righteousness as honour; count not splendour but virtue as nobility...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E6DB2"
        },
        [50104601] = {
          Content = "如若对百年春业务相关有所疑问，可至此处问询。",
          DialogueId = 50104601,
          GUID = "7D6E7E1A",
          SpeakNpcId = 701054,
          Subtitle = "If you have any enquiries regarding EverSpring's services, you may speak to me here.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E7E1A"
        },
        [50104701] = {
          Content = "昨天到港的北风莓酱，怎么现在还没通过检查！快把货给我！",
          DialogueId = 50104701,
          GUID = "7D6E8E82",
          SpeakNpcId = 701057,
          Subtitle = "The Borealberry jam that came in yesterday — why is it still held up in inspection? I need my goods, and I need them now!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E8E82"
        },
        [50104801] = {
          Content = "回家……可是，我的家又在哪里？这里……又是什么地方？",
          DialogueId = 50104801,
          GUID = "7D6E9EEA",
          SpeakNpcId = 701059,
          Subtitle = "Home... but where is it? And where am I...?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E9EEA"
        },
        [50104901] = {
          Content = "敕愿亡魂，早离迷茫，急急如律，往生乐乡……",
          DialogueId = 50104901,
          GUID = "7D6EAF52",
          SpeakNpcId = 701060,
          Subtitle = "By vow and decree we summon the lost: Cease your wandering; hasten unto the Realm of Bliss...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EAF52"
        },
        [50105001] = {
          Content = "如果爷爷回来看我的话，就让叶子落在我的头上吧！",
          DialogueId = 50105001,
          GUID = "7D6EBFBA",
          SpeakNpcId = 701061,
          Subtitle = "Grandpa! If you're really back, make a leaf fall on my head!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EBFBA"
        },
        [50105101] = {
          Content = "这棵树，一直在说话！",
          DialogueId = 50105101,
          GUID = "7D6ED022",
          SpeakNpcId = 701063,
          Subtitle = "This tree! It keeps talking!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6ED022"
        },
        [50105201] = {
          Content = "你也是从外面过来的？",
          DialogueId = 50105201,
          GUID = "7D6EE08A",
          SpeakNpcId = 701065,
          Subtitle = "You're from outside too... aren't you?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EE08A"
        },
        [50105301] = {
          Content = "小鬼，微茫市可不是你随便乱逛的地方。",
          DialogueId = 50105301,
          GUID = "7D6EF0F2",
          SpeakNpcId = 701066,
          Subtitle = "Oi, kid — Haze Market isn't the sort of place you just stroll into for fun.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EF0F2"
        },
        [50105401] = {
          Content = "这缝儿得趁早补，再泡些日子，木芯都得烂透咯。",
          DialogueId = 50105401,
          GUID = "7D6F015A",
          SpeakNpcId = 701067,
          Subtitle = "Best patch that seam up soon... leave her soaking a few more months and the core'll rot clean through.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F015A"
        },
        [50105501] = {
          Content = "呼……呼……",
          DialogueId = 50105501,
          GUID = "7D6F11C2",
          SpeakNpcId = 701071,
          Subtitle = "Huff... Huff...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F11C2"
        },
        [50105601] = {
          Content = "一会冷一会热……想当年我太姥姥还跟我说，这里是个春暖花开的好地方呢！",
          DialogueId = 50105601,
          GUID = "7D6F222A",
          SpeakNpcId = 701072,
          Subtitle = "Hot one minute, freezing the next... My great-grandmother always said it used to be spring all year round.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F222A"
        },
        [50105701] = {
          Content = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
          DialogueId = 50105701,
          GUID = "7D6F3292",
          SpeakNpcId = 701073,
          Subtitle = "Here we are! Once I light the incense, Lord Argent will surely descend and wipe that wicked beast out for good — just like in the old tales!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F3292"
        },
        [50105801] = {
          Content = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
          DialogueId = 50105801,
          GUID = "7D6F42FA",
          SpeakNpcId = 701042,
          Subtitle = "The Stellapass is running fine. Come to think of it, it's about due for its next maintenance...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F42FA"
        },
        [50105901] = {
          Content = "龙老板，好久不见，新到的银针要尝尝吗，香的嘞~",
          DialogueId = 50105901,
          GUID = "7D6F5362",
          SpeakNpcId = 701055,
          Subtitle = "Long, it's been a while. Care to try the new Silver Needle? The fragrance is exquisite~",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F5362"
        },
        [50106001] = {
          Content = "到底是什么时候就在这里的呢？",
          DialogueId = 50106001,
          GUID = "7D6F63CA",
          SpeakNpcId = 701062,
          Subtitle = "Hmm... I wonder how long this tree has been standing here.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F63CA"
        },
        [50106101] = {
          Content = "最近微茫市来了些新面孔，买卖时闲话许多，上不得台面。",
          DialogueId = 50106101,
          GUID = "7D6F7432",
          SpeakNpcId = 701068,
          Subtitle = "Quite a few new faces in Haze Market of late — far too chatty when they trade. No class whatsoever.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F7432"
        },
        [50106201] = {
          Content = "下次和虬先生约见之时，定要选个风雅茶楼，而不是这种……",
          DialogueId = 50106201,
          GUID = "7D6F849A",
          SpeakNpcId = 701070,
          Subtitle = "Next time I meet Mr Qiu, it'll have to be somewhere respectable — a proper teahouse, not... whatever this place is.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F849A"
        },
        [50106301] = {
          Content = "福运蛋上新款式啦，要不要来扭一发试试？",
          DialogueId = 50106301,
          Duration = 5,
          GUID = "7D6F9502",
          SpeakNpcId = 900012,
          Subtitle = "New Lucky Egg variants just dropped! Fancy giving one a spin?"
        },
        [50107001] = {
          Content = "我的钱袋子呢？我的钱袋子怎么不见了？",
          DialogueId = 50107001,
          GUID = "7D7007DA",
          Subtitle = "Where's my purse!? I had it a second ago..."
        },
        [50107002] = {
          Content = "定是那油嘴滑舌的小贩子偷的！",
          DialogueId = 50107002,
          GUID = "7D700804",
          Subtitle = "I'll wager it was that fast-talking hawker."
        },
        [50107003] = {
          Content = "诶？怎么就是找不到呢？",
          DialogueId = 50107003,
          GUID = "7D70082E",
          Subtitle = "Hmm... where could it be?"
        },
        [50107004] = {
          Content = "我早跟你说了这街上有贼，之前有人看到了，一个小女孩，皮肤黑黢黢的！",
          DialogueId = 50107004,
          GUID = "7D700858",
          Subtitle = "Told you — there are pickpockets about on this street. Someone saw a little girl earlier — face all smeared with grime."
        },
        [50107005] = {
          Content = "博山香行周年店庆，来店订购香料满十赠五~",
          DialogueId = 50107005,
          GUID = "7D700882",
          Subtitle = "Boshan Incense House anniversary offer! Buy ten, get five free!"
        },
        [50107006] = {
          Content = "你要知道一点——我对香料品质的要求很高，晒得太干我不要，香味散得太过我也不要。",
          DialogueId = 50107006,
          GUID = "7D7008AC",
          Subtitle = "Just so we're clear: I'm very particular about incense. If it's too dry, I won't take it. And if the scent fades too fast, I'm not interested either."
        },
        [50107007] = {
          Content = "之前定的那批香料，品质相当不错，这次就按原先的订单再来一批，还是送到我家中。",
          DialogueId = 50107007,
          GUID = "7D7008D6",
          Subtitle = "The incense you sent last time was excellent. I'll have more of the same — delivered to my house again."
        },
        [50107008] = {
          Content = "噫！好酸的果干！",
          DialogueId = 50107008,
          GUID = "7D700900",
          Subtitle = "Ugh! That's really sour!"
        },
        [50107009] = {
          Content = "为什么没人来试试我做的糕点呢……难道是卖相不太好？可是味道很香呀……",
          DialogueId = 50107009,
          GUID = "7D70092A",
          Subtitle = "Why won't anyone try my pastries...? Is it the way they look? But they smell amazing..."
        },
        [50107010] = {
          Content = "华胥特色小吃，吃一口念一年！",
          DialogueId = 50107010,
          GUID = "7D700954",
          Subtitle = "Huaxu special snacks! One bite and you'll be back for more!"
        },
        [50107011] = {
          Content = "各色果干，酸甜可口，欢迎试吃品尝~",
          DialogueId = 50107011,
          GUID = "7D70097E",
          Subtitle = "Candied fruit! Sweet and tangy — plenty to choose from! Free samples — have a taste!"
        },
        [50107012] = {
          Content = "那里曾是家布鞋店，现在却已经改成了木雕摊……东市啊，大变样咯！",
          DialogueId = 50107012,
          GUID = "7D7009A8",
          Subtitle = "That used to be a little cloth-shoe shop. Now look at it — a woodcarver's stall... East Market's changed so much."
        },
        [50107013] = {
          Content = "这位客人，看你身材匀称，要不要来试试我们千绣阁里的成衣？",
          DialogueId = 50107013,
          GUID = "7D7009D2",
          Subtitle = "Good day! You'd look lovely in our designs. Fancy trying something on at Qianxiu Pavilion?"
        },
        [50107014] = {
          Content = "同福饭馆菜品上新，外域高人指点，香料入菜，佳肴更添新风味。",
          DialogueId = 50107014,
          GUID = "7D7009FC",
          Subtitle = "New dishes at Tongfu Eatery! Incense in the cooking — an aroma you've never tasted before! A secret technique taught by a master chef from distant lands!"
        },
        [50107015] = {
          Content = "香料做菜？听起来奇奇怪怪的，这做出来的东西能好吃吗？",
          DialogueId = 50107015,
          GUID = "7D700A26",
          Subtitle = "Incense... in food? That can't be right. Who'd think that tastes good?"
        },
        [50107016] = {
          Content = "同福饭馆的厨子发了疯，居然把莞婆娘碾碎包进丸子里！",
          DialogueId = 50107016,
          GUID = "7D700A50",
          Subtitle = "The chef at Tongfu Eatery's lost his mind! He's crushed up Wan Beetles and stuffed them into the meatballs!"
        },
        [50107017] = {
          Content = "一天到晚就知道折腾看似新颖实则无用的花招，可别忘了华胥美食的精髓是什么！",
          DialogueId = 50107017,
          GUID = "7D700A7A",
          Subtitle = "All sparkle, no substance. Have they forgotten what Huaxu cooking's really about!?"
        },
        [50107018] = {
          Content = "秀芳……不要离开我……秀芳……",
          DialogueId = 50107018,
          GUID = "7D700AA4",
          Subtitle = "Xiufang... don't leave me... Xiufang..."
        },
        [50107019] = {
          Content = "把翠屏雀搬来了皓京城？！还有此等奇事！",
          DialogueId = 50107019,
          GUID = "7D700ACE",
          Subtitle = "They brought Emeraldfinches to Haojing!? That's unbelievable!"
        },
        [50107020] = {
          Content = "雀翎茗轩……是在这里吗？",
          DialogueId = 50107020,
          GUID = "7D700AF8",
          Subtitle = "Trailing Glory Teahouse... is it round here somewhere?"
        },
        [50107021] = {
          Content = "东市雀翎茗轩开张，凡携亲眷者入座，皆送花茶一壶。",
          DialogueId = 50107021,
          GUID = "7D700B22",
          Subtitle = "Trailing Glory Teahouse — now open in East Market! Bring the family — free pot of flower tea!"
        },
        [50107022] = {
          Content = "呜呜……龙君不公啊！这茶舍还未开张，怎料运来的雀儿都不见踪影，我该如何是好……",
          DialogueId = 50107022,
          GUID = "7D700B4C",
          Subtitle = "(sobbing) No... Lord Argent, it's not fair... My teahouse hasn't even opened yet, and the finches we ordered have vanished without a trace... What am I supposed to do...?"
        },
        [50107023] = {
          Content = "游船游船，十文一趟，排队购票，客满即发。",
          DialogueId = 50107023,
          GUID = "7D700B76",
          Subtitle = "Boat rides! Ten coins a trip! Tickets here — line up! Once the boat's full, we're off!"
        },
        [50107024] = {
          Content = "这皓京城的地形，怎么看怎么觉得邪乎呢……",
          DialogueId = 50107024,
          GUID = "7D700BA0",
          Subtitle = "Something's off about Haojing's layout... the more I look, the stranger it feels."
        },
        [50107025] = {
          Content = "想当初咱这湖边多清净？钓竿一放，不消半个时辰就能钓上好几尾大鱼。",
          DialogueId = 50107025,
          GUID = "7D700BCA",
          Subtitle = "Remember when it used to be quiet round here? Drop a line and you'd pull up a couple of big ones in under half an hour."
        },
        [50107026] = {
          Content = "若是能把这五禽戏练好，你平日的那些小病小灾，都可一并消弭！",
          DialogueId = 50107026,
          GUID = "7D700BF4",
          Subtitle = "If you really commit to practising the Five-Animal Frolics, all those little aches and everyday niggles will ease on their own."
        },
        [50107027] = {
          Content = "他们还真把那五禽戏当真了不成？",
          DialogueId = 50107027,
          GUID = "7D700C1E",
          Subtitle = "They don't seriously believe in that Five-Animal Frolics stuff, do they?"
        },
        [50107028] = {
          Content = "自己要早起练功也便罢了，为何还要拖着我早起……呵欠……",
          DialogueId = 50107028,
          GUID = "7D700C48",
          Subtitle = "If you want to get up early and practise, fine... but why drag me out of bed too? Yaaawn..."
        },
        [50107029] = {
          Content = "这皓京城还没有我说不成的媒！",
          DialogueId = 50107029,
          GUID = "7D700C72",
          Subtitle = "In Haojing, there isn't a match I can't make!"
        },
        [50107030] = {
          Content = "我这般主动找人说亲，会不会……被他看出来了？",
          DialogueId = 50107030,
          GUID = "7D700C9C",
          Subtitle = "If I bring up the match... will he see right through me?"
        },
        [50107031] = {
          Content = "咱皓京人，除了吃就是喝，没别的~",
          DialogueId = 50107031,
          GUID = "7D700CC6",
          Subtitle = "Us Haojing lot — apparently all we do is eat and drink. That's our life~"
        },
        [50107032] = {
          Content = "瞧你这孩子，走起路来慌慌张张，留心点别踩到路上的石子了！",
          DialogueId = 50107032,
          GUID = "7D700CF0",
          Subtitle = "Look at you, rushing about. Careful now — don't go tripping on the stones."
        },
        [50107033] = {
          Content = "什么？涨了这么多？我没看错吧？",
          DialogueId = 50107033,
          GUID = "7D700D1A",
          Subtitle = "What!? It's gone up that much!? You can't be serious."
        },
        [50107034] = {
          Content = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
          DialogueId = 50107034,
          GUID = "7D700D44",
          Subtitle = "Ma... Pa loved you so much. Wherever he is, he wouldn't want to see you in tears."
        },
        [50107035] = {
          Content = "现在都什么年代了，哪有在丧礼上请乐队的人家！",
          DialogueId = 50107035,
          GUID = "7D700D6E",
          Subtitle = "What were you thinking? Who books a band for a funeral these days!?"
        },
        [50107036] = {
          Content = "林兄，昔日你我诗会相逢，一见如故。高山流水，难遇知音，这杯，我敬你！",
          DialogueId = 50107036,
          GUID = "7D700D98",
          Subtitle = "Lin... from the moment we met at that poetry gathering, it felt like we'd known each other for years. You don't come by friends like that often. Here's to you, brother."
        },
        [50107037] = {
          Content = "草木深胡同……是在这里？还是……",
          DialogueId = 50107037,
          GUID = "7D700DC2",
          Subtitle = "Overgrown Hutong... should be this way...? Or..."
        },
        [50107038] = {
          Content = "你说那家私房菜？我是听说过，但那家地方小，难订座，现下去问恐怕是吃不上了。",
          DialogueId = 50107038,
          GUID = "7D700DEC",
          Subtitle = "That little tucked-away place? Yeah, I've heard of it. It's tiny — hard to get a table. If we go now, we'll probably be out of luck."
        },
        [50107039] = {
          Content = "若非有仙人指路，怎知这小巷深处竟藏着这庖厨圣地！",
          DialogueId = 50107039,
          GUID = "7D700E16",
          Subtitle = "Must be a miracle I found this place. Who knew there'd be food this good hidden down a little alley like this?"
        },
        [50107040] = {
          Content = "老张啊，你那只八哥，今日居然念了几句诗，是不是你孙子整日在家背书被它听着学了去？",
          DialogueId = 50107040,
          GUID = "7D700E40",
          Subtitle = "Zhang, your mynah was rattling off a few lines of poetry today. Been listening to your grandson practising at home, has it?"
        },
        [50107041] = {
          Content = "凡夫俗子溜凡羽俗鸟，他们那些鸟，能有我这只厉害吗？",
          DialogueId = 50107041,
          GUID = "7D700E6A",
          Subtitle = "Common folk, showing off their plain little birds, as if any of them could hold a candle to mine."
        },
        [50107042] = {
          Content = "车三进六，将军！老友，这局棋，你该怎么破？",
          DialogueId = 50107042,
          GUID = "7D700E94",
          Subtitle = "Right... chariot. Check! Go on then — how are you getting out of this, my friend?"
        },
        [50107043] = {
          Content = "叫上陈老太太，咱们也在家里聚上一聚，打打骨牌？",
          DialogueId = 50107043,
          GUID = "7D700EBE",
          Subtitle = "Shall we invite Mrs Chen round? Have a little get-together at ours — play a bit of dominoes."
        },
        [50107044] = {
          Content = "我看你是蹬鼻子上脸，三天不打上房揭瓦！给我回去复习功课！",
          DialogueId = 50107044,
          GUID = "7D700EE8",
          Subtitle = "You're really asking for it! I turn my back for five minutes and look at you! Home. Now. And do your homework!"
        },
        [50107045] = {
          Content = "我来了！不好意思，今天翻墙出来被阿娘逮到了……",
          DialogueId = 50107045,
          GUID = "7D700F12",
          Subtitle = "Sorry I'm late... I tried to sneak out, but Mum caught me..."
        },
        [50107046] = {
          Content = "三……二……一……躲好了吗？无由生马上要出来抓你们咯？",
          DialogueId = 50107046,
          GUID = "7D700F3C",
          Subtitle = "Three... two... one... Ready or not — here comes Wishen!"
        },
        [50107047] = {
          Content = "今年的税账至今还在统计之中，明年的汇算眼见着也要来了……真是忙到头晕眼花。",
          DialogueId = 50107047,
          GUID = "7D700F66",
          Subtitle = "We're still balancing this year's tax ledgers, and next year's audit's already looming... I'm run off my feet."
        },
        [50107048] = {
          Content = "昨夜通宵整理典籍，今日双眼昏花，恐一蹬腿就要去往虞泉了！",
          DialogueId = 50107048,
          GUID = "7D700F90",
          Subtitle = "I was up all night poring over the old texts. My eyes are shot — at this rate, I'll be at the Spring of Yu before long."
        },
        [50107049] = {
          Content = "奉香大典意味着什么？意味着休假呀！我一直想去海伯利亚看雪……",
          DialogueId = 50107049,
          GUID = "7D700FBA",
          Subtitle = "You know what the Grand Incense Rite means? Time off! I've always wanted to go to Hyperborea and see the snow..."
        },
        [50107050] = {
          Content = "这般数据出现在这栏不太应当，莫非是填错了？",
          DialogueId = 50107050,
          GUID = "7D700FE4",
          Subtitle = "These numbers shouldn't be in this column... did I put that in wrong?"
        },
        [50107051] = {
          Content = "最近的日子，真是难得的清闲啊~",
          DialogueId = 50107051,
          GUID = "7D70100E",
          Subtitle = "Lately, it's been a rare spell of peace and quiet."
        },
        [50107052] = {
          Content = "下次遇到这种事情记得早些来泉通司，硬拖只会让事态恶化。",
          DialogueId = 50107052,
          GUID = "7D701038",
          Subtitle = "Next time this happens, come to the Hall of Founts straight away. Letting it drag on will only make things worse."
        },
        [50107053] = {
          Content = "祀香阁今年为何额外申请了一笔经费，是作何用处的？",
          DialogueId = 50107053,
          GUID = "7D701062",
          Subtitle = "The Hall of Incense is requesting additional funding this year — what's it for?"
        },
        [50107054] = {
          Content = "搭台子，修香炉，后续还有各种开销，我都递交申请了，只是拨款何时能来？",
          DialogueId = 50107054,
          GUID = "7D70108C",
          Subtitle = "There's the stage to build, the censer to repair — and that's just the start. I've filed all the requests, so when's the funding coming through?"
        },
        [50107055] = {
          Content = "是，就是往西郊那个方向，鬼鬼祟祟的，看起来不像什么好人。",
          DialogueId = 50107055,
          GUID = "7D7010B6",
          Subtitle = "Yeah — out west, near the outskirts. Just hanging around, acting shifty. Doesn't look like a decent sort."
        },
        [50107056] = {
          Content = "西郊西郊西郊，为何几封投诉信，来来回回都在提西郊？",
          DialogueId = 50107056,
          GUID = "7D7010E0",
          Subtitle = "The western outskirts again? Why is it always the western outskirts with these complaints?"
        },
        [50107057] = {
          Content = "快给我来碗茶水，刚从西郊回来，渴死我了！",
          DialogueId = 50107057,
          GUID = "7D70110A",
          Subtitle = "Quick — get me some tea! I've just come back from the western outskirts. I'm dying of thirst!"
        },
        [50107058] = {
          Content = "嗯，是说您负责运输的一船货物在码头丢失了……不是货物？那是……翠屏雀？！",
          DialogueId = 50107058,
          GUID = "7D701134",
          Subtitle = "Right. So the shipment you were carrying went missing at the docks. Not cargo? Then what was it— a whole boatload of Emeraldfinches!?"
        },
        [50107059] = {
          Content = "它到底是怎么跑出去的呢？",
          DialogueId = 50107059,
          GUID = "7D70115E",
          Subtitle = "How on earth did it get out?"
        },
        [50107060] = {
          Content = "找不回来了……一切努力都付之东流了……",
          DialogueId = 50107060,
          GUID = "7D701188",
          Subtitle = "They're gone... I'm done. All that work, down the drain..."
        },
        [50107061] = {
          Content = "已经找到一只了？在民居的屋顶上？到底是怎么飞上去的？！",
          DialogueId = 50107061,
          GUID = "7D7011B2",
          Subtitle = "They've already found one? On someone's roof? How on earth did it get up there!?"
        },
        [50107062] = {
          Content = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
          DialogueId = 50107062,
          GUID = "7D7011DC",
          Subtitle = "Qianxiu Pavilion's orders are up again this year... Our embroidery's doing really well in Haojing."
        },
        [50107063] = {
          Content = "此趟运输甜果只有百分之三损毁？甚好甚好~",
          DialogueId = 50107063,
          GUID = "7D701206",
          Subtitle = "Only three per cent loss on this fruit shipment? Good. Very good."
        },
        [50107064] = {
          Content = "太皓神君的纹样大家早就看腻啦~一点新意也没有。",
          DialogueId = 50107064,
          GUID = "7D701230",
          Subtitle = "Aw, it's that same Lord Argent motif again. Nothing fresh about it."
        },
        [50107065] = {
          Content = "各位好姐姐好哥哥们，现在呢就已经到了咱们皓京，也是咱们华胥呢，最繁华的地方~",
          DialogueId = 50107065,
          GUID = "7D70125A",
          Subtitle = "And here we are — Haojing at last! This is the busiest, most vibrant part of Huaxu~"
        },
        [50107066] = {
          Content = "三百九十九？！皓京三天两晚包吃包住包来回船票只需要三百九十九？",
          DialogueId = 50107066,
          GUID = "7D701284",
          Subtitle = "399!? Three days and two nights in Haojing, full board, plus return boat fare — the whole package for 399!?"
        },
        [50107067] = {
          Content = "恁大一个皓京城，比我屋头看着气派多了哟！",
          DialogueId = 50107067,
          GUID = "7D7012AE",
          SpecialConversation = "偏川普",
          Subtitle = "Cor, Haojing's huge! Makes my place back home look tiny."
        },
        [50107068] = {
          Content = "别靠过来！我……呕……我……头好晕……怎么有三个太阳……呕！",
          DialogueId = 50107068,
          GUID = "7D7012D8",
          Subtitle = "Don't come any closer... I... ugh... my head's spinning. Why are there three suns? ...Bleurgh."
        },
        [50107069] = {
          Content = "水龙车我先带走了。不知道哪个龟孙以为是普通木桶，居然往里面放香油，被老鼠啃得面目全非。",
          DialogueId = 50107069,
          GUID = "7D701302",
          Subtitle = "I'll take the fire pump cart with me for now. Some bloody idiot thought it was a wooden barrel and poured sesame oil into it. Now the rats have got into it, and it's a right mess."
        },
        [50107070] = {
          Content = "匠矩阁的师傅已经来将水龙车全部取走了吗？太麻烦他们了。",
          DialogueId = 50107070,
          GUID = "7D70132C",
          Subtitle = "The artisans from the Hall of Craft have already collected all the fire pump carts? Sorry. I didn't mean to make extra work for them."
        },
        [50107071] = {
          Content = "为何匠矩阁的人回回要来参商港跑个好几趟，来回拉扯不嫌麻烦吗？",
          DialogueId = 50107071,
          GUID = "7D701356",
          Subtitle = "Why do the Hall of Craft lot keep going back and forth to the Port of Parting Stars? Don't they ever get tired of it?"
        },
        [50107072] = {
          Content = "凌波微步，且看我腾空起，驾云去，身似飞雁过南关，蜻蜓点水不留痕！嘿！哈！",
          DialogueId = 50107072,
          GUID = "7D701380",
          Subtitle = "Ripple-Step! Watch this — up I go, and off I fly! Riding the clouds! Fast as a swallow, light as a dragonfly on water. You won't even see me! Hah! Hyah!"
        },
        [50107073] = {
          Content = "天一热，潮一涨，这浸在水中的部分就开始疯狂长苔，转动都费劲……",
          DialogueId = 50107073,
          GUID = "7D7013AA",
          Subtitle = "Soon as it gets hot and the tide comes in, the parts sitting in the water get coated in algae. Then it's a struggle just to get the thing turning."
        },
        [50107074] = {
          Content = "要不是他们把水车停了下来，怎会有这多事端？",
          DialogueId = 50107074,
          GUID = "7D7013D4",
          Subtitle = "If they hadn't stopped the waterwheel, we wouldn't be dealing with this mess."
        },
        [50107075] = {
          Content = "你需谨记六字——明法、公心、勤谨。",
          DialogueId = 50107075,
          GUID = "7D7013FE",
          Subtitle = "Remember these three virtues: respect the law, uphold fairness, and practise diligence."
        },
        [50107076] = {
          Content = "每至夜半三更，船舶抵港，那船工吆喝声、铁链撞击声、货箱搬运声，直吵得人不得安睡！",
          DialogueId = 50107076,
          GUID = "7D701428",
          SpecialConversation = "该npc为一期印象npc",
          Subtitle = "Every night, well past midnight, the ships come in. Dockhands shouting, chains clanking, crates scraping along... It's so loud I can't get a wink of sleep!"
        },
        [50107077] = {
          Content = "游船游船，十文一趟，排队购票，客满即发。",
          DialogueId = 50107077,
          GUID = "7D701452",
          SpecialConversation = "该npc与刘福最好为一人",
          Subtitle = "Boat rides! Ten coins a trip! Tickets here — line up! Once the boat's full, we're off!"
        },
        [50107078] = {
          Content = "稍……稍等一下……我查一下刚买的《华胥问候语录大全》。",
          DialogueId = 50107078,
          GUID = "7D70147C",
          SpecialConversation = "外国人",
          Subtitle = "J—Just a moment... let me check this guide to Huaxu greetings I just bought."
        },
        [50107079] = {
          Content = "他大舅母，晚上做了什么好吃的？可是来这儿散散步，消消食？",
          DialogueId = 50107079,
          GUID = "7D7014A6",
          Subtitle = "Evening. Had something nice for dinner? Out for a little stroll to walk it off?"
        },
        [50107080] = {
          Content = "一，二，三，铁柱呢？铁柱为何不在？你们来的时候看到他了吗？",
          DialogueId = 50107080,
          GUID = "7D7014D0",
          Subtitle = "One, two, three... Where's Tiezhu? Why isn't he here? Did you see him on the way?"
        },
        [50107081] = {
          Content = "尘香袅袅龙君现，典前争辉竞纷纭。奉香大典特别活动——灯谜会，待君赏玩！",
          DialogueId = 50107081,
          GUID = "7D7014FA",
          Subtitle = "\"Where incense hangs on the air, Lord Argent descends; on the eve of the Rite, the forecourt is awash with light.\" In honour of the Rite, we present a special event: the Lantern Riddle Fair. Do come and enjoy it."
        },
        [50107082] = {
          Content = "妈妈我到皓京了……",
          DialogueId = 50107082,
          GUID = "7D701524",
          Subtitle = "Mum... I made it to Haojing..."
        },
        [50107083] = {
          Content = "这里面不能进去吗？我买票也不行？那有什么办法能进去看看？我想见白龙神君。",
          DialogueId = 50107083,
          GUID = "7D70154E",
          Subtitle = "What d'you mean I can't go in? I'll buy a ticket! No? So how do I get in, then? I want to see Lord Argent."
        },
        [50107084] = {
          Content = "你看！只要内心足够虔诚，望向执律阁顶之时，就会看到白龙神君在云间遨游。",
          DialogueId = 50107084,
          GUID = "7D701578",
          Subtitle = "Look over there, above the Hall of Adjudication. See? If you're truly devout, you'll see Lord Argent coiling through the clouds."
        },
        [50107085] = {
          Content = "朝报朝报，茶不思饭不想只想看朝报，皓京独家新闻，绝对真实绝对劲爆！",
          DialogueId = 50107085,
          GUID = "7D7015A2",
          Subtitle = "Morning Paper! Morning Paper! Fresh off the press! Haojing exclusives — spicy stuff, and all true!"
        },
        [50107086] = {
          Content = "这字乍一看好似和海伯利亚那边没什么区别，可凑在一起为什么完全看不懂……",
          DialogueId = 50107086,
          GUID = "7D7015CC",
          SpecialConversation = "外国人",
          Subtitle = "At first glance, these characters look a lot like the ones back home in Hyperborea. So why can't I make head nor tail of it once they're put together?"
        },
        [50107087] = {
          Content = "您听我说，您去一个地方，吃什么玩什么，都是次要，主要的是要来感受当地的氛围，您说对不对？",
          DialogueId = 50107087,
          GUID = "7D7015F6",
          Subtitle = "Hear me out. When you go somewhere, the food and sights come second. It's the atmosphere that matters. You've got to get a feel for the place. Right?"
        },
        [50107088] = {
          Content = "退一万步说，在人家办事处门口宣传这些也不合适吧……",
          DialogueId = 50107088,
          GUID = "7D701620",
          Subtitle = "Even if you mean well, it's a bit much to be hawking that right outside the offices..."
        },
        [50107089] = {
          Content = "我家老婆子好好地走在街上，他路也不看，直接推着车撞了过来。",
          DialogueId = 50107089,
          GUID = "7D70164A",
          Subtitle = "My wife was just walking down the street, minding her own business. Then this bloke comes barreling along, not looking where he's going, and rams his cart straight into her."
        },
        [50107090] = {
          Content = "以香论道法，坐实众生象，天地为共生，万物与我一……",
          DialogueId = 50107090,
          GUID = "7D701674",
          Subtitle = "Through incense, the Way is spoken; the forms of all beings take shape. Heaven and earth breathe in unison. All things and I, as one..."
        },
        [50107091] = {
          Content = "为人在世，奉天命当如沙洲，勤而学当如竹溪先生。",
          DialogueId = 50107091,
          GUID = "7D70169E",
          Subtitle = "To live well, keep to Heaven's Mandate, steadfast as Mr Shazhou. To learn well, keep to your studies, diligent as Master Zhuxi."
        },
        [50107092] = {
          Content = "我何时曾说我亲眼见过竹溪先生？我说的是父亲年幼之时，曾在学院听竹溪先生传授最后一课。",
          DialogueId = 50107092,
          GUID = "7D7016C8",
          Subtitle = "When did I ever say I met Master Zhuxi in person? What I said was this: when my father was young, he heard Master Zhuxi give his final lecture at the academy."
        },
        [50107093] = {
          Content = "吵死了……这怎么让人背书！",
          DialogueId = 50107093,
          GUID = "7D7016F2",
          Subtitle = "They're too loud... How's anyone meant to learn like this!?"
        },
        [50107094] = {
          Content = "所谓理一，即天地万物都只有一个理，所谓分殊，即千差万殊的事物都是一个理的体现。",
          DialogueId = 50107094,
          GUID = "7D70171C",
          Subtitle = "\"One principle\" is the idea that heaven, earth, and all things share a single underlying truth. \"Many expressions\" means that the countless differences we see are simply manifestations of that same truth."
        },
        [50107095] = {
          Content = "五味万殊，而大同于美；曲变虽众，亦大同于和；子性各异，但大同于敏；教术众多，然大同于情。",
          DialogueId = 50107095,
          GUID = "7D701746",
          Subtitle = "Flavours may differ a thousand ways, yet all tend towards the good. Tunes may change without end, yet all return to harmony. The young may vary in temperament, yet all share a quickness of wit. Methods of teaching may be many, yet all come back to the heart."
        },
        [50107096] = {
          Content = "这万事万物，道理总是只有一个，但一个道理却可涵盖了世间万物，所以理一定是在前面的！",
          DialogueId = 50107096,
          GUID = "7D701770",
          Subtitle = "There's one principle behind everything. If it encompasses all things, it must come before all else!"
        },
        [50107097] = {
          Content = "今天该轮到你执勤了吧，之前你说你娘风寒，我可帮你顶了三天，夫子都起疑了！",
          DialogueId = 50107097,
          GUID = "7D70179A",
          Subtitle = "Wasn't it your turn on duty today? You said your mum had a cold, so I covered for you for three days. Now even the teacher's starting to get suspicious!"
        },
        [50107098] = {
          Content = "奉香大典期间放假，你们都去哪玩？我哥从外地回来了，说要给我带外国的新奇玩具呢。",
          DialogueId = 50107098,
          GUID = "7D7017C4",
          Subtitle = "School's off for the Grand Incense Rite. Where are you guys going? My brother's just got back, and he says he's bringing me some cool stuff from abroad."
        },
        [50107099] = {
          Content = "下午的蹴球赛，咱们队还差一人，你问过樾山哥没有？他要是肯来，咱们定能踢得对面满地找牙！",
          DialogueId = 50107099,
          GUID = "7D7017EE",
          Subtitle = "We're one short for the football match this afternoon. Have you checked with Yueshan yet? If he can make it, we'll absolutely wipe the floor with them."
        },
        [50107100] = {
          Content = "按这个势头算下去，岂不是又要扩张？可这又还能往哪里扩呢？",
          DialogueId = 50107100,
          GUID = "7D701818",
          Subtitle = "At this rate, it's bound to expand again... but where can it possibly go from here?"
        },
        [50107101] = {
          Content = "是了，来年开春便要递上辞函，到时候自然是会念着大家的，放心！",
          DialogueId = 50107101,
          GUID = "7D701842",
          Subtitle = "That's right. Come spring, I'll hand in my resignation. And when the time comes, I won't forget any of you, so don't worry."
        },
        [50107102] = {
          Content = "若华胥的安宁和平需要人们以不同的努力去守护，那为何飘零人的行为不能算是一种独特的方式？",
          DialogueId = 50107102,
          GUID = "7D70186C",
          Subtitle = "If Huaxu's peace is upheld by all sorts of people, in all sorts of ways, then why doesn't the Drifters' way count too?"
        },
        [50107103] = {
          Content = "好啊，今天的辩题有趣，我在学院许久没见过这么有意思的辩题了。",
          DialogueId = 50107103,
          GUID = "7D701896",
          Subtitle = "Now that's a debate topic. I haven't heard one this interesting at the academy in ages."
        },
        [50107104] = {
          Content = "空口说白话，不亚于纸上谈兵。有这闲工夫，不如多读些书！",
          DialogueId = 50107104,
          GUID = "7D7018C0",
          Subtitle = "All talk, no action. If you've got time to spare, go and read a book."
        },
        [50107105] = {
          Content = "椒兰村的香料自然是地道，处理方式也多样，只是要论品质，外面的许多园子都不遑多让。",
          DialogueId = 50107105,
          GUID = "7D7018EA",
          Subtitle = "Jiaolan Village's incense is certainly authentic, and it is processed in a variety of ways. That said, many incense gardens beyond the village produce incense of comparable quality."
        },
        [50107106] = {
          Content = "敢问祀烟阁的管事香官现在何处？鄙人自氤园而来，与他有约。",
          DialogueId = 50107106,
          GUID = "7D701914",
          Subtitle = "May I ask where the incense warden is? I've come from Yinyuan, and I have an appointment with him."
        },
        [50107107] = {
          Content = "今日怎得是你来奉香，你哥又回烟津渡了？",
          DialogueId = 50107107,
          GUID = "7D70193E",
          Subtitle = "How come you're the one offering incense today? Has your brother gone back to Mistwharf again?"
        },
        [50107108] = {
          Content = "伏惟上苍垂佑，神君护持，愿家父身体健康，百病不侵。",
          DialogueId = 50107108,
          GUID = "7D701968",
          Subtitle = "May Heaven bless us, and may Lord Argent watch over us. May my father be in good health, and kept safe from illness."
        },
        [50107109] = {
          Content = "唔……我的愿望是，长高一点，也不用太高，像一个正常的抟土氏就好。",
          DialogueId = 50107109,
          GUID = "7D701992",
          Subtitle = "Mm... I just want to be taller. Just a bit. Like everyone else..."
        },
        [50107110] = {
          Content = "奉香大典今年比往年都热闹许多呢！香官跟我说的。",
          DialogueId = 50107110,
          GUID = "7D7019BC",
          Subtitle = "This year's Grand Incense Rite's meant to be far livelier than usual. That's what the incense warden said."
        },
        [50107111] = {
          Content = "往年到了奉香大典期间，总是需要许多帮工入阁，今年怎得没动静了？",
          DialogueId = 50107111,
          GUID = "7D7019E6",
          Subtitle = "In past years, they always needed plenty of extra hands at the Hall of Incense during the Rite. So why's it gone so quiet there this year?"
        },
        [50107112] = {
          Content = "全城的香炉都要仔细查验香料储备，尤其是中心广场水上的那个炉子，务必不能有疏漏。",
          DialogueId = 50107112,
          GUID = "7D701A10",
          Subtitle = "Inspect the incense reserves in every censer across the city. Be thorough. Pay special attention to the one on the water in the central square. Don't miss a thing."
        },
        [50107113] = {
          Content = "难不成真是我思维迟缓，想不出新颖独特的香方了？",
          DialogueId = 50107113,
          GUID = "7D701A3A",
          Subtitle = "Has my mind really gone dull? Can't I come up with any new incense recipes any more?"
        },
        [50107114] = {
          Content = "不同的香方自然作用也不相同，你初来乍到，不了解也很正常。",
          DialogueId = 50107114,
          GUID = "7D701A64",
          Subtitle = "Different incense recipes have different effects. You're new here, so it's no wonder you don't know."
        },
        [50107115] = {
          Content = "听说了吗？祀香阁今年招了一位特殊香官，据说是……一位皎皎之民！",
          DialogueId = 50107115,
          GUID = "7D701A8E",
          Subtitle = "Have you heard? The Hall of Incense has brought in a special incense warden this year. They say it's... a Lunarian!"
        },
        [50107116] = {
          Content = "皎皎之民？！那矮冬瓜大头鱼一样的家伙，如何能担任香官一职？",
          DialogueId = 50107116,
          GUID = "7D701AB8",
          Subtitle = "A Lunarian!? Those stunted, big-headed little creatures? How could one of them possibly be fit to serve as an incense warden?"
        },
        [50107117] = {
          Content = "去泉通司问过了吗？奉香大典前事务繁杂，那批拨款要早点讨过来才好做事。",
          DialogueId = 50107117,
          GUID = "7D701AE2",
          Subtitle = "Have you asked at the Hall of Founts? It's always hectic before the Grand Incense Rite. Best to chase that allocation up early, or you won't get much done."
        },
        [50107118] = {
          Content = "师傅，我就是想来问问，这炉灶为何总是出问题，我这几番叨扰，自己都有点过意不去了。",
          DialogueId = 50107118,
          GUID = "7D701B0C",
          Subtitle = "Any idea why this burner keeps acting up? Sorry to trouble you again, but it won't behave."
        },
        [50107119] = {
          Content = "过两天不是休息了吗？你准备回家？还是带妻子出门逛逛？",
          DialogueId = 50107119,
          GUID = "7D701B36",
          Subtitle = "We've got a couple of days off soon. Any plans? Heading home, or taking your wife out somewhere?"
        },
        [50107120] = {
          Content = "来奉香也有这么多嘁嘁喳喳嘟嘟囔囔，要么就是嘀嘀咕咕哼哼唧唧，这要我们如何兢兢业业干活？",
          DialogueId = 50107120,
          GUID = "7D701B60",
          Subtitle = "We can't even offer incense in peace. Nothing but whispering, sniggering, and yapping. How are we supposed to get any proper work done?"
        },
        [50107121] = {
          Content = "你这关节做的根本不行！偶人要做抬手、转腰的动作，反复受力下来，榫头迟早开裂！",
          DialogueId = 50107121,
          GUID = "7D701B8A",
          Subtitle = "The joint you've made won't hold. With the puppet lifting its arms and twisting at the waist all the time, that tenon's going to split sooner or later."
        },
        [50107122] = {
          Content = "你瞧瞧，这是咱们新研究的木头珍猪，上了发条后一下便能冲出十米，想学的话来机枢派报个名？",
          DialogueId = 50107122,
          GUID = "7D701BB4",
          Subtitle = "Check this out — our new wind-up wooden Petit Boar. Wind it up and it'll dash ten metres in a flash. Want to learn how to make one? Sign up as an apprentice with the Jishu Sect!"
        },
        [50107123] = {
          Content = "叔叔，这是什么？看着好可爱，可以送给我吗？",
          DialogueId = 50107123,
          GUID = "7D701BDE",
          Subtitle = "Sir, what's that? It's so cute! Can I have it?"
        },
        [50107124] = {
          Content = "年年招新，年年没人，与其把心思放在拉人进阁，还不如多花些时间造个惊天动地的大工程出来！",
          DialogueId = 50107124,
          GUID = "7D701C08",
          Subtitle = "Year after year we recruit, year after year nobody comes. Instead of trying to rope people in, we'd be better off pouring that effort into a project that'll shake the world."
        },
        [50107126] = {
          Content = "民以食为天，食以香为先，香……这香……香啊……香。",
          DialogueId = 50107126,
          GUID = "7D701C5C",
          Subtitle = "\"Food is the first necessity\"... and when it comes to food, it's all about the smell. And this... this smell... mm... that's the stuff."
        },
        [50107127] = {
          Content = "这就是华胥风格的服饰吗？嘶……我怎么觉得穿起来哪里怪怪的呢？",
          DialogueId = 50107127,
          GUID = "7D701C86",
          Subtitle = "So this is Huaxu clothing? Hmm... why does it feel a bit off on me?"
        },
        [50107128] = {
          Content = "青青子衿，悠悠我心，在这苍茫人世间，难道我真就无法找到相伴一生之人？",
          DialogueId = 50107128,
          GUID = "7D701CB0",
          SpecialConversation = "该角色不怎么着调，可以跳脱一点",
          Subtitle = "Ah... my poor, lonely heart. In a world this vast, am I truly doomed to be alone forever?"
        },
        [50107129] = {
          Content = "要是我把这个人杀了……大家的反响一定很好，要是再把这个也顺便刀了……",
          DialogueId = 50107129,
          GUID = "7D701CDA",
          Subtitle = "If I kill him... people will love it. And if I take that one out as well, while I'm at it..."
        },
        [50107130] = {
          Content = "天气大好啊，等开春，去收两斤新茶泡来喝！",
          DialogueId = 50107130,
          GUID = "7D701D04",
          Subtitle = "Lovely weather today! Come spring, I'll buy some fresh tea and brew a pot."
        },
        [50107131] = {
          Content = "瞧见那远处的楼没？我啊，小时候曾听老人说，其实它根本不存在，都是假的！",
          DialogueId = 50107131,
          GUID = "7D701D2E",
          Subtitle = "See that tower in the distance? When I was little, the old folks used to say it wasn't real at all — just a trick of the eye!"
        },
        [50107132] = {
          Content = "所有目光向我看齐，在场的各位，都是彻彻底底的聪明龙！聪明土！",
          DialogueId = 50107132,
          GUID = "7D701D58",
          Subtitle = "Hey, everyone — look at me! You're all smart — every one of you!"
        },
        [50107133] = {
          Content = "怎就没有愿意与我辩论之人？莫非是我过于咄咄逼人了？",
          DialogueId = 50107133,
          GUID = "7D701D82",
          Subtitle = "How come no one wants to debate me? Have I been coming on too strong?"
        },
        [50107134] = {
          Content = "要说最为复杂的调解案……莫过于十年前的那场意外了。",
          DialogueId = 50107134,
          GUID = "7D701DAC",
          Subtitle = "The most complicated mediation case I ever handled was the accident ten years ago."
        },
        [50107135] = {
          Content = "若是法理不通，又怎敢把评判的权利交由那劳什子人心私情？",
          DialogueId = 50107135,
          GUID = "7D701DD6",
          Subtitle = "If the law can't stand up to scrutiny, letting personal feelings decide is even less defensible."
        },
        [50107136] = {
          Content = "现在敲敲打打的这些木头块，那都没意思！要是放在以前，我能给你们看带劲的大家伙！",
          DialogueId = 50107136,
          GUID = "7D701E00",
          Subtitle = "These bits of wood you lot keep knocking together — there's nothing to them. Back in the day, I could've shown you the real stuff."
        },
        [50107137] = {
          Content = "皎皎为何不能当香官？我偏要当这皎皎第一人！",
          DialogueId = 50107137,
          GUID = "7D701E2A",
          Subtitle = "Why can't a Lunarian be an incense warden? I'll be the first — just you wait and see!"
        },
        [50107138] = {
          Content = "夫君莫急，你先将那筐香料放下再说，那种叶子娇贵，颠了撒了香味可要散一半呢。",
          DialogueId = 50107138,
          GUID = "7D701E54",
          Subtitle = "Easy, love. Set the basket down first. Those leaves are delicate — knock them about and you'll lose half the fragrance."
        },
        [50107139] = {
          Content = "想起来了，我可都想起来了，由来巷的事儿，我可全都记着呢！",
          DialogueId = 50107139,
          GUID = "7D701E7E",
          Subtitle = "Oh! I remember now! I remember everything about Youlai Alley!"
        },
        [50107140] = {
          Content = "飘零四杰啊……那可真是一段因为年代久远而模糊不清的故事啊……",
          DialogueId = 50107140,
          GUID = "7D701EA8",
          Subtitle = "The Four Drifters... that's a story so old it's gone blurry round the edges..."
        },
        [50107141] = {
          Content = "高高的台上我远远地望，见笨笨的家伙建高高的台~",
          DialogueId = 50107141,
          GUID = "7D701ED2",
          Subtitle = "Up on the high stage, peeking from far away — silly little builders, stacking it up all day~"
        },
        [50107142] = {
          Content = "又来了一个长鼻子家伙，诶呀诶呀，这家伙怎么看着我？",
          DialogueId = 50107142,
          GUID = "7D701EFC",
          Subtitle = "Ah! Another visitor with a long nose? Hey~ why are you staring at me like that?"
        },
        [50107143] = {
          Content = "都去哪里了？我要开始抓你们了哦！",
          DialogueId = 50107143,
          GUID = "7D701F26",
          Subtitle = "Where'd you all go? Alright — I'm coming to catch you!"
        },
        [50107144] = {
          Content = "谁家的孩子穿一身白，太素净，看着一点也不喜庆！",
          DialogueId = 50107144,
          GUID = "7D701F50",
          Subtitle = "Look at you, all dressed in white. Far too plain. You look like you're going to a funeral!"
        },
        [50107145] = {
          Content = "此香烘制程度不够，你闻，香味还没散出来呢。",
          DialogueId = 50107145,
          GUID = "7D701F7A",
          Subtitle = "This batch of incense isn't dry enough yet. Here, have a smell. The aroma hasn't developed properly."
        },
        [50107146] = {
          Content = "早跟你说了，收回来的新鲜吿苍要立即拿去晾晒，为何回回都能忘了呢？",
          DialogueId = 50107146,
          GUID = "7D701FA4",
          Subtitle = "I've told you — fresh Skylilies go straight out to dry as soon as you bring them back. How do you forget every time?"
        },
        [50107147] = {
          Content = "落生香的原料研磨最讲究精细，一遍下来若是还有这种大颗粒，你得重新再来一遍。",
          DialogueId = 50107147,
          GUID = "7D701FCE",
          Subtitle = "Luosheng Incense needs a very fine grind. If there are still chunks this size after one pass, you'll have to run it through again."
        },
        [50107148] = {
          Content = "亮哥亮哥！快来帮忙，炉子又炸了！",
          DialogueId = 50107148,
          GUID = "7D701FF8",
          Subtitle = "Help, Liang! Come quick! The stove's blown up again!"
        },
        [50107149] = {
          Content = "合香是一门技术活，没你想得那么简单，配比和时间都要多加注意，制香也要顺应天时呀~",
          DialogueId = 50107149,
          GUID = "7D702022",
          Subtitle = "Incense blending is a craft. It's not as simple as you think. Mind the ratios, mind the timing... and even then, a bit of luck comes into it."
        },
        [50107150] = {
          Content = "那批香装好了吗？订货的那些人问过几回了。",
          DialogueId = 50107150,
          GUID = "7D70204C",
          Subtitle = "Is that batch of incense packed and ready yet? The client has asked a few times already."
        },
        [50107151] = {
          Content = "抓紧犁完这片田，就能早些回家歇息了……",
          DialogueId = 50107151,
          GUID = "7D702076",
          Subtitle = "Just this last bit to plough... then I can get home and put my feet up."
        },
        [50107152] = {
          Content = "听说最近西郊有人借着飘零人的名头活动，不知道是打什么鬼主意。",
          DialogueId = 50107152,
          GUID = "7D7020A0",
          Subtitle = "Heard someone's been making moves out in the western outskirts lately, using the Drifters' name. Can't tell what they're up to."
        },
        [50107153] = {
          Content = "是小苏带回来的那位？模样俊俏，当真是位妙人~",
          DialogueId = 50107153,
          GUID = "7D7020CA",
          Subtitle = "So you're the one Su brought back? Well, look at you. Aren't you a charming youngster."
        },
        [50107154] = {
          Content = "大哥，我们什么时候才能出山啊，天天待在这里太无聊了……",
          DialogueId = 50107154,
          GUID = "7D7020F4",
          Subtitle = "Come on... when are we going down the mountain? I'm so bored up here..."
        },
        [50107155] = {
          Content = "哼！我早说过不要随便带人回来，不然山外山迟早会暴露出去！",
          DialogueId = 50107155,
          GUID = "7D70211E",
          Subtitle = "Hmph. I told you not to bring outsiders back. Sooner or later, someone's going to find this place."
        },
        [50107156] = {
          Content = "机枢有什么好！听我的，剑拿着，咱俩练两手才是真的。",
          DialogueId = 50107156,
          GUID = "7D702148",
