        [51000501] = {
          Content = "拜托你了……",
          DialogueId = 51000501,
          GUID = "7FACA5B2",
          NextOptions = {
            [1] = 510005011
          },
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000502] = {
          Content = "天呐！你找到安妮了？",
          DialogueId = 51000502,
          GUID = "7FACA5DC",
          NextOptions = {
            [1] = 510005021
          },
          SpeakNpcId = 700006,
          Subtitle = "My goodness! Have you found Annie?",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000503] = {
          Content = "……",
          DialogueId = 51000503,
          GUID = "7FACA606",
          NextDialogue = 51000504,
          SpeakNpcId = 700006,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700006:Shock_End"
          }
        },
        [51000504] = {
          Content = "胡说……胡说，胡说！",
          DialogueId = 51000504,
          GUID = "7FACA630",
          NextDialogue = 51000591,
          SpeakNpcId = 700006,
          Subtitle = "Nonsense... That's utter nonsense!",
          TalkActionId = {
            [1] = "700006:Disagree"
          }
        },
        [51000505] = {
          Content = "你说，孩子没了母亲可怎么行呢……",
          DialogueId = 51000505,
          GUID = "7FACA65A",
          NextDialogue = 51000506,
          Scripts = [[
SEQ{
MoveTo{ActorId{700006},TargetPoint{"Point_510005_Aier2"},MoveSpeed{150},Visibility{"Show"}},
MoveTo{ActorId{700006},TargetPoint{"Point_510005_Aier"},MoveSpeed{150},Visibility{"Hide"}}
}]],
          SpeakNpcId = 700006,
          Subtitle = "How do you think a child can manage without her mother..."
        },
        [51000506] = {
          Content = "（爱尔莎像着了魔一样朝某个方向走去，泪水与笑容交织在她憔悴的脸上，很快她的身影就消失在了远方。）",
          DialogueId = 51000506,
          GUID = "7FACA684",
          NextDialogue = 51000507,
          Subtitle = "(She thrusts the coin pouch into your arms and walks away, as if spellbound. Tears and a smile mingle on her weary face, flickering faintly before she disappears into the distance.)"
        },
        [51000507] = {
          Content = "（她匆忙中落下了一个小箱子——这是她原本打算赠与帮她找到女儿的好心人的。你为她的事奔忙了这么久，这些报酬理当属于你。）",
          DialogueId = 51000507,
          GUID = "7FACA6AE",
          Subtitle = "(A gentle lie might bring comfort for a time — but in the end, truth must be faced. Time will mend what it can... and perhaps, someday, she'll heal.)"
        },
        [51000590] = {
          Content = "之前是我太疏忽，只知道拜托别人，傻傻地等，让我的安妮等了那么久，没关系，都没关系，我现在就启程去找她……自己去找……",
          DialogueId = 51000590,
          GUID = "7FACB44C",
          NextDialogue = 51000505,
          SpeakNpcId = 700006,
          Subtitle = "I've been a terrible mother — how could I just wait here for others to help me? My Annie must've waited for me for so long... It's okay, I'll set off to find her now... I'll find my baby on my own..."
        },
        [51000591] = {
          Content = "我的安妮……我的安妮那么乖，她怎么可能抛下自己的妈妈呢！你骗我，你骗我！",
          DialogueId = 51000591,
          GUID = "7FACB476",
          NextDialogue = 51000590,
          SpeakNpcId = 700006,
          Subtitle = "My Annie... My sweet Annie, she'd never leave her mother like this! You're lying, you dirty liar!"
        },
        [51000601] = {
          Camera = "-234.948181,323.855713,130.964355,0.00001,-3.599974,-48.399338,32.0,100000.0,false,Manual,2.8",
          Content = "拜托你了……",
          DialogueId = 51000601,
          GUID = "7FACB61A",
          LookAt = {
            [1] = "700006:n(0)"
          },
          NextOptions = {
            [1] = 510006011
          },
          Scripts = "TurnTo{TurnToDescription{\"700006:n(100001)\"}}",
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000602] = {
          Camera = "-110.428955,187.104736,199.557129,0.00006,-12.599321,-55.19915,32.0,500.0,false,Manual,2.8",
          Content = "……天啊，奇迹真的发生了……",
          DialogueId = 51000602,
          FinalCamera = "-95.131409,197.827637,199.557129,0.000059,-12.799316,-54.799076,32.0,500.0,false,Manual,2.8",
          GUID = "7FACB644",
          LookAt = {
            [1] = "700006:n(700196)"
          },
          NextDialogue = 51000603,
          Scripts = "MoveTo{ActorId{700196},TargetPoint{\"Point200203_Alice\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700006,
          Subtitle = "Oh my God, miracles do happen...",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          },
          ToFinalCameraBlendTime = 3
        },
        [51000603] = {
          Content = "让妈妈好好看看，妈妈想你想得都快发疯了！嗯？你怎么和以前不太一样了？你变瘦了好多……",
          DialogueId = 51000603,
          FacialId = {
            [1] = "700006:CM_Happy01"
          },
          GUID = "7FACB66E",
          NextDialogue = 51000604,
          SpeakNpcId = 700006,
          Subtitle = "Let Mum have a good look at you, sweetie... I've missed you so much that I almost lost my mind! Hm? You seem a bit different... Much thinner than before..."
        },
        [51000604] = {
          Camera = "98.233093,31.165039,150.292969,0.000063,-2.599365,-39.19735,32.0,150.0,false,Manual,2.8",
          Content = "没关系的，没关系的，妈妈准备了你最爱吃的北风莓沙拉和奶油布丁，回家吧，我的孩子，都过去了，都过去了……",
          DialogueId = 51000604,
          GUID = "7FACB698",
          NextDialogue = 51000605,
          SpeakNpcId = 700006,
          Subtitle = "It's okay, I've made your favourite Borealberry Salad and Cream Pudding; let's go home, my baby, everything's okay now...",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000605] = {
          Content = "谢谢你，好心人，这是给你的报酬。我差点就以为我再也见不到我的安妮了。谢谢你，谢谢你……",
          DialogueId = 51000605,
          GUID = "7FACB6C2",
          NextDialogue = 51000690,
          SpeakNpcId = 700006,
          Subtitle = "Bless you, kind soul. This is for you. I thought I'd never see my Annie again. Thank you, thank you so much..."
        },
        [51000606] = {
          Content = "我的宝贝女儿……只要不离开妈妈，妈妈为你做什么都可以……",
          DialogueId = 51000606,
          GUID = "7FACB6EC",
          SpeakNpcId = 700006,
          Subtitle = "My precious daughter... As long as you don't leave me, I'll do anything for you..."
        },
        [51000690] = {
          Content = "（女人喜极而泣，不停道谢着。泪水流干后，就是幸福的未来……或许。）",
          DialogueId = 51000690,
          GUID = "7FACC4B4",
          Subtitle = "(Tears of joy stream down the woman's face as she utters her gratitude repeatedly. After the tears dry, a mother and a child will live happily ever after... hopefully.)"
        },
        [51000701] = {
          Content = "……",
          DialogueId = 51000701,
          GUID = "7FACC682",
          NextOptions = {
            [1] = 510007011
          },
          SpeakNpcId = 700032,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          }
        },
        [51000702] = {
          Content = "我……我脑袋很昏沉。我不知道自己是谁，也不清楚这是哪里……",
          DialogueId = 51000702,
          GUID = "7FACC6AC",
          NextDialogue = 51000703,
          SpeakNpcId = 700032,
          Subtitle = "I... I feel so foggy. Honestly, I don't even know who I am — or where this place is."
        },
        [51000703] = {
          Content = "我是被一个好心的旅行医生从北边雪山救回来的。他说我发了高烧，烧坏了脑子，所以才会失去记忆……",
          DialogueId = 51000703,
          GUID = "7FACC6D6",
          NextOptions = {
            [1] = 510007031,
            [2] = 510007032,
            [3] = 510007033
          },
          SpeakNpcId = 700032,
          Subtitle = "A kind-hearted doctor found me up in the northern mountains and brought me back. She said I had a terrible fever... and that it probably damaged my memory.",
          bForbidSkipOptions = true
        },
        [51000705] = {
          Content = "这几天我唯一能想起来的就是漫天的暴风雪，我在山上举步维艰……但我大病初愈，现在的身体状况估计连出城都难，可以拜托你帮我调查吗？",
          DialogueId = 51000705,
          GUID = "7FACC72A",
          NextOptions = {
            [1] = 510007051,
            [2] = 51000002
          },
          SpeakNpcId = 700032,
          Subtitle = "The only thing I could remember these past few days was the relentless blizzard as I struggled to make my way across the mountain... But right now I'm in no condition to go anywhere. Could you help me with the investigation?",
          TalkActionId = {
            [1] = "700032:Explain01_Start"
          },
          bForbidSkipOptions = true
        },
        [51000706] = {
          Content = "除了救我的好心人，你是唯一一个愿意对我这样一个身无分文的女孩子伸出援助之手的。除了谢谢，我不知道还能说什么好……",
          DialogueId = 51000706,
          GUID = "7FACC754",
          NextDialogue = 51000790,
          SpeakNpcId = 700032,
          Subtitle = "Apart from the kind doctor who saved me, you are the only one willing to offer a helping hand to a penniless girl like me. I don't know what else to say but thank you...",
          TalkActionId = {
            [1] = "700032:Explain01_End"
          }
        },
        [51000707] = {
          Content = "有结果吗？",
          DialogueId = 51000707,
          GUID = "7FACC77E",
          SpeakNpcId = 700032,
          Subtitle = "Did you find anything?"
        },
        [51000790] = {
          Content = "对了，这里有一封信，医生说这是从我身上找到的。虽然我对这封信一点印象都没有……但这个线索可能会有用？",
          DialogueId = 51000790,
          GUID = "7FACD51C",
          NextDialogue = 51000791,
          SpeakNpcId = 700032,
          Subtitle = "Oh — this was in my coat pocket. I don't remember anything about it... but maybe it's important?"
        },
        [51000791] = {
          Content = "（你开始思索最近遇到的两个人——近乎疯癫地寻找女儿的爱尔莎夫人，以及失忆的少女。当然，还有少女口袋里那封写给母亲的信。）",
          DialogueId = 51000791,
          GUID = "7FACD546",
          NextDialogue = 51000792,
          Subtitle = "(The threads begin to connect between the two individuals you've recently come across — Ms Elsa, who's been driven near to madness in search of her daughter, and this amnesiac girl. And then there's the letter, seemingly penned to a mother.)"
        },
        [51000792] = {
          Content = "（失忆的少女也许就是爱尔莎失踪的女儿，安妮——你这样猜测。）",
          DialogueId = 51000792,
          GUID = "7FACD570",
          NextDialogue = 51000793,
          Subtitle = "(The thought crosses your mind that the girl bereft of memory might very well be Elsa's missing daughter, Annie.)"
        },
        [51000793] = {
          Content = "（你应该带她去找爱尔莎确认的，但是，爱尔莎似乎会把每一个路过的年轻人当成安妮……也许还是先收集更多失忆少女身份的证据为好。）",
          DialogueId = 51000793,
          GUID = "7FACD59A",
          NextDialogue = 51000794,
          Subtitle = "(Intuition suggests bringing her to Elsa for recognition, yet Elsa's delusion leads her to see Annie in every youthful face... Gathering more substantial evidence of the girl's identity seems the prudent course at the moment.)"
        },
        [51000794] = {
          Content = "（解铃还须系铃人，看来想要探知少女的身世，还得先想办法找到那位当初救下少女的医生。）",
          DialogueId = 51000794,
          GUID = "7FACD59B",
          Subtitle = "(If anyone holds the key to this girl's past, it's the doctor who saved her back then.)"
        },
        [51000801] = {
          Content = "你平安回来了，辛苦你了，有什么发现吗？",
          DialogueId = 51000801,
          GUID = "7FACD6EA",
          NextDialogue = 51000802,
          SpeakNpcId = 700032,
          Subtitle = "You've returned safely. Did you find anything?",
          TalkActionId = {
            [1] = "700032:Agree"
          }
        },
        [51000802] = {
          Content = "（眼前的少女无依无靠，而爱尔莎夫人也因为爱女失踪而精神失常……你不禁想，如果少女就是安妮该有多好。）",
          DialogueId = 51000802,
          GUID = "7FACD714",
          NextDialogue = 51000890,
          Subtitle = "(The girl standing before you is all alone, and Ms Elsa has been driven to the brink of madness by her daughter's disappearance... You find yourself wishing she were Annie.)"
        },
        [51000803] = {
          Content = "……这是……！",
          DialogueId = 51000803,
          GUID = "7FACD73E",
          NextDialogue = 51000893,
          SpeakNpcId = 700032,
          Subtitle = "...What's this...",
          TalkActionId = {
            [1] = "700032:Shock_Start"
          }
        },
        [51000804] = {
          Content = "我……我记起来了……",
          DialogueId = 51000804,
          GUID = "7FACD768",
          NextDialogue = 51000805,
          SpeakNpcId = 700032,
          Subtitle = "...It's all coming back to me now...",
          TalkActionId = {
            [1] = "700032:Shock_End"
          }
        },
        [51000805] = {
          Content = "我叫爱丽丝，是一名来自伊瑟尔的考古学学生……",
          DialogueId = 51000805,
          GUID = "7FACD792",
          NextDialogue = 51000806,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "My name is Alice, I'm an archaeology student from Aethyrie...",
          TalkActionId = {
            [1] = "700032:Talk02_Start"
          }
        },
        [51000806] = {
          Content = "当时我正在维德弗尼尔雪山勘查，却恰巧遭遇了接连数日的暴风雪，很快我就迷失了方向……",
          DialogueId = 51000806,
          GUID = "7FACD7BC",
          NextDialogue = 51000807,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "I was conducting a survey in the Vidofnir Mountains when I got caught in a snowstorm that lasted for days, and soon I lost my way..."
        },
        [51000807] = {
          Content = "后来，我遇见了奄奄一息的安妮，我们一起艰难生活了数日。我们鼓励着彼此活下去，约好在暴风雪停歇后，我要去她在冰湖城的家做客……",
          DialogueId = 51000807,
          GUID = "7FACD7E6",
          NextDialogue = 51000808,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Later on, I met Annie, who was clinging to life by a mere thread. Together, we struggled to live on for several days. We encouraged each other to try to survive, and she invited me to visit her home in Icelake after the storm..."
        },
        [51000808] = {
          Content = "可是她伤得太重了，最终还是没能挺过去……最后她把衣服给了我，希望我再穿暖和一些，能活着走出雪山……",
          DialogueId = 51000808,
          GUID = "7FACD810",
          NextDialogue = 51000809,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "But... she was too badly hurt. She didn't make it. Before she passed, she gave me her coat. Said it might keep me warm enough to get through...",
          TalkActionId = {
            [1] = "700032:Talk02_End"
          }
        },
        [51000809] = {
          Content = "安妮……",
          DialogueId = 51000809,
          GUID = "7FACD83A",
          NextDialogue = 51000810,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Annie...",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          }
        },
        [51000810] = {
          Content = "谢谢你……我会永远记住安妮的。",
          DialogueId = 51000810,
          GUID = "7FACD864",
          NextDialogue = 51000811,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Thank you... I will always remember Annie.",
          TalkActionId = {
            [1] = "700032:Explain02_End"
          }
        },
        [51000811] = {
          Content = "（爱丽丝温柔地抚摸着衣物，这是一个女孩保护了另一个女孩的见证。你告别爱丽丝，准备将事实转告爱尔莎。）",
          DialogueId = 51000811,
          GUID = "7FACD88E",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "(Alice gently strokes the clothing which is a testament of one girl protecting the other. You bid farewell to Alice and get ready to tell Elsa the truth.)"
        },
        [51000812] = {
          ContentES = "Tan pronto como me recupere, tomaré el camino para una nueva aventura.",
          DialogueId = 51000812,
          GUID = "7FACD8B8",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Once I've recovered, I will start my next adventure."
        },
        [51000813] = {
          Content = "你的名字是安妮。我找到了你的母亲，你口袋里那封信就是写给她的。",
          DialogueId = 51000813,
          GUID = "7FACD8E2",
          NextDialogue = 51000894,
          SpeakNpcId = 100001,
          Subtitle = "Your name is Annie. I've found your mother, and that letter you're carrying is meant for her."
        },
        [51000814] = {
          Content = "谢谢你！她一定很担心我。",
          DialogueId = 51000814,
          GUID = "7FACD90C",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Thank you! She must be worried about me."
        },
        [51000815] = {
          Content = "等母亲好些，我就带她去看看大自然有多美！",
          DialogueId = 51000815,
          GUID = "7FACD936",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Once my mother gets better, I'll take her to see the beauty in the great outdoors!"
        },
        [51000890] = {
          Content = "（回忆起爱尔莎说过，她家只有母女俩相依为命，你脑海中突然闪过一个可怕的念头——如果你<H>从未见过</>爱丽丝的日记……）",
          DialogueId = 51000890,
          GUID = "7FACE584",
          NextDialogue = 51000891,
          Subtitle = "(Recalling Elsa's words about how she and her daughter were the only two in their family, a dreadful thought crosses your mind — if you had never seen Alice's diary...)"
        },
        [51000891] = {
          Content = "（少女将有一个温暖的小家可以依靠，而爱尔莎的“女儿”也回来了。<H>这似乎是最完美的结局——只是，这两个人同样拥有知晓真相的权利……</>）",
          DialogueId = 51000891,
          GUID = "7FACE5AE",
          NextDialogue = 51000892,
          Subtitle = "(Then the girl would have a warm hearth to return to, and Elsa would have her \"daughter\" back. This seems like the perfect ending — except, they both have the right to know the truth...)"
        },
        [51000892] = {
          Content = "（应该做出怎样的选择？将真相告知二人，还是这样将错就错下去？）",
          DialogueId = 51000892,
          GUID = "7FACE5D8",
          NextOptions = {
            [1] = 510008921,
            [2] = 510008121
          },
          Subtitle = "(The dilemma stands: to unveil the harsh truth or perpetuate the comforting falsehood?)",
          bForbidSkipOptions = true
        },
        [51000893] = {
          Content = "这是……我写的……",
          DialogueId = 51000893,
          GUID = "7FACE602",
          NextDialogue = 51000804,
          SpeakNpcId = 700032,
          Subtitle = "This is... something I wrote..."
        },
        [51000894] = {
          Content = "安妮……原来这就是我的名字啊。总觉得稍微有点陌生呢……",
          DialogueId = 51000894,
          GUID = "7FACE62C",
          NextDialogue = 51000895,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Annie... So that's my name. Has a strange ring to it..."
        },
        [51000895] = {
          Content = "抱歉，我都忘了……谢谢，真的谢谢你！带我去找妈妈吧，她一定会重谢你的！",
          DialogueId = 51000895,
          GUID = "7FACE656",
          NextOptions = {
            [1] = 510008141
          },
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Sorry, I really don't remember a thing... Thank you, really, thank you so much! Could you take me to my mother? She will definitely give you a ton of thank-you gifts!",
          bForbidSkipOptions = true
        },
        [51000901] = {
          Content = "陌生的客人！什么风把您吹到了我这里来？不过您要是想找点乐子，到马丁这来看看准没错！",
          DialogueId = 51000901,
          GUID = "7FACE752",
          NextDialogue = 51000902,
          SpeakNpcId = 700022,
          Subtitle = "A new customer! What brings you here? But if you're looking for some fun, you've come to the right place with Martin!",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000902] = {
          Content = "（面前的男人对你行了一个花里胡哨的大礼，然后变戏法一样摆出一堆错落的商品）",
          DialogueId = 51000902,
          GUID = "7FACE77C",
          NextDialogue = 51000903,
          SpeakNpcId = 700022,
          Subtitle = "(The man in front of you performs an extravagant bow, then magically displays a bunch of scattered goods.)"
        },
        [51000903] = {
          Content = "随意挑选，相信马丁的品味！您见过的没见过的都能在这里找到，偶尔给自己的生活带来点小惊喜！",
          DialogueId = 51000903,
          GUID = "7FACE7A6",
          SpeakNpcId = 700022,
          Subtitle = "Feel free to choose. Trust Martin's choice! You can find everything here, seen or unseen, occasionally spicing up your life!",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          },
          TalkOptions = {
            [1] = 510009031,
            [2] = 510009032,
            [3] = 510009033
          }
        },
        [51000904] = {
          Content = "你可真没礼貌~会估价可不等于你是个有品味的人，甜心。",
          DialogueId = 51000904,
          GUID = "7FACE7D0",
          SpeakNpcId = 700022,
          Subtitle = "You're quite impolite. Being able to appraise doesn't mean you have good taste, sweetheart.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000905] = {
          Content = "任由它们浪费难道不也是一种犯罪吗？我只是想给他们都找一个家~",
          DialogueId = 51000905,
          GUID = "7FACE7FA",
          SpeakNpcId = 700022,
          Subtitle = "Isn't letting them go to waste also a crime? I just want to find a home for them all.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000906] = {
          Content = "哦~这可是商业机密。你想好用什么来和我交换了吗？",
          DialogueId = 51000906,
          GUID = "7FACE824",
          SpeakNpcId = 700022,
          Subtitle = "Nah-ah. That's a trade secret. So, have you thought about what you'd like to exchange with me?",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000907] = {
          Content = "（你看了看他的商品，遗憾地摇了摇头）",
          DialogueId = 51000907,
          GUID = "7FACE84E",
          Subtitle = "(You look at his goods and sadly shake your head.) ",
          TalkOptions = {
            [1] = 510009072
          }
        },
        [51000908] = {
          Content = "那我大概不是你需要的那种人，但我会等到你愿意惠顾的那天的。",
          DialogueId = 51000908,
          GUID = "7FACE878",
          SpeakNpcId = 700022,
          Subtitle = "Then I'm probably not the person you need, but I'll wait for the day you extend your patronage."
        },
        [51000909] = {
          Content = "我明白了！你是这个冰湖城里很罕见的一种人……",
          DialogueId = 51000909,
          GUID = "7FACE8A2",
          NextDialogue = 51000910,
          SpeakNpcId = 700022,
          Subtitle = "I got it! You're a rare kind of person in Icelake…",
          TalkActionId = {
            [1] = "700022:Think_Start"
          }
        },
        [51000910] = {
          Content = "你既不是来采购廉价物资的贫民窟居民，也不是对邻居的私生活大有兴趣的贵族老爷，你对马丁无欲无求，甚至你从来没听过我的名字，对不对？",
          DialogueId = 51000910,
          GUID = "7FACE8CC",
          SpeakNpcId = 700022,
          Subtitle = "You're neither a slum dweller here to buy cheap supplies nor a noble interested in the private lives of your neighbors. You have no desire or need for Martin. You've never even heard my name, have you?",
          TalkActionId = {
            [1] = "700022:Think_End"
          },
          TalkOptions = {
            [1] = 510009101,
            [2] = 510009102,
            [3] = 510009103
          }
        },
        [51000911] = {
          Content = "那请容我为您自我介绍！我是冰湖城的拾荒者之王，每个垃圾桶的知心兄弟，废弃物品最好的代言者与推销者。",
          DialogueId = 51000911,
          GUID = "7FACE8F6",
          NextDialogue = 51000990,
          SpeakNpcId = 700022,
          Subtitle = "Then allow me to introduce myself! I am the King of Scavengers in Icelake, the confidant brother of every rubbish bin, and the best spokesperson and promoter of discarded items. ",
          TalkActionId = {
            [1] = "700022:Confident_Start"
          }
        },
        [51000912] = {
          Content = "事实上，垃圾桶里隐藏着各式各样的秘密，只要你足够耐心，不辞辛苦……它们就会把这户人家的心事源源不断地告诉你。",
          DialogueId = 51000912,
          GUID = "7FACE920",
          SpeakNpcId = 700022,
          Subtitle = "In fact, rubbish bins hide all sorts of secrets. As long as you're patient enough and don't mind the hard work, they will continue to share with you the secrets of their households.",
          TalkActionId = {
            [1] = "700022:Confident_End"
          }
        },
        [51000913] = {
          Content = "你好奇了？真不错。我知道，惯常的商品打动不了你们，但马丁有自己的办法。",
          DialogueId = 51000913,
          GUID = "7FACE94A",
          NextDialogue = 51000991,
          SpeakNpcId = 700022,
          Subtitle = "Now you get intrigued? That's great. I know ordinary goods won't impress you, but Martin has his ways.",
          TalkActionId = {
            [1] = "700022:Explain01_Start"
          }
        },
        [51000914] = {
          Content = "如果你们能帮它们找到主人，或许就能更加了解这个城市，哪怕什么也没得到，至少你们满足了自己的好奇心。",
          DialogueId = 51000914,
          GUID = "7FACE974",
          NextDialogue = 51000915,
          SpeakNpcId = 700022,
          Subtitle = "If you can help find their owners, you might understand this city better. Even if you get nothing, at least you satisfy your curiosity.",
          TalkActionId = {
            [1] = "700022:Explain01_End"
          }
        },
        [51000915] = {
          Content = "（马丁变出了一些无法具体名状的东西，然后朝着你们挤了挤眼睛。）",
          DialogueId = 51000915,
          GUID = "7FACE99E",
          NextDialogue = 51000916,
          Subtitle = "(Martin produces some indescribable things and winks at you.)"
        },
        [51000916] = {
          Content = "想试试吗？",
          DialogueId = 51000916,
          GUID = "7FACE9C8",
          SpeakNpcId = 700022,
          Subtitle = "Want to give it a try?",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000917] = {
          Content = "祝您寻人顺利，侦探阁下。",
          DialogueId = 51000917,
          GUID = "7FACE9F2",
          SpeakNpcId = 700022,
          Subtitle = "Good luck, Detective.",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          }
        },
        [51000918] = {
          Content = "进展得还顺利吗，侦探阁下？",
          DialogueId = 51000918,
          GUID = "7FACEA1C",
          SpeakNpcId = 700022,
          Subtitle = "Everything going well, Detective?"
        },
        [51000990] = {
          Content = "我的名字想必已经无需重复，我就是马丁。",
          DialogueId = 51000990,
          GUID = "7FACF5EC",
          NextDialogue = 51000912,
          SpeakNpcId = 700022,
          Subtitle = "My name probably speaks for itself. I am Martin."
        },
        [51000991] = {
          Content = "我愿意把“谜题”卖给你们，你们可以把它们当做“某人的心结”或者“失物”。",
          DialogueId = 51000991,
          GUID = "7FACF616",
          NextDialogue = 51000914,
          SpeakNpcId = 700022,
          Subtitle = "I'm willing to sell \"puzzles\" to you. You can treat them as \"someone's scars\" or \"lost items\"."
        },
        [51001001] = {
          Camera = "30.150391,500.332031,170.427734,0.000075,-9.398094,-93.777969,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（你远远地就看到一个商贩打扮的人站在售票处，他和售票员似乎起了些摩擦）",
          DialogueId = 51001001,
          GUID = "7FACF7BA",
          LookAt = {
            [1] = "700021:n(700033)"
          },
          NextDialogue = 51001002,
          Subtitle = "(You see a person dressed as a vendor at the ticket counter, seemingly in a dispute with the ticket seller.)"
        },
        [51001002] = {
          Camera = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
          Content = "我只是问问都不行吗！你妈妈没教你礼貌吗？！",
          DialogueId = 51001002,
          GUID = "7FACF7E4",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001003,
          SpeakNpcId = 700033,
          Subtitle = "Can't I even ask? Didn't your mother teach you manners?!",
          TalkActionId = {
            [1] = "700033:Angry01_Start"
          }
        },
        [51001003] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          Content = "哦好的先生，那么在我礼貌地告诉你票价后，你打算怎么做？",
          DialogueId = 51001003,
          GUID = "7FACF80E",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001090,
          SpeakNpcId = 700021,
          Subtitle = "Oh alright, sir. So, after I politely tell you the ticket price, what do you plan to do?",
          TalkActionId = {
            [1] = "700021:Talk01_Start"
          }
        },
        [51001004] = {
          Camera = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
          Content = "你你怎么知道我没……",
          DialogueId = 51001004,
          GUID = "7FACF838",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001005,
          SpeakNpcId = 700033,
          Subtitle = "H...How do you know I don't have...",
          TalkActionId = {
            [1] = "700033:Angry01_End"
          }
        },
        [51001005] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          Content = "滚吧住在窝棚板里的大富豪。",
          DialogueId = 51001005,
          GUID = "7FACF862",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001091,
          SpeakNpcId = 700021,
          Subtitle = "Off you go, you shack-dwelling tycoon.",
          TalkActionId = {
            [1] = "700021:Talk01_End"
          }
        },
        [51001006] = {
          Camera = "319.767578,148.608398,91.180664,0.000064,-0.797267,-149.347275,35.0,400.0,false,Manual,2.8",
          Content = "（商贩哆嗦着嘴唇转身就走，而售票员高傲地哼了一声，不屑地瞥向你们。）",
          DialogueId = 51001006,
          GUID = "7FACF88C",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001007,
          Scripts = "MoveTo{ActorId{700033},TargetPoint{\"Point200202_Shangfan\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          Subtitle = "(The vendor leaves, lips trembling, while the ticket seller snorts arrogantly, glancing disdainfully at you.) "
        },
        [51001007] = {
          Content = "你呢？你又有什么事？我劝你不要浪费我的时间，不然你只能和他一样灰溜溜地滚回自己的老鼠洞。",
          DefaultLookAt = "Self",
          DialogueId = 51001007,
          GUID = "7FACF8B6",
          LookAt = {
            [1] = "0:n(700021)"
          },
          SpeakNpcId = 700021,
          Subtitle = "What about you? What do you want? I advise you not to waste my time, or you'll slink back into your rat hole just like him.",
          TalkActionId = {
            [1] = "700021:Talk03_Start"
          },
          TalkOptions = {
            [1] = 510010071,
            [2] = 510010072
          },
          TurnTo = {
            [1] = "700021:n(0)"
          }
        },
        [51001008] = {
          Content = "又一个！我不管你在虚张声势些什么，在我对你发出诚挚的问候之前，你最好赶紧消失！",
          DialogueId = 51001008,
          GUID = "7FACF8E0",
          SpeakNpcId = 700021,
          Subtitle = "Not another one! Before I send you my sincerest regards, you'd better disappear quickly!",
          TalkActionId = {
            [1] = "700021:Talk03_End"
          }
        },
        [51001009] = {
          Content = "你、你在说什么，我可听不懂！",
          DialogueId = 51001009,
          GUID = "7FACF90A",
          NextDialogue = 51001010,
          SpeakNpcId = 700021,
          Subtitle = "W...What are you talking about? I don't understand!",
          TalkActionId = {
            [1] = "700021:Talk03_End"
          }
        },
        [51001010] = {
          Content = "（你拿出从马丁那拿来的“废品”，一罐用纸叠出来的五角星，你展开其中一颗，俨然是一张已经过期的废票。）",
          DialogueId = 51001010,
          GUID = "7FACF934",
          Subtitle = "(You take out the \"scrap\" you got from Martin, a jar of pentagonal stars made of paper. You unfold one to find out it's clearly an expired ticket.)"
        },
        [51001012] = {
          Content = "……",
          DialogueId = 51001012,
          GUID = "7FACF988",
          NextDialogue = 51001013,
          SpeakNpcId = 700021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700021:Shock_Start"
          }
        },
        [51001013] = {
          Content = "（她好像陷入了极度的震惊，很快，两行眼泪从这个趾高气昂的售票员脸上流了下来。）",
          DialogueId = 51001013,
          GUID = "7FACF9B2",
          NextDialogue = 51001014,
          Subtitle = "(She seems extremely shocked. Before you know it, tears are streaming down the face of this haughty ticket seller.)"
        },
        [51001014] = {
          Content = "为什么……为什么要让我再看到它？",
          DialogueId = 51001014,
          GUID = "7FACF9DC",
          NextDialogue = 51001015,
          SpeakNpcId = 700021,
          Subtitle = "Why... Why do you have to show this to me again?",
          TalkActionId = {
            [1] = "700021:Shock_End"
          }
        },
        [51001015] = {
          Content = "为什么要提醒我不能实现的梦？",
          DialogueId = 51001015,
          GUID = "7FACFA06",
          NextDialogue = 51001016,
          SpeakNpcId = 700021,
          Subtitle = "Why remind me of dreams that can't be fulfilled?",
          TalkActionId = {
            [1] = "700021:Disagree"
          }
        },
        [51001016] = {
          Content = "每天，我看着火车轰鸣而来，又看着它呼啸而去，我希望能和那些达官贵人一样乘上去，但留给我的只有卖不完的票。",
          DialogueId = 51001016,
          GUID = "7FACFA30",
          NextDialogue = 51001017,
          SpeakNpcId = 700021,
          Subtitle = "Every day, I watch trains roar in and out. I hope to ride them like those high officials, but all I have are unsold tickets.",
          TalkActionId = {
            [1] = "700021:Explain02_Start"
          }
        },
        [51001017] = {
          Content = "有的人活了一辈子都没见过车票长什么样，我比他们的运气好一些，好歹能每天都握着这张无法兑现的入场券。",
          DialogueId = 51001017,
          GUID = "7FACFA5A",
          NextDialogue = 51001018,
          SpeakNpcId = 700021,
          Subtitle = "Some people live their entire lives without seeing a ticket. I'm luckier because at least I get to hold an unfulfillable entry pass every day."
        },
        [51001018] = {
          Content = "但我的好运也就到此为止了，这个世界上有的是连星星都无法实现的愿望，我正是意识到这一点，才将它们丢弃……",
          DialogueId = 51001018,
          GUID = "7FACFA84",
          SpeakNpcId = 700021,
          Subtitle = "But that's where my luck ends. In this world, there are wishes even stars can't fulfil. I realised this, and that's why I threw them away...",
          TalkActionId = {
            [1] = "700021:Explain02_End"
          },
          TalkOptions = {
            [1] = 510010181,
            [2] = 510010182,
            [3] = 510010183,
            [4] = 510010184
          }
        },
        [51001019] = {
          Content = "那么谁来为我搭这条天梯呢？仙女教母吗？",
          DialogueId = 51001019,
          GUID = "7FACFAAE",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "Then who will build this ladder to heaven for me? The Fairy Godmother?"
        },
        [51001020] = {
          Content = "你说得对，我和他们又有什么差别呢？",
          DialogueId = 51001020,
          GUID = "7FACFAD8",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "You're right. How am I any different from them?"
        },
        [51001021] = {
          Content = "是啊……我还不能失去这份我痛恨又赖以生存的工作。",
          DialogueId = 51001021,
          GUID = "7FACFB02",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "You're right... I can't lose this job that I hate yet make a living from."
        },
        [51001022] = {
          Content = "我是有些疾世愤俗，但还没发疯，不过也许那一天也不远了。",
          DialogueId = 51001022,
          GUID = "7FACFB2C",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "I might be disillusioned with the world, but I'm not crazy yet, though that day might not be far off."
        },
        [51001023] = {
          Content = "（售票员拿走了你手中的车票星星，找了个干燥的地方将这些寄宿着心愿的纸片付之一炬）",
          DialogueId = 51001023,
          GUID = "7FACFB56",
          NextDialogue = 51001024,
          SpeakNpcId = 700021,
          Subtitle = "(The ticket seller takes the ticket stars from your hand, finds a dry place, and sets these wish-bearing papers on fire.)"
        },
        [51001024] = {
          Content = "我总是骂那些想离开的家伙是做梦，",
          DialogueId = 51001024,
          GUID = "7FACFB80",
          NextDialogue = 51001025,
          SpeakNpcId = 700021,
          Subtitle = "I always scold those who want to leave as dreamers,",
          TalkActionId = {
            [1] = "700021:Explain01_Start"
          }
        },
        [51001025] = {
          Content = "但也许该从梦中醒来的是我自己。",
          DialogueId = 51001025,
          GUID = "7FACFBAA",
          NextDialogue = 51001026,
          SpeakNpcId = 700021,
          Subtitle = "but maybe it's me who should wake up from the dream.",
          TalkActionId = {
            [1] = "700021:Explain01_End"
          }
        },
        [51001026] = {
          Content = "（从此以后，杰西卡只是漠然地坐在售票厅里，不管谁问她都能得到机械的回答，好像某种售票的机器。）",
          DialogueId = 51001026,
          GUID = "7FACFBD4",
          Subtitle = "(From then on, Jessica just sat indifferently in the ticket hall, giving mechanical responses to anyone who asked like a ticket machine.)"
        },
        [51001027] = {
          Content = "……",
          DialogueId = 51001027,
          GUID = "7FACFBFE",
          SpeakNpcId = 700021,
          Subtitle = "..."
        },
        [51001090] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          Content = "是礼貌地掏出一笔巨款向我买票，还是搓搓自己漏不出一个子儿的裤兜对我颐指气使？",
          DialogueId = 51001090,
          GUID = "7FAD0654",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001004,
          SpeakNpcId = 700021,
          Subtitle = "Will you politely pull out a huge amount of money to buy a ticket, or will you fiddle with your empty pockets and boss me around?"
        },
        [51001091] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          Content = "这天气正适合你一边擦火柴一边叫奶奶，在梦里亲奶奶带你坐火车，到时候你想去哪去哪，再也不用在我跟前丢人现眼！",
          DialogueId = 51001091,
          GUID = "7FAD067E",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001006,
          SpeakNpcId = 700021,
          Subtitle = "This weather is just right for you to strike a match and call for grandma, dreaming that she takes you on a train. Go wherever you like in your dream, and stop shaming yourself in front of me!"
        },
        [51001092] = {
          Content = "（不过好事是她再也不像从前一样脾气暴躁，骂骂咧咧了。）",
          DialogueId = 51001092,
          GUID = "7FAD06A8",
          Subtitle = "(But the good thing is she was no longer as temperamental and foul-mouthed as before.)"
        },
        [51001101] = {
          Content = "（不知从何处游荡而来的秽兽叼着一个记事本，击败秽兽后，你将它捡了起来……）",
          DialogueId = 51001101,
          GUID = "7FAD0822",
          NextDialogue = 51001102,
          Subtitle = "(A Filthoid, wandering from nowhere, clutched a notebook in its jaws. After defeating the Filthoid, you picked up the notebook...)"
        },
        [51001102] = {
          Content = "（如果日记上记录的内容属实，那么失忆少女的真实身份，就已十分明了了。同样水落石出的，还有爱尔莎夫人那个失踪的女儿，安妮的下落……）",
          DialogueId = 51001102,
          GUID = "7FAD084C",
          NextDialogue = 51001103,
          Subtitle = "(If the words in this diary are true... then the truth is clear at last.)"
        },
        [51001103] = {
          Content = "（……安妮已经不幸离世，而得到她衣物的另一位少女爱丽丝活了下来。尽管在雪山幸存，但连续高烧还是夺走了爱丽丝的记忆。）",
          DialogueId = 51001103,
          GUID = "7FAD0876",
          Subtitle = "(...Annie has tragically passed away, while the other girl, Alice, who ended up with Annie's clothes, has survived. Although Alice made it through the ordeal in the snowy mountains, the severe fevers she suffered afterwards took away her memories.)"
        },
        [51001201] = {
          ContentES = "¿{性别:Un Phoxcazador|Una Phoxcazadora}? Nunca habría creído que uno de ellos llegaría a este lugar... Tú también debes tener lo necesario para convertirte en {性别:un héroe|una heroína}.",
          DialogueId = 51001201,
          GUID = "7FAD188A",
          NextDialogue = 51001212,
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001202] = {
          ContentES = "Eh, sí. Aparte de este viejo loco que soy, nadie más se molesta en criar pájaro de plumas doradas hoy en día.",
          DialogueId = 51001202,
          GUID = "7FAD18B4",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Well, who else but this old geezer would bother keeping these birds nowadays.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001203] = {
          ContentES = "¿Comerlos? ¿Sabes cuán valiosos son estos pájaros para un minero?!",
          DialogueId = 51001203,
          GUID = "7FAD18DE",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Are you insane?? Do you have any idea how precious these birds are to a miner?!",
          TalkActionId = {
            [1] = "700003:Disagree"
          }
        },
        [51001204] = {
          ContentES = "Los mineros dependen cada vez más de los chismes de alta tecnología fabricados por la Academia de Alquimia... hasta el punto de olvidar los métodos tradicionales.",
          DialogueId = 51001204,
          GUID = "7FAD1908",
          NextOptions = {
            [1] = 510012041,
            [2] = 510012042,
            [3] = 510012043
          },
          SpeakNpcId = 700003,
          Subtitle = "Miners today have grown so reliant on the high-tech gadgets from the Alchemy Academy, that they have forgotten the old ways.",
          bForbidSkipOptions = true
        },
        [51001205] = {
          ContentES = "Exactamente. Su sensibilidad excepcional a los gases tóxicos los convertía en compañeros indispensables en nuestras antiguas expediciones. Siempre llevábamos a uno de ellos con nosotros bajo tierra para comprobar si los túneles eran seguros.",
          DialogueId = 51001205,
          GUID = "7FAD1932",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Exactly, their amazing sensitivity to harmful gases made them a must-have for us miners in the old days. We'd always have one by our side underground to help detect whether the tunnels were safe.",
          TalkActionId = {
            [1] = "700003:Agree"
          }
        },
        [51001206] = {
          ContentES = "Bien dicho. Hoy en día ya no hay muchos jóvenes capaces de tal reflexión.",
          DialogueId = 51001206,
          GUID = "7FAD195C",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Well said. Quite rare to find young folks with such insight these days.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001207] = {
          ContentES = "Hmpf. Hago todo esto por los mineros, no para obtener la aprobación de los demás.",
          DialogueId = 51001207,
          GUID = "7FAD1986",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Hmph, I do what I do for us miners' sake. I don't need others' approval.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001208] = {
          ContentES = "Las herramientas sin alma pueden fallar... incluso traicionarte. Pero un compañero al que le has ofrecido tu afecto siempre estará ahí para afrontar las pruebas a tu lado.",
          DialogueId = 51001208,
          GUID = "7FAD19B0",
          NextDialogue = 51001209,
          SpeakNpcId = 700003,
          Subtitle = "Soulless tools may fail you, or even betray you. It's the companion you've always cherished that will stand by you through every trial.",
          TalkActionId = {
            [1] = "700003:Think_Start"
          }
        },
        [51001209] = {
          ContentES = "El día en que los detectores de la Academia fallen, tal vez serán estos compañeros leales los que salvarán la vida de los mineros...",
          DialogueId = 51001209,
          GUID = "7FAD19DA",
          NextDialogue = 51001210,
          SpeakNpcId = 700003,
          Subtitle = "Should the day come when the Academy's fancy tools give out, it may well be these loyal friends that save miners' lives...",
          TalkActionId = {
            [1] = "700003:Think_End"
          }
        },
        [51001210] = {
          ContentES = "(El viejo minero dirige su mirada hacia un montículo de tierra cercano. Sus labios se mueven, como si quisiera decir algo... pero todo lo que sale de su boca es un profundo suspiro.)",
          DialogueId = 51001210,
          GUID = "7FAD1A04",
          Subtitle = "(The old miner's gaze settles on a nearby mound, his lips trembling with unvoiced thoughts, culminating in nothing but a weary sigh.)"
        },
        [51001211] = {
          ContentES = "(Permanece en silencio. De vez en cuando, sale de sus pensamientos para dar un largo suspiro. ¿Era un homenaje a un compañero desaparecido... o una lamentación por un mundo que cambia demasiado rápido?)",
          DialogueId = 51001211,
          GUID = "7FAD1A2E",
          Subtitle = "(In silence, the elder periodically snaps from his thoughts, letting out a lingering sigh. It's unclear whether it's a tribute to a fallen comrade or a lament for the changing times.)"
        },
        [51001212] = {
          Content = "老人温柔地注视着空中的一小片黑点，你顺着他的视线远眺，看到了一群离去的飞鸟。待到所有鸟群飞走后，老人才转身继续与你交谈。",
          DialogueId = 51001212,
          GUID = "7FAD188B",
          NextOptions = {
            [1] = 510012011,
            [2] = 510012012
          },
          Subtitle = "The elder watched a dark speck in the sky with a soft gaze. You looked out and saw a distant flock of birds. The conversation resumed only after the last one had vanished.",
          bForbidSkipOptions = true
        },
        [51001301] = {
          Content = "天杀的卡米拉！不识货的瞎眼婆娘！",
          DialogueId = 51001301,
          GUID = "7FAD28F2",
          NextDialogue = 510013013,
          SpeakNpcId = 700014,
          Subtitle = "That blasted Camilla! Stupid hag! She has no idea what good stuff tastes like!"
        },
        [51001302] = {
          Content = "我呸！老子骂两句怎么了！",
          DialogueId = 51001302,
          GUID = "7FAD291C",
          NextDialogue = 51001304,
          SpeakNpcId = 700014,
          Subtitle = "Pah! What's it to you?"
        },
        [51001303] = {
          Content = "医药费！必须给我医药费！你快把我鼻子打歪了！",
          DialogueId = 51001303,
          GUID = "7FAD2946",
          NextDialogue = 51001304,
          SpeakNpcId = 700014,
          Subtitle = "Ugh! You must pay for this! Gimme your money! Nearly broke my nose, you!"
        },
        [51001304] = {
          Content = "这么着急替她出头？哈，我知道了，你也是“卡米拉后援会”的蠢蛋之一！可悲啊，被那个虚伪的女人骗得团团转！",
          DialogueId = 51001304,
          GUID = "7FAD2970",
          NextOptions = {
            [1] = 510013041,
            [2] = 510013042,
            [3] = 510013043
          },
          SpeakNpcId = 700014,
          Subtitle = "Jumping to her defence, are we? Ha, you must be one of those \"Camilla fan club\" idiots! Pathetic losers, all bamboozled by that two-faced witch!",
          bForbidSkipOptions = true
        },
        [51001305] = {
          Content = "嘴巴刚刚不还挺能说的吗，怎么，脑袋终于被冷风吹醒，看清那婆娘了？",
          DialogueId = 51001305,
          GUID = "7FAD299A",
          SpeakNpcId = 700014,
          Subtitle = "Had a sharp tongue just now, didn't ya? What, did the cold finally clear your head enough to see through that hag?"
        },
        [51001306] = {
          Content = "你，你说什么……",
          DialogueId = 51001306,
          GUID = "7FAD29C4",
          NextDialogue = 510013061,
          SpeakNpcId = 700014,
          Subtitle = "Wh—What are you talking about..."
        },
        [51001307] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          Content = "如果你货比三家，就会发现卡米拉售卖的发酵饮品和冰湖城格格不入。",
          DialogueId = 51001307,
          GUID = "7FAD29EE",
          LookAt = {
            [1] = "700014:n(100001)",
            [2] = "100001:n(700014)"
          },
          NextDialogue = 51001308,
          SpeakNpcId = 700014,
          Subtitle = "If you shopped around, you'd see Camilla's brew is an odd fit for Icelake.",
          TalkActionId = {
            [1] = "700014:Explain01_Start"
          }
        },
        [51001308] = {
          Content = "冰湖城里所有的饮品老板都和我有合作，我家的手艺有口皆碑，只有她拒绝加入，油盐不进的家伙！你就不觉得这里面有猫腻吗？！",
          DialogueId = 51001308,
          GUID = "7FAD2A18",
          NextDialogue = 51001309,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{700014},AnimationId{\"Explain02_End\"},Duration{0}}",
          SpeakNpcId = 700014,
          Subtitle = "I mean, in Icelake, every tavern owner except her is my client. My stuff's good enough to knock people out, but she always turns me down — what a stubborn mule! Doesn't that seem fishy to you?",
          TalkActionId = {
            [1] = "700014:Explain02_Start"
          }
        },
        [51001309] = {
          Content = "事实是，我的发酵饮品价格只有卡米拉的一半，而且口味几乎没有差别，我敢保证！只要在我这里尝试一次，就能体会到“实惠”的味道。",
          DialogueId = 51001309,
          GUID = "7FAD2A42",
          NextOptions = {
            [1] = 510013091,
            [2] = 510013092
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"87.344482,-123.555176,125.176514,0.000141,5.699588,170.405472,35.000008,177.462952,false,Manual,5.0"},duration{0}},
LookAt{_delay{5.2},LookAtDescription{"100001:n(100001)"}},
PlayAnimation{_delay{5.5},ActorId{100001},AnimationId{"Think_Start"},Duration{0.5}},
PlayAnimation{_delay{5.5},ActorId{700014},AnimationId{"Talk01_End"},Duration{0.5}}
}]],
          SpeakNpcId = 700014,
          Subtitle = "Fact is, my booze is half the price of Camilla's and tastes just as good — I assure you! Try it, and you'll understand what a real bargain means.",
          TalkActionId = {
            [1] = "700014:Talk01_Start"
          }
        },
        [51001310] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          Content = "哈哈，还是您有眼光，多谢惠顾！",
          DialogueId = 51001310,
          GUID = "7FAD2A6C",
          NextDialogue = 51001311,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{\"Agree\"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "Ha, now we're talking! Thanks for your patronage!",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51001311] = {
          Camera = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
          Content = "慢着！等一下。",
          DialogueId = 51001311,
          GUID = "7FAD2A96",
          LookAt = {
            [1] = "700014:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001312,
          Scripts = [[
PARA{
MoveTo{_delay{1},ActorId{200003},TargetPoint{"PDien1"},MoveSpeed{60},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{1},TargetPosition{"35.446289,521.132324,214.651123,0.000096,-10.999998,-89.999939,45.0,388.895966,false,Manual,5.0"},duration{3}},
CameraMoveTo{TargetPosition{"-104.617432,-216.151855,139.375488,0.000126,-2.100092,62.600006,35.0,384.123901,false,Manual,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"-146.654297,-177.086426,138.553223,0.000128,-0.500031,40.001247,35.0,272.58197,false,Manual,5.0"},duration{2.5}}
},
TurnTo{_delay{2.5},TurnToDescription{"100001:n(200003)"}},
TurnTo{_delay{5},TurnToDescription{"700014:n(200003)"}},
LookAt{_delay{6.5},LookAtDescription{"200003:n(100001)"}},
PlayAnimation{_delay{6.7},ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Hold on a moment."
        },
        [51001312] = {
          Content = "冰湖城的人啊，无论是谁，说的话你只信一半就好。",
          DialogueId = 51001312,
          GUID = "7FAD2AC0",
          NextDialogue = 51001315,
          SpeakNpcId = 200003,
          Subtitle = "Just a word of advice — always take what you hear in Icelake with a grain of salt."
        },
        [51001313] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          Content = "别算了啊，你不试试怎么知道——",
          DialogueId = 51001313,
          GUID = "7FAD2AEA",
          NextDialogue = 51001314,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "Come on, give it a try and you'll—",
          TalkActionId = {
            [1] = "700014:Talk01_Start",
            [2] = "100001:Think_End"
          }
        },
        [51001314] = {
          Camera = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
          Content = "不错嘛，看来你还保持着最基本的戒心。",
          DialogueId = 51001314,
          GUID = "7FAD2B14",
          LookAt = {
            [1] = "700014:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001315,
          Scripts = [[
PARA{
MoveTo{_delay{1},ActorId{200003},TargetPoint{"PDien1"},MoveSpeed{60},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{1},TargetPosition{"35.446289,521.132324,214.651123,0.000096,-10.999998,-89.999939,45.0,388.895966,false,Manual,5.0"},duration{3}},
CameraMoveTo{TargetPosition{"-104.617432,-216.151855,139.375488,0.000126,-2.100092,62.600006,35.0,384.123901,false,Manual,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"-122.449951,-202.495117,138.553223,0.000128,-1.900083,50.401207,35.0,272.58197,false,Manual,5.0"},duration{2.5}}
},
TurnTo{_delay{2.5},TurnToDescription{"100001:n(200003)"}},
TurnTo{_delay{5},TurnToDescription{"700014:n(200003)"}},
LookAt{_delay{6.5},LookAtDescription{"200003:n(100001)"}},
PlayAnimation{_delay{6.7},ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Not bad — I see you're keeping your wits about you."
        },
        [51001315] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          Content = "你你、你想干什么！怎么还挡着别人做生意？",
          DialogueId = 51001315,
          GUID = "7FAD2B3E",
          LookAt = {
            [1] = "200003:n(700014)"
          },
          NextDialogue = 51001316,
          SpeakNpcId = 700014,
          Subtitle = "Wh—What do you want!? I didn't go to your place and meddle in your business!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          }
        },
        [51001316] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          Content = "别误会，我对你的买卖没什么兴趣，我来找你是要和你谈谈另一件事。",
          DialogueId = 51001316,
          GUID = "7FAD2B68",
          NextDialogue = 51001317,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "Don't get me wrong, I'm not interested in your business. I'm here to discuss something else with you.",
          TalkActionId = {
            [1] = "200003:Talk03_End",
            [2] = "700014:Angry01_End"
          },
          TurnTo = {
            [1] = "100001:p(-30)"
          }
        },
        [51001317] = {
          Content = "最近总有人冒用我的名字到处贩卖劣质的假货，说什么“这是水仙平原推出的新品”啦，“在水仙平原的吧台上被一抢而光，想喝都喝不到”啦……",
          DialogueId = 51001317,
          GUID = "7FAD2B92",
          NextDialogue = 51001318,
          Scripts = "PlayAnimation{_delay{3},ActorId{200003},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "Recently, someone's been using my name to sell shoddy knock-offs, claiming they're \"the new special from The Asphodel\", or that they'd be \"sold out at the bar in a minute, impossible to snag a sip...\"",
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001318] = {
          Content = "你也知道，做生意讲究的无非就是个信誉，酒水的质量关乎水仙平原的脸面，我总不能任由他人到处抹黑。",
          DialogueId = 51001318,
          GUID = "7FAD2BBC",
          NextDialogue = 51001319,
          SpeakNpcId = 200003,
          Subtitle = "As you know, in business, brand image is everything. The quality of our drinks is the face of The Asphodel, and I can't just let someone drag our name through the mud.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001319] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          Content = "这、这……这和我有什么关系？我可没工夫多管你的闲事！",
          DialogueId = 51001319,
          GUID = "7FAD2BE6",
          NextDialogue = 51001320,
          Scripts = "PlayAnimation{_delay{3},ActorId{700014},AnimationId{\"Sigh_End\"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "...Wh—What's that got to do with me? I don't have time for your problems!",
          TalkActionId = {
            [1] = "700014:Sigh_Start"
          }
        },
        [51001320] = {
          Content = "让开让开，我要走了，你不做生意我还得做呢。",
          DialogueId = 51001320,
          GUID = "7FAD2C10",
          NextDialogue = 51001321,
          SpeakNpcId = 700014,
          Subtitle = "Outta my way. I've got business to run.",
          TalkActionId = {
            [1] = "700014:Confident_Start"
          }
        },
        [51001321] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          Content = "走？就在不久前水仙平原拒绝与你合作的时候，我让人保留了一份你售卖的酒水样本，你猜怎么样？",
          DialogueId = 51001321,
          GUID = "7FAD2C3A",
          NextDialogue = 51001322,
          SpeakNpcId = 200003,
          Subtitle = "Not so fast. When The Asphodel turned you down, I kept a sample of your booze. And guess what—"
        },
        [51001322] = {
          Content = "你带来的货品和市面上那些冒充水仙平原的假货成分一模一样。这恐怕不仅仅是巧合这么简单吧？",
          DialogueId = 51001322,
          GUID = "7FAD2C64",
          NextDialogue = 51001323,
          SpeakNpcId = 200003,
          Subtitle = "Your booze exactly matches the knock-offs on the market. Seems more than coincidental, wouldn't you say?"
        },
        [51001323] = {
          Camera = "-209.837891,-298.262207,123.758301,0.000147,1.099674,42.806149,35.000008,408.143951,false,Manual,5.0",
          Content = "什么意思！你少血口喷人！我我我、我怎么可能卖假货！你就是怕我的酒抢了你的老主顾，才、才在这里胡说八道！",
          DialogueId = 51001323,
          GUID = "7FAD2C8E",
          NextOptions = {
