          },
          NextDialogue = 51001327,
          SpeakNpcId = 700014,
          Subtitle = "...Fine! That'll show her!"
        },
        [51001327] = {
          Content = "（迪恩双手抱住一桶酒，仰头痛饮。）",
          DialogueId = 51001327,
          GUID = "7FAD2D36",
          IsBlack = 1,
          LookAt = {
