        },
        [51001328] = {
          Camera = "-58.997803,-300.757812,211.441162,0.000378,-35.900509,52.402233,35.000008,288.862579,false,Manual,5.0",
          Content = "（可不等迪恩喝完，他仿佛就像是被人打了一拳，身形一晃重重砸在地上，洒在地上的液体仍然散发着浓郁的气味。）",
          DialogueId = 51001328,
          FinalCamera = "-163.664062,-436.681641,303.508057,0.000378,-35.900513,52.404461,35.000008,288.862579,false,Manual,5.0",
          GUID = "7FAD2D60",
          LookAt = {
            [1] = "700014:n(700014)"
          },
          NextOptions = {
            [1] = 510013281
          },
          Subtitle = "(But before he can drain it, he staggers as if struck in the gut and then crashes heavily to the ground, his spilt drink reeking up the place.)",
          TalkActionId = {
            [1] = "700014:Onground02",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10
        },
        [51001329] = {
          Camera = "-139.912598,-187.989746,131.374023,0.00013,0.499936,50.203888,35.0,272.58197,false,Manual,5.0",
          Content = "我说过，冰湖城可不是那种人人安居乐业的好地方，想要在这里站稳脚跟处处都得留个心眼儿。",
          DialogueId = 51001329,
          GUID = "7FAD2D8A",
          LookAt = {
            [1] = "200003:n(100001)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001330,
          SpeakNpcId = 200003,
          Subtitle = "As I've always said, Icelake isn't some idyllic haven. Keeping your wits about you is the only way to survive here.",
          TurnTo = {
            [1] = "100001:p(30)"
          }
        },
        [51001330] = {
          Content = "唉，要是就这么放着不管他的小命可就不保了，还是先差人把他送进医院，再和他清算总账吧。",
          DialogueId = 51001330,
          GUID = "7FAD2DB4",
          NextDialogue = 51001331,
          SpeakNpcId = 200003,
          Subtitle = "*sigh* If we just leave him be, he might just kick it. I'll get him to a hospital, and settle the score with him later."
        },
        [51001331] = {
          Content = "还有，虽然不像迪恩这么“实惠”，但如果你想喝点一分钱一分货的酒，水仙平原随时欢迎你。",
          DialogueId = 51001331,
          GUID = "7FAD2DDE",
          SpeakNpcId = 200003,
          Subtitle = "By the way — unlike Dean's \"bargains\", if you're looking for quality that truly matches the price, The Asphodel welcomes you anytime."
        },
        [51001332] = {
          Content = "要说哪的酒最好，还得是水仙平原啊。",
          DialogueId = 51001332,
          GUID = "7FAD2E08",
          NextDialogue = 51001333,
          SpeakNpcId = 790009,
          Subtitle = "The best brews? You'll find them at The Asphodel, no question.",
          TalkActionId = {
            [1] = "790009:Talk02_Start"
          }
        },
        [51001333] = {
          Content = "这里的酒气味醇香，口味丰满，最难能可贵的是入口绵甜干净，回味悠长。",
          DialogueId = 51001333,
          GUID = "7FAD2E32",
          NextDialogue = 51001334,
          SpeakNpcId = 790009,
          Subtitle = "Intoxicating aroma, full-bodied flavours, and what sets it apart most? The smooth, clean finish — it lingers on the tongue."
        },
        [51001334] = {
          Content = "正所谓好酒是这世上最勾心的情人啊……不行，我得再来一杯……",
          DialogueId = 51001334,
          GUID = "7FAD2E5C",
          SpeakNpcId = 790009,
          Subtitle = "A fine drink is like a seductive lover... Ah, I think I need another refill...",
          TalkActionId = {
            [1] = "790009:Talk02_End"
          }
        },
        [51001335] = {
          Content = "你不知道吧，水仙平原最厉害的地方可不止有这儿的饮品。",
          DialogueId = 51001335,
          GUID = "7FAD2E86",
          NextDialogue = 51001336,
          SpeakNpcId = 790010,
          Subtitle = "There's more to The Asphodel than just great drinks.",
          TalkActionId = {
            [1] = "790010:Talk03_Start"
          }
        },
        [51001336] = {
          Content = "在水仙平原，你根本就不用担心被卷进醉汉一时兴起的茬架，或者被不知道哪来的疯子打得头破血流……",
          DialogueId = 51001336,
          GUID = "7FAD2EB0",
          NextDialogue = 51001337,
          SpeakNpcId = 790010,
          Subtitle = "Because you can enjoy a tipple here without having to worry about getting caught in a brawl with drunkards or getting whacked by some random lunatic..."
        },
        [51001337] = {
          Content = "要知道这可是卡米拉的地盘，只要提起她的名字，哈，看谁还敢闹事。",
          DialogueId = 51001337,
          GUID = "7FAD2EDA",
          SpeakNpcId = 790010,
          Subtitle = "After all, this is Camilla's turf. Her name alone keeps everyone in line — no one dares stir up trouble here.",
          TalkActionId = {
            [1] = "790010:Talk03_End"
          }
        },
        [51001338] = {
          Content = "呜呜……呜呜呜……",
          DialogueId = 51001338,
          GUID = "7FAD2F04",
          NextDialogue = 51001339,
          SpeakNpcId = 790011,
          Subtitle = "Boohoo... Boohoo...",
          TalkActionId = {
            [1] = "790011:Sigh_Start"
          }
        },
        [51001339] = {
          Content = "爱！你告诉我什么是爱的滋味？是我加入卡米拉后援会时的欣喜若狂？还是听到她解散后援会话语时的心碎……",
          DialogueId = 51001339,
          GUID = "7FAD2F2E",
          NextDialogue = 51001340,
          SpeakNpcId = 790011,
          Subtitle = "Love... what does it really taste like!? Was it the rush of ecstasy when I joined Camilla's fan club, or the crushing heartbreak when I heard she disbanded it?"
        },
        [51001340] = {
          Content = "呜呜……只有卡米拉大人的微笑才能将我这破碎的心重新粘连！",
          DialogueId = 51001340,
          GUID = "7FAD2F58",
          SpeakNpcId = 790011,
          Subtitle = "Boohoo... Only Lady Camilla's smile can piece back together my shattered heart!",
          TalkActionId = {
            [1] = "790011:Sigh_End"
          }
        },
        [51001401] = {
          ContentES = "“Bajo la lluvia, las flores de mamá se marchitaron... Entonces el cielo sembró pequeñas flores en los charcos, para disculparse con ella.”",
          DialogueId = 51001401,
          GUID = "7FAD395A",
          NextDialogue = 51001402,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          }
        },
        [51001402] = {
          ContentES = "¿Sabéis? Este pequeño poema se titula Disculpas, y fue escrito por uno de mis alumnos... tiene solo seis años.",
          DialogueId = 51001402,
          GUID = "7FAD3984",
          NextOptions = {
            [1] = 510014021,
            [2] = 510014022,
            [3] = 510014023
          },
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51001403] = {
          ContentES = "(Alrededor de Sunny, los niños llevan ropa elegante: sin duda, provienen de familias nobles.)",
          DialogueId = 51001403,
          GUID = "7FAD39AE",
          NextDialogue = 51001404,
          Subtitle = "(The children around Sunny are in finery, presumably from aristocratic families.)"
        },
        [51001404] = {
          ContentES = "Jaja, dice la verdad, este no es el único poema de este tipo. Su creatividad siempre me sorprende.",
          DialogueId = 51001404,
          GUID = "7FAD39D8",
          NextDialogue = 51001405,
          SpeakNpcId = 700017,
          Subtitle = "Haha, actually, there are many more like this one, and their creativity never ceases to amaze me.",
          TalkActionId = {
            [1] = "700017:Explain01_Start"
          }
        },
        [51001405] = {
          ContentES = "Siempre he pensado que una imaginación desbordante y una creatividad sin límites... es lo más valioso que puede tener un niño.",
          DialogueId = 51001405,
          GUID = "7FAD3A02",
          NextDialogue = 51001406,
          SpeakNpcId = 700017,
          Subtitle = "I've always believed that unfettered creativity and imagination are a child's most precious qualities.",
          TalkActionId = {
            [1] = "700017:Explain01_End"
          }
        },
        [51001406] = {
          ContentES = "Pero para los nobles, una maestra como yo probablemente sea la menos competente que puedan encontrar.",
          DialogueId = 51001406,
          GUID = "7FAD3A2C",
          NextOptions = {
            [1] = 510014061
          },
          RestartTag = 51001406,
          SpeakNpcId = 700017,
          Subtitle = "It's just that, to the nobility, a tutor like me is deemed quite incompetent.",
          bForbidSkipOptions = true
        },
        [51001407] = {
          ContentES = "Oh, se acerca la hora de la clase. Disculpa, debo irme ahora.",
          DialogueId = 51001407,
          GUID = "7FAD3A56",
          NextDialogue = 51001408,
          SpeakNpcId = 700017,
          Subtitle = "Ah, it's nearly time for class. Excuse me, I have to go now."
        },
        [51001408] = {
          ContentES = "(Sunny echó un vistazo a su reloj de bolsillo, se disculpó y se apresuró a irse.)",
          DialogueId = 51001408,
          GUID = "7FAD3A80",
          SpeakNpcId = 700017,
          Subtitle = "(Sunny glanced at her pocket watch, excused herself, and hurried off.)"
        },
        [51001409] = {
          ContentES = "Jaja... gracias por sus palabras. Nunca me he arrepentido de mi elección, aunque eso me costara mi trabajo.",
          DialogueId = 51001409,
          GUID = "7FAD3AAA",
          NextDialogue = 51001410,
          SpeakNpcId = 700017,
          Subtitle = "Haha, thank you. I've never once regretted my choice, even if it costs me my job.",
          TalkActionId = {
            [1] = "700017:Agree"
          }
        },
        [51001410] = {
          ContentES = "En el futuro, mis alumnos deberán dedicarse a la recitación de las Leyes Imperiales y a la preparación de los exámenes de la Legión.",
          DialogueId = 51001410,
          GUID = "7FAD3AD4",
          NextDialogue = 51001411,
          SpeakNpcId = 700017,
          Subtitle = "In the future, my students will have to embark on a path filled with Imperial Law recitations and military test preparations."
        },
        [51001411] = {
          ContentES = "Esta es mi última lección. Debo decirles que, sin importar la dureza o la monotonía de la realidad que deban enfrentar... siempre estaré orgullosa de sus sueños.",
          DialogueId = 51001411,
          GUID = "7FAD3AFE",
          NextDialogue = 51001490,
          SpeakNpcId = 700017,
          Subtitle = "This being our final lesson, I must let them know — no matter the cruelty or drudgery of the reality ahead, I'll forever be proud of their dreams.",
          TalkActionId = {
            [1] = "700083:Think_End",
            [2] = "700084:Think_End",
            [3] = "700085:Confident_End"
          }
        },
        [51001412] = {
          ContentES = "¡Por supuesto! ¡He recibido el regalo más hermoso del mundo!",
          DialogueId = 51001412,
          GUID = "7FAD3B28",
          NextDialogue = 51001413,
          SpeakNpcId = 700017,
          Subtitle = "Absolutely! I've received the most amazing gift in the world!",
          TalkActionId = {
            [1] = "700017:Agree"
          }
        },
        [51001413] = {
          ContentES = "“Mi profesora dice que soy una estrella en el cielo, y que ella no es más que mi reflejo en el mar.”",
          DialogueId = 51001413,
          GUID = "7FAD3B52",
          NextDialogue = 51001414,
          SpeakNpcId = 700017,
          Subtitle = "\"My teacher says I'm a star in the sky, and she's just my reflection in the sea at night.\"",
          TalkActionId = {
            [1] = "700017:Explain01_Start"
          }
        },
        [51001414] = {
          ContentES = "“Pero entre el cielo y el mar hay diez mil metros... Eso no está bien.”",
          DialogueId = 51001414,
          GUID = "7FAD3B7C",
          NextDialogue = 51001415,
          SpeakNpcId = 700017,
          Subtitle = "\"But heavens and seas are so far apart — that doesn't seem right.\""
        },
        [51001415] = {
          ContentES = "Entonces dije: “¡Mira! ¡Una estrella fugaz!”",
          DialogueId = 51001415,
          GUID = "7FAD3BA6",
          NextDialogue = 51001416,
          SpeakNpcId = 700017,
          Subtitle = "\"So I say: 'Look! A shooting star zooming by!'\"",
          TalkActionId = {
            [1] = "700017:Explain01_End"
          }
        },
        [51001416] = {
          ContentES = "¿Sabéis? Este pequeño poema se titula Encuentro, y fue escrito por uno de mis alumnos... tiene solo seis años.",
          DialogueId = 51001416,
          GUID = "7FAD3BD0",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Come to You\", and it's written by a six-year-old student of mine."
        },
        [51001417] = {
          ContentES = "Me pregunto qué estarán haciendo estos niños ahora... Seguramente han crecido mucho.",
          DialogueId = 51001417,
          GUID = "7FAD3BFA",
          SpeakNpcId = 700017,
          Subtitle = "I wonder what those kids have been up to lately. They must have grown taller, haven't they?"
        },
        [51001490] = {
          ContentES = "(Al final de la clase, los niños agitan sus pequeñas manos para despedirse. Sunny los observa alejarse, con una sonrisa tierna en los labios.)",
          DialogueId = 51001490,
          GUID = "7FAD47F4",
          NextOptions = {
            [1] = 510014901,
            [2] = 510014902
          },
          Scripts = [[
PARA{
MoveTo{ActorId{700083},MoveSpeed{150},TargetPoint{"Point_Sangni_nearby_YNF01"},Visibility{"Hide"}},
MoveTo{ActorId{700084},MoveSpeed{150},TargetPoint{"Point_Sangni_nearby_YNF02"},Visibility{"Hide"}},
MoveTo{ActorId{700085},MoveSpeed{150},TargetPoint{"Point_Sangni_nearby_YNM01"},Visibility{"Hide"}}
}]],
          Subtitle = "(As Sunny's class concluded, the children waved goodbye. Sunny smiles warmly as she watches them leave.)",
          bForbidSkipOptions = true
        },
        [51001501] = {
          ContentES = "Uf... ¿por qué no se quita esta mancha de sangre?",
          DialogueId = 51001501,
          GUID = "7FAD49C2",
          NextDialogue = 51001502,
          SpeakNpcId = 700067,
          Subtitle = "Ugh... why won't this bloodstain come off?",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          }
        },
        [51001502] = {
          ContentES = "No quiero que me vuelvan a golpear por esto...",
          DialogueId = 51001502,
          GUID = "7FAD49EC",
          SpeakNpcId = 700067,
          Subtitle = "I don't wanna get beaten up for this again...",
          TalkActionId = {
            [1] = "700067:Sigh_End"
          },
          TalkOptions = {
            [1] = 510015021,
            [2] = 510015022,
            [3] = 510015023
          }
        },
        [51001503] = {
          ContentES = "¿Qué dices?",
          DialogueId = 51001503,
          GUID = "7FAD4A16",
          NextDialogue = 51001504,
          SpeakNpcId = 700067,
          Subtitle = "What was that?"
        },
        [51001504] = {
          ContentES = "Pff... no tengo ganas de discutir. Espera a que termine de limpiar.",
          DialogueId = 51001504,
          GUID = "7FAD4A40",
          NextDialogue = 51001505,
          SpeakNpcId = 700067,
          Subtitle = "Oof, I'm swamped right now. Maybe talk to me after I'm done cleaning."
        },
        [51001505] = {
          ContentES = "(El hombre frota con ahínco, empujando el trapo áspero con un gesto agotado. Sólo al borde del colapso consigue finalmente hacer desaparecer la mancha.)",
          DialogueId = 51001505,
          GUID = "7FAD4A6A",
          NextDialogue = 51001506,
          Subtitle = "(He scrubs hard with the rough cloth, over and over, finally removing the bloodstain just as he's about to collapse from exhaustion.)"
        }
      }
    end
  },
  {
    MinKey = 51001506,
    MaxKey = 51002420,
    Loader = function()
      return {
        [51001506] = {
          ContentES = "Uf... Esos dos se dieron una paliza bestial. Había sangre por todas partes... qué horror para limpiar.",
          DialogueId = 51001506,
          GUID = "7FAD4A94",
          NextDialogue = 51001507,
          SpeakNpcId = 700067,
          Subtitle = "*sigh* That fight earlier was brutal, blood splattered everywhere. Such a nightmare to clean up.",
          TalkActionId = {
            [1] = "700067:Talk01_Start"
          }
        },
        [51001507] = {
          ContentES = "Es más fácil cuando es una ejecución limpia, o con veneno... Al menos casi no hay sangre.",
          DialogueId = 51001507,
          GUID = "7FAD4ABE",
          SpeakNpcId = 700067,
          Subtitle = "Much easier when it's a quick kill, or with poison — hardly any mess.",
          TalkActionId = {
            [1] = "700067:Talk01_End"
          },
          TalkOptions = {
            [1] = 510015071
          }
        },
        [51001508] = {
          ContentES = "¿Y qué? Es fácil dar lecciones cuando no estás en mi lugar. Ocúpate de tus propios asuntos.",
          DialogueId = 51001508,
          GUID = "7FAD4AE8",
          SpeakNpcId = 700067,
          Subtitle = "Who asked you? Easy to judge when you're not in my shoes. Mind your own business!"
        },
        [51001509] = {
          ContentES = "¿Qué quieres que haga? Cuando está sucio, hay que limpiar. Y si no lo haces bien, son golpes e insultos.",
          DialogueId = 51001509,
          GUID = "7FAD4B12",
          NextDialogue = 51001510,
          SpeakNpcId = 700067,
          Subtitle = "What choice do I have? When the floor's dirty, I gotta clean it, or it's beatings and scoldings for me.",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          }
        },
        [51001510] = {
          ContentES = "Antes solía sentir lástima por ellos, pero la compasión tiene un límite. Apenas si puedo mantenerme con vida, ¡no puedo preocuparme por los demás!",
          DialogueId = 51001510,
          GUID = "7FAD4B3C",
          NextDialogue = 51001511,
          SpeakNpcId = 700067,
          Subtitle = "I used to feel sorry for them, but there's only so much sympathy to go around. I'm struggling to keep myself alive — can't afford to worry about others!",
          TalkActionId = {
            [1] = "700067:Sigh_End"
          }
        },
        [51001511] = {
          ContentES = "Con el tiempo, la sangre ya no es más que un líquido rojo. Endurecerse es más fácil... si no lo haces, la vida se vuelve imposible.",
          DialogueId = 51001511,
          GUID = "7FAD4B66",
          NextDialogue = 51001512,
          SpeakNpcId = 700067,
          Subtitle = "Over time, blood's just another red spill to me. Being numb helps me make it through the day...",
          TalkActionId = {
            [1] = "700067:Explain01_Start"
          }
        },
        [51001512] = {
          ContentES = "Bueno, basta de hablar. Aún tengo otra área que limpiar...",
          DialogueId = 51001512,
          GUID = "7FAD4B90",
          SpeakNpcId = 700067,
          Subtitle = "Alright, I should get back to work. There's another mess waiting for me...",
          TalkActionId = {
            [1] = "700067:Explain01_End"
          }
        },
        [51001513] = {
          ContentES = "Bueno, basta de hablar. Aún tengo otra área que limpiar...",
          DialogueId = 51001513,
          GUID = "7FAD4BBA",
          SpeakNpcId = 700067,
          Subtitle = "Alright, I should get back to work. There's another mess waiting for me..."
        },
        [51001601] = {
          ContentES = "¡Lárgate, sucio Charon!",
          DialogueId = 51001601,
          GUID = "7FAD5A2A",
          NextDialogue = 51001602,
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!"
        },
        [51001602] = {
          ContentES = "(Delante de ti, un hombre Charon con un uniforme hecho trizas observa a los transeúntes con una mirada llena de odio.)",
          DialogueId = 51001602,
          GUID = "7FAD5A54",
          NextOptions = {
            [1] = 510016021,
            [2] = 510016022,
            [3] = 510016023
          },
          Subtitle = "(Dressed in ragged military garb, the Charon man before you sends menacing glares towards the passersby.)",
          bForbidSkipOptions = true
        },
        [51001603] = {
          ContentES = "¡Eh! ¿Qué haces?! ¿Quieres pelear o qué?!",
          DialogueId = 51001603,
          GUID = "7FAD5A7E",
          NextDialogue = 51001604,
          SpeakNpcId = 700068,
          Subtitle = "Oi! What are you doing?! Looking for trouble?!"
        },
        [51001604] = {
          ContentES = "Tú también tienes cuernos... como nosotros.",
          DialogueId = 51001604,
          GUID = "7FAD5AA8",
          NextDialogue = 51001608,
          SpeakNpcId = 100001,
          Subtitle = "You've got horns too, just like us."
        },
        [51001605] = {
          ContentES = "¡Ay, qué {性别:santo|santa} eres! Vete a predicar eso a la Oficina de Seguridad, que ellos sabrán cómo callarte.",
          DialogueId = 51001605,
          GUID = "7FAD5AD2",
          NextDialogue = 51001606,
          SpeakNpcId = 700068,
          Subtitle = "Look at that, a saint here! Why not enlighten the security bureau with your little sermon? Maybe they'll reward you with a free lesson on how to watch your mouth."
        },
        [51001606] = {
          ContentES = "¿Y de verdad crees que te tratarían con respeto si estuvieras en mi lugar?",
          DialogueId = 51001606,
          GUID = "7FAD5AFC",
          NextDialogue = 51001608,
          SpeakNpcId = 100001,
          Subtitle = "Think the security bureau would show you any respect if you were in my shoes?"
        },
        [51001607] = {
          ContentES = "¿Un Charon, yo también? ¿Estás bromeando? ¿De verdad crees que tú y yo somos iguales? ¡Qué chiste!",
          DialogueId = 51001607,
          GUID = "7FAD5B26",
          NextDialogue = 51001608,
          SpeakNpcId = 700068,
          Subtitle = "How dare you! Who do you think you're talking to? You think you and I are the same kind?"
        },
        [51001608] = {
          ContentES = "¿Quieres que te diga algo? ¡No todos los Charons somos iguales!",
          DialogueId = 51001608,
          GUID = "7FAD5B50",
          NextDialogue = 51001609,
          SpeakNpcId = 700068,
          Subtitle = "For your information, we Charons aren't all cut from the same cloth!"
        },
        [51001609] = {
          ContentES = "Desde niño me impuse los estándares de los Solarianos. Jamás me junté con los otros Charons. ¿Conoces a muchos Charons que hablen como yo? Te lo digo: es un acento dismaniano perfecto.",
          DialogueId = 51001609,
          GUID = "7FAD5B7A",
          NextDialogue = 51001691,
          SpeakNpcId = 700068,
          Subtitle = "Since I was a kid, I've held myself to Sola standards, and never mingled with other Charons. Ever met a Charon who speaks like I do? Just so you know, this is a standard Dismania accent!"
        },
        [51001610] = {
          ContentES = "Estás {性别:celoso|celosa}, ¿verdad? Pues esto me lo he ganado.",
          DialogueId = 51001610,
          GUID = "7FAD5BA4",
          NextDialogue = 51001692,
          SpeakNpcId = 700068,
          Subtitle = "Jealous, huh? Well, I've earned this!"
        },
        [51001611] = {
          ContentES = "¿Lo entiendes ahora? Soy mucho más Sola que cualquiera de ustedes. Por eso me convertí en oficial, mientras tú andas por ahí con harapos, como {性别:un mendigo|una mendiga}.",
          DialogueId = 51001611,
          GUID = "7FAD5BCE",
          NextDialogue = 51001612,
          SpeakNpcId = 700068,
          Subtitle = "Got it? I'm more Sola than any of you could ever be, that's why I've become an officer, while you roam around in rags like a beggar."
        },
        [51001612] = {
          ContentES = "Basta de perder el tiempo. Si hablo contigo, es solo porque tengo un corazón tan noble como el de un Sola. Considéralo una lección gratuita. Ahora lárgate y ve a mendigar en otra parte, no quiero volver a verte, me das mala suerte.",
          DialogueId = 51001612,
          GUID = "7FAD5BF8",
          NextOptions = {
            [1] = 510016121
          },
          RestartTag = 51001612,
          SpeakNpcId = 700068,
          Subtitle = "Alright, I've indulged you this long only because my heart's as big as any Sola's. Consider this as a gratis lesson for you Charons. Now shoo, take your lowlife vibes away from me.",
          bForbidSkipOptions = true
        },
        [51001613] = {
          ContentES = "¿Qué? ¿Qué acabas de decir?",
          DialogueId = 51001613,
          GUID = "7FAD5C22",
          NextDialogue = 51001614,
          SpeakNpcId = 700068,
          Subtitle = "Huh? What did you say?"
        },
        [51001614] = {
          ContentES = "He oído que Hyperborea otorga un título prestigioso, el de Charon Laureado, a los más merecedores.",
          DialogueId = 51001614,
          GUID = "7FAD5C4C",
          NextDialogue = 51001615,
          SpeakNpcId = 100001,
          Subtitle = "I've heard about this \"Laurelled Charon\" medal that Hyperborea grants to the most distinguished Charons."
        },
        [51001615] = {
          ContentES = "Un oficial tan valiente, leal y con un acento impecable como tú, debe tener una. Me encantaría verla con mis propios ojos.",
          DialogueId = 51001615,
          GUID = "7FAD5C76",
          NextDialogue = 51001616,
          SpeakNpcId = 100001,
          Subtitle = "Someone as brave, loyal, and with an impeccable accent like you must have one. I'd be thrilled to finally see it!"
        },
        [51001616] = {
          ContentES = "... ¡La... la dejé en casa! ¡Otra vez será!",
          DialogueId = 51001616,
          GUID = "7FAD5CA0",
          NextDialogue = 51001617,
          SpeakNpcId = 700068,
          Subtitle = "...I... must've left it at home! Maybe next time!"
        },
        [51001617] = {
          ContentES = "¿De verdad? ¡Lo admiro, mi oficial!",
          DialogueId = 51001617,
          GUID = "7FAD5CCA",
          NextDialogue = 51001693,
          SpeakNpcId = 100001,
          Subtitle = "Is that so? I truly admire you, sir!"
        },
        [51001618] = {
          ContentES = "¡Claro que sí!",
          DialogueId = 51001618,
          GUID = "7FAD5CF4",
          NextDialogue = 51001619,
          SpeakNpcId = 700068,
          Subtitle = "Of course!"
        },
        [51001619] = {
          ContentES = "También dicen que allí hay una famosa fuente llamada “Vobiandé”...",
          DialogueId = 51001619,
          GUID = "7FAD5D1E",
          NextDialogue = 51001620,
          SpeakNpcId = 100001,
          Subtitle = "There's that famous \"Maidé Upp\" fountain in the inner city, isn't there?"
        },
        [51001620] = {
          ContentES = "Probablemente nunca tendré la oportunidad de pisar ese lugar. Al menos dime, ¿la estatua cerca de la fuente es un león o un lobo? Por favor, realmente quiero saberlo.",
          DialogueId = 51001620,
          GUID = "7FAD5D48",
          NextDialogue = 51001621,
          SpeakNpcId = 100001,
          Subtitle = "A lowly Charon like me will probably never get to see it. Could you tell me if the statue by the fountain is a lion or a wolf. Please, sir, I'm dying to be enlightened!"
        },
        [51001621] = {
          ContentES = "Déjame pensar... Sí, es un león. ¡Un león, obviamente!",
          DialogueId = 51001621,
          GUID = "7FAD5D72",
          NextDialogue = 51001622,
          SpeakNpcId = 700068,
          Subtitle = "Err... it's... a lion. Right, a lion!"
        },
        [51001622] = {
          ContentES = "Oficial… ¿estás seguro? Un amigo me dijo que…",
          DialogueId = 51001622,
          GUID = "7FAD5D9C",
          NextDialogue = 51001623,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure, sir? Because a friend of mine said..."
        },
        [51001623] = {
          ContentES = "Ah, no, espera… No dormí bien anoche, me duele la cabeza. Ahora que lo pienso, ¡es un lobo! Sí, un lobo, pasé frente a él esta misma mañana, ¿{性别:satisfecho|satisfecha}?",
          DialogueId = 51001623,
          GUID = "7FAD5DC6",
          NextDialogue = 51001624,
          SpeakNpcId = 700068,
          Subtitle = "Ah, wait... had a rough night, headache's killing me! Now that I think about it, it's a wolf — walked by it just this morning, happy now?"
        },
        [51001624] = {
          ContentES = "(Una sonrisa admirativa permanece en tu rostro, pero en tu mente mil emociones se cruzan: primero la ira, luego la incomprensión, hasta que solo queda la lástima.)",
          DialogueId = 51001624,
          GUID = "7FAD5DF0",
          NextDialogue = 51001625,
          Subtitle = "(A veneer of admiration remains on your face, yet a whirlwind of emotions sweeps through your mind — from initial anger to bewilderment, settling finally on pity.)"
        },
        [51001625] = {
          ContentES = "Me temo que tu memoria realmente te juega malas pasadas… Porque no existe la fuente “Vobiandé” en realidad, es una fuente inventada.",
          DialogueId = 51001625,
          GUID = "7FAD5E1A",
          NextDialogue = 51001626,
          SpeakNpcId = 100001,
          Subtitle = "Seems your memory's still playing tricks on you. Because there's no \"Maidé Upp\" fountain — it's actually a made-up fountain."
        },
        [51001626] = {
          ContentES = "¡{性别:Pequeño astuto|Pequeña astuta}...! ¿Cómo te atreves!",
          DialogueId = 51001626,
          GUID = "7FAD5E44",
          NextDialogue = 51001627,
          SpeakNpcId = 700068,
          Subtitle = "You crafty little twerp...! How dare you—!"
        },
        [51001627] = {
          ContentES = "(Anticipando su movimiento, esquivaste ágilmente el furioso puñetazo del hombre.)",
          DialogueId = 51001627,
          GUID = "7FAD5E6E",
          NextDialogue = 51001628,
          Subtitle = "(Anticipating his move, you nimbly dodged the man's furious punch.)"
        },
        [51001628] = {
          ContentES = "Adiós, mi oficial. La próxima vez, espero que aún puedas enseñarme cosas sobre la ciudad interior.",
          DialogueId = 51001628,
          GUID = "7FAD5E98",
          SpeakNpcId = 100001,
          Subtitle = "Goodbye, sir. Hope I can pick your brain about the inner city again some other time."
        },
        [51001629] = {
          ContentES = "¡¡LÁRGATE!! ¡No quiero volver a verte jamás! ¡¡LÁRGATE!!",
          DialogueId = 51001629,
          GUID = "7FAD5EC2",
          SpeakNpcId = 700068,
          Subtitle = "Scram!! Don't let me catch sight of you again!! Beat it!!!"
        },
        [51001690] = {
          ContentES = "¿Qué? ¿Tú otra vez? ¡Te dije que te largaras!",
          DialogueId = 51001690,
          GUID = "7FAD68C4",
          SpeakNpcId = 700068,
          Subtitle = "What, you again? Didn't I tell you to get out of my sight?"
        },
        [51001691] = {
          ContentES = "Mis amigos Solarianos dicen que, al oírme hablar, jamás adivinarían que soy un Charon. Dicen que hablo exactamente como ellos.",
          DialogueId = 51001691,
          GUID = "7FAD68EE",
          NextDialogue = 51001610,
          SpeakNpcId = 700068,
          Subtitle = "My Sola friends all say they can't tell that I'm actually a Charon from the way I speak. They say I sound just like one of them."
        },
        [51001692] = {
          ContentES = "Durante tres años, todas las mañanas leía La Actualidad de Hyperborea durante dos horas, corrigiendo mi acento... mientras me estremecía por los crímenes que algunos Charons habían cometido de manera vergonzosa.",
          DialogueId = 51001692,
          GUID = "7FAD6918",
          NextDialogue = 51001611,
          SpeakNpcId = 700068,
          Subtitle = "For three years straight, I'd start every morning reading \"Hyperborean News\" for two hours, fine-tuning my accent while cringing at the crimes some Charon had disgracefully committed."
        },
        [51001693] = {
          ContentES = "Se dice que los Charons Laureados tienen el derecho de residir en la ciudad interior. Seguramente tendrás una mansión espléndida allí, como en los cuentos, ¡con mayordomos y sirvientes por docenas!",
          DialogueId = 51001693,
          GUID = "7FAD6942",
          NextDialogue = 51001618,
          SpeakNpcId = 100001,
          Subtitle = "I've heard that Laurelled Charons are entitled to live in the inner city. You must own a splendid mansion there, like something out of a storybook — with legions of butlers and servants!"
        },
        [51001701] = {
          ContentES = "La tubería n° 13 está en reparación. Maldita sea... hay demasiadas ratas ahí dentro.",
          DialogueId = 51001701,
          GUID = "7FAD6A92",
          NextDialogue = 51001702,
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          }
        },
        [51001702] = {
          ContentES = "(Dutton levanta la vista hacia ti. Un olor repugnante emana de su ropa, tan fuerte que retrocedes instintivamente un paso, luchando contra las náuseas.)",
          DialogueId = 51001702,
          GUID = "7FAD6ABC",
          NextDialogue = 51001703,
          Subtitle = "(Dutton looks up, reeking so strongly that you're forced to step back. You manage to stifle a gag.)",
          TalkActionId = {
            [1] = "700069:Sigh_End"
          }
        },
        [51001703] = {
          ContentES = "¡Eh! ¿Por qué te alejas? Cuando trabajas en las alcantarillas, es normal oler un poco fuerte.",
          DialogueId = 51001703,
          GUID = "7FAD6AE6",
          NextOptions = {
            [1] = 510017031,
            [2] = 510017032,
            [3] = 510017033
          },
          SpeakNpcId = 700069,
          Subtitle = "Hey! That was a bit uncalled for. Comes with the territory when you work in sewers, doesn't it?",
          bForbidSkipOptions = true
        },
        [51001704] = {
          ContentES = "No te fíes a lo que ves. Hace algunos años, la mayoría de la gente me llamaba con respeto “Doctor Dutton”.",
          DialogueId = 51001704,
          GUID = "7FAD6B10",
          NextDialogue = 51001705,
          SpeakNpcId = 700069,
          Subtitle = "You might not believe it, but there was a time people respectfully addressed me as \"Doctor Dutton\"."
        },
        [51001705] = {
          ContentES = "Probablemente entiendas lo que representaba ese título para un Charon nacido en los tugurios.",
          DialogueId = 51001705,
          GUID = "7FAD6B3A",
          NextDialogue = 51001706,
          SpeakNpcId = 700069,
          Subtitle = "You get what that title means to a Charon who's come up from the slums, right?"
        },
        [51001706] = {
          ContentES = "He atendido a innumerables Charons en el hospital central... incluso nobles se desplazaban para una consulta.",
          DialogueId = 51001706,
          GUID = "7FAD6B64",
          NextDialogue = 51001707,
          SpeakNpcId = 700069,
          Subtitle = "I've treated countless Charons at the central hospital; even the nobility sought me out for consultations.",
          TalkActionId = {
            [1] = "700069:Explain02_Start"
          }
        },
        [51001707] = {
          ContentES = "Si no me crees, pregunta a los jóvenes Charons: sus padres siempre les repetían que tomaran ejemplo de mí.",
          DialogueId = 51001707,
          GUID = "7FAD6B8E",
          NextDialogue = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "Don't take my word for it — go ask the younger Charons. Their folks always told them to model themselves on me.",
          TalkActionId = {
            [1] = "700069:Explain02_End"
          }
        },
        [51001708] = {
          ContentES = "En aquel entonces, era un verdadero maniático de la limpieza... el más mínimo grano de polvo entre dos baldosas me volvía loco.",
          DialogueId = 51001708,
          GUID = "7FAD6BB8",
          NextOptions = {
            [1] = 510017081
          },
          RestartTag = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "I was quite a stickler for cleanliness back then; a single speck of dust between the tiles would drive me nuts...",
          bForbidSkipOptions = true
        },
        [51001709] = {
          ContentES = "Reparaba personas, hoy arreglo tuberías... al final, es lo mismo, ¿no?",
          DialogueId = 51001709,
          GUID = "7FAD6BE2",
          NextDialogue = 51001710,
          SpeakNpcId = 700069,
          Subtitle = "I used to patch up people, and now I patch up pipes. Not much difference, eh?",
          TalkActionId = {
            [1] = "700069:Think_Start"
          }
        },
        [51001710] = {
          ContentES = "(Dutton esboza una sonrisa tranquila, como si estuviera pasando sin rencor la página de un pasado doloroso.)",
          DialogueId = 51001710,
          GUID = "7FAD6C0C",
          Subtitle = "(Dutton gave a serene smile, seemingly turning a page on some tough memories without a grudge.)",
          TalkActionId = {
            [1] = "700069:Think_End"
          }
        },
        [51001711] = {
          ContentES = "Imagina la escena: un transeúnte se desploma, golpeado por una emergencia vital, justo frente a un médico... y ese médico elige valientemente salvarlo.",
          DialogueId = 51001711,
          GUID = "7FAD6C36",
          NextDialogue = 51001712,
          SpeakNpcId = 700069,
          Subtitle = "Picture this: a pedestrian collapsed from an acute condition right in front of a doctor, who heroically opted to save him.",
          TalkActionId = {
            [1] = "700069:Explain01_Start"
          }
        },
        [51001712] = {
          ContentES = "¿Quieres saber qué pasó después? Mejor pásame esta llave inglesa.",
          DialogueId = 51001712,
          GUID = "7FAD6C60",
          NextDialogue = 51001713,
          SpeakNpcId = 700069,
          Subtitle = "Curious about what happened next? Hand me that wrench first—"
        },
        [51001713] = {
          ContentES = "El milagro no ocurrió. Lo que pasó fue un juicio colosal por negligencia médica. Para preservar su reputación, el hospital tuvo que despedir a un empleado.",
          DialogueId = 51001713,
          GUID = "7FAD6C8A",
          NextDialogue = 51001714,
          SpeakNpcId = 700069,
          Subtitle = "No miracle happened, just a massive lawsuit for medical malpractice. For the sake of the hospital's reputation, an employee had to be fired.",
          TalkActionId = {
            [1] = "700069:Explain01_End"
          }
        },
        [51001714] = {
          ContentES = "Y ese hombre, que no sabía hacer nada más que curar… terminó en las alcantarillas.",
          DialogueId = 51001714,
          GUID = "7FAD6CB4",
          NextDialogue = 51001715,
          SpeakNpcId = 700069,
          Subtitle = "Imagine that—someone who knew nothing but how to heal, ending up in the sewer pipes.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          }
        },
        [51001715] = {
          ContentES = "Al menos, este paso aquí curó mi vieja obsesión por la limpieza en unos pocos meses. Ya es algo.",
          DialogueId = 51001715,
          GUID = "7FAD6CDE",
          NextDialogue = 51001716,
          SpeakNpcId = 700069,
          Subtitle = "Funny enough, a few months down here cured me of that intense fixation with cleanliness. A silver lining, am I right?",
          TalkActionId = {
            [1] = "700069:Sigh_End"
          }
        },
        [51001716] = {
          ContentES = "Y bueno… este trabajo me permite no morir de hambre en la calle. Solo tendré que pagar mis deudas hasta que me pongan en la tumba.",
          DialogueId = 51001716,
          GUID = "7FAD6D08",
          NextOptions = {
            [1] = 510017161
          },
          SpeakNpcId = 700069,
          Subtitle = "At least this gig keeps me from starving on the streets, though I'll be paying debts till I'm six feet under.",
          bForbidSkipOptions = true
        },
        [51001717] = {
          ContentES = "(Dutton gira la espalda y aprieta concienzudamente los nuevos tornillos de la tubería. Mueve los brazos con costumbre y energía, como si ni siquiera hubiera oído tu pregunta.)",
          DialogueId = 51001717,
          GUID = "7FAD6D32",
          NextDialogue = 51001718,
          Subtitle = "(Dutton turns, focusing on tightening the screws of the replacement pipe with his wrench, his arms swinging skillfully, seemingly oblivious to your question.)"
        },
        [51001718] = {
          ContentES = "(En el ensordecedor silencio que sigue, la respuesta es evidente para ambos.)",
          DialogueId = 51001718,
          GUID = "7FAD6D5C",
          Subtitle = "(Yet, in the echoing silence that ensues, the answer is clear to both of you without a word spoken.)"
        },
        [51001719] = {
          ContentES = "¡Ay...! ¡Realmente hay demasiadas ratas ahí dentro!",
          DialogueId = 51001719,
          GUID = "7FAD6D86",
          SpeakNpcId = 700069,
          Subtitle = "Ow...! The rats are taking over down here!"
        },
        [51001801] = {
          Content = "嘿，我都听说了，你在格雷姆矿坑可是干了票大的。这么好的身手，要不要咱们一起做个委托，你拿八我拿二，怎么样？",
          DialogueId = 51001801,
          GUID = "7FAD7AFA",
          NextOptions = {
            [1] = 510018011,
            [2] = 510018012
          },
          SpeakNpcId = 200015,
          Subtitle = "Hey, kid! Word's got around about your big score at Glevum Pit. Really impressive, I'd say! How about you and I team up for a gig? I'll take a 20% cut, you keep 80%. What do you say?",
          bForbidSkipOptions = true
        },
        [51001802] = {
          Content = "好嘞，那我们这就出发。",
          DialogueId = 51001802,
          GUID = "7FAD7B24",
          NextDialogue = 51001803,
          SpeakNpcId = 200015,
          Subtitle = "Alright, let's get going then.",
          TalkActionId = {
            [1] = "200015:Agree"
          }
        },
        [51001803] = {
          Content = "卡米拉，酒钱先赊着啊，等我拿到报酬就还你。",
          DialogueId = 51001803,
          GUID = "7FAD7B4E",
          LookAt = {
            [1] = "200015:n(200003)",
            [2] = "200003:n(200015)"
          },
          NextDialogue = 51001804,
          SpeakNpcId = 200015,
          Subtitle = "Camilla, put the drink on my tab. I'll pay you back once I get the reward.",
          TurnTo = {
            [1] = "200015:n(200003)",
            [2] = "200003:n(200015)"
          }
        },
        [51001804] = {
          Content = "老规矩，先把你的怀表放我这做抵押。",
          DialogueId = 51001804,
          GUID = "7FAD7B78",
          NextDialogue = 51001805,
          SpeakNpcId = 200003,
          Subtitle = "Same as always then, your pocket watch stays here as collateral."
        },
        [51001805] = {
          Content = "没问题没问题，{nickname}，我们快去快回吧。",
          DialogueId = 51001805,
          GUID = "7FAD7BA2",
          SpeakNpcId = 200015,
          Subtitle = "Sure, sure. , let's make short work of this.",
          TurnTo = {
            [1] = "200015:n(0)"
          }
        },
        [51001901] = {
          Content = "（还没推开水仙平原的门，就已能听到其中响彻的咒骂声，仿佛想让全城都来倾听他的愤怒。）",
          DialogueId = 51001901,
          GUID = "7FAD8B62",
          NextDialogue = 51001902,
          Subtitle = "(Before even enter The Asphodel, you already hear the echoing curse words, as if wanting the whole city to listen to his rage.)"
        },
        [51001902] = {
          Content = "你怎么还有脸活着！我真是老糊涂了，当初就不该只是把你简单赶出去！",
          DialogueId = 51001902,
          GUID = "7FAD8B8C",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001903,
          SpeakNpcId = 700047,
          Subtitle = "How dare you show yourself in front of my face! I was such a fool. I should have done more than just kick you out!",
          TalkActionId = {
            [1] = "700047:Angry01_Start"
          }
        },
        [51001903] = {
          Content = "顶着我们家的姓抛头露面这么多年，我寄给你的警告信都让你拿去烧炉灰了？",
          DialogueId = 51001903,
          GUID = "7FAD8BB6",
          NextDialogue = 51001904,
          SpeakNpcId = 700047,
          Subtitle = "You paraded around with our family name for so many years. Did you use my warning letters as kindling?",
          TalkActionId = {
            [1] = "700047:Angry01_End"
          }
        },
        [51001904] = {
          Content = "是，是，岳父大人说得对，但这个姓毕竟是过去您……",
          DialogueId = 51001904,
          GUID = "7FAD8BE0",
          NextDialogue = 51001905,
          SpeakNpcId = 200015,
          Subtitle = "Yes, yes, you are right, but after all, that surname is what you...",
          TalkActionId = {
            [1] = "200015:Shock_Start"
          }
        },
        [51001905] = {
          Content = "（威尔斯如一个犯错的孩童般低头站在一名老者面前，任由对方的手指戳打在自己身上。）",
          DialogueId = 51001905,
          GUID = "7FAD8C0A",
          NextDialogue = 51001906,
          Subtitle = "(Wells, like a child who's misbehaved, stands with his head bowed in front of an old man, allowing the latter's finger to jab at him.)"
        },
        [51001906] = {
          Content = "别来沾边，没什么本事还学人家做狩月人，这钱、这名声是你配赚的？天天像条狗一样给人跑前跑后，内城现在都把我们威尔斯家当笑话看！",
          DialogueId = 51001906,
          GUID = "7FAD8C34",
          NextDialogue = 51001907,
          SpeakNpcId = 700047,
          Subtitle = "Shut up! You have no talent, yet you try to be a Phoxhunter. Do you really think you deserve this money and fame? Running around like a dog for others. The inner city now sees the Wells family as a joke!",
          TalkActionId = {
            [1] = "200015:Shock_End"
          }
        },
        [51001907] = {
          Content = "我这不是想着，要是哪天有出息了，说不定您会再考虑一下萨拉的事——",
          DialogueId = 51001907,
          GUID = "7FAD8C5E",
          NextDialogue = 51001908,
          SpeakNpcId = 200015,
          Subtitle = "I was just thinking, if I make something of myself someday, maybe you'll reconsider things about me and Sara—",
          TalkActionId = {
            [1] = "200015:Explain02_Start"
          }
        },
        [51001908] = {
          Content = "你还敢提她的名字！少他**惦记了，你和我女儿，永远都没有复合的可能，永远！",
          DialogueId = 51001908,
          GUID = "7FAD8C88",
          NextDialogue = 51001909,
          SpeakNpcId = 700047,
          Subtitle = "How dare you mention her name! Forget about it. You and my daughter will never get back together, never!",
          TalkActionId = {
            [1] = "700047:Angry01_Start"
          }
        },
        [51001909] = {
          Content = "别怪我没警告你，你要是敢踏进内城一步，我就打断你的腿。",
          DialogueId = 51001909,
          GUID = "7FAD8CB2",
          NextDialogue = 51001910,
          SpeakNpcId = 700047,
          Subtitle = "Don't say I didn't warn you. If you dare step foot in the inner city, I'll break your legs.",
          TalkActionId = {
            [1] = "700047:Angry01_End"
          }
        },
        [51001910] = {
          Content = "是，是……",
          DialogueId = 51001910,
          GUID = "7FAD8CDC",
          NextDialogue = 51001911,
          SpeakNpcId = 200015,
          Subtitle = "Yeah, yeah...",
          TalkActionId = {
            [1] = "200015:Explain02_End"
          }
        },
        [51001911] = {
          Content = "（老者看着不断点头的威尔斯气更是不打一处来，环顾四周，最后把视线落到了刚进水仙平原的你身上。）",
          DialogueId = 51001911,
          GUID = "7FAD8D06",
          NextDialogue = 51001912,
          Subtitle = "(The old man, glaring at the nodding Wells, grows even more infuriated, looking around and finally setting his eyes on you, who just enters The Asphodel.)"
        },
        [51001912] = {
          Content = "还有你，狩月人是吧，你们这种卡戎我见多了，幻想着靠狩月人扬名立万，当上桂冠卡戎？",
          DialogueId = 51001912,
          GUID = "7FAD8D30",
          NextDialogue = 51001990,
          SpeakNpcId = 700047,
          Subtitle = "And you, a Phoxhunter? I've seen many like you, dreaming of making a name for yourself as a Phoxhunter, and becoming a laurelled Charon.",
          TalkActionId = {
            [1] = "700047:Explain01_Start"
          }
        },
        [51001913] = {
          Content = "岳父，{nickname}很有本事的，和我这种废物不一样……",
          DialogueId = 51001913,
          GUID = "7FAD8D5A",
          NextDialogue = 51001914,
          SpeakNpcId = 200015,
          Subtitle = "Father-in-law,  is a capable one, not a loser like me..."
        },
        [51001914] = {
          Content = "费迪南特·威尔斯先生，先前是你们二人的私事，我不便插嘴。但无缘无故打扰我们的客人，水仙平原可就要送客了。",
          DialogueId = 51001914,
          GUID = "7FAD8D84",
          NextDialogue = 51001915,
          SpeakNpcId = 200003,
          Subtitle = "Mr. Ferdinand Wells, I had no right to interfere what happened between you two. But if you keep harassing my other guests for no reason like this, The Asphodel might have to show you the door.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001915] = {
          Content = "（坐在柜台前的卡米拉吐出一抹烟圈，轻描淡写的话语在空旷的水仙平原中却显得无比洪亮。）",
          DialogueId = 51001915,
          GUID = "7FAD8DAE",
          NextDialogue = 51001991,
          Subtitle = "(Camilla, sitting behind the counter, puffs out a ring of smoke. Her casual words echoing powerfully in the empty tavern.)",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51001916] = {
          Content = "哼。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51001916,
          GUID = "7FAD8DD8",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001917,
          SpeakNpcId = 700047,
          Subtitle = "Hmph.",
          TalkActionId = {
            [1] = "700047:Disagree"
          }
        },
        [51001917] = {
          Content = "（老者没听清你说什么，继续指着威尔斯的鼻子咒骂，也许应该过一会儿，等他冷静一点再说。）",
          DialogueId = 51001917,
          GUID = "7FAD8E02",
          Subtitle = "(The elder didn't quite catch what you said, and continued to curse Wells. Maybe it's better to wait a bit for him to calm down.)"
        },
        [51001918] = {
          Content = "……哼。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51001918,
          GUID = "7FAD8E2C",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001919,
          SpeakNpcId = 700047,
          Subtitle = "...Hmph.",
          TalkActionId = {
            [1] = "700047:Disagree"
          }
        },
        [51001919] = {
          Content = "（老者被你说得哑口无言，恶狠狠地回瞪一眼，摔门而出。）",
          DialogueId = 51001919,
          GUID = "7FAD8E56",
          NextDialogue = 51001920,
          Scripts = "MoveTo{ActorId{700047},TargetPoint{\"TargetPoint_LeaveTavern\"},MoveSpeed{90},Visibility{\"Hide\"}}",
          Subtitle = "(The elder is left speechless by your words, and glares fiercely before storming out.)"
        },
        [51001920] = {
          Content = "抱歉抱歉，给大家添麻烦了。那、那个，我岳……费迪南特·威尔斯先生十几年没来过外城了。",
          DialogueId = 51001920,
          GUID = "7FAD8E80",
          LookAt = {
            [1] = "200015:n(0)"
          },
          NextDialogue = 51001992,
          SpeakNpcId = 200015,
          Subtitle = "Sorry for causing everyone so much trouble. Well, my father-in-law... I mean Mr. Ferdinand Wells hasn't been to the outer city for years.",
          TalkActionId = {
            [1] = "200015:Sigh_Start"
          }
        },
        [51001921] = {
          Content = "没事，要是一两句恶言就能刺激到，我们也不会站在这里。倒是听说威尔斯先生最近在做委托时受了伤，不要紧吗？",
          DialogueId = 51001921,
          GUID = "7FAD8EAA",
          NextDialogue = 51001922,
          SpeakNpcId = 100001,
          Subtitle = "It's alright. We wouldn't be here today if we gave in to every slight or insult. Anyway, I heard you were injured recently during a commission. Are you okay?"
        },
        [51001922] = {
          Content = "小事，多亏了它，没受什么致命伤。",
          DialogueId = 51001922,
          GUID = "7FAD8ED4",
          NextDialogue = 51001923,
          SpeakNpcId = 200015,
          Subtitle = "It's nothing. Luckily this thing saved me from being fatally injured.",
          TalkActionId = {
            [1] = "200015:Explain01_Start"
          }
        },
        [51001923] = {
          Content = "（威尔斯说着从胸前取出一块精致的怀表，裂纹遍布表盘，指针夸张地朝上扭曲着，让关闭怀表的翻盖都成了一种奢望。）",
          DialogueId = 51001923,
          GUID = "7FAD8EFE",
          NextOptions = {
            [1] = 510019231,
            [2] = 510019232
          },
          Subtitle = "(Wells takes out a finely crafted pocket watch from his chest. The dial is covered in cracks, and the hands are twisted upwards in an exaggerated manner, making closing the watch cover a mere wish.)",
          TalkActionId = {
            [1] = "200015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51001924] = {
          Content = "那是他自己做的，十几年前，没人不知道天才钟表匠陶德·威尔斯的名字。当年靠这手艺，甚至差点成为桂冠卡戎。",
          DialogueId = 51001924,
          GUID = "7FAD8F28",
          NextDialogue = 51001925,
          SpeakNpcId = 200003,
          Subtitle = "He made it himself. Over a decade ago, there wasn't a soul who hadn't heard of Todd Wells, the prodigy clockmaker. Back then, his craftsmanship almost won him the title of Laurelled Charon.",
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001925] = {
          Content = "做工确实精良，就这么裂开了真是可惜。",
          DialogueId = 51001925,
          GUID = "7FAD8F52",
          NextDialogue = 51001926,
          SpeakNpcId = 100001,
          Subtitle = "Such a beautifully crafted watch. It's a pity it cracked like that.",
          TalkActionId = {
            [1] = "200003:Explain01_End"
          }
        },
        [51001926] = {
          Content = "哈哈，话是这么说，其实很久以前指针就坏掉不走了，只是带身上留个念想。",
          DialogueId = 51001926,
          GUID = "7FAD8F7C",
          NextDialogue = 51001927,
          SpeakNpcId = 200015,
          Subtitle = "Haha. Actually the hands had been broken for a long time, you know. I just keep it with me as a memento.",
          TalkActionId = {
            [1] = "200015:Sigh_Start"
          }
        },
        [51001927] = {
          Content = "为什么不试着修好它呢？",
          DialogueId = 51001927,
          GUID = "7FAD8FA6",
          NextDialogue = 51001928,
          SpeakNpcId = 100001,
          Subtitle = "Why don't you try to fix it then?"
        },
        [51001928] = {
          Content = "维修用的工具和原料都被我岳父掐死，想修也没得修。",
          DialogueId = 51001928,
          GUID = "7FAD8FD0",
          NextDialogue = 51001929,
          SpeakNpcId = 200015,
          Subtitle = "The tools and materials needed for repairs were cut off by my father-in-law, so even if I wanted to fix it, I just couldn't.",
          TalkActionId = {
            [1] = "200015:Sigh_End"
          }
        },
        [51001929] = {
          Content = "……没办法。不是所有东西都是你想修，你用力去修，就能修得好的。",
          DialogueId = 51001929,
          GUID = "7FAD8FFA",
          NextDialogue = 51001930,
          SpeakNpcId = 200015,
          Subtitle = "...It's the way it is. Not everything can be fixed just because you want to and put effort into it.",
          TalkActionId = {
            [1] = "200015:Talk01_Start"
          }
        },
        [51001930] = {
          Content = "……",
          DialogueId = 51001930,
          GUID = "7FAD9024",
          NextDialogue = 51001931,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51001931] = {
          Content = "不说这些了！刚才真是谢了啊，要不是你出来说话，我这耳朵估计都要废了。",
          DialogueId = 51001931,
          GUID = "7FAD904E",
          NextDialogue = 51001932,
          SpeakNpcId = 200015,
          Subtitle = "Anyway! Enough about that. Thanks again for stepping in — if you hadn't, I'd be half-deaf by now from all that yelling.",
          TalkActionId = {
            [1] = "200015:Talk01_End"
          }
        },
        [51001932] = {
          Content = "来来，今天随便吃随便喝。我开这边的酒，你把那边几桶开了，通通我买单！",
          DialogueId = 51001932,
          GUID = "7FAD9078",
          NextDialogue = 51001934,
          SpeakNpcId = 200015,
          Subtitle = "Come on, drinks are on me tonight! I'll crack open these kegs — you handle those ones over there!",
          TalkActionId = {
            [1] = "200015:Explain02_Start"
          }
        },
        [51001933] = {
          Content = "来嘛，喝，喝起来！",
          DialogueId = 51001933,
          GUID = "7FAD90A2",
          SpeakNpcId = 200015,
          Subtitle = "Come on, let's drink and party all night!"
        },
        [51001934] = {
          Content = "……",
          DialogueId = 51001934,
          GUID = "7FAD9079",
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200015:Explain02_End"
          }
        },
        [51001935] = {
          Camera = "122.0,278.0,139.0,0.000007,0.0,-95.0,35.0,200.0,false,Manual,2.8",
          Content = "（你将面前的酒桶全部打开，转身看去，威尔斯已经挂回了熟悉的笑容，举杯畅饮了起来。）",
          DialogueId = 51001935,
          FinalCamera = "102.0,278.0,139.0,0.000007,0.0,-95.0,35.0,350.0,false,Manual,2.8",
          GUID = "7FAD907A",
          Scripts = "TurnTo{_delay{1.5},TurnToDescription{\"100001:n(700207)\"}}",
          Subtitle = "(You pop open the last keg. Glancing back, you see Wells already raising a glass, his grin wide and familiar as ever.)",
          TalkActionId = {
            [1] = "700207:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51001936] = {
          Content = "只是那欢笑之下捧着怀表的一丝落寞，恐怕也如怀表本身一样，无法被轻易修复吧。",
          DialogueId = 51001936,
          Duration = 4,
          GUID = "7FAD907B",
          Subtitle = [[
(And yet... beneath the laughter, his fingers curl around the broken pocket watch, a quiet sorrow flickering beneath the surface.)
(Like the shattered timepiece, a part of him is no longer easily mended.) ]]
        },
        [51001990] = {
          Content = "告诉你们，<H>冰湖城这么多年就没出过几个活着的桂冠卡戎</>，卡戎最后，都只会消失在街角暗巷里！",
          DialogueId = 51001990,
          GUID = "7FAD99FC",
          NextDialogue = 51001913,
          SpeakNpcId = 700047,
          Subtitle = "Let me tell you something. Icelake hasn't had many living laurelled Charons for years. Charons only end up rotting in some dark alley!",
          TalkActionId = {
            [1] = "700047:Explain01_End"
          }
        },
        [51001991] = {
          Content = "（不知是心理作用还是真实变化，烟雾间水仙平原的温度都感觉上升了不少。）",
          DialogueId = 51001991,
          GUID = "7FAD9A26",
          NextOptions = {
            [1] = 510019911,
            [2] = 510019912,
            [3] = 510019913
          },
          RestartTag = 51001915,
          Subtitle = "(As if the temperature in The Asphodel rose significantly in the smoke.)",
          bForbidSkipOptions = true
        },
        [51001992] = {
          Content = "老人家比较……那个，尊重传统。他说的那些话你别往心里去。",
          DialogueId = 51001992,
          GUID = "7FAD9A50",
          NextDialogue = 51001921,
          SpeakNpcId = 200015,
          Subtitle = "Let's just say he's more... traditional. Don't take his words to heart.",
          TalkActionId = {
            [1] = "200015:Sigh_End"
          }
        },
        [51002001] = {
          Content = "来往的朋友，稍微停一停脚步，给上几个银币，就能获得南国海岛隐藏的惊天秘宝——的线索。",
          DialogueId = 51002001,
          GUID = "7FAD9BCA",
          NextDialogue = 51002002,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you will get something unimaginable! Yes, the clue to the secret treasure of a southern island!",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002002] = {
          Content = "难道您真的就甘心每天面对冰冷的面包和变味的红酒吗？不如开始一场冒险，拥抱机遇，改变人生！",
          DialogueId = 51002002,
          GUID = "7FAD9BF4",
          NextDialogue = 51002003,
          SpeakNpcId = 700048,
          Subtitle = "Are you really content with cold bread and stale wine every day? Why not embark on an adventure, seize the opportunity, and change your life!",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002003] = {
          Content = "（眼前这位满嘴投机主义言论的老人衣着破烂，言语激昂，但是这让他看起来很不值得信任。）",
          DialogueId = 51002003,
          GUID = "7FAD9C1E",
          NextOptions = {
            [1] = 510020031,
            [2] = 510020032,
            [3] = 510020033
          },
          Subtitle = "(The old man before you is dressed in rags, but his eyes gleam with fiery conviction. Still, all that grand talk only makes him seem... less than trustworthy.)",
          bForbidSkipOptions = true
        },
        [51002004] = {
          Content = "哎呀，我这不是一把老骨头，要把机会让给年轻人嘛。",
          DialogueId = 51002004,
          GUID = "7FAD9C48",
          NextDialogue = 51002005,
          SpeakNpcId = 700048,
          Subtitle = "Oh, I'm just an old man. I'd rather give the opportunity to the younger generation.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002005] = {
          Content = "唉，我要是你这个年纪啊，肯定就已经收拾行李准备动身了。",
          DialogueId = 51002005,
          GUID = "7FAD9C72",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "If I were your age, I'd surely be packing my stuff and setting off right now."
        },
        [51002006] = {
          Content = "怎么？有兴趣？年轻人很会把握机会嘛。",
          DialogueId = 51002006,
          GUID = "7FAD9C9C",
          NextDialogue = 51002007,
          SpeakNpcId = 700048,
          Subtitle = "What, you are interested? You do know how to seize opportunities.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002007] = {
          Content = "我就喜欢你这样的聪明孩子，所以我确实可以免费给你透露那么一两句。",
          DialogueId = 51002007,
          GUID = "7FAD9CC6",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "I like smart kids like you, so I can indeed reveal a thing or two for free.",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002008] = {
          Content = "你这叫什么话？还没听我说呢就说在骗人，怎么一点礼貌都没有。",
          DialogueId = 51002008,
          GUID = "7FAD9CF0",
          NextDialogue = 51002009,
          SpeakNpcId = 700048,
          Subtitle = "What are you talking about? You accuse me of defraudation without even hearing me out. Where are your manners?",
          TalkActionId = {
            [1] = "700048:Disagree"
          }
        },
        [51002009] = {
          Content = "既然你觉得我是骗子，那我就要跟你说上几句了，让你开开眼界。",
          DialogueId = 51002009,
          GUID = "7FAD9D1A",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "Since you think I'm a swindler, let me tell you a few things to set things straight."
        },
        [51002010] = {
          Content = "实际上啊，我不是冰湖城本地人，出生在帝国南方的一个海岛上。",
          DialogueId = 51002010,
          GUID = "7FAD9D44",
          NextDialogue = 51002011,
          SpeakNpcId = 700048,
          Subtitle = "Actually, I'm not a local from Icelake. I was born on an island in the southern part of the Empire.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002011] = {
          Content = "我们的那个海岛啊，被一棵巨大的天之树遮盖着，一般的地图上根本找不着。",
          DialogueId = 51002011,
          GUID = "7FAD9D6E",
          NextDialogue = 51002012,
          SpeakNpcId = 700048,
          Subtitle = "Our island was covered by a giant Heaventree, that you couldn't find on any ordinary map."
        },
        [51002012] = {
          Content = "岛上有一个隐秘的山洞，里面有一尊女神的雕像，比你见过的所有女人都要美！据说啊，这个女神的雕像的后面就藏着宝藏。",
          DialogueId = 51002012,
          GUID = "7FAD9D98",
          NextDialogue = 51002013,
          SpeakNpcId = 700048,
          Subtitle = "There's a secret cave on the island with a statue of a goddess more beautiful than any woman you've ever seen! Legend has it that the treasure is hidden right behind this goddess statue.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002013] = {
          Content = "至于这个宝藏具体是什么，想继续听的话，给上几个子儿就行。",
          DialogueId = 51002013,
          GUID = "7FAD9DC2",
          NextOptions = {
            [1] = 510020131
          },
          RestartTag = 51002013,
          SpeakNpcId = 700048,
          Subtitle = "As for what this treasure is, if you want to hear more, just a few silver coins will suffice.",
          bForbidSkipOptions = true
        },
        [51002014] = {
          Content = "（听着很像是净界岛，这家伙十有八九是个骗子，先不在他身上浪费时间了。）",
          DialogueId = 51002014,
          GUID = "7FAD9DEC",
          NextDialogue = 51002015,
          SpeakNpcId = 100001,
          Subtitle = "(It sounds a lot like Purgatorio Island. This guy is probably a swindler. Best not to waste any time on him.)"
        },
        [51002015] = {
          Content = "还是算了，我的铜币还没有多到为了听个响就随便乱扔的地步。",
          DialogueId = 51002015,
          GUID = "7FAD9E16",
          SpeakNpcId = 100001,
          Subtitle = "Forget it. My coins are in short supply so I can't throw them around just to hear something."
        },
        [51002016] = {
          Content = "你说的这个南方岛屿，是不是附近有一棵巨大的天之树，叫做净界岛？",
          DialogueId = 51002016,
          GUID = "7FAD9E40",
          NextDialogue = 51002017,
          SpeakNpcId = 100001,
          Subtitle = "This southern island you're talking about, does it have a giant Heaventree near it, and do they call it Purgatorio Island?"
        },
        [51002017] = {
          Content = "——！",
          DialogueId = 51002017,
          GUID = "7FAD9E6A",
          NextDialogue = 51002018,
          SpeakNpcId = 700048,
          Subtitle = "!!!"
        },
        [51002018] = {
          Content = "你为什么会知道这个名字？",
          DialogueId = 51002018,
          GUID = "7FAD9E94",
          NextDialogue = 51002019,
          SpeakNpcId = 700048,
          Subtitle = "How do you know that name?",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002019] = {
          Content = "那是我曾经的家。",
          DialogueId = 51002019,
          GUID = "7FAD9EBE",
          NextDialogue = 51002020,
          SpeakNpcId = 100001,
          Subtitle = "That was my home."
        },
        [51002020] = {
          Content = "……你也是那里的人？难道那里不再阻止村民离开了吗？",
          DialogueId = 51002020,
          GUID = "7FAD9EE8",
          NextDialogue = 51002021,
          SpeakNpcId = 700048,
          Subtitle = "...You're from there too? Have they stopped preventing villagers from leaving?",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002021] = {
          Content = "也不瞒着你了，我二十岁的时候出海打渔，看着帝国的海岸线弯弯曲曲，像极了我在书上读到过的马鞍和城堡。",
          DialogueId = 51002021,
          GUID = "7FAD9F12",
          NextDialogue = 51002022,
          SpeakNpcId = 700048,
          Subtitle = "Tell you what, when I was twenty, I went out to fish on the sea. I looked at the coastline of the Empire, which was winding like the saddles and castles I'd read about in books."
        },
        [51002022] = {
          Content = "于是我没有和往常一样带着渔获回家，而是一直向东，到了海岸这一侧。只不过这边的日子和我想象中还是有点不太一样……",
          DialogueId = 51002022,
          GUID = "7FAD9F3C",
          NextDialogue = 51002023,
          SpeakNpcId = 700048,
          Subtitle = "So, instead of taking my catch home as usual, I kept heading east, to this side of the coast. But life here turned out to be a bit different from what I had imagined..."
        },
        [51002023] = {
          Content = "唉，十几年了，现在想回去连个路费都凑不出，只能耍耍嘴皮子。",
          DialogueId = 51002023,
          GUID = "7FAD9F66",
          NextDialogue = 51002024,
          SpeakNpcId = 700048,
          Subtitle = "It's been over a decade, and now I can't even scrape together enough for the fare back. I can only make ends meet with my eloquence.",
          TalkActionId = {
            [1] = "700048:Sigh_Start"
          }
        },
        [51002024] = {
          Content = "那，既然你也是从净界岛出来的，那应该知道，村子最东边那一户的人家，现在还好吗？",
          DialogueId = 51002024,
          GUID = "7FAD9F90",
          NextDialogue = 51002025,
          SpeakNpcId = 700048,
          Subtitle = "So, since you're also from Purgatorio Island, do you know how the family at the easternmost part of the village is doing?",
          TalkActionId = {
            [1] = "700048:Sigh_End"
          }
        },
        [51002025] = {
          Content = "（向他讲述村子被秽兽袭击，大部分村民已经坐船逃走的场景。）",
          DialogueId = 51002025,
          GUID = "7FAD9FBA",
          NextDialogue = 51002026,
          SpeakNpcId = 100001,
          Subtitle = "(You told him about the village being attacked by Filthoids, with most villagers escaping by boat.)"
        },
        [51002026] = {
          Content = "居然……",
          DialogueId = 51002026,
          GUID = "7FAD9FE4",
          NextDialogue = 51002027,
          SpeakNpcId = 700048,
          Subtitle = "What the..."
        },
        [51002027] = {
          Content = "不过，听你的意思是他们都逃出来了吧，逃出来就好，逃出来就好……",
          DialogueId = 51002027,
          GUID = "7FADA00E",
          NextDialogue = 51002028,
          SpeakNpcId = 700048,
          Subtitle = "But you just said they all escaped, right? Thank god... As long as they've got away...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002028] = {
          Content = "对了，如果你们有机会回到净界岛的话，能不能去我的老房子附近看看，有没有什么东西留下来。",
          DialogueId = 51002028,
          GUID = "7FADA038",
          NextDialogue = 51002029,
          SpeakNpcId = 700048,
          Subtitle = "By the way, if you ever get a chance to go back to Purgatorio Island, could you check near my old house to see if there's anything left?"
        },
        [51002029] = {
          Content = "如果实在什么都找不到的话，帮我带点东西回来吧，什么都行，一片草叶也行。",
          DialogueId = 51002029,
          GUID = "7FADA062",
          NextDialogue = 51002030,
          SpeakNpcId = 700048,
          Subtitle = "If you can't find anything, just bring back something for me. Anything will do, even a blade of grass.",
          TalkActionId = {
            [1] = "700048:Explain02_Start"
          }
        },
        [51002030] = {
          Content = "好。",
          DialogueId = 51002030,
          GUID = "7FADA08C",
          SpeakNpcId = 100001,
          Subtitle = "Sure."
        },
        [51002031] = {
          Content = "唉，小时候想出来难得很，现在想回去又回不去……",
          DialogueId = 51002031,
          GUID = "7FADA0B6",
          NextDialogue = 51002032,
          SpeakNpcId = 700048,
          Subtitle = "It was so hard to leave when I was young, and now I can't go back...",
          TalkActionId = {
            [1] = "700048:Explain02_End"
          }
        },
        [51002032] = {
          Content = "再见。",
          DialogueId = 51002032,
          GUID = "7FADA0E0",
          SpeakNpcId = 100001,
          Subtitle = "Take care."
        },
        [51002101] = {
          Content = "这里应该就是那个布鲁内托的家了。",
          DialogueId = 51002101,
          Duration = 3,
          GUID = "7FADAC32",
          NextDialogue = 51002102,
          SpeakNpcId = 100001,
          Subtitle = "This should be it — Brunetto's old place."
        },
        [51002102] = {
          Content = "这儿有个箱子，里面会有什么能捎带给他的东西吗？",
          DialogueId = 51002102,
          Duration = 4,
          GUID = "7FADAC5C",
          NextDialogue = 51002103,
          SpeakNpcId = 100001,
          Subtitle = "There's a chest here. Might be something inside I can bring back for him."
        },
        [51002103] = {
          Content = "可惜没看到钥匙，去附近找找看吧。",
          DialogueId = 51002103,
          Duration = 2.5,
          GUID = "7FADAC86",
          SpeakNpcId = 100001,
          Subtitle = "No key, though... I'll have a look around. Maybe it's nearby."
        },
        [51002104] = {
          Content = "从形状来看，就是这把钥匙了。",
          DialogueId = 51002104,
          Duration = 2,
          GUID = "7FADAC87",
          SpeakNpcId = 100001,
          Subtitle = "Looks like this fits. Let's give it a try."
        },
        [51002105] = {
          Camera = "183.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（钥匙缓缓转动，生锈的锁芯吃力地咬合着，发出刺耳的摩擦声。当箱子彻底打开，周围的秽兽也被异响吸引到了附近，拦住了你的去路。）",
          DialogueId = 51002105,
          FinalCamera = "186.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC88",
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{2}},
CameraMoveTo{_delay{3},TargetPosition{"-55.90625,-613.697266,78.0,0.0,0.0,72.803268,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
PARA{
CameraMoveTo{_delay{3},TargetPosition{"-127.292969,-843.583984,77.028931,0.0,0.0,72.203499,35.0,100000.0,false,DoNotOverride,2.8"},duration{7}},
SetLocation{ActorId{700208},TargetPoint{"MovePoint_700208"},Visibility{"Show"}},
SetLocation{ActorId{700209},TargetPoint{"MovePoint_700209"},Visibility{"Show"}},
SEQ{
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Think_End"},Duration{1}},
TurnTo{_delay{2},TurnToDescription{"100001:p(-130)"}}
}
}
}]],
          Subtitle = "(The key scrapes against the rusted lock, screeching sharp and loud. As the chest creaks open, the noise cuts through the silence, and from the shadows, a pack of Filthoids comes swarming, blocking your way out.)",
          ToFinalCameraBlendTime = 3
        },
        [51002106] = {
          Camera = "-160.396484,-385.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（这些秽兽并不是你的对手，但这小小的插曲让你感到了一丝熟悉，久远的回忆开始苏醒，你仿佛听到了两个小孩在这间房子前打闹的声音。）",
          DialogueId = 51002106,
          FinalCamera = "-160.396484,-404.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC89",
          NextDialogue = 51002107,
          Subtitle = "(The Filthoids weren't much trouble — but something about the scuffle tugs at your memory. You catch a flash of a distant summer afternoon: two kids scrapping in front of this very house.)",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002107] = {
          Camera = "119.585938,-26.257812,128.0,-0.0,-9.999997,-145.798935,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我想起来了，小时候我和这家的小孩打过一架。名字我已经记不清了，算起来，应该是布鲁内托的孙子吧。",
          DialogueId = 51002107,
          FinalCamera = "119.585938,-26.257812,128.0,0.0,-9.999997,-138.598923,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8A",
          NextDialogue = 51002108,
          Scripts = "TurnTo{_delay{3},TurnToDescription{\"100001:n(700211)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "It's coming back to me now. I once got into a fight with the boy who lived here. Can't quite remember his name... but he must've been Brunetto's grandson.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002108] = {
          Camera = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "起因是什么已经想不起来了，但我还记得开打前的最后一句话是……那小鬼喊我独眼龙，我骂他是眼睛鼓鼓的大青蛙。",
          DialogueId = 51002108,
          GUID = "7FADAC8B",
          NextDialogue = 51002109,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{2}},
CameraMoveTo{_delay{3},TargetPosition{"88.632812,-31.105469,133.52002,0.000039,-12.79989,-135.199905,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
PlayAnimation{_delay{1},ActorId{700211},AnimationId{"Angry01_Start"},Duration{1}},
}]],
          SpeakNpcId = 100001,
          Subtitle = "I don't even recall what started it. But I do remember the last thing we said before it turned physical — he called me \"One-Eye,\" and I shot back with \"googly-eyed toad.\""
        },
        [51002109] = {
          Camera = "-143.595703,-312.263672,94.0,0.0,0.0,57.398624,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哈哈，原来我也有这么口无遮拦的时候……现在想想，那时候我好像也没有那么生气，因为再怎么说，我的身边还有贝蕾在。",
          DialogueId = 51002109,
          GUID = "7FADAC8C",
          NextDialogue = 51002110,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Sigh_Start"},Duration{3}},
PlayAnimation{ActorId{100001},AnimationId{"Sigh_End"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Heh... I was kinda mean back then. Funny thing is, I don't think I was actually mad. I still had Berry with me, after all..."
        },
        [51002110] = {
          Camera = "70.748047,32.113281,1751.04126,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "后来……好像是和好了吧？我记得我们爬到屋顶上……",
          DialogueId = 51002110,
          FinalCamera = "70.748047,32.113281,1859.0,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8D",
          SpeakNpcId = 100001,
          Subtitle = "And later... I think we made up. I remember the two of us climbing up to the roof...",
          ToFinalCameraBlendTime = 7
        },
        [51002111] = {
          Camera = "51.001041,365.471497,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊对，就是在这儿，过了几天他拿着一袋吃的和我道歉。我本来还想骂他来着，但看着那三人份的面包，最后还是让馋虫战胜了尊严。",
          DialogueId = 51002111,
          FinalCamera = "14.224466,404.913452,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8E",
          NextDialogue = 51002112,
          SpeakNpcId = 700210,
          Subtitle = "Yeah — this spot. Right here. A few days later, he came back with food to apologise. I was all ready to yell at him... but when I saw that bread in his hands — big enough for the three of us to eat our fill — well, my stomach won that battle over my pride.",
          ToFinalCameraBlendTime = 7
        },
        [51002112] = {
          Camera = "-78.281792,63.089108,96.67688,0.000094,-0.099919,90.79702,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯……我们三个就这样坐在屋顶默默地吃着又硬又焦的面包，看着日头渐斜，大人们载着打来的鱼回村。",
          DialogueId = 51002112,
          FinalCamera = "-123.657745,62.460995,96.67688,0.000094,-0.099919,90.797005,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8F",
          NextDialogue = 51002113,
          SpeakNpcId = 700210,
          Subtitle = "So we sat up here, the three of us. Quietly chewing on that tough, burnt bread, watching the sun dip low while the grown-ups hauled in the day's catch.",
          ToFinalCameraBlendTime = 7
        },
        [51002113] = {
          Camera = "-182.640976,408.587311,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "最后那小鬼噎着了，连着打了一串嗝。我们三个一起笑了，那次吵架就这么过去了。",
          DialogueId = 51002113,
          FacialId = {
            [1] = "700210:Ahaha02"
          },
          FinalCamera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC90",
          NextDialogue = 51002114,
          SpeakNpcId = 700210,
          Subtitle = "And then... with one massive bite, he started hiccuping like crazy. We couldn't stop laughing — and just like that, the fight was forgotten.",
          ToFinalCameraBlendTime = 7
        },
        [51002114] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "四舍五入的话，我从那个时候就已经认识布鲁内托了吧。",
          DialogueId = 51002114,
          FacialId = {
            [1] = "700210:Smile02"
          },
          GUID = "7FADAC91",
          NextDialogue = 51002115,
          SpeakNpcId = 700210,
          Subtitle = "...Huh. Guess I've known Brunetto — sort of — since way back then."
        },
        [51002115] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "如果实在什么都找不到的话，帮我带点东西回来吧，什么都行，一片草叶也行。",
          DialogueId = 51002115,
          GUID = "7FADAC92",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030106.T_Story_Recall_10030106'",
          NextDialogue = 51002116,
          SpeakNpcId = 700048,
          Subtitle = "If you can't find anything, just bring back something for me. Anything will do, even a blade of grass."
        },
        [51002116] = {
          Camera = "167.319687,115.790215,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "再给布鲁内托带点特产吧，这个季节的鱼我记得都很肥美。",
          DialogueId = 51002116,
          FinalCamera = "181.948135,137.309357,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC93",
          SpeakNpcId = 700210,
          Subtitle = "Maybe I'll bring him a little extra, too. If I remember right, the fish are nice and plump this time of year.",
          ToFinalCameraBlendTime = 7
        },
        [51002117] = {
          Content = "回去吧，这些应该能够缓解布鲁内托的乡愁了。",
          DialogueId = 51002117,
          Duration = 3,
          GUID = "7FADAC94",
          NextDialogue = 51002118,
          SpeakNpcId = 100001,
          Subtitle = "Alright — time to head back. This should help ease a bit of that homesickness."
        },
        [51002118] = {
          Content = "孙子通过打架认识，爷爷通过坑骗认识……哈……真是奇怪的缘分……",
          DialogueId = 51002118,
          Duration = 4,
          GUID = "7FADAC95",
          SpeakNpcId = 100001,
          Subtitle = "Huh. Got to know the grandson through a fistfight... and the grandfather through a street scam. Heh. Life really does have a funny way of looping people together, doesn't it?"
        },
        [51002201] = {
          Content = "来往的朋友，稍微停一停脚步，给上几个银币，您就能加入冰湖城渔夫互助会，获得最好最新的——啊！是你……",
          DialogueId = 51002201,
          GUID = "7FADBC9A",
          NextDialogue = 51002202,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you can join The Fisheries in Icelake to get the best and latest— Oh! It's you..."
        },
        [51002202] = {
          Content = "这应该是你的东西？",
          DialogueId = 51002202,
          GUID = "7FADBCC4",
          NextDialogue = 51002203,
          SpeakNpcId = 100001,
          Subtitle = "Is this yours?"
        },
        [51002203] = {
          Content = "啊！没错，这就是我小时候翻来覆去一直在看的书，那时候就是看着这本书，想离开巴掌大的小岛……",
          DialogueId = 51002203,
          GUID = "7FADBCEE",
          NextDialogue = 51002204,
          SpeakNpcId = 700048,
          Subtitle = "Ah! That's it! The book I used to pore over for hours as a kid. I'd sit there staring at the pictures, dreaming of life beyond our tiny island...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002204] = {
          Content = "谢谢，谢谢你，我今天晚上得要好好再翻一遍。不过现在先不说了，唉，挣钱糊口要紧。",
          DialogueId = 51002204,
          GUID = "7FADBD18",
          NextDialogue = 51002205,
          SpeakNpcId = 700048,
          Subtitle = "Thank you. Thank you so much. I need to give it a good read tonight. But for now, *sigh* making a living is more important.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002205] = {
          Content = "再见，不要再骗人了。哦对了，这些鱼干也拿去，净界岛钓上来做的。",
          DialogueId = 51002205,
          GUID = "7FADBD42",
          NextDialogue = 51002206,
          SpeakNpcId = 100001,
          Subtitle = "Take care. And no more scamming people, alright? Oh, and here — some dried fish, caught off Purgatorio Island.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002206] = {
          Content = "这是……谢谢，真的太谢谢你了……",
          DialogueId = 51002206,
          GUID = "7FADBD6C",
          SpeakNpcId = 700048,
          Subtitle = "Oh, wow... Thank you. Really. Thank you so much..."
        },
        [51002207] = {
          Content = "冰湖城渔夫互助会，有兴趣的朋友了解一下，几十年经验老渔夫亲自指导，作为兴趣作为工作都棒极了！",
          DialogueId = 51002207,
          GUID = "7FADBD96",
          NextDialogue = 51002208,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, those who are interested in Icelake Fishermen's Mutual Aid Society can learn more about it. We have decades of fishing experience from veteran fishermen. Fishing is great either serving as a hobby or a job!"
        },
        [51002208] = {
          Content = "哎呀，这不是{nickname}吗，都是老乡了，有空我们交流下捕鱼的技术？",
          DialogueId = 51002208,
          GUID = "7FADBD97",
          NextDialogue = 51002209,
          SpeakNpcId = 700048,
          Subtitle = "Ah, {Nickname}! Great to see you again! Us old island folk ought to swap fishing tricks sometime, eh?"
        },
        [51002209] = {
          Content = "下次一定。",
          DialogueId = 51002209,
          GUID = "7FADBDC0",
          SpeakNpcId = 100001,
          Subtitle = "Maybe next time."
        },
        [51002301] = {
          Content = "年轻人，你有哈默尔·狄金森的消息了吗？",
          DialogueId = 51002301,
          GUID = "7FADCD02",
          NextOptions = {
            [1] = 510023011
          },
          SpeakNpcId = 700019,
          Subtitle = "Young one, any news of Hamel Dickinson?"
        },
        [51002302] = {
          Content = "（是的，格雷姆矿坑的那本无名日记，它的扉页写着主人的名字——哈默尔·狄金森。）",
          DialogueId = 51002302,
          GUID = "7FADCD2C",
          NextDialogue = 51002303,
          Subtitle = "(Indeed, it is the same name on the title page of the journal you retrieved from Glevum Pit.)"
        },
        [51002303] = {
          Content = "（如果没猜错的话，那只盘踞在矿坑深处的怪物，它的真实身份就是……）",
          DialogueId = 51002303,
          GUID = "7FADCD56",
          NextDialogue = 51002304,
          Subtitle = "(If your guess is correct, then the monster haunting the depths of the pit might just be...)"
        },
        [51002304] = {
          Content = "（从言及那个男人开始，老妇人浑浊的眼睛就有了些光亮，看来哈默尔·狄金森这个名字对她而言并不一般。她在期待着一个答案。）",
          DialogueId = 51002304,
          GUID = "7FADCD80",
          NextOptions = {
            [1] = 510023041,
            [2] = 510023042
          },
          Subtitle = "(Her cloudy eyes brighten slightly at the mention of that man. The name Hamel Dickinson clearly holds great significance for her. She is awaiting an answer.)",
          bForbidSkipOptions = true
        },
        [51002305] = {
          Content = "……",
          DialogueId = 51002305,
          GUID = "7FADCDAA",
          NextDialogue = 51002306,
          SpeakNpcId = 700019,
          Subtitle = "..."
        },
        [51002306] = {
          Content = "（老妇人逐字逐句地默念着那本日记。泪水从她满是皱纹的眼角不断滚落。）",
          DialogueId = 51002306,
          GUID = "7FADCDD4",
          NextDialogue = 51002307,
          Subtitle = "(Word by word, she silently reads through the journal. Tears stream down her deeply lined cheeks.)"
        },
        [51002307] = {
          Content = "（然后她将日记抱在胸前，像是在拥抱着一位久别重逢的爱人。）",
          DialogueId = 51002307,
          GUID = "7FADCDFE",
          NextDialogue = 51002308,
          Subtitle = "(She then clasps the journal to her chest, as if embracing a long-lost beloved.)"
        },
        [51002308] = {
          Content = "……年轻人，谢谢你。谢谢你帮忙找到这个埋藏了四十年的答案。",
          DialogueId = 51002308,
          GUID = "7FADCE28",
          NextDialogue = 51002309,
          SpeakNpcId = 700019,
          Subtitle = "...Thank you, young one. Thank you for uncovering this secret that's been buried for forty years.",
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51002309] = {
          Content = "请你去找我的女仆莎莉领取报酬吧。我想一个人待一会儿。",
          DialogueId = 51002309,
          GUID = "7FADCE52",
          NextDialogue = 51002310,
          SpeakNpcId = 700019,
          Subtitle = "Please see my maid Sally for your reward. I'd like some time alone."
        },
        [51002310] = {
          Content = "（老妇人转过身去，只留下衰老佝偻的背影。）",
          DialogueId = 51002310,
          GUID = "7FADCE7C",
          Subtitle = "(She turns away, her frail, stooped back towards you.)"
        },
        [51002311] = {
          Content = "……",
          DialogueId = 51002311,
          GUID = "7FADCEA6",
          SpeakNpcId = 700019,
          Subtitle = "..."
        },
        [51002312] = {
          Content = "抱歉，我没听过这个名字。如果以后有消息，我会回来找你的。",
          DialogueId = 51002312,
          GUID = "7FADCED0",
          NextDialogue = 51002313,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I've never heard that name. If I get any news, I will get back to you."
        },
        [51002313] = {
          Content = "好……好，谢谢你，年轻人。",
          DialogueId = 51002313,
          GUID = "7FADCEFA",
          NextDialogue = 51002314,
          SpeakNpcId = 700019,
          Subtitle = "Okay, okay... Thank you."
        },
        [51002314] = {
          Content = "我备好了一份薄礼，请你到我家去找我的女仆莎莉吧，就说是希琳夫人让你来的。",
          DialogueId = 51002314,
          GUID = "7FADCF24",
          NextDialogue = 51002315,
          SpeakNpcId = 700019,
          Subtitle = "I've prepared a gift. Please go to my house and ask for my maid, Sally, and tell her that Lady Hilin sent you."
        },
        [51002315] = {
          Content = "去吧，愿你一路顺风……",
          DialogueId = 51002315,
          GUID = "7FADCF4E",
          SpeakNpcId = 700019,
          Subtitle = "Just go. May you have a smooth journey."
        },
        [51002320] = {
          Content = "孩子，你就是那位叫做{nickname}的狩月人吧。希琳夫人让我将报酬预支给你。",
          DialogueId = 51002320,
          GUID = "7FADD020",
          NextDialogue = 51002321,
          SpeakNpcId = 700020,
          Subtitle = "Child, you're , the Phoxhunter, aren't you? Lady Hilin told me to pay you in advance.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002321] = {
          Content = "如果你在哪里听说了哈默尔·狄金森的消息，一定要快点跟夫人讲！",
          DialogueId = 51002321,
          GUID = "7FADD04A",
          NextDialogue = 51002322,
          SpeakNpcId = 700020,
          Subtitle = "Should you hear anything about Hamel Dickinson, please do tell her ladyship as soon as possible.",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002322] = {
          Content = "唉！她那身子从去年开始就越来越差，如今恐怕没有多少日子了。哈默尔的事情，是她的最后一桩心事……",
          DialogueId = 51002322,
          GUID = "7FADD074",
          NextOptions = {
            [1] = 51002323
          },
          SpeakNpcId = 700020,
          Subtitle = "*sigh* She's been really going downhill since last year, and now I'm afraid she doesn't have much time left. Information about Hamel is the last remaining thing weighing on her mind.",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002323] = {
          Content = "可以告诉我哈默尔的事情吗？",
          DialogueId = 51002323,
          GUID = "51002323.0",
          NextDialogue = 51002404,
          Subtitle = "Could you tell me more about Mr Dickinson?"
        },
        [51002401] = {
          Content = "孩子，你就是那个叫做{nickname}的狩月人吧。希琳夫人让我将报酬转交给你。",
          DialogueId = 51002401,
          GUID = "7FADDD6A",
          NextDialogue = 51002402,
          SpeakNpcId = 700020,
          Subtitle = "Child, thank you for all your help. Here's a little something for you.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002402] = {
          Content = "唉！她那身子从去年开始就越来越差，如今恐怕没有多少日子了。哈默尔的事情，是她的最后一桩心事……",
          DialogueId = 51002402,
          GUID = "7FADDD94",
          NextDialogue = 51002403,
          SpeakNpcId = 700020,
          Subtitle = "*sigh* Her ladyship's health has worsened since last year, and I fear she doesn't have much time left. Her past with Mr Dickinson was the last thing on her mind...",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002403] = {
          Content = "虽然不是什么好消息，但婶婶还是要谢谢你！圆了她最后一桩心愿。",
          DialogueId = 51002403,
          GUID = "7FADDDBE",
          NextOptions = {
            [1] = 510024031
          },
          SpeakNpcId = 700020,
          Subtitle = "Though it wasn't the news we hoped for, I still want to thank you for helping her retrieve this final piece of her past.",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002404] = {
          Content = "唉……到这份上，我们确实不能再瞒着你了。",
          DialogueId = 51002404,
          GUID = "7FADDDE8",
          NextDialogue = 51002405,
          SpeakNpcId = 700020,
          Subtitle = "Well... I suppose there's no point in keeping secrets now.",
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002405] = {
          Content = "你可能猜到了，哈默尔是夫人四十年前的心上人。那时夫人……不，应该叫她小姐，还是个热情活泼的姑娘。哈默尔·狄金森是个和她年龄相仿的矿工，就在她父亲管理的格雷姆矿场工作。",
          DialogueId = 51002405,
          GUID = "7FADDE12",
          NextDialogue = 51002406,
          SpeakNpcId = 700020,
          Subtitle = "You might have guessed — Mr Dickinson was her ladyship's beau forty years ago. At that time, her ladyship... well, it was Miss Hilin back then — was a cheerful, lively girl.Hamel Dickinson was a miner of her age, working at her father's Glevum Pit."
        },
        [51002406] = {
          Content = "像所有俗套的浪漫故事那样，他们越是地位悬殊，就越是执拗，非得逆着全世界的意思在一起。",
          DialogueId = 51002406,
          GUID = "7FADDE3C",
          NextDialogue = 51002407,
          SpeakNpcId = 700020,
          Subtitle = "As it often goes in such stories, the greater their social divide, the more stubbornly they clung to each other against all odds.",
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002407] = {
          Content = "那些故事会告诉你，爱情就像一团火，旁人越想扑灭就越烧得旺。但他们不会告诉你，这团火在决堤的现实面前，是多么不值一提！",
          DialogueId = 51002407,
          GUID = "7FADDE66",
          NextDialogue = 51002408,
          SpeakNpcId = 700020,
          Subtitle = "They say love burns brighter under opposition, but those stories don't tell you how quickly it can be extinguished by harsh reality!"
        },
        [51002408] = {
          Content = "当这件事传到当年的老爷——也就是工程炼金院派驻格雷姆矿场的董事耳朵里的时候，哈默尔得到的不是祝福，而是一顿毒打。",
          DialogueId = 51002408,
          GUID = "7FADDE90",
          NextDialogue = 51002409,
          SpeakNpcId = 700020,
          Subtitle = "When the master, who was the director of Glevum Pit appointed by the Aeolipile, learned about their relationship, Hamel Dickinson received a terrible thrashing instead of the master's blessing."
        },
        [51002409] = {
          Content = "不只是因为他的身份，更因为老爷已经为小姐安排了一门门当户对的亲事，对方是弗莱格桑行省的贵族——富豪新贵与没落贵族各取所需的联姻，没有比这更合适的婚事了。",
          DialogueId = 51002409,
          GUID = "7FADDEBA",
          NextDialogue = 51002410,
          SpeakNpcId = 700020,
          Subtitle = "It was not just because of his background — the master had already arranged a politically advantageous marriage for Miss Hilin. She was supposed to marry a noble from Flagson — a perfect match that would benefit both a new money family and a declining noble line.",
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002410] = {
          Content = "但小姐没有放弃，那时候的她勇敢又果决。她偷偷拜托我转交哈默尔一封信，约定一个月后，也就是4月26日零点，在银色和平广场见面。",
          DialogueId = 51002410,
          GUID = "7FADDEE4",
          NextDialogue = 51002411,
          SpeakNpcId = 700020,
          Subtitle = "But Miss Hilin didn't give up. She was such a brave and assertive young lady back then. She secretly asked me to deliver a letter to Mr Dickinson, asking him to meet her at midnight on April 26th at the Silverpeace Square."
        },
        [51002411] = {
          Content = "那天正赶上老爷生日，仆人们都在为宴会忙前忙后。小姐便计划趁机逃出去，对她来说那是唯一一次逃离的机会。",
          DialogueId = 51002411,
          GUID = "7FADDF0E",
          NextDialogue = 51002412,
          SpeakNpcId = 700020,
          Subtitle = "That day happened to be the master's birthday, and all hands would be busy preparing for the celebration. Miss Hilin saw it as her only chance to escape her father's control.",
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002412] = {
          Content = "她下定决心，只要哈默尔来，她就打算和他一起走，无论去哪里。",
          DialogueId = 51002412,
          GUID = "7FADDF38",
          NextOptions = {
            [1] = 510024141
          },
          SpeakNpcId = 700020,
          Subtitle = "She made up her mind that if he showed up, she would run away with him, no matter the destination."
        },
        [51002415] = {
          Content = "是。希琳小姐在那里等到天亮，等来的却只有气急败坏的父亲。不久之后，她就像一件货物那样，被远嫁到了弗莱格桑行省。",
          DialogueId = 51002415,
          GUID = "7FADDFB6",
          NextDialogue = 51002416,
          SpeakNpcId = 700020,
          Subtitle = "That's right. Miss Hilin waited there till dawn, but only her furious father showed up. Soon after, she was sent away like a parcel to Flagson.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002416] = {
          Content = "万幸！她的丈夫——也就是后来的老爷对她挺和善的，夫人也度过了四十年平静的时光。她从来不提当年的事情，就像是哈默尔·狄金森从未存在过一样。",
          DialogueId = 51002416,
          GUID = "7FADDFE0",
          NextDialogue = 51002417,
          SpeakNpcId = 700020,
          Subtitle = "Thank goodness that her husband — his lordship — treated her well, and she spent forty peaceful years with him. She never mentioned those days again, as if Hamel Dickinson had never existed."
        },
        [51002417] = {
          Content = "一年前老爷去世了，夫人的身体也大不如前。一天，她突然告诉我，她想在人生的最后一段时间回到冰湖城，去找一个她一直未曾得到的答案。那时我才知道，哈默尔这个人，她从来都没有忘掉，只是变成了一根扎在心里的刺。",
          DialogueId = 51002417,
          GUID = "7FADE00A",
          NextDialogue = 51002418,
          SpeakNpcId = 700020,
          Subtitle = "A year ago, his lordship passed away, and her ladyship's health began to fail. One day, she suddenly told me she wanted to return to Icelake in her final days, to find the answer she deserved. That's when I realised, she had never forgotten Hamel Dickinson — he had become a missing piece of her heart."
        },
        [51002418] = {
          Content = "我们搬来了冰湖城，然而城里没有人知道哈默尔的下落。我们找到了几个还在世的老矿工，但他们回忆了半天，只能想起，最后一次见到哈默尔，已经是四十年前的事了……",
          DialogueId = 51002418,
          GUID = "7FADE034",
          NextDialogue = 51002419,
          SpeakNpcId = 700020,
          Subtitle = "So we moved back to Icelake, but no one knew of Hamel Dickinson's whereabouts. We managed to track down a few old miners, but after racking their memories, the last time they remembered seeing Mr Dickinson was forty years ago...",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002419] = {
          Content = "唉，不知道夫人有生之年，还能不能了却最后的心事。",
          DialogueId = 51002419,
          GUID = "7FADE05E",
          NextDialogue = 51002420,
          SpeakNpcId = 700020,
          Subtitle = "*sigh* I wonder if her ladyship will see her final wish come true."
        },
        [51002420] = {
          Content = "都是陈年往事……唉，拉着你唠唠叨叨了这么久，看来我也老了啊。",
          DialogueId = 51002420,
          GUID = "7FADE088",
