    Loader = function()
      return {
        [51002421] = {
          Content = "你是狩月人，那肯定挺忙的，婶婶就不打扰你啦。",
          DialogueId = 51002421,
          GUID = "7FADE0B2",
          NextDialogue = 51002422,
          SpeakNpcId = 700020,
