          NextDialogue = 51003922,
          SpeakNpcId = 100001,
          Subtitle = "Since they call you a demon, you might as well act like one."
        },
        [51003922] = {
          Content = "走，我们回去找他们。",
          DialogueId = 51003922,
          GUID = "7FAED6F4",
          SpeakNpcId = 100001,
          Subtitle = "Let's go back and confront them."
        },
        [51004001] = {
