            [2] = "700089:n(100001)",
            [3] = "700090:n(100001)"
          }
        },
        [51004004] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "这就和卡戎勾搭上了？不是一家人不进一家门！",
          DialogueId = 51004004,
          GUID = "7FAEE468",
          NextDialogue = 51004005,
          SpeakNpcId = 700088,
          Subtitle = "She already made friends with a Charon? I knew it! Charons of a horn flock together!",
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [51004005] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我……",
          DialogueId = 51004005,
          GUID = "7FAEE492",
          NextDialogue = 51004006,
          SpeakNpcId = 700104,
          Subtitle = "I..."
        },
        [51004006] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（女孩努力地张嘴想要说什么，但似乎还没组织好语言，也许是需要一些小小的帮助。要对她的同学们说什么？）",
          DialogueId = 51004006,
          GUID = "7FAEE4BC",
          NextOptions = {
            [1] = 510040061,
            [2] = 510040062
          },
          Subtitle = "(The girl tries to say something, but she just can't get the words out. Perhaps she needs a little help to tell her classmates how she feels.)"
        },
        [51004007] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "是的……给我……给我……滚开！",
          DialogueId = 51004007,
          GUID = "7FAEE4E6",
          NextDialogue = 51004008,
          SpeakNpcId = 700104,
          Subtitle = "Yeah... Just... get... out of my... way!",
          TalkActionId = {
            [1] = "700104:Agree"
          }
        },
        [51004008] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "……不然我……我会和我的朋友一起把你们都送进地狱……！",
          DialogueId = 51004008,
          GUID = "7FAEE510",
          NextDialogue = 51004009,
          SpeakNpcId = 700104,
          Subtitle = "...Or I... My friend and I will send you all to hell...!"
        },
        [51004009] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "或者，你们不是喜欢虫子、喜欢老鼠吗？就把你们丢进下水道好了……！",
          DialogueId = 51004009,
          GUID = "7FAEE53A",
          NextDialogue = 51004010,
          SpeakNpcId = 700104,
          Subtitle = "Or... Since you like worms and rats so much... I... I'll send you into the sewers...!",
          TalkActionId = {
            [1] = "700104:Think_Start"
          }
        },
        [51004010] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "不，不行，老鼠肯定也会嫌弃你们的！",
          DialogueId = 51004010,
          GUID = "7FAEE564",
          NextDialogue = 51004011,
          SpeakNpcId = 700104,
          Subtitle = "Wait... No. Even the rats would think you're gross!",
          TalkActionId = {
            [1] = "700104:Think_End"
          }
        },
        [51004011] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（仿佛是打破了某种无形的束缚，女孩一反之前寡言少语的样子，滔滔不绝地骂了起来。）",
          DialogueId = 51004011,
          GUID = "7FAEE58E",
          NextDialogue = 51004012,
          Subtitle = "(As if breaking free from some intangible shackles, the girl, who was once so quiet, is now unleashing a stream of invective.)"
        },
        [51004012] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "她居然骂人？！她疯了吧？",
          DialogueId = 51004012,
          GUID = "7FAEE5B8",
          NextDialogue = 51004013,
          SpeakNpcId = 700088,
          Subtitle = "She curses at us?! Is she insane?",
          TalkActionId = {
            [1] = "700088:Confident_Start"
          },
          TurnTo = {
            [1] = "700089:n(700104)"
          }
        },
        [51004013] = {
          Camera = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "气死我了！来人啊，给我教训教训她，让我满意了这些钱就都是你们的！",
          DialogueId = 51004013,
          GUID = "7FAEE5E2",
          SpeakNpcId = 700089,
          Subtitle = "Ugh, I'm so pissed off right now! Someone teach her a lesson! Do it properly and this money is all yours!",
          TalkActionId = {
            [1] = "700089:Angry01_Start"
          }
        },
        [51004101] = {
          Camera = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "这个白头发的，不好惹啊！",
          DialogueId = 51004101,
          GUID = "7FAEF452",
          NextDialogue = 51004102,
          SpeakNpcId = 700088,
          Subtitle = "That white-haired demon is so strong!",
          TalkActionId = {
            [1] = "700088:Sigh_Start",
            [2] = "700089:Shock_Start"
          }
        },
        [51004102] = {
          Camera = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "喂……情况好像不太妙啊！我们还是先回去吧！",
          DialogueId = 51004102,
          GUID = "7FAEF47C",
          LookAt = {
            [1] = "700089:n(700088)"
          },
          NextDialogue = 51004103,
          SpeakNpcId = 700089,
          Subtitle = "Umm... This doesn't look good! We better scoot!"
        },
        [51004103] = {
          Camera = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "等等。",
          DialogueId = 51004103,
          GUID = "7FAEF4A6",
          NextDialogue = 51004104,
          SpeakNpcId = 100001,
          Subtitle = "Wait.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51004104] = {
          Camera = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "费伊已经和我这个恶魔签了一份协议，如果你们再找她的麻烦，我会在一分钟之内出现在你们面前。",
          DialogueId = 51004104,
          GUID = "7FAEF4D0",
          NextDialogue = 51004105,
          SpeakNpcId = 100001,
          Subtitle = "For your information, Faye has signed a demon contract with me. If you ever mess with her again, I will show up immediately to deal with you.",
          TalkActionId = {
            [1] = "700088:Sigh_End"
          }
        },
        [51004105] = {
          Camera = "-199.681152,34.707031,99.213867,0.000074,-2.198085,-15.786639,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "你……你……哼！",
          DialogueId = 51004105,
          GUID = "7FAEF4FA",
          SpeakNpcId = 700088,
          Subtitle = "You... you...! Hmph!",
          TalkActionId = {
            [1] = "700088:Angry01_Start"
          }
        },
        [51004106] = {
          Content = "学生们一溜烟逃走了。",
          DialogueId = 51004106,
          GUID = "7FAEF524",
          Subtitle = "(The students scamper off quickly.)"
        },
        [51004107] = {
          Content = "你看，他们的胆量不过如此。",
          DialogueId = 51004107,
          GUID = "7FAEF54E",
          NextDialogue = 51004108,
          SpeakNpcId = 100001,
          Subtitle = "See? That's all they can do."
        },
        [51004108] = {
          Content = "……嗯！",
          DialogueId = 51004108,
          GUID = "7FAEF578",
          NextDialogue = 51004109,
          SpeakNpcId = 700105,
          Subtitle = "...Yeah!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004109] = {
          Content = "多亏了有你在……你抡起拳头的样子真的很威风呢！",
          DialogueId = 51004109,
          GUID = "7FAEF5A2",
          NextOptions = {
            [1] = 510041091,
            [2] = 510041092
          },
          SpeakNpcId = 700105,
          Subtitle = "Thanks for helping me... You looked really cool throwing those punches!",
          bForbidSkipOptions = true
        },
        [51004110] = {
          Content = "诶，是、是吗？我只是……把以前偷偷在心里想的话说出来了。",
          DialogueId = 51004110,
          GUID = "7FAEF5CC",
          NextDialogue = 51004111,
          SpeakNpcId = 700105,
          Subtitle = "R—Really? I... I just said the things that I'd wanted to say but couldn't.",
          TalkActionId = {
            [1] = "700105:Shock_Start"
          }
        },
        [51004111] = {
          Content = "谢谢你，我长这么大，还是头一次心里这么畅快呢！",
          DialogueId = 51004111,
          GUID = "7FAEF5F6",
          NextDialogue = 51004112,
          SpeakNpcId = 700105,
          Subtitle = "Thank you so much. I've never felt so relieved and happy in my life!",
          TalkActionId = {
            [1] = "700105:Shock_End"
          }
        },
        [51004112] = {
          Content = "不用谢，他们短时间应该不会来找你麻烦了，我送你回家吧。这是我的地址——如果他们再惹你，就来找我。",
          DialogueId = 51004112,
          GUID = "7FAEF620",
          NextDialogue = 51004113,
          SpeakNpcId = 100001,
          Subtitle = "You're welcome. Your classmates should leave you alone for a while. I'll walk you home. Here, this is my address — come find me if they give you trouble again."
        },
        [51004113] = {
          Content = "我不想回家……！",
          DialogueId = 51004113,
          GUID = "7FAEF64A",
          NextDialogue = 51004114,
          SpeakNpcId = 700105,
          Subtitle = "I don't want to go home...!",
          TalkActionId = {
            [1] = "700105:Disagree"
          }
        },
        [51004114] = {
          Content = "我是卡戎，我要和卡戎之民待在一起……",
          DialogueId = 51004114,
          GUID = "7FAEF674",
          NextOptions = {
            [1] = 510041141
          },
          RestartTag = 51004114,
          SpeakNpcId = 700105,
          Subtitle = "I'm a Charon and I want to stay with my people...",
          TalkActionId = {
            [1] = "700105:Agree"
          },
          bForbidSkipOptions = true
        },
        [51004115] = {
          Content = "（女孩固执地噘着嘴，并没有被你说服。）",
          DialogueId = 51004115,
          GUID = "7FAEF69E",
          Subtitle = "(The girl gives you a stubborn pout, clearly unconvinced.)"
        },
        [51004116] = {
          Content = "还没看清他们吗？他们平日里对着你威风凛凛，但真的有人比他们拳头更硬的时候，他们就会落荒而逃。",
          DialogueId = 51004116,
          GUID = "7FAEF6C8",
          NextDialogue = 51004117,
          SpeakNpcId = 100001,
          Subtitle = "Don't you see that? They acted all tough and mighty towards you, but once someone stronger shows up, they just run away.",
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004117] = {
          Content = "他们不像自己表现得那么强大。所以，他们嘴里说的自然也不是事实。费伊，你是如假包换的索拉之民，不要被他们蹩脚的谎言骗了。",
          DialogueId = 51004117,
          GUID = "7FAEF6F2",
          NextDialogue = 51004118,
          SpeakNpcId = 100001,
          Subtitle = "They're not as strong as they pretend to be. Likewise, their words are not as truthful as they seem. Faye, don't listen to them. You're a hundred percent Sola."
        },
        [51004118] = {
          Content = "记住，永远不要因为别人的恶意质疑自己，责备自己……这是我的家人教会我的，我也把它教给你。",
          DialogueId = 51004118,
          GUID = "7FAEF71C",
          NextDialogue = 51004119,
          SpeakNpcId = 100001,
          Subtitle = "Remember, never doubt yourself just because someone says bad things about you... My family taught me this, and I hope you'll keep it in mind too."
        },
        [51004119] = {
          Content = "（女孩略带困惑地眨了眨眼，似乎还不能完全理解你话语的含义，但是表情却有所缓和。）",
          DialogueId = 51004119,
          GUID = "7FAEF746",
          NextDialogue = 51004120,
          Subtitle = "(The girl blinks her eyes in confusion. She probably doesn't understand everything you just said, but her expression softens.)"
        },
        [51004120] = {
          Content = "好吧……既然你这么说的话，我会努力试试看的！但在那之前，我还有最后一个小小的请求……",
          DialogueId = 51004120,
          GUID = "7FAEF770",
          NextDialogue = 51004121,
          SpeakNpcId = 700105,
          Subtitle = "Okay... If that's what you say, I'll try my best! But before I leave, I still have a teensy-weensy request...",
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004121] = {
          Content = "可以让我摸一下你的角吗？",
          DialogueId = 51004121,
          GUID = "7FAEF79A",
          NextOptions = {
            [1] = 510041211,
            [2] = 510041212
          },
          SpeakNpcId = 700105,
          Subtitle = "May I touch your horn?",
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51004122] = {
          Content = "谢谢！",
          DialogueId = 51004122,
          GUID = "7FAEF7C4",
          NextDialogue = 51004123,
          SpeakNpcId = 700105,
          Subtitle = "Thank you!",
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004123] = {
          Content = "（女孩小心翼翼地伸出纤瘦的手，摸了摸你头上的角。）",
          DialogueId = 51004123,
          GUID = "7FAEF7EE",
          NextDialogue = 51004126,
          Subtitle = "(The girl carefully extends her frail hand and touches the horn on your head.)"
        },
        [51004124] = {
          Content = "好吧，那我不摸，就看一看……",
          DialogueId = 51004124,
          GUID = "7FAEF818",
          NextDialogue = 51004125,
          SpeakNpcId = 700105,
          Subtitle = "Alright then. I won't touch it. But can I at least get a better look...?",
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004125] = {
          Content = "（女孩小心翼翼地凑上来，仔细地打量着你头上的角。）",
          DialogueId = 51004125,
          GUID = "7FAEF842",
          NextDialogue = 51004126,
          Subtitle = "(She carefully approaches you and studies the horn on your head.)"
        },
        [51004126] = {
          Content = "原来真正的角，是这样的啊……",
          DialogueId = 51004126,
          GUID = "7FAEF86C",
          NextDialogue = 51004127,
          SpeakNpcId = 700105,
          Subtitle = "So this is what a real Charon horn looks like..."
        },
        [51004127] = {
          Content = "红色的，很精巧……还会反射阳光呢。确实比我的辫子要可爱多了。",
          DialogueId = 51004127,
          GUID = "7FAEF896",
          NextOptions = {
            [1] = 510041271
          },
          SpeakNpcId = 700105,
          Subtitle = "It's red and really delicate... it even reflects the sunlight. It looks way cuter than my pigtails.",
          bForbidSkipOptions = true
        },
        [51004128] = {
          Content = "你是第一个这么说的人。但它们现在都被弄乱了……我要重新梳好才行。",
          DialogueId = 51004128,
          GUID = "7FAEF8C0",
          NextDialogue = 51004129,
          SpeakNpcId = 700105,
          Subtitle = "You're the first to tell me that. But my pigtails are all messed up now... I have to braid them again.",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004129] = {
          Content = "（女孩从书包里找出一把梳子，认真地将头上的两条辫子重新梳好，然后将它们向上提起来，比划出角的样子。）",
          DialogueId = 51004129,
          GUID = "7FAEF8EA",
          NextDialogue = 51004130,
          Subtitle = "(The girl takes out a comb from her bag. She then carefully combs and re-braids her pigtails. Once she's done, she lifts them up.)",
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004130] = {
          Content = "这样像不像恶魔角？",
          DialogueId = 51004130,
          GUID = "7FAEF914",
          NextOptions = {
            [1] = 510041301,
            [2] = 510041302
          },
          SpeakNpcId = 700105,
          Subtitle = "Now, do they look like demon horns?",
          bForbidSkipOptions = true
        },
        [51004131] = {
          Content = "嘿嘿。",
          DialogueId = 51004131,
          GUID = "7FAEF93E",
          NextDialogue = 51004133,
          SpeakNpcId = 700105,
          Subtitle = "Heheh."
        },
        [51004132] = {
          Content = "哈哈，那也不错。",
          DialogueId = 51004132,
          GUID = "7FAEF968",
          NextDialogue = 51004133,
          SpeakNpcId = 700105,
          Subtitle = "Haha. That's good, too.",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004133] = {
          Content = "啊，我口袋里还有多的发圈呢，要不要给你也扎个小辫子？",
          DialogueId = 51004133,
          GUID = "7FAEF992",
          NextOptions = {
            [1] = 510041331,
            [2] = 510041332
          },
          SpeakNpcId = 700105,
          Subtitle = "I have plenty of hairbands in my pocket. Can I braid a pigtail for you?",
          bForbidSkipOptions = true
        },
        [51004134] = {
          Content = "就扎一下让我看看嘛！",
          DialogueId = 51004134,
          GUID = "7FAEF9BC",
          NextDialogue = 51004135,
          SpeakNpcId = 700105,
          Subtitle = "Please! I wanna see how it looks!"
        },
        [51004135] = {
          Content = "（女孩不由分说地踮起脚尖，试图把你按到一个她能够得到的位置。看来，她已经精神多了。）",
          DialogueId = 51004135,
          GUID = "7FAEF9E6",
          NextDialogue = 51004136,
          Subtitle = "(The girl stands on her toes and pushes you down to reach your hair. She seems a lot more positive and energetic than before.)"
        },
        [51004136] = {
          Content = "来，稍微蹲下一些……",
          DialogueId = 51004136,
          GUID = "7FAEFA10",
          NextDialogue = 51004137,
          SpeakNpcId = 700105,
          Subtitle = "Come on, just squat down a little...",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004137] = {
          Content = "（你感到脑后的发丝被人轻轻地揪住了。女孩梳头的动作非常温柔，看来不用担心发际线受到伤害了。）",
          DialogueId = 51004137,
          GUID = "7FAEFA3A",
          NextDialogue = 51004138,
          Subtitle = "(You feel the girl slightly tugging your hair. She combs your hair very gently. You don't have to worry about losing any.)",
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004138] = {
          Content = "好了！哇，你扎辫子的样子好可爱！",
          DialogueId = 51004138,
          GUID = "7FAEFA64",
          NextDialogue = 51004139,
          SpeakNpcId = 700105,
          Subtitle = "Done! Wow, you look so pretty with pigtails!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004139] = {
          Content = "可惜我没有带镜子……",
          DialogueId = 51004139,
          GUID = "7FAEFA8E",
          NextDialogue = 51004140,
          SpeakNpcId = 700105,
          Subtitle = "Too bad I don't have a mirror...",
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004140] = {
          Content = "啊……我想到了！我可以画出来。",
          DialogueId = 51004140,
          GUID = "7FAEFAB8",
          NextDialogue = 51004141,
          SpeakNpcId = 700105,
          Subtitle = "Ah...! I know! I can draw a picture of you.",
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004141] = {
          Content = "（女孩打开书包，在笔记本上认真画着你的样子。）",
          DialogueId = 51004141,
          GUID = "7FAEFAE2",
          NextDialogue = 51004142,
          Subtitle = "(The girl opens her backpack and takes out a notebook. She then tries to draw a nice picture of you.)"
        },
        [51004142] = {
          Content = "对了，你叫什么名字呀？",
          DialogueId = 51004142,
          GUID = "7FAEFB0C",
          NextOptions = {
            [1] = 510041421
          },
          SpeakNpcId = 700105,
          Subtitle = "Oh, I forgot to ask — what's your name?",
          bForbidSkipOptions = true
        },
        [51004143] = {
          Content = "嗯！{nickname}，我会一直一直记住你的。给，这是我给你画的画像，再见！",
          DialogueId = 51004143,
          GUID = "7FAEFB36",
          NextDialogue = 51004144,
          SpeakNpcId = 700105,
          Subtitle = "Okay, ! I'll always remember you. Here, keep this picture I drew of you. See you around!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004144] = {
          Content = "……太神秘了，这就是城里人的艺术吗……",
          DialogueId = 51004144,
          GUID = "7FAEFB60",
          NextDialogue = 51004145,
          SpeakNpcId = 100001,
          Subtitle = "...That is some modern abstract art."
        },
        [51004145] = {
          Content = "（女孩正准备离开，忽然又回过头，认真地看向你。）",
          DialogueId = 51004145,
          GUID = "7FAEFB8A",
          NextDialogue = 51004146,
          Subtitle = "(The girl is about to leave but she suddenly turns around and gives you a serious gaze.)"
        },
        [51004146] = {
          Content = "对了……刚才给你梳头的时候，我突然想到一件事。",
          DialogueId = 51004146,
          GUID = "7FAEFBB4",
          NextDialogue = 51004147,
          SpeakNpcId = 700105,
          Subtitle = "Oh yeah... While I was combing your hair, I suddenly remembered something."
        },
        [51004147] = {
          Content = "他们一直都告诉我，卡戎是恶魔的孩子，是脑袋笨笨又一肚子坏水的，总是在做坏事的……",
          DialogueId = 51004147,
          GUID = "7FAEFBDE",
          NextDialogue = 51004148,
          SpeakNpcId = 700105,
          Subtitle = "They kept telling me that Charons are demon's children who are stupid, evil, and are always doing bad things...",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004148] = {
          Content = "这些话……其实也不是真的吧？",
          DialogueId = 51004148,
          GUID = "7FAEFC08",
          NextDialogue = 51004149,
          SpeakNpcId = 700105,
          Subtitle = "I don't think those words are true.",
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004149] = {
          Content = "那也是他们用来欺负你们的借口，对不对？",
          DialogueId = 51004149,
          GUID = "7FAEFC32",
          NextOptions = {
            [1] = 510041491,
            [2] = 510041492
          },
          SpeakNpcId = 700105,
          Subtitle = "They were just lies made up as an excuse to bully your kind, right?",
          TalkActionId = {
            [1] = "700105:Confident_Start"
          },
          bForbidSkipOptions = true
        },
        [51004150] = {
          Content = "你们一定……承受了比我多得多的痛苦吧。",
          DialogueId = 51004150,
          GUID = "7FAEFC5C",
          NextDialogue = 51004151,
          SpeakNpcId = 700105,
          Subtitle = "You must have... suffered way more pain than I ever have.",
          TalkActionId = {
            [1] = "700105:Confident_End"
          }
        },
        [51004151] = {
          Content = "今后，如果有什么我能帮得上忙的事，请尽管说……不是因为我们是同类，而是因为我们是朋友。",
          DialogueId = 51004151,
          GUID = "7FAEFC86",
          SpeakNpcId = 700105,
          Subtitle = "If there's anything I can do to help in the future, please do let me know... It's not because we're the same kind, but because we're friends.",
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          }
        },
        [51004152] = {
          Content = "同学们还是不喜欢我，但现在我已经不怕他们了！这都是多亏了你！",
          DialogueId = 51004152,
          GUID = "7FAEFCB0",
          SpeakNpcId = 700105,
          Subtitle = "My classmates still don't like me, but I'm not afraid of them anymore! All thanks to you!"
        },
        [51004201] = {
          Content = "啧，生面孔啊。",
          DialogueId = 51004201,
          GUID = "7FAF04BA",
          NextDialogue = 51004202,
          SpeakNpcId = 700096,
          Subtitle = "Tsk. A new face.",
          TalkActionId = {
            [1] = "700096:Talk03_Start"
          }
        },
        [51004202] = {
          Content = "（眼前的男人眯起眼，抿了抿嘴唇上锐利的裂口，吐出干燥的话语。）",
          DialogueId = 51004202,
          GUID = "7FAF04E4",
          NextDialogue = 51004203,
          Subtitle = "(The man before you squints, his lips cracked and dry, as he gruffly spits out his words.)"
        },
        [51004203] = {
          Content = "说说吧，谁介绍你来的？",
          DialogueId = 51004203,
          GUID = "7FAF050E",
          NextOptions = {
            [1] = 510042031,
            [2] = 510042032,
            [3] = 510042033
          },
          SpeakNpcId = 700096,
          Subtitle = "Tell me. Who sent you here?",
          TalkActionId = {
            [1] = "700096:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51004204] = {
          Content = "（一个新的问题，才是最好的回答。）",
          DialogueId = 51004204,
          GUID = "7FAF0538",
          NextDialogue = 51004207,
          Subtitle = "(Answering a question with another question always works.)"
        },
        [51004205] = {
          Content = "（“介绍”？很明显，他是在等什么人。）",
          DialogueId = 51004205,
          GUID = "7FAF0562",
          NextDialogue = 51004207,
          Subtitle = "(It is obvious that he's waiting for someone.)"
        },
        [51004206] = {
          Content = "（不知道他在问什么，但没人会拒绝这个回答。）",
          DialogueId = 51004206,
          GUID = "7FAF058C",
          NextDialogue = 51004207,
          Subtitle = "(I don't know what he meant, but that's an answer that no one will refuse.)"
        },
        [51004207] = {
          Content = "（男人沉默了一阵，抬眼打量起你来，几乎能听见他抬头时脊椎疲惫地的异响。）",
          DialogueId = 51004207,
          GUID = "7FAF05B6",
          NextDialogue = 51004208,
          Subtitle = "(The man broods silently for a while, assessing you. His posture decrepit as he raises his head with an audible creak.)"
        },
        [51004208] = {
          Content = "碎嘴子。",
          DialogueId = 51004208,
          GUID = "7FAF05E0",
          NextDialogue = 51004209,
          SpeakNpcId = 700096,
          Subtitle = "You smooth talker.",
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004209] = {
          Content = "（他轻哼了一声，又似乎很满意你的回答。）",
          DialogueId = 51004209,
          GUID = "7FAF060A",
          NextDialogue = 51004210,
          Subtitle = "(He snorted, but he seemed to be satisfied with your answer.)"
        },
        [51004210] = {
          Content = "不管是谁介绍你来的，反正也是为了我口袋里的货，对吧？",
          DialogueId = 51004210,
          GUID = "7FAF0634",
          NextDialogue = 51004211,
          SpeakNpcId = 700096,
          Subtitle = "I don't care who the fixer is. You're here for the stuff in my pocket, ain't that right?",
          TalkActionId = {
            [1] = "700096:Confident_Start"
          }
        },
        [51004211] = {
          Content = "（男人扯开衣领，黯淡的金属管自怀中闪过。）",
          DialogueId = 51004211,
          GUID = "7FAF065E",
          NextDialogue = 51004212,
          Subtitle = "(He opens his collar to reveal a dull iron piece.)",
          TalkActionId = {
            [1] = "700096:Confident_End"
          }
        },
        [51004212] = {
          Content = "（他立刻收紧了衣领，警惕地望了望四周。）",
          DialogueId = 51004212,
          GUID = "7FAF0688",
          NextDialogue = 51004213,
          Subtitle = "(After showing it, he quickly conceals it again, looking around warily.)"
        },
        [51004213] = {
          Content = "4号口径，双管单发，不论是卡戎人还是秽兽，在它面前都走不过两下。",
          DialogueId = 51004213,
          GUID = "7FAF06B2",
          NextDialogue = 51004214,
          SpeakNpcId = 700096,
          Subtitle = "Calibre 4. Double barrelled. Single shot. No Charon or Filthoid can survive a blast from this baby."
        },
        [51004214] = {
          Content = "（男人撇了撇嘴，像在谈论农用杀虫剂的功效。）",
          DialogueId = 51004214,
          GUID = "7FAF06DC",
          NextDialogue = 51004215,
          Subtitle = "(His lip curls, as if he's just discussing the uses of a pesticide.)"
        },
        [51004215] = {
          Content = "这回的货不要钱，只要你帮我办件事。",
          DialogueId = 51004215,
          GUID = "7FAF0706",
          NextOptions = {
            [1] = 510042151,
            [2] = 510042152
          },
          SpeakNpcId = 700096,
          Subtitle = "You can have it for free, but I'll need you to do something for me.",
          bForbidSkipOptions = true
        },
        [51004216] = {
          Content = "哆嗦什么？你不就是冲着这玩意来的吗？",
          DialogueId = 51004216,
          GUID = "7FAF0730",
          NextDialogue = 51004217,
          SpeakNpcId = 700096,
          Subtitle = "Cut the crap. You're here for this piece of metal, ain't that right?",
          TalkActionId = {
            [1] = "700096:Explain01_Start"
          }
        },
        [51004217] = {
          Content = "事儿办利索了，不仅东西归你，我再追补给你一笔。",
          DialogueId = 51004217,
          GUID = "7FAF075A",
          NextOptions = {
            [1] = 510042171,
            [2] = 510042172
          },
          RestartTag = 51004216,
          SpeakNpcId = 700096,
          Subtitle = "Do the job, and it's yours. I can even give you extra money.",
          TalkActionId = {
            [1] = "700096:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51004218] = {
          Content = "想快点，我等不了你太久。",
          DialogueId = 51004218,
          GUID = "7FAF0784",
          SpeakNpcId = 700096,
          Subtitle = "Are you in or what? I ain't got all day."
        },
        [51004219] = {
          Content = "好吧，你要我做什么？",
          DialogueId = 51004219,
          GUID = "7FAF07AE",
          NextDialogue = 51004220,
          SpeakNpcId = 100001,
          Subtitle = "Fine, I'm in. What's the deal?"
        },
        [51004220] = {
          Content = "爽快，一会儿我给你个地方，目标就是那地方除了女人之外的东西都清了。",
          DialogueId = 51004220,
          GUID = "7FAF07D8",
          NextDialogue = 51004221,
          SpeakNpcId = 700096,
          Subtitle = "Good. I'll give you a location. Kill everything there except for a woman.",
          TalkActionId = {
            [1] = "700096:Agree"
          }
        },
        [51004221] = {
          Content = "这……感情问题……？",
          DialogueId = 51004221,
          GUID = "7FAF0802",
          NextDialogue = 51004222,
          SpeakNpcId = 100001,
          Subtitle = "So... A bad romance, huh?"
        },
        [51004222] = {
          Content = "别多嘴。",
          DialogueId = 51004222,
          GUID = "7FAF082C",
          NextDialogue = 51004223,
          SpeakNpcId = 700096,
          Subtitle = "None of your beeswax. Just get it done.",
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004223] = {
          Content = "(男人紧了紧衣领，抿住干瘪的嘴唇，不愿再吐出任何一个字。)",
          DialogueId = 51004223,
          GUID = "7FAF0856",
          Subtitle = "(The man tightens his collar and licks his dried lips, unwilling to utter another word.)"
        },
        [51004301] = {
          Content = "行啊，收了钱就走吧，我不希望在这附近见到你。",
          DialogueId = 51004301,
          GUID = "7FAF1522",
          NextDialogue = 51004302,
          SpeakNpcId = 700101,
          Subtitle = "That was impressive. Now, take the quid and leave. Don't want to see you around here again.",
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004302] = {
          Content = "你是想找人清理附近的秽兽？就算不雇佣我，也会有人处理那些秽兽的。",
          DialogueId = 51004302,
          GUID = "7FAF154C",
          NextDialogue = 51004303,
          SpeakNpcId = 100001,
          Subtitle = "You just wanted the Filthoids cleared? You didn't need to hire me for that. Someone would have handled it eventually."
        },
        [51004303] = {
          Content = "有人处理？谁？那群把卡戎人当狗的杂碎？",
          DialogueId = 51004303,
          GUID = "7FAF1576",
          NextDialogue = 51004304,
          SpeakNpcId = 700101,
          Subtitle = "Someone? You mean those bloody uniformed buggers treating Charons like trash?",
          TalkActionId = {
            [1] = "700101:Angry01_Start"
          }
        },
        [51004304] = {
          Content = "你猜猜他们到时候打开门，发现这里住的是一个卡戎女人，他们会怎么办？",
          DialogueId = 51004304,
          GUID = "7FAF15A0",
          NextDialogue = 51004305,
          SpeakNpcId = 700101,
          Subtitle = "What do you think happens when they find a frail Charon woman alone in there?",
          TalkActionId = {
            [1] = "700101:Angry01_End"
          }
        },
        [51004305] = {
          Content = "（男人突然捂紧胸口，浑身战栗起来，像是伤口被扯痛一般。好一阵，他才止住颤抖，偏过头，吐出一口唾沫钉在地上。）",
          DialogueId = 51004305,
          GUID = "7FAF15CA",
          NextDialogue = 51004306,
          Subtitle = "(The man suddenly clutches his chest, shaking and wincing as if a deep, old wound has flared. He stops shaking after a while, and then turns his head to spit on the ground.)"
        },
        [51004306] = {
          Content = "一个善良的卡戎女人，为了救一个重伤躺在路边的陌生人，砸伤了内城跑出来的烈犬。",
          DialogueId = 51004306,
          GUID = "7FAF15F4",
          NextDialogue = 51004307,
          SpeakNpcId = 700101,
          Subtitle = "A kind Charon woman once threw stones at a hound that ran out of the inner city to save an injured stranger."
        },
        [51004307] = {
          Content = "就因为这点事，她被毒打一顿，拖出冰湖城的门，丢到这荒地里。",
          DialogueId = 51004307,
          GUID = "7FAF161E",
          NextDialogue = 51004308,
          SpeakNpcId = 700101,
          Subtitle = "For that, they flogged her, dragged her bleeding body outside Icelake, and left her in this wilderness."
        },
        [51004308] = {
          Content = "这……也许你可以想办法帮她离开冰湖城，换个地方生活。",
          DialogueId = 51004308,
          GUID = "7FAF1648",
          NextDialogue = 51004309,
          SpeakNpcId = 100001,
          Subtitle = "...Maybe you can figure out a way to get her out of Icelake and live somewhere else."
        },
        [51004309] = {
          Content = "……快了，快攒够了。",
          DialogueId = 51004309,
          GUID = "7FAF1672",
          NextDialogue = 51004310,
          SpeakNpcId = 700101,
          Subtitle = "...I'm working on it. Soon I'll have enough cash.",
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004310] = {
          Content = "（男人转过身，面向帐篷的方向，僵硬的嘴角罕见地被撬开了一瞬，露出类似笑容的表情。）",
          DialogueId = 51004310,
          GUID = "7FAF169C",
          LookAt = {
            [1] = "700101:n(700100)"
          },
          NextDialogue = 51004311,
          Subtitle = "(The man turns around to face the tent. His stiff lips open into what seems to be a smile, a rare expression for this man.)",
          TurnTo = {
            [1] = "700101:n(700100)"
          }
        },
        [51004311] = {
          Content = "（你似乎听见了朽木舒展时发出的干燥异响。）",
          DialogueId = 51004311,
          GUID = "7FAF16C6",
          Subtitle = "(You thought you heard the cracks made by dead wood being straightened out.)"
        },
        [51004401] = {
          Content = "下水道里的什么是不会消失的？",
          DialogueId = 51004401,
          GUID = "7FAF258A",
          NextOptions = {
            [1] = 510044011,
            [2] = 510044012,
            [3] = 510044013
          },
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What's in the sewers that never goes away?",
          bForbidSkipOptions = true
        },
        [51004402] = {
          Content = "进来吧。",
          DialogueId = 51004402,
          GUID = "7FAF25B4",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Come on in."
        },
        [51004403] = {
          Content = "这不是什么都不知道的蠢货该来的地方。",
          DialogueId = 51004403,
          GUID = "7FAF25DE",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "This is no place for a clueless fool like you."
        },
        [51004501] = {
          Camera = "-234.128906,122.0,168.883789,0.0,-11.799739,-20.999071,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "没有女人，只有秽兽，全清完了。还是说这光秃秃的地皮也要我给铲了？",
          DialogueId = 51004501,
          FinalCamera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF35F2",
          LookAt = {
            [1] = "700101:n(100001)",
            [2] = "100001:n(700101)"
          },
          NextDialogue = 51004502,
          SpeakNpcId = 100001,
          Subtitle = "No woman — just Filthoids. They're all down. Or was I supposed to polish the ground for you too?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51004502] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嘴皮子还挺厉害，没找到我说的女人你就不奇怪吗？",
          DialogueId = 51004502,
          GUID = "7FAF361C",
          NextDialogue = 51004503,
          SpeakNpcId = 700101,
          Subtitle = "Heh. Sharp tongue, huh? Not even curious why she wasn't there?",
          TalkActionId = {
            [1] = "100001:Confident_End",
            [2] = "700101:Talk03_Start"
          }
        },
        [51004503] = {
          Camera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你说地方，我清完，委托只是这样而已。",
          DialogueId = 51004503,
          GUID = "7FAF3646",
          NextDialogue = 51004504,
          SpeakNpcId = 100001,
          Subtitle = "You gave me a location. I cleared it. That's the job.",
          TalkActionId = {
            [1] = "700101:Talk03_End",
            [2] = "100001:Explain01_Start"
          }
        },
        [51004504] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "专业，这才是狩月人该有的样子。抱歉试探了一下你，做我们这行的，总得多留个心眼。",
          DialogueId = 51004504,
          GUID = "7FAF3670",
          NextDialogue = 51004505,
          SpeakNpcId = 700101,
          Subtitle = "Now that's professional. Thing is — this wasn't the spot. Had to throw out a few false leads. In our line of work, you learn to trust slow and lie fast.",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700101:Agree"
          }
        },
        [51004505] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "去这张纸上的位置吧，和之前一样，除了女人之外的东西全清了。",
          DialogueId = 51004505,
          GUID = "7FAF369A",
          SpeakNpcId = 700101,
          Subtitle = "Here. This is the real location. Same deal — clear out everything except the woman.",
          TalkActionId = {
            [1] = "700101:Give"
          }
        },
        [51004901] = {
          Content = "（街边一位拿着一叠纸的女人吸引了你的注意：你留意到纸上罗列着一些药剂。也许这个女人与<H>玛尔洁给的某个线索</>有关。）",
          DialogueId = 51004901,
          GUID = "7FAF7792",
          LookAt = {
            [1] = "700010:n(0)"
          }
        },
        [51004902] = {
          Content = "你决定向她展示玛尔洁曾交给你的某样线索。",
          DialogueId = 51004902,
          FinalDialogueId = 51004905,
          GUID = "7FAF77BC",
          NextOptions = {
            [1] = 510049021,
            [2] = 510049022,
            [3] = 510049023
          },
          Subtitle = "You decide to show her one thing you got from Margie.",
          bForbidSkipOptions = true
        },
        [51004903] = {
          Content = "（女人一言不发，只是用警惕的目光盯着你，摇了摇头。看来，这不是她遗落的东西。）",
          DialogueId = 51004903,
          GUID = "7FAF77E6",
          NextOptions = {
            [1] = 510049031,
            [2] = 510049032
          },
          Subtitle = "(The woman remains silent. She looks at you warily and shakes her head. Perhaps what you showed her isn't something she lost.)",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004905] = {
          Content = "露娜……医生？这份药方是你写的吗。",
          DialogueId = 51004905,
          GUID = "7FAF783A",
          NextDialogue = 51004906,
          SpeakNpcId = 100001,
          Subtitle = "Dr Luna, is it? Did you write this prescription?"
        },
        [51004906] = {
          Content = "（你将手中的药方翻到露娜面前，好让药方上那些危险的文字能被露娜看到。）",
          DialogueId = 51004906,
          GUID = "7FAF7864",
          NextDialogue = 51004907,
          Subtitle = "(You present the prescription in your hand and show Luna the dangerous lines.)"
        },
        [51004907] = {
          Content = "“城外的秽兽吃我们的肉，城内的农场主剪我们的毛。猎犬们吃着白面包，卡戎羊儿嚼着地上的草。摸爬滚打、摇尾乞怜，只为博主人芳心一笑。”",
          DialogueId = 51004907,
          GUID = "7FAF788E",
          NextDialogue = 51004908,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Wild Filthoids gorge on our flesh, city lords shear our fleece. The hounds dine on fine white loaves, while lowly Charon sheep chew yellowed grass. We roll and we crawl, we baa and we fawn. The masters laugh, while we bear it all.\""
        },
        [51004908] = {
          ContentES = "Ah... O-Oh, yo... eh...",
          DialogueId = 51004908,
          GUID = "7FAF78B8",
          NextDialogue = 51004909,
          SpeakNpcId = 700010,
          Subtitle = "Ah... Uhm... I...",
          TalkActionId = {
            [1] = "700010:Shock_Start"
          }
        },
        [51004909] = {
          Content = "（露娜看后立马支支吾吾了起来，焦急地用两只手胡乱地在空中比划，无论是字迹还是反应，都证明了你找对了人。）",
          DialogueId = 51004909,
          GUID = "7FAF78E2",
          NextOptions = {
            [1] = 510049091,
            [2] = 510049092
          },
          Subtitle = "(Luna starts to stammer and gesture wildly with her hands. Her handwriting and reactions prove that you have found the right person.)",
          TalkActionId = {
            [1] = "700010:Shock_Loop"
          }
        },
        [51004910] = {
          Content = "（露娜的情绪稍微平复了一些。）",
          DialogueId = 51004910,
          GUID = "7FAF790C",
          NextDialogue = 51004912,
          Subtitle = "(Your words seem to calm Luna down a little.)",
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004911] = {
          Content = "（她看起来更加焦急了。）",
          DialogueId = 51004911,
          GUID = "7FAF7936",
          NextDialogue = 51004912,
          Subtitle = "(Your actions seem to make her more anxious.)",
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004912] = {
          Content = "这张纸如果落在其他人手里，你会惹上不小的麻烦吧？",
          DialogueId = 51004912,
          GUID = "7FAF7960",
          NextDialogue = 51004913,
          SpeakNpcId = 100001,
          Subtitle = "If this piece of paper falls into the hands of someone else, you might get into some serious trouble."
        },
        [51004913] = {
          Content = "（露娜指了指喉咙上的疤痕，然后拿起一张空白的纸，奋笔疾书。）",
          DialogueId = 51004913,
          GUID = "7FAF798A",
          NextDialogue = 51004914,
          Subtitle = "(Luna points at her throat, then grabs a blank sheet and scribbles at speed.)",
          TalkActionId = {
            [1] = "700010:Explain02_Start"
          }
        },
        [51004914] = {
          Content = "“我曾是一个吟游诗人。几个仇恨卡戎的人绑架了我。他们嘲弄我，殴打我，割去我的头发，划破我的皮肤。”",
          DialogueId = 51004914,
          GUID = "7FAF79B4",
          NextDialogue = 510049141,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I used to be a wandering bard. Then they came — those thugs who hate the Charon. They dragged me away. Mocked me. Beat me. Shaved my head. Tore my skin.\"",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [51004915] = {
          Content = "那你为什么还在写？",
          DialogueId = 51004915,
          GUID = "7FAF79DE",
          NextDialogue = 51004916,
          SpeakNpcId = 100001,
          Subtitle = "Then... why do you keep writing these?"
        },
        [51004916] = {
          Content = "（露娜低头在纸上写着什么。）",
          DialogueId = 51004916,
          GUID = "7FAF7A08",
          NextDialogue = 51004917,
          Subtitle = "(Luna lowers her head and keeps on writing.)"
        },
        [51004917] = {
          Content = "“憋在心里太难受。”",
          DialogueId = 51004917,
          GUID = "7FAF7A32",
          NextOptions = {
            [1] = 510049171,
            [2] = 510049172,
            [3] = 510049173
          },
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Keeping it bottled up inside hurts a lot.\"",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004918] = {
          Content = "“是啊。什么都改变不了，我甚至写了都不敢给别人看，但我还是忍不住想写点什么。”",
          DialogueId = 51004918,
          GUID = "7FAF7A5C",
          NextDialogue = 51004919,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I know. I can't even show others what I wrote. But I just can't help it.\""
        },
        [51004919] = {
          Content = "“我已经唱不了歌了，我怕如果有一天我什么也不写了，我就会弄丢最后一件珍贵的东西，那时我就真的什么也没有了。”",
          DialogueId = 51004919,
          GUID = "7FAF7A86",
          NextDialogue = 51004920,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I can't sing anymore. And if I give up writing too, I'll lose the last valuable thing I have. When that happens, I'll truly have nothing to call my own.\""
        },
        [51004920] = {
          Content = "不开心的话就多找点实在的事做吧，会让自己舒服些。还有，你写可以，下次记得收好吧，别再不小心弄丢了。",
          DialogueId = 51004920,
          GUID = "7FAF7AB0",
          NextDialogue = 51004921,
          SpeakNpcId = 100001,
          Subtitle = "You can find something else to keep yourself occupied. That should make you feel better. You can also keep writing if it helps, just don't lose your work again."
        },
        [51004921] = {
          Content = "（女人思索了良久，点了点头。）",
          DialogueId = 51004921,
          GUID = "7FAF7ADA",
          NextDialogue = 51004922,
          Subtitle = "(The woman thinks for a while and then nods.)",
          TalkActionId = {
            [1] = "700010:Agree"
          }
        },
        [51004922] = {
          Content = "“谢谢你还给我，好心人。这是给你的报酬。”",
          DialogueId = 51004922,
          GUID = "7FAF7B04",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Thank you for returning this to me, gentle soul. Please accpet this as a thank-you gift.\"",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004923] = {
          Content = "“你谬赞了，我只是一个只敢在纸上发牢骚的胆小鬼，我连把这些东西给其他人看的勇气都没有。”",
          DialogueId = 51004923,
          GUID = "7FAF7B2E",
          NextDialogue = 51004924,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"You flatter me. I'm just a coward whose complaints remain on useless pieces of scrap. I don't even have the courage to show them to anyone.\"",
          TalkActionId = {
            [1] = "700010:Disagree"
          }
        },
        [51004924] = {
          Content = "你肯写真心话，已经比大多数人勇敢了。只是下次收好吧，别再不小心弄丢了。",
          DialogueId = 51004924,
          GUID = "7FAF7B58",
          NextDialogue = 51004925,
          SpeakNpcId = 100001,
          Subtitle = "Expressing your true feelings in writing already makes you braver than most people. Just try to keep your work safe and don't lose it again."
        },
        [51004925] = {
          Content = "（女人嘴唇勾出一丝微笑，她点点头，你看到她双眼噙着泪花。）",
          DialogueId = 51004925,
          GUID = "7FAF7B82",
          NextDialogue = 51004926,
          Subtitle = "(The lady gives a faint smile and nods. You can see tears welling in her eyes.)"
        },
        [51004926] = {
          Content = "“谢谢你还给我，好心人。这是给你的报酬。”",
          DialogueId = 51004926,
          GUID = "7FAF7BAC",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Thank you for returning this to me, gentle soul. Please accpet this as a thank-you gift.\"",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004927] = {
          Content = "（女人发出一声嘶哑的哀鸣，痛苦地将脸埋在手掌间。良久，她才颤抖着打开手袋，把它交给了你。）",
          DialogueId = 51004927,
          GUID = "7FAF7BD6",
          NextDialogue = 51004928,
          Subtitle = "(The lady gives a raspy wail and buries her sad face in her hands. After a long time, she finally opens her purse and gives you some money while quaking in fear.)",
          TalkActionId = {
            [1] = "700010:Sigh_Start"
          }
        },
        [51004928] = {
          Content = "“这些全都送给你，求你把那张纸还给我吧。”",
          DialogueId = 51004928,
          GUID = "7FAF7C00",
          NextDialogue = 51004929,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"This is all yours. Just give me back that piece of paper.\"",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004929] = {
          Content = "（你满意地点点头——要是这张纸落在别人手里，她损失的可不只是这些了。你为她免去了大麻烦，这是你应得的报酬。）",
          DialogueId = 51004929,
          GUID = "7FAF7C2A",
          Subtitle = "(You give a satisfied nod — if the poetry falls into the wrong hands, she would lose more than just a wad of cash. You saved her from that fate and deserve the payment.)"
        },
        [51004930] = {
          Content = "呜呜……哇呀……",
          DialogueId = 51004930,
          GUID = "7FAF7C54",
          NextDialogue = 51004931,
          SpeakNpcId = 700010,
          Subtitle = "Hngh... Waaahh..."
        },
        [51004931] = {
          Content = "（露娜一如既往吐露着无人能听懂的字句，她看向你的目光有些躲闪。）",
          DialogueId = 51004931,
          GUID = "7FAF7C7E",
          Subtitle = "(Luna still mumbles unintelligibly. Her eyes dart about to avoid your gaze.)"
        },
        [51004935] = {
          Camera = "-843.349854,-34.817383,370.464844,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          Content = "不想活了是不是？交出来！",
          DialogueId = 51004935,
          FinalCamera = "-635.633789,-118.727051,302.828857,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          GUID = "7FAF7C7F",
          NextDialogue = 51004936,
          SpeakNpcId = 700225,
          Subtitle = "Got a death wish, have you? Hand it over!",
          ToFinalCameraBlendTime = 10
        },
        [51004936] = {
          Content = "让老子看看你又在写什么好东西——",
          DialogueId = 51004936,
          GUID = "7FAF7C80",
          NextDialogue = 51004937,
          SpeakNpcId = 700226,
          Subtitle = "Let's see what you've scribbled this time — what're you hiding, huh?"
        },
        [51004937] = {
          Content = "上次是喉咙不听使唤，这次是什么？眼？手爪子？",
          DialogueId = 51004937,
          GUID = "7FAF7C81",
          NextDialogue = 51004938,
          SpeakNpcId = 700225,
          Subtitle = "Last time it was your throat — what now? Your eyes? Hands? Maybe both?"
        },
        [51004938] = {
          Content = "啊……啊啊！",
          DialogueId = 51004938,
          GUID = "7FAF7C82",
          NextDialogue = 51004939,
          SpeakNpcId = 700010,
          Subtitle = "Aargh... aaaargh!"
        },
        [51004939] = {
          Content = "（被恶徒包围的女人慌忙捡着地上的纸张，紧咬着下嘴唇，脸色苍白，眼神恐惧。你不清楚他们的关系，但你知道女人正处于危险之中。）",
          DialogueId = 51004939,
          GUID = "7FAF7C83",
          Subtitle = "(The woman scrambles to scoop up her scattered notes. Her lips press tight, her face ghost-pale. Fear blazes in her eyes as the thugs close in. You're not sure what they're after — but one thing's clear: she's in danger.)"
        },
        [51004941] = {
          Content = "（露娜慌忙向你鞠了鞠躬，似是感谢，又接着焦急地开始收拾地上散落的纸。）",
          DialogueId = 51004941,
          GUID = "7FAF7C84",
          NextDialogue = 51004942,
          Subtitle = "(Luna gives you a quick bow — perhaps a gesture of thanks — then hastily drops down to gather the remaining papers.)"
        },
        [51004942] = {
          Content = "你还好吧？这些纸是什么？",
          DialogueId = 51004942,
          GUID = "7FAF7C85",
          NextDialogue = 51004943,
          SpeakNpcId = 100001,
          Subtitle = "You all right? What are these papers?"
        },
        [51004943] = {
          Content = "啊……呜呜！",
          DialogueId = 51004943,
          GUID = "7FAF7C86",
          NextDialogue = 51004944,
          SpeakNpcId = 700010,
          Subtitle = "Ah... u-uh...!"
        },
        [51004944] = {
          Content = "（你注意到，那些纸上写着“药方”……也许这个女人与<H>玛尔洁给的某个线索</>有关？）",
          DialogueId = 51004944,
          GUID = "7FAF7C87",
          NextOptions = {
            [1] = 510049011,
            [2] = 510049012
          },
          Subtitle = "(Your eyes flick over one of the sheets — you spot the word \"prescription.\" Could this woman be linked to one of the items Margie gave you?)",
          bForbidSkipOptions = true
        },
        [51004945] = {
          Content = "唔……唔唔。",
          DialogueId = 51004945,
          GUID = "7FAF7C88",
          NextDialogue = 51004946,
          SpeakNpcId = 700010,
          Subtitle = "Mm... mmm."
        },
        [51004946] = {
          Content = "（女人面带微笑，似是在表达谢意。）",
          DialogueId = 51004946,
          GUID = "7FAF7C89",
          NextDialogue = 51004947,
          SpeakNpcId = 700010,
          Subtitle = "(She gives a quiet nod and a faint smile — her way of saying thank you.)"
        },
        [51004947] = {
          Content = "我曾经认识一名医生，虽然他现在不在冰湖城了，但我可以尝试去他曾经的住所帮你找找有没有合适的药方。",
          DialogueId = 51004947,
          GUID = "7FAF7C8A",
          NextDialogue = 51004948,
          SpeakNpcId = 100001,
          Subtitle = "I knew a doctor. He's not in Icelake anymore, but I can check the place where he used to stay. There might be something there that could help your throat."
        },
        [51004948] = {
          Content = "呜……",
          DialogueId = 51004948,
          GUID = "7FAF7C8B",
          NextDialogue = 51004949,
          SpeakNpcId = 700010,
          Subtitle = "Mm..."
        },
        [51004949] = {
          Content = "（露娜低下头，她似乎知道自己的嗓子铁定是没救的。但她再次抬头的时候眼中却闪了闪希望的光芒，好像在说：“万一呢？”）",
          DialogueId = 51004949,
          GUID = "7FAF7C8C",
          Subtitle = "(She lowers her head. She knows her voice may be gone for good — but when she looks up again, there's a flicker of hope in her eyes, as if to say: \"But what if...?\")"
        },
        [51004950] = {
          Content = "呜……哇啊！",
          DialogueId = 51004950,
          GUID = "7FAF7C8D",
          NextDialogue = 51004951,
          SpeakNpcId = 700010,
          Subtitle = "Hngh... wwryaa..."
        },
        [51004951] = {
          Content = "（女人警惕地看着你，拼命摇着头，似乎是在说“我真的没有钱了”。）",
          DialogueId = 51004951,
          GUID = "7FAF7C8E",
          NextDialogue = 51004952,
          SpeakNpcId = 700010,
          Subtitle = "(She stares at you warily, shaking her head in panic. You can almost hear the words she's unable to speak: \"I don't have anything left!\")"
        },
        [51004952] = {
          Content = "唉，别那么紧张，这次我是来帮忙的。就那么白拿你的也不是我的作风。",
          DialogueId = 51004952,
          GUID = "7FAF7C8F",
          NextDialogue = 51004953,
          SpeakNpcId = 100001,
          Subtitle = "Easy. I'm actually here to help this time. Didn't plan to just take your stuff and walk away for free."
        },
        [51004953] = {
          Content = "我曾经认识一名医生，虽然他现在不在冰湖城了，但我可以尝试去他曾经的住所帮你找找有没有合适的药方。",
          DialogueId = 51004953,
          GUID = "7FAF7C90",
          NextDialogue = 51004954,
          SpeakNpcId = 100001,
          Subtitle = "I knew a doctor. He's not in Icelake anymore, but I can check the place where he used to stay. There might be something there that could help your throat."
        },
        [51004954] = {
          Content = "（露娜的脸上写满了疑惑——现在的她并不是那么信任你。）",
          DialogueId = 51004954,
          GUID = "7FAF7C91",
          Subtitle = "(Doubt lingers in her eyes. She doesn't really trust you at the moment.)"
        },
        [51004955] = {
          Content = "（某书架上）",
          DialogueId = 51004955,
          GUID = "7FAF7C92",
          Subtitle = "(On a bookshelf)"
        },
        [51004956] = {
          Content = "（冰湖城总会有些古怪的感冒像大风一样刮过，虽然来得快去得也快，但孩子们生病时总归是很难受的。————感冒速效药）",
          DialogueId = 51004956,
          Duration = 4,
          GUID = "7FAF7C93",
          IsBlack = 1,
          NextDialogue = 51004957,
          Subtitle = "(Icelake knows all too well the strange seasonal colds that sweep in like winter winds— \nstriking fast, and vanishing just as quickly. Even so, they're always hard on the little ones.\n\n—Rapid Relief: Cold Remedy)"
        },
        [51004957] = {
          Content = "感觉不是这个。",
          DialogueId = 51004957,
