        },
        [51005936] = {
          Content = "没个半年走不过来，脑子正常的人都不会这么干。",
          DialogueId = 51005936,
          GUID = "7FB02160",
          NextDialogue = 51005937,
          SpeakNpcId = 700126,
          Subtitle = "At least six months, I guess. Only those lacking common sense would attempt a thing like this.",
          TalkActionId = {
            [1] = "700126:Talk01_Start"
          }
        },
        [51005937] = {
          Camera = "94.544922,-72.209961,230.001465,0.000072,-21.18392,156.51619,41.357956,1.5,false,Disable,1.2",
          Content = "咳咳，我作为大大哥，一向是很厚道的。你们把箱子还给{nickname}，再帮我跑几个腿，我就宽宏大量，不和你们计较了。",
          DialogueId = 51005937,
          GUID = "7FB0218A",
          LookAt = {
            [1] = "700126:n(700123)"
          },
          NextOptions = {
            [1] = 510059371,
            [2] = 510059372
          },
          SpeakNpcId = 700126,
          Subtitle = "Ahem, alright. I am a fair Super Bro. Give back the chest to  and run some errands for me, and I'll show mercy and forgive you.",
          TalkActionId = {
            [1] = "700126:Talk01_End"
          },
          bForbidSkipOptions = true
        },
        [51005938] = {
          Camera = "-80.927734,-14.502441,185.629883,0.000013,-16.983728,145.126053,40.0,1.5,false,Disable,1.2",
          Content = "这不得给你找回场子嘛。再说了，这可不是欺负，他们还得谢谢咱们呢。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51005938,
          GUID = "7FB021B4",
          LookAt = {
            [1] = "700126:n(100001)"
          },
          NextDialogue = 51005940,
          Scripts = "PlayAnimation{_delay{2},ActorId{700126},AnimationId{\"Confident_End\"},Duration{0.1}}",
          SpeakNpcId = 700126,
          Subtitle = "Well, I'm trying to make them show some respect. Besides, we're not taking advantage of them. They're going to thank us for this.",
          TalkActionId = {
            [1] = "700126:Confident_Start"
          }
        },
        [51005939] = {
          Camera = "-497.850647,19.27832,106.201172,0.000021,-0.383638,8.526095,35.000008,1.5,false,Disable,1.2",
          Content = "啊？没有了，真的没有了！我们的兜比你的脸还干净！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51005939,
          GUID = "7FB021DE",
          NextDialogue = 51005940,
          SpeakNpcId = 700123,
          Subtitle = "Huh? We got nothing left! It's true! Our pockets are emptier than a ghost town!",
          TalkActionId = {
            [1] = "700123:Disagree"
          }
        },
        [51005940] = {
          Camera = "97.474609,-59.709961,145.413574,0.000075,-3.983646,159.516525,41.357956,1.5,false,Disable,1.2",
          Content = "好吧，那就下次再说。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51005940,
          GUID = "7FB02208",
          LookAt = {
            [1] = "700126:n(700123)"
          },
          NextDialogue = 51005941,
          SpeakNpcId = 700126,
          Subtitle = "Fine. Maybe next time."
        },
        [51005941] = {
          Content = "谢谢大大哥们！",
          DialogueId = 51005941,
          GUID = "7FB02232",
          NextDialogue = 51005942,
          SpeakNpcName = "UI_CMNpc_Name_SanXiongdi",
          Subtitle = "Thank you, Super Bros!",
          TalkActionId = {
            [1] = "700123:Agree",
            [2] = "700124:Agree",
            [3] = "700125:Agree"
          }
        },
        [51005942] = {
          Camera = "-425.447266,140.77002,126.579102,0.000018,-1.584133,-13.274455,35.000011,1.5,false,Disable,1.2",
          Content = "你看。",
          DialogueId = 51005942,
          GUID = "7FB0225C",
          LookAt = {
            [1] = "700126:n(100001)"
          },
          NextDialogue = 51005943,
          SpeakNpcId = 700126,
          Subtitle = "Told you.",
          TalkActionId = {
            [1] = "700126:Talk01_Start",
            [2] = "100001:Sigh_Start"
          }
        },
        [51005943] = {
          Camera = "-462.640625,217.032227,95.944336,0.000029,2.416118,-24.873308,35.222115,1.5,false,Disable,1.2",
          Content = "好了，既然麻烦完美解决，今晚都去我那吃？",
          DialogueId = 51005943,
          FinalCamera = "-600.123047,257.368652,161.696289,0.000031,-4.384059,-21.671299,23.312325,1.5,false,Disable,1.2",
          GUID = "7FB02286",
          LookAt = {
            [1] = "700126:n(700126)"
          },
          NextDialogue = 51005944,
          Scripts = "TurnTo{_delay{1.5},TurnToDescription{\"700126:n(100001)\"}}",
          SpeakNpcId = 700126,
          Subtitle = "Alright, looks like we've got everything settled. Come to my place tonight. Dinner's on me.",
          TalkActionId = {
            [1] = "700126:Talk01_End",
            [2] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 12
        },
        [51005944] = {
          Content = "好，又蹭到饭了！",
          DialogueId = 51005944,
          GUID = "7FB022B0",
          LookAt = {
            [1] = "700126:n(700125)"
          },
          NextDialogue = 51005945,
          SpeakNpcId = 700125,
          Subtitle = "Free food? Hooray!",
          TalkActionId = {
            [1] = "700125:Angry01_Start"
          }
        },
        [51005945] = {
          Content = "走吧走吧，跟我不用那么客气。",
          DialogueId = 51005945,
          GUID = "7FB022DA",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700126,
          Subtitle = "Let's go.",
          TalkActionId = {
            [1] = "700126:Talk01_Start"
          }
        },
        [51005946] = {
          Content = "大大哥们好！",
          DialogueId = 51005946,
          GUID = "7FB02304",
          LookAt = {
            [1] = "700130:n(0)"
          },
          SpeakNpcName = "UI_CMNpc_Name_SanXiongdi",
          Subtitle = "Howdy, Super Bros!",
          TurnTo = {
            [1] = "700130:n(0)"
          }
        },
        [51006001] = {
          Camera = "-1493.62561,331.186523,137.640625,0.0,0.0,-131.798843,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "这个月的话，老猎人小队排行第一，卡米拉女士冷暴力受害者小队排行第二，目标是天生无敌大狩月人小队第三……",
          DialogueId = 51006001,
          GUID = "7FB02C0A",
          NextDialogue = 51006002,
          Scripts = "SEQ{CameraMoveTo{TargetPosition{\"-1493.62561,315.0,137.640625,0.0,0.0,-131.798843,35.0,100000.0,false,DoNotOverride,2.8\"},duration{1.5}},PARA{CameraMoveTo{_delay{2},TargetPosition{\"-963.597046,234.248047,150.28125,0.000001,1.799966,34.202541,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},PlayAnimation{ActorId{200003},AnimationId{\"Talk03_Start\"},Duration{2}}},CameraMoveTo{_delay{4},TargetPosition{\"-7.200806,-120.374023,142.90625,0.000004,0.0,87.602119,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
          SpeakNpcId = 700143,
          Subtitle = "For this month, the Old Hunters is in the lead, with Victims of Ms Camilla's Gaslighting right behind them, and Our Aim is to Become Naturally Invincible Super Phoxhunters is ranked third...",
          TurnTo = {
            [1] = "100001:n(700143)",
            [2] = "700144:n(700143)"
          }
        },
        [51006002] = {
          Camera = "-7.200806,-120.374023,142.90625,0.000004,0.0,87.602119,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "老队伍的名字都还是挺规矩的，但……哎，总有一天这个看板要会写不下的。",
          DialogueId = 51006002,
          FinalCamera = "-7.493896,-127.367188,142.90625,0.000004,0.0,87.602119,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB02C34",
          NextDialogue = 51006003,
          Scripts = "SEQ{PlayAnimation{ActorId{700143},AnimationId{\"Disagree\"},Duration{1}},PlayAnimation{ActorId{700143},AnimationId{\"Sigh_Start\"},Duration{1}}}",
          SpeakNpcId = 700143,
          Subtitle = "The older teams have proper names, but the new ones... *sigh* We're running out of space on this bulletin board.",
          ToFinalCameraBlendTime = 5
        },
        [51006003] = {
          Camera = "-23.626343,-435.28418,117.951172,0.0,-1.000022,88.595695,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（水仙平原的侍者在看板前一边写着奇怪词汇一边喃喃自语，看上去非常专注地发着愁。）",
          DialogueId = 51006003,
          FinalCamera = "-23.626343,-403.0,117.951172,0.0,-0.999994,88.595695,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB02C5E",
          NextDialogue = 51006004,
          Scripts = "SEQ{PARA{LookAt{LookAtDescription{\"700144:n(100001)\"}},LookAt{LookAtDescription{\"100001:n(700144)\"}}},PARA{LookAt{_delay{2},LookAtDescription{\"700144:n(700144)\"}},LookAt{_delay{2},LookAtDescription{\"100001:n(100001)\"}}},PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}}}",
          Subtitle = "(A tavern waiter mumbles to himself while writing down a series of strange names on the board. He seems to be intently worried about something.)",
          ToFinalCameraBlendTime = 7
        },
        [51006004] = {
          Camera = "-29.76123,245.500977,144.087891,0.000001,-1.299956,-87.998413,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你好，请问你这是……？",
          DialogueId = 51006004,
          GUID = "7FB02C88",
          NextDialogue = 51006005,
          SpeakNpcId = 100001,
          Subtitle = "Hello, what are you doing...?",
          TalkActionId = {
            [1] = "700143:Sigh_End",
            [2] = "700144:Confident_End",
            [3] = "100001:Explain02_Start"
          },
          TurnTo = {
            [1] = "700143:n(100001)"
          }
        },
        [51006005] = {
          Camera = "-41.585571,-289.919922,132.876953,0.000008,0.399996,91.800735,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯？我在更新这个月的狩月人小队排名——卡米拉女士想出来的法子，整理这些狩月人们的数据。",
          DialogueId = 51006005,
          GUID = "7FB02CB2",
          NextDialogue = 51006006,
          SpeakNpcId = 700143,
          Subtitle = "Huh? Oh, I'm updating the Phoxhunter Team Rankings for the month. It was Ms Camilla's idea to keep track and showcase how the Phoxhunters are doing.",
          TalkActionId = {
            [1] = "700143:Explain01_Start",
            [2] = "100001:Explain02_End"
          }
        },
        [51006006] = {
          Camera = "-41.585571,-289.919922,132.876953,0.000008,0.399996,91.800735,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "每个月完成了多少委托呀，平均一次委托收了多少佣金呀，和委托人吵没吵过架之类。",
          DialogueId = 51006006,
          GUID = "7FB02CDC",
          NextDialogue = 51006007,
          SpeakNpcId = 700143,
          Subtitle = "This includes how many commissions they've knocked out this month, their average earnings per job, whether they've had any dust-ups with clients, that sort of thing.",
          TalkActionId = {
            [1] = "700143:Explain01_End"
          }
        },
        [51006007] = {
          Camera = "-22.652466,-432.3125,117.951172,0.0,-1.000022,87.596008,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "所以你们如果要和奥特赛德一起结成新的小队的话，也最好商量一下自己的队伍名字，找我来登记。",
          DialogueId = 51006007,
          FinalCamera = "-22.652466,-411.0,117.951172,0.0,-1.000022,87.596001,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB02D06",
          NextDialogue = 51006008,
          SpeakNpcId = 700143,
          Subtitle = "So, if you're thinking of starting a new team with Outsider, do take the time to discuss your team's name and get back to me once you're ready to register.",
          ToFinalCameraBlendTime = 7
        },
        [51006008] = {
          Camera = "-165.896606,-64.533203,164.121094,0.000034,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "原来是这样，之前白确实听到过一些抱怨，说这里的狩月人们看起来脾气都不是很好，不敢委托工作。",
          DialogueId = 51006008,
          GUID = "7FB02D30",
          LookAt = {
            [1] = "100001:n(700144)",
            [2] = "700144:n(100001)"
          },
          NextDialogue = 51006009,
          SpeakNpcId = 700144,
          Subtitle = "That makes sense. Snow's heard quite a few complaints about the bad-tempered Phoxhunters here. They do have a reputation for being a bit grumpy and intimidating.",
          TurnTo = {
            [1] = "700144:n(100001)"
          }
        },
        [51006009] = {
          Camera = "-165.896606,-64.533203,164.121094,0.000034,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "但是如果一个队伍起了什么汪汪队喵喵队之类的名字，就突然没那么可怕了——毕竟人们总说，喜欢小动物的没有坏人。",
          DialogueId = 51006009,
          GUID = "7FB02D5A",
          NextDialogue = 51006010,
          Scripts = "SetLocation{ActorId{700145},TargetPoint{\"TargetPoint_Aote\"},Visibility{\"Show\"}}",
          SpeakNpcId = 700144,
          Subtitle = "But — imagine teams named \"Paw Buddies\" or \"Kitten Pals\" — they'd seem so friendly! Everyone knows animal lovers are good people.",
          TalkActionId = {
            [1] = "700144:Talk01_Start"
          }
        },
        [51006010] = {
          Camera = "184.0,-79.0,87.949219,0.000015,4.999999,-170.997498,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "我看不见得，我之前的单人小队的名字也是小动物啊，怎么委托数就没见涨。",
          DialogueId = 51006010,
          FinalCamera = "184.0,-76.0,87.949219,0.000015,4.999999,-170.997498,33.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB02D84",
          LookAt = {
            [1] = "100001:n(700145)",
            [2] = "700144:n(700145)"
          },
          NextDialogue = 51006011,
          SpeakNpcId = 700145,
          Subtitle = "Well, I don't think so. My solo team was named after a small critter but that didn't help me get more commissions.",
          TalkActionId = {
            [1] = "700145:Think_Start",
            [2] = "700144:Talk01_End"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "100001:n(700145)",
            [2] = "700144:n(700145)"
          }
        },
        [51006011] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396646,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊！狗耳朵是从哪里冒出来的！",
          DialogueId = 51006011,
          GUID = "7FB02DAE",
          NextDialogue = 51006012,
          SpeakNpcId = 700144,
          Subtitle = "Whoa? Mutt Ears! You just popped up from nowhere!",
          TalkActionId = {
            [1] = "700144:Shock_Start",
            [2] = "700145:Think_End"
          },
          TurnTo = {
            [1] = "700145:n(100001)"
          }
        },
        [51006012] = {
          Camera = "122.913086,-109.845703,133.205078,0.000018,0.999987,179.004623,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "这不是路过刚好看到我们的新朋友，过来看看，搭把手什么的？",
          DialogueId = 51006012,
          GUID = "7FB02DD8",
          NextDialogue = 51006013,
          SpeakNpcId = 700145,
          Subtitle = "I was just passing by and saw our new friend. So I came to check on you guys and see if you need any help.",
          TalkActionId = {
            [1] = "700145:Talk03_Start"
          }
        },
        [51006013] = {
          Camera = "-262.660034,43.351562,185.205078,0.000012,-11.200007,-53.19593,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "你的小队名字是什么？",
          DialogueId = 51006013,
          GUID = "7FB02E02",
          NextDialogue = 51006014,
          SpeakNpcId = 100001,
          Subtitle = "What's the name of your team?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51006014] = {
          Camera = "122.937256,-108.84668,135.205078,0.000018,0.19994,178.604645,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "“食用昆虫研究队”……",
          DialogueId = 51006014,
          GUID = "7FB02E2C",
          NextDialogue = 51006015,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"700145:n(700145)\"}}",
          SpeakNpcId = 700145,
          Subtitle = "Edible Insects Researcher Squad..."
        },
        [51006015] = {
          Camera = "-262.660034,43.351562,185.205078,0.000012,-11.200007,-53.19593,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "首先我觉得我们提到小动物时一般想不到昆虫，然后我觉得你应该很清楚为什么这个名字不会带来更多委托……",
          DialogueId = 51006015,
          GUID = "7FB02E56",
          LookAt = {
            [1] = "700145:n(100001)"
          },
          NextDialogue = 51006016,
          SpeakNpcId = 100001,
          Subtitle = "Well, for starters, when people talk about small animals, they don't usually think of insects. Besides, you probably know why your team's name hasn't exactly been drumming up more commissions...",
          TalkActionId = {
            [1] = "100001:Disagree",
            [2] = "700145:Talk03_End"
          }
        },
        [51006016] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396646,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "就是就是，我刚刚还在想，奥特赛德怎么会给队伍起可爱小动物的名字，怎么想都不太可能！",
          DialogueId = 51006016,
          GUID = "7FB02E80",
          NextDialogue = 51006017,
          SpeakNpcId = 700144,
          Subtitle = "Exactly! I knew there was no way for Outsider to name his team after cutesy furballs!",
          TalkActionId = {
            [1] = "700144:Angry01_Start",
            [2] = "100001:Confident_End"
          }
        },
        [51006017] = {
          Camera = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "你懂什么，这叫做与众不同，一眼就能让人留下印象，你觉得呢，{nickname}？是不是非常有冲击力。",
          DialogueId = 51006017,
          GUID = "7FB02EAA",
          NextOptions = {
            [1] = 510060171,
            [2] = 510060172,
            [3] = 510060173
          },
          SpeakNpcId = 700145,
          Subtitle = "What do you know? I'm trying to stand out from the crowd and leave an impression. What do you think, ? The name of my team left its mark on you, right?",
          TalkActionId = {
            [1] = "700145:Explain01_Start",
            [2] = "700144:Angry01_End"
          },
          bForbidSkipOptions = true
        },
        [51006018] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "就是就是！",
          DialogueId = 51006018,
          GUID = "7FB02ED4",
          LookAt = {
            [1] = "700145:n(100001)",
            [2] = "100001:n(700145)",
            [3] = "700144:n(700145)"
          },
          NextDialogue = 51006023,
          SpeakNpcId = 700144,
          Subtitle = "Exactly!",
          TalkActionId = {
            [1] = "700144:Agree"
          }
        },
        [51006019] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "就是就是！",
          DialogueId = 51006019,
          GUID = "7FB02EFE",
          LookAt = {
            [1] = "700145:n(100001)",
            [2] = "100001:n(700145)",
            [3] = "700144:n(700145)"
          },
          NextDialogue = 51006023,
          SpeakNpcId = 700144,
          Subtitle = "Exactly!",
          TalkActionId = {
            [1] = "700144:Agree"
          }
        },
        [51006020] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "不——好——！你们这样下去，队伍一定会变成看板上倒数第一的！",
          DialogueId = 51006020,
          GUID = "7FB02F28",
          LookAt = {
            [1] = "700145:n(100001)",
            [2] = "100001:n(700145)",
            [3] = "700144:n(700145)"
          },
          NextDialogue = 51006021,
          SpeakNpcId = 700144,
          Subtitle = "NO WAY! Keep messing around like this and our team will hit the rock bottom of the list!",
          TalkActionId = {
            [1] = "700144:Disagree"
          }
        },
        [51006021] = {
          Camera = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "倒数第一不也会让人好奇——",
          DialogueId = 51006021,
          GUID = "7FB02F52",
          NextDialogue = 51006022,
          SpeakNpcId = 700145,
          Subtitle = "Being at the rock bottom might get people interested as well—"
        },
        [51006022] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "停停停！",
          DialogueId = 51006022,
          GUID = "7FB02F7C",
          NextDialogue = 51006023,
          SpeakNpcId = 700144,
          Subtitle = "NOPE! Not on my watch!",
          TalkActionId = {
            [1] = "700144:Disagree"
          }
        },
        [51006023] = {
          Camera = "-165.896606,-64.533203,164.121094,0.000035,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "现在我们组成了新的队伍，已经不是你一个人单打独斗了，所以你这个名字作废，我们来取一个新的名字！",
          DialogueId = 51006023,
          GUID = "7FB02FA6",
          NextDialogue = 51006024,
          SpeakNpcId = 700144,
          Subtitle = "Now that we've teamed up, it's time to scrap the old team name of yours and come up with a new one!",
          TalkActionId = {
            [1] = "700144:Explain02_Start"
          },
          TurnTo = {
            [1] = "100001:n(700144)"
          }
        },
        [51006024] = {
          Camera = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "呃，也行，不过要是我们三个意见不统一怎么办。",
          DialogueId = 51006024,
          GUID = "7FB02FD0",
          NextDialogue = 51006025,
          SpeakNpcId = 700145,
          Subtitle = "Umm, okay. But what if the three of us can't agree on the name?",
          TalkActionId = {
            [1] = "700145:Agree",
            [2] = "700144:Explain02_End"
          }
        },
        [51006025] = {
          Camera = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
          Content = "哼哼，白早就想好啦，自然是靠身手决定，谁赢了就听谁的。跟我来，我们来比试比试吧。",
          DialogueId = 51006025,
          GUID = "7FB02FFA",
          Scripts = "SEQ{PlayAnimation{ActorId{700144},AnimationId{\"Agree\"},Duration{2}},PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{1}}}",
          SpeakNpcId = 700144,
          Subtitle = "Hah! This Demon King is way ahead of you. Let's hold a little contest, and the winner chooses the name. Come on, follow me for some challenges!"
        },
        [51006101] = {
          Camera = "245.083435,-275.051758,86.080566,0.0,0.0,113.398338,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "喔，这不是吵闹小白吗！后面跟着的是……食用昆虫研究队的赛特奥德！",
          DialogueId = 51006101,
          GUID = "7FB03C72",
          LookAt = {
            [1] = "100001:n(700146)",
            [2] = "700144:n(700146)",
            [3] = "700145:n(700146)"
          },
          NextDialogue = 51006102,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
          SpeakNpcId = 700146,
          Subtitle = "Ah, isn't this our resident loud chatterbox, Snow!? And behind you is... Mr Siteolder from the Edible Insects Researcher Squad！",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          TurnTo = {
            [1] = "100001:n(700146)",
            [2] = "700144:n(700146)",
            [3] = "700145:n(700146)",
            [4] = "700146:n(700144)"
          }
        },
        [51006102] = {
          Camera = "234.691406,72.036133,66.071777,0.000003,10.399475,-155.20079,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊，我当是谁呢，原来是探险家皎皎啊。虽然刚刚叫对了我的小队名让我有一点感动，但只是几天不见，你又把我名字叫错了。",
          DialogueId = 51006102,
          GUID = "7FB03C9C",
          NextDialogue = 51006103,
          Scripts = "SEQ{PlayAnimation{ActorId{700145},AnimationId{\"Explain01_Start\"},Duration{3}},PlayAnimation{ActorId{700145},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{700145},AnimationId{\"Disagree\"},Duration{1}}}",
          SpeakNpcId = 700145,
          Subtitle = "Oh, it's you, Lunoxplorer. Flattered you remember my team's name, but you've botched my name again. It's only been a few days!",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          TurnTo = {
            [1] = "700146:n(700145)"
          }
        },
        [51006103] = {
          Camera = "-105.877808,-273.970215,200.745117,0.000031,-17.99987,65.800964,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那是因为我的注意力总是在你带回来的记录上，等下次，我就一定会记对你的名字的！赛特奥德小哥。",
          DialogueId = 51006103,
          GUID = "7FB03CC6",
          NextDialogue = 51006104,
          SpeakNpcId = 700146,
          Subtitle = "That's because I'm always too focused on your performance data. I promise I'll get your name right next time, Mr Siteolder.",
          TalkActionId = {
            [1] = "700146:Explain01_Start"
          }
        },
        [51006104] = {
          Camera = "-253.942383,145.432129,112.640137,0.000095,-3.399563,-32.804798,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那么吵闹小白，这位是？",
          DialogueId = 51006104,
          GUID = "7FB03CF0",
          NextDialogue = 51006105,
          SpeakNpcId = 700146,
          Subtitle = "So, Snow the Loud Chatterbox, tell me about this one.",
          TalkActionId = {
            [1] = "700146:Explain01_End"
          },
          TurnTo = {
            [1] = "700146:n(700144)"
          }
        },
        [51006105] = {
          Camera = "-47.697998,-122.447266,163.110352,0.000107,-15.799224,-21.20565,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "{性别：他|她}呀，是{nickname}，我新认识的小仆从，现在我在引导{性别：他|她}成为一名合格的狩月人。",
          DialogueId = 51006105,
          GUID = "7FB03D1A",
          LookAt = {
            [1] = "100001:n(700144)"
          },
          NextDialogue = 51006106,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"700144:n(100001)\"}},LookAt{LookAtDescription{\"700144:n(100001)\"}},PlayAnimation{_delay{2},ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}}}",
          SpeakNpcId = 700144,
          Subtitle = "{性别:He|She} is my newly recruited little minion. I'm showing {性别:him|her} the ropes of being a qualified Phoxhunter. "
        },
        [51006106] = {
          Camera = "-70.926147,-57.200684,76.004883,0.000152,0.0,32.790924,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "那么，我再来向你介绍一下！她是探险家皎皎，我认识的皎皎之民中就数她最富有冒险精神，最喜欢收集各种冒险者的情报啦。",
          DialogueId = 51006106,
          GUID = "7FB03D44",
          LookAt = {
            [1] = "100001:n(700146)"
          },
          NextDialogue = 51006107,
          Scripts = "SEQ{CameraMoveTo{TargetPosition{\"-70.926147,-62.0,76.004883,0.000152,0.0,32.790958,28.0,100000.0,false,DoNotOverride,2.8\"},duration{2}},CameraMoveTo{TargetPosition{\"59.133484,-36.513672,112.323975,0.000181,0.0,78.584763,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"60.901123,-27.689453,112.323975,0.000181,0.0,78.984596,28.0,100000.0,false,DoNotOverride,2.8\"},duration{2}},CameraMoveTo{TargetPosition{\"35.020691,-126.598145,87.284668,0.000142,0.0,77.791298,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},PlayAnimation{ActorId{700146},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 700144,
          Subtitle = "That being said, time for me to introduce Lunoxplorer! She's the most adventurous Luno I've ever met, and she loves to collect all sorts of information about adventurers.",
          TurnTo = {
            [1] = "700144:n(700146)",
            [2] = "700146:n(100001)"
          }
        },
        [51006107] = {
          Camera = "35.020691,-126.598145,87.284668,0.000142,0.0,77.791298,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "你看，就连奥特赛德的那个糟糕的小队名字，她都会记得！",
          DialogueId = 51006107,
          GUID = "7FB03D6E",
          NextDialogue = 51006108,
          SpeakNpcId = 700144,
          Subtitle = "To prove that, she actually remembers that horrible name of Outsider's team!",
          TalkActionId = {
            [1] = "700146:Explain02_End"
          }
        },
        [51006108] = {
          Camera = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "奥德赛特的起名水准虽然一般，但身手还是很厉害的！换做一般的狩月人，顶着这样一个小队名字，应该在一年前转行或者三个月前饿毙街头了。",
          DialogueId = 51006108,
          GUID = "7FB03D98",
          NextDialogue = 51006109,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"62.480164,-164.678711,86.856934,0.000015,0.0,88.998657,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 700146,
          Subtitle = "While Mr Oldsiter may not excel at naming, he's certainly a seasoned Phoxhunter. An ordinary Phoxhunter stuck with a team name like that would have quit or starved to death by now.",
          TalkActionId = {
            [1] = "700145:Talk03_Start",
            [2] = "700146:Confident_Start"
          }
        },
        [51006109] = {
          Camera = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "饿毙……行吧，改，改吧。那么小个子你说的靠身手决定，是什么意思？",
          DialogueId = 51006109,
          GUID = "7FB03DC2",
          NextDialogue = 51006110,
          SpeakNpcId = 700145,
          Subtitle = "Starved to death...? Um, fine. Let's change that name. So, Button Mushroom, tell us more about the little trials.",
          TalkActionId = {
            [1] = "700146:Confident_End"
          }
        },
        [51006110] = {
          Camera = "78.202087,-48.859863,118.763184,0.000051,-12.200288,-36.19857,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哼，你的疙瘩脑袋总算转过弯了，那么先让我来和探险家皎皎前辈解释一下发生了什么。",
          DialogueId = 51006110,
          GUID = "7FB03DEC",
          NextDialogue = 51006111,
          SpeakNpcId = 700144,
          Subtitle = "Hmph, you've finally come around! Let me fill in Lunoxplorer on the situation.",
          TalkActionId = {
            [1] = "700144:Confident_Start",
            [2] = "700145:Talk03_End"
          }
        },
        [51006111] = {
          Camera = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（白张牙舞爪地比划了奥特赛德对于旧小队名的喜爱，以及通过靠身手来统一意见的打算。）",
          DialogueId = 51006111,
          GUID = "7FB03E16",
          IsBlack = 1,
          NextDialogue = 51006112,
          Subtitle = "(Snow gave a very exaggerated and animated tale of how Outsider was obsessed with the original name of his team and how the three of you decided to have a competition to decide the team's name.)"
        },
        [51006112] = {
          Content = "喔，我明白了，是用那个挑战来决定啊，那我是不会输的！",
          DialogueId = 51006112,
          GUID = "7FB03E40",
          NextDialogue = 51006113,
          SpeakNpcId = 700145,
          Subtitle = "Got it, we're deciding it through that challenge. Well, I won't be losing!",
          TalkActionId = {
            [1] = "700145:Angry01_Start"
          },
          TurnTo = {
            [1] = "700146:n(700145)"
          }
        },
        [51006113] = {
          Camera = "-107.990723,-296.696289,204.89624,0.000065,-19.999907,67.198593,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯，你确实是挑战次数最多的几个人之一，但{nickname}应该没有见过我设下的挑战，让我来说明一下。",
          DialogueId = 51006113,
          GUID = "7FB03E6A",
          NextDialogue = 51006114,
          SpeakNpcId = 700146,
          Subtitle = "Yes. You've made some of the most attempts so far. But  might not be familiar with my challenge, so here's a quick overview.",
          TalkActionId = {
            [1] = "700145:Angry01_End",
            [2] = "700146:Agree"
          }
        },
        [51006114] = {
          Camera = "18.039185,-278.991699,158.917725,0.000157,-13.200044,68.989624,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "简单来说呢，我之所以会对狩月人这么熟悉，是因为我会观察各位的身手，再记录下来。",
          DialogueId = 51006114,
          GUID = "7FB03E94",
          NextDialogue = 51006115,
          SpeakNpcId = 700146,
          Subtitle = "Simply put, I've gotten to know the Phoxhunters by observing and documenting their skills and performance.",
          TurnTo = {
            [1] = "700146:n(100001)"
          }
        },
        [51006115] = {
          Camera = "61.417114,-123.797852,85.32666,0.0,0.0,86.990524,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "但狩月人这么多，并且在他们执行委托时跟在后面也很危险，所以我就找了一个帮手——一位年长的，令人尊敬的，但是长得和你有些像的铁匠。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51006115,
          GUID = "7FB03EBE",
          NextDialogue = 51006116,
          Scripts = "SEQ{TurnTo{_delay{4},TurnToDescription{\"700146:n(700144)\"}},CameraMoveTo{_delay{1},TargetPosition{\"54.903625,146.320801,86.79541,0.000006,0.0,-72.008141,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"59.0,148.0,86.79541,0.000006,0.0,-72.008102,28.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
          SpeakNpcId = 700146,
          Subtitle = "The thing is, with so many Phoxhunters, observing them during live missions is too risky. That's why I enlisted the help of a respected elder — a smith who looks a bit like you."
        },
        [51006116] = {
          Camera = "123.392273,2.931152,85.919922,0.000078,0.0,-60.200184,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "难道你说的是铁匠皎皎前辈？我们认识她呀！",
          DialogueId = 51006116,
          GUID = "7FB03EE8",
          NextDialogue = 51006117,
          SpeakNpcId = 700144,
          Subtitle = "Are you talking about Lunosmith? We know her!",
          TalkActionId = {
            [1] = "700144:Agree"
          }
        },
        [51006117] = {
          Camera = "245.083435,-275.051758,86.080566,0.0,0.0,113.398293,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "喔，认识的话就好说了，你们应该见过她的手艺。",
          DialogueId = 51006117,
          GUID = "7FB03F12",
          NextDialogue = 51006118,
          SpeakNpcId = 700146,
          Subtitle = "Great, that makes things easier — you must have seen her handiwork."
        },
        [51006118] = {
          Camera = "-36.301025,308.482422,2046.960449,0.000022,-8.399964,-137.801437,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我拜托她做了一个魔法小玩意，能够在各个地方留下记号。那个记号只要被人碰一下，就会显出一段文字，也能记录下附近的人的行动。",
          DialogueId = 51006118,
          FinalCamera = "78.561584,181.818848,2047.960449,0.000022,-8.399964,-137.801376,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB03F3C",
          NextDialogue = 51006119,
          SpeakNpcId = 700146,
          Subtitle = "I asked her to make a magical gadget — a location marker that can be placed anywhere. Interacting with the marker displays a brief message and records nearby activities.",
          ToFinalCameraBlendTime = 10
        },
        [51006119] = {
          Camera = "-317.315186,330.895508,307.277344,0.000049,-21.599884,-50.999966,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "要是有人完成了文字要求的行动，就算是完成了挑战。要是结果足够好，就可以在我这里拿到一些报酬。所以说，我是最清楚怎么摸清狩月人身手的了。",
          DialogueId = 51006119,
          GUID = "7FB03F66",
          NextDialogue = 51006120,
          SpeakNpcId = 700146,
          Subtitle = "You complete the challenge by fulfilling the task specified in the message. And if the results are good, I might even have a prize for you. That's how I keep tabs on Phoxhunters' performance."
        },
        [51006120] = {
          Camera = "68.506897,3.594238,109.754639,0.000018,13.999626,-134.600388,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我可太熟悉这些挑战了，小个子这下失算了，我都不知道怎么输。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51006120,
          GUID = "7FB03F90",
          NextDialogue = 51006121,
          Scripts = "PlayAnimation{_delay{1},ActorId{700145},AnimationId{\"Disagree\"},Duration{2}}",
          SpeakNpcId = 700145,
          Subtitle = "I'm all too familiar with these challenges. You bet on the wrong horse, Button Mushroom. I don't even know how to lose.",
          TurnTo = {
            [1] = "700146:n(700145)"
          }
        },
        [51006121] = {
          Camera = "-17.909668,-172.834961,149.789795,0.000038,-17.999323,66.400116,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你先冷静一下，我只看最后的挑战结果。那么如果这位{nickname}{性别：小兄弟|小姑娘}也没问题的话，就来这里找我吧。",
          DialogueId = 51006121,
          GUID = "7FB03FBA",
          NextDialogue = 51006122,
          Scripts = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Disagree\"},Duration{2}},LookAt{LookAtDescription{\"700146:n(100001)\"}}}",
          SpeakNpcId = 700146,
          Subtitle = "Easy now. Let's see the results speak for themselves. Come find me here if you're up for it, {性别:young man|young lady}."
        },
        [51006122] = {
          Camera = "68.506897,3.594238,109.754639,0.000018,13.999626,-134.600388,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（探险家皎皎掏出笔，在你手中的冰湖城地图上做了一个标记。）",
          DialogueId = 51006122,
          GUID = "7FB03FE4",
          IsBlack = 1,
          Subtitle = "(Lunoxplorer took out a pen and marked a spot on your map of Icelake.)"
        },
        [51006201] = {
          Camera = "100.462158,-55.870972,113.845947,0.000005,-7.000062,-90.399178,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "好，那么在开始之前我讲解一下规则：在我说开始之后，沿着我标记的发光圈圈一直向前就好！",
          DialogueId = 51006201,
          GUID = "7FB04CDA",
          NextDialogue = 51006202,
          Scripts = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Explain02_Start\"},Duration{2}},PlayAnimation{ActorId{700146},AnimationId{\"Explain02_End\"},Duration{1}},PARA{TurnTo{TurnToDescription{\"700146:p(90)\"}},CameraMoveTo{TargetPosition{\"365.846802,-145.875488,80.777954,0.0,0.0,-161.797287,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}},CameraMoveTo{TargetPosition{\"365.846802,-135.0,80.777954,0.0,0.0,-161.797287,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
          SpeakNpcId = 700146,
          Subtitle = "Okay. Let's go over the rules before we start. Once I say \"GO\", you need to navigate through the glowing circles I've marked along the path."
        },
        [51006202] = {
          Camera = "176.590088,288.807129,234.116333,0.000006,-17.800079,-96.798767,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "别担心，别看那个奥特赛文那么有信心，但是我更看好你，加油加油。",
          DialogueId = 51006202,
          GUID = "7FB04D04",
          Scripts = "SEQ{TurnTo{TurnToDescription{\"700146:n(100001)\"}},LookAt{LookAtDescription{\"700146:n(100001)\"}},PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}}}",
          SpeakNpcId = 700146,
          Subtitle = "Don't worry. That Outsayer may look confident, but my money's on you. Go get 'em!",
          TalkActionId = {
            [1] = "700145:Sigh_Start",
            [2] = "100001:Confident_Start"
          }
        },
        [51006301] = {
          Content = "驾轻就熟，我赢定了。",
          DialogueId = 51006301,
          Duration = 3,
          GUID = "7FB05D42",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700145,
          Subtitle = "Easy peasy. I've got this in the bag."
        },
        [51006302] = {
          Content = "哎？谁往地上泼油？",
          DialogueId = 51006302,
          Duration = 3,
          GUID = "7FB05D6C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700145,
          Subtitle = "Huh? Who spilt oil on the ground?"
        },
        [51006303] = {
          Content = "不是？怎么屋顶还有狗？",
          DialogueId = 51006303,
          Duration = 3,
          GUID = "7FB05D96",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 51006304,
          SpeakNpcId = 700145,
          Subtitle = "What? A dog on the rooftop?"
        },
        [51006304] = {
          Content = "汪汪——",
          DialogueId = 51006304,
          Duration = 2,
          GUID = "7FB05DC0",
          SpeakNpcName = "UI_Npc_Name_Dog",
          Subtitle = "Woof, woof—"
        },
        [51006305] = {
          Content = "刚刚是发挥失常了吧，别着急，再来一次，我相信你！",
          DialogueId = 51006305,
          Duration = 3,
          GUID = "7FB05DEA",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700146,
          Subtitle = "It's okay, try again. I believe in you!"
        },
        [51006401] = {
          Content = "哦，{nickname}身手不错嘛，那么我们现在去进行第二场测试，跟着我来。",
          DialogueId = 51006401,
          Duration = 3,
          GUID = "7FB06DAA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 51006402,
          SpeakNpcId = 700146,
          Subtitle = "Well done, . Now, follow me to the second challenge."
        },
        [51006402] = {
          Content = "奥德特赛也抓紧赶上，不要跟丢了。",
          DialogueId = 51006402,
          Duration = 2,
          GUID = "7FB06DD4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700146,
          Subtitle = "Keep up, Oldtryer. Don't lose sight of us."
        },
        [51006501] = {
          Camera = "190.745117,183.455322,84.877686,0.000011,0.0,-90.395432,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "这一个测试的规则也很简单：我说开始后，面前会出现我拜托铁匠皎皎前辈做的气球。",
          DialogueId = 51006501,
          GUID = "7FB07E12",
          NextDialogue = 51006502,
          Scripts = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}},PARA{TurnTo{TurnToDescription{\"700146:p(-90)\"}},CameraMoveTo{TargetPosition{\"-135.275879,-75.0,84.279785,0.000003,0.0,-0.597107,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}},CameraMoveTo{TargetPosition{\"-135.275879,-63.0,84.279785,0.000003,0.0,-0.597107,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
          SpeakNpcId = 700146,
          Subtitle = "The rules for this challenge are also quite simple. Once I say \"GO\", balloons crafted by Lunosmith at my request will rise."
        },
        [51006502] = {
          Camera = "485.306641,-103.10376,80.212891,0.000003,0.0,-177.99791,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "瞄准，然后打爆它就好！",
          DialogueId = 51006502,
          GUID = "7FB07E3C",
          SpeakNpcId = 700146,
          Subtitle = "Shoot and pop them. That's it!",
          TalkActionId = {
            [1] = "700146:Confident_Start"
          }
        },
        [51006601] = {
          Content = "奇怪了，我的子弹呢？",
          DialogueId = 51006601,
          Duration = 2,
          GUID = "7FB08E7A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 700145,
          Subtitle = "Hey, where are my bullets?"
        },
        [51006602] = {
          Content = "……可恶，刚刚手上沾了油，装弹好麻烦。",
          DialogueId = 51006602,
          Duration = 2,
          GUID = "7FB08EA4",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 700145,
          Subtitle = "...Dammit. I got oil on my hands. I can hardly reload."
        },
        [51006603] = {
          Content = "别装弹了，{nickname}已经完成测试了。",
          DialogueId = 51006603,
          Duration = 2,
          GUID = "7FB08ECE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700146,
          Subtitle = "Don't bother reloading.  has already completed the challenge."
        },
        [51006701] = {
          Camera = "-20.024414,-347.564941,170.543701,0.000067,-13.199791,66.207527,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "恭喜你，{nickname}，我的眼光没错，你是一位潜力十足的狩月人。",
          DialogueId = 51006701,
          GUID = "7FB09EE2",
          LookAt = {
            [1] = "100001:n(700146)",
            [2] = "700144:n(700146)",
            [3] = "700145:n(700146)",
            [4] = "700146:n(100001)"
          },
          NextDialogue = 51006702,
          SpeakNpcId = 700146,
          Subtitle = "Congratulations, . I was right. You've proven yourself a Phoxhunter with real promise.",
          TalkActionId = {
            [1] = "700146:Agree"
          }
        },
        [51006702] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哼哼，按照之前的约定，新的小队名字，就由你来取啦！奥特赛德，你有意见吗？",
          DialogueId = 51006702,
          GUID = "7FB09F0C",
          NextDialogue = 51006703,
          Scripts = "SEQ{PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}},LookAt{_delay{2},LookAtDescription{\"700144:n(700145)\"}}}",
          SpeakNpcId = 700144,
          Subtitle = "Hmm-hmph. So, according to our agreement, you get to decide the team's name! Outsider, any problem with that?"
        },
        [51006703] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我抗议！你们一定是在针对我！",
          DialogueId = 51006703,
          GUID = "7FB09F36",
          NextDialogue = 51006704,
          SpeakNpcId = 700145,
          Subtitle = "Hell yeah! You must have set some traps for me!",
          TalkActionId = {
            [1] = "700145:Sigh_Start"
          }
        },
        [51006704] = {
          Camera = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "怎么可能，我是专业的狩月人能力记录者，不会偏袒谁，也不会针对谁。",
          DialogueId = 51006704,
          GUID = "7FB09F60",
          LookAt = {
            [1] = "700146:n(700145)"
          },
          NextDialogue = 51006705,
          SpeakNpcId = 700146,
          Subtitle = "Nonsense. As a professional at tracking Phoxhunter performance, I don't take sides or target individuals.",
          TalkActionId = {
            [1] = "700145:Sigh_End"
          },
          TurnTo = {
            [1] = "700146:n(700145)"
          }
        },
        [51006705] = {
          Camera = "64.692383,-137.981445,87.32666,0.0,0.0,87.390518,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "除非……",
          DialogueId = 51006705,
          GUID = "7FB09F8A",
          NextDialogue = 51006706,
          SpeakNpcId = 700146,
          Subtitle = "Unless...",
          TalkActionId = {
            [1] = "700146:Explain02_Start"
          }
        },
        [51006706] = {
          Camera = "11.383789,132.50415,88.602051,0.000028,2.199956,-70.207726,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "除非？",
          DialogueId = 51006706,
          GUID = "7FB09FB4",
          NextDialogue = 51006707,
          SpeakNpcId = 100001,
          Subtitle = "Unless what?",
          TalkActionId = {
            [1] = "700146:Explain02_End"
          }
        },
        [51006707] = {
          Camera = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "除非有人和这个奥特赛德一样，简直把完成挑战当成营生的手段一样！每次我新布设了一批记号，他都第一个过去挑战，再冲到我这边要报酬，坏透了！",
          DialogueId = 51006707,
          GUID = "7FB09FDE",
          NextDialogue = 51006708,
          SpeakNpcId = 700146,
          Subtitle = "Unless someone takes these challenges as a job and tries to bleed me dry like Outsider! Can you believe this man? Every time I set up a new batch of challenge markers, he's the first to finish, then hounds me for rewards — the cheek!"
        },
        [51006708] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "只要他去过一次的挑战，就没几个人再能超过他拿到报酬！搞得别人都不愿意参加了！所以我要让他尝一尝苦头！",
          DialogueId = 51006708,
          GUID = "7FB0A008",
          LookAt = {
            [1] = "700145:n(700145)"
          },
          NextDialogue = 51006709,
          SpeakNpcId = 700146,
          Subtitle = "And because no one could ever beat his records, nobody else wanted to take on my challenges anymore! That's why somebody needs to be taught a lesson!"
        },
        [51006709] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你报复我居然是因为这个？！还有你终于叫对我的名字了，之前是不是都是故意的？",
          DialogueId = 51006709,
          GUID = "7FB0A032",
          LookAt = {
            [1] = "700145:n(700146)"
          },
          NextOptions = {
            [1] = 510067091,
            [2] = 510067092,
            [3] = 510067093
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{700145},AnimationId{\"Talk03_Start\"},Duration{2}}",
          SpeakNpcId = 700145,
          Subtitle = "Is that why you've been sabotaging me!? And you finally got my name right. Have you been messing it up on purpose all this time?",
          TurnTo = {
            [1] = "700146:n(100001)"
          },
          bForbidSkipOptions = true
        },
        [51006710] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哎呀……我又不知道你是为了收集数据什么的，还以为你就是铜币花不完，解闷呢。",
          DialogueId = 51006710,
          GUID = "7FB0A05C",
          LookAt = {
            [1] = "700145:n(700146)",
            [2] = "700146:n(700145)"
          },
          NextDialogue = 51006711,
          SpeakNpcId = 700145,
          Subtitle = "Well... I didn't realise you were collecting data. I thought you were just burning through your coin stash out of boredom.",
          TalkActionId = {
            [1] = "700145:Talk03_End"
          },
          TurnTo = {
            [1] = "700146:n(100001)"
          }
        },
        [51006711] = {
          Camera = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那这下知道了吧，以后不要再第一个冲过去挑战了。",
          DialogueId = 51006711,
          GUID = "7FB0A086",
          LookAt = {
            [1] = "700146:n(700145)"
          },
          NextDialogue = 51006717,
          SpeakNpcId = 700146,
          Subtitle = "Well, now you know. So don't come to bust my challenges next time.",
          TalkActionId = {
            [1] = "700146:Agree"
          }
        },
        [51006712] = {
          Camera = "-20.936523,-347.155518,172.543701,0.000068,-12.799808,66.407326,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊，抱歉把你牵连进来，但是你的挑战结果确实很厉害哦，这一点我可没有骗你。",
          DialogueId = 51006712,
          GUID = "7FB0A0B0",
          LookAt = {
            [1] = "700145:n(700146)",
            [2] = "700146:n(700145)"
          },
          NextDialogue = 51006713,
          SpeakNpcId = 700146,
          Subtitle = "Ah, sorry to drag you into this. But you did really well in the challenges, and I'm not lying about that.",
          TalkActionId = {
            [1] = "700145:Talk03_End",
            [2] = "700146:Confident_Start"
          },
          TurnTo = {
            [1] = "700146:n(100001)"
          }
        },
        [51006713] = {
          Camera = "263.242676,-125.993896,140.543701,0.0,0.0,-169.591751,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "确实，都快赶上我的记录了，仅次于我！",
          DialogueId = 51006713,
          GUID = "7FB0A0DA",
          NextDialogue = 51006714,
          SpeakNpcId = 700145,
          Subtitle = "Indeed. Almost beat my records. Almost!",
          TalkActionId = {
            [1] = "700146:Confident_End",
            [2] = "700145:Agree"
          }
        },
        [51006714] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我看你是被狗咬得还不够疼！",
          DialogueId = 51006714,
          GUID = "7FB0A104",
          NextDialogue = 51006717,
          SpeakNpcId = 700144,
          Subtitle = "I think you need another lesson!",
          TalkActionId = {
            [1] = "700144:Disagree"
          }
        },
        [51006715] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "就是，弱诶！",
          DialogueId = 51006715,
          GUID = "7FB0A12E",
          LookAt = {
            [1] = "700145:n(700146)",
            [2] = "700146:n(700145)"
          },
          NextDialogue = 51006716,
          SpeakNpcId = 700144,
          Subtitle = "Yeah. Slowcoach!",
          TalkActionId = {
            [1] = "700145:Talk03_End",
            [2] = "700144:Agree"
          },
          TurnTo = {
            [1] = "700146:n(100001)"
          }
        },
        [51006716] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你们……我不和你们较真！",
          DialogueId = 51006716,
          GUID = "7FB0A158",
          NextDialogue = 51006717,
          SpeakNpcId = 700145,
          Subtitle = "You... I'm not going to dignify that with a response.",
          TalkActionId = {
            [1] = "700145:Disagree"
          }
        },
        [51006717] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那，我们回到一开始的话题，既然是{nickname}赢了，那小队名字还是由{性别：他|她}起好啦。",
          DialogueId = 51006717,
          GUID = "7FB0A182",
          LookAt = {
            [1] = "700144:n(700145)",
            [2] = "700145:n(700144)"
          },
          NextDialogue = 51006718,
          SpeakNpcId = 700144,
          Subtitle = "Let's get back to the main topic. Since  won, {性别:he|she} gets to decide the team's name.",
          TalkActionId = {
            [1] = "700144:Confident_Start"
          },
          TurnTo = {
            [1] = "700144:n(700145)",
            [2] = "700145:n(700144)"
          }
        },
        [51006718] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "行吧，行吧，我没意见。",
          DialogueId = 51006718,
          GUID = "7FB0A1AC",
          NextDialogue = 51006719,
          SpeakNpcId = 700145,
          Subtitle = "Okay, fine. Go ahead. Whatever.",
          TalkActionId = {
            [1] = "700144:Confident_End",
            [2] = "700145:Agree"
          }
        },
        [51006719] = {
          Camera = "-318.093262,330.265869,317.277344,0.00005,-21.599884,-51.000023,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "不过，真的不考虑一下“食用昆虫研究队”这样让人看一眼后在半夜惊醒也会想到的如惊雷一般的好名字吗！",
          DialogueId = 51006719,
          GUID = "7FB0A1D6",
          NextDialogue = 51006720,
          SpeakNpcId = 700145,
          Subtitle = "But are you sure you don't want an impressive name like \"Edible Insects Researcher Squad\"? Just hearing it will jolt you awake at night, you know!",
          TalkActionId = {
            [1] = "700145:Think_Start",
            [2] = "100001:Sigh_Start"
          }
        },
        [51006720] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我不觉得！我还是觉得什么“光之魔王见习小队“这样的名字更能吸引人！",
          DialogueId = 51006720,
          GUID = "7FB0A200",
          NextDialogue = 51006721,
          SpeakNpcId = 700144,
          Subtitle = "No, thanks! I'd say something like \"Squires of the Demon King of Light\" has more allure.",
          TalkActionId = {
            [1] = "700144:Disagree"
          }
        },
        [51006721] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那……“光之魔王的食用昆虫研究见习小队”？",
          DialogueId = 51006721,
          GUID = "7FB0A22A",
          NextDialogue = 51006722,
          SpeakNpcId = 700145,
          Subtitle = "Then... how about \"Intern Researchers on Edible Insects of the Demon King of Light\"?",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          }
        },
        [51006722] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "唔……昆虫还是很显眼，那“真·纯白地狱之极光大魔王的昆虫研究见习小队”？",
          DialogueId = 51006722,
          GUID = "7FB0A254",
          NextDialogue = 51006723,
          SpeakNpcId = 700144,
          Subtitle = "Hmph... we should make the word \"insect\" less conspicuous. What about \"Intern Researchers on Yummy Bugs of the Demon King of Ultralight from the Pure White Infernal\"?",
          TalkActionId = {
            [1] = "700144:Talk03_Start",
            [2] = "700145:Think_End"
          }
        },
        [51006723] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "魔王的部分太多了！依我看不如“伪·纯白地狱之极光大魔王的六足有翅小动物的九十九种美味烹饪法研究见习小队”？",
          DialogueId = 51006723,
          GUID = "7FB0A27E",
          NextDialogue = 51006724,
          SpeakNpcId = 700145,
          Subtitle = "We're focusing too much on the Demon King of Light part! I think we should go for \"Intern Researchers on the 99 Innovative Culinary Styles of Delicious Winged Hexapods of the Demon King of Ultralight from the Pure White Infernal\". What do you say?",
          TalkActionId = {
            [1] = "700144:Talk03_End",
            [2] = "700145:Angry01_Start"
          }
        },
        [51006724] = {
          Camera = "-20.024414,-347.564941,170.543701,0.000067,-13.199791,66.207527,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "他们俩在一起犯蠢，正好给你考虑的时间。虽然好像有很多人在给小队起名的时候会犹豫非常久，不过，我的建议是，遵从内心就好。",
          DialogueId = 51006724,
          GUID = "7FB0A2A8",
          LookAt = {
            [1] = "700146:n(100001)"
          },
          NextDialogue = 51006725,
          SpeakNpcId = 700146,
          Subtitle = "While these two knuckleheads are bickering, take your time to think. Many agonize over naming their teams, but my advice? Follow your heart.",
          TalkActionId = {
            [1] = "700144:Angry01_Start",
            [2] = "700146:Explain02_Start"
          }
        },
        [51006725] = {
          Camera = "63.574219,-21.67749,130.883057,0.0,0.0,-88.191345,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "内心吗……",
          DialogueId = 51006725,
          GUID = "7FB0A2D2",
          NextDialogue = 51006726,
          SpeakNpcId = 100001,
          Subtitle = "Follow my heart...?",
          TalkActionId = {
            [1] = "700146:Explain02_End"
          }
        },
        [51006726] = {
          Camera = "63.574219,-21.67749,130.883057,0.0,0.0,-88.191345,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "“生命是航行在无尽长夜里的孤船。”",
          DialogueId = 51006726,
          GUID = "7FB0A2FC",
          IsBlack = 1,
          NextDialogue = 51006727,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "\"Life is like a lonely cruise through the boundless darkness of the night.\""
        },
        [51006727] = {
          Camera = "63.574219,-21.67749,130.883057,0.0,0.0,-88.191345,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "“河流泪水满溢，夹岸荆棘丛生。”",
          DialogueId = 51006727,
          GUID = "7FB0A326",
          IsBlack = 1,
          NextDialogue = 51006728,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "\"The river weeps, overflowing its banks, while the thorny thickets on either side stand as a testament to its sorrow.\""
        },
        [51006728] = {
          Camera = "62.574707,-21.70874,140.883057,0.0,0.0,-88.191345,66.0,170.0,false,Manual,2.8",
          Content = "夜航……",
          DialogueId = 51006728,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB0A350",
          NextDialogue = 51006729,
          Scripts = "CameraMoveTo{_delay{1},TargetPosition{\"63.574219,-21.67749,130.883057,0.0,0.0,-88.191345,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 100001,
          Subtitle = "Cruise through the night... Nocturnal voyagers...",
          TalkActionId = {
            [1] = "700144:Angry01_End",
            [2] = "700145:Angry01_End"
          }
        },
        [51006729] = {
          Camera = "63.574219,-21.67749,130.883057,0.0,0.0,-88.191345,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "就叫夜航者吧。",
          DialogueId = 51006729,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB0A37A",
          NextDialogue = 51006730,
          SpeakNpcId = 100001,
          Subtitle = "Let's call ourselves \"The Noctoyagers.\"",
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51006730] = {
          Camera = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "夜……航？",
          DialogueId = 51006730,
          GUID = "7FB0A3A4",
          NextDialogue = 51006731,
          SpeakNpcId = 700144,
          Subtitle = "Nocto ... yagers?",
          TalkActionId = {
            [1] = "700144:Think_Start"
          }
        },
        [51006731] = {
          Camera = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯……？这么短的名字？不过，也挺不错的。",
          DialogueId = 51006731,
          GUID = "7FB0A3CE",
          NextDialogue = 51006732,
          SpeakNpcId = 700145,
          Subtitle = "Hmm... The name's a little short, but it doesn't sound bad.",
          TalkActionId = {
            [1] = "700145:Agree"
          }
        },
        [51006732] = {
          Camera = "-20.024414,-347.564941,170.543701,0.000067,-13.199791,66.207527,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "既然名字已经定下了，那就抽空回到水仙平原，告诉那位侍者吧。",
          DialogueId = 51006732,
          GUID = "7FB0A3F8",
          NextDialogue = 51006733,
          Scripts = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Confident_Start\"},Duration{2}},PlayAnimation{ActorId{700146},AnimationId{\"Confident_End\"},Duration{1}},PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}}}",
          SpeakNpcId = 700146,
          Subtitle = "Now that you have the name, head back to The Asphodel and tell the waiter there when you have the time."
        },
        [51006733] = {
          Content = "啊，对了，拿着这个。",
          DialogueId = 51006733,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_ExploreBadge_Beibao_Chapter01.T_ExploreBadge_Beibao_Chapter01'}",
          GUID = "7FB0A3F9",
          NextDialogue = 51006740,
          SpeakNpcId = 700146,
          Subtitle = "Right, take this."
        },
        [51006734] = {
          Content = "“夜航者”……嗯，好名字！要是人人都像你们一样，这块看板就不会不够写了……",
          DialogueId = 51006734,
          GUID = "7FB0A44C",
          LookAt = {
            [1] = "700143:n(0)"
          },
          NextDialogue = 51006735,
          SpeakNpcId = 700143,
          Subtitle = "\"The Noctoyagers\"... Hmm, sounds pretty good! If other teams were like you, there would be plenty of space on the board.",
          TalkActionId = {
            [1] = "700143:Explain01_Start"
          },
          TurnTo = {
            [1] = "700143:n(0)"
          }
        },
        [51006735] = {
          Content = "加油，加油，把那些又长又拗口的名字挤下去。",
          DialogueId = 51006735,
          GUID = "7FB0A476",
          SpeakNpcId = 700143,
          Subtitle = "Keep it up. Try to best those long, tongue-twisting names and get to the top.",
          TalkActionId = {
            [1] = "700143:Explain01_End"
          }
        },
        [51006736] = {
          Camera = "38.65332,-125.365479,127.959717,0.000135,-12.798094,77.399048,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "但是现在我对这片大陆的每一处角落都已经铭记于心，不再需要这些标记引路啦。",
          DialogueId = 51006736,
          GUID = "7FB0A3FC",
          NextDialogue = 51006737,
          SpeakNpcId = 700146,
          Subtitle = "I know the continent too well to need them now. ",
          TalkActionId = {
            [1] = "700146:Explain02_End"
          }
        },
        [51006737] = {
          Camera = "-156.711914,-582.082031,262.790527,0.000124,-17.197691,64.395233,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "所以，要是你在四处探险的时候，遇到这些标记，就帮我把它们带回来吧。带回来的越多，就越能证明你是优秀的狩月人，报酬当然也少不了。",
          DialogueId = 51006737,
          GUID = "7FB0A3FD",
          NextDialogue = 51006738,
          SpeakNpcId = 700146,
          Subtitle = "If you find any on your journeys, do return them to me. Consider each one proof of your skill as a Phoxhunter. Your reward will reflect your success."
        },
        [51006738] = {
          Camera = "-156.711914,-582.082031,262.790527,0.000124,-17.197691,64.395233,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "加油哦，初出茅庐的狩月人，我期待“夜航者”这三个字被写在看板顶端的那一天。",
          DialogueId = 51006738,
          GUID = "7FB0A3FE",
          NextDialogue = 51006739,
          SpeakNpcId = 700146,
          Subtitle = "I have high hopes for you. Looking forward to seeing \"Noctoyagers\" carved at the very top of the board!",
          TalkActionId = {
            [1] = "700146:Confident_Start"
          }
        },
        [51006739] = {
          Camera = "23.104004,116.666016,110.322754,0.000047,1.399806,-78.204651,28.0,100000.0,false,DoNotOverride,2.8",
          Content = "谢谢你，再见。",
          DialogueId = 51006739,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB0A422",
          SpeakNpcId = 100001,
          Subtitle = "Thank you. See you around.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51006740] = {
          Camera = "80.842773,-51.764648,173.552246,0.000151,-10.797237,-94.405273,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "这个是？",
          DialogueId = 51006740,
          GUID = "7FB0A3FA",
          NextDialogue = 51006741,
          SpeakNpcId = 100001,
          Subtitle = "What's this?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51006741] = {
          Camera = "38.65332,-125.365479,127.959717,0.000135,-12.798094,77.399048,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "觉得眼熟吗？眼熟的话就说明你还挺喜欢探险的，没见过的话也没关系！这是我特制的标记，当我外出探险的时候，会用它来标记走过的路。",
          DialogueId = 51006741,
          GUID = "7FB0A3FB",
          NextDialogue = 51006736,
          SpeakNpcId = 700146,
          Subtitle = "Looks familiar? If it does, it means you're no stranger to adventure. If not, don't concern yourself. These are my old trail markers.",
          TalkActionId = {
            [1] = "700146:Explain02_Start",
            [2] = "100001:Think_End"
          }
        },
        [51006801] = {
          Camera = "-208.101562,-322.367188,154.874023,0.000172,12.798783,96.059433,12.0,1.5,false,Disable,1.2",
          Content = "愿你的灵魂于雾海深处获得安宁……",
          DialogueId = 51006801,
          FinalCamera = "-208.101562,-322.367188,98.418945,0.000172,12.798783,96.059433,12.0,1.5,false,Disable,1.2",
          GUID = "7FB0AF4A",
          NextDialogue = 51006802,
          SpeakNpcId = 700133,
          Subtitle = "May your soul find peace in the depths of the Misty Sea...",
          TalkActionId = {
            [1] = "700133:Think_Start"
          },
          ToFinalCameraBlendTime = 8
        },
        [51006802] = {
          Camera = "-397.094727,-621.34375,166.169922,0.000161,-7.00162,55.459202,35.0,1.5,false,Disable,1.2",
          Content = "（在这片对你来说意义沉重的回忆之地，一位身披黑纱的女人静静地垂眸低语。伴随着低沉的祷告之声，女人手中的提灯散发出荧荧的幽光。）",
          DialogueId = 51006802,
          GUID = "7FB0AF74",
          LookAt = {
            [1] = "100001:n(700133)"
          },
          NextOptions = {
            [1] = 51006803,
            [2] = 51006804
          },
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"200218510060P1\"},MoveSpeed{80},Visibility{\"Show\"}}",
          Subtitle = "(In this place burdened with your poignant memories, a woman draped in black veils speaks softly, eyes downcast. Her lantern emits a soft, eerie glow as she murmurs her prayer.)"
        },
        [51006803] = {
          Content = "你在做什么？",
          DialogueId = 51006803,
          GUID = "7FB0AF9E",
          NextDialogue = 51006805,
          Subtitle = "What are you doing here?"
        },
        [51006804] = {
          Content = "你是谁？",
          DialogueId = 51006804,
          GUID = "7FB0AFC8",
          NextDialogue = 51006805,
          Subtitle = "Who are you?"
        },
        [51006805] = {
          Camera = "-89.203125,275.894531,124.682617,0.000181,-2.801388,-79.533676,35.0,1.5,false,Disable,1.2",
          Content = "你来了，孩子……请稍等，待我完成最后的仪式。",
          DialogueId = 51006805,
          GUID = "7FB0AFF2",
          LookAt = {
            [1] = "100001:n(700133)",
            [2] = "700133:p(200218510060P3)"
          },
          NextDialogue = 51006806,
          SpeakNpcId = 700133,
          Subtitle = "You have come, child... Please, wait while I complete this final rite."
        },
        [51006806] = {
          Camera = "-243.27832,141.84375,135.348633,0.000225,-4.600918,-11.145157,35.0,1.5,false,Disable,1.2",
          Content = "……愿你于母神的怀抱中重获新生。",
          DialogueId = 51006806,
          FinalCamera = "-243.27832,141.84375,129.169922,0.000225,-4.600918,-11.145157,35.0,1.5,false,Disable,1.2",
          GUID = "7FB0B01C",
          LookAt = {
            [1] = "700133:n(700133)"
          },
          NextDialogue = 51006807,
          SpeakNpcId = 700133,
          Subtitle = "…May you be reborn within the bosom of Mother Embla.",
          ToFinalCameraBlendTime = 6
        },
        [51006807] = {
          Camera = "-122.856445,-382.609375,156.415039,0.000195,-5.601042,76.061539,80.0,1.5,false,Disable,1.2",
          Content = "你好，孩子。我是一名漂泊的雾海引渡人——或者，如果你更喜欢以姓名相称，也可以称呼我为妮弗尔夫人。",
          DialogueId = 51006807,
          GUID = "7FB0B046",
          LookAt = {
            [1] = "700133:n(100001)"
          },
          NextDialogue = 51006808,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Greetings, child. I roam as the Ferrywoman of the Misty Sea — or, if you prefer a more personal touch, you may call me Lady Nifle.",
          TalkActionId = {
            [1] = "700133:Think_End"
          },
          TurnTo = {
            [1] = "700133:n(100001)"
          }
        },
        [51006808] = {
          Content = "我听见此处彷徨灵魂的絮语，因此前来指引“她”回归雾海。",
          DialogueId = 51006808,
          GUID = "7FB0B070",
          NextDialogue = 51006809,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "I heard the whispers of a wandering soul here, so I came to guide her to return to the Misty Sea.",
          TalkActionId = {
            [1] = "700133:Explain02_Start"
          }
        },
        [51006809] = {
          Content = "彷徨的灵魂？",
          DialogueId = 51006809,
          GUID = "7FB0B09A",
          NextDialogue = 51006810,
          SpeakNpcId = 100001,
          Subtitle = "A wandering soul?"
        },
        [51006810] = {
          Camera = "-63.210938,263.902344,129.163086,0.000284,-1.000821,-85.744926,50.0,1.5,false,Disable,1.2",
          Content = "是的。孩子，你是否也为一位亡者而来？",
          DialogueId = 51006810,
          GUID = "7FB0B0C4",
          NextDialogue = 51006811,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Indeed. Child, have you come here for someone who has passed?",
          TalkActionId = {
            [1] = "700133:Explain02_End"
          }
        },
        [51006811] = {
          Content = "你怎么知道？",
          DialogueId = 51006811,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB0B0EE",
          NextDialogue = 51006812,
          SpeakNpcId = 100001,
          Subtitle = "How did you know?"
        },
        [51006812] = {
          Content = "我的双眼能看到灵魂所思之物。",
          DialogueId = 51006812,
          GUID = "7FB0B118",
          NextDialogue = 51006813,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "My eyes can see the longings of souls.",
          TalkActionId = {
            [1] = "700133:Agree"
          }
        },
        [51006813] = {
          Content = "方才，在引导她归去之时，我看到了她牵念的一切，其中便有你的身影。",
          DialogueId = 51006813,
          GUID = "7FB0B142",
          NextDialogue = 51006814,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"700133:n(100001)\"}}",
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "As I guided her, I glimpsed all she held dear — and among these visions, I saw you.",
          TalkActionId = {
            [1] = "700133:Think_Start"
          }
        },
        [51006814] = {
          Camera = "-107.791016,-87.445312,208.306641,0.000234,-20.00128,-75.339943,50.0,161.900574,false,Manual,4.684293",
          Content = "……她是我的朋友。",
          DialogueId = 51006814,
          FinalCamera = "-107.791016,-87.445312,205.959961,0.000234,-20.00128,-75.339943,50.0,161.900574,false,Manual,4.684293",
          GUID = "7FB0B16C",
          NextDialogue = 51006815,
          SpeakNpcId = 100001,
          Subtitle = "...She was a friend of mine.",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "700133:Think_End"
          },
          ToFinalCameraBlendTime = 6
        },
        [51006815] = {
          Content = "我……没能保护好她。她或许是……对我感到失望。",
          DialogueId = 51006815,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB0B196",
          NextDialogue = 51006816,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Disagree\"},Duration{0.1}}",
          SpeakNpcId = 100001,
          Subtitle = "I... I failed to protect her. She must be... disappointed in me.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          }
        },
        [51006816] = {
          Camera = "-108.74707,-318.570312,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
          Content = "不，恰恰相反。我曾见过许多怀抱着强烈的遗憾与怨恨归去的灵魂，他们的恸哭悲号，如浓雾一般溢满河岸。",
          DialogueId = 51006816,
          FinalCamera = "-112.657227,-317.488281,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
          GUID = "7FB0B1C0",
          NextDialogue = 51006817,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Quite the opposite. Many souls I've witnessed depart with intense grievances and bitterness, their cries thick as the fog along the riverbanks.",
          TalkActionId = {
            [1] = "700133:Disagree"
          },
          ToFinalCameraBlendTime = 6
        },
        [51006817] = {
          Camera = "-120.291992,-125.242188,65.380859,0.000261,13.99884,64.854691,50.0,245.850052,false,Manual,11.670671",
          Content = "但是，那个灵魂的声音非常温柔。没有哀叹，也没有愤怒与不甘，而是在诉说感谢以及……祝福。",
          DialogueId = 51006817,
          GUID = "7FB0B1EA",
          NextDialogue = 51006818,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "But her voice was very gentle. It bore no sorrow, anger, nor resentment — only expressions of gratitude and... blessings.",
          TalkActionId = {
            [1] = "700133:Talk02_Start"
          }
        },
        [51006818] = {
          Camera = "-53.820312,278.359375,119.661133,0.000265,1.398256,-88.943329,80.0,202.867935,false,Manual,11.670671",
          CameraBlendCurve = "easeOutQuad",
          Content = "或许，那便是她所为你留下的。",
          DialogueId = 51006818,
          FinalCamera = "-53.820312,278.359375,119.661133,0.000265,1.398256,-88.943329,80.0,522.565857,false,Manual,11.670671",
          GUID = "7FB0B214",
          NextDialogue = 51006819,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Perhaps, those were meant for you.",
          TalkActionId = {
            [1] = "700133:Talk02_End"
          },
          ToFinalCameraBlendTime = 5
        },
        [51006819] = {
          Content = "可是……",
          DialogueId = 51006819,
          GUID = "7FB0B23E",
          NextOptions = {
            [1] = 51006820,
            [2] = 51006821
          },
          SpeakNpcId = 100001,
          Subtitle = "But...",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51006820] = {
          Content = "我很想念她。",
          DialogueId = 51006820,
          GUID = "7FB0B268",
          NextDialogue = 51006822,
          Subtitle = "I miss her terribly."
        },
        [51006821] = {
          Content = "我不接受这样的结局。",
          DialogueId = 51006821,
          GUID = "7FB0B292",
          NextDialogue = 51006822,
          Subtitle = "I refuse to accept this ending."
        },
        [51006822] = {
          Camera = "-200.257812,-533.824219,181.400391,0.000274,-6.801939,71.257195,80.0,522.565857,false,Manual,11.670671",
          Content = "（妮弗尔夫人温柔地笑了，似是早就猜到了你想说的话。）",
          DialogueId = 51006822,
          GUID = "7FB0B2BC",
          NextDialogue = 51006823,
          Subtitle = "(Lady Nifle smiles gently, as if she had anticipated your response.)",
          TalkActionId = {
            [1] = "700133:Agree"
          }
        },
        [51006823] = {
          Camera = "-147.616211,-244.476562,75.759766,0.000265,7.39762,69.851921,80.0,318.95755,false,Manual,11.670671",
          Content = "孩子，我已经在这世上活了很久、很久，送别了无数的亡魂，也曾无数次听过这样的话语。",
          DialogueId = 51006823,
          FinalCamera = "-147.616211,-244.476562,78.396484,0.000265,7.39762,69.851921,80.0,318.95755,false,Manual,11.670671",
          GUID = "7FB0B2E6",
          NextDialogue = 51006824,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Child, I have lived long and bid farewell to countless souls, and I've heard such words time and again.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 6
        },
        [51006824] = {
          Camera = "-2590.543945,-1518.859375,933.94043,0.000426,-19.601589,29.648626,18.0,318.95755,false,Disable,11.670671",
          Content = "草木会因一场山火而化作焦土，虫豸会因一阵狂风而溺于深水……无常本就是生命的一部分。或早或晚，死亡终将来临。",
          DialogueId = 51006824,
          FinalCamera = "-2618.442383,-1534.75,945.375,0.000426,-19.601589,29.648626,18.0,318.95755,false,Disable,11.670671",
          GUID = "7FB0B310",
          LookAt = {
            [1] = "700133:p(200218510060P2)"
          },
          NextDialogue = 51006825,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Just as plants succumb to wildfires and bugs perish in storms... Impermanence is a part of life. Sooner or later, death touches us all.",
          ToFinalCameraBlendTime = 10
        },
        [51006825] = {
          Camera = "-100.15625,166.824219,62.766602,0.000582,37.387058,-69.136719,18.0,318.95755,false,Disable,11.670671",
          Content = "除了诅咒命运的冷漠与残酷，或是哀叹自我的无力与渺小，我们还可以选择……珍惜切实拥有的回忆。",
          DialogueId = 51006825,
          FinalCamera = "-100.15625,166.824219,58.511719,0.000582,37.387058,-69.136719,18.0,318.95755,false,Disable,11.670671",
          GUID = "7FB0B33A",
          NextDialogue = 51006826,
          Scripts = "CameraMoveTo{_delay{3.1},TargetPosition{\"-116.790039,-32.921875,80.651367,0.000596,20.386126,46.463051,50.0,318.95755,false,Disable,11.670671\"},duration{0}}",
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Rather than cursing fate's indifference and cruelty, or lamenting our frailty, we can choose to... cherish the memories we hold dear.",
          ToFinalCameraBlendTime = 3
        },
        [51006826] = {
          Camera = "-112.657227,-317.488281,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
          Content = "毕竟，如果说死亡是“必然”，那么活着的每一日，不正是与它擦肩而过的“奇迹”吗？",
          DialogueId = 51006826,
          FinalCamera = "-108.74707,-318.570312,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
          GUID = "7FB0B364",
          LookAt = {
            [1] = "700133:n(100001)"
          },
          NextDialogue = 51006827,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "After all, if death is the inevitable, then every moment alive is a miracle that defies the odds, isn't it?",
          ToFinalCameraBlendTime = 6
        },
        [51006827] = {
          Camera = "-108.535156,-156.035156,123.041016,0.000277,-1.200986,70.850563,50.0,262.367676,false,Manual,11.670671",
          Content = "我想，去往了雾海的那个灵魂，也一定会希望……当你回忆起与她共同经历的时日，你是面带笑意的，而非哀怜和悲泣。",
          DialogueId = 51006827,
          GUID = "7FB0B38E",
          NextOptions = {
            [1] = 51006828
          },
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "I believe that the gentle soul who journeyed to the Misty Sea would also wish that... when you recall your time together, you'd find yourself smiling, not crying with grief.",
          TalkActionId = {
            [1] = "700133:Give"
          }
        },
        [51006828] = {
          Content = "“雾海”到底是什么地方？",
          DialogueId = 51006828,
          GUID = "7FB0B3B8",
          NextDialogue = 51006829,
          Subtitle = "What's the Misty Sea like?"
        },
        [51006829] = {
          Camera = "-95.244141,-1.792969,77.727539,0.000237,25.99535,65.250359,18.0,262.367676,false,Disable,11.670671",
          Content = "雾海……是卡戎之民的生命之源，亦是安眠之地。亡者的灵魂回归雾海，生者的灵魂从中诞生。生命如此循环流转，生生不息。",
          DialogueId = 51006829,
          FinalCamera = "-100.587891,0.652344,77.727539,0.000236,25.99535,65.250565,18.0,262.367676,false,Disable,11.670671",
          GUID = "7FB0B3E2",
          NextDialogue = 51006830,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "The Misty Sea... is the cradle and resting place of life for the people of Charon. Souls of the deceased return there, and the living emerge from it, life flowing in endless cycles.",
          ToFinalCameraBlendTime = 6
        },
        [51006830] = {
          Camera = "-111.96875,-162.601562,135.374023,0.000258,6.394546,-70.962959,27.0,262.367676,false,Disable,11.670671",
          Content = "如果是那样……",
          DialogueId = 51006830,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB0B40C",
          NextDialogue = 51006831,
          NextOptions = {
            [1] = 51006831,
            [2] = 51006832
          },
          SpeakNpcId = 100001,
          Subtitle = "If that's the case..."
        },
        [51006831] = {
          Content = "我能去雾海把她带回来吗？",
          DialogueId = 51006831,
          GUID = "7FB0B436",
          NextDialogue = 51006833,
          Subtitle = "Can I go to the Misty Sea and bring her back?"
        },
        [51006832] = {
          Content = "她还会回到我身边吗？",
          DialogueId = 51006832,
          GUID = "7FB0B460",
          NextDialogue = 51006833,
          Subtitle = "Will she ever return to me?"
        },
        [51006833] = {
          Camera = "-792.569336,-40.027344,85.155273,0.000242,-0.205042,-2.348938,18.000004,262.367676,false,Disable,11.670671",
          Content = "（妮弗尔夫人没有立刻回答。她抬起那双满含温柔与悲悯的眼眸，静静地看着你，半晌之后才再度开口——）",
          DialogueId = 51006833,
          FinalCamera = "-809.700195,-39.3125,85.211914,0.000242,-0.205042,-2.348938,18.000004,262.367676,false,Disable,11.670671",
          GUID = "7FB0B48A",
          NextDialogue = 51006834,
          Subtitle = "(Lady Nifle does not answer immediately. She raises her tender, compassionate eyes, and after a long pause, speaks again—)",
          ToFinalCameraBlendTime = 6
        },
        [51006834] = {
          Camera = "-134.571289,-64.273438,162.016602,0.000233,-12.205288,51.838001,50.0,262.367676,false,Disable,11.670671",
          Content = "如果向我提问的是别人，我应当会如此回答：生与死的循环是不容违背的世界法则，凭人类的力量绝对无法与之抗衡。",
          DialogueId = 51006834,
          FinalCamera = "-136.608398,-62.683594,162.016602,0.000234,-12.205288,51.838234,50.0,262.367676,false,Disable,11.670671",
          GUID = "7FB0B4B4",
          NextDialogue = 51006835,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Were it someone else asking, my answer would be thus: The cycle of life and death is a universal law, not to be defied by human might.",
          TalkActionId = {
            [1] = "700133:Disagree"
          },
          ToFinalCameraBlendTime = 6
        },
        [51006835] = {
          Camera = "-57.59375,207.816406,103.970703,0.000219,3.798521,-89.331329,80.0,445.659943,false,Manual,22.0",
          Content = "不过，孩子，我能感受得到……你背负着不同寻常的命运。",
          DialogueId = 51006835,
          GUID = "7FB0B4DE",
          NextDialogue = 51006836,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "However, child, I sense... you are bound by an unusual destiny."
        },
        [51006836] = {
          Camera = "-128.890625,-402.097656,132.947266,0.000231,-1.40176,75.0606,80.0,445.659943,false,Manual,22.0",
          Content = "有朝一日，当你获得了足够强大的力量——当你能够直面世界的真相，甚至打破构筑它的法则本身……或许，通向雾海之河亦会为你倒流。",
          DialogueId = 51006836,
          FinalCamera = "-125.893555,-402.882812,132.947266,0.000233,-1.40176,75.060074,80.0,445.659943,false,Manual,22.0",
          GUID = "7FB0B508",
          LookAt = {
            [1] = "700133:p(200218510060P2)"
          },
          NextOptions = {
            [1] = 51006837
          },
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "One day, when you have garnered enough strength to confront this world's truths and perhaps even challenge its very laws... then, perhaps the river to the Misty Sea might flow backwards for you.",
          ToFinalCameraBlendTime = 6
        },
        [51006837] = {
          Content = "你的意思是……？！",
          DialogueId = 51006837,
          GUID = "7FB0B532",
          NextDialogue = 51006838,
          Subtitle = "You mean...!?"
        },
        [51006838] = {
          Camera = "-239.978516,-66.265625,99.682617,0.000237,6.198123,33.460938,80.000008,264.973846,false,Manual,22.0",
          Content = "呵呵……我不过是驻于河畔的一介旁观者。这个问题的答案，只能由你自己寻得。",
          DialogueId = 51006838,
          GUID = "7FB0B55C",
          LookAt = {
            [1] = "700133:n(100001)"
          },
          NextDialogue = 51006839,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Hehe... I am merely an observer by the riverbank. The answer to this question must be discovered by yourself."
        },
        [51006839] = {
          Camera = "-142.427734,-464.648438,180.995117,0.000256,-7.402442,75.056717,80.000008,411.46283,false,Disable,22.0",
          Content = "如果你真的心怀渴望，那么，就请继续前进吧。",
          DialogueId = 51006839,
          GUID = "7FB0B586",
          NextDialogue = 51006840,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "If your heart truly yearns for it, then proceed on your path.",
          TalkActionId = {
            [1] = "700133:Agree"
          }
        },
        [51006840] = {
          Content = "一路顺风，亲爱的孩子。",
          DialogueId = 51006840,
          GUID = "7FB0B5B0",
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Godspeed, dear child.",
          TalkActionId = {
            [1] = "700133:Give"
          }
        },
        [51006841] = {
          Content = "孩子，纵是前路无常，也请你坚定地走下去吧。",
          DialogueId = 51006841,
          GUID = "7FB0B5DA",
          NextDialogue = 51006842,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Child, even though the path ahead is uncertain, always proceed with determination."
        },
        [51006842] = {
          Content = "愿母神茵布拉赐福于你。",
          DialogueId = 51006842,
          GUID = "7FB0B604",
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "May Mother Embla bless you."
        },
        [51006901] = {
          Camera = "475.811523,676.893555,129.602295,0.000004,0.0,-119.200165,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（列车售票亭吸引了你的注意：你回忆起从玛尔洁那里得到的“货物”，它们中的某一个似乎与“车票”有关。）",
          DialogueId = 51006901,
          FinalCamera = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB0BFB2",
          LookAt = {
            [1] = "700147:n(700148)",
            [2] = "700148:n(700147)"
          },
          NextDialogue = 51006902,
          Subtitle = "(The train ticket booth catches your eye, reminding you of an item you got from Margie — an item related to \"tickets.\")",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51006902] = {
          Camera = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（你来得不凑巧，一个异国打扮的卡戎之民与售票员起了冲突。）",
          DialogueId = 51006902,
          GUID = "7FB0BFDC",
          NextDialogue = 51006903,
          Subtitle = "(You've come at a bad time — a foreign-looking Charon is in a heated argument with the ticket seller.)",
          TalkActionId = {
            [1] = "700147:Confident_Start",
            [2] = "100001:Think_End"
          }
        },
        [51006903] = {
          Camera = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "没钱就滚开！",
          DialogueId = 51006903,
          GUID = "7FB0C006",
          NextDialogue = 51006904,
          SpeakNpcId = 700147,
          Subtitle = "Get lost if you have no money!"
        },
        [51006904] = {
          Camera = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "天呐，我只想一问！你为何狂躁！",
          DialogueId = 51006904,
          GUID = "7FB0C030",
          NextDialogue = 51006905,
          SpeakNpcId = 700148,
          Subtitle = "Goodness, I just asked a simple question! Why so angry!?",
          TalkActionId = {
            [1] = "700147:Confident_End",
            [2] = "700148:Shock_Start"
          }
        },
        [51006905] = {
          Camera = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哦好的，这位怪腔怪调的穷鬼先生，在我礼貌地告诉你票价后，你打算怎么做？搓搓自己漏不出一个子儿的破口袋对我颐指气使？",
          DialogueId = 51006905,
          GUID = "7FB0C05A",
          NextDialogue = 51006906,
          SpeakNpcId = 700147,
          Subtitle = "Alright, Mr Quirky Accent — after I've politely told you the fare, what's your plan? To fumble through those empty pockets and then boss me around?",
          TalkActionId = {
            [1] = "700147:Talk03_Start",
            [2] = "700148:Shock_End"
          }
        },
        [51006906] = {
          Camera = "33.833008,-38.410156,159.227783,0.00001,0.999987,101.202133,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你在讲什么？你怎知我没——",
          DialogueId = 51006906,
          GUID = "7FB0C084",
          NextDialogue = 51006907,
          SpeakNpcId = 700148,
          Subtitle = "What you say? How you know me no—",
          TalkActionId = {
            [1] = "700148:Explain01_Start",
            [2] = "700147:Talk03_End"
          }
        },
        [51006907] = {
          Camera = "8.34668,69.227539,155.484863,0.000015,-7.799837,-93.597458,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "知道什么？卡戎人兜里能有几个铜币？这里只属于富豪、贵族和高官，不欢迎穷光蛋！",
          DialogueId = 51006907,
          GUID = "7FB0C0AE",
          NextDialogue = 51006908,
          SpeakNpcId = 700147,
          Subtitle = "What's there to know? Like a Charon would have more than five coins in their pocket! This place is reserved for the rich and the powerful — not penniless wanderers like you!",
          TalkActionId = {
            [1] = "700148:Explain01_End",
            [2] = "700147:Confident_Start"
          }
        },
        [51006908] = {
          Camera = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（异国人哆嗦着嘴唇，改换某种方言加以反击，然而什么也没听懂的售票员轻蔑地看了他一眼，不再理他，商人自讨没趣，悻悻离去。）",
          DialogueId = 51006908,
          GUID = "7FB0C0D8",
          Scripts = "PARA{MoveTo{_delay{2},ActorId{700148},MoveSpeed{75},TargetPoint{\"QuestPoint_20021901Move\"}},CameraMoveTo{_delay{2},TargetPosition{\"479.638672,673.591797,127.602295,0.000004,-0.600005,-125.400406,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
          Subtitle = "(The foreigner fumbles a retort in his mother tongue, but the ticket seller, not understanding a word, merely gives him a scornful glance before turning away. The man leaves, crestfallen.)"
        },
        [51006921] = {
          Content = "看你白白净净的，怎么也跟兄弟抢垃圾啊？",
          DialogueId = 51006921,
          GUID = "7FB0C0D9",
          NextOptions = {
            [1] = 51006922,
            [2] = 51006923
          },
          SpeakNpcId = 700230,
          Subtitle = "Well, well — look at you. Clean skin, tidy coat. What're you doing digging through trash with the likes of us?"
        },
        [51006922] = {
          Content = "我还没动手呢！",
          DialogueId = 51006922,
          GUID = "7FB0C0DA",
          NextDialogue = 51006924,
          Subtitle = "I haven't even touched anything!"
        },
        [51006923] = {
          Content = "我才没有翻垃圾桶的癖好。",
          DialogueId = 51006923,
          GUID = "7FB0C0DB",
          NextDialogue = 51006924,
          Subtitle = "Bin diving's not really my thing, thanks."
        },
        [51006924] = {
          Content = "你这小孩少充楞，我都看到了。",
          DialogueId = 51006924,
          GUID = "7FB0C0DC",
          NextDialogue = 51006925,
          SpeakNpcId = 700230,
          Subtitle = "Don't play dumb, kid."
        },
        [51006925] = {
          Content = "昨天有个穿制服的女的，一边哭，一边把这盒子丢了进去。有个拾荒的老太太好心问她怎么了，结果愣是被那凶女人劈头盖脸骂了一顿，让少管闲事。",
          DialogueId = 51006925,
          GUID = "7FB0C0DD",
          NextDialogue = 51006926,
          SpeakNpcId = 700230,
          Subtitle = "Yesterday, some woman in uniform came by — sobbing her eyes out. She chucked a box right into the bin. Some nice old lady picking through scraps tried to ask if she was okay... got yelled at, real nasty. Told her to shove off and mind her own business."
        },
        [51006926] = {
          Content = "喏，就是你手上那个盒子。还说你不是从垃圾桶捡的？",
          DialogueId = 51006926,
          GUID = "7FB0C0DE",
          NextDialogue = 51006927,
          SpeakNpcId = 700230,
          Subtitle = "And that box you're holding? Yeah, that one. So... still wanna say you didn't dig through the bin?"
        },
        [51006927] = {
          Content = "不是我……算了懒得解释了，总之谢谢你告诉我失主的信息。",
          DialogueId = 51006927,
          GUID = "7FB0C0DF",
          NextDialogue = 51006928,
          SpeakNpcId = 100001,
          Subtitle = "It wasn't— ...you know what, forget it. Thanks for the info anyway."
        },
        [51006928] = {
          Content = "（穿制服的凶女人……会和玛尔洁的“哪件货物”有关呢？）",
          DialogueId = 51006928,
          GUID = "7FB0C0E0",
          SpeakNpcId = 100001,
          Subtitle = "(A woman in uniform... Could she have something to do with one of the items Margie gave me?)"
        },
        [51006931] = {
          Content = "成为售票员的第一年零八个月，我终于攒够了可以从冰湖城坐到南方丹流城的车票钱。",
          DialogueId = 51006931,
          GUID = "7FB0C49E",
          NextDialogue = 51006932,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "One year and eight months into the job, I finally saved enough for a single fare to Scarletriver — one of the big southern cities."
        },
        [51006932] = {
          Content = "这不是很好吗？你在一步步接近梦想。",
          DialogueId = 51006932,
          GUID = "7FB0C4C8",
          NextDialogue = 51006933,
          SpeakNpcId = 100001,
          Subtitle = "Isn't that exciting? You're getting closer to your dream."
        },
        [51006933] = {
          Content = "接近？你忘了<H>卡戎监护金</>了吗？票本身的价格连买票要交的监护金零头都不到！要想买去他那边的票，我要不吃不喝五年！可我还有家要养……",
          DialogueId = 51006933,
          GUID = "7FB0C4F2",
          NextDialogue = 51007147,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
