        },
        [51007914] = {
          Content = "嗨呀没关系的，第一次玩总会有点紧张，但这不有我在嘛！我等你平复下心情，准备好了再找我就行。",
          DialogueId = 51007914,
          GUID = "7FB165E4",
          SpeakNpcId = 700191,
          Subtitle = "Ah, no worries! Totally normal to feel a bit jittery your first time. Take your time — when you're ready, come find me!"
        },
        [51007915] = {
          Content = "好吧好吧，那我就来给你示范一下怎么玩，你之后也帮我去雾区跟大伙宣传宣传我这项目哈。",
          DialogueId = 51007915,
          GUID = "7FB1660E",
          NextDialogue = 51007916,
          SpeakNpcId = 700191,
          Subtitle = "Alright, alright. I'll show you — but you gotta promise to spread the word for me when you get back to Mist Aken, yeah?"
        },
        [51007916] = {
          Content = "（达顿说完便钻进了管道，待金属被挤压的咯吱咯吱声完全停息，你听到达顿拍了拍管道的内壁对你说。）",
          DialogueId = 51007916,
          GUID = "7FB16638",
          NextDialogue = 51007917,
          Subtitle = "(With that, Dutton squeezes himself into the pipe. The metal groans and creaks under his weight. Once he's wedged in, he gives the pipe a good smack and shouts back to you.)"
        },
        [51007917] = {
          Content = "哎呦你没先体验真是可惜了，我这管子里不仅擦得干净，还很香哩。行了，滑梯出口就在前面，我先滑过去了哈，回见！",
          DialogueId = 51007917,
          GUID = "7FB16662",
          SpeakNpcId = 700191,
          Subtitle = "Tell you what — you're gonna regret not going first! It's spotless in here, and smells nice! Alright, the exit's just up ahead — I'm off! See you at the bottom!"
        },
        [51007918] = {
          Content = "（咯吱作响的管道将附近的秽兽吸引了过来，待你清理完这些小麻烦后，达顿的声音从身旁的管道传来。）",
          DialogueId = 51007918,
          GUID = "7FB1668C",
          IsBlack = 1,
          NextDialogue = 51007919,
          Subtitle = "(The creaking and groaning of the pipes have drawn the attention of nearby Filthoids. After clearing out the pests, you hear Dutton's voice echoing from the pipe next to you.)"
        },
        [51007919] = {
          Content = "太——好——玩——啦——我——们——终——点——见——",
          DialogueId = 51007919,
          GUID = "7FB166B6",
          SpeakNpcId = 700191,
          Subtitle = "It's—so—much—fun—! See—you—at—the—finish—line—!"
        },
        [51007920] = {
          Content = "（终点除了一滩水什么也没有。趴在管道上仔细聆听，你能听到咯吱声还在不断地从终点前方传来。你知道，达顿滑过头了。）",
          DialogueId = 51007920,
          GUID = "7FB166E0",
          Subtitle = "(The \"finish line\" turns out to be little more than a puddle of murky water. Pressing your ear to the pipe, you can still make out the faint metallic groaning, fading into the distance. It's clear Dutton has completely overshot the exit.)"
        },
        [51007921] = {
          Content = "（一只又一只的秽兽被喷出了管道，拦住了你的去路。）",
          DialogueId = 51007921,
          GUID = "7FB1670A",
          IsBlack = 1,
          Subtitle = "(Filthoids come spitting out of the pipe one after another, piling up and blocking your path.)"
        },
        [51007922] = {
          Camera = "-143.335342,-546.682495,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
          Content = "唔——呃——呕——",
          DialogueId = 51007922,
          FinalCamera = "-60.066826,-542.436035,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
          GUID = "7FB16734",
          NextDialogue = 51007923,
          SpeakNpcId = 700191,
          Subtitle = "Urgh—guh—bleegh—!",
          TalkActionId = {
            [1] = "700191:Hurt01"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100001:n(700191)"
          }
        },
        [51007923] = {
          Content = "（从错误出口喷出来的达顿面色苍白，趴在地上狂吐不止，显然“滑梯”颇为颠簸——这个“下水道滑梯”并没有他所说的那么安全有趣。）",
          DialogueId = 51007923,
          GUID = "7FB1675E",
          NextOptions = {
            [1] = 51007924,
            [2] = 51007925
          },
          Subtitle = "(Pale and crumpled on the ground, Dutton is heaving and retching uncontrollably. Clearly, the \"sewer slide\" wasn't quite as safe — or fun — as he'd made it out to be.)"
        },
        [51007924] = {
          Content = "你没事吧？",
          DialogueId = 51007924,
          GUID = "7FB16788",
          ImprPlusId = 1002,
          NextDialogue = 51007926,
          Subtitle = "You okay?"
        },
        [51007925] = {
          Content = "我没看清，你能再滑一次吗？",
          DialogueId = 51007925,
          GUID = "7FB167B2",
          ImprPlusId = 1005,
          NextDialogue = 51007926,
          Subtitle = "I didn't quite catch how you finish the ride — mind showing me again?"
        },
        [51007926] = {
          Camera = "-310.433411,-170.472031,157.965942,0.000161,-12.197788,12.9158,15.353726,100000.0,false,Manual,22.0",
          Content = "呼……呼……",
          DialogueId = 51007926,
          GUID = "7FB167DC",
          NextDialogue = 51007927,
          SpeakNpcId = 700191,
          Subtitle = "Huff... Huff..."
        },
        [51007927] = {
          Content = "不行了，我得，休息一下……答应你的奖励，给……我先走了……",
          DialogueId = 51007927,
          GUID = "7FB16806",
          NextDialogue = 51007928,
          SpeakNpcId = 700191,
          Subtitle = "Can't... need... a minute... Here's your reward... I'm outta here...",
          TalkActionId = {
            [1] = "700191:Sigh_Start"
          }
        },
        [51007928] = {
          Camera = "-125.646004,-486.612549,465.015015,-0.001072,-47.41058,90.325813,15.353726,100000.0,false,Manual,22.0",
          Content = "唉……到底怎么才能搞出便宜好玩，雾区人也能玩得起的游乐设施呢……",
          DialogueId = 51007928,
          GUID = "7FB16830",
          NextDialogue = 51007929,
          SpeakNpcId = 700191,
          Subtitle = "*sigh*... There's gotta be a way to make cheap, fun rides for Mist Aken folks... There's gotta be..."
        },
        [51007929] = {
          Content = "（达顿递给你一个小包裹，然后捂着胸口头也不回地离开了下水道——显然，他不会再回到这个令他伤心的地方了。）",
          DialogueId = 51007929,
          GUID = "7FB1685A",
          IsBlack = 1,
          Subtitle = "(Dutton hands you a small bundle, then staggers off clutching his chest — without so much as a backward glance at the place that just crushed his dreams.)"
        },
        [51007930] = {
          Content = "雾区什么娱乐项目都没有，肯定还有潜在的商机，让我再好好想想……",
          DialogueId = 51007930,
          GUID = "7FB16884",
          SpeakNpcId = 700191,
          Subtitle = "Mist Aken's got no entertainment at all... There's gotta be an untapped market hiding somewhere. I'll figure something out... sooner or later..."
        },
        [51008001] = {
          Content = "走，走开……不买月石的话就赶紧走……别把那群当兵的引来了……",
          DialogueId = 51008001,
          GUID = "7FB1742A",
          NextDialogue = 51008002,
          SpeakNpcId = 700113,
          Subtitle = "S—Scoot if you ain't buying any Phoxene... Stop drawing the soldiers' attention to me..."
        },
        [51008002] = {
          Content = "（男人瑟缩在角落，与他健硕的体格所给人的印象相去甚远。他的眼神躲闪，渴望将身旁的月石脱手，却迟疑着要不要向他人寻求帮助。）",
          DialogueId = 51008002,
          GUID = "7FB17454",
          NextOptions = {
            [1] = 51008003,
            [2] = 51008004,
            [3] = 51008005,
            [4] = 51008007
          },
          Subtitle = "(Despite his strong, powerful build, the man cowers in the corner. His shifty gaze and the bag of Phoxene by his side suggest he's desperate to rid himself of it but hesitant to ask for help.)"
        },
        [51008003] = {
          Content = "我虽然不买，但分我一半报酬的话，可以帮你找找买家。",
          DialogueId = 51008003,
          GUID = "7FB1747E",
          ImprPlusId = 1001,
          NextDialogue = 51008009,
          Subtitle = "I'm not buying, but I can find you a buyer if we split it fifty-fifty."
        },
        [51008004] = {
          Content = "你需要什么帮助吗？",
          DialogueId = 51008004,
          GUID = "7FB174A8",
          ImprPlusId = 1004,
          NextDialogue = 51008009,
          Subtitle = "Do you need help?"
        },
        [51008005] = {
          Content = "帝国肯定不会允许你干这种事，不想惹麻烦的话就快走吧。",
          DialogueId = 51008005,
          GUID = "7FB174D2",
          ImprPlusId = 1002,
          NextDialogue = 51008006,
          Subtitle = "This is illegal in the Empire. You should leave if you don't want any trouble."
        },
        [51008006] = {
          Content = "您高抬贵手，把我当个屁放了吧，我只要把这批月石卖掉就立马离开冰湖城，绝不回来。",
          DialogueId = 51008006,
          GUID = "7FB174FC",
          NextDialogue = 51008009,
          SpeakNpcId = 700113,
          Subtitle = "Show some mercy and look the other way, please. Once I sell this load of Phoxene I'll leave Icelake at once and never ever come back."
        },
        [51008007] = {
          Content = "咳！军团的士兵委托我盘查你，赶紧把通行证拿出来！",
          DialogueId = 51008007,
          GUID = "7FB17526",
          ImprPlusId = 1005,
          NextDialogue = 51008008,
          Subtitle = "Ahem! The Legion commissioned me to search the likes of you. Show me your travel permit!"
        },
        [51008008] = {
          Content = "（男人听罢提起袋子就要跑，好不容易向他说明玩笑并解释身份后，他才悄声说明了自己的难处。）",
          DialogueId = 51008008,
          GUID = "7FB17550",
          NextDialogue = 51008009,
          SpeakNpcId = 700113,
          Subtitle = "(The man grabs his bag and bolts. After a breathless chase, you manage to tell him who you really are and convince him you were joking. In a hushed voice, he reveals his dire circumstances.)"
        },
        [51008009] = {
          Content = "只要你帮我找个买家，报酬分你七成，不，八成！拜托了，拜托！",
          DialogueId = 51008009,
          GUID = "7FB1757A",
          SpeakNpcId = 700113,
          Subtitle = "Find me a buyer and I'll let you take 70 percents! No, 80! Please! I really need the help!"
        },
        [51008010] = {
          Content = "（虽说答应了男人的委托，但他的神色和袋子上干涸的暗红色痕迹都宣告着这批月石的来路并不单纯。）",
          DialogueId = 51008010,
          GUID = "7FB175A4",
          NextDialogue = 51008011,
          Subtitle = "(You've agreed to the man's request. But the way his eyes dart about — and the dried streaks of crimson on the sack he's hauling — hint that there's more to this Phoxene than he's letting on.)"
        },
        [51008011] = {
          Content = "（贸然寻找买主也许会招来麻烦，也许，先确认一下这批月石的来历会更好？）",
          DialogueId = 51008011,
          GUID = "7FB175CE",
          Subtitle = "(Might be wiser to hold off finding a buyer for now and figure out where exactly this haul came from.)"
        },
        [51008012] = {
          Content = "（这片草丛刚刚是不是有什么东西闪了一下？）",
          DialogueId = 51008012,
          GUID = "7FB175F8",
          NextOptions = {
            [1] = 51008053
          },
          Subtitle = "(Wait... was that a glint of light just now, flickering through the grass?)"
        },
        [51008013] = {
          Content = "（你翻了翻草丛，什么都没找到。也许刚才只是眼花了吧。）",
          DialogueId = 51008013,
          GUID = "7FB17622",
          Subtitle = "(You part the grass, but there's nothing there. Must've been a trick of the light.)"
        },
        [51008014] = {
          Content = "（你翻了翻草丛，果然找到了一颗散发着微弱光亮的石头——月石。只是，月石上同样沾着暗红色的血迹，和男人袋子上的暗红痕迹一模一样。）",
          DialogueId = 51008014,
          GUID = "7FB1764C",
          NextDialogue = 51008015,
          Subtitle = "(You part the grass — and there it is: a shard of Phoxene, faintly aglow, streaked with the same dried red as the sack Larry was carrying.)"
        },
        [51008015] = {
          Content = "我可不觉得今天是什么运气好到足够随地捡月石的日子。更何况这种带着一抹血迹的月石可不常见……",
          DialogueId = 51008015,
          GUID = "7FB17676",
          NextDialogue = 51008016,
          SpeakNpcId = 100001,
          Subtitle = "Doesn't seem like the kind of day where Phoxene just drops into my lap... especially not bloodstained ones. Yeah — something's definitely off."
        },
        [51008016] = {
          Content = "吼——",
          DialogueId = 51008016,
          GUID = "7FB176A0",
          NextDialogue = 51008017,
          Subtitle = "Roaaaar—!"
        },
        [51008017] = {
          Content = "先清理掉碍事的秽兽吧……",
          DialogueId = 51008017,
          GUID = "7FB176CA",
          SpeakNpcId = 100001,
          Subtitle = "Better deal with these Filthoids first..."
        },
        [51008018] = {
          Content = "（一片凌乱的残渣碎屑，是冰湖的碎石、折断的树枝、些许瓦砾碎片。看这个凌乱程度，这里想必经历过一场打斗。）",
          DialogueId = 51008018,
          GUID = "7FB176F4",
          NextDialogue = 51008019,
          Subtitle = "(Scattered debris litters the ground — pebbles from the lake, snapped branches, and splinters of masonry. Judging by the mess, a fight broke out here.)"
        },
        [51008019] = {
          Content = "（残渣中夹杂着撕下来的劣质布料和棉絮，这些布料似乎和那个寻找买主的男人身上穿的衣物类似。）",
          DialogueId = 51008019,
          GUID = "7FB1771E",
          Subtitle = "(Among the rubble, you spot scraps of torn fabric and tufts of stuffing... the same kind as on that man's threadbare clothes.)"
        },
        [51008020] = {
          Content = "（翻开那些碎屑，你又发现了一小块染血的月石。）",
          DialogueId = 51008020,
          GUID = "7FB17748",
          Subtitle = "(Sifting through the wreckage, you uncover another small Phoxene shard — stained dark with blood.)"
        },
        [51008021] = {
          Content = "（周围的脚印杂乱无章，但却并没有秽兽或野兽的蹄印，只有人类的脚印。）",
          DialogueId = 51008021,
          GUID = "7FB17772",
          Subtitle = "(The footprints are a tangled mess, crisscrossing wildly through the dirt — but there's something telling. No claw marks. No beast tracks. Just human prints.)"
        },
        [51008022] = {
          Content = "（一道重物被拖行的痕迹绵延至远处。）",
          DialogueId = 51008022,
          GUID = "7FB1779C",
          NextDialogue = 51008023,
          Subtitle = "(A long drag mark scores the earth, trailing off into the distance — as if something heavy had been hauled away.)"
        },
        [51008023] = {
          Content = "嗯……我想，我大概能猜到这里发生过什么了。月石上血迹的来源是：",
          DialogueId = 51008023,
          GUID = "7FB177C6",
          NextOptions = {
            [1] = 51008024,
            [2] = 51008026,
            [3] = 51008028
          },
          SpeakNpcId = 100001,
          Subtitle = "Hm... it's coming together now. The blood on that Phoxene — it came from:"
        },
        [51008024] = {
          Content = "人类",
          DialogueId = 51008024,
          GUID = "7FB177F0",
          NextDialogue = 51008025,
          Subtitle = "Humans"
        },
        [51008025] = {
          Content = "（是的，这里并没有秽兽和野兽来过。）",
          DialogueId = 51008025,
          GUID = "7FB1781A",
          NextDialogue = 51008030,
          Subtitle = "(That's right. No beast tracks. No Filthoid claws. Just humans.)"
        },
        [51008026] = {
          Content = "野兽",
          DialogueId = 51008026,
          GUID = "7FB17844",
          NextDialogue = 51008027,
          Subtitle = "Beasts"
        },
        [51008027] = {
          Content = "（不对，如果有野兽来过，这里应该会留有野兽的蹄印。）",
          DialogueId = 51008027,
          GUID = "7FB1786E",
          NextDialogue = 51008030,
          Subtitle = "(No... if beasts had passed through, there'd be pawprints or claw marks.)"
        },
        [51008028] = {
          Content = "秽兽",
          DialogueId = 51008028,
          GUID = "7FB17898",
          NextDialogue = 51008029,
          Subtitle = "Filthoids"
        },
        [51008029] = {
          Content = "（不对，如果有秽兽来过，这里应该会留有秽兽的蹄印。）",
          DialogueId = 51008029,
          GUID = "7FB178C2",
          NextDialogue = 51008030,
          Subtitle = "(No... if Filthoids had been here, there'd be gouges and claw marks all over.)"
        },
        [51008030] = {
          Content = "（是有人在这里袭击了其他人，也许就是为了……抢走那一小袋月石。接下来怎么办呢……）",
          DialogueId = 51008030,
          GUID = "7FB178EC",
          SpeakNpcId = 100001,
          Subtitle = "Looks like there was a fight here... probably over that sack of Phoxene. Now then — what's my next move?",
          TalkOptions = {
            [1] = 51008031,
            [2] = 51008032
          }
        },
        [51008031] = {
          Content = "那个人的月石来路不正，不如吞下这笔不义之财。",
          DialogueId = 51008031,
          GUID = "7FB17916",
          ImprPlusId = 1005,
          Subtitle = "That Phoxene was taken in blood anyway. Why shouldn't I claim it for myself?"
        },
        [51008032] = {
          Content = "那个人做了恶事，去找卫戍部队举报他吧。",
          DialogueId = 51008032,
          GUID = "7FB17940",
          ImprPlusId = 1002,
          Subtitle = "That guy did some really bad things. Better report him to the Escort."
        },
        [51008033] = {
          Content = "你干了什么见不得人的事吧？",
          DialogueId = 51008033,
          GUID = "7FB1796A",
          NextDialogue = 51008034,
          SpeakNpcId = 100001,
          Subtitle = "You've done something you're not proud of... haven't you?"
        },
        [51008034] = {
          Content = "这枚月石你可能未必会有印象，但它一定记得你。它上面沾染的血迹的主人也永远不会忘了你的。",
          DialogueId = 51008034,
          GUID = "7FB17994",
          NextDialogue = 51008035,
          SpeakNpcId = 100001,
          Subtitle = "This little Phoxene nugget — maybe you don't remember it, but it remembers you. And so does the one whose blood is on it."
        },
        [51008035] = {
          Content = "我……我听不懂你在说什么！",
          DialogueId = 51008035,
          GUID = "7FB179BE",
          NextDialogue = 51008036,
          SpeakNpcId = 700113,
          Subtitle = "I... I don't know what you're talking about!"
        },
        [51008036] = {
          Content = "不用你帮忙了，什么月石，我听不懂！",
          DialogueId = 51008036,
          GUID = "7FB179E8",
          NextDialogue = 51008037,
          SpeakNpcId = 700113,
          Subtitle = "I don't need your help anymore — just leave me alone!"
        },
        [51008037] = {
          Content = "没必要这样，卫戍部队马上就要到了。不过，我倒是有个法子可以帮你——前提是，这袋月石归我。",
          DialogueId = 51008037,
          GUID = "7FB17A12",
          NextDialogue = 51008038,
          SpeakNpcId = 100001,
          Subtitle = "Easy. The Escort's on their way. I could make them turn around — but that'll cost you. Let's say... one sack of Phoxene."
        },
        [51008038] = {
          Content = "我……你……",
          DialogueId = 51008038,
          GUID = "7FB17A3C",
          NextDialogue = 51008039,
          SpeakNpcId = 700113,
          Subtitle = "You—! I..."
        },
        [51008039] = {
          Content = "当然，你也可以选择跟他们走，这完全是你的自由。",
          DialogueId = 51008039,
          GUID = "7FB17A66",
          NextDialogue = 51008040,
          SpeakNpcId = 100001,
          Subtitle = "Up to you. Stay and greet them if you want."
        },
        [51008040] = {
          Content = "我可以在这里等你做选择， 但卫戍部队大概不会等你。在你犹豫这会儿的时间里，他们大概就要到喽。",
          DialogueId = 51008040,
          GUID = "7FB17A90",
          NextDialogue = 51008041,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine either way. Take your time and think it over — oh wait, I forgot the Escort aren't exactly known for their patience."
        },
        [51008041] = {
          Content = "我给你！我全都给你还不行么！",
          DialogueId = 51008041,
          GUID = "7FB17ABA",
          NextDialogue = 51008042,
          SpeakNpcId = 700113,
          Subtitle = "Fine! You want it? Take it! All yours!"
        },
        [51008042] = {
          Content = "就是这袋该死的月石！如果不是偶然发现它，我的兄弟们应该都还活着的！我们现在应该已经快要休息了……",
          DialogueId = 51008042,
          GUID = "7FB17AE4",
          NextDialogue = 51008043,
          SpeakNpcId = 700113,
          Subtitle = "Take this bloody sack of Phoxene... it's all because of this damn thing! If we hadn't stumbled across it... my mates would still be alive!"
        },
        [51008043] = {
          Content = "不不……我们今天的收获比往常还要好一点，没准今晚还能一起去一次水仙平原，每个人都能来上一杯满满的麦芽酒！",
          DialogueId = 51008043,
          GUID = "7FB17B0E",
          NextDialogue = 51008044,
          SpeakNpcId = 700113,
          Subtitle = "If they were, we'd be packing up by now... hell, we'd probably be down at the tavern already, raising a full pint of malt to a good day's haul..."
        },
        [51008044] = {
          Content = "我们可以一醉方休，可以吹牛到半夜，明早再一起……",
          DialogueId = 51008044,
          GUID = "7FB17B38",
          NextDialogue = 51008045,
          SpeakNpcId = 700113,
          Subtitle = "We'd drink 'til we sloshed. Shoot the breeze 'til the stars went out. And tomorrow... we'd—"
        },
        [51008045] = {
          Content = "我……我不能给你！",
          DialogueId = 51008045,
          GUID = "7FB17B62",
          SpeakNpcId = 700113,
          Subtitle = "No... I... I can't give it to you!"
        },
        [51008046] = {
          Camera = "-607.952148,-441.947266,565.15332,0.000023,-34.799801,23.996548,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你骗我！根本就没有什么卫戍部队，你就是想吞掉我这月石罢了！",
          DialogueId = 51008046,
          GUID = "7FB17B8C",
          NextDialogue = 51008047,
          SpeakNpcId = 700113,
          Subtitle = "You tricked me! There's no Escort coming — you just wanted the Phoxene for yourself!"
        },
        [51008047] = {
          Content = "你就是用它砸死了你的朋友——像刚才袭击我那样？",
          DialogueId = 51008047,
          GUID = "7FB17BB6",
          NextDialogue = 51008048,
          SpeakNpcId = 100001,
          Subtitle = "You killed your mates for these shiny rocks, didn't you? Same way you just tried to kill me?"
        },
        [51008048] = {
          Content = "是他们先动手的……我，我这都是正当防卫！",
          DialogueId = 51008048,
          GUID = "7FB17BE0",
          NextDialogue = 51008049,
          SpeakNpcId = 700113,
          Subtitle = "They attacked me first... I... I was defending myself!"
        },
        [51008049] = {
          Content = "还有你……你想贪下这包月石，你、又是什么好东西？还教训起我来了？",
          DialogueId = 51008049,
          GUID = "7FB17C0A",
          NextOptions = {
            [1] = 51008050,
            [2] = 51008051
          },
          SpeakNpcId = 700113,
          Subtitle = "And you — don't act high and mighty! You're after the Phoxene too, aren't you? What makes you any different from me!?"
        },
        [51008050] = {
          Content = "成年人应该为犯下的错付出代价，这包月石给你长点记性。",
          DialogueId = 51008050,
          GUID = "7FB17C34",
          ImprPlusId = 1001,
          NextDialogue = 51008052,
          Subtitle = "Grown men pay for their mistakes. Think of this sack of Phoxene as your price."
        },
        [51008051] = {
          Content = "我不是什么好人，你自然也不是。但我至少愿意给你留一条命，滚吧。",
          DialogueId = 51008051,
          GUID = "7FB17C5E",
          ImprPlusId = 1005,
          NextDialogue = 51008052,
          Subtitle = "I'm no saint — and you're no better than me. But at least I'm letting you live. Now get lost."
        },
        [51008052] = {
          Content = "（手里染血的月石沉甸甸的。它是如此沉重，仿佛要变成一个怪物，把所有的“拉里”都吃掉。）",
          DialogueId = 51008052,
          GUID = "7FB17C88",
          IsBlack = 1,
          Subtitle = "(The bloodstained Phoxene sits heavy in your hand. Heavier than it should be — almost as if it might twist itself into a gaping maw, waiting to devour the next \"Larry\" who gets too close.)"
        },
        [51008053] = {
          Content = "低头翻找一下看看",
          DialogueId = 51008053,
          GUID = "7FB17CB2",
          ImprCheckId = 1070,
          Subtitle = "Look down and search"
        },
        [51008054] = {
          ContentES = "(Después de eliminar a los problemáticos Filthoids, ves algo medio enterrado en la tierra. Curioso, te acercas para verlo mejor.)",
          DialogueId = 51008054,
          GUID = "7FB17CDC"
        },
        [51009001] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "新剧上映，新剧上映！那边的年轻人，要不要来体验一下？",
          DialogueId = 51009001,
          GUID = "7FB2183A",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          NextDialogue = 51009002,
          SpeakNpcId = 700240,
          Subtitle = "Fresh off the stage — new show, new experience! Hey, you there — fancy trying something different?"
        },
        [51009002] = {
          Content = "叫我吗？",
          DialogueId = 51009002,
          GUID = "7FB21864",
          NextDialogue = 51009003,
          SpeakNpcId = 100001,
          Subtitle = "You talking to me?"
        },
        [51009003] = {
          Content = "是的是的，盖雷亚剧院正在试演一种全新的戏剧——沉浸式戏剧！",
          DialogueId = 51009003,
          GUID = "7FB2188E",
          NextDialogue = 51009004,
          SpeakNpcId = 700240,
          Subtitle = "Uh-uh! The Galea Theatre is trial-running a brand-new form of performance — immersive theatre!"
        },
        [51009004] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "这是来自卢卡的全新演绎形式！你不会再像过去一样被按在观众席上，而是可以自己选择去哪儿，甚至自己成为故事的一部分……",
          DialogueId = 51009004,
          GUID = "7FB218B8",
          NextDialogue = 51009005,
          SpeakNpcId = 700240,
          Subtitle = "It's an exciting style from Luca: no more sitting stuck in your seat — you can move around freely, and even become part of the story yourself!",
          TalkActionId = {
            [1] = "700240:Explain02_Start"
          }
        },
        [51009005] = {
          Content = "我们需要志愿者来完成这场伟大的艺术实验！现在正在上映的是一场英雄冒险故事，你要来参加吗？我们准备了特别的礼物相赠！",
          DialogueId = 51009005,
          GUID = "7FB218E2",
          SpeakNpcId = 700240,
          Subtitle = "We're looking for volunteers to help bring this groundbreaking art experiment to life! Our current production is a timeless hero's adventure. Interested in joining? We've even got a special gift ready for every participant!",
          TalkActionId = {
            [1] = "700240:Explain02_End"
          }
        },
        [51009006] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "好，请跟我来！",
          DialogueId = 51009006,
          GUID = "7FB2190C",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          SpeakNpcId = 700240,
          Subtitle = "Wonderful! This way, please!",
          TalkActionId = {
            [1] = "700240:Explain01_Start"
          }
        },
        [51009007] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "好吧，等你有兴趣了再来找我就好！",
          DialogueId = 51009007,
          GUID = "7FB21936",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          SpeakNpcId = 700240,
          Subtitle = "That's alright! Swing by whenever the mood strikes — you'll be welcome anytime!",
          TalkActionId = {
            [1] = "700240:Agree"
          }
        },
        [51009008] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          Content = "你回来了，要来参加<H>沉浸式戏剧</>的试演吗？",
          DialogueId = 51009008,
          GUID = "7FB21960",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          SpeakNpcId = 700240,
          Subtitle = "Ah, you're back! Ready to give the immersive theatre experience a try?"
        },
        [51009009] = {
