        },
        [51009307] = {
          ContentES = "(Ella extiende la mano, toma hábilmente algunos tallos más del estante, paga junto con las suyas y te las entrega.)",
          DialogueId = 51009307,
          GUID = "7FB24A6E",
          NextDialogue = 51009308,
          Subtitle = "(She reaches out, deftly takes a few more stems from the shelf, pays for them along with her own, and hands them to you.)"
        },
        [51009308] = {
          ContentES = "Aquí tienes.",
          DialogueId = 51009308,
          GUID = "7FB24A98",
          NextDialogue = 51009309,
          SpeakNpcId = 700247,
          Subtitle = "Here you are."
        },
        [51009309] = {
          ContentES = "No hace falta que me des las gracias. Considera que estás compartiendo su buena fortuna.",
          DialogueId = 51009309,
          GUID = "7FB24AC2",
          NextDialogue = 51009317,
          SpeakNpcId = 700247,
          Subtitle = "No need to thank me. Just think of it as you sharing in his good fortune."
        },
        [51009310] = {
          ContentES = "Gracias, yo también las encuentro encantadoras.",
          DialogueId = 51009310,
          GUID = "7FB24AEC",
          ImprPlusId = 1004,
          NextDialogue = 51009311,
          Subtitle = "Thank you, I think they're lovely too."
        },
        [51009311] = {
          ContentES = "Puedes quedártelas si quieres.",
          DialogueId = 51009311,
          GUID = "7FB24B16",
          NextDialogue = 51009312,
          Subtitle = "You can have them if you like."
        },
        [51009312] = {
          ContentES = "Estoy segura de que a él tampoco le habría molestado.",
          DialogueId = 51009312,
          GUID = "7FB24B40",
          NextDialogue = 51009317,
          Subtitle = "I'm sure he wouldn't have minded either."
        },
        [51009313] = {
          ContentES = "¡No, no soporto el rosa!",
          DialogueId = 51009313,
          GUID = "7FB24B6A",
          ImprPlusId = 1005,
          NextDialogue = 51009314,
          Subtitle = "Oh no, I can't stand pink!"
        },
        [51009314] = {
          ContentES = "Vaya, lamento mucho escuchar eso.",
          DialogueId = 51009314,
          GUID = "7FB24B94",
          NextDialogue = 51009315,
          SpeakNpcId = 700247,
          Subtitle = "Oh dear, I'm so sorry to hear that."
        },
        [51009315] = {
          ContentES = "Bueno, es cierto. Supongo que no a todos les gusta el rosa…",
          DialogueId = 51009315,
          GUID = "7FB24BBE",
          NextDialogue = 51009316,
          SpeakNpcId = 700247,
          Subtitle = "Well, it's true. Not everyone likes pink, I suppose..."
        },
        [51009316] = {
          ContentES = "Ahora que lo mencionas, quizá a él tampoco… ¡Pero no importa! Vamos a fingir que sí.",
          DialogueId = 51009316,
          GUID = "7FB24BE8",
          NextDialogue = 51009317,
          SpeakNpcId = 700247,
          Subtitle = "Now that you mention it, perhaps he didn't either... But never mind! Let's just pretend he did."
        },
        [51009317] = {
          ContentES = "¿Son estas flores para alguien?",
          DialogueId = 51009317,
          GUID = "7FB24C12",
          NextDialogue = 51009318,
          SpeakNpcId = 100001,
          Subtitle = "Are these flowers for someone?"
        },
        [51009318] = {
          ContentES = "Sí. Tengo un amigo hada, muy parecido a ti con cuernos, y estas son para él.",
          DialogueId = 51009318,
          GUID = "7FB24C3C",
          NextOptions = {
            [1] = 51009319,
            [2] = 51009321
          },
          SpeakNpcId = 700247,
          Subtitle = "Yes. I have a faerie friend, much like you with horns, and these are for him."
        },
        [51009319] = {
          ContentES = "¿Hada?",
          DialogueId = 51009319,
          GUID = "7FB24C66",
          NextDialogue = 51009320,
          Subtitle = "Faerie?"
        },
        [51009320] = {
          ContentES = "Jeje, así es como él se llamaba a sí mismo.",
          DialogueId = 51009320,
          GUID = "7FB24C90",
          NextDialogue = 51009323,
          SpeakNpcId = 700247,
          Subtitle = "Oh, that's what he called himself."
        },
        [51009321] = {
          ContentES = "Soy Charon.",
          DialogueId = 51009321,
          GUID = "7FB24CBA",
          NextDialogue = 51009322,
          Subtitle = "I'm Charon."
        },
        [51009322] = {
          ContentES = "Bueno, “hada” era la palabra que él usaba.",
          DialogueId = 51009322,
          GUID = "7FB24CE4",
          NextDialogue = 51009323,
          SpeakNpcId = 700247,
          Subtitle = "Well, \"faerie\" was his word for it."
        },
        [51009323] = {
          ContentES = "Hablando de eso, ¿ha empezado a soplar el viento afuera?",
          DialogueId = 51009323,
          GUID = "7FB24D0E",
          NextOptions = {
            [1] = 51009324,
            [2] = 51009326,
            [3] = 51009328
          },
          SpeakNpcId = 700247,
          Subtitle = "Speaking of which,has the wind picked up outside?"
        },
        [51009324] = {
          ContentES = "No me di cuenta.",
          DialogueId = 51009324,
          GUID = "7FB24D38",
          NextDialogue = 51009325,
          Subtitle = "I didn't notice."
        },
        [51009325] = {
          ContentES = "Ya veo… No importa, lo comprobaré yo misma más tarde.",
          DialogueId = 51009325,
          GUID = "7FB24D62",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "I see... No matter, I'll check for myself later."
        },
        [51009326] = {
          ContentES = "Hace bastante viento.",
          DialogueId = 51009326,
          GUID = "7FB24D8C",
          NextDialogue = 51009327,
          Subtitle = "It's quite windy."
        },
        [51009327] = {
          ContentES = "Eso es maravilloso.",
          DialogueId = 51009327,
          GUID = "7FB24DB6",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "That's wonderful."
        },
        [51009328] = {
          ContentES = "Puedo crear viento, incluso si no lo hay.",
          DialogueId = 51009328,
          GUID = "7FB24DE0",
          NextDialogue = 51009329,
          Subtitle = "I can make wind, even if there isn't any."
        },
        [51009329] = {
          ContentES = "¿De verdad? ¿Eres tan {性别:poderoso|poderosa}? Muy amable de tu parte.",
          DialogueId = 51009329,
          GUID = "7FB24E0A",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "Really? You're that powerful? That's very kind of you."
        },
        [51009330] = {
          ContentES = "Necesito esperar a que el viento sople antes de poder darle las flores.",
          DialogueId = 51009330,
          GUID = "7FB24E34",
          NextOptions = {
            [1] = 51009331,
            [2] = 51009333,
            [3] = 51009335
          },
          SpeakNpcId = 700247,
          Subtitle = "I need to wait for the wind to pick up before I can give him the flowers."
        },
        [51009331] = {
          ContentES = "¿Por qué necesitas el viento?",
          DialogueId = 51009331,
          GUID = "7FB24E5E",
          NextDialogue = 51009332,
          Subtitle = "Why do you need the wind?"
        },
        [51009332] = {
          ContentES = "Porque cuando sopla el viento, las flores pueden flotar hacia el cielo.",
          DialogueId = 51009332,
          GUID = "7FB24E88",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "Because when the wind blows, the flowers can float up into the sky."
        },
        [51009333] = {
          ContentES = "¿Tu amigo es acaso un hada del viento?",
          DialogueId = 51009333,
          GUID = "7FB24EB2",
          NextDialogue = 51009334,
          Subtitle = "Is your friend a wind faerie, by any chance?"
        },
        [51009334] = {
          ContentES = "¡Qué pensamiento tan interesante! Quizá lo sea.",
          DialogueId = 51009334,
          GUID = "7FB24EDC",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "An interesting thought! Perhaps he is."
        },
        [51009335] = {
          ContentES = "¿Es algún tipo de ritual especial?",
          DialogueId = 51009335,
          GUID = "7FB24F06",
          NextDialogue = 51009336,
          Subtitle = "Is this some special kind of ritual?"
        },
        [51009336] = {
          ContentES = "Bueno… es un ritual para enviar pensamientos a alguien.",
          DialogueId = 51009336,
          GUID = "7FB24F30",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "Well... it's a ritual for sending thoughts to someone."
        },
        [51009337] = {
          ContentES = "Ese amigo mío… subió al cielo hace varios años.",
          DialogueId = 51009337,
          GUID = "7FB24F5A",
          NextDialogue = 51009338,
          SpeakNpcId = 700247,
          Subtitle = "That friend of mine... he went up to the sky several years ago."
        },
        [51009338] = {
          ContentES = "Hoy es el día anual de recuerdo.",
          DialogueId = 51009338,
          GUID = "7FB24F84",
          NextOptions = {
            [1] = 51009339
          },
          RestartTag = 51009338,
          SpeakNpcId = 700247,
          Subtitle = "Today is the annual day of remembrance."
        },
        [51009339] = {
          ContentES = "(Recuérdale las costumbres de Charon.)",
          DialogueId = 51009339,
          FailDialogue = 51009340,
          GUID = "7FB24FAE",
          ImprCheckId = 1071,
          NextDialogue = 51009341,
          Subtitle = "(Remind her of Charon customs.)"
        },
        [51009340] = {
          ContentES = "(Por un momento, no puedes recordar bien los detalles de la costumbre.)",
          DialogueId = 51009340,
          GUID = "7FB24FD8",
          Subtitle = "(For a moment, you can't quite recall the details of the custom.)"
        },
        [51009341] = {
          ContentES = "Según las creencias de Charon, el Mar Nebuloso es adonde van las almas. Si deseas recordarlo, dejar que las flores floten sobre el agua tendría más sentido.",
          DialogueId = 51009341,
          GUID = "7FB25002",
          NextDialogue = 51009342,
          SpeakNpcId = 100001,
          Subtitle = "In Charon belief, the Misty Sea is where souls go. If you wish to remember him, sending the flowers onto the water would make more sense."
        },
        [51009342] = {
          ContentES = "Sí… lo sé. Pero él era diferente.",
          DialogueId = 51009342,
          GUID = "7FB2502C",
          NextDialogue = 51009343,
          SpeakNpcId = 700247,
          Subtitle = "Well... I know. But he was different."
        },
        [51009343] = {
          ContentES = "(La mujer guarda silencio y mira por la ventana, en sus ojos se asoma una suave nostalgia.)",
          DialogueId = 51009343,
          GUID = "7FB25056",
          NextDialogue = 51009344,
          Subtitle = "(The woman falls silent, gazing out the window, her eyes filled with a gentle nostalgia.)"
        },
        [51009344] = {
          ContentES = "Lo conocí por primera vez a las afueras de la ciudad. Teníamos la misma edad y congeniamos de inmediato, así que nos hicimos amigos enseguida.",
          DialogueId = 51009344,
          GUID = "7FB25080",
          NextDialogue = 51009345,
          SpeakNpcId = 700247,
          Subtitle = "I first met him outside the city. We were the same age, and our personalities just clicked, so we became fast friends."
        },
        [51009345] = {
          ContentES = "Me decía que era un “hada” venida del cielo… Jeje… en realidad, desde el principio supe que él era Charon. Pero cada vez que lo veía esforzarse tanto por mantener esa historia, no tenía corazón para quitársela.",
          DialogueId = 51009345,
          GUID = "7FB250AA",
          NextDialogue = 51009346,
          SpeakNpcId = 700247,
          Subtitle = "He told me he was a \"faerie\" from the sky... Hehe, truthfully, I knew all along he was Charon. But every time I saw him trying so hard to keep up the story, I couldn't bear to spoil it for him."
        },
        [51009346] = {
          ContentES = "Además, era realmente como un hada de los cuentos: sabía tantas cosas que yo desconocía y siempre tenía historias fascinantes que contar, una tras otra.",
          DialogueId = 51009346,
          GUID = "7FB250D4",
          NextOptions = {
            [1] = 51009347,
            [2] = 51009349
          },
          SpeakNpcId = 700247,
          Subtitle = "Besides, he really was just like a faerie from the stories — he knew so many things I didn't, and always had endless fascinating tales to tell."
        },
        [51009347] = {
          ContentES = "Suena como un amigo maravilloso.",
          DialogueId = 51009347,
          GUID = "7FB250FE",
          NextDialogue = 51009348,
          Subtitle = "Sounds like a wonderful friend."
        },
        [51009348] = {
          ContentES = "¡Sí! Fue el mejor amigo que alguien podría tener.",
          DialogueId = 51009348,
          GUID = "7FB25128",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Yes! He's the best friend ever."
        },
        [51009349] = {
          ContentES = "Entonces, ¿pasó toda su vida interpretando el papel de un hada?",
          DialogueId = 51009349,
          GUID = "7FB25152",
          NextDialogue = 51009350,
          Subtitle = "So he was playing the part of a faerie his whole life?"
        },
        [51009350] = {
          ContentES = "Dicho así, suena un poco infantil, ¿no crees?",
          DialogueId = 51009350,
          GUID = "7FB2517C",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Sounds a bit childish when you put it like that, doesn't it?"
        },
        [51009351] = {
          ContentES = "Siempre me inquietó un poco… pensar en cómo acabaríamos hablando de ello cuando crecieras y dejáramos atrás la edad en la que creer en cuentos de hadas era algo natural.",
          DialogueId = 51009351,
          GUID = "7FB251A6",
          NextDialogue = 51009352,
          SpeakNpcId = 700247,
          Subtitle = "It always bothered me a little... wondering how we would finally talk about it, once we grew up and passed the age where believing in fairy tales came naturally."
        },
        [51009352] = {
          ContentES = "Fuera yo o fuera él quien lo mencionara, solo imaginarlo ya resultaba incómodo…",
          DialogueId = 51009352,
          GUID = "7FB251D0",
          NextDialogue = 51009353,
          SpeakNpcId = 700247,
          Subtitle = "Whether I brought it up or he did, just imagining it felt so awkward..."
        },
        [51009353] = {
          ContentES = "Pero al final, nunca llegamos a ese momento. Se fue antes de que alcanzáramos la mayoría de edad.",
          DialogueId = 51009353,
          GUID = "7FB251FA",
          NextDialogue = 51009354,
          SpeakNpcId = 700247,
          Subtitle = "But in the end, we never reached that point. He left before we came of age."
        },
        [51009354] = {
          ContentES = "¿Crees que… eligió marcharse justo en ese momento porque lo sabía? Qué alma tan bondadosa tenía…",
          DialogueId = 51009354,
          GUID = "7FB25224",
          NextDialogue = 51009355,
          SpeakNpcId = 700247,
          Subtitle = "Do you think... he might have chosen to leave at that precise time because he knew? What a gentle soul he was..."
        },
        [51009355] = {
          ContentES = "(La mujer acaricia los suaves pétalos y baja la mirada con delicadeza. Es imposible descifrar del todo la emoción en su rostro.)",
          DialogueId = 51009355,
          GUID = "7FB2524E",
          NextOptions = {
            [1] = 51009356,
            [2] = 51009358,
            [3] = 51009360
          },
          Subtitle = "(The woman strokes the soft petals, gently lowering her gaze. You can't quite decipher the emotion on her face.)"
        },
        [51009356] = {
          ContentES = "Lamento mucho tu pérdida.",
          DialogueId = 51009356,
          GUID = "7FB25278",
          ImprPlusId = 1002,
          NextDialogue = 51009357,
          Subtitle = "Sorry for your loss."
        },
        [51009357] = {
          ContentES = "No pasa nada. Han pasado muchos años.",
          DialogueId = 51009357,
          GUID = "7FB252A2",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "It's okay. It's been years."
        },
        [51009358] = {
          ContentES = "Ambos son personas increíblemente bondadosas.",
          DialogueId = 51009358,
          GUID = "7FB252CC",
          ImprPlusId = 1004,
          NextDialogue = 51009359,
          Subtitle = "You're both incredibly kind people."
        },
        [51009359] = {
          ContentES = "Entonces... gracias.",
          DialogueId = 51009359,
          GUID = "7FB252F6",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Then... thank you."
        },
        [51009360] = {
          ContentES = "Al llegar a la mayoría de edad… ¿empezó a mostrar señales de Deterioro?",
          DialogueId = 51009360,
          GUID = "7FB25320",
          ImprPlusId = 1003,
          NextDialogue = 51009361,
          Subtitle = "Coming of age... Did he start showing signs of Deterioration?"
        },
        [51009361] = {
          ContentES = "Sí… eso fue exactamente lo que pensé. Después de todo, se marchó justo antes de cumplir los dieciocho años.",
          DialogueId = 51009361,
          GUID = "7FB2534A",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Well, that's what I thought. After all, he left just before he turned eighteen."
        },
        [51009362] = {
          ContentES = "Había previsto su propio destino. La última vez que nos vimos, me dijo que regresaba a su patria en el cielo y que ya no podría volver a visitarme.",
          DialogueId = 51009362,
          GUID = "7FB25374",
          NextDialogue = 51009363,
          SpeakNpcId = 700247,
          Subtitle = "He had foreseen his own fate. The last time we met, he told me he was returning to his homeland in the sky and wouldn't be able to visit me anymore."
        },
        [51009363] = {
          ContentES = "Fue la mentira más torpe que contó en toda su vida… Sus ojos ya estaban llenos de lágrimas, pero aun así forzó una sonrisa y, con el tono más animado posible, me dijo:",
          DialogueId = 51009363,
          GUID = "7FB2539E",
          NextDialogue = 51009364,
          SpeakNpcId = 700247,
          Subtitle = "It was the most poorly told lie of his life... His eyes were already brimming with tears, yet he forced a smile and said to me in the cheeriest voice—"
        },
        [51009364] = {
          ContentES = "“Por favor, no estés triste. Aunque ya no pueda venir a verte, siempre estaré cuidándote desde lo alto de las nubes…”",
          DialogueId = 51009364,
          GUID = "7FB253C8",
          NextDialogue = 51009365,
          SpeakNpcId = 700247,
          Subtitle = "\"Please don't be sad. Even though I can't come to see you anymore, I'll be watching over you from above the clouds, always...\""
        },
        [51009365] = {
          ContentES = "“Cada vez que mires al cielo, tus pensamientos llegarán hasta mí, llevados por el viento.”",
          DialogueId = 51009365,
          GUID = "7FB253F2",
          NextDialogue = 51009366,
          SpeakNpcId = 700247,
          Subtitle = "\"Whenever you look up at the sky, your thoughts will reach me on the wind.\""
        },
        [51009366] = {
          ContentES = "(Mientras dice esto, la mujer sonríe. ¿Es un juego de luces, o hay un leve destello en sus ojos, una lágrima, o quizá el reflejo del sol a través del cristal de la ventana?)",
          DialogueId = 51009366,
          GUID = "7FB2541C",
          NextDialogue = 51009367,
          Subtitle = "(As she says this, the woman smiles. Is it a trick of the light, or is there a faint glimmer in her eyes—a tear, or perhaps a reflection from the sun through the window pane?)"
        },
        [51009367] = {
          ContentES = "Así que… ¿por eso lanzaste las flores al cielo?",
          DialogueId = 51009367,
          GUID = "7FB25446",
          NextDialogue = 51009368,
          SpeakNpcId = 100001,
          Subtitle = "So, that's why you cast the flowers into the sky?"
        },
        [51009368] = {
          ContentES = "Así es. Ya que esa era la historia que él quería contarme, elijo creer que su descanso final no se encuentra en el Mar Nebuloso, sino en el vasto cielo azul.",
          DialogueId = 51009368,
          GUID = "7FB25470",
          NextDialogue = 51009369,
          SpeakNpcId = 700247,
          Subtitle = "Indeed. Since that was the story he wanted to tell me, I choose to believe that his final resting place isn't the Misty Sea, but the vast blue sky."
        },
        [51009369] = {
          ContentES = "Mientras esparza los pétalos al viento, él sentirá mis pensamientos.",
          DialogueId = 51009369,
          GUID = "7FB2549A",
          NextOptions = {
            [1] = 51009370,
            [2] = 51009371
          },
          SpeakNpcId = 700247,
          Subtitle = "As long as I scatter the petals to the wind, he'll feel my thoughts."
        },
        [51009370] = {
          ContentES = "Espero que reciba tus flores.",
          DialogueId = 51009370,
          GUID = "7FB254C4",
          NextDialogue = 51009372,
          Subtitle = "I hope he receives your flowers."
        },
        [51009371] = {
          ContentES = "Estoy {性别:seguro|segura} de que las recibirá.",
          DialogueId = 51009371,
          GUID = "7FB254EE",
          NextDialogue = 51009372,
          Subtitle = "I'm sure he will receive them."
        },
        [51009372] = {
          ContentES = "…Gracias.",
          DialogueId = 51009372,
          GUID = "7FB25518",
          NextDialogue = 51009373,
          SpeakNpcId = 700247,
          Subtitle = "...Thank you."
        },
        [51009373] = {
          ContentES = "Ahora, al mirar atrás, creo que en el fondo siempre supo que yo había visto a través de su pequeña farsa.",
          DialogueId = 51009373,
          GUID = "7FB25542",
          NextDialogue = 51009374,
          SpeakNpcId = 700247,
          Subtitle = "Looking back now, I think he probably knew all along that I had seen through his little charade."
        },
        [51009374] = {
          ContentES = "Una historia tejida con mentiras, que termina con otra mentira… ¿no resulta, de algún modo, bastante apropiado?",
          DialogueId = 51009374,
          GUID = "7FB2556C",
          NextDialogue = 51009375,
          SpeakNpcId = 700247,
          Subtitle = "A story woven from lies, ending with a lie... doesn't that seem rather fitting, in a way?"
        },
        [51009375] = {
          ContentES = "Bien, será mejor que vaya fuera de la ciudad para cumplir mi promesa antes de que anochezca.",
          DialogueId = 51009375,
          GUID = "7FB25596",
          NextDialogue = 51009376,
          SpeakNpcId = 700247,
          Subtitle = "Right, I'd best be off outside the city walls to keep my promise to him before it gets dark."
        },
        [51009376] = {
          ContentES = "Adiós, pequeña hada. Que tu propia historia tenga un final verdadero y feliz.",
          DialogueId = 51009376,
          GUID = "7FB255C0",
          SpeakNpcId = 700247,
          Subtitle = "Goodbye, little faerie. May your own story have a true and happy ending."
        },
        [51009377] = {
          ContentES = "Hola de nuevo, pequeña hada. Hace un tiempo precioso hoy, ¿verdad?",
          DialogueId = 51009377,
          GUID = "7FB255EA",
          SpeakNpcId = 700247,
          Subtitle = "Hello again, little faerie. Lovely weather we're having, isn't it?"
        },
        [51009401] = {
          ContentES = "¡Por favor, espere un momento, {性别:honorable señor|honorable señora}!",
          DialogueId = 51009401,
          GUID = "7FB259DA",
          NextDialogue = 51009402,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A moment of your time, {性别:good sir|fair lady}!",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009402] = {
          ContentES = "Ah... ¿cómo podría siquiera describir su belleza?",
          DialogueId = 51009402,
          GUID = "7FB25A04",
          NextDialogue = 51009403,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah... how does one even begin to capture your beauty?"
        },
        [51009403] = {
          ContentES = "Un tanuki mudo compone poemas en su honor, la luna verdosa os cubre con un resplandor dorado. Una liebre marina le corona con gemas talladas en frutos de palma... y yo, junto a un basurero olvidado, canto su nombre a las estrellas —",
          DialogueId = 51009403,
          GUID = "7FB25A2E",
          NextDialogue = 51009404,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A mute tanuki pens sonnets in your name; the verdant moon casts gold across your form. A sea hare crowns you with palmfruit jewels... while I, by a forgotten bin, sing your name to the stars—"
        },
        [51009404] = {
          ContentES = "Que mis alabanzas alcancen o no su mirada, le ruego... le imploro...",
          DialogueId = 51009404,
          GUID = "7FB25A58",
          NextDialogue = 51009405,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Even if my words fall short of your splendour, I beg you... I implore you..."
        },
        [51009405] = {
          ContentES = "¡Oh! ¡Qué porte tan impresionante! ¡Debe de ser {性别:el famoso Phoxcazador, señor|la famosa Phoxcazadora, señora} {nickname}!",
          DialogueId = 51009405,
          GUID = "7FB25A82",
          NextDialogue = 51009406,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! Such poise, such presence! You must be the illustrious Phoxhunter — {性别:Mr|Miss} !",
          TalkActionId = {
            [1] = "700306:Talk01_End"
          }
        },
        [51009406] = {
          ContentES = "(¿Soy tan {性别:conocido|conocida} así? ... No, tengo la sensación de que esto no va a traer nada bueno...)",
          DialogueId = 51009406,
          GUID = "7FB25AAC",
          NextDialogue = 51009407,
          SpeakNpcId = 100001,
          Subtitle = "(Am I actually that well-known around here...? No — this is definitely heading somewhere strange...)"
        },
        [51009407] = {
          ContentES = "Encantado de conocerle, me llamo Fane. Mi profesora le espera desde hace mucho tiempo. Sígame, por favor.",
          DialogueId = 51009407,
          GUID = "7FB25AD6",
          NextDialogue = 51009408,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          Subtitle = "A pleasure to meet you — I'm Fane. My teacher has been awaiting your arrival. This way, please.",
          TalkActionId = {
            [1] = "700306:Talk02_Start"
          }
        },
        [51009408] = {
          ContentES = "¿Profesora?",
          DialogueId = 51009408,
          GUID = "7FB25B00",
          NextDialogue = 51009409,
          SpeakNpcId = 100001,
          Subtitle = "Teacher?",
          TalkActionId = {
            [1] = "700306:Talk02_End"
          }
        },
        [51009409] = {
          ContentES = "Ah... es cierto, me pidió que no la llamara así en público. Pero supongo que para usted no será un problema... le agradecería que mantuviera eso en privado.",
          DialogueId = 51009409,
          GUID = "7FB25B2A",
          Scripts = "PlayOrStopBGM{_delay{8},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          Subtitle = "Oh — right... She asked me not to call her that in public. But I doubt she'll mind if it's you. Still... I'd appreciate it if you kept it just between us."
        },
        [51009410] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Profesora, le he traído {性别:a la señora|al señor}{nickname}.",
          DialogueId = 51009410,
          GUID = "7FB25B54",
          LookAt = {
            [1] = "700306:n(700300)"
          },
          NextDialogue = 51009411,
          SpeakNpcId = 700306,
          Subtitle = "Ms Violetta, I've brought ."
        },
        [51009411] = {
          Camera = "-398.734863,102.79834,140.336914,0.000002,-0.59967,-17.199116,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Aquí estás, joven {性别:Phoxcazador|Phoxcazadora}.",
          DialogueId = 51009411,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25B7E",
          LookAt = {
            [1] = "700306:n(100001)"
          },
          NextDialogue = 51009412,
          SpeakNpcId = 700300,
          Subtitle = "You've come, young Phoxhunter.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009412] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Oh, qué {性别:chico|chica} tan adorable. Tu rostro me recuerda a los primeros copos de Lago Helado, puros, cristalinos y los granates rojos que se posan sobre ellos, tan delicados que no puedo evitar querer tocarlos...",
          DialogueId = 51009412,
          GUID = "7FB25BA8",
          NextDialogue = 51009413,
          SpeakNpcId = 700300,
          Subtitle = "Ah... such a darling child. Your beauty reminds me of Icelake's first snow — that flawless glisten... and those garnets scattered across it, red as pigeon blood... so tender, one's hand longs to—",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009413] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Espera... no te acerques a mí!",
          DialogueId = 51009413,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "-93.166504,20.057129,149.304932,-1.999999,-3.400054,-165.189987,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB25BD2",
          NextDialogue = 51009414,
          SpeakNpcId = 100001,
          Subtitle = "Wait — don't come any closer!",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1
        },
        [51009414] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Jeje... Veo que no te agradan mucho los gestos de afecto. Mis disculpas, todo esto debe parecerte muy extraño. Permíteme presentarme adecuadamente.",
          DialogueId = 51009414,
          GUID = "7FB25BFC",
          NextDialogue = 51009415,
          SpeakNpcId = 700300,
          Subtitle = "Hehe, not a fan of warm greetings, I see. My apologies — this must all seem terribly dubious. Allow me to introduce myself properly.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009415] = {
          ContentES = "Me llamo Violetta. Soy una cantante de ópera.",
          DialogueId = 51009415,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB25C26",
          NextDialogue = 51009416,
          SpeakNpcId = 700300,
          Subtitle = "I'm Violetta — an opera singer.",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009416] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(¿Por qué todos los cantantes de ópera hablan de una forma tan extraña...?)",
          DialogueId = 51009416,
          GUID = "7FB25C50",
          NextDialogue = 51009417,
          SpeakNpcId = 100001,
          Subtitle = "(Why do you opera singers talk like that...?)",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009417] = {
          Camera = "-142.214844,78.577148,148.40918,0.000003,-0.599971,-20.395008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Si mi rostro te suena, seguramente me has visto en el escenario... o en un cartel de un espectáculo por aquí.",
          DialogueId = 51009417,
          GUID = "7FB25C7A",
          NextOptions = {
            [1] = 510093271,
            [2] = 510093272
          },
          SpeakNpcId = 700300,
          Subtitle = "If I seem familiar, perhaps you've seen me on stage... or glimpsed one of my posters nearby."
        },
        [51009418] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Lo recuerdo. “La voz onírica venida de Luca, el rostro de mil metamorfosis”... Eso es lo que decían los carteles, ¿verdad?",
          DialogueId = 51009418,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB25CA4",
          NextDialogue = 51009420,
          SpeakNpcId = 100001,
          Subtitle = "I remember now — \"A dream-born voice from Luca, a visage that shifts like mist.\" That's what the posters said, right?",
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51009419] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "“La voz onírica venida de Luca, el rostro de mil metamorfosis” . Así es como la describen. La Profesora Violetta es la cantante más destacada de todo Lago Helado. Se pueden ver enormes carteles con su imagen en el Teatro Galea.",
          DialogueId = 51009419,
          GUID = "7FB25CCE",
          LookAt = {
            [1] = "100001:n(700306)"
          },
          NextDialogue = 51009420,
          SpeakNpcId = 700306,
          Subtitle = "\"A dream-born voice from Luca, a visage that shifts like mist\" — that's her. Ms Violetta is the most sought-after diva in Icelake. You'll find her posters all over the Galea Theatre.",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009420] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que así me presentan... Un poco exagerado, ciertamente, pero debo decir que me gusta.",
          DialogueId = 51009420,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB25CF8",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009421,
          SpeakNpcId = 700300,
          Subtitle = "So that's what they say about me. A bit extravagant... but I rather like the sound of it.",
          TalkActionId = {
            [1] = "700306:Talk01_End",
            [2] = "700300:Confident_Start"
          }
        },
        [51009421] = {
          ContentES = "Me encanta ver a las multitudes aclamando mis actuaciones, escuchar sus conversaciones apasionadas sobre tal o cual fragmento cantado.",
          DialogueId = 51009421,
          GUID = "7FB25D22",
          NextDialogue = 51009422,
          SpeakNpcId = 700300,
          Subtitle = "I love the applause — and the chatter my performances stir in every corner of the city."
        },
        [51009422] = {
          ContentES = "Cada papel que interpreto, cada capricho improvisado... enciende las columnas de chismes durante semanas.",
          DialogueId = 51009422,
          GUID = "7FB25D4C",
          NextDialogue = 51009423,
          SpeakNpcId = 700300,
          Subtitle = "Every role I play, every off-script whim... they ignite the gossip columns for weeks. I thrive on that kind of attention."
        },
        [51009423] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Perdona que interrumpa... pero, ¿cuál es exactamente el encargo?",
          DialogueId = 51009423,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25D76",
          NextDialogue = 51009424,
          SpeakNpcId = 100001,
          Subtitle = "Sorry to interrupt... but what's the job, exactly?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009424] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah... me dejo llevar por mis palabras, como siempre.",
          DialogueId = 51009424,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25DA0",
          NextDialogue = 51009425,
          SpeakNpcId = 700300,
          Subtitle = "Ah, forgive me — I've let my flourishes run away with me again.",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700300:Explain02_Start"
          }
        },
        [51009425] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "La verdad es que, aunque disfruto ser el centro de atención, y me he acostumbrado bastante hay... ciertas situaciones que incluso yo encuentro problemáticas.",
          DialogueId = 51009425,
          GUID = "7FB25DCA",
          NextDialogue = 51009426,
          SpeakNpcId = 700300,
          Subtitle = "Truth is, while I do enjoy being the centre of attention — and have grown quite used to it — there are... certain situations even I find troublesome.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009426] = {
          ContentES = "Mira esto.",
          DialogueId = 51009426,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Letter.T_Guide_ChapterFire_Letter'}",
          GUID = "7FB25DF4",
          NextDialogue = 51009427,
          SpeakNpcId = 700300,
          Subtitle = "Here — take a look at this.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009427] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Una carta de amor? Parece que viene de uno de tus admiradores.",
          DialogueId = 51009427,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25E1E",
          NextDialogue = 51009428,
          SpeakNpcId = 100001,
          Subtitle = "A love letter? Looks like it's from one of your fans.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009428] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ser demasiado adulada puede convertirse a veces en una carga. Entiendo su pasión, aunque no pueda compartirla, siempre hago mi mejor esfuerzo por responder con cortesía.",
          DialogueId = 51009428,
          GUID = "7FB25E48",
          NextDialogue = 51009429,
          SpeakNpcId = 700300,
          Subtitle = "Popularity can be a heavy crown. I understand their affection — and while I can't reciprocate those feelings, I do my best to respond with kindness.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009429] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No es la primera vez que recibo este tipo de cartas... y siempre he intentado responderlas. Pero esta vez... ¡he recibido un cajón entero!",
          DialogueId = 51009429,
          GUID = "7FB25E72",
          NextDialogue = 51009430,
          SpeakNpcId = 700300,
          Subtitle = "I've received such letters before — many, in fact — and I've replied where I could. But this time, I've been sent an entire box.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009430] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡¿Un... cajón entero?!",
          DialogueId = 51009430,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB25E9C",
          NextDialogue = 51009431,
          SpeakNpcId = 100001,
          Subtitle = "An entire box of letters...!?",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009431] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí. Y todas vienen de la misma persona. Primero el buzón... luego mi carruaje, el marco de mi puerta, las macetas, los alféizares de las ventanas...",
          DialogueId = 51009431,
          GUID = "7FB25EC6",
          NextDialogue = 51009432,
          SpeakNpcId = 700300,
          Subtitle = "Yes — all from the same admirer. It began with the mailbox... then my carriage, then the doorframe, flowerpots, windowsills...",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "100001:Shock_End"
          }
        },
        [51009432] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Cada rincón de mi hogar se encuentra lleno de cartas en cuanto me doy la vuelta.",
          DialogueId = 51009432,
          GUID = "7FB25EF0",
          NextDialogue = 51009433,
          SpeakNpcId = 700300,
          Subtitle = "They slip them in wherever they can — whenever my back is turned.",
          TalkActionId = {
            [1] = "700300:Talk01_End"
          }
        },
        [51009433] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿No debería ser la Escolta la encargada de este tipo de asuntos?",
          DialogueId = 51009433,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB25F1A",
          NextDialogue = 51009434,
          SpeakNpcId = 100001,
          Subtitle = "Shouldn't this be something for the Escort to deal with?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009434] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eso también pensé al principio. Pero las personalidades públicas siempre deben andar con pies de plomo...",
          DialogueId = 51009434,
          GUID = "7FB25F44",
          NextDialogue = 51009435,
          SpeakNpcId = 700300,
          Subtitle = "That was my first thought as well. But public figures... walk a fine line.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009435] = {
          ContentES = "Una pequeña anécdota puede convertirme en el tema favorito de los chismes... pero como artista, me gustaría que se hablara de mi arte en el escenario, no de mis asuntos del corazón. Espero que lo entiendas.",
          DialogueId = 51009435,
          GUID = "7FB25F6E",
          NextDialogue = 51009436,
          SpeakNpcId = 700300,
          Subtitle = "A bit of harmless gossip might make me the talk of teatimes... but as a performer, I'd rather the town whisper about my stagecraft — not my romances.",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009436] = {
          Camera = "124.308105,149.785156,166.572021,0.000009,-4.799984,-153.390015,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "De acuerdo, entiendo. ¿Tienes alguna pista sobre el remitente?",
          DialogueId = 51009436,
          GUID = "7FB25F98",
          NextDialogue = 51009437,
          SpeakNpcId = 100001,
          Subtitle = "Fair enough. Do you have any clues about the sender?"
        },
        [51009437] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Olvidé mencionarlo antes: en realidad sé dónde vive. Las cartas son anónimas, pero él realmente no ha intentado ocultar su identidad.",
          DialogueId = 51009437,
          GUID = "7FB25FC2",
          NextDialogue = 51009438,
          SpeakNpcId = 700300,
          Subtitle = "Ah, yes — I forgot to mention. I actually do know where he lives. The letters are unsigned, but he's made no real effort to hide his identity.",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009438] = {
          ContentES = "Después de todo, si uno debe ocultar su nombre incluso en una carta de amor... ¿cómo esperar una respuesta?",
          DialogueId = 51009438,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB25FEC",
          NextDialogue = 51009439,
          SpeakNpcId = 700300,
          Subtitle = "If one must hide even their name in a love letter... what hope is there for a reply?"
        },
        [51009439] = {
          Camera = "-642.584961,260.924316,353.573975,0.000005,-21.200073,-26.393641,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Todo lo que te pido es que lo encuentres... y que le des una pequeña “advertencia”.",
          DialogueId = 51009439,
          GUID = "7FB26016",
          NextOptions = {
            [1] = 510093491,
            [2] = 510093492
          },
          SpeakNpcId = 700300,
          Subtitle = "I only ask that you find him... and deliver a gentle \"warning.\""
        },
        [51009440] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sabía que podía contar contigo.",
          DialogueId = 51009440,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB26040",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          Subtitle = "How reassuring. I knew you were the right one to ask.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009441] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sabes... este tipo de persona podría malinterpretar cualquier atención. Incluso podría animarle a ir más lejos.",
          DialogueId = 51009441,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2606A",
          NextDialogue = 51009442,
          SpeakNpcId = 700300,
          Subtitle = "You see, someone like that... even a moment of attention might feel like victory. And that can turn dangerous.",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009442] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ya entiendo. Tiene sentido.",
          DialogueId = 51009442,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB26094",
          NextDialogue = 51009443,
          SpeakNpcId = 100001,
          Subtitle = "I see. That makes sense."
        },
        [51009443] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sabía que podía contar contigo.",
          DialogueId = 51009443,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB260BE",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          Subtitle = "Then I'll leave it in your hands.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009444] = {
          ContentES = "Ah, y antes de que te vayas, toma esto. Puede ser útil.",
          DialogueId = 51009444,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          GUID = "7FB260E8",
          NextDialogue = 51009445,
          SpeakNpcId = 700300,
          Subtitle = "Oh — and before you go, take this. It may come in handy.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009445] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Esta cinta...",
          DialogueId = 51009445,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB26112",
          NextDialogue = 51009446,
          SpeakNpcId = 100001,
          Subtitle = "This ribbon...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009446] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Hay algo mal?",
          DialogueId = 51009446,
          GUID = "7FB2613C",
          NextDialogue = 51009447,
          SpeakNpcId = 700300,
          Subtitle = "Is something wrong?"
        },
        [51009447] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No... no es nada. Volveré pronto.",
          DialogueId = 51009447,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26166",
          SpeakNpcId = 100001,
          Subtitle = "No... it's nothing. I'll be back soon.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009448] = {
          Camera = "695.307617,-554.236328,471.275024,0.000054,-20.794161,139.593384,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "La dirección que me dio la señora Violetta debería estar aquí... Sin embargo, no parece haber viviendas en los alrededores.",
          DialogueId = 51009448,
          GUID = "7FB26190",
          NextDialogue = 51009449,
          SpeakNpcId = 100001,
          Subtitle = "This is the address Ms Violetta gave me. Doesn't exactly look like a residential area, though...",
          TalkActionId = {
            [1] = "700313:Think_Start"
          }
        },
        [51009449] = {
          ContentES = "Hay un soldado cerca. Vamos a hacerle algunas preguntas.",
          DialogueId = 51009449,
          GUID = "7FB261BA",
          NextDialogue = 51009450,
          SpeakNpcId = 100001,
          Subtitle = "There's a guard nearby — maybe he'll know something."
        },
        [51009450] = {
          Camera = "232.955078,593.629395,162.682861,0.000058,-3.794279,-115.003006,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hola, me gustaría preguntarle algo.",
          DialogueId = 51009450,
          GUID = "7FB261E4",
          NextDialogue = 51009451,
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"Questpoint_Nvzhu_20023002\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Hey — mind if I ask you something?"
        },
        [51009451] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Estoy un poco ocupado ahora. ¿Puede esperar? ...Vaya, esto es raro. ¿Qué le pasa a este fonógrafo?",
          DialogueId = 51009451,
          GUID = "7FB2620E",
          NextDialogue = 51009452,
          SpeakNpcId = 700313,
          Subtitle = "Bit tied up right now — can it wait? ...Huh, that's odd. What's up with this phonograph?"
        },
        [51009452] = {
          Camera = "408.029297,-87.160217,216.346191,0.000075,-13.994142,150.79335,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(El soldado se agita, visiblemente molesto, manipulando un viejo fonógrafo a sus pies.)",
          DialogueId = 51009452,
          GUID = "7FB26238",
          NextDialogue = 51009453,
          Subtitle = "(The soldier frowns at an old phonograph at his feet, fiddling with the dials in frustration.)"
        },
        [51009453] = {
          ContentES = "¿Está roto?",
          DialogueId = 51009453,
          GUID = "7FB26262",
          NextDialogue = 51009454,
          SpeakNpcId = 100001,
          Subtitle = "Is it broken?"
        },
        [51009454] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No está realmente roto... solo es viejo. A veces falla. Juro que un buen golpe solía arreglarlo...",
          DialogueId = 51009454,
          GUID = "7FB2628C",
          NextOptions = {
            [1] = 510093641
          },
          SpeakNpcId = 700313,
          Subtitle = "Not broken, exactly... just old. Sometimes it acts up. I swear a good smack used to fix it...",
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009455] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Sabes cómo funcionan estos? Está bien, arréglalo y te responderé todo lo que necesites.",
          DialogueId = 51009455,
          GUID = "7FB262B6",
          NextDialogue = 51009456,
          SpeakNpcId = 700313,
          Subtitle = "You know how to work these? Alright — fix it for me, and I'll answer whatever you need.",
          TalkActionId = {
            [1] = "700313:Talk01_End"
          }
        },
        [51009456] = {
          Camera = "96.858398,213.679291,148.014893,0.00006,-3.794279,-114.800949,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Trato hecho.",
          DialogueId = 51009456,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB262E0",
          SpeakNpcId = 100001,
          Subtitle = "Deal.",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Talk01_End"
          }
        },
        [51009457] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ahí tienes, eso debería funcionar.",
          DialogueId = 51009457,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "7FB2630A",
          NextDialogue = 51009458,
          SpeakNpcId = 100001,
          Subtitle = "There — that should do it.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009458] = {
          Camera = "490.863281,-71.149292,246.487061,0.000077,-14.394158,157.593735,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡No está mal! Finalmente podré escuchar mis cintas. Ah, la voz de señora Violetta... qué delicia...",
          DialogueId = 51009458,
          GUID = "7FB26334",
          NextDialogue = 51009459,
          SpeakNpcId = 700313,
          Subtitle = "Not bad! Now I can finally enjoy my tapes again... Ahh, Ms Violetta's voice — it's just—",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700313:Shock_Start"
          }
        },
        [51009459] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Conoce a la señora Violetta?",
          DialogueId = 51009459,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2635E",
          NextDialogue = 51009460,
          SpeakNpcId = 100001,
          Subtitle = "Wait — you know Violetta?",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Shock_End"
          }
        },
        [51009460] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Quién en Lago Helado no la conoce? ¡Su primer disco vale una fortuna! He estado ahorrando durante tres meses y aún no puedo permitírmelo... Así que me conformo con estas cintas baratas.",
          DialogueId = 51009460,
          GUID = "7FB26388",
          NextDialogue = 51009461,
          SpeakNpcId = 700313,
          Subtitle = "Who in Icelake doesn't? Her debut album's a collector's item! I've been saving for three months and still can't afford one... Guess these budget tapes will have to do for now.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009461] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Perfecto. Porque lo que quería preguntarte en realidad es sobre la señora Violetta.",
          DialogueId = 51009461,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB263B2",
          SpeakNpcId = 100001,
          Subtitle = "Perfect. Because what I wanted to ask is actually about Ms Violetta.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009462] = {
          ContentES = "(Tras hacer jurar al guardia que mantendría el secreto, le explicas la situación: la señora Violetta ha estado recibiendo cartas no deseadas de un admirador obsesionado.)",
          DialogueId = 51009462,
          GUID = "7FB263DC",
          Subtitle = "(After swearing the guard to secrecy, you explain the situation: Ms Violetta has been receiving unwanted letters from an obsessed admirer.)"
        },
        [51009463] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡¿Qué!? ¡Es escandaloso! Si se esconde en este barrio, lo sacaré de ahí y le enseñaré modales.",
          DialogueId = 51009463,
          GUID = "7FB26406",
          NextDialogue = 51009464,
          SpeakNpcId = 700313,
          Subtitle = "What!? That's outrageous! If that creep's squatting on my beat, I'll drag him out myself — give him a piece of my mind!",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700313:Angry01_Start"
          }
        },
        [51009464] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eso... no hará falta.",
          DialogueId = 51009464,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB26430",
          NextDialogue = 51009465,
          SpeakNpcId = 100001,
          Subtitle = "That... won't be necessary.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51009465] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Claro que sí! No soporto a los sinvergüenzas que alteran la paz pública. Conozco a todas las caras de esta calle, dame alguna pista y lo desenmascararé.",
          DialogueId = 51009465,
          GUID = "7FB2645A",
          NextDialogue = 51009466,
          SpeakNpcId = 700313,
          Subtitle = "Sure it is! I can't stand lowlifes who disrupt public peace. I know every face on this block — just give me something to go on, and I'll smoke him out.",
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009466] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Una pista, eh...? Mire más bien esta carta. ¿Le suena de algo?",
          DialogueId = 51009466,
          GUID = "7FB26484",
          NextDialogue = 51009467,
          SpeakNpcId = 100001,
          Subtitle = "I've got this letter here... See if anything jumps out?",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009467] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Una carta? Está bien, déjame verla.",
          DialogueId = 51009467,
          GUID = "7FB264AE",
          NextDialogue = 51009468,
          SpeakNpcId = 700313,
          Subtitle = "A letter? Alright, let's take a look.",
          TalkActionId = {
            [1] = "700313:Confident_End"
          }
        },
        [51009468] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "....",
          DialogueId = 51009468,
          FinalCamera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB264D8",
          NextDialogue = 51009469,
          SpeakNpcId = 700313,
          Subtitle = "...",
          ToFinalCameraBlendTime = 1
        },
        [51009469] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "....",
          DialogueId = 51009469,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26502",
          NextDialogue = 51009470,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009470] = {
          ContentES = "... ¿Qué pasa? ¿Por qué no dices nada?",
          DialogueId = 51009470,
          GUID = "7FB2652C",
          NextDialogue = 51009471,
          SpeakNpcId = 100001,
          Subtitle = "What's with the sudden silence?"
        },
        [51009471] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No... no puede ser. Esta carta, ¡es sentida y... sincera! ¿Cómo podría ser acoso?",
          DialogueId = 51009471,
          GUID = "7FB26556",
          NextDialogue = 51009472,
          SpeakNpcId = 700313,
          Subtitle = "No... no way. This letter — it's heartfelt and... sincere! How could this be harassment?",
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009472] = {
          Camera = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Parece que he encontrado al culpable. ¿No decía usted hace un momento que iba a enseñarle modales?",
          DialogueId = 51009472,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB26580",
          NextDialogue = 51009473,
          SpeakNpcId = 100001,
          Subtitle = "Looks like we've found our guy. Weren't you just going on about giving someone a piece of your mind?"
        },
        [51009473] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Es un malentendido, tiene que ser un malentendido! ¡Juro que mis sentimientos por la señora Violetta son reales! Además, ¿no es sabido que a ella le gustan las declaraciones apasionadas? ¿Por qué va a ver esto como acoso?",
          DialogueId = 51009473,
          GUID = "7FB265AA",
          NextDialogue = 51009474,
          SpeakNpcId = 700313,
          Subtitle = "This is all a huge misunderstanding! It was all from the heart! I swear — my feelings for Ms Violetta are real! Ms Violetta adores bold declarations of love — why would she see this as anything but romantic!?"
        },
        [51009474] = {
          ContentES = "Espera un segundo... ¿me habrá engañado <H>{性别:ese Phoxcazador|esa Phoxcazadora}</>...?",
          DialogueId = 51009474,
          GUID = "7FB265D4",
          NextDialogue = 51009475,
          SpeakNpcId = 700313,
          Subtitle = "Wait a sec... was I tricked by that Phoxhunter...?"
        },
        [51009475] = {
          ContentES = "¡Ahora lo entiendo! ¡Eres tú! ¡Nunca fuiste enviada por la señora Violetta, solo quieres separarnos!",
          DialogueId = 51009475,
          GUID = "7FB265FE",
          NextDialogue = 51009476,
          SpeakNpcId = 700313,
          Subtitle = "Oh, I get it now — it's you! You're not here on Ms Violetta's behalf — you're trying to drive a wedge between us!",
          TalkActionId = {
            [1] = "700313:Angry01_Start"
          }
        },
        [51009476] = {
          ContentES = "¿Tienes alguna prueba de que ella te envió? ¡A mi parecer solo quieres sembrar la discordia!",
          DialogueId = 51009476,
          GUID = "7FB26628",
          NextDialogue = 51009477,
          SpeakNpcId = 700313,
          Subtitle = "Got any proof she sent you? I bet you're just here to stir the pot!"
        },
        [51009477] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Intentar romper el vínculo sagrado que une a señora Violetta con sus fieles admiradores? ¡Jamás! ¡Te haré arrepentirte de lo que has hecho!",
          DialogueId = 51009477,
          GUID = "7FB26652",
          NextDialogue = 51009478,
          SpeakNpcId = 700313,
          Subtitle = "Trying to poison the sacred bond between Ms Violetta and her loyal fans!? Not on my watch — I'll make you regret it!"
        },
        [51009478] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Pero qué están diciendo…?",
          DialogueId = 51009478,
          GUID = "7FB2667C",
          NextDialogue = 51009479,
          SpeakNpcId = 100001,
          Subtitle = "What's your problem...?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51009479] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Bien. Mejor calmar primero a este soldado fanático.)",
          DialogueId = 51009479,
          GUID = "7FB266A6",
          SpeakNpcId = 100001,
          Subtitle = "(Alright. Best calm this delusional man down first.)"
        },
        [51009480] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Señora Violetta... lo siento... es que yo... no fui lo suficientemente fuerte para protegerla...",
          DialogueId = 51009480,
          GUID = "7FB266D0",
          NextDialogue = 51009481,
          SpeakNpcId = 700313,
          Subtitle = "Ms Violetta... I'm sorry... I was just... not strong enough to protect you...",
          TalkActionId = {
