          }
        },
        [51009481] = {
          Camera = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Ya estáis? Mirad más bien esto.",
          DialogueId = 51009481,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "7FB266FA",
          NextDialogue = 51009482,
          SpeakNpcId = 100001,
          Subtitle = "Are you done? Here. Take a look at this.",
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "700313:Stop01_End"
          }
        },
        [51009482] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Es... es el lazo de señora Violetta? ¿El que lleva desde su primera representación, hace más de diez años...?",
          DialogueId = 51009482,
          GUID = "7FB26724",
          NextDialogue = 51009483,
          SpeakNpcId = 700313,
          Subtitle = "This... this is her ribbon. She's worn it since her debut, over ten years ago...",
          TalkActionId = {
            [1] = "700313:Shock_Start"
          }
        },
        [51009483] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Lo reconociste tan rápido?",
          DialogueId = 51009483,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB2674E",
          NextDialogue = 51009484,
          SpeakNpcId = 100001,
          Subtitle = "You recognised it that quickly?",
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51009484] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Claro que sí... ¿Por qué estoy contando todo esto, de todas maneras...?",
          DialogueId = 51009484,
          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          Subtitle = "Of course I did... Ugh. Why am I even wasting my breath?",
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          ContentES = "Si ella te dio esto... entonces supongo que no tengo oportunidad. No la molestaré más. Espero que sean felices juntos.",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313,
          Subtitle = "If she gave you this... then I guess I've got no chance. I won't bother her again. Hope you two are happy together."
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No digas más. Deja que un corazón roto llore solo en la oscuridad...",
          DialogueId = 51009486,
          GUID = "7FB267CC",
          NextDialogue = 51009487,
          SpeakNpcId = 700313,
          Subtitle = "Say no more. Let a broken heart weep alone in the dark...",
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009487] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(No dice nada más... solo sigue sollozando. Es mejor darle algo de espacio.)",
          DialogueId = 51009487,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB267F6",
          SpeakNpcId = 100001,
          Subtitle = "(He won't say another word... just keeps sobbing. Best to give him some space.)"
        },
        [51009488] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Señora Violetta, aquí estoy de nuevo.",
          DialogueId = 51009488,
          GUID = "7FB26820",
          NextDialogue = 51009489,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta — I'm back.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009489] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Gracias por tu ayuda. ¿Puedo deducir que el asunto está resuelto?",
          DialogueId = 51009489,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB2684A",
          NextDialogue = 51009490,
          SpeakNpcId = 700300,
          Subtitle = "Thank you. I take it the matter's been settled?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Talk02_Start"
          }
        },
        [51009490] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí. Ya no vendrá a molestarte. Aquí está tu lazo, dudo que hubiera salido tan bien sin él.",
          DialogueId = 51009490,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26874",
          NextDialogue = 51009491,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. He won't be bothering you again. Here's your ribbon — I doubt it would've gone so smoothly without it.",
          TalkActionId = {
            [1] = "700300:Talk02_End",
            [2] = "100001:Give"
          }
        },
        [51009491] = {
          ContentES = "He oído que lo llevas desde tus inicios... ¿hace más de diez años?",
          DialogueId = 51009491,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2689E",
          NextDialogue = 51009492,
          SpeakNpcId = 100001,
          Subtitle = "I heard you've worn this since your debut... over a decade ago?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009492] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí. Es un recuerdo de una amiga muy querida. Ella era brillante, pero el destino no fue amable con ella...",
          DialogueId = 51009492,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268C8",
          NextDialogue = 51009493,
          SpeakNpcId = 700300,
          Subtitle = "Yes. It was a keepsake from a dear friend of mine. She was brilliant, yet ill-favoured by fate...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Sigh_Start"
          }
        },
        [51009493] = {
          ContentES = "Ella nunca tuvo la oportunidad de cumplir su sueño... pero yo sí. Solo esperaba compartir el protagonismo con ella.",
          DialogueId = 51009493,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268F2",
          NextDialogue = 51009494,
          SpeakNpcId = 700300,
          Subtitle = "She never got the chance to realise her dream... but I did. I only hoped to share the spotlight with her.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009494] = {
          ContentES = "Por eso, en mi primera representación, diseñé mi propio cartel: blanco y negro, excepto por una única franja vívida de violeta.",
          DialogueId = 51009494,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2691C",
          NextDialogue = 51009495,
          SpeakNpcId = 700300,
          Subtitle = "When I debuted, I designed my own poster — black and white, save for one vivid streak of violet.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009495] = {
          ContentES = "Seguramente has oído el nombre “Violetta de los Mil Rostros”. Gracias a mis habilidades con el maquillaje, puedo convertirme en cualquiera para el escenario, adoptando un rostro diferente para cada papel que interpreto.",
          DialogueId = 51009495,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26946",
          NextDialogue = 51009496,
          SpeakNpcId = 700300,
          Subtitle = "You've likely heard the name \"Violetta of a Thousand Faces.\" With my skills in makeup, I can become anyone for the stage — taking on a different face for every role I play."
        },
        [51009496] = {
          ContentES = "Pero una cosa nunca cambia: este lazo. Lo llevo siempre. <H>Se ha convertido en mi firma</>.",
          DialogueId = 51009496,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26970",
          NextDialogue = 51009497,
          SpeakNpcId = 700300,
          Subtitle = "But one thing never changes: this ribbon. I wear it every time. It's become my signature.",
          TalkActionId = {
            [1] = "700300:Talk02_End"
          }
        },
        [51009497] = {
          Camera = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ya veo...",
          DialogueId = 51009497,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "7FB2699A",
          NextDialogue = 51009498,
          SpeakNpcId = 100001,
          Subtitle = "I see..."
        },
