            [1] = "100001:Talk02_Start"
          }
        },
        [51009504] = {
          ContentES = "Dieciséis años... ya son dieciséis años... ¿Pero por qué... por qué hacer daño a inocentes?",
          DialogueId = 51009504,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26AC0",
          NextDialogue = 51009505,
          SpeakNpcId = 700300,
          Subtitle = "I didn't realise it's been sixteen years... But why? Why hurt someone who had nothing to do with it...?",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700300:Disagree"
          }
        },
        [51009505] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Estás pálida... ¿estás bien?",
          DialogueId = 51009505,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          FinalCamera = "-143.32959,40.580566,146.557373,0.000003,-2.199983,-3.996218,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB26AEA",
          NextDialogue = 51009506,
          SpeakNpcId = 100001,
          Subtitle = "You look pale... are you alright?",
          ToFinalCameraBlendTime = 2
        },
        [51009506] = {
          ContentES = "Perdóname... fui ingenua. Pensé que podría evitar armar un escándalo, pero las cosas se han descontrolado. Tendré que recurrir a la Escolta.",
          DialogueId = 51009506,
          GUID = "7FB26B14",
          NextDialogue = 51009507,
          SpeakNpcId = 700300,
          Subtitle = "Forgive me... I was naive. I thought I could avoid causing a stir, but things have escalated beyond my control. I'll have to turn to the Escort.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009507] = {
