          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700300:Give"
          }
        },
        [51009509] = {
          ContentES = "Señora Violetta — o, ¿debería decir, señora E. R.?\nConozco todos tus sucios secretitos de los últimos dieciséis años.\nVen sola al estanque junto a la puerta lateral de Lago Helado a medianoche, o no puedo garantizar la seguridad de tu alumna.",
          DialogueId = 51009509,
          Duration = 5,
          GUID = "7FB26B92",
          Subtitle = "Violetta — or should I say, Ms E. R.\nI know all your filthy secrets from the past sixteen years.\nCome alone to the pool by Icelake's side gate at midnight, or I can't guarantee your student's safety."
        },
        [51009510] = {
