        [51009511] = {
          Camera = "-143.32959,40.580566,146.557373,0.000003,-2.199983,-3.996218,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Me temo que todas estas cartas no eran más que un señuelo. Bajé la guardia.",
          DialogueId = 51009511,
          GUID = "7FB26BE6",
          NextDialogue = 51009512,
          SpeakNpcId = 700300,
          Subtitle = "So the earlier letters were just a smokescreen. I let my guard down.",
