          GUID = "7FB27AD4",
          IsBlack = 1,
          NextDialogue = 510095121,
          Subtitle = "(The boy tugs anxiously at your sleeve.)"
        },
        [51009603] = {
          ContentES = "El tío Donat está enfermo... muy enfermo...",
          DialogueId = 51009603,
          GUID = "7FB27AFE",
          NextDialogue = 51009604,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat's sick... it's really bad...",
          TalkActionId = {
            [1] = "700303:Sigh_Start"
          }
        },
        [51009604] = {
          ContentES = "Todos dicen que eres {性别:el más fuerte de los Phoxcazadores|la más fuerte de los Phoxcazadores}... y también {性别: el más amable|la más amable}... ¡Te lo ruego... sálvalo!",
          DialogueId = 51009604,
          GUID = "7FB27B28",
          NextDialogue = 51009605,
          SpeakNpcId = 700303,
          Subtitle = "They say you're the strongest Phoxhunter — and the kindest, too... Please... I'm begging you — please help him!"
        },
        [51009605] = {
          ContentES = "¿Está enfermo? ¿Han visto a un médico?",
          DialogueId = 51009605,
          GUID = "7FB27B52",
          NextDialogue = 51009606,
          SpeakNpcId = 100001,
          Subtitle = "He's sick? Has he seen a doctor?"
        },
        [51009606] = {
