          DialogueId = 51009606,
          GUID = "7FB27B7C",
          NextDialogue = 51009607,
          SpeakNpcId = 700303,
          Subtitle = "He has... but the doctor said it's already too late...",
          TalkActionId = {
            [1] = "700303:Disagree"
          }
        },
        [51009607] = {
