        [51009610] = {
          Camera = "47.982422,-602.043945,9.373535,0.00001,7.999701,87.596718,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(El chico llama a la puerta, pero nadie responde.)",
          DialogueId = 51009610,
          GUID = "7FB27C24",
          IsBlack = 1,
          NextDialogue = 51009611,
          Subtitle = "(The boy knocks. No one answers.)"
        },
        [51009611] = {
          ContentES = "¿Eh? Qué extraño... Estaba aquí hace un momento..",
          DialogueId = 51009611,
          GUID = "7FB27C4E",
          NextDialogue = 51009612,
          SpeakNpcId = 700303,
          Subtitle = "Huh? That's weird... he was home just a minute ago...",
          TalkActionId = {
            [1] = "700303:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700303)"
          }
        },
        [51009612] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Sabes a dónde podría haber ido?",
          DialogueId = 51009612,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB27C78",
          NextDialogue = 51009613,
          SpeakNpcId = 100001,
          Subtitle = "Any idea where he might've gone?",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700303:Sigh_End"
          },
          TurnTo = {
            [1] = "700303:n(100001)"
          }
        },
        [51009613] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eh… ¡oh sí!",
          DialogueId = 51009613,
          GUID = "7FB27CA2",
          NextDialogue = 51009614,
          SpeakNpcId = 700303,
          Subtitle = "Umm... oh! Right!",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700303:Think_Start"
          }
        },
        [51009614] = {
          ContentES = "Creo que decía a menudo que quería volver a ver “la Mina”. Algo así como... Glem... Glum...?",
          DialogueId = 51009614,
          GUID = "7FB27CCC",
          NextDialogue = 51009615,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat kept saying he wanted to go back to \"the pit\"... Something like Glen... or Glum, I think?"
        },
        [51009615] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Mina de Glevum?",
          DialogueId = 51009615,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB27CF6",
          NextDialogue = 51009616,
          SpeakNpcId = 100001,
          Subtitle = "Glevum Pit?",
          TalkActionId = {
            [1] = "700303:Think_End",
            [2] = "100001:Talk02_Start"
          }
        },
        [51009616] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Sí, eso es! ¿Vas a ir? ¡Déjame ir contigo!",
          DialogueId = 51009616,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27D20",
          NextDialogue = 51009617,
          SpeakNpcId = 700303,
          Subtitle = "Yeah, that's it! Are you going there, {性别:sir|miss}? Can I come too?",
          TalkActionId = {
            [1] = "700303:Explain02_Start"
          }
        },
        [51009617] = {
          ContentES = "Está muy enfermo... y tengo miedo de que—",
          DialogueId = 51009617,
          GUID = "7FB27D4A",
          NextDialogue = 51009618,
          SpeakNpcId = 700303,
          Subtitle = "He's really sick... and I'm worried that—"
        },
        [51009618] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es demasiado peligroso para un chico. No puedo llevarte allí. Pero te prometo que si lo encuentro, lo traeré de vuelta aquí. Espérame, por favor.",
          DialogueId = 51009618,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB27D74",
          NextDialogue = 51009619,
          SpeakNpcId = 100001,
          Subtitle = "It's a very dangerous place. I can't take a kid with me. But I promise — if I find him, I'll bring him back. Just wait here.",
          TalkActionId = {
            [1] = "700303:Explain02_End",
            [2] = "100001:Disagree"
          }
        },
        [51009619] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Está bien... Gracias. De verdad.",
          DialogueId = 51009619,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27D9E",
          NextDialogue = 51009620,
          SpeakNpcId = 700303,
          Subtitle = "Okay... Thank you. Really."
        },
        [51009620] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ahora, dime sobre Donat.",
          DialogueId = 51009620,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB27DC8",
          NextDialogue = 51009621,
          SpeakNpcId = 100001,
          Subtitle = "Now, tell me about Donat.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009621] = {
          Camera = "231.359863,-211.90625,128.92334,0.000026,-9.600595,128.990936,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Es el más bondadoso de todo Lago Helado!",
          DialogueId = 51009621,
          GUID = "7FB27DF2",
          NextDialogue = 51009622,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat's the kindest person in all of Icelake! ",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700303:Confident_Start"
          }
        },
        [51009622] = {
          ContentES = "Comparte su comida con nosotros, compra ropa y libros para los niños de Zona Nebulosa con su propio dinero.",
          DialogueId = 51009622,
          GUID = "7FB27E1C",
          NextDialogue = 51009623,
          SpeakNpcId = 700303,
          Subtitle = "He shares food with us, buys clothes and books for the kids in Mist Aken with his own money."
        },
        [51009623] = {
          ContentES = "Repara casas y muebles, lleva medicinas a los enfermos y ofrece refugio a los mendigos durante las tormentas de nieve... Casi todo el mundo aquí le debe algo.",
          DialogueId = 51009623,
          GUID = "7FB27E46",
          NextDialogue = 51009624,
          SpeakNpcId = 700303,
          Subtitle = "He fixes homes and furniture, brings medicine to the sick, even takes in beggars when the snow gets bad... Almost everyone in the slums owes him something."
        },
        [51009624] = {
          ContentES = "Y además, y además—",
          DialogueId = 51009624,
          GUID = "7FB27E70",
          NextDialogue = 51009625,
          SpeakNpcId = 700303,
          Subtitle = "And, and—"
        },
        [51009625] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...Eh, quería decir: ¿cómo es físicamente?",
          DialogueId = 51009625,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB27E9A",
          NextDialogue = 51009626,
          SpeakNpcId = 100001,
          Subtitle = "...Er, I meant, what does he look like?",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51009626] = {
          Camera = "47.982422,-602.043945,9.373535,0.00001,7.999701,87.596718,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? Oh... ¡perdón!",
          DialogueId = 51009626,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27EC4",
          NextDialogue = 51009627,
          SpeakNpcId = 700303,
          Subtitle = "Huh? Oh... sorry!",
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "700303:Explain02_Start"
          }
        },
        [51009627] = {
          ContentES = "Tiene algo más de cuarenta años, el pelo castaño, es bastante alto y delgado... y su ropa está muy gastada.",
          DialogueId = 51009627,
          GUID = "7FB27EEE",
          NextDialogue = 51009628,
          SpeakNpcId = 700303,
          Subtitle = "He's in his early forties, tall, skinny, brown hair... his clothes are pretty worn..."
        },
        [51009628] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Muy bien, Entendido..",
          DialogueId = 51009628,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB27F18",
          SpeakNpcId = 100001,
          Subtitle = "Got it.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51009629] = {
          ContentES = "*Cof, cof*",
          DialogueId = 51009629,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB27F42",
          NextOptions = {
            [1] = 51009630
          },
          SpeakNpcId = 700301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "*cough*"
        },
        [51009630] = {
          ContentES = "Perdón...",
          DialogueId = 51009630,
          GUID = "7FB27F6C",
          NextDialogue = 510095401,
          Subtitle = "Excuse me..."
        },
        [51009631] = {
          ContentES = "¿Eres Donat?",
          DialogueId = 51009631,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB27F96",
          NextDialogue = 51009632,
          SpeakNpcId = 100001,
          Subtitle = "Are you Donat?",
          TalkActionId = {
            [1] = "700301:Explain01_End"
          }
        },
        [51009632] = {
          ContentES = "¿Y tú, quién eres...?",
          DialogueId = 51009632,
          GUID = "7FB27FC0",
          NextDialogue = 51009633,
          SpeakNpcId = 700301,
          Subtitle = "You are...?"
        },
        [51009633] = {
          ContentES = "Un chico me pidió que viniera a buscarte.",
          DialogueId = 51009633,
          GUID = "7FB27FEA",
          NextDialogue = 51009634,
          SpeakNpcId = 100001,
          Subtitle = "A child asked me to find you."
        },
        [51009634] = {
          ContentES = "Ah... Lars, imagino. Ese chico siempre se preocupa demasiado.",
          DialogueId = 51009634,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28014",
          NextDialogue = 51009635,
          SpeakNpcId = 700301,
          Subtitle = "Ah... Lars, was it? That boy's a worrier.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009635] = {
          ContentES = "Solo quería ver este lugar nuevamente... Antes, los monstruos lo infestaban y no se podía acercar.",
          DialogueId = 51009635,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB2803E",
          NextDialogue = 51009636,
          SpeakNpcId = 700301,
          Subtitle = "I just... wanted to revisit this old pit. I remember it swarming with monsters — no way to get near."
        },
        [51009636] = {
          ContentES = "Pero escuché que {性别:un Phoxcazador muy talentoso|una Phoxcazadora muy talentosa} los había eliminado... Así que aproveché la oportunidad para regresar.",
          DialogueId = 51009636,
          GUID = "7FB28068",
          NextOptions = {
            [1] = 510096361,
            [2] = 510096362
          },
          SpeakNpcId = 700301,
          Subtitle = "Then I heard a skilled Phoxhunter had cleared them out, so... I figured it was safe enough to come back.",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009637] = {
          ContentES = "¿De verdad...? Te lo agradezco — *cof, cof*.",
          DialogueId = 51009637,
          GUID = "7FB28092",
          NextDialogue = 51009638,
          SpeakNpcId = 700301,
          Subtitle = "Is that so...? Thank you, truly—*cough*"
        },
        [51009638] = {
          ContentES = "Lo siento... Tengo que ir un poco más lejos. Gracias por haber venido hasta aquí, pero dile a Lars que todo está bien. Dejaré tu recompensa en el Asfódelo más tarde. *Cof*...",
          DialogueId = 51009638,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB280BC",
          NextDialogue = 51009639,
          SpeakNpcId = 700301,
          Subtitle = "Sorry... I need to press on a bit further in. Thank you for coming all this way. Please tell Lars I'm okay. I'll leave your reward for the commission at The Asphodel later... *cough*"
        },
        [51009639] = {
          ContentES = "Solo he eliminado a los más grandes de los Filthoids. Podría quedar alguno. En tu estado, no deberías avanzar sola. ¿A dónde quieres ir? Te acompañaré.",
          DialogueId = 51009639,
          GUID = "7FB280E6",
          NextDialogue = 51009640,
          SpeakNpcId = 100001,
          Subtitle = "I've only taken care of the largest one. There might still be Filthoids inside. You're not in any shape to explore alone. Where were you headed? Let me walk with you."
        },
        [51009640] = {
          ContentES = "¿Tú... harías eso?",
          DialogueId = 51009640,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28110",
          NextDialogue = 51009641,
          SpeakNpcId = 700301,
          Subtitle = "You'd... do that?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009641] = {
          ContentES = "Sí. Le prometí a Lars que te traería sano y salvo.",
          DialogueId = 51009641,
          GUID = "7FB2813A",
          NextDialogue = 51009642,
          SpeakNpcId = 100001,
          Subtitle = "I promised Lars I'd bring you home safely."
        },
        [51009642] = {
          ContentES = "Gracias... gracias, joven {性别:amigo|amiga}.",
          DialogueId = 51009642,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28164",
          SpeakNpcId = 700301,
          Subtitle = "Thank you... thank you, kind soul.",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009643] = {
          Camera = "-375.460938,260.694336,170.375488,0.000148,-11.001406,-38.598434,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Gracias, {性别:jovencito|jovencita}...",
          DialogueId = 51009643,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB2818E",
          NextDialogue = 51009644,
          SpeakNpcId = 700301,
          Subtitle = "Thank you, young one...",
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009644] = {
          Camera = "704.804688,1549.59082,762.798828,0.000162,-10.801759,-103.40123,25.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Está aún más deteriorado de lo que recordaba...",
          DialogueId = 51009644,
          FinalCamera = "704.804688,1549.59082,762.798828,0.000163,-10.801759,-103.401352,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB281B8",
          NextDialogue = 51009645,
          SpeakNpcId = 700301,
          Subtitle = "It's even more run-down than I'd imagined...",
          ToFinalCameraBlendTime = 5
        },
        [51009645] = {
          Camera = "949.248047,585.90332,736.995117,0.000167,0.198089,-138.598633,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "La puerta principal está cerrada con llave. Afortunadamente, aún podemos pasar por este tubo...",
          DialogueId = 51009645,
          GUID = "7FB281E2",
          SpeakNpcId = 700301,
          Subtitle = "Main gate's locked, too. Good thing this pipe still lets us through..."
        },
        [51009646] = {
          ContentES = "*Cof, cof, cof* ...",
          DialogueId = 51009646,
          GUID = "7FB2820C",
          NextDialogue = 51009647,
          SpeakNpcId = 700301,
          Subtitle = "*cough* *cough* *cough*..."
        },
        [51009647] = {
          ContentES = "¿Estás bien?",
          DialogueId = 51009647,
          GUID = "7FB28236",
          NextDialogue = 51009648,
          SpeakNpcId = 100001,
          Subtitle = "You alright?"
        },
        [51009648] = {
          ContentES = "Yo... *cof, cof*, estoy bien... Continuemos. El lugar que busco está cerca.",
          DialogueId = 51009648,
          GUID = "7FB28260",
          NextDialogue = 51009649,
          SpeakNpcId = 700301,
          Subtitle = "I'm f—*cough*—fine... Let's keep moving. The place I'm looking for is just ahead."
        },
        [51009649] = {
          ContentES = "Pareces conocer bien el lugar.",
          DialogueId = 51009649,
          GUID = "7FB2828A",
          NextDialogue = 51009650,
          SpeakNpcId = 100001,
          Subtitle = "You seem to know this place well."
        },
        [51009650] = {
          ContentES = "Sí... Fui minero aquí. Hace dieciséis años, caminaba por este camino todos los días.",
          DialogueId = 51009650,
          GUID = "7FB282B4",
          NextDialogue = 51009651,
          SpeakNpcId = 700301,
          Subtitle = "I do... I used to be a miner here. Sixteen years ago, I walked this path every day."
        },
        [51009651] = {
          ContentES = "Pasábamos diez, doce horas al día allí abajo... Conocía cada rincón de memoria, incluso con los ojos cerrados.",
          DialogueId = 51009651,
          GUID = "7FB282DE",
          SpeakNpcId = 700301,
          Subtitle = "Back then, we'd spend ten, twelve hours down here... I knew every turn — even with my eyes closed."
        },
        [51009652] = {
          ContentES = "Vaya... Hay Filthoids por todas partes...",
          DialogueId = 51009652,
          GUID = "7FB28308",
          SpeakNpcId = 700301,
          Subtitle = "Darn it... it's surrounded by Filthoids..."
        },
        [51009653] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Afortunadamente... No ha sido dañada. Gracias, de verdad.",
          DialogueId = 51009653,
          GUID = "7FB28332",
          NextDialogue = 51009654,
          SpeakNpcId = 700301,
          Subtitle = "Thank goodness... It's still intact. Thank you, truly."
        },
        [51009654] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sig... mi viejo amigo. He venido a verte...",
          DialogueId = 51009654,
          FinalCamera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2835C",
          NextDialogue = 51009655,
          SpeakNpcId = 700301,
          Subtitle = "Sig... my old friend. I've come to see you...",
          ToFinalCameraBlendTime = 5
        },
        [51009655] = {
          ContentES = "¿Es... una tumba?",
          DialogueId = 51009655,
          GUID = "7FB28386",
          NextDialogue = 51009656,
          SpeakNpcId = 100001,
          Subtitle = "Is this... a grave?"
        },
        [51009656] = {
          ContentES = "Parece un triste montón de piedras, ¿verdad?",
          DialogueId = 51009656,
          GUID = "7FB283B0",
          NextDialogue = 51009657,
          SpeakNpcId = 700301,
          Subtitle = "Doesn't look like much, does it?"
        },
        [51009657] = {
          Camera = "391.647461,354.068359,51.502441,0.000019,-5.200888,-159.003296,40.0,565.324158,false,Manual,2.8",
          ContentES = "Él decía que yo era su mejor amigo... y lo único que pude ofrecerle fue este pequeño pedazo de tierra miserable.",
          DialogueId = 51009657,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB283DA",
          NextDialogue = 51009658,
          SpeakNpcId = 700301,
          Subtitle = "He called me his best mate... and this — this sorry little spot — is all I could manage for him.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009658] = {
          ContentES = "Espera... esto es... No... ¿Por qué...?",
          DialogueId = 51009658,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28404",
          NextDialogue = 51009659,
          SpeakNpcId = 700301,
          Subtitle = "Wait... is that—!? No... Why...?",
          TalkActionId = {
            [1] = "700301:Shock_Start"
          }
        },
        [51009659] = {
          ContentES = "(El rostro de Donat, pálido unos momentos antes, se tensa de repente. Sus venas sobresalen, su mirada llena de sorpresa y dolor. Sigues su mirada y ves, apoyado contra la lápida, una cinta violeta.)",
          DialogueId = 51009659,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2842E",
          NextDialogue = 51009660,
          Subtitle = "(The sick man's face — ashen moments ago — suddenly stiffens, veins standing taut beneath his skin, his eyes locked in shock and disbelief. Following his gaze, you spot it: a violet ribbon, lying untouched beside the gravestone.)"
        },
        [51009660] = {
          Camera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Violet... ¿por qué has regresado?",
          DialogueId = 51009660,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28458",
          NextDialogue = 51009661,
          SpeakNpcId = 700301,
          Subtitle = "Violet... why have you come back?",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700301)"
          }
        },
        [51009661] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Violet...? ¿Quién es?",
          DialogueId = 51009661,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28482",
          NextDialogue = 51009662,
          SpeakNpcId = 100001,
          Subtitle = "Violet? Who's that?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah... ¿Te importaría hacerle un favor a un viejo por un momento? Tengo algunas historias antiguas que contar.",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          Subtitle = "Ah... would you humour an old man for a moment? I've a few old stories to tell.",
          TalkActionId = {
            [1] = "700301:Sigh_End",
            [2] = "100001:Talk02_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009663] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Con gusto. Pero volvamos primero, ¿de acuerdo? Lars aún debe de estar preocupado.",
          DialogueId = 51009663,
          GUID = "7FB284D6",
          NextDialogue = 51009664,
          SpeakNpcId = 100001,
          Subtitle = "I'd love to. But let's head back first, alright? Lars must be worried sick."
        },
        [51009664] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí... sí, tienes razón. Vamos.",
          DialogueId = 51009664,
          GUID = "7FB28500",
          SpeakNpcId = 700301,
          Subtitle = "Yes... yes, you're right. Let's go.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009665] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Tío Donat, por fin has vuelto!",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat — you're back!",
          TurnTo = {
            [1] = "700303:n(700301)",
            [2] = "700301:n(700303)",
            [3] = "100001:n(700303)"
          }
        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Lo siento, pequeño... Te he preocupado otra vez — *cof*",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          Subtitle = "Sorry, lad... made you worry again — *cough*",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Todavía estás tosiendo! Ven, te llevaré al médico.",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          Subtitle = "You're coughing again! Come on — let me take you to a doctor.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No... no hace falta... Es mi castigo. Nada podrá curarlo.",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          Subtitle = "No, no need... This is what I deserve. No cure's going to fix it.",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No digas eso, tío Donat...",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          Subtitle = "Don't say that, Uncle Donat...",
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          ContentES = "¿Recuerdas? Aquel invierno especialmente frío, cuando tenía que dormir junto a los conductos de ventilación de la fábrica para no congelarme... Tú también temblabas de frío, pero me diste tu único abrigo.",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303,
          Subtitle = "Remember that winter, when I had to sleep next to the factory vents just to stay warm? You were freezing too — and still gave me the only padded coat you had."
        },
        [51009671] = {
          ContentES = "¡Todo el mundo en la calle sabe lo buena persona que eres! ¿Por qué sigues repitiendo que mereces lo que te pasa? ¡No es verdad!",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303,
          Subtitle = "Everyone round here knows what a good person you are! So why do you keep saying you deserve this? It's just not true!"
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "... ¿Tiene esto algo que ver con las “viejas historias” de las que querías hablarme?",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          Subtitle = "...Does this have to do with the \"old stories\" you wanted to tell?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí... Todo empezó hace dieciséis años.",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          Subtitle = "Mm. Sixteen years back...",
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Como muchos capítulos aburridos de mi vida, mis años como minero no fueron los peores, pero tampoco fueron nada gloriosos. Días largos hasta el agotamiento, apenas lo necesario para poner pan en la mesa.",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301,
          Subtitle = "Like every other dreary chapter of my life, the years I spent as a miner weren't good, but they weren't the worst either. Long days of grind, just enough to wear you down, just enough to put bread on the table."
        },
        [51009675] = {
          ContentES = "Cuando lo pienso... Aunque los grandes jefes nunca nos trataron con justicia, tal vez fueron los días más tranquilos de mi vida...",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301,
          Subtitle = "Looking back... even though the bigwigs never treated us fairly, those might've been the least troubled days I ever had..."
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero mi amigo Sig, él no tuvo esa suerte. Su hermana Violet, su única familia se enfermó. Tenía solo dieciocho años.",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301,
          Subtitle = "But my friend Sig... he wasn't so lucky. His little sister, Violet — the only family he had — fell ill. Only eighteen, that girl..."
        },
        [51009677] = {
          ContentES = "Y cuando crees que las cosas no pueden empeorar... siempre lo hacen.",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301,
          Subtitle = "And just when you think things can't get worse... they usually do."
        },
        [51009678] = {
          ContentES = "El Phoxene de la Mina de Glevum se volvía más escaso día tras día y nuestros salarios también. El pan blanco se convirtió en pan manchado de polvo... luego incluso eso se mezcló con salvado y aserrín.",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301,
          Subtitle = "Phoxene from Glevum Pit grew scarcer by the day — and so did our wages. White bread became dust-stained bread... then even that was bulked with husks and sawdust."
        },
        [51009679] = {
          ContentES = "Para Sig, que ya vivía al día, la enfermedad de Violet sonaba como una sentencia de muerte.",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          Subtitle = "For Sig — barely making ends meet — Violet falling ill was like hearing her death sentence out loud.",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          ContentES = "Todavía recuerdo ese amanecer. Sig había conseguido alcohol barato de los obreros, y estábamos sentados sobre las piedras frente a la Mina, bebiendo botella tras botella.",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          Subtitle = "I still remember that dawn. Sig scrounged up cheap liquor from the lads, and we sat on the stone outside the pit, knocking them back one bottle at a time.",
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          ContentES = "Lloraba como un niño, contando cómo siempre se habían apoyado el uno al otro. A veces tarareaba las canciones favoritas de Violet... otras veces maldecía en voz baja a Fabrice Ruthford.",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301,
          Subtitle = "He cried like a child, rambling on about how the two of them had always relied on each other. One moment he was softly humming her favourite songs... the next, muttering curses at Fabrice Ruthford through gritted teeth."
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Fabrice Ruthford? ¿Quién es?",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          Subtitle = "Who's that?",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "El encargado de la Mina de Glevum, un alto mando de la Academia Aeolipile.",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          Subtitle = "An officer at The Aeolipile, the one who ran Glevum Pit back then.",
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          ContentES = "Le di una palmada en el hombro y dije: “¿De qué sirve maldecirlo? No somos más que unos don nadies. Si tienes valor, ¿por qué no lo secuestras y le quitas el dinero tú mismo?”",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          Subtitle = "I remember clapping him on the shoulder and saying, \"What good does cursing him do? We're just nobodies. If you've got guts, why not grab the man himself and get the money straight from his pocket?\"",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          ContentES = "... Han pasado dieciséis años, y siempre me pregunto: si no me hubiera emborrachado ese día, si no hubiera soltado semejantes tonterías... ¿habría pasado todo esto?",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          Subtitle = "...Sixteen years on, I still ask myself — if I hadn't been drunk and mouthing off like that, would any of this have happened?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Quieres decir... que Sig realmente lo hizo?",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          Subtitle = "You mean... Sig actually did it?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí. Un día se marchó de la Mina sin avisar. Cuando fui a su casa, había desaparecido... y Violet también.",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          Subtitle = "Yes. One day, he quit the mine without a word. When I went to his house to check on him, both he and Violet were gone.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          ContentES = "Al principio, pensé que la había llevado a otro lugar para curarla... Hasta que una semana después, recibí una carta de Violet.",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301,
          Subtitle = "I thought he'd taken her elsewhere for treatment... until a week later, I received a letter from Violet."
        },
        [51009689] = {
          ContentES = "Sig y yo éramos cercanos, pero apenas conocía a su hermana, siempre estaba postrada en la cama. Había gastado sus últimas monedas para que un Phoxcazador de paso entregara la carta a la mina.",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301,
          Subtitle = "Sig and I were close back then, but I hardly knew his sister. She was always bedridden. She spent her last coins getting that letter delivered to the mine via a passing Phoxhunter."
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "En esa carta, explicaba que Sig había secuestrado a la hija del oficial para pedir un rescate. Me suplicaba que lo detuviera antes de que fuera demasiado tarde.",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301,
          Subtitle = "She said Sig had kidnapped Officer Ruthford's daughter, demanding ransom. She begged me to stop him before it was too late."
        },
        [51009691] = {
          ContentES = "La mantenía en una vieja casa en las afueras de la ciudad. Cuando lo encontré, estaba en shock... pero lo admitió todo.",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301,
          Subtitle = "He was holding the girl in an old house on the outskirts. When I found him, he was stunned... but he owned up to it."
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sabía que eran mis palabras las que habían abierto la puerta a esa locura. Estaba consumido por la culpa. Quería detenerlo de verdad, pero al ver a Violet, tan débil que no podía hablar... dudé.",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301,
          Subtitle = "My drunken rant that night opened a door to a nightmare. I was consumed by regret. I wanted to stop him — I truly did... but when I saw Violet, so frail she could barely speak... I hesitated."
        },
        [51009693] = {
          ContentES = "Sig me suplicó que fingiera que nada había pasado. Pero la investigación se estrechaba... y el miedo... el miedo me sacudió hasta los huesos.",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301,
          Subtitle = "He begged me to pretend nothing had happened. But the investigation was tightening... and the fear... it shook me to my bones."
        },
        [51009694] = {
          ContentES = "Al final... yo—",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301,
          Subtitle = "In the end... I—"
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Los... denunciaron?",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          Subtitle = "You... turned them in?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No debí... nunca debí...",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          Subtitle = "I shouldn't have... I never should have!",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Y después? ¿Qué les pasó?",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          Subtitle = "What happened after that?",
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "El oficial vino en persona a dirigir el arresto. Sig resistió... y accidentalmente prendió fuego a la casa.",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          Subtitle = "The officer came himself, leading the arrest. During the struggle, Sig accidentally set the house on fire.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          ContentES = "Entré corriendo para rescatarlos... pero en la confusión solo logré sacar a Violet de allí. Su rostro estaba ennegrecido por el hollín... solo dos surcos pálidos marcaban sus mejillas por las lágrimas.",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301,
          Subtitle = "I rushed in, trying to save them — but in the chaos, I only managed to get Violet out. Her face was black with soot... only her tears had carved two pale trails down her cheeks."
        },
        [51009700] = {
          ContentES = "Temía que la consideraran cómplice. Así que la escondí en un barril de agua, con la esperanza de que la Legión no la encontrara.",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301,
          Subtitle = "I was terrified she'd be punished for her brother's crime. So I hid her in a water barrel, hoping the Legion wouldn't find her."
        },
        [51009701] = {
          ContentES = "Sig fue arrestado. En cuanto a la hija del oficial... sólo quedó su cuerpo calcinado entre los escombros.",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301,
          Subtitle = "In the end, Sig was caught. And the officer's daughter... all they found was her charred remains in the rubble."
        },
        [51009702] = {
          ContentES = "Loco de rabia, el oficial ignoró todo procedimiento judicial. Ejecutó a Sig con sus propias manos. En cuanto a Violet... le entregué toda la recompensa y la saqué de Lago Helado en secreto, rezando para que pudiera alejarse de todo esto.",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301,
          Subtitle = "The officer was enraged. He didn't even wait for a trial — he executed Sig with his own hands. As for Violet... I gave her all the bounty money and smuggled her out of Icelake, praying she'd get away from all this."
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Aún recuerdo su rostro en el momento de la partida, marcado por la enfermedad, pero ardiendo de ira. Aquel día llevaba esa cinta violeta...",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301,
          Subtitle = "I still remember her face when she left — worn thin by sickness, but her eyes were burning with fury. She was wearing this violet ribbon that day..."
        },
        [51009704] = {
          ContentES = "Dijo que abandonaría Lago Helado para siempre. Que no quería volver a verme jamás.",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301,
          Subtitle = "She said she'd leave Icelake for good. Said she never wanted to see me again."
        },
        [51009705] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Y cómo culparla? Yo era el borracho que empujó a un amigo al crimen, y el cobarde cuyo miedo costó dos vidas. ¿Quién querría volver a ver a un hombre así?",
          DialogueId = 51009705,
          FinalCamera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28BBA",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextOptions = {
            [1] = 510095461,
            [2] = 510095462
          },
          SpeakNpcId = 700301,
          Subtitle = "And who could blame her? I was the drunk who doomed a friend and the coward whose fear cost two innocent lives. Why would anyone want to see me again?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009706] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tienes razón.",
          DialogueId = 51009706,
          GUID = "7FB28BE4",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          Subtitle = "You're right.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009707] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Es verdad, tío Donat, solo hiciste lo que creías correcto!",
          DialogueId = 51009707,
          GUID = "7FB28C0E",
          NextDialogue = 51009708,
          SpeakNpcId = 700303,
          Subtitle = "Yeah! You just did what you thought was right, Uncle Donat!",
          TalkActionId = {
            [1] = "700303:Angry01_Start"
          }
        },
        [51009708] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eso es lo que todos me dicen... Pero no cambia nada: dos vidas inocentes se perdieron por mi culpa.",
          DialogueId = 51009708,
          GUID = "7FB28C38",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          Subtitle = "That's what they all say. But it doesn't change the fact that two innocent lives were gone because of me.",
          TalkActionId = {
            [1] = "700301:Disagree",
            [2] = "700303:Angry01_End"
          }
        },
        [51009709] = {
          ContentES = "Caí gravemente enfermo. Desde entonces, no he dejado de ayudar a los demás. Me dije que con cada buena acción, expiaba un poco más mis faltas.",
          DialogueId = 51009709,
          GUID = "7FB28C62",
          NextDialogue = 51009710,
          SpeakNpcId = 700301,
          Subtitle = "After that, I got really sick. Then I started doing what I could to help others, trying to make things right. I thought... maybe each good deed could chip away at my sins.",
          TalkActionId = {
            [1] = "700301:Explain01_Start"
          }
        },
        [51009710] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero aún veo a Sig en mis pesadillas, mirándome con sus ojos llenos de odio. Todavía escucho a la pobre Enola gritar entre las llamas. Dicen que ninguna bondad hacia los vivos puede obtener el perdón de los muertos.",
          DialogueId = 51009710,
          GUID = "7FB28C8C",
          NextDialogue = 51009711,
          SpeakNpcId = 700301,
          Subtitle = "But still... I see Sig in my dreams, glaring at me in rage. I hear poor Enola screaming as the fire takes her. They say no kindness to the living will ever buy forgiveness from the dead."
        },
        [51009711] = {
          ContentES = "Ah... Violet... ¿Es por eso que has vuelto a Lago Helado? ¿Porque, al igual que yo, no puedes perdonarme?",
          DialogueId = 51009711,
          GUID = "7FB28CB6",
          NextDialogue = 51009712,
          SpeakNpcId = 700301,
          Subtitle = "Violet... is that why you came back to Icelake? Because you still can't forgive me... just like I never could?",
          TalkActionId = {
            [1] = "700301:Disagree"
          }
        },
        [51009712] = {
          ContentES = "¿Has venido... para liberarme de mi carga...?",
          DialogueId = 51009712,
          GUID = "7FB28CE0",
          SpeakNpcId = 700301,
          Subtitle = "Have you come to put me out of my misery...?",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009713] = {
          ContentES = "(Su voz se apaga poco a poco. Se derrumba.)",
          DialogueId = 51009713,
          GUID = "7FB28D0A",
          Subtitle = "(His voice trails off. He collapses.)"
        },
        [51009714] = {
          Camera = "564.476807,-378.041016,169.732422,0.00009,-13.999387,141.803299,30.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿¡Tío Donat!? ¡Respóndeme!",
          DialogueId = 51009714,
          GUID = "7FB28D34",
          NextDialogue = 51009715,
          Scripts = [[
PARA{
SEQ{
TurnTo{TurnToDescription{"700303:n(700301)"}},
PlayAnimation{ActorId{700303},AnimationId{"Angry01_Start"},Duration{1}}
},
SEQ{
TurnTo{TurnToDescription{"100001:n(700301)"}},
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}}
}
}]],
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat!? Are you alright!?",
          TalkActionId = {
            [1] = "700301:Onground02"
          }
        },
        [51009715] = {
          ContentES = "Uf... Está bien. Parece que solo se desmayó por agotamiento y estrés. Quédate cerca de él, no dejes que se aleje de nuevo.",
          DialogueId = 51009715,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB28D5E",
          LookAt = {
            [1] = "700303:n(100001)"
          },
          NextDialogue = 51009716,
          SpeakNpcId = 100001,
          Subtitle = "Whew... he's fine. Looks like he just fainted from exhaustion and stress. Keep an eye on him — don't let him wander off again.",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700303:Angry01_End"
          }
        },
        [51009716] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí... Avisaré a todos, nos encargaremos de él juntos.",
          DialogueId = 51009716,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28D88",
          NextDialogue = 51009717,
          SpeakNpcId = 700303,
          Subtitle = "Mm. I'll get the others — we'll take care of him together.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          },
          TurnTo = {
            [1] = "100001:n(700303)"
          }
        },
        [51009717] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Um... ¿puedo preguntarte algo, {性别:señor|señora}?",
          DialogueId = 51009717,
          GUID = "7FB28DB2",
          NextDialogue = 51009718,
          SpeakNpcId = 700303,
          Subtitle = "Um... can I ask you something, {性别:sir|miss}?",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          },
          TurnTo = {
            [1] = "700303:n(100001)"
          }
        },
        [51009718] = {
          Camera = "-204.549316,-144.984375,111.20166,0.000049,-3.59994,24.790976,40.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Qué pasa?",
          DialogueId = 51009718,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28DDC",
          NextDialogue = 51009719,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009719] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Crees que... el tío Donat es una mala persona?",
          DialogueId = 51009719,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28E06",
          NextOptions = {
            [1] = 510096291,
            [2] = 510096292,
            [3] = 510096293,
            [4] = 510096294
          },
          SpeakNpcId = 700303,
          Subtitle = "Do you think... Uncle Donat is a bad person?",
          TalkActionId = {
            [1] = "700303:Explain02_Start"
          }
        },
        [51009720] = {
          Camera = "174.810547,-35.033203,84.850098,0.000033,-4.400117,168.992874,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que eso es lo que piensas... Entiendo. Gracias, {性别:señor|señora}. Aquí, toma esto, ¡me costó mucho tiempo ahorrar este dinero!",
          DialogueId = 51009720,
          GUID = "7FB28E30",
          NextDialogue = 51009721,
          SpeakNpcId = 700303,
          Subtitle = "So that's what you think... I see. Thank you, {性别:sir|miss}! This is for you — I saved it up for a long time!",
          TalkActionId = {
            [1] = "700303:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51009721] = {
          Camera = "34.74585,-46.004883,96.84375,0.000042,-1.400134,16.193537,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Esta cinta violeta... seguramente la dejó Violet en la tumba de Sig.)",
          DialogueId = 51009721,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28E5A",
          NextDialogue = 51009722,
          SpeakNpcId = 100001,
          Subtitle = "(That violet ribbon... it must've been left by Violet at Sig's grave.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009722] = {
          ContentES = "(Dieciséis años... ahora tendría unos treinta. ¿Realmente ha regresado? Tal vez debería preguntar cuando tenga la oportunidad.)",
          DialogueId = 51009722,
          GUID = "7FB28E84",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 100001,
          Subtitle = "(Sixteen years... she'd be in her thirties by now. Has she really returned? Maybe I should ask around when I get the chance.)"
        },
        [51009723] = {
          Camera = "-1245.721924,-374.627869,402.247803,-8.001631,-17.80077,20.798534,23.337744,100000.0,false,DoNotOverride,2.8",
          ContentES = "Otra noche sin descanso... ¡imposible encontrar la paz!",
          DialogueId = 51009723,
          FinalCamera = "-1026.618896,-291.636963,327.767822,-8.001973,-14.000665,19.198555,23.337744,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28EAE",
          NextDialogue = 51009724,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023200"}},
PlayFacial{ActorId{100001},FacialId{"Angry01"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Another restless night... no peace for the weary!",
          ToFinalCameraBlendTime = 3
        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentES = "Oh, pobre alma... ¿eres como yo? Vagando por estos pasillos helados, mirando hacia el horizonte, buscando el brillo de una estrella nacida del amor y la esperanza...",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O, wretched soul — do you too wander these icy halls, chasing the distant gleam, yearning for love and a starlit dream?"
        },
        [51009725] = {
          ContentES = "(Oyes una voz cantando en la esquina de una calle. Miras a tu alrededor, pero no hay nadie. ¿Quieres seguir buscando?)",
          DialogueId = 51009725,
          GUID = "7FB28F02",
          Subtitle = "(From a quiet street corner, you hear a melodic voice — but there's no one in sight. Should you keep looking?)"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentES = "Da... da da...",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Da... Da da...",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          ContentES = "¿Quién anda ahí?",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001,
          Subtitle = "Who's there!?"
        },
        [51009728] = {
          ContentES = "Oh, perdón... ¿te asusté? Estoy aquí, a cinco pasos delante de ti. Sí, por aquí.",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh — pardon me. I didn't mean to startle you. I'm right here — five steps ahead. Yes, just here.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentES = "Buenas noches a ti, alma desvelada.",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023201"}},
TurnTo{TurnToDescription{"100001:n(700309)"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A good evening to you, sleepless one."
        },
        [51009730] = {
          ContentES = "No, no estás soñando. Soy yo quien te habla.",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "It's not just you. I really am talking."
        },
        [51009731] = {
          ContentES = "¿Tiene que haber necesariamente alguien escondido dentro? ¿Acaso una caja no puede simplemente... hablar?",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "Must there be someone hiding inside? Can't a crate simply... talk?"
        },
        [51009732] = {
          ContentES = "Lo siento, soy solo una simple caja antigua. No concedo deseos.",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "Sorry — I'm just a plain old crate. I don't grant wishes."
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero... ¿cómo puede hablar una caja?",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          Subtitle = "But... how can a crate talk?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentES = "Dime... ¿qué crees que es más difícil: cantar o hablar?",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309,
          Subtitle = "If you must ask — tell me this: what's harder, singing or speaking?"
        },
        [51009735] = {
          ContentES = "Cantar, supongo.",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001,
          Subtitle = "Singing, I suppose."
        },
        [51009736] = {
          ContentES = "Las pequeñas cajas de música pueden cantar solo hay que darle cuerda a la llave y sale una melodía. Hablar es más fácil que cantar, y yo soy más grande y mejor hecha que cualquier caja de música.",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309,
          Subtitle = "Little music boxes can sing — simply wind a key and out comes a melody. Since speaking's easier than singing, and I'm larger and better made than any music box..."
        },
        [51009737] = {
          ContentES = "Entonces, ¿por qué no podría hablarte, del mismo modo que tú me hablas ahora?",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          Subtitle = "Why shouldn't I be able to talk to you, just as you're talking to me?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentES = "Pero...",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          Subtitle = "But...",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentES = "Lo sé, te parece extraño.",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309,
          Subtitle = "I understand — you're confused."
        },
        [51009740] = {
          ContentES = "La gente piensa que las cajas no deberían hablar como los troncos huecos, que solo devuelven el eco de tu voz. Pero sé sincero contigo mismo: ¿no te gustaría una caja que realmente te respondiera?",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309,
          Subtitle = "People think crates shouldn't talk — like hollow trees, only echoing back your voice. But be honest with yourself: wouldn't you want a crate that actually answers?"
        },
        [51009741] = {
          ContentES = "No me abriste de inmediato. Lo que significa que, en el fondo, tal vez querías que hablara contigo, ¿verdad?",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          Subtitle = "You didn't pry me open straight away. That means... part of you wanted me to speak, didn't it?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "....",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentES = "Parece que comienzas a aceptar la idea. Entonces... ¿te gustaría quedarte un poco a charlar?",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          Subtitle = "Seems like you've come to terms with it. So — will you stay a while and talk?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿De qué quieres hablar?",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          Subtitle = "What do you want to talk about?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hmm... ¿qué tal si hablamos de la ópera que se dio anteayer en el Teatro Galea?",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          Subtitle = "Hmm... how about the opera at the Galea Theatre, two nights ago?",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          ContentES = "Se llamaba Putini. ¿La viste? ¿Qué opinaste de la voz de la cantante principal?",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309,
          Subtitle = "It was called Putini. Did you see it? What did you think of the lead's voice?"
        },
        [51009747] = {
          ContentES = "Sabes, no puedo ir al teatro... después de todo, solo soy una caja.",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309,
          Subtitle = "I'm just a crate, after all. I can't go to the theatre."
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Lo siento, no la vi.",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I didn't see it.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentES = "No pasa nada. Nadie te culpa. Pero deberías verla algún día, es una obra maravillosa. La heroína, Putini, es hermosa, generosa... y sobre todo, tiene el coraje de perseguir su libertad.",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309,
          Subtitle = "That's all right. No one's blaming you. But you should see it someday — it's a beautiful piece. The heroine, Putini — she's radiant, kind... and brave enough to chase her freedom."
        },
        [51009750] = {
          ContentES = "Yo también me gustaría ser como ella. Pero solo soy una simple caja.",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309,
          Subtitle = "I want to be like her. But I'm just a crate."
        },
        [51009751] = {
          ContentES = "Entonces tomé una decisión.",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309,
          Subtitle = "So, I made a decision."
        },
        [51009752] = {
          ContentES = "¿Qué decisión?",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentES = "Quiero partir hacia el mar. ¿Quién dijo que una caja debe quedarse en una esquina? Puede convertirse en un barco, dejarse llevar por las olas... Quiero sentir el viento marino, lleno de sal y arena.",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          Subtitle = "I want to set sail. Who says crates must stay on street corners? A crate could become a boat, drifting on the tide... I want to feel the sea wind — rough with salt and sand.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentES = "Pero dejar este lugar también significa perderlo todo.",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309,
          Subtitle = "But leaving here means losing everything I have."
        },
        [51009755] = {
          ContentES = "Liberarse de su jaula también es perder su refugio. Obtener la libertad también es enfrentarse a lo desconocido.",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309,
          Subtitle = "To leave the cage... is to leave the shelter. And freedom — well, that means stepping into the unknown."
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces dime, {性别:amigo mío|amiga mía}... ¿qué crees que debería hacer?",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309,
          Subtitle = "So tell me, my friend... what do you think I should do?"
        },
        [51009757] = {
          ContentES = "...Tienes razón.",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309,
          Subtitle = "...You're right."
        },
        [51009758] = {
          ContentES = "Gracias por hablar con una simple caja, alma bondadosa. Se acerca el amanecer... y con él, la magia que da vida a esta vieja madera se desvanece.",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309,
          Subtitle = "Thank you for keeping a lonely crate company, kind soul. Dawn is close... and with it, the magic in these old timbers begins to fade."
        },
        [51009759] = {
          ContentES = "Que cada noche de desvelo que enfrentes... no, mejor dicho que todas tus noches estén llenas de dulces sueños.",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309,
          Subtitle = "May every sleepless night you face... no — may all your nights be filled with peaceful dreams."
        },
        [51009760] = {
          ContentES = "(Escuchas un leve susurro, como un hada diminuta que se aleja del cuarto de un niño antes del amanecer. Cuando vuelves en ti, la Señorita Caja ha desaparecido.)",
          DialogueId = 51009760,
          GUID = "7FB294C0",
          Subtitle = "(You hear a faint tremble — like a pixie slipping from a child's bedside just before dawn.)\n(And when you come back to your senses, Miss Crate is gone.)"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Esa voz dentro de la caja... No sé por qué, pero terminé dejándome llevar por su conversación.)",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          Subtitle = "(What just happened...? That voice in the crate somehow steered the whole conversation.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Sin duda es un niño del barrio jugando. No puedo dejar esto sin investigar, debería hacer algunas preguntas por aquí.)",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001,
          Subtitle = "(It's probably some local kid messing around... but I can't just leave it. I should ask around.)"
        },
        [51009763] = {
          ContentES = "Disculpa... ¿quién eres? Te he visto rondando por aquí un rato.",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Excuse me... who are you? You've been hanging around my place for a while."
        },
        [51009764] = {
          ContentES = "¿Buscas un encargo? Seguimiento, recolección, entrega... acepto todo tipo de encargos, siempre que sean legales.",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Looking to hire someone? I take all kinds of commissions — tracking, foraging, courier work — so long as it's legal."
        },
        [51009765] = {
          ContentES = "¿Un encargo?",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001,
          Subtitle = "Commission?"
        },
        [51009766] = {
          ContentES = "¿Eh? ¿No estás aquí para contratarme?",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Huh? So you're not here to hire me?"
        },
        [51009767] = {
          ContentES = "Bueno... parece que la fama de “Giselle la Phoxcazadora” no es tan brillante como Camilla decía.",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302,
          Subtitle = "Alright. I guess Camilla oversold it — \"Giselle the Phoxhunter\" isn't exactly a household name."
        },
        [51009768] = {
          ContentES = "Giselle la Phoxcazadora... Sí, ese nombre me suena.",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001,
          Subtitle = "Giselle the Phoxhunter... yeah, that does sound familiar."
        },
        [51009769] = {
          ContentES = "Gracias, pero no hace falta que lo digas solo para agradarme.",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302,
          Subtitle = "Thanks, but you don't have to say that just to make me feel better."
        },
        [51009770] = {
          ContentES = "No, no, lo digo en serio...",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001,
          Subtitle = "No no, I mean it—"
        },
        [51009771] = {
          ContentES = "(Le cuentas a Giselle sobre la caja que hablaba detrás de su casa.)",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772,
          Subtitle = "(You tell Giselle about the talking crate behind her house.)"
        },
        [51009772] = {
          ContentES = "Entonces... ¿una caja detrás de mi casa te habló y te sugirió ir a la ópera? Muy bien, lo entiendo.",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302,
          Subtitle = "So— a crate behind my house struck up a conversation and suggested you watch an opera. Got it."
        },
        [51009773] = {
          ContentES = "...",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51009774] = {
          ContentES = "Tu reacción es... no exactamente lo que esperaba.",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001,
          Subtitle = "That's... not quite the reaction I was expecting."
        },
        [51009775] = {
          ContentES = "¿Ah, sí? Seguro que es mi naturaleza. Ya sea un niño escondido en una caja o una caja que realmente habla, para mí, ambos son plausibles.",
          DialogueId = 51009775,
          GUID = "7FB29736",
          NextDialogue = 51009776,
          SpeakNpcId = 700302,
          Subtitle = "No? Well, that's me. Whether it's a kid in a box or a box with a voice — either way, I've seen stranger."
        },
        [51009776] = {
          ContentES = "Gracias por contarme eso. Haré algunas preguntas.",
          DialogueId = 51009776,
          GUID = "7FB29760",
          NextDialogue = 51009777,
          SpeakNpcId = 700302,
          Subtitle = "Thanks for letting me know. I'll ask around."
        },
        [51009777] = {
          ContentES = "Ah, por cierto... creo saber quién eres. Eres {nickname}, ¿verdad? La nueva estrella en ascenso entre los Phoxcazadores.",
          DialogueId = 51009777,
          GUID = "7FB2978A",
          NextOptions = {
            [1] = 510096871,
            [2] = 510096872,
            [3] = 510096873
          },
          SpeakNpcId = 700302,
          Subtitle = "Oh, wait — you're , right? You've made a bit of a name for yourself among the Phoxhunters."
        },
        [51009778] = {
          ContentES = "Lo sospechaba. Me alegra ver que mi instinto no me engaña.",
          DialogueId = 51009778,
          GUID = "7FB297B4",
          NextDialogue = 51009781,
          SpeakNpcId = 700302,
          Subtitle = "Thought so. Good to see my instincts aren't getting rusty."
        },
        [51009779] = {
          ContentES = "Relájate. Talentos nuevos como tú se hacen famosos rápidamente.",
          DialogueId = 51009779,
          GUID = "7FB297DE",
          NextDialogue = 51009781,
          SpeakNpcId = 700302,
          Subtitle = "Relax. Talented newcomers like you don't stay under the radar for long."
        },
        [51009780] = {
          ContentES = "Un poco directo... pero definitivamente difícil de olvidar.",
          DialogueId = 51009780,
          GUID = "7FB29808",
          NextDialogue = 51009781,
          SpeakNpcId = 700302,
          Subtitle = "Bit on the nose... but certainly hard to forget."
        },
        [51009781] = {
          ContentES = "Ya que parece que tienes algo de tiempo... ¿me ayudarías?",
          DialogueId = 51009781,
          GUID = "7FB29832",
          NextDialogue = 51009782,
          SpeakNpcId = 700302,
          Subtitle = "If you're free, I could use a hand."
        },
        [51009782] = {
          ContentES = "Necesito algunas hierbas, te daré la lista. Solo déjalas en el Asfódelo cuando termines. Camilla te dará tu pago.",
          DialogueId = 51009782,
          GUID = "7FB2985C",
          NextDialogue = 51009783,
          SpeakNpcId = 700302,
          Subtitle = "I need a few herbs — I'll give you the list. Just drop them at The Asphodel once you're done. Camilla will be holding your payment."
        },
        [51009783] = {
          ContentES = "¿No quieres que te las entregue aquí?",
          DialogueId = 51009783,
          GUID = "7FB29886",
          NextDialogue = 51009784,
          SpeakNpcId = 100001,
          Subtitle = "You don't want them delivered here?"
        },
        [51009784] = {
          ContentES = "No, no hace falta. El Asfódelo está bien.",
          DialogueId = 51009784,
          GUID = "7FB298B0",
          SpeakNpcId = 700302,
          Subtitle = "No. The Asphodel's fine."
        },
        [51009785] = {
          Camera = "777.87793,290.900391,409.416016,0.000004,-23.199877,-161.79744,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Esto debería bastar.)",
          DialogueId = 51009785,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB298DA",
          NextDialogue = 51009786,
          SpeakNpcId = 100001,
          Subtitle = "(This should do it.)",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51009786] = {
          Camera = "104.59375,60.244141,114.90918,0.000007,-13.199702,-164.194138,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Estas hierbas… son todas muy comunes. Si Giselle es realmente una Phoxcazadora, ¿por qué me pediría recogerlas por ella?)",
          DialogueId = 51009786,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29904",
          NextDialogue = 51009787,
          SpeakNpcId = 100001,
          Subtitle = "(These herbs... they're just common types. Why would a Phoxhunter like Giselle ask me to gather them? She could've easily done it herself.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009787] = {
          ContentES = "(Ahora que lo pienso, su actitud también era extraña…)",
          DialogueId = 51009787,
          GUID = "7FB2992E",
          NextDialogue = 51009788,
          SpeakNpcId = 100001,
          Subtitle = "(Come to think of it... she was acting a little strange.)"
        },
        [51009788] = {
          ContentES = "(Será mejor que lleve esto al Asfódelo. Tal vez Camilla sepa qué está pasando.)",
          DialogueId = 51009788,
          GUID = "7FB29958",
          SpeakNpcId = 100001,
          Subtitle = "(Better drop these off at The Asphodel. Maybe Camilla knows what's going on.)"
        },
        [51009789] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Buenas tardes. ¿Vienes por una copa o buscando trabajo?",
          DialogueId = 51009789,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29982",
          NextDialogue = 51009790,
          SpeakNpcId = 200003,
          Subtitle = "Afternoon. Here for a drink, or looking for a gig?"
        },
        [51009790] = {
          ContentES = "Solo vine a entregar esto. Giselle me pidió que trajera estas hierbas aquí.",
          DialogueId = 51009790,
          GUID = "7FB299AC",
          NextDialogue = 51009791,
          SpeakNpcId = 100001,
          Subtitle = "Just here to drop something off. Giselle asked me to deliver these."
        },
        [51009791] = {
          ContentES = "¿Giselle? Sí, pasó hace un rato, incluso me dejó un paquete para ti. Pero… algo no anda bien. ¿Qué fue exactamente lo que te pidió?",
          DialogueId = 51009791,
          GUID = "7FB299D6",
          NextDialogue = 51009792,
          SpeakNpcId = 200003,
          Subtitle = "Giselle? She was here earlier — actually left something for you. But... something felt off. What exactly did she ask you to do?",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009792] = {
          ContentES = "(Le explicas cómo Giselle te pidió que recolectaras hierbas.)",
          DialogueId = 51009792,
          GUID = "7FB29A00",
          NextDialogue = 51009793,
          Subtitle = "(You explain how Giselle sent you to gather herbs.)"
        },
        [51009793] = {
          ContentES = "....",
          DialogueId = 51009793,
          GUID = "7FB29A2A",
          NextDialogue = 51009794,
          SpeakNpcId = 200003,
          Subtitle = "..."
        },
        [51009794] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Qué pasa? ¿Hay algún problema?",
          DialogueId = 51009794,
          GUID = "7FB29A54",
          NextDialogue = 51009795,
          SpeakNpcId = 100001,
          Subtitle = "What is it? Something wrong?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        }
      }
    end
  },
  {
    MinKey = 51009795,
