        [51009798] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mmm. Solía ser capitana en la Escolta, la dejó hace dieciséis años, tras una disputa con su superior por un caso. Ahora es una Phoxcazadora: astuta, hábil y muy respetada en el oficio.",
          DialogueId = 51009798,
          GUID = "7FB29AFC",
          NextDialogue = 51009799,
          SpeakNpcId = 200003,
          Subtitle = "Mm. She used to be a Captain in the Escort — left sixteen years ago after a falling-out with her superior over a case. Now she's a Phoxhunter. Sharp, skilled — well-respected in the trade."
        },
        [51009799] = {
          ContentES = "En fin... no vale la pena darle más vueltas. El encargo es legítimo, y de hecho te dejó algo.",
          DialogueId = 51009799,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29B26",
          NextDialogue = 51009800,
          SpeakNpcId = 200003,
          Subtitle = "Anyway... no point overthinking it. The job's valid, and she did leave you something. I won't pry.",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009800] = {
          ContentES = "Toma, esto es para ti.",
          DialogueId = 51009800,
          GUID = "7FB29B50",
          NextDialogue = 51009801,
          SpeakNpcId = 200003,
          Subtitle = "Here — this is for you.",
          TalkActionId = {
            [1] = "200003:Give"
          }
        },
        [51009801] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Esto es... el pago? ¿Y una carta?",
          DialogueId = 51009801,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29B7A",
          SpeakNpcId = 100001,
          Subtitle = "This is... the payment. And a letter?"
        },
        [51009802] = {
          ContentES = "Hola, mi {性别:querido amigo|querida amiga},\nGracias por hacerle compañía a una vieja caja un poco loca hasta altas horas de la noche... y por darme el valor de zarpar.\nTal vez lo que hago no sea justo para con mis amigas... o con mi maestra. Pero estoy segura de que lo entenderán.\nEl mundo es grande. Las volveré a ver en algún lugar, sobre otro escenario.\nY por favor, no culpes a Giselle. Fue mi decisión. Espero que mi egoísmo no haya causado problemas a nadie.\nAh... me doy cuenta de que nunca te dije mi nombre.\nPero ya no importa, no volveré a necesitarlo. Veamos...\nBien... si algún día encuentras una chica llamada Putini... espero que me reconozcas. Y te prometo que yo te reconoceré.",
          DialogueId = 51009802,
          Duration = 10,
          GUID = "7FB29BA4",
          Subtitle = "Dear friend, \nThank you for keeping a strange old crate company deep into the night — and for giving me the courage to set sail.\nPerhaps this isn't fair to my friends... or my teacher. But I believe they'll understand. The world is vast. I'll meet them again — somewhere out there, on another stage.\nAnd please, don't blame Giselle. This was my decision alone. I hope my selfishness hasn't brought anyone trouble. \nAh... I just realised I never told you my name.\nBut it doesn't matter now — I won't be needing it anymore. Let's see...\nOkay — if one day, you meet a girl named Putini... I hope you'll recognise me. And I promise — I'll recognise you."
        },
        [51009803] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Parece que te hiciste una amiga bastante interesante. Apostaría a que detrás de eso hay una buena historia.",
          DialogueId = 51009803,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29BCE",
          NextDialogue = 51009804,
          SpeakNpcId = 200003,
          Subtitle = "Looks like you made an interesting friend. I bet there's a good story there.",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009804] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No exactamente... Honestamente, ni siquiera sé bien qué fue lo que pasó.",
          DialogueId = 51009804,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB29BF8",
          NextDialogue = 51009805,
          SpeakNpcId = 100001,
          Subtitle = "Not really. Honestly... I'm still not sure what actually happened.",
          TalkActionId = {
            [1] = "200003:Talk02_End",
            [2] = "100001:ScratchHead_Start"
          }
        },
        [51009805] = {
          ContentES = "(Le cuentas todo lo que ha pasado en los últimos dos días.)",
          DialogueId = 51009805,
          GUID = "7FB29C22",
          IsBlack = 1,
          NextDialogue = 51009806,
          Subtitle = "(You recount everything that's happened over the past two days.)"
        },
        [51009806] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Putini...",
          DialogueId = 51009806,
          GUID = "7FB29C4C",
          NextDialogue = 51009807,
          SpeakNpcId = 200003,
          Subtitle = "Putini...",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009807] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Te suena ese nombre?",
          DialogueId = 51009807,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29C76",
          NextDialogue = 51009808,
          SpeakNpcId = 100001,
          Subtitle = "Does that name mean anything to you?",
          TalkActionId = {
            [1] = "100001:ScratchHead_End"
          }
        },
        [51009808] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No por sí solo. Pero... ¿no mencionó esa voz en la caja una ópera que se acababa de presentar en el teatro?",
          DialogueId = 51009808,
          GUID = "7FB29CA0",
          NextDialogue = 51009809,
          SpeakNpcId = 200003,
          Subtitle = "Not by itself. But didn't that voice in the crate mention an opera that just played at the theatre?"
        },
        [51009809] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, incluso me preguntó qué me pareció la actuación de la protagonista.",
          DialogueId = 51009809,
          GUID = "7FB29CCA",
          NextDialogue = 51009810,
          SpeakNpcId = 100001,
          Subtitle = "Yeah — she even asked how the lead did.",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009810] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Qué curioso... Justo he oído algunos rumores al respecto.",
          DialogueId = 51009810,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29CF4",
          NextDialogue = 51009811,
          SpeakNpcId = 200003,
          Subtitle = "Funny thing, that. There's been some talk in the tavern...",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009811] = {
          ContentES = "Un cliente me contó que asistió al ensayo general de Putini. Y según él, la actriz principal no era la misma que subió al escenario la noche del estreno.",
          DialogueId = 51009811,
          GUID = "7FB29D1E",
          NextDialogue = 51009812,
          SpeakNpcId = 200003,
          Subtitle = "One of the regulars caught the dress rehearsal for Putini. Said the lead wasn't the same actress who performed on opening night."
        },
        [51009812] = {
          ContentES = "Según él, la intérprete del ensayo era más joven y muy talentosa, pero la noche del estreno fue la antigua estrella quien subió al escenario.",
          DialogueId = 51009812,
          GUID = "7FB29D48",
          NextDialogue = 51009813,
          SpeakNpcId = 200003,
          Subtitle = "They said the rehearsal lead was younger — even more talented. But in the end, the role went to the usual star."
        },
        [51009813] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Quieres decir que...?",
          DialogueId = 51009813,
          GUID = "7FB29D72",
          NextDialogue = 51009814,
          SpeakNpcId = 100001,
          Subtitle = "You mean—",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009814] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Solo son rumores de taberna, nada que permita establecer un vínculo claro entre ambos casos.",
          DialogueId = 51009814,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29D9C",
          NextDialogue = 51009815,
          SpeakNpcId = 200003,
          Subtitle = "It's just hearsay. Nothing solid to connect these dots."
        },
        [51009815] = {
          ContentES = "Pero... si tienes algo de tiempo, tal vez valga la pena indagar un poco más. Yo también quisiera saber cómo termina esta historia.",
          DialogueId = 51009815,
          GUID = "7FB29DC6",
          NextDialogue = 51009816,
          SpeakNpcId = 200003,
          Subtitle = "Still... if you've got time, maybe dig a little deeper. I'd like to know the truth too."
        },
        [51009816] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Camilla no sabe más que yo... Pero hay algo seguro: el comportamiento de Giselle fue extraño.)",
          DialogueId = 51009816,
          GUID = "7FB29DF0",
          NextDialogue = 51009817,
          SpeakNpcId = 100001,
          Subtitle = "(So Camilla's in the dark too... But one thing's for sure — Giselle was acting strange.)",
          TalkActionId = {
            [1] = "200003:Talk02_End"
          }
        },
        [51009817] = {
          ContentES = "(¿La chica de la caja... será la actriz que nunca pudo subir al escenario? Y si es así, ¿lo sabía Giselle desde el principio?)",
          DialogueId = 51009817,
          GUID = "7FB29E1A",
          NextDialogue = 51009818,
          SpeakNpcId = 100001,
          Subtitle = "(That girl in the crate... could she have been the one from the dress rehearsal? And if so — did Giselle know the whole time?)"
        },
        [51009818] = {
          ContentES = "(...No sirve de nada adivinar. Tendré que preguntarle directamente a Giselle.)",
          DialogueId = 51009818,
          GUID = "7FB29E44",
          SpeakNpcId = 100001,
          Subtitle = "(...No use guessing. I'll have to ask Giselle myself.)"
        },
        [51009819] = {
          Camera = "-459.554443,-130.776611,223.984375,0.000025,-13.400024,3.198126,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Te lo dije! ¡Lo he estado diciendo desde el principio!",
          DialogueId = 51009819,
          FacialId = {
            [1] = "700307:CM_Angry01"
          },
          GUID = "7FB29E6E",
          NextDialogue = 51009820,
          SpeakNpcId = 700307,
          Subtitle = "I told you so — I've been saying this from the start!",
          TalkActionId = {
            [1] = "700307:Angry01_Start"
          }
        },
        [51009820] = {
          ContentES = "¡Nunca deberíamos haber contratado a esa mujer sospechosa como institutriz! ¡Nunca deberíamos haber dejado que Rosalind tomara esas malditas clases de canto!",
          DialogueId = 51009820,
          GUID = "7FB29E98",
          NextDialogue = 51009821,
          SpeakNpcId = 700307,
          Subtitle = "We never should've hired that dubious woman as a tutor! And we never should've let Rosalind take those blasted singing lessons!"
        },
        [51009821] = {
          ContentES = "¡Fuiste tú quien dijo que necesitaba una actividad para que dejara de pasar el día en la calle!",
          DialogueId = 51009821,
          FacialId = {
            [1] = "700308:CM_Sad01"
          },
          GUID = "7FB29EC2",
          NextDialogue = 51009822,
          SpeakNpcId = 700308,
          Subtitle = "You were the one who said she needed something to keep her busy — so she wouldn't be out roaming around all day!",
          TalkActionId = {
            [1] = "700308:Explain01_Start"
          }
        },
        [51009822] = {
          ContentES = "¡Quería algo que la mantuviera en casa, no algo que la hiciera salir corriendo de nuevo y acabar secuestrada!",
          DialogueId = 51009822,
          GUID = "7FB29EEC",
          NextDialogue = 51009823,
          SpeakNpcId = 700307,
          Subtitle = "I meant something to keep her home — not something that'd send her running off again and getting herself kidnapped!",
          TalkActionId = {
            [1] = "700307:Angry01_End",
            [2] = "700308:Explain01_End"
          }
        },
        [51009823] = {
          ContentES = "¡Y ustedes, los inútiles de la Escolta! ¿De qué sirven!? Finalmente teníamos una pista, ¡y por su lentitud, los secuestradores se escaparon!",
          DialogueId = 51009823,
          GUID = "7FB29F16",
          NextDialogue = 51009824,
          Scripts = [[
PARA{
TurnTo{TurnToDescription{"700307:n(700313)"}},
TurnTo{TurnToDescription{"700308:n(700313)"}}
}]],
          SpeakNpcId = 700307,
          Subtitle = "And you Escort grunts — what use are you!? We finally had a lead, and you lot were too slow — now the kidnappers are gone!"
        },
        [51009824] = {
          ContentES = "...",
          DialogueId = 51009824,
          GUID = "7FB29F40",
          NextDialogue = 51009825,
          SpeakNpcId = 700313,
          Subtitle = "..."
        },
        [51009825] = {
          ContentES = "Pff.... ¿por qué estoy perdiendo el tiempo gritándole a unos idiotas como estos? ¡Voy a encontrar a mi hija yo mismo!",
          DialogueId = 51009825,
          GUID = "7FB29F6A",
          NextDialogue = 51009826,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"700307:n(700307)"}},
LookAt{LookAtDescription{"700308:n(700308)"}},
MoveTo{ActorId{700307},MoveSpeed{150},TargetPoint{"MagnusMPoint_20023205"}},
MoveTo{ActorId{700308},MoveSpeed{150},TargetPoint{"MagnusFPoint_20023205"}}
}]],
          SpeakNpcId = 700307,
          Subtitle = "Ugh — why am I even wasting my breath on imbeciles like you? I'll find my daughter myself!"
        },
        [51009826] = {
          Camera = "-238.418213,-514.537842,220.403809,0.000037,-12.999988,72.598557,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "... Uff. Finalmente se fue.",
          DialogueId = 51009826,
          GUID = "7FB29F94",
          NextDialogue = 51009827,
          SpeakNpcId = 700313,
          Subtitle = "...Phew. He's finally gone."
        },
        [51009827] = {
          Camera = "77.355469,-517.516235,186.296875,0.000047,-11.199768,98.997734,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Por favor, mantente alejado. Esta zona está restringida.",
          DialogueId = 51009827,
          GUID = "7FB29FBE",
          NextDialogue = 51009828,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023205"}},
TurnTo{TurnToDescription{"100001:n(700313)"}}
}]],
          SpeakNpcId = 700313,
          Subtitle = "Please stay back — this area's off-limits."
        },
        [51009828] = {
          Camera = "-445.371338,-206.447021,167.490234,0.00006,-10.999575,13.197603,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentES = "Perdón, escuché gritos... ¿Qué está pasando aquí?",
          DialogueId = 51009828,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB29FE8",
          NextDialogue = 51009829,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I heard yelling. Is everything okay?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009829] = {
          ContentES = "Recibimos un informe de un secuestro. Se suponía que la víctima estaba retenida aquí, pero cuando llegamos, el lugar ya estaba vacío.",
          DialogueId = 51009829,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2A012",
          NextDialogue = 51009830,
          SpeakNpcId = 700313,
          Subtitle = "We received a report of a kidnapping. The victim was supposedly held here, but the place was already empty when we arrived.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009830] = {
          ContentES = "Esta propiedad está bajo cierre. Si solo estás aquí por curiosidad, te pediré que te vayas.",
          DialogueId = 51009830,
          GUID = "7FB2A03C",
          NextDialogue = 51009831,
          SpeakNpcId = 700313,
          Subtitle = "This property's on lockdown. If you're just here out of curiosity, I'll have to ask you to move along."
        },
        [51009831] = {
          ContentES = "Entendido... ¿Y quiénes eran esas dos personas?",
          DialogueId = 51009831,
          GUID = "7FB2A066",
          NextDialogue = 51009832,
          SpeakNpcId = 100001,
          Subtitle = "Who were those two just now?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009832] = {
          ContentES = "El Conde Magnus y su esposa, los padres de la víctima. Entiendo que estén preocupados, pero... digamos que son fieles a su reputación.",
          DialogueId = 51009832,
          GUID = "7FB2A090",
          NextDialogue = 51009833,
          SpeakNpcId = 700313,
          Subtitle = "The victim's parents — the Earl and Countess of Magnus. I get that they're worried, but they really do live up to their reputation...",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009833] = {
          ContentES = "Se dice que siempre estaban controlando a su hija. Tal vez la señorita Rosalind se escapó solo para tomar un respiro...",
          DialogueId = 51009833,
          GUID = "7FB2A0BA",
          NextDialogue = 51009834,
          SpeakNpcId = 700313,
          Subtitle = "Word is they were always breathing down their daughter's neck. Maybe Miss Rosalind ran off just to get some air..."
        },
        [51009834] = {
          ContentES = "Mmm, basta de charla. Si obtienes cualquier información, repórtala a la Escolta.",
          DialogueId = 51009834,
          GUID = "7FB2A0E4",
          NextDialogue = 51009835,
          SpeakNpcId = 700313,
          Subtitle = "Ahem... that's enough gossip. If you have any information, please report it to the Escort."
        },
        [51009835] = {
          Camera = "-99.088623,-74.42334,133.572266,0.000056,-4.199521,-40.602531,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentES = "(Giselle... y la Señorita Caja... ya no están aquí.)",
          DialogueId = 51009835,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2A10E",
          NextDialogue = 51009836,
          SpeakNpcId = 100001,
          Subtitle = "(Giselle and Miss Crate... they're both gone.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009836] = {
          ContentES = "(¿Un secuestro? ¿Podría estar relacionado con la carta que dejó Giselle en la taberna?)",
          DialogueId = 51009836,
          GUID = "7FB2A138",
          NextDialogue = 51009837,
          SpeakNpcId = 100001,
          Subtitle = "(A kidnapping... could it have something to do with that letter Giselle left at the tavern?)"
        },
        [51009837] = {
          ContentES = "(No tengo ninguna pista por ahora. Tendré que mantenerme alerta y ver qué aparece.)",
          DialogueId = 51009837,
          GUID = "7FB2A162",
          SpeakNpcId = 100001,
          Subtitle = "(No leads for now. Guess I'll just have to stay sharp and see what turns up.)"
        },
        [51009838] = {
          ContentES = "Da... da da...",
          DialogueId = 51009838,
          GUID = "7FB2A163",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Da... Da da..."
        },
        [51009850] = {
          Camera = "-1567.962891,-185.177612,2329.811035,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          ContentES = "(Han pasado tantas cosas en Lago Helado estos últimos días... y ahora, incluso ha habido un secuestro.)",
          DialogueId = 51009850,
          FinalCamera = "-1614.97168,-559.773193,2467.275635,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A384",
          NextDialogue = 51009851,
          Scripts = "SetTag{Tag{\"Huozai04Tag\"},Value{\"Value_1\"}}",
          SpeakNpcId = 100001,
          Subtitle = "(So much has happened in Icelake these past few days... and now, there's even been a kidnapping.)",
          ToFinalCameraBlendTime = 5
        },
        [51009851] = {
          Camera = "389.291016,-7961.245117,-744.026855,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          ContentES = "(Pensándolo bien, <H>varios eventos</> parecen estar conectados de alguna manera.)",
          DialogueId = 51009851,
          FinalCamera = "712.783569,-8322.950195,-679.47168,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3AE",
          NextDialogue = 51009852,
          SpeakNpcId = 100001,
          Subtitle = "(Now that I think about it, some of these events might be more closely connected than they seemed.)",
          ToFinalCameraBlendTime = 5
        },
        [51009852] = {
          Camera = "1489.815308,3777.302246,3313.351074,0.000015,-35.199669,-107.997414,20.0,100000.0,false,Manual,2.8",
          ContentES = "(Mejor poner todo en claro... y empezar a conectar los puntos.)",
          DialogueId = 51009852,
          FinalCamera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3D8",
          SpeakNpcId = 100001,
          Subtitle = "(Time to lay everything out... and start connecting the dots.)",
          ToFinalCameraBlendTime = 5
        },
        [51009853] = {
          Camera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          ContentES = "(Había más en este caso de lo que se creía. Y la señora Violetta... seguramente conoce la verdad. Giselle secuestró a su alumna para obligarla a mostrarse.)",
          DialogueId = 51009853,
          GUID = "7FB2A402",
          NextDialogue = 51009854,
          SpeakNpcId = 100001,
          Subtitle = "(There was more to the kidnapping sixteen years ago... and Violetta may be the one who knows the truth. Giselle took her student just to force a meeting.)"
        },
        [51009854] = {
          ContentES = "(Si mis deducciones son correctas, ella debería estar con Violetta ahora mismo.)",
          DialogueId = 51009854,
          GUID = "7FB2A42C",
          NextDialogue = 51009855,
          SpeakNpcId = 100001,
          Subtitle = "(If my deductions are right, she should be with Violetta right now.)"
        },
        [51009855] = {
          ContentES = "(La carta mencionaba la ubicación. Debo apresurarme... esperemos que no sea demasiado tarde.)",
          DialogueId = 51009855,
          GUID = "7FB2A456",
          SpeakNpcId = 100001,
          Subtitle = "(The letter mentioned the location. I need to hurry... let's hope I'm not too late.)"
        },
        [51009856] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentES = "Justo a tiempo, ¿eh?",
          DialogueId = 51009856,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2A480",
          NextDialogue = 51009857,
          SpeakNpcId = 700302,
          Subtitle = "Right on time, huh.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009857] = {
          ContentES = "...",
          DialogueId = 51009857,
          GUID = "7FB2A4AA",
          NextDialogue = 51009858,
          SpeakNpcId = 700300,
          Subtitle = "..."
        },
        [51009858] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Qué pasa con el silencio? Esto no es un tribunal. Si esperas a que te lean tus derechos, no contengas la respiración.",
          DialogueId = 51009858,
          GUID = "7FB2A4D4",
          NextDialogue = 51009859,
          SpeakNpcId = 700302,
          Subtitle = "What's with the silence? This isn't a courtroom. If you're waiting for a \"You have the right to remain silent,\" don't hold your breath."
        },
        [51009859] = {
          ContentES = "¿Y qué quieres que diga? Vamos, te escucho. Después de un golpe tan bajo, ¿qué respuesta esperas exactamente?",
          DialogueId = 51009859,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB2A4FE",
          NextDialogue = 51009860,
          SpeakNpcId = 700300,
          Subtitle = "And what would you have me say? Go on, enlighten me. After a despicable stunt like this, what kind of answer do you expect to hear?"
        },
        [51009860] = {
          Camera = "148.300781,-316.230469,157.037598,0.999999,-5.400179,115.588638,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Te burlas de mí? ¿O de verdad crees que tus crímenes pueden maquillarse tan fácilmente como tu rostro? ¿Crees que un poco de polvo puede borrarlo todo?",
          DialogueId = 51009860,
          GUID = "7FB2A528",
          NextDialogue = 51009861,
          SpeakNpcId = 700302,
          Subtitle = "Still playing dumb, are we? Or do you actually believe your crimes are as easy to cover up as your real face? You really think a bit of powder and paint can hide everything?"
        },
        [51009861] = {
          ContentES = "Muy bien... Déjame refrescar tu memoria.",
          DialogueId = 51009861,
          GUID = "7FB2A552",
          NextDialogue = 51009862,
          SpeakNpcId = 700302,
          Subtitle = "Fine. Then let me jog your memory."
        },
        [51009862] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentES = "Hace dieciséis años, en Lago Helado, un joven llamado Sig secuestró a Enola Ruthford, la hija de Fabrice Ruthford, responsable de la Mina de Glevum.",
          DialogueId = 51009862,
          GUID = "7FB2A57C",
          NextDialogue = 51009863,
          SpeakNpcId = 700302,
          Subtitle = "Sixteen years ago, in Icelake, a young man named Sig kidnapped the daughter of Fabrice Ruthford — then overseer of Glevum Pit. Her name was Enola."
        },
        [51009863] = {
          ContentES = "Cuando la Escolta lo acorralaron, resistió y accidentalmente incendió la casa en la lucha. Enola murió en las llamas. Y Sig fue condenado a muerte.",
          DialogueId = 51009863,
          GUID = "7FB2A5A6",
          NextDialogue = 51009864,
          SpeakNpcId = 700302,
          Subtitle = "When the Escort cornered him, he resisted — and accidentally set the house on fire in the struggle. Enola died in the flames. And Sig was sentenced to death."
        },
        [51009864] = {
          Camera = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, he oído hablar de esa tragedia. Una historia lamentable... que descanse en paz esa pobre niña.",
          DialogueId = 51009864,
          GUID = "7FB2A5D0",
          NextDialogue = 51009865,
          SpeakNpcId = 700300,
          Subtitle = "I've heard of that tragedy. A pity, truly. May that poor girl rest in peace.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          ContentES = "Pero yo solo llegué a Lago Helado mucho después. ¿Qué tiene que ver esto conmigo?",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300,
          Subtitle = "But I only arrived in Icelake a few years ago. What could any of this possibly have to do with me?"
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentES = "Porque alguien sobrevivió a ese incendio.",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          Subtitle = "Because someone survived that fire.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          ContentES = "Un testigo afirma que había tres personas en la casa esa noche: Sig, Enola... y la hermana de Sig, Violet, una niña de la misma edad que Enola.",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302,
          Subtitle = "A witness said there were three people in the house that night — Sig, Enola... and Sig's sister, Violet. A girl around the same age as Enola."
        },
        [51009868] = {
          ContentES = "En el caos, ese testigo logró sacar a una niña de las llamas, una niña que él <H>creyó</> que era Violet. ¿Pero lo era realmente?",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302,
          Subtitle = "In the chaos, that witness managed to pull a girl from the flames — a girl he thought was Violet. But was she really?"
        },
        [51009869] = {
          ContentES = "Corrígeme si me equivoco: mataste a Violet esa noche... y luego tomaste su nombre para engañar a Donat y escapar de Lago Helado, ¿verdad, Enola Ruthford?",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          Subtitle = "Tell me I'm wrong. Sixteen years ago, you killed Violet in that fire — then took her name, and tricked Donat into helping you escape Icelake. Didn't you, Enola Ruthford?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...Heh. Qué historia tan fascinante. Los buenos misterios son tan raros hoy en día.",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          Subtitle = "...Heh. Now there's a compelling tale. Good mysteries are so rare these days.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentES = "Continúa, me gustan las historias.",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          Subtitle = "Please, do go on. I'm dying to hear how it ends.",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pasé años investigando este caso. Un cuerpo irreconocible... una sola sobreviviente... demasiadas coincidencias.",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          Subtitle = "I spent years combing through that case. A body burnt beyond recognition... a lone survivor... it was all just a little too convenient.",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentES = "Todas las piezas estaban allí, pero faltaba el hilo conductor.",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302,
          Subtitle = "All the pieces were there, but the thread connecting them all together was missing."
        },
        [51009874] = {
          ContentES = "Si no hubiera sido asignada a la protección de Fabrice Ruthford en aquel entonces, si no hubiera escuchado cantar a su hija —",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302,
          Subtitle = "As luck would have it, back when I was assigned to guard Fabrice Ruthford, I once heard his daughter sing."
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Esa voz... la reconocería en cualquier parte. Fue entonces cuando supe quién eras realmente, “Violetta de los mil rostros”.",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302,
          Subtitle = "That voice... I'd recognise it anywhere. And that's when I knew who you really were, \"Violetta of a Thousand Faces.\""
        },
        [51009876] = {
          ContentES = "Incluso encontré formas de estudiar tus hábitos... por ejemplo, enviando a alguien a entregarte cartas falsas para observarte.",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          Subtitle = "I tried to study your habits — even arranged for false letters to be delivered, just to keep tabs on you.",
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentES = "Ah, así que era uno de los tuyos.",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          Subtitle = "Ah, so he was one of yours.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentES = "No exactamente. En realidad era uno de tus admiradores. Solo le di un pequeño empujón. Gracias a él, obtuve la confirmación que necesitaba.",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302,
          Subtitle = "Not quite. He really was a fan. I just gave him a gentle nudge. And thanks to him, I got the answer I needed."
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero hay algo que todavía no entiendo.",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302,
          Subtitle = "Still, there's one thing I don't understand."
        },
        [51009880] = {
          ContentES = "Cambiar de identidad con Violet no habría sido posible sin su colaboración. ¿Cómo los convenciste?",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          Subtitle = "Swapping places with Violet — it couldn't have been possible unless both Sig and the girl went along with it. How did you convince them?",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pensé que me harías una pregunta difícil... La respuesta es sencilla.",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          Subtitle = "That's your big mystery? The answer's simple.",
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentES = "Servías bajo el mando de mi padre. Entonces deberías saber lo que significaba desafiarle.",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          Subtitle = "You used to serve under my father. Then you should know what it meant to defy him.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentES = "El pobre Sig ya sabía que no saldría con vida... y conociendo a mi padre, Violet tampoco tenía ninguna oportunidad.",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300,
          Subtitle = "Poor Sig was already prepared to throw his life away — but knowing my father, Violet was as good as dead too."
        },
        [51009884] = {
          ContentES = "Les ofrecí una solución: tras recibir el rescate, solo tenían que ganar tiempo, crear confusión y darle a Violet una oportunidad para escapar.",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300,
          Subtitle = "So I offered them a way out: Once the ransom was collected, stall as long as possible while creating a distraction to buy some time for Violet."
        },
        [51009885] = {
          ContentES = "Patético, ¿no? En su pánico, se enfrentó a la Escolta solo, con la esperanza de que una niña enferma huyera de una casa en llamas...",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          Subtitle = "Pathetic, isn't it? In his panic, he actually ran off on his own to hold off the Escort, hoping that a sickly little girl might somehow escape a blazing house...",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentES = "Aproveché la oportunidad. Maté a esa pobre niña que se interponía en mi camino. Tomé su nombre. Dejé atrás ese tugurio... y a mi padre. Dejé atrás todo lo que me impedía subir al escenario.",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300,
          Subtitle = "I took my chance. Killed that poor wretch who stood in my way. Took her name, left behind the dump — and my father. Left behind everything that ever stood between me and the stage."
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302,
          Subtitle = "..."
        },
        [51009888] = {
          ContentES = "¿Qué pasa, Giselle? Has perseguido esta verdad durante años... y ahora que la tienes, no pareces contenta.",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300,
          Subtitle = "What's the matter, Giselle? You've chased this truth for years... and now that you have it, you don't look the least bit satisfied."
        },
        [51009889] = {
          ContentES = "Estás completamente loca... ¿Todo esto solo por los focos? ¡Has matado a dos personas! ¡Dos vidas inocentes!",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          Subtitle = "You're insane... All of this — just for the spotlight!? You killed two people! Two innocent lives!",
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentES = "Entonces, ¿qué vas a hacer? ¿Revelar mis crímenes públicamente para arruinar mi reputación? ¿O... vengar su muerte aquí y ahora?",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          Subtitle = "So what will it be? Drag my sins into the light? Or take your revenge, right here and now?",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentES = "...Solo quería revelar la verdad... y entregarte a la Escolta.",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302,
          Subtitle = "...I only ever meant to reveal the truth... and turn you in to the Escort."
        },
        [51009892] = {
          ContentES = "(Giselle saca una daga. Su furia enrarece el aire. Casi puedes oír el cuero crujir bajo la fuerza de su agarre y el chirrido de sus dientes apretados.)",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          Subtitle = "(Giselle draws a dagger. Her fury thickens the air — you can almost hear her teeth grinding, the hilt creaking under the pressure of her grip.)",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentES = "(Si nadie la detiene, esa daga pronto pondrá fin a la más bella voz de Lago Helado... De todos modos, no puedes quedarte ahí viendo cómo alguien comete un asesinato.)",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1,
          Subtitle = "(If no one stops her, that dagger will silence the finest voice in Icelake. Whatever the truth... you can't just stand by and watch someone commit murder.)"
        },
        [51009894] = {
          ContentES = "{nickname}... ¿Qué haces aquí?",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300,
          Subtitle = "? What are you doing here?"
        },
        [51009895] = {
          ContentES = "¡Apártate! ¡No permitiré que una basura como ella viva ni un minuto más!",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          Subtitle = "Get out of my way. I won't let a monster like her walk free!",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentES = "(Se le ha ido completamente la cabeza... Tengo que encontrar la manera de calmarla.)",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001,
          Subtitle = "(She's lost it... I have to bring her back to her senses.)"
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Cálmate, Giselle. Tal vez haya más en esta historia de lo que crees.",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          Subtitle = "Giselle, calm down. There might be more to this than you think.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          ContentES = "¿¡No oíste lo que acaba de decir!? ¿¡Cómo se supone que me calme!?",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          Subtitle = "Did you not hear what she just said!? How am I supposed to calm down!?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          ContentES = "No se va a ir a ningún lado, no con nosotros aquí. Respira hondo, tengo algunas preguntas para ella.",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001,
          Subtitle = "She's not going anywhere — not with us here. Just take a breath. I have a few questions for her."
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,false,DoNotOverride,2.8",
          ContentES = "....",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          ContentES = "Está bien. Adelante.",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          Subtitle = "Fine. Go ahead.",
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Antes que nada... señora Violetta, ¿le resulta familiar esto?",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          Subtitle = "Before that — Ms Violetta, does this look familiar?",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          ContentES = "Eso es...",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          Subtitle = "That's...",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          ContentES = "(Violetta levanta instintivamente la mano hacia la parte posterior de su cabeza. Sus dedos rozan una textura familiar... luego se queda inmóvil, como si fuera golpeada por la realidad.)",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          Subtitle = "(Violetta's hand drifts instinctively to the back of her head. Her fingers find the familiar texture — and she freezes.)"
        },
        [51009905] = {
          ContentES = "Visto tu reacción, no me equivoqué... Fuiste tú quien dejó esa cinta en la tumba de Sig, ¿verdad?",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001,
          Subtitle = "Huh... just as I thought. You left this ribbon at Sig's grave, didn't you?"
        },
        [51009906] = {
          ContentES = "Me dijiste que pertenecía a una amiga muy querida, y que si habías elegido subir al escenario, era para cumplir su sueño.",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          Subtitle = "You once told me it belonged to a dear friend — and that you took to the stage to fulfil her dream.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentES = "Eres realmente {性别:un tonto ingenuo|una tonta ingenua}. Nunca creí que pudieras tragarte una historia tan melosa.",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300,
          Subtitle = "You're a naive fool. I can't believe you actually fell for such sentimental drivel."
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tal vez. Por eso fui a Donat a buscar la verdad, pidiéndole prestada esta cinta.",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          Subtitle = "Maybe. Which is why I borrowed this ribbon from Donat — to find out the truth.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentES = "Me habló de Violet. Dijo que era una chica increíblemente talentosa. Sin la pobreza ni la enfermedad, sin duda habría llegado a ser una gran dramaturga.",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001,
          Subtitle = "He told me about Violet. About how gifted she was. If not for poverty and illness, she might've been a great playwright."
        },
        [51009910] = {
          ContentES = "El destino no fue amable con ella, pero nunca se rindió. Incluso cuando estaba postrada en cama, seguía persiguiendo su sueño a su manera.",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001,
          Subtitle = "Fate dealt her a cruel hand, but she never gave up. Even when she could barely leave her bed, she still found a way to pursue her dream."
        },
        [51009911] = {
          ContentES = "Quería que la actriz más grande del mundo interpretara su obra, y que la historia que escribió, la última y más hermosa llegara a cada rincón de Atlasia.",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001,
          Subtitle = "She dreamed of the world's greatest actor performing her work — of her final, proudest piece reaching every corner of Atlasia."
        },
        [51009912] = {
          ContentES = "Y esa obra era...",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          Subtitle = "And that piece was—",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "...Putini. Una obra en tres actos. Luego fue adaptada a ópera.",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          Subtitle = "...Putini. A three-act play. Later adapted into the opera.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Exactamente. Ahora entiendes que seguir mintiendo solo empeoraría las cosas. Así que...",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          Subtitle = "Good. You get it now — lying any further would only make things worse. So...",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tienes razón... toda obra merece un final.",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "I suppose you're right. Every play must end eventually.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "...¿Realmente es el momento para tanto teatro?",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "...Is this really the time for theatrics?",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentES = "Si todos los espectadores fueran tan perspicaces como tú, los dramaturgos no tendrían que romperse la cabeza simplificando sus tramas.",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300,
          Subtitle = "Well, if every audience were as sharp as you, mystery playwrights wouldn't have to twist themselves in knots to dumb things down."
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿De qué hablan los dos? ¿Qué significa todo esto?",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          Subtitle = "What are you two talking about? What's going on here?",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es muy sencillo, Giselle. Si Violetta realmente consideraba a Violet como una simple herramienta para desechar, ¿por qué elegiría un nombre tan parecido al suyo?",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          Subtitle = "It's simple, Giselle. If she really saw Violet as nothing but a pawn, why would she take a name so close to hers?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          ContentES = "Déjame contarte lo que creo: Hace dieciséis años, Sig secuestró a Enola Ruthford, la que ahora se hace llamar Violetta para reunir lo necesario para tratar a su hermana.",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          Subtitle = "Let me tell you the version I see: Sixteen years ago, Sig kidnapped Enola Ruthford — the girl who would one day call herself Violetta — to raise money for his sister's treatment.",
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentES = "Durante su cautiverio, Enola conoció a Violet, enferma y postrada en la cama. Y en ese corto tiempo, se hicieron amigas cercanas.",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001,
          Subtitle = "While she was held captive, Enola met the bedridden Violet. And somewhere in that brief time, the two became close friends."
        },
        [51009922] = {
          ContentES = "Pero no duró mucho...",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001,
          Subtitle = "But it didn't last long."
        },
        [51009923] = {
          ContentES = "Violet sabía que sus días estaban contados. No quería que su hermano se hundiera más en el error. Así que escribió a Donat, el amigo de Sig, pidiéndole que interviniera.",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001,
          Subtitle = "Violet knew her time was running out. She didn't want her brother sinking deeper down the wrong path. So she wrote to Donat — a trusted friend of Sig's — hoping he'd intervene."
        },
        [51009924] = {
          ContentES = "Y Donat lo hizo. Reportó el secuestro... a ti, Giselle. Pero para entonces, supongo que Violet ya estaba...",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001,
          Subtitle = "And Donat did. He reported the kidnapping... to you, Giselle. But by then, I suspect Violet was already—"
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah... irónico, ¿verdad? Fui secuestrada, pero de alguna manera... esos fueron los días más felices de mi vida.",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          Subtitle = "Ah... strange, isn't it? I was kidnapped, yet somehow... those were the happiest days of my life.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentES = "Sig me tenía atada en una habitación, pero nunca tuvo intención de hacerme daño. Apenas me prestaba atención, solo caminaba sin cesar por la casa.",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300,
          Subtitle = "Sig kept me tied up in a room, but he never meant me harm. He barely paid me any attention — just paced endlessly around the house."
        },
        [51009927] = {
          ContentES = "Sabía que había otra persona en la casa, una joven. La escuchaba tararear suavemente los días que se sentía bien...",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300,
          Subtitle = "I knew there was someone else — a girl — in the house. I could hear her humming softly, on days when her mood was light..."
        },
        [51009928] = {
          ContentES = "Tal vez entendió que no podía cuidar de dos personas a la vez. Unos días después, me desató y me dejó moverme libremente por la planta baja.",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300,
          Subtitle = "Perhaps Sig realised he couldn't possibly tend to two helpless people at once. So a few days in, he untied me — let me move around the ground floor as I pleased."
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Cada vez que él salía, subía discretamente a ver a Violet al piso de arriba. Ella me leía sus historias, y yo las interpretaba, les daba vida.",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300,
          Subtitle = "And whenever he left the house, I'd steal upstairs to see Violet. She'd tell me the stories she was writing... and I'd act them out — bringing the characters to life."
        },
        [51009930] = {
          ContentES = "“¡Mi amado, no llores por mí! En esta noche sin sueño, pongo rumbo bajo la luz plateada...”",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"My dearest, weep no tears for me — on this sleepless night, I set off in silver light.\""
        },
        [51009931] = {
          ContentES = "“El viento hincha mi vela, la marea besa mi remo... el faro brilla sobre el mar, ¡y la luna resplandece con fuerza!”",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"The wind fills my sail, the tide kisses my oar. The lighthouse aglow, 'neath the moon — oh, so bright!\""
        },
        [51009932] = {
          ContentES = "Gracias, Enola... Fue maravilloso. De verdad. Jeje... Siempre que imaginaba a Putini, se parecía a ti: valiente, radiante y siempre en busca de su libertad...",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Thank you, Enola... that was beautiful. Truly. Hehe... Whenever I imagined Putini, she always looked like you — bold, radiant, and forever chasing her freedom..."
        },
        [51009933] = {
          ContentES = "¡Gracias! Improvisé un poco... Pero conozco a un compositor talentoso, Cavaradossi. Quizá podríamos pedirle que adapte Putini en una ópera...",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Thanks! I did a bit of improvising... But I know a brilliant composer — his name's Cavaradossi. Maybe we could ask him to adapt Putini into an opera—"
        },
        [51009934] = {
          ContentES = "...Pero probablemente nunca tendré la oportunidad de cantarla.",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "...Not that I'll ever get the chance to sing it."
        },
        [51009935] = {
          ContentES = "Tengo dieciocho años. Mi padre ya ha arreglado mi matrimonio dentro de dos meses, con un joven oficial de la Academia de Alquimia.",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "I'm eighteen now. My father's already arranged my marriage — two months from now, to some young officer from the Alchemy Academy."
        },
        [51009936] = {
          ContentES = "Supongo que pasaré el resto de mi vida como un adorno bonito acumulando polvo en un salón... o con las manos hundidas para siempre en esos malditos frascos de Phoxichor.",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Guess I'll spend the rest of my life as a pretty trophy collecting dust in a parlour... or elbow-deep in those wretched Phoxichor canisters."
        },
        [51009937] = {
          ContentES = "No, no... Enola, esto no debería ser así. Tienes una voz tan dulce como la de una alondra... No perteneces a un salón cualquiera. Perteneces a un gran escenario, al más grande de todos.",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "No, no... Enola, this isn't how it should be. You have a voice as sweet as a lark's... You don't belong in some parlour... You belong on a grand stage — the grandest there is."
        },
        [51009938] = {
          ContentES = "Toda persona que ame cantar merece brillar bajo los reflectores, sea Sola o Charon, rica o pobre...",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Everyone who loves to sing... deserves their moment in the spotlight... Solarian or Charon, rich or poor..."
        },
        [51009939] = {
          ContentES = "Encontraré la manera de convencer a mi hermano para que te deje ir. Mi cuerpo ya me está fallando... No sé si tendré tiempo de escribir la última escena de Putini...",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "I'll talk to my brother. I'll find a way to help you escape. My body's already giving out... and I may never finish the final act of Putini..."
        },
        [51009940] = {
          ContentES = "Pero, Enola... prométeme que subirás al escenario. Que harás que nuestro Putini se escuche en todo el mundo...",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "But Enola — promise me that you'll take the stage, and share our Putini with the world..."
        },
        [51009941] = {
          ContentES = "“Toda persona que ame cantar merece brillar bajo los reflectores, sea Sola o Charon, rica o pobre...” Ese fue el último deseo de Violet... y se convirtió en mi razón de vivir.",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300,
          Subtitle = "\"Everyone who loves to sing deserves their moment in the spotlight. Solarian or Charon, rich or poor...\" That was Violet's final wish — and it became the truth I live by."
        },
        [51009942] = {
          ContentES = "...Cuando ella murió, canté el último acto de Putini frente a Sig. Estaba destrozado por el dolor... pero en sus ojos vi una chispa renacer de las cenizas.",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300,
          Subtitle = "...After she passed, I sang the finished final act of Putini for Sig. He was hollowed by grief — but when he heard it, his eyes lit with disbelief... and for a moment, I saw hope flicker in the ashes."
        },
        [51009943] = {
          ContentES = "Todavía tenemos la oportunidad de honrarla. Violet vertió su alegría, tristeza, esperanza y anhelo en esa obra. Quiero que el mundo lo escuche, debo asegurarme de que así sea.",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300,
          Subtitle = "We still have a chance to honour her. Violet poured her joy, sorrow, hope, and longing into that script. I want the world to hear it — I need to make sure they do."
        },
        [51009944] = {
          ContentES = "Ambas nacimos para el escenario. La enfermedad se la llevó demasiado pronto, pero yo llevaré su alma a cada escenario, en cada luz.",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300,
          Subtitle = "We were both born for the stage. Illness took her far too soon, but I'll carry her soul in every role I play — in every spotlight I step into."
        },
        [51009945] = {
          ContentES = "Así que, para ayudarte a escapar del control de tu padre... y para cumplir el último deseo de Violet... Sig aceptó interpretar su papel en esta puesta en escena.",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001,
          Subtitle = "So to help you escape your father's grip — and to fulfil Violet's last wish — Sig agreed to play his part in the act."
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentES = "No... imposible. Si eso es cierto, ¿por qué acaba de decir todo lo que dijo...?",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          Subtitle = "No... That can't be... If that's true, then why did she just—?",
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentES = "Porque viniste aquí con tu versión de los hechos ya decidida, Giselle. Y la señora Violetta temía que al contradecirte, podría poner en peligro la vida de su alumna Rosalind.",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001,
          Subtitle = "You came here convinced of her guilt, Giselle. And Ms Violetta couldn't risk provoking you — not with her student Rosalind's safety at stake."
        },
        [51009948] = {
          ContentES = "¿Qué...?",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          Subtitle = "What—?",
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tengo una solicitud... No huiré, te lo prometo. Pero ven conmigo. Me gustaría mostrarte un lugar.",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300,
          Subtitle = "I have a request... I won't run, I promise. Just — come with me. There's somewhere I need to go."
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentES = "Está bien. Pero no creas que podrás hacer ningún truco.",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          Subtitle = "Fine. But don't think you can pull any tricks.",
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentES = "Todo ha sido reconstruido... Pero para mí, cada ladrillo, cada piedra sigue viéndose igual que hace dieciséis años.",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          Subtitle = "It's all been rebuilt... But to me, every brick, every stone still looks just as it did back then.",
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentES = "Violet... He vuelto a verte. Y he traído nuestra obra conmigo.",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          Subtitle = "Violet... I came back to see you. And I brought our work with me.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentES = "Alguien lista finalmente entendió nuestra historia... Y extrañamente, no tengo miedo. Me siento... aliviada. Tal vez porque por fin puedo decirte todo como debe ser... Para Sig... lo siento.",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300,
          Subtitle = "Someone with a sharp eye pieced together our story. Strangely, I'm not scared. I feel... relieved. Maybe because, at long last, I can say this to you properly: I'm sorry. About Sig."
        },
        [51009954] = {
          ContentES = "(Los dedos de Violetta rozan la pared, como si compartiera recuerdos con una amiga que no ha visto en años. Tal vez el momento de despedirse ha llegado, y por eso ha vuelto aquí.)",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          Subtitle = "(Violetta's fingers graze the wall, as if sharing memories with an old friend she hasn't seen in years. Perhaps the time for farewell has come, and that's what brought her back here.)",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Gracias... por permitirme seguir mis caprichos hasta el final.",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          Subtitle = "Thank you... for indulging me.",
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentES = "Entonces, Violetta... Aceptaste las acusaciones por otra razón, porque la muerte de Sig eso no era parte de tu plan. ¿Verdad?",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          Subtitle = "So, Violetta... You went along with the accusations for another reason, didn't you? Because Sig's death — that wasn't part of your plan.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentES = "Fabrice Ruthford. Era un hombre frío y despiadado. Los mineros bajo su mando morían casi de hambre. Incluso sus oficiales de la Escolta no estaban mucho mejor.",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          Subtitle = "Fabrice Ruthford... He was a ruthless, heartless man. The miners under him starved. His Escort officers weren't much better off.",
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ni siquiera con su propia hija mostró ternura. Rechazaba todo lo que ella era, pisoteaba sus sueños, encarcelaba su libertad... Quería moldearla según la vida sin brillo que había planeado para ella.",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          Subtitle = "He showed no mercy — not even to his own daughter. He dismissed everything she was, crushed her dreams, caged her spirit... and forced her into the lifeless future he had planned.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentES = "Y sin embargo... cuando su hija “murió”, ese hombre cruel ignoró todo procedimiento judicial y ejecutó al secuestrador con sus propias manos, sabiendo muy bien que eso le costaría su carrera.",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300,
          Subtitle = "And yet... when his daughter \"died,\" the same heartless man threw aside all legal procedure and executed the kidnapper with his own hands — knowing full well it would cost him his career."
        },
        [51009960] = {
          ContentES = "Había ideado mil planes para enviar una carta al tribunal después de escapar... Suficientes para demostrar la inocencia de Sig. Pero lo que nunca imaginé fue...",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300,
          Subtitle = "I thought of countless ways to slip the truth to the court once I was free. I thought I could save Sig in secret. But the one thing I never imagined—"
        },
        [51009961] = {
          ContentES = "... Que tu padre te amaba mucho más de lo que tú creías.",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          Subtitle = "...Was that your father loved you more than you ever knew.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentES = "... Hubo tantas veces en las que quise confesarlo todo. Pero Hyperborea era solo el punto de partida: su obra debía viajar por todo el mundo. Tenía que cumplir mi promesa... o al menos intentarlo.",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          Subtitle = "...There were so many times I wanted to reveal the truth. But Hyperborea was only the beginning — her story needed to reach the world. I had to keep my promise... or at least, keep trying.",
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentES = "Así que cuando viniste a buscarme, Giselle... sentí un extraño alivio. He formado a muchos niños talentosos a lo largo de los años. Ellos podrán llevar Putini mucho más lejos de lo que yo jamás podría.",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          Subtitle = "So when you came to me, Giselle... I felt oddly relieved. I've trained many gifted children over the years. They can carry Putini farther and wider than I ever could.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentES = "Y todo lo que tenías que hacer... era dejar que Giselle creyera que era cierto. Así podrías limpiar por fin el nombre de Sig.",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001,
          Subtitle = "And all you had to do... was let Giselle believe it was true. So you could finally clear Sig's name."
        },
        [51009965] = {
          ContentES = "... Iré contigo, Giselle. Pero solo después de que liberes a Rosalind Magnus.",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300,
          Subtitle = "...I'll go with you, Giselle. But only after you release Rosalind Magnus."
        },
        [51009966] = {
          ContentES = "Por mí... por Sig y por Violet... no debe sufrir ningún daño.",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300,
          Subtitle = "For my sake... and for Sig and Violet... she must not come to harm."
        },
        [51009967] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "... Ella ya ha dejado Lago Helado.",
          DialogueId = 51009967,
          GUID = "7FB2B6B6",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009968,
          SpeakNpcId = 700302,
          Subtitle = "...She's already left Icelake.",
          TalkActionId = {
            [1] = "700302:Talk01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009968] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Qué?",
          DialogueId = 51009968,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2B6E0",
          NextDialogue = 51009969,
          SpeakNpcId = 700300,
          Subtitle = "What?",
          TalkActionId = {
            [1] = "700300:Shock_Start"
          }
        },
        [51009969] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tú eras su profesora de canto. Deberías saber bien a qué se enfrentaba.",
          DialogueId = 51009969,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2B70A",
          NextDialogue = 51009970,
          SpeakNpcId = 700302,
          Subtitle = "You were her vocal teacher. You should know what she was up against."
        },
        [51009970] = {
          ContentES = "Una avecilla dispuesta a romperse las alas solo para escapar de su jaula... Vosotras dos sois tal para cual.",
          DialogueId = 51009970,
          GUID = "7FB2B734",
          NextDialogue = 51009971,
          SpeakNpcId = 700302,
          Subtitle = "A fledgling willing to break her own wings just to escape the cage... The two of you really are cut from the same cloth."
        },
        [51009971] = {
          ContentES = "Así que todo este tiempo... me mentías.",
          DialogueId = 51009971,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B75E",
          NextDialogue = 51009972,
          SpeakNpcId = 700300,
          Subtitle = "So all this time... you were lying to me.",
          TalkActionId = {
            [1] = "700300:Shock_End"
          }
        },
        [51009972] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "No estaba planeado. Nunca pensé que alguien tan cercano a ti vendría a contratarme para “secuestrarla”. Simplemente... aproveché la oportunidad.",
          DialogueId = 51009972,
          GUID = "7FB2B788",
          NextDialogue = 51009973,
          SpeakNpcId = 700302,
          Subtitle = "It wasn't my plan. I didn't expect someone close to you would come to hire me to \"kidnap\" her. I just... took the chance when it came.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009973] = {
          ContentES = "Mi actuación fue bastante convincente, ¿no? Quizás ha llegado la hora de probar suerte en el escenario.",
          DialogueId = 51009973,
          GUID = "7FB2B7B2",
          NextDialogue = 51009974,
          SpeakNpcId = 700302,
          Subtitle = "Pretty convincing performance, wasn't it? Maybe it's time I tried the stage."
        },
        [51009974] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Ya no quieres ser una Phoxcazadora?",
          DialogueId = 51009974,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "7FB2B7DC",
          NextDialogue = 51009975,
          SpeakNpcId = 100001,
          Subtitle = "You don't want to be a Phoxhunter anymore?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009975] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "Je. Con todo el alboroto por el “secuestro” de la señorita Magnus, tendré que desaparecer por un tiempo de todos modos.",
          DialogueId = 51009975,
          GUID = "7FB2B806",
          NextDialogue = 51009976,
          SpeakNpcId = 700302,
          Subtitle = "Heh. Thanks to the big stir over Lady Magnus's kidnapping, I'll be laying low for a good while anyway."
        },
        [51009976] = {
          ContentES = "En cuanto a Violetta...",
          DialogueId = 51009976,
          GUID = "7FB2B830",
          NextDialogue = 51009977,
          SpeakNpcId = 700302,
          Subtitle = "As for Violetta...",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009977] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "{nickname}, tú decidirás. Ya que descubriste la verdad antes que yo, te corresponde a ti decidir qué será de ella.",
          DialogueId = 51009977,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2B85A",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009978,
          SpeakNpcId = 700302,
          Subtitle = "It's your call, . You uncovered the truth before I could — so you get to decide what happens next.",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009978] = {
          ContentES = "¿Estás segura, Giselle?",
          DialogueId = 51009978,
          GUID = "7FB2B884",
          NextDialogue = 51009979,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure, Giselle?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009979] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "No lo sé. <H>Si revelamos la verdad, ella podría perderlo todo, su nombre, su sueño. Pero si guardamos silencio... el nombre de Sig nunca será limpiado.</>",
          DialogueId = 51009979,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B8AE",
          NextDialogue = 51009980,
          SpeakNpcId = 700302,
          Subtitle = "I don't know. If we tell the world, she could lose everything — her name, her dream, all of it. But if we keep it quiet... then Sig's name will never be cleared."
        },
        [51009980] = {
          ContentES = "Ya no sé qué pensar. Tal vez sea mejor que seas tú quien decida.",
          DialogueId = 51009980,
          GUID = "7FB2B8D8",
          NextDialogue = 51009981,
          SpeakNpcId = 700302,
          Subtitle = "I can't think straight right now. Maybe handing the choice to you really is best."
        },
        [51009981] = {
          ContentES = "Si eres tú quien toma esta decisión... la aceptaré.",
          DialogueId = 51009981,
          GUID = "7FB2B902",
          NextOptions = {
            [1] = 510098911,
            [2] = 510098912
          },
          SpeakNpcId = 700300,
          Subtitle = "If it's your decision... I'll readily accept it.",
          TalkActionId = {
            [1] = "700300:Agree"
          },
          bForbidSkipOptions = true
        },
        [51009982] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "Giselle.",
          DialogueId = 51009982,
          GUID = "7FB2B92C",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009983,
          SpeakNpcId = 100001,
          Subtitle = "Giselle.",
          TalkActionId = {
            [1] = "700302:Talk03_Start"
          }
        },
        [51009983] = {
          ContentES = "Te escucho.",
          DialogueId = 51009983,
          GUID = "7FB2B956",
          NextDialogue = 51009984,
          SpeakNpcId = 700302,
          Subtitle = "I'm listening."
        },
        [51009984] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Podríamos... mantenerlo en secreto? ¿No sacar todo esto a la luz?",
          DialogueId = 51009984,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2B980",
          NextDialogue = 51009985,
          SpeakNpcId = 100001,
          Subtitle = "Can we... keep it quiet? Not bring this all to light?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009985] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sig dio su vida y su honor para que la señora Violetta pudiera llevar Putini al mundo. No creo que quisiera que todo terminara así.",
          DialogueId = 51009985,
          GUID = "7FB2B9AA",
          NextDialogue = 51009986,
          SpeakNpcId = 100001,
          Subtitle = "Sig bore the blame — and even gave his life — so Ms Violetta could share Putini with the world. I don't think this is how he'd want things to end."
        },
        [51009986] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "...De acuerdo. Lo entiendo.",
          DialogueId = 51009986,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2B9D4",
          NextDialogue = 51009987,
          SpeakNpcId = 700302,
          Subtitle = "...All right. I understand.",
          TalkActionId = {
            [1] = "700302:Agree",
            [2] = "100001:Explain02_End"
          }
        },
        [51009987] = {
          ContentES = "¿Giselle?",
