          DialogueId = 51009989,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2BA52",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009990,
          SpeakNpcId = 700300,
          Subtitle = "I'm truly grateful.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009990] = {
          ContentES = "En ese caso, estamos de acuerdo.",
          DialogueId = 51009990,
          GUID = "7FB2BA7C",
          NextDialogue = 51009991,
          SpeakNpcId = 700302,
          Subtitle = "Then it's settled, I suppose.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009991] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah, y... ¿me honraríais con vuestra presencia en la representación dentro de dos días? Os reservaré los mejores asientos.",
          DialogueId = 51009991,
          GUID = "7FB2BAA6",
          NextDialogue = 51009992,
          SpeakNpcId = 700300,
          Subtitle = "In that case... would you both honour me with your presence at the performance two days from now? I'll have the finest seats in the house prepared."
        },
        [51009992] = {
          ContentES = "¿Una representación...?",
          DialogueId = 51009992,
          GUID = "7FB2BAD0",
          NextDialogue = 51009993,
          SpeakNpcId = 700302,
          Subtitle = "A performance...?"
        },
        [51009993] = {
          ContentES = "Sí, Putini. Considérala como una representación de despedida para Rosalind. Es su obra favorita.",
          DialogueId = 51009993,
          GUID = "7FB2BAFA",
          NextDialogue = 51010006,
          SpeakNpcId = 700300,
          Subtitle = "Yes — Putini. Think of it as a send-off for Rosalind... It's her favourite play."
        },
        [51009994] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entiendo lo que hiciste, señora Violetta. Pero no podemos permitir que un hombre sea recordado como un asesino, ni siquiera después de su muerte.",
          DialogueId = 51009994,
          GUID = "7FB2BB24",
          LookAt = {
            [1] = "700300:n(100001)"
