          NextDialogue = 51009995,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100001:n(700300)"}},
PlayAnimation{ActorId{100001},AnimationId{"Talk01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I understand why you did it, Ms Violetta. But we can't let an innocent man be remembered as a murderer even in death."
        },
        [51009995] = {
          ContentES = "Sig ya no está entre nosotros. Pero aún tenemos la oportunidad de limpiar su nombre.",
          DialogueId = 51009995,
          GUID = "7FB2BB4E",
          NextDialogue = 51009996,
          SpeakNpcId = 100001,
          Subtitle = "Sig's gone. But we still have a chance to clear his name."
        },
        [51009996] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "{nickname}... Gracias.",
          DialogueId = 51009996,
          GUID = "7FB2BB78",
          NextDialogue = 51009997,
          SpeakNpcId = 700302,
          Subtitle = "...Thank you, .",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009997] = {
          ContentES = "Sig te secuestró por dinero, sí. Pero no era un asesino. La verdad debe salir a la luz.",
          DialogueId = 51009997,
          GUID = "7FB2BBA2",
          NextDialogue = 51009998,
          SpeakNpcId = 100001,
          Subtitle = "Sig did kidnap you for money. But that doesn't make him a murderer. The truth deserves to be heard."
        },
        [51009998] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentES = "Señora Violetta... cuando esto salga a la luz, podrías perderlo todo: tu reputación, tu carrera...",
          DialogueId = 51009998,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2BBCC",
          NextDialogue = 51009999,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta... once this is made public, it may cost you everything. Your reputation, your career..."
        },
        [51009999] = {
          ContentES = "Lo entiendo. Pero está bien así... Perdóname, Violet. Nuestro sueño deberá seguir vivo a través de estos jóvenes.",
          DialogueId = 51009999,
          GUID = "7FB2BBF6",
          NextDialogue = 51010000,
          SpeakNpcId = 700300,
          Subtitle = "I understand. But that's all right. I'm sorry, Violet. Our dream... will have to live on through the children now."
        },
        [51010000] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "En ese caso, estamos de acuerdo.",
          DialogueId = 51010000,
          GUID = "7FB2BC20",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51010001,
          SpeakNpcId = 700302,
          Subtitle = "Then it's settled, I suppose."
        },
        [51010001] = {
          ContentES = "Última cosa...",
          DialogueId = 51010001,
          GUID = "7FB2BC4A",
          NextDialogue = 51010002,
          SpeakNpcId = 700300,
          Subtitle = "One last thing..."
        },
        [51010002] = {
          ContentES = "¿Hmm? Es un poco tarde para cambiar de opinión.",
          DialogueId = 51010002,
          GUID = "7FB2BC74",
          NextDialogue = 51010003,
          SpeakNpcId = 700302,
          Subtitle = "Hm? If you're thinking of backing out, it's a bit late for that.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010003] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentES = "Oh, no. Solo quisiera invitaros a la representación dentro de dos días. Considérenla mi canto del cisne. Os reservaré los mejores asientos.",
          DialogueId = 51010003,
          GUID = "7FB2BC9E",
          NextDialogue = 51010004,
          SpeakNpcId = 700300,
          Subtitle = "Nothing of the sort. I'd simply like to invite you both to a performance — two nights from now. Think of it as my swan song. I'll make sure the best seats are ready.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010004] = {
          ContentES = "¿Tu canto del cisne...?",
          DialogueId = 51010004,
          GUID = "7FB2BCC8",
          NextDialogue = 51010005,
          SpeakNpcId = 700302,
          Subtitle = "Your swan song...?"
        },
        [51010005] = {
          ContentES = "Sí. Putini. Todo comenzó con esta obra, y es justo que también termine con ella.",
          DialogueId = 51010005,
          GUID = "7FB2BCF2",
          NextDialogue = 51010006,
          SpeakNpcId = 700300,
          Subtitle = "Yes. Putini. It all began with this play — and it's only right it ends with it too."
        }
      }
    end
  },
