          NextDialogue = 51010009,
          SpeakNpcId = 700300,
          Subtitle = "..."
        },
        [51010009] = {
          ContentES = "No me malinterpretes, iré. Pero digamos que para una “media fugitiva”, es mejor no llamar demasiado la atención.",
          DialogueId = 51010009,
          GUID = "7FB2BD9A",
          NextDialogue = 51010010,
