          GUID = "7FB2BEC0",
          NextDialogue = 51010017,
          SpeakNpcId = 700300,
          Subtitle = "It's just...",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010017] = {
          ContentES = "... Estás pensando en la Señorita Rosalind, ¿verdad?",
          DialogueId = 51010017,
          GUID = "7FB2BEEA",
          NextDialogue = 51010018,
          SpeakNpcId = 100001,
          Subtitle = "You're thinking of Miss Rosalind?"
        },
        [51010018] = {
          ContentES = "Mmm. Se suponía que iba a ser su representación de despedida. Pero ni siquiera sé si todavía está en Lago Helado... o si podrá asistir a su obra favorita.",
          DialogueId = 51010018,
          GUID = "7FB2BF14",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700300:n(700302)"
          },
          NextDialogue = 51010019,
          SpeakNpcId = 700300,
          Subtitle = "Mm. I meant this to be her send-off... but I don't even know if she's still in Icelake. Or if she'll get to see the play she loves most."
        },
        [51010019] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001564,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentES = "No me mires. Para evitar que sus padres la encuentren, preferí no conocer su escondite.",
          DialogueId = 51010019,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2BF3E",
          NextOptions = {
            [1] = 510099291,
            [2] = 510099292
          },
          SpeakNpcId = 700302,
          Subtitle = "Don't look at me. I've no clue where she is now either. Figured the less I know, the harder it is for her parents to track her down."
        },
        [51010020] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentES = "Esperemos que sí... Oh, {nickname}.",
          DialogueId = 51010020,
          FacialId = {
            [1] = "700302:CM_Idle",
            [2] = "700300:CM_Smile01"
          },
          GUID = "7FB2BF68",
          SpeakNpcId = 700300,
          Subtitle = "Let's hope so... Oh, ."
        },
        [51010021] = {
          ContentES = "Has relacionado tres eventos que parecían no tener conexión... para hacerlos parte de una historia con un final feliz. Tu mente y determinación me impresionan.",
          DialogueId = 51010021,
          GUID = "7FB2BF92",
          NextDialogue = 51010022,
          SpeakNpcId = 700300,
          Subtitle = "You tied together three threads no one thought related... and led them to a joyful ending. Your sharp mind and resolve are remarkable."
        },
        [51010022] = {
          ContentES = "Así que tengo otro encargo para ti: se trata de otro de mis alumnos. La recompensa no es un problema. Pasa a verme al teatro cuando tengas tiempo.",
          DialogueId = 51010022,
          GUID = "7FB2BFBC",
          NextDialogue = 51010023,
          SpeakNpcId = 700300,
          Subtitle = "Which brings me to another request — it concerns another of my students. I hope you'll take the case. The fee will be fair, of course. Just visit me at the theatre when you have a moment."
        },
        [51010023] = {
          ContentES = "Pero no esta noche, esta noche pertenece a la música y al viaje. Deja tus preocupaciones atrás... y disfruta de esta noche inolvidable.",
          DialogueId = 51010023,
          GUID = "7FB2BFE6",
          SpeakNpcId = 700300,
          Subtitle = "But not tonight — tonight is for music, and voyage. Leave your burdens behind — and let this be a night to remember."
        },
        [51010024] = {
          ContentES = "Encuentras los asientos reservados por Violetta y te acomodas, esperando a que se levante el telón.",
          DialogueId = 51010024,
          GUID = "7FB2C010",
          NextDialogue = 51010025,
          Subtitle = "You find the seats Violetta reserved for you and settle in, waiting for the curtain to rise."
        },
        [51010025] = {
          ContentES = "Mientras las luces se apagan poco a poco, una potente voz de soprano se eleva tras el telón, llenando el teatro de una magia indescriptible.",
          DialogueId = 51010025,
          GUID = "7FB2C03A",
          NextDialogue = 51010026,
          Subtitle = "As the house lights dim, a powerful soprano unfurls from behind the curtain, flooding the theatre with wonder."
        },
        [51010026] = {
          ContentES = "El público contiene la respiración. Este silencio profundo te pone casi inquietante.",
          DialogueId = 51010026,
          GUID = "7FB2C064",
          NextDialogue = 51010027,
          Subtitle = "The audience holds its breath. The silence is so deep, it unsettles you."
        },
        [51010027] = {
          ContentES = "Es difícil contener tus exclamaciones ante las escenas más espectaculares, temes que un suspiro de admiración interrumpa la magia.",
          DialogueId = 51010027,
          GUID = "7FB2C08E",
          NextDialogue = 51010028,
          Subtitle = "It's hard to hold back a gasp at the dazzling moments — you're almost afraid the sound of your spontaneous awe might spoil the magic."
        },
        [51010028] = {
          ContentES = "Pero tus preocupaciones se desvanecen cuando cae la última nota, incluso olvidas aplaudir.",
          DialogueId = 51010028,
          GUID = "7FB2C0B8",
          Subtitle = "But your worries melt away — by the time the final note falls, you're so mesmerised, you've forgotten even to applaud."
        },
        [51010029] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Uf... Vaya espectáculo. Casi me hizo olvidar cuánto detesto los lugares cerrados y llenos de gente.",
          DialogueId = 51010029,
          GUID = "7FB2C0E2",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010030,
          SpeakNpcId = 700302,
          Subtitle = "Whew. That was quite the show. Almost made me forget how much I hate crowded, enclosed spaces."
        },
        [51010030] = {
          ContentES = "Creo que por fin entiendo por qué el escenario tiene tanta magia para la gente.",
          DialogueId = 51010030,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C10C",
          NextDialogue = 51010031,
          SpeakNpcId = 100001,
          Subtitle = "I think I finally get why the stage holds such magic for people.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010031] = {
          ContentES = "Solo espero que la gente deje de pedirme que los secuestre a sí mismos. No es exactamente la carrera que tenía en mente.",
          DialogueId = 51010031,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C136",
          NextDialogue = 51010032,
          SpeakNpcId = 700302,
          Subtitle = "I just hope folks stop asking me to kidnap themselves. Not exactly the career path I had in mind.",
          TalkActionId = {
            [1] = "700302:Confident_Start",
            [2] = "100001:Talk02R_End"
          }
        },
        [51010032] = {
          ContentES = "Aunque, para ser honesta, no estoy mejor. Yo también me encerré en mis obsesiones durante años.",
          DialogueId = 51010032,
          GUID = "7FB2C160",
          NextDialogue = 51010033,
          SpeakNpcId = 700302,
          Subtitle = "Then again, who am I to judge? I've spent half my life stuck in my own mess."
        },
        [51010033] = {
          ContentES = "Tengo curiosidad... ¿por qué este asunto te importaba tanto?",
          DialogueId = 51010033,
          GUID = "7FB2C18A",
          NextDialogue = 51010034,
          SpeakNpcId = 100001,
          Subtitle = "Can I ask... why are you so invested in this case?"
        },
        [51010034] = {
          ContentES = "... ¿Puedo no responder a eso?",
          DialogueId = 51010034,
          GUID = "7FB2C1B4",
          NextDialogue = 51010035,
          SpeakNpcId = 700302,
          Subtitle = "...Do I have to answer that?"
        },
        [51010035] = {
          ContentES = "Solo si quieres.",
          DialogueId = 51010035,
          GUID = "7FB2C1DE",
          NextDialogue = 51010036,
          SpeakNpcId = 100001,
          Subtitle = "Only if you want to.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "700302:Confident_End"
          }
        },
        [51010036] = {
          ContentES = "Está bien... no tiene sentido hacer misterios con alguien tan {性别:sincero|sincera} como tú.",
          DialogueId = 51010036,
          GUID = "7FB2C208",
          NextDialogue = 51010037,
          SpeakNpcId = 700302,
          Subtitle = "...Okay. No point playing coy with someone as sincere and kind as you.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51010037] = {
          ContentES = "Donat seguramente te contó que había denunciado a Sig. Pues bien, la persona a la que acudió... fui yo.",
          DialogueId = 51010037,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2C232",
          NextDialogue = 51010038,
          SpeakNpcId = 700302,
          Subtitle = "Donat told you he turned Sig in, right? The person he came to... was me."
        },
        [51010038] = {
          ContentES = "Al principio, para no asustarlo, quería ir a negociar sola y liberar al rehén sin hacer olas. Pero cuando me di cuenta de que se trataba de la hija de mi superior, dudé... y acabé presentando un informe.",
          DialogueId = 51010038,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2C25C",
          NextDialogue = 51010039,
          SpeakNpcId = 700302,
          Subtitle = "At first, to avoid tipping off the culprit, I planned to go in alone, talk Sig down, and get the hostage out safely. But when I realised who she was — my superior's daughter — I hesitated. Ended up reporting it up the chain instead."
        },
        [51010039] = {
          ContentES = "Y... ya conoces el resto. Su padre perdió el control, rechazó mi propuesta y lanzó un asalto completo.",
          DialogueId = 51010039,
          GUID = "7FB2C286",
          NextDialogue = 51010040,
          SpeakNpcId = 700302,
          Subtitle = "And... you know the rest. Her father lost it, rejected my proposal, and launched a full-on raid."
        },
        [51010040] = {
          ContentES = "Si hubiera seguido mi plan... tal vez nada de esto habría sucedido.",
          DialogueId = 51010040,
          GUID = "7FB2C2B0",
          NextDialogue = 51010041,
          SpeakNpcId = 700302,
          Subtitle = "If I'd just stuck to my plan... maybe none of this would've happened."
        },
        [51010041] = {
          ContentES = "Podría haber dificultado un poco las cosas para Violetta... pero al menos Sig no habría muerto por algo que no hizo.",
          DialogueId = 51010041,
          GUID = "7FB2C2DA",
          NextDialogue = 51010042,
          SpeakNpcId = 700302,
          Subtitle = "It might've made things a bit harder for Violetta... but at least Sig wouldn't have died for something he didn't do."
        },
        [51010042] = {
          ContentES = "Giselle...",
          DialogueId = 51010042,
          GUID = "7FB2C304",
          NextDialogue = 51010043,
          SpeakNpcId = 100001,
          Subtitle = "Giselle...",
          TalkActionId = {
            [1] = "700302:Talk02_End"
          }
        },
        [51010043] = {
          ContentES = "Entiendo por qué lo hizo: cualquier padre que perdiera a su hija habría hecho lo mismo. Pero la justicia debe llegar después de que toda la verdad salga a la luz, no antes.",
          DialogueId = 51010043,
          GUID = "7FB2C32E",
          NextDialogue = 51010044,
          SpeakNpcId = 700302,
          Subtitle = "I get why he did it — any parent who lost their child would. But justice should come after the full truth comes to light, not before.",
          TalkActionId = {
            [1] = "700302:Sigh_Start"
          }
        },
        [51010044] = {
          ContentES = "No fue por eso que me uní a la Escolta.",
          DialogueId = 51010044,
          GUID = "7FB2C358",
          NextDialogue = 51010045,
          SpeakNpcId = 700302,
          Subtitle = "I didn't join the Escort for that."
        },
        [51010045] = {
          ContentES = "Entonces la Escolta cometieron una tontería al perder a alguien que realmente representaba la justicia.",
          DialogueId = 51010045,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C382",
          NextDialogue = 51010046,
          SpeakNpcId = 100001,
          Subtitle = "Then the Escort was a fool to lose someone who actually stood for justice.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51010046] = {
          ContentES = "... ¿Era eso un cumplido?",
          DialogueId = 51010046,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C3AC",
          NextDialogue = 51010047,
          SpeakNpcId = 700302,
          Subtitle = "Was that a compliment?",
          TalkActionId = {
            [1] = "700302:Sigh_End"
          }
        },
        [51010047] = {
          ContentES = "En fin, lo hecho, hecho está. Veré si puedo revelar parte de la verdad, manteniendo en secreto la identidad de Violetta.",
          DialogueId = 51010047,
          GUID = "7FB2C3D6",
          NextDialogue = 51010048,
          SpeakNpcId = 700302,
          Subtitle = "Anyway, what's done is done. I'll see if I can reveal part of the truth — without exposing Violetta, of course.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51010048] = {
          ContentES = "Sin Enola, no tendrás ninguna prueba para convencer a la Escolta de reabrir la investigación.",
          DialogueId = 51010048,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C400",
          NextDialogue = 51010049,
          SpeakNpcId = 100001,
          Subtitle = "But without Enola herself, there's no solid proof. The Escort wouldn't reopen a case over just hearsay.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010049] = {
          ContentES = "¿La Escolta? Inútil. Se lo contaré todo a la prensa. El rumor es un juez mucho más poderoso que archivos polvorientos.",
          DialogueId = 51010049,
          GUID = "7FB2C42A",
          NextDialogue = 51010050,
          SpeakNpcId = 700302,
          Subtitle = "The Escort? Nah, I'm not going to them. I'll tell the local papers. Let the story spread. The public makes a better jury than some dusty court records.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010050] = {
          ContentES = "¿Crees que realmente funcionará...?",
          DialogueId = 51010050,
          GUID = "7FB2C454",
          NextDialogue = 51010051,
          SpeakNpcId = 100001,
          Subtitle = "Will that really work...?"
        },
        [51010051] = {
          ContentES = "A la gente le encantan los secretos ocultos. Creer que han descubierto lo que se esconde tras las apariencias les hace sentirse inteligentes. Yo solo... voy a aprovechar eso un poco.",
          DialogueId = 51010051,
          GUID = "7FB2C47E",
          NextDialogue = 51010052,
          SpeakNpcId = 700302,
          Subtitle = "People love hidden truths. Believing they know more than others about what's beneath the surface makes them feel smart. I'm just going to take advantage of that."
        },
        [51010052] = {
          ContentES = "¡Uy!",
          DialogueId = 51010052,
          GUID = "7FB2C4A8",
          IsBlack = 1,
          NextDialogue = 51010053,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint1_20023305"},MoveSpeed{250},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700305)"}},
LookAt{LookAtDescription{"700302:n(700305)"}},
TurnTo{TurnToDescription{"700305:n(100001)"}}
},
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{ActorId{700302},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{ActorId{700305},AnimationId{"Explain02_Start"},Duration{1}}
}}]],
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "...Whoops!"
        },
        [51010053] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡P-perdón! ¡No te vi! ¿Estás bien? ¿No te hice daño?",
          DialogueId = 51010053,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2C4D2",
          NextDialogue = 51010054,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "S—Sorry! I didn't see you! Are you okay? Did I hurt you?"
        },
        [51010054] = {
          ContentES = "Estoy bien. Solo ten cuidado, ¿vale?",
          DialogueId = 51010054,
          GUID = "7FB2C4FC",
          NextDialogue = 51010055,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just be more careful next time, alright?",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010055] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mmm...",
          DialogueId = 51010055,
          GUID = "7FB2C526",
          NextDialogue = 51010056,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Mm...",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010056] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Tengo algo en mi cara?",
          DialogueId = 51010056,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2C550",
          NextDialogue = 51010057,
          SpeakNpcId = 100001,
          Subtitle = "What? Something on my face?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010057] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No, nada en absoluto... Jiji... ¡Gracias por las hierbas! ¡Oh no, voy a llegar tarde!",
          DialogueId = 51010057,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2C57A",
          NextDialogue = 51010058,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Nope! Hehe... Thanks for the herbs! Oh no, I'm gonna be late!",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010058] = {
          ContentES = "¿Hierbas...? Espera, ¡dejaste caer algo!",
          DialogueId = 51010058,
          GUID = "7FB2C5A4",
          NextDialogue = 51010059,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint2_20023305"},MoveSpeed{250},Visibility{"Hide"}},
PlayAnimation{ActorId{100001},AnimationId{"Nvzhu_Story_StretchHand_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Herbs...? Wait— You dropped something!"
        },
        [51010059] = {
          ContentES = "¡Quédate con ello!",
          DialogueId = 51010059,
          GUID = "7FB2C5CE",
          NextDialogue = 51010060,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "You can keep it!!!"
        },
        [51010060] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "En serio... los jóvenes de hoy siempre están tan apurados.",
          DialogueId = 51010060,
          GUID = "7FB2C5F8",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010061,
          SpeakNpcId = 700302,
          Subtitle = "Seriously. Kids these days — always a whirlwind.",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010061] = {
          ContentES = "¿Por qué me dejó esto...? Tiene un bordado encima... ¿Es su nombre?",
          DialogueId = 51010061,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C622",
          NextDialogue = 51010062,
          SpeakNpcId = 100001,
          Subtitle = "Why'd she leave this...? Huh, there's embroidery — is this her name...?"
        },
        [51010062] = {
          ContentES = "... ¿Putini?",
          DialogueId = 51010062,
          GUID = "7FB2C64C",
          NextDialogue = 51010063,
          SpeakNpcId = 100001,
          Subtitle = "...Putini?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010063] = {
          ContentES = "Si algún día encuentras una chica llamada Putini... espero que me reconozcas. Y te prometo que yo te reconoceré.",
          DialogueId = 51010063,
          GUID = "7FB2C676",
          IsBlack = 1,
          NextDialogue = 51010064,
          Subtitle = "If one day, you meet a girl named Putini... I hope you'll recognise me. And I promise — I'll recognise you."
        },
        [51010064] = {
          ContentES = "¿Qué te hace sonreír así?",
          DialogueId = 51010064,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "7FB2C6A0",
          NextDialogue = 51010065,
          SpeakNpcId = 700302,
          Subtitle = "What's so funny?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010065] = {
          ContentES = "Si ni siquiera tú la reconociste... tal vez Violetta no sea la única que tiene mil rostros.",
          DialogueId = 51010065,
          GUID = "7FB2C6CA",
          NextDialogue = 51010066,
          SpeakNpcId = 100001,
          Subtitle = "If even you didn't recognise her... maybe Violetta's not the only one with a thousand faces.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010066] = {
          ContentES = "La vida nunca se juega en un solo acto. Nos veremos en una nueva escena. Hasta entonces... buen viaje, Señorita Caja.",
          DialogueId = 51010066,
          GUID = "7FB2C6F4",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "Life's a play with more than one act. We'll meet again — on a new stage. Until then... safe travels, Miss Crate."
        },
        [51010067] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 51010067,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2C71E",
          NextDialogue = 51010068,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51010068] = {
          ContentES = "Buenos días, {nickname}. ¿Por qué esa cara triste?",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300,
          Subtitle = "Morning, . Why the gloomy face?"
        },
        [51010069] = {
          ContentES = "Señora Violetta...",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta..."
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentES = "Vamos, no hace falta decir más. Soy yo quien se retira, no tú. No tienes que sentir pena por mí.",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          Subtitle = "Now, now — no need to feel sorry for me. I'm stepping down, not dying.",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentES = "Simplemente hiciste lo que haría cualquiera con conciencia. No dejes que eso te pese. Piénsalo así: solo ayudaste a una fugitiva a encontrar el camino de regreso a casa, nada más.",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300,
          Subtitle = "You simply did what anyone with a conscience would. Don't let it weigh on you. Think of it this way: you just helped a runaway find her way home, that's all."
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentES = "Parece que todos están aquí.",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302,
          Subtitle = "Looks like everyone's here."
        },
        [51010073] = {
          ContentES = "Señorita Giselle, llegas justo a tiempo. Aquí tienes tus entradas.",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          Subtitle = "Miss Giselle — perfect timing. Here are your tickets.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentES = "Gracias. Ya he contactado a mis antiguos compañeros de la Escolta: no intervendrán hasta que termine la representación.",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          Subtitle = "Thanks. I've spoken to my old Escort contacts — they'll hold off until the curtain falls.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentES = "Muy agradecida. La representación está a punto de empezar, será mejor que vaya entre bastidores.",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          Subtitle = "Much appreciated. The show's about to start — I'd better get backstage.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentES = "Entonces entremos también. Puede que haya contribuido a poner fin a su carrera en el escenario... pero debo admitir que tengo ganas de ver su canto del cisne.",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302,
          Subtitle = "Let's head in too, then. I may have played a part in ending her stage career... but I've got to admit, I'm looking forward to her swan song."
        },
        [51010077] = {
          ContentES = "Vamos.",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001,
          Subtitle = "Let's."
        },
        [51010078] = {
          ContentES = "Encuentras los asientos reservados por Violetta y te acomodas, esperando a que se levante el telón.",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079,
          Subtitle = "You find the seats Violetta reserved for you and settle in, waiting for the curtain to rise."
        },
        [51010079] = {
          ContentES = "Mientras las luces se apagan poco a poco, una potente voz de soprano se eleva tras el telón, llenando el teatro de una magia indescriptible.",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080,
          Subtitle = "As the house lights dim, a powerful soprano unfurls from behind the curtain, flooding the theatre with wonder."
        },
        [51010080] = {
          ContentES = "El público contiene la respiración. Este silencio profundo te pone casi inquietante.",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081,
          Subtitle = "The audience holds its breath. The silence is so deep, it unsettles you."
        },
        [51010081] = {
          ContentES = "Es difícil contener tus exclamaciones ante las escenas más espectaculares, temes que un suspiro de admiración interrumpa la magia.",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082,
          Subtitle = "It's hard to hold back a gasp at the dazzling moments — you're almost afraid the sound of your spontaneous awe might spoil the magic."
        },
        [51010082] = {
          ContentES = "Pero tus preocupaciones se desvanecen —",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083,
          Subtitle = "But your worries melt away —"
        },
        [51010083] = {
          ContentES = "Cuando cae la última nota, incluso olvidas aplaudir.",
          DialogueId = 51010083,
          GUID = "7FB2C9BE",
          Subtitle = "By the time the final note falls, you're so mesmerised, you've forgotten even to applaud."
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Giselle, me debes una explicación!",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Giselle — you owe me an explanation!",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Oh? ¿Y qué podría necesitar que le explique el todopoderoso Lord Ruthford?",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          Subtitle = "Oh? And what could the all-knowing Lord Ruthford possibly need me to explain?",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          ContentES = "Le dijiste a la Escolta que Violetta era Enola, pero cuando llegué a los bastidores con mis hombres... ¡ya no quedaba nadie!",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304,
          Subtitle = "You told the Escort Violetta was Enola — but when I brought my men backstage, there was no one there!"
        },
        [51010087] = {
          ContentES = "Ah, eso. No me esperaba que vinieras en persona. Qué implicación, realmente.",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302,
          Subtitle = "Ah, that. Didn't think you'd come in person. Very hands-on of you, sir."
        },
        [51010088] = {
          ContentES = "¡No te pongas lista conmigo! ¡Llévame con Enola, ahora!",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304,
          Subtitle = "Don't get clever with me! Take me to Enola — now!"
        },
        [51010089] = {
          ContentES = "Parece que olvidas un detalle: ya no soy parte de La Escolta. Y tú tampoco. Simplemente transmití una información... como una simple ciudadana.",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302,
          Subtitle = "I think you're forgetting something — I'm not with the Escort anymore. And neither are you. I just passed on a tip... as a civilian."
        },
        [51010090] = {
          ContentES = "Así que no, no acepto tus órdenes. Pero bueno siempre puedes presentar un encargo a Giselle, la Phoxcazadora.",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302,
          Subtitle = "So no, I don't take orders from you. But hey — you could always file a commission with Giselle the Phoxhunter."
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tch... ¡Está bien! ¡Entonces te contrataré!",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          Subtitle = "Tch... Fine! Then I'll file one!",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentES = "Perfecto. Rechazo el encargo.",
          DialogueId = 51010092,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CB38",
          NextDialogue = 51010093,
          SpeakNpcId = 700302,
          Subtitle = "Great. I refuse to take the job.",
          TalkActionId = {
            [1] = "700302:Talk01_Start"
          }
        },
        [51010093] = {
          ContentES = "¿Te estás burlando de mí?",
          DialogueId = 51010093,
          GUID = "7FB2CB62",
          NextDialogue = 51010094,
          SpeakNpcId = 700304,
          Subtitle = "You messing with me!?"
        },
        [51010094] = {
          ContentES = "Bueno, considerando que actualmente soy sospechosa del secuestro de la hija de un conde, digamos que mis servicios están temporalmente suspendidos.",
          DialogueId = 51010094,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CB8C",
          NextDialogue = 51010095,
          SpeakNpcId = 700302,
          Subtitle = "Well, seeing as I'm currently a suspect in the kidnapping of an earl's daughter, let's just say my services are temporarily suspended."
        },
        [51010095] = {
          ContentES = "En el fondo, si hubieras aceptado la solución pacífica que propuse en su momento, nada de esto habría ocurrido.",
          DialogueId = 51010095,
          GUID = "7FB2CBB6",
          NextDialogue = 51010096,
          SpeakNpcId = 700302,
          Subtitle = "Truth is, if you'd listened back then and gone with the peaceful route I proposed, none of this would've happened."
        },
        [51010096] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tú... fui una tonta por creer alguna vez que encontrarías a Enola.",
          DialogueId = 51010096,
          GUID = "7FB2CBE0",
          NextDialogue = 51010097,
          SpeakNpcId = 700304,
          Subtitle = "You... I was a fool to ever believe you'd find Enola.",
          TalkActionId = {
            [1] = "700302:Talk01_End"
          }
        },
        [51010097] = {
          ContentES = "Enola... mi hija... La encontraré yo misma. ¡Y a ti no quiero volver a verte jamás!",
          DialogueId = 51010097,
          GUID = "7FB2CC0A",
          NextDialogue = 51010098,
          SpeakNpcId = 700304,
          Subtitle = "Enola... my daughter... I'll find you myself. And you — don't ever show your face again!"
        },
        [51010098] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentES = "Con gusto.",
          DialogueId = 51010098,
          GUID = "7FB2CC34",
          NextDialogue = 51010099,
          Scripts = "MoveTo{ActorId{700304},TargetPoint{\"FabricePoint_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700302,
          Subtitle = "Gladly.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010099] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Estás bien, Giselle?",
          DialogueId = 51010099,
          FinalCamera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2CC5E",
          NextDialogue = 51010100,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},TargetPoint{"NvzhuPoint_20023305"},MoveSpeed{150},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700302)"}},
LookAt{LookAtDescription{"700302:n(100001)"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You alright, Giselle?",
          ToFinalCameraBlendTime = 5
        },
        [51010100] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mejor que nunca. No podía hablarle así cuando estaba en la Escolta. Se sintió de maravilla.",
          DialogueId = 51010100,
          GUID = "7FB2CC88",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010101,
          SpeakNpcId = 700302,
          Subtitle = "Never better. Couldn't talk to him like that when I was in the Escort. Felt pretty darn good."
        },
        [51010101] = {
          ContentES = "¿Quién era exactamente?",
          DialogueId = 51010101,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2CCB2",
          NextDialogue = 51010102,
          SpeakNpcId = 100001,
          Subtitle = "Who was that, anyway?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010102] = {
          ContentES = "Fabrice Ruthford. El padre de Violetta. Tan impulsivo como hace dieciséis años.",
          DialogueId = 51010102,
          GUID = "7FB2CCDC",
          NextDialogue = 51010103,
          SpeakNpcId = 700302,
          Subtitle = "Fabrice Ruthford. Violetta's father. Still as hot-headed as he was sixteen years ago.",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010103] = {
          ContentES = "¿Y entonces dónde está la señorita Violetta?",
          DialogueId = 51010103,
          GUID = "7FB2CD06",
          NextDialogue = 51010104,
          SpeakNpcId = 100001,
          Subtitle = "Then where's Ms Violetta?"
        },
        [51010104] = {
          ContentES = "Desaparecida. Cuando Fabrice irrumpió, los bastidores ya estaban vacíos.",
          DialogueId = 51010104,
          GUID = "7FB2CD30",
          NextDialogue = 51010105,
          SpeakNpcId = 700302,
          Subtitle = "Gone. Backstage was already empty by the time he barged in."
        },
        [51010105] = {
          ContentES = "¡Uy!",
          DialogueId = 51010105,
          GUID = "7FB2CD5A",
          IsBlack = 1,
          NextDialogue = 51010106,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint1_20023305"},MoveSpeed{250},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700305)"}},
LookAt{LookAtDescription{"700302:n(700305)"}},
