          DialogueId = 51103032,
          Duration = 7,
          GUID = "7FEE5A88",
          NextDialogue = 51103033,
          SpeakNpcId = 700323,
          Subtitle = "This one's a touch trickier — watch carefully."
        },
        [51103033] = {
          Content = "这机枢门的位置会根据牵引的方向不同而产生变化，所以你得把它停在合适的位置，然后钻进去拿奖励，明白了吧？",
          DialogueId = 51103033,
          GUID = "7FEE5AB2",
          SpeakNpcId = 700323,
          Subtitle = "The gate shifts its position with each pull. Halt it at just the right point, and you'll be able to slip through and claim the reward. Clear?"
