          GUID = "7FEE5B06",
          NextDialogue = 51103042,
          SpeakNpcId = 700323,
          Subtitle = "Hah! None who’ve savoured the wonders of fine craft ever leave unimpressed. And don't worry — I've set up plenty more in Mistwharf. You're welcome to test yourself further.",
          TalkActionId = {
            [1] = "700323:Agree"
          }
        },
        [51103037] = {
          Content = "奖励太少了。",
          DialogueId = 51103037,
          GUID = "7FEE5B07",
          ImprPlusId = 1201,
          NextDialogue = 51103038,
          Subtitle = "Bit stingy with the rewards."
