        },
        [51105062] = {
          Camera = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "！",
          DialogueId = 51105062,
          FacialId = {
            [1] = "700329:Shock01"
          },
          GUID = "7FEF5CC4",
          NextDialogue = 51105063,
          SpeakNpcId = 700329,
          Subtitle = "!",
          TalkActionId = {
            [1] = "700329:Shock_Start"
          }
        },
        [51105063] = {
          Camera = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "难道是奶奶！",
          DialogueId = 51105063,
          GUID = "7FEF5CEE",
          NextDialogue = 51105064,
          SpeakNpcId = 700329,
          Subtitle = "Could it be... Nana!?"
        },
        [51105064] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "灵灵每天都祈祷，希望奶奶能一直留在身边保护灵灵，原来已经实现了吗？",
          DialogueId = 51105064,
          GUID = "7FEF5D18",
          NextDialogue = 51105065,
          SpeakNpcId = 700329,
          Subtitle = "I prayed every single day for Nana to stay by my side... and she really did? I just didn't know?",
          TalkActionId = {
            [1] = "700329:Shock_End"
          }
        },
        [51105065] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "只是灵灵自己不知道而已……奶奶真好，白龙神君第二好！",
          DialogueId = 51105065,
          GUID = "7FEF5D42",
          NextDialogue = 51105066,
          SpeakNpcId = 700329,
          Subtitle = "Nana's the best... Lord Argent is second-best!",
          TalkActionId = {
            [1] = "700329:Talk02_Start"
          }
        },
        [51105066] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "虽然再也看不见奶奶了，但灵灵可以和以前一样，陪着奶奶晒太阳，为奶奶读她看不清的报纸……对了，这次轮到灵灵去给奶奶唱摇篮曲了！",
          DialogueId = 51105066,
          GUID = "7FEF5D6C",
          NextOptions = {
            [1] = 51105067,
            [2] = 51105069
          },
          SpeakNpcId = 700329,
          Subtitle = "Even if I can't see her anymore... I can still sit with her in the sun, read her the bits of the newspaper she couldn't make out... Oh! And this time — it's my turn to sing her the lullaby!"
        },
        [51105067] = {
          Content = "我找到了能让你看见无由生的方法，但只在半个时辰内有效。",
          DialogueId = 51105067,
          GUID = "7FEF5D96",
          ImprPlusId = 1207,
          NextDialogue = 51105068,
          Subtitle = "I've found a way for you to see her — but it'll only last for half an hour."
        },
        [51105068] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "什么！我和奶奶可以再见面了吗？",
          DialogueId = 51105068,
          GUID = "7FEF5DC0",
          NextDialogue = 51105071,
          SpeakNpcId = 700329,
          Subtitle = "Really!? I get to see Nana again?"
        },
        [51105069] = {
          Content = "加钱，我有办法让你再见一次奶奶，但只有半个时辰。",
          DialogueId = 51105069,
          GUID = "7FEF5DEA",
          ImprPlusId = 1206,
          NextDialogue = 51105070,
          Subtitle = "I've found a way for you to see her — but it'll only last for half an hour, and it'll cost you extra."
        },
        [51105070] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "灵灵的零花钱全部给你！{性别：大哥哥|大姐姐}，这些够吗……？",
          DialogueId = 51105070,
          FacialId = {
            [1] = "700329:Shy"
          },
          GUID = "7FEF5E14",
          NextDialogue = 51105071,
          SpeakNpcId = 700329,
          Subtitle = "I'll give you all my pocket money! Is it enough, {性别:sir|miss}?"
        },
        [51105071] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "拿着这个就可以看到无由生了。",
          DialogueId = 51105071,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FEF5E3E",
          NextDialogue = 51105072,
          SpeakNpcId = 100001,
          Subtitle = "Here — take this. It'll let you see her.",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51105072] = {
          Content = "灵灵接过花束，紧张地闭上了眼睛，过了好一会才慢慢睁开。",
          DialogueId = 51105072,
          GUID = "7FEF5E68",
          IsBlack = 1,
          NextDialogue = 51105073,
          Subtitle = "Lingling clutches the bouquet, shuts her eyes tight... and only dares to open them after a long moment.",
          TalkActionId = {
            [1] = "700329:Talk02_End"
          }
        },
        [51105073] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "……？",
          DialogueId = 51105073,
          GUID = "7FEF5E92",
          NextDialogue = 51105074,
          SpeakNpcId = 700329,
          Subtitle = "...?"
        },
        [51105074] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "灵灵怎么什么都没看到？这里是华胥，说谎的话，会有狴犴来抓你的！灵灵可以不计较，但也不想看见你被揍，你要不快跑吧……",
          DialogueId = 51105074,
          GUID = "7FEF5EBC",
          NextDialogue = 51105075,
          SpeakNpcId = 700329,
          Subtitle = "I don't see anything! In Huaxu, if you lie, the Bi'an comes to drag you off! Still, I don't want to watch you get smacked... maybe you should start running."
        },
        [51105075] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "如果无由生对你有执念，就一定不会离得太远。灵灵要不要试着呼唤她呢？",
          DialogueId = 51105075,
          GUID = "7FEF5EE6",
          NextDialogue = 51105076,
          SpeakNpcId = 100001,
          Subtitle = "If the Wishen misses you that much, she won't be far. Want to try calling out to her?"
        },
        [51105076] = {
          Camera = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那灵灵试试……",
          DialogueId = 51105076,
          GUID = "7FEF5F10",
          NextDialogue = 51105077,
          SpeakNpcId = 700329,
          Subtitle = "Okay... I'll try..."
        },
        [51105077] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "奶奶，我在这里！我好想你呀——所以可不可以让我见见你——",
          DialogueId = 51105077,
          GUID = "7FEF5F3A",
          LookAt = {
            [1] = "700329:n(700331)"
          },
          NextDialogue = 51105078,
          SpeakNpcId = 700329,
          Subtitle = "Nana — I'm here! I miss you so much! Can I see you again — please?",
          TalkActionId = {
            [1] = "700329:Talk02_Start"
          }
        },
        [51105078] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "奶——奶——",
          DialogueId = 51105078,
          GUID = "7FEF5F64",
          LookAt = {
            [1] = "700329:n(100001)"
          },
          NextDialogue = 51105079,
          SpeakNpcId = 700329,
          Subtitle = "Naaa–naaa—!"
        },
        [51105079] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，你什么时候回来的？",
          DialogueId = 51105079,
          GUID = "7FEF5F8E",
          LookAt = {
            [1] = "100001:n(700331)"
          },
          NextDialogue = 51105080,
          Scripts = "SetVisibility{ActorId{700331},Visibility{\"Show\"}}",
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?",
          TalkActionId = {
            [1] = "700329:Talk02_End"
          },
          TurnTo = {
            [1] = "700329:n(700331)"
          }
        },
        [51105080] = {
          Camera = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我、我等你好久了……萍萍，早上了，我们去找吿苍来插瓶吧。",
          DialogueId = 51105080,
          GUID = "7FEF5FB8",
          NextDialogue = 51105081,
          SpeakNpcId = 700331,
          Subtitle = "I... I've been waiting so long... Pingping, the sun's come out — let's pick some Skylilies to put in the vase."
        },
        [51105081] = {
          Camera = "-132.632812,-149.719727,173.525391,0.00008,-14.200147,49.79491,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "奶奶我是灵灵呀，谁是——",
          DialogueId = 51105081,
          GUID = "7FEF5FE2",
          NextDialogue = 51105082,
          SpeakNpcId = 700329,
          Subtitle = "Nana? It's me — Lingling! Who's P—"
        },
        [51105082] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，中午了，我们看会书吧。",
          DialogueId = 51105082,
          GUID = "7FEF600C",
          NextDialogue = 51105083,
          SpeakNpcId = 700331,
          Subtitle = "Pingping... it's noon now. Let's read for a while."
        },
        [51105083] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，下午了，我们去散步，你喜欢促织娘对不对？",
          DialogueId = 51105083,
          GUID = "7FEF6036",
          NextDialogue = 51105084,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, it's afternoon... Let's take a walk. You like Loomhoppers, don't you?"
        },
        [51105084] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍摔伤了，痛不痛？爷爷给你吹吹，“呼呼”，不痛不痛……",
          DialogueId = 51105084,
          GUID = "7FEF6060",
          NextDialogue = 51105085,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, you scraped your knee? Does it hurt? Grandpa will give it some fwoo fwoo — pain, pain, go away... there, all better now."
        },
        [51105085] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "不对……这不是奶奶……我也不喜欢促织娘……",
          DialogueId = 51105085,
          FacialId = {
            [1] = "700329:Shy"
          },
          GUID = "7FEF608A",
          LookAt = {
            [1] = "700329:n(700329)"
          },
          NextDialogue = 51105086,
          SpeakNpcId = 700329,
          Subtitle = "No... this isn't right. That's not Nana... And I don't even like Loomhoppers..."
        },
        [51105086] = {
          Camera = "-749.443359,813.657715,264.467773,0.000045,-6.800218,-50.603058,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "等一下，那奶奶，喜欢促织娘吗？",
          DialogueId = 51105086,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FEF60B4",
          LookAt = {
            [1] = "100001:n(700329)"
          },
          NextDialogue = 51105087,
          SpeakNpcId = 100001,
          Subtitle = "Hold on — did your Nana like Loomhoppers?"
        },
        [51105087] = {
          Camera = "-1365.160156,-105.44873,321.923828,0.000059,-6.199885,0.00011,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "奶奶以前会捉促织娘来逗我，但我吓得直叫，奶奶就再也不这样了……灵灵想，奶奶大概是喜欢的。",
          DialogueId = 51105087,
          GUID = "7FEF60DE",
          NextDialogue = 51105088,
          SpeakNpcId = 700329,
          Subtitle = "Nana used to catch them to cheer me up, but I was so scared I screamed, so she never did that again... I think maybe she did like them.",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105088] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "那你还记得奶奶的名字吗？",
          DialogueId = 51105088,
          GUID = "7FEF6108",
          NextDialogue = 51105089,
          SpeakNpcId = 100001,
          Subtitle = "Do you remember what your Nana's name was?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51105089] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "啊，我想起来了！奶奶的名字是思萍！",
          DialogueId = 51105089,
          FacialId = {
            [1] = "700329:Shock02"
          },
          GUID = "7FEF6132",
          NextDialogue = 51105090,
          SpeakNpcId = 700329,
          Subtitle = "Oh! I remember now! Her name was Siping!"
        },
        [51105090] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，你什么时候回来的？",
          DialogueId = 51105090,
          GUID = "7FEF615C",
          NextDialogue = 51105091,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?",
          TurnTo = {
            [1] = "700329:n(700331)"
          }
        },
        [51105091] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我、我等你好久了……萍萍，早上了，我们去找吿苍来插瓶吧。",
          DialogueId = 51105091,
          GUID = "7FEF6186",
          NextDialogue = 51105092,
          SpeakNpcId = 700331,
          Subtitle = "I... I've been waiting so long... Pingping, the sun's come out — let's pick some Skylilies to put in the vase."
        },
        [51105092] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，中午了，我们看会书吧。",
          DialogueId = 51105092,
          GUID = "7FEF61B0",
          NextDialogue = 51105093,
          SpeakNpcId = 700331,
          Subtitle = "Pingping... it's noon now. Let's read for a while."
        },
        [51105093] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "看来他把你认成了思萍奶奶，这大概是你奶奶的爷爷，辈分上应该是……？",
          DialogueId = 51105093,
          GUID = "7FEF61DA",
          NextDialogue = 51105094,
          SpeakNpcId = 100001,
          Subtitle = "Looks like he mistook you for your Nana. He must be your Nana's grandfather, which makes him your...?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105094] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "是灵灵的高祖父！以前，奶奶说我和她小时候长得很像，原来是真的……",
          DialogueId = 51105094,
          GUID = "7FEF6204",
          NextDialogue = 51105095,
          SpeakNpcId = 700329,
          Subtitle = "My great-great-grandfather! Nana always said I looked just like her when she was little... So it really was true!",
          TalkActionId = {
            [1] = "700329:Explain01_Start"
          }
        },
        [51105095] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "原来，奶奶也不是天生的奶奶，她也有疼爱她的长辈……",
          DialogueId = 51105095,
          GUID = "7FEF622E",
          NextDialogue = 51105096,
          SpeakNpcId = 700329,
          Subtitle = "Ah, so Nana wasn't born a Nana... She was a kid who had grown-ups who loved her, too...",
          TalkActionId = {
            [1] = "700329:Explain01_End"
          }
        },
        [51105096] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，你什么时候回来的？",
          DialogueId = 51105096,
          GUID = "7FEF6258",
          NextDialogue = 51105097,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?",
          TurnTo = {
            [1] = "700329:n(700331)"
          }
        },
        [51105097] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "……我从来没见过高祖父，据说他在奶奶年轻的时候去世了，那时我们刚刚搬到皓京。因为没能及时收到消息，奶奶错过了见他的最后一面……",
          DialogueId = 51105097,
          FacialId = {
            [1] = "700329:Sad01"
          },
          GUID = "7FEF6282",
          NextDialogue = 51105098,
          SpeakNpcId = 700329,
          Subtitle = "I never met him... Nana said he passed away when she was young, when she just moved to Haojing. She didn't get the news in time because of the move... so she never got to say goodbye..."
        },
        [51105098] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "所以，他变成了无由生，一直在等萍萍回来。",
          DialogueId = 51105098,
          GUID = "7FEF62AC",
          NextDialogue = 51105099,
          SpeakNpcId = 100001,
          Subtitle = "That's why he became a Wishen — waiting for Siping to come home, even now.",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105099] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "大概就是这样吧……",
          DialogueId = 51105099,
          GUID = "7FEF62D6",
          NextOptions = {
            [1] = 51105100
          },
          SpeakNpcId = 700329,
          Subtitle = "That must be it..."
        },
        [51105100] = {
          Content = "陪在你身边的不是奶奶，你会感到失落吗？",
          DialogueId = 51105100,
          GUID = "7FEF6300",
          ImprPlusId = 1209,
          NextDialogue = 51105101,
          Subtitle = "Are you sad it wasn't Nana?"
        },
        [51105101] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "……嗯，是有点。",
          DialogueId = 51105101,
          GUID = "7FEF632A",
          LookAt = {
            [1] = "700329:n(700329)"
          },
          NextDialogue = 51105102,
          SpeakNpcId = 700329,
          Subtitle = "...A little, I guess.",
          TalkActionId = {
            [1] = "700329:Think_Start"
          }
        },
        [51105102] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "但是看到太爷爷这样，我反而不希望奶奶像这样，因为遗憾徘徊在这里……",
          DialogueId = 51105102,
          GUID = "7FEF6354",
          NextDialogue = 51105103,
          SpeakNpcId = 700329,
          Subtitle = "But... seeing Great-Great-Grandpa like this — I don't want Nana to end up the same... Stuck here, full of regrets..."
        },
        [51105103] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我现在甚至觉得很庆幸，奶奶一定是心愿已了，才化成星星的……",
          DialogueId = 51105103,
          GUID = "7FEF637E",
          NextDialogue = 51105104,
          SpeakNpcId = 700329,
          Subtitle = "Now I'm almost glad — Nana's wishes must've all come true before she became a star..."
        },
        [51105104] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "或许奶奶也期待过，变成星星后会与自己的爷爷一起再捉促织娘吧，可是现在，他们还是天各一方。",
          DialogueId = 51105104,
          GUID = "7FEF63A8",
          NextDialogue = 51105105,
          SpeakNpcId = 700329,
          Subtitle = "Maybe... she became a star so she could find her grandpa again. Maybe she wanted to chase Loomhoppers with him, like they used to... But even now, they still can't be together...",
          TalkActionId = {
            [1] = "700329:Think_End"
          }
        },
        [51105105] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "你想解除他的执念吗？",
          DialogueId = 51105105,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FEF63D2",
          NextDialogue = 51105106,
          SpeakNpcId = 100001,
          Subtitle = "Do you want to help him let go?"
        },
        [51105106] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯，我一定要这么做！",
          DialogueId = 51105106,
          GUID = "7FEF63FC",
          LookAt = {
            [1] = "700329:n(700331)"
          },
          SpeakNpcId = 700329,
          Subtitle = "Absolutely!",
          TalkActionId = {
            [1] = "700329:Explain02_Start"
          }
        },
        [51105107] = {
          Camera = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "爷爷快看，这是我给你带的促织娘！",
          DialogueId = 51105107,
          GUID = "7FEF6D02",
          NextDialogue = 51105108,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"700329:n(700331)"}},
PlayAnimation{ActorId{700329},AnimationId{"Give"},Duration{2}},
}]],
          SpeakNpcId = 700329,
          Subtitle = "Look, Grandpa — I brought you Loomhoppers!"
        },
        [51105108] = {
          Camera = "-132.632812,-149.719727,173.525391,0.00008,-14.200147,49.79491,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍，你什么时候回来的？",
          DialogueId = 51105108,
          GUID = "7FEF6D2C",
          NextDialogue = 51105109,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?"
        },
        [51105109] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我已经回来一阵了！和爷爷待在一块也有好几天了，爷爷记得吗？",
          DialogueId = 51105109,
          GUID = "7FEF6D56",
          NextDialogue = 51105110,
          SpeakNpcId = 700329,
          Subtitle = "I've been back a while! We've spent so many days together — do you remember, Grandpa?",
          TalkActionId = {
            [1] = "700329:Confident_Start"
          }
        },
        [51105110] = {
          Camera = "-265.007812,-512.92627,1311.914062,0.000054,-24.599936,45.398846,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "以后呀，爷爷再也不用一个人去捉促织娘了！我会陪着爷爷去采吿苍，去看书，还有一起做很多很多事情……",
          DialogueId = 51105110,
          GUID = "7FEF6D80",
          NextDialogue = 51105111,
          SpeakNpcId = 700329,
          Subtitle = "From now on, you won't have to catch Loomhoppers all by yourself! I'll pick Skylilies with you, read with you — we'll do all sorts of things together!"
        },
        [51105111] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我不会再让爷爷一个人孤零零的了！",
          DialogueId = 51105111,
          GUID = "7FEF6DAA",
          NextDialogue = 51105112,
          SpeakNpcId = 700329,
          Subtitle = "You don't have to be alone ever again!",
          TalkActionId = {
            [1] = "700329:Confident_End"
          }
        },
        [51105112] = {
          Camera = "-132.632812,-149.719727,173.525391,0.00008,-14.200147,49.79491,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哦……哦……萍萍回来了，萍萍回来了。",
          DialogueId = 51105112,
          GUID = "7FEF6DD4",
          NextDialogue = 51105113,
          SpeakNpcId = 700331,
          Subtitle = "Oh... Pingping's back... Pingping really came home..."
        },
        [51105113] = {
          Camera = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "爷爷还以为，再也见不到萍萍了，我就知道，萍萍一定会回来看我的。",
          DialogueId = 51105113,
          GUID = "7FEF6DFE",
          NextDialogue = 51105114,
          SpeakNpcId = 700331,
          Subtitle = "I thought... I'd never see her again. But I knew she'd come back... my dear Pingping..."
        },
        [51105114] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "萍萍之前不在这里，一定是没有找到回家的路……",
          DialogueId = 51105114,
          GUID = "7FEF6E28",
          NextDialogue = 51105115,
          SpeakNpcId = 700331,
          Subtitle = "She must've lost her way... That's why it took her so long to come back..."
        },
        [51105115] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "是呀，前几天只是和爷爷捉迷藏！现在爷爷找到我了，我当然要理爷爷，以后我会在这里住很久很久……",
          DialogueId = 51105115,
          GUID = "7FEF6E52",
          NextDialogue = 51105116,
          SpeakNpcId = 700329,
          Subtitle = "That's right! I was just playing hide-and-seek with you, Grandpa! And now that you've found me, I'm not going anywhere. I'll be by your side for a long, long time...",
          TalkActionId = {
            [1] = "700329:Talk02_Start"
          }
        },
        [51105116] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "爷爷可以一直看见我！",
          DialogueId = 51105116,
          GUID = "7FEF6E7C",
          NextDialogue = 51105117,
          SpeakNpcId = 700329,
          Subtitle = "Now you can see me every single day!",
          TalkActionId = {
            [1] = "700329:Talk02_End"
          }
        },
        [51105117] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "是嘛，真好啊……真好啊……我等到了……",
          DialogueId = 51105117,
          GUID = "7FEF6EA6",
          NextDialogue = 51105118,
          SpeakNpcId = 700331,
          Subtitle = "Is that so...? How wonderful... Finally..."
        },
        [51105118] = {
          Camera = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "谢谢你……谢谢你们……",
          DialogueId = 51105118,
          GUID = "7FEF6ED0",
          NextOptions = {
            [1] = 51105119,
            [2] = 51105121,
            [3] = 51105123
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{700331},AnimationId{"Wuyou_Disappear01"},Duration{1.5}},
SetVisibility{ActorId{700331},Visibility{"Hide"}}
}]],
          SpeakNpcId = 700331,
          Subtitle = "Thank you... both of you..."
        },
        [51105119] = {
          Content = "你不是害怕促织娘吗？",
          DialogueId = 51105119,
          GUID = "7FEF6EFA",
          ImprPlusId = 1208,
          NextDialogue = 51105120,
          Subtitle = "I thought you were scared of Loomhoppers."
        },
        [51105120] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "灵灵是很害怕虫子，它有好多会乱动的腿，拿在手上刺挠挠的……但是想到这是太爷爷和奶奶的共同回忆，灵灵好像也没有那么害怕了。",
          DialogueId = 51105120,
          GUID = "7FEF6F24",
          NextDialogue = 51105126,
          SpeakNpcId = 700329,
          Subtitle = "I am! They've got so many legs and they prickle my fingers... But if they meant something special to Great-Great-Grandpa and Nana... then I guess they're not that scary after all.",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105121] = {
          Content = "冒充萍萍算说谎吗？",
          DialogueId = 51105121,
          GUID = "7FEF6F4E",
          ImprPlusId = 1210,
          NextDialogue = 51105122,
          Subtitle = "Does pretending to be Pingping count as lying?"
        },
        [51105122] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我可没说我是萍萍，是太爷爷自己误会了！灵灵从来不做违反大风九章的事情！",
          DialogueId = 51105122,
          GUID = "7FEF6F78",
          NextDialogue = 51105126,
          SpeakNpcId = 700329,
          Subtitle = "I never said I was! Great-Great-Grandpa just thought I was! I'd never break the Nine Chapters!",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105123] = {
          Content = "太爷爷和奶奶都不在了，灵灵会感到寂寞吗？",
          DialogueId = 51105123,
          GUID = "7FEF6FA2",
          ImprPlusId = 1209,
          NextDialogue = 51105124,
          Subtitle = "Now that they're both gone... do you feel lonely?"
        },
        [51105124] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "不会哦，灵灵现在心里暖洋洋的。就算太爷爷和奶奶走了，他们的思念也会化作另外一种方式守护着灵灵吧。",
          DialogueId = 51105124,
          GUID = "7FEF6FCC",
          NextDialogue = 51105125,
          SpeakNpcId = 700329,
          Subtitle = "Not at all! I feel all warm inside. Even if they're gone, their love for me is still here — I can feel it."
        },
        [51105125] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "而且，他们现在一定已经在天上见面了吧！",
          DialogueId = 51105125,
          GUID = "7FEF6FF6",
          NextDialogue = 51105126,
          SpeakNpcId = 700329,
          Subtitle = "And I bet they've already found each other up there!",
          TalkActionId = {
            [1] = "700329:Confident_Start"
          }
        },
        [51105126] = {
          Camera = "-702.90625,168.117188,149.791992,0.000007,-3.799948,-12.6027,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "给！这些都是灵灵的零花钱！",
          DialogueId = 51105126,
          GUID = "7FEF7020",
          NextDialogue = 51105127,
          SpeakNpcId = 700329,
          Subtitle = "Here! This is all of my pocket money — take it!"
        },
        [51105127] = {
          Camera = "-702.90625,168.117188,149.791992,0.000007,-3.799948,-12.6027,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "“银货两讫”，咳咳，爹娘总是把这句话挂在嘴上。这可是织星客的优良传统哦！",
          DialogueId = 51105127,
          FacialId = {
            [1] = "700329:Smile01"
          },
          GUID = "7FEF704A",
          NextDialogue = 51105128,
          SpeakNpcId = 700329,
          Subtitle = "\"Money for service,\" ahem, that's what Mum and Dad always say. It's a proud Starweaver tradition!",
          TalkActionId = {
            [1] = "700329:Confident_Start"
          }
        },
        [51105128] = {
          Camera = "-1365.160156,-105.44873,321.923828,0.000059,-6.199885,0.00011,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "对灵灵来说，这段经历是无价之宝，所以灵灵愿意把自己身上的所有都给你！希望{性别：大哥哥|大姐姐}不要觉得少！",
          DialogueId = 51105128,
          GUID = "7FEF7074",
          SpeakNpcId = 700329,
          Subtitle = "This whole thing means more to me than anything... so I want you to have all I've got! I hope that's enough, {性别:sir|miss}!",
          TalkActionId = {
            [1] = "700329:Confident_End"
          }
        },
        [51105129] = {
          Content = "要不要去采些吿苍来插瓶呢？",
          DialogueId = 51105129,
          GUID = "7FEF709E",
          SpeakNpcId = 700361,
          Subtitle = "Should I go pick some Skylilies to put in the vase?"
        },
        [51105201] = {
          ContentES = "El Carnaval de la Vela de Plata llega a su fin una vez más. A simple vista, la calma ha vuelto, y el Asfódelo deberían recuperar su bullicio habitual.",
          DialogueId = 51105201,
          GUID = "7FEFBF0A",
          NextDialogue = 51105202,
          Subtitle = "The annual Silvercandle Carnival has come to a close. Silence has returned, and the Asphodel should be settling back into its usual rhythm."
        },
        [51105202] = {
          ContentES = "Pero la realidad es otra... Una serie de incidentes inesperados ha ensombrecido lo que debía ser una celebración sin límites.",
          DialogueId = 51105202,
          GUID = "7FEFBF34",
          NextDialogue = 51105203,
          Subtitle = "Yet, that's not quite the case. A string of unexpected events has cast a shadow over what was supposed to be a fun-filled celebration."
        },
        [51105203] = {
          ContentES = "Así, unos días después del fin de las festividades, un pequeño revuelo surge en silencio.",
          DialogueId = 51105203,
          GUID = "7FEFBF5E",
          Subtitle = "And so, on the day after the festivities, a small ruckus quietly unfolds..."
        },
        [51105204] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          ContentES = "... Uf. Siento que falta algo. Como si no hubiera disfrutado lo suficiente.",
          DialogueId = 51105204,
          GUID = "7FEFBF88",
          NextDialogue = 51105205,
          SpeakNpcId = 700349,
          Subtitle = "Ugh... Something's missing... It feels like I didn't get enough out of it.",
          TalkActionId = {
            [1] = "700349:Talk01_Start"
          }
        },
        [51105205] = {
          Camera = "391.339111,-304.583008,188.128906,0.00004,-11.199583,155.19725,35.0,305.677551,false,Manual,2.8",
          ContentES = "El Carnaval de la Vela de Plata terminó así, sin brillo… Qué decepción. Toda mi inspiración se ha ido volando.",
          DialogueId = 51105205,
          GUID = "7FEFBFB2",
          LookAt = {
            [1] = "700350:n(700349)",
            [2] = "700349:n(700350)"
          },
          NextDialogue = 51105206,
          SpeakNpcId = 700350,
          Subtitle = "The Silvercandle Carnival just... fizzled out. It was so anticlimactic that I've lost all my inspiration.",
          TalkActionId = {
            [1] = "700350:Explain01_Start",
            [2] = "700349:Talk01_End"
          }
        },
        [51105206] = {
          Camera = "240.266602,24.936523,161.671875,0.000056,-2.399227,52.196819,35.0,204.573959,false,Manual,2.8",
          ContentES = "...",
          DialogueId = 51105206,
          FacialId = {
            [1] = "200003:Syouganai01"
          },
          GUID = "7FEFBFDC",
          NextDialogue = 51105207,
          SpeakNpcId = 200003,
          Subtitle = "…"
        },
        [51105207] = {
          Camera = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
          ContentES = "¿Qué pasa? ¿Por qué todos parecen tan desanimados? Normalmente, Camilla ya habría empezado a decirles que dejen de holgazanear y vuelvan al trabajo.",
          DialogueId = 51105207,
          FacialId = {
            [1] = "700352:Doubt01"
          },
          GUID = "7FEFC006",
          LookAt = {
            [1] = "700352:n(700350)",
            [2] = "700349:n(700352)",
            [3] = "700350:n(700352)"
          },
          NextDialogue = 51105208,
          SpeakNpcId = 700352,
          Subtitle = "What's going on? Why the long faces? And Camilla too. Shouldn't she be the first one telling us to stop lounging around and get back to work?",
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105208] = {
          Camera = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
          ContentES = "Y sin embargo… ni siquiera Camilla dice nada.",
          DialogueId = 51105208,
          GUID = "7FEFC030",
          NextDialogue = 51105209,
          SpeakNpcId = 700352,
          Subtitle = "Even she's gone quiet."
        },
        [51105209] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentES = "¡Ah, ya veo! ¡Deben estar agotados por todo el ajetreo del carnaval, verdad? ¡Necesitan un descanso!",
          DialogueId = 51105209,
          FacialId = {
            [1] = "700352:Confident01"
          },
          GUID = "7FEFC05A",
          LookAt = {
            [1] = "700352:n(700349)"
          },
          NextDialogue = 51105210,
          SpeakNpcId = 700352,
          Subtitle = "Ah, I see! You guys must be feeling worn out from all the hustle and bustle of the carnival, right? You need a break!",
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105210] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          ContentES = "No exactamente, todo lo contrario. El carnaval de este año se detuvo abruptamente debido al accidente en el teatro. No hubo un gran final… simplemente… terminó.",
          DialogueId = 51105210,
          GUID = "7FEFC084",
          LookAt = {
            [1] = "700349:n(700352)"
          },
          NextDialogue = 51105211,
          SpeakNpcId = 700349,
          Subtitle = "Not really, quite the opposite. This year's carnival was abruptly cut short due to the accident at the theatre. There wasn't a big finale... it just... ended.",
          TalkActionId = {
            [1] = "700349:Disagree"
          }
        },
        [51105211] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          ContentES = "Todo se interrumpió antes de que el ambiente realmente se animara. Honestamente… es peor que si el carnaval nunca hubiera empezado.",
          DialogueId = 51105211,
          GUID = "7FEFC0AE",
          NextDialogue = 51105212,
          SpeakNpcId = 700349,
          Subtitle = "It's like the fun stopped before it even got started. Honestly, it's worse than if we'd never celebrated at all."
        },
        [51105212] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentES = "Lo entiendo… Es como cuando quiero ayudar a alguien y, a mitad de camino, descubro que todo ya está resuelto. ¡Se corta toda motivación!",
          DialogueId = 51105212,
          FacialId = {
            [1] = "700352:Think02"
          },
          GUID = "7FEFC0D8",
          NextDialogue = 51105213,
          SpeakNpcId = 700352,
          Subtitle = "I get it now. It's like when I try to help someone, but halfway through, I realize they've already figured it out. It's kind of a letdown!"
        },
        [51105213] = {
          Camera = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
          ContentES = "¡Exacto! Como una idea genial en un sueño que desaparece al despertar… o un estornudo que nunca llega. ¡Ni siquiera puedo pensar en un tercer ejemplo!",
          DialogueId = 51105213,
          GUID = "7FEFC102",
          LookAt = {
            [1] = "700350:n(700352)"
          },
          NextDialogue = 51105214,
          SpeakNpcId = 700350,
          Subtitle = "Exactly! It's like having a brilliant idea in a dream, only for it to vanish the moment you wake up. Or a sneeze that never comes out! I don't even know how to describe it."
        },
        [51105214] = {
          Camera = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
          ContentES = "En fin… todo parece sin vida.",
          DialogueId = 51105214,
          GUID = "7FEFC12C",
          NextDialogue = 51105215,
          SpeakNpcId = 700350,
          Subtitle = "It all just feels... pointless.",
          TalkActionId = {
            [1] = "700350:Explain01_End"
          }
        },
        [51105215] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentES = "Parece más grave de lo que pensaba…",
          DialogueId = 51105215,
          FacialId = {
            [1] = "700352:Sad01"
          },
          GUID = "7FEFC156",
          LookAt = {
            [1] = "700352:n(700350)"
          },
          NextDialogue = 51105216,
          SpeakNpcId = 700352,
          Subtitle = "That sounds pretty serious...",
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105216] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentES = "No, esto no puede ser. ¡Tengo que encontrar una solución, si no todo Lafo Helado seguirá así!",
          DialogueId = 51105216,
          GUID = "7FEFC180",
          LookAt = {
            [1] = "700352:n(700352)"
          },
          NextDialogue = 51105217,
          SpeakNpcId = 700352,
          Subtitle = "This won't do. I've got to think of something. Maybe I could get some help from someone else. Otherwise, we'll never get back to normal!",
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105217] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentES = "¿Quién podría ayudarme…? ¡Ah! ¡Ellas! ¡Por supuesto! Siempre se mantienen calmadas, pase lo que pase.",
          DialogueId = 51105217,
          FacialId = {
            [1] = "700352:None"
          },
          GUID = "7FEFC1AA",
          NextDialogue = 51105218,
          SpeakNpcId = 700352,
          Subtitle = "Who should I talk to...? Oh, I know! I'll ask them! They're always so composed and unfazed.",
          TalkActionId = {
            [1] = "700352:Bai_Think2Confident"
          }
        },
        [51105218] = {
          Camera = "-310.544434,-605.483398,200.802734,0.000083,-9.19898,40.997597,35.0,588.773376,false,Manual,2.8",
          ContentES = "Si descubro cómo mantienen su motivación sin dejarse influir, ¡podré devolver el impulso a toda la ciudad!",
          DialogueId = 51105218,
          GUID = "7FEFC1D4",
          SpeakNpcId = 700352,
          Subtitle = "I just need to figure out how they stay so motivated and focused. I'm sure we could use their advice to snap everyone out of this funk!"
        },
        [51105301] = {
          Camera = "457.37326,-586.730225,248.960373,0.000032,-15.000139,121.598587,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Realmente cuento con ustedes tres. ¡Por favor, devuelvan algo de energía a Lago Helado!",
          DialogueId = 51105301,
          GUID = "7FEFCF72",
          NextDialogue = 51105302,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"},RelatedRegionId{\"210101\"}}",
          SpeakNpcId = 700352,
          Subtitle = "I'm really counting on you three. Please bring some energy back to Icelake!"
        },
        [51105302] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Bueno, solo soy herrera, pero es difícil quedarme de brazos cruzados cuando Nieve está tan entusiasmada con esto.",
          DialogueId = 51105302,
          FacialId = {
            [1] = "700353:Happy02"
          },
          GUID = "7FEFCF9C",
          NextDialogue = 51105303,
          SpeakNpcId = 700353,
          Subtitle = "Well, I'm just a blacksmith, but it's hard to sit back and watch when Snow's so fired up about this."
        },
        [51105303] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Normalmente me encargo de servir bebidas y provisiones durante los descansos… pero si todos descansan sin fin, no es mejor.",
          DialogueId = 51105303,
          GUID = "7FEFCFC6",
          NextDialogue = 51105304,
          SpeakNpcId = 700354,
          Subtitle = "I've been serving drinks and supplies during breaks, but if everyone keeps resting... that's not good either."
        },
        [51105304] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mmm-hmm, la intención de Nieve es encomiable. En mis crónicas, Lago Helado es la gran metrópolis del Norte… Si todos carecen de energía, tendré que renombrarla como la “Gran Somnópolis”.",
          DialogueId = 51105304,
          GUID = "7FEFCFF0",
          NextDialogue = 51105305,
          SpeakNpcId = 700355,
          Subtitle = "Mm-hmm, Snow's heart is in the right place. Icelake's always been known as the great northern metropolis in my records, but if the citizens don't get their energy back, I might have to start calling it \"Great Somnopolis.\""
        },
        [51105305] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Eso! ¡Exactamente lo que pienso! ¡Entonces busquemos juntos una manera de despertar a todos!",
          DialogueId = 51105305,
          GUID = "7FEFD01A",
          NextDialogue = 51105306,
          SpeakNpcId = 700352,
          Subtitle = "Right? That's exactly what I think. So, let's come up with something to help everyone snap out of it!",
          TalkActionId = {
            [1] = "700352:Talk02_Start"
          }
        },
        [51105306] = {
          Camera = "135.03241,-10.31543,93.88092,0.000073,-4.399932,146.59407,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Desde mi punto de vista, la solución es sencilla—",
          DialogueId = 51105306,
          FacialId = {
            [1] = "700353:Happy01"
          },
          GUID = "7FEFD044",
          NextDialogue = 51105307,
          SpeakNpcId = 700353,
          Subtitle = "Well, from my perspective, the answer is simple—"
        },
        [51105307] = {
          Camera = "130.178741,-15.803711,93.827461,0.000077,-0.999905,121.994286,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Solo existe un verdadero remedio, a saber —",
          DialogueId = 51105307,
          GUID = "7FEFD06E",
          NextDialogue = 51105308,
          SpeakNpcId = 700354,
          Subtitle = "There's only one true solution, and that is—",
          TalkActionId = {
            [1] = "700352:Talk02_End"
          }
        },
        [51105308] = {
          Camera = "132.125397,17.031494,91.702133,0.000075,-2.599946,-177.40564,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, lo pensé de inmediato —",
          DialogueId = 51105308,
          GUID = "7FEFD098",
          NextDialogue = 51105309,
          SpeakNpcId = 700355,
          Subtitle = "Yeah, I know exactly what to do—",
          TalkActionId = {
            [1] = "700355:Confident_Start"
          }
        },
        [51105309] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Cuál es?",
          DialogueId = 51105309,
          GUID = "7FEFD0C2",
          NextDialogue = 51105310,
          SpeakNpcId = 700352,
          Subtitle = "What is it?!",
          TalkActionId = {
            [1] = "700352:Excited01_Start"
          }
        },
        [51105310] = {
          Camera = "618.50708,-678.68042,180.93396,0.000092,-5.799923,127.191681,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Forjar! ¡Comerciar! ¡AVENTURA!",
          DialogueId = 51105310,
          FacialId = {
            [1] = "700353:Smile02"
          },
          GUID = "7FEFD0EC",
          NextDialogue = 51105311,
          SpeakNpcName = "UI_CMName_Name_SanRenTongShi",
          Subtitle = "FORGING! TRADING! ADVENTURE!"
        },
        [51105311] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Son tres cosas completamente diferentes!",
          DialogueId = 51105311,
          FacialId = {
            [1] = "700352:Unhappy01"
          },
          GUID = "7FEFD116",
          NextDialogue = 51105312,
          SpeakNpcId = 700352,
          Subtitle = "Those are three totally different things!",
          TalkActionId = {
            [1] = "700352:Excited01_End"
          }
        },
        [51105312] = {
          Camera = "429.908936,-169.867676,216.608871,0.000088,-20.19973,151.389633,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Y no son soluciones, sino simplemente lo que cada una de ustedes sabe hacer!",
          DialogueId = 51105312,
          GUID = "7FEFD140",
          NextDialogue = 51105313,
          SpeakNpcId = 700352,
          Subtitle = "More like what each of you specializes in, not actual solutions!",
          TalkActionId = {
            [1] = "700352:Sigh_Start"
          }
        },
        [51105313] = {
          Camera = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? Eso es inesperado.",
          DialogueId = 51105313,
          FacialId = {
            [1] = "700353:Shock01"
          },
          GUID = "7FEFD16A",
          NextDialogue = 51105314,
          SpeakNpcId = 700353,
          Subtitle = "Well, I didn't see that coming."
        },
        [51105314] = {
          Camera = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sin embargo, pensé que teníamos exactamente la misma idea.",
          DialogueId = 51105314,
          GUID = "7FEFD194",
          LookAt = {
            [1] = "700354:n(700353)"
          },
          NextDialogue = 51105315,
          SpeakNpcId = 700355,
          Subtitle = "I thought you two would be on the same page as I am."
        },
        [51105315] = {
          Camera = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "… Entonces, si no venden nada, es porque realmente creen que el comercio no es esencial. Estoy un poco decepcionada.",
          DialogueId = 51105315,
          GUID = "7FEFD1BE",
          LookAt = {
            [1] = "700355:n(700353)"
          },
          NextDialogue = 51105316,
          SpeakNpcId = 700354,
          Subtitle = "Hmm, so that's why you two never sell anything. Now I'm a little disappointed."
        },
        [51105316] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Espera, espera! Bueno… ya que cada una está convencida de que su trabajo devuelve energía, ¡entonces voy a probar todo, una por una!",
          DialogueId = 51105316,
          GUID = "7FEFD1E8",
          LookAt = {
            [1] = "700354:n(700352)",
            [2] = "700355:n(700352)"
          },
          NextDialogue = 51105317,
          SpeakNpcId = 700352,
          Subtitle = "Wait, wait, hold on! I've got an idea. Since you all think your work can help lift everyone's spirits, I'll try each of your ideas, one by one.",
          TalkActionId = {
            [1] = "700352:Sigh_End"
          }
        },
        [51105317] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Vamos, empecemos por mí! Toma un martillo, y verás: el entusiasmo volverá por sí mismo.",
          DialogueId = 51105317,
          FacialId = {
            [1] = "700353:Confident02"
          },
          GUID = "7FEFD212",
          NextDialogue = 51105318,
          SpeakNpcId = 700353,
          Subtitle = "Alright, let's start with me! Grab a hammer, and I'll show you how to get fired up!"
        },
        [51105318] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Está bien. Nunca he hecho esto… ¿puedes enseñarme?",
          DialogueId = 51105318,
          FacialId = {
            [1] = "700353:CM_Idle"
          },
          GUID = "7FEFD23C",
          NextDialogue = 51105319,
          SpeakNpcId = 700352,
          Subtitle = "You got it! But I've never done this before. Can you teach me the ropes?",
          TalkActionId = {
            [1] = "700352:AgreeHead"
          }
        },
        [51105319] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es muy simple. Toma el martillo, respira hondo… y golpea —",
          DialogueId = 51105319,
          FacialId = {
            [1] = "700353:Smile02"
          },
          GUID = "7FEFD266",
          NextDialogue = 51105320,
          SpeakNpcId = 700353,
          Subtitle = "It's simple, really. Just grab the hammer, take a deep breath, and... smash—"
        },
        [51105320] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Imaginando la sonrisa de quienes verán tu obra terminada. Así nace la motivación.",
          DialogueId = 51105320,
          GUID = "7FEFD290",
          NextDialogue = 51105321,
          SpeakNpcId = 700353,
          Subtitle = "Hit it while imagining how happy people will be when they see what you've made. That's the motivation you need."
        },
        [51105321] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y además, ver las chispas volar con cada golpe rítmico te dará una verdadera sensación de logro.",
          DialogueId = 51105321,
          GUID = "7FEFD2BA",
          NextDialogue = 51105322,
          SpeakNpcId = 700353,
          Subtitle = "And on top of that, seeing the sparks fly with every rhythmic strike will give you a real sense of accomplishment."
        },
        [51105322] = {
          Camera = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hmm… creo entender. En resumen, manejar un martillo genera entusiasmo.",
          DialogueId = 51105322,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFD2E4",
          NextDialogue = 51105323,
          SpeakNpcId = 700352,
          Subtitle = "Okay... I think I get it now. So, swinging a giant hammer makes you feel powerful.",
          TalkActionId = {
            [1] = "700352:SpecialConfident_Start"
          }
        },
        [51105323] = {
          Camera = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Vamos, es mi turno… ¡Uaaah! ¡Está pesado!",
          DialogueId = 51105323,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFD30E",
          NextDialogue = 51105324,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/hammer\"},PlayAs2D{true}}",
          SpeakNpcId = 700352,
          Subtitle = "Let me give it a try... Whoa, this thing's heavy...",
          TalkActionId = {
            [1] = "700352:SpecialConfident_End"
          }
        },
        [51105324] = {
          ContentES = "Nieve levanta el martillo y lo baja con todas sus fuerzas.",
          DialogueId = 51105324,
          GUID = "7FEFD338",
          IsBlack = 1,
          NextDialogue = 51105325,
          Subtitle = "Snow lifted the hammer and swung it with all her might."
        },
        [51105325] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Oh… Es cierto… Se siente cómo la fuerza surge del cuerpo al manejar un martillo así…",
          DialogueId = 51105325,
          FacialId = {
            [1] = "700352:Confident02"
          },
          GUID = "7FEFD362",
          NextDialogue = 51105326,
          SpeakNpcId = 700352,
          Subtitle = "Hmm, yeah… swinging this hammer really does make me feel... like there's power flowing through me.",
          TalkActionId = {
            [1] = "700352:SpecialHappy_Start"
          }
        },
        [51105326] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Quizá si todos forjaran juntos, recuperarían la sonrisa!",
          DialogueId = 51105326,
          GUID = "7FEFD38C",
          NextDialogue = 51105327,
          SpeakNpcId = 700352,
          Subtitle = "Maybe I could get everyone to try forging. It could be fun!"
        },
        [51105327] = {
          ContentES = "Pero a medida que Nieve continúa, sus movimientos se vuelven cada vez más lentos…",
          DialogueId = 51105327,
          GUID = "7FEFD3B6",
          IsBlack = 1,
          NextDialogue = 51105328,
          Subtitle = "As Snow continued to swing the hammer, her movements began to slow.",
          TalkActionId = {
            [1] = "700352:SpecialHappy_End"
          }
        },
        [51105328] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Estoy... agotada... No puedo más...",
          DialogueId = 51105328,
          FacialId = {
            [1] = "700352:Sad03"
          },
          GUID = "7FEFD3E0",
          NextDialogue = 51105329,
          SpeakNpcId = 700352,
          Subtitle = "So... tired... Can't swing... anymore...",
          TalkActionId = {
            [1] = "700352:BaiTX_Story_Cry_Start"
          }
        },
        [51105329] = {
          Camera = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No... es demasiado... Necesito dormir ahora mismo... Buenas noches...",
          DialogueId = 51105329,
          GUID = "7FEFD40A",
          NextDialogue = 51105330,
          SpeakNpcId = 700352,
          Subtitle = "No good. I'm wiped out. I need to sleep... Goodnight..."
        },
        [51105330] = {
          Camera = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y ya puedo sacar una conclusión... Este método no es realmente adecuado para devolver energía a todos...",
          DialogueId = 51105330,
          FacialId = {
            [1] = "700352:Syouganai01"
          },
          GUID = "7FEFD434",
          NextDialogue = 51105331,
          SpeakNpcId = 700352,
          Subtitle = "And I don't think this is the best way to motivate people..."
        },
        [51105331] = {
          Camera = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Por eso no funciona. Trabajar en exceso solo empeora la fatiga.",
          DialogueId = 51105331,
          GUID = "7FEFD45E",
          NextDialogue = 51105332,
          SpeakNpcId = 700354,
          Subtitle = "Told you. Overworking just makes everyone more tired."
        },
        [51105332] = {
          Camera = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "El carnaval existía para permitir que la gente descansara. El ruido de los martillos debería ser solo música de fondo, no la actividad principal.",
          DialogueId = 51105332,
          GUID = "7FEFD488",
          NextDialogue = 51105333,
          SpeakNpcId = 700354,
          Subtitle = "The carnival was supposed to help people relax, not turn into a workout. The clanging of hammers should've been the background noise, not the main event."
        },
        [51105333] = {
          Camera = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Es así? Bueno, estar en el fondo me parece bien. Es tu turno entonces. Veamos cómo el comercio puede insuflar vitalidad.",
          DialogueId = 51105333,
          FacialId = {
            [1] = "700353:Happy01"
          },
          GUID = "7FEFD4B2",
          NextDialogue = 51105334,
          SpeakNpcId = 700353,
          Subtitle = "Is that so? Well, being in the background is fine by me. Your turn! Let's see how \"trading\" is supposed to lift spirits."
        },
        [51105334] = {
          Camera = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hmpf. Pasas demasiado tiempo encerrada forjando. No tienes idea de lo que pasa afuera.",
          DialogueId = 51105334,
          GUID = "7FEFD4DC",
          NextDialogue = 51105335,
          SpeakNpcId = 700354,
          Subtitle = "Hmph, you've been stuck in that forge for too long. You clearly have no idea what's been going on outside."
        },
        [51105335] = {
          Camera = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sígueme. Y de paso, lleva también a Nieve... ya está durmiendo.",
          DialogueId = 51105335,
          GUID = "7FEFD506",
          SpeakNpcId = 700354,
          Subtitle = "Follow me. And don't forget to bring that sleepyhead along."
        },
        [51105401] = {
          Camera = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? ¿Por qué estoy en la plaza? No me digas que golpeé demasiado fuerte y me lancé yo misma hasta aquí...",
          DialogueId = 51105401,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFDFDA",
          NextDialogue = 51105402,
          SpeakNpcId = 700352,
          Subtitle = "Huh? How did I end up in the plaza? Did I swing the hammer so hard I flung myself across the city?",
          TalkActionId = {
            [1] = "700352:SpecialLook01_Start"
          },
          TurnTo = {
            [1] = "700360:n(700352)"
          }
        },
        [51105402] = {
          Camera = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Y ustedes, están bien? Nadie resultó herida, ¿verdad?",
          DialogueId = 51105402,
          GUID = "7FEFE004",
          LookAt = {
            [1] = "700352:n(700355)"
          },
          NextDialogue = 51105403,
          SpeakNpcId = 700352,
          Subtitle = "Are you guys okay? I didn't hurt anyone, did I?"
        },
        [51105403] = {
          Camera = "-158.35083,-438.890656,112.984375,0.000041,-9.199888,76.798775,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No, tranquilo. Simplemente te has esforzado demasiado... y te has agotada.",
          DialogueId = 51105403,
          GUID = "7FEFE02E",
          LookAt = {
            [1] = "700354:n(700352)"
          },
          NextDialogue = 51105404,
          SpeakNpcId = 700354,
          Subtitle = "No, you just wore yourself out.",
          TurnTo = {
            [1] = "700352:n(700354)"
          }
        },
        [51105404] = {
          Camera = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ya veo... Pero entonces... ¿qué debía hacer, exactamente?",
          DialogueId = 51105404,
          FacialId = {
            [1] = "700352:CM_Idle"
          },
          GUID = "7FEFE058",
          NextDialogue = 51105405,
          SpeakNpcId = 700352,
          Subtitle = "Oh, I see... but what was I supposed to be doing again?",
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105405] = {
          Camera = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ibas a devolverle vida a Lago Helado mediante el comercio.",
          DialogueId = 51105405,
          GUID = "7FEFE082",
          NextDialogue = 51105406,
          SpeakNpcId = 700354,
          Subtitle = "To breathe life back into Icelake through trading."
        },
        [51105406] = {
          Camera = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Ah, cierto! ¡Ya lo recuerdo! Entonces, ¿qué debemos hacer exactamente? ¡Enséñame!",
          DialogueId = 51105406,
          GUID = "7FEFE0AC",
          NextDialogue = 51105407,
          SpeakNpcId = 700352,
          Subtitle = "Oh, right! I remember now! So, what exactly do we need to do? Teach me the ropes!",
          TalkActionId = {
            [1] = "700352:Excited01_Start"
          }
        },
        [51105407] = {
          Camera = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Bueno, en realidad es bastante simple. Hay que crear oportunidades, mantener el misterio, lanzar una tendencia... Cuando sabes despertar el deseo, el entusiasmo sigue naturalmente.",
          DialogueId = 51105407,
          GUID = "7FEFE0D6",
          NextDialogue = 51105408,
          SpeakNpcId = 700354,
          Subtitle = "Hmm… it's actually pretty simple. Create opportunities, build some suspense, start a trend. If you bait the hook right, you can reel in the passion."
        },
        [51105408] = {
          Camera = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y cuando el deseo de poseer, de comprar, llena el corazón, la gente vuelve a trabajar con entusiasmo. Así es como renace la energía.",
          DialogueId = 51105408,
          GUID = "7FEFE100",
          NextDialogue = 51105409,
          SpeakNpcId = 700354,
          Subtitle = "Once people feel that buy-it rush, they'll work hard for it. That's how you get the energy back.",
          TalkActionId = {
            [1] = "700352:Excited01_End"
          }
        },
        [51105409] = {
          Camera = "-698.29834,-1511.247803,548.52002,0.000096,-3.199643,-79.40123,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mira, por ejemplo: he preparado aquí una bebida exclusiva de clausura del Carnaval de la Vela de Plata. Cada compra otorga un sello.",
          DialogueId = 51105409,
          GUID = "7FEFE12A",
          NextDialogue = 51105410,
          SpeakNpcId = 700354,
          Subtitle = "Less talk, more action. For example, I've prepared an exclusive drink just for the Silvercandle Carnival. And every purchase earns a stamp."
        },
        [51105410] = {
          Camera = "-60.891846,1.497742,78.666992,0.0,-1.200105,-41.399494,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Al reunir cinco sellos, se obtiene un candelabro de plata de edición limitada. Hay cinco colores... y una versión secreta negra iridiscente.",
          DialogueId = 51105410,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFE154",
          NextDialogue = 51105411,
          SpeakNpcId = 700354,
          Subtitle = "Collect five stamps, and you can win a limited-edition silver candlestick! There are five colors, plus a secret black version."
        },
        [51105411] = {
          Camera = "-211.238281,484.548462,133.915771,0.000002,-6.80019,-72.198151,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Vamos, Nieve, empieza a gritar y difundir la noticia! Si suficientes personas compran, ¡Lago Helado recuperará su vitalidad!",
          DialogueId = 51105411,
          GUID = "7FEFE17E",
          NextDialogue = 51105412,
          SpeakNpcId = 700354,
          Subtitle = "Come on, Snow, start shouting and get the word out! If enough people buy it, we'll bring Icelake back to life!"
        },
        [51105412] = {
          Camera = "-165.009277,12.943481,86.168457,0.000005,-5.000094,-19.198158,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Sí! ¡Haré cualquier cosa para devolver la vida a Lago Helado!",
          DialogueId = 51105412,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFE1A8",
          NextDialogue = 51105413,
          SpeakNpcId = 700352,
          Subtitle = "Oh, yeah! I'll do anything to bring life back to Icelake!"
        },
        [51105413] = {
          Camera = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Bebida exclusiva de clausura del Carnaval de la Vela de Plata! ¡Compra una y recibe un candelabro de plata de edición limitada! ¡Y hasta hay una versión secreta!",
          DialogueId = 51105413,
          GUID = "7FEFE1D2",
          LookAt = {
            [1] = "700352:n(700360)"
          },
          NextDialogue = 51105414,
          SpeakNpcId = 700352,
          Subtitle = "Silvercandle Carnival exclusive drink! Get your limited-edition silver candlestick! And don't miss the secret version!",
          TalkActionId = {
            [1] = "700352:BaiTX_Story_Shout_Start"
          }
        },
        [51105414] = {
          Camera = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Disponible solo un día! ¡Solo hoy! ¡Si no, habrá que esperar hasta el próximo año! ¡Vengan a verlo!",
          DialogueId = 51105414,
          GUID = "7FEFE1FC",
          LookAt = {
            [1] = "700352:n(700355)"
          },
          NextDialogue = 51105415,
          SpeakNpcId = 700352,
          Subtitle = "One day only! Get it today or wait till next year! Come one, come all!"
        },
        [51105415] = {
          Camera = "-32.104248,371.151123,518.605469,0.000011,-3.999909,-83.395515,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Las llamadas de Luno, la sirvienta, y de Nieve se mezclan en la plaza. Muchos transeúntes se detienen, observan... y luego niegan con la cabeza antes de marcharse.",
          DialogueId = 51105415,
          GUID = "7FEFE226",
          NextDialogue = 51105416,
          Subtitle = "Snow's and Lunotress's shouts echoed across the plaza, drawing the attention of many curious onlookers. But after a quick glance, they shook their heads and walked away."
        },
        [51105416] = {
          Camera = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hmm... ¿Quizá no estoy gritando lo suficiente...?",
          DialogueId = 51105416,
          FacialId = {
            [1] = "700352:Sad03"
          },
          GUID = "7FEFE250",
          NextDialogue = 51105417,
          SpeakNpcId = 700352,
          Subtitle = "Hmm... Maybe I'm not shouting loud enough?",
          TalkActionId = {
            [1] = "700352:BaiTX_Story_Shout_End"
          }
        },
        [51105417] = {
          Camera = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No, no es eso... es solo que... no es realmente emocionante...",
          DialogueId = 51105417,
          FacialId = {
            [1] = "700352:CM_Idle"
          },
          GUID = "7FEFE27A",
          NextDialogue = 51105418,
          SpeakNpcId = 700360,
          Subtitle = "Na, it's not that... it's just... not really exciting...",
          TurnTo = {
            [1] = "700352:n(700360);700355:n(700360)"
          }
        },
        [51105418] = {
          Camera = "-154.719238,-781.528137,203.725098,0.000044,-10.999541,77.402351,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Cómo es eso? Las bebidas son deliciosas, los candelabros son elegantes... ¿Qué no es emocionante?",
          DialogueId = 51105418,
          FacialId = {
            [1] = "700352:Shock01"
          },
          GUID = "7FEFE2A4",
          LookAt = {
            [1] = "700354:n(700360)"
          },
          NextDialogue = 51105419,
          SpeakNpcId = 700354,
          Subtitle = "What? Why not? We've got great drinks, and those candlesticks are super stylish. What's not exciting?",
          TalkActionId = {
            [1] = "700352:Shock_Start"
          }
        },
        [51105419] = {
          Camera = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Bueno, ya tengo como siete u ocho candelabros en casa... además de una docena de placas de edición limitada del carnaval, y quizá veinte o más de insignias.",
          DialogueId = 51105419,
          GUID = "7FEFE2CE",
          NextDialogue = 51105420,
          SpeakNpcId = 700360,
          Subtitle = "Well, I've already got like seven or eight candlesticks at home... plus a dozen carnival limited-edition plaques, and maybe two dozen badges or more.",
          TalkActionId = {
            [1] = "700360:Sigh_Start"
          }
        },
        [51105420] = {
          Camera = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Durante el carnaval de la Vela de Plata, parecía que todos los comerciantes se habían puesto de acuerdo. Cada tienda ofrecía sus objetos conmemorativos... y todos eran un éxito.",
          DialogueId = 51105420,
          FacialId = {
            [1] = "700352:CM_Idle"
          },
          GUID = "7FEFE2F8",
          NextDialogue = 51105421,
          SpeakNpcId = 700360,
          Subtitle = "During the carnival, every shop in the city had something special and limited, and the thing is, they were all great.",
          TalkActionId = {
            [1] = "700352:Shock_End"
          }
        },
        [51105421] = {
          Camera = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sin darnos cuenta, compramos demasiado... Y ahora, las carteras están vacías y los arrepentimientos bien presentes.",
          DialogueId = 51105421,
          GUID = "7FEFE322",
          NextDialogue = 51105422,
          SpeakNpcId = 700360,
          Subtitle = "Everyone got carried away and bought tons of stuff... now we're all broke and full of regret."
        },
        [51105422] = {
          Camera = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces escucharles vender aún, una vez terminada el carnaval... Solo avivará la culpa y el dolor.",
          DialogueId = 51105422,
          GUID = "7FEFE34C",
          NextDialogue = 51105423,
          SpeakNpcId = 700360,
          Subtitle = "Hearing you still pushing sales after the carnival just brings back that guilt and pain...",
          TalkActionId = {
            [1] = "700360:Sigh_End"
          }
        },
        [51105423] = {
          Camera = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Oh... Lo siento... No quería...",
          DialogueId = 51105423,
          GUID = "7FEFE376",
          NextDialogue = 51105424,
          SpeakNpcId = 700352,
          Subtitle = "Oh... I'm sorry, I didn't mean to..."
        },
        [51105424] = {
          Camera = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No se preocupe. No es una recriminación. Al contrario, realmente apreciamos que intente tantas cosas para hacernos sonreír de nuevo.",
          DialogueId = 51105424,
          FacialId = {
            [1] = "700360:Smile01"
          },
          GUID = "7FEFE3A0",
          NextDialogue = 51105425,
          SpeakNpcId = 700360,
          Subtitle = "No hard feelings. Honestly, we appreciate that you're trying so many different ways to lift our spirits.",
          TalkActionId = {
            [1] = "700360:Explain01_Start"
          }
        },
        [51105425] = {
          Camera = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ánimo. Estoy seguro de que encontrará la solución.",
          DialogueId = 51105425,
          GUID = "7FEFE3CA",
          NextDialogue = 51105426,
          SpeakNpcId = 700360,
          Subtitle = "Keep at it! I'm sure you'll figure it out!",
          TalkActionId = {
            [1] = "700360:Explain01_End",
            [2] = "700352:BaiTX_Story_RubForehead_End"
          }
        },
        [51105426] = {
          Camera = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Exacto! Bueno, eres nuestra última esperanza, Luno, la exploradora.",
          DialogueId = 51105426,
          GUID = "7FEFE3F4",
          NextDialogue = 51105427,
          SpeakNpcId = 700352,
          Subtitle = "Right! Well, you're our last hope, Lunoxplorer.",
          TurnTo = {
            [1] = "700352:n(700355);700355:n(700352)"
          }
        },
        [51105427] = {
          Camera = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Bueno, supongo que ahora es mi turno.",
          DialogueId = 51105427,
          GUID = "7FEFE41E",
          LookAt = {
            [1] = "700354:n(700355)"
          },
          NextDialogue = 51105428,
          SpeakNpcId = 700355,
          Subtitle = "Well, I guess it's my turn now.",
          TalkActionId = {
            [1] = "700355:Agree"
          }
        },
        [51105428] = {
          Camera = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mi respuesta es simple: la aventura.",
          DialogueId = 51105428,
          GUID = "7FEFE448",
          NextDialogue = 51105429,
          SpeakNpcId = 700355,
          Subtitle = "My answer is simple— adventure!"
        },
        [51105429] = {
          Camera = "122.499512,-108.44696,348.161377,0.000066,2.39976,-124.394104,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Durante el Carnaval de la Vela de Plata, todos se quedaron celebrando en Lago Helado. Por lo tanto, es lógico pensar que la gente terminó sofocándose entre esas paredes.",
          DialogueId = 51105429,
          GUID = "7FEFE472",
          NextDialogue = 51105430,
          SpeakNpcId = 700355,
          Subtitle = "Everyone spent the carnival partying inside the city, but I bet they're all suffering from major cabin fever. The walls have been keeping everyone's spirits down.",
          TalkActionId = {
            [1] = "700355:Explain02_Start"
          }
        },
        [51105430] = {
          Camera = "-5.647949,-37.965942,63.306885,0.000058,-1.398379,-172.39415,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Si cada uno sale de la ciudad, se acerca a la naturaleza, respira aire libre... ¡Estoy segura de que elevará el ánimo de todos!",
          DialogueId = 51105430,
          GUID = "7FEFE49C",
          NextDialogue = 51105431,
          SpeakNpcId = 700355,
          Subtitle = "So, if we can just get people outside, surrounded by nature, breathing fresh air... I'm sure it'll lift everyone's mood!"
        },
        [51105431] = {
          Camera = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Oh! ¡Eso tiene mucho sentido! Entonces, si encontramos el mejor lugar cerca del Lago Lamentoso y dejamos que todos disfruten de la vista, eso funcionará, ¿verdad?",
          DialogueId = 51105431,
          GUID = "7FEFE4C6",
          NextDialogue = 51105432,
          SpeakNpcId = 700352,
          Subtitle = "Oh! That makes perfect sense. So, if we find the best spot near Lamenting Lake and let everyone enjoy the view, that'll do the trick, right?",
          TalkActionId = {
            [1] = "700352:RaiseHand_Start"
          }
        },
        [51105432] = {
          Camera = "-87.131836,-425.705322,92.41748,0.000067,-8.799558,88.407211,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Exactamente. Entiendes rápido, Nieve. Ya sabes lo que tengo en mente.",
          DialogueId = 51105432,
          GUID = "7FEFE4F0",
          NextDialogue = 51105433,
          SpeakNpcId = 700355,
          Subtitle = "Exactly, you're catching on fast, Snow!",
          TalkActionId = {
            [1] = "700355:Explain02_End",
            [2] = "700352:RaiseHand_End"
          }
        },
        [51105433] = {
          Camera = "-123.174316,-60.997009,67.639648,0.000072,4.20047,5.206679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Perfecto, vamos!",
          DialogueId = 51105433,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFE51A",
          SpeakNpcId = 700352,
          Subtitle = "Alright, let's go!",
          TalkActionId = {
            [1] = "700352:SpecialHappy_Start"
          }
        },
        [51105501] = {
          Camera = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, es aquí. El espacio es vasto, sin obstáculos... perfecto para relajarse y respirar.",
          DialogueId = 51105501,
          GUID = "7FEFF042",
          NextDialogue = 51105502,
          SpeakNpcId = 700352,
          Subtitle = "Yep, this is the spot! The view is completely open and unobstructed. It's perfect for relaxing and unwinding.",
          TalkActionId = {
            [1] = "700356:Avoid",
            [2] = "700357:Avoid"
          }
        },
        [51105502] = {
          Camera = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tienes razón. Cada vez que vengo aquí, siento que me recargo por completo. Estoy segura de que los demás también sentirán lo mismo y se llenarán de energía con este lugar.",
          DialogueId = 51105502,
          GUID = "7FEFF06C",
          NextDialogue = 51105503,
          SpeakNpcId = 700355,
          Subtitle = "You're right. Every time I come here, I feel completely recharged. I'm sure others will feel the same way and be energized by this place."
        },
        [51105503] = {
          Camera = "-157.613281,-2017.939453,386.613281,0.000007,-21.999744,146.197006,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Ayuda! ¡Ayuda—!",
          DialogueId = 51105503,
          GUID = "7FEFF096",
          NextDialogue = 51105504,
          SpeakNpcName = "UI_CMName_Name_FuJinChuanLai",
          Subtitle = "Help! Someone, help!"
        },
        [51105504] = {
          Camera = "-292.320312,132.621094,98.302734,0.000022,-9.399808,-35.402294,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Alguien está pidiendo ayuda. Vamos a ver.",
          DialogueId = 51105504,
          GUID = "7FEFF0C0",
          SpeakNpcId = 700355,
          Subtitle = "Sounds like someone's in trouble. Let's go check it out!",
          TalkActionId = {
            [1] = "700355:Explain01_Start"
          }
        },
        [51105505] = {
          Camera = "468.472656,-386.455078,184.522461,0.000007,-11.999959,151.198257,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Gracias... gracias por habernos salvado...",
          DialogueId = 51105505,
          FacialId = {
            [1] = "700356:Sad01",
            [2] = "700357:Sad01"
          },
          GUID = "7FEFF0EA",
          LookAt = {
            [1] = "700356:n(700352);700357:n(700352);700352:n(700356);700355:n(700356)"
          },
          NextDialogue = 51105506,
          SpeakNpcId = 700356,
          Subtitle = "Th-thank you! Thank you for saving us!",
          TalkActionId = {
            [1] = "700356:Explain01_Start"
          }
        },
        [51105506] = {
          Camera = "145.941406,-168.082031,122.435547,0.000021,-0.999502,157.595932,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sin ustedes, nunca habríamos podido regresar a Lago Helado... snif...",
          DialogueId = 51105506,
          GUID = "7FEFF114",
          NextDialogue = 51105507,
          SpeakNpcId = 700357,
          Subtitle = "If you hadn't shown up, we never would've made it back to Icelake... Boohoo.",
          TalkActionId = {
            [1] = "700357:Sigh_Start"
          }
        },
        [51105507] = {
          Camera = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Todo está bien ahora, están a salvo. Pero... ¿por qué estaban aquí?",
          DialogueId = 51105507,
          GUID = "7FEFF13E",
          NextDialogue = 51105508,
          SpeakNpcId = 700352,
          Subtitle = "It's okay, you're safe now! But... what were you two doing all the way out here?",
          TalkActionId = {
            [1] = "700352:Confident_Start"
          }
        },
        [51105508] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es mi culpa... Mi hermana y yo vivimos en Zona Nebulosa. Nuestros padres nos prohíben salir de la ciudad.",
          DialogueId = 51105508,
          GUID = "7FEFF168",
          NextDialogue = 51105509,
          SpeakNpcId = 700356,
          Subtitle = "It's all my fault. My sister and I live in Mist Aken, and our parents never let us leave the city."
        },
        [51105509] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces, durante el carnaval, cuando los guardias se relajaron para participar en las celebraciones... Aprovechamos la oportunidad para salir y ver el exterior.",
          DialogueId = 51105509,
          GUID = "7FEFF192",
          NextDialogue = 51105510,
          SpeakNpcId = 700356,
          Subtitle = "So, we thought, with everyone relaxing during the carnival, the guards wouldn't be around. We snuck out to see what the world beyond the city was like."
        },
        [51105510] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero tan pronto como cruzamos el puente, nos encontramos con los Filthoids. Intentamos escondernos... y cuanto más huíamos, más nos adentrábamos...",
          DialogueId = 51105510,
          GUID = "7FEFF1BC",
          NextDialogue = 51105511,
          SpeakNpcId = 700356,
          Subtitle = "But as soon as we crossed the bridge, we ran into some Filthoids. We had to hide, and the further we went, the worse it got...",
          TalkActionId = {
            [1] = "700357:Sigh_End"
          }
        },
        [51105511] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Al final, nos rodearon. Sin ustedes...",
          DialogueId = 51105511,
          GUID = "7FEFF1E6",
          NextDialogue = 51105512,
          SpeakNpcId = 700356,
          Subtitle = "We eventually got cornered, and if it wasn't for you...",
          TalkActionId = {
            [1] = "700356:Explain01_End"
          }
        },
        [51105512] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hermano mayor... es mi culpa. No debí haber insistido para salir. Regresemos... No quiero volver a salir de Lago Helado...",
          DialogueId = 51105512,
          GUID = "7FEFF210",
          LookAt = {
            [1] = "700357:n(700356)"
          },
          NextDialogue = 51105513,
          SpeakNpcId = 700357,
          Subtitle = "I'm sorry too. I shouldn't have insisted on leaving the city. Let's go back. I never want to leave the city again...",
          TalkActionId = {
            [1] = "700357:Explain02_Start"
          }
        },
        [51105513] = {
          Camera = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí... Para mucha gente, el mundo más allá de los muros sigue siendo demasiado peligroso...",
          DialogueId = 51105513,
          GUID = "7FEFF23A",
          LookAt = {
            [1] = "700357:n(700352)"
          },
          NextDialogue = 51105514,
          SpeakNpcId = 700352,
          Subtitle = "Hmm, for most people, the world beyond the walls is still too dangerous...",
          TalkActionId = {
            [1] = "700357:Explain02_End",
            [2] = "700352:Think_Start"
          }
        },
        [51105514] = {
          Camera = "-51.9375,-57.070312,124.332031,0.000017,-6.39975,-57.802399,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Debí pensarlo mejor. El deseo de explorar puede despertar entusiasmo, pero no es algo adecuado para todos. Regresemos.",
          DialogueId = 51105514,
          GUID = "7FEFF264",
          SpeakNpcId = 700355,
          Subtitle = "I should've thought this through. The desire to explore can fuel excitement, but it's not for everyone. Let's head back.",
          TalkActionId = {
            [1] = "700352:Think_End",
            [2] = "700355:Agree"
          }
        },
        [51105515] = {
          ContentES = "(Ruidos de combate, intensos pero sin gravedad real.)",
          DialogueId = 51105515,
          GUID = "7FEFF28E",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/fight\"},PlayAs2D{true}}",
          Subtitle = "(The sound of a scuffle — coming from a fight that couldn't quite commit to being serious.)"
        },
        [51105601] = {
          Camera = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces… ni siquiera el método de Luno, la exploradora, ha funcionado…",
          DialogueId = 51105601,
          GUID = "7FF000AA",
          LookAt = {
            [1] = "700352:n(700355);700355:n(700352)"
          },
          NextDialogue = 51105602,
          SpeakNpcId = 700352,
          Subtitle = "So, even Lunoxplorer's idea didn't work...",
          TalkActionId = {
            [1] = "700352:Sigh_Start"
          },
          TurnTo = {
            [1] = "700355:n(700352)"
          }
        },
        [51105602] = {
          Camera = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Qué deberíamos hacer ahora?",
          DialogueId = 51105602,
          GUID = "7FF000D4",
          NextDialogue = 51105603,
          SpeakNpcId = 700352,
          Subtitle = "What should we do now?"
        },
        [51105603] = {
          Camera = "93.466797,-74.861328,96.041504,0.000017,-5.799609,141.39859,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No te desanimes. Al menos, nuestros esfuerzos sí ayudaron de verdad a alguien.",
          DialogueId = 51105603,
          GUID = "7FF000FE",
          NextDialogue = 51105604,
          SpeakNpcId = 700355,
          Subtitle = "Chin up! At least our efforts helped those kids.",
          TalkActionId = {
            [1] = "700355:Explain02_Start"
          }
        },
        [51105604] = {
          Camera = "93.466797,-74.861328,96.041504,0.000017,-5.799609,141.39859,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí… tienes razón. No fue en vano.",
          DialogueId = 51105604,
          GUID = "7FF00128",
          NextDialogue = 51105605,
          SpeakNpcId = 700352,
          Subtitle = "You're right. It wasn't all in vain.",
          TalkActionId = {
            [1] = "700352:Sigh_End"
          }
        },
        [51105605] = {
          Camera = "-192.395508,-2.036133,165.440918,0.000029,-7.999804,5.19757,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Dónde se habían metido? ¡Tu padre y yo estábamos muertos de preocupación!",
          DialogueId = 51105605,
          FacialId = {
            [1] = "700358:Sad02"
          },
          GUID = "7FF00152",
          LookAt = {
            [1] = "700358:n(700356);700352:n(700358);700355:n(700358)"
          },
          NextDialogue = 51105606,
          SpeakNpcId = 700358,
          Subtitle = "Where have you two been? Your father and I were so worried!",
          TalkActionId = {
            [1] = "700358:Confident_Start",
            [2] = "700355:Explain02_End"
          },
          TurnTo = {
            [1] = "700352:n(700358)",
            [2] = "700355:(700358)"
          }
        },
        [51105606] = {
          Camera = "181.737305,9.148438,135.123047,0.000029,-7.799679,159.398849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Salimos de la ciudad y nos encontramos con unos Filthoids… Por suerte, ellas nos salvaron.",
          DialogueId = 51105606,
          GUID = "7FF0017C",
          LookAt = {
            [1] = "700356:n(700358)"
          },
          NextDialogue = 51105607,
          SpeakNpcId = 700356,
          SpeakNpcName = "UI_CMName_Name_NanHai",
          Subtitle = "We went outside the city and ran into some Filthoids. Luckily, they saved us!",
          TalkActionId = {
            [1] = "700358:Confident_End"
          }
        },
        [51105607] = {
          Camera = "-279.733398,363.849609,151.888672,0.000033,-5.399538,-40.201584,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿¡Fuera de la ciudad!? Pero ¿qué estaban haciendo los guardias en la entrada…? En fin… no importa. Lo importante es que estén bien.",
          DialogueId = 51105607,
          FacialId = {
            [1] = "700358:Shock02"
          },
          GUID = "7FF001A6",
          NextDialogue = 51105608,
          SpeakNpcId = 700358,
          Subtitle = "Outside the city?! What were the guards doing?! Ugh... never mind, I'm just glad you're alright.",
          TalkActionId = {
            [1] = "700358:Shock_Start"
          }
        },
        [51105608] = {
          Camera = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Gracias a las dos.",
          DialogueId = 51105608,
          FacialId = {
            [1] = "700358:None"
          },
          GUID = "7FF001D0",
          LookAt = {
            [1] = "700358:n(700352)"
          },
          NextDialogue = 51105609,
          SpeakNpcId = 700358,
          Subtitle = "Thank you so much!",
          TalkActionId = {
            [1] = "700358:Shock_End"
          }
        },
        [51105609] = {
          Camera = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Espera un momento… ¿Eres Nieve, verdad?",
          DialogueId = 51105609,
          GUID = "7FF001FA",
          NextDialogue = 51105610,
          SpeakNpcId = 700358,
          Subtitle = "Wait a minute... You're Snow, right?",
          TalkActionId = {
            [1] = "700358:Talk01_Start"
          }
        },
        [51105610] = {
          Camera = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? ¿Me conoces?",
          DialogueId = 51105610,
          GUID = "7FF00224",
          NextDialogue = 51105611,
          SpeakNpcId = 700352,
          Subtitle = "Huh? You know me?",
          TalkActionId = {
            [1] = "700352:Think_Start",
            [2] = "700358:Talk01_End"
          }
        },
        [51105611] = {
          Camera = "50.040039,30.647461,131.996094,0.000035,3.20023,0.399084,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No personalmente, pero estos días se habla mucho de una tal Luno que intenta devolver el ánimo a los habitantes de Lago Helado. Por la descripción… no hay duda de que es usted",
          DialogueId = 51105611,
          GUID = "7FF0024E",
          NextDialogue = 51105612,
          SpeakNpcId = 700358,
          Subtitle = "I didn't, but I've been hearing rumors lately. Apparently, a certain Luno has been working to cheer up the people of Icelake. From the descriptions, it has to be you.",
          TalkActionId = {
            [1] = "700358:Agree"
          }
        },
        [51105612] = {
          Camera = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Jeje… ¡Exacto! ¡Esa soy yo!",
          DialogueId = 51105612,
          GUID = "7FF00278",
          NextDialogue = 51105613,
          SpeakNpcId = 700352,
          Subtitle = "Hehe, that's right, it's me!",
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105613] = {
          Camera = "56.023438,-549.053711,122.467773,0.00005,-3.199588,88.599136,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero… siendo sincera, no he encontrado ninguna solución milagrosa. Y con el tiempo, incluso yo empiezo a quedarme sin energías…",
          DialogueId = 51105613,
          GUID = "7FF002A2",
          NextDialogue = 51105614,
          SpeakNpcId = 700352,
          Subtitle = "But… I haven't really found anything that works. Honestly, at this rate, even I'm starting to feel run down.",
          TalkActionId = {
            [1] = "700352:Sigh_Start"
          }
        },
        [51105614] = {
          Camera = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Oh, no te preocupes por eso! Acabo de escuchar que tus amigos te han estado buscando por todas partes. No sabían a dónde habías ido. Apresúrate y ve al Teatro Galea.",
          DialogueId = 51105614,
          GUID = "7FF002CC",
          NextDialogue = 51105615,
          SpeakNpcId = 700358,
          Subtitle = "Oh, don't worry about that! I just heard your friends have been looking all over for you. They couldn't figure out where you ran off to. Hurry over to the Galea Theatre.",
          TalkActionId = {
            [1] = "700358:Explain01_Start"
          }
        },
        [51105615] = {
          Camera = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? ¿El Teatro Galea? ¡Muy bien, voy ahora mismo!",
          DialogueId = 51105615,
          GUID = "7FF002F6",
          SpeakNpcId = 700352,
          Subtitle = "The Galea Theatre? Got it, I'll head there now!",
          TalkActionId = {
            [1] = "700352:Bai_Think2Confident"
          }
        },
        [51105701] = {
          Camera = "23.855469,1780.534668,845.710938,0.000039,-0.800191,-90.801872,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "En el escenario del Teatro Galea, se ha levantado un gran panel de papel. A juzgar por la silueta... representa a una Luno.",
          DialogueId = 51105701,
          FinalCamera = "17.328125,1336.186768,839.191406,0.000039,-1.000206,-90.801872,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FF01112",
          NextDialogue = 51105702,
          Subtitle = "On the stage of the Galea Theatre, a paper cutout sign is set up. From the silhouette, it looks like one of the Lunarians.",
          ToFinalCameraBlendTime = 5
        },
        [51105702] = {
          Camera = "410.433594,758.865479,107.394531,0.000057,-1.200132,-118.800987,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Eh! ¡Nieve, por fin llegas!",
          DialogueId = 51105702,
          GUID = "7FF0113C",
          LookAt = {
            [1] = "700349:n(700352)"
          },
          NextDialogue = 51105703,
          SpeakNpcId = 700349,
          Subtitle = "Snow! You're back!",
          TalkActionId = {
            [1] = "700349:Explain01_Start"
          }
        },
        [51105703] = {
          Camera = "22.292969,279.418884,100.0625,0.000061,4.399789,-95.400414,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Esa silueta triunfante, bañada por los focos... ¡Parece un gigante erguido en el escenario!",
          DialogueId = 51105703,
          GUID = "7FF01166",
          NextDialogue = 51105704,
          SpeakNpcId = 700350,
          Subtitle = "Ah, that triumphant silhouette, illuminated by the stage lights, is as magnificent as a giant!",
          TalkActionId = {
            [1] = "700350:Talk02_Start"
          }
        },
        [51105704] = {
          Camera = "71.03125,17.270752,111.34375,0.000066,-7.600156,112.99839,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Wells? ¿Buck? ¿Y... todos están aquí? ¿Qué está pasando?",
          DialogueId = 51105704,
          GUID = "7FF01190",
          LookAt = {
            [1] = "700352:n(700349)"
          },
          NextDialogue = 51105705,
          SpeakNpcId = 700352,
          Subtitle = "Wells, Buck? And… everyone's here? What are you all doing here?",
          TalkActionId = {
            [1] = "700350:Talk02_End",
            [2] = "700352:Shock03_Start"
          }
        },
        [51105705] = {
          Camera = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Para ser honesto, al principio, cuando nos enteramos de que intentabas motivarnos de nuevo... Pensamos que te aburrías, como siempre, y que buscabas algo que hacer.",
          DialogueId = 51105705,
          GUID = "7FF011BA",
          NextDialogue = 51105706,
          SpeakNpcId = 700349,
          Subtitle = "Honestly, at first, when we heard you were trying to cheer us up, we thought you were just bored and causing trouble, like usual.",
          TalkActionId = {
            [1] = "700352:Shock03_End"
          }
        },
        [51105706] = {
          Camera = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero cuando nos dimos cuenta de que realmente estabas probando todo tipo de métodos... Aunque ninguno realmente tuvo éxito, los habituales del Asfódelo fueron conmovidos.",
          DialogueId = 51105706,
          GUID = "7FF011E4",
          NextDialogue = 51105707,
          SpeakNpcId = 700349,
          Subtitle = "But then we heard you were actually out there trying so many different things to lift our spirits. While it didn't quite work, the regulars at the Asphodel heard about it and were really touched by your effort.",
          TalkActionId = {
            [1] = "700349:Explain01_End"
          }
        },
        [51105707] = {
          Camera = "-117.642578,-246.383423,180.195312,0.00005,-13.000267,74.194115,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Eh! ¡No hacía falta mencionar lo de “ninguna ha tenido éxito”.",
          DialogueId = 51105707,
          FacialId = {
            [1] = "700352:Sad03"
          },
          GUID = "7FF0120E",
          NextDialogue = 51105708,
          SpeakNpcId = 700352,
          Subtitle = "You didn't have to mention the \"it didn't quite work\" part!",
          TalkActionId = {
            [1] = "700352:Sad02_Start"
          }
        },
        [51105708] = {
          Camera = "378.371094,743.933472,140.042969,0.000055,-4.200552,-119.40416,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, bueno... eso no es lo importante. Lo importante es que nos dimos cuenta de que no podíamos dejarte correr por ahí sola.",
          DialogueId = 51105708,
          GUID = "7FF01238",
          NextDialogue = 51105709,
          SpeakNpcId = 700349,
          Subtitle = "Uh, that's not the point. What matters is, we realized we couldn't just sit back while you were running around doing all the work!",
          TalkActionId = {
            [1] = "700349:Talk02_Start"
          }
        },
        [51105709] = {
          Camera = "378.371094,743.933472,140.042969,0.000055,-4.200552,-119.40416,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que decidimos hacer algo, nosotros también. No queríamos que tus esfuerzos fueran en vano.",
          DialogueId = 51105709,
          GUID = "7FF01262",
          NextDialogue = 51105710,
          SpeakNpcId = 700349,
          Subtitle = "So, we decided we had to do something. We couldn't let all your effort go to waste.",
          TalkActionId = {
            [1] = "700349:Talk02_End"
          }
        },
        [51105710] = {
          Camera = "45.978516,411.828857,121.648438,0.000068,-1.000397,-97.205254,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Las ideas comenzaron a brotar, las mentes chocaban... y las chispas volaban.",
          DialogueId = 51105710,
          FacialId = {
            [1] = "700352:None"
          },
          GUID = "7FF0128C",
          NextDialogue = 51105711,
          SpeakNpcId = 700350,
          Subtitle = "Then, inspiration struck, and ideas started flowing.",
          TalkActionId = {
            [1] = "700352:Sad02_End"
          }
        },
        [51105711] = {
          Camera = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Para resumir, después de pensar, no encontramos una solución perfecta. Así que pedimos ayuda a otros... hasta que encontramos a la Directora Putsch.",
          DialogueId = 51105711,
          GUID = "7FF012B6",
          NextDialogue = 51105712,
          SpeakNpcId = 700349,
          Subtitle = "What Buck means is, after we talked it through, we didn't come up with anything solid, so we went to ask others for help. Eventually, we found Director Putsch.",
          TalkActionId = {
            [1] = "700349:Explain02_Start"
          }
        }
      }
    end
  },
  {
    MinKey = 51105712,
    MaxKey = 51108012,
    Loader = function()
      return {
        [51105712] = {
          Camera = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Todos tenían ideas sobre cómo agradecerte, pero no podíamos ponernos de acuerdo sobre la mejor manera.",
          DialogueId = 51105712,
          GUID = "7FF012E0",
          NextDialogue = 51105713,
          SpeakNpcId = 700349,
          Subtitle = "Everyone had ideas on how to thank you, but we just couldn't decide on the best way."
        },
        [51105713] = {
          Camera = "85.224609,834.157471,143.992188,0.000093,-3.799914,-95.203133,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Discutimos, argumentamos, casi nos peleamos... Y sin darnos cuenta, el entusiasmo volvió.",
          DialogueId = 51105713,
          GUID = "7FF0130A",
          NextDialogue = 51105714,
          SpeakNpcId = 700349,
          Subtitle = "So, we all gathered here to argue, scratch our heads, and have a big shouting match. But somewhere in all that chaos, the enthusiasm suddenly came rushing back!"
        },
        [51105714] = {
          Camera = "85.224609,834.157471,143.992188,0.000093,-3.799914,-95.203133,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Fue entonces cuando entendimos algo: actuar juntos por un objetivo claro avivó la llama en cada uno de nosotros.",
          DialogueId = 51105714,
          GUID = "7FF01334",
          NextDialogue = 51105715,
          SpeakNpcId = 700349,
          Subtitle = "That's when we realized — acting with a clear goal in mind can reignite everyone's spirit.",
          TalkActionId = {
            [1] = "700349:Explain02_End"
          }
        },
        [51105715] = {
          Camera = "242.505859,2691.037598,777.695312,0.000124,0.999209,-92.40229,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Finalmente, decidimos instalar aquí un escenario dedicado a los Lunos, y organizar un pequeño baile para marcar oficialmente el final del Carnaval de la Vela de Plata.",
          DialogueId = 51105715,
          GUID = "7FF0135E",
          LookAt = {
            [1] = "700352:n(700359)"
          },
          NextDialogue = 51105716,
          SpeakNpcId = 700359,
          Subtitle = "So, we decided to build a stage for the Lunos right here and throw a small dance party to officially mark the end of the Silvercandle Carnival.",
          TalkActionId = {
            [1] = "700359:Talk03_Start"
          }
        },
        [51105716] = {
          Camera = "48.492188,150.261108,106.398438,0.000098,6.400003,-77.597488,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero sobre todo... para agradecerte a ti, y a todos los Lunos que se han esforzado tanto por los demás.",
          DialogueId = 51105716,
          FacialId = {
            [1] = "700359:Smile01"
          },
          GUID = "7FF01388",
          NextDialogue = 51105717,
          SpeakNpcId = 700359,
          Subtitle = "More importantly, this is our way of thanking you, and all the Lunos who've been working tirelessly for us."
        },
        [51105717] = {
          Camera = "47.298828,36.943848,122.441406,0.000113,-10.600057,107.802986,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Solo que, como todo se preparó con urgencia, la decoración aún no está lista... ¡pero estoy segura de que los habitantes de Lago Helado nos echarán una mano!",
          DialogueId = 51105717,
          GUID = "7FF013B2",
          NextDialogue = 51105718,
          SpeakNpcId = 700359,
          Subtitle = "The backdrop isn't quite finished because we were in a bit of a rush, but I'm sure the kind citizens of Icelake will pitch in!",
          TalkActionId = {
            [1] = "700359:Talk03_End"
          }
        },
        [51105718] = {
          Camera = "47.298828,36.943848,122.441406,0.000113,-10.600057,107.802986,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? ¿Por qué los Lunos? No hemos hecho nada excepcional... solo lo que siempre hacemos.",
          DialogueId = 51105718,
          GUID = "7FF013DC",
          NextDialogue = 51105719,
          SpeakNpcId = 700352,
          Subtitle = "Wait... why Lunos? We didn't do anything special... just our usual work.",
          TalkActionId = {
            [1] = "700352:Shy03_Start"
          }
        },
        [51105719] = {
          Camera = "-8.619141,416.381531,105.339844,0.000135,-0.200131,-79.794884,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Exactamente. Cuando todos estaban sin fuerzas, ustedes siguieron como siempre.",
          DialogueId = 51105719,
          GUID = "7FF01406",
          NextDialogue = 51105720,
          SpeakNpcId = 700359,
          Subtitle = "Exactly. You've always been helping others, and when everyone was feeling down, seeing you guys doing your usual thing—",
          TalkActionId = {
            [1] = "700359:Think_Start"
          }
        },
        [51105720] = {
          Camera = "-8.619141,416.381531,105.339844,0.000135,-0.200131,-79.794884,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Forjar, comerciar, explorar... ayudó a encender la esperanza. Por eso, todos quieren hacer algo por ustedes.",
          DialogueId = 51105720,
          GUID = "7FF01430",
          NextDialogue = 51105721,
          SpeakNpcId = 700359,
          Subtitle = "— whether it's forging, adventuring, or doing business — helped spark hope. That's why everyone wants to do something for you.",
          TalkActionId = {
            [1] = "700359:Think_End"
          }
        },
        [51105721] = {
          Camera = "210.134766,-175.124634,161.980469,0.000142,-12.600367,121.406113,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "... ¿Incluso hacer lo que siempre hacemos puede inspirar a los demás?",
          DialogueId = 51105721,
          GUID = "7FF0145A",
          NextDialogue = 51105722,
          SpeakNpcId = 700352,
          Subtitle = "...Even just doing what we always do can inspire others?",
          TalkActionId = {
            [1] = "700352:Shy03_End"
          }
        },
        [51105722] = {
          Camera = "13.275391,55.729736,111.578125,0.000138,-6.800259,96.806892,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ahora lo entiendo... Jejeje, parece que mi constante correr de un lado a otro con mi {性别:pequeño secuaz|pequeña secuaz} al final me ha hecho bastante popular entre la gente de Lago Helado.",
          DialogueId = 51105722,
          GUID = "7FF01484",
          LookAt = {
            [1] = "700352:n(700352)"
          },
          NextDialogue = 51105723,
          SpeakNpcId = 700352,
          Subtitle = "I see it now... Hehe, it looks like my constant running around with my little minion has made me quite popular with the people of Icelake after all.",
          TalkActionId = {
            [1] = "700352:SpecialConfident_Start"
          }
        },
        [51105723] = {
          Camera = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Sí, claro! ¡Eres la Reina Demonio más temida, respetada y querida, que cuida a sus súbditos y nos da poder siempre que lo desees!",
          DialogueId = 51105723,
          FacialId = {
            [1] = "700349:Smile01"
          },
          GUID = "7FF014AE",
          NextDialogue = 51105724,
          SpeakNpcId = 700349,
          Subtitle = "Yes, of course! You're the most feared, respected, and beloved demon king, who cares for her subjects and empowers us whenever you want!",
          TalkActionId = {
            [1] = "700349:Agree",
            [2] = "700352:SpecialConfident_End"
          }
        },
        [51105724] = {
          Camera = "0.195312,-69.396484,112.128906,0.000143,-7.20016,90.206581,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Exactamente! Entonces escuchen bien: ¡la Reina Demonio les da la orden! ¡Recuperen fuerzas, y que comience el último baile del Carnaval de la Vela de Plata!",
          DialogueId = 51105724,
          FacialId = {
            [1] = "700352:Smile02"
          },
          GUID = "7FF014D8",
          NextDialogue = 51105725,
          SpeakNpcId = 700352,
          Subtitle = "Exactly! So, I command you all, as the magnificent demon king! Get your energy back, and let the final dance of the Silvercandle Carnival begin!",
          TalkActionId = {
            [1] = "700352:SpecialHappy_Start"
          }
        },
        [51105725] = {
          Camera = "320.064453,1972.346924,419.992188,0.000141,-7.200317,-99.594925,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Sí!",
          DialogueId = 51105725,
          GUID = "7FF01502",
          NextDialogue = 51105726,
          SpeakNpcName = "UI_CMName_Name_ZhongRen",
          Subtitle = "Yeah!"
        },
        [51105726] = {
          Camera = "-22.078125,-800.788818,638.539062,0.000137,3.599831,-91.394226,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así, el Carnaval de la Vela de Plata, antaño ensombrecida por diversos incidentes, recuperó por fin su esplendor… gracias a los esfuerzos de una Luno que se autoproclamaba Reina Demonio, y al calor que volvió a llenar Lago Helado.",
          DialogueId = 51105726,
          FinalCamera = "61.220703,-802.816284,638.539062,0.000137,3.599831,-91.394226,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FF0152C",
          Subtitle = "And so, this year's Silvercandle Carnival, a celebration once shrouded in gloom, was successfully revived thanks to the efforts of a self-proclaimed Luno Demon King, restoring joy to Icelake once again.",
          ToFinalCameraBlendTime = 7
        },
