        [51115031] = {
          Content = "古语有云：“君子报仇，十年不晚”！",
          DialogueId = 51115031,
          GUID = "7FF60BC6",
          NextDialogue = 51115032,
          SpeakNpcId = 701019,
          Subtitle = "They say revenge is a dish best served cold!"
