        [51115033] = {
          Content = "你怎么知道？！",
          DialogueId = 51115033,
          GUID = "7FF60C1A",
          NextDialogue = 51115034,
          SpeakNpcId = 701019,
          Subtitle = "How did you know!?",
          TalkActionId = {
            [1] = "701019:Shock_Start"
          }
        },
        [51115034] = {
          Content = "上一个欺负我的供货商就是在我的复仇计划写到一半的时候散伙了。",
          DialogueId = 51115034,
          GUID = "7FF60C44",
          NextDialogue = 51115035,
          SpeakNpcId = 701019,
          Subtitle = "The last supplier who pushed me around shut down halfway through my revenge plan!",
          TalkActionId = {
            [1] = "701019:Shock_End"
          }
        },
        [51115035] = {
          Content = "所以你真正的计划其实是把他们熬死吗……",
          DialogueId = 51115035,
          GUID = "7FF60C6E",
          NextDialogue = 51115036,
          SpeakNpcId = 100001,
          Subtitle = "So your real plan is... just outlasting them?"
        },
        [51115036] = {
          Content = "那还能怎么办嘛，我脑子比较笨，只能靠日积月累了。古语有云：“不积跬步，无以至千里”！",
          DialogueId = 51115036,
          GUID = "7FF60C98",
          NextOptions = {
            [1] = 51115037,
            [2] = 51115042,
            [3] = 51115045
          },
          SpeakNpcId = 701019,
          Subtitle = "What else can I do? I'm not very clever — I just have to keep at it. As the old saying goes: \"Slow and steady wins the race.\" So I'll just keep writing!"
        },
        [51115037] = {
          Content = "你可以去找止流寻求帮助。",
          DialogueId = 51115037,
          GUID = "7FF60CC2",
          ImprPlusId = 1207,
          NextDialogue = 51115038,
          Subtitle = "You could ask Zhiliu for help."
