        [51115041] = {
          Content = "可别又打个三年……",
          DialogueId = 51115041,
          GUID = "7FF60D6A",
          NextDialogue = 51115047,
          SpeakNpcId = 100001,
          Subtitle = "Just don't spend another three years rehearsing it this time."
