        [51115043] = {
          Content = "谢谢你呀，你们外面来的人都这么会说话吗？",
          DialogueId = 51115043,
          GUID = "7FF60DBE",
          NextDialogue = 51115044,
          SpeakNpcId = 701019,
          Subtitle = "Thanks! Are people from outside Huaxu all this nice?"
