        [51115045] = {
          Content = "我这里提供有偿代报仇服务。",
          DialogueId = 51115045,
          GUID = "7FF60E12",
          ImprPlusId = 1206,
          NextDialogue = 51115046,
          Subtitle = "I do offer revenge-for-hire, you know."
