        [51115046] = {
          Content = "使不得使不得，这种关系到身家性命的事，怎么好意思牵连别人。",
          DialogueId = 51115046,
          GUID = "7FF60E3C",
          NextDialogue = 51115047,
          SpeakNpcId = 701019,
          Subtitle = "No, no — I can't have someone risking their life on my account."
