          NextDialogue = 51117002,
          SpeakNpcId = 701022,
          Subtitle = "Nah-uh! It's a Bi'an!",
          TalkActionId = {
            [1] = "701022:Angry01_Start"
          }
        },
        [51117002] = {
          Camera = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "（枯荣阁外，两个小孩吵吵嚷嚷的，不知在争论些什么。你无意中放慢了脚步，引起了他们的注意——）",
          DialogueId = 51117002,
          GUID = "7FF74F24",
          NextDialogue = 51117003,
          Subtitle = "(Outside the Hall of Ephemerality, two children are loudly arguing about something. You slow your steps without meaning to — and they spot you.)",
          TalkActionId = {
            [1] = "701021:Angry01_End",
            [2] = "701022:Angry01_End"
          }
        },
        [51117003] = {
          Content = "{性别：大哥哥|大姐姐}，{性别：大哥哥|大姐姐}！你说呢？",
          DialogueId = 51117003,
          GUID = "7FF74F4E",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)"
          },
          NextOptions = {
            [1] = 51117004
          },
          SpeakNpcId = 701021,
          Subtitle = "{性别：Sir|Miss}! What do you think?"
        },
        [51117004] = {
          Content = "我说什么？",
          DialogueId = 51117004,
          GUID = "7FF74F78",
          NextDialogue = 51117005,
          Subtitle = "Huh?"
        },
        [51117005] = {
          Content = "你说那个白色的影子到底是什么？",
          DialogueId = 51117005,
          GUID = "7FF74FA2",
          NextDialogue = 51117006,
          SpeakNpcId = 701021,
          Subtitle = "What do you think the white shadow is?",
          TalkActionId = {
            [1] = "701021:Think_Start"
          }
        },
        [51117006] = {
          Content = "什么白色的影子？",
          DialogueId = 51117006,
          GUID = "7FF74FCC",
          NextDialogue = 51117007,
          SpeakNpcId = 100001,
          Subtitle = "What white shadow?",
          TalkActionId = {
            [1] = "701021:Think_End"
          }
        },
        [51117007] = {
          Camera = "807.511719,-81.339844,690.010742,0.000093,5.194338,77.734879,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "就是旁边的这间宅子里出现的那个呀！我们几个都看见过。",
          DialogueId = 51117007,
          GUID = "7FF74FF6",
          NextDialogue = 51117008,
          SpeakNpcId = 701021,
          Subtitle = "The one that shows up in that house! We all saw it."
        },
        [51117008] = {
          Content = "那白色的影子会飞，会浮在空中，还会突然出现、突然消失，你觉得那到底是什么？",
          DialogueId = 51117008,
          GUID = "7FF75020",
          NextDialogue = 51117009,
          SpeakNpcId = 701021,
          Subtitle = "It flies about, floats in mid-air — comes and goes in a flash. What do you think it is?"
        },
        [51117009] = {
          Camera = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我觉得是狴犴！身为执法者，狴犴在有人的地方要时刻保持威严，但一直这样多累呀，所以它们会偷偷跑进这间没人的宅子里嬉戏玩耍。",
          DialogueId = 51117009,
          GUID = "7FF7504A",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701022)"
          },
          NextDialogue = 51117010,
          SpeakNpcId = 701022,
          Subtitle = "I think it's a Bi'an! They're law-keepers, right? They have to act all serious in front of people — must be exhausting! So maybe they sneak into this empty house to run around and play.",
          TalkActionId = {
            [1] = "701022:Talk01_Start"
          }
        },
        [51117010] = {
          Content = "说什么傻话呢，狴犴可是大风九章的使者，又不是你家的狗狗，才不需要玩呢！而且这座宅子最近有人住了。",
          DialogueId = 51117010,
          GUID = "7FF75074",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117011,
          SpeakNpcId = 701021,
          Subtitle = "No way! A Bi'an's an enforcer of the Nine Chapters — it's not your pet dog. They don't need to play! And someone lives in that house now — it's not empty anymore.",
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117011] = {
          Content = "我觉得那个白色影子一定是无由生。它可能是这个宅子的上一任主人变的，因为太喜欢这座宅子，所以不愿意离开……",
          DialogueId = 51117011,
          GUID = "7FF7509E",
          NextDialogue = 51117012,
          SpeakNpcId = 701021,
          Subtitle = "I think the white shadow must be a Wishen! Maybe the last owner turned into one — they loved the house so much they never wanted to leave...",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117012] = {
          Content = "如果真的是宅子主人变的，怎么会现在才出现呢？",
          DialogueId = 51117012,
          GUID = "7FF750C8",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117013,
          SpeakNpcId = 701022,
          Subtitle = "If it really was the owner, why would it only show up now?",
          TalkActionId = {
            [1] = "701021:Talk02_End"
          }
        },
        [51117013] = {
          Content = "无由生可以活很久很久，说不定它之前是出门玩了呀。",
          DialogueId = 51117013,
          GUID = "7FF750F2",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117014,
          SpeakNpcId = 701021,
          Subtitle = "Wishen can live for ages — maybe it was just out playing before!"
        },
        [51117014] = {
          Content = "可是无由生的颜色也不是白的呀！",
          DialogueId = 51117014,
          GUID = "7FF7511C",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117015,
          SpeakNpcId = 701022,
          Subtitle = "But Wishen aren't even white!",
          TalkActionId = {
            [1] = "701022:Explain01_Start"
          }
        },
        [51117015] = {
          Content = "你怎么知道没有白的无由生？无由生才会飞，狴犴又不会飞。",
          DialogueId = 51117015,
          GUID = "7FF75146",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117016,
          SpeakNpcId = 701021,
          Subtitle = "How do you know there aren't white Wishen? Wishen can fly — Bi'an can't!",
          TalkActionId = {
            [1] = "701022:Explain01_End"
          }
        },
        [51117016] = {
          Content = "你怎么知道没有会飞的狴犴？",
          DialogueId = 51117016,
          GUID = "7FF75170",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117017,
          SpeakNpcId = 701022,
          Subtitle = "Then how do you know there aren't flying Bi'an?"
        },
        [51117017] = {
          Content = "……哼！{性别：大哥哥|大姐姐}，你说呢，你觉得那是无由生还是狴犴？",
          DialogueId = 51117017,
          GUID = "7FF7519A",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)"
          },
          NextOptions = {
            [1] = 51117018
          },
          RestartTag = 51117017,
          SpeakNpcId = 701021,
          Subtitle = "...Hmph! {性别：Sir|Miss}, what do you think? Wishen or Bi'an?"
        },
        [51117018] = {
          Content = "（白色影子吗……会是什么呢？）",
          DialogueId = 51117018,
          FailDialogue = 51117019,
          GUID = "7FF751C4",
          ImprCheckId = 1125,
          NextDialogue = 51117020,
          Subtitle = "(A white shadow... what could it be?)"
        },
        [51117019] = {
          Content = "（一时没想到答案。）",
          DialogueId = 51117019,
          GUID = "7FF751EE",
          Subtitle = "(Nothing comes to mind.)"
        },
        [51117020] = {
          Content = "我觉得你们说的都不对。我猜那个白色影子是住在这里的人养的小宠物。",
          DialogueId = 51117020,
          GUID = "7FF75218",
          NextDialogue = 51117021,
          SpeakNpcId = 100001,
          Subtitle = "I don't think either of you got it right. My guess? It's just the resident's pet.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51117021] = {
          Content = "啊……？",
          DialogueId = 51117021,
          GUID = "7FF75242",
          NextDialogue = 51117022,
          SpeakNpcId = 701021,
          Subtitle = "Huh...?"
        },
        [51117022] = {
          Content = "小宠物……是说小猫小狗吗？可是我们看到的那个影子会瞬间消失诶！",
          DialogueId = 51117022,
          GUID = "7FF7526C",
          NextDialogue = 51117023,
          SpeakNpcId = 701021,
          Subtitle = "A pet? Like a cat or a dog? But the shadow disappears so fast!",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117023] = {
          Content = "对呀，而且它有时候飞得特别快，比我们家的小猫被擀面杖吓得跳起来的速度还快。",
          DialogueId = 51117023,
          GUID = "7FF75296",
          NextDialogue = 51117024,
          SpeakNpcId = 701022,
          Subtitle = "Yeah! And sometimes it moves even faster than our cat when it leaps up after getting scared by the rolling pin!",
          TalkActionId = {
            [1] = "701022:Think_Start",
            [2] = "701021:Talk02_End"
          }
        },
        [51117024] = {
          Content = "不信的话，你们就敲门问问看。",
          DialogueId = 51117024,
          GUID = "7FF752C0",
          NextDialogue = 51117025,
          SpeakNpcId = 100001,
          Subtitle = "If you don't believe me, you could always knock on the door and ask.",
          TalkActionId = {
            [1] = "701022:Think_End"
          }
        },
        [51117025] = {
          Content = "可、可是里面住的是个陌生人……",
          DialogueId = 51117025,
          GUID = "7FF752EA",
          NextDialogue = 51117026,
          SpeakNpcId = 701021,
          Subtitle = "B—But the person inside is a stranger...",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51117026] = {
          Content = "听我外婆讲，这个宅子里住的好像是很厉害的大人物，万一那个大人物听了生气了怎么办？",
          DialogueId = 51117026,
          GUID = "7FF75314",
          NextDialogue = 51117028,
          SpeakNpcId = 701022,
          Subtitle = "My gran says someone really important lives in there. What if they get angry with us?"
        },
        [51117027] = {
          Content = "第三个小孩入场",
          DialogueId = 51117027,
          GUID = "7FF7533E",
          Subtitle = "(A third child trots over.)"
        },
        [51117028] = {
          Camera = "-183.449219,717.648438,135.62793,0.000058,-3.004539,-77.045387,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "咦？兰叶，望南，你们两个怎么在这里呀？",
          DialogueId = 51117028,
          GUID = "7FF75368",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(100001)"
          },
          NextDialogue = 51117029,
          Scripts = "MoveTo{ActorId{701023},TargetPoint{\"YuXian_Target\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 701023,
          Subtitle = "Huh? Lan Ye, Wang Nan — what are you two doing out here?"
        },
        [51117029] = {
          Camera = "-157.855469,429.066406,150.193359,0.000067,-5.60486,-83.644531,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我们正在辩论那个白色影子的真身呢！",
          DialogueId = 51117029,
          GUID = "7FF75392",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117030,
          SpeakNpcId = 701021,
          Subtitle = "We're trying to figure out what the white shadow really is!"
        },
        [51117030] = {
          Content = "噢，这个呀，我已经知道啦。我昨天经过这里的时候恰好遇见了住在里面的姐姐，她说那个白色的影子是“鱼龙”。",
          DialogueId = 51117030,
          GUID = "7FF753BC",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117031,
          SpeakNpcId = 701023,
          Subtitle = "Oh, that? I already know! I met the lady who lives there yesterday — she said the white shadow is a Fish-loong.",
          TalkActionId = {
            [1] = "701023:Explain01_Start"
          }
        },
        [51117031] = {
          Content = "她解释了一大堆什么“寄托”呀，“思念”呀什么的，我不太听得懂……反正就是类似于小宠物的东西啦！",
          DialogueId = 51117031,
          GUID = "7FF753E6",
          NextDialogue = 51117032,
          SpeakNpcId = 701023,
          Subtitle = "She started talking about \"remembrance\" and \"someone dearly missed\"... I didn't really get it. Anyway, it's basically like a little pet!"
        },
        [51117032] = {
          Content = "她还变了一只出来给我看呢，“鱼龙”摸上去就像水做的一样，凉凉的，可神奇了！",
          DialogueId = 51117032,
          GUID = "7FF75410",
          NextDialogue = 51117033,
          SpeakNpcId = 701023,
          Subtitle = "She even summoned one for me! It felt like it was made of water — all soft and cool. It was amazing!",
          TalkActionId = {
            [1] = "701023:Explain01_End"
          }
        },
        [51117033] = {
          Content = "什么？！",
          DialogueId = 51117033,
          GUID = "7FF7543A",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117034,
          SpeakNpcId = 701021,
          Subtitle = "What!?"
        },
        [51117034] = {
          Content = "居、居然真的是小宠物……",
          DialogueId = 51117034,
          GUID = "7FF75464",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117035,
          SpeakNpcId = 701023,
          Subtitle = "S—So it really is a pet..."
        },
        [51117035] = {
          Content = "没想到最后是这个{性别：大哥哥|大姐姐}猜对了……",
          DialogueId = 51117035,
          GUID = "7FF7548E",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)",
            [3] = "100001:n(100001)",
            [4] = "701023:n(100001)"
          },
          NextOptions = {
            [1] = 51117036,
            [2] = 51117040,
            [3] = 51117044
          },
          SpeakNpcId = 701021,
          Subtitle = "I honestly thought {性别：he|she} was joking..."
        },
        [51117036] = {
          Content = "其实是因为我也见过那位姐姐，所以才能猜对的。",
          DialogueId = 51117036,
          GUID = "7FF754B8",
          ImprPlusId = 1207,
          NextDialogue = 51117037,
          Subtitle = "I've met that lady before — that's how I knew."
        },
        [51117037] = {
          Content = "怎么你也见过？那我也要见。",
          DialogueId = 51117037,
          GUID = "7FF754E2",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117038,
          SpeakNpcId = 701021,
          Subtitle = "You've seen her too? Then I want to meet her!",
          TalkActionId = {
            [1] = "701021:Talk01_Start"
          }
        },
        [51117038] = {
          Content = "我也要，我也要！",
          DialogueId = 51117038,
          GUID = "7FF7550C",
          LookAt = {
