        },
        [51117044] = {
          Content = "哼哼，这就是大人的实力。",
          DialogueId = 51117044,
          GUID = "7FF75608",
          ImprPlusId = 1210,
          NextDialogue = 51117045,
          Subtitle = "Heh-heh~ I know that because I'm a smart grown-up."
        },
        [51117045] = {
          Content = "那我长大以后也要变得这么聪明。",
          DialogueId = 51117045,
          GUID = "7FF75632",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117046,
          SpeakNpcId = 701022,
          Subtitle = "When I grow up, I'm going to be just as smart!",
          TalkActionId = {
            [1] = "701022:Talk01_Start"
          }
        },
        [51117046] = {
          Content = "我要变得比这个{性别：大哥哥|大姐姐}还聪明！",
          DialogueId = 51117046,
          GUID = "7FF7565C",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117047,
          SpeakNpcId = 701021,
          Subtitle = "Then I'll be even smarter!",
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117047] = {
          Content = "那你们还在这儿玩什么呀，赶快回去做功课啦。",
          DialogueId = 51117047,
          GUID = "7FF75686",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117048,
          SpeakNpcId = 701023,
          Subtitle = "Then what are the two of you still standing here for? Messing about won't make you smarter. Go on — get your homework done!"
        },
