        [51124014] = {
          Content = "别这么想，你是最独特的皎皎，至少在吓人这一点上……",
          DialogueId = 51124014,
          GUID = "7FFBCD8C",
          ImprPlusId = 1209,
          NextDialogue = 51124015,
          Subtitle = "Don't say that. You are one of a kind — especially when it comes to giving people a proper scare..."
        },
        [51124015] = {
          Content = "唔……好像是这个道理，那本皎皎今日要放弃灵异皎皎这个称号，从今日开始，我要改名为恐怖皎皎！",
          DialogueId = 51124015,
          GUID = "7FFBCDB6",
          NextOptions = {
            [1] = 51124018
