        [51124016] = {
          Content = "我就是无由生。",
          DialogueId = 51124016,
          GUID = "7FFBCDE0",
          ImprPlusId = 1210,
          NextDialogue = 51124017,
          Subtitle = "I am a Wishen."
        },
        [51124017] = {
          Content = "才不是嘞，虽然本皎皎对无由生的研究已经不再是唯一，但是据我所知，无由生都是没有实体的，你看起来分明就是直挺挺地站在这里……",
          DialogueId = 51124017,
          GUID = "7FFBCE0A",
          NextOptions = {
            [1] = 51124018
          },
          SpeakNpcId = 701033,
          Subtitle = "As if! My research might not be one-of-a-kind any more, but I do know Wishen don't have solid bodies! And look at you — solid as anything!"
