        [51124018] = {
          Content = "（所以这只皎皎吓人的目的是……）",
          DialogueId = 51124018,
          FailDialogue = 51124019,
          GUID = "7FFBCE34",
          ImprCheckId = 1130,
          NextDialogue = 51124020,
          Subtitle = "(So the reason she's scaring people out here is...)"
        },
        [51124019] = {
          Content = "（她为什么要在这里吓人呢？）",
          DialogueId = 51124019,
          GUID = "7FFBCE5E",
          SpeakNpcId = 100001,
          Subtitle = "(What's she doing out here trying to scare people?)"
        },
        [51124020] = {
          Content = "所以你不在乎自己是什么皎皎，你只是想要成为独一无二的皎皎。",
          DialogueId = 51124020,
          GUID = "7FFBCE88",
          NextDialogue = 51124021,
          SpeakNpcId = 100001,
          Subtitle = "So it's not really about the title — you just want to be one of a kind."
        },
        [51124021] = {
          Content = "噫呀呀呀！被戳穿了！被你发现了！哈哈！对，就是这样，无论如何我都是独一无二的皎皎哦！",
          DialogueId = 51124021,
          FacialId = {
            [1] = "701033:Happy02"
          },
          GUID = "7FFBCEB2",
          NextDialogue = 51124022,
          SpeakNpcId = 701033,
          Subtitle = "Eeee! You've seen straight through me! Haha! Exactly — I'm one of a kind, no matter what!",
          TalkActionId = {
            [1] = "701033:Explain01_Start"
          }
        },
        [51124022] = {
          Content = "现在在我这里，你已经是个非常独特的皎皎了。",
          DialogueId = 51124022,
          GUID = "7FFBCEDC",
          NextDialogue = 51124023,
          SpeakNpcId = 100001,
          Subtitle = "Well, you're already pretty special to me.",
          TalkActionId = {
