          DialogueId = 51127410,
          GUID = "7FFDFAB4",
          SpeakNpcId = 701064,
          Subtitle = "Right... definitely not here."
        },
        [51127501] = {
          Content = "哟，小鬼，东张西望什么呢？叫的就是你，看起来不像是老练的买家，明显也和咱们也不是一条船的，说说，你……是来做什么的？",
          DialogueId = 51127501,
          GUID = "7FFE09A2",
          NextOptions = {
