          GUID = "7FFE0AC8",
          NextDialogue = 51127509,
          SpeakNpcId = 100001,
          Subtitle = "You're drunk."
        },
        [51127509] = {
          Content = "我喝多？我才没喝多，你才喝多了呢，你快回来，我和你讲……嗝！嗝！嗝！我和你讲蛟人……嗝！",
          DialogueId = 51127509,
          GUID = "7FFE0AF2",
