        [51127608] = {
          Content = "这缝儿得趁早补，再泡些日子，木芯都得烂透咯。",
          DialogueId = 51127608,
          GUID = "7FFE1B30",
          NextDialogue = 51127609,
          SpeakNpcId = 701067,
          Subtitle = "Best patch that seam up soon... leave her soaking a few more months and the core'll rot clean through."
        },
        [51127609] = {
          Content = "这船，老归老了，但这木料用的可都是好木料，平日里如果好好保养，再用个好些年应该也没问题。",
          DialogueId = 51127609,
          GUID = "7FFE1B5A",
          NextDialogue = 51127610,
          SpeakNpcId = 701067,
          Subtitle = "She's old, aye — but good timber lasts. Treat her right and she'll see out a few more decades yet."
        },
        [51127610] = {
          Content = "娃儿，你又来啦，来找我聊天还是侃大山？",
          DialogueId = 51127610,
          GUID = "7FFE1B84",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "Ah, you're back, kiddo. Got questions in that head of yours, or just here to shoot the breeze with an old carpenter?"
        },
        [51127611] = {
          Content = "这艘船有什么特别之处？",
          DialogueId = 51127611,
          GUID = "7FFE1BAE",
          NextDialogue = 51127612,
          Subtitle = "What's so special about this boat?"
        },
        [51127612] = {
          Content = "老！就是它的特别之处。虬先生收藏的古董里，它可能不是最老的那个，但是总该是最大的那一个。",
          DialogueId = 51127612,
          GUID = "7FFE1BD8",
          NextDialogue = 51127613,
          SpeakNpcId = 701067,
          Subtitle = "Her age — that's what makes her special. Among all Mr Qiu's antiques, she may not be the oldest, but she's surely the biggest."
        },
        [51127613] = {
          Content = "据说微茫市还没建立的时候，这船就不知道从哪飘来了，一直在岸边搁浅，后面这里逐渐有了人气，才给这船又捡起来利用利用。",
          DialogueId = 51127613,
          GUID = "7FFE1C02",
          NextDialogue = 51127614,
          SpeakNpcId = 701067,
          Subtitle = "Funny thing about her, though — she's got history. Word is, this boat drifted in long before Haze Market even existed. She ran aground by the shore, and folk settled nearby, hauled her ashore, and put her to use again."
        },
        [51127614] = {
          Content = "不过这船之前似乎是织星客们的，因为那些家伙喜欢在船身顶部装上个巨大的千星板，但这条船上的板不知道被什么人拆了。",
          DialogueId = 51127614,
          GUID = "7FFE1C2C",
          NextDialogue = 51127615,
          SpeakNpcId = 701067,
          Subtitle = "Seems she once belonged to the Starweavers. They used to mount a great Stellapass over the hold — but this one's been stripped off, looks like."
        },
        [51127615] = {
          Content = "也许是织星客们回收了去？我也跟虬先生问过，但他却没告诉我太多。",
          DialogueId = 51127615,
          GUID = "7FFE1C56",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "Maybe the Starweavers reclaimed it. I asked Mr Qiu, but he wasn't keen to say much."
        },
        [51127616] = {
          Content = "你是机枢派的木匠吗？",
          DialogueId = 51127616,
          GUID = "7FFE1C80",
          NextDialogue = 51127617,
          Subtitle = "Are you a carpenter with the Jishu Sect?"
        },
        [51127617] = {
          Content = "娃儿这都看得出来啊，我以前是在机枢派学过些时日，但我对那会动的木头娃娃确实不感兴趣，我就喜欢琢磨钻研那不会动的东西。",
          DialogueId = 51127617,
          GUID = "7FFE1CAA",
          NextDialogue = 51127618,
          SpeakNpcId = 701067,
          Subtitle = "Sharp eyes, kiddo. Aye, I trained with the Jishu for a spell, but I never cared much for those walking wooden dolls. I've always liked things that stay still while you're carving them."
        },
        [51127618] = {
          Content = "咱们华胥建筑的那些讲究可多呢，什么飞檐斗拱，什么雕栏玉砌，要是能把它们全琢磨明白，我这把老骨头，也是死而无憾了。",
          DialogueId = 51127618,
          GUID = "7FFE1CD4",
          NextDialogue = 51127619,
          SpeakNpcId = 701067,
          Subtitle = "Huaxu architecture's full of fine craft — soaring eaves, interlocking brackets, carved rails, stone inlay — clever stuff, all of it. If I could master all that, now that'd be a fine way to end a life's work."
        },
        [51127619] = {
          Content = "不过琢磨归琢磨，人还是得吃饭的嘛，虬先生每次请我过来都开价不菲，我啊，一年到头就等着他这大单吃呢。",
          DialogueId = 51127619,
          GUID = "7FFE1CFE",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "Interest's one thing, but a man's got to eat. Mr Qiu pays well enough — truth be told, one job from him keeps me fed for the year."
        },
        [51127620] = {
          Content = "这船大概多大岁数了？",
          DialogueId = 51127620,
          GUID = "7FFE1D28",
          NextDialogue = 51127621,
          Subtitle = "How old would you say this ship is?"
        },
        [51127621] = {
          Content = "我倒也没仔细琢磨过，按船上木料的情况来看，约莫怎么也有个百来年的历史了，但这种事也说不好。",
          DialogueId = 51127621,
          GUID = "7FFE1D52",
          NextDialogue = 51127622,
          SpeakNpcId = 701067,
          Subtitle = "Never studied her up close, but by the timber, I'd say she's a hundred years old — give or take. Hard to be sure."
        },
        [51127622] = {
          Content = "也许在虬先生之前，哪些对这老古董情有独钟的怪咖，也曾里里面面给它翻修过呢？",
          DialogueId = 51127622,
          GUID = "7FFE1D7C",
          NextDialogue = 51127623,
          SpeakNpcId = 701067,
          Subtitle = "Maybe before Mr Qiu got her, some eccentric with a soft spot for antiques refitted her inside and out. Wouldn't surprise me."
        },
        [51127623] = {
          Content = "不过说到底可以确定的是，这船应该是出自早年那班织星客们的，不然谁还会在船身顶部留个如此大的坑位用来装千星板呢？",
          DialogueId = 51127623,
          GUID = "7FFE1DA6",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "But one thing's certain — she was built by the first Starweavers. Who else would leave such a hollow in her deck for a Stellapass?"
        },
        [51127624] = {
          Content = "这船从哪来的？",
          DialogueId = 51127624,
          GUID = "7FFE1DD0",
          NextDialogue = 51127625,
          Subtitle = "Where did this ship come from?"
        },
        [51127625] = {
          Content = "这个嘛……我也不是特别清楚，不过排除掉那些怪力乱神的说法，或者天禄司高层与微茫市内部有所勾结这种怎么想都不可能的……倒是有两种较为可信。",
          DialogueId = 51127625,
          GUID = "7FFE1DFA",
          NextDialogue = 51127626,
          SpeakNpcId = 701067,
          Subtitle = "Hmm... can't say for sure. Put aside all that mythical nonsense — or those wild tales about the Ministry of Fortune scheming with Haze Market — there are two stories folk reckon might hold water."
        },
        [51127626] = {
          Content = "一是说百年之前，黑蛟作乱之时，白龙神君将其镇压，恰逢海域附近有一艘归来的织星客船只，无力承受神君怒火。",
          DialogueId = 51127626,
          GUID = "7FFE1E24",
          NextDialogue = 51127627,
          SpeakNpcId = 701067,
          Subtitle = "First one goes back a hundred years. When the Dark Loong ran wild, Lord Argent struck it down. A Starweaver ship happened to be nearby, homeward bound, and couldn't withstand his fury."
        },
        [51127627] = {
          Content = "巨大的浪潮把船掀翻，船上人员全都死于海难，这艘船顺着洋流肆意漂流，直到在此触礁。",
          DialogueId = 51127627,
          GUID = "7FFE1E4E",
          NextDialogue = 51127628,
          SpeakNpcId = 701067,
          Subtitle = "A great surge overturned the ship, killed everyone aboard, and she drifted on the currents till she ran aground here."
        },
        [51127628] = {
          Content = "另一说是……（小声）你知道这里的人不好惹吧？",
          DialogueId = 51127628,
          GUID = "7FFE1E78",
          NextDialogue = 51127629,
          SpeakNpcId = 701067,
          Subtitle = "The other tale is... (lowers his voice) you know the folk round here aren't ones to mess with, right?"
        },
        [51127629] = {
          Content = "（小声）说是有那种……心肠极为歹毒，心思极为缜密之人，混进了织星客里，把船上的人都……伪装成海难呢。",
          DialogueId = 51127629,
          GUID = "7FFE1EA2",
          NextDialogue = 51127630,
          SpeakNpcId = 701067,
          Subtitle = "(whispering) They say some cruel, cunning soul wormed his way into the Starweavers' crew — killed the lot, then staged the wreck himself."
        },
        [51127630] = {
          Content = "（正常）诶呀，不过那都是说着图一乐的，真正的原因想必只是哪位前辈的收藏罢。",
          DialogueId = 51127630,
          GUID = "7FFE1ECC",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "(regular voice) Ah, just stories to pass the time. Truth's probably duller — someone's old collection, nothing more."
        },
        [51127631] = {
          Content = "没什么要说的了。",
          DialogueId = 51127631,
          GUID = "7FFE1EF6",
          NextDialogue = 51127632,
          Subtitle = "That's all I needed to know."
        },
        [51127632] = {
          Content = "要走了吗娃儿，下次再过来找我说说话呗，年纪大啦，就爱和你们这些娃儿没事聊上几句。",
          DialogueId = 51127632,
          GUID = "7FFE1F20",
          SpeakNpcId = 701067,
          Subtitle = "Heading off, kiddo? Drop by again sometime — old folks like me don't mind a bit of chatter with you fresh-faced kids."
        },
        [51127633] = {
          DialogueId = 51127633,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51127632,
          GUID = "7FFE1F4A",
          NextOptions = {
            [1] = 51127611,
            [2] = 51127616,
            [3] = 51127620,
            [4] = 51127624,
            [5] = 51127631
          }
        },
        [51127701] = {
          Content = "最近微茫市来了些新面孔，买卖时闲话许多，上不得台面。",
          DialogueId = 51127701,
          GUID = "7FFE2A72",
          NextDialogue = 51127702,
          SpeakNpcId = 701068,
          Subtitle = "Quite a few new faces in Haze Market of late — far too chatty when they trade. No class whatsoever."
        },
        [51127702] = {
          Content = "可不是，那次我路过偶然看到个摆件小巧可爱，想收一个回去送婆娘，结果一问，你猜他怎么说的？",
          DialogueId = 51127702,
          GUID = "7FFE2A9C",
          NextDialogue = 51127703,
          SpeakNpcId = 701069,
          Subtitle = "Tell me about it. Saw this fine little trinket at a stall the other day — thought I'd buy it for the missus. So I asked the price, and guess what he said?"
        },
        [51127703] = {
          Content = "我猜猜……什么家传之宝，或者盗墓所得，亦或者是……总归是些上不得台面的说法。",
          DialogueId = 51127703,
          GUID = "7FFE2AC6",
          NextDialogue = 51127704,
          SpeakNpcId = 701068,
          Subtitle = "Let me guess — \"family heirloom,\" \"dug up from a tomb,\" one of those tales best left untold."
        },
        [51127704] = {
          Content = "何止上不得台面，这是失了咱们微茫市的规矩！谁不知道，微茫市做生意最重要的一点就是只谈物件，不问来去。",
          DialogueId = 51127704,
          GUID = "7FFE2AF0",
          NextDialogue = 51127705,
          SpeakNpcId = 701069,
          Subtitle = "Worse — breaks the Market's rules! Everyone knows the golden line here: talk price, not provenance. Trade the goods, never the tale behind them."
        },
        [51127705] = {
          Content = "哟，你说这我又想起来了，之前那些来问我那摊子价格的，张口就是几几钱，连暗语也不说，真是不懂规矩！",
          DialogueId = 51127705,
          GUID = "7FFE2B1A",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "Ha! That reminds me — a few greenhorns at my stall the other day, calling out prices in the open. Not a whisper of code between them. No respect for the rules at all!"
        },
        [51127706] = {
          Content = "你们还有规矩可言？",
          DialogueId = 51127706,
          GUID = "7FFE2B44",
          NextDialogue = 51127707,
          Subtitle = "You lot have rules?"
        },
        [51127707] = {
          Content = "你又是哪来的小鬼？",
          DialogueId = 51127707,
          GUID = "7FFE2B6E",
          NextDialogue = 51127708,
          SpeakNpcId = 701069,
          Subtitle = "And who the heck are you, kid?"
        },
        [51127708] = {
          Content = "诶诶诶，别介，你眼睛不灵光啦，这可是虬先生的客人！",
          DialogueId = 51127708,
          GUID = "7FFE2B98",
          NextDialogue = 51127709,
          SpeakNpcId = 701068,
          Subtitle = "Easy, now. Take a closer look — that's Mr Qiu's honoured guest."
        },
        [51127709] = {
          Content = "是吗？虬先生为何会请这么个乳臭未干的小娃娃回来？",
          DialogueId = 51127709,
          GUID = "7FFE2BC2",
          NextDialogue = 51127710,
          SpeakNpcId = 701069,
          Subtitle = "That so? Hard to see what business he'd have with a green pup like this."
        },
        [51127710] = {
          Content = "算啦，必定是有什么过人之处吧，虬先生自有自己的打算，我们就别揣度了。客人找我们何事啊？",
          DialogueId = 51127710,
          GUID = "7FFE2BEC",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "Well, perhaps the child's got some talent of their own. Mr Qiu always has his reasons — no use second-guessing. So then, what brings you here?"
        },
        [51127711] = {
          Content = "你们不是黑市吗？黑市也会有规矩？",
          DialogueId = 51127711,
          GUID = "7FFE2C16",
          NextDialogue = 51127712,
          Subtitle = "Aren't you black marketeers? Didn't think there'd be rules down here."
        },
        [51127712] = {
          Content = "原先自当是没有的，以前的微茫市，哦，那时候还没起名呢，只是个闲散之人聚集之所，大家想怎么做生意就怎么做生意。",
          DialogueId = 51127712,
          GUID = "7FFE2C40",
          NextDialogue = 51127713,
          SpeakNpcId = 701068,
          Subtitle = "None, back in the day. Haze Market didn't even have a name then — just a place for those without a proper trade, swapping goods as they pleased."
        },
        [51127713] = {
          Content = "反正就是被大风九章逮住了，也就是少条胳膊少条腿的事，有条烂命在，有点小钱花，日子依旧美得很。",
          DialogueId = 51127713,
          GUID = "7FFE2C6A",
          NextDialogue = 51127714,
          SpeakNpcId = 701068,
          Subtitle = "If the enforcers of the Nine Chapters caught you, you might lose an arm or a leg — but if you kept your skin and a few coins, life was still decent enough."
        },
        [51127714] = {
          Content = "想得美呢，能在咱们这混的人，哪个不是贪心不足的亡命之徒，久而久之就互相争起了对方的地盘，使点阴招用点手段，诶呀，真是成日里都闹得不可开交。",
          DialogueId = 51127714,
          GUID = "7FFE2C94",
          NextDialogue = 51127715,
          SpeakNpcId = 701069,
          Subtitle = "Ha! Decent, my foot. Everyone here's a greedy cutthroat. Sooner or later they started fighting over turf, scheming, stabbing each other in the back... it was chaos most days."
        },
        [51127715] = {
          Content = "所以啊，还是得需要规矩，只要在规矩里过的还能算舒服，那便也过着吧。",
          DialogueId = 51127715,
          GUID = "7FFE2CBE",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "So, in the end, we needed rules. As long as life stays bearable within those lines — well, that's good enough for most of us."
        },
        [51127716] = {
          Content = "你们为什么要顺从这种规矩？",
          DialogueId = 51127716,
          GUID = "7FFE2CE8",
          NextDialogue = 51127717,
          Subtitle = "Why go along with those rules?"
        },
        [51127717] = {
          Content = "来来来，我给你打个比方，一笔大单，谈成了能赚个十分，但我们内部之间明争暗斗，给人下套，这开销便去了十五分，那即使单子谈成，也是要亏钱。",
          DialogueId = 51127717,
          GUID = "7FFE2D12",
          NextDialogue = 51127718,
          SpeakNpcId = 701068,
          Subtitle = "Let me put it this way. Say there's a big deal — could bring ten percent in profit if it goes well. But if we waste time brawling and double-crossing each other, that chaos alone costs us fifteen. Even if the deal goes through, we still end up losing money."
        },
        [51127718] = {
          Content = "你说这样的生意我们做不做？",
          DialogueId = 51127718,
          GUID = "7FFE2D3C",
          NextDialogue = 51127719,
          SpeakNpcId = 701068,
          Subtitle = "So tell me — would you take that kind of deal?"
        },
        [51127719] = {
          Content = "傻子才做呢，哈哈！我看啊，要做的是先把这些不守规矩的家伙们全清空。",
          DialogueId = 51127719,
          GUID = "7FFE2D66",
          NextDialogue = 51127727,
          SpeakNpcId = 701069,
          Subtitle = "Only a fool would! Ha! When it gets like that, best thing to do's toss out the lot who won't play by the rules."
        },
        [51127720] = {
          Content = "所以是虬先生来给你们制定规矩？",
          DialogueId = 51127720,
          GUID = "7FFE2D90",
          NextDialogue = 51127721,
          Subtitle = "So Mr Qiu's the one who made those rules?"
        },
        [51127721] = {
          Content = "算是吧，我们多少要服他一些，他啊，这里……",
          DialogueId = 51127721,
          GUID = "7FFE2DBA",
          NextDialogue = 51127722,
          SpeakNpcId = 701069,
          Subtitle = "More or less. We owe him some respect — the man's sharp up here..."
        },
        [51127722] = {
          Content = "（他指了指自己的头。）",
          DialogueId = 51127722,
          GUID = "7FFE2DE4",
          NextDialogue = 51127723,
          Subtitle = "(He taps his temple.)"
        },
        [51127723] = {
          Content = "转的快，机灵。他教了我们那么多，多少听他些也是给他面子了，不过他定的规矩也不是什么难遵守的，大多数情况，他也会睁一只眼闭一只眼。",
          DialogueId = 51127723,
          GUID = "7FFE2E0E",
          NextDialogue = 51127724,
          SpeakNpcId = 701069,
          Subtitle = "Quick mind, that man. He's taught us a fair bit, so we give him his due. And his rules aren't hard to follow — most times, he just turns a blind eye anyway."
        },
        [51127724] = {
          Content = "管的严了谁还在这？大虬九章吗？哈哈哈！",
          DialogueId = 51127724,
          GUID = "7FFE2E38",
          NextDialogue = 51127727,
          SpeakNpcId = 701068,
          Subtitle = "If he cracked down too hard, who'd still be here? We don't need another Nine Chapters — one's quite enough! Ha ha ha!"
        },
        [51127725] = {
          Content = "不说了。",
          DialogueId = 51127725,
          GUID = "7FFE2E62",
          NextDialogue = 51127726,
          Subtitle = "That's enough talk."
        },
        [51127726] = {
          Content = "就走了？不再多说几句了？",
          DialogueId = 51127726,
          GUID = "7FFE2E8C",
          SpeakNpcId = 701068,
          Subtitle = "Off so soon? Stay a while — have a word, eh?"
        },
        [51127727] = {
          DialogueId = 51127727,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51127726,
          GUID = "7FFE2EB6",
          NextOptions = {
            [1] = 51127706,
            [2] = 51127711,
            [3] = 51127716,
            [4] = 51127725
          }
        },
        [51127801] = {
          Content = "下次和虬先生约见之时，定要选个风雅茶楼，而不是这种……",
          DialogueId = 51127801,
          GUID = "7FFE3ADA",
          NextDialogue = 51127802,
          SpeakNpcId = 701070,
          Subtitle = "Next time I meet Mr Qiu, it'll have to be somewhere respectable — a proper teahouse, not... whatever this place is."
        },
        [51127802] = {
          Content = "总得要隔三岔五来这微茫市，实在有损我钱老五的名声……要是被人看到了……我这脸还要不要了，不定说我与这些奸诈小人同流合污呢！",
          DialogueId = 51127802,
          GUID = "7FFE3B04",
          NextDialogue = 51127803,
          SpeakNpcId = 701070,
          Subtitle = "Having to come down to Haze Market every now and then... dreadful for one's reputation! If anyone were to see me here, I'd never live it down — they'd say I was rubbing shoulders with crooks and swindlers!"
        },
        [51127803] = {
          Content = "你对微茫市意见很大嘛。",
          DialogueId = 51127803,
          GUID = "7FFE3B2E",
          NextDialogue = 51127804,
          SpeakNpcId = 100001,
          Subtitle = "You've got quite the opinion of Haze Market."
        },
        [51127804] = {
          Content = "你是谁？看起来不像这里的人，难道是虬先生的考古协会的？不，看起来也不像，考古协会的那些学生而可不会随身携带如此危险的刀械。",
          DialogueId = 51127804,
          GUID = "7FFE3B58",
          NextDialogue = 51127805,
          SpeakNpcId = 701070,
          Subtitle = "And who might you be? You don't look like one of the locals... Wait, are you from Mr Qiu's Archaeological Society? No, no, that can't be it — those students never carry anything half as dangerous-looking as that sword of yours."
        },
        [51127805] = {
          Content = "所以你到底是做什么呢，事先声明，我可是虬先生的贵客，是要与他谈生意的，你可不能对我舞刀弄枪的，我身上可还有沉月香囊！",
          DialogueId = 51127805,
          GUID = "7FFE3B82",
          NextOptions = {
            [1] = 51127806,
            [2] = 51127817,
            [3] = 51127831
          },
          SpeakNpcId = 701070,
          Subtitle = "So what exactly are you after, then? I'll have you know I'm one of Mr Qiu's honoured guests — here to discuss business! No need to go flashing that sword about. And just so you're aware — I'm carrying a Lunarose sachet!"
        },
        [51127806] = {
          Content = "瞧给你吓得。",
          DialogueId = 51127806,
          GUID = "7FFE3BAC",
          NextDialogue = 51127807,
          Subtitle = "You're awfully jumpy."
        },
        [51127807] = {
          Content = "什么吓不吓的，我这是对微茫市出没的家伙都有戒心，如果你跟他们不是一伙的，我建议你也提起心思来打交道，别被骗了都帮人数钱。",
          DialogueId = 51127807,
          GUID = "7FFE3BD6",
          NextDialogue = 51127808,
          SpeakNpcId = 701070,
          Subtitle = "Jumpy? Nonsense! I simply know better than to trust the sort that lurk around these streets. If you're not one of them, take my advice — keep your wits about you, or they'll have you fleeced before you know it."
        },
        [51127808] = {
          Content = "如果你和他们也是一伙的……那……那就当我没说！",
          DialogueId = 51127808,
          GUID = "7FFE3C00",
          NextOptions = {
            [1] = 51127809
          },
          SpeakNpcId = 701070,
          Subtitle = "But if you are one of them... well — forget I said anything!"
        },
        [51127809] = {
          Content = "所以你对微茫市的人又很厌恶？",
          DialogueId = 51127809,
          GUID = "7FFE3C2A",
          NextDialogue = 51127810,
          Subtitle = "So you really despise the people of Haze Market?"
        },
        [51127810] = {
          Content = "哼，那帮草菅人命，不顾王法的亡命之徒，他们就是华胥的败类，华胥的风气都是被他们带坏了的！",
          DialogueId = 51127810,
          GUID = "7FFE3C54",
          NextDialogue = 51127811,
          SpeakNpcId = 701070,
          Subtitle = "Hmph! That lot — lawless ruffians, the sort who treat lives like weeds. The dregs of Huaxu — rot that's poisoned its very morals!"
        },
        [51127811] = {
          Content = "什么微茫市，就是个彻彻底底的黑市，他们根本不讲道义，有钱就赚，赚得全是昧良心钱……我呸！这些人哪有什么良心！",
          DialogueId = 51127811,
          GUID = "7FFE3C7E",
          NextDialogue = 51127812,
          SpeakNpcId = 701070,
          Subtitle = "\"Haze Market,\" they call it — nothing but a den of thieves and thugs! There's no honour among them — they'll chase any coin, however dirty. Pfah! As if any of them still knew what a conscience was!"
        },
        [51127812] = {
          Content = "你可离他们远些，别看这些披着人皮道貌岸然的样子，他们的头上，多少都背着几桩冤案呢。",
          DialogueId = 51127812,
          GUID = "7FFE3CA8",
          NextOptions = {
            [1] = 51127813,
            [2] = 51127815
          },
          SpeakNpcId = 701070,
          Subtitle = "Best keep your distance. Don't be taken in by their polite faces and fine clothes — every one of them's got blood on his hands."
        },
        [51127813] = {
          Content = "可是虬先生不也是这样的人吗？",
          DialogueId = 51127813,
          GUID = "7FFE3CD2",
          NextDialogue = 51127814,
          Subtitle = "But isn't Mr Qiu one of them too?"
        },
        [51127814] = {
          Content = "不，虬先生是不一样的，虬先生在这里是为了约束他们，让他们不要再做那些伤天害理的事情，所以虬先生才是这里唯一的好人。",
          DialogueId = 51127814,
          GUID = "7FFE3CFC",
          SpeakNpcId = 701070,
          Subtitle = "No, no — Mr Qiu's the exception! He's only here to keep that rabble in line, to stop them doing all those wicked, heartless things. He's the only decent soul in this pit."
        },
        [51127815] = {
          Content = "你觉得虬先生就是干净的？",
          DialogueId = 51127815,
          GUID = "7FFE3D26",
          NextDialogue = 51127816,
          Subtitle = "You really think Mr Qiu's clean?"
        },
        [51127816] = {
          Content = "虬先生就是黑市里开出的荷花！出淤泥而不染，他能在这大染缸之中自保，并混出了自己的名头，已经很了不起了，你这种小孩不会理解的。",
          DialogueId = 51127816,
          GUID = "7FFE3D50",
          SpeakNpcId = 701070,
          Subtitle = "Mr Qiu's like a lotus rising from the muck — pure and untouched by the filth around him! To stay that clean in a place like this, and still make a name for himself... remarkable, truly remarkable. You're too young to understand."
        },
        [51127817] = {
          Content = "你这么厌恶微茫市，为什么还和虬先生做生意？",
          DialogueId = 51127817,
          GUID = "7FFE3D7A",
          NextDialogue = 51127818,
          Subtitle = "If you despise Haze Market so much, why do business with Mr Qiu?"
        },
        [51127818] = {
          Content = "虬先生……虬先生他不一样……",
          DialogueId = 51127818,
          GUID = "7FFE3DA4",
          NextDialogue = 51127819,
          SpeakNpcId = 701070,
          Subtitle = "Mr Qiu... he's different."
        },
        [51127819] = {
          Content = "虬先生是大才，无论是生意场还是收藏界，他可都是鼎鼎有名的人物。不止如此，和他相处时的感觉也让人舒服，他总能洞察你真实的需求。",
          DialogueId = 51127819,
          GUID = "7FFE3DCE",
          NextDialogue = 51127820,
          SpeakNpcId = 701070,
          Subtitle = "He's a man of real talent — everyone in business, every collector worth his salt, knows his name. More than that, he's a pleasure to deal with — it's like he sees straight through you."
        },
        [51127820] = {
          Content = "有句话怎么说来着，和聪明人做事，话只用说一半，对方便能知晓你的想法，并竭力满足你。",
          DialogueId = 51127820,
          GUID = "7FFE3DF8",
          NextOptions = {
            [1] = 51127821
          },
          SpeakNpcId = 701070,
          Subtitle = "There's a saying — when you work with clever folk, you never need to finish your words. They'll catch your meaning and see it done before you even ask."
        },
        [51127821] = {
          Content = "还有呢？",
          DialogueId = 51127821,
          GUID = "7FFE3E22",
          NextDialogue = 51127822,
          Subtitle = "Anything else, then?"
        },
        [51127822] = {
          Content = "还有，那可太多了，虬先生出钱爽快，从我这定的陈皮，都是百年起步的，在这华胥没几个人买得起这么稀有的东西！",
          DialogueId = 51127822,
          GUID = "7FFE3E4C",
          NextDialogue = 51127823,
          SpeakNpcId = 701070,
          Subtitle = "Oh, plenty! Mr Qiu's generous to a fault — every batch of aged tangerine peel he buys off me is over a hundred years old! Not many in Huaxu can afford such treasures, I can tell you that."
        },
        [51127823] = {
          Content = "他还私下资助考古事业，我们华胥泱泱前年的历史，若不是虬先生出资挖掘，怕是多少时日都难见天日。",
          DialogueId = 51127823,
          GUID = "7FFE3E76",
          NextDialogue = 51127824,
          SpeakNpcId = 701070,
          Subtitle = "He even funds archaeology out of his own pocket! Without his support, half of Huaxu's glorious past would still be buried underground, never seeing daylight."
        },
        [51127824] = {
          Content = "还有……",
          DialogueId = 51127824,
          GUID = "7FFE3EA0",
          NextOptions = {
            [1] = 51127825,
            [2] = 51127828
          },
          SpeakNpcId = 701070,
          Subtitle = "And besides that... let me think..."
        },
        [51127825] = {
          Content = "还有呢？",
          DialogueId = 51127825,
          GUID = "7FFE3ECA",
          NextDialogue = 51127826,
          Subtitle = "Yeah?"
        },
        [51127826] = {
          Content = "讲义气啊！我们这些经常来往的熟人，逢年过节，虬先生总是会给咱们都寄上些礼品，有时候是精致名点，有时是珍奇古玩，总是少不了的。",
          DialogueId = 51127826,
          GUID = "7FFE3EF4",
          NextDialogue = 51127827,
          SpeakNpcId = 701070,
          Subtitle = "Generous, that's what he is! Those of us who deal with him often — every festival, every holiday — Mr Qiu never forgets us. One time it's fine pastries, another time rare curios... he's thoughtful like that, always is."
        },
        [51127827] = {
          Content = "如果不是虬先生对大家如此之好，我何必还苦兮兮跑来这黑市等着他与他交易……",
          DialogueId = 51127827,
          GUID = "7FFE3F1E",
          SpeakNpcId = 701070,
          Subtitle = "If he weren't so good to us, do you think I'd drag myself all the way down to this wretched place just to wait on him?"
        },
        [51127828] = {
          Content = "好了不要再说了，知道你是虬吹了。",
          DialogueId = 51127828,
          GUID = "7FFE3F48",
          NextDialogue = 51127829,
          Subtitle = "All right, all right — I get it, you're a hardcore fan of his."
        },
        [51127829] = {
          Content = "什么意思，你们这些小孩嘴里说出的词语总是让我听不明白，就像我那八岁的女儿，一天到晚都在那说什么……又能怎……语气怪怪的。",
          DialogueId = 51127829,
          GUID = "7FFE3F72",
          NextDialogue = 51127830,
          SpeakNpcId = 701070,
          Subtitle = "A what now? \"Hardcore\"? You young folk and your bizarre jargon — half the time I've no idea what you're on about! Just like my eight-year-old, always tossing around some new term... what was it she said the other day—?"
        },
        [51127830] = {
          Content = "说起来我那女儿，也很喜欢老虬，老虬来我家时，总会给她额外捎上些甜品果子，她每回都盼着他来……",
          DialogueId = 51127830,
          GUID = "7FFE3F9C",
          SpeakNpcId = 701070,
          Subtitle = "Speaking of my little girl — she's quite taken with Mr Qiu herself! Whenever he visits, he brings her sweets, fine pastries... she's forever asking when he'll come again."
        },
        [51127831] = {
          Content = "我先溜了！",
          DialogueId = 51127831,
          GUID = "7FFE3FC6",
          NextDialogue = 51127832,
          Subtitle = "I'm off."
        },
        [51127832] = {
          Content = "怎么就走了，你还没说你来这里是做什么的呢！",
          DialogueId = 51127832,
          GUID = "7FFE3FF0",
          SpeakNpcId = 701070,
          Subtitle = "Off already? But you never told me what brings you here!"
        },
        [51127901] = {
          Content = "（这只狴犴的状态看起来很不对劲，似乎在变黑与保持白色之间摇摆不定……）",
          DialogueId = 51127901,
          GUID = "7FFE4B42",
          NextOptions = {
            [1] = 51127902,
            [2] = 51127907
          },
          Subtitle = "(Its form flickers between shadow and pale light, as though it's fighting itself.)"
        },
        [51127902] = {
          Content = "我能帮你什么吗？",
          DialogueId = 51127902,
          GUID = "7FFE4B6C",
          NextDialogue = 51127903,
          Subtitle = "Can I help you somehow?"
        },
        [51127903] = {
          Content = "呼……",
          DialogueId = 51127903,
          GUID = "7FFE4B96",
          NextDialogue = 51127904,
          SpeakNpcId = 701071,
          Subtitle = "Huff..."
        },
        [51127904] = {
          Content = "（它看了你一眼，眼底猩红，不知是受了伤还是在竭力保持清醒。）",
          DialogueId = 51127904,
          GUID = "7FFE4BC0",
          NextDialogue = 51127905,
          Subtitle = "(It raises its head, bloodshot eyes meeting yours — whether from pain or the effort of holding itself together, you cannot tell.)"
        },
        [51127905] = {
          Content = "……呜……噫呜……呜……",
          DialogueId = 51127905,
          GUID = "7FFE4BEA",
          NextDialogue = 51127906,
          SpeakNpcId = 701071,
          Subtitle = "...Groan... grhh... rrhh..."
        },
        [51127906] = {
          Content = "（狴犴在你面前自绝了。）",
          DialogueId = 51127906,
          GUID = "7FFE4C14",
          NextOptions = {
            [1] = 51127912,
            [2] = 51127914
          },
          Subtitle = "(Before your eyes, the Bi'an takes its own life.)"
        },
        [51127907] = {
          Content = "（拿起武器，做好防备。）",
          DialogueId = 51127907,
          GUID = "7FFE4C3E",
          NextDialogue = 51127908,
          Subtitle = "(Ready your weapon.)"
        },
        [51127908] = {
          Content = "嗷！",
          DialogueId = 51127908,
          GUID = "7FFE4C68",
          NextDialogue = 51127909,
          SpeakNpcId = 701071,
          Subtitle = "Rraugh!"
        },
        [51127909] = {
          Content = "（在你露出刀光的那一刹，狴犴仰天长啸，向你冲来，却因力竭跌倒在地。）",
          DialogueId = 51127909,
          GUID = "7FFE4C92",
          NextDialogue = 51127910,
          Subtitle = "(As your blade flashes, the Bi'an snaps — its body swallowed by darkness as it lunges at you.)"
        },
        [51127910] = {
          Content = "嗷呜呜……呜……",
          DialogueId = 51127910,
          GUID = "7FFE4CBC",
          NextDialogue = 51127911,
          SpeakNpcId = 701071,
          Subtitle = "Awoo... whuh... rrhh..."
        },
        [51127911] = {
          Content = "（狴犴在你面前咽了气。）",
          DialogueId = 51127911,
          GUID = "7FFE4CE6",
          NextOptions = {
            [1] = 51127912,
            [2] = 51127914
          },
          Subtitle = "(The creature collapses at your feet, its final breath fading into silence.)"
        },
        [51127912] = {
          Content = "安葬狴犴。",
          DialogueId = 51127912,
          GUID = "7FFE4D10",
          ImprPlusId = 1207,
          NextDialogue = 51127913,
          Subtitle = "Bury the Bi'an."
        },
        [51127913] = {
          Content = "（你将这只死去的狴犴好好安葬了……）",
          DialogueId = 51127913,
          GUID = "7FFE4D3A",
          Subtitle = "(You lay the fallen beast to rest, as gently as you can.)"
        },
        [51127914] = {
          Content = "离开吧。",
          DialogueId = 51127914,
          GUID = "7FFE4D64",
          ImprPlusId = 1211,
          NextDialogue = 51127915,
          Subtitle = "I'm leaving."
        },
        [51127915] = {
          Content = "（自尘土中来，归尘土中去……）",
          DialogueId = 51127915,
          GUID = "7FFE4D8E",
          Subtitle = "(From dust it rose — and to dust it fades...)"
        },
        [51128001] = {
          Content = "嘶……又冷起来了，这鬼天气！我带来的考古器材全都结了一层晶，零件迟钝，反应不灵，诶！又要让虬先生破费维修了！",
          DialogueId = 51128001,
          GUID = "7FFE5BAA",
          NextDialogue = 51128002,
          SpeakNpcId = 701072,
          Subtitle = "Brr... freezing again. Rotten weather. Everything's frosted up — gears stiff, sensors half-asleep. Oh dear. Mr Qiu'll have to foot the repairs again."
        },
        [51128002] = {
          Content = "咦？你是谁？你怎么会跑到这种地方来？快回去快回去，这里可不是等闲之辈可以随意来往的地方！",
          DialogueId = 51128002,
          GUID = "7FFE5BD4",
          NextOptions = {
            [1] = 51128003,
            [2] = 51128005
          },
          SpeakNpcId = 701072,
          Subtitle = "Hmm? Who are you? What are you doing out here? Off you pop, now. This isn't a place ordinary folk are meant to wander!"
        },
        [51128003] = {
          Content = "（听到她提起虬先生……）我是虬先生叫过来的。",
          DialogueId = 51128003,
          GUID = "7FFE5BFE",
          ImprPlusId = 1208,
          NextDialogue = 51128004,
          Subtitle = "Mr Qiu sent me."
        },
        [51128004] = {
          Content = "虬先生叫你来的？怎么可能？不是说了尘漠石海区域只由我一人来负责就好吗？来之前还说的……什么什么，无甚旧史，不必细考的……",
          DialogueId = 51128004,
          GUID = "7FFE5C28",
          SpeakNpcId = 701072,
          Subtitle = "He did? That can't be right. He said the Gritblight Expanse was my brief alone. Before I left he even said— what was it — \"no old records, nothing worth digging into,\" or something along those lines."
        },
        [51128005] = {
          Content = "看你一个人在这很危险，就过来看看。",
          DialogueId = 51128005,
          GUID = "7FFE5C52",
          ImprPlusId = 1207,
          NextDialogue = 51128006,
          Subtitle = "You looked as if you needed a hand, so I thought I'd check in."
        },
        [51128006] = {
          Content = "呜呜呜，谢谢你好心人，我在这太久了，风餐露宿的，都快忘了还有除了玄色狴犴之外的正常人存在了。",
          DialogueId = 51128006,
          GUID = "7FFE5C7C",
          NextDialogue = 51128007,
          SpeakNpcId = 701072,
          Subtitle = "Oh, thank you, kind soul! I've been out here so long — camping in the wind and sleeping under the stars — that I'd almost forgotten normal life being existed... apart from those Sable Bi'an prowling around."
        },
        [51128007] = {
          Content = "不管怎么说，你也得先回去多带些衣服，这里的温差特殊，没一会就要冷得结冰了。",
          DialogueId = 51128007,
          GUID = "7FFE5CA6",
          NextDialogue = 51128008,
          SpeakNpcId = 701072,
          Subtitle = "Still, you'd best go home and grab a thicker coat. With the swings here you'll be frozen stiff in no time."
        },
        [51128008] = {
          Content = "呼……我也得去加上两件衣服了。",
          DialogueId = 51128008,
          GUID = "7FFE5CD0",
          SpeakNpcId = 701072,
          Subtitle = "Whew. I'd better throw on a couple more layers myself."
        },
        [51128101] = {
          Content = "一会冷一会热……想当年我姥姥还跟我说，这里是个春暖花开的好地方呢！",
          DialogueId = 51128101,
          GUID = "7FFE6C12",
          NextDialogue = 51128102,
          SpeakNpcId = 701072,
          Subtitle = "Hot one minute, freezing the next... My grandmother always said it used to be spring all round."
        },
        [51128102] = {
          Content = "啊啊啊！又热起来了！一热起来我就心烦气躁！臭外套，滚一边去吧！",
          DialogueId = 51128102,
          GUID = "7FFE6C3C",
          NextDialogue = 51128103,
          SpeakNpcId = 701072,
          Subtitle = "Ah—! It's scorching again! Heat makes me tetchy. Ugh, this wretched coat — off you come!"
        },
        [51128103] = {
          Content = "你！你是谁！哦！我想起来了，你之前来过这里！衣服带好了吗？这就回来啦？",
          DialogueId = 51128103,
          GUID = "7FFE6C66",
          NextOptions = {
            [1] = 51128104,
            [2] = 51128106,
            [3] = 51128120
          },
          SpeakNpcId = 701072,
          Subtitle = "Hey! Who are y— oh, right, I remember you. Back again, are you? Brought a coat this time?"
        },
        [51128104] = {
          Content = "我包里有很多件。",
          DialogueId = 51128104,
          GUID = "7FFE6C90",
          NextDialogue = 51128105,
          Subtitle = "Got plenty in my pack."
        },
        [51128105] = {
          Content = "那就好，你可不知道这里的天气有多怪，一会冷得牙齿打颤，一会又热得满头大汗，真是要了命了。",
          DialogueId = 51128105,
          GUID = "7FFE6CBA",
          NextOptions = {
            [1] = 51128108
          },
          SpeakNpcId = 701072,
          Subtitle = "Good. You've no idea how absurd this weather gets — teeth chattering one minute, sweating buckets the next. It's crazy."
        },
        [51128106] = {
          Content = "我不怕冷，也不怕热。",
          DialogueId = 51128106,
          GUID = "7FFE6CE4",
          NextDialogue = 51128107,
          Subtitle = "I don't mind the cold or the heat."
        },
        [51128107] = {
          Content = "什么？！那是你没见识过这里的天气有多怪！一会冷得牙齿打颤，一会又热得满头大汗，真是要了命了。",
          DialogueId = 51128107,
          GUID = "7FFE6D0E",
          NextOptions = {
            [1] = 51128108
          },
          SpeakNpcId = 701072,
          Subtitle = "What? Then you've not seen it at its worst. Give it an hour — teeth chattering one minute, sweating buckets the next. It's crazy."
        },
        [51128108] = {
          Content = "这里的天气为什么奇怪？",
          DialogueId = 51128108,
          GUID = "7FFE6D38",
          NextDialogue = 51128109,
          Subtitle = "What's with the weather here?"
        },
        [51128109] = {
          Content = "嘿！你要问这个，我可太有发言权了，我在这待了这么久，可算把这地方的历史和劳什子浊化现象整明白了七七八八。",
          DialogueId = 51128109,
          GUID = "7FFE6D62",
          NextDialogue = 51128122,
          SpeakNpcId = 701072,
          Subtitle = "Ha! You've come to the right person. I've been out here so long I've nearly pieced the whole story together — this place and that blasted Blightening."
        },
        [51128110] = {
          Content = "聊聊这里的曾经。",
          DialogueId = 51128110,
          GUID = "7FFE6D8C",
          NextDialogue = 51128111,
          Subtitle = "What was it like before?"
        },
        [51128111] = {
          Content = "以前啊，我太姥姥说的，说这里是个好地方，好山好水，山川纵横，美景如画，四季如春。那时这还没那么荒，有人会在山上种半步仙。",
          DialogueId = 51128111,
          GUID = "7FFE6DB6",
          NextDialogue = 51128112,
          SpeakNpcId = 701072,
          Subtitle = "Long ago — so my great-grandmother used to say — it was all green hills and clear streams, spring the year round. People even planted Heavenstep on the slopes."
        },
        [51128112] = {
          Content = "那花一开，满山都是红艳艳的，香气熏得人昏昏沉沉，扰得路过的织星客们纷纷投诉，说是从这路上走就会香昏迷过去。",
          DialogueId = 51128112,
          GUID = "7FFE6DE0",
          SpeakNpcId = 701072,
          Subtitle = "When the flowers were out, the hills went scarlet and the scent was heady enough to make travellers woozy. Even the Starweavers complained it could make you swoon."
        },
        [51128113] = {
          Content = "聊聊这里为什么会变成这样。",
          DialogueId = 51128113,
          GUID = "7FFE6E0A",
          NextDialogue = 51128114,
          Subtitle = "How did it get like this?"
        },
        [51128114] = {
          Content = "还能因为什么，烛阴之灾呗。那恶兽，贼心不死，吞吐之间全是黑雾，雾气从海上向内地不断扩散，直至覆盖整个区域。",
          DialogueId = 51128114,
          GUID = "7FFE6E34",
          NextDialogue = 51128115,
          SpeakNpcId = 701072,
          Subtitle = "What else? The Scourge of Zhuyin, of course. Vile thing — spewing a black mist that rolls in from the sea and smothers the lot."
        },
        [51128115] = {
          Content = "黑雾还邪气着呢！被影响的地方一会冷一会热，山上的石头受不住这温差，全碎成了块块。那花啊草啊的也不长了，盖上了一层不知道什么东西。",
          DialogueId = 51128115,
          GUID = "7FFE6E5E",
          NextDialogue = 51128116,
          SpeakNpcId = 701072,
          Subtitle = "The black mist was foul. Wherever it spread, the air flipped from freezing to scorching in a heartbeat. The jolts split rock to bits, and every flower and blade of grass withered under a strange crust."
        },
        [51128116] = {
          Content = "这种现象就是浊化，也是我一直在这里研究的方向。",
          DialogueId = 51128116,
          GUID = "7FFE6E88",
          SpeakNpcId = 701072,
          Subtitle = "That's what we call Blightening — the very thing I've been studying out here."
        },
        [51128117] = {
          Content = "聊聊浊化。",
          DialogueId = 51128117,
          GUID = "7FFE6EB2",
          NextDialogue = 51128118,
          Subtitle = "What exactly is Blightening?"
        },
        [51128118] = {
          Content = "唔……这其实很难说，但我的初步推测是，黑雾里有种晶尘，肉眼看不到，但是会在呼吸之间被吸入体内。",
          DialogueId = 51128118,
          GUID = "7FFE6EDC",
          NextDialogue = 51128119,
          SpeakNpcId = 701072,
          Subtitle = "Hmm... hard to pin down. My best guess is that the black mist carries crystalline motes — too fine to see, easy to breathe in without noticing."
        },
        [51128119] = {
          Content = "被这种晶尘影响的生物，原本的形态就会被破坏。原理嘛……搞不懂！但是邪门的很，不是我说，狴犴大人都抵挡不了呢！",
          DialogueId = 51128119,
          GUID = "7FFE6F06",
          SpeakNpcId = 701072,
          Subtitle = "Anything that takes them in warps out of shape. As for the cause... no idea. Uncanny stuff — even the Bi'an can't fight it off."
        },
        [51128120] = {
          Content = "不和你聊了",
          DialogueId = 51128120,
          GUID = "7FFE6F30",
          NextDialogue = 51128121,
          Subtitle = "That'll do for now."
        },
        [51128121] = {
          Content = "好不容易等来个聊聊天的，诶……再不和正常人说说话，我的嘴巴可就要生锈啦。",
          DialogueId = 51128121,
          GUID = "7FFE6F5A",
          SpeakNpcId = 701072,
          Subtitle = "Aw, don't go! Took me ages to find someone to chat with. If I don't talk to a normal human soon, my tongue'll go rusty."
        },
        [51128122] = {
          DialogueId = 51128122,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51128121,
          GUID = "7FFE6F84",
          NextOptions = {
            [1] = 51128110,
            [2] = 51128113,
            [3] = 51128117,
            [4] = 51128120
          }
        },
        [51128201] = {
          Content = "这怎么连个插香的地方都没有……还好我带了香炉！不然今天好不容易铤而走险过来一趟，要是啥也没干就回去可太丢面子了！",
          DialogueId = 51128201,
          GUID = "7FFE7C7A",
          NextOptions = {
            [1] = 51128202,
            [2] = 51128204
          },
          SpeakNpcId = 701073,
          Subtitle = "What— no place to set the incense? Good job I brought a burner! After risking my neck to get here, it'd be a bit rich to leave empty-handed!"
        },
        [51128202] = {
          Content = "你怎么一个人在这，这里很危险。",
          DialogueId = 51128202,
          GUID = "7FFE7CA4",
          ImprPlusId = 1207,
          NextDialogue = 51128203,
          Subtitle = "What are you doing out here? It's dangerous."
        },
        [51128203] = {
          Content = "我当然知道危险啦，多谢你的提醒，但我就是图着危险才特意来此处的！我偏要来这旁人不敢涉足之地，点上一根沉月香给白龙神君，求他将烛阴之灾彻底扫除！",
          DialogueId = 51128203,
          GUID = "7FFE7CCE",
          SpeakNpcId = 701073,
          Subtitle = "I know! Thanks for the warning. That's exactly why I'm here. I'll light a stick of Lunarose for Lord Argent where only the brave venture, and beg Them to purge the Scourge of Zhuyin once and for all!"
        },
        [51128204] = {
          Content = "再等一会就有玄色狴犴来吃你咯。",
          DialogueId = 51128204,
          GUID = "7FFE7CF8",
          ImprPlusId = 1205,
          NextDialogue = 51128205,
          Subtitle = "Linger any longer and a Sable Bi'an will be along to make a meal of you."
        },
        [51128205] = {
          Content = "莫慌莫慌，我自是知道此地危险，但是我偏要来这旁人不敢涉足之地，点上一根沉月香给白龙神君，求他将烛阴之灾彻底扫除！",
          DialogueId = 51128205,
          GUID = "7FFE7D22",
          NextDialogue = 51128206,
          SpeakNpcId = 701073,
          Subtitle = "No need to fret. I know it's dangerous — that's the point. I'm lighting a stick of Lunarose for Lord Argent right here, where only the brave venture, and begging Him to purge the Scourge of Zhuyin for good."
        },
        [51128206] = {
          Content = "不必担心我，我虽手无寸铁，但胜在机灵跑得快，且不是第一天来这了。反倒是你要担心自己，是那玄色狴犴找过来，我拔腿就跑时带不上你。",
          DialogueId = 51128206,
          GUID = "7FFE7D4C",
          NextDialogue = 51128207,
          SpeakNpcId = 701073,
          Subtitle = "Don't worry about me. I've no weapon, true, but I've got quick legs and a quicker head! It isn't my first time out here. You watch yourself — if a Sable Bi'an shows up, I'll be off like a shot and won't have time to haul you along."
        },
        [51128207] = {
          Content = "所以你先走吧，不用管我！",
          DialogueId = 51128207,
          GUID = "7FFE7D76",
          SpeakNpcId = 701073,
          Subtitle = "Go on then — don't trouble over me!"
        },
        [51128208] = {
          Content = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
          DialogueId = 51128208,
          GUID = "7FFE7DA0",
          NextDialogue = 51128209,
          SpeakNpcId = 701073,
          Subtitle = "Here we are! Once I light the incense, Lord Argent will surely descend and wipe that wicked beast out for good — just like in the old tales!"
        },
        [51128209] = {
          Content = "诶哟，怎么又是你，你也真不害怕呢，这种地方你还一遍又一遍地来。",
          DialogueId = 51128209,
          GUID = "7FFE7DCA",
          NextOptions = {
            [1] = 51128210,
            [2] = 51128233
          },
          SpeakNpcId = 701073,
          Subtitle = "Huh? You again. You've got nerve, coming back to a place like this."
        },
        [51128210] = {
          Content = "这话该是我说你吧……",
          DialogueId = 51128210,
          GUID = "7FFE7DF4",
          NextDialogue = 51128211,
          Subtitle = "I could say the same about you..."
        },
        [51128211] = {
          Content = "哦！说的也是呢，我才是一遍又一遍来这的，不过不是说了嘛，我机灵跑得快，哪怕遇到危险也可以逃走的，为了你的安全，你还是先走吧。",
          DialogueId = 51128211,
          GUID = "7FFE7E1E",
          NextOptions = {
            [1] = 51128212
          },
          SpeakNpcId = 701073,
          Subtitle = "Ha! Fair point. Like I said, I'm quick on my feet. If trouble turns up, I'll be gone before it catches me. You should head out, though — safer that way."
        },
        [51128212] = {
          Content = "我压根不用逃，直接击退玄色狴犴都可以。",
          DialogueId = 51128212,
          GUID = "7FFE7E48",
          NextDialogue = 51128213,
          Subtitle = "I don't need to run. I can drive the Sable Bi'an off myself."
        },
        [51128213] = {
          Content = "看不出来啊，没想到你这么厉害，那你应该不是华胥人吧，唔……穿着打扮的确不是很像……",
          DialogueId = 51128213,
          GUID = "7FFE7E72",
          NextDialogue = 51128214,
          SpeakNpcId = 701073,
          Subtitle = "Really? Didn't take you for the tough sort. You're not from Huaxu, are you? Your clothes don't look Huaxu, either."
        },
        [51128214] = {
          Content = "那你要跟我一起奉香吗？要是有两个人一起，想必白龙神君更能听到我们的求助！",
          DialogueId = 51128214,
          GUID = "7FFE7E9C",
          NextOptions = {
            [1] = 51128215,
            [2] = 51128221
          },
          SpeakNpcId = 701073,
          Subtitle = "Will you join me in offering incense, then? Two voices together — surely Lord Argent will hear us better."
        },
        [51128215] = {
          Content = "你在这荒郊野岭奉香不是很奇怪吗？",
          DialogueId = 51128215,
          GUID = "7FFE7EC6",
          NextDialogue = 51128216,
          Subtitle = "Doesn't it feel a bit odd to offer incense out in the middle of nowhere?"
        },
        [51128216] = {
          Content = "诶，这你就有所不知了，你应该知道此地天象异诡是何原因吧，就是那百年之前危害华胥的烛阴之灾，可你知不知道，烛阴这只恶兽为何会造成灾害呢？",
          DialogueId = 51128216,
          GUID = "7FFE7EF0",
          NextDialogue = 51128217,
          SpeakNpcId = 701073,
          Subtitle = "You don't know the half of it. You know why the skies twist and churn here, don't you? It's because of the Scourge of Zhuyin a hundred years ago. But do you know why that foul beast brought such ruin on Huaxu?"
        },
        [51128217] = {
          Content = "算啦，我也就不卖关子了，直接告诉你吧。在咱们华胥上古时期，有一只为非作歹的妖兽，名为烛阴。",
          DialogueId = 51128217,
          GUID = "7FFE7F1A",
          NextDialogue = 51128218,
          SpeakNpcId = 701073,
          Subtitle = "All right, I won't keep you guessing. Long ago in Huaxu, there lived a wicked creature called Zhuyin."
        },
        [51128218] = {
          Content = "其以不安之心篡夺华胥人行凶作恶，伤人见血，百姓因其作乱民不聊生，叫苦不迭。百姓们便轮番点香，求助于神君。",
          DialogueId = 51128218,
          GUID = "7FFE7F44",
          NextDialogue = 51128219,
          SpeakNpcId = 701073,
          Subtitle = "It sowed unrest in people's hearts and drove them to harm one another. The land fell into misery and people knew no peace, so they lit incense — one after another — and prayed for Lord Argent's help."
        },
        [51128219] = {
          Content = "白龙神君在九天之上，闻到了百姓们点的沉月香，遂勃然大怒。动用神力将之驱逐至华胥海外。",
          DialogueId = 51128219,
          GUID = "7FFE7F6E",
          NextDialogue = 51128220,
          SpeakNpcId = 701073,
          Subtitle = "On high, Lord Argent caught the scent of the incense, learned of Zhuyin's crime, and grew wrathful. It called on Its divine might and banished the beast beyond Huaxu's shores."
        },
        [51128220] = {
          Content = "悬衡派仙人们齐心协力，以锁龙环将烛阴层层束缚在仙山之上，才让华胥重回安宁与祥和之中。",
          DialogueId = 51128220,
          GUID = "7FFE7F98",
          NextOptions = {
            [1] = 51128223
          },
          SpeakNpcId = 701073,
          Subtitle = "Then the immortals of the Xuanheng Sect combined their strength, bound Zhuyin with the Loong Seal, and sealed it upon the sacred mountain. Only then did Huaxu know peace again."
        },
        [51128221] = {
          Content = "好，给我一支。",
          DialogueId = 51128221,
          GUID = "7FFE7FC2",
          NextDialogue = 51128222,
          Subtitle = "Sure. Let's do this."
        },
        [51128222] = {
          Content = "（你陪着他一起奉了根香。）",
          DialogueId = 51128222,
          GUID = "7FFE7FEC",
          NextOptions = {
            [1] = 51128223
          },
          Subtitle = "(You take a stick of incense and join him in the offering.)"
        },
        [51128223] = {
          Content = "所以你是想来复刻神话里的奉香行为，呼唤白龙神君？",
          DialogueId = 51128223,
          GUID = "7FFE8016",
          NextDialogue = 51128224,
          Subtitle = "So you mean to call Lord Argent the way people did in the old tales?"
        },
        [51128224] = {
          Content = "正是如此！我想着，定是现在大家整日都在奉香，白龙神君闻到哪哪都是香味，不知该帮哪里了。不如我来这无人之境奉香，神君一定会很好奇。",
          DialogueId = 51128224,
          GUID = "7FFE8040",
          NextDialogue = 51128225,
          SpeakNpcId = 701073,
          Subtitle = "That's right. These days everyone's burning incense everywhere — Lord Argent must catch it from all sides and hardly know who needs It most! So I figured if I burn mine here, where no one ever comes, It'll take notice."
        },
        [51128225] = {
          Content = "好奇什么？",
          DialogueId = 51128225,
          GUID = "7FFE806A",
          NextDialogue = 51128226,
          SpeakNpcId = 100001,
          Subtitle = "Take notice of what, exactly?"
        },
        [51128226] = {
          Content = "好奇为何这人烟稀少之地会有香气啊！足见我心诚之滔滔！",
          DialogueId = 51128226,
          GUID = "7FFE8094",
          NextDialogue = 51128227,
          SpeakNpcId = 701073,
          Subtitle = "That there's incense burning in the middle of nowhere, of course! They'll see how sincere my heart is!"
        },
        [51128227] = {
          Content = "……",
          DialogueId = 51128227,
          GUID = "7FFE80BE",
          NextDialogue = 51128228,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51128228] = {
          Content = "好啦，不多说了，你要跟我一起来奉吗？",
          DialogueId = 51128228,
          GUID = "7FFE80E8",
          NextOptions = {
            [1] = 51128229,
            [2] = 51128231
          },
          SpeakNpcId = 701073,
          Subtitle = "Right, enough chatter. Will you light another stick with me?"
        },
        [51128229] = {
          Content = "可以。",
          DialogueId = 51128229,
          GUID = "7FFE8112",
          NextDialogue = 51128230,
          Subtitle = "All right."
        },
        [51128230] = {
          Content = "来！今日我等一起奉香，明日你我皆是挚友！",
          DialogueId = 51128230,
          GUID = "7FFE813C",
          SpeakNpcId = 701073,
          Subtitle = "Great! Incense side by side today — fast friends tomorrow!"
        },
        [51128231] = {
          Content = "算了吧。",
          DialogueId = 51128231,
          GUID = "7FFE8166",
          NextDialogue = 51128232,
          Subtitle = "I'll pass."
        },
        [51128232] = {
          Content = "那好吧，你们外国人是不懂我们这些讲究的。",
          DialogueId = 51128232,
          GUID = "7FFE8190",
          SpeakNpcId = 701073,
          Subtitle = "Fair enough — outsiders don't always get our ways."
        },
        [51128233] = {
          Content = "有别的事，我先走了。",
          DialogueId = 51128233,
          GUID = "7FFE81BA",
          NextDialogue = 51128234,
          Subtitle = "I've got other things to do. I should get going."
        },
        [51128234] = {
          Content = "哦哦，那好吧！有缘再会！",
          DialogueId = 51128234,
          GUID = "7FFE81E4",
          SpeakNpcId = 701073,
          Subtitle = "All right, then. Until fate brings us together again!"
        },
        [51128301] = {
          Content = "（不知何人立的碑，碑上的字是……）",
          DialogueId = 51128301,
          GUID = "7FFE8CE2",
          NextDialogue = 51128302,
          Subtitle = "(No hand is named. This stele bears these words:)"
        },
        [51128302] = {
          DialogueId = 51128302,
          DialoguePanelType = "{type:showtext;topic:SCEREAD_NAME_1000001;content:SCEREAD_TEXT_1000001}",
          GUID = "7FFE8D0C"
        },
        [51128401] = {
          Content = "（石碑上刻着密密麻麻的铭文，似是对一些人的纪念。）",
          DialogueId = 51128401,
          GUID = "7FFE9D4A",
          NextDialogue = 51128402,
          Subtitle = "(Upon the stone run close-set lines — a memorial to the fallen.)"
        },
        [51128402] = {
          DialogueId = 51128402,
          DialoguePanelType = "{type:showtext;topic:SCEREAD_NAME_1000002;content:SCEREAD_TEXT_1000002}",
          GUID = "7FFE9D74"
        },
        [51140001] = {
          Camera = "-113.539062,61.592773,195.840332,0.000114,-25.089722,-48.41589,35.000008,218.514374,false,Manual,1.894586",
          Content = "不知道为什么……每次走在幽明涧，总觉得身后有阵阵凉风，冷飕飕地往我的领口里钻……",
          DialogueId = 51140001,
          GUID = "80060C6A",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          Scripts = "SetVisibility{ActorId{701074},Visibility{\"Hide\"}}",
          SpeakNpcId = 200002,
          Subtitle = "I don't know why... Whenever I walk through Twilight Ravine, these cold draughts crawl down my back and sneak straight into my collar...",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          }
        },
        [51140002] = {
          Camera = "-113.539062,61.592773,195.840332,0.000114,-25.089722,-48.41589,35.000008,218.514374,false,Manual,1.894586",
          Content = "那种感觉就像是我在水仙平原偷懒，卡米拉从背后阴恻恻地靠过来，然后……",
          DialogueId = 51140002,
          GUID = "80060C94",
          Scripts = "SetVisibility{ActorId{701074},Visibility{\"Hide\"}}",
          SpeakNpcId = 200002,
          Subtitle = "It's just like back at The Asphodel when I'm trying to sneak off for a break, and Camilla creeps up behind me with that icy stare, and then—",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          }
        },
        [51140003] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "敢问二位……",
          DialogueId = 51140003,
          FinalCamera = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
          GUID = "80060CBE",
          Scripts = "SetVisibility{ActorId{701074},Visibility{\"Show\"}}",
          SpeakNpcId = 701074,
          SpeakNpcName = "UI_NPC_Name_mosheng_Sce",
          Subtitle = "Er, pardon me...",
          TalkActionId = {
            [1] = "701074:Wuyou_Born"
          },
          ToFinalCameraBlendTime = 0.2
        },
        [51140004] = {
          Camera = "-339.228027,-47.569336,251.475708,0.000101,-29.99987,-4.83933,61.07761,402.688873,false,Manual,7.0",
          Content = "呜啊！有鬼啊！！！",
          DialogueId = 51140004,
          GUID = "80060CE8",
          LookAt = {
            [1] = "200002:n(200002)",
            [2] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Waaah! A—A ghost!?",
          TalkActionId = {
            [1] = "200002:Afraid_Start",
            [2] = "100001:Talk03_Start"
          }
        },
        [51140005] = {
          Camera = "-339.228027,-47.569336,251.475708,0.000101,-29.99987,-4.83933,61.07761,402.688873,false,Manual,7.0",
          Content = "哪哪——哪里来的妖魔鬼怪！胆胆胆敢恐——恐吓本魔王大人！信不信我——玄黄什么什么……糟糕，后面想不起来了！",
          DialogueId = 51140005,
          GUID = "80060D12",
          LookAt = {
            [1] = "100001:n(701074)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Wh—Wh—What are you!? H—How dare you try to scare the great Demon King! I'll blast you with... my exorcism powers or something!",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51140006] = {
          Camera = "763.383301,600.294922,831.858032,0.000046,-32.495926,-142.840744,35.000008,100000.0,false,DoNotOverride,7.0",
          Content = "竟然听得到我说话？太好了！惊扰二位非尾生有意之举，在此向二位致歉，还望海涵。",
          DialogueId = 51140006,
          GUID = "80060D3C",
          SpeakNpcId = 701074,
          Subtitle = "You can actually hear me? Wonderful! I'm Weisheng, and I never meant to startle either of you. Please accept my apologies.",
          TalkActionId = {
            [1] = "200002:Afraid_End"
          }
        },
        [51140007] = {
          Camera = "-205.567871,-119.201172,110.475708,0.000172,0.0,5.771363,35.000015,187.02475,false,Manual,7.0",
          Content = "什么嘛，原来是无由生，你怎么突然冒出来，吓了我好一大跳……看在你道歉态度诚恳的份上，魔王大人就原谅你了。",
          DialogueId = 51140007,
          GUID = "80060D66",
          Scripts = [[
SEQ
{
PARA{
PlayAnimation{ActorId{200002},AnimationId{"Alright_Start"},Duration{1}},
PlayFacial{ActorId{200002},FacialId{"Unhappy02"}}
},
PARA{
PlayAnimation{ActorId{200002},AnimationId{"Alright_End"}},
PlayFacial{ActorId{200002},FacialId{"None"}}
}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Oh, it's just a Wishen! Don't sneak up on me like that! You nearly scared me to death... But fine. Since you apologised properly, the great Demon King will forgive you."
        },
        [51140008] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "多谢二位大人不计小人过。在下拦路却是另有隐情，实不相瞒，在下有一要事……",
          DialogueId = 51140008,
          GUID = "80060D90",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 701074,
          Subtitle = "My thanks to you both for being so understanding. I stopped you because there's something I truly need your..."
        },
        [51140009] = {
          Content = "（敏锐察觉到一丝不对劲，脚步偷偷向后挪了挪。）",
          DialogueId = 51140009,
          GUID = "80060DBA",
          ImprPlusId = 1208,
          Subtitle = "(Sensing something off, you quietly edge a step back.)"
        },
        [51140010] = {
          Content = "要我跑腿是吧？打扰了这就走！",
          DialogueId = 51140010,
          GUID = "80060DE4",
          ImprPlusId = 1206,
          Subtitle = "Another errand, is it? Right then — I'm off!"
        },
        [51140011] = {
          Camera = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "是委托的气息！小仆从！准备——诶？你怎么一副要逃跑的样子？！",
          DialogueId = 51140011,
          GUID = "80060E0E",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Shock02_Start"},Duration{1}},
PlayAnimation{ActorId{200002},AnimationId{"Angry01_Start"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "That's the smell of a new quest! Brace yourself, little minion... Huh? Why are you backing off like you're about to leg it!?"
        },
        [51140012] = {
          Content = "（你正想离开，却觉得好像有什么轻飘飘的东西靠近了你，然后……）",
          DialogueId = 51140012,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "80060E38",
          IsBlack = 1,
          LookAt = {
            [1] = "200002:n(701074);100001:n(100001)"
          },
          SpeakNpcId = 0,
          Subtitle = "(You turn to leave when something weightless slips in beside you.)"
        },
        [51140013] = {
          Content = "（尾生蹦到了你的脚边。）",
          DialogueId = 51140013,
          GUID = "80060E62",
          IsBlack = 1,
          SpeakNpcId = 0,
          Subtitle = "(Weisheng's pale form settles quietly at your feet.)"
        },
        [51140014] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "在下只希望二位能<H>帮我寻找爱妻闲书下落</>，若是你不帮我，我就……我就一直跟着你，直到你答应为止！",
          DialogueId = 51140014,
          GUID = "80060E8C",
          SpeakNpcId = 701074,
          Subtitle = "I only wish for your help in finding my wife, Xianshu. If you refuse, then I... I shall simply stay with you. I won't leave until you agree!",
          TalkActionId = {
            [1] = "100001:Shock02_End"
          }
        },
        [51140015] = {
          Camera = "-194.939453,-70.49707,155.490723,0.000079,-19.495415,-7.838241,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "你——你这家伙耍赖！",
          DialogueId = 51140015,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "80060EB6",
          LookAt = {
            [1] = "200002:n(200002)",
            [2] = "100001:n(100001)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Hey! That's blackmail!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          }
        },
        [51140016] = {
          Camera = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
          Content = "他们都看不到听不到我，你们是第一个回应我说话的。我晓得你们比旁人特殊，只有你们才能帮我！",
          DialogueId = 51140016,
          GUID = "80060EE0",
          SpeakNpcId = 701074,
          Subtitle = "No one else can see me... nor hear me. In all this time, you're the first to ever answer me. You must have some special gift. Only you can help!",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          }
        },
        [51140017] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "……你说说看吧。",
          DialogueId = 51140017,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "80060F0A",
          LookAt = {
            [1] = "100001:n(701074)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...All right, let's hear it.",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51140018] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "真……真的吗？你，你愿意帮我找我妻子了？",
          DialogueId = 51140018,
          GUID = "80060F34",
          SpeakNpcId = 701074,
          Subtitle = "R—Really? You... you'll help me? You'd truly help me find her?"
        }
      }
    end
  },
  {
    MinKey = 51140019,
    MaxKey = 51151107,
    Loader = function()
      return {
        [51140019] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "好，好的！事情是这样的。我生前住蒹葭浦附近，靠做些小买卖维持生计，虽没赚到什么大钱，但日子过得倒也舒坦。",
          DialogueId = 51140019,
          GUID = "80060F5E",
          SpeakNpcId = 701074,
          Subtitle = "O—Okay! Right... then let me tell you what happened. When I was alive, I lived near Reedshore and ran a small stall selling odds and ends. I never earned much, but our days were steady enough."
        },
        [51140020] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "本以为一生就这样平平淡淡过去了，直到我认识了爱妻闲书，我与她情投意合，很快便成了婚，婚后更是如胶似漆，伉俪情深……",
          DialogueId = 51140020,
          GUID = "80060F88",
          SpeakNpcId = 701074,
          Subtitle = "I thought life would stay that way... until I met Xianshu. We suited each other so well that we soon married, and from then on we were inseparable. We cared for each other deeply and—"
        },
        [51140021] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "说重点。",
          DialogueId = 51140021,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "80060FB2",
          SpeakNpcId = 100001,
          Subtitle = "...Let's get to the important part.",
          TalkActionId = {
            [1] = "100001:ConfidentLRToExplainL_Start"
          }
        },
        [51140022] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "是是！只可惜天有不测风云，闲书不知为何得了一种怪病，痛苦异常。我便去求助枯荣阁里的药师为其治疗，药师为我开了些药剂。",
          DialogueId = 51140022,
          FinalCamera = "25.034668,-51.429688,210.820923,0.000096,-10.894411,176.561234,35.000008,100000.0,false,DoNotOverride,7.0",
          GUID = "80060FDC",
          SpeakNpcId = 701074,
          Subtitle = "R—Right! But fate can be unkind. Xianshu fell ill quite suddenly, with a strange sickness that caused her terrible pain. I went to the apothecary at the Hall of Ephemerality for help, and she prepared the herbs for Xianshu's medicine.",
          ToFinalCameraBlendTime = 5
        },
        [51140023] = {
          Content = "那日后，我日日为她煎药试药，悉心照料，依旧不见好转，我便想着将她带去皓京问问有没有更好的药师治疗，谁知道……她一直不同意。",
          DialogueId = 51140023,
          GUID = "80061006",
          SpeakNpcId = 701074,
          Subtitle = "From then on, I brewed her medicine day after day, and tasted each dose myself before giving it to her. I cared for her as best I could... but even with the medicine, she did not improve. I wished to take her to Haojing, to see if we might find someone more skilled who could help her... but she would not agree.",
          TalkActionId = {
            [1] = "100001:ConfidentLRToExplainL_End"
          }
        },
        [51140024] = {
          Content = "她失踪那日，我终于耐不住性子，第一次凶了她……我直至今日都在后悔。",
          DialogueId = 51140024,
          GUID = "80061030",
          SpeakNpcId = 701074,
          Subtitle = "And on the day she disappeared... I lost my patience and spoke sharply to her, for the first time in my life. I have regretted it ever since."
        },
        [51140025] = {
          Camera = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
          Content = "我那天好说歹说，她终于点头愿意随我去看病。我便去铺子上拜托伙计看摊，和闲书约好晚上直接在码头见面，不耽误出发时间。",
          DialogueId = 51140025,
          GUID = "8006105A",
          SpeakNpcId = 701074,
          Subtitle = "That day, I begged her again and again, and at last she agreed to go with me to Haojing for treatment. Before leaving for my stall to ask a friend to watch it for me, we agreed to meet at the pier that evening so we would not delay our departure."
        },
        [51140026] = {
          Camera = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
          Content = "可谁知道……我在码头等到天亮，却根本没等到她！",
          DialogueId = 51140026,
          GUID = "80061084",
          SpeakNpcId = 701074,
          Subtitle = "But... I never imagined... I waited all the way until dawn... but she never came!"
        },
        [51140027] = {
          Camera = "-175.286621,11.260742,161.297852,0.000068,-19.495415,-35.038132,35.000008,100000.0,false,DoNotOverride,7.0",
          Content = "等一下等一下？她会不会是因为生病倒在家里了？",
          DialogueId = 51140027,
          GUID = "800610AE",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Wait! Maybe she was just too sick and passed out at home?",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End",
            [2] = "200002:Think_Start"
          }
        },
        [51140028] = {
          Camera = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
          Content = "家中自然是看过了，但却没有找到一丝闲书的痕迹，她好像就这样，突然轻轻地挥一挥袖，从我的世界里消失了……",
          DialogueId = 51140028,
          GUID = "800610D8",
          SpeakNpcId = 701074,
          Subtitle = "Of course I went home to look for her... but there was not a single trace of her. She had simply vanished from my life, as if she had never been there at all."
        },
        [51140029] = {
          Camera = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
          Content = "我怕她是否会有一日归来，便一直在码头等她。那日下了很大的雨，浮星埠水位上涨，我却担心她要是此时回来找不到我，于是我便执意不走。",
          DialogueId = 51140029,
          GUID = "80061102",
          SpeakNpcId = 701074,
          Subtitle = "I stayed at the pier all the same. I thought she might come back one day, and I wanted to be there if she did. That day, the rain just kept coming, and the waters at Starwharf rose higher and higher, but I still would not leave. I was afraid that if she came back and I wasn't there, I'd lose her again."
        },
        [51140030] = {
          Camera = "-205.567871,-119.201172,110.475708,0.000172,0.0,5.771363,35.000015,187.02475,false,Manual,7.0",
          Content = "为什么不去找地方避雨呢？你就傻傻等着吗？",
          DialogueId = 51140030,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "8006112C",
          LookAt = {
            [1] = "200002:n(701074)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Why didn't you get out of the rain? Did you really just stand there the whole time?",
          TalkActionId = {
            [1] = "200002:Think_End"
          }
        },
        [51140031] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "那日洪水暴涨，我只能抓住一切随手能见着的东西……人力终不能胜天，我被水卷走，死不见全尸，幸而化作无由之身，游荡于此。",
          DialogueId = 51140031,
          GUID = "80061156",
          SpeakNpcId = 701074,
          Subtitle = "All I could do was cling to whatever I could reach... but no one can stand against a flood like that. I was swept away, and my body was never found. But by some twist of fate, I became a Wishen after I died, left to wander here."
        },
        [51140032] = {
          Camera = "-272.66748,181.339844,236.877319,0.000052,-19.999928,-51.83622,27.780128,100000.0,false,DoNotOverride,7.0",
          Content = "你……你……诶……真是个笨蛋啊！",
          DialogueId = 51140032,
          FacialId = {
            [1] = "200002:Sad03"
          },
          GUID = "80061180",
          LookAt = {
            [1] = "200002:n(701074)",
            [2] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "That's so... Ugh, you idiot!",
          TalkActionId = {
            [1] = "200002:Sigh_Start"
          }
        },
        [51140033] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "鸿毛之命，此时不必再提及，我只求二位帮忙，去扶氏<H>枯荣阁</>那里帮我问问闲书的踪迹。",
          DialogueId = 51140033,
          GUID = "800611AA",
          SpeakNpcId = 701074,
          Subtitle = "My life was never worth much in the first place. There is no need to feel sorry for me. All I ask is that you go to the Hall of Ephemerality — clinic run by the House of Zhuyou — and ask after Xianshu for me."
        },
        [51140034] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "我妻子那病需要以药吊命，要是她回来了，想必第一时间一定会去找那里的药师开药的。",
          DialogueId = 51140034,
          GUID = "800611D4",
          SpeakNpcId = 701074,
          Subtitle = "Her illness needs steady treatment, and she cannot miss her medicine. If she has returned, she would likely go to the apothecary there to fetch more of it."
        },
        [51140035] = {
          Camera = "-174.360352,-43.571289,181.889648,0.000123,-15.293852,16.366138,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "知道了，我会帮你去问问，但结果如何我不能保证。",
          DialogueId = 51140035,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800611FE",
          LookAt = {
            [1] = "100001:n(701074)"
          },
          SpeakNpcId = 100001,
          Subtitle = "All right. I'll ask for you, but I can't promise anything.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51140036] = {
          Camera = "-25.474121,-45.555664,158.86438,0.000091,5.70566,175.16095,35.000008,100000.0,false,DoNotOverride,7.0",
          Content = "大恩大德，尾生来世必报！",
          DialogueId = 51140036,
          GUID = "80061228",
          SpeakNpcId = 701074,
          Subtitle = "I will never forget this. And if there is a next life... I will repay your kindness!",
          TalkActionId = {
            [1] = "701074:Wuyou_Disappear"
          }
        },
        [51140037] = {
          Camera = "-287.652344,948.660156,170.522461,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "（扶疏正痴痴望着一个方向发呆，连鱼龙也显得垂头丧气。）",
          DialogueId = 51140037,
          FinalCamera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          GUID = "80061252",
          Scripts = [[
PARA{
MoveTo{ActorId{100001},MoveSpeed{100},TargetPoint{"Targetpoint_20030901"},Visibility{"Show"}},
MoveTo{ActorId{200002},MoveSpeed{100},TargetPoint{"Targetpoint_20030902"},Visibility{"Show"}}
}]],
          SpeakNpcId = 0,
          Subtitle = "(As you enter the Hall of Ephemerality, you find Fushu standing still, lost in thought. Even her Fish-loong droops listlessly at her side.)",
          TalkActionId = {
            [1] = "701075:Think_Start"
          },
          ToFinalCameraBlendTime = 4
        },
        [51140038] = {
          Content = "是有什么心事吗？",
          DialogueId = 51140038,
          GUID = "8006127C",
          ImprPlusId = 1209,
          Subtitle = "Is something on your mind?"
        },
        [51140039] = {
          Content = "（等她发现自己。）",
          DialogueId = 51140039,
          GUID = "800612A6",
          ImprPlusId = 1207,
          Subtitle = "(Wait quietly for her to notice you.)"
        },
        [51140040] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "唔，{nickname}，是你……怎么得空来了枯荣阁，温习时想起一些往事，不免失神，让你见笑了。",
          DialogueId = 51140040,
          GUID = "800612D0",
          LookAt = {
            [1] = "701075:n(100001)"
          },
          SpeakNpcId = 701075,
          Subtitle = "Ah, ... You are here. What brings you to the Hall of Ephemerality today? I was reading some old medical texts, and a few memories surfaced before I realised it. It seems my thoughts wandered for a moment.",
          TalkActionId = {
            [1] = "701075:Think_End"
          },
          TurnTo = {
            [1] = "701075:n(100001)"
          }
        },
        [51140041] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "唔，{nickname}，是你……怎么得空来了枯荣阁，温书入迷一时失神，居然没注意到你进来。",
          DialogueId = 51140041,
          GUID = "800612FA",
          LookAt = {
            [1] = "701075:n(100001)"
          },
          SpeakNpcId = 701075,
          Subtitle = "Ah, ... I did not realise you had arrived. I was too absorbed in my texts and failed to notice you come in.",
          TalkActionId = {
            [1] = "701075:Think_End"
          },
          TurnTo = {
            [1] = "701075:n(100001)"
          }
        },
        [51140042] = {
          Camera = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
          Content = "我都要把这里的诊籍都翻遍了，不是发烧感冒就是胃痛腹泻，怎么也和尾生说的那种情况对不上呀。",
          DialogueId = 51140042,
          GUID = "80061324",
          SpeakNpcId = 200002,
          Subtitle = "I've gone through almost every record in here! It's all colds, fevers, and tummy trouble — nothing even close to the kind of patient Weisheng mentioned!",
          TalkActionId = {
            [1] = "200002:Alright_Start"
          }
        },
        [51140043] = {
          Camera = "147.988281,-372.753906,263.493164,0.000021,-23.151232,113.072533,76.142418,493.532471,false,Manual,3.0",
          Content = "扶疏扶疏，我们这次来是有一件奇怪的事情要问你呢！",
          DialogueId = 51140043,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "8006134E",
          SpeakNpcId = 200002,
          Subtitle = "Miss Fushu! We've got something super strange to ask you!",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          TurnTo = {
            [1] = "100001:n(701075)",
            [2] = "701075:n(200002)"
          }
        },
        [51140044] = {
          Camera = "-74.871094,-49.457031,176.993164,0.000086,-14.999942,-17.730551,35.000015,130.112747,false,Manual,7.0",
          Content = "是身体不适还是另有心疾，能帮到你的地方，扶疏定然鼎力相助。",
          DialogueId = 51140044,
          FacialId = {
            [1] = "701075:Smile01"
          },
          GUID = "80061378",
          SpeakNpcId = 701075,
          Subtitle = "Is it an ailment of the body, or a trouble of the heart? Whatever it may be, if it lies within my ability, I will do all I can to help."
        },
        [51140045] = {
          Content = "（你向扶疏讲述了一位无由生在寻找生病妻子的事。）",
          DialogueId = 51140045,
          GUID = "800613A2",
          IsBlack = 1,
          SpeakNpcId = 0,
          Subtitle = "(You tell Fushu about the Wishen searching for his sick wife.)",
          TurnTo = {
            [1] = "701075:n(100001)"
          }
        },
        [51140046] = {
          Camera = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
          Content = "大抵是家姐生前收治过的病人。据记载，烟津渡上次洪灾致人溺亡已是九十余年前……",
          DialogueId = 51140046,
          GUID = "800613CC",
          SpeakNpcId = 701075,
          Subtitle = "Most likely, he was a patient my elder sister tended to in her time. According to the records kept here, the last great flood at Mistwharf to claim lives occurred more than ninety years ago...",
          TalkActionId = {
            [1] = "701075:Explain01_Start",
            [2] = "200002:Excited01_End"
          }
        },
        [51140047] = {
          Camera = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
          Content = "那时家姐年纪尚轻，尚未自立门户，还在枯荣阁坐诊。",
          DialogueId = 51140047,
          GUID = "800613F6",
          SpeakNpcId = 701075,
          Subtitle = "In those days, my sister was still young — she had not begun practising on her own. She assisted patients here, within the Hall of Ephemerality.",
          TalkActionId = {
            [1] = "701075:Explain01_End"
          }
        },
        [51140048] = {
          Camera = "171.115234,-119.117188,100.751953,0.000108,-4.999999,154.070587,35.000008,300.780701,false,Manual,5.20548",
          Content = "那个尾生竟然已经死了九十多年了吗！",
          DialogueId = 51140048,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "80061420",
          SpeakNpcId = 200002,
          Subtitle = "Wait... so Weisheng's been dead for over ninety years!?",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          }
        },
        [51140049] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "没错，他的妻子如今还活着的希望已是渺茫。",
          DialogueId = 51140049,
          FacialId = {
            [1] = "701075:Think01"
          },
          GUID = "8006144A",
          SpeakNpcId = 701075,
          Subtitle = "Indeed. The hope of his wife still living is now exceedingly faint.",
          TalkActionId = {
            [1] = "701075:Think_Start"
          }
        },
        [51140050] = {
          Camera = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "但如此痴情之人，帮他寻得当年妻子下落，权当圆他一个念想，让他得以了却执念，回归往生也好。",
          DialogueId = 51140050,
          GUID = "80061474",
          SpeakNpcId = 701075,
          Subtitle = "Yet for one who held such steadfast devotion, learning what became of her may give him the answer he has sought for decades... and perhaps allow his spirit, at long last, to find release.",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          }
        },
        [51140051] = {
          Camera = "-113.632812,-83.152344,198.851562,0.00007,-17.949545,-0.526916,35.000011,645.22876,false,DoNotOverride,7.0",
          Content = "家姐历年行医都有诊籍留档，{nickname}，我随你去阁中找找。",
          DialogueId = 51140051,
          FacialId = {
            [1] = "701075:None"
          },
          GUID = "8006149E",
          SpeakNpcId = 701075,
          Subtitle = "My sister kept meticulous case records throughout her years of practice. Come, . Let us search the archives together.",
          TalkActionId = {
            [1] = "701075:Think_End"
          }
        },
        [51140052] = {
          Camera = "95.519531,110.679688,109.566406,0.000037,0.0,-126.112823,11.880002,248.943176,false,Manual,2.8",
          Content = "找到诊籍了吗？",
          DialogueId = 51140052,
          GUID = "800614C8",
          Scripts = [[
SEQ{ MoveTo{ActorId{701075},MoveSpeed{150},TargetPoint{"Targetpoint_20030907"}}, TurnTo{TurnToDescription{"701075:n(100001)"}}
}]],
          SpeakNpcId = 701075,
          Subtitle = "Have you found the record you seek?",
          TalkActionId = {
            [1] = "200002:Alright_End"
          }
        },
        [51140053] = {
          Camera = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
          Content = "没有，似乎没有对得上的，只有这一篇有些奇怪。",
          DialogueId = 51140053,
          GUID = "800614F2",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "No. None of them really line up... except this one. Something about it feels off.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51140054] = {
          Content = "（你将诊籍递给扶疏，她仔细看了一会儿。）",
          DialogueId = 51140054,
          GUID = "8006151C",
          IsBlack = 1,
          SpeakNpcId = 0,
          Subtitle = "(You hand the case record to Fushu. She reads it through in quiet concentration.)"
        },
        [51140055] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "咦……这里面有个人……我曾在姐姐的日记里见过……",
          DialogueId = 51140055,
          GUID = "80061546",
          SpeakNpcId = 701075,
          Subtitle = "Mm... This individual. I recall seeing him mentioned in my sister's diary.",
          TalkActionId = {
            [1] = "701075:Think_Start"
          }
        },
        [51140056] = {
          Camera = "120.662109,32.841797,142.3125,0.000078,-19.999907,-159.908264,22.322252,236.840927,false,Manual,7.0",
          Content = "日记？你姐姐还写过日记呀？",
          DialogueId = 51140056,
          GUID = "80061570",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "701075:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "A diary? Your sister actually kept a diary?",
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "701075:Think_End"
          }
        },
        [51140057] = {
          Camera = "-93.105469,39.958984,123.023438,0.000084,6.0,-18.908363,35.000008,178.587616,false,Manual,7.0",
          Content = "嗯，姐姐怕我醒了后她不在，我对她不与我重叠的生活毫无了解，便将自己的经历以日记形式记录了下来。",
          DialogueId = 51140057,
          GUID = "8006159A",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "701075:n(200002)"
          },
          SpeakNpcId = 701075,
          Subtitle = "Yes. She feared that, should I one day awaken to find her gone, I would know nothing of the life she had lived beyond our time together. So she recorded her days in the form of a diary.",
          TalkActionId = {
            [1] = "701075:Explain02_Start",
            [2] = "200002:Talk01_End"
          }
        },
        [51140058] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "……不好意思，又提到你的伤心事了。",
          DialogueId = 51140058,
          GUID = "800615C4",
          LookAt = {
            [1] = "701075:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Sorry. I didn't mean to bring up sad memories.",
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "701075:Explain02_End"
          }
        },
        [51140059] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "并无感伤，姐姐想必也是不愿看到我伤怀才如此行事。",
          DialogueId = 51140059,
          GUID = "800615EE",
          SpeakNpcId = 701075,
          Subtitle = "It's all right. I believe she wrote them so that I would not need to grieve for her.",
          TalkActionId = {
            [1] = "701075:Disagree"
          }
        },
        [51140060] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "姐姐曾在年轻时的日记里提过一名患者，其妻在大疫中不幸殒命，自此患上心病，终日幻想其妻尚存于世，与那个不存在的人对话。",
          DialogueId = 51140060,
          GUID = "80061618",
          SpeakNpcId = 701075,
          Subtitle = "In her youth, she wrote of a patient whose wife had perished in the Great Plague. From then on, he suffered an ailment of the heart, spending his days believing she still walked among the living, speaking to one who was no longer in this world.",
          TalkActionId = {
            [1] = "701075:Talk03_Start"
          }
        },
        [51140061] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "姐姐写道，这让她照见了自己的影子，如同姐姐与沉睡中的我对话一样，有趣却又愚痴。",
          DialogueId = 51140061,
          GUID = "80061642",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 701075,
          Subtitle = "She wrote that he was like a mirror held up to her — just as she would speak to me in my long sleep. A thing both curious and foolish.",
          TalkActionId = {
            [1] = "701075:Talk03ToThink_Start"
          }
        },
        [51140062] = {
          Content = "那位患者拒绝服药，姐姐只得想了个法子，借口要为他的妻子诊病，以试药为由，回回让他带走两副汤药，自己先吃一副。",
          DialogueId = 51140062,
          GUID = "8006166C",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 701075,
          Subtitle = "He refused all medicine, so my sister devised a gentle ruse. She told him she must also tend to his wife and, under the pretext of testing the remedy, had him take two doses each time — one for \"her\", and the other for him to test its effect. She insisted that he drink his dose first.",
          TalkActionId = {
            [1] = "701075:Talk03ToThink_End"
          }
        },
        [51140063] = {
          Camera = "124.955078,118.574219,128.228516,0.000018,-6.242916,-137.315506,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "我想起来了！尾生之前说过，他给自己的妻子试药来着！",
          DialogueId = 51140063,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "80061696",
          SpeakNpcId = 200002,
          Subtitle = "Oh! That's right! Weisheng did say he tested the medicine on himself for his wife!",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          }
        },
        [51140064] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "…………！原来如此，尾生的妻子，我们已经找到了。她就是：",
          DialogueId = 51140064,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "800616C0",
          LookAt = {
            [1] = "100001:n(701075)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...So that's how it is. We've already found Weisheng's \"wife\". She is—",
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "200002:Shock03_End"
          }
        },
        [51140065] = {
          Content = "刘姓女子",
          DialogueId = 51140065,
          GUID = "800616EA",
          ImprPlusId = 1211,
          Subtitle = "The girl surnamed Liu"
        },
        [51140066] = {
          Content = "陈姓女子",
          DialogueId = 51140066,
          GUID = "80061714",
          ImprPlusId = 1211,
          Subtitle = "The woman surnamed Chen"
        },
        [51140067] = {
          Content = "柳姓男子",
          DialogueId = 51140067,
          GUID = "8006173E",
          ImprPlusId = 1211,
          Subtitle = "The man surnamed Liu"
        },
        [51140068] = {
          Content = "早已不存于世",
          DialogueId = 51140068,
          GUID = "80061768",
          ImprPlusId = 1208,
          Subtitle = "Someone who had already passed away at that time"
        },
        [51140069] = {
          Camera = "-130.283203,752.826172,160.511719,0.000086,2.696961,101.435776,11.88,100000.0,false,Manual,2.8",
          Content = "想来，那名真正的患者，应是诊籍里的柳姓男子，也就是<H>柳尾生</>吧？",
          DialogueId = 51140069,
          GUID = "80061792",
          SpeakNpcId = 701075,
          Subtitle = "Mm... The true patient must have been the man surnamed Liu in the record — Liu Weisheng himself.",
          TalkActionId = {
            [1] = "701075:Talk03ToTalkL_Start"
          }
        },
        [51140070] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "拜托你们寻找妻子的那位无由生名叫尾生，应该就是这位柳姓病人死后幻化而成。",
          DialogueId = 51140070,
          GUID = "800617BC",
          SpeakNpcId = 701075,
          Subtitle = "The Wishen who pleaded with you to find his wife bears the same name. He must be what this man became after his passing."
        },
        [51140071] = {
          Camera = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
          Content = "扶疏，你在说什么呀……我都有点糊涂了……",
          DialogueId = 51140071,
          GUID = "800617E6",
          SpeakNpcId = 200002,
          Subtitle = "What are you talking about, Fushu? I'm getting all mixed up...",
          TalkActionId = {
            [1] = "200002:Disagree",
            [2] = "701075:Talk03ToTalkL_End"
          }
        },
        [51140072] = {
          Camera = "-86.828125,129.613281,73.053711,0.000108,9.999997,-87.957306,28.133715,234.328125,false,Manual,1.855292",
          Content = "……我明白了！你姐姐救治的那个病人，不是尾生的妻子，而是尾生自己！他的妻子早就过世了，而他得了心病，一直以为自己的妻子还在身边！",
          DialogueId = 51140072,
          GUID = "80061810",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(701075)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...No, I see it now! The patient your sister treated wasn't Weisheng's wife at all — it was Weisheng himself! His wife had died long before, and he was so heartbroken he kept believing she was still beside him!",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51140073] = {
          Camera = "-642.771484,-71.21875,4.600586,0.000118,7.999989,2.046195,42.955368,234.325912,false,DoNotOverride,7.0",
          Content = "是的……他之所以在暴雨中苦等一夜，直到溺亡都等不来他的妻子，是因为他吃了药，妄想的症状有所减轻，所以反而“看不到”幻想出的妻子了。",
          DialogueId = 51140073,
          GUID = "8006183A",
          SpeakNpcId = 701075,
          Subtitle = "Yes... He waited through that storm the entire night, never once seeing his wife — because the medicine had begun to ease his delusions. The wife he believed remained at his side simply faded from his sight.",
          TalkActionId = {
            [1] = "701075:Talk03_End"
          }
        },
        [51140074] = {
          Camera = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
          Content = "扶疏，这册诊籍里的柳姓男子，他的名字是不是叫<H>柳尾生</>？",
          DialogueId = 51140074,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "80061864",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Fushu, this man in the record... was his full name Liu Weisheng?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51140075] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "不错。他的姓名应该只记在姐姐日记里，你怎知……？",
          DialogueId = 51140075,
          GUID = "8006188E",
          SpeakNpcId = 701075,
          Subtitle = "That is correct. His full name appears only in my sister's diary. How did you come to know this...?"
        },
        [51140076] = {
          Camera = "-86.828125,129.613281,73.053711,0.000108,9.999997,-87.957306,28.133715,234.328125,false,Manual,1.855292",
          Content = "拜托我们寻找妻子的那位无由生名叫尾生，应该就是这位柳姓病人死后幻化而成。",
          DialogueId = 51140076,
          GUID = "800618B8",
          SpeakNpcId = 100001,
          Subtitle = "The Wishen who asked us to find his wife is named Weisheng. He must be what this man became after his death.",
          TalkActionId = {
            [1] = "100001:ConfidentLToExplain_Start"
          }
        },
        [51140077] = {
          Camera = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
          Content = "……我明白了！扶疏的姐姐救治的那个病人，不是尾生的妻子，而是尾生自己！他的妻子早就过世了，而他得了心病，一直以为自己的妻子还在身边！",
          DialogueId = 51140077,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "800618E2",
          SpeakNpcId = 200002,
          Subtitle = "Oh! I get it now! The patient Fushu's sister treated wasn't his wife at all — it was Weisheng himself! His wife had died long before, and he was so heartbroken he kept believing she was still beside him!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          }
        },
        [51140078] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "是的……他之所以在暴雨中苦等一夜，直到溺亡都等不来他的妻子，是因为他吃了药，妄想的症状有所减轻，所以反而“看不到”幻想出的妻子了。",
          DialogueId = 51140078,
          GUID = "8006190C",
          SpeakNpcId = 100001,
          Subtitle = "Right... He waited out there the whole night in the storm and never saw his wife — because the medicine was easing his delusions. He could no longer \"see\" the wife he'd imagined.",
          TalkActionId = {
            [1] = "100001:ConfidentLToExplain_End",
            [2] = "200002:Excited02_End"
          }
        },
        [51140079] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "竟是……此般造化弄人。",
          DialogueId = 51140079,
          GUID = "80061936",
          SpeakNpcId = 701075,
          Subtitle = "*sigh*... Fate does not spare its cruelties.",
          TalkActionId = {
            [1] = "100001:Confident_End"
          }
        },
        [51140080] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "呜……小仆从，我们赶紧回去把消息带给尾生吧。它实在太可怜了，希望它能解脱出来，回到那个什么忘川……",
          DialogueId = 51140080,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "80061960",
          SpeakNpcId = 200002,
          Subtitle = "Aw... Little Minion, let's go back and tell Weisheng. It's sooo sad... I hope he can finally find closure and return to— uh... that place... the River of Forgetting...?",
          TalkActionId = {
            [1] = "200002:Sigh_Start"
          }
        },
        [51140081] = {
          Camera = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
          Content = "恕我冒昧，{nickname}，你打算如何告知那位尾生呢？",
          DialogueId = 51140081,
          FacialId = {
            [1] = "701075:Disappoint01"
          },
          GUID = "8006198A",
          SpeakNpcId = 701075,
          Subtitle = "If I may ask, ... how do you intend to tell Weisheng?",
          TalkActionId = {
            [1] = "701075:Talk02_Start",
            [2] = "200002:Sigh_End"
          }
        },
        [51140082] = {
          Camera = "-80.082031,72.5625,90.84375,0.000107,3.097224,-93.557159,11.88,234.325912,false,Manual,1.855292",
          Content = "扶疏，你似乎有什么建议？",
          DialogueId = 51140082,
          GUID = "800619B4",
          LookAt = {
            [1] = "200002:n(701075)",
            [2] = "100001:n(701075)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Do you have something in mind, Fushu?",
          TalkActionId = {
            [1] = "701075:Talk02_End",
            [2] = "100001：Explain02_Start"
          }
        },
        [51140083] = {
          Camera = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
          Content = "那位无由生，生前便已执念深重，不愿相信眼前事实。倘若如实告知，只怕……对它的执念并无助益。",
          DialogueId = 51140083,
          GUID = "800619DE",
          SpeakNpcId = 701075,
          Subtitle = "That Wishen bore a deep obsession even in life, unable to accept the truth before him. If you were to speak plainly, I fear it would do little to ease that burden...",
          TalkActionId = {
            [1] = "701075:Explain02_Start"
          }
        },
        [51140084] = {
          Camera = "-19.023438,-3.457031,149.845703,0.000083,1.15922,-11.708227,35.000008,85.264961,false,Manual,7.0",
          Content = "如果你愿意听扶疏一言——",
          DialogueId = 51140084,
          GUID = "80061A08",
          SpeakNpcId = 701075,
          Subtitle = "If you would heed a word of mine...",
          TalkActionId = {
            [1] = "100001：Explain02_End"
          }
        },
        [51140085] = {
          Content = "（扶疏在你的耳边低语了几句。）",
          DialogueId = 51140085,
          GUID = "80061A32",
          IsBlack = 1,
          LookAt = {
            [1] = "701075:n(701075)",
            [2] = "200002:n(200002)",
            [3] = "100001:n(100001)"
          },
          SpeakNpcId = 0,
          Subtitle = "(Fushu leans closer and whispers softly at your ear.)"
        },
        [51140086] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "如此，对它来说或许是更好的答案。",
          DialogueId = 51140086,
          FacialId = {
            [1] = "701075:None"
          },
          GUID = "80061A5C",
          SpeakNpcId = 701075,
          Subtitle = "Handled this way... it may be the kinder answer for him.",
          TalkActionId = {
            [1] = "701075:Explain02_End"
          }
        },
        [51140087] = {
          Camera = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
          Content = "谢谢你，扶疏。我们告辞了。",
          DialogueId = 51140087,
          GUID = "80061A86",
          Scripts = [[
PARA{
MoveTo{_delay{2},ActorId{100001},MoveSpeed{150},TargetPoint{"Targetpoint_20030905"}},
MoveTo{_delay{2},ActorId{200002},MoveSpeed{150},TargetPoint{"Targetpoint_20030906"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Thank you, Fushu. We'll take our leave."
        },
        [51140088] = {
          Camera = "112.988281,113.580078,57.077148,0.000138,3.696717,102.451233,35.000008,820.2052,false,Manual,7.0",
          Content = "……斯人已逝，徒留生者徘徊在尘世间，茕茕孑立，形影成双。",
          DialogueId = 51140088,
          GUID = "80061AB0",
          Scripts = "MoveTo{ActorId{701075},MoveSpeed{150},TargetPoint{\"Targetpoint_20030904\"}},",
          SpeakNpcId = 701075,
          Subtitle = "...The departed have long since gone, and the living remain — alone, with only their own shadow for company."
        },
        [51140089] = {
          Camera = "-50.109375,864.226562,147.566406,0.000144,0.0,169.044022,50.171638,134.067627,false,Manual,7.0",
          Content = "消弭执念，说起来容易，但对真正心怀执念的人而言，它真的好沉重……太沉重了……你说是不是？",
          DialogueId = 51140089,
          FacialId = {
            [1] = "701075:Sad01"
          },
          GUID = "80061ADA",
          Scripts = [[
SEQ{ TurnTo{TurnToDescription{"701075:p(-20)"}}, LookAt{LookAtDescription{"701075:n(100001)"}}
}]],
          SpeakNpcId = 701075,
          Subtitle = "To loosen an obsession is simple to speak of... but for one who truly bears it, the weight is unbearable... far too heavy to lay down. Would you not say so..."
        },
        [51140090] = {
          Camera = "-50.109375,864.226562,147.566406,0.000144,0.0,169.044022,50.171638,134.067627,false,Manual,7.0",
          Content = "——姐姐。",
          DialogueId = 51140090,
          GUID = "80061B04",
          LookAt = {
            [1] = "701075:n(701075)"
          },
          SpeakNpcId = 701075,
          Subtitle = "...Sister?",
          TalkActionId = {
            [1] = "701075:Sad02_Start"
          }
        },
        [51150001] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "你们回来了！怎么样，有问到我妻子的消息吗？",
          DialogueId = 51150001,
          GUID = "800C750A",
          SpeakNpcId = 701074,
          Subtitle = "You're back! Did you learn anything about my wife?",
          TalkActionId = {
            [1] = "701074:Wuyou_Born"
          }
        },
        [51150002] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "（按照扶疏的建议，你开始向尾生娓娓道来妻子的下落……）",
          DialogueId = 51150002,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800C7534",
          Subtitle = "(As Fushu advised, you begin speaking gently of what became of her...)",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51150003] = {
          Camera = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
          Content = "什么？你说闲书已经不在人世了？因为……我已经死了九十多年？",
          DialogueId = 51150003,
          GUID = "800C755E",
          SpeakNpcId = 701074,
          Subtitle = "What...? You mean Xianshu... she is no longer in this world? Because... I have been dead for more than ninety years...?"
        },
        [51150004] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "是的。",
          DialogueId = 51150004,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "800C7588",
          SpeakNpcId = 100001,
          Subtitle = "That's right.",
          TalkActionId = {
            [1] = "100001：Explain01_End"
          }
        },
        [51150005] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "……原来……在这虞泉……我竟已浑浑噩噩度过如此之久……",
          DialogueId = 51150005,
          GUID = "800C75B2",
          SpeakNpcId = 701074,
          Subtitle = "Then I've been wandering here all this time... the Spring of Yu... all these long, empty years..."
        },
        [51150006] = {
          Camera = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "那闲书呢？她去了哪儿？她……这些年来，她好吗？",
          DialogueId = 51150006,
          GUID = "800C75DC",
          SpeakNpcId = 701074,
          Subtitle = "And Xianshu...? Where did she go? Has she... has she been well all these years...?"
        },
        [51150007] = {
          Camera = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "(你与白对视了一眼）",
          DialogueId = 51150007,
          GUID = "800C7606",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 0,
          Subtitle = "(You and Snow exchange a glance.)"
        },
        [51150008] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "闲书抱病多年，一直得你照料，但她不愿成为你的负累。所以当年，她选择了离家出走。",
          DialogueId = 51150008,
          GUID = "800C7630",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(200002)"
          },
          SpeakNpcId = 100001,
          Subtitle = "When she was ill, you cared for her as best you could. But after so many years of sickness, she feared she'd only burden you further. So... she chose to leave home.",
          TalkActionId = {
            [1] = "100001:ExplainTwo_Start"
          }
        },
        [51150009] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "但是……机缘巧合之下，她遇到了一位在烟津渡旅行的天才药师。在那位天才药师的悉心治疗下，闲书得以痊愈。",
          DialogueId = 51150009,
          GUID = "800C765A",
          LookAt = {
            [1] = "100001:n(701074)",
            [2] = "200002:n(701074)"
          },
          SpeakNpcId = 100001,
          Subtitle = "But by a stroke of good fortune, she crossed paths with a travelling apothecary — one of remarkable skill. Under her care, she slowly recovered."
        },
        [51150010] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "可当她回到家去找你的时候，却听到了你已经死在洪水里的消息。",
          DialogueId = 51150010,
          FacialId = {
            [1] = "100001:Sad03"
          },
          GUID = "800C7684",
          SpeakNpcId = 100001,
          Subtitle = "And when she finally returned home to find you, she learned instead that the flood had taken your life.",
          TalkActionId = {
            [1] = "100001:ExplainTwo_End"
          }
        },
        [51150011] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "竟是……如此……",
          DialogueId = 51150011,
          GUID = "800C76AE",
          SpeakNpcId = 701074,
          Subtitle = "All this time... I never knew..."
        },
        [51150012] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "但，她并没有让自己就这样一辈子浑浑噩噩下去。为你痛哭一场后，她拜那位药师为师，开始学习药学。",
          DialogueId = 51150012,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "800C76D8",
          SpeakNpcId = 100001,
          Subtitle = "She grieved for you with all her heart... but she did not lose herself to sorrow forever. She begged that apothecary to take her in as a disciple, and began learning the art of medicine.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51150013] = {
          Camera = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
          Content = "她希望可以尽绵薄之力，为那些被病痛折磨的人缓解痛苦。她不希望她与你的悲剧，再在其他人身上上演。",
          DialogueId = 51150013,
          GUID = "800C7702",
          SpeakNpcId = 100001,
          Subtitle = "She wished to help those in pain, so that what happened between you and her would never happen to anyone else."
        },
        [51150014] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "她是一个勤奋的学生，后来，她也成为了老师，她也有了自己的学生。再后来，学生又有了学生……",
          DialogueId = 51150014,
          GUID = "800C772C",
          SpeakNpcId = 100001,
          Subtitle = "She studied with great devotion. And in time, she became an apothecary in her own right — and later took on students of her own. And those students, in time, taught students of their own as well.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51150015] = {
          Camera = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
          Content = "他们一起，救治了很多病人。学生们都很爱戴她，就像她的儿女一样……一直到她九十岁高龄辞世。",
          DialogueId = 51150015,
          GUID = "800C7756",
          SpeakNpcId = 100001,
          Subtitle = "Together, they healed countless lives. Her students cherished her as though she were family... right up until she passed peacefully in her nineties."
        },
        [51150016] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "……太好了，太好了……",
          DialogueId = 51150016,
          GUID = "800C7780",
          SpeakNpcId = 701074,
          Subtitle = "Good... That's... that's so good..."
        },
        [51150017] = {
          Camera = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
          Content = "她的病好了……她幸福地度过一生……我便放心了……",
          DialogueId = 51150017,
          GUID = "800C77AA",
          SpeakNpcId = 701074,
          Subtitle = "Her illness healed... she lived well... a full, long life... I can rest easy at last...",
          TalkActionId = {
            [1] = "701074:Wuyou_Agree"
          }
        },
        [51150018] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "一切都……过去了……我也可以安心地……",
          DialogueId = 51150018,
          GUID = "800C77D4",
          SpeakNpcId = 701074,
          Subtitle = "Everything I held onto... I can finally let it rest... and now, I can leave without regret..."
        },
        [51150019] = {
          Camera = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
          Content = "谢谢你们，二位，真的……谢谢……",
          DialogueId = 51150019,
          GUID = "800C77FE",
          SpeakNpcId = 701074,
          Subtitle = "Thank you... both of you... truly... thank... you...",
          TalkActionId = {
            [1] = "701074:Wuyou_Disappear"
          }
        },
        [51150020] = {
          Content = "尾生的身体逐渐透明，直到逐渐消失在你面前，在完全消散的瞬间，你看到什么晶莹剔透的东西从它体内坠落。",
          DialogueId = 51150020,
          GUID = "800C7828",
          SpeakNpcId = 0,
          Subtitle = "(His voice fades to a whisper as his form grows translucent — until at last he melts into the quiet air. And in the moment he disappears, something glimmering slips from within him and falls gently to the ground.)"
        },
        [51150021] = {
          Content = "无由生也会流泪吗？还是说只是一束偶然折射过来的阳光……",
          DialogueId = 51150021,
          GUID = "800C7852",
          SpeakNpcId = 0,
          Subtitle = "(Do Wishen cry...? Or was it only a glimmer of sunlight?)"
        },
        [51151001] = {
          Camera = "-619.021484,275.37793,18.173828,0.000051,1.999995,-13.887951,33.047028,100000.0,false,DoNotOverride,2.8",
          Content = "是说百年春角落那间仓库吗？那里不是早就租给天岚先生做供货仓库了吗？为何现在过来提起？",
          DialogueId = 51151001,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "700371:Cin_Nervous"
          },
          FinalCamera = "-542.628906,256.49707,21.111328,0.000051,2.499999,-13.887944,33.047028,100000.0,false,DoNotOverride,2.8",
          GUID = "800D191A",
          LookAt = {
            [1] = "100001:n(700370)"
          },
          NextDialogue = 51151002,
          SpeakNpcId = 700370,
          Subtitle = "You mean that warehouse over in the corner of EverSpring? Mr Tianlan rented it as a storehouse some time ago. Why bring it up now?",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700370:Talk03_Start"
          },
          ToFinalCameraBlendTime = 25
        },
        [51151002] = {
          Content = "天岚先生自从上次跟船出海后迟迟未归，但他之前收购的一批香料都放在仓库里，已经放了好几个月。",
          DialogueId = 51151002,
          GUID = "800D1944",
          NextDialogue = 51151003,
          SpeakNpcId = 700371,
          Subtitle = "Mr Tianlan hasn't returned since he last set sail. The batch of incense he bought beforehand has been sitting in that warehouse for months.",
          TalkActionId = {
            [1] = "700371:Explain02_Start"
          }
        },
        [51151003] = {
          Content = "你这话说的我都有些迷糊了。放着便放着呗，那间仓库的租金一直续到明年呢……",
          DialogueId = 51151003,
          GUID = "800D196E",
          NextDialogue = 51151004,
          SpeakNpcId = 700370,
          Subtitle = "I don't quite follow. If the goods are simply sitting there, then let them sit — the rent's paid through next year. What's the harm?",
          TalkActionId = {
            [1] = "700370:Talk03_End"
          }
        },
        [51151004] = {
          Content = "不是啊，望春姐，是最近百年春都在说，那仓库里闹鬼！",
          DialogueId = 51151004,
          GUID = "800D1998",
          NextDialogue = 51151005,
          SpeakNpcId = 700371,
          Subtitle = "That's not the issue, Miss Wangchun. Everyone in EverSpring's saying the place is haunted!"
        },
        [51151005] = {
          Content = "什……什么？！",
          DialogueId = 51151005,
          FacialId = {
            [1] = "700370:Cin_Angry01"
          },
          GUID = "800D19C2",
          NextDialogue = 51151006,
          SpeakNpcId = 700370,
          Subtitle = "Wh—What!?",
          TalkActionId = {
            [1] = "700370:Shock03_Start",
            [2] = "700371:Explain02_End"
          }
        },
        [51151006] = {
          Content = "是这样，之前有一批点货人想进去检查库存，结果刚进去就晕头转脑的，人没看到货就绕出门了。",
          DialogueId = 51151006,
          GUID = "800D19EC",
          NextDialogue = 51151007,
          SpeakNpcId = 700371,
          Subtitle = "Some clerks went in to check the stock, but the moment they stepped inside, they felt dizzy. Before they knew it, they'd already wandered back out without ever seeing the goods.",
          TalkActionId = {
            [1] = "700371:Explain02_Start"
          }
        },
        [51151007] = {
          Content = "后来有人不信邪，去了好些个胆子大的，都被这样恭恭敬敬“请”了出来。",
          DialogueId = 51151007,
          GUID = "800D1A16",
          NextDialogue = 51151008,
          SpeakNpcId = 700371,
          Subtitle = "Others still didn't believe it, so they sent in a few bolder hands — only for every one of them to be gently guided back outside, as though by unseen forces.",
          TalkActionId = {
            [1] = "700370:Shock03_End"
          }
        },
        [51151008] = {
          Content = "如此说来，虽然未出现伤人事件，但也确实是个麻烦事，我知晓了，抽空我会派人去看看的。",
          DialogueId = 51151008,
          FacialId = {
            [1] = "700370:Cin_Idle"
          },
          GUID = "800D1A40",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 700370,
          Subtitle = "I see. No one's been harmed, but it's trouble nonetheless. Very well — I'll arrange for someone to inspect it as soon as I can.",
          TalkActionId = {
            [1] = "100001:Talk03ToThink_Start",
            [2] = "700370:Explain01_Start"
          }
        },
        [51151009] = {
          Content = "小仆从，你有没有觉得这间房子有些诡异……",
          DialogueId = 51151009,
          GUID = "800D1A6A",
          NextDialogue = 51151010,
          SpeakNpcId = 200002,
          Subtitle = "Hey, Little Minion... doesn't this place feel kinda weird to you?"
        },
        [51151010] = {
          Content = "没有，是你想多了吧。",
          DialogueId = 51151010,
          GUID = "800D1A94",
          NextDialogue = 51151011,
          SpeakNpcId = 100001,
          Subtitle = "Not really. You're probably just imagining things."
        },
        [51151011] = {
          Content = "是吗？可我总觉得这里的温度要比百年春别的地方冷一些，还能听到……一些奇怪的声音……",
          DialogueId = 51151011,
          GUID = "800D1ABE",
          NextDialogue = 51151012,
          SpeakNpcId = 200002,
          Subtitle = "You think so? But it's definitely colder here than the rest of EverSpring... and I keep hearing these strange little noises..."
        },
        [51151012] = {
          Content = "如果你好奇的话，白天人来人往不太方便，我们晚上再来看看吧。",
          DialogueId = 51151012,
          GUID = "800D1AE8",
          SpeakNpcId = 100001,
          Subtitle = "If you're that curious, we can come back tonight. Too many people around to poke around properly right now."
        },
        [51151013] = {
          Camera = "-210.691406,554.429688,229.848145,0.000044,-12.799794,-74.596756,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "刚进那仓库没走几步路，我寻思那货箱怎么如此眼熟，就顺着墙壁摸着走，结果你猜怎么着？",
          DialogueId = 51151013,
          FinalCamera = "-193.257812,491.109375,214.922363,0.000039,-12.799808,-74.597397,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "800D1B12",
          LookAt = {
            [1] = "700373:n(700372)",
            [2] = "700374:n(700372)",
            [3] = "100001:n(700372)",
            [4] = "200002:n(700372)",
            [5] = "700372:n(700374)"
          },
          NextDialogue = 51151014,
          SpeakNpcId = 700372,
          Subtitle = "I'd barely taken a few steps inside when I thought, hang on... why do these crates look so familiar? So I kept one hand on the wall and felt my way along. And guess what happened next?",
          TalkActionId = {
            [1] = "700372:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51151014] = {
          Camera = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "有话快说，一天到晚尽卖你那关子。",
          DialogueId = 51151014,
          FacialId = {
            [1] = "700373:CM_Angry01"
          },
          GUID = "800D1B3C",
          NextDialogue = 51151015,
          SpeakNpcId = 700373,
          Subtitle = "Out with it already. Don't leave us hanging.",
          TalkActionId = {
            [1] = "700373:Confident_New_Start",
            [2] = "700372:Explain02_End"
          }
        },
        [51151015] = {
          Content = "咱们里面就你进去过百年春那闹鬼的仓库，别吊大伙的胃口啦。",
          DialogueId = 51151015,
          FacialId = {
            [1] = "700373:CM_Idle"
          },
          GUID = "800D1B66",
          NextDialogue = 51151016,
          SpeakNpcId = 700374,
          Subtitle = "Yeah! You're the only one who actually made it inside that creepy warehouse. Come on, spill it.",
          TalkActionId = {
            [1] = "700374:Talk03_Start"
          }
        },
        [51151016] = {
          Camera = "22.886719,365.171875,164.92334,0.000081,-4.399475,-107.398392,40.32243,100000.0,false,DoNotOverride,2.8",
          Content = "你们还是太年轻，沉不住气，那我就给你们说明白咯——我当时就顺着墙壁，摸着货箱，一步一步地走。",
          DialogueId = 51151016,
          FacialId = {
            [1] = "700372:Cin_Angry01"
          },
          FinalCamera = "28.777344,301.472656,160.696777,0.000088,-3.399412,-113.597153,40.32243,100000.0,false,DoNotOverride,2.8",
          GUID = "800D1B90",
          NextDialogue = 51151017,
          SpeakNpcId = 700372,
          Subtitle = "You young lads have no patience. Fine, listen carefully then — I kept my hand on the wall, felt along the crates, and shuffled forward bit by bit.",
          TalkActionId = {
            [1] = "700372:Disagree"
          },
          ToFinalCameraBlendTime = 15
        },
        [51151017] = {
          Content = "我手上不是拿着蜡烛嘛，我就觉得……诶？这蜡烛怎么摇摆不定的？这屋子里明明也没风呀，结果，就在我一个晃神之间——！",
          DialogueId = 51151017,
          GUID = "800D1BBA",
          NextDialogue = 51151018,
          SpeakNpcId = 700372,
          Subtitle = "I had a candle in my hand, right? Suddenly I'm thinking, huh? Why's the flame wobbling like that? There wasn't even a breeze in there. Then, just as my mind wandered for a moment...",
          TalkActionId = {
            [1] = "700372:Explain02_Start",
            [2] = "700373:Confident_New_End",
            [3] = "700374:Talk03_End"
          }
        },
        [51151018] = {
          Camera = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "哇啊啊！",
          DialogueId = 51151018,
          FacialId = {
            [1] = "700374:CM_Shock01",
            [2] = "700372:Cin_Idle"
          },
          GUID = "800D1BE4",
          NextDialogue = 51151019,
          SpeakNpcId = 700374,
          Subtitle = "Waaah!",
          TalkActionId = {
            [1] = "700374:Shock_Start"
          }
        },
        [51151019] = {
          Content = "笨蛋，叫什么？本来不吓人，你这一嗓子给我吓得够呛！继续说！",
          DialogueId = 51151019,
          FacialId = {
            [1] = "700373:CM_Angry01"
          },
          GUID = "800D1C0E",
          LookAt = {
            [1] = "700373:n(700374)",
            [2] = "100001:n(700374)",
            [3] = "200002:n(700374)",
            [4] = "700372:n(700374)"
          },
          NextDialogue = 51151020,
          SpeakNpcId = 700373,
          Subtitle = "Idiot! What are you shrieking for? It wasn't scary until you yelled and made me jump! Go on!",
          TalkActionId = {
            [1] = "700373:Angry01_Start",
            [2] = "700374:Shock_End"
          }
        },
        [51151020] = {
          Content = "蜡烛，灭啦~~~",
          DialogueId = 51151020,
          FacialId = {
            [1] = "700373:CM_Idle",
            [2] = "700374:CM_Idle"
          },
          GUID = "800D1C38",
          LookAt = {
            [1] = "700373:n(700372)",
            [2] = "700374:n(700372)",
            [3] = "100001:n(700372)",
            [4] = "200002:n(700372)",
            [5] = "700372:n(700374)"
          },
          NextDialogue = 51151021,
          SpeakNpcId = 700372,
          Subtitle = "The candle... went out~!",
          TalkActionId = {
            [1] = "700372:Explain02_End",
            [2] = "700373:Angry01_End"
          }
        },
        [51151021] = {
          Camera = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "呜啊啊啊啊啊！",
          DialogueId = 51151021,
          FacialId = {
            [1] = "700374:CM_Shock01",
            [2] = "700373:CM_Shock01",
            [3] = "200002:Smile01"
          },
          FinalCamera = "-306.484375,75.011719,167.002441,0.000083,-8.799134,3.801234,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "800D1C62",
          LookAt = {
            [1] = "100001:n(700373)",
            [2] = "200002:n(700373)",
            [3] = "700372:n(700373)"
          },
          NextDialogue = 51151022,
          Scripts = "CameraShake{FileName {\"FixSimple_CameraShake_Normal\"}}",
          SpeakNpcId = 700374,
          Subtitle = "Uwaaaah!",
          TalkActionId = {
            [1] = "700373:Shock_Start",
            [2] = "700374:Shock_Start"
          },
          ToFinalCameraBlendTime = 1
        },
        [51151022] = {
          Content = "呜啊啊啊啊啊！",
          DialogueId = 51151022,
          GUID = "800D1C8C",
          NextDialogue = 51151023,
          SpeakNpcId = 700373,
          Subtitle = "Uwaaaah!"
        },
        [51151023] = {
          Content = "你这不是也被吓到了吗？",
          DialogueId = 51151023,
          FacialId = {
            [1] = "700373:CM_Idle",
            [2] = "700374:CM_Ahaha01"
          },
          GUID = "800D1CB6",
          LookAt = {
            [1] = "700373:n(700374)",
            [2] = "700374:n(700373)"
          },
          NextDialogue = 51151024,
          SpeakNpcId = 700374,
          Subtitle = "Ha! You totally jumped as well!",
          TalkActionId = {
            [1] = "700374:Shock_End"
          }
        },
        [51151024] = {
          Content = "我这是被你吓到的！后来呢？后来发生什么了？",
          DialogueId = 51151024,
          FacialId = {
            [1] = "700373:CM_Angry01",
            [2] = "700374:CM_Idle",
            [3] = "200002:Happy02",
            [4] = "100001:Ahaha02"
          },
          GUID = "800D1CE0",
          NextDialogue = 51151025,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"700373:n(700372)\"}}",
          SpeakNpcId = 700373,
          Subtitle = "I was scared by you! Anyway, what happened after that?",
          TalkActionId = {
            [1] = "700373:Shock_End"
          }
        },
        [51151025] = {
          Camera = "28.777344,301.472656,160.696777,0.000088,-3.399412,-113.597153,40.32243,100000.0,false,DoNotOverride,2.8",
          Content = "后面……我没了蜡烛看不见路，所以就顺着来路退出去咯。说了也奇怪，回程的时候顺风顺水，一点问题也没有。",
          DialogueId = 51151025,
          FacialId = {
            [1] = "700373:CM_Idle",
            [2] = "100001:None",
            [3] = "200002:None"
          },
          GUID = "800D1D0A",
          LookAt = {
            [1] = "700373:n(700372)",
            [2] = "700374:n(700372)",
            [3] = "100001:n(700372)",
            [4] = "200002:n(700372)",
            [5] = "700372:n(700374)"
          },
          NextDialogue = 51151026,
          SpeakNpcId = 700372,
          Subtitle = "After that... with no candle I couldn't see a thing, so I just felt my way back the same route. Funny thing is, going back was strangely easy — not a single hitch.",
          TalkActionId = {
            [1] = "700372:Disagree"
          }
        },
        [51151026] = {
          Camera = "-306.484375,75.011719,167.002441,0.000083,-8.799134,3.801234,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "看来这闹鬼的地方是有些玄乎……你身上不会沾了什么脏东西吧，这几天你可得好好去白龙神君那拜拜。",
          DialogueId = 51151026,
          GUID = "800D1D34",
          NextDialogue = 51151027,
          SpeakNpcId = 700373,
          Subtitle = "Sounds like that place really is a bit uncanny... Nothing followed you back, right? Best go pay your respects to Lord Argent, just in case.",
          TalkActionId = {
            [1] = "700373:Think_Start"
          }
        },
        [51151027] = {
          Content = "太可怕了，我每天回家的时候还要路过那间仓库呢，要是我也被那些家伙盯上……呜啊，好可怕！",
          DialogueId = 51151027,
          FacialId = {
            [1] = "700374:CM_Sad01"
          },
          GUID = "800D1D5E",
          LookAt = {
            [1] = "700374:n(700374)",
            [2] = "200002:n(200002)"
          },
          NextDialogue = 51151028,
          SpeakNpcId = 700374,
          Subtitle = "That's horrible... I walk past that warehouse every day on my way home. If something follows me home too... aaah!",
          TalkActionId = {
            [1] = "700374:Pray_Start"
          }
        },
        [51151028] = {
          Camera = "213.640625,-171.183594,172.974609,0.000074,-8.198412,134.596756,40.0,100000.0,false,DoNotOverride,2.8",
          Content = "闹鬼？华胥的幽灵不就是无由生嘛，所以说……是有无由生在捣乱？",
          DialogueId = 51151028,
          FacialId = {
            [1] = "200002:Think02",
            [2] = "700374:CM_Idle"
          },
          GUID = "800D1D88",
          NextDialogue = 51151029,
          SpeakNpcId = 200002,
          Subtitle = "Haunted? In Huaxu, ghosts are all just Wishen, aren't they? So... is it a Wishen messing with people in there?",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "700373:Think_End"
          }
        },
        [51151029] = {
          Camera = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "管他是闹鬼还是闹事，天岚先生既然把仓库托付给我们，就是相信我们无论发生什么都能把事摆平！",
          DialogueId = 51151029,
          FacialId = {
            [1] = "700373:CM_Angry01"
          },
          GUID = "800D1DB2",
          LookAt = {
            [1] = "100001:n(700373)",
            [2] = "200002:n(700373)"
          },
          NextDialogue = 51151030,
          SpeakNpcId = 700373,
          Subtitle = "Ghosts or no ghosts, Mr Tianlan left that warehouse in our care. That means he trusts us to handle whatever comes our way!",
          TalkActionId = {
            [1] = "700373:CM_Story_AngryPoint_Start"
          }
        },
        [51151030] = {
          Content = "兄弟们，话不多说，咱三今晚一起，把这仓库里的牛鬼蛇神全部赶走！成不成？",
          DialogueId = 51151030,
          GUID = "800D1DDC",
          LookAt = {
            [1] = "700373:n(700374)"
          },
          NextDialogue = 51151031,
          SpeakNpcId = 700373,
          Subtitle = "Enough talking. Tonight the three of us go in together and clear out whatever's hiding in there! What do you say?"
        },
        [51151031] = {
          Content = "……",
          DialogueId = 51151031,
          GUID = "800D1E06",
          LookAt = {
            [1] = "700373:n(700372)"
          },
          NextDialogue = 51151032,
          SpeakNpcId = 700372,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700374:Pray_End"
          }
        },
        [51151032] = {
          Content = "……",
          DialogueId = 51151032,
          GUID = "800D1E30",
          LookAt = {
            [1] = "700373:n(700374)"
          },
          NextDialogue = 51151033,
          SpeakNpcId = 700374,
          Subtitle = "..."
        },
        [51151033] = {
          Content = "怎么不说话？哑巴了？",
          DialogueId = 51151033,
          GUID = "800D1E5A",
          NextOptions = {
            [1] = 51151034,
            [2] = 51151035
          },
          SpeakNpcId = 700373,
          Subtitle = "Oi, why so quiet? Cat got your tongues?",
          TalkActionId = {
            [1] = "700373:CM_Story_AngryPoint_End"
          }
        },
        [51151034] = {
          Content = "他们看起来并不想去。",
          DialogueId = 51151034,
          GUID = "800D1E84",
          ImprPlusId = 1209,
          NextDialogue = 51151036,
          Subtitle = "It doesn't look like they're willing to go."
        },
        [51151035] = {
          Content = "怂了！",
          DialogueId = 51151035,
          GUID = "800D1EAE",
          ImprPlusId = 1210,
          NextDialogue = 51151036,
          Subtitle = "They're chickening out!"
        },
        [51151036] = {
          Content = "哥几个什么意思呢？天岚先生走之前怎么说的？你们对得起先生的信任吗？",
          DialogueId = 51151036,
          GUID = "800D1ED8",
          LookAt = {
            [1] = "700373:n(700372)"
          },
          NextDialogue = 51151037,
          SpeakNpcId = 700373,
          Subtitle = "Hey! What's with you lot? What did Mr Tianlan tell us before he left? Are you really going to let him down?",
          TalkActionId = {
            [1] = "700373:Angry01_Start"
          }
        },
        [51151037] = {
          Camera = "28.777344,301.472656,160.696777,0.000088,-3.399412,-113.597153,40.32243,100000.0,false,DoNotOverride,2.8",
          Content = "我已经去过了，下一个该轮到你们了……",
          DialogueId = 51151037,
          FacialId = {
            [1] = "700372:Cin_Ahaha02"
          },
          GUID = "800D1F02",
          NextDialogue = 51151038,
          SpeakNpcId = 700372,
          Subtitle = "I've already been there... It's your turn...",
          TalkActionId = {
            [1] = "700372:Salute_Start"
          }
        },
        [51151038] = {
          Camera = "-194.214844,51.722656,184.808594,0.000098,-12.799473,29.2036,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "我、我实在不敢去……",
          DialogueId = 51151038,
          FacialId = {
            [1] = "700374:CM_Sad01"
          },
          GUID = "800D1F2C",
          LookAt = {
            [1] = "700373:n(700374)"
          },
          NextDialogue = 51151039,
          SpeakNpcId = 700374,
          Subtitle = "I—I really don't have the nerve to go...",
          TalkActionId = {
            [1] = "700374:Disagree"
          }
        },
        [51151039] = {
          Camera = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "好！好啊你们，既然你们都不敢去，我就找别人一同前去！我就不信这偌大一个华胥，找不出两个有胆之人！",
          DialogueId = 51151039,
          GUID = "800D1F56",
          NextDialogue = 51151040,
          SpeakNpcId = 700373,
          Subtitle = "Fine! Suit yourselves! If none of you dare go, I'll find someone else! Don't tell me I can't find two people with a bit of backbone in all of Huaxu!",
          TalkActionId = {
            [1] = "700372:Salute_End"
          }
        },
        [51151040] = {
          Camera = "179.324219,-165.5,220.73877,0.000185,-15.398804,129.391922,30.0,100000.0,false,DoNotOverride,2.8",
          Content = "就……你！你们这两个外乡人，今夜和我一起去，如何？",
          DialogueId = 51151040,
          GUID = "800D1F80",
          LookAt = {
            [1] = "700373:n(100001)",
            [2] = "700372:n(100001)",
            [3] = "700374:n(100001)"
          },
          NextDialogue = 51151041,
          SpeakNpcId = 700373,
          Subtitle = "Hey... you two! Outlanders — you're coming with me tonight. How about it?",
          TalkActionId = {
            [1] = "700373:Angry01_End"
          }
        },
        [51151041] = {
          Camera = "70.183594,-23.027344,199.26416,0.000156,-17.198503,132.787445,40.0,100000.0,false,DoNotOverride,2.8",
          Content = "诶？我们只是来看热闹的，怎么把我们算上了？",
          DialogueId = 51151041,
          FacialId = {
            [1] = "200002:Shock02"
          },
          GUID = "800D1FAA",
          NextDialogue = 51151042,
          SpeakNpcId = 200002,
          Subtitle = "Huh!? We were just watching. How did we suddenly get dragged into this?",
          TalkActionId = {
            [1] = "200002:Think_End",
            [2] = "100001:TilteHead_Start"
          }
        },
        [51151042] = {
          Camera = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "怎么？怕了？看你们两个浓眉大眼的样子，还以为是什么勇武之士，没想到还是和这两个笨蛋一样，胆小怕事！",
          DialogueId = 51151042,
          GUID = "800D1FD4",
          LookAt = {
            [1] = "700373:n(200002)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 51151043,
          SpeakNpcId = 700373,
          Subtitle = "What, scared already? I thought the pair of you were proper warriors, but it turns out you're just as cowardly as these two idiots!",
          TalkActionId = {
            [1] = "700373:Talk03_Start",
            [2] = "100001:TilteHead_End"
          }
        },
        [51151043] = {
          Camera = "32.535156,17.695312,163.679688,0.000156,-19.198513,142.387589,40.0,100000.0,false,DoNotOverride,2.8",
          Content = "你说谁胆小怕事了！不就是无由生嘛，我和小仆从不知道都已经见过多少只了！倒是你，到时候可别吓晕过去，拖我们后腿！",
          DialogueId = 51151043,
          FacialId = {
            [1] = "200002:Angry01",
            [2] = "100001:Ahaha02"
          },
          GUID = "800D1FFE",
          NextDialogue = 51151044,
          SpeakNpcId = 200002,
          Subtitle = "Who are you calling cowardly! It's only a Wishen. Little Minion and I have dealt with more of them than we can count! Just don't pass out and slow us down!",
          TalkActionId = {
            [1] = "200002:Angry01_Start",
            [2] = "100001:Sigh_Start"
          }
        },
        [51151044] = {
          Camera = "-180.933594,126.3125,153.535645,0.000205,-4.798679,-17.01202,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "好！有骨气！那咱们就约好了，今天晚上，仓库门口见！对，咱们定个接头的暗号吧！就用……最有名的那句！",
          DialogueId = 51151044,
          FacialId = {
            [1] = "700373:CM_Happy01"
          },
          GUID = "800D2028",
          NextDialogue = 51151045,
          SpeakNpcId = 700373,
          Subtitle = "That's more like it! Knew you had some guts! Then it's settled — tonight at the warehouse door. Right... we'll need a watchword. Let's use the most famous line of all!",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          }
        },
        [51151045] = {
          Camera = "79.785156,-33.371094,194.149414,0.000156,-16.798576,132.787445,30.000002,100000.0,false,DoNotOverride,2.8",
          Content = "最有名的那句？想难倒我？魔王大人无所不知，那就今晚不见不散！",
          DialogueId = 51151045,
          FacialId = {
            [1] = "200002:Confident01",
            [2] = "100001:Doubt01"
          },
          GUID = "800D2052",
          NextDialogue = 51151046,
          SpeakNpcId = 200002,
          Subtitle = "The most famous line? Testing me, are you? Hmph. The Demon King knows everything. Tonight it is — you'd better show up!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          }
        },
        [51151046] = {
          Camera = "-3.273438,56.136719,193.95459,0.000133,-19.998594,124.586739,30.000008,100000.0,false,DoNotOverride,2.8",
          Content = "（为什么你会知道什么暗号啊！）",
          DialogueId = 51151046,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "-19.519531,79.710938,183.536133,0.000133,-19.998594,124.586739,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "800D207C",
          SpeakNpcId = 100001,
          Subtitle = "(Why does she even know that...?)",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 3
        },
        [51151047] = {
          Camera = "595.386719,637.626953,151.045898,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "之前咱们听了望春他们聊过后，我就去跟锦鲤皎皎打听了一下，如果她的消息没有出错……闹鬼的仓库就是这里了！",
          DialogueId = 51151047,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "555.324219,595.366699,149.560547,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "800D20A6",
          NextDialogue = 51151048,
          SpeakNpcId = 200002,
          Subtitle = "After listening to Wangchun and the others last time, I went and asked Lunocarp. If she got her facts straight... this should be the haunted warehouse!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51151048] = {
          Camera = "-36.691406,-227.51709,152.65332,0.000044,-7.06497,67.329269,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "既然是百年春烦恼的事情，就交给我们来帮忙解决吧！狩月人的售后服务，包老板满意！",
          DialogueId = 51151048,
          GUID = "800D20D0",
          SpeakNpcId = 200002,
          Subtitle = "If it's causing trouble for EverSpring, we'll deal with it! Phoxhunters' after-sales service — we never let a client down!",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51151049] = {
          Camera = "595.386719,637.626953,151.045898,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "我们白天路过的房子是这间吗？",
          DialogueId = 51151049,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "555.324219,595.366699,149.560547,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "800D20FA",
          NextDialogue = 51151050,
          SpeakNpcId = 100001,
          Subtitle = "Is this the place we walked past earlier?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51151050] = {
          Camera = "-36.691406,-227.51709,152.65332,0.000044,-7.06497,67.329269,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "唔……门口我做了石头标记……嗯嗯！就是这间！",
          DialogueId = 51151050,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "800D2124",
          NextDialogue = 51151051,
          SpeakNpcId = 200002,
          Subtitle = "Mmm... I left a stone by the door as a marker... Yup! This is the one!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          }
        },
        [51151051] = {
          Content = "那就进去一探究竟吧。",
          DialogueId = 51151051,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800D214E",
          NextDialogue = 51151052,
          SpeakNpcId = 100001,
          Subtitle = "Then let's head in and see what we find.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51151052] = {
          Content = "出发出发！",
          DialogueId = 51151052,
          GUID = "800D2178",
          SpeakNpcId = 200002,
          Subtitle = "Mm-hmm! Let's go!"
        },
        [51151053] = {
          Camera = "501.320312,-108.880371,210.521484,0.000008,-12.845597,152.96994,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "来了，接头暗号是？",
          DialogueId = 51151053,
          GUID = "800D21A2",
          LookAt = {
            [1] = "700373:n(100001)",
            [2] = "100001:n(700373)",
            [3] = "200002:n(700373)"
          },
          NextDialogue = 51151054,
          SpeakNpcId = 700373,
          Subtitle = "There you are. The watchword?",
          TalkActionId = {
            [1] = "700373:Talk03_Start"
          }
        },
        [51151054] = {
          Content = "接头暗号？",
          DialogueId = 51151054,
          FacialId = {
            [1] = "100001:Curious"
          },
          GUID = "800D21CC",
          NextDialogue = 51151055,
          SpeakNpcId = 100001,
          Subtitle = "Huh?",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51151055] = {
          Content = "你忘了吗？宫廷月夜酒……",
          DialogueId = 51151055,
          FacialId = {
            [1] = "700373:CM_Angry01"
          },
          GUID = "800D21F6",
          NextDialogue = 51151056,
          SpeakNpcId = 700373,
          Subtitle = "Forgotten already? Royal Noctar Brew...",
          TalkActionId = {
            [1] = "100001:ScratchHead_End"
          }
        },
        [51151056] = {
          Camera = "-75.279297,-3.990723,118.624023,0.000049,-9.845662,26.368061,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "二百八一壶！",
          DialogueId = 51151056,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "800D2220",
          LookAt = {
            [1] = "700373:n(200002)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 51151057,
          SpeakNpcId = 200002,
          Subtitle = "Two-eighty a pot!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          }
        },
        [51151057] = {
          Camera = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "这就是最有名的接头暗号吗？",
          DialogueId = 51151057,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "800D224A",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 51151058,
          SpeakNpcId = 100001,
          Subtitle = "That's the most famous line?",
          TalkActionId = {
            [1] = "100001:TilteHead_Start"
          }
        },
        [51151058] = {
          Camera = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "哼哼，小仆从对华胥的了解还是太肤浅啦~不像魔王大人，未卜先知，无所不知！",
          DialogueId = 51151058,
          GUID = "800D2274",
          NextDialogue = 51151059,
          SpeakNpcId = 200002,
          Subtitle = "Ha~ Little Minion, you know far too little about Huaxu. Not like your Demon King, who knows everything before it even happens!",
          TalkActionId = {
            [1] = "200002:AgreeHead"
          }
        },
        [51151059] = {
          Camera = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "是你缠着锦鲤皎皎教你的吧。",
          DialogueId = 51151059,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "800D229E",
          NextDialogue = 51151060,
          SpeakNpcId = 100001,
          Subtitle = "You pestered Lunocarp into teaching you that, didn't you?",
          TalkActionId = {
            [1] = "200002:Confident_End"
          }
        },
        [51151060] = {
          Camera = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "你怎么知道的！",
          DialogueId = 51151060,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "800D22C8",
          NextDialogue = 51151061,
          SpeakNpcId = 200002,
          Subtitle = "How did you know!?",
          TalkActionId = {
            [1] = "200002:Shock03_Start",
            [2] = "100001:TilteHead_End"
          }
        },
        [51151061] = {
          Camera = "501.320312,-108.880371,210.521484,0.000008,-12.845597,152.96994,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "哈哈。你们来之前，我早就绕着这房子转了两圈，除了檐角又长了些青苔之外，并无其他异样。等你们准备好了，咱们就进去。",
          DialogueId = 51151061,
          FacialId = {
            [1] = "700373:CM_Smile01",
            [2] = "100001:None",
            [3] = "200002:None"
          },
          GUID = "800D22F2",
          LookAt = {
            [1] = "700373:n(100001)",
            [2] = "100001:n(700373)",
            [3] = "200002:n(700373)"
          },
          NextDialogue = 51151062,
          SpeakNpcId = 700373,
          Subtitle = "Haha. Before you got here, I'd already done a couple of laps round this place. Didn't see anything weird — just a bit more moss on the eaves, that's all. Once you're ready, we'll head in.",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          }
        },
        [51151062] = {
          Content = "好，我们走吧。",
          DialogueId = 51151062,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800D231C",
          NextDialogue = 51151063,
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's go.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200002:Confident_Start"
          }
        },
        [51151063] = {
          Content = "勇气可嘉，不愧是我看中的人，我这就……咦？",
          DialogueId = 51151063,
          GUID = "800D2346",
          NextDialogue = 51151064,
          SpeakNpcId = 700373,
          Subtitle = "That's the spirit. Knew I picked the right people. Let me just— huh?",
          TalkActionId = {
            [1] = "700373:Talk03_End"
          }
        },
        [51151064] = {
          Content = "等等，我好像……没带开门的钥匙……",
          DialogueId = 51151064,
          FacialId = {
            [1] = "700373:CM_Idle"
          },
          GUID = "800D2370",
          LookAt = {
            [1] = "700373:n(700373)"
          },
          NextDialogue = 51151065,
          SpeakNpcId = 700373,
          Subtitle = "Wait... don't tell me... I forgot the key...",
          TalkActionId = {
            [1] = "700373:Disagree"
          }
        },
        [51151065] = {
          Camera = "-75.279297,-3.990723,118.624023,0.000049,-9.845662,26.368061,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "你也太粗心大意啦，这下我们该怎么进去？",
          DialogueId = 51151065,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "800D239A",
          NextDialogue = 51151066,
          SpeakNpcId = 200002,
          Subtitle = "You're so careless! How are we meant to get in now?"
        },
        [51151066] = {
          Content = "（一阵阴风吹来。“吱呀”一声，那本该紧锁的门，不知为何竟大敞开来。乍一望去，宛如一张黑漆漆的饕餮大口，似乎随时会将你们吞入……）",
          DialogueId = 51151066,
          GUID = "800D23C4",
          IsBlack = 1,
          NextDialogue = 51151067,
          Subtitle = "(A sudden gust of cold wind blows. With a long creak, the door that should have been locked tight slowly swings open, yawning like a pitch-black maw ready to swallow you whole...)"
        },
        [51151067] = {
          Camera = "212.025391,71.061035,156.366211,0.000012,-5.445498,168.168427,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "鬼啊！！！闹鬼啦！！！",
          DialogueId = 51151067,
          FacialId = {
            [1] = "700373:CM_Shock01"
          },
          GUID = "800D23EE",
          NextDialogue = 51151068,
          Scripts = "CameraShake{FileName {\"FixSimple_CameraShake_Normal\"}}",
          SpeakNpcId = 700373,
          Subtitle = "Gaah—!! It's actually haunted!",
          TalkActionId = {
            [1] = "700373:Shock_Start",
            [2] = "200002:Confident_End"
          }
        },
        [51151068] = {
          Content = "（在你们面前，肖阿壮扭头就跑，眨眼间便已经没了踪影……）",
          DialogueId = 51151068,
          GUID = "800D2418",
          IsBlack = 1,
          NextDialogue = 51151069,
          Scripts = "SetVisibility{ActorId{700373},Visibility{\"Hide\"}}",
          Subtitle = "(Xiao spins round and bolts. In the blink of an eye, he's gone...)"
        },
        [51151069] = {
          Camera = "-201.375,-40.395996,174.717773,0.000056,-11.445586,26.764484,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "不是……他……明明是他撺掇我们过来探险，这还没进去就被吓跑了？他今天在码头那样说话，我还以为他胆子很大呢！",
          DialogueId = 51151069,
          GUID = "800D2442",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 51151070,
          SpeakNpcId = 200002,
          Subtitle = "Wait— what? He's the one who dragged us into this, and he ran off before we even got inside? After how he acted at the docks today, I really thought he had guts!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          }
        },
        [51151070] = {
          Camera = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "白，你好好想想。他如果真的胆子很大，又为什么一定要拉上别人和他一起探险呢？",
          DialogueId = 51151070,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "800D246C",
          NextDialogue = 51151071,
          SpeakNpcId = 100001,
          Subtitle = "Think about it, Snow. If he were really that brave, he wouldn't need other people to tag along.",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "200002:Angry01_End"
          }
        },
        [51151071] = {
          Camera = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "是哦，这么说好像有些道理。小仆从，还是你观察仔细。那现在要怎么办，我们还进去吗？",
          DialogueId = 51151071,
          FacialId = {
            [1] = "200002:Think02"
          },
          GUID = "800D2496",
          NextDialogue = 51151072,
          SpeakNpcId = 200002,
          Subtitle = "Huh... fair point. You really are sharp, Little Minion. So what now — do we still go in?",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "100001:Talk02_End"
          }
        },
        [51151072] = {
          Camera = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
          Content = "是不是需要展现一下我对华胥的了解了？华胥有句俗语，叫……来都来了。",
          DialogueId = 51151072,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800D24C0",
          SpeakNpcId = 100001,
          Subtitle = "Guess it's my turn to show I do know Huaxu. There's a saying around here — we're already here, so we might as well.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51151073] = {
          Camera = "-54.057632,-5.761841,316.41864,0.00005,-11.218168,90.395935,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "仓库里怎么都是游荡的无由生……他们好像在守护着最里面的什么东西？",
