          Content = "我这也有妙妙罐罐，和我走，怎么样？",
          DialogueId = 51151115,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800D2BCE",
          NextDialogue = 51151116,
          SpeakNpcId = 100001,
          Subtitle = "I've got some Yum Treats too. How about sticking with me from now on?"
        },
        [51151116] = {
          Camera = "-257.016357,106.369873,179.233536,0.000001,-9.588553,-21.443916,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "吖……",
          DialogueId = 51151116,
          GUID = "800D2BF8",
          NextDialogue = 51151117,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
          SpeakNpcId = 700377,
          Subtitle = "Peep..."
        },
        [51151117] = {
          Content = "吖！",
          DialogueId = 51151117,
          GUID = "800D2C22",
          NextDialogue = 51151118,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}",
          SpeakNpcId = 700377,
          Subtitle = "Peep!"
        },
        [51151118] = {
          Content = "看起来它同意跟我们走啦~",
          DialogueId = 51151118,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "800D2C4C",
          NextDialogue = 51151119,
          SpeakNpcId = 200002,
          Subtitle = "Looks like it's agreed to come with us~",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          TurnTo = {
            [1] = "200002:n(100001)"
          }
        },
        [51151119] = {
          Content = "灵神大人，相逢本是一场缘，若是今日你选择离开，我们自然也不宜久留，只求大人记得我们，有空再来找我们说说话！",
          DialogueId = 51151119,
          GUID = "800D2C76",
          NextDialogue = 51151120,
          SpeakNpcId = 700375,
          Subtitle = "Lord Geniemon, our meeting must have been fate. If you choose to depart today, then we, too, should take our leave. Only... remember us, that is all we ask. Visit when time allows!",
          TalkActionId = {
            [1] = "700375:Wuyou_Agree"
          }
        },
        [51151120] = {
          Content = "大人……呜呜……可千万不要忘了我们啊，如果没有你，我们都不知道该和谁聊天了……",
          DialogueId = 51151120,
          GUID = "800D2CA0",
          NextDialogue = 51151121,
          SpeakNpcId = 700376,
          Subtitle = "My lord... (sob) Please don't forget us. Without you, we won't even know who to talk to anymore...",
          TalkActionId = {
            [1] = "700376:Wuyou_Disagree"
          }
        },
        [51151121] = {
          Content = "吖吖……",
          DialogueId = 51151121,
          GUID = "800D2CCA",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
          SpeakNpcId = 700377,
          Subtitle = "Peep, peep..."
        },
        [51151122] = {
          Content = "（你就这么看着一个魔灵和两个无由生相拥而泣，互相把不存在的眼泪抹在对方身上，等了好久，直到将哼哈二将送至门外……）",
          DialogueId = 51151122,
          GUID = "800D2CF4",
          Subtitle = "(You watch as a Geniemon and two Wishen hug and sob, wiping imaginary tears onto one another. You wait a long while before finally seeing Hmph Shen and Ha Shen off at the door...)"
        },
        [51151123] = {
          Content = "呼~可算把两位无由生送走了，想不到这些无由生还挺有情有义的嘛……接下来就轮到……",
          DialogueId = 51151123,
          GUID = "800D2D1E",
          NextDialogue = 51151124,
          SpeakNpcId = 200002,
          Subtitle = "Whew~ Finally got those two Wishen on their way. Who would've thought they'd be so loyal and sentimental... Now—"
        },
        [51151124] = {
          Content = "小仆从，你带妙妙罐罐了吗？试试投喂这只魔灵吧！",
          DialogueId = 51151124,
          GUID = "800D2D48",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, did you bring any Yum Treats? Go on — try feeding this Geniemon!"
        },
        [51151125] = {
          Content = "（这只魔灵似乎对你们的到来看起来有些疑惑。）",
          DialogueId = 51151125,
          GUID = "800D263B",
          NextDialogue = 51151082,
          Subtitle = "(This Geniemon seems somewhat puzzled by your arrival.)"
        },
        [51151126] = {
          Content = "（这只魔灵明显意识到了你们的来意，但因有无由生相助而显得十分得意。）",
          DialogueId = 51151126,
          GUID = "800D26B9",
          NextDialogue = 51151085,
          Subtitle = "(The Geniemon clearly understands your intentions but appears quite smug with the Wishen by its side.)"
        },
        [51151127] = {
          Content = "（咿咿呀呀说了一大堆，完全听不懂……）",
          DialogueId = 51151127,
          GUID = "800D278B",
          NextDialogue = 51151090,
          Subtitle = "(It babbles a great deal... completely incomprehensible...)"
        },
        [51151128] = {
          Content = "(它似乎有些害怕？）",
          DialogueId = 51151128,
          GUID = "800D2833",
          NextDialogue = 51151094,
          Subtitle = "(It seems a bit frightened?)"
        },
        [51151129] = {
          Content = "是说百年春角落那间仓库吗？那里不是早就租给天岚先生做供货仓库了吗？为何现在过来提起？",
          DialogueId = 51151129,
          GUID = "800D2D49",
          SpeakNpcId = 700370,
          Subtitle = "You mean that warehouse over in the corner of EverSpring? Mr Tianlan rented it as a storehouse some time ago. Why bring it up now?"
        },
        [51151201] = {
          Camera = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "是白魔王大人和她忠诚的有龙氏随从！你们来找我玩啦！",
          DialogueId = 51151201,
          GUID = "800D39EA",
          NextDialogue = 51151202,
          Scripts = [[
SEQ{
PARA{
LookAt{LookAtDescription{"200002:n(900012)"}}, 
LookAt{LookAtDescription{"100001:n(900012)"}},
PlayAnimation{ActorId{900012},AnimationId{"Talk02_Start"}},
LookAt{LookAtDescription{"900012:n(200002)"}}
},
LookAt{_delay{1},LookAtDescription{"900012:n(100001)"}}
}]],
          SpeakNpcId = 900012,
          Subtitle = "Hey! Look who it is — Snow the Demon King and her trusty Loongscion! You came to see me!"
        },
        [51151202] = {
          Content = "“她忠诚的有龙氏随从”不配拥有自己的姓名吗？",
          DialogueId = 51151202,
          GUID = "800D3A14",
          NextDialogue = 51151203,
          SpeakNpcId = 100001,
          Subtitle = "I have a name.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51151203] = {
          Content = "当然是开玩笑的啦，{nickname}也是锦鲤皎皎的好朋友！你的角红红的一只，像枫叶，很特别。我很羡慕这样的角呢。",
          DialogueId = 51151203,
          FacialId = {
            [1] = "900012:Smile02"
          },
          GUID = "800D3A3E",
          NextDialogue = 51151204,
          SpeakNpcId = 900012,
          Subtitle = "Haha, I know! Just messing with you, ! You're a good friend of mine too! And that red horn of yours — like a pretty maple leaf — I'm sooo jealous, I want one too!",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "900012:Talk02_End"
          }
        },
        [51151204] = {
          Camera = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "说起来，锦鲤皎皎，这个高高的、装满小球的机器是什么？",
          DialogueId = 51151204,
          FacialId = {
            [1] = "900012:None"
          },
          FinalCamera = "368.707031,55.0,181.27832,0.000102,5.401252,-149.163544,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "800D3A68",
          NextDialogue = 51151205,
          SpeakNpcId = 200002,
          Subtitle = "Hey, Lunocarp, what's that tall machine stuffed with all those little balls?",
          ToFinalCameraBlendTime = 1
        },
        [51151205] = {
          Camera = "277.509766,14.723633,155.932617,0.000082,-10.198612,-178.573135,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "不愧是火眼金睛的白魔王大人，一眼就能看出好东西！这可是本皎皎做生意的独家秘诀。",
          DialogueId = 51151205,
          FacialId = {
            [1] = "900012:Confident01"
          },
          GUID = "800D3A92",
          LookAt = {
            [1] = "900012:n(200002)"
          },
          NextDialogue = 51151206,
          SpeakNpcId = 900012,
          Subtitle = "You're really sharp, Snow the Demon King! Spotted the good stuff straight away! This here is my secret money-maker!",
          TalkActionId = {
            [1] = "900012:Excited01_Start"
          }
        },
        [51151206] = {
          Content = "我特意找一个机枢派的叫公、公什么的师傅定制了这套福运蛋机。只要往里面投入代币，它就会给你随机吐小奖品出来！",
          DialogueId = 51151206,
          GUID = "800D3ABC",
          NextDialogue = 51151207,
          SpeakNpcId = 900012,
          Subtitle = "I went to a craftsman from the Jishu Sect — Master Gong... Gong-something — and had him build this Lucky Egg machine for me! Toss in a token and — pop! — out comes a random prize!",
          TalkActionId = {
            [1] = "900012:Excited01_End"
          }
        },
        [51151207] = {
          Camera = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "随机性才是挣钱的诀窍——这是本皎皎某天向白龙神君大人祈祷时，一下子福至心灵想出来的。怎么样，是不是天才般的想法？",
          DialogueId = 51151207,
          GUID = "800D3AE6",
          LookAt = {
            [1] = "900012:n(900012)"
          },
          NextDialogue = 51151208,
          SpeakNpcId = 900012,
          Subtitle = "The trick is letting randomness work its wonders — that's how you make money! This genius idea hit me while I was praying to Lord Argent. Amazing, right?",
          TalkActionId = {
            [1] = "900012:Excited02_Start"
          }
        },
        [51151208] = {
          Camera = "-57.599609,-59.527832,146.118164,0.000087,-5.198607,48.427074,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "那你的生意好吗？",
          DialogueId = 51151208,
          GUID = "800D3B10",
          NextDialogue = 51151209,
          SpeakNpcId = 100001,
          Subtitle = "So... is business any good?",
          TalkActionId = {
            [1] = "900012:Excited02_End",
            [2] = "100001:Talk02_Start"
          }
        },
        [51151209] = {
          Camera = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "……呜，一般。",
          DialogueId = 51151209,
          FacialId = {
            [1] = "900012:Syouganai01"
          },
          GUID = "800D3B3A",
          NextDialogue = 51151210,
          SpeakNpcId = 900012,
          Subtitle = "...Meh. Only so-so.",
          TalkActionId = {
            [1] = "900012:DisagreeHead",
            [2] = "100001:Talk02_End"
          }
        },
        [51151210] = {
          Content = "因为这个想法太新潮了，所以到现在连机器的本钱还没挣回来。大概这就是高手常常落寞吧。",
          DialogueId = 51151210,
          FacialId = {
            [1] = "900012:Sad03"
          },
          GUID = "800D3B64",
          NextDialogue = 51151211,
          SpeakNpcId = 900012,
          Subtitle = "It's just too ahead of its time, so I still haven't made back what I spent on it. Guess that's the fate of a true genius.",
          TalkActionId = {
            [1] = "900012:Shy03_Start"
          }
        },
        [51151211] = {
          Content = "如果你们在烟津渡捡到什么太虚符文呀、齿轮呀一类的玩意儿，可以用它来抽福运蛋机。",
          DialogueId = 51151211,
          FacialId = {
            [1] = "900012:None"
          },
          GUID = "800D3B8E",
          NextDialogue = 51151212,
          SpeakNpcId = 900012,
          Subtitle = "Anyway... if you pick up any Taixu Runes, gears, or stuff like that around Mistwharf, you can use them for a spin on my Lucky Egg machine."
        },
        [51151212] = {
          Content = "这些福运蛋里的小垃圾……咳咳，不对，是小奖品！你们就不客气地拿走，当做是本皎皎的一片心意吧！",
          DialogueId = 51151212,
          GUID = "800D3BB8",
          SpeakNpcId = 900012,
          Subtitle = "These little pieces of useless rubbi— um, I mean, the prizes! Whatever comes out, it's yours! Think of it as a little gift from me!",
          TalkActionId = {
            [1] = "900012:Shy03_End"
          }
        },
        [51151301] = {
          Content = "是{nickname}和白魔王大人，你们来找我玩啦！今天的福运蛋又上新了新款式，要不要来扭一发试试？",
          DialogueId = 51151301,
          GUID = "800D4A52",
          NextOptions = {
            [1] = 51151302,
            [2] = 51151307
          },
          SpeakNpcId = 900012,
          Subtitle = "Hey, it's  and Snow the Demon King! You came to visit me again! I've got brand-new Lucky Eggs today — wanna give it a spin?",
          TalkActionId = {
            [1] = "900012:Explain01_Start"
          }
        },
        [51151302] = {
          Content = "聊聊锦鲤皎皎的梦想。",
          DialogueId = 51151302,
          GUID = "800D4A7C",
          NextDialogue = 51151303,
          Subtitle = "Ask Lunocarp about her dreams."
        },
        [51151303] = {
          Content = "我呀，以前只是个普普通通的皎皎，每天最大的梦想不过是怎么从那些抠门织星客手中多抢下来几个单子，直到白魔王大人的出现改变了这一切——",
          DialogueId = 51151303,
          GUID = "800D4AA6",
          NextDialogue = 51151304,
          SpeakNpcId = 900012,
          Subtitle = "Me? I used to be just a plain old Luno, trying every day to squeeze a few more orders out of those stingy Starweavers. But then Snow the Demon King showed up — and she changed my life!",
          TalkActionId = {
            [1] = "900012:Explain01_End"
          }
        },
        [51151304] = {
          Content = "现在的我已经不再是昨日的我了！我要成为青史留名的织星客，带领皎皎一族走向辉煌！",
          DialogueId = 51151304,
          GUID = "800D4AD0",
          NextDialogue = 51151305,
          SpeakNpcId = 900012,
          Subtitle = "I'm not the same Luno I used to be! I'm gonna become a Starweaver whose name goes down in history — and bring the Lunos back to glory!",
          TalkActionId = {
            [1] = "900012:Excited02_Start"
          }
        },
        [51151305] = {
          Content = "以后白魔王大人的宫殿旁边，一定也有本皎皎豪华商铺的一席之地！",
          DialogueId = 51151305,
          GUID = "800D4AFA",
          NextDialogue = 51151306,
          SpeakNpcId = 900012,
          Subtitle = "Someday, right next to the Demon King's palace, there'll be a huge, fancy shop with my name on it — absolutely!"
        },
        [51151306] = {
          Content = "这是约定和梦想！你们就等着瞧吧，我一定会做到的！",
          DialogueId = 51151306,
          GUID = "800D4B24",
          NextDialogue = 51151313,
          SpeakNpcId = 900012,
          Subtitle = "It's both a dream and a promise! Just you wait — I'll make it happen!",
          TalkActionId = {
            [1] = "900012:Excited02_End"
          }
        },
        [51151307] = {
          Content = "聊聊锦鲤皎皎的生意经。",
          DialogueId = 51151307,
          GUID = "800D4B4E",
          NextDialogue = 51151308,
          Subtitle = "Ask Lunocarp about her business ideas."
        },
        [51151308] = {
          Content = "听我说听我说，我最近有一个体悟……福运蛋之所以没什么人来玩，除了它太新潮之外，奖品不够吸引人也是一大痛点！",
          DialogueId = 51151308,
          GUID = "800D4B78",
          NextDialogue = 51151309,
          SpeakNpcId = 900012,
          Subtitle = "Ooh, about that — I had an epiphany lately! The Lucky Egg isn't just struggling because it's ahead of its time — the real problem is that the prizes are boring! That's the fatal flaw!",
          TalkActionId = {
            [1] = "900012:Explain01_End"
          }
        },
        [51151309] = {
          Content = "华胥有些织星客和悬衡派谈下了授权，专门售卖限定版香囊，生意可红火啦。这给了本皎皎灵感！",
          DialogueId = 51151309,
          GUID = "800D4BA2",
          NextDialogue = 51151310,
          SpeakNpcId = 900012,
          Subtitle = "Some Starweavers in Huaxu made deals with the Xuanheng Sect to sell limited-edition sachets, and they're selling like crazy! That totally inspired me!",
          TalkActionId = {
            [1] = "900012:Talk02_Start"
          }
        },
        [51151310] = {
          Content = "说到足够吸引人的奖品，那自然得是我们人见人爱的皎皎一族！",
          DialogueId = 51151310,
          GUID = "800D4BCC",
          NextDialogue = 51151311,
          SpeakNpcId = 900012,
          Subtitle = "And if we're talking irresistibly adorable prizes, it's obviously us Lunos!",
          TalkActionId = {
            [1] = "900012:Talk02_End"
          }
        },
        [51151311] = {
          Content = "{nickname}，你说你说，我去订制一款皎皎联名奖品，将来自海伯利亚的魔王大人作为压轴隐藏款，是不是一定能大卖特卖？",
          DialogueId = 51151311,
          GUID = "800D4BF6",
          NextDialogue = 51151312,
          SpeakNpcId = 900012,
          Subtitle = "If I make a collab with the Demon King and put it in as the secret rare drop — it's gonna be a massive hit, right? What do you think, ?",
          TalkActionId = {
            [1] = "900012:Excited01_Start"
          }
        },
        [51151312] = {
          Content = "嘿嘿，到时候一定会数钱数到手软！",
          DialogueId = 51151312,
          GUID = "800D4C20",
          NextDialogue = 51151313,
          SpeakNpcId = 900012,
          Subtitle = "Haha! I'll be rolling in coins till I'm dizzy!",
          TalkActionId = {
            [1] = "900012:Excited01_End"
          }
        },
        [51151313] = {
          Content = "你们忙你们的去吧！在努力实现梦想这方面，本皎皎也不能输！",
          DialogueId = 51151313,
          GUID = "800D4C4A",
          SpeakNpcId = 900012,
          Subtitle = "Okay, okay, off you go — you've got things to do! And I've got dreams to chase too... no way I'm falling behind!"
        },
        [51151401] = {
          ContentES = "... (Lunoeggy escribe en la tabla: “Encantada de verte.”)",
          DialogueId = 51151401,
          GUID = "800D5ABA",
          NextOptions = {
            [1] = 51151402,
            [2] = 51151403
          },
          SpeakNpcId = 900011,
          Subtitle = "... (Lunoeggy writes on the board: \"So glad you're here!\")"
        },
        [51151402] = {
          ContentES = "Tengo la sensación de haberte visto en algún lugar...",
          DialogueId = 51151402,
          GUID = "800D5AE4",
          NextDialogue = 51151404,
          Subtitle = "I feel like I've seen you somewhere before..."
        },
        [51151403] = {
          ContentES = "¿No nos habremos encontrado en Lago Helado?",
          DialogueId = 51151403,
          GUID = "800D5B0E",
          NextDialogue = 51151404,
          Subtitle = "Have we met in a place called Icelake?"
        },
        [51151404] = {
          ContentES = "... (¡Exacto! ¡Soy yo! Tengo muchísimas, muchísimas copias. Si no me crees, espera a llegar a la próxima ciudad: verás otra versión de mí allí.)",
          DialogueId = 51151404,
          GUID = "800D5B38",
          NextOptions = {
            [1] = 51151405,
            [2] = 51151407
          },
          SpeakNpcId = 900011,
          Subtitle = "... (That's right! It's me! I've got loads and loads of copies of myself. If you don't believe me, just wait until you reach the next city — you'll see another me there.)"
        },
        [51151405] = {
          ContentES = "Te creo.",
          DialogueId = 51151405,
          GUID = "800D5B62",
          ImprPlusId = 1207,
          NextDialogue = 51151406,
          Subtitle = "I believe you."
        },
        [51151406] = {
          ContentES = "¡Una Lunoeggy capaz de multiplicarse… Qué criatura increíblemente fascinante!",
          DialogueId = 51151406,
          GUID = "800D5B8C",
          NextOptions = {
            [1] = 51151412
          },
          SpeakNpcId = 100001,
          Subtitle = "A Lunoeggy with countless copies... what an incredible little creature."
        },
        [51151407] = {
          ContentES = "No me lo creo.",
          DialogueId = 51151407,
          GUID = "800D5BB6",
          ImprPlusId = 1208,
          NextDialogue = 51151408,
          Subtitle = "I don't buy it."
        },
        [51151408] = {
          ContentES = "¿Son simplemente diferentes Luno escondidas dentro de cáscara similares, verdad? Solo me pregunto por qué todas eligieron exactamente la misma.",
          DialogueId = 51151408,
          GUID = "800D5BE0",
          NextDialogue = 51151409,
          SpeakNpcId = 100001,
          Subtitle = "You're just different Lunos hiding inside the same sort of eggshell, aren't you? You just happened to pick matching shells, for some reason."
        },
        [51151409] = {
          ContentES = "... (¡Ja! ¡Porque el mejor escondite es mezclarse entre una multitud de Lunoeggy!)",
          DialogueId = 51151409,
          GUID = "800D5C0A",
          NextDialogue = 51151410,
          SpeakNpcId = 900011,
          Subtitle = "... (Hah! That's because the best hiding place is in a crowd of me!)"
        },
        [51151410] = {
          ContentES = "... (Así, cuando una de nosotras te gana en los dados y buscas vengarte, nunca sabes cuál de nosotras te ha vencido.)",
          DialogueId = 51151410,
          GUID = "800D5C34",
          NextDialogue = 51151411,
          SpeakNpcId = 900011,
          Subtitle = "... (That way, when one of me beats you at dice and you try to win your money back... you'll never know which one it was!)"
        },
        [51151411] = {
          ContentES = "Tiene sentido.",
          DialogueId = 51151411,
          GUID = "800D5C5E",
          NextOptions = {
            [1] = 51151412
          },
          SpeakNpcId = 100001,
          Subtitle = "That actually makes sense."
        },
        [51151412] = {
          ContentES = "Entonces… ¿puedes abrir la cáscara y mostrarme qué hay dentro?",
          DialogueId = 51151412,
          GUID = "800D5C88",
          NextDialogue = 51151413,
          Subtitle = "So... can you open the eggshell and show me what's inside?"
        },
        [51151413] = {
          ContentES = "... (¡Imposible! Bajo el cascarón hay más cascarón, bajo el cascarón solo hay cascarón, ¡definitivamente no es una Luno, absolutamente no!)",
          DialogueId = 51151413,
          GUID = "800D5CB2",
          SpeakNpcId = 900011,
          Subtitle = "...! (Absolutely not! Under this eggshell is another eggshell, and under that is another one! Definitely not a Luno... definitely not!)"
        },
        [51152002] = {
          Content = "诶？小仆从小仆从，这附近的风声好大哦，你听你听，呜呜呜呜呜的。",
          DialogueId = 51152002,
          GUID = "800DBD54",
          SpeakNpcId = 701087,
          Subtitle = "Huh? Little Minion, listen — hear that? The wind's so loud out here. Woooooo..."
        },
        [51152003] = {
          Content = "呜……呜……",
          DialogueId = 51152003,
          GUID = "800DBD7E",
          SpeakNpcName = "UI_CMNpc_Name_Zhongniannan",
          Subtitle = "Woo... woo..."
        },
        [51152004] = {
          Content = "呜……别过来，不要逼我……不要逼我！",
          DialogueId = 51152004,
          GUID = "800DBDA8",
          SpeakNpcName = "UI_CMNpc_Name_Zhongniannan",
          Subtitle = "Woo... don't come any closer... Don't make me do this... Don't—!"
        },
        [51152005] = {
          Content = "咦，不，不是风声，好像是有人在前面！我们快过去看看发生了什么吧。",
          DialogueId = 51152005,
          GUID = "800DBDD2",
          SpeakNpcId = 701087,
          Subtitle = "Wait... That's not the wind. Someone's up ahead! C'mon — let's take a look!"
        },
        [51152007] = {
          Content = "好，我们出发！",
          DialogueId = 51152007,
          GUID = "800DBE26",
          SpeakNpcId = 200002,
          Subtitle = "Right! Let's go!"
        },
        [51152008] = {
          Content = "呜哇，好多秽兽，看招看招！",
          DialogueId = 51152008,
          GUID = "800DBE50",
          SpeakNpcId = 200002,
          Subtitle = "Woah... there's loads of them! Alright, bring it on!"
        },
        [51152009] = {
          Content = "好耶，马上就能把这群坏家伙打跑了。不过话说回来，你有没有觉得那个被困的家伙有点眼熟哇？",
          DialogueId = 51152009,
          GUID = "800DBE7A",
          SpeakNpcId = 200002,
          Subtitle = "Ha! We're gonna chase these nasty things off in a sec! ...Hang on. Doesn't that guy they've got cornered look kinda familiar?"
        },
        [51152010] = {
          Content = "先专注眼前的敌人吧。",
          DialogueId = 51152010,
          GUID = "800DBEA4",
          SpeakNpcId = 100001,
          Subtitle = "Eyes front. Finish the fight first."
        },
        [51152011] = {
          Camera = "643.927734,72.326172,238.735352,0.000106,-19.939514,-168.080322,35.0,472.956573,false,Manual,2.557317",
          Content = "呼……呼……",
          DialogueId = 51152011,
          FinalCamera = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
          GUID = "800DBECE",
          LookAt = {
            [1] = "200002:n(701088)"
          },
          SpeakNpcId = 701088,
          Subtitle = "Huff... huff...",
          TalkActionId = {
            [1] = "701088:Hurt01"
          },
          ToFinalCameraBlendTime = 5
        },
        [51152012] = {
          Camera = "421.720703,-66.143555,106.893555,0.00008,-8.94039,-173.895111,35.000008,197.80249,false,Manual,2.8",
          Content = "那些秽兽都被我们打跑啦，你的伤……",
          DialogueId = 51152012,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "800DBEF8",
          SpeakNpcId = 200002,
          Subtitle = "They've gone! You're bleeding — are you alright?",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          TurnTo = {
            [1] = "701088:n(100001)"
          }
        },
        [51152013] = {
          Content = "发乎于心，现乎于行。若是动了兵戈，人心就会变质。无论这兵戈朝向的是友邻还是恶敌，性质都是相同的！终是逆了天意呀！",
          DialogueId = 51152013,
          GUID = "800DBF22",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'\n",
          SpeakNpcId = 701088,
          Subtitle = "It begins in the heart and takes shape in one's deeds. Once a blade is drawn, the heart is changed — no matter if that blade is turned on friend or foe, the nature of it is the same. In the end... it defies the will of Heaven!",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          }
        },
        [51152014] = {
          Content = "按照你的意思。我们应该在原地待着，什么都不做，束手就擒……是吗？",
          DialogueId = 51152014,
          GUID = "800DBF4C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'",
          SpeakNpcName = "UI_Npc_Name_Zhiliu",
          Subtitle = "So you're saying we should stand idle, do nothing — and let them devour us? Is that it?"
        },
        [51152015] = {
          Content = "白龙神君会为我们驱除恶邪的！要是招来白龙神君的厌弃，失去了祂的庇护，那才是因小失大。您请三思啊！",
          DialogueId = 51152015,
          GUID = "800DBF76",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'",
          SpeakNpcId = 701088,
          Subtitle = "Lord Argent will drive this evil away for us! If we provoke Their wrath and lose Their protection, that would be our true ruin. I beg you — please reconsider!"
        },
        [51152016] = {
          Camera = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
          Content = "啊，是你！你是那时候被止流姐姐赶出百年春的家伙。",
          DialogueId = 51152016,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "800DBFA0",
          SpeakNpcId = 200002,
          Subtitle = "Oh! It's you — you're the bloke Zhiliu kicked out of EverSpring!",
          TalkActionId = {
            [1] = "200002:Talk01_Start"
          }
        },
        [51152017] = {
          Camera = "414.412109,-49.105469,121.125977,0.000048,1.599821,152.399612,35.0,290.856323,false,Manual,2.056568",
          Content = "（鲜血顺着男子的额角滑至地面，那摊鲜血旁，倒着一只死去不久的秽兽。结合周围香雾缭绕却未见狴犴的样子，看来他直到遇袭都没等到白龙神君的庇护。）",
          DialogueId = 51152017,
          GUID = "800DBFCA",
          SpeakNpcId = 0,
          Subtitle = "(Blood trickled from the man's brow and pooled on the ground. Beside it lay a Filthoid, dead only moments ago. Incense hung heavy in the air, yet there was no sign of Bi'an. It seems that even with his life on the line, Lord Argent's protection never came.)",
          TalkActionId = {
            [1] = "200002:Talk01_End",
            [2] = "100001:Give"
          }
        },
        [51152018] = {
          Content = "这只秽兽是你杀死的。",
          DialogueId = 51152018,
          GUID = "800DBFF4",
          ImprPlusId = 1208,
          Subtitle = "So you killed this Filthoid."
        },
        [51152019] = {
          Content = "看来白龙神君并没有对你出手相助。",
          DialogueId = 51152019,
          GUID = "800DC01E",
          ImprPlusId = 1206,
          Subtitle = "Looks like Lord Argent didn't lift a finger."
        },
        [51152020] = {
          Content = "之前不是说，就算是死外面也绝不动武吗？",
          DialogueId = 51152020,
          GUID = "800DC048",
          ImprPlusId = 1210,
          Subtitle = "Thought you'd rather die than fight?"
        },
        [51152024] = {
          Camera = "360.478516,-106.482422,91.936523,0.000124,0.0,159.903,16.91279,275.194305,false,Manual,2.8",
          Content = "哈哈……是你们。我在百年春见过你们。",
          DialogueId = 51152024,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800DC0F0",
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Wave02_Start"},Duration{3}},
PlayAnimation{ActorId{100001},AnimationId{"Wave02_End"}}
}]],
          SpeakNpcId = 701088,
          Subtitle = "Hah... so it's you. I saw you back at EverSpring.",
          TalkActionId = {
            [1] = "701088:Idle",
            [2] = "200002:Confident_Start"
          }
        },
        [51152025] = {
          Camera = "61.623047,-87.913086,149.791992,0.000068,3.860225,27.111759,35.000008,629.109375,false,DoNotOverride,2.8",
          Content = "你们是来耻笑我的吗……无所谓，笑就笑吧。我触犯了诫律，我动了兵刃……",
          DialogueId = 51152025,
          GUID = "800DC11A",
          SpeakNpcId = 701088,
          Subtitle = "Come to mock me, have you...? Go on, then. I broke the Admonitions. I took up a weapon..."
        },
        [51152026] = {
          Camera = "61.623047,-87.913086,149.791992,0.000068,3.860225,27.111759,35.000008,629.109375,false,DoNotOverride,2.8",
          Content = "我犯了错……白龙神君就要降下惩罚了。哈、哈……",
          DialogueId = 51152026,
          FacialId = {
            [1] = "701088:Sad01"
          },
          GUID = "800DC144",
          SpeakNpcId = 701088,
          Subtitle = "I've sinned... and now Lord Argent will punish me. Heh...",
          TalkActionId = {
            [1] = "701088:Disagree"
          }
        },
        [51152027] = {
          Camera = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
          Content = "你是笨蛋吗！死脑筋！",
          DialogueId = 51152027,
          FacialId = {
            [1] = "200002:Angry02"
          },
          GUID = "800DC16E",
          SpeakNpcId = 200002,
          Subtitle = "You idiot! You're impossible.",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          }
        },
        [51152028] = {
          Camera = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
          Content = "我听小仆从说，白龙神君只是说，不能对人类动手吧？但祂没有说过，对秽兽动手也不可以吧？",
          DialogueId = 51152028,
          GUID = "800DC198",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion told me — Lord Argent only said you can't hurt people, right? No one said you couldn't fight Filthoids!",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          }
        },
        [51152029] = {
          Camera = "-44.644531,-128.060547,109.717773,0.000053,4.460147,35.51128,35.000008,395.555206,false,Manual,2.8",
          Content = "我、我不知道……诫律没提到秽兽，我不知道……我只知道，不可动武，不可动武……这是我从小到大的信仰。",
          DialogueId = 51152029,
          FacialId = {
            [1] = "701088:Grief"
          },
          GUID = "800DC1C2",
          SpeakNpcId = 701088,
          Subtitle = "I—I don't know... The Admonitions never said anything about Filthoids. I don't know. All I ever knew was: no violence. Don't ever fight... That's what I've believed my whole life.",
          TalkActionId = {
            [1] = "701088:Sigh_Start"
          }
        },
        [51152030] = {
          Camera = "-44.644531,-128.060547,109.717773,0.000053,4.460147,35.51128,35.000008,395.555206,false,Manual,2.8",
          Content = "可是刚刚，那秽兽扑上来，血盆大口对着我，我无论如何都不想死、不想死啊！于是我就拿着、拿着砍树的柴刀，拼命地——",
          DialogueId = 51152030,
          GUID = "800DC1EC",
          SpeakNpcId = 701088,
          Subtitle = "But then that Filthoid jumped me — fangs out, claws everywhere... I—I didn't want to die! So I grabbed my woodcutting axe... and I just... swung for my life—",
          TalkActionId = {
            [1] = "701088:Sigh_End"
          }
        },
        [51152031] = {
          Camera = "431.021484,-25.061523,196.442383,0.000075,-11.940488,159.505447,35.000008,308.194794,false,Manual,2.8",
          Content = "这就对了。",
          DialogueId = 51152031,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "800DC216",
          SpeakNpcId = 100001,
          Subtitle = "That's more like it.",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51152032] = {
          Camera = "431.021484,-25.061523,196.442383,0.000075,-11.940488,159.505447,35.000008,308.194794,false,Manual,2.8",
          Content = "什么神明，什么信仰，都没有活下去重要，这才是你的本心。所以，你才会在生死关头做出这样的选择。",
          DialogueId = 51152032,
          GUID = "800DC240",
          SpeakNpcId = 100001,
          Subtitle = "Gods, faith — none of it matters more than staying alive. When it came down to it, you listened to your gut and fought to survive."
        },
        [51152033] = {
          Camera = "338.265625,19.038086,179.210938,0.000076,-10.340483,176.105225,35.0,210.359772,false,Manual,2.8",
          Content = "看你伤成这样，就不笑话你了。人想活着有什么错？我送你回百年春吧。",
          DialogueId = 51152033,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "800DC26A",
          SpeakNpcId = 100001,
          Subtitle = "I'd laugh, but look at you. Guess I'll cut you some slack this time. Seriously though — what's so wrong with wanting to live? Alright. Let's get you back to EverSpring.",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          }
        },
        [51152034] = {
          Camera = "60.732422,-88.369141,149.791992,0.000076,3.860225,27.111778,35.000008,290.0,false,Manual,2.8",
          Content = "百年春？这……",
          DialogueId = 51152034,
          FacialId = {
            [1] = "701088:Nervous"
          },
          GUID = "800DC294",
          SpeakNpcId = 701088,
          Subtitle = "EverSpring...? But—",
          TalkActionId = {
            [1] = "701088:Shock_Start"
          }
        },
        [51152035] = {
          Camera = "244.042969,25.453125,161.979492,0.000076,-9.34042,173.305008,35.000008,111.625343,false,Manual,2.8",
          Content = "想活命的话就少说几句吧。",
          DialogueId = 51152035,
          GUID = "800DC2BE",
          SpeakNpcId = 100001,
          Subtitle = "If you want to live, save your breath.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51152036] = {
          Camera = "-22.400391,-85.114258,115.713867,0.000092,8.260102,28.910444,38.0,357.30426,false,Manual,2.0",
          Content = "是、是……",
          DialogueId = 51152036,
          GUID = "800DC2E8",
          SpeakNpcId = 701088,
          Subtitle = "U—Understood...",
          TalkActionId = {
            [1] = "701088:Shock_End"
          }
        },
        [51152037] = {
          Camera = "204.353516,19.880981,141.953125,0.000018,0.800095,-168.670593,33.0,272.927826,false,Manual,2.8",
          Content = "我、我……",
          DialogueId = 51152037,
          FacialId = {
            [1] = "701088:Grief"
          },
          GUID = "800DC312",
          LookAt = {
            [1] = "100001:n(701088)"
          },
          SpeakNpcId = 701088,
          Subtitle = "I—I...",
          TalkActionId = {
            [1] = "701088:Sigh_Start"
          }
        },
        [51152038] = {
          Camera = "-151.316406,-261.926147,162.417969,0.000048,-3.799989,55.524673,50.0,371.934418,false,Manual,2.5",
          Content = "怎么了？",
          DialogueId = 51152038,
          GUID = "800DC33C",
          LookAt = {
            [1] = "701088:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51152039] = {
          Camera = "204.353516,19.880981,141.953125,0.000018,0.800095,-168.670593,33.0,272.927826,false,Manual,2.8",
          Content = "方前我对止流大人如此出言不逊，她、她还愿意收留我吗……",
          DialogueId = 51152039,
          GUID = "800DC366",
          SpeakNpcId = 701088,
          Subtitle = "Earlier... I spoke out of turn to Miss Zhiliu. Will she really take me in...?",
          TalkActionId = {
            [1] = "701088:Sigh_End"
          }
        },
        [51152040] = {
          Camera = "93.96875,-175.016968,177.651367,0.000065,-8.600068,90.798744,50.0,198.719955,false,Manual,2.5",
          Content = "她先前不过是对你以信仰为由，阻止大家自卫而愤怒。但如今……你已经用双手诚实地做出了选择。",
          DialogueId = 51152040,
          GUID = "800DC390",
          SpeakNpcId = 100001,
          Subtitle = "She was angry because you used faith as an excuse to stop people from defending themselves. But you've made your choice now — and it was the honest one.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51152041] = {
          Camera = "93.96875,-175.016968,177.651367,0.000065,-8.600068,90.798744,50.0,198.719955,false,Manual,2.5",
          Content = "只要你真诚道歉，我想她会谅解的。",
          DialogueId = 51152041,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "800DC3BA",
          SpeakNpcId = 100001,
          Subtitle = "Apologise properly, and I think she'll forgive you.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51152042] = {
          Camera = "350.330078,-275.796265,132.675781,0.000026,0.600155,140.929413,15.794469,336.572845,false,Manual,2.8",
          Content = "……我明白了。",
          DialogueId = 51152042,
          FacialId = {
            [1] = "701088:Nervous"
          },
          GUID = "800DC3E4",
          SpeakNpcId = 701088,
          Subtitle = "...Right. I will.",
          TalkActionId = {
            [1] = "701088:Agree"
          }
        },
        [51152043] = {
          Camera = "350.330078,-275.796265,132.675781,0.000026,0.600155,140.929413,15.794469,336.572845,false,Manual,2.8",
          Content = "想不到我半生的信仰救不了我，最终救了我的竟是这把柴刀……",
          DialogueId = 51152043,
          GUID = "800DC40E",
          SpeakNpcId = 701088,
          Subtitle = "Funny, isn't it...? The faith I clung to for half my life couldn't save me... and this old axe did.",
          TalkActionId = {
            [1] = "701088:Talk02_Start"
          }
        },
        [51152044] = {
          Camera = "69.585938,11.308655,153.422852,0.000016,0.999987,-144.27388,33.0,143.369492,false,Manual,2.8",
          Content = "我会向止流大人致歉……还有，致谢。",
          DialogueId = 51152044,
          FacialId = {
            [1] = "701088:Sad01"
          },
          GUID = "800DC438",
          SpeakNpcId = 701088,
          Subtitle = "I'll apologise to Miss Zhiliu... and thank her, too.",
          TalkActionId = {
            [1] = "701088:Talk02_End"
          }
        },
        [51152045] = {
          Camera = "69.585938,11.308655,153.422852,0.000016,0.999987,-144.27388,33.0,143.369492,false,Manual,2.8",
          Content = "多谢义士一路护送，请收下我的谢礼吧。",
          DialogueId = 51152045,
          GUID = "800DC462",
          SpeakNpcId = 701088,
          Subtitle = "Thank you for getting me back in one piece. Please — take this. A small token of my gratitude.",
          TalkActionId = {
            [1] = "701088:Give"
          }
        },
        [51153001] = {
          Content = "不对味，不对味，这味怎么不对啊？老板，你是不是做了什么手脚。这茶汤与我<H>记忆中的滋味</>分明相差甚远！",
          DialogueId = 51153001,
          GUID = "800E613A",
          SpeakNpcId = 701091,
          Subtitle = "No — this isn't it. Not even close. What did you do to it? It tastes nothing like what I remember."
        },
        [51153002] = {
          Camera = "-408.917969,289.988281,124.88916,-0.0,-4.999999,-26.999968,22.0,556.40625,false,Manual,1.7",
          Content = "这位客人，究竟是哪里不对，哪里味道不一样，你倒是说出个一二来啊？",
          DialogueId = 51153002,
          FacialId = {
            [1] = "701090:CM_Angry01"
          },
          GUID = "800E6164",
          LookAt = {
            [1] = "100001:n(701090)"
          },
          NextDialogue = 51153003,
          SpeakNpcId = 701090,
          Subtitle = "Oh? And what, exactly, is \"wrong\" with it? Go on — spell it out.",
          TalkActionId = {
            [1] = "701090:Angry01_Start"
          }
        },
        [51153003] = {
          Camera = "-22.859375,122.511719,145.754395,0.000026,0.199988,-79.15564,33.0,197.256683,false,Manual,1.78578",
          Content = "你在这里红口白牙瞎说，这不是在砸我的买卖吗！这位白衣服{性别：小兄弟|姑娘}，我看你在这儿站了一阵子了，不然你来评评理？",
          DialogueId = 51153003,
          GUID = "800E618E",
          LookAt = {
            [1] = "701090:n(100001)"
          },
          NextOptions = {
            [1] = 51153004,
            [2] = 51153007
          },
          SpeakNpcId = 701090,
          Subtitle = "You're lying through your teeth! Trying to wreck my business, are you? Hey, you there — {性别：lad|lassie} in white. You've been watching all along. So tell me. Who's in the wrong here?",
          TalkActionId = {
            [1] = "701090:Angry01_End"
          }
        },
        [51153004] = {
          Content = "是不是老板换了原料或工艺，以次充好？",
          DialogueId = 51153004,
          GUID = "800E61B8",
          NextDialogue = 51153005,
          Subtitle = "Did you cut corners? Swap in cheaper ingredients?"
        },
        [51153005] = {
          Camera = "-285.1875,166.675781,127.64502,0.000036,1.399991,-33.151527,50.0,375.0,false,Manual,2.8",
          Content = "你可别瞎说，我这大碗茶，三停茶叶一停花，半银币一大碗，从未变过。",
          DialogueId = 51153005,
          GUID = "800E61E2",
          NextDialogue = 51153006,
          SpeakNpcId = 701090,
          Subtitle = "Don't talk rubbish. Three parts tea, one part flowers. Half a silver coin for a full bowl. That's how it's always been.",
          TalkActionId = {
            [1] = "701090:Talk03_Start"
          }
        },
        [51153006] = {
          Camera = "-285.1875,166.675781,127.64502,0.000036,1.399991,-33.151527,50.0,375.0,false,Manual,2.8",
          Content = "我随老父亲在此处卖了二十年茶水了，从挑着担子卖水起，到今日有两间小铺，从不做偷工减料，以次充好的事！",
          DialogueId = 51153006,
          GUID = "800E620C",
          NextDialogue = 51153009,
          SpeakNpcId = 701090,
          Subtitle = "I've been selling tea here with my old man for twenty years. Started out carrying the pole ourselves — now we've got two little stalls. We've never cut corners. Never swapped in cheap stuff. Not once.",
          TalkActionId = {
            [1] = "701090:Talk03_End"
          }
        },
        [51153007] = {
          Content = "是不是这位顾客故意找茬，白吃白喝？",
          DialogueId = 51153007,
          GUID = "800E6236",
          NextDialogue = 51153008,
          Subtitle = "Is he just picking a fight — trying to scrounge a free drink?"
        },
        [51153008] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "这位小友，我绝非信口开河，你且听我道来。",
          DialogueId = 51153008,
          GUID = "800E6260",
          LookAt = {
            [1] = "100001:n(701091)"
          },
          NextDialogue = 51153009,
          SpeakNpcId = 701091,
          Subtitle = "I assure you, I'm not making this up. Please, hear me out.",
          TurnTo = {
            [1] = "701091:n(100001)",
            [2] = "100001:n(701091)"
          }
        },
        [51153009] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "小友你有所不知，我是一名织星客，常年游历异乡，久不归家。这次在横越沙漠，口干舌燥时，口中突然涌起年幼时曾经尝过的花茶的甘香。",
          DialogueId = 51153009,
          GUID = "800E628A",
          LookAt = {
            [1] = "701091:n(100001)",
            [2] = "100001:n(701091)"
          },
          NextDialogue = 51153010,
          SpeakNpcId = 701091,
          Subtitle = "I'm a Starweaver. I've travelled far from home for many years. This time, crossing the desert parched to the bone, the smell and taste of the flower tea I grew up with came back to me all at once.",
          TalkActionId = {
            [1] = "701091:Talk02_Start"
          }
        },
        [51153010] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "这不，我一回到浮星埠，就奔着这家茶摊来了。可是他家的茶汤却变了味道，令人好不扫兴。",
          DialogueId = 51153010,
          GUID = "800E62B4",
          NextDialogue = 51153011,
          SpeakNpcId = 701091,
          Subtitle = "So the moment I returned to Starwharf, I came straight here. And yet... this bowl is different. It's a disappointment."
        },
        [51153011] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "我记得之前的茶汤，甘冽解渴，花香隐约，只是汤中有碎末这一点不好。如今你这茶，透亮清澈，确不是曾经的茶汤。",
          DialogueId = 51153011,
          GUID = "800E62DE",
          NextDialogue = 51153012,
          SpeakNpcId = 701091,
          Subtitle = "The tea I remember was brisk and refreshing, with a faint floral note. The only trouble was the dregs in the bottom of the bowl. But yours now — clear and bright. It isn't the same tea.",
          TalkActionId = {
            [1] = "701091:Talk02_End"
          }
        },
        [51153012] = {
          Camera = "8.28125,542.140625,129.218262,0.000026,0.999981,-90.554573,50.0,605.407349,false,Manual,2.8",
          Content = "老弟，你这么一说我就明白了。我老父亲年前回家颐养天年，我接手了这家铺子，把之前的碎末子换成了整叶。",
          DialogueId = 51153012,
          FacialId = {
            [1] = "701090:CM_Smile01"
          },
          GUID = "800E6308",
          LookAt = {
            [1] = "100001:n(701090)",
            [2] = "701091:n(701090)",
            [3] = "701090:n(701091)"
          },
          NextDialogue = 51153013,
          SpeakNpcId = 701090,
          Subtitle = "Ah... now I get it. My old man retired before the New Year, and I took over. I stopped using broken leaves and switched to whole ones.",
          TalkActionId = {
            [1] = "701090:Think_Start"
          }
        },
        [51153013] = {
          Camera = "8.28125,542.140625,129.218262,0.000026,0.999981,-90.554573,50.0,605.407349,false,Manual,2.8",
          Content = "我这茶摊卖的不过是解渴的大碗茶，没想到这点差别让你给品出来了。",
          DialogueId = 51153013,
          GUID = "800E6332",
          NextDialogue = 51153014,
          SpeakNpcId = 701090,
          Subtitle = "It's just something to wet the throat... never thought anyone would care enough to notice.",
          TalkActionId = {
            [1] = "701090:Think_End"
          }
        },
        [51153014] = {
          Camera = "141.191406,-101.46875,191.177734,0.000115,-13.600491,142.446793,50.0,284.737152,false,Manual,1.78578",
          Content = "既然误会解开，那我就告……",
          DialogueId = 51153014,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "800E635C",
          LookAt = {
            [1] = "701091:n(100001)"
          },
          NextDialogue = 51153015,
          SpeakNpcId = 100001,
          Subtitle = "Right. If that's cleared up, I'll—",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51153015] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "小友且留步！",
          DialogueId = 51153015,
          GUID = "800E6386",
          LookAt = {
            [1] = "100001:n(701091)",
            [2] = "701091:n(100001)"
          },
          NextDialogue = 51153016,
          SpeakNpcId = 701091,
          Subtitle = "One moment, young friend!",
          TalkActionId = {
            [1] = "701091:Explain02_Start"
          }
        },
        [51153016] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "我今日定要找到旧时茶汤的滋味。百年春客商云集，天下商品无所不有，在那儿一定能找到老板曾经用过的那款茶叶。",
          DialogueId = 51153016,
          GUID = "800E63B0",
          NextDialogue = 51153017,
          SpeakNpcId = 701091,
          Subtitle = "Today, I'm finding that old taste again. One way or another. EverSpring is full of merchants. If anyone still sells the tea I remember, it will be there."
        },
        [51153017] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "不知小友是否愿意随我一同前往。",
          DialogueId = 51153017,
          GUID = "800E63DA",
          NextOptions = {
            [1] = 51153018,
            [2] = 51153020
          },
          SpeakNpcId = 701091,
          Subtitle = "Would you accompany me?",
          TalkActionId = {
            [1] = "701091:Explain02_End"
          }
        },
        [51153018] = {
          Content = "走这一趟也不是不行，有什么好处吗？",
          DialogueId = 51153018,
          GUID = "800E6404",
          ImprPlusId = 1201,
          NextDialogue = 51153019,
          Subtitle = "Maybe. What's in it for me?"
        },
        [51153019] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "如今一路上玄色狴犴猖獗为灾，如能护送我平安抵达百年春，定当重金酬谢！",
          DialogueId = 51153019,
          GUID = "800E642E",
          SpeakNpcId = 701091,
          Subtitle = "Sable Bi'an have been active on the roads of late. See me safely to EverSpring, and you will be well compensated.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153020] = {
          Content = "一路上玄色狴犴泛滥，你是在担心安危吗？",
          DialogueId = 51153020,
          GUID = "800E6458",
          ImprPlusId = 1204,
          NextDialogue = 51153021,
          Subtitle = "With Sable Bi'an everywhere, you're worried about the road, aren't you?"
        },
        [51153021] = {
          Camera = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
          Content = "正是。近来烛阴为灾，我多年未归，先前的道路也不知畅行与否。如能护送我平安抵达百年春，定当重金酬谢！",
          DialogueId = 51153021,
          GUID = "800E6482",
          SpeakNpcId = 701091,
          Subtitle = "Precisely. Zhuyin has been causing trouble of late. I've been away for years — I don't even know whether the old road is still passable. See me safely to EverSpring, and you will be well compensated.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153022] = {
          Content = "经蒹葭浦至浮星埠，我幼时常走这条路去看船，没想到如今它竟变得如此危险。",
          DialogueId = 51153022,
          GUID = "800E64AC",
          NextDialogue = 51153023,
          SpeakNpcId = 701091,
          Subtitle = "This road between Reedshore and Starwharf... I used to walk it all the time as a kid, just to watch the ships at the quay. Never thought it'd turn this dangerous.",
          TalkActionId = {
            [1] = "701091:Think_Start"
          }
        },
        [51153023] = {
          Content = "果然时移世易，不可同日而语。",
          DialogueId = 51153023,
          GUID = "800E64D6",
          NextDialogue = 51153024,
          SpeakNpcId = 701091,
          Subtitle = "How times have changed. And the world with them."
        },
        [51153024] = {
          Content = "我们继续前进吧，百年春就在前面了。",
          DialogueId = 51153024,
          GUID = "800E6500",
          SpeakNpcId = 701091,
          Subtitle = "Come. Let's press on — EverSpring is just ahead.",
          TalkActionId = {
            [1] = "701091:Think_End"
          }
        },
        [51153025] = {
          Camera = "-218.316406,82.341675,107.538086,0.000017,5.878347,-22.685118,60.0,535.899536,false,Manual,2.8",
          Content = "陈老兄，哪阵风把你吹来了。久不见面，这一趟出海还顺利吗？",
          DialogueId = 51153025,
          GUID = "800E652A",
          LookAt = {
            [1] = "701092:n(701091)",
            [2] = "701091:n(701092)",
            [3] = "100001:n(701092)"
          },
          NextDialogue = 51153026,
          SpeakNpcId = 701092,
          Subtitle = "Chen! Well, if it isn't you. It's been ages. How have you been, brother?",
          TalkActionId = {
            [1] = "701092:Talk01_Start"
          }
        },
        [51153026] = {
          Content = "你不在的日子里，兄弟可挂心你了。为了我们一同长大的交情，我好茶好酒都给你留着，就等你回来一同品尝。",
          DialogueId = 51153026,
          GUID = "800E6554",
          NextDialogue = 51153027,
          SpeakNpcId = 701092,
          Subtitle = "We go way back. I've been thinking of you while you were away at sea all these years. I've been saving the best tea and wine for you, waiting for the day you'd come back and share it with me.",
          TalkActionId = {
            [1] = "701092:Talk01_End"
          }
        },
        [51153027] = {
          Camera = "-499.664062,-243.194458,187.458984,0.000042,-8.200284,15.325444,30.0,410.0,false,Manual,2.8",
          Content = "来来来二位请坐，请上座！我好好给你讲讲这些日子里发生的事！",
          DialogueId = 51153027,
          GUID = "800E657E",
          NextDialogue = 51153028,
          SpeakNpcId = 701092,
          Subtitle = "Come on — both of you. Sit. I've got stories for you. You won't believe what's been going on.",
          TalkActionId = {
            [1] = "701092:Explain01_Start"
          }
        },
        [51153028] = {
          Content = "（胡老板滔滔不绝地讲述起了近日的见闻，你和陈白沙只能等待着他回过神来……）",
          DialogueId = 51153028,
          GUID = "800E65A8",
          IsBlack = 1,
          NextDialogue = 51153029,
          SpeakNpcId = 0,
          Subtitle = "(Proprietor Hu launches into an endless stream of gossip and stories. You and Chen Baisha can only wait for him to finally pause for breath...)"
        },
        [51153029] = {
          Camera = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
          Content = "对了老兄，我见到你激动得都忘了，你这趟来是为了什么事？",
          DialogueId = 51153029,
          GUID = "800E65D2",
          NextDialogue = 51153030,
          SpeakNpcId = 701092,
          Subtitle = "Ah... listen to me. I got carried away. So, what brings you here this time, brother?",
          TalkActionId = {
            [1] = "701092:Explain01_End"
          }
        },
        [51153030] = {
          Camera = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
          Content = "我来找一款花茶……",
          DialogueId = 51153030,
          GUID = "800E65FC",
          NextDialogue = 51153031,
          SpeakNpcId = 701091,
          Subtitle = "I'm looking for a particular flower tea that—",
          TalkActionId = {
            [1] = "701091:Explain02_Start"
          }
        },
        [51153031] = {
          Camera = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
          Content = "花茶，那还不容易！伙计们，把最好的端上来！",
          DialogueId = 51153031,
          FacialId = {
            [1] = "701092:CM_Ahaha01"
          },
          GUID = "800E6626",
          NextDialogue = 51153032,
          SpeakNpcId = 701092,
          Subtitle = "Flower tea? That's easy! Lads — bring out the best we've got!",
          TalkActionId = {
            [1] = "701092:Explain02_Start"
          }
        },
        [51153032] = {
          Content = "（伙计们一溜烟地端上了十多款花茶。）",
          DialogueId = 51153032,
          GUID = "800E6650",
          IsBlack = 1,
          NextDialogue = 51153033,
          SpeakNpcId = 0,
          Subtitle = "(His men hurry over, setting down more than a dozen different flower teas in quick succession.)",
          TalkActionId = {
            [1] = "701092:Explain02_End"
          }
        },
        [51153033] = {
          Camera = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
          Content = "陈老兄，你先尝尝这款莲花茶。清晨日未出之时将茶叶置入菡萏中经日，如此反复数次，焙干后，香美异常。",
          DialogueId = 51153033,
          FacialId = {
            [1] = "701092:CM_Smile01"
          },
          GUID = "800E667A",
          NextDialogue = 51153034,
          SpeakNpcId = 701092,
          Subtitle = "Brother Chen, try this lotus tea first. Before sunrise we pack the tea leaves into fresh lotus blossoms, leave them there all day, then do it again — several rounds. After that, we dry and roast the leaves. The fragrance is something else.",
          TalkActionId = {
            [1] = "701092:Give"
          }
        },
        [51153034] = {
          Content = "（陈白沙尝了尝这杯莲花茶。）",
          DialogueId = 51153034,
          GUID = "800E66A4",
          IsBlack = 1,
          NextDialogue = 51153035,
          SpeakNpcId = 0,
          Subtitle = "(Chen Baisha takes a sip of the lotus tea.)"
        },
        [51153035] = {
          Camera = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
          Content = "确实不错，但是……",
          DialogueId = 51153035,
          GUID = "800E66CE",
          NextDialogue = 51153036,
          SpeakNpcId = 701091,
          Subtitle = "It's excellent, no question... but—",
          TalkActionId = {
            [1] = "701091:Explain02_End"
          }
        },
        [51153036] = {
          Camera = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
          Content = "陈老兄，你再尝尝这款茉莉花茶。九窨一提，汤色黄绿明净，花香清雅，滋味清甜，花叶交错，犹如碧潭飘雪。",
          DialogueId = 51153036,
          GUID = "800E66F8",
          NextDialogue = 51153037,
          SpeakNpcId = 701092,
          Subtitle = "Then try this jasmine. Scented nine times. The liquor's a clear yellow-green, the aroma light and refined, and the taste fresh with a gentle sweetness. The flowers and leaves come together like snow on green water.",
          TalkActionId = {
            [1] = "701092:Give"
          }
        },
        [51153037] = {
          Content = "（陈白沙又尝了尝这杯茉莉花茶。）",
          DialogueId = 51153037,
          GUID = "800E6722",
          IsBlack = 1,
          NextDialogue = 51153038,
          SpeakNpcId = 0,
          Subtitle = "(Chen Baisha takes a sip of the jasmine tea.)"
        },
        [51153038] = {
          Camera = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
          Content = "多谢招待，只是……",
          DialogueId = 51153038,
          GUID = "800E674C",
          NextDialogue = 51153039,
          SpeakNpcId = 701091,
          Subtitle = "Much obliged... I—",
          TalkActionId = {
            [1] = "701091:Think_Start"
          }
        },
        [51153039] = {
          Camera = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
          Content = "陈老兄，你再试试这款桂花茶。汤色通透，滋味醇厚，花茶一体，清雅有蜜香。",
          DialogueId = 51153039,
          GUID = "800E6776",
          NextDialogue = 51153040,
          SpeakNpcId = 701092,
          Subtitle = "Alright — osmanthus next. Bright and golden, rich and mellow. It's not tea with osmanthus — the blossom and the tea are one, with a soft fragrance and a honeyed note.",
          TalkActionId = {
            [1] = "701092:Give"
          }
        },
        [51153040] = {
          Content = "（陈白沙只得喝下了这杯桂花茶。）",
          DialogueId = 51153040,
          GUID = "800E67A0",
          IsBlack = 1,
          LookAt = {
            [1] = "701091:n(701091)"
          },
          NextDialogue = 51153041,
          SpeakNpcId = 0,
          Subtitle = "(Chen Baisha has no choice but to down the osmanthus tea.)",
          TalkActionId = {
            [1] = "701091:Think_End"
          }
        },
        [51153041] = {
          Camera = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
          Content = "好茶是好茶，就是……",
          DialogueId = 51153041,
          GUID = "800E67CA",
          NextDialogue = 51153042,
          SpeakNpcId = 701091,
          Subtitle = "It's fine tea, no question... but—",
          TalkActionId = {
            [1] = "701091:Sigh_Start"
          }
        },
        [51153042] = {
          Camera = "48.894531,-6.67627,173.09668,0.000049,-4.600002,-33.478237,50.0,230.0,false,Manual,2.8",
          Content = "不合适，对不对？别急，再尝尝这个！",
          DialogueId = 51153042,
          GUID = "800E67F4",
          SpeakNpcId = 701092,
          Subtitle = "Not quite right, hm? Don't worry — next one!",
          TalkActionId = {
            [1] = "701092:Give"
          }
        },
        [51153043] = {
          Content = "在胡老板热情的招待下，陈白沙一次性喝下了十多杯不同的花茶。",
          DialogueId = 51153043,
          GUID = "800E681E",
          SpeakNpcId = 0,
          Subtitle = "Under Hu's relentless hospitality, Chen Baisha ends up drinking more than a dozen flower teas in one sitting."
        },
        [51153044] = {
          Camera = "205.382812,225.099731,26.811523,0.000026,3.692967,-111.917961,33.0,237.662262,false,Manual,2.8",
          Content = "不……嗝……不行了……我再也喝不下了……",
          DialogueId = 51153044,
          GUID = "800E6848",
          NextDialogue = 51153045,
          SpeakNpcId = 701091,
          Subtitle = "N—No... hic... I can't... I can't drink another drop...",
          TalkActionId = {
            [1] = "701091:Onground01_Loop"
          }
        },
        [51153045] = {
          Camera = "57.484375,110.06665,34.862305,0.0,19.999989,-59.999985,50.000008,327.854492,false,Manual,5.0",
          Content = "怎么样，找到还可入口的没有？",
          DialogueId = 51153045,
          FacialId = {
            [1] = "701092:CM_Smile01"
          },
          GUID = "800E6872",
          LookAt = {
            [1] = "701092:n(701091)"
          },
          NextDialogue = 51153046,
          SpeakNpcId = 701092,
          Subtitle = "Well? Did any of them hit the mark?"
        },
        [51153046] = {
          Camera = "205.382812,225.099731,26.811523,0.000026,3.692967,-111.917961,33.0,237.662262,false,Manual,2.8",
          Content = "我……我……嗝……",
          DialogueId = 51153046,
          FacialId = {
            [1] = "701091:CM_Sad01"
          },
          GUID = "800E689C",
          LookAt = {
            [1] = "701091:n(701092)"
          },
          NextDialogue = 51153047,
          SpeakNpcId = 701091,
          Subtitle = "I... I... hic..."
        },
        [51153047] = {
          Camera = "419.035156,-105.711426,187.561523,0.000082,-9.999806,-178.116913,50.0,398.468353,false,Manual,5.0",
          Content = "我来替他说吧，我们在找二十年前浮星埠茶摊子卖的碎末子。",
          DialogueId = 51153047,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "800E68C6",
          LookAt = {
            [1] = "701092:n(100001)",
            [2] = "100001:n(701092)"
          },
          NextDialogue = 51153048,
          SpeakNpcId = 100001,
          Subtitle = "Let me explain. Mr Chen is looking for the cheap tea they used at a street stall in Starwharf twenty years ago.",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51153048] = {
          Camera = "-133.570312,74.551025,127.095703,0.000084,2.000234,-34.916454,50.0,428.920837,false,Manual,2.8",
          Content = "碎末子？你们找它做什么，又不是什么好东西。",
          DialogueId = 51153048,
          FacialId = {
            [1] = "701092:Curious"
          },
          GUID = "800E68F0",
          NextDialogue = 51153049,
          SpeakNpcId = 701092,
          Subtitle = "Cheap tea? What on earth for? That's just broken leaf. Scraps.",
          TalkActionId = {
            [1] = "701092:Think_Start"
          }
        },
        [51153049] = {
          Camera = "419.035156,-105.711426,187.561523,0.000082,-9.999806,-178.116913,50.0,398.468353,false,Manual,5.0",
          Content = "确实不过是街上摊子卖的大碗茶。只是这位织星客对此念念不忘，一定要找到他所说的“旧时的滋味”不可。",
          DialogueId = 51153049,
          GUID = "800E691A",
          NextDialogue = 51153050,
          SpeakNpcId = 100001,
          Subtitle = "Exactly. Just big bowls of tea from a street stall. But he can't get that old taste out of his head. He's determined to find it again.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          }
        },
        [51153050] = {
          Camera = "57.484375,110.06665,34.862305,0.0,19.999989,-59.999985,50.000008,327.854492,false,Manual,5.0",
          Content = "陈老兄，这些茶里有哪款让你想起以前的滋味的吗？",
          DialogueId = 51153050,
          GUID = "800E6944",
          LookAt = {
            [1] = "701092:n(701091)"
          },
          NextDialogue = 51153051,
          SpeakNpcId = 701092,
          Subtitle = "Well, did any of these bring back what you remember, brother?",
          TalkActionId = {
            [1] = "701092:Think_End"
          }
        },
        [51153051] = {
          Camera = "610.267578,-184.272705,139.628906,0.000035,-9.30713,162.883575,60.0,605.249268,false,Manual,2.8",
          Content = "一次性……嗝……喝太多，分……嗝……不出来了。",
          DialogueId = 51153051,
          FacialId = {
            [1] = "701091:CM_Sad01"
          },
          GUID = "800E696E",
          NextDialogue = 51153052,
          SpeakNpcId = 701091,
          Subtitle = "I... hic... I drank too much, too fast... I can't tell them... hic... apart anymore..."
        },
        [51153052] = {
          Camera = "239.548828,50.161377,163.197266,0.000064,-6.400146,-93.912025,30.0,181.281296,false,Manual,5.0",
          Content = "唉……老兄，让我来替你想想吧。",
          DialogueId = 51153052,
          FacialId = {
            [1] = "701092:CM_Idle"
          },
          GUID = "800E6998",
          NextDialogue = 51153053,
          SpeakNpcId = 701092,
          Subtitle = "...Hah. Alright. Let me think.",
          TalkActionId = {
            [1] = "701092:Talk01_Start"
          }
        },
        [51153053] = {
          Camera = "664.539062,942.744019,270.186523,0.000074,-7.000185,72.683929,11.0,327.854492,false,DoNotOverride,5.0",
          Content = "二十年前，我们俩都还是在蒹葭浦的河滩上赤着脚玩泥巴的野孩子。",
          DialogueId = 51153053,
          FinalCamera = "664.539062,942.744019,270.186523,-0.0,-7.000185,109.999985,11.000002,327.854492,false,DoNotOverride,5.0",
          GUID = "800E69C2",
          NextDialogue = 51153054,
          SpeakNpcId = 701092,
          Subtitle = "Twenty years ago, the two of us were still barefoot brats, down on the Reedshore riverbank, splashing in the mud.",
          ToFinalCameraBlendTime = 10
        },
        [51153054] = {
          Content = "没想到二十年过去，一个往西，一个往东，好几年也见不上一面。",
          DialogueId = 51153054,
          GUID = "800E69EC",
          NextDialogue = 51153055,
          SpeakNpcId = 701092,
          Subtitle = "And who would've thought... twenty years later, we'd go our separate ways and barely cross paths at all?"
        },
        [51153055] = {
          Content = "时光飞逝，有什么味道是永久不变的呢……",
          DialogueId = 51153055,
          GUID = "800E6A16",
          NextDialogue = 51153056,
          SpeakNpcId = 701092,
          Subtitle = "Time flies. What ever stays the same? Even tea doesn't taste like it used to..."
        },
        [51153056] = {
          Camera = "388.880859,100.010376,1.513672,0.00003,10.692913,-163.316513,38.0,306.638,false,Manual,2.8",
          Content = "我……我知道了！",
          DialogueId = 51153056,
          FacialId = {
            [1] = "701091:CM_Shock01"
          },
          FinalCamera = "208.158203,45.84729,37.138672,0.00003,10.692913,-163.316513,38.0,117.599663,false,Manual,2.8",
          GUID = "800E6A40",
          NextDialogue = 51153057,
          SpeakNpcId = 701091,
          Subtitle = "I... I've got it!",
          ToFinalCameraBlendTime = 0.2
        },
        [51153057] = {
          Content = "（陈白沙迅速地从地上爬了起来，目光炯炯地看着你。）",
          DialogueId = 51153057,
          GUID = "800E6A6A",
          IsBlack = 1,
          NextDialogue = 51153058,
          SpeakNpcId = 0,
          Subtitle = "(Chen Baisha scrambles to his feet, eyes suddenly bright as he turns to you.)",
          TalkActionId = {
            [1] = "701091:Idle"
          }
        },
        [51153058] = {
          Camera = "172.066406,36.535034,156.958008,0.000033,-6.107124,-151.715576,30.0,185.0,false,Manual,2.8",
          Content = "{nickname}小友……",
          DialogueId = 51153058,
          FacialId = {
            [1] = "701091:CM_Smile01"
          },
          GUID = "800E6A94",
          LookAt = {
            [1] = "701091:n(100001)",
            [2] = "100001:n(701091)"
          },
          NextOptions = {
            [1] = 51153059,
            [2] = 51153061
          },
          SpeakNpcId = 701091,
          Subtitle = "My friend...",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51153059] = {
          Content = "来都来了，就帮忙帮到底吧。",
          DialogueId = 51153059,
          GUID = "800E6ABE",
          ImprPlusId = 1204,
          NextDialogue = 51153060,
          Subtitle = "Well... I've come this far. Might as well see it through."
        },
        [51153060] = {
          Camera = "37.376953,-174.963745,129.658203,0.000059,3.999984,87.884972,30.000002,191.158386,false,Manual,2.8",
          Content = "多谢小友，等我尝到那旧日花茶，必有重谢！",
          DialogueId = 51153060,
          GUID = "800E6AE8",
          SpeakNpcId = 701091,
          Subtitle = "Thank you, my friend. Once I find that flower tea and taste it again, you will be well rewarded.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153061] = {
          Content = "再让我跑腿就要收费了！",
          DialogueId = 51153061,
          GUID = "800E6B12",
          ImprPlusId = 1201,
          NextDialogue = 51153062,
          Subtitle = "Pull another trip like this, and I'll be charging extra."
        },
        [51153062] = {
          Camera = "37.376953,-174.963745,129.658203,0.000059,3.999984,87.884972,30.000002,191.158386,false,Manual,2.8",
          Content = "一定一定，绝不亏待！",
          DialogueId = 51153062,
          GUID = "800E6B3C",
          SpeakNpcId = 701091,
          Subtitle = "Of course. Of course! I'll make it worth your while.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153063] = {
          Content = "你端着一壶茶来这儿，就是你说的……好主意？",
          DialogueId = 51153063,
          GUID = "800E6B66",
          NextDialogue = 51153064,
          SpeakNpcId = 100001,
          Subtitle = "So this is your \"brilliant idea\"? Bringing a whole teapot out here?"
        },
        [51153064] = {
          Content = "哈哈，我想明白了。既然想要找那时的味道，自然也要重现当时的情境不是。",
          DialogueId = 51153064,
          GUID = "800E6B90",
          NextDialogue = 51153065,
          SpeakNpcId = 701091,
          Subtitle = "Ha. I've realised what I was missing. If I want that taste back, I need the moment that came with it.",
          TalkActionId = {
            [1] = "701091:Talk01_Start"
          }
        },
        [51153065] = {
          Content = "那时我整日在这片河滩上狂奔，兴许等我跑得渴了累了，就能找到当时的味道了。",
          DialogueId = 51153065,
          GUID = "800E6BBA",
          NextDialogue = 51153066,
          SpeakNpcId = 701091,
          Subtitle = "Back then I used to run up and down this riverbank until I was parched. Maybe if I run myself dry again, the taste will come back."
        },
        [51153066] = {
          Content = "小友不妨和我来比试一番。",
          DialogueId = 51153066,
          GUID = "800E6BE4",
          SpeakNpcId = 701091,
          Subtitle = "Would you humour me and race me?",
          TalkActionId = {
            [1] = "701091:Talk01_End"
          }
        },
        [51153067] = {
          Content = "二十年没在这片河滩上跑过了，今天真是过瘾！",
          DialogueId = 51153067,
          GUID = "800E6C0E",
          SpeakNpcId = 701091,
          Subtitle = "Twenty years on... and it still feels the same!"
        },
        [51153068] = {
          Content = "嘿咻……有点跟不上了……",
          DialogueId = 51153068,
          GUID = "800E6C38",
          SpeakNpcId = 701091,
          Subtitle = "Huff... huff... I can't... keep up..."
        },
        [51153069] = {
          Content = "呼……呼……自愧不如！自愧不如！",
          DialogueId = 51153069,
          GUID = "800E6C62",
          SpeakNpcId = 701091,
          Subtitle = "Hah... hah... I'm done for! You win!"
        },
        [51153070] = {
          Content = "（陈白沙大口将茶水灌进了口里，随即累得倒下了。）",
          DialogueId = 51153070,
          GUID = "800E6C8C",
          IsBlack = 1,
          NextDialogue = 51153071,
          SpeakNpcId = 0,
          Subtitle = "(Chen Baisha drains the tea in great gulps, then drops to the ground, utterly spent.)",
          TalkActionId = {
            [1] = "701091:Onground01_Loop"
          }
        },
        [51153071] = {
          Camera = "82.539062,236.600586,94.693359,0.000013,-1.542742,-109.15033,38.0,410.739655,false,Manual,2.8",
          Content = "是你想找的滋味吗？",
          DialogueId = 51153071,
          FacialId = {
            [1] = "100001:Curious"
          },
          GUID = "800E6CB6",
          LookAt = {
            [1] = "100001:n(701091)"
          },
          NextDialogue = 51153072,
          SpeakNpcId = 100001,
          Subtitle = "So? Was that the taste you were after?",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51153072] = {
          Camera = "225.349609,-183.40332,129.71582,0.000022,-14.342556,161.450195,38.0,362.946472,false,Manual,2.8",
          Content = "有八分像了，还有两分差在哪里呢……",
          DialogueId = 51153072,
          GUID = "800E6CE0",
          LookAt = {
            [1] = "701091:n(100001)"
          },
          NextDialogue = 51153073,
          SpeakNpcId = 701091,
          Subtitle = "So close... But it's not quite there. Something's still missing."
        },
        [51153073] = {
          Camera = "225.349609,-183.40332,129.71582,0.000022,-14.342556,161.450195,38.0,362.946472,false,Manual,2.8",
          Content = "我记得……记得……",
          DialogueId = 51153073,
          GUID = "800E6D0A",
          LookAt = {
            [1] = "701091:n(701091)"
          },
          NextDialogue = 51153074,
          SpeakNpcId = 701091,
          Subtitle = "I remember..."
        },
        [51153074] = {
          Camera = "82.539062,236.600586,94.693359,0.000013,-1.542742,-109.15033,38.0,410.739655,false,Manual,2.8",
          Content = "你回想起了什么？",
          DialogueId = 51153074,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "800E6D34",
          NextDialogue = 51153075,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:TilteHead_Start",
            [2] = "100001:ConfidentLRToExplainL_Start"
          }
        },
        [51153075] = {
          Camera = "-105.767578,-54.1875,3088.036133,0.0,12.999988,42.650269,11.0,362.946472,false,DoNotOverride,2.8",
          Content = "我想起十数年前，蒹葭浦还没犯烛阴之灾的日子。我和伙伴一同在河滩上玩泥沙、磨螺壳的时候。",
          DialogueId = 51153075,
          FinalCamera = "-2100.933594,-1892.0625,2461.760742,0.0,12.999988,42.650452,11.000002,362.946472,false,DoNotOverride,2.8",
          GUID = "800E6D5E",
          NextDialogue = 51153076,
          SpeakNpcId = 701091,
          Subtitle = "It's those days I'm thinking of. Before the Scourge of Zhuyin ever reached this place. Back when my friends and I played in the mud here, polishing shells by the river.",
          ToFinalCameraBlendTime = 10
        },
        [51153076] = {
          Content = "我想起那时也是这样的天，白云悠悠从头顶飘过。似乎永无烦恼，永无忧虑。",
          DialogueId = 51153076,
          GUID = "800E6D88",
          NextDialogue = 51153077,
          SpeakNpcId = 701091,
          Subtitle = "White clouds drifting lazily overhead... as if we'd never known worry.",
          TalkActionId = {
            [1] = "100001:TilteHead_End"
          }
        },
        [51153077] = {
          Content = "是从什么时候开始，我决定当一名织星客的呢……又是从什么时候开始，我们各奔东西，各自万里未归，异乡为客的呢……",
          DialogueId = 51153077,
          GUID = "800E6DB2",
          NextDialogue = 51153078,
          SpeakNpcId = 701091,
          Subtitle = "When did I decide to become a Starweaver? And when did we start to drift apart? One by one, we ended up far from home... year after year."
        },
        [51153078] = {
          Camera = "0.871094,-16.166992,127.25293,0.000021,-6.342841,-89.151169,38.000008,179.802216,false,Manual,2.8",
          Content = "你最早喝到这碗茶，是在什么时候？",
          DialogueId = 51153078,
          GUID = "800E6DDC",
          NextDialogue = 51153079,
          SpeakNpcId = 100001,
          Subtitle = "When did you first drink that bowl of tea?",
          TalkActionId = {
            [1] = "100001:ConfidentLRToExplainL_End"
          }
        },
        [51153079] = {
          Camera = "7466.974609,-3541.548828,3565.794922,0.0,-6.200104,-34.800346,11.0,362.946472,false,DoNotOverride,2.8",
          Content = "我年幼时，有一次父亲带着我，沿着蒹葭浦走去浮星埠看船。路途遥远，我累极了，也兴奋极了。",
          DialogueId = 51153079,
          FinalCamera = "10758.478516,-5829.231445,3130.332031,0.0,-6.200104,-34.800346,11.0,362.946472,false,DoNotOverride,2.8",
          GUID = "800E6E06",
          NextDialogue = 51153080,
          SpeakNpcId = 701091,
          Subtitle = "When I was young, my father took me on foot along the riverbank — from Reedshore all the way to Starwharf — just to watch the ships. It was a long walk. I was exhausted, and buzzing with excitement.",
          ToFinalCameraBlendTime = 10
        },
        [51153080] = {
          Content = "我们在茶摊喝茶，不远处的大海波光粼粼，商船穿梭往来，码头上人声喧哗，还是孩子的我，一下被这场景所深深吸引。",
          DialogueId = 51153080,
          GUID = "800E6E30",
          NextDialogue = 51153081,
          SpeakNpcId = 701091,
          Subtitle = "We bought tea from a stall. The sea glittered nearby. Merchant ships came and went. The quay was buzzing. I was a wide-eyed boy... I couldn't look away.",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          }
        },
        [51153081] = {
          Content = "也许从第一次见到大海起，就注定了我未来会远远地离开这片土地，走到天涯海角去。",
          DialogueId = 51153081,
          GUID = "800E6E5A",
          NextDialogue = 51153082,
          SpeakNpcId = 701091,
          Subtitle = "Maybe it began there. The first time I saw the sea. The first time I knew I'd one day go beyond this land... all the way to the ends of the world."
        },
        [51153082] = {
          Content = "但是再一次见到这片天空，还是会感慨万千啊……",
          DialogueId = 51153082,
          GUID = "800E6E84",
          NextDialogue = 51153083,
          SpeakNpcId = 701091,
          Subtitle = "And yet... coming back under this same sky still catches in my throat."
        },
        [51153083] = {
          Content = "（陈白沙默然不语，在地上躺了好一会儿，似乎在深思些什么。）",
          DialogueId = 51153083,
          GUID = "800E6EAE",
          IsBlack = 1,
          NextDialogue = 51153084,
          SpeakNpcId = 0,
          Subtitle = "(Chen Baisha falls silent. He lies there for a long while, staring up at the sky, lost in thought.)",
          TalkActionId = {
            [1] = "701091:Idle"
          }
        },
        [51153084] = {
          Camera = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
          Content = "小友，我明白了。",
          DialogueId = 51153084,
          GUID = "800E6ED8",
          LookAt = {
            [1] = "701091:n(100001)"
          },
          NextDialogue = 51153085,
          SpeakNpcId = 701091,
          Subtitle = "My friend... I understand now.",
          TalkActionId = {
            [1] = "701091:Explain02_Start"
          }
        },
        [51153085] = {
          Camera = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
          Content = "再也不会有和从前一模一样的茶叶的味道了，就像不会有和从前一样的日子。",
          DialogueId = 51153085,
          GUID = "800E6F02",
          NextDialogue = 51153086,
          SpeakNpcId = 701091,
          Subtitle = "There'll never be tea that tastes the way it did back then... just as there'll never be days like those again."
        },
        [51153086] = {
          Camera = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
          Content = "我所怀念的不过是逝去的岁月，和再也回不去的小时候。",
          DialogueId = 51153086,
          GUID = "800E6F2C",
          NextDialogue = 51153087,
          SpeakNpcId = 701091,
          Subtitle = "It isn't the tea I miss. It's those days... and the childhood I can't return to.",
          TalkActionId = {
            [1] = "701091:Explain02_End"
          }
        },
        [51153087] = {
          Camera = "-58.130859,194.003906,181.458984,0.000058,-9.342407,-86.547867,30.0,228.692245,false,Manual,2.8",
          Content = "再见了，小友，这些报酬你请收好。",
          DialogueId = 51153087,
          GUID = "800E6F56",
          LookAt = {
            [1] = "701091:n(701091)"
          },
          NextDialogue = 51153088,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"701091:p(-180)"}},   PlayAnimation{ActorId{100001},AnimationId{"RaiseHand_Start"}}
}]],
          SpeakNpcId = 701091,
          Subtitle = "Farewell, my friend. Please — take this. You've earned it."
        },
        [51153088] = {
          Camera = "18.898438,5.989258,151.822266,0.000043,-13.742524,-94.34774,30.0,192.427872,false,Manual,2.8",
          Content = "你要去哪里？",
          DialogueId = 51153088,
          FacialId = {
            [1] = "100001:Curious"
          },
          GUID = "800E6F80",
          NextDialogue = 51153089,
          SpeakNpcId = 100001,
          Subtitle = "Where are you going?",
          TalkActionId = {
            [1] = "100001:RaiseHand_End"
          }
        },
        [51153089] = {
          Camera = "-104.441406,157.805664,256.822266,0.000024,-24.942291,-76.543663,50.0,400.0,false,Manual,2.8",
          Content = "已经过去的不可再追回，现在的一切尚在手中。",
          DialogueId = 51153089,
          FinalCamera = "-104.441406,157.805664,256.822266,0.000024,-24.942291,-76.543663,50.0,210.0,false,Manual,2.8",
          GUID = "800E6FAA",
          NextDialogue = 51153090,
          SpeakNpcId = 701091,
          Subtitle = "You can't take back what's gone. But there are things I can still hold on to.",
          TalkActionId = {
            [1] = "701091:Disagree"
          },
          ToFinalCameraBlendTime = 5
        },
        [51153090] = {
          Content = "我已经喝不到二十年前的茶了，但是我现在仍然能和我的父亲一起散步、谈天说地、走去港口看船。",
          DialogueId = 51153090,
          GUID = "800E6FD4",
          NextDialogue = 51153091,
          SpeakNpcId = 701091,
          Subtitle = "I may never find that tea from twenty years ago again... but I can still walk with my father, talk as we go, and watch the ships at the quay with him."
        },
        [51153091] = {
          Camera = "609.125,169.490234,2.267578,0.0,7.999989,-155.538208,34.0,720.492676,false,Manual,2.8",
          Content = "我要回家了。",
          DialogueId = 51153091,
          GUID = "800E6FFE",
          SpeakNpcId = 701091,
          Subtitle = "I'm going home.",
          TalkActionId = {
            [1] = "701091:Explain02_Start"
          }
        },
        [51153092] = {
          Content = "如今的浮星埠，比二十年前父亲带我来看船时更加热闹了。",
          DialogueId = 51153092,
          GUID = "800E6FFF",
          SpeakNpcId = 701098,
          Subtitle = "Starwharf's even livelier now than it was back then. Hard to believe it's been twenty years since you first brought me here to watch the ships, Father."
        },
        [51153093] = {
          Content = "二十年过去，这里也成了你出发的地方了……",
          DialogueId = 51153093,
          GUID = "800E7000",
          SpeakNpcId = 701099,
          Subtitle = "Twenty years on... and now this is where your journey begins as well."
        },
        [51153094] = {
          Content = "小友，还是我略胜一筹！",
          DialogueId = 51153094,
          GUID = "800E7001",
          SpeakNpcId = 701091,
          Subtitle = "It seems, young friend, that I am still one move ahead."
        },
        [51154001] = {
          Content = "我就知道你会再来找我。",
          DialogueId = 51154001,
          GUID = "800F054A",
          NextOptions = {
            [1] = 51154002,
            [2] = 51154003
          },
          SpeakNpcId = 701096,
          Subtitle = "I had a feeling you'd return."
        },
        [51154002] = {
          Content = "说吧，还有什么事。",
          DialogueId = 51154002,
          GUID = "800F0574",
          ImprPlusId = 1208,
          NextDialogue = 51154004,
          Subtitle = "Go on, then. What is it?"
        },
        [51154003] = {
          Content = "你笑得太恶心了，到底还想说什么。",
          DialogueId = 51154003,
          GUID = "800F059E",
          ImprPlusId = 1210,
          NextDialogue = 51154004,
          Subtitle = "Drop the creepy smile. Spit it out."
        },
        [51154004] = {
          Content = "不用如此戒备，既然提到投资，自然是要再为你提供一些切实的便利。",
          DialogueId = 51154004,
          GUID = "800F05C8",
          NextDialogue = 51154005,
          SpeakNpcId = 701096,
          Subtitle = "No need to be so on edge. Since we're talking investments, it's only fitting I offer you something... a little more practical."
        },
        [51154005] = {
          Content = "小友且看我这件藏品。",
          DialogueId = 51154005,
          GUID = "800F05F2",
          NextDialogue = 51154006,
          SpeakNpcId = 701096,
          Subtitle = "Come. Let me show you a piece from my collection."
        },
        [51154006] = {
          Content = "玄色狴犴！",
          DialogueId = 51154006,
          GUID = "800F061C",
          NextDialogue = 51154007,
