          DialogueId = 60140005,
          Duration = 4,
          GUID = "968DDF92",
          Subtitle = "Tremble!",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_01"
        },
        [60140006] = {
          ContentES = "¡No creas que puedes escapar!",
          DialogueId = 60140006,
          Duration = 4,
          GUID = "968DDFBC",
          Subtitle = "Don't think you can get away!",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_02"
        },
        [60140201] = {
          ContentES = "¡Aléjate... de mí...!",
          DialogueId = 60140201,
          Duration = 4,
          GUID = "968DFFBA",
          Subtitle = "...Stay away... from me...!",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleStart"
        },
        [60140202] = {
          ContentES = "Sí... no merezco... vivir...",
          DialogueId = 60140202,
          Duration = 6,
          GUID = "968DFFE4",
          Subtitle = "Right... I don't deserve... to live...",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageStart"
        },
        [60140203] = {
          ContentES = "¡Aaah—!",
          DialogueId = 60140203,
          Duration = 4,
          GUID = "968E000E",
          Subtitle = "Aargh—",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageEnd"
        },
        [60140204] = {
          ContentES = "¡Uaaahhh—!",
          DialogueId = 60140204,
          Duration = 4,
          GUID = "968E0038",
          Subtitle = "Aaaaargh—",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_Condemn"
        },
        [60140205] = {
          ContentES = "Gracias...",
          DialogueId = 60140205,
          Duration = 5,
          GUID = "968E0062",
          Subtitle = "Thank you...",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleEnd"
        },
        [60140206] = {
          ContentES = "...Aaah...",
          DialogueId = 60140206,
          Duration = 2,
          GUID = "968E008C",
          Subtitle = "...Ahhh...",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill03"
        },
        [60140207] = {
          ContentES = "...¡Corre... por favor...!",
          DialogueId = 60140207,
          Duration = 4,
          GUID = "968E00B6",
          Subtitle = "...Run... please...!",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill10"
        },
        [60140401] = {
          ContentES = "Mi queridísima hija, gracias por venir a este mundo.",
          DialogueId = 60140401,
          Duration = 4,
          GUID = "968E208A",
          Subtitle = "My dearest child, thank you for coming into the world.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E208A"
        },
        [60140402] = {
          ContentES = "Eres el orgullo de nuestras vidas.",
          DialogueId = 60140402,
          Duration = 3,
          GUID = "968E20B4",
          Subtitle = "You are the pride of our lives.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20B4"
        },
        [60140403] = {
          ContentES = "¡Psyche, ven! ¡Juremos con nuestros meñiques que seremos amigas para toda la vida!",
          DialogueId = 60140403,
          Duration = 4,
          GUID = "968E20DE",
          Subtitle = "Psyche, pinky promise. We'll be best friends for life!",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20DE"
        },
        [60140404] = {
          ContentES = "Recordaré que de verdad viviste en este mundo.",
          DialogueId = 60140404,
          Duration = 3,
          GUID = "968E2108",
          Subtitle = "I'll remember that you've lived in this world.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2108"
        },
        [60140405] = {
          ContentES = "Te esperaremos... hasta tu regreso.",
          DialogueId = 60140405,
          Duration = 2.5,
          GUID = "968E2132",
          Subtitle = "We'll wait for your return.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2132"
        },
        [60140406] = {
          ContentES = "Oh, destino... solo por esta vez, ten piedad de mí. Déjame ayudarla a cumplir este deseo...",
          DialogueId = 60140406,
          Duration = 6,
          GUID = "968E215C",
          Subtitle = "Fate, please have mercy on me. Let me help her fulfil this wish.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E215C"
        },
        [60140407] = {
          ContentES = "Lleva contigo esta flor. Te traerá buena suerte.",
          DialogueId = 60140407,
          Duration = 3,
          GUID = "968E2186",
          Subtitle = "Take this flower with you. It will bring you good luck.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2186"
        },
        [60140408] = {
          ContentES = "Irás a una pequeña isla, donde podrás construir una casa junto al mar y plantar flores blancas a su alrededor.",
          DialogueId = 60140408,
          Duration = 6,
          GUID = "968E21B0",
          Subtitle = "You'll go to a small island, where you can build a house by the sea and grow white flowers around it.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21B0"
        },
        [60140409] = {
          ContentES = "Psyche, estoy aquí para llevarte a casa.",
          DialogueId = 60140409,
          Duration = 3,
          GUID = "968E21DA",
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21DA"
        },
        [60140501] = {
          ContentES = "Todos los veredictos son en nombre de la justicia.",
          DialogueId = 60140501,
          Duration = 5,
          GUID = "968E30F2",
          Subtitle = "All verdicts are in the name of justice.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleStart"
        },
        [60140502] = {
          ContentES = "¡Cómo te atreves a desafiar la ley…!",
          DialogueId = 60140502,
          Duration = 5,
          GUID = "968E311C",
          Subtitle = "How dare you defy the law...",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_condemn"
        },
        [60140503] = {
          ContentES = "Tú… te has demostrado frente a la llama ardiente.",
          DialogueId = 60140503,
          Duration = 5,
          GUID = "968E3146",
          Subtitle = "You... have proved yourself in the face of fiery flame.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd"
        },
        [60140504] = {
          ContentES = "Presenta tus últimas súplicas.",
          DialogueId = 60140504,
          Duration = 5,
          GUID = "968E3170",
          Subtitle = "Present your final pleas.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01"
        },
        [60140505] = {
          ContentES = "Retorcerte patéticamente no retrasará tu sentencia.",
          DialogueId = 60140505,
          Duration = 5,
          GUID = "968E319A",
          Subtitle = "Writhing pathetically won't delay your sentence.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02"
        },
        [60140506] = {
          ContentES = "Encuentra tu final entre estas cadenas.",
          DialogueId = 60140506,
          Duration = 5,
          GUID = "968E31C4",
          Subtitle = "Meet your demise within these chains.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01"
        },
        [60140507] = {
          ContentES = "La ley relatará tus crímenes.",
          DialogueId = 60140507,
          Duration = 5,
          GUID = "968E31EE",
          Subtitle = "The law shall recount your crimes.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02"
        },
        [60140508] = {
          ContentES = "No hay escape del alcance del infierno.",
          DialogueId = 60140508,
          Duration = 5,
          GUID = "968E3218",
          Subtitle = "No escape from the inferno's grasp.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill03"
        },
        [60149001] = {
          ContentES = "¡A-a-a-alta las manos! Uf, {性别:ese|esa} parece fuerte… ¡Me voy de aquí!",
          DialogueId = 60149001,
          Duration = 5,
          GUID = "9693A37A",
          SpeakNpcId = 920001,
          Subtitle = "H...H...H...H...Hands in the air! Ooh, this one looks tough... I'm outta here.",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r01"
        },
        [60149002] = {
          Content = "可恶！怎么是你，再再再见。",
          DialogueId = 60149002,
          Duration = 3.8,
          GUID = "9693A3A4",
          SpeakNpcId = 920001,
          Subtitle = "Argh, not you again! H...H...H...Have a nice day, bye!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r02"
        },
        [60149003] = {
          Content = "留留留下买路财！啧，怎么今天一上来就碰到硬茬子，告辞。",
          DialogueId = 60149003,
          Duration = 6.7,
          GUID = "9693A3CE",
          SpeakNpcId = 920001,
          Subtitle = "Y...Y...Your money or your life...! Gosh! How am I supposed to mug a walkin' arsenal? See ya!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r03"
        },
        [60149004] = {
          Content = "除了打劫，逃跑我也是专业的！",
          DialogueId = 60149004,
          Duration = 3.5,
          GUID = "9693A3F8",
          SpeakNpcId = 920001,
          Subtitle = "Tell you what, I also major in escapin'!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill01"
        },
        [60149005] = {
          Content = "舍不得孩子套不着狼，这些都给你，别再追啦！",
          DialogueId = 60149005,
          Duration = 5.1,
          GUID = "9693A422",
          SpeakNpcId = 920001,
          Subtitle = "Luno who mugs and runs away, lives to mug another day! Just take these and lemme scarper!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill02"
        },
        [60149006] = {
          Content = "咋还在追我啊，这个给你行了吧。",
          DialogueId = 60149006,
          Duration = 3.5,
          GUID = "9693A44C",
          SpeakNpcId = 920001,
          Subtitle = "Ugh, just take that and lemme off the hook!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill03"
        },
        [60149007] = {
          Content = "你使那么大劲干啥呢！",
          DialogueId = 60149007,
          Duration = 2.5,
          GUID = "9693A476",
          SpeakNpcId = 920001,
          Subtitle = "Oww! That hurt!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01"
        },
        [60149008] = {
          Content = "可恶，以后走夜路小心点！",
          DialogueId = 60149008,
          Duration = 3.2,
          GUID = "9693A4A0",
          SpeakNpcId = 920001,
          Subtitle = "Ugh, this is not over! Better watch your back at night!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02"
        },
        [60149009] = {
          Content = "啊啊啊啊啊，我要生气了！",
          DialogueId = 60149009,
          Duration = 3.4,
          GUID = "9693A4CA",
          SpeakNpcId = 920001,
          Subtitle = "RAAAARGH!! Now I'm mad!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03"
        },
        [60149010] = {
          Content = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
          DialogueId = 60149010,
          Duration = 6,
          GUID = "9693A4F4",
          SpeakNpcId = 920001,
          Subtitle = "You ju...ju...jumbo dumbo are too stupid to catch me! HYA-HYA-HYA!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill04"
        },
        [60149011] = {
          Content = "这次是我大意了，下次我一定要把你打得抱头大哭，呜……",
          DialogueId = 60149011,
          Duration = 10.4,
          GUID = "9693A51E",
          SpeakNpcId = 920001,
          Subtitle = "I've mucked it all up! You'll get yours next time — just you wait! Boohoo...",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_death"
        },
        [60149012] = {
          Content = "东西南北四条街，打听打听谁是爹，道上谁不知道我打劫皎皎的名号！",
          DialogueId = 60149012,
          Duration = 6.9,
          GUID = "9693A548",
          SpeakNpcId = 920001,
          Subtitle = "North, south, east and west! I'm your pappy and I'm da best! Ask around and you will know, give your money to this Luno!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r01"
        },
        [60149013] = {
          Content = "跟我斗，你还是太年轻了呀~",
          DialogueId = 60149013,
          Duration = 5.7,
          GUID = "9693A572",
          SpeakNpcId = 920001,
          Subtitle = "Hah, tenderfoot! You're gettin' pawned!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r02"
        },
        [60149014] = {
          Content = "哼，我打打打劫皎皎可不是好惹的。",
          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          Subtitle = "Hmph, this Lulu Lunoloot is not someone you can mess with!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
          Content = "呼，呼……你咋还不累呢，吃啥玩意长大的啊。",
          DialogueId = 60149015,
          Duration = 8.8,
          GUID = "9693A5C6",
          SpeakNpcId = 920001,
          Subtitle = "Huff... huff... Ain't you tired yet? What did they feed you?",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r04"
        },
        [60150001] = {
          ContentES = "¡Aléjate!",
          DialogueId = 60150001,
          Duration = 3,
          GUID = "9694478A",
          SpeakNpcId = 200053,
          Subtitle = "Back off!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01"
        },
        [60150002] = {
          ContentES = "¡Tú lo pediste!",
          DialogueId = 60150002,
          Duration = 3,
          GUID = "969447B4",
          SpeakNpcId = 200053,
          Subtitle = "You asked for this!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02"
        },
        [60150003] = {
          ContentES = "No puedo correr más... me rindo...",
          DialogueId = 60150003,
          Duration = 5,
          GUID = "969447DE",
          SpeakNpcId = 200053,
          Subtitle = "I can't run any further... I surrender...",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [60150004] = {
          ContentES = "¡Ríndete!",
          DialogueId = 60150004,
          Duration = 3,
          GUID = "96944808",
          SpeakNpcId = 200053,
          Subtitle = "Give it up!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01"
        },
        [60150005] = {
          ContentES = "¡Deja de seguirme!",
          DialogueId = 60150005,
          Duration = 3,
          GUID = "96944832",
          SpeakNpcId = 200053,
          Subtitle = "Quit it!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02"
        },
        [60150006] = {
          ContentES = "¡No me atraparás!",
          DialogueId = 60150006,
          Duration = 4,
          GUID = "9694485C",
          SpeakNpcId = 200053,
          Subtitle = "No way you can catch me!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03"
        },
        [60160001] = {
          Content = "开启锯轮攻击！（待包装）",
          DialogueId = 60160001,
          Duration = 4,
          GUID = "969AB02A",
          SpeakNpcId = 920001
        },
        [60160002] = {
          Content = "持续轰炸目标！（待包装）",
          DialogueId = 60160002,
          Duration = 4,
          GUID = "969AB054",
          SpeakNpcId = 920001
        },
        [60160003] = {
          Content = "列车，提速，狂暴模式！！（待包装）",
          DialogueId = 60160003,
          Duration = 4,
          GUID = "969AB07E",
          SpeakNpcId = 920001
        },
        [60160004] = {
          Content = "连锁型-炸弹攻击！（待包装）",
          DialogueId = 60160004,
          Duration = 4,
          GUID = "969AB0A8",
          SpeakNpcId = 920001
        },
        [60160005] = {
          Content = "追踪型-炸弹攻击！（待包装）",
          DialogueId = 60160005,
          Duration = 4,
          GUID = "969AB0D2",
          SpeakNpcId = 920001
        },
        [60170001] = {
          ContentES = "¡Muere... MUEREEEE!",
          DialogueId = 60170001,
          Duration = 1.5,
          GUID = "96A118CA",
          Subtitle = "Die... DIIIEEE!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01"
        },
        [60170002] = {
          ContentES = "¡Raaagh... Ughhh... AAAARRRGH!",
          DialogueId = 60170002,
          Duration = 1.5,
          GUID = "96A118F4",
          Subtitle = "Raaagh... Ughhh... AAAARRRGH!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill06"
        },
        [60170003] = {
          ContentES = "GRRRRR... Rugido... ¡RUGIDOOOO!",
          DialogueId = 60170003,
          Duration = 4,
          GUID = "96A1191E",
          Subtitle = "GRRRRR... Roar... ROOOAAAR!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill08"
        },
        [60180001] = {
          ContentES = "¡Que cualquiera que se acerque sea fulminado por el juicio de los cielos!",
          DialogueId = 60180001,
          Duration = 3,
          GUID = "9834E965",
          Subtitle = "Draw nigh, and be smitten by divine ire!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleStart"
        },
        [60180002] = {
          ContentES = "¡GRRRR!",
          DialogueId = 60180002,
          Duration = 3,
          GUID = "9834E966",
          Subtitle = "GRRRAAAUGH!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Condemn"
        },
        [60180003] = {
          ContentES = "Todo... es nada.",
          DialogueId = 60180003,
          Duration = 3,
          GUID = "9834E967",
          Subtitle = "All... is naught.",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleEnd"
        },
        [60180004] = {
          ContentES = "Las tinieblas caen sobre este mundo.",
          DialogueId = 60180004,
          Duration = 4,
          GUID = "9834E968",
          Subtitle = "Behold... the world's eve falleth.",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill05"
        },
        [60180005] = {
          ContentES = "Las sombras rugen, el trueno despierta...",
          DialogueId = 60180005,
          Duration = 5,
          GUID = "9834E969",
          Subtitle = "Heavens doth blacken, thunder rolls damnation!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill06"
        },
        [60180006] = {
          ContentES = "\n¡ROOOAAAR—!",
          DialogueId = 60180006,
          Duration = 3,
          GUID = "9834E970",
          Subtitle = "ROOOAAAR—!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill07"
        },
        [60200101] = {
          ContentES = "¡Oh, no! ¡El enemigo nos ha detectado!",
          DialogueId = 60200101,
          Duration = 4,
          GUID = "96B46312",
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh, we've been spotted by the enemy!",
          VoiceName = "voice/$Locale$/story/0/602001/96B46312",
          bTurnOffVoice = true
        },
        [60200201] = {
          ContentES = "¡Enemigos avistados! ¡Impídelos de pedir refuerzos!",
          DialogueId = 60200201,
          Duration = 4,
          GUID = "96B4737A",
          SpeakNpcId = 200002,
          Subtitle = "Enemies in sight; stop them before they call for backup.",
          VoiceName = "voice/$Locale$/story/0/602002/96B4737A",
          bTurnOffVoice = true
        },
        [60200301] = {
          ContentES = "¡Cuidado, van a avisar a sus aliados! Si no lo evitamos, la situación se complicará mucho.",
          DialogueId = 60200301,
          Duration = 4,
          GUID = "96B483E2",
          SpeakNpcId = 200002,
          Subtitle = "Watch out, the enemy's about to call for backup! Things will get sticky if we don't nip this in the bud.",
          VoiceName = "voice/$Locale$/story/0/602003/96B483E2",
          bTurnOffVoice = true
        },
        [60200401] = {
          ContentES = "¡Van a llamar refuerzos! ¡Rápido, encuentra una forma de impedirlo!",
          DialogueId = 60200401,
          Duration = 4,
          GUID = "96B4944A",
          SpeakNpcId = 200002,
          Subtitle = "They're going to call for backup! Do something! Now!",
          VoiceName = "voice/$Locale$/story/0/602004/96B4944A",
          bTurnOffVoice = true
        },
        [60200501] = {
          ContentES = "¡Argh, nos habíamos escondido tan bien! Qué pena, tendremos que eliminarlos rápidamente.",
          DialogueId = 60200501,
          Duration = 4,
          GUID = "96B4A4B2",
          SpeakNpcId = 200002,
          Subtitle = "Ugh, thought we hid well. Eh, let's sort them out quickly.",
          VoiceName = "voice/$Locale$/story/0/602005/96B4A4B2",
          bTurnOffVoice = true
        },
        [60210101] = {
          ContentES = "El cliente solo nos compró un poco de tiempo, ¡así que vamos a destruir esas cosas raras antes de que sea demasiado tarde!",
          DialogueId = 60210101,
          Duration = 4,
          GUID = "9687C88C",
          SpeakNpcId = 200002,
          Subtitle = "The client's only bought us a teeny bit of time — so let's bust those weird-looking thingies before it's too late!",
          VoiceName = "voice/$Locale$/story/0/602101/9687C88C",
          bTurnOffVoice = true
        },
        [60210201] = {
          ContentES = "¡Yupi! ¡Todo desmantelado! ¡Encargo cumplido!",
          DialogueId = 60210201,
          Duration = 3,
          GUID = "9687C892",
          SpeakNpcId = 200002,
          Subtitle = "Yay! All down! Commission accomplished~!",
          VoiceName = "voice/$Locale$/story/0/602102/9687C892",
          bTurnOffVoice = true
        },
        [60210301] = {
          ContentES = "¡El cliente dice que el tiempo se acabó! ¡A retirarse, rápido!",
          DialogueId = 60210301,
          Duration = 3,
          GUID = "9687C896",
          SpeakNpcId = 200002,
          Subtitle = "The client says time's up! Let's get out of here before it gets messy!",
          VoiceName = "voice/$Locale$/story/0/602103/9687C896",
          bTurnOffVoice = true
        },
        [60220101] = {
          ContentES = "¡Espera, ¿qué?! ¿La primera partida ya está comenzando?",
          DialogueId = 60220101,
          Duration = 4,
          GUID = "9687C89A",
          NextDialogue = 60220102,
          SpeakNpcId = 200002,
          Subtitle = "Wait, what, the first match is starting already?",
          VoiceName = "voice/$Locale$/story/0/602201/9687C89A",
          bTurnOffVoice = true
        },
        [60220102] = {
          ContentES = "A ver… ¡Nuestra primera misión es eliminar al jugador estrella del equipo “Los Decepcionados”!",
          DialogueId = 60220102,
          Duration = 3,
          GUID = "9687C89E",
          NextDialogue = 60220103,
          SpeakNpcId = 200002,
          Subtitle = "Let me see… Our first task is to eliminate the star player of the \"The Fork Shakens\" team!",
          VoiceName = "voice/$Locale$/story/0/602201/9687C89E",
          bTurnOffVoice = true
        },
        [60220103] = {
          ContentES = "¡Pero ni siquiera sabemos dónde se esconden! ¡Rápido, busquemos pistas!",
          DialogueId = 60220103,
          Duration = 3,
          GUID = "9687C8A2",
          SpeakNpcId = 200002,
          Subtitle = "But we've no idea where the others are hiding! Let's look around for clues.",
          VoiceName = "voice/$Locale$/story/0/602201/9687C8A2",
          bTurnOffVoice = true
        },
        [60220201] = {
          ContentES = "¡Sabemos dónde está escondido su jugador estrella! ¡Vamos a derrotarlo, ups, quiero decir, a eliminarlo!",
          DialogueId = 60220201,
          Duration = 3,
          GUID = "9687C8A6",
          SpeakNpcId = 200002,
          Subtitle = "We know where their star player is hiding! Let's go defeat — oops, I mean eliminate them!",
          VoiceName = "voice/$Locale$/story/0/602202/9687C8A6",
          bTurnOffVoice = true
        },
        [60220301] = {
          ContentES = "¡La próxima ronda parece ser una batalla territorial! ¡Démonos prisa!",
          DialogueId = 60220301,
          Duration = 3,
          GUID = "9687C8AA",
          SpeakNpcId = 200002,
          Subtitle = "The next round seems to be a territory battle! Let's hurry over!",
          VoiceName = "voice/$Locale$/story/0/602203/9687C8AA",
          bTurnOffVoice = true
        },
        [60220401] = {
          ContentES = "¡Expúlsenlos de la zona designada! ¡La victoria será nuestra, “El Comandante es el mejor”!",
          DialogueId = 60220401,
          Duration = 4,
          GUID = "9687C8AE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Drive them out of the designated zone! Victory will surely belong to us, \"Chief's the Best\"!",
          VoiceName = "voice/$Locale$/story/0/602204/9687C8AE",
          bTurnOffVoice = true
        },
        [60220501] = {
          ContentES = "El orgullo de la Legión recae sobre sus hombros.",
          DialogueId = 60220501,
          Duration = 4,
          GUID = "9687C8B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "The pride of the legion rests on you.",
          VoiceName = "voice/$Locale$/story/0/602205/9687C8B2",
          bTurnOffVoice = true
        },
        [60220601] = {
          ContentES = "¡Argh... ¡Qué resistencia! Es hora de pelear en serio.",
          DialogueId = 60220601,
          Duration = 4,
          GUID = "9687C8B6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Ugh, they're so stubborn! Guess it's time to get serious.",
          VoiceName = "voice/$Locale$/story/0/602206/9687C8B6",
          bTurnOffVoice = true
        },
        [60220701] = {
          ContentES = "Aunque hayamos perdido... ¡la próxima ronda será nuestra!",
          DialogueId = 60220701,
          Duration = 3,
          GUID = "9687C8BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Even though we lost… there's still next round! We still have a chance!",
          VoiceName = "voice/$Locale$/story/0/602207/9687C8BA",
          bTurnOffVoice = true
        },
        [60220801] = {
          ContentES = "¡Por fin! ¡La tercera ronda! ¡Rápido, al cofre! ¡No vamos a dejar que alguien más lo tome!",
          DialogueId = 60220801,
          Duration = 4,
          GUID = "9687C8BE",
          SpeakNpcId = 200002,
          Subtitle = "Finally, the third match! Quick, to the prize chest, we can't let anyone else grab it!",
          VoiceName = "voice/$Locale$/story/0/602208/9687C8BE",
          bTurnOffVoice = true
        },
        [60220901] = {
          ContentES = "¡Ya está, comienza! ¡Recoge las llaves de estos tipos y abre el cofre final!",
          DialogueId = 60220901,
          Duration = 3,
          GUID = "9687C8C2",
          NextDialogue = 60220902,
          SpeakNpcId = 200002,
          Subtitle = "It's starting now! Snatch the keys back from these guys and unlock the final treasure chest!",
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C2",
          bTurnOffVoice = true
        },
        [60220902] = {
          ContentES = "¡Herejes! ¿Cómo osáis codiciar un tesoro bendecido por los dioses? ¡Preparad para enfrentar Su ira!",
          DialogueId = 60220902,
          Duration = 4,
          GUID = "9687C8C4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          Subtitle = "Heretics! How dare you covet treasures bestowed by the gods. Ready to face divine wrath?",
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C4",
          bTurnOffVoice = true
        },
        [60221001] = {
          ContentES = "¡Adelante, fieles servidores! ¡Cosechad el fruto de la victoria en Su nombre!",
          DialogueId = 60221001,
          Duration = 4,
          GUID = "9687C8C6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          Subtitle = "Go, devout followers! Pluck the fruit of victory in Its name.",
          VoiceName = "voice/$Locale$/story/0/602210/9687C8C6",
          bTurnOffVoice = true
        },
        [60221101] = {
          ContentES = "¡Por la gloria de la Legión! ¡Adelante!",
          DialogueId = 60221101,
          Duration = 4,
          GUID = "9687C8CA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "For the glory of the legion, advance!",
          VoiceName = "voice/$Locale$/story/0/602211/9687C8CA",
          bTurnOffVoice = true
        },
        [60221201] = {
          ContentES = "Como se esperaba... la tercera ronda es la más decisiva. ¡Es nuestro momento para brillar!",
          DialogueId = 60221201,
          Duration = 4,
          GUID = "9687C8CE",
          SpeakNpcId = 930004,
          Subtitle = "Just as I predicted — the third match is where it really counts. Now, it's our time to shine!",
          VoiceName = "voice/$Locale$/story/0/602212/9687C8CE",
          bTurnOffVoice = true
        },
        [60221301] = {
          ContentES = "¡Una cerradura abierta! ¡Sigamos, podemos abrir las otras!",
          DialogueId = 60221301,
          Duration = 3,
          GUID = "9687C8D2",
          SpeakNpcId = 200002,
          Subtitle = "One lock opened! Keep it up, we can get the rest too!",
          VoiceName = "voice/$Locale$/story/0/602213/9687C8D2",
          bTurnOffVoice = true
        },
        [60221401] = {
          ContentES = "¡El cofre está abierto, ¡yupi! ¡Somos los vencedores!",
          DialogueId = 60221401,
          Duration = 3,
          GUID = "9687C8D6",
          SpeakNpcId = 200002,
          Subtitle = "The chest is open, yayyy! We won!",
          VoiceName = "voice/$Locale$/story/0/602214/9687C8D6",
          bTurnOffVoice = true
        },
        [60221501] = {
          ContentES = "¡Mira, mira! ¡La organización acaba de lanzar una nueva llave en la arena!",
          DialogueId = 60221501,
          Duration = 4,
          GUID = "9687C8DA",
          SpeakNpcId = 200002,
          Subtitle = "Look, look over there! The organizers just threw a new key into the arena!",
          VoiceName = "voice/$Locale$/story/0/602215/9687C8DA",
          bTurnOffVoice = true
        },
        [60221601] = {
          ContentES = "¡Por la gloria de la Legión! ¡Adelante!",
          DialogueId = 60221601,
          Duration = 4,
          GUID = "9687C8DE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930005,
          Subtitle = "For the glory of the legion, advance!",
          VoiceName = "voice/$Locale$/story/0/602216/9687C8DE",
          bTurnOffVoice = true
        },
        [60230101] = {
          ContentES = "¡Rápido, encuentra la Estación de pociones!",
          DialogueId = 60230101,
          Duration = 4,
          GUID = "96910001",
          SpeakNpcId = 200002,
          Subtitle = "Hurry, let's find the Potion Station!",
          VoiceName = "voice/$Locale$/story/0/602301/96910001",
          bTurnOffVoice = true
        },
        [60230201] = {
          ContentES = "¡Ah, sí, lo recuerdo! ¡Para que la Estación de pociones recupere el Suero, tenemos que derrotar a los enemigos cerca de ella!",
          DialogueId = 60230201,
          Duration = 4,
          GUID = "96910029",
          NextDialogue = 60230202,
          SpeakNpcId = 200002,
          Subtitle = "Oh yeah! To make the station collect the serum, we gotta defeat enemies near it!",
          VoiceName = "voice/$Locale$/story/0/602302/96910029",
          bTurnOffVoice = true
        },
        [60230202] = {
          ContentES = "¡Llena la Estación de pociones para completar el encargo! ¡Vamos!",
          DialogueId = 60230202,
          Duration = 4,
          GUID = "96910191",
          SpeakNpcId = 200002,
          Subtitle = "Fill up the Potion Station to complete the commission! Go, go, go!",
          VoiceName = "voice/$Locale$/story/0/602302/96910191",
          bTurnOffVoice = true
        },
        [60230301] = {
          ContentES = "Shh... He escuchado ruidos extraños... ¡Parece que un monstruo grande se acerca por aquí!",
          DialogueId = 60230301,
          Duration = 4,
          GUID = "96910321",
          SpeakNpcId = 200002,
          Subtitle = "Shh… I hear something weird, sounds like a big guy's coming!",
          VoiceName = "voice/$Locale$/story/0/602303/96910321",
          bTurnOffVoice = true
        },
        [60230401] = {
          ContentES = "¡Uaaaah! ¡Un monstruo gigante corre hacia nosotros escupiendo un Humo tóxico! Si lo dejamos hacer, ¡corromperá todo el Suero en la Estación de pociones! ¡Rápido, elimínalo!",
          DialogueId = 60230401,
          Duration = 4,
          GUID = "969104B1",
          SpeakNpcId = 200002,
          Subtitle = "Whoaaa, a huge thing is charging over with Toxic Smog! It'll corrupt all the serum in the station! Take it down, quick!",
          VoiceName = "voice/$Locale$/story/0/602304/969104B1",
          bTurnOffVoice = true
        },
        [60300101] = {
          ContentES = "Shh... ¡Creo que escuché el llanto de un Geniemon! ¡Vamos a rescatarlo!",
          DialogueId = 60300101,
          Duration = 4,
          GUID = "96F47952",
          SpeakNpcId = 200002,
          Subtitle = "Shh... I think I heard the crying of a Geniemon! Let's go rescue it!",
          VoiceName = "voice/$Locale$/story/0/603001/96F47952",
          bTurnOffVoice = true
        },
        [60800101] = {
          Content = "没有钥匙……在附近找找看吧。",
          DialogueId = 60800101,
          Duration = 5,
          GUID = "9834E892",
          SpeakNpcId = 100001,
          Subtitle = "A chest key needed... Look around to seek one."
        },
