        [70010100] = {
          Camera = "6426.663086,7746.713379,-121.966454,0.253341,0.343415,-129.197754,35.0,350.0,false,Manual,2.8",
          Content = "TalkMechanism测试",
          DialogueId = 70010100,
          GUID = "AF435008",
          SpeakNpcId = 10201
        },
        [70010101] = {
          Camera = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
          Content = "近日岛上秽兽日渐活跃，所有居民准备好船只与物资，随时准备出海避险。",
          DialogueId = 70010101,
          Duration = 5,
          GUID = "AF435032",
          SpeakNpcId = 102011,
          Subtitle = "Recently, the Filthoids on the island have become increasingly active. All residents are preparing boats and supplies, ready to set sail and escape at any time."
        },
        [70010201] = {
          Camera = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
          Content = "居民谨记，为了避免海伯利亚官员发现我们，出海捕鱼时远离不明船只。\n祖辈为了避免卷入无谓的战争逃到这里，相信他们的智慧，严守告诫。",
          DialogueId = 70010201,
          Duration = 5,
          GUID = "AF43609A",
          SpeakNpcId = 102012,
          Subtitle = [[
Residents, remember to stay away from unidentified ships when fishing at sea to avoid being detected by the Hyperborean authorities. 
 Our ancestors fled here to avoid getting involved in meaningless wars. We must adhere to their ways.]]
        },
        [70010301] = {
          Camera = "-364.107666,1506.973633,120.13916,0.000131,13.391685,87.755157,18.0,100000.0,false,Manual,18.0",
          Content = "村民们应该早已乘船逃离秽兽肆虐的村子，而远处的“天之树”正是他们出海的天然灯塔。",
          DialogueId = 70010301,
          Duration = 5,
          GUID = "AF437102",
          SpeakNpcId = 102013,
          Subtitle = "The villagers must've fled the Filthoid-ravaged village by now. The distant \"Heaventree\" serves as their natural lighthouse when out at sea."
        },
        [70010401] = {
          Camera = "-564.918457,-24.525635,71.417542,0.000015,34.991844,0.800468,18.0,1932.963745,false,Manual,2.8",
          Content = "从未见过的雕像，供奉着不知姓名的神明，不知是什么时代的遗物……",
          DialogueId = 70010401,
          Duration = 5,
          GUID = "AF43816A",
          SpeakNpcId = 102014,
          Subtitle = "A never-before-seen statue, dedicated to an unnamed deity. It's an artefact from an unknown era..."
        },
        [70010501] = {
          Camera = "-33.021576,347.337158,98.72699,0.000062,6.798647,-91.995422,18.0,100000.0,false,Manual,2.8",
          Content = "用剑刃刻下的铭文，只能辨认其中部分内容：\n……\n格里昂尼亚的加拉斯随布伦丹将军远征至此，将伪教艾利西安的盲信徒尽数驱逐。\n……\n尽一切可能毁去伪神的痕迹。\n……\n虽然想要留守于此，但岛屿贫瘠，不知能否常驻。\n……",
          DialogueId = 70010501,
          Duration = 5,
          GUID = "AF4391D2",
          SpeakNpcId = 102015,
          Subtitle = [[
Some inscriptions have been carved into it with a blade. Only some of the content is discernible: 
 ...
Gralenia's Galas accompanied General Brendan's expeditionary forces here, expelling all the blind followers of the false goddess, Elysia. 
 ...
Do everything you can to erase all traces of the false god. 
 ...
Although I wish to remain here, the island is barren, so I don't think I can stay here permanently. 
 ...]]
        },
        [70010601] = {
          Camera = "-1111.150024,-564.398438,447.803864,0.000071,30.199543,17.596375,15.0,100000.0,false,Manual,2.8",
          Content = "从巨大的雕像与两侧悬崖边缘残余的建筑来看，很久以前，这里应该是一处神庙。",
          DialogueId = 70010601,
          Duration = 5,
          GUID = "AF43A23A",
          SpeakNpcId = 102016,
          Subtitle = "Judging from the huge statue and the ruined buildings at the edge of the cliff, it appears that this place was once a temple a long time ago."
        },
        [70010701] = {
          Camera = "507.757812,-5157.005371,-457.544922,0.000083,-13.799645,-41.00135,20.0,511.06842,false,Manual,2.8",
          Content = "秽兽的残骸，余温尚存。可见不久之前，这里发生过一场交战。",
          DialogueId = 70010701,
          Duration = 5,
          GUID = "AF43B2A2",
          SpeakNpcId = 102017,
          Subtitle = "The remains of a Filthoid. Its lingering warmth proves that there was a fierce battle here not long ago."
        },
        [70010801] = {
          Camera = "454.451172,-463.453125,534.632812,0.000046,-15.999574,138.796616,15.0,100000.0,false,Manual,8.0",
          Content = "彩绘的神像，虽然保持完好，但是周围的断壁残垣显示着很久以前，这里曾经发生过一次彻底的劫掠。",
          DialogueId = 70010801,
          Duration = 5,
          GUID = "AF43C30A",
          SpeakNpcId = 102018,
          Subtitle = "The painted statue, though well-preserved, is surrounded by ruins, indicating that this place was looted a long time ago."
        },
        [70010901] = {
          Camera = "-742.34668,128.554199,307.391235,0.000063,-10.999725,71.996475,15.0,100000.0,false,Manual,2.8",
          Content = "似乎是用来炼金的装置，不知为何出现在神庙遗迹里。",
          DialogueId = 70010901,
          Duration = 5,
          GUID = "AF43D372",
          SpeakNpcId = 102019,
          Subtitle = "It appears to be an alchemical device, but it's unclear why it's in these temple ruins."
        },
        [70011001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.8",
          ContentES = "Una foto tomada hace más de diez años. El cristal del marco está cubierto de huellas dactilares. En la foto, una chica Charon sonriente, con el viento acariciando su cabello.\n\nEn la parte de atrás, escrito con pluma fuente:\n“Mi hija — Hayley. Tomada en Río Escarlata.”\n\nNo se parece realmente a Psyche, pero sin embargo... su sonrisa clara evoca irresistiblemente su recuerdo.",
          DialogueId = 70011001,
          Duration = 5,
          GUID = "AF43E3DA",
          SpeakNpcId = 102020,
          Subtitle = "An old photograph, taken more than a decade ago. The glass is clouded with fingerprints. In the picture, a Charon girl smiles softly as the breeze toys with her hair.\n\nOn the back, written in fountain pen:\n\"My daughter — Hayley. Taken in Scarletriver.\"\n\nShe doesn't much resemble Psyche... and yet, something in that innocent smile calls her to mind all the same."
        },
        [70011101] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "（高大的档案柜，按字母顺序井然有序地排列着“住客”的档案。每份档案除了孩子的照片，还清楚地记着孩子们在修普诺斯之家度过的每一天。）\n\n赛琪的档案\n年龄：17\n症状：失明，失聪\n赛琪来的时候已是秽蚀中期，但她还是坚强、热情地向每个人打招呼。我多么希望诊断的结果是错误的，这样我还能欺骗自己，赛琪并没有出现秽蚀，她的人生还能回到正轨。\n……\n她将父母来看望时送的花都放在床头，连落脚和睡觉的地方都被压缩得很小很小。\n……\n我把二楼的空房收拾了出来，那边采光更好，赛琪和她的花搬进去以后应该能待得更舒适一些。\n……\n她真的很喜欢花，每天仔细地打理花束，再分发给其他孩子们，如果不是因为秽蚀，她将来一定能将“牵念之花”打理得比她父母还要出色。\n……\n赛琪今天给我也送了支花，看着她恬静的笑脸，我仿佛又见到了你……海莉……\n……\n我看着账本发愁的样子不小心被赛琪看到了，她缠着我询问原因，我拗不过她，如实将修普诺斯之家财政上的问题说给了她听。\n（批注：我得尽快给收购者回信，不能再让孩子们担心下去了。）\n……\n赛琪把老宅打扫了出来，还顺势租给个来路不明的小鬼……希望那个小鬼别给修普诺斯之家惹来什么麻烦。\n……\n<H>她说想要活下去，哪怕能以人类的身份再多活一天也好，听到这句话时我既欣慰又愤怒。\n欣慰是因为她终于吐露了心声，她以看淡生死的样子强撑太久了。\n愤怒是因为那个小鬼！我不知道那个小鬼对赛琪做了什么，但给必死之人活下去的勇气，太过残忍了。\n如果无法拯救，那就不要给予无意义的希望！\n……\n（批注：但如果这是赛琪的愿望……我得加快抑制秽蚀手术的研究了。为了赛琪，为了孩子们。）</>",
          DialogueId = 70011101,
          Duration = 5,
          GUID = "AF43F442",
          SpeakNpcId = 102021,
          Subtitle = "(Tall file cabinets, neatly arranged in alphabetical order, hold the files of the \"lodgers.\" Each file, besides a photo of the child, clearly documents every day the children spent at the Hypnos' House.)\n\nPsyche's Profile\nAge: 17\nSymptoms: Blindness, Deafness\n\nWhen Psyche arrived, her Deterioration had already progressed to the mid-stage. Yet, she greeted everyone with such warmth. I wish I could believe the diagnosis was wrong — that she wasn't suffering from Deterioration, and that her life could somehow get back on track.\n...\nShe keeps the flowers her parents brought her by her bedside, even though it leaves her barely any space to sleep or even stand.\n...\nI cleared out a better-lit room on the second floor. Hopefully, Psyche and her flowers will be more comfortable there.\n...\nShe really loves flowers. Every day, she tends to them with care and shares them with the other children. If it weren't for the shadow of Deterioration, she would have taken care of Flower of Solicitude even better than her parents ever did.\n...\nToday, Psyche gave me a flower too. Her peaceful smile reminded me of you, Hayley...\n...\nPsyche saw me frowning over the finances today and wouldn't stop pestering me until I told her about Hypnos' House's financial struggles.\n(Note: Must reply to the buyer soon. Can't let the children keep worrying about this.)\n...\nPsyche cleaned out the old house and even rented it to some kid with a shady background... I just hope that kid doesn't stir up trouble for Hypnos' House.\n...\nShe told me she wished to live longer as a human — even if just for one more day. I was both relieved and furious to hear that.\nI felt relieved because Psyche finally opened up. She's been putting on a brave face and acting like she doesn't care about life or death for far too long.\nI felt furious because of that blasted kid! I don't know what that little rascal said to her, but giving false hope to someone who's destined to leave the world soon — that's the cruellest thing one could do.\n...\n(Note: But if that's what Psyche wants... I must speed up the research on the anti-Deterioration drug... For Psyche, and for other kids.)"
        },
        [70011201] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "艾克的档案\n年龄：19\n症状：失明\n艾克是独自来修普诺斯之家的，不知道他的父母是不忍心看到孩子的结局，还是单纯的狠心。居然任由一个盲人独自来到冰湖城。\n……\n他说想看书，但我这里只有无趣冗长的医学典籍，即使这样他也没有嫌弃。我读着书，他坐在一旁听，就这样度过了一天。\n……\n我听到艾克在梦里呼唤他父亲的名字。\n……\n我在弗莱格桑行省找到了艾克的父亲，他没注意到我，只是专注地哼着摇篮曲，哄着他怀里的人族婴儿入睡。\n……\n我去买了些用盲文撰写的书，艾克开心地说谢谢父亲，我本想告诉他我不是，但最后只能艰难地嗯了一声然后匆匆离开了病房。\n……",
          DialogueId = 70011201,
          Duration = 5,
          GUID = "AF4404AA",
          SpeakNpcId = 102022,
          Subtitle = [[
Ike's Profile
Age: 19
Symptom: Blindness

Ike came to the Hypnos' House alone. It's unclear whether his parents couldn't bear to see his fate or were simply heartless. They just let a blind kid come to Icelake by himself.
...
He said he wanted to read books, but all I had were dull, lengthy medical books. Even so, he didn't mind. So I read while he sat there listening, and that's how we spent the day.
...
I heard Ike calling for his father in his dreams.
...
I found Ike's father in the Flagson Province, but he didn't notice me. He was just focused on humming a lullaby to the sola baby in his arms.
...
I bought some books written in Braille. Ike was so happy. "Thank you, Father", he said. I wanted to tell him I wasn't his father, but in the end, I could only manage a strained "Mm" and hurried out of the ward.
...]]
        },
        [70011301] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "罗比的档案\n年龄：18\n症状：成骨不全\n罗比被送到修普诺斯之家的时候浑身缠满了绷带，轻微的磕碰就可能引起严重的骨折，甚至连下床都很困难。\n……\n我把他的床位挪到了窗边，这样他可以多晒晒太阳。\n……\n康复训练很成功，莱娜女士的料理给罗比的身体提供了足够的营养，现在他可以拄着拐杖在修普诺斯之家走走了。\n……\n今天罗比的腿又骨折了，比来得时候还要严重。为了不给我添麻烦居然从楼梯上摔下来都不愿大声喊叫……看来我最近确实太憔悴了，害得孩子们反过来担心我。\n……\n他想出去采朵花作为赛琪的回礼，我同意了。虽然我们最后只捡到几根枯枝，但他还是笑得很开心。\n……",
          DialogueId = 70011301,
          Duration = 5,
          GUID = "AF441512",
          SpeakNpcId = 102023,
          Subtitle = [[
Robie's Profile
Age: 18
Symptom: Osteogenesis Imperfecta

When Robie was sent to the Hypnos' House, he was wrapped in bandages from head to toe. Even the slightest bump could cause a severe fracture, and even getting out of bed was a struggle for him.
...
I moved his bed to the window so he could get more sunlight.
...
The rehabilitation training was a success. Lady Lina's cooking provided Robie with enough nutrition, and now he can walk around the Hypnos' House with a cane.
...
Today, Robie's leg fractured again, even more severely than when he arrived. He fell down the stairs but didn't want to cause me any trouble, so he didn't even cry out... Looks like I've been too haggard recently, making the kids start worrying about me.
...
He wanted to go out and pick a flower as a return gift for Psyche, and I agreed. Although we only found a few dry branches in the end, he still smiled happily.
...]]
        },
        [70011401] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          Content = "约瑟芬的档案\n年龄：17\n症状：脏器变形，呼吸困难\n她的秽蚀印记出现在脖子上，看着她跑上跑下活泼的样子，我反而有种不好的预感。\n……\n她突然跌倒在地喘着粗气，全身检查的结果很不理想，脏器出现了严重变形，接下来几天她都只能待在手术室了。\n……\n她的状态好些了，但还是离不开呼吸器，为了不让她在睡觉时出事，我必须每晚守在她的床边为她扶稳呼吸器，擦去冷汗。好在咖啡的储备足够，我还撑得住。\n……",
          DialogueId = 70011401,
          Duration = 5,
          GUID = "AF44257A",
          SpeakNpcId = 102024,
          Subtitle = [[
Josephine's Profile
Age: 17
Symptoms: Organ Deformation, Difficult Breathing

Her Deterioration mark appeared on her neck. Seeing her running around so energetically, I actually got a bad feeling.
...
She suddenly collapsed, gasping for breath. The results of her full-body check-up were not good at all, saying her organs were severely deformed. She had to stay in the operating room for the next few days.
...
Her condition improves a bit, but she still can't do without the respirator. To make sure nothing happened to her while she's sleeping, I have to stay by her bedside every night to hold the respirator steady and wipe away her cold sweat. Fortunately, there is still enough coffee to keep me going.
...]]
        },
        [70011501] = {
          Camera = "589.100586,92.850586,87.400391,0.000028,0.0,-178.390396,22.0,400.0,false,DoNotOverride,2.8",
          Content = "受恶劣天气影响，城外第一公路发生严重侧翻事故。目前第六军团下属卫戍部队已展开抢修工作，请广大市民减少外出，出行时做好防滑措施。",
          DialogueId = 70011501,
          Duration = 5,
          GUID = "AF4435E2",
          SpeakNpcId = 102025,
          Subtitle = "Due to adverse weather conditions, a major rollover accident has occurred on the primary highway outside the city. The 6th Legion's Escort is currently undertaking emergency repair work. Residents are advised to minimise travel and take necessary anti-slip measures when venturing out."
        },
        [70011601] = {
          Camera = "-83.132812,-721.489746,92.419189,0.000006,-0.600217,80.994888,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "紧闭的大门切断了人们进入矿场的道路，耳旁传来冰冷的机械音，断断续续地重复着当年矿坑被封禁时的通知……\n月石矿脉枯竭……即日起列为废弃状态……工程炼金院不再提供安全保障……强行进入出现意外，概不负责……",
          DialogueId = 70011601,
          Duration = 5,
          GUID = "AF44464A",
          SpeakNpcId = 102026,
          Subtitle = [[
The jammed gate has severed access to the pit. A cold, mechanical voice intermittently repeats the notice issued when the pit was closed. 

The Phoxene veins have been depleted... Effective immediately, the pit is designated as abandoned...
The Legion will no longer ensure security in this area... 
Individuals assume all responsibility for any incidents resulting from unauthorised entry...]]
        },
        [70011701] = {
          Content = "冰冷的机械音反复重复着军团转移矿工时的通知。\n第六军团驻扎部队将护送名单中的矿工转移至弗莱格桑行省继续从事相关工作。\n转移列车将于格雷姆矿场关闭前三小时准时发车，请名单中的各位矿工谨记以下注意事项：\n1、随身携带物品超过五公斤者，枪决\n2、不在规定时间乘车者，枪决\n3、对名单有疑问者，枪决",
          DialogueId = 70011701,
          Duration = 5,
          GUID = "AF4456B2",
          SpeakNpcId = 102027,
          Subtitle = [[
A cold, mechanical voice relentlessly repeats the Legion's relocation instructions for miners. 

The 6th Legion's Garrison will escort miners on the list for relocation to the Flagson Province for continued labour. The transfer train will depart precisely three hours before the closure of Glevum Pit. Miners on the list must observe the following: 
1. Those carrying over five kilograms of personal belongings will face execution.
2. Those failing to board at the designated time will face execution.
3. Those questioning the list will face execution.]]
        },
        [70011801] = {
          Camera = "-415.066528,-79.582031,152.246094,0.000006,0.599875,-0.799286,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "上了年头的老旧合照，记录着水仙平原开业时的盛况，平民、富商甚至是一些内城的官员都围聚在这里，为这家年轻的店铺献上最美好的祝福。",
          DialogueId = 70011801,
          Duration = 5,
          GUID = "AF44671A",
          SpeakNpcId = 102028,
          Subtitle = "(A yellowed photo capturing the grand opening of The Asphodel. Commoners, merchant princes and even some officials from the inner city gathered here to offer their best wishes to this newly opened tavern.)"
        },
        [70011901] = {
          Camera = "-652.218567,-446.646545,311.657959,0.000055,7.500012,42.603733,10.0,100000.0,false,DoNotOverride,2.8",
          Content = "在帝国随处可见的巨幅海报，上面写着“荣耀尽归吾皇”等标语。",
          DialogueId = 70011901,
          Duration = 5,
          GUID = "AF447782",
          SpeakNpcId = 102029,
          Subtitle = "(A large poster, commonly seen throughout the Empire, bearing slogans like \"All glory to our Emperor\".)"
        },
        [70012001] = {
          Camera = "251.815674,-114.571671,67.927124,0.000047,-3.399658,170.391632,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "第六军团面向卡戎之民的新一期选拔考核即将展开，满足申报条件的卡戎之民可自行提交申请材料。\n改变命运的时刻已至，在黑狼旗下呼唤吾皇尤里乌斯的威名，向海伯利亚献上你们的忠诚！\n注：\n1、考核表现特别优异者可取得桂冠卡戎奖章，拥有入驻内城的资格。\n2、未能获取桂冠卡戎奖章但表现突出者，将编入外围卫戍部队服役。\n3、考核最终解释权归第六军团科赛托斯行省驻扎部队所有。\n4、考核途中出现的一切意外由本人承担。",
          DialogueId = 70012001,
          Duration = 5,
          GUID = "AF4487EA",
          SpeakNpcId = 102030,
          Subtitle = [[
The latest 6th Legion recruitment (Charon Special) are set to commence shortly. Eligible Charons can proceed to the Security Bureau to submit their applications. Seize the moment to change your destiny. Under the flag of the Black Wolves, invoke the might of Emperor Julius and pledge your allegiance to Hyperborea! 
Note: 
1. Those with exceptional performance may earn the Laurelled Charon Medal, granting the privilege to be stationed in the Inner City.

2. Those who do not receive the Laurelled Charon Medal but show outstanding performance will be conscripted into the Outer City Escort. 
3. Final interpretation rights of the recruitment belong to the 6th Legion's Cocytus Province Garrison; participants assume all responsibility for any incidents that occur during the assessment.]]
        },
        [70012101] = {
          Camera = "-413.806396,24.681641,230.520782,0.000089,-29.19894,-18.408882,35.0,400.0,false,DoNotOverride,2.8",
          Content = "储藏罐上写着“月髓液”的字样。在帝国的交通、照明等一系列物品上都能看到这一名词，从名字判断，应该是某种从月石演变来的产物。",
          DialogueId = 70012101,
          Duration = 5,
          GUID = "AF449852",
          SpeakNpcId = 102031,
          Subtitle = "A pale blue canister labelled \"Phoxichor\". This term is visible on a variety of items related to transportation and lighting across the Empire. The name itself suggests it is a derivative of Phoxene."
        },
        [70012201] = {
          Camera = "-829.676514,67.595215,115.704071,0.000047,28.996904,-8.414193,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "钟表指针每次划过12点都会在表盘上短暂地浮现出一个姓名——陶德·威尔斯。能将机关技术与光学原理结合，在作品上隐晦地留下名字。\n想必威尔斯先生应是一位杰出的钟表匠。",
          DialogueId = 70012201,
          Duration = 5,
          GUID = "AF44A8BA",
          SpeakNpcId = 102032,
          Subtitle = "Each time the clock hands pass 12, the name \"Todd Wells\" briefly appears on the dial. Combining mechanical ingenuity with optical principles to subtly incorporate his name into his work, Mr. Wells must be a master clockmaker."
        },
        [70012301] = {
          Camera = "576.424805,22.139282,190.283051,0.000035,-16.800291,175.187546,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "刚一靠近车辆就听到一阵激昂的叫喊，“嗨嗨嗨，你也对这台PRT20A感兴趣对吧，这也是没办法的嘛！\n毕竟是第二代<H>由军用转为民用，搭载着月髓引擎的小型汽车</>，无数人传承下来的智慧结晶啊。\n虽然速度比不上军用的，但能近距离听着月髓引擎的轰鸣，开着它上路就已经是一种高贵身份的象征了……”。\n说话者滔滔不绝地从这台车的历史讲到结构，引擎讲到车身，甚至连轮胎的纹路都不放过，连讲数个小时。\n当耳边终于清静下来，脑海里还萦绕着一堆缸啊转啊等不知所云的词组。抬头环顾四周确认请静下来的原因。\n原来是这名狂热的爱好者早已跑去跟另一名倒霉的行人介绍起了面前的车辆。",
          DialogueId = 70012301,
          Duration = 5,
          GUID = "AF44B922",
          SpeakNpcId = 102033,
          Subtitle = "(Upon approaching the vehicle, you're greeted by an excited shout, \"Hey, there! You're also fascinated by this PRT20A, aren't you? I know, right?! I mean, this one here is the second-gen civilian model adapted from military use, powered by a Phoxynamo Wheel—a true epitome of wisdom passed down through the ages!)\n(Sure, it's not as speedy as the military versions, but just being able to hear the Phoxynamo Wheel purring up close while driving it around, that's a status symbol in itself...\", the speaker goes on and on, covering everything from the car's history, its engineering, the wheel, the body, down to the very treads on the tyres, talking your ear off for hours.)\n(When things finally quieten down, your head's still spinning with all sorts of technical jargon about cylinders and rotations. Looking around to find out why it's gone quiet, you see that the car fanatic has already scooted off to start up the same spiel with another poor soul passing by.)"
        },
        [70012401] = {
          Camera = "-712.020264,-289.200195,10.626465,0.000082,16.793509,22.182402,10.0,100000.0,false,DoNotOverride,2.8",
          Content = "高大的纪念碑，背面记满了帝国人的姓名，正面则深深地刻着简短的一句话：\n纪念为这片土地带来悠久和平而英勇牺牲的军人们。\n荣耀尽归吾皇。",
          DialogueId = 70012401,
          Duration = 5,
          GUID = "AF44C98A",
          SpeakNpcId = 102034,
          Subtitle = [[
A towering monument, its back inscribed with names of the Empire's people, and on the front deeply engraved with a brief inscription: 
In memory of the soldiers who sacrificed themselves for the lasting peace on this land. 
All glory to our Emperor.]]
        },
        [70012501] = {
          Camera = "-593.807617,-151.208984,181.682983,0.000059,-13.99979,25.798237,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "不知这是第几次在冰湖城看到矿灯、矿镐和矿车了，如此数量庞大的矿业工具无疑宣告着冰湖城在过去进行月石开采时的辉煌。\n但看着这些工具被丢在垃圾箱旁，落满灰尘，任谁都能明白，属于矿工的辉煌早已成为过去。",
          DialogueId = 70012501,
          Duration = 5,
          GUID = "AF44D9F2",
          SpeakNpcId = 102035,
          Subtitle = "(In Icelake, the multitude of mining lamps, pickaxes, and minecarts is striking. The abundance of these mining tools speaks volumes of the city's once thriving Phoxene ore mining era. Yet, now they lie discarded beside rubbish bins, coated in dust, a poignant testament that the miners' days of glory have faded into history.)"
        },
        [70012601] = {
          Camera = "-429.546875,-25.467529,208.017578,0.000075,25.39749,-29.411985,20.0,100000.0,false,Manual,2.8",
          Content = "工厂巨大的阴影洒向城市，如俯视蝼蚁的巨人，将弱小的生命笼罩在自己的身影之下。\n每天都有数以千计的工人进出其中，即使身隔数百米，也能听到那巨人永不停歇的轰鸣。",
          DialogueId = 70012601,
          Duration = 5,
          GUID = "AF44EA5A",
          SpeakNpcId = 102036,
          Subtitle = "The factory's immense shadow sprawls across the city, engulfing innumerable puny lives, like a giant looming over ants. Thousands of workers come and leave every day, and even from hundreds of metres away, one can hear the relentless rumble of this behemoth."
        },
        [70012701] = {
          Camera = "7.69043,-170.557617,63.654785,0.0,0.0,-89.999939,10.0,100000.0,false,DoNotOverride,2.24",
          Content = "封锁的路障禁止任何人通行，从路障旁醒目的提示来看，前方区域已被第六军团卫戍部队接管。",
          DialogueId = 70012701,
          Duration = 5,
          GUID = "AF44FAC2",
          SpeakNpcId = 102037,
          Subtitle = "The roadblock prohibits any passage. The prominent sign nearby indicates that the area ahead is now under the control of the 6th Legion's Escort."
        },
        [70012801] = {
          Camera = "902.932129,1093.807129,22.332031,0.000012,7.59978,-122.402924,35.0,100000.0,false,Manual,2.8",
          Content = "以月髓液驱动的供暖设施，坐在旁边会感觉心里暖洋洋的。但从其简陋的安装手法和位置来看，应该是某位民间非专业人士安置的。\n毕竟对帝国官方来说，为卡戎之民修筑供暖设施是完全没有意义的行为。",
          DialogueId = 70012801,
          Duration = 5,
          GUID = "AF450B2A",
          SpeakNpcId = 102038,
          Subtitle = "A heating facility powered by Phoxichor, providing a comforting warmth to those nearby. Its makeshift installation and placement, however, hint at the handiwork of a local amateur, as the Empire deems the provision of heating for Charons utterly unnecessary."
        },
        [70012901] = {
          Camera = "538.746094,139.100586,83.406647,0.000042,-10.399529,-172.984406,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "凌乱的喷漆，密密麻麻地写满了对卡戎之民的侮辱性文字。",
          DialogueId = 70012901,
          Duration = 5,
          GUID = "AF451B92",
          SpeakNpcId = 102039,
          Subtitle = "Messy graffiti crammed with insults to Charons."
        },
        [70013001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.27",
          Content = "小到只能容纳一只鸟的坟墓，上面的墓碑上没有姓名，只刻着一句话，“我永远的伙伴，带我逃出生天的英雄，长眠于此。——科农”。",
          DialogueId = 70013001,
          Duration = 5,
          GUID = "AF452BFA",
          SpeakNpcId = 102040,
          Subtitle = "A tiny grave, barely large enough to accommodate a bird. The headstone is bereft of names, inscribed only with, \"Here lies my constant companion, the hero who helped me escape from the mine. — Conon\"."
        },
        [70013101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.28",
          Content = "发着淡淡黄光的编织袋，通过凸起的棱角能辨别出里面装满了月石，编织袋的底部有红色的血迹。",
          DialogueId = 70013101,
          Duration = 5,
          GUID = "AF453C62",
          SpeakNpcId = 102041,
          Subtitle = "A woven bag emitting a soft yellow glow, its bulging corners indicating it is filled with Phoxene, with the bottom marked by stains of blood."
        },
        [70013201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.29",
          Content = "积木\n（简易的积木，曾经在孩子们之间很流行的款式，但现在看来有些过时老旧了。）\n",
          DialogueId = 70013201,
          Duration = 5,
          GUID = "AF454CCA",
          SpeakNpcId = 102042,
          Subtitle = [[
Building Blocks
(Simple building blocks, once popular among children but now seeming outdated and worn.)]]
        },
        [70013301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.30",
          Content = "赛琪的房间\n（门上挂着绿色蝴蝶画板，稚嫩的笔触在上面涂鸦出“赛琪的房间”，这里应该是赛琪曾生活过的地方，只是现在房门锁着，应该是母亲黛西的意愿。）",
          DialogueId = 70013301,
          Duration = 5,
          GUID = "AF455D32",
          SpeakNpcId = 102043,
          Subtitle = [[
Psyche's Room
(A green butterfly drawing board hangs on the door, with childish scribble spelling out "Psyche's Room". This must have been where Psyche lived. But now the door is locked, presumably at her mother Daisy's behest.)]]
        },
        [70013401] = {
          Camera = "-274.459961,499.943848,20.897705,0.000001,4.999999,-79.999969,16.0,100000.0,false,Manual,2.8",
          Content = "透过“百相”服装店的橱窗，能看到一条富有品味的长裙，每一寸布料都恰到好处，彰显身段的同时衬出裙子主人优雅的气质，完美贴合哈兰的身材。",
          DialogueId = 70013401,
          Duration = 5,
          GUID = "AF456D9A",
          SpeakNpcId = 102044,
          Subtitle = "(Through the window of the boutique named Looks Galore, one can see an elegant long dress. Each piece of fabric is expertly tailored, accentuating the wearer's beautiful figure and grace, perfectly suited for someone like Harlan.)"
        },
        [70013501] = {
          Camera = "36.606445,286.352539,23.979492,0.000003,-8.400025,-108.599854,15.0,100000.0,false,Manual,2.32",
          Content = "摆放在里奥拉身旁的水桶、抹布，这些工具应该是用来清洁旁边暗红色污渍的，想来这里之前发生过惨烈的冲突。",
          DialogueId = 70013501,
          Duration = 5,
          GUID = "AF457E02",
          SpeakNpcId = 102045,
          Subtitle = "(A bucket and mop set beside Lio, presumably for cleaning the ominous dark red stains nearby. A brutal confrontation might have occurred here.)"
        },
        [70013601] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.33",
          Content = "泛黄的老海报，能勉强分辨出上面的内容：\n……\n首席歌者薇奥莱塔女士的演出将在下周开启！\n《雪国的孩子》经典重现，天籁般的歌谣将响彻冰湖城！\n持续一整个星期！不能错过！决不能错过！\n给钱就能带你混进内城！体验人上人的音乐盛宴！\n……\n联系人：杰克先生\n联系方式：每天半夜在下水道井盖旁汇合，向红头发的男人报暗号“布谷布谷”。",
          DialogueId = 70013601,
          Duration = 5,
          GUID = "AF458E6A",
          SpeakNpcId = 102046,
          Subtitle = [[
A faded, barely legible old poster reads:
...
Lead vocalist Ms. Violetta's performance coming next week!
Children From the Snowfield makes a classic return, with her ethereal voice set to resonate throughout Icelake!
A full week of unmissable performances! Absolutely not to be missed!
Pay for an exclusive opportunity to be smuggled into the Inner City! A glimpse into a musical feast for the elite!
...
Contact: Mr. Jack
Meeting Point: Every midnight by the sewer manhole. Signal to the red-haired man with the code word "Cuckoo, Cuckoo".]]
        },
        [70013701] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.34",
          Content = "一本破破烂烂的教科书，空白的部分被人画上了许多粗劣的涂鸦。在这些涂鸦中，费伊被描绘成了一个长角的恶魔，正在施放可怕的巫术。",
          DialogueId = 70013701,
          Duration = 5,
          GUID = "AF459ED2",
          SpeakNpcId = 102047,
          Subtitle = "(A tattered textbook, its blank spaces filled with crude doodles. In these scribbles, Fahy is portrayed as a horned demon practising sinister dark magic.)"
        },
        [70013801] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.35",
          ContentES = "A veces se ve a una mujer de rostro severo en la Casa de Hypnos, barriendo los pasillos y cocinando comidas calientes para los niños.\n\nCuando se le pregunta por qué, ella responde simplemente:\n“El Sr. Henrik me contrató, así que hago mi trabajo. Así es como va el mundo.”\n\nSu voz lleva una quieta fatiga, suficiente para desalentar cualquier insistencia.\n\nPero todos los niños de la Casa de Hypnos lo saben: la Sra. Lina nunca ha aceptado ni un solo céntimo del Sr. Henrik.",
          DialogueId = 70013801,
          Duration = 5,
          GUID = "AF45AF3A",
          SpeakNpcId = 102048,
          Subtitle = "A stern-faced woman is often seen at Hypnos' House, sweeping the halls and cooking warm meals for the children.\n\nWhen asked why she's there, she simply replies:\n\"Mr Henrik hired me, so I do the job. That's just how the world turns.\"\n\nHer voice carries a quiet weariness — enough to dissuade further questions.\n\nBut every child at Hypnos' House knows the truth: Ms Lina has never taken a single coin from Mr Henrik."
        },
        [70013901] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.36",
          Content = "五花八门的废弃品，很难判断玛尔洁选品的依据是什么。他们曾经的主人都是谁呢？",
          DialogueId = 70013901,
          Duration = 5,
          GUID = "AF45BFA2",
          SpeakNpcId = 102049,
          Subtitle = "(An eclectic array of abandoned items, leaving one to wonder about Martin's criteria for selection. Who might their previous owners have been?)"
        },
        [70014001] = {
          Camera = "-394.105225,225.10498,147.011475,0.00004,-19.999113,-46.394775,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "卡米拉拒收的酒水，不知道接下来会流通到哪里。",
          DialogueId = 70014001,
          Duration = 5,
          GUID = "AF45D00A",
          SpeakNpcId = 102050,
          Subtitle = "(The alcoholic beverages rejected by Camilla. No one knows where they will end up next.)"
        },
        [70014101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.38",
          Content = "孩子的尺码，看来巴克听到的脚步声来源于此。",
          DialogueId = 70014101,
          Duration = 5,
          GUID = "AF45E072",
          SpeakNpcId = 102051,
          Subtitle = [[
Footprints
(Child-sized footprints. These likely belong to the footsteps Buck heard.)]]
        },
        [70014201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.39",
          Content = "看来犯人的背包破了个小洞，零碎的爆米花撒了一路。“饱满果实的气味”……原来如此。",
          DialogueId = 70014201,
          Duration = 5,
          GUID = "AF45F0DA",
          SpeakNpcId = 102052,
          Subtitle = [[
Popcorn
(It appears that a small hole in the perpetrator's backpack left a trail of popcorn. "The scent of ripe fruit"... now it all adds up.)]]
        },
        [70014301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.40",
          Content = "简陋的小帐篷，贝琳达长居于此，并且经营着一家起咨询作用的小店，没有招牌，没有明确的咨询范围，往来的客人似乎有自己的难言之隐。",
          DialogueId = 70014301,
          Duration = 5,
          GUID = "AF460142",
          SpeakNpcId = 102053,
          Subtitle = "A humble tent where Belinda has made her home and runs a small advisory shop, with no sign nor a clear business scope. Her clients seem to bring with them their own unspoken woes."
        },
        [70014401] = {
          Camera = "-277.21875,1095.014038,199.530029,0.000023,24.997671,-88.593628,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "以月髓液驱动的巨大吊机。随着工程炼金院的改良，工人们只用在操纵室推一下摇杆即可完成对复数个巨大吊机的操作，大大提升了工作效率。\n但这一改动同时也磨灭了不少年幼时喜爱巨大吊机的男孩的梦，以及大量工人的工作机会。",
          DialogueId = 70014401,
          Duration = 5,
          GUID = "AF4611AA",
          SpeakNpcId = 102054,
          Subtitle = "A gigantic crane powered by Phoxichor. With modifications by the Aeolipile, these cranes no longer require operators to be stationed atop them. A mere push of a joystick in the control room can now simultaneously manage multiple cranes, greatly enhancing efficiency. However, this advancement has also shattered the dreams of many young boys once enamoured with these colossal machines, along with numerous job opportunities for workers."
        },
        [70014501] = {
          Camera = "-553.419922,-854.08313,145.091064,0.000012,-2.200284,52.400944,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "从标签来看似乎是一款名叫PRT05MV的军用钻探车，风吹日晒与斑驳锈迹在它的车身上留下岁月的痕迹。\n既没人看管也无人回收，不知是帝国对车辆安保的自信，还是军团的威严让所有想要靠近这辆废车的生物望而却步。",
          DialogueId = 70014501,
          Duration = 5,
          GUID = "AF462212",
          SpeakNpcId = 102055,
          Subtitle = "(An abandoned military drilling vehicle labelled PRT05MV. Its body bears the scars of time with weathering and patchy rust. Left unattended and unreclaimed, it is unclear whether this is due to the Empire's confidence in its vehicle security or the Legion's daunting presence deterring any creature from approaching this forsaken vehicle.)"
        },
        [70014601] = {
          Camera = "18.892578,-214.330688,159.580475,0.000026,-31.400263,99.99868,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "一块已经长毛，用旧报纸包裹起来的黑面包。\n面包虽已无法食用，但展开报纸，擦掉霉菌后还能勉强看出这是一张十几年前的老旧报纸。\n与报道一同刊登的还有庆祝仪式的数张照片，照片里军官和工人们拿着工程炼金院发表的格雷姆新矿脉报告开心的笑着。",
          DialogueId = 70014601,
          Duration = 5,
          GUID = "AF46327A",
          SpeakNpcId = 102056,
          Subtitle = "A mouldy piece of rye bread encased in old newspaper. The bread is surely inedible now. Smoothing out the newspaper and brushing off the mould, one can find it is an edition from over a decade ago, featuring a report about the 6th Legion's agreement with the original owners of Glevum Pit.\n\n...\nIn the interest of the miners and for the betterment of Icelake, Glevum Pit will henceforth cease private mining operations, with all affairs to be managed by the Legion.\n...\n\nThe report includes several black and white photographs of the celebration ceremony. Oddly though, in these images, only the officer brandishing the agreement and the jubilant workers are visible. The pit's original owners are conspicuously absent — whether by choice or circumstance, one cannot tell."
        },
        [70014701] = {
          Content = "揉成一团的信件，从字迹来看应是统一印刷而非人工手写。\n你好，帝国子民：\n我是海伯利亚的建立者，你们最伟大的迪斯一世。我于皇都迪斯玛尼亚写下这封信，\n是的，我没有死，而是通过秘术活了下来。\n如今我正准备重启对艾利西安的伟大征途，但当年的资金都被冻结了，暂时取不出。如果你仍有身为帝国之人的荣耀与血性，可将赞助资金寄到皇都凯旋大街233号，待我攻陷艾利西安圣都后，必将双倍奉还。\n记住，战争一触即发，不要拖延！我等待着你的赞助资金，届时，我将如闪电般归来！",
          DialogueId = 70014701,
          Duration = 5,
          GUID = "AF4642E2",
          SpeakNpcId = 102057,
          Subtitle = "A crumpled letter, evidently mass-printed rather than handwritten, reads: \n\nDear People of the Empire,\n\nGreetings from your greatest Dis I, the founder of the Hyperborea Empire, in Dismania, the imperial capital.\nAstonishing as it may seem, I am very much alive, having mastered the art of longevity.\nI am now gearing up to resume my great quest against Elysium.\nHowever, a small hitch — my required funds are all tied up in Icelake, and my current condition precludes me from accessing them personally. \nIf you still have the honor and courage of being a man of the Empire, do send your sponsorship to No. 233, Triumph Street in the imperial capital.\nRest assured, once I've bounced back and retrieved the full war funds, your investment will be returned twofold. \n\nRemember, the war is coming, so please act swiftly! Your sponsorship is eagerly anticipated!\nOnce I'm ready, I will return like lightning!"
        },
        [70014801] = {
          Camera = "-233.383423,129.945312,39.479553,0.000071,26.799578,-19.787138,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "一款名叫冰湖往事的发酵饮品，转动阀门即可装上满满一杯。\n其色调接近月石，初尝时有股薄荷般的清爽，如冰湖拂过的冷风。\n咽下时有股蜜糖般的甘甜。如月石开采事业的辉煌，紧接着，泥煤的苦涩充斥五脏六腑，留下无穷的回味。\n冰湖往事，恰如其名，难怪成为水仙平原最受欢迎的饮品。",
          DialogueId = 70014801,
          Duration = 5,
          GUID = "AF46534A",
          SpeakNpcId = 102058,
          Subtitle = [[
(A fermented beverage known as "Tales of Icelake", just a valve turn away from filling your cup. Its hue resembles Phoxene, with an initial refreshing minty taste reminiscent of a brisk Icelake breeze. When swallowed, it leaves a honeyed sweetness akin to the glory of the Phoxene mining industry.)

(Finally, a lingering peaty bitterness fills the senses, leaving an indelible aftertaste. True to its name, Tales of Icelake is unsurprisingly the most popular beverage at The Asphodel.)]]
        },
        [70014901] = {
          Camera = "144.133301,295.799561,71.270615,0.000111,5.599437,-116.392715,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "精妙的齿轮结构，不管怎么转动，水仙平原的一切都没有发生变化，然而从吧台后方那隐隐传来的机械运转声可以推测，这些齿轮并不是简单的装饰。",
          DialogueId = 70014901,
          Duration = 5,
          GUID = "AF4663B2",
          NextDialogue = 70014902,
          SpeakNpcId = 102059,
          Subtitle = "(An intricate gear mechanism that, despite its movements, leaves The Asphodel unchanged. However, the subtle mechanical sounds from behind the bar hint at a purpose beyond mere decoration.)"
        },
        [70014902] = {
          Content = "也许正如卡米拉说过的那样，商人为了一丁点蝇头小利连上绞架的事都做得出，水仙平原也并不仅是表面上卖卖发酵饮品那么简单。",
          DialogueId = 70014902,
          GUID = "AF4663B3",
          SpeakNpcId = 102059,
          Subtitle = "(Perhaps, just like Camilla once remarked, \"for a sliver of profit, merchants would go to the gallows\" — and The Asphodel may well be more than just a hut selling fermented drinks.)"
        },
        [70015001] = {
          Camera = "267.163086,229.933594,218.354156,0.000008,-28.000093,-144.996719,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "月髓科技应用在帝国人民生活中的标志之一，虽然照明效果一般，但凭借消耗少、成本低、寿命长等特点，还是让其成为冰湖城人民使用的主流灯具。\n在过去，工程炼金院扩建格雷姆矿场时也曾大量使用该款灯具。",
          DialogueId = 70015001,
          Duration = 5,
          GUID = "AF46741A",
          SpeakNpcId = 102060,
          Subtitle = "One example of Phoxene technology application in the everyday lives of Imperial citizens. While the lighting is average, its excellent efficiency, low cost, and longevity have made it the primary lighting choice in Icelake. In the past, during the expansion of Glevum Pit by the 6th Legion, these lamps were also used extensively."
        },
        [70015101] = {
          Camera = "-293.902832,-246.538574,58.947754,0.000011,22.198734,42.000011,35.0,100000.0,false,Manual,2.8",
          Content = "明明是帝国常见的门楣样式，但看着那两个小方框，脑海里还是不自觉地将其过滤成一张龇牙咧嘴说着“看什么看！”的奇怪面容。",
          DialogueId = 70015101,
          Duration = 5,
          GUID = "AF46741B",
          SpeakNpcId = 102061,
          Subtitle = "At first glance, it seems like just an ordinary doorframe, the kind you'd see anywhere in the Empire. Yet, those two square panels strangely resemble a face, almost as if it's snarling, \"What are you looking at!?\""
        },
        [70015201] = {
          Content = "骨架、武器和未吃完的食物压在破烂的背包之下，诉说着那些消失在废矿深处的，狩月人的最终宿命。\n这些背包有新有旧，它们的主人出于相似的目的进入废矿，幻想着自己不会成为失败的那一个，最终又迎来相似的，令人悲哀的结局。",
          DialogueId = 70015201,
          GUID = "AF4694EA",
          Subtitle = "Beneath a pile of worn backpacks lie bones, weapons, and unfinished provisions — silent evidence of the grim fate that has claimed many a Phoxhunter who dared to descend into the forsaken pit.\nNew or old, these backpacks once belonged to those chasing the same rags-to-riches dream, each believing they would escape such a fate, only to meet the same tragic end."
        },
        [70015301] = {
          Content = "从背包中的日记和早已失去光泽的月石来看，如果变故来得再晚一些，也许背包的主人能得到更好的未来。",
          DialogueId = 70015301,
          GUID = "AF46A552",
          Subtitle = "Tattered diaries and faded Phoxene cubes suggest that, had luck favoured them, their owners might have carved out a much brighter future."
        },
        [70015401] = {
          Content = "被弃置在垃圾桶里的《冰湖城早报》，但仔细一看，有几个字印刷错了——看来只是一份仿制品。\n展开一看，上面似乎记载了不少耸人听闻的内容。",
          DialogueId = 70015401,
          Duration = 5,
          GUID = "AF46B5BA",
          NextDialogue = 70015402,
          SpeakNpcId = 102064,
          Subtitle = "An old copy of the Icelake Daily, discarded in a rubbish bin, catches your eye. Upon closer inspection, you spot a few typos — it's clearly a knockoff. As you leaf through it, you come across some sensational stories:"
        },
        [70015402] = {
          Content = "莫里斯·格伦维尔秘事\n……冰湖城的市民都知道昙花一现的格伦维尔家族，以及莫里斯·格伦维尔先生生前白手起家，一跃成为钢铁大亨，但家族成员先后遭遇诅咒，疯癫、意外死亡或失踪的故事。但是我们今天要谈的是另一件事——为什么格伦维尔先生要保留他穷小子的历史？",
          DialogueId = 70015402,
          Duration = 5,
          GUID = "AF46B5E4",
          NextDialogue = 70015403,
          SpeakNpcId = 102064,
          Subtitle = "Morris Glenville's Hidden Past\nEvery citizen of Icelake is familiar with the meteoric rise and sudden downfall of the Glenville family — how Morris Glenville, once a man of humble origins, became a steel magnate, only for his family to be plagued by madness, mysterious deaths, and disappearances. But today, we ask a different question — why did Mr Glenville choose to preserve his modest past?"
        },
        [70015403] = {
          Content = "……读者们有所不知，莫里斯发迹的第一桶金，正是他少年时在这位工程炼金院高官手下办事时赚得的，而这位官员是一名桂冠卡戎；结合莫里斯在日后成为了一名不折不扣的反卡戎主义者这一事实，我们不难推测出，在少年时，莫里斯和他的卡戎上司之间一定埋藏着一些隐秘的往事……",
          DialogueId = 70015403,
          Duration = 5,
          GUID = "AF46B60E",
          NextDialogue = 70015404,
          SpeakNpcId = 102064,
          Subtitle = "Few know that in his youth, Morris Glenville earned his seed money working under a high-ranking officer at the Aeolipile Alchademy, who was, in fact, a Laurelled Charon. Given Glenville's later vehement anti-Charon stance, one might wonder — what hidden history lies between him and his former Charon boss?"
        },
        [70015404] = {
          Content = "震惊！尤里乌斯陛下真实身份竟是替身？\n……当年报纸的报道和皇宫供职人士的回忆录中都记载了尤里乌斯陛下即位前的言谈，那时的他毫无疑问是一位谦和谨慎，风度翩翩的皇子。那么，为什么陛下会在即位后性情大变？\n真相只有一个，那就是——真实的陛下早就被谋害了，如今坐在柏罗纳宫中的那位皇帝，是不折不扣的假货！……\n",
          DialogueId = 70015404,
          Duration = 5,
          GUID = "AF46B638",
          NextDialogue = 70015405,
          SpeakNpcId = 102064,
          Subtitle = "The True Identity of Emperor Julius Revealed!!!\nHistorical records and accounts from those who served at the royal palace consistently portrayed Prince Julius, before his ascension to the throne, as a humble, graceful, and cautious gentleman. So, what caused his drastic change in demeanour upon taking the throne? There's only one plausible explanation — the real Julius was assassinated, and the man now in the Palace of Belloona is an imposter!"
        },
        [70015405] = {
          Content = "你觉得自己好像知道得太多了，连忙把这份伪造的小报扔回了垃圾桶。",
          DialogueId = 70015405,
          Duration = 5,
          GUID = "AF46B662",
          SpeakNpcId = 102064,
          Subtitle = "Realising you may have stumbled onto something you shouldn't, you quickly toss the knockoff newspaper back into the bin."
        },
        [70015501] = {
          Camera = "382.455078,-10.461182,127.896484,0.000083,-5.801112,-108.595062,30.0,96.67099,false,Manual,4.0",
          ContentES = "Una foto tomada hace más de diez años. El cristal del marco está cubierto de huellas dactilares. En la foto, una chica Charon sonriente, con el viento acariciando su cabello.\n\nEn la parte de atrás, escrito con pluma fuente:\n“Mi hija — Hayley. Tomada en Río Escarlata.”\n\nNo se parece realmente a Psyche, pero sin embargo... su sonrisa clara evoca irresistiblemente su recuerdo.",
          DialogueId = 70015501,
          Duration = 5,
          GUID = "AF46C622",
          Subtitle = "An old photograph, taken more than a decade ago. The glass is clouded with fingerprints. In the picture, a Charon girl smiles softly as the breeze toys with her hair.\n\nOn the back, written in fountain pen:\n\"My daughter — Hayley. Taken in Scarletriver.\"\n\nShe doesn't much resemble Psyche... and yet, something in that innocent smile calls her to mind all the same."
        },
        [70015601] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          Content = "日志的封面上写着简短的一句话，“愿灵魂永眠于雾海”。翻开这本厚重的日志，能看到一个个熟悉的日期与姓名。",
          DialogueId = 70015601,
          Duration = 5,
          GUID = "AF46D68A",
          NextDialogue = 70015602,
          Subtitle = "The cover of the heavy journal bears a simple inscription: \"May their souls rest in the Misty Sea.\" As you flip through the pages, you recognise names and dates that are all too familiar."
        },
        [70015602] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          Content = "……\n9月3日，卡罗琳娜·布朗。\n……\n10月29日，亨特·克拉克。\n……\n11月25日，赛琪·弗莱伊。",
          DialogueId = 70015602,
          Duration = 5,
          GUID = "AF46D6B4",
          Subtitle = [[
...
September 3, Carolina Brown.
...
October 29, Hunt Clark.
...
November 25, Psyche Frey.]]
        },
        [70015701] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          Content = "与月石颜色相似的晶石。但仔细观察，纹路和质地与月石完全不同，只是一些普通的“会发光的石头”而已。",
          DialogueId = 70015701,
          Duration = 5,
          GUID = "AF46E6F2",
          NextDialogue = 70015702,
          Subtitle = "A crystal that resembles Phoxene at first glance, but a closer inspection reveals its texture and pattern are entirely different — just an ordinary glowing rock."
        },
        [70015702] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          Content = "人类按照使用价值把矿石分为三六九等，月石是珍贵的资源，而它们则是无用的废品。\n但也正因于此，月石被采掘一空，被打碎，被切割，最终成为工厂里冰凉的月髓液，而它们则幸运而完整地留下了。",
          DialogueId = 70015702,
          Duration = 5,
          GUID = "AF46E71C",
          Subtitle = [[
Humans rank minerals by their usefulness, and while Phoxene is a highly coveted resource, these stones are deemed worthless.
As a result, while Phoxene ore was mined to exhaustion, shattered, and refined into cold Phoxichor in roaring factories, these unassuming rocks remain untouched, preserved in their natural state.]]
        },
        [70015801] = {
          Camera = "492.773438,-508.054688,926.297363,0.000004,-0.000096,143.197693,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "码头四处可见的大型起重装置。不同于帝国常见的铆钉与金属交织而成的冰冷风格，华胥的装置多以木制榫卯结构为主。细看其底座上刻着一行小字：天梁司制造。",
          DialogueId = 70015801,
          Duration = 5,
          GUID = "AF46F75A",
          Subtitle = "Large cranes are commonly found across the docks. Unlike the Empire's cold constructions of riveted metal, those in Huaxu are built mainly with wooden mortise-and-tenon joints. A closer look reveals a small inscription at the base: Made by the Ministry of Works."
        },
        [70015901] = {
          Camera = "-447.582031,-536.535156,268.742676,0.000001,5.399906,55.198711,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "损毁的上古机傀，在岁月的摧折中早已失去了原始功能。其零件如今随意地散落在烟津渡的各处，被茂盛生长的草木掩盖。",
          DialogueId = 70015901,
          Duration = 5,
          GUID = "AF4707C2",
          Subtitle = "The remains of an ancient automaton have long been stripped of their original function by the passage of time. Its parts now lie scattered across Mistwharf, many of them half-buried beneath overgrown vegetation."
        },
        [70016001] = {
          Content = "<H>银烛狂欢</>将在盖雷亚剧院如期举行，请参与者自行准备你心仪的装扮，选择你要扮演的身份。\n让我们放下职业、放下种族、放下冲突相聚在于此，沐浴在皇帝的恩典之下，齐声赞颂皇帝的仁德，荣耀尽归吾皇！",
          DialogueId = 70016001,
          GUID = "AF47182A",
          Subtitle = [[
The Silvercandle Carnival will proceed as scheduled at Galea Theatre. Participants are encouraged to prepare their finest attire and select the role they wish to embody. 
Let us set aside professions, races, and conflicts, and gather under the Emperor's grace. Together, we shall bask in His Majesty's benevolence and proclaim: All glory to our Emperor!]]
        },
        [70016002] = {
          Content = "厚厚的点名册，详细地记录了每位工作人员一天的行程，除了排练，连吃饭睡觉和如厕的行程都被记录在内。\n不知是剧团长狠心地将所有人“软禁”在剧院之内，还是剧团长为了保护自己的演员，而不得不时刻关注每个人的动向。",
          DialogueId = 70016002,
          GUID = "AF471854",
          Subtitle = [[
A thick attendance log that meticulously records every staff member's daily schedule, tracking everything from rehearsals to meals, sleeping hours, and even bathroom breaks.
It's hard to tell whether the director is ruthlessly "imprisoning" everyone in the theatre or simply keeping a vigilant watch to protect her performers.]]
        },
        [70016003] = {
          Content = "帝皇尾戒勋章，完全由纯金打造，只会颁发给为帝国做出卓越贡献的军人。\n\n科赛托斯行省冰湖城第六军团下属卫戍部队，<H>黎瑟·费西尔</>。\n在连年、数次<H>清缴秽兽作战</>中，决策果断，作战英勇，收尾迅速。\n在维护地区治安的过程中起到了无可比拟的关键作用。\n现经军团评估，以吾皇尤里乌斯之名，授予黎瑟·费西尔帝皇尾戒勋章及准尉军衔，望广大军人以其为榜样，奋发上进，共同成长。\n荣耀尽归吾皇。",
          DialogueId = 70016003,
          GUID = "AF47187E",
          Subtitle = "A medal forged entirely of pure gold. According to the accompanying commendation letter, this honour is reserved for soldiers whose contributions to the Empire are deemed exceptional beyond measure."
        },
        [70016004] = {
          Content = "压在一堆杂物下的老旧报纸，记录着很久以前的悲惨事故。\n\n<H>秽蚀者异常凶险，不要被表象欺骗！</>\n9月24日，本市发生一起极为恶劣的“秽蚀”事件，经第六军团卫戍部队调查后，得出以下结论：\n冰湖城市民费西尔夫妇于9月13日在泪湖畔公路边上偶遇一名叫做罗比·布朗的青年。因其身受重伤，费西尔夫妇将其带回家中照料。\n然而，罗比·布朗是一名秽蚀者，他躲过了帝国对潜在秽蚀者的例行盘查并潜逃至城外，且在接受费西尔夫妇帮助时，刻意掩盖了自己的秽蚀痕迹。十日后，悲剧发生：布朗蜕变成为秽兽，杀死了包括费西尔夫妇在内数十名居住在冰湖城南区的市民。第六军团下属冰湖城卫戍部队紧急出动才平息此次骚乱。\n骚乱共造成18人死亡，其中包含3名索拉之民；另有34人受伤。在此提醒各位市民谨记，不要轻易收留身份不明的卡戎之民，一旦发现秽蚀者，立即上报治安署。它们永远只是人类的敌人，无一例外。如有刻意包庇秽蚀者、隐瞒不报者，一律按照《海伯利亚刑事法典》第54条规定，处以死刑。",
          DialogueId = 70016004,
          GUID = "AF4718A8",
          Subtitle = "Buried beneath a pile of old clutter, this yellowed newspaper recounts a tragic incident from years ago."
        },
        [70016005] = {
          Content = "系着歪扭蝴蝶结的朴素礼盒，礼盒边是一瓶帝国最顶尖的止痛剂，和一封不知是什么原因没被塞入礼盒的纸条，上面写着“希望你能早日康复”。",
          DialogueId = 70016005,
          GUID = "AF4718D2",
          Subtitle = "A plain gift box with a clumsily made ribbon bow, accompanied by a bottle of the Empire's finest painkiller. Next to it is an unsent note that reads: \"Get well soon.\""
        },
        [70016006] = {
          Camera = "-35.015625,151.625,225.035156,0.000034,-14.798724,-71.592674,35.0,100000.0,false,Manual,22.0",
          Content = "（内城城墙下姐弟的合照，照片的右上角写着“黎瑟·费西尔”与“布鲁斯·费西尔”两个名字，还有庆祝弟弟布鲁斯通过第六军团考核的祝语。）",
          DialogueId = 70016006,
          GUID = "AF4718FC",
          Subtitle = "(A photo of a brother and sister standing under the inner city wall. Scribbled in the top-right corner are the names \"Rhythm Fischer\" and \"Blues Fischer,\" along with a congratulatory note celebrating Blues' passing the 6th Legion's entrance tests.)"
        },
        [70016007] = {
          Camera = "36.316406,112.411133,226.279297,0.00002,-31.198172,-98.592926,35.0,100000.0,false,Manual,22.0",
          Content = "（看起来很久没使用过的口琴，比起黎瑟的爱好，更像某种礼物。）",
          DialogueId = 70016007,
          GUID = "AF471926",
          Subtitle = "(A harmonica that looks like it hasn't been used in a long time. Its condition suggests it's more of a cherished gift than a personal hobby of Rhythm's.)"
        },
        [70016008] = {
          Content = "石灰墙的一角用小刀刻满了密密麻麻的字，有的歪歪扭扭，似是孩童的字迹；有些已经成熟，像是成年人所写。这些字都是同一句话：\n“我不会再看着任何人被秽兽杀死。”",
          DialogueId = 70016008,
          GUID = "AF471950",
          Subtitle = "One corner of the limewashed wall is covered in countless etched words. Some are crooked and childlike, while others are firm and deliberate, clearly written by an adult hand. All of them repeat the same sentence: \"I'll never let anyone die to Filthoids again.\""
        },
        [70016009] = {
          Content = "多位幕后人员记录的道具筹备单，详细记录着盖雷亚剧院近半个月所有道具的出入情况。\n\n10月08日，服装、睡袋筹备完成，确认人：蒙德里（批注：食物储备不足，<H>为了接下来为期一个月的集中排练，得托人再送一批进来</>）\n…………\n11月12日，新麦克风3只替换完成，确认人：格林德（批注：有一只麦克风声音巨响，普奇剧团长说这样就好，不做更换。）\n11月14日，红色幕布替换完成，金色幕布已收回仓库。确认人：贝尔\n…………\n11月24日，丢失的5顶假发回收完成，确认人：贝尔（批注：更衣室的角落容易藏东西，我今天去把那清空一下。）\n11月25日，花冠15顶筹备完成，马靴9双筹备完成，确认人：蒙德里",
          DialogueId = 70016009,
          GUID = "AF47197A",
          Subtitle = [[
Galea Theatre Props Inventory

A detailed log maintained by the backstage crew, documenting the management of props at Galea Theatre over the past two weeks.

8-Oct
Organized: Costumes and sleeping bags.
Logged by: Mondry
(Note: Food supplies are running low. We'll need to bring in another batch soon to prepare for the upcoming month-long intensive rehearsals.)
...
12-Nov
Replaced: Three new microphones.
Logged by: Grinde
(Note: One microphone produces an unusually loud sound, but Director Putsch insisted that it remain as is.)
14-Nov
Updated: Red curtain installed; gold curtain returned to storage.
Logged by: Bell
...
24-Nov
Retrieved: Five missing wigs.
Logged by: Bell
(Note: The dressing room corners are cluttered and seem to hide all sorts of things. I'll clean them out today.)
25-Nov
Organized: Fifteen flower crowns; nine pairs of riding boots.
Logged by: Mondry]]
        },
        [70016010] = {
          Content = "与剧院帷幕材质十分接近的布料，虽然老旧但十分整洁，显然经过什么人的认真打理。\n仔细观察和触摸会发现，和袭击现场发现的帷幕是同一块布料。",
          DialogueId = 70016010,
          GUID = "AF4719A4",
          Subtitle = [[
A piece of fabric resembling theatre curtain material. Though old and worn, it is impeccably clean, clearly maintained with care.
Upon closer inspection, it matches the fabric found at the crime scene.]]
        },
        [70016011] = {
          Content = "假人模型虽然很旧，但造型和姿势明显经过了精心设计，看起来端庄而优雅。",
          DialogueId = 70016011,
          GUID = "AF4719CE",
          Subtitle = "Though worn with age, the mannequin has clearly been posed and styled with care, exuding a graceful elegance, — like a performer lost in the moment on stage."
        },
        [70016012] = {
          Content = "四周遍布着巨大而凌乱的爪痕，就算这里不是怪物的藏身处，也一定是怪物经常活动的地方。想必这就是十三军团将此处列为封锁区域的原因之一。",
          DialogueId = 70016012,
          GUID = "AF4719F8",
          Subtitle = "Huge claw marks slash across the walls — dense, erratic, as if left in a frenzy of agony and madness."
        },
        [70016013] = {
          Content = "冰湖城下水道的部分布局图，错综复杂的管道连接着各个区域，图上大量区域还标注着“未经军团许可，常时禁止进入”的标语。",
          DialogueId = 70016013,
          GUID = "AF471A22",
          Subtitle = "A partial map of Icelake's sewer system. Its tangled network of pipes connects the city's many districts. Numerous sections are marked \"Do Not Enter Without Escort Authorisation.\""
        },
        [70016101] = {
          Camera = "-15.959961,1605.265137,1322.948242,0.000059,-29.399687,-89.596825,20.875948,100000.0,false,Manual,22.0",
          ContentES = "(Restablecer la energía del sistema de transporte de torretas requiere conectar cuatro cables.)",
          DialogueId = 70016101,
          GUID = "AF472892",
          NextDialogue = 70016102,
          Subtitle = "(Restoring power to the turret transport system requires four cables to be connected.)"
        },
        [70016102] = {
          Camera = "224.294922,655.639038,672.151611,0.000109,-27.999538,-125.796112,20.875948,100000.0,false,Manual,22.0",
          ContentES = "(Uno ya está conectado.)",
          DialogueId = 70016102,
          GUID = "AF4728BC",
          NextDialogue = 70016103,
          Subtitle = "(One is already in place.)"
        },
        [70016103] = {
          Camera = "-1774.869141,-1374.734619,1171.844727,0.000131,-33.399078,23.004192,20.875948,100000.0,false,Manual,22.0",
          ContentES = "(Quedan tres. Sigue los cables para encontrar las Ruedas Phoxynamo restantes.)",
          DialogueId = 70016103,
          GUID = "AF4728E6",
          Subtitle = "(Three to go. Follow the cables to locate the remaining Phoxynamo Wheels.)"
        },
        [70016104] = {
          Camera = "-5344.007812,-255.292114,647.478394,0.000156,-14.998623,83.199738,20.875948,100000.0,false,Manual,22.0",
          ContentES = "(Este es <H>un conjunto</> de Ruedas Phoxynamo, y parece que debe activarse dentro de un <H>tiempo límite</>.)",
          DialogueId = 70016104,
          GUID = "AF472910",
          Subtitle = "(This set of Phoxynamo Wheels appears to be on a timer. Activate them quickly!)"
        },
        [70016105] = {
          Camera = "5543.811523,-2108.574219,180.364319,0.000151,-3.998317,-104.994102,20.875948,100000.0,false,Manual,22.0",
          ContentES = "(El acceso está bloqueado... ¿Habría alguna manera de activar las Ruedas Phoxynamo <H>a distancia</>?)",
          DialogueId = 70016105,
          GUID = "AF47293A",
          Subtitle = "(The path is blocked. Is there a way to trigger the Phoxynamo Wheels from a distance?)"
        },
        [70016106] = {
          Camera = "157.341797,-91.314453,242.558594,0.0,-60.19952,101.398407,16.122608,100000.0,false,Manual,22.0",
          ContentES = "(Este no es Avar. Es un completo desconocido.)",
          DialogueId = 70016106,
          GUID = "AF472964",
          Subtitle = "(This isn't Avar. It's a complete stranger.)"
        },
        [70016107] = {
          Camera = "-71.794922,628.722656,135.195312,0.000076,12.199674,-90.596268,17.78793,100000.0,false,Manual,22.0",
          ContentES = "※ Testimonio de Calem (unidad de los Narvales)\nDeclaraciones como sigue:\n• Vi {性别2:al capitán|a la capitana} {nickname2} de los Grifos salir {性别2:solo|sola} de ▇▇▇▇, con el pecho cubierto de ▇▇▇▇. \n• {性别2:Él|Ella} nos ordenó mantener la posición, afirmando que {性别2:él|ella} iría a revisar▇▇▇▇ para detectar posibles Abandonados ocultos. \n• Dos minutos después, sonó la alarma. La capitana Falsi y yo entramos corriendo: el capitán Avar de los Lobos Blancos yacía en un charco de sangre. ▇▇▇▇ ya había sido activado.",
          DialogueId = 70016107,
          GUID = "AF47298E",
          Subtitle = "※ Testimony from Calem (Narwhals unit) \nStatements as follows:\n• \"I saw Captain  of the Griffins exit the ▇▇▇ ▇▇▇▇ alone — there was ▇▇▇ ▇▇▇▇ {性别2:his|her} chest.\"\n• \"{性别2:He|She} told us to hold position while {性别2:he|she} went to check the ▇▇▇▇ for any remaining Forsakens personnel.\"\n• \"Two minutes later, the alarm sounded. Captain Falsi and I rushed in — found Captain Avar of the Snow Wolves lying in a pool of blood. The ▇▇▇▇ ▇▇▇▇ had already been triggered.\""
        },
        [70016108] = {
          ContentES = "(No queda rastro de vida entre los soldados.)",
          DialogueId = 70016108,
          GUID = "AF4729B8",
          Subtitle = "(No trace of life remains among the soldiers.)"
        },
        [70016109] = {
          ContentES = "(Los cadáveres de Filthoids cercanos cuentan la historia: fueron estas bestias las que los acabaron. Y aun en la muerte, los soldados no se rindieron en silencio: sus últimos disparos dejaron heridas mortales en los Filthoids que los mataron.)",
          DialogueId = 70016109,
          GUID = "AF4729E2",
          Subtitle = "(The Filthoid corpses nearby tell the tale: it was these beasts that ended them. And yet, even in death, the soldiers did not go quietly — their final rounds left lethal wounds in the Filthoids that claimed them.)"
        },
        [70016110] = {
          Camera = "129.879883,311.569336,152.664062,0.000072,3.399556,-2.996889,17.78793,100000.0,false,Manual,22.0",
          ContentES = "※ Investigación sobre el origen familiar de {nickname2}\n{nickname2} es {性别2:un superviviente confirmado|una superviviente confirmada} del ▇▇▇▇, ocurrido hace tres años durante una operación militar contra ▇▇▇▇. Según {nickname2}, {性别2:él|ella} sufre de pérdida de memoria, aunque no presenta signos de disfunción cognitiva.\nCabe señalar que, según los testimonios de otros supervivientes, {nickname2} no figuraba en la lista de pasajeros registrados del ▇▇▇▇. En otras palabras, <H>{性别2:él era un auténtico “pasajero fantasma”|ella era una auténtica “pasajera fantasma”}</>.\nEn ese momento, la 13.ª Legión llevó a cabo una investigación exhaustiva sobre su identidad sin lograr autenticarla, descartando definitivamente la hipótesis ▇▇▇▇. Una de las teorías principales sugiere que {性别2:él podría haber sido un civil local|ella podría haber sido una civil local} que buscó refugio en ▇▇▇▇ durante el bombardeo y sufrió una lesión en la cabeza, lo que resultó en amnesia parcial.",
          DialogueId = 70016110,
          GUID = "AF47298F",
          Subtitle = "※ Investigation into the Family Background of \n is a confirmed survivor of the ▇▇▇ ▇▇▇▇, which occurred three years ago during a military operation against ▇▇▇ ▇▇▇ ▇▇▇. According to , {性别2:he|she} suffers from memory loss, though exhibits no signs of cognitive dysfunction.\nNotably, eyewitness accounts from other survivors confirm that  was not listed among the original passengers on ▇▇▇ ▇▇▇. In other words, {性别2:he|she} was a bona fide \"ghost passenger.\"\nAt the time, the 13th Legion conducted a comprehensive investigation into 's background but was unable to verify {性别2:his|her} identity. However, the possibility of {性别2:him|her} being ▇▇▇ ▇▇▇▇ ▇▇▇ was definitively ruled out. A leading theory suggests that {性别2:he|she} may have been a local civilian who sought shelter in ▇▇ ▇▇▇▇ during the bombing and suffered a head injury, resulting in partial amnesia."
        },
        [70016111] = {
          Content = "用石块垒起的石堆，旁边放着一束白花，看起来似乎有着某种纪念意义。仔细看的话，有一块石头上似乎浅浅刻着一个“H”开头的名字，但已经难以辨认。",
          DialogueId = 70016111,
          GUID = "AF4729E3",
          Subtitle = "A small cairn has been set here, white flowers laid gently beside it — a quiet sign of remembrance. Look closely, and you can just make out a name beginning with \"H\" carved into one of the stones, its letters worn to near nothing by time."
        },
        [70016201] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "记载大风九章诫律的大型石碑，用意为警醒世人。碑上所刻的诫律，在华胥境内请务必遵守。",
          DialogueId = 70016201,
          Duration = 5,
          GUID = "AF4738FA",
          NextDialogue = 70016202,
          Subtitle = "This large stone stele, inscribed with the Nine Chapters of Dafeng, was set in place to warn all who pass. The admonitions carved upon it are to be strictly observed within the borders of Huaxu."
        },
        [70016202] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "天地大德，其名为生。戕身害命，不可为也。\n夫人根基，定文为信。毁约背盟，不可为也。\n著真去伪，赤心为诚。妄言欺众，不可为也。",
          DialogueId = 70016202,
          Duration = 5,
          GUID = "AF473924",
          NextDialogue = 70016203,
          Subtitle = "Heaven's great virtue bears the name of Life;\nTo wound or kill — this must not be done.\nA man is measured by the strength of his word;\nTo break faith or betray a vow — this must not be done.\nLet truth be manifest and falsehood driven out;\nTo deceive and mislead the many — this must not be done."
        },
        [70016203] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "卑以自牧，束己为谦。骄狂跋扈，不可为也。\n尊贤友客，守序为礼。放诞无忌，不可为也。\n以我及人，制宜为义。恃强凌弱，不可为也。",
          DialogueId = 70016203,
          Duration = 5,
          GUID = "AF47394E",
          NextDialogue = 70016204,
          Subtitle = "Govern the self with humility, bind conduct to modesty;\nTo indulge in arrogance and tyranny — this must not be done.\nHonour the worthy, extend courtesy, and let order be the measure of propriety;\nTo act with wanton excess and unbridled abandon — this must not be done.\nLet compassion and righteousness guide your mind and every deed;\nTo oppress the weak by force — this must not be done."
        }
      }
    end
  },
  {
    MinKey = 70016204,
    MaxKey = 71002508,
    Loader = function()
      return {
        [70016204] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          Content = "清心敛行，身正为廉。枉法贪酷，不可为也。\n裁辨是非，知之为明。淆乱颠倒，不可为也。\n垂聆天宪，恭肃为敬。离经叛道，不可为也。",
          DialogueId = 70016204,
          Duration = 5,
          GUID = "AF473978",
          Subtitle = "Let your heart be pure, your conduct restrained, and uprightness be the mark of integrity;\nTo bend the law for greed or cruelty — this must not be done.\nLet clarity be your unwavering guide in discerning right from wrong;\nTo confuse truth and falsehood — this must not be done.\nAttend to Heaven's edict with a reverent mind and a solemn heart;\nTo rebel against the sacred order — this must not be done."
        },
        [70016301] = {
          Camera = "11.238281,-188.23291,625.148438,0.000004,-3.799989,-98.400398,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "华胥人的精神信仰——白龙神君太皓的塑像。",
          DialogueId = 70016301,
          Duration = 5,
          GUID = "AF474962",
          NextDialogue = 70016302,
          Subtitle = "A statue of Taihao — known as Lord Argent, who is revered by the people of Huaxu."
        },
        [70016302] = {
          Camera = "11.238281,-188.23291,625.148438,0.000004,-3.799989,-98.400398,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "这尊塑像龙首昂扬，伫立在百年春外的河滩之中，静静守护着这方净土。它起到的作用似乎不仅为精神寄托。据说当危机来临时，白龙神君能借助这尊塑像现身，回应人们的祈祷，荡清一切邪恶。",
          DialogueId = 70016302,
          Duration = 5,
          GUID = "AF47498C",
          Subtitle = "It stands upon the riverbank outside EverSpring, its mighty head held high as it watches silently over the realm. Yet its role seems to reach beyond mere symbolism. Legend holds that, in times of crisis, Lord Argent may manifest through the statue itself, answering prayers and purging all that is foul."
        },
        [70016401] = {
          Camera = "2886.273438,2012.956055,3502.893555,0.000015,5.199823,-141.799973,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "远看似乎是一尊明月高悬于百年春背面，近看才能发现其上独属于机械装置的纹路，随之而来的是馥郁袭人的香气。",
          DialogueId = 70016401,
          Duration = 5,
          GUID = "AF4759CA",
          NextDialogue = 70016402,
          Subtitle = "From afar, it resembles a bright moon looming above the rear of EverSpring. Only up close do its mechanical patterns emerge, together with a rich, lingering plume of incense."
        },
        [70016402] = {
          Camera = "2886.273438,2012.956055,3502.893555,0.000015,5.199823,-141.799973,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "这轮“明月”集悬衡机枢二派技术之大成，实为烟津渡区域的香料动力装置。香在这个装置内挥发，被鼓动吹往四方，维持着大风九章的秩序。",
          DialogueId = 70016402,
          Duration = 5,
          GUID = "AF4759F4",
          Subtitle = "This \"moon\" draws upon the finest techniques of both the Xuanheng and Jishu sects, and is in truth the Incense-Powered Device of Mistwharf. Incense vapour is released within and channelled outward, its influence carried across the land to uphold the order of the Nine Chapters of Dafeng."
        },
        [70016501] = {
          Camera = "29.942383,-19.513672,525.364014,0.000019,28.799376,-80.196136,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "不见天日的潮声岩穴反而能催生出大型的发光植物，这就是生命对于光明的永恒向往吗？",
          DialogueId = 70016501,
          Duration = 5,
          GUID = "AF476A32",
          NextDialogue = 70016502,
          Subtitle = "In the lightless depths of Tidesong Cavern, a great luminous plant somehow flourishes — perhaps a quiet testament to life's eternal yearning for the light."
        },
        [70016502] = {
          Camera = "29.942383,-19.513672,525.364014,0.000019,28.799376,-80.196136,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "它悬于岩顶，将皎洁而微弱的光辉洒往洞穴中，为偶尔路过的行人提供前路的指引。",
          DialogueId = 70016502,
          Duration = 5,
          GUID = "AF476A5C",
          Subtitle = "Suspended from the cavern ceiling, it spills a soft, pale glow into the darkness, guiding any traveller who passes below."
        },
        [70016601] = {
          Camera = "745.375,17.552734,2003.395996,0.000002,7.399881,175.19902,13.0,100000.0,false,DoNotOverride,2.8",
          Content = "搁浅于微茫市的大型沉船，外表看上去已腐朽废弃，毫无生气，其内却别有洞天。被此处的主人虬先生改造为自己的居所，名为“潜龙居”。",
          DialogueId = 70016601,
          Duration = 5,
          GUID = "AF477A9A",
          Subtitle = "A large shipwreck that lies stranded in Haze Market. Its hull appears decayed and lifeless, yet its interior hides a world of its own. Its owner, Mr Qiu, has refashioned it into his dwelling, naming it \"The Hidden Loong\"."
        },
        [70016701] = {
          Camera = "909.160156,-79.808594,2942.352051,0.000001,-4.80014,-178.998611,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "岁月能摧折大部分事物，使其失去原本功能，但显然有一些永恒的造物能够超越时间。",
          DialogueId = 70016701,
          Duration = 5,
          GUID = "AF478B02",
          NextDialogue = 70016702,
          Subtitle = "Time wears down most things, stripping them of their purpose, yet some creations endure beyond the grasp of ages."
        },
        [70016702] = {
          Camera = "909.160156,-79.808594,2942.352051,0.000001,-4.80014,-178.998611,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "机枢派的研究重地被毁数百年后，此地的机括战阵核心依然悬于听鸦原的上空，抵御着一切外来入侵者——纵使它的创造者早已泯于历史的尘埃之中。",
          DialogueId = 70016702,
          Duration = 5,
          GUID = "AF478B2C",
          Subtitle = "Centuries after the Jishu Sect's research grounds fell to ruin, the array's core still hangs above Crowsong Hollow, driving back all intruders long after its creators have vanished from history."
        },
        [70016801] = {
          Camera = "1339.019531,976.865234,1511.71582,0.000001,3.999799,-138.800369,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "尘漠石海中部的香塔，建于上一次烛阴之灾期间，曾用于净化局部空气，延缓尘漠蔓延的速度。",
          DialogueId = 70016801,
          Duration = 5,
          GUID = "AF479B6A",
          NextDialogue = 70016802,
          Subtitle = "An Incense Tower that stands within the heart of the Gritblight Expanse. Built during the last occurrence of the Scourge of Zhuyin, it once served to purify the air and slow the advance of Gritblight."
        },
        [70016802] = {
          Camera = "1339.019531,976.865234,1511.71582,0.000001,3.999799,-138.800369,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "以其倒塌在这片荒漠中的现状，结局已不明自言。",
          DialogueId = 70016802,
          Duration = 5,
          GUID = "AF479B94",
          Subtitle = "Now collapsed into the sands, its condition speaks for itself."
        },
        [70016901] = {
          Camera = "-970.289062,2657.070312,1862.426758,0.000044,17.199194,-63.00082,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "曾经生长于此地的巨树，受烛阴之灾的殃及，其树表如今已被厚厚一层结晶化的尘漠所覆盖。",
          DialogueId = 70016901,
          Duration = 5,
          GUID = "AF47ABD2",
          NextDialogue = 70016902,
          Subtitle = "A giant tree that once thrived here, but was ultimately corrupted by the Scourge of Zhuyin. Its bark is now sealed beneath a thick crust of crystallised Gritblight."
        },
        [70016902] = {
          Camera = "-970.289062,2657.070312,1862.426758,0.000044,17.199194,-63.00082,11.88,100000.0,false,DoNotOverride,2.8",
          Content = "它的生命永远停滞在了这个时刻，枝叶也不再舒张，以无声的沉默警告一切活物不要踏入此地。",
          DialogueId = 70016902,
          Duration = 5,
          GUID = "AF47ABFC",
          Subtitle = "Its life has been frozen in this final moment. Its leaves will never rustle again, offering a silent warning to all living things not to set foot here."
        },
        [70017001] = {
          Camera = "-194.170898,571.792969,277.285156,0.000037,16.40015,-66.80262,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "曾用于驱逐烛阴的祭坛。受烛阴泄漏而出力量的影响，扭曲的蜃影在此处久久不散。烛阴的悲鸣和吼叫如同幻痛般印刻在每个到访者的心灵之中。",
          DialogueId = 70017001,
          Duration = 5,
          GUID = "AF47BC3A",
          Subtitle = "An altar once used to repel Zhuyin. Its runaway energies have left distorted mirages lingering here. Zhuyin's wails and roars echo like a phantom ache in the minds of all who draw near."
        },
        [70017101] = {
          Camera = "233.236328,49.142578,328.026367,0.000006,-47.99913,-169.796097,35.0,404.294037,false,DoNotOverride,2.8",
          Content = "散落于桌上的医学笔记，纸张看起来有些年头，显然被人翻阅过多次。纸张的空白处以蝇头小字密密麻麻地写满了批注。仔细看可以发现字迹分属二人，较新字迹的归属人似乎是药理的初学者。",
          DialogueId = 70017101,
          Duration = 5,
          GUID = "AF47CCA2",
          NextDialogue = 70017102,
          Subtitle = "Medical notes that lie scattered across the desk. The pages are visibly aged and well-thumbed, with cramped annotations crowding every blank space. A closer look reveals two distinct hands — the newer notes appear to belong to a novice in pharmacology."
        },
        [70017102] = {
          Camera = "233.236328,49.142578,328.026367,0.000006,-47.99913,-169.796097,35.0,404.294037,false,DoNotOverride,2.8",
          Content = "笔记的落款处以娟秀的字迹写着“扶风”二字。",
          DialogueId = 70017102,
          Duration = 5,
          GUID = "AF47CCCC",
          Subtitle = "At the end of the notes, the signature \"Fufeng\" is written in an elegant hand."
        },
        [70017201] = {
          Camera = "-86.421875,207.039062,257.314453,0.000016,-39.599575,-81.797188,25.0,100000.0,false,DoNotOverride,2.8",
          Content = "枯荣阁外面对庭院露天放置的古筝。只要看到这幅景象，就能想象出此间主人午后在这里抚一首琴曲，清风拂面的雅致。",
          DialogueId = 70017201,
          Duration = 5,
          GUID = "AF47DD0A",
          Subtitle = "A zheng that stands outdoors in the Hall of Ephemerality's courtyard. One glance at it is enough to evoke the image of its owner playing a quiet melody here on a gentle afternoon, the breeze brushing softly past."
        },
        [70017301] = {
          Camera = "-356.626953,463.605469,232.6875,0.000018,-4.400076,-38.39875,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "装有多格药草的药柜，似乎很少被使用。苦涩的气味十分冲脑醒神。",
          DialogueId = 70017301,
          Duration = 5,
          GUID = "AF47ED72",
          Subtitle = "A medicine cabinet stocked with herbs divided into neat compartments. It appears rarely used. A sharp, astringent scent rises from within, clearing the mind of anyone who comes near."
        },
        [70017401] = {
          Camera = "-423.304688,2.398438,413.355469,0.000008,-43.799706,9.802094,35.0,100000.0,false,DoNotOverride,2.8",
          Content = "供病人休憩的床铺，洁净无尘，被褥被一丝不苟地叠放好。靠近后能闻到一股似有若无的香气，与此间主人的气质非常相称。",
          DialogueId = 70017401,
          Duration = 5,
          GUID = "AF47FDDA",
          Subtitle = "A spotless sickbed kept ready for any patient in need. The bed is made with meticulous care. A faint, lingering fragrance hangs in the air around it, wholly in keeping with its owner's temperament."
        },
        [70017501] = {
          Camera = "641.003906,-32.821289,236.93042,0.0,-0.200043,179.599518,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "小巧的祠台，是华胥人用于悼念逝去亲人，供奉小小祭品的去处。",
          DialogueId = 70017501,
          Duration = 5,
          GUID = "AF480E42",
          NextDialogue = 70017502,
          Subtitle = "This small altar is where the people of Huaxu come to honour lost loved ones and offer simple tributes."
        },
        [70017502] = {
          Camera = "641.003906,-32.821289,236.93042,0.0,-0.200043,179.599518,15.0,100000.0,false,DoNotOverride,2.8",
          Content = "在他们看不见的角落，无由生早已大大方方地入住了这里——这份怀有对亲人思念的祭品，就由我们代为收下吧。",
          DialogueId = 70017502,
          Duration = 5,
          GUID = "AF480E6C",
          Subtitle = "Unseen by them, a group of Wishen have long since taken up residence here, quietly claiming the place as their own. As for this offering, left in remembrance of the departed... we shall accept it in their stead."
        },
        [71000000] = {
          ContentES = "Miau…",
          DialogueId = 71000000,
          Duration = 3,
          GUID = "B1BDB580",
          SpeakNpcId = 800002,
          Subtitle = "Meow..."
        },
        [71000100] = {
          ContentES = "Un gato callejero maúlla con tristeza, como si intentara llamar la atención de algún alma compasiva.",
          DialogueId = 71000100,
          GUID = "B1BDC5E8",
          SpeakNpcId = 800006,
          Subtitle = "(A stray cat meows forlornly, as if hoping to catch the attention of a kind-hearted passer-by.)"
        },
        [71000200] = {
          ContentES = "Disculpe, ¿vende comida para gatos?",
          DialogueId = 71000200,
          GUID = "B1BDD650",
          NextDialogue = 710002001,
          SpeakNpcId = 100001,
          Subtitle = "Hello, do you sell cat food here?"
        },
        [71000210] = {
          ContentES = "Disculpe, ¿vende comida para gatos?",
          DialogueId = 71000210,
          GUID = "B1BDD7F4",
          NextDialogue = 710002101,
          SpeakNpcId = 100001,
          Subtitle = "Excuse me, do you sell cat food here?"
        },
        [71000220] = {
          ContentES = "(Colocas la comida frente al gato.)",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001,
          Subtitle = "(Put down some cat food)"
        },
        [71000300] = {
          ContentES = "(El gato da un salto, se aleja unos pasos y luego se detiene para mirarte, como si te invitara a seguirlo.)",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000310] = {
          ContentES = "(El gato da un salto, se aleja unos pasos y luego se detiene para mirarte, como si te invitara a seguirlo.)",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000320] = {
          ContentES = "(El gato da un salto, se aleja unos pasos y luego se detiene para mirarte, como si te invitara a seguirlo.)",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000330] = {
          ContentES = "(El gato da vueltas alegremente alrededor de tus pies. Su expresión satisfecha calienta tu alma y te llena de una extraña serenidad.)",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006,
          Subtitle = "(The cat circles around your feet, obviously happy and content. A warm sense of peace and joy fills your heart.)"
        },
        [71000501] = {
          ContentES = "¡Eh, deténganse! Si no, tendré que usar mi carta secreta… Bueno, ustedes lo quisieron— ¡AYUDA! ¡AAAH!",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005,
          Subtitle = "Hey, stop it! Or I'll have to pull out my secret weapon... Alright, you asked for this — HELP! AAHHH!!!"
        },
        [71000502] = {
          ContentES = "Buaaaah…",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005,
          Subtitle = "Waaahhh..."
        },
        [71000503] = {
          ContentES = "Listo, ese era el último.",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014,
          Subtitle = "That was the last of them. All clear."
        },
        [71000504] = {
          ContentES = "Iré a comprobar si aún hay enemigos merodeando por la zona. Ten cuidado.",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014,
          Subtitle = "I'll go check if there are any more enemies nearby. Be careful on your own."
        },
        [71000505] = {
          ContentES = "¡Recibido! ¡Tendré cuidado",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015,
          Subtitle = "Got it! I'll stay sharp!"
        },
        [71000506] = {
          ContentES = "Oh, tú también has venido… snif… No pensé que vendría tanta gente a ayudarme… Aquí tienen un pequeño obsequio como agradecimiento. ¡Gracias a todos! ¡Son los mejores!",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015,
          Subtitle = "Aww, you're here too... *sob*... I can't believe so many people are willing to help me. Here's a little something for your trouble. Thanks, everyone! You guys are the best!"
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Gracias! Me has sacado de un buen apuro… ¡Volvamos a la aventura!",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          Subtitle = "Thank you, I'm safe now! On to more adventures!",
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Gracias! Me has sacado de un buen apuro… ¡Volvamos a la aventura!",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          Subtitle = "Thank you, I'm safe now! On to more adventures!",
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentES = "(Varios barriles arrastrados por las olas se amontonan en la playa. Si los registras, podrías encontrar algo útil.)",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006,
          Subtitle = "(Barrels washed ashore line the beach. Maybe they hold something useful.)"
        },
        [71000612] = {
          ContentES = "(El fondo de este barril está destrozado. Sea cual sea la riqueza que contuviera antes, ahora no es más que un trozo de chatarra. Será mejor revisar otro.)",
          DialogueId = 71000612,
          GUID = "B1BE19E8",
          Subtitle = "(This barrel has a gaping hole in the bottom. Whatever treasure it once held is long gone. Better try another.)"
        },
        [71000613] = {
          ContentES = "(Este barril no contiene más que peces y camarones podridos. Será mejor revisar otro.)",
          DialogueId = 71000613,
          GUID = "B1BE1A12",
          Subtitle = "(Nothing but rotten fish and shrimp in this one. Better try another.)"
        },
        [71000615] = {
          ContentES = "(La perseverancia da sus frutos: al registrar con cuidado, descubres en un escondite oculto algunos recursos que aún pueden aprovecharse.)",
          DialogueId = 71000615,
          GUID = "B1BE1A66",
          Subtitle = "(Patience pays off. After a meticulous search, you spot a hidden compartment — and inside, a stash of usable supplies.)"
        },
        [71000701] = {
          ContentES = "Qué fastidio… solo me quedaban unas cuantas tuberías por revisar.",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007,
          Subtitle = "Dang it! Just a few more to go, and now this."
        },
        [71000710] = {
          ContentES = "¿Qué ocurre?",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001,
          Subtitle = "What happened?"
        },
        [71000711] = {
          ContentES = "Tengo que inspeccionar las tuberías de Phoxichor que abastecen a la ciudad.",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007,
          Subtitle = "I was checking the condition of the Phoxichor pipes that connect the city."
        },
        [71000721] = {
          ContentES = "Pero mi cuerda de seguridad se rompió en la tubería anterior… ¿Podrías subir a revisar las últimas por mí?",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007,
          Subtitle = "I've only got a few left, but my safety rope just snapped. Could you go check the rest of the pipes for me?"
        },
        [71000741] = {
          ContentES = "He marcado las tuberías restantes. ¡Me salvas la vida!",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007,
          Subtitle = "I've marked the remaining pipes for you. I'm counting on you!"
        },
        [71000751] = {
          ContentES = "(Esta tubería está en buen estado. Vamos a revisar la siguiente.)",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006,
          Subtitle = "(This pipe's in good shape. Let's go check the next one.)"
        },
        [71000761] = {
          ContentES = "(La última también parece estar en buen estado. Es hora de volver e informar al obrero.)",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006,
          Subtitle = "(The last one looks good too. Time to go back and inform the fitter.)"
        },
        [71000771] = {
          ContentES = "¿Todo bien? ¡Son excelentes noticias! ¡Muchísimas gracias!",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007,
          Subtitle = "All good? That's great news! Thank you so much!"
        },
        [71000780] = {
          ContentES = "(Esta tubería presenta una ligera fisura. Será mejor avisar al obrero.)",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006,
          Subtitle = "(This pipe has been slightly damaged. Better inform the fitter.)"
        },
        [71000781] = {
          ContentES = "Uf… más horas extra. Toma, coge mi llave y ve cerrando la válvula principal de Phoxichor mientras busco mis herramientas.",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007,
          Subtitle = "Oof... Looks like I'll be working overtime again. Here, take my key and shut off the main Phoxichor valve while I grab my tools."
        },
        [71000782] = {
          ContentES = "Gracias, me hago cargo.",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007,
          Subtitle = "Thank you. I'll take it from here."
        },
        [71000801] = {
          ContentES = "¡{nickname}, {nickname}, rápido! ¡He encontrado un nuevo tema de investigación!",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011,
          Subtitle = "Hey, ! Come quick — I've found something amazing! A brand new research subject!"
        },
        [71000802] = {
          ContentES = "El material que necesito está al otro lado del lago. ¿Podrías ayudarme a recogerlo?",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011,
          Subtitle = "The material I need is way across the lake. Would you mind helping me grab some?"
        },
        [71000803] = {
          ContentES = "Esto debería ser lo que busca Theo. Es hora de llevárselo.",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001,
          Subtitle = "This should be what Theo's looking for. Time to bring it back."
        },
        [71000804] = {
          ContentES = "¡Gracias! Para convertirme en un gran alquimista, todavía hay tanto que aprender… ¡pero lo lograré!",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011,
          Subtitle = "Thank you! To become a great alchemist, there's still sooo much I've got to learn... But I'll get there!"
        },
        [71000805] = {
          ContentES = "¡Ah, ya entiendo! ¡La primera lección para ser un gran alquimista: encontrar tus materiales por ti mismo!",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011,
          Subtitle = "Oh... I see. Well, I guess that's lesson number one for any great alchemist — gather your own materials! Got it!"
        },
        [71000901] = {
          ContentES = "¡Al escondite! ¡Al escondite! ¡Ven a jugar con nosotros!",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008,
          Subtitle = "Hide and seek! Come and play hide and seek!"
        },
        [71000902] = {
          ContentES = "¡Al escondite! ¡Al escondite! ¡Ven a jugar con nosotros!",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          Subtitle = "Hide and seek! Come and play hide and seek!",
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          ContentES = "¡De acuerdo! ¡Pero no quiero buscar, quiero esconderme!",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          Subtitle = "I'm in! But I don't want to be the seeker, I want to hide!",
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          ContentES = "¡Yo también! He encontrado un escondite genial… ¡Esta vez seguro que gano!",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          Subtitle = "Me too! I've found a super secret spot. I'm sure to win this time!",
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          ContentES = "Pero ¿quién va a buscar? … ¿Hay alguien que quiera jugar con nosotros?",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009,
          Subtitle = "But we need a seeker... Anyone else up for a game with us?"
        },
        [71000906] = {
          ContentES = "(Los niños te ven al pasar y te miran con ilusión, esperando tu respuesta.)",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006,
          Subtitle = "(The kids notice you passing by, their eyes wide with hope, eagerly waiting for your response.)"
        },
        [71000907] = {
          ContentES = "(Los niños dan saltos de alegría y desaparecen en un abrir y cerrar de ojos al doblar la esquina. Es hora de pensar dónde podrían haberse escondido.)",
          DialogueId = 71000907,
          GUID = "B1BE4A4E",
          Subtitle = "(The children cheer excitedly and vanish around the corner in the blink of an eye. Time to find them!)"
        },
        [71000908] = {
          ContentES = "¡Guau, eso fue rápido!",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008,
          Subtitle = "Wow, that was quick!"
        },
        [71000909] = {
          ContentES = "¡Eres realmente {性别:bueno|buena} en esto!",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009,
          Subtitle = "You're really good at this!"
        },
        [71000910] = {
          ContentES = "Uf, he perdido…",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010,
          Subtitle = "Ugh, can't believe I lost..."
        },
        [71000911] = {
          ContentES = "Bueno, vale, he perdido, así es el juego… Toma, aquí tienes tu recompensa. ¡Vuelve a jugar con nosotros otra vez!",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008,
          Subtitle = "Alright, you win. Here's your prize. Come play with us again sometime!"
        },
        [71001001] = {
          ContentES = "(Un coche reluciente y completamente nuevo está ahí, abandonado. ¿Será… una oportunidad de oro?)",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006,
          Subtitle = "(A brand-new vehicle sits unattended. Could this be... a golden opportunity?)"
        },
        [71001002] = {
          ContentES = "(El depósito de Phoxichor está lleno hasta el borde… ¡Sin duda, una auténtica ganga!)",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006,
          Subtitle = "(The car's got a full canister of Phoxichor — jackpot!)"
        },
        [71001003] = {
          ContentES = "¡Eh! ¿Qué estás haciendo?! ¡Rápido, pidan refuerzos!",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010,
          Subtitle = "What do you think you're doing!? Guys, I need support!"
        },
        [71001004] = {
          ContentES = "(Ya nadie puede detenerte. Abres la puerta, te haces con el depósito de Phoxichor y te marchas con un buen botín. Todo sale según lo previsto… ¡qué día tan afortunado!)",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006,
          Subtitle = "(With no one left to stop you, you pry open the door, grab the Phoxichor Canister, and walk away with a small fortune. Everything's going smooth. What a lucky day.)"
        },
        [71001005] = {
          ContentES = "(Al final, tu conciencia se impone. Decides informar a los guardias de la puerta de la ciudad sobre la brecha de seguridad.)",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006,
          Subtitle = "(Your better angels prevail. You decide to report the security lapse to the guards at the city gate.)"
        },
        [71001006] = {
          ContentES = "Gracias por avisarnos. Reforzaremos las patrullas de inmediato. Acepta este pequeño obsequio como muestra de nuestro agradecimiento.",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010,
          Subtitle = "Thank you for bringing this to our attention. I'll send more patrols right away. Please accept this small gift as a gesture of gratitude from us."
        },
        [71001101] = {
          ContentES = "(¡Los Filthoids se acercan! ¡Repélelos!)",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006,
          Subtitle = "(Filthoids incoming! Dispel them!)"
        },
        [71001201] = {
          ContentES = "(Las malas hierbas han cubierto las huellas que tú y Berry dejasteis aquí. Tal vez sea hora de despejar los alrededores de la estatua.)",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006,
          Subtitle = "(Overgrown weeds have swallowed the traces of the memories you once shared here with Berry. Perhaps it's time to clear the shrine's surroundings.)"
        },
        [71001202] = {
          ContentES = "(Gracias a tus esfuerzos, la estatua recupera su pureza, tal como la recuerdas.)",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006,
          Subtitle = "(The weeds are gone. The shrine stands pristine once more — just as you remember it.)"
        },
        [71001301] = {
          ContentES = "Según Berry, aquí es donde vivíamos antes… pero no tengo ningún recuerdo.",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001,
          Subtitle = "Berry said this is where we used to live, but I can't remember a thing..."
        },
        [71001302] = {
          ContentES = "Tal vez debería explorar un poco los alrededores. Con un poco de suerte, algo me vendrá a la memoria.",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001,
          Subtitle = "Maybe if I look around, something will jog my memory."
        },
        [71001303] = {
          ContentES = "Los muebles son muy rudimentarios. Muchos clavos están profundamente clavados en la madera, exactamente como las manijas de las puertas de nuestro pueblo. Berry debía tener una fuerza increíble incluso de niña.",
          DialogueId = 71001303,
          GUID = "B1BE8B46",
          Subtitle = "The furniture looks pretty rough — lots of nails hammered deep into the wood, just like the door handles back in the village. Berry must have been incredibly strong even as a kid."
        },
        [71001304] = {
          ContentES = "Vaya… ¿un libro de cuentos sobre alquimia? Así que de aquí venían todas esas historias extrañas que me contaba antes de dormir.",
          DialogueId = 71001304,
          GUID = "B1BE8B70",
          NextDialogue = 71001305,
          Subtitle = "Wait, is this... an alchemy storybook? So all those weird bedtime stories Berry told me when we were little came from this."
        },
        [71001305] = {
          ContentES = "Pero estas anotaciones en los márgenes son mucho más cuidadas que la letra de Berry. ¿Quién pudo haberlas escrito?",
          DialogueId = 71001305,
          GUID = "B1BE8B9A",
          Subtitle = "But these notes in the margins are much neater than Berry's handwriting. Who could've written them?"
        },
        [71001306] = {
          ContentES = "Recuerdo muchas cosas sobre Berry… pero de este lugar, no me viene nada a la mente.",
          DialogueId = 71001306,
          GUID = "B1BE8BC4",
          NextDialogue = 71001307,
          SpeakNpcId = 100001,
          Subtitle = "Mm, I'm recalling a lot about Berry, but still nothing about this place."
        },
        [71001307] = {
          ContentES = "No importa. Tal vez algún día los recuerdos regresen por sí solos.",
          DialogueId = 71001307,
          GUID = "B1BE8BEE",
          SpeakNpcId = 100001,
          Subtitle = "Never mind. Maybe it'll come back to me someday."
        },
        [71001401] = {
          ContentES = "(El aroma de las Bayas boreales llega a tus narices desde lejos. Si recoges algunas, podrías venderlas a buen precio.)",
          DialogueId = 71001401,
          Duration = 4,
          GUID = "B1BE9B5A",
          SpeakNpcId = 800006,
          Subtitle = "(You catch the fragrant aroma of Borealberries from afar. If you pick some, you could make a small fortune.)"
        },
        [71001402] = {
          ContentES = "(Estas Bayas boreales son vibrantes y jugosas. No hay duda de que estas delicias se venderán fácilmente.)",
          DialogueId = 71001402,
          Duration = 4,
          GUID = "B1BE9B84",
          SpeakNpcId = 800006,
          Subtitle = "(These Borealberries are vibrant and plump. It's clear these seasonal delights will fetch a good price anywhere.)"
        },
        [71001403] = {
          ContentES = "(Dos comerciantes más están ocupados en la distancia, también buscando comprar Bayas boreales. Tal vez convenga hablar con ambos antes de decidir a quién vender.)",
          DialogueId = 71001403,
          Duration = 4,
          GUID = "B1BE9BAE",
          SpeakNpcId = 800006,
          Subtitle = "(You notice two traders nearby looking to buy Borealberries. Maybe it's worth talking to them both before deciding who to sell to.)"
        },
        [71001404] = {
          ContentES = "Mi puesto en Lago Helado lleva años funcionando. Las ganancias son modestas, pero todos mis clientes son habituales. Tomaré toda tu cosecha, será un buen trato y podremos ayudarnos en el futuro.",
          DialogueId = 71001404,
          GUID = "B1BE9BD8",
          NextOptions = {
            [1] = 710014041,
            [2] = 710014042
          },
          SpeakNpcId = 818002,
          Subtitle = "I've been running this little stall in Icelake for years. Just a small business — it makes more friends than money. I mean, we can look out for each other in this city, am I right?"
        },
        [71001405] = {
          ContentES = "¡Eh! Veo tus Bayas boreales. Puedo pagar mucho más que esos comerciantes locales tacaños. ¿Hacemos un buen trato juntos?",
          DialogueId = 71001405,
          GUID = "B1BE9C02",
          NextOptions = {
            [1] = 710014051,
            [2] = 710014052
          },
          SpeakNpcId = 818003,
          Subtitle = "Hey there, I see you've got some Borealberries. I can pay way more than those penny-pinching local traders. How about we make some serious cash together, huh?"
        },
        [71001406] = {
          ContentES = "(Priorizando relaciones a largo plazo, cierras el trato con el comerciante local a pesar de la menor ganancia.)",
          DialogueId = 71001406,
          Duration = 3,
          GUID = "B1BE9C2C",
          SpeakNpcId = 800006,
          Subtitle = "(Prioritising long-term connections, you make the deal with the local trader despite the lower profit.)"
        },
        [71001407] = {
          ContentES = "(Las promesas de beneficios futuros no son tan confiables como las ganancias inmediatas. Cierras el trato con el comerciante forastero y obtienes una buena suma.)",
          DialogueId = 71001407,
          Duration = 4,
          GUID = "B1BE9C56",
          SpeakNpcId = 800006,
          Subtitle = "(Promises of future benefits aren't as reliable as immediate gains. You make the deal with the out-of-town trader and walk away with a hefty sum.)"
        },
        [71001501] = {
          ContentES = "Uf… otra vez esto.",
          DialogueId = 71001501,
          Duration = 3,
          GUID = "B1BEABC2",
          SpeakNpcId = 818006,
          Subtitle = "Ugh... not this again."
        },
        [71001502] = {
          ContentES = "¿Qué pasó?",
          DialogueId = 71001502,
          GUID = "B1BEABEC",
          NextDialogue = 71001503,
          SpeakNpcId = 100001,
          Subtitle = "What happened?"
        },
        [71001503] = {
          ContentES = "Nunca consigo hacerla funcionar. Intenta tú, a ver si el problema es la máquina o yo.",
          DialogueId = 71001503,
          GUID = "B1BEAC16",
          SpeakNpcId = 818006,
          Subtitle = "I can't seem to get this machine working properly. Why don't you give it a try? Let's see if it's the machine or just me."
        },
        [71001504] = {
          ContentES = "Gracias.",
          DialogueId = 71001504,
          Duration = 2,
          GUID = "B1BEAC40",
          SpeakNpcId = 818006,
          Subtitle = "Thank you."
        },
        [71001505] = {
          ContentES = "¡Impresionante! Entonces parece que el problema soy yo…",
          DialogueId = 71001505,
          GUID = "B1BEAC6A",
          SpeakNpcId = 818006,
          Subtitle = "Impressive! Looks like I'm the problem then..."
        },
        [71001506] = {
          ContentES = "¿Eh… funcionó?",
          DialogueId = 71001506,
          Duration = 2,
          GUID = "B1BEAC94",
          SpeakNpcId = 818006,
          Subtitle = "That actually worked?"
        },
        [71001507] = {
          ContentES = "Eh… ¿estás seguro de que un golpe bastaría?",
          DialogueId = 71001507,
          Duration = 2,
          GUID = "B1BEACBE",
          SpeakNpcId = 818006,
          Subtitle = "Um... are you sure a smack would work?"
        },
        [71001508] = {
          ContentES = "Espera… ¿no se ha desprendido una pieza?",
          DialogueId = 71001508,
          Duration = 2,
          GUID = "B1BEACE8",
          SpeakNpcId = 818006,
          Subtitle = "Wait, did a part just fly off?"
        },
        [71001509] = {
          ContentES = "Increíble… ¡realmente funcionó!",
          DialogueId = 71001509,
          GUID = "B1BEAD12",
          SpeakNpcId = 818006,
          Subtitle = "Wow, you've got the magic touch!"
        },
        [71001601] = {
          ContentES = "Tantos Filthoids… ¿qué voy a hacer…?",
          DialogueId = 71001601,
          Duration = 3,
          GUID = "B1BEBC2A",
          SpeakNpcId = 818004,
          Subtitle = "So many Filthoids... What am I going to do...?"
        },
        [71001602] = {
          ContentES = "¿Qué pasó?",
          DialogueId = 71001602,
          GUID = "B1BEBC54",
          NextDialogue = 71001603,
          SpeakNpcId = 100001,
          Subtitle = "What's wrong?"
        },
        [71001603] = {
          ContentES = "Guau, por tu equipo, debes ser {性别:un Phoxcazador habilidoso|una Phoxcazadora habilidosa}, ¿verdad? En realidad… yo también soy una Phoxcazadora, pero soy demasiado débil…",
          DialogueId = 71001603,
          GUID = "B1BEBC7E",
          NextDialogue = 71001604,
          SpeakNpcId = 818004,
          Subtitle = "Wow, judging by your gear, you must be a really skilled Phoxhunter, right? Actually... I'm a Phoxhunter myself, but I'm not very strong..."
        },
        [71001604] = {
          ContentES = "¿Podrías ayudarme a recuperar mi arma en medio de estos Filthoids? Si no, ni siquiera podré aceptar mi próximo encargo…",
          DialogueId = 71001604,
          GUID = "B1BEBCA8",
          NextDialogue = 71001605,
          SpeakNpcId = 818004,
          Subtitle = "Could you help me retrieve my weapon from those Filthoids? If I don't get it back, I won't be able to take on my next commission..."
        },
        [71001605] = {
          ContentES = "… Te ayudaré.",
          DialogueId = 71001605,
          GUID = "B1BEBCD2",
          NextDialogue = 71001606,
          SpeakNpcId = 100001,
          Subtitle = "...Sure, I'll help you out."
        },
        [71001606] = {
          ContentES = "¡Muchísimas gracias!",
          DialogueId = 71001606,
          GUID = "B1BEBCFC",
          SpeakNpcId = 818004,
          Subtitle = "Thank you so much!"
        },
        [71001607] = {
          ContentES = "Los Filthoids están justo enfrente. Ten cuidado.",
          DialogueId = 71001607,
          Duration = 3,
          GUID = "B1BEBD26",
          SpeakNpcId = 818004,
          Subtitle = "They're just up ahead. Be careful!"
        },
        [71001608] = {
          ContentES = "Snif... Si no la recupero, ¿cómo voy a ganarme la vida…? No he comido bien en días…",
          DialogueId = 71001608,
          GUID = "B1BEBD50",
          NextOptions = {
            [1] = 710016081,
            [2] = 710016082
          },
          SpeakNpcId = 818004,
          Subtitle = "*sob* If I can't take it back, how am I supposed to make a living...? I haven't had a proper meal in days..."
        },
        [71001609] = {
          ContentES = "¡Gracias! Me voy a hacer mi encargo. ¡Hasta pronto!",
          DialogueId = 71001609,
          GUID = "B1BEBD7A",
          SpeakNpcId = 818004,
          Subtitle = "Thank you! I'm off to my next commission. Take care!"
        },
        [71001610] = {
          ContentES = "Sé toda la historia. ¿Estás seguro de que es buena idea devolverle su arma a esta joven Phoxcazadora? Con su fuerza, podría morir en su próxima encargo. En lugar de eso, ¿por qué no vendérmela a mí? Es la opción más segura para todos.",
          DialogueId = 71001610,
          GUID = "B1BEBDA4",
          NextOptions = {
            [1] = 710016101,
            [2] = 710016102
          },
          SpeakNpcId = 818005,
          Subtitle = "I know the whole story. Are you sure it's a good idea to give her the weapon back? With her strength, she might just die on her next commission. So, why not sell the weapon to me? It's the safer option for everyone."
        },
        [71001611] = {
          ContentES = "¡Gracias! Espero que podamos hacer negocios juntos otra vez.",
          DialogueId = 71001611,
          GUID = "B1BEBDCE",
          SpeakNpcId = 818005,
          Subtitle = "Thank you! Looking forward to our next deal!"
        },
        [71001701] = {
          ContentES = "¡Eh, pero si es {nickname}! ¡Ven rápido!",
          DialogueId = 71001701,
          GUID = "B1BECC92",
          SpeakNpcId = 818012,
          Subtitle = "Oh, hey! Isn't that ? Come here!"
        },
        [71001702] = {
          ContentES = "Hmm, tengo investigaciones importantes que hacer aquí. Protégeme mientras trabajo, ¿sí?",
          DialogueId = 71001702,
          GUID = "B1BECCBC",
          NextOptions = {
            [1] = 710017021,
            [2] = 710017022
          },
          SpeakNpcId = 818012,
          Subtitle = "I've got some serious research to do here. Can you protect me while I work?"
        },
        [71001703] = {
          ContentES = "¿Por qué siempre aparecen molestos justo cuando estoy concentrada en mis estudios? ¡Te toca! Estoy a punto de hacer un descubrimiento crucial.",
          DialogueId = 71001703,
          GUID = "B1BECCE6",
          SpeakNpcId = 818012,
          Subtitle = "Why do baddies always show up when I'm in the middle of research? I'm counting on you! I'm just getting to the bottom of it."
        },
        [71001704] = {
          ContentES = "Entonces, aquí así… y por aquí… Hmm… Sí, casi… ¡un poco más de paciencia!",
          DialogueId = 71001704,
          GUID = "B1BECD10",
          SpeakNpcId = 818012,
          Subtitle = "Let's see... Hmm... Huh... Almost there! Hang in there!"
        },
        [71001705] = {
          ContentES = "¡Perfecto, eso es! ¡Investigación terminada! ¡Yuju!",
          DialogueId = 71001705,
          GUID = "B1BECD3A",
          SpeakNpcId = 818012,
          Subtitle = "That's a wrap! Research successfully complete! Hooray!"
        },
        [71001706] = {
          ContentES = "Menos mal que estabas aquí. Mi expedición ha sido todo un éxito gracias a ti. Toma, un pequeño regalo para agradecerte. ¡La próxima vez volvamos a hacer equipo!",
          DialogueId = 71001706,
          GUID = "B1BECD64",
          SpeakNpcId = 818012,
          Subtitle = "I couldn't have done it without you! Here's a little something for your trouble~ Let's team up again next time!"
        },
        [71001707] = {
          ContentES = "Oh… si no te quedas conmigo, será mejor que me vaya rápido. Este lugar me da un poco de escalofríos…",
          DialogueId = 71001707,
          GUID = "B1BECD8E",
          SpeakNpcId = 818012,
          Subtitle = "Oh... Well, if you won't stick around, I'd better leave. This place gives me the creeps..."
        },
        [71001801] = {
          ContentES = "Vamos, señor, todo está bien. Está exagerando.",
          DialogueId = 71001801,
          GUID = "B1BEDCFA",
          NextDialogue = 71001802,
          SpeakNpcId = 818059,
          Subtitle = "Come on, sir — it's not that deep. You're reading too much into it."
        },
        [71001802] = {
          ContentES = "¿Exagerar? ¿Acaso no ve el peligro que acecha en las sombras? ¡Confiar Lago Helado a su generación es condenarla!",
          DialogueId = 71001802,
          GUID = "B1BEDD24",
          SpeakNpcId = 818009,
          Subtitle = "Reading too much? You lot can't see the danger crawling right under your noses! Icelake's done for with your lot in charge!"
        },
        [71001803] = {
          ContentES = "Tranquilo, señor. ¿Hay algo en lo que pueda ayudarlo?",
          DialogueId = 71001803,
          GUID = "B1BEDD4E",
          NextDialogue = 71001804,
          SpeakNpcId = 100001,
          Subtitle = "Easy, sir. Is there something I can help you with?"
        },
        [71001804] = {
          ContentES = "¡Criminales saliendo de todas partes, se los digo! Cada generación es peor que la anterior.",
          DialogueId = 71001804,
          GUID = "B1BEDD78",
          NextDialogue = 71001805,
          SpeakNpcId = 818009,
          Subtitle = "Criminals — swarming out of the cracks, I tell you! Tch — kids these days, all spineless!"
        },
        [71001805] = {
          ContentES = "Ya que la Oficina de Seguridad prefiere holgazanear, ¡me encargaré yo mismo! Y tú, {性别:chico|chica}, pareces {性别:decidido|decidida}, ¡ven y échame una mano!",
          DialogueId = 71001805,
          GUID = "B1BEDDA2",
          SpeakNpcId = 818009,
          Subtitle = "If the lazy pups at the Security Bureau won't act, then I will! And you — {性别:lad|lass} — you look sharp. Feel like lending an old soldier a hand?"
        },
        [71001806] = {
          ContentES = "Bah...",
          DialogueId = 71001806,
          GUID = "B1BEDDCC",
          SpeakNpcId = 818009,
          Subtitle = "Hmph..."
        },
        [71001807] = {
          ContentES = "Tch…",
          DialogueId = 71001807,
          GUID = "B1BEDDF6",
          SpeakNpcId = 818009,
          Subtitle = "Tch..."
        },
        [71001808] = {
          ContentES = "Tch… esta vez se escondieron bien, ¿eh? ¡Pero no me rendiré! Ustedes más les vale cuidarse…",
          DialogueId = 71001808,
          GUID = "B1BEDE20",
          SpeakNpcId = 818009,
          Subtitle = "Hmph, sneaky little devils... But I'm not done. This city needs justice — and I won't stop till it gets it. You lot better watch your backs..."
        },
        [71001809] = {
          ContentES = "¡Al ataque!",
          DialogueId = 71001809,
          GUID = "B1BEDE4A",
          NextDialogue = 71001810,
          SpeakNpcId = 818011,
          Subtitle = "Now!"
        },
        [71001810] = {
          ContentES = "¡Ah! ¡Las ratas salen de sus agujeros! ¿Lo ves? ¡Lago Helado nunca ha sido seguro! ¡Estos viejos huesos les recordarán lo que es la justicia!",
          DialogueId = 71001810,
          GUID = "B1BEDE74",
          NextDialogue = 71001813,
          SpeakNpcId = 818009,
          Subtitle = "Ha! The rats are out of hiding! Told you — Icelake's never been safe! Time for these old bones to dish out some justice!"
        },
        [71001811] = {
          ContentES = "Gracias, {性别:chico|chica}. Ahora la seguridad de Lago Helado depende solo de tú y yo.",
          DialogueId = 71001811,
          GUID = "B1BEDE9E",
          SpeakNpcId = 818009,
          Subtitle = "You did good, kid. The safety of Icelake rests on shoulders like ours."
        },
        [71001812] = {
          ContentES = "¡Bah! De todos modos no esperaba nada de nadie. Vete.",
          DialogueId = 71001812,
          GUID = "B1BEDEC8",
          SpeakNpcId = 818009,
          Subtitle = "Hmph. Figures. Should've known better than to count on anyone. Off with you, then."
        },
        [71001813] = {
          ContentES = "(Antes de que puedas reaccionar, el anciano se lanza directo contra ellos. Será mejor que lo sigas antes de que esto acabe en una masacre.)",
          DialogueId = 71001813,
          GUID = "B1BEDE75",
          SpeakNpcId = 800006,
          Subtitle = "(Before you can stop him, the old man charges straight in. You'd better follow — before this turns into a bloodbath.)"
        },
        [71001901] = {
          ContentES = "Entonces… ¿realmente cambia algo o no?",
          DialogueId = 71001901,
          GUID = "B1BEED62",
          SpeakNpcId = 818016,
          Subtitle = "Hmm... I wonder if that tweak actually made any difference..."
        },
        [71001902] = {
          ContentES = "¡Ah, qué buen momento! Acabo de ajustar de nuevo el elevador. ¿Podrías probarlo y decirme si te parece más rápido? He subido y bajado tantas veces que ya no siento la diferencia.",
          DialogueId = 71001902,
          GUID = "B1BEED8C",
          SpeakNpcId = 818016,
          Subtitle = "Ah — good timing. I just finished adjusting the lift again. Could you give it a quick ride and tell me if it feels any faster? I've been up and down so many times I honestly can't tell anymore."
        },
        [71001903] = {
          ContentES = "¿Fue tan rápido? Eh… quizás me haya saltado algo. Parece que tendré que hacer un diagnóstico completo otra vez. Gracias por ayudarme con los datos, toma esto como compensación.",
          DialogueId = 71001903,
          GUID = "B1BEEDB6",
          SpeakNpcId = 818016,
          Subtitle = "It went that fast? Huh... maybe I missed something. Looks like I'll have to do a full diagnostic again. Thanks for helping with the data — here, take this for your trouble."
        },
        [71001904] = {
          ContentES = "Realmente no sentí ninguna diferencia.",
          DialogueId = 71001904,
          GUID = "B1BEEDE0",
          NextDialogue = 71001905,
          SpeakNpcId = 100001,
          Subtitle = "Didn't really feel any different."
        },
        [71001905] = {
          ContentES = "Sí… claro. Quizás solo estoy ajustando para tranquilizarme. Gracias por los datos de todas formas, toma esto.",
          DialogueId = 71001905,
          GUID = "B1BEEE0A",
          SpeakNpcId = 818016,
          Subtitle = "Yeah... figures. Maybe I'm just tweaking it for peace of mind at this point. Still — appreciate the feedback. Here, something for your time."
        },
        [71002001] = {
          ContentES = "Jerry, ¿a dónde te has ido ahora…? *snif snif*",
          DialogueId = 71002001,
          GUID = "B1BEFDCA",
          SpeakNpcId = 818017,
          Subtitle = "Jerry! Where did you run off to again...? *sniffles*"
        },
        [71002002] = {
          ContentES = "¿Puedes ayudarme a encontrar a mi <H>gato</>? Debería estar cerca…",
          DialogueId = 71002002,
          GUID = "B1BEFDF4",
          SpeakNpcId = 818017,
          Subtitle = "Could you help me look for my cat? He should still be around here somewhere..."
        },
        [71002003] = {
          ContentES = "(Pronto ves un pequeño gato acurrucado en el suelo, temblando. Parece aterrorizado ante el contacto humano.)",
          DialogueId = 71002003,
          GUID = "B1BEFE1E",
          SpeakNpcId = 800006,
          Subtitle = "(You soon spot a small cat curled up on the ground, trembling. He looks terrified of human contact.)"
        },
        [71002004] = {
          ContentES = "¡Por fin estás aquí, Jerry! ¡Muchísimas gracias!",
          DialogueId = 71002004,
          GUID = "B1BEFE48",
          NextDialogue = 71002005,
          SpeakNpcId = 818018,
          Subtitle = "Oh, Jerry, there you are! Thank you so much!"
        },
        [71002005] = {
          ContentES = "(La joven toma a Jerry en brazos y lo cubre de besos. Finges ignorar al pobre animal, que se retuerce de terror, aceptas tu recompensa y te marchas en silencio.)",
          DialogueId = 71002005,
          GUID = "B1BEFE72",
          SpeakNpcId = 800006,
          Subtitle = "(The girl scoops Jerry into her arms and buries him in kisses. You try not to notice the poor thing wriggling in panic as you quietly accept your reward and slip away.)"
        },
        [71002006] = {
          ContentES = "¿Tampoco tú lo encontraste…? ¡Qué pena! Ese gato callejero que corre por todas partes no puede ser mi Jerry. ¡Le diré a mamá que me compre otro gato, más obediente y más bonito!",
          DialogueId = 71002006,
          GUID = "B1BEFE9C",
          SpeakNpcId = 818018,
          Subtitle = "You couldn't find him either...? Tch, whatever. I don't want a scruffy stray to be my Jerry anyway. I'll just have Mum get me a better cat — even cuter and well-behaved!"
        },
        [71002007] = {
          ContentES = "¡Gracias! Jerry… mi pequeño Jerry…",
          DialogueId = 71002007,
          GUID = "B1BEFEC6",
          SpeakNpcId = 818017,
          Subtitle = "Thank you! Oh, Jerry... please be okay..."
        },
        [71002101] = {
          ContentES = "¡Ah, {nickname}! ¡{性别:Mi salvador|Mi salvadora}, ven rápido a ayudarme!",
          DialogueId = 71002101,
          GUID = "B1BF0E32",
          SpeakNpcId = 818007,
          Subtitle = "! Thank goodness you're here! I need your help!"
        },
        [71002102] = {
          ContentES = "Tengo que entregar esta caja de suministros a mis compañeros al otro lado del Lago Lamentoso, pero de repente me duele horriblemente el estómago. ¿Podrías llevarla por mí? ¡Te lo ruego!",
          DialogueId = 71002102,
          GUID = "B1BF0E5C",
          SpeakNpcId = 818007,
          Subtitle = "I was supposed to deliver this crate of supplies to my colleagues across the Lamenting Lake, but I've suddenly got this terrible stomachache. Could you deliver it for me? Please, I'm begging you!"
        },
        [71002103] = {
          ContentES = "Hola, vengo a entregar los suministros que Kevin me pidió traerles.",
          DialogueId = 71002103,
          GUID = "B1BF0E86",
          NextDialogue = 71002104,
          SpeakNpcId = 100001,
          Subtitle = "Hello, Kevin asked me to bring these supplies to you."
        },
        [71002104] = {
          ContentES = "Un momento… faltan dos cargadores y un fusil. ¡Admítelo, los robaste!",
          DialogueId = 71002104,
          GUID = "B1BF0EB0",
          SpeakNpcId = 818008,
          Subtitle = "Wait a minute... The crate is missing two clips and a rifle. You took them, didn't you?"
        },
        [71002105] = {
          ContentES = "¡Desviar material imperial es un delito grave! ¡Vienes conmigo!",
          DialogueId = 71002105,
          GUID = "B1BF0EDA",
          SpeakNpcId = 818008,
          Subtitle = "Embezzling imperial property is a serious offence. You're coming with me!"
        },
        [71002106] = {
          ContentES = "¿Eh? ¡Me ausenté un minuto para ir al baño y ya están peleándose!",
          DialogueId = 71002106,
          GUID = "B1BF0F04",
          NextDialogue = 71002107,
          SpeakNpcId = 818007,
          Subtitle = "Whoa! I was in the bathroom for a minute, and you're already at each other's throats!"
        },
        [71002107] = {
          ContentES = "Ellos fueron quienes empezaron.",
          DialogueId = 71002107,
          GUID = "B1BF0F2E",
          NextDialogue = 71002108,
          SpeakNpcId = 100001,
          Subtitle = "They started it."
        },
        [71002108] = {
          ContentES = "Mira lo que hizo {性别:este canalla|esta canalla}, ¡hasta tuvo el descaro de robar suministros de la Legión!",
          DialogueId = 71002108,
          GUID = "B1BF0F58",
          NextDialogue = 71002109,
          SpeakNpcId = 818008,
          Subtitle = "Look what this crook did — even had the nerve to steal legion supplies!"
        },
        [71002109] = {
          ContentES = "¿Eh? ¿Oh! ¿Dos cargadores y un fusil? Fui yo, ya los había tomado antes.",
          DialogueId = 71002109,
          GUID = "B1BF0F82",
          NextDialogue = 71002110,
          SpeakNpcId = 818007,
          Subtitle = "Huh? Oh, you mean two clips and a rifle? That's on me. I already took my share earlier."
        },
        [71002110] = {
          ContentES = "No estarás hablando en serio… ¿Entregar suministros de la Legión a un desconocido? ¿Y si fuera {性别:un|una} de Los Abandonados?!",
          DialogueId = 71002110,
          GUID = "B1BF0FAC",
          NextDialogue = 71002111,
          SpeakNpcId = 818008,
          Subtitle = "You're unbelievable! How could you just hand over legion supplies to a random stranger? {性别:He|She} could've been one of The Forsakens!"
        },
        [71002111] = {
          ContentES = "Ah, lo siento. Prometo tener más cuidado la próxima vez.",
          DialogueId = 71002111,
          GUID = "B1BF0FD6",
          NextDialogue = 71002112,
          SpeakNpcId = 818007,
          Subtitle = "Ah, sorry, my bad! Lesson learned — won't happen again!"
        },
        [71002112] = {
          ContentES = "{nickname}, toma esto como compensación. Perdón por haberte metido en este lío.",
          DialogueId = 71002112,
          GUID = "B1BF1000",
          Scripts = "TurnTo{TurnToDescription{\"818007:n(0)\"}}",
          SpeakNpcId = 818007,
          Subtitle = "Here, . Take this as an apology. Sorry for dragging you into this mess."
        },
        [71002113] = {
          ContentES = "¿Intentas ganar tiempo y escapar, eh? Chicos, mantengan un ojo bien atento a {性别:este crío|esta cría}, que no se escape a escondidas.",
          DialogueId = 71002113,
          GUID = "B1BF102A",
          SpeakNpcId = 818008,
          Subtitle = "Trying to stall and slip away, huh? Everyone, keep a close eye on this kid. Don't let {性别:him|her} get away."
        },
        [71002114] = {
          ContentES = "¡Ya volví!",
          DialogueId = 71002114,
          GUID = "B1BF1054",
          NextDialogue = 71002115,
          SpeakNpcId = 818007,
          Subtitle = "I'm back!"
        },
        [71002115] = {
          ContentES = "¿Eh, material faltante? ¡Oh! ¿Dos cargadores y un fusil? Fui yo quien los tomó hace un rato.",
          DialogueId = 71002115,
          GUID = "B1BF107E",
          NextDialogue = 71002116,
          SpeakNpcId = 818007,
          Subtitle = "Huh? Missing supplies? Oh, you mean two clips and a rifle, right? That's on me. I already took my share earlier."
        },
        [71002116] = {
          ContentES = "No estarás hablando en serio… ¿Entregar suministros de la Legión a un desconocido? ¿Y si fuera {性别:un|una} de Los Abandonados?!",
          DialogueId = 71002116,
          GUID = "B1BF10A8",
          NextDialogue = 71002117,
          SpeakNpcId = 818008,
          Subtitle = "You're unbelievable! How could you just hand over legion supplies to a random stranger? {性别:He|She} could've been one of The Forsakens!"
        },
        [71002117] = {
          ContentES = "Ah, lo siento. Prometo tener más cuidado la próxima vez.",
          DialogueId = 71002117,
          GUID = "B1BF10D2",
          NextDialogue = 71002118,
          SpeakNpcId = 818007,
          Subtitle = "Ah, sorry, my bad! Lesson learned — won't happen again!"
        },
        [71002118] = {
          ContentES = "{nickname}, toma esto como compensación. Perdón por haberte metido en este lío.",
          DialogueId = 71002118,
          GUID = "B1BF10FC",
          Scripts = "TurnTo{TurnToDescription{\"818007:n(0)\"}}",
          SpeakNpcId = 818007,
          Subtitle = "Here, . Take this as an apology. Sorry for dragging you into this mess."
        },
        [71002201] = {
          ContentES = "Uf… hoy realmente no tengo ganas de trabajar…",
          DialogueId = 71002201,
          GUID = "B1BF1E9A",
          SpeakNpcId = 818019,
          Subtitle = "Ugh... I really, really don't feel like working today..."
        },
        [71002202] = {
          ContentES = "El jefe y sus “brillantes” ideas otra vez. “¡Que los sabores del restaurante de la Paz Plateada lleguen a todos los hogares!”, dice. ¿Acaso pensó en nosotros, los pobres repartidores?",
          DialogueId = 71002202,
          GUID = "B1BF1EC4",
          NextDialogue = 71002203,
          SpeakNpcId = 818019,
          Subtitle = "The boss and his \"brilliant\" ideas again. \"Bringing Silverpeace flavours to every household,\" he says. Did he ever stop to think about us poor delivery grunts!?"
        },
        [71002203] = {
          ContentES = "¿Necesitas ayuda?",
          DialogueId = 71002203,
          GUID = "B1BF1EEE",
          NextDialogue = 71002204,
          SpeakNpcId = 100001,
          Subtitle = "Need a hand?"
        },
        [71002204] = {
          ContentES = "¡Absolutamente! Si alguien pudiera trabajar en mi lugar, ¡y sin pedir nada a cambio, sería un sueño! Pero bueno… todos sabemos que eso nunca pasa…",
          DialogueId = 71002204,
          GUID = "B1BF1F18",
          NextDialogue = 71002205,
          SpeakNpcId = 818019,
          Subtitle = "Desperately! Ideally, someone to cover my shift — for free. But hey, when does that ever happen?"
        },
        [71002205] = {
          ContentES = "Si realmente quieres ayudar, ¿podrías llevarme algunas cosas? No puedo pagarte, pero te dejaré beber toda el agua que quieras en el Lago Lamentoso.",
          DialogueId = 71002205,
          GUID = "B1BF1F42",
          SpeakNpcId = 818019,
          Subtitle = "If you're really up for it, mind carrying a few things for me? I can't pay you, but hey, I'll treat you to all the water you can drink by Lamenting Lake."
        },
        [71002206] = {
          ContentES = "¡Eh! ¡Miren lo que tenemos aquí, alguien cargando un festín! ¡Hoy nos vamos a dar un banquete, chicos!",
          DialogueId = 71002206,
          GUID = "B1BF1F6C",
          NextDialogue = 71002207,
          SpeakNpcId = 818057,
          Subtitle = "Oi! Look what we've got here — someone carrying a feast. Lucky day, boys!"
        },
        [71002207] = {
          ContentES = "¡No toquen! ¡Estos platos son para los clientes! Si no reciben su comida, todo mi salario del día se va al aire.",
          DialogueId = 71002207,
          GUID = "B1BF1F96",
          NextDialogue = 71002208,
          SpeakNpcId = 818019,
          Subtitle = "No! These are for customers! If they don't get their food, my whole day's pay goes poof!"
        },
        [71002208] = {
          ContentES = "¡Nos da igual, pásanoslos!",
          DialogueId = 71002208,
          GUID = "B1BF1F97",
          NextDialogue = 71002209,
          SpeakNpcId = 818057,
          Subtitle = "Not our problem. Now hand it over."
        },
        [71002209] = {
          ContentES = "¡Alto!",
          DialogueId = 71002209,
          GUID = "B1BF1F98",
          SpeakNpcId = 100001,
          Subtitle = "Back off."
        },
        [71002210] = {
          ContentES = "Uf… menos mal que la sopa no se derramó. Vamos, terminemos esta entrega antes de que pase algo más…",
          DialogueId = 71002210,
          GUID = "B1BF1FC0",
          SpeakNpcId = 818019,
          Subtitle = "Whew... thank goodness the soup didn't spill. C'mon, let's finish this delivery before anything else goes wrong..."
        },
        [71002211] = {
          ContentES = "Vamos, casi terminamos… ¡solo queda una entrega más! En serio, el jefe podría calmarse con sus ideas locas…",
          DialogueId = 71002211,
          GUID = "B1BF20BC",
          SpeakNpcId = 818019,
          Subtitle = "That's another one down! One more to go... Seriously, can't the boss go five minutes without a \"visionary new idea\"?"
        },
        [71002212] = {
          ContentES = "¿Qué es este lío en medio del camino…? ¡Hoy todo me sale mal!",
          DialogueId = 71002212,
          GUID = "B1BF1FEA",
          NextDialogue = 71002218,
          SpeakNpcId = 818019,
          Subtitle = "Ugh — what is all this stuff!? Who even leaves this kind of mess in the middle of the road!?"
        },
        [71002213] = {
          ContentES = "Toma, quédate con los platos. Yo despejaré el camino.",
          DialogueId = 71002213,
          GUID = "B1BF2014",
          SpeakNpcId = 100001,
          Subtitle = "Here. You hold the food. I'll clear the path."
        },
        [71002214] = {
          ContentES = "¿Qué? ¿Ya lo despejaste todo? ¡Aún llegamos a tiempo! ¡Vamos, vamos!",
          DialogueId = 71002214,
          GUID = "B1BF2015",
          SpeakNpcId = 818019,
          Subtitle = "Wait — you cleared it all? We can still make it! GO GO GO!"
        },
        [71002215] = {
          ContentES = "Uf… por fin todo entregado. Sin ti, hoy no habría ganado ni una sola moneda. Bueno… se acabó el descanso, toca volver al trabajo.",
          DialogueId = 71002215,
          GUID = "B1BF203E",
          NextDialogue = 71002216,
          SpeakNpcId = 818019,
          Subtitle = "Phew... all delivered. If it weren't for you, I wouldn't have earned a single coin today. Okay... break's over. Time to get back to work."
        },
        [71002216] = {
          ContentES = "¿No decías que ibas a renunciar?",
          DialogueId = 71002216,
          GUID = "B1BF2068",
          NextDialogue = 71002217,
          SpeakNpcId = 100001,
          Subtitle = "Weren't you just quitting?"
        },
        [71002217] = {
          ContentES = "(Luno, la repartidora sacude el polvo de su ropa y se aleja. La respuesta a tu pregunta se pierde en el pequeño suspiro cansado que deja atrás…)",
          DialogueId = 71002217,
          GUID = "B1BF2092",
          SpeakNpcId = 800006,
          Subtitle = "(The Lunodeliverer brushes off her coat and walks away. The only answer is a long, weary sigh tossed over her shoulder.)"
        },
        [71002218] = {
          ContentES = "¡Estoy harto! Esta vez se lo digo al jefe, ¡este trabajo lo RECHAZO!",
          DialogueId = 71002218,
          GUID = "B1BF1FEB",
          NextDialogue = 71002213,
          SpeakNpcId = 818019,
          Subtitle = "That's it! I quit! I'm going back to tell the boss I'm DONE with this nonsense!"
        },
        [71002301] = {
          ContentES = "Uf… dime que no acabo de romperlo…",
          DialogueId = 71002301,
          GUID = "B1BF2F02",
          SpeakNpcId = 818020,
          Subtitle = "Oof... Please tell me I didn't just break it..."
        },
        [71002302] = {
          ContentES = "¿¡Quién anda ahí!?",
          DialogueId = 71002302,
          GUID = "B1BF2F2C",
          NextDialogue = 71002303,
          SpeakNpcId = 818020,
          Subtitle = "Who's there!?"
        },
        [71002303] = {
          ContentES = "Oh… solo {{性别:un Phoxcazador|una Phoxcazadora} de paso. Ejem… oye, ¿te importaría echarme una mano? Solo hay que probar este aparato, ¡es muy fácil! Te daré una recompensa.",
          DialogueId = 71002303,
          GUID = "B1BF2F56",
          SpeakNpcId = 818020,
          Subtitle = "Oh... just a passing Phoxhunter. Ahem... Say, how about lending me a hand? Just help me test this thing. It won't bite, promise! I'll even toss you a reward for the trouble."
        },
        [71002304] = {
          ContentES = "¡Aguanta 15 segundos y ya está! ¡Vamos, ánimo!",
          DialogueId = 71002304,
          GUID = "B1BF2F80",
          SpeakNpcId = 818020,
          Subtitle = "Just hang in there for 15 seconds — that's all. You've got this!"
        },
        [71002305] = {
          ContentES = "¿Qué? ¿Todos los disparos fallaron!? No puede ser… ¡Juraban que esto era equipo militar de primera de Elysium! Uf, probablemente solo un montón de chatarra elegante. Ah, olvida lo que dije. Aquí tienes tu pago. Y, eh… mantengámoslo entre nosotros, ¿vale?",
          DialogueId = 71002305,
          GUID = "B1BF2FAA",
          SpeakNpcId = 818020,
          Subtitle = "Wait, every shot missed!? No way... They swore this thing was top-grade Elysian military issue! Ugh, probably just some fancy-looking scrap. Ah — forget what I just said. Here's your payment. And, uh... let's keep this between us, yeah?"
        },
        [71002306] = {
          ContentES = "¿Qué? ¡Todos los disparos dieron en el blanco y todavía estás de pie!? Pero juraban que esto era equipo militar de primera de Elysium. Probablemente solo una chatarra sobrevalorada… Ah, olvida lo que acabo de decir. Toma, aquí está tu paga. Y, eh… mantengámoslo entre nosotros, ¿vale?",
          DialogueId = 71002306,
          GUID = "B1BF2FD4",
          SpeakNpcId = 818020,
          Subtitle = "Wait, it landed every shot — and you're still standing!? But they swore this thing was top-grade Elysian military issue! Tch. Probably just some overpriced junk... Ah — forget what I just said. Here's your payment. And, uh... let's keep this between us, yeah?"
        },
        [71002401] = {
          ContentES = "Argh… ¡esta excavadora ya está averiada y ni siquiera ha empezado a trabajar! Pero… ¿dónde está mi kit de reparación?",
          DialogueId = 71002401,
          GUID = "B1BF3F6A",
          SpeakNpcId = 818015,
          Subtitle = "Ugh... why'd the excavator break before it even started working!? Where did I put that toolkit..."
        },
        [71002402] = {
          ContentES = "¡Guau! ¡Qué coincidencia encontrarnos en un lugar así! Ya que estás aquí, ¿quieres vigilar mi preciada excavadora mientras voy a buscar mis herramientas?",
          DialogueId = 71002402,
          GUID = "B1BF3F94",
          SpeakNpcId = 818015,
          Subtitle = "Whoa — fancy seeing you here! This has to be fate, right? Say, could you do me a teeny favour and keep an eye on my precious detector while I run back and grab my kit?"
        },
        [71002403] = {
          ContentES = "¡Genial! Solo quédate cerca y no la pierdas de vista, ¿vale? ¡Vuelvo enseguida!",
          DialogueId = 71002403,
          GUID = "B1BF3FBE",
          NextDialogue = 71002404,
          SpeakNpcId = 818015,
          Subtitle = "Yay, you're a lifesaver! Just stay close and don't let it out of your sight, okay? Be right back~!"
        },
        [71002404] = {
          ContentES = "Hmm… algunas piezas están atascadas. Si las desbloqueo un poco, debería ser más fácil repararlas después.",
          DialogueId = 71002404,
          GUID = "B1BF3FE8",
          SpeakNpcId = 100001,
          Subtitle = "Hm... looks like some parts are jammed. If I loosen them a bit, it might make things easier to fix later."
        },
        [71002405] = {
          ContentES = "(La excavadora hace ruido y atrae a los Filthoids cercanos. Debes repelerlos antes de que se acerquen demasiado.)",
          DialogueId = 71002405,
          GUID = "B1BF4012",
          SpeakNpcId = 800006,
          Subtitle = "(The excavator's beeping is attracting nearby Filthoids. Better drive them off before they get too close.)"
        },
        [71002406] = {
          ContentES = "Eh… ¿incluso desbloqueaste las piezas atascadas? ¡Eres {性别:el|la} mejor!",
          DialogueId = 71002406,
          GUID = "B1BF403C",
          SpeakNpcId = 818015,
          Subtitle = "Aww... you even unjammed the parts!? You're the best!"
        },
        [71002407] = {
          ContentES = "¡Ya estoy de vuelta! ¡Sabía que podía contar contigo!",
          DialogueId = 71002407,
          GUID = "B1BF4066",
          SpeakNpcId = 818015,
          Subtitle = "I'm back! Thanks — I knew I could count on you!"
        },
        [71002501] = {
          ContentES = "Uf… esta maldita alcantarilla está bloqueada de nuevo…",
          DialogueId = 71002501,
          GUID = "B1BF4FD2",
          SpeakNpcId = 818021,
          Subtitle = "Ugh... sewer's clogged again..."
        },
        [71002502] = {
          ContentES = "¿Qué pasó?",
          DialogueId = 71002502,
          GUID = "B1BF4FFC",
          NextDialogue = 71002503,
          SpeakNpcId = 100001,
          Subtitle = "What's going on?"
        },
        [71002503] = {
          ContentES = "Toda esta zona está bloqueada. Mi superior me dio un manual diciendo “sigue las instrucciones”, pero no entiendo nada… ¿Podrías ayudarme?",
          DialogueId = 71002503,
          GUID = "B1BF5026",
          NextOptions = {
            [1] = 710025041,
            [2] = 710025042
          },
          SpeakNpcId = 818021,
          Subtitle = "Whole drain's backed up. My superior tossed me this manual — said to \"follow the steps,\" but I can't make heads or tails of it... Mind lending a hand?"
        },
        [71002505] = {
          ContentES = "Según el manual, solo hay que abrir tres válvulas para crear una corriente fuerte y evacuar todo.",
          DialogueId = 71002505,
          GUID = "B1BF507A",
          NextDialogue = 71002511,
          SpeakNpcId = 100001,
          Subtitle = "It says here you just need to open three sluice gates to flush it out."
        },
        [71002507] = {
          ContentES = "¡Genial! La segunda está por allá.",
          DialogueId = 71002507,
          GUID = "B1BF50CE",
          SpeakNpcId = 818021,
          Subtitle = "Nice! Second one's just over there."
        },
        [71002508] = {
          ContentES = "Y la tercera… veamos… ¡sí, aquí está!",
          DialogueId = 71002508,
          GUID = "B1BF50F8",
          SpeakNpcId = 818021,
          Subtitle = "And the third... right, there it is!"
        }
      }
    end
  },
  {
    MinKey = 71002509,
