          NextOptions = {
            [1] = 710026021,
            [2] = 710026022
          },
          SpeakNpcId = 818023,
          Subtitle = "Hey, you're a Phoxhunter too, right? I took this mining job thinking it'd be easy coin, but there's no way I can finish solo. How about it? We team up, split the reward fifty-fifty?",
          bForbidSkipOptions = true
        },
        [71002603] = {
          ContentES = "Perfecto. Ocúpate del resto, yo ordeno lo que ya he sacado.",
          DialogueId = 71002603,
