        },
        [71005126] = {
          ContentES = "Ya lo pesqué, mira.",
          DialogueId = 71005126,
          GUID = "B1C0FDFF",
          NextDialogue = 71005127,
          SpeakNpcId = 818045,
          Subtitle = "Already caught it."
        },
        [71005127] = {
          ContentES = "(Te señala con el dedo.)",
          DialogueId = 71005127,
          GUID = "B1C0FE28",
          NextDialogue = 71005128,
          SpeakNpcId = 800006,
          Subtitle = "(He points at you.)"
        },
        [71005128] = {
          ContentES = "No todos los peces tienen aletas, ¿sabes? A veces basta con unas palabras enigmáticas y uno o dos gestos extraños… y algo siempre muerde.",
          DialogueId = 71005128,
          GUID = "B1C0FE52",
          NextDialogue = 71005129,
          SpeakNpcId = 818045,
          Subtitle = "Not every fish has fins, you know. Sometimes all it takes is a few cryptic words and a strange act or two... And something always bites."
