          DialogueId = 71005132,
          GUID = "B1C0FEA8",
          NextDialogue = 71005133,
          SpeakNpcId = 818045,
          Subtitle = "Hmm. That's a big one — I'll give you that. But the one I'm after? Even bigger."
        },
        [71005133] = {
          ContentES = "Esos trozos de hielo están molestando a mis peces. Aplástalos y luego veremos.",
          DialogueId = 71005133,
          GUID = "B1C0FEA9",
          SpeakNpcId = 818045,
          Subtitle = "Those shards of ice are throwing everything off. Smash them. Then we'll see."
        },
