        [71005139] = {
          ContentES = "Esto es lo que aprendí al hablar con tanta gente. No te dejes engañar tan fácilmente la próxima vez.",
          DialogueId = 71005139,
          GUID = "B1C0FF24",
          NextDialogue = 71005140,
          SpeakNpcId = 818045,
          Subtitle = "That's what I learned from people. Just try not to nibble so easily next time."
        },
        [71005140] = {
          ContentES = "En fin, perdón por la molestia. Toma, esto es para ti. Considéralo como una disculpa.",
          DialogueId = 71005140,
          GUID = "B1C0FF4E",
          SpeakNpcId = 818045,
          Subtitle = "Anyway — sorry for the mischief. Here. Consider this an apology."
        },
        [71005141] = {
          ContentES = "Creo que ya he oído suficiente. Es hora de decir la verdad.",
          DialogueId = 71005141,
          GUID = "B1C0FF78",
          SpeakNpcId = 100001,
          Subtitle = "I think I've heard enough. Time to reel the truth out of you."
        },
        [71005142] = {
          ContentES = "He visto cómo la gente cae con solo unas palabras bonitas y un poco de actuación, así que… quise comprobar si de verdad funcionaba con alguien.",
          DialogueId = 71005142,
          GUID = "B1C0FFA2",
          NextDialogue = 71005143,
          SpeakNpcId = 818045,
          Subtitle = "Alright, alright! You got me. I've seen how folks fall for a few smooth words and a bit of showmanship... So I figured — why not give it a try myself?"
        },
        [71005143] = {
          ContentES = "En fin, perdón por la molestia. Toma, esto es para ti. Considéralo como una disculpa.",
          DialogueId = 71005143,
          GUID = "B1C0FFCC",
          SpeakNpcId = 818045,
          Subtitle = "Anyway — sorry for the mischief. Here. Consider this an apology."
        },
        [71005201] = {
          ContentES = "¡Monedas de la suerte, monedas mágicas! ¡Vengan a comprar, señor, señora!",
          DialogueId = 71005201,
          GUID = "B1C10ACA",
          SpeakNpcId = 818046,
          Subtitle = "Lucky coins! Real magic lucky coins! Come get one while they last!"
        },
        [71005202] = {
          ContentES = "(Al acercarte, la niña saca apresuradamente unas monedas del bolsillo y te las ofrece.)",
          DialogueId = 71005202,
          GUID = "B1C10AF4",
          NextDialogue = 71005203,
          SpeakNpcId = 800006,
          Subtitle = "(As you draw closer, the girl hurriedly fishes a few copper coins from her pocket and holds them out to you.)"
        },
        [71005203] = {
          ContentES = "¡Hola, {性别:señor|señorita}! ¿Quieres una moneda de la suerte? ¡Mamá me las dejó a mí! Ella decía: una moneda ahuyenta las preocupaciones, dos traen siempre buena suerte, y tres… con tres, ¡puedes lograr cualquier cosa!",
          DialogueId = 71005203,
          GUID = "B1C10B1E",
          NextDialogue = 71005204,
          SpeakNpcId = 818046,
          Subtitle = "Hi there, {性别:Sir|Miss}! Would you like a lucky coin? My mum gave them to me! She said — one coin takes away your worries, two keeps happiness close, and three... three can make any wish come true!"
        },
        [71005204] = {
          ContentES = "...",
          DialogueId = 71005204,
          GUID = "B1C10B48",
          NextDialogue = 71005205,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [71005205] = {
          ContentES = "Todas están encantadas por mamá, ¡de verdad! ¡No te estoy mintiendo! Si no me crees, ¡pregúntales a los demás! Anda, anda, y vuelve a decirme si quieres comprar alguna. Yo esperaré aquí.",
          DialogueId = 71005205,
          GUID = "B1C10B49",
          SpeakNpcId = 818046,
          Subtitle = "They're really magic! Mum cast a spell on them herself — I swear I'm not lying! If you don't believe me, you can ask around! Go on! I'll be right here waiting."
        },
        [71005206] = {
          ContentES = "(Notas varias monedas de la suerte colocadas a los pies de un anciano. Te acercas y entablas conversación con él.)",
          DialogueId = 71005206,
          GUID = "B1C10B72",
          NextDialogue = 71005207,
          SpeakNpcId = 800006,
          Subtitle = "(You spot a few \"lucky coins\" lying at the feet of an old man. You walk over to speak with him.)"
        },
        [71005207] = {
          ContentES = "¿Monedas de la suerte? ¡Jaja! Si de verdad funcionaran, ¿crees que seguiría muriéndome de hambre sentado en este rincón?",
          DialogueId = 71005207,
          GUID = "B1C10B73",
          NextDialogue = 71005208,
          SpeakNpcId = 818047,
          Subtitle = "Lucky coins? Heh... If they really worked, do you think I'd still be starving out here on this street corner?"
        },
        [71005208] = {
          ContentES = "Pero no se lo digas a la niña, ¿de acuerdo? Ya no tiene a nadie… Pobrecita. Incluso algo que no es real puede dar un poco de esperanza, ¿no crees?",
          DialogueId = 71005208,
          GUID = "B1C10B74",
          SpeakNpcId = 818047,
          Subtitle = "But don't go repeating that to the little girl, alright? She's got no family left. Poor thing... Sometimes, even when something isn't real, it still gives people something to hold on to. You get what I mean?"
        },
        [71005209] = {
          ContentES = "(Un chico juega con varias monedas de la suerte entre las manos. Te acercas para hablar con él.)",
          DialogueId = 71005209,
          GUID = "B1C10B9C",
          NextDialogue = 71005210,
          SpeakNpcId = 800006,
          Subtitle = "(You see a boy turning a few \"lucky coins\" over in his hands. You walk over to speak with him.)"
        },
        [71005210] = {
          ContentES = "¿Ves alguna diferencia entre la moneda de la suerte que tengo en la mano izquierda y la de la mano derecha?",
          DialogueId = 71005210,
          GUID = "B1C10B9D",
          NextDialogue = 71005211,
          SpeakNpcId = 818048,
          Subtitle = "Can you tell the difference between the lucky coin in my left hand and the plain copper one in my right?"
        },
        [71005211] = {
          ContentES = "(Te muestra ambas manos. Al observarlas con atención, confirmas que son idénticas.)",
          DialogueId = 71005211,
          GUID = "B1C10B9E",
          NextDialogue = 71005212,
          SpeakNpcId = 800006,
          Subtitle = "(He holds out both hands. After a careful look... you confirm — they're exactly the same.)"
        },
        [71005212] = {
          ContentES = "Exacto. Porque ambas son monedas de la suerte. No están hechas con magia, sino con bondad.",
          DialogueId = 71005212,
          GUID = "B1C10B9F",
          NextDialogue = 71005213,
          SpeakNpcId = 818048,
          Subtitle = "Yup. Because they are both lucky coins. Not made by magic — made by kindness."
        },
        [71005213] = {
          ContentES = "Unas cuantas monedas sueltas a cambio de la sonrisa de una niña. Sinceramente, puede que sea uno de los mejores tratos que hagas en tu vida.",
          DialogueId = 71005213,
          GUID = "B1C10BA0",
          SpeakNpcId = 818048,
          Subtitle = "Just a few spare coins for a little girl's smile. Honestly? That might be one of the best trades you'll ever find."
        },
        [71005214] = {
          ContentES = "Entonces, ¿ves? Todo el mundo dice que funcionan, ¿no?",
          DialogueId = 71005214,
          GUID = "B1C10BC6",
          SpeakNpcId = 818046,
          Subtitle = "So? Everyone says they work, don't they?"
        },
        [71005215] = {
          ContentES = "Jeje… ¿de verdad? Bueno, si eso es lo que quieres, ¡te las venderé todas! ¡Espero que te traigan muchísima, muchísima felicidad!",
          DialogueId = 71005215,
          GUID = "B1C10BF0",
          SpeakNpcId = 818046,
          Subtitle = "Hehe, really? Well, if that's what you want — they're all yours! I hope they bring you lots and lots of happiness!"
        },
        [71005216] = {
          ContentES = "¿Por ti {性别:mismo|misma}, eh…? Eso es genial. ¿Crees que… quizá yo también podría hacerlo algún día?",
          DialogueId = 71005216,
          GUID = "B1C10C1A",
          NextDialogue = 71005217,
          SpeakNpcId = 818046,
          Subtitle = "Earn it on your own, huh...? That's really cool. Do you think... maybe I could do that too, one day?"
        },
        [71005217] = {
          ContentES = "Claro que sí.",
          DialogueId = 71005217,
          GUID = "B1C10C1B",
          NextDialogue = 71005218,
          SpeakNpcId = 100001,
          Subtitle = "Of course you could."
        },
        [71005218] = {
          ContentES = "Mmm… lo pensaré. ¡Muchas gracias!",
          DialogueId = 71005218,
          GUID = "B1C10C1C",
          SpeakNpcId = 818046,
          Subtitle = "Mmm... I'll think about it. Thank you — really!"
        },
        [71005301] = {
          ContentES = "¡Al ladrón! ¡Al ladrón! ¡Ayuda, por favor!",
          DialogueId = 71005301,
          GUID = "B1C11B32",
          SpeakNpcId = 818042,
          Subtitle = "Help! I've been robbed! Somebody help — please! Anyone!!"
