          DialogueId = 71005302,
          GUID = "B1C11B5C",
          NextDialogue = 71005303,
          SpeakNpcId = 100001,
          Subtitle = "Which way did they go?"
        },
        [71005303] = {
          ContentES = "¡Por allí! Se fueron por ese lado… *snif*… La ciudad exterior de verdad es tan peligrosa como dicen…",
          DialogueId = 71005303,
          GUID = "B1C11B86",
          SpeakNpcId = 818042,
          Subtitle = "Th—That way... They ran off that way... *sobs* The outer city really is as dangerous as they say..."
        },
        [71005304] = {
          ContentES = "¡Premio gordo! ¡Esos mocosos de la ciudad interior están llenos de dinero! ¡Estaremos tranquilos por meses!",
          DialogueId = 71005304,
          GUID = "B1C11C04",
          NextDialogue = 71005305,
          SpeakNpcId = 818043,
          Subtitle = "Jackpot! Inner city brats are loaded! We're set for months, boys!"
        },
        [71005305] = {
