          DialogueId = 71005305,
          GUID = "B1C11C2E",
          NextDialogue = 71005306,
          SpeakNpcId = 100001,
          Subtitle = "Drop what you stole. Now."
        },
        [71005306] = {
          ContentES = "Ja — alguien intenta hacerse {性别:el héroe|la heroína}, ¿eh? Bueno entonces, ¡te lo buscaste!",
          DialogueId = 71005306,
          GUID = "B1C11C58",
          SpeakNpcId = 818043,
          Subtitle = "Heh — someone's trying to play the hero, huh? Alright then — you asked for it!"
        },
        [71005307] = {
