          DialogueId = 71005307,
          GUID = "B1C11CAC",
          SpeakNpcId = 818043,
          Subtitle = "Tch, whatever. Not worth it. Let's bail — move!"
        },
        [71005308] = {
          ContentES = "(Los ladrones huyen en todas direcciones. Recoges el bolso y piensas en qué deberías hacer.)",
          DialogueId = 71005308,
          GUID = "B1C11CD6",
          SpeakNpcId = 800006,
          Subtitle = "(The petty thieves scatter in different directions. You pick the stolen handbag off the ground and weigh your next move.)"
        },
        [71005309] = {
          ContentES = "(Llamémoslo matrícula: una lección de supervivencia. Guardas el dinero sin dudar. Sinceramente, es generoso de tu parte no pedirle más.)",
          DialogueId = 71005309,
          GUID = "B1C11D2A",
          SpeakNpcId = 800006,
          Subtitle = "(Call it tuition — a lesson in survival. You pocket the money without hesitation. Frankly, it's generous of you not to charge her extra.)"
        },
        [71005310] = {
          ContentES = "He encontrado tu bolso. ¿Es este, verdad?",
          DialogueId = 71005310,
          GUID = "B1C11D54",
          NextDialogue = 71005311,
          SpeakNpcId = 100001,
          Subtitle = "Got it back. Is this the one?"
        },
        [71005311] = {
          ContentES = "¡Sí! ¡Sí, es ese! ¡Muchísimas gracias!",
