          DialogueId = 71005312,
          GUID = "B1C11DA8",
          NextDialogue = 71005313,
          SpeakNpcId = 800006,
          Subtitle = "(She wipes away her tears, then pulls a generous stack of cash from the handbag and presses it into your hands.)"
        },
        [71005313] = {
          ContentES = "Por favor, toma esto. Eres {性别:un Phoxcazador tan amable y honesto|una Phoxcazadora tan amable y honesta}. Gracias… de verdad… *snif*",
          DialogueId = 71005313,
          GUID = "B1C11DA9",
          SpeakNpcId = 818042,
          Subtitle = "Please — take this. You're such a kind and honest Phoxhunter. Thank you... really... *sobs*"
        },
        [71005401] = {
