          DialogueId = 71005401,
          GUID = "B1C12B9A",
          SpeakNpcId = 818044,
          Subtitle = "Step right up! Big prizes inside — don't miss your chance!"
        },
        [71005402] = {
          ContentES = "¡Eh, {性别:Phoxcazador|Phoxcazadora}! ¿Te animas a probar tu suerte? Si consigues abrir esta caja, ¡el premio será todo tuyo!",
          DialogueId = 71005402,
          GUID = "B1C12BC4",
          SpeakNpcId = 818044,
          Subtitle = "Hey there, Phoxhunter! Care to test your luck? If you can open this box, the prize is all yours!"
        },
        [71005403] = {
          ContentES = "(Oyes un clic al girar la cerradura. Justo cuando parece que lo logras… ¡CLAC! La tapa se cierra de golpe. Hagas lo que hagas, el cofre se niega a abrirse de nuevo.)",
          DialogueId = 71005403,
          GUID = "B1C12C18",
          SpeakNpcId = 800006,
          Subtitle = "(You hear a soft click as the lock turns. Just when it seems like you've got it — CLACK! The lid snaps shut. No matter what you try, it refuses to open again.)"
        },
        [71005404] = {
          ContentES = "¡Ah! ¡Has roto mi cofre! ¡Tienes que pagar por esto! ¡Ahora mismo, dame tu dinero!",
