          GUID = "B1C12C42",
          NextOptions = {
            [1] = 710054041,
            [2] = 710054042
          },
          SpeakNpcId = 818044,
          Subtitle = "Hey! You broke my prize box! You owe me for this! Now gimme your money!"
        },
        [71005405] = {
          ContentES = "Shhh… no tan alto. Tengo otras… oportunidades de negocio por aquí. Mira, toma esto, ¿sí? Y hagamos como si nada de esto hubiera pasado.",
          DialogueId = 71005405,
          GUID = "B1C12CC0",
          NextDialogue = 71005406,
          SpeakNpcId = 818044,
          Subtitle = "Shhh! Keep it down, will you? I've got other... business opportunities around here. Look — take this, yeah? And let's just pretend this never happened."
        },
        [71005406] = {
