        [71007201] = {
          ContentES = "Hmm… ¿cuál debería elegir…?",
          DialogueId = 71007201,
          GUID = "B1C252EA",
          SpeakNpcId = 818074,
          Subtitle = "Hmm... which one should I go for...?"
        },
        [71007203] = {
          ContentES = "¡Oh! Llegas justo a tiempo. Siempre me cuesta decidirme cuando voy a comprar algo. ¿Podrías ayudarme a comparar y darme tu opinión?",
          DialogueId = 71007203,
          GUID = "B1C2533E",
          NextOptions = {
            [1] = 710072031,
            [2] = 710072032
          },
          SpeakNpcId = 818074,
          Subtitle = "Oh — sorry to bother you. I can never decide what to buy. Could I trouble you to take a look and give me a bit of advice?",
          bForbidSkipOptions = true
        },
        [71007204] = {
          ContentES = "Muchas gracias. Te esperaré aquí.",
          DialogueId = 71007204,
          GUID = "B1C25368",
          SpeakNpcId = 818074,
          Subtitle = "Thank you so much. I'll wait right here."
        },
        [71007206] = {
          ContentES = "Todo lo que vendo es de primera calidad, traído directamente de su lugar de origen y con la certificación oficial de Primavera Eterna. Es un poco más caro, sí, pero cada pieza vale lo que cuesta.",
          DialogueId = 71007206,
          GUID = "B1C253BC",
          SpeakNpcId = 818072,
          Subtitle = "Everything I sell is premium stock, brought in directly from its place of origin. Most of it has travelled thousands of miles before reaching my stall, and every item comes with EverSpring's official certification. They may cost a little more, but you really do get what you pay for."
        },
        [71007207] = {
          ContentES = "“Bah, son solo artículos de uso diario. Sean de primera calidad o no, ¿qué diferencia hay? Los míos son más baratos y salen más a cuenta. ¿No te parece?”",
          DialogueId = 71007207,
          GUID = "B1C253E6",
          SpeakNpcId = 818073,
          Subtitle = "It's all everyday necessities — \"premium\" doesn't really mean a thing. My goods are much cheaper, and that makes them the better deal. Don't you agree?"
        },
        [71007208] = {
          ContentES = "(Tras observar cuidadosamente los productos, has tomado una decisión. Es hora de volver y dar tu opinión al viajero indeciso.)",
          DialogueId = 71007208,
          GUID = "B1C25410",
          SpeakNpcId = 800006,
          Subtitle = "(After looking everything over, you've made your choice. Time to head back and tell the indecisive traveller what you think.)"
        },
        [71007209] = {
          ContentES = "Entonces, ¿cuál crees que es la mejor opción?",
          DialogueId = 71007209,
          GUID = "B1C2543A",
          NextOptions = {
            [1] = 710072091,
            [2] = 710072092
          },
          SpeakNpcId = 818074,
          Subtitle = "Well? Which one do you think is the better buy?",
          bForbidSkipOptions = true
        },
        [71007210] = {
          ContentES = "Muy bien, seguiré tu consejo. ¡Muchas gracias!",
          DialogueId = 71007210,
          GUID = "B1C25464",
          SpeakNpcId = 818074,
          Subtitle = "Right then, I'll go with him! Thanks for the advice!"
        },
        [71007301] = {
          ContentES = "(La zona está llena de enemigos. Elimínalos para rescatar al Geniemon.)",
          DialogueId = 71007301,
          GUID = "B1C26352",
          SpeakNpcId = 800006,
          Subtitle = "(The area around the Geniemon is swarming with enemies. Defeat them before rescuing it.)"
        },
        [71007302] = {
          ContentES = "(Los ruidos de combate atraen aún más enemigos.)",
          DialogueId = 71007302,
          GUID = "B1C2637C",
          SpeakNpcId = 800006,
          Subtitle = "(The sounds of battle have drawn in additional enemies.)"
        },
        [71007303] = {
          ContentES = "(La zona está segura por ahora. ¡Aprovecha para rescatar al Geniemon!)",
          DialogueId = 71007303,
          GUID = "B1C263A6",
          SpeakNpcId = 800006,
          Subtitle = "(The area is clear for the moment. Now's your chance to free the Geniemon.)"
        },
        [71007401] = {
          Content = "（周围突然出现了应天侍，准备应敌）（待包装）",
          DialogueId = 71007401,
          GUID = "B1C273BA",
          SpeakNpcId = 800006
        },
        [71007501] = {
          ContentES = "¡Eh! ¡Paren, paren! ¡Se lo han llevado todo! ¿Y ahora qué se supone que voy a vender yo? ¿Alguien… alguien podría ayudarme?",
          DialogueId = 71007501,
          GUID = "B1C28422",
          SpeakNpcId = 818078,
          Subtitle = "Hey— stop! Quit it! If you clear me out, what am I supposed to sell? Someone— anyone— give me a hand!"
        },
        [71007502] = {
          ContentES = "(Al acercarte, descubres a un hombre desanimado, en cuclillas en el suelo. A su alrededor hay restos de patata esparcidos por todas partes.)",
          DialogueId = 71007502,
          GUID = "B1C2844C",
          NextDialogue = 71007503,
          SpeakNpcId = 800006,
          Subtitle = "(As you draw nearer, you find a miserable-looking man slumped on the ground, shreds of potato scattered all around him.)"
        },
        [71007503] = {
          ContentES = "Perdona la molestia… pero pareces alguien de fiar. ¿Podrías echarme una mano?",
          DialogueId = 71007503,
          GUID = "B1C28476",
          NextOptions = {
            [1] = 710075031,
            [2] = 710075032
          },
          SpeakNpcId = 818078,
          Subtitle = "Sorry to trouble you — but you look like someone dependable. Could you give me a hand?"
        },
        [71007504] = {
          ContentES = "Gracias, de verdad. La cosa es así: en cuanto pongo un poco de patata en el puesto, las Gaviotas nubosas del puerto se vuelven completamente locas y se lanzan sobre él. Mira… así…",
          DialogueId = 71007504,
          GUID = "B1C284A0",
          SpeakNpcId = 818078,
          Subtitle = "Thanks — really. Here's the situation: every time I put out so much as a handful of shredded potato, the Skywing Gulls down by the docks absolutely lose their minds and mob the stall. Watch — like this..."
        },
        [71007505] = {
          ContentES = "(El hombre recoge con cuidado unas patatas ralladas. Al instante, varias Gaviotas nubosas baten las alas y empiezan a dar vueltas sobre sus cabezas.)",
          DialogueId = 71007505,
          GUID = "B1C284CA",
          SpeakNpcId = 800006,
          Subtitle = "(He gingerly gathers a few stray shreds. Almost at once, several Skywing Gulls swoop in, circling overhead.)"
        },
        [71007506] = {
          ContentES = "¡Aaaah…! ¿Lo ves? ¿¡Lo ves!? ¡Han vuelto! ¡Rápido, ayúdame a espantarlas, te lo ruego!",
          DialogueId = 71007506,
          GUID = "B1C284F4",
          NextDialogue = 71007507,
          SpeakNpcId = 818078,
          Subtitle = "Ahhhh—! See? See!? They're back again! Please... help me chase them off!"
        },
        [71007507] = {
          ContentES = "(Las gaviotas giran sin descanso, acercándose en cuanto ven una oportunidad. Parece que su razón de existir se reduce a las patatas, y que su único objetivo en la vida es arrebatárselas de las manos al hombre.)",
          DialogueId = 71007507,
          GUID = "B1C2851E",
          SpeakNpcId = 800006,
          Subtitle = "(The Skywing Gulls wheel above you in tight circles, edging closer whenever they think they can snatch a bite— as if their entire existence revolved around shredded potatoes.)"
        },
        [71007508] = {
          ContentES = "Uf… vender patatas en los muelles es mucho más peligroso de lo que imaginaba. Gracias… de verdad, gracias.",
          DialogueId = 71007508,
          GUID = "B1C28548",
          SpeakNpcId = 818078,
          Subtitle = "Whew... selling potatoes on the docks is far more dangerous than I thought. Thank you so much..."
        },
        [71007601] = {
