        },
        [71007801] = {
          ContentES = "Tú, de ahí… {性别:Phoxcazador|Phoxcazadora}. ¿Podrías acercarte un momento?",
          DialogueId = 71007801,
          GUID = "B1C2B55A",
          SpeakNpcId = 818082,
          Subtitle = "Hey — Phoxhunter. Have you a moment to spare?"
        },
        [71007802] = {
          ContentES = "Recientemente he desarrollado un nuevo incienso capaz de despertar el inconsciente oculto en la mente. ¿Aceptarías ayudarme con un experimento? Solo tendrás que encenderlo y describirme lo que veas.",
          DialogueId = 71007802,
          GUID = "B1C2B584",
          NextOptions = {
            [1] = 710078021,
            [2] = 710078022
          },
          SpeakNpcId = 818082,
          Subtitle = "I've been working on a new incense that awakens what lies buried in the mind. Would you help me test it? Just light it, and then tell me what you see.",
          bForbidSkipOptions = true
        },
        [71007803] = {
          ContentES = "Perfecto. Ve y enciende el incienso en este incensario de allí.",
          DialogueId = 71007803,
          GUID = "B1C2B5AE",
          SpeakNpcId = 818082,
          Subtitle = "Good. You can start by lighting the incense in the censer over there."
        },
        [71007804] = {
          ContentES = "(Una fragancia extraña se cuela en tus sentidos. Tus pensamientos se dispersan y poco a poco se funden con el entorno que te rodea.)",
          DialogueId = 71007804,
          GUID = "B1C2B5D8",
          NextDialogue = 71007805,
          SpeakNpcId = 800006,
          Subtitle = "(A strange fragrance threads into your senses. Your thoughts begin to drift outward, scattering across the world around you.)"
        },
        [71007805] = {
          ContentES = "(Una pregunta emerge desde lo más profundo de tu mente: ¿qué es lo que más deseas en este momento?)",
          DialogueId = 71007805,
          GUID = "B1C2B602",
          NextOptions = {
            [1] = 710078051,
            [2] = 710078052,
            [3] = 710078053
          },
          SpeakNpcId = 800006,
          Subtitle = "(A question rises within you — what is it you desire most in this moment?)",
          bForbidSkipOptions = true
        },
        [71007806] = {
