          bAllowClickSkipScript = false
        },
        [72001002] = {
          ContentES = "La pared dice que solo rechaza lo que quiere rechazar.",
          DialogueId = 72001002,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F3864",
          NextDialogue = 72001003,
          SpeakNpcId = 820000,
          Subtitle = "The wall says it only keeps out what it wants to keep out."
        },
        [72001003] = {
          ContentES = "Pero si le agradas… te dejará pasar.",
          DialogueId = 72001003,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F388E",
          NextDialogue = 72001004,
          SpeakNpcId = 820000,
          Subtitle = "But if it likes you... it lets you through."
