          bAllowClickSkipScript = false
        },
        [72001102] = {
          ContentES = "Creía que este cofre era un Salutín. Le pedí durante tanto tiempo que se moviera…",
          DialogueId = 72001102,
          FacialId = {
            [1] = "820000:PetPan_Wink"
          },
          GUID = "B43F48CC",
          NextDialogue = 72001103,
          SpeakNpcId = 820000,
          Subtitle = "I thought this box was a Bro Boxie. I spent forever trying to talk him into moving."
        },
        [72001103] = {
          ContentES = "Pero no… debí darle una pequeña patada antes.",
          DialogueId = 72001103,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F48F6",
          NextDialogue = 72001104,
          SpeakNpcId = 820000,
          Subtitle = "Turns out he wasn't. Maybe I should've given him a teeny kick..."
