          bAllowClickSkipScript = false
        },
        [72001202] = {
          ContentES = "Este árbol parece cansado… Se acostó para descansar.",
          DialogueId = 72001202,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F5934",
          NextDialogue = 72001203,
          SpeakNpcId = 820000,
          Subtitle = "This tree looks tired... It's just lying down for a nap."
        },
        [72001203] = {
          ContentES = "Entonces… la nieve que cayó al suelo… ¿quizá también se cansó de volar y decidió quedarse quieta para descansar?",
          DialogueId = 72001203,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F595E",
          NextDialogue = 72001204,
          SpeakNpcId = 820000,
          Subtitle = "Do you think the snow on the ground is tired too? Maybe it just wanted a little rest."
        },
        [72001204] = {
          DialogueId = 72001204,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
