          bAllowClickSkipScript = false
        },
        [72001302] = {
          ContentES = "Aquí se está tan bien… Puedes sentarte conmigo.",
          DialogueId = 72001302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F699C",
          NextDialogue = 72001303,
          SpeakNpcId = 820000,
          Subtitle = "It's nice and warm here. You can sit with me if you like."
        },
        [72001303] = {
          ContentES = "Pero no por mucho tiempo, mis otros amigos podrían pasar frío.",
          DialogueId = 72001303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F69C6",
          NextDialogue = 72001304,
          SpeakNpcId = 820000,
          Subtitle = "Just don't stay too long — my other friends might get chilly."
