        },
        [72001402] = {
          ContentES = "Un camino sin salida… hmm…",
          DialogueId = 72001402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F7A04",
          NextDialogue = 72001403,
          SpeakNpcId = 820000,
          Subtitle = "This is a dead end... mm..."
        },
        [72001403] = {
          ContentES = "O quizá quería decir… que me gustaría quedarme solo un rato. ¿Quieres… quedarte a solas conmigo?",
          DialogueId = 72001403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F7A2E",
          NextDialogue = 72001404,
          SpeakNpcId = 820000,
          Subtitle = "Or maybe what I meant was — I want to be alone for a while. Would you like to be alone with me?"
        },
        [72001404] = {
          ContentES = "Pero entonces… ¿podría seguir llamándose estar solo?",
          DialogueId = 72001404,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F7A58",
          NextDialogue = 72001405,
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
          SpeakNpcId = 820000,
          Subtitle = "But... does that still count as being alone?",
          bAllowClickSkipScript = false
