          bAllowClickSkipScript = false
        },
        [72001502] = {
          ContentES = "Estas casas se ven tan cansadas… su piel está toda dañada, llena de manchas…",
          DialogueId = 72001502,
          FacialId = {
            [1] = "820000:PetPan_Speechless"
          },
          GUID = "B43F8A6C",
          NextDialogue = 72001503,
          SpeakNpcId = 820000,
          Subtitle = "These houses look so tired. Their skin's all spotty and peeling..."
        },
        [72001503] = {
          ContentES = "Ojalá pudieran sanar…",
          DialogueId = 72001503,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F8A96",
          NextDialogue = 72001504,
          SpeakNpcId = 820000,
          Subtitle = "I hope they get better soon."
