          },
          GUID = "B43F9AAA",
          NextDialogue = 72001602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72001602] = {
          ContentES = "¡Esta montaña es tan alta! ¡Tan brillante! ¡Y yo, justo en la cima! ¡Soy increíble!",
          DialogueId = 72001602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F9AD4",
          NextDialogue = 72001603,
          SpeakNpcId = 820000,
          Subtitle = "This mountain is so tall! So bright! Look at me — on the top! I'm amazing!"
        },
        [72001603] = {
          ContentES = "¡Yiiip! ¿No es una montaña? Entonces… ¿qué es?",
          DialogueId = 72001603,
          FacialId = {
            [1] = "820000:PetPan_Speechless"
          },
          GUID = "B43F9AFE",
          NextDialogue = 72001604,
          SpeakNpcId = 820000,
          Subtitle = "Eeya? This isn't a mountain? Uh-uh!"
        },
        [72001604] = {
          ContentES = "Es alta y puntiaguda… ¡claro que es una montaña!",
          DialogueId = 72001604,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F9B28",
          NextDialogue = 72001605,
          SpeakNpcId = 820000,
          Subtitle = "It's tall and pointy... totally a mountain!"
        },
        [72001605] = {
