          NextDialogue = 72001702,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72001702] = {
          ContentES = "Si ves bien el camino bajo tus pies… ya no tendrás miedo de los Filthoids, ¿verdad?",
          DialogueId = 72001702,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43FAB3C",
          NextDialogue = 72001703,
          SpeakNpcId = 820000,
          Subtitle = "If you can see the path right under your feet... Would you still be less scared of the Filthoids?"
        },
        [72001703] = {
          ContentES = "¡Tadaa! ¿Ves? Ahora todo está bonito y bien iluminado.",
          DialogueId = 72001703,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43FAB66",
          NextDialogue = 72001704,
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 820000,
          Subtitle = "Ta-da~! Now it's all nice and bright.",
