          },
          GUID = "B4400DAC",
          NextDialogue = 72002303,
          SpeakNpcId = 820000,
          Subtitle = "Flowers are so kind. They always make people smile."
        },
        [72002303] = {
          ContentES = "¿Y si, en secreto… susurraran palabras dulces a quienes las reciben?",
