          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DD6",
          NextDialogue = 72002304,
          SpeakNpcId = 820000,
          Subtitle = "Do you think they whisper little secrets to them when we're not looking?"
        },
