          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002402] = {
          ContentES = "Dime… ¿crees que un ser, quizá un dios, lo bastante poderoso, podría alzar por completo el Lago Lamentoso… y morderlo como si fuera un caramelo?",
          DialogueId = 72002402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4401E14",
          NextDialogue = 72002403,
          SpeakNpcId = 820000,
          Subtitle = "Do you think... someone super strong — like a god, maybe — could pick up the whole Lamenting Lake and eat it like candy?"
        },
        [72002403] = {
          ContentES = "¿A qué sabría? Es azul… así que quizá sabría al cielo.",
          DialogueId = 72002403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4401E3E",
          NextDialogue = 72002404,
          SpeakNpcId = 820000,
          Subtitle = "I wonder what it tastes like. It's blue, so... maybe it tastes like the sky?"
        },
        [72002404] = {
