          },
          GUID = "B4403EE4",
          NextDialogue = 72002603,
          SpeakNpcId = 820000,
          Subtitle = "Mm~ Thank you for building a cabin for me."
        },
        [72002603] = {
          ContentES = "Si algún día creces tanto como yo, tú también podrás mudarte aquí… y seremos vecinos.",
          DialogueId = 72002603,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403F0E",
          NextDialogue = 72002604,
          SpeakNpcId = 820000,
