          },
          GUID = "B4404F4C",
          NextDialogue = 72002703,
          SpeakNpcId = 820000,
          Subtitle = "Where are you off to?"
        },
        [72002703] = {
          ContentES = "Si ves a esa humana que parece hecha de vidrio roto… intenta ser su amiga, ¿sí?",
          DialogueId = 72002703,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4404F76",
          NextDialogue = 72002704,
          SpeakNpcId = 820000,
          Subtitle = "If you see that human who looks like a piece of broken glass... try to be her friend, okay?"
