          },
          GUID = "B44090EC",
          NextDialogue = 72003103,
          SpeakNpcId = 820000,
          Subtitle = "What are you looking for?"
        },
        [72003103] = {
          ContentES = "Si no me estás buscando a mí, puedo ayudarte.",
          DialogueId = 72003103,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4409116",
          NextDialogue = 72003104,
          SpeakNpcId = 820000,
          Subtitle = "If you're not looking for me, I can help."
