        },
        [72003302] = {
          ContentES = "Muchos vinieron… muchos se fueron.",
          DialogueId = 72003302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B1BC",
          NextDialogue = 72003303,
          SpeakNpcId = 820000,
          Subtitle = "So many people came, and so many left."
        },
        [72003303] = {
          ContentES = "Hay demasiados olores, no consigo recordarlos todos… ¿Y tú, los recuerdas?",
          DialogueId = 72003303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B1E6",
          NextDialogue = 72003304,
          SpeakNpcId = 820000,
          Subtitle = "So many scents lingering... I can't remember them all. Can you?"
        },
        [72003304] = {
