          },
          GUID = "B440C223",
          NextDialogue = 72003402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003402] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Aquí está mi tesoro! ¡Solo quienes superen la prueba de la sabiduría pueden entrar!",
          DialogueId = 72003402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C224",
          NextDialogue = 72003403,
          SpeakNpcId = 820000,
          Subtitle = "This is my treasure trove! Only those who pass the trial of wisdom may enter!"
        },
        [72003403] = {
          ContentES = "Así que dime… aquí, en esta fortaleza… ¿qué color te deja pasar?",
          DialogueId = 72003403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C24E",
          SpeakNpcId = 820000,
          Subtitle = "So tell me — here, in this fortress... What colour lets you through?",
          TalkOptions = {
            [1] = 72003404,
            [2] = 72003405,
            [3] = 72003406
          }
        },
        [72003404] = {
          ContentES = "¡Azul!",
          DialogueId = 72003404,
          GUID = "B440C278",
          ImprPlusId = 1003,
          Subtitle = "Blue!"
        },
        [72003405] = {
          ContentES = "¡Rojo!",
          DialogueId = 72003405,
          GUID = "B440C2A2",
          ImprPlusId = 1016,
          Subtitle = "Red!"
        },
        [72003406] = {
          ContentES = "¡Naranja!",
          DialogueId = 72003406,
          GUID = "B440C2CC",
          ImprPlusId = 1016,
          Subtitle = "Orange!"
        },
        [72003407] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Exacto! ¡Has elegido el color del paso! ¡adelante, entra!",
          DialogueId = 72003407,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C2F6",
          NextDialogue = 72003409,
          SpeakNpcId = 820000,
          Subtitle = "That's right! You picked the right colour — so in you go!"
        },
        [72003408] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡No! Piénsalo otra vez. ¡Esta vez, piensa bien en serio!",
          DialogueId = 72003408,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C320",
          NextDialogue = 72003409,
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
          SpeakNpcId = 820000,
          Subtitle = "Nope! Have another think. A really good one this time!",
          bAllowClickSkipScript = false
        },
        [72003409] = {
          DialogueId = 72003409,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
