          bAllowClickSkipScript = false
        },
        [72003502] = {
          ContentES = "¡Ay…! Ese vapor me golpeó.",
          DialogueId = 72003502,
          FacialId = {
            [1] = "820000:PetPan_Cry"
          },
          GUID = "B440D28C",
          NextDialogue = 72003503,
          SpeakNpcId = 820000,
          Subtitle = "Owie...! That steam hit me."
        },
        [72003503] = {
          ContentES = "Es malo. No me cae bien. ¡Y tú tampoco deberías hacerte su amigo!",
          DialogueId = 72003503,
          FacialId = {
            [1] = "820000:PetPan_Speechless"
          },
          GUID = "B440D2B6",
          NextDialogue = 72003504,
          SpeakNpcId = 820000,
          Subtitle = "He's mean. I don't like him. And you shouldn't be his friend, either!"
        },
        [72003504] = {
