          NextDialogue = 72003602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003602] = {
          ContentES = "Aquí… huele un poco como afuera. Huele a alegría, a grandeza.",
          DialogueId = 72003602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440E2F4",
          NextDialogue = 72003603,
          SpeakNpcId = 820000,
          Subtitle = "Mmm... this place smells a bit like the outside world. It smells happy, and awesome!"
        },
        [72003603] = {
          ContentES = "Nada que ver con esos lugares saturados de gritos y peleas.",
          DialogueId = 72003603,
          FacialId = {
            [1] = "820000:PetPan_Speechless"
          },
          GUID = "B440E31E",
          NextDialogue = 72003604,
          SpeakNpcId = 820000,
          Subtitle = "Not like those other places full of the smell of yelling and fighting."
        },
        [72003604] = {
