        },
        [72100401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC0A",
          NextDialogue = 72100402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100402] = {
          ContentES = "¿Qué aroma flota en el aire? ¿Lirio celeste… o tal vez Primavera suprema?",
          DialogueId = 72100402,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC34",
          NextDialogue = 72100403,
          SpeakNpcId = 830001,
          Subtitle = "What's that scent drifting on the air? Skylily? Or perhaps Vernal Prime?"
        },
        [72100403] = {
          ContentES = "No es tan bueno como mi propia composición… Qué lástima… Nunca podré recrearla.",
          DialogueId = 72100403,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC5E",
          NextDialogue = 72100404,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Not as good as my own blend. A pity... I can't make it anymore.",
          bAllowClickSkipScript = false
        },
        [72100404] = {
          DialogueId = 72100404,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC88",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100501] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100501,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFC72",
          NextDialogue = 72100502,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100502] = {
          ContentES = "¡Liang Qing, hijo mío! ¿Te encuentras bien?",
          DialogueId = 72100502,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFC9C",
          NextDialogue = 72100503,
          SpeakNpcId = 830001,
          Subtitle = "Liang Qing, my child! Are you well?"
        },
        [72100503] = {
          ContentES = "¿Eh…? ¿No es mi hijo? Entonces… ¿quién eres tú?",
          DialogueId = 72100503,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFCC6",
          NextDialogue = 72100504,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Oh? Not my child? Then who... are you?",
          bAllowClickSkipScript = false
        },
        [72100504] = {
          DialogueId = 72100504,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFCF0",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100601] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100601,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0CDA",
          NextDialogue = 72100602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100602] = {
          ContentES = "Si trepo hasta la cima de un árbol gigantesco, ¿podré acercarme a Taihao?",
          DialogueId = 72100602,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D04",
          NextDialogue = 72100603,
          SpeakNpcId = 830001,
          Subtitle = "If I climb a tall tree all the way up, can I get closer to Lord Taihao?"
        },
        [72100603] = {
          ContentES = "¿Cuánto tiempo haría falta? ¿Diez años… cien años… sería suficiente?",
          DialogueId = 72100603,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D2E",
          NextDialogue = 72100604,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "How long would it take? Ten years? A hundred? Would that be enough?",
          bAllowClickSkipScript = false
        },
        [72100604] = {
          DialogueId = 72100604,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D58",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100701] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100701,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1D42",
          NextDialogue = 72100702,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100702] = {
          ContentES = "Hace tanto frío… Tiemblo por todo mi cuerpo, siento que mis dientes se van a romper…",
          DialogueId = 72100702,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1D6C",
          NextDialogue = 72100703,
          SpeakNpcId = 830001,
          Subtitle = "So chilly... I'm freezing all over. Feels like my teeth are about to shatter."
        },
        [72100703] = {
          ContentES = "Espera… Pero no tengo dientes, ¿verdad? Entonces… esta sensación de escalofrío es…",
          DialogueId = 72100703,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1D96",
          NextDialogue = 72100704,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Wait... I don't have teeth, do I? Then this shivering feeling is from...",
          bAllowClickSkipScript = false
        },
        [72100704] = {
          DialogueId = 72100704,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1DC0",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100801] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100801,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2DAA",
          NextDialogue = 72100802,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100802] = {
          ContentES = "Solía venir aquí a menudo, a mirar el cielo. Tenía la sensación de ver mi propio reflejo, detrás de las nubes.",
          DialogueId = 72100802,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2DD4",
          NextDialogue = 72100803,
          SpeakNpcId = 830001,
          Subtitle = "I used to come here to gaze at the sky. It was like I could see myself behind the clouds."
        },
        [72100803] = {
          ContentES = "Ahora ya no necesito mirar. De todos modos, ya no puedo verme a mí mismo.",
          DialogueId = 72100803,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2DFE",
          NextDialogue = 72100804,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "No need to look now. After all, I can't see myself anymore!",
          bAllowClickSkipScript = false
        },
        [72100804] = {
          DialogueId = 72100804,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2E28",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100901] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100901,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E12",
          NextDialogue = 72100902,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100902] = {
          ContentES = "¿Qué color prefieres? Verde habichuela… o gris grulla?",
          DialogueId = 72100902,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E3C",
          NextDialogue = 72100903,
          SpeakNpcId = 830001,
          Subtitle = "What's your favourite colour? Light green, or crane-gray?"
        },
        [72100903] = {
          ContentES = "¿Yo? Me gusta el azul de las nubes y del agua. Azul… como mi cuerpo.",
          DialogueId = 72100903,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E66",
          NextDialogue = 72100904,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I love cloud-water blue. Just like my... body.",
          bAllowClickSkipScript = false
        },
        [72100904] = {
          DialogueId = 72100904,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E90",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101001] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101001,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4E7A",
          NextDialogue = 72101002,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101002] = {
          ContentES = "El Polvo corrompido lo cubre todo, devora el cielo. Imposible distinguir la dirección, ni siquiera el camino recorrido…",
          DialogueId = 72101002,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4EA4",
          NextDialogue = 72101003,
          SpeakNpcId = 830001,
          Subtitle = "The Gritblight blots out the sky. No sense of direction, can't even tell where I came from..."
        },
        [72101003] = {
          ContentES = "Qué suerte tenerte aquí para guiarme. Gracias a ti, {性别:amigo venido|amiga venida} de lejos.",
          DialogueId = 72101003,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4ECE",
          NextDialogue = 72101004,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Lucky to have you show me the way. Thank you, friend from afar.",
          bAllowClickSkipScript = false
        },
        [72101004] = {
          DialogueId = 72101004,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4EF8",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101101] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101101,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5EE2",
          NextDialogue = 72101102,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101102] = {
          ContentES = "¡Je je je! ¡Me has encontrado! ¡Todo está ocurriendo exactamente según mi plan!",
          DialogueId = 72101102,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5F0C",
          NextDialogue = 72101103,
          SpeakNpcId = 830001,
          Subtitle = "E-hehe! You found me! All according to my grand scheme!"
        },
        [72101103] = {
          ContentES = "Según el plan, el siguiente paso es entregarte esto.",
          DialogueId = 72101103,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5F36",
          NextDialogue = 72101104,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "As planned, the next step is to give you this!",
          bAllowClickSkipScript = false
        },
        [72101104] = {
          DialogueId = 72101104,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
