        },
        [72101301] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101301,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F7FB2",
          NextDialogue = 72101302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101302] = {
          ContentES = "El agua golpea la piedra, se filtra en la tierra y nutre toda vida.",
          DialogueId = 72101302,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F7FDC",
          NextDialogue = 72101303,
          SpeakNpcId = 830001,
          Subtitle = "Water strikes stone, soaks the earth, and gives life to all things."
        },
        [72101303] = {
          ContentES = "Dicen que al final, todos llegan a un lugar llamado el Río del Olvido… ¿Es este río… también un riachuelo como este?",
          DialogueId = 72101303,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F8006",
          NextDialogue = 72101304,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I've heard that in the end, everyone goes to a place called the River of Forgetting. Is this river... a stream like this one too?",
          bAllowClickSkipScript = false
        },
        [72101304] = {
          DialogueId = 72101304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F8030",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F901A",
          NextDialogue = 72101402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101402] = {
          ContentES = "Los juncos son altos, tan altos que ocultan todo en su interior; no se ve nada.",
          DialogueId = 72101402,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F9044",
          NextDialogue = 72101403,
          SpeakNpcId = 830001,
          Subtitle = "Reeds so tall, tall and deep. Hide inside, secrets keep."
        },
        [72101403] = {
          ContentES = "¡Jiji! Sin este claro entre los juncos, ¿cómo me habrías encontrado?",
          DialogueId = 72101403,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F906E",
          NextDialogue = 72101404,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Hehe, if not for this bald patch in the reeds, how could you ever have found me?",
          bAllowClickSkipScript = false
        },
        [72101404] = {
          DialogueId = 72101404,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F9098",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101501] = {
          Camera = "196.204834,-2.952158,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101501,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA082",
          NextDialogue = 72101502,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101502] = {
          ContentES = "¿Cómo se formó esta piedra puntiaguda? La he estado observando durante tanto tiempo…",
          DialogueId = 72101502,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA0AC",
          NextDialogue = 72101503,
          SpeakNpcId = 830001,
          Subtitle = "How was this sharp stone formed? I've been watching it for so long."
        },
        [72101503] = {
          ContentES = "Es tan afilada… Haría una lanza perfectamente puntiaguda.",
          DialogueId = 72101503,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA0D6",
          NextDialogue = 72101504,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "It's so sharp. It would make a perfect, keen spear.",
          bAllowClickSkipScript = false
        },
        [72101504] = {
          DialogueId = 72101504,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA100",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101601] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101601,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB0EA",
          NextDialogue = 72101602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101602] = {
          ContentES = "¡La pendiente llama! ¡Llevado por el viento, pisando las flores, bajo la pendiente a toda velocidad!",
          DialogueId = 72101602,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB114",
          NextDialogue = 72101603,
          SpeakNpcId = 830001,
          Subtitle = "The slope calls! I ride the wind, tread the blooms, and race it to the bottom!"
        },
        [72101603] = {
          ContentES = "¡Yuju! ¡No me detengas!",
          DialogueId = 72101603,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB13E",
          NextDialogue = 72101604,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Woo-hoo! Don't try to stop me!",
          bAllowClickSkipScript = false
        },
        [72101604] = {
          DialogueId = 72101604,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB168",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101701] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101701,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC152",
          NextDialogue = 72101702,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101702] = {
          ContentES = "Esos tonos amarillos brillantes… ¿Son hojas caídas o pétalos?",
          DialogueId = 72101702,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC17C",
          NextDialogue = 72101703,
          SpeakNpcId = 830001,
          Subtitle = "These bright yellow colours... Are they fallen leaves, or petals?"
        },
        [72101703] = {
          ContentES = "No lo sé… Pero lo que me rodea es rosa y violeta. Me detectaste al primer vistazo, ¿verdad?",
          DialogueId = 72101703,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC1A6",
          NextDialogue = 72101704,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I don't know... But what envelops me is pink and purple. You must have spotted that right away, didn't you?",
          bAllowClickSkipScript = false
        },
        [72101704] = {
          DialogueId = 72101704,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC1D0",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72999999] = {
          DialogueId = 72999999,
          DialoguePanelType = "AllHide",
          Duration = 1.4,
          GUID = "B6BF7256"
        },
        [73000201] = {
          ContentES = "He mejorado este dispositivo. Vamos, inténtalo otra vez, ayúdame a probar estos ajustes. ¡Me costó una fortuna traerlo desde Elysium…! ¡Esta vez no escaparás!",
          DialogueId = 73000201,
          GUID = "B6BF937A",
          SpeakNpcId = 818022,
          Subtitle = "I gave this thing another upgrade — go on, give it a whirl and help me test the tweaks. Cost me a fortune to smuggle in from Elysium, y'know. No way you're getting through this time!"
        },
        [73000202] = {
          ContentES = "¿Quieres intentarlo de nuevo? Claro, ¿por qué no? Ustedes los ágiles realmente aman saltar por todas partes, ¿eh?",
          DialogueId = 73000202,
          GUID = "B6BF93A4",
          SpeakNpcId = 818022,
          Subtitle = "You wanna go again? Sure, why not. You nimble types really love bouncing around, huh?"
        },
        [73000203] = {
          ContentES = "¿Eh? ¿¡Otra vez lo lograste!? Al menos falla una vez… No, tengo que optimizarlo un poco más.",
          DialogueId = 73000203,
          GUID = "B6BF93CE",
          SpeakNpcId = 818022,
          Subtitle = "What!? Again...? Can't you just fail once? Fine, fine... guess it still needs a bit more work."
        },
        [73000204] = {
          ContentES = "¡Sí, eso es! ¡El efecto que quería! ¿Honestamente? Todavía no sé para qué sirve realmente… pero bueno, seguro que le encontraré utilidad.",
          DialogueId = 73000204,
          GUID = "B6BF93F8",
          SpeakNpcId = 818022,
          Subtitle = "Yep, that's more like it! Honestly? Still not sure what practical use it has... but hey, gotta be good for something."
        },
        [73000301] = {
          ContentES = "Ah, vuelves… justo cuando acababa de traer una nueva mejora. La versión anterior era demasiado fácil, pero esta vez… ¡apuesto a que tropezarás!",
          DialogueId = 73000301,
          GUID = "B6BFA3E2",
          SpeakNpcId = 818022,
          Subtitle = "You're back. Good timing — I gave it another upgrade. Last one was way too easy. But this time? I bet you'll trip at least once."
        },
        [73000302] = {
          ContentES = "¿Quieres intentarlo de nuevo? Claro, ¿por qué no? Ustedes los ágiles realmente aman saltar por todas partes, ¿eh?",
          DialogueId = 73000302,
          GUID = "B6BFA40C",
          SpeakNpcId = 818022,
          Subtitle = "You wanna go again? Sure, why not. You nimble types really love bouncing around, huh?"
        },
        [73000303] = {
          ContentES = "¿¡Qué!? ¿Otra vez lo lograste? Imposible… Gasté un montón de monedas en mejorarlo, ¡no me rendiré! ¡Espera un poco, la próxima vez te atraparé!",
          DialogueId = 73000303,
          GUID = "B6BFA436",
          SpeakNpcId = 818022,
          Subtitle = "Again!? Seriously!? I've poured so much into upgrading this thing... But I'm not giving up! Just you wait — I'll get you next time!"
        },
        [73000304] = {
          ContentES = "Je, je… viéndote moverte así, se me ocurrió una idea. Se lo propondré a mi superior: instalar este dispositivo en las puertas de Lago Helado, para impedir cualquier intrusión…",
          DialogueId = 73000304,
          GUID = "B6BFA460",
          SpeakNpcId = 818022,
          Subtitle = "Hah! Watching you flail around just now gave me an idea. I'll pitch it to my superior — slap this baby on the Icelake gates and stop anyone from barging in!"
        },
        [73000401] = {
          ContentES = "¡Por fin llegas! Te estaba esperando. Esta vez invertí todos mis ahorros para volver este mecanismo devastador. Ahora es perfecto… ¡no tienes ninguna posibilidad de pasar!",
          DialogueId = 73000401,
          GUID = "B6BFB44A",
          SpeakNpcId = 818022,
          Subtitle = "There you are! I've been waiting. I poured every last coin into this baby — she's a beast now. No way you're getting through this time."
        },
        [73000402] = {
          ContentES = "¿Quieres intentarlo de nuevo? Claro, ¿por qué no? Ustedes los ágiles realmente aman saltar por todas partes, ¿eh?",
          DialogueId = 73000402,
          GUID = "B6BFB474",
          SpeakNpcId = 818022,
          Subtitle = "You wanna go again? Sure, why not. You nimble types really love bouncing around, huh?"
        },
        [73000403] = {
          ContentES = "¿Otra vez… otra vez falló?! ¡Ya basta! Debí haberlo sabido: no se puede esperar nada bueno de la chatarra de Elysium. Este es el precio de haber desobedecido a Su Majestad…",
          DialogueId = 73000403,
          GUID = "B6BFB49E",
          SpeakNpcId = 818022,
          Subtitle = "Again!? Are you kidding me!? Ugh... Y'know what, forget it. I should've known better than to trust Elysian tech. This is what I get for smuggling their junk behind His Majesty's back."
        },
        [73000404] = {
          ContentES = "Bah. Dejaré este trasto aquí. Diviértete con él si te da la gana… De todos modos, parece que te divierte.",
          DialogueId = 73000404,
          GUID = "B6BFB4C8",
          SpeakNpcId = 818022,
          Subtitle = "Fine. I'm leaving this thing right here. Do what you want with it. Not like you're not having fun anyway."
        },
        [73000405] = {
          ContentES = "¿Y bien? ¿Ya probaste su poder? Je, je… incluso podría ofrecérselo a Su Majestad, proponer usarlo para entrenar y seleccionar a los reclutas. Con la recompensa, por fin podré pagar todas las deudas que contraje para mejorarlo.",
          DialogueId = 73000405,
          GUID = "B6BFB4F2",
          SpeakNpcId = 818022,
          Subtitle = "Ha! Gotcha at last! This thing's a masterpiece — I oughta present it to His Majesty himself. Perfect for screening recruits. I'll finally rake in a fat bonus and pay off all the debt I racked up building it."
        },
        [73000502] = {
          ContentES = "(La máquina zumba suavemente. Un dial tosco está fijado en ella, grabado con tres opciones: Fácil, Difícil y Extremo. Un dial tosco está fijado en ella, grabado con tres opciones: Fácil, Difícil y Extremo.)",
          DialogueId = 73000502,
          GUID = "B6BFC4DC",
          SpeakNpcId = 818022,
          Subtitle = "(The machine hums softly. A crude dial sits atop it, etched with three labels: Easy, Hard, and Extremely Hard. Looks like the handiwork of that overly chatty soldier.)"
        },
        [73000601] = {
          Content = "（是运输用升降机，兴许可以得到补给。不过，也要小心留意是否有埋伏的敌人。）",
          DialogueId = 73000601,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFD51A",
          SpeakNpcId = 110022,
          Subtitle = "(A cargo lift. Could be a good chance to resupply... but I'd better stay alert. Could be an ambush.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [73000701] = {
          Content = "这个房间暂时安全，可以操作控制台了。",
          DialogueId = 73000701,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFE582",
          SpeakNpcId = 110022,
          Subtitle = "Room's clear for now. Time to access the control panel.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [73000801] = {
          Content = "获取控制权限中，请稍等。",
          DialogueId = 73000801,
          GUID = "B6BFF5EA",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Authorising access. Please wait...",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [73000901] = {
          Content = "（中央控制室是独立供能……这里的髓动轮并未受到动力室爆炸的影响。）",
          DialogueId = 73000901,
          ExStoryInfo = "EXPlayer",
          GUID = "B6C00652",
          SpeakNpcId = 110022,
          Subtitle = "(So the Central Control Room runs on a separate grid... That's why the blast didn't reach this part.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [73001001] = {
          Content = "线路错误，控制台处于保护状态。请关闭髓动轮以解除保护状态。",
          DialogueId = 73001001,
          GUID = "B6C016BA",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Power flow error detected. Control panel locked for protection. Please shut down all Phoxynamo Wheels to lift the lock.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [80001001] = {
          ContentES = "¡Oh! ¡Estoy frente a la casa del Gran Mago! Toc, toc, toc… ¡Gran Mago, estás ahí?",
          DialogueId = 80001001,
          GUID = "C8462C3A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Wow, I'm at the door of the Great Magician's house! Knock, knock~ Great Magician, are you home?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C3A"
        },
        [80001002] = {
          ContentES = "Hmm… Ninguna respuesta. Parece que ha salido. ¡Vamos a ver afuera si podemos encontrarlo!",
          DialogueId = 80001002,
          GUID = "C8462C64",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Hmm, no response... Looks like he went out. Let's go and look for him then!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C64"
        },
        [80001003] = {
          ContentES = "Oh… la historia frente a mí ni siquiera tiene colores… ¡Pero no importa, tengo mi pincel mágico! ¡Voy a colorear la historia mientras avanzo!",
          DialogueId = 80001003,
          GUID = "C8462C8E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Oh, the story ahead has no colour... That's okay, I can paint the story with my magic brush while I go forward.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C8E"
        },
        [80001004] = {
          ContentES = "Vamos, tomemos este camino y sigamos las pistas del Gran Mago.",
          DialogueId = 80001004,
          GUID = "C8462CB8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's go along this path to find the Great Magician.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CB8"
        },
        [80001005] = {
          ContentES = "¿Eh? Pero… no hay ni una sola flor en el jardín…",
          DialogueId = 80001005,
          GUID = "C8462CE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80001006,
          SpeakNpcId = 700142,
          Subtitle = "How come? There isn't a single flower in the garden...",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CE2"
        },
        [80001006] = {
          ContentES = "¡Haré aparecer unas flores bonitas aquí!",
          DialogueId = 80001006,
          GUID = "C8462D0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let me sprinkle some beautiful flowers here!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D0C"
        },
        [80001007] = {
          ContentES = "¡Listo! ¡Así se ve mucho mejor! ¡Continuemos nuestra aventura!",
          DialogueId = 80001007,
          GUID = "C8462D36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Now, the garden looks much prettier. Let's continue the journey~",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D36"
        },
        [80001008] = {
          ContentES = "Oh… ¡Es una pluma dejada por el Pequeño Ruiseñor!",
          DialogueId = 80001008,
          GUID = "C8462D60",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80001009,
          SpeakNpcId = 700142,
          Subtitle = "Wait, these are... feathers from the Little Nightingale!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D60"
        },
        [80001009] = {
          ContentES = "Reunamos las plumas. Seguro que nos traerán buena suerte.",
          DialogueId = 80001009,
          GUID = "C8462D8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's gather the feathers — It will bring us good luck.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D8A"
        },
        [80001010] = {
          ContentES = "El camino está bloqueado… ¿Cómo puedo hacer que estas lianas se aparten?",
          DialogueId = 80001010,
          GUID = "C8462DB4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "The road ahead is blocked... What should I do to ask the vines to make way?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DB4"
        },
        [80001011] = {
          ContentES = "¡Genial! ¡Ahora puedo avanzar!",
          DialogueId = 80001011,
          GUID = "C8462DDE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Great! Now I can keep going~",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DDE"
        },
        [80001012] = {
          ContentES = "Quizás el Gran Mago esté allí…",
          DialogueId = 80001012,
          GUID = "C8462E08",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Would the Great Magician be there?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E08"
        },
        [80001013] = {
          ContentES = "¿Oh? La hoguera sigue encendida… Parece que el Gran Mago se fue hace solo unos momentos.",
          DialogueId = 80001013,
          GUID = "C8462E32",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Oh? The bonfire is still burning — looks like the Great Magician left only moments ago.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E32"
        },
        [80001014] = {
          ContentES = "¡Guau… las luciérnagas brillan como pequeñas estrellas que vuelan!",
          DialogueId = 80001014,
          GUID = "C8462E5C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Whoa, the moment the fireflies scattered... It's like the stars had suddenly grown wings.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E5C"
        },
        [80001015] = {
          ContentES = "Aquí también han brotado bonitas flores.",
          DialogueId = 80001015,
          GUID = "C8462E86",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80001016,
          SpeakNpcId = 700142,
          Subtitle = "Lovely blossoms have unfurled here, too.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E86"
        },
        [80001016] = {
          ContentES = "¡Y mira, hongos redonditos! Si salto sobre uno, seguro rebotaré muy alto.",
          DialogueId = 80001016,
          GUID = "C8462EB0",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "And look, round mushrooms! If you stepped on one, it'd send you springing sky-high!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EB0"
        },
        [80001017] = {
          ContentES = "¿¡Un tesoro?! ¿Será… el escondite secreto del Gran Mago?",
          DialogueId = 80001017,
          GUID = "C8462EDA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Didn't expect to see a treasure chest here. Could it be the Great Magician's secret hoard?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EDA"
        },
        [80001018] = {
          ContentES = "No hay camino más adelante… ¿Cómo voy a cruzar?",
          DialogueId = 80001018,
          GUID = "C8462F04",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "There's no way ahead. How can I get through?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F04"
        },
        [80001019] = {
          ContentES = "¡Guau…! ¡Qué hongos tan adorables! ¿Habéis venido a ayudarme?",
          DialogueId = 80001019,
          GUID = "C8462F2E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80001020,
          SpeakNpcId = 700142,
          Subtitle = "Wow...! Lovely mushrooms! Are you here to help me?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F2E"
        },
        [80001020] = {
          ContentES = "¡Muchas gracias! Así puedo saltar al otro lado.",
          DialogueId = 80001020,
          GUID = "C8462F58",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Thank you. This way, I can just jump to the other side.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F58"
        },
        [80001021] = {
          ContentES = "¡Oh! Aquí también hay un cofre… ¿Lo dejó el Gran Mago a propósito para mí?",
          DialogueId = 80001021,
          GUID = "C8462F82",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Huh, there's a treasure chest here too?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F82"
        },
        [80001022] = {
          Camera = "55.417297,85.066406,122.219238,0.000047,0.044225,-103.953941,35.0,272.596405,false,Manual,7.0",
          ContentES = "¡Gran Mago! ¡Por fin te he encontrado!",
          DialogueId = 80001022,
          Duration = 8,
          GUID = "C8462FAC",
          NextDialogue = 80001023,
          Scripts = [[
PARA{
CameraMoveTo{_delay{0.1},TargetPosition{"85.921997,188.681641,126.737305,0.000048,-0.755863,-106.954742,35.0,272.596405,false,Manual,7.0"},duration{8}},
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{"Feina_Story_Wish_Start"},Duration{2}}
}]],
          SpeakNpcId = 700142,
          Subtitle = "Great Magician, I've finally found you!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462FAC"
        },
        [80001023] = {
