          SpeakNpcId = 700142,
          Subtitle = "It looks like it's longing for a different colour.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0A"
        },
        [80004252] = {
          ContentES = "Oh no… el color que acabo de pintar ha desaparecido…",
          DialogueId = 80004252,
          Duration = 3,
          GUID = "C8483B0B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004253,
          SpeakNpcId = 700142,
          Subtitle = "Oh no, the colour I just painted is gone...",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0B"
        },
        [80004253] = {
          ContentES = "¡Debo pintar más rápido antes de que desaparezca de nuevo!",
          DialogueId = 80004253,
          Duration = 3,
          GUID = "C8483B0C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "I'll have to paint faster before the next vanish!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0C"
        },
        [80004254] = {
          Camera = "-4.021118,-147.850586,140.854248,0.000064,-3.469995,89.231857,35.0,160.025635,false,Manual,12.0",
          ContentES = "Todavía me faltan algunas plumas del Pequeño Ruiseñor… ¿Volvemos a buscar?",
          DialogueId = 80004254,
          Duration = 12,
          GUID = "C8483B0D",
          Scripts = [[
PARA{
CameraMoveTo{_delay{6.5},TargetPosition{"-130.023865,-580.916016,82.43866,0.000115,4.930222,79.821289,35.000011,872.114136,false,Manual,12.0"},duration{8}},
SEQ{
PARA{
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Think01"}}
},
PlayAnimation{_delay{2.5},ActorId{211001},AnimationId{"Think_End"},Duration{1}},
TurnTo{_delay{1},TurnToDescription{"211001:p(180)"}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Smile01"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "(Still missing some feathers... Should we head back and search again?)"
        },
        [80010100] = {
          Content = "嗯，荣幸之至。",
          DialogueId = 80010100,
          GUID = "C84C0108",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0108"
        },
        [80010101] = {
          Content = "这是为了维系您与我之间的友谊，而有意为之的邀约，对吗？",
          DialogueId = 80010101,
          GUID = "C84C0132",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0132"
        },
        [80010102] = {
          Content = "好，那么我愿与您共饮。",
          DialogueId = 80010102,
          GUID = "C84C015C",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C015C"
        },
        [80010103] = {
          Content = "唔，咳……",
          DialogueId = 80010103,
          GUID = "C84C0186",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0186"
        },
        [80010104] = {
          Content = "没什么，请继续讲吧。",
          DialogueId = 80010104,
          GUID = "C84C01B0",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C01B0"
        },
        [80010105] = {
          Content = "不，只是……",
          DialogueId = 80010105,
          GUID = "C84C01DA",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C01DA"
        },
        [80010106] = {
          Content = "嗯。被您看穿了呢。",
          DialogueId = 80010106,
          GUID = "C84C0204",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0204"
        },
        [80010107] = {
          Content = "酒的味道，颇有些……浓烈。长久以来，受到家族较多管束的缘故，我极少品尝这种饮品。",
          DialogueId = 80010107,
          GUID = "C84C022E",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C022E"
        },
        [80010108] = {
          Content = "但既然您饱含诚意的邀请了，那回绝就过于失礼。",
          DialogueId = 80010108,
          GUID = "C84C0258",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0258"
        },
        [80010109] = {
          Content = "您不必为此介怀。对宾客投其所好或许是尽地主之谊的必要礼节，但适逢其时的好意本身已经足以慰藉风尘。",
          DialogueId = 80010109,
          GUID = "C84C0282",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0282"
        },
        [80010110] = {
          Content = "而且，我也在逐步学会适应“外面的一切”。",
          DialogueId = 80010110,
          GUID = "C84C02AC",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C02AC"
        },
        [80010111] = {
          Content = "第一次抵达北境的时候，在冰天雪地的荒原上，也曾有一位年迈的猎人给了我同样的东西。",
          DialogueId = 80010111,
          GUID = "C84C02D6",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C02D6"
        },
        [80010112] = {
          Content = "“烈酒”。",
          DialogueId = 80010112,
          GUID = "C84C0300",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0300"
        },
        [80010113] = {
          Content = "远比您调制的这杯更辛辣，更苦涩，甚至让人难以保持清醒的意志。",
          DialogueId = 80010113,
          GUID = "C84C032A",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C032A"
        },
        [80010114] = {
          Content = "但却非常温暖。像一小簇火苗，让几乎冻僵的我们再次有了活着的知觉。",
          DialogueId = 80010114,
          GUID = "C84C0354",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0354"
        },
        [80010115] = {
          Content = "是的，这没什么值得隐瞒的。",
          DialogueId = 80010115,
          GUID = "C84C037E",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C037E"
        },
        [80010116] = {
          Content = "您这个玩笑……我并不觉得非常有趣。",
          DialogueId = 80010116,
          GUID = "C84C03A8",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03A8"
        },
        [80010117] = {
          Content = "我是一名漂泊之人，如您所见。",
          DialogueId = 80010117,
          GUID = "C84C03D2",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03D2"
        },
        [80010118] = {
          Content = "也许您已经从希尔妲那里听说过，我们的故土，是迪斯玛尼亚——也许您会更加熟悉它的另一个称呼，“皇都”。",
          DialogueId = 80010118,
          GUID = "C84C03FC",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03FC"
        },
        [80010119] = {
          Content = "在那里，我和家族发生了一些冲突，致使流落至此。",
          DialogueId = 80010119,
          GUID = "C84C0426",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0426"
        },
        [80010120] = {
          Content = "请谅解。您是与我订立过重要契约的人，按照礼节，我本应坦诚以待。",
          DialogueId = 80010120,
          GUID = "C84C0450",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0450"
        },
        [80010121] = {
          Content = "但关于这件事，请容许我保守秘密——",
          DialogueId = 80010121,
          GUID = "C84C047A",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C047A"
        },
        [80010122] = {
          Content = "我对您虽无戒备之心，但出于对您安全的顾虑，还是建议您不要牵涉过深为好。",
          DialogueId = 80010122,
          GUID = "C84C04A4",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C04A4"
        },
        [80010123] = {
          Content = "时间有些迟了，谢谢您今日的邀请。回见。",
          DialogueId = 80010123,
          GUID = "C84C04CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C04CE"
        },
        [80010201] = {
          Content = "与您共度的时光称得上令人欢悦，虽然我还不能很好地适应它的味道。",
          DialogueId = 80010201,
          GUID = "C84C119A",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C119A"
        },
        [80010202] = {
          Content = "嗯……的确没有呢。",
          DialogueId = 80010202,
          GUID = "C84C11C4",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C11C4"
        },
        [80010203] = {
          Content = "请不要误会，我并非在对您的邀约敷衍了事。",
          DialogueId = 80010203,
          GUID = "C84C11EE",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C11EE"
        },
        [80010204] = {
          Content = "只是希尔妲不允许我对食物拥有偏好。她每日都会要求厨师奉上和此前完全不同的菜肴，而这些餐点里，喜爱的也好，厌弃的也好，她都会要求我一视同仁地品尝。",
          DialogueId = 80010204,
          GUID = "C84C1218",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1218"
        },
        [80010205] = {
          Content = "久而久之，我也就没有什么“喜爱的味道”了。",
          DialogueId = 80010205,
          GUID = "C84C1242",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1242"
        },
        [80010206] = {
          Content = "呵呵……您或许误解她了。她不是无礼之徒，此举也绝非傲慢地越俎代庖。",
          DialogueId = 80010206,
          GUID = "C84C126C",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C126C"
        },
        [80010207] = {
          Content = "呵呵……如果您是我，想必就不会说出这样的话了。",
          DialogueId = 80010207,
          GUID = "C84C1296",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1296"
        },
        [80010208] = {
          Content = "希尔妲是个敏锐的姑娘。她非常清楚，对我而言，拥有喜好，便意味着危险。",
          DialogueId = 80010208,
          GUID = "C84C12C0",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C12C0"
        },
        [80010209] = {
          Content = "比如……我来问您一个问题。您看这杯酒——",
          DialogueId = 80010209,
          GUID = "C84C12EA",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C12EA"
        },
        [80010210] = {
          Content = "假设我喜爱浸泡了罗勒叶和迷迭香的酒，每次都会一饮而尽，",
          DialogueId = 80010210,
          GUID = "C84C1314",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1314"
        },
        [80010211] = {
          Content = "而您又是一名受雇于主，混迹于一众家仆之中，想要夺取我性命的“窥伺者”，",
          DialogueId = 80010211,
          GUID = "C84C133E",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C133E"
        },
        [80010212] = {
          Content = "您要如何忍住，不把那漂亮而致命的毒液涂抹在罗勒叶之上呢？",
          DialogueId = 80010212,
          GUID = "C84C1368",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1368"
        },
        [80010213] = {
          Content = "哦？我只是做个简单的比喻。难道您真的……",
          DialogueId = 80010213,
          GUID = "C84C1392",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1392"
        },
        [80010214] = {
          Content = "呵呵，别太紧张。我不会怀疑您。",
          DialogueId = 80010214,
          GUID = "C84C13BC",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C13BC"
        },
        [80010215] = {
          Content = "的确……",
          DialogueId = 80010215,
          GUID = "C84C13E6",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C13E6"
        },
        [80010216] = {
          Content = "在我身边环绕着的人……或许更应该称呼他们是兽群。",
          DialogueId = 80010216,
          GUID = "C84C1410",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1410"
        },
        [80010217] = {
          Content = "他们像是一群秃鹫，随时在等待着我停止挣扎的一刻，然后分食。",
          DialogueId = 80010217,
          GUID = "C84C143A",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C143A"
        },
        [80010218] = {
          Content = "迪斯玛尼亚的每一粒灵魂，包括我自己，都是污浊的。",
          DialogueId = 80010218,
          GUID = "C84C1464",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1464"
        },
        [80010219] = {
          Content = "呵呵……也许对您而言，漂泊在外意味着异邦的风土，喧哗而有趣的人们，焕然一新的人生。但至于我……",
          DialogueId = 80010219,
          GUID = "C84C148E",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C148E"
        },
        [80010220] = {
          Content = "陌生的土地给了我片刻喘息，但我终究要到故乡。不过，并非因为我有多怀念它。",
          DialogueId = 80010220,
          GUID = "C84C14B8",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C14B8"
        },
        [80010221] = {
          Content = "而是我全部的爱与憎恨，思念与愤怒，都在那个地方。",
          DialogueId = 80010221,
          GUID = "C84C14E2",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C14E2"
        },
        [80010222] = {
          Content = "我该走了。还有……",
          DialogueId = 80010222,
          GUID = "C84C150C",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C150C"
        },
        [80010223] = {
          Content = "尝得出，相比上次，您在调和时有意减淡了口味。",
          DialogueId = 80010223,
          GUID = "C84C1536",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1536"
        },
        [80010224] = {
          Content = "多谢您，将我的无意之言记挂在心。",
          DialogueId = 80010224,
          GUID = "C84C1560",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1560"
        },
        [80010301] = {
          Content = "尝得出，您调制饮品的手艺愈发娴熟，甚至达到了希尔妲五成的水准。",
          DialogueId = 80010301,
          GUID = "C84C2202",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2202"
        },
        [80010302] = {
          Content = "我不像希尔妲那样，擅长社交上的体面辞令。我的意思是，以她为基准的话，五成也已经很了不起了。",
          DialogueId = 80010302,
          GUID = "C84C222C",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C222C"
        },
        [80010303] = {
          Content = "如果说有什么值得特别留意的……",
          DialogueId = 80010303,
          GUID = "C84C2256",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2256"
        },
        [80010304] = {
          Content = "那就是您过于平等地糅合了所有原料，反而让人无法品尝出它的基底——也就是，调制者最想要呈现的味道。",
          DialogueId = 80010304,
          GUID = "C84C2280",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2280"
        },
        [80010305] = {
          Content = "您近日心绪也有些乱。也许，忧虑太多纷杂的事，不如选择一件最重要的，细细研磨。",
          DialogueId = 80010305,
          GUID = "C84C22AA",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22AA"
        },
        [80010306] = {
          Content = "啊……",
          DialogueId = 80010306,
          GUID = "C84C22D4",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22D4"
        },
        [80010307] = {
          Content = "杯子……粘上了……抱歉，我并非有意弄脏它。",
          DialogueId = 80010307,
          GUID = "C84C22FE",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22FE"
        },
        [80010308] = {
          Content = "只是赴约之前，我刚刚完成那幅画。没有希尔妲提醒，我忘记手指沾了些颜料。",
          DialogueId = 80010308,
          GUID = "C84C2328",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2328"
        },
        [80010309] = {
          Content = "…………",
          DialogueId = 80010309,
          GUID = "C84C2352",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2352"
        },
        [80010310] = {
          Content = "是您的话，倒无妨。",
          DialogueId = 80010310,
          GUID = "C84C237C",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C237C"
        },
        [80010311] = {
          Content = "过去吗？呵呵……如果这是真正的过去，就好了。",
          DialogueId = 80010311,
          GUID = "C84C23A6",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23A6"
        },
        [80010312] = {
          Content = "父亲、母亲……",
          DialogueId = 80010312,
          GUID = "C84C23D0",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23D0"
        },
        [80010313] = {
          Content = "其实我从未见过他们。",
          DialogueId = 80010313,
          GUID = "C84C23FA",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23FA"
        },
        [80010314] = {
          Content = "在我的居所，他们存在过的痕迹——连同他们的画像——都已经被残忍粗暴地抹去了。我只能通过老仆人的只言片语，去想象他们的样子。",
          DialogueId = 80010314,
          GUID = "C84C2424",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2424"
        },
        [80010315] = {
          Content = "年岁尚小的时候啊，我每天都在想，我总会与他们相见的。就在未来的某一天……",
          DialogueId = 80010315,
          GUID = "C84C244E",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C244E"
        },
        [80010316] = {
          Content = "到那天，我们就可以像这样，邀来最优秀的画师，来为我们画一幅家族肖像。像那些可爱的三口之家一样。",
          DialogueId = 80010316,
          GUID = "C84C2478",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2478"
        },
        [80010317] = {
          Content = "但真正到了我能够把心中所思绘制在画布上的年纪，我才知道，我画的不是过去，亦非未来。",
          DialogueId = 80010317,
          GUID = "C84C24A2",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24A2"
        },
        [80010318] = {
          Content = "而是从未存在过，将来也不会存在的……",
          DialogueId = 80010318,
          GUID = "C84C24CC",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24CC"
        },
        [80010319] = {
          Content = "“泡影”。",
          DialogueId = 80010319,
          GUID = "C84C24F6",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24F6"
        },
        [80010320] = {
          Content = "嗯。也许您早已猜到，在我记事之前，他们已经是墓园的白骨。",
          DialogueId = 80010320,
          GUID = "C84C2520",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2520"
        },
        [80010321] = {
          Content = "抱歉，我不小心自顾自地说起来了，连带您的心情也变糟糕了吧。",
          DialogueId = 80010321,
          GUID = "C84C254A",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C254A"
        },
        [80010322] = {
          Content = "您认真地准备了饮品和茶点，想必并非打算听我喋喋不休地叨念些不快的旧事。",
          DialogueId = 80010322,
          GUID = "C84C2574",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2574"
        },
        [80010323] = {
          Content = "我们来聊些其他的吧，比如珀西·巴莱德的诗集。",
          DialogueId = 80010323,
          GUID = "C84C259E",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C259E"
        },
        [80010401] = {
          Content = "……您又邀请了我呢。真是奇怪。",
          DialogueId = 80010401,
          GUID = "C84C326A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C326A"
        },
        [80010402] = {
          Content = "我认为，我并不是一个可以给您带来欢愉的攀谈对象。",
          DialogueId = 80010402,
          GUID = "C84C3294",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3294"
        },
        [80010403] = {
          Content = "我今天读了一句诗：“好奇心会杀死一只知更鸟”……",
          DialogueId = 80010403,
          GUID = "C84C32BE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C32BE"
        },
        [80010404] = {
          Content = "罢了，既然您再度问起，那么我讲一个故事吧。",
          DialogueId = 80010404,
          GUID = "C84C32E8",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C32E8"
        },
        [80010405] = {
          Content = "很久很久之前，有一个年轻的姑娘，她从出生起就住在一座黄金的牢笼里……",
          DialogueId = 80010405,
          GUID = "C84C3312",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3312"
        },
        [80010406] = {
          Content = "她似乎拥有世上的一切：她有一百顶镶着璀璨钻石的冠冕，有一百件皎洁珍珠编织的衣衫，有一百名仆人每天献上沾着晨露的鲜花……",
          DialogueId = 80010406,
          GUID = "C84C333C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C333C"
        },
        [80010407] = {
          Content = "但有一件东西是她始终得不到的：那就是黄金牢笼外的任何事物，哪怕是一滴雨，一缕风。",
          DialogueId = 80010407,
          GUID = "C84C3366",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3366"
        },
        [80010408] = {
          Content = "一个夜晚，一条陌生的龙闯进了黄金的牢笼。",
          DialogueId = 80010408,
          GUID = "C84C3390",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3390"
        },
        [80010409] = {
          Content = "她不知道那条龙硕大的身躯是如何钻进狭窄的栅栏，只知道它带来了她梦寐以求的一切——诗集，油彩，琴弦，剑术……以及她日思夜想的，牢笼之外的故事。",
          DialogueId = 80010409,
          GUID = "C84C33BA",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C33BA"
        },
        [80010410] = {
          Content = "虽然身在牢笼之中，但她却从龙带来的故事里，看到了广阔的天空，触摸到旷野的清风，奔跑在金色的麦田，听到了广场上吟游诗人的歌谣。",
          DialogueId = 80010410,
          GUID = "C84C33E4",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C33E4"
        },
        [80010411] = {
          Content = "她是如此感谢龙带给她的一切……",
          DialogueId = 80010411,
          GUID = "C84C340E",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C340E"
        },
        [80010412] = {
          Content = "直到有一天，她无意间从传言中得知，正是那条龙，在她还在襁褓中时，灭亡了她的城市，杀死了她的亲生父亲……是的，它是一条恶龙。",
          DialogueId = 80010412,
          GUID = "C84C3438",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3438"
        },
        [80010413] = {
          Content = "然后，恶龙将她锁进了这座黄金的监牢。",
          DialogueId = 80010413,
          GUID = "C84C3462",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3462"
        },
        [80010414] = {
          Content = "少女将愤怒熔铸成刺剑，等待着恶龙再次踏着月色来访，她发誓将以利刃贯穿恶龙的心脏。但最后，她却犹疑了。她颤抖着询问传言的虚实，她渴望得到错误的答案。",
          DialogueId = 80010414,
          GUID = "C84C348C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C348C"
        },
        [80010415] = {
          Content = "但恶龙却亲口承认了一切。最后，她的剑只触及恶龙坚硬的鳞片。",
          DialogueId = 80010415,
          GUID = "C84C34B6",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C34B6"
        },
        [80010416] = {
          Content = "不久之后，黄金囚笼里的吃穿用度，全部变了模样。每日奉上的鲜花，花蕾中再也不是晨露，而是毒刺。",
          DialogueId = 80010416,
          GUID = "C84C34E0",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C34E0"
        },
        [80010417] = {
          Content = "终于有一天，一位聪明的女仆想方设法找到黄金的钥匙，打开了囚笼的门……女仆对少女说，她自由了。",
          DialogueId = 80010417,
          GUID = "C84C350A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C350A"
        },
        [80010418] = {
          Content = "但是少女知道，恶龙焚城的火焰在她的心底燃烧着，记忆的余烬环绕着她，将她投入深渊。她永远不会得到自由了。",
          DialogueId = 80010418,
          GUID = "C84C3534",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3534"
        },
        [80010419] = {
          Content = "嗯，很久之后我才得知，那两场<C=#FF0000>盛大的谋杀</C>。",
          DialogueId = 80010419,
          GUID = "C84C355E",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C355E"
        },
        [80010420] = {
          Content = "从那之后，我的梦中永远是鲜血淋漓的身体，痛苦扭曲的面庞……每一晚，每一晚。",
          DialogueId = 80010420,
          GUID = "C84C3588",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3588"
        },
        [80010421] = {
          Content = "在用小刀划破自己皮肤的时候，我已经是那么痛了。那么被利剑贯穿的父亲，被埋在废墟中的母亲，该有多痛啊……",
          DialogueId = 80010421,
          GUID = "C84C35B2",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C35B2"
        },
        [80010422] = {
          Content = "呵呵，您知道吗？您眼前的芙罗拉，并不是什么优雅高贵的贵族小姐……",
          DialogueId = 80010422,
          GUID = "C84C35DC",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C35DC"
        },
        [80010423] = {
          Content = "她只是一个献祭生命也在所不惜的，复仇的恶鬼啊。",
          DialogueId = 80010423,
          GUID = "C84C3606",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3606"
        },
        [80010424] = {
          Content = "呵呵……呵呵呵。",
          DialogueId = 80010424,
          GUID = "C84C3630",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3630"
        },
        [80010425] = {
          Content = "{NickName}，我想，您拥有一位过于优秀的骑士。",
          DialogueId = 80010425,
          GUID = "C84C365A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C365A"
        },
        [80010426] = {
          Content = "贝蕾妮卡小姐，她把您护佑得多周全啊，无论是身体，还是灵魂。",
          DialogueId = 80010426,
          GUID = "C84C3684",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3684"
        },
        [80010427] = {
          Content = "“新的人生”……好漂亮的愿望，就像孩子们吹出的肥皂泡……",
          DialogueId = 80010427,
          GUID = "C84C36AE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C36AE"
        },
        [80010428] = {
          Content = "呵呵……呵呵呵。",
          DialogueId = 80010428,
          GUID = "C84C36D8",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C36D8"
        },
        [80010429] = {
          Content = "{NickName}，您真的是一个过于天真的家伙。",
          DialogueId = 80010429,
          GUID = "C84C3702",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3702"
        },
        [80010430] = {
          Content = "以至于，您可以笃定地认为，您有资格对抗我所对抗的东西。",
          DialogueId = 80010430,
          GUID = "C84C372C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C372C"
        },
        [80010431] = {
          Content = "您不知道，那是一个怎样的<C=#FF0000>“怪物”</C>……",
          DialogueId = 80010431,
          GUID = "C84C3756",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3756"
        },
        [80010432] = {
          Content = "…………",
          DialogueId = 80010432,
          GUID = "C84C3780",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3780"
        },
        [80010433] = {
          Content = "失礼了，我今天说了太多错误的言辞。",
          DialogueId = 80010433,
          GUID = "C84C37AA",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37AA"
        },
        [80010434] = {
          Content = "把这一切都忘了吧。或者，请您只当它是从某本小说里读来的传奇故事。",
          DialogueId = 80010434,
          GUID = "C84C37D4",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37D4"
        },
        [80010435] = {
          Content = "以及，不要再邀请我赴约了。这样，我还可以视您为一名值得尊敬的受托人。",
          DialogueId = 80010435,
          GUID = "C84C37FE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37FE"
        },
        [80010436] = {
          Content = "只是这样……就好。",
          DialogueId = 80010436,
          GUID = "C84C3828",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3828"
        },
        [80010501] = {
          Content = "我应该说过，请您不要再邀请我。",
          DialogueId = 80010501,
          GUID = "C84C42D2",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C42D2"
        },
        [80010502] = {
          Content = "如果事关我们的契约，谈判桌远比这里更加合适。",
          DialogueId = 80010502,
          GUID = "C84C42FC",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C42FC"
        },
        [80010503] = {
          Content = "呵……",
          DialogueId = 80010503,
          GUID = "C84C4326",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4326"
        },
        [80010504] = {
          Content = "我想，上次我已经给了您清楚的回答。",
          DialogueId = 80010504,
          GUID = "C84C4350",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4350"
        },
        [80010505] = {
          Content = "回去吧。我的前路没有过去，也没有未来。只有紧紧闭锁的漆黑深渊。",
          DialogueId = 80010505,
          GUID = "C84C437A",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C437A"
        },
        [80010506] = {
          Content = "即使是您放声呼喊，也无法将我从那里带回。",
          DialogueId = 80010506,
          GUID = "C84C43A4",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43A4"
        },
        [80010507] = {
          Content = "…………",
          DialogueId = 80010507,
          GUID = "C84C43CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43CE"
        },
        [80010508] = {
          Content = "…………",
          DialogueId = 80010508,
          GUID = "C84C43F8",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43F8"
        },
        [80010509] = {
          Content = "你……",
          DialogueId = 80010509,
          GUID = "C84C4422",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4422"
        },
        [80010510] = {
          Content = "哪来的笨蛋{性别：先生|小姐}，幼稚鬼，秽兽一样的脑袋！你以为你是什么人？传奇小说里的屠龙勇士，神眷之子？少做白日梦了！我们的契约只是要你帮我找东西，可没约定过这种事！",
          DialogueId = 80010510,
          GUID = "C84C444C",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C444C"
        },
        [80010511] = {
          Content = "你知道我的仇人是什么家伙吗？别犯蠢了，他一秒钟，一句话，就足以要你的命。",
          DialogueId = 80010511,
          GUID = "C84C4476",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4476"
        },
        [80010512] = {
          Content = "……失礼了。",
          DialogueId = 80010512,
          GUID = "C84C44A0",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44A0"
        },
        [80010513] = {
          Content = "您……在说些什么。",
          DialogueId = 80010513,
          GUID = "C84C44CA",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CA"
        },
        [80010514] = {
          Content = "我希望可以成为芙罗拉的朋友，而非仅仅是受托人。不……甚至不只是朋友，而是可以共享哀乐，共享命运的人。",
          DialogueId = 80010514,
          GUID = "C84C44CB",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CB"
        },
        [80010515] = {
          Content = "所以，如果我没有可以将芙罗拉带回的绳索，那就让我也一起跳下去吧。",
          DialogueId = 80010515,
          GUID = "C84C44CC",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CC"
        },
        [80010516] = {
          Content = "我不是什么诸神眷顾的屠龙勇者，但我可以和你一起战斗至最后一刻。",
          DialogueId = 80010516,
          GUID = "C84C44CD",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CD"
        },
        [80010517] = {
          Content = "哪怕最终你的剑折断了，至少还有人可以陪你一起躺在血泊里，而不是让你孤独一人面对死亡。",
          DialogueId = 80010517,
          GUID = "C84C44CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CE"
        },
        [80010518] = {
          Content = "…………",
          DialogueId = 80010518,
          GUID = "C84C44F4",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44F4"
        },
        [80010519] = {
          Content = "真是……愚蠢啊。",
          DialogueId = 80010519,
          GUID = "C84C451E",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C451E"
        },
        [80010520] = {
          Content = "说到这份上，我要用什么办法才能甩掉你呢……",
          DialogueId = 80010520,
          GUID = "C84C4548",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4548"
        },
        [80010521] = {
          Content = "我没有过去，也没有未来。",
          DialogueId = 80010521,
          GUID = "C84C4572",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4572"
        },
        [80010522] = {
          Content = "除了千疮百孔的灵魂，一无所有。",
          DialogueId = 80010522,
          GUID = "C84C459C",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C459C"
        },
        [80010523] = {
          Content = "既然你来了……那就和我一起，行走在鲜血淋漓的“现在”吧。",
          DialogueId = 80010523,
          GUID = "C84C45C6",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C45C6"
        },
        [80010524] = {
          Content = "直到那漆黑之物杀死我们，或者我们杀死它。",
          DialogueId = 80010524,
          GUID = "C84C45F0",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C45F0"
        },
        [80020100] = {
          ContentES = "A menos que tengas un encargo para mí, no necesitamos andar con tanta cháchara. Sin embargo, si tu encargo es conversar, entonces una pequeña tarifa de servicio bastará para comprar mi compañía temporal.",
          DialogueId = 80020100,
          GUID = "C85269A8",
          SpeakNpcId = 93102,
          Subtitle = "Unless you have a task for me, we don't need to engage in much small talk. However, if your task is to have a chat, then a small service fee will buy my temporary companionship.",
          VoiceName = "voice/$Locale$/inv/Xier/001/C85269A8"
        },
        [80020201] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentES = "Debo admitirlo, te envidio por tener el tiempo libre para montar una pequeña fiesta de té.",
          DialogueId = 80020201,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8527A3A",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020202,
          SpeakNpcId = 93102,
          Subtitle = "I must say, I envy you for having the leisure to throw a little tea party.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A3A"
        },
        [80020202] = {
          ContentES = "Acabo de terminar un encargo en el norte y siento que me estoy desmoronando de cansancio. Probablemente necesite dormir un día entero para recuperarme.",
          DialogueId = 80020202,
          GUID = "C8527A64",
          NextOptions = {
            [1] = 800202021,
            [2] = 800202022
          },
          SpeakNpcId = 93102,
          Subtitle = "I've just completed a grueling assignment up north and feel like I'm falling apart. I'll probably need a full night and day of sleep to recover.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A64"
        },
        [80020203] = {
          ContentES = "No te preocupes, ya me tienes aquí. Vamos a tomar algo y luego me voy a dormir.",
          DialogueId = 80020203,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527A8E",
          NextDialogue = 80020205,
          SpeakNpcId = 93102,
          Subtitle = "It's fine. I'm already seated — might as well have a drink with you before heading to bed.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A8E"
        },
        [80020204] = {
          ContentES = "Hum... ¿Y si me ayudas con un encargo para que veas cómo se siente?",
          DialogueId = 80020204,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527AB8",
          NextDialogue = 80020205,
          SpeakNpcId = 93102,
          Subtitle = "Perhaps you can handle a commission for me next time.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527AB8"
        },
        [80020205] = {
          ContentES = "Puf, tal vez debería rechazar los encargos de este cliente. La paga es buena, pero apenas vale el riesgo.",
          DialogueId = 80020205,
          GUID = "C8527AE2",
          NextDialogue = 80020206,
          SpeakNpcId = 93102,
          Subtitle = "Mm, maybe I should just reject further commissions from this client. The pay is good but hardly worth the danger.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527AE2"
        },
        [80020206] = {
          ContentES = "Me encargó que entregara una carta bastante insultante a sus parientes aficionados a la violencia, solo para hacerlos enfurecer.",
          DialogueId = 80020206,
          GUID = "C8527B0C",
          NextDialogue = 80020207,
          SpeakNpcId = 93102,
          Subtitle = "She had me deliver a rather colourful letter to her violence-prone relatives back home, designed to make them see red.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B0C"
        },
        [80020207] = {
          ContentES = "Pero como mensajera debo pirarme en el acto: si me hubiera quedado, esos matones, que nunca han sido insultados, me hubieran disparado ahí mismo.",
          DialogueId = 80020207,
          FacialId = {
            [1] = "93102:Uninterested01"
          },
          GUID = "C8527B36",
          NextDialogue = 80020208,
          SpeakNpcId = 93102,
          Subtitle = "I had to bolt the second I delivered the letter; otherwise, the phrase \"shoot the messenger\" might have become more than just metaphorical — I bet those savages have never been on the receiving end of the kind words used in that letter.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B36"
        },
        [80020208] = {
          ContentES = "Luego pasé toda la noche caminando por la nieve para evitar que me alcanzaran. Podría haberme hecho cargo de ellos sin problema, pero no dan paga extra...",
          DialogueId = 80020208,
          GUID = "C8527B60",
          NextDialogue = 80020209,
          SpeakNpcId = 93102,
          Subtitle = "Then it was a whole night's trekking through the snow to dodge ambushes. Sure, I could easily handle them, but there's no extra pay for that...",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B60"
        },
        [80020209] = {
          ContentES = "¿Eh? ¿Por qué esa cara de tanta sorpresa?",
          DialogueId = 80020209,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8527B8A",
          NextOptions = {
            [1] = 800202091,
            [2] = 800202092
          },
          SpeakNpcId = 93102,
          Subtitle = "Hmm? You look astonished. What's wrong?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B8A"
        },
        [80020210] = {
          ContentES = "Claro, al menos por ahora sí.",
          DialogueId = 80020210,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527BB4",
          NextDialogue = 80020212,
          SpeakNpcId = 93102,
          Subtitle = "Of course, at least for now.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527BB4"
        },
        [80020211] = {
          ContentES = "No pasa nada, he vivido cosas aún más peligrosas.",
          DialogueId = 80020211,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527BDE",
          NextDialogue = 80020212,
          SpeakNpcId = 93102,
          Subtitle = "Not really. I've been through worse.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527BDE"
        },
        [80020212] = {
          ContentES = "Antes de ser la criada de la señorita Flora, tuve otro trabajo por un corto tiempo. Fue allí donde aprendí la mayoría de mis habilidades... que a veces pueden ser útiles, y otras no tanto.",
          DialogueId = 80020212,
          GUID = "C8527C08",
          NextDialogue = 80020213,
          SpeakNpcId = 93102,
          Subtitle = "Before I was Miss Flora's maid, I briefly held a different position where I acquired many of the skills I use today, whether necessary or not.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C08"
        },
        [80020213] = {
          ContentES = "Por ejemplo, sé desmontar armas de fuego con rapidez, extraer venenos de plantas y dominar técnicas para noquear a alguien en tres segundos sin poner en peligro su vida...",
          DialogueId = 80020213,
          GUID = "C8527C32",
          NextDialogue = 80020214,
          SpeakNpcId = 93102,
          Subtitle = "Like how to swiftly dismantle firearms, extract poison from plants, or knock someone out in three seconds without serious harm...",
          TalkActionId = {
            [1] = "93102:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C32"
        },
        [80020214] = {
          ContentES = "Pues ya que eres mi cliente a largo plazo, no hace falta ocultarlo. En realidad, en el pasado trabajé como agente.",
          DialogueId = 80020214,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C8527C5C",
          NextDialogue = 80020215,
          SpeakNpcId = 93102,
          Subtitle = "Well, you are my long-term client, so I'll just be upfront with you — I used to be an agent.",
          TalkActionId = {
            [1] = "93102:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C5C"
        },
        [80020215] = {
          ContentES = "Bueno, había quienes nos llamaban espías, pero el nombre da igual. En pocas palabras, nuestro oficio era actuar desde las sombras, sin revelar nunca nuestra verdadera identidad.",
          DialogueId = 80020215,
          GUID = "C8527C86",
          NextDialogue = 80020216,
          SpeakNpcId = 93102,
          Subtitle = "Some called us spies. But the title doesn't matter. Essentially, we were a nameless group, always cloaked in disguise and shadow.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C86"
        },
        [80020216] = {
          ContentES = "Podrías cruzarte con uno en la calle, y pensar que es una persona cualquiera, sin saber que en realidad va de camino a provocar caos o a entregar mensajes secretos.",
          DialogueId = 80020216,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527CB0",
          NextOptions = {
            [1] = 800202161,
            [2] = 800202162
          },
          SpeakNpcId = 93102,
          Subtitle = "You might brush past one on the street, thinking they're just an ordinary passerby, when in reality, they could be on their way to create chaos or deliver secret messages.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CB0"
        },
        [80020217] = {
          ContentES = "Yo también solía romantizarlo, pero las cosas no son así en realidad.",
          DialogueId = 80020217,
          FacialId = {
            [1] = "93102:Sad01"
          },
          GUID = "C8527CDA",
          NextDialogue = 80020219,
          SpeakNpcId = 93102,
          Subtitle = "I once romanticised it as well, but reality is another story.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CDA"
        },
        [80020218] = {
          ContentES = "Sin duda, puede sonar emocionante, pero en realidad está lleno de riesgos y dificultades.",
          DialogueId = 80020218,
          FacialId = {
            [1] = "93102:Sad01"
          },
          GUID = "C8527D04",
          NextDialogue = 80020219,
          SpeakNpcId = 93102,
          Subtitle = "Indeed, it may sound exciting, but it's actually packed with challenges and risks.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D04"
        },
        [80020219] = {
          ContentES = "La mayor parte de los agentes trabajan para la Legión y no pueden liberarse, están obligados a seguir órdenes que podrían incluso exigirles matar a sus propios familiares.",
          DialogueId = 80020219,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527D2E",
          NextDialogue = 80020220,
          SpeakNpcId = 93102,
          Subtitle = "Most agents are stuck with their legion, forced to follow orders — some even involve killing their own family.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D2E"
        },
        [80020220] = {
          ContentES = "Yo no podía soportar todas esas reglas y restricciones, así que encontré una forma de liberarme.",
          DialogueId = 80020220,
          GUID = "C8527D58",
          NextDialogue = 80020221,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't stand all those rules and restrictions, so I figured out a way to break free.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D58"
        },
        [80020221] = {
          ContentES = "Escapar, por supuesto, no fue nada sencillo. Esta bebida no sería suficiente para contarte toda esa historia.",
          DialogueId = 80020221,
          FacialId = {
            [1] = "93102:Syouganai01"
          },
          GUID = "C8527D82",
          NextDialogue = 80020222,
          SpeakNpcId = 93102,
          Subtitle = "The escape was another heart-stopping story. This drink's not enough for me to share it, though.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D82"
        },
        [80020222] = {
          ContentES = "Ya es hora de irme a la cama. Mañana debo preparar el desayuno para la señorita Flora. Hace varios días que ha probado uno de mis postres.",
          DialogueId = 80020222,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527DAC",
          NextDialogue = 80020223,
          SpeakNpcId = 93102,
          Subtitle = "I should go to bed now. I'll need to prepare breakfast for Miss Flora tomorrow. It's been days since she had my dessert.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527DAC"
        },
        [80020223] = {
          ContentES = "Gracias por la bebida, a la próxima me toca invitarte un trozo de pastel.",
          DialogueId = 80020223,
          FacialId = {
            [1] = "93102:Satisfy01"
          },
          GUID = "C8527DD6",
          NextDialogue = 80020224,
          SpeakNpcId = 93102,
          Subtitle = "And as a thank-you for this drink, I'll save a piece of cake for you.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527DD6"
        },
        [80020224] = {
          ContentES = "Pues, buenas noches.",
          DialogueId = 80020224,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527E00",
          SpeakNpcId = 93102,
          Subtitle = "Good night, then.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527E00"
        },
        [80020301] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentES = "Hoy tengo algo de tiempo libre. Puedo acompañarte a tomarnos unos cuantos tragos más.",
          DialogueId = 80020301,
          FacialId = {
            [1] = "93102:Satisfy01"
          },
          GUID = "C8528AA2",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020302,
          SpeakNpcId = 93102,
          Subtitle = "I've finally got some free time today. I'm all yours if you're up for a few more drinks.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528AA2"
        },
        [80020302] = {
          ContentES = "Cuando terminemos, planeo salir a dar una vuelta. Después de aceptar tantos encargos, siempre quedan unas cuantas monedas de plata de sobra.",
          DialogueId = 80020302,
          GUID = "C8528ACC",
          NextOptions = {
            [1] = 800203021,
            [2] = 800203022
          },
          SpeakNpcId = 93102,
          Subtitle = "And after we're done here, I'm going to hit the shops — I've got some extra silver coins to squander from all those commissions I took.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528ACC"
        },
        [80020303] = {
          ContentES = "Está bien, te puedo ayudar a escoger algunas prendas que te queden bien.",
          DialogueId = 80020303,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528AF6",
          NextDialogue = 80020305,
          SpeakNpcId = 93102,
          Subtitle = "Sure, I can help pick out something that suits you.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528AF6"
        },
        [80020304] = {
          ContentES = "Por supuesto. También como y duermo… Lo que la gente normal hace.",
          DialogueId = 80020304,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528B20",
          NextDialogue = 80020305,
          SpeakNpcId = 93102,
          Subtitle = "Like I'd breathe, have meals, and sleep.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B20"
        },
        [80020305] = {
          ContentES = "Para mí, ir de compras es la manera más fácil de relajarme. No hay que pensar mucho, puedo respirar aire fresco y ponerme la ropa que me gusta... No tengo muchas oportunidades así.",
          DialogueId = 80020305,
          GUID = "C8528B4A",
          NextDialogue = 80020306,
          SpeakNpcId = 93102,
          Subtitle = "Shopping is my way to unwind. It's thoughtless, gets me some fresh air, and I can wear what I like — a rare opportunity for me.",
          TalkActionId = {
            [1] = "93102:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B4A"
        },
        [80020306] = {
          ContentES = "En el trabajo, normalmente llevo el uniforme de criada o un abrigo largo con muchos bolsillos, donde guardo todas las herramientas que me puedan hacer falta.",
          DialogueId = 80020306,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528B74",
          NextDialogue = 80020307,
          SpeakNpcId = 93102,
          Subtitle = "At work, I'm typically in my maid's uniform or a bulky trench coat filled with pockets for various mission-essential gadgets.",
          TalkActionId = {
            [1] = "93102:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B74"
        },
        [80020307] = {
          ContentES = "Además, para no llamar mucho la atención durante los encargos, me recojo el cabello. Ya sabes, el color rojo es muy llamativo.",
          DialogueId = 80020307,
          GUID = "C8528B9E",
          NextDialogue = 80020308,
          SpeakNpcId = 93102,
          Subtitle = "And to keep a low profile during a mission, I'd tie up my hair. You know, red hair tends to draw unnecessary attention.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B9E"
        },
        [80020308] = {
          ContentES = "Pero cuando salgo de compras, no tengo que preocuparme por eso. Puedo vestir ropa de colores más claros.",
          DialogueId = 80020308,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8528BC8",
          NextDialogue = 80020309,
          SpeakNpcId = 93102,
          Subtitle = "But when I'm out shopping, I can let loose a bit and wear lighter-coloured clothes.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528BC8"
        },
        [80020309] = {
          ContentES = "La ropa de colores claros combina muy bien con el color de mi cabello, pero cuando salgo con la señorita Flora, me pongo un sombrero.",
          DialogueId = 80020309,
          GUID = "C8528BF2",
          NextDialogue = 80020310,
          SpeakNpcId = 93102,
          Subtitle = "Light colours really complement my hair. Though when I'm out with Miss Flora, I still tend to wear a hat.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528BF2"
        },
        [80020310] = {
          ContentES = "Pero siempre llevo zapatos rojo oscuro para combinar, como un pastel rojo que siempre lleva fresas encima.",
          DialogueId = 80020310,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528C1C",
          NextDialogue = 80020311,
          SpeakNpcId = 93102,
          Subtitle = "I always wear dark red shoes. You know, like a red velvet cake needs to be topped with red berries.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C1C"
        },
        [80020311] = {
          ContentES = "También me pongo un poco de perfume que le compré al Tejestrellas, y algunas joyas de diseño oriental. Me ponen de buenas.",
          DialogueId = 80020311,
          GUID = "C8528C46",
          NextDialogue = 80020312,
          SpeakNpcId = 93102,
          Subtitle = "I'd also dab on some fragrances and wear exotic accessories from the Starweavers — they really lift my spirits.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C46"
        },
        [80020312] = {
          ContentES = "Con tu cabello plateado claro, también te verías más vibrante con ropa de colores brillantes.",
          DialogueId = 80020312,
          GUID = "C8528C70",
          NextOptions = {
            [1] = 800203121,
            [2] = 800203122
          },
          SpeakNpcId = 93102,
          Subtitle = "With your light silver hair, you'd look more vibrant in bright colours too.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C70"
        },
        [80020313] = {
          ContentES = "Eh? Pensé que era fácil de entender.",
          DialogueId = 80020313,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8528C9A",
          NextDialogue = 80020315,
          SpeakNpcId = 93102,
          Subtitle = "Hmm? I thought it was pretty straightforward.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C9A"
        },
        [80020314] = {
          ContentES = "Así es. No pierdes nada en intentarlo.",
          DialogueId = 80020314,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528CC4",
          NextDialogue = 80020315,
          SpeakNpcId = 93102,
          Subtitle = "Right? You should try it too.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CC4"
        },
        [80020315] = {
          ContentES = "En realidad, mi fascinación por esto comenzó durante mi carrera como agente. Teníamos que perfeccionar el arte del disfraz y lucir como otra persona.",
          DialogueId = 80020315,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8528CEE",
          NextDialogue = 80020316,
          SpeakNpcId = 93102,
          Subtitle = "Actually, my fascination with this started during my career as an agent. We had to master the art of disguise, looking completely unlike ourselves.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CEE"
        }
      }
    end
  },
  {
    MinKey = 80020316,
    MaxKey = 80040115,
    Loader = function()
      return {
        [80020316] = {
          ContentES = "Empecé con lo más básico: una niña que vendía flores, una dama con joyas más pesadas que su ropa, una anciana que parecía que el viento la iba a tumbar… y a veces hasta me disfrazaba de “princesa” o “príncipe”.",
          DialogueId = 80020316,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C8528D18",
          NextOptions = {
            [1] = 800203161
          },
          SpeakNpcId = 93102,
          Subtitle = "I started with the basics: playing a street flower girl, a heavy-jewelled lady, an elderly woman teetering in the breeze, and even a \"prince\" or \"princess\" at times.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D18"
        },
        [80020317] = {
          ContentES = "Sí, mientras no hablara, nadie me reconocía. De hecho, algunas jóvenes nobles incluso me regalaban sus pañuelos. Era bastante divertido.",
          DialogueId = 80020317,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528D42",
          NextDialogue = 80020318,
          SpeakNpcId = 93102,
          Subtitle = "Mm-hmm, it was quite convincing as long as I remained silent. There were even a few noble ladies who gave me their handkerchiefs — it was adorable.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D42"
        },
        [80020318] = {
          ContentES = "Con el tiempo, me di cuenta de que cuando me disfrazaba de otra persona, mi estado de ánimo también cambiaba. Incluso un vestido o unos pendientes podían alegrarme el día.",
          DialogueId = 80020318,
          GUID = "C8528D6C",
          NextDialogue = 80020319,
          SpeakNpcId = 93102,
          Subtitle = "Over time, I realised that disguising myself as someone else could also change my mood. Even a dress or a piece of jewellery can be a factor in brightening my day.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D6C"
        },
        [80020319] = {
          ContentES = "Desde entonces, empecé a disfrutar de ir de compras y comprarme ropa nueva.",
          DialogueId = 80020319,
          GUID = "C8528D96",
          NextDialogue = 80020320,
          SpeakNpcId = 93102,
          Subtitle = "So, after that, I fell in love with shopping for new outfits.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D96"
        },
        [80020320] = {
          ContentES = "Oh, ya me terminé mi bebida. Vamos, permíteme armarte un conjunto como agradecimiento por invitármela.",
          DialogueId = 80020320,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8528DC0",
          SpeakNpcId = 93102,
          Subtitle = "Well, I've finished my drink. Let's go hit the shops. I'll help you put together an outfit as a thank-you.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528DC0"
        },
        [80020401] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentES = "Gracias por la invitación... Muchas gracias.",
          DialogueId = 80020401,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529B0A",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020402,
          SpeakNpcId = 93102,
          Subtitle = "Thanks for inviting me... Mm, thank you.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B0A"
        },
        [80020402] = {
          ContentES = "Cuando termine mi bebida, iré a podar las flores.",
          DialogueId = 80020402,
          GUID = "C8529B34",
          NextOptions = {
            [1] = 800204021,
            [2] = 800204022
          },
          SpeakNpcId = 93102,
          Subtitle = "After this drink, I'm off to trim the flowers.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B34"
        },
        [80020403] = {
          ContentES = "En realidad, es todo lo contrario. Quiero tomar las tijeras precisamente porque no estoy de buen humor.",
          DialogueId = 80020403,
          FacialId = {
            [1] = "93102:Disappoint01"
          },
          GUID = "C8529B5E",
          NextDialogue = 80020405,
          SpeakNpcId = 93102,
          Subtitle = "Quite the opposite, actually. I want to pick up the shears precisely because I'm not in the best spirits.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B5E"
        },
        [80020404] = {
          ContentES = "De hecho no lo hago por trabajo, sino para despejar la mente.",
          DialogueId = 80020404,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529B88",
          NextDialogue = 80020405,
          SpeakNpcId = 93102,
          Subtitle = "It's not about work, actually; it's more about stress relief.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B88"
        },
        [80020405] = {
          ContentES = "Cuando me siento muy estresada, me gusta tomar las tijeras y podar las flores que están a punto de marchitarse, siento como si también pudiera cortar mi propio desánimo.",
          DialogueId = 80020405,
          GUID = "C8529BB2",
          NextDialogue = 80020406,
          SpeakNpcId = 93102,
          Subtitle = "When I feel the pressure mounting, I find snipping away at dying flowers quite cathartic — as if I'm trimming away my own gloom.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529BB2"
        },
        [80020406] = {
          ContentES = "¿Qué tiene? ¿Te parece raro? No es más que una forma de desahogarme. Después de todo, los encargos que acepto normalmente requieren mucho más que solo conversar.",
          DialogueId = 80020406,
          GUID = "C8529BDC",
          NextDialogue = 80020407,
          SpeakNpcId = 93102,
          Subtitle = "I hope you wouldn't find that strange. It's just my way of blowing off steam. After all, the assignments I take normally require much more than making conversations.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529BDC"
        },
        [80020407] = {
          ContentES = "Cuando trabajaba como agente, algunos de mis colegas tenían... digamos, formas más turbias de relajarse.",
          DialogueId = 80020407,
          FacialId = {
            [1] = "93102:Unhappy02"
          },
          GUID = "C8529C06",
          NextDialogue = 80020408,
          SpeakNpcId = 93102,
          Subtitle = "Back when I was an agent, some of my colleagues had... let's say, darker ways of unwinding.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C06"
        },
        [80020408] = {
          ContentES = "Completar un asesinato que dura un segundo puede requerir un mes de planificación, semanas de preparativos y un día entero de espera angustiosa. Y si fallas, puede significar pasar el resto de la vida tras las rejas.",
          DialogueId = 80020408,
          GUID = "C8529C30",
          NextDialogue = 80020409,
          SpeakNpcId = 93102,
          Subtitle = "An assassination that lasts only seconds might require a month of planning, a week of prep, and a whole day of agonising wait — and failure could mean a lifetime behind bars.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C30"
        },
        [80020409] = {
          ContentES = "Teniendo en cuenta ese tipo de estrés, podar un par de flores ya es mostrar bastante autocontrol, ¿no crees?",
          DialogueId = 80020409,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C8529C5A",
          NextOptions = {
            [1] = 800204091,
            [2] = 800204092
          },
          SpeakNpcId = 93102,
          Subtitle = "Considering that kind of pressure, randomly cutting several flowers seems quite mild, doesn't it?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C5A"
        },
        [80020410] = {
          ContentES = "No es tanto que esté preocupada.",
          DialogueId = 80020410,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529C84",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "Well, it's not really a bother.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C84"
        },
        [80020411] = {
          ContentES = "Parece que no estás captando el punto de esta conversación, ¿no?",
          DialogueId = 80020411,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529CAE",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "It seems you're missing the point of this conversation, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CAE"
        },
        [80020412] = {
          ContentES = "Simplemente siento nostalgia por alguien... que fue muy importante para mí.",
          DialogueId = 80020412,
          GUID = "C8529CD8",
          NextDialogue = 80020413,
          SpeakNpcId = 93102,
          Subtitle = "I was just thinking of... um, someone important.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CD8"
        },
        [80020413] = {
          ContentES = "Ella, al igual que yo, también era una agente. Pero ella pensaba que yo no estaba hecha para esto. Así que me empeñé en demostrarle que no solo podía hacerlo bien, sino que podía hacerlo mejor que nadie.",
          DialogueId = 80020413,
          GUID = "C8529D02",
          NextDialogue = 80020414,
          SpeakNpcId = 93102,
          Subtitle = "She was a fellow agent, but she always thought I wasn't cut out for the job. So I made so much effort trying to prove to her that I was not only competent but exceptional.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D02"
        },
        [80020414] = {
          ContentES = "Resultó que ella tenía razón.",
          DialogueId = 80020414,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529D2C",
          NextDialogue = 80020415,
          SpeakNpcId = 93102,
          Subtitle = "In the end, it turned out she was right.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D2C"
        },
        [80020415] = {
          ContentES = "Yo no podía poner las misiones por encima de todo, como ella lo hacía.",
          DialogueId = 80020415,
          GUID = "C8529D56",
          NextDialogue = 80020416,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't put missions above all else like she could.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D56"
        },
        [80020416] = {
          ContentES = "Aunque, en parte, me siento contenta de no haber seguido sus pasos.",
          DialogueId = 80020416,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8529D80",
          NextDialogue = 80020417,
          SpeakNpcId = 93102,
          Subtitle = "Yet, there's a part of me that's relieved that I didn't end up walking her path.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D80"
        },
        [80020417] = {
          ContentES = "Cuando me fui de la Legión, perdí el contacto con ella. Ahora que mi vida aquí es más tranquila, me da curiosidad saber cómo le va.",
          DialogueId = 80020417,
          GUID = "C8529DAA",
          NextOptions = {
            [1] = 800204171
          },
          SpeakNpcId = 93102,
          Subtitle = "We lost touch when I left the Legion. Now that I'm settling in here, I find myself... wondering how she's doing.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DAA"
        },
        [80020418] = {
          ContentES = "Es que...",
          DialogueId = 80020418,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8529DD4",
          NextDialogue = 80020419,
          SpeakNpcId = 93102,
          Subtitle = "Huh? Well...",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DD4"
        },
        [80020419] = {
          ContentES = "Tienes razón, en vez de quedarme aquí podando flores, será mejor que vaya a verla.",
          DialogueId = 80020419,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529DFE",
          SpeakNpcId = 93102,
          Subtitle = "You're right. Instead of trimming flowers here, perhaps I should just go see her in person.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DFE"
        },
        [80020501] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentES = "Apenas regreso y ya vienes a invitarme a tomar algo. Dime, ¿me has estado espiando y practicando mis técnicas de agente?",
          DialogueId = 80020501,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C852AB72",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextOptions = {
            [1] = 800205011,
            [2] = 800205012
          },
          SpeakNpcId = 93102,
          Subtitle = "You approached me as soon as I returned, inviting me for a drink. Please be honest with me — have you picked up some of my old agent tricks and been keeping tabs on me?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AB72"
        },
        [80020503] = {
          ContentES = "Está bien, no te molestaré más. En el fondo, lo que quieres saber es si llegué a ver a esa persona importante, ¿verdad?",
          DialogueId = 80020503,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ABC6",
          NextDialogue = 80020504,
          SpeakNpcId = 93102,
          Subtitle = "I was only teasing you. You came over because you're curious if I've met that lady who's important to me, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABC6"
        },
        [80020504] = {
          ContentES = "A decir verdad, no. Por ciertos motivos, la trasladaron fuera de la capital, así que solo me he enterado de su paradero por otras personas.",
          DialogueId = 80020504,
          GUID = "C852ABF0",
          NextDialogue = 80020505,
          SpeakNpcId = 93102,
          Subtitle = "Truth be told, no. She was reassigned away from the capital for certain reasons, so I've only caught snippets about her from others.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABF0"
        },
        [80020505] = {
          ContentES = "Ahora está en un pueblito al sur, donde no hace frío ni nieva como aquí. Allá puede disfrutar a menudo de la luz del sol y de la música.",
          DialogueId = 80020505,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AC1A",
          NextDialogue = 80020506,
          SpeakNpcId = 93102,
          Subtitle = "She's in a small town in the south — nothing like the icy grip here, but a place where she can enjoy bright sunlight and some music often.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC1A"
        },
        [80020506] = {
          ContentES = "Para ser sincera, me sentí aliviada. No estaba segura de cómo dirigirme a ella... Saber que está bien me da algo de tranquilidad.",
          DialogueId = 80020506,
          GUID = "C852AC44",
          NextDialogue = 80020507,
          SpeakNpcId = 93102,
          Subtitle = "To be honest, I was relieved. Because I wasn't sure how I would face her... But knowing she's doing well gives me some peace of mind.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC44"
        },
        [80020507] = {
          ContentES = "De esta manera, se rompió el último vínculo que me unía a la Legión… y a mi identidad como agente.",
          DialogueId = 80020507,
          GUID = "C852AC6E",
          NextOptions = {
            [1] = 800205071,
            [2] = 800205072
          },
          SpeakNpcId = 93102,
          Subtitle = "This means the last ties between me, the Legion, and my past life as an agent have finally been severed.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC6E"
        },
        [80020508] = {
          ContentES = "Sí… al fin logré dejarlo atrás.",
          DialogueId = 80020508,
          GUID = "C852AC98",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "Yes, finally.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC98"
        },
        [80020509] = {
          ContentES = "Antes sí, pero ahora ya no.",
          DialogueId = 80020509,
          GUID = "C852ACC2",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "The old me would, but no, not anymore.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACC2"
        },
        [80020510] = {
          ContentES = "La verdad es que esta persona es muy cercana a mí. Por ella quise entrar en la Legión... y también es por ella que ahora deseo irme.",
          DialogueId = 80020510,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C852ACEC",
          NextDialogue = 80020511,
          SpeakNpcId = 93102,
          Subtitle = "She's actually a close family member of mine. She was the reason that I joined the Legion, and the reason I decided to leave.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACEC"
        },
        [80020511] = {
          ContentES = "Ella no quería que me metiera en un oficio tan arriesgado, pero yo me empeñaba en mostrarle que podía manejarlo y que podía compartir parte de sus preocupaciones.",
          DialogueId = 80020511,
          GUID = "C852AD16",
          NextDialogue = 80020512,
          SpeakNpcId = 93102,
          Subtitle = "She never wanted me to stay in such a dangerous profession, but I was desperate to show her that I could handle it — maybe even share some of her burdens.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD16"
        },
        [80020512] = {
          ContentES = "Irónicamente, mientras yo debía proteger a la señorita Flora, ella tenía la misión de acabar con ella.",
          DialogueId = 80020512,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AD40",
          NextDialogue = 800205121,
          SpeakNpcId = 93102,
          Subtitle = "It was the irony of fate that she and I received conflicting missions — hers to eliminate Miss Flora, mine to protect her.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD40"
        },
        [80020513] = {
          ContentES = "Así que huí con la señorita Flora antes de que su plan de asesinato comenzara. No tenía ni el tiempo ni el deseo de volver a pensar en mis días en la Legión ni en ella.",
          DialogueId = 80020513,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AD6A",
          NextDialogue = 80020514,
          SpeakNpcId = 93102,
          Subtitle = "So I took Miss Flora and fled before her assassination attempt could commence. At that time, I didn't have the leisure to dwell on my days in the Legion or anything related to her.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6A"
        },
        [80020514] = {
          ContentES = "Es solo ahora, que todo está un poco más tranquilo, y que usted está aquí para escuchar mis historias, que todo esto me ha pesado hasta el punto de hacerme perder el control hace poco.",
          DialogueId = 80020514,
          GUID = "C852AD6B",
          NextOptions = {
            [1] = 800205141,
            [2] = 800205142
          },
          SpeakNpcId = 93102,
          Subtitle = "It's only because things have settled down recently, and you've been there for me to unload these old stories, that this whole thing had become a thorn in my heart, which led to my recent discomposure.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6B"
        },
        [80020515] = {
          ContentES = "Lo único que sé con certeza es que tarde o temprano tendré que afrontar esta despedida definitiva con ella. Antes, trataba de escapar de esa realidad.",
          DialogueId = 80020515,
          GUID = "C852ADBE",
          NextDialogue = 80020516,
          SpeakNpcId = 93102,
          Subtitle = "What I knew for sure was that eventually, I had to confront a complete farewell with her, which was something I had been trying to run away from.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADBE"
        },
        [80020516] = {
          ContentES = "Ahora que finalmente ha sucedido, no se siente tan mal. Incluso me alivia que ya no me atormente.",
          DialogueId = 80020516,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ADE8",
          NextDialogue = 80020517,
          SpeakNpcId = 93102,
          Subtitle = "Now that it's finally happened, it doesn't feel so bad. I'm even relieved that it'll no longer haunt me.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADE8"
        },
        [80020517] = {
          ContentES = "Tengo tantas cosas que quiero hacer ahora: podar flores, hornear un pastel, comprar ropa nueva, quizás hasta bailar un poco.",
          DialogueId = 80020517,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AE12",
          NextDialogue = 80020518,
          SpeakNpcId = 93102,
          Subtitle = "I've got so much I want to do now — trim flowers, bake a cake, shop for new outfits, maybe even dance a little.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE12"
        },
        [80020518] = {
          ContentES = "Sin embargo, lo que más anhelo en este momento es darte las gracias. Gracias a ti he logrado, por fin, liberarme de lo que tanto me afligía.",
          DialogueId = 80020518,
          GUID = "C852AE3C",
          NextOptions = {
            [1] = 800205181,
            [2] = 800205182
          },
          SpeakNpcId = 93102,
          Subtitle = "But what I want to do most at the moment is thank you for helping me truly move on.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE3C"
        },
        [80020519] = {
          ContentES = "Pero debo advertirte que, ahora que conoces mi pasado, el día en que la Legión intente capturarme a mí y a la señorita Flora... no podrás mantenerte al margen.",
          DialogueId = 80020519,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AE66",
          NextDialogue = 80020520,
          SpeakNpcId = 93102,
          Subtitle = "But I must also remind you: now that you know my past, it means that one day when the Legion comes after me and Miss Flora, you won't be able to stay out of it.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE66"
        },
        [80020520] = {
          ContentES = "¿Qué pasa? ¿Te asusté? ¿Crees que te he dado un caramelo envenenado, ¿verdad?",
          DialogueId = 80020520,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C852AE90",
          NextDialogue = 80020521,
          SpeakNpcId = 93102,
          Subtitle = "I hope you're not too scared. Do you feel like I've handed you a sugar-coated poison?",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE90"
        },
        [80020521] = {
          ContentES = "Descuida. Yo, Hilda, una criada fiel, me haré cargo de todo y estaré a tu lado para protegerte siempre.",
          DialogueId = 80020521,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AEBA",
          SpeakNpcId = 93102,
          Subtitle = "Please rest assured that, I, Hilda, the all-capable maid, will always ensure your safety.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AEBA"
        },
        [80020522] = {
          ContentES = "Gracias... ¿Suena raro que lo diga? Hablo con total sinceridad.",
          DialogueId = 80020522,
          FacialId = {
            [1] = "93102:Happy02"
          },
          GUID = "C852AE65",
          NextDialogue = 80020519,
          SpeakNpcId = 93102,
          Subtitle = "Thank you — is it so strange to hear that from me? I mean it sincerely.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE65"
        },
        [80030100] = {
          ContentES = "Estas vacaciones son valiosas, y pasarlas contigo es tan agradable como dormir.",
          DialogueId = 80030100,
          GUID = "C878DD68",
          Subtitle = "This holiday is precious, and spending it with you is just as enjoyable as sleeping.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C878DD68"
        },
        [80030101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "No hay nada como una buena bebida, y un buen descanso. ¡Qué placer no tener que trabajar!",
          DialogueId = 80030101,
          GUID = "C858D272",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030102,
          SpeakNpcId = 94202,
          Subtitle = "Nothing beats having a refreshing drink after a good rest. It's so wonderful to have a break from work!",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D272"
        },
        [80030102] = {
          ContentES = "Ah, por cierto… antes de venir, el asistente me dio un paquete que todavía no he abierto. Quiero echarle un vistazo…",
          DialogueId = 80030102,
          GUID = "C858D29C",
          NextDialogue = 80030103,
          SpeakNpcId = 94202,
          Subtitle = "Speaking of which, I got a package before I came here. Let me take a look.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D29C"
        },
        [80030103] = {
          ContentES = "Seguro que es el pijama y el incienso para dormir que encargué… Perfecto, volveré a casa y tomaré otro descanso.",
          DialogueId = 80030103,
          GUID = "C858D2C6",
          NextDialogue = 80030104,
          SpeakNpcId = 94202,
          Subtitle = "This must be the pyjamas and incense my subordinate bought me as a sleep aid. Perfect, I'll go back home and take another rest.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2C6"
        },
        [80030104] = {
          ContentES = "Eh? ¿«Propuesta para optimizar las plantas ornamentales del campamento de la 13.ª Legión»? ¿«Solicitud de compra de instalaciones recreativas para mejorar la moral de los soldados»?",
          DialogueId = 80030104,
          GUID = "C858D2F0",
          NextDialogue = 80030105,
          SpeakNpcId = 94202,
          Subtitle = "Huh? \"Proposal on the Optimisation of Ornamental Plants of the 13th Legion\"? \"Application for Purchasing Recreational Facilities to Enhance Soldiers' Morale\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2F0"
        },
        [80030105] = {
          ContentES = "Ay, trabajo y nada más que trabajo. Lo dejaré para más tarde. Nada ni nadie arruinará mis preciadas vacaciones. A menos que venga la Comandante, pero dudo que aparezca por aquí.",
          DialogueId = 80030105,
          GUID = "C858D31A",
          NextOptions = {
            [1] = 800301051,
            [2] = 800301052
          },
          SpeakNpcId = 94202,
          Subtitle = "Urgh, it's always about work. Let's talk about this later. I won't let my holiday be spoiled by anything or anyone, except the Chief. But I doubt she'll show up here.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D31A"
        },
        [80030106] = {
          ContentES = "No es nada fácil idear unas reglas tan prácticas.",
          DialogueId = 80030106,
          GUID = "C858D344",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "It's not easy to come up with such practical principles as these.",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D344"
        },
        [80030107] = {
          ContentES = "¡No digas tonterías! ¿Cómo puedes llamar a esto holgazanear?",
          DialogueId = 80030107,
          FacialId = {
            [1] = "94202:Blink"
          },
          GUID = "C858D36E",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "Whoa, how could you call this \"slacking off\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D36E"
        },
        [80030108] = {
          ContentES = "Esto es lo que yo llamo: el “Modo Howard de rendimiento Energético”. Creado por mí, el mismísimo Randy Howard.",
          DialogueId = 80030108,
          GUID = "C858D398",
          NextDialogue = 80030109,
          SpeakNpcId = 94202,
          Subtitle = "This is the \"Howard High-Efficiency Energy-Saving Mode\", created by yours truly, Randy Howard.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D398"
        },
        [80030109] = {
          ContentES = "Cuando descanses, recuerda despejar tu mente de todo lo que tenga que ver con el trabajo. Así no regresarás con cara de zombie a la oficina.",
          DialogueId = 80030109,
          GUID = "C858D3C2",
          NextDialogue = 80030110,
          SpeakNpcId = 94202,
          Subtitle = "When you take a break, clear your mind of all work so that you can start working again in a good mood. That way, you won't dread getting back to work.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3C2"
        },
        [80030110] = {
          ContentES = "Después de varios años de optimizar este modo, he logrado que funcione a la perfección.",
          DialogueId = 80030110,
          GUID = "C858D3EC",
          NextDialogue = 80030111,
          SpeakNpcId = 94202,
          Subtitle = "After years of practising and optimising this method, I've got it working perfectly.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3EC"
        },
        [80030111] = {
          ContentES = "Me permite idear en segundos la solución más eficiente para cualquier situación.",
          DialogueId = 80030111,
          GUID = "C858D416",
          NextDialogue = 80030112,
          SpeakNpcId = 94202,
          Subtitle = "This has helped me to figure out the most energy-saving solution to different problems in seconds.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D416"
        },
        [80030112] = {
          ContentES = "Por ejemplo, ahora mismo, esta reunión tiene un propósito oculto.",
          DialogueId = 80030112,
          GUID = "C858D417",
          NextDialogue = 80030113,
          SpeakNpcId = 94202,
          Subtitle = "Such as this conversation with an ulterior motive.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D417"
        },
        [80030113] = {
          ContentES = "¿Qué dices? No te entiendo.",
          DialogueId = 80030113,
          GUID = "80030113.0",
          NextDialogue = 80030114,
          SpeakNpcId = 790008,
          Subtitle = "Huh? I'm not following."
        },
        [80030114] = {
          ContentES = "Ya es demasiado tarde para fingir que no entiendes.",
          DialogueId = 80030114,
          GUID = "C858D418",
          NextDialogue = 80030115,
          SpeakNpcId = 94202,
          Subtitle = "A bit too late to play dumb, don't you think?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D418"
        },
        [80030115] = {
          ContentES = "Dime, ¿cómo está Berenica ahora?",
          DialogueId = 80030115,
          GUID = "80030115.0",
          NextDialogue = 80030116,
          SpeakNpcId = 790008,
          Subtitle = "...Tell me, how's Berenica doing now?!"
        },
        [80030116] = {
          ContentES = "Ah, con que así se llama el N.º 0, Berenica.",
          DialogueId = 80030116,
          GUID = "C858D419",
          NextDialogue = 80030117,
          SpeakNpcId = 94202,
          Subtitle = "Hah, so that's No. 0's name — Berenica.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D419"
        },
        [80030117] = {
          ContentES = "Ya es un poco tarde para fingir que no sabías.",
          DialogueId = 80030117,
          GUID = "80030117.0",
          NextDialogue = 80030118,
          SpeakNpcId = 790008,
          Subtitle = "A bit late to play dumb too, I'd say."
        },
        [80030118] = {
          ContentES = "Bueno, las personas inteligentes suelen empezar una conversación fingiendo que no saben nada.",
          DialogueId = 80030118,
          GUID = "C858D41A",
          NextDialogue = 80030119,
          SpeakNpcId = 94202,
          Subtitle = "Well, playing dumb is how smart people start a conversation.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41A"
        },
        [80030119] = {
          ContentES = "Pero, tu pregunta es algo inútil. Aunque te respondiera, no tendrías manera de comprobar su veracidad.",
          DialogueId = 80030119,
          GUID = "C858D41B",
          NextDialogue = 80030120,
          SpeakNpcId = 94202,
          Subtitle = "But honestly, your question's moot. For starters, even if I did tell you something, there's no way you could verify it.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41B"
        },
        [80030120] = {
          ContentES = "Además, según el Modo Howard de rendimiento energético, hay que mantener el mundo laboral y lo personal separados.",
          DialogueId = 80030120,
          GUID = "C858D41C",
          NextDialogue = 80030121,
          SpeakNpcId = 94202,
          Subtitle = "Secondly, in the principle of the \"Howard High-Efficiency Energy-Saving Mode\", I keep work and life separate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41C"
        },
        [80030121] = {
          ContentES = "La vida puede integrarse al trabajo, pero el trabajo nunca debe integrarse a la vida. En este momento, estoy técnicamente de vacaciones… Así es como ahorro energía.",
          DialogueId = 80030121,
          GUID = "C858D41D",
          NextDialogue = 80030122,
          SpeakNpcId = 94202,
          Subtitle = "Life might blend into work, but work must never intrude on my life. Right now, I'm technically on vacation, and that's the most \"energy-efficient\" way I operate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41D"
        },
        [80030122] = {
          ContentES = "Así que, tanto ahora como en el futuro, no haremos progreso alguno con el tema del N.º 0. Pero si es sobre la vida, hay mucho de qué hablar.",
          DialogueId = 80030122,
          GUID = "C858D41E",
          NextDialogue = 80030123,
          SpeakNpcId = 94202,
          Subtitle = "So, this conversation and any future talks about No. 0 aren't gonna get anywhere; but if you want to chat about life and other fun stuff, I'm all ears.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41E"
        },
        [80030123] = {
          ContentES = "Entonces, no hay nada de lo que podamos hablar. Puedes marcharte.",
          DialogueId = 80030123,
          GUID = "C858D41F",
          NextDialogue = 80030124,
          SpeakNpcId = 790008,
          Subtitle = "Then it seems we're done here. You can leave.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41F"
        },
        [80030124] = {
          ContentES = "Aunque no puedo decirte dónde está, puedo asegurarte que está a salvo.",
          DialogueId = 80030124,
          GUID = "C858D421",
          NextDialogue = 80030125,
          SpeakNpcId = 94202,
          Subtitle = "While I can't disclose her whereabouts, I can assure you, she's safe.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D421"
        },
        [80030125] = {
          ContentES = "Como dijiste, no tengo forma de comprobar lo que dices.",
          DialogueId = 80030125,
          GUID = "C858D422",
          NextDialogue = 80030126,
          SpeakNpcId = 790008,
          Subtitle = "There's no way I could verify that.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D422"
        },
        [80030126] = {
          ContentES = "¡Jajaja! Aprendes rápido.",
          DialogueId = 80030126,
          GUID = "C858D423",
          NextDialogue = 80030127,
          SpeakNpcId = 94202,
          Subtitle = "Hahaha, smart people are all quick learners.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D423"
        },
        [80030127] = {
          ContentES = "Ay… Es triste ver cómo las buenas intenciones no se valoran… Estoy tan devastado, que quizá mañana no pueda descansar lo suficiente.",
          DialogueId = 80030127,
          GUID = "C858D4BE",
          NextDialogue = 80030128,
          SpeakNpcId = 94202,
          Subtitle = "*sigh* It's sad to see good intentions go unappreciated — so much so that I might not be able to rest properly tomorrow...",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4BE"
        },
        [80030128] = {
          ContentES = "¡Un momento! ¿Y si extiendo mis vacaciones por motivos de salud? Algo así como: “Necesito más días libres porque, pobrecito yo, mi enfermedad no me permitió descansar de verdad”. ¡Suena totalmente lógico!",
          DialogueId = 80030128,
          GUID = "C858D4E8",
          NextDialogue = 80030129,
          SpeakNpcId = 94202,
          Subtitle = "Oh, wait! Maybe I should try to extend my holiday by taking sick leave. Like, I need a prolonged holiday 'cause my illness had prevented me from getting proper rest. That makes perfect sense, doesn't it?!",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4E8"
        },
        [80030129] = {
          ContentES = "Y la razón que usaré será... ¡Me duele todo el cuerpo, sobre todo el corazón!",
          DialogueId = 80030129,
          GUID = "C858D512",
          NextDialogue = 80030130,
          SpeakNpcId = 94202,
          Subtitle = "And the reason I'll use will be... I feel achy all over, especially in my heart.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D512"
        },
        [80030130] = {
          ContentES = "Podría poner que la causa fue “un accidente durante la jornada laboral, resuelto mediante conciliación privada”. Hasta podría recibir una compensación por ser durante el horario laboral… Hoy va a hacer un día productivo.",
          DialogueId = 80030130,
          GUID = "C858D53C",
          NextDialogue = 80030131,
          SpeakNpcId = 94202,
          Subtitle = "Because of a conflict during a public opinion survey... but it has been resolved through private negotiations. Maybe I'll even get compensation out of it. Today has been very fruitful.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D53C"
        },
        [80030131] = {
          ContentES = "¡En lo que tardaste en tomarte una taza de té, yo ya gané muchos días libres! ¡Hacemos un gran equipo!",
          DialogueId = 80030131,
          GUID = "C858D566",
          NextDialogue = 80030132,
          SpeakNpcId = 94202,
          Subtitle = "You just extended my holiday in mere seconds. My friend, you're the best!",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D566"
        },
        [80030132] = {
          ContentES = "Espero con ansias la próxima “razón para ausentarme”… digo, para vernos de nuevo.",
          DialogueId = 80030132,
          GUID = "C858D590",
          SpeakNpcId = 94202,
          Subtitle = "I'm looking forward to my next excuse for... Ahem... I mean, our next meeting.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D590"
        },
        [80030201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "Parece que al fin te dignaste a hablar conmigo sobre temas más personales.",
          DialogueId = 80030201,
          GUID = "C858E2DA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030202,
          SpeakNpcId = 94202,
          Subtitle = "Looks like you're finally up for some casual chats, huh?",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E2DA"
        },
        [80030202] = {
          ContentES = "Sigo en plena misión, así que no podía reunirme contigo durante el horario laboral. Tuve que pedir un día libre especialmente para venir a tomar algo contigo.",
          DialogueId = 80030202,
          GUID = "C858E304",
          NextDialogue = 80030203,
          SpeakNpcId = 94202,
          Subtitle = "I'm still on a mission, so I couldn't meet up with you during working hours. I requested leave especially to grab a drink with you.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E304"
        },
        [80030203] = {
          ContentES = "Como excusa, siempre puedo decir que una dama de la Ciudad Interior me invitó a un baile.",
          DialogueId = 80030203,
          GUID = "C858E32E",
          NextDialogue = 80030204,
          SpeakNpcId = 94202,
          Subtitle = "And my reason for this leave... I told them I was invited to a dance by a young lady of nobility.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E32E"
        },
        [80030204] = {
          ContentES = "No te sorprendas. Que un joven oficial y una dama noble tengan algún que otro romance no es algo nuevo. En la Legión, todos se hacen de la vista gorda. Después de todo, relacionarse con la nobleza puede aumentar su influencia.",
          DialogueId = 80030204,
          GUID = "C858E358",
          NextDialogue = 80030205,
          SpeakNpcId = 94202,
          Subtitle = "Oh don't be surprised. It's quite common for young officers and noble ladies to have romantic affairs. The Legion turns a blind eye to them. After all, having relations with \"the nobility\" can bolster the Legion's influence.",
          VoiceName = "voice/$Locale$/inv/Landi/0/C858E358"
        },
        [80030205] = {
          ContentES = "Y que un caballero, de buen porte como yo, prolongue sus vacaciones por motivos así, es de lo más normal.",
          DialogueId = 80030205,
          GUID = "C858E382",
          NextOptions = {
            [1] = 800302051,
            [2] = 800302052
          },
          SpeakNpcId = 94202,
          Subtitle = "As a gentleman, I had to take longer leave for this reason. I think it makes perfect sense.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E382"
        },
        [80030206] = {
          ContentES = "¡Ah! Tus palabras van directo al corazón… Tendré que alargar mis vacaciones para recuperarme de semejante golpe.",
          DialogueId = 80030206,
          GUID = "C858E3AC",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Your words are like a dagger in my heart. I might have to extend my leave to recover from that burn.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3AC"
        },
        [80030207] = {
          ContentES = "Mmm, lo tomaré como un cumplido.",
          DialogueId = 80030207,
          GUID = "C858E3D6",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Thank you, I'll take that as a compliment.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3D6"
        },
        [80030208] = {
          ContentES = "Aunque me he dado cuenta que “caballero” se usa en realidad más para ironizar que para halagar a alguien.",
          DialogueId = 80030208,
          GUID = "C858E400",
          NextDialogue = 80030209,
          SpeakNpcId = 94202,
          Subtitle = "I'm aware by the way, that \"gentleman\" is often used sarcastically, not as praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E400"
        },
        [80030209] = {
          ContentES = "Y cuando era pequeño, mis hermanas siempre me decían que convertirse en un caballero era a lo que todo hombre debía aspirar, propósito de vida.",
          DialogueId = 80030209,
          GUID = "C858E42A",
          NextOptions = {
            [1] = 800302091,
            [2] = 800302092
          },
          SpeakNpcId = 94202,
          Subtitle = "When I was little, my sisters told me that being a gentleman is the ultimate goal for a man.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E42A"
        },
        [80030210] = {
          ContentES = "No del todo. Quizá llegaste a esa conclusión por la buena impresión que tienes de mí.",
          DialogueId = 80030210,
          GUID = "C858E454",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you're making that assumption based on your high opinion of me, but unfortunately, they're not lovely ladies, not at all.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E454"
        },
        [80030211] = {
          ContentES = "Todos fuimos jóvenes alguna vez: ingenuos, tiernos, adorables.",
          DialogueId = 80030211,
          GUID = "C858E47E",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "I was just like any ordinary kid. Dumb and naive.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E47E"
        },
        [80030212] = {
          ContentES = "TEs un viejo recuerdo de la infancia que aún duele un poco, pero ya que somos colegas de vacaciones, no está de más que te las cuente.",
          DialogueId = 80030212,
          GUID = "C858E4A8",
          NextDialogue = 80030213,
          SpeakNpcId = 94202,
          Subtitle = "Look, I really don't feel like talking about my sisters. They tormented me during my childhood. But since you're my holiday buddy, I will tell you this.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4A8"
        },
        [80030213] = {
          ContentES = "¡Yo crecí bajo el “cariñito” de mis hermanas! Y para sobrevivir de sus garras… ejem, quiero decir, de su “cariñito”, tuve que desarrollar varios tipos de habilidades…",
          DialogueId = 80030213,
          GUID = "C858E4D2",
          NextOptions = {
            [1] = 800302131,
            [2] = 800302132
          },
          SpeakNpcId = 94202,
          Subtitle = "I grew up with their \"love\". To survive their clutches... ahem, I mean love, I had to develop many skills.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4D2"
        },
        [80030214] = {
          ContentES = "Pero no era ese tipo de cariño.",
          DialogueId = 80030214,
          GUID = "C858E4FC",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, love. Tough love.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4FC"
        },
        [80030215] = {
          ContentES = "Así es la vida para algunos.",
          DialogueId = 80030215,
          GUID = "C858E526",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, it was rather bitter.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E526"
        },
        [80030216] = {
          ContentES = "En aquel entonces, me decían que un caballero debía besar el vestido de una dama al encontrarse, y que uno debía seguir los principios y la etiqueta para ocultar sus verdaderos pensamientos y sentimientos.",
          DialogueId = 80030216,
          GUID = "C858E550",
          NextDialogue = 80030217,
          SpeakNpcId = 94202,
          Subtitle = "Back then, they told me that a gentleman should kiss a lady's dress when they meet, and that one should adhere to principles and etiquette to conceal their true thoughts and feelings.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E550"
        },
        [80030217] = {
          ContentES = "Cuando tenía cinco o seis años, me comportaba como un caballero con cada dama que conocía, aunque no quería hacerlo.",
          DialogueId = 80030217,
          GUID = "C858E57A",
          NextDialogue = 80030218,
          SpeakNpcId = 94202,
          Subtitle = "When I was five or six years old, I acted like a gentleman to every woman I met, even though I didn't want to.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E57A"
        },
        [80030218] = {
          ContentES = "Puedes imaginarte cómo me observaban y se reían mis hermanas. Más tarde me dijeron que los caballeros en realidad no tenían que hacer eso.",
          DialogueId = 80030218,
          GUID = "C858E5A4",
          NextDialogue = 80030219,
          SpeakNpcId = 94202,
          Subtitle = "You can imagine how my sisters watched me and laughed. Later on, they told me that gentlemen didn't really have to do that.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5A4"
        },
        [80030219] = {
          ContentES = "En realidad, deberían besar el dorso de la mano de una dama. No su vestido.",
          DialogueId = 80030219,
          GUID = "C858E5CE",
          NextDialogue = 80030220,
          SpeakNpcId = 94202,
          Subtitle = "They should actually kiss the back of a lady's hand. Not her dress.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5CE"
        },
        [80030220] = {
          ContentES = "En fin, cuanto más lo recuerdo, más rabia me da. Mejor brindemos por mi triste infancia.",
          DialogueId = 80030220,
          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          Subtitle = "Anyway, let's not talk about this. Here's a toast to my miserable childhood.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5F8"
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "Aquí estoy. Ves que no iba a dejarte esperando.",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202,
          Subtitle = "I'm here. I couldn't stand you up now, could I?",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903AA"
        },
        [80030402] = {
          ContentES = "Aquí traigo la “Vasija de control de temperatura de aleación militar” mejorada. La probé y funciona de maravilla... *bostezo*...",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          Subtitle = "Check this out. The Military Alloy Temperature Control Vessel - Ultimate Type. I've tried it, and it works like a charm... *yawn*",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903D4"
        },
        [80030403] = {
          ContentES = "Pero ahora mismo estoy agotado, necesito encontrar un lugar para echarme una siesta. Se me están acabando los días de vacaciones, y mañana no puedo presentarme ante la comandante Sibylle con ojeras.",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          Subtitle = "I'm feeling a bit drowsy at the moment, I need to find a place to get some shut-eye. I've nearly run out of annual leave, and I can't report to Chief Sibylle tomorrow with dark rings around my eyes.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903FE"
        },
        [80030404] = {
          ContentES = "Tienes buena intuición, sí… hay algunas cosas que me preocupan.",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202,
          Subtitle = "You're very perceptive. Yes, there's something on my mind.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590428"
        },
        [80030405] = {
          ContentES = "Ya que lo notaste, no voy a ocultarlo. La verdad tuve una pesadilla.",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "I won't keep it from you. Basically, I had a nightmare.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590452"
        },
        [80030406] = {
          ContentES = "¡Para nada! Alguien como yo, que odia lo complicado, suele rechazar la mayoría de las invitaciones.",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          Subtitle = "Of course not. You know how lazy I am. I turn most invitations down.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C859047C"
        },
        [80030407] = {
          ContentES = "A decir verdad, es porque anoche tuve una pesadilla y eso me dejó de mal humor.",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "To be honest, I had a nightmare last night, so I'm feeling a bit off today.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904A6"
        },
        [80030408] = {
          ContentES = "Ay, como en tantas otras pesadillas, se trataba de mi complicado padre…",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202,
          Subtitle = "Well, like many of my nightmares, this one was about my dad.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904D0"
        },
        [80030409] = {
          ContentES = "Sí, él también fue militar del Imperio en su momento. Pero ahora… lleva varios años postrado en la cama.",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          Subtitle = "He used to be a soldier in the Empire, but... he's been bedridden for years now.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904FA"
        },
        [80030410] = {
          ContentES = "Cuando era engañado por mis hermanas y soñaba con ser un caballero, mi padre ya era un suboficial en la Legión. En aquel entonces, él pasaba mucho tiempo en el frente y poco en casa… más o menos como yo ahora.",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          Subtitle = "Back when I was tricked by my sisters into becoming a gentleman, he was a sergeant in the Legion. He spent more time on the front lines than at home, just like me now.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590524"
        },
        [80030411] = {
          ContentES = "Pero a diferencia de mí ahora, él valoraba mucho su uniforme. Para él, la Legión parecía su verdadero hogar, mientras que el lugar donde estábamos mis hermanas y yo no era más que un hospedaje donde podía quejarse a voluntad.",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202,
          Subtitle = "But the difference between us is that he was proud of being a soldier. He treated the Legion as his home and his actual home as nothing more than a hotel where he could complain as much as he liked.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859054E"
        },
        [80030412] = {
          ContentES = "Cada vez que volvía a casa, siempre se quejaba de algo: A veces de que el retrato de Su Majestad no estaba colgado derecho, y otras de que mis hermanas llegaban tarde.",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202,
          Subtitle = "Whenever he came home, he'd complain about something or other, like the Emperor's portrait not being hung up properly, or my sisters coming home too late.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590578"
        },
        [80030413] = {
          ContentES = "Pero sin importar qué, siempre dejaba un tiempo para evaluarme.",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202,
          Subtitle = "And he'd always check up on me last.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905A2"
        },
        [80030414] = {
          ContentES = "Me preguntaba cuánto había crecido, qué libros había leído, los nombres de los fuertes que recordaba, y qué habilidades de supervivencia había aprendido. Una pregunta tras otra.",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202,
          Subtitle = "He'd check how much taller I'd got, how many books I'd read, how many forts I'd learned the names of, and what new survival skills I'd acquired.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905CC"
        },
        [80030415] = {
          ContentES = "Intenté hablar con él de otros temas, pero todo lo que no tuviera que ver con “ser militar” le resultaba completamente indiferente.",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202,
          Subtitle = "I tried talking to him about other things, but he wasn't interested in anything other than \"being a soldier.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905F6"
        },
        [80030416] = {
          ContentES = "Una vez, para complacerlo, tallé cuidadosamente una pistola en madera, como hago ahora con mis pequeños inventos, y esperaba con ilusión su elogio.",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          Subtitle = "Once, to try to please him, I painstakingly carved a wooden pistol for him and eagerly awaited his praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590620"
        },
        [80030417] = {
          ContentES = "Pero él simplemente dejó caer la pistola sobre la mesa “¡pum!”, y con el rostro serio, dijo: “Deja de perder el tiempo en tonterías como esas y concéntrate en cómo ser un buen militar”.",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202,
          Subtitle = "But with a stren face he just snatched it from me, \"Don't waste your time on things like this. Think about how you can become a better soldier from now on.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859064A"
        },
        [80030418] = {
          ContentES = "En ese momento, sentí que algo cambió dentro de mí. Algo frío, amargo, intangible e imparable, como el viento aullando fuera de nuestra casa.",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202,
          Subtitle = "At that moment, I felt something change within me. Something cold, bitter, intangible and unstoppable, like the howling wind outside our home.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590674"
        },
        [80030419] = {
          ContentES = "Más tarde me di cuenta de que quizá era odio lo que sentía, tal vez no muy intenso, pero lo suficiente para hacer que la persona frente a mí me resultara desagradable.",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202,
          Subtitle = "Later, I gradually realised that it was hatred. Although it was weak to begin with, it was still strong enough to make me feel that the person in front of me was nothing more than a stranger.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859069E"
        },
        [80030420] = {
          ContentES = "Después de eso, dejé de intentar complacerlo. Ya no me importaban sus evaluaciones ni que me llamara “basura” o me dijera insultos más hirientes.",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202,
          Subtitle = "So after that, I stopped trying to be the son he wanted me to be. I ignored his check-ups on me, no matter how much he scolded me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906C8"
        },
        [80030421] = {
          ContentES = "Hasta que un día, de repente, lo trajeron de vuelta. Durante la batalla, al tratar de proteger a sus subordinados, una esquirla le golpeó la cabeza. Aunque con vida, perdió completamente la conciencia.",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202,
          Subtitle = "Years passed... He was shot in the head while protecting one of his subordinates. He was sent home with a purple heart. Although he was still alive, he had fallen into a coma.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906F2"
        },
        [80030422] = {
          ContentES = "No tenía muchos ahorros. Todo su salario lo enviaba a casa. Así que, lo enviaron de vuelta solo con su medalla reluciente, y su pistola de madera partido en dos.",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202,
          Subtitle = "When he came back, he had nothing but shiny medals, his slender savings, and a wooden pistol that was broken in two.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859071C"
        },
        [80030423] = {
          ContentES = "Siempre pensé que estaba completamente decepcionado de mí, pero sus subordinados me dijeron que aquella pistola de madera lo llevaba siempre consigo. Se había roto cuando cayó en el campo de batalla.",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202,
          Subtitle = "I thought he was disappointed in me because of that broken pistol, but his subordinates told me that he carried it with him at all times and that it broke when he fell on the battlefield.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590746"
        },
        [80030424] = {
          ContentES = "En el fondo, parece que sí me valoraba. Pero su forma de expresarlo era irreconocible.",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          Subtitle = "It seems that he did love me after all. But his way of expressing it was unrecognisable. Maddening.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590770"
        },
        [80030425] = {
          ContentES = "Si realmente se hubiera sentido orgulloso de mí, hubiera preferido que me lo dijera con palabras, aunque fuera la frase más simple de ánimo, en vez de obligarme a hacer cosas que no quería.",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202,
          Subtitle = "If he was proud of me, he should've told me. A few words of encouragement would've been enough, but instead, he just forced me to do things I didn't enjoy.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859079A"
        },
        [80030426] = {
          ContentES = "Aunque nunca más volvió a presionarme para que hiciera algo, me uní a la Legión de todos modos, tal como él quería.",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202,
          Subtitle = "Although he'd never push me to do anything again, I still joined the army, just like he wanted.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907C4"
        },
        [80030427] = {
          ContentES = "Me preguntaba cómo sería ese lugar que había convertido a mi padre en un hombre tan silencioso. Y quería demostrar que podía vivir bien, incluso sin sus regaños.",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202,
          Subtitle = "I was curious about the Legion, the place that had turned my father into a detached man. I also wanted to prove that I could live a great life without his scolding.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907EE"
        },
        [80030428] = {
          ContentES = "Desafortunadamente para ambos, descubrí que él tenía razón todo el tiempo. Me estaba protegiendo.",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202,
          Subtitle = "Unfortunately for both of us, I found out that he was right all along. He was protecting me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590818"
        },
        [80030429] = {
          ContentES = "No éramos como la mayoría de la Legión. Teníamos que levantarnos de entre los cuerpos amontonados en el campo de batalla, arrodillarnos y aceptar las medallas que nos concedían por caridad.",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202,
          Subtitle = "We're unlike most people in the Legion. We crawled out of piles of corpses on the battlefield, and kneel down to receive the medals they bestowed upon us like charity.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590842"
        },
        [80030430] = {
          ContentES = "Un trabajo digno, una vida cómoda, incluso nuestra propia supervivencia… todo dependía de esas pequeñas medallas. Mi padre, por nuestra familia, lo dio todo.",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202,
          Subtitle = "A decent job, a great life, and a means of survival. Everything about us is determined by those small medals. For the sake of our family, my dad devoted himself to them.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859086C"
        },
        [80030431] = {
          ContentES = "Obedeció, soportó, reprimió sus sentimientos, contuvo las lágrimas y se convirtió en un cascarón de hombre.",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202,
          Subtitle = "He obeyed, endured, suppressed his feelings, pushed back the tears, and turned himself into a husk of a man.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590896"
        },
        [80030432] = {
          ContentES = "Yo no soy capaz de soportar lo mismo, pero necesito el dinero para vivir y mantener a mi familia. Así que, como puedes ver, ahora soy un perdedor feliz.",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202,
          Subtitle = "I can't do that, but I need money to support myself and maintain my family's decent lifestyle. So, I'm a happy loser now, as you can see.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908C0"
        },
        [80030433] = {
          ContentES = "...",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908EA"
        },
        [80030434] = {
          ContentES = "Tienes una gran intuición. Para ser sincero, yo mismo tardé mucho en entender lo que estaba haciendo. Lo comprendí solo después de haber estado mucho tiempo deprimido.",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          Subtitle = "You have a keen eye. But to be frank, I have no idea what I want to do. After a long bout of depression, I've finally realised that —",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590914"
        },
        [80030435] = {
          ContentES = "Aunque mis decisiones no coincidan del todo con lo que papá esperaba, estoy satisfecho con mi vida.",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202,
          Subtitle = "Even though I haven't lived up to my dad's expectations, I'm happy with the life I have.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859093E"
        },
        [80030436] = {
          ContentES = "Ojalá… así, esta pesadilla por fin podría acabar.",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "I hope so. If that happens, my nightmares may finally end.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590968"
        },
        [80030437] = {
          ContentES = "¡Qué buena está! Después de tomarla, seguro que no tendré más pesadillas.",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "That tastes good. This will help me sleep without nightmares.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590992"
        },
        [80030438] = {
          ContentES = "Gracias, colega de vacaciones, pero si quiero ir mañana al trabajo, tengo que ir a dormir un poco.",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          Subtitle = "Thanks, holiday buddy, but I need some sleep now, or else I'll have to take more leave tomorrow.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909BC"
        },
        [80030439] = {
          ContentES = "No te preocupes, la próxima vez que nos veamos, seguiré siendo el Randy que conoces. Y si vuelvo a tener pesadillas, te pediré que me prepares otra bebida.",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          Subtitle = "Don't worry, I'll be the regular Randy you know the next time we meet. And if I have another nightmare, please make me one more cup of this delicious drink.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909E6"
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "Una bebida caliente, con extra de azúcar. Además, traje algunos postres de la Capital Imperial. Tuve que hacer una larga cola para comprarlos, pruébalos.",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202,
          Subtitle = "A hot drink with extra sugar, please. I brought some desserts from the Imperial Capital. I queued up to buy them during my break. Want to try some?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591412"
        },
        [80030502] = {
          ContentES = "Sí, por eso quería beber algo dulce, y para prepararte para lo que te voy a decir a continuación.",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "I sure am. I'm in the mood for a sweet drink as a prelude to my invitation.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859143C"
        },
        [80030503] = {
          ContentES = "¡Nada! Solo quiero invitarte a algo, eso no significa que esté tramando algo.",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "Ooh! I want to ask a small favour of you, but I wouldn't call it a \"plan.\"",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591466"
        },
        [80030504] = {
          ContentES = "Ejem, eh, bueno… aunque sea un poco repentino, ¿te gustaría bailar conmigo?",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202,
          Subtitle = "Ahem... Maybe this is a little sudden, but do you want to attend a dance with me?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591490"
        },
        [80030505] = {
          ContentES = "La Legión siempre debe mantener buenas relaciones con las entidades locales. Por eso, debemos asistir a las ceremonias sociales que se celebran en la Ciudad Interior, aunque a veces suelen ser un poco molestas.",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          Subtitle = "Like I mentioned to you before, the Legion needs to maintain ties with local nobility. So, I need to attend annoying social balls in the inner city from time to time.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914BA"
        },
        [80030506] = {
          ContentES = "No tengo ganas de ir. Aunque sea considerado un viaje de trabajo, tratar con esos tipos y sus esposas es un verdadero fastidio.",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202,
          Subtitle = "I really don't want to go. The trip is paid for, but dealing with nobility is such a headache.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914E4"
        },
        [80030507] = {
          ContentES = "Así que se me ocurrió una buena idea: entrar acompañado de una dama hermosa que esté dispuesta a bailar conmigo.",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202,
          Subtitle = "So, I have a perfect solution. I can take a gorgeous lady with me as my partner.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859150E"
        },
        [80030508] = {
          ContentES = "Así no habrá nadie que venga a presentarme a una parienta lejana que ni ellos mismos conocen.",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202,
          Subtitle = "That way, no one will try to introduce me to a female relative I've never met before.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591538"
        },
        [80030509] = {
          ContentES = "Bueno… pensé que… tal vez podrías disfrazarte, probar un estilo diferente…",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          Subtitle = "Well... I was thinking... maybe... you could try to disguise yourself as a lady.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591562"
        },
        [80030510] = {
          ContentES = "¡Ah! ¡Pues porque yo soy el invitado!",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "I can't. I'm the one who's been invited.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859158C"
        },
        [80030511] = {
          ContentES = "¡Ay! La verdad es que no tengo muchas opciones, por eso se me ocurrió esta idea.",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "Sorry, but you're my last hope. I'm really clutching at straws here!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915B6"
        },
        [80030512] = {
          ContentES = "Ya hemos bebido juntos tantas veces, confío más en ti que en cualquiera de mis hermanas. Si no, no se me hubiera ocurrido pedirte algo así.",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202,
          Subtitle = "We've had so many drinks together, and you're my closest friend. I'm even closer to you than my siblings, so I'm begging you for help.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915E0"
        },
        [80030513] = {
          ContentES = "Vamos, hoy por mí y mañana por ti. ¡Si me ayudas a salir de este aprieto te daré la mitad de mi sueldo durante los próximos seis meses!",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202,
          Subtitle = "If you help me in my time of need, I'll give you half of my salary for the next six months. And, if Chief Sibylle tries to arrest you next time, I'll come forward and protect you!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859160A"
        },
        [80030514] = {
          ContentES = "Si de verdad no te gusta la idea, después del baile yo me pongo el vestido, ¿trato hecho?",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202,
          Subtitle = "If that's not enough, I'll dress up like a lady and entertain you after the ball. What do you say?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591634"
        },
        [80030515] = {
          ContentES = "¡No… no me malinterpretes! No, no, no es así. No tengo ese tipo de interés. ¿Cómo puedes pensar eso?",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          Subtitle = "No, no, no! You've got the wrong idea! What makes you think that?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859165E"
        },
        [80030516] = {
          ContentES = "Los buenos amigos comen juntos, juegan juntos, van juntos al baño, se ponen vestidos juntos, y cosas así. Es lo normal, ¿no?",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202,
          Subtitle = "I mean, it's normal, right? Best buds do everything together — hang out, share meals, hit the restroom, try on dresses...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591688"
        },
        [80030517] = {
          ContentES = "¡Oye, no te rías! Lo digo en serio, necesito una respuesta. Si no estás de acuerdo, tendré que ingeniármelas de otra forma…",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Hey, don't laugh at me. I'm really in a bind here. Please just give me your answer. If you say \"no,\" I'll have to find another solution.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916B2"
        },
        [80030518] = {
          ContentES = "Por favor, al menos intenta considerarlo...",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202,
          Subtitle = "Just think about it...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916DC"
        },
        [80030519] = {
          ContentES = "Espera… ¿Aceptaste? ¡Genial! ¡Ahora somos prácticamente hermanos!",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202,
          Subtitle = "Huh? Really? That's fantastic! You're a lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591706"
        },
        [80030520] = {
          ContentES = "Me has hecho un enorme favor. Te lo recompensaré de cualquier forma que pueda.",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591730"
        },
        [80030521] = {
          ContentES = "Pero hablemos de esto después del baile. Necesito ir a casa y preparar mi traje antes de que cambies de opinión.",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
          SpeakNpcId = 94202,
          Subtitle = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859175A"
        },
        [80030522] = {
          ContentES = "Nos vemos luego, mi colega de vacaciones, mi pareja de descansos, y la razón de todas mis aventuras hasta ahora.",
          DialogueId = 80030522,
          GUID = "C8591784",
          SpeakNpcId = 94202,
          Subtitle = "I'll see you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591784"
        },
        [80030523] = {
          ContentES = "Mmm, ¿no quieres pensarlo un poco más? Después del baile, voy a buscar la manera de devolverte el favor, como quien inventa excusas para faltar al trabajo.",
          DialogueId = 80030523,
          GUID = "C85917AE",
          NextDialogue = 80030524,
          SpeakNpcId = 94202,
          Subtitle = "Please give it plenty of consideration. After the ball, I'll find many creative ways to repay you, just like how I come up with excuses to take time off.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85917AE"
        },
        [80030524] = {
          ContentES = "Creo que por ahora debemos tranquilizarnos y darte un tiempo para pensar. Igual, confío en que vas a aceptar.",
          DialogueId = 80030524,
          GUID = "C85917D8",
          NextDialogue = 80030525,
          SpeakNpcId = 94202,
          Subtitle = "Take as much time as you need. I really need your help, and I'm certain that you'll come through for me.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85917D8"
        },
        [80030525] = {
          ContentES = "Bueno, me retiro por ahora. Estaré esperando tus buenas noticias, mi colega de vacaciones, mi pareja de descansos.",
          DialogueId = 80030525,
          GUID = "C8591802",
          SpeakNpcId = 94202,
          Subtitle = "I'll be awaiting your answer. See you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591802"
        },
        [80030526] = {
          ContentES = "Siendo sincero... sí. Es que no existe mejor pareja de baile que tú… Por eso, ¿me ayudarías a liberarme de este problema?",
          DialogueId = 80030526,
          GUID = "C8591856",
          NextOptions = {
            [1] = 800305261
          },
          SpeakNpcId = 94202,
          Subtitle = "Yes, you're my best dancing partner, after all. The question is, are you willing to do me this favour?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591856"
        },
        [80030527] = {
          ContentES = "¿Ah…?",
          DialogueId = 80030527,
          GUID = "C8591880",
          NextDialogue = 80030528,
          SpeakNpcId = 94202,
          Subtitle = "What?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591880"
        },
        [80030528] = {
          ContentES = "¿Por qué diablos haría eso? ¡Si de verdad quisiera arrestarte, lo habría hecho desde la primera vez que nos conocimos!",
          DialogueId = 80030528,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          Subtitle = "Why on earth would you think that? If I really wanted to arrest you, I could've done that the first time we met.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918AA"
        },
        [80030529] = {
          ContentES = "No le veo el sentido a usar mis preciadas vacaciones para venir a organizar algo como un “baile de arresto secreto”.",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202,
          Subtitle = "I don't see the point in using my precious leave to come here and organise something like a \"secret arrest ball\".",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918D4"
        },
        [80030530] = {
          ContentES = "¿Y si me rechazas? ¿Cómo funcionaría mi plan en ese caso?",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202,
          Subtitle = "And what if you turn me down? How would my plan work in that case?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918FE"
        },
        [80030531] = {
          ContentES = "¿Estás bromeando? ¿De verdad piensas que soy un tonto malvado?",
          DialogueId = 80030531,
          GUID = "C8591928",
          NextOptions = {
            [1] = 800305311,
            [2] = 800305312
          },
          SpeakNpcId = 94202,
          Subtitle = "You must be kidding. Do you seriously think I'm a scheming fool like that?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591928"
        },
        [80030532] = {
          ContentES = "Menos mal. Si de verdad me malinterpretaras y pensaras que soy un sinvergüenza dispuesto a traicionar a mi amiga de esa manera, necesitaría un mes de vacaciones para recuperarme de tal desengaño.",
          DialogueId = 80030532,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591952",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          Subtitle = "Alright then. If you really did misunderstand me and think I was a shameless jerk who'd betray his friends like that, I'd need a month's leave to recover from such heartbreak.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591952"
        },
        [80030533] = {
          ContentES = "¡Oye, al menos niega que traicioné a mi amiga por interés personal, o si no vas a herir mis sentimientos!",
          DialogueId = 80030533,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C859197C",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          Subtitle = "Hey, at least deny that I betrayed my friends for personal gain, or else you'll hurt my feelings!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859197C"
        },
        [80030534] = {
          ContentES = "Sin embargo, ahora hay algo de lo que puedo estar seguro: No le tienes miedo al peligro.",
          DialogueId = 80030534,
          GUID = "C85919A6",
          NextDialogue = 80030535,
          SpeakNpcId = 94202,
          Subtitle = "But now there's one thing I'm sure of — You're not afraid of risk at all.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919A6"
        },
        [80030535] = {
          ContentES = "Solo estás jugando conmigo para ver cómo reacciono.",
          DialogueId = 80030535,
          GUID = "C85919D0",
          NextOptions = {
            [1] = 800305351,
            [2] = 800305352
          },
          SpeakNpcId = 94202,
          Subtitle = "So, you were messing with me to see my reaction.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919D0"
        },
        [80030536] = {
          ContentES = "No sabía que te encantaran las bromas tontas como a mí. ¿De quién lo aprendiste?",
          DialogueId = 80030536,
          GUID = "C85919FA",
          NextDialogue = 80030537,
          SpeakNpcId = 94202,
          Subtitle = "I didn't know you love mean tricks like me. Where did you pick that up?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919FA"
        },
        [80030537] = {
          ContentES = "La verdad, sí me asusté por unos segundos. Aunque en el fondo sabía que era imposible, igual me preocupé… ¿y si de verdad pensabas eso de mí?",
          DialogueId = 80030537,
          GUID = "C8591A24",
          NextDialogue = 80030538,
          SpeakNpcId = 94202,
          Subtitle = "I panicked for a moment then. Although deep down I knew it was impossible, I was still worried. What if you really thought that way?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A24"
        },
        [80030538] = {
          ContentES = "Y ahora, como compensación por tu bromita, tienes que aceptar mi invitación.",
          DialogueId = 80030538,
          GUID = "C8591A4E",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "So, to make up for your trick, you must help me.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A4E"
        },
        [80030539] = {
          ContentES = "¿Eh?",
          DialogueId = 80030539,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591A78",
          NextDialogue = 80030540,
          SpeakNpcId = 94202,
          Subtitle = "What?!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A78"
        },
        [80030540] = {
          ContentES = "Está bien, tienes razón. Siempre he querido arrestarte. Solo pienso en eso de día y de noche. Cuando no duermo, solo pienso en cómo capturarte. Solo que la pereza siempre me gana… y nunca hago nada.",
          DialogueId = 80030540,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591AA2",
          NextDialogue = 80030541,
          SpeakNpcId = 94202,
          Subtitle = "Okay, fine, you're right. I've been wanting to arrest you for ages. Every morning, I wake up and think about how to carry out my devious plan, but I procrastinate too much to actually do it.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591AA2"
        },
        [80030541] = {
          ContentES = "Y justo esta vez que por fin quería ponerme a trabajar… me descubriste. ¿Y ahora qué hago?",
          DialogueId = 80030541,
          GUID = "C8591ACC",
          NextDialogue = 80030542,
          SpeakNpcId = 94202,
          Subtitle = "This time, I was hoping to fulfil my duty but failed. What do I do?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591ACC"
        },
        [80030542] = {
          ContentES = "Todo indica que me expulsarán de la Legión, y que deambularé por las frías calles de Lago Helado, sufriendo frío y hambre, sin un techo donde refugiarme…",
          DialogueId = 80030542,
          GUID = "C8591AF6",
          NextDialogue = 80030543,
          SpeakNpcId = 94202,
          Subtitle = "One day, I'll be fired by the Legion and end up homeless and destitute on the cold streets of Icelake.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591AF6"
        },
        [80030543] = {
          ContentES = "¿De verdad podrías quedarte mirando cómo me convierto en una escultura de hielo en plena calle?",
          DialogueId = 80030543,
          GUID = "C8591B20",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Do you really want to see me turn into an ice sculpture on the street?",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B20"
        },
        [80030544] = {
          ContentES = "Por favor, al menos intenta considerarlo...",
          DialogueId = 80030544,
          GUID = "C8591B4A",
          NextDialogue = 80030545,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you can think twice before answering me...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B4A"
        },
        [80030545] = {
          ContentES = "¿Eh? ¿En serio dijiste que sí? ¡Fantástico! Tú… tú… ¡eres como mi alma gemela!",
          DialogueId = 80030545,
          GUID = "C8591B74",
          NextDialogue = 80030546,
          SpeakNpcId = 94202,
          Subtitle = "... Huh? Really? That's fantastic! You're my lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B74"
        },
        [80030546] = {
          ContentES = "Me has hecho un enorme favor. Te lo recompensaré de cualquier forma que pueda.",
          DialogueId = 80030546,
          GUID = "C8591B9E",
          NextDialogue = 80030547,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B9E"
        },
        [80030547] = {
          ContentES = "Pero hablemos de esto después del baile. Necesito ir a casa y preparar mi traje antes de que cambies de opinión.",
          DialogueId = 80030547,
          GUID = "C8591BC8",
          NextDialogue = 80030548,
          SpeakNpcId = 94202,
          Subtitle = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591BC8"
        },
        [80030548] = {
          ContentES = "Nos vemos luego, mi colega de vacaciones, mi pareja de descansos, y la razón de todas mis aventuras hasta ahora.",
          DialogueId = 80030548,
          GUID = "C8591BF2",
          SpeakNpcId = 94202,
          Subtitle = "I'll see you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591BF2"
        },
        [80040101] = {
          Camera = "-52.422852,-88.373047,123.091431,0.000216,-4.998045,54.58065,40.000011,196.024292,false,Manual,4.967944",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "¡Ya está listo! ¡Berry, pruébalo!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040101,
          Duration = 8,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-52.422852,-88.373047,123.091431,0.000229,2.801914,39.180523,40.000011,120.906364,false,Manual,4.967944",
          GUID = "C85F3B12",
          NextDialogue = 80040102,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/cook_finish\"},PlayAs2D{true}}",
          SpeakNpcId = 790008,
          Subtitle = "There we go. Try this, Berry.",
          TalkActionId = {
            [1] = "790008:Give"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B12"
        },
        [80040102] = {
          Camera = "-29.085938,-97.268799,150.180298,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786",
          ContentES = "Eh, sí...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040102,
          FacialId = {
            [1] = "790007:Iyada01"
          },
          GUID = "C85F3B3C",
          NextDialogue = 80040103,
          SpeakNpcId = 790007,
          Subtitle = "Hmm, okay...",
          TalkActionId = {
            [1] = "790007:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B3C"
        },
        [80040103] = {
          Camera = "-199.146484,-426.681641,234.483765,0.000222,-15.191071,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentES = "Ah, por cierto, ¿por qué querías quitarme el cucharón hace rato?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040103,
          FinalCamera = "-186.857422,-430.990479,234.483765,0.000221,-15.191064,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B66",
          NextDialogue = 80040104,
          SpeakNpcId = 790007,
          Subtitle = "So, why were you so eager to take the ladle from me earlier?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B66"
        },
        [80040104] = {
          Camera = "-24.671387,-68.66333,139.902344,0.000222,-5.191469,35.319683,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentES = "¡Pues, porque querías echarle granadas a la sopa de pescado!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040104,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "-24.671387,-68.66333,139.902344,0.000222,-4.591458,35.919678,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B90",
          NextDialogue = 80040105,
          SpeakNpcId = 790008,
          Subtitle = "Because you were about to add pomegranates to the fish soup!",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B90"
        },
        [80040105] = {
          ContentES = "¿Y no se puede? Recuerdo que cuando éramos pequeños a ti también te gustaban las granadas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040105,
          FacialId = {
