          SpeakNpcId = 790007,
          Subtitle = "What's wrong with that? I remember you used to love pomegranates when you were little.",
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BBA"
        },
        [80040106] = {
          Camera = "98.562256,-40.027588,134.129395,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          ContentES = "El año pasado, cuando pasamos por ese árbol de granadas, recogiste una bolsa entera. Qué lástima que se cayeran todas cuando te resbalaste, recuerdo lo triste que te sentiste.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040106,
