          SpeakNpcId = 790007,
          Subtitle = "Remember last year when we walked past that big pomegranate tree? You picked a whole bag of them. Too bad they all rolled down the hill when you slipped. You said it was such a waste.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BE4"
        },
        [80040107] = {
          ContentES = "Así que cuando volvieron a crecer, recogí varias especialmente para ti... No me digas que ya no te gustan.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040107,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C85F3C0E",
          NextDialogue = 80040108,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"-187.269043,-90.881348,151.269409,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205"},duration{0}},
CameraMoveTo{TargetPosition{"-178.94751,-87.67041,150.519897,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205"},duration{8}}
}]],
          SpeakNpcId = 790007,
          Subtitle = "So this time, I picked some just for you... Don't you like them anymore?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C0E"
        },
        [80040108] = {
          ContentES = "No es eso. El punto es que si las mezclas con pescado, va a saber muy raro, ¿no crees?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040108,
          GUID = "C85F3C38",
          NextDialogue = 80040109,
          SpeakNpcId = 790008,
          Subtitle = "It's not about the pomegranates. It's just that pomegranates and fish might not taste good together, don't you think?",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C38"
        },
        [80040109] = {
          Camera = "21.563721,-75.783936,229.640259,-0.000637,-35.195148,81.889259,40.0,256.07196,false,DoNotOverride,3.614923",
          ContentES = "¿Pero no decías que las bayas con leche sabían riquísimas? En la Isla del Purgatorio no es tan fácil conseguir leche, pero si en vez de eso usamos sopa de pescado, sería lo mismo... ¿no?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040109,
          FacialId = {
            [1] = "790007:Shock01"
          },
          FinalCamera = "10.167236,-74.255371,229.640259,-0.000639,-35.195141,79.688759,40.0,256.07196,false,DoNotOverride,3.614923",
          GUID = "C85F3C62",
          NextDialogue = 80040110,
          SpeakNpcId = 790007,
          Subtitle = "But you like berries dipped in milk... It's hard to buy milk here on this island, so I thought soup would work just as well.",
          TalkActionId = {
            [1] = "790007:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C62"
        },
        [80040110] = {
          Camera = "-37.483398,2.658447,166.522949,-0.00064,-21.195223,-16.305603,35.0,310.796967,false,DoNotOverride,3.614923",
          ContentES = "Claro que no es lo mismo. Para empezar, la sopa de pescado es salada y huele, obviamente, a pescado. No va bien con los sabores dulces. Además, la fruta sabe mejor cuando se come natural; si la hierves en la olla, pierde su textura crujiente.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040110,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "-35.881348,8.803955,166.522949,-0.000641,-21.195223,-19.305702,35.0,310.796967,false,DoNotOverride,3.614923",
          GUID = "C85F3C8C",
          NextDialogue = 80040111,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-485.556885,386.265381,18.750732,-0.000641,6.804555,-44.504627,35.0,680.101196,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-473.364258,398.938477,18.750732,-0.000641,6.804555,-47.504635,35.0,680.101196,false,Manual,1.2\"},duration{15}}}",
          SpeakNpcId = 790008,
          Subtitle = "{性别:It's not really the same|It's really not the same}. Fish soup has a strong salty, fishy taste, so it doesn't go well with sweet fruits. Plus, fruits are best eaten fresh; they'd lose their crunch if boiled.",
          TalkActionId = {
            [1] = "790007:Think_End",
            [2] = "790008:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C8C"
        },
        [80040111] = {
          ContentES = "Y en todo caso, ¡si vas a hervir granadas, al menos quítales la cáscara primero!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040111,
          FacialId = {
            [1] = "790008:Doubt01"
          },
          GUID = "C85F3CB6",
          NextDialogue = 80040112,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-107.39624,20.544678,102.665894,-0.000641,6.403753,-15.313855,35.0,680.101196,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-107.39624,20.544678,102.665894,-0.000641,7.603742,-15.313935,35.0,680.101196,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 790008,
          Subtitle = "And even if you were to cook pomegranates, you should at least peel them first...",
          TalkActionId = {
            [1] = "790008:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3CB6"
        },
        [80040112] = {
          Camera = "146.959473,123.187256,110.276123,-0.000641,2.803786,-132.900482,30.0,296.883026,false,Manual,4.419911",
          ContentES = "Mmm... Es más complicado de lo que pensaba.",
