        [80040125] = {
          Camera = "113.315186,151.120361,105.79834,0.000122,6.203184,-112.57106,40.0,164.391006,false,Manual,5.845709",
          ContentES = "Para nada, en realidad cocinas muy bien, casi siempre.... Solo que esas dos veces no tuviste tanta suerte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040125,
          FacialId = {
            [1] = "790008:Ahaha02"
          },
          FinalCamera = "122.489502,147.21582,105.446533,0.000123,3.003179,-140.170731,40.000011,313.635376,false,Manual,5.845709",
          GUID = "C85F3F02",
          NextDialogue = 80040126,
          SpeakNpcId = 790008,
          Subtitle = "...Not at all. Your cooking is usually great. Those were just minor hiccups — everyone has off days.",
          TalkActionId = {
            [1] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3F02"
        },
        [80040126] = {
          ContentES = "Cuando cocinas, siempre tengo muchas ganas de probar cualquier plato nuevo que inventes… ¡Y sabes qué! El que escribió «El arte de la cocina» no tiene ni idea de lo que es cocinar. No sabe cómo combinar los ingredientes de forma original.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040126,
          FacialId = {
            [1] = "790008:Satisfy01"
          },
          GUID = "C85F3F2C",
          NextDialogue = 80040127,
          Scripts = "PARA{SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{_delay{3},ActorId{790008},AnimationId{\"Confident_Start\"},Duration{3}}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-451.446045,109.144287,58.609131,0.000133,5.802526,-23.556147,40.0,62.233727,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-448.734375,115.36499,58.609131,0.000134,5.802526,-23.555901,40.0,62.233727,false,Manual,22.0\"},duration{15}}}}",
          SpeakNpcId = 790008,
          Subtitle = "I always look forward to trying whatever new dish you've invented... And you know what? It's the author of \"The Art of Cooking\" who has no taste! They don't appreciate innovative ingredient combinations.",
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3F2C"
        },
        [80040127] = {
          Camera = "-7.822998,17.936523,129.39856,0.000159,0.802219,-147.953476,40.0,127.794029,false,Manual,5.845709",
          ContentES = "¿En serio? O solo me quieres hacer sentir mejor...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040127,
          FacialId = {
            [1] = "790008:None",
            [2] = "790007:Satisfy01"
          },
          FinalCamera = "-5.730713,14.651611,129.39856,0.000159,0.802219,-150.153061,40.0,137.385742,false,Manual,5.845709",
          GUID = "C85F3F56",
          NextDialogue = 80040128,
          SpeakNpcId = 790007,
          Subtitle = "You really think so? Or are you just saying that...",
          TalkActionId = {
            [1] = "790008:Confident_End",
            [2] = "790007:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3F56"
        },
        [80040128] = {
          Camera = "-119.140625,17.986816,144.082153,0.000186,-5.597982,-15.525949,40.000011,174.773438,false,Manual,5.845709",
          ContentES = "¡Claro que no! ¿Cuándo te he mentido?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040128,
          GUID = "C85F3F80",
          NextDialogue = 80040129,
          SpeakNpcId = 790008,
          Subtitle = "Have I ever lied to you?",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3F80"
        },
        [80040129] = {
          Camera = "-578.566895,555.506348,232.559326,0.000266,-9.399719,-48.958965,40.0,859.451477,false,Manual,1.2",
          ContentES = "Bueno...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040129,
          GUID = "C85F3FAA",
          NextDialogue = 80040130,
          SpeakNpcId = 790007,
          Subtitle = "...Right.",
          TalkActionId = {
            [1] = "790007:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3FAA"
        },
        [80040130] = {
          Camera = "-578.566895,555.506348,232.559326,0.000266,-9.399719,-48.958965,40.0,859.451477,false,Manual,1.2",
          ContentES = "Entonces, ¿puedes decirme a qué sabe una granada?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040130,
          FinalCamera = "-573.692627,549.909668,231.330811,0.000266,-9.399719,-48.958935,40.0,859.451477,false,Manual,1.2",
          GUID = "C85F3FD4",
          NextDialogue = 80040131,
          SpeakNpcId = 790007,
          Subtitle = "Well, can you tell me what a pomegranate tastes like?",
          TalkActionId = {
            [1] = "790008:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3FD4"
        },
        [80040131] = {
          Camera = "-221.572266,-16.551514,137.419067,0.00028,-4.399502,-7.360059,40.0,282.428741,false,Manual,2.79054",
          ContentES = "Es un poco dulce, un poco amargo y... bueno, y otras cosas más que no puedo decirte ahora.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040131,
          FinalCamera = "-220.866455,-10.840088,137.419067,0.000279,-4.399502,-9.360314,40.0,282.428741,false,Manual,2.79054",
          GUID = "C85F3FFE",
          NextDialogue = 80040132,
          SpeakNpcId = 790008,
          Subtitle = "It's a bit sweet, a bit sour, and — well, let's keep that a secret for now.",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3FFE"
        },
        [80040132] = {
          Camera = "95.760498,168.30957,108.807495,0.000322,1.199449,-118.340714,25.0,282.428741,false,Manual,2.79054",
          ContentES = "¿Por qué?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040132,
          GUID = "C85F4028",
          NextDialogue = 80040133,
          SpeakNpcId = 790007,
          Subtitle = "Why?",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F4028"
        },
        [80040133] = {
          Camera = "95.760498,168.30957,108.807495,0.000322,1.199449,-118.340714,25.0,282.428741,false,Manual,2.79054",
          ContentES = "Que te digan cómo sabe algo es aburridísimo. Es mejor que lo pruebes tú misma.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040133,
          GUID = "C85F4052",
          NextDialogue = 80040134,
          SpeakNpcId = 790008,
          Subtitle = "Tasting is something you should experience yourself.",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F4052"
        },
        [80040134] = {
          Camera = "-173.155518,-29.748779,137.313843,0.000326,-3.800016,-5.949226,35.000008,211.470428,false,Manual,2.79054",
          ContentES = "Si perdiste el sentido del gusto por una poción, entonces debe existir otra que te lo devuelva, ¿no?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040134,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-172.891357,-26.610596,137.313843,0.000326,-3.800016,-6.94926,35.000008,211.470428,false,Manual,2.79054",
          GUID = "C85F407C",
          NextDialogue = 80040135,
          SpeakNpcId = 790008,
          Subtitle = "If it's the potion that made you lose your taste, there's got to be something that can bring it back, right?",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F407C"
        },
        [80040135] = {
          Camera = "-425.241211,98.722656,62.558838,0.000359,6.599335,-20.947884,35.0,476.22876,false,Manual,12.234338",
          ContentES = "Bien, desde ahora me pondré a juntar dinero en serio. ¡Para poder salir pronto de esta isla y encontrar esa poción!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040135,
          FinalCamera = "-427.385742,93.11792,62.558838,0.000359,6.599335,-19.947929,35.000008,482.809113,false,Manual,14.941204",
          GUID = "C85F40A6",
          NextDialogue = 80040136,
          SpeakNpcId = 790008,
          Subtitle = "Alright, starting today, I'm going to earn as much as I can, so that I can soon get off this island to find that cure!",
          TalkActionId = {
            [1] = "790008:Angry01_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F40A6"
        },
        [80040136] = {
          Camera = "-33.544434,-5.307129,160.189575,0.000367,-19.800526,-12.556828,35.0,211.470428,false,DoNotOverride,2.79054",
          ContentES = "Una vez que recuperes el sentido del gusto, probaremos toda la comida deliciosa que hay más allá de esta isla. ¡Y compraremos un montón de tus granadas favoritas hasta llenar la habitación con ellas!",
          DialogueId = 80040136,
          FacialId = {
            [1] = "790008:Happy02"
          },
          FinalCamera = "-32.419434,-0.398926,160.189575,0.000366,-19.800526,-15.957611,35.0,211.470428,false,DoNotOverride,2.79054",
          GUID = "C85F40D0",
          LookAt = {
            [1] = "790007:n(790007)"
          },
          NextDialogue = 80040137,
          Scripts = "SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Angry01_End\"},Duration{1}},PlayAnimation{_delay{3},ActorId{790008},AnimationId{\"Explain02_Start\"},Duration{3}}}",
          SpeakNpcId = 790008,
          Subtitle = "Once your sense of taste is back, we'll try all the delicious food out there in the world... and buy loads of your favourite pomegranates!",
          TalkActionId = {
            [1] = "790007:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F40D0"
        },
