        [80040138] = {
          Camera = "-433.807861,306.72583,200.69043,0.000452,21.596996,-168.54541,35.0,1486.565063,false,Manual,1.2",
          ContentES = "¿Más allá de esta isla...?",
          DefaultLookAt = "TalkNpc",
