          FinalCamera = "-433.807861,306.72583,200.69043,0.000451,26.996834,-173.544968,35.0,1486.565063,false,Manual,1.2",
          GUID = "C85F4124",
          SpeakNpcId = 790007,
          Subtitle = "...The world beyond this island, mm.",
