        [80040403] = {
          Camera = "-653.439453,-441.171875,78.795898,-0.519562,3.799265,-78.597588,45.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡¿Qué?!",
          DialogueId = 80040403,
          FinalCamera = "-662.69043,-395.287109,75.687256,-0.519562,3.799265,-78.597588,45.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C85F6C9E",
