        [80040405] = {
          Camera = "-361.287109,107.506836,20.286011,0.00013,7.201205,-11.001987,35.000008,265.279572,false,DoNotOverride,4.86023",
          ContentES = "¡{nickname}…! ¿Te encuentras bien?",
          DialogueId = 80040405,
          GUID = "C85F6CF2",
          IsBlack = 1,
          NextDialogue = 80040406,
          Scripts = "SEQ{StopNormalSound{EventKey{\"Invite_Heitao_Sound_Loop\"}},PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/monster_attack_nvzhu\"},PlayAs2D{true}}}",
