        },
        [80040406] = {
          Camera = "11.561523,71.806152,135.715027,0.000139,-16.599018,5.797287,35.000008,265.279572,false,DoNotOverride,4.86023",
          ContentES = "Berry, lo siento, creo que...",
          DialogueId = 80040406,
          FinalCamera = "10.962891,79.581055,135.715027,0.000139,-16.599018,0.79736,35.000008,265.279572,false,DoNotOverride,4.86023",
          GUID = "C85F6D1C",
          IsBlack = 1,
          NextDialogue = 80040407,
          SpeakNpcId = 790008,
          Subtitle = "Berry, I think I might...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6D1C"
        },
        [80040407] = {
          Camera = "192.182617,198.81543,123.755371,-0.519562,0.0,-141.410492,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡...!",
          DialogueId = 80040407,
          GUID = "C85F6D46",
          IsBlack = 1,
          SpeakNpcId = 790007,
          Subtitle = " ...!",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6D46"
        },
        [80040409] = {
          Camera = "169.034668,216.214355,146.896851,0.002309,-25.007753,-135.609787,35.000011,340.145996,false,DoNotOverride,22.0",
          ContentES = "La herida está vendada. No debería haber ningún problema.",
          DialogueId = 80040409,
          FacialId = {
            [1] = "790060:Smile01"
          },
          FinalCamera = "178.08252,207.950684,146.896851,0.002304,-23.6077,-139.41008,35.000011,340.145996,false,DoNotOverride,22.0",
          GUID = "C85F6D9A",
          NextDialogue = 80040410,
          SpeakNpcId = 790060,
          Subtitle = "I've patched up all your wounds. It should be all right for now.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6D9A"
        },
        [80040410] = {
          Camera = "40.396484,533.094727,40.722107,0.000072,-4.601348,-103.414253,45.0,563.736694,false,Manual,7.664447",
          ContentES = "No tienes fiebre y tu respiración es normal… Parece que te dormiste solo por el cansancio. Estos días han sido bastante intensos para ti.",
          DialogueId = 80040410,
          FacialId = {
            [1] = "790060:Satisfy01"
          },
          FinalCamera = "54.046875,529.838867,40.722107,0.000072,-4.601348,-103.414253,45.0,563.736694,false,Manual,7.664447",
          GUID = "C85F6DC4",
          LookAt = {
            [1] = "790060:n(790064)"
          },
          NextDialogue = 80040411,
          SpeakNpcId = 790060,
          Subtitle = "No fever, your breathing's steady... looks like you're just worn out and fast asleep. Right, you've really been through a lot these past few days.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6DC4"
        },
        [80040411] = {
          Camera = "-73.277832,275.365723,48.60321,0.000391,1.589139,-27.006346,35.000008,79.77787,false,Manual,1.824698",
          ContentES = "Siempre que me hago daño yo, me reprochas sin parar.",
          DialogueId = 80040411,
          FinalCamera = "-75.61084,270.786133,48.60321,0.00039,1.589139,-27.006401,35.000008,218.197388,false,Manual,1.824698",
          GUID = "C85F6DEE",
          NextDialogue = 80040412,
          SpeakNpcId = 790060,
          Subtitle = "You always lecture me when I get hurt.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6DEE"
        },
        [80040412] = {
          ContentES = "Y ahora, que por fin puedo “vengarme” y reprocharte, te quedas durmiendo plácidamente...",
          DialogueId = 80040412,
          GUID = "C85F6E18",
          NextDialogue = 80040414,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"-95.536133,255.541504,60.537231,0.002338,10.59139,-27.213076,55.0,340.145996,false,DoNotOverride,2.993798"},duration{0}},
CameraMoveTo{TargetPosition{"-103.48584,238.5,60.537231,0.002337,11.191442,-22.214205,55.0,340.145996,false,DoNotOverride,2.993798"},duration{15}}
}]],
          SpeakNpcId = 790060,
          Subtitle = "Now the tables have turned, and here you are, sleeping like a log... not giving me a chance to lecture you.",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6E18"
        },
        [80040414] = {
          ContentES = "Siempre me preguntas por qué tengo que cuidarte... Yo también tengo esa duda, ¿por qué será?",
          DialogueId = 80040414,
          FacialId = {
            [1] = "790060:None"
          },
          GUID = "C85F6E6C",
          NextDialogue = 80040415,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"191.12207,230.868164,155.581116,0.002298,-21.007647,-133.010544,35.000008,340.145996,false,DoNotOverride,2.993798"},duration{0}},
CameraMoveTo{TargetPosition{"177.152832,243.899902,155.581787,0.002297,-21.007652,-131.210739,35.000008,340.145996,false,DoNotOverride,2.993798"},duration{15}}
}]],
          SpeakNpcId = 790060,
          Subtitle = "You always wonder why I feel the need to protect you... Hmm, why is that?",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6E6C"
        },
        [80040415] = {
          ContentES = "Tienes razón. No somos diferentes, cuando me entra arena en los ojos, a mi también me pican. Si me hacen cosquillas, también me río. Y cuando me corto, también sangro... también me duele.",
          DialogueId = 80040415,
          FacialId = {
            [1] = "790060:Iyada01"
          },
          GUID = "C85F6E96",
          NextDialogue = 80040416,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"-6.992676,87.786133,149.375549,0.002285,-21.206869,-24.605883,35.000008,244.56134,false,DoNotOverride,3.621493"},duration{0}},
CameraMoveTo{TargetPosition{"-6.992676,87.786133,149.375549,0.002281,-24.6068,-19.605743,35.000008,244.56134,false,DoNotOverride,3.621493"},duration{15}}
}]],
          SpeakNpcId = 790060,
          Subtitle = "You're right, I'm just like you — sand in my eyes makes them itch, a tickle on my palm makes me laugh, and a cut on my hand hurts and bleeds.",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6E96"
        },
        [80040416] = {
          Camera = "-225.149414,36.097168,86.482788,0.002315,-11.20821,41.174503,35.000008,373.138092,false,Manual,2.993798",
          ContentES = "Tú y yo no somos tan diferentes. ¿Por qué siempre tengo la necesidad de protegerte... como si fuera parte de lo que soy?",
          DialogueId = 80040416,
          FinalCamera = "-233.417969,45.550781,76.621582,0.002315,-11.20821,41.174503,35.000008,373.138092,false,Manual,2.993798",
          GUID = "C85F6EC0",
          LookAt = {
            [1] = "790060:n(790064)"
          },
          NextDialogue = 80040417,
          SpeakNpcId = 790060,
          Subtitle = "There's no real difference between us. So why do I always feel this deep need to protect you... as if it's simply part of who I am?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6EC0"
        },
        [80040417] = {
          Camera = "-34.588379,105.483887,14.617371,0.002332,-7.602717,-143.999451,35.000008,245.027496,false,DoNotOverride,1.824698",
          ContentES = "Ahora lo comprendo mejor... Quizá sea porque fuiste tú quien me enseñó todo esto.",
          DialogueId = 80040417,
          FacialId = {
            [1] = "790060:Satisfy01"
          },
          FinalCamera = "-18.903809,74.785156,19.733093,0.002335,-9.002653,-161.59935,35.000008,245.027496,false,DoNotOverride,1.824698",
          GUID = "C85F6EEA",
          LookAt = {
            [1] = "790060:n(790060)"
          },
          NextDialogue = 80040418,
          SpeakNpcId = 790060,
          Subtitle = "I think I'm starting to understand now... maybe it's because you taught me these things—",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6EEA"
        },
        [80040418] = {
          ContentES = "Al crecer junto a ti, pude comprender la naturaleza del ser humano. No somos máquinas que solo saben pelear y luchar. Cuando estamos contentos, reímos, cuando estamos tristes, lloramos.",
          DialogueId = 80040418,
          GUID = "C85F6F14",
          LookAt = {
            [1] = "790060:n(790064)"
          },
          NextDialogue = 80040419,
          Scripts = [[
PARA{
SEQ{PlayAnimation{ActorId{790060},AnimationId{"Sit_Talk03_Start"},Duration{3}},PlayAnimation{ActorId{790060},AnimationId{"Sit_Talk03_End"},Duration{1}}},
SEQ{
CameraMoveTo{_delay{12},TargetPosition{"-203.837402,256.402344,195.641724,0.002327,-15.208583,-19.810177,55.0,340.145996,false,DoNotOverride,2.993798"},duration{0}},
CameraMoveTo{TargetPosition{"-194.081055,279.682129,195.641724,0.00232,-16.008596,-24.409195,55.0,340.145996,false,DoNotOverride,2.993798"},duration{8}}
}
}]],
          SpeakNpcId = 790060,
          Subtitle = "Growing up with you, I learned that this is how people should live — we're not machines built for fighting and killing; we laugh when we're happy, and cry when sad.",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6F14"
        },
        [80040419] = {
          ContentES = "Cuando se tiene miedo, hay que gritar. Cuando se siente dolor, uno se recuesta en los brazos de alguien.",
          DialogueId = 80040419,
          GUID = "C85F6F3E",
          NextDialogue = 80040420,
          SpeakNpcId = 790060,
          Subtitle = "When we're scared, it's okay to shout out; when in pain, we should find comfort in someone's embrace.",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6F3E"
        },
        [80040420] = {
          Camera = "-70.148926,422.999512,371.254883,-10.013577,-40.206741,-59.274754,25.0,373.138092,false,Manual,2.993798",
          ContentES = "Luego, está <H>ella</>, ni sé si puedo llamarla “mamá”, y después estás tú...",
          DialogueId = 80040420,
          FinalCamera = "-76.626465,419.856934,370.308533,-10.014523,-40.206684,-52.074379,25.0,373.138092,false,Manual,2.993798",
          GUID = "C85F6F68",
          NextDialogue = 80040421,
          Scripts = "PlayAnimation{_delay{2},ActorId{790060},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790060,
          Subtitle = "There's her — don't know if I have the right to call her \"mother\" — and then there's you...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6F68"
        },
        [80040421] = {
          Camera = "35.807617,108.178223,86.479065,0.002307,17.391552,20.986578,35.000011,340.145996,false,DoNotOverride,22.0",
          ContentES = "Ustedes me hacen sentir que puedo vivir como una persona de verdad.",
          DialogueId = 80040421,
          FacialId = {
            [1] = "790060:Smile01"
          },
          FinalCamera = "46.60498,112.319824,90.100525,0.002307,17.391552,20.986578,35.000011,340.145996,false,DoNotOverride,22.0",
          GUID = "C85F6F92",
          NextDialogue = 80040422,
          SpeakNpcId = 790060,
          Subtitle = "The two of you made me feel like I could live like a real person.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6F92"
        },
        [80040422] = {
          Camera = "-23.915527,115.649414,25.067749,0.002335,-10.407589,-143.409561,35.000008,340.145996,false,DoNotOverride,22.0",
          ContentES = "Duerme,{nickname}. Yo cuidaré de ti durante la noche.",
          DialogueId = 80040422,
          FinalCamera = "-36.480957,106.318848,22.193542,0.002335,-10.407589,-143.409561,35.000008,340.145996,false,DoNotOverride,22.0",
          GUID = "C85F6FBC",
          NextDialogue = 80040423,
          SpeakNpcId = 790060,
          Subtitle = "...Sleep tight, . I'll keep watch over you tonight.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F6FBC"
        },
        [80040423] = {
          DialogueId = 80040423,
          Duration = 5,
          GUID = "C85F6FBD",
          IsBlack = 1,
          NextDialogue = 80040424,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/story_invite_monster_far_loop\"},EventKey{\"Invite_Heitao_Sound_Loop\"},PlayAs2D{true}}"
        },
        [80040424] = {
          Camera = "-93.630859,24.962891,220.886658,5.000505,-29.609524,35.775024,30.000008,274.119965,false,DoNotOverride,2.993798",
          ContentES = "Qué raro… ¿por qué esos Filthoids se volvieron locos de repente?",
          DialogueId = 80040424,
          FinalCamera = "-102.309082,35.967773,219.821167,5.000515,-29.609531,35.775021,30.000008,274.119965,false,DoNotOverride,2.993798",
          GUID = "C85F7010",
          LookAt = {
            [1] = "790060:p(BP_11010402_heitao)"
          },
          NextDialogue = 80040425,
          Scripts = "StopNormalSound{EventKey{\"Invite_Heitao_Sound_Loop\"}}",
          SpeakNpcId = 790060,
          Subtitle = "Something doesn't add up... why have those Filthoids suddenly gone berserk?",
          TalkActionId = {
            [1] = "790060:Sit_Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F7010"
        },
        [80040425] = {
          Camera = "-12.207031,335.27832,15.362854,0.002289,3.389604,-97.820328,30.0,346.472321,false,Manual,2.993798",
          ContentES = "Puede que tengas razón... Fui tonta al creer que, quedándome en la Isla del Purgatorio, podría evitar cualquier peligro.",
          DialogueId = 80040425,
          FacialId = {
            [1] = "790060:Satisfy01"
          },
          FinalCamera = "-26.918457,337.268066,15.362854,0.00229,3.389604,-95.620445,30.0,346.472321,false,Manual,2.993798",
          GUID = "C85F703A",
          NextDialogue = 80040426,
          SpeakNpcId = 790060,
          Subtitle = "Maybe you were right. It was naive of me to think staying on Purgatorio Island would keep us safe.",
          TalkActionId = {
            [1] = "790060:Sit_Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F703A"
        },
        [80040426] = {
          Camera = "3.683594,184.143555,95.722168,0.002534,-6.803585,-60.810005,30.000008,308.979584,false,DoNotOverride,2.993798",
          ContentES = "Seguir escondiéndonos aquí no es la solución... Si fueron capaces de encontrarnos una vez, lo harán de nuevo.",
          DialogueId = 80040426,
          FinalCamera = "-19.79834,171.027344,95.722656,0.002534,-6.803585,-60.810005,30.000008,308.979584,false,DoNotOverride,2.993798",
          GUID = "C85F7064",
          NextDialogue = 80040427,
          SpeakNpcId = 790060,
          Subtitle = "We can't keep hiding forever. They found us this time, and there'll be a next time.",
          TalkActionId = {
            [1] = "790060:Sit_Idle_Loop"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F7064"
        },
        [80040427] = {
          Camera = "-4.847656,66.36084,122.277466,0.002532,-4.803555,23.188864,30.000008,308.979584,false,DoNotOverride,2.993798",
          ContentES = "{nickname}, mañana, al despertar, nos iremos {性别:juntos|juntas}. Buscaremos ese vasto continente, lleno de libertad como tú dices...",
          DialogueId = 80040427,
          FinalCamera = "-4.847656,66.36084,122.277466,0.002534,-4.803555,30.58811,30.000013,308.979584,false,DoNotOverride,2.993798",
          GUID = "C85F708E",
          LookAt = {
            [1] = "790060:n(790060)"
          },
          NextDialogue = 80040428,
          SpeakNpcId = 790060,
          Subtitle = ", when you wake up tomorrow, let's leave this island. We'll find somewhere vast and free. Like you said—",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F708E"
        },
        [80040428] = {
          Camera = "-123.908203,78.151855,88.040039,0.002289,15.593007,19.590528,30.0,346.472321,false,DoNotOverride,2.993798",
          ContentES = "“Yo seré tu escudo, tú serás mi voz”.",
          DialogueId = 80040428,
          GUID = "C85F70B8",
          IsBlack = 1,
          NextDialogue = 80040429,
          SpeakNpcId = 790060,
          Subtitle = "\"I'll be your shield, and you'll be my voice.\"",
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F70B8"
        },
        [80040429] = {
          Camera = "-30.251465,18.105957,23.325562,0.00232,8.991138,-48.805122,20.0,346.472321,false,DoNotOverride,2.993798",
          ContentES = "No hay nada que temer... No existe nada que pueda asustarme.",
          DialogueId = 80040429,
          FinalCamera = "-9.417969,-5.694824,28.330261,0.00232,8.991138,-48.805122,20.0,346.472321,false,DoNotOverride,2.993798",
          GUID = "C85F70E2",
          IsBlack = 1,
          SpeakNpcId = 790060,
          Subtitle = "There's nothing to fear now — not anymore.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/004/C85F70E2"
        },
        [80050100] = {
          ContentES = "{性别:Sr.|Srta.} Unicornio, escuché que estás organizando una fiesta del té. También me gustaría asistir.",
          DialogueId = 80050100,
          GUID = "C865A388",
          Subtitle = "{性别:Mr|Miss} Unicorn, are you having a tea party? May I join you~?",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A388"
        },
        [80050101] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentES = "Hola, {性别:Sr.|Srta.} Unicornio. Acabo de recibir este increíble regalo por parte del Gran Mago. ¿Quieres verlo?",
          DialogueId = 80050101,
          GUID = "C865A3B2",
          NextOptions = {
            [1] = 80050102
          },
          SpeakNpcId = 790017,
          Subtitle = "Hello, {性别:Mr|Miss} Unicorn. I've just got this amazing gift from the Great Magician. Would you like to see it?",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A3B2"
        },
        [80050102] = {
          ContentES = "¿Qué es?",
          DialogueId = 80050102,
          GUID = "C865A3DC",
          NextDialogue = 80050103,
          Subtitle = "What is it?"
        },
        [80050103] = {
          ContentES = "Ah, ¡son bloques de construcción!",
          DialogueId = 80050103,
          GUID = "C865A406",
          NextDialogue = 80050104,
          SpeakNpcId = 790017,
          Subtitle = "It's a box of building blocks.",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A406"
        },
        [80050104] = {
          ContentES = "A simple vista los bloques de construcción parecen todos iguales, pero si te fijas con atención, cada uno tiene una forma, un color y un patrón diferente.",
          DialogueId = 80050104,
          GUID = "C865A430",
          NextDialogue = 80050105,
          SpeakNpcId = 790017,
          Subtitle = "Look at these blocks — they might look similar at first glance, but if you look closely, you'll see that each one has a unique shape, colour, and pattern!",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A430"
        },
        [80050105] = {
          ContentES = "Los conté. ¡Deben de haber más de una docena de bloques diferentes!",
          DialogueId = 80050105,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865A45A",
          NextOptions = {
            [1] = 80050106
          },
          SpeakNpcId = 790017,
          Subtitle = "I've counted — there are over a dozen different types here!",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A45A"
        },
        [80050106] = {
          ContentES = "¿No son casquillos de bala?",
          DialogueId = 80050106,
          GUID = "C865A484",
          NextDialogue = 80050107,
          Subtitle = "Aren't these actually spent casings?"
        },
        [80050107] = {
          ContentES = "¿Casquillos de bala? Con que así se llaman... Sí que sabes mucho, gracias por decírmelo. Ahora, déjame mostrarte cómo apilarlos, ¡es muy divertido!",
          DialogueId = 80050107,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865A4AE",
          NextDialogue = 80050108,
          SpeakNpcId = 790017,
          Subtitle = "Spent casings... Is that what they're called? Wow, you know so much! Thanks for telling me. Now, let me show you how to stack them up — it's really fun!",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A4AE"
        },
        [80050108] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentES = "¡Mira! Al unirlos de esta manera, ¡se transforman en una minipistola!",
          DialogueId = 80050108,
          GUID = "C865A4D8",
          IsBlack = 1,
          NextDialogue = 80050109,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_gun\"},PlayAs2D{true}}",
          SpeakNpcId = 790017,
          Subtitle = "Watch this! If you put them together like this, it becomes a tiny pistol.",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A4D8"
        },
        [80050109] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentES = "Y así, se transforman en un enorme cañón... ¡BUUM!",
          DialogueId = 80050109,
          GUID = "C865A502",
          IsBlack = 1,
          NextDialogue = 80050110,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_cannon\"},PlayAs2D{true}}",
          SpeakNpcId = 790017,
          Subtitle = "And like this, it turns into a big cannon — BOOM!",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A502"
        },
        [80050110] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentES = "Ahora, mira. ¡Es un dirigible!",
          DialogueId = 80050110,
          GUID = "C865A52C",
          IsBlack = 1,
          NextOptions = {
            [1] = 80050111
          },
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_engine\"},PlayAs2D{true}}",
          SpeakNpcId = 790017,
          Subtitle = "Now, look — it's an airship!",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A52C"
        },
        [80050111] = {
          ContentES = "Fue Outsider quien te enseñó todo esto, ¿verdad?",
          DialogueId = 80050111,
          GUID = "C865A556",
          NextDialogue = 80050112,
          Subtitle = "It's Outsider who taught you all these, isn't it?"
        },
        [80050112] = {
          ContentES = "¡Sí! Me enseñó muchas formas geniales de juntarlos, como hacer un robot gigante que puede disparar misiles desde los hombros y que puede desplegar sus alas de la espalda.",
          DialogueId = 80050112,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865A580",
          NextDialogue = 80050113,
          SpeakNpcId = 790017,
          Subtitle = "Yes! He showed me lots of cool ways to put them together, like making a giant robot that can shoot missiles from its shoulders and has wings on its back—",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A580"
        },
        [80050113] = {
          ContentES = "¡Ah! ¡Y también puede lanzar sus puños como misiles! ¡Te lo mostraré!",
          DialogueId = 80050113,
          GUID = "C865A5AA",
          NextDialogue = 80050114,
          SpeakNpcId = 790017,
          Subtitle = "Oh! And the fists — they can launch too! I'll show you!",
          TalkActionId = {
            [1] = "790017:Give"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A5AA"
        },
        [80050114] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          DialogueId = 80050114,
          GUID = "C865A5AB",
          IsBlack = 1,
          NextDialogue = 80050115,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_punch\"},PlayAs2D{true}}"
        },
        [80050115] = {
          ContentES = "Aunque tiene su truco… Pfiu, ¡pero ya está listo!",
          DialogueId = 80050115,
          GUID = "C865A5FE",
          NextDialogue = 80050116,
          SpeakNpcId = 790017,
          Subtitle = "It's a bit tricky though... Whew, there it is!",
          TalkActionId = {
            [1] = "790017:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A5FE"
        },
        [80050116] = {
          ContentES = "¡No tenía idea de que los casquillos usados pudieran ser tan divertidos! Déjame ver.",
          DialogueId = 80050116,
          GUID = "C865A628",
          NextDialogue = 80050117,
          SpeakNpcId = 100001,
          Subtitle = "I had no idea that spent casings could be this fun. Let me see it.",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A628"
        },
        [80050117] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          DialogueId = 80050117,
          GUID = "C865A629",
          IsBlack = 1,
          NextDialogue = 80050118,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/break_bullet_building\"},PlayAs2D{true}}"
        },
        [80050118] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentES = "¡Uy! ¡Se cayó…!",
          DialogueId = 80050118,
          GUID = "C865A67C",
          IsBlack = 1,
          NextDialogue = 80050119,
          SpeakNpcId = 100001,
          Subtitle = "Um, it collapsed...",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A67C"
        },
        [80050119] = {
          ContentES = "Ay…",
          DialogueId = 80050119,
          FacialId = {
            [1] = "790017:Sad02"
          },
          GUID = "C865A6A6",
          NextOptions = {
            [1] = 80050120
          },
          SpeakNpcId = 790017,
          Subtitle = "Ah...",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A6A6"
        },
        [80050120] = {
          ContentES = "¡No estés triste! Te lo compensaré con otra cosa.",
          DialogueId = 80050120,
          GUID = "C865A6D0",
          NextDialogue = 80050121,
          Subtitle = "Sorry... please don't cry! I'll make it up to you with something else."
        },
        [80050121] = {
          ContentES = "Hmm… déjame pensarlo...",
          DialogueId = 80050121,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865A6FA",
          NextDialogue = 80050122,
          SpeakNpcId = 790017,
          Subtitle = "Hmm...",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A6FA"
        },
        [80050122] = {
          ContentES = "Ya sé. ¿Podrías concederme cuatro deseos, {性别:Sr.|Srta.} Unicornio? Dicen que los unicornios cumplen deseos, ¡y estoy segura de que tú también puedes!",
          DialogueId = 80050122,
          GUID = "C865A724",
          NextOptions = {
            [1] = 80050123,
            [2] = 80050124,
            [3] = 80050125
          },
          SpeakNpcId = 790017,
          Subtitle = "Then could you grant me four wishes, {性别:Mr|Miss} Unicorn? They say unicorns make people's wishes come true, and I'm sure you can too!",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A724"
        },
        [80050123] = {
          ContentES = "Por supuesto, cualquier cosa que esté dentro de mis posibilidades.",
          DialogueId = 80050123,
          GUID = "C865A74E",
          NextDialogue = 80050126,
          Subtitle = "Absolutely, anything within my powers."
        },
        [80050124] = {
          ContentES = "Tengo la sensación de que me estás estafando…",
          DialogueId = 80050124,
          GUID = "C865A778",
          NextDialogue = 80050126,
          Subtitle = "Am I being ripped off...?"
        },
        [80050125] = {
          ContentES = "¿No se supone que son solo tres deseos? ¡¿Cómo que cuatro?!",
          DialogueId = 80050125,
          GUID = "C865A7A2",
          NextDialogue = 80050126,
          Subtitle = "Isn't the standard three wishes? Why do you get four?"
        },
        [80050126] = {
          ContentES = "Jeje…",
          DialogueId = 80050126,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865A7CC",
          NextOptions = {
            [1] = 80050127
          },
          SpeakNpcId = 790017,
          Subtitle = "Hehe...",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A7CC"
        },
        [80050127] = {
          ContentES = "Bueno, ¿y cuál es el primer deseo?",
          DialogueId = 80050127,
          GUID = "C865A7F6",
          NextDialogue = 80050128,
          Subtitle = "What's your first wish then?"
        },
        [80050128] = {
          ContentES = "¡Quiero aprender magia! Sé lo básico, pero no sé cómo usarla de verdad… {性别:Sr.|Srta.} Unicornio, ¿podrías enseñarme?",
          DialogueId = 80050128,
          FacialId = {
            [1] = "790017:Smile02"
          },
          GUID = "C865A820",
          NextOptions = {
            [1] = 80050129,
            [2] = 80050132
          },
          SpeakNpcId = 790017,
          Subtitle = "I want to learn magic! I know a little bit of the basics, but I don't know how to actually use it... {性别:Mr|Miss} Unicorn, can you teach me?",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A820"
        },
        [80050129] = {
          ContentES = "¿Por qué no le pides a Outsider que te enseñe?",
          DialogueId = 80050129,
          GUID = "C865A84A",
          NextDialogue = 80050130,
          Subtitle = "Why don't you ask Outsider to teach you?"
        },
        [80050130] = {
          ContentES = "Él no quiere… Y tampoco me deja leer los libros de magia, los puso en un estante alto, aunque me ponga de puntitas no los alcanzo. A veces apilo sillas para agarrar un libro cuando él no está… Oh, ¡por favor que esto quede entre nosotros!",
          DialogueId = 80050130,
          GUID = "C865A874",
          NextDialogue = 80050131,
          SpeakNpcId = 790017,
          Subtitle = "He wouldn't... and he wouldn't let me read the magic books either — he put them up on a tall shelf, way out of my reach.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A874"
        },
        [80050131] = {
          ContentES = "Solo puedo aprovechar cuando él no está para apilar los taburetes y tomar los libros a escondidas… ¡Ah, cierto, cierto! ¡No se lo vayas a contar a nadie!",
          DialogueId = 80050131,
          GUID = "C865A89E",
          NextDialogue = 80050138,
          SpeakNpcId = 790017,
          Subtitle = "I sometimes stack chairs to sneak a book when he's not around — oh, please keep this just between us!",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A89E"
        },
        [80050132] = {
          ContentES = "¡Tendré que cobrarte por esto!",
          DialogueId = 80050132,
          GUID = "C865A8C8",
          NextDialogue = 80050133,
          Subtitle = "I usually charge for lessons."
        },
        [80050133] = {
          ContentES = "¿Eh? Em… ¿te serviría un frasco grande lleno de malvaviscos?",
          DialogueId = 80050133,
          FacialId = {
            [1] = "790017:Shock02"
          },
          GUID = "C865A8F2",
          NextDialogue = 80050134,
          SpeakNpcId = 790017,
          Subtitle = "Huh? Um... would a big jar of marshmallows cover it?",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A8F2"
        },
        [80050134] = {
          ContentES = "Pero como es un deseo para Fina, hagámoslo gratis.",
          DialogueId = 80050134,
          GUID = "C865A91C",
          NextDialogue = 80050135,
          SpeakNpcId = 100001,
          Subtitle = "But since it's Fina's wish, let's make it free.",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A91C"
        },
        [80050135] = {
          ContentES = "¡Genial!",
          DialogueId = 80050135,
          FacialId = {
            [1] = "790017:Happy01"
          },
          GUID = "C865A946",
          NextDialogue = 80050136,
          SpeakNpcId = 790017,
          Subtitle = "Yay!",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A946"
        },
        [80050136] = {
          ContentES = "¡Muchas gracias! Outsider no quiso enseñarme… Y tampoco me deja leer los libros de magia. Los puso en un estante alto, aunque me ponga de puntitas no los alcanzo.",
          DialogueId = 80050136,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865A970",
          NextDialogue = 80050137,
          SpeakNpcId = 790017,
          Subtitle = "Thank you so much! Outsider wouldn't teach me... and he wouldn't let me read the magic books either — he put them up on a tall shelf, way out of my reach.",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A970"
        },
        [80050137] = {
          ContentES = "Solo puedo aprovechar cuando él no está para apilar los taburetes y tomar los libros a escondidas… ¡Ah, cierto, cierto! ¡No se lo vayas a contar a nadie!",
          DialogueId = 80050137,
          GUID = "C865A99A",
          NextDialogue = 80050138,
          SpeakNpcId = 790017,
          Subtitle = "I sometimes stack chairs to sneak a book when he's not around — oh, please keep this just between us!",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A99A"
        },
        [80050138] = {
          ContentES = "Él siempre dice que aprender magia significa abandonar la comodidad del hogar, alejarse de la cálida chimenea para adentrarse en un páramo frío y desolado...",
          DialogueId = 80050138,
          GUID = "C865A9C4",
          NextDialogue = 80050139,
          SpeakNpcId = 790017,
          Subtitle = "He always says that learning magic means leaving one's cosy home, away from the warm fireplace, to trudge through the barren, harsh wilderness...",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A9C4"
        },
        [80050139] = {
          ContentES = "Un lugar donde viven lobos de nieve con ojos verdes aterradores, y brujas del pantano en escobas con capas que gotean veneno.",
          DialogueId = 80050139,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865A9EE",
          NextOptions = {
            [1] = 80050140,
            [2] = 80050143
          },
          SpeakNpcId = 790017,
          Subtitle = "And there will be snow wolves with terrifying green eyes, and swamp witches on brooms, their cloaks dripping with poison.",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A9EE"
        },
        [80050140] = {
          ContentES = "No es para tanto, solo trata de asustarte.",
          DialogueId = 80050140,
          GUID = "C865AA18",
          NextDialogue = 80050141,
          Subtitle = "He was just exaggerating to frighten you. It's not that scary."
        },
        [80050141] = {
          ContentES = "Ah… ¡lo sabía! Solo teme que me enferme o me haga daño.. Pero ¿y si nunca mejoro…? No quiero quedarme todo el día en casa, tirada en la cama sin hacer nada... y no ser más que una carga para él.",
          DialogueId = 80050141,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865AA42",
          NextDialogue = 80050142,
          SpeakNpcId = 790017,
          Subtitle = "Ah... I knew it! He's worried I might get sick or hurt. But what if I never get better...? I don't want to just lie in bed all day, being a burden to him.",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AA42"
        },
        [80050142] = {
          ContentES = "Quiero ser útil. No quiero que me menosprecien nunca más.",
          DialogueId = 80050142,
          GUID = "C865AA6C",
          NextDialogue = 80050145,
          SpeakNpcId = 790017,
          Subtitle = "...I want to be helpful. I don't want to be looked down upon anymore.",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AA6C"
        },
        [80050143] = {
          ContentES = "En realidad, hay cosas más aterradoras que los lobos de nieve y las brujas del pantano.",
          DialogueId = 80050143,
          GUID = "C865AA96",
          NextDialogue = 80050144,
          Subtitle = "Actually, there are things scarier than snow wolves and swamp witches."
        },
        [80050144] = {
          ContentES = "Si ese es el caso… definitivamente no puedo dejar que vayan solos. Necesito dominar la magia para ayudarlos.",
          DialogueId = 80050144,
          GUID = "C865AAC0",
          NextDialogue = 80050145,
          SpeakNpcId = 790017,
          Subtitle = "If that's the case... I definitely can't let you go by yourselves. I need to master magic to help you.",
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AAC0"
        },
        [80050145] = {
          ContentES = "Así que, ¿podrías enseñarme, por favor? ¡Prometo que no se lo diré a nadie!",
          DialogueId = 80050145,
          FacialId = {
            [1] = "790017:Confident02"
          },
          GUID = "C865AAEA",
          NextOptions = {
            [1] = 80050146
          },
          SpeakNpcId = 790017,
          Subtitle = "So, could you teach me, please? I promise I won't tell anyone!",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AAEA"
        },
        [80050146] = {
          ContentES = "De acuerdo, empecemos a practicar ahora.",
          DialogueId = 80050146,
          GUID = "C865AB14",
          NextDialogue = 80050147,
          Subtitle = "Alright, let's start practising now."
        },
        [80050147] = {
          ContentES = "¡Yeii! ¡Eres {性别:el Sr.|la Srta.} Unicornio más amable y dulce del mundo entero!",
          DialogueId = 80050147,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865AB3E",
          SpeakNpcId = 790017,
          Subtitle = "Yay! You're the kindest and sweetest {性别:Mr|Miss} Unicorn in the whole world!",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AB3E"
        },
        [80050201] = {
          Camera = "364.267578,-629.911316,141.387695,0.0,0.0,123.199776,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mi segundo deseo es que {性别:el Sr.|la Srta.} Unicornio me lleve en secreto fuera de la ciudad para ver las estrellas de verdad.",
          DialogueId = 80050201,
          Duration = 5,
          GUID = "C865B41A",
          IsBlack = 1,
          NextDialogue = 80050202,
          Scripts = "PlayAnimation{_click{false},_delay{5},ActorId{790017},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 790017,
          Subtitle = "My second wish is for {性别:Mr|Miss} Unicorn to secretly take me out of the city to see the real stars.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B41A"
        },
        [80050202] = {
          Camera = "198.488281,-216.339706,-7.433838,0.000016,4.399113,131.781357,18.0,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "El cielo es tan vasto y lejano, y las estrellas tan brillantes… Es todo tan hermoso…",
          DialogueId = 80050202,
          FinalCamera = "164.765625,-177.972809,-5.608887,0.000038,26.398823,132.182083,18.0,100000.0,false,DoNotOverride,22.0",
          GUID = "C865B444",
          NextDialogue = 80050203,
          SpeakNpcId = 790017,
          Subtitle = "The sky is so vast and distant, and the stars are so bright... it's all so beautiful...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B444"
        },
        [80050203] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "En la ciudad, incluso en noches despejadas, solo se puede ver un pedacito de cielo por culpa de los edificios y los muros.",
          DialogueId = 80050203,
          GUID = "C865B46E",
          NextDialogue = 80050204,
          SpeakNpcId = 790017,
          Subtitle = "In the city, even on clear nights, you can only see a small patch of the sky because of the buildings and city walls.",
          TurnTo = {
            [1] = "790017:n(100001)",
            [2] = "100001:n(790017)"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B46E"
        },
        [80050204] = {
          ContentES = "La lámpara de estrellas que me dio Outsider es muy bonita, pero… no hay nada como ver el cielo estrellado de verdad… ¡achís!",
          DialogueId = 80050204,
          GUID = "C865B498",
          NextOptions = {
            [1] = 80050205,
            [2] = 80050206
          },
          SpeakNpcId = 790017,
          Subtitle = "The star lamp Outsider gave me is pretty, but there's nothing like the real starry sky... achoo!",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B498"
        },
        [80050205] = {
          ContentES = "Ten cuidado, no vayas a resfriarte.",
          DialogueId = 80050205,
          GUID = "C865B4C2",
          NextDialogue = 80050207,
          Subtitle = "Be careful not to catch a cold."
        },
        [80050206] = {
          ContentES = "Ponte detrás de mí, te cubriré del viento.",
          DialogueId = 80050206,
          GUID = "C865B4EC",
          NextDialogue = 80050207,
          Subtitle = "Stand behind me, I'll shield you from the wind."
        },
        [80050207] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Estoy bien, de verdad. Si no me crees puedes tocar mi mano, ¡está calientita! Me gustaría quedarme un rato más…",
          DialogueId = 80050207,
          GUID = "C865B516",
          NextDialogue = 80050208,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}},PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"Talk02_Start\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "I'm okay, really. You can feel my palm. It's quite warm! I'd like to stay out a little longer...",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B516"
        },
        [80050208] = {
          Camera = "-370.169922,731.447144,106.094727,0.000026,35.394604,129.986496,18.0,100000.0,false,DoNotOverride,22.0",
          ContentES = "¡Mira! Esas estrellas de allá, juntas parecen un conejito, ¿no?",
          DialogueId = 80050208,
          GUID = "C865B540",
          NextOptions = {
            [1] = 80050209,
            [2] = 80050211,
            [3] = 80050214
          },
          SpeakNpcId = 790017,
          Subtitle = "Look! Those stars over there, they look like a bunny together, don't they?",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B540"
        },
        [80050209] = {
          ContentES = "Sí, sí parecen.",
          DialogueId = 80050209,
          GUID = "C865B56A",
          NextDialogue = 80050210,
          Subtitle = "Yes, they do."
        },
        [80050210] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Jeje. Esta noche inventaré una historia sobre las maravillosas aventuras de un conejito que vive en las estrellas.",
          DialogueId = 80050210,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865B594",
          NextOptions = {
            [1] = 80050217
          },
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Confident_Start\"},Duration{2}},PlayAnimation{_delay{3},ActorId{790017},AnimationId{\"Confident_End\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "Hehe. Then I'll make up a story about a little bunny's marvelous adventures among the stars tonight.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B594"
        },
        [80050211] = {
          ContentES = "Parecen más un muslo de pollo grande.",
          DialogueId = 80050211,
          GUID = "C865B5BE",
          NextDialogue = 80050212,
          Subtitle = "They look more like a big drumstick."
        },
        [80050212] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh?... No lo veo. ¿No será más bien que tienes hambre?",
          DialogueId = 80050212,
          FacialId = {
            [1] = "790017:Shock01"
          },
          GUID = "C865B5E8",
          NextDialogue = 80050213,
          SpeakNpcId = 790017,
          Subtitle = "Huh? ...I don't see it. Are you hungry?",
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B5E8"
        },
        [80050213] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es broma. De todas formas, tengo curiosidad...",
          DialogueId = 80050213,
          GUID = "C865B612",
          NextOptions = {
            [1] = 80050217
          },
          SpeakNpcId = 100001,
          Subtitle = "Just kidding. Anyway, I'm curious—",
          TalkActionId = {
            [1] = "790017:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B612"
        },
        [80050214] = {
          ContentES = "Parecen más bien un delfín con unos pantalones en la cabeza.",
          DialogueId = 80050214,
          GUID = "C865B63C",
          NextDialogue = 80050215,
          Subtitle = "They look more like a dolphin wearing pants on its head."
        },
        [80050215] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? ¿En seeerio? ¡No logro imaginarlo...!",
          DialogueId = 80050215,
          FacialId = {
            [1] = "790017:Shock01"
          },
          GUID = "C865B666",
          NextDialogue = 80050216,
          SpeakNpcId = 790017,
          Subtitle = "Huh? Wh—What's that?! I can't picture it...",
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B666"
        },
        [80050216] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es broma. De todas formas, tengo curiosidad...",
          DialogueId = 80050216,
          GUID = "C865B690",
          NextOptions = {
            [1] = 80050217
          },
          SpeakNpcId = 100001,
          Subtitle = "Just kidding. Anyway, I'm curious—",
          TalkActionId = {
            [1] = "790017:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B690"
        },
        [80050217] = {
          ContentES = "Fina, ¿por qué te gusta mirar tanto las estrellas?",
          DialogueId = 80050217,
          GUID = "C865B6BA",
          NextDialogue = 80050218,
          Subtitle = "Why do you like seeing the stars so much, Fina?"
        },
        [80050218] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hace mucho tiempo, mi mamá me contó una historia sobre un pajarito que se convirtió en una estrella… Es mi favorita, y ahora quiero contártela a ti también.",
          DialogueId = 80050218,
          GUID = "C865B6E4",
          NextDialogue = 80050219,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "A long time ago, my mom told me a story about a little bird that turned into a star... It's my favourite, and I'd love to share it with you.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B6E4"
        },
        [80050219] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Este pajarito no era como los demás: tenía plumas feas, un canto desagradable, y sus garras y pico no eran tan fuertes como el de los otros pajaritos. Los otros pájaros no lo querían, siempre lo molestaban y trataban de echarlo.",
          DialogueId = 80050219,
          GUID = "C865B70E",
          NextDialogue = 80050220,
          Scripts = "PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 790017,
          Subtitle = "This bird wasn't like the others: she had ugly feathers, a jarring song, and her claws and beak were not sharp. The other birds didn't like her, always bullying her, trying to chase her away.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B70E"
        },
        [80050220] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero este pequeño pajarito anhelaba el cielo estrellado. Le suplicaba a las estrellas que lo llevaran para unirse a ellas, aunque eso significara perecer en su caliente resplandor.",
          DialogueId = 80050220,
          GUID = "C865B738",
          NextOptions = {
            [1] = 80050221
          },
          SpeakNpcId = 790017,
          Subtitle = "Yet, this little bird yearned for the starry sky. She prayed to the stars, wishing for a chance to join them, even if it meant perishing in their fiery glow.",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B738"
        },
        [80050221] = {
          ContentES = "¿Las estrellas le cumplieron su deseo?",
          DialogueId = 80050221,
          GUID = "C865B762",
          NextDialogue = 80050222,
          Subtitle = "So the stars answered her prayers?"
        },
        [80050222] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No… Algunas estrellas lo ignoraban, mientras que otras se burlaban de su atrevimiento. Un pequeño pajarito feo soñando con surcar el hermoso cielo estrellado, ¡qué ridículo!",
          DialogueId = 80050222,
          GUID = "C865B78C",
          NextOptions = {
            [1] = 80050223
          },
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain01_End\"},Duration{2}},PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "No... Some stars ignored her, while some mocked her for overreaching: a plain little bird dreaming of soaring through the beautiful starry sky, how ridiculous.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B78C"
        },
        [80050223] = {
          ContentES = "¿Qué pasó después?",
          DialogueId = 80050223,
          GUID = "C865B7B6",
          NextDialogue = 80050224,
          Subtitle = "What happened then?"
        },
        [80050224] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Decidió no depositar sus esperanzas en los demás. Se despidió de su familia y voló solo hacia el cielo nocturno.",
          DialogueId = 80050224,
          GUID = "C865B7E0",
          NextDialogue = 80050225,
          SpeakNpcId = 790017,
          Subtitle = "She decided not to pin her hopes on others. Bidding farewell to her family, she flew toward the night sky alone.",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B7E0"
        },
        [80050225] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Voló cada vez más alto, y el cielo se volvía cada vez más frío. Al final, se congeló, y ya no pudo batir sus alas de nuevo...",
          DialogueId = 80050225,
          GUID = "C865B80A",
          NextOptions = {
            [1] = 80050226
          },
          SpeakNpcId = 790017,
          Subtitle = "The higher she flew, the colder the sky became; eventually, she froze, never to flap her wings again.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B80A"
        },
        [80050226] = {
          ContentES = "Es un final muy triste....",
          DialogueId = 80050226,
          GUID = "C865B834",
          NextDialogue = 80050227,
          Subtitle = "...That's quite a sad ending."
        },
        [80050227] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Espera, ese no es el final. Mientras el pajarito yacía congelado, de pronto se dio cuenta de algo: su cuerpo estallaba silenciosamente en llamas, como si se estuviera convirtiendo en una <H>estrella de verdad</>.",
          DialogueId = 80050227,
          GUID = "C865B85E",
          NextDialogue = 80050228,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain01_Start\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"Explain01_End\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "No, that's not the end. As the little bird lay frozen, she suddenly realised something: her plain body began to quietly burst into radiant flames, just like a shining star in the sky.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B85E"
        },
        [80050228] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Y sí! ¡Se convirtió en una estrella de verdad!",
          DialogueId = 80050228,
          GUID = "C865B888",
          NextDialogue = 80050229,
          SpeakNpcId = 790017,
          Subtitle = "That's right — she became a star herself!",
          TalkActionId = {
            [1] = "790017:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B888"
        },
        [80050229] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Esa era la historia. ¿Te gusta, {性别:el Sr.|la Srta.} Unicornio?",
          DialogueId = 80050229,
          GUID = "C865B8B2",
          LookAt = {
            [1] = "790017:p(180102P)"
          },
          NextOptions = {
            [1] = 80050230,
            [2] = 80050232
          },
          SpeakNpcId = 790017,
          Subtitle = "And that's my story. Do you like it, {性别:Mr|Miss} Unicorn?",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B8B2"
        },
        [80050230] = {
          ContentES = "Me gustó la historia. Es muy bonita.",
          DialogueId = 80050230,
          GUID = "C865B8DC",
          NextDialogue = 80050231,
          Subtitle = "I love it. It's a beautiful story."
        },
        [80050231] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ese pajarito es muy valiente, incluso más de lo que imaginaba. Me gustó mucho su historia.",
          DialogueId = 80050231,
          GUID = "C865B906",
          LookAt = {
            [1] = "790017:n(100001)"
          },
          NextDialogue = 80050235,
          SpeakNpcId = 100001,
          Subtitle = "I love it. That little bird was much braver than I expected.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B906"
        },
        [80050232] = {
          ContentES = "Qué triste historia, no me gustó.",
          DialogueId = 80050232,
          GUID = "C865B930",
          NextDialogue = 80050233,
          Subtitle = "I didn't like it. It's too sad."
        },
        [80050233] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Creo que el pajarito no tenía por qué sacrificarse… Pareciera más como un simple escape, una evasión a la injusticia. Debería haber luchado.",
          DialogueId = 80050233,
          GUID = "C865B95A",
          LookAt = {
            [1] = "790017:n(100001)"
          },
          NextDialogue = 80050234,
          SpeakNpcId = 100001,
          Subtitle = "The little bird shouldn't have had to sacrifice herself... It was an evasion of real injustice. She should've fought back.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B95A"
        },
        [80050234] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ya veo… bueno, esa sí sería una historia totalmente diferente.",
          DialogueId = 80050234,
          GUID = "C865B984",
          NextDialogue = 80050235,
          SpeakNpcId = 790017,
          Subtitle = "I see... well, that would indeed be a completely different story.",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B984"
        },
        [80050235] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 80050235,
          GUID = "C865B9AE",
          LookAt = {
            [1] = "790017:p(180102P)"
          },
          NextDialogue = 80050236,
          SpeakNpcId = 790017,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B9AE"
        },
        [80050236] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Quizás algún día yo también pueda convertirme en un pajarito.",
          DialogueId = 80050236,
          GUID = "C865B9D8",
          LookAt = {
            [1] = "790017:n(790017)"
          },
          NextOptions = {
            [1] = 80050237
          },
          SpeakNpcId = 790017,
          Subtitle = "Do you think I can be like that little bird someday?",
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B9D8"
        },
        [80050237] = {
          ContentES = "La familia del pajarito se sentiría triste...",
          DialogueId = 80050237,
          GUID = "C865BA02",
          NextDialogue = 80050238,
          Subtitle = "...The little bird's family would be devastated."
        },
        [80050238] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah… eso nunca me lo había planteado.",
          DialogueId = 80050238,
          GUID = "C865BA2C",
          LookAt = {
            [1] = "790017:n(100001)"
          },
          NextDialogue = 80050239,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Sigh_End\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{1}}}",
          SpeakNpcId = 790017,
          Subtitle = "Ah... I hadn't thought of that.",
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BA2C"
        },
        [80050239] = {
          ContentES = "Siempre imaginé que su familia estaría orgullosa y feliz, porque brillaría tan intensamente en el cielo nocturno y hasta la eternidad.",
          DialogueId = 80050239,
          GUID = "C865BA56",
          NextDialogue = 80050240,
          SpeakNpcId = 790017,
          Subtitle = "I always imagined her family would be proud and happy for her because she would always shine so brightly in the night sky.",
          TalkActionId = {
            [1] = "790017:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BA56"
        },
        [80050240] = {
          ContentES = "Si lo extrañan, solo tienen que mirar al cielo en las noches sin nubes y saludarlo, tal como lo hacemos nosotros.",
          DialogueId = 80050240,
          GUID = "C865BA80",
          NextDialogue = 80050241,
          SpeakNpcId = 790017,
          Subtitle = "If they missed her, they could simply look up at the starry sky on cloudless nights and say hello, just as we have done.",
          TalkActionId = {
            [1] = "790017:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BA80"
        },
        [80050241] = {
          ContentES = "Pero me hiciste acordar… Desde que se convirtió en estrella, ya no puede hablar ni moverse. Su familia nunca podría alcanzarla, por muy lejos que caminaran.",
          DialogueId = 80050241,
          GUID = "C865BAAA",
          NextDialogue = 80050242,
          SpeakNpcId = 790017,
          Subtitle = "But you've made me realise that as a star, she could no longer speak or move. Her family would never be able to reach her, no matter how far they trekked.",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BAAA"
        },
        [80050242] = {
          ContentES = "¿Eso haría que su familia se sintiera triste? Necesito pensarlo un poco más...",
          DialogueId = 80050242,
          GUID = "C865BAD4",
          NextDialogue = 80050243,
          SpeakNpcId = 790017,
          Subtitle = "Would that make her family sad? I need to think about it...",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BAD4"
        },
        [80050243] = {
          ContentES = "Muchas gracias por hablar conmigo, {性别:Sr.|Srta.} Unicornio. Volvamos a casa.",
          DialogueId = 80050243,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865BAFE",
          SpeakNpcId = 790017,
          Subtitle = "Thank you for taking me out to see the stars tonight, {性别:Mr|Miss} Unicorn. Let's go home.",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865BAFE"
        },
        [80050301] = {
          Camera = "-220.272461,-361.613037,104.543945,0.0,0.0,64.200195,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mi tercer deseo es que {性别:el Sr.|la Srta.} Unicornio me lleve a lo alto de las murallas de Lago Helado.",
          DialogueId = 80050301,
          GUID = "C865C482",
          IsBlack = 1,
          NextDialogue = 80050302,
          SpeakNpcId = 790017,
          Subtitle = "My third wish is for {性别:Mr|Miss} Unicorn to take me up on the town walls of Icelake.",
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C482"
        },
        [80050302] = {
          Camera = "-58.240234,-248.958618,99.918945,0.000097,3.997675,105.603172,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Puf, puff, uff...",
          DialogueId = 80050302,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          FinalCamera = "-21.044922,-372.557251,86.48877,0.000079,4.397842,110.200386,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C4AC",
          NextOptions = {
            [1] = 80050303
          },
          SpeakNpcId = 790017,
          Subtitle = "Huff... huff... huff... huff...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C4AC"
        },
        [80050303] = {
          ContentES = "Más despacio, no corras tan rápido.",
          DialogueId = 80050303,
          GUID = "C865C4D6",
          NextDialogue = 80050304,
          Subtitle = "Take it easy, Fina."
        },
        [80050304] = {
          Camera = "-62.108398,71.224731,134.228027,0.000089,-8.600738,-108.702515,35.000011,332.46875,false,Manual,2.8",
          ContentES = "¡No pasa nada! ¡Mira, ahora estamos en el lugar más alto de Lago Helado! ¡Estamos en el cielo, como verdaderos pájaros!",
          DialogueId = 80050304,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865C500",
          NextDialogue = 80050305,
          SpeakNpcId = 790017,
          Subtitle = "I'm fine, look! We're now at the highest point of the outer city! It feels like we're birds soaring in the sky!",
          TurnTo = {
            [1] = "790017:n(100001)"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C500"
        }
      }
    end
