          NextDialogue = 80050410,
          SpeakNpcId = 790017,
          Subtitle = "That's okay, I'll teach you!",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D63A"
        },
        [80050410] = {
          ContentES = "No hay prisa, ¡lo haremos poco a poquito!",
          DialogueId = 80050410,
          FacialId = {
            [1] = "790017:Confident02"
          },
          GUID = "C865D664",
          NextDialogue = 80050411,
          SpeakNpcId = 790017,
          Subtitle = "No pressure, we'll figure it out together.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D664"
        },
        [80050411] = {
          ContentES = "Comencemos la primera historia con una aventura sencilla...",
          DialogueId = 80050411,
          GUID = "C865D68E",
          NextDialogue = 80050412,
          SpeakNpcId = 790017,
          Subtitle = "Let's start the first story with a simple adventure~",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D68E"
        },
        [80050412] = {
          ContentES = "Un día, la pequeña Ruiseñor y {性别:el Sr.|la Srta.} Unicornio emprendieron un viaje juntos.",
          DialogueId = 80050412,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D6B8",
          NextDialogue = 80050413,
          SpeakNpcId = 790017,
          Subtitle = "One day, Little Nightingale and {性别:Mr|Miss} Unicorn embarked on an adventure together...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D6B8"
        },
        [80050413] = {
          ContentES = "¿Solo ellos dos, no tienen compañeros?",
          DialogueId = 80050413,
          GUID = "C865D6E2",
          NextOptions = {
            [1] = 80050414,
            [2] = 80050416,
            [3] = 80050418
          },
          SpeakNpcId = 790017,
          Subtitle = "Was it just the two of them, or were there other friends?",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D6E2"
        },
        [80050414] = {
          ContentES = "Solo ellos dos.",
          DialogueId = 80050414,
          GUID = "C865D70C",
          NextDialogue = 80050415,
          Subtitle = "Just the two of them."
        },
        [80050415] = {
          ContentES = "Es su aventura secreta, solo de ellos dos.",
          DialogueId = 80050415,
          GUID = "C865D736",
          NextDialogue = 80050420,
          SpeakNpcId = 790017,
          Subtitle = "Then it'd be their very own secret adventure.",
