          SpeakNpcId = 790017,
          Subtitle = "After that, they...",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D92E"
        },
        [80050428] = {
          ContentES = "Descubrieron un cofre misterioso.",
          DialogueId = 80050428,
          GUID = "C865D958",
          NextDialogue = 80050429,
          Subtitle = "Discovered a mysterious treasure chest."
        },
        [80050429] = {
          ContentES = "¿Un cofre?… ¿Qué secretos guardará en su interior? ¿Monedas de plata, flores hermosas, o tiernos bloques de construcción?",
          DialogueId = 80050429,
          GUID = "C865D982",
          NextDialogue = 80050434,
          SpeakNpcId = 790017,
          Subtitle = "A chest...? What could be in it? Silver coins, pretty flowers, or finely made building blocks?",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D982"
        },
        [80050430] = {
          ContentES = "Hicieron nuevos amigos en un país lejano.",
          DialogueId = 80050430,
          GUID = "C865D9AC",
          NextDialogue = 80050431,
          Subtitle = "Made new friends in a foreign land."
        },
        [80050431] = {
          ContentES = "Así los compañeros de viaje aumentaron, y todo se volvió más divertido.",
          DialogueId = 80050431,
          GUID = "C865D9D6",
          NextDialogue = 80050434,
          SpeakNpcId = 790017,
          Subtitle = "That means more companions for the journey — the more, the merrier!",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D9D6"
        },
        [80050432] = {
          ContentES = "Se embelesaron ante el espléndido paisaje.",
          DialogueId = 80050432,
          GUID = "C865DA00",
          NextDialogue = 80050433,
          Subtitle = "Revelled in the spectacular scenery."
        },
        [80050433] = {
          ContentES = "Así es… el propósito de un viaje es descubrir paisajes hermosos.",
          DialogueId = 80050433,
          GUID = "C865DA2A",
          NextDialogue = 80050434,
          SpeakNpcId = 790017,
          Subtitle = "Right, going on an adventure is about seeing all those wonderful places in the world.",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DA2A"
        },
        [80050434] = {
          ContentES = "Al final, ellos...",
          DialogueId = 80050434,
          FacialId = {
            [1] = "790017:Confident01"
          },
          GUID = "C865DA54",
          NextOptions = {
            [1] = 80050435,
            [2] = 80050436,
            [3] = 80050437
          },
          SpeakNpcId = 790017,
          Subtitle = "In the end, they...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DA54"
        },
        [80050435] = {
          ContentES = "Regresaron a su tierra natal con muchísimos tesoros.",
          DialogueId = 80050435,
          GUID = "C865DA7E",
          NextDialogue = 80050438,
          Subtitle = "Returned home with a wealth of treasures."
        },
        [80050436] = {
          ContentES = "Vivieron días felices en otro próspero reino.",
          DialogueId = 80050436,
          GUID = "C865DAA8",
          NextDialogue = 80050438,
          Subtitle = "Settled down in another prosperous land and lived happily ever after."
        },
        [80050437] = {
          ContentES = "Derrotaron al temible rey demonio y se ganaron la admiración de todos.",
          DialogueId = 80050437,
          GUID = "C865DAD2",
          NextDialogue = 80050438,
          Subtitle = "Defeated the evil Demon Lord and became celebrated folk heroes."
        },
        [80050438] = {
          ContentES = "¡Así es! Entonces, así es como la historia…",
          DialogueId = 80050438,
          GUID = "C865DAFC",
          NextDialogue = 80050439,
          SpeakNpcId = 790017,
          Subtitle = "Right! So this is how the story...",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DAFC"
        },
        [80050439] = {
          ContentES = "Humm...",
          DialogueId = 80050439,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DB26",
          NextOptions = {
            [1] = 80050440
          },
          SpeakNpcId = 790017,
          Subtitle = "Hmm...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DB26"
        },
        [80050440] = {
          ContentES = "¿Pasa algo?",
          DialogueId = 80050440,
          GUID = "C865DB50",
          NextDialogue = 80050441,
          Subtitle = "What's wrong?"
        },
        [80050441] = {
          ContentES = "Siento que a la historia le falta algo…",
          DialogueId = 80050441,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865DB7A",
          NextDialogue = 80050442,
          SpeakNpcId = 790017,
          Subtitle = "I just feel like... there's something missing from our story...",
          TalkActionId = {
            [1] = "790017:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DB7A"
        },
        [80050442] = {
          ContentES = "...",
          DialogueId = 80050442,
          GUID = "C865DBA4",
          NextDialogue = 80050443,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBA4"
        },
        [80050443] = {
          ContentES = "Hemos creado una historia tan perfecta… Todos se ven tan alegres, tan contentos… ¿Qué podría estar faltando?",
          DialogueId = 80050443,
          GUID = "C865DBCE",
          NextDialogue = 80050444,
          SpeakNpcId = 790017,
          Subtitle = "It's such a perfect story, with a happy ending for everyone... What could possibly be missing?",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBCE"
        },
        [80050444] = {
          ContentES = "...",
          DialogueId = 80050444,
          GUID = "C865DBF8",
          NextDialogue = 80050445,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBF8"
        },
        [80050445] = {
          ContentES = "Creo que ya sé...",
          DialogueId = 80050445,
          GUID = "C865DC22",
          NextOptions = {
            [1] = 80050446,
            [2] = 80050447
          },
          SpeakNpcId = 100001,
          Subtitle = "I think I know.",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DC22"
        },
        [80050446] = {
          ContentES = "El problema con esta historia es que es demasiado “perfecta”.",
          DialogueId = 80050446,
          GUID = "C865DC4C",
          NextDialogue = 80050448,
          Subtitle = "The problem with this story is just being \"perfect.\""
        },
        [80050447] = {
          ContentES = "Lo que le falta es un toque de “pena”.",
          DialogueId = 80050447,
          GUID = "C865DC76",
          NextDialogue = 80050448,
          Subtitle = "What's missing from the story is \"regrets.\""
        },
        [80050448] = {
          ContentES = "Todo en esta historia es demasiado perfecto. No hay desafíos reales ni penas, todo sale tan bien que parece casi irreal.",
          DialogueId = 80050448,
          GUID = "C865DCA0",
          NextDialogue = 80050449,
          SpeakNpcId = 100001,
          Subtitle = "Everything in this story goes perfectly, doesn't it? Without any real challenges or regrets, it all feels almost unreal.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCA0"
        },
        [80050449] = {
          ContentES = "...",
          DialogueId = 80050449,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DCCA",
          NextDialogue = 80050450,
          SpeakNpcId = 790017,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCCA"
        },
        [80050450] = {
          ContentES = "Así es... Cuando era pequeña, las historias que me contaba mi mamá no solo eran felicidad y risas. También había penas y lágrimas.",
          DialogueId = 80050450,
          GUID = "C865DCF4",
          NextDialogue = 80050451,
          SpeakNpcId = 790017,
          Subtitle = "Right... When I was little, the stories my mother told weren't just about happiness and laughter. There would also be bad things and tears:",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCF4"
        },
        [80050451] = {
          ContentES = "Las princesas caían en sueños profundos, los valientes príncipes eran transformados en bestias, los niños eran llevados por malvados hechiceros, y los pajaritos se congelaban en el cielo nocturno…",
          DialogueId = 80050451,
          FacialId = {
            [1] = "790017:Sad01"
          },
          GUID = "C865DD1E",
          NextDialogue = 80050452,
          SpeakNpcId = 790017,
          Subtitle = "Beautiful princesses fell into deep slumbers, enchanted princes turned into beasts, children were taken by evil sorcerers, and little birds froze in the night sky...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD1E"
        },
        [80050452] = {
          ContentES = "Aunque los finales normalmente eran felices… ¿por qué tenían que experimentar tristeza primero? ¿Por qué no podían ser felices todo el tiempo?",
          DialogueId = 80050452,
          GUID = "C865DD48",
          NextOptions = {
            [1] = 80050453
          },
          SpeakNpcId = 790017,
          Subtitle = "Even though the endings were normally good... why must they experience sadness first? Why couldn't they be happy all the time?",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD48"
        },
        [80050453] = {
          ContentES = "Porque la vida es así.",
          DialogueId = 80050453,
          GUID = "C865DD72",
          NextDialogue = 80050454,
          Subtitle = "Because that's just how life is."
        },
        [80050454] = {
          ContentES = "Es justo como los malvaviscos que tanto te gustan. En un frasco tan grande, llamado vida, vienen en muchos y variados sabores: algunos son dulces, otros ácidos, y otros un poco amargos.",
          DialogueId = 80050454,
          GUID = "C865DD9C",
          NextDialogue = 80050455,
          SpeakNpcId = 100001,
          Subtitle = "Well, take your favourite marshmallows for example: They come in different flavours — some are sweet, some are sour, and some are even a bit bitter.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD9C"
        },
        [80050455] = {
          ContentES = "¡Mmm! Me encantan los que son muy dulces, y odio los amargos… como los de sabor mostaza. ¿Por qué alguien pondría mostaza en los malvaviscos?",
          DialogueId = 80050455,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865DDC6",
          NextDialogue = 80050456,
          SpeakNpcId = 790017,
          Subtitle = "Right! I love those sweet ones, and hate the bitter ones... no, the mustard flavour is the worst. Why would anyone put mustard in marshmallows!?",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DDC6"
        },
        [80050456] = {
          ContentES = "Cada vez que sin querer pruebo uno de mostaza, me hace llorar y tengo que comer uno dulce para quitarme el sabor. ¡El malvavisco dulce sabe aún más dulce así!....",
          DialogueId = 80050456,
          FacialId = {
            [1] = "790017:Syouganai01"
          },
          GUID = "C865DDF0",
          NextDialogue = 80050457,
          SpeakNpcId = 790017,
          Subtitle = "Every time I had one of those by mistake, it'd bring tears to my eyes, and I had to find a sweet one to get rid of the mustard taste in my mouth. What's funny is that the sweet taste would seem stronger—",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DDF0"
        },
        [80050457] = {
          ContentES = "Ah… ya entiendo… es por eso que existen los de sabor amargo, hacen que los de sabor dulce sepan aún más deliciosos.",
          DialogueId = 80050457,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865DE1A",
          NextDialogue = 80050458,
          SpeakNpcId = 790017,
          Subtitle = "Ah, I get it now... It's precisely because of the bitter and mustard-flavored ones that the sweet ones taste so good.",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE1A"
        },
        [80050458] = {
          ContentES = "...",
          DialogueId = 80050458,
          GUID = "C865DE44",
          NextDialogue = 80050459,
          SpeakNpcId = 790017,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE44"
        },
        [80050459] = {
          ContentES = "Y con las historias es igual, ¿verdad? Si no hubiera tristeza ni penas, entonces la felicidad no se sentiría así de valiosa…",
          DialogueId = 80050459,
          FacialId = {
            [1] = "790017:Shock02"
          },
          GUID = "C865DE6E",
          NextDialogue = 80050460,
          SpeakNpcId = 790017,
          Subtitle = "And it's the same with the stories, right? If there's no sadness or regrets, then happiness wouldn't feel as precious...",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE6E"
        },
        [80050460] = {
          ContentES = "Ah… así es… Ahora lo entiendo.",
          DialogueId = 80050460,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DE98",
          NextDialogue = 80050461,
          SpeakNpcId = 790017,
          Subtitle = "So that's how it is... I see.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE98"
        },
        [80050461] = {
          ContentES = "La historia que acabamos de escribir representa nuestro deseo más profundo. Pero una historia real, como nuestra vida, tiene tanto risas como lágrimas…",
          DialogueId = 80050461,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865DEC2",
          NextDialogue = 80050462,
          SpeakNpcId = 790017,
          Subtitle = "The story we just wrote stands for our fondest wish. But a real story, like our lives, has both laughter and tears...",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DEC2"
        },
        [80050462] = {
          ContentES = "Muchas gracias por hablar conmigo, {性别: Sr.|Srta.} Unicornio. Creo que necesitaré un poco más de tiempo…",
          DialogueId = 80050462,
          GUID = "C865DEEC",
          NextDialogue = 80050463,
          SpeakNpcId = 790017,
          Subtitle = "Thank you, {性别:Mr|Miss} Unicorn. I think I'll need more time...",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DEEC"
        },
        [80050463] = {
          ContentES = "Crecer, vivir, aprender y viajar... antes de que pueda terminar este libro de historias.",
          DialogueId = 80050463,
          GUID = "C865DF16",
          NextDialogue = 80050464,
          SpeakNpcId = 790017,
          Subtitle = "To grow, to live, to learn, and to travel — before I can finish this storybook.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DF16"
        },
        [80050464] = {
          ContentES = "¡Así que, {性别: Sr.|Srta.} Unicornio, todavía me debes un deseo!",
          DialogueId = 80050464,
          FacialId = {
            [1] = "790017:Confident01"
          },
          GUID = "C865DF40",
          NextOptions = {
            [1] = 80050465,
            [2] = 80050466
          },
          SpeakNpcId = 790017,
          Subtitle = "So, {性别:Mr|Miss} Unicorn, you still owe me that wish!",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DF40"
        },
        [80050465] = {
          ContentES = "Está bien, te lo prometo.",
          DialogueId = 80050465,
          GUID = "C865DF6A",
          NextDialogue = 80050467,
          Subtitle = "Sure, whenever you feel ready."
        },
        [80050466] = {
          ContentES = "Uf, me metí de lleno en esto, ¿verdad?",
          DialogueId = 80050466,
          GUID = "C865DF94",
          NextDialogue = 80050467,
          Subtitle = "Oof, I walked right into this, didn't I?"
        },
        [80050467] = {
          ContentES = "Jejeje, ¡llenemos este libro con historias maravillosas en el futuro!",
          DialogueId = 80050467,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865DFBE",
          SpeakNpcId = 790017,
          Subtitle = "Hehe, let's fill this book with wonderful stories in the future!",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DFBE"
        },
        [80060100] = {
          ContentES = "¡No hay nada más importante en el mundo que comer! A ver… ¿ya tienes la pancita bien llenita?",
          DialogueId = 80060100,
          GUID = "C86C0C28",
          Subtitle = "Nothing's more important than having a good meal! Lemme see if you've had your fill!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C28"
        },
        [80060101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "Mmm… Qué rico huele esta bebida hecha con pan. ¿Tú la hiciste? ¡Huele tan... tan rico!",
          DialogueId = 80060101,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C0C52",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextDialogue = 80060102,
          SpeakNpcId = 95101,
          Subtitle = "Mmm — this bread drink smells amazing! Did you make it yourself? You've really got a knack for this!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C52"
        },
        [80060102] = {
          ContentES = "Durante una ofrenda en la Iglesia Elysiana, una señora muy amable trajo una bebida de pan, hecha por ella misma. ¡Dijo que se demoró muchísimo en hacerla!",
          DialogueId = 80060102,
          GUID = "C86C0C7C",
          NextDialogue = 80060103,
          SpeakNpcId = 95101,
          Subtitle = "At one of our food drives, a kind-hearted lady brought along her homemade bread drink. She said it was quite the project!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C7C"
        },
        [80060103] = {
          ContentES = "Tienes que cortar el pan en trocitos, espolvorear un poquito de azúcar de malta, tostarlo hasta que quede bien calentito, y luego remojarlo para que agarre el sabor, hasta volverse una deliciosa espuma...",
          DialogueId = 80060103,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0CA6",
          NextDialogue = 80060104,
          SpeakNpcId = 95101,
          Subtitle = "You gotta chop up bread into bits, sprinkle on some sweet malt sugar, toast it till it's nice and warm, then soak it to let it ferment into a bubbly delight...",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0CA6"
        },
        [80060104] = {
          ContentES = "Mmm… Sabe igual de riquito que el de la señora.",
          DialogueId = 80060104,
          GUID = "C86C0CD0",
          NextOptions = {
            [1] = 80060105
          },
          Subtitle = "Mmm... this tastes just as good as the bread drink she made!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0CD0"
        },
        [80060105] = {
          ContentES = "¿Sabés como se prepara?",
          DialogueId = 80060105,
          GUID = "C86C0CFA",
          NextDialogue = 80060106,
          Subtitle = "Wow, you know how to make this? It's not a common drink."
        },
        [80060106] = {
          ContentES = "¡Je je! ¡Cualquier cosa que llene pancitas y haga felices a todos, yo sé prepararla!",
          DialogueId = 80060106,
          GUID = "C86C0D24",
          NextDialogue = 80060107,
          SpeakNpcId = 95101,
          Subtitle = "Mm-hmm, I know everything about keeping bellies full!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D24"
        },
        [80060107] = {
          ContentES = "¡Y no es por presumir! Pero prácticamente soy la enciclopedia gastronómica de Elysium. ¡No existe comida que la Comisaria de Provisiones, Truffle, no conozca!",
          DialogueId = 80060107,
          FacialId = {
            [1] = "95101:Confident02"
          },
          GUID = "C86C0D4E",
          NextDialogue = 80060108,
          SpeakNpcId = 95101,
          Subtitle = "I'm not bragging, you know — I'm like Elysium's walking encyclopedia of food! There's nothing about food that Commissary Truffle doesn't know!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D4E"
        },
        [80060108] = {
          ContentES = "Así que, si tienes cualquier duda sobre una comida, ¡puedes venir a preguntarme! Dónde están las verduras más ricas de la temporada o con qué se hace tal platillo… ¡No hay nada que Truffle no sepa!",
          DialogueId = 80060108,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0D78",
          NextOptions = {
            [1] = 80060109
          },
          SpeakNpcId = 95101,
          Subtitle = "So, any questions you've got about food — like where to find the best veggies in season right now, or what's in a certain dish — I've got all the answers!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D78"
        },
        [80060109] = {
          ContentES = "¿De verdad? ¿Puedes adivinar las frutas que acabas de beber?",
          DialogueId = 80060109,
          GUID = "C86C0DA2",
          NextDialogue = 80060110,
          Subtitle = "Really? Can you guess which fruits are in this drink?"
        },
        [80060110] = {
          ContentES = "Reto aceptado, ¡déjame probar otra vez! Mmm... ¡Es baya boreal! Pero las bayas que usaste todavía están un poquito ácidas, se volverían más dulces y jugosas un par de días después.",
          DialogueId = 80060110,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C0DCC",
          NextOptions = {
            [1] = 80060111
          },
          SpeakNpcId = 95101,
          Subtitle = "Challenge accepted~ Lemme have another sip! ...Mmm, borealberries! Though they are a bit tart right now; they'd become sweeter and juicier a couple of days later.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0DCC"
        },
        [80060111] = {
          ContentES = "Mmm… todavía hay otra baya que no has adivinado.",
          DialogueId = 80060111,
          GUID = "C86C0DF6",
          NextDialogue = 80060112,
          Subtitle = "You missed another berry, though."
        },
        [80060112] = {
          ContentES = "Sí… hay otro saborcito… tan familiar… déjame pensar… ya te digo…",
          DialogueId = 80060112,
          GUID = "C86C0E20",
          NextOptions = {
            [1] = 80060113
          },
          SpeakNpcId = 95101,
          Subtitle = "I know... Mmm, this taste is so familiar... just give me a moment...",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0E20"
        },
        [80060113] = {
          ContentES = "Ya que no puedes adivinarlo, te lo diré...",
          DialogueId = 80060113,
          GUID = "C86C0E4A",
          NextDialogue = 80060114,
          Subtitle = "Need a hint? It's—"
        },
        [80060114] = {
          ContentES = "¡Son gotas escarlatas! Son las que acabas de recoger esta mañana en el bosque, di que sí.",
          DialogueId = 80060114,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C0E74",
          NextOptions = {
            [1] = 80060115
          },
          SpeakNpcId = 95101,
          Subtitle = "—Vermilion Teardrops! Freshly picked this morning from the wild, right?",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0E74"
        },
        [80060115] = {
          ContentES = "Estás en lo cierto...",
          DialogueId = 80060115,
          GUID = "C86C0E9E",
          NextDialogue = 80060116,
          Subtitle = "Exactly right..."
        },
        [80060116] = {
          ContentES = "Jeje, no te sorprendas tanto, ¡no subestimes el paladar de Truffle! Junto con Filbert he probado toditito lo que puedas imaginar. No hay nada que se le escape a Truffle.",
          DialogueId = 80060116,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0EC8",
          NextDialogue = 80060117,
          SpeakNpcId = 95101,
          Subtitle = "Haha, why so surprised? It's no big deal. Filbert and I have tried EVERYTHING you can imagine — there's nothing unfamiliar to my taste buds.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0EC8"
        },
        [80060117] = {
          ContentES = "Las gotas escarlatas tienen un sabor ácido, como las ciruelas, así que combinan muy bien con bayas dulces. En cambio, los piñones tienen la cáscara muy durita, ¡pero el fruto seco de su interior es bastante tierno, crujiente y dulcecito!",
          DialogueId = 80060117,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C0EF2",
          NextDialogue = 80060118,
          SpeakNpcId = 95101,
          Subtitle = "Now, Vermilion Teardrops are a bit sour, like plums, so they go well with sweet berries; giant pine cones have tough shells, but the nuts inside are tender, crunchy, and sweet!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0EF2"
        },
        [80060118] = {
          ContentES = "Los zarcillos rampantes son así de feítos como se ven. La sabia que expulsan parece leche y huele a frutita. ¡Ni se te ocurra comerlo porque te dolerá la pancita...!",
          DialogueId = 80060118,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C0F1C",
          NextOptions = {
            [1] = 80060119,
            [2] = 80060122
          },
          SpeakNpcId = 95101,
          Subtitle = "Creeping Tendrils taste just as awful as they look; insulating sealant looks like milk and smells fruity, but if you eat it, you'll get a tummy ache... so never try it!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F1C"
        },
        [80060119] = {
          ContentES = "Por favor, dime que nunca has probado los tentáculos de Filthoid...",
          DialogueId = 80060119,
          GUID = "C86C0F46",
          NextDialogue = 80060120,
          Subtitle = "...Please tell me you've never tried Filthoid tentacles..."
        },
        [80060120] = {
          ContentES = "No, todavía no he probado esos. ¿Me pregunto a qué sabrán? Probablemente sean muy resbaladizos y elásticos… Quizás Filbert y yo lo descubramos juntas un día…",
          DialogueId = 80060120,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0F70",
          NextDialogue = 80060121,
          SpeakNpcId = 95101,
          Subtitle = "Nope, haven't gotten around to those. Wonder how they taste? Probably very slimy and chewy... Should Filbert and I try them out sometime...",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F70"
        },
        [80060121] = {
          ContentES = "Mmm, ¡paso! Aunque Filbert puede tumbar a los Filthoids pequeños, los grandes son bastante violentos. ¡No puedo poner a Filbert en peligro!",
          DialogueId = 80060121,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C0F9A",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          Subtitle = "Mm, pass! Though Filbert can knock over small Filthoids, those big ones are quite violent. I can't put Filbert in danger!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F9A"
        },
        [80060122] = {
          ContentES = "Es un milagro que hayas logrado mantenerte sana hasta ahora...",
          DialogueId = 80060122,
          GUID = "C86C0FC4",
          NextDialogue = 80060123,
          Subtitle = "It's a miracle you've managed to stay healthy growing up..."
        },
        [80060123] = {
          ContentES = "Sí, cuando era pequeñita, Filbert y yo nos la pasábamos por ahí, comíamos frutas venenosas y a veces nos daba dolor de pancita.",
          DialogueId = 80060123,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0FEE",
          NextDialogue = 80060124,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh. When I was little and wandering with Filbert, we occasionally nibbled on something poisonous and got sick.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0FEE"
        },
        [80060124] = {
          ContentES = "¡Pero no te preocupes! Ahora ya soy toda una experta en reconocer qué plantas se pueden comer o no.",
          DialogueId = 80060124,
          GUID = "C86C1018",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          Subtitle = "But don't worry! Now I'm quite the expert at identifying which plants are safe to munch on.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1018"
        },
        [80060125] = {
          ContentES = "¡¿Cómo has comido tantas cosas?!",
          DialogueId = 80060125,
          GUID = "C86C1042",
          NextDialogue = 80060126,
          Subtitle = "How come you've tried so many different \"foods\"?"
        },
        [80060126] = {
          ContentES = "Porque antes no había nada que comer. Cuando era muy, muy pequeñita, andaba sola por el mundo.",
          DialogueId = 80060126,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C106C",
          NextDialogue = 80060127,
          SpeakNpcId = 95101,
          Subtitle = "Because there was nothing much to eat. I started wandering alone at a very young age.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C106C"
        },
        [80060127] = {
          ContentES = "Desde pequeñita siempre he comido más que los demás. De vez en cuando había alguien amable que me regalaba golosinas, pero nunca quedaba llenita. Todos los días tenía mucha... mucha hambre.",
          DialogueId = 80060127,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1096",
          NextDialogue = 80060128,
          SpeakNpcId = 95101,
          Subtitle = "I've always been a big eater, so even though kind people sometimes gave me food, it was never enough — I was always hungry...",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1096"
        },
        [80060128] = {
          ContentES = "¡Ay, pero no pongas esa cara! Ya no estoy triste, porque poco después conocí a Filbert.",
          DialogueId = 80060128,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C10C0",
          NextDialogue = 80060129,
          SpeakNpcId = 95101,
          Subtitle = "Aww, don't feel bad for me! I'm not upset about it, because I met Filbert soon after.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10C0"
        },
        [80060129] = {
          ContentES = "Ese día yo tenía mucha... mucha hambre, y Filbert también, y aunque era tan pequeñita, me dio el único pedazo de pan que había sacado del basurero.",
          DialogueId = 80060129,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C10EA",
          NextDialogue = 80060130,
          SpeakNpcId = 95101,
          Subtitle = "That day, I was super hungry, and so was Filbert. She was just a tiny piglet then, but she gave me the only piece of bread she had found in a bin.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10EA"
        },
        [80060130] = {
          ContentES = "No recuerdo muy bien lo que estaba pensando en ese momento. Solo me acuerdo que me recosté junto a su oreja y le dije: “¡Vámonos de esta ciudad y busquemos comida en el bosque!”",
          DialogueId = 80060130,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C1114",
          NextOptions = {
            [1] = 80060131
          },
          SpeakNpcId = 95101,
          Subtitle = "I don't quite remember what I was thinking back then, just that I whispered into her ear, \"Let's leave the city and find food in the wild together!\"",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1114"
        },
        [80060131] = {
          ContentES = "Guau, una cerda que entiende a las personas...",
          DialogueId = 80060131,
          GUID = "C86C113E",
          NextDialogue = 80060132,
          Subtitle = "Wow, a pig that understands human speech..."
        },
        [80060132] = {
          ContentES = "Sí, es maravilloso, ¿verdad? Filbert es como un pastel de cumpleaños enviado por los dioses.",
          DialogueId = 80060132,
          GUID = "C86C1168",
          NextDialogue = 80060133,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh, amazing, right? Filbert must be a gift from the gods.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1168"
        },
        [80060133] = {
          ContentES = "Desde ese día, Filbert me lleva por los campos y bosques… Nunca más hemos vuelto a pasar hambre, y hasta podemos guardar comida para compartirla con otras personas hambrientas.",
          DialogueId = 80060133,
          GUID = "C86C1192",
          NextDialogue = 80060134,
          SpeakNpcId = 95101,
          Subtitle = "Ever since that day, Filbert has carried me to fields and forests to find food... We never went hungry again, and we've even been able to share extra food with other starving people.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1192"
        },
        [80060134] = {
          ContentES = "Ah... Filbert... Debe tener hambre, sola afuera. Oye, ¿puedo llevarme la mitad de la bebida que me diste para que la pruebe?",
          DialogueId = 80060134,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C11BC",
          NextOptions = {
            [1] = 80060135,
            [2] = 80060138
          },
          SpeakNpcId = 95101,
          Subtitle = "Ah... I wonder if Filbert's hungry out there on her own. Can I take the rest of this drink to share with her?",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C11BC"
        },
        [80060135] = {
          ContentES = "Claro que sí.",
          DialogueId = 80060135,
          GUID = "C86C11E6",
          NextDialogue = 80060136,
          Subtitle = "Of course."
        },
        [80060136] = {
          ContentES = "¡Guau!… qué buena persona eres. Algunas personas se molestan cuando comparto comida rica con Filbert, solo porque es una cerdita. Pero para mí, Filbert es una amiga muy, muy especial…",
          DialogueId = 80060136,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C1210",
          NextDialogue = 80060137,
          SpeakNpcId = 95101,
          Subtitle = "Aww, you're so kind-hearted! Some people frown upon me sharing treats with Filbert, just because she looks like a pig. But to me, Filbert is a dear friend...",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1210"
        },
        [80060137] = {
          ContentES = "¡De corazón gracias… por no rechazarla!",
          DialogueId = 80060137,
          GUID = "C86C123A",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          Subtitle = "Anyway, thank you so much for not judging!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C123A"
        },
        [80060138] = {
          ContentES = "No quiero que la cerda lo beba…",
          DialogueId = 80060138,
          GUID = "C86C1264",
          NextDialogue = 80060139,
          Subtitle = "I'd rather not share my drink with a pig..."
        },
        [80060139] = {
          ContentES = "Bueno… pues entonces yo tampoco voy a beberlo.",
          DialogueId = 80060139,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C128E",
          NextDialogue = 80060140,
          SpeakNpcId = 95101,
          Subtitle = "Oh...Okay. Then I won't drink it either.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C128E"
        },
        [80060140] = {
          ContentES = "Filbert es mi mejor amiga. Si la rechazas, es como si me rechazaras a mí… Filbert se entristecería, y yo también. Como sea, gracias por el pan y la bebida.",
          DialogueId = 80060140,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C12B8",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          Subtitle = "Filbert is my best friend; rejecting her is the same as rejecting me... it'd hurt her feelings, and mine too. But still, thank you for the bread drink.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12B8"
        },
        [80060141] = {
          ContentES = "Ya he bebido suficiente. ¡Hasta la próxima!",
          DialogueId = 80060141,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C12E2",
          SpeakNpcId = 95101,
          Subtitle = "I'm full now. See you around!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12E2"
        },
        [80060201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "Humm… Mmm…",
          DialogueId = 80060201,
          GUID = "C86C1CBA",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextDialogue = 80060202,
          SpeakNpcId = 95101,
          Subtitle = "Hmm... ugh...",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1CBA"
        },
        [80060202] = {
          ContentES = "*Suspira*",
          DialogueId = 80060202,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1CE4",
          NextOptions = {
            [1] = 80060203
          },
          SpeakNpcId = 95101,
          Subtitle = "*sigh*",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1CE4"
        },
        [80060203] = {
          ContentES = "¿Eh? ¿Por qué tan triste?",
          DialogueId = 80060203,
          GUID = "C86C1D0E",
          NextDialogue = 80060204,
          Subtitle = "You seem upset. What's wrong?"
        },
        [80060204] = {
          ContentES = "¿Eh? No, no… no estoy triste. Jejeje…",
          DialogueId = 80060204,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C1D38",
          NextOptions = {
            [1] = 80060205
          },
          SpeakNpcId = 95101,
          Subtitle = "Huh? Oh, I'm fine... Hehe, hehehe!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1D38"
        },
        [80060205] = {
          ContentES = "No finjas, tu cara estaba inflada como un pan.",
          DialogueId = 80060205,
          GUID = "C86C1D62",
          NextDialogue = 80060206,
          Subtitle = "Come on, I could spot that pout from a mile away."
        },
        [80060206] = {
          ContentES = "Ay… ¡Me descubriste! Bueno, aunque mi dicho es “compartamos más pan y menos problemas”, pero ya que lo preguntas… ¡Quizás puedas ayudarme a resolver este asunto!",
          DialogueId = 80060206,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1D8C",
          NextDialogue = 80060207,
          SpeakNpcId = 95101,
          Subtitle = "Ah, you saw through me... Well, they say sharing bread is good and sharing troubles is bad, but since you asked... maybe you can help me figure this out!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1D8C"
        },
        [80060207] = {
          ContentES = "Hace un par de días me topé con un tipo muy malo… Parece que era el mayordomo de alguna familia rica, y vino a hablar con nuestro comisario de Provisiones porque quería comprar nueces.",
          DialogueId = 80060207,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1DB6",
          NextDialogue = 80060208,
          SpeakNpcId = 95101,
          Subtitle = "A few days ago, I met a really obnoxious guy... He seemed to be a butler for some noble family, and he wanted to buy loads of nuts from us commissaries.",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1DB6"
        },
        [80060208] = {
          ContentES = "Hizo que sus sirvientes se llevaran ¡siete sacos enteros! Y la paga que puso en el recibo tenía muchos... muchos ceros.",
          DialogueId = 80060208,
          GUID = "C86C1DE0",
          NextDialogue = 80060209,
          SpeakNpcId = 95101,
          Subtitle = "He and his men brought seven big bags, and the payment offered was all zeros and commas!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1DE0"
        },
        [80060209] = {
          ContentES = "Como siempre dice la sacerdotisa: “¡Si hay dinero que ganar, no lo dejes pasar”. Así que Filbert y yo estuvimos ocupadas todo el día buscando nueces.",
          DialogueId = 80060209,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1E0A",
          NextOptions = {
            [1] = 80060210
          },
          SpeakNpcId = 95101,
          Subtitle = "As a priestess in the church always says, \"A coin not earned is a coin lost!\" So, Filbert and I worked our tails off all day for this order.",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E0A"
        },
        [80060210] = {
          ContentES = "¿Acaso se llevó las cosas y no pagó?",
          DialogueId = 80060210,
          GUID = "C86C1E34",
          NextDialogue = 80060211,
          Subtitle = "Did he stiff you on the payment for those nuts?"
        },
        [80060211] = {
          ContentES = "Todo lo contrario, no solo pagó lo justo, ¡sino que además nos dio un extra por el trabajo rápido! ¡Fue algo tan... tan maravilloso!",
          DialogueId = 80060211,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1E5E",
          NextDialogue = 80060212,
          SpeakNpcId = 95101,
          Subtitle = "It was the opposite. He paid in full and even added a bonus for our quick service — it should've been a great deal.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E5E"
        },
        [80060212] = {
          ContentES = "Pero, mientras se iban, me di cuenta de que el mayordomo estaba sacando las torcinueces de los sacos y tirándolas por ahí.",
          DialogueId = 80060212,
          GUID = "C86C1E88",
          NextDialogue = 80060213,
          SpeakNpcId = 95101,
          Subtitle = "But as they were leaving, I noticed the butler picking out some fresh Twisty Pods from the bags and throwing them away.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E88"
        },
        [80060213] = {
          ContentES = "Me apresuré a detenerlo y le dije que todas eran nueces muy, muy ricas, y que es normal que las torcinueces vengan con una pelusita blanca, ¡que no era moho!",
          DialogueId = 80060213,
          GUID = "C86C1EB2",
          NextDialogue = 80060214,
          SpeakNpcId = 95101,
          Subtitle = "I stopped him right there and explained those were perfectly good nuts — the white stuff was their natural fuzz, not mould.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1EB2"
        },
        [80060214] = {
          ContentES = "Y adivina qué dijo… ¡me dijo que sabía que esas nueces no estaban malas, solo que no se les podía extraer mucho aceite, y por eso las tiraba!",
          DialogueId = 80060214,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1EDC",
          NextOptions = {
            [1] = 80060215
          },
          SpeakNpcId = 95101,
          Subtitle = "And guess what, he said he knew they weren't mouldy, but they weren't good for extracting oil, so he didn't want them!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1EDC"
        },
        [80060215] = {
          ContentES = "¿Extraer aceite...?",
          DialogueId = 80060215,
          GUID = "C86C1F06",
          NextDialogue = 80060216,
          Subtitle = "Extracting oil...?"
        },
        [80060216] = {
          ContentES = "¡Ajá! ¡No compraron esos frutos secos para comer! No vas a creer esto...",
          DialogueId = 80060216,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1F30",
          NextDialogue = 80060217,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh! They didn't buy those nuts to eat! You won't believe this—",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F30"
        },
        [80060217] = {
          ContentES = "Me dijo que la familia de su patrón se baña todos los días en leche. ¡Y que solo usaban la leche de las mejores vacas, como si fuera lo más normal del mundo!",
          DialogueId = 80060217,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1F5A",
          NextDialogue = 80060218,
          SpeakNpcId = 95101,
          Subtitle = "He said his master's family bathe in boiled milk every day! And they only use milk from the healthiest cows on the farm!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F5A"
        },
        [80060218] = {
          ContentES = "¡Y eso no es todo! También le añaden especias para perfumar la leche, le echan pétalos de tulipán. ¡Y ahora quieren usar aceite de nueces!",
          DialogueId = 80060218,
          GUID = "C86C1F84",
          NextDialogue = 80060219,
          SpeakNpcId = 95101,
          Subtitle = "And that's not all — they'd add fresh perfume to the bath milk. They used to use tulip petals for the fragrance, and now they're switching to essential oil from nuts!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F84"
        },
        [80060219] = {
          ContentES = "Y a las nueces que no se les puede extraer aceite… ¡las tiran todas al basurer!",
          DialogueId = 80060219,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1FAE",
          NextOptions = {
            [1] = 80060220,
            [2] = 80060222
          },
          SpeakNpcId = 95101,
          Subtitle = "As for the nuts that couldn't be used for oil? Straight into the bin!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1FAE"
        },
        [80060220] = {
          ContentES = "¡Qué desperdicio…!",
          DialogueId = 80060220,
          GUID = "C86C1FD8",
          NextDialogue = 80060221,
          Subtitle = "That's so wasteful..."
        },
        [80060221] = {
          ContentES = "¡Exacto! Y aunque yo pudiera soportarlo, ¡Filbert jamás estaría de acuerdo!",
          DialogueId = 80060221,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2002",
          NextDialogue = 80060224,
          SpeakNpcId = 95101,
          Subtitle = "Exactly! And even if I could look the other way, Filbert wouldn't be okay with it!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2002"
        },
        [80060222] = {
          ContentES = "Hmm, bañarse en leche... debe ser agradable...",
          DialogueId = 80060222,
          GUID = "C86C202C",
          NextDialogue = 80060223,
          Subtitle = "Hmm, bathe in milk... must be nice..."
        },
        [80060223] = {
          ContentES = "¡Ay, no digas eso! ¡Nuestras escrituras no nos permiten desperdiciar comida! ¡es un gran crimen! ¡Ya les llegará su merecido!",
          DialogueId = 80060223,
          FacialId = {
            [1] = "95101:Confident01"
          },
          GUID = "C86C2056",
          NextDialogue = 80060224,
          SpeakNpcId = 95101,
          Subtitle = "Ah, don't say that! Our scriptures say wasting food is a huge sin! They'll get their comeuppance!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2056"
        },
        [80060224] = {
          ContentES = "Le devolví las monedas de plata que me dio y recuperé mis nueces. ¡No puedo permitir que se desperdicien ni un poquito! Según las enseñanzas del gran Dios, ¡el pecado más imperdonable es el de desperdiciar!",
          DialogueId = 80060224,
          GUID = "C86C2080",
          NextOptions = {
            [1] = 80060225,
            [2] = 80060227
          },
          SpeakNpcId = 95101,
          Subtitle = "I threw his money right back at him and took back my nuts. I just couldn't watch them waste food like that! According to the divine teachings, the worst sin is waste!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2080"
        },
        [80060225] = {
          ContentES = "¡Tienes todo la razón! Desperdiciar la comida no está bien.",
          DialogueId = 80060225,
          GUID = "C86C20AA",
          NextDialogue = 80060226,
          Subtitle = "You're absolutely right, Truffle. Wasting food is bad."
        },
        [80060226] = {
          ContentES = "¡Verdad que sí! Cada vez que se desperdicia aunque sea un poquito de comida, hay un estómago que se queda con hambre.",
          DialogueId = 80060226,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C20D4",
          NextDialogue = 80060231,
          SpeakNpcId = 95101,
          Subtitle = "Right? Every bit of wasted food could have filled a hungry belly. I can't let food go to waste! Not even a little bit!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C20D4"
        },
        [80060227] = {
          ContentES = "Bueno, al final de cuentas ellos pagaron por las nueces. Cómo las usen es cosa de ellos…",
          DialogueId = 80060227,
          GUID = "C86C20FE",
          NextDialogue = 80060228,
          Subtitle = "But if they've already paid, isn't it their right to do as they please with their own stuff?"
        },
        [80060228] = {
          ContentES = "¿Eh...? Eso no es lo que los dioses nos enseñan… Lo que dices tiene algo de sentido pero… mi corazoncito siente que no está del todo bien…",
          DialogueId = 80060228,
          GUID = "C86C2128",
          NextDialogue = 80060229,
          SpeakNpcId = 95101,
          Subtitle = "Huh? That's not what the gods teach... Though what you said does make sense... But something still doesn't feel right...",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2128"
        },
        [80060229] = {
          ContentES = "Puf, qué complicado… mejor lo dejo así. Si él tiene la libertad de usar la comida como quiera, ¡yo también tengo la libertad de no vendérsela!",
          DialogueId = 80060229,
          FacialId = {
            [1] = "95101:Confident01"
          },
          GUID = "C86C2152",
          NextDialogue = 80060230,
          SpeakNpcId = 95101,
          Subtitle = "Ugh, so complicated. Well, if they have the right to waste their own food, then I have the right not to sell food to them!",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2152"
        },
        [80060230] = {
          ContentES = "Si tan solo las personas que más tienen supieran que todavía hay muchas otras que pasan hambre…",
          DialogueId = 80060230,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C217C",
          NextDialogue = 80060231,
          SpeakNpcId = 95101,
          Subtitle = "If only those who never have to worry about food could see that there are still people starving out there...",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C217C"
        },
        [80060231] = {
          ContentES = "Al final, perdí las moneditas que había conseguido y la sacerdotisa me regañó un buen rato, pero igual repartí todas las nueces entre las personas con más necesidad.",
          DialogueId = 80060231,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C21A6",
          NextDialogue = 80060232,
          SpeakNpcId = 95101,
          Subtitle = "Anyway — in the end, I got a lecture from a priestess for losing that order, but I still gave all those nuts to people in need.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C21A6"
        },
        [80060232] = {
          ContentES = "¡Sé lo que es tener la pancita vacía, y no me gusta nada de nada!… Nunca más quiero pasar hambre, y tampoco quiero que nadie más la tenga...",
          DialogueId = 80060232,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C21D0",
          NextOptions = {
            [1] = 80060233
          },
          SpeakNpcId = 95101,
          Subtitle = "I know what starving feels like — it's awful! I never want that again, and I don't want to see anyone else starve.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C21D0"
        },
        [80060233] = {
          ContentES = "Eres una niña muy buena, Truffle.",
          DialogueId = 80060233,
          GUID = "C86C21FA",
          NextDialogue = 80060234,
          Subtitle = "You have a kind heart, Truffle."
        },
        [80060234] = {
          ContentES = "Ay... Siento que todavía falta un largo, larguísimo camino para cumplir mi sueño junto a Filbert: que a nadie nunca más le falte comida.",
          DialogueId = 80060234,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C2224",
          NextDialogue = 80060235,
          SpeakNpcId = 95101,
          Subtitle = "*sigh*... It feels like there's still a loooong way to go before Filbert and I can achieve our dream of feeding everyone in the world.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2224"
        },
        [80060235] = {
          ContentES = "Bueno… ya no podemos seguir esperando. Filbert y yo vamos a juntar comida. Otro día volveré a jugar contigo, ¿sí? ¡Y tú, acuérdate de comer bien y mucho!",
          DialogueId = 80060235,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C224E",
          SpeakNpcId = 95101,
          Subtitle = "Well, I guess I should try even harder! I'm off to gather food with Filbert now! See you around — and don't forget to eat well!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C224E"
        },
        [80060301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "Jeje, el jugo de baya boreal de esta temporada está realmente delicioso. Nada ácido, todo dulcito, ¡qué rico está!",
          DialogueId = 80060301,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2D22",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextOptions = {
            [1] = 80060302
          },
          SpeakNpcId = 95101,
          Subtitle = "Hehe, borealberry juice is just the best this season — so sweet and refreshing, not sour at all. Yum yum!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2D22"
        },
        [80060302] = {
          ContentES = "Qué bien que te guste.",
          DialogueId = 80060302,
          GUID = "C86C2D4C",
          NextDialogue = 80060303,
          Subtitle = "Glad you like it."
        },
        [80060303] = {
          ContentES = "¿Podrías darme la receta? ¡Estoy segura de que Filbert saltaría de la alegría si la prueba!",
          DialogueId = 80060303,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C2D76",
          NextOptions = {
            [1] = 80060304
          },
          SpeakNpcId = 95101,
          Subtitle = "Can I have the recipe? Filbert would love this too!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2D76"
        },
        [80060304] = {
          ContentES = "Claro que sí.",
          DialogueId = 80060304,
          GUID = "C86C2DA0",
          NextDialogue = 80060305,
          Subtitle = "Sure."
        },
        [80060305] = {
          ContentES = "¡Gracias! ¡Eres una persona muy, muy buena y filan... filantrópica… ¿lo dije bien? En fin, ¡eres un ángel como el de las escrituras!",
          DialogueId = 80060305,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C2DCA",
          NextDialogue = 80060306,
          SpeakNpcId = 95101,
          Subtitle = "Thank you! You're so benevolent and phillan... phillan-thropic — did I get that right? Anyway, you're an angel!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2DCA"
        },
        [80060306] = {
          ContentES = "Filbert y yo solíamos recoger bayas boreales. Solo había que tirar de ellas un poquito, y caían en tus manos. Podía llenar cestas enteras. Filbert se ponía a dar vueltas de lo contenta que estaba.",
          DialogueId = 80060306,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2DF4",
          NextDialogue = 80060307,
          SpeakNpcId = 95101,
          Subtitle = "Filbert and I used to pick borealberries very often. Just a little twist, and they'd fall into my hands. I'd fill baskets full of them, and Filbert was always so happy hauling them back.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2DF4"
        },
        [80060307] = {
          ContentES = "Una vez comimos tantísimas bayitas que nuestras lenguas y bocas se pusieron moradas, y por más que intentamos lavarnos junto al río, ¡no se quitaba!",
          DialogueId = 80060307,
          GUID = "C86C2E1E",
          NextDialogue = 80060308,
          SpeakNpcId = 95101,
          Subtitle = "One time, we ate so many our tongues and lips turned purple! We spent a lot of time washing our mouths by the stream, but the colour just wouldn't come off.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E1E"
        },
        [80060308] = {
          ContentES = "Filbert se puso nerviosa, saltó al río a lavarse y... ¡un cangrejo le pellizcó la patita! Estaba llore y llore porque le dolía mucho. Yo, sin pensarlo, me lancé al agua a rescatarla… ¡y resulta que debajo de otra piedra había un cangrejo grande!",
          DialogueId = 80060308,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2E48",
          NextDialogue = 80060309,
          SpeakNpcId = 95101,
          Subtitle = "Filbert got so upset she jumped into the stream to wash up, and then a crab under the pebbles pinched her foot — it hurt so much she whimpered. So I jumped right in to save her, and guess what — there was another crab, a really big one...",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E48"
        },
        [80060309] = {
          ContentES = "Al final, acabamos todas mojadas y nos fuimos cojeando con la cara llorosa y todas moraditas. La sacerdotisa McGuffin nos curó mientras nos regañaba bien feíto.",
          DialogueId = 80060309,
          GUID = "C86C2E72",
          NextDialogue = 80060310,
          SpeakNpcId = 95101,
          Subtitle = "We both ended up soaking wet, limping back with teary, purple-stained faces. Priestess McGuffin patched us up, all the while giving us a good scolding.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E72"
        },
        [80060310] = {
          ContentES = "Desde entonces, cada vez que Filbert pasa por los arbustos, mira las bayas boreales con mucha hambre… pero no se atreve a probarlas otra vez.",
          DialogueId = 80060310,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2E9C",
          NextOptions = {
            [1] = 80060311
          },
          SpeakNpcId = 95101,
          Subtitle = "Since then, every time Filbert passes a berry bush, she just eyes those borealberries eagerly but never dares to nibble at one.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E9C"
        },
        [80060311] = {
          ContentES = "¿Les da mucho miedo la sacerdotisa McGuffin…?",
          DialogueId = 80060311,
          GUID = "C86C2EC6",
          NextDialogue = 80060312,
          Subtitle = "Are you two scared of Priestess McGuffin?"
        },
        [80060312] = {
          ContentES = "¡A mí un poquito! Pero cada vez que Filbert la ve, tiembla de miedo. Probablemente es porque al principio le decía que la iba a sacar de la casa.",
          DialogueId = 80060312,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C2EF0",
          NextDialogue = 80060313,
          SpeakNpcId = 95101,
          Subtitle = "I'm not. But Filbert shivers whenever she's around, probably because she threatened to kick her out when we first came.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2EF0"
        },
        [80060313] = {
          ContentES = "Cuando la sacerdotisa McGuffin me adoptó, siempre tenía miedo de que Filbert se comiera toda la comida y no dejara nada para los demás.",
          DialogueId = 80060313,
          GUID = "C86C2F1A",
          NextDialogue = 80060340,
          SpeakNpcId = 95101,
          Subtitle = "When Priestess McGuffin first took me in, she was worried that Filbert would eat up all the food in the church and leave everyone else hungry.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F1A"
        },
        [80060314] = {
          ContentES = "La sacerdotisa McGuffin finalmente terminó adoptándola, pero sigue diciendo que Filbert no tiene nada de especial. Dice cosas como:",
          DialogueId = 80060314,
          GUID = "C86C2F44",
          NextDialogue = 80060315,
          SpeakNpcId = 95101,
          Subtitle = "Priestess McGuffin eventually agreed to keep Filbert, though she still complains Filbert isn't cool enough. She'd say things like—",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F44"
        },
        [80060315] = {
          ContentES = "“Truffle, mira este libro, lo escribió una persona de Hyperborea. Habla de un héroe que se hace amigo de un dragón. ¿Por qué los animales de los demás siempre son tan geniales, y nosotros solo podemos tener una cerdita?”",
          DialogueId = 80060315,
          GUID = "C86C2F6E",
          NextDialogue = 80060316,
          SpeakNpcId = 95101,
          Subtitle = "\"Little Truffle, have you read this Hyperborean novel about a hero who befriends a dragon? Why do they get such cool animal friends, and we just have a pig?\"",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F6E"
        },
        [80060316] = {
          ContentES = "“Mira este otro libro, lo escribió alguien de Huaxu. Aunque aquí sí llevan un cerdito… parece que es un tipo de general que cayó del cielo, y hasta es capaz de enfrentarse a monstruos. Nuestra cerdita… no tiene ninguna habilidad especial, ¿o sí?”",
          DialogueId = 80060316,
          GUID = "C86C2F98",
          NextOptions = {
            [1] = 80060317,
            [2] = 80060319,
            [3] = 80060320
          },
          SpeakNpcId = 95101,
          Subtitle = "\"And here's another novel by a Huaxu writer — they have a pig too, but theirs is a celestial general who fights monsters! Does our pig have any special powers?\"",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F98"
        },
        [80060317] = {
          ContentES = "Ella tiene razón, deberías buscarte un compañero más admirable.",
          DialogueId = 80060317,
          GUID = "C86C2FC2",
          NextDialogue = 80060318,
          Subtitle = "Maybe she has a point. You should find a cooler companion."
        },
        [80060318] = {
          ContentES = "¡Imposible! ¡¿Cómo podría abandonar a Filbert?!",
          DialogueId = 80060318,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C2FEC",
          NextOptions = {
            [1] = 80060322
          },
          SpeakNpcId = 95101,
          Subtitle = "Nuh-uh! I would never leave Filbert!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2FEC"
        },
        [80060319] = {
          ContentES = "No, Filbert es irremplazable para mí.",
          DialogueId = 80060319,
          GUID = "C86C3016",
          NextDialogue = 80060321,
          Subtitle = "She's wrong. Filbert is irreplaceable."
        },
        [80060320] = {
          ContentES = "No le hagas caso. ¡Montar un cerdito es de lo más genial!",
          DialogueId = 80060320,
          GUID = "C86C3040",
          NextDialogue = 80060321,
          Subtitle = "Don't listen to her — riding a pig is super cool!"
        },
        [80060321] = {
          ContentES = "Guau, ¿de verdad lo piensas? ¡Eres lo mejor! ¡Qué te bendigan el dios de la vida, de la abundancia y todos los dioses que existan…!",
          DialogueId = 80060321,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C306A",
          NextOptions = {
            [1] = 80060322
          },
          SpeakNpcId = 95101,
          Subtitle = "Wow, you really think so? You're the best! May the Gods of Life, Bounty, Borealberry, Burrowing Botato — any gods there are — bless you!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C306A"
        },
        [80060322] = {
          ContentES = "En verdad quieres mucho a Filbert. Seguramente es una Geniemon muy especial.",
          DialogueId = 80060322,
          GUID = "C86C3094",
          NextDialogue = 80060323,
          Subtitle = "You really like Filbert. She must be very special."
        },
        [80060323] = {
          ContentES = "¿Especial? ¡Claro que sí! Pero tengo curiosidad… ¿por qué crees que sea especial, {nickname}?",
          DialogueId = 80060323,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C30BE",
          NextOptions = {
            [1] = 80060324,
            [2] = 80060326
          },
          SpeakNpcId = 95101,
          Subtitle = "Special? She sure is! But I'm curious — why would you think so, ?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C30BE"
        },
        [80060324] = {
          ContentES = "Filbert corre muy rápido.",
          DialogueId = 80060324,
          GUID = "C86C30E8",
          NextDialogue = 80060325,
          Subtitle = "Because Filbert runs very fast."
        }
      }
    end
  },
  {
    MinKey = 80060325,
    MaxKey = 80080124,
    Loader = function()
      return {
        [80060325] = {
          ContentES = "En realidad, la mayoría de Geniemon pueden correr muy... muy rápido, y muchos cerdos normales también. Y comparado con ellos, Filbert ni siquiera se acerca.",
          DialogueId = 80060325,
          FacialId = {
            [1] = "95101:Smile01"
          },
          GUID = "C86C3112",
          NextDialogue = 80060328,
          SpeakNpcId = 95101,
          Subtitle = "Actually, all Geniemons are pretty fast. Many wild pigs can also do the same. And compared to them, Filbert isn't even close.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3112"
        },
        [80060326] = {
          ContentES = "Filbert sabe buscar comida.",
          DialogueId = 80060326,
          GUID = "C86C313C",
          NextDialogue = 80060327,
          Subtitle = "Because Filbert can find lots of food."
        },
        [80060327] = {
          ContentES = "Filbert usa su naricita para buscar setas rojas. La verdad es que, muchos Geniemon tienen un olfato muy agudo. Si se los pides bien, ¡también pueden ayudarte a encontrar comida!",
          DialogueId = 80060327,
          FacialId = {
            [1] = "95101:Smile01"
          },
          GUID = "C86C3166",
          NextDialogue = 80060328,
          SpeakNpcId = 95101,
          Subtitle = "She uses her nose to sniff out food in the wild. Actually, all Geniemons have sharp noses. If you ask them nicely, they could help you find food too.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3166"
        },
        [80060328] = {
          ContentES = "En realidad, estuve pensando en eso desde que la sacerdotisa McGuffin me hizo la misma pregunta.",
          DialogueId = 80060328,
          GUID = "C86C3190",
          NextDialogue = 80060329,
          SpeakNpcId = 95101,
          Subtitle = "Actually, I've really thought about this after Priestess McGuffin asked me.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3190"
        },
        [80060329] = {
          ContentES = "Una vez me pregunté, entre todos los adorables Geniemon que existen, ¿por qué es Filbert la que está a mi lado?",
          DialogueId = 80060329,
          GUID = "C86C31BA",
          NextDialogue = 80060330,
          SpeakNpcId = 95101,
          Subtitle = "I once wondered, among all Geniemons out there, why must it be Filbert?",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C31BA"
        },
        [80060330] = {
          ContentES = "Le estuve dando vueltas al asunto toda la noche. Al día siguiente, Filbert me despertó con su naricita y entonces lo entendí.",
          DialogueId = 80060330,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C31E4",
          NextDialogue = 80060331,
          SpeakNpcId = 95101,
          Subtitle = "But I only thought about it for one night. The next morning, when Filbert nuzzled my face to wake me up, it suddenly all made sense.",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C31E4"
        },
        [80060331] = {
          ContentES = "Es porque Filbert… ¡es mi Filbert! Siempre me ayuda a buscar setas rojas en el lodo, carga con las bolsas de comida y lucha contra los matones…",
          DialogueId = 80060331,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C320E",
          NextDialogue = 80060332,
          SpeakNpcId = 95101,
          Subtitle = "Because only Filbert... is my Filbert! The one who helps me dig for mushrooms, carry bags of food handouts, and fight against bullies...",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C320E"
        },
        [80060332] = {
          ContentES = "Está conmigo cuando leo las escrituras, me da abracitos cuando estoy enferma y me acompaña cuando tengo que hacer recados.",
          DialogueId = 80060332,
          GUID = "C86C3238",
          NextOptions = {
            [1] = 80060333
          },
          SpeakNpcId = 95101,
          Subtitle = "She's always been there for me — when I stumble through scriptures, when I get sick, and when I run around on errands.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3238"
        },
        [80060333] = {
          ContentES = "Entonces, ¿son todos esos pequeños momentos que han compartido juntas lo que hace que Filbert sea tan especial?",
          DialogueId = 80060333,
          GUID = "C86C3262",
          NextDialogue = 80060334,
          Subtitle = "So it's the many little moments you've shared together that make Filbert so special?"
        },
        [80060334] = {
          ContentES = "¡Sí! Aunque mucha gente piense que Filbert no tiene nada de especial, aunque haya Geniemon más rápidos, más bonitos o que recojan más setas rojas… incluso si no fuera más que una cerdita común…",
          DialogueId = 80060334,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C328C",
          NextDialogue = 80060335,
          SpeakNpcId = 95101,
          Subtitle = "Exactly! Even though many people think Filbert is not cool, and even though there are many Geniemons in this world that run faster, look cuter, and dig up more mushrooms than Filbert... even if Filbert is just an ordinary pig...",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C328C"
        },
        [80060335] = {
          ContentES = "Filbert sigue siendo la única en el mundo, ¡la mejor compañera de la Comisaria de Provisiones Truffle!",
          DialogueId = 80060335,
          GUID = "C86C32B6",
          NextOptions = {
            [1] = 80060336
          },
          SpeakNpcId = 95101,
          Subtitle = "Filbert is still the one and only in the world — Commissary Truffle's best partner!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C32B6"
        },
        [80060336] = {
          ContentES = "Lo recuerdo bien, es la Comisaria Especial de Provisiones.",
          DialogueId = 80060336,
          GUID = "C86C32E0",
          NextDialogue = 80060337,
          Subtitle = "Right, I remember she's the Special Commissary."
        },
        [80060337] = {
          ContentES = "¡Exacto! Truffle y Filbert juntas, ahuyentan el hambre...",
          DialogueId = 80060337,
          GUID = "C86C330A",
          NextDialogue = 80060338,
          SpeakNpcId = 95101,
          Subtitle = "Right! Truffle and Filbert together, fighting hunger—",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C330A"
        },
        [80060338] = {
          ContentES = "¡Ah, sí! Casi lo olvido, todavía no he repartido la comida que recolectamos…",
          DialogueId = 80060338,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C3334",
          NextDialogue = 80060339,
          SpeakNpcId = 95101,
          Subtitle = "Ah! I almost forgot — I haven't divvied up today's food.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3334"
        },
        [80060339] = {
          ContentES = "Tengo que irme, {nickname}. ¡Hasta la próxima!",
          DialogueId = 80060339,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C335E",
          SpeakNpcId = 95101,
          Subtitle = "I have to go now, . See you next time!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C335E"
        },
        [80060340] = {
          ContentES = "Pero pronto todos se dieron cuenta de que, a pesar de que Filbert sea una cerdita, no come tanto como una, y que no se acabaría toda la comida.",
          DialogueId = 80060340,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2F1B",
          NextDialogue = 80060314,
          SpeakNpcId = 95101,
          Subtitle = "But it didn't take long for them to realize that she didn't share a pig's voracious appetite and wouldn't devour large amounts of food.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F1B"
        },
        [80060401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "¡{nickname}! Eh… ¡tengo una pregunta súper importante! ¿Puedes responderme ahora mismo?",
          DialogueId = 80060401,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3D8A",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextOptions = {
            [1] = 80060402
          },
          SpeakNpcId = 95101,
          Subtitle = "! I... I have a really important question! Can you answer it right now?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3D8A"
        },
        [80060402] = {
          ContentES = "Claro. ¿Cuál es la pregunta?",
          DialogueId = 80060402,
          GUID = "C86C3DB4",
          NextDialogue = 80060403,
          Subtitle = "Sure. What is it?"
        },
        [80060403] = {
          ContentES = "Quiero preguntarte… si pudieras llenar tu pancita todos los días, ¿serías feliz?",
          DialogueId = 80060403,
          GUID = "C86C3DDE",
          NextOptions = {
            [1] = 80060404,
            [2] = 80060405
          },
          SpeakNpcId = 95101,
          Subtitle = "I'm wondering — would you be happy if you get to fill yourself up every day?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3DDE"
        },
        [80060404] = {
          ContentES = "¡Por supuesto!",
          DialogueId = 80060404,
          GUID = "C86C3E08",
          NextDialogue = 80060406,
          Subtitle = "Of course."
        },
        [80060405] = {
          ContentES = "Mmm, no lo sé.",
          DialogueId = 80060405,
          GUID = "C86C3E32",
          NextDialogue = 80060406,
          Subtitle = "Mm, I don't know."
        },
        [80060406] = {
          ContentES = "Entonces tengo otra pregunta: ¿si realmente basta con llenarse la pancita para ser feliz?",
          DialogueId = 80060406,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C3E5C",
          NextOptions = {
            [1] = 80060407,
            [2] = 80060409
          },
          SpeakNpcId = 95101,
          Subtitle = "Then I have another question — is just being able to fill yourself up every day enough to make you happy?",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3E5C"
        },
        [80060407] = {
          ContentES = "Claro. ¿Qué hay para molestarse cuando estás lleno?",
          DialogueId = 80060407,
          GUID = "C86C3E86",
          NextDialogue = 80060408,
          Subtitle = "Uh-huh. What's there to be upset about when you're full?"
        },
        [80060408] = {
          ContentES = "¡Exacto! Comer hasta quedar llenito es lo más, más, más importante.",
          DialogueId = 80060408,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3EB0",
          NextDialogue = 80060411,
          SpeakNpcId = 95101,
          Subtitle = "Exactly! There's nothing more important than a full belly!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3EB0"
        },
        [80060409] = {
          ContentES = "No creo… También hay otras cosas por las cuales uno debe preocuparse.",
          DialogueId = 80060409,
          GUID = "C86C3EDA",
          NextDialogue = 80060410,
          Subtitle = "Nah, there's plenty of stuff to worry about."
        },
        [80060410] = {
          ContentES = "¿Ah? ¿En serio? Entonces parece que pensamos un poquito diferente.",
          DialogueId = 80060410,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3F04",
          NextDialogue = 80060411,
          SpeakNpcId = 95101,
          Subtitle = "Huh? Really? We might be different then.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F04"
        },
        [80060411] = {
          ContentES = "En mi caso, yo soy feliz mientras pueda comer todos los días hasta quedar llenita. Pero tengo dos amigos que piensan distinto y me dejan un poco confundida.",
          DialogueId = 80060411,
          GUID = "C86C3F2E",
          NextDialogue = 80060412,
          SpeakNpcId = 95101,
          Subtitle = "For me, as long as I get to fill my belly every day, I'm happy. But I have two friends who don't feel the same way at all, so I'm a bit confused.",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F2E"
        },
        [80060412] = {
          ContentES = "Una de ellos vive en las afueras y es la hija mayor de una familia rica. Su casa tiene un montón de joyas que podrían cambiarse por muchísimas monedas de plata, y contrata a muchos cocineros expertos para que le preparen comida rica.",
          DialogueId = 80060412,
          FacialId = {
            [1] = "95101:Doubt01"
          },
          GUID = "C86C3F58",
          NextDialogue = 80060413,
          SpeakNpcId = 95101,
          Subtitle = "One is a lady from a rich merchant family. She lives out in the suburbs, and has loads of shiny gems that can be traded for tons of silver coins; she can easily afford to hire lots of amazing chefs to make as much delicious food as she wants.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F58"
        },
        [80060413] = {
          ContentES = "Sin embargo, ella no es feliz. La sacerdotisa me explicó que está así porque tiene que mudarse muy lejos, a una ciudad que no le gusta, y además compartir su vida con alguien que no conoce.",
          DialogueId = 80060413,
          GUID = "C86C3F82",
          NextDialogue = 80060414,
          SpeakNpcId = 95101,
          Subtitle = "But she's still not happy. One priestess told me it's because she has to move far away to a city she doesn't like, to live with someone she doesn't even know.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F82"
        },
        [80060414] = {
          ContentES = "Cambió toda la comida que había ahorrado durante un mes por un nuevo conjunto de escrituras en el santuario.",
          DialogueId = 80060414,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C3FAC",
          NextDialogue = 80060415,
          SpeakNpcId = 95101,
          Subtitle = "And the other one's the most devout follower in our church. He traded all the food he saved up for a month for a new set of scriptures at the shrine.",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3FAC"
        },
        [80060415] = {
          ContentES = "¡Ay! ¿Acaso no tendrá hambre? Siempre está tan flaquito que parece que el viento se lo va a llevar. Pero él dice que mientras siga leyendo las escrituras puede… “lalimentar su alma”.",
          DialogueId = 80060415,
          GUID = "C86C3FD6",
          NextDialogue = 80060416,
          SpeakNpcId = 95101,
          Subtitle = "I mean, isn't that crazy? Wouldn't he end up starving because of that? He's always been so thin — the wind can easily carry him away like a leaf! But he says that reading the scriptures \"feeds his soul\"!",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3FD6"
        },
        [80060416] = {
          ContentES = "Mmm, no lo logro entender… ¿por qué son tan diferentes a mí?",
          DialogueId = 80060416,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C4000",
          NextDialogue = 80060417,
          SpeakNpcId = 95101,
          Subtitle = "I just don't get it... Why are they so different from me?",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4000"
        },
        [80060417] = {
          ContentES = "¿Por qué habrá personas que comen hasta quedar llenas, pero no son felices, y otras que pasan hambre, pero están contentas?",
          DialogueId = 80060417,
          GUID = "C86C402A",
          NextDialogue = 80060418,
          SpeakNpcId = 95101,
          Subtitle = "Why are some people still upset even when they're full? And why are some happy even when they're starving?",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C402A"
        },
        [80060418] = {
          ContentES = "En las escrituras sagradas, el dios dice que debemos intentar hacer feliz a los demás… pero, ¿cómo puedo lograr que todos estén contentos?",
          DialogueId = 80060418,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C4054",
          NextOptions = {
            [1] = 80060419,
            [2] = 80060420
          },
          SpeakNpcId = 95101,
          Subtitle = "The scriptures say we should all try to make others happy... but how can I make EVERYONE happy?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4054"
        },
        [80060419] = {
          ContentES = "El corazón humano es lo más complicado, no hay dos personas que piensen igual.",
          DialogueId = 80060419,
          GUID = "C86C407E",
          NextDialogue = 80060421,
          Subtitle = "Human hearts are quite complicated. Everyone feels different."
        },
        [80060420] = {
          ContentES = "No se puede hacer feliz a todos. Los dioses están equivocados, no les hagas caso.",
          DialogueId = 80060420,
          GUID = "C86C40A8",
          NextDialogue = 80060421,
          Subtitle = "You can't make everyone happy; that's just nonsense in the scriptures."
        },
        [80060421] = {
          ContentES = "¿Eh? ¿Qué quieres decir? No te entiendo muy bien…",
          DialogueId = 80060421,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C40D2",
          NextDialogue = 80060422,
          SpeakNpcId = 95101,
          Subtitle = "What do you mean? I don't get it...",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C40D2"
        },
        [80060422] = {
          ContentES = "La gente llora cuando está triste, ríe cuando está contenta, se fastidia cuando está enojada y come cuando tiene hambre. Es bastante simple, ¿no?",
          DialogueId = 80060422,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C40FC",
          NextOptions = {
            [1] = 80060423
          },
          SpeakNpcId = 95101,
          Subtitle = "People cry when they're sad, laugh when they're happy, yell when they're upset, and eat when they're hungry... What's so complicated about that?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C40FC"
        },
        [80060423] = {
          ContentES = "A Filbert le encanta el jugo de cilantro, ¿verdad?",
          DialogueId = 80060423,
          GUID = "C86C4126",
          NextDialogue = 80060424,
          Subtitle = "Filbert loves coriander juice, right?"
        },
        [80060424] = {
          ContentES = "¡Sí! La sacerdotisa le prepara todos los días a Filbert jugo fresco de cilantro.",
          DialogueId = 80060424,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C4150",
          NextOptions = {
            [1] = 80060425
          },
          SpeakNpcId = 95101,
          Subtitle = "Mm-hmm! The priestesses make fresh coriander juice for Filbert every day!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4150"
        },
        [80060425] = {
          ContentES = "¿Y tú, Truffle? ¿Te gusta el cilantro?",
          DialogueId = 80060425,
          GUID = "C86C417A",
          NextDialogue = 80060426,
          Subtitle = "What about you, Truffle? Do you like coriander?"
        },
        [80060426] = {
          ContentES = "El sabor del cilantro es raro. Al principio se siente amargo en la lengua, pero tiene un aroma curiosito. Solo puedo comerlas si me tapo la nariz… ¡Ah, ahora lo entiendo!",
          DialogueId = 80060426,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C41A4",
          NextDialogue = 80060427,
          SpeakNpcId = 95101,
          Subtitle = "Mmm, coriander tastes weird — bitter on the tongue but strangely fragrant... I can only eat it if I hold my nose... Ah, I get it now!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41A4"
        },
        [80060427] = {
          ContentES = "A algunas personas les gusta la leche de avellanas, pero otras huyen cuando la huelen. A Filbert le gustan el cilantro, pero a mí no… Nuestra felicidad viene de cosas diferentes...",
          DialogueId = 80060427,
          GUID = "C86C41CE",
          NextDialogue = 80060428,
          SpeakNpcId = 95101,
          Subtitle = "Some people love hazelnut milk, but others hate its smell; Filbert loves coriander, but I don't... Our happiness comes from different things...",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41CE"
        },
        [80060428] = {
          ContentES = "Ya lo entiendo. Tal vez mis amigos también sienten algo parecido: hay cosas que les dan más alegría que comer, por eso pueden aguantar el hambre.",
          DialogueId = 80060428,
          FacialId = {
            [1] = "95101:Unhappy01"
          },
          GUID = "C86C41F8",
          NextDialogue = 80060429,
          SpeakNpcId = 95101,
          Subtitle = "I see... For the two friends of mine, there are things that make them much happier than a full belly makes them, so they don't mind starving.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41F8"
        },
        [80060429] = {
          ContentES = "Entonces… ¿qué más podría hacer por ellos?",
          DialogueId = 80060429,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C4222",
          NextOptions = {
            [1] = 80060430,
            [2] = 80060434
          },
          SpeakNpcId = 95101,
          Subtitle = "Then... what can I do for everyone?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4222"
        },
        [80060430] = {
          ContentES = "Ya estás haciendo algo increíble al llenar la pancita de tanta gente.",
          DialogueId = 80060430,
          GUID = "C86C424C",
          NextDialogue = 80060431,
          Subtitle = "You're already doing an amazing thing by filling so many people's bellies."
        },
        [80060431] = {
          ContentES = "¿De verdad? ¿Ya he hecho felices a muchas personas?",
          DialogueId = 80060431,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C4276",
          NextDialogue = 80060432,
          SpeakNpcId = 95101,
          Subtitle = "Really? Have I already made a lot of people happy?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4276"
        },
        [80060432] = {
          ContentES = "Sí. Para muchas personas, comer hasta llenarse no siempre los hace felices, pero no tener nada para comer, seguramente los pondría tristes.",
          DialogueId = 80060432,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C42A0",
          NextDialogue = 80060433,
          SpeakNpcId = 10001,
          Subtitle = "Yes. Being full might not necessarily mean happiness for everyone, but starving certainly means misery.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C42A0"
        },
        [80060433] = {
          ContentES = "¡Gracias! ¡Eres tan dulce! Hoy cuando recogía frutas, me caí del árbol y me di un buen golpe… pero después de oírte, ya no me duele nada.",
          DialogueId = 80060433,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C42CA",
          NextDialogue = 80060438,
          SpeakNpcId = 95101,
          Subtitle = "Thank you! You're so sweet! I fell from a tree picking plums today, but your nice words just made the pain go away!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C42CA"
        },
        [80060434] = {
          ContentES = "No puedes hacer feliz a todos. Con que tú seas feliz, ya es suficiente.",
          DialogueId = 80060434,
          GUID = "C86C42F4",
          NextDialogue = 80060435,
          Subtitle = "You can't attend to everyone; just focus on making yourself happy."
        },
        [80060435] = {
          ContentES = "¿Qué cosas me hacen feliz? Mmm… déjame pensar…",
          DialogueId = 80060435,
          GUID = "C86C431E",
          NextDialogue = 80060436,
          SpeakNpcId = 95101,
          Subtitle = "Stuff that makes me happy? Hmm, let's see...",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C431E"
        },
        [80060436] = {
          ContentES = "Ver que todos coman hasta llenarse me hace feliz… Cuando la sacerdotisa me felicita y me acaricia la cabecita también me hace muy feliz. Y cuando Filbert me roza con su naricita, ¡eso también me hace feliz! Ah, y, y… ¡hablar aquí contigo también me hace muy feliz!",
          DialogueId = 80060436,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C4348",
          NextDialogue = 80060437,
          SpeakNpcId = 95101,
          Subtitle = "I feel happy when I see everyone well-fed, when some priestess pats my head and says I did a good job, when Filbert nuzzles me with her snout, and... oh! Sitting here chatting with you makes me happy too!",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4348"
        },
        [80060437] = {
          ContentES = "Así que... si sigo siendo como ahora, ¿basta con eso?",
          DialogueId = 80060437,
          GUID = "C86C4372",
          NextDialogue = 80060438,
          SpeakNpcId = 95101,
          Subtitle = "So you're saying... I just keep doing what I'm already doing, and that's enough?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4372"
        },
        [80060438] = {
          ContentES = "...",
          DialogueId = 80060438,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C439C",
          NextDialogue = 80060439,
          SpeakNpcId = 95101,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C439C"
        },
        [80060439] = {
          ContentES = "Ay… Qué inteligente eres, yo soy algo tontita. Si ni tú sabes cómo hacer felices a todos, ¿cómo podría saberlo yo?",
          DialogueId = 80060439,
          FacialId = {
            [1] = "95101:Sad02"
          },
          GUID = "C86C43C6",
          NextDialogue = 80060440,
          SpeakNpcId = 95101,
          Subtitle = "Well... you're smart, and I'm just silly. If even you don't know how to make everyone happy, then I certainly can't figure it out.",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C43C6"
        },
        [80060440] = {
          ContentES = "Pero ya está decidido: ¡Seré una buena Comisaria de Provisiones!",
          DialogueId = 80060440,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C43F0",
          NextDialogue = 80060441,
          SpeakNpcId = 95101,
          Subtitle = "But I've made up my mind — I'll keep doing my best as a commissary!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C43F0"
        },
        [80060441] = {
          ContentES = "Tal vez no pueda alegrar a todo el mundo. Pero si darles de comer los hace un poquito más felices… entonces no estaré fallando a las enseñanzas de los dioses, ¿verdad?",
          DialogueId = 80060441,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C441A",
          NextOptions = {
            [1] = 80060442
          },
          SpeakNpcId = 95101,
          Subtitle = "Maybe I can't make everyone happy. But if filling their bellies makes them even a tiny bit happier, then I'm not failing the teachings of the gods, am I?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C441A"
        },
        [80060442] = {
          ContentES = "Sí, no hay duda de que es una labor muy noble.",
          DialogueId = 80060442,
          GUID = "C86C4444",
          NextDialogue = 80060443,
          Subtitle = "Right, it's a noble cause."
        },
        [80060443] = {
          ContentES = "Jeje… ¡gracias! Hay un montón de cosas que no entiendo. Si más adelante tengo dudas y te busco… ¿podrías seguir explicándome?",
          DialogueId = 80060443,
          GUID = "C86C446E",
          NextOptions = {
            [1] = 80060444,
            [2] = 80060446
          },
          SpeakNpcId = 95101,
          Subtitle = "Hehe... Thank you! There's so much in this world I don't understand. If I ever get confused about anything, can I still come to you?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C446E"
        },
        [80060444] = {
          ContentES = "No hay problema.",
          DialogueId = 80060444,
          GUID = "C86C4498",
          NextDialogue = 80060445,
          Subtitle = "Any time."
        },
        [80060445] = {
          ContentES = "¡Genial!",
          DialogueId = 80060445,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C44C2",
          NextDialogue = 80060449,
          SpeakNpcId = 95101,
          Subtitle = "You're the best!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C44C2"
        },
        [80060446] = {
          ContentES = "¡Una pregunta, una avellana!",
          DialogueId = 80060446,
          GUID = "C86C44EC",
          NextDialogue = 80060447,
          Subtitle = "Then I want one filbert for one question."
        },
        [80060447] = {
          ContentES = "¡Ah, eso no! Si Filbert se aleja de mí, ¡seguro que tendrá miedito!",
          DialogueId = 80060447,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C4516",
          NextDialogue = 80060448,
          SpeakNpcId = 95101,
          Subtitle = "Ah, I can't do that. Filbert would be scared without me by her side...",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4516"
        },
        [80060448] = {
          ContentES = "¡Ah, te referías a la avellana! ¡Claro! ¡Te traeré montones de avellanas para llenarte!",
          DialogueId = 80060448,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C4540",
          NextDialogue = 80060449,
          SpeakNpcId = 95101,
          Subtitle = "Oh, you meant the nut — sure! I'll bring you loads of filberts to fill you up!",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4540"
        },
        [80060449] = {
          ContentES = "¡Trato hecho! Serás {性别:el consultor|la consultora} oficial de la gran misión de Truffle y Filbert, ¡dedo meñique levantado, sellamos el pacto!",
          DialogueId = 80060449,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C456A",
          SpeakNpcId = 95101,
          Subtitle = "It's a deal then. You'll be the official consultant for the great cause of Truffle and Filbert — pinky promise!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C456A"
        },
        [80070101] = {
          Camera = "-108.692429,383.760162,74.947266,0.000002,8.799756,-69.59346,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Comandante Sibylle, he terminado de limpiar la oficina que me indicó.",
          DialogueId = 80070101,
          GUID = "C87274F2",
          NextDialogue = 80070102,
          SpeakNpcId = 790014,
          Subtitle = "Chief Sibylle, I've cleaned up the office you were using before.",
          TalkActionId = {
            [1] = "790014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87274F2"
        },
        [80070102] = {
          ContentES = "Considéralo uno de los beneficios de tu ascenso a mayor. Esa será tu nueva oficina.",
          DialogueId = 80070102,
          GUID = "C872751C",
          NextDialogue = 80070103,
          SpeakNpcId = 790013,
          Subtitle = "Consider it one of the perks of your promotion to Major. That's your workspace now.",
          TalkActionId = {
            [1] = "790014:Explain01_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872751C"
        },
        [80070103] = {
          ContentES = "Su Majestad ha aprobado personalmente tus logros. Desde capturar espías de la Iglesia Elysiana, hasta acabar con varios seguidores de los Abandonados. Sin mencionar la neutralización de grandes Filthoids. Tus méritos no han pasado desapercibidos en la corte.",
          DialogueId = 80070103,
          GUID = "C8727546",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070104,
          SpeakNpcId = 790013,
          Subtitle = "His Majesty himself approves. Your achievements — capturing spies from the Elysian Church, suppressing The Forsakens, and neutralising large Filthoids — haven't gone unnoticed by His Majesty.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727546"
        },
        [80070104] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentES = "Todo se lo debo al apoyo de la Comandante de la Legión.",
          DialogueId = 80070104,
          GUID = "C8727570",
          LookAt = {
            [1] = "790013:n(790013)"
          },
          NextDialogue = 80070105,
          SpeakNpcId = 790014,
          Subtitle = "...I owe it all to your leadership, Chief.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727570"
        },
        [80070105] = {
          ContentES = "Ahórrate tus palabras. La 13ª Legión no necesita ese tipo de adulaciones. Lo que Randy te va a enseñar debes aprenderlo con criterio y usarlo según convenga.",
          DialogueId = 80070105,
          GUID = "C872759A",
          NextDialogue = 80070106,
          SpeakNpcId = 790013,
          Subtitle = "Save it. We don't entertain sycophants in the 13th Legion. Use your head, be smart with what Randy taught you.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872759A"
        },
        [80070106] = {
          ContentES = "Maldición, otra vez volvió a tomarme el pelo.",
          DialogueId = 80070106,
          GUID = "C87275C4",
          NextDialogue = 80070107,
          SpeakNpcId = 790014,
          Subtitle = "D**n it, he's duped me again.",
          TalkActionId = {
            [1] = "790014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87275C4"
        },
        [80070107] = {
          Camera = "-118.393959,-109.984428,23.003906,0.000025,18.800102,61.800278,35.000008,369.962646,false,Manual,9.880018",
          ContentES = "Ya que estás aquí, está claro que tienes tus dudas, incluso siendo mayor. Vamos, cuéntamelas.",
          DialogueId = 80070107,
          GUID = "C87275EE",
          NextDialogue = 80070108,
          SpeakNpcId = 790013,
          Subtitle = "Since you're here, it's clear you have uncertainties, even as a Major. Let's hear them.",
          TalkActionId = {
            [1] = "790014:Sigh_End"
          },
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87275EE"
        },
        [80070108] = {
          Camera = "-16.022058,-23.41791,119.476562,0.000012,4.399871,-83.797165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así es. mientras limpiaba la oficina me encontré con algunas de tus pertenencias personales, y pensé que quizás querrías echarles un vistazo.",
          DialogueId = 80070108,
          GUID = "C8727618",
          NextDialogue = 80070109,
          SpeakNpcId = 790014,
          Subtitle = "Right, I've come across some of your personal items while clearing out the office, and I thought you might wanna have a look, Chief.",
          TalkActionId = {
            [1] = "790014:Give"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727618"
        },
        [80070109] = {
          ContentES = "Estos documentos con el emblema de la Academia Spathatoi parecen ser bastantes antiguos.",
          DialogueId = 80070109,
          GUID = "C8727642",
          NextDialogue = 80070110,
          SpeakNpcId = 790014,
          Subtitle = "These documents have the Spathatoi crest on them. They seem quite old.",
          TalkActionId = {
            [1] = "790014:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727642"
        },
        [80070110] = {
          ContentES = "Siempre has manejado personalmente los asuntos relacionados con los Spathatoi, así que no me entrometí. ¿Cómo te gustaría proceder con estos documentos, comandante?",
          DialogueId = 80070110,
          GUID = "C872766C",
          NextDialogue = 80070111,
          SpeakNpcId = 790014,
          Subtitle = "You've always dealt with matters related to the Spathatoi personally, so I didn't pry. How would you like to proceed with these documents, Chief?",
          TalkActionId = {
            [1] = "790014:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872766C"
        },
        [80070111] = {
          Camera = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
          ContentES = "Estos son... solo algunas viejas listas de artículos contrabandeados de los Spathatoi que Randy recopiló para el caso hace años. Puedes tirarlos.",
          DialogueId = 80070111,
          GUID = "C8727696",
          NextDialogue = 80070112,
          SpeakNpcId = 790013,
          Subtitle = "These are... just some old lists of smuggled items from the Spathatoi that Randy put together for the case years ago. They can be discarded now.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727696"
        },
        [80070112] = {
          Camera = "-18.71162,-52.899345,121.708984,0.000012,4.399871,-83.797165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Listas de artículos contrabandeados…? ¿Acaso no es una prueba importante?",
          DialogueId = 80070112,
          GUID = "C87276C0",
          NextDialogue = 80070113,
          SpeakNpcId = 790014,
          Subtitle = "Lists of smuggled items... Aren't these vital evidence?",
          TalkActionId = {
            [1] = "790013:Explain01_End",
            [2] = "790014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87276C0"
        },
        [80070113] = {
          Camera = "-87.774124,-53.601727,54.482422,0.000029,17.19998,61.800571,35.000008,369.962646,false,Manual,9.880018",
          ContentES = "El 13ª Legión es una unidad directamente bajo el mando de Su Majestad. Nuestras acciones se guían por objetivos, no por pruebas.",
          DialogueId = 80070113,
          FinalCamera = "-84.453262,-36.544121,59.619141,0.000028,17.19998,61.800621,35.000008,369.962646,false,Manual,9.880018",
          GUID = "C87276EA",
          NextDialogue = 80070114,
          SpeakNpcId = 790013,
          Subtitle = "The 13th Legion operates directly under His Majesty's command — our actions are guided by objectives, not by evidence.",
          TalkActionId = {
            [1] = "790014:Explain02_End",
            [2] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87276EA"
        },
        [80070114] = {
          ContentES = "Es comprensible que tengas dudas, ya que solo te has enfrentado a enemigos del exterior y aún no has tratado con problemas internos. Considero oportuno aprovechar esta ocasión para ponerte al tanto.",
          DialogueId = 80070114,
          GUID = "C8727714",
          NextDialogue = 80070115,
          SpeakNpcId = 790013,
          Subtitle = "Your confusion is understandable. Until now, your enemies have been external, and you've yet to witness the internal machinations. Let's take this chance to bring you up to speed.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727714"
        },
        [80070115] = {
          ContentES = "Cuando nuestras acciones involucran a otras organizaciones del Imperio, todo el “proceso burocrático” deja de importar. La 13ª Legión solo se enfoca en obtener los “resultados” que Su Majestad desea.",
          DialogueId = 80070115,
          GUID = "C872773E",
          IsBlack = 1,
          SpeakNpcId = 790013,
          Subtitle = "When our missions intersect with other internal organisations, the \"process\" becomes irrelevant. The 13th Legion focuses solely on achieving the \"results\" His Majesty desires.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872773E"
        },
        [80070116] = {
          Camera = "524.42627,-192.475586,223.517578,0.000009,-12.600278,160.80278,35.000008,369.962646,false,Manual,9.880018",
          ContentES = "Señor Willers, se le imputa el contrabando de equipos alquímicos en el mercado negro. ¿Se entrega voluntariamente o debemos proceder a escoltarle?",
          DialogueId = 80070116,
          FinalCamera = "532.717896,-168.658752,223.517578,0.000009,-12.600278,160.80278,35.000008,369.962646,false,Manual,9.880018",
          GUID = "C8727768",
          NextDialogue = 80070117,
          SpeakNpcId = 790015,
          Subtitle = "Mr Willers, you stand accused of smuggling alchemical equipment to the black market. Would you prefer to come quietly, or shall I assist you?",
          TalkActionId = {
            [1] = "790015:Explain01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727768"
        },
        [80070117] = {
          Camera = "-216.380081,-25.239105,134.419922,0.000003,0.599745,13.60984,35.0,100000.0,false,Manual,10.0",
          ContentES = "¡Soy un alquimista de alto renombre! ¡Aún con el respaldo de Su Majestad, la 13ª Legión no puede actuar como le plazca!",
          DialogueId = 80070117,
          GUID = "C8727792",
          NextDialogue = 80070118,
          SpeakNpcId = 790016,
          Subtitle = "I'm a senior alchemist. Even with the Emperor backing the 13th Legion, you cannot simply do as you please!",
          TalkActionId = {
            [1] = "790015:Explain01_End",
            [2] = "790016:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727792"
        },
        [80070118] = {
          Camera = "-28.744118,-95.146759,106.203125,0.000002,9.199704,137.200348,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Le conviene cuidar sus palabras. En caso de imputarse el contrabando, podría conservar la vida si tiene suerte. En casos de difamación o el cuestionamiento del mandato de Su Majestad, se le podría sancionar como alta traición.",
          DialogueId = 80070118,
          GUID = "C87277BC",
          NextDialogue = 80070119,
          SpeakNpcId = 790015,
          Subtitle = "Ssh, I'd advise you to think carefully before you speak. If this is just about smuggling, the lucky ones might still be spared. But if you slander and question His Majesty, then it would be considered treason.",
          TalkActionId = {
            [1] = "790015:Talk03_Start",
            [2] = "790016:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87277BC"
        },
        [80070119] = {
          Camera = "-216.380081,-25.239105,134.419922,0.000003,0.599745,13.60984,35.0,100000.0,false,Manual,10.0",
          ContentES = "Mmm, ¿sabes qué? Más te vale que sigas, así me ahorro el esfuerzo de escoltarlo, podría simplemente dispararte aquí mismo. Anda, sigue hablando.",
          DialogueId = 80070119,
          GUID = "C87277E6",
          NextDialogue = 80070120,
          Scripts = "SEQ{PlayAnimation{ActorId{790015},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790015},AnimationId{\"Think_Start\"},Duration{3}}}",
          SpeakNpcId = 790015,
          Subtitle = "Hmm, you know what, you might as well go on — it saves me the trouble of dragging you back — I could just shoot you on the spot. Come on, keep talking.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87277E6"
        },
        [80070120] = {
          ContentES = "No, no, por favor… Soy fiel a Su Majestad y al Imperio, nunca los traicionaría. Esos aparatos están estropeados. En vez de tirarlos pensé en venderlos para conseguir algo de dinero y comprar otros mejores...",
          DialogueId = 80070120,
          GUID = "C8727810",
          NextDialogue = 80070121,
          SpeakNpcId = 790016,
          Subtitle = "No, no... I am utterly loyal to His Majesty and the Empire... I harbour no ulterior motives... Those devices were faulty, so I thought it better to exchange them for money to buy new ones than to let them go to waste...",
          TalkActionId = {
            [1] = "790015:Think_End",
            [2] = "790016:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727810"
        },
        [80070121] = {
          Camera = "1.974182,790.534241,-2.171875,0.0,7.599726,-89.396553,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Estos aparatos son inútiles para la Academia Spathatoi pero, ¿y si acaban en manos de Los Abandonados, o incluso de Los Elysianos?",
          DialogueId = 80070121,
          FinalCamera = "1.650574,821.253418,-6.269531,0.0,7.599726,-89.396553,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C872783A",
          NextDialogue = 80070122,
          SpeakNpcId = 790013,
          Subtitle = "Those devices might be useless to the Academy, but if they end up in the hands of The Forsakens — or even worse, the Elysians — through the black market, have you considered the consequences?",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790015:n(790013)",
            [2] = "790016:n(790013)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872783A"
        },
        [80070122] = {
          Camera = "133.41275,-15.108414,77.826172,0.000001,3.799675,-114.404198,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Podrían hacer ingeniería inversa de nuestra tecnología con esos equipos descartados, lo que provocaría más bajas.",
          DialogueId = 80070122,
          GUID = "C8727864",
          NextDialogue = 80070123,
          SpeakNpcId = 790013,
          Subtitle = "They could reverse-engineer our tech through those rejects, which would lead to more casualties.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          TurnTo = {
            [1] = "790013:n(790016)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727864"
        },
        [80070123] = {
          ContentES = "El dinero que has ganado con el contrabando está manchado con la sangre de los soldados que luchan en el frente.",
          DialogueId = 80070123,
          GUID = "C872788E",
          NextDialogue = 80070124,
          SpeakNpcId = 790013,
          Subtitle = "The money you've made through smuggling is tainted with the blood of our soldiers fighting at the front.",
          TalkActionId = {
            [1] = "790013:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872788E"
        },
        [80070124] = {
          Camera = "802.744385,-2917.147705,950.736328,0.000016,-14.799558,100.006508,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "No te acusarán: ellos ya son héroes caídos, y tú no eres más que un vil buitre que revolotea en torno a sus cadáveres.",
          DialogueId = 80070124,
          GUID = "C87278B8",
          NextDialogue = 80070125,
          SpeakNpcId = 790013,
          Subtitle = "They won't accuse you, for they're fallen heroes, and you're just a vile vulture circling their corpses.",
          TalkActionId = {
            [1] = "790013:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87278B8"
        },
        [80070125] = {
          ContentES = "El Imperio no tiene necesidad de moscas que solo repiten cánticos de lealtad.",
          DialogueId = 80070125,
          GUID = "C87278E2",
          NextDialogue = 80070126,
          SpeakNpcId = 790013,
          Subtitle = "The Empire has no need for loyalty-chanting flies.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87278E2"
        },
        [80070126] = {
          ContentES = "No, por favor… En Hyperborea, ese delito no merece la pena capital… Dijiste que aún podía salvar mi vida. ¡Exijo un juicio justo!",
          DialogueId = 80070126,
          GUID = "C872790C",
          NextDialogue = 80070127,
          SpeakNpcId = 790016,
          Subtitle = "No, please... In Hyperborea, my smuggling amount wouldn't warrant a death sentence... You even said yourself I could live — I demand a fair trial!",
          TalkActionId = {
            [1] = "790016:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872790C"
        },
        [80070127] = {
          Camera = "-5.173111,14.265663,123.404297,0.000001,4.199979,-175.594803,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Yo dije: “los que tengan suerte”.",
          DialogueId = 80070127,
          GUID = "C8727936",
          NextDialogue = 800701271,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"790015:n(790016)\"}},PlayAnimation{ActorId{790015},AnimationId{\"Talk03_Start\"},Duration{2}}}",
          SpeakNpcId = 790015,
          Subtitle = "Well, I said \"the lucky ones.\"",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727936"
        },
        [80070128] = {
          Camera = "-18.071548,-70.088799,137.375,0.000012,-1.200228,-84.797432,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Perfecto! Me gusta el estilo simple y directo.",
          DialogueId = 80070128,
          FinalCamera = "-18.661856,-63.606865,137.505859,0.000012,-1.200228,-84.797432,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8727960",
          NextDialogue = 80070129,
          SpeakNpcId = 790014,
          Subtitle = "That's certainly simple and efficient.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727960"
        },
        [80070129] = {
          Camera = "-64.542519,-9.4065,79.558594,0.000028,16.399981,62.800785,35.000008,369.962646,false,Manual,9.880018",
          ContentES = "No es tan simple. La 13ª Legión solo recibe órdenes de Su Majestad. En las sombras, somos su espada oculta, pero en la luz, servimos como mensajeros de su benevolencia.",
          DialogueId = 80070129,
          GUID = "C872798A",
          NextDialogue = 80070130,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Disagree\"},Duration{2}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{3}}}",
          SpeakNpcId = 790013,
          Subtitle = "It's not that simple. The 13th Legion only takes orders from the Emperor. In the shadows, we are His Majesty's hidden blade, but in the light, we also serve as the messenger of his benevolence.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872798A"
        },
        [80070130] = {
          ContentES = "Ejecutar a un contrabandista no cerró el caso. Tenemos que enviar un mensaje a los alquimistas.",
          DialogueId = 80070130,
          GUID = "C87279B4",
          NextDialogue = 80070131,
          SpeakNpcId = 790013,
          Subtitle = "Executing a smuggler didn't close the case. We still needed to gather the alchemists together to deliver a message.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87279B4"
        },
        [80070131] = {
          Camera = "-1357.414917,-1285.646851,0.798828,0.000054,2.999491,42.001163,35.000008,369.962646,false,Manual,9.880018",
          ContentES = "Seguramente ya estaban demasiado asustados para hablar.",
          DialogueId = 80070131,
          FinalCamera = "-1393.55542,-1245.51001,0.798828,0.000054,2.999491,42.001163,35.000008,369.962646,false,Manual,9.880018",
          GUID = "C87279DE",
          NextDialogue = 80070132,
          SpeakNpcId = 790014,
          Subtitle = "I bet they were too scared to even speak.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87279DE"
        },
        [80070132] = {
          ContentES = "Es cierto. Pero no les aguardaba la muerte, sino un discurso sobre el aumento de fondos para la Academia Spathatoi… Mientras el cuerpo de Willers yacía clavado en el podio.",
          DialogueId = 80070132,
          GUID = "C8727A08",
          NextDialogue = 80070133,
          SpeakNpcId = 790013,
          Subtitle = "That was true. But what awaited them wasn't execution, but a speech announcing increased funding for the Spathatoi... With Willers's corpse nailed to the podium.",
          TalkActionId = {
            [1] = "790013:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A08"
        },
        [80070133] = {
          ContentES = "El Imperio avanza como un carro de guerra que retumba, y no puede prescindir de la Academia como su motor. Permitir que un solo acto de contrabando frene el progreso de sus investigaciones sería ir en contra de la voluntad de Su Majestad.",
          DialogueId = 80070133,
          GUID = "C8727A32",
          NextDialogue = 80070134,
          SpeakNpcId = 790013,
          Subtitle = "The Empire advances like a rumbling war chariot, and it cannot do without the academy as its engine. If we let a single act of smuggling impede the academy's research progress, that would be going against His Majesty's wishes.",
          TalkActionId = {
            [1] = "790013:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A32"
        },
        [80070134] = {
          Camera = "-108.692429,383.760162,74.947266,0.000001,8.799756,-69.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Así que vamos a dejar que los otros se salven?",
          DialogueId = 80070134,
          GUID = "C8727A5C",
          NextDialogue = 80070135,
          SpeakNpcId = 790014,
          Subtitle = "So the rest of them just got off the hook just like that?",
          TalkActionId = {
            [1] = "790014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A5C"
        },
        [80070135] = {
          ContentES = "Con un espectáculo así basta, todos deben observar el destino de los traidores al Imperio.",
          DialogueId = 80070135,
          GUID = "C8727A86",
          NextDialogue = 80070136,
          SpeakNpcId = 790013,
          Subtitle = "A spectacle of deterrence would suffice. All have witnessed the fate of those who betrayed the Empire.",
          TalkActionId = {
            [1] = "790014:Explain01_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A86"
        },
        [80070136] = {
          ContentES = "Los parásitos y ratas como Willers pasarán sus noches en constante terror. Los oportunistas respirarán aliviados, agradecidos con su prudencia por no haber cometido aún nada ilegal.",
          DialogueId = 80070136,
          GUID = "C8727AB0",
          NextDialogue = 80070137,
          SpeakNpcId = 790013,
          Subtitle = "The vermin and parasites like Willers would live in perpetual fear, dreading the knock at their doors every night. Those fence-sitters would breathe a sigh of relief, grateful for their prudence before making the wrong choice.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727AB0"
        },
        [80070137] = {
          ContentES = "Mientras tanto, los leales verán a los culpables castigados y a los virtuosos premiados, y con ello afianzarán su fe en la justicia de Su Majestad.",
          DialogueId = 80070137,
          GUID = "C8727ADA",
          NextDialogue = 80070138,
          SpeakNpcId = 790013,
          Subtitle = "While the loyal — through the purge of the sinful and the commendation of the virtuous — will further cement their faith in His Majesty's justice.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727ADA"
        },
        [80070138] = {
          Camera = "-87.774124,-53.601727,54.482422,0.000029,17.19998,61.800571,35.000008,369.962646,false,Manual,9.880018",
          ContentES = "Zanahoria y palo — la regla de oro para comandar lealtad. Debemos tolerar algunas impurezas, ajustando nuestra presión según sea necesario.",
          DialogueId = 80070138,
          GUID = "C8727B04",
          NextDialogue = 80070139,
          SpeakNpcId = 790013,
          Subtitle = "Carrot and stick — the golden rule for commanding loyalty. We must tolerate some impurities, adjusting our grip as necessary.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B04"
        },
        [80070139] = {
          Camera = "-108.692429,383.760162,74.947266,0.000001,8.799756,-69.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Demasiado complicado para mí. Tener el rango de mayor no parece tan bueno. Mejor hago algo que sí puedo manejar, como deshacerme de esta lista.",
          DialogueId = 80070139,
          GUID = "C8727B2E",
          NextDialogue = 80070140,
          SpeakNpcId = 790014,
          Subtitle = "Sounds too complicated for me to understand. I'm starting to think becoming a Major isn't all that great for me. Maybe I should stick to what I understand, like getting rid of this list.",
          TalkActionId = {
            [1] = "790014:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B2E"
        },
        [80070140] = {
          Camera = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
          ContentES = "No dejes que la presión te agobie. La 13ª Legión significa muerte para nuestros enemigos, pero es un ancla firme para nuestros aliados. Apóyate en Randy, él te ayudará a manejar los detalles.",
          DialogueId = 80070140,
          GUID = "C8727B58",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070141,
          SpeakNpcId = 790013,
          Subtitle = "Don't let the pressure overwhelm you. The 13th Legion spells death for our enemies but serves as a steadfast anchor for our allies. Take Randy — he'll help you navigate the minutiae.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B58"
        },
        [80070141] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentES = "¿Randy? Me ha tendido trampas más veces de las que puedo contar.",
          DialogueId = 80070141,
          GUID = "C8727B82",
          NextDialogue = 80070142,
          SpeakNpcId = 790014,
          Subtitle = "Randy? He's tricked me more times than I can count.",
          TalkActionId = {
            [1] = "790014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B82"
        },
        [80070142] = {
          Camera = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
          ContentES = "Su artimaña es parte de sus lecciones. Él no te haría daño de verdad. Aunque seamos pocos, la 13ª Legión reúne a los mejores guerreros y guerreras. Debes aprender a adaptarte y a ganarte la confianza de todos.",
          DialogueId = 80070142,
          GUID = "C8727BAC",
          NextDialogue = 80070143,
          SpeakNpcId = 790013,
          Subtitle = "His tricking you is also a lesson in disguise. He would never truly harm you. Though the smallest in number, the 13th Legion is composed of the forces' finest warriors. You need to learn how to blend in and build rapport with everyone.",
          TalkActionId = {
            [1] = "790014:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727BAC"
        },
        [80070143] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentES = "Entiendo, me esforzaré.",
          DialogueId = 80070143,
          GUID = "C8727BD6",
          SpeakNpcId = 790014,
          Subtitle = "Alright, I'll give it my best shot.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727BD6"
        },
        [80070201] = {
          Camera = "-178.038208,706.88324,245.560547,0.000045,-15.599693,-71.79892,25.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Comandante, ya me deshice de las listas de artículos contrabandeados. Solo queda una grabadora estropeada y una foto que usted debe revisar.",
          DialogueId = 80070201,
          FinalCamera = "-192.709595,702.058655,245.560547,0.000045,-15.599693,-71.798897,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C872855A",
          LookAt = {
            [1] = "790014:n(790013)"
          },
          NextDialogue = 80070202,
          Scripts = "MoveTo{ActorId{790014},MoveSpeed{75},TargetPoint{\"TargetPoint_430102\"}}",
          SpeakNpcId = 790014,
          Subtitle = "Chief, the lists of smuggled items have been dealt with. All that's left is a broken recorder and an old photo for your review.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872855A"
        },
        [80070202] = {
          ContentES = "Esa grabadora lleva sonando sin parar desde que la encendieron. Empiezo a sospechar que es un instrumento de tortura.",
          DialogueId = 80070202,
          GUID = "C8728584",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070203,
          SpeakNpcId = 790014,
          Subtitle = "The recorder just keeps buzzing non-stop when it's on — I almost thought it was some kind of torture device.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728584"
        },
        [80070203] = {
          Camera = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
          ContentES = "Déjala aquí. Aunque ya tengo muchas grabadoras similares, una más no hará daño.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070203,
          GUID = "C87285AE",
          NextDialogue = 80070204,
          SpeakNpcId = 790013,
          Subtitle = "Uh, that one. Just leave it here. Though I have many like it, one more won't hurt.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87285AE"
        },
        [80070204] = {
          ContentES = "Es normal que no entiendas de lo qué hablan en la grabación. Solo es el ruido de motor de un dirigible de hace más de diez años.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070204,
          GUID = "C87285D8",
          NextDialogue = 80070205,
          SpeakNpcId = 790013,
          Subtitle = "As for what's on it, it's no surprise you don't know — it's the sound of an airship engine model used over a decade ago.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87285D8"
        },
        [80070205] = {
          ContentES = "Ahora los dirigibles del Imperio priorizan la estabilidad y la duración, no como en la guerra, que solo se fijaban en la velocidad y la cantidad de munición que podían llevar.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070205,
          GUID = "C8728602",
          NextDialogue = 80070206,
          SpeakNpcId = 790013,
          Subtitle = "Modern Empire airships prioritise stability and endurance, unlike during that war when speed and firepower were all that mattered.",
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728602"
        },
        [80070206] = {
          Camera = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Supongo que se refiere a la batalla conocida como “la Elegía de los Dioses” contra la Iglesia Elysiana de hace 23 años. En esa batalla, la 13ª Legión asaltó su torre abordo de prototipos de aeronave. Esa hazaña es tan famosa que hasta los niños se la saben, no dudo que hasta puedan recitar un par de versos.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070206,
          GUID = "C872862C",
          NextDialogue = 80070207,
          Scripts = "SEQ{PlayAnimation{ActorId{790014},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790014},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790014,
          Subtitle = "You mean the \"Divine Elegy\" offensive against the Elysian Church more than 20 years ago, right? In that battle, the 13th Legion stormed their tower in prototype airships. That's a story even kids in the street can sing a verse or two about.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872862C"
        },
        [80070207] = {
          ContentES = "Y gracias a esos méritos usted se convirtió en la Comandante de Legión más joven de todo el Imperio.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070207,
          GUID = "C8728656",
          NextDialogue = 80070208,
          SpeakNpcId = 790014,
          Subtitle = "And it was your valour in that battle that made you the youngest chief in Empire history.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728656"
        },
        [80070208] = {
          Camera = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
          ContentES = "La 13ª Legión esquivó la zona de fuego cruzado, asaltó la torre jamás pisada y llegó por primera vez al santuario de los “Dioses”. Sin duda, algo digno de ser cantado en una elegía.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070208,
          GUID = "C8728680",
          NextDialogue = 80070209,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Think_Start\"},Duration{2}},PlayAnimation{ActorId{790013},AnimationId{\"Think_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Agree\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "...Mm, we bypassed the hot zone at the border and struck directly at their normally untouchable tower, reaching the gods' lair for the first time. It's a tale worth retelling indeed.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728680"
        },
        [80070209] = {
          ContentES = "Pero para la 13ª Legión, incluso para mí, esa batalla no significó la gloria… sino ira y humillación.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070209,
          GUID = "C87286AA",
          NextDialogue = 80070210,
          SpeakNpcId = 790013,
          Subtitle = "But for the 13th Legion — or more precisely, for me — the campaign brought not only glory but also... anger and shame.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87286AA"
        },
        [80070210] = {
          ContentES = "Los doce oficiales que entraron en la torre perecieron. De no haber permanecido en el dirigible exterior, hoy solo sería un número más en la lista de bajas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070210,
          GUID = "C87286D4",
          NextDialogue = 80070211,
          SpeakNpcId = 790013,
          Subtitle = "All 12 officers who attacked the tower were killed. Had I not been left to guard the airship outside, I might just be another number on the casualty list.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87286D4"
        },
        [80070211] = {
          Camera = "-63.415112,74.612396,161.78125,0.000025,-23.199345,52.011242,35.000008,453.595306,false,DoNotOverride,8.167668",
          ContentES = "Detrás de la gloria, se oculta nuestra amarga derrota.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070211,
          GUID = "C87286FE",
          NextDialogue = 80070212,
          SpeakNpcId = 790013,
          Subtitle = "Behind the glory was our grievous defeat.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87286FE"
        },
        [80070212] = {
          ContentES = "Lo último que puedo recordar es que yo pilotaba aquel dirigible fuera de control, llevando conmigo a otro… camarada, con heridas graves, a través de la lluvia de artillería y proyectiles mágicos, cruzando la línea fronteriza.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070212,
          GUID = "C8728728",
          NextDialogue = 80070213,
          SpeakNpcId = 790013,
          Subtitle = "My last memory of that battle is piloting an out-of-control airship, weaving through relentless artillery fire and magical barrages across the border.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728728"
        },
        [80070213] = {
          ContentES = "Esta grabación me transporta de nuevo a aquel instante en el dirigible. Vuelven a mi mente el olor a sangre y el zumbido de ese viejo motor.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070213,
          GUID = "C8728752",
          NextDialogue = 80070214,
          SpeakNpcId = 790013,
          Subtitle = "This recording takes me back to that airship... to that moment. It reminds me of the smell of blood in my nose and the weary roar of the engines in my ears.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728752"
        },
        [80070214] = {
          Camera = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eso explica por qué siempre eliges el lugar más cercano al motor en el dirigible.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070214,
          GUID = "C872877C",
          NextDialogue = 80070215,
          SpeakNpcId = 790014,
          Subtitle = "That explains why you always choose the spot closest to the engine on flights.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872877C"
        },
        [80070215] = {
          Camera = "-1015.568604,-969.672852,166.992188,0.0,-4.99948,47.392773,35.000008,100000.0,false,Manual,2.8",
          ContentES = "La guerra es así, nos cambia a todos.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070215,
          FinalCamera = "-985.23938,-936.698364,163.091797,0.0,-4.99948,47.392773,35.000008,100000.0,false,Manual,2.8",
          GUID = "C87287A6",
          NextDialogue = 80070216,
          SpeakNpcId = 790013,
          Subtitle = "This is war. It changes people.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87287A6"
        },
        [80070216] = {
          ContentES = "He visto a demasiados soldados en hospitales, todavía atormentados por la guerra mucho tiempo después de haber dejado el frente. A veces, los fuegos artificiales o incluso una pistola de juguete puede provocarles una crisis nerviosa.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070216,
          GUID = "C87287D0",
          NextDialogue = 80070217,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "I've seen too many soldiers in hospitals, still haunted by the war long after leaving the front. Sometimes, a ceremonial cannon or even a child's toy gun can trigger a breakdown.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87287D0"
        },
        [80070217] = {
          ContentES = "La guerra deja su huella incluso en los más fuertes. Solo basta fijarse en el Comandante de la 11ª Legión que tiene su destacamento en la frontera, siempre duerme con un ojo abierto.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070217,
          GUID = "C87287FA",
          NextDialogue = 80070218,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Explain02_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "War leaves its mark even on the toughest among us. Take the Chief of the 11th Legion stationed at the border, who sleeps with one eye open.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87287FA"
        },
        [80070218] = {
          Camera = "-63.415112,74.612396,161.78125,0.000025,-23.199345,52.011242,35.000008,453.595306,false,DoNotOverride,8.167668",
          ContentES = "Tuvieron que contener la mayor parte de las tropas de Elysium en la frontera y soportaban la misma presión y bajas que nosotros.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070218,
          GUID = "C8728824",
          NextDialogue = 80070219,
          SpeakNpcId = 790013,
          Subtitle = "In that campaign, their forces held off the bulk of the Elysian army at the border, bearing just as much burden and bloodshed as we did.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728824"
        },
        [80070219] = {
          Camera = "-9.893036,212.023102,120.853516,0.000003,-4.000004,-89.204086,45.0,100000.0,false,Manual,16.970627",
          ContentES = "¿Ese es el motivo por el que reproduce la grabación una y otra vez? ¿Se culpa de la muerte de sus compañeros?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070219,
          GUID = "C872884E",
          NextDialogue = 80070220,
          SpeakNpcId = 790014,
          Subtitle = "Is that why you replay this recording over and over? Out of guilt over your comrades' deaths?",
          TalkActionId = {
            [1] = "790014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872884E"
        },
        [80070220] = {
          Camera = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
          ContentES = "No, solo es para mantenerme despierta. Cuando me entra sueño, esto me ayuda a concentrarme.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070220,
          GUID = "C8728878",
          NextDialogue = 80070221,
          SpeakNpcId = 790013,
          Subtitle = "No, just to keep myself sharp. When I feel tired, it helps me focus.",
          TalkActionId = {
            [1] = "790014:Explain02_End",
            [2] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728878"
        },
        [80070221] = {
          ContentES = "Muchos se lamentan por sus fracasos, se sienten impotentes, atrapados en la culpa, y ven el fracaso como castigo. Este es el instinto y el privilegio de los débiles.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070221,
          GUID = "C87288A2",
          NextDialogue = 80070222,
          SpeakNpcId = 790013,
          Subtitle = "Many dwell on past failures, lamenting their impotence, wallowing in guilt, and torturing themselves — this is the instinct and privilege of the weak.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87288A2"
        },
        [80070222] = {
          Camera = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
          ContentES = "Pero para mí, el fracaso es como una vieja cicatriz: duele, sí, pero me mantiene alerta y me obliga a seguir adelante. Y entre el dolor y la humillación, me empuja a alcanzar la victoria.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070222,
          GUID = "C87288CC",
          NextDialogue = 80070223,
          SpeakNpcId = 790013,
          Subtitle = "But to me, failure is the scar of the past. It's a harsh reminder for me to keep pushing, to climb from all the pain and shame to victory.",
          TalkActionId = {
            [1] = "790013:Talk03_End",
            [2] = "790014:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87288CC"
        },
        [80070223] = {
          ContentES = "Aprecio lo que sacrificaron mis compañeros, así que no puedo permitirme caer como ellos. Ponerme a descansar o recordar a los muertos antes de haber logrado la victoria sería desaprovechar su sacrificio.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070223,
          GUID = "C87288F6",
          NextDialogue = 80070224,
          SpeakNpcId = 790013,
          Subtitle = "I honour my comrades' sacrifices, which is precisely why I refuse to fall as they did. Pausing for breath or to mourn the fallen before claiming final victory would only squander their sacrifices.",
          TalkActionId = {
            [1] = "790014:Think_End",
            [2] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87288F6"
        },
        [80070224] = {
          Camera = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Muchos me dicen insensible, inhumana, y algunos incluso mencionan mis humildes orígenes, piensan que a crueldad corre por la sangre de los Charon.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070224,
          GUID = "C8728920",
          NextDialogue = 80070225,
          SpeakNpcId = 790013,
          Subtitle = "Many call me cold-hearted, and some even cite my humble origins, claiming that cruelty is in my Charon blood.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728920"
        },
        [80070225] = {
          ContentES = "Al final, olvidarían los fracasos e incluso los nombres de los caídos. Como si fueran insectos zumbando antes de perecer, mientras que yo sigo ascendiendo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070225,
          GUID = "C872894A",
          NextDialogue = 80070226,
          SpeakNpcId = 790013,
          Subtitle = "But in the end, they'd forget the failures and even the names of the fallen, just buzzing like bugs before they perish.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872894A"
        },
        [80070226] = {
          Camera = "-56.278519,-30.622166,132.205078,0.000009,-9.000037,-85.60675,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Al final, solo quedo yo, sin olvidar la vergüenza y el fracaso, y escalando siempre hacia la cima.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070226,
          GUID = "C8728974",
          NextDialogue = 80070227,
          SpeakNpcId = 790013,
          Subtitle = "All that remains is me, bearing the scars of defeat, continually climbing upward.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728974"
        },
        [80070227] = {
          ContentES = "En mi opinión, usted está ya en lo alto, muchos se esfuerzan toda la vida sin alcanzarlo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070227,
          GUID = "C872899E",
          NextDialogue = 80070228,
          SpeakNpcId = 790014,
          Subtitle = "From my perspective, Chief, you've already reached heights many can't even dream of...",
          TalkActionId = {
            [1] = "790014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872899E"
        },
        [80070228] = {
          Camera = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
          ContentES = "No, no basta. La 13ª Legión lleva consigo un “verdadero ideal” que el mundo aún desconoce.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070228,
          GUID = "C87289C8",
          NextDialogue = 80070229,
          SpeakNpcId = 790013,
          Subtitle = "No, it's not enough. The 13th Legion bears a \"true ideal\" not yet known to the world.",
          TalkActionId = {
            [1] = "790014:Explain02_End",
            [2] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87289C8"
        },
        [80070229] = {
          Camera = "-1154.983398,-1628.61377,1072.589844,0.000071,-26.199942,47.398281,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Muchos de los que viven bajo el apellido de sus familias, nacen con el poder en sus manos y se regocijan en fama y gloria. Solo miran hacia abajo, y viven planeando cómo derribar a los que llevan el verdadero ideal.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070229,
          FinalCamera = "-1186.510742,-1599.621582,1072.589844,0.000071,-26.199942,47.398281,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C87289F2",
          NextDialogue = 80070230,
          SpeakNpcId = 790013,
          Subtitle = "Some of those born into privilege have long been drunk with fame, power, and glory. They only look downward, always plotting to shove those bearing true ideals off the cliff.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87289F2"
        },
        [80070230] = {
          ContentES = "Los nobles que apenas pueden montar o entender lo básico del mando, no deberían existir en este país.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070230,
          GUID = "C8728A1C",
          NextDialogue = 80070231,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "Nobles who can barely ride or understand the basics of command don't belong in this country.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A1C"
        },
        [80070231] = {
          Camera = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
          ContentES = "No puedo estancarme como ellos. Debo ascender más alto y alcanzar el poder supremo.",
          DialogueId = 80070231,
          GUID = "C8728A46",
          LookAt = {
            [1] = "790013:n(790013)"
          },
          NextDialogue = 80070232,
          SpeakNpcId = 790013,
          Subtitle = "I cannot afford to mark time like they do. I must climb higher, to the utmost power.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A46"
        },
        [80070232] = {
          Camera = "-83.885132,575.331421,43.728516,0.0,8.799899,-79.398201,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Cuando llegue el momento, no solo guiaré al Imperio de Hyperborea, si no a toda la humanidad, hacia un nuevo futuro. ¿Comprendes, Lynn?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070232,
          FinalCamera = "-90.078613,608.423706,38.511719,0.0,8.799899,-79.398201,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8728A70",
          NextDialogue = 80070233,
          Scripts = "SEQ{MoveTo{ActorId{790013},MoveSpeed{75},TargetPoint{\"TargetPoint_43010201\"}},LookAt{_delay{2},LookAtDescription{\"790013:n(790014)\"}}}",
          SpeakNpcId = 790013,
          Subtitle = "When that time comes, we shall lead the Hyperborean Empire — no, all of humanity, into a new tomorrow. Do you understand, Lynn?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A70"
        },
        [80070233] = {
          ContentES = "Para serle honesta, no comprendí del todo. Usted sabe que vine aquí solo para ganarme la vida, no tenía muchas opciones.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070233,
          GUID = "C8728A9A",
          NextDialogue = 80070234,
          SpeakNpcId = 790014,
          Subtitle = "Honestly, I didn't quite follow. You know, I'm just here for the cash — didn't have much choice.",
          TalkActionId = {
            [1] = "790014:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A9A"
        },
        [80070234] = {
          Camera = "-85.702591,-181.152481,118.537109,0.000021,-1.599391,69.810509,45.0,453.595306,false,Manual,8.167668",
          ContentES = "Pero si estás diciendo que se avecinan grandes cambios... Cuando llegue el momento, seguramente tendré que luchar para proteger a mi familia, no me quedará otra opción.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070234,
          GUID = "C8728AC4",
          NextDialogue = 80070235,
          SpeakNpcId = 790014,
          Subtitle = "But if you're saying big changes are coming... Then when they do, I'll definitely fight my hardest to protect my family — didn't have much choice on that either.",
          TalkActionId = {
            [1] = "790014:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728AC4"
        },
        [80070235] = {
          Camera = "-17.806854,326.852264,116.085938,0.000009,2.799769,-82.405029,45.0,80.247894,false,DoNotOverride,16.970627",
          ContentES = "Aprecio tu sinceridad, Lynn. Por humilde que sea, tienes algo por lo que vale la pena luchar, eso es lo único que importa.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070235,
          GUID = "C8728AEE",
          Scripts = "LookAt{_delay{2},LookAtDescription{\"790013:n(790013)\"}}",
          SpeakNpcId = 790013,
          Subtitle = "I appreciate your candour, Lynn. However modest, you have something worth fighting for — that's all that matters.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728AEE"
        },
        [80070301] = {
          Camera = "1179.431641,-1065.483887,93.511719,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ya guardé la grabadora. La foto… es de mi maestra y de mi ingenua camarada de antaño.",
          DialogueId = 80070301,
          FinalCamera = "1156.185791,-1092.036255,93.511719,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C87295C2",
          NextDialogue = 80070302,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          SpeakNpcId = 790013,
          Subtitle = "I've taken care of the recorder. As for the photo… it's of my teacher and that naive fellow pupil of mine, right?",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87295C2"
        },
        [80070302] = {
          Camera = "32.871628,241.033554,128.292969,0.000024,-4.399693,-100.193977,45.000011,419.787506,false,Manual,10.901892",
          ContentES = "¿Por qué llama a todos ingenuos, Comandante?",
          DialogueId = 80070302,
          GUID = "C87295EC",
          NextDialogue = 80070303,
          SpeakNpcId = 790014,
          Subtitle = "Why do you call everybody naive, Chief?",
          TalkActionId = {
            [1] = "790013:Explain01_End",
            [2] = "790014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87295EC"
        },
        [80070303] = {
          ContentES = "Ja... sí, lo mismo he dicho de ti. Pero su ingenuidad era diferente a la tuya. Ella era otra alumna de mi maestra, con un corazón notablemente puro.",
          DialogueId = 80070303,
          GUID = "C8729616",
          NextDialogue = 80070304,
          SpeakNpcId = 790013,
          Subtitle = "Ha, yes, I've said the same about you. But her naivety was different to yours. She was another pupil of my teacher, with a remarkably pure heart.",
          TalkActionId = {
            [1] = "790014:Sigh_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729616"
        },
        [80070304] = {
          Camera = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
          ContentES = "Incluso dentro de la Academia Spathatoi, ella tenía fantasías poco realistas sobre la alquimia. La primera vez que me vio, nos preguntó a mí y a la maestra si la alquimia haría que todos vivieran mejor.",
          DialogueId = 80070304,
          GUID = "C8729640",
          NextDialogue = 80070305,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0067_story_daphnis_theme_piano\"}}",
          SpeakNpcId = 790013,
          Subtitle = "Even within the Spathatoi, she held onto some rather fanciful ideas about alchemy. I remember the first time I met her, she asked me and our teacher: \"Alchemy will make everyone's life better, right?\"",
          TalkActionId = {
            [1] = "790013:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729640"
        },
        [80070305] = {
          ContentES = "¿Tú qué opinas, Lynn?",
          DialogueId = 80070305,
          GUID = "C872966A",
          NextDialogue = 80070306,
          SpeakNpcId = 790013,
          Subtitle = "So, what do you think of alchemy, Lynn?",
          TalkActionId = {
            [1] = "790013:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872966A"
        },
        [80070306] = {
          Camera = "32.871628,241.033554,128.292969,0.000024,-4.399693,-100.193977,45.000011,419.787506,false,Manual,10.901892",
          ContentES = "Tecnología sofisticada. Nunca la he usado.",
          DialogueId = 80070306,
          GUID = "C8729694",
          NextDialogue = 80070307,
          SpeakNpcId = 790014,
          Subtitle = "Some fancy tech. I've never really used it myself.",
          TalkActionId = {
            [1] = "790014:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729694"
        },
        [80070307] = {
          Camera = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
          ContentES = "Jeje, nuestros antepasados refinaron la alquimia hasta convertirla en la base de la vida del Imperio. La has estado usando sin darte cuenta.",
          DialogueId = 80070307,
          GUID = "C87296BE",
          NextDialogue = 80070308,
          SpeakNpcId = 790013,
          Subtitle = "Haha, our ancestors had long ago refined alchemy into the very foundation of the Empire's lifestyle. You've been using it all along. You just didn't realise it.",
          TalkActionId = {
            [1] = "790013:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87296BE"
        },
        [80070308] = {
          Camera = "24.780663,-23.754013,119.826172,0.000024,-1.399649,-100.595001,45.0,100000.0,false,DoNotOverride,10.901892",
          ContentES = "Por ejemplo, tanto las balas como las armas que empleas son creación alquímica.",
          DialogueId = 80070308,
          GUID = "C87296E8",
          NextDialogue = 80070309,
          SpeakNpcId = 790013,
          Subtitle = "Take the bullets and firearms you use — they are one of the products of alchemical technology.",
          TalkActionId = {
            [1] = "790013:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87296E8"
        },
        [80070309] = {
          ContentES = "¿De verdad? Vaya, yo seguro estaría perdida sin mis armas. Los que estudian alquimia deben de ser unos académicos muy talentosos.",
          DialogueId = 80070309,
          GUID = "C8729712",
          NextDialogue = 80070310,
          Scripts = "SEQ{PlayAnimation{ActorId{790014},AnimationId{\"Think_Start\"},Duration{2}},PlayAnimation{ActorId{790014},AnimationId{\"Think_End\"},Duration{1}}}",
          SpeakNpcId = 790014,
          Subtitle = "Really? Huh, well, I'd sure be lost without my guns. Those alchemists must be some talented scholars.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729712"
        },
        [80070310] = {
          Camera = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
          ContentES = "Sí, la mayoría piensa como tú. Los alquimistas quizá sean extraños, pero sus inventos están transformando poco a poco el país.",
          DialogueId = 80070310,
          GUID = "C872973C",
          NextDialogue = 80070311,
          SpeakNpcId = 790013,
          Subtitle = "Most would agree. Alchemists might be a bit eccentric, but their inventions have been steadily transforming this country.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872973C"
        },
        [80070311] = {
          ContentES = "Mi maestra me decía que la alquimia era una ciencia capaz de cambiar el futuro del Imperio, mi camarada creía que era la llave que traería la paz y la esperanza.",
          DialogueId = 80070311,
          GUID = "C8729766",
          NextDialogue = 80070312,
          SpeakNpcId = 790013,
          Subtitle = "My teacher always said alchemy was a profound science that would change the future of the Empire. While my fellow pupil believed it was the key to peace and hope.",
          TalkActionId = {
            [1] = "790013:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729766"
        },
        [80070312] = {
          Camera = "-0.956041,3.409428,92.585938,0.000023,10.400335,91.608727,45.0,100000.0,false,DoNotOverride,10.901892",
          ContentES = "Pero para mí, la alquimia es algo más práctico: una escalera para ascender al poder.",
          DialogueId = 80070312,
          GUID = "C8729790",
          NextDialogue = 80070313,
          SpeakNpcId = 790013,
          Subtitle = "But for me, alchemy is something more pragmatic — a tool for climbing the ladder of power.",
          TalkActionId = {
            [1] = "790013:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729790"
        },
        [80070313] = {
          ContentES = "Fueron mis habilidades alquímicas las que llamaron la atención de Su Majestad. Gracias a mi lealtad y capacidad, fui nombrada como una de las oficiales participantes en la batalla de la “Elegía de los Dioses”.",
          DialogueId = 80070313,
          GUID = "C87297BA",
          NextDialogue = 80070314,
          SpeakNpcId = 790013,
          Subtitle = "It was my alchemy skills, coupled with my loyalty and competence, that first got the Emperor's attention, making me a key player in the Divine Elegy offensive.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87297BA"
        },
        [80070314] = {
          ContentES = "Cuando estaba en la Academia Spathatoi, obtuve calificaciones perfectas en todas las materias, pero nunca invertí mi tiempo en la investigación. Simplemente no me interesaban los conocimientos teóricos.",
          DialogueId = 80070314,
          GUID = "C87297E4",
          NextDialogue = 80070315,
          SpeakNpcId = 790013,
          Subtitle = "I aced every subject at the academy but never really poured my heart into any research. The deep theoretical knowledge just didn't resonate with me.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87297E4"
        },
        [80070315] = {
          ContentES = "Eso enfureció a mi maestra, y hasta dijo en la graduación que jamás dominaría el verdadero conocimiento. Pero, a lo largo de la historia, ¿cuántos realmente lo han comprendido?",
          DialogueId = 80070315,
          GUID = "C872980E",
          NextDialogue = 80070316,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Disagree\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "That infuriated my teacher. At the graduation ceremony, she even said that I would never grasp true knowledge. But riddle me this — how many have truly understood knowledge and truth through the ages?",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872980E"
        },
        [80070316] = {
          Camera = "68.550446,-309.161438,92.363281,0.000028,-0.200043,106.210724,45.000011,450.975708,false,Manual,5.23506",
          ContentES = "¿Y ahora dónde estarán?",
          DialogueId = 80070316,
          GUID = "C8729838",
          NextDialogue = 80070317,
          Scripts = "TurnTo{TurnToDescription{\"790013:p(180)\"}}",
          SpeakNpcId = 790013,
          Subtitle = "And where are they now?",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729838"
        },
        [80070317] = {
          ContentES = "Después de tanto tiempo, si ella me preguntara de nuevo, mi respuesta seguiría siendo la misma. Lástima que ya no existe posibilidad alguna.",
          DialogueId = 80070317,
          GUID = "C8729862",
          NextDialogue = 80070318,
          Scripts = "PlayAnimation{_delay{2},ActorId{790013},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 790013,
          Subtitle = "After all this time, if she were to ask me that question again, my answer would still be the same. Only now, there's no chance of that.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729862"
        },
        [80070318] = {
          Camera = "42.315338,214.12384,94.9375,-0.0,-0.600128,-103.201942,35.000015,384.64978,false,Manual,7.401211",
          ContentES = "Ah, escuché a Randy decir que la Primera Alquimista ha fallecido, y que su relación con su estrella alumna era... complicada.",
          DialogueId = 80070318,
          GUID = "C872988C",
          NextDialogue = 80070319,
          SpeakNpcId = 790014,
          Subtitle = "Right, I heard from Randy that the chief alchemist has passed away and that her relationship with her star pupil was... complicated.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872988C"
        },
        [80070319] = {
          ContentES = "Sí, lo más triste es que la maestra nunca volvió a ver a su alumna favorita antes de morir, es decir, a mi camarada. Solo yo y... unos cuantos cuervos estuvimos fuera del hospital.",
          DialogueId = 80070319,
          GUID = "C87298B6",
          NextDialogue = 80070320,
          SpeakNpcId = 790013,
          Subtitle = "Yes. Sadly, even when my teacher passed away, her favourite student — my fellow pupil — never showed up. It was just me there... along with a few ominous crows outside the hospital room.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87298B6"
        },
        [80070320] = {
          ContentES = "Lo más triste es que nunca resolvió la fórmula que personificaba la verdad. Su monumental investigación terminó como garabatos indescifrables.",
          DialogueId = 80070320,
          GUID = "C87298E0",
          NextDialogue = 80070321,
          SpeakNpcId = 790013,
          Subtitle = "What's sadder is that she never solved the formula that epitomized truth. Her monumental research ended up as indecipherable scribbles.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87298E0"
        },
        [80070321] = {
          Camera = "149.89209,-233.861969,6.462891,0.000063,12.797854,113.801712,35.000008,100000.0,false,DoNotOverride,7.401211",
          ContentES = "La maestra confió sus ideales y ambiciones a mi camarada, antes de caer en la incansable búsqueda de la verdad. ¿Y qué hizo ella...?",
          DialogueId = 80070321,
          FinalCamera = "132.743332,-194.975647,16.105469,0.000063,12.797854,113.801628,35.000011,100000.0,false,DoNotOverride,7.401211",
          GUID = "C872990A",
          NextDialogue = 80070322,
          SpeakNpcId = 790013,
          Subtitle = "She entrusted her ideals and dreams to her, collapsing in her pursuit of truth. And what did she do?",
          TalkActionId = {
            [1] = "790013:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872990A"
        },
        [80070322] = {
          ContentES = "Abandonó su estatus y recursos, desperdiciando su talento en un campo completamente alejado de la alquimia.",
          DialogueId = 80070322,
          GUID = "C8729934",
          NextDialogue = 80070323,
          SpeakNpcId = 790013,
          Subtitle = "She abandoned her prospects and resources, wasting her talents in a completely different field.",
          TalkActionId = {
            [1] = "790013:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729934"
        },
        [80070323] = {
          Camera = "19.332775,-55.147057,119.476562,0.000024,0.000417,-99.596123,45.0,100000.0,false,DoNotOverride,10.901892",
          ContentES = "¿No había dicho que uno no debía aferrarse al pasado?",
          DialogueId = 80070323,
          FacialId = {
            [1] = "790013:None"
          },
          GUID = "C872995E",
          NextDialogue = 80070324,
          SpeakNpcId = 790014,
          Subtitle = "Didn't you say you don't dwell on the past?",
          TalkActionId = {
            [1] = "790014:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872995E"
        },
        [80070324] = {
          Camera = "68.539764,281.670898,93.375,0.0,5.399783,-108.200027,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, pero eso no significa que no tenga sentimientos. Cada vez que me acuerdo, me inundan una mezcla de ira, confusión, arrepentimiento e incluso celos.",
          DialogueId = 80070324,
          GUID = "C8729988",
          NextDialogue = 80070325,
          SpeakNpcId = 790013,
          Subtitle = "I did, but that doesn't mean I'm devoid of feelings. Every time I look back, I'm overwhelmed by a mix of anger, confusion, regret, and even jealousy.",
          TalkActionId = {
            [1] = "790014:Explain01L_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729988"
        },
        [80070325] = {
          ContentES = "Siempre supe que no era una de sus mejores estudiantes, aquellas que tenían sus sueños, sus ambiciones y perspectivas ilimitadas.",
          DialogueId = 80070325,
          GUID = "C87299B2",
          NextDialogue = 80070326,
          SpeakNpcId = 790013,
          Subtitle = "I always knew I wasn't one of her best students, who had their dreams, their ambitions, and limitless prospects.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87299B2"
        },
        [80070326] = {
          Camera = "93.881493,148.724472,103.033203,-0.000001,9.39976,-174.598511,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero también sabía que sería la alumna que acompañaría a la maestra hasta el final de su vida.",
          DialogueId = 80070326,
          FacialId = {
            [1] = "790013:None"
          },
          GUID = "C87299DC",
          NextDialogue = 80070327,
          SpeakNpcId = 790013,
          Subtitle = "But I know I'll be the one who makes it to the end.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87299DC"
        },
        [80070327] = {
          Camera = "68.550446,-309.161438,92.363281,0.000028,-0.200043,106.210785,45.000011,451.021332,false,Manual,5.197097",
          ContentES = "Por cierto. Sé que no vas a decir nada, pero igual quiero advertirte. Lo que te he contado hoy, no debe saberlo nadie.",
          DialogueId = 80070327,
          GUID = "C8729A06",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070328,
          SpeakNpcId = 790013,
          Subtitle = "By the way, though I know you wouldn't mention this conversation to anyone, I still have to remind you to keep it between us.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A06"
        },
        [80070328] = {
          Camera = "28.509796,241.818237,128.292969,0.000024,-3.59966,-101.194298,45.0,100000.0,false,Manual,16.626261",
          ContentES = "Sí, sí, lo entiendo, y tampoco tengo a quién contárselo. Pero, Comandante, si no quiere que nadie se entere, ¿por qué me lo cuenta a mí?",
          DialogueId = 80070328,
          GUID = "C8729A30",
          NextDialogue = 80070329,
          SpeakNpcId = 790014,
          Subtitle = "Understood! I don't really have anyone to talk to anyway. But I'm curious, Chief — if you don't want anyone to know, why share all this with me?",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A30"
        },
        [80070329] = {
          ContentES = "Porque eres la persona más adecuada para esto. Sé que no te importa, que tampoco entiendes estas historias y emociones complejas, ni dirías palabras vacías de consuelo, sean sinceras o fingidas.",
          DialogueId = 80070329,
          GUID = "C8729A5A",
          NextDialogue = 80070330,
          SpeakNpcId = 790013,
          Subtitle = "Because you're the right person for this. I know you don't care about nor understand those complex past events and emotions, and you're not one to offer empty sympathies, sincere or not.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A5A"
        },
        [80070330] = {
          Camera = "20.92244,-217.006439,116.833984,0.000028,-1.999476,97.407928,45.000011,359.358795,false,Manual,10.901892",
          ContentES = "Nunca he necesitado de la simpatía o el consuelo de nadie.",
          DialogueId = 80070330,
          GUID = "C8729A84",
          NextDialogue = 80070331,
          SpeakNpcId = 790013,
          Subtitle = "I've never needed any sympathy or pity from anyone.",
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A84"
        },
        [80070331] = {
          ContentES = "Al final, las personas solo pueden confiar en aquello que está en sus propias manos, y creo que tú también lo comprendes.",
          DialogueId = 80070331,
          GUID = "C8729AAE",
          NextDialogue = 80070332,
          SpeakNpcId = 790013,
          Subtitle = "All we can truly rely on is what we wield. I think you understand that too.",
          TalkActionId = {
            [1] = "790013:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729AAE"
        },
        [80070332] = {
          Camera = "1185.878418,-1058.124756,135.4375,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eso será todo por hoy. Si algún día necesitas alguien con quien hablar, puedes contar conmigo.",
          DialogueId = 80070332,
          FinalCamera = "1255.99585,-1119.513062,135.765625,0.0,-0.200466,138.797638,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8729AD8",
          NextDialogue = 80070333,
          SpeakNpcId = 790013,
          Subtitle = "That will be all for today. If you ever feel lost, you're welcome to talk to me.",
          TalkActionId = {
            [1] = "790013:Angry01_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729AD8"
        },
        [80070333] = {
          ContentES = "No sé consolar tus emociones, pero puedo darte los medios para resolver tus dudas.",
          DialogueId = 80070333,
          GUID = "C8729B02",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0067_story_daphnis_theme_piano\"}}",
          SpeakNpcId = 790013,
          Subtitle = "While I may not offer comfort, I can guide you through resolving your doubts.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729B02"
        },
        [80080101] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Nunca había visto un Filthoid tan enorme… Mi cabeza daba vueltas y no podía moverme. Sabía que algún día regresaría al Mar Nebuloso y al regazo de la Gran Diosa Madre, pero no esperaba que ese día llegara tan pronto.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080101,
          GUID = "C878DD92",
          NextDialogue = 80080102,
          SpeakNpcId = 790004,
          Subtitle = "I'd never seen such a huge Filthoid before... My head was spinning, and I couldn't move my arms or legs. I knew I'd soon be returning to the Misty Sea and the bosom of Mother Embla, but I didn't expect that day to come so soon.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DD92"
        },
        [80080102] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces, {性别: él|ella} “¡zaz!” se lanzó y, cuando abrí los ojos, ¡ya estaba justo frente a mí!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080102,
          GUID = "C878DDBC",
          NextDialogue = 80080103,
          SpeakNpcId = 790004,
          Subtitle = "Then — {性别:he|she} suddenly charged forward. When I opened my eyes, {性别:he|she} was already shielding me from that Filthoid!",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DDBC"
        },
        [80080103] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "{性别: Él|Ella} no era particularmente fuerte, pero se enfrentó con valentía al Filthoid, sin retroceder ni un centímetro…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080103,
          GUID = "C878DDE6",
          NextDialogue = 80080104,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Disagree\"},Duration{2}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} wasn't exactly strong, but {性别:he|she} bravely stared down the Filthoid, not backing down an inch...",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DDE6"
        },
        [80080104] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y entonces ese gigante Filthoid les arremetió con fuerza, y ustedes dos cayeron al suelo. Pero lucharon codo a codo y lograron derribarlo. Después apareció un hombre llamado Outsider. Y luego...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080104,
          GUID = "C878DE10",
          NextDialogue = 80080105,
          SpeakNpcId = 790002,
          Subtitle = "And then that giant Filthoid leapt up, slammed down, and you both fell. Then you fought side by side and took it down. Then a man named Outsider popped up. And then—",
          TalkActionId = {
            [1] = "790002:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE10"
        },
        [80080105] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Ay, Elisa! ¡Sin spoilers, por favor!",
          DialogueId = 80080105,
          GUID = "C878DE3A",
          NextDialogue = 80080106,
          SpeakNpcId = 790004,
          Subtitle = "Aw, Elisa! No spoilers, please!",
          TalkActionId = {
            [1] = "790004:Sigh_Start",
            [2] = "790002:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE3A"
        },
        [80080106] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ya contaste tu aventura en la Mina de Glevum más de tres veces. Si tuviera una moneda por cada vez que cuentas esa historia, sería rica…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080106,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878DE64",
          NextDialogue = 80080107,
          SpeakNpcId = 790002,
          Subtitle = "You've told your Glevum Pit adventure three times already. I wish I had a coin for every time you told that story...",
          TalkActionId = {
            [1] = "790002:Talk02_Start",
            [2] = "790004:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE64"
        },
        [80080107] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero, pero… todavía no se la cuento a Fred… Mmm, bueno, y eso fue lo que pasó en la Mina.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080107,
          GUID = "C878DE8E",
          NextDialogue = 80080108,
          SpeakNpcId = 790004,
          Subtitle = "Well, I haven't told Fred yet, so... Um, right, that's what happened in the pit.",
          TalkActionId = {
            [1] = "790002:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE8E"
        },
        [80080108] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "A Psyche debe agradarle bastante {性别:ese nuevo amigo|esa nueva amiga}.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080108,
          GUID = "C878DEB8",
          NextDialogue = 80080109,
          SpeakNpcId = 790001,
          Subtitle = "You must really like your new friend, Psyche.",
          TalkActionId = {
            [1] = "790001:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DEB8"
        },
        [80080109] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Aunque usualmente hablas bastante… Hoy estás hablando más de la cuenta…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080109,
          GUID = "C878DEE2",
          NextDialogue = 80080110,
          SpeakNpcId = 790001,
          Subtitle = "Because you're especially talkative today, not that you're ever really quiet...",
          TalkActionId = {
            [1] = "790001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DEE2"
        },
        [80080110] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "… ¿Eh? ¿En serio?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080110,
          GUID = "C878DF0C",
          NextDialogue = 80080111,
          SpeakNpcId = 790004,
          Subtitle = "...Um, am I?",
          TalkActionId = {
            [1] = "790001:Explain01_End",
            [2] = "790004:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF0C"
        },
        [80080111] = {
          Camera = "-293.373047,-99.673187,105.125,0.0,0.200002,27.605503,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y a pesar de eso, yo nunca había escuchado esa historia. Deja que Psyche la termine.",
          DialogueId = 80080111,
          GUID = "C878DF36",
          LookAt = {
            [1] = "790003:n(790004)",
            [2] = "790004:n(790003)"
          },
          NextDialogue = 80080112,
          SpeakNpcId = 790003,
          Subtitle = "I've indeed never heard this story before. Let Psyche finish.",
          TalkActionId = {
            [1] = "790004:Shock_End",
            [2] = "790003:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF36"
        },
        [80080112] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Muy bien! Entonces, ¿en qué iba…? Ah, Elisa ya contó la segunda parte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080112,
          GUID = "C878DF60",
          LookAt = {
            [1] = "790004:n(790002)"
          },
          NextDialogue = 80080113,
          SpeakNpcId = 790004,
          Subtitle = "Alright! Now, where was I... Oh, Elisa already finished the second half for me.",
          TalkActionId = {
            [1] = "790004:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF60"
        },
        [80080113] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Ooh! Acabo de recordar algo que no les había dicho. Esa persona no es de aquí, sino de un lugar más allá de Hyperborea, ¡una pequeña isla del sur!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080113,
          FacialId = {
            [1] = "790004:Happy01"
          },
          GUID = "C878DF8A",
          NextDialogue = 80080114,
          SpeakNpcId = 790004,
          Subtitle = "Ooh! I just thought of something I haven't told you guys — that person isn't from around here but from a place far beyond Hyperborea — a small island to the south!",
          TalkActionId = {
            [1] = "790004:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF8A"
        },
        [80080114] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "{性别:Él|Ella} me contó que en aquel lugar hay arena dorada y romero blanco… ¡Y que el mar es cien veces más grande que el Lago Lamentoso!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080114,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878DFB4",
          NextDialogue = 80080115,
          Scripts = "PARA{PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{4}},SEQ{LookAt{LookAtDescription{\"790004:n(790002)\"}},LookAt{_delay{2},LookAtDescription{\"790004:n(790003)\"}}}}",
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} told me there's golden sand and white rosemary on that island... And the sea — it's as big as a hundred Lamenting Lakes put together!",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DFB4"
        },
        [80080115] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "También me contó que hay un Árbol Celestial gigantesco, pero a diferencia del Lago helado, la brisa entre sus ramas es cálida. Los marineros lo usan como faro.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080115,
          GUID = "C878DFDE",
          NextDialogue = 80080116,
          SpeakNpcId = 790004,
          Subtitle = "There is also a giant Heaventree there — but unlike the one in Icelake, the breeze through the treetops is warm. Sailors use the Heaventree as a beacon at sea.",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DFDE"
        },
        [80080116] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mar, brisas cálidas, y hasta un Árbol Celestial en lugar del helado Phoxichor de las fábricas, que incluso funciona de faro para los navegantes…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080116,
          GUID = "C878E008",
          NextDialogue = 80080117,
          SpeakNpcId = 790001,
          Subtitle = "Sea, warm breezes, a Heaventree that's not just cold Phoxichor in factories, but a beacon for sailors...",
          TalkActionId = {
            [1] = "790001:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E008"
        },
        [80080117] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Esa... esa persona alguna vez se ha parado bajo el Árbol Celestial? Seguro debe verse brillante, y tan majestuoso como en las canciones que cantan los bardos errantes, ¿no?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080117,
          GUID = "C878E032",
          NextDialogue = 80080118,
          Scripts = "SEQ{PlayAnimation{ActorId{790001},AnimationId{\"Think_End\"},Duration{1}},PlayAnimation{ActorId{790001},AnimationId{\"Explain01_Start\"},Duration{1}}}",
          SpeakNpcId = 790001,
          Subtitle = "Has that person ever stood under the Heaventree? From there, does the Heaventree look sparkling and magnificent — like in the songs by those wandering bards?",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E032"
        },
        [80080118] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sobre la arena que mencionaste…",
          DialogueId = 80080118,
          GUID = "C878E05C",
          LookAt = {
            [1] = "790003:n(790004)",
            [2] = "790004:n(790003)",
            [3] = "790002:n(790003)",
            [4] = "790001:n(790003)"
          },
          NextDialogue = 80080119,
          SpeakNpcId = 790003,
          Subtitle = "About the sand you mentioned just now...",
          TalkActionId = {
            [1] = "790001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E05C"
        },
        [80080119] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "He oído que la arena junto al mar es muy suave, que al pisarla se siente como pisar harina, y que no es nada áspera. Además, la arena es muy limpia gracias las olas, así que no ensucia los pies, ¿es verdad?",
          DialogueId = 80080119,
          GUID = "C878E086",
          NextDialogue = 80080120,
          SpeakNpcId = 790003,
          Subtitle = "I've heard that the sand by the sea is soft and smooth, and stepping on it feels like stepping on flour, not at all rough on the feet. And the sand is also very clean because of the waves, so it doesn't dirty your feet, right?",
          TalkActionId = {
            [1] = "790003:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E086"
        },
        [80080120] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "{性别:Él|Ella} no mencionó nada de eso… ¡Se lo preguntaré la próxima vez!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080120,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C878E0B0",
          LookAt = {
            [1] = "790002:n(790004)",
            [2] = "790001:n(790004)",
            [3] = "790003:n(790004)"
          },
          NextDialogue = 80080121,
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} didn't mention any of this... I'll ask for you all next time!",
          TalkActionId = {
            [1] = "790003:Talk01_End",
            [2] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E0B0"
        },
        [80080121] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿De qué sirve saber si eso es verdad, si ni siquiera podemos salir de Lago Helado?",
          DialogueId = 80080121,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878E0DA",
          LookAt = {
            [1] = "790004:n(790002)",
            [2] = "790002:n(790004)",
            [3] = "790001:n(790002)",
            [4] = "790003:n(790002)"
          },
          NextDialogue = 80080122,
          SpeakNpcId = 790002,
          Subtitle = "What's the point in knowing all this, when we can't even leave Icelake?",
          TalkActionId = {
            [1] = "790002:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E0DA"
        },
        [80080122] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Eso es cierto...",
          DialogueId = 80080122,
          GUID = "C878E104",
          LookAt = {
            [1] = "790003:n(790003)"
          },
          NextDialogue = 80080123,
          SpeakNpcId = 790003,
          Subtitle = "...That's true.",
          TalkActionId = {
            [1] = "790003:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E104"
        },
        [80080123] = {
