          DefaultLookAt = "TalkNpc",
          DialogueId = 80080125,
          GUID = "C878E182",
          NextDialogue = 80080126,
          SpeakNpcId = 790004,
          Subtitle = "Hunt shares tales of the Phoxhunters' adventures, and Mia tells us about all kinds of fish hiding beneath the ice of the Lamenting Lake...",
          TalkActionId = {
            [1] = "790004:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E182"
        },
        [80080126] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Carolina nos da un vistazo fascinante de la vida de las damas de la ciudad interna, Elisa ofrece versiones únicas de los viejos cuentos, y Fred comparte trucos ingeniosos de limpieza…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080126,
          GUID = "C878E1AC",
          NextDialogue = 80080127,
          SpeakNpcId = 790004,
          Subtitle = "Carolina gives us a fascinating glimpse into the novel lives of the ladies in the inner city, Elisa offers unique takes on old fairy tales, and Fred shares clever cleaning tricks...",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E1AC"
        },
        [80080127] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Aunque no podamos vivir todo esto en persona, sigue siendo maravilloso escucharlo de quienes sí lo hicieron.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080127,
          GUID = "C878E1D6",
          NextDialogue = 80080128,
          SpeakNpcId = 790004,
          Subtitle = "Even if we don't get to experience all this first-hand, it's still wonderful to hear them from those who did.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E1D6"
        },
        [80080128] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204903,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Oh, qué genial es aprender tanto, justo cuando nuestra vida está a punto de terminar. Para llevar todo ese conocimiento directo a la tumba.",
          DialogueId = 80080128,
          GUID = "C878E200",
          LookAt = {
            [1] = "790002:n(790002)",
            [2] = "790001:n(790002)",
            [3] = "790003:n(790002)"
          },
          NextDialogue = 80080129,
          SpeakNpcId = 790002,
          Subtitle = "Oh, it's really cool to learn so much when our lives are about to end — so we can take all this knowledge straight to the grave.",
          TalkActionId = {
            [1] = "790002:Sigh_Start",
            [2] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E200"
        },
        [80080129] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204903,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No te parece irónicamente cruel?",
          DialogueId = 80080129,
          GUID = "C878E22A",
          LookAt = {
            [1] = "790002:n(790004)",
            [2] = "790001:n(790002)",
            [3] = "790003:n(790002)"
          },
          NextDialogue = 80080130,
          SpeakNpcId = 790002,
          Subtitle = "Don't you find that ironically cruel?",
          TalkActionId = {
            [1] = "790002:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E22A"
        },
        [80080130] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204903,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 80080130,
          GUID = "C878E254",
          LookAt = {
            [1] = "790003:n(790003)"
          },
          NextDialogue = 80080131,
          SpeakNpcId = 790003,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E254"
        },
        [80080131] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tienes razón en lo que dices…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080131,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C878E27E",
          LookAt = {
            [1] = "790004:n(790002)",
            [2] = "790003:n(790004)",
            [3] = "790002:n(790004)",
            [4] = "790001:n(790004)"
          },
          NextDialogue = 80080132,
          SpeakNpcId = 790004,
          Subtitle = "You do have a point...",
          TalkActionId = {
            [1] = "790004:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E27E"
        },
        [80080132] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero, humm, siento que hay algo que no encaja.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080132,
          GUID = "C878E2A8",
          NextDialogue = 80080133,
          SpeakNpcId = 790004,
          Subtitle = "But, um, I still feel there's more to it...",
          TalkActionId = {
            [1] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E2A8"
        },
        [80080133] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sé que mis días están contados, no hay manera de negarlo. Pero si me quedo aquí sin hacer nada, simplemente esperando que llegue “ese día”…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080133,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878E2D2",
          NextDialogue = 80080134,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Agree\"},Duration{2}},PlayAnimation{ActorId{790004},AnimationId{\"Explain01_Start\"},Duration{2}},PlayAnimation{ActorId{790004},AnimationId{\"Explain01_End\"},Duration{1}}}",
          SpeakNpcId = 790004,
          Subtitle = "I know my days are numbered — there's no denying that. But if I just sit here doing nothing, simply waiting for \"that day\" to come...",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E2D2"
        },
        [80080134] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No podría perdonarme ni en la tumba.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080134,
          GUID = "C878E2FC",
          NextDialogue = 80080135,
          SpeakNpcId = 790004,
          Subtitle = "Then I couldn't forgive myself, even in the grave.",
          TalkActionId = {
            [1] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E2FC"
        },
        [80080135] = {
          Camera = "955.041016,143.792236,123.109375,0.0,0.0,90.006081,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que cuido las flores, leo, salgo de aventuras y comparto historias con todos… Siento que debo ocuparme con algo…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080135,
          FinalCamera = "955.041016,594.0,123.109375,0.0,0.0,90.006081,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C878E326",
          NextDialogue = 80080136,
          SpeakNpcId = 790004,
          Subtitle = "So I tend flowers, read, go on adventures, and share stories with everyone... I always feel that I should busy myself with something, anything...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E326"
        },
        [80080136] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tal vez, así, cuando ese día llegue, tenga menos arrepentimientos.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080136,
          GUID = "C878E350",
          NextDialogue = 80080137,
          SpeakNpcId = 790004,
          Subtitle = "Perhaps then, when that day comes, I'll have fewer regrets.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E350"
        },
        [80080137] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero de verdad no quise decir nada que te molestara, Elisa. Lo siento. Trataré de mantener la boca cerrada de ahora en adelante.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080137,
          GUID = "C878E37A",
          NextDialogue = 80080138,
          SpeakNpcId = 790004,
          Subtitle = "But I didn't mean to upset you, Elisa — I'm sorry. I'll try to keep my mouth shut from now on.",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E37A"
        },
        [80080138] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? Psyche, eres la única persona que ha querido hablar conmigo desde que Hunt se fue…",
          DialogueId = 80080138,
          GUID = "C878E3A4",
          LookAt = {
            [1] = "790004:n(790001)"
          },
          NextDialogue = 80080139,
          SpeakNpcId = 790001,
          Subtitle = "Huh? But Psyche, you're the only one willing to talk to me ever since Hunt left...",
          TalkActionId = {
            [1] = "790001:Give"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E3A4"
        },
        [80080139] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 80080139,
          GUID = "C878E3CE",
          LookAt = {
            [1] = "790002:n(790002)"
          },
          NextDialogue = 80080140,
          SpeakNpcId = 790002,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E3CE"
        },
        [80080140] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No te preocupes. Lo dije por decir… De hecho, si no hablaras, extrañaría mucho tus charlas.",
          DialogueId = 80080140,
          GUID = "C878E3F8",
          LookAt = {
            [1] = "790002:n(790004)",
            [2] = "790004:n(790002)"
          },
          NextDialogue = 80080141,
          SpeakNpcId = 790002,
          Subtitle = "Don't worry about it. I was just speaking off the cuff... I'd actually miss your chatter if it was gone.",
          TalkActionId = {
            [1] = "790002:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E3F8"
        },
        [80080141] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Bueno… Me alegra que no estés molesta, Elisa.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080141,
          GUID = "C878E422",
          NextDialogue = 80080142,
          SpeakNpcId = 790004,
          Subtitle = "Okay... I'm glad you're not upset, Elisa.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E422"
        },
        [80080142] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "La próxima vez que veas a esa persona, ¿podrías preguntarle sobre la arena dorada por mí?",
          DialogueId = 80080142,
          GUID = "C878E44C",
          LookAt = {
            [1] = "790003:n(790004)",
            [2] = "790004:n(790003)",
            [3] = "790002:n(790003)",
            [4] = "790001:n(790003)"
          },
          NextDialogue = 80080143,
          SpeakNpcId = 790003,
          Subtitle = "Next time you see that person, could you ask about the golden sand for me?",
          TalkActionId = {
            [1] = "790003:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E44C"
        },
        [80080143] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y sobre el Árbol Celestial.",
          DialogueId = 80080143,
          GUID = "C878E476",
          LookAt = {
            [1] = "790004:n(790001)",
            [2] = "790003:n(790004)",
            [3] = "790002:n(790001)",
            [4] = "790001:n(790004)"
          },
          NextDialogue = 80080144,
          SpeakNpcId = 790001,
          Subtitle = "And about the Heaventree.",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E476"
        },
        [80080144] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Claro! Lo tengo anotado. La próxima vez le preguntaré.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080144,
          FacialId = {
            [1] = "790004:Smile01"
          },
          GUID = "C878E4A0",
          LookAt = {
            [1] = "790004:n(790002)"
          },
          SpeakNpcId = 790004,
          Subtitle = "Sure! I'll keep all this in mind. I'll ask for you next time I see {性别:him|her}.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E4A0"
        },
        [80080201] = {
          Camera = "152.138672,195.628784,134.539062,0.0,-1.200071,-127.200096,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "linear",
          ContentES = "Elisa, he vuelto.",
          DialogueId = 80080201,
          FinalCamera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C878EDFA",
          NextDialogue = 80080202,
          Scripts = "SEQ{MoveTo{ActorId{790004},MoveSpeed{75},TargetPoint{\"QuestPoint_530102\"}},TurnTo{TurnToDescription{\"790004:n(790006)\"}}}",
          SpeakNpcId = 790004,
          Subtitle = "Elisa, I'm back.",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EDFA"
        },
        [80080202] = {
          Camera = "-81.119141,-25.830444,135.263672,0.0,0.599909,-131.198853,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Te traje un poco de pan. Apuesto a que te saltaste el desayuno. No me iré hasta que te lo termines.",
          DialogueId = 80080202,
          GUID = "C878EE24",
          NextDialogue = 80080203,
          SpeakNpcId = 790004,
          Subtitle = "I brought you some bread — I bet you've skipped the meals again. I'm not going anywhere until you finish it.",
          TalkActionId = {
            [1] = "790004:Give"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE24"
        },
        [80080203] = {
          Camera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Por qué desperdiciar comida…? Al fin y al cabo, pronto todos dejaremos este mundo.",
          DialogueId = 80080203,
          GUID = "C878EE4E",
          NextDialogue = 80080204,
          SpeakNpcId = 790006,
          Subtitle = "Why waste food... We're all going to leave the world soon anyway.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE4E"
        },
        [80080204] = {
          Camera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "No digas eso… ¿Ves esa planta de allí? Esa planta se marchitará algún día, pero aun así la regamos y la cuidamos para que florezca.",
          DialogueId = 80080204,
          GUID = "C878EE78",
          NextDialogue = 80080205,
          SpeakNpcId = 790004,
          Subtitle = "Don't say that... Do you see that plant over there? It'll eventually wither for sure, but we still water and take care of it so that it'll bloom one day.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE78"
        },
        [80080205] = {
          Camera = "-0.818359,59.526489,190.207031,0.000001,-10.400117,20.598642,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Y si esa flor nunca llega a florecer?",
          DialogueId = 80080205,
          FinalCamera = "-0.818359,59.526489,206.207031,0.000001,-10.400117,20.598642,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C878EEA2",
          NextDialogue = 80080206,
          SpeakNpcId = 790006,
          Subtitle = "But what if it never blooms?",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EEA2"
        },
        [80080206] = {
          Camera = "-78.357422,-27.765015,126.353516,0.000021,3.399993,-132.00238,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces, solo verlo brotar y crecer más grande sigue siendo maravilloso, ¿no?",
          DialogueId = 80080206,
          GUID = "C878EECC",
          NextDialogue = 80080207,
          SpeakNpcId = 790004,
          Subtitle = "Then, just watching it sprout and grow bigger is still wonderful, isn't it?",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EECC"
        },
        [80080207] = {
          Camera = "-263.033203,-174.554382,138.316406,0.000001,-1.800322,23.388023,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Olvídalo... No tengo el mismo tacto que tú con las plantas.",
          DialogueId = 80080207,
          GUID = "C878EEF6",
          NextDialogue = 80080208,
          SpeakNpcId = 790006,
          Subtitle = "...Forget it. I don't have your green thumb.",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EEF6"
        },
        [80080208] = {
          Camera = "-263.033203,-174.554382,138.316406,0.000001,-1.800322,23.388023,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Por cierto, ¿para qué vino esa persona hace un momento? Ni siquiera es {性别:un Deteriorador|una Deterioradora}, y aun así viene casi todos los días… ¿no será {性别:un|una} espía de la Oficina de Seguridad?",
          DialogueId = 80080208,
          GUID = "C878EF20",
          NextDialogue = 80080209,
          SpeakNpcId = 790006,
          Subtitle = "By the way, why was that person here earlier? {性别:He|She} is not a Deteriorator, so why the frequent visits? Is {性别:he|she} a spy for the Security Bureau?",
          TurnTo = {
            [1] = "790006:n(790004)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF20"
        },
        [80080209] = {
          Camera = "26.732422,82.374146,145.716797,0.000007,-5.80006,-125.792847,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Te refieres a {nickname}? {性别:Él|Ella} no es de aquí. Ahora es {性别: un Phoxcazador|una Phoxcazadora}, así que no creo que tenga relación alguna con la Oficina de Seguridad. Al parecer, vino por un encargo…",
          DialogueId = 80080209,
          GUID = "C878EF4A",
          NextDialogue = 80080210,
          SpeakNpcId = 790004,
          Subtitle = "You mean ? {性别:He|She}'s not a local. {性别:He|She} now works as a Phoxhunter and has nothing to do with the Security Bureau. I think {性别:he|she} was here for a commission.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF4A"
        },
        [80080210] = {
          Camera = "26.732422,82.374146,145.716797,0.000007,-5.80006,-125.792847,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentES = "Escuché que encontró lo que el Dr. Henrik necesitaba. Quizá pueda ayudarnos, deberíamos… eh, no importa.",
          DialogueId = 80080210,
          GUID = "C878EF74",
          NextDialogue = 80080211,
          SpeakNpcId = 790004,
          Subtitle = "I heard {性别:he|she} found something Dr Henrik needs. If it helps, maybe we... um, never mind.",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF74"
        },
        [80080211] = {
          Camera = "-147.058594,-85.52063,138.552734,0.000007,-0.200043,29.804741,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ayer dijiste que saliste de la ciudad con esa persona, y que al volver el Dr. Henrik les dio una buena reprimenda.",
          DialogueId = 80080211,
          GUID = "C878EF9E",
          NextDialogue = 80080212,
          SpeakNpcId = 790006,
          Subtitle = "Didn't you say you went out of town with that person yesterday and got an earful from Dr Henrik?",
          TalkActionId = {
            [1] = "790006:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF9E"
        },
        [80080212] = {
          Camera = "-160.625,-5.968567,134.414062,0.000007,0.199988,-105.995361,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah… sí...",
          DialogueId = 80080212,
          GUID = "C878EFC8",
          NextDialogue = 80080213,
          SpeakNpcId = 790004,
          Subtitle = "Huh? Um, yes...",
          TalkActionId = {
            [1] = "790004:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EFC8"
        },
        [80080213] = {
          Camera = "-164.548828,-79.17041,134.091797,0.000007,0.80002,25.802954,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Entonces, ¿por qué sigues entrometiéndote en sus asuntos? Si no es {性别:uno|una} de los nuestros, ni pertenece a la Oficina de Seguridad, mejor no te metas.",
          DialogueId = 80080213,
          GUID = "C878EFF2",
          NextDialogue = 80080214,
          SpeakNpcId = 790006,
          Subtitle = "Then why still mix up with {性别:him|her}? Since {性别:he|she}'s not one of us and not with the Security Bureau, {性别:he|she} has nothing to do with us, right?",
          TalkActionId = {
            [1] = "790004:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EFF2"
        },
        [80080214] = {
          Camera = "22.615234,70.785767,148.324219,0.000011,-8.000091,-127.191437,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Yo... solo pensé que quizás había algo en lo que podía ayudar…",
          DialogueId = 80080214,
          GUID = "C878F01C",
          NextDialogue = 80080215,
          SpeakNpcId = 790004,
          Subtitle = "I... I just thought there might be something I could do—",
          TalkActionId = {
            [1] = "790006:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F01C"
        },
        [80080215] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "La verdad, Psyche, a veces no te entiendo.",
          DialogueId = 80080215,
          GUID = "C878F046",
          NextDialogue = 80080216,
          SpeakNpcId = 790006,
          Subtitle = "Honestly, Psyche, I don't understand you sometimes.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F046"
        },
        [80080216] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "{nickname} es solo {性别:un forastero|una forastera}, y quizá se marche de Lago Helado mañana mismo. Ni siquiera {性别:él|ella} sabe… de tu situación… Sabes bien que ninguno de nosotros estará por mucho tiempo en este mundo.",
          DialogueId = 80080216,
          GUID = "C878F070",
          NextDialogue = 80080217,
          SpeakNpcId = 790006,
          Subtitle = "{性别:He|She} is just a stranger, and might just leave Icelake tomorrow. {性别:He|She} doesn't even know... what will happen to you... You know it — everyone here is not long for this world.",
          TalkActionId = {
            [1] = "790006:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F070"
        },
        [80080217] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Todos los días ayudas a medio mundo: a uno le llevas flores o le cocinas algo, al otro le cuentas historias o le buscas un lugar donde quedarse. ¿De qué sirve todo eso?",
          DialogueId = 80080217,
          GUID = "C878F09A",
          NextDialogue = 80080218,
          SpeakNpcId = 790006,
          Subtitle = "Yet you're always out helping others, giving away flowers, making meals, telling stories, helping travellers with accommodations... What's the point?",
          TalkActionId = {
            [1] = "790006:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F09A"
        },
        [80080218] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Deja de meterte tanto en los asuntos de los demás y piensa un poco más en ti.",
          DialogueId = 80080218,
          GUID = "C878F0C4",
          NextDialogue = 80080219,
          SpeakNpcId = 790006,
          Subtitle = "Maybe you should stop meddling in other people's business and focus on yourself more.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F0C4"
        },
        [80080219] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tienes razón...",
          DialogueId = 80080219,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C878F0EE",
          NextDialogue = 80080220,
          SpeakNpcId = 790004,
          Subtitle = "...You have a point.",
          TalkActionId = {
            [1] = "790004:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F0EE"
        },
        [80080220] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero te equivocas en una cosa, no soy tan desinteresada como tú crees.",
          DialogueId = 80080220,
          GUID = "C878F118",
          NextDialogue = 80080221,
          SpeakNpcId = 790004,
          Subtitle = "But you got one thing wrong — I'm not as selfless as you think.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F118"
        },
        [80080221] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Para ser más precisa... hago todas esas cosas por mí misma.",
          DialogueId = 80080221,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878F142",
          NextDialogue = 80080222,
          SpeakNpcId = 790004,
          Subtitle = "To be more precise... I did all those things for myself.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F142"
        },
        [80080222] = {
          Camera = "37.734375,86.957642,146.630859,0.000001,-5.400023,-127.39193,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Te mentiría si dijera que... no tengo miedo de morir.",
          DialogueId = 80080222,
          GUID = "C878F16C",
          NextDialogue = 80080223,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790004},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{790004},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 790004,
          Subtitle = "I'm not afraid of dying — no, that's an overstatement... I am afraid.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F16C"
        },
        [80080223] = {
          Camera = "-130.748047,-103.410034,139.367188,0.00001,3.199786,-140.194809,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero más que la muerte… lo que me aterra es la idea de desaparecer. Una vez que se olvidan de ti, es como si la prueba de tu existencia se borrara de este mundo.",
          DialogueId = 80080223,
          GUID = "C878F196",
          NextDialogue = 80080224,
          SpeakNpcId = 790004,
          Subtitle = "But what terrifies me even more than death is... the idea of \"disappearing.\" Once you're forgotten, it's like the very evidence of your existence just gets wiped away.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F196"
        },
        [80080224] = {
          Camera = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ahora entiendo, es por eso que te esfuerzas en ayudar a tanta gente como puedes, lo que esperas es que te recuerden el mayor tiempo posible… ¿es eso?",
          DialogueId = 80080224,
          GUID = "C878F1C0",
          NextDialogue = 80080225,
          SpeakNpcId = 790006,
          Subtitle = "So you go out of your way to help as many people as possible, hoping they'll remember you for as long as they can — is that it?",
          TalkActionId = {
            [1] = "790004:Explain01_End",
            [2] = "790006:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F1C0"
        },
        [80080225] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí. En realidad… soy muy egoísta. Tienes razón, {性别:él|ella} tal vez se vaya algún día.",
          DialogueId = 80080225,
          GUID = "C878F1EA",
          NextDialogue = 80080226,
          SpeakNpcId = 790004,
          Subtitle = "Yes... I'm actually... very selfish. You're right, {性别:he|she} will leave one day.",
          TalkActionId = {
            [1] = "790004:Agree",
            [2] = "790006:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F1EA"
        },
        [80080226] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "No pertenece a Lago Helado, desde el principio lo supe. Es diferente a las personas que conocemos, y no se quedará aquí {性别:atrapado|atrapada} para siempre como nosotros.",
          DialogueId = 80080226,
          GUID = "C878F214",
          NextDialogue = 80080227,
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} doesn't belong here. I've always known that {性别:he|she} is different — unlike us, trapped in Icelake forever.",
          TalkActionId = {
            [1] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F214"
        },
        [80080227] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "Precisamente por eso quiero ser su amiga. Así, se llevará consigo los recuerdos que tiene de mí, los llevará en sus viajes y aventuras por todo el mundo.",
          DialogueId = 80080227,
          GUID = "C878F23E",
          NextDialogue = 80080228,
          SpeakNpcId = 790004,
          Subtitle = "And that's exactly why I want to be friends with {性别:him|her} — so that {性别:he|she} will carry memories of me while going on wonderful adventures around the world.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F23E"
        },
        [80080228] = {
          Camera = "-2481.224609,-566.944275,10.640625,0.0,1.999715,-93.189522,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "En los libros, dicen que en el norte, el sol de Askard nunca se esconde; que en el sur hay una torre, en Elysium, y se alza por todas las nubes; y que en el este existen naves en Huaxu, que se elevan hacia las estrellas…",
          DialogueId = 80080228,
          FinalCamera = "-2069.626953,-579.504761,10.279297,0.0,1.999715,-93.189522,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "C878F268",
          NextDialogue = 80080229,
          SpeakNpcId = 790004,
          Subtitle = "I've read about the never-setting sun in Askard to the north, the cloud-capped tower of Elysium down the south, and further east, the star-bound ships of Huaxu...",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F268"
        },
        [80080229] = {
          Camera = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero para entonces, tú ya te habrás ido.",
          DialogueId = 80080229,
          GUID = "C878F292",
          NextDialogue = 80080230,
          SpeakNpcId = 790006,
          Subtitle = "But you'll be gone by then.",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F292"
        },
        [80080230] = {
          Camera = "28.722656,72.22937,144.703125,0.00001,-5.200185,-127.592773,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sin embargo viviré en sus recuerdos. Y de esa manera, mi vida continuará junto a la suya.",
          DialogueId = 80080230,
          GUID = "C878F2BC",
          NextDialogue = 80080231,
          SpeakNpcId = 790004,
          Subtitle = "But I'll live on in {性别:his|her} memories. That way, it's like my life continues with {性别:him|her}.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F2BC"
        },
        [80080231] = {
          Camera = "-272.109375,-179.431152,139.566406,0.000012,-3.599967,24.199917,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Y cómo puedes estar tan segura de que {性别:él|ella} te recordará?",
          DialogueId = 80080231,
          GUID = "C878F2E6",
          NextDialogue = 80080232,
          SpeakNpcId = 790006,
          Subtitle = "How do you know for sure that {性别:he|she} will remember you?",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F2E6"
        },
        [80080232] = {
          Camera = "21.574219,67.467163,141.941406,0.000012,-5.400146,-127.189346,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentES = "Yo… no estoy segura. No soy tan inteligente como tú. Hay muchas cosas que no entiendo, y no sé cómo hacer para que la gente me siga recordando.",
          DialogueId = 80080232,
          GUID = "C878F310",
          NextDialogue = 80080233,
          SpeakNpcId = 790004,
          Subtitle = "I... I'm not sure. I'm not as smart as you. I don't understand many things, and I don't know how to make people remember me more.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F310"
        },
        [80080233] = {
          Camera = "21.574219,67.467163,141.941406,0.000012,-5.400146,-127.189346,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que lo hago a mi manera… Por ejemplo, hablo con {性别:él|ella}, intento escuchar sus problemas y echarle una mano con algunas cosas…",
          DialogueId = 80080233,
          GUID = "C878F33A",
          NextDialogue = 80080234,
          SpeakNpcId = 790004,
          Subtitle = "So I just try my luck... like chatting with {性别:him|her}, listening to {性别:his|her} problems, and helping out with things...",
          TalkActionId = {
            [1] = "790004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F33A"
        },
        [80080234] = {
          Camera = "-104.746094,-61.860352,133.810547,0.000011,3.199862,-132.793442,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Con suerte, quizá pueda dejar un recuerdo en su memoria. Aunque, solo es una suposición...",
          DialogueId = 80080234,
          GUID = "C878F364",
          NextDialogue = 80080235,
          SpeakNpcId = 790004,
          Subtitle = "Hopefully, that will leave more of an impression in {性别:his|her} memory — it's really just a shot in the dark though...",
          TalkActionId = {
            [1] = "790004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F364"
        },
        [80080235] = {
          Camera = "38.255859,86.966919,163.544922,0.00009,-9.399658,-125.779823,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "*Suspira*",
          DialogueId = 80080235,
          FinalCamera = "38.255859,86.966919,163.544922,0.000088,-9.399658,-122.98008,35.000011,100000.0,false,DoNotOverride,2.8",
