          DialogueId = 80080236,
          GUID = "C878F3B8",
          NextDialogue = 80080237,
          SpeakNpcId = 790006,
          Subtitle = "You can be such a fool sometimes, Psyche.",
          TalkActionId = {
            [1] = "790006:Disagree"
