          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F3B8"
        },
        [80080237] = {
          Camera = "-272.960938,-184.779846,138.189453,0.000032,-3.000755,27.59623,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentES = "Quizás deberías darle un regalo. Pero ya no le des más de tus flores.",
          DialogueId = 80080237,
          GUID = "C878F3E2",
          NextDialogue = 80080238,
          SpeakNpcId = 790006,
          Subtitle = "...Maybe give {性别:him|her} a gift. But please, no more of your flowers.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F3E2"
        },
        [80080238] = {
          Camera = "-144.699219,-93.240356,140.8125,0.000035,0.199558,-130.997589,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Eh? Entonces… ¿qué debería darle…?",
          DialogueId = 80080238,
          GUID = "C878F40C",
          NextDialogue = 80080239,
          SpeakNpcId = 790004,
          Subtitle = "Huh? Then what should I get {性别:him|her}...?",
          TalkActionId = {
            [1] = "790004:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F40C"
        },
        [80080239] = {
          Camera = "-269.560547,-176.554443,135.869141,0.000043,-2.40075,25.794977,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "Algo que no se estropee fácilmente… Debes regalarle algo duradero, especial, que pueda llevar siempre consigo, y que además tenga cierta utilidad.",
          DialogueId = 80080239,
          GUID = "C878F436",
          NextDialogue = 80080240,
          SpeakNpcId = 790006,
          Subtitle = "Something that won't break or go bad easily, that's for sure... It should be durable, special, and easy for {性别:him|her} to carry around at all times, ideally something practical.",
          TalkActionId = {
            [1] = "790004:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F436"
        },
        [80080240] = {
          Camera = "-269.560547,-176.554443,135.869141,0.000043,-2.40075,25.794977,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "De esa manera… siempre te recordará.",
          DialogueId = 80080240,
          GUID = "C878F460",
          NextDialogue = 80080241,
          SpeakNpcId = 790006,
          Subtitle = "That way... it might always remind {性别:him|her} of you.",
          TalkActionId = {
            [1] = "790006:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F460"
        },
        [80080241] = {
          Camera = "-137.921875,-86.418274,139.603516,0.000013,0.598939,-130.579102,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Qué buena idea!",
          DialogueId = 80080241,
          GUID = "C878F48A",
          NextDialogue = 80080242,
          SpeakNpcId = 790004,
          Subtitle = "That's a great idea!",
          TalkActionId = {
            [1] = "790006:Explain02_End",
            [2] = "790004:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F48A"
        },
        [80080242] = {
          Camera = "-137.921875,-86.418274,139.603516,0.000013,0.598939,-130.579102,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Ya sé…! Tengo un “tesoro” perfecto para regalarle...",
          DialogueId = 80080242,
          GUID = "C878F4B4",
          NextDialogue = 80080243,
          SpeakNpcId = 790004,
          Subtitle = "I've got it... I have the perfect \"treasure\" to give {性别:him|her}!",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F4B4"
        },
        [80080243] = {
          Camera = "15.410156,46.214355,140.125,0.0,-4.199951,-129.79097,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Gracias, Elisa! Como era de esperar, eres mucho más lista que yo.",
          DialogueId = 80080243,
          FacialId = {
            [1] = "790004:Happy02"
          },
          GUID = "C878F4DE",
          NextDialogue = 80080244,
          SpeakNpcId = 790004,
          Subtitle = "Thanks, Elisa! You really are much smarter than me.",
          TalkActionId = {
