        },
        [80080302] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Debí venir un poco más tarde para darte tiempo de despedirte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080302,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FE8C",
          NextDialogue = 80080303,
          SpeakNpcId = 790005,
          Subtitle = "I should've come a bit later to give you more time to say goodbye.",
          TalkActionId = {
            [1] = "790005:Explain01_Start"
          },
          TurnTo = {
            [1] = "790004:n(790005)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FE8C"
        },
        [80080303] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Dr. Henrik, a qué se refiere…?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080303,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FEB6",
          NextDialogue = 80080304,
          SpeakNpcId = 790004,
          Subtitle = "Dr Henrik, do you mean...",
          TalkActionId = {
            [1] = "790004:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FEB6"
        },
        [80080304] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Me refiero a {性别:ese muchacho|esa muchacha}, {nickname}. Fue difícil {性别:dejarlo|dejarla} ir, ¿verdad?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080304,
          GUID = "C878FEE0",
          NextDialogue = 80080305,
          SpeakNpcId = 790005,
          Subtitle = "I mean that kid, . It was hard letting go of {性别:him|her} when {性别:he|she} grasped your hand, wasn't it?",
          TalkActionId = {
            [1] = "790004:Think_End",
            [2] = "790005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FEE0"
        },
        [80080305] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "... Sí, enseguida ves lo que siento.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080305,
          GUID = "C878FF0A",
          NextDialogue = 80080306,
          SpeakNpcId = 790004,
          Subtitle = "Yeah... you always see right through me.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF0A"
        },
        [80080306] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Pero yo sé que, incluso estando frente a frente, nos separa una gran distancia… tan grande como la que hay entre Lago Helado y el océano.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080306,
          GUID = "C878FF34",
          LookAt = {
            [1] = "790004:n(790004)"
          },
          NextDialogue = 80080307,
          SpeakNpcId = 790004,
          Subtitle = "But I know that even though {性别:he|she} was right in front of me, {性别:he|she} was actually very far away, as far as Icelake is from the ocean.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF34"
        },
        [80080307] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y aunque {性别:él|ella} me extienda su mano, no soy capaz de sostenerla. Del mismo modo en que trato con todas mis fuerzas de {性别:mirarlo|mirarla} y, sin embargo, es como ver a la nada.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080307,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FF5E",
          LookAt = {
            [1] = "790004:n(790005)"
          },
          NextDialogue = 80080308,
          SpeakNpcId = 790004,
          Subtitle = "So even though {性别:he|she} reached out, I couldn't really grasp {性别:his|her} hand, just as I tried so hard to look at {性别:him|her}, but couldn't see anything.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF5E"
        },
        [80080308] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Psyche... hay algo que quiero decirte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080308,
          GUID = "C878FF88",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080309,
          SpeakNpcId = 790005,
          Subtitle = "...Psyche, there's something I want you to know.",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790005:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF88"
        },
        [80080309] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "El medicamento para detener el Deterioro está listo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080309,
          GUID = "C878FFB2",
          NextDialogue = 80080310,
          SpeakNpcId = 790005,
          Subtitle = "The development of anti-deterioration medication is finished.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFB2"
        },
        [80080310] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Tan rápido? Pensé que la investigación tomaría más tiempo…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080310,
          FacialId = {
            [1] = "790004:Shock01"
          },
          GUID = "C878FFDC",
          NextDialogue = 80080311,
          SpeakNpcId = 790004,
          Subtitle = "Already? I thought the research would take longer...",
          TalkActionId = {
            [1] = "790004:Alright_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFDC"
        },
        [80080311] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Comencé a investigar hace años, pero abandoné todo tras la muerte de Hayley. Lo retomé solo por ti… bueno, por todos ustedes.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080311,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C8790006",
          LookAt = {
            [1] = "790005:n(790004)"
          },
          NextDialogue = 80080312,
          SpeakNpcId = 790005,
          Subtitle = "I started the research years ago but put it aside after Hayley's death. I only picked it up again for you... for all of you.",
          TalkActionId = {
            [1] = "790005:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790006"
        },
        [80080312] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Afortunadamente, todos los datos teóricos anteriores siguen frescos en mi mente, y con ese fragmento del <H>Cristal estelar</>, logré replicar la mayoría de los pasos experimentales...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080312,
          GUID = "C8790030",
          NextDialogue = 80080313,
          SpeakNpcId = 790005,
          Subtitle = "Fortunately, all the previous theoretical data is still fresh in my mind, and with that piece of the Crystallo of Stella, I managed to replicate most of the experimental steps...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790030"
        },
        [80080313] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Eso es maravilloso! Pero... si su investigación fue todo un éxito, ¿por qué le veo tan triste…?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080313,
          GUID = "C879005A",
          NextDialogue = 80080314,
          SpeakNpcId = 790004,
          Subtitle = "That's great! Your research succeeded! But... this is good news, right? Why do you still look so sad...?",
          TalkActionId = {
            [1] = "790004:Alright_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879005A"
        },
        [80080314] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "*Suspira* No sé si puedas entenderlo…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080314,
          GUID = "C8790084",
          NextDialogue = 80080315,
          SpeakNpcId = 790005,
          Subtitle = "*sigh* It's complicated...",
          TalkActionId = {
            [1] = "790005:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790084"
        },
        [80080315] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "El Cristal estelar es sumamente inestable, combinado correctamente puede frenar el proceso de Deterioro, pero también puede acelerarlo. Las condiciones que desencadenan cada resultado dependen de un diminuto margen de error.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080315,
          GUID = "C87900AE",
          NextDialogue = 80080316,
          SpeakNpcId = 790005,
          Subtitle = "Crystallo is highly unstable. Under specific medicinal catalysts, it can suppress the process of deterioration, or accelerate it... The conditions triggering each process are only minutely different.",
          TalkActionId = {
            [1] = "790005:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87900AE"
        },
        [80080316] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Lamentablemente, todos los textos farmacológicos relevantes de Huaxu se perdieron en Hyperborea, y no puedo verificar cada paso de mi trabajo únicamente a través de la teoría.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080316,
          GUID = "C87900D8",
          NextDialogue = 80080317,
          SpeakNpcId = 790005,
          Subtitle = "Sadly, all the relevant pharmacological texts from Huaxu were lost in Hyperborea, and I can't verify each step of my work purely through theory.",
          TalkActionId = {
            [1] = "790005:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87900D8"
        },
        [80080317] = {
          Camera = "271.882812,218.0,222.382812,0.0,0.0,-172.398712,35.0,500.0,false,Manual,2.8",
          ContentES = "La única opción es probar el medicamento… pero no atrevo a suministrarte un fármaco que no ha sido probado.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080317,
          FinalCamera = "271.882812,268.0,222.382812,0.0,0.0,-172.398712,35.0,300.0,false,Manual,2.8",
          GUID = "C8790102",
          NextDialogue = 80080318,
          SpeakNpcId = 790005,
          Subtitle = "The only option is clinical trials... but I can't bring myself to test an unverified new drug on you.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790102"
        },
        [80080318] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603367,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Tal vez sea su bondad lo que ha frenado su investigación, Dr. Henrik. Por favor, permítame ayudarle con los ensayos clínicos.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080318,
          GUID = "C879012C",
          NextDialogue = 80080319,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 790004,
          Subtitle = "Perhaps your kindness is why the research on the anti-deterioration drug hasn't progressed further. Dr Henrik, please allow me to help you with the clinical trials.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879012C"
        },
        [80080319] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "La Casa de Hypnos fue fundada para aliviar el sufrimiento… ¡si experimento contigo, no me diferenciaría de la Legión!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080319,
          GUID = "C8790156",
          NextDialogue = 80080320,
          SpeakNpcId = 790005,
          Subtitle = "Hypnos' House was founded to alleviate suffering... If I use you for experiments, how am I any different from the Legion!?",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790005:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790156"
        },
        [80080320] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Se equivoca… Usted ha estado cuidándonos, haciendo todo lo posible por aliviar nuestro dolor, pero ahora ese dolor lo está cargando usted mismo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080320,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C8790180",
          NextDialogue = 80080321,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"DisagreeHead\"},Duration{1}},PlayAnimation{ActorId{790004},AnimationId{\"Talk02_Start\"},Duration{2}}}",
          SpeakNpcId = 790004,
          Subtitle = "It's not like that... You've been taking care of us, going out of your way to ease our pain, but the pain hasn't disappeared — you've simply taken it upon yourself.",
          TalkActionId = {
            [1] = "790005:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790180"
        },
        [80080321] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que, por favor, déjeme cargar parte de ese peso.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080321,
          GUID = "C87901AA",
          NextDialogue = 80080322,
          SpeakNpcId = 790004,
          Subtitle = "So, please let me share some of that burden.",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901AA"
        },
        [80080322] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es más complicado de lo que imaginas… ¿Sabes lo que podría ocurrir si tomas el medicamento?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080322,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C87901D4",
          NextDialogue = 80080323,
          SpeakNpcId = 790005,
          Subtitle = "It's more complicated than you might think... Do you realise what could happen if you take that medicine?",
          TalkActionId = {
            [1] = "790005:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901D4"
        },
        [80080323] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "No estoy segura de entender muy bien la situación. ¿Quiere decir que podría funcionar, pero también podría no funcionar?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080323,
          GUID = "C87901FE",
          NextDialogue = 80080324,
          Scripts = "SEQ{LookAt{LookAtDescription{\"790004:n(790004)\"}},LookAt{_delay{2},LookAtDescription{\"790004:n(790005)\"}}}",
          SpeakNpcId = 790004,
          Subtitle = "... I'm not sure if I get this right. Do you mean it might work, but also might not?",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901FE"
        },
        [80080324] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Hay un cincuenta por ciento de posibilidades.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080324,
          GUID = "C8790228",
          NextDialogue = 80080325,
          SpeakNpcId = 790005,
          Subtitle = "There's a fifty-fifty chance.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790228"
        },
        [80080325] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Podrías recuperarte y tener una segunda oportunidad, o…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080325,
          GUID = "C8790252",
          NextDialogue = 80080326,
          SpeakNpcId = 790005,
          Subtitle = "You could recover and gain a second chance at life, or...",
          TalkActionId = {
            [1] = "790005:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790252"
        },
        [80080326] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Podría acelerar el Deterioro… Incluso te robarían tus últimos días.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080326,
          GUID = "C879027C",
          NextDialogue = 80080327,
          SpeakNpcId = 790005,
          Subtitle = "Your condition could deteriorate rapidly... You might even be robbed of your last moments.",
          TalkActionId = {
            [1] = "790005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879027C"
        },
        [80080327] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080327,
          GUID = "C87902A6",
          LookAt = {
            [1] = "790004:n(790004)"
          },
          NextDialogue = 80080328,
          SpeakNpcId = 790004,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902A6"
        },
        [80080328] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Dr. Henrik, he tomado una decisión.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080328,
          GUID = "C87902D0",
          LookAt = {
            [1] = "790004:n(790005)"
          },
          NextDialogue = 80080329,
          SpeakNpcId = 790004,
          Subtitle = "Dr Henrik, I've made up my mind.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902D0"
        },
        [80080329] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es posible que el medicamento que usted elaboró alivie nuestro sufrimiento. Aunque las probabilidades de que funcione sean bajas, quiero ayudarle con la investigación. Además…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080329,
          GUID = "C87902FA",
          NextDialogue = 80080330,
          SpeakNpcId = 790004,
          Subtitle = "The anti-deterioration drug is a chance to ease the pain of us all. Even if the chances of success are slim to none, I'd still like to help with your research. Besides...",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902FA"
        },
        [80080330] = {
          Camera = "-127.080078,-30.343323,142.15625,0.000079,-5.799957,57.598873,50.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Siento que he cambiado. Ya no soy la misma de antes.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080330,
          GUID = "C8790324",
          NextDialogue = 80080331,
          SpeakNpcId = 790004,
          Subtitle = "I feel like I've changed... I'm not who I used to be.",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790324"
        },
        [80080331] = {
          Camera = "-87.792969,98.007385,119.857422,0.000075,6.799897,-100.99704,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Cambiada...?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080331,
          GUID = "C879034E",
          NextDialogue = 80080332,
          SpeakNpcId = 790005,
          Subtitle = "What do you mean?",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879034E"
        },
        [80080332] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Desde que conocí a alguien y viví esa aventura, soy diferente.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080332,
          GUID = "C8790378",
          NextDialogue = 80080333,
          SpeakNpcId = 790004,
          Subtitle = "I've changed ever since I met someone and went on an adventure.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790378"
        },
        [80080333] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Me he vuelto más ambiciosa… ahora lo que más deseo es tiempo...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080333,
          GUID = "C87903A2",
          NextDialogue = 80080334,
          SpeakNpcId = 790004,
          Subtitle = "I've become much greedier... I now yearn for more time, more of everything...",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903A2"
        },
        [80080334] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Deseo poder tomar la mano de alguien, huir de Lago Helado, viajar a tierras lejanas…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080334,
          GUID = "C87903CC",
          NextDialogue = 80080335,
          SpeakNpcId = 790004,
          Subtitle = "I wish to hold someone's hand and escape Icelake, to travel to far-off lands...",
          TalkActionId = {
            [1] = "790004:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903CC"
        },
        [80080335] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Deseo envejecer… quiero algún día ser mayor y ver mis arrugas, sentarme en la plaza, alimentar a los pájaros y contar a los niños historias de mi juventud…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080335,
          GUID = "C87903F6",
          NextDialogue = 80080336,
          SpeakNpcId = 790004,
          Subtitle = "I wish to grow older... so that one day I'll become a wrinkled old lady, sitting in the square, feeding birds and sharing stories of my youth with children...",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903F6"
        },
        [80080336] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Antes creía que bastaba con aprovechar mis últimos días. Pero ahora quiero más…",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080336,
          GUID = "C8790420",
          NextDialogue = 80080337,
          SpeakNpcId = 790004,
          Subtitle = "I once thought that making the most of my last days was enough. But now, I want more...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790420"
        },
        [80080337] = {
          Camera = "-115.541016,2.555298,138.173828,0.000146,-6.001127,46.597878,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Quiero vivir.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080337,
          GUID = "C879044A",
          NextDialogue = 80080338,
          SpeakNpcId = 790004,
          Subtitle = "I want to LIVE.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879044A"
        },
        [80080338] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así que, Dr. Henrik, por favor, permítame ayudar con la investigación.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080338,
          GUID = "C8790474",
          NextDialogue = 80080339,
          SpeakNpcId = 790004,
          Subtitle = "So, Dr Henrik, please allow me to help with the research.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790474"
        },
        [80080339] = {
          Camera = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "“Si el destino decide que no puedo vivir como una persona normal, al menos déjame morir como una…”",
          DialogueId = 80080339,
          GUID = "C879049E",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080340,
          SpeakNpcId = 790005,
          Subtitle = "\"If fate decides I can't live like a person, then at least let me die like one...\"",
          TalkActionId = {
            [1] = "790005:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879049E"
        },
        [80080340] = {
          Camera = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Esa fue la última voluntad de mi hija Hayley. Tú y ella son tan parecidas… y a la vez tan distintas.",
          DialogueId = 80080340,
          GUID = "C87904C8",
          LookAt = {
            [1] = "790005:n(790004)"
          },
          NextDialogue = 80080341,
          SpeakNpcId = 790005,
          Subtitle = "That was Hayley — my daughter's last wish. You and her are so alike, yet so different...",
          TalkActionId = {
            [1] = "790005:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87904C8"
        },
        [80080341] = {
          Camera = "-137.392578,-0.853027,138.126953,0.000042,13.199668,-95.195374,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "“Vivir como una persona normal”… ahora entiendo tu deseo.",
          DialogueId = 80080341,
          GUID = "C87904F2",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080342,
          SpeakNpcId = 790005,
          Subtitle = "\"To live like a person\" — I understand your wish now.",
          TalkActionId = {
            [1] = "790005:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87904F2"
        },
        [80080342] = {
          Camera = "-123.386719,-265.981384,183.080078,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentES = "Destino… te ruego que te apiades de mí esta vez… déjame ayudarla a cumplir este deseo.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080342,
          FinalCamera = "-123.013672,-238.728149,177.398438,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "C879051C",
          SpeakNpcId = 790005,
          Subtitle = "Fate, grant me mercy just this once... allow me to help her fulfil this wish.",
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "790005:p(180)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879051C"
        },
        [80090100] = {
          ContentES = "Jejeje… ¿qué travesura vamos a hacer hoy?",
          DialogueId = 80090100,
          GUID = "C87F4608",
          Subtitle = "Heehee, what mischief shall we get into today?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4608"
        },
        [80090101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "...",
          DialogueId = 80090101,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4632",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090102,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4632"
        },
        [80090102] = {
          ContentES = "...",
          DialogueId = 80090102,
          GUID = "C87F465C",
          NextDialogue = 80090103,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F465C"
        },
        [80090103] = {
          ContentES = "¡Oye! ¿No viste cómo desaparecí de repente después de terminar mi bebida? ¡¿Cómo puedes actuar como si nada hubiera pasado?!",
          DialogueId = 80090103,
          GUID = "C87F4686",
          NextDialogue = 80090104,
          SpeakNpcId = 92301,
          Subtitle = "...Hey! Didn't you see I suddenly vanished after finishing my drink? How could you just act like nothing happened?!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4686"
        },
        [80090104] = {
          ContentES = "¡A plena luz del día, yo, la Demonio Tabethe, la Mano Roja se desvanece misteriosamente! ¿Ni siquiera te da un poco de curiosidad… o preocupación?",
          DialogueId = 80090104,
          GUID = "C87F46B0",
          NextOptions = {
            [1] = 80090105,
            [2] = 80090107
          },
          SpeakNpcId = 92301,
          Subtitle = "Right in broad daylight, Demon Tabethe the Red Hand mysteriously disappeared! Aren't you at least a bit curious or worried?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F46B0"
        },
        [80090105] = {
          ContentES = "Hace un momento había una silla aquí. Esa eras tu transformada, ¿no?",
          DialogueId = 80090105,
          GUID = "C87F46DA",
          NextDialogue = 80090106,
          Subtitle = "There was an extra chair here... It was you, wasn't it?"
        },
        [80090106] = {
          ContentES = "¡¿Quuué?! ¡Descubriste mi increíble disfraz para ocultarme!",
          DialogueId = 80090106,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F4704",
          NextDialogue = 80090109,
          SpeakNpcId = 92301,
          Subtitle = "What?! You saw through my awesome disguise?!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4704"
        },
        [80090107] = {
          ContentES = "¿Por qué debería preocuparme? Al contrario, agradezco que te hayas transformado en una silla solo para entretenerme.",
          DialogueId = 80090107,
          GUID = "C87F472E",
          NextDialogue = 80090108,
          Subtitle = "Why would I be worried? If anything, I appreciate that you turned into a chair just to entertain me."
        },
        [80090108] = {
          ContentES = "¡Que no se te suba a la cabeza! ¡solo quería asustarte! ¡Buuu!",
          DialogueId = 80090108,
          GUID = "C87F4758",
          NextDialogue = 80090109,
          SpeakNpcId = 92301,
          Subtitle = "Pff, get over yourself — I was just trying to spook you! BOO! Get it?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4758"
        },
        [80090109] = {
          ContentES = "Puf... Esta vez me equivoqué, pero a la próxima me transformaré en algo que ni te imaginas…",
          DialogueId = 80090109,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4782",
          NextDialogue = 80090110,
          SpeakNpcId = 92301,
          Subtitle = "Hmph, I slipped up this time. But next time, I'll turn into something you'd never expect!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4782"
        },
        [80090110] = {
          ContentES = "¿Podría transformarme en…un barril? ¿Un candelabro? ¿Un gran martillo?",
          DialogueId = 80090110,
          GUID = "C87F47AC",
          NextDialogue = 80090111,
          SpeakNpcId = 92301,
          Subtitle = "What to turn into next... Maybe a barrel? A chandelier? Or even a big hammer?",
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F47AC"
        },
        [80090111] = {
          ContentES = "Guau, ¡qué talento tienes!",
          DialogueId = 80090111,
          GUID = "C87F47D6",
          NextDialogue = 80090112,
          SpeakNpcId = 790008,
          Subtitle = "Wow, you're really good at this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F47D6"
        },
        [80090112] = {
          ContentES = "¡Obvio! A este truco especial lo llamo… caramelo… camello… camuflo-algo… ¡Ah, sí! ¡“Camuflaje”!",
          DialogueId = 80090112,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4800",
          NextDialogue = 80090113,
          SpeakNpcId = 92301,
          Subtitle = "Of course! I heard this trick of mine is called... caramel... camel... camel-something... Ah — camouflage! That's it!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4800"
        },
        [80090113] = {
          ContentES = "Así que puedes transformarte en cualquier cosa...",
          DialogueId = 80090113,
          GUID = "C87F482A",
          NextDialogue = 80090114,
          SpeakNpcId = 790008,
          Subtitle = "So you can turn into anything?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F482A"
        },
        [80090114] = {
          ContentES = "Jiji, claro que sí. ¡Mira bien…!",
          DialogueId = 80090114,
          GUID = "C87F4854",
          NextDialogue = 80090144,
          SpeakNpcId = 92301,
          Subtitle = "Hehe, you bet! Watch this—",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4854"
        },
        [80090115] = {
          Camera = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
          ContentES = "Te haré una propuesta que no podrás rechazar. Será mejor que lo pienses muy bien antes de responder.",
          DialogueId = 80090115,
          GUID = "C87F487E",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090116,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I'll make an offer you can't refuse. Think it over before you respond.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F487E"
        },
        [80090116] = {
          ContentES = "Lo que me despierta son los negocios. ¿Y a ti?",
          DialogueId = 80090116,
          GUID = "C87F48A8",
          NextOptions = {
            [1] = 80090117,
            [2] = 80090119
          },
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What wakes me is business; what about you?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F48A8"
        },
        [80090117] = {
          ContentES = "Jaja... Lo que me despierta es el resplandor cegador de Demonio Tabethe, la Mano Roja.",
          DialogueId = 80090117,
          GUID = "C87F48D2",
          NextDialogue = 80090118,
          Subtitle = "Haha — what wakes me is the blinding brilliance of Demon Tabethe the Red Hand!"
        },
        [80090118] = {
          ContentES = "Jiji, con esa boca tan encantadora, cualquier bebida se queda corta…",
          DialogueId = 80090118,
          FacialId = {
            [1] = "790052:Happy01"
          },
          GUID = "C87F48FC",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hehe, you're so sweet — sweeter than this drink you made!",
          TalkActionId = {
            [1] = "790052:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F48FC"
        },
        [80090119] = {
          ContentES = "Jaja.... ¡Le voy a contar a Camilla!",
          DialogueId = 80090119,
          GUID = "C87F4926",
          NextDialogue = 80090120,
          Subtitle = "Haha — I'm going to tell on you to Camilla!"
        },
        [80090120] = {
          ContentES = "¡Jajaja! Pierdes tu tiempo, ¡no le tengo miedo! ¡Nadie puede atraparme, a la Demonio Tabethe, la Mano Roja!",
          DialogueId = 80090120,
          FacialId = {
            [1] = "790052:Confident01"
          },
          GUID = "C87F4950",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I'm not scared of her! No one can catch Demon Tabethe the Red Hand!",
          TalkActionId = {
            [1] = "790052:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4950"
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "Pero no puedo transformarme en cualquier cosa… ni demasiado grande ni demasiado pequeña. Puedo ser un gato, pero no un ratón… un barril sí, ¡pero un poste de luz ni pensarlo!",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          Subtitle = "But I can't turn into anything too big or too small. I can do a cat, but not a mouse; a barrel, but not a lamppost.",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F497A"
        },
        [80090122] = {
          ContentES = "Pero con eso basta y sobra para engañar a la mayoría de las personas. Puedo transformarme en lo que quiera: desde una lata hasta un basurero, y esos ladronzuelos caen en mis trampas sin saber quién los golpeó.",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301,
          Subtitle = "That's enough to fool most people, though. I can just turn into a bin or a crate, and those rotten thieves won't know what hit them!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49A4"
        },
        [80090123] = {
          ContentES = "...Vaya, esto podría causarme problemas algún día.",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124,
          Subtitle = "...Oh boy, this might be a problem someday."
        },
        [80090124] = {
          ContentES = "¿Qué dices ahí entre dientes, eh?",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F49F8",
          NextDialogue = 80090125,
          SpeakNpcId = 92301,
          Subtitle = "What are you mumbling about?",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49F8"
        },
        [80090125] = {
          ContentES = "Nada, solo estaba diciendo que eres genial.",
          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008,
          Subtitle = "Nothing, I just meant you are awesome.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A22"
        },
        [80090126] = {
          ContentES = "Pero evita convertirte en un basurero o una caja, por si acaso alguien pasa y te lastima mientras busca algo.",
          DialogueId = 80090126,
          GUID = "C87F4A4C",
          NextDialogue = 80090127,
          SpeakNpcId = 790008,
          Subtitle = "But maybe avoid turning into bins or crates next time. Wouldn't want someone accidentally smashing you while looking for something useful...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A4C"
        },
        [80090127] = {
          ContentES = "¿Quién tendría las manos tan revoltosas?",
          DialogueId = 80090127,
          GUID = "C87F4A76",
          NextDialogue = 80090128,
          SpeakNpcId = 92301,
          Subtitle = "Who would do that?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A76"
        },
        [80090128] = {
          ContentES = "Eh… ¿algunos transeúntes demasiado curiosos, tal vez?",
          DialogueId = 80090128,
          GUID = "C87F4AA0",
          NextDialogue = 80090129,
          SpeakNpcId = 790008,
          Subtitle = "Er... some overly curious passersby, perhaps?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4AA0"
        },
        [80090129] = {
          ContentES = "Siempre se quedan con lo que sirve y lo demás lo tiran... ¡Típico de los adultos malvados!",
          DialogueId = 80090129,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4ACA",
          NextDialogue = 80090130,
          SpeakNpcId = 92301,
          Subtitle = "Always taking what's useful and tossing the rest — typical bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4ACA"
        },
        [80090130] = {
          ContentES = "¿Esos transeúntes no querrían hacerle daño a nadie? Y… ¿quiénes son esos “adultos malvados” de los que hablas?",
          DialogueId = 80090130,
          GUID = "C87F4AF4",
          NextDialogue = 80090136,
          SpeakNpcId = 790008,
          Subtitle = "Those passersby wouldn't mean to hurt anyone! Anyway, who are those \"bad grown-ups\" you always talk about?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4AF4"
        },
        [80090131] = {
          ContentES = "¡Suena convincente! Menos mal que no andas con malas mañas.",
          DialogueId = 80090131,
          GUID = "C87F4B1E",
          NextDialogue = 80090132,
          Subtitle = "Sounds impressive; good thing you're not a baddy."
        },
        [80090132] = {
          ContentES = "¿Qué quieres decir?",
          DialogueId = 80090132,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F4B48",
          NextDialogue = 80090133,
          SpeakNpcId = 92301,
          Subtitle = "What do you mean?",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B48"
        },
        [80090133] = {
          ContentES = "Lo que quiero decir es que si esos listillos con malas intenciones tuvieran tu poder de camuflaje, toda la ciudad sería un caos.",
          DialogueId = 80090133,
          GUID = "C87F4B72",
          NextDialogue = 80090134,
          SpeakNpcId = 790008,
          Subtitle = "I mean, imagine if someone smart but nasty had your skills — the whole town would be in chaos.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B72"
        },
        [80090134] = {
          ContentES = "Sí, sí. ¡Yo también pienso lo mismo! Yo no soy como esos adultos malos. Espera… ¿me estás diciendo que no soy suficientemente lista?",
          DialogueId = 80090134,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F4B9C",
          NextDialogue = 80090135,
          SpeakNpcId = 92301,
          Subtitle = "Mm-hmm, I thought so too! I'm nothing like those bad grown-ups. Wait, are you saying I'm not smart?",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B9C"
        },
        [80090135] = {
          ContentES = "Claro que no, ¡eres muy lista! Pero bueno… me da curiosidad saber más de los “adultos malvados” de los que siempre hablas. ¿Quiénes son?",
          DialogueId = 80090135,
          GUID = "C87F4BC6",
          NextDialogue = 80090136,
          SpeakNpcId = 790008,
          Subtitle = "Of course not, Tabethe is very smart. Anyway, I've been curious about these \"bad grown-ups\" you always talk about. Who are they?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4BC6"
        },
        [80090136] = {
          ContentES = "¡Cualquier matón que se ensaña con los débiles! La primera vez que conocí a adultos malvados fue en el orfanato. Esos cuidadores… bueno, llamarlos “cuidadores” es mucho decir, más bien parecían carceleros.",
          DialogueId = 80090136,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4BF0",
          NextDialogue = 80090137,
          SpeakNpcId = 92301,
          Subtitle = "Any bullies who pick on the weak! The first time I met bad grown-ups was at the orphanage. Those caretakers... well, calling them \"caretakers\" is a stretch — they were more like jailers.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4BF0"
        },
        [80090137] = {
          ContentES = "En aquel entonces, cuando me pillaban buscando comida en la cocina, ¡me pegaban! ¡Bah, esos monstruos! Si lo hacía era porque nunca me daban suficiente comida.",
          DialogueId = 80090137,
          GUID = "C87F4C1A",
          NextDialogue = 80090138,
          SpeakNpcId = 92301,
          Subtitle = "Back then, when they caught me sneaking food in the kitchen, they'd beat me. Ugh, those monsters! I only did it because they never fed me enough!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4C1A"
        },
        [80090138] = {
          ContentES = "Si me los volviera a encontrar, los colgaría de patas a arriba y les haría mirar mientras me como toda la comida de la cocina.",
          DialogueId = 80090138,
          GUID = "C87F4C44",
          NextOptions = {
            [1] = 80090139,
            [2] = 80090140
          },
          SpeakNpcId = 92301,
          Subtitle = "If I ran into them now, I'd hang them upside down from the ceiling and make them watch as I eat up all the food in the kitchen!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4C44"
        },
        [80090139] = {
          ContentES = "Eso ya pasó. Esos adultos malvados ya no pueden lastimarte.",
          DialogueId = 80090139,
          GUID = "C87F4C6E",
          NextDialogue = 80090141,
          Subtitle = "There, there. Those bad grown-ups can't hurt you anymore."
        },
        [80090140] = {
          ContentES = "¡Sí, esos bribones se lo merecen!",
          DialogueId = 80090140,
          GUID = "C87F4C98",
          NextDialogue = 80090141,
          Subtitle = "Sounds great! Those baddies so deserve that."
        },
        [80090141] = {
          ContentES = "¡Exacto, exacto!",
          DialogueId = 80090141,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4CC2",
          NextDialogue = 80090142,
          SpeakNpcId = 92301,
          Subtitle = "Hmph! Exactly!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4CC2"
        },
        [80090142] = {
          ContentES = "Listo, estuvo muy buena mi bebida. La próxima vez te cuento más chismes sobre esos adultos malvados. ¡Ahora vamos a jugar!",
          DialogueId = 80090142,
          GUID = "C87F4CEC",
          NextDialogue = 80090143,
          SpeakNpcId = 92301,
          Subtitle = "Alright, I've finished my drink. I'll tell you more about those bad grown-ups next time. Now, let's go play outside!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4CEC"
        },
        [80090143] = {
          ContentES = "Jejeje, ¡juguemos al escondite! Esta vez no me encontrarás tan fácilmente.",
          DialogueId = 80090143,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F4D16",
          SpeakNpcId = 92301,
          Subtitle = "Hehehe, wanna play hide and seek? I bet you won't find me so easily this time!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4D16"
        },
        [80090144] = {
          DialogueId = 80090144,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "C87F4D17",
          IsBlack = 1
        },
        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "Hmm, esta bebida está un poco salada, pero sabe tan rica. Es como un algodón de azúcar con sabor a brisa marina.",
          DialogueId = 80090201,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F569A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090202,
          SpeakNpcId = 92301,
          Subtitle = "Mmm, this drink's a bit salty but so yummy — like sea breeze-flavored cotton candy!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F569A"
        },
        [80090202] = {
          ContentES = "Este sabor me recuerda a algo que probé hace mucho tiempo… cuando todavía estaba con mi mamá y mi papá, antes de que nuestro barco se hundiera y yo terminara en ese orfanato…",
          DialogueId = 80090202,
          GUID = "C87F56C4",
          NextDialogue = 80090203,
          SpeakNpcId = 92301,
          Subtitle = "It kind of reminds me of something I drank long ago... back when I was still with my mom and dad, before our ship sank and I ended up at that orphanage...",
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F56C4"
        },
        [80090203] = {
          ContentES = "¡Pero si me dieran a elegir, preferiría vagar sola por el mundo! Esos adultos malvados ni siquiera querían darnos suficiente comida, ¡y mucho menos algo rico para beber!",
          DialogueId = 80090203,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F56EE",
          NextDialogue = 80090204,
          SpeakNpcId = 92301,
          Subtitle = "But honestly, I'd choose wandering on my own over staying with those bad grown-ups! They were stingy with food, not to mention anything as nice as a drink.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F56EE"
        },
        [80090204] = {
          ContentES = "Al menos estando en la calle podía buscar algo de comer en los basureros, ¡eso era mejor que morirme de hambre bajo las garras de esos adultos malvados!",
          DialogueId = 80090204,
          GUID = "C87F5718",
          NextDialogue = 80090205,
          SpeakNpcId = 92301,
          Subtitle = "At least being on the streets, I could scavenge for something to eat — beats starving under the watch of those bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5718"
        },
        [80090205] = {
          ContentES = "Cuando fui un poco mayor, de vez en cuando venían unos supuestos visitantes y se llevaban a niños con cuernitos como yo, esos a los que nadie quería. Decían que una familia rica los estaba adoptando.",
          DialogueId = 80090205,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F5742",
          NextDialogue = 80090206,
          SpeakNpcId = 92301,
          Subtitle = "When I got a bit older, groups of rich visitors would come by now and then, taking away some unwanted kids with horns like me. People at the orphanage said they were adopted by rich families.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5742"
        },
        [80090206] = {
          ContentES = "Yo no deseaba tener otros papás, pero al considerar que, si era parte de una familia rica no volvería a pasar hambre, claro que quería que me adoptaran. Pero esos adultos malvados decían que ninguna familia querría a una mocosa problemática como yo.",
          DialogueId = 80090206,
          GUID = "C87F576C",
          NextDialogue = 80090207,
          SpeakNpcId = 92301,
          Subtitle = "I didn't want new parents, but I thought being in a rich home meant I'd never go hungry again, so I wanted them to take me. But those bad grown-ups said no rich people would want a naughty troublemaker like me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F576C"
        },
        [80090207] = {
          ContentES = "¡Ja! ¡Como si yo fuera a portarme bien solo para que me adoptaran! No soportaba ni un día más en ese lugar horrible, así que cuando vinieron de visita… ¡me transformé en una de sus maletas!",
          DialogueId = 80090207,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5796",
          NextDialogue = 80090208,
          SpeakNpcId = 92301,
          Subtitle = "Hmph! As if I'd ever behave just to be chosen! I couldn't stand that awful place for another day, so during their visit, I transformed into one of their suitcases.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5796"
        },
        [80090208] = {
          ContentES = "¡Resulta que esos ricachones no eran tan listos! Me levantaron y se fueron tan tranquilos, sin sospechar nada. Aunque mis pobres orejas sufrieron lo peor… ¡Las usaron como asas y casi me dejan caer en el camino!",
          DialogueId = 80090208,
          GUID = "C87F57C0",
          NextOptions = {
            [1] = 80090209,
            [2] = 80090211
          },
          SpeakNpcId = 92301,
          Subtitle = "Turns out those rich folks weren't too bright — they just picked me up and walked away, completely clueless. It was rough on my ears, though — they were pulled as the handles, and I almost got dropped along the way!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F57C0"
        },
        [80090209] = {
          ContentES = "¡Eso debió doler muchísimo! ¡A partir de ahora protegeré tus orejas!",
          DialogueId = 80090209,
          GUID = "C87F57EA",
          NextDialogue = 80090210,
          Subtitle = "Oof, that must've hurt a lot! I'll take extra care of your ears from now on!"
        },
        [80090210] = {
          ContentES = "Gracias, aunque eso sonó un poco raro...",
          DialogueId = 80090210,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F5814",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          Subtitle = "...Thanks, sounds a bit weird though...",
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5814"
        },
        [80090211] = {
          ContentES = "¡Escapar de ese lugar demuestra que Demonio Tabethe, la Mano Roja, ya era increíble incluso cuando era una niña!",
          DialogueId = 80090211,
          GUID = "C87F583E",
          NextDialogue = 80090212,
          Subtitle = "Managing to escape from that place proves Demon Tabethe the Red Hand was awesome even as a kid!"
        },
        [80090212] = {
          ContentES = "Jiji, ¡por supuesto! Lástima que en ese entonces no era tan hábil, si no jamás habría convertido mis orejas en las asas.",
          DialogueId = 80090212,
          GUID = "C87F5868",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          Subtitle = "Hehe, you bet! Too bad I wasn't as skilled back then, or I wouldn't have turned my ears into the handles.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5868"
        },
        [80090213] = {
          ContentES = "En realidad, mi plan era colarme entre esos niños que iban a ser adoptados, así ya nunca más volvería a pasar hambre.",
          DialogueId = 80090213,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5892",
          NextDialogue = 80090214,
          SpeakNpcId = 92301,
          Subtitle = "Actually, I was planning to sneak in with those kids getting adopted, hoping I'd never starve again with a rich family.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5892"
        },
        [80090214] = {
          ContentES = "¡Y luego esos ricachones apestaban a desinfectante! Me picaba la nariz del puro olor. Además… no sé por qué, pero la forma en que miraban a los niños… me daba muy mala espina.",
          DialogueId = 80090214,
          GUID = "C87F58BC",
          NextDialogue = 80090215,
          SpeakNpcId = 92301,
          Subtitle = "But those rich people reeked of disinfectant — it stung my nose! And the way they looked at those kids... I don't know why, but it gave me the creeps...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58BC"
        },
        [80090215] = {
          ContentES = "Era como… ¡como la mirada de un chef evaluando a un pez o un pato antes de cocinarlo!",
          DialogueId = 80090215,
          GUID = "C87F58E6",
          NextDialogue = 80090216,
          SpeakNpcId = 92301,
          Subtitle = "It was like... a chef sizing up fish or ducks!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58E6"
        },
        [80090216] = {
          ContentES = "¡Los buenos adultos casi ni existen, pero malvados he visto muchos! En lugar de confiar en ellos, mejor confío en mí misma.",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          Subtitle = "I've seen too many bad grown-ups to trust them — I might be better off on my own. So I didn't join those kids, and ended up running away by myself.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5910"
        },
        [80090217] = {
          ContentES = "¡Y ese fue mi primer paso para convertirme en la Demonio Tabethe, la Mano Roja!",
          DialogueId = 80090217,
          GUID = "C87F593A",
          NextOptions = {
            [1] = 80090218,
            [2] = 80090220
          },
          SpeakNpcId = 92301,
          Subtitle = "And that was my first step towards becoming Demon Tabethe the Red Hand!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F593A"
        },
        [80090218] = {
          ContentES = "Creo que no eres una niña mala, solo… eres algo especial.",
          DialogueId = 80090218,
          GUID = "C87F5964",
          NextDialogue = 80090219,
          Subtitle = "I think you're not a bad kid, Tabethe. You're just... very special."
        },
        [80090219] = {
          ContentES = "¿No soy mala, sino especial? Nadie me lo había dicho antes… Niña especial… Jeje.",
          DialogueId = 80090219,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F598E",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          Subtitle = "Not bad, just special? No one's ever put it that way before... A special kid, special... Hehe!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F598E"
        },
        [80090220] = {
          ContentES = "Esos ricachones sonaban bastante sospechosos. Tomaste una buena decisión, Tabethe.",
          DialogueId = 80090220,
          GUID = "C87F59B8",
          NextDialogue = 80090221,
          Subtitle = "Those rich visitors sounded really sketchy; you made a smart call, Tabethe."
        },
        [80090221] = {
          ContentES = "¡Exacto! Tú estás de acuerdo conmigo, ¿verdad?",
          DialogueId = 80090221,
          GUID = "C87F59E2",
          NextDialogue = 80090222,
          SpeakNpcId = 92301,
          Subtitle = "Exactly, you got it!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F59E2"
        },
        [80090222] = {
          ContentES = "Solo quería escapar. Si hubiera tenido en ese entonces las habilidades que tengo ahora, sin duda los hubiera seguido sigilosamente para ver lo que estaban tramando.",
          DialogueId = 80090222,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5A0C",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          Subtitle = "Back then, I was just focused on getting away. If I were as good at my disguise tricks then, I would've secretly followed them to see what they were really up to!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A0C"
        },
        [80090223] = {
          ContentES = "Hiciste muy bien en escapar, Tabethe. ¡Felicidades por haber logrado tu libertad!",
          DialogueId = 80090223,
          GUID = "C87F5A36",
          NextDialogue = 80090224,
          SpeakNpcId = 790008,
          Subtitle = "Getting out safely on your own was already something. Congratulations on earning your freedom, Tabethe.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A36"
        },
        [80090224] = {
          ContentES = "¡Sí, realmente hice bien! Es increíble respirar de nuevo aire fresco. Me di cuenta de que el cielo nocturno no siempre era tan oscuro, y las estrellas, que veía difuminadas a través del vidrio sucio, eran en realidad brillantes y hermosas.",
          DialogueId = 80090224,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F5A60",
          NextDialogue = 80090225,
          SpeakNpcId = 92301,
          Subtitle = "Yeah, I did great! Breathing fresh air again was so awesome. For the first time, I realised the night sky wasn't always so dark, and the dim stars I'd seen through dirty glass were actually bright and beautiful.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A60"
        },
        [80090225] = {
          ContentES = "Esa noche dormí bajo las estrellas, sobre el césped, ¡y desperté con un hermoso día soleado! Desde entonces, he estado viviendo en aquel pequeño pueblo costero, libre de esos adultos malvados.",
          DialogueId = 80090225,
          GUID = "C87F5A8A",
          NextDialogue = 80090226,
          SpeakNpcId = 92301,
          Subtitle = "I slept under the stars that night, right on the grass — and woke up to a beautiful sunny day! Since that day, I've been living in that little seaside town, free from those bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A8A"
        },
        [80090226] = {
          ContentES = "Además, conocí a alguien allí…",
          DialogueId = 80090226,
          GUID = "C87F5AB4",
          NextDialogue = 80090227,
          SpeakNpcId = 92301,
          Subtitle = "And I met someone there...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5AB4"
        },
        [80090227] = {
          ContentES = "¿Por fin conociste a una buena persona?",
          DialogueId = 80090227,
          GUID = "C87F5ADE",
          NextDialogue = 80090228,
          SpeakNpcId = 790008,
          Subtitle = "Did you finally meet someone kind?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5ADE"
        },
        [80090228] = {
          ContentES = "Sí, una persona buena de verdad. Pero ahora estoy un poco cansada… ¡Incluso la Demonio Tabethe, la Mano Roja se cansa!",
          DialogueId = 80090228,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F5B08",
          NextDialogue = 80090229,
          SpeakNpcId = 92301,
          Subtitle = "Yep, a really, really kind person! But I'm a bit tired now... even Demon Tabethe the Red Hand needs her rest!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5B08"
        },
        [80090229] = {
          ContentES = "La próxima vez que me prepares otra bebida, te lo contaré.",
          DialogueId = 80090229,
          GUID = "C87F5B32",
          SpeakNpcId = 92301,
          Subtitle = "Next time you whip up a new drink, I'll tell you all about it!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5B32"
        },
        [80090301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "¡La bebida de hoy está muy buena! Jejeje, ¡sabes exactamente lo que me gusta!",
          DialogueId = 80090301,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F6702",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090302,
          SpeakNpcId = 92301,
          Subtitle = "Yum-yum! This drink's so good — just like all the other drinks you've made! Hehe, you know exactly what I like.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6702"
        },
        [80090302] = {
          ContentES = "Anoche me quedé dormida tumbada en el césped, mirando el cielo nocturno. El azul del cielo se fue oscureciendo poco a poco, y las estrellas parecían arándanos cubiertos de azúcar.",
          DialogueId = 80090302,
          GUID = "C87F672C",
          NextDialogue = 80090303,
          SpeakNpcId = 92301,
          Subtitle = "I fell asleep on the grass under the stars last night. The sky turned from bright blue to dark navy, with stars twinkling like frosting on a blueberry smoothie!",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F672C"
        },
        [80090303] = {
          ContentES = "Sin contar la noche que escapé del orfanato, casi nunca he dormido tan a gusto sobre el césped.",
          DialogueId = 80090303,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6756",
          NextDialogue = 80090304,
          SpeakNpcId = 92301,
          Subtitle = "Except for the night I escaped the orphanage, I almost never had such a sound night's sleep on the grass.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6756"
        },
        [80090304] = {
          ContentES = "Porque al principio, cuando llegué a este pueblo, hice un montón de travesuras…",
          DialogueId = 80090304,
          GUID = "C87F6780",
          NextDialogue = 80090305,
          SpeakNpcId = 92301,
          Subtitle = "...Because when I first got to the town, I did a lot of bad stuff...",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6780"
        },
        [80090305] = {
          ContentES = "Por eso, no le simpatizo a los adultos y me apodaron la “Demonio”.",
          DialogueId = 80090305,
          GUID = "C87F67AA",
          NextOptions = {
            [1] = 80090306,
            [2] = 80090308
          },
          SpeakNpcId = 92301,
          Subtitle = "The grown-ups there hated me for that. They called me a \"demon\"...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F67AA"
        },
        [80090306] = {
          ContentES = "¿Tal vez te excediste con tus travesuras?",
          DialogueId = 80090306,
          GUID = "C87F67D4",
          NextDialogue = 80090307,
          Subtitle = "Did you maybe go too far with your pranks?"
        },
        [80090307] = {
          ContentES = "¡Es que son demasiado tontos! Humm… bueno, está bien, tienes razón.",
          DialogueId = 80090307,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F67FE",
          NextDialogue = 80090310,
          SpeakNpcId = 92301,
          Subtitle = "They could've handled it if they were smarter! Well... you're right, it was my fault.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F67FE"
        },
        [80090308] = {
          ContentES = "¿Será que te comiste todos los peces del pueblo?",
          DialogueId = 80090308,
          GUID = "C87F6828",
          NextDialogue = 80090309,
          Subtitle = "Did you polish off all the fish in town?"
        },
        [80090309] = {
          ContentES = "¡No como tanto! Hum… aunque en parte tienes razón…",
          DialogueId = 80090309,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F6852",
          NextDialogue = 80090310,
          SpeakNpcId = 92301,
          Subtitle = "I'm not that big of an eater! Well, you got part of it right though...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6852"
        },
        [80090310] = {
          ContentES = "He sobrevivido robando comida de los puestos callejeros. Cuando los vendedores se enfadaban y querían castigarme, yo los molestaba y les hacía muecas. No pensaba que estuviera haciendo algo malo.",
          DialogueId = 80090310,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F687C",
          NextDialogue = 80090311,
          SpeakNpcId = 92301,
          Subtitle = "I had been living off stealing food from the street stalls. The vendors were so mad they tried to beat me, but I just mimicked their angry faces to piss them off. I didn't think what I did was wrong back then.",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F687C"
        },
        [80090311] = {
          ContentES = "“¡Solo tomé un poquito, no se van a morir de hambre, tacaños!”",
          DialogueId = 80090311,
          GUID = "C87F68A6",
          NextDialogue = 80090312,
          SpeakNpcId = 92301,
          Subtitle = "\"I just took a little, it's not like you'd starve! Tightwad!\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68A6"
        },
        [80090312] = {
          ContentES = "Pero, todo cambió cuando la conocí…",
          DialogueId = 80090312,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F68D0",
          NextDialogue = 80090313,
          SpeakNpcId = 92301,
          Subtitle = "Until I met her...",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68D0"
        },
        [80090313] = {
          ContentES = "Era la hija de un pescador. Cuando me descubrió robando del puesto de su padre, no me regañó, al contrario, me regaló pescados y me preguntó si me había perdido. Luego, me invitó a quedarme en su casa esa noche. Nunca antes había conocido a alguien tan amable.",
          DialogueId = 80090313,
          GUID = "C87F68FA",
          NextDialogue = 80090314,
          SpeakNpcId = 92301,
          Subtitle = "She was the fishmonger's daughter. She caught me stealing from her dad's stall but didn't tell on me; instead, she gave me fish to fill my belly, asked if I was separated from my family, and even offered me a place to stay for the night. She was the first truly kind person I'd ever met.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68FA"
        },
        [80090314] = {
          ContentES = "Luego sucedieron muchas cosas… Perdió su casa, la iban a enviar al orfanato y... ¡y yo no iba a permitir que ella sufriera lo mismo que yo! Decidí que sería su familia..",
          DialogueId = 80090314,
          GUID = "C87F6924",
          NextDialogue = 80090315,
          SpeakNpcId = 92301,
          Subtitle = "A lot happened after that... She ended up without a home and had to go to the orphanage — like I'd let her go through what I had! I decided I'd be her family!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6924"
        },
        [80090315] = {
          ContentES = "Nos reíamos todos los días, jugábamos con el agua en la playa y nos mojábamos la una a la otra, mientras yo me transformaba en todo tipo de animalitos para hacerla reír.",
          DialogueId = 80090315,
          GUID = "C87F694E",
          NextDialogue = 80090316,
          SpeakNpcId = 92301,
          Subtitle = "We'd giggle under the hot sun, splash each other by the sea, and race down muddy paths together. I'd turn into little animals just to make her laugh.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F694E"
        },
        [80090316] = {
          ContentES = "Era como una hermanita para mí y me llamaba Hermana Mayor Tabethe. Aunque no siempre teníamos suficiente comida, siempre decía que era feliz.",
          DialogueId = 80090316,
          GUID = "C87F6978",
          NextDialogue = 80090317,
          SpeakNpcId = 92301,
          Subtitle = "She was like a little sister to me — she'd call me Big Sis Tabethe. Even though we didn't always have enough food, she always said she was happy.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6978"
        }
      }
    end
  },
  {
    MinKey = 80090317,
    MaxKey = 80110102,
    Loader = function()
      return {
        [80090317] = {
          ContentES = "Por ella dejé de robar a los adultos buenos. ¡A partir de ese momento, Demonio Tabethe, la Mano Roja, solo se fijaría en los malos!",
          DialogueId = 80090317,
          GUID = "C87F69A2",
          NextOptions = {
            [1] = 80090318,
            [2] = 80090320
          },
          SpeakNpcId = 92301,
          Subtitle = "It was because of her that I decided to stop stealing from good grown-ups. From then on, Demon Tabethe the Red Hand would only target the bad ones!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F69A2"
        },
        [80090318] = {
          ContentES = "¿Te importa mucho lo que piensa?",
          DialogueId = 80090318,
          GUID = "C87F69CC",
          NextDialogue = 80090319,
          Subtitle = "Is it because you care about what she thinks?"
        },
        [80090319] = {
          ContentES = "Sí, no quiero que se sienta triste.",
          DialogueId = 80090319,
          GUID = "C87F69F6",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          Subtitle = "Yeah. I didn't wanna break her heart.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F69F6"
        },
        [80090320] = {
          ContentES = "¡Hermana mayor Tabethe!",
          DialogueId = 80090320,
          GUID = "C87F6A20",
          NextDialogue = 80090321,
          Subtitle = "Big Sis Tabethe!"
        },
        [80090321] = {
          ContentES = "¡Ay, cállate, qué vergüenza!",
          DialogueId = 80090321,
          FacialId = {
            [1] = "92301:Unacceptable01"
          },
          GUID = "C87F6A4A",
          NextDialogue = 80090322,
          SpeakNpcId = 92301,
          Subtitle = "Wha... Stop it! You're embarrassing both yourself and me!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6A4A"
        },
        [80090322] = {
          ContentES = "Si yo también te llamara hermana, ¿me llevarías a vivir contigo?",
          DialogueId = 80090322,
          GUID = "C87F6A74",
          NextDialogue = 80090323,
          SpeakNpcId = 790008,
          Subtitle = "I just wanted to see if you'd also take me in if I called you that...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6A74"
        },
        [80090323] = {
          ContentES = "¿Tienes ocho años o qué? Compórtate como alguien de tu edad.",
          DialogueId = 80090323,
          GUID = "C87F6A9E",
          NextDialogue = 80090324,
          SpeakNpcId = 92301,
          Subtitle = "...Are you an eight-year-old? Come on, act your age.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6A9E"
        },
        [80090324] = {
          ContentES = "Era una broma. Entonces, ¿te importa mucho lo que ella piensa?",
          DialogueId = 80090324,
          GUID = "C87F6AC8",
          NextDialogue = 80090325,
          SpeakNpcId = 790008,
          Subtitle = "Just kidding. So, was it because you really care about what she thinks?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6AC8"
        },
        [80090325] = {
          ContentES = "Ella me preguntó si estaba bien robarle a las personas buenas.",
          DialogueId = 80090325,
          GUID = "C87F6AF2",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          Subtitle = "She once asked me, \"Is it right to steal from good people?\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6AF2"
        },
        [80090326] = {
          ContentES = "Al principio no le hice caso. ¿Cómo podrían esos vendedores ser buenas personas? Me moría de hambre y solo me gritaban, sin darme nunca nada de comer.",
          DialogueId = 80090326,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6B1C",
          NextDialogue = 80090327,
          SpeakNpcId = 92301,
          Subtitle = "At first, I didn't listen — how could those vendors be good people? I was starving, and they just yelled at me, never giving me anything to eat.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B1C"
        },
        [80090327] = {
          ContentES = "Luego me di cuenta de que algunos vendedores me veían robar, pero no me decían nada.",
          DialogueId = 80090327,
          GUID = "C87F6B46",
          NextDialogue = 80090328,
          SpeakNpcId = 92301,
          Subtitle = "But then I realised — some vendors actually saw me stealing, but they looked the other way.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B46"
        },
        [80090328] = {
          ContentES = "Y los que me persiguieron nunca llegaron a seguirme de verdad... Claro, no podrían haberme atrapado si lo hubieran intentado, ¡yo era muy rápida...!",
          DialogueId = 80090328,
          GUID = "C87F6B70",
          NextDialogue = 80090329,
          SpeakNpcId = 92301,
          Subtitle = "And those who chased me never really followed through... Of course, they couldn't catch me if they tried — I was fast...!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B70"
        },
        [80090329] = {
          ContentES = "Algunos incluso me daban la comida que no lograban vender. Yo pensaba que lo hacían por miedo, como si me estuvieran pagando “protección”.",
          DialogueId = 80090329,
          GUID = "C87F6B9A",
          NextDialogue = 80090330,
          SpeakNpcId = 92301,
          Subtitle = "And some vendors even left unsold food out for me. But back then I thought they did it because they were scared of me and were paying protection money.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B9A"
        },
        [80090330] = {
          ContentES = "Guardaba tanto rencor hacia los adultos malvados que no veía la bondad de los adultos buenos.",
          DialogueId = 80090330,
          GUID = "C87F6BC4",
          NextDialogue = 80090331,
          SpeakNpcId = 92301,
          Subtitle = "I held such a grudge against the bad people I met, that I was completely blind to the kindness of those good people.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6BC4"
        },
        [80090331] = {
          ContentES = "Cuando me di cuenta de todo esto, me sentí tan mal que la comida que había robado me supo amarga.",
          DialogueId = 80090331,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6BEE",
          NextDialogue = 80090332,
          SpeakNpcId = 92301,
          Subtitle = "When I realised all this, I felt so bad that the food I stole tasted off.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6BEE"
        },
        [80090332] = {
          ContentES = "Creo que toda la rabia que había acumulado contra los adultos malos la terminé descargando con esos vendedores.",
          DialogueId = 80090332,
          GUID = "C87F6C18",
          NextDialogue = 80090333,
          SpeakNpcId = 92301,
          Subtitle = "I guess I'd been taking out my hate for the bad grown-ups on those vendors.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6C18"
        },
        [80090333] = {
          ContentES = "Fui una verdadera Demonio...",
          DialogueId = 80090333,
          GUID = "C87F6C42",
          NextOptions = {
            [1] = 80090334,
            [2] = 80090336
          },
          SpeakNpcId = 92301,
          Subtitle = "I really was a demon...",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6C42"
        },
        [80090334] = {
          ContentES = "No tienes que culparte, Tabethe. Muchas personas pasan toda su vida sin reconocer sus errores. Tú lo hiciste muy bien.",
          DialogueId = 80090334,
          GUID = "C87F6C6C",
          NextDialogue = 80090335,
          Subtitle = "There's no need to beat yourself up, Tabethe. A lot of people fail to own up to their mistakes in a whole lifetime. You already did great."
        },
        [80090335] = {
          ContentES = "Gracias… pero en realidad, no hace falta que me consueles. Sé que lo que hice estuvo mal.",
          DialogueId = 80090335,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6C96",
          NextDialogue = 80090338,
          SpeakNpcId = 92301,
          Subtitle = "Thank you... but you don't need to sugar-coat it for me. I know what I did was wrong.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6C96"
        },
        [80090336] = {
          ContentES = "Algún día crecerás y si sigues molestando a las personas buenas, ¿no te convertiría eso en una adulta malvada?",
          DialogueId = 80090336,
          GUID = "C87F6CC0",
          NextDialogue = 80090337,
          Subtitle = "You will grow up someday. Wouldn't bullying good people just make you one of the bad grown-ups?"
        },
        [80090337] = {
          ContentES = "Tienes razón… regáñame cuanto quieras, lo escucharé todo sin replicar.",
          DialogueId = 80090337,
          GUID = "C87F6CEA",
          NextDialogue = 80090338,
          SpeakNpcId = 92301,
          Subtitle = "You're right... Go ahead and let me have it. I won't talk back — I deserve this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6CEA"
        },
        [80090338] = {
          ContentES = "Desde entonces, solo robaba a los ladrones y a los adultos malvados. Se siente genial no hacer daño a los buenos.",
          DialogueId = 80090338,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F6D14",
          NextDialogue = 80090339,
          SpeakNpcId = 92301,
          Subtitle = "Ever since then, I'd only take stuff from bad thieves and mean grown-ups. It felt great, and it wouldn't hurt good people.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D14"
        },
        [80090339] = {
          ContentES = "¿Y adivina qué? ¡Esos malvados están forrados de dinero! Ahora casi nunca paso hambre. Además, me encanta gastarles bromas y verlos enfadarse. ¡Es muy divertido!",
          DialogueId = 80090339,
          GUID = "C87F6D3E",
          NextOptions = {
            [1] = 80090340
          },
          SpeakNpcId = 92301,
          Subtitle = "And guess what — those bad guys are loaded! I hardly ever go hungry now. Plus, I get to play tricks on them and watch them fume, hehe, it's so much fun!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D3E"
        },
        [80090340] = {
          ContentES = "Más que la comida, lo que te divierte es hacerles travesuras, ¿verdad?",
          DialogueId = 80090340,
          GUID = "C87F6D68",
          NextDialogue = 80090341,
          Subtitle = "It's more about the fun of playing tricks on them than finding stuff to eat, huh?"
        },
        [80090341] = {
          ContentES = "¡Exacto! Eh, bueno… ¡no realmente! Es más bien hacer justicia. Solo les enseño a no meterse con las personas buenas.",
          DialogueId = 80090341,
          GUID = "C87F6D92",
          NextDialogue = 80090342,
          SpeakNpcId = 92301,
          Subtitle = "Exactly! Er, I mean, not really! This is about \"serving justice.\" All I did was teach them not to mess with the good folks.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D92"
        },
        [80090342] = {
          ContentES = "¡Hoy he hablado tanto que creo que mi garganta está echando humo!",
          DialogueId = 80090342,
          GUID = "C87F6DBC",
          NextDialogue = 80090343,
          SpeakNpcId = 92301,
          Subtitle = "Whew, that was a lot of talking today — my throat's literally smoking!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6DBC"
        },
        [80090343] = {
          ContentES = "Jejeje, ese batido de arándanos estaba buenísimo, ¡dame otro vaso!",
          DialogueId = 80090343,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F6DE6",
          SpeakNpcId = 92301,
          Subtitle = "Hehe, can I get a refill of that blueberry drink?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6DE6"
        },
        [80090401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "¡Está delicioso! Nunca me voy a cansar de esta bebida. No suelo decir cosas bonitas, pero muchas gracias por preparármela.",
          DialogueId = 80090401,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F776A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090402,
          SpeakNpcId = 92301,
          Subtitle = "This is so good! I could never get enough of this drink! I don't often say nice things, but thank you for always making these for me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F776A"
        },
        [80090402] = {
          ContentES = "Jejeje, ya que me has preparado tantas bebidas deliciosas, ¡es justo que te devuelva el favor!",
          DialogueId = 80090402,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F7794",
          NextDialogue = 80090403,
          SpeakNpcId = 92301,
          Subtitle = "Hehehe, since you've made so many good drinks for me, it's time I return the favour!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7794"
        },
        [80090403] = {
          ContentES = "Delante de ti, hay una bebida sospechosa de color oscuro, que burbujea y desprende un olor extraño. Al mirarla de cerca, reconoces distintos frutos secos y caramelos depositados en el fondo.",
          DialogueId = 80090403,
          GUID = "C87F77BE",
          NextDialogue = 80090404,
          Subtitle = "Before you is a suspicious dark drink, bubbling and giving off a strange scent. Upon closer inspection, you recognise various dried fruits and candies settled at the bottom."
        },
        [80090404] = {
          ContentES = "¡Tarán! Contempla mi creación especial, la Demonio Tabethe, la Mano Roja, ¡nombrada en honor a mi propio título! Este vaso está lleno de mi gratitud, jejeje.",
          DialogueId = 80090404,
          GUID = "C87F77E8",
          NextOptions = {
            [1] = 80090405,
            [2] = 80090410
          },
          SpeakNpcId = 92301,
          Subtitle = "Ta-da! Behold my special creation — Demon Tabethe the Red Hand — named after my own title! Just so you know, this glass is filled with my thanks, hehe!",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F77E8"
        },
        [80090405] = {
          ContentES = "Rechazar la bebida",
          DialogueId = 80090405,
          GUID = "C87F7812",
          NextDialogue = 80090406,
          Subtitle = "Refuse the drink"
        },
        [80090406] = {
          ContentES = "¡Vamos! ¡Esta es la única “Demonio Tabethe, la Mano Roja” en el mundo!",
          DialogueId = 80090406,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F783C",
          NextDialogue = 80090407,
          SpeakNpcId = 92301,
          Subtitle = "Come on! This is the one and only \"Demon Tabethe the Red Hand\" in the world!",
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F783C"
        },
        [80090407] = {
          ContentES = "Puse en esta bebida toda la comida deliciosa que los adultos buenos me han dado. He ido guardando los ingredientes poco a poco, me esforcé para no comerlos todos de una. ¡Ni me imagino lo deliciosa que será esta bebida con todas esas cosas buenas juntas!",
          DialogueId = 80090407,
          GUID = "C87F7866",
          NextDialogue = 80090408,
          SpeakNpcId = 92301,
          Subtitle = "I've put all the good food that good grown-ups gave me into this drink. I've been saving the ingredients bit by bit — tried so hard not to eat them right away! I can't even imagine how yummy this drink will be with all that good stuff put together!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7866"
        },
        [80090408] = {
          ContentES = "¿Qué tal si la compartimos? ¡No es que no quiera probarla! ¡Solo estoy dando un ejemplo para un cobarde!",
          DialogueId = 80090408,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F7890",
          NextDialogue = 80090409,
          SpeakNpcId = 92301,
          Subtitle = "How about we share it? Not that I want to try it myself! I'm just setting an example for a coward!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7890"
        },
        [80090409] = {
          ContentES = "¡Venga, brindemos!",
          DialogueId = 80090409,
          GUID = "C87F78BA",
          SpeakNpcId = 92301,
          Subtitle = "Cheers!",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F78BA"
        },
        [80090410] = {
          ContentES = "Aceptar la bebida",
          DialogueId = 80090410,
          GUID = "C87F78E4",
          NextDialogue = 80090411,
          Subtitle = "Accept the drink"
        },
        [80090411] = {
          ContentES = "¡Una elección digna de alguien con buen gusto!",
          DialogueId = 80090411,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F790E",
          NextDialogue = 80090412,
          SpeakNpcId = 92301,
          Subtitle = "Excellent choice!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F790E"
        },
        [80090412] = {
          ContentES = "Puse en esta bebida toda la comida deliciosa que los adultos buenos me han dado. He ido guardando los ingredientes poco a poco, me esforcé para no comerlos todos de una. ¡Ni me imagino lo deliciosa que será esta bebida con todas esas cosas buenas juntas!",
          DialogueId = 80090412,
          GUID = "C87F7938",
          NextDialogue = 80090413,
          SpeakNpcId = 92301,
          Subtitle = "I've put all the good food that good grown-ups gave me into this drink. I've been saving the ingredients bit by bit — tried so hard not to eat them right away! I can't even imagine how yummy this drink will be with all that good stuff put together!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7938"
        },
        [80090413] = {
          ContentES = "¿Quién más que tú merece esta bebida tan deliciosa? Aunque... ¿me compartirías un poquito? No te la acabes toda, jejeje. Tengo curiosidad a qué sabe la mejor bebida del mundo.",
          DialogueId = 80090413,
          GUID = "C87F7962",
          NextDialogue = 80090414,
          SpeakNpcId = 92301,
          Subtitle = "Who else but you deserves such a precious drink, right? But could you share a little with me? Hehe, I'm curious what the best drink in the world tastes like!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7962"
        },
        [80090414] = {
          ContentES = "¡Bueno, ya basta de tanta cháchara! ¡Salud!",
          DialogueId = 80090414,
          GUID = "C87F798C",
          SpeakNpcId = 92301,
          Subtitle = "Alright, I'm done getting all mushy! Cheers!",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F798C"
        },
        [80090415] = {
          ContentES = "{性别:Ambos|Ambas} vacían la bebida especial de Tabethe. Un extraño dulzor inunda tu boca, y poco después pierdes el conocimiento.",
          DialogueId = 80090415,
          GUID = "C87F79B6",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "You both chug Tabethe's special concoction. A bizarre sweetness overwhelms your taste buds; soon after, you black out."
        },
        [80090416] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "Aún respiraban. Solo se desmayaron, pero están bien.",
          DialogueId = 80090416,
          DisableMouth = 1,
          FacialId = {
            [1] = "92301:Close"
          },
          GUID = "C87F79E0",
          IsBlack = 1,
          NextDialogue = 80090417,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "They're still breathing. Both of them are fine — just passed out.",
          TalkActionId = {
            [1] = "92301:Zhangyu_Story_Tentacle"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F79E0"
        },
        [80090417] = {
          ContentES = "¡Ipuu! ¡Casi me matan del susto! Le advertí a Tabethe que no ponga cualquier cosa en esa bebida, ¡no es segura!",
          DialogueId = 80090417,
          DisableMouth = 1,
          GUID = "C87F7A0A",
          IsBlack = 1,
          NextDialogue = 80090418,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Waah... I was so scared... I've warned Tabethe not to put just anything in that drink — it's not safe...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7A0A"
        },
        [80090418] = {
          ContentES = "Jajaja ¡Posiblemente les arruine la cabeza y tengan efectos secundarios raros!",
          DialogueId = 80090418,
          DisableMouth = 1,
          GUID = "C87F7A34",
          IsBlack = 1,
          NextDialogue = 80090419,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hehehe, maybe it'll mess up their brains and cause some weird side effects!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7A34"
        },
        [80090419] = {
          ContentES = "¡Qué inoportuno, mejor cállate!",
          DialogueId = 80090419,
          DisableMouth = 1,
          GUID = "C87F7A5E",
          IsBlack = 1,
          NextOptions = {
            [1] = 80090420
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Knock it off! You ghoul!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7A5E"
        },
        [80090420] = {
          ContentES = "¿Quién...?",
          DialogueId = 80090420,
          GUID = "C87F7A88",
          NextDialogue = 80090421,
          Subtitle = "...Who's there?"
        },
        [80090421] = {
          ContentES = "Ves varios tentáculos que se extienden desde Tabethe, balanceándose suavemente frente a ti.",
          DialogueId = 80090421,
          DisableMouth = 1,
          GUID = "C87F7AB2",
          NextDialogue = 80090422,
          Subtitle = "You see several tentacles extending from Tabethe gently swaying in front of you."
        },
        [80090422] = {
          ContentES = "¿Lo escucharon?… ¡{nickname} nos está hablando!",
          DialogueId = 80090422,
          DisableMouth = 1,
          GUID = "C87F7ADC",
          NextDialogue = 80090423,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Did you hear that...?  is talking to us.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7ADC"
        },
        [80090423] = {
          ContentES = "Que yo sepa, solo Tabethe puede escucharnos, ¿verdad?",
          DialogueId = 80090423,
          DisableMouth = 1,
          GUID = "C87F7B06",
          NextDialogue = 80090424,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "To my knowledge, only Tabethe can hear us speak.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7B06"
        },
        [80090424] = {
          ContentES = "¡Oh no… esto está mal, muy mal! ¡Lo sabía! Cada vez que 5 dice algo malo, ¡se cumple! ¡La próxima vez, por favor, cállate! ¡Te lo suplico!",
          DialogueId = 80090424,
          DisableMouth = 1,
          GUID = "C87F7B30",
          NextOptions = {
            [1] = 80090425
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Oh no... This is bad, really bad! I knew it — every time 5 says something bad, it always happens for real! Could you zip it next time? I'm begging you!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7B30"
        },
        [80090425] = {
          ContentES = "¿Los tentáculos… están hablando…?",
          DialogueId = 80090425,
          GUID = "C87F7B5A",
          NextDialogue = 80090426,
          Subtitle = "Are those tentacles talking...?"
        },
        [80090426] = {
          ContentES = "Eh… hola. Sí, somos los tentáculos de Tabethe. ¡Nunca pensamos que podríamos estar en una situación así! La vida realmente está llena de sorpresas, ¿eh? Jaja…",
          DialogueId = 80090426,
          DisableMouth = 1,
          GUID = "C87F7B84",
          NextDialogue = 80090427,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Um... hello? Yes, we're Tabethe's tentacles. Never thought we'd be having a conversation like this! Life's full of surprises, huh? Haha...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7B84"
        },
        [80090427] = {
          ContentES = "Parece que la culpable de todo esto es la bebida… Sentimos mucho haberte dado algo tan raro, pero ni Tabethe ni nosotros lo hicimos a propósito, buaa…",
          DialogueId = 80090427,
          DisableMouth = 1,
          GUID = "C87F7BAE",
          NextOptions = {
            [1] = 80090428,
            [2] = 80090429
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2",
          Subtitle = "Um... it might be that drink that caused this situation... We're so sorry... didn't mean to make you chug down something weird...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7BAE"
        },
        [80090428] = {
          ContentES = "¿Tabethe está bien?",
          DialogueId = 80090428,
          GUID = "C87F7BD8",
          NextDialogue = 80090430,
          Subtitle = "Is Tabethe okay?"
        },
        [80090429] = {
          ContentES = "¿Estoy bien...?",
          DialogueId = 80090429,
          GUID = "C87F7C02",
          NextDialogue = 80090430,
          Subtitle = "Am I okay?"
        },
        [80090430] = {
          ContentES = "Según mi observación, su reacción actual se debe únicamente a unos... “ingredientes especiales”. ¡Una buena dormida lo arreglará!",
          DialogueId = 80090430,
          DisableMouth = 1,
          GUID = "C87F7C2C",
          NextDialogue = 80090431,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "Based on my observations, you're both just reacting to some... special ingredients. A good sleep should fix it!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7C2C"
        },
        [80090431] = {
          ContentES = "¡Que quede claro que fue bajo mi liderazgo que ideamos esta bebida para el encuentro sin precedentes de Tabethe contigo!",
          DialogueId = 80090431,
          DisableMouth = 1,
          GUID = "C87F7C56",
          NextDialogue = 80090432,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "Ahem, just so you know — it was under my leadership that we concocted this beverage for Tabethe's unprecedented get-together with you!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7C56"
        },
        [80090432] = {
          ContentES = "¿Ah? ¿No será más bien que Tabethe no tiene ni idea de cómo preparar bebidas y esto es culpa de esas bonitas setas que cortó en rodajas y echó?",
          DialogueId = 80090432,
          DisableMouth = 1,
          GUID = "C87F7C80",
          NextDialogue = 80090433,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Hmm? I thought it was because Tabethe knew nothing about making drinks, so she just threw in some pretty mushroom slices, which led to this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7C80"
        },
        [80090433] = {
          ContentES = "Jejeje, si sigues con aires de superioridad, 3, ¡tú también acabarás en la próxima bebida! Jejejeje",
          DialogueId = 80090433,
          DisableMouth = 1,
          GUID = "C87F7CAA",
          NextDialogue = 80090434,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu5",
          Subtitle = "Hehe, keep acting all smug, 3, and you might find yourself part of the next drink, hehehe.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7CAA"
        },
        [80090434] = {
          ContentES = "¡Uuuh, qué horror!",
          DialogueId = 80090434,
          DisableMouth = 1,
          GUID = "C87F7CD4",
          NextDialogue = 80090435,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2",
          Subtitle = "Ah, that sounds horrible! Waah!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7CD4"
        },
        [80090435] = {
          ContentES = "Dejen de alborotar… ¿acaso no se cansan? No ven que están asustando a {nickname}...",
          DialogueId = 80090435,
          DisableMouth = 1,
          GUID = "C87F7CFE",
          NextOptions = {
            [1] = 80090436
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu4",
          Subtitle = "Please, you guys are too loud... Aren't you tired? And don't scare ...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7CFE"
        },
        [80090436] = {
          ContentES = "Ya entiendo. Todo esto es un sueño, un extraño sueño.",
          DialogueId = 80090436,
          GUID = "C87F7D28",
          NextDialogue = 80090437,
          Subtitle = "Got it — this is a dream. A really weird one."
        },
        [80090437] = {
          ContentES = "Supongo que puedes tomarlo como un sueño. Aunque no puedo decir cuánto tiempo durarán los efectos de la bebida… En realidad, hay bastante que queremos decirte. Quizá esta sea la oportunidad… ¡1, tú primero!",
          DialogueId = 80090437,
          DisableMouth = 1,
          GUID = "C87F7D52",
          NextDialogue = 80090438,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "That's one way to see it. Though no one knows how long the drink's effects will last... Actually, there's quite a lot we'd like to talk to you about! Maybe this is the chance... 1, you go first!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7D52"
        },
        [80090438] = {
          ContentES = "Mi conciencia nació en el océano, justo después del naufragio. Acompañé a Tabethe durante aquellos momentos oscuros en el mar. Ella lo superó hablándome.",
          DialogueId = 80090438,
          DisableMouth = 1,
          GUID = "C87F7D7C",
          NextDialogue = 80090439,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1",
          Subtitle = "...My sentience came into being on the ocean, right after the shipwreck. I kept Tabethe company during those dark times in the sea. She got through it by talking to me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7D7C"
        },
        [80090439] = {
          ContentES = "Yo… yo… yo desperté en el orfanato. Tabethe acababa de llegar y los adultos no la trataban bien. Tenía miedo, pero también quería parecer fuerte frente a cualquiera. Por las noches, ella se aferraba a mí, temblando...",
          DialogueId = 80090439,
          DisableMouth = 1,
          GUID = "C87F7DA6",
          NextDialogue = 80090440,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2",
          Subtitle = "I... I woke up when Tabethe had just been taken in by the orphanage. The staff there were mean to her; she was scared, but wouldn't show weakness in front of anyone. At night, she'd cling on to me, shivering...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7DA6"
        },
        [80090440] = {
          ContentES = "Yo me uní a este ilustre grupo en la cocina del orfanato. Gracias a mi oportuna dirección, logramos esquivar a los guardias que patrullaban y obtuvimos medio pedazo de pan como botín de nuestra hazaña.",
          DialogueId = 80090440,
          DisableMouth = 1,
          GUID = "C87F7DD0",
          NextDialogue = 80090441,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "I myself joined this esteemed group in the orphanage's kitchen. In a dire moment, it was under my command that we managed to evade the patrolling guards and secure half a loaf of bread!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7DD0"
        },
        [80090441] = {
          ContentES = "Y en cuanto a mi manera de hablar, es una perfecta imitación del director del orfanato.",
          DialogueId = 80090441,
          DisableMouth = 1,
          GUID = "C87F7DFA",
          NextDialogue = 80090442,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "And as for my manner of speaking, it's a perfect impersonation of the head of the orphanage.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7DFA"
        },
        [80090442] = {
          ContentES = "*Bosteza* Desperté la noche en que escapamos del orfanato. La sensación de alivio era tan intensa… que en cuanto estuvimos a salvo, me quedé dormido sobre el césped junto a ella…",
          DialogueId = 80090442,
          DisableMouth = 1,
          GUID = "C87F7E24",
          NextDialogue = 80090443,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu4",
          Subtitle = "Yawn... I awoke the night we escaped the orphanage. The sense of relief was so heavy... that once we were safe, I fell asleep right away on the grass with her...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7E24"
        },
        [80090443] = {
          ContentES = "Jejeje, Ahora me toca a mí. ¡Soy la mejor compañera de fechorías de Tabethe! ¡La emoción de todos esos atracos es simplemente increíble! ¡Wuju!",
          DialogueId = 80090443,
          DisableMouth = 1,
          GUID = "C87F7E4E",
          NextDialogue = 80090444,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu5",
          Subtitle = "And then there's me, hehehe! I'm Tabethe's best partner in crime! The thrill of all sorts of heists is just the best! Woo-hoo!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7E4E"
        },
        [80090444] = {
          ContentES = "¡Cálmate! Perdona, este chico es un poco impredecible. Cof cof, soy el más joven y mi conciencia nació hace poco.",
          DialogueId = 80090444,
          DisableMouth = 1,
          GUID = "C87F7E78",
          NextDialogue = 80090445,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Get ahold of yourself! Sorry, this kid is a bit of a wild card. Ahem, I'm the youngest, and only recently became sentient.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7E78"
        },
        [80090445] = {
          ContentES = "En realidad, desperté una vez hace mucho tiempo. Pero la niña que vendía pescado se separó de Tabethe, y ella se puso muy triste. No lo decía, pero le afectó mucho y terminé deprimido junto con ella... volví a caer en el sueño y me sumí en esos recuerdos.",
          DialogueId = 80090445,
          DisableMouth = 1,
          GUID = "C87F7EA2",
          NextDialogue = 80090446,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Actually, I woke up once a long time ago. But then that little fish vendor girl got separated from Tabethe, which made her very sad. She didn't talk about it, but it hit her really hard and even affected me — I fell back into slumber, immersed in those memories.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7EA2"
        },
        [80090446] = {
          ContentES = "Hasta que conoció a otra persona que también la valora de verdad... Sí, desperté por ti.",
          DialogueId = 80090446,
          DisableMouth = 1,
          GUID = "C87F7ECC",
          NextDialogue = 80090447,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Until she met another person who also truly cherishes her — yes, it was because of you that I woke up again.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7ECC"
        },
        [80090447] = {
          ContentES = "Gracias por cuidar de Tabethe. Tu bondad me despertó de mi sueño. Y fue bajo mi sugerencia que ella decidió preparar esa bebida como muestra de agradecimiento.",
          DialogueId = 80090447,
          DisableMouth = 1,
          GUID = "C87F7EF6",
          NextDialogue = 80090448,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Thank you for taking care of Tabethe. Your kindness woke me from my dream. And it was on my suggestion that she decided to make this drink as a thank you.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7EF6"
        },
        [80090448] = {
          ContentES = "¡Pero no esperaba que se le fuera tanto de las manos! No sabe nada de preparar bebidas y solo echó lo que le pareció bonito... ¡Y ustedes dos, 3 y 5! ¡Ustedes la animaron!",
          DialogueId = 80090448,
          DisableMouth = 1,
          GUID = "C87F7F20",
          NextDialogue = 80090449,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "But I didn't expect her to go this overboard! She knows nothing about mixing drinks and just tossed in whatever looked good — and you two, 3 and 5! You two egged her on!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7F20"
        },
        [80090449] = {
          ContentES = "Lo sentimos... de verdad...",
          DialogueId = 80090449,
          DisableMouth = 1,
          GUID = "C87F7F4A",
          NextOptions = {
            [1] = 80090450
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "We're so sorry...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7F4A"
        },
        [80090450] = {
          ContentES = "Jaja, no pasa nada.",
          DialogueId = 80090450,
          GUID = "C87F7F74",
          NextDialogue = 80090451,
          Subtitle = "Haha, it's okay."
        },
        [80090451] = {
          ContentES = "...",
          DialogueId = 80090451,
          DisableMouth = 1,
          GUID = "C87F7F9E",
          NextDialogue = 80090452,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7F9E"
        },
        [80090452] = {
          ContentES = "Tabethe se está despertando. ¿Cómo te sientes?",
          DialogueId = 80090452,
          DisableMouth = 1,
          GUID = "C87F7FC8",
          NextDialogue = 80090453,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1",
          Subtitle = "Tabethe's waking up. How do you feel?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7FC8"
        },
        [80090453] = {
          ContentES = "¡Tan rápido! ¡Ni siquiera terminé mi discurso!",
          DialogueId = 80090453,
          DisableMouth = 1,
          GUID = "C87F7FF2",
          NextOptions = {
            [1] = 80090454,
            [2] = 80090455
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "Ah, already?! I haven't finished my speech...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7FF2"
        },
        [80090454] = {
          ContentES = "Qué sueño tan extraño… Será mejor despertar pronto...",
          DialogueId = 80090454,
          GUID = "C87F801C",
          NextDialogue = 80090456,
          Subtitle = "What a weird dream. Better wake up ASAP..."
        },
        [80090455] = {
          ContentES = "Son adorables. Espero que esto pueda pasar más a menudo.",
          DialogueId = 80090455,
          GUID = "C87F8046",
          NextDialogue = 80090456,
          Subtitle = "They're adorable. I hope this could happen more often."
        },
        [80090456] = {
          ContentES = "Ese sabor extraño te golpea de nuevo. Aunque ya lo habías experimentado antes, aún inunda tus sentidos de manera abrumadora.",
          DialogueId = 80090456,
          GUID = "C87F8070",
          IsBlack = 1,
          NextDialogue = 80090457,
          Subtitle = "That odd taste hits you again. Even though you've experienced it before, it still overwhelmingly floods your senses."
        },
        [80090457] = {
          ContentES = "Antes de desmayarte de nuevo, escuchas varias voces discutiendo: “Que los dioses bendigan a los de buen corazón”, “Lo que no te mata te hace más fuerte”, “Yo tomaré la delantera con la cabeza.”, junto con muchas voces que murmuran: “Gracias”.",
          DialogueId = 80090457,
          GUID = "C87F809A",
          IsBlack = 1,
          Subtitle = "Before blacking out again, you seem to hear a cacophony of voices: \"Gods bless the kind-hearted,\" \"What doesn't kill you makes you stronger,\" \"I'll take the lead with the head,\" along with many voices murmuring, \"Thank you.\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F809A"
        },
        [80090458] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentES = "¡¿Estás bien?! Oh no... no fue la bebida, ¿verdad...?",
          DialogueId = 80090458,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F80C4",
          NextDialogue = 80090459,
          SpeakNpcId = 92301,
          Subtitle = "Aaaare you alright?! Oh no... it wasn't the drink, was it...?",
          TalkActionId = {
            [1] = "92301:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F80C4"
        },
        [80090459] = {
          ContentES = "¡Ey, yo también bebí lo mismo! Estaba tan bueno que me mareé por un momento. ¡Pero ya no pasa nada! ¡Oye, despierta! Ni se te ocurra intentar engañarme fingiendo que es una intoxicación alimentaria...!",
          DialogueId = 80090459,
          GUID = "C87F80EE",
          NextOptions = {
            [1] = 80090460
          },
          SpeakNpcId = 92301,
          Subtitle = "...I drank the same thing! It was so good that it knocked me out for a moment, but I'm perfectly fine now! Hey, wake up! Don't even think about trying to scam me by pretending it's food poisoning...!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F80EE"
        },
        [80090460] = {
          ContentES = "Deja de gritar… Estoy bien… solo escuché a unos tentáculos hablando…",
          DialogueId = 80090460,
          GUID = "C87F8118",
          NextDialogue = 80090461,
          Subtitle = "Will you keep it down...? I'm fine... just heard some tentacles talking, that's all..."
        },
        [80090461] = {
          ContentES = "...",
          DialogueId = 80090461,
          FacialId = {
            [1] = "92301:Shock02"
          },
          GUID = "C87F8142",
          NextDialogue = 80090462,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F8142"
        },
        [80090462] = {
          ContentES = "¡DOCTOR! ¡DOCTOOOOOOR!",
          DialogueId = 80090462,
          GUID = "C87F816C",
          NextDialogue = 80090463,
          SpeakNpcId = 92301,
          Subtitle = "Doc! Help!!!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F816C"
        },
        [80090463] = {
          ContentES = "Aún te sientes mal, y sientes ver los tentáculos de Tabethe retorciéndose alegremente, como si te estuvieran saludando.",
          DialogueId = 80090463,
          GUID = "C87F8196",
          Subtitle = "You're still feeling awful, but you seem to see Tabethe's tentacles cheerfully quivering, as if they are nodding at you."
        },
        [80100100] = {
          ContentES = "¿Es una cita privada?",
          DialogueId = 80100100,
          GUID = "C885AEA8",
          Subtitle = "Are we going on a private date?",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEA8"
        },
        [80100101] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentES = "Por fin te decidiste a invitarme. Llegué hace mucho, y me empezaba a preguntar… ¿cuánto tiempo ibas a hacer esperar a esta pobre perfumista errante?",
          DialogueId = 80100101,
          FacialId = {
            [1] = "92101:Satisfy01"
          },
          GUID = "C885AED2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100102,
          SpeakNpcId = 92101,
          Subtitle = "Finally received your invitation. Much time has passed since I arrived at this place, and I'd been wondering how long you were going to keep this poor wandering perfumer waiting.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AED2"
        },
        [80100102] = {
          ContentES = "Qué insensible eres… debes saber que incluso el corazón más apasionado, no puede.... arder para siempre. La indiferencia puede apagar la llama de la pasión.",
          DialogueId = 80100102,
          GUID = "C885AEFC",
          NextOptions = {
            [1] = 801001021,
            [2] = 801001022
          },
          SpeakNpcId = 92101,
          Subtitle = "You should know even the most passionate heart cannot burn forever. Indifference will extinguish those flames, leaving it hard and cold.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEFC"
        },
        [80100103] = {
          ContentES = "Ya te lo dije bien claro: me dejaste esperando. Qué injusto es el destino, que me da un amor que me comienza a ignorar...",
          DialogueId = 80100103,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF26",
          NextOptions = {
            [1] = 801001041
          },
          SpeakNpcId = 92101,
          Subtitle = "You left me out in the cold. Fate is so cruel for giving me a romance that begins with the coldest of shoulders.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF26"
        },
        [80100104] = {
          ContentES = "¡Vaya! Nunca pensé que las palabras de mi primer amor pudieran sentirse tan frías. ¿Acaso no te das cuenta de que nuestra historia de amor acaba de comenzar?",
          DialogueId = 80100104,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF50",
          NextOptions = {
            [1] = 801001041
          },
          SpeakNpcId = 92101,
          Subtitle = "*sigh* Never thought your words could be even colder than your actions. Are you truly blind to the romance that is about to blossom?",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF50"
        },
        [80100105] = {
          ContentES = "No te hagas {性别:el tonto|la tonta}… Obviamente hablo de ti y de mí. ¿De quiénes más son los ojos que se miran profundamente en este mismo momento?",
          DialogueId = 80100105,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF7A",
          NextDialogue = 80100106,
          SpeakNpcId = 92101,
          Subtitle = "Between you and me, of course. Who else's eyes are looking deep into each other at this very moment?",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF7A"
        },
        [80100106] = {
          ContentES = "No te sorprendas tanto. Para ti quizás solo sea una huésped en tu casa, pero este encuentro encierra un significado oculto… y más aún cuando esta historia de amor nos envuelve a {性别:los|las} dos.",
          DialogueId = 80100106,
          GUID = "C885AFA4",
          NextDialogue = 80100107,
          SpeakNpcId = 92101,
          Subtitle = "Don't be so surprised, hehe. You might treat me as a temporary guest staying over at your place. But for me, every encounter is a story waiting to unfold, especially when it's you.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFA4"
        },
        [80100107] = {
          ContentES = "No apartes la mirada. Tus ojos color vino reflejan las posibilidades de nuestro futuro. En esta neblina embriagadora, compartiremos un dúo de amor… o un paseo por mi jardín aromático.",
          DialogueId = 80100107,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885AFCE",
          NextDialogue = 80100108,
          SpeakNpcId = 92101,
          Subtitle = "Don't look away. Your wine-red eyes reflect possibilities of our future. Within this intoxicating haze, we shall share a duet of love or a walk in my aroma garden.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFCE"
        },
        [80100108] = {
          ContentES = "Tarde o temprano sucumbirás a mi amor, tu cuerpo se impregnará de mi aroma. Cuando llegue ese momento, el destino revelará si en verdad eres la “Persona destinada”.",
          DialogueId = 80100108,
          GUID = "C885AFF8",
          NextDialogue = 80100109,
          SpeakNpcId = 92101,
          Subtitle = "You will eventually sway to my passions, and every inch of you shall bear my scent. When that moment comes, fate shall reveal if you are indeed the destined one.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFF8"
        },
        [80100109] = {
          ContentES = "Y lo más hermoso es que no tienes que hacer nada. Basta con que te dejes llevar, y yo te haré probar el amor más puro e intenso.",
          DialogueId = 80100109,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B022",
          NextOptions = {
            [1] = 801001091,
            [2] = 801001092
          },
          SpeakNpcId = 92101,
          Subtitle = "You don't even need to make your own move for all this to happen. Just submit and follow my lead, and I shall let you experience a love of utmost purity and sweetness.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B022"
        },
        [80100110] = {
          ContentES = "Jeje, entiendo tus preocupaciones… pero estoy segura de que en el juego del amor no existen reglas escritas, ninguna que dicte el momento exacto en el que dos almas puedan amarse.",
          DialogueId = 80100110,
          GUID = "C885B04C",
          NextDialogue = 80100112,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, I understand your concerns. But you should know that no law or tradition dictates the number of days one must wait for love to sprout.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B04C"
        },
        [80100111] = {
          ContentES = "Ejem... Qué adivinanza tan linda y encantadora. Quizás deba reformular mis palabras: estoy a punto de ascender al escenario llamado Amor, y estoy buscando a {性别:un compañero adecuado|una compañera adecuada}.",
          DialogueId = 80100111,
          FacialId = {
            [1] = "92101:Shock02"
          },
          GUID = "C885B076",
          NextDialogue = 80100112,
          SpeakNpcId = 92101,
          Subtitle = "Ahem... What a cute and lovely guess. Perhaps I shall rephrase my words: I'm about to ascend the stage called Love, and I'm seeking a suitable partner.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B076"
        },
        [80100112] = {
          ContentES = "Claro que, si decides rechazarme, no hay problema… puedes recordar todo lo que pasó hoy como un sueño perfumado que preparé cuidadosamente para ti.",
          DialogueId = 80100112,
          GUID = "C885B0A0",
          NextDialogue = 80100113,
          SpeakNpcId = 92101,
          Subtitle = "Of course, if you wish to refuse, then just treat today's encounter as a scented dream that I have carefully concocted for you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0A0"
        },
        [80100113] = {
          ContentES = "Pero quiero que sepas esto: yo, Rebecca, la perfumista errante que ha recorrido incontables tierras, siempre he estado buscando a la persona destinada a ser mi amor eterno.",
          DialogueId = 80100113,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B0CA",
          NextDialogue = 80100114,
          SpeakNpcId = 92101,
          Subtitle = "But I want you to know that I, Rebecca the wandering perfumer, am always seeking my destined life partner.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0CA"
        },
        [80100114] = {
          ContentES = "Cuando por fin encuentre a la “Persona destinada”, compartiré con esa persona incontables momentos… y jamás volveremos a separarnos.",
          DialogueId = 80100114,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885B0F4",
          NextDialogue = 80100115,
          SpeakNpcId = 92101,
          Subtitle = "When I finally find the one, I shall share countless moments and sweet words with them, and we will never be apart.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0F4"
        },
        [80100115] = {
          ContentES = "Pero… como ves, estoy envuelta en una cálida capa de veneno dulce. Aunque esta envoltura me protege, también me impide sentir la cercanía de un abrazo o la ternura de un beso.",
          DialogueId = 80100115,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885B11E",
          NextDialogue = 80100116,
          SpeakNpcId = 92101,
          Subtitle = "I know it is difficult, for I am enshrouded in a warm layer of sweet venom. Though the coating protects me, it renders me incapable of receiving intimate hugs or loving kisses.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B11E"
        },
        [80100116] = {
          ContentES = "Pero nunca dejo de buscar. Estoy convencida de que si este mundo fue capaz de engendrar a una criatura extraña como yo, entonces también debió engendrar a alguien que pueda soportar mi veneno y aceptarme tal cual.",
          DialogueId = 80100116,
          GUID = "C885B148",
          NextDialogue = 80100117,
          SpeakNpcId = 92101,
          Subtitle = "But I never give up. I strongly believe that if this land gave birth to a freak like me, it must have given birth to another who can withstand my venom and accept me for who I am.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B148"
        },
        [80100117] = {
          ContentES = "Y tú, mi amor de ojos vino tinto, me has mostrado esa posibilidad.",
          DialogueId = 80100117,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B172",
          NextDialogue = 80100118,
          SpeakNpcId = 92101,
          Subtitle = "And you, my darling with wine-red eyes, you showed me the potential in this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B172"
        },
        [80100118] = {
          ContentES = "Así que consideremos este momento como nuestra primera cita y la confesión de nuestro amor.",
          DialogueId = 80100118,
          GUID = "C885B19C",
          NextDialogue = 80100119,
          SpeakNpcId = 92101,
          Subtitle = "So, let's consider this very moment as our very first date, a sweet little gift for your sincerity.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B19C"
        },
        [80100119] = {
          ContentES = "Puedes rechazarme, pero entonces mi veneno sellará tus labios para que esta confesión de amor quede sellado con veneno por siempre. ¿Qué prefieres?",
          DialogueId = 80100119,
          GUID = "C885B1C6",
          SpeakNpcId = 92101,
          Subtitle = "You can refuse, but then my venom will seal your tongue to safeguard my secret forever. Which one do you prefer?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B1C6"
        },
        [80100201] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentES = "Otra vez estamos {性别:solos|solas}. Poca gente se queda después de haber descubierto esta parte de mí sin salir corriendo gritando.",
          DialogueId = 80100201,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885BF3A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801002011
          },
          SpeakNpcId = 92101,
          Subtitle = "Another occasion of us alone. It's rare that someone hasn't fled screaming in terror after discovering that side of me.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF3A"
        },
        [80100202] = {
          ContentES = "Seguramente ya lo has notado.",
          DialogueId = 80100202,
          GUID = "C885BF64",
          NextDialogue = 80100203,
          SpeakNpcId = 92101,
          Subtitle = "You must have sensed it already.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF64"
        },
        [80100203] = {
          ContentES = "Extiende tus brazos y míralos. Qué limpios están… aunque tengan callos y cicatrices, siguen siendo impecables. Cuando estás {性别:cansado|cansada}, tu brazo rezuma sudor salado.",
          DialogueId = 80100203,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885BF8E",
          NextDialogue = 80100204,
          SpeakNpcId = 92101,
          Subtitle = "Stretch out your arms and take a look. Aww, such clean and lovely arms. Though callused and scarred, they remain pure and immaculate. And when tired, they only weep with salty sweat—",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF8E"
        },
        [80100204] = {
          ContentES = "En cambio de los míos, solo fluye un veneno mortal.",
          DialogueId = 80100204,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885BFB8",
          NextDialogue = 80100205,
          SpeakNpcId = 92101,
          Subtitle = "They differ from mine, which solely exude and bleed deadly venom.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFB8"
        },
        [80100205] = {
          ContentES = "El veneno incontrolable es como un viejo amigo mío. Dependo de él para ahuyentar a los Filthoids que se lanzan sobre mí en los senderos del bosque o para enviar a los soldados perseguidos a un sueño eterno.",
          DialogueId = 80100205,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885BFE2",
          NextDialogue = 80100206,
          SpeakNpcId = 92101,
          Subtitle = "The uncontrollable venom is like a wild old friend of mine. I rely on it to ward off Filthoids pouncing on me in forest trails or to send pursuing soldiers to an eternal sleep.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFE2"
        },
        [80100206] = {
          ContentES = "Sin embargo, a veces se excede y termina alejando todo aquello que deseo tener cerca. Si me acerco a un manantial, basta con que me lave el rostro para que los peces que nadan cerca terminen muriendo.",
          DialogueId = 80100206,
          GUID = "C885C00C",
          NextDialogue = 80100207,
          SpeakNpcId = 92101,
          Subtitle = "But the venom is the vile and vicious repellant of anything and anyone that I wish to get closer to. Merely washing my face in a pond paralyses and suffocates any fish that tries to give me a friendly peck.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C00C"
        },
        [80100207] = {
          ContentES = "En un momento de mi vida, llegué a odiarlo. Si no fuera por este veneno, sería como cualquier otra chica de mi edad: iría al mercado a escoger vestidos y miraría en secreto al chico que me gusta desde la esquina.",
          DialogueId = 80100207,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C036",
          NextOptions = {
            [1] = 801002071,
            [2] = 801002072
          },
          SpeakNpcId = 92101,
          Subtitle = "I once detested it. If not for my venom, I would be like many other girls of my age. I would be picking out my favorite clothes at the market, or stealing a glance at my crush.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C036"
        },
        [80100208] = {
          ContentES = "No se puede llamar eso sueños, solo pensamientos pasajeros, que hoy me hacen sonreír.",
          DialogueId = 80100208,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C060",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          Subtitle = "They're not dreams. Just occasional notions that never linger. I laugh at myself for having had those thoughts.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C060"
        },
        [80100209] = {
          ContentES = "No, diría que ya me acostumbré. Encontré una forma armoniosa de convivir con él.",
          DialogueId = 80100209,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C08A",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          Subtitle = "Not exactly. It's more like I've subdued the venom. I found a more fitting way to coexist with it.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C08A"
        },
        [80100210] = {
          ContentES = "Ya no tengo que espiar, ni tampoco poner a las personas a prueba con molestas conversaciones. Con un dulce abrazo, por más breve que sea, sé si esa persona puede quedarse conmigo por siempre.",
          DialogueId = 80100210,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C0B4",
          NextDialogue = 80100211,
          SpeakNpcId = 92101,
          Subtitle = "Now, I no longer peep at someone I like, nor waste time on hours of useless talk to test their sincerity. A moment of sweet embrace is all I need to determine if this one is suited for a long-term commitment with me.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0B4"
        },
        [80100211] = {
          ContentES = "El veneno es mi prueba más valiosa. Si algún día aparece alguien que sea capaz de soportar mis abrazos, sabré que esa persona es el amor de mi vida.",
          DialogueId = 80100211,
          GUID = "C885C0DE",
          NextDialogue = 80100212,
          SpeakNpcId = 92101,
          Subtitle = "The venom serves as my most valuable touchstone. If I meet someone capable of withstanding my embrace, I would immediately know that I've met the destined one.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0DE"
        },
        [80100212] = {
          ContentES = "Por desgracia, aún no he encontrado a alguien así, y quizá jamás lo haga. Sin embargo, ¿no te parece mucho más romántico que las vacías charlas de amor entre las personas del mundo?",
          DialogueId = 80100212,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C108",
          NextDialogue = 80100213,
          SpeakNpcId = 92101,
          Subtitle = "It's just that this person has yet to appear — perhaps they never will. But don't you find this far more romantic than the inane love talks between worldly people?",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C108"
        },
        [80100213] = {
          ContentES = "Al menos para mí, esto es un regalo. Todos los que me temen, me muestran cariño o buscan complacerme deben pasar la misma prueba.",
          DialogueId = 80100213,
          GUID = "C885C132",
          NextDialogue = 80100214,
          SpeakNpcId = 92101,
          Subtitle = "At least for me, it's a gift. Those who fear me, intimidate me, care for me, or obey me are all subject to this fair and equal trial.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C132"
        },
        [80100214] = {
          ContentES = "Así que, vago por el mundo y ya no envidio a los demás, porque mi veneno único me ayudará a encontrar el amor especial que será completamente mío.",
          DialogueId = 80100214,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C15C",
          NextDialogue = 80100215,
          SpeakNpcId = 92101,
          Subtitle = "Although I remain the same as I was and my wanderings continue, I no longer envy others, because my unique venom will help me find the special love that will be wholly mine.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C15C"
        },
        [80100215] = {
          ContentES = "Así que ahora, abro mis brazos y te pregunto… ¿quieres abrazarme?",
          DialogueId = 80100215,
          GUID = "C885C186",
          NextOptions = {
            [1] = 801002151,
            [2] = 801002152
          },
          SpeakNpcId = 92101,
          Subtitle = "Now, I intend to open my arms and ask you one question: Will you embrace me?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C186"
        },
        [80100216] = {
          ContentES = "Jeje, no tengas miedo. Eres la primera persona que me escucha hablar tanto de mi pasado. Aunque solo exista una oportunidad, ¿y si resulta que eres la persona que tanto he estado buscando?",
          DialogueId = 80100216,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885C1B0",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, don't be scared. You're the first to hear me divulge this much about my past. You get only one chance, but perhaps you're indeed the one I've been searching for.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1B0"
        },
        [80100217] = {
          ContentES = "¿Aprovecharías la oportunidad para usar tu espada y cortarme la garganta? No necesitas estar tan a la defensiva. Puedo sentir que, en realidad, somos muy {性别:parecidos|parecidas}. {性别:Ambos|Ambas} cargamos un destino diferente al de los demás.",
          DialogueId = 80100217,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885C1DA",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          Subtitle = "And then you'll pierce my throat with that sword in your hand, right? Hehe, don't be so on guard. I can feel it. We're kindred souls, you and me, fated to lead lives not shared by any other.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1DA"
        },
        [80100218] = {
          ContentES = "*Suspira* Qué curioso… No pensé que la cita que acabamos de tener terminara con tu rechazo. Qué pena.",
          DialogueId = 80100218,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C204",
          NextDialogue = 80100219,
          SpeakNpcId = 92101,
          Subtitle = "*sigh* I didn't expect that this date, iniciated by you, would actually end with your rejection of my advance. What a pity.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C204"
        },
        [80100219] = {
          ContentES = "De todos modos, aún nos queda mucho tiempo. Ten cuidado… quizás un día aparezca detrás de ti y te abrace con fuerza.",
          DialogueId = 80100219,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885C22E",
          NextOptions = {
            [1] = 801002191
          },
          SpeakNpcId = 92101,
          Subtitle = "But we still have time, and you'd better be careful. A day might come when I decide to appear right behind you and hold you tight.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C22E"
        },
        [80100220] = {
          ContentES = "¡Qué adorable, pareces un gatito enseñando los colmillos. Será mejor que mantenga cierta distancia. Hasta pronto. Espero con ilusión nuestra próxima cita.",
          DialogueId = 80100220,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885C258",
          SpeakNpcId = 92101,
          Subtitle = "Oh, how cute, just like a little kitten baring its tiny fangs. Perhaps I should keep my distance, then. Goodbye, I look forward to our next rendezvous.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C258"
        },
        [80100221] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.396057,51.444664,130.0,false,Manual,2.8",
          ContentES = "Hola, aquí estamos de nuevo, después de solo unos segundos.",
          DialogueId = 80100221,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C282",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100222,
          SpeakNpcId = 92101,
          Subtitle = "Only a few seconds have passed, yet we meet again.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C282"
        },
        [80100222] = {
          ContentES = "Veo que en realidad no estás tan a la defensiva, qué alegría. No te preocupes, no planeo abrazarte todavía… solo quiero advertirte de algo:",
          DialogueId = 80100222,
          GUID = "C885C2AC",
          NextDialogue = 80100223,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, it seems you're not that wary of me, which is nice. Don't worry, I don't intend to embrace you right now, but I have a word of advice:",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2AC"
        },
        [80100223] = {
          ContentES = "Date la vuelta y mírame cuando oigas mi voz la próxima vez que nos encontremos, y no apartes la mirada, o podría ocurrir algo peligroso.",
          DialogueId = 80100223,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C2D6",
          NextDialogue = 80100224,
          SpeakNpcId = 92101,
          Subtitle = "Turn around and look at me once you hear my voice the next time we meet, and do not shift your gaze elsewhere, or something dangerous might happen.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2D6"
        },
        [80100224] = {
          ContentES = "Entonces, esta vez, es realmente una despedida. Arrivederci.",
          DialogueId = 80100224,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C300",
          SpeakNpcId = 92101,
          Subtitle = "Now, this is goodbye for sure. Arrivederci.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C300"
        },
        [80100301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentES = "Hoy he sido llamada por el “vínculo mudo del amor”, cada gota de mi veneno anhela verte.",
          DialogueId = 80100301,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885CFA2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100302,
          SpeakNpcId = 92101,
          Subtitle = "The \"Unspoken Bond of Love\" has called me here today. Every drop of my venom yearns to see you.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFA2"
        },
        [80100302] = {
          ContentES = "Veamos cuán {性别:sincronizados|sincronizadas} estamos ahora. ¿Crees poder adivinar lo que voy a decir a continuación?",
          DialogueId = 80100302,
          GUID = "C885CFCC",
          NextOptions = {
            [1] = 801003021,
            [2] = 801003022
          },
          SpeakNpcId = 92101,
          Subtitle = "Interested in seeing how in tune we are with each other? Guess what I'm about to say next.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFCC"
        },
        [80100303] = {
          ContentES = "La sinceridad es uno de tus muchos encantos.",
          DialogueId = 80100303,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885CFF6",
          NextDialogue = 80100304,
          SpeakNpcId = 92101,
          Subtitle = "And being so straightforward happens to be one of your charms.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFF6"
        },
        [80100304] = {
          ContentES = "Dejemos los rodeos y hablemos directamente de historias del pasado.",
          DialogueId = 80100304,
          GUID = "C885D020",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          Subtitle = "Then let's just skip the senseless prattle and focus directly on matters of the past.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D020"
        },
        [80100305] = {
          ContentES = "Así es. Estamos en sincronía, sabía que lo que iba a hacer era lo correcto.",
          DialogueId = 80100305,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885D04A",
          NextDialogue = 80100306,
          SpeakNpcId = 92101,
          Subtitle = "That's right. See, we are so in sync with each other. Seems I've made the right choice in deciding to do this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D04A"
        },
        [80100306] = {
          ContentES = "Estoy a punto de compartir un cierto secreto contigo, lo que también significa que se acerca el peligro.",
          DialogueId = 80100306,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D074",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          Subtitle = "I'm about to share a certain secret with you, which also means danger is approaching.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D074"
        },
        [80100307] = {
          ContentES = "Una vez conocí a alguien parecido a mí. Nació con la piel roja, como si fueran llamas, su personalidad era intensa e irascible con poca tolerancia hacia las impurezas.",
          DialogueId = 80100307,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D09E",
          NextDialogue = 80100308,
          SpeakNpcId = 92101,
          Subtitle = "I once met someone like me. She was born with fiery-red skin. Her temperament is the same, a blazing firebrand with little tolerance for the impure.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D09E"
        },
        [80100308] = {
          ContentES = "A diferencia de mí, que soy una monstruo despreciada y abandonada desde la infancia, ella carga con el legado y las esperanzas de su familia. Se convirtió en una guardiana, ningún prisionero escapa de su mirada.",
          DialogueId = 80100308,
          GUID = "C885D0C8",
          NextDialogue = 80100309,
          SpeakNpcId = 92101,
          Subtitle = "Unlike me, a monster despised and abandoned since childhood, she carries the legacy and hopes of her family, and ultimately becomes the righteous warden. No criminal she sets her sights on can ever escape her.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0C8"
        },
        [80100309] = {
          ContentES = "Sin embargo, su fuego es similar a mi veneno: ahuyenta a cualquiera que intente acercarse, ya sea con buenas o malas intenciones. Nadie se le acerca por miedo.",
          DialogueId = 80100309,
          GUID = "C885D0F2",
          NextOptions = {
            [1] = 801003091
          },
          SpeakNpcId = 92101,
          Subtitle = "However, like my venom, her flames tend to drive away or scare off anyone who tries to approach, be it with good or ill intent.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0F2"
        },
        [80100310] = {
          ContentES = "Sí. Un monstruo como yo no puede evitar dejar algunos cadáveres a su paso, ya sea por accidente o por voluntad. No debería sorprenderte que me persigan.",
          DialogueId = 80100310,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D11C",
          NextDialogue = 80100311,
          SpeakNpcId = 92101,
          Subtitle = "Yes. You know, a monster like me, who's born with lethal venom, can't help but leave a few bodies behind, whether by accident or willful intent. It shouldn't surprise you that I'm wanted.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D11C"
        },
        [80100311] = {
          ContentES = "Durante su larga y obstinada persecución, me di cuenta de algo: ella es como yo, ambas somos monstruos solitarios. Así que me aproveché de eso.",
          DialogueId = 80100311,
          GUID = "C885D146",
          NextDialogue = 80100312,
          SpeakNpcId = 92101,
          Subtitle = "During her long and persistent chase, I realised something — she's just like me, we're both lonely monsters. So, I took advantage of this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D146"
        },
        [80100312] = {
          ContentES = "Le confesé mi historia para confundirla, le hice ver que no era la única rara en Atlasia, y que su compasión y clemencia podrían hacerme retomar el camino correcto.",
          DialogueId = 80100312,
          GUID = "C885D170",
          NextDialogue = 80100313,
          SpeakNpcId = 92101,
          Subtitle = "I offered a seemingly sincere confession to confuse her, making her realise that she wasn't the only freak in this vast land and think that her pity and clemency would get me back on track.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D170"
        },
        [80100313] = {
          ContentES = "Luego, simplemente me escapé, justo después de que ella destruyera las pruebas de mis propios crímenes.",
          DialogueId = 80100313,
          GUID = "C885D19A",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100314,
          SpeakNpcId = 92101,
          Subtitle = "But then, I just ran away right after she destroyed the evidence of my crimes.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D19A"
        },
        [80100314] = {
          ContentES = "Ni te imaginas lo furiosa que se puso, y cómo apretaba los dientes de rabia. Juró que iba a atraparme. Por eso, si decides protegerme te haría cómplice y ambos acabaríamos en la cárcel.",
          DialogueId = 80100314,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D1C4",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801003141,
            [2] = 801003142
          },
          SpeakNpcId = 92101,
          Subtitle = "You can hardly imagine how furious she became, how her fires burnt as she gnashed her teeth and swore to throw me in prison. However, you should know that by granting me refuge, you will be seen as an accomplice.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1C4"
        },
        [80100315] = {
          ContentES = "Así que era eso... Ahora entiendo por qué siento esa aura de peligro que me embriaga cada vez que te veo.",
          DialogueId = 80100315,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885D1EE",
          NextDialogue = 80100316,
          SpeakNpcId = 92101,
          Subtitle = "Is that so? Now I understand why I always feel an intoxicating aura of danger whenever I see you.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1EE"
        },
        [80100316] = {
          ContentES = "Entonces, ya que te he advertido del peligro que enfrentarás, y aun así no te has opuesto… ¿significa eso que estamos acercándonos más?",
          DialogueId = 80100316,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D218",
          NextDialogue = 80100317,
          SpeakNpcId = 92101,
          Subtitle = "Since you showed no sign of displeasure or rejection after I told you about a potential threat, does that mean we're growing closer?",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D218"
        },
        [80100317] = {
          ContentES = "Confieso que dudé un poco en contarte mi peligroso pasado. Temía terminar vagando sola por el mundo otra vez.",
          DialogueId = 80100317,
          GUID = "C885D242",
          NextDialogue = 80100318,
          SpeakNpcId = 92101,
          Subtitle = "I confess that I did struggle a bit when I was deciding if I should tell you about my dangerous past. I was worried that I would end up wandering this world on my own again.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D242"
        },
        [80100318] = {
          ContentES = "Pero, no deseo que sufras más peligros… Con mi veneno sobra y basta.",
          DialogueId = 80100318,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D26C",
          NextDialogue = 80100319,
          SpeakNpcId = 92101,
          Subtitle = "But I cannot bear to see you menaced by other threats. My venom alone is dangerous enough as it is.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D26C"
        },
        [80100319] = {
          ContentES = "Sin embargo, me has convencido de que, mientras permanezca aquí, sin duda podré encontrar a la “Persona destinada”.",
          DialogueId = 80100319,
          GUID = "C885D296",
          NextOptions = {
            [1] = 801003191
          },
          SpeakNpcId = 92101,
          Subtitle = "Yet your answers have strengthened my belief that I shall find my destined one by staying here.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D296"
        },
        [80100320] = {
          ContentES = "Sí, alguien que he estado buscando desde Luca hasta Hyperborea. Pensaba que esa persona solo aparecía en mis sueños, como una figura brillante pero indistinta.",
          DialogueId = 80100320,
          GUID = "C885D2C0",
          NextDialogue = 80100321,
          SpeakNpcId = 92101,
          Subtitle = "Yes, someone that I've yet to find as I travelled from Luca to Hyperborea. I thought that person only appeared in my dreams as a shiny yet indistinct figure.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2C0"
        },
        [80100321] = {
          ContentES = "Su fuerte cuerpo podrá soportar cada gota de mi veneno… su corazón tan puro podrá recibir todo mi amor… y con sus manos tersas secará cada una de mis lágrimas...",
          DialogueId = 80100321,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885D2EA",
          NextDialogue = 80100322,
          SpeakNpcId = 92101,
          Subtitle = "{性别:His|Her} body is strong enough to withstand every drop of my venom... whose heart is pure enough to take in all my love... and whose hands are gentle enough to wipe away all my sorrows...",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2EA"
        },
        [80100322] = {
          ContentES = "Dime, ¿crees que esa persona pueda escucharme?",
          DialogueId = 80100322,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D314",
          NextOptions = {
            [1] = 801003221,
            [2] = 801003222
          },
          SpeakNpcId = 92101,
          Subtitle = "Do you think {性别:he|she} has heard all that?",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D314"
        },
        [80100323] = {
          ContentES = "Oh… Jajaja…",
          DialogueId = 80100323,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885D33E",
          NextDialogue = 80100324,
          SpeakNpcId = 92101,
          Subtitle = "Oh... Hahahaha...",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D33E"
        },
        [80100324] = {
          ContentES = "Eres una persona realmente adorable, extraña y divertida, del que no puedo cansarme...",
          DialogueId = 80100324,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D368",
          NextDialogue = 80100325,
          SpeakNpcId = 92101,
          Subtitle = "You are so cute, weird, and interesting that I just can't get enough of...",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D368"
        },
        [80100325] = {
          ContentES = "Ahora mismo tengo tantas ganas de envolverte en mi veneno... Pero no juego con el amor, mis intenciones son serias.",
          DialogueId = 80100325,
          GUID = "C885D392",
          NextDialogue = 80100326,
          SpeakNpcId = 92101,
          Subtitle = "I really want to embrace you with my venom now... But I'm 100% serious when it comes to love.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D392"
        },
        [80100326] = {
          ContentES = "Así que, démosnos un tiempo para pensarlo.",
          DialogueId = 80100326,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D3BC",
          SpeakNpcId = 92101,
          Subtitle = "So, let's give us some time to ponder over it.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3BC"
        },
        [80100327] = {
          ContentES = "Qué {性别:astuto|astuta}. ¿Cómo se te ocurren palabras tan ambiguas que rechazan, pero al mismo tiempo atraen?",
          DialogueId = 80100327,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D3E6",
          NextDialogue = 80100328,
          SpeakNpcId = 92101,
          Subtitle = "How cunning. How do you come up with these ambiguous lines of rejection that subtly lead people on?",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3E6"
        },
        [80100328] = {
          ContentES = "¿Apropiada? ¿Cómo se supone que debo interpretar eso? Para mí, seguirte a todas partes es la distancia apropiada… ¿y para ti? ¿Qué es lo apropiado?",
          DialogueId = 80100328,
          GUID = "C885D410",
          NextDialogue = 80100329,
          SpeakNpcId = 92101,
          Subtitle = "Appropriate... how am I supposed to interpret that? For me, shadowing you around is the appropriate distance... But what about you? I'm not sure what's the appropriate distance for you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D410"
        },
        [80100329] = {
          ContentES = "¿Acaso seríamos como amantes, que fingen indiferencia ante el mundo mientras se aman en lo oculto? ¿O nos separaríamos para siempre, sin posibilidad de volver a encontrarnos?",
          DialogueId = 80100329,
          GUID = "C885D43A",
          NextDialogue = 80100330,
          SpeakNpcId = 92101,
          Subtitle = "Is it like secret lovers who frolic only when alone and pretend to be strangers in the presence of others? Or should we just go our separate ways and never, ever see each other again?",
          TalkActionId = {
            [1] = "92101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D43A"
        },
        [80100330] = {
          ContentES = "Esos dos extremos quizás sean los más simples. En lugar de decir claramente “quiero” o “encontrarás alguien mejor”, prefieres este camino de diálogos e intentos.",
          DialogueId = 80100330,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D464",
          NextDialogue = 80100331,
          SpeakNpcId = 92101,
          Subtitle = "But these two extremes might just offer the easiest solutions. Instead of just saying \"I do\" or \"I hope you find someone who actually deserves you,\" you chose the option that paves the way for future dialogues and tests.",
          TalkActionId = {
            [1] = "92101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D464"
        },
        [80100331] = {
          ContentES = "No puedo acercarme demasiado y ponerte en peligro… ni puedo alejarme y dejar que nuestros cuerpos y almas se conviertan en extraños.",
          DialogueId = 80100331,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D48E",
          NextDialogue = 80100332,
          SpeakNpcId = 92101,
          Subtitle = "I can't get too close and risk putting you in danger, nor can I stay away from you and let us become strangers.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D48E"
        },
        [80100332] = {
          ContentES = "Es como crear un perfume sin reglas, donde cada ajuste de cada medida se convierte en un juego delicado… hasta encontrar la esencia perfecta.",
          DialogueId = 80100332,
          GUID = "C885D4B8",
          NextOptions = {
            [1] = 801003321
          },
          SpeakNpcId = 92101,
          Subtitle = "This is like crafting a perfume formula without precise measurements. I can only keep fiddling with the weights and measures as I work towards the perfect result.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4B8"
        },
        [80100333] = {
          ContentES = "Claro que sí. Nunca me había enfrentado a un desafío así. Confío en que al resolverlo, la respuesta me llevará a encontrar a la “Persona destinada”.",
          DialogueId = 80100333,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D4E2",
          NextOptions = {
            [1] = 801003331
          },
          SpeakNpcId = 92101,
          Subtitle = "Of course I am. I've never had a problem like this before, and I believe that by solving it, I will get the answer I've been looking for and find my destined one.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4E2"
        },
        [80100334] = {
          ContentES = "Sí, alguien que he estado buscando desde Luca hasta Hyperborea. Pensaba que esa persona solo aparecía en mis sueños, como una figura brillante pero indistinta.",
          DialogueId = 80100334,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D50C",
          NextDialogue = 80100335,
          SpeakNpcId = 92101,
          Subtitle = "Yes, someone that I've yet to find as I travelled from Luca to Hyperborea. I thought that person only appeared in my dreams as a shiny yet indistinct figure.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D50C"
        },
        [80100335] = {
          ContentES = "Su fuerte cuerpo podrá soportar cada gota de mi veneno… su corazón tan puro podrá recibir todo mi amor… y con sus manos tersas secará cada una de mis lágrimas...",
          DialogueId = 80100335,
          GUID = "C885D536",
          NextDialogue = 80100336,
          SpeakNpcId = 92101,
          Subtitle = "{性别:His|Her} body is strong enough to withstand every drop of my venom... whose heart is pure enough to take in all my love... and whose hands are gentle enough to wipe away all my sorrows...",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D536"
        },
        [80100336] = {
          ContentES = "En cuanto a la “Persona destinada”… ¿no serás tú, individuo adorable y extraño y divertido... que por eso no puedo cansarme?",
          DialogueId = 80100336,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885D560",
          NextDialogue = 80100337,
          SpeakNpcId = 92101,
          Subtitle = "As for whether the destined one is you, who is so cute, weird, and interesting that I just can't get enough of...",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D560"
        },
        [80100337] = {
          ContentES = "Así que, dame un tiempo para pensarlo.",
          DialogueId = 80100337,
          GUID = "C885D58A",
          SpeakNpcId = 92101,
          Subtitle = "Please give me some time to ponder over it.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D58A"
        },
        [80100401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentES = "*Suspira*",
          DialogueId = 80100401,
          FacialId = {
            [1] = "92101:Sad02"
          },
          GUID = "C885E00A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801004011,
            [2] = 801004012
          },
          SpeakNpcId = 92101,
          Subtitle = "*sigh*...",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E00A"
        },
        [80100402] = {
          ContentES = "Sí… hay algo que me tiene totalmente inquieta, y la persona que está frente a mí es la misma fuente de ese problema.",
          DialogueId = 80100402,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E034",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          Subtitle = "Yes, a most vexing matter, and the person who is in front of me is the very source of that trouble.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E034"
        },
        [80100403] = {
          ContentES = "No… no se trata del momento, sino de ti. Desde que recibí tu invitación, una sensación de inquietud empezó a recorrer mi cuerpo.",
          DialogueId = 80100403,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E05E",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          Subtitle = "No, it's not about the timing, it's the person. My troubles began the moment I received your invitation.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E05E"
        },
        [80100404] = {
          ContentES = "¿Sabes? Aunque tengas un aspecto puro e inmaculado, escondes un veneno capaz de dejar sin respiración a quien se acerque.",
          DialogueId = 80100404,
          GUID = "C885E088",
          NextDialogue = 80100405,
          SpeakNpcId = 92101,
          Subtitle = "Despite your pure, flawless appearance, you can suffocate people with your own \"venom.\"",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E088"
        },
        [80100405] = {
          ContentES = "No anunciaste tu peligro como yo lo hice en nuestro primer encuentro. En cambio, tejiste con cautela una delicada red de palabras.",
          DialogueId = 80100405,
          GUID = "C885E0B2",
          NextDialogue = 80100406,
          SpeakNpcId = 92101,
          Subtitle = "You did not announce your danger like I did at our first encounter, but instead cautiously wove a web of words.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0B2"
        },
        [80100406] = {
          ContentES = "Quizás no lo hagas a propósito, pero las personas se sienten atraídas sin darse cuenta, dejándose envolver por tu influencia sutil, hasta volverse distintas de lo que eran antes.",
          DialogueId = 80100406,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E0DC",
          NextDialogue = 80100407,
          SpeakNpcId = 92101,
          Subtitle = "Perhaps you didn't mean to, but it makes people more accustomed to staying here subconsciously, being imperceptibly influenced and changed by you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0DC"
        },
        [80100407] = {
          ContentES = "Después de dejar Luca, apenas me quedé mucho tiempo en ningún lugar ni conocí a alguien que realmente mereciera mi atención.",
          DialogueId = 80100407,
          GUID = "C885E106",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100408,
          SpeakNpcId = 92101,
          Subtitle = "After leaving Luca, I hardly stayed at any place for long or met anyone worthy of my attention.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E106"
        },
        [80100408] = {
          ContentES = "Pensé que esta vez sería igual. Que en un momento de hastío, me despediría con un abrazo mortal.",
          DialogueId = 80100408,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E130",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100409,
          SpeakNpcId = 92101,
          Subtitle = "I thought it would be the same this time — that I would bid farewell to the one with my embrace when I was tired of the journey.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E130"
        },
        [80100409] = {
          ContentES = "Pero esta vez, sorprendentemente, dudé. El veneno dentro de mi cuerpo me susurraba al oído que no podía alejarme de este lugar.",
          DialogueId = 80100409,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885E15A",
          NextDialogue = 80100410,
          SpeakNpcId = 92101,
          Subtitle = "But I hesitated this time. The venom within my body keeps whispering that I can never leave this place.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E15A"
        },
        [80100410] = {
          ContentES = "No puedo aceptar esta versión de mí misma, y esa es la verdadera fuente de mi angustia. Por eso he decidido que hoy pondré fin a nuestro viaje.",
          DialogueId = 80100410,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E184",
          NextDialogue = 80100411,
          SpeakNpcId = 92101,
          Subtitle = "I can't take this, and this is the source of my troubles. So, I've decided to conclude this journey today.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E184"
        },
        [80100411] = {
          ContentES = "En pocas palabras: voy a cubrirte en mi veneno y te diré adiós.",
          DialogueId = 80100411,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E1AE",
          NextDialogue = 80100412,
          SpeakNpcId = 92101,
          Subtitle = "Simply put — I want to wrap you in my venom and bid you farewell.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1AE"
        },
        [80100412] = {
          ContentES = "¿Hay algo más que quieras decir? En estos últimos segundos que te quedan de vida.",
          DialogueId = 80100412,
          GUID = "C885E1D8",
          NextOptions = {
            [1] = 801004121,
            [2] = 801004122
          },
          SpeakNpcId = 92101,
          Subtitle = "So, any last words for the last seconds?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1D8"
        },
        [80100413] = {
          ContentES = "Sé exactamente lo que quiero, y anhelo ver el terror en tu rostro.",
          DialogueId = 80100413,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E202",
          NextDialogue = 80100414,
          SpeakNpcId = 92101,
          Subtitle = "Running away? No, not at all. I know exactly what I want, and I yearn to see the terror on your face.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E202"
        },
        [80100414] = {
          ContentES = "Qué lástima que no te hayas asustado.",
          DialogueId = 80100414,
          GUID = "C885E22C",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          Subtitle = "But you don't seem scared. What a pity.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E22C"
        },
        [80100415] = {
          ContentES = "¿De verdad? ¿Ni siquiera te has asustado un poco? Ansiaba observar tu rostro lleno de miedo. Qué pena.",
          DialogueId = 80100415,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E256",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          Subtitle = "Really? That didn't scare you at all? I was so hoping to see terror on your face. What a pity.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E256"
        },
        [80100416] = {
          ContentES = "Entonces no me queda más remedio que conformarme… y contarte mis verdaderas intenciones.",
          DialogueId = 80100416,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E280",
          NextDialogue = 80100417,
          SpeakNpcId = 92101,
          Subtitle = "Then I'll have to settle for the next best thing, and tell you about my real thoughts.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E280"
        },
        [80100417] = {
          ContentES = "Estos días a tu lado no se parecen en nada a mi vida anterior. Cada tarde, te susurraba palabras dulces, nos poníamos a prueba, en la frontera entre lo verdadero y lo falso...",
          DialogueId = 80100417,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E2AA",
          NextDialogue = 80100418,
          SpeakNpcId = 92101,
          Subtitle = "Days I shared with you are unlike the others I had before. I would say romantic things and we would test each other's sincerity during these afternoon dates...",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2AA"
        },
        [80100418] = {
          ContentES = "Después de despedirnos, abría mi paraguas y corría hasta un callejón desierto. Allí, recordaba cada palabra que habíamos dicho… y bailaba sola, dejándome llevar, dando vueltas sin rumbo.",
          DialogueId = 80100418,
          GUID = "C885E2D4",
          NextDialogue = 80100419,
          SpeakNpcId = 92101,
          Subtitle = "And when the date ended, I would take my umbrella and find a deserted alley. There, I would mull over the conversations we had while dancing and swaying all on my own.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2D4"
        },
        [80100419] = {
          ContentES = "¿Acaso no te parece romántico?",
          DialogueId = 80100419,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E2FE",
          NextDialogue = 80100420,
          SpeakNpcId = 92101,
          Subtitle = "Hehe... Isn't that romantic as well?",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2FE"
        },
        [80100420] = {
          ContentES = "Aunque siempre deseé encontrar a la “Persona destinada”, alguien capaz de soportar la intensidad de mis abrazos, hoy me di cuenta de que, en el fondo,lo único que anhelo es un amor único, solo mío.",
          DialogueId = 80100420,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E328",
          NextDialogue = 80100421,
          SpeakNpcId = 92101,
          Subtitle = "I had always wanted to find the destined one who was capable of surviving my embrace. But today, I finally realised that all I want is love that belongs to me.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E328"
        },
        [80100421] = {
          ContentES = "Mi abrazo servía de piedra de toque. Pero al primer latido sincero... supe. Un amor verdadero, único... no necesita ser puesto a prueba.",
          DialogueId = 80100421,
          GUID = "C885E352",
          NextDialogue = 80100422,
          SpeakNpcId = 92101,
          Subtitle = "My embrace used to be my touchstone. But when my heart skipped a beat, I started to know that true love, the kind I can call my own, does not need to be tested.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E352"
        },
        [80100422] = {
          ContentES = "Los besos y los abrazos no son necesarios. Al contrario… lo que yo deseo es una estela que perdure, un aroma final que nunca se disipe.",
          DialogueId = 80100422,
          GUID = "C885E37C",
          NextDialogue = 80100423,
          SpeakNpcId = 92101,
          Subtitle = "The kisses and hugs are not necessary. I prefer the lingering aftertaste that does not fade.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E37C"
        },
        [80100423] = {
          ContentES = "Quiero decirte “buenos días” cada mañana, dejar que inhales la fragancia recién creada y experimentar contigo nuevos aromas… Vivir así, día tras día, no sería tan malo.",
          DialogueId = 80100423,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885E3A6",
          NextDialogue = 80100424,
          SpeakNpcId = 92101,
          Subtitle = "It doesn't seem bad to have daily routines like morning greetings, smelling my latest perfume, and continuing my work on other perfume recipes...",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3A6"
        },
        [80100424] = {
          ContentES = "Intentaré crear un perfume que neutralice mi veneno, o buscaré un hechizo que purifique mis toxinas. Como la pequeña sirena de los cuentos de hadas, haré lo que sea necesario para cambiar por amor.",
          DialogueId = 80100424,
          GUID = "C885E3D0",
          NextDialogue = 80100425,
          SpeakNpcId = 92101,
          Subtitle = "I will try to make a perfume that can neutralise my venom, or search for a spell that can cleanse the toxins. Like some little mermaid in those fairytales, I'll do whatever I can to change for my love.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3D0"
        },
        [80100425] = {
          ContentES = "Así quizás, algún día, pueda abrazarte.",
          DialogueId = 80100425,
          GUID = "C885E3FA",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100426,
          SpeakNpcId = 92101,
          Subtitle = "Perhaps a day will come when I can finally hold you in my arms.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3FA"
        },
        [80100426] = {
          ContentES = "No sería para ponerte a prueba, sino una forma de entregarte todo mi amor.",
          DialogueId = 80100426,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885E424",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          SpeakNpcId = 92101,
          Subtitle = "Not for any test, but only to express my love for you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E424"
        },
        [80110100] = {
          ContentES = "Jaja, gracias.",
          DialogueId = 80110100,
          GUID = "C88C1748",
          Subtitle = "Hah, thanks.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1748"
        },
        [80110101] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentES = "¿Evaluando tus habilidades para mezclar bebidas? Entonces buscaste a la persona equivocada, porque yo no sé de esas cosas.",
          DialogueId = 80110101,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1772",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110102,
          SpeakNpcId = 93101,
          Subtitle = "Assessing your drink mixing skills? You got the wrong person. I know nothing about this.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1772"
        },
        [80110102] = {
          ContentES = "Para mí, todos los licores del mundo son lo mismo. Lo único que importa es que sea bebible. Cuando se trata de los sonidos de estas botellas y frascos, para mí son solo ruido.",
          DialogueId = 80110102,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C179C",
          NextOptions = {
            [1] = 801101021
          },
          SpeakNpcId = 93101,
          Subtitle = "All drinks are the same to me — If it tastes right, I'll drink it. When it comes to these bottles and flasks sounds, they are just noise to me.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C179C"
        }
      }
    end
  },
  {
    MinKey = 80110103,
    MaxKey = 80120327,
    Loader = function()
      return {
        [80110103] = {
          ContentES = "La Legión está hecha para la guerra, no para hacer picnics.",
          DialogueId = 80110103,
          GUID = "C88C17C6",
          NextDialogue = 80110104,
          SpeakNpcId = 93101,
          Subtitle = "The Legion's built for war, not picnics.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17C6"
        },
        [80110104] = {
          ContentES = "Espera, ¿acabas de decir “Legión”…?",
          DialogueId = 80110104,
          FacialId = {
            [1] = "93101:Doubt01"
          },
          GUID = "C88C17F0",
          NextDialogue = 80110105,
          SpeakNpcId = 93101,
          Subtitle = "Wait, you mentioned the \"Legion\"...",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17F0"
        },
        [80110105] = {
          ContentES = "¿Qué intenciones tienes? ¿Qué planeas? ¿Cuál es tu identidad? ¿Quién te envió? ¿Qué intentas averiguar? ¡Quiero una explicación!",
          DialogueId = 80110105,
          GUID = "C88C181A",
          NextOptions = {
            [1] = 801101051,
            [2] = 801101052
          },
          SpeakNpcId = 93101,
          Subtitle = "...What do you want? What are you planning? Who are you? Who sent you? What intel are you after? Spill it.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C181A"
        },
        [80110106] = {
          ContentES = "Estás demasiado bien informado para ser {性别:un simple Phoxcazador|una simple Phoxcazadora}.",
          DialogueId = 80110106,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1844",
          NextDialogue = 80110107,
          SpeakNpcId = 93101,
          Subtitle = "You're too well-informed for a mere Phoxhunter.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1844"
        },
        [80110107] = {
          ContentES = "Lo sospechaba... Nadie es tan servicial sin tener algo entre manos.",
          DialogueId = 80110107,
          GUID = "C88C186E",
          NextDialogue = 80110108,
          SpeakNpcId = 93101,
          Subtitle = "…I should've known. No one offers gifts without wanting something in return.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C186E"
        },
        [80110108] = {
          ContentES = "Es hora de llevarte a la Legión para interrogarte. Coopera y no me obligues a atarte, no nos vendría bien a ninguno de los dos.",
          DialogueId = 80110108,
          FacialId = {
            [1] = "93101:Confident01"
          },
          GUID = "C88C1898",
          NextDialogue = 80110109,
          SpeakNpcId = 93101,
          Subtitle = "Time to take you to the Legion for questioning. Cooperate, and don't make me tie you up — it won't look good for either of us.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1898"
        },
        [80110109] = {
          ContentES = "(Lo siguiente pasa rápidamente por tu mente: Sin agregar más explicaciones, Lynn saca una pistola. Te apunta rápidamente a la frente).",
          DialogueId = 80110109,
          GUID = "C88C18C2",
          IsBlack = 1,
          NextDialogue = 80110110,
          Subtitle = "(The following quickly flashes through your mind: Lynn takes out her gun immediately, and the dark muzzle is pointed straight at your forehead.)",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18C2"
        },
        [80110110] = {
          ContentES = "(Era evidente que ese sería el final de todo. Pero negaste con la cabeza, y apartaste de ti aquel último pensamiento).",
          DialogueId = 80110110,
          GUID = "C88C18EC",
          IsBlack = 1,
          NextDialogue = 80110111,
          Subtitle = "(This outcome is predictable. You shook your head and dismissed the risky idea to keep fishing out intel from her.)",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18EC"
        },
        [80110111] = {
          ContentES = "Te estás equivocando. Solo te vi pasar y pensé en invitarte a tomar algo.",
          DialogueId = 80110111,
          GUID = "C88C1916",
          NextDialogue = 80110112,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You've got it wrong. I just saw you and thought I'd invite you for a drink.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1916"
        },
        [80110112] = {
          ContentES = "...",
          DialogueId = 80110112,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1940",
          NextDialogue = 80110113,
          SpeakNpcId = 93101,
          Subtitle = "......",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1940"
        },
        [80110113] = {
          ContentES = "Me puse demasiado nerviosa. Eh, disculpa por eso.",
          DialogueId = 80110113,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C196A",
          NextDialogue = 80110114,
          SpeakNpcId = 93101,
          Subtitle = "Guess I was too on edge. Ahem, sorry about that.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C196A"
        },
        [80110114] = {
          ContentES = "Es solo que ha habido algunos Phoxcazadores audaces que, al ver que yo era uno de ellos, intentaron acercarse a mí y sonsacar los secretos de la Legión.",
          DialogueId = 80110114,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1994",
          NextOptions = {
            [1] = 801101141,
            [2] = 801101142
          },
          SpeakNpcId = 93101,
          Subtitle = "It's just there have been some audacious Phoxhunters who, seeing that I was one of them, tried to get close to me and fish for the secrets of the legion.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1994"
        },
        [80110115] = {
          ContentES = "Sí, fue hace mucho tiempo. Espera… ¿se supone que tengo permiso para hablar de eso?",
          DialogueId = 80110115,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C19BE",
          NextDialogue = 80110116,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, that was years ago. Wait, should I reveal this to others?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19BE"
        },
        [80110116] = {
          ContentES = "No pasa nada.... La Legión tampoco exige ocultar la identidad que uno tenía antes.",
          DialogueId = 80110116,
          GUID = "C88C19E8",
          NextOptions = {
            [1] = 801101161
          },
          SpeakNpcId = 93101,
          Subtitle = "...Never mind. The Legion doesn't say we have to hide who we were.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19E8"
        },
        [80110117] = {
          ContentES = "Uf, no tienes idea de cómo es estar en la Legión.",
          DialogueId = 80110117,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C1A12",
          NextDialogue = 80110118,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, you have no idea what it's like in the Legion.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A12"
        },
        [80110118] = {
          ContentES = "En las murallas de la Legión hay rejas eléctricas de Phoxichor que despiden chispas sin parar. Sirven para que nadie se escape… y para electrocutar a cualquier ladrón o espía que se acerque.",
          DialogueId = 80110118,
          GUID = "C88C1A3C",
          NextDialogue = 80110119,
          SpeakNpcId = 93101,
          Subtitle = "Legion camps are surrounded by electric fences powered by Phoxichor. They crackle with sparks, detering deserters, as well as discouraging thieves and spies.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A3C"
        },
        [80110119] = {
          ContentES = "Pero al menos puedes ver esas rejas. Son las invisibles de las que debes preocuparte, si te equivocas, dices algo incorrecto, ¡zas!, te electrocutas allí mismo.",
          DialogueId = 80110119,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1A66",
          NextDialogue = 80110120,
          SpeakNpcId = 93101,
          Subtitle = "But at least you can see those fences. It's the invisible ones you have to worry about — if you slip up, say the wrong thing, one zap, and you're gone.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A66"
        },
        [80110120] = {
          ContentES = "Mi jefa detesta a los traidores sobre todo. No pienso dejar que me saquen información y acabar muerta por un simple descuido.",
          DialogueId = 80110120,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1A90",
          NextOptions = {
            [1] = 801101201,
            [2] = 801101202
          },
          SpeakNpcId = 93101,
          Subtitle = "My supreme officer has something personal against traitors. I don't want to end up dead over some accidental leak.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A90"
        },
        [80110121] = {
          ContentES = "¡Pues, claro! Si yo ni siquiera quería entrar.",
          DialogueId = 80110121,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1ABA",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          Subtitle = "You think? I never wanted to be in the Legion.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1ABA"
        },
        [80110122] = {
          ContentES = "¿Estatus y prestigio? Claro, si crees que vale la pena arriesgar la vida todos los días. ¿Lo harías?",
          DialogueId = 80110122,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1AE4",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          Subtitle = "Status and prestige? Sure, if you think risking your neck daily is worth it.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1AE4"
        },
        [80110123] = {
          ContentES = "Pues mira.... cuando era una Phoxcazadora tampoco era pan comido, pero al menos era libre.",
          DialogueId = 80110123,
          GUID = "C88C1B0E",
          NextDialogue = 80110124,
          SpeakNpcId = 93101,
          Subtitle = "...I was happier as a Phoxhunter. It wasn't an easy gig, but at least I was free.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B0E"
        },
        [80110124] = {
          ContentES = "No todos los encargos implican arriesgar la vida. A veces tocaba pasear perros o cazar ciervos, cosas bastante tranquilas. Y después de un encargo pesado, incluso podías ir al Asfódelo, a tomar un trago y entrar en calor.",
          DialogueId = 80110124,
          GUID = "C88C1B38",
          NextDialogue = 80110125,
          SpeakNpcId = 93101,
          Subtitle = "Not all commissions were about cheating death. Sometimes you'd get to walk dogs or hunt deer. And after a big score, you could enjoy a pint at The Asphodel.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B38"
        },
        [80110125] = {
          ContentES = "Puedes hacerlo por tu cuenta. No necesitas explicar tus planes a nadie ni preocuparte por lastre innecesario.",
          DialogueId = 80110125,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1B62",
          NextDialogue = 80110126,
          SpeakNpcId = 93101,
          Subtitle = "You can do it on your own. No need to explain to anyone about your plans or worry about dead weight.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B62"
        },
        [80110126] = {
          ContentES = "Y lo mejor de todo. No tienes que soportar a los oficiales ruidosos que cacarean como gallinas.",
          DialogueId = 80110126,
          GUID = "C88C1B8C",
          NextOptions = {
            [1] = 801101261
          },
          SpeakNpcId = 93101,
          Subtitle = "Most importantly, you didn't have to deal with commanders who can't stop their yapping.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B8C"
        },
        [80110127] = {
          ContentES = "Pensé que no se podía hablar mal de tus jefes. ¿No te electrocutarían por decir todo esto?",
          DialogueId = 80110127,
          GUID = "C88C1BB6",
          NextDialogue = 80110128,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "I thought bad-mouthing your superiors can be considered as something wrong. Wouldn't that get you zapped?",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BB6"
        },
        [80110128] = {
          ContentES = "¡¡…!!",
          DialogueId = 80110128,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1BE0",
          NextDialogue = 80110129,
          SpeakNpcId = 93101,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BE0"
        },
        [80110129] = {
          ContentES = "¡Por supuesto! No soy una de esas nobles de piel dura que aguantan todo. Pero si mis superiores oyeran esto, me freirían... o algo peor.",
          DialogueId = 80110129,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1C0A",
          NextDialogue = 80110130,
          SpeakNpcId = 93101,
          Subtitle = "A...Absolutely! I'm no noble — those thick-skinned aristocrats can definitely survive a zap. But if my superiors heard this, they'd fry me, or worse.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C0A"
        },
        [80110130] = {
          ContentES = "Si te atreves a contarlo, te volaré la cabeza de un tiro, ¿entiendes?",
          DialogueId = 80110130,
          GUID = "C88C1C34",
          NextOptions = {
            [1] = 801101301
          },
          SpeakNpcId = 93101,
          Subtitle = "If you go around telling people what I just said, I'll put a bullet in your head. Understood?",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C34"
        },
        [80110131] = {
          ContentES = "Pero, debo decir que me has sorprendido un poco…",
          DialogueId = 80110131,
          GUID = "C88C1C5E",
          NextDialogue = 80110132,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Anyway, I find you quite... different.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C5E"
        },
        [80110132] = {
          ContentES = "Yo pensaba que, como una oficial de Hyperborea, tendrías algo de... creencia en el Imperio. Como, hablar de honor, lealtad, esas cosas...",
          DialogueId = 80110132,
          GUID = "C88C1C88",
          NextDialogue = 80110133,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "I thought as a Hyperborean officer, you would have some... belief in the Empire. Like, talk about honour, loyalty, stuff like that...",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C88"
        },
        [80110133] = {
          ContentES = "Pff, eso sirve para engañar a los novatos. Pero para mí…",
          DialogueId = 80110133,
          GUID = "C88C1CB2",
          NextDialogue = 80110134,
          SpeakNpcId = 93101,
          Subtitle = "Pfft, that kind of crap might work on the noobs.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CB2"
        },
        [80110134] = {
          ContentES = "Quizá mucha gente daría todo por cosas que no se pueden ver ni tocar, pero yo no. Sé perfectamente por qué me convertí en una Phoxcazadora y por qué me uní a la Legión.",
          DialogueId = 80110134,
          GUID = "C88C1CDC",
          NextDialogue = 80110135,
          SpeakNpcId = 93101,
          Subtitle = "Many would sacrifice everything for those invisible and untouchable things like sense of faith, but I am not one of them. I know exactly why I became a Phoxhunter and why I joined the Legion.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CDC"
        },
        [80110135] = {
          ContentES = "No es más que para ganarme el pan... Lo tuve muy claro desde el principio. La Legión necesita mi fuerza y yo necesito su paga. Es un negocio donde cada uno obtiene lo que necesita.",
          DialogueId = 80110135,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1D06",
          NextDialogue = 80110136,
          SpeakNpcId = 93101,
          Subtitle = "...I just needed a job that brings food to the table. I got that figured out from the start. The Legion needs my skills and I need their paycheck. Simple exchange.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D06"
        },
        [80110136] = {
          ContentES = "Lo de honor o la fe que hablas… no existe.",
          DialogueId = 80110136,
          GUID = "C88C1D30",
          NextOptions = {
            [1] = 801101361
          },
          SpeakNpcId = 93101,
          Subtitle = "All that talk of \"glory\" and \"faith\" — it's not why I'm here.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D30"
        },
        [80110137] = {
          ContentES = "¡¡…!!",
          DialogueId = 80110137,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1D5A",
          NextDialogue = 80110138,
          SpeakNpcId = 93101,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D5A"
        },
        [80110138] = {
          ContentES = "¡Maldita sea! Sabía que no debería haber tomado esta bebida. No puedo quedarme callada cuando estoy un poco mareada.",
          DialogueId = 80110138,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1D84",
          NextDialogue = 80110139,
          SpeakNpcId = 93101,
          Subtitle = "D**n it! I knew I shouldn't have had this drink. Can't keep my mouth shut when I'm a bit tipsy.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D84"
        },
        [80110139] = {
          ContentES = "¡Me largo, no voy a beber más! ¡No digas nada a nadie!",
          DialogueId = 80110139,
          GUID = "C88C1DAE",
          SpeakNpcId = 93101,
          Subtitle = "I'm done here! And don't you dare let today's conversation out!",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1DAE"
        },
        [80110201] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentES = "Dame otra bebida...",
          DialogueId = 80110201,
          GUID = "C88C27DA",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110202,
          SpeakNpcId = 93101,
          Subtitle = "...Hit me with another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          ContentES = "Oye, ¿cómo consigues los encargos en Lago helado normalmente? ¿Aún te sigues quedando en “Asfódelo”?",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          Subtitle = "Hey, how do you usually pick up your gigs? Still at The Asphodel?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentES = "Nada ha cambiado mucho. Asfódelo es un lugar muy bonito… al menos Camilla no te manda a matar o a saquear de la nada.",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          Subtitle = "Hmm, just like old times. The Asphodel is a neat place... At least Camilla doesn't suddenly throw in jobs where you have to kill people and rob their stuff.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          ContentES = "Ja, nunca subestimes a Lago Helado. Está llena de tipos más duros que en la capital, sobre todo en las afueras donde la Oficina de Seguridad ni se molesta en vigilar. Pero no te preocupes, los encargos de Camilla son bastante tranquilos, a menos que aceptes encargos por tu cuenta. Allí sí podrías meterte en asuntos bastante turbios.",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          Subtitle = "Hah, never underestimate Icelake. It's teeming with tougher nuts than the capital, especially with the Security Bureau ignoring the outskirts. But don't worry — Camilla's gigs are clean, unless you're dabbling in the sketchy ones.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          ContentES = "Hablando de eso, ¿cómo está Camilla? ¿Sigue siendo igual de dura que antes?",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          Subtitle = "Speaking of which, how is Camilla these days? Still got that edge?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          ContentES = "¡Qué bueno! Vaya, como pasan los años. Camilla se ha vuelto amable... Qué pena que mi jefa siga siendo igual de temible.",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "That's good to hear! Ugh, time flies, even turned Camilla sweet, but it still couldn't soften up my iron-fisted supreme officer.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          ContentES = "Bueno, Camilla no ha cambiado en nada… Puf, es igual que mi jefa: bonita, pero anda por ahí comportándose como un volcán enojado.",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "Okay, so Camilla hasn't changed at all... Ugh, she's just like my supreme officer — pretty but goes around acting like a pissed volcano.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          ContentES = "No puedo darte nombres... Si te lo digo, me tirarían contra las rejas eléctricas de la muralla para volverme cenizas.",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          Subtitle = "Her name is... Sorry, can't tell you. I'd rather not end up on the electric fence getting zapped to ashes.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          ContentES = "Todo el día tiene la cara larga, como si toda la Legión le debiera un montón de dinero.",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          Subtitle = "She's always got this long face like the entire Legion owes her money or something.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          ContentES = "¡Puf! Y sus manías raras. ¿Quién en su sano juicio no usaría una pistola? Pero ella insiste en usar su látigo electrificado, dice que es mucho más manejable que una pistola.",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, and her quirks! Like, who doesn't use a gun these days? But she insists on using her electrified whip and claims it works better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          ContentES = "(De pronto, tuviste un presentimiento. Esa descripción te hizo acordar de alguien que estabas buscando: Sibylle).",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          Subtitle = "(Your heart skipped a beat. Her descriptions reminded you of someone you're looking for — Sibylle.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          ContentES = "Las personas normales suelen preferir tranquilidad cuando piensan, ¿verdad? Pues ella no, se pasa todo el día escuchando una grabación ruidosa, y dice que eso la motiva y le ayuda a concentrarse mejor.",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          Subtitle = "And people usually prefer peace and quiet when they have something to think about, right? Not her — she always blasts a loud recording and says it pumps her up and helps her think better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          ContentES = "Incluso tiene cuervos en su oficina. ¡Y no le importa que sus excrementos caigan justo sobre los informes que le envía a Su Majes.... Ups, quiero decir, a su jefe.",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          Subtitle = "She even keeps crows in her office. Hasn't she ever worried about bird droppings on her reports to His M—um, her higher-ups?",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          ContentES = "Y eso no es todo. La gente normal va al río para relajarse, disfrutar de la brisa y del paisaje, ¿verdad? Pues ella no, a ella le gusta ir a ver a los pescadores regresar con las manos vacías, dice que le resulta divertido y que le ayuda a aliviar el estrés.",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          Subtitle = "And then there's this: normal people go to the riverside to unwind and enjoy the breeze and scenery, right? My boss? She goes there only to watch anglers come back empty-handed, says it's funny and stress-relieving.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          ContentES = "¿Cómo puede existir alguien así?",
          DialogueId = 80110215,
          GUID = "C88C2A26",
          NextOptions = {
            [1] = 801102151
          },
          SpeakNpcId = 93101,
          Subtitle = "I mean — who does that!?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A26"
        },
        [80110216] = {
          ContentES = "Es una rarita. Si la conoces en persona, ya no te parecerá tan interesante. De la que te acabo de contar es mi jefa mayor, pero mi jefe directo es más raro aún.",
          DialogueId = 80110216,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C2A50",
          NextDialogue = 80110217,
          SpeakNpcId = 93101,
          Subtitle = "She's nuts. Trust me, she's far less interesting in person. Oh, and that's just the top boss. My direct superior? Even nuttier.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A50"
        },
        [80110217] = {
          ContentES = "Es muy creído para hablar y se cree muy elegante. ¿Honestamente? Suena como un ganso mojado e indeciso.",
          DialogueId = 80110217,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2A7A",
          NextDialogue = 80110218,
          SpeakNpcId = 93101,
          Subtitle = "Now this dude rambles in circles and thinks he's all classy. Honestly? He sounds like a wishy-washy wet goose.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A7A"
        },
        [80110218] = {
          ContentES = "Se la pasa todo el día hablando de eficiencia y ahorro de energía, pero es muy obvio, son solo excusas para holgazanear. Ese truquito ya nos lo sabemos todos.",
          DialogueId = 80110218,
          GUID = "C88C2AA4",
          NextDialogue = 80110219,
          SpeakNpcId = 93101,
          Subtitle = "That guy's always babbling about efficiency and energy saving. Ugh, everyone knows that he's just making excuses for his laziness.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AA4"
        },
        [80110219] = {
          ContentES = "Pero no te puedo mentir, ese tipo es bastante listo. A menudo se la pasa holgazaneando y, sin embargo, logra hacer su trabajo, sin que nadie pueda encontrarle fallos.",
          DialogueId = 80110219,
          GUID = "C88C2ACE",
          NextDialogue = 80110220,
          SpeakNpcId = 93101,
          Subtitle = "But I'll give him this — he's sharp. Slacks off, sure, but somehow still manages to get the job done. No one can really fault him for that.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2ACE"
        },
        [80110220] = {
          ContentES = "Hace poco, él descubrió la ubicación de un tesoro con solo un par de pistas. Era algo que mi jefa había estado buscando durante años. Pero, bueno… al final hubo un pequeño contratiempo.",
          DialogueId = 80110220,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2AF8",
          NextDialogue = 80110221,
          SpeakNpcId = 93101,
          Subtitle = "Not long ago, he cracked the location of treasure with just a few clues. That's something my supreme officer had been chasing for years. But, well, there was... a little hiccup.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AF8"
        },
        [80110221] = {
          ContentES = "(Si no me equivoco, el “tesoro” del que habla Lynn... podría bien ser Berenica.)",
          DialogueId = 80110221,
          GUID = "C88C2B22",
          NextOptions = {
            [1] = 801102211
          },
          Subtitle = "(If I guessed correctly, the \"treasure\" that Lynn mentioned could very well be Berry.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B22"
        },
        [80110222] = {
          ContentES = "No me preguntes a mí… Los dos estuvieron a cargo de esa misión. Es un asunto confidencial, ¿cómo voy a saberlo?",
          DialogueId = 80110222,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2B4C",
          NextDialogue = 80110223,
          SpeakNpcId = 93101,
          Subtitle = "Don't ask me... The two of them handled that mission together. It's all top secret — how would I know?",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B4C"
        },
        [80110223] = {
          ContentES = "...",
          DialogueId = 80110223,
          GUID = "C88C2B76",
          NextDialogue = 80110224,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "......",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B76"
        },
        [80110224] = {
          ContentES = "Vaya, hoy sí que he dicho demasiadas cosas que no debía… Puf, toda la culpa la tiene esta maldita bebida. ¡No me digas que le pusiste algún tipo de suero de la verdad o algo así!",
          DialogueId = 80110224,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C2BA0",
          NextDialogue = 80110225,
          SpeakNpcId = 93101,
          Subtitle = "Crap. I really said a load of stuff I shouldn't be saying at all... It must be this lousy booze! You didn't spike it with a truth serum or something, did you?",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BA0"
        },
        [80110225] = {
          ContentES = "Me voy, me voy. Menos mal que en Dismania no bebo, o mi jefa ya me habría electrocutado con el látigo... No, espera, eso mejor no lo digo...",
          DialogueId = 80110225,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2BCA",
          SpeakNpcId = 93101,
          Subtitle = "Sheesh. I'm outta here. Ugh — thank goodness I don't drink in Dismania, or I'd end up zapped by my superior's whip... Argh, better stop talking now...",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BCA"
        },
        [80110226] = {
          Camera = "164.130432,-127.039795,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Confío en que no dirás nada de lo que he dicho.",
          DialogueId = 80110226,
          FinalCamera = "164.130432,-118.0,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C88C2BF4",
          LookAt = {
            [1] = "790014:n(790008)"
          },
          NextDialogue = 80110227,
          SpeakNpcId = 790014,
          Subtitle = "And I trust you won't go blabbing about what I said.",
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "790008:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BF4"
        },
        [80110227] = {
          Camera = "13.894012,-267.815552,157.042679,0.00001,-2.999996,96.801392,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sé muy bien que escogiste un trago más fuerte. Tus motivos eran sacarme información, pero decidí hacerme la tonta y seguirte el juego.",
          DialogueId = 80110227,
          GUID = "C88C2C1E",
          NextDialogue = 80110228,
          SpeakNpcId = 790014,
          Subtitle = "I know exactly why you chose that extra-strong drink. You had your own reasons for coaxing intel from me — but I chose to act the fool and play along.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C1E"
        },
        [80110228] = {
          Camera = "13.276428,-53.140625,124.735672,0.000025,0.0,86.600571,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Dejémoslo así. No sigas intentando probarme. No puedo enfrentarme a la Legión, todos tenemos que vivir, ¿no?",
          DialogueId = 80110228,
          FinalCamera = "13.276428,-68.0,124.735672,0.000025,0.0,86.600571,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C88C2C48",
          LookAt = {
            [1] = "790014:n(790014)"
          },
          NextDialogue = 80110229,
          SpeakNpcId = 790014,
          Subtitle = "Let's stop here. Don't push any further. I can't cross the Legion — everyone's gotta live, right?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C48"
        },
        [80110229] = {
          Camera = "14.200928,-236.600464,163.609055,-0.0,-7.599944,97.395355,35.0,180.0,false,Manual,2.8",
          ContentES = "Y tampoco quiero… perder a una persona con la quien pueda hablar.",
          DialogueId = 80110229,
          FinalCamera = "12.948349,-226.679688,163.609055,0.000001,-7.599944,97.195381,35.0,130.0,false,Manual,2.8",
          GUID = "C88C2C72",
          NextDialogue = 80110230,
          SpeakNpcId = 790014,
          Subtitle = "And I don't want to... lose someone that I can actually talk to.",
          TalkActionId = {
            [1] = "790014:Disagree",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C72"
        },
        [80110230] = {
          ContentES = "Bueno, eso es todo. ¡Me voy!",
          DialogueId = 80110230,
          GUID = "C88C2C9C",
          IsBlack = 1,
          SpeakNpcId = 790014,
          Subtitle = "Alright, that's it. I'm off!",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C9C"
        },
        [80110301] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentES = "Oye, hazme un favor. Te doy algo a cambio.",
          DialogueId = 80110301,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3842",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110302,
          SpeakNpcId = 93101,
          Subtitle = "Hey, do me a favor. I'll pay you.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3842"
        },
        [80110302] = {
          ContentES = "Mañana regresaré a la capital, pero tengo que entregar un paquete. Ayúdame a entregarlo al distrito oeste, en la calle Roble Nº 48, a una mujer llamada Riola Baker.",
          DialogueId = 80110302,
          GUID = "C88C386C",
          NextOptions = {
            [1] = 801103021
          },
          SpeakNpcId = 93101,
          Subtitle = "I'm off to the capital tomorrow and I've got a package here that needs to be delivered to No. 48, Oak Street in the west suburbs. It's for a lady named Riola Baker.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C386C"
        },
        [80110303] = {
          ContentES = "¿Por qué tantas preguntas?",
          DialogueId = 80110303,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3896",
          NextOptions = {
            [1] = 801103031,
            [2] = 801103032
          },
          SpeakNpcId = 93101,
          Subtitle = "You're asking too many questions.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3896"
        },
        [80110304] = {
          ContentES = "De acuerdo. Entonces te lo diré. Dentro hay un arma y una máscara.",
          DialogueId = 80110304,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C38C0",
          NextDialogue = 80110305,
          SpeakNpcId = 93101,
          Subtitle = "Fair point. Alright, I'll spill it. There's a gun and a mask in there.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38C0"
        },
        [80110305] = {
          ContentES = "No te pongas de nervios, es un arma de juguete. Si no me crees, puedes usarla contra mí.",
          DialogueId = 80110305,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C38EA",
          NextOptions = {
            [1] = 801103051
          },
          SpeakNpcId = 93101,
          Subtitle = "Don't be nervous. It's just a toy gun. If you don't believe me, feel free to test it on me.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38EA"
        },
        [80110306] = {
          ContentES = "(¡BANG!)",
          DialogueId = 80110306,
          GUID = "C88C3914",
          NextDialogue = 80110307,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          Subtitle = "(BANG—)",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3914"
        },
        [80110307] = {
          ContentES = "¡Ay! Aunque sean balas de salva duelen bastante, ¡y por qué me disparaste en la frente! ¡Ven aquí, que te voy a dar una paliza! ¡Maldita sea, eso dolió muchísimo!",
          DialogueId = 80110307,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C393E",
          NextDialogue = 80110308,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          SpeakNpcId = 93101,
          Subtitle = "Ow! Fake bullets hurt too! And why aim at the head!? Get over here, I'm gonna give you a thrashing! D**n, that friggin' hurt.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C393E"
        },
        [80110308] = {
          ContentES = "*Suspira*, eso me trae recuerdos. Cuando era niña, me peleaba con Riola, nos pegábamos con la resortera. Tengo suerte que haya salido viva. Esa pistola… es un regalo para ella.",
          DialogueId = 80110308,
          GUID = "C88C3968",
          NextOptions = {
            [1] = 801103081
          },
          SpeakNpcId = 93101,
          Subtitle = "*sigh* You know what, this reminds me of the fights I used to have with Riola when we were little. We'd use slingshots to hit each other in the head. Lucky I'm still alive, huh? Anyway, this gun... is my present for her.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3968"
        },
        [80110309] = {
          ContentES = "Sí, algo así… Ya que venía de una misión de Lago Helado, decidí traerle algo.",
          DialogueId = 80110309,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3992",
          NextDialogue = 80110310,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, sort of... Had to come to Icelake for a mission, figured I might as well bring something.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3992"
        },
        [80110310] = {
          ContentES = "¡Deja de preguntar tanto! ¿Lo haces o no? Si no, buscaré a {性别:otro Phoxcazador|otra Phoxcazadora}.",
          DialogueId = 80110310,
          GUID = "C88C39BC",
          NextOptions = {
            [1] = 801103101
          },
          SpeakNpcId = 93101,
          Subtitle = "And you've had way too many questions. Look, are you in or out? There's no shortage of Phoxhunters for the job, you know.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39BC"
        },
        [80110311] = {
          ContentES = "¿Ir yo? ¡Ni hablar! Ni de broma volvería a Lago Helado, a menos que sea por una orden de arriba.",
          DialogueId = 80110311,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C39E6",
          NextOptions = {
            [1] = 801103111,
            [2] = 801103112
          },
          SpeakNpcId = 93101,
          Subtitle = "Deliver it myself? Forget it. If it weren't for orders from the top, I wouldn't bother coming back to Icelake.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39E6"
        },
        [80110312] = {
          ContentES = "¡Bah, déjate ya!",
          DialogueId = 80110312,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3A10",
          NextDialogue = 80110313,
          SpeakNpcId = 93101,
          Subtitle = "Tsk, cut it out.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A10"
        },
        [80110313] = {
          ContentES = "No es como si nunca hubiera vuelto. De hecho, una vez estaba pensando en ir a ver mis amigos de la infancia con los que hacía travesuras, invitarlos a tomar algo. Solo quería charlar de las cosas tontas que hacíamos antes, para despejarme un poco de la Legión.",
          DialogueId = 80110313,
          GUID = "C88C3A3A",
          NextDialogue = 80110314,
          SpeakNpcId = 93101,
          Subtitle = "I did come back here before and had plans to catch up with the old gang. We used to climb trees and swipe veg together as kids. I wanted to chat with them, laugh about those silly pranks over a pint or two, and forget about life in the Legion for a while.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A3A"
        },
        [80110314] = {
          ContentES = "Al final, no sé ni cómo se enteraron de que iba a volver, apenas puse un pie ahí y ya me estaban esperando en fila. Cuando llegué, me saludaron desde lejos: “¡Oficial Lynn!”. Hasta los pájaros del tejado salieron volando del susto.",
          DialogueId = 80110314,
          GUID = "C88C3A64",
          NextDialogue = 80110315,
          SpeakNpcId = 93101,
          Subtitle = "But word got out I was coming. They all lined up, saluted from a distance, yelling \"Officer Lynn\" so loud it scared the birds off the roofs.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A64"
        },
        [80110315] = {
          ContentES = "Yo pensaba que, aunque me hubiera distanciado un poco de ellos, todos volveríamos a reír y recordar cómo jugábamos juntos de niños.",
          DialogueId = 80110315,
          GUID = "C88C3A8E",
          NextDialogue = 80110316,
          SpeakNpcId = 93101,
          Subtitle = "I thought I'd let them do their thing. Get it out of their system. Then we'd all loosen up a bit reminiscing about tearing down the streets as kids.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A8E"
        },
        [80110316] = {
          ContentES = "Pero la vieja pandilla nunca me dio la oportunidad. Todos estaban demasiado ocupados saludando, inclinándose como si me debieran algo. Ni siquiera podían mirarme a los ojos.",
          DialogueId = 80110316,
          GUID = "C88C3AB8",
          NextOptions = {
            [1] = 801103161
          },
          SpeakNpcId = 93101,
          Subtitle = "But the old gang never gave me the chance. Everyone was too busy saluting, bowing like they owed me something. Couldn't even look me in the eye.",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AB8"
        },
        [80110317] = {
          ContentES = "Claro que es normal. He visto lo suficiente como para saber por qué me tienen tanto miedo. Si no fuera por mi entrada en la Legión, yo sería quien tiembla al ver a los soldados.",
          DialogueId = 80110317,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3AE2",
          NextDialogue = 80110318,
          SpeakNpcId = 93101,
          Subtitle = "Of course it's normal. I've seen my fair share of things to know why they're so afraid of me. If it weren't for my joining the Legion, I'd be the one who trembles at the sight of soldiers.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AE2"
        },
        [80110318] = {
          ContentES = "En Lago Helado… no, en toda Hyperborea siempre ha sido así. Los poderosos abusan de los débiles, los ricos maltratan a los pobres… Siempre ha sido así desde que era niña. Nada ha cambiado.",
          DialogueId = 80110318,
          GUID = "C88C3B0C",
          NextDialogue = 80110319,
          SpeakNpcId = 93101,
          Subtitle = "Icelake... No, it's the same for the whole of Hyperborea — the strong and rich walk all over the weak and poor... This has always been the way since I was a little girl. Nothing's changed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B0C"
        },
        [80110319] = {
          ContentES = "Oye, ¿sabes para qué sirve esa arma y esa máscara?",
          DialogueId = 80110319,
          GUID = "C88C3B36",
          NextDialogue = 80110320,
          SpeakNpcId = 93101,
          Subtitle = "Anyway, do you know what the gun and mask are for?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B36"
        },
        [80110320] = {
          ContentES = "De niños, Riola y yo estábamos obsesionadas con un cómic sobre Leblanc, un ladrón que robaba a los ricos malvados para dar a los pobres. Todos lo llamaban “el héroe enmascarado”.",
          DialogueId = 80110320,
          GUID = "C88C3B60",
          NextDialogue = 80110321,
          SpeakNpcId = 93101,
          Subtitle = "When we were kids, Riola and I were obsessed with this comic about Leblanc, a rogue who'd steal from wicked rich folks and give to the poor. They called him the \"Masked Hero.\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B60"
        },
        [80110321] = {
          ContentES = "Riola y yo hacíamos máscaras de papel y usábamos resorteras como pistolas. Subíamos a las murallas de Lago Helado y gritábamos en voz alta las frases que Leblanc decía en el cómic, no sentíamos ninguna vergüenza.",
          DialogueId = 80110321,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3B8A",
          NextDialogue = 80110322,
          SpeakNpcId = 93101,
          Subtitle = "We made masks from scrap cardboard and used slingshots as our guns. We'd climb the town walls of Icelake, shouting Leblanc's lines from the comics. Silly, I know, but we didn't feel a bit embarrassed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B8A"
        },
        [80110322] = {
          ContentES = "Porque en ese entonces, pensábamos que… tarde o temprano… también nos convertiríamos en “heroínas”.",
          DialogueId = 80110322,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3BB4",
          NextDialogue = 80110323,
          SpeakNpcId = 93101,
          Subtitle = "Those were the days when we felt we could... well... eventually become heroes ourselves.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BB4"
        },
        [80110323] = {
          ContentES = "Muchos años después, en una tienda de Dismania, encontré la máscara de Leblanc y una pistola de juguete que parecía tan real. Las compré sin pensarlo dos veces.",
          DialogueId = 80110323,
          GUID = "C88C3BDE",
          NextDialogue = 80110324,
          SpeakNpcId = 93101,
          Subtitle = "Years later, I spotted a beautifully crafted Leblanc mask and toy gun in a Dismania store. I couldn't resist, so I bought them.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BDE"
        },
        [80110324] = {
          ContentES = "Entonces pensaba: ‘Puede que me haya convertido en una mala que solo dispara a los de Charon, pero al menos Riola aún podría ser una ‘heroína’.",
          DialogueId = 80110324,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3C08",
          NextDialogue = 80110325,
          SpeakNpcId = 93101,
          Subtitle = "Back then, I thought, \"I might have turned into a Charon-killing baddie, but at least Riola could still be a hero...\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C08"
        },
        [80110325] = {
          ContentES = "Hasta que la vi en Lago Helado: temblaba como un ganso asustado y pasó de llamarme “Lynn” a decir “Oficial Lynn”. Ahí supe que ella, como yo, ya no podía volver atrás.",
          DialogueId = 80110325,
          GUID = "C88C3C32",
          NextDialogue = 80110326,
          SpeakNpcId = 93101,
          Subtitle = "The last time I saw her in Icelake, she trembled like a scared goose and called me \"Officer Lynn.\" That's when I knew, we'd both changed. There's no going back to the good old days.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C32"
        },
        [80110326] = {
          ContentES = "Ay, me duele la cabeza… ¡Necesito un trago!",
          DialogueId = 80110326,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3C5C",
          NextDialogue = 80110327,
          SpeakNpcId = 93101,
          Subtitle = "...Ugh, my head's hurting. Hit me with another!",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C5C"
        },
        [80110327] = {
          ContentES = "Es por todas estas malditas cosas que no quiero volver a Lago Helado. Ni siquiera quiero ver a mis hermanos. Con saber que están bien… me basta.",
          DialogueId = 80110327,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3C86",
          NextOptions = {
            [1] = 801103271
          },
          SpeakNpcId = 93101,
          Subtitle = "These are the reasons why I avoid being back at Icelake. I don't even want to meet my own siblings. Just seeing them from afar, knowing they're alive and well, that's enough for me.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C86"
        },
        [80110328] = {
          ContentES = "No, al contrario. En las cartas que me escriben, siempre me dicen que me extrañan mucho y que vaya a verlos más seguido.",
          DialogueId = 80110328,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C3CB0",
          NextDialogue = 80110329,
          SpeakNpcId = 93101,
          Subtitle = "No, quite the opposite. They write all the time, saying how much they miss me and wish I'd visit.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CB0"
        },
        [80110329] = {
          ContentES = "Pero, aunque los vea, ¿qué se supone que les diga? ¿Que vi otro experimento raro en la Academia Spathatoi? ¿O que arresté a unos cuantos Charons?...",
          DialogueId = 80110329,
          GUID = "C88C3CDA",
          NextDialogue = 80110330,
          SpeakNpcId = 93101,
          Subtitle = "But what could I tell them? About the latest horrors I've seen at the Academy? Or how many Charon prisoners I took?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CDA"
        },
        [80110330] = {
          ContentES = "En fin, da igual. Cada uno tiene sus propias cargas. Todo esto es tan malditamente normal hoy en día.",
          DialogueId = 80110330,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3D04",
          NextOptions = {
            [1] = 801103301
          },
          SpeakNpcId = 93101,
          Subtitle = "...Forget it. Everyone's got their own burdens. It's all so damn normal these days.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D04"
        },
        [80110331] = {
          ContentES = "El mundo debería ser un lugar donde, si quieres volver a casa, simplemente puedas hacerlo… O mejor dicho, nuestra generación debería hacer que así sea.",
          DialogueId = 80110331,
          GUID = "C88C3D2E",
          NextDialogue = 80110332,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "This should be a world where you can return home whenever you want... Perhaps our generation should try to make it one.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D2E"
        },
        [80110332] = {
          ContentES = "Solo alguien de fuera como tú pensaría que esto es raro… y que realmente se puede cambiar.",
          DialogueId = 80110332,
          GUID = "C88C3D58",
          NextDialogue = 80110333,
          SpeakNpcId = 93101,
          Subtitle = "Only outsiders like you would think this is weird and believe this can change.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D58"
        },
        [80110333] = {
          ContentES = "¿Piensas que algún día los charons podrán convivir en paz con los humanos, sin ser discriminados por unos cuernos raros, o por su columna vertebral extraña o la magia rara que practican?",
          DialogueId = 80110333,
          GUID = "C88C3D82",
          NextDialogue = 80110334,
          SpeakNpcId = 93101,
          Subtitle = "Perhaps you also believe a day will come when Charons and Solas can live together in peace, and that people won't be judged for their strange-looking horns and spines, and the weird magic in their veins.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D82"
        },
        [80110334] = {
          ContentES = "¿Quién sabe?",
          DialogueId = 80110334,
          GUID = "C88C3DAC",
          NextDialogue = 80110335,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "That could happen.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DAC"
        },
        [80110335] = {
          ContentES = "Aunque no puedas evitar que caiga nieve en Lago Helado, al menos sí puedes juntarla y hacer un bonito muñeco de nieve con ella, ¿no?",
          DialogueId = 80110335,
          GUID = "C88C3DD6",
          NextDialogue = 80110336,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Even if you can't stop the snow in Icelake, you can at least shovel it away and make snowmen out of it, right?",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DD6"
        },
        [80110336] = {
          ContentES = "Al menos deberías acercarte a tu amiga y decirle que aún recuerdas lo que soñaban cuando eran niñas… incluso si ahora es imposible cumplirlo. Deberías visitar a tu familia y decirles que los extrañas, sin importar en quién te hayas convertido, esa parte de ti nunca cambiará.",
          DialogueId = 80110336,
          GUID = "C88C3E00",
          NextDialogue = 80110337,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You can at least go to your friend and tell her you remember your childhood dreams, even if they're broken now. You should be able to knock on the door of your family home and tell your folks that you'll always miss them no matter who you've become. That part of you never changes.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E00"
        },
        [80110337] = {
          ContentES = "Jaja, la verdad, me gusta bastante tu forma de pensar. Aunque sigo creyendo que es un poco idealista, pero es mucho mejor que asumir esa tontería de que “el mundo es así y nadie puede cambiarlo”.",
          DialogueId = 80110337,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E2A",
          NextDialogue = 80110338,
          SpeakNpcId = 93101,
          Subtitle = "...Hah. To be honest, I like your way of thinking, even if it's a bit naive for my taste. It's way better than the usual crap like \"Oh, that's the way it is, nobody can change the world.\"",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E2A"
        },
        [80110338] = {
          ContentES = "Al menos, al escucharte, siento que hasta el viento frío de Lago Helado se vuelve un poco más cálido. Mmm… dame otro trago.",
          DialogueId = 80110338,
          FacialId = {
            [1] = "93101:Happy02"
          },
          GUID = "C88C3E54",
          NextDialogue = 80110339,
          SpeakNpcId = 93101,
          Subtitle = "And your words actually made this Icelake breeze a bit warmer, I must say. Hmm... Pour me another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E54"
        },
        [80110339] = {
          ContentES = "Veamos hasta dónde puedes llegar. Dices que todavía sueñas con cambiar el mundo, pues yo quiero ver si este mundo puede ser cambiado por {性别:un ingenuo|una ingenua} como tú.",
          DialogueId = 80110339,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E7E",
          NextDialogue = 80110340,
          SpeakNpcId = 93101,
          Subtitle = "Let's see how far you can take this dream of changing the world. I'm curious if a naive fool can actually make a difference, even a little.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E7E"
        },
        [80110340] = {
          ContentES = "Si algún día necesitas ayuda, puedes venir a buscarme… claro, excepto por asuntos que tengan que ver con la Legión. Solo hoy no tengo tiempo, debo hacer otras cosas.",
          DialogueId = 80110340,
          GUID = "C88C3EA8",
          NextDialogue = 80110341,
          SpeakNpcId = 93101,
          Subtitle = "And if you ever need help, and I'm free, just ask — as long as it's nothing against the Legion. But not today — I've just changed my mind about something and will be busy later.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3EA8"
        },
        [80110341] = {
          ContentES = "El encargo queda cancelado. Devuélveme la máscara y el arma de juguete.",
          DialogueId = 80110341,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3ED2",
          SpeakNpcId = 93101,
          Subtitle = "I'm cancelling the commission. Now, gimme back my mask and gun.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3ED2"
        },
        [80120000] = {
          ContentES = "Ah, eso es la vida: un sillón cómodo, una bebida, unos aperitivos, una chimenea encendida y tu compañía. Todo es tan acogedor...",
          DialogueId = 80120000,
          GUID = "C8926F80",
          Subtitle = "Ahh, this is the life — a comfy chair, a drink, some snacks, a warm fireplace, and your company. All nice and cosy..."
        },
        [80120100] = {
          Camera = "254.617188,-63.0,110.607666,0.0,0.0,155.600769,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Los muebles de dentro? Los traje hace treinta años de la capital imperial, Dismania. La rareza de los materiales y la calidad del trabajo superan cualquier cosa que puedan imaginar.",
          DialogueId = 80120100,
          FinalCamera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8927FE8",
          NextDialogue = 80120101,
          SpeakNpcId = 790018,
          Subtitle = "The pieces of furniture inside? I brought them from the Imperial capital of Dismania thirty years ago. The rarity of the materials and the craftsmanship are beyond your wildest dreams.",
          TalkActionId = {
            [1] = "790018:Explain01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8927FE8"
        },
        [80120101] = {
          Camera = "-270.549316,-21.425171,153.719727,0.000001,-9.200162,19.797686,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Está seguro de que quiere que nos llevemos esos artículos tan valiosos, señor? En caso de que cambie de opinión, no habría manera de que yo…",
          DialogueId = 80120101,
          FacialId = {
            [1] = "790019:Iyada01"
          },
          GUID = "C8928012",
          NextDialogue = 80120102,
          SpeakNpcId = 790019,
          Subtitle = "Um, are you sure you want me to handle these valuable items, sir? If you change your mind all of a sudden, there's no way for a scavenger like me to...",
          TalkActionId = {
            [1] = "790019:Explain02_Start",
            [2] = "790018:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928012"
        },
        [80120102] = {
          Camera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Me has hecho la pregunta varias veces y he repetido mi respuesta: esos muebles, ustedes pueden disponer de estos muebles como deseen. Mis verdaderas riquezas son mis partituras, bien a salvo donde deben estar.",
          DialogueId = 80120102,
          GUID = "C892803C",
          NextDialogue = 80120103,
          SpeakNpcId = 790018,
          Subtitle = "You've already asked multiple times, and my answer remains: yes, these pieces are yours to handle. My true treasures are my music scores, and they have been well secured where they belong.",
          TalkActionId = {
            [1] = "790019:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892803C"
        },
        [80120103] = {
          Camera = "-91.792969,-17.010254,119.101807,0.000001,-2.600096,26.798737,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Está bien, entonces solo para confirmar: en el estudio encontramos un montón de hojas… Al revisarlas, me di cuenta de que eran partituras.",
          DialogueId = 80120103,
          GUID = "C8928066",
          NextDialogue = 80120104,
          SpeakNpcId = 790019,
          Subtitle = "Well then, just to double-check before we start: about this huge pile of sheets — I collected them from the study. They look like music scores too...",
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928066"
        },
        [80120104] = {
          Camera = "188.380859,5.304199,118.568604,0.000005,0.0,165.387512,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Quémalas.",
          DialogueId = 80120104,
          GUID = "C8928090",
          NextDialogue = 80120105,
          SpeakNpcId = 790018,
          Subtitle = "Just burn them.",
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928090"
        },
        [80120105] = {
          Camera = "-194.875488,-9.761597,155.702393,0.000033,-32.798512,130.396423,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "No son más que borradores, desechos inútiles. Busca a alguien que tenga frío, que se sirva de ellos para calentarse.",
          DialogueId = 80120105,
          FinalCamera = "-183.950195,-22.665466,181.275146,0.000027,-35.598583,129.996002,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89280BA",
          NextDialogue = 80120106,
          SpeakNpcId = 790018,
          Subtitle = "They're nothing but useless drafts, rubbish. Give them to someone struggling to stay warm to burn.",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280BA"
        },
        [80120106] = {
          Camera = "7.850098,-71.797974,9.991455,0.000032,31.599302,132.795364,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es ridículo, si esas hojas de verdad tuvieran valor, ya estarían guardadas, ¿no? No hace falta que me hagas preguntas inútiles.",
          DialogueId = 80120106,
          GUID = "C89280E4",
          NextDialogue = 80120107,
          SpeakNpcId = 790018,
          Subtitle = "How laughable — if they were important to me, before you waste my time with these stupid questions, don't you think I'd have properly saved them already?",
          TalkActionId = {
            [1] = "790018:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280E4"
        },
        [80120107] = {
          Camera = "-65.708008,-20.782593,149.700928,0.000017,-11.799984,31.404984,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 80120107,
          FacialId = {
            [1] = "790019:Sad01"
          },
          GUID = "C892810E",
          LookAt = {
            [1] = "790019:p(P33010101)"
          },
          NextDialogue = 80120108,
          SpeakNpcId = 790019,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C892810E"
        },
        [80120108] = {
          Camera = "10.617676,-39.324158,127.336182,0.000074,1.400339,142.991364,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "A lo lejos vuelve a sonar el silbato del tren, como si estuviera apresurando al excéntrico músico a regresar a Dismania.",
          DialogueId = 80120108,
          GUID = "C8928138",
          LookAt = {
            [1] = "790018:p(P33010102)"
          },
          NextDialogue = 80120109,
          Subtitle = "The distant sound of a train whistle echoes, as if hurrying the eccentric musician on his journey back to Dismania.",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928138"
        },
        [80120109] = {
          Camera = "-272.822754,-25.003113,137.138184,0.0,-3.399993,22.39842,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es hora de irme. Nunca más nos volveremos a ver, Charon.",
          DialogueId = 80120109,
          GUID = "C8928162",
          LookAt = {
            [1] = "790019:n(790018)"
          },
          NextDialogue = 80120110,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790018:n(790018)"}},
MoveTo{ActorId{790018},MoveSpeed{75},TargetPoint{"MovePoint_33010102"}}
}]],
          SpeakNpcId = 790018,
          Subtitle = "It's time I left. See you never, Charon.",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928162"
        },
        [80120110] = {
          Camera = "41.422852,127.761597,116.559082,0.000003,-0.200043,-76.786568,25.0,73.935852,false,Manual,2.8",
          ContentES = "...",
          DialogueId = 80120110,
          FacialId = {
            [1] = "790019:Sad02"
          },
          FinalCamera = "36.748535,126.659424,116.559082,0.000003,-0.200043,-76.586166,25.0,235.730316,false,Manual,3.0",
          GUID = "C892818C",
          LookAt = {
            [1] = "790008:n(790019)",
            [2] = "790019:p(P33010101)"
          },
          NextOptions = {
            [1] = 801201101,
            [2] = 801201102
          },
          Scripts = "MoveTo{ActorId{790008},MoveSpeed{75},TargetPoint{\"MovePoint_33010101\"}}",
          SpeakNpcId = 790019,
          Subtitle = "...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Maer/001/C892818C"
        },
        [80120111] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentES = "Ah, eres tú. Espera, ¡dame un minuto!",
          DialogueId = 80120111,
          GUID = "C89281B6",
          NextDialogue = 80120112,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790019:n(790008)"}},
TurnTo{TurnToDescription{"790019:n(790008)"}},
PlayAnimation{ActorId{790019},AnimationId{"Agree"},Duration{1}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Oh, it's you. Excuse me for a minute!",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89281B6"
        },
        [80120112] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentES = "(Margie respira profundamente y comienza a murmurar para sí misma, pero su voz se escucha aún más clara.)",
          DialogueId = 80120112,
          GUID = "C89281E0",
          NextDialogue = 80120113,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790019:n(790019)"}},
TurnTo{TurnToDescription{"790019:p(180)"}}
}]],
          Subtitle = "(Margie takes a deep breath and begins to murmur to herself under her breath, though you can still hear her, even more clearly.)",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89281E0"
        },
        [80120113] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentES = "La vida es un vertedero, lleno de basura. Ellos no se mueven, pero yo puedo correr, para mantener mi vida a salvo...",
          DialogueId = 80120113,
          GUID = "C892820A",
          NextDialogue = 80120114,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Angry01_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Angry01_End"},Duration{1},_delay{2},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Life's a dump, full of junk. They can't move but I can run, to keep my life safe and sound...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C892820A"
        },
        [80120114] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentES = "¿Los gritos? No hay que preocuparse, es solo un perrito enfadado. Pelear con él es perder el tiempo, ve mejor a tomar el sol, tranquila, al sol de un momento.",
          DialogueId = 80120114,
          GUID = "C8928234",
          NextDialogue = 80120115,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Sigh_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Sigh_End"},Duration{1},_delay{2},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Don't get pissed, the jerks would win. Save your strength, unclench your fist, go soak up the sun with a grin...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928234"
        },
        [80120115] = {
          Camera = "32.413086,166.017761,96.0354,0.000066,5.199563,-79.384827,60.0,248.284149,false,Manual,5.0",
          ContentES = "Huff.. Sonríe… relájate...",
          DialogueId = 80120115,
          GUID = "C892825E",
          NextDialogue = 80120116,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790008},AnimationId{"Explain02_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790008},AnimationId{"Explain02_End"},Duration{1},_delay{3},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Whew — Go to your happy place. Go to your happy place...",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892825E"
        },
        [80120116] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentES = "Eso es... ¡ya estoy mejor! No son más que ladridos. Después de tanto tiempo en Lago Helado, ya estoy acostumbrada.",
          DialogueId = 80120116,
          FacialId = {
            [1] = "790019:Unhappy01"
          },
          GUID = "C8928288",
          NextOptions = {
            [1] = 801201161
          },
          SpeakNpcId = 790019,
          Subtitle = "All set... I'm all good now! Just some barking noise. After all these years in Icelake, I'm so used to it.",
          TurnTo = {
            [1] = "790019:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928288"
        },
        [80120117] = {
          ContentES = "¿Perrito? ¿Dónde? ¡Quiero acariciarlo…! Ah, espera, ¿te refieres al señor Kossak?",
          DialogueId = 80120117,
          GUID = "C89282B2",
          NextDialogue = 80120118,
          Scripts = [[
SEQ{
PlayFacial{ActorId{790019},FacialId{"Smile02"}},
PlayFacial{_delay{4},ActorId{790019},FacialId{"Shock01"}},
}]],
          SpeakNpcId = 790019,
          Subtitle = "Doggie? Where? I wanna pet it... Oh, you mean Mr Kossak.",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89282B2"
        },
        [80120118] = {
          ContentES = "Escuché que era un gran compositor de Dismania, dicen que fue quien escribió el «Himno al Emperador Julius», o algo así. Y que impresionó a Su Majestad, los soldados lo cantan todos los años en el Día Nacional.",
          DialogueId = 80120118,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89282DC",
          NextDialogue = 80120119,
          SpeakNpcId = 790019,
          Subtitle = "Well, I heard he's a famous composer from Dismania. That \"Julius Anthem\" he wrote — don't know if I got the name right — impressed even the Emperor. Those soldiers sing it every year on National Day.",
          TalkActionId = {
            [1] = "790019:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89282DC"
        },
        [80120119] = {
          Camera = "26.599121,-60.766174,127.509766,0.00013,-3.899717,69.789467,35.000008,130.711365,false,Manual,4.0",
          ContentES = "Pero no sé por qué, en el apogeo de su carrera, fue despedido de la capital. Desde entonces, toca su viejo gong en el Teatro Galea. Ya van treinta años.",
          DialogueId = 80120119,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          FinalCamera = "26.599121,-60.766174,127.509766,0.00013,-3.899717,69.789467,37.0,130.711365,false,Manual,4.0",
          GUID = "C8928306",
          NextDialogue = 80120120,
          SpeakNpcId = 790019,
          Subtitle = "But for some reason, he was thrown out of the capital at the height of his fame. Ended up in Icelake, banging on that beat-up gong at Galea Theatre for thirty years.",
          TalkActionId = {
            [1] = "790019:Disagree"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928306"
        },
        [80120120] = {
          Camera = "25.643555,148.86615,117.203857,0.000134,-1.299553,-75.005913,35.0,286.089264,false,Manual,4.0",
          ContentES = "Se dice que recientemente escribió una sinfonía llamada «La gloria de Hyperborea», que a los grandes jefes les gustó y lo hicieron regresar.",
          DialogueId = 80120120,
          GUID = "C8928330",
          NextDialogue = 80120121,
          SpeakNpcId = 790019,
          Subtitle = "But I heard he recently wrote some symphonic works called \"The Glory of Hyperborea,\" and some big shots in the capital liked them enough to bring him back.",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928330"
        },
        [80120121] = {
          Camera = "13.561035,-82.322632,125.807861,0.000016,-12.60006,31.003906,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Todas las pertenencias de su casa se las dejó a Camilla para que se encargase, y ella me pasó ese encargo. Al principio pensé que sería una sorpresa agradable, pero resultó ser que el cliente era todo un personaje... Qué mala suerte.",
          DialogueId = 80120121,
          FacialId = {
            [1] = "790019:Sad02"
          },
          FinalCamera = "3.181641,-88.561157,128.515381,0.000017,-12.60006,31.004112,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C892835A",
          NextOptions = {
            [1] = 801201211
          },
          Scripts = [[
PARA{
PlayAnimation{ActorId{790019},AnimationId{"Explain02_End"},Duration{1},_click{false}},
SEQ{
PlayAnimation{_delay{8},ActorId{790019},AnimationId{"ScratchHead_Start"},Duration{1},_click{false}},
PlayAnimation{_delay{3},ActorId{790019},AnimationId{"ScratchHead_End"},Duration{1},_click{false}},
},
SEQ{
CameraMoveTo{_delay{7.6},TargetPosition{"32.449707,-25.237549,113.582275,0.000057,3.999902,67.00164,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"33.751953,-22.16748,113.815186,0.000057,3.999902,67.001724,35.0,100000.0,false,DoNotOverride,2.8"},duration{7}},
},
}]],
          SpeakNpcId = 790019,
          Subtitle = "He turned to Camilla to deal with all the stuff he left behind, and Camilla passed the big job on to me. I thought it was a stroke of luck at first, but it turned out the client was quite the character. Tough break...",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C892835A"
        },
        [80120122] = {
          Camera = "13.058594,-189.487427,130.297607,0.000067,-5.400023,73.400612,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Así es, me dedico a rebuscar entre la basura con la esperanza de encontrar algo que se pueda revender.",
          DialogueId = 80120122,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "10.127441,-188.613403,130.297607,0.000069,-5.400023,72.800484,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928384",
          NextDialogue = 80120123,
          SpeakNpcId = 790019,
          Subtitle = "Uh-huh. Normally I'm just hustling between rubbish bins trying to collect anything useful to resell.",
          TalkActionId = {
            [1] = "790019:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928384"
        },
        [80120123] = {
          Camera = "-379.716797,343.199707,394.461182,0.000096,-29.400166,-38.797962,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Y no es común que un rico deje tantas cosas de valor y se vaya de Lago Helado, con todo lo que dejó, se… se podrían llenar, exagerando un poco, ¡unos cincuenta contenedores de basura!",
          DialogueId = 80120123,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-379.716797,343.199707,372.476074,0.000104,-27.00005,-39.19701,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89283AE",
          NextDialogue = 80120124,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{790019},AnimationId{"DisagreeHead"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_Start"},Duration{3},_delay{2},_click{false}},
PlayAnimation{_delay{3},ActorId{790019},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "It's not often you find a rich guy who leaves behind a houseful of stuff without a second thought. His leftover belongings are worth a fortune — okay, maybe not a hundred bins worth, but definitely fifty at least!",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283AE"
        },
        [80120124] = {
          Camera = "-46.604492,-258.057495,81.282959,0.000152,2.599918,66.012314,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Esos muebles antiguos eran de madera de primera calidad. Se podrían convertir en camas o mesas. También hablé con el sastre y me dijo que con las cortinas, manteles y alfombras se podría confeccionar ropa, claro que primero se deben lavar muy bien.",
          DialogueId = 80120124,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C89283D8",
          NextDialogue = 80120125,
          SpeakNpcId = 790019,
          Subtitle = "Take those antique furniture pieces — the wood is top quality. You could turn them into beds or tables. I also checked with the tailor — those curtains, tablecloths, and rugs can be made into clothes after a few washes.",
          TalkActionId = {
            [1] = "790019:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283D8"
        },
        [80120125] = {
          Camera = "3.307129,189.679504,120.907227,0.0,-2.599973,-71.797028,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Unas cuantas familias de los barrios bajos podrán dormir y vestirse mejor, y yo puedo sacar un buen dinerito. Aunque ese compositor era bastante gruñón, fue bastante generoso con el pago, jejeje…",
          DialogueId = 80120125,
          GUID = "C8928402",
          NextDialogue = 80120126,
          SpeakNpcId = 790019,
          Subtitle = "A few more families in the slums will get to sleep and dress better, and I'll make a tiny fortune. Plus, even though that musician was quite mean, he was pretty generous with the pay, hehe...",
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = "790019:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928402"
        },
        [80120126] = {
          Camera = "30.832031,-69.490662,105.26709,0.000002,4.999924,73.193848,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es curioso… Hace un momento estaba muy enojada, como si tuviera el corazón en llamas. ¡Pero ahora me siento más relajada!",
          DialogueId = 80120126,
          FacialId = {
            [1] = "790019:Happy01"
          },
          GUID = "C892842C",
          NextDialogue = 80120127,
          SpeakNpcId = 790019,
          Subtitle = "Can you believe it? I was totally upset just a moment ago, but now I'm not mad at all!",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892842C"
        },
        [80120127] = {
          Camera = "-37.370605,-328.404663,168.14209,0.000007,-11.000026,70.593628,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "De todas maneras, el señor Kossak ya está en Dismania y la gente de los barrios pobres podrá obtener algunos artículos de calidad. Y aunque me estuvo regañando un poco, una vez que empiece a trabajar, ¡lo olvidaré por completo!",
          DialogueId = 80120127,
          FacialId = {
            [1] = "790019:Smile01"
          },
          FinalCamera = "-37.370605,-328.404663,152.396973,0.000009,-9.199978,70.193542,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928456",
          NextOptions = {
            [1] = 801201271,
            [2] = 801201272
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Explain02_End"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"DisagreeHead"},Duration{3},_delay{4},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Anyway, Kossak's off to Dismania, and the folks in the slums get some good supplies. It doesn't matter that I got a little scolding — once I start to get busy, I'll forget all about it!",
          ToFinalCameraBlendTime = 11.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928456"
        },
        [80120128] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Claro que sí, estaría estupendo! Sacar todos esos armarios yo sola me tomaría mucho tiempo. Mientras los movemos, si ves algo que te guste, siéntete libre de tomarlo.",
          DialogueId = 80120128,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C8928480",
          SpeakNpcId = 790019,
          Subtitle = "Oh, that would be great! It's a bit of a chore hauling out his cabinets on my own. Feel free to pick anything you like while we're at it.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928480"
        },
        [80120129] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Claro! Considéralo como un regalo de agradecimiento por aguantar mis quejas. Vamos, ayúdame a recoger todo, y si ves algo que te guste, siéntete libre de tomarlo.",
          DialogueId = 80120129,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C89284AA",
          SpeakNpcId = 790019,
          Subtitle = "Sure thing! Consider it a thank you for putting up with my grumble. Come on, help me out here. You can pick whatever catches your eye.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284AA"
        },
        [80120130] = {
          ContentES = "Pasaste un día productivo con Margie… aunque a la hora de dormir, tus brazos estaban muy adoloridos.",
          DialogueId = 80120130,
          GUID = "C89284D4",
          Subtitle = "You spent a productive day with Margie... Though your arms were sore from all the lifting by bedtime...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284D4"
        },
        [80120201] = {
          Camera = "1333.655273,158.495117,593.059387,0.000084,-23.399462,-148.791443,45.0,1393.645752,false,Manual,2.8",
          ContentES = "Margie se ocupó de los objetos que dejó el gran músico Kossak y también tomó temporalmente una de las habitaciones del Santuario. A menudo se escuchaban ruidos metálicos desde la habitación, seguramente estaba convirtiendo la basura en tesoro.",
          DialogueId = 80120201,
          FinalCamera = "1329.534668,166.603516,574.799133,0.000082,-22.599415,-147.989853,45.0,1393.645752,false,Manual,2.8",
          GUID = "C892907A",
          Scripts = [[
SEQ{
CameraMoveTo{TargetPosition{"-536.0,361.0,216.0,0.000089,-19.999989,-58.799721,35.0,100000.0,false,DoNotOverride,2.8"},duration{3}},
CameraMoveTo{TargetPosition{"-180.185974,-395.118164,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-180.185974,-405.0,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8"},duration{3}},
}]],
          Subtitle = "Margie has taken up a room at Sanctuary to sort through the items left behind by the famous musician Kossak. The constant clatters and clanking from the room suggest she's busy turning waste into treasure.",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892907A"
        },
        [80120202] = {
          ContentES = "Decides a echar un vistazo…",
          DialogueId = 80120202,
          GUID = "C89290A4",
          Subtitle = "You decide to check on her...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290A4"
        },
        [80120203] = {
          Camera = "-153.358521,286.205566,141.870239,0.000003,-7.000151,-147.997467,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Oh? {nickname}, ¡eres tú! ¡Ven rápido, ven rápido! Justo acabo de encontrar algo extraño.",
          DialogueId = 80120203,
          FacialId = {
            [1] = "790019:Smile01"
          },
          GUID = "C89290CE",
          NextDialogue = 80120204,
          SpeakNpcId = 790019,
          Subtitle = "Oh! , it's you! Come here — I've just stumbled upon something strange!",
          TurnTo = {
            [1] = "790019:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290CE"
        },
        [80120204] = {
          Camera = "-225.281067,222.903564,116.151337,0.000004,-0.80002,-144.597412,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Encontré esta tabla cuando desarmaba un armario. ¿Y por qué es extraña…? dale un golpe y verás.",
          DialogueId = 80120204,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-234.476318,216.367676,116.006004,0.000004,-0.600005,-144.597412,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89290F8",
          NextOptions = {
            [1] = 801202041,
            [2] = 801202042
          },
          SpeakNpcId = 790019,
          Subtitle = "Found this wooden plank while I was taking apart a cabinet. Now, listen to how it sounds when I tap it.",
          TalkActionId = {
            [1] = "790019:Give"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290F8"
        },
        [80120205] = {
          Camera = "-284.374023,129.285156,139.56041,0.000053,-11.399346,-170.182327,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Sí, al golpearla suena como si estuviera hueca. Seguro que hay algo escondido dentro.",
          DialogueId = 80120205,
          FacialId = {
            [1] = "790019:Smile02"
          },
          GUID = "C8929122",
          NextDialogue = 80120207,
          SpeakNpcId = 790019,
          Subtitle = "Exactly! The sound isn't right. There's definitely something stashed inside.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929122"
        },
        [80120206] = {
          Camera = "-284.374023,129.285156,139.56041,0.000053,-11.399346,-170.182327,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Exacto. El señor Kossak decía que sus muebles estaban hechos de una madera fina, ya no recuerdo el nombre. Pero lo importante es… que está hueca por dentro.",
          DialogueId = 80120206,
          FacialId = {
            [1] = "790019:Smile02"
          },
          GUID = "C892914C",
          NextDialogue = 80120207,
          SpeakNpcId = 790019,
          Subtitle = "Oh, yeah. Kossak bragged that all his furniture was made from some fancy wood, though I can't remember the name. But what I'm trying to tell you is — it's hollow!",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892914C"
        },
        [80120207] = {
          Camera = "232.653351,361.8125,281.633331,0.000094,-18.999201,-161.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mi instinto de detective me dice que esta madera tiene mucho que contar, y no sería raro, desde que empecé a buscar tesoros en los basureros he encontrado todo tipo de secretos, incluso los que no quiero descubrir.",
          DialogueId = 80120207,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C8929176",
          NextDialogue = 80120208,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Agree"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_Start"},Duration{4},_delay{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "My detective instincts are telling me this piece of wood must have a breathtaking backstory! Ever since I started treasure hunting around the city's rubbish bins, secrets keep finding their way to me, whether I want them or not.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929176"
        },
        [80120208] = {
          Camera = "-233.092163,217.391113,116.084183,0.0,-0.600005,-144.397369,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Por ejemplo, si hay vidrios rotos, generalmente significa que hubo una pelea en la casa. Si hay un montón de ropa vieja, seguro que esa familia recibió un buen dinero. Y ni hablar de las cartas de amor destrozadas que he encontrado…",
          DialogueId = 80120208,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89291A0",
          NextDialogue = 80120209,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Explain01_Start"},Duration{3},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Explain01_End"},Duration{1},_click{false}},
PARA{
PlayFacial{_delay{6.5},ActorId{790008},FacialId{"Happy02"}},
LookAt{LookAtDescription{"790019:p(P33010202)"}},
}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Like, if there's broken glass in the bin, it usually means the household just had a fight. If it's a huge bunch of old clothes, then they must've come into cash all of a sudden. And don't get me started on those torn-up love letters I found...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291A0"
        },
        [80120209] = {
          Camera = "96.989166,365.946533,258.328094,0.000015,-19.39859,-156.192947,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "En fin, volviendo a esta tabla hueca. La habitación estaba muy oscura, así que la traje para acá. Estaba a punto de abrirla cuando llegaste. Seguro hay algo interesante escondido. Vamos a ver…",
          DialogueId = 80120209,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "135.622986,382.351562,322.567413,0.000009,-24.598625,-156.393433,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89291CA",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120290,
          SpeakNpcId = 790019,
          Subtitle = "Anyway, back to this hollow plank. It was too dark in the room, so I brought it out here. I was just about to crack it open when you showed up. There's got to be something interesting hidden inside. Let's see...",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291CA"
        },
        [80120210] = {
          Camera = "-181.880615,263.347656,136.257751,0.000037,-5.797976,-149.392807,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Otra partitura? Kossak dijo que todas sus partituras valiosas estaban guardadas, pero si esta no le importaba, ¿por qué se tomó la molestia de esconderla de esa forma?",
          DialogueId = 80120210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_Read_02.T_Read_02'}",
          FacialId = {
            [1] = "790019:Shock01"
          },
          GUID = "C89291F4",
          NextDialogue = 80120211,
          SpeakNpcId = 790019,
          Subtitle = "...Another music score? Kossak said he'd take all the valuable ones with him. But if this one wasn't important to him, why did he go through the trouble of hiding it so carefully?",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291F4"
        },
        [80120211] = {
          Camera = "-288.548035,170.670166,120.789764,0.000075,0.402121,-147.390503,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Déjame ver qué es lo que dice… ¿«El demonio se liberó de las cadenas»? Nunca había oído esta pieza…",
          DialogueId = 80120211,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C892921E",
          NextOptions = {
            [1] = 801202111
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{790019},AnimationId{\"Think_End\"},Duration{1},_click{false}},",
          SpeakNpcId = 790019,
          Subtitle = "Lemme see what it's about... \"Demons Broken Loose\"? Never heard of this piece before...",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892921E"
        },
        [80120212] = {
          Camera = "-409.604431,-6.535156,126.660339,0.000048,-2.997824,66.607025,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "“Hola, Kossak del futuro. Espero que estés bien y feliz con tu vida ahora. Quiero decirte que estamos a punto de hacer algo muy arriesgado:”",
          DialogueId = 80120212,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-407.011719,-7.655762,126.660339,0.000048,-2.997797,66.607208,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929248",
          LookAt = {
            [1] = "790019:p(P33010202)"
          },
          NextDialogue = 80120213,
          SpeakNpcId = 790019,
          Subtitle = "\"Hello there, future me. How are you? Are you happy with your life now? Just a heads up — I'm about to take a risky leap:\"",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929248"
        },
        [80120213] = {
          Camera = "-144.685608,266.765869,90.548981,0.000028,3.199581,-150.191788,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "“Estoy componiendo un tema sobre la comunidad más olvidada de nuestra nación: los Charons. Parece una gran idea, ¿no crees?”",
          DialogueId = 80120213,
          FacialId = {
            [1] = "790019:Shock01"
          },
          FinalCamera = "-143.404663,264.529785,90.548981,0.000028,3.199581,-150.191788,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929272",
          LookAt = {
            [1] = "790019:p(P33010202)"
          },
          NextDialogue = 80120214,
          SpeakNpcId = 790019,
          Subtitle = "\"I'm writing a composition about our land's most overlooked community — Charons. Sounds like a great idea, doesn't it?\"",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929272"
        },
        [80120214] = {
          Camera = "117.682922,273.904541,278.035675,0.000035,-23.000122,-167.605408,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "“No sé qué me brindará esto una vez que lo publique, espero que fama y reconocimiento, pero sobre todo espero que la gente logre sentir algo de simpatía por el pueblo de los Charons. Aunque lo más probable es que los puristas me regañen por 'macillar el arte'.”",
          DialogueId = 80120214,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "149.964203,280.998291,292.065369,0.000035,-23.000122,-167.605408,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C892929C",
          NextDialogue = 80120215,
          SpeakNpcId = 790019,
          Subtitle = "\"I don't know what will come of it after it's published. Hopefully, it'll earn me some recognition and maybe even get people to sympathize with the Charon community. But it's more likely that the old guard will scold me for 'sullying music.'\"",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892929C"
        },
        [80120215] = {
          Camera = "401.697601,87.518555,94.828476,0.000034,-2.599092,173.794434,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "“Tal vez me arrepienta, pero en este momento estoy convencido de que estoy haciendo lo correcto.”",
          DialogueId = 80120215,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "401.697601,87.518555,124.666946,0.000034,-4.599217,173.394348,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89292C6",
          NextDialogue = 80120216,
          SpeakNpcId = 790019,
          Subtitle = "\"I might regret this decision someday, but at the moment, I believe in what I'm doing.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89292C6"
        },
        [80120216] = {
          Camera = "787.620972,-53.718506,1202.445679,0.000004,-45.999557,170.397659,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "“Así que, dejo una copia aquí, en caso de que tú, o esos puristas conservadores, llegaran a destruir mi obra a cenizas.”",
          DialogueId = 80120216,
          FinalCamera = "697.515381,213.27832,1078.197266,0.000005,-44.799149,-177.402649,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89292F0",
          NextDialogue = 80120217,
          SpeakNpcId = 790019,
          Subtitle = "\"So, I'm leaving a copy here, just in case the cold shoulder — or those old guard bigots — end up destroying my hard work.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89292F0"
        },
        [80120217] = {
          Camera = "1272.104248,1465.506348,636.589355,0.000045,-20.798307,-178.202515,60.0,1238.551392,false,Manual,2.8",
          ContentES = "“Espero que cuando leas esta carta, estés escuchando a los Charons cantando esta canción fuera de tu ventana, y que estés sonriéndole a la vida, como lo hago yo ahora.”",
          DialogueId = 80120217,
          FinalCamera = "1271.768799,1475.04248,636.589355,0.000045,-20.598291,-178.002518,60.0,1238.551392,false,Manual,2.8",
          GUID = "C892931A",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120218,
          SpeakNpcId = 790019,
          Subtitle = "\"I really hope that by the time you read this letter, you'll hear Charons singing this song outside your window. And I hope you'll be able to smile at life, like I'm doing right now.\"",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892931A"
        },
        [80120218] = {
          Camera = "-393.488953,121.270996,118.823044,0.000066,3.202293,41.604927,60.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "...",
          DialogueId = 80120218,
          FacialId = {
            [1] = "790019:Sad01"
          },
          GUID = "C8929344",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextOptions = {
            [1] = 801202181,
            [2] = 801202182
          },
          SpeakNpcId = 790019,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929344"
        },
        [80120219] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Vaya, este Kossak del pasado… parece que sí era buena persona.",
          DialogueId = 80120219,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892936E",
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          Subtitle = "That Kossak... he was really a decent fellow back then.",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892936E"
        },
        [80120220] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Mmm… Sí, es posible. Quizá realmente no le daba importancia a sus otras partituras, porque ya estaba totalmente seguro de que su tesoro más grande “estaba en el lugar que le correspondía…”",
          DialogueId = 80120220,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C8929398",
          LookAt = {
            [1] = "790019:p(P33010201)",
            [2] = "790008:p(P33010201)"
          },
          NextDialogue = 80120221,
          SpeakNpcId = 790019,
          Subtitle = "Hmm... You might be right. He didn't care about most of his music scores, but he was awfully sure that his most important pieces had been \"well secured where they belong\"...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929398"
        },
        [80120221] = {
          Camera = "-440.217041,86.593506,117.899193,0.000059,-0.799351,34.609612,35.0,234.284531,false,Manual,5.0",
          ContentES = "Así que, tal vez para él, esa era la más valiosa. Y con “estar en el lugar que le corresponde” se refería a entregarla a un Charon, porque estaba escrita para ellos.",
          DialogueId = 80120221,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89293C2",
          LookAt = {
            [1] = "790019:n(790008)",
            [2] = "790008:n(790019)"
          },
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          Subtitle = "So maybe, just maybe, this score was the one he cherished most. And the \"right place\" for it was in the hands of a Charon — because it was written for them.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89293C2"
        },
        [80120222] = {
          Camera = "-252.260193,281.916748,126.221512,0.000009,-3.999636,-119.588837,35.0,234.284531,false,Manual,5.0",
          ContentES = "La letra es preciosa… ¡Ah! Me pregunto cómo sonará esta canción cuando se cante.",
          DialogueId = 80120222,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          GUID = "C89293EC",
          LookAt = {
            [1] = "790019:n(790019)"
          },
          NextDialogue = 80120223,
          SpeakNpcId = 790019,
          Subtitle = "The lyrics are really something... I wonder what this song will sound like.",
          TalkActionId = {
            [1] = "790019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89293EC"
        },
        [80120223] = {
          Camera = "-304.703491,193.633301,104.081329,-0.0,7.999981,-131.396408,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡De acuerdo, he tomado una decisión!",
          DialogueId = 80120223,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C8929416",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120224,
          SpeakNpcId = 790019,
          Subtitle = "Alright — I've made up my mind!",
          TalkActionId = {
            [1] = "790019:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929416"
        },
        [80120224] = {
          Camera = "-255.582703,344.383789,69.178757,0.000035,7.599951,-112.388451,35.000008,264.602783,false,Manual,2.8",
          ContentES = "No importa si Kossak olvidó esta partitura o la dejó a propósito, él confió en mí para que manejara sus cosas, así que voy a tomarme esto en serio.",
          DialogueId = 80120224,
          GUID = "C8929440",
          NextDialogue = 80120225,
          SpeakNpcId = 790019,
          Subtitle = "Whether Kossak forgot about this score or left it behind on purpose, he trusted me to handle his stuff, so I'm going to take it seriously.",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929440"
        },
        [80120225] = {
          Camera = "-501.36084,57.133301,131.599701,0.000011,-4.399932,31.404215,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Vamos, {nickname}, acompáñame a la casa de Camilla. Parece que ella sabe de partituras, y quiero que me enseñe a cantarla.",
          DialogueId = 80120225,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892946A",
          NextDialogue = 80120226,
          SpeakNpcId = 790019,
          Subtitle = "Come on, , let's head over to Ms Camilla's tavern. I think she can read music. I'm going to ask her to teach me this song.",
          TalkActionId = {
            [1] = "790019:Explain02_End",
            [2] = [[

790008:AgreeHead]]
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892946A"
        },
        [80120226] = {
          Camera = "-302.98645,187.943359,114.158592,0.000014,3.400027,-133.7966,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "Cuando aprenda a cantarla, se la enseñaré a los Charons de Lago Helado, y les diré que es una pieza escrita especialmente para nosotros por un gran músico.",
          DialogueId = 80120226,
          FacialId = {
            [1] = "790019:Happy01"
          },
          FinalCamera = "-302.98645,187.943359,114.158592,0.000026,3.400027,-133.7966,36.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929494",
          NextDialogue = 80120227,
          SpeakNpcId = 790019,
          Subtitle = "Once I've learned it, I'll teach it to all the Charons in Icelake. I'll tell them it's a song written especially for us by a respected musician.",
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929494"
        },
        [80120227] = {
          Camera = "193.657837,-330.853027,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "De esa manera, esta canción no acabará como sus borradores descartados, arrojada al fuego y quemada hasta las cenizas.",
          DialogueId = 80120227,
          FinalCamera = "153.661621,-330.320312,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89294BE",
          NextDialogue = 80120228,
          SpeakNpcId = 790019,
          Subtitle = "That way, this song won't end up like his discarded drafts, tossed into the fire and burned to ashes.",
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294BE"
        },
        [80120228] = {
          Camera = "79.69873,985.43457,55.531265,0.000044,12.80017,92.181931,55.0,490.84668,false,Manual,1.2",
          ContentES = "Tal vez algún día esta canción llegue a la capital y él realmente escuche a los Charons cantarla. Pero si no la escucha, no importa. De todas formas, habré hecho lo correcto...",
          DialogueId = 80120228,
          FinalCamera = "103.997955,961.556152,69.737282,0.000067,10.600037,97.981682,55.0,490.84668,false,Manual,1.2",
          GUID = "C89294E8",
          NextDialogue = 80120229,
          SpeakNpcId = 790019,
          Subtitle = "Who knows? Maybe one day, this song will reach the capital, so he'll hear Charons singing it outside his window. But even if that won't happen, it doesn't matter. I'll have done my job—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294E8"
        },
        [80120229] = {
          Camera = "-312.233704,183.148438,116.782532,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentES = "¡Devolver los tesoros olvidados a la luz y permitir que muestren su verdadero valor, esa es mi misión!",
          DialogueId = 80120229,
          FacialId = {
            [1] = "790019:Happy02"
          },
          FinalCamera = "-316.72876,177.902344,117.07206,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929512",
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"-285.357117,180.728271,121.084183,0.0,0.0,-143.597351,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 790019,
          Subtitle = "Bringing forgotten treasures back into the light and letting their value be seen — that's my mission!",
          TalkActionId = {
            [1] = "790019:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929512"
        },
        [80120230] = {
          ContentES = "Más tarde, Camilla comenta que «El demonio se liberó de las cadenas» es una pieza brillante y muy desafiante de interpretar.",
          DialogueId = 80120230,
          Duration = 4,
          GUID = "C892953C",
          NextDialogue = 80120231,
          Subtitle = "Later, according to Camilla, \"Demons Broken Loose\" is indeed a brilliant piece, and quite a challenging one.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C892953C"
        },
        [80120231] = {
          ContentES = "A Margie le tomó tres días en aprender a cantarla, tuvo que bajarla a una octava. Poco después, ya se oía su melodía flotando por las calles de Lago Helado.",
          DialogueId = 80120231,
          Duration = 5,
          GUID = "C8929566",
          NextDialogue = 80120232,
          Subtitle = "It took Margie three full days to master the song, and even then, she had to transpose it down an octave. Before long, echoes of the melody began to drift through the streets of Icelake.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929566"
        },
        [80120232] = {
          ContentES = "Esto es lo que Margie suele llamar “convertir la basura en tesoro”.",
          DialogueId = 80120232,
          Duration = 3,
          GUID = "C8929590",
          Subtitle = "Seems like Margie has accomplished her mission of bringing forgotten treasures back into the light.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929590"
        },
        [80120290] = {
          DialogueId = 80120290,
          GUID = "C89291CB",
          IsBlack = 1,
          NextDialogue = 80120210,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_woodbrk\"},PlayAs2D{true}}"
        },
        [80120301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentES = "Mmm...",
          DialogueId = 80120301,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A0E2",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120302,
          SpeakNpcId = 93301,
          Subtitle = "Hmm...",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentES = "Amargo y dulce a la vez… Uf, ¡siento que es un sabor que a mi viejo gruñón le encantaría! En cuanto a mí, creo que necesitaré otros diez… no, veinte años para llegar a entender este sabor.",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          Subtitle = "Bitter and sweet at the same time... Ugh, this tastes like something my stupid old man would love! As for me, I think I'll need another ten... no, make that twenty years to appreciate this taste.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentES = "¡No entiendo esta bebida! ¿Por qué alguien querría torturarse con este sabor amargo?",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "I just don't get this drink! Why would anyone want to torture themselves with this bitter taste?",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentES = "¡Exacto! Nada supera a una bebida refrescante después de un día de trabajo, ¡es como si una brisa fresca chocara con tu rostro!",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "Exactly! Nothing beats a refreshing drink after a day's work — it's like a cool wave from head to toe!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A160"
        },
        [80120305] = {
          ContentES = "¡Mi padre! Todo el mundo lo llama el viejo Martin. Antes de que yo tomara el relevo, él se encargaba de todos los basureros de Lago Helado.",
          DialogueId = 80120305,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A18A",
          NextDialogue = 80120306,
          SpeakNpcId = 93301,
          Subtitle = "Oh, that's my dad! They call him Old Martin. Before I took over, he was the one managing all the rubbish bins in Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A18A"
        },
        [80120306] = {
          ContentES = "Ya que todos lo llaman “El Rey del Basurero”, quedé atrapada con ese tonto y ridículo apodo de “La Princesa del Basurero” ¡Puaj! ¡Todo por culpa de ese viejo presumido!",
          DialogueId = 80120306,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A1B4",
          NextDialogue = 80120307,
          SpeakNpcId = 93301,
          Subtitle = "If it weren't for his stupid title \"King of the Bins,\" I wouldn't be stuck with that tacky, lame nickname \"Princess Rubbish Bin\"... Ugh, it's all that flashy old man's fault!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1B4"
        },
        [80120307] = {
          ContentES = "Quería un apodo que me hiciera ver más genial, más inteligente y confiable…",
          DialogueId = 80120307,
          FacialId = {
            [1] = "93301:Iyada01"
          },
          GUID = "C892A1DE",
          NextOptions = {
            [1] = 801203071,
            [2] = 801203081
          },
          SpeakNpcId = 93301,
          Subtitle = "I mean, I was hoping for something cooler, smarter, and more reliable...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1DE"
        },
        [80120308] = {
          ContentES = "¡Exacto, exacto! Jejeje, ¡ya me estás entendiendo!",
          DialogueId = 80120308,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A208",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          Subtitle = "That's right! Hehe, you totally get me!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A208"
        },
        [80120309] = {
          ContentES = "¡Aaah, cállate, cállate! ¡O te doy con mi pala!",
          DialogueId = 80120309,
          FacialId = {
            [1] = "93301:Disappoint01"
          },
          GUID = "C892A232",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          Subtitle = "Aaaah! Stop it! I'll whack you with my shovel if you say that again!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A232"
        },
        [80120310] = {
          ContentES = "Ay… ese viejo gruñón, desde que me pasó el negocio no lo he vuelto a ver. No tengo idea de qué andará haciendo. ¡Ojalá que no nos meta en problemas a Camilla y a mí!",
          DialogueId = 80120310,
          FacialId = {
            [1] = "93301:Unhappy01"
          },
          GUID = "C892A25C",
          NextOptions = {
            [1] = 801203101
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh... ever since that stupid old man dumped all the work on me, I barely see him around. No idea what he's been doing. He better not be causing trouble for me and Ms Camilla!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A25C"
        },
        [80120311] = {
          ContentES = "Eh, si no fuera por este sabor amargo… creo que, en realidad… no me hubiera acordado de ese viejo gruñón…",
          DialogueId = 80120311,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892A286",
          NextOptions = {
            [1] = 801203111,
            [2] = 801203121
          },
          SpeakNpcId = 93301,
          Subtitle = "Uh, well... if it weren't for this bitter taste, I guess I haven't really thought about him in a while...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A286"
        },
        [80120312] = {
          ContentES = "¡Estoy muy ocupada con el trabajo! Al fin y al cabo, ¡el me dejó todas estas responsabilidades!",
          DialogueId = 80120312,
          FacialId = {
            [1] = "93301:Shock02"
          },
          GUID = "C892A2B0",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          Subtitle = "Well, in my defence, I've been swamped with work! His work, to be precise!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2B0"
        },
        [80120313] = {
          ContentES = "Bueno… al crecer se tiene que volar y dejar el nido, es algo natural.",
          DialogueId = 80120313,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A2DA",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          Subtitle = "Ahem... Well, you know, when little animals grow up, they leave the nest to fend for themselves. It's totally normal.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2DA"
        },
        [80120314] = {
          ContentES = "Además, durante más de diez años de mi vida, ese viejo gruñón prácticamente no se despegó de mí. Sobre todo después de mudarnos a Lago Helado. Pasamos un año entero cruzando las llanuras heladas, solos, él y yo, nadie más.",
          DialogueId = 80120314,
          GUID = "C892A304",
          NextDialogue = 80120315,
          SpeakNpcId = 93301,
          Subtitle = "Besides, that stupid old man has been fussing over me for more than ten years. Especially after we left our old home for Icelake — we spent a whole year trekking across the snowfields, just the two of us, not another living soul in sight.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A304"
        },
        [80120315] = {
          ContentES = "Ya tuve suficiente de escuchar sus cuentos y berrinches. Así que… así que, bueno, no lo extraño tanto… creo.",
          DialogueId = 80120315,
          GUID = "C892A32E",
          NextDialogue = 80120316,
          SpeakNpcId = 93301,
          Subtitle = "I've had enough of his tales, his songs, and his tricks to last me a lifetime. So... I guess that's why I don't really miss him that much... probably.",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A32E"
        },
        [80120316] = {
          ContentES = "Poco después de llegar a Lago Helado, el viejo gruñón empezó a “marcar territorio”, a “reclutar pandilleros locales”, “cobrarles protección a los negocios”, “hacer alianzas y convertirse en el jefe”… Parecía que se la estaba pasando muy bien solo.",
          DialogueId = 80120316,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A358",
          NextOptions = {
            [1] = 801203161
          },
          SpeakNpcId = 93301,
          Subtitle = "Plus, soon after we arrived in Icelake, he jumped right into \"staking out territories,\" \"recruiting the local henchmen,\" \"figuring out the protection racket,\" \"making alliances with local powers,\" and \"becoming the top dog.\" He seemed to enjoy himself just fine on his own.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A358"
        },
        [80120317] = {
          ContentES = "Es decir, solo investigó la distribución de la basura, incorporó a los antiguos trabajadores de limpieza, estableció criterios seguros para la compra, buscó a través de Camilla a comerciantes dispuestos a reciclar los desechos, y al final se convirtió en el “Rey del Basurero”.",
          DialogueId = 80120317,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A382",
          NextDialogue = 80120318,
          SpeakNpcId = 93301,
          Subtitle = "Oh, it's actually just mapping out the rubbish bin locations, recruiting the sanitation workers, setting rules for rubbish collection, finding buyers through Ms Camilla, and becoming the \"King of the Bins.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A382"
        },
        [80120318] = {
          ContentES = "A ese viejo le encanta hablar con palabras pomposas, ¡suena como un personaje de teatro! Un mal hábito del pasado supongo, no creo que pueda cambiar eso.",
          DialogueId = 80120318,
          GUID = "C892A3AC",
          NextOptions = {
            [1] = 801203181
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh, that stupid old man loves spouting off fancy talk — he sounds like a flashy character from a drama script! Bad habits from his rough-and-tumble days back home, I guess. He can't seem to shake them off. Gah!",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3AC"
        },
        [80120319] = {
          ContentES = "¡Quién sabe! A ese viejo le encantaba contarme sus “grandes hazañas” del pasado como si fueran historias grandiosas.",
          DialogueId = 80120319,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A3D6",
          NextDialogue = 80120320,
          SpeakNpcId = 93301,
          Subtitle = "It's hard to say! The old man always liked to brag about his \"glorious past\" back home. Stuff like...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3D6"
        },
        [80120320] = {
          ContentES = "“Cada misión de un limpiador concierne tanto al honor personal como al beneficio de la familia. Desde el plano hasta el más mínimo detalle, todo debe ser perfecto. Y tu padre… es el mejor limpiador de todos.”",
          DialogueId = 80120320,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A400",
          NextDialogue = 80120321,
          SpeakNpcId = 93301,
          Subtitle = "\"A scavenger's every mission is a matter of personal honour and family interest. From daily planning to personal grooming, everything must be meticulously prepared. And your father, my dear, was the finest scavenger of all.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A400"
        },
        [80120321] = {
          ContentES = "Fue culpa de su mala influencia. Cuando recién llegué a Lago Helado, hablaba exactamente como una “pequeña Martin”. Al final, fue Camilla quien se hartó de mi tono y se tomó su tiempo para corregirme.",
          DialogueId = 80120321,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A42A",
          NextOptions = {
            [1] = 801203211
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh, his bad influence is why, when I first got to Icelake, I talked exactly like a \"Mini-Martin.\" Ms Camilla said it was really annoying, and it took her forever to help me lose that tone...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A42A"
        },
        [80120322] = {
          ContentES = "¡Ni loca! ¡Me da vergüenza!",
          DialogueId = 80120322,
          FacialId = {
            [1] = "93301:Unacceptable01"
          },
          GUID = "C892A454",
          NextOptions = {
            [1] = 801203221,
            [2] = 801203231
          },
          SpeakNpcId = 93301,
          Subtitle = "No way! That's too embarrassing!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A454"
        },
        [80120323] = {
          ContentES = "Bueno, solo esta vez, ¿eh? ¡Después, nunca más!",
          DialogueId = 80120323,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A47E",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          Subtitle = "Fine, just this once, okay? No encores!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A47E"
        },
        [80120324] = {
          ContentES = "¡Aaaay! ¡Lo haré, lo haré! ¡Pero deja de llamarme así!",
          DialogueId = 80120324,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A4A8",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          Subtitle = "Aaaahhhh!!! Okay, okay! I'll do it! Just stop already!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4A8"
        },
        [80120325] = {
          ContentES = "Eh… cuando el viejo Martin me dejaba en la tienda de Camilla y salía a hacer sus asuntos, yo le decía algo como…",
          DialogueId = 80120325,
          FacialId = {
            [1] = "93301:Think01"
          },
          GUID = "C892A4D2",
          NextDialogue = 80120326,
          SpeakNpcId = 93301,
          Subtitle = "Uh… When Old Martin dropped me off at Ms Camilla's tavern before he went off to do who-knows-what, I'd say...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4D2"
        },
        [80120326] = {
          ContentES = "“Recuerda tu misión, padre. Nuestro futuro depende de cada una de tus acciones. Espero que te hayas lavado bien la cara, cepillado los dientes, y que tengas un plan sólido.”",
          DialogueId = 80120326,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A4FC",
          NextOptions = {
            [1] = 801203261
          },
          SpeakNpcId = 93301,
          Subtitle = "\"Remember your mission, Father. Our future hinges on your every move, so I trust you've washed your face, brushed your teeth, and made a thorough plan.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4FC"
        },
        [80120327] = {
          ContentES = "“Y él se quitaba el sombrero y me respondía: ¡A sus órdenes, señorita! Si alguno de nosotros falla, escribiremos su nombre junto a la palabra “idiota” en la puerta del Asfódelo para que todos lo vean.”",
          DialogueId = 80120327,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A526",
          NextOptions = {
            [1] = 801203271
          },
          SpeakNpcId = 93301,
          Subtitle = "And then Old Martin would tip his hat and say, \"As you command, ma'am! Should either of us fail, we'll inscribe that person's name with the modifier \"idiot\" on The Asphodel's door for all to see.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A526"
        }
      }
    end
  },
  {
    MinKey = 80120328,
    MaxKey = 80130409,
    Loader = function()
      return {
        [80120328] = {
          ContentES = "Y yo le respondía: “Ya que compartimos el mismo apellido, lo grabaré en el fondo de la olla, así resguardaré la dignidad del que me dejó a cargo de esta misión y dejaré el fuego de la cocina purifique la vergüenza con su llama redentora.”",
          DialogueId = 80120328,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A550",
          NextOptions = {
            [1] = 801203281
          },
          SpeakNpcId = 93301,
          Subtitle = "And I'd reply, \"Oh, considering we share a last name, better to inscribe it on the bottom of a pot instead — saves me the shame and allows the stove fire to scorch your disgrace!\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A550"
        },
        [80120329] = {
          ContentES = "¡Jajajajajajajajajaja!",
          DialogueId = 80120329,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A57A",
          NextDialogue = 80120330,
          SpeakNpcId = 100001,
          Subtitle = "Ahahahahahahaha!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A57A"
        },
        [80120330] = {
          ContentES = "Ahora que lo pienso, que te dieran el título de “Princesa del Basurero” no es culpa del viejo Martin, ¡creo que te lo ganaste tu misma!",
          DialogueId = 80120330,
          GUID = "C892A5A4",
          NextDialogue = 80120331,
          SpeakNpcId = 100001,
          Subtitle = "Now I see why you ended up with the title \"Princess Rubbish Bin\" — it's not all Old Martin's fault!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5A4"
        },
        [80120331] = {
          ContentES = "¡Claro que no! ¡Es culpa suya! Solo de pensar que casi termino siendo tan pretenciosa como él, me recorre un escalofrío por todo el cuerpo.",
          DialogueId = 80120331,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A5CE",
          NextDialogue = 80120332,
          SpeakNpcId = 93301,
          Subtitle = "I don't care! It's totally his fault! Just thinking I almost turned into a pompous blowhard like him gives me the chills.",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5CE"
        },
        [80120332] = {
          ContentES = "Además, ¿te diste cuenta?, se nota que el viejo sentía mucha nostalgia y orgullo de su pasado. No creo que haya abandonado su hogar natal solo porque odiara el caos.",
          DialogueId = 80120332,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A5F8",
          NextDialogue = 80120333,
          SpeakNpcId = 93301,
          Subtitle = "And I don't know if you figured this out — the stupid old man clearly misses and takes pride in his past. I don't think he left home just because he hated the chaos there.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5F8"
        },
        [80120333] = {
          ContentES = "Me pregunto: ¿Qué fue exactamente lo que pasó para que abandonara su hogar y se arriesgara a cruzar las llanuras conmigo?",
          DialogueId = 80120333,
          FacialId = {
            [1] = "93301:Unhappy02"
          },
          GUID = "C892A622",
          NextDialogue = 80120334,
          SpeakNpcId = 93301,
          Subtitle = "But what could have happened that made him leave home and drag me across the snowfields?",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A622"
        },
        [80120334] = {
          ContentES = "¡Estaba segura que me ocultaba un gran secreto! Pero cada vez que le preguntaba, me decía algo como: “No te lo voy a decir. Si quieres saberlo, usa tu cabeza y averígualo por ti misma.”",
          DialogueId = 80120334,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A64C",
          NextDialogue = 80120335,
          SpeakNpcId = 93301,
          Subtitle = "He's definitely hiding something huge from me! But every time I ask, all he says is, \"I won't tell you. If you do want to know, use your head and figure it out yourself.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A64C"
        },
        [80120335] = {
          ContentES = "Así que el año pasado me dediqué a investigar unos meses. Pero el viejo es muy astuto y escurridizo… no pude encontrar nada, ni siquiera las pertenencias que trajo consigo desde su hogar natal.",
          DialogueId = 80120335,
          GUID = "C892A676",
          NextDialogue = 80120336,
          SpeakNpcId = 93301,
          Subtitle = "So last year, I secretly investigated him for months. But the old man's so crafty and sneaky, he even hid the stuff he brought from our hometown. I couldn't find it no matter what.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A676"
        },
        [80120336] = {
          ContentES = "Después de todo ese tiempo perdido y sin encontrar ni una pista de pasado, ¡tuvo el descaro de burlarse de mí en mi cara!",
          DialogueId = 80120336,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A6A0",
          NextOptions = {
            [1] = 801203361
          },
          SpeakNpcId = 93301,
          Subtitle = "After months of digging, I came up empty. And to top it off, he had the nerve to mock me—",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6A0"
        },
        [80120337] = {
          ContentES = "Un día, el viejo escurridizo volvió de la nada, algo muy raro, pasó todo el día conmigo e incluso olvidó llevarse su maleta… ¡esa misma que había traído desde nuestro antiguo hogar!",
          DialogueId = 80120337,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A6CA",
          NextDialogue = 80120338,
          SpeakNpcId = 93301,
          Subtitle = "One day, out of nowhere, the old man actually showed up. He spent the whole day with me, and even forgot to take his suitcase with him when he left — the one he brought from our hometown!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6CA"
        },
        [80120338] = {
          ContentES = "Y pensé: “¡Ja! El viejo cometió un descuido por fin, lo atrapé.” Así que abrí la maleta… pero dentro solo había una olla.",
          DialogueId = 80120338,
          GUID = "C892A6F4",
          NextDialogue = 80120339,
          SpeakNpcId = 93301,
          Subtitle = "I thought, \"Ha! That old man slipped up at last!\" So I opened the suitcase, and inside... was just a pot.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6F4"
        },
        [80120339] = {
          ContentES = "(Margie golpea con furia el casco que lleva en la cabeza, y resuena un eco metálico).",
          DialogueId = 80120339,
          GUID = "C892A71E",
          NextDialogue = 80120340,
          Subtitle = "(Margie angrily taps on the pot she's wearing on her head, producing a hollow sound.)",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A71E"
        },
        [80120340] = {
          ContentES = "¡Exactamente esta misma olla! Y además, dejó una nota dentro de la maleta…",
          DialogueId = 80120340,
          GUID = "C892A748",
          NextDialogue = 80120341,
          SpeakNpcId = 93301,
          Subtitle = "This thing right here! And he left a note in the suitcase...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A748"
        },
        [80120341] = {
          ContentES = "“Señorita Margie, estaba seguro que abriría esta maleta para intentar descubrir mis secretos, por lo que ya los he trasladado a un lugar que jamás encontrarás.”",
          DialogueId = 80120341,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A772",
          NextDialogue = 80120342,
          SpeakNpcId = 93301,
          Subtitle = "\"Dear Miss Margie, I knew you'd snoop in this suitcase, so I've relocated the secret to a place you'd least expect.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A772"
        },
        [80120342] = {
          ContentES = "“Para compensar su disgusto, le dejo este obsequio: un casco multifuncional que, usado correctamente, protege eficazmente la cabeza, y al voltearlo, puede servir para cocinar, además la lámpara fijada al frente ilumina el camino. Sin duda, un artículo ideal tanto para el hogar como para los viajes.”",
          DialogueId = 80120342,
          GUID = "C892A79C",
          NextDialogue = 80120343,
          SpeakNpcId = 93301,
          Subtitle = "\"To make up for your disappointment, I've left you this — an all-purpose pot helmet! Worn normally, it protects your head; flip it over, and it's a perfect cooking pot. The attached lamp even works as a flashlight. Truly, the ultimate all-in-one tool.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A79C"
        },
        [80120343] = {
          ContentES = "“Por cierto, feliz cumpleaños. Firma: Martin”",
          DialogueId = 80120343,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A7C6",
          NextOptions = {
            [1] = 801203431,
            [2] = 801203432
          },
          SpeakNpcId = 93301,
          Subtitle = "\"By the way, happy birthday. — Martin.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7C6"
        },
        [80120344] = {
          ContentES = "¡Estoy bastante segura de que solo se estaba burlando de mí!",
          DialogueId = 80120344,
          GUID = "C892A7F0",
          NextDialogue = 80120345,
          SpeakNpcId = 93301,
          Subtitle = "...I'm pretty sure he was mocking me!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7F0"
        },
        [80120345] = {
          ContentES = "En fin, después de eso, ya no me molesté en seguir investigando sus secretos.",
          DialogueId = 80120345,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A81A",
          NextDialogue = 80120346,
          SpeakNpcId = 93301,
          Subtitle = "Anyway, after that, I gave up caring about his stupid secret.",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A81A"
        },
        [80120346] = {
          ContentES = "Hablando de eso, tengo un presentimiento…",
          DialogueId = 80120346,
          GUID = "C892A844",
          NextDialogue = 80120347,
          SpeakNpcId = 100001,
          Subtitle = "Speaking of secrets, I've got a hunch...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A844"
        },
        [80120347] = {
          ContentES = "¿A qué te refieres?",
          DialogueId = 80120347,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A86E",
          NextDialogue = 80120348,
          SpeakNpcId = 93301,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A86E"
        },
        [80120348] = {
          ContentES = "¿Y qué tal si tu secreto… está escondido en ese “casco multifuncional”?",
          DialogueId = 80120348,
          GUID = "C892A898",
          NextDialogue = 80120349,
          SpeakNpcId = 100001,
          Subtitle = "Could his secret be hidden... inside this \"all-purpose helmet\"?",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A898"
        },
        [80120349] = {
          ContentES = "Si dijo que “el secreto está en un lugar que jamás encontrarás”, entonces ¿no sería posible… que el lugar más inesperado sea, en realidad, el que este más cerca?",
          DialogueId = 80120349,
          GUID = "C892A8C2",
          NextDialogue = 80120350,
          SpeakNpcId = 100001,
          Subtitle = "I mean, he did say it was at a place you'd least expect, so... maybe the most obvious place is the place you'd never expect.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8C2"
        },
        [80120350] = {
          ContentES = "¡Ah…! ¡Aquella vez me desanimé tanto que no investigué bien este casco! Ahora que lo pienso, si el casco está modificado, ¡tal vez esconda algo dentro! ¡Vamos a desmontarlo ahora!",
          DialogueId = 80120350,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A8EC",
          NextDialogue = 80120351,
          SpeakNpcId = 93301,
          Subtitle = "Ah...!!! Come to think of it, I was so bummed back then I didn't even check this helmet carefully! You might be right — it's been modified, so it's possible that he had hidden something inside! Let's take it apart now!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8EC"
        },
        [80120351] = {
          ContentES = "¡Es verdad! Debajo de la capa de amortiguación hay un compartimento secreto. ¡Sabía que tenías talento de detective!",
          DialogueId = 80120351,
          GUID = "C892A916",
          IsBlack = 1,
          NextDialogue = 80120352,
          SpeakNpcId = 93301,
          Subtitle = "Aha! A hidden compartment under the padding! I knew you had a detective's knack!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A916"
        },
        [80120352] = {
          ContentES = "¡Te atrapé, viejo gruñón! ¡Se acabó, encontré tu secreto!",
          DialogueId = 80120352,
          GUID = "C892A940",
          IsBlack = 1,
          NextDialogue = 80120353,
          SpeakNpcId = 93301,
          Subtitle = "Gotcha, stupid old man! The jig's up!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A940"
        },
        [80120353] = {
          ContentES = "(Margie manipula hábilmente el casco, su experiencia reutilizando chatarra le ayuda mucho. Sus dedos se mueven con destreza, y pronto el casco queda completamente desarmado).",
          DialogueId = 80120353,
          GUID = "C892A96A",
          IsBlack = 1,
          NextDialogue = 80120354,
          Subtitle = "(Margie skillfully manipulates the pot helmet — her experience with repurposing scrap obviously helps a lot. Her fingers move deftly, and soon the pot is fully disassembled.)",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A96A"
        },
        [80120354] = {
          ContentES = "Esto… esto es…",
          DialogueId = 80120354,
          GUID = "C892A994",
          IsBlack = 1,
          NextDialogue = 80120355,
          SpeakNpcId = 93301,
          Subtitle = "Ah, this is...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A994"
        },
        [80120355] = {
          ContentES = "(Margie mira la olla con los ojos bien abiertos, sin palabras. Tomas la olla de sus manos y, en el fondo, ves grabadas unas pequeñas letras).",
          DialogueId = 80120355,
          GUID = "C892A9BE",
          IsBlack = 1,
          NextDialogue = 80120356,
          Subtitle = "(Margie stares wide-eyed at the pot, speechless. You take the pot from her and see a small inscription on the bottom—)",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9BE"
        },
        [80120356] = {
          ContentES = "“Para mi torpe hija, Margie:”",
          DialogueId = 80120356,
          GUID = "C892A9E8",
          IsBlack = 1,
          NextDialogue = 80120357,
          Subtitle = "\"Dear Margie, my silly daughter,\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9E8"
        },
        [80120357] = {
          ContentES = "“Felicidades por fallar una vez más en el juego 'Búsqueda de los secretos del viejo Martin'. Por ello, añadiré la palabra 'idiota' delante de tu nombre.”",
          DialogueId = 80120357,
          GUID = "C892AA12",
          IsBlack = 1,
          NextDialogue = 80120358,
          Subtitle = "\"Congratulations on failing yet again in the 'Find Old Martin's Secret' game. As punishment, I shall add the modifier 'Idiot' to your name.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA12"
        },
        [80120358] = {
          ContentES = "“Ya que compartimos el mismo apellido, lo grabaré en el fondo de la olla: así resguardaré la dignidad del que me dejó a cargo de esta misión y dejaré que el fuego de la cocina purifique la vergüenza con su llama redentora.”",
          DialogueId = 80120358,
          GUID = "C892AA3C",
          IsBlack = 1,
          Subtitle = "\"Considering we share a last name, I hereby inscribe it on the bottom of this pot instead, which saves me the shame, and allows the stove fire to scorch your disgrace.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA3C"
        },
        [80120401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentES = "*Snif*... La detective Margie ha resuelto otro caso revolucionario…",
          DialogueId = 80120401,
          GUID = "C892B14A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204011
          },
          SpeakNpcId = 93301,
          Subtitle = "*sniffles* ...Detective Margie has cracked yet another groundbreaking case...",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B14A"
        },
        [80120402] = {
          ContentES = "¡Estas… estas son lágrimas de felicidad!",
          DialogueId = 80120402,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892B174",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204021
          },
          SpeakNpcId = 93301,
          Subtitle = "Th—These are tears of joy!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B174"
        },
        [80120403] = {
          ContentES = "(Margie se bebe de un trago el vaso de agua, luego saca con cuidado algo que lleva en su bolsillo y te lo muestra: es un mechón de pelo cuyo color te resulta familiar).",
          DialogueId = 80120403,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B19E",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120404,
          Subtitle = "(Margie gulps down a full glass of water, then gingerly pulls something from her pocket and presents it to you — it's a clump of fur, somewhat familiar in colour.)",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B19E"
        },
        [80120404] = {
          ContentES = "¡Encontré a Colagorda!",
          DialogueId = 80120404,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B1C8",
          NextOptions = {
            [1] = 801204041
          },
          SpeakNpcId = 93301,
          Subtitle = "I found Plumpytail!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1C8"
        },
        [80120405] = {
          ContentES = "¡Es la gatita con la que vagabundeaba en la nieve!",
          DialogueId = 80120405,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B1F2",
          NextDialogue = 80120406,
          SpeakNpcId = 93301,
          Subtitle = "Plumpytail's the little cat I used to roam the snowfields with!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1F2"
        },
        [80120406] = {
          ContentES = "Cuando llegué a Lago Helado no quiso venir conmigo y se quedó en la naturaleza. ¡Hice un peluche que se parece mucho a ella para recordarla siempre!",
          DialogueId = 80120406,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B21C",
          NextDialogue = 80120407,
          SpeakNpcId = 93301,
          Subtitle = "Then I came to Icelake, but she didn't want to come with me and stayed in the wilderness. I made a plushie that looks just like her to remember her!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B21C"
        },
        [80120407] = {
          ContentES = "Hoy pensaba ir a revisar los basureros que están cerca de la puerta de la ciudad, ¡pero por casualidad encontré estos pelos sueltos! ¡Mira!",
          DialogueId = 80120407,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B246",
          NextDialogue = 80120408,
          SpeakNpcId = 93301,
          Subtitle = "I was just going to check the bins near the city gates today, but instead, I stumbled upon this clump of fur! Look!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B246"
        },
        [80120408] = {
          ContentES = "El pelo gris con manchas negras, con una textura suave, pero firme. Incluso estaba un poco húmedo cuando lo encontré… ¡Definitivamente es Colagorda! ¡Volvió por mí!",
          DialogueId = 80120408,
          GUID = "C892B270",
          NextDialogue = 80120409,
          SpeakNpcId = 93301,
          Subtitle = "The greyish colour with black spots, the soft yet coarse feel, and the fact that it was even a bit damp when I found it... It's definitely Plumpytail! She came back for me!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B270"
        },
        [80120409] = {
          ContentES = "Cuando jugábamos “Persiguiendo al Sospechoso”, dejaba mechones de pelo que se había lamido en diferentes lugares para despistarme. Esa era una de sus trucos característicos.",
          DialogueId = 80120409,
          GUID = "C892B29A",
          NextDialogue = 80120410,
          SpeakNpcId = 93301,
          Subtitle = "Back in the day, when Plumpytail and I played \"Tailing the Suspect,\" she would leave bits of furball from her grooming in different directions to throw me off. That was one of her signature tricks.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B29A"
        },
        [80120410] = {
          ContentES = "Yo era una detective novata en ese entonces, así que siempre caía directo en sus trampas. Para cuando yo estaba agotada de correr en círculos, salía de su escondite con la cabeza erguida y balanceando la cola como si fuera la reina del mundo...",
          DialogueId = 80120410,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B2C4",
          NextDialogue = 80120411,
          SpeakNpcId = 93301,
          Subtitle = "I was such a rookie detective back then, so I always walked straight into Plumpytail's traps. By the time I was worn out from running in circles, Plumpytail would prance around with her head held high, tail swaying like she was king of the world!",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2C4"
        },
        [80120411] = {
          ContentES = "Estoy empezando a recordarlo todo… la rabia de ser burlada cuando jugábamos, la frustración de perder su pista, el pánico al perderme en la nieve… y el desconcierto de sostener un puñado de pelo mojado.",
          DialogueId = 80120411,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B2EE",
          NextOptions = {
            [1] = 801204111
          },
          SpeakNpcId = 93301,
          Subtitle = "...It's all coming back to me — the irritation of being toyed with by the \"Suspect Cat,\" the frustration of losing the trail, the panic of getting lost in the snowfields, and the bafflement of holding a handful of wet fur!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2EE"
        },
        [80120412] = {
          ContentES = "¡Bah! ¡Después de tantos años, ya no soy la joven detective de antes! Además, Lago Helado es mi territorio, y esta vez atraparé a esa “gatita sospechosa” cueste lo que cueste.️",
          DialogueId = 80120412,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B318",
          NextDialogue = 80120413,
          SpeakNpcId = 93301,
          Subtitle = "Hmph! Those days are long behind me! I'm no longer the rookie I once was! Plus, Icelake is my turf now, and this time, I'm definitely going to catch the \"Suspect Cat\"!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B318"
        },
        [80120413] = {
          ContentES = "He mapeado los posibles escondites según la geografía de cada callejón e incluso soborné a los gatos callejeros del barrio con pescaditos. ¡El que me de pistas sobre la “gatita sospechosa” será muy bien recompensado!",
          DialogueId = 80120413,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B342",
          NextOptions = {
            [1] = 801204131,
            [2] = 801204141
          },
          SpeakNpcId = 93301,
          Subtitle = "I've been mapping out the possible hiding spots based on the alley layouts and even bribed the local strays with fish treats. Anyone who can provide a lead on this outsider cat will be handsomely rewarded!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B342"
        },
        [80120414] = {
          ContentES = "¡Atrapé a un enorme gato blanco que me dio pistas falsas! ¡De castigo se quedará medio mes sin pescaditos!",
          DialogueId = 80120414,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B36C",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Aha! Caught a white-furred big cat spreading false alarms! As punishment, no fish treats for half a month!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B36C"
        },
        [80120415] = {
          ContentES = "Jejeje, aunque me halagues así… jejeje, ¡no voy a dejar que se me suba a la cabeza, jejeje!",
          DialogueId = 80120415,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B396",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Hehe, even if you flatter me like that... hehe, I won't let it go to my head, hehe!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B396"
        },
        [80120416] = {
          ContentES = "Ejem, como decía… gracias a un meticuloso razonamiento, finalmente encontré a Colagorda en un callejón lleno de cajas de cartón: ¡un paraíso irresistible para una gatita acostumbrada a vivir en la calle!",
          DialogueId = 80120416,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B3C0",
          NextDialogue = 80120417,
          SpeakNpcId = 93301,
          Subtitle = "Ahem, as I was saying... my detailed deductions finally led me to a narrow alley full of cardboard boxes — it's like an irresistible paradise for a cat used to living in the wild!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3C0"
        },
        [80120417] = {
          ContentES = "Y efectivamente, ahí estaba la sospechosa, tomando el sol dentro de una caja de cartón, moviendo la cola con total despreocupación como si fuera la dueña del lugar.",
          DialogueId = 80120417,
          FacialId = {
            [1] = "93301:Happy01"
          },
          GUID = "C892B3EA",
          NextDialogue = 80120418,
          SpeakNpcId = 93301,
          Subtitle = "And sure enough, there was the suspect, basking in the sun inside a cardboard box, casually flicking her tail at me as if she owned the place!",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3EA"
        },
        [80120418] = {
          ContentES = "Después de tanto tiempo sin verla, Colagorda seguía siendo la misma... y sin embargo parecía un poco distinta a como la recordaba…",
          DialogueId = 80120418,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B414",
          NextDialogue = 80120419,
          Scripts = "PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "It's been so long, yet Plumpytail was still the same Plumpytail I knew... No, actually, she seemed a bit different this time.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B414"
        },
        [80120419] = {
          ContentES = "Cuando nos despedimos, Colagorda estaba creciendo. No le gustaba que la tocaran, y si se molestaba, desaparecía sin dejar rastro. Esta vez, al reencontrarla, sentí que había madurado bastante… hasta parecía un poco viejita.",
          DialogueId = 80120419,
          GUID = "C892B43E",
          NextDialogue = 80120420,
          SpeakNpcId = 93301,
          Subtitle = "When we last parted, Plumpytail had just grown up and didn't like being petted — one wrong move, and she'd vanish in a flash. But today, she seemed more mature, almost like an old cat.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B43E"
        },
        [80120420] = {
          ContentES = "¿Acaso la edad suaviza el carácter también en los animales? Aunque no le traje sus golosinas favoritas, me dejaba acariciarla por todas partes: el vientre, las patas, la cola.",
          DialogueId = 80120420,
          GUID = "C892B468",
          NextDialogue = 80120421,
          SpeakNpcId = 93301,
          Subtitle = "Does \"mellow with age\" also apply to animals? Even without her favourite jerky, she let me pet her all over — belly rubs, paw squeezes, tail strokes and all.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B468"
        },
        [80120421] = {
          ContentES = "Esta vez, Colagorda vino acompañada de algunos gatitos. Sin embargo, al igual que ella cuando era pequeña, eran tímidos y solo se asomaban con la cabecita desde la caja. ¡Pero solo su pelaje demuestra que ella los cuida muy bien!",
          DialogueId = 80120421,
          GUID = "C892B492",
          NextDialogue = 80120422,
          Scripts = "SEQ{PlayAnimation{ActorId{93301},AnimationId{\"Sit_Talk01_Start\"},Duration{1}},PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_Talk01_End\"},Duration{1}}}",
          SpeakNpcId = 93301,
          Subtitle = "This time, Plumpytail even brought a few kittens along. They're just as timid as Plumpytail used to be, peeking their little heads out from the box. But just from their fur, I could tell Plumpytail has been taking great care of them!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B492"
        },
        [80120422] = {
          ContentES = "Era realmente conmovedor… esa torpe gatita que ni siquiera podía atrapar ratones en las llanuras heladas, ¡ahora protegía y mantenía a sus gatitos sanos y salvos!",
          DialogueId = 80120422,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4BC",
          NextOptions = {
            [1] = 801204221
          },
          SpeakNpcId = 93301,
          Subtitle = "It's amazing... that clumsy cat who couldn't even catch a snowfield rat is now providing for a whole litter of kittens of her own!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4BC"
        },
        [80120423] = {
          ContentES = "Tienes razón… ambas hemos crecido desde que nos conocimos. Jeje… aunque da un poco de pena admitirlo…",
          DialogueId = 80120423,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4E6",
          NextDialogue = 80120424,
          SpeakNpcId = 93301,
          Subtitle = "You're right... we've both grown since we first met. Hehe... it's kinda embarrassing to admit though...",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4E6"
        },
        [80120424] = {
          ContentES = "A decir verdad, cuando recién llegué a Lago Helado, no era como ahora. En esa época lloraba con frecuencia… ¡Eh, eh! ¡No te atrevas a burlarte!",
          DialogueId = 80120424,
          GUID = "C892B510",
          NextDialogue = 80120425,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "Actually, when I first came to Icelake, I was such a crybaby — hey, don't you dare make fun of me!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B510"
        },
        [80120425] = {
          ContentES = "Hubo varias veces en que quise irme de Lago Helado, hacer como si nunca hubiera llegado. Pensaba en encontrar a Colagorda y deambular por ahí junto a ella… la verdad, la idea no sonaba nada mal.",
          DialogueId = 80120425,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B53A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204251
          },
          SpeakNpcId = 93301,
          Subtitle = "I thought about leaving Icelake more than once. I figured I could just pretend I'd never come and wander the world with Plumpytail, which seemed pretty great.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B53A"
        },
        [80120426] = {
          ContentES = "El viejo Martin siempre decía que la ciudad era un buen lugar, así que yo también le creí. Me imaginaba que una “ciudad” era como un refugio donde la gente con antorchas se reunía para abrigarse y protegerse unos a otros.",
          DialogueId = 80120426,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B564",
          NextDialogue = 80120427,
          SpeakNpcId = 93301,
          Subtitle = "Old Martin always said the city was a good place, so I believed it too. I imagined a \"city\" as a sanctuary where torch-bearing folks huddle together for warmth and protection.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B564"
        },
        [80120427] = {
          ContentES = "Sin embargo, resultó que en ese refugio los Charons eran discriminados sin razón. Los ricos tienen más ropa de la que podrían usar en toda su vida, mientras que los pobres en los barrios marginales apenas podían sobrevivir al crudo invierno…",
          DialogueId = 80120427,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B58E",
          NextDialogue = 80120428,
          SpeakNpcId = 93301,
          Subtitle = "But... Ugh! The things that go on in this \"sanctuary\" are just absurd. Charons are discriminated against for no reason; rich folks have more furs than they could wear in a lifetime, while the poor in the slums might not even survive the cold winter...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B58E"
        },
        [80120428] = {
          ContentES = "¡Y simplemente extrañaba tanto a Colagorda! Y me dije, en todos lados hay cosas buenas y malas, así que… ¿por qué no quedarme con mi gatita favorita?",
          DialogueId = 80120428,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B5B8",
          NextOptions = {
            [1] = 801204281,
            [2] = 801204291
          },
          SpeakNpcId = 93301,
          Subtitle = "And I just missed Plumpytail so much! I figured, every place has its good and bad, so why not just stick with my favourite cat?",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5B8"
        },
        [80120429] = {
          ContentES = "¿Eh? Él no… bueno, quizá sí… De todas formas, la que se quedó en Lago Helado fui yo, ¿no?",
          DialogueId = 80120429,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B5E2",
          NextDialogue = 80120431,
          Scripts = "PlayAnimation{_delay{1},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "Huh? He wouldn't... um, maybe... Anyway, I'm still here in Icelake, aren't I?",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5E2"
        },
        [80120430] = {
          ContentES = "Sí, ahora que lo pienso, solo era una niña intentando huir de los problemas.",
          DialogueId = 80120430,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B60C",
          NextDialogue = 80120431,
          SpeakNpcId = 93301,
          Subtitle = "Yeah, now that I think about it, I was just a kid trying to run away from problems.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B60C"
        },
        [80120431] = {
          ContentES = "De hecho, lo hice una vez. Un día, unos niños Sola me tiraron piedras, y me enojé tanto que corrí directamente hacia la puerta de la ciudad. No paraba de correr y gritar el nombre de Colagorda.",
          DialogueId = 80120431,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892B636",
          NextDialogue = 80120432,
          SpeakNpcId = 93301,
          Subtitle = "I actually did it once. One time, some Sola kids threw rocks at me, and I got so mad that I ran straight for the city gate. I just kept running, calling out for Plumpytail.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B636"
        },
        [80120432] = {
          ContentES = "Y entonces… la vi. Colagorda estaba peleando con un lobo de nieve por un ratón espalda plateada.",
          DialogueId = 80120432,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B660",
          NextDialogue = 80120433,
          SpeakNpcId = 93301,
          Subtitle = "And then... I did run into Plumpytail. She was fighting a snow wolf over a silverback vole.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B660"
        },
        [80120433] = {
          ContentES = "Supuse que debía de estar hambrienta, así que le lancé un pedazo de carne seca. Pero ni siquiera lo miró. Sus ojos estaban fijos únicamente en su presa y en su enemigo.",
          DialogueId = 80120433,
          GUID = "C892B68A",
          NextDialogue = 80120434,
          SpeakNpcId = 93301,
          Subtitle = "I figured Plumpytail must've been starving, so I threw her a piece of jerky. But she didn't even look at it. Her eyes were fixed only on her prey and her enemy.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B68A"
        },
        [80120434] = {
          ContentES = "Al final, Colagorda ganó. Se acercó hacia mí, con mucho orgullo, maullando, ya fuera para presumir o quizás simplemente porque estaba feliz de verme después de tanto tiempo.",
          DialogueId = 80120434,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B6B4",
          NextDialogue = 80120435,
          SpeakNpcId = 93301,
          Subtitle = "In the end, Plumpytail won. She strutted over to me all proud-like, meowing — either showing off or maybe just happy to see me after so long.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6B4"
        },
        [80120435] = {
          ContentES = "Le acaricié su cabeza peluda y le dije: “Colagorda, me iré contigo. Vivamos juntas en las llanuras heladas.”",
          DialogueId = 80120435,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B6DE",
          NextDialogue = 80120436,
          SpeakNpcId = 93301,
          Subtitle = "I petted her fluffy head and said, \"Plumpytail, I'll go with you. Let's live together in the snowfields.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6DE"
        },
        [80120436] = {
          ContentES = "Pero Colagorda no me llevó a su hogar. Se escapó de mis brazos y siguió maullando en dirección a Lago Helado.",
          DialogueId = 80120436,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B708",
          NextDialogue = 80120437,
          SpeakNpcId = 93301,
          Subtitle = "But Plumpytail didn't take me to her home. She darted out of my arms and kept meowing in one direction — it was the direction of Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B708"
        },
        [80120437] = {
          ContentES = "Supongo que estaba tratando de decirme que las llanuras heladas no eran mi hogar, y que yo pertenecía al Lago Helado.",
          DialogueId = 80120437,
          GUID = "C892B732",
          NextDialogue = 80120438,
          SpeakNpcId = 93301,
          Subtitle = "I guess she was trying to tell me the snowfields weren't my home, and I belonged to Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B732"
        },
        [80120438] = {
          ContentES = "Ahí fue cuando me di cuenta… Incluso dándole de comer, Colagorda seguiría esforzándose por cazar, porque esa era su forma de vivir.",
          DialogueId = 80120438,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B75C",
          NextDialogue = 80120439,
          SpeakNpcId = 93301,
          Subtitle = "That's when I realised... Even with me feeding her, Plumpytail would still try her best to hunt, because that was her way of living.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B75C"
        },
        [80120439] = {
          ContentES = "Y yo también tenía mi forma de vivir, pero era demasiado cobarde para enfrentar mi vida en la ciudad, siempre pensando en volver corriendo con Colagorda. ¡Pff, qué miedosa era!",
          DialogueId = 80120439,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B786",
          NextOptions = {
            [1] = 801204391,
            [2] = 801204401
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "And I had my way of living too, but I was too chicken to face my life in the city, always thinking of running back to Plumpytail — ugh, I was such a coward!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B786"
        },
        [80120440] = {
          ContentES = "Sí. Así que seguí su consejo y regresé. Pero hubo un pequeño problema...",
          DialogueId = 80120440,
          GUID = "C892B7B0",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120442,
          SpeakNpcId = 93301,
          Subtitle = "Yeah. So I listened to her advice and went back. But there was a slight mishap...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B7B0"
        },
        [80120441] = {
          ContentES = "Buaaa, ¡ya no me regañes! Ni siquiera el viejo Martin me dijo nada. Aunque, pensándolo bien, esa vez el viejo se preocupó bastante por mí porque pasó algo inesperado cuando regresaba...",
          DialogueId = 80120441,
          FacialId = {
            [1] = "93301:Pain01"
          },
          GUID = "C892B7DA",
          NextDialogue = 80120442,
          SpeakNpcId = 93301,
          Subtitle = "Waaah, I know I messed up... I'm sorry! Not even Old Martin scolded me for that! Speaking of which, the old man was actually worried sick for once, because I ran into a little trouble on the way back...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B7DA"
        },
        [80120442] = {
          ContentES = "¡Salí corriendo sin mirar por dónde iba! Le dije adiós a Colagorda, luego empecé a dar vueltas, cada vez más cansada, hasta quedarme dormida en la nieve...",
          DialogueId = 80120442,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B804",
          NextDialogue = 80120443,
          SpeakNpcId = 93301,
          Subtitle = "I was so mad when I ran out that I didn't even pay attention to remembering the way! So after I said goodbye to Plumpytail, I got lost... And I just kept walking, feeling more and more tired, until I fell asleep in the snow...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B804"
        },
        [80120443] = {
          ContentES = "Cuando desperté, sentí que me movía de un lado a otro. Resultó que el viejo me estaba cargando en la espalda. No era muy alto, pero su espalda era igual de fuerte que cuando era pequeña.",
          DialogueId = 80120443,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B82E",
          NextDialogue = 80120444,
          SpeakNpcId = 93301,
          Subtitle = "I woke up to a bumpy ride — turned out that stupid old man was carrying me on his back. He's not tall, but his back is as sturdy as it was when I was little.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B82E"
        },
        [80120444] = {
          ContentES = "Me sentí muy abrigada porque me había envuelto en varias capas de su bufanda, cubriéndome hasta la boca.",
          DialogueId = 80120444,
          GUID = "C892B858",
          NextDialogue = 80120445,
          SpeakNpcId = 93301,
          Subtitle = "I felt very warm because he had bundled me up in a long scarf, wrapping me in layer after layer, covering even my mouth, like Solas do.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B858"
        },
        [80120445] = {
          ContentES = "Y así fue como mi primera aventura fuera de Lago Helado terminó abruptamente.",
          DialogueId = 80120445,
          GUID = "C892B882",
          NextDialogue = 80120446,
          SpeakNpcId = 93301,
          Subtitle = "And that's how Margie's first adventure outside Icelake sloppily ended.",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B882"
        },
        [80120446] = {
          ContentES = "Desde entonces, estoy aprendiendo a vivir en Lago Helado, pero cada vez que surge un problema, ese viejo se burlaba de mí, y me llamaba “Pequeña Colagorda, la cazadora torpe”.",
          DialogueId = 80120446,
          GUID = "C892B8AC",
          NextDialogue = 80120447,
          SpeakNpcId = 93301,
          Subtitle = "Since then, I've been learning how to make a life for myself in Icelake. But every time I run into trouble, that stupid old man still teases me, calling me \"Can't-catch-anything Plumpytail Junior.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B8AC"
        },
        [80120447] = {
          ContentES = "¡Pero estaba equivocado! Colagorda se había convertido en una cazadora experta, y yo había aprendido a sobrevivir. Tal como dijiste: ambas habíamos crecido.",
          DialogueId = 80120447,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B8D6",
          NextOptions = {
            [1] = 801204471
          },
          SpeakNpcId = 93301,
          Subtitle = "But he's wrong! Plumpytail had already become a skilled hunter, and I've learned to survive here too — just like you said, we've both grown.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B8D6"
        },
        [80120448] = {
          ContentES = "¡Bueno, todo es culpa de Colagorda! ¿Por qué tuvo que irse tan pronto? Le rogué mil veces en mi mente que se quedara, y aun así se fue...",
          DialogueId = 80120448,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B900",
          NextDialogue = 80120449,
          SpeakNpcId = 93301,
          Subtitle = "Well, it's all Plumpytail's fault! Why did she have to leave so soon!? I must've begged her to stay a thousand times in my head, yet she still left before the sun even set...",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B900"
        },
        [80120449] = {
          ContentES = "¡Está bien, no más excusas! La próxima vez que vea a Colagorda, ¡me despediré con una sonrisa!",
          DialogueId = 80120449,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B92A",
          SpeakNpcId = 93301,
          Subtitle = "...Alright, no more excuses! Next time Plumpytail and I meet again, I'll see her off with a smile!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B92A"
        },
        [80130000] = {
          ContentES = "H-Hola… perdón si llegué en un mal momento…",
          DialogueId = 80130000,
          GUID = "C898D820",
          SpeakNpcId = 93103,
          Subtitle = "H—Hi... I hope I'm not being a bother...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898D820"
        },
        [80130101] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentES = "H-Hola…",
          DialogueId = 80130101,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E8B2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130102,
          SpeakNpcId = 93103,
          Subtitle = "H—Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E8B2"
        },
        [80130102] = {
          ContentES = "Me presento: Yo... me llamo Yale, soy de Río Escarlata... Tengo una pequeña tienda llamada Juguetería ¡Pum-pum!",
          DialogueId = 80130102,
          GUID = "C898E8DC",
          NextDialogue = 80130103,
          SpeakNpcId = 93103,
          Subtitle = "P—Please allow me to introduce myself. I... I'm Yale, from Scarletriver... I run a little shop called Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E8DC"
        },
        [80130103] = {
          ContentES = "En nuestra tienda, eh... ofrecemos una gran variedad de juguetes explosivos... que explotan de una forma divertida... A los niños de Río Escarlata les encantan...",
          DialogueId = 80130103,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898E906",
          NextDialogue = 80130104,
          SpeakNpcId = 93103,
          Subtitle = "We sell, um... little toys that explode... in a fun way! The kids in Scarletriver love them...",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E906"
        },
        [80130104] = {
          ContentES = "Este es el catálogo de nuestros productos. Si algo te interesa alguno, escríbenos. También hacemos entregas a domicilio.",
          DialogueId = 80130104,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E930",
          NextDialogue = 80130105,
          SpeakNpcId = 93103,
          Subtitle = "Here's a catalogue of our products. If anything catches your eye, just drop us a note. We do home delivery as well...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E930"
        },
        [80130105] = {
          ContentES = "Bueno… entonces me voy, ya se está haciendo tarde y podría ser peligroso.",
          DialogueId = 80130105,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898E95A",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801301051,
            [2] = 801301052
          },
          SpeakNpcId = 93103,
          Subtitle = "Er... I should get going. It's not safe to stay out too late...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E95A"
        },
        [80130106] = {
          ContentES = "Ehh… puedo quedarme un poco más…",
          DialogueId = 80130106,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E984",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          Subtitle = "O—Okay... I can stay a little longer...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E984"
        },
        [80130107] = {
          ContentES = "Tú… te ves un poco {性别:enfadado|enfadada}. ¿Es porque fui descortés? Lo siento, no fue a propósito…",
          DialogueId = 80130107,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E9AE",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          Subtitle = "You look upset... I—I'm sorry... Did I say something wrong? I didn't mean to...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9AE"
        },
        [80130108] = {
          ContentES = "Ay, ¡por todos los santos! ¡Hazte a un lado! ¿No juraste que esta vez no te acobardarías y qué presentarías nuestros juguetes en Lago Helado?",
          DialogueId = 80130108,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898E9D8",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130109,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh, for crying out loud — move over. Didn't you swear you wouldn't chicken out this time? That you'd pitch our toys to Icelake?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9D8"
        },
        [80130109] = {
          ContentES = "¡Y mírate ahora! Puf, parece que tendré que sacarte del apuro otra vez.",
          DialogueId = 80130109,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA02",
          NextDialogue = 80130110,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "And now look at you! Ugh, looks like I'll have to bail you out again.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA02"
        },
        [80130110] = {
          ContentES = "Perdón… cada vez que estoy cerca {性别:del famoso Phoxcazador|de la famosa Phoxcazadora} de Lago Helado, me da un poco de miedo y no sé cómo empezar...",
          DialogueId = 80130110,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA2C",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130111,
          SpeakNpcId = 93103,
          Subtitle = "I—I'm sorry... It's just... {性别：he|she}'s a really famous Phoxhunter in Icelake... I got nervous...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA2C"
        },
        [80130111] = {
          ContentES = "¿Miedo de que? escucha, {性别:él|ella} no va a hacerte daño. Solo háblale como si fuera uno de los niños que van a nuestra tienda.",
          DialogueId = 80130111,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA56",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801301111,
            [2] = 801301112
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Don't be a chicken. {性别：He|She}'s not gonna eat you alive. Just talk to {性别：him|her} like you talk to the kids at our shop.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA56"
        },
        [80130112] = {
          ContentES = "...",
          DialogueId = 80130112,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA80",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130113,
          SpeakNpcId = 93103,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA80"
        },
        [80130113] = {
          ContentES = "Eso no me dio miedo… Solo querías ayudarme a relajarme, ¿verdad? Gracias.",
          DialogueId = 80130113,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EAAA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          Subtitle = "That wasn't scary at all. You were just trying to help me relax, right? Thank you...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAAA"
        },
        [80130114] = {
          ContentES = "¿Del tipo sanador...? Nunca había oído eso antes, pero definitivamente no eres {性别:el Phoxcazador|la Phoxcazadora} que imaginaba, ya sabes, enorme y {性别:estrepitoso|estrepitosa} como una bomba...",
          DialogueId = 80130114,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898EAD4",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          Subtitle = "H...heartwarming type...? I've never heard of that type before, but you're definitely not what I pictured — you know, huge, louder than a bomb...",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAD4"
        },
        [80130115] = {
          ContentES = "Eh, entonces, déjame presentarte a mi amigo Oliver. Vive dentro de esta bomba, un alquimista lo encerró allí.",
          DialogueId = 80130115,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EAFE",
          NextDialogue = 80130116,
          SpeakNpcId = 93103,
          Subtitle = "Anyway, let me introduce my friend. This is Oliver. He, um, lives in this bomb. An alchemist sealed him inside...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAFE"
        },
        [80130116] = {
          ContentES = "Gestionamos la juguetería ¡Pum-pum! juntos: yo atiendo a los clientes, y él crea nuevos productos.",
          DialogueId = 80130116,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EB28",
          NextDialogue = 80130117,
          SpeakNpcId = 93103,
          Subtitle = "We run Snap 'n' Spark together: I serve customers, and he comes up with new products.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB28"
        },
        [80130117] = {
          ContentES = "Sinceramente, Yale se bloquea a menudo al hablar, así que tengo que tomar el relevo con frecuencia, como hoy.",
          DialogueId = 80130117,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB52",
          NextDialogue = 80130118,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Let's be real — Yale freezes halfway through his pitch more often than not, so I end up handling the talking too, like today.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB52"
        },
        [80130118] = {
          ContentES = "Tal y como Yale lo mencionó, vendemos pequeños juguetes explosivos. Los tres más vendidos del mes pasado fueron: el Dirigible Bum, el Cohete Silbador y el Carrusel Explosivo.",
          DialogueId = 80130118,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB7C",
          NextOptions = {
            [1] = 801301181,
            [2] = 801301182
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "He already mentioned we sell explosive little toys. Last month's top three sellers were: Boom-Blimp, Whizpop Firework, and Kaboom-Spinner.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB7C"
        },
        [80130119] = {
          ContentES = "¿Por qué la prisa?… aún no te mencionado nuestros productos más explosivos.",
          DialogueId = 80130119,
          GUID = "C898EBA6",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Tsk, hear me out first — I haven't even gotten to the real boom yet!",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBA6"
        },
        [80130120] = {
          ContentES = "Mmm… ¿así que estás interesado, eh? Bueno, eso fue solo el calentamiento. Lo que realmente queremos mostrarte es esto:",
          DialogueId = 80130120,
          GUID = "C898EBD0",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Heh... so you're interested, huh? Well, those were just the warm-up. What we really want to show you is this—",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBD0"
        },
        [80130121] = {
          ContentES = "Parece un simple despertador, ¿eh? Pero en realidad es una bomba de alta potencia, capaz de hacer volar por los aires todo lo que te fastidie. Te presentamos: La Destrozaestrellas.",
          DialogueId = 80130121,
          GUID = "C898EBFA",
          NextDialogue = 80130122,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Looks like an ordinary alarm clock, right? But just one of these — and boom, all your troubles go up in smoke. Introducing: the Starshatterer.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBFA"
        },
        [80130122] = {
          ContentES = "Incluso en Río Escarlata se escucha hablar de ti. Estoy seguro que {性别:un Phoxcazador|una Phoxcazadora} tan increíble como tú podría usar un poco de potencia extra.",
          DialogueId = 80130122,
          GUID = "C898EC24",
          NextDialogue = 80130123,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Word about you's even made it to Scarletriver. Bet an awesome Phoxhunter like you could use a little extra firepower.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC24"
        },
        [80130123] = {
          ContentES = "Si te cuesta recordar el nombre, también puedes llamarlo Pequeño Bum, como suelo llamarlo yo. Ayuda a despistar a los soldados del Imperio y así piensan que es solo un juguete para niños.",
          DialogueId = 80130123,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EC4E",
          NextDialogue = 80130124,
          SpeakNpcId = 93103,
          Subtitle = "If the name's too hard to remember, you can just call them Tot Poppers. That's what I call them... it helps throw off Empire soldiers... makes them think it's just some kid's toy, so they drop their guard.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC4E"
        },
        [80130124] = {
          ContentES = "Los dibujos en las carcasas los hice yo. Sirven para que estas bombas no se vean tan aterradoras.",
          DialogueId = 80130124,
          GUID = "C898EC78",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130125,
          SpeakNpcId = 93103,
          Subtitle = "And the little drawings on the casings — they're also from me... This way the bombs look a bit less scary...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC78"
        },
        [80130125] = {
          ContentES = "¿Cuántas veces tengo que decirlo? Los que compran bombas lo hacen por el gran ¡BOOM!, no por los adornos",
          DialogueId = 80130125,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECA2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130126,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ugh. How many times do I have to say it? People who buy bombs just want a good BOOM, not some cutesy nonsense.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECA2"
        },
        [80130126] = {
          ContentES = "Creo que los dibujos hacen que nuestros productos destaquen. Y, cuando los dibujaba, tú no parabas de darme consejos sobre cómo hacerlos más adorables…",
          DialogueId = 80130126,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ECCC",
          NextDialogue = 80130127,
          SpeakNpcId = 93103,
          Subtitle = "But I think the drawings make our products stand out. And when I was sketching them, you were the one shouting all those tips about how to make them even cuter...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECCC"
        },
        [80130127] = {
          ContentES = "E…eso es porque, si los vas a dibujar, ¡tienes que dibujarlos bien! Si salen feos, ¡nadie va a querer comprarlos!",
          DialogueId = 80130127,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECF6",
          NextDialogue = 80130128,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I... I only did that so you wouldn't botch it, all right? If the logo's ugly, no one's gonna buy them — duh!",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECF6"
        },
        [80130128] = {
          ContentES = "Bueno, bueno. Ya te contamos todo. Si quieres hacer un pedido, solo envíanos un mensaje.",
          DialogueId = 80130128,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED20",
          NextDialogue = 80130129,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ahem. Anyway — that's our big sales pitch. If you'd like to place an order, just send us a note.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED20"
        },
        [80130129] = {
          ContentES = "Eso sí, no olvides poner Pequeño Bum en tu mensaje, o el Imperio podría darse cuenta.",
          DialogueId = 80130129,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED4A",
          NextDialogue = 80130130,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But make sure you write Tot Poppers on your order, not Starshatterers. Otherwise... we'll both be in hot water.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED4A"
        },
        [80130130] = {
          ContentES = "La dirección de la tienda está en el catálogo. Esperamos tu pedido...",
          DialogueId = 80130130,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ED74",
          NextDialogue = 80130131,
          SpeakNpcId = 93103,
          Subtitle = "Our shop address is on the catalogue. We'll be waiting for your order...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED74"
        },
        [80130131] = {
          ContentES = "Yale y Oliver, del Río Escarlata, hacen un dúo fantástico. Cuando tengas tiempo, compra algunos de sus juguetes: el Cohete Silbador y el Carrusel Explosivo suenan muy divertidos…",
          DialogueId = 80130131,
          GUID = "C898ED9E",
          Subtitle = "Yale and Oliver — the unforgettable duo from Scarletriver. If you ever have the chance, why not pick up a few of their creations? Those Kaboom Spinners and Whizpop Fireworks sound like an absolute blast...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED9E"
        },
        [80130201] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentES = "Hola...",
          DialogueId = 80130201,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F91A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130202,
          SpeakNpcId = 93103,
          Subtitle = "Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F91A"
        },
        [80130202] = {
          ContentES = "¿Me recuerdas? Soy Yale, de la Juguetería ¡Pum-pum!",
          DialogueId = 80130202,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898F944",
          NextOptions = {
            [1] = 801302021,
            [2] = 801302022
          },
          SpeakNpcId = 93103,
          Subtitle = "Do you remember me? I'm Yale, from Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F944"
        },
        [80130203] = {
          ContentES = "Bueno… en aquel entonces no nos conocíamos, ahora es diferente.",
          DialogueId = 80130203,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F96E",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Th—That was because we barely knew each other then. It's better now.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F96E"
        },
        [80130204] = {
          ContentES = "Mmm… es cierto que él siempre ha sido mucho mejor para hablar que yo.",
          DialogueId = 80130204,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F998",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Mm... He's always been much better at talking than I am.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F998"
        },
        [80130205] = {
          ContentES = "Hoy tengo motivos para venir solo.",
          DialogueId = 80130205,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898F9C2",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130206,
          SpeakNpcId = 93103,
          Subtitle = "I came by myself today, though.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9C2"
        },
        [80130206] = {
          ContentES = "No es que estemos peleados ni nada de eso, Oliver y yo nos llevamos muy bien. Y es por eso que hay cosas que no puedo contarle.",
          DialogueId = 80130206,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898F9EC",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130207,
          SpeakNpcId = 93103,
          Subtitle = "It's not that we had a fight or anything — Oliver and I get along just fine. Which... might be exactly why there are things I can't quite say to him.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9EC"
        },
        [80130207] = {
          ContentES = "Así que... pensé que quizá... podría contártelo a ti. Y no te preocupes, no vengo a pedirte consejo. Solo... necesito que alguien me escuche. Y… pareces ser alguien que sabe escuchar...",
          DialogueId = 80130207,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FA16",
          NextDialogue = 80130208,
          SpeakNpcId = 93103,
          Subtitle = "So... I thought maybe... I could tell you instead. N—No pressure — I'm not here asking for advice. I... just need someone to listen. And... you seemed like a good listener.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA16"
        },
        [80130208] = {
          ContentES = "Verás, en realidad los primeros dueños de la Juguetería ¡Pum-pum! No fuimos ni Oliver ni yo, sino un anciano de muy mal carácter.",
          DialogueId = 80130208,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FA40",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130209,
          SpeakNpcId = 93103,
          Subtitle = "I never told you this, but Snap 'n' Spark wasn't ours to begin with. It belonged to a very, very grumpy old man.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA40"
        },
        [80130209] = {
          ContentES = "No tenía paciencia y siempre me obligaba a hacer esto o aquello, pero yo nunca lo hacía bien.... Con el tiempo, aprendí cómo manejar la tienda.",
          DialogueId = 80130209,
          FacialId = {
            [1] = "93103:Unhappy01"
          },
          GUID = "C898FA6A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130210,
          SpeakNpcId = 93103,
          Subtitle = "He yelled a lot... always bossing me around. I messed up a lot of things at first... But after a while, even through all the shouting... I started to pick up how to run the place.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA6A"
        },
        [80130210] = {
          ContentES = "Y un día, de repente, me dijo que tenía que irse muy lejos... y me dejó a cargo de la tienda.",
          DialogueId = 80130210,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FA94",
          NextDialogue = 80130211,
          SpeakNpcId = 93103,
          Subtitle = "Then one day he simply announced he was off somewhere far away — and left the place to me.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA94"
        },
        [80130211] = {
          ContentES = "Después de eso, me quedé solo. Sin él, realmente no sabía cómo diseñar nuevos juguetes. Así que seguí vendiendo el inventario que quedaba.",
          DialogueId = 80130211,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FABE",
          NextOptions = {
            [1] = 801302111,
            [2] = 801302112
          },
          SpeakNpcId = 93103,
          Subtitle = "After that, it was just me. Without him there... I didn't really know how to make new toys anymore. So I just kept selling whatever stock he'd left behind...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FABE"
        },
        [80130212] = {
          ContentES = "Mmm… sí, pienso lo mismo, fue muy extraño, todo pasó tan de repente.",
          DialogueId = 80130212,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FAE8",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "I... I didn't understand it either. It all happened so suddenly.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FAE8"
        },
        [80130213] = {
          ContentES = "Gracias… en realidad me esforcé mucho por aprender todo.",
          DialogueId = 80130213,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FB12",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "Thank you... I really did try my best to learn everything I could back then.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB12"
        },
        [80130214] = {
          ContentES = "En fin... pasaron unos meses. Más padres llegaron con sus hijos, y el negocio finalmente empezó a mejorar...",
          DialogueId = 80130214,
          FacialId = {
            [1] = "93103:Happy01"
          },
          GUID = "C898FB3C",
          NextDialogue = 80130215,
          SpeakNpcId = 93103,
          Subtitle = "Anyway... a few months passed. More parents came in with their kids, business was finally picking up...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB3C"
        },
        [80130215] = {
          ContentES = "Y entonces, un día, apareció un chico más o menos de mi edad. Pensé que era solo otro cliente, así que empecé a recomendarle juguetes.",
          DialogueId = 80130215,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FB66",
          NextDialogue = 80130216,
          SpeakNpcId = 93103,
          Subtitle = "Then one day a boy about my age showed up. I thought he was just another customer, so I started recommending toys.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB66"
        },
        [80130216] = {
          ContentES = "Sin embargo, él me habló con frialdad y me dijo: “La tienda ni siquiera era del viejo, él se la robó”.",
          DialogueId = 80130216,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FB90",
          NextDialogue = 80130217,
          SpeakNpcId = 93103,
          Subtitle = "But he just looked at me and said, in this cold voice, that Snap 'n' Spark wasn't the old man's shop at all — that he had stolen it from him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB90"
        },
        [80130217] = {
          ContentES = "Al principio no le creí. Pero luego se dirigió directamente al taller, tomó las herramientas como si las hubiera estado usando toda la vida...",
          DialogueId = 80130217,
          GUID = "C898FBBA",
          NextDialogue = 80130218,
          SpeakNpcId = 93103,
          Subtitle = "I didn't believe him at first. But then he marched straight to the workbench, picked up the tools like he'd been using them forever...",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBBA"
        },
        [80130218] = {
          ContentES = "Yo quería decirle que esos explosivos eran peligrosos, pero en un par de movimientos ya había hecho una bomba, y su técnica era mucho mejor que la del anciano.",
          DialogueId = 80130218,
          GUID = "C898FBE4",
          NextDialogue = 80130219,
          SpeakNpcId = 93103,
          Subtitle = "I tried to warn him that the materials were dangerous and not to mess with them — but before I could even finish, he had already put together a bomb. Faster than the old man ever could.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBE4"
        },
        [80130219] = {
          ContentES = "Me miró con un tono muy desagradable y me dijo que el viejo era un ladrón... y que yo también lo era.",
          DialogueId = 80130219,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FC0E",
          NextDialogue = 80130220,
          SpeakNpcId = 93103,
          Subtitle = "He looked at me — and, in this really harsh, accusing voice — said the old man was a thief... and that I was one too.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC0E"
        },
        [80130220] = {
          ContentES = "Aunque no quería admitirlo, viendo la manera como que se movía por la tienda, me parecía evidente que realmente era el autentico dueño de la tienda.",
          DialogueId = 80130220,
          GUID = "C898FC38",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130221,
          SpeakNpcId = 93103,
          Subtitle = "I didn't want to believe him. But the way he handled everything... it felt like... he really belonged there. Like he was the real owner all along.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC38"
        },
        [80130221] = {
          ContentES = "Así que... yo...",
          DialogueId = 80130221,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FC62",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302211,
            [2] = 801302212
          },
          SpeakNpcId = 93103,
          Subtitle = "So... now I...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC62"
        },
        [80130222] = {
          ContentES = "Sí, quiero saber si es cierto y si en realidad debería devolverle la tienda.",
          DialogueId = 80130222,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FC8C",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "Yes. If what he said is true... maybe I should give Snap 'n' Spark back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC8C"
        },
        [80130223] = {
          ContentES = "Si realmente es suya... lo correcto sería hacerlo.",
          DialogueId = 80130223,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FCB6",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "If he really was the owner... then I think I should.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCB6"
        },
        [80130224] = {
          ContentES = "La verdad es que tengo miedo. Pero... si él es el verdadero dueño de la Juguetería ¡Pum-pum!... ¿qué se supone que deba hacer?",
          DialogueId = 80130224,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FCE0",
          NextDialogue = 80130225,
          SpeakNpcId = 93103,
          Subtitle = "The truth is, I'm scared. B—but... if he really is the true owner of Snap 'n' Spark... what am I supposed to do?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCE0"
        },
        [80130225] = {
          ContentES = "Me he encariñado tanto con el lugar... Me costó acostumbrarme a recibir a los clientes, a recomendar juguetes, a hablar mejor con los niños... ¿Podrá él hacer todo eso también?",
          DialogueId = 80130225,
          GUID = "C898FD0A",
          NextDialogue = 80130226,
          SpeakNpcId = 93103,
          Subtitle = "I've grown so attached to the place... I worked really hard — learning how to greet customers, recommend toys, get better at talking to other kids... Could he do all that too?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD0A"
        },
        [80130226] = {
          ContentES = "Y si siempre fue su tienda... ¿cómo podría compensárselo? No sé por qué se fue en primer lugar, pero... simplemente se siente mal.",
          DialogueId = 80130226,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FD34",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130227,
          SpeakNpcId = 93103,
          Subtitle = "And if it was his shop all along... how could I ever make it up to him? I don't know why he left in the first place, but... it just feels wrong.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD34"
        },
        [80130227] = {
          ContentES = "Que te roben tu propia tienda, y luego volver para encontrar a un extraño detrás del mostrador... ni siquiera puedo imaginar lo terrible que debe sentirse...",
          DialogueId = 80130227,
          GUID = "C898FD5E",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302271
          },
          SpeakNpcId = 93103,
          Subtitle = "Imagine losing your own shop, then coming back to find a stranger behind the counter... I can't even picture how awful that must feel...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD5E"
        },
        [80130229] = {
          ContentES = "Sé exactamente lo que diría: gritarme, llamarme idiota, insistir en que ahora soy el dueño legítimo, y decirme que me concentre en gestionarlo mejor en lugar de entregarlo.",
          DialogueId = 80130229,
          FacialId = {
            [1] = "93103:Confident02"
          },
          GUID = "C898FDB2",
          NextDialogue = 80130230,
          SpeakNpcId = 93103,
          Subtitle = "I know exactly what he'd say: yell at me, call me an idiot, insist I'm the rightful owner now — tell me to focus on running it better instead of handing it over.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDB2"
        },
        [80130230] = {
          ContentES = "Seguro que tratará de impedírmelo… Pero bueno, aunque sea muy duro al hablar, en el fondo es una buen tipo.",
          DialogueId = 80130230,
          FacialId = {
            [1] = "93103:Syouganai01"
          },
          GUID = "C898FDDC",
          NextDialogue = 80130231,
          SpeakNpcId = 93103,
          Subtitle = "He'd definitely try to stop me... But I know — underneath it all, he's actually really kind.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDDC"
        },
        [80130231] = {
          ContentES = "Pero... ese chico también es una buena persona. Y no estoy de acuerdo en que a la gente buena siempre le deban pasar cosas malas. Alguien debería hacer lo correcto por él.",
          DialogueId = 80130231,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE06",
          NextDialogue = 80130232,
          SpeakNpcId = 93103,
          Subtitle = "But... that boy was a good person too. And I don't think good people should always get the short end of the stick. Someone ought to do right by him as well.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE06"
        },
        [80130232] = {
          ContentES = "Gracias por el té. Creo que ya sé lo que tengo que hacer. De verdad... gracias. Ahora debo regresar a Río Escarlata.",
          DialogueId = 80130232,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C898FE30",
          NextDialogue = 80130233,
          SpeakNpcId = 93103,
          Subtitle = "Thanks for the tea. I think I know what I need to do now. Really — thank you. I'll head back to Scarletriver.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE30"
        },
        [80130233] = {
          ContentES = "¡Ah! Y si aún quieres pedir algo de la Juguetería ¡Pum-pum! solo escríbeme una carta. La tienda seguirá abierta de todos modos.",
          DialogueId = 80130233,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE5A",
          NextDialogue = 80130234,
          SpeakNpcId = 93103,
          Subtitle = "Oh! And if you still want to order something from Snap 'n' Spark, just send a letter. The shop's staying open either way.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE5A"
        },
        [80130234] = {
          ContentES = "Yale se marcha rápidamente, es evidente que ha tomado la decisión de devolver la Juguetería ¡Pum-pum! a su verdadero dueño.",
          DialogueId = 80130234,
          GUID = "C898FE84",
          IsBlack = 1,
          Subtitle = "Yale hurries off — clearly, he's made up his mind to return Snap 'n' Spark to its rightful owner.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE84"
        },
        [80130301] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentES = "Ey, hola.",
          DialogueId = 80130301,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990982",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130302,
          SpeakNpcId = 93103,
          Subtitle = "Yo.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990982"
        },
        [80130302] = {
          ContentES = "¿Tienes un momento? ¿Podemos charlar?",
          DialogueId = 80130302,
          GUID = "C89909AC",
          NextOptions = {
            [1] = 801303021,
            [2] = 801303022
          },
          SpeakNpcId = 93103,
          Subtitle = "Got a minute?",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909AC"
        },
        [80130303] = {
          ContentES = "Je, no soy ese tonto.",
          DialogueId = 80130303,
          GUID = "C89909D6",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          Subtitle = "Tch. I'm not that idiot.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909D6"
        },
        [80130304] = {
          ContentES = "Bah. Ya me cansé de jugar al “juego de la bomba”.",
          DialogueId = 80130304,
          GUID = "C8990A00",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          Subtitle = "Duh. I'm done playing \"say hello to my talking bomb.\"",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A00"
        },
        [80130305] = {
          ContentES = "Soy Oliver, Oliver Kuzka. No una extraña criatura encerrada en una bomba.",
          DialogueId = 80130305,
          GUID = "C8990A2A",
          NextDialogue = 80130306,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Name's Oliver. Oliver Kuzka. Not some fantastic creature holed up inside a bomb.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A2A"
        },
        [80130306] = {
          ContentES = "Probablemente no has escuchado ese nombre antes, pero no importa. Recuerda bien: si alguna vez pasas por Dismania, dirígete quince kilómetros más allá de la puerta norte. Allí encontrarás una fortaleza en ruinas. Mi obra maestra.",
          DialogueId = 80130306,
          GUID = "C8990A54",
          NextDialogue = 80130307,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "You probably haven't heard the name. Doesn't matter. Just remember it. If you ever swing by Dismania, head fifteen kilometres out from the north gate. You'll find a ruined fortress. My signature work.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A54"
        },
        [80130307] = {
          ContentES = "En cuanto a por qué estoy aquí... eso depende. Dime, ¿qué te dijo Yale la última vez que se vieron?",
          DialogueId = 80130307,
          GUID = "C8990A7E",
          NextOptions = {
            [1] = 801303071,
            [2] = 801303072
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "As for why I'm here... That depends. Tell me — what did Yale say to you last time he was here?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A7E"
        },
        [80130308] = {
          ContentES = "Ja. Eres más {性别:duro|dura} de lo que pareces, me gusta así. Solo cooperas si te lo piden bien, ¿eh? Supongo que somos del mismo tipo.",
          DialogueId = 80130308,
          GUID = "C8990AA8",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Hah. Tougher than you look — I like that. You only play along when asked nicely, huh? Guess we're the same type.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AA8"
        },
        [80130309] = {
          ContentES = "Está bien, me gusta que hablen así, directo y sin rodeos.",
          DialogueId = 80130309,
          GUID = "C8990AD2",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Fair enough. I like straight talk.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AD2"
        },
        [80130310] = {
          ContentES = "La verdad, entonces. Pero te aviso, es una historia larga.",
          DialogueId = 80130310,
          GUID = "C8990AFC",
          NextDialogue = 80130311,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "The truth, then. But fair warning — it's a long story.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AFC"
        },
        [80130311] = {
          ContentES = "Como ya dije: me llamo Oliver Kuzka, el verdadero propietario de este cuerpo. Y el mejor fabricante de bombas que jamás conocerás.",
          DialogueId = 80130311,
          GUID = "C8990B26",
          NextDialogue = 80130312,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Like I said — I'm Oliver Kuzka, the real owner of this body. And the best damn bomb maker you'll ever meet.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B26"
        },
        [80130312] = {
          ContentES = "En aquel entonces yo apenas era un mocoso. Pensaba que podía hacer volar por los aires todo el Imperio con mis pequeños juguetes. Ni siquiera me detuve a pensar qué pasaría si me atrapaban... o quizás simplemente supuse que no pasaría.",
          DialogueId = 80130312,
          GUID = "C8990B50",
          NextDialogue = 80130313,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Back then, I was barely more than a kid myself. Thought I could blow the whole Empire sky-high with my little toys. Never even stopped to think what'd happen if I got caught... or maybe I just figured it wouldn't happen.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B50"
        },
        [80130313] = {
          ContentES = "Así que cuando la Legión finalmente me atrapó, no tenía ni idea de lo que venía.",
          DialogueId = 80130313,
          GUID = "C8990B7A",
          NextDialogue = 80130314,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So when the Legion finally bagged me, I had no clue what was coming.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B7A"
        },
        [80130314] = {
          ContentES = "Me llevaron a un laboratorio de la Academia Spathatoi y me sentaron frente a un anciano de aspecto amigable llamado Jones.",
          DialogueId = 80130314,
          GUID = "C8990BA4",
          NextDialogue = 80130315,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "They hauled me off to some Spathatoi lab and sat me in front of this kindly looking old man called Jones.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BA4"
        },
        [80130315] = {
          ContentES = "Hablaba con mucha suavidad, decía que el crimen era solo un “tropiezo mental” curable con la medicación adecuada. Tonterías.",
          DialogueId = 80130315,
          GUID = "C8990BCE",
          NextDialogue = 80130316,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Spoke real gentle, that one — kept saying crime was just \"a mental hiccup\" curable with right medication. Rubbish.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BCE"
        },
        [80130316] = {
          ContentES = "No pasaba hambre, de verdad. Pero me obligaban a tomar medicamentos y me sometían a innumerables revisiones. La medicina no sabía mal, pero cada vez que la tomaba sentía que mi mente empezaba a ralentizarse… y poco a poco empezaba a olvidar muchas cosas..",
          DialogueId = 80130316,
          GUID = "C8990BF8",
          NextDialogue = 80130317,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "They didn't starve me, not really. Fed me fine, even. But they did force drugs down my throat and ran endless \"check-ups.\" The stuff didn't taste bad, but after every dose, my thoughts would slow to a crawl... and little by little, my memories started slipping away.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BF8"
        },
        [80130317] = {
          ContentES = "Al principio todavía me quedaba energía para soltarle groserías a ese viejo con malas intenciones, pero a medida que tomaba sus “medicinas”, poco a poco fui olvidando cómo maldecir.",
          DialogueId = 80130317,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990C22",
          NextDialogue = 80130318,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "At first, I still had enough fire left to cuss that shady codger out — but the more meds I swallowed, the harder it was to remember the curse words.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C22"
        },
        [80130318] = {
          ContentES = "Alguien dijo una vez: “un hombre que nunca maldice es un hombre que ha perdido su voz”.",
          DialogueId = 80130318,
          GUID = "C8990C4C",
          NextDialogue = 80130319,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Someone once said: a man who never swears is a man who's lost his voice.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C4C"
        },
        [80130319] = {
          ContentES = "Pero eso era solo el comienzo. Poco a poco empecé a olvidar cómo caminar… cómo mover las manos, e incluso cómo respirar.",
          DialogueId = 80130319,
          GUID = "C8990C76",
          NextDialogue = 80130320,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "And that was only the beginning. Slowly, I forgot how to walk straight, how to grip things — even how to breathe.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C76"
        },
        [80130320] = {
          ContentES = "Sabía que había algo malo en las “medicinas” que me daba, pero cuando las tomaba no podía recordar cómo escupirlas. Solo podía quedarme quieto, y sentir cómo mis recuerdos se disolvían uno a uno. Habría preferido estallar en mil pedazos...",
          DialogueId = 80130320,
          GUID = "C8990CA0",
          NextDialogue = 80130321,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I knew there was something wrong with those drugs. But every time they poured something down my throat, I couldn't even remember how to spit it out. All I could do was sit there and watch my memories dissolve. I'd have preferred being blown to bits.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CA0"
        },
        [80130321] = {
          ContentES = "Al final, me convertí en un simple espectador, que miraba el cuerpo de Oliver Kuzka en el espejo… y no podía reconocerse a sí mismo.",
          DialogueId = 80130321,
          GUID = "C8990CCA",
          NextDialogue = 80130322,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "In the end, all that was left of me was a shadow — watching some puppet called \"Oliver Kuzka\" move in the mirror, without a clue who the hell he was anymore.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CCA"
        },
        [80130322] = {
          ContentES = "Hasta que un día, ese viejo infeliz entró, se dirigió a este cuerpo y dijo: “Tu nombre es Yale.”",
          DialogueId = 80130322,
          GUID = "C8990CF4",
          NextDialogue = 80130323,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Until one day, that old bastard walked in, stared at my body, and said: \"Your name is Yale.\"",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CF4"
        },
        [80130323] = {
          ContentES = "Así que él es Yale… ¿pero entonces quién demonios soy yo?",
          DialogueId = 80130323,
          GUID = "C8990D1E",
          NextOptions = {
            [1] = 801303231,
            [2] = 801303232
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So he's Yale... then who the hell am I?",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D1E"
        },
        [80130324] = {
          ContentES = "No es raro que no lo entiendas, a mí también me tomó un buen tiempo comprenderlo. Jones… había creado una segunda personalidad en mi cuerpo.",
          DialogueId = 80130324,
          GUID = "C8990D48",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Figures. Took me a while, too. Jones... he created a new alter ego inside my body.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D48"
        },
        [80130325] = {
          ContentES = "Sí, creó una segunda personalidad, con la intención de borrar por completo al Charon criminal llamado Oliver Kuzka.",
          DialogueId = 80130325,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990D72",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Too right. He created a new alter ego inside my body — meant to overwrite the Charon criminal named Oliver Kuzka.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D72"
        },
        [80130326] = {
          ContentES = "Pero hay que reconocerlo. Sin Yale, habría perdido el control de mi cuerpo para siempre. Por más que luchara, no podía mover ni un dedo.",
          DialogueId = 80130326,
          GUID = "C8990D9C",
          NextDialogue = 80130327,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But I'll give it to him — without Yale, I'd have lost control of my body forever. No matter how hard I fought, I couldn't move a finger.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D9C"
        },
        [80130327] = {
          ContentES = "No obstante, mis pensamientos podían llegar hasta él. Cada vez que pensaba que “Eres una imitación”, se encogía como una codorniz asustada, mirando a todos lados y agachando la cabeza.",
          DialogueId = 80130327,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990DC6",
          NextDialogue = 80130328,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But my thoughts could get through to him. Every time I so much as thought \"You're a knock-off,\" he'd flinch like a startled quail — eyes darting, shoulders hunched.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DC6"
        },
        [80130328] = {
          ContentES = "Te puedes imaginar cuánto lo odiaba. Pasaba mis días maldiciéndolo con lo que me quedaba de insultos.",
          DialogueId = 80130328,
          GUID = "C8990DF0",
          NextDialogue = 80130329,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "You can imagine how much I hated him back then. I spent every waking second hurling every insult I could still remember at him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DF0"
        },
        [80130329] = {
          ContentES = "Para él, yo no era más que una voz desquiciada en su cabeza.",
          DialogueId = 80130329,
          GUID = "C8990E1A",
          NextDialogue = 80130330,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "To him, I must have been just a crazy voice in his head.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E1A"
        },
        [80130330] = {
          ContentES = "Intentó expulsarme, pero ¿cómo podría haber perdido? Este cuerpo es mío.",
          DialogueId = 80130330,
          GUID = "C8990E44",
          NextDialogue = 80130331,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "He tried to shut me out, of course. But how could he? That body was mine.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E44"
        },
        [80130331] = {
          ContentES = "Entonces ese desgraciado viejo se dio cuenta. Le preguntó a Yale si alguna vez había oído el nombre de “Oliver”.",
          DialogueId = 80130331,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990E6E",
          NextDialogue = 80130332,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Then that old bastard caught on. He asked Yale if he'd ever heard the name \"Oliver.\"",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E6E"
        },
        [80130332] = {
          ContentES = "Yale lo negó todo. Jones lo miró fijamente a los ojos… como si pudiera verme escondido allí detrás.",
          DialogueId = 80130332,
          GUID = "C8990E98",
          NextDialogue = 80130333,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Yale denied it. But Jones just kept staring into his eyes... like he could see me hiding behind them.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E98"
        },
        [80130333] = {
          ContentES = "Luego, Jones le trajo a Yale un tocadiscos. Y en cuanto esa máquina empezaba a sonar, yo perdía por completo la conciencia, como si una vela se apagara en la oscuridad.",
          DialogueId = 80130333,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990EC2",
          NextDialogue = 80130334,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "After that, Jones wheeled in a record player. Each time the needle dropped and the music started, I blacked out— like someone snuffing a candle.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EC2"
        },
        [80130334] = {
          ContentES = "Sabía que el tocadiscos y la música eran su nuevo truco para dejarme inconsciente, de modo que Yale pudiera llevarse mi cuerpo para siempre.",
          DialogueId = 80130334,
          GUID = "C8990EEC",
          NextDialogue = 80130335,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I knew the record player and the music was his new trick to wipe me out, so Yale could take the body for good.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EEC"
        },
        [80130335] = {
          ContentES = "Pensé que en esos ciclos de sueño y vigilia perdería por completo la memoria, pero un día, de repente, Yale me dijo que ya no quería escuchar esa música.",
          DialogueId = 80130335,
          GUID = "C8990F16",
          NextDialogue = 80130336,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Caught in that endless loop of blackouts and brief flashes of waking, I figured I'd lose everything — memories, thoughts, even the last scraps of who I was. But then, one day, I heard Yale's voice, telling me he didn't want to listen to the music any more.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F16"
        },
        [80130336] = {
          ContentES = "Fue entonces cuando me di cuenta: la “imitación” que no paraba de maltratar... era una persona real. Así que hicimos un trato. Trazamos un plan. Y escapamos del laboratorio de ese viejo bastardo para siempre.",
          DialogueId = 80130336,
          GUID = "C8990F40",
          NextDialogue = 80130337,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "That's when it hit me: the \"knock-off\" I kept abusing... was a real person. So we made a deal. Put together a plan. And broke out of that old bastard's lab for good.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F40"
        },
        [80130337] = {
          ContentES = "Al final, llegamos a Río Escarlata y abrimos juntos una tienda de juguetes. Yale le puso ese nombre estúpido: “¡Pum-pum!”. Desde entonces, nunca más mencionamos lo del laboratorio.",
          DialogueId = 80130337,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990F6A",
          NextDialogue = 80130338,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "We made it to Scarletriver and opened a toy shop. He named it Snap 'n' Spark — stupid name, if you ask me — and we never spoke of the lab again.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F6A"
        },
        [80130338] = {
          ContentES = "Hace unos días volví a perder el conocimiento, esa misma sensación familiar. Pensé que se había drogado para apagarme. No tengo idea de lo que hizo mientras yo estaba inconsciente, así que pregunté por ahí. Resulta que se había ido de viaje a Lago Helado.",
          DialogueId = 80130338,
          GUID = "C8990F94",
          NextDialogue = 80130339,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Couple days ago, I blacked out again — that same old, familiar feeling. Figured he must've dosed himself to shut me down. No idea what he got up to while I was under, so I asked around. Turns out he'd taken a trip to Icelake.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F94"
        },
        [80130339] = {
          ContentES = "En realidad yo lo conozco mejor que a nadie, es tímido e introvertido, pero también se que es demasiado amable para su propio bien. No es el tipo de persona que me haría algo a mis espaldas.",
          DialogueId = 80130339,
          GUID = "C8990FBE",
          NextDialogue = 80130340,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Thing is, I know him better than anyone — timid, shy... but too kind and soft for his own good. Definitely not the type to pull a stunt behind my back — not unless something was eating at him.",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FBE"
        },
        [80130340] = {
          ContentES = "Por eso, tomé la medicina que pone mi otra personalidad en reposo, necesito saber qué dijo a mis espaldas.",
          DialogueId = 80130340,
          GUID = "C8990FE8",
          NextOptions = {
            [1] = 801303401
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So I took the meds myself, knocked him out, and came here. I need to know what he said behind my back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FE8"
        },
        [80130341] = {
          ContentES = "(Relata la historia de Yale, de la Juguetería ¡Pum-pum! y del misterioso antiguo dueño, que en realidad es una metáfora sobre su propio cuerpo y el de Oliver).",
          DialogueId = 80130341,
          GUID = "C8991012",
          IsBlack = 1,
          NextDialogue = 80130342,
          Subtitle = "(You recount Yale's tale about Snap 'n' Spark and the mysterious former shopkeeper, which, in fact, is a metaphor of his very body and its true owner.)",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991012"
        },
        [80130342] = {
          ContentES = "Entonces... ¿¡me drogó, y vino aquí para devolverme mi cuerpo!?",
          DialogueId = 80130342,
          GUID = "C899103C",
          NextDialogue = 80130343,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So... he drugged me, came here, and decided to give the body back to me!?",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899103C"
        },
        [80130343] = {
          ContentES = "¡Ese... ese idiota... ese inútil debilucho!",
          DialogueId = 80130343,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8991066",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801303431,
            [2] = 801303432
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "That... that idiot... that hopeless, soft-hearted wimp!",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991066"
        },
        [80130344] = {
          ContentES = "... Muy gracioso, ahora solo necesito esperar a que se despierte y que podamos aclarar todo esto.",
          DialogueId = 80130344,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8991090",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "...Hilarious. What I need to do now is wait for him to wake up, so that we can sort all this out.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991090"
        },
        [80130345] = {
          ContentES = "No lo sé. De cualquier manera, me quedaré hasta que despierte, y aclararemos con él todo lo que pasó.",
          DialogueId = 80130345,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C89910BA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Maybe. Maybe not. Either way, I'm staying put till he wakes, and we'll sort it out.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910BA"
        },
        [80130346] = {
          ContentES = "A propósito, gracias por escucharme. Cuando Yale despierte... si se pone testarudo, tal vez necesite tu ayuda para tranquilizarlo.",
          DialogueId = 80130346,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C89910E4",
          NextDialogue = 80130347,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Thanks, by the way, for hearing me out. When Yale wakes up... if he turns out to be too stubborn, I might need you to back me up.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910E4"
        },
        [80130347] = {
          ContentES = "Oliver se queda sentado en la silla, muy inquieto, rebotando una pierna sin parar. Parece que va a pasar un buen rato para que Yale despierte…",
          DialogueId = 80130347,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C899110E",
          IsBlack = 1,
          Subtitle = "Oliver sits restlessly, one leg bouncing non-stop. It looks like it'll be a while before Yale wakes up...",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899110E"
        },
        [80130401] = {
          Camera = "-49.926758,-243.0,161.0,0.000036,-19.199852,68.998772,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿En dónde... estoy?",
          DialogueId = 80130401,
          FacialId = {
            [1] = "790023:Smile01"
          },
          FinalCamera = "-49.926758,-249.212219,161.0,0.000036,-19.199852,68.998741,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89919EA",
          NextDialogue = 80130402,
          SpeakNpcId = 790023,
          Subtitle = "Where am I...?",
          TalkActionId = {
            [1] = "790023:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Yeer/004/C89919EA"
        },
        [80130402] = {
          Camera = "-75.0,-188.0,153.0,0.000051,-4.999999,-66.802383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Es tan brillante… tan cálido… no se parece al lugar que suelo soñar, donde siempre hay luces encendidas, pero se siente un frío que cala hasta los huesos.",
          DialogueId = 80130402,
          FinalCamera = "-58.0,-188.0,153.0,0.000051,-4.999999,-66.802383,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8991A14",
          LookAt = {
            [1] = "100001:n(790023)"
          },
          NextDialogue = 80130403,
          Scripts = "SetLocation{ActorId{100001},TargetPoint{\"TargetPoint_Nvzhu\"},Visibility{\"Show\"}}",
          SpeakNpcId = 790023,
          Subtitle = "So bright... and warm... Not like the place in my dreams— lights always on, yet freezing cold.",
          TalkActionId = {
            [1] = "790023:Talk03_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991A14"
        },
        [80130403] = {
          Camera = "79.0,-274.0,116.0,0.0,0.0,110.998604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "Ah… {nickname}, eres tú. ¿Estoy en Lago Helado? ¿Cómo es que llegue aquí...?",
          DialogueId = 80130403,
          GUID = "C8991A3E",
          LookAt = {
            [1] = "790023:n(100001)"
          },
          NextOptions = {
            [1] = 801304041
          },
          SpeakNpcId = 790023,
          Subtitle = "Ah... , it's you. Am I in Icelake? How did I—?",
          TurnTo = {
            [1] = "790023:n(100001)"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991A3E"
        },
        [80130405] = {
          Camera = "92.0,244.638428,137.0,0.0,-3.999991,-112.202751,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "¿Oliver? Debes estar {性别:equivocado|equivocada}. Oliver es mi amigo, pero es una bomba. No puede llevarme a ninguna parte, precisamente...",
          DialogueId = 80130405,
          GUID = "C8991A92",
          NextDialogue = 80130406,
          SpeakNpcId = 790023,
          Subtitle = "Oliver? You must be mistaken. Oliver's my friend, but he's a bomb. He can't exactly take me anywhere...",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991A92"
        },
        [80130406] = {
          Camera = "92.0,244.638428,137.0,0.0,-3.999991,-112.202751,35.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentES = "¡Idiota! ¿Todavía quieres fingir que no pasó nada? Ya se lo dije todo.",
          DialogueId = 80130406,
          FinalCamera = "198.0,164.0,129.0,0.000008,-4.999869,-140.201721,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8991ABC",
          NextDialogue = 80130407,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Seriously? The jig's up — I already told {性别：him|her} everything, you idiot.",
          TalkActionId = {
            [1] = "790024:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "790023:n(790024)",
