          GUID = "C8991BE2",
          NextDialogue = 80130415,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "...Just waiting for someone to say sorry, that's all.",
          TurnTo = {
            [1] = "790024:n(790023)",
