        },
        [80130414] = {
          Camera = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentES = "No tengo nada que decir, pero me doy cuenta que Yale si tiene mucho que decir.",
          DialogueId = 80130414,
          FacialId = {
            [1] = "790023:None"
          },
          GUID = "C8991C0C",
