        },
        [80140307] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000428,54.601673,1.42055,17.953863,46.621048,false,Manual,2.8",
          ContentES = "¿Dónde… estoy? ¿Qué me ha sucedido…?",
          DialogueId = 80140307,
          FinalCamera = "-94.440186,-1.264404,77.296875,0.000423,39.199577,-24.999739,17.953863,46.621048,false,Manual,2.8",
          GUID = "C89F731E",
          NextDialogue = 80140308,
