      return {
        [80180217] = {
          Camera = "69.490723,-197.728516,145.714844,0.000191,0.801079,171.39772,30.000002,293.752045,false,DoNotOverride,2.8",
          ContentES = "No pretendo negar su valor. Pero un fármaco como el AG-1899, podría ser desarrollado por otros alquimistas. Simplemente les llevaría más tiempo.",
          DialogueId = 80180217,
          FinalCamera = "68.950684,-201.303711,145.714844,0.000191,0.801079,171.39772,30.000002,293.752045,false,DoNotOverride,2.8",
          GUID = "C8B906DA",
          NextDialogue = 80180218,
          SpeakNpcId = 790013,
          Subtitle = "I don't deny its value. But a drug like this — it could be developed by other alchemists. It would simply take more time.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B906DA"
        },
        [80180218] = {
          Camera = "32.769043,41.966309,152.269531,0.000203,-6.59857,-107.203644,30.000002,249.2892,false,Manual,2.8",
          ContentES = "Como investigadora de rango superior, deberías dedicarte a los campos que el Imperio necesita con mayor urgencia y cumplir con lo que la Academia Spathatoi espera de ti.",
          DialogueId = 80180218,
          FinalCamera = "40.151367,39.748047,152.269531,0.000204,-6.59857,-109.603592,30.000002,249.2892,false,Manual,2.8",
          GUID = "C8B90704",
          NextDialogue = 80180219,
          SpeakNpcId = 790013,
          Subtitle = "As a researcher superior to others, you should have served where the Empire needs you most, to meet what the Academy expects.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90704"
        },
        [80180219] = {
          Camera = "971.158691,717.543945,7.337891,0.000212,3.801465,-145.200256,30.000002,1297.015747,false,Manual,2.8",
          ContentES = "Dado la locura que has hecho, incluso si Silas no te castiga, todas tus investigaciones futuras quedarán bajo supervisión especial.",
          DialogueId = 80180219,
          FinalCamera = "971.158691,717.543945,7.337891,0.000213,4.001452,-142.200302,30.000002,1297.015747,false,Manual,2.8",
          GUID = "C8B9072E",
          NextDialogue = 80180220,
          SpeakNpcId = 790013,
          Subtitle = "Now that you've pulled this stunt, even if Silas doesn't punish you, all your research will now be conducted under direct oversight, given his temper.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9072E"
