        [80180220] = {
          Camera = "971.158691,717.543945,7.337891,0.000213,4.001452,-142.200302,30.000002,1297.015747,false,Manual,2.8",
          ContentES = "...",
          DialogueId = 80180220,
          GUID = "C8B90758",
          NextDialogue = 80180221,
          SpeakNpcId = 790045,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90758"
        },
        [80180221] = {
          Camera = "44.922852,-289.09082,141.619141,0.000184,-3.598758,107.796936,30.000002,298.325684,false,Manual,2.8",
          ContentES = "No, Comandante. No me uniré al Proyecto de Intensificación como lo pidió el Decano. Porque me niego a convertirme en la siguiente Emilia Gaston.",
          DialogueId = 80180221,
          FinalCamera = "52.822266,-286.523438,141.619141,0.000183,-3.398798,109.996681,30.000002,298.325684,false,Manual,2.8",
          GUID = "C8B90782",
          NextDialogue = 80180222,
          SpeakNpcId = 790045,
          Subtitle = "No, Chief. I won't join the Intensification Project as the dean required. Because I refuse to become the next Emilia Gaston.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90782"
        },
        [80180222] = {
          Camera = "66.137207,-83.689941,127.6875,0.000023,5.200861,-122.401611,30.000002,298.325684,false,DoNotOverride,2.8",
          ContentES = "¿Emilia Gaston?",
          DialogueId = 80180222,
          FinalCamera = "63.108887,-81.731445,127.6875,0.000025,5.200861,-120.00177,30.000002,298.325684,false,DoNotOverride,2.8",
          GUID = "C8B907AC",
          NextDialogue = 80180223,
          SpeakNpcId = 790013,
          Subtitle = "Emilia Gaston?",
          TalkActionId = {
            [1] = "790013:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B907AC"
        },
        [80180223] = {
          Camera = "479.37207,-381.822266,18.287109,0.000066,7.800827,150.999481,30.000002,298.325684,false,DoNotOverride,2.8",
          ContentES = "La reasignaron al Proyecto de Intensificación antes de que pudiéramos terminar nuestro trabajo. Ella no quería ir, pero no tenía voz ni voto, por ser orden directa de la Academia Spathatoi.",
          DialogueId = 80180223,
          FinalCamera = "479.37207,-381.822266,18.287109,0.000066,9.800829,150.799469,30.000002,298.325684,false,DoNotOverride,2.8",
          GUID = "C8B907D6",
          NextDialogue = 80180224,
          SpeakNpcId = 790045,
          Subtitle = "She was reassigned to the Intensification Project before we could finish our work. She didn't want it — not for anything — but she had no say. Because that was the Spathatoi's order.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B907D6"
        },
        [80180224] = {
          Camera = "40.990723,54.654297,136.542969,0.000085,-1.399444,-109.997879,30.000002,249.443985,false,Manual,2.8",
          ContentES = "Ah… ¿te refieres a la alquimista que murió accidentalmente hace seis meses?",
          DialogueId = 80180224,
          FinalCamera = "47.699219,52.181641,136.542969,0.000085,-1.399444,-113.197594,30.000002,249.443985,false,Manual,2.8",
          GUID = "C8B90800",
          NextDialogue = 80180225,
          SpeakNpcId = 790013,
          Subtitle = "Ah... the alchemist who died in that accident six months ago.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90800"
        },
        [80180225] = {
          Camera = "47.699219,52.181641,136.542969,0.000085,-1.399444,-113.197594,30.000002,249.443985,false,Manual,2.8",
          ContentES = "Estás exagerando. Siempre has sido precavida, no como ella. Ella era imprudente, se olvidó de asegurar las correas… y terminó atravesada por un sujeto de prueba fuera de control.",
          DialogueId = 80180225,
          GUID = "C8B9082A",
          NextDialogue = 80180226,
          SpeakNpcId = 790013,
          Subtitle = "You're being paranoid. You've always been careful — not like her. She was reckless. Forgot to fasten the restraints... and ended up impaled by a berserk test subject.",
          TalkActionId = {
            [1] = "790013:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9082A"
        },
        [80180226] = {
          Camera = "40.967773,-116.154785,129.154297,0.000088,3.600206,109.805168,30.000002,249.443985,false,DoNotOverride,2.8",
          ContentES = "No... Comandante. En realidad, usted nunca conoció a Emilia Gaston.",
          DialogueId = 80180226,
          FinalCamera = "40.967773,-116.154785,129.154297,0.00009,5.800196,110.005104,30.000002,249.443985,false,DoNotOverride,2.8",
          GUID = "C8B90854",
          NextDialogue = 80180227,
          SpeakNpcId = 790045,
          Subtitle = "...No, Chief. You never really knew Emilia Gaston.",
          TalkActionId = {
            [1] = "790045:DisagreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90854"
        },
        [80180227] = {
          Camera = "40.967773,-116.154785,129.154297,0.00009,5.800196,110.005104,30.000002,249.443985,false,DoNotOverride,2.8",
          ContentES = "Trabajé con ella durante mucho tiempo. Emilia era mucho más meticulosa y cautelosa que yo.",
          DialogueId = 80180227,
          GUID = "C8B9087E",
          NextDialogue = 80180228,
          SpeakNpcId = 790045,
          Subtitle = "I worked with her for a long time. She was far more meticulous than I ever was.",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9087E"
        },
        [80180228] = {
          Camera = "543.975098,-643.192871,207.191406,0.000092,-8.199464,137.000534,30.000002,861.833862,false,Manual,1.2",
          ContentES = "Lo que usted vio solo es el informe sobre la muerte de Emilia… que había sangre por todas partes. Y aun así… ni una sola vez pidió que la salvaran…",
          DialogueId = 80180228,
          FinalCamera = "563.548828,-622.201172,207.191406,0.000092,-8.199464,138.8004,30.000002,861.833862,false,Manual,1.2",
          GUID = "C8B908A8",
          NextDialogue = 80180229,
          SpeakNpcId = 790045,
          Subtitle = "The report just said she died. What it didn't say was... there was blood everywhere. Still pouring from her chest... And... and even then... not once did she ask for help...",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B908A8"
        },
        [80180229] = {
          Camera = "54.456055,-318.109375,151.507812,0.000091,-5.799561,105.601219,30.000002,319.662201,false,Manual,1.2",
          ContentES = "Y aún así... ella... lo único que decía era “lo siento”... una y otra vez… al sujeto de prueba que la maldecía.",
          DialogueId = 80180229,
          FinalCamera = "49.29834,-299.633301,149.564453,0.000087,-6.199557,105.001999,30.000002,319.662201,false,Manual,1.2",
          GUID = "C8B908D2",
          NextDialogue = 80180230,
          SpeakNpcId = 790045,
          Subtitle = "She just kept saying... \"I'm sorry\" over and over... to the test subject who was still cursing her.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B908D2"
        },
        [80180230] = {
          Camera = "49.29834,-299.633301,149.564453,0.000087,-6.199557,105.001999,30.000002,319.662201,false,Manual,1.2",
          ContentES = "No fue un descuido. Ella se quitó las correas. Porque no podía soportar ver sufrir a otro ser humano.",
          DialogueId = 80180230,
          GUID = "C8B908FC",
          NextDialogue = 80180231,
          SpeakNpcId = 790045,
          Subtitle = "She didn't forget the restraints. She released them... because she couldn't bear to see another human being suffer.",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B908FC"
        },
        [80180231] = {
          Camera = "962.483398,712.037109,2.564453,0.00009,7.400503,-144.79744,30.000002,1383.023071,false,Manual,1.2",
          ContentES = "Si hubiera sido yo... quizás habría hecho lo mismo. Lo único que me libró de su destino, fue una carta de reasignación.",
          DialogueId = 80180231,
          FinalCamera = "964.055176,709.811035,2.564453,0.000089,7.400503,-143.597458,30.000002,1383.023071,false,Manual,1.2",
          GUID = "C8B90926",
          NextDialogue = 80180232,
          SpeakNpcId = 790045,
          Subtitle = "Had it been me... I might've done the same. The only thing that spared me from her fate — was a reassignment letter.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90926"
        },
        [80180232] = {
          Camera = "98.930664,135.452148,204.640625,-10.808317,-18.599213,-115.984474,30.000002,368.927856,false,Manual,1.2",
          ContentES = "Esos sujetos de prueba no eran más que la escoria de la sociedad. Pensé que la muerte de Emilia al menos te habría enseñado algo.",
          DialogueId = 80180232,
          FinalCamera = "89.845215,140.586426,202.753906,-10.808901,-18.599213,-114.383667,30.000002,368.927856,false,Manual,1.2",
          GUID = "C8B90950",
          NextDialogue = 80180233,
          SpeakNpcId = 790013,
          Subtitle = "Those test subjects were just dregs of society. I thought Emilia's death might've at least taught you something.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90950"
        },
        [80180233] = {
          Camera = "24.695312,-121.806152,171.394531,-10.819184,-18.998465,-112.377495,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentES = "La mayoría de los Charons son serpientes frías, egoístas y astutas. En cuanto les des la espalda, te clavan los colmillos.",
          DialogueId = 80180233,
          FinalCamera = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
          GUID = "C8B9097A",
          NextDialogue = 80180234,
          SpeakNpcId = 790013,
          Subtitle = "Most Charons are cold, selfish, and cunning. Turn your back, and they'll sink their fangs into your heel without a second thought.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9097A"
        },
        [80180234] = {
          Camera = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentES = "Y yo no soy diferente. También soy fría, egoísta y astuta. Si te pusieras por encima de mí, me aplastarías con la misma facilidad con la que yo podría aplastarte ahora.",
          DialogueId = 80180234,
          GUID = "C8B909A4",
          NextDialogue = 80180235,
          SpeakNpcId = 790013,
          Subtitle = "And I'm no different. Cold, selfish, cunning. If you stood above me, you'd crush me — just as easily as I could crush you now.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B909A4"
        },
        [80180235] = {
          Camera = "274.801758,201.754395,22.921875,-0.001008,14.001088,-135.975983,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentES = "Pero, por ahora, no tienes ese derecho, Daphne. La “misericordia” es un privilegio de los fuertes.",
          DialogueId = 80180235,
          FinalCamera = "274.801758,201.754395,22.921875,-0.001008,11.201038,-136.775848,30.000002,368.927856,false,DoNotOverride,1.2",
          GUID = "C8B909CE",
          NextDialogue = 80180236,
          SpeakNpcId = 790013,
          Subtitle = "But you don't. Mercy is a privilege of the strong, Daphne.",
          TalkActionId = {
            [1] = "790013:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B909CE"
        },
        [80180236] = {
          Camera = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
          ContentES = "Tienes razón... Emilia liberó a ese sujeto de prueba por bondad, y lo único que él hizo fue pagarle con una daga en el corazón. Sí, son realmente fríos y astutos.",
          DialogueId = 80180236,
          FinalCamera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          GUID = "C8B909F8",
          NextDialogue = 80180237,
          SpeakNpcId = 790045,
          Subtitle = "...You're right. Emilia unshackled that test subject out of kindness — and he repaid her with a blade to the heart. Yes, they're cold and cunning.",
          TalkActionId = {
            [1] = "790013:Talk01_End",
            [2] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B909F8"
        },
        [80180237] = {
          Camera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          ContentES = "Pero… ¿quién los hizo así?",
          DialogueId = 80180237,
          GUID = "C8B90A22",
          NextDialogue = 80180238,
          SpeakNpcId = 790045,
          Subtitle = "But who made them that way?",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90A22"
        },
        [80180238] = {
          Camera = "38.929199,-70.45166,156.289062,-0.001007,-6.799528,-109.573471,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentES = "...",
          DialogueId = 80180238,
          FinalCamera = "45.669922,-72.849121,156.289062,-0.001008,-6.799528,-112.173264,30.000002,368.927856,false,DoNotOverride,1.2",
          GUID = "C8B90A4C",
          NextDialogue = 80180239,
          SpeakNpcId = 790013,
          Subtitle = "......",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90A4C"
        },
        [80180239] = {
          Camera = "384.644531,-492.653809,29.773438,-0.001008,8.000091,136.426346,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentES = "Comandante, no… Sibylle… ya tomé mi decisión, y no cambiaré de opinión.",
          DialogueId = 80180239,
          FinalCamera = "396.825684,-480.255859,29.773438,-0.001007,8.000091,138.426254,35.0,300.532867,false,DoNotOverride,3.442178",
          GUID = "C8B90A76",
          NextDialogue = 80180240,
          SpeakNpcId = 790045,
          Subtitle = "Chief — no, Sibylle... I've made my choice. And I won't turn back.",
          TalkActionId = {
            [1] = "790045:DisagreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90A76"
        },
        [80180240] = {
          Camera = "396.825684,-480.255859,29.773438,-0.001007,8.000091,138.426254,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentES = "“La alquimia existe para mejorar la vida de las personas”, con ese <H>ideal</> ingresé a la Academia Spathatoi.",
          DialogueId = 80180240,
          GUID = "C8B90AA0",
          NextDialogue = 80180241,
          SpeakNpcId = 790045,
          Subtitle = "\"Alchemy exists to make life better.\" That's the ideal I believed in when I entered the Academy.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90AA0"
        },
        [80180241] = {
          Camera = "51.583496,-229.13623,99.591797,-0.001008,6.199721,102.229668,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentES = "Sibylle, aquí me tienes. Aceptaré el castigo que la Academia me imponga… Pero, por última vez, te lo suplico, si ordenas a la Academia Spathatoi producir el AG-1899, todas las personas atormentadas por el dolor estarán eternamente agradecidas.",
          DialogueId = 80180241,
          FinalCamera = "62.180664,-226.969727,99.591797,-0.001007,6.199721,105.430244,35.0,300.532867,false,DoNotOverride,3.442178",
          GUID = "C8B90ACA",
          NextDialogue = 80180242,
          SpeakNpcId = 790045,
          Subtitle = "I'm going back, Sibylle, to accept the punishment at the Academy... But I still want to beg you for one last time — if you would order the Alchemy to produce AG-1899, all those who are tortured by pain will be extremely grateful to you.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90ACA"
        },
        [80180242] = {
          Camera = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
          ContentES = "Ya que estás tan decidida, te daré algunos consejos.",
          DialogueId = 80180242,
          FinalCamera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          GUID = "C8B90AF4",
          NextDialogue = 80180243,
          SpeakNpcId = 790013,
          Subtitle = "Since you're so set on it, I'll give you a few pieces of advice.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90AF4"
        },
        [80180243] = {
          Camera = "47.391602,-123.157227,200.138672,-0.001004,-26.399937,111.230003,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentES = "Después de tanto tiempo en la Academia, sabes demasiado. Silas nunca te dejará marcharte libremente. Solo te quedan tres opciones.",
          DialogueId = 80180243,
          FinalCamera = "55.6875,-120.101562,200.138672,-0.001007,-26.399929,114.229691,35.0,300.532867,false,DoNotOverride,3.442178",
          GUID = "C8B90B1E",
          NextDialogue = 80180244,
          SpeakNpcId = 790013,
          Subtitle = "You have been at the Academy for so long and know so many core secrets, Silas will certainly not allow you to go wherever you please. So, you have three options now.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B1E"
        },
        [80180244] = {
          ContentES = "{空格}",
          DialogueId = 80180244,
          GUID = "C8B90B48",
          IsBlack = 1,
          NextDialogue = 80180245,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_load\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B48"
        },
        [80180245] = {
          Camera = "41.63623,-81.270996,178.802734,-10.80179,-16.399618,-113.192589,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "Opción A: Deja que te encierren o te internen en un manicomio, donde pasarás el resto de tu vida.",
          DialogueId = 80180245,
          FinalCamera = "48.197266,-83.916504,180.082031,-10.802736,-16.999601,-116.99115,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90B72",
          NextDialogue = 80180246,
          SpeakNpcId = 790013,
          Subtitle = "A: Let them imprison you or commit you to an asylum, where you will spend the rest of your life.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B72"
        },
        [80180246] = {
          Camera = "109.578125,-199.028809,139.896484,-0.001007,2.399862,174.2034,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "Opción B: Coloca esta pistola en tu sien… y acaba con esto.",
          DialogueId = 80180246,
          FinalCamera = "109.203613,-202.743164,139.896484,-0.001007,2.399862,174.2034,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90B9C",
          NextDialogue = 80180247,
          SpeakNpcId = 790013,
          Subtitle = "B: Put this gun to your temple — and go straight to hell.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B9C"
        },
        [80180247] = {
          Camera = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
          ContentES = "He considerado ambas opciones. ¿Cuál es la tercera?",
          DialogueId = 80180247,
          FinalCamera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          GUID = "C8B90B9D",
          NextDialogue = 80180248,
          SpeakNpcId = 790045,
          Subtitle = "I've thought about both of these options. What's the third one?",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B9D"
        },
        [80180248] = {
          Camera = "250.523438,210.553223,66.386719,-0.001007,9.000072,-133.994293,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "Opción C: Presentas una solicitud de traslado a Fulvis. Vas al frente… y mueres como un gusano.",
          DialogueId = 80180248,
          FinalCamera = "250.523438,210.553223,66.386719,-0.001007,5.80006,-132.794342,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90B9E",
          NextDialogue = 80180249,
          SpeakNpcId = 790013,
          Subtitle = "C: File a transfer request to Fulvis. Head to the front lines — and die like a maggot.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B9E"
        },
        [80180249] = {
          Camera = "46.905762,-84.696289,145.484375,-0.001007,-2.400326,-115.394318,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "La lluvia de balas destrozará tu orgullo y el dolor pudrirá tu dignidad. Ver caer a tus camaradas, uno a uno, destrozará tu voluntad. Y al final, una muerte sin sentido devorará aquello en lo que alguna vez creíste.",
          DialogueId = 80180249,
          FinalCamera = "52.906738,-87.544922,145.484375,-0.001007,-2.400326,-118.794006,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90BC6",
          NextDialogue = 80180250,
          SpeakNpcId = 790013,
          Subtitle = "The hail of bullets will shred your pride. The pain will rot your dignity. Watching your comrades fall — one by one — will grind your will to dust. And in the end, a meaningless death will devour what you once believed in.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90BC6"
        },
        [80180250] = {
          Camera = "37.298828,51.883789,147.867188,-0.001007,-3.200312,-109.992836,30.000002,250.348099,false,Manual,2.8",
          ContentES = "Pero si, por milagro, sobrevives... entonces regresa a mi lado...",
          DialogueId = 80180250,
          FinalCamera = "44.025879,49.503418,147.867188,-0.001007,-3.200319,-113.192429,30.000002,250.348099,false,Manual,2.8",
          GUID = "C8B90BF0",
          NextDialogue = 80180251,
          SpeakNpcId = 790013,
          Subtitle = "But if, by some miracle, you survive... Then come back to me —",
          TalkActionId = {
            [1] = "790045:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90BF0"
        },
        [80180251] = {
          Camera = "972.825684,719.781738,4.660156,-0.001007,3.199554,-144.190918,30.000002,250.348099,false,Manual,2.8",
          ContentES = "Y entonces me dirás si <H>aún te mantienes firme a tus ideales.</>",
          DialogueId = 80180251,
          FinalCamera = "973.912109,718.088379,4.660156,-0.001007,3.399556,-143.391037,30.000002,250.348099,false,Manual,2.8",
          GUID = "C8B90C1A",
          SpeakNpcId = 790013,
          Subtitle = "And tell me if you still stay true to your ideals.",
          TalkActionId = {
            [1] = "790045:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90C1A"
        },
        [80180301] = {
          Camera = "269.386719,-113.140137,157.827637,0.000044,-6.800259,160.204285,30.000002,309.33728,false,Manual,1.2",
          ContentES = "Y esa es la razón por la que dejé la Academia Spathatoi. Elegí convertirme en médica de campaña. Probablemente sea lo último que aún puedo decidir por mí misma.",
          DialogueId = 80180301,
          FinalCamera = "271.535156,-107.079102,157.827637,0.000044,-6.800259,160.80426,30.000002,309.33728,false,Manual,1.2",
          GUID = "C8B914A2",
          NextDialogue = 80180302,
          SpeakNpcId = 790045,
          Subtitle = "This is why I left the Spathatoi. I chose to become a field medic — perhaps the last decision I'll ever get to make for myself.",
          TalkActionId = {
            [1] = "790057:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B914A2"
        },
        [80180302] = {
          Camera = "-121.863525,337.176758,36.699707,0.000079,9.19965,-61.996338,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Querida madre, cuando escuche esta grabación, ya estaré de camino al campo de batalla. Tal vez no regrese, y lamento despedirme de usted de esta manera.",
          DialogueId = 80180302,
          FinalCamera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B914CC",
          NextDialogue = 80180303,
          SpeakNpcId = 790045,
          Subtitle = "Dear Mother... By the time you hear this recording, I'll be en route to the front lines. I may not return. I'm sorry to say goodbye this way.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B914CC"
        },
        [80180303] = {
          Camera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Hay una caja de analgésicos sobre mi escritorio. Por favor, entrégesela al señor Roger Gaston en el Hospital Riverside. Los he probado en mí misma, funcionan...",
          DialogueId = 80180303,
          GUID = "C8B914F6",
          NextDialogue = 80180304,
          SpeakNpcId = 790045,
          Subtitle = "There's a box of painkillers on my desk. Please pass it on to Mr Roger Gaston at Riverside Hospital. I've tested it on myself — it works.",
          TalkActionId = {
            [1] = "790057:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B914F6"
        },
        [80180304] = {
          Camera = "79.812988,-4.779297,137.84375,0.00008,-2.80035,168.601562,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Perdóneme por no poder cumplir con sus expectativas. Soy la peor hija del mundo… Y la desertora más deshonrosa.",
          DialogueId = 80180304,
          FinalCamera = "79.812988,-4.779297,137.84375,0.00008,2.399684,168.800461,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B91520",
          NextDialogue = 80180305,
          SpeakNpcId = 790045,
          Subtitle = "Forgive me for failing to live up to your hopes, Mother. I'm the world's worst daughter... and the most disgraceful deserter.",
          TalkActionId = {
            [1] = "790057:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91520"
        },
        [80180305] = {
          Camera = "429.874512,-79.35791,282.631104,0.000086,-25.399929,174.798096,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Pero no me arrepiento de mi decisión, porque creo que algún día, en un futuro lejano, veremos el amanecer de una era más luminosa.",
          DialogueId = 80180305,
          FinalCamera = "431.295898,-62.712891,282.631104,0.000086,-25.399921,179.798019,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B9154A",
          NextDialogue = 80180306,
          SpeakNpcId = 790045,
          Subtitle = "But I don't regret my choice. Because I believe — someday, far in the future — we'll witness the dawn of a brighter age.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9154A"
        },
        [80180306] = {
          Camera = "431.295898,-62.712891,282.631104,0.000086,-25.399921,179.798019,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Entonces, quizá alguien se acerque a mi tumba y me diga:",
          DialogueId = 80180306,
          GUID = "C8B91574",
          NextDialogue = 80180307,
          SpeakNpcId = 790045,
          Subtitle = "And maybe then, someone will stand at my grave... and say—",
          TalkActionId = {
            [1] = "790057:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91574"
        },
        [80180307] = {
          Camera = "126.79541,-93.274414,133.225342,0.000073,-1.399772,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "“Daphne Theodore, hiciste lo correcto.”",
          DialogueId = 80180307,
          FinalCamera = "105.866211,-75.204102,132.549316,0.000073,-0.599752,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B9159E",
          NextDialogue = 80180308,
          SpeakNpcId = 790045,
          Subtitle = "Daphne Theodore, you did the right thing.",
          TalkActionId = {
            [1] = "790057:Explain02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9159E"
        },
        [80180308] = {
          Camera = "105.866211,-75.204102,132.549316,0.000073,-0.599752,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "...",
          DialogueId = 80180308,
          GUID = "C8B915C8",
          NextDialogue = 80180309,
          SpeakNpcId = 790057,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B915C8"
        },
        [80180309] = {
          Camera = "503.694824,337.953125,141.101562,21.599174,-5.399681,-139.205948,30.000002,606.763855,false,Manual,1.2",
          ContentES = "Avar… mira a la hija que criaste, ¡es como dos gotas de agua de ti! ¿Cómo pudo ser… tan estúpida, egoísta y terca?",
          DialogueId = 80180309,
          FinalCamera = "527.729492,358.695312,144.101807,21.599174,-5.399681,-139.205948,30.000002,606.763855,false,Manual,1.2",
          GUID = "C8B915F2",
          NextDialogue = 80180310,
          SpeakNpcId = 790057,
          Subtitle = "Avar... look at your daughter. She's just like you — cut from the same cloth! How could she be so... foolish, so selfish, so impossibly stubborn!",
          TalkActionId = {
            [1] = "790057:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B915F2"
        },
        [80180310] = {
          Camera = "173.015625,-19.455566,210.615723,0.000005,-26.399349,169.588226,30.000002,606.763855,false,DoNotOverride,1.2",
          ContentES = "¡Inconcebible! ¿Acaso no entendía que, si tan solo hubiera admitido su error y cedido un poco o hubiera pedido ayuda, muchas cosas podrían cambiado?",
          DialogueId = 80180310,
          FinalCamera = "175.425293,-8.150879,210.615723,0.000005,-26.399342,172.787903,30.000002,606.763855,false,DoNotOverride,1.2",
          GUID = "C8B9161C",
          NextDialogue = 80180311,
          SpeakNpcId = 790057,
          Subtitle = "Unbelievable! Doesn't she see it? A simple apology — a little compromise — or just asking for my help — and everything could've turned out differently!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9161C"
        },
        [80180311] = {
          Camera = "175.425293,-8.150879,210.615723,0.000005,-26.399342,172.787903,30.000002,606.763855,false,DoNotOverride,1.2",
          ContentES = "...",
          DialogueId = 80180311,
          GUID = "C8B91646",
          NextDialogue = 80180312,
          SpeakNpcId = 790057,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790057:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91646"
        },
        [80180312] = {
          Camera = "-121.863525,337.176758,36.699707,0.000079,9.19965,-61.996338,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Pero… yo no olvido. Siempre recuerdo…",
          DialogueId = 80180312,
          FinalCamera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B91670",
          NextDialogue = 80180313,
          SpeakNpcId = 790057,
          Subtitle = "...But now I remember.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91670"
        },
        [80180313] = {
          Camera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentES = "Fue esa misma ingenuidad… esa misma necedad… la que me hizo elegirte hace tantos años. Al final… la verdadera tonta fui yo.",
          DialogueId = 80180313,
          GUID = "C8B9169A",
          NextDialogue = 80180314,
          SpeakNpcId = 790057,
          Subtitle = "It was that same naivety... that same foolish defiance... that made me choose you, all those years ago. In the end... the real fool was me.",
          TalkActionId = {
            [1] = "790057:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9169A"
        },
        [80180314] = {
          ContentES = "Por favor… vuelvan con vida los dos.",
          DialogueId = 80180314,
          GUID = "C8B916C4",
          IsBlack = 1,
          SpeakNpcId = 790057,
          Subtitle = "You two... Please... Come back alive.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B916C4"
        },
        [80180315] = {
          Camera = "6.101562,-49.640625,124.166504,0.000013,8.197476,156.384064,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "¡Gracias a los dioses, te encontré! Vamos, ven conmigo...",
          DialogueId = 80180315,
          FinalCamera = "8.539062,-43.953125,124.166504,0.000013,8.19747,159.784409,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B916EE",
          NextDialogue = 80180316,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_battlegroundamb\"},PlayAs2D{true}}",
          SpeakNpcId = 790045,
          Subtitle = "Thank goodness you're here! Hurry, come with—",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B916EE"
        },
        [80180316] = {
          Camera = "-207.921875,-77.121094,192.568481,-0.000763,-28.411339,25.592079,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "Daphne, mi pierna está rota, no puedo caminar.",
          DialogueId = 80180316,
          FinalCamera = "-207.921875,-77.121094,192.568481,-0.000763,-31.811392,25.591383,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B91718",
          NextDialogue = 80180317,
          SpeakNpcId = 110029,
          SpeakNpcName = "UI_Npc_Name_Shibing1",
          Subtitle = "Daphne... my leg's broken. I can't move...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91718"
        },
        [80180317] = {
          Camera = "-14.828125,-78.089844,22.154419,-0.000763,8.188918,41.38969,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "Déjame... ve a salvar... a los demás...",
          DialogueId = 80180317,
          FinalCamera = "-20.101562,-71.96875,22.154419,-0.000763,8.188918,38.389439,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B91742",
          NextDialogue = 80180318,
          SpeakNpcId = 110029,
          SpeakNpcName = "UI_Npc_Name_Shibing1",
          Subtitle = "Just leave me here... Go help the others...",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91742"
        },
        [80180318] = {
          Camera = "264.460938,-208.398438,17.238892,-0.000763,7.587547,140.188553,30.000002,125.0,false,DoNotOverride,2.8",
          ContentES = "No... estamos aún dentro del alcance del fuego enemigo. Si te quedas aquí morirás...",
          DialogueId = 80180318,
          FinalCamera = "264.460938,-208.398438,17.238892,-0.000763,9.787565,140.388489,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B9176C",
          LookAt = {
            [1] = "790045:n(110029)"
          },
          NextDialogue = 80180319,
          SpeakNpcId = 790045,
          Subtitle = "No — we're still in range of enemy fire. If you stay, you'll die!",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9176C"
        },
        [80180319] = {
          Camera = "839.445312,-1032.527344,775.925781,-0.000763,-28.213598,126.587334,30.000002,1439.973022,false,Manual,1.2",
          ContentES = "Ahora vamos a inmovilizar esa fractura. Te llevaré al refugio temporal. ¡Vas a estar bien!",
          DialogueId = 80180319,
          FinalCamera = "808.445312,-1055.539062,775.925781,-0.000763,-28.213598,126.587334,30.000002,1439.973022,false,Manual,1.2",
          GUID = "C8B91796",
          NextDialogue = 80180320,
          SpeakNpcId = 790045,
          Subtitle = "We'll stabilise the fracture now. I'll carry you to the temporary shelter. You're going to be all right!",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91796"
        },
        [80180320] = {
          ContentES = "No tengas miedo… súbete a mi espalda.",
          DialogueId = 80180320,
          GUID = "C8B917C0",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "Don't be afraid... Climb on my back.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B917C0"
        },
        [80180321] = {
          Camera = "513.552734,-224.316406,18.752075,0.000019,6.799938,154.605255,30.000002,529.988831,false,Manual,1.2",
          ContentES = "Ya no se escuchan los sonidos de los cañones… ni el gruñido de los Filthoids...",
          DialogueId = 80180321,
          FinalCamera = "506.753906,-238.71875,18.752075,0.000019,6.799938,152.005585,30.000002,529.988831,false,Manual,1.2",
          GUID = "C8B917EA",
          LookAt = {
            [1] = "790045:n(110028)"
          },
          NextDialogue = 80180322,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_battlegroundamb\"},PlayAs2D{true}}",
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "The shelling... The Filthoid growls... I can't hear them anymore...",
          TalkActionId = {
            [1] = "790045:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B917EA"
        },
        [80180322] = {
          Camera = "196.876953,34.6875,120.079834,0.000088,-26.199738,159.806366,30.000002,529.988831,false,DoNotOverride,1.2",
          ContentES = "Señorita… ¿Ya nos vamos… a casa?",
          DialogueId = 80180322,
          FinalCamera = "196.876953,34.6875,120.079834,0.000088,-22.799608,159.406357,30.000002,529.988831,false,DoNotOverride,1.2",
          GUID = "C8B91814",
          NextDialogue = 80180323,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "Miss... are we... going home?",
          TalkActionId = {
            [1] = "790045:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91814"
        },
        [80180323] = {
          Camera = "87.494141,6.46875,123.438232,0.000091,8.600396,-139.792511,30.000002,529.988831,false,DoNotOverride,1.2",
          ContentES = "Sí, te acabo de suministrar un fuerte analgésico. Solo descansa un poco y pronto estaremos en casa.",
          DialogueId = 80180323,
          FinalCamera = "90.357422,3.183594,123.438232,0.00009,8.600396,-141.992706,30.000002,529.988831,false,DoNotOverride,1.2",
          GUID = "C8B9183E",
          NextDialogue = 80180324,
          SpeakNpcId = 790045,
          Subtitle = "...Yes. I gave you a strong painkiller. Just close your eyes and rest... We'll be home soon.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9183E"
        },
        [80180324] = {
          Camera = "3.556641,-141.828125,170.939697,0.000186,-23.799309,78.602211,30.000002,249.318649,false,Manual,2.618686",
          ContentES = "No… no, estás mintiendo... no volveremos.",
          DialogueId = 80180324,
          FinalCamera = "0.082031,-141.308594,170.939697,0.000187,-23.799301,76.601868,30.000002,249.318649,false,Manual,2.618686",
          GUID = "C8B91868",
          NextDialogue = 80180325,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "No... you're lying. There's no way back.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91868"
        },
        [80180325] = {
          Camera = "173.759766,145.246094,54.668579,0.000196,13.199661,-141.398911,30.000002,249.318649,false,DoNotOverride,2.618686",
          ContentES = "Dismania está demasiado lejos, está lloviendo mucho y el camino está lleno de lodo… no podremos regresar…",
          DialogueId = 80180325,
          FinalCamera = "173.759766,145.246094,54.668579,0.000197,10.999637,-141.39917,30.000002,249.318649,false,DoNotOverride,2.618686",
          GUID = "C8B91892",
          NextDialogue = 80180326,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "Dismania's too far... The rain's pouring. The roads are all mud. We'll never make it back...",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91892"
        },
        [80180326] = {
          Camera = "173.759766,145.246094,54.668579,0.000197,10.999637,-141.39917,30.000002,249.318649,false,DoNotOverride,2.618686",
          ContentES = "Señorita... por favor, llévele un mensaje a mi madre…",
          DialogueId = 80180326,
          GUID = "C8B918BC",
          NextDialogue = 80180327,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "Miss... please... Tell my mother...",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B918BC"
        },
        [80180327] = {
          Camera = "10.199219,-121.546875,161.82373,0.000328,-23.799868,82.186981,30.000002,233.226471,false,Manual,4.18986",
          ContentES = "En el tercer cajón de la estantería… el perfume… era… un regalo de cumpleaños, quería darle… una sorpresa…",
          DialogueId = 80180327,
          FinalCamera = "6.730469,-121.144531,161.82373,0.000328,-23.799868,79.786621,30.000002,233.226471,false,Manual,4.18986",
          GUID = "C8B918E6",
          NextDialogue = 80180328,
          SpeakNpcId = 110028,
          Subtitle = "Third drawer in the bookshelf... The perfume... It was for her birthday... I wanted to... surprise her...",
          TalkActionId = {
            [1] = "790045:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B918E6"
        },
        [80180328] = {
          Camera = "513.552734,-224.316406,18.752075,0.000019,6.799938,154.605255,30.000002,529.988831,false,Manual,1.2",
          ContentES = "Te lo prometo... Le llevaré tu mensaje sin falta.",
          DialogueId = 80180328,
          FinalCamera = "506.753906,-238.71875,18.752075,0.000019,6.799938,152.005585,30.000002,529.988831,false,Manual,1.2",
          GUID = "C8B91910",
          NextDialogue = 80180329,
          SpeakNpcId = 790045,
          Subtitle = "...I promise. I'll get your message to her.",
          TalkActionId = {
            [1] = "790045:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91910"
        },
        [80180329] = {
          Camera = "87.494141,6.46875,123.438232,0.000091,8.600396,-139.792511,30.000002,529.988831,false,DoNotOverride,1.2",
          ContentES = "¡Cuidado! ¡Es un dron magnético!",
          DialogueId = 80180329,
          FinalCamera = "90.357422,3.183594,123.438232,0.00009,8.600396,-141.992706,30.000002,529.988831,false,DoNotOverride,1.2",
          GUID = "C8B9193A",
          NextDialogue = 80180330,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_cibao\"},PlayAs2D{true}}",
          SpeakNpcName = "UI_Npc_Name_Shibing3",
          Subtitle = "Look out! Hostile Magnetix Drones!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9193A"
        },
        [80180330] = {
          ContentES = "¡¡¡!!!",
          DialogueId = 80180330,
          GUID = "C8B91964",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91964"
        },
        [80180331] = {
          Camera = "146.429688,96.429688,150.266846,0.000012,-9.59936,-155.996857,30.000002,288.725769,false,Manual,2.8",
          ContentES = "¿Te sientes mejor?",
          DialogueId = 80180331,
          FinalCamera = "148.185547,92.328125,150.266846,0.000011,-9.59936,-156.997086,30.000002,288.725769,false,Manual,2.8",
          GUID = "C8B9198E",
          NextDialogue = 80180332,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_cibao\"},PlayAs2D{true}}",
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "Feeling better now?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9198E"
        },
        [80180332] = {
          Camera = "47.626953,1.003906,177.767212,0.000037,-24.198778,64.204277,30.000002,288.725769,false,DoNotOverride,2.8",
          ContentES = "Sí… gracias por encargarte del dron magnético.",
          DialogueId = 80180332,
          FinalCamera = "43.027344,3.367188,177.767212,0.000031,-24.198792,61.204487,30.000002,288.725769,false,DoNotOverride,2.8",
          GUID = "C8B919B8",
          NextDialogue = 80180333,
          SpeakNpcId = 790045,
          Subtitle = "Yeah. Thanks for taking out the Magnetix Drones.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B919B8"
        },
        [80180333] = {
          Camera = "-277.273438,-616.734375,167.08728,0.00006,-8.597869,70.799004,30.000002,598.523071,false,Manual,1.2",
          ContentES = "¿Eres idiota o qué? ¡Te lanzaste directo sobre el herido! Estaba claro que no iba a sobrevivir… ¿acaso querías morir tú también? Si te mueres, ¿quién se encargará de los demás?",
          DialogueId = 80180333,
          FinalCamera = "-264.697266,-621.226562,167.08728,0.00006,-8.597869,71.198959,30.000002,598.523071,false,Manual,1.2",
          GUID = "C8B919E2",
          NextDialogue = 80180334,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "Are you out of your mind? Throwing yourself over a dying soldier like that!? He was clearly a goner — were you trying to get yourself killed too? If you'd died, what were the rest of the wounded supposed to do without you?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B919E2"
        },
        [80180334] = {
          Camera = "-264.697266,-621.226562,167.08728,0.00006,-8.597869,71.198959,30.000002,598.523071,false,Manual,1.2",
          ContentES = "...",
          DialogueId = 80180334,
          GUID = "C8B91A0C",
          NextDialogue = 80180335,
          SpeakNpcId = 790045,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A0C"
        },
        [80180335] = {
          Camera = "19.4375,-31.675781,136.009277,0.000104,1.00259,58.791103,30.000008,598.523071,false,DoNotOverride,1.2",
          ContentES = "Jeje...",
          DialogueId = 80180335,
          FinalCamera = "23.224609,-34.007812,136.009277,0.000104,1.00259,60.590927,30.000008,598.523071,false,DoNotOverride,1.2",
          GUID = "C8B91A36",
          NextDialogue = 80180336,
          SpeakNpcId = 790045,
          Subtitle = "...Hehe.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A36"
        },
        [80180336] = {
          Camera = "163.349609,102.542969,151.724365,0.000122,-8.39728,-154.012268,30.000008,303.919434,false,Manual,2.099485",
          ContentES = "¿Por qué te ríes?",
          DialogueId = 80180336,
          FinalCamera = "166.277344,96.828125,151.724365,0.000123,-8.39728,-157.012573,30.000008,303.919434,false,Manual,2.099485",
          GUID = "C8B91A60",
          NextDialogue = 80180337,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "What's so funny?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A60"
        },
        [80180337] = {
          Camera = "-236.851562,-653.707031,37.399048,0.000145,5.401894,72.381973,40.0,784.897949,false,Manual,1.422013",
          ContentES = "Me recuerdas a mi madre... y a mi hermana mayor, cuando era estudiante. Si estuvieran aquí, dirían lo mismo.",
          DialogueId = 80180337,
          FinalCamera = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
          GUID = "C8B91A8A",
          NextDialogue = 80180338,
          SpeakNpcId = 790045,
          Subtitle = "You remind me of my mother. And my senior, back when I was a student. If they were here... they'd have said the same thing.",
          TalkActionId = {
            [1] = "790045:Sigh_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A8A"
        },
        [80180338] = {
          Camera = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
          ContentES = "Depositaron en mí sus esperanzas pero… al final, nunca aprendí.",
          DialogueId = 80180338,
          GUID = "C8B91AB4",
          NextDialogue = 80180339,
          SpeakNpcId = 790045,
          Subtitle = "They always hoped I'd learn. But I never did.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91AB4"
        },
        [80180339] = {
          Camera = "-4.738281,-90.714844,105.755493,0.000144,6.801099,61.380829,40.0,784.897949,false,DoNotOverride,1.422013",
          ContentES = "Hay tanta gente racional en este mundo. Son capaces de sopesar el costo frente al beneficio y siempre eligen la opción “menos mala”. Son líderes natos y trazan el rumbo de cada era.",
          DialogueId = 80180339,
          FinalCamera = "-4.738281,-90.714844,105.755493,0.00014,8.801094,61.180855,40.0,784.897949,false,DoNotOverride,1.422013",
          GUID = "C8B91ADE",
          NextDialogue = 80180340,
          SpeakNpcId = 790045,
          Subtitle = "There are so many rational people in this world. They weigh cost against benefit — always choose the \"least bad\" option. They're born leaders. They steer the course of every era.",
          TalkActionId = {
            [1] = "790045:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91ADE"
        },
        [80180340] = {
          Camera = "997.089844,-499.308594,-19.915771,0.000057,6.20341,151.968689,40.0,1144.406128,false,Manual,1.422013",
          ContentES = "Pero yo no soy una de ellos. Nunca he sido paciente como para pensar a largo plazo. Todo lo que puedo escuchar… son los gritos justo frente a mí.",
          DialogueId = 80180340,
          FinalCamera = "993.359375,-506.820312,-19.915771,0.000057,6.20341,150.768692,40.0,1144.406128,false,Manual,1.422013",
          GUID = "C8B91B08",
          NextDialogue = 80180341,
          SpeakNpcId = 790045,
          Subtitle = "But I'm not one of them. I've never been calm enough to think that far ahead. All I can hear... are the cries right in front of me.",
          TalkActionId = {
            [1] = "790045:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B08"
        },
        [80180341] = {
          Camera = "32.263672,-32.617188,205.199585,0.00012,-27.195707,64.570541,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentES = "Aun así… creo que una era mejor debería tener espacio, incluso para las tontas que no miran a lo lejos como yo.",
          DialogueId = 80180341,
          FinalCamera = "37.583984,-35.265625,205.105835,0.000127,-27.195707,67.17112,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91B32",
          NextDialogue = 80180342,
          SpeakNpcId = 790045,
          Subtitle = "Still... I believe a better era should have room — even for short-sighted fools like me.",
          TalkActionId = {
            [1] = "790045:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B32"
        },
        [80180342] = {
          Camera = "163.349609,102.542969,151.724365,0.000122,-8.39728,-154.012268,30.000008,303.919434,false,Manual,2.099485",
          ContentES = "¡Qué tonterías…!",
          DialogueId = 80180342,
          FinalCamera = "166.277344,96.828125,151.724365,0.000123,-8.39728,-157.012573,30.000008,303.919434,false,Manual,2.099485",
          GUID = "C8B91B5C",
          NextDialogue = 80180343,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "What are you talking about...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B5C"
        },
        [80180343] = {
          Camera = "-173.388672,-447.8125,33.189331,0.00006,9.004928,71.363441,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentES = "Lo siento… me puse a hablar sola. No te preocupes por nada. Solo recuerda que si alguna vez resultas herido, no te abandonaré.",
          DialogueId = 80180343,
          FinalCamera = "-154.09375,-454.523438,33.189331,0.000057,9.004921,73.362991,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91B86",
          NextDialogue = 80180344,
          SpeakNpcId = 790045,
          Subtitle = "Sorry... I got a little carried away. Just remember this — if you're ever hurt, I won't leave you behind.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B86"
        },
        [80180344] = {
          Camera = "62.640625,-18.921875,119.119995,0.000043,3.604052,-161.235825,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentES = "Y no tomes tu vida a la ligera. Los que siguen vivos pueden hacer mucho más que los que ya se han ido.",
          DialogueId = 80180344,
          FinalCamera = "65.09375,-25.960938,119.119995,0.000042,3.604052,-162.835632,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91BB0",
          NextDialogue = 80180345,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "...Then you remember this — your life matters too. Don't act like it doesn't. The living can do far more than the dead.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91BB0"
        },
        [80180345] = {
          Camera = "65.09375,-25.960938,119.119995,0.000042,3.604052,-162.835632,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentES = "“Portar la voluntad de tus compañeros viviendo es tan noble como morir por ellos”, eso fue lo que nos dijo el Comandante Avar.",
          DialogueId = 80180345,
          GUID = "C8B91BDA",
          NextDialogue = 80180346,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "\"To carry your comrades' will and live — that's as noble as dying for them.\" That's what Commander Avar once told us.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91BDA"
        },
        [80180346] = {
          Camera = "-150.710938,-191.480469,126.76355,0.000074,-0.195801,55.361076,45.0,362.249939,false,Manual,3.206755",
          ContentES = "¿El comandante… de verdad dijo algo así…?",
          DialogueId = 80180346,
          FinalCamera = "-145.195312,-195.398438,126.76355,0.000074,-0.195801,57.360607,45.0,362.249939,false,Manual,3.206755",
          GUID = "C8B91C04",
          NextDialogue = 80180347,
          SpeakNpcId = 790045,
          Subtitle = "He... said that?",
          TalkActionId = {
            [1] = "790045:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C04"
        },
        [80180347] = {
          Camera = "-23.109375,-128.339844,101.804077,0.0001,7.60392,62.159901,45.0,242.334976,false,Manual,3.206755",
          ContentES = "Está bien, lo recordaré.",
          DialogueId = 80180347,
          FinalCamera = "-19.283203,-130.453125,101.804077,0.000098,7.60392,63.560059,45.0,254.569183,false,Manual,3.206755",
          GUID = "C8B91C2E",
          NextDialogue = 80180348,
          SpeakNpcId = 790045,
          Subtitle = "I'll keep that in mind.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C2E"
        },
        [80180348] = {
          Camera = "-19.283203,-130.453125,101.804077,0.000098,7.60392,63.560059,45.0,254.569183,false,Manual,3.206755",
          ContentES = "Ya casi es hora… debo partir.",
          DialogueId = 80180348,
          GUID = "C8B91C58",
          NextDialogue = 80180349,
          SpeakNpcId = 790045,
          Subtitle = "That's enough rest. Time to move on.",
          TalkActionId = {
            [1] = "790045:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C58"
        },
        [80180349] = {
          Camera = "1023.142578,-512.480469,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          ContentES = "¿A dónde vas?",
          DialogueId = 80180349,
          FinalCamera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          GUID = "C8B91C82",
          NextDialogue = 80180350,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "Where are you going?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C82"
        },
        [80180350] = {
          Camera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          ContentES = "Voy a ver si quedan suministros de emergencia y además…",
          DialogueId = 80180350,
          GUID = "C8B91CAC",
          NextDialogue = 80180351,
          SpeakNpcId = 790045,
          Subtitle = "To check for emergency supplies. And then...",
          TalkActionId = {
            [1] = "790045:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CAC"
        },
        [80180351] = {
          Camera = "-128.251953,-146.082031,134.427856,0.000144,-1.196642,52.959221,45.0,317.18219,false,Manual,6.360716",
          ContentES = "Voy a buscar al capitán {nickname2} para confirmar si {性别2:él|ella} está a salvo.",
          DialogueId = 80180351,
          FinalCamera = "-126.076172,-147.757812,134.427856,0.000144,-1.196642,53.559261,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91CD6",
          SpeakNpcId = 790045,
          Subtitle = "To find Captain , and make sure {性别2:he|she}'s safe.",
          TalkActionId = {
            [1] = "790045:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CD6"
        },
        [80180352] = {
          Camera = "-14.550781,-91.125,107.247437,0.000139,8.803205,58.55764,45.0,317.18219,false,Manual,6.360716",
          ContentES = "(Al cruzar un camino cubierto de cadáveres, oigo mi propia respiración pesada, siento los latidos de mi corazón. Nunca me había sentido tan pequeña.)",
          DialogueId = 80180352,
          FinalCamera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D00",
          IsBlack = 1,
          NextDialogue = 80180353,
          SpeakNpcId = 790045,
          Subtitle = [[
As I moved through the path strewn with corpses, I could hear my own ragged breath.
Feel the thud of my own heartbeat. Never had I felt so small.]],
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D00"
        },
        [80180353] = {
          Camera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          ContentES = "(Superé a mis compañeros de clase, sobreviví a experimentos, vencí el dolor… Llegué a creer que era invencible. Pero ahora lo entiendo: hay muchas más cosas que no puedo conquistar… que aquellas que sí puedo.)",
          DialogueId = 80180353,
          GUID = "C8B91D2A",
          IsBlack = 1,
          NextDialogue = 80180354,
          SpeakNpcId = 790045,
          Subtitle = "I had bested my classmates, survived experiments, overcome pain... I once thought I was invincible.\nBut now I understand — there are far more things I cannot conquer... than those I can.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D2A"
        },
        [80180354] = {
          Camera = "47.957031,-1250.3125,16.771729,0.000155,3.202962,92.956001,45.0,317.18219,false,Manual,6.360716",
          ContentES = "(Pero, sin importar lo que me espere… cuando esta batalla termine… ya sea que salga con vida o que solo mi alma regrese, espero poder llevar estas palabras a Sibylle Mason…)",
          DialogueId = 80180354,
          FinalCamera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D54",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "Still, whatever lies ahead... When this battle ends... Whether I make it out alive, or only my soul returns —\nI hope I can carry these words to Sibylle Mason—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D54"
        },
        [80180355] = {
          Camera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          ContentES = "<H>Daphne Theodore, siempre fue firme en sus ideales.</>",
          DialogueId = 80180355,
          GUID = "C8B91D7E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "\"Daphne Theodore stays true to her ideals.\"",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D7E"
        },
        [80190001] = {
          ContentES = "Si es comida y bebida gratis, no te hagas de rogar. Quien no aprovecha, es un tonto.",
          DialogueId = 80190001,
          GUID = "C8BF4C0A",
          Subtitle = "Free food and drink? Don't mind if I do — only a fool would turn down a freebie."
        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          ContentES = "¿Vives {性别:solo|sola} en una casa tan grande? No está mal, incluso veo que montaste un bar.",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "You've got this big place all to yourself? Not bad — even set up a proper bar, I see.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          ContentES = "Bien por ti. Deberías invitar a amigos más a menudo, así podrías tener tus propios contactos en Lago Helado.",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102,
          Subtitle = "Good for you. You ought to have friends over more often — never hurts to build a few ties in Icelake."
        },
        [80190104] = {
          ContentES = "Bueno, cuéntame, ¿qué quieres esta vez? Si es algo demasiado complicado, paso. Últimamente tengo muchos trabajos pendientes.",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          Subtitle = "Alright then — what do you want this time? If it's anything too much of a bother, I'm out. Got a big job hanging over me lately.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          ContentES = "¡Eh… me pusiste la piel de gallina! Está vez lo dejaré pasar, pero si le dices eso a todos con quienes tomas, no todos lo tomarán tan bien.",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          Subtitle = "Oof... That's sweet enough to rot my teeth. I'll let it slide — but if you say that to everyone you drink with, someone's bound to choke on their pint.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          ContentES = "Eso está mejor. Déjame probar lo que sabes hacer.",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          Subtitle = "Now that's more like it. Let's see if your mix is worth the pour.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          ContentES = "Toma la copa y da un gran trago.",
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          ContentES = "Hmm... Dulce con un toque de acidez, servido caliente. Casi alcanza el nivel del Asfódelo, pero con tu toque personal.",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Hmm... Sweet, with a tangy edge. Served warm, too — not bad at all. I'd say it's on par with the stuff back at The Asphodel, though you've definitely added your own twist.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          ContentES = "Apuesto a que este te costó mucho esfuerzo, ¿no? Para ser sincero, superó mis expectativas. Aunque, con solo una taza de agua caliente me habría bastado, soy fácil de complacer. No hacía falta esmerarse tanto.",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102,
          Subtitle = "Bet this one took a fair bit of effort, eh? Didn't expect a drink this good, to be honest. Even just a warm cup of water would've done the trick — I'm easy. No need to pull out all the stops."
        },
        [80190110] = {
          ContentES = "Te ves bastante alegre… ah, ya entiendo. Ahorras algo de dinero y luego lo derrochas en fiestas y bebidas, tal vez en algún capricho nuevo. Eso es lo que llaman “pagar por divertirse”, ¿verdad?",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102,
          Subtitle = "You're looking rather chipper though... ah, I get it. Got a bit of coin lying around, huh? Thought you'd splash out — parties, drinks, maybe a new trinket or two. That's what they call \"buying a good time\" these days, right?"
        },
        [80190111] = {
          ContentES = "Pero invitas a la gente para hablar, ¿no? Eso demuestra que soy quien mejor te comprende y quien más te respeta.",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          Subtitle = "Well, isn't that the whole point? You pour someone a drink, you get a proper chat. Just means I know how to read the room — and I've got the decency to play along.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          ContentES = "No, no, me equivoqué. Tu casa, tus reglas. Mejor, suéltame un puñetazo si eso te ayuda a desahogarte.",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          Subtitle = "Whoa now, my bad! Your place, your booze — that makes you the boss. Here — throw a punch if it'll help you blow off some steam.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          ContentES = "Dejando las bromas aparte, si quieres un consejo de alguien con algo de experiencia: no todo el mundo merece una copa… ni que lo llamen “amigo”.",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          Subtitle = "Kidding, obviously. But if you're after a bit of advice from someone who's been around — not everyone's worth the drink or the word \"friend.\"",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          ContentES = "Especialmente en un lugar como Lago Helado. Siempre hay algún desgraciado que te observa los bolsillos, que te halaga solo para encontrar la manera de aprovecharse de ti.",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102,
          Subtitle = "Especially not in a place like Icelake. Always some grinning bastard eyeing your pockets, buttering you up just to find a way in."
        },
        [80190115] = {
          ContentES = "Por afuera, te sonríen, te halagan y te ponen en un pedestal. Pero en el segundo en que tengas problemas, tendrás más suerte confiando en un perro callejero.",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          Subtitle = "They'll smile, flatter, make you feel like you're the sun — and the second you're in trouble? You'd have better luck counting on a stray dog.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          ContentES = "Ah, lo has entendido todo. Yo, Outsider, soy el mayor vividor y amigo de juergas que jamás conocerás. Si hay licor gratis o una comida caliente, puedo olerla a kilómetros y venir enseguida.",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          Subtitle = "Ding ding ding — got me! I, Outsider, am the finest freeloader you'll ever meet. Disguised, of course, as a charming drinking buddy. If there's free booze or a hot meal, I'll sniff it out from a mile off.",
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          ContentES = "Si alguien quiere disputarme ese título, tendrá que medirse conmigo. Y aquellos que planeen comer de tu plato, solo podrán esperar hasta que me haya saciado yo primero.",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102,
          Subtitle = "Anyone wants the title, they'll have to fight me for it. And those who're planning to eat off your plate, they can only wait until I've had my fill."
        },
        [80190118] = {
          ContentES = "Eh, no hay por qué apresurarse. Recién empezaba a ponerme cómodo.",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          Subtitle = "Oi, oi — no need to be hasty. I've only just got comfy.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          ContentES = "¿Eh? ¿De qué hablas? No entiendo nada.",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          Subtitle = "Hmm? What's that now? No idea what you're talking about.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          ContentES = "El licor está muy bueno. Sírveme otra copa antes de arrastrarme de vuelta al trabajo.",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102,
          Subtitle = "But hey — the drink's good. Pour me another before I drag myself back to the grind."
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "Parece que llegue media hora tarde. Para compensarlo te juro que, aunque la bebida de hoy sepa a pescado podrido me la beberé de un solo trago.",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102,
          Subtitle = "Ah — half an hour late, huh? My bad. To make it up to you, I swear — even if today's drink tastes like bad fish in a dirty sock, I'll down it in one go!"
        },
        [80190202] = {
          ContentES = "Jajaja, cómo lo adivinaste tan rápido.",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
          NextDialogue = 80190203,
          SpeakNpcId = 95102,
          Subtitle = "Haha — sharp one. Saw right through me."
        },
        [80190203] = {
          ContentES = "¿Recuerdas ese gran trabajo del que hable el otro día? Bueno, recién acabo de terminarlo junto con Wells, nos tomo más tiempo de lo esperado.",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102,
          Subtitle = "Remember that big job I mentioned the other day? Just wrapped it up with Wells. Took a bit longer than we thought."
        },
        [80190204] = {
          ContentES = "El problema no fue el trabajo, sino las personas involucradas que lo complicaban todo.",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102,
          Subtitle = "The job wasn't the problem — it was the people involved that made it a pain."
        },
        [80190205] = {
          ContentES = "No, la Legión es fácil de manejar, si ya conoces las reglas y evitas inmiscuirte en los asuntos del Imperio, puedes evitar cualquier problema con ellos.",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          Subtitle = "Nah. The Legion's manageable — long as you know the rules, read the room, and steer clear of stepping on the Empire's toes, you can find ways around most of their messes.",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          ContentES = "Son como una espada: afilada y letal, pero al menos las ves venir.",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102,
          Subtitle = "They're like a drawn blade — sharp and deadly, sure, but at least you see it coming."
        },
        [80190207] = {
          ContentES = "Pero hay otro grupo, más violento y completamente caótico. Como una bomba oculta, lista para explotar.",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          Subtitle = "It's the other lot you need to watch out for. The ones with no rules, just chaos. Like a live bomb buried just out of sight—",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          ContentES = "Los Abandonados, ese grupo de locos furiosos. Involucrarse con ellos es firmar para un caos sin fin.",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102,
          Subtitle = "The Forsakens. That mad bunch. Once they drag you in, everything gets ten times messier."
        },
        [80190209] = {
          ContentES = "Por ejemplo, este trabajo de entrega, al principio aparentemente normal. Wells sintió que el peso no cuadraba, abrió la caja discretamente y, ¿adivina qué? Armas prohibidas para los Abandonados.",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102,
          Subtitle = "Take this job, for example — just your standard delivery gig, right? But Wells thought something felt off with the weight, so he quietly chiselled a hole in the crate and had a peek. And what do you know? It was packed with contraband weapons, all marked for the Forsakens."
        },
        [80190210] = {
          ContentES = "Si hubiéramos pasado por la puerta principal de la ciudad, lo más seguro es que los guardias habrían abierto fuego contra nosotros, sin que antes pudiéramos decir alguna palabra.",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102,
          Subtitle = "If we'd hauled that through the city gates, the guards would've gunned us down before we got a word in."
        },
        [80190211] = {
          ContentES = "Probablemente ese era su plan. Tal vez querían algunas muertes entre los Phoxcazadores, o un buen caos para infiltrarse en Lago Helado.",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102,
          Subtitle = "Which was probably the plan. Maybe they wanted a few Phoxhunters dead. Maybe a little public chaos to slip into Icelake."
        },
        [80190212] = {
          ContentES = "O puede ser que solo querían un espectáculo, un show para que sus seguidores vieran lo despiadados que son los Solas contra los Charons.",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          Subtitle = "Or maybe it was all for show — a nice live performance, so their followers could watch exactly how cruel Solas are to Charons.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          ContentES = "Completamente incomprensible, ¿eh? Normal que nadie entienda sus métodos ni sus objetivos.",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          Subtitle = "Point is, there's no guessing with them. Their motives don't make sense to normal folk — and their methods are even worse.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          ContentES = "Al final, tuvimos que pasar esas armas por las alcantarillas para completar la “entrega”.",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102,
          Subtitle = "In the end, we had to smuggle the weapons in through the sewers just to finish the so-called \"delivery.\""
        },
        [80190215] = {
          ContentES = "Ahora que lo cuento suena bastante sencillo, pero en realidad Wells y yo no hemos dormido en días.",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102,
          Subtitle = "Sounds simple when I say it, right? But Wells and I haven't had a proper night's sleep in days."
        },
        [80190216] = {
          ContentES = "Aun así, es incorrecto llegar tarde.",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          Subtitle = "Still — wrong's wrong. Doesn't matter how busy I was, I showed up late.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          ContentES = "Nah, a {性别:un amigo|una amiga} que te invita a tomar algo no se le dice que no. Aunque estuviera seis metros bajo tierra, me levantaría por un trago.",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          Subtitle = "Nah. I'd never say no to a drinking buddy. Even if I were six feet under, I'd still claw my way up for a sip.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          ContentES = "Toma la copa y da un gran trago.",
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          ContentES = "Pero tienes razón, sí necesito descansar. Antes de irme, te doy un último consejo: por tu bien y por el bien de quienes te rodean, mantente lejos de Los Abandonados.",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "But yeah, I do need sleep. Before I go — one last bit of advice. For your own safety, and for the sake of those who care about you... steer clear of the Forsakens.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          ContentES = "Al igual que la mayoría de las personas... al ver peligro, mantienes tu distancia y punto.",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102,
          Subtitle = "...Just survival instinct. Like most folk — I see danger, I walk the other way."
        },
        [80190221] = {
          ContentES = "Esa es una valiosa lección que he aprendido tras tanto tiempo atrapado en este sistema lleno de violencia. Jamás, escúchame bien, jamás te acerques a Los Abandonados.",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102,
          Subtitle = "I've spent years scraping by between the grinding gears of clashing war machines. And if there's one thing I've learned, it's this: stay the hell away from the Forsakens."
        },
        [80190222] = {
          ContentES = "Esto no es una tontería de borrachos… es un consejo que puede salvarte la vida.",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102,
          Subtitle = "This isn't some drunken ramble. This is life-or-death advice."
        },
        [80190301] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "Outsider llega justo a tiempo, pero después de beber un trago, permanece en silencio.",
          DialogueId = 80190301,
          Duration = 3,
          FacialId = {
            [1] = "95102:Unhappy02"
          },
          GUID = "C8BF7D42",
          NextDialogue = 80190302,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "Outsider shows up right on time. But after just one sip, he goes completely quiet.",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190302] = {
          ContentES = "...",
          DialogueId = 80190302,
          GUID = "C8BF7D6C",
          NextDialogue = 80190303,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "...",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190303] = {
          ContentES = "...",
          DialogueId = 80190303,
          GUID = "C8BF7D96",
          NextOptions = {
            [1] = 801903031,
            [2] = 801903032
          },
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190304] = {
          ContentES = "...",
          DialogueId = 80190304,
          GUID = "C8BF7DC0",
          NextDialogue = 80190305,
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190305] = {
          ContentES = "Ah… sí, estoy bien. La bebida está buena, igual que la otra vez.",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102,
          Subtitle = "...Ah... yeah. I'm fine. Good drink. Solid as ever."
        },
        [80190306] = {
          ContentES = "...",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
            [1] = 801903061,
            [2] = 801903062
          },
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190307] = {
          ContentES = "¿Eh? Pamplinas ¿Crees que lloraría en público? Lo sentimental no va con los compañeros de juerga.",
          DialogueId = 80190307,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF7E3E",
          NextDialogue = 80190308,
          SpeakNpcId = 95102,
          Subtitle = "Hah? Don't be ridiculous. Like I'd cry in front of people. Do I look like the soft-hearted type to you, buddy?",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190308] = {
          ContentES = "Pero... últimamente, suelo pensar mucho en mi pasado... Tal vez sea la edad la que hace eso.",
          DialogueId = 80190308,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF7E68",
          NextDialogue = 80190309,
          SpeakNpcId = 95102,
          Subtitle = "That said... lately, I've been thinking about the past more than I used to. Maybe I'm just getting old."
        },
        [80190309] = {
          ContentES = "No me mires con esa cara. No voy a abrirme ni a desnudar mi alma. ¿De verdad pensaste que unas cuantas copas te iban a comprar mi pasado?",
          DialogueId = 80190309,
          GUID = "C8BF7E92",
          NextDialogue = 80190310,
          SpeakNpcId = 95102,
          Subtitle = "Don't give me that look. I'm not about to open up and bare my soul. You didn't seriously think a few drinks would buy my whole life story, did you?"
        },
        [80190310] = {
          ContentES = "Cada persona tiene secretos que deben llevarse a la tumba. Puede que no se entierren dentro del ataúd, pero son los compañeros más leales que llevamos con nosotros allá abajo.",
          DialogueId = 80190310,
          GUID = "C8BF7EBC",
          NextDialogue = 80190311,
          SpeakNpcId = 95102,
          Subtitle = "Everyone's got things they'll take with them to the grave. They might not be buried in the coffin, but make no mistake — they're the most loyal companions we carry down there."
        },
        [80190311] = {
          ContentES = "Esos secretos pueden ser triviales, como gustar del olor del Phoxichor, o romperse un diente con un pan de jengibre demasiado duro. O cosas más pesadas, un pasado que no se comparte.",
          DialogueId = 80190311,
          GUID = "C8BF7EE6",
          NextDialogue = 80190312,
          SpeakNpcId = 95102,
          Subtitle = "Could be something silly — like being weirdly fond of the smell of Phoxichor, or cracking a tooth on your favourite rock-hard gingersnap. Could be... a past you never talk about."
        },
        [80190312] = {
          ContentES = "No se ve nada de eso por fuera, son secretos, por una razón. Pero eso es lo que guía la mayoría de las decisiones de una persona. Quizá no siempre sea la razón principal, pero casi. Sabes a lo que me refiero.",
          DialogueId = 80190312,
          GUID = "C8BF7F10",
          NextDialogue = 80190313,
          SpeakNpcId = 95102,
          Subtitle = "You won't see that stuff on the surface — they're called secrets for a reason. But truth is, it's that very stuff that drives a person. Not the whole reason, maybe — but close enough. You get the point."
        },
        [80190313] = {
          ContentES = "Cuando alguien comparte sus secretos con demasiada facilidad, suele ser por una de varias razones. Una puede ser que esos recuerdos ya no significan mucho para ellos…",
          DialogueId = 80190313,
          GUID = "C8BF7F3A",
          NextDialogue = 80190314,
          SpeakNpcId = 95102,
          Subtitle = "When someone shares their secrets too easily, it's usually for one of a few reasons. Either those memories don't mean much to them anymore..."
        },
        [80190314] = {
          ContentES = "O inventa una historia para buscar un poco de compasión.",
          DialogueId = 80190314,
          GUID = "C8BF7F64",
          NextDialogue = 80190315,
          SpeakNpcId = 95102,
          Subtitle = "Or they're just spinning a tale to fish for sympathy."
        },
        [80190315] = {
          ContentES = "En cualquier caso, revelar tus secretos a cualquiera es arriesgado. Les das armas a los demás, y además puede parecer frivolidad. O peor, desesperación.",
          DialogueId = 80190315,
          GUID = "C8BF7F8E",
          NextOptions = {
            [1] = 801903151,
            [2] = 801903152
          },
          SpeakNpcId = 95102,
          Subtitle = "Either way — spilling your guts to just anyone? That's reckless. You're handing over leverage. People might just see it as carelessness. Or worse... desperation.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190316] = {
          ContentES = "Sí, sí, entiendo lo que dices. Incluso yo he dejado escapar uno que otro secreto en el Asfódelo, como cuando conseguí un que otro trabajito jugoso y terminé soltando la sopa.",
          DialogueId = 80190316,
          GUID = "C8BF7FB8",
          NextDialogue = 80190317,
          SpeakNpcId = 95102,
          Subtitle = "Yeah, yeah, I get it. And you're not wrong. I say all this, but even I've let slip a secret or two at the tavern — like when I landed a juicy side gig or two.",
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190317] = {
          ContentES = "Pero… digamos que no todos los secretos pesan igual.",
          DialogueId = 80190317,
          GUID = "C8BF7FE2",
          NextOptions = {
            [1] = 801903171
          },
          SpeakNpcId = 95102,
          Subtitle = "But... let's just say, not all secrets weigh the same.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190318] = {
          ContentES = "¡Oye! ¿Cómo puedes decir algo así?",
          DialogueId = 80190318,
          GUID = "C8BF800C",
          NextDialogue = 80190319,
          SpeakNpcId = 95102,
          Subtitle = "Hey! How could you say that?",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190319] = {
          ContentES = "Precisamente porque eres mi {性别:amigo|amiga} no puedo contártelo. No intento hacerme el misterioso ni el dramático, ¿de acuerdo? Piénsalo como un consejo de alguien que se preocupa por ti.",
          DialogueId = 80190319,
          GUID = "C8BF8036",
          NextDialogue = 80190320,
          SpeakNpcId = 95102,
          Subtitle = "It's exactly because you're my friend that I can't tell you. I'm not trying to be cryptic or dramatic, alright? Think of it as a word of advice from someone who cares about you:"
        },
        [80190320] = {
          ContentES = "Excavar en el pasado es arriesgarse a encontrar algo más que tesoros. A veces, es la muerte la que resurge. Así que, para ahorrártelo, prefiero llevar esa carga solo.",
          DialogueId = 80190320,
          GUID = "C8BF8060",
          NextDialogue = 80190321,
          SpeakNpcId = 95102,
          Subtitle = "Digging up old graves doesn't always lead to treasure. Sometimes, all you find is rot. And I'd rather you never have to deal with the stench. Let me carry it."
        },
        [80190321] = {
          ContentES = "Está bien. He hecho un buen trabajo dejando el pasado atrás. Y si alguna vez vuelve a llamar a la puerta… oye, seré yo quien la abra, no tú. Tú solo concéntrate en el presente y déjame encargarme del resto.",
          DialogueId = 80190321,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF808A",
          NextDialogue = 80190322,
          SpeakNpcId = 95102,
          Subtitle = "It's fine. I've done a pretty good job of leaving the past behind. And if it ever comes knocking again — hey, I'll be the one answering the door. Not you. You just focus on the moment and let me handle the rest."
        },
        [80190322] = {
          ContentES = "¡Muy bien entonces! ¡Otra ronda, por favor! La anterior pasó demasiado rápido, no pude saborearla.",
          DialogueId = 80190322,
          GUID = "C8BF80B4",
          NextOptions = {
            [1] = 801903221,
            [2] = 801903222
          },
          SpeakNpcId = 95102,
          Subtitle = "Alright then — another round, please! That last one went down so smooth, I barely tasted it."
        },
        [80190323] = {
          ContentES = "¡Jajaja! No hay nada como beber un trago fuerte acompañado de {性别:un amigo|una amiga} de lengua afilada… esto sí que es vivir.",
          DialogueId = 80190323,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF80DE",
          NextOptions = {
            [1] = 801903231
          },
          SpeakNpcId = 95102,
          Subtitle = "Hahaha! A stiff drink, a sharp-tongued friend, and a bit of banter — now this is the life."
        },
        [80190324] = {
          ContentES = "¿Acabas de insultarme?",
          DialogueId = 80190324,
          GUID = "C8BF8108",
          SpeakNpcId = 95102,
          Subtitle = "What was that!?",
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentES = "Toma la copa y da un gran trago.",
          DialogueId = 80190401,
          GUID = "C8BF8DAA",
          NextDialogue = 80190402,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190402] = {
          ContentES = "¿Eh? ¿Acabas de llamarme?",
          DialogueId = 80190402,
          FacialId = {
            [1] = "95102:Doubt01"
          },
          GUID = "C8BF8DD4",
          NextOptions = {
            [1] = 801904021
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Hm? What did you just call me?"
        },
        [80190403] = {
          ContentES = "Ah... probablemente fue mi imaginación. He estado algo paranoico últimamente, lo siento.",
          DialogueId = 80190403,
          FacialId = {
            [1] = "95102:Unhappy01"
          },
          GUID = "C8BF8DFE",
          NextDialogue = 80190404,
          SpeakNpcId = 95102,
          Subtitle = "Ah... must've been my imagination again. Been a bit on edge lately — sorry about that.",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190404] = {
          ContentES = "Desde hace mucho tiempo he estado escuchando voces que me llaman por mi verdadero nombre. Algunas suenan amables, otras firmes.",
          DialogueId = 80190404,
          GUID = "C8BF8E28",
          NextDialogue = 80190405,
          SpeakNpcId = 95102,
          Subtitle = "Truth is, I've been hearing voices calling my real name in my head for years. Some soft, some firm.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190405] = {
          ContentES = "Es como el tinnitus, te acostumbras con el tiempo. Cuando me aburro, hasta les respondo por diversión, aunque sé que no son reales.",
          DialogueId = 80190405,
          GUID = "C8BF8E52",
          NextDialogue = 80190406,
          SpeakNpcId = 95102,
          Subtitle = "It's like tinnitus — you get used to it. Sometimes I even answer back, just for kicks. They're not real, after all."
        },
        [80190406] = {
          ContentES = "Pero ayer... pasó algo extraño. Respondí como de costumbre y esta vez alguien me contestó.",
          DialogueId = 80190406,
          GUID = "C8BF8E7C",
          NextDialogue = 80190407,
          SpeakNpcId = 95102,
          Subtitle = "But yesterday... something strange happened. I replied on reflex — just a little \"hm?\" — and this time, someone actually answered."
        },
        [80190407] = {
          ContentES = "De repente, el bote de basura en la esquina de la calle se volcó y una figura sospechosa saltó y me saludó.",
          DialogueId = 80190407,
          GUID = "C8BF8EA6",
          NextDialogue = 80190408,
          SpeakNpcId = 95102,
          Subtitle = "A rubbish bin tipped over near the street corner, and some shady character popped out from behind it and said hello."
        },
        [80190408] = {
          ContentES = "Quería pensar que era broma de algún mocoso. Pero, por desgracia, escuché que me llamaron por un nombre que solo Los Abandonados conocen. Y no, no era “Outsider”.",
          DialogueId = 80190408,
          GUID = "C8BF8ED0",
          NextDialogue = 80190409,
          SpeakNpcId = 95102,
          Subtitle = "Oof, I wanted to think it was just some brat messing around. But no — he called me by a name only the Forsakens would know. Not the name you know. Not Outsider."
        },
        [80190409] = {
          ContentES = "Me hice el tonto. Le dije que se había equivocado de persona. No sé si se lo creyó... Ay, debería haber dejado que Wells se encargara solo de Los Abandonados.",
          DialogueId = 80190409,
          GUID = "C8BF8EFA",
          NextOptions = {
            [1] = 801904091
          },
          SpeakNpcId = 95102,
          Subtitle = "I played dumb. Told him he had the wrong guy. No idea if he bought it... Ugh, should've let Wells handle that Forsakens' gig on his own.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190410] = {
          ContentES = "...",
          DialogueId = 80190410,
          GUID = "C8BF8F24",
          NextDialogue = 80190411,
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190411] = {
          ContentES = "Toma la copa y da un gran trago.",
          DialogueId = 80190411,
          GUID = "C8BF8F4E",
          NextDialogue = 80190412,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190412] = {
          ContentES = "Supongo que debo contarte algunas cosas. No me gustaría que un día te apuñalen en algún callejón, solo porque no sabías en qué me había metido.",
          DialogueId = 80190412,
          GUID = "C8BF8F78",
          NextDialogue = 80190413,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Yeah. I suppose I owe you the truth. You deserve to know — wouldn't want you catching a blade in some back alley one day, just because you didn't know what I'd gotten tangled up in.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190413] = {
          ContentES = "Antes tuve… un pequeño conflicto con Los Abandonados, así que han estado buscándome desde entonces. Y ese encargo de hace unos días <H>quizás</> haya revelado mi paradero.",
          DialogueId = 80190413,
          GUID = "C8BF8FA2",
          NextDialogue = 80190414,
          SpeakNpcId = 95102,
          Subtitle = "I've got... history with the Forsakens. Bad blood. They've been hunting me for a while now. That last gig? Might've given 'em a whiff of my trail."
        },
        [80190414] = {
          ContentES = "Así que ahora tengo que borrar mis huellas en Lago Helado. Asegurarme de que no sigan mis pistas y me encuentren.",
          DialogueId = 80190414,
          GUID = "C8BF8FCC",
          NextDialogue = 80190415,
          SpeakNpcId = 95102,
          Subtitle = "So now I've gotta cover my tracks in Icelake. Make sure nothing leads back to me."
        },
        [80190415] = {
          ContentES = "Porque si eso pasa… mis amigos serán los primeros en sufrir. Irán tras ellos, uno por uno, hasta que alguien ceda y me delate. Y tú… tú tampoco te salvarías.",
          DialogueId = 80190415,
          GUID = "C8BF8FF6",
          NextDialogue = 80190416,
          SpeakNpcId = 95102,
          Subtitle = "Because if it does... my friends'll be the first to suffer. They'll go after them, one by one — until someone cracks and gives me up. And you? You wouldn't walk away, either."
        },
        [80190416] = {
          ContentES = "Pero oye, si ese día llega, solo di que era un compañero de copas. Que no me conoces bien y que no sabes nada de todo esto...",
          DialogueId = 80190416,
          GUID = "C8BF9020",
          NextOptions = {
            [1] = 801904161,
            [2] = 801904162
          },
          SpeakNpcId = 95102,
          Subtitle = "But hey — if that day comes, just say I was some drinking buddy. That you don't know me well. Don't know a thing about any of this.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190417] = {
          ContentES = "Eh, escucha, aún no ha pasado nada. Pero… si algún día realmente llega ese momento…",
          DialogueId = 80190417,
          GUID = "C8BF904A",
          NextDialogue = 80190418,
          SpeakNpcId = 95102,
          Subtitle = "Uh-uh. Hear me out. I'm just saying if. But if the worst does come...",
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190418] = {
          ContentES = "Cuando llegue el momento, tendré que dejarlos… dejar esta ciudad. Te encargo que cuides de Fina por mí, ¿sí?",
          DialogueId = 80190418,
          GUID = "C8BF9074",
          NextDialogue = 80190419,
          SpeakNpcId = 95102,
          Subtitle = "I'll have to leave. Leave the city. Leave you lot behind. And Fina... take care of her for me, yeah?"
        },
        [80190419] = {
          ContentES = "Si pregunta, dile que he tomado un gran contrato. He escrito algunas cartas, dale una por mes, debería tranquilizarla por un rato.",
          DialogueId = 80190419,
          GUID = "C8BF909E",
          NextDialogue = 80190420,
          SpeakNpcId = 95102,
          Subtitle = "If she asks, tell her I landed a big job. One that needs me gone a while. Here — these are letters I wrote. Give her one each month. That should buy you some time."
        },
        [80190420] = {
          ContentES = "Ah, y hay algo de dinero escondido detrás del tercer ladrillo a la derecha de la chimenea, tómalo si lo necesitas. A ver qué más...",
          DialogueId = 80190420,
          GUID = "C8BF90C8",
          NextDialogue = 80190421,
          SpeakNpcId = 95102,
          Subtitle = "Oh, right — there's some cash behind the third brick to the right of my fireplace. Take it if you need it. What else, what else...",
          TalkActionId = {
            [1] = "95102:Sit_Think_End"
          }
        },
        [80190421] = {
          ContentES = "Outsider, cálmate un poco.",
          DialogueId = 80190421,
          GUID = "C8BF90F2",
          NextDialogue = 80190422,
          SpeakNpcId = 790008,
          Subtitle = "Outsider, breathe. Calm down."
        },
        [80190422] = {
          ContentES = "Estoy tranquilo. Ahora repite todo lo que te acabo de decir. Cuando no esté, todo dependerá de ti.",
          DialogueId = 80190422,
          GUID = "C8BF911C",
          NextDialogue = 80190423,
          SpeakNpcId = 95102,
          Subtitle = "I am calm. Now repeat everything I just told you. If I'm not around, someone's gotta hold the line."
        },
        [80190423] = {
          ContentES = "Normalmente, no eres así… ¿es por Los Abandonados?",
          DialogueId = 80190423,
          GUID = "C8BF9146",
          NextDialogue = 80190424,
          SpeakNpcId = 790008,
          Subtitle = "This really isn't like you. Is it because of the Forsakens?"
        },
        [80190424] = {
          ContentES = "¿Normalmente? Estoy seguro que ni en mi mejor estado duraría cinco minutos contra esos lunáticos.",
          DialogueId = 80190424,
          FacialId = {
            [1] = "95102:Unacceptable01"
          },
          GUID = "C8BF9170",
          NextDialogue = 80190425,
          SpeakNpcId = 95102,
          Subtitle = "\"Like me,\" huh? Pretty sure the regular me wouldn't last five minutes against those lunatics with no moral scruples—",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190425] = {
          ContentES = "Por solo una pequeña información, ellos te arrancarían todas las uñas. Una por una.",
          DialogueId = 80190425,
          GUID = "C8BF919A",
          NextDialogue = 80190426,
          SpeakNpcId = 95102,
          Subtitle = "For a scrap of intel, they'd pull your fingernails out. One by one."
        },
        [80190426] = {
          ContentES = "Y eso es lo mínimo que te podrían hacer esos dementes para comenzar, lo último que quiero es que algo así le suceda a un amigo.",
          DialogueId = 80190426,
          GUID = "C8BF91C4",
          NextDialogue = 80190427,
          SpeakNpcId = 95102,
          Subtitle = "And that's just their idea of a warm-up. I'm not letting that happen... Not to anyone I care about."
        },
        [80190427] = {
          ContentES = "Pero eso aún no ha pasado, y dijiste que tu rastro solo <H>quizás</> había sido comprometido, ¿no?",
          DialogueId = 80190427,
          GUID = "C8BF91EE",
          NextDialogue = 80190428,
          SpeakNpcId = 790008,
          Subtitle = "But none of that's happened yet. You said your location might've been compromised — not that it has."
        },
        [80190428] = {
          ContentES = "Aunque sea solo una pequeña posibilidad, tenemos que estar preparados.",
          DialogueId = 80190428,
          GUID = "C8BF9218",
          NextDialogue = 80190429,
          SpeakNpcId = 95102,
          Subtitle = "Still. I've gotta start planning for the worst. Can't take any chances."
        },
        [80190429] = {
          ContentES = "¿Acaso en el pasado no existieron “posibilidades” similares? ¿Es más peligroso ahora que antes?",
          DialogueId = 80190429,
          GUID = "C8BF9242",
          NextDialogue = 80190430,
          SpeakNpcId = 790008,
          Subtitle = "This isn't the first time, is it? Is this one really more dangerous than the others?"
        },
        [80190430] = {
          ContentES = "Si tuviera que clasificar la peor, esta ni siquiera estaría en el top cinco.",
          DialogueId = 80190430,
          FacialId = {
            [1] = "95102:Think01"
          },
          GUID = "C8BF926C",
          NextDialogue = 80190431,
          SpeakNpcId = 95102,
          Subtitle = "Hmm... Come to think of it, this one might not even crack the top five.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190431] = {
          ContentES = "Exacto, entonces… ¿cómo resolviste esas cosas antes?",
          DialogueId = 80190431,
          GUID = "C8BF9296",
          NextDialogue = 80190432,
          SpeakNpcId = 790008,
          Subtitle = "Right? And how did you get through those?"
        },
        [80190432] = {
          ContentES = "Bueno algunas fueron solo falsas alarmas... fue sencillo resolverlo con intimidación, engaños o incluso involucrando a la Legión. Los trucos de siempre.",
          DialogueId = 80190432,
          GUID = "C8BF92C0",
          NextOptions = {
            [1] = 801904321,
            [2] = 801904322
          },
          SpeakNpcId = 95102,
          Subtitle = "Well... some turned out to be false alarms. Others... bluffing, baiting, dragging the Legion into it, staging a few \"cameos\" in far-off cities — you know, the usual."
        },
        [80190433] = {
          ContentES = "Outsider se queda pensando por un momento. Toma la copa y da un gran trago.",
          DialogueId = 80190433,
          GUID = "C8BF92EA",
          NextDialogue = 80190434,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190434] = {
          ContentES = "Tienes razón. No sé en qué estaba pensando. He sobrevivido a cosas mucho peores y ya hasta me adelanté a dejarte mi “último testamento”.",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Yeah... you're right. What was I thinking? I've lived through worse. One little scare, and here I am — handing you my last words like it's the end of the world.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          ContentES = "Quizás he pasado demasiado tiempo contigo. O quizás ahora que eres mi Capitán, una parte de mí pensó que podría depender de ti. O quizás... simplemente me he vuelto débil.",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102,
          Subtitle = "Maybe I've been spending too much time with you. Or maybe now that you're my Captain, some part of me thought I could lean a little. Or maybe... I've just gone soft."
        },
        [80190436] = {
          ContentES = "No, no… ¡Imposible! Debe ser que el licor está raro hoy, ¿Dije algo muy cursi hace un momento verdad? Dime la verdad, ¿lo hice? ¿no? ¿no, verdad?",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          Subtitle = "No, no, no — can't be. Must be this drink. You spiked it, didn't you? I didn't say anything soppy just now, right? Be honest — I didn't, yeah?",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          ContentES = "En fin, en lugar de preocuparte por lo que podría pasar, espera a que pase. Tal vez encontremos una mejor solución.",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008,
          Subtitle = "Anyway — rather than worry about what might happen, maybe we stay cool until it actually does. Who knows? By then, we might've already found a way through."
        },
        [80190438] = {
          ContentES = "Mmm... buen punto. ¡Salud! Brindo por mi yo del futuro. Ojalá sea más sabio y sensato que mi yo actual. Y por ti, por ser {性别:un buen amigo|una buena amiga}.",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102,
          Subtitle = "Hmm... good point. Cheers to that — here's to future me. May he be wiser and more put-together than current me. And to you — for being a good friend."
        },
        [80190439] = {
          ContentES = "Toma la copa y da un gran trago.",
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          ContentES = "Aun así... te debo una disculpa. He hecho las paces con lo que me espera, ¿pero con mi pasado? Aún no puedo contártelo todo. Todavía no.",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Still... I owe you an apology. I've made peace with whatever's ahead — but my past? I still can't tell you everything. Not yet.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          ContentES = "Pero te prometo que llegará el día en que te mostraré el camino que recorrí antes de llegar a Lago Helado. Aunque me cause dolor, quizá haga que cambies tu percepción de mí.",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102,
          Subtitle = "But I promise — someday, I'll show you the path that led me here. It won't be easy. And you might not like what you find."
        },
        [80190442] = {
          ContentES = "Pero creo que en ese momento, no dudarás en servirme un trago como esta noche, {性别:amigo mío|amiga mía}.",
          DialogueId = 80190442,
          GUID = "C8BF9464",
          SpeakNpcId = 95102,
          Subtitle = "But when that day comes... I believe you won't mind making me a drink like this one. Just like tonight, my friend."
        },
        [80200001] = {
          Camera = "-1480.738281,3129.994141,100.084961,0.000177,18.397858,-82.573738,35.0,3295.439453,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "春采薇，夏生苋，秋结枳，冬访芝……",
          DialogueId = 80200001,
          Duration = 1,
          FinalCamera = "-1480.738281,3129.994141,100.084961,0.000191,0.799146,-69.377235,35.0,3295.439453,false,Manual,2.8",
          GUID = "C8C5B4AA",
          NextDialogue = 80200002,
          SpeakNpcId = 790053,
          Subtitle = "Spring vetch, summer amaranth; autumn citrus, winter ganoderma...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B4AA"
        }
      }
    end
  },
  {
    MinKey = 80200002,
    MaxKey = 80210104,
    Loader = function()
      return {
        [80200002] = {
          CameraBlendCurve = "easeInOutQuad",
          Content = "不向阳处无灰木，冰雪心里紫露花。青草深处分碧薷，异香丛里是告苍……",
          DialogueId = 80200002,
          GUID = "C8C5B4D4",
          NextOptions = {
            [1] = 802000021,
            [2] = 802000022,
            [3] = 802000023
          },
          Scripts = [[
PARA{
MoveTo{_delay{10},ActorId{790008},TargetPoint{"BP_200101a_nvzhu01"},MoveSpeed{55},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{4},TargetPosition{"-6.146816,120.018967,141.563477,0.000095,5.200048,-128.788574,45.000023,110.798798,false,Manual,7.870067"},duration{0}},
CameraMoveTo{TargetPosition{"-9.100973,100.566628,143.263672,0.000098,5.199925,-138.591827,45.000023,93.368507,false,Manual,7.870067"},duration{35}}
},
SEQ{
CameraMoveTo{_delay{12},TargetPosition{"244.989624,223.965759,137.616211,0.000058,-2.599365,-155.996475,30.000008,381.480011,false,Manual,3.425282"},duration{0}},
CameraMoveTo{TargetPosition{"236.706024,240.90596,137.616211,0.000058,-2.599365,-152.396286,30.000008,381.480011,false,Manual,3.425282"},duration{10}}
},
LookAt{_delay{9.5},LookAtDescription{"790053:n(790008)"}},
TurnTo{_delay{10.6},TurnToDescription{"790053:n(790008)"}},
PlayAnimation{_delay{11.5},ActorId{790053},AnimationId{"Baiheng_Story_Special03_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Where no sun shines, Ashless Wood thrives; in hearts of frost, Dewiolet blooms. Beneath thick grasses, Verdawort coils; from hidden scents, Vesperleaf stirs.",
          ToFinalCameraBlendTime = 35,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B4D4"
        },
        [80200004] = {
          Content = "的确如此，方才提及的皆可入药，有的也可以食用。",
          DialogueId = 80200004,
          GUID = "C8C5B528",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          Subtitle = "Indeed. Each one bears medicinal properties — a few are even edible.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B528"
        },
        [80200006] = {
          Content = "呵呵，没想到你涉猎如此之广，正是出自《草木精要》。",
          DialogueId = 80200006,
          GUID = "C8C5B57C",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          Subtitle = "Hehe... I didn't know you were so well-read. You're right — it's from Essentials of Medicinal Herbs.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B57C"
        },
        [80200008] = {
          Content = "无碍，你我之间不必如此小心。你愿来拜访，我自是欢迎。",
          DialogueId = 80200008,
          GUID = "C8C5B5D0",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          Subtitle = "Not at all. There's no need for such formality between us. You're always welcome here.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B5D0"
        },
        [80200009] = {
          Camera = "330.082214,-1013.532104,415.926758,0.000049,-15.199328,108.205627,45.0,1011.382263,false,DoNotOverride,1.2",
          Content = "正巧，我已读了半晌书，是该休息的时候了。",
          DialogueId = 80200009,
          FinalCamera = "357.199249,-1095.939087,439.499023,0.000049,-15.199328,108.205627,45.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B5FA",
          NextDialogue = 80200010,
          Scripts = [[
PARA{
LookAt{_delay{3.1},LookAtDescription{"790053:n(790053)"}},
LookAt{_delay{3.5},LookAtDescription{"790008:n(790053)"}},
TurnTo{_delay{3},TurnToDescription{"790053:p(90)"}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "I've been reading for quite some time now... A short respite may be in order.",
          TalkActionId = {
            [1] = "790053:Talk02_End",
            [2] = [[

790008:Talk03_Start]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B5FA"
        },
        [80200010] = {
          Camera = "58.601952,177.411819,149.177734,0.000077,-2.599174,-139.997375,35.000008,198.557495,false,Manual,10.616697",
          Content = "只是如今的枯荣阁早已人去楼空，并无好茶款待，倒是失礼。",
          DialogueId = 80200010,
          FacialId = {
            [1] = "790053:Sad03"
          },
          FinalCamera = "65.497627,183.20816,149.582031,0.000077,-2.599174,-139.997391,35.000008,198.557495,false,Manual,10.616697",
          GUID = "C8C5B624",
          NextOptions = {
            [1] = 802000101,
            [2] = 802000102,
            [3] = 802000103
          },
          Scripts = "LookAt{_delay{5.1},LookAtDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Though this Hall of Ephemerality lies long deserted, I've no fine tea to serve... I fear I've made a poor host.",
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B624"
        },
        [80200012] = {
          Content = "起初确实不大习惯，但我实在留恋故地，因此不惯也惯了。",
          DialogueId = 80200012,
          GUID = "C8C5B678",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          Subtitle = "It was, at first. But my ties to this place run deep... and in time, I came to embrace the solitude.",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B678"
        },
        [80200014] = {
          Content = "谢你海涵，这就是所谓的“君子之交淡若水”吧。",
          DialogueId = 80200014,
          GUID = "C8C5B6CC",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          Subtitle = "Thank you for your forbearance. I suppose this is what they call \"a friendship as calm as water\".",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B6CC"
        },
        [80200016] = {
          Content = "饿了吗？但此刻天色尚早，并不是正经用餐的时候，再过些时候吧。",
          DialogueId = 80200016,
          GUID = "C8C5B720",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          Subtitle = "Feeling hungry already? But it's still a touch early for a proper meal. Bear with it a while longer, if you can.",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B720"
        },
        [80200017] = {
          Camera = "-634.981689,1124.922974,959.174805,0.000074,-35.198467,-55.38472,30.0,1833.385742,false,DoNotOverride,10.243358",
          Content = "难得今日有缘相见，那我也不再遮掩，其实……扶疏有一事相求。",
          DialogueId = 80200017,
          Duration = 1,
          FinalCamera = "-886.519958,1045.29541,1024.44043,0.000078,-35.798367,-46.98473,30.0,1833.385742,false,DoNotOverride,10.243358",
          GUID = "C8C5B74A",
          NextDialogue = 80200018,
          Scripts = "PlayAnimation{_delay{3.5},ActorId{790053},AnimationId{\"Baiheng_Story_Special01_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Since fate has granted us this rare encounter, allow me to speak plainly. There is... something I wish to ask of you.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790053:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B74A"
        },
        [80200018] = {
          Camera = "-368.470367,-21.31028,215.013672,0.000096,-14.799707,17.818779,30.0,498.626465,false,Manual,4.781349",
          Content = "可以说来听听。",
          DialogueId = 80200018,
          Duration = 1,
          FinalCamera = "-368.470367,-21.31028,204.082031,0.000096,-14.799714,17.818808,30.0,498.626465,false,Manual,4.781349",
          GUID = "C8C5B774",
          NextDialogue = 80200019,
          SpeakNpcId = 790008,
          Subtitle = "Go ahead. I'm listening.",
          TalkActionId = {
            [1] = "790008:Talk02_Start",
            [2] = "790053:Baiheng_Story_Special01_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B774"
        },
        [80200019] = {
          Content = "上次凭笔记中寻来的方子治好了那位被玄色狴犴所伤的姑娘，使我对药理生出几分兴趣。",
          DialogueId = 80200019,
          GUID = "C8C5B79E",
          NextDialogue = 80200020,
          SpeakNpcId = 790053,
          Subtitle = "The other day, I treated the young lady wounded by that Sable Bi'an using a remedy I found in one of my sister's old notes. It stirred in me... an interest in pharmacology.",
          TalkActionId = {
            [1] = "790008:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B79E"
        },
        [80200020] = {
          Camera = "13.768398,198.582336,146.612305,0.000078,-0.599117,-112.591949,35.0,194.999741,false,Manual,7.870067",
          Content = "扶氏世代以枯荣之术救人，药理则是近百年才出现的学问。家姐生前精于此道，我所知却是微末。",
          DialogueId = 80200020,
          FinalCamera = "13.768398,198.582336,142.704102,0.000078,-0.599117,-112.591949,35.0,194.999741,false,Manual,7.870067",
          GUID = "C8C5B7C8",
          NextDialogue = 80200021,
          Scripts = [[
PARA{
PlayAnimation{_delay{10},ActorId{790053},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "My clan has long practised the Art of Ephemerality. But pharmacology — as a formal discipline — has only emerged in the past century. My sister excelled in it. As for me... my grasp is but fragmentary.",
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = "790053:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B7C8"
        },
        [80200021] = {
          Camera = "0.365,149.368027,144.621094,0.000082,-0.199114,-123.592377,35.0,139.78009,false,Manual,10.0",
          Content = "我……我想贯彻家传使命的愿望自然未改，但从棺中苏醒的因缘，是家姐与她的弟子耗尽心血得来，我也不愿轻易辜负他们。",
          DialogueId = 80200021,
          FinalCamera = "-2.978582,144.336792,144.600586,0.000082,-0.199114,-123.592377,35.0,139.78009,false,Manual,10.0",
          GUID = "C8C5B7F2",
          NextDialogue = 80200022,
          SpeakNpcId = 790053,
          Subtitle = "I've never wavered in my wish to carry forward our family's calling. Yet my return from a long slumber — that miracle was wrought by the lifelong efforts of my sister and her disciples. Such devotion... cannot go unanswered.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B7F2"
        },
        [80200022] = {
          Camera = "-56.301811,69.71508,137.660156,0.000099,-1.798833,52.211357,30.000002,113.82692,false,Manual,7.870067",
          Content = "因此我才试着去研习如今的医药学问，但这样的事终究是纸上得来终觉浅。",
          DialogueId = 80200022,
          FinalCamera = "-51.461147,75.961639,137.414062,0.000099,-1.798833,52.211399,30.000002,113.82692,false,Manual,7.870067",
          GUID = "C8C5B81C",
          NextDialogue = 80200023,
          SpeakNpcId = 790053,
          Subtitle = "That's why I've begun studying modern medicine. But books alone can only take one so far.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B81C"
        },
        [80200023] = {
          Camera = "-1016.887939,779.020264,118.349609,0.000108,1.800718,-34.790836,35.0,1192.438843,false,Manual,1.460963",
          Content = "我一直很想找人实践一番，看看要如何去望闻问切，所谓病理，在人身上究竟是何等境况。",
          DialogueId = 80200023,
          Duration = 2,
          FinalCamera = "-1097.473145,835.017334,72.382812,0.00011,1.800718,-34.790791,35.0,1303.897095,false,Manual,1.460963",
          GUID = "C8C5B846",
          NextDialogue = 80200024,
          SpeakNpcId = 790053,
          Subtitle = "What I truly long for is practice — to observe, to examine, to diagnose... To understand what illness means in the living body.",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B846"
        },
        [80200024] = {
          Content = "只是百年光阴转瞬即逝，我在此地早已是无亲无友。",
          DialogueId = 80200024,
          GUID = "C8C5B870",
          NextDialogue = 80200025,
          SpeakNpcId = 790053,
          Subtitle = "But a century has passed in the blink of an eye. I have no kin left... no companions in this era.",
          TalkActionId = {
            [1] = "790053:Baiheng_Story_Special03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B870"
        },
        [80200025] = {
          Camera = "37.140533,321.639557,117.170898,0.00008,4.200812,-104.992432,35.0,316.709778,false,Manual,7.870067",
          Content = "若随意为人诊治，要是出了差错，岂不成了医德不修之人？",
          DialogueId = 80200025,
          FinalCamera = "22.796768,325.479004,117.170898,0.000079,4.200812,-101.992027,35.0,309.972931,false,Manual,7.870067",
          GUID = "C8C5B89A",
          NextDialogue = 80200026,
          SpeakNpcId = 790053,
          Subtitle = "And if I were to err in treating a stranger... it would be malpractice, no different from harm.",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B89A"
        },
        [80200026] = {
          Content = "若要寻找有些交情，也愿担待扶疏一二的……思来想去，你竟是唯一的人选。",
          DialogueId = 80200026,
          Duration = 2,
          GUID = "C8C5B8C4",
          NextDialogue = 80200027,
          SpeakNpcId = 790053,
          Subtitle = "So I searched my thoughts for someone who knows me — who might be willing to take that risk for me. In the end... there is only you.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B8C4"
        },
        [80200027] = {
          Camera = "-290.514648,-38.780998,123.578125,0.000118,-0.99953,28.606005,40.000011,357.798157,false,Manual,3.557784",
          Content = "然而身体状况乃是私隐，你若不愿，我定不会勉强你。",
          DialogueId = 80200027,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-316.806091,-53.123318,124.101562,0.00012,-0.99953,28.606005,40.000011,391.280212,false,Manual,3.557784",
          GUID = "C8C5B8EE",
          NextOptions = {
            [1] = 802000271,
            [2] = 802000272,
            [3] = 802000273
          },
          SpeakNpcId = 790053,
          Subtitle = "That said, health is a deeply private matter. If you are unwilling, I shall not press you.",
          TalkActionId = {
            [1] = "790008:Laugh01_Start",
            [2] = "790053:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B8EE"
        },
        [80200029] = {
          Content = "多谢……对你来说虽是举手小事，但扶疏铭记在心。",
          DialogueId = 80200029,
          GUID = "C8C5B942",
          NextDialogue = 80200034,
          SpeakNpcId = 790053,
          Subtitle = "My thanks... It may seem a small kindness to you, but I shall carry it close to heart.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B942"
        },
        [80200031] = {
          Content = "诶？竟、竟如此信任我吗？等一下，倒也不用这么急着脱下斗篷……",
          DialogueId = 80200031,
          GUID = "C8C5B996",
          NextDialogue = 80200034,
          SpeakNpcId = 790053,
          Subtitle = "Eh—? Y—You trust me that much!? Wait, there's no need to take off your cloak just yet...",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B996"
        },
        [80200033] = {
          Content = "我自然不会提如此危险之事！不过……这是答应的意思吗？",
          DialogueId = 80200033,
          GUID = "C8C5B9EA",
          NextDialogue = 80200034,
          SpeakNpcId = 790053,
          Subtitle = "Heavens, I'd never ask anything so perilous! But... was that a yes?",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B9EA"
        },
        [80200034] = {
          Camera = "-12.930632,116.6409,137.194336,0.000094,6.600558,-127.588852,45.000011,194.999756,false,DoNotOverride,7.870067",
          Content = "承蒙不弃，扶疏一定尽力而为。",
          DialogueId = 80200034,
          FacialId = {
            [1] = "790053:None"
          },
          GUID = "C8C5BA14",
          NextDialogue = 80200035,
          SpeakNpcId = 790053,
          Subtitle = "Then... you have my deepest thanks. I'll give it everything I have.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA14"
        },
        [80200035] = {
          Content = "扶疏仔仔细细地为你诊治一番。",
          DialogueId = 80200035,
          GUID = "C8C5BA3E",
          IsBlack = 1,
          Subtitle = "Fushu conducts a thorough and meticulous examination.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA3E"
        },
        [80200036] = {
          Camera = "-40.848995,85.709183,149.865234,0.000094,1.200781,-124.785934,45.000011,194.999756,false,DoNotOverride,7.870067",
          Content = "嗯……你的身体十分健康，至少在我看来没有什么大的不妥，只是……",
          DialogueId = 80200036,
          Duration = 2,
          FinalCamera = "-27.404249,104.783081,149.896484,0.000094,0.000697,-124.58551,45.000023,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BA68",
          NextDialogue = 80200037,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{5.5},ActorId{790053},FacialId{"Sad03"}},
LookAt{_delay{5.5},LookAtDescription{"790053:n(790008)"}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Hm... You're in good health overall — at least, from what I can observe. However...",
          TalkActionId = {
            [1] = "790053:AgreeHead"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA68"
        },
        [80200037] = {
          Camera = "392.614807,235.654694,222.652344,0.000092,-12.197959,-161.590683,35.0,526.995789,false,Manual,5.0",
          Content = "从面色上看不出来，但您应该很久、很久没有睡觉了吧？",
          DialogueId = 80200037,
          FinalCamera = "428.94931,247.75415,230.928711,0.000092,-12.197959,-161.590683,35.0,575.327454,false,Manual,5.0",
          GUID = "C8C5BA92",
          NextOptions = {
            [1] = 802000371,
            [2] = 802000372,
            [3] = 802000373
          },
          Scripts = "PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "It doesn't show in your face, but... you've been without proper rest for quite some time, haven't you?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA92"
        },
        [80200039] = {
          Camera = "-68.012299,-87.562286,149.491211,0.000127,-4.999302,78.203064,45.000023,243.328293,false,Manual,7.870067",
          Content = "长此以往，可能会落下病根，可要千万注意。若是没有安枕的地方，这枯荣阁也可做你暂时落脚的地方。",
          DialogueId = 80200039,
          FinalCamera = "-71.695663,-105.224762,151.068359,0.000125,-4.999302,78.203476,45.000023,243.328293,false,Manual,7.870067",
          GUID = "C8C5BAE6",
          NextDialogue = 80200049,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{790008},AnimationId{\"Sad02_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "If this keeps up, it could take a real toll on your health. Please take care. And if you've nowhere else to rest... the Hall of Ephemerality is open to you — for as long as you need.",
          TalkActionId = {
            [1] = "790008:Sad02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BAE6"
        },
        [80200041] = {
          Camera = "83.14875,64.28849,101.996094,0.000119,14.400353,-169.600876,45.000023,174.605179,false,Manual,13.342517",
          Content = "求财虽是人之常情，但连轴转并不可取。如果不加改善，下次就没有免费诊治的机会了，或许……我还会考虑向你收取高额诊金喔。",
          DialogueId = 80200041,
          FinalCamera = "100.070984,67.397232,97.577148,0.000119,14.400353,-169.600876,45.000023,174.605179,false,Manual,13.342517",
          GUID = "C8C5BB3A",
          NextDialogue = 80200042,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.5},ActorId{790053},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{9},ActorId{790053},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Seeking fortune is only natural... but pushing yourself to exhaustion is far from wise. If this persists, your next check-up won't be complimentary. I might even have to levy a rather steep consultation fee.",
          TalkActionId = {
            [1] = "790053:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BB3A"
        },
        [80200042] = {
          Camera = "-68.012299,-87.562286,149.491211,0.000127,-4.999302,78.203064,45.000023,243.328293,false,Manual,7.870067",
          Content = "不——要——啊——我——要——撤——回——这——个——诊——疗——",
          DialogueId = 80200042,
          FacialId = {
            [1] = "790008:Shock01"
          },
          FinalCamera = "-71.695663,-105.224762,151.068359,0.000125,-4.999302,78.203476,45.000023,243.328293,false,Manual,7.870067",
          GUID = "C8C5BB64",
          NextDialogue = 80200049,
          SpeakNpcId = 790008,
          Subtitle = "Nooo... I take it back!",
          TalkActionId = {
            [1] = "790008:Deny01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BB64"
        },
        [80200044] = {
          Camera = "18.80476,51.77895,116.756836,0.000134,19.000513,-169.000351,45.000023,104.895348,false,Manual,13.342517",
          Content = "嗯……如果病人的态度非常不配合的话，我只能把药方换成别的了。",
          DialogueId = 80200044,
          FacialId = {
            [1] = "790053:None"
          },
          FinalCamera = "31.438776,54.239975,112.322266,0.000134,19.000513,-169.000351,45.000023,104.895348,false,Manual,13.342517",
          GUID = "C8C5BBB8",
          NextDialogue = 80200045,
          SpeakNpcId = 790053,
          Subtitle = "Hm... If the patient proves especially noncompliant, I may have to prescribe a more... hands-on remedy.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BBB8"
        },
        [80200045] = {
          Camera = "-59.732349,80.69458,137.875,0.000137,3.600158,57.199467,45.000023,104.895348,false,Manual,13.342517",
          Content = "比如？",
          DialogueId = 80200045,
          FacialId = {
            [1] = "790008:Shock01"
          },
          FinalCamera = "-46.697857,72.286606,137.875,0.000137,3.600158,57.199017,45.000023,104.895348,false,Manual,13.342517",
          GUID = "C8C5BBE2",
          NextDialogue = 80200046,
          SpeakNpcId = 790008,
          Subtitle = "Like what?",
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BBE2"
        },
        [80200046] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          Content = "我自幼练武，只是寻常伤筋动骨的话，不用枯荣之术我也能医治。",
          DialogueId = 80200046,
          FinalCamera = "77.175941,183.945618,140.588867,0.000115,0.600701,-140.191589,45.000011,215.31575,false,Manual,7.870067",
          GUID = "C8C5BC0C",
          NextDialogue = 80200047,
          SpeakNpcId = 790053,
          Subtitle = "I trained in martial arts from a young age. For ordinary sprains or fractures, I can manage treatment even without the Art of Ephemerality.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC0C"
        },
        [80200047] = {
          Camera = "-68.012299,-87.562286,149.491211,0.000127,-4.999302,78.203064,45.000023,243.328293,false,Manual,7.870067",
          Content = "不过有时病人疼得厉害，乱动起来可能会加重病情，这时候只要击打这里，就可以让人暂时失去意识，来，我指给你看……",
          DialogueId = 80200047,
          FinalCamera = "-71.695663,-105.224762,151.068359,0.000125,-4.999302,78.203476,45.000023,243.328293,false,Manual,7.870067",
          GUID = "C8C5BC36",
          NextDialogue = 80200048,
          Scripts = "PlayAnimation{_delay{6.5},ActorId{790008},AnimationId{\"Shock03_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "But if a patient thrashes in pain, it could aggravate the injury... In such cases, a strike here may render them unconscious. Come — allow me to show you.",
          TalkActionId = {
            [1] = "790053:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC36"
        },
        [80200048] = {
          Camera = "-62.237785,15.439123,144.02832,0.000127,-1.999053,63.202065,45.000023,156.11145,false,Manual,7.870067",
          Content = "不不不用了医生，我选择保守治疗！",
          DialogueId = 80200048,
          GUID = "C8C5BC60",
          NextDialogue = 80200049,
          SpeakNpcId = 790008,
          Subtitle = "N—No, thank you! I'll take the conservative treatment!",
          TalkActionId = {
            [1] = "790008:Shock03_End",
            [2] = "790008:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC60"
        },
        [80200049] = {
          Camera = "917.762695,-1503.946777,620.68457,0.00014,-11.399223,120.200478,50.0,1992.261841,false,Manual,7.870067",
          Content = "确实能察觉到，你的睡眠时间少到了夸张的地步……是有失眠，或者入睡困难之类的问题吗？",
          DialogueId = 80200049,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "906.586975,-1504.471436,476.373047,0.000145,-11.399176,120.200394,50.0,1992.261841,false,Manual,7.870067",
          GUID = "C8C5BC8A",
          NextDialogue = 80200050,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.5},ActorId{790053},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{9.5},ActorId{790053},AnimationId{"Talk01_End"},Duration{1}}
}
]],
          SpeakNpcId = 790053,
          Subtitle = "Your level of sleep deprivation is quite severe... Have you been struggling with insomnia? Or difficulty falling asleep?",
          TalkActionId = {
            [1] = "790053:AgreeHead"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC8A"
        },
        [80200050] = {
          Camera = "29.712376,30.286741,171.701172,0.000042,-16.598623,100.198341,35.0,121.834335,false,Manual,7.870067",
          Content = "我可能是天生觉少……不过我有多梦的症状。有时从梦中突然惊醒，就再也睡不着了。",
          DialogueId = 80200050,
          FinalCamera = "31.944149,17.895794,175.456055,0.000043,-16.598602,100.198334,35.0,141.404282,false,Manual,7.870067",
          GUID = "C8C5BCB4",
          NextDialogue = 80200051,
          SpeakNpcId = 790008,
          Subtitle = "Maybe I'm just someone who doesn't need much sleep by nature... But I do dream a lot. Sometimes I wake suddenly and can't fall back asleep.",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BCB4"
        },
        [80200051] = {
          Camera = "21.420506,52.709782,178.382812,0.00004,-17.199427,-170.186905,35.0,194.999756,false,DoNotOverride,7.870067",
          Content = "竟是如此。我还以为你是自入华胥以来无暇休息所致，原来是老症候了。",
          DialogueId = 80200051,
          FinalCamera = "38.83992,55.71632,183.859375,0.000053,-17.199413,-170.186905,35.0,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BCDE",
          NextDialogue = 80200052,
          SpeakNpcId = 790053,
          Subtitle = "I see. I had assumed it was merely the pace of life since arriving in Huaxu... but this runs deeper. You've carried it with you far longer.",
          TalkActionId = {
            [1] = "790053:Explain02_Start",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BCDE"
        },
        [80200052] = {
          Camera = "360.680786,-114.169701,136.203125,0.000063,-0.798668,151.998245,40.0,439.529266,false,Manual,7.870067",
          Content = "不过我已经想好了一剂药方，不敢保证药到病除，但坚持服用也会有所裨益。",
          DialogueId = 80200052,
          FinalCamera = "383.679688,-126.399124,136.564453,0.000063,-0.798668,151.998245,40.0,439.529266,false,Manual,7.870067",
          GUID = "C8C5BD08",
          NextDialogue = 80200053,
          SpeakNpcId = 790053,
          Subtitle = "In any case, I've prepared a formula. I can't promise immediate results, but with consistent use, it should gradually ease the symptoms.",
          TalkActionId = {
            [1] = "790008:Shy03_Start",
            [2] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD08"
        },
        [80200053] = {
          Camera = "-677.720764,380.481873,76.758789,0.000025,-31.199032,162.811325,35.0,313.548645,false,Manual,1.445948",
          Content = "只是……其中最关键的一味“怀梦草”，是枯荣阁中没有的。要去百年春求购，又需好些时日。",
          DialogueId = 80200053,
          FinalCamera = "-710.28772,390.565186,56.109375,0.000025,-31.199032,162.811325,35.000008,732.714722,false,DoNotOverride,1.445948",
          GUID = "C8C5BD32",
          NextDialogue = 80200054,
          SpeakNpcId = 790053,
          Subtitle = "That said... the key ingredient is Oneirowort — and the Hall of Ephemerality is currently out of stock. It's normally sourced from EverSpring, but procuring it may take days.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD32"
        },
        [80200054] = {
          Camera = "778.143555,49.141846,84.628906,0.000074,3.000878,175.011826,35.0,841.834229,false,Manual,1.445948",
          Content = "最好便是枯荣阁附近寻上一寻，若是幸运，今晚你便能好好休息了。不知你意下如何呢？",
          DialogueId = 80200054,
          FinalCamera = "775.015259,13.243744,84.628906,0.000074,3.000878,175.011826,35.0,841.834229,false,Manual,1.445948",
          GUID = "C8C5BD5C",
          NextDialogue = 80200055,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{790053},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{"Baiheng_Story_Special03_Start"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Our best chance may be to search the nearby area. With luck, you might sleep soundly as soon as tonight. What do you think?",
          TalkActionId = {
            [1] = "790053:Think_Start",
            [2] = "790008:Shy03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD5C"
        },
        [80200055] = {
          Camera = "-138.100891,-376.441467,153.882812,0.000078,-5.798817,78.616974,35.0,194.999756,false,DoNotOverride,7.870067",
          Content = "那就多谢你了！",
          DialogueId = 80200055,
          FinalCamera = "-148.366501,-427.434601,159.165039,0.000079,-5.798817,78.617157,35.0,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BD86",
          NextDialogue = 80200056,
          SpeakNpcId = 790008,
          Subtitle = "Sounds great! I'd appreciate that.",
          TalkActionId = {
            [1] = "790008:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD86"
        },
        [80200056] = {
          Camera = "233.269958,261.403778,125.821289,0.000096,0.201415,-148.185486,35.000008,194.999756,false,DoNotOverride,7.870067",
          Content = "时间不等人，即刻出发吧。",
          DialogueId = 80200056,
          FinalCamera = "260.721527,278.433655,125.711914,0.000096,0.201415,-148.185486,35.000008,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BDB0",
          Scripts = "PlayAnimation{_delay{3.5},ActorId{790008},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Come — no sense in lingering.",
          TalkActionId = {
            [1] = "790008:ScratchHead_End",
            [2] = "790053:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BDB0"
        },
        [80200101] = {
          Camera = "1531.92334,3538.163574,1883.558594,0.000098,-23.599333,-116.380653,25.0,3742.911621,false,Manual,1.2",
          Content = "潺潺水底伏流荇，静静池上开莲草。树下菌邻怀梦草，难分彼此是音容……",
          DialogueId = 80200101,
          FinalCamera = "1369.106445,3209.869629,1836.991211,0.0001,-23.599354,-116.380653,25.0,3742.911621,false,Manual,1.2",
          GUID = "C8C5C512",
          NextDialogue = 80200102,
          Scripts = [[
PARA{
MoveTo{ActorId{790008},TargetPoint{"BP_Stage_200201a nvzhu00"},MoveSpeed{75},Visibility{"Show"}},
MoveTo{ActorId{790053},TargetPoint{"BP_Stage_200201a fushu00"},MoveSpeed{75},Visibility{"Show"}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Liltfern sways where waters stream; Eclipta blooms where ripples gleam. Where fungi root beneath the tree, Oneirowort and Echowort be — Which is which, none e'er could see.",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C512"
        },
        [80200102] = {
          Camera = "272.323822,540.773193,-5.51709,0.000158,1.596106,-125.767914,25.0,504.355042,false,Manual,2.8",
          Content = "刚才就听到你在诵读这些句子，有什么含义吗？",
          DialogueId = 80200102,
          FinalCamera = "285.816895,531.043884,-5.51709,0.000157,1.596106,-125.767914,25.0,504.355042,false,Manual,2.8",
          GUID = "C8C5C53C",
          NextDialogue = 80200103,
          Scripts = "PlayAnimation{_delay{3.5},ActorId{790053},AnimationId{\"Shy02_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "I heard you reciting something earlier — what do those lines mean?",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C53C"
        },
        [80200103] = {
          Content = "这是《草木精要》附录中的一首歌谣，简单介绍了一些药草的生长环境，方便有需要的人寻找它们。",
          DialogueId = 80200103,
          GUID = "C8C5C566",
          NextDialogue = 80200104,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{\"Shy02_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "A rhyme from the appendix of Essentials of Medicinal Herbs — a simple mnemonic verse describing where certain plants tend to grow. It was written to help folk find remedies in times of need.",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C566"
        },
        [80200104] = {
          Content = "在如今的华胥，基本人人都能背上几句，也算是耳熟能详了。",
          DialogueId = 80200104,
          GUID = "C8C5C590",
          NextDialogue = 80200105,
          SpeakNpcId = 790053,
          Subtitle = "These days in Huaxu, most people know at least a few lines. It's become something of a common chant.",
          TurnTo = {
            [1] = "790053:p(-170)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C590"
        },
        [80200105] = {
          Content = "了解过后，若是碰上被虫蛇咬伤，或是突发疾病，便知道在哪里寻药救急。",
          DialogueId = 80200105,
          GUID = "C8C5C5BA",
          NextDialogue = 80200106,
          SpeakNpcId = 790053,
          Subtitle = "Once committed to memory, it teaches you where to search — should you be bitten by a snake, stung by an insect, or fall ill far from aid.",
          TalkActionId = {
            [1] = "790053:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C5BA"
        },
        [80200106] = {
          Camera = "1127.049072,-417.77417,137.300293,0.000186,-4.403259,-49.972614,45.0,865.540161,false,Manual,2.8",
          Content = "方才我念的这几句，是说在水底可以找到流荇，在池塘中能寻道莲草，而怀梦草则通常生在树下，与菌类为邻，但……",
          DialogueId = 80200106,
          FinalCamera = "1169.831299,-381.845581,137.300293,0.000186,-4.403259,-49.972614,45.0,865.540161,false,Manual,2.8",
          GUID = "C8C5C5E4",
          NextDialogue = 80200107,
          SpeakNpcId = 790053,
          Subtitle = "The part I was reciting says Liltfern grows beneath the stream, Eclipta Grass by the water's edge, and Oneirowort by tree roots — often where fungi thrive. However...",
          TalkActionId = {
            [1] = "790053:Explain01_End"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C5E4"
        },
        [80200107] = {
          Content = "有一种名叫音容草的植物，与怀梦草十分相似，不是有经验的医生或是采药人，几乎无从分辨。",
          DialogueId = 80200107,
          GUID = "C8C5C60E",
          NextDialogue = 80200108,
          SpeakNpcId = 790053,
          Subtitle = "There's another plant, Echowort, that so closely resembles Oneirowort it's near impossible to tell them apart, unless you're a seasoned herbalist or physician.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C60E"
        },
        [80200108] = {
          Camera = "-43.556976,175.887131,26.972168,0.00019,2.19607,-57.766472,35.0,102.559563,false,Manual,8.468321",
          Content = "家姐的笔记中倒是附上过对比插图，就是……",
          DialogueId = 80200108,
          GUID = "C8C5C638",
          NextDialogue = 80200109,
          SpeakNpcId = 790053,
          Subtitle = "My sister left behind some comparative sketches in her notes, but...",
          TalkActionId = {
            [1] = "790053:Think_Start"
          },
          TurnTo = {
            [1] = "790008:n(790053)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C638"
        },
        [80200109] = {
          Camera = "-2162.862305,-1856.842285,475.34668,0.000297,-6.00418,31.439232,25.0,3742.911621,false,Manual,2.8",
          Content = "（扶疏对你摊开了一本旧书册，你瞄了一眼那堪比卢卡先锋艺术的画作，与扶疏面面相觑。）",
          DialogueId = 80200109,
          Duration = 8,
          FinalCamera = "-2293.00708,-1643.934814,475.34668,0.000282,-6.004153,31.438747,25.0,3742.911621,false,Manual,2.8",
          GUID = "C8C5C662",
          LookAt = {
            [1] = "790053:n(790008)"
          },
          NextDialogue = 80200110,
          Scripts = "MoveTo{ActorId{790008},TargetPoint{\"BP_Stage_200201a nvzhu01\"},MoveSpeed{75},Visibility{\"Show\"}}",
          Subtitle = "(Fushu opens a weathered tome before you. You glance at the illustration — it wouldn't look out of place in one of Luca's avant-garde exhibits. You and Fushu exchange a helpless look.)",
          TalkActionId = {
            [1] = "790053:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790053:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C662"
        },
        [80200110] = {
          Camera = "-17.572052,-65.612328,29.06543,0.000324,-4.803699,88.838623,25.000006,198.752441,false,Manual,2.86577",
          Content = "……就没有别的办法了吗？",
          DialogueId = 80200110,
          FinalCamera = "-17.572052,-65.612328,22.90918,0.000324,-4.603697,89.038612,25.000006,198.752441,false,Manual,2.86577",
          GUID = "C8C5C68C",
          LookAt = {
            [1] = "790008:n(790053)"
          },
          NextDialogue = 80200111,
          SpeakNpcId = 790008,
          Subtitle = "...Is there any other way?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C68C"
        },
        [80200111] = {
          Content = "有的。",
          DialogueId = 80200111,
          GUID = "C8C5C6B6",
          NextDialogue = 80200112,
          SpeakNpcId = 790053,
          Subtitle = "There is.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C6B6"
        },
        [80200112] = {
          Content = "这都能分辨，说自己不精医药，不会只是自谦吧？",
          DialogueId = 80200112,
          GUID = "C8C5C6E0",
          NextDialogue = 80200113,
          SpeakNpcId = 790008,
          Subtitle = "You can actually make sense of this? And you still say you're not good at pharmacology?",
          TalkActionId = {
            [1] = "790053:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C6E0"
        },
        [80200113] = {
          Camera = "-100.957642,97.399895,23.348633,-0.0,2.59638,5.238194,25.000006,107.654762,false,Manual,8.945262",
          Content = "那确是肺腑之言。",
          DialogueId = 80200113,
          FinalCamera = "-110.44091,100.271729,22.933105,-0.0,2.59638,5.238703,25.000006,107.654762,false,Manual,9.192281",
          GUID = "C8C5C70A",
          NextDialogue = 80200114,
          SpeakNpcId = 790053,
          Subtitle = "I meant what I said. My knowledge barely scratches the surface.",
          TalkActionId = {
            [1] = "790008:Think_End",
            [2] = "790053:Shy03_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C70A"
        },
        [80200114] = {
          Content = "因此，我打算尝一口。",
          DialogueId = 80200114,
          GUID = "C8C5C734",
          NextOptions = {
            [1] = 802001141,
            [2] = 802001142,
            [3] = 802001143
          },
          SpeakNpcId = 790053,
          Subtitle = "Which is why... I plan to taste it.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C734"
        },
        [80200118] = {
          Camera = "-7.335266,63.901058,19.666992,0.000328,0.796134,114.242729,25.000006,73.700699,false,Manual,6.954087",
          Content = "现在？",
          DialogueId = 80200118,
          GUID = "C8C5C7DC",
          NextDialogue = 80200119,
          SpeakNpcId = 790008,
          Subtitle = "Right now?",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C7DC"
        },
        [80200119] = {
          Camera = "-124.730896,121.885643,18.354492,0.000339,4.396244,-8.16414,40.000011,142.142242,false,Manual,10.751457",
          Content = "现在。",
          DialogueId = 80200119,
          GUID = "C8C5C806",
          NextDialogue = 80200120,
          SpeakNpcId = 790053,
          Subtitle = "Right now.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C806"
        },
        [80200120] = {
          Camera = "-19.875801,64.694672,26.397461,0.000339,-4.003659,104.637611,35.000008,61.685242,false,Manual,8.529664",
          Content = "直接吃？",
          DialogueId = 80200120,
          FacialId = {
            [1] = "790008:Shock01"
          },
          GUID = "C8C5C830",
          NextDialogue = 80200121,
          SpeakNpcId = 790008,
          Subtitle = "You're really going to eat it?",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C830"
        },
        [80200121] = {
          Camera = "-61.263931,118.475212,29.812012,0.000339,1.596277,-18.963583,40.000011,71.518158,false,Manual,10.743117",
          Content = "直接吃。",
          DialogueId = 80200121,
          FacialId = {
            [1] = "790053:Confident02"
          },
          GUID = "C8C5C85A",
          NextDialogue = 80200122,
          SpeakNpcId = 790053,
          Subtitle = "I am.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C85A"
        },
        [80200122] = {
          Camera = "56.401764,-276.272797,359.396973,0.000302,-23.203312,-69.771858,35.0,957.564941,false,DoNotOverride,1.963203",
          Content = "你放心，音容草的毒性十分轻微，对有些人甚至不起作用，顶多只是看到些幻象——啊，我们有一个叫做“音容笑貌”的词，这种草的名字就取自这里……",
          DialogueId = 80200122,
          FinalCamera = "184.088745,-229.228088,359.396484,0.000302,-23.203312,-69.771858,35.0,957.564941,false,DoNotOverride,1.963203",
          GUID = "C8C5C884",
          NextDialogue = 80200123,
          SpeakNpcId = 790053,
          Subtitle = "Don't worry — Echowort's toxins are exceedingly mild. Some feel nothing at all. At most, you may glimpse a fleeting vision. Its name stems from an old saying: \"to leave one's echoes and smiles in another's memory\" — a poetic way of remembering the departed.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C884"
        },
        [80200123] = {
          Content = "……我怎么听了更不放心了！",
          DialogueId = 80200123,
          GUID = "C8C5C8AE",
          NextDialogue = 80200124,
          SpeakNpcId = 790008,
          Subtitle = "...You do know that doesn't exactly make me less worried about you, right?",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C8AE"
        },
        [80200124] = {
          Camera = "-849.182129,91.680786,200.708984,0.000292,-14.003527,-4.370487,35.0,193.602356,false,DoNotOverride,1.963203",
          Content = "无妨，事物的有毒与无毒还是要看剂量决定。",
          DialogueId = 80200124,
          FinalCamera = "-1086.069824,90.220459,259.590332,0.000292,-14.003512,-4.37048,35.0,957.564941,false,DoNotOverride,1.963203",
          GUID = "C8C5C8D8",
          NextDialogue = 80200125,
          SpeakNpcId = 790053,
          Subtitle = "There's no need for alarm. In most cases, whether a plant is poisonous or not lies in the dose.",
          TalkActionId = {
            [1] = "790053:Shy02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C8D8"
        },
        [80200125] = {
          Content = "而音容草，只是吃下一小片叶子的话，就算产生幻觉，也只会维持几分钟而已。",
          DialogueId = 80200125,
          GUID = "C8C5C902",
          NextDialogue = 80200126,
          SpeakNpcId = 790053,
          Subtitle = "A single sliver of Echowort may bring on a vision — but it fades swiftly.",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C902"
        },
        [80200126] = {
          Content = "虽然……医师们大多不建议这么做，但这确实是最容易分辨两种药草的方法，有不少采药人也会这么做。",
          DialogueId = 80200126,
          GUID = "C8C5C92C",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200127,
          SpeakNpcId = 790053,
          Subtitle = "Most physicians discourage this method... yet for many herb gatherers, it remains the surest test.",
          TalkActionId = {
            [1] = "790053:Shy02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C92C"
        },
        [80200127] = {
          Camera = "24.366035,-108.460983,18.662598,0.000304,5.595769,91.042618,25.000006,87.857491,false,Manual,5.644706",
          Content = "况且我乃枯荣之术传人，就算中了些药草毒性也会很快自愈。你放心。",
          DialogueId = 80200127,
          FacialId = {
            [1] = "790008:Sad03"
          },
          FinalCamera = "29.917435,-114.85643,18.026367,0.000304,5.595769,91.042618,25.000006,88.778442,false,Manual,9.148426",
          GUID = "C8C5C956",
          NextDialogue = 80200128,
          Scripts = "MoveTo{_delay{0.5},ActorId{790053},TargetPoint{\"BP_Stage_200201a fushu01\"},MoveSpeed{75},Visibility{\"Show\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Besides — I practise the Art of Ephemerality. Even if a reaction occurs, I can recover at once. Truly, there's no need to worry.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790053:p(100)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C956"
        },
        [80200128] = {
          Camera = "-110.911285,136.177673,10.118164,0.000291,2.795774,-37.361984,25.000006,193.602356,false,Manual,1.963203",
          Content = "（扶疏摘取了叶尖，吞入口中。很快，她垂下了眼睛，开始喃喃自语。）",
          DialogueId = 80200128,
          FacialId = {
            [1] = "790053:Pain01"
          },
          FinalCamera = "-88.784508,117.885399,13.398438,0.000292,3.395786,-42.959278,25.000006,193.602356,false,Manual,1.963203",
          GUID = "C8C5C980",
          NextDialogue = 80200129,
          Subtitle = "(Fushu plucks the tip of the grass and places it on her tongue. Before long, her gaze dips low — and she begins to murmur softly beneath her breath.)",
          TalkActionId = {
            [1] = "790053:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C980"
        },
        [80200129] = {
          Content = "唔……",
          DialogueId = 80200129,
          GUID = "C8C5C9AA",
          NextDialogue = 80200130,
          SpeakNpcId = 790053,
          Subtitle = "Mmh...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C9AA"
        },
        [80200130] = {
          Content = "为什么……放弃……",
          DialogueId = 80200130,
          GUID = "C8C5C9D4",
          NextDialogue = 80200131,
          SpeakNpcId = 790053,
          Subtitle = "Why... forsake...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C9D4"
        },
        [80200131] = {
          Content = "自己……你……枯荣之术……",
          DialogueId = 80200131,
          GUID = "C8C5C9FE",
          NextDialogue = 80200132,
          SpeakNpcId = 790053,
          Subtitle = "You... the Art of Ephemerality...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C9FE"
        },
        [80200132] = {
          Camera = "113.499001,-31.578545,43.0,0.000285,-6.404784,175.03244,25.000006,68.417297,false,Manual,5.395136",
          Content = "……扶疏？扶疏？你还知道自己是谁吗？",
          DialogueId = 80200132,
          FinalCamera = "112.918457,-38.210022,43.0,0.000285,-6.404784,175.03244,25.000006,68.417297,false,Manual,5.395136",
          GUID = "C8C5CA28",
          NextDialogue = 80200133,
          Scripts = [[
SEQ{
MoveTo{ActorId{790008},TargetPoint{"BP_Stage_200201a nvzhu02"},MoveSpeed{95},Visibility{"Show"}},
TurnTo{TurnToDescription{"790008:n(790053)"}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "...Fushu? Fushu!? Do you still know who you are?",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CA28"
        },
        [80200133] = {
          Camera = "81.298691,-86.003426,-26.211426,0.000293,34.992874,120.430283,25.000006,94.024963,false,Manual,6.516896",
          Content = "自然知道，我乃祝由扶疏。",
          DialogueId = 80200133,
          FinalCamera = "90.446938,-101.709572,-38.469238,0.000291,33.992943,120.230286,25.000006,109.357407,false,Manual,5.14559",
          GUID = "C8C5CA52",
          LookAt = {
            [1] = "790008:n(790053)"
          },
          NextDialogue = 80200134,
          SpeakNpcId = 790053,
          Subtitle = "Of course. I am Fushu, the Zhuyou therapy user.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CA52"
        },
        [80200134] = {
          Content = "身膺大风九章给予的神力，就应当救死扶伤，尽职尽责，哪怕耗尽最后一滴精血也在所不惜，我们扶氏代代如此……",
          DialogueId = 80200134,
          GUID = "C8C5CA7C",
          NextDialogue = 80200135,
          SpeakNpcId = 790053,
          Subtitle = "Endowed with divine power by the Nine Chapters of Dafeng, I must heal the sick and tend the dying — to uphold my duty without fail, even at the cost of my last breath. That is the path passed down through generations of my bloodline...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CA7C"
        },
        [80200135] = {
          Camera = "1.20282,-148.704437,-23.814941,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
          Content = "怎么只有你扶风如此特殊，上不应天命，下不惜生灵，不尽祝由义务，离经叛道……",
          DialogueId = 80200135,
          FacialId = {
            [1] = "790053:Angry01"
          },
          FinalCamera = "-1.691193,-164.853149,-30.109375,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
          GUID = "C8C5CAA6",
          LookAt = {
            [1] = "790053:n(790008)"
          },
          NextDialogue = 80200136,
          SpeakNpcId = 790053,
          Subtitle = "So why do you, Fufeng... defy that path without shame? You spurn Heaven's order above, disregard life below... abandon your healer's oath, and stray from our family's creed...",
          TalkActionId = {
            [1] = "790008:Explain02_Start",
            [2] = "790053:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CAA6"
        },
        [80200136] = {
          Content = "等等！我不是你姐姐——",
          DialogueId = 80200136,
          GUID = "C8C5CAD0",
          NextDialogue = 80200137,
          SpeakNpcId = 790008,
          Subtitle = "Hold on! I'm not your sis—",
          TalkActionId = {
            [1] = "790008:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CAD0"
        },
        [80200137] = {
          Camera = "236.822632,-103.189087,84.118164,0.000283,-14.803396,162.835953,35.0,231.354126,false,Manual,6.101897",
          Content = "做出这等事来，你自然不再是我姐姐——",
          DialogueId = 80200137,
          FinalCamera = "311.739746,-126.329514,104.841797,0.000284,-14.803334,162.835846,35.0,319.934235,false,Manual,6.101897",
          GUID = "C8C5CAFA",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextOptions = {
            [1] = 802001371,
            [2] = 802001372,
            [3] = 802001373
          },
          SpeakNpcId = 790053,
          Subtitle = "After what you did... could you still call yourself my sister?",
          TalkActionId = {
            [1] = "790053:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CAFA"
        },
        [80200139] = {
          Content = "我怎会信你那天马行空的理论……但{nickname}，好熟悉的名字，这是……",
          DialogueId = 80200139,
          GUID = "C8C5CB4E",
          NextDialogue = 80200144,
          SpeakNpcId = 790053,
          Subtitle = "What sort of ridiculous tale is that supposed to be...? Although... ... that name... it does feel... familiar...",
          TalkActionId = {
            [1] = "790053:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CB4E"
        },
        [80200141] = {
          Content = "……你竟幡然悔悟了？这……有些突然，我还没做好要原谅你的准备……",
          DialogueId = 80200141,
          GUID = "C8C5CBA2",
          NextDialogue = 80200144,
          SpeakNpcId = 790053,
          Subtitle = "You... truly regret it? This is... unexpected. I... I wasn't ready to forgive you...",
          TalkActionId = {
            [1] = "790053:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CBA2"
        },
        [80200143] = {
          Content = "母亲……？母亲为何在此？您不是早已……对不起，一定是小疏让您失望，您才会前来面责……",
          DialogueId = 80200143,
          GUID = "C8C5CBF6",
          NextDialogue = 80200144,
          SpeakNpcId = 790053,
          Subtitle = "Mother...? But... you passed long ago... I must have failed so deeply that you've come to chastise me yourself...",
          TalkActionId = {
            [1] = "790053:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CBF6"
        },
        [80200144] = {
          Camera = "316.662354,-321.98291,-17.210449,0.000328,1.794318,137.019302,25.000006,416.265686,false,Manual,3.949137",
          Content = "我这是……不对、不对……我已不是百年前的扶疏……",
          DialogueId = 80200144,
          FacialId = {
            [1] = "790053:Sad03"
          },
          FinalCamera = "348.058899,-351.249207,-18.554199,0.000328,1.794318,137.019318,25.000006,416.265686,false,Manual,3.949137",
          GUID = "C8C5CC20",
          NextDialogue = 80200145,
          SpeakNpcId = 790053,
          Subtitle = "No... no, this isn't right... I'm not the Fushu of a century past.",
          TalkActionId = {
            [1] = "790053:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC20"
        },
        [80200145] = {
          Content = "姐姐也早已……",
          DialogueId = 80200145,
          GUID = "C8C5CC4A",
          NextDialogue = 80200146,
          SpeakNpcId = 790053,
          Subtitle = "And my sister... she's long gone too...",
          TalkActionId = {
            [1] = "790053:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC4A"
        },
        [80200146] = {
          Camera = "202.944183,-80.828308,97.52002,0.000333,-20.805847,168.223129,25.000006,235.269485,false,Manual,3.949137",
          Content = "……我要一个人静静，你……不要跟来。",
          DialogueId = 80200146,
          FinalCamera = "205.474915,-68.67897,97.52002,0.000333,-20.805847,168.223129,25.000006,235.269485,false,Manual,3.949137",
          GUID = "C8C5CC74",
          NextDialogue = 80200147,
          Scripts = "MoveTo{_delay{2},ActorId{790053},TargetPoint{\"BP_Stage_200201a fushu02\"},MoveSpeed{65},Visibility{\"Show\"}}",
          SpeakNpcId = 790053,
          Subtitle = "...Please. Leave me be. I need a moment alone.",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "790053:p(-170)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC74"
        },
        [80200147] = {
          Content = "一炷香后，扶疏回到了你们分开的的地方。",
          DialogueId = 80200147,
          GUID = "C8C5CC9E",
          IsBlack = 1,
          Subtitle = "An incense's time later, Fushu returns to where you parted.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC9E"
        },
        [80200148] = {
          Camera = "514.843018,-282.773102,136.926758,0.000068,-3.999574,142.810944,30.000008,609.051941,false,Manual,2.015938",
          Content = "好点了吗？",
          DialogueId = 80200148,
          FacialId = {
            [1] = "790008:None",
            [2] = "790053:Sad01"
          },
          FinalCamera = "432.307831,-370.087555,136.926758,0.000073,-3.199554,131.41127,30.000008,609.051941,false,Manual,2.015938",
          GUID = "C8C5CCC8",
          NextDialogue = 80200149,
          Scripts = "PlayAnimation{_delay{1},ActorId{790008},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Feeling better?",
          TalkActionId = {
            [1] = "790008:Explain01_Start",
            [2] = "790053:Sigh_Loop"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CCC8"
        },
        [80200149] = {
          Content = "嗯，没事了。抱歉……我失态了。",
          DialogueId = 80200149,
          GUID = "C8C5CCF2",
          NextDialogue = 80200150,
          Scripts = "PlayAnimation{_delay{2},ActorId{790053},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Mm. I'm all right now. Forgive me... I lost my composure.",
          TalkActionId = {
            [1] = "790053:Disagree",
            [2] = "790053:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CCF2"
        },
        [80200150] = {
          Content = "没吓到你吧？",
          DialogueId = 80200150,
          GUID = "C8C5CD1C",
          NextOptions = {
            [1] = 802001501,
            [2] = 802001502
          },
          SpeakNpcId = 790053,
          Subtitle = "Did I startle you?",
          TalkActionId = {
            [1] = "790053:Explain02_End",
            [2] = "790008:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CD1C"
        },
        [80200153] = {
          Camera = "158.343323,112.661469,131.67627,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          Content = "你不在意就好。",
          DialogueId = 80200153,
          FacialId = {
            [1] = "790053:Sad02"
          },
          FinalCamera = "148.15004,110.905052,132.002441,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          GUID = "C8C5CD9A",
          NextDialogue = 80200154,
          SpeakNpcId = 790053,
          Subtitle = "Then I'm relieved.",
          TalkActionId = {
            [1] = "790008:Confident_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CD9A"
        },
        [80200154] = {
          Content = "……我方才看到了百多年前和姐姐吵架的场景，我以为我已经放下，没想到……",
          DialogueId = 80200154,
          FacialId = {
            [1] = "790053:Sad02"
          },
          GUID = "C8C5CDC4",
          NextDialogue = 80200155,
          Scripts = [[
PARA{
TurnTo{_delay{2},TurnToDescription{"790053:p(170)"}},
PlayAnimation{_delay{4.5},ActorId{790053},AnimationId{"Sad02_Start"},Duration{1}},
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"-515.03064,-883.369263,360.678711,0.000062,-15.199882,63.794632,30.000008,125.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-551.471924,-865.434082,360.678711,0.000064,-15.199888,63.79414,30.000008,125.0,false,DoNotOverride,2.8"},duration{15}}
}
}]],
          SpeakNpcId = 790053,
          Subtitle = "In that vision, I glimpsed an argument with my sister — a memory more than a century old. I thought I'd long made peace with it... but perhaps not entirely.",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CDC4"
        },
        [80200155] = {
          Camera = "-64.305794,-38.344486,108.832031,1.0,4.399236,53.000343,40.0,213.353607,false,Manual,8.188937",
          Content = "不过，倒有意外收获，在幻觉中我依稀听得……音容草本身也是一味难得的香料，作用绝非只是致幻而已。",
          DialogueId = 80200155,
          FinalCamera = "-73.563438,-50.619896,107.648438,0.999998,4.399222,53.000751,40.0,213.353607,false,Manual,8.188937",
          GUID = "C8C5CDEE",
          NextDialogue = 80200156,
          Scripts = "TurnTo{_delay{2},TurnToDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Still... there was something unexpected. It seemed to hint that Echowort is more than a simple hallucinogen — it's also a rare culinary herb.",
          TalkActionId = {
            [1] = "790053:Sad02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CDEE"
        },
        [80200156] = {
          Camera = "158.343323,112.661469,131.67627,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          Content = "它能录下生长期间的“见闻”，若是被人食用，说不定可以看到此地过去的往事……",
          DialogueId = 80200156,
          FacialId = {
            [1] = "790053:Confident01"
          },
          FinalCamera = "148.15004,110.905052,132.002441,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          GUID = "C8C5CE18",
          NextDialogue = 80200157,
          Scripts = "PlayAnimation{_delay{4},ActorId{790053},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Some say it absorbs the memories of the places it grows. Those who consume it may glimpse echoes of the past — stories rooted in the soil beneath it.",
          TalkActionId = {
            [1] = "790053:Think_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE18"
        },
        [80200157] = {
          Content = "我在如今版本的《草木精要》中从未见过这样的记录，或许是抄写遗漏，倒是可以补录。",
          DialogueId = 80200157,
          GUID = "C8C5CE42",
          NextDialogue = 80200158,
          Scripts = "PlayAnimation{_delay{4},ActorId{790053},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "This isn't noted in the current edition of Essentials of Medicinal Herbs... likely a scribal omission. I should make a record — and see it restored.",
          TalkActionId = {
            [1] = "790053:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE42"
        },
        [80200158] = {
          Camera = "-64.305794,-38.344486,108.832031,1.0,4.399236,53.000343,40.0,213.353607,false,Manual,8.188937",
          Content = "走吧，这附近或许能找到我们要的怀梦草。",
          DialogueId = 80200158,
          FacialId = {
            [1] = "790008:Beg"
          },
          FinalCamera = "-73.563438,-50.619896,107.648438,0.999998,4.399222,53.000751,40.0,213.353607,false,Manual,8.188937",
          GUID = "C8C5CE6C",
          NextDialogue = 80200159,
          SpeakNpcId = 790053,
          Subtitle = "Come. We may still find Oneirowort nearby.",
          TalkActionId = {
            [1] = "790053:Confident_Start",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE6C"
        },
        [80200159] = {
          Content = "要不算了吧？",
          DialogueId = 80200159,
          GUID = "C8C5CE96",
          NextDialogue = 80200160,
          SpeakNpcId = 790008,
          Subtitle = "I don't know... that looked like a serious case of food poisoning.",
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE96"
        },
        [80200160] = {
          Camera = "83.435791,64.057053,136.885742,0.000068,1.999476,179.598953,40.0,108.610825,false,Manual,7.645144",
          Content = "半途作废可不是扶氏作风。没关系，我身体无恙，你若有兴趣，我可为你表演一套五禽戏，你若能学会，对身体很有好处……",
          DialogueId = 80200160,
          GUID = "C8C5CEC0",
          NextDialogue = 80200161,
          SpeakNpcId = 790053,
          Subtitle = "It's not my nature to leave things half-done. Truly — I'm quite well. If you're curious, I could even demonstrate the full Five-Animal Frolics sequence. It's excellent for circulation... assuming you can keep up.",
          TalkActionId = {
            [1] = "790008:Talk02_End",
            [2] = "790053:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CEC0"
        },
        [80200161] = {
          Camera = "134.218704,-27.63744,135.273926,0.000073,-1.000513,111.398094,40.000011,154.959457,false,Manual,10.744748",
          Content = "呃……不如等我们找到怀梦草，你再教给我吧？",
          DialogueId = 80200161,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8C5CEEA",
          NextDialogue = 80200162,
          SpeakNpcId = 790008,
          Subtitle = "Uhh... maybe teach me after we find the Oneirowort?",
          TalkActionId = {
            [1] = "790008:Deny01"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CEEA"
        },
        [80200162] = {
          Camera = "476.449219,-253.639587,133.560059,0.000068,-3.999574,142.810989,30.000008,609.051941,false,Manual,2.015938",
          Content = "呵，一言为定。",
          DialogueId = 80200162,
          FinalCamera = "514.843018,-282.773102,136.926758,0.000068,-3.999574,142.810989,30.000008,609.051941,false,Manual,2.015938",
          GUID = "C8C5CF14",
          SpeakNpcId = 790053,
          Subtitle = "Heh. It's a promise.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CF14"
        },
        [80200201] = {
          Camera = "296.831238,2487.655029,978.387207,0.000159,-0.599212,-85.411514,35.0,111.63089,false,DoNotOverride,20.07291",
          Content = "找到了。",
          DialogueId = 80200201,
          FinalCamera = "296.831238,2487.655029,978.387207,0.00016,-19.599077,-96.010071,35.0,111.63089,false,DoNotOverride,20.07291",
          GUID = "C8C5CF3E",
          NextDialogue = 80200202,
          SpeakNpcId = 790053,
          Subtitle = "Here's one.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CF3E"
        },
        [80200202] = {
          Content = "那么我先尝尝，你若怕我再冲撞到你，可以先退得远些，几分钟后再来查看我的情况。",
          DialogueId = 80200202,
          GUID = "C8C5CF68",
          LookAt = {
            [1] = "790053:n(790008)"
          },
          NextDialogue = 80200203,
          SpeakNpcId = 790053,
          Subtitle = "I'll try it. Should the effects prove unpleasant, you may step aside and return once they pass.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CF68"
        },
        [80200203] = {
          Camera = "89.105469,150.867188,132.969238,0.000064,-0.998505,-137.796677,30.000002,198.114532,false,Manual,4.214613",
          Content = "等等！",
          DialogueId = 80200203,
          GUID = "C8C5CF92",
          NextDialogue = 80200204,
          SpeakNpcId = 790008,
          Subtitle = "Wait!",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CF92"
        },
        [80200204] = {
          Camera = "-37.011719,125.353516,135.46582,0.000068,-2.597596,-30.799438,30.000008,198.114532,false,DoNotOverride,4.214613",
          Content = "要不，我们还是换一换，由我来尝试吧？",
          DialogueId = 80200204,
          GUID = "C8C5CFBC",
          NextDialogue = 80200205,
          SpeakNpcId = 790008,
          Subtitle = "How about we switch — let me try it this time?",
          TalkActionId = {
            [1] = "790008:Explain02_End",
            [2] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CFBC"
        },
        [80200205] = {
          Camera = "89.105469,150.867188,132.969238,0.000064,-0.998505,-137.796631,30.000002,198.114532,false,Manual,4.214613",
          Content = "可我不想让你平白难受，这不是我救治你的初衷。",
          DialogueId = 80200205,
          GUID = "C8C5CFE6",
          NextDialogue = 80200206,
          SpeakNpcId = 790053,
          Subtitle = "I cannot allow you to bear this in my stead. When I offered to treat you, I never intended to subject you to harm — however slight.",
          TalkActionId = {
            [1] = "790053:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CFE6"
        },
        [80200206] = {
          Camera = "-37.011719,125.353516,135.46582,0.000068,-2.597596,-30.799438,30.000008,198.114532,false,DoNotOverride,4.214613",
          Content = "正因为你是医者，所以才更应该由我试药。",
          DialogueId = 80200206,
          GUID = "C8C5D010",
          NextDialogue = 80200207,
          SpeakNpcId = 790008,
          Subtitle = "Exactly — you're the doctor here. So it should be me.",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D010"
        },
        [80200207] = {
          Content = "如果出了纰漏，我相信扶疏一定能救我，但如果扶疏倒下了，不通医药，也不会枯荣之术的我，不就只能看着了？",
          DialogueId = 80200207,
          FacialId = {
            [1] = "790008:Nervous"
          },
          GUID = "C8C5D03A",
          NextDialogue = 80200208,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.1},ActorId{790008},AnimationId{"Explain02_Start"},Duration{1}},
PlayAnimation{_delay{7.1},ActorId{790008},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "If something goes wrong, I know you'll be able to save me. But if you collapse... I wouldn't know where to begin. I'd be helpless.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D03A"
        },
        [80200208] = {
          Camera = "-75.154465,1007.605713,531.828613,0.000125,-25.599077,-85.208382,35.0,1081.229736,false,DoNotOverride,6.835649",
          Content = "这……恕我不能同意，没想到这点是我思虑不周，不如我们还是另找方法——",
          DialogueId = 80200208,
          FinalCamera = "-85.453995,1130.481567,590.911621,0.000125,-25.599077,-85.208382,35.0,1081.229736,false,DoNotOverride,6.835649",
          GUID = "C8C5D064",
          LookAt = {
            [1] = "790053:n(790053)",
            [2] = "790008:n(790053)"
          },
          NextDialogue = 80200209,
          Scripts = [[
LookAt{_delay{6.01},LookAtDescription{"790053:n(790008)"}}



]],
          SpeakNpcId = 790053,
          Subtitle = "I... I can't agree to that. But I see your reasoning — I didn't consider it carefully enough. Perhaps we should find ano—",
          TalkActionId = {
            [1] = "790053:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790053:p(75)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D064"
        },
        [80200209] = {
          Content = "（没等扶疏说完，你就撕下了指甲大小的叶片塞进了嘴里。）",
          DialogueId = 80200209,
          Duration = 2,
          GUID = "C8C5D08E",
          NextDialogue = 80200210,
          Scripts = "PlayAnimation{_delay{1.9},ActorId{790008},AnimationId{\"Laugh01_Start\"},Duration{1}}",
          Subtitle = "(Before she can finish, you pinch off a sliver of the herb's blade and place it on your tongue.)",
          TurnTo = {
            [1] = "790008:n(790053)",
            [2] = "790053:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D08E"
        },
        [80200210] = {
          Camera = "-26.813253,90.971672,125.448242,0.000143,18.400255,-128.598114,45.0,69.91674,false,Manual,9.337125",
          Content = "啊！",
          DialogueId = 80200210,
          FacialId = {
            [1] = "790053:Shock02"
          },
          GUID = "C8C5D0B8",
          NextDialogue = 80200211,
          SpeakNpcId = 790053,
          Subtitle = "Ah—!",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D0B8"
        },
        [80200211] = {
          Content = "你怎么……等等不是说这个的时候……",
          DialogueId = 80200211,
          GUID = "C8C5D0E2",
          NextDialogue = 80200212,
          Scripts = "MoveTo{_delay{2.01},ActorId{790053},TargetPoint{\"BP_200301a_fushu01\"},MoveSpeed{100},Visibility{\"Show\"}}\n",
          SpeakNpcId = 790053,
          Subtitle = "What are you—!? No... this isn't the time to—",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D0E2"
        },
        [80200212] = {
          Camera = "-3.932695,151.455307,158.64209,0.000183,-14.39743,-63.200489,35.0,81.946014,false,Manual,9.956834",
          Content = "你感觉如何？",
          DialogueId = 80200212,
          FacialId = {
            [1] = "790008:Uninterested01"
          },
          GUID = "C8C5D10C",
          NextDialogue = 80200213,
          SpeakNpcId = 790053,
          Subtitle = "How do you feel!?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D10C"
        },
        [80200213] = {
          Content = "嗯……还不错，味道像薄荷，吃着很清乐依昂——",
          DialogueId = 80200213,
          GUID = "C8C5D136",
          NextDialogue = 80200214,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"43.367142,98.584366,137.931641,0.000168,18.599136,163.187195,35.000008,111.63089,false,Manual,20.07291"},duration{0}},
CameraMoveTo{TargetPosition{"43.367142,98.584366,137.931641,0.00015,46.798969,165.587006,35.000008,111.63089,false,Manual,20.07291"},Blend{"easeInOutQuad"},duration{3}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "Mmm... not bad. Kinda minty. It's got this clean, cooool...",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D136"
        },
        [80200214] = {
          Content = "（扶疏的脸逐渐模糊，你确认了一件事：你不属于音容草耐受人群。）",
          DialogueId = 80200214,
          GUID = "C8C5D160",
          IsBlack = 1,
          Subtitle = "(Her face begins to blur before your eyes. One thing becomes clear: you are not naturally tolerant to Echowort.)",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D160"
        },
        [80200215] = {
          Content = "进入幻境，主角在枯荣阁中刷出，NPC扶风刷出，背对主角。",
          DialogueId = 80200215,
          GUID = "C8C5D18A",
          Subtitle = "Enter an illusory realm. The protagonist is transported to the Hall of Ephemerality. An NPC (Fufeng) stands with her back turned.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D18A"
        },
        [80200216] = {
          Camera = "-166.21434,-364.135559,166.314453,5.0,-28.801657,28.80596,30.000008,107.243362,false,Manual,2.8",
          Content = "头、头好晕……这里是枯荣阁？",
          DialogueId = 80200216,
          FinalCamera = "-193.228027,-378.986328,183.258789,5.000042,-29.001637,30.205877,30.000008,107.243362,false,Manual,2.8",
          GUID = "C8C5D1B4",
          NextDialogue = 80200217,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{3.01},TargetPosition{"-100.220222,-4.642982,23.701172,-8.017351,11.596875,-97.81694,25.0,107.243362,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-100.220222,-4.642982,23.701172,-8.018849,14.59651,-92.416206,25.000002,107.243362,false,DoNotOverride,2.8"},duration{8}}
},
PlayAnimation{_delay{4.01},ActorId{790008},AnimationId{"Story_Headache_End"},Duration{1}},
TurnTo{_delay{6.01},TurnToDescription{"790008:p(-140)"}},
LookAt{_delay{7.01},LookAtDescription{"790008:p(BP_200301_nvzhu01)"}}
}
]],
          SpeakNpcId = 790008,
          Subtitle = "Ugh... my head... This place — is this the Hall of Ephemerality?",
          TalkActionId = {
            [1] = "790008:Story_Headache_Loop"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D1B4"
        },
        [80200217] = {
          Content = "那是……扶疏？",
          DialogueId = 80200217,
          FacialId = {
            [1] = "790008:Shock01"
          },
          GUID = "C8C5D1DE",
          LookAt = {
            [1] = "790008:n(790054)"
          },
          NextDialogue = 80200218,
          Scripts = "PlayAnimation{_delay{1.01},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "And is that... Fushu?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D1DE"
        },
        [80200218] = {
          Camera = "-84.304626,35.644173,65.415039,0.000002,2.396269,78.78582,35.0,107.243362,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "麻烦。麻烦。麻烦。麻烦！",
          DialogueId = 80200218,
          FacialId = {
            [1] = "790054:Angry01"
          },
          FinalCamera = "-66.061569,127.614021,68.84082,0.000002,1.396248,78.785858,35.0,107.243362,false,DoNotOverride,2.8",
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ugh... what a nuisance. Truly, what a wretched nuisance!",
          TalkActionId = {
            [1] = "790054:Angry01_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D208"
        },
        [80200219] = {
          Content = "唉，早上起来的时候，还再三告诫自己别去惹她别去惹她，怎么早饭还没吃完，就破戒了！",
          DialogueId = 80200219,
          GUID = "C8C5D232",
          NextDialogue = 80200220,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Sigh_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Sigh_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Told myself again and again this morning — don't snap, don't prod her. And yet what happened? Didn't even get through our breakfast before I provoked that stubborn mule again!",
          TalkActionId = {
            [1] = "790054:Angry01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D232"
        },
        [80200220] = {
          Camera = "-2343.795166,1023.041992,114.227539,0.000092,-0.803982,-4.996912,35.0,2401.962891,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "扶风啊扶风！你怎能如此沉不住气呢！那小妮子脾气再臭，也是你亲妹子！你又不可能扔下她不管，干嘛总是气她呢！",
          DialogueId = 80200220,
          FinalCamera = "-2335.671875,1115.896973,114.227539,0.000092,-0.803982,-4.997154,35.0,2401.962891,false,Manual,2.8",
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          Scripts = [[
PARA{
TurnTo{_delay{1.01},TurnToDescription{"790054:p(90))"}},
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Fufeng, honestly... must you always rise to it? Prickly as she is, she's still your little sister. It's not as though you can simply turn your back on her. So why keep needling her?",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D25C"
        },
        [80200221] = {
          Camera = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
          Content = "没办法啊没办法，扶疏那一本正经的样子，实在是很好气……笑容没有消失，只是从扶疏妹妹的脸上，移到了我的脸上……",
          DialogueId = 80200221,
          FacialId = {
            [1] = "790054:Sad01"
          },
          GUID = "C8C5D286",
          NextDialogue = 80200222,
          Scripts = [[
PARA{
SetLocation{ActorId{790008},TargetPoint{"BP_200301b_fushu01"},Visibility{"Show"}},
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Angry01_End"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{8.01},ActorId{790054},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "But I can't help it! That solemn little face — it's infuriating. And now, the smile's gone from her lips... and somehow ended up on mine.",
          TalkActionId = {
            [1] = "790054:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D286"
        },
        [80200222] = {
          Camera = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
          CameraBlendCurve = "easeInOutQuad",
          Content = "人之常情，人之常情嘛！",
          DialogueId = 80200222,
          FinalCamera = "108.321411,1110.508301,147.339844,0.000063,-8.613893,-93.255981,40.0,218.69223,false,Manual,11.861392",
          GUID = "C8C5D2B0",
          NextDialogue = 80200223,
          Scripts = "MoveTo{ActorId{790008},TargetPoint{\"BP_200301b_nvzhu01\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 790054,
          Subtitle = "Human nature, isn't it? Just plain human nature...",
          TalkActionId = {
            [1] = "790054:Think_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D2B0"
        },
        [80200223] = {
          Content = "扶、扶疏？是你吗？",
          DialogueId = 80200223,
          Duration = 1,
          GUID = "C8C5D2DA",
          LookAt = {
            [1] = "790008:n(790054)",
            [2] = "790054:n(790008)"
          },
          NextDialogue = 80200224,
          SpeakNpcId = 790008,
          Subtitle = "F—Fushu? Is that you?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D2DA"
        },
        [80200224] = {
          Camera = "-5.917664,812.056946,114.511719,0.000043,2.986077,54.542389,35.000015,234.030762,false,Manual,3.823875",
          CameraBlendCurve = "easeInOutQuad",
          Content = "不是哦。我是扶疏的双胞胎姐姐，扶风。将我俩弄混的人，你不是第一个。",
          DialogueId = 80200224,
          FacialId = {
            [1] = "790008:None",
            [2] = "790054:None"
          },
          FinalCamera = "-19.185059,822.114929,114.511719,0.000044,2.786068,50.5424,35.000015,234.030762,false,Manual,3.823875",
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Ah — I'm afraid not. I'm Fufeng, her twin sister. You wouldn't be the first to mix us up.",
          TalkActionId = {
            [1] = "790054:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D304"
        },
        [80200225] = {
          Content = "你找扶疏？怪了，她素来不和人来往，是个小闷葫芦，原来也有熟人？",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "You're looking for Fushu? How curious. She's not one to mingle — closed up like a little clamshell, that one. Didn't think she had anyone she'd call a friend.",
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D32E"
        },
        [80200226] = {
          Content = "哇……你这个年纪的人，竟不觉得她闷，还这样夸奖她，不错不错，扶疏的朋友，就是我扶风的朋友！",
          DialogueId = 80200226,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Huh... Someone your age, speaking so earnestly of her quiet ways? That's rare. Well, if you're a friend of hers, then you have a friend in me.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D382"
        },
        [80200227] = {
          Content = "讹钱讹到我枯荣阁来了？！你去这十里八乡问问，这小闷葫芦的肚子里连点铜钱响都听不到，你要诬赖人，好歹也诬赖给我吧！",
          DialogueId = 80200227,
          FacialId = {
            [1] = "790054:Angry01"
          },
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{_delay{8.01},ActorId{790054},AnimationId{"Angry01_End"},Duration{1}},
PlayAnimation{_delay{8.5},ActorId{790054},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{10},ActorId{790054},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "What, here to swindle my little sister now? Please — shake her upside down and not a single coin would fall. If you're going to lie, at least pick a more plausible mark.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D3D6"
        },
        [80200228] = {
          Content = "噫，油嘴滑舌，要是没病没痛就回家自己玩儿吧，乖。",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          Scripts = "PlayAnimation{_delay{4.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "Ugh, smooth talker. If you're neither sick or wounded, best run along and try your luck elsewhere.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D42A"
        },
        [80200229] = {
          Camera = "-30.235046,1285.589722,155.125977,0.000064,-7.212188,-68.241211,35.000019,393.319,false,Manual,3.482719",
          CameraBlendCurve = "easeInOutQuad",
          Content = "所以，你造访枯荣阁所为何事？",
          DialogueId = 80200229,
          FacialId = {
            [1] = "790054:None"
          },
          FinalCamera = "31.76886,1303.230225,155.125977,0.00006,-7.012207,-79.441032,35.000019,393.319,false,Manual,3.482719",
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054,
          Subtitle = "So... what brings you to the Hall of Ephemerality?",
          TalkActionId = {
            [1] = "790054:Confident_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D454"
        },
        [80200230] = {
          Content = "我误食了音容草，头脑发昏，还看见奇奇怪怪的东西，我想扶疏一定能治，就寻医问药来了。",
          DialogueId = 80200230,
          FacialId = {
            [1] = "790008:Sad03"
          },
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          Scripts = "PlayAnimation{_delay{7.01},ActorId{790008},AnimationId{\"Explain02_End\"},Duration{1}}\n",
          SpeakNpcId = 790008,
          Subtitle = "I accidentally ate some Echowort. My head's spinning and I'm seeing strange things. I thought Fushu might know what to do, so I came looking for her.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D47E"
        },
        [80200231] = {
          Camera = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
          Content = "你来得不巧，扶疏正生着闷气呢，还是别在这时候打扰她了。不过我是一名医师，让我看病也是一样的。",
          DialogueId = 80200231,
          FinalCamera = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{"Think_End"},Duration{1}},
TurnTo{_delay{5.8},TurnToDescription{"790054:n(790008)"}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Unlucky timing — she's sulking right now. Best not to poke the beehive. But I'm a physician too, you know. I could help.",
          TalkActionId = {
            [1] = "790054:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4A8"
        },
        [80200232] = {
          Camera = "-253.072449,961.222961,89.996094,0.000045,3.386319,-1.453428,35.000015,323.748901,false,Manual,3.482719",
          Content = "让我仔细看看……",
          DialogueId = 80200232,
          FinalCamera = "-253.819214,931.512756,89.996094,0.000045,3.186317,-1.253389,35.000015,323.748901,false,Manual,3.482719",
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          Scripts = "MoveTo{ActorId{790054},TargetPoint{\"BP_200301b_fushu03\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 790054,
          Subtitle = "Let me have a look...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4D2"
        },
        [80200233] = {
          Content = "嗯……步履还算稳健，双目也有焦点，口齿利索，舌头不打架，误食的量应该不大。大约是半片左右？",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Hmm... your footing's steady, eyes still sharp, speech coherent — I'd wager it was a small dose. Half a blade, perhaps?",
          TalkActionId = {
            [1] = "790054:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4FC"
        },
        [80200234] = {
          Content = "你症状不重，没等解药熬完，就全好了。再耐心等等吧，很快就会清醒的，别怕。",
          DialogueId = 80200234,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D526",
          NextDialogue = 80200235,
          Scripts = "PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "Nothing serious. You'll feel fine before the antidote even finishes steeping. Just sit tight — it'll pass.",
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D526"
        },
        [80200235] = {
          Camera = "24.030762,840.372314,98.698242,0.000059,12.985261,58.542137,35.000023,135.488754,false,Manual,8.071544",
          CameraBlendCurve = "easeInOutQuad",
          Content = "要是实在难受，我随身带了些橘枳丸，你嚼两个，会好些。",
          DialogueId = 80200235,
          FinalCamera = "14.792786,846.531738,98.698242,0.000066,12.985261,54.742638,35.000023,135.488754,false,Manual,8.071544",
          GUID = "C8C5D550",
          NextDialogue = 80200236,
          SpeakNpcId = 790054,
          Subtitle = "If it grows unbearable, I've some tangerine tonic on hand. Chew a few — they ought to ease the discomfort.",
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790054:p(-30)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D550"
        },
        [80200236] = {
          Content = "我猜，你还有少眠多梦的毛病，于是你想去找怀梦草医治，但却不小心误食了极其类似的音容草。",
          DialogueId = 80200236,
          FacialId = {
            [1] = "790054:Angry01"
          },
          GUID = "C8C5D57A",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200237,
          SpeakNpcId = 790054,
          Subtitle = "Let me guess — trouble sleeping? Too many dreams? Went hunting Oneirowort and picked Echowort instead?",
          TalkActionId = {
            [1] = "790054:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D57A"
        },
        [80200237] = {
          Content = "不过想治这个毛病，还是匍地枝与隙中花一同煎来服下更合适，怀梦草虽能助眠，但会在梦中看到难以忘怀之事，徒惹伤怀。",
          DialogueId = 80200237,
          GUID = "C8C5D5A4",
          LookAt = {
            [1] = "790054:n(790008)"
          },
          NextDialogue = 80200238,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{10.01},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "If it's true relief you seek, you'd do better with a decoction of Creeping Tendrils and Crackblooms. Oneirowort may lull you to sleep, yes — but the memories it stirs will cling to your dreams, and weigh upon the heart.",
          TalkActionId = {
            [1] = "790054:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D5A4"
        },
        [80200238] = {
          Camera = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
          Content = "……不提外貌，你和扶疏确实相像。",
          DialogueId = 80200238,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C8C5D5CE",
          NextDialogue = 80200239,
          SpeakNpcId = 790008,
          Subtitle = "...Looks aside, you and Fushu really are quite alike.",
          TalkActionId = {
            [1] = "790008:Laugh01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D5CE"
        },
        [80200239] = {
          Camera = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
          Content = "这话倒是鲜少听到，我和扶疏虽是双生胎，但都说我性格跳脱，颇有“离经叛道”的嫌疑，与大风九章第九条很不相宜。",
          DialogueId = 80200239,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D5F8",
          NextDialogue = 80200240,
          SpeakNpcId = 790054,
          Subtitle = "Now that's a rare remark. We may be twins, but I've always been the unruly one — ever toeing the line of Dafeng's Ninth Admonition.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D5F8"
        },
        [80200240] = {
          Camera = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
          Content = "扶疏瞧着冷淡疏离，你瞧着风风火火，但只要涉及问诊的时候，那份一本正经，温和耐心简直如出一辙。",
          DialogueId = 80200240,
          FacialId = {
            [1] = "790008:Shy"
          },
          GUID = "C8C5D622",
          NextDialogue = 80200241,
          SpeakNpcId = 790008,
          Subtitle = "Fushu may seem cold and distant, and you blaze like fire — but when you're tending the sick, you're the same. Meticulous, gentle... utterly sincere.",
          TalkActionId = {
            [1] = "790008:Laugh01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D622"
        },
        [80200241] = {
          Camera = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
          Content = "你这人……现在我相信你和扶疏很熟了。",
          DialogueId = 80200241,
          FacialId = {
            [1] = "790054:None"
          },
          GUID = "C8C5D64C",
          NextDialogue = 80200242,
          SpeakNpcId = 790054,
          Subtitle = "You... hah. Now I believe you're truly close to her.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D64C"
        },
        [80200242] = {
          Camera = "-225.803223,724.690369,-5.095703,0.00006,18.385708,34.549988,35.000015,390.386017,false,Manual,3.482719",
          CameraBlendCurve = "easeInOutQuad",
          Content = "那孩子性格执拗，许多话憋在心里不肯说，一张嘴也不怎么灵巧，有时明明是这个意思，说出来却离题万里。",
          DialogueId = 80200242,
          FinalCamera = "-314.394165,663.687378,-40.84668,0.000058,18.385708,34.550003,35.000015,390.386017,false,Manual,3.482719",
          GUID = "C8C5D676",
          NextDialogue = 80200243,
          SpeakNpcId = 790054,
          Subtitle = "That girl... so hopelessly stubborn. Bottles up every thought. And when she tries to speak from the heart, the words twist themselves into knots.",
          TalkActionId = {
            [1] = "790054:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D676"
        },
        [80200243] = {
          Camera = "60.795898,983.703857,142.798828,0.000097,-11.615378,-75.852562,35.000019,86.947418,false,Manual,4.75455",
          Content = "大概……只有你这样细心的人才能和她玩到一起吧！",
          DialogueId = 80200243,
          GUID = "C8C5D6A0",
          NextDialogue = 80200244,
          SpeakNpcId = 790054,
          Subtitle = "Takes someone patient and perceptive to understand her... Like you.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D6A0"
        },
        [80200244] = {
          Camera = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
          Content = "我这个做姐姐的惯爱嘴欠，先甘拜下风啦。",
          DialogueId = 80200244,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D6CA",
          NextDialogue = 80200245,
          SpeakNpcId = 790054,
          Subtitle = "I've always had the sharper tongue — no wonder I rub her the wrong way. Some big sister I turned out to be.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D6CA"
        },
        [80200245] = {
          Camera = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
          Content = "那么，扶疏的熟人！姐姐有件事情拜托，看在扶疏的面子上，你一定会答应我的吧！",
          DialogueId = 80200245,
          FinalCamera = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
          GUID = "C8C5D6F4",
          NextDialogue = 80200246,
          SpeakNpcId = 790054,
          Subtitle = "Now then, friend of Fushu — I have a small favour to ask. And I trust you won't turn me down. Not when it's for her sake.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D6F4"
        },
        [80200246] = {
          Content = "愿闻其详。",
          DialogueId = 80200246,
          GUID = "C8C5D71E",
          NextDialogue = 80200247,
          SpeakNpcId = 790008,
          Subtitle = "Sure. What is it?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D71E"
        },
        [80200247] = {
          Camera = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
          Content = "可不可以帮我找一下送给扶疏的道歉礼物？",
          DialogueId = 80200247,
          GUID = "C8C5D748",
          NextDialogue = 80200248,
          SpeakNpcId = 790054,
          Subtitle = "May I trouble you to help me prepare an apology gift?",
          TalkActionId = {
            [1] = "790008:Confident_Start",
            [2] = "790054:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D748"
        },
        [80200248] = {
          Camera = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "离这里不远的水域中，常有寿星乌贼出没，帮我钓些来，不难的吧！",
          DialogueId = 80200248,
          FinalCamera = "-248.974243,678.924866,174.214844,0.000118,0.185153,65.936897,35.000019,4716.592773,false,Manual,1.2",
          GUID = "C8C5D772",
          Scripts = "PlayAnimation{_delay{1.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "There's a stretch of water not far from here where Shouxing Squid tend to gather. Could you catch a few for me? It shouldn't prove too difficult.",
          TalkActionId = {
            [1] = "790054:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D772"
        },
        [80200301] = {
          Camera = "-979.67981,-2224.893066,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "哇……真的钓到了，好厉害。全能如我，坐在那里一天也未必能钓上来一条……",
          DialogueId = 80200301,
          Duration = 1,
          FinalCamera = "-1096.155396,-2166.05835,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
          GUID = "C8C5E5E2",
          NextDialogue = 80200302,
          Scripts = [[
PARA{
MoveTo{ActorId{790008},TargetPoint{"BP_200401a_nvzhu01"},MoveSpeed{90},Visibility{"Show"}},
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{"Explain01_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Well now... you actually caught some? Impressive. As for me — jack of all trades though I claim to be — I could sit here all day and still come up empty...",
          ToFinalCameraBlendTime = 25,
          TurnTo = {
            [1] = "790054:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E5E2"
        },
        [80200302] = {
          Camera = "0.420166,-219.716721,163.364258,0.000018,-7.399601,85.99836,45.0,289.463654,false,Manual,6.00204",
          CameraBlendCurve = "easeInOutQuad",
          Content = "并非全能。",
          DialogueId = 80200302,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-18.45842,-218.633926,160.760742,0.000016,-6.999639,81.997551,45.0,289.463654,false,Manual,6.00204",
          GUID = "C8C5E60C",
          NextDialogue = 80200303,
          SpeakNpcId = 790008,
          Subtitle = "\"All trades\" might've been a stretch.",
          TalkActionId = {
            [1] = "790008:Laugh01_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E60C"
        },
        [80200303] = {
          Content = "扶疏给我看过你的画，很抽象。",
          DialogueId = 80200303,
          Duration = 3,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8C5E636",
          LookAt = {
            [1] = "790008:n(790054)"
          },
          NextDialogue = 80200304,
          SpeakNpcId = 790008,
          Subtitle = "Fushu showed me your paintings. Very... avant-garde.",
          TalkActionId = {
            [1] = "790008:Laugh01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E636"
        },
        [80200304] = {
          Camera = "-212.935883,315.686401,125.688477,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
          Content = "……你们是不是有点太熟了，她怎么把此等家丑也告诉你？",
          DialogueId = 80200304,
          FinalCamera = "-271.671875,398.944336,125.233398,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
          GUID = "C8C5E660",
          NextDialogue = 80200305,
          Scripts = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "...She showed you those? Just how close are the two of you?",
          TalkActionId = {
            [1] = "790054:Confident_Start"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E660"
        },
        [80200305] = {
          Content = "咳……但我从来不知道扶疏喜欢寿星乌贼。",
          DialogueId = 80200305,
          GUID = "C8C5E68A",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200306,
          Scripts = "PlayAnimation{_delay{1.1},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Well... not close enough to know she had a thing for Shouxing Squid.",
          TalkActionId = {
            [1] = "790008:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E68A"
        },
        [80200306] = {
          Content = "并非喜欢。",
          DialogueId = 80200306,
          GUID = "C8C5E6B4",
          NextDialogue = 80200307,
          SpeakNpcId = 790054,
          Subtitle = "Not quite.",
          TalkActionId = {
            [1] = "790008:Explain01L_End"
          },
          TurnTo = {
            [1] = "790054:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E6B4"
        },
        [80200307] = {
          Content = "扶疏最讨厌寿星乌贼，小时候被吓哭过呢！",
          DialogueId = 80200307,
          FacialId = {
            [1] = "790054:Smile02"
          },
          GUID = "C8C5E6DE",
          LookAt = {
            [1] = "790054:n(790008)"
          },
          NextOptions = {
            [1] = 802003071,
            [2] = 802003072,
            [3] = 802003073
          },
          SpeakNpcId = 790054,
          Subtitle = "She loathes them. When we were little, just seeing one would have her bawling her eyes out.",
          TalkActionId = {
            [1] = "790054:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E6DE"
        },
        [80200311] = {
          Camera = "-1.582031,-202.988312,154.458984,0.000054,-4.600522,86.210663,50.000008,127.993942,false,Manual,11.517033",
          CameraBlendCurve = "easeInOutQuad",
          Content = "其实我最近已经和她吵架好几次了，你应该知道我们吵架的缘由吧？",
          DialogueId = 80200311,
          FacialId = {
            [1] = "790008:Beg",
            [2] = "790054:Sad01"
          },
          FinalCamera = "-4.151443,-241.749527,157.583984,0.000054,-4.600494,86.210938,50.000008,320.172394,false,Manual,6.00204",
          GUID = "C8C5E786",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200312,
          SpeakNpcId = 790054,
          Subtitle = "We've been at odds a lot lately. I imagine you know why.",
          TalkActionId = {
            [1] = "790054:Angry01_End",
            [2] = "790008:Shy03_Start"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E786"
        },
        [80200312] = {
          Content = "无非就是我想要钻研新的治病救人的办法，而她认为要坚守枯荣之术。",
          DialogueId = 80200312,
          Duration = 1,
          GUID = "C8C5E7B0",
          NextDialogue = 80200313,
          SpeakNpcId = 790054,
          Subtitle = "Simple, really — I want to explore new ways of healing. But she insists on clinging to the Art of Ephemerality.",
          TalkActionId = {
            [1] = "790054:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E7B0"
        },
        [80200313] = {
          Camera = "-96.161865,159.932739,99.22168,0.000047,7.599357,-58.392002,40.0,273.733917,false,Manual,6.00204",
          CameraBlendCurve = "easeInOutQuad",
          Content = "老实说，她有她的道理，我的方法一是前途未卜，不知成效，二是背离了大风九章……",
          DialogueId = 80200313,
          FinalCamera = "-122.544006,202.442444,84.046875,0.000046,8.199416,-58.192867,40.0,320.911621,false,Manual,6.00204",
          GUID = "C8C5E7DA",
          NextDialogue = 80200314,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"Think_Start"}},
LookAt{_delay{1.1},LookAtDescription{"790054:n(790008)"}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "And truthfully? I can't entirely fault her. My methods are untested, uncertain... and they stray far from the Nine Chapters of Dafeng.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E7DA"
        },
        [80200314] = {
          Content = "我与我的研究最后究竟是怎样的结局，谁也不知道。",
          DialogueId = 80200314,
          Duration = 2,
          GUID = "C8C5E804",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200315,
          Scripts = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "What lies ahead for me — or my work — I can't say.",
          TalkActionId = {
            [1] = "790054:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E804"
        },
        [80200315] = {
          Camera = "-63.858021,-9.877949,179.9375,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
          CameraBlendCurve = "easeInOutQuad",
          Content = "但有一件事我可以确定，那就是滥用枯荣之术，扶疏妹妹一定会英年早逝吧。",
          DialogueId = 80200315,
          FinalCamera = "-57.449242,-15.032286,177.196289,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
          GUID = "C8C5E82E",
          NextDialogue = 80200316,
          Scripts = "PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "But one thing I do know: if she keeps pushing herself like this, the Art of Ephemerality will consume her.",
          TalkActionId = {
            [1] = "790054:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E82E"
        },
        [80200316] = {
          Camera = "-43.131927,125.243118,128.523438,0.000069,4.597353,-67.988014,55.0,219.25647,false,Manual,17.764473",
          CameraBlendCurve = "easeInOutQuad",
          Content = "而我……不想看到这个局面，所以我绝不会让步，我们的架也只能一直吵下去了。",
          DialogueId = 80200316,
          FinalCamera = "-50.373177,143.161255,126.967773,0.000069,4.597353,-67.987976,55.0,219.25647,false,Manual,17.764473",
          GUID = "C8C5E858",
          LookAt = {
            [1] = "790054:n(790008)"
          },
          NextDialogue = 80200317,
          Scripts = [[
PARA{
PlayAnimation{_delay{4.1},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{11.1},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "And that... I couldn't bear. So no — I won't back down, which means we'll probably keep clashing, again and again.",
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790054:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E858"
        },
        [80200317] = {
          Camera = "-826.984375,564.034241,566.810547,0.00006,-22.002954,-35.181374,30.0,1155.509888,false,Manual,17.764473",
          CameraBlendCurve = "easeInOutQuad",
          Content = "唉，摊上这么一个不知姐姐苦心的妹妹，就算是得由我来道歉，我也不会让她好过的！",
          DialogueId = 80200317,
          FinalCamera = "-826.984375,564.034241,531.505859,0.000068,-22.202971,-35.380627,30.0,1155.509888,false,Manual,17.764473",
          GUID = "C8C5E882",
          NextDialogue = 80200318,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "That little sister of mine... never realises just how much I worry. Hmph. Even if I'm the one who has to apologise — I'm not making it easy on her!",
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          ToFinalCameraBlendTime = 40,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E882"
        },
        [80200318] = {
          Content = "但我已经不被允许靠近她了，这些小可爱就交由你来转赠吧！她那么信任你，肯定毫无防备，说不定还会像小时候一样被吓哭哦。",
          DialogueId = 80200318,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5E8AC",
          NextOptions = {
            [1] = 80200319
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{9.1},ActorId{790054},AnimationId{"Angry01_Start"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "She won't even let me near her right now. So, I'm counting on you to deliver these little \"sweethearts.\" She trusts you — won't suspect a thing. Might even shriek like she did as a child — wouldn't that be amusing?",
          TalkActionId = {
            [1] = "790054:Explain01_Start",
            [2] = "790008:Shy03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E8AC"
        },
        [80200319] = {
          Content = "寿星乌贼……",
          DialogueId = 80200319,
          GUID = "C8C5E8D6",
          NextDialogue = 80200320,
          Subtitle = "Shouxing squid..."
        },
        [80200320] = {
          Camera = "-40.08873,-25.583652,132.830078,0.000071,0.997262,64.819328,40.0,103.979561,false,Manual,17.764473",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你只是想拐弯抹角地告诉她，“希望你能长命百岁”吧？",
          DialogueId = 80200320,
          Duration = 1,
          FinalCamera = "-44.77795,-23.377747,132.830078,0.000071,0.997262,64.819717,40.0,103.979561,false,Manual,17.764473",
          GUID = "C8C5E900",
          NextDialogue = 80200321,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{"Think_End"},Duration{1}},
PlayFacial{_delay{4.1},ActorId{790008},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "This is actually your way of saying, \"May you live a long and healthy life,\" isn't it?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E900"
        },
        [80200321] = {
          Camera = "-335.726562,-30.426773,87.43457,-0.299988,4.600269,5.00543,28.0,371.52066,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "呃……看破不说破嘛，这种小心思说出来就没劲儿了。我还想看扶疏生气的样子呢！",
          DialogueId = 80200321,
          FinalCamera = "-376.866547,-34.026245,84.112305,-0.299988,4.600269,5.00543,28.0,383.921387,false,Manual,1.2",
          GUID = "C8C5E92A",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200322,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"Talk03_Start"},Duration{1}},
LookAt{_delay{6.1},LookAtDescription{"790054:n(790008)"}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Ehh—! Must you spoil it by putting it into words? Sentiments lose their charm once spelled out. I was hoping to see that flustered little face of hers!",
          TalkActionId = {
            [1] = "790054:Angry01_End"
          },
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790054:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E92A"
        },
        [80200322] = {
          Content = "快去！快去！",
          DialogueId = 80200322,
          GUID = "C8C5E954",
          SpeakNpcId = 790054,
          Subtitle = "Now go on! Shoo, shoo!",
          TalkActionId = {
            [1] = "790008:AgreeHead",
            [2] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E954"
        },
        [80200323] = {
          Content = "出幻境，回到采药任务点1，和扶疏站桩。",
          DialogueId = 80200323,
          GUID = "C8C5E97E",
          Subtitle = "Exit the illusory realm. Return to Collection Site 1. Speak with Fushu.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E97E"
        },
        [80200324] = {
          Camera = "119.887146,130.070343,137.368652,0.000012,2.799851,-138.98819,45.0,175.296234,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你醒了！",
          DialogueId = 80200324,
          FacialId = {
            [1] = "790053:Shock01"
          },
          FinalCamera = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98819,45.0,202.350357,false,Manual,12.098981",
          GUID = "C8C5E9A8",
          NextDialogue = 80200325,
          SpeakNpcId = 790053,
          Subtitle = "Ah... you've come to!",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790008:n(790053)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E9A8"
        },
        [80200325] = {
          Content = "才过去三四分钟，但实在牵肠挂肚……我都怀疑是否记错了书上的内容，莫非毒性比我想象中大？",
          DialogueId = 80200325,
          FacialId = {
            [1] = "790053:Sad01"
          },
          GUID = "C8C5E9D2",
          NextDialogue = 80200326,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3.1},ActorId{790053},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Only three or four minutes passed, yet I was already fretting... I even began to question the texts — could the toxin have been more potent than I thought?",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E9D2"
        },
        [80200326] = {
          Content = "我想给你用枯荣之术，但又怕没等我施术完毕，你就又好了……",
          DialogueId = 80200326,
          GUID = "C8C5E9FC",
          NextDialogue = 80200327,
          Scripts = "PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "I nearly invoked the Art of Ephemerality — but feared you'd recover before the spell was done...",
          TalkActionId = {
            [1] = "790053:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E9FC"
        },
        [80200327] = {
          Camera = "30.172951,-5.828094,146.924805,0.000022,-4.600405,68.410217,45.0,131.244232,false,Manual,6.805237",
          Content = "噗嗤……你们姐妹俩还真是像……",
          DialogueId = 80200327,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8C5EA26",
          NextDialogue = 80200328,
          SpeakNpcId = 790008,
          Subtitle = "Haha — you two really are twin sisters...",
          TalkActionId = {
            [1] = "790008:Laugh01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EA26"
        },
        [80200328] = {
          Camera = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98822,45.0,202.350357,false,Manual,6.805237",
          Content = "你也……见到家姐了？",
          DialogueId = 80200328,
          FacialId = {
            [1] = "790053:Unacceptable01"
          },
          GUID = "C8C5EA50",
          NextDialogue = 80200329,
          SpeakNpcId = 790053,
          Subtitle = "You saw my sister...?",
          TalkActionId = {
            [1] = "790053:Shy02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EA50"
        },
        [80200329] = {
          Camera = "-15.628626,-121.557404,164.124023,0.000028,-8.000521,72.409447,45.0,254.346725,false,Manual,6.805237",
          Content = "没错，你记得吗，她同你吵架，送了你最讨厌的寿星乌贼做道歉礼物。",
          DialogueId = 80200329,
          GUID = "C8C5EA7A",
          NextDialogue = 80200330,
          SpeakNpcId = 790008,
          Subtitle = "I did. You two had a fight. Then she tried to make peace — with Shouxing Squid, of all things.",
          TalkActionId = {
            [1] = "790008:Talk01_Start",
            [2] = "790053:Shy02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EA7A"
        },
        [80200330] = {
          Camera = "95.230194,90.889275,139.040527,0.000013,1.999715,-138.388199,45.0,129.860046,false,Manual,6.805237",
          Content = "……我都已经忘记了。那真是，很久很久以前的往事了。",
          DialogueId = 80200330,
          FacialId = {
            [1] = "790053:Sad03"
          },
          GUID = "C8C5EAA4",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200331,
          Scripts = "PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "...I'd forgotten. That was long, long ago.",
          TalkActionId = {
            [1] = "790053:DisagreeHead",
            [2] = "790008:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EAA4"
        },
        [80200331] = {
          Camera = "415.101501,-1311.599854,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你接受她的道歉了吗？",
          DialogueId = 80200331,
          FinalCamera = "448.243896,-1301.340576,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
          GUID = "C8C5EACE",
          NextDialogue = 80200332,
          SpeakNpcId = 790008,
          Subtitle = "Did you accept her apology?",
          TalkActionId = {
            [1] = "790008:Talk02_Start",
            [2] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EACE"
        },
        [80200332] = {
          Content = "呵呵……没有，我和她又吵了一架。我虽然不后悔……",
          DialogueId = 80200332,
          GUID = "C8C5EAF8",
          NextDialogue = 80200333,
          SpeakNpcId = 790053,
          Subtitle = "No... we argued once more. I do not regret my words — and yet...",
          TalkActionId = {
            [1] = "790008:Talk02_End",
            [2] = "790053:Sad02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EAF8"
        },
        [80200333] = {
          Camera = "106.505447,46.279133,180.103516,0.000015,-17.200472,-157.386368,45.0,118.629143,false,Manual,12.098981",
          Content = "但或许，现在的我会愿意接受那条寿星乌贼。",
          DialogueId = 80200333,
          FacialId = {
            [1] = "790053:SpecialSmile"
          },
          FinalCamera = "93.592377,40.89082,175.773438,0.000015,-17.200472,-157.386368,45.0,109.419518,false,Manual,12.098981",
          GUID = "C8C5EB22",
          NextDialogue = 80200334,
          SpeakNpcId = 790053,
          Subtitle = "Perhaps now, I might bring myself to accept the offering.",
          TalkActionId = {
            [1] = "790053:Sad02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EB22"
        },
        [80200334] = {
          Content = "……但也只是或许，我不喜欢多足生物，这点千真万确。",
          DialogueId = 80200334,
          FacialId = {
            [1] = "790053:Pain01"
          },
          GUID = "C8C5EB4C",
          NextDialogue = 80200335,
          SpeakNpcId = 790053,
          Subtitle = "Only perhaps. My aversion to multi-legged creatures remains wholly undiminished.",
          TalkActionId = {
            [1] = "790053:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EB4C"
        },
        [80200335] = {
          Camera = "48.175987,-418.433289,149.098633,0.000042,-4.200382,92.013222,45.0,450.246735,false,Manual,12.098981",
          CameraBlendCurve = "easeInOutQuad",
          Content = "其实……不应该让你看到这些往事，过去的人都已作古，看到这些徒惹伤怀，也是无益。",
          DialogueId = 80200335,
          FacialId = {
            [1] = "790008:Beg"
          },
          FinalCamera = "-69.18502,-422.553558,149.098633,0.000043,-3.200346,79.0131,45.0,450.246735,false,Manual,12.098981",
          GUID = "C8C5EB76",
          NextDialogue = 80200336,
          SpeakNpcId = 790053,
          Subtitle = "I shouldn't have let you glimpse such things. The past is long buried... to unearth it only invites old sorrow.",
          TalkActionId = {
            [1] = "790053:Sigh_End",
            [2] = "790008:Confident_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EB76"
        },
        [80200336] = {
          Content = "只是这枯荣阁是我们从小生长的地方，恐怕所有的音容草里，都存放着我们的过往。",
          DialogueId = 80200336,
          GUID = "C8C5EBA0",
          NextDialogue = 80200337,
          SpeakNpcId = 790053,
          Subtitle = "But this place — the Hall of Ephemerality — was where we came of age. I suppose every blade of Echowort here bears a sliver of our story.",
          TurnTo = {
            [1] = "790053:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EBA0"
        },
        [80200337] = {
          Camera = "-23.33609,-427.601105,149.098633,0.00004,16.598991,57.414169,45.0,450.246735,false,Manual,12.098981",
          CameraBlendCurve = "easeInOutQuad",
          Content = "所以下一次，还是由我来尝试吧，好吗？",
          DialogueId = 80200337,
          FinalCamera = "-23.33609,-427.601105,149.098633,0.000045,22.798664,61.012764,45.0,450.246735,false,Manual,12.098981",
          GUID = "C8C5EBCA",
          NextOptions = {
            [1] = 802003371,
            [2] = 802003372
          },
          SpeakNpcId = 790053,
          Subtitle = "So next time... allow me to be the one to taste it. Would you?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EBCA"
        },
        [80200339] = {
          Content = "谢谢。",
          DialogueId = 80200339,
          GUID = "C8C5EC1E",
          NextDialogue = 80200342,
          SpeakNpcId = 790053,
          Subtitle = "Thank you.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EC1E"
        },
        [80200341] = {
          Content = "呵呵，下次相约之时，我再讲给你听吧。",
          DialogueId = 80200341,
          GUID = "C8C5EC72",
          NextDialogue = 80200342,
          SpeakNpcId = 790053,
          Subtitle = "Hehe... Then next time we meet, I'll recount the whole tale myself.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EC72"
        },
        [80200342] = {
          Content = "好，那去寻找下一个地方吧。",
          DialogueId = 80200342,
          GUID = "C8C5EC9C",
          SpeakNpcId = 790053,
          Subtitle = "Come — take this. Let's move on.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EC9C"
        },
        [80200343] = {
          Content = "转场，枯荣阁野外",
          DialogueId = 80200343,
          GUID = "C8C5ECC6",
          Subtitle = "Scene Transition – Surrounding Wilds of the Hall of Ephemerality",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ECC6"
        },
        [80200344] = {
          Camera = "172.202026,4449.555664,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          Content = "找到了。",
          DialogueId = 80200344,
          FinalCamera = "402.414307,4427.007812,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
          GUID = "C8C5ECF0",
          NextDialogue = 80200345,
          SpeakNpcId = 790053,
          Subtitle = "Here's one.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790008:n(790053)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ECF0"
        },
        [80200345] = {
          Content = "要不要猜一猜，这是音容草，还是怀梦草呢？",
          DialogueId = 80200345,
          GUID = "C8C5ED1A",
          NextOptions = {
            [1] = 802003451,
            [2] = 802003452
          },
          SpeakNpcId = 790053,
          Subtitle = "Care to guess — is it Echowort, or Oneirowort?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          TurnTo = {
            [1] = "790053:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ED1A"
        },
        [80200348] = {
          Camera = "-514.179199,-65.437241,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
          Content = "看着没什么殊异之处，但摸在手里，确实有些极其微妙的差别……我猜这就是我们要找的怀梦草。",
          DialogueId = 80200348,
          FinalCamera = "-516.200806,-55.210449,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
          GUID = "C8C5ED98",
          NextDialogue = 80200349,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.1},ActorId{790053},AnimationId{"Confident_End"},Duration{1}},
PlayAnimation{_delay{6.1},ActorId{790053},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{_delay{8.1},ActorId{790053},AnimationId{"Explain01_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "It appears nearly identical to what we found before — but in the hand, the texture feels subtly different. I believe this is Oneirowort.",
          TalkActionId = {
            [1] = "790053:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ED98"
        },
        [80200349] = {
          Camera = "83.302071,146.197098,182.37207,0.000091,-11.599047,-118.401756,40.000011,172.35437,false,Manual,3.813417",
          Content = "如果不是连续失败两次，我恐怕永远不会有这样的发现。",
          DialogueId = 80200349,
          GUID = "C8C5EDC2",
          NextDialogue = 80200350,
          SpeakNpcId = 790053,
          Subtitle = "Had we not failed twice before, I might never have caught the difference.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EDC2"
        },
        [80200350] = {
          Camera = "5.743984,121.353485,148.166016,0.000061,-2.198931,1.794543,40.000023,104.974152,false,Manual,8.259511",
          Content = "第一个发现这两种植物的人是怎么做到的？难道她也像我们一样，一点一点试出来的？",
          DialogueId = 80200350,
          GUID = "C8C5EDEC",
          NextDialogue = 80200351,
          Scripts = "PlayAnimation{_delay{5.1},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "How did the first person ever tell them apart? Trial and error, like us?",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EDEC"
        },
        [80200351] = {
          Camera = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
          Content = "呵……是呀，她是怎么做到的呢？",
          DialogueId = 80200351,
          FacialId = {
            [1] = "790053:Think01"
          },
          GUID = "C8C5EE16",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200352,
          Scripts = "PlayFacial{_delay{2.1},ActorId{790053},FacialId{\"Sad03\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Heh... how did she do that, indeed?",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE16"
        },
        [80200352] = {
          Camera = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
          Content = "想必，一定经过无数次危险，与无数次不眠不休的钻研吧，即使不被理解，即使历经伤痛，她也从来没有放弃过。",
          DialogueId = 80200352,
          FinalCamera = "30.070026,119.496765,135.290039,0.000068,30.998163,-82.200356,50.000008,3999.122314,false,Manual,9.225292",
          GUID = "C8C5EE40",
          LookAt = {
            [1] = "790053:p(BP_200401fushu)"
          },
          NextDialogue = 80200353,
          SpeakNpcId = 790053,
          Subtitle = "She must've endured countless perils, sleepless nights, tireless study... Misunderstood, perhaps even hurt — yet never once losing heart.",
          ToFinalCameraBlendTime = 32,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE40"
        },
        [80200353] = {
          Content = "一切都是为了从无数个一百年前，一直流传到今天的那个悬壶济世的理想。",
          DialogueId = 80200353,
          Duration = 2,
          GUID = "C8C5EE6A",
          NextDialogue = 80200354,
          SpeakNpcId = 790053,
          Subtitle = "All for the sake of an ancient vow — to mend, to soothe, to care — carried forward by healer after healer through the ages.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE6A"
        },
        [80200354] = {
          Camera = "-159.132416,-51.042709,147.863281,0.00019,-2.796628,27.59856,50.000011,312.992676,false,Manual,3.221528",
          Content = "其实，还有一件事忘了告诉你。我刚才遇见的扶风说，匍地枝与隙中花更合适治疗多梦少眠。",
          DialogueId = 80200354,
          FacialId = {
            [1] = "790008:Beg"
          },
          GUID = "C8C5EE94",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200355,
          SpeakNpcId = 790008,
          Subtitle = "There's something I forgot to mention. Fufeng said Creeping Tendrils and Crackblooms work better for insomnia and restless sleep.",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE94"
        },
        [80200355] = {
          Content = "怀梦草虽能助眠，但会在梦中看到无法忘怀之事。",
          DialogueId = 80200355,
          GUID = "C8C5EEBE",
          NextDialogue = 80200356,
          Scripts = "PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Oneirowort may help one sleep, but it also stirs old memories that weigh upon the heart.",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EEBE"
        },
        [80200356] = {
          Camera = "71.251167,76.700455,164.569336,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
          Content = "也就是说，我不需要怀梦草了，但即使如此，你也要尝试吗？",
          DialogueId = 80200356,
          Duration = 1,
          FinalCamera = "66.068237,71.181648,163.882812,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
          GUID = "C8C5EEE8",
          NextDialogue = 80200357,
          SpeakNpcId = 790008,
          Subtitle = "So I don't really need it anymore. But... do you still want to try it?",
          TalkActionId = {
            [1] = "790008:Shy03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EEE8"
        },
        [80200357] = {
          Content = "扶疏没有说话，只是照旧将那叶尖放入口中。这一次，没有不安与责难，你听到了均匀的呼吸声，以及一句浅浅的梦呓——",
          DialogueId = 80200357,
          Duration = 2,
          GUID = "C8C5EF12",
          IsBlack = 1,
          NextDialogue = 80200358,
          Subtitle = "Fushu does not reply. As before, she places the grass blade upon her tongue. But this time, there is no tension, no reproach — only the rhythm of her breath, and a faint murmur from the depths of a dream.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EF12"
        },
        [80200358] = {
          Camera = "10.260178,29.508621,158.517578,0.00016,-13.799194,-104.60054,55.0,26.127415,false,Manual,15.973291",
          CameraBlendCurve = "easeInOutQuad",
          Content = "唉……下一次，换个道歉礼物吧。",
          DialogueId = 80200358,
          FacialId = {
            [1] = "790053:Close"
          },
          FinalCamera = "13.641603,40.02512,158.702148,0.000164,-2.999177,-107.99968,55.000008,38.118717,false,Manual,15.973291",
          GUID = "C8C5EF3C",
          Scripts = "PlayFacial{_delay{1.5},ActorId{790053},FacialId{\"SpecialSmile\"}}",
          SpeakNpcId = 790053,
          Subtitle = "... Next time, pick a more fitting gift of apology, would you?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EF3C"
        },
        [80210101] = {
          Camera = "805.707031,-8.211914,540.876953,0.0,0.0,-177.666962,25.0,125.0,false,DoNotOverride,2.8",
          Content = "侠自然是快意恩仇的，他们手提三尺剑，专爱打抱不平。",
          DialogueId = 80210101,
          FinalCamera = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
          GUID = "C8CC2DB2",
          NextDialogue = 80210102,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "A hero wanders with blades keen, hearts unbound, and rights the world's wrongs.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2DB2"
        },
        [80210102] = {
          Content = "浪迹天涯，四海飘零，不受任何羁绊。要按时回家的人，武艺再高，也更像是镖师，这听起来就比侠客不潇洒得多了。",
          DialogueId = 80210102,
          GUID = "C8CC2DDC",
          NextDialogue = 80210103,
          Subtitle = "The righteous roam free, untethered and unfettered. To keep a curfew is to be a guard, not a hero. For true grace lies not in the blade, but in the freedom it brings.",
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2DDC"
        },
        [80210103] = {
          Camera = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
          Content = "你要走了。",
          DialogueId = 80210103,
          FacialId = {
            [1] = "790065:CM_Sad01",
            [2] = "790066:CM_Sad01"
          },
          GUID = "C8CC2E06",
          LookAt = {
            [1] = "790065:n(790066)"
          },
          NextDialogue = 80210104,
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          SpeakNpcId = 790065,
          Subtitle = "So you're leaving.",
          TalkActionId = {
            [1] = "790067:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "790065:n(790066)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2E06"
        },
        [80210104] = {
          Camera = "390.390625,-180.267578,96.469727,0.000003,-1.798122,157.194687,30.0,337.309082,false,Manual,2.8",
          Content = "我要走了。",
          DialogueId = 80210104,
          FinalCamera = "310.414062,-146.627441,93.75,0.000003,0.0,157.194702,30.0,323.332245,false,Manual,2.8",
          GUID = "C8CC2E30",
          NextDialogue = 80210105,
          SpeakNpcId = 790066,
          Subtitle = "So I am.",
          TalkActionId = {
            [1] = "790066:Talk03_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2E30"
        }
      }
    end
  },
  {
    MinKey = 80210105,
