        [90010101] = {
          ContentES = "Vamos... otro golpe más... ¡Nada de parar... ¡No aún!",
          DialogueId = 90010101,
          Duration = 3,
          GUID = "E154B232",
          SpeakNpcId = 900001,
          Subtitle = "Don't falter, keep hammering...",
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_05"
        },
        [90010201] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentES = "¿Has encontrado algún tesoro últimamente? ¡Muéstramelo, y quizás forge un arma verdaderamente extraordinaria con ello!",
          DialogueId = 90010201,
          GUID = "E154C29A",
          SpeakNpcId = 900001,
          Subtitle = "Have you come across any treasures lately? Show me, and I might forge a truly extraordinary weapon out of it!",
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_r02"
        },
        [90010301] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentES = "Es mi amigo. Aunque sea pequeño, es bastante fuerte, él avivó el fuego de la forja para mí.",
          DialogueId = 90010301,
          GUID = "E154D302",
          SpeakNpcId = 900001,
          Subtitle = "That's my little friend. Tiny, but strong — it keeps the forge fire going."
        },
        [90020101] = {
          ContentES = "Bostezo Buenos días... Oh, ¿ya pasó la mañana? Bueno, entonces buenas tardes... ¿O quizá debería decir buenas noches?",
          DialogueId = 90020101,
          Duration = 3,
          GUID = "E15B1AD2",
          SpeakNpcId = 900002,
          Subtitle = "Good morning...",
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_r03"
        },
        [90020201] = {
          ContentES = "¿Eh?! J-juro que no estaba echando una siesta... ¡Humm! ¿Quieres comprar algo?",
          DialogueId = 90020201,
          GUID = "E15B2B3A",
          SpeakNpcId = 900002,
          Subtitle = "Ah! I... I wasn't slacking off... Ahem! I mean, what can I get you?",
          TalkActionId = {
            [1] = "900002:Shangdian_Write_Start"
          },
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_r01"
        },
        [90020301] = {
          ContentES = "Hablemos de otra cosa.",
          DialogueId = 90020301,
          GUID = "E15B3BA2",
          Subtitle = "Let's talk about something else"
        },
        [90020302] = {
          ContentES = "Adiós",
          DialogueId = 90020302,
          GUID = "E15B3BCC",
          Subtitle = "Goodbye"
        },
        [90030000] = {
          ContentES = "{性别:Él|Ella} nunca quería vivir como un pájaro enjaulado. Sé que algún día {性别:él|ella} abandonará esa isla para alcanzar el cielo. Pero lo que no puede saber es si eso será una bendición o una maldición para nosotros.",
          DialogueId = 90030000,
          GUID = "E15B3BCB",
          SpeakNpcId = 81101,
          Subtitle = "{性别:He|She} was never meant to be caged. I always knew {性别:he|she} would someday leave the island to reach for the sky. What I couldn't tell was whether that would be a blessing or a curse for us.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_idle"
        },
        [90030001] = {
          ContentES = "Bienvenida de vuelta. ¿Qué plan tienes para hoy? ¿O prefieres descansar en casa?",
          DialogueId = 90030001,
          GUID = "E161730A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 900300011,
            [2] = 900300013,
            [3] = 900300014,
            [4] = 900300015,
            [5] = 900300016,
            [6] = 900300018
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81101,
          Subtitle = "Welcome back. What are your plans for today? Or are you planning to rest at home?",
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_welcome",
          bForbidSkipOptions = true
        },
        [90030002] = {
          Content = "聊点别的",
          DialogueId = 90030002,
          GUID = "90030002.0",
          NextDialogue = 90030001,
          Subtitle = "Let's talk about something else"
        },
        [90030003] = {
          Content = "再见",
          DialogueId = 90030003,
          GUID = "90030003.0",
          Subtitle = "Goodbye"
        },
        [90030101] = {
          ContentES = "¿Deseo? A mí... no se me ocurre ningún deseo. Tu sonrisa por cada mañana ya es el mejor ánimo para mí.",
          DialogueId = 90030101,
          GUID = "E1618372",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030103,
          SpeakNpcId = 81101,
          Subtitle = "Wishes? I... can't think of any. Your smile in the morning is already the greatest pick-me-up of all.",
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_1"
        },
        [90030103] = {
          ContentES = "Te prometo que te traeré de vuelta.",
          DialogueId = 90030103,
          GUID = "E16183C6",
          NextDialogue = 90030104,
          SpeakNpcId = 100001,
          Subtitle = "I promise I'll get you back.",
          TalkActionId = {
            [1] = "81101:Explain02_End"
          }
        },
        [90030104] = {
          ContentES = "No te presiones demasiado. Si te sientes deprimida, ven a hablar conmigo. O si no tienes ganas de hablar, podemos pasar un momento en silencio {性别:juntosl|juntas}.",
          DialogueId = 90030104,
          GUID = "E16183F0",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "Don't push yourself. If you ever feel down, just come to me for a chat. Or, if you don't feel like talking, we can just spend some quiet time together.",
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90030301] = {
          ContentES = "A diferencia de la Isla del Purgatorio, aquí nieva todos los días. Por suerte, tienes un lugar cálido para quedarte. En comparación con nuestra pequeña cabaña en la Isla del Purgatorio, este lugar es bastante lujoso.",
          DialogueId = 90030301,
          GUID = "E161A442",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030303,
          SpeakNpcId = 81101,
          Subtitle = "Unlike Purgatorio Island, it snows here every day. Thankfully, you have a warm place to stay. Compared to our little shack back on the island, this place feels quite luxurious.",
          TalkActionId = {
            [1] = "81101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_1"
        },
        [90030303] = {
          ContentES = "Pero sigo teniendo un poco de frío.",
          DialogueId = 90030303,
          GUID = "E161A443",
          NextDialogue = 90030304,
          SpeakNpcId = 100001,
          Subtitle = "But I'm still a bit chilly.",
          TalkActionId = {
            [1] = "81101:Think_End"
          }
        },
        [90030304] = {
          ContentES = "¿Recuerdas cómo se te quedaban siempre las manos heladas en invierno? Ven, déjame calentártelas.",
          DialogueId = 90030304,
          GUID = "E161A46C",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "Remember how your hands would always get very cold in winter? Here, let me warm them up.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90030401] = {
          ContentES = "...No lo sé. Yo tampoco estoy segura. Quizás sea un hermoso sueño, en el que nunca me haya alejado de tu lado, como siempre.",
          DialogueId = 90030401,
          GUID = "E161B4AA",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030403,
          SpeakNpcId = 81101,
          Subtitle = "...I'm not sure either. Maybe it's a beautiful dream where I've never left your side, as always.",
          TalkActionId = {
            [1] = "81101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_1"
        },
        [90030403] = {
          ContentES = "Daría cualquier cosa por volver a verte.",
          DialogueId = 90030403,
          GUID = "E161B4FE",
          NextDialogue = 90030404,
          SpeakNpcId = 100001,
          Subtitle = "I'd give anything to see you again.",
          TalkActionId = {
            [1] = "81101:Talk02_End"
          }
        },
        [90030404] = {
          ContentES = "Yo también quería verte, muchísimo... Ojalá nos podamos volver a encontrar algún día.",
          DialogueId = 90030404,
          GUID = "E161B528",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "I feel the same, very much so... May we truly reunite one day.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90030501] = {
          ContentES = "Bueno, ese lugar es como una ciudad hecha de acero... Mm, más bien como una prisión exactamente. Pasé mi infancia allí.",
          DialogueId = 90030501,
          GUID = "E161C512",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030503,
          SpeakNpcId = 81101,
          Subtitle = "Well, that place is like a city made of steel... Mm, more like a prison, to be precise. I spent my early years there.",
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_1"
        },
        [90030503] = {
          ContentES = "Más tarde, alguien me escapó de allí. Junta contigo, nos llevó a la Isla del Purgatorio. No puedo decirte mucho sobre ella... Lo siento. Le prometí que no lo diría a nadie.",
          DialogueId = 90030503,
          GUID = "E161C566",
          NextDialogue = 90030504,
          SpeakNpcId = 81101,
          Subtitle = "Later on, along with you, I was taken away from there by someone, and we ended up on Purgatorio Island. I can't share much about her, though — Sorry, I promised her.",
          TalkActionId = {
            [1] = "81101:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_2"
        },
        [90030504] = {
          ContentES = "... La vida en la Isla del Purgatorio era tan tranquila que casi creía que podríamos vivir así para siempre. Pero hasta el día en que ellos vinieron ante mí, no me di cuenta de que yo nunca había escapado verdaderamente de esa prisión.",
          DialogueId = 90030504,
          GUID = "E161C590",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "...Life on Purgatorio Island was so peaceful, that I almost believed we could live that way forever. But it wasn't until the day they came for me that I realised I had never truly escaped that prison.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90030601] = {
          ContentES = "Sí, es un poco ruidoso, pero no me disgusta. Has hecho muchos nuevos amigos aquí, esto es bueno, me alegro mucho por ti.",
          DialogueId = 90030601,
          GUID = "E161D57A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030603,
          SpeakNpcId = 81101,
          Subtitle = "It's somewhat noisy, but I don't hate it. You've made many new friends here, which is a good thing — I'm really happy for you.",
          TalkActionId = {
            [1] = "81101:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_1"
        },
        [90030603] = {
          ContentES = "De esta manera, nunca te sentirás sola, incluso cuando yo no esté de tu lado.",
          DialogueId = 90030603,
          GUID = "E161D5A4",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "This way, you'll never feel lonely, even when I'm not around.",
          TalkActionId = {
            [1] = "81101:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90030801] = {
          ContentES = "Pues, descansa un momento con la cabeza en mi regazo, como en los viejos tiempos.",
          DialogueId = 90030801,
          GUID = "E161F64A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "Then rest your head on my lap for a while, just like old times.",
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_06_1",
          bForbidSkipOptions = true
        },
        [90031001] = {
          ContentES = "Señorita Truffle, ¿podría... acariciar a su cerdito? Solo una vez. Por favor, sujételo para mí, temo que se escape. Los animalitos siempre parecen huir de mí cuando me los acerca.",
          DialogueId = 90031001,
          GUID = "E162171A",
          NextDialogue = 90031002,
          SpeakNpcId = 81101,
          Subtitle = "Miss Truffle, may I... pet your pig? Just one stroke will do. Please hold her still for me; I'm afraid she might run off... Little animals always seem to flee from me.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_1"
        },
        [90031002] = {
          ContentES = "Gracias... Ah, qué suave y cálido, qué agradable...",
          DialogueId = 90031002,
          GUID = "E1621744",
          SpeakNpcId = 81101,
          Subtitle = "Thank you... Ah, it's so warm and soft. How nice...",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_2"
        },
        [90031101] = {
          ContentES = "No soy esa “N.º 0” de la Legión, ni tu títere. Vete, porque no me iré contigo vivo.",
          DialogueId = 90031101,
          GUID = "E1622782",
          SpeakNpcId = 81101,
          Subtitle = "I'm not that \"No.0\" from the Legion, nor am I your stooge. Leave, as I will never leave with you alive.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_03"
        },
        [90031201] = {
          ContentES = "He oído que eres una gran gourmet. ¿Podrías compartir algunas de tus recetas? {nickname} siempre habla maravillas de tu cocina, y no es solo adulación, es un elogio sincero.",
          DialogueId = 90031201,
          GUID = "E16237EA",
          NextDialogue = 90031202,
          SpeakNpcId = 81101,
          Subtitle = "I heard you're quite the gourmet. Could you show me some of your recipes?  always raves about your cooking, and it was genuine, not just flattery.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_04_1"
        },
        [90031202] = {
          ContentES = "Espera, ¿eso es todo? Entonces, ¿por qué...? ¿Cuál es tu secreto?",
          DialogueId = 90031202,
          GUID = "E1623814",
          SpeakNpcId = 81101,
          Subtitle = "Wait, is that all? Then why... What's your secret?",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_04_2"
        },
        [90040000] = {
          ContentES = "¿Te quedas para pasar un rato agradable conmigo? *risita* Ya lo estoy esperando.",
          DialogueId = 90040000,
          GUID = "E167DBA9",
          SpeakNpcId = 82101,
          Subtitle = "Are you staying here to spend some lovely time with me? I'm already looking forward to it.",
          VoiceName = "voice/$Locale$/char/Shuimu/vo_idle"
        },
        [90040001] = {
          ContentES = "He estado esperando aquí desde que desperté. Mi veneno casi se ha agotado... Menos mal que viniste. Puedo sentirlo burbujear otra vez por mis venas... ¿Podrías... acercarte un poco más?",
          DialogueId = 90040001,
          GUID = "E167DBAA",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextOptions = {
            [1] = 900400011,
            [2] = 900400012,
            [3] = 900400013,
            [4] = 900400014,
            [5] = 900400015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82101,
          Subtitle = "I've been waiting here ever since I woke up. My venom has almost run dry... So, it's a good thing you came. I can feel it bubbling through my veins again. Can you come a little closer...?",
          TalkActionId = {
            [1] = "82101:Give"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90040002] = {
          Content = "聊点别的",
          DialogueId = 90040002,
          GUID = "90040002.0",
          NextDialogue = 90040001,
          Subtitle = "Let's talk about something else"
        },
        [90040003] = {
          Content = "再见",
          DialogueId = 90040003,
          GUID = "90040003.0",
          Subtitle = "Goodbye"
        },
        [90040101] = {
          ContentES = "Sí, me encantan los días lluviosos. Me recuerdan a las historias de amor que he leído, donde los encuentros románticos siempre suceden bajo la lluvia.",
          DialogueId = 90040101,
          GUID = "E167EC12",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040103,
          SpeakNpcId = 82101,
          Subtitle = "Yes, I love rainy days. They remind me of the love stories I've read, where romantic encounters always happen on a rainy day.",
          TalkActionId = {
            [1] = "82101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_1"
        },
        [90040103] = {
          ContentES = "¿Acaso los días de lluvia no son más adecuados para quedarse en la cama? ¿Por qué habría encuentros románticos?",
          DialogueId = 90040103,
          GUID = "E167EC13",
          NextDialogue = 90040104,
          SpeakNpcId = 100001,
          Subtitle = "Aren't rainy days more for sleeping in? Why would there be romantic encounters?",
          TalkActionId = {
            [1] = "82101:Explain02_End"
          }
        },
        [90040104] = {
          ContentES = "¿Has observado alguna vez a los que buscan refugio de la lluvia? Se encuentran bajo los aleros, el aire húmedo intensifica el aroma de la vegetación, el amor fluye gentilmente con avances tentativos...",
          DialogueId = 90040104,
          GUID = "E167EC3C",
          NextDialogue = 90040105,
          SpeakNpcId = 82101,
          Subtitle = "Have you ever observed those seeking shelter from the rain? They meet under eaves, the damp air enhancing the fragrance of greenery, love gently flowing with tentative advances...",
          TalkActionId = {
            [1] = "82101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_2"
        },
        [90040105] = {
          ContentES = "Jeje... Espera a la próxima vez que llueva y sal conmigo, lo verás.",
          DialogueId = 90040105,
          GUID = "E167EC3B",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "Hehe, join me next time it rains, and you'll see what I mean.",
          TalkActionId = {
            [1] = "82101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90040201] = {
          ContentES = "Ah, inicias una conversación sobre el amor conmigo... qué inesperado.",
          DialogueId = 90040201,
          GUID = "E167FC7A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040203,
          SpeakNpcId = 82101,
          Subtitle = "Ah, you're initiating a conversation about love with me — how unexpected.",
          TalkActionId = {
            [1] = "82101:Shock_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_1"
        },
        [90040203] = {
          ContentES = "Hmm, ¿cómo lo describo?... Hum, es como el agua en el perfume, que besa y abraza cada ingrediente, devora y absorbe su fragancia, y al final se fusiona con ellos para crear un aroma duradero...",
          DialogueId = 90040203,
          GUID = "E167FCA4",
          NextDialogue = 90040204,
          SpeakNpcId = 82101,
          Subtitle = "Hmm, how should I put it? ...It's like water in perfume, which kisses and embraces each ingredient, devours and absorbs their fragrance, and eventually blends with them to create a long-lasting aroma...",
          TalkActionId = {
            [1] = "82101:Shock_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_2"
        },
        [90040204] = {
          ContentES = "¿Te refieres a pasar tiempo juntos cada día?",
          DialogueId = 90040204,
          GUID = "E167FCA5",
          NextDialogue = 90040205,
          SpeakNpcId = 100001,
          Subtitle = "You mean it's about cuddling up together every day?"
        },
        [90040205] = {
          ContentES = "Mucho más. Busco un amor tan profundo que nos haga verdaderamente inseparables... Incluso si la vida de uno termina, este se convertirá en el abono para las flores de nuestro jardín, las flores se convertirán en perfume, perdurando alrededor del otro por la eternidad.",
          DialogueId = 90040205,
          GUID = "E167FCA6",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "There's much more to that. I seek a love so profound that we become truly inseparable... Even if life itself ends, one will become the mulch for the flowers in our garden; the blooms will turn into perfume, lingering around the other for eternity.",
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90040301] = {
          ContentES = "¿Especial? Ay, efectivamente... Desde pequeña, muchos me han visto un “monstruo”.",
          DialogueId = 90040301,
          GUID = "E1680CE2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040303,
          SpeakNpcId = 82101,
          Subtitle = "Special? Indeed... Many have seen me as a \"monster\" since I was young.",
          TalkActionId = {
            [1] = "82101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_1"
        },
        [90040303] = {
          ContentES = "Esas caras de disgusto no son agradables, y eso hay que corregirlo...",
          DialogueId = 90040303,
          GUID = "E1680D36",
          NextDialogue = 90040304,
          SpeakNpcId = 82101,
          Subtitle = "The looks of disgust on their faces aren't pleasant, which should be corrected...",
          TalkActionId = {
            [1] = "82101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_2"
        },
        [90040304] = {
          ContentES = "Quizás una pequeña punzada de mi toxina en su piel suavice esas miradas de disgusto... Jeje.",
          DialogueId = 90040304,
          GUID = "E1680D60",
          NextDialogue = 90040305,
          SpeakNpcId = 82101,
          Subtitle = "Perhaps a little sting of my toxin in their skin will soften those harsh looks... Hehe.",
          TalkActionId = {
            [1] = "82101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_3"
        },
        [90040305] = {
          ContentES = "Entonces, cuando dices “especial”, ¿te refieres a “especial” como un monstruo... o a “especialmente” encantadora?",
          DialogueId = 90040305,
          GUID = "E1680D8A",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "So, when you say \"special\", do you mean special like a monster... or specially enchanting?",
          TalkActionId = {
            [1] = "82101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90040401] = {
          ContentES = "Estoy perfectamente bien. Mi veneno forma parte de mí, como un regalo del Dios del Amor, es inofensivo para mí y me ayudará a encontrar a la Persona destinada.",
          DialogueId = 90040401,
          GUID = "E1681D4A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040403,
          SpeakNpcId = 82101,
          Subtitle = "I'm perfectly fine. My venom is part of me, like a gift from the God of Love — it's harmless to me, and will help me find my destined lover.",
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_04_1"
        },
        [90040403] = {
          ContentES = "Parece que realmente te gusta mucho ese regalo.",
          DialogueId = 90040403,
          GUID = "E1681D4B",
          NextDialogue = 90040404,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like you really appreciate this gift."
        },
        [90040404] = {
          ContentES = "Por supuesto. Aunque a menudo me hace parecer un monstruo, también me distingue. Creo firmemente que la Persona destinada para un monstruo debe ser muy especial, ¿no crees?",
          DialogueId = 90040404,
          GUID = "E1681D74",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "Of course. Though it often casts me as a monster, it also sets me apart. I believe that the destined lover meant for a monster must be quite special, don't you think?",
          TalkActionId = {
            [1] = "82101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90040501] = {
          ContentES = "Es mi perfume característico, con notas de salida tan intensas como un primer encuentro, notas de corazón de dulzura que fijan el aroma, y una nota de fondo que perdura con un regusto agridulce.",
          DialogueId = 90040501,
          GUID = "E1682DB2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040503,
          SpeakNpcId = 82101,
          Subtitle = "It's my signature perfume, with top notes as intense as a first encounter, heart notes of sweet nothings that fix the scent, and a base note that lingers with a bittersweet aftertaste.",
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_05_1"
        },
        [90040503] = {
          ContentES = "Pues, ¿cuáles son los ingredientes específicos?",
          DialogueId = 90040503,
          GUID = "E1682E06",
          NextDialogue = 90040504,
          SpeakNpcId = 100001,
          Subtitle = "What exactly are the ingredients?"
        },
        [90040504] = {
          ContentES = "Ese es mi pequeño secreto. Sin embargo, me encantaría guiarte personalmente en el proceso de elaboración, paso a paso, del comienzo al final.",
          DialogueId = 90040504,
          GUID = "E1682E30",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "That's my little secret. However, I'd be delighted to guide you through the blending process myself, one step at a time.",
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90040601] = {
          ContentES = "Ese aliento seco... ¡Ah, eres tú! ¡Cuánto tiempo sin verte! ¿Sigues planeando llevarme esposada? ¡Sí! Suena divertido.\nDespués de todo, aunque te diera mil oportunidades, siempre escaparía de tu control... ¿No crees? Señorita Alcaidesa.",
          DialogueId = 90040601,
          GUID = "E1683E1A",
          SpeakNpcId = 82101,
          Subtitle = [[
That dry scent... Oh, it's you. Long time no see. Still planning to take me away in handcuffs? That sounds like a fun idea...
After all, even if I gave you a thousand chances, I would still escape from your grasp... Wouldn't you agree, Ms. Warden?]],
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_01"
        },
        [90040701] = {
          ContentES = "¿Me tienes miedo? No te preocupes. Al final, haré que me ames. Ven, huele la fragancia que mezclé. Es muy dulce y creo que te encantará.",
          DialogueId = 90040701,
          GUID = "E1684E82",
          SpeakNpcId = 82101,
          Subtitle = "You're scared of me? Don't worry. I'll make you love me eventually. Come, have a whiff of the perfume I've blended. It smells very sweet, and I believe you'll love it.",
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_02"
        },
        [90050000] = {
          ContentES = "¡Oye! ¡Déjame pelear contigo! Estoy aburridísima y mis tentáculos necesitan estirarse.",
          DialogueId = 90050000,
          GUID = "E16E4449",
          SpeakNpcId = 82301,
          Subtitle = "Heyyyy, lemme fight with you. I'm bored stiff and my tentacles need to stretch out!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_idle"
        },
        [90050001] = {
          ContentES = "Hum... ahora es el momento perfecto. Debería irme antes de... ¡Eh! ¡Cuándo llegaste!",
          DialogueId = 90050001,
          GUID = "E16E444A",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextOptions = {
            [1] = 900500011,
            [2] = 900500012,
            [3] = 900500013,
            [4] = 900500014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82301,
          Subtitle = "Now's the perfect timing. I should head out before... Huh?! When did you get here?",
          TalkActionId = {
            [1] = "82301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90050002] = {
          Content = "聊点别的",
          DialogueId = 90050002,
          GUID = "90050002.0",
          NextDialogue = 90050001,
          Subtitle = "Let's talk about something else"
        },
        [90050003] = {
          Content = "再见",
          DialogueId = 90050003,
          GUID = "90050003.0",
          Subtitle = "Goodbye"
        },
        [90050101] = {
          ContentES = "Berry, yo...",
          DialogueId = 90050101,
          GUID = "E16E54B2",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050103,
          SpeakNpcId = 82301,
          Subtitle = "\"Berry, I...\"",
          TalkActionId = {
            [1] = "82301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_01_1"
        },
        [90050103] = {
          ContentES = "¿?",
          DialogueId = 90050103,
          GUID = "E16E5506",
          NextDialogue = 90050104,
          SpeakNpcId = 100001,
          Subtitle = "?"
        },
        [90050104] = {
          ContentES = "Tu sonrisa por cada mañana ya es el mejor ánimo para mí. A partir de ahora, siempre estaré aquí para protegerte. Jeje, bastante convincente, ¿no?",
          DialogueId = 90050104,
          GUID = "E16E5530",
          NextDialogue = 90050105,
          SpeakNpcId = 82301,
          Subtitle = "\"Your smile in the morning is already the greatest pick-me-up of all. From now on, I'll always be there to keep you safe.\" Hee hee, pretty convincing, isn't it?",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_01_2"
        },
        [90050105] = {
          ContentES = "¡No! ¡Muy lejos! ¡Y deja de imitarme!",
          DialogueId = 90050105,
          GUID = "E16E555A",
          NextDialogue = 90050106,
          SpeakNpcId = 100001,
          Subtitle = "No! Not even close! And stop mimicking us!",
          TalkActionId = {
            [1] = "82301:Explain02_End"
          }
        },
        [90050106] = {
          ContentES = "¿Estás {性别:enfadadol|enfadada}? Jiji, ¡tus ceños fruncidos me dan aún más ganas de imitarte!",
          DialogueId = 90050106,
          GUID = "E16E5584",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "Are you angry? Hehehe, that scowl on your face makes me want to mimic you even more!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90050201] = {
          ContentES = "¡Es fácil! ¡Es que puedo cambiar mi aspecto como quiera! Jiji, puedo adoptar cualquier forma o color y camuflarme perfectamente en cualquier sitio. ¡Nadie me detecta!",
          DialogueId = 90050201,
          GUID = "E16E651A",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050203,
          SpeakNpcId = 82301,
          Subtitle = "Easy, I can change my look however I want! Hehe, I can take any shape, any colour, and blend in anywhere perfectly. No one can spot me!",
          TalkActionId = {
            [1] = "82301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_02_1"
        },
        [90050203] = {
          ContentES = "Una vez, incluso me convertí en un barril solo esperando para asustarte, pero no te acercaste...",
          DialogueId = 90050203,
          GUID = "E16E6544",
          NextDialogue = 90050204,
          SpeakNpcId = 82301,
          Subtitle = "One time, I even turned into a barrel just to scare you, but you never came near...",
          TalkActionId = {
            [1] = "82301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_02_2"
        },
        [90050204] = {
          ContentES = "Bueno, un barril que apareció de repente en medio de la habitación, de todas maneras, solo había una posibilidad...",
          DialogueId = 90050204,
          GUID = "E16E6546",
          NextDialogue = 90050205,
          SpeakNpcId = 100001,
          Subtitle = "Well, a random barrel popping up in the middle of a room? That's a bit of a giveaway..."
        },
        [90050205] = {
          ContentES = "¡¿Qué?! Espera, ¡por eso sabías que era yo y te fuiste sin más! ¡Eres tan pícara!",
          DialogueId = 90050205,
          GUID = "E16E6545",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "What?! Wait, so you knew it was me and just walked away? That's not cool!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90050301] = {
          ContentES = "¡Oye! ¡No me metas en el mismo saco que esos malvados que roban a cualquiera! ¡No soy como ellos!",
          DialogueId = 90050301,
          GUID = "E16E7582",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050303,
          SpeakNpcId = 82301,
          Subtitle = "Hey! Don't lump me together with those baddies who steal from just anyone! I'm nothing like them!",
          TalkActionId = {
            [1] = "82301:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_03_1"
        },
        [90050303] = {
          ContentES = "¿Diferencia? ¿Cuál es la diferencia?",
          DialogueId = 90050303,
          GUID = "E16E7584",
          NextDialogue = 90050304,
          SpeakNpcId = 100001,
          Subtitle = "How are you any different?",
          TalkActionId = {
            [1] = "82301:Talk01_End"
          }
        },
        [90050304] = {
          ContentES = "Yo solo robo a los ladrones. Me camuflo, me acerco sigilosamente y les quito mis tesoros favoritos ¡directo de sus bolsillos!",
          DialogueId = 90050304,
          GUID = "E16E7585",
          NextDialogue = 90050305,
          SpeakNpcId = 82301,
          Subtitle = "I only steal from thieves. I blend in, sneak up close, and pluck my favourite treasures right from their pockets!",
          TalkActionId = {
            [1] = "82301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_03_2"
        },
        [90050305] = {
          ContentES = "Cuando se dan cuenta, ¡sus caras son geniales! Jiji... ¡Si acaso, soy más bien una justiciera!",
          DialogueId = 90050305,
          GUID = "E16E7583",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "When they find out, their faces are priceless! Hehe... If anything, I'm more like a vigilante!",
          TalkActionId = {
            [1] = "82301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90050401] = {
          ContentES = "¡Claro que no! A ti tampoco te gustaría que te llamaran “demonio” con cara de asco y ceño fruncido.",
          DialogueId = 90050401,
          GUID = "E16E85EA",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050403,
          SpeakNpcId = 82301,
          Subtitle = "Of course not. You wouldn't like it either if people called you a \"demon\" with a frown and disgust.",
          TalkActionId = {
            [1] = "82301:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_1"
        },
        [90050403] = {
          ContentES = "Entonces, ¿por qué te autodenominas “Demonio Tabethe, la Mano Roja”?",
          DialogueId = 90050403,
          GUID = "E16E85EC",
          NextDialogue = 90050404,
          SpeakNpcId = 100001,
          Subtitle = "Then why do you call yourself \"Demon Tabethe the Red Hand\"?",
          TalkActionId = {
            [1] = "82301:Talk03_End"
          }
        },
        [90050404] = {
          ContentES = "Es porque quiero que la palabra “demonio” se vuelva genial. Ahora, solo con mencionar mi título “Demonio Tabethe, la Mano Roja”, a los ladrones les da escalofríos.",
          DialogueId = 90050404,
          GUID = "E16E85EB",
          NextDialogue = 90050405,
          SpeakNpcId = 82301,
          Subtitle = "That's because I want to make the word \"demon\" cool. Now, the mere mention of my title \"Demon Tabethe the Red Hand\" sends shivers down the spine of those thieves.",
          TalkActionId = {
            [1] = "82301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_2"
        },
        [90050405] = {
          ContentES = "Algún día, la palabra “demonio” solo hará que la gente piense lo genial que soy. ¡Qué gran sueño es! ¿Verdad?",
          DialogueId = 90050405,
          GUID = "E16E85ED",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "And one day, the word \"demon\" will only make people think how awesome I am. That'll be pretty cool, don't you think?",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90050501] = {
          ContentES = "¿Quieres atraparme? ¿Por qué? ¡No soy mala! Solo robo a otros ladrones. ¡No es para tanto!... ¡Oye, aléjate! ¡Ay! ¡Eso me quemó!",
          DialogueId = 90050501,
          GUID = "E16E9652",
          SpeakNpcId = 82301,
          Subtitle = "You wanna catch me? Why? I'm not a bad girl! I only steal from other thieves. It's no big deal... Hey, stay away from me! Ow! That burnt!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_01"
        },
        [90050601] = {
          ContentES = "¿Esto es para mí? Mmm, pero pareces muy peligroso, así que será mejor que te lo quedes. Espera... este aroma me está mareando... Siento que mis tentáculos se están entumeciendo... ¡De verdad que eres peligroso!",
          DialogueId = 90050601,
          GUID = "E16EA6BA",
          SpeakNpcId = 82301,
          Subtitle = "This is for me? Hmm, but you look pretty dangerous, so you'd better keep it. Wait... this scent is making me feel light-headed... My tentacles are going numb... You really are dangerous!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_02"
        },
        [90050701] = {
          ContentES = "¡Me encanta la forma en que le hablas a tu espada! “Samael, ¿te gusta este lugar? ¡Exploremos más sitios juntos!”\n¡Oye! ¿Qué te pasa? ¿Por qué te alteras tanto? Jaja, ¡eres muy gracioso!",
          DialogueId = 90050701,
          GUID = "E16EB722",
          SpeakNpcId = 82301,
          Subtitle = [[
I love the way you talk to your sword! "Samael, do you like this place? Let's explore more places together!"
Hey, what's up with you, getting all riled up? Haha, you're a proper laugh!]],
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_03"
        },
        [90060000] = {
          ContentES = "¡Qué vista tan placentera!... ¿No tienes miedo de mi fuego? ¡Ja, hormiga ignorante! Lamentarás tu ignorancia cuando te aplasté contra el suelo.",
          DialogueId = 90060000,
          GUID = "E174ACE9",
          SpeakNpcId = 83201,
          Subtitle = "What a blissful sight... Aren't you afraid of my fire, insect? Hmph, you'll regret your ignorance when I stomp you into the dirt.",
          VoiceName = "voice/$Locale$/char/Haier/vo_idle"
        },
        [90060001] = {
          ContentES = "¿Estás listo para el interrogatorio?",
          DialogueId = 90060001,
          GUID = "E174ACEA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextOptions = {
            [1] = 900600011,
            [2] = 900600012,
            [3] = 900600013,
            [4] = 900600014,
            [5] = 900600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83201,
          Subtitle = "Ready for the interrogation?",
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_welcome",
          bForbidSkipOptions = true
        },
        [90060002] = {
          Content = "聊点别的",
          DialogueId = 90060002,
          GUID = "90060002.0",
          NextDialogue = 90060001,
          Subtitle = "Let's talk about something else"
        },
        [90060003] = {
          Content = "再见",
          DialogueId = 90060003,
          GUID = "90060003.0",
          Subtitle = "Goodbye"
        },
        [90060101] = {
          ContentES = "Si conocieras la historia, sabrías que la primera Alcaidesa de la Prisión Militar Real tenía la piel como lava fundida. Incluso los criminales más despiadados temían sus interrogatorios.",
          DialogueId = 90060101,
          GUID = "E174BD52",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060102,
          SpeakNpcId = 83201,
          Subtitle = "If you learned about history, you'd know that the first warden of the Royal Military Prison had skin like molten lava. Even the most ruthless criminals feared her interrogations.",
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_1"
        },
        [90060102] = {
          ContentES = "Yo, como descendiente suya, llevo con orgullo su título, lista para incinerar todos los pecados con mi fuego.",
          DialogueId = 90060102,
          GUID = "E174BD53",
          NextDialogue = 90060103,
          SpeakNpcId = 83201,
          Subtitle = "As her descendant, I proudly bear her name, ready to incinerate all sins with my fire.",
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_2"
        },
        [90060103] = {
          ContentES = "Entonces... ¿Tu piel abrasadora te dificulta la vida diaria?",
          DialogueId = 90060103,
          GUID = "E174BD54",
          NextDialogue = 90060104,
          SpeakNpcId = 100001,
          Subtitle = "Then... does your scorching skin make everyday life difficult?"
        },
        [90060104] = {
          ContentES = "Sí tiene algunos desafíos: solo puedo dormir en camas de hierro y no puedo estar mucho tiempo en estructuras de madera. Sin embargo, me permite sacar criminales de edificios en llamas y administrar justicia. Además, el frío nunca me molesta.",
          DialogueId = 90060104,
          GUID = "E174BD55",
          NextDialogue = 90060105,
          SpeakNpcId = 83201,
          Subtitle = "It does pose some challenges — I can only sleep on iron beds and can't linger in wooden structures for long. However, it allows me to pull criminals from burning buildings and administer justice. And the cold never bothers me.",
          TalkActionId = {
            [1] = "83201:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_3"
        },
        [90060105] = {
          ContentES = "Mi aspecto inusual es más bien un regalo para mí. Si acaso tiene algún inconveniente... siempre he querido probar el helado, pero se derrite en mi mano antes de poder saborearlo...",
          DialogueId = 90060105,
          GUID = "E174BD56",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "My unusual appearance is more of a gift. If there's any downside... I've always wanted to try ice cream, but it melts in my hand before I can taste it...",
          TalkActionId = {
            [1] = "83201:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90060201] = {
          ContentES = "Desde la fundación del Imperio, mi familia ha gestionado la prisión donde se encarcelaban los criminales más atroces, corrigiendo los errores o eliminando las amenazas.",
          DialogueId = 90060201,
          GUID = "E174CDBA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060202,
          SpeakNpcId = 83201,
          Subtitle = "Since the Empire's inception, my family has managed the prison that holds the most heinous criminals, correcting wrongs and neutralising threats.",
          TalkActionId = {
            [1] = "83201:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_1"
        },
        [90060202] = {
          ContentES = "Mi piel de un rojo intenso, legado de mi antepasado, la primera guardia, me predestinó a hacer cumplir el estricto código que ella estableció. Así que no fui yo quien eligió ser Alcaidesa, fue el manto de la Alcaidesa el que me eligió.",
          DialogueId = 90060202,
          GUID = "E174CDBB",
          NextDialogue = 90060203,
          SpeakNpcId = 83201,
          Subtitle = "My fiery red skin, a legacy from the first warden, predestined me to continue enforcing the iron-clad code she established. So it wasn't me who chose to become a warden; it was the mantle of warden that chose me.",
          TalkActionId = {
            [1] = "83201:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_2"
        },
        [90060203] = {
          ContentES = "¿Eso significa que ya has alcanzado tus metas?",
          DialogueId = 90060203,
          GUID = "E174CDBC",
          NextDialogue = 90060204,
          SpeakNpcId = 100001,
          Subtitle = "Does that mean you've already achieved your aspirations?"
        },
        [90060204] = {
          ContentES = "Convertirme en Alcaidesa es solo el principio. Me obliga a permanecer vigilante, erradicando cualquier injusticia dentro del Imperio hasta mi último suspiro.",
          DialogueId = 90060204,
          GUID = "E174CDBD",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Becoming a warden is merely the beginning. It compels me to remain vigilant, eradicating any injustice within the Empire until my final breath.",
          TalkActionId = {
            [1] = "83201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90060301] = {
          ContentES = "Por supuesto. La prisión del Imperio está llena de criminales astutos. Mis deberes incluyen realizar interrogatorios, revisar expedientes y frustrar los intentos de escape.",
          DialogueId = 90060301,
          GUID = "E174DE22",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060302,
          SpeakNpcId = 83201,
          Subtitle = "Certainly. The Imperial Prison is teeming with devious criminals. My duties include conducting interrogations, reviewing case files, and thwarting escape attempts.",
          TalkActionId = {
            [1] = "83201:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_1"
        },
        [90060302] = {
          ContentES = "Cada minuto de descanso retrasa la justicia, y cuando la justicia se retrasa, el caos y la ley de la selva prevalecen.",
          DialogueId = 90060302,
          GUID = "E174DE23",
          NextDialogue = 90060303,
          SpeakNpcId = 83201,
          Subtitle = "Every minute of rest delays justice a bit, and when justice is delayed, chaos and the law of the jungle take over.",
          TalkActionId = {
            [1] = "83201:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_2"
        },
        [90060303] = {
          ContentES = "¿Sería más fácil tu trabajo si hubiera menos prisioneros?",
          DialogueId = 90060303,
          GUID = "E174DE24",
          NextDialogue = 90060304,
          SpeakNpcId = 100001,
          Subtitle = "Would your job be easier if there were fewer prisoners?"
        },
        [90060304] = {
          ContentES = "Algunos eruditos han imaginado un mundo sin crímenes. Si ese día llegara, mi propósito desaparecería, pues el mal exige la existencia de una Alcaidesa. Hasta entonces, estoy comprometida con el mantenimiento del orden.",
          DialogueId = 90060304,
          GUID = "E174DE25",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Some scholars have envisioned a crime-free world. Should such a day come, my purpose would vanish, for evil necessitates a warden's existence. Until then, I am committed to upholding order.",
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90060401] = {
          ContentES = "¿Justicia? La justicia es el control del deseo mediante el poder, la supresión del mal mediante la fuerza y el castigo de los malvados por los poderosos.",
          DialogueId = 90060401,
          GUID = "E174EE8A",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060402,
          SpeakNpcId = 83201,
          Subtitle = "Justice? It is the restraint of desire through power, the suppression of evil through strength, and the punishment of the wicked by the mighty.",
          TalkActionId = {
            [1] = "83201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_1"
        },
        [90060402] = {
          ContentES = "¿No es eso un poco “demasiado simplista”?",
          DialogueId = 90060402,
          GUID = "E174EE8B",
          NextDialogue = 90060403,
          SpeakNpcId = 100001,
          Subtitle = "Isn't that a bit \"painting with a broad brush\"?",
          TalkActionId = {
            [1] = "83201:Explain01_End"
          }
        },
        [90060403] = {
          ContentES = "¿Hmph, simplista? No esperaría que un niño ingenuo lo entendiera. No vivimos en una utopía donde la gente simplemente se da la mano y se ama. ¡Solo a través del poder absoluto y el orden se puede asegurar la verdadera justicia!",
          DialogueId = 90060403,
          GUID = "E174EE8C",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Hmph, broad? I wouldn't expect a naive child to understand. We don't live in a utopia where people simply hold hands and love each other. Only through absolute power and order can true justice be secured!",
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90060501] = {
          ContentES = "Con los criminales aun vagando por las calles del Imperio, el tiempo libre es un lujo para la Acaidesa. El único respiro que tengo es cuando me tomo unos tragos de licor fuerte entre tanta actividad.",
          DialogueId = 90060501,
          GUID = "E174FEF2",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060502,
          SpeakNpcId = 83201,
          Subtitle = "With criminals still roaming the streets of the Empire, spare time is a luxury for a warden. The only respite I get is when I sneak in a few strong drinks amidst a busy schedule.",
          TalkActionId = {
            [1] = "83201:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_1"
        },
        [90060502] = {
          ContentES = "¿¡Qué!? ¿Bebes alcohol?",
          DialogueId = 90060502,
          GUID = "E174FF1C",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060503,
          SpeakNpcId = 100001,
          Subtitle = "What!? You drink!?",
          TalkActionId = {
            [1] = "83201:Talk01_End"
          }
        },
        [90060503] = {
          ContentES = "¿Por qué tanta sorpresa? Es solo una distracción. Durante los interrogatorios, siempre escuché hablar de varios tipos de alcohol. Eso despertó mi curiosidad por esa supuesta poción malvada que siempre parecía estar asociada al crimen. Así que bebo de vez en cuando.",
          DialogueId = 90060503,
          GUID = "E174FF1D",
          NextDialogue = 90060504,
          SpeakNpcId = 83201,
          Subtitle = "Why so surprised? It's merely a diversion. During interrogations, I always hear about various kinds of alcohol, which made me curious about this so-called wicked potion that seems to be associated with crime. So I drink once in a while.",
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_2"
        },
        [90060504] = {
          ContentES = "Y cuanto más bebo, más convencida estoy de que no es la bebida la que es mala.",
          DialogueId = 90060504,
          GUID = "E174FF1E",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "And the more I drink, the more I'm convinced that it's not the drink that is wicked.",
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90060601] = {
          ContentES = "Yo soy la Alcaidesa y tú, la Jefa de la Legión. Juntas, somos las implacables guardianas del oscuro orden del Imperio. Su odio hacia nosotras no significa nada, ¡mientras sirvamos a Hyperborea!",
          DialogueId = 90060601,
          GUID = "E1750F5A",
          SpeakNpcId = 83201,
          Subtitle = "I'm the warden and you're the Legion's chief. Together, we're the merciless keepers of the dark order that is the Empire. Their hatred of us means nothing, as long as we serve Hyperborea!",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_01"
        },
        [90060701] = {
          ContentES = "Nos encontramos otra vez.",
          DialogueId = 90060701,
          GUID = "E1751FC2",
          SpeakNpcId = 83201,
          Subtitle = "We meet again.",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_02"
        },
        [90060801] = {
          ContentES = "¡Bah! Eres el Ayudante de Sibylle... el que siempre es acusado de incumplimiento de sus deberes, ¿eh? Puedo ver que escondes tu destreza y ambición solo para estar al lado de Sibylle. Entonces, ¿cuáles son tus motivos ocultos?",
          DialogueId = 90060801,
          GUID = "E175302A",
          SpeakNpcId = 83201,
          Subtitle = "Tsk, you're Sibylle's adjutant... the one who's always being accused of failing your duties, huh? I can tell that you're hiding your prowess and ambition just so you can stand alongside Sibylle. So what are your ulterior motives.",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_03"
        },
        [90070000] = {
          ContentES = "Un día tranquilo es un día bueno.",
          DialogueId = 90070000,
          GUID = "E17B1589",
          SpeakNpcId = 84201,
          Subtitle = "An uneventful day is a good day.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_idle"
        },
        [90070001] = {
          ContentES = "Haz lo que quieras. Aprecia tu libertad antes de que las cadenas de la ley te aten.",
          DialogueId = 90070001,
          GUID = "E17B158A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextOptions = {
            [1] = 900700011,
            [2] = 900700012,
            [3] = 900700013,
            [4] = 900700014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84201,
          Subtitle = "Do what you need to. Cherish your freedom before the chains of law bind you.",
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_welcome",
          bForbidSkipOptions = true
        },
        [90070002] = {
          Content = "聊点别的",
          DialogueId = 90070002,
          GUID = "90070002.0",
          NextDialogue = 90070001,
          Subtitle = "Let's talk about something else"
        },
        [90070003] = {
          Content = "再见",
          DialogueId = 90070003,
          GUID = "90070003.0",
          Subtitle = "Goodbye"
        },
        [90070101] = {
          ContentES = "... Ve a leer un tomo o busca otra compañía para tales discursos triviales. Quizás los Tejestrellas que venden sus artesanías puedan satisfacer tu curiosidad.",
          DialogueId = 90070101,
          GUID = "E17B25F2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070102,
          SpeakNpcId = 84201,
          Subtitle = "...Go read a tome or seek another's company for such trivial discourse. Perhaps the Starweavers peddling their crafts would indulge your curiosity.",
          TalkActionId = {
            [1] = "84201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_1"
        },
        [90070102] = {
          ContentES = "Cada uno ve el mundo de manera diferente. Me interesa conocer tu opinión.",
          DialogueId = 90070102,
          GUID = "E17B25F3",
          NextDialogue = 90070103,
          SpeakNpcId = 100001,
          Subtitle = "Everyone looks at the world differently. I'm asking about your views.",
          TalkActionId = {
            [1] = "84201:Talk03_End"
          }
        },
        [90070103] = {
          ContentES = "A menudo estoy absorto en mis pensamientos, por eso mi perspectiva suele ser bastante subjetiva. Si realmente sientes curiosidad, una visita a ese lugar te resultará mucho más reveladora que cualquier relato de segunda mano.",
          DialogueId = 90070103,
          GUID = "E17B25F4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "I am often preoccupied, and my perspectives are notably skewed. Should your curiosity truly beckon, a visit thither would enlighten you far beyond any second-hand account.",
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90070201] = {
          ContentES = "Los «Nueve Capítulos de Dafeng» son las leyes sagradas de Huaxu, no admiten ninguna desobediencia. Si alguien se atreve a desafiar el decreto divino, nos toca a algunos sofocar la consiguiente agitación.",
          DialogueId = 90070201,
          GUID = "E17B365A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070202,
          SpeakNpcId = 84201,
          Subtitle = "The Nine Chapters are the sacred laws of Huaxu, brooking no defiance. Should anyone dare to challenge divine decree, it falls upon some to quell the ensuing turmoil.",
          TalkActionId = {
            [1] = "84201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_1"
        },
        [90070202] = {
          ContentES = "Eso te convierte en un oficial respetado, ¿verdad?",
          DialogueId = 90070202,
          GUID = "E17B365B",
          NextDialogue = 90070203,
          SpeakNpcId = 100001,
          Subtitle = "Does that make you a respected senior official then?",
          TalkActionId = {
            [1] = "84201:Explain01_End"
          }
        },
        [90070203] = {
          ContentES = "... Quizás, solo un título. Rara vez me relaciono con la gente común. Mi presencia, por muy necesaria que sea para hacer cumplir la ley, a menudo trae consigo desgracias. Pocos en Huaxu me recibirían con alegría.",
          DialogueId = 90070203,
          GUID = "E17B365C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "...Perhaps in title. I seldom consort with the commoners. My presence, necessary as it may be for law's enforcement, often brings collateral grief. Few in Huaxu would greet me with joy.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90070301] = {
          ContentES = "No hay nada que celebrar. Esa es toda la cuestión.",
          DialogueId = 90070301,
          GUID = "E17B46C2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070302,
          SpeakNpcId = 84201,
          Subtitle = "There is nought to celebrate. That is the entirety of the matter.",
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_1"
        },
        [90070302] = {
          ContentES = "Quizás podrías compartir tus molestias conmigo.",
          DialogueId = 90070302,
          GUID = "E17B46C3",
          NextDialogue = 90070303,
          SpeakNpcId = 100001,
          Subtitle = "Maybe you can try sharing your troubles with me."
        },
        [90070303] = {
          ContentES = "Agradezco tu preocupación, sin embargo, no quiero cargar a otra alma con mis molestias. Es innecesario.",
          DialogueId = 90070303,
          GUID = "E17B46C4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "Your concern is appreciated, yet I would not burden another soul with my woes. It is unnecessary.",
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90070401] = {
          ContentES = "En efecto. La luna, una maravilla celestial, purifica los restos del día, sea una festividad o un acto vil. A lo largo de los tiempos, la luna creciente simplemente observa desde su encumbrada posición.",
          DialogueId = 90070401,
          GUID = "E17B572A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070402,
          SpeakNpcId = 84201,
          Subtitle = "Indeed. The moon, a celestial marvel, purifies the remnants of the day, be it festivity or foul deed. Through the ages, the crescent merely watches from its lofty perch.",
          TalkActionId = {
            [1] = "84201:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_1"
        },
        [90070402] = {
          ContentES = "¿Estás pensando en el pasado?",
          DialogueId = 90070402,
          GUID = "E17B572B",
          NextDialogue = 90070403,
          SpeakNpcId = 100001,
          Subtitle = "Are you thinking about the past?",
          TalkActionId = {
            [1] = "84201:Talk02_End"
          }
        },
        [90070403] = {
          ContentES = "No, soy uno que le ha dicho adiós al pasado. Esta noche, simplemente me he permitido medio vaso más de vino.",
          DialogueId = 90070403,
          GUID = "E17B572C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "No, I am one who has bid farewell to the past. Tonight, I simply indulged in an extra half cup of wine.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90070501] = {
          ContentES = "Desconozco la historia que has abandonado, pero nuestros aromas son similares. Mantén tu distancia: no hallo consuelo en mi propia especie.",
          DialogueId = 90070501,
          GUID = "E17B6792",
          SpeakNpcId = 84201,
          Subtitle = "I know not of the history you've forsaken, but our scents are alike. Keep your distance - I find little comfort in my own kind.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_01"
        },
        [90070601] = {
          ContentES = "Ya no somos camaradas de antaño. Como el viento fugaz, la gente pasa. Es mejor dejar atrás el ayer.",
          DialogueId = 90070601,
          GUID = "E17B77FA",
          SpeakNpcId = 84201,
          Subtitle = "We are no longer comrades of old. Like the fleeting wind, people drift by. Best leave yesteryear behind.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_02"
        },
        [90070701] = {
          ContentES = "Tu determinación y tu respeto por la ley merecen mi respeto. ¿Alguna vez la duda nubla tu certeza?",
          DialogueId = 90070701,
          GUID = "E17B8862",
          SpeakNpcId = 84201,
          Subtitle = "Your resolve and adherence to law command my respect. Do moments of doubt ever cloud your certitude?",
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_03"
        },
        [90080000] = {
          ContentES = "Hmm... Esta escopeta plegable furtiva automático podría mejorarse para disparar en ráfaga... Si le aumento la potencia de fuego... Hmm, perfecto, podré eliminar a los enemigos aún más rápido en la próxima misión y volver a casa temprano.",
          DialogueId = 90080000,
          GUID = "E1817E29",
          SpeakNpcId = 84202,
          Subtitle = "Hmm... This sneak folding shotgun could use an auto-fire upgrade, and if I give it more firepower... Then, we can take out our enemies even faster on our next mission and head home early.",
          VoiceName = "voice/$Locale$/char/Landi/vo_idle"
        },
        [90080001] = {
          ContentES = "Ah... Me siento tan fresco al despertarme. Oye, amigo, no tiene sentido trabajar todo el día. Tu lista de tareas nunca terminará. Recuerda, el descanso es una necesidad, no es un lujo.",
          DialogueId = 90080001,
          GUID = "E1817E2A",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextOptions = {
            [1] = 900800011,
            [2] = 900800012,
            [3] = 900800013,
            [4] = 900800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84202,
          Subtitle = "Ahh... I feel so fresh after just waking up. Listen, buddy, there's no point in working all day. Your to-do list will never end. Remember, relaxation is a necessity, not a luxury.",
          VoiceName = "voice/$Locale$/char/Landi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90080002] = {
          Content = "聊点别的",
          DialogueId = 90080002,
          GUID = "90080002.0",
          NextDialogue = 90080001,
          Subtitle = "Let's talk about something else"
        },
        [90080003] = {
          Content = "再见",
          DialogueId = 90080003,
          GUID = "90080003.0",
          Subtitle = "Goodbye"
        },
        [90080101] = {
          ContentES = "¿Mi familia? Mis padres llevan años sin preocuparse por mí. Solo mis dos hermanas intentan mandarme de vez en cuando. Pero ahora que estoy en la Legión, fuera de su alcance.",
          DialogueId = 90080101,
          GUID = "E1818E92",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080103,
          SpeakNpcId = 84202,
          Subtitle = "My family? My parents haven't really fussed over me for years; just my sisters occasionally trying to boss me around. But now that I'm in the Legion, they're out of reach.",
          TalkActionId = {
            [1] = "84202:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_1"
        },
        [90080103] = {
          ContentES = "Parece que tus hermanas son bastante mandonas.",
          DialogueId = 90080103,
          GUID = "E1818EE6",
          NextDialogue = 90080104,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like your sisters are pretty mean."
        },
        [90080104] = {
          ContentES = "¡No, no, nada de eso! ¡E-Ellas son absolutamente encantadoras, inteligentes, amables, dulces, con mucho encanto, hermosas y casi perfectas! Sin embargo, un poco más de decoro sería bueno...",
          DialogueId = 90080104,
          GUID = "E1818F10",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "Oh, not at all! T-They're absolutely delightful, smart, kind-hearted, gentle, charming, beautiful, and just about perfect! Though, a bit more decorum would be nice...",
          TalkActionId = {
            [1] = "84202:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90080201] = {
          ContentES = "¡Anda, tú eres de los que no saben apreciar un buen descanso! Escucha bien: las camas son refugios, donde el alma encuentra la paz; los tejados son santuarios, donde desaparecen las preocupaciones. En los jardines por la tarde, la luz del sol brilla, la siesta es una melodía de los dulces sueños...",
          DialogueId = 90080201,
          GUID = "E1819EFA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080203,
          SpeakNpcId = 84202,
          Subtitle = "Huh, you're one of those who don't appreciate a good rest! Listen up: Beds are havens, where souls find ease; rooftops sanctuaries, where anxieties cease. In afternoon gardens, the sunlight gleams; take a nap, and enjoy the symphony of sweet dreams...",
          TalkActionId = {
            [1] = "84202:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_1"
        },
        [90080203] = {
          ContentES = "(Da la vuelta y se va)",
          DialogueId = 90080203,
          GUID = "E1819F4E",
          NextDialogue = 90080204,
          SpeakNpcId = 100001,
          Subtitle = "(Turn around and leave)"
        },
        [90080204] = {
          ContentES = "... ¡Oye! ¡Todavía no he terminado!",
          DialogueId = 90080204,
          GUID = "E1819F78",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "...Hey! I wasn't done!",
          TalkActionId = {
            [1] = "84202:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90080301] = {
          ContentES = "¡Ella es una auténtica máquina de trabajo! Necesitaría partirme en tres solo para seguirle el ritmo... Bueno, quiero decir, la Jefa Sibylle, como una capitana, siempre es muy estricta con nosotros.",
          DialogueId = 90080301,
          GUID = "E181AF62",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080303,
          SpeakNpcId = 84202,
          Subtitle = "She sure knows how to run you ragged... I'd need to split myself in three just to keep up... Ahem, I mean, Chief Sibylle is always perfectly strict with us.",
          TalkActionId = {
            [1] = "84202:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_1"
        },
        [90080303] = {
          ContentES = "Demasiado tarde, lo oí todo.",
          DialogueId = 90080303,
          GUID = "E181AFB6",
          NextDialogue = 90080304,
          SpeakNpcId = 100001,
          Subtitle = "Too late, I heard that clearly."
        },
        [90080304] = {
          ContentES = "Ay, qué debo hacer... Pues, ¿qué te parece si te invito a un té por la tarde y olvidamos esta conversación? No te preocupes, no estará envenenado.",
          DialogueId = 90080304,
          GUID = "E181AFE0",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "...How about I treat you to some afternoon tea, and we pretend this conversation never happened? Don't worry, it won't be spiked.",
          TalkActionId = {
            [1] = "84202:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90080401] = {
          ContentES = "Te he diseñado algo increíble: ¡un robot compañero! Te seguirá en el combate, agitando una pequeña pancarta y animándote: “¡Ánimo!” “¡Lo estás petando!”.",
          DialogueId = 90080401,
          GUID = "E181BFCA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080403,
          SpeakNpcId = 84202,
          Subtitle = "I've rigged up something awesome for you — a tiny robot sidekick! It'll follow you around in battle, waving a little banner and cheering, \"Go get'em! You're smashing it!\"",
          TalkActionId = {
            [1] = "84202:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_1"
        },
        [90080403] = {
          ContentES = "Es genial, ¿verdad? ¿Si está lleno de energía? Espera a que lo termine...",
          DialogueId = 90080403,
          GUID = "E181BFF4",
          NextDialogue = 90080404,
          SpeakNpcId = 84202,
          Subtitle = "Pretty cool, huh? Just wait till I actually get it working...",
          TalkActionId = {
            [1] = "84202:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_2"
        },
        [90080404] = {
          ContentES = "(Da la vuelta y se va)",
          DialogueId = 90080404,
          GUID = "E181BFF5",
          NextDialogue = 90080405,
          SpeakNpcId = 100001,
          Subtitle = "(Turn around and leave)"
        },
        [90080405] = {
          ContentES = "¡Oye, no he terminado! Hice estos planos durante mis valiosos descansos... ¿Sabes lo difícil que fue esconderlos de la Jefa Sibylle?",
          DialogueId = 90080405,
          GUID = "E181BFF6",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "Hey, I didn't finish! I drew up these plans during my precious breaks — do you know how hard it was for me to keep them from Chief Sibylle?",
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90080501] = {
          ContentES = "Mi informe, Jefa Sibylle. Las tareas de hoy están organizadas. Si tiene alguna orden adicional, estoy lista para cumplirla. Sin embargo, hoy ha sido un día muy exigente, así que debería descansar bien para evitar el agotamiento.",
          DialogueId = 90080501,
          GUID = "E181D032",
          SpeakNpcId = 84202,
          Subtitle = "Reporting, Chief Sibylle. Today's tasks have been arranged. If you have any additional orders, I'm ready to carry them out. However, today was quite demanding, so you should take some rest to avoid burning out.",
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_01"
        },
        [90080601] = {
          ContentES = "¡Excelente trabajo en la última misión! Pero he recibido algunas quejas por los daños a la propiedad pública durante la ejecución. Eh, me da un poco de vergüenza disculparme en tu nombre, soy algo tímida. Así que... querida y amable Señorita Lynn, ¿podrías encargarte de estas tareas urgentes por mí? ¡Por favor!",
          DialogueId = 90080601,
          GUID = "E181E09A",
          SpeakNpcId = 84202,
          Subtitle = "Great job on the last mission, but I've received some complaints about damage to public property... I find it kinda awkward to apologise to people on your behalf... After all, I'm a bit shy. Soooo, lovely and kind-hearted Miss Lynn, could you handle these urgent tasks for me? Pretty please with a cherry on top!",
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_02"
        },
        [90080701] = {
          ContentES = "¿Qué...? ¿Cómo es esto posible? ¡Quizás estoy tan cansada que veo cosas! Mejor pido la baja por lesión laboral y me tomo unos días más de descanso.",
          DialogueId = 90080701,
          GUID = "E181F102",
          SpeakNpcId = 84202,
          Subtitle = "Wha... How can this be? Maybe I'm just so tired that I'm seeing things now. Might as well file for a work-related injury and take a few more days off.",
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_03"
        },
        [90090000] = {
          ContentES = "Exponer tu espalda a tu enemigo con tanta facilidad... ¿Es ingenuidad o pura locura?",
          DialogueId = 90090000,
          GUID = "E187E6C9",
          SpeakNpcId = 84301,
          Subtitle = "Exposing your back to your enemy so carelessly... Is it naivety or sheer folly?",
          VoiceName = "voice/$Locale$/char/Xibi/vo_idle"
        },
        [90090001] = {
          ContentES = "Al observar tus esfuerzos incansables por fortalecerte, no puedo evitar esperar con ansias el día en que vuelvas a desafiarme.",
          DialogueId = 90090001,
          GUID = "E187E6CA",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextOptions = {
            [1] = 900900011,
            [2] = 900900012,
            [3] = 900900013,
            [4] = 900900014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84301,
          Subtitle = "Watching your relentless efforts to strengthen yourself, I can't help but look forward to the day you challenge me again.",
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90090002] = {
          Content = "聊点别的",
          DialogueId = 90090002,
          GUID = "90090002.0",
          NextDialogue = 90090001,
          Subtitle = "Let's talk about something else"
        },
        [90090003] = {
          Content = "再见",
          DialogueId = 90090003,
          GUID = "90090003.0",
          Subtitle = "Goodbye"
        },
        [90090101] = {
          ContentES = "Una fuerza especial bajo el mando directo del Emperador, encargada de misiones encubiertas y que sirve como un martillo listo para golpear en el campo de batalla.",
          DialogueId = 90090101,
          GUID = "E187F732",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090103,
          SpeakNpcId = 84301,
          Subtitle = "A special force under the direct command of the Emperor, tasked with covert missions and serving as a hammer ready to strike on the battlefield.",
          TalkActionId = {
            [1] = "84301:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_1"
        },
        [90090103] = {
          ContentES = "¡Ah! Con el apoyo del Emperador, no me extraña que seas tan arrogante.",
          DialogueId = 90090103,
          GUID = "E187F786",
          NextDialogue = 90090104,
          SpeakNpcId = 100001,
          Subtitle = "Huh, backed by the Emperor — no wonder you're always so overbearing.",
          TalkActionId = {
            [1] = "84301:Talk03_End"
          }
        },
        [90090104] = {
          ContentES = "Te equivocas. Sin el Emperador, la Legión sigue en pie, pero sin la Legión, la corona caería sin remedio.",
          DialogueId = 90090104,
          GUID = "E187F7B0",
          NextDialogue = 90090105,
          SpeakNpcId = 84301,
          Subtitle = "You got it all wrong. Without the Emperor, the Legion still stands; without the Legion, however, the crown would surely fall.",
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_2"
        },
        [90090105] = {
          ContentES = "¿Debería denunciarte por traición por esa declaración?",
          DialogueId = 90090105,
          GUID = "E187F7DA",
          NextDialogue = 90090106,
          SpeakNpcId = 100001,
          Subtitle = "Should I report you for treason based on that statement?",
          TalkActionId = {
            [1] = "84301:Confident_Start"
          }
        },
        [90090106] = {
          ContentES = "No dudes en intentarlo. La traición es un delito grave, y cualquier acusación tendría que ascender por los rangos y acabar directamente en mi escritorio.",
          DialogueId = 90090106,
          GUID = "E187F804",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "Feel free to try. Treason is a grave offence, and any accusation would work its way up through the ranks and end up right on my desk.",
          TalkActionId = {
            [1] = "84301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90090201] = {
          ContentES = "Hmpf, mi lealtad no es al Imperio, sino a mis ideales. Un hombre lo dio todo por ellos, y ese es su legado que me esfuerzo por mantener.",
          DialogueId = 90090201,
          GUID = "E188079A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090203,
          SpeakNpcId = 84301,
          Subtitle = "Hmph, my allegiance is not to the Empire, but to my ideals. A man once gave everything for these, and it is his legacy that I strive to uphold.",
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_1"
        },
        [90090203] = {
          ContentES = "Solo estás buscando excusas. No importa cuál sea la razón, tus acciones no son más que una forma de apoyar la tiranía.",
          DialogueId = 90090203,
          GUID = "E18807EE",
          NextDialogue = 90090204,
          SpeakNpcId = 100001,
          Subtitle = "You're just making excuses. No matter the reason, your actions are nothing more than enabling tyranny."
        },
        [90090204] = {
          ContentES = "No te falta razón. Sin embargo, para conseguir lo que deseo, usaré todos los medios a mi alcance y ascenderé al poder por cualquier método. Pero cada paso que doy me acerca más a mi ideal. ¿Y a ti, a dónde te han llevado tus pasos?",
          DialogueId = 90090204,
          GUID = "E1880818",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "You're not wrong. To get what I desire, I'll use everything at my disposal and climb the ladder by any means necessary; but each step I take is a step closer to what I believe in. Where have your steps led you?",
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90090301] = {
          ContentES = "Ya da igual. Mi familia ya no está desde hace mucho tiempo.",
          DialogueId = 90090301,
          GUID = "E1881802",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090303,
          SpeakNpcId = 84301,
          Subtitle = "It's okay. My family's long gone anyway.",
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_1"
        },
        [90090303] = {
          ContentES = "...",
          DialogueId = 90090303,
          GUID = "E1881856",
          NextDialogue = 90090304,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [90090304] = {
          ContentES = "De hecho, lo encuentro liberador. Esto significa que ya no hay distracciones, solo hay un camino claro para enfrentarme a mis enemigos, tanto los conocidos como los ocultos.",
          DialogueId = 90090304,
          GUID = "E1881880",
          NextDialogue = 90090305,
          SpeakNpcId = 84301,
          Subtitle = "I find it liberating, actually. It means no more distractions — just a clear path to contend with my enemies, both known and hidden.",
          TalkActionId = {
            [1] = "84301:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_2"
        },
        [90090305] = {
          ContentES = "Para cualquiera en la Legión, los sentimientos son meras debilidades.",
          DialogueId = 90090305,
          GUID = "E18818AA",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "Sentiment and feelings are merely weaknesses for anyone in the Legion.",
          TalkActionId = {
            [1] = "84301:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90090401] = {
          ContentES = "Así es. He soportado insultos y burlas en persona, aquellos que se esconden a espaldas seguramente se quejan aún más.",
          DialogueId = 90090401,
          GUID = "E188286A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090403,
          SpeakNpcId = 84301,
          Subtitle = "Indeed. I've endured my share of curses and jibes to my face, and those from the gutter surely grumble even more.",
          TalkActionId = {
            [1] = "84301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_1"
        },
        [90090403] = {
          ContentES = "Afortunadamente, en este mundo injusto, el poder absoluto todavía puede ganarte un mínimo de respeto.",
          DialogueId = 90090403,
          GUID = "E18828BE",
          NextDialogue = 90090404,
          SpeakNpcId = 84301,
          Subtitle = "Fortunately, in this unjust world, absolute power can still earn one a modicum of respect.",
          TalkActionId = {
            [1] = "84301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_2"
        },
        [90090404] = {
          ContentES = "En ese caso, si alguna vez pierdes tu poder, seguro que te darán la patada mientras estás en el suelo.",
          DialogueId = 90090404,
          GUID = "E18828E8",
          NextDialogue = 90090405,
          SpeakNpcId = 100001,
          Subtitle = "In that case, if you ever lost your power, they'd certainly kick you hard while you're down."
        },
        [90090405] = {
          ContentES = "Exactamente. Por eso nunca mostraré debilidad; de lo contrario, se abalanzarán como lobos al olor de la sangre, ansiosos por despedazarme.",
          DialogueId = 90090405,
          GUID = "E1882912",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "Exactly, which is why I'll never show weakness; otherwise, they'd pounce like wolves at the scent of blood, eager to tear me apart.",
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90090501] = {
          ContentES = "... Es hora de zanjar nuestras diferencias.",
          DialogueId = 90090501,
          GUID = "E18838D2",
          SpeakNpcId = 84301,
          Subtitle = "...It's time we resolve our differences.",
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_01"
        },
        [90090801] = {
          ContentES = "Cuanto más perfecta sea tu máscara, más afilados serán los colmillos que has forjado en la oscuridad. Espero el día en que reveles tu verdadera naturaleza, para destrozarlos sin piedad.",
          DialogueId = 90090801,
          GUID = "E1886A0A",
          SpeakNpcId = 84301,
          Subtitle = "The more flawless your disguise, the sharper the fangs you've honed in the dark. I await the day you reveal your true nature, so I can shatter those fangs without mercy.",
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_04"
        },
        [90091001] = {
          ContentES = "¿Ya se han organizado todos los informes recientes de misiones, planes de combate, documentos de logística e informes de bajas?\nBien, entonces, finalicemos hoy los eslóganes de la campaña exterior, los análisis de los casos internos, los informes de rutina para el Emperador y los datos de las pruebas de las nuevas armas de la Academia Spathatoi. Esto forma parte de nuestro trabajo, no es una carga adicional.",
          DialogueId = 90091001,
          GUID = "E1888ADA",
          SpeakNpcId = 84301,
          Subtitle = [[
Have all the recent mission briefings, combat plans, logistical documents, and loss reports been organised?
Good. Then let's also finalise the external campaign slogans, domestic case analyses, routine reports to the Emperor, and the test data for the new weapons from Spathatoi today. These are part of our job, not an extra burden.]],
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_05"
        },
        [90100000] = {
          ContentES = "Siento que el tiempo pasa volando cuando solo os miro... Ojalá el tiempo no transcurriera tan rápido.",
          DialogueId = 90100000,
          GUID = "E18E4F69",
          SpeakNpcId = 85301,
          Subtitle = "I feel like time flies when I do nothing but watch you guys... I wish time wouldn't go so fast.",
          VoiceName = "voice/$Locale$/char/Saiqi/vo_idle"
        },
        [90100001] = {
          ContentES = "¡Genial! Sigo aquí hoy. Y tú también...",
          DialogueId = 90100001,
          GUID = "E18E4F6A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextOptions = {
            [1] = 901000011,
            [2] = 901000012,
            [3] = 901000013,
            [4] = 901000014,
            [5] = 901000015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85301,
          Subtitle = "Such a relief — I'm still here today. And so are you...",
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90100002] = {
          Content = "聊点别的",
          DialogueId = 90100002,
          GUID = "90100002.0",
          NextDialogue = 90100001,
          Subtitle = "Let's talk about something else"
        },
        [90100003] = {
          Content = "再见",
          DialogueId = 90100003,
          GUID = "90100003.0",
          Subtitle = "Goodbye"
        },
        [90100101] = {
          ContentES = "¡Gracias! De hecho, los Charons somos bastante resistentes al frío, así que no necesitamos abrigos pesados y caros.",
          DialogueId = 90100101,
          GUID = "E18E5FD2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100103,
          SpeakNpcId = 85301,
          Subtitle = "Thank you! Actually, we Charons are quite resilient to the cold, so there's no need for expensive, heavy coats.",
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_1"
        },
        [90100103] = {
          ContentES = "Mi mamá hizo este vestido, pero yo elegí el color -este verde vibrante- y también los patrones de las mariposas. Quedaría genial en un lugar cálido, como el sur.",
          DialogueId = 90100103,
          GUID = "E18E6026",
          NextDialogue = 90100104,
          SpeakNpcId = 85301,
          Subtitle = "My mom made this dress, but I chose the colour — this vibrant green — and the butterfly details too. They'd look right at home somewhere warm, like the south.",
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_2"
        },
        [90100104] = {
          ContentES = "Así es. Las mariposas son un detalle muy bonito, te quedan perfectamente.",
          DialogueId = 90100104,
          GUID = "E18E6050",
          NextDialogue = 90100105,
          SpeakNpcId = 100001,
          Subtitle = "I see. The butterflies are a nice touch — they suit you perfectly."
        },
        [90100105] = {
          ContentES = "¿De verdad? ¡Qué bien! De hecho, solo he visto mariposas azules en los alrededores del Lago Helado. Me encantaría ver algún día qué otros colores de las mariposas existen.",
          DialogueId = 90100105,
          GUID = "E18E607A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Really? That's so nice to hear! Actually, I've only seen blue butterflies around Icelake. I'd love to see what other colours are out there someday.",
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90100201] = {
          ContentES = "Sí, siempre ha sido así durante cientos de años. Nos tratan como plagas, e incluso he sufrido acoso e insultos sin ninguna razón.",
          DialogueId = 90100201,
          GUID = "E18E703A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100203,
          SpeakNpcId = 85301,
          Subtitle = "Yeah, it's been that way for ages. We're treated like pests and I've faced harassment and insults for no reason.",
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_1"
        },
        [90100203] = {
          ContentES = "¿Será porque los Solas temen lo que los Charons pueden hacer?",
          DialogueId = 90100203,
          GUID = "E18E708E",
          NextDialogue = 90100204,
          SpeakNpcId = 100001,
          Subtitle = "Is it because Solas fear what Charons can do?"
        },
        [90100204] = {
          ContentES = "Probablemente. Dicen que “La magia es la raíz de todo mal”. Los libros de historia afirman que nuestros ancestros la usaron para gobernar a los Solas hace más de mil años, cometiendo actos terribles.",
          DialogueId = 90100204,
          GUID = "E18E70B8",
          NextDialogue = 90100205,
          SpeakNpcId = 85301,
          Subtitle = "Probably. They say \"Magic is the root of all evil.\" History books claim our ancestors used it to rule over Solas more than a thousand years ago, committing terrible acts.",
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_2"
        },
        [90100205] = {
          ContentES = "Sinceramente, me resulta difícil imaginar algo así... Los Charons que conozco tienen tanto miedo de los Solas que ni siquiera se atreven a hablar en su presencia, y mucho menos a usar magia.",
          DialogueId = 90100205,
          GUID = "E18E70E2",
          NextDialogue = 90100206,
          SpeakNpcId = 85301,
          Subtitle = "Honestly, I can hardly imagine that... The Charons I know are too terrified of Solas to even speak up around them, let alone use magic.",
          TalkActionId = {
            [1] = "85301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_3"
        },
        [90100206] = {
          ContentES = "Además, la magia de la mayoría de los Charons es bastante simple: solo sirve para cosas sencillas como encender la chimenea o congelar los alimentos.",
          DialogueId = 90100206,
          GUID = "E18E710C",
          NextDialogue = 90100207,
          SpeakNpcId = 85301,
          Subtitle = "And Most Charon magic is quite ordinary — just good for simple things like lighting fireplaces or freezing food.",
          TalkActionId = {
            [1] = "85301:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_4"
        },
        [90100207] = {
          ContentES = "¿Te gustaría volver a aquellos tiempos, cuando los Charons gobernaban a los Solas?",
          DialogueId = 90100207,
          GUID = "E18E7136",
          NextDialogue = 90100208,
          SpeakNpcId = 100001,
          Subtitle = "Would you wish to go back to those times — when Charons ruled over Solas?",
          TalkActionId = {
            [1] = "85301:Talk01_End"
          }
        },
        [90100208] = {
          ContentES = "En absoluto. ¿Por qué uno tiene que gobernar al otro? ¿Por qué los Charons y los Solas no pueden vivir en paz simplemente?",
          DialogueId = 90100208,
          GUID = "E18E7160",
          NextDialogue = 90100209,
          SpeakNpcId = 85301,
          Subtitle = "Not at all. Why must one rule over the other? Why can't Charons and Solas just live in peace?",
          TalkActionId = {
            [1] = "85301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_5"
        },
        [90100209] = {
          ContentES = "Lo único que deseo es que... cuando llegue la primavera, todos podamos salir juntos a disfrutar de las flores. Con eso me bastaría.",
          DialogueId = 90100209,
          GUID = "E18E718A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "All I wish for is that when spring comes, everyone can go out together to enjoy all kinds of flowers. That would be enough for me.",
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90100301] = {
          ContentES = "Ah, seguramente son de mi nuevo proyecto de jardinería. El patio de la Casa de Hypnos parecía un poco pelado con tan pocos árboles. Así que yo quería plantar algunas flores blancas ahí...",
          DialogueId = 90100301,
          GUID = "E18E80A2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100303,
          SpeakNpcId = 85301,
          Subtitle = "Ah, that might be from my new gardening project. The courtyard at the Hypnos' House looked a bit barren with just a few trees, so I planted some white flowers there.",
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_1"
        },
        [90100303] = {
          ContentES = "Quizás debería plantar algunas aquí también: campanitas, anémonas, drías blancas... ¿Cuál se adaptaría mejor a este lugar?",
          DialogueId = 90100303,
          GUID = "E18E80F6",
          NextDialogue = 90100304,
          SpeakNpcId = 85301,
          Subtitle = "Perhaps we should plant some here too — bellflowers, windflowers, white dryas... Which would suit this place best?",
          TalkActionId = {
            [1] = "85301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_2"
        },
        [90100304] = {
          ContentES = "¿Por qué no preguntas a los demás y recopilas sus opiniones?",
          DialogueId = 90100304,
          GUID = "E18E8120",
          NextDialogue = 90100305,
          SpeakNpcId = 100001,
          Subtitle = "Maybe you could ask around and gather everyone's thoughts on it."
        },
        [90100305] = {
          ContentES = "Tienes razón, debería ser una decisión de todos... ¡Iré a preguntar! Por cierto, ¿qué flor te gusta más entre estas? Te recogeré algunas cuando florezcan.",
          DialogueId = 90100305,
          GUID = "E18E814A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Right, it should be a group decision... I'll ask around! By the way, which flower do you like best? I'll pick some for you when they bloom.",
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90100401] = {
          ContentES = "No, he vivido aquí toda mi vida. Siempre oigo esos trenes y me pregunto a dónde irán. Me encantaría ver qué hay allí afuera.",
          DialogueId = 90100401,
          GUID = "E18E80CC",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100403,
          SpeakNpcId = 85301,
          Subtitle = "No, I've been here my whole life. I always hear those trains and wonder about the places they're heading to. I'd really love to see what's out there.",
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_1"
        },
        [90100403] = {
          ContentES = "¿Qué lugares están en tu lista de deseos?",
          DialogueId = 90100403,
          GUID = "E18E80CB",
          NextDialogue = 90100404,
          SpeakNpcId = 100001,
          Subtitle = "What places are on your wish list?",
          TalkActionId = {
            [1] = "85301:Explain02_End"
          }
        },
        [90100404] = {
          ContentES = "Mmm, me encantaría visitar la capital, para empezar. El tío Henrik me contó que los atardeceres en el Río Escarlata son impresionantes... ¡Ah! Y me encantaría visitar la Isla del Purgatorio de la que me hablabas, para sentir la brisa marina y ver si es tan salada como dijiste.",
          DialogueId = 90100404,
          GUID = "E18E910A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Mm, I'd definitely want to visit the capital, for starters; Uncle Henrik once told me the sunsets in Scarletriver are breathtaking... Oh, and I'd love to visit Purgatorio Island you told me about — to feel the sea breeze and see if it's as salty as you described!",
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90100501] = {
          ContentES = "Oh, nada, es que... Quiero miraros bien, para memorizar vuestros rostros.",
          DialogueId = 90100501,
          GUID = "E18EA172",
          NextDialogue = 90100502,
          SpeakNpcId = 85301,
          Subtitle = "Oh, it's just that... I want to take a good look at you all, to memorize your faces better.",
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_1"
        },
        [90100502] = {
          ContentES = "¿Podrías mirarme atentamente un momento? Me gustaría que me recuerdes... tal como soy ahora.",
          DialogueId = 90100502,
          GUID = "E18EA19C",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Could you maybe take a moment to look at me carefully? I'd like you to remember me... just as I am right now.",
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90100601] = {
          Content = "我听说奥特赛德先生为菲娜的生日精心准备了很久。虽然嘴上不饶人，但你其实是个很体贴的人吧？下一次菲娜生日，我可以和你们一起为她准备惊喜吗？",
          DialogueId = 90100601,
          GUID = "E18EB1DA",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_01"
        },
        [90100801] = {
          ContentES = "¿Me contarás la historia de Elysium? ¡Muchas gracias! Humm... ¿Qué tipo de flores te gustaría a cambio? ¿Dicen que deliciosas?",
          DialogueId = 90100801,
          GUID = "E18ED2AA",
          SpeakNpcId = 85301,
          Subtitle = [[
Are you gonna tell me the story of Elysium? Thank you so much! I wonder what kind of flowers you'd like in return?
Delicious ones, you say?]],
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_03"
        }
      }
    end
  },
  {
    MinKey = 90110000,
    MaxKey = 90190203,
    Loader = function()
      return {
        [90110000] = {
          ContentES = "Barrer y ventilar por la mañana, rociar alcohol fuerte por la tarde y encender incienso al anochecer para ahuyentar a los insectos, esa es la única manera de mantener una habitación limpia.",
          DialogueId = 90110000,
          GUID = "E194B809",
          SpeakNpcId = 82401,
          Subtitle = "Sweeping up and venting in the morning, spraying strong liquor in the afternoon, and lighting incense sticks at dusk to drive away insects — that's the only way to keep a room clean.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_idle"
        },
        [90110001] = {
          ContentES = "El entorno moldea el espíritu, y el cuidado consciente fortalece el cuerpo. Quizás un paseo bajo este cielo bondadoso obre maravillas en tu salud.",
          DialogueId = 90110001,
          GUID = "E194B80A",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextOptions = {
            [1] = 901100011,
            [2] = 901100012,
            [3] = 901100013,
            [4] = 901100014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82401,
          Subtitle = "One's surroundings shape the spirit, and mindful care strengthens the body. Perhaps a walk beneath these kindly skies would do wonders for your health.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_welcome",
          bForbidSkipOptions = true
        },
        [90110002] = {
          Content = "聊点别的",
          DialogueId = 90110002,
          GUID = "90110002.0",
          NextDialogue = 90110001,
          Subtitle = "Let's talk about something else"
        },
        [90110003] = {
          Content = "再见",
          DialogueId = 90110003,
          GUID = "90110003.0",
          Subtitle = "Goodbye"
        },
        [90110101] = {
          ContentES = "En efecto. No obstante, el contenido es complejo y críptico, y aún no logro comprender del todo las diferencias entre ciertos remedios. Quizás simplemente no tengo la aptitud necesaria para esta disciplina.",
          DialogueId = 90110101,
          GUID = "E194C872",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110103,
          SpeakNpcId = 82401,
          Subtitle = "Indeed. Yet, the contents are dense and cryptic, and even the distinctions between certain remedies remain elusive to me. Perhaps I simply lack the aptitude for this craft.",
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_1"
        },
        [90110103] = {
          ContentES = "¿En serio? Pensé que, para una sanadora, entender estas cosas sería pan comido.",
          DialogueId = 90110103,
          GUID = "E194C8C6",
          NextDialogue = 90110104,
          SpeakNpcId = 100001,
          Subtitle = "Really? I thought for a healer, grasping this kind of stuff would be a walk in the park."
        },
        [90110104] = {
          ContentES = "En mi época... la medicina no era el método de curación más popular. La gente generalmente practicaba un arte curativo milagroso llamado “Zhuyou” para ahuyentar las enfermedades.",
          DialogueId = 90110104,
          GUID = "E194C8F0",
          NextDialogue = 90110105,
          SpeakNpcId = 82401,
          Subtitle = "In my time... medication was not the primary means of healing. People practised a miraculous healing art called \"Zhuyou\" to ward off illness.",
          TalkActionId = {
            [1] = "82401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_2"
        },
        [90110105] = {
          ContentES = "Aunque este método podía traer sanación y paz, exigía el sacrificio de la fuerza vital del sanador. Ninguno de nosotros vivió para ver la vejez. Derramar nuestra esencia hasta morir era el único camino que conocíamos.",
          DialogueId = 90110105,
          GUID = "E194C8F1",
          NextDialogue = 90110106,
          SpeakNpcId = 82401,
          Subtitle = "While this method could bring healing and peace, it demanded the sacrifice of a healer's very life force. None of us lived to see old age — pouring out our essence unto death was the only path we knew.",
          TalkActionId = {
            [1] = "82401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_3"
        },
        [90110106] = {
          ContentES = "... Es una carga muy pesada de llevar.",
          DialogueId = 90110106,
          GUID = "E194C8F2",
          NextDialogue = 90110107,
          SpeakNpcId = 100001,
          Subtitle = "...That's such a heavy burden to bear."
        },
        [90110107] = {
          ContentES = "El Pabellón de lo Efímero hoy no es más que una reliquia del tiempo, pero el camino de sanar y salvar vidas nunca ha carecido de sucesores. Incluso bajo la carga más pesada, siempre habrá quienes avancen con una determinación inquebrantable.",
          DialogueId = 90110107,
          GUID = "E194C8F3",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "The Hall of Ephemerality may now be but a relic of time, yet the path of healing and saving lives has never lacked successors. Even under the heaviest burdens, there will always be those who press forward with unwavering resolve.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90110201] = {
          ContentES = "Sueño con un mundo sin enfermedades incurables.",
          DialogueId = 90110201,
          GUID = "E194D8DA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110203,
          SpeakNpcId = 82401,
          Subtitle = "I dream of a world without incurable maladies.",
          TalkActionId = {
            [1] = "82401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_1"
        },
        [90110203] = {
          ContentES = "Es un sueño bastante grandioso...",
          DialogueId = 90110203,
          GUID = "E194D92E",
          NextDialogue = 90110204,
          SpeakNpcId = 100001,
          Subtitle = "That's quite a grand dream...",
          TalkActionId = {
            [1] = "82401:Explain02_End"
          }
        },
        [90110204] = {
          ContentES = "Suena como una pura fantasía, ¿verdad? Sin embargo, incluso sin los milagros de la magia curativa, el propósito de un sanador no cambia.*risita suave* Debo admitir que, viniendo de alguien que aún tiene dificultades para comprender los libros médicos como yo, estas palabras pueden sonarles absurdas.",
          DialogueId = 90110204,
          GUID = "E194D958",
          NextDialogue = 90110205,
          SpeakNpcId = 82401,
          Subtitle = "It rings as but a fanciful daydream, doesn't it? Yet, even without the miracles of healing magic, the purpose of a healer remains unchanged. I must admit, coming from someone who still struggles to fully grasp medical texts, such a speech must sound absurd.",
          TalkActionId = {
            [1] = "82401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_2"
        },
        [90110205] = {
          ContentES = "Pero... seguiré pisando este camino, no solo por el bien de los demás o por el legado del Pabellón de lo Efímero, sino también por mi propia realización.",
          DialogueId = 90110205,
          GUID = "E194D982",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "But... I'll continue treading this path — not merely for the sake of others or the legacy of the Hall of Ephemerality, but for my own fulfilment as well.",
          TalkActionId = {
            [1] = "82401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90110301] = {
          ContentES = "Es un lugar para curar y salvar vidas.",
          DialogueId = 90110301,
          GUID = "E194E942",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110303,
          SpeakNpcId = 82401,
          Subtitle = "It's a place for healing and saving lives.",
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_1"
        },
        [90110303] = {
          ContentES = "¿Me puedes contar más sobre él?",
          DialogueId = 90110303,
          GUID = "E194E944",
          NextDialogue = 90110304,
          SpeakNpcId = 100001,
          Subtitle = "Can you tell me more about it?"
        },
        [90110304] = {
          ContentES = "Esa es la única misión del Pabellón de lo Efímero. Si hubiera que hablar de otros aspectos... cada sanador que se formó en sus muros plantó un albaricoquero el primer día de su práctica. Sin embargo, con el tiempo, las tormentas y la decadencia se llevaron a muchos. Ahora, queda menos de la mitad.",
          DialogueId = 90110304,
          GUID = "E194E943",
          NextDialogue = 90110305,
          SpeakNpcId = 82401,
          Subtitle = "The Hall's mission is singular — to heal, and to heal alone. If one were to speak of other aspects... every healer who trained within its walls planted an apricot tree on the first day of their practice. Yet, as time passed, storms and decay claimed many. Now, fewer than half remain.",
          TalkActionId = {
            [1] = "82401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_2"
        },
        [90110305] = {
          ContentES = "Al despertar de un largo sueño, busqué el albaricoquero que planté en mi juventud. Tristemente, el árbol se había marchitado hasta convertirse en madera estéril, y ni siquiera esta cálida primavera pudo incitar nuevos brotes de sus ramas.",
          DialogueId = 90110305,
          GUID = "E194E945",
          NextDialogue = 90110306,
          SpeakNpcId = 82401,
          Subtitle = "Waking up from a long slumber, I sought the apricot tree I once planted in my youth. Sadly, the tree had withered to barren wood, and not even this warm spring could coax new buds from its branches.",
          TalkActionId = {
            [1] = "82401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_3"
        },
        [90110306] = {
          ContentES = "La vida pasa volando, como un caballo galopando por un estrecho desfiladero, una chispa que salta de un pedernal, o un fantasma que vaga en un sueño. ¿Cuándo puede encontrar el camino en medio de tanta efemeralidad? El pasado se aleja cada vez más, mientras las esperanzas de reparación se desvanecen como la niebla matutina.",
          DialogueId = 90110306,
          GUID = "E194E946",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "Life rushes by, like a fleeting horse through a narrow chasm, a spark struck from flint, or a phantom wandering in a dream. How does one find their way back through such transience? The past slips further from reach, while hopes to amend it vanish like morning mist.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90110401] = {
          ContentES = "La muerte es como una lámpara que se apaga. Todas las huellas desaparecen, todas las voces se desvanecen. Esa profunda quietud aislada puede consumir hasta el último rastro de esperanza y posibilidad. Si estuviera en mi poder, evitaría que ningún paciente cayera en tal abismo.",
          DialogueId = 90110401,
          GUID = "E194F9AA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110403,
          SpeakNpcId = 82401,
          Subtitle = "Death is like a lamp extinguished — all traces vanish, all voices fade. That isolation, that profound stillness, consumes every glimmer of hope and possibility. If it lies within my power, I would spare any patient from falling into such an abyss.",
          TalkActionId = {
            [1] = "82401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_1"
        },
        [90110403] = {
          ContentES = "Casi suena como si lo hubieras vivido en carne propia.",
          DialogueId = 90110403,
          GUID = "E194F9FE",
          NextDialogue = 90110404,
          SpeakNpcId = 100001,
          Subtitle = "It almost sounds as though you've experienced it firsthand."
        },
        [90110404] = {
          ContentES = "No te equivocas. Yo... una vez regresé del umbral de la muerte, luchando por salir de las garras de una enfermedad grave. Si tuviera que enfrentar tal prueba de nuevo, no podría decir con certeza que tomaría la misma decisión.",
          DialogueId = 90110404,
          GUID = "E194FA28",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "You're not mistaken. I... once returned from the brink of death, clawing my way back from the clutches of grave illness. Should such a trial confront me again, I cannot say with certainty that I would make the same choice.",
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90110501] = {
          ContentES = "Señor Randy, en mi humilde opinión, la apatía y la pereza también son síntomas de enfermedad. Quizás ahora esté bien, pero pueden causar problemas de salud en el futuro. ¿Qué le parece hacer un poco de ejercicios para ayudarle?",
          DialogueId = 90110501,
          GUID = "E1950A12",
          SpeakNpcId = 82401,
          Subtitle = "Mr. Randy, in my humble opinion, lethargy and laxity are no less symptoms of illness. They may not trouble you now, but they sow the seeds of future ailments. Perhaps we could engage in some light sparring? A touch of exercise might do you good.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_01"
        },
        [90110601] = {
          ContentES = "Si bien un sanador puede aliviar el sufrimiento, está fuera de su alcance desafiar el destino. Puedo ofrecerle un remedio para calmar su angustia del corazón, pero la raíz de sus problemas está fuera de mi alcance. Lo mejor es aceptar y adaptarse al paso del tiempo para encontrar el camino hacia la serenidad...",
          DialogueId = 90110601,
          GUID = "E1951A7A",
          SpeakNpcId = 82401,
          Subtitle = [[
While a healer may ease affliction, defying fate is beyond us. I can offer a remedy to cool the heart's heat, yet the root of your troubles lies beyond my grasp. It is best to accept and adapt to the flow of time to find your own path to solace...
 ]],
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_02"
        },
        [90110701] = {
          ContentES = "¿Oye a menudo que otra voz le habla? ¿Pueden oírla otros también? ¿Qué tal ha sido su descanso? ¿Hay algo que le pese en el corazón? Las aflicciones de la mente son las más difíciles de sanar, incluso con la ayuda de las técnicas de Zhuyou. Pero, como sanadora, no escatimaré esfuerzos.",
          DialogueId = 90110701,
          GUID = "E1952AE2",
          SpeakNpcId = 82401,
          Subtitle = "You often hear another voice speaking to you? Can others hear it too? How has your slumber been? Has something been weighing on your heart? The mind's afflictions are the most elusive to heal, even with the aid of Zhuyou techniques. But as a healer, I will spare no effort.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_03"
        },
        [90120000] = {
          ContentES = "Vamos a descansar un poco, Filbert. Toma algo de grano y frutos secos, y unas cuantas flores de aperitivo. Si no tienes hambre, las engancharé en mi sombrero por ahora.",
          DialogueId = 90120000,
          GUID = "E19B20A9",
          SpeakNpcId = 85101,
          Subtitle = "Let's take some rest, Filbert. Have some grains and nuts, and a few flowers for snacks. If you're full, I'll pin them to my hat for now.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_idle"
        },
        [90120001] = {
          ContentES = "El sol brilla mucho y los pajaritos están piando de alegría después de un buen atracón. ¿Tú también tienes hambre? ¿Quieres comer algo también?",
          DialogueId = 90120001,
          GUID = "E19B20AA",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextOptions = {
            [1] = 901200011,
            [2] = 901200012,
            [3] = 901200013,
            [4] = 901200014,
            [5] = 901200015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85101,
          Subtitle = "The sun is shining bright, and the little birdies are chirping with joy after a hearty meal. Are you hungry too? Wanna grab something to eat as well?",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90120002] = {
          Content = "聊点别的",
          DialogueId = 90120002,
          GUID = "90120002.0",
          NextDialogue = 90120001,
          Subtitle = "Let's talk about something else"
        },
        [90120003] = {
          Content = "再见",
          DialogueId = 90120003,
          GUID = "90120003.0",
          Subtitle = "Goodbye"
        },
        [90120101] = {
          ContentES = "¿Eh? ¿No lo sabes? El trabajo de una comisaria es asegurarse de que todos coman bien, lidiando con todo tipo de alimentos cada día.",
          DialogueId = 90120101,
          GUID = "E19B3112",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120103,
          SpeakNpcId = 85101,
          Subtitle = "Huh? You don't know? A commissary's job is to make sure everyone's well-fed, dealing with all sorts of food every day.",
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_1"
        },
        [90120103] = {
          ContentES = "Por ejemplo, yo recojo todo tipo de alimentos de la naturaleza en el campo, Filbert los trae de vuelta y luego el Señor Barba de la panadería, los convierte en comida deliciosa para todos.",
          DialogueId = 90120103,
          GUID = "E19B3166",
          NextDialogue = 90120104,
          SpeakNpcId = 85101,
          Subtitle = "For example, I go out to gather all kinds of ingredients from the wild, have Filbert haul them back, and then get Mr Beard at the bakery to turn them into yummy food for everyone.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_2"
        },
        [90120104] = {
          ContentES = "Y por cierto, regatear con el Señor Barba ¡también es parte de mi trabajo! ¡Jeje!",
          DialogueId = 90120104,
          GUID = "E19B3190",
          NextDialogue = 90120105,
          SpeakNpcId = 85101,
          Subtitle = "And just so you know, haggling with Mr Beard is part of my job too! Hehe.",
          TalkActionId = {
            [1] = "85101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_3"
        },
        [90120105] = {
          ContentES = "¡Vaya! Eso suena impresionante. ¿Es igual para todos los comisarios?",
          DialogueId = 90120105,
          GUID = "E19B31BA",
          NextDialogue = 90120106,
          SpeakNpcId = 100001,
          Subtitle = "Wow! That sounds impressive. Is it the same for all commissaries?"
        },
        [90120106] = {
          ContentES = "¡Qué va! Los demás parecen ser más bien intelectuales, para ellos todo es papeleo: rellenar solicitudes y esperar a que lleguen trenes llenos de comida.",
          DialogueId = 90120106,
          GUID = "E19B31E4",
          NextDialogue = 90120107,
          SpeakNpcId = 85101,
          Subtitle = "Oh, not at all! The others seem to be brainy types; they're all about the paperwork — filling out application forms, then waiting for trains loaded with food to roll in.",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_4"
        },
        [90120107] = {
          ContentES = "Pero para un pueblo pequeño como el nuestro, ¡Filbert y yo podemos alimentar a todos! De lo contrario, quizás tenga que aprender a rellenar esos formularios. ¡Ay, no entiendo nada de eso!",
          DialogueId = 90120107,
          GUID = "E19B320E",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "But for a small town like ours, just Filbert and I can feed everyone! Otherwise, I might have to start filling out those forms too — ugh, it's all gibberish to me.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90120201] = {
          ContentES = "¿Eh? Hmm, quizás sí... Nunca lo había pensado, ¡pero Filbert solo tumba a esos malandrines, gritones y peleones! ¡Se lo merecen!",
          DialogueId = 90120201,
          GUID = "E19B417A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120203,
          SpeakNpcId = 85101,
          Subtitle = "Hmm... maybe it does? I've never really thought about it, but Filbert only knocks down those no-good, shouty, fighty troublemakers! They totally deserve it!",
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_1"
        },
        [90120203] = {
          ContentES = "Esos tipos siempre terminan con hambre después de sus peleas. Les iría mejor arando campos que blandiendo armas. Así habría menos gente que se vaya a la cama con hambre.",
          DialogueId = 90120203,
          GUID = "E19B41CE",
          NextDialogue = 90120204,
          SpeakNpcId = 85101,
          Subtitle = "Those guys always end up hungry after their brawls. They'd do more good ploughing fields than swinging weapons — that way, less people would go to bed hungry.",
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_2"
        },
        [90120204] = {
          ContentES = "Entonces, ¿seguramente odias las guerras?",
          DialogueId = 90120204,
          GUID = "E19B41F8",
          NextDialogue = 90120205,
          SpeakNpcId = 100001,
          Subtitle = "You must really hate wars, then."
        },
        [90120205] = {
          ContentES = "¡Absolutamente! Las guerras solo traen hambre, ¡son terribles! He oído que en tiempos de guerra, la gente muere de inanición... ¡es lo peor! Espero no tener que verlo jamás.",
          DialogueId = 90120205,
          GUID = "E19B4222",
          NextDialogue = 90120206,
          SpeakNpcId = 85101,
          Subtitle = "Absolutely! Fighting just leads to hunger — that's really awful! I've heard that in times of war, everyone ends up starving, which is just the worst! I hope I never have to see that.",
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_3"
        },
        [90120206] = {
          ContentES = "Si estalla una guerra, podrías montar a Filbert y embestir a esos alborotadores.",
          DialogueId = 90120206,
          GUID = "E19B424C",
          NextDialogue = 90120207,
          SpeakNpcId = 100001,
          Subtitle = "If war does break out, you could mount Filbert and ram those troublemakers.",
          TalkActionId = {
            [1] = "85101:Confident_End"
          }
        },
        [90120207] = {
          ContentES = "¡Eso es! ¡Quienquiera que cause hambre a la gente, tarde o temprano será embestido por Filbert!",
          DialogueId = 90120207,
          GUID = "E19B4276",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "Right! Anyone who makes people go hungry will sooner or later get knocked over by Filbert!",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90120301] = {
          ContentES = "¡Sí, lo es! Y ¿sabes qué? ¡Aunque haya varios arroyos de por medio, Filbert es capaz de olfatear bayas maduras y luego salimos a toda carga a buscarlas! ¡Bastante genial, ¿no crees?!",
          DialogueId = 90120301,
          GUID = "E19B51E2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120303,
          SpeakNpcId = 85101,
          Subtitle = "Yeah, she is! And you know what, even across several creeks, Filbert can sniff out ripe berries and then off we go charging! Pretty awesome, isn't she?",
          TalkActionId = {
            [1] = "85101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_1"
        },
        [90120303] = {
          ContentES = "¡Qué bueno! Entonces no hay riesgo de escasez de comida.",
          DialogueId = 90120303,
          GUID = "E19B5236",
          NextDialogue = 90120304,
          SpeakNpcId = 100001,
          Subtitle = "Awesome. No risk of food shortage then.",
          TalkActionId = {
            [1] = "85101:Talk02_End"
          }
        },
        [90120304] = {
          ContentES = "¡No te preocupes! Filbert siempre trae comida extra. ¡Así que nunca, nunca te burles de ella! Le harías daño a ella y también a mí.",
          DialogueId = 90120304,
          GUID = "E19B5260",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "No worries at all! Filbert always brings more food. So never ever make fun of her — it would hurt her feelings, and mine too.",
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90120401] = {
          ContentES = "¡Gracias! En realidad, son pantalones cortos, no es un vestido. Al comienzo fue un vestido largo y blanco, muy bonito. Luego la modista de la sastrería los convirtió en pantalones cortos para mí.",
          DialogueId = 90120401,
          GUID = "E19B624A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120403,
          SpeakNpcId = 85101,
          Subtitle = "Thank you! Actually, these are shorts, not a dress. They did start as a pretty, long, white dress; then the lady at the tailor's shop turned them into shorts for me.",
          TalkActionId = {
            [1] = "85101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_1"
        },
        [90120403] = {
          ContentES = "¿Por qué?",
          DialogueId = 90120403,
          GUID = "E19B629E",
          NextDialogue = 90120404,
          SpeakNpcId = 100001,
          Subtitle = "Why is that?",
          TalkActionId = {
            [1] = "85101:Explain01_End"
          }
        },
        [90120404] = {
          ContentES = "Es que un vestido no es lo más práctico para tanto correteo. Una vez, tropecé con el dobladillo y se me voló todo el pan que llevaba en los brazos.",
          DialogueId = 90120404,
          GUID = "E19B62C8",
          NextDialogue = 90120405,
          SpeakNpcId = 85101,
          Subtitle = "Because dresses aren't the best for all the running around I do. One time, I tripped over the hem and all the bread in my arms went flying.",
          TalkActionId = {
            [1] = "85101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_2"
        },
        [90120405] = {
          ContentES = "Pero si llega el día en que ya nadie pase hambre, ¡le pediré a la modista que me los vuelva a convertir en vestido!",
          DialogueId = 90120405,
          GUID = "E19B62F2",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "But if the day comes, when no one's starving anymore, I'll have them changed back into a dress!",
          TalkActionId = {
            [1] = "85101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90120501] = {
          ContentES = "Oh, yo estoy meditando, no distraída. Soy miembro de la Iglesia Elísea, así que intento reflexionar de vez en cuando.",
          DialogueId = 90120501,
          GUID = "E19B72B2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120503,
          SpeakNpcId = 85101,
          Subtitle = "Oh, I was meditating, not zoning out. I'm a member of the Elysian Church after all, so I do try to give some deep thought occasionally.",
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_1"
        },
        [90120503] = {
          ContentES = "¿En qué estás pensando? ¿Por qué no existe un dios de la saciedad, quizás?",
          DialogueId = 90120503,
          GUID = "E19B7306",
          NextDialogue = 90120504,
          SpeakNpcId = 100001,
          Subtitle = "What were you thinking, then? Why isn't there a god of full bellies, perhaps?"
        },
        [90120504] = {
          ContentES = "Solía preguntarme eso, pero los clérigos dijeron que era… blasfomia o algo así. Así que dejé de pensar en eso.",
          DialogueId = 90120504,
          GUID = "E19B7330",
          NextDialogue = 90120505,
          SpeakNpcId = 85101,
          Subtitle = "I used to wonder about that, but the clergy said it was... blastphomy or something. So I stopped thinking about that.",
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_2"
        },
        [90120505] = {
          ContentES = "Nunca termino de entender lo que dicen, como por ejemplo que la gula es un pecado terrible... pero parece que cuanto más alto es el estatus de alguien, más comen.",
          DialogueId = 90120505,
          GUID = "E19B735A",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "I never quite get what they say, like how gluttony is a terrible sin... but it seems like the higher someone's status, the more they eat.",
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90120601] = {
          ContentES = "¿Encontraste patatas germinadas en el basurero? ¡No las tires! ¡Las plantamos! Después de mullir la tierra y regar, ¡pronto tendremos muchas patatas para todos!",
          DialogueId = 90120601,
          GUID = "E19B831A",
          SpeakNpcId = 85101,
          Subtitle = "You found sprouting potatoes in the bin? Don't throw them away — let's plant them! With a little digging and watering, we'll have lots of potatoes for everyone soon enough!",
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_01"
        },
        [90120701] = {
          ContentES = "Siempre estás trabajando muy duro. ¿No te da hambre? ¿Por qué no te unes a la Iglesia? ¡Te prometo que te llenaré la barriga!",
          DialogueId = 90120701,
          GUID = "E19B9382",
          SpeakNpcId = 85101,
          Subtitle = "You're always working so hard. Don't you get hungry? Why not join the Church? I'm sure I'll make your tummy full!",
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_02"
        },
        [90120801] = {
          ContentES = "¡Holaaa! Oí que rezar te puede elevar el espíritu. Yo, personalmente, creo que una buena comida hace lo mismo. Pero, ¿qué funciona mejor, rezar o comer?",
          DialogueId = 90120801,
          GUID = "E19BA3EA",
          SpeakNpcId = 85101,
          Subtitle = "Helloooo! I heard that praying can make one's soul feel uplifted. Personally, I think that a good meal does the same thing. But which one works better, praying or dining?",
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_03"
        },
        [90130000] = {
          ContentES = "... No está mal. Debería tener suficiente para este mes. Pensé que ese ** Randy se quedaría con todo... Enviaré esta parte a casa y me las apañaré con el resto.",
          DialogueId = 90130000,
          GUID = "E1A18949",
          SpeakNpcId = 83101,
          Subtitle = "Not bad. I should have enough for this month. I thought that ** Randy would take it all himself. I'll send this lot home and get by with the rest.",
          VoiceName = "voice/$Locale$/char/Linen/vo_idle"
        },
        [90130001] = {
          ContentES = "¿Necesitas algo? Suéltalo rápido. Tengo una misión que terminar.",
          DialogueId = 90130001,
          GUID = "E1A1894A",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextOptions = {
            [1] = 901300011,
            [2] = 901300012,
            [3] = 901300013,
            [4] = 901300014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83101,
          Subtitle = "Need anything? Spit it out quickly. I've got a mission to finish.",
          VoiceName = "voice/$Locale$/char/Linen/vo_welcome",
          bForbidSkipOptions = true
        },
        [90130002] = {
          Content = "聊点别的",
          DialogueId = 90130002,
          GUID = "90130002.0",
          NextDialogue = 90130001,
          Subtitle = "Let's talk about something else"
        },
        [90130003] = {
          Content = "再见",
          DialogueId = 90130003,
          GUID = "90130003.0",
          Subtitle = "Goodbye"
        },
        [90130101] = {
          ContentES = "¿Sibylle? Es la Jefa de la 13.ª Legión.",
          DialogueId = 90130101,
          GUID = "E1A199B2",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130103,
          SpeakNpcId = 83101,
          Subtitle = "Sibylle? She's the chief of the 13th Legion.",
          TalkActionId = {
            [1] = "83101:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_01_1"
        },
        [90130103] = {
          ContentES = "¿Algo más?",
          DialogueId = 90130103,
          GUID = "E1A199B3",
          NextDialogue = 90130104,
          SpeakNpcId = 100001,
          Subtitle = "Anything else?",
          TalkActionId = {
            [1] = "83101:Talk03_End"
          }
        },
        [90130104] = {
          ContentES = "Bah, ¿cómo puedo saber más? Ella manda, yo cumplo. Eso es todo.",
          DialogueId = 90130104,
          GUID = "E1A199B4",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "Ugh, what do you expect me to know? She calls the shots, I do the work. That's all.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90130201] = {
          ContentES = "¿Consejos? Mi único consejo es que no hay problema que un buen puñetazo no pueda arreglar. Si eso no funciona, tira otro.",
          DialogueId = 90130201,
          GUID = "E1A1AA1A",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130203,
          SpeakNpcId = 83101,
          Subtitle = "Tips? The only tip I have is there's no problem a good punch can't fix. If that doesn't work, throw another.",
          TalkActionId = {
            [1] = "83101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_1"
        },
        [90130203] = {
          ContentES = "¿Y si dos puñetazos tampoco lo resuelven?",
          DialogueId = 90130203,
          GUID = "E1A1AA6E",
          NextDialogue = 90130204,
          SpeakNpcId = 100001,
          Subtitle = "What if two punches don't sort it out either?"
        },
        [90130204] = {
          ContentES = "Entonces, una bala suele ser la solución.",
          DialogueId = 90130204,
          GUID = "E1A1AA98",
          NextDialogue = 90130205,
          SpeakNpcId = 83101,
          Subtitle = "Then a bullet usually does the trick.",
          TalkActionId = {
            [1] = "83101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_2"
        },
        [90130205] = {
          ContentES = "Pero he oído que hay gente que puede encajar una bala y seguir en pie.",
          DialogueId = 90130205,
          GUID = "E1A1AAC2",
          NextDialogue = 90130206,
          SpeakNpcId = 100001,
          Subtitle = "But I heard some people can take a bullet and still stand."
        },
        [90130206] = {
          ContentES = "Oh, es solo una expresión. Lo que quiero decir es: sé lo más duro y fuerte que puedas, y eso es todo lo que necesitas. Sigue con tus tonterías y tu cara será la próxima en recibir esos puñetazos.",
          DialogueId = 90130206,
          GUID = "E1A1AAEC",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "It's just a figure of speech. My point is: be as tough and strong as you can be, and that's all you need. Keep nitpicking, and your face will be getting those punches next.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90130301] = {
          ContentES = "Vi una pistola buenísima el otro día... Olvídalo, no voy a dejar de comer para comprarla. Además, la vieja me queda mejor en la mano.",
          DialogueId = 90130301,
          GUID = "E1A1BA82",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130303,
          SpeakNpcId = 83101,
          Subtitle = "Saw a really nice gun the other day... Forget it, can't skimp on food just to buy it. The old one feels better in my hands anyway.",
          TalkActionId = {
            [1] = "83101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_03_1"
        },
        [90130303] = {
          ContentES = "Si te gusta mucho, quizás pueda conseguir una para ti.",
          DialogueId = 90130303,
          GUID = "E1A1BAD6",
          NextDialogue = 90130304,
          SpeakNpcId = 100001,
          Subtitle = "If you really like it, maybe I can get one for you.",
          TalkActionId = {
            [1] = "83101:Think_End"
          }
        },
        [90130304] = {
          ContentES = "¿De verdad?... Pero, estás tan tieso como yo... Pues, te agradezco, pero no vayas a romper tu alcancía por mí. No quiero deberle nada a nadie.",
          DialogueId = 90130304,
          GUID = "E1A1BB00",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "Really?... Nah, you look as broke as me... I appreciate the gesture, but don't go break a piggy bank for me. I don't wanna owe anyone anything.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90130401] = {
          ContentES = "No hay trabajo, no hay comida. ¿Qué parte no entiendes?",
          DialogueId = 90130401,
          GUID = "E1A1CAEA",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130403,
          SpeakNpcId = 83101,
          Subtitle = "No work, no food. What don't you get?",
          TalkActionId = {
            [1] = "83101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_04_1"
        },
        [90130403] = {
          ContentES = "Estaría bien tener un equilibrio, ¿verdad?",
          DialogueId = 90130403,
          GUID = "E1A1CB3E",
          NextDialogue = 90130404,
          SpeakNpcId = 100001,
          Subtitle = "But it's also important to find a balance, right?"
        },
        [90130404] = {
          ContentES = "Estoy de acuerdo, pero mis clientes no piensan así. Siempre me están acosando con: ¿Ya está listo el trabajo? ¡Date prisa! ¡Uf! i no tuviera que alimentar a mi familia, les partiría la cara de imbéciles.",
          DialogueId = 90130404,
          GUID = "E1A1CB68",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "Balance would be great, but my clients don't see it that way — always hounding me, \"Is the job done yet? Hurry up!\" Ugh, if I didn't have a family to feed, I'd punch them in their stupid faces.",
          TalkActionId = {
            [1] = "83101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90130501] = {
          ContentES = "La próxima vez, ve directo al grano, ¿quieres? Tanto balbuceo innecesario me está sacando de quicio.",
          DialogueId = 90130501,
          GUID = "E1A1DB52",
          SpeakNpcId = 83101,
          Subtitle = "Keep it short and cut to the chase next time, will you? All this unnecessary mumbling is getting on my nerves.",
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_01"
        },
        [90130601] = {
          ContentES = "... Buen día, comandante.",
          DialogueId = 90130601,
          GUID = "E1A1EBBA",
          SpeakNpcId = 83101,
          Subtitle = "Good day, ma'am...",
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_02"
        },
        [90130701] = {
          ContentES = "Eres un soldado de primera. Eso es todo lo que tengo que decir. Y... asegúrate de cuidarte en tu tiempo libre. ¡Apúrate! Ya oíste bastante, ¡así que lárgate!",
          DialogueId = 90130701,
          GUID = "E1A1FC22",
          SpeakNpcId = 83101,
          Subtitle = "You're a top soldier. That's all I've got to say. Also... make sure you look after yourself in your downtime. Chop-chop, you've heard enough, now get out of here.",
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_03"
        },
        [90150000] = {
          ContentES = "♪ Qué casita tan pequeña, tan pequeña... Se esconde entre el verdor de las copas de los árboles, entre los ríos dorados... Mira esa chimenea, las brasas crepitan... Sosteniendo el soldadito de plomo recién reparado por papá, escuchando a mamá cantar una nana... Duérmete...",
          DialogueId = 90150000,
          GUID = "E1AE5A8B",
          SpeakNpcId = 81801,
          Subtitle = "♪ What a tiny, tiny, little home... It rests in and hides in the treetops; and the magical golden river flow... Do you see that stove? The embers crackle, crackle... Papa making a toy shining so bright, and Mama humming a lullaby... Good night~",
          VoiceName = "voice/$Locale$/char/Feina/vo_idle"
        },
        [90150001] = {
          ContentES = "... Ah... eres tú. Hola, ¿cómo estás?",
          DialogueId = 90150001,
          GUID = "E1AE5A8A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextOptions = {
            [1] = 901500011,
            [2] = 901500012,
            [3] = 901500013,
            [4] = 901500014,
            [5] = 901500015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81801,
          Subtitle = "...Ah, it's you. Hello, how are you?",
          VoiceName = "voice/$Locale$/char/Feina/vo_welcome",
          bForbidSkipOptions = true
        },
        [90150002] = {
          Content = "聊点别的",
          DialogueId = 90150002,
          GUID = "90150002.0",
          NextDialogue = 90150001,
          Subtitle = "Let's talk about something else"
        },
        [90150003] = {
          Content = "再见",
          DialogueId = 90150003,
          GUID = "90150003.0",
          Subtitle = "Goodbye"
        },
        [90150101] = {
          ContentES = "Hmm, tengo una pregunta, si existe un dulce que me hiciera crecer alta...",
          DialogueId = 90150101,
          GUID = "E1AE6AF2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150103,
          SpeakNpcId = 81801,
          Subtitle = "Um, I was wondering... if there were a candy that could make me grow very tall...",
          TalkActionId = {
            [1] = "81801:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_1"
        },
        [90150103] = {
          ContentES = "Después de comer ese dulce, ¿podría crecer tan alta que pudiera ver por encima de las nubes e incluso tocar las estrellas?",
          DialogueId = 90150103,
          GUID = "E1AE6B46",
          NextDialogue = 90150104,
          SpeakNpcId = 81801,
          Subtitle = "So tall that I could see above the clouds and even touch the stars!",
          TalkActionId = {
            [1] = "81801:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_2"
        },
        [90150104] = {
          ContentES = "Pero, qué pasaría si te pisara sin querer, posiblemente me aplastaría como una tortilla...",
          DialogueId = 90150104,
          GUID = "E1AE6B70",
          NextDialogue = 90150105,
          SpeakNpcId = 100001,
          Subtitle = "But what if you accidentally stepped on me and flattened me like a pancake..."
        },
        [90150105] = {
          ContentES = "¡Seguramente que no, prometo caminar con mucho cuidado! Bueno... si estás muy preocupada, puedes posarte en mi mano y damos un paseo. ¿Qué te parece?",
          DialogueId = 90150105,
          GUID = "E1AE6B9A",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "I'd walk carefully, I promise! Well... if you're really worried, you could perch on my hand and we'll go for a spin. What do you think?",
          TalkActionId = {
            [1] = "81801:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90150201] = {
          ContentES = "Tengo un gran cofre de cristal lleno de nieve suave, como la que cae fuera de mi ventana, y algodón del azúcar blanco como la nieve. También me gustaría meter las nubes tan suaves como eso algodón de azúcar y las brisas tan cálidas como esas nubes...",
          DialogueId = 90150201,
          GUID = "E1AE7B5A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150203,
          SpeakNpcId = 81801,
          Subtitle = "I have a big glass chest filled with the soft snow from outside my window and marshmallows as white as the snow. I'd also like to put in clouds as fluffy as those marshmallows, and breezes as warm as those clouds...",
          TalkActionId = {
            [1] = "81801:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_1"
        },
        [90150203] = {
          ContentES = "Y también vuestras risas y carcajadas, todas se meten en ese cofre~",
          DialogueId = 90150203,
          GUID = "E1AE7BAE",
          NextDialogue = 90150204,
          SpeakNpcId = 81801,
          Subtitle = "And our giggles and chuckles in there too, every single one~",
          TalkActionId = {
            [1] = "81801:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_2"
        },
        [90150204] = {
          ContentES = "¡Qué bueno! Debe ser maravilloso estar allí dentro.",
          DialogueId = 90150204,
          GUID = "E1AE7BD8",
          NextDialogue = 90150205,
          SpeakNpcId = 100001,
          Subtitle = "Wow... it must be heavenly to nestle inside."
        },
        [90150205] = {
          ContentES = "Hum... si puedes comer uno de esos dulces que te hacen encoger, podrías entrar. Pero todo es blanco allí, así que ten cuidado de no perderte.",
          DialogueId = 90150205,
          GUID = "E1AE7C02",
          NextDialogue = 90150206,
          SpeakNpcId = 81801,
          Subtitle = "Well... if you nibble one of those candies that shrinks you down tiny, you could get in for a visit. But everything's white in there, so be careful not to wander off and lose your way.",
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_3"
        },
        [90150206] = {
          ContentES = "Si me pierdo, ¿Fina vendrá a buscarme?",
          DialogueId = 90150206,
          GUID = "E1AE7C2C",
          NextDialogue = 90150207,
          SpeakNpcId = 100001,
          Subtitle = "If I do get lost in there, will Fina come to find me?",
          TalkActionId = {
            [1] = "81801:Think_Start"
          }
        },
        [90150207] = {
          ContentES = "Mmm... déjame pensar... Si te pierdes, esparciré un sendero de migas de pan para ti... ¡Síguelo, y encontrarás la salida!",
          DialogueId = 90150207,
          GUID = "E1AE7C56",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "Mmm... If you get lost, I'll scatter breadcrumbs in a trail for you... Follow them and you'll find the way out!",
          TalkActionId = {
            [1] = "81801:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90150301] = {
          ContentES = "¡Mmm...! En mi sueño, vi un ruiseñor con plumas blancas, que un momento descansaba en mi mano y al siguiente jugaba a las escondidas conmigo por la casa... Hmm, ¿fui yo quien soñó, o acaso él soñó conmigo?",
          DialogueId = 90150301,
          GUID = "E1AE8BC2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150303,
          SpeakNpcId = 81801,
          Subtitle = "Mm-hmm! I dreamed of a nightingale, pure as driven snow, resting on my hand one moment, and playing hide-and-seek with me the next... Hmm, was it me who dreamed, or did it dream of me, I wonder?",
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_1"
        },
        [90150303] = {
          ContentES = "¿Quizás ambos soñaron en un mismo mundo de sueño?",
          DialogueId = 90150303,
          GUID = "E1AE8C16",
          NextDialogue = 90150304,
          SpeakNpcId = 100001,
          Subtitle = "Perhaps you both visited the same dreamland."
        },
        [90150304] = {
          ContentES = "¡Quizás tengas razón! Tal vez sea un mundo mágico donde todos los niños y animalitos que duermen puedan jugar juntos. Hmm... ¿con quién me encontraré en mi próximo sueño? ¿El Búho Sabio, la Señorita Canario o el Señor Conejo?",
          DialogueId = 90150304,
          GUID = "E1AE8C40",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "You might be right! Maybe it's a wonderland where all the sleeping children and little animals can play together. Hmm... I wonder who I'll meet in my next dream — Owl the Wise, Miss Canary, or Sir Rabbit?",
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90150401] = {
          ContentES = "Antes tenía una mamá y dos papás. Pero ya no están...",
          DialogueId = 90150401,
          GUID = "E1AE9C2A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150402,
          SpeakNpcId = 81801,
          Subtitle = "I used to have a mum and two dads. But they've all gone...",
          TalkActionId = {
            [1] = "81801:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_1"
        },
        [90150402] = {
          ContentES = "El primer papá se fue a una tierra lejana con mamá. Y el segundo... también se fue a una tierra lejana... Yo lo llevé allí.",
          DialogueId = 90150402,
          GUID = "E1AE9C54",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "The first dad went to a faraway land with mum. And the second one... he's in that faraway land too... I sent him there.",
          TalkActionId = {
            [1] = "81801:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90150501] = {
          ContentES = "Él es el mejor mago, con la voz más suave y con el corazón más bondadoso de todo el mundo...",
          DialogueId = 90150501,
          GUID = "E1AEAC92",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150503,
          SpeakNpcId = 81801,
          Subtitle = "He's the greatest magician, with the most soothing voice and the gentlest soul in the world...",
          TalkActionId = {
            [1] = "81801:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_1"
        },
        [90150503] = {
          ContentES = "¿?",
          DialogueId = 90150503,
          GUID = "E1AEACE6",
          NextDialogue = 90150504,
          SpeakNpcId = 100001,
          Subtitle = "?",
          TalkActionId = {
            [1] = "81801:Explain02_End"
          }
        },
        [90150504] = {
          ContentES = "Eh, ¿qué ocurre? Pareces muy confundida.",
          DialogueId = 90150504,
          GUID = "E1AEAD10",
          NextDialogue = 90150505,
          SpeakNpcId = 81801,
          Subtitle = "Er, what's wrong? You look very confused.",
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_2"
        },
        [90150505] = {
          ContentES = "¡Este no es el Outsider que yo conozco!",
          DialogueId = 90150505,
          GUID = "E1AEAD3A",
          NextDialogue = 90150506,
          SpeakNpcId = 100001,
          Subtitle = "This is so not the Outsider I know!"
        },
        [90150506] = {
          ContentES = "¿Eh...? ¿Quieres decir que él no es amable ni suave contigo? Lo siento mucho... ¡Le daré un golpecito en la cabeza y le pediré que sea más amable contigo!",
          DialogueId = 90150506,
          GUID = "E1AEAD64",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "Huh...? You mean he's not kind or gentle to you? I'm so sorry... I'll give him a little tap on his head and ask him to be nicer!",
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90150601] = {
          ContentES = "Prométeme que nunca, jamás, jamás... irás a ese lugar tan aterrador lleno de magos malvados, ¿vale?",
          DialogueId = 90150601,
          GUID = "E1AEBCFA",
          SpeakNpcId = 81801,
          Subtitle = "Promise me that you'll never, ever, ever... go to that scary place with lots and lots of bad sorcerers, okay?",
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_01"
        },
        [90150701] = {
          ContentES = "¿Qué es eso? ¿Es tu mascota, Señorita Hámster? ¡Increíble! ¡Seguramente puede llevarte volando por encima de las murallas de los castillos!",
          DialogueId = 90150701,
          GUID = "E1AECD62",
          SpeakNpcId = 81801,
          Subtitle = "What's that? Is it your elf pet, Miss Hamster? Wow, unbelievable... It must be able to carry you as it flies over the walls of castles.",
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_02"
        },
        [90150801] = {
          ContentES = "Señorita Leonisa, ¿estás intentando despertar al hada dormida dentro de la espada gigante? Quizás necesites recitar muchos conjuros, como: ¡Oh, aquel que despertó la sagrada espada Samael será destinado a ser rey de Elysium!",
          DialogueId = 90150801,
          GUID = "E1AEDDCA",
          SpeakNpcId = 81801,
          Subtitle = "Miss Lioness, are you trying to wake up the fairy inside the giant sword? Perhaps you need to chant a lot of incantations, like, \"O chosen one who awoke the sacred greatsword Samael, destined to be the king of Elysium!\"",
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_03"
        },
        [90160000] = {
          ContentES = "Es muy bueno tener tranquilidad y un lugar al que me sienta apegado después de tantos años.",
          DialogueId = 90160000,
          GUID = "E1B4C329",
          SpeakNpcId = 85102,
          Subtitle = "It's nice having peace of mind and a place I can feel attached to after so many years.",
          VoiceName = "voice/$Locale$/char/Aote/vo_idle"
        },
        [90160001] = {
          ContentES = "¡Por fin estás! Terminé todos mis deberes y estoy agotado, pero solo he ganado un poco de dinero. ¡Uf! Sabes que hago mucho por vosotros.",
          DialogueId = 90160001,
          GUID = "E1B4C32A",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextOptions = {
            [1] = 901600011,
            [2] = 901600012,
            [3] = 901600013,
            [4] = 901600014,
            [5] = 901600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85102,
          Subtitle = "Here you are, finally! I've finished all my chores and got absolutely knackered, but I've only earned a few quid. Urgh... You know I do much for you guys.",
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_welcome",
          bForbidSkipOptions = true
        },
        [90160002] = {
          Content = "聊点别的",
          DialogueId = 90160002,
          GUID = "90160002.0",
          NextDialogue = 90160001,
          Subtitle = "Let's talk about something else"
        },
        [90160003] = {
          Content = "再见",
          DialogueId = 90160003,
          GUID = "90160003.0",
          Subtitle = "Goodbye"
        },
        [90160101] = {
          ContentES = "¿Una guía? No, la mayoría de los que se dedican a esto no son de los que se ponen a leer libros. Pero sí tengo algunas fórmulas concisas, como mi lema personal es: Dos golpes en las costillas, uno en la cabeza, así de muertos, ni el emperador los revive.",
          DialogueId = 90160101,
          GUID = "E1B4D392",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160103,
          SpeakNpcId = 85102,
          Subtitle = "A guide? No, most folks in this trade aren't the type to stick their nose in a book. But I do have a few mottoes to share, like my personal fighting mantra: \"Two hits in the ribs, one on the head; so dead even the emperor can't pull 'em back.\"",
          TalkActionId = {
            [1] = "85102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_1"
        },
        [90160103] = {
          ContentES = "Interesante, ¿tienes más?",
          DialogueId = 90160103,
          GUID = "E1B4D3E6",
          NextDialogue = 90160104,
          SpeakNpcId = 100001,
          Subtitle = "Interesting, got any more?",
          TalkActionId = {
            [1] = "85102:Confident_Start"
          }
        },
        [90160104] = {
          ContentES = "No te metas en más de lo que puedes manejar. En este trabajo, la codicia es el mayor enemigo. A veces viene de otros, pero más a menudo, viene de uno mismo.",
          DialogueId = 90160104,
          GUID = "E1B4D410",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "Don't bite off more than you can chew. In our line of work, greed is the biggest enemy — sometimes it comes from others, but more often, it comes from within.",
          TalkActionId = {
            [1] = "85102:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90160201] = {
          ContentES = "Ellos son como un incendio forestal que nunca se apaga, listo para reavivarse en cualquier momento. Por tu propia seguridad, mejor mantente alejado...",
          DialogueId = 90160201,
          GUID = "E1B4E3FA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160203,
          SpeakNpcId = 85102,
          Subtitle = "They're like a wildfire that's never fully extinguished, ready to flare up at any moment. For your own good, better keep your distance...",
          TalkActionId = {
            [1] = "85102:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_1"
        },
        [90160203] = {
          ContentES = "¿Tan serio? ¿Por qué?",
          DialogueId = 90160203,
          GUID = "E1B4E44E",
          NextDialogue = 90160204,
          SpeakNpcId = 100001,
          Subtitle = "Why? What's it to me?",
          TalkActionId = {
            [1] = "85102:Talk03_End"
          }
        },
        [90160204] = {
          ContentES = "Es que... Hemos tenido algunos pequeños encontronazos. Si alguna vez tienes que lidiar con ellos, asegúrate de que no menciones mi nombre.",
          DialogueId = 90160204,
          GUID = "E1B4E478",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "Well... let's just say we've had our little scuffles. If you ever deal with them, make sure my name doesn't come up.",
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90160301] = {
          ContentES = "Sí. ¿Me puedes traer esa venda de allá? Necesito esconderla para que Fina no se entere, de lo contrario, va a armar un escándalo.",
          DialogueId = 90160301,
          GUID = "E1B4F462",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160303,
          SpeakNpcId = 85102,
          Subtitle = "Yeah. Can you grab that bandage over there for me? I need to keep it from Fina, or she'll make a big fuss again.",
          TalkActionId = {
            [1] = "85102:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_1"
        },
        [90160303] = {
          ContentES = "Solo está preocupada por ti.",
          DialogueId = 90160303,
          GUID = "E1B4F4B6",
          NextDialogue = 90160304,
          SpeakNpcId = 100001,
          Subtitle = "She's just concerned about you.",
          TalkActionId = {
            [1] = "85102:Explain02_End"
          }
        },
        [90160304] = {
          ContentES = "Lo sé, pero las lesiones son parte del trabajo. Prefiero que no se preocupe tanto. Por favor, cúbreme si te pregunta, ¿vale? Te lo agradeceré.",
          DialogueId = 90160304,
          GUID = "E1B4F4E0",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "I know, but injuries are part of the job. I'd rather she not worry so much. Cover for me if she asks, will you? I owe you one.",
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90160401] = {
          ContentES = "Oh. ¿Quieres probar estos bichitos? No te fijes en la apariencia. Solo quítales la cabeza, serán crujientes como galletas, con un ligero sabor a carne en la boca...",
          DialogueId = 90160401,
          GUID = "E1B504CA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160403,
          SpeakNpcId = 85102,
          Subtitle = "Oh, would you like some? Don't mind their looks — just pop off the head, and they're crunchy like cookies, even with a hint of meaty aftertaste...",
          TalkActionId = {
            [1] = "85102:Give"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_1"
        },
        [90160403] = {
          ContentES = "(Se da la vuelta y corre.)",
          DialogueId = 90160403,
          GUID = "E1B5051E",
          NextDialogue = 90160404,
          SpeakNpcId = 100001,
          Subtitle = "(Turn around and run)"
        },
        [90160404] = {
          ContentES = "¿A dónde vas? ¡Esto es un conocimiento útil para sobrevivir!... Cuando te pierdas en la naturaleza sin comida, estos bichitos serán una fuente de energía más valiosa y podrán salvarte la vida.",
          DialogueId = 90160404,
          GUID = "E1B50548",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "Wha... where are you going!? This is vital survival wisdom... If you got lost in the wild with no food, these little critters could be a lifesaver.",
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90160501] = {
          ContentES = "Eh... un momento, ¿por qué solo tienes tantas pocas monedas? ¿Volviste a regalar tu parte del botín?",
          DialogueId = 90160501,
          GUID = "E1B51532",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160503,
          SpeakNpcId = 85102,
          Subtitle = "Wait a sec, why do you only have a few coins in your hand? Did you give away your share of the bounty again?",
          TalkActionId = {
            [1] = "85102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_1"
        },
        [90160503] = {
          ContentES = "Ellos necesitan el dinero más que yo.",
          DialogueId = 90160503,
          GUID = "E1B51586",
          NextDialogue = 90160504,
          SpeakNpcId = 100001,
          Subtitle = "They needed the money more than I did.",
          TalkActionId = {
            [1] = "85102:Confident_End"
          }
        },
        [90160504] = {
          ContentES = "Pero... Ay, no importa, eres así, siempre pensando en los demás. Avísame si necesitas dinero.",
          DialogueId = 90160504,
          GUID = "E1B515B0",
          NextDialogue = 90160505,
          SpeakNpcId = 85102,
          Subtitle = "But... Never mind, this is you, always looking out for others. Let me know if you're ever short on cash.",
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_2"
        },
        [90160505] = {
          ContentES = "De hecho, ¡ahora mismo estoy sin un céntimo!",
          DialogueId = 90160505,
          GUID = "E1B515DA",
          NextDialogue = 90160506,
          SpeakNpcId = 100001,
          Subtitle = "Actually, I'm short right now."
        },
        [90160506] = {
          ContentES = "...Te estás aprovechando, colega.",
          DialogueId = 90160506,
          GUID = "E1B51604",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "...You're milking it, buddy.",
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90160601] = {
          Content = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
          DialogueId = 90160601,
          GUID = "E1B5259A",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_01"
        },
        [90160701] = {
          ContentES = "Eres la chica que es muy amiga de {nickname}, ¿verdad?... Dicen que no te has sentido bien. Siéntate para descansar un momento.",
          DialogueId = 90160701,
          GUID = "E1B53602",
          NextDialogue = 90160702,
          SpeakNpcId = 85102,
          Subtitle = "You're the girl who's very close to , right? I heard you've been feeling unwell. Do you want to sit down and have a rest?",
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_1"
        },
        [90160702] = {
          ContentES = "Siéntete como en tu casa, cuido de mi hermana enferma todo el tiempo en casa, estoy acostumbrado a cuidar de los demás... Si tienes hambre, sed o necesitas algo, solo avísame. La amiga de {nickname} también es la mía.",
          DialogueId = 90160702,
          GUID = "E1B5362C",
          SpeakNpcId = 85102,
          Subtitle = "If you're hungry, thirsty, or need anything, just say the word. It's no bother — I look after my sickly sister back home all the time. A friend of 's is a friend of mine.",
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_2"
        },
        [90170000] = {
          ContentES = "Mmm~¡Qué día tan maravilloso! Perfecto para recoger flores, y después oleré de maravilla. ¿{nickname}, quieres acompañarme?",
          DialogueId = 90170000,
          GUID = "E1BB2BC9",
          SpeakNpcId = 83301,
          Subtitle = "Aww~ What a lovely day! Perfect for picking flowers, and I'd smell great after that~ Care to join me?",
          VoiceName = "voice/$Locale$/char/Maer/vo_idle"
        },
        [90170001] = {
          ContentES = "¡He quitado la nieve de la entrada de tu casa de camino aquí! ¿Te ha impresionado, verdad? Seguramente estás pensando en invitarme a una taza de chocolate~",
          DialogueId = 90170001,
          GUID = "E1BB2BCA",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextOptions = {
            [1] = 901700011,
            [2] = 901700012,
            [3] = 901700013,
            [4] = 901700014,
            [5] = 901700015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83301,
          Subtitle = "I've cleared the snow from your doorstep on my way here! Touched, huh? Bet you're thinking of treating me to a cup of cocoa~",
          VoiceName = "voice/$Locale$/char/Maer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90170002] = {
          Content = "聊点别的",
          DialogueId = 90170002,
          GUID = "90170002.0",
          NextDialogue = 90170001,
          Subtitle = "Let's talk about something else"
        },
        [90170003] = {
          Content = "再见",
          DialogueId = 90170003,
          GUID = "90170003.0",
          Subtitle = "Goodbye"
        },
        [90170101] = {
          ContentES = "Humm... Se trata de dar nueva vida a las cosas que la gente tira y de dar a quienes no tienen mucho una oportunidad de vivir mejor.",
          DialogueId = 90170101,
          GUID = "E1BB3C32",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170103,
          SpeakNpcId = 83301,
          Subtitle = "Well... it's about giving discarded items a new home and providing those in need with a chance at a better life.",
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_1"
        },
        [90170103] = {
          ContentES = "¿Y cómo se hace eso?",
          DialogueId = 90170103,
          GUID = "E1BB3C86",
          NextDialogue = 90170104,
          SpeakNpcId = 100001,
          Subtitle = "And how's that done?"
        },
        [90170104] = {
          ContentES = "Por ejemplo, convertir las viejas cortinas de terciopelo de un aristócrata en abrigos de invierno para los ancianos; o llevar muñecas a los niños que solo tienen piedras como juguetes... ¡se alegran durante muchísimo tiempo!",
          DialogueId = 90170104,
          GUID = "E1BB3CB0",
          NextDialogue = 90170105,
          SpeakNpcId = 83301,
          Subtitle = "For instance, turning an aristocrat's cast-off velvet curtains into warm winter coats for the elderly, or bringing discarded dolls to children whose only playthings are pebbles — they'll be overjoyed for a long time.",
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_2"
        },
        [90170105] = {
          ContentES = "Una vez, arrastré hasta casa una estantería rota que alguien había tirado. Aunque casi muero de cansancio, enseguida se convirtió en un parque de juegos para una camada de gatitos, ¡valió totalmente la pena!",
          DialogueId = 90170105,
          GUID = "E1BB3CDA",
          NextDialogue = 90170106,
          SpeakNpcId = 83301,
          Subtitle = "There was one time, I dragged back a broken bookshelf someone had thrown out. Though I was half-dead from the effort, it quickly turned into a non-stop playground for a litter of kittens — totally worth it!",
          TalkActionId = {
            [1] = "83301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_3"
        },
        [90170106] = {
          ContentES = "¡Eso es el trabajo de la recicladora! Generalmente son cosas sin importancia, pero nunca hay un momento aburrido. ¿Qué te parece, quieres unirte a nosotros?",
          DialogueId = 90170106,
          GUID = "E1BB3D04",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "That's scavenging for you! It's mostly small fry stuff, but never a dull moment. So, what do you say, wanna join us?",
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90170201] = {
          ContentES = "¡Shhh! ¡Es un secreto de primera para las recicladoras! No te lo habría contado si no me hubieras ayudado con ese ladrón!",
          DialogueId = 90170201,
          GUID = "E1BB4C9A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170203,
          SpeakNpcId = 83301,
          Subtitle = "Shhhh! That's a scavenger's top secret! I wouldn't have let you in on it if you hadn't helped me out with that thief!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_1"
        },
        [90170203] = {
          ContentES = "Este mapa muestra la ubicación de todos los basureros del Lago Helado, y también he marcado los pocos donde suelen aparecer las mejores cosas. ¡He ampliado esos basureros y ajustado el horario de mis visitas a la perfección!",
          DialogueId = 90170203,
          GUID = "E1BB4CEE",
          NextDialogue = 90170204,
          SpeakNpcId = 83301,
          Subtitle = "This map charts every rubbish bin in Icelake, and I've marked the few where the best stuff tends to gather — I've upgraded those bins to larger sizes and timed my visits to perfection!",
          TalkActionId = {
            [1] = "83301:Give"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_2"
        },
        [90170204] = {
          ContentES = "Pero este trabajo es muy aleatorio, en realidad, casi siempre depende de la suerte...",
          DialogueId = 90170204,
          GUID = "E1BB4D18",
          NextDialogue = 90170205,
          SpeakNpcId = 83301,
          Subtitle = "But scavenging is really hit-or-miss — mostly, it all comes down to luck...",
          TalkActionId = {
            [1] = "83301:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_3"
        },
        [90170205] = {
          ContentES = "Este trabajo no es nada fácil...",
          DialogueId = 90170205,
          GUID = "E1BB4D42",
          NextDialogue = 90170206,
          SpeakNpcId = 100001,
          Subtitle = "Scavenging's no picnic, that's for sure...",
          TalkActionId = {
            [1] = "83301:Sigh_End"
          }
        },
        [90170206] = {
          ContentES = "¡Así es, oye, yo sabía que lo entenderías!",
          DialogueId = 90170206,
          GUID = "E1BB4D6C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Ha, I knew you'd understand!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90170301] = {
          ContentES = "¡Oh, no, no es así! De hecho, me encanta el Lago Helado. Es que a menudo recuerdo los días que pasaba paseando por los campos de nieve con mi padre. Pasé toda mi infancia de esta manera.",
          DialogueId = 90170301,
          GUID = "E1BB5D02",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170303,
          SpeakNpcId = 83301,
          Subtitle = "Oh, you've got it backwards! I love Icelake through and through. It's just that I often reminisce about the days I spent wandering the snowfields with my dad; that's how I grew up.",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_1"
        },
        [90170303] = {
          ContentES = "¿Qué recuerdos te traen aquellos días?",
          DialogueId = 90170303,
          GUID = "E1BB5D56",
          NextDialogue = 90170304,
          SpeakNpcId = 100001,
          Subtitle = "How do you feel about those days?",
          TalkActionId = {
            [1] = "83301:Agree"
          }
        },
        [90170304] = {
          ContentES = "Mirando desde aquí, los campos de nieve parecen sacados de un cuento de hadas. Pero cuando estás allí dentro, te sientes diminuto. Incluso después de caminar durante horas por la nieve hasta las rodillas, esa sensación no desaparece, siempre es el mismo paisaje.",
          DialogueId = 90170304,
          GUID = "E1BB5D80",
          NextDialogue = 90170305,
          SpeakNpcId = 83301,
          Subtitle = "From here, the snowfields look like something out of a fairy tale. But once you step into it, you'd feel so very small. Even after trudging through knee-high snow for hours, that feeling would never leave.",
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_2"
        },
        [90170305] = {
          ContentES = "No me disgustan aquellos días. ¡Pero el Lago Helado bullicioso y animado es mi lugar favorito!",
          DialogueId = 90170305,
          GUID = "E1BB5DAA",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "I don't hate those days. But the bustling, lively Icelake is my absolute favourite!",
          TalkActionId = {
            [1] = "83301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90170401] = {
          ContentES = "Ese es el gran gato que solía acompañarme por los campos de nieve cuando era pequeña! Le llamábamos “Colagorda”. Solo me dejaba acariciar si le dábamos carne seca, pero ¡ay!, ¡su pelaje era tan suave! ¡Es lo mejor de lo mejor!",
          DialogueId = 90170401,
          GUID = "E1BB6D6A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170403,
          SpeakNpcId = 83301,
          Subtitle = "That's the big cat that used to roam the snowfields with me when I was little! We called him \"Plumpytail\". He would only let me pet him in exchange for some jerky, but oh, the feel of his fur — hehehe, it's the best of the best!",
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_1"
        },
        [90170403] = {
          ContentES = "¿Cómo suena un gran gato de los campos de nieve? ¿Más como un gato o como un tigre?",
          DialogueId = 90170403,
          GUID = "E1BB6DBE",
          NextDialogue = 90170404,
          SpeakNpcId = 100001,
          Subtitle = "What does a big snowfield cat sound like? More like a cat or a tiger?",
          TalkActionId = {
            [1] = "83301:Explain02_End"
          }
        },
        [90170404] = {
          ContentES = "Humm... Ciertamente no hace “miau-miau-miau”, suena más como “rrruaahhh- rrruaahhh-!”",
          DialogueId = 90170404,
          GUID = "E1BB6DE8",
          NextDialogue = 90170405,
          SpeakNpcId = 83301,
          Subtitle = "Mmm... it's certainly not like \"meow\"; it's more like, \"raawr—raawr—!\"",
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_2"
        },
        [90170405] = {
          ContentES = "¿Aún podemos ver Colagorda?",
          DialogueId = 90170405,
          GUID = "E1BB6E12",
          NextDialogue = 90170406,
          SpeakNpcId = 100001,
          Subtitle = "Is Plumpytail still around?",
          TalkActionId = {
            [1] = "83301:Think_End"
          }
        },
        [90170406] = {
          ContentES = "Colagorda prefiere la vida salvaje a la vida en la ciudad. Por eso tuvimos que tomar caminos separados. Sin embargo, ella siempre permanecerá en mi memoria, al igual que aquel campo de nieve.",
          DialogueId = 90170406,
          GUID = "E1BB6E3C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Plumpytail prefers the wild over city life. We had to go our separate ways, but she'll always be a part of me, just like the snowfields.",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90170501] = {
          ContentES = "¡No! ¡Eso no soy yo! ¡Soy demasiado mayor para un título tan infantil! ¡Por favor, te ruego que no me vuelvas a llamar así!",
          DialogueId = 90170501,
          GUID = "E1BB7DD2",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170503,
          SpeakNpcId = 83301,
          Subtitle = "Nah-uh! That's not me! I'm too grown up for such a childish title! Please, I beg of you, don't ever call me that again!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_1"
        },
        [90170503] = {
          ContentES = "¿Pues, cómo te gustaría que te llamaran?",
          DialogueId = 90170503,
          GUID = "E1BB7E26",
          NextDialogue = 90170504,
          SpeakNpcId = 100001,
          Subtitle = "Then how would you like to be referred to?"
        },
        [90170504] = {
          ContentES = "Claro que es... ejem, ejem, Señorita Margie, ¡la Detective Taciturna que recorre los rincones más recónditos de la ciudad! ¡Hoy te revelaré los secretos del Lago Helado, como siempre!",
          DialogueId = 90170504,
          GUID = "E1BB7E50",
          NextDialogue = 90170505,
          SpeakNpcId = 83301,
          Subtitle = "Ahem, that would be — Lady Margie the reticent detective, a lone shadow-walker of the city! Today, I will unveil for you the secrets of Icelake, as always!",
          TalkActionId = {
            [1] = "83301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_2"
        },
        [90170505] = {
          ContentES = "Jeje, ¡ese sí que es un título apropiado para mí!",
          DialogueId = 90170505,
          GUID = "E1BB7E7A",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Hehe, now that's a proper title for me~",
          TalkActionId = {
            [1] = "83301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90170701] = {
          ContentES = "¡Pequeña Fina! ¡Cuánto tiempo sin verte! ¿Quieres escuchar el siguiente capítulo de «Nieve, la Guardiana Felina, y Jengibre, el Detective Gatuno»? ¡Perfecto! ¡Déjame coger un taburete y me pongo cómodo para contarte una buena historia!",
          DialogueId = 90170701,
          GUID = "E1BB9EA2",
          SpeakNpcId = 83301,
          Subtitle = "Little Fina! It's been ages~ Wanna hear the next chapter of \"Snowball the Cat Ranger & Ginger the Cat Detective\"? No problem! Let me just grab a stool and settle in for a good tale!",
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_02"
        },
        [90170801] = {
          ContentES = "¡Le juro que soy una ciudadana ejemplar, Señora Acaidesa! ¡Jamás he robado ni saqueado! Solo recojo unas sobras de los cubos para calmar el hambre. Su deber no llega hasta la basura, ¿verdad?",
          DialogueId = 90170801,
          GUID = "E1BBAF0A",
          SpeakNpcId = 83301,
          Subtitle = "I assure you I'm an upstanding citizen, Ms Warden! Never pilfered or plundered, merely collecting some scraps from the bins to quiet my stomach. Even your dedication doesn't extend to rubbish, does it?",
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_03"
        },
        [90170901] = {
          ContentES = "Estás viviendo al día, ¿verdad? ¿Quieres acompañarme a recolectar las basuras? Quizás puedas vivir mejor.",
          DialogueId = 90170901,
          GUID = "E1BBBF72",
          SpeakNpcId = 83301,
          Subtitle = "You're living hand to mouth, aren't you...? That's really tough. Would you like to join me in scavenging? Might make things a bit easier...",
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_04"
        },
        [90180000] = {
          ContentES = "Yale: T-Tres tristes tigres t-t-tragan trigo...",
          DialogueId = 90180000,
          GUID = "E1C19467",
          NextDialogue = 90180002,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Peter Piker p-picked a peck of p-p-peckled peppers...",
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_1"
        },
        [90180001] = {
          ContentES = "Yale: Hola... ¡Qué buen día!... Es perfecto para hacer experimentos explosivos... Mmm, ¡qué buen día!",
          DialogueId = 90180001,
          GUID = "E1C1946A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextOptions = {
            [1] = 901800011,
            [2] = 901800012,
            [3] = 901800013,
            [4] = 901800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Hi... Such a nice day, isn't it... Perfect for some explosive experiments... Um, what a nice day.",
          TalkActionId = {
            [1] = "83103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90180002] = {
          ContentES = "Oliver: ¡Es “Tres tristes tigres tragan trigo en un trigal”! ¡Vamos, Yale, sigue el ritmo!",
          DialogueId = 90180002,
          GUID = "E1C19468",
          NextDialogue = 90180003,
          SpeakNpcId = 83103,
          Subtitle = "Oliver: It's \"Peter Piper picked a peck of pickled peppers!\" Come on, Yale, keep up!",
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_2"
        },
        [90180003] = {
          ContentES = "Yale: ¡E-Está bien! T-Tres tristes tigres...",
          DialogueId = 90180003,
          GUID = "E1C19469",
          SpeakNpcId = 83103,
          Subtitle = "Yale: O-Okay! P-Peter Piker p-picked...",
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_3"
        },
        [90180004] = {
          Content = "聊点别的",
          DialogueId = 90180004,
          GUID = "90180004.0",
          NextDialogue = 90180001,
          Subtitle = "Let's talk about something else"
        },
        [90180005] = {
          Content = "再见",
          DialogueId = 90180005,
          GUID = "90180005.0",
          Subtitle = "Goodbye"
        },
        [90180101] = {
          ContentES = "Yale: Oliver no es una bomba que habla... Puede sonar raro, pero... en realidad...",
          DialogueId = 90180101,
          GUID = "E1C1A4D2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180103,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Oliver is not a talking bomb... It might sound strange, but... he's actually...",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_1"
        },
        [90180103] = {
          ContentES = "Oliver: ¡Cállate, me estás cabreando! Soy Yale, y Yale soy yo. ¿Lo entiendes? No importa aunque no lo entiendes. No creo que alguien con tu pequeño cerebro pueda entenderlo.",
          DialogueId = 90180103,
          GUID = "E1C1A526",
          NextDialogue = 90180104,
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Ugh, you're killing me here! I am Yale, and Yale is me. Got it? Not that I'd expect someone with your pea-sized brain to understand.",
          TalkActionId = {
            [1] = "83103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_2"
        },
        [90180104] = {
          ContentES = "¡Qué bomba tan grosera! Quizás deberías deshacerte de ella.",
          DialogueId = 90180104,
          GUID = "E1C1A550",
          NextDialogue = 90180105,
          SpeakNpcId = 100001,
          Subtitle = "What a rude bomb, maybe you should get rid of it.",
          TalkActionId = {
            [1] = "83103:Angry01_End"
          }
        },
        [90180105] = {
          ContentES = "Yale: ¡Oliver a-a-actualmente es un buen chico! Puede parecer un poco rudo y grosero, y le gusta aparecer de repente, pero...",
          DialogueId = 90180105,
          GUID = "E1C1A57A",
          NextDialogue = 90180106,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Oliver's a-a-actually a nice guy! He might s-seem a bit rough, and mean, a-and likes to pop up out of the b-blue, but...",
          TalkActionId = {
            [1] = "83103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_3"
        },
        [90180106] = {
          ContentES = "Oliver: ¡Oye! ¿Esas son las palabras elogiosas?",
          DialogueId = 90180106,
          GUID = "E1C1A5A4",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Hey! That's your idea of nice words?",
          TalkActionId = {
            [1] = "83103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90180201] = {
          ContentES = "Yale: Yo... probablemente no pueda ser de mucha ayuda. Lo único en lo que soy bueno... posiblemente es en hacer “Pequeño Bum”...",
          DialogueId = 90180201,
          GUID = "E1C1B53A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180203,
          SpeakNpcId = 83103,
          Subtitle = "Yale: I... I might not be much help. The only thing I'm good at... is probably making Tot Poppers...",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_1"
        },
        [90180203] = {
          ContentES = "¿Eh? ¿Qué es “Pequeño Bum”?",
          DialogueId = 90180203,
          GUID = "E1C1B58E",
          NextDialogue = 90180204,
          SpeakNpcId = 100001,
          Subtitle = "Hmm? What's a Tot Popper?"
        },
        [90180204] = {
          ContentES = "Yale: “Pequeño Bum”... es un artículo más popular... en la juguetería “Crac y Chis”. Se requiere mucho tiempo para hacerlo.",
          DialogueId = 90180204,
          GUID = "E1C1B5B8",
          NextDialogue = 90180205,
          SpeakNpcId = 83103,
          Subtitle = "Yale: They're the most popular items at our \"Snap 'n' Spark\" toy store... They take a lot of time to make.",
          TalkActionId = {
            [1] = "83103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_2"
        },
        [90180205] = {
          ContentES = "Yale: Pero no es por mi buena habilidad... Todo se lo debo a la experiencia de Oliver.",
          DialogueId = 90180205,
          GUID = "E1C1B5E2",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Yale: But it's not because I'm skilled... It's all thanks to Oliver's expertise.",
          TalkActionId = {
            [1] = "83103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90180301] = {
          ContentES = "Yale: ¡Ah, lo siento! P-pero si hablo rápido, me enredo con las palabras.",
          DialogueId = 90180301,
          GUID = "E1C1C5A2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180303,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Ah, sorry! B-But if I start speaking fast, my tongue tends to get all t-t-tied up.",
          TalkActionId = {
            [1] = "83103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_1"
        },
        [90180303] = {
          ContentES = "Debe ser difícil para ti comunicarte con los demás.",
          DialogueId = 90180303,
          GUID = "E1C1C5F6",
          NextDialogue = 90180304,
          SpeakNpcId = 100001,
          Subtitle = "It must be hard for you to communicate with others then.",
          TalkActionId = {
            [1] = "83103:Sigh_End"
          }
        },
        [90180304] = {
          ContentES = "Yale: N-No pasa nada, a veces Oliver habla por mí... Y cuando no hay nadie más, Oliver siempre me escucha.",
          DialogueId = 90180304,
          GUID = "E1C1C620",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Yale: I-It's okay, sometimes Oliver speaks for me... And when no one else's around, Oliver would always hear me out.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90180401] = {
          ContentES = "Yale: Yo nunca tuve una “infancia”... Desde mis primeros recuerdos, he estado en este cuerpo. Oliver sí podría haber tenido una.",
          DialogueId = 90180401,
          GUID = "E1C1D60A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180403,
          SpeakNpcId = 83103,
          Subtitle = "Yale: I never really had a \"childhood\"... From my earliest memories, I've been in this body. Oliver might have one, though.",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_1"
        },
        [90180403] = {
          ContentES = "La falta de la infancia es algo triste.",
          DialogueId = 90180403,
          GUID = "E1C1D65E",
          NextDialogue = 90180404,
          SpeakNpcId = 100001,
          Subtitle = "Missing out on childhood, that's kind of sad."
        },
        [90180404] = {
          ContentES = "Yale: A veces me pregunto cómo sería tener una “infancia”... ¿El Señor Jones me habría contado un cuento antes de dormir todas las noches, como un padre normal?",
          DialogueId = 90180404,
          GUID = "E1C1D688",
          NextDialogue = 90180405,
          SpeakNpcId = 83103,
          Subtitle = "Yale: I've sometimes wondered what having a \"childhood\" would be like... Would Mr Jones have told me bedtime stories every night, like a normal dad...?",
          TalkActionId = {
            [1] = "83103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_2"
        },
        [90180405] = {
          ContentES = "Oliver: ¿Esperas que ese imbécil te cuente cuentos antes de dormir? ¿Has perdido la cabeza?",
          DialogueId = 90180405,
          GUID = "E1C1D6B2",
          NextDialogue = 90180406,
          SpeakNpcId = 83103,
          Subtitle = "Oliver: You expect that jerk to tell you bedtime stories? Have you lost your mind?",
          TalkActionId = {
            [1] = "83103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_3"
        },
        [90180406] = {
          ContentES = "Yale: ¡L-Lo siento! S-Sé que a él solo le importaban sus experimentos... No lo habría hecho...",
          DialogueId = 90180406,
          GUID = "E1C1D6DC",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Yale: S-Sorry! I-I know he only cared about his experiments... He wouldn't have done that...",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90180501] = {
          ContentES = "Yale: H-hola... Tu canto es realmente b-bonito.",
          DialogueId = 90180501,
          GUID = "E1C1E672",
          NextDialogue = 90180502,
          SpeakNpcId = 83103,
          Subtitle = "Yale: H-hello... Your singing is really b-beautiful.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_1"
        },
        [90180502] = {
          ContentES = "Oliver: ¡Bah! Solo otra víctima.",
          DialogueId = 90180502,
          GUID = "E1C1E69C",
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Hmph, just another victim.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_2"
        },
        [90180601] = {
          ContentES = "Yale: ¿Filbert... es tu amiga? Yo también tengo un buen amigo. Es tan c-confiable como F-Filbert.",
          DialogueId = 90180601,
          GUID = "E1C1F6DA",
          NextDialogue = 90180602,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Is Filbert... your friend? I have a good friend too. He's as r-reliable as F-Filbert.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_1"
        },
        [90180602] = {
          ContentES = "Oliver: Espera, ¿en serio?",
          DialogueId = 90180602,
          GUID = "E1C1F704",
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Wait, seriously?",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_2"
        },
        [90180701] = {
          ContentES = "Yale: Eh... por favor, no te enfades, todos mis experimentos con bombas c-cumplen con los estándares de s-seguridad...",
          DialogueId = 90180701,
          GUID = "E1C20742",
          SpeakNpcId = 83103,
          Subtitle = "Yale: Uh... p-please don't be mad, a-all my bomb experiments are up to s-s-s-safety s-standards...",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_03"
        },
        [90190000] = {
          ContentES = "Los momentos como estos son tan raros, sin gritos de auxilio, sin informes urgentes. Hmm... Quizás me prepare un café y por fin termine esa novela. ¿Con quién terminará la Princesa...?",
          DialogueId = 90190000,
          GUID = "E1C7FD09",
          SpeakNpcId = 85401,
          Subtitle = "Moments like these are rare — no cries for help, no urgent reports. Hmm... Perhaps I'll make some coffee and finally finish that novel. Whom does the princess end up with, I wonder?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_idle"
        },
        [90190001] = {
          ContentES = "Es un placer verte hoy sano y salvo. Cuídate... La paz que todos anhelamos llegará sin duda algún día.",
          DialogueId = 90190001,
          GUID = "E1C7FD0A",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextOptions = {
            [1] = 901900011,
            [2] = 901900012,
            [3] = 901900013,
            [4] = 901900014,
            [5] = 901900015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85401,
          Subtitle = "It's delightful to see you safe and well today. Take care... The peace we all long for will surely arrive someday.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90190002] = {
          Content = "聊点别的",
          DialogueId = 90190002,
          GUID = "90190002.0",
          NextDialogue = 90190001,
          Subtitle = "Let's talk about something else"
        },
        [90190003] = {
          Content = "再见",
          DialogueId = 90190003,
          GUID = "90190003.0",
          Subtitle = "Goodbye"
        },
        [90190101] = {
          ContentES = "Yo... creo que no tengo ningún pasatiempo en particular. Leer, quizás, si eso cuenta.",
          DialogueId = 90190101,
          GUID = "E1C80D72",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190102,
          SpeakNpcId = 85401,
          Subtitle = "I... don't think I have any particular hobbies. Reading, maybe, if that counts.",
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_1"
        },
        [90190102] = {
          ContentES = "Mi mamá siempre dice que quedándome en casa con mis libros y sin ir a todos esos bailes y tertulias, estaré perdiendo innumerables oportunidades para ascender en la escala social...",
          DialogueId = 90190102,
          GUID = "E1C80D9C",
          NextDialogue = 90190103,
          SpeakNpcId = 85401,
          Subtitle = "My mother always says staying home with my books and skipping all those balls and salons will cost me countless opportunities to climb the social ladder...",
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_2"
        },
        [90190103] = {
          ContentES = "Pero, sinceramente, prefiero así.",
          DialogueId = 90190103,
          GUID = "E1C80DC6",
          NextDialogue = 90190104,
          SpeakNpcId = 85401,
          Subtitle = "But honestly, I prefer it this way.",
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_3"
        },
        [90190104] = {
          ContentES = "¿Qué libros estás leyendo estos días?",
          DialogueId = 90190104,
          GUID = "E1C80DF0",
          NextDialogue = 90190105,
          SpeakNpcId = 100001,
          Subtitle = "What are you reading these days?"
        },
        [90190105] = {
          ContentES = "Principalmente, libros sobre medicina de campo de batalla: «Manual de Ayuda de Campo de Emergencia», «Guía Práctica para el Cuidado de Traumatismos», «Cómo Establecer un Hospital de Campaña Temporal»...",
          DialogueId = 90190105,
          GUID = "E1C80E1A",
          NextDialogue = 90190106,
          SpeakNpcId = 85401,
          Subtitle = "Mostly books on battlefield medicine — Emergency Field Aid Manual, Practical Guide to Trauma Care, How to Set Up a Temporary Field Hospital...",
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_4"
        },
        [90190106] = {
          ContentES = "Quizás sepas que mis estudios previos no se centraban en primeros auxilios, así que, aunque tengo la cualificación del paramédica, a veces me siento un poco superada.",
          DialogueId = 90190106,
          GUID = "E1C80E44",
          NextDialogue = 90190107,
          SpeakNpcId = 85401,
          Subtitle = "You may know that my previous studies never focused on first aid, so even with my medic qualifications, I still feel out of my depth sometimes.",
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_5"
        },
        [90190107] = {
          ContentES = "Deberías relajarte de vez en cuando. No te exijas tanto.",
          DialogueId = 90190107,
          GUID = "E1C80E6E",
          NextDialogue = 90190108,
          SpeakNpcId = 100001,
          Subtitle = "You should try to unwind now and then. Don't push yourself too hard."
        },
        [90190108] = {
          ContentES = "Lo sé, por eso estos días estoy leyendo un libro... que se llama «Tacones de Cristal». Cuenta una historia sobre... una princesa y un caballero... ¡No es que me gusten las novelas románticas! Solo... casualmente la abrí y eso es todo...",
          DialogueId = 90190108,
          GUID = "E1C80E98",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "I know, which is why I've been reading... Glass Heels. It's about a—a princess and a knight... Not that I'm into romantic novels or anything! I just... happened to flip through it, that's all...",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90190201] = {
          ContentES = "¡Por supuesto! La alquimia es la piedra angular de Hyperborea. ¡Los eruditos la llaman el “Milagro Primordial”!",
          DialogueId = 90190201,
          GUID = "E1C81DDA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190202,
          SpeakNpcId = 85401,
          Subtitle = "Certainly! Alchemy is the cornerstone of Hyperborea — scholars call it the \"primordial miracle.\"",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_1"
        },
        [90190202] = {
          ContentES = "Al principio, su propósito era simple: extraer oro de Phoxene. Pero con el tiempo, la gente descubrió que este pequeño cristal podía hacer mucho más: accionar maquinaria, generar chipas de electricidad... Es la “magia” de los Solarianos.",
          DialogueId = 90190202,
          GUID = "E1C81E04",
          NextDialogue = 90190203,
          SpeakNpcId = 85401,
          Subtitle = "At first, its purpose was simple: to extract gold from Phoxene. But over time, we discovered this tiny crystal could do so much more — power machinery, generate electricity... It's Solarian magic.",
          TalkActionId = {
            [1] = "85401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_2"
        },
        [90190203] = {
          ContentES = "... Pero luego, la Academia de Alquimia...",
          DialogueId = 90190203,
          GUID = "E1C81E2E",
          NextDialogue = 90190204,
          SpeakNpcId = 85401,
          Subtitle = "...But then, the Academy...",
          TalkActionId = {
            [1] = "85401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_3"
        }
      }
    end
  },
  {
    MinKey = 90190204,
    MaxKey = 90250106,
    Loader = function()
      return {
        [90190204] = {
          ContentES = "¿Estudiaste allí, verdad?",
          DialogueId = 90190204,
          GUID = "E1C81E58",
          NextDialogue = 90190205,
          SpeakNpcId = 100001,
          Subtitle = "You used to study there, didn't you?"
        },
        [90190205] = {
          ContentES = "... Sí, en la Spathatoi. Pero ese capítulo de mi vida ya concluyó.",
          DialogueId = 90190205,
          GUID = "E1C81E82",
          NextDialogue = 90190206,
          SpeakNpcId = 85401,
          Subtitle = "...Yes, in the Spathatoi. But that chapter of my life is over now.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_4"
        },
        [90190206] = {
          ContentES = "¿Por qué te fuiste?",
          DialogueId = 90190206,
          GUID = "E1C81EAC",
          NextDialogue = 90190207,
          SpeakNpcId = 100001,
          Subtitle = "Why did you leave?"
        },
        [90190207] = {
          ContentES = "Me fui porque la Spathatoi perdió su rumbo. Lo que comenzó como la búsqueda del conocimiento se convirtió en algo oscuro. Se ha convertido en el núcleo más ardiente de la maquinaria de guerra de Hyperborea, pero su combustible trae sufrimientos y desgracias a mucha gente.",
          DialogueId = 90190207,
          GUID = "E1C81ED6",
          NextDialogue = 90190208,
          SpeakNpcId = 85401,
          Subtitle = "I left because the Spathatoi lost its way. What began as a pursuit of knowledge turned into something darker. It's become the blazing core of Hyperborea's war machine, but its fuel brings suffering and misfortune to its people.",
          TalkActionId = {
            [1] = "85401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_5"
        },
        [90190208] = {
          ContentES = "Supongo que... yo no era tan fuerte como creía. No podía aceptar en lo que se había convertido, y no tenía el valor ni la fuerza para cambiarlo. Por eso, hice lo único que podía: me fui.",
          DialogueId = 90190208,
          GUID = "E1C81F00",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "I suppose... I wasn't as strong as I thought. I couldn't reconcile with what it had become, and I lacked the courage or strength to change it. So, I did the only thing I could — I walked away.",
          TalkActionId = {
            [1] = "85401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90190301] = {
          ContentES = "Algunos artículos y medicamentos de primeros auxilios. Hay vendas, antisépticos, anestésicos y herramientas básicas para el cuidado de heridas, como bisturíes y suturas.",
          DialogueId = 90190301,
          GUID = "E1C82E42",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190302,
          SpeakNpcId = 85401,
          Subtitle = "Some emergency tools and supplies — bandages, antiseptics, anesthetics, and the basic tools for wound care like surgical blades and sutures.",
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_1"
        },
        [90190302] = {
          ContentES = "También llevo un pañuelo y un peine.",
          DialogueId = 90190302,
          GUID = "E1C82E6C",
          NextDialogue = 90190303,
          SpeakNpcId = 85401,
          Subtitle = "I also keep a handkerchief and a comb in it.",
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_2"
        },
        [90190303] = {
          ContentES = "¿Llevas artículos de belleza al campo de batalla? Debes cuidar mucho tu elegancia.",
          DialogueId = 90190303,
          GUID = "E1C82E96",
          NextDialogue = 90190304,
          SpeakNpcId = 100001,
          Subtitle = "You bring beauty supplies to the battlefield? You must take great care in staying elegant."
        },
        [90190304] = {
          ContentES = "No, no es lo que piensas... No son para mí misma, sino para los fallecidos. Los uso para ayudar a quienes fallecen... para que se vean presentables.",
          DialogueId = 90190304,
          GUID = "E1C82EC0",
          NextDialogue = 90190305,
          SpeakNpcId = 85401,
          Subtitle = "Oh, it's not what you think... They're not for me — they're for my patients. I use them to help those who don't make it... tidy up a bit.",
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_3"
        },
        [90190305] = {
          ContentES = "La crueldad de la muerte no solo arrebata la vida, sino también la dignidad del ser humano.",
          DialogueId = 90190305,
          GUID = "E1C82EEA",
          NextDialogue = 90190306,
          SpeakNpcId = 85401,
          Subtitle = "The cruelty of death robs people of more than just their lives — it strips them of their dignity.",
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_4"
        },
        [90190306] = {
          ContentES = "Solo quiero que... cuando sus familias vengan a darles su último adiós, puedan ver a sus seres queridos en paz, como si simplemente estuvieran durmiendo. Tras estar separados tanto tiempo, ningún padre o madre debería tener que ver el rostro de su hijo retorcido por el dolor...",
          DialogueId = 90190306,
          GUID = "E1C82F14",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "I just want... when their families come to say their final goodbyes, for them to see their loved ones at peace, as though they're merely asleep. After being apart for so long, no parent should have to see their child's face twisted in pain...",
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90190401] = {
          ContentES = "¡Oh, no, está bien! Puedo manejar... Bueno, a veces sí es un poco difícil... Las clases de primeros auxilios y enfermería no son tan difíciles, pero las pruebas de aptitud física... sí me resultan muy difíciles.",
          DialogueId = 90190401,
          GUID = "E1C83EAA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190402,
          SpeakNpcId = 85401,
          Subtitle = "Oh, it's fine! I can handle it... Well, maybe just a little tough sometimes. The emergency care and nursing lessons aren't too bad, but the physical fitness tests... those are a real struggle for me.",
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_1"
        },
        [90190402] = {
          ContentES = "Aunque me levanto antes que todos para entrenar más, apenas consigo aprobar... Por favor no te rías de mí. Adquirir resistencia física es mucho más difícil que estudiar.",
          DialogueId = 90190402,
          GUID = "E1C83ED4",
          NextDialogue = 90190403,
          SpeakNpcId = 85401,
          Subtitle = "Even though I get up earlier than everyone else for extra training, I still only manage to scrape by with passing scores... Please don't make fun of me! Building stamina is so much harder than studying.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_2"
        },
        [90190403] = {
          ContentES = "Levantarse temprano para extra entrenamiento suena agotador.",
          DialogueId = 90190403,
          GUID = "E1C83EFE",
          NextDialogue = 90190404,
          SpeakNpcId = 100001,
          Subtitle = "Waking up early for extra training sounds exhausting."
        },
        [90190404] = {
          ContentES = "Sí, lo es. Pero cuando dejo de pensar en mis piernas cansadas y miro hacia arriba, veo los campos de trigo extendiéndose más allá de la ciudad y las casitas en el horizonte, escucho el crujido de los molinos de viento y el silbido de los pastores. Siempre me hace sentir mucho mejor.",
          DialogueId = 90190404,
          GUID = "E1C83F28",
          NextDialogue = 90190405,
          SpeakNpcId = 85401,
          Subtitle = "It is. But when I take my mind off my tired legs and look up, I see the wheat fields stretching beyond the city and the cottages on the horizon, and hear the windmills creaking and the herdsmen whistling. It always helps me feel so much better.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_3"
        },
        [90190405] = {
          ContentES = "Porque... correr por ese camino me da la sensación de estar protegiendo esas cosas sencillas y preciosas de que sean arrebatadas.",
          DialogueId = 90190405,
          GUID = "E1C83F52",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "Because... running along that road feels like my way of protecting these simple, precious things from being taken away.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90190501] = {
          ContentES = "... La última vez que hablé con mi papá fue por el radio. Estaba en el campo de batalla de la Fortaleza de Lonza, y a pesar del peligro, me dijo: No te preocupes, estaré bien.",
          DialogueId = 90190501,
          GUID = "E1C84F12",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190502,
          SpeakNpcId = 85401,
          Subtitle = "...The last time I spoke with my father was over the radio. It was on the battlefield of Lonza Fortress, and despite the danger, he told me, \"Don't worry, I'll be fine.\"",
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_1"
        },
        [90190502] = {
          ContentES = "Después de todo lo que pasó, a menudo encendía el radio en plena noche, sintonizaba su canal y pulsaba el botón de llamada, con la esperanza de oír su voz de nuevo...",
          DialogueId = 90190502,
          GUID = "E1C84F3C",
          NextDialogue = 90190503,
          SpeakNpcId = 85401,
          Subtitle = "After everything that happened, I'd often turn on my radio in the dead of night, tune to his channel, and press the call button, hoping to hear his voice again...",
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_2"
        },
        [90190503] = {
          ContentES = "No fue sino hasta que me senté allí en silencio durante lo que me pareció una eternidad que me di cuenta... de que nunca volvería.",
          DialogueId = 90190503,
          GUID = "E1C84F66",
          NextDialogue = 90190504,
          SpeakNpcId = 85401,
          Subtitle = "It wasn't until I sat there in silence for what felt like an eternity that I realized... he was never coming back.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_3"
        },
        [90190504] = {
          ContentES = "Mis condolencias...",
          DialogueId = 90190504,
          GUID = "E1C84F90",
          NextDialogue = 90190505,
          SpeakNpcId = 100001,
          Subtitle = "My condolences..."
        },
        [90190505] = {
          ContentES = "Gracias. No te preocupes, me mantendré fuerte y seguiré adelante. No pararé hasta que limpie el nombre de mi padre y honre a los agraviados que cayeron en la Batalla de Lonza.",
          DialogueId = 90190505,
          GUID = "E1C84FBA",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "Thank you. Don't worry, I'll stay strong and keep pushing on. Until I clear my father's name and honour the wronged who fell in the Lonza battle, I won't stop.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_4",
          bForbidSkipOptions = true
        },
        [90190601] = {
          ContentES = "Leí una vez textos médicos de Huaxu en la biblioteca de la capital. Aunque sus teorías difieren de las tradiciones médicas de Hyperborea, han demostrado ser notablemente efectivas en los tratamientos. Todavía hay partes que no comprendo del todo: ¿te importaría ayudarme con ellas?",
          DialogueId = 90190601,
          GUID = "E1C85F7A",
          SpeakNpcId = 85401,
          Subtitle = "I once read medical texts from Huaxu in the capital's library. While their theories differ from those of Hyperborea's medical traditions, they've proven remarkably effective in treatment. There are still parts I don't fully understand — would you mind helping me with them?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_01"
        },
        [90190701] = {
          ContentES = "Señora Acaidesa, ¿la justicia que llega tarde aún merece llamarse justicia?",
          DialogueId = 90190701,
          GUID = "E1C86FE2",
          SpeakNpcId = 85401,
          Subtitle = "Madam Warden, I wonder — does justice that arrives late still deserve to be called justice?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_02"
        },
        [90190801] = {
          ContentES = "Ha pasado tanto tiempo. Desde que dejé la Spathatoi, apenas hemos hablado. ¿Cómo estás...?",
          DialogueId = 90190801,
          GUID = "E1C8804A",
          SpeakNpcId = 85401,
          Subtitle = "It's been so long. Since I left the Spathatoi, we've barely spoken. How... have you been?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_03"
        },
        [90190901] = {
          ContentES = "Aunque ya no pertenezco a la Spathatoi, siempre será un lugar en que estudié. Sé que es difícil obtener el perdón, pero quiero decirte: lo siento.",
          DialogueId = 90190901,
          GUID = "E1C890B2",
          SpeakNpcId = 85401,
          Subtitle = "Even though I've left the Spathatoi, it remains a place that shaped me. I know forgiveness might be too much to hope for, but I still want to say — I'm sorry.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_04"
        },
        [90200000] = {
          ContentES = "Shhh... Casi estoy en el personaje.",
          DialogueId = 90200000,
          GUID = "E1CE65A9",
          SpeakNpcId = 81103,
          Subtitle = "Hush... I am nearly in character.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_idle"
        },
        [90200001] = {
          ContentES = "Ahora yo actúo como el papel del prisionero destrozado, y tú, como {性别:el alcaide|la alcaidesa}, guardas mis cadenas.",
          DialogueId = 90200001,
          GUID = "E1CE65AA",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextOptions = {
            [1] = 902000011,
            [2] = 902000012,
            [3] = 902000013,
            [4] = 902000014,
            [5] = 902000015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81103,
          Subtitle = "I assume the role of the shattered prisoner, and you, as a watchful warden, stand sentinel over my chains.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90200002] = {
          Content = "聊点别的",
          DialogueId = 90200002,
          GUID = "90200002.0",
          NextDialogue = 90200001,
          Subtitle = "Let's talk about something else"
        },
        [90200003] = {
          Content = "再见",
          DialogueId = 90200003,
          GUID = "90200003.0",
          Subtitle = "Goodbye"
        },
        [90200101] = {
          ContentES = "Era como una lámpara de cristal rota, una estrella caída en una alcantarilla sucia.",
          DialogueId = 90200101,
          GUID = "E1CE7612",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200102,
          SpeakNpcId = 81103,
          Subtitle = "He was a shattered crystal lamp, a fallen star plunged into a filthy gutter.",
          TalkActionId = {
            [1] = "81103:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_1"
        },
        [90200102] = {
          ContentES = "¿...?",
          DialogueId = 90200102,
          GUID = "E1CE763C",
          NextDialogue = 90200103,
          SpeakNpcId = 100001,
          Subtitle = "...?",
          TalkActionId = {
            [1] = "81103:Talk01_End"
          }
        },
        [90200103] = {
          ContentES = "Era justo como esas cosas: ridículamente absurdo, pero de algún modo, brillaba con gran esplendor.",
          DialogueId = 90200103,
          GUID = "E1CE7666",
          NextDialogue = 90200104,
          SpeakNpcId = 81103,
          Subtitle = "He was just like those things — laughably absurd, yet somehow, they shine brilliantly.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_2"
        },
        [90200104] = {
          ContentES = "El muro entre nuestras celdas era tan delgado que se oía todo. Estaba allí, a apenas un metro de distancia, divagando sobre su familia, tejiendo sueños del futuro o cantando alguna melodía irremediablemente desafinada.",
          DialogueId = 90200104,
          GUID = "E1CE7690",
          NextDialogue = 90200105,
          SpeakNpcId = 81103,
          Subtitle = "The wall between our cells was so thin, every sound passed through. There he was, barely a metre away — rambling about his family, spinning dreams of the future, or singing some hopelessly off-key tune.",
          TalkActionId = {
            [1] = "81103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_3"
        },
        [90200105] = {
          ContentES = "Por un momento, olvidaba que yo era una bestia enjaulada. Me sentía como un niño normal en la escuela, despertando de una pesadilla durante la siesta, con el ruido de un compañero ruidoso a mi lado.",
          DialogueId = 90200105,
          GUID = "E1CE76BA",
          NextDialogue = 90200106,
          SpeakNpcId = 81103,
          Subtitle = "For a moment, I'd forget I was a caged beast. Instead, I'd feel like an ordinary child in school, waking from a nightmare during an afternoon nap to the racket of a noisy classmate beside me.",
          TalkActionId = {
            [1] = "81103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_4"
        },
        [90200106] = {
          ContentES = "Así que te sentiste atraído hacia él, y se hicieron amigos.",
          DialogueId = 90200106,
          GUID = "E1CE76E4",
          NextDialogue = 90200107,
          SpeakNpcId = 100001,
          Subtitle = "So, you were drawn to him, and you became friends."
        },
        [90200107] = {
          ContentES = "... Je... Quizás.",
          DialogueId = 90200107,
          GUID = "E1CE770E",
          NextDialogue = 90200108,
          SpeakNpcId = 81103,
          Subtitle = "...Heh. Perhaps.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_5"
        },
        [90200108] = {
          ContentES = "Pero “amigo” es una palabra demasiado luminosa para alguien como yo. Éramos más bien como dos peces desorientados, luchando por sobrevivir en un lecho de río seco.",
          DialogueId = 90200108,
          GUID = "E1CE7738",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "But \"friend\" is far too bright a word for someone like me. We were more like two stranded fish, floundering together in a drying riverbed.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90200201] = {
          ContentES = "¿Por qué? La historia de Parsifal terminó hace mucho tiempo. Ese nombre no es más que un eco lejano ahora, tan tenue y distante que a veces me pregunto si fue alguna vez real.",
          DialogueId = 90200201,
          GUID = "E1CE867A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200202,
          SpeakNpcId = 81103,
          Subtitle = "Why should I? Parsifal's story ended long ago. That name is but a distant echo now, so faint and far away that I sometimes wonder if it was ever real.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_1"
        },
        [90200202] = {
          ContentES = "Pero para mí, tú eres real.",
          DialogueId = 90200202,
          GUID = "E1CE86A4",
          NextDialogue = 90200203,
          SpeakNpcId = 100001,
          Subtitle = "But to me, you're real."
        },
        [90200203] = {
          ContentES = "... ¿Ah, sí?",
          DialogueId = 90200203,
          GUID = "E1CE86CE",
          NextDialogue = 90200204,
          SpeakNpcId = 81103,
          Subtitle = "...Is that so?",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_2"
        },
        [90200204] = {
          ContentES = "Bien. Entonces, llevaré esta actuación final a su conclusión, por ti, mi última y única audiencia.",
          DialogueId = 90200204,
          GUID = "E1CE86F8",
          NextDialogue = 90200205,
          SpeakNpcId = 81103,
          Subtitle = "Then I shall carry this final performance to its conclusion — for you, my last and only audience.",
          TalkActionId = {
            [1] = "81103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_3"
        },
        [90200205] = {
          ContentES = "Gracias por concederme un escenario donde descansar mi alma fatigada.",
          DialogueId = 90200205,
          GUID = "E1CE8722",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "Thank you, for granting me a stage to rest my weary soul.",
          TalkActionId = {
            [1] = "81103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90200301] = {
          ContentES = "Eres muy amable. Gracias. Sin embargo, todas mis promesas se han cumplido. Hay poco que me conmueva.",
          DialogueId = 90200301,
          GUID = "E1CE96E2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200302,
          SpeakNpcId = 81103,
          Subtitle = "You're so kind. Thank you. Yet, all my vows have been fulfilled. There's little left that stirs my heart.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_1"
        },
        [90200302] = {
          ContentES = "...",
          DialogueId = 90200302,
          GUID = "E1CE970C",
          NextDialogue = 90200303,
          SpeakNpcId = 81103,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_2"
        },
        [90200303] = {
          ContentES = "Si alguna vez te encuentras en el Teatro Galea, por favor, transmítele a la Señora Violetta que me he asentado en Aethyrie. Dile que no se preocupe, pues estoy muy bien.",
          DialogueId = 90200303,
          GUID = "E1CE9736",
          NextDialogue = 90200304,
          SpeakNpcId = 81103,
          Subtitle = "Should you ever find yourself at the Galea Theatre, please convey to Ms Violetta that I've settled down in Aethyrie. Assure her not to worry, as I am doing very well now.",
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_3"
        },
        [90200304] = {
          ContentES = "“Una tierra de música y poesía, donde cada guijarro marca un ritmo, y cada arroyo canta una melodía.”",
          DialogueId = 90200304,
          GUID = "E1CE9760",
          NextDialogue = 90200305,
          SpeakNpcId = 81103,
          Subtitle = "\"A land of music and poetry, where every pebble taps out a rhythm, and every brook sings a melody.\"",
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_4"
        },
        [90200305] = {
          ContentES = "Espero que esto la convenza de no preguntar por mi paradero. Yo fui su alumno predilecto... Prefiero no empañar sus recuerdos.",
          DialogueId = 90200305,
          GUID = "E1CE978A",
          NextDialogue = 90200306,
          SpeakNpcId = 81103,
          Subtitle = "Hopefully, that'll keep her from enquiring after me. Once her favoured pupil... I'd rather not tarnish her memories.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_5"
        },
        [90200306] = {
          ContentES = "¿Es una pequeña mentira piadosa...?",
          DialogueId = 90200306,
          GUID = "E1CE97B4",
          NextDialogue = 90200307,
          SpeakNpcId = 100001,
          Subtitle = "A little white lie, I see."
        },
        [90200307] = {
          ContentES = "Así es. La ignorancia es siempre una bendición.",
          DialogueId = 90200307,
          GUID = "E1CE97DE",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "Indeed. Ignorance is always bliss.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_6",
          bForbidSkipOptions = true
        },
        [90200401] = {
          ContentES = "¿Por qué quieres aprender a actuar? No necesitas convertirte en otra persona.",
          DialogueId = 90200401,
          GUID = "E1CEA74A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200402,
          SpeakNpcId = 81103,
          Subtitle = "Why seek to learn acting? You have no need to become someone else.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_1"
        },
        [90200402] = {
          ContentES = "¿“Convertirme en otra persona”?",
          DialogueId = 90200402,
          GUID = "E1CEA774",
          NextDialogue = 90200403,
          SpeakNpcId = 100001,
          Subtitle = "Become someone else?"
        },
        [90200403] = {
          ContentES = "Cuando estás en el escenario, cada parte de ti desde tus huesos hasta tu respiración, se entrega al personaje. En ese momento, puedes despojarte de todas tus penas y dolores, entrando en un mundo inmaculado por la realidad.",
          DialogueId = 90200403,
          GUID = "E1CEA79E",
          NextDialogue = 90200404,
          SpeakNpcId = 81103,
          Subtitle = "When you're on stage, every part of you — from your very bones to the breaths you take — is surrendered to the character. In that moment, you can shed all your sorrows and pain, stepping into a world unblemished by reality.",
          TalkActionId = {
            [1] = "81103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_2"
        },
        [90200404] = {
          ContentES = "Pero tú naciste como {性别:el héroe|la heroína} de tu propia historia, con la admiración y la confianza de quienes te rodean. Brillas con naturalidad, sin necesidad de ningún foco para cautivar.",
          DialogueId = 90200404,
          GUID = "E1CEA7C8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "But you... you were born the {性别：hero|heroine} of your own story, already carrying the admiration and trust of those around you. You shine effortlessly, needing no spotlight to dazzle.",
          TalkActionId = {
            [1] = "81103:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90200501] = {
          ContentES = "Permanece en pie, perdurando mucho más allá de mis años. A un lado de sus imponentes muros, se alza la imponente ciudad interior, majestuosa como nubes de tormenta, pero más fría.",
          DialogueId = 90200501,
          GUID = "E1CEB7B2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200502,
          SpeakNpcId = 81103,
          Subtitle = "It stands, enduring time far beyond my years. On one side of its towering walls lies the imposing inner city — majestic as storm clouds, yet colder.",
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_1"
        },
        [90200502] = {
          ContentES = "Figuras elegantemente vestidas descienden de carruajes forrados de seda, discutiendo sobre arte, poesía y el perpetuo cielo sombrío. Cotillean sobre bailes y esponsales, lamentando cómo el fango de la nieve derretida de la ciudad exterior ensucia sus finas botas de cuero.",
          DialogueId = 90200502,
          GUID = "E1CEB7DC",
          NextDialogue = 90200503,
          SpeakNpcId = 81103,
          Subtitle = "Elegantly clad figures alight from silk-lined carriages, discussing art, poetry, and the perpetual gloom of the skies. They gossip about balls and betrothals, lamenting how the mire of melting snow from the outer city soils their fine leather boots.",
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_2"
        },
        [90200503] = {
          ContentES = "Al otro lado de los muros,el alborotado distrito de la niebla bulle de caos. Allí los vendedores gritaban a todo pulmón, las madres sujetan a sus hijos, rogando por un mendrugo de pan de centeno. Las manos traviesas dibujaban grafitis desafiantes en el muro, siempre un paso por delante de las patrullas.",
          DialogueId = 90200503,
          GUID = "E1CEB806",
          NextDialogue = 90200504,
          SpeakNpcId = 81103,
          Subtitle = "On the other side of the walls, the rowdy fog district buzzes with chaos. Vendors hawk loudly, mothers clutch their children, begging for a scrap of rye bread. Mischievous hands sketch defiant graffiti, always a step ahead of the patrols.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_3"
        },
        [90200504] = {
          ContentES = "Así se encuentra nuestro Teatro Galea. Está atrapado entre estos dos mundos, oyendo todo, pero sin comprender nada.",
          DialogueId = 90200504,
          GUID = "E1CEB830",
          NextDialogue = 90200505,
          SpeakNpcId = 81103,
          Subtitle = "And so stands our Galea Theatre, caught between these two worlds, hearing all yet understanding none.",
          TalkActionId = {
            [1] = "81103:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_4"
        },
        [90200505] = {
          ContentES = "¿Pues, tienes algún recuerdo personal de ti de aquí?",
          DialogueId = 90200505,
          GUID = "E1CEB85A",
          NextDialogue = 90200506,
          SpeakNpcId = 100001,
          Subtitle = "Any personal memories there?",
          TalkActionId = {
            [1] = "81103:Confident_End"
          }
        },
        [90200506] = {
          ContentES = "Curiosamente, lo primero que me viene a la mente no son los guiones ni el lujoso vestuario, ni la abarrotada sala de utilería que barría a diario.",
          DialogueId = 90200506,
          GUID = "E1CEB884",
          NextDialogue = 90200507,
          SpeakNpcId = 81103,
          Subtitle = "Oddly, it's not the scripts or the lavish costumes that first come to mind, nor the cluttered prop room I swept daily.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_5"
        },
        [90200507] = {
          ContentES = "Lo que recuerdo es la alfombra de terciopelo que cubría el escenario tras la caída del telón. Cuando yo era niño, después de la primera actuación que puedo recordar, mi madre y yo nos quedábamos en el escenario una vez que todos se iban, recitando líneas y bailando hasta la madrugada.",
          DialogueId = 90200507,
          GUID = "E1CEB8AE",
          NextDialogue = 90200508,
          SpeakNpcId = 81103,
          Subtitle = "It's the velvet carpet that blanketed the stage after the curtain fell. As a child, after the earliest performance I can remember, my mother and I lingered on the stage after everyone left, reciting lines and dancing through the night.",
          TalkActionId = {
            [1] = "81103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_6"
        },
        [90200508] = {
          ContentES = "Al romper el alba, el cansancio me venció... me recosté en la alfombra, apoyando la cabeza en el regazo de mi madre, y me hundí en un largo y dulce sueño.",
          DialogueId = 90200508,
          GUID = "E1CEB8D8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "When dawn broke, exhaustion finally overtook me. I lay down on that carpet, resting my head on Mother's lap, and drifted into a long, sweet dream.",
          TalkActionId = {
            [1] = "81103:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_7",
          bForbidSkipOptions = true
        },
        [90200601] = {
          ContentES = "¿Cómo estás últimamente?\n... Disculpa mi brusquedad. No nos conocemos. Solo pregunto... por un amigo mío.",
          DialogueId = 90200601,
          GUID = "E1CEC81A",
          SpeakNpcId = 81103,
          Subtitle = [[
How have you been lately?
...Apologies for the abruptness. We don't actually know each other. I was... merely enquiring for a friend.]],
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_01"
        },
        [90200701] = {
          ContentES = "¿Verdad? Así que has encontrado un nuevo hogar y una familia que se preocupa por ti... ¡Qué bueno! Rompiste tu jaula... ¡Qué alma tan valiente eres!",
          DialogueId = 90200701,
          GUID = "E1CED882",
          SpeakNpcId = 81103,
          Subtitle = "Is that so? You've found a new home and a family who cares for you... That's wonderful. You've broken free of your cage — what a brave soul you are.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_02"
        },
        [90200901] = {
          ContentES = "Tu mímica es extraordinaria. Ni siquiera los mejores utileros de escenario podrían crear algo tan exquisitamente detallado.",
          DialogueId = 90200901,
          GUID = "E1CEF952",
          SpeakNpcId = 81103,
          Subtitle = "Your mimicry is extraordinary. Even the finest stage prop artists couldn't craft something so exquisitely detailed.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_04"
        },
        [90210000] = {
          ContentES = "¿Hay algo en lo que pueda ayudar? No es que sea una adicta al trabajo, simplemente... es un hábito, creo que. Cuando no estoy ocupada, me siento inquieta.",
          DialogueId = 90210000,
          GUID = "E1D4CE49",
          SpeakNpcId = 84101,
          Subtitle = "Is there anything I can help with? It's not that I'm a workaholic — it's just... a habit, I guess. When I'm not busy, I feel unsettled.",
          VoiceName = "voice/$Locale$/char/Lise/vo_idle"
        },
        [90210001] = {
          ContentES = "Patrulla finalizada. No se detectaron criaturas peligrosas, daños estructurales ni marcas sospechosas. Las operaciones rutinarias pueden continuar sin interrupción. Informe concluido.",
          DialogueId = 90210001,
          GUID = "E1D4CE4A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextOptions = {
            [1] = 902100011,
            [2] = 902100012,
            [3] = 902100013,
            [4] = 902100014,
            [5] = 902100015,
            [6] = 902100016,
            [7] = 902100017
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84101,
          Subtitle = "Patrol complete. No signs of dangerous creatures, structural damage, or suspicious markings. Routine operations may proceed without interruption. Report concluded.",
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_welcome",
          bForbidSkipOptions = true
        },
        [90210002] = {
          Content = "聊点别的",
          DialogueId = 90210002,
          GUID = "90210002.0",
          NextDialogue = 90210001,
          Subtitle = "Let's talk about something else"
        },
        [90210003] = {
          Content = "再见",
          DialogueId = 90210003,
          GUID = "90210003.0",
          Subtitle = "Goodbye"
        },
        [90210101] = {
          ContentES = "Oh... ¿Lo has notado? Sí, tengo una, me la regaló alguien muy querido. La guardo bien, pero... No puedo evitar comprobar que esté allí de vez en cuando, por si acaso desaparece.",
          DialogueId = 90210101,
          GUID = "E1D4DEB2",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210102,
          SpeakNpcId = 84101,
          Subtitle = "Oh... You've noticed. Yes, I have one — it was given to me by someone very dear. I keep it locked away safely, but... I can't help checking on it now and then, worried it might just vanish somehow.",
          TalkActionId = {
            [1] = "84101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_1"
        },
        [90210102] = {
          ContentES = "Entonces seguramente sabes tocar muchas melodías con ella.",
          DialogueId = 90210102,
          GUID = "E1D4DEDC",
          NextDialogue = 90210103,
          SpeakNpcId = 100001,
          Subtitle = "Then you must know how to play lots of tunes on it.",
          TalkActionId = {
            [1] = "84101:Explain02_End"
          }
        },
        [90210103] = {
          ContentES = "En realidad, solo sé una. La persona que me la regaló me la enseñó. No aprendí rápido... Quizás es que nunca he sido buena en expresar emociones...",
          DialogueId = 90210103,
          GUID = "E1D4DF06",
          NextDialogue = 90210104,
          SpeakNpcId = 84101,
          Subtitle = "Actually, I only know one. The person who gave it to me taught me. I wasn't quick to pick it up back then... maybe because I've never been good at things that require emotional expression...",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_2"
        },
        [90210104] = {
          ContentES = "Pero cada vez que estoy demasiado tenso o me dejo llevar por los impulsos, siempre recurro a ella. Es como un ancla: me recuerda lo que realmente importa, aquello en lo que puedo confiar. De esta manera, me ayuda a recuperar la calma.",
          DialogueId = 90210104,
          GUID = "E1D4DF30",
          NextDialogue = 90210105,
          SpeakNpcId = 84101,
          Subtitle = "But whenever I'm too tense or carried away, I find myself reaching for it. It's like an anchor — a reminder of the things that matter, the things I can trust. It always helps me find my calm again.",
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_3"
        },
        [90210105] = {
          ContentES = "Muchos de mis compañeros recurren a los médicos para aliviar el estrés, mediante tranquilizantes, estimulantes, ese tipo de cosas. Yo nunca he necesitado esos. Ya sea que mi corazón lata rápido o lento, la armónica siempre me tranquiliza.",
          DialogueId = 90210105,
          GUID = "E1D4DF5A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Many of my peers rely on doctors for stress relief — sedatives, stimulants, that kind of stuff. I've never needed that. Whether my heart races or slows, the harmonica always steadies me.",
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90210201] = {
          ContentES = "No está mal. La Legión es uno de los pocos lugares donde el trabajo duro se ve realmente recompensado. He ganado mi posición aquí, y ahora incluso tengo algunos subordinados. Me aseguro de que traten a los Charons y a los Solas con el mismo respeto.",
          DialogueId = 90210201,
          GUID = "E1D4EF1A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210202,
          SpeakNpcId = 84101,
          Subtitle = "Not bad. The Legion is one of the few places where hard work truly gets rewarded. I've earned my position here, and now I even have a few subordinates. I make sure they treat Charons and Solas with the same respect.",
          TalkActionId = {
            [1] = "84101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_1"
        },
        [90210202] = {
          ContentES = "He oído muchas quejas, e incluso acusaciones muy duras, sobre cómo la Legión trata al Charon. Hago todo lo posible por aliviar eso... Quizás algún día la gente vea a la Legión con mejores ojos. Espero que con el tiempo, la gente vea a la Legión de una mejora manera.",
          DialogueId = 90210202,
          GUID = "E1D4EF44",
          NextDialogue = 90210203,
          SpeakNpcId = 84101,
          Subtitle = "I've heard plenty of complaints — and bitter accusations — about how harshly the Legion treats the Charon community. I do everything I can to change that... Maybe someday, people will start to see the Legion in a better light.",
          TalkActionId = {
            [1] = "84101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_2"
        },
        [90210203] = {
          ContentES = "Pero hay muy pocas personas como tú.",
          DialogueId = 90210203,
          GUID = "E1D4EF6E",
          NextDialogue = 90210204,
          SpeakNpcId = 100001,
          Subtitle = "But are there enough people like you to really make a difference?"
        },
        [90210204] = {
          ContentES = "Poco a poco habrá más. Hubo un tiempo en que no había ni un solo Charon en la Legión. Sé que aún no puedo lograr un gran cambio, pero si sigo insistiendo en guiar a mis subordinados por el buen camino, creo que los conflictos entre los Charons y los Solas disminuirán poco a poco.",
          DialogueId = 90210204,
          GUID = "E1D4EF98",
          NextDialogue = 90210205,
          SpeakNpcId = 84101,
          Subtitle = "Not yet. But there will be. There was a time when you wouldn't find even a single Charon in the Legion. I know I can't make a big difference just yet, but if I guide my subordinates down the right path, I believe the conflicts between Charons and Solas will ease, bit by bit.",
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_3"
        },
        [90210205] = {
          ContentES = "Sí, tratar a todos con justicia y protegerlos de los Filthoids y del Deterioro... Creo que estos esfuerzos pueden mejorar la vida de los Charons. Quizás, así se calmarán un poco los pesados suspiros que se oyen en el Lago Helado.",
          DialogueId = 90210205,
          GUID = "E1D4EFC2",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Treating everyone fairly and keeping them safe from Filthoids and Deterioration... I believe these efforts can improve life for the Charon community. Maybe, it will quiet the weary sighs echoing through Icelake a little bit.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90210301] = {
          ContentES = "No diría que es responsabilidad. Simplemente sigo las normas de las Tropas de Escolta.",
          DialogueId = 90210301,
          GUID = "E1D4FF82",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210302,
          SpeakNpcId = 84101,
          Subtitle = "I wouldn't call it responsibility. I'm simply following the Escort's regulations to the letter.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_1"
        },
        [90210302] = {
          ContentES = "Pero los demás soldados no parecen hacer lo mismo, siempre son imprudentes y groseros.",
          DialogueId = 90210302,
          GUID = "E1D4FFAC",
          NextDialogue = 90210303,
          SpeakNpcId = 100001,
          Subtitle = "But the other soldiers don't seem to do the same — they're always so reckless and rude."
        },
        [90210303] = {
          ContentES = "Las normas de la Tropa de Escolta prohíben a cualquier legionario comentar la conducta de sus compañeros.",
          DialogueId = 90210303,
          GUID = "E1D4FFD6",
          NextDialogue = 90210304,
          SpeakNpcId = 84101,
          Subtitle = "The Escort's regulations forbid any legionary from commenting on the conduct of their fellow legionaries.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_2"
        },
        [90210304] = {
          ContentES = "De hecho, no los entiendo. Quizás para ellos es solo un trabajo en las Tropas de Escolta. Mientras sus superiores no se den cuenta, creen que está bien relajarse o hacer tonterías.",
          DialogueId = 90210304,
          GUID = "E1D50000",
          NextDialogue = 90210305,
          SpeakNpcId = 84101,
          Subtitle = "That said, I really don't understand them. Maybe, to them, it's just a job. As long as their superiors don't notice, they think it's fine to slack off or mess around.",
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_3"
        },
        [90210305] = {
          ContentES = "Creo que esa actitud es errónea. La gente necesita algo que la guíe y la modere. Sin eso, simplemente se dejan llevar por la vida, permitiendo que sus valores se vayan deteriorando poco a poco, hasta convertirse en algo tan insignificante como las ratas en las alcantarillas.",
          DialogueId = 90210305,
          GUID = "E1D5002A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "I think that kind of attitude is wrong. People need something to keep themselves in check. Without it, they'll just drift through life, letting their standards erode little by little — until they're no better than rats in the sewers.",
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90210401] = {
          ContentES = "No... Gracias. No me gusta verme en el espejo. Ver mis cuernos siempre me genera una sensación de incomodidad...",
          DialogueId = 90210401,
          GUID = "E1D50FEA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210402,
          SpeakNpcId = 84101,
          Subtitle = "No... Thank you. I don't really enjoy looking at myself in the mirror. Seeing my horns always makes me feel... uncomfortable.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_1"
        },
        [90210402] = {
          ContentES = "¿O sea que no te sientes cómoda con el aspecto del Charon?",
          DialogueId = 90210402,
          GUID = "E1D51014",
          NextDialogue = 90210403,
          SpeakNpcId = 100001,
          Subtitle = "So, you're not comfortable with how Charons look?"
        },
        [90210403] = {
          ContentES = "No, no es eso. No me avergüenza mi herencia Charon. Es solo que... Creo que mis cuernos se verían mucho mejor si fueran más regulares, más simétricos. ¡No me malinterpretes! No digo nada de malo sobre tus cuernos...",
          DialogueId = 90210403,
          GUID = "E1D5103E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "No, that's not it at all. I'm not ashamed of my Charon heritage. It's just... I think my horns would look much better if they were more regular, more symmetrical. Ah, don't get me wrong! I'm not saying there's anything wrong with your horn...",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90210501] = {
          ContentES = "Sí... Pero ahora me parece muy pesada, casi insoportable... No sé si tengo la fuerza para volver a cogerla y tocarla.",
          DialogueId = 90210501,
          GUID = "E1D52052",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210502,
          SpeakNpcId = 84101,
          Subtitle = "I do... but it feels so heavy now, almost unbearably so. I'm not sure I have the strength to pick it up and play anymore.",
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_1"
        },
        [90210502] = {
          ContentES = "Después de todo, alguna vez esta armónica representaba todas mis esperanzas y sueños. Ahora, solo me recuerda todo lo que he perdido.",
          DialogueId = 90210502,
          GUID = "E1D5207C",
          NextDialogue = 90210503,
          SpeakNpcId = 84101,
          Subtitle = "After all, it once carried all my hopes and dreams. Now, it just reminds me of everything I've lost.",
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_2"
        },
        [90210503] = {
          ContentES = "Si algún día vuelves a tocarla, me encantaría ser tu primer oyente.",
          DialogueId = 90210503,
          GUID = "E1D520A6",
          NextDialogue = 90210504,
          SpeakNpcId = 100001,
          Subtitle = "If you ever feel ready to play it again, I'd be honoured to be your first listener."
        },
        [90210504] = {
          ContentES = "... Bueno, gracias. Te prometo que cuando vuelva a tocar, cuando esté lista para aprender una nueva melodía, serás la primera en oírla.",
          DialogueId = 90210504,
          GUID = "E1D520D0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "...Thank you. I promise, when the day comes that I can pick it up again — when I'm ready to learn a new tune — I'll make sure you're the first to hear it.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90210601] = {
          ContentES = "He estado haciendo trabajos ocasionales. Con eso me alcanza para cubrir mis gastos rutinarios. Pero, sinceramente, ganar dinero ya no es lo importante. Ahora, el trabajo me sirve para mantenerme ocupada.",
          DialogueId = 90210601,
          GUID = "E1D530BA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210602,
          SpeakNpcId = 84101,
          Subtitle = "I've been taking on odd jobs here and there. It's enough to cover my expenses. But honestly, earning a living isn't the point anymore. These days, work is more about keeping myself busy.",
          TalkActionId = {
            [1] = "84101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_1"
        },
        [90210602] = {
          ContentES = "¿Mantenerte ocupada?",
          DialogueId = 90210602,
          GUID = "E1D530E4",
          NextDialogue = 90210603,
          SpeakNpcId = 100001,
          Subtitle = "Keeping busy?",
          TalkActionId = {
            [1] = "84101:Talk02_End"
          }
        },
        [90210603] = {
          ContentES = "Sí... El trabajo me da un propósito. Me hace feliz. Cuando estoy ocupada, incluso la luz del sol me parece más cálida.",
          DialogueId = 90210603,
          GUID = "E1D5310E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Yes... Work gives me purpose. It makes me happy. When I'm busy, even the sunlight feels a little warmer.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_2",
          bForbidSkipOptions = true
        },
        [90210701] = {
          ContentES = "Mejor que si me hubiera quedado. La Legión fue mi refugio, el lugar donde creía que mis sueños podían cumplirse realidad. Pero esos sueños se convirtieron en ilusiones, ese supuesto refugio fue un infierno que arrastró a mis seres queridos a un abismo de desesperación sin fin...",
          DialogueId = 90210701,
          GUID = "E1D54122",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210702,
          SpeakNpcId = 84101,
          Subtitle = "Better than if I'd stayed, I suppose. The Legion was once my refuge, the place where I thought my dreams could take flight. But those dreams... they turned out to be illusions, and that so-called refuge was a hell that dragged my loved one into an unending abyss of despair...",
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_1"
        },
        [90210702] = {
          ContentES = "Ahora, mi corazón arde en deseo de venganza, pero no puedo apuntar mi arma contra quienes alguna vez llamé compañeros. Me siento perdida... Dime, ¿qué debo hacer?",
          DialogueId = 90210702,
          GUID = "E1D5414C",
          NextDialogue = 90210703,
          SpeakNpcId = 84101,
          Subtitle = "Now, my heart burns with the desire for vengeance, yet I can't bring myself to aim my weapon at those I once called comrades. I feel lost... Tell me, what should I do?",
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_2"
        },
        [90210703] = {
          ContentES = "Creo que esa es una pregunta a la que solo tú misma puedes responder.",
          DialogueId = 90210703,
          GUID = "E1D54176",
          NextDialogue = 90210704,
          SpeakNpcId = 100001,
          Subtitle = "I think that's a question only you can answer."
        },
        [90210704] = {
          ContentES = "... Disculpa mi pérdida de control. Tienes razón. Debo resolverlo yo misma, en lugar de poner esa carga sobre ti. Aunque... puede que me tome algo de tiempo...",
          DialogueId = 90210704,
          GUID = "E1D541A0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "...Sorry, I lost my cool. You're right — I need to figure it out on my own, instead of placing that weight on you. Though... it might take me some time.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_3",
          bForbidSkipOptions = true
        },
        [90210901] = {
          ContentES = "Esta propuesta es increíblemente detallada, con cada segundo planificado. Seguirla al pie de la letra debe ser muy satisfactorio. Pero... Es difícil creer que el comandante Randy haya preparado algo así.",
          DialogueId = 90210901,
          GUID = "E1D561F2",
          SpeakNpcId = 84101,
          Subtitle = "This proposal is remarkably detailed, down to every second accounted for. Following it through must be immensely satisfying. It's just... hard to believe something like this was put together by Lieutenant Colonel Randy.",
          VoiceName = "voice/$Locale$/char/Lise/vo_companio_02"
        },
        [90220000] = {
          ContentES = "En una tierra tan llena de turbulencias, tener un lugar tan tranquilo para un breve momento de paz es un consuelo excepcional.",
          DialogueId = 90220000,
          GUID = "E1DB36E9",
          SpeakNpcId = 81502,
          Subtitle = "In a land so fraught with turmoil, having such a tranquil place for even a brief moment of peace is a rare comfort.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_idle"
        },
        [90220001] = {
          ContentES = "Ah, eres tú, mi {性别:querido niño|querida niña}. Buenos días. ¿Hay algo que quieras compartir conmigo?",
          DialogueId = 90220001,
          GUID = "E1DB36EA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextOptions = {
            [1] = 902200011,
            [2] = 902200012,
            [3] = 902200013,
            [4] = 902200014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81502,
          Subtitle = "Ah, it's you, my dear child. Good day. Is there something on your mind you'd like to share with me?",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90220002] = {
          Content = "聊点别的",
          DialogueId = 90220002,
          GUID = "90220002.0",
          NextDialogue = 90220001,
          Subtitle = "Let's talk about something else"
        },
        [90220003] = {
          Content = "再见",
          DialogueId = 90220003,
          GUID = "90220003.0",
          Subtitle = "Goodbye"
        },
        [90220101] = {
          ContentES = "Eso es. A lo largo de los incontables años, he viajado -o quizás he vagabundeado- por cada rincón de Atlasia. He pisado cada palmo de su suelo y acariciado con mis dedos cada grano de arena.",
          DialogueId = 90220101,
          GUID = "E1DB4752",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220102,
          SpeakNpcId = 81502,
          Subtitle = "Indeed. Over the course of endless time, I've travelled — or perhaps wandered — through every corner of Atlasia, treading upon every inch of its soil and tracing every grain of sand with my fingertips.",
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_1"
        },
        [90220102] = {
          ContentES = "Entonces, ¿cuál es tu lugar favorito?",
          DialogueId = 90220102,
          GUID = "E1DB477C",
          NextDialogue = 90220103,
          SpeakNpcId = 100001,
          Subtitle = "So, which place is your favourite?",
          TalkActionId = {
            [1] = "81502:Explain01_End"
          }
        },
        [90220103] = {
          ContentES = "Cuando hayas viajado por lo suficiente, te darás cuenta de que el paisaje de todos los lugares no es tan diferente. Ya sean las nieves del Norte, las arenas de Khemet o el humo que sale de las chimeneas en Huaxu, son solo diferentes tonalidades de niebla que rodean el bosque.",
          DialogueId = 90220103,
          GUID = "E1DB47A6",
          NextDialogue = 90220104,
          SpeakNpcId = 81502,
          Subtitle = "Once you've seen enough, you'll find that the scenery of all places is not so different after all. Whether it's the snows of the North, the sands of Khemet, or the smoke curling from the chimneys of Huaxu, they are all but different shades of mist drifting through the forest.",
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_2"
        },
        [90220104] = {
          ContentES = "Si tuviera que elegir... serían las montañas y los bosques de Aethyrie. El aire de allí me trae la mayor paz.",
          DialogueId = 90220104,
          GUID = "E1DB47D0",
          NextDialogue = 90220105,
          SpeakNpcId = 81502,
          Subtitle = "If I had to choose, though... it would be the mountains and forests of Aethyrie. The air there brings me the most peace.",
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_3"
        },
        [90220105] = {
          ContentES = "Algún día tendré que visitarlo.",
          DialogueId = 90220105,
          GUID = "E1DB47FA",
          NextDialogue = 90220106,
          SpeakNpcId = 100001,
          Subtitle = "I'll have to visit someday."
        },
        [90220106] = {
          ContentES = "Quizás lo hagas.",
          DialogueId = 90220106,
          GUID = "E1DB4824",
          NextDialogue = 90220107,
          SpeakNpcId = 81502,
          Subtitle = "Perhaps you will.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_4"
        },
        [90220107] = {
          ContentES = "Si alguna vez te adentras en el Bosque Esmeralda, ¿podrías traerme un ramo de asteres blancos para conmemorar? Bajo aquella tierra reposan mis amigos, mis hijos y una versión de mí misma de antaño.",
          DialogueId = 90220107,
          GUID = "E1DB484E",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Should you wander into the Emerald Forest, would you mind bringing a bouquet of white asters for me? Beneath its earth rest my friends, my child, and a version of myself from long ago.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90220201] = {
          ContentES = "El Mar Nebuloso es la cuna y el descanso final de todos los seres vivos. Al Mar Nebuloso, los difuntos regresan, y desde allí, la vida comienza de nuevo... Igualmente que las nubes que se disuelven en la tierra como lluvia, para que luego florezcan las flores en ese mismo suelo.",
          DialogueId = 90220201,
          GUID = "E1DB57BA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220202,
          SpeakNpcId = 81502,
          Subtitle = "The Misty Sea is the birthplace and final rest of all living beings. To the Misty Sea, the deceased return, and from there, life begins anew... just as dying clouds dissolve into the earth as rain, only for flowers to bloom again from that very soil.",
          TalkActionId = {
            [1] = "81502:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_1"
        },
        [90220202] = {
          ContentES = "¿Yo también iré allí algún día?",
          DialogueId = 90220202,
          GUID = "E1DB57E4",
          NextDialogue = 90220203,
          SpeakNpcId = 100001,
          Subtitle = "Will I go there someday, too?",
          TalkActionId = {
            [1] = "81502:Confident_End"
          }
        },
        [90220203] = {
          ContentES = "Sí, creo que sí, mi {性别:niño|niña}. Un día viajarás al Mar Nebuloso, a los brazos de la Madre Embla.",
          DialogueId = 90220203,
          GUID = "E1DB580E",
          NextDialogue = 90220204,
          SpeakNpcId = 81502,
          Subtitle = "I believe so, my child. One day, you will journey to the Misty Sea, into the embrace of Mother Embla.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_2"
        },
        [90220204] = {
          ContentES = "Eso suena... un poco aterrador.",
          DialogueId = 90220204,
          GUID = "E1DB5838",
          NextDialogue = 90220205,
          SpeakNpcId = 100001,
          Subtitle = "That sounds... a bit scary."
        },
        [90220205] = {
          ContentES = "Mi {性别:querido niño|querida niña}, atesora todo lo que la vida te ofrece, pero no le temas a su final. El final no es sufrimiento, sino la inevitable conclusión del viaje de la vida.",
          DialogueId = 90220205,
          GUID = "E1DB5862",
          NextDialogue = 90220206,
          SpeakNpcId = 81502,
          Subtitle = "My dear child, cherish all that life offers, yet do not shrink from its passing. Demise is not suffering, but the inevitable conclusion of life's journey.",
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_3"
        },
        [90220206] = {
          ContentES = "Si te cansas, descansa en mis brazos un rato... No temas, este no será un sueño eterno. Todavía tienes mucho que cumplir en este mundo.",
          DialogueId = 90220206,
          GUID = "E1DB588C",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Should you ever grow weary, rest in my arms for a while... There is no need to fear — this will not be your eternal sleep. There is still much for you to fulfil in this world.",
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90220301] = {
          ContentES = "¿Te sorprende mucho eso? De hecho, hace mucho tiempo, durante “La Gran Migración”, estuve en primera línea como soldado, experta en combate cuerpo a cuerpo.",
          DialogueId = 90220301,
          GUID = "E1DB6822",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220302,
          SpeakNpcId = 81502,
          Subtitle = "Did that surprise you? Long ago, during the Great Migration, I stood on the front lines as a soldier well-versed in close combat.",
          TalkActionId = {
            [1] = "81502:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_1"
        },
        [90220302] = {
          ContentES = "Aunque esos días quedaron atrás, aún recuerdo las habilidades fundamentales del combate.",
          DialogueId = 90220302,
          GUID = "E1DB684C",
          NextDialogue = 90220303,
          SpeakNpcId = 81502,
          Subtitle = "Though those days are far behind me, I still remember the essentials of fighting.",
          TalkActionId = {
            [1] = "81502:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_2"
        },
        [90220303] = {
          ContentES = "Durante mi viaje, me enfrenté a menudo a las bestias salvajes. Sus garras y colmillos me dejaron cicatrices, moretones e incluso sufrí heridas de las que debí haber muerto.",
          DialogueId = 90220303,
          GUID = "E1DB6876",
          NextDialogue = 90220304,
          SpeakNpcId = 81502,
          Subtitle = "During my wanderings, I've often faced roaming beasts. Their claws and fangs have left me with scars, bruises, and even deaths I should have rightfully endured.",
          TalkActionId = {
            [1] = "81502:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_3"
        },
        [90220304] = {
          ContentES = "Es difícil imaginarte luchando cuerpo a cuerpo.",
          DialogueId = 90220304,
          GUID = "E1DB68A0",
          NextDialogue = 90220305,
          SpeakNpcId = 100001,
          Subtitle = "It's hard to picture you grappling hand-to-hand...",
          TalkActionId = {
            [1] = "81502:Talk02_End"
          }
        },
        [90220305] = {
          ContentES = "Incluso la luna eterna mengua y crece, en constante cambio. Los humanos, naturalmente, son mucho más complejos, especialmente alguien que ha vivido incontables vidas más allá de la existencia mortal.",
          DialogueId = 90220305,
          GUID = "E1DB68CA",
          NextDialogue = 90220306,
          SpeakNpcId = 81502,
          Subtitle = "Even the eternal moon wanes and waxes, ever changing. Humans, naturally, are far more complex — especially one who's lived countless lifetimes beyond a mortal span.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_4"
        },
        [90220306] = {
          ContentES = "Si tienes curiosidad por saber sobre aquellos días, te los contaré con detalle otro día.",
          DialogueId = 90220306,
          GUID = "E1DB68F4",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "If you're curious about those days, I'll recount them in detail for you another time.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90220401] = {
          ContentES = "“Amigos”... Según la definición común de esta palabra, he tenido muchos amigos a lo largo de mi vida.",
          DialogueId = 90220401,
          GUID = "E1DB788A",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220402,
          SpeakNpcId = 81502,
          Subtitle = "\"Friends\"... By the common definition of the word, I've had many over my long years.",
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_1"
        },
        [90220402] = {
          ContentES = "Sin embargo, cuando oigo esa palabra, los primeros en venirme a la mente son Lexis y Erika, quienes me sacaron de Elysium.",
          DialogueId = 90220402,
          GUID = "E1DB78B4",
          NextDialogue = 90220403,
          SpeakNpcId = 81502,
          Subtitle = "Yet when I hear that word, the first who come to mind are Lexis and Erika, the two who once led me away from Elysium.",
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_2"
        },
        [90220403] = {
          ContentES = "¿Cómo eran?",
          DialogueId = 90220403,
          GUID = "E1DB78DE",
          NextDialogue = 90220404,
          SpeakNpcId = 100001,
          Subtitle = "What were they like?"
        },
        [90220404] = {
          ContentES = "En los anales de la historia y los relatos de héroes, suelen ser retratados como el Sabio que desveló el velo de ignorancia de los dioses, y la Heroína que dio su vida por la causa del Sabio...",
          DialogueId = 90220404,
          GUID = "E1DB7908",
          NextDialogue = 90220405,
          SpeakNpcId = 81502,
          Subtitle = "In the annals of history and the tales of heroes, they're often portrayed as the Sage who tore away the gods' veil of ignorance, and the Heroine who gave her life for the Sage's cause...",
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_3"
        },
        [90220405] = {
          ContentES = "Pero en mis recuerdos, simplemente eran Lexis y Erika.",
          DialogueId = 90220405,
          GUID = "E1DB7932",
          NextDialogue = 90220406,
          SpeakNpcId = 81502,
          Subtitle = "But in my memories, they are simply Lexis and Erika.",
          TalkActionId = {
            [1] = "81502:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_4"
        },
        [90220406] = {
          ContentES = "Erika era una joven chica valiente y vivaz, con un espíritu que atraía a todos. Lexis, aunque brillante, solía reflexionar demasiado. Se sumía en profundas reflexiones repentinamente, lo que, paradójicamente, le hacía parecer un poco lento.",
          DialogueId = 90220406,
          GUID = "E1DB795C",
          NextDialogue = 90220407,
          SpeakNpcId = 81502,
          Subtitle = "Erika was a brave and lively young woman, with a spirit that drew everyone to her. Lexis, though brilliant, often overthought things. He'd suddenly lapse into deep musings, which, ironically, made him seem a bit slow.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_5"
        },
        [90220407] = {
          ContentES = "¿Recuerdas alguna anécdota divertida?",
          DialogueId = 90220407,
          GUID = "E1DB7986",
          NextDialogue = 90220408,
          SpeakNpcId = 100001,
          Subtitle = "Any fun stories?"
        },
        [90220408] = {
          ContentES = "Humm... Una vez, Lexis intentó disculparse con Erika por algo que había hecho. Por capricho, ella señaló uno de los blancos de entrenamiento de los soldados y le dijo que lo perdonaría si lograba dar en la diana...",
          DialogueId = 90220408,
          GUID = "E1DB79B0",
          NextDialogue = 90220409,
          SpeakNpcId = 81502,
          Subtitle = "Mm... There was one time Lexis tried to apologize to Erika for something he'd done. On a whim, she pointed to one of the soldiers' archery training dummies, saying she'd forgive him if he could hit the bullseye...",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_6"
        },
        [90220409] = {
          ContentES = "Por supuesto, ella no lo decía en serio. Ni siquiera todos los soldados podían lograrlo, por no hablar de Lexis, cuyas manos eran para la pluma y el pergamino, no para el arco ni la espada.",
          DialogueId = 90220409,
          GUID = "E1DB79DA",
          NextDialogue = 90220410,
          SpeakNpcId = 81502,
          Subtitle = "Of course, she didn't mean it seriously. Not even all the soldiers could manage it, let alone Lexis, whose hands were meant for quills and scrolls, not bows or blades.",
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_7"
        },
        [90220410] = {
          ContentES = "Pero se tomó sus palabras muy en serio. Después de que los soldados se marcharon, se quedó y practicó solo toda la noche.",
          DialogueId = 90220410,
          GUID = "E1DB7A04",
          NextDialogue = 90220411,
          SpeakNpcId = 81502,
          Subtitle = "But he took her words to heart. After the soldiers left, he stayed behind and practised alone, long into the night.",
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_8"
        },
        [90220411] = {
          ContentES = "Como imaginarás, la verdadera historia no es un relato de héroes omnipotentes. Incluso alguien tan brillante como Lexis tenía sus límites, practicó hasta que le sangraron las palmas. Erika terminó envolviéndolas con lino, pero él nunca dio en la diana.",
          DialogueId = 90220411,
          GUID = "E1DB7A2E",
          NextDialogue = 90220412,
          SpeakNpcId = 81502,
          Subtitle = "As you might guess, true history is not a tale of omnipotent heroes. Even someone as brilliant as Lexis had his limits — he practised until his palms bled. Erika ended up wrapping them in linen, but he never did strike the mark.",
          TalkActionId = {
            [1] = "81502:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_9"
        },
        [90220412] = {
          ContentES = "Jeje... Lo interesante es que ni siquiera recuerdo por qué discutieron. Es tan extraño... Ahora, cuando pienso en ellos, lo primero que me viene a la mente son esos pequeños detalles insignificantes.",
          DialogueId = 90220412,
          GUID = "E1DB7A58",
          NextDialogue = 90220413,
          SpeakNpcId = 81502,
          Subtitle = "The funny thing is, I can't even recall why they argued in the first place. Strange, isn't it? When I think of them now, it's always these small, insignificant details that come to mind first.",
          TalkActionId = {
            [1] = "81502:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_10"
        },
        [90220413] = {
          ContentES = "Suenan como unos tiempos maravillosos.",
          DialogueId = 90220413,
          GUID = "E1DB7A82",
          NextDialogue = 90220414,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like some golden memories."
        },
        [90220414] = {
          ContentES = "Así es. Efectivamente... Fueron unos días maravillosos y llenos de alegría. Pero ya quedaron en el pasado.",
          DialogueId = 90220414,
          GUID = "E1DB7AAC",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Indeed. Those were such precious, joyful days... But they are far behind me now.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_11",
          bForbidSkipOptions = true
        },
        [90220501] = {
          ContentES = "Ninguno podrá escapar de su pasado para siempre. Con el tiempo, tendrás que enfrentarte a él... Que tengas la fuerza para confrontarlo cuando llegue ese momento.",
          DialogueId = 90220501,
          GUID = "E1DB88F2",
          SpeakNpcId = 81502,
          Subtitle = "No soul can outrun its past forever. In time, you will have to confront yours. May you have the strength to face it when that moment arrives.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_01"
        },
        [90220601] = {
          ContentES = "Querida, llevas un aura que me resulta muy familiar. ¿Será que tú, como yo, provienes de días pasados?",
          DialogueId = 90220601,
          GUID = "E1DB995A",
          SpeakNpcId = 81502,
          Subtitle = "My dear, you carry an aura I find quite familiar. Could it be that you, like me, hail from bygone days?",
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_02"
        },
        [90230000] = {
          ContentES = "Le pedí a mi secretaria que me liberara la agenda para los próximos días. Por ahora, solo deseo disfrutar de esta tranquilidad a tu lado, lejos del bullicio del mundo. ¿Es sinceridad u otra estrategia? ¿Qué opinas?",
          DialogueId = 90230000,
          GUID = "E1E19F60",
          SpeakNpcId = 84102,
          Subtitle = "I had my secretary clear my schedule for the next few days. For now, I wish only to savour this tranquillity with you, untouched by the clamour of the outside world. Is this out of sincerity, or another calculated move? Why don't you take a guess?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_idle"
        },
        [90230001] = {
          ContentES = "Has venido a verme... {性别:¿Todavía estás enfadado? ¿Confundido?|¿Todavía estás enfadada? ¿Confundida?} ¿O sea, te has vuelto indiferente a mí? Da igual. Tenemos mucho tiempo para discutirlo.",
          DialogueId = 90230001,
          GUID = "E1E19F8A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextOptions = {
            [1] = 902300011,
            [2] = 902300012,
            [3] = 902300013,
            [4] = 902300014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84102,
          Subtitle = "Ah, so you've come to see me... Are you still resentful? Conflicted, perhaps? Or have you become indifferent toward me? It makes no difference. We have all the time in the world to figure it out.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90230002] = {
          Content = "聊点别的",
          DialogueId = 90230002,
          GUID = "E1E19FB4",
          NextDialogue = 90230001,
          Subtitle = "Let's talk about something else"
        },
        [90230003] = {
          Content = "再见",
          DialogueId = 90230003,
          GUID = "E1E19FDE",
          Subtitle = "Goodbye"
        },
        [90230101] = {
          ContentES = "Nada es ajeno a una negociación. La única pregunta es: ¿qué precio hará que la balanza se incline a tu favor?",
          DialogueId = 90230101,
          GUID = "E1E1AFF2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230102,
          SpeakNpcId = 84102,
          Subtitle = "There is nothing that cannot be leveraged in a negotiation. The only question is — what price will move the scales in your favour?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_1"
        },
        [90230102] = {
          ContentES = "¿Incluso si el precio es tu vida?",
          DialogueId = 90230102,
          GUID = "E1E1B01C",
          NextDialogue = 90230103,
          SpeakNpcId = 100001,
          Subtitle = "Even when the price is your life?"
        },
        [90230103] = {
          ContentES = "Efectivamente. Tu vida, la mía y la de las incontables personas más: cada una es solo una pieza en un tablero mayor, cuyo valor depende únicamente de lo que esté en juego.",
          DialogueId = 90230103,
          GUID = "E1E1B046",
          NextDialogue = 90230104,
          SpeakNpcId = 84102,
          Subtitle = "Indeed. Your life, mine, and the lives of countless others — each is but a piece on a grander board, their worth determined only by the stakes at play.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_2"
        },
        [90230104] = {
          ContentES = "Para quienes somos tan insignificantes, intercambiar lo poco que tenemos por lo que deseamos, también es una gran fortuna.",
          DialogueId = 90230104,
          GUID = "E1E1B070",
          NextDialogue = 90230105,
          SpeakNpcId = 84102,
          Subtitle = "For those as insignificant as we, to exchange what little we have for what we desire... is that not, in itself, a stroke of fortune?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_3"
        },
        [90230105] = {
          ContentES = "¿Mi respuesta te incomoda? Entonces, por favor, demuéstrame que me equivoco.",
          DialogueId = 90230105,
          GUID = "E1E1B09A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "Does my answer unsettle you? Then, by all means, prove me wrong.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90230201] = {
          ContentES = "Humm... Nunca te centres solo en las ganancias y pérdidas momentáneas. Piensa a largo plazo. Sé generoso cuando sea necesario. Aprende a comprender a las personas, a usarlas y a hacerles favores, para que te respeten, te admiren y también te teman.",
          DialogueId = 90230201,
          GUID = "E1E1C05A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230202,
          SpeakNpcId = 84102,
          Subtitle = "Mmm... Never lose yourself in fleeting profits and losses. Play the long game. Be generous when needed. Learn to read people, to use them, and to grant them favours, so that they respect you, admire you, and also fear you. True power lies in that delicate balance.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_1"
        },
        [90230202] = {
          ContentES = "Eso no es lo que pensaba en mi mente.",
          DialogueId = 90230202,
          GUID = "E1E1C084",
          NextDialogue = 90230203,
          SpeakNpcId = 100001,
          Subtitle = "That's not quite what I had in mind."
        },
        [90230203] = {
          ContentES = "Jeje. Los productos tienen precios fijos, pero las relaciones humanas son una moneda completamente diferente. Quienes regatean por cada moneda, permanecerán siempre atados a su pequeño rincón. Solo dominando el arte de la influencia, se puede elevar por encima del mero comercio y alcanzar hasta la verdadera grandeza.",
          DialogueId = 90230203,
          GUID = "E1E1C0AE",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "Heh. Goods have fixed prices, but human connections are a different currency altogether. Those who haggle over every coin will remain forever bound to their little corner of the market. Only by mastering the art of influence can one rise above mere trade and ascend to true greatness.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90230301] = {
          ContentES = "A menudo estoy metido en los detalles de los negocios, rara vez tengo tiempo libre. El tiempo libre es un lujo para mí.",
          DialogueId = 90230301,
          GUID = "E1E1D0C2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230302,
          SpeakNpcId = 84102,
          Subtitle = "I am often entangled in the minutiae of business and rarely afforded the luxury of leisure.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_1"
        },
        [90230302] = {
          ContentES = "Sin embargo, si me concediera un breve respiro... probablemente buscaría consuelo en el teatro. Ya sean las antiguas tradiciones narrativas de Huaxu, las refinadas óperas del Imperio o las películas de vanguardia que triunfan en el extranjero, cada una me interesa.",
          DialogueId = 90230302,
          GUID = "E1E1D0EC",
          NextDialogue = 90230303,
          SpeakNpcId = 84102,
          Subtitle = "Yet, if fate were to grant me a fleeting moment of respite... I would likely seek solace in the theatre. Be it the age-old storytelling traditions of Huaxu, the refined operas of the Empire, or the avant-garde films gaining traction overseas — each offers its own intrigue.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_2"
        },
        [90230303] = {
          ContentES = "Parece que nuestro encuentro en el teatro no fue casual.",
          DialogueId = 90230303,
          GUID = "E1E1D116",
          NextDialogue = 90230304,
          SpeakNpcId = 100001,
          Subtitle = "It seems our meeting at the theatre wasn't just a coincidence, then."
        },
        [90230304] = {
          ContentES = "Jeje... Supongo que no. El teatro capta momentos fugaces de la vida, pero en esos momentos fugaces se revelan las profundas verdades sobre la naturaleza humana. La naturaleza humana es algo que desafía la lógica, prospera en la contradicción y resulta fascinante por su imprevisibilidad.",
          DialogueId = 90230304,
          GUID = "E1E1D140",
          NextDialogue = 90230305,
          SpeakNpcId = 84102,
          Subtitle = "Heh... No, I suppose not. Theatre distils fleeting moments of life, yet within those fragments, it unveils profound truths about the human soul — one that defies reason, thrives in contradiction, and remains endlessly captivating in its unpredictability.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_3"
        },
        [90230305] = {
          ContentES = "¿Qué sorpresas inesperadas me traerás? Estaré atenta.",
          DialogueId = 90230305,
          GUID = "E1E1D16A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "So, what unexpected turns will you bring to my story? I shall be watching with keen interest.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90230401] = {
          ContentES = "¿Eh? ¿Lo has notado? Es un viejo hábito, nada más.",
          DialogueId = 90230401,
          GUID = "E1E1E12A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230402,
          SpeakNpcId = 84102,
          Subtitle = "Hmm? So, you've noticed. An old habit, nothing more.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_1"
        },
        [90230402] = {
          ContentES = "De pequeña, un accidente me dejó atrapada en un barranco a oscuras durante tres días y tres noches. Ahí se originó este... malo hábito.",
          DialogueId = 90230402,
          GUID = "E1E1E154",
          NextDialogue = 90230403,
          SpeakNpcId = 84102,
          Subtitle = "When I was little, an accident left me stranded in a pitch-black ravine for three days and nights. It was then this... tendency took root.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_2"
        },
        [90230403] = {
          ContentES = "En este mundo, todos tenemos nuestros miedos. Yo no soy la excepción... Parece {性别:sorprendido|sorprendida}. ¿Por qué?",
          DialogueId = 90230403,
          GUID = "E1E1E17E",
          NextDialogue = 90230404,
          SpeakNpcId = 84102,
          Subtitle = "In this world, everyone harbours their own fears. I am no exception... You seem surprised. May I ask why?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_3"
        },
        [90230404] = {
          ContentES = "Solo pensaba... que no pareces una persona que tenga miedos o debilidades.",
          DialogueId = 90230404,
          GUID = "E1E1E1A8",
          NextDialogue = 90230405,
          SpeakNpcId = 100001,
          Subtitle = "I just thought... you don't seem like someone who has fears or weaknesses."
        },
        [90230405] = {
          ContentES = "Jeje... Tiene razón. Las debilidades pueden ser fatales para un comerciante.",
          DialogueId = 90230405,
          GUID = "E1E1E1D2",
          NextDialogue = 90230406,
          SpeakNpcId = 84102,
          Subtitle = "Heh... Correct. Weakness can be a merchant's undoing.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_4"
        },
        [90230406] = {
          ContentES = "Me entrené rigurosamente para suprimir este defecto. En las negociaciones, puedo controlarlo fácilmente en todo momento. Pero en su presencia, no hay necesidad de fingir.",
          DialogueId = 90230406,
          GUID = "E1E1E1FC",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "I underwent rigorous trainings to suppress this fear. At the negotiating table, I can cast it aside with ease. But in your presence, there's no need for such pretences.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_5",
          bForbidSkipOptions = true
        },
        [90230501] = {
          ContentES = "Su perfume tiene una dulzura audaz y embriagadora, sin reservas ni disculpas. Contrasta enormemente con las fragancias sutiles de Huaxu. Me interesa mucho.",
          DialogueId = 90230501,
          GUID = "E1E1F192",
          SpeakNpcId = 84102,
          Subtitle = "Your perfume carries a bold, intoxicating sweetness — unrestrained, unapologetic. A striking contrast to the subtle fragrances of Huaxu. I'm intrigued.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_01"
        },
        [90230601] = {
          ContentES = "He visto una sombra de alguien a quien conocí.. No, debo estar equivocado. No me haga caso.",
          DialogueId = 90230601,
          GUID = "E1E201FA",
          SpeakNpcId = 84102,
          Subtitle = "I saw a trace of someone I once knew in you... No, I must be mistaken. Pay me no mind.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_03"
        },
        [90240000] = {
          ContentES = "Es un lugar luminoso y espacioso. Sería perfecto para practicar esgrima si no hubiera tantas mesas y sillas en el camino.",
          DialogueId = 90240000,
          GUID = "E1E80800",
          SpeakNpcId = 81503,
          Subtitle = "Bright and roomy — would be a perfect spot for sparring if there weren't so many tables and chairs in the way.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_idle"
        },
        [90240001] = {
          ContentES = "¡Hoy es un día perfecto para beber y cantar! Ven, déjame terminar mi vaso y luego iremos a matar los pecadores que merecen mi espada. ¿Qué? ¿Ya dije lo mismo ayer? Bueno, cada día es bueno para vivir así, ¿no estás de acuerdo?",
          DialogueId = 90240001,
          GUID = "E1E8082A",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextOptions = {
            [1] = 902400011,
            [2] = 902400012,
            [3] = 902400013,
            [4] = 902400014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81503,
          Subtitle = "Today's perfect for drinking and singing! Come on, let me finish this glass, and then we'll chase down the sinners who deserve my sword. What? I said the same thing yesterday? Well, every day's a fine day to live like this, don't you think?",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_welcome",
          bForbidSkipOptions = true
        },
        [90240002] = {
          Content = "聊点别的",
          DialogueId = 90240002,
          GUID = "E1E80854",
          NextDialogue = 90240001,
          Subtitle = "Let's talk about something else"
        },
        [90240003] = {
          Content = "再见",
          DialogueId = 90240003,
          GUID = "E1E8087E",
          Subtitle = "Goodbye"
        },
        [90240101] = {
          ContentES = "¿A ti también te interesa la esgrima? Lo imagino, veo que tienes una espada muy buena. Debes ser muy hábil con ella. ¡Vamos a tener un combate de práctica amistoso y veamos qué tal lo haces!",
          DialogueId = 90240101,
          GUID = "E1E81892",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240102,
          SpeakNpcId = 81503,
          Subtitle = "You're into swordplay too? Figured as much — you've got a fine blade there. You must be pretty good with it. Let's have a friendly spar and see what you've got!",
          TalkActionId = {
            [1] = "81503:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_1"
        },
        [90240102] = {
          ContentES = "Sinceramente, ha pasado mucho tiempo desde que conocí a alguien realmente a mi nivel. Mi maestro siempre decía que yo necesitaba más entrenamiento porque era demasiado directo y que debería mejorar mi actuación.",
          DialogueId = 90240102,
          GUID = "E1E818BC",
          NextDialogue = 90240103,
          SpeakNpcId = 81503,
          Subtitle = "Honestly, it's been ages since I've met anyone truly on par with me. Though, my shifu always said I need more honing because I'm too blunt — and that I should work on my acting.",
          TalkActionId = {
            [1] = "81503:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_2"
        },
        [90240103] = {
          ContentES = "¿La actuación también forma parte de la esgrima?",
          DialogueId = 90240103,
          GUID = "E1E818E6",
          NextDialogue = 90240104,
          SpeakNpcId = 100001,
          Subtitle = "Is acting part of swordsmanship?"
        },
        [90240104] = {
          ContentES = "No creo que sí, pero mi maestro siempre decía que la esgrima no se trata solo de la habilidad, sino de la actuación, como “Ocultar tu fuerza fingiendo debilidad”, “Dominar al enemigo sin luchar” y “Derrotar a pocos con muchos”. Esas también son las técnicas de esgrima superiores.",
          DialogueId = 90240104,
          GUID = "E1E81910",
          NextDialogue = 90240105,
          SpeakNpcId = 81503,
          Subtitle = "Not exactly how I see it, but he always said that swordsmanship isn't just about skill; it's about strategy. Stuff like \"conceal your strength by feigning weakness,\" \"subdue the enemy without fighting,\" and \"overwhelm the few with the many.\" Said that's what separates the good from the great.",
          TalkActionId = {
            [1] = "81503:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_3"
        },
        [90240105] = {
          ContentES = "Cuando era niño, él me hacía la misma broma. Decía que sus habilidades eran mediocres y me decía que, si lograba derribarlo, no tendría que entrenar más. Tardé un año en darme cuenta de que ni siquiera podía tocarle la manga.",
          DialogueId = 90240105,
          GUID = "E1E8193A",
          NextDialogue = 90240106,
          SpeakNpcId = 81503,
          Subtitle = "Back when I was a kid, he used to pull that same trick on me. He'd claim his skills were mediocre and tell me if I could knock him down, I wouldn't have to train anymore. Took me a whole year to realize I couldn't even touch his sleeve.",
          TalkActionId = {
            [1] = "81503:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_4"
        },
        [90240106] = {
          ContentES = "Hasta un día, estuve tan agotado que me desplomé en el suelo. Entonces me di cuenta: no había ni una gota de sudor a sus pies. ¿Su aspecto torpe y vacilante? Todo era un acto.",
          DialogueId = 90240106,
          GUID = "E1E81964",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "One day, I was so wiped out I just collapsed. That's when I noticed — not a single drop of sweat beneath his feet. That doddering, clumsy look of his? All an act.",
          TalkActionId = {
            [1] = "81503:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90240201] = {
          ContentES = "Muchas razones, en realidad, pero para resumirlo: odio estar atado por ellas.",
          DialogueId = 90240201,
          GUID = "E1E828FA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240202,
          SpeakNpcId = 81503,
          Subtitle = "Plenty of reasons, really, but if I had to sum it up: I hate being bound by them.",
          TalkActionId = {
            [1] = "81503:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_1"
        },
        [90240202] = {
          ContentES = "He sido un espíritu libre toda mi vida, haciendo las cosas a mi manera, desenvainando mi espada ante cualquier injusticia. Solo escuchaba lo que quería oír de mi maestro o Yuming. El resto... entraba por un oído y me salía por el otro, como el viento. Así que dime, ¿por qué iba a dejarme encadenar por unas leyes?",
          DialogueId = 90240202,
          GUID = "E1E82924",
          NextDialogue = 90240203,
          SpeakNpcId = 81503,
          Subtitle = "I've been free-spirited all my life, doing everything my way, drawing my sword wherever I saw injustice. I only ever listened to what I wanted to hear from my Shifu or Yuming. The rest? In one ear and out the other, like the wind passing by. So tell me, why would I let myself be chained by some laws?",
          TalkActionId = {
            [1] = "81503:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_2"
        },
        [90240203] = {
          ContentES = "Entonces, dime la razón principal.",
          DialogueId = 90240203,
          GUID = "E1E8294E",
          NextDialogue = 90240204,
          SpeakNpcId = 100001,
          Subtitle = "Tell me the biggest reason then."
        },
        [90240204] = {
          ContentES = "Diría que es la preocupación de un espadachín. Por ejemplo: cuando uno aprende esgrima, sigue al pie de la letra el manual de técnicas, ¿Verdad? Contra oponentes comunes, eso basta. La espada se mueve de forma instantánea.",
          DialogueId = 90240204,
          GUID = "E1E82978",
          NextDialogue = 90240205,
          SpeakNpcId = 81503,
          Subtitle = "I'd say it's the concern of a swordsman. Think of it this way — when you first learn swordsmanship, you follow the swordplay scroll move by move, right? Against regular foes, that's enough. Your sword moves instinctively.",
          TalkActionId = {
            [1] = "81503:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_3"
        },
        [90240205] = {
          ContentES = "Pero si te apegas demasiado al manual, no sabes reaccionar, tu espada no es mejor que un pedazo de chatarra: roma, torpe e inútil. Ante algo inesperado, te verás como un pollo sin cabeza, dando vueltas sin rumbo.",
          DialogueId = 90240205,
          GUID = "E1E829A2",
          NextDialogue = 90240206,
          SpeakNpcId = 81503,
          Subtitle = "But if you stick too closely to the scroll and can't think on your feet, your sword's no better than a lump of scrap — dull, clumsy, useless. Face something unexpected, and you'll flail around like a headless chicken.",
          TalkActionId = {
            [1] = "81503:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_4"
        },
        [90240206] = {
          ContentES = "En mi opinión, el Huaxu actual es como un espadachín torpe, aferrado a sus «Nueve Capítulos de Dafeng». Ni siquiera pueden derrotar un errante como yo, ¿qué oportunidad tendrán contra una verdadera amenaza? Solo es cuestión de tiempo para que caigan.",
          DialogueId = 90240206,
          GUID = "E1E829CC",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "To me, Huaxu is like a clumsy swordsman glued to their Nine Chapters of Dafeng. They can't even deal with a Drifter like me — what chance do they have against a true threat? It's only a matter of time before they fall.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_5",
          bForbidSkipOptions = true
        },
        [90240301] = {
          ContentES = "¡Por supuesto! Ser bueno en la espada no significa que solo puedas usarla. En Huaxu, hay gente que usa plumas y palillos como armas; ¿acaso eso significa que los espadachines deben morir de hambre o no pueden escribir nunca?",
          DialogueId = 90240301,
          GUID = "E1E83962",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240302,
          SpeakNpcId = 81503,
          Subtitle = "Of course! Being good with a sword doesn't mean you're stuck using only it. In Huaxu, there are people who can use pens and chopsticks as weapons — does that mean swordsmen are supposed to starve or never write?",
          TalkActionId = {
            [1] = "81503:Agree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_1"
        },
        [90240302] = {
          ContentES = "¡Qué lástima! Esperaba que pudieras cortar una bala por la mitad con tu espada.",
          DialogueId = 90240302,
          GUID = "E1E8398C",
          NextDialogue = 90240303,
          SpeakNpcId = 100001,
          Subtitle = "That's disappointing. I was hoping you could do stuff like slicing a bullet in half with your sword."
        },
        [90240303] = {
          ContentES = "Oh, puedo hacerlo. Pero ¿para qué? Esquivarlo es mucho más fácil, después de todo. Incluso los jabalíes en el bosque saben que es mejor comer rábanos que corteza de árbol.",
          DialogueId = 90240303,
          GUID = "E1E839B6",
          NextDialogue = 90240304,
          SpeakNpcId = 81503,
          Subtitle = "Oh, I can do that. But why bother? Dodging is way easier, after all. Even boars in the woods know to go for radishes over tree bark when they can.",
          TalkActionId = {
            [1] = "81503:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_2"
        },
        [90240304] = {
          ContentES = "Por supuesto, si alguna vez me encuentro con un oponente digno, puedes apostar a que sacaré mi espada y daré el cien por cien.",
          DialogueId = 90240304,
          GUID = "E1E839E0",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "That said, if I ever meet a worthy opponent, you can bet I'll draw my sword and go all out.",
          TalkActionId = {
            [1] = "81503:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90240401] = {
          ContentES = "Sí, efectivamente. Ahora que lo mencionas, recuerdo varios. Hay cosas como “Rey Fulano”, “Señor de Tal” o “Inmortal de Cual”. Los animales son lo más común, como: dragones, tigres, leones, grullas... ¡de todo! Es como un parque zoológico.",
          DialogueId = 90240401,
          GUID = "E1E849CA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240402,
          SpeakNpcId = 81503,
          Subtitle = "They sure do. Now that you mention it, I can think of quite a few. Stuff like \"King So-and-So,\" \"Lord Something,\" or \"Immortal This-and-That.\" Animals are the go-to — dragons, tigers, lions, cranes, you name it. It's like a whole zoo out there.",
          TalkActionId = {
            [1] = "81503:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_1"
        },
        [90240402] = {
          ContentES = "Así funciona: cuanto más largo sea el apodo, peores serán las habilidades. Con un apodo más largo, seguramente es un principiante. Con uno ni largo ni corto, no está mal. Con uno corto, es alguien con quien no conviene meterte. Y los que no tienen apodo, son los verdaderos maestros.",
          DialogueId = 90240402,
          GUID = "E1E849F4",
          NextDialogue = 90240403,
          SpeakNpcId = 81503,
          Subtitle = "Here's how it works: the longer the title, the lousier the skills. Four words? A newbie. Three? Not bad. Two — that's someone you don't want to mess with. And those with no nickname at all? They're the true grandmasters.",
          TalkActionId = {
            [1] = "81503:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_2"
        },
        [90240403] = {
          ContentES = "¿Pues, Kezhou es tu nombre real o un apodo?",
          DialogueId = 90240403,
          GUID = "E1E84A1E",
          NextDialogue = 90240404,
          SpeakNpcId = 100001,
          Subtitle = "So is Kezhou your real name or a nickname?"
        },
        [90240404] = {
          ContentES = "Por supuesto es mi nombre real. Sé que suena raro, como un apodo, ¿verdad? Incluso mi maestro solía decirme eso, me advertía que con un nombre así la gente me tomaría por un experto y eso solo me traería molestias.",
          DialogueId = 90240404,
          GUID = "E1E84A48",
          NextDialogue = 90240405,
          SpeakNpcId = 81503,
          Subtitle = "I walk this world with my real name, of course. I know, it sounds made-up, doesn't it? Even my shifu used to say so — warned me that a name like this would have people mistaking me for some prodigy, and that'd only bring me trouble.",
          TalkActionId = {
            [1] = "81503:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_3"
        },
        [90240405] = {
          ContentES = "Pero es el nombre que me puso mi padre. Quizás esperaba que creciera para convertirme en un héroe. No me dejó mucho, pero llevar este nombre me hace sentir como si su espada aún dejara huella en el mundo.",
          DialogueId = 90240405,
          GUID = "E1E84A72",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "But it's the name my old man gave me. Maybe he hoped I'd grow up to be some kind of hero. He didn't leave much behind, but carrying this name feels like his sword still leaves its mark on the world.",
          TalkActionId = {
            [1] = "81503:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90240601] = {
          ContentES = "Por ahora, me quedaré con tu vieja espada. Cuando dejes de andar deprimido y con esa cara larga, te la devolveré. Pero solo si me ganas en un duelo. Si pierdes, será mía para siempre.",
          DialogueId = 90240601,
          GUID = "E1E86A9A",
          SpeakNpcId = 81503,
          Subtitle = "I'm holding onto your old sword for now. When you stop moping around with that gloomy face, I'll give it back — but only if you beat me in a duel. Lose, and it's mine for good.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_02"
        },
        [90240701] = {
          ContentES = "Una espada puede ser una compañera, un juguete o una herramienta para todo tipo de cosas: cortar, abrir o afeitar. Pero nunca debe ser tu amo. No dejes que esa espada te frene en tu camino.",
          DialogueId = 90240701,
          GUID = "E1E87B02",
          SpeakNpcId = 81503,
          Subtitle = "A sword can be a friend, a toy, or even a tool for all sorts of things — cutting, prying, shaving. But it should never be your master. Don't let that blade hold you back.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_03"
        },
        [90250000] = {
          ContentES = "¡Samael, hace un día precioso afuera! ¿No es este el clima perfecto para comer algo frío? He oído que la Ciudad Sagrada tiene un postre increíble llamado helado. Es una comida de plebeyos, pero apuesto a que es mucho más sabrosa que cualquier cosa que repartan esos viejos carcas. ¡Te conseguiré un poco en secreto!",
          DialogueId = 90250000,
          GUID = "E1EE70A0",
          SpeakNpcId = 81501,
          Subtitle = "Samael, it's a beautiful day outside! Isn't this the perfect weather to eat something cool? I've heard the Holy City has an amazing dessert called ice cream. It's a commoner's food, but I bet it's way tastier than anything those old farts are handing out. I'll secretly grab you some!",
          VoiceName = "voice/$Locale$/char/Baonu/vo_idle"
        },
        [90250001] = {
          ContentES = "¡Hola! Estoy sacando a Samael a tomar un poco de aire fresco, absorbiendo la luz del sol, sintiendo este lugar juntos. ¿Quieres saludarlo?¡Estará encantado! ...Bueno, ¡probablemente! Jeje~",
          DialogueId = 90250001,
          GUID = "E1EE70CA",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextOptions = {
            [1] = 90250100,
            [2] = 90250200,
            [3] = 90250300,
            [4] = 90250400
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81501,
          Subtitle = "Hey! I'm taking Samael out for some fresh air — soaking up the sunlight, getting a feel for this place together. Wanna say hi? It'll be thrilled! ...Well, probably! Hehe~",
          VoiceName = "voice/$Locale$/char/Baonu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90250002] = {
          Content = "聊点别的",
          DialogueId = 90250002,
          GUID = "E1EE70F4",
          NextDialogue = 90250001,
          Subtitle = "Let's talk about something else"
        },
        [90250003] = {
          Content = "再见",
          DialogueId = 90250003,
          GUID = "E1EE711E",
          Subtitle = "Goodbye"
        },
        [90250100] = {
          ContentES = "Tu arma parece bastante poderosa...",
          DialogueId = 90250100,
          GUID = "E1EE8108",
          NextDialogue = 90250101,
          Subtitle = "Your weapon looks pretty powerful..."
        },
        [90250101] = {
          ContentES = "¡Samael no es solo un arma, es mi mejor amigo!",
          DialogueId = 90250101,
          GUID = "E1EE8132",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250102,
          SpeakNpcId = 81501,
          Subtitle = "Samael's not just a weapon — it's my best friend!",
          TalkActionId = {
            [1] = "81501:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_1"
        },
        [90250102] = {
          ContentES = "¿Por qué llamarías espada a tu amigo?",
          DialogueId = 90250102,
          GUID = "E1EE815C",
          NextDialogue = 90250103,
          SpeakNpcId = 100001,
          Subtitle = "Why would you call a sword your friend?"
        },
        [90250103] = {
          ContentES = "En la Iglesia, solo aquellos elegidos por una de las Siete Reliquias pueden convertirse en una de Las Siete Virtudes. Había muchos guerreros fuertes ese día, pero yo fui la única que pudo liberar a Samael. Me eligió a mí, ¡así que claro que debo tratarlo como se merece!",
          DialogueId = 90250103,
          GUID = "E1EE8186",
          NextDialogue = 90250104,
          SpeakNpcId = 81501,
          Subtitle = "In the Church, only those chosen by one of the Seven Relics can become one of the \"Seven Virtues.\" There were loads of strong warriors that day, but I was the only one who could pull Samael free. It chose me, so of course I've got to treat it right!",
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_2"
        },
        [90250104] = {
          ContentES = "...Lo único es que, desde entonces, no ha respondido a mí. Ni una sola vez... ¡E-Espera! ¡Eso es un secreto de alto nivel! ¡No puedes contarle a nadie, ¿entiendes!?",
          DialogueId = 90250104,
          GUID = "E1EE81B0",
          NextDialogue = 90250105,
          SpeakNpcId = 81501,
          Subtitle = "...Only thing is, ever since then, it hasn't responded to me. Not once... W—Wait — that's top secret! You can't tell anyone, got it!?",
          TalkActionId = {
            [1] = "81501:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_3"
        },
        [90250105] = {
          ContentES = "Le cubres la hoja con helado todos los días. No es de extrañar que te esté dando el tratamiento del silencio.",
          DialogueId = 90250105,
          GUID = "E1EE81DA",
          NextDialogue = 90250106,
          SpeakNpcId = 100001,
          Subtitle = "You smother its blade in ice cream every day. No wonder it's giving you the silent treatment."
        },
        [90250106] = {
          ContentES = "¿¡Eh!? ¿¡No le gusta el helado!? Entonces... ¿qué tal puré de papas? ¿¡O aderezo para ensaladas!?",
          DialogueId = 90250106,
          GUID = "E1EE8204",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "Huh!? It doesn't like ice cream!? Then... what about mashed potatoes? Or salad dressing!?",
          TalkActionId = {
            [1] = "81501:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_4",
          bForbidSkipOptions = true
        }
      }
    end
  },
  {
    MinKey = 90250200,
