    Loader = function()
      return {
        [90250200] = {
          ContentES = "Entonces... ¿cómo es la gente de la Iglesia?",
          DialogueId = 90250200,
          GUID = "E1EE9170",
          NextDialogue = 90250201,
          Subtitle = "So... what are the Church folks like?"
        },
        [90250201] = {
          ContentES = "¡Uf! ¡Cállate! ¡No quiero hablar de esos viejos aguafiestas! Uf, me has arruinado el día... No, no, no puedo enfadarme. Cálmate, Lisbell...",
          DialogueId = 90250201,
          GUID = "E1EE919A",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250202,
          SpeakNpcId = 81501,
          Subtitle = "Ugh—! Shut up! I don't want to talk about those old stick-in-the-muds! Ughhh, you've ruined my day— ...No, no, I can't get angry. Stay calm, Lisbell...",
          TalkActionId = {
            [1] = "81501:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_02_1"
        },
        [90250202] = {
          ContentES = "Parece que tienes algunos problemas con ellos.",
          DialogueId = 90250202,
          GUID = "E1EE91C4",
          NextDialogue = 90250203,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like you've got some issues with them."
        },
        [90250203] = {
          ContentES = "¡Ejem! ¡Para nada! Son absolutamente maravillosos. Tan amables y comprensivos. Cuando te equivocas en un himno, solo tienes que copiarlo treinta veces. Y si te pillan dándole crema a Samael, solo son dos días encerrado para reflexión en solitario. Realmente, son lo mejor. Absolutamente encantadores...",
          DialogueId = 90250203,
          GUID = "E1EE91EE",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "Ahem! Not at all! They are absolutely wonderful. So kind and understanding. When you mess up a hymn, you just have to copy it thirty times. And if they catch you feeding cream to Samael, it's only two days locked up for solitary reflection. Really, they're the best. Absolutely lovely...",
          TalkActionId = {
            [1] = "81501:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90250300] = {
          ContentES = "¿Qué significa exactamente “Paciencia”?",
          DialogueId = 90250300,
          GUID = "E1EEA1D8",
          NextDialogue = 90250301,
          Subtitle = "What does Patience mean, exactly?"
        },
        [90250301] = {
          ContentES = "Exactamente lo que dice. Ser paciente significa mantenerse fuerte y estoico, aguantando cualquier cosa y nunca, ¡pero nunca, enfadándose!",
          DialogueId = 90250301,
          GUID = "E1EEA202",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250302,
          SpeakNpcId = 81501,
          Subtitle = "Just what it says. Being patient means staying strong and stoic — putting up with anything and never, ever blowing up!",
          TalkActionId = {
            [1] = "81501:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_1"
        },
        [90250302] = {
          ContentES = "Eso suena... realmente difícil.",
          DialogueId = 90250302,
          GUID = "E1EEA22C",
          NextDialogue = 90250303,
          SpeakNpcId = 100001,
          Subtitle = "That sounds... really tough."
        },
        [90250303] = {
          ContentES = "¡¿Verdad?! Pero debido a este título, siempre me están diciendo que “trague mi ira con paciencia”. Pero es como... como ser obligado a detener un bostezo a mitad de camino o levantar tu espada para un golpe perfecto, solo para que te digan: “¡Oye! Ese no es un enemigo, ¡es un amigo!” Simplemente te hace aún más...",
          DialogueId = 90250303,
          GUID = "E1EEA256",
          NextDialogue = 90250304,
          SpeakNpcId = 81501,
          Subtitle = "Right!? But because of this title, they're always telling me to \"swallow my anger with patience.\" But it's like... like being forced to stop mid-yawn or raising your sword for a perfect strike, only to be told, \"Hey! That's not an enemy, it's a friend!\" It just makes you even more—",
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_2"
        },
        [90250304] = {
          ContentES = "¡Argh! Dicen que la ira es un pecado grave. No debo enfadarme. No debo...",
          DialogueId = 90250304,
          GUID = "E1EEA280",
          NextDialogue = 90250305,
          SpeakNpcId = 81501,
          Subtitle = "Argh, they say anger is a grave sin. I mustn't get angry. I mustn't...",
          TalkActionId = {
            [1] = "81501:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_3"
        },
        [90250305] = {
          ContentES = "Eso debe ser difícil para ti.",
          DialogueId = 90250305,
          GUID = "E1EEA2AA",
          NextDialogue = 90250306,
          SpeakNpcId = 100001,
          Subtitle = "That must be hard on you."
        },
        [90250306] = {
          ContentES = "¡Bueno... viene con el trabajo! ¡Soy la Señorita Paciencia, después de todo! Jeje!",
          DialogueId = 90250306,
          GUID = "E1EEA2D4",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "Well... it comes with the job! I am Lord Patience, after all! Hehe!",
          TalkActionId = {
            [1] = "81501:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90250400] = {
          ContentES = "¿Qué exactamente son las “Siete Virtudes”?",
          DialogueId = 90250400,
          GUID = "E1EEB240",
          NextDialogue = 90250401,
          Subtitle = "What exactly are the \"Seven Virtues?\""
        },
        [90250401] = {
          ContentES = "¡Las 'Siete Virtudes' son los campeones más nobles, más poderosos y más deslumbrantes de todo Elysium! ¡Naturalmente, también son los más virtuosos, está en el nombre!",
          DialogueId = 90250401,
          GUID = "E1EEB26A",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250402,
          SpeakNpcId = 81501,
          Subtitle = "The \"Seven Virtues\" are the most noble, most powerful, and most drop-dead dazzling champions in all of Elysium! Naturally, they're also the most virtuous — it's in the name!",
          TalkActionId = {
            [1] = "81501:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_04_1"
        },
        [90250402] = {
          ContentES = "Eh...",
          DialogueId = 90250402,
          GUID = "E1EEB294",
          NextDialogue = 90250403,
          SpeakNpcId = 100001,
          Subtitle = "Uh..."
        },
        [90250403] = {
          ContentES = "¿Qué significa esa mirada...? ¡Cómo te atreves a dudar de mí! ¡Te condeno a copiar el Códice treinta, no, cien veces!",
          DialogueId = 90250403,
          GUID = "E1EEB2BE",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "What's with that look...? How dare you doubt me! I hereby sentence you to copy the Codex thirty — no, a hundred times!",
          TalkActionId = {
            [1] = "81501:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90250601] = {
          ContentES = "“La Paciencia es una de las Siete Virtudes. Quienes poseen este don pueden descubrir secretos ocultos y lograr hazañas extraordinarias…”\n¡Ya no puedo más! ¡No me imites, pequeño champiñón! ¡En nombre de los Nueve Dioses, te partiré por la mitad con Samael si lo haces una vez más!",
          DialogueId = 90250601,
          GUID = "E1EED33A",
          SpeakNpcId = 81501,
          Subtitle = [[
"Patience is one of the Seven Virtues. Those gifted with patience can discover hidden secrets and accomplish extraordinary... feats..."
I can't take it anymore! Don't imitate me dwarf in the name of the Nine Gods I'll cut you in half with Samel if you do that one more time!]],
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_02"
        },
        [90250701] = {
          ContentES = "¿Crema? ¿Qué pasa? Así es como los Elysianos cuidamos de nuestras armas. ¿Tienes algún problema con eso?",
          DialogueId = 90250701,
          GUID = "E1EEE3A2",
          SpeakNpcId = 81501,
          Subtitle = "Cream? What's wrong? That's how we Elysians take care of our weapons. You got a problem with that?",
