        [200049011] = {
          Content = "可以。",
          DialogueId = 200049011,
          GUID = "200049011.0"
        },
        [200049012] = {
          Content = "猪的事先放一放。",
          DialogueId = 200049012,
          GUID = "200049012.0"
        },
        [200054111] = {
          Content = "就和卡戎之民与索拉之民外表不同，但都是人类一样？",
          DialogueId = 200054111,
          GUID = "200054111",
          ImprPlusId = 1003,
          NextDialogue = 20005412,
          Subtitle = "Kind of like how Charons and Solas look different but are both human?"
        },
        [200054112] = {
          Content = "就和枪与弓箭虽然外表不同，但都是远距离武器一样？",
          DialogueId = 200054112,
          GUID = "200054112.0",
          ImprPlusId = 1001,
