        },
        [200065131] = {
          Content = "我乃夜航者小队队长——{nickname}！在此细数你们的罪恶！",
          DialogueId = 200065131,
          GUID = "200065131",
          ImprPlusId = 1004,
          NextDialogue = 20006514,
          Subtitle = "And I am , captain of the Noctoyagers! Your crimes end here!"
        },
        [200065132] = {
          Content = "我是路过的下水道工人马里奥，不认识她们！",
          DialogueId = 200065132,
          GUID = "200065132",
          ImprPlusId = 1005,
          NextDialogue = 20006516,
          Subtitle = "And I am just a mushroom-loving plumber passing by. Have no idea who they are."
        },
        [200065133] = {
