        [200071013] = {
          Content = "没什么事。",
          DialogueId = 200071013,
          GUID = "200071013",
          Subtitle = "Nothing. Goodbye."
        },
        [510001041] = {
          Content = "啊啊啊！我喝！让我自己来！",
          DialogueId = 510001041,
          GUID = "510001041.0",
          ImprPlusId = 1004,
          NextDialogue = 51000105,
          Subtitle = "Ahhh! I'll drink it myself! Thank you!"
        },
        [510001042] = {
          Content = "（灵巧地闪开——你并不信任陌生人过分的热情。）",
          DialogueId = 510001042,
          GUID = "510001042.0",
          ImprPlusId = 1001,
          NextDialogue = 51000107,
          Subtitle = "(Skillfully sidestep — You're wary of over-the-top kindness from strangers.)"
        },
        [510001101] = {
          Content = "您口中的“夫人”生了病？",
          DialogueId = 510001101,
          GUID = "510001101",
          NextDialogue = 51000111,
          Subtitle = "The lady you mentioned — is she sick?"
        },
        [510003021] = {
          Content = "（留意到她的衣服布料颇为华贵。）",
          DialogueId = 510003021,
          GUID = "510003021.0",
          ImprPlusId = 1001,
          NextDialogue = 51000303,
          Subtitle = "(The fabric of her outfit appears quite luxurious.)"
        },
        [510003022] = {
