        [510098242] = {
          ContentES = "Y ahora... ¡la verdad finalmente sale a la luz!",
          DialogueId = 510098242,
          GUID = "510098242.0",
          ImprPlusId = 1005,
          NextDialogue = 51009916,
          Subtitle = "Then hold onto your hat... for the ultimate TRUTH REVEALED!"
        },
        [510098591] = {
          ContentES = "(Mira a Giselle)",
          DialogueId = 510098591,
          GUID = "510098591.0",
          NextDialogue = 51009950,
          Subtitle = "(Turn to Giselle)"
        },
        [510098911] = {
