          GUID = "510098911.0",
          NextDialogue = 51009982,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Conceal the truth"
        },
        [510098912] = {
          ContentES = "Revelar la verdad",
          DialogueId = 510098912,
          GUID = "510098912.0",
          NextDialogue = 51009994,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Reveal the truth"
        },
        [510099291] = {
          ContentES = "Ella lo verá.",
          DialogueId = 510099291,
          GUID = "510099291.0",
          ImprPlusId = 1004,
          NextDialogue = 51010020,
          Subtitle = "She'll see it."
        },
        [510099292] = {
          ContentES = "Salir de Lago Helado lleva tiempo, tal vez todavía esté aquí.",
          DialogueId = 510099292,
          GUID = "510099292.0",
          ImprPlusId = 1003,
          NextDialogue = 51010020,
          Subtitle = "Leaving Icelake takes time to arrange — she may still be around."
        },
        [510100471] = {
          ContentES = "¿Entonces realmente lo habías pensado?",
          DialogueId = 510100471,
          GUID = "510100471.0",
          ImprPlusId = 1001,
          NextDialogue = 51010138,
          Subtitle = "So you weren't joking about that!?"
        },
        [510100472] = {
          ContentES = "Oye, ¿qué pasa con esa obra de “Detective Giselle” que aún me debes?",
          DialogueId = 510100472,
          GUID = "510100472.0",
          ImprPlusId = 1005,
          NextDialogue = 51010139,
          Subtitle = "Hey, what about that \"Detective Giselle\" play you still owe me?"
        },
        [510102031] = {
          ContentES = "Tu voz es magnífica.",
          DialogueId = 510102031,
          GUID = "510102031.0",
          ImprPlusId = 1004,
          NextDialogue = 51010204,
          Subtitle = "Your voice is beautiful."
        },
        [510102032] = {
          ContentES = "Estás demasiado fuerte.",
          DialogueId = 510102032,
          GUID = "510102032.0",
          ImprPlusId = 1005,
          NextDialogue = 51010205,
          Subtitle = "You're too loud."
        },
        [510102091] = {
          ContentES = "Huele a hierro y fuego.",
          DialogueId = 510102091,
          GUID = "510102091.0",
          NextDialogue = 51010210,
          Subtitle = "It smells like iron and fire."
        },
        [510102092] = {
          ContentES = "Huele a nieve.",
          DialogueId = 510102092,
          GUID = "510102092.0",
          NextDialogue = 51010213,
          Subtitle = "It smells like snow."
        },
        [510102093] = {
          ContentES = "Huele a lágrimas.",
          DialogueId = 510102093,
          GUID = "510102093.0",
          NextDialogue = 51010215,
          Subtitle = "It smells like tears."
        },
        [510103261] = {
          ContentES = "El que posee su cuerpo original.",
          DialogueId = 510103261,
          GUID = "510103261.0",
          ImprPlusId = 1001,
          NextDialogue = 51010327,
          Subtitle = "The one with Ask's original body."
        },
        [510103262] = {
          ContentES = "El que posee su alma.",
          DialogueId = 510103262,
          GUID = "510103262.0",
          ImprPlusId = 1004,
          NextDialogue = 51010327,
          Subtitle = "The one with Ask's original soul."
        },
        [510103263] = {
          ContentES = "Ninguno de los dos es realmente Ask.",
          DialogueId = 510103263,
          GUID = "510103263.0",
          ImprPlusId = 1003,
          NextDialogue = 51010327,
          Subtitle = "I don't think either one is really the original Ask."
        },
        [510103264] = {
          ContentES = "Los bardos errantes, realmente hacen preguntas absurdas...",
          DialogueId = 510103264,
          GUID = "510103264.0",
          ImprPlusId = 1005,
          NextDialogue = 51010328,
          Subtitle = "Are all bards this pointlessly philosophical?"
        },
        [510104031] = {
          ContentES = "Ya he estado allí.",
          DialogueId = 510104031,
          GUID = "510104031.0",
          NextDialogue = 51010404,
          Subtitle = "I have."
        },
        [510104032] = {
          ContentES = "No, nunca.",
          DialogueId = 510104032,
          GUID = "510104032.0",
          NextDialogue = 51010405,
          Subtitle = "I haven't."
        },
        [510104033] = {
          ContentES = "Una vez combatí contra la Legión allí.",
          DialogueId = 510104033,
          GUID = "510104033.0",
          NextDialogue = 51010406,
          Subtitle = "I fought the Legion there once."
        },
        [510104101] = {
          ContentES = "¿Una persona misteriosa?",
          DialogueId = 510104101,
          GUID = "510104101.0",
          NextDialogue = 51010411,
          Subtitle = "A mysterious person?"
        },
        [510104161] = {
          ContentES = "Creo saber de quién hablas.",
          DialogueId = 510104161,
          GUID = "510104161.0",
          NextDialogue = 51010417,
          Subtitle = "I think I know that person."
        },
        [510104162] = {
