        },
        [710001001] = {
          ContentES = "(Parece hambriento… Vamos a buscarle algo de comer.)",
          DialogueId = 710001001,
          GUID = "710001001.0",
          Subtitle = "(The cat looks hungry. Maybe I should find something to feed it.)"
        },
        [710001002] = {
          ContentES = "(Parece muy solo… Podría quedarme un rato para jugar con él.)",
          DialogueId = 710001002,
          GUID = "710001002.0",
          Subtitle = "(The cat seems lonely. Perhaps spending some time playing with it might help.)"
        },
        [710001003] = {
          ContentES = "(Ya hay demasiada gente pasando hambre… No es momento de preocuparse por un gato.)",
          DialogueId = 710001003,
          GUID = "710001003.0",
          Subtitle = "(With so many people starving, who has time to worry about a cat?)"
        },
        [710002001] = {
          ContentES = "¡No, no! Si ni siquiera los humanos tienen qué comer, ¿quién pensaría en alimentar a un gato?",
          DialogueId = 710002001,
          GUID = "710002001.0",
          SpeakNpcId = 700107,
          Subtitle = "No. We're barely managing to feed people, let alone pets."
        },
        [710002101] = {
          ContentES = "Sí, adelante, puede tomarla. ¡Qué sorpresa! Creía que solo los ricos de la ciudad interior se compraba comida para sus mascotas.",
          DialogueId = 710002101,
          GUID = "710002101.0",
          SpeakNpcId = 700106,
          Subtitle = "Yes, take your pick. This is rare. I thought only the wealthy folks from the inner city buy cat food for their pets."
        },
        [710002201] = {
          ContentES = "(El gato da dos vueltas alrededor de la ración, dudando, y luego baja la guardia y empieza a comer. Al ver su expresión satisfecha, una suave calidez reconforta tu corazón.)",
          DialogueId = 710002201,
          GUID = "710002201.0",
          SpeakNpcId = 800006,
          Subtitle = "(The cat circles the food warily before eventually lowering its guard and digging in. Watching it eat fills your heart with a sense of peace and joy.)"
        },
        [710007210] = {
          ContentES = "De acuerdo, me encargo de ello.",
          DialogueId = 710007210,
          GUID = "710007210.0",
          NextDialogue = 71000741,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Alright, I'll help."
        },
        [710007211] = {
          ContentES = "Lo siento, ahora mismo estoy algo {性别:ocupado|ocupada}.",
          DialogueId = 710007211,
          GUID = "710007211.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Sorry, I'm a bit tied up right now."
        },
        [710008021] = {
          ContentES = "(Aceptar)",
          DialogueId = 710008021,
          GUID = "710008021.0",
