          NextDialogue = 80020304,
          Subtitle = "You'd go shopping?"
        },
        [800203121] = {
          ContentES = "¿De verdad funciona así?",
          DialogueId = 800203121,
          GUID = "800203121.0",
          NextDialogue = 80020313,
          Subtitle = "Is it really that transformative?"
        },
        [800203122] = {
          ContentES = "Suena bastante elegante.",
          DialogueId = 800203122,
          GUID = "800203122.0",
          NextDialogue = 80020314,
          Subtitle = "It does sound quite stylish."
        },
        [800203161] = {
          ContentES = "¿Príncipe?",
          DialogueId = 800203161,
          GUID = "800203161.0",
          NextDialogue = 80020317,
          Subtitle = "A prince?"
        },
        [800204021] = {
          ContentES = "Parece que estás de buen humor.",
          DialogueId = 800204021,
          GUID = "800204021.0",
          NextDialogue = 80020403,
          Subtitle = "Sounds like you're in a good mood."
        },
        [800204022] = {
          ContentES = "Eso sí suena a tarea de criadas.",
          DialogueId = 800204022,
          GUID = "800204022.0",
          NextDialogue = 80020404,
          Subtitle = "That sounds like a typical maid's chore."
        },
        [800204091] = {
          ContentES = "Entonces, ¿qué es lo que te tiene preocupada?",
          DialogueId = 800204091,
          GUID = "800204091.0",
          NextDialogue = 80020410,
          Subtitle = "So what's bothering you?"
        },
        [800204092] = {
          ContentES = "¿Y si me cuentas un poco más de tus antiguos colegas?",
          DialogueId = 800204092,
          GUID = "800204092.0",
          NextDialogue = 80020411,
          Subtitle = "Care to share more about your former colleagues?"
        },
        [800204171] = {
          ContentES = "Si te da curiosidad, ¿por qué no vas a verla?",
          DialogueId = 800204171,
          GUID = "800204171.0",
          NextDialogue = 80020418,
          Subtitle = "Why not go visit her then?"
        },
        [800205011] = {
          ContentES = "¿Eh? No es más que una simple coincidencia.",
          DialogueId = 800205011,
          GUID = "800205011.0",
          NextDialogue = 80020503,
          Subtitle = "Huh? It's just a coincidence."
        },
        [800205012] = {
          ContentES = "Tu cabello es tan llamativo que no puede pasar desapercibido.",
          DialogueId = 800205012,
          GUID = "800205012.0",
          NextDialogue = 80020503,
          Subtitle = "Well, with hair as bright as yours, it's hard not to notice you."
        },
        [800205071] = {
          ContentES = "¿Suena como si por fin te hubieras quitado un peso de encima?",
          DialogueId = 800205071,
          GUID = "800205071.0",
          NextDialogue = 80020508,
          Subtitle = "Sounds like you've resolved some inner conflicts."
        },
        [800205072] = {
          ContentES = "¿No te da un poco de pena?",
          DialogueId = 800205072,
          GUID = "800205072.0",
          NextDialogue = 80020509,
          Subtitle = "Would you have any regrets?"
        },
        [800205121] = {
          ContentES = "Mientras yo aún dudaba, ella no titubeó ni un instante en cumplir la misión... hasta el punto de verme a mí como un obstáculo que podía eliminar si fuera necesario.",
          DialogueId = 800205121,
          GUID = "C852AD41",
          NextDialogue = 80020513,
          SpeakNpcId = 93102,
          Subtitle = "While I was hesitating, she didn't think twice about fulfilling her task — even considering me as a potential obstacle to be removed if necessary.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD41"
        },
        [800205141] = {
          ContentES = "¿Todavía le guardas rencor?",
          DialogueId = 800205141,
          GUID = "C852AD6C",
          NextDialogue = 800205143,
          Subtitle = "Do you still hate her?"
        },
        [800205142] = {
          ContentES = "¿Todavía la amas?",
          DialogueId = 800205142,
          GUID = "C852AD6D",
          NextDialogue = 800205143,
          Subtitle = "Do you still love her?"
        },
        [800205143] = {
          ContentES = "Siendo honesta, no lo sé. Siento algo de enfado, un poco de resentimiento y algo de nostalgia por ella. Para agentes como nosotras, hablar de amor y odio es un lujo que no podemos permitirnos.",
          DialogueId = 800205143,
          FacialId = {
            [1] = "93102:Unhappy01"
          },
          GUID = "C852AD94",
          NextDialogue = 80020515,
          SpeakNpcId = 93102,
          Subtitle = "To be honest, I don't know. I just feel a bit indignant, aggrieved, and wistful. For agents like us, love and hate are luxuries we can't afford.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD94"
        },
        [800205181] = {
          ContentES = "¿Cómo? ¿Acabas de darme las gracias?",
          DialogueId = 800205181,
          GUID = "800205181.0",
          NextDialogue = 80020522,
          Subtitle = "Hm? Did you just say \"thank you\"?"
        },
        [800205182] = {
          ContentES = "No te escuché bien, ¿puedes repetirlo?",
          DialogueId = 800205182,
          GUID = "800205182.0",
          NextDialogue = 80020522,
          Subtitle = "Come again?"
        },
        [800301051] = {
          ContentES = "Realmente tienes tus principios en este tipo de cosas.",
          DialogueId = 800301051,
          GUID = "800301051.0",
          NextDialogue = 80030106,
          Subtitle = "You're indeed a man of principles when it comes to this."
        },
        [800301052] = {
          ContentES = "Siempre buscas la manera de holgazanear.",
          DialogueId = 800301052,
          GUID = "800301052.0",
          NextDialogue = 80030107,
          Subtitle = "You're always slacking off, Randy."
        },
        [800302051] = {
          ContentES = "¿Un caballero que se inventa excusas para no trabajar?",
          DialogueId = 800302051,
          GUID = "800302051.0",
          NextDialogue = 80030206,
          Subtitle = "A gentleman who lies to get off work?"
        },
        [800302052] = {
          ContentES = "Sí, claro… un caballero tan refinado, todo un galán.",
          DialogueId = 800302052,
          GUID = "800302052.0",
          NextDialogue = 80030207,
          Subtitle = "Yeah, definitely. You're such a gentleman."
        },
        [800302091] = {
