        [801001021] = {
          ContentES = "¿Insensible? ¿Qué he hecho yo?",
          DialogueId = 801001021,
          GUID = "801001021.0",
          NextDialogue = 80100103,
          Subtitle = "Indifference? What have I done?"
        },
        [801001022] = {
          ContentES = "Es cierto, soy insensible. ¿Y qué harás al respecto?",
          DialogueId = 801001022,
          GUID = "801001022.0",
          NextDialogue = 80100104,
          Subtitle = "...That's right, that's what I am, cold and uncaring."
        },
        [801001041] = {
          ContentES = "¿Historia de amor? ¿De quién con quién?",
          DialogueId = 801001041,
          GUID = "801001041.0",
          NextDialogue = 80100105,
          Subtitle = "Romance? Between whom?"
        },
        [801001091] = {
          ContentES = "Tranquilízate un poco, apenas nos conocemos.",
          DialogueId = 801001091,
          GUID = "801001091.0",
          NextDialogue = 80100110,
          Subtitle = "Calm down. We've just met."
        },
        [801001092] = {
          ContentES = "Ya lo entiendo. Estás practicando para una obra de teatro.",
          DialogueId = 801001092,
          GUID = "801001092.0",
          NextDialogue = 80100111,
          Subtitle = "I get it now. You're rehearsing poetic literature for a theatre show."
        },
        [801002011] = {
          ContentES = "¿Esta parte de ti?",
          DialogueId = 801002011,
          GUID = "801002011.0",
          NextDialogue = 80100202,
          Subtitle = "That side of you?"
        },
        [801002071] = {
          ContentES = "Nunca pensé que desearas esas cosas.",
          DialogueId = 801002071,
          GUID = "801002071.0",
          NextDialogue = 80100208,
          Subtitle = "Never thought you'd dream of that."
        },
        [801002072] = {
          ContentES = "Dijiste que antes... ¿significa eso que ya te has acostumbrado?",
          DialogueId = 801002072,
          GUID = "801002072.0",
          NextDialogue = 80100209,
          Subtitle = "You said once... Does that mean you've grown used to it?"
        },
        [801002151] = {
          ContentES = "Es demasiado peligroso, no puedo.",
          DialogueId = 801002151,
          GUID = "801002151.0",
          NextDialogue = 80100216,
          Subtitle = "It's too dangerous. I refuse."
        },
        [801002152] = {
          ContentES = "Inténtalo si te atreves.",
          DialogueId = 801002152,
          GUID = "801002152.0",
          NextDialogue = 80100217,
          Subtitle = "Try it if you dare."
        },
        [801002191] = {
          ContentES = "No te permitiría tener esa oportunidad.",
          DialogueId = 801002191,
          GUID = "801002191.0",
          NextDialogue = 80100220,
          Subtitle = "You won't get a chance like that."
        },
        [801003021] = {
          ContentES = "Odio adivinar lo que los demás piensan.",
          DialogueId = 801003021,
          GUID = "801003021.0",
          NextDialogue = 80100303,
          Subtitle = "I don't like guessing what others are thinking."
        },
        [801003022] = {
          ContentES = "¿Historias de tu pasado?",
          DialogueId = 801003022,
          GUID = "801003022.0",
          NextDialogue = 80100305,
          Subtitle = "Matters of your past?"
        },
        [801003091] = {
          ContentES = "¿Ella te está persiguiendo?",
          DialogueId = 801003091,
          GUID = "801003091.0",
          NextDialogue = 80100310,
          Subtitle = "Is she after you?"
        },
        [801003141] = {
          ContentES = "De todas formas, el Imperio ya me tiene en la mira. No cambiaría nada añadir un crimen más a la lista.",
          DialogueId = 801003141,
          GUID = "801003141.0",
          NextDialogue = 80100315,
          Subtitle = "I'm already wanted by the Empire anyway. Being listed for another crime hardly matters to me."
        },
        [801003142] = {
          ContentES = "Quizás deberíamos mantener una distancia apropiada.",
          DialogueId = 801003142,
          GUID = "801003142.0",
          NextDialogue = 80100327,
          Subtitle = "Perhaps we should keep an appropriate distance."
        },
        [801003191] = {
          ContentES = "¿Persona destinada?",
          DialogueId = 801003191,
          GUID = "801003191.0",
          NextDialogue = 80100320,
          Subtitle = "Destined one?"
        },
        [801003221] = {
          ContentES = "Creo que ya te ha escuchado.",
          DialogueId = 801003221,
          GUID = "801003221.0",
          NextDialogue = 80100323,
          Subtitle = "Every word of it, I believe."
        },
        [801003222] = {
          ContentES = "¿Quién es? ¿Quieres que le deje un mensaje por ti?",
          DialogueId = 801003222,
          GUID = "801003222.0",
          NextDialogue = 80100323,
          Subtitle = "Who would that be? I can relay your words if you want."
        },
        [801003321] = {
          ContentES = "¿Por qué tengo la sensación de que lo estás disfrutando?",
          DialogueId = 801003321,
          GUID = "801003321.0",
          NextDialogue = 80100333,
          Subtitle = "Why do I get the feeling that you're enjoying this?"
        },
        [801003331] = {
          ContentES = "¿Persona destinada?",
          DialogueId = 801003331,
          GUID = "801003331.0",
          NextDialogue = 80100334,
          Subtitle = "Destined one?"
        },
        [801004011] = {
          ContentES = "¿Hay algo que te preocupe?",
          DialogueId = 801004011,
          GUID = "801004011.0",
          NextDialogue = 80100402,
          Subtitle = "Something troubling you?"
        },
        [801004012] = {
          ContentES = "Creo que fue un mal momento para invitarte.",
          DialogueId = 801004012,
          GUID = "801004012.0",
          NextDialogue = 80100403,
          Subtitle = "Guess I didn't invite you at the right time."
        },
        [801004121] = {
          ContentES = "Estás negando quién realmente eres.",
          DialogueId = 801004121,
          GUID = "801004121.0",
          NextDialogue = 80100413,
          Subtitle = "You're running away from who you really are."
        },
        [801004122] = {
          ContentES = "¡Qué mala actuación!",
          DialogueId = 801004122,
          GUID = "801004122.0",
          NextDialogue = 80100415,
          Subtitle = "Your acting is terrible."
        },
        [801101021] = {
          ContentES = "Parece que en la Legión la comida y la bebida son mejores.",
          DialogueId = 801101021,
          GUID = "801101021.0",
          NextDialogue = 80110103,
          Subtitle = "Seems like the Legion has better food and drinks."
        },
        [801101051] = {
          ContentES = "He oído que la Legión consiguió un tesoro llamado “N.º 0”…",
          DialogueId = 801101051,
          GUID = "801101051.0",
          NextDialogue = 80110106,
          Subtitle = "I heard the Legion got a treasure called \"No. 0\"."
        },
        [801101052] = {
          ContentES = "Le estás dando muchas vueltas, solo quería invitarte a beber algo, eso es todo.",
          DialogueId = 801101052,
          GUID = "801101052.0",
          NextDialogue = 80110112,
          Subtitle = "You're overthinking it. I just want to offer you a drink."
        },
        [801101141] = {
          ContentES = "Así que tú también fuiste una Phoxcazadora.",
          DialogueId = 801101141,
          GUID = "801101141.0",
          NextDialogue = 80110115,
          Subtitle = "So you were a Phoxhunter before?"
        },
        [801101142] = {
          ContentES = "Así que eres de Lago Helado.",
          DialogueId = 801101142,
          GUID = "801101142.0",
          NextDialogue = 80110115,
          Subtitle = "So you're originally from Icelake?"
        },
        [801101161] = {
          ContentES = "Parece que tienes mucho cuidado con lo que dices.",
          DialogueId = 801101161,
          GUID = "801101161.0",
          NextDialogue = 80110117,
          Subtitle = "You seem to be so careful of what you say."
        },
        [801101201] = {
          ContentES = "¿Y no te sientes agobiada por estar dentro de la Legión?",
          DialogueId = 801101201,
          GUID = "801101201.0",
          NextDialogue = 80110121,
          Subtitle = "The Legion must have made you feel repressed."
        },
        [801101202] = {
          ContentES = "No lo hubiera imaginado, parece que disfrutas del estatus y el prestigio que conlleva.",
          DialogueId = 801101202,
          GUID = "801101202.0",
          NextDialogue = 80110122,
          Subtitle = "I wouldn't have guessed — you seem to thrive on the status and prestige it brings."
        },
        [801101261] = {
          ContentES = "¿Se supone que puedo saber esto?",
          DialogueId = 801101261,
          GUID = "801101261.0",
          NextDialogue = 80110127,
          Subtitle = "Is this something I can know?"
        },
        [801101301] = {
          ContentES = "Solo estaba bromeando.",
          DialogueId = 801101301,
          GUID = "801101301.0",
          NextDialogue = 80110131,
          Subtitle = "I was just joking."
        },
        [801101361] = {
          ContentES = "Eh... ¡De nuevo, advertencia de zas-zas!",
          DialogueId = 801101361,
          GUID = "801101361.0",
          NextDialogue = 80110137,
          Subtitle = "Um... Again, zap-zap warning~"
        },
        [801102021] = {
          ContentES = "Sí. En la taberna de la señora Camilla.",
          DialogueId = 801102021,
          GUID = "801102021.0",
          NextDialogue = 80110203,
          Subtitle = "Yep, at Ms Camilla's tavern."
        },
        [801102031] = {
          ContentES = "¡¿Hay encargos de matar y saquear?!",
          DialogueId = 801102031,
          GUID = "801102031.0",
          NextDialogue = 80110204,
          Subtitle = "You mean there are commissions that involve killing and robbing people!?"
        },
        [801102051] = {
          ContentES = "No, ella es bastante amable.",
          DialogueId = 801102051,
          GUID = "801102051.0",
          NextDialogue = 80110206,
          Subtitle = "Nah, she's a very kind lady now."
        },
        [801102052] = {
          ContentES = "Así es, suele ser bastante temible.",
          DialogueId = 801102052,
          GUID = "801102052.0",
          NextDialogue = 80110207,
          Subtitle = "Yes, still being fierce and sharp-tongued."
        },
        [801102071] = {
          ContentES = "¿Quién es tu jefa...?",
          DialogueId = 801102071,
          GUID = "801102071.0",
          NextDialogue = 80110208,
          Subtitle = "...Who's your supreme officer?"
        },
        [801102091] = {
          ContentES = "De hecho tú me das la misma impresión...",
          DialogueId = 801102091,
          GUID = "801102091.0",
          NextDialogue = 80110210,
          Subtitle = "You give me the same vibes..."
        },
        [801102151] = {
          ContentES = "Tu jefa parece una persona interesante.... ¿Puedes contarme más sobre ella?",
          DialogueId = 801102151,
          GUID = "801102151.0",
          NextDialogue = 80110216,
          Subtitle = "...Your superior officer sounds like an interesting person. Can you tell me more about her?"
        },
        [801102211] = {
          ContentES = "Sigue contándome. ¿Al final encontraron el tesoro? ¿Dónde está ahora?",
          DialogueId = 801102211,
          GUID = "801102211.0",
          NextDialogue = 80110222,
          Subtitle = "Keep going. Did they finally find the treasure? Where is it now?"
        },
        [801103021] = {
          ContentES = "¿Qué contiene el paquete?",
          DialogueId = 801103021,
          GUID = "801103021.0",
          NextDialogue = 80110303,
          Subtitle = "What's in the package?"
        },
        [801103031] = {
          ContentES = "Tengo que comprobar que el paquete no tenga nada peligroso.",
          DialogueId = 801103031,
          GUID = "801103031.0",
          NextDialogue = 80110304,
          Subtitle = "I need to know if there are any hazardous materials."
        },
        [801103032] = {
          ContentES = "Me temo que, si envío algo indebido, podrían electrocutarme por eso.",
          DialogueId = 801103032,
          GUID = "801103032.0",
          NextDialogue = 80110304,
          Subtitle = "I don't want to end up delivering something illegal and get zapped for it."
        },
        [801103051] = {
          ContentES = "¡Pruébalo!",
          DialogueId = 801103051,
          GUID = "801103051.0",
          NextDialogue = 80110306,
          Subtitle = "Try it out!"
        },
        [801103081] = {
          ContentES = "¿Esa pistola es… un regalo?",
          DialogueId = 801103081,
          GUID = "801103081.0",
          NextDialogue = 80110309,
          Subtitle = "This gun is... a present?"
        },
        [801103101] = {
          ContentES = "Está bien, pero si es un regalo para tu amiga, ¿por qué no se lo entregas tú misma?",
          DialogueId = 801103101,
          GUID = "801103101.0",
          NextDialogue = 80110311,
          Subtitle = "I can do the job. But if it's a gift for a friend, why don't you deliver it yourself?"
        },
        [801103111] = {
          ContentES = "¿Por qué?",
          DialogueId = 801103111,
          GUID = "801103111.0",
          NextDialogue = 80110312,
          Subtitle = "Why is that?"
        },
        [801103112] = {
          ContentES = "¿Después de estar tanto tiempo en la gran ciudad, ya desprecias a Lago Helado?",
          DialogueId = 801103112,
          GUID = "801103112.0",
          NextDialogue = 80110312,
          Subtitle = "What, gotten too used to the big city life to care about your humble hometown?"
        },
        [801103161] = {
          ContentES = "¿Tú crees que ese comportamiento es normal?",
          DialogueId = 801103161,
          GUID = "801103161.0",
          NextDialogue = 80110317,
          Subtitle = "Do you think this is normal?"
        },
        [801103271] = {
          ContentES = "¿Tu familia también te tiene miedo?",
          DialogueId = 801103271,
          GUID = "801103271.0",
          NextDialogue = 80110328,
          Subtitle = "Is your family afraid of you?"
        },
        [801103301] = {
          ContentES = "No creo que todo esto sea normal.",
          DialogueId = 801103301,
          GUID = "801103301.0",
          NextDialogue = 80110331,
          Subtitle = "I don't think any of this feels normal."
        },
        [801201101] = {
          ContentES = "¿Estás bien?",
          DialogueId = 801201101,
          GUID = "801201101.0",
          NextDialogue = 80120111,
          Subtitle = "You okay?"
        },
        [801201102] = {
          ContentES = "(Le das una palmadita en su hombro).",
          DialogueId = 801201102,
          GUID = "801201102.0",
          NextDialogue = 80120111,
          Subtitle = "(Pats Margie on the shoulder)"
        },
        [801201161] = {
          ContentES = "¿Ladridos? Entonces, ¿quién era el perrito?",
          DialogueId = 801201161,
          GUID = "801201161.0",
          NextDialogue = 80120117,
          Subtitle = "Barking? Right. So who was that doggie?"
        },
        [801201211] = {
          ContentES = "¿Una sorpresa agradable?",
          DialogueId = 801201211,
          GUID = "801201211.0",
          NextDialogue = 80120122,
          Subtitle = "A stroke of luck? Why's that?"
        },
        [801201271] = {
          ContentES = "¿Puedo darte una mano?",
          DialogueId = 801201271,
          GUID = "801201271.0",
          NextDialogue = 80120128,
          Subtitle = "Mind if I lend a hand?"
        },
        [801201272] = {
          ContentES = "El que encuentra, se queda. Yo también voy a tomar algunas cosas.",
          DialogueId = 801201272,
          GUID = "801201272.0",
          NextDialogue = 80120129,
          Subtitle = "Finders keepers. I'd like a share of the finds too."
        },
        [801202041] = {
          ContentES = "¿Suena hueca?",
          DialogueId = 801202041,
          GUID = "801202041.0",
          NextDialogue = 80120205,
          Subtitle = "Sounds like it's hollow inside."
        },
        [801202042] = {
          ContentES = "Y además es una madera muy buena…",
          DialogueId = 801202042,
          GUID = "801202042.0",
          NextDialogue = 80120206,
          Subtitle = "It's got a nice ring to it. Quality wood."
        },
        [801202111] = {
          ContentES = "Hay un papel doblado en esta página. ¿Qué es lo que dice?",
          DialogueId = 801202111,
          GUID = "801202111.0",
          NextDialogue = 80120212,
          Subtitle = "There's a note tucked in here. What does it say?"
        },
        [801202181] = {
          ContentES = "El tiempo lo ha cambiado después de todo...",
          DialogueId = 801202181,
          GUID = "801202181.0",
          NextDialogue = 80120219,
          Subtitle = "Time has changed him after all."
        },
        [801202182] = {
          ContentES = "Quizá él nunca cambió, por eso dejó intencionalmente esta partitura aquí.",
          DialogueId = 801202182,
          GUID = "801202182.0",
          NextDialogue = 80120220,
          Subtitle = "Maybe he never really changed. That's why he left this score behind on purpose."
        },
        [801203021] = {
          ContentES = "Aunque le puse azúcar, parece que todavía no te acostumbras al café.",
          DialogueId = 801203021,
          GUID = "801203021.0",
          NextDialogue = 80120303,
          Subtitle = "Even with sugar, our Margie still can't stomach coffee."
        },
        [801203031] = {
          ContentES = "Te gustan más las bebidas dulces y refrescantes, ¿verdad?",
          DialogueId = 801203031,
          GUID = "801203031.0",
          NextDialogue = 80120304,
          Subtitle = "You're more of a fan of cool, refreshing drinks or something sweet, huh?"
        },
        [801203041] = {
          ContentES = "¿Quién es tu “viejo gruñón”...?",
          DialogueId = 801203041,
          GUID = "801203041.0",
          NextDialogue = 80120305,
          Subtitle = "Who is your \"stupid old man\"?"
        },
        [801203071] = {
          ContentES = "¡Entendido! ¡Señorita detective taciturna!",
          DialogueId = 801203071,
          GUID = "801203071.0",
          NextDialogue = 80120308,
          Subtitle = "Understood! Miss Reticent Detective it is!"
        },
        [801203081] = {
          ContentES = "¡Entendido! ¡La Princesa del Basurero más genial, inteligente y confiable!",
          DialogueId = 801203081,
          GUID = "801203081.0",
          NextDialogue = 80120309,
          Subtitle = "Understood! The coolest, smartest, most reliable Princess Rubbish Bin!"
        },
        [801203101] = {
          ContentES = "Nunca me habías hablado sobre tu padre. ¿Verdad?",
          DialogueId = 801203101,
          GUID = "801203101.0",
          NextDialogue = 80120311,
          Subtitle = "I've never heard you talk about your dad before."
        },
        [801203111] = {
          ContentES = "Es un poco lo mismo para ustedes dos, ¿no?",
          DialogueId = 801203111,
          GUID = "801203111.0",
          NextDialogue = 80120312,
          Subtitle = "Sounds like you're no better than him on this!"
        },
        [801203121] = {
          ContentES = "De tal palo, tal astilla...",
          DialogueId = 801203121,
          GUID = "801203121.0",
          NextDialogue = 80120313,
          Subtitle = "Like father, like daughter, huh?"
        },
        [801203161] = {
          ContentES = "...¿Espera, qué acabas de decir? ¿Debería denunciar esto?",
          DialogueId = 801203161,
          GUID = "801203161.0",
          NextDialogue = 80120317,
          Subtitle = "...Wait, what did you just say!? Should I report this?"
        },
        [801203181] = {
          ContentES = "Pero, si Martin abandonó su pueblo natal contigo, entonces tampoco le debía de gustar ese lugar, ¿no?",
          DialogueId = 801203181,
          GUID = "801203181.0",
          NextDialogue = 80120319,
          Subtitle = "But since Martin brought you away from your old home, maybe he didn't like it there either."
        },
        [801203211] = {
          ContentES = "No te imagino hablando de esa forma, ¿me puedes hacer una demostración?",
          DialogueId = 801203211,
          GUID = "801203211.0",
          NextDialogue = 80120322,
          Subtitle = "Really? How did you talk back then? Can you give me a demo?"
        },
        [801203221] = {
          ContentES = "¡Te lo ruego, honorable señorita detective taciturna! ¡Te lo cambio por tu bebida favorita!",
          DialogueId = 801203221,
          GUID = "801203221.0",
          NextDialogue = 80120323,
          Subtitle = "Please, Miss Reticent Detective, I'll trade you your favourite drink for it!"
        },
        [801203231] = {
          ContentES = "Si te niegas, me veré obligado a... Princesa del Basurero, su alteza...",
          DialogueId = 801203231,
          GUID = "801203231.0",
          NextDialogue = 80120324,
          Subtitle = "If you won't, I'll just have to play dirty — Princess Rubbish Bin, Your Highness—"
        },
        [801203261] = {
          ContentES = "(Aguantar la risa).",
          DialogueId = 801203261,
          GUID = "801203261.0",
          NextDialogue = 80120327,
          Subtitle = "(Holding back a laugh.)"
        },
        [801203271] = {
          ContentES = "(¡Morderse los labios para no reír!)",
          DialogueId = 801203271,
          GUID = "801203271.0",
          NextDialogue = 80120328,
          Subtitle = "(It's increasingly hard to hold it back!)"
        },
        [801203281] = {
          ContentES = "(¡No puedo Aguantar más!)",
          DialogueId = 801203281,
          GUID = "801203281.0",
          NextDialogue = 80120329,
          Subtitle = "(Can't hold it back anymore!)"
        },
        [801203361] = {
          ContentES = "¿Cómo se burló de ti?",
          DialogueId = 801203361,
          GUID = "801203361.0",
          NextDialogue = 80120337,
          Subtitle = "Mock you? How?"
        },
        [801203431] = {
          ContentES = "Usar una olla como casco… el viejo Martin realmente tiene un gusto muy peculiar.",
          DialogueId = 801203431,
          GUID = "801203431.0",
          NextDialogue = 80120344,
          Subtitle = "A pot helmet... Old Martin sure has a unique sense of style."
        },
        [801203432] = {
          ContentES = "Así que era un regalo de cumpleaños… parece que el viejo Martin te quería mucho.",
          DialogueId = 801203432,
          GUID = "801203432.0",
          NextDialogue = 80120344,
          Subtitle = "So it was a birthday gift... Looks like Old Martin really cares about you."
        },
        [801204011] = {
          ContentES = "¿Por qué lloras? ¡Deberías sonreír, es una buena noticia!",
          DialogueId = 801204011,
          GUID = "801204011.0",
          NextDialogue = 80120402,
          Subtitle = "What's with the tears? Isn't that a good thing?"
        },
        [801204021] = {
          ContentES = "Toma un poco de agua. Estoy aquí si deseas hablar.",
          DialogueId = 801204021,
          GUID = "801204021.0",
          NextDialogue = 80120403,
          Subtitle = "Here, have some water. I'm here whenever you're ready to talk."
        },
        [801204041] = {
          ContentES = "¿Quién o qué es una Colagorda?",
          DialogueId = 801204041,
          GUID = "801204041.0",
          NextDialogue = 80120405,
          Subtitle = "Plumpytail? What's that?"
        },
        [801204111] = {
          ContentES = "¡Oh, pobre detective, completamente manipulado por Colagorda!",
          DialogueId = 801204111,
          GUID = "801204111.0",
          NextDialogue = 80120412,
          Subtitle = "Aww, poor detective, completely at the mercy of Plumpytail!"
        },
        [801204131] = {
          ContentES = "¡Miau, miau! señorita detective, tengo una pista importante.",
