          NextDialogue = 80160357,
          Subtitle = "She reached out to you."
        },
        [801603562] = {
          ContentES = "Ella te estaba manipulando.",
          DialogueId = 801603562,
          GUID = "801603562.0",
          NextDialogue = 80160360,
          Subtitle = "She was manipulating you."
        },
        [801603671] = {
          ContentES = "¡Esa persona es detestable! ¡Esta vez no dejaré que se escape!",
          DialogueId = 801603671,
          GUID = "801603671.0",
          NextDialogue = 80160368,
          Subtitle = "She's despicable! She won't get away this time!"
        },
        [801603672] = {
          ContentES = "(Qué hermoso sueño… ojalá algún día tenga la oportunidad de vivir uno así.)",
          DialogueId = 801603672,
          GUID = "801603672.0",
          NextDialogue = 80160368,
          Subtitle = "(That dream sounds blissful... if only I could borrow it for a night.)"
