        [801604031] = {
          ContentES = "Así es como se debe tratar a los amigos.",
          DialogueId = 801604031,
          GUID = "801604031.0",
          NextDialogue = 80160404,
          Subtitle = "Just how friends treat each other, that's all."
        },
        [801604051] = {
          ContentES = "¿Qué se te antoja hoy? La señora Camilla dice que en la Capital Imperial últimamente está de moda...",
          DialogueId = 801604051,
          GUID = "801604051",
          NextDialogue = 80160406,
          Subtitle = "Want to try something new? Camilla says this one's all the rage in the capital—"
