        [801604121] = {
          ContentES = "¿Estás bien? ¡Te advertí que no bebieras tan rápido!",
          DialogueId = 801604121,
          GUID = "801604121.0",
          NextDialogue = 80160413,
          Subtitle = "Are you all right? I told you not to drink so fast!"
