        [801701051] = {
          ContentES = "Increíble.",
          DialogueId = 801701051,
          GUID = "801701051.0",
          NextDialogue = 80170108,
          Subtitle = "That's incredible."
        },
        [801701052] = {
          ContentES = "¿Cuál es su secreto? Por favor, enséñeme.",
          DialogueId = 801701052,
          GUID = "801701052.0",
          NextDialogue = 80170106,
          Subtitle = "What's your secret? Please teach me."
