        [801701371] = {
          ContentES = "¡Eso fue maravilloso.!",
          DialogueId = 801701371,
          GUID = "801701371.0",
          NextDialogue = 80170138,
          Subtitle = "That's wonderful news."
        },
        [801701372] = {
          ContentES = "Las cosas no son tan simples, ¿verdad?",
          DialogueId = 801701372,
          GUID = "801701372.0",
          NextDialogue = 80170139,
          Subtitle = "It's not that simple, is it?"
