        [801701451] = {
          ContentES = "¿Qué pasó después?",
          DialogueId = 801701451,
          GUID = "801701451.0",
          NextDialogue = 80170146,
          Subtitle = "What happened next?"
        },
        [801701561] = {
          ContentES = "Pero aún no quiero ver morir así a las personas que me importan. Tal vez, si me esfuerzo un poco más, pueda encontrar un verdadero milagro que las salve.",
          DialogueId = 801701561,
          GUID = "801701561.0",
          NextDialogue = 80170157,
          Subtitle = "But I still don't want to see the people I care about pass away like that. Maybe if I try harder, I can find a real miracle to save them."
        },
        [801701562] = {
          ContentES = "Tienes razón. Quizá aceptar que la muerte es inevitable, sea la decisión más sensata.",
          DialogueId = 801701562,
          GUID = "801701562.0",
          NextDialogue = 80170158,
          Subtitle = "You're right. Perhaps accepting inevitable death is the better choice."
        },
        [801702011] = {
          ContentES = "Últimamente han pasado demasiadas cosas, y me siento algo {性别:agotado|agotada}.",
          DialogueId = 801702011,
          GUID = "801702011.0",
          NextDialogue = 80170202,
          Subtitle = "So much has happened lately. I'm feeling exhausted."
