        },
        [900103011] = {
          ContentES = "¿Qué es esa cosa oscura, allá?",
          DialogueId = 900103011,
          GUID = "900103011.0",
          Subtitle = "What's that black thingy over there?"
        },
        [900103012] = {
          ContentES = "Adiós.",
          DialogueId = 900103012,
          GUID = "900103012.0",
          Subtitle = "Goodbye."
        },
        [900300011] = {
          ContentES = "¿Tienes algún deseo, Berry?",
          DialogueId = 900300011,
          GUID = "900300011.0",
          NextDialogue = 90030101,
          Subtitle = "Do you have any wishes, Berry?"
        },
        [900300013] = {
          ContentES = "Hace tanto frío en Lago Helado.",
          DialogueId = 900300013,
          GUID = "900300013.0",
          NextDialogue = 90030301,
          Subtitle = "It's so bitterly cold here in Icelake..."
        },
        [900300014] = {
          ContentES = "¿Berry? ¿Cómo es que estás aquí?",
          DialogueId = 900300014,
          GUID = "900300014.0",
          NextDialogue = 90030401,
          Subtitle = "Berry? How come you are here?"
        },
        [900300015] = {
          ContentES = "¿Cómo es la Legión Hyperborean?",
          DialogueId = 900300015,
          GUID = "900300015.0",
          NextDialogue = 90030501,
          Subtitle = "What's the Hyperborean Legion like?"
        },
        [900300016] = {
          ContentES = "Siempre te gustaban los lugares tranquilos, ¿el ruido aquí te molesta mucho?",
          DialogueId = 900300016,
          GUID = "900300016.0",
          NextDialogue = 90030601,
          Subtitle = "You've always preferred quiet settings; does the noise here bother you?"
        },
        [900300018] = {
          ContentES = "Berry, estoy {性别:cansado|cansada}...",
          DialogueId = 900300018,
          GUID = "900300018.0",
          NextDialogue = 90030801,
          Subtitle = "Berry, I'm tired..."
        },
        [900400011] = {
          ContentES = "Siempre pareces tan feliz cuando llueve, ¿verdad?",
          DialogueId = 900400011,
          GUID = "900400011.0",
          NextDialogue = 90040101,
          Subtitle = "You always seem so happy when it rains."
        },
        [900400012] = {
          ContentES = "Siempre estás hablando de amor. ¿Qué significa realmente “amor” para ti...?",
          DialogueId = 900400012,
          GUID = "900400012.0",
          NextDialogue = 90040201,
          Subtitle = "You're always talking about love. What does \"love\" really mean to you...?"
        },
        [900400013] = {
          ContentES = "Tu forma de pensar es muy especial.",
          DialogueId = 900400013,
          GUID = "900400013.0",
          NextDialogue = 90040301,
          Subtitle = "Your way of thinking is quite special."
        },
        [900400014] = {
          ContentES = "¿Estás bien con tanto toxina en el cuerpo?",
          DialogueId = 900400014,
          GUID = "900400014.0",
          NextDialogue = 90040401,
          Subtitle = "Are you alright with that much toxin in your body?"
        },
        [900400015] = {
          ContentES = "Siempre hay una fragancia agradable a tu alrededor.",
          DialogueId = 900400015,
          GUID = "900400015.0",
          NextDialogue = 90040501,
          Subtitle = "There's always a pleasant smell around you."
        },
        [900500011] = {
          ContentES = "Estás muy callada hoy... Pareces otra persona.",
          DialogueId = 900500011,
          GUID = "900500011.0",
          NextDialogue = 90050101,
          Subtitle = "You're so quiet today... It's like you're a completely different person."
        },
        [900500012] = {
          ContentES = "Los ladrones suelen estar muy alerta. ¿Cómo consigues robarles sus cosas justo delante de sus narices?",
          DialogueId = 900500012,
          GUID = "900500012.0",
          NextDialogue = 90050201,
          Subtitle = "Thieves are usually quite alert. How do you manage to swipe their stuff right under their noses?"
        },
        [900500013] = {
          ContentES = "¡A quien le gusta robar será una persona malvada!",
          DialogueId = 900500013,
          GUID = "900500013.0",
          NextDialogue = 90050301,
          Subtitle = "Those who like to steal are no good."
        },
        [900500014] = {
          ContentES = "Pensé que a la mayoría de los Charons no les gustaría que les llamaran “demonio”, ¿verdad?",
          DialogueId = 900500014,
          GUID = "900500014.0",
          NextDialogue = 90050401,
          Subtitle = "I thought most Charons wouldn't appreciate being called a \"demon\"..."
        },
        [900600011] = {
          ContentES = "Tu piel es roja como el fuego. ¡Qué único!",
          DialogueId = 900600011,
          GUID = "900600011.0",
          NextDialogue = 90060101,
          Subtitle = "Your skin is as red as fire. That's quite unique."
        },
        [900600012] = {
          ContentES = "¿Por qué decidiste convertirte en Acaidesa, Hellfire?",
          DialogueId = 900600012,
          GUID = "900600012.0",
          NextDialogue = 90060201,
          Subtitle = "Why did you choose to become a warden?"
        },
        [900600013] = {
          ContentES = "¿Es muy exigente el trabajo de Alcaidesa?",
          DialogueId = 900600013,
          GUID = "900600013.0",
          NextDialogue = 90060301,
          Subtitle = "Is being a warden a busy job?"
        },
        [900600014] = {
          ContentES = "¿Qué significa la justicia para ti?",
          DialogueId = 900600014,
          GUID = "900600014.0",
          NextDialogue = 90060401,
          Subtitle = "What does justice mean to you?"
        },
        [900600015] = {
          ContentES = "¿Qué haces en tu tiempo libre?",
          DialogueId = 900600015,
          GUID = "900600015.0",
          NextDialogue = 90060501,
          Subtitle = "What do you do in your spare time?"
        },
        [900700011] = {
          ContentES = "Dijiste que vienes de Huaxu. ¿Cómo es ese lugar?",
          DialogueId = 900700011,
          GUID = "900700011.0",
          NextDialogue = 90070101,
          Subtitle = "You said you're from Huaxu. What is the place like?"
        },
        [900700012] = {
          ContentES = "Te defines como un sirviente de los «Nueve Capítulos de Dafeng». ¿Qué significan esos?",
          DialogueId = 900700012,
          GUID = "900700012.0",
          NextDialogue = 90070201,
          Subtitle = "You call yourself a servant guarding the Nine Chapters of Dafeng. What does that mean?"
        },
        [900700013] = {
          ContentES = "Siempre pareces tan sombrío. ¿Ha pasado algo últimamente?",
          DialogueId = 900700013,
          GUID = "900700013.0",
          NextDialogue = 90070301,
          Subtitle = "You always seem so sombre. Has something happened recently?"
        },
        [900700014] = {
          ContentES = "He notado que contemplas a menudo la luna por la noche.",
          DialogueId = 900700014,
          GUID = "900700014.0",
          NextDialogue = 90070401,
          Subtitle = "I notice you often gaze at the moon at night."
        },
        [900800011] = {
          ContentES = "¿Siempre has sido tan perezoso? ¿Tu familia no te dice nada al respecto?",
          DialogueId = 900800011,
          GUID = "900800011.0",
          NextDialogue = 90080101,
          Subtitle = "Have you always been this idle? Doesn't your family say anything about this?"
        },
        [900800012] = {
          ContentES = "¿Por qué te duermes en cualquier sitio?",
          DialogueId = 900800012,
          GUID = "900800012.0",
          NextDialogue = 90080201,
          Subtitle = "How come you nap just about anywhere?"
        },
        [900800013] = {
          ContentES = "¿Qué tal es trabajar con la Jefa Sibylle?",
          DialogueId = 900800013,
          GUID = "900800013.0",
          NextDialogue = 90080301,
          Subtitle = "What's it like working under Chief Sibylle?"
        },
        [900800014] = {
          ContentES = "¿Con qué estás trasteando?",
          DialogueId = 900800014,
          GUID = "900800014.0",
          NextDialogue = 90080401,
          Subtitle = "What are you fiddling with?"
        },
        [900900011] = {
          ContentES = "¿Qué es exactamente la 13.ª Legión?",
          DialogueId = 900900011,
          GUID = "900900011.0",
          NextDialogue = 90090101,
          Subtitle = "What exactly is the 13th Legion?"
        },
        [900900012] = {
          ContentES = "Como una persona de Charon, ¿por qué sigues sirviendo al Imperio?",
          DialogueId = 900900012,
          GUID = "900900012.0",
          NextDialogue = 90090201,
          Subtitle = "As a Charon, why would you still serve the Empire?"
        },
        [900900013] = {
          ContentES = "¿Alguna vez has pensado en cómo te sentirías si alguien te quitara la familia como tú has hecho con la de otros?",
          DialogueId = 900900013,
          GUID = "900900013.0",
          NextDialogue = 90090301,
          Subtitle = "Have you ever thought about how you'd feel if someone took your family the way you've taken others'?"
        },
        [900900014] = {
          ContentES = "Dado el desprecio del Imperio hacia los Charons, imagino que tampoco te ven con buenos ojos.",
          DialogueId = 900900014,
          GUID = "900900014.0",
          NextDialogue = 90090401,
          Subtitle = "Given the Empire's disdain for Charons, I imagine they don't look kindly on you either."
        },
        [901000011] = {
          ContentES = "Ese vestido es tan precioso, pero, ¿no te preocupa coger frío?",
          DialogueId = 901000011,
          GUID = "901000011.0",
          NextDialogue = 90100101,
          Subtitle = "That's really a lovely dress, but are you not worried about catching a cold?"
