        [901000012] = {
          ContentES = "Recuerdo que me mencionaste que en Hyperborea la gente no ve con buenos ojos a los Charons.",
          DialogueId = 901000012,
          GUID = "901000012.0",
          NextDialogue = 90100201,
          Subtitle = "I remember you mentioned that people don't look kindly on Charons in Hyperborea."
        },
        [901000013] = {
          ContentES = "Últimamente huele a las flores por aquí.",
          DialogueId = 901000013,
          GUID = "901000013.0",
          NextDialogue = 90100301,
          Subtitle = "There's a flowery smell around here lately."
        },
        [901000014] = {
          ContentES = "¿Alguna vez has dejado el Lago Helado, Psyche?",
          DialogueId = 901000014,
          GUID = "901000014.0",
          NextDialogue = 90100401,
          Subtitle = "Have you ever left Icelake, Psyche?"
