        [901100013] = {
          ContentES = "¿Cómo es el Pabellón de lo Efímero?",
          DialogueId = 901100013,
          GUID = "901100013.0",
          NextDialogue = 90110301,
          Subtitle = "What's the Hall of Ephemerality like?"
