          GUID = "901100014.0",
          NextDialogue = 90110401,
          Subtitle = "As a healer, you must possess a particularly profound understanding of death, don't you?"
        },
        [901200011] = {
          ContentES = "Escuché que eres la Comisaria. ¿De qué se trata eso exactamente?",
          DialogueId = 901200011,
          GUID = "901200011.0",
          NextDialogue = 90120101,
          Subtitle = "I heard you're a commissary. What's that all about?"
