        [901200012] = {
          ContentES = "Tengo una pregunta, ¿duele si Filbert te choca?",
          DialogueId = 901200012,
          GUID = "901200012.0",
          NextDialogue = 90120201,
          Subtitle = "Just wondering — does it hurt to get bumped by Filbert?"
