        [901300011] = {
          ContentES = "¿Puedes decirme algo sobre Sibylle?",
          DialogueId = 901300011,
          GUID = "901300011.0",
          NextDialogue = 90130101,
          Subtitle = "Can you tell me something about Sibylle?"
        },
        [901300012] = {
          ContentES = "Escuché que tuviste bastantes trabajos antes de unirte a la Legión. ¿Tienes algún consejo profesional?",
          DialogueId = 901300012,
          GUID = "901300012.0",
          NextDialogue = 90130201,
          Subtitle = "Heard you pulled quite a few gigs before joining the Legion. Got any pro tips?"
