        [901300013] = {
          ContentES = "Pareces perdido en tus pensamientos, ¿en qué estás pensando?",
          DialogueId = 901300013,
          GUID = "901300013.0",
          NextDialogue = 90130301,
          Subtitle = "You seem to be lost in thought; what's on your mind?"
