        [901300014] = {
          ContentES = "¿Por qué te esfuerzas tanto en el trabajo?",
          DialogueId = 901300014,
          GUID = "901300014.0",
          NextDialogue = 90130401,
          Subtitle = "Why do you always push yourself so hard at work?"
