        [901500011] = {
          ContentES = "¿En qué piensas?",
          DialogueId = 901500011,
          GUID = "901500011.0",
          NextDialogue = 90150101,
          Subtitle = "A coin for your thoughts."
        },
        [901500012] = {
          ContentES = "¿Tienes algún pequeño secreto que quieras compartir conmigo, Fina?",
          DialogueId = 901500012,
          GUID = "901500012.0",
          NextDialogue = 90150201,
          Subtitle = "Got any little secrets you'd like to share with me, Fina?"
