        [901500013] = {
          ContentES = "¿Has dormido bien anoche?",
          DialogueId = 901500013,
          GUID = "901500013.0",
          NextDialogue = 90150301,
          Subtitle = "Did you have a good night's sleep?"
        },
        [901500014] = {
          ContentES = "Fina, ¿tienes algún otro familiar además de tu hermano?",
          DialogueId = 901500014,
          GUID = "901500014.0",
          NextDialogue = 90150401,
          Subtitle = "Fina, do you have any family other than your brother?"
        },
        [901500015] = {
          ContentES = "¿Cómo es Outsider?",
          DialogueId = 901500015,
          GUID = "901500015.0",
          NextDialogue = 90150501,
          Subtitle = "What's Outsider like?"
        },
        [901600011] = {
          ContentES = "¿Tienes alguna guía rápida para convertirse en un Phoxcazador experimentado?",
          DialogueId = 901600011,
          GUID = "901600011.0",
          NextDialogue = 90160101,
          Subtitle = "Do you have something like a quickstart guide to becoming a seasoned Phoxhunter to share?"
        },
        [901600012] = {
          ContentES = "¿Por qué el Imperio le da tanta importancia a la “Alianza de los Abandonados”? ¿Quiénes son?",
          DialogueId = 901600012,
          GUID = "901600012.0",
          NextDialogue = 90160201,
          Subtitle = "Why is the Empire making such a big deal about \"The Forsakens\"? What are they?"
        },
        [901600013] = {
          ContentES = "¿Te has hecho daño?",
          DialogueId = 901600013,
          GUID = "901600013.0",
          NextDialogue = 90160301,
          Subtitle = "Did you get hurt?"
        },
        [901600014] = {
          ContentES = "¿Qué es eso que tienes en la mano?",
          DialogueId = 901600014,
          GUID = "901600014.0",
          NextDialogue = 90160401,
          Subtitle = "What is that thing in your hand?!"
        },
        [901600015] = {
          ContentES = "Uf, ¡la misión se finalizó con éxito!",
          DialogueId = 901600015,
          GUID = "901600015.0",
          NextDialogue = 90160501,
          Subtitle = "Phew, request successfully completed."
        },
        [901700011] = {
          ContentES = "¿Qué hacen una “recicladora”?",
          DialogueId = 901700011,
          GUID = "901700011.0",
          NextDialogue = 90170101,
          Subtitle = "What do scavengers do?"
        },
        [901700012] = {
          ContentES = "¿«Guía completa del mapa de basureros del Lago Helado»...?",
          DialogueId = 901700012,
          GUID = "901700012.0",
          NextDialogue = 90170201,
          Subtitle = "\"The One-Stop Rubbish Bin Map Guide of Icelake\"...?"
        },
        [901700013] = {
          ContentES = "A veces te veo mirando los campos de nieve de lejos. ¿Quieres irte de aquí?",
          DialogueId = 901700013,
          GUID = "901700013.0",
          NextDialogue = 90170301,
          Subtitle = "I sometimes see you gazing at the distant snowfields. Do you wish to leave here?"
        },
        [901700014] = {
          ContentES = "¿Qué animal está en tu amuleto?",
          DialogueId = 901700014,
          GUID = "901700014.0",
          NextDialogue = 90170401,
          Subtitle = "What animal is on your charm?"
        },
        [901700015] = {
          ContentES = "Sabes, la gente de los barrios pobres te llama “Princesa del Basurero”.",
          DialogueId = 901700015,
          GUID = "901700015.0",
          NextDialogue = 90170501,
          Subtitle = "You know, people in the slums call you \"Princess Rubbish Bin\"."
        },
        [901800011] = {
          ContentES = "¿Es una bomba que habla?",
          DialogueId = 901800011,
          GUID = "901800011.0",
          NextDialogue = 90180101,
          Subtitle = "Is that a talking bomb?"
        },
        [901800012] = {
          ContentES = "¿Te interesan las comisiones del Phoxcazador? ¿Quieres acompañarme?",
          DialogueId = 901800012,
          GUID = "901800012.0",
          NextDialogue = 90180201,
          Subtitle = "Are you interested in Phoxhunter commissions? Care to join me?"
        },
        [901800013] = {
          ContentES = "Pareces hablar siempre muy despacio.",
          DialogueId = 901800013,
          GUID = "901800013.0",
          NextDialogue = 90180301,
          Subtitle = "You seem to always speak very slowly."
        },
        [901800014] = {
          ContentES = "¿Tú y Oliver eran amigos desde la infancia?",
          DialogueId = 901800014,
          GUID = "901800014.0",
          NextDialogue = 90180401,
          Subtitle = "Were you and Oliver childhood friends?"
        },
        [901900011] = {
          ContentES = "Y a ti, ¿qué te gusta hacer en tu tiempo libre fuera del campo de batalla?",
          DialogueId = 901900011,
          GUID = "901900011.0",
          NextDialogue = 90190101,
          Subtitle = "What do you like to do in your downtime away from the battlefield?"
        },
        [901900012] = {
          ContentES = "¿Podrías hablarme un poco sobre la alquimia?",
          DialogueId = 901900012,
          GUID = "901900012.0",
          NextDialogue = 90190201,
          Subtitle = "Could you tell me about alchemy?"
        },
        [901900013] = {
          ContentES = "He notado que siempre llevas esa mochila. ¿Qué guardas dentro?",
          DialogueId = 901900013,
          GUID = "901900013.0",
          NextDialogue = 90190301,
          Subtitle = "I've noticed you always carry that backpack. What do you keep inside?"
        },
        [901900014] = {
          ContentES = "Entrenar como paramédica debe ser duro, ¿verdad?",
          DialogueId = 901900014,
          GUID = "901900014.0",
          NextDialogue = 90190401,
          Subtitle = "Training as a medic must be tough, isn't it?"
        },
        [901900015] = {
          ContentES = "A veces te veo mirando fijamente tu radio.",
          DialogueId = 901900015,
          GUID = "901900015.0",
          NextDialogue = 90190501,
          Subtitle = "Sometimes I see you staring at your radio.",
          TriggerCondition = {
            QuestChainFinish = {QuestChainId = 110109}
          }
        },
